BEGIN TRANSACTION;

-- alter this code if you want to add the same version from different sources
DECLARE @BibleCode varchar(16) = 'NET'

EXEC add_Version @code='NET', @name='New English Translation', @lang='eng', @year=2001, @hebrew='MAS', @greek='AX', @license=6, @level=7.00

EXEC add_Revision @code='NET2001', @version='NET', @year=2001, @sub='Beta 1'
EXEC add_Revision @code='NET2003', @version='NET', @year=2003, @sub='Beta 2'
EXEC add_Revision @code='NET2005', @version='NET', @year=2005, @sub='Edition 1'
EXEC add_Revision @code='NET2017', @version='NET', @year=2017, @sub='Edition 2'
EXEC add_Revision @code='NET2019', @version='NET', @year=2019

EXEC add_Resource @version='NET', @type='license', @url='https://netbible.com/copyright/', @official=1, @siteName='New English Translation', @siteUrl='https://netbible.com/'
EXEC add_Resource @version='NET', @type='version', @url='https://netbible.com/', @official=1, @siteName='New English Translation', @siteUrl='https://netbible.com/'
EXEC add_Resource @version='NET', @type='read', @url='https://netbible.org/', @official=1, @siteName='NETBible.org', @siteUrl='https://netbible.org/'
EXEC add_Resource @version='NET', @type='file', @url='https://bible.org/downloads', @official=1
EXEC add_Resource @version='NET', @type='file', @url='https://bible.org/downloads', @official=0, @siteName='eBible.org', @siteUrl='https://ebible.org/'

EXEC add_Bible @code=@BibleCode, @name='New English Translation', @version='NET', @revision='NET2005', @year=2005, @sub='Edition 1', @sourceUrl='https://ebible.org/find/show.php?id=engnet'

EXEC add_VersionNote @version='NET', @bible=@BibleCode, @label='copyright', @note=N'The Scriptures quoted are from the NET Bible® https://netbible.com copyright ©1996, 2019 used with permission from Biblical Studies Press, L.L.C. All rights reserved'

DECLARE @BibleId int = (SELECT [Id] FROM [Bibles] WHERE [Code] = @BibleCode)

EXEC add_BibleVerse @BibleId, 101001001, N' In the beginning God created the heavens and the earth.'
EXEC add_BibleVerse @BibleId, 101001002, N'Now the earth was without shape and empty, and darkness was over the surface of the watery deep, but the Spirit of God was moving over the surface of the water.'
EXEC add_BibleVerse @BibleId, 101001003, N'God said, “Let there be light.” And there was light!'
EXEC add_BibleVerse @BibleId, 101001004, N'God saw that the light was good, so God separated the light from the darkness.'
EXEC add_BibleVerse @BibleId, 101001005, N'God called the light “day” and the darkness “night.” There was evening, and there was morning, marking the first day.'
EXEC add_BibleVerse @BibleId, 101001006, N'God said, “Let there be an expanse in the midst of the waters and let it separate water from water.'
EXEC add_BibleVerse @BibleId, 101001007, N'So God made the expanse and separated the water under the expanse from the water above it. It was so.'
EXEC add_BibleVerse @BibleId, 101001008, N'God called the expanse “sky.” There was evening, and there was morning, a second day.'
EXEC add_BibleVerse @BibleId, 101001009, N'God said, “Let the water under the sky be gathered to one place and let dry ground appear.” It was so.'
EXEC add_BibleVerse @BibleId, 101001010, N'God called the dry ground “land” and the gathered waters he called “seas.” God saw that it was good.'
EXEC add_BibleVerse @BibleId, 101001011, N'God said, “Let the land produce vegetation: plants yielding seeds according to their kinds, and trees bearing fruit with seed in it according to their kinds.” It was so.'
EXEC add_BibleVerse @BibleId, 101001012, N'The land produced vegetation – plants yielding seeds according to their kinds, and trees bearing fruit with seed in it according to their kinds. God saw that it was good.'
EXEC add_BibleVerse @BibleId, 101001013, N'There was evening, and there was morning, a third day.'
EXEC add_BibleVerse @BibleId, 101001014, N'God said, “Let there be lights in the expanse of the sky to separate the day from the night, and let them be signs to indicate seasons and days and years,'
EXEC add_BibleVerse @BibleId, 101001015, N'and let them serve as lights in the expanse of the sky to give light on the earth.” It was so.'
EXEC add_BibleVerse @BibleId, 101001016, N'God made two great lights – the greater light to rule over the day and the lesser light to rule over the night. He made the stars also.'
EXEC add_BibleVerse @BibleId, 101001017, N'God placed the lights in the expanse of the sky to shine on the earth,'
EXEC add_BibleVerse @BibleId, 101001018, N'to preside over the day and the night, and to separate the light from the darkness. God saw that it was good.'
EXEC add_BibleVerse @BibleId, 101001019, N'There was evening, and there was morning, a fourth day.'
EXEC add_BibleVerse @BibleId, 101001020, N'God said, “Let the water swarm with swarms of living creatures and let birds fly above the earth across the expanse of the sky.”'
EXEC add_BibleVerse @BibleId, 101001021, N'God created the great sea creatures and every living and moving thing with which the water swarmed, according to their kinds, and every winged bird according to its kind. God saw that it was good.'
EXEC add_BibleVerse @BibleId, 101001022, N'God blessed them and said, “Be fruitful and multiply and fill the water in the seas, and let the birds multiply on the earth.”'
EXEC add_BibleVerse @BibleId, 101001023, N'There was evening, and there was morning, a fifth day.'
EXEC add_BibleVerse @BibleId, 101001024, N'God said, “Let the land produce living creatures according to their kinds: cattle, creeping things, and wild animals, each according to its kind.” It was so.'
EXEC add_BibleVerse @BibleId, 101001025, N'God made the wild animals according to their kinds, the cattle according to their kinds, and all the creatures that creep along the ground according to their kinds. God saw that it was good.'
EXEC add_BibleVerse @BibleId, 101001026, N'Then God said, “Let us make humankind in our image, after our likeness, so they may rule over the fish of the sea and the birds of the air, over the cattle, and over all the earth, and over all the creatures that move on the earth.”'
EXEC add_BibleVerse @BibleId, 101001027, N'God created humankind in his own image, in the image of God he created them, male and female he created them.'
EXEC add_BibleVerse @BibleId, 101001028, N'God blessed them and said to them, “Be fruitful and multiply! Fill the earth and subdue it! Rule over the fish of the sea and the birds of the air and every creature that moves on the ground.”'
EXEC add_BibleVerse @BibleId, 101001029, N'Then God said, “I now give you every seed-bearing plant on the face of the entire earth and every tree that has fruit with seed in it. They will be yours for food.'
EXEC add_BibleVerse @BibleId, 101001030, N'And to all the animals of the earth, and to every bird of the air, and to all the creatures that move on the ground – everything that has the breath of life in it – I give every green plant for food.” It was so.'
EXEC add_BibleVerse @BibleId, 101001031, N'God saw all that he had made – and it was very good! There was evening, and there was morning, the sixth day.'
EXEC add_BibleVerse @BibleId, 101002001, N'The heavens and the earth were completed with everything that was in them.'
EXEC add_BibleVerse @BibleId, 101002002, N'By the seventh day God finished the work that he had been doing, and he ceased on the seventh day all the work that he had been doing.'
EXEC add_BibleVerse @BibleId, 101002003, N'God blessed the seventh day and made it holy because on it he ceased all the work that he had been doing in creation.'
EXEC add_BibleVerse @BibleId, 101002004, N'This is the account of the heavens and the earth when they were created – when the Lord God made the earth and heavens.'
EXEC add_BibleVerse @BibleId, 101002005, N'Now no shrub of the field had yet grown on the earth, and no plant of the field had yet sprouted, for the Lord God had not caused it to rain on the earth, and there was no man to cultivate the ground.'
EXEC add_BibleVerse @BibleId, 101002006, N'Springs would well up from the earth and water the whole surface of the ground.'
EXEC add_BibleVerse @BibleId, 101002007, N'The Lord God formed the man from the soil of the ground and breathed into his nostrils the breath of life, and the man became a living being.'
EXEC add_BibleVerse @BibleId, 101002008, N'The Lord God planted an orchard in the east, in Eden; and there he placed the man he had formed.'
EXEC add_BibleVerse @BibleId, 101002009, N'The Lord God made all kinds of trees grow from the soil, every tree that was pleasing to look at and good for food. (Now the tree of life and the tree of the knowledge of good and evil were in the middle of the orchard.)'
EXEC add_BibleVerse @BibleId, 101002010, N'Now a river flows from Eden to water the orchard, and from there it divides into four headstreams.'
EXEC add_BibleVerse @BibleId, 101002011, N'The name of the first is Pishon; it runs through the entire land of Havilah, where there is gold.'
EXEC add_BibleVerse @BibleId, 101002012, N'(The gold of that land is pure; pearls and lapis lazuli are also there).'
EXEC add_BibleVerse @BibleId, 101002013, N'The name of the second river is Gihon; it runs through the entire land of Cush.'
EXEC add_BibleVerse @BibleId, 101002014, N'The name of the third river is Tigris; it runs along the east side of Assyria. The fourth river is the Euphrates.'
EXEC add_BibleVerse @BibleId, 101002015, N'The Lord God took the man and placed him in the orchard in Eden to care for it and to maintain it.'
EXEC add_BibleVerse @BibleId, 101002016, N'Then the Lord God commanded the man, “You may freely eat fruit from every tree of the orchard,'
EXEC add_BibleVerse @BibleId, 101002017, N'but you must not eat from the tree of the knowledge of good and evil, for when you eat from it you will surely die.”'
EXEC add_BibleVerse @BibleId, 101002018, N'The Lord God said, “It is not good for the man to be alone. I will make a companion for him who corresponds to him.”'
EXEC add_BibleVerse @BibleId, 101002019, N'The Lord God formed out of the ground every living animal of the field and every bird of the air. He brought them to the man to see what he would name them, and whatever the man called each living creature, that was its name.'
EXEC add_BibleVerse @BibleId, 101002020, N'So the man named all the animals, the birds of the air, and the living creatures of the field, but for Adam no companion who corresponded to him was found.'
EXEC add_BibleVerse @BibleId, 101002021, N'So the Lord God caused the man to fall into a deep sleep, and while he was asleep, he took part of the man’s side and closed up the place with flesh.'
EXEC add_BibleVerse @BibleId, 101002022, N'Then the Lord God made a woman from the part he had taken out of the man, and he brought her to the man.'
EXEC add_BibleVerse @BibleId, 101002023, N'Then the man said, “This one at last is bone of my bones and flesh of my flesh; this one will be called ‘woman,’ for she was taken out of man.”'
EXEC add_BibleVerse @BibleId, 101002024, N'That is why a man leaves his father and mother and unites with his wife, and they become a new family.'
EXEC add_BibleVerse @BibleId, 101002025, N'The man and his wife were both naked, but they were not ashamed.'
EXEC add_BibleVerse @BibleId, 101003001, N'Now the serpent was more shrewd than any of the wild animals that the Lord God had made. He said to the woman, “Is it really true that God said, ‘You must not eat from any tree of the orchard’?”'
EXEC add_BibleVerse @BibleId, 101003002, N'The woman said to the serpent, “We may eat of the fruit from the trees of the orchard;'
EXEC add_BibleVerse @BibleId, 101003003, N'but concerning the fruit of the tree that is in the middle of the orchard God said, ‘You must not eat from it, and you must not touch it, or else you will die.’”'
EXEC add_BibleVerse @BibleId, 101003004, N'The serpent said to the woman, “Surely you will not die,'
EXEC add_BibleVerse @BibleId, 101003005, N'for God knows that when you eat from it your eyes will open and you will be like divine beings who know good and evil.”'
EXEC add_BibleVerse @BibleId, 101003006, N'When the woman saw that the tree produced fruit that was good for food, was attractive to the eye, and was desirable for making one wise, she took some of its fruit and ate it. She also gave some of it to her husband who was with her, and he ate it.'
EXEC add_BibleVerse @BibleId, 101003007, N'Then the eyes of both of them opened, and they knew they were naked; so they sewed fig leaves together and made coverings for themselves.'
EXEC add_BibleVerse @BibleId, 101003008, N'Then the man and his wife heard the sound of the Lord God moving about in the orchard at the breezy time of the day, and they hid from the Lord God among the trees of the orchard.'
EXEC add_BibleVerse @BibleId, 101003009, N'But the Lord God called to the man and said to him, “Where are you?”'
EXEC add_BibleVerse @BibleId, 101003010, N'The man replied, “I heard you moving about in the orchard, and I was afraid because I was naked, so I hid.”'
EXEC add_BibleVerse @BibleId, 101003011, N'And the Lord God said, “Who told you that you were naked? Did you eat from the tree that I commanded you not to eat from?”'
EXEC add_BibleVerse @BibleId, 101003012, N'The man said, “The woman whom you gave me, she gave me some fruit from the tree and I ate it.”'
EXEC add_BibleVerse @BibleId, 101003013, N'So the Lord God said to the woman, “What is this you have done?” And the woman replied, “The serpent tricked me, and I ate.”'
EXEC add_BibleVerse @BibleId, 101003014, N'The Lord God said to the serpent, “Because you have done this, cursed are you above all the wild beasts and all the living creatures of the field! On your belly you will crawl and dust you will eat all the days of your life.'
EXEC add_BibleVerse @BibleId, 101003015, N'And I will put hostility between you and the woman and between your offspring and her offspring; her offspring will attack your head, and you will attack her offspring’s heel.”'
EXEC add_BibleVerse @BibleId, 101003016, N'To the woman he said, “I will greatly increase your labor pains; with pain you will give birth to children. You will want to control your husband, but he will dominate you.”'
EXEC add_BibleVerse @BibleId, 101003017, N'But to Adam he said, “Because you obeyed your wife and ate from the tree about which I commanded you, ‘You must not eat from it,’ cursed is the ground thanks to you; in painful toil you will eat of it all the days of your life.'
EXEC add_BibleVerse @BibleId, 101003018, N'It will produce thorns and thistles for you, but you will eat the grain of the field.'
EXEC add_BibleVerse @BibleId, 101003019, N'By the sweat of your brow you will eat food until you return to the ground, for out of it you were taken; for you are dust, and to dust you will return.”'
EXEC add_BibleVerse @BibleId, 101003020, N'The man named his wife Eve, because she was the mother of all the living.'
EXEC add_BibleVerse @BibleId, 101003021, N'The Lord God made garments from skin for Adam and his wife, and clothed them.'
EXEC add_BibleVerse @BibleId, 101003022, N'And the Lord God said, “Now that the man has become like one of us, knowing good and evil, he must not be allowed to stretch out his hand and take also from the tree of life and eat, and live forever.”'
EXEC add_BibleVerse @BibleId, 101003023, N'So the Lord God expelled him from the orchard in Eden to cultivate the ground from which he had been taken.'
EXEC add_BibleVerse @BibleId, 101003024, N'When he drove the man out, he placed on the eastern side of the orchard in Eden angelic sentries who used the flame of a whirling sword to guard the way to the tree of life.'
EXEC add_BibleVerse @BibleId, 101004001, N'Now the man had marital relations with his wife Eve, and she became pregnant and gave birth to Cain. Then she said, “I have created a man just as the Lord did!”'
EXEC add_BibleVerse @BibleId, 101004002, N'Then she gave birth to his brother Abel. Abel took care of the flocks, while Cain cultivated the ground.'
EXEC add_BibleVerse @BibleId, 101004003, N'At the designated time Cain brought some of the fruit of the ground for an offering to the Lord.'
EXEC add_BibleVerse @BibleId, 101004004, N'But Abel brought some of the firstborn of his flock – even the fattest of them. And the Lord was pleased with Abel and his offering,'
EXEC add_BibleVerse @BibleId, 101004005, N'but with Cain and his offering he was not pleased. So Cain became very angry, and his expression was downcast.'
EXEC add_BibleVerse @BibleId, 101004006, N'Then the Lord said to Cain, “Why are you angry, and why is your expression downcast?'
EXEC add_BibleVerse @BibleId, 101004007, N'Is it not true that if you do what is right, you will be fine? But if you do not do what is right, sin is crouching at the door. It desires to dominate you, but you must subdue it.”'
EXEC add_BibleVerse @BibleId, 101004008, N'Cain said to his brother Abel, “Let’s go out to the field.” While they were in the field, Cain attacked his brother Abel and killed him.'
EXEC add_BibleVerse @BibleId, 101004009, N'Then the Lord said to Cain, “Where is your brother Abel?” And he replied, “I don’t know! Am I my brother’s guardian?”'
EXEC add_BibleVerse @BibleId, 101004010, N'But the Lord said, “What have you done? The voice of your brother’s blood is crying out to me from the ground!'
EXEC add_BibleVerse @BibleId, 101004011, N'So now, you are banished from the ground, which has opened its mouth to receive your brother’s blood from your hand.'
EXEC add_BibleVerse @BibleId, 101004012, N'When you try to cultivate the ground it will no longer yield its best for you. You will be a homeless wanderer on the earth.”'
EXEC add_BibleVerse @BibleId, 101004013, N'Then Cain said to the Lord, “My punishment is too great to endure!'
EXEC add_BibleVerse @BibleId, 101004014, N'Look! You are driving me off the land today, and I must hide from your presence. I will be a homeless wanderer on the earth; whoever finds me will kill me.”'
EXEC add_BibleVerse @BibleId, 101004015, N'But the Lord said to him, “All right then, if anyone kills Cain, Cain will be avenged seven times as much.” Then the Lord put a special mark on Cain so that no one who found him would strike him down.'
EXEC add_BibleVerse @BibleId, 101004016, N'So Cain went out from the presence of the Lord and lived in the land of Nod, east of Eden.'
EXEC add_BibleVerse @BibleId, 101004017, N'Cain had marital relations with his wife, and she became pregnant and gave birth to Enoch. Cain was building a city, and he named the city after his son Enoch.'
EXEC add_BibleVerse @BibleId, 101004018, N'To Enoch was born Irad, and Irad was the father of Mehujael. Mehujael was the father of Methushael, and Methushael was the father of Lamech.'
EXEC add_BibleVerse @BibleId, 101004019, N'Lamech took two wives for himself; the name of the first was Adah, and the name of the second was Zillah.'
EXEC add_BibleVerse @BibleId, 101004020, N'Adah gave birth to Jabal; he was the first of those who live in tents and keep livestock.'
EXEC add_BibleVerse @BibleId, 101004021, N'The name of his brother was Jubal; he was the first of all who play the harp and the flute.'
EXEC add_BibleVerse @BibleId, 101004022, N'Now Zillah also gave birth to Tubal-Cain, who heated metal and shaped all kinds of tools made of bronze and iron. The sister of Tubal-Cain was Naamah.'
EXEC add_BibleVerse @BibleId, 101004023, N'Lamech said to his wives, “Adah and Zillah! Listen to me! You wives of Lamech, hear my words! I have killed a man for wounding me, a young man for hurting me.'
EXEC add_BibleVerse @BibleId, 101004024, N'If Cain is to be avenged seven times as much, then Lamech seventy-seven times!”'
EXEC add_BibleVerse @BibleId, 101004025, N'And Adam had marital relations with his wife again, and she gave birth to a son. She named him Seth, saying, “God has given me another child in place of Abel because Cain killed him.”'
EXEC add_BibleVerse @BibleId, 101004026, N'And a son was also born to Seth, whom he named Enosh. At that time people began to worship the Lord.'
EXEC add_BibleVerse @BibleId, 101005001, N'This is the record of the family line of Adam. When God created humankind, he made them in the likeness of God.'
EXEC add_BibleVerse @BibleId, 101005002, N'He created them male and female; when they were created, he blessed them and named them “humankind.”'
EXEC add_BibleVerse @BibleId, 101005003, N'When Adam had lived 130 years he fathered a son in his own likeness, according to his image, and he named him Seth.'
EXEC add_BibleVerse @BibleId, 101005004, N'The length of time Adam lived after he became the father of Seth was 800 years; during this time he had other sons and daughters.'
EXEC add_BibleVerse @BibleId, 101005005, N'The entire lifetime of Adam was 930 years, and then he died.'
EXEC add_BibleVerse @BibleId, 101005006, N'When Seth had lived 105 years, he became the father of Enosh.'
EXEC add_BibleVerse @BibleId, 101005007, N'Seth lived 807 years after he became the father of Enosh, and he had other sons and daughters.'
EXEC add_BibleVerse @BibleId, 101005008, N'The entire lifetime of Seth was 912 years, and then he died.'
EXEC add_BibleVerse @BibleId, 101005009, N'When Enosh had lived 90 years, he became the father of Kenan.'
EXEC add_BibleVerse @BibleId, 101005010, N'Enosh lived 815 years after he became the father of Kenan, and he had other sons and daughters.'
EXEC add_BibleVerse @BibleId, 101005011, N'The entire lifetime of Enosh was 905 years, and then he died.'
EXEC add_BibleVerse @BibleId, 101005012, N'When Kenan had lived 70 years, he became the father of Mahalalel.'
EXEC add_BibleVerse @BibleId, 101005013, N'Kenan lived 840 years after he became the father of Mahalalel, and he had other sons and daughters.'
EXEC add_BibleVerse @BibleId, 101005014, N'The entire lifetime of Kenan was 910 years, and then he died.'
EXEC add_BibleVerse @BibleId, 101005015, N'When Mahalalel had lived 65 years, he became the father of Jared.'
EXEC add_BibleVerse @BibleId, 101005016, N'Mahalalel lived 830 years after he became the father of Jared, and he had other sons and daughters.'
EXEC add_BibleVerse @BibleId, 101005017, N'The entire lifetime of Mahalalel was 895 years, and then he died.'
EXEC add_BibleVerse @BibleId, 101005018, N'When Jared had lived 162 years, he became the father of Enoch.'
EXEC add_BibleVerse @BibleId, 101005019, N'Jared lived 800 years after he became the father of Enoch, and he had other sons and daughters.'
EXEC add_BibleVerse @BibleId, 101005020, N'The entire lifetime of Jared was 962 years, and then he died.'
EXEC add_BibleVerse @BibleId, 101005021, N'When Enoch had lived 65 years, he became the father of Methuselah.'
EXEC add_BibleVerse @BibleId, 101005022, N'After he became the father of Methuselah, Enoch walked with God for 300 years, and he had other sons and daughters.'
EXEC add_BibleVerse @BibleId, 101005023, N'The entire lifetime of Enoch was 365 years.'
EXEC add_BibleVerse @BibleId, 101005024, N'Enoch walked with God, and then he disappeared because God took him away.'
EXEC add_BibleVerse @BibleId, 101005025, N'When Methuselah had lived 187 years, he became the father of Lamech.'
EXEC add_BibleVerse @BibleId, 101005026, N'Methuselah lived 782 years after he became the father of Lamech, and he had other sons and daughters.'
EXEC add_BibleVerse @BibleId, 101005027, N'The entire lifetime of Methuselah was 969 years, and then he died.'
EXEC add_BibleVerse @BibleId, 101005028, N'When Lamech had lived 182 years, he had a son.'
EXEC add_BibleVerse @BibleId, 101005029, N'He named him Noah, saying, “This one will bring us comfort from our labor and from the painful toil of our hands because of the ground that the Lord has cursed.”'
EXEC add_BibleVerse @BibleId, 101005030, N'Lamech lived 595 years after he became the father of Noah, and he had other sons and daughters.'
EXEC add_BibleVerse @BibleId, 101005031, N'The entire lifetime of Lamech was 777 years, and then he died.'
EXEC add_BibleVerse @BibleId, 101005032, N'After Noah was 500 years old, he became the father of Shem, Ham, and Japheth.'
EXEC add_BibleVerse @BibleId, 101006001, N'When humankind began to multiply on the face of the earth, and daughters were born to them,'
EXEC add_BibleVerse @BibleId, 101006002, N'the sons of God saw that the daughters of humankind were beautiful. Thus they took wives for themselves from any they chose.'
EXEC add_BibleVerse @BibleId, 101006003, N'So the Lord said, “My spirit will not remain in humankind indefinitely, since they are mortal. They will remain for 120 more years.”'
EXEC add_BibleVerse @BibleId, 101006004, N'The Nephilim were on the earth in those days (and also after this) when the sons of God were having sexual relations with the daughters of humankind, who gave birth to their children. They were the mighty heroes of old, the famous men.'
EXEC add_BibleVerse @BibleId, 101006005, N'But the Lord saw that the wickedness of humankind had become great on the earth. Every inclination of the thoughts of their minds was only evil all the time.'
EXEC add_BibleVerse @BibleId, 101006006, N'The Lord regretted that he had made humankind on the earth, and he was highly offended.'
EXEC add_BibleVerse @BibleId, 101006007, N'So the Lord said, “I will wipe humankind, whom I have created, from the face of the earth – everything from humankind to animals, including creatures that move on the ground and birds of the air, for I regret that I have made them.”'
EXEC add_BibleVerse @BibleId, 101006008, N'But Noah found favor in the sight of the Lord.'
EXEC add_BibleVerse @BibleId, 101006009, N'This is the account of Noah. Noah was a godly man; he was blameless among his contemporaries. He walked with God.'
EXEC add_BibleVerse @BibleId, 101006010, N'Noah had three sons: Shem, Ham, and Japheth.'
EXEC add_BibleVerse @BibleId, 101006011, N'The earth was ruined in the sight of God; the earth was filled with violence.'
EXEC add_BibleVerse @BibleId, 101006012, N'God saw the earth, and indeed it was ruined, for all living creatures on the earth were sinful.'
EXEC add_BibleVerse @BibleId, 101006013, N'So God said to Noah, “I have decided that all living creatures must die, for the earth is filled with violence because of them. Now I am about to destroy them and the earth.'
EXEC add_BibleVerse @BibleId, 101006014, N'Make for yourself an ark of cypress wood. Make rooms in the ark, and cover it with pitch inside and out.'
EXEC add_BibleVerse @BibleId, 101006015, N'This is how you should make it: The ark is to be 450 feet long, 75 feet wide, and 45 feet high.'
EXEC add_BibleVerse @BibleId, 101006016, N'Make a roof for the ark and finish it, leaving 18 inches from the top. Put a door in the side of the ark, and make lower, middle, and upper decks.'
EXEC add_BibleVerse @BibleId, 101006017, N'I am about to bring floodwaters on the earth to destroy from under the sky all the living creatures that have the breath of life in them. Everything that is on the earth will die,'
EXEC add_BibleVerse @BibleId, 101006018, N'but I will confirm my covenant with you. You will enter the ark – you, your sons, your wife, and your sons’ wives with you.'
EXEC add_BibleVerse @BibleId, 101006019, N'You must bring into the ark two of every kind of living creature from all flesh, male and female, to keep them alive with you.'
EXEC add_BibleVerse @BibleId, 101006020, N'Of the birds after their kinds, and of the cattle after their kinds, and of every creeping thing of the ground after its kind, two of every kind will come to you so you can keep them alive.'
EXEC add_BibleVerse @BibleId, 101006021, N'And you must take for yourself every kind of food that is eaten, and gather it together. It will be food for you and for them.'
EXEC add_BibleVerse @BibleId, 101006022, N'And Noah did all that God commanded him – he did indeed.'
EXEC add_BibleVerse @BibleId, 101007001, N'The Lord said to Noah, “Come into the ark, you and all your household, for I consider you godly among this generation.'
EXEC add_BibleVerse @BibleId, 101007002, N'You must take with you seven of every kind of clean animal, the male and its mate, two of every kind of unclean animal, the male and its mate,'
EXEC add_BibleVerse @BibleId, 101007003, N'and also seven of every kind of bird in the sky, male and female, to preserve their offspring on the face of the earth.'
EXEC add_BibleVerse @BibleId, 101007004, N'For in seven days I will cause it to rain on the earth for forty days and forty nights, and I will wipe from the face of the ground every living thing that I have made.”'
EXEC add_BibleVerse @BibleId, 101007005, N'And Noah did all that the Lord commanded him.'
EXEC add_BibleVerse @BibleId, 101007006, N'Noah was 600 years old when the floodwaters engulfed the earth.'
EXEC add_BibleVerse @BibleId, 101007007, N'Noah entered the ark along with his sons, his wife, and his sons’ wives because of the floodwaters.'
EXEC add_BibleVerse @BibleId, 101007008, N'Pairs of clean animals, of unclean animals, of birds, and of everything that creeps along the ground,'
EXEC add_BibleVerse @BibleId, 101007009, N'male and female, came into the ark to Noah, just as God had commanded him.'
EXEC add_BibleVerse @BibleId, 101007010, N'And after seven days the floodwaters engulfed the earth.'
EXEC add_BibleVerse @BibleId, 101007011, N'In the six hundredth year of Noah’s life, in the second month, on the seventeenth day of the month – on that day all the fountains of the great deep burst open and the floodgates of the heavens were opened.'
EXEC add_BibleVerse @BibleId, 101007012, N'And the rain fell on the earth forty days and forty nights.'
EXEC add_BibleVerse @BibleId, 101007013, N'On that very day Noah entered the ark, accompanied by his sons Shem, Ham, and Japheth, along with his wife and his sons’ three wives.'
EXEC add_BibleVerse @BibleId, 101007014, N'They entered, along with every living creature after its kind, every animal after its kind, every creeping thing that creeps on the earth after its kind, and every bird after its kind, everything with wings.'
EXEC add_BibleVerse @BibleId, 101007015, N'Pairs of all creatures that have the breath of life came into the ark to Noah.'
EXEC add_BibleVerse @BibleId, 101007016, N'Those that entered were male and female, just as God commanded him. Then the Lord shut him in.'
EXEC add_BibleVerse @BibleId, 101007017, N'The flood engulfed the earth for forty days. As the waters increased, they lifted the ark and raised it above the earth.'
EXEC add_BibleVerse @BibleId, 101007018, N'The waters completely overwhelmed the earth, and the ark floated on the surface of the waters.'
EXEC add_BibleVerse @BibleId, 101007019, N'The waters completely inundated the earth so that even all the high mountains under the entire sky were covered.'
EXEC add_BibleVerse @BibleId, 101007020, N'The waters rose more than twenty feet above the mountains.'
EXEC add_BibleVerse @BibleId, 101007021, N'And all living things that moved on the earth died, including the birds, domestic animals, wild animals, all the creatures that swarm over the earth, and all humankind.'
EXEC add_BibleVerse @BibleId, 101007022, N'Everything on dry land that had the breath of life in its nostrils died.'
EXEC add_BibleVerse @BibleId, 101007023, N'So the Lord destroyed every living thing that was on the surface of the ground, including people, animals, creatures that creep along the ground, and birds of the sky. They were wiped off the earth. Only Noah and those who were with him in the ark survived.'
EXEC add_BibleVerse @BibleId, 101007024, N'The waters prevailed over the earth for 150 days.'
EXEC add_BibleVerse @BibleId, 101008001, N'But God remembered Noah and all the wild animals and domestic animals that were with him in the ark. God caused a wind to blow over the earth and the waters receded.'
EXEC add_BibleVerse @BibleId, 101008002, N'The fountains of the deep and the floodgates of heaven were closed, and the rain stopped falling from the sky.'
EXEC add_BibleVerse @BibleId, 101008003, N'The waters kept receding steadily from the earth, so that they had gone down by the end of the 150 days.'
EXEC add_BibleVerse @BibleId, 101008004, N'On the seventeenth day of the seventh month, the ark came to rest on one of the mountains of Ararat.'
EXEC add_BibleVerse @BibleId, 101008005, N'The waters kept on receding until the tenth month. On the first day of the tenth month, the tops of the mountains became visible.'
EXEC add_BibleVerse @BibleId, 101008006, N'At the end of forty days, Noah opened the window he had made in the ark'
EXEC add_BibleVerse @BibleId, 101008007, N'and sent out a raven; it kept flying back and forth until the waters had dried up on the earth.'
EXEC add_BibleVerse @BibleId, 101008008, N'Then Noah sent out a dove to see if the waters had receded from the surface of the ground.'
EXEC add_BibleVerse @BibleId, 101008009, N'The dove could not find a resting place for its feet because water still covered the surface of the entire earth, and so it returned to Noah in the ark. He stretched out his hand, took the dove, and brought it back into the ark.'
EXEC add_BibleVerse @BibleId, 101008010, N'He waited seven more days and then sent out the dove again from the ark.'
EXEC add_BibleVerse @BibleId, 101008011, N'When the dove returned to him in the evening, there was a freshly plucked olive leaf in its beak! Noah knew that the waters had receded from the earth.'
EXEC add_BibleVerse @BibleId, 101008012, N'He waited another seven days and sent the dove out again, but it did not return to him this time.'
EXEC add_BibleVerse @BibleId, 101008013, N'In Noah’s six hundred and first year, in the first day of the first month, the waters had dried up from the earth, and Noah removed the covering from the ark and saw that the surface of the ground was dry.'
EXEC add_BibleVerse @BibleId, 101008014, N'And by the twenty-seventh day of the second month the earth was dry.'
EXEC add_BibleVerse @BibleId, 101008015, N'Then God spoke to Noah and said,'
EXEC add_BibleVerse @BibleId, 101008016, N'“Come out of the ark, you, your wife, your sons, and your sons’ wives with you.'
EXEC add_BibleVerse @BibleId, 101008017, N'Bring out with you all the living creatures that are with you. Bring out every living thing, including the birds, animals, and every creeping thing that creeps on the earth. Let them increase and be fruitful and multiply on the earth!”'
EXEC add_BibleVerse @BibleId, 101008018, N'Noah went out along with his sons, his wife, and his sons’ wives.'
EXEC add_BibleVerse @BibleId, 101008019, N'Every living creature, every creeping thing, every bird, and everything that moves on the earth went out of the ark in their groups.'
EXEC add_BibleVerse @BibleId, 101008020, N'Noah built an altar to the Lord. He then took some of every kind of clean animal and clean bird and offered burnt offerings on the altar.'
EXEC add_BibleVerse @BibleId, 101008021, N'And the Lord smelled the soothing aroma and said to himself, “I will never again curse the ground because of humankind, even though the inclination of their minds is evil from childhood on. I will never again destroy everything that lives, as I have just done.'
EXEC add_BibleVerse @BibleId, 101008022, N'“While the earth continues to exist, planting time and harvest, cold and heat, summer and winter, and day and night will not cease.”'
EXEC add_BibleVerse @BibleId, 101009001, N'Then God blessed Noah and his sons and said to them, “Be fruitful and multiply and fill the earth.'
EXEC add_BibleVerse @BibleId, 101009002, N'Every living creature of the earth and every bird of the sky will be terrified of you. Everything that creeps on the ground and all the fish of the sea are under your authority.'
EXEC add_BibleVerse @BibleId, 101009003, N'You may eat any moving thing that lives. As I gave you the green plants, I now give you everything.'
EXEC add_BibleVerse @BibleId, 101009004, N'But you must not eat meat with its life (that is, its blood) in it.'
EXEC add_BibleVerse @BibleId, 101009005, N'For your lifeblood I will surely exact punishment, from every living creature I will exact punishment. From each person I will exact punishment for the life of the individual since the man was his relative.'
EXEC add_BibleVerse @BibleId, 101009006, N'“Whoever sheds human blood, by other humans must his blood be shed; for in God’s image God has made humankind.”'
EXEC add_BibleVerse @BibleId, 101009007, N'But as for you, be fruitful and multiply; increase abundantly on the earth and multiply on it.”'
EXEC add_BibleVerse @BibleId, 101009008, N'God said to Noah and his sons,'
EXEC add_BibleVerse @BibleId, 101009009, N'“Look! I now confirm my covenant with you and your descendants after you'
EXEC add_BibleVerse @BibleId, 101009010, N'and with every living creature that is with you, including the birds, the domestic animals, and every living creature of the earth with you, all those that came out of the ark with you – every living creature of the earth.'
EXEC add_BibleVerse @BibleId, 101009011, N'I confirm my covenant with you: Never again will all living things be wiped out by the waters of a flood; never again will a flood destroy the earth.”'
EXEC add_BibleVerse @BibleId, 101009012, N'And God said, “This is the guarantee of the covenant I am making with you and every living creature with you, a covenant for all subsequent generations:'
EXEC add_BibleVerse @BibleId, 101009013, N'I will place my rainbow in the clouds, and it will become a guarantee of the covenant between me and the earth.'
EXEC add_BibleVerse @BibleId, 101009014, N'Whenever I bring clouds over the earth and the rainbow appears in the clouds,'
EXEC add_BibleVerse @BibleId, 101009015, N'then I will remember my covenant with you and with all living creatures of all kinds. Never again will the waters become a flood and destroy all living things.'
EXEC add_BibleVerse @BibleId, 101009016, N'When the rainbow is in the clouds, I will notice it and remember the perpetual covenant between God and all living creatures of all kinds that are on the earth.”'
EXEC add_BibleVerse @BibleId, 101009017, N'So God said to Noah, “This is the guarantee of the covenant that I am confirming between me and all living things that are on the earth.”'
EXEC add_BibleVerse @BibleId, 101009018, N'The sons of Noah who came out of the ark were Shem, Ham, and Japheth. (Now Ham was the father of Canaan.)'
EXEC add_BibleVerse @BibleId, 101009019, N'These were the sons of Noah, and from them the whole earth was populated.'
EXEC add_BibleVerse @BibleId, 101009020, N'Noah, a man of the soil, began to plant a vineyard.'
EXEC add_BibleVerse @BibleId, 101009021, N'When he drank some of the wine, he got drunk and uncovered himself inside his tent.'
EXEC add_BibleVerse @BibleId, 101009022, N'Ham, the father of Canaan, saw his father’s nakedness and told his two brothers who were outside.'
EXEC add_BibleVerse @BibleId, 101009023, N'Shem and Japheth took the garment and placed it on their shoulders. Then they walked in backwards and covered up their father’s nakedness. Their faces were turned the other way so they did not see their father’s nakedness.'
EXEC add_BibleVerse @BibleId, 101009024, N'When Noah awoke from his drunken stupor he learned what his youngest son had done to him.'
EXEC add_BibleVerse @BibleId, 101009025, N'So he said, “Cursed be Canaan! The lowest of slaves he will be to his brothers.”'
EXEC add_BibleVerse @BibleId, 101009026, N'He also said, “Worthy of praise is the Lord, the God of Shem! May Canaan be the slave of Shem!'
EXEC add_BibleVerse @BibleId, 101009027, N'May God enlarge Japheth’s territory and numbers! May he live in the tents of Shem and may Canaan be his slave!”'
EXEC add_BibleVerse @BibleId, 101009028, N'After the flood Noah lived 350 years.'
EXEC add_BibleVerse @BibleId, 101009029, N'The entire lifetime of Noah was 950 years, and then he died.'
EXEC add_BibleVerse @BibleId, 101010001, N'This is the account of Noah’s sons Shem, Ham, and Japheth. Sons were born to them after the flood.'
EXEC add_BibleVerse @BibleId, 101010002, N'The sons of Japheth were Gomer, Magog, Madai, Javan, Tubal, Meshech, and Tiras.'
EXEC add_BibleVerse @BibleId, 101010003, N'The sons of Gomer were Askenaz, Riphath, and Togarmah.'
EXEC add_BibleVerse @BibleId, 101010004, N'The sons of Javan were Elishah, Tarshish, the Kittim, and the Dodanim.'
EXEC add_BibleVerse @BibleId, 101010005, N'From these the coastlands of the nations were separated into their lands, every one according to its language, according to their families, by their nations.'
EXEC add_BibleVerse @BibleId, 101010006, N'The sons of Ham were Cush, Mizraim, Put, and Canaan.'
EXEC add_BibleVerse @BibleId, 101010007, N'The sons of Cush were Seba, Havilah, Sabtah, Raamah, and Sabteca. The sons of Raamah were Sheba and Dedan.'
EXEC add_BibleVerse @BibleId, 101010008, N'Cush was the father of Nimrod; he began to be a valiant warrior on the earth.'
EXEC add_BibleVerse @BibleId, 101010009, N'He was a mighty hunter before the Lord. (That is why it is said, “Like Nimrod, a mighty hunter before the Lord.”)'
EXEC add_BibleVerse @BibleId, 101010010, N'The primary regions of his kingdom were Babel, Erech, Akkad, and Calneh in the land of Shinar.'
EXEC add_BibleVerse @BibleId, 101010011, N'From that land he went to Assyria, where he built Nineveh, Rehoboth-Ir, Calah,'
EXEC add_BibleVerse @BibleId, 101010012, N'and Resen, which is between Nineveh and the great city Calah.'
EXEC add_BibleVerse @BibleId, 101010013, N'Mizraim was the father of the Ludites, Anamites, Lehabites, Naphtuhites,'
EXEC add_BibleVerse @BibleId, 101010014, N'Pathrusites, Casluhites (from whom the Philistines came), and Caphtorites.'
EXEC add_BibleVerse @BibleId, 101010015, N'Canaan was the father of Sidon his firstborn, Heth,'
EXEC add_BibleVerse @BibleId, 101010016, N'the Jebusites, Amorites, Girgashites,'
EXEC add_BibleVerse @BibleId, 101010017, N'Hivites, Arkites, Sinites,'
EXEC add_BibleVerse @BibleId, 101010018, N'Arvadites, Zemarites, and Hamathites. Eventually the families of the Canaanites were scattered'
EXEC add_BibleVerse @BibleId, 101010019, N'and the borders of Canaan extended from Sidon all the way to Gerar as far as Gaza, and all the way to Sodom, Gomorrah, Admah, and Zeboiim, as far as Lasha.'
EXEC add_BibleVerse @BibleId, 101010020, N'These are the sons of Ham, according to their families, according to their languages, by their lands, and by their nations.'
EXEC add_BibleVerse @BibleId, 101010021, N'And sons were also born to Shem (the older brother of Japheth), the father of all the sons of Eber.'
EXEC add_BibleVerse @BibleId, 101010022, N'The sons of Shem were Elam, Asshur, Arphaxad, Lud, and Aram.'
EXEC add_BibleVerse @BibleId, 101010023, N'The sons of Aram were Uz, Hul, Gether, and Mash.'
EXEC add_BibleVerse @BibleId, 101010024, N'Arphaxad was the father of Shelah, and Shelah was the father of Eber.'
EXEC add_BibleVerse @BibleId, 101010025, N'Two sons were born to Eber: One was named Peleg because in his days the earth was divided, and his brother’s name was Joktan.'
EXEC add_BibleVerse @BibleId, 101010026, N'Joktan was the father of Almodad, Sheleph, Hazarmaveth, Jerah,'
EXEC add_BibleVerse @BibleId, 101010027, N'Hadoram, Uzal, Diklah,'
EXEC add_BibleVerse @BibleId, 101010028, N'Obal, Abimael, Sheba,'
EXEC add_BibleVerse @BibleId, 101010029, N'Ophir, Havilah, and Jobab. All these were sons of Joktan.'
EXEC add_BibleVerse @BibleId, 101010030, N'Their dwelling place was from Mesha all the way to Sephar in the eastern hills.'
EXEC add_BibleVerse @BibleId, 101010031, N'These are the sons of Shem according to their families, according to their languages, by their lands, and according to their nations.'
EXEC add_BibleVerse @BibleId, 101010032, N'These are the families of the sons of Noah, according to their genealogies, by their nations, and from these the nations spread over the earth after the flood.'
EXEC add_BibleVerse @BibleId, 101011001, N'The whole earth had a common language and a common vocabulary.'
EXEC add_BibleVerse @BibleId, 101011002, N'When the people moved eastward, they found a plain in Shinar and settled there.'
EXEC add_BibleVerse @BibleId, 101011003, N'Then they said to one another, “Come, let’s make bricks and bake them thoroughly.” (They had brick instead of stone and tar instead of mortar.)'
EXEC add_BibleVerse @BibleId, 101011004, N'Then they said, “Come, let’s build ourselves a city and a tower with its top in the heavens so that we may make a name for ourselves. Otherwise we will be scattered across the face of the entire earth.”'
EXEC add_BibleVerse @BibleId, 101011005, N'But the Lord came down to see the city and the tower that the people had started building.'
EXEC add_BibleVerse @BibleId, 101011006, N'And the Lord said, “If as one people all sharing a common language they have begun to do this, then nothing they plan to do will be beyond them.'
EXEC add_BibleVerse @BibleId, 101011007, N'Come, let’s go down and confuse their language so they won’t be able to understand each other.”'
EXEC add_BibleVerse @BibleId, 101011008, N'So the Lord scattered them from there across the face of the entire earth, and they stopped building the city.'
EXEC add_BibleVerse @BibleId, 101011009, N'That is why its name was called Babel – because there the Lord confused the language of the entire world, and from there the Lord scattered them across the face of the entire earth.'
EXEC add_BibleVerse @BibleId, 101011010, N'This is the account of Shem. Shem was 100 old when he became the father of Arphaxad, two years after the flood.'
EXEC add_BibleVerse @BibleId, 101011011, N'And after becoming the father of Arphaxad, Shem lived 500 years and had other sons and daughters.'
EXEC add_BibleVerse @BibleId, 101011012, N'When Arphaxad had lived 35 years, he became the father of Shelah.'
EXEC add_BibleVerse @BibleId, 101011013, N'And after he became the father of Shelah, Arphaxad lived 403 years and had other sons and daughters.'
EXEC add_BibleVerse @BibleId, 101011014, N'When Shelah had lived 30 years, he became the father of Eber.'
EXEC add_BibleVerse @BibleId, 101011015, N'And after he became the father of Eber, Shelah lived 403 years and had other sons and daughters.'
EXEC add_BibleVerse @BibleId, 101011016, N'When Eber had lived 34 years, he became the father of Peleg.'
EXEC add_BibleVerse @BibleId, 101011017, N'And after he became the father of Peleg, Eber lived 430 years and had other sons and daughters.'
EXEC add_BibleVerse @BibleId, 101011018, N'When Peleg had lived 30 years, he became the father of Reu.'
EXEC add_BibleVerse @BibleId, 101011019, N'And after he became the father of Reu, Peleg lived 209 years and had other sons and daughters.'
EXEC add_BibleVerse @BibleId, 101011020, N'When Reu had lived 32 years, he became the father of Serug.'
EXEC add_BibleVerse @BibleId, 101011021, N'And after he became the father of Serug, Reu lived 207 years and had other sons and daughters.'
EXEC add_BibleVerse @BibleId, 101011022, N'When Serug had lived 30 years, he became the father of Nahor.'
EXEC add_BibleVerse @BibleId, 101011023, N'And after he became the father of Nahor, Serug lived 200 years and had other sons and daughters.'
EXEC add_BibleVerse @BibleId, 101011024, N'When Nahor had lived 29 years, he became the father of Terah.'
EXEC add_BibleVerse @BibleId, 101011025, N'And after he became the father of Terah, Nahor lived 119 years and had other sons and daughters.'
EXEC add_BibleVerse @BibleId, 101011026, N'When Terah had lived 70 years, he became the father of Abram, Nahor, and Haran.'
EXEC add_BibleVerse @BibleId, 101011027, N'This is the account of Terah. Terah became the father of Abram, Nahor, and Haran. And Haran became the father of Lot.'
EXEC add_BibleVerse @BibleId, 101011028, N'Haran died in the land of his birth, in Ur of the Chaldeans, while his father Terah was still alive.'
EXEC add_BibleVerse @BibleId, 101011029, N'And Abram and Nahor took wives for themselves. The name of Abram’s wife was Sarai, and the name of Nahor’s wife was Milcah; she was the daughter of Haran, the father of both Milcah and Iscah.'
EXEC add_BibleVerse @BibleId, 101011030, N'But Sarai was barren; she had no children.'
EXEC add_BibleVerse @BibleId, 101011031, N'Terah took his son Abram, his grandson Lot (the son of Haran), and his daughter-in-law Sarai, his son Abram’s wife, and with them he set out from Ur of the Chaldeans to go to Canaan. When they came to Haran, they settled there.'
EXEC add_BibleVerse @BibleId, 101011032, N'The lifetime of Terah was 205 years, and he died in Haran.'
EXEC add_BibleVerse @BibleId, 101012001, N'Now the Lord said to Abram, “Go out from your country, your relatives, and your father’s household to the land that I will show you.'
EXEC add_BibleVerse @BibleId, 101012002, N'Then I will make you into a great nation, and I will bless you, and I will make your name great, so that you will exemplify divine blessing.'
EXEC add_BibleVerse @BibleId, 101012003, N'I will bless those who bless you, but the one who treats you lightly I must curse, and all the families of the earth will bless one another by your name.”'
EXEC add_BibleVerse @BibleId, 101012004, N'So Abram left, just as the Lord had told him to do, and Lot went with him. (Now Abram was 75 years old when he departed from Haran.)'
EXEC add_BibleVerse @BibleId, 101012005, N'And Abram took his wife Sarai, his nephew Lot, and all the possessions they had accumulated and the people they had acquired in Haran, and they left for the land of Canaan. They entered the land of Canaan.'
EXEC add_BibleVerse @BibleId, 101012006, N'Abram traveled through the land as far as the oak tree of Moreh at Shechem. (At that time the Canaanites were in the land.)'
EXEC add_BibleVerse @BibleId, 101012007, N'The Lord appeared to Abram and said, “To your descendants I will give this land.” So Abram built an altar there to the Lord, who had appeared to him.'
EXEC add_BibleVerse @BibleId, 101012008, N'Then he moved from there to the hill country east of Bethel and pitched his tent, with Bethel on the west and Ai on the east. There he built an altar to the Lord and worshiped the Lord.'
EXEC add_BibleVerse @BibleId, 101012009, N'Abram continually journeyed by stages down to the Negev.'
EXEC add_BibleVerse @BibleId, 101012010, N'There was a famine in the land, so Abram went down to Egypt to stay for a while because the famine was severe.'
EXEC add_BibleVerse @BibleId, 101012011, N'As he approached Egypt, he said to his wife Sarai, “Look, I know that you are a beautiful woman.'
EXEC add_BibleVerse @BibleId, 101012012, N'When the Egyptians see you they will say, ‘This is his wife.’ Then they will kill me but will keep you alive.'
EXEC add_BibleVerse @BibleId, 101012013, N'So tell them you are my sister so that it may go well for me because of you and my life will be spared on account of you.”'
EXEC add_BibleVerse @BibleId, 101012014, N'When Abram entered Egypt, the Egyptians saw that the woman was very beautiful.'
EXEC add_BibleVerse @BibleId, 101012015, N'When Pharaoh’s officials saw her, they praised her to Pharaoh. So Abram’s wife was taken into the household of Pharaoh,'
EXEC add_BibleVerse @BibleId, 101012016, N'and he did treat Abram well on account of her. Abram received sheep and cattle, male donkeys, male servants, female servants, female donkeys, and camels.'
EXEC add_BibleVerse @BibleId, 101012017, N'But the Lord struck Pharaoh and his household with severe diseases because of Sarai, Abram’s wife.'
EXEC add_BibleVerse @BibleId, 101012018, N'So Pharaoh summoned Abram and said, “What is this you have done to me? Why didn’t you tell me that she was your wife?'
EXEC add_BibleVerse @BibleId, 101012019, N'Why did you say, ‘She is my sister,’ so that I took her to be my wife? Here is your wife! Take her and go!”'
EXEC add_BibleVerse @BibleId, 101012020, N'Pharaoh gave his men orders about Abram, and so they expelled him, along with his wife and all his possessions.'
EXEC add_BibleVerse @BibleId, 101013001, N'So Abram went up from Egypt into the Negev. He took his wife and all his possessions with him, as well as Lot.'
EXEC add_BibleVerse @BibleId, 101013002, N'(Now Abram was very wealthy in livestock, silver, and gold.)'
EXEC add_BibleVerse @BibleId, 101013003, N'And he journeyed from place to place from the Negev as far as Bethel. He returned to the place where he had pitched his tent at the beginning, between Bethel and Ai.'
EXEC add_BibleVerse @BibleId, 101013004, N'This was the place where he had first built the altar, and there Abram worshiped the Lord.'
EXEC add_BibleVerse @BibleId, 101013005, N'Now Lot, who was traveling with Abram, also had flocks, herds, and tents.'
EXEC add_BibleVerse @BibleId, 101013006, N'But the land could not support them while they were living side by side. Because their possessions were so great, they were not able to live alongside one another.'
EXEC add_BibleVerse @BibleId, 101013007, N'So there were quarrels between Abram’s herdsmen and Lot’s herdsmen. (Now the Canaanites and the Perizzites were living in the land at that time.)'
EXEC add_BibleVerse @BibleId, 101013008, N'Abram said to Lot, “Let there be no quarreling between me and you, and between my herdsmen and your herdsmen, for we are close relatives.'
EXEC add_BibleVerse @BibleId, 101013009, N'Is not the whole land before you? Separate yourself now from me. If you go to the left, then I’ll go to the right, but if you go to the right, then I’ll go to the left.”'
EXEC add_BibleVerse @BibleId, 101013010, N'Lot looked up and saw the whole region of the Jordan. He noticed that all of it was well-watered (before the Lord obliterated Sodom and Gomorrah) like the garden of the Lord, like the land of Egypt, all the way to Zoar.'
EXEC add_BibleVerse @BibleId, 101013011, N'Lot chose for himself the whole region of the Jordan and traveled toward the east. So the relatives separated from each other.'
EXEC add_BibleVerse @BibleId, 101013012, N'Abram settled in the land of Canaan, but Lot settled among the cities of the Jordan plain and pitched his tents next to Sodom.'
EXEC add_BibleVerse @BibleId, 101013013, N'(Now the people of Sodom were extremely wicked rebels against the Lord.)'
EXEC add_BibleVerse @BibleId, 101013014, N'After Lot had departed, the Lord said to Abram, “Look from the place where you stand to the north, south, east, and west.'
EXEC add_BibleVerse @BibleId, 101013015, N'I will give all the land that you see to you and your descendants forever.'
EXEC add_BibleVerse @BibleId, 101013016, N'And I will make your descendants like the dust of the earth, so that if anyone is able to count the dust of the earth, then your descendants also can be counted.'
EXEC add_BibleVerse @BibleId, 101013017, N'Get up and walk throughout the land, for I will give it to you.”'
EXEC add_BibleVerse @BibleId, 101013018, N'So Abram moved his tents and went to live by the oaks of Mamre in Hebron, and he built an altar to the Lord there.'
EXEC add_BibleVerse @BibleId, 101014001, N'At that time Amraphel king of Shinar, Arioch king of Ellasar, Kedorlaomer king of Elam, and Tidal king of nations'
EXEC add_BibleVerse @BibleId, 101014002, N'went to war against Bera king of Sodom, Birsha king of Gomorrah, Shinab king of Admah, Shemeber king of Zeboiim, and the king of Bela (that is, Zoar).'
EXEC add_BibleVerse @BibleId, 101014003, N'These last five kings joined forces in the Valley of Siddim (that is, the Salt Sea).'
EXEC add_BibleVerse @BibleId, 101014004, N'For twelve years they had served Kedorlaomer, but in the thirteenth year they rebelled.'
EXEC add_BibleVerse @BibleId, 101014005, N'In the fourteenth year, Kedorlaomer and the kings who were his allies came and defeated the Rephaites in Ashteroth Karnaim, the Zuzites in Ham, the Emites in Shaveh Kiriathaim,'
EXEC add_BibleVerse @BibleId, 101014006, N'and the Horites in their hill country of Seir, as far as El Paran, which is near the desert.'
EXEC add_BibleVerse @BibleId, 101014007, N'Then they attacked En Mishpat (that is, Kadesh) again, and they conquered all the territory of the Amalekites, as well as the Amorites who were living in Hazazon Tamar.'
EXEC add_BibleVerse @BibleId, 101014008, N'Then the king of Sodom, the king of Gomorrah, the king of Admah, the king of Zeboiim, and the king of Bela (that is, Zoar) went out and prepared for battle. In the Valley of Siddim they met'
EXEC add_BibleVerse @BibleId, 101014009, N'Kedorlaomer king of Elam, Tidal king of nations, Amraphel king of Shinar, and Arioch king of Ellasar. Four kings fought against five.'
EXEC add_BibleVerse @BibleId, 101014010, N'Now the Valley of Siddim was full of tar pits. When the kings of Sodom and Gomorrah fled, they fell into them, but some survivors fled to the hills.'
EXEC add_BibleVerse @BibleId, 101014011, N'The four victorious kings took all the possessions and food of Sodom and Gomorrah and left.'
EXEC add_BibleVerse @BibleId, 101014012, N'They also took Abram’s nephew Lot and his possessions when they left, for Lot was living in Sodom.'
EXEC add_BibleVerse @BibleId, 101014013, N'A fugitive came and told Abram the Hebrew. Now Abram was living by the oaks of Mamre the Amorite, the brother of Eshcol and Aner. (All these were allied by treaty with Abram.)'
EXEC add_BibleVerse @BibleId, 101014014, N'When Abram heard that his nephew had been taken captive, he mobilized his 318 trained men who had been born in his household, and he pursued the invaders as far as Dan.'
EXEC add_BibleVerse @BibleId, 101014015, N'Then, during the night, Abram divided his forces against them and defeated them. He chased them as far as Hobah, which is north of Damascus.'
EXEC add_BibleVerse @BibleId, 101014016, N'He retrieved all the stolen property. He also brought back his nephew Lot and his possessions, as well as the women and the rest of the people.'
EXEC add_BibleVerse @BibleId, 101014017, N'After Abram returned from defeating Kedorlaomer and the kings who were with him, the king of Sodom went out to meet Abram in the Valley of Shaveh (known as the King’s Valley).'
EXEC add_BibleVerse @BibleId, 101014018, N'Melchizedek king of Salem brought out bread and wine. (Now he was the priest of the Most High God.)'
EXEC add_BibleVerse @BibleId, 101014019, N'He blessed Abram, saying, “Blessed be Abram by the Most High God, Creator of heaven and earth.'
EXEC add_BibleVerse @BibleId, 101014020, N'Worthy of praise is the Most High God, who delivered your enemies into your hand.” Abram gave Melchizedek a tenth of everything.'
EXEC add_BibleVerse @BibleId, 101014021, N'Then the king of Sodom said to Abram, “Give me the people and take the possessions for yourself.”'
EXEC add_BibleVerse @BibleId, 101014022, N'But Abram replied to the king of Sodom, “I raise my hand to the Lord, the Most High God, Creator of heaven and earth, and vow'
EXEC add_BibleVerse @BibleId, 101014023, N'that I will take nothing belonging to you, not even a thread or the strap of a sandal. That way you can never say, ‘It is I who made Abram rich.’'
EXEC add_BibleVerse @BibleId, 101014024, N'I will take nothing except compensation for what the young men have eaten. As for the share of the men who went with me – Aner, Eshcol, and Mamre – let them take their share.”'
EXEC add_BibleVerse @BibleId, 101015001, N'After these things the word of the Lord came to Abram in a vision: “Fear not, Abram! I am your shield and the one who will reward you in great abundance.”'
EXEC add_BibleVerse @BibleId, 101015002, N'But Abram said, “O sovereign Lord, what will you give me since I continue to be childless, and my heir is Eliezer of Damascus?”'
EXEC add_BibleVerse @BibleId, 101015003, N'Abram added, “Since you have not given me a descendant, then look, one born in my house will be my heir!”'
EXEC add_BibleVerse @BibleId, 101015004, N'But look, the word of the Lord came to him: “This man will not be your heir, but instead a son who comes from your own body will be your heir.”'
EXEC add_BibleVerse @BibleId, 101015005, N'The Lord took him outside and said, “Gaze into the sky and count the stars – if you are able to count them!” Then he said to him, “So will your descendants be.”'
EXEC add_BibleVerse @BibleId, 101015006, N'Abram believed the Lord, and the Lord considered his response of faith as proof of genuine loyalty.'
EXEC add_BibleVerse @BibleId, 101015007, N'The Lord said to him, “I am the Lord who brought you out from Ur of the Chaldeans to give you this land to possess.”'
EXEC add_BibleVerse @BibleId, 101015008, N'But Abram said, “O sovereign Lord, by what can I know that I am to possess it?”'
EXEC add_BibleVerse @BibleId, 101015009, N'The Lord said to him, “Take for me a heifer, a goat, and a ram, each three years old, along with a dove and a young pigeon.”'
EXEC add_BibleVerse @BibleId, 101015010, N'So Abram took all these for him and then cut them in two and placed each half opposite the other, but he did not cut the birds in half.'
EXEC add_BibleVerse @BibleId, 101015011, N'When birds of prey came down on the carcasses, Abram drove them away.'
EXEC add_BibleVerse @BibleId, 101015012, N'When the sun went down, Abram fell sound asleep, and great terror overwhelmed him.'
EXEC add_BibleVerse @BibleId, 101015013, N'Then the Lord said to Abram, “Know for certain that your descendants will be strangers in a foreign country. They will be enslaved and oppressed for four hundred years.'
EXEC add_BibleVerse @BibleId, 101015014, N'But I will execute judgment on the nation that they will serve. Afterward they will come out with many possessions.'
EXEC add_BibleVerse @BibleId, 101015015, N'But as for you, you will go to your ancestors in peace and be buried at a good old age.'
EXEC add_BibleVerse @BibleId, 101015016, N'In the fourth generation your descendants will return here, for the sin of the Amorites has not yet reached its limit.”'
EXEC add_BibleVerse @BibleId, 101015017, N'When the sun had gone down and it was dark, a smoking firepot with a flaming torch passed between the animal parts.'
EXEC add_BibleVerse @BibleId, 101015018, N'That day the Lord made a covenant with Abram: “To your descendants I give this land, from the river of Egypt to the great river, the Euphrates River –'
EXEC add_BibleVerse @BibleId, 101015019, N'the land of the Kenites, Kenizzites, Kadmonites,'
EXEC add_BibleVerse @BibleId, 101015020, N'Hittites, Perizzites, Rephaites,'
EXEC add_BibleVerse @BibleId, 101015021, N'Amorites, Canaanites, Girgashites, and Jebusites.”'
EXEC add_BibleVerse @BibleId, 101016001, N'Now Sarai, Abram’s wife, had not given birth to any children, but she had an Egyptian servant named Hagar.'
EXEC add_BibleVerse @BibleId, 101016002, N'So Sarai said to Abram, “Since the Lord has prevented me from having children, have sexual relations with my servant. Perhaps I can have a family by her.” Abram did what Sarai told him.'
EXEC add_BibleVerse @BibleId, 101016003, N'So after Abram had lived in Canaan for ten years, Sarai, Abram’s wife, gave Hagar, her Egyptian servant, to her husband to be his wife.'
EXEC add_BibleVerse @BibleId, 101016004, N'He had sexual relations with Hagar, and she became pregnant. Once Hagar realized she was pregnant, she despised Sarai.'
EXEC add_BibleVerse @BibleId, 101016005, N'Then Sarai said to Abram, “You have brought this wrong on me! I allowed my servant to have sexual relations with you, but when she realized that she was pregnant, she despised me. May the Lord judge between you and me!”'
EXEC add_BibleVerse @BibleId, 101016006, N'Abram said to Sarai, “Since your servant is under your authority, do to her whatever you think best.” Then Sarai treated Hagar harshly, so she ran away from Sarai.'
EXEC add_BibleVerse @BibleId, 101016007, N'The Lord’s angel found Hagar near a spring of water in the desert – the spring that is along the road to Shur.'
EXEC add_BibleVerse @BibleId, 101016008, N'He said, “Hagar, servant of Sarai, where have you come from, and where are you going?” She replied, “I’m running away from my mistress, Sarai.”'
EXEC add_BibleVerse @BibleId, 101016009, N'Then the Lord’s angel said to her, “Return to your mistress and submit to her authority.'
EXEC add_BibleVerse @BibleId, 101016010, N'I will greatly multiply your descendants,” the Lord’s angel added, “so that they will be too numerous to count.”'
EXEC add_BibleVerse @BibleId, 101016011, N'Then the Lord’s angel said to her, “You are now pregnant and are about to give birth to a son. You are to name him Ishmael, for the Lord has heard your painful groans.'
EXEC add_BibleVerse @BibleId, 101016012, N'He will be a wild donkey of a man. He will be hostile to everyone, and everyone will be hostile to him. He will live away from his brothers.”'
EXEC add_BibleVerse @BibleId, 101016013, N'So Hagar named the Lord who spoke to her, “You are the God who sees me,” for she said, “Here I have seen one who sees me!”'
EXEC add_BibleVerse @BibleId, 101016014, N'That is why the well was called Beer Lahai Roi. (It is located between Kadesh and Bered.)'
EXEC add_BibleVerse @BibleId, 101016015, N'So Hagar gave birth to Abram’s son, whom Abram named Ishmael.'
EXEC add_BibleVerse @BibleId, 101016016, N'(Now Abram was 86 years old when Hagar gave birth to Ishmael.)'
EXEC add_BibleVerse @BibleId, 101017001, N'When Abram was 99 years old, the Lord appeared to him and said, “I am the sovereign God. Walk before me and be blameless.'
EXEC add_BibleVerse @BibleId, 101017002, N'Then I will confirm my covenant between me and you, and I will give you a multitude of descendants.”'
EXEC add_BibleVerse @BibleId, 101017003, N'Abram bowed down with his face to the ground, and God said to him,'
EXEC add_BibleVerse @BibleId, 101017004, N'“As for me, this is my covenant with you: You will be the father of a multitude of nations.'
EXEC add_BibleVerse @BibleId, 101017005, N'No longer will your name be Abram. Instead, your name will be Abraham because I will make you the father of a multitude of nations.'
EXEC add_BibleVerse @BibleId, 101017006, N'I will make you extremely fruitful. I will make nations of you, and kings will descend from you.'
EXEC add_BibleVerse @BibleId, 101017007, N'I will confirm my covenant as a perpetual covenant between me and you. It will extend to your descendants after you throughout their generations. I will be your God and the God of your descendants after you.'
EXEC add_BibleVerse @BibleId, 101017008, N'I will give the whole land of Canaan – the land where you are now residing – to you and your descendants after you as a permanent possession. I will be their God.”'
EXEC add_BibleVerse @BibleId, 101017009, N'Then God said to Abraham, “As for you, you must keep the covenantal requirement I am imposing on you and your descendants after you throughout their generations.'
EXEC add_BibleVerse @BibleId, 101017010, N'This is my requirement that you and your descendants after you must keep: Every male among you must be circumcised.'
EXEC add_BibleVerse @BibleId, 101017011, N'You must circumcise the flesh of your foreskins. This will be a reminder of the covenant between me and you.'
EXEC add_BibleVerse @BibleId, 101017012, N'Throughout your generations every male among you who is eight days old must be circumcised, whether born in your house or bought with money from any foreigner who is not one of your descendants.'
EXEC add_BibleVerse @BibleId, 101017013, N'They must indeed be circumcised, whether born in your house or bought with money. The sign of my covenant will be visible in your flesh as a permanent reminder.'
EXEC add_BibleVerse @BibleId, 101017014, N'Any uncircumcised male who has not been circumcised in the flesh of his foreskin will be cut off from his people – he has failed to carry out my requirement.”'
EXEC add_BibleVerse @BibleId, 101017015, N'Then God said to Abraham, “As for your wife, you must no longer call her Sarai; Sarah will be her name.'
EXEC add_BibleVerse @BibleId, 101017016, N'I will bless her and will give you a son through her. I will bless her and she will become a mother of nations. Kings of countries will come from her!”'
EXEC add_BibleVerse @BibleId, 101017017, N'Then Abraham bowed down with his face to the ground and laughed as he said to himself, “Can a son be born to a man who is a hundred years old? Can Sarah bear a child at the age of ninety?”'
EXEC add_BibleVerse @BibleId, 101017018, N'Abraham said to God, “O that Ishmael might live before you!”'
EXEC add_BibleVerse @BibleId, 101017019, N'God said, “No, Sarah your wife is going to bear you a son, and you will name him Isaac. I will confirm my covenant with him as a perpetual covenant for his descendants after him.'
EXEC add_BibleVerse @BibleId, 101017020, N'As for Ishmael, I have heard you. I will indeed bless him, make him fruitful, and give him a multitude of descendants. He will become the father of twelve princes; I will make him into a great nation.'
EXEC add_BibleVerse @BibleId, 101017021, N'But I will establish my covenant with Isaac, whom Sarah will bear to you at this set time next year.”'
EXEC add_BibleVerse @BibleId, 101017022, N'When he finished speaking with Abraham, God went up from him.'
EXEC add_BibleVerse @BibleId, 101017023, N'Abraham took his son Ishmael and every male in his household (whether born in his house or bought with money) and circumcised them on that very same day, just as God had told him to do.'
EXEC add_BibleVerse @BibleId, 101017024, N'Now Abraham was 99 years old when he was circumcised;'
EXEC add_BibleVerse @BibleId, 101017025, N'his son Ishmael was thirteen years old when he was circumcised.'
EXEC add_BibleVerse @BibleId, 101017026, N'Abraham and his son Ishmael were circumcised on the very same day.'
EXEC add_BibleVerse @BibleId, 101017027, N'All the men of his household, whether born in his household or bought with money from a foreigner, were circumcised with him.'
EXEC add_BibleVerse @BibleId, 101018001, N'The Lord appeared to Abraham by the oaks of Mamre while he was sitting at the entrance to his tent during the hottest time of the day.'
EXEC add_BibleVerse @BibleId, 101018002, N'Abraham looked up and saw three men standing across from him. When he saw them he ran from the entrance of the tent to meet them and bowed low to the ground.'
EXEC add_BibleVerse @BibleId, 101018003, N'He said, “My lord, if I have found favor in your sight, do not pass by and leave your servant.'
EXEC add_BibleVerse @BibleId, 101018004, N'Let a little water be brought so that you may all wash your feet and rest under the tree.'
EXEC add_BibleVerse @BibleId, 101018005, N'And let me get a bit of food so that you may refresh yourselves since you have passed by your servant’s home. After that you may be on your way.” “All right,” they replied, “you may do as you say.”'
EXEC add_BibleVerse @BibleId, 101018006, N'So Abraham hurried into the tent and said to Sarah, “Quick! Take three measures of fine flour, knead it, and make bread.”'
EXEC add_BibleVerse @BibleId, 101018007, N'Then Abraham ran to the herd and chose a fine, tender calf, and gave it to a servant, who quickly prepared it.'
EXEC add_BibleVerse @BibleId, 101018008, N'Abraham then took some curds and milk, along with the calf that had been prepared, and placed the food before them. They ate while he was standing near them under a tree.'
EXEC add_BibleVerse @BibleId, 101018009, N'Then they asked him, “Where is Sarah your wife?” He replied, “There, in the tent.”'
EXEC add_BibleVerse @BibleId, 101018010, N'One of them said, “I will surely return to you when the season comes round again, and your wife Sarah will have a son!” (Now Sarah was listening at the entrance to the tent, not far behind him.'
EXEC add_BibleVerse @BibleId, 101018011, N'Abraham and Sarah were old and advancing in years; Sarah had long since passed menopause.)'
EXEC add_BibleVerse @BibleId, 101018012, N'So Sarah laughed to herself, thinking, “After I am worn out will I have pleasure, especially when my husband is old too?”'
EXEC add_BibleVerse @BibleId, 101018013, N'The Lord said to Abraham, “Why did Sarah laugh and say, ‘Will I really have a child when I am old?’'
EXEC add_BibleVerse @BibleId, 101018014, N'Is anything impossible for the Lord? I will return to you when the season comes round again and Sarah will have a son.”'
EXEC add_BibleVerse @BibleId, 101018015, N'Then Sarah lied, saying, “I did not laugh,” because she was afraid. But the Lord said, “No! You did laugh.”'
EXEC add_BibleVerse @BibleId, 101018016, N'When the men got up to leave, they looked out over Sodom. (Now Abraham was walking with them to see them on their way.)'
EXEC add_BibleVerse @BibleId, 101018017, N'Then the Lord said, “Should I hide from Abraham what I am about to do?'
EXEC add_BibleVerse @BibleId, 101018018, N'After all, Abraham will surely become a great and powerful nation, and all the nations on the earth will pronounce blessings on one another using his name.'
EXEC add_BibleVerse @BibleId, 101018019, N'I have chosen him so that he may command his children and his household after him to keep the way of the Lord by doing what is right and just. Then the Lord will give to Abraham what he promised him.”'
EXEC add_BibleVerse @BibleId, 101018020, N'So the Lord said, “The outcry against Sodom and Gomorrah is so great and their sin so blatant'
EXEC add_BibleVerse @BibleId, 101018021, N'that I must go down and see if they are as wicked as the outcry suggests. If not, I want to know.”'
EXEC add_BibleVerse @BibleId, 101018022, N'The two men turned and headed toward Sodom, but Abraham was still standing before the Lord.'
EXEC add_BibleVerse @BibleId, 101018023, N'Abraham approached and said, “Will you sweep away the godly along with the wicked?'
EXEC add_BibleVerse @BibleId, 101018024, N'What if there are fifty godly people in the city? Will you really wipe it out and not spare the place for the sake of the fifty godly people who are in it?'
EXEC add_BibleVerse @BibleId, 101018025, N'Far be it from you to do such a thing – to kill the godly with the wicked, treating the godly and the wicked alike! Far be it from you! Will not the judge of the whole earth do what is right?”'
EXEC add_BibleVerse @BibleId, 101018026, N'So the Lord replied, “If I find in the city of Sodom fifty godly people, I will spare the whole place for their sake.”'
EXEC add_BibleVerse @BibleId, 101018027, N'Then Abraham asked, “Since I have undertaken to speak to the Lord (although I am but dust and ashes),'
EXEC add_BibleVerse @BibleId, 101018028, N'what if there are five less than the fifty godly people? Will you destroy the whole city because five are lacking?” He replied, “I will not destroy it if I find forty-five there.”'
EXEC add_BibleVerse @BibleId, 101018029, N'Abraham spoke to him again, “What if forty are found there?” He replied, “I will not do it for the sake of the forty.”'
EXEC add_BibleVerse @BibleId, 101018030, N'Then Abraham said, “May the Lord not be angry so that I may speak! What if thirty are found there?” He replied, “I will not do it if I find thirty there.”'
EXEC add_BibleVerse @BibleId, 101018031, N'Abraham said, “Since I have undertaken to speak to the Lord, what if only twenty are found there?” He replied, “I will not destroy it for the sake of the twenty.”'
EXEC add_BibleVerse @BibleId, 101018032, N'Finally Abraham said, “May the Lord not be angry so that I may speak just once more. What if ten are found there?” He replied, “I will not destroy it for the sake of the ten.”'
EXEC add_BibleVerse @BibleId, 101018033, N'The Lord went on his way when he had finished speaking to Abraham. Then Abraham returned home.'
EXEC add_BibleVerse @BibleId, 101019001, N'The two angels came to Sodom in the evening while Lot was sitting in the city’s gateway. When Lot saw them, he got up to meet them and bowed down with his face toward the ground.'
EXEC add_BibleVerse @BibleId, 101019002, N'He said, “Here, my lords, please turn aside to your servant’s house. Stay the night and wash your feet. Then you can be on your way early in the morning.” “No,” they replied, “we’ll spend the night in the town square.”'
EXEC add_BibleVerse @BibleId, 101019003, N'But he urged them persistently, so they turned aside with him and entered his house. He prepared a feast for them, including bread baked without yeast, and they ate.'
EXEC add_BibleVerse @BibleId, 101019004, N'Before they could lie down to sleep, all the men – both young and old, from every part of the city of Sodom – surrounded the house.'
EXEC add_BibleVerse @BibleId, 101019005, N'They shouted to Lot, “Where are the men who came to you tonight? Bring them out to us so we can have sex with them!”'
EXEC add_BibleVerse @BibleId, 101019006, N'Lot went outside to them, shutting the door behind him.'
EXEC add_BibleVerse @BibleId, 101019007, N'He said, “No, my brothers! Don’t act so wickedly!'
EXEC add_BibleVerse @BibleId, 101019008, N'Look, I have two daughters who have never had sexual relations with a man. Let me bring them out to you, and you can do to them whatever you please. Only don’t do anything to these men, for they have come under the protection of my roof.”'
EXEC add_BibleVerse @BibleId, 101019009, N'“Out of our way!” they cried, and “This man came to live here as a foreigner, and now he dares to judge us! We’ll do more harm to you than to them!” They kept pressing in on Lot until they were close enough to break down the door.'
EXEC add_BibleVerse @BibleId, 101019010, N'So the men inside reached out and pulled Lot back into the house as they shut the door.'
EXEC add_BibleVerse @BibleId, 101019011, N'Then they struck the men who were at the door of the house, from the youngest to the oldest, with blindness. The men outside wore themselves out trying to find the door.'
EXEC add_BibleVerse @BibleId, 101019012, N'Then the two visitors said to Lot, “Who else do you have here? Do you have any sons-in-law, sons, daughters, or other relatives in the city? Get them out of this place'
EXEC add_BibleVerse @BibleId, 101019013, N'because we are about to destroy it. The outcry against this place is so great before the Lord that he has sent us to destroy it.”'
EXEC add_BibleVerse @BibleId, 101019014, N'Then Lot went out and spoke to his sons-in-law who were going to marry his daughters. He said, “Quick, get out of this place because the Lord is about to destroy the city!” But his sons-in-law thought he was ridiculing them.'
EXEC add_BibleVerse @BibleId, 101019015, N'At dawn the angels hurried Lot along, saying, “Get going! Take your wife and your two daughters who are here, or else you will be destroyed when the city is judged!”'
EXEC add_BibleVerse @BibleId, 101019016, N'When Lot hesitated, the men grabbed his hand and the hands of his wife and two daughters because the Lord had compassion on them. They led them away and placed them outside the city.'
EXEC add_BibleVerse @BibleId, 101019017, N'When they had brought them outside, they said, “Run for your lives! Don’t look behind you or stop anywhere in the valley! Escape to the mountains or you will be destroyed!”'
EXEC add_BibleVerse @BibleId, 101019018, N'But Lot said to them, “No, please, Lord!'
EXEC add_BibleVerse @BibleId, 101019019, N'Your servant has found favor with you, and you have shown me great kindness by sparing my life. But I am not able to escape to the mountains because this disaster will overtake me and I’ll die.'
EXEC add_BibleVerse @BibleId, 101019020, N'Look, this town over here is close enough to escape to, and it’s just a little one. Let me go there. It’s just a little place, isn’t it? Then I’ll survive.”'
EXEC add_BibleVerse @BibleId, 101019021, N'“Very well,” he replied, “I will grant this request too and will not overthrow the town you mentioned.'
EXEC add_BibleVerse @BibleId, 101019022, N'Run there quickly, for I cannot do anything until you arrive there.” (This incident explains why the town was called Zoar.)'
EXEC add_BibleVerse @BibleId, 101019023, N'The sun had just risen over the land as Lot reached Zoar.'
EXEC add_BibleVerse @BibleId, 101019024, N'Then the Lord rained down sulfur and fire on Sodom and Gomorrah. It was sent down from the sky by the Lord.'
EXEC add_BibleVerse @BibleId, 101019025, N'So he overthrew those cities and all that region, including all the inhabitants of the cities and the vegetation that grew from the ground.'
EXEC add_BibleVerse @BibleId, 101019026, N'But Lot’s wife looked back longingly and was turned into a pillar of salt.'
EXEC add_BibleVerse @BibleId, 101019027, N'Abraham got up early in the morning and went to the place where he had stood before the Lord.'
EXEC add_BibleVerse @BibleId, 101019028, N'He looked out toward Sodom and Gomorrah and all the land of that region. As he did so, he saw the smoke rising up from the land like smoke from a furnace.'
EXEC add_BibleVerse @BibleId, 101019029, N'So when God destroyed the cities of the region, God honored Abraham’s request. He removed Lot from the midst of the destruction when he destroyed the cities Lot had lived in.'
EXEC add_BibleVerse @BibleId, 101019030, N'Lot went up from Zoar with his two daughters and settled in the mountains because he was afraid to live in Zoar. So he lived in a cave with his two daughters.'
EXEC add_BibleVerse @BibleId, 101019031, N'Later the older daughter said to the younger, “Our father is old, and there is no man anywhere nearby to have sexual relations with us, according to the way of all the world.'
EXEC add_BibleVerse @BibleId, 101019032, N'Come, let’s make our father drunk with wine so we can have sexual relations with him and preserve our family line through our father.”'
EXEC add_BibleVerse @BibleId, 101019033, N'So that night they made their father drunk with wine, and the older daughter came and had sexual relations with her father. But he was not aware that she had sexual relations with him and then got up.'
EXEC add_BibleVerse @BibleId, 101019034, N'So in the morning the older daughter said to the younger, “Since I had sexual relations with my father last night, let’s make him drunk again tonight. Then you go and have sexual relations with him so we can preserve our family line through our father.”'
EXEC add_BibleVerse @BibleId, 101019035, N'So they made their father drunk that night as well, and the younger one came and had sexual relations with him. But he was not aware that she had sexual relations with him and then got up.'
EXEC add_BibleVerse @BibleId, 101019036, N'In this way both of Lot’s daughters became pregnant by their father.'
EXEC add_BibleVerse @BibleId, 101019037, N'The older daughter gave birth to a son and named him Moab. He is the ancestor of the Moabites of today.'
EXEC add_BibleVerse @BibleId, 101019038, N'The younger daughter also gave birth to a son and named him Ben-Ammi. He is the ancestor of the Ammonites of today.'
EXEC add_BibleVerse @BibleId, 101020001, N'Abraham journeyed from there to the Negev region and settled between Kadesh and Shur. While he lived as a temporary resident in Gerar,'
EXEC add_BibleVerse @BibleId, 101020002, N'Abraham said about his wife Sarah, “She is my sister.” So Abimelech, king of Gerar, sent for Sarah and took her.'
EXEC add_BibleVerse @BibleId, 101020003, N'But God appeared to Abimelech in a dream at night and said to him, “You are as good as dead because of the woman you have taken, for she is someone else’s wife.”'
EXEC add_BibleVerse @BibleId, 101020004, N'Now Abimelech had not gone near her. He said, “Lord, would you really slaughter an innocent nation?'
EXEC add_BibleVerse @BibleId, 101020005, N'Did Abraham not say to me, ‘She is my sister’? And she herself said, ‘He is my brother.’ I have done this with a clear conscience and with innocent hands!”'
EXEC add_BibleVerse @BibleId, 101020006, N'Then in the dream God replied to him, “Yes, I know that you have done this with a clear conscience. That is why I have kept you from sinning against me and why I did not allow you to touch her.'
EXEC add_BibleVerse @BibleId, 101020007, N'But now give back the man’s wife. Indeed he is a prophet and he will pray for you; thus you will live. But if you don’t give her back, know that you will surely die along with all who belong to you.”'
EXEC add_BibleVerse @BibleId, 101020008, N'Early in the morning Abimelech summoned all his servants. When he told them about all these things, they were terrified.'
EXEC add_BibleVerse @BibleId, 101020009, N'Abimelech summoned Abraham and said to him, “What have you done to us? What sin did I commit against you that would cause you to bring such great guilt on me and my kingdom? You have done things to me that should not be done!”'
EXEC add_BibleVerse @BibleId, 101020010, N'Then Abimelech asked Abraham, “What prompted you to do this thing?”'
EXEC add_BibleVerse @BibleId, 101020011, N'Abraham replied, “Because I thought, ‘Surely no one fears God in this place. They will kill me because of my wife.’'
EXEC add_BibleVerse @BibleId, 101020012, N'What’s more, she is indeed my sister, my father’s daughter, but not my mother’s daughter. She became my wife.'
EXEC add_BibleVerse @BibleId, 101020013, N'When God made me wander from my father’s house, I told her, ‘This is what you can do to show your loyalty to me: Every place we go, say about me, “He is my brother.”’”'
EXEC add_BibleVerse @BibleId, 101020014, N'So Abimelech gave sheep, cattle, and male and female servants to Abraham. He also gave his wife Sarah back to him.'
EXEC add_BibleVerse @BibleId, 101020015, N'Then Abimelech said, “Look, my land is before you; live wherever you please.”'
EXEC add_BibleVerse @BibleId, 101020016, N'To Sarah he said, “Look, I have given a thousand pieces of silver to your ‘brother.’ This is compensation for you so that you will stand vindicated before all who are with you.”'
EXEC add_BibleVerse @BibleId, 101020017, N'Abraham prayed to God, and God healed Abimelech, as well as his wife and female slaves so that they were able to have children.'
EXEC add_BibleVerse @BibleId, 101020018, N'For the Lord had caused infertility to strike every woman in the household of Abimelech because he took Sarah, Abraham’s wife.'
EXEC add_BibleVerse @BibleId, 101021001, N'The Lord visited Sarah just as he had said he would and did for Sarah what he had promised.'
EXEC add_BibleVerse @BibleId, 101021002, N'So Sarah became pregnant and bore Abraham a son in his old age at the appointed time that God had told him.'
EXEC add_BibleVerse @BibleId, 101021003, N'Abraham named his son – whom Sarah bore to him – Isaac.'
EXEC add_BibleVerse @BibleId, 101021004, N'When his son Isaac was eight days old, Abraham circumcised him just as God had commanded him to do.'
EXEC add_BibleVerse @BibleId, 101021005, N'(Now Abraham was a hundred years old when his son Isaac was born to him.)'
EXEC add_BibleVerse @BibleId, 101021006, N'Sarah said, “God has made me laugh. Everyone who hears about this will laugh with me.”'
EXEC add_BibleVerse @BibleId, 101021007, N'She went on to say, “Who would have said to Abraham that Sarah would nurse children? Yet I have given birth to a son for him in his old age!”'
EXEC add_BibleVerse @BibleId, 101021008, N'The child grew and was weaned. Abraham prepared a great feast on the day that Isaac was weaned.'
EXEC add_BibleVerse @BibleId, 101021009, N'But Sarah noticed the son of Hagar the Egyptian – the son whom Hagar had borne to Abraham – mocking.'
EXEC add_BibleVerse @BibleId, 101021010, N'So she said to Abraham, “Banish that slave woman and her son, for the son of that slave woman will not be an heir along with my son Isaac!”'
EXEC add_BibleVerse @BibleId, 101021011, N'Sarah’s demand displeased Abraham greatly because Ishmael was his son.'
EXEC add_BibleVerse @BibleId, 101021012, N'But God said to Abraham, “Do not be upset about the boy or your slave wife. Do all that Sarah is telling you because through Isaac your descendants will be counted.'
EXEC add_BibleVerse @BibleId, 101021013, N'But I will also make the son of the slave wife into a great nation, for he is your descendant too.”'
EXEC add_BibleVerse @BibleId, 101021014, N'Early in the morning Abraham took some food and a skin of water and gave them to Hagar. He put them on her shoulders, gave her the child, and sent her away. So she went wandering aimlessly through the wilderness of Beer Sheba.'
EXEC add_BibleVerse @BibleId, 101021015, N'When the water in the skin was gone, she shoved the child under one of the shrubs.'
EXEC add_BibleVerse @BibleId, 101021016, N'Then she went and sat down by herself across from him at quite a distance, about a bowshot away; for she thought, “I refuse to watch the child die.” So she sat across from him and wept uncontrollably.'
EXEC add_BibleVerse @BibleId, 101021017, N'But God heard the boy’s voice. The angel of God called to Hagar from heaven and asked her, “What is the matter, Hagar? Don’t be afraid, for God has heard the boy’s voice right where he is crying.'
EXEC add_BibleVerse @BibleId, 101021018, N'Get up! Help the boy up and hold him by the hand, for I will make him into a great nation.”'
EXEC add_BibleVerse @BibleId, 101021019, N'Then God enabled Hagar to see a well of water. She went over and filled the skin with water, and then gave the boy a drink.'
EXEC add_BibleVerse @BibleId, 101021020, N'God was with the boy as he grew. He lived in the wilderness and became an archer.'
EXEC add_BibleVerse @BibleId, 101021021, N'He lived in the wilderness of Paran. His mother found a wife for him from the land of Egypt.'
EXEC add_BibleVerse @BibleId, 101021022, N'At that time Abimelech and Phicol, the commander of his army, said to Abraham, “God is with you in all that you do.'
EXEC add_BibleVerse @BibleId, 101021023, N'Now swear to me right here in God’s name that you will not deceive me, my children, or my descendants. Show me, and the land where you are staying, the same loyalty that I have shown you.”'
EXEC add_BibleVerse @BibleId, 101021024, N'Abraham said, “I swear to do this.”'
EXEC add_BibleVerse @BibleId, 101021025, N'But Abraham lodged a complaint against Abimelech concerning a well that Abimelech’s servants had seized.'
EXEC add_BibleVerse @BibleId, 101021026, N'“I do not know who has done this thing,” Abimelech replied. “Moreover, you did not tell me. I did not hear about it until today.”'
EXEC add_BibleVerse @BibleId, 101021027, N'Abraham took some sheep and cattle and gave them to Abimelech. The two of them made a treaty.'
EXEC add_BibleVerse @BibleId, 101021028, N'Then Abraham set seven ewe lambs apart from the flock by themselves.'
EXEC add_BibleVerse @BibleId, 101021029, N'Abimelech asked Abraham, “What is the meaning of these seven ewe lambs that you have set apart?”'
EXEC add_BibleVerse @BibleId, 101021030, N'He replied, “You must take these seven ewe lambs from my hand as legal proof that I dug this well.”'
EXEC add_BibleVerse @BibleId, 101021031, N'That is why he named that place Beer Sheba, because the two of them swore an oath there.'
EXEC add_BibleVerse @BibleId, 101021032, N'So they made a treaty at Beer Sheba. Then Abimelech and Phicol, the commander of his army, returned to the land of the Philistines.'
EXEC add_BibleVerse @BibleId, 101021033, N'Abraham planted a tamarisk tree in Beer Sheba. There he worshiped the Lord, the eternal God.'
EXEC add_BibleVerse @BibleId, 101021034, N'So Abraham stayed in the land of the Philistines for quite some time.'
EXEC add_BibleVerse @BibleId, 101022001, N'Some time after these things God tested Abraham. He said to him, “Abraham!” “Here I am!” Abraham replied.'
EXEC add_BibleVerse @BibleId, 101022002, N'God said, “Take your son – your only son, whom you love, Isaac – and go to the land of Moriah! Offer him up there as a burnt offering on one of the mountains which I will indicate to you.”'
EXEC add_BibleVerse @BibleId, 101022003, N'Early in the morning Abraham got up and saddled his donkey. He took two of his young servants with him, along with his son Isaac. When he had cut the wood for the burnt offering, he started out for the place God had spoken to him about.'
EXEC add_BibleVerse @BibleId, 101022004, N'On the third day Abraham caught sight of the place in the distance.'
EXEC add_BibleVerse @BibleId, 101022005, N'So he said to his servants, “You two stay here with the donkey while the boy and I go up there. We will worship and then return to you.”'
EXEC add_BibleVerse @BibleId, 101022006, N'Abraham took the wood for the burnt offering and put it on his son Isaac. Then he took the fire and the knife in his hand, and the two of them walked on together.'
EXEC add_BibleVerse @BibleId, 101022007, N'Isaac said to his father Abraham, “My father?” “What is it, my son?” he replied. “Here is the fire and the wood,” Isaac said, “but where is the lamb for the burnt offering?”'
EXEC add_BibleVerse @BibleId, 101022008, N'“God will provide for himself the lamb for the burnt offering, my son,” Abraham replied. The two of them continued on together.'
EXEC add_BibleVerse @BibleId, 101022009, N'When they came to the place God had told him about, Abraham built the altar there and arranged the wood on it. Next he tied up his son Isaac and placed him on the altar on top of the wood.'
EXEC add_BibleVerse @BibleId, 101022010, N'Then Abraham reached out his hand, took the knife, and prepared to slaughter his son.'
EXEC add_BibleVerse @BibleId, 101022011, N'But the Lord’s angel called to him from heaven, “Abraham! Abraham!” “Here I am!” he answered.'
EXEC add_BibleVerse @BibleId, 101022012, N'“Do not harm the boy!” the angel said. “Do not do anything to him, for now I know that you fear God because you did not withhold your son, your only son, from me.”'
EXEC add_BibleVerse @BibleId, 101022013, N'Abraham looked up and saw behind him a ram caught in the bushes by its horns. So he went over and got the ram and offered it up as a burnt offering instead of his son.'
EXEC add_BibleVerse @BibleId, 101022014, N'And Abraham called the name of that place “The Lord provides.” It is said to this day, “In the mountain of the Lord provision will be made.”'
EXEC add_BibleVerse @BibleId, 101022015, N'The Lord’s angel called to Abraham a second time from heaven'
EXEC add_BibleVerse @BibleId, 101022016, N'and said, “‘I solemnly swear by my own name,’ decrees the Lord, ‘that because you have done this and have not withheld your son, your only son,'
EXEC add_BibleVerse @BibleId, 101022017, N'I will indeed bless you, and I will greatly multiply your descendants so that they will be as countless as the stars in the sky or the grains of sand on the seashore. Your descendants will take possession of the strongholds of their enemies.'
EXEC add_BibleVerse @BibleId, 101022018, N'Because you have obeyed me, all the nations of the earth will pronounce blessings on one another using the name of your descendants.’”'
EXEC add_BibleVerse @BibleId, 101022019, N'Then Abraham returned to his servants, and they set out together for Beer Sheba where Abraham stayed.'
EXEC add_BibleVerse @BibleId, 101022020, N'After these things Abraham was told, “Milcah also has borne children to your brother Nahor –'
EXEC add_BibleVerse @BibleId, 101022021, N'Uz the firstborn, his brother Buz, Kemuel (the father of Aram),'
EXEC add_BibleVerse @BibleId, 101022022, N'Kesed, Hazo, Pildash, Jidlaph, and Bethuel.”'
EXEC add_BibleVerse @BibleId, 101022023, N'(Now Bethuel became the father of Rebekah.) These were the eight sons Milcah bore to Abraham’s brother Nahor.'
EXEC add_BibleVerse @BibleId, 101022024, N'His concubine, whose name was Reumah, also bore him children – Tebah, Gaham, Tahash, and Maacah.'
EXEC add_BibleVerse @BibleId, 101023001, N'Sarah lived 127 years.'
EXEC add_BibleVerse @BibleId, 101023002, N'Then she died in Kiriath Arba (that is, Hebron) in the land of Canaan. Abraham went to mourn for Sarah and to weep for her.'
EXEC add_BibleVerse @BibleId, 101023003, N'Then Abraham got up from mourning his dead wife and said to the sons of Heth,'
EXEC add_BibleVerse @BibleId, 101023004, N'“I am a temporary settler among you. Grant me ownership of a burial site among you so that I may bury my dead.”'
EXEC add_BibleVerse @BibleId, 101023005, N'The sons of Heth answered Abraham,'
EXEC add_BibleVerse @BibleId, 101023006, N'“Listen, sir, you are a mighty prince among us! You may bury your dead in the choicest of our tombs. None of us will refuse you his tomb to prevent you from burying your dead.”'
EXEC add_BibleVerse @BibleId, 101023007, N'Abraham got up and bowed down to the local people, the sons of Heth.'
EXEC add_BibleVerse @BibleId, 101023008, N'Then he said to them, “If you agree that I may bury my dead, then hear me out. Ask Ephron the son of Zohar'
EXEC add_BibleVerse @BibleId, 101023009, N'if he will sell me the cave of Machpelah that belongs to him; it is at the end of his field. Let him sell it to me publicly for the full price, so that I may own it as a burial site.”'
EXEC add_BibleVerse @BibleId, 101023010, N'(Now Ephron was sitting among the sons of Heth.) Ephron the Hethite replied to Abraham in the hearing of the sons of Heth – before all who entered the gate of his city –'
EXEC add_BibleVerse @BibleId, 101023011, N'“No, my lord! Hear me out. I sell you both the field and the cave that is in it. In the presence of my people I sell it to you. Bury your dead.”'
EXEC add_BibleVerse @BibleId, 101023012, N'Abraham bowed before the local people'
EXEC add_BibleVerse @BibleId, 101023013, N'and said to Ephron in their hearing, “Hear me, if you will. I pay to you the price of the field. Take it from me so that I may bury my dead there.”'
EXEC add_BibleVerse @BibleId, 101023014, N'Ephron answered Abraham, saying to him,'
EXEC add_BibleVerse @BibleId, 101023015, N'“Hear me, my lord. The land is worth 400 pieces of silver, but what is that between me and you? So bury your dead.”'
EXEC add_BibleVerse @BibleId, 101023016, N'So Abraham agreed to Ephron’s price and weighed out for him the price that Ephron had quoted in the hearing of the sons of Heth – 400 pieces of silver, according to the standard measurement at the time.'
EXEC add_BibleVerse @BibleId, 101023017, N'So Abraham secured Ephron’s field in Machpelah, next to Mamre, including the field, the cave that was in it, and all the trees that were in the field and all around its border,'
EXEC add_BibleVerse @BibleId, 101023018, N'as his property in the presence of the sons of Heth before all who entered the gate of Ephron’s city.'
EXEC add_BibleVerse @BibleId, 101023019, N'After this Abraham buried his wife Sarah in the cave in the field of Machpelah next to Mamre (that is, Hebron) in the land of Canaan.'
EXEC add_BibleVerse @BibleId, 101023020, N'So Abraham secured the field and the cave that was in it as a burial site from the sons of Heth.'
EXEC add_BibleVerse @BibleId, 101024001, N'Now Abraham was old, well advanced in years, and the Lord had blessed him in everything.'
EXEC add_BibleVerse @BibleId, 101024002, N'Abraham said to his servant, the senior one in his household who was in charge of everything he had, “Put your hand under my thigh'
EXEC add_BibleVerse @BibleId, 101024003, N'so that I may make you solemnly promise by the Lord, the God of heaven and the God of the earth: You must not acquire a wife for my son from the daughters of the Canaanites, among whom I am living.'
EXEC add_BibleVerse @BibleId, 101024004, N'You must go instead to my country and to my relatives to find a wife for my son Isaac.”'
EXEC add_BibleVerse @BibleId, 101024005, N'The servant asked him, “What if the woman is not willing to come back with me to this land? Must I then take your son back to the land from which you came?”'
EXEC add_BibleVerse @BibleId, 101024006, N'“Be careful never to take my son back there!” Abraham told him.'
EXEC add_BibleVerse @BibleId, 101024007, N'“The Lord, the God of heaven, who took me from my father’s house and the land of my relatives, promised me with a solemn oath, ‘To your descendants I will give this land.’ He will send his angel before you so that you may find a wife for my son from there.'
EXEC add_BibleVerse @BibleId, 101024008, N'But if the woman is not willing to come back with you, you will be free from this oath of mine. But you must not take my son back there!”'
EXEC add_BibleVerse @BibleId, 101024009, N'So the servant placed his hand under the thigh of his master Abraham and gave his solemn promise he would carry out his wishes.'
EXEC add_BibleVerse @BibleId, 101024010, N'Then the servant took ten of his master’s camels and departed with all kinds of gifts from his master at his disposal. He journeyed to the region of Aram Naharaim and the city of Nahor.'
EXEC add_BibleVerse @BibleId, 101024011, N'He made the camels kneel down by the well outside the city. It was evening, the time when the women would go out to draw water.'
EXEC add_BibleVerse @BibleId, 101024012, N'He prayed, “O Lord, God of my master Abraham, guide me today. Be faithful to my master Abraham.'
EXEC add_BibleVerse @BibleId, 101024013, N'Here I am, standing by the spring, and the daughters of the people who live in the town are coming out to draw water.'
EXEC add_BibleVerse @BibleId, 101024014, N'I will say to a young woman, ‘Please lower your jar so I may drink.’ May the one you have chosen for your servant Isaac reply, ‘Drink, and I’ll give your camels water too.’ In this way I will know that you have been faithful to my master.”'
EXEC add_BibleVerse @BibleId, 101024015, N'Before he had finished praying, there came Rebekah with her water jug on her shoulder. She was the daughter of Bethuel son of Milcah (Milcah was the wife of Abraham’s brother Nahor).'
EXEC add_BibleVerse @BibleId, 101024016, N'Now the young woman was very beautiful. She was a virgin; no man had ever had sexual relations with her. She went down to the spring, filled her jug, and came back up.'
EXEC add_BibleVerse @BibleId, 101024017, N'Abraham’s servant ran to meet her and said, “Please give me a sip of water from your jug.”'
EXEC add_BibleVerse @BibleId, 101024018, N'“Drink, my lord,” she replied, and quickly lowering her jug to her hands, she gave him a drink.'
EXEC add_BibleVerse @BibleId, 101024019, N'When she had done so, she said, “I’ll draw water for your camels too, until they have drunk as much as they want.”'
EXEC add_BibleVerse @BibleId, 101024020, N'She quickly emptied her jug into the watering trough and ran back to the well to draw more water until she had drawn enough for all his camels.'
EXEC add_BibleVerse @BibleId, 101024021, N'Silently the man watched her with interest to determine if the Lord had made his journey successful or not.'
EXEC add_BibleVerse @BibleId, 101024022, N'After the camels had finished drinking, the man took out a gold nose ring weighing a beka and two gold bracelets weighing ten shekels and gave them to her.'
EXEC add_BibleVerse @BibleId, 101024023, N'“Whose daughter are you?” he asked. “Tell me, is there room in your father’s house for us to spend the night?”'
EXEC add_BibleVerse @BibleId, 101024024, N'She said to him, “I am the daughter of Bethuel the son of Milcah, whom Milcah bore to Nahor.'
EXEC add_BibleVerse @BibleId, 101024025, N'We have plenty of straw and feed,” she added, “and room for you to spend the night.”'
EXEC add_BibleVerse @BibleId, 101024026, N'The man bowed his head and worshiped the Lord,'
EXEC add_BibleVerse @BibleId, 101024027, N'saying “Praised be the Lord, the God of my master Abraham, who has not abandoned his faithful love for my master! The Lord has led me to the house of my master’s relatives!”'
EXEC add_BibleVerse @BibleId, 101024028, N'The young woman ran and told her mother’s household all about these things.'
EXEC add_BibleVerse @BibleId, 101024029, N'(Now Rebekah had a brother named Laban.) Laban rushed out to meet the man at the spring.'
EXEC add_BibleVerse @BibleId, 101024030, N'When he saw the bracelets on his sister’s wrists and the nose ring and heard his sister Rebekah say, “This is what the man said to me,” he went out to meet the man. There he was, standing by the camels near the spring.'
EXEC add_BibleVerse @BibleId, 101024031, N'Laban said to him, “Come, you who are blessed by the Lord! Why are you standing out here when I have prepared the house and a place for the camels?”'
EXEC add_BibleVerse @BibleId, 101024032, N'So Abraham’s servant went to the house and unloaded the camels. Straw and feed were given to the camels, and water was provided so that he and the men who were with him could wash their feet.'
EXEC add_BibleVerse @BibleId, 101024033, N'When food was served, he said, “I will not eat until I have said what I want to say.” “Tell us,” Laban said.'
EXEC add_BibleVerse @BibleId, 101024034, N'“I am the servant of Abraham,” he began.'
EXEC add_BibleVerse @BibleId, 101024035, N'“The Lord has richly blessed my master and he has become very wealthy. The Lord has given him sheep and cattle, silver and gold, male and female servants, and camels and donkeys.'
EXEC add_BibleVerse @BibleId, 101024036, N'My master’s wife Sarah bore a son to him when she was old, and my master has given him everything he owns.'
EXEC add_BibleVerse @BibleId, 101024037, N'My master made me swear an oath. He said, ‘You must not acquire a wife for my son from the daughters of the Canaanites, among whom I am living,'
EXEC add_BibleVerse @BibleId, 101024038, N'but you must go to the family of my father and to my relatives to find a wife for my son.’'
EXEC add_BibleVerse @BibleId, 101024039, N'But I said to my master, ‘What if the woman does not want to go with me?’'
EXEC add_BibleVerse @BibleId, 101024040, N'He answered, ‘The Lord, before whom I have walked, will send his angel with you. He will make your journey a success and you will find a wife for my son from among my relatives, from my father’s family.'
EXEC add_BibleVerse @BibleId, 101024041, N'You will be free from your oath if you go to my relatives and they will not give her to you. Then you will be free from your oath.’'
EXEC add_BibleVerse @BibleId, 101024042, N'When I came to the spring today, I prayed, ‘O Lord, God of my master Abraham, if you have decided to make my journey successful, may events unfold as follows:'
EXEC add_BibleVerse @BibleId, 101024043, N'Here I am, standing by the spring. When the young woman goes out to draw water, I’ll say, “Give me a little water to drink from your jug.”'
EXEC add_BibleVerse @BibleId, 101024044, N'Then she will reply to me, “Drink, and I’ll draw water for your camels too.” May that woman be the one whom the Lord has chosen for my master’s son.’'
EXEC add_BibleVerse @BibleId, 101024045, N'“Before I finished praying in my heart, along came Rebekah with her water jug on her shoulder! She went down to the spring and drew water. So I said to her, ‘Please give me a drink.’'
EXEC add_BibleVerse @BibleId, 101024046, N'She quickly lowered her jug from her shoulder and said, ‘Drink, and I’ll give your camels water too.’ So I drank, and she also gave the camels water.'
EXEC add_BibleVerse @BibleId, 101024047, N'Then I asked her, ‘Whose daughter are you?’ She replied, ‘The daughter of Bethuel the son of Nahor, whom Milcah bore to Nahor.’ I put the ring in her nose and the bracelets on her wrists.'
EXEC add_BibleVerse @BibleId, 101024048, N'Then I bowed down and worshiped the Lord. I praised the Lord, the God of my master Abraham, who had led me on the right path to find the granddaughter of my master’s brother for his son.'
EXEC add_BibleVerse @BibleId, 101024049, N'Now, if you will show faithful love to my master, tell me. But if not, tell me as well, so that I may go on my way.”'
EXEC add_BibleVerse @BibleId, 101024050, N'Then Laban and Bethuel replied, “This is the Lord’s doing. Our wishes are of no concern.'
EXEC add_BibleVerse @BibleId, 101024051, N'Rebekah stands here before you. Take her and go so that she may become the wife of your master’s son, just as the Lord has decided.”'
EXEC add_BibleVerse @BibleId, 101024052, N'When Abraham’s servant heard their words, he bowed down to the ground before the Lord.'
EXEC add_BibleVerse @BibleId, 101024053, N'Then he brought out gold, silver jewelry, and clothing and gave them to Rebekah. He also gave valuable gifts to her brother and to her mother.'
EXEC add_BibleVerse @BibleId, 101024054, N'After this, he and the men who were with him ate a meal and stayed there overnight. When they got up in the morning, he said, “Let me leave now so I can return to my master.”'
EXEC add_BibleVerse @BibleId, 101024055, N'But Rebekah’s brother and her mother replied, “Let the girl stay with us a few more days, perhaps ten. Then she can go.”'
EXEC add_BibleVerse @BibleId, 101024056, N'But he said to them, “Don’t detain me – the Lord has granted me success on my journey. Let me leave now so I may return to my master.”'
EXEC add_BibleVerse @BibleId, 101024057, N'Then they said, “We’ll call the girl and find out what she wants to do.”'
EXEC add_BibleVerse @BibleId, 101024058, N'So they called Rebekah and asked her, “Do you want to go with this man?” She replied, “I want to go.”'
EXEC add_BibleVerse @BibleId, 101024059, N'So they sent their sister Rebekah on her way, accompanied by her female attendant, with Abraham’s servant and his men.'
EXEC add_BibleVerse @BibleId, 101024060, N'They blessed Rebekah with these words: “Our sister, may you become the mother of thousands of ten thousands! May your descendants possess the strongholds of their enemies.”'
EXEC add_BibleVerse @BibleId, 101024061, N'Then Rebekah and her female servants mounted the camels and rode away with the man. So Abraham’s servant took Rebekah and left.'
EXEC add_BibleVerse @BibleId, 101024062, N'Now Isaac came from Beer Lahai Roi, for he was living in the Negev.'
EXEC add_BibleVerse @BibleId, 101024063, N'He went out to relax in the field in the early evening. Then he looked up and saw that there were camels approaching.'
EXEC add_BibleVerse @BibleId, 101024064, N'Rebekah looked up and saw Isaac. She got down from her camel'
EXEC add_BibleVerse @BibleId, 101024065, N'and asked Abraham’s servant, “Who is that man walking in the field toward us?” “That is my master,” the servant replied. So she took her veil and covered herself.'
EXEC add_BibleVerse @BibleId, 101024066, N'The servant told Isaac everything that had happened.'
EXEC add_BibleVerse @BibleId, 101024067, N'Then Isaac brought Rebekah into his mother Sarah’s tent. He took her as his wife and loved her. So Isaac was comforted after his mother’s death.'
EXEC add_BibleVerse @BibleId, 101025001, N'Abraham had taken another wife, named Keturah.'
EXEC add_BibleVerse @BibleId, 101025002, N'She bore him Zimran, Jokshan, Medan, Midian, Ishbak, and Shuah.'
EXEC add_BibleVerse @BibleId, 101025003, N'Jokshan became the father of Sheba and Dedan. The descendants of Dedan were the Asshurites, Letushites, and Leummites.'
EXEC add_BibleVerse @BibleId, 101025004, N'The sons of Midian were Ephah, Epher, Hanoch, Abida, and Eldaah. All these were descendants of Keturah.'
EXEC add_BibleVerse @BibleId, 101025005, N'Everything he owned Abraham left to his son Isaac.'
EXEC add_BibleVerse @BibleId, 101025006, N'But while he was still alive, Abraham gave gifts to the sons of his concubines and sent them off to the east, away from his son Isaac.'
EXEC add_BibleVerse @BibleId, 101025007, N'Abraham lived a total of 175 years.'
EXEC add_BibleVerse @BibleId, 101025008, N'Then Abraham breathed his last and died at a good old age, an old man who had lived a full life. He joined his ancestors.'
EXEC add_BibleVerse @BibleId, 101025009, N'His sons Isaac and Ishmael buried him in the cave of Machpelah near Mamre, in the field of Ephron the son of Zohar, the Hethite.'
EXEC add_BibleVerse @BibleId, 101025010, N'This was the field Abraham had purchased from the sons of Heth. There Abraham was buried with his wife Sarah.'
EXEC add_BibleVerse @BibleId, 101025011, N'After Abraham’s death, God blessed his son Isaac. Isaac lived near Beer Lahai Roi.'
EXEC add_BibleVerse @BibleId, 101025012, N'This is the account of Abraham’s son Ishmael, whom Hagar the Egyptian, Sarah’s servant, bore to Abraham.'
EXEC add_BibleVerse @BibleId, 101025013, N'These are the names of Ishmael’s sons, by their names according to their records: Nebaioth (Ishmael’s firstborn), Kedar, Adbeel, Mibsam,'
EXEC add_BibleVerse @BibleId, 101025014, N'Mishma, Dumah, Massa,'
EXEC add_BibleVerse @BibleId, 101025015, N'Hadad, Tema, Jetur, Naphish, and Kedemah.'
EXEC add_BibleVerse @BibleId, 101025016, N'These are the sons of Ishmael, and these are their names by their settlements and their camps – twelve princes according to their clans.'
EXEC add_BibleVerse @BibleId, 101025017, N'Ishmael lived a total of 137 years. He breathed his last and died; then he joined his ancestors.'
EXEC add_BibleVerse @BibleId, 101025018, N'His descendants settled from Havilah to Shur, which runs next to Egypt all the way to Asshur. They settled away from all their relatives.'
EXEC add_BibleVerse @BibleId, 101025019, N'This is the account of Isaac, the son of Abraham. Abraham became the father of Isaac.'
EXEC add_BibleVerse @BibleId, 101025020, N'When Isaac was forty years old, he married Rebekah, the daughter of Bethuel the Aramean from Paddan Aram and sister of Laban the Aramean.'
EXEC add_BibleVerse @BibleId, 101025021, N'Isaac prayed to the Lord on behalf of his wife because she was childless. The Lord answered his prayer, and his wife Rebekah became pregnant.'
EXEC add_BibleVerse @BibleId, 101025022, N'But the children struggled inside her, and she said, “If it is going to be like this, I’m not so sure I want to be pregnant!” So she asked the Lord,'
EXEC add_BibleVerse @BibleId, 101025023, N'and the Lord said to her, “Two nations are in your womb, and two peoples will be separated from within you. One people will be stronger than the other, and the older will serve the younger.”'
EXEC add_BibleVerse @BibleId, 101025024, N'When the time came for Rebekah to give birth, there were twins in her womb.'
EXEC add_BibleVerse @BibleId, 101025025, N'The first came out reddish all over, like a hairy garment, so they named him Esau.'
EXEC add_BibleVerse @BibleId, 101025026, N'When his brother came out with his hand clutching Esau’s heel, they named him Jacob. Isaac was sixty years old when they were born.'
EXEC add_BibleVerse @BibleId, 101025027, N'When the boys grew up, Esau became a skilled hunter, a man of the open fields, but Jacob was an even-tempered man, living in tents.'
EXEC add_BibleVerse @BibleId, 101025028, N'Isaac loved Esau because he had a taste for fresh game, but Rebekah loved Jacob.'
EXEC add_BibleVerse @BibleId, 101025029, N'Now Jacob cooked some stew, and when Esau came in from the open fields, he was famished.'
EXEC add_BibleVerse @BibleId, 101025030, N'So Esau said to Jacob, “Feed me some of the red stuff – yes, this red stuff – because I’m starving!” (That is why he was also called Edom.)'
EXEC add_BibleVerse @BibleId, 101025031, N'But Jacob replied, “First sell me your birthright.”'
EXEC add_BibleVerse @BibleId, 101025032, N'“Look,” said Esau, “I’m about to die! What use is the birthright to me?”'
EXEC add_BibleVerse @BibleId, 101025033, N'But Jacob said, “Swear an oath to me now.” So Esau swore an oath to him and sold his birthright to Jacob.'
EXEC add_BibleVerse @BibleId, 101025034, N'Then Jacob gave Esau some bread and lentil stew; Esau ate and drank, then got up and went out. So Esau despised his birthright.'
EXEC add_BibleVerse @BibleId, 101026001, N'There was a famine in the land, subsequent to the earlier famine that occurred in the days of Abraham. Isaac went to Abimelech king of the Philistines at Gerar.'
EXEC add_BibleVerse @BibleId, 101026002, N'The Lord appeared to Isaac and said, “Do not go down to Egypt; settle down in the land that I will point out to you.'
EXEC add_BibleVerse @BibleId, 101026003, N'Stay in this land. Then I will be with you and will bless you, for I will give all these lands to you and to your descendants, and I will fulfill the solemn promise I made to your father Abraham.'
EXEC add_BibleVerse @BibleId, 101026004, N'I will multiply your descendants so they will be as numerous as the stars in the sky, and I will give them all these lands. All the nations of the earth will pronounce blessings on one another using the name of your descendants.'
EXEC add_BibleVerse @BibleId, 101026005, N'All this will come to pass because Abraham obeyed me and kept my charge, my commandments, my statutes, and my laws.”'
EXEC add_BibleVerse @BibleId, 101026006, N'So Isaac settled in Gerar.'
EXEC add_BibleVerse @BibleId, 101026007, N'When the men of that place asked him about his wife, he replied, “She is my sister.” He was afraid to say, “She is my wife,” for he thought to himself, “The men of this place will kill me to get Rebekah because she is very beautiful.”'
EXEC add_BibleVerse @BibleId, 101026008, N'After Isaac had been there a long time, Abimelech king of the Philistines happened to look out a window and observed Isaac caressing his wife Rebekah.'
EXEC add_BibleVerse @BibleId, 101026009, N'So Abimelech summoned Isaac and said, “She is really your wife! Why did you say, ‘She is my sister’?” Isaac replied, “Because I thought someone might kill me to get her.”'
EXEC add_BibleVerse @BibleId, 101026010, N'Then Abimelech exclaimed, “What in the world have you done to us? One of the men might easily have had sexual relations with your wife, and you would have brought guilt on us!”'
EXEC add_BibleVerse @BibleId, 101026011, N'So Abimelech commanded all the people, “Whoever touches this man or his wife will surely be put to death.”'
EXEC add_BibleVerse @BibleId, 101026012, N'When Isaac planted in that land, he reaped in the same year a hundred times what he had sown, because the Lord blessed him.'
EXEC add_BibleVerse @BibleId, 101026013, N'The man became wealthy. His influence continued to grow until he became very prominent.'
EXEC add_BibleVerse @BibleId, 101026014, N'He had so many sheep and cattle and such a great household of servants that the Philistines became jealous of him.'
EXEC add_BibleVerse @BibleId, 101026015, N'So the Philistines took dirt and filled up all the wells that his father’s servants had dug back in the days of his father Abraham.'
EXEC add_BibleVerse @BibleId, 101026016, N'Then Abimelech said to Isaac, “Leave us and go elsewhere, for you have become much more powerful than we are.”'
EXEC add_BibleVerse @BibleId, 101026017, N'So Isaac left there and settled in the Gerar Valley.'
EXEC add_BibleVerse @BibleId, 101026018, N'Isaac reopened the wells that had been dug back in the days of his father Abraham, for the Philistines had stopped them up after Abraham died. Isaac gave these wells the same names his father had given them.'
EXEC add_BibleVerse @BibleId, 101026019, N'When Isaac’s servants dug in the valley and discovered a well with fresh flowing water there,'
EXEC add_BibleVerse @BibleId, 101026020, N'the herdsmen of Gerar quarreled with Isaac’s herdsmen, saying, “The water belongs to us!” So Isaac named the well Esek because they argued with him about it.'
EXEC add_BibleVerse @BibleId, 101026021, N'His servants dug another well, but they quarreled over it too, so Isaac named it Sitnah.'
EXEC add_BibleVerse @BibleId, 101026022, N'Then he moved away from there and dug another well. They did not quarrel over it, so Isaac named it Rehoboth, saying, “For now the Lord has made room for us, and we will prosper in the land.”'
EXEC add_BibleVerse @BibleId, 101026023, N'From there Isaac went up to Beer Sheba.'
EXEC add_BibleVerse @BibleId, 101026024, N'The Lord appeared to him that night and said, “I am the God of your father Abraham. Do not be afraid, for I am with you. I will bless you and multiply your descendants for the sake of my servant Abraham.”'
EXEC add_BibleVerse @BibleId, 101026025, N'Then Isaac built an altar there and worshiped the Lord. He pitched his tent there, and his servants dug a well.'
EXEC add_BibleVerse @BibleId, 101026026, N'Now Abimelech had come to him from Gerar along with Ahuzzah his friend and Phicol the commander of his army.'
EXEC add_BibleVerse @BibleId, 101026027, N'Isaac asked them, “Why have you come to me? You hate me and sent me away from you.”'
EXEC add_BibleVerse @BibleId, 101026028, N'They replied, “We could plainly see that the Lord is with you. So we decided there should be a pact between us – between us and you. Allow us to make a treaty with you'
EXEC add_BibleVerse @BibleId, 101026029, N'so that you will not do us any harm, just as we have not harmed you, but have always treated you well before sending you away in peace. Now you are blessed by the Lord.”'
EXEC add_BibleVerse @BibleId, 101026030, N'So Isaac held a feast for them and they celebrated.'
EXEC add_BibleVerse @BibleId, 101026031, N'Early in the morning the men made a treaty with each other. Isaac sent them off; they separated on good terms.'
EXEC add_BibleVerse @BibleId, 101026032, N'That day Isaac’s servants came and told him about the well they had dug. “We’ve found water,” they reported.'
EXEC add_BibleVerse @BibleId, 101026033, N'So he named it Shibah; that is why the name of the city has been Beer Sheba to this day.'
EXEC add_BibleVerse @BibleId, 101026034, N'When Esau was forty years old, he married Judith the daughter of Beeri the Hittite, as well as Basemath the daughter of Elon the Hittite.'
EXEC add_BibleVerse @BibleId, 101026035, N'They caused Isaac and Rebekah great anxiety.'
EXEC add_BibleVerse @BibleId, 101027001, N'When Isaac was old and his eyes were so weak that he was almost blind, he called his older son Esau and said to him, “My son!” “Here I am!” Esau replied.'
EXEC add_BibleVerse @BibleId, 101027002, N'Isaac said, “Since I am so old, I could die at any time.'
EXEC add_BibleVerse @BibleId, 101027003, N'Therefore, take your weapons – your quiver and your bow – and go out into the open fields and hunt down some wild game for me.'
EXEC add_BibleVerse @BibleId, 101027004, N'Then prepare for me some tasty food, the kind I love, and bring it to me. Then I will eat it so that I may bless you before I die.”'
EXEC add_BibleVerse @BibleId, 101027005, N'Now Rebekah had been listening while Isaac spoke to his son Esau. When Esau went out to the open fields to hunt down some wild game and bring it back,'
EXEC add_BibleVerse @BibleId, 101027006, N'Rebekah said to her son Jacob, “Look, I overheard your father tell your brother Esau,'
EXEC add_BibleVerse @BibleId, 101027007, N'‘Bring me some wild game and prepare for me some tasty food. Then I will eat it and bless you in the presence of the Lord before I die.’'
EXEC add_BibleVerse @BibleId, 101027008, N'Now then, my son, do exactly what I tell you!'
EXEC add_BibleVerse @BibleId, 101027009, N'Go to the flock and get me two of the best young goats. I’ll prepare them in a tasty way for your father, just the way he loves them.'
EXEC add_BibleVerse @BibleId, 101027010, N'Then you will take it to your father. Thus he will eat it and bless you before he dies.”'
EXEC add_BibleVerse @BibleId, 101027011, N'“But Esau my brother is a hairy man,” Jacob protested to his mother Rebekah, “and I have smooth skin!'
EXEC add_BibleVerse @BibleId, 101027012, N'My father may touch me! Then he’ll think I’m mocking him and I’ll bring a curse on myself instead of a blessing.”'
EXEC add_BibleVerse @BibleId, 101027013, N'So his mother told him, “Any curse against you will fall on me, my son! Just obey me! Go and get them for me!”'
EXEC add_BibleVerse @BibleId, 101027014, N'So he went and got the goats and brought them to his mother. She prepared some tasty food, just the way his father loved it.'
EXEC add_BibleVerse @BibleId, 101027015, N'Then Rebekah took her older son Esau’s best clothes, which she had with her in the house, and put them on her younger son Jacob.'
EXEC add_BibleVerse @BibleId, 101027016, N'She put the skins of the young goats on his hands and the smooth part of his neck.'
EXEC add_BibleVerse @BibleId, 101027017, N'Then she handed the tasty food and the bread she had made to her son Jacob.'
EXEC add_BibleVerse @BibleId, 101027018, N'He went to his father and said, “My father!” Isaac replied, “Here I am. Which are you, my son?”'
EXEC add_BibleVerse @BibleId, 101027019, N'Jacob said to his father, “I am Esau, your firstborn. I’ve done as you told me. Now sit up and eat some of my wild game so that you can bless me.”'
EXEC add_BibleVerse @BibleId, 101027020, N'But Isaac asked his son, “How in the world did you find it so quickly, my son?” “Because the Lord your God brought it to me,” he replied.'
EXEC add_BibleVerse @BibleId, 101027021, N'Then Isaac said to Jacob, “Come closer so I can touch you, my son, and know for certain if you really are my son Esau.”'
EXEC add_BibleVerse @BibleId, 101027022, N'So Jacob went over to his father Isaac, who felt him and said, “The voice is Jacob’s, but the hands are Esau’s.”'
EXEC add_BibleVerse @BibleId, 101027023, N'He did not recognize him because his hands were hairy, like his brother Esau’s hands. So Isaac blessed Jacob.'
EXEC add_BibleVerse @BibleId, 101027024, N'Then he asked, “Are you really my son Esau?” “I am,” Jacob replied.'
EXEC add_BibleVerse @BibleId, 101027025, N'Isaac said, “Bring some of the wild game for me to eat, my son. Then I will bless you.” So Jacob brought it to him, and he ate it. He also brought him wine, and Isaac drank.'
EXEC add_BibleVerse @BibleId, 101027026, N'Then his father Isaac said to him, “Come here and kiss me, my son.”'
EXEC add_BibleVerse @BibleId, 101027027, N'So Jacob went over and kissed him. When Isaac caught the scent of his clothing, he blessed him, saying, “Yes, my son smells like the scent of an open field which the Lord has blessed.'
EXEC add_BibleVerse @BibleId, 101027028, N'May God give you the dew of the sky and the richness of the earth, and plenty of grain and new wine.'
EXEC add_BibleVerse @BibleId, 101027029, N'May peoples serve you and nations bow down to you. You will be lord over your brothers, and the sons of your mother will bow down to you. May those who curse you be cursed, and those who bless you be blessed.”'
EXEC add_BibleVerse @BibleId, 101027030, N'Isaac had just finished blessing Jacob, and Jacob had scarcely left his father’s presence, when his brother Esau returned from the hunt.'
EXEC add_BibleVerse @BibleId, 101027031, N'He also prepared some tasty food and brought it to his father. Esau said to him, “My father, get up and eat some of your son’s wild game. Then you can bless me.”'
EXEC add_BibleVerse @BibleId, 101027032, N'His father Isaac asked, “Who are you?” “I am your firstborn son,” he replied, “Esau!”'
EXEC add_BibleVerse @BibleId, 101027033, N'Isaac began to shake violently and asked, “Then who else hunted game and brought it to me? I ate all of it just before you arrived, and I blessed him. He will indeed be blessed!”'
EXEC add_BibleVerse @BibleId, 101027034, N'When Esau heard his father’s words, he wailed loudly and bitterly. He said to his father, “Bless me too, my father!”'
EXEC add_BibleVerse @BibleId, 101027035, N'But Isaac replied, “Your brother came in here deceitfully and took away your blessing.”'
EXEC add_BibleVerse @BibleId, 101027036, N'Esau exclaimed, “‘Jacob’ is the right name for him! He has tripped me up two times! He took away my birthright, and now, look, he has taken away my blessing!” Then he asked, “Have you not kept back a blessing for me?”'
EXEC add_BibleVerse @BibleId, 101027037, N'Isaac replied to Esau, “Look! I have made him lord over you. I have made all his relatives his servants and provided him with grain and new wine. What is left that I can do for you, my son?”'
EXEC add_BibleVerse @BibleId, 101027038, N'Esau said to his father, “Do you have only that one blessing, my father? Bless me too!” Then Esau wept loudly.'
EXEC add_BibleVerse @BibleId, 101027039, N'So his father Isaac said to him, “Indeed, your home will be away from the richness of the earth, and away from the dew of the sky above.'
EXEC add_BibleVerse @BibleId, 101027040, N'You will live by your sword but you will serve your brother. When you grow restless, you will tear off his yoke from your neck.”'
EXEC add_BibleVerse @BibleId, 101027041, N'So Esau hated Jacob because of the blessing his father had given to his brother. Esau said privately, “The time of mourning for my father is near; then I will kill my brother Jacob!”'
EXEC add_BibleVerse @BibleId, 101027042, N'When Rebekah heard what her older son Esau had said, she quickly summoned her younger son Jacob and told him, “Look, your brother Esau is planning to get revenge by killing you.'
EXEC add_BibleVerse @BibleId, 101027043, N'Now then, my son, do what I say. Run away immediately to my brother Laban in Haran.'
EXEC add_BibleVerse @BibleId, 101027044, N'Live with him for a little while until your brother’s rage subsides.'
EXEC add_BibleVerse @BibleId, 101027045, N'Stay there until your brother’s anger against you subsides and he forgets what you did to him. Then I’ll send someone to bring you back from there. Why should I lose both of you in one day?”'
EXEC add_BibleVerse @BibleId, 101027046, N'Then Rebekah said to Isaac, “I am deeply depressed because of these daughters of Heth. If Jacob were to marry one of these daughters of Heth who live in this land, I would want to die!”'
EXEC add_BibleVerse @BibleId, 101028001, N'So Isaac called for Jacob and blessed him. Then he commanded him, “You must not marry a Canaanite woman!'
EXEC add_BibleVerse @BibleId, 101028002, N'Leave immediately for Paddan Aram! Go to the house of Bethuel, your mother’s father, and find yourself a wife there, among the daughters of Laban, your mother’s brother.'
EXEC add_BibleVerse @BibleId, 101028003, N'May the sovereign God bless you! May he make you fruitful and give you a multitude of descendants! Then you will become a large nation.'
EXEC add_BibleVerse @BibleId, 101028004, N'May he give you and your descendants the blessing he gave to Abraham so that you may possess the land God gave to Abraham, the land where you have been living as a temporary resident.”'
EXEC add_BibleVerse @BibleId, 101028005, N'So Isaac sent Jacob on his way, and he went to Paddan Aram, to Laban son of Bethuel the Aramean and brother of Rebekah, the mother of Jacob and Esau.'
EXEC add_BibleVerse @BibleId, 101028006, N'Esau saw that Isaac had blessed Jacob and sent him off to Paddan Aram to find a wife there. As he blessed him, Isaac commanded him, “You must not marry a Canaanite woman.”'
EXEC add_BibleVerse @BibleId, 101028007, N'Jacob obeyed his father and mother and left for Paddan Aram.'
EXEC add_BibleVerse @BibleId, 101028008, N'Then Esau realized that the Canaanite women were displeasing to his father Isaac.'
EXEC add_BibleVerse @BibleId, 101028009, N'So Esau went to Ishmael and married Mahalath, the sister of Nebaioth and daughter of Abraham’s son Ishmael, along with the wives he already had.'
EXEC add_BibleVerse @BibleId, 101028010, N'Meanwhile Jacob left Beer Sheba and set out for Haran.'
EXEC add_BibleVerse @BibleId, 101028011, N'He reached a certain place where he decided to camp because the sun had gone down. He took one of the stones and placed it near his head. Then he fell asleep in that place'
EXEC add_BibleVerse @BibleId, 101028012, N'and had a dream. He saw a stairway erected on the earth with its top reaching to the heavens. The angels of God were going up and coming down it'
EXEC add_BibleVerse @BibleId, 101028013, N'and the Lord stood at its top. He said, “I am the Lord, the God of your grandfather Abraham and the God of your father Isaac. I will give you and your descendants the ground you are lying on.'
EXEC add_BibleVerse @BibleId, 101028014, N'Your descendants will be like the dust of the earth, and you will spread out to the west, east, north, and south. All the families of the earth will pronounce blessings on one another using your name and that of your descendants.'
EXEC add_BibleVerse @BibleId, 101028015, N'I am with you! I will protect you wherever you go and will bring you back to this land. I will not leave you until I have done what I promised you!”'
EXEC add_BibleVerse @BibleId, 101028016, N'Then Jacob woke up and thought, “Surely the Lord is in this place, but I did not realize it!”'
EXEC add_BibleVerse @BibleId, 101028017, N'He was afraid and said, “What an awesome place this is! This is nothing else than the house of God! This is the gate of heaven!”'
EXEC add_BibleVerse @BibleId, 101028018, N'Early in the morning Jacob took the stone he had placed near his head and set it up as a sacred stone. Then he poured oil on top of it.'
EXEC add_BibleVerse @BibleId, 101028019, N'He called that place Bethel, although the former name of the town was Luz.'
EXEC add_BibleVerse @BibleId, 101028020, N'Then Jacob made a vow, saying, “If God is with me and protects me on this journey I am taking and gives me food to eat and clothing to wear,'
EXEC add_BibleVerse @BibleId, 101028021, N'and I return safely to my father’s home, then the Lord will become my God.'
EXEC add_BibleVerse @BibleId, 101028022, N'Then this stone that I have set up as a sacred stone will be the house of God, and I will surely give you back a tenth of everything you give me.”'
EXEC add_BibleVerse @BibleId, 101029001, N'So Jacob moved on and came to the land of the eastern people.'
EXEC add_BibleVerse @BibleId, 101029002, N'He saw in the field a well with three flocks of sheep lying beside it, because the flocks were watered from that well. Now a large stone covered the mouth of the well.'
EXEC add_BibleVerse @BibleId, 101029003, N'When all the flocks were gathered there, the shepherds would roll the stone off the mouth of the well and water the sheep. Then they would put the stone back in its place over the well’s mouth.'
EXEC add_BibleVerse @BibleId, 101029004, N'Jacob asked them, “My brothers, where are you from?” They replied, “We’re from Haran.”'
EXEC add_BibleVerse @BibleId, 101029005, N'So he said to them, “Do you know Laban, the grandson of Nahor?” “We know him,” they said.'
EXEC add_BibleVerse @BibleId, 101029006, N'“Is he well?” Jacob asked. They replied, “He is well. Now look, here comes his daughter Rachel with the sheep.”'
EXEC add_BibleVerse @BibleId, 101029007, N'Then Jacob said, “Since it is still the middle of the day, it is not time for the flocks to be gathered. You should water the sheep and then go and let them graze some more.”'
EXEC add_BibleVerse @BibleId, 101029008, N'“We can’t,” they said, “until all the flocks are gathered and the stone is rolled off the mouth of the well. Then we water the sheep.”'
EXEC add_BibleVerse @BibleId, 101029009, N'While he was still speaking with them, Rachel arrived with her father’s sheep, for she was tending them.'
EXEC add_BibleVerse @BibleId, 101029010, N'When Jacob saw Rachel, the daughter of his uncle Laban, and the sheep of his uncle Laban, he went over and rolled the stone off the mouth of the well and watered the sheep of his uncle Laban.'
EXEC add_BibleVerse @BibleId, 101029011, N'Then Jacob kissed Rachel and began to weep loudly.'
EXEC add_BibleVerse @BibleId, 101029012, N'When Jacob explained to Rachel that he was a relative of her father and the son of Rebekah, she ran and told her father.'
EXEC add_BibleVerse @BibleId, 101029013, N'When Laban heard this news about Jacob, his sister’s son, he rushed out to meet him. He embraced him and kissed him and brought him to his house. Jacob told Laban how he was related to him.'
EXEC add_BibleVerse @BibleId, 101029014, N'Then Laban said to him, “You are indeed my own flesh and blood.” So Jacob stayed with him for a month.'
EXEC add_BibleVerse @BibleId, 101029015, N'Then Laban said to Jacob, “Should you work for me for nothing because you are my relative? Tell me what your wages should be.”'
EXEC add_BibleVerse @BibleId, 101029016, N'(Now Laban had two daughters; the older one was named Leah, and the younger one Rachel.'
EXEC add_BibleVerse @BibleId, 101029017, N'Leah’s eyes were tender, but Rachel had a lovely figure and beautiful appearance.)'
EXEC add_BibleVerse @BibleId, 101029018, N'Since Jacob had fallen in love with Rachel, he said, “I’ll serve you seven years in exchange for your younger daughter Rachel.”'
EXEC add_BibleVerse @BibleId, 101029019, N'Laban replied, “I’d rather give her to you than to another man. Stay with me.”'
EXEC add_BibleVerse @BibleId, 101029020, N'So Jacob worked for seven years to acquire Rachel. But they seemed like only a few days to him because his love for her was so great.'
EXEC add_BibleVerse @BibleId, 101029021, N'Finally Jacob said to Laban, “Give me my wife, for my time of service is up. I want to have marital relations with her.”'
EXEC add_BibleVerse @BibleId, 101029022, N'So Laban invited all the people of that place and prepared a feast.'
EXEC add_BibleVerse @BibleId, 101029023, N'In the evening he brought his daughter Leah to Jacob, and Jacob had marital relations with her.'
EXEC add_BibleVerse @BibleId, 101029024, N'(Laban gave his female servant Zilpah to his daughter Leah to be her servant.)'
EXEC add_BibleVerse @BibleId, 101029025, N'In the morning Jacob discovered it was Leah! So Jacob said to Laban, “What in the world have you done to me! Didn’t I work for you in exchange for Rachel? Why have you tricked me?”'
EXEC add_BibleVerse @BibleId, 101029026, N'“It is not our custom here,” Laban replied, “to give the younger daughter in marriage before the firstborn.'
EXEC add_BibleVerse @BibleId, 101029027, N'Complete my older daughter’s bridal week. Then we will give you the younger one too, in exchange for seven more years of work.”'
EXEC add_BibleVerse @BibleId, 101029028, N'Jacob did as Laban said. When Jacob completed Leah’s bridal week, Laban gave him his daughter Rachel to be his wife.'
EXEC add_BibleVerse @BibleId, 101029029, N'(Laban gave his female servant Bilhah to his daughter Rachel to be her servant.)'
EXEC add_BibleVerse @BibleId, 101029030, N'Jacob had marital relations with Rachel as well. He loved Rachel more than Leah, so he worked for Laban for seven more years.'
EXEC add_BibleVerse @BibleId, 101029031, N'When the Lord saw that Leah was unloved, he enabled her to become pregnant while Rachel remained childless.'
EXEC add_BibleVerse @BibleId, 101029032, N'So Leah became pregnant and gave birth to a son. She named him Reuben, for she said, “The Lord has looked with pity on my oppressed condition. Surely my husband will love me now.”'
EXEC add_BibleVerse @BibleId, 101029033, N'She became pregnant again and had another son. She said, “Because the Lord heard that I was unloved, he gave me this one too.” So she named him Simeon.'
EXEC add_BibleVerse @BibleId, 101029034, N'She became pregnant again and had another son. She said, “Now this time my husband will show me affection, because I have given birth to three sons for him.” That is why he was named Levi.'
EXEC add_BibleVerse @BibleId, 101029035, N'She became pregnant again and had another son. She said, “This time I will praise the Lord.” That is why she named him Judah. Then she stopped having children.'
EXEC add_BibleVerse @BibleId, 101030001, N'When Rachel saw that she could not give Jacob children, she became jealous of her sister. She said to Jacob, “Give me children or I’ll die!”'
EXEC add_BibleVerse @BibleId, 101030002, N'Jacob became furious with Rachel and exclaimed, “Am I in the place of God, who has kept you from having children?”'
EXEC add_BibleVerse @BibleId, 101030003, N'She replied, “Here is my servant Bilhah! Have sexual relations with her so that she can bear children for me and I can have a family through her.”'
EXEC add_BibleVerse @BibleId, 101030004, N'So Rachel gave him her servant Bilhah as a wife, and Jacob had marital relations with her.'
EXEC add_BibleVerse @BibleId, 101030005, N'Bilhah became pregnant and gave Jacob a son.'
EXEC add_BibleVerse @BibleId, 101030006, N'Then Rachel said, “God has vindicated me. He has responded to my prayer and given me a son.” That is why she named him Dan.'
EXEC add_BibleVerse @BibleId, 101030007, N'Bilhah, Rachel’s servant, became pregnant again and gave Jacob another son.'
EXEC add_BibleVerse @BibleId, 101030008, N'Then Rachel said, “I have fought a desperate struggle with my sister, but I have won.” So she named him Naphtali.'
EXEC add_BibleVerse @BibleId, 101030009, N'When Leah saw that she had stopped having children, she gave her servant Zilpah to Jacob as a wife.'
EXEC add_BibleVerse @BibleId, 101030010, N'Soon Leah’s servant Zilpah gave Jacob a son.'
EXEC add_BibleVerse @BibleId, 101030011, N'Leah said, “How fortunate!” So she named him Gad.'
EXEC add_BibleVerse @BibleId, 101030012, N'Then Leah’s servant Zilpah gave Jacob another son.'
EXEC add_BibleVerse @BibleId, 101030013, N'Leah said, “How happy I am, for women will call me happy!” So she named him Asher.'
EXEC add_BibleVerse @BibleId, 101030014, N'At the time of the wheat harvest Reuben went out and found some mandrake plants in a field and brought them to his mother Leah. Rachel said to Leah, “Give me some of your son’s mandrakes.”'
EXEC add_BibleVerse @BibleId, 101030015, N'But Leah replied, “Wasn’t it enough that you’ve taken away my husband? Would you take away my son’s mandrakes too?” “All right,” Rachel said, “he may sleep with you tonight in exchange for your son’s mandrakes.”'
EXEC add_BibleVerse @BibleId, 101030016, N'When Jacob came in from the fields that evening, Leah went out to meet him and said, “You must sleep with me because I have paid for your services with my son’s mandrakes.” So he had marital relations with her that night.'
EXEC add_BibleVerse @BibleId, 101030017, N'God paid attention to Leah; she became pregnant and gave Jacob a son for the fifth time.'
EXEC add_BibleVerse @BibleId, 101030018, N'Then Leah said, “God has granted me a reward because I gave my servant to my husband as a wife.” So she named him Issachar.'
EXEC add_BibleVerse @BibleId, 101030019, N'Leah became pregnant again and gave Jacob a son for the sixth time.'
EXEC add_BibleVerse @BibleId, 101030020, N'Then Leah said, “God has given me a good gift. Now my husband will honor me because I have given him six sons.” So she named him Zebulun.'
EXEC add_BibleVerse @BibleId, 101030021, N'After that she gave birth to a daughter and named her Dinah.'
EXEC add_BibleVerse @BibleId, 101030022, N'Then God took note of Rachel. He paid attention to her and enabled her to become pregnant.'
EXEC add_BibleVerse @BibleId, 101030023, N'She became pregnant and gave birth to a son. Then she said, “God has taken away my shame.”'
EXEC add_BibleVerse @BibleId, 101030024, N'She named him Joseph, saying, “May the Lord give me yet another son.”'
EXEC add_BibleVerse @BibleId, 101030025, N'After Rachel had given birth to Joseph, Jacob said to Laban, “Send me on my way so that I can go home to my own country.'
EXEC add_BibleVerse @BibleId, 101030026, N'Let me take my wives and my children whom I have acquired by working for you. Then I’ll depart, because you know how hard I’ve worked for you.”'
EXEC add_BibleVerse @BibleId, 101030027, N'But Laban said to him, “If I have found favor in your sight, please stay here, for I have learned by divination that the Lord has blessed me on account of you.”'
EXEC add_BibleVerse @BibleId, 101030028, N'He added, “Just name your wages – I’ll pay whatever you want.”'
EXEC add_BibleVerse @BibleId, 101030029, N'“You know how I have worked for you,” Jacob replied, “and how well your livestock have fared under my care.'
EXEC add_BibleVerse @BibleId, 101030030, N'Indeed, you had little before I arrived, but now your possessions have increased many times over. The Lord has blessed you wherever I worked. But now, how long must it be before I do something for my own family too?”'
EXEC add_BibleVerse @BibleId, 101030031, N'So Laban asked, “What should I give you?” “You don’t need to give me a thing,” Jacob replied, “but if you agree to this one condition, I will continue to care for your flocks and protect them:'
EXEC add_BibleVerse @BibleId, 101030032, N'Let me walk among all your flocks today and remove from them every speckled or spotted sheep, every dark-colored lamb, and the spotted or speckled goats. These animals will be my wages.'
EXEC add_BibleVerse @BibleId, 101030033, N'My integrity will testify for me later on. When you come to verify that I’ve taken only the wages we agreed on, if I have in my possession any goat that is not speckled or spotted or any sheep that is not dark-colored, it will be considered stolen.”'
EXEC add_BibleVerse @BibleId, 101030034, N'“Agreed!” said Laban, “It will be as you say.”'
EXEC add_BibleVerse @BibleId, 101030035, N'So that day Laban removed the male goats that were streaked or spotted, all the female goats that were speckled or spotted (all that had any white on them), and all the dark-colored lambs, and put them in the care of his sons.'
EXEC add_BibleVerse @BibleId, 101030036, N'Then he separated them from Jacob by a three-day journey, while Jacob was taking care of the rest of Laban’s flocks.'
EXEC add_BibleVerse @BibleId, 101030037, N'But Jacob took fresh-cut branches from poplar, almond, and plane trees. He made white streaks by peeling them, making the white inner wood in the branches visible.'
EXEC add_BibleVerse @BibleId, 101030038, N'Then he set up the peeled branches in all the watering troughs where the flocks came to drink. He set up the branches in front of the flocks when they were in heat and came to drink.'
EXEC add_BibleVerse @BibleId, 101030039, N'When the sheep mated in front of the branches, they gave birth to young that were streaked or speckled or spotted.'
EXEC add_BibleVerse @BibleId, 101030040, N'Jacob removed these lambs, but he made the rest of the flock face the streaked and completely dark-colored animals in Laban’s flock. So he made separate flocks for himself and did not mix them with Laban’s flocks.'
EXEC add_BibleVerse @BibleId, 101030041, N'When the stronger females were in heat, Jacob would set up the branches in the troughs in front of the flock, so they would mate near the branches.'
EXEC add_BibleVerse @BibleId, 101030042, N'But if the animals were weaker, he did not set the branches there. So the weaker animals ended up belonging to Laban and the stronger animals to Jacob.'
EXEC add_BibleVerse @BibleId, 101030043, N'In this way Jacob became extremely prosperous. He owned large flocks, male and female servants, camels, and donkeys.'
EXEC add_BibleVerse @BibleId, 101031001, N'Jacob heard that Laban’s sons were complaining, “Jacob has taken everything that belonged to our father! He has gotten rich at our father’s expense!”'
EXEC add_BibleVerse @BibleId, 101031002, N'When Jacob saw the look on Laban’s face, he could tell his attitude toward him had changed.'
EXEC add_BibleVerse @BibleId, 101031003, N'The Lord said to Jacob, “Return to the land of your fathers and to your relatives. I will be with you.”'
EXEC add_BibleVerse @BibleId, 101031004, N'So Jacob sent a message for Rachel and Leah to come to the field where his flocks were.'
EXEC add_BibleVerse @BibleId, 101031005, N'There he said to them, “I can tell that your father’s attitude toward me has changed, but the God of my father has been with me.'
EXEC add_BibleVerse @BibleId, 101031006, N'You know that I’ve worked for your father as hard as I could,'
EXEC add_BibleVerse @BibleId, 101031007, N'but your father has humiliated me and changed my wages ten times. But God has not permitted him to do me any harm.'
EXEC add_BibleVerse @BibleId, 101031008, N'If he said, ‘The speckled animals will be your wage,’ then the entire flock gave birth to speckled offspring. But if he said, ‘The streaked animals will be your wage,’ then the entire flock gave birth to streaked offspring.'
EXEC add_BibleVerse @BibleId, 101031009, N'In this way God has snatched away your father’s livestock and given them to me.'
EXEC add_BibleVerse @BibleId, 101031010, N'“Once during breeding season I saw in a dream that the male goats mating with the flock were streaked, speckled, and spotted.'
EXEC add_BibleVerse @BibleId, 101031011, N'In the dream the angel of God said to me, ‘Jacob!’ ‘Here I am!’ I replied.'
EXEC add_BibleVerse @BibleId, 101031012, N'Then he said, ‘Observe that all the male goats mating with the flock are streaked, speckled, or spotted, for I have observed all that Laban has done to you.'
EXEC add_BibleVerse @BibleId, 101031013, N'I am the God of Bethel, where you anointed the sacred stone and made a vow to me. Now leave this land immediately and return to your native land.’”'
EXEC add_BibleVerse @BibleId, 101031014, N'Then Rachel and Leah replied to him, “Do we still have any portion or inheritance in our father’s house?'
EXEC add_BibleVerse @BibleId, 101031015, N'Hasn’t he treated us like foreigners? He not only sold us, but completely wasted the money paid for us!'
EXEC add_BibleVerse @BibleId, 101031016, N'Surely all the wealth that God snatched away from our father belongs to us and to our children. So now do everything God has told you.”'
EXEC add_BibleVerse @BibleId, 101031017, N'So Jacob immediately put his children and his wives on the camels.'
EXEC add_BibleVerse @BibleId, 101031018, N'He took away all the livestock he had acquired in Paddan Aram and all his moveable property that he had accumulated. Then he set out toward the land of Canaan to return to his father Isaac.'
EXEC add_BibleVerse @BibleId, 101031019, N'While Laban had gone to shear his sheep, Rachel stole the household idols that belonged to her father.'
EXEC add_BibleVerse @BibleId, 101031020, N'Jacob also deceived Laban the Aramean by not telling him that he was leaving.'
EXEC add_BibleVerse @BibleId, 101031021, N'He left with all he owned. He quickly crossed the Euphrates River and headed for the hill country of Gilead.'
EXEC add_BibleVerse @BibleId, 101031022, N'Three days later Laban discovered Jacob had left.'
EXEC add_BibleVerse @BibleId, 101031023, N'So he took his relatives with him and pursued Jacob for seven days. He caught up with him in the hill country of Gilead.'
EXEC add_BibleVerse @BibleId, 101031024, N'But God came to Laban the Aramean in a dream at night and warned him, “Be careful that you neither bless nor curse Jacob.”'
EXEC add_BibleVerse @BibleId, 101031025, N'Laban overtook Jacob, and when Jacob pitched his tent in the hill country of Gilead, Laban and his relatives set up camp there too.'
EXEC add_BibleVerse @BibleId, 101031026, N'“What have you done?” Laban demanded of Jacob. “You’ve deceived me and carried away my daughters as if they were captives of war!'
EXEC add_BibleVerse @BibleId, 101031027, N'Why did you run away secretly and deceive me? Why didn’t you tell me so I could send you off with a celebration complete with singing, tambourines, and harps?'
EXEC add_BibleVerse @BibleId, 101031028, N'You didn’t even allow me to kiss my daughters and my grandchildren good-bye. You have acted foolishly!'
EXEC add_BibleVerse @BibleId, 101031029, N'I have the power to do you harm, but the God of your father told me last night, ‘Be careful that you neither bless nor curse Jacob.’'
EXEC add_BibleVerse @BibleId, 101031030, N'Now I understand that you have gone away because you longed desperately for your father’s house. Yet why did you steal my gods?”'
EXEC add_BibleVerse @BibleId, 101031031, N'“I left secretly because I was afraid!” Jacob replied to Laban. “I thought you might take your daughters away from me by force.'
EXEC add_BibleVerse @BibleId, 101031032, N'Whoever has taken your gods will be put to death! In the presence of our relatives identify whatever is yours and take it.” (Now Jacob did not know that Rachel had stolen them.)'
EXEC add_BibleVerse @BibleId, 101031033, N'So Laban entered Jacob’s tent, and Leah’s tent, and the tent of the two female servants, but he did not find the idols. Then he left Leah’s tent and entered Rachel’s.'
EXEC add_BibleVerse @BibleId, 101031034, N'(Now Rachel had taken the idols and put them inside her camel’s saddle and sat on them.) Laban searched the whole tent, but did not find them.'
EXEC add_BibleVerse @BibleId, 101031035, N'Rachel said to her father, “Don’t be angry, my lord. I cannot stand up in your presence because I am having my period.” So he searched thoroughly, but did not find the idols.'
EXEC add_BibleVerse @BibleId, 101031036, N'Jacob became angry and argued with Laban. “What did I do wrong?” he demanded of Laban. “What sin of mine prompted you to chase after me in hot pursuit?'
EXEC add_BibleVerse @BibleId, 101031037, N'When you searched through all my goods, did you find anything that belonged to you? Set it here before my relatives and yours, and let them settle the dispute between the two of us!'
EXEC add_BibleVerse @BibleId, 101031038, N'“I have been with you for the past twenty years. Your ewes and female goats have not miscarried, nor have I eaten rams from your flocks.'
EXEC add_BibleVerse @BibleId, 101031039, N'Animals torn by wild beasts I never brought to you; I always absorbed the loss myself. You always made me pay for every missing animal, whether it was taken by day or at night.'
EXEC add_BibleVerse @BibleId, 101031040, N'I was consumed by scorching heat during the day and by piercing cold at night, and I went without sleep.'
EXEC add_BibleVerse @BibleId, 101031041, N'This was my lot for twenty years in your house: I worked like a slave for you – fourteen years for your two daughters and six years for your flocks, but you changed my wages ten times!'
EXEC add_BibleVerse @BibleId, 101031042, N'If the God of my father – the God of Abraham, the one whom Isaac fears – had not been with me, you would certainly have sent me away empty-handed! But God saw how I was oppressed and how hard I worked, and he rebuked you last night.”'
EXEC add_BibleVerse @BibleId, 101031043, N'Laban replied to Jacob, “These women are my daughters, these children are my grandchildren, and these flocks are my flocks. All that you see belongs to me. But how can I harm these daughters of mine today or the children to whom they have given birth?'
EXEC add_BibleVerse @BibleId, 101031044, N'So now, come, let’s make a formal agreement, you and I, and it will be proof that we have made peace.”'
EXEC add_BibleVerse @BibleId, 101031045, N'So Jacob took a stone and set it up as a memorial pillar.'
EXEC add_BibleVerse @BibleId, 101031046, N'Then he said to his relatives, “Gather stones.” So they brought stones and put them in a pile. They ate there by the pile of stones.'
EXEC add_BibleVerse @BibleId, 101031047, N'Laban called it Jegar Sahadutha, but Jacob called it Galeed.'
EXEC add_BibleVerse @BibleId, 101031048, N'Laban said, “This pile of stones is a witness of our agreement today.” That is why it was called Galeed.'
EXEC add_BibleVerse @BibleId, 101031049, N'It was also called Mizpah because he said, “May the Lord watch between us when we are out of sight of one another.'
EXEC add_BibleVerse @BibleId, 101031050, N'If you mistreat my daughters or if you take wives besides my daughters, although no one else is with us, realize that God is witness to your actions.”'
EXEC add_BibleVerse @BibleId, 101031051, N'“Here is this pile of stones and this pillar I have set up between me and you,” Laban said to Jacob.'
EXEC add_BibleVerse @BibleId, 101031052, N'“This pile of stones and the pillar are reminders that I will not pass beyond this pile to come to harm you and that you will not pass beyond this pile and this pillar to come to harm me.'
EXEC add_BibleVerse @BibleId, 101031053, N'May the God of Abraham and the god of Nahor, the gods of their father, judge between us.” Jacob took an oath by the God whom his father Isaac feared.'
EXEC add_BibleVerse @BibleId, 101031054, N'Then Jacob offered a sacrifice on the mountain and invited his relatives to eat the meal. They ate the meal and spent the night on the mountain.'
EXEC add_BibleVerse @BibleId, 101031055, N'Early in the morning Laban kissed his grandchildren and his daughters goodbye and blessed them. Then Laban left and returned home.'
EXEC add_BibleVerse @BibleId, 101032001, N'So Jacob went on his way and the angels of God met him.'
EXEC add_BibleVerse @BibleId, 101032002, N'When Jacob saw them, he exclaimed, “This is the camp of God!” So he named that place Mahanaim.'
EXEC add_BibleVerse @BibleId, 101032003, N'Jacob sent messengers on ahead to his brother Esau in the land of Seir, the region of Edom.'
EXEC add_BibleVerse @BibleId, 101032004, N'He commanded them, “This is what you must say to my lord Esau: ‘This is what your servant Jacob says: I have been staying with Laban until now.'
EXEC add_BibleVerse @BibleId, 101032005, N'I have oxen, donkeys, sheep, and male and female servants. I have sent this message to inform my lord, so that I may find favor in your sight.’”'
EXEC add_BibleVerse @BibleId, 101032006, N'The messengers returned to Jacob and said, “We went to your brother Esau. He is coming to meet you and has four hundred men with him.”'
EXEC add_BibleVerse @BibleId, 101032007, N'Jacob was very afraid and upset. So he divided the people who were with him into two camps, as well as the flocks, herds, and camels.'
EXEC add_BibleVerse @BibleId, 101032008, N'“If Esau attacks one camp,” he thought, “then the other camp will be able to escape.”'
EXEC add_BibleVerse @BibleId, 101032009, N'Then Jacob prayed, “O God of my father Abraham, God of my father Isaac, O Lord, you said to me, ‘Return to your land and to your relatives and I will make you prosper.’'
EXEC add_BibleVerse @BibleId, 101032010, N'I am not worthy of all the faithful love you have shown your servant. With only my walking stick I crossed the Jordan, but now I have become two camps.'
EXEC add_BibleVerse @BibleId, 101032011, N'Rescue me, I pray, from the hand of my brother Esau, for I am afraid he will come and attack me, as well as the mothers with their children.'
EXEC add_BibleVerse @BibleId, 101032012, N'But you said, ‘I will certainly make you prosper and will make your descendants like the sand on the seashore, too numerous to count.’”'
EXEC add_BibleVerse @BibleId, 101032013, N'Jacob stayed there that night. Then he sent as a gift to his brother Esau'
EXEC add_BibleVerse @BibleId, 101032014, N'two hundred female goats and twenty male goats, two hundred ewes and twenty rams,'
EXEC add_BibleVerse @BibleId, 101032015, N'thirty female camels with their young, forty cows and ten bulls, and twenty female donkeys and ten male donkeys.'
EXEC add_BibleVerse @BibleId, 101032016, N'He entrusted them to his servants, who divided them into herds. He told his servants, “Pass over before me, and keep some distance between one herd and the next.”'
EXEC add_BibleVerse @BibleId, 101032017, N'He instructed the servant leading the first herd, “When my brother Esau meets you and asks, ‘To whom do you belong? Where are you going? Whose herds are you driving?’'
EXEC add_BibleVerse @BibleId, 101032018, N'then you must say, ‘They belong to your servant Jacob. They have been sent as a gift to my lord Esau. In fact Jacob himself is behind us.’”'
EXEC add_BibleVerse @BibleId, 101032019, N'He also gave these instructions to the second and third servants, as well as all those who were following the herds, saying, “You must say the same thing to Esau when you meet him.'
EXEC add_BibleVerse @BibleId, 101032020, N'You must also say, ‘In fact your servant Jacob is behind us.’” Jacob thought, “I will first appease him by sending a gift ahead of me. After that I will meet him. Perhaps he will accept me.”'
EXEC add_BibleVerse @BibleId, 101032021, N'So the gifts were sent on ahead of him while he spent that night in the camp.'
EXEC add_BibleVerse @BibleId, 101032022, N'During the night Jacob quickly took his two wives, his two female servants, and his eleven sons and crossed the ford of the Jabbok.'
EXEC add_BibleVerse @BibleId, 101032023, N'He took them and sent them across the stream along with all his possessions.'
EXEC add_BibleVerse @BibleId, 101032024, N'So Jacob was left alone. Then a man wrestled with him until daybreak.'
EXEC add_BibleVerse @BibleId, 101032025, N'When the man saw that he could not defeat Jacob, he struck the socket of his hip so the socket of Jacob’s hip was dislocated while he wrestled with him.'
EXEC add_BibleVerse @BibleId, 101032026, N'Then the man said, “Let me go, for the dawn is breaking.” “I will not let you go,” Jacob replied, “unless you bless me.”'
EXEC add_BibleVerse @BibleId, 101032027, N'The man asked him, “What is your name?” He answered, “Jacob.”'
EXEC add_BibleVerse @BibleId, 101032028, N'“No longer will your name be Jacob,” the man told him, “but Israel, because you have fought with God and with men and have prevailed.”'
EXEC add_BibleVerse @BibleId, 101032029, N'Then Jacob asked, “Please tell me your name.” “Why do you ask my name?” the man replied. Then he blessed Jacob there.'
EXEC add_BibleVerse @BibleId, 101032030, N'So Jacob named the place Peniel, explaining, “Certainly I have seen God face to face and have survived.”'
EXEC add_BibleVerse @BibleId, 101032031, N'The sun rose over him as he crossed over Penuel, but he was limping because of his hip.'
EXEC add_BibleVerse @BibleId, 101032032, N'That is why to this day the Israelites do not eat the sinew which is attached to the socket of the hip, because he struck the socket of Jacob’s hip near the attached sinew.'
EXEC add_BibleVerse @BibleId, 101033001, N'Jacob looked up and saw that Esau was coming along with four hundred men. So he divided the children among Leah, Rachel, and the two female servants.'
EXEC add_BibleVerse @BibleId, 101033002, N'He put the servants and their children in front, with Leah and her children behind them, and Rachel and Joseph behind them.'
EXEC add_BibleVerse @BibleId, 101033003, N'But Jacob himself went on ahead of them, and he bowed toward the ground seven times as he approached his brother.'
EXEC add_BibleVerse @BibleId, 101033004, N'But Esau ran to meet him, embraced him, hugged his neck, and kissed him. Then they both wept.'
EXEC add_BibleVerse @BibleId, 101033005, N'When Esau looked up and saw the women and the children, he asked, “Who are these people with you?” Jacob replied, “The children whom God has graciously given your servant.”'
EXEC add_BibleVerse @BibleId, 101033006, N'The female servants came forward with their children and bowed down.'
EXEC add_BibleVerse @BibleId, 101033007, N'Then Leah came forward with her children and they bowed down. Finally Joseph and Rachel came forward and bowed down.'
EXEC add_BibleVerse @BibleId, 101033008, N'Esau then asked, “What did you intend by sending all these herds to meet me?” Jacob replied, “To find favor in your sight, my lord.”'
EXEC add_BibleVerse @BibleId, 101033009, N'But Esau said, “I have plenty, my brother. Keep what belongs to you.”'
EXEC add_BibleVerse @BibleId, 101033010, N'“No, please take them,” Jacob said. “If I have found favor in your sight, accept my gift from my hand. Now that I have seen your face and you have accepted me, it is as if I have seen the face of God.'
EXEC add_BibleVerse @BibleId, 101033011, N'Please take my present that was brought to you, for God has been generous to me and I have all I need.” When Jacob urged him, he took it.'
EXEC add_BibleVerse @BibleId, 101033012, N'Then Esau said, “Let’s be on our way! I will go in front of you.”'
EXEC add_BibleVerse @BibleId, 101033013, N'But Jacob said to him, “My lord knows that the children are young, and that I have to look after the sheep and cattle that are nursing their young. If they are driven too hard for even a single day, all the animals will die.'
EXEC add_BibleVerse @BibleId, 101033014, N'Let my lord go on ahead of his servant. I will travel more slowly, at the pace of the herds and the children, until I come to my lord at Seir.”'
EXEC add_BibleVerse @BibleId, 101033015, N'So Esau said, “Let me leave some of my men with you.” “Why do that?” Jacob replied. “My lord has already been kind enough to me.”'
EXEC add_BibleVerse @BibleId, 101033016, N'So that same day Esau made his way back to Seir.'
EXEC add_BibleVerse @BibleId, 101033017, N'But Jacob traveled to Succoth where he built himself a house and made shelters for his livestock. That is why the place was called Succoth.'
EXEC add_BibleVerse @BibleId, 101033018, N'After he left Paddan Aram, Jacob came safely to the city of Shechem in the land of Canaan, and he camped near the city.'
EXEC add_BibleVerse @BibleId, 101033019, N'Then he purchased the portion of the field where he had pitched his tent; he bought it from the sons of Hamor, Shechem’s father, for a hundred pieces of money.'
EXEC add_BibleVerse @BibleId, 101033020, N'There he set up an altar and called it “The God of Israel is God.”'
EXEC add_BibleVerse @BibleId, 101034001, N'Now Dinah, Leah’s daughter whom she bore to Jacob, went to meet the young women of the land.'
EXEC add_BibleVerse @BibleId, 101034002, N'When Shechem son of Hamor the Hivite, who ruled that area, saw her, he grabbed her, forced himself on her, and sexually assaulted her.'
EXEC add_BibleVerse @BibleId, 101034003, N'Then he became very attached to Dinah, Jacob’s daughter. He fell in love with the young woman and spoke romantically to her.'
EXEC add_BibleVerse @BibleId, 101034004, N'Shechem said to his father Hamor, “Acquire this young girl as my wife.”'
EXEC add_BibleVerse @BibleId, 101034005, N'When Jacob heard that Shechem had violated his daughter Dinah, his sons were with the livestock in the field. So Jacob remained silent until they came in.'
EXEC add_BibleVerse @BibleId, 101034006, N'Then Shechem’s father Hamor went to speak with Jacob about Dinah.'
EXEC add_BibleVerse @BibleId, 101034007, N'Now Jacob’s sons had come in from the field when they heard the news. They were offended and very angry because Shechem had disgraced Israel by sexually assaulting Jacob’s daughter, a crime that should not be committed.'
EXEC add_BibleVerse @BibleId, 101034008, N'But Hamor made this appeal to them: “My son Shechem is in love with your daughter. Please give her to him as his wife.'
EXEC add_BibleVerse @BibleId, 101034009, N'Intermarry with us. Let us marry your daughters, and take our daughters as wives for yourselves.'
EXEC add_BibleVerse @BibleId, 101034010, N'You may live among us, and the land will be open to you. Live in it, travel freely in it, and acquire property in it.”'
EXEC add_BibleVerse @BibleId, 101034011, N'Then Shechem said to Dinah’s father and brothers, “Let me find favor in your sight, and whatever you require of me I’ll give.'
EXEC add_BibleVerse @BibleId, 101034012, N'You can make the bride price and the gift I must bring very expensive, and I’ll give whatever you ask of me. Just give me the young woman as my wife!”'
EXEC add_BibleVerse @BibleId, 101034013, N'Jacob’s sons answered Shechem and his father Hamor deceitfully when they spoke because Shechem had violated their sister Dinah.'
EXEC add_BibleVerse @BibleId, 101034014, N'They said to them, “We cannot give our sister to a man who is not circumcised, for it would be a disgrace to us.'
EXEC add_BibleVerse @BibleId, 101034015, N'We will give you our consent on this one condition: You must become like us by circumcising all your males.'
EXEC add_BibleVerse @BibleId, 101034016, N'Then we will give you our daughters to marry, and we will take your daughters as wives for ourselves, and we will live among you and become one people.'
EXEC add_BibleVerse @BibleId, 101034017, N'But if you do not agree to our terms by being circumcised, then we will take our sister and depart.”'
EXEC add_BibleVerse @BibleId, 101034018, N'Their offer pleased Hamor and his son Shechem.'
EXEC add_BibleVerse @BibleId, 101034019, N'The young man did not delay in doing what they asked because he wanted Jacob’s daughter Dinah badly. (Now he was more important than anyone in his father’s household.)'
EXEC add_BibleVerse @BibleId, 101034020, N'So Hamor and his son Shechem went to the gate of their city and spoke to the men of their city,'
EXEC add_BibleVerse @BibleId, 101034021, N'“These men are at peace with us. So let them live in the land and travel freely in it, for the land is wide enough for them. We will take their daughters for wives, and we will give them our daughters to marry.'
EXEC add_BibleVerse @BibleId, 101034022, N'Only on this one condition will these men consent to live with us and become one people: They demand that every male among us be circumcised just as they are circumcised.'
EXEC add_BibleVerse @BibleId, 101034023, N'If we do so, won’t their livestock, their property, and all their animals become ours? So let’s consent to their demand, so they will live among us.”'
EXEC add_BibleVerse @BibleId, 101034024, N'All the men who assembled at the city gate agreed with Hamor and his son Shechem. Every male who assembled at the city gate was circumcised.'
EXEC add_BibleVerse @BibleId, 101034025, N'In three days, when they were still in pain, two of Jacob’s sons, Simeon and Levi, Dinah’s brothers, each took his sword and went to the unsuspecting city and slaughtered every male.'
EXEC add_BibleVerse @BibleId, 101034026, N'They killed Hamor and his son Shechem with the sword, took Dinah from Shechem’s house, and left.'
EXEC add_BibleVerse @BibleId, 101034027, N'Jacob’s sons killed them and looted the city because their sister had been violated.'
EXEC add_BibleVerse @BibleId, 101034028, N'They took their flocks, herds, and donkeys, as well as everything in the city and in the surrounding fields.'
EXEC add_BibleVerse @BibleId, 101034029, N'They captured as plunder all their wealth, all their little ones, and their wives, including everything in the houses.'
EXEC add_BibleVerse @BibleId, 101034030, N'Then Jacob said to Simeon and Levi, “You have brought ruin on me by making me a foul odor among the inhabitants of the land – among the Canaanites and the Perizzites. I am few in number; they will join forces against me and attack me, and both I and my family will be destroyed!”'
EXEC add_BibleVerse @BibleId, 101034031, N'But Simeon and Levi replied, “Should he treat our sister like a common prostitute?”'
EXEC add_BibleVerse @BibleId, 101035001, N'Then God said to Jacob, “Go up at once to Bethel and live there. Make an altar there to God, who appeared to you when you fled from your brother Esau.”'
EXEC add_BibleVerse @BibleId, 101035002, N'So Jacob told his household and all who were with him, “Get rid of the foreign gods you have among you. Purify yourselves and change your clothes.'
EXEC add_BibleVerse @BibleId, 101035003, N'Let us go up at once to Bethel. Then I will make an altar there to God, who responded to me in my time of distress and has been with me wherever I went.”'
EXEC add_BibleVerse @BibleId, 101035004, N'So they gave Jacob all the foreign gods that were in their possession and the rings that were in their ears. Jacob buried them under the oak near Shechem'
EXEC add_BibleVerse @BibleId, 101035005, N'and they started on their journey. The surrounding cities were afraid of God, and they did not pursue the sons of Jacob.'
EXEC add_BibleVerse @BibleId, 101035006, N'Jacob and all those who were with him arrived at Luz (that is, Bethel) in the land of Canaan.'
EXEC add_BibleVerse @BibleId, 101035007, N'He built an altar there and named the place El Bethel because there God had revealed himself to him when he was fleeing from his brother.'
EXEC add_BibleVerse @BibleId, 101035008, N'(Deborah, Rebekah’s nurse, died and was buried under the oak below Bethel; thus it was named Oak of Weeping.)'
EXEC add_BibleVerse @BibleId, 101035009, N'God appeared to Jacob again after he returned from Paddan Aram and blessed him.'
EXEC add_BibleVerse @BibleId, 101035010, N'God said to him, “Your name is Jacob, but your name will no longer be called Jacob; Israel will be your name.” So God named him Israel.'
EXEC add_BibleVerse @BibleId, 101035011, N'Then God said to him, “I am the sovereign God. Be fruitful and multiply! A nation – even a company of nations – will descend from you; kings will be among your descendants!'
EXEC add_BibleVerse @BibleId, 101035012, N'The land I gave to Abraham and Isaac I will give to you. To your descendants I will also give this land.”'
EXEC add_BibleVerse @BibleId, 101035013, N'Then God went up from the place where he spoke with him.'
EXEC add_BibleVerse @BibleId, 101035014, N'So Jacob set up a sacred stone pillar in the place where God spoke with him. He poured out a drink offering on it, and then he poured oil on it.'
EXEC add_BibleVerse @BibleId, 101035015, N'Jacob named the place where God spoke with him Bethel.'
EXEC add_BibleVerse @BibleId, 101035016, N'They traveled on from Bethel, and when Ephrath was still some distance away, Rachel went into labor – and her labor was hard.'
EXEC add_BibleVerse @BibleId, 101035017, N'When her labor was at its hardest, the midwife said to her, “Don’t be afraid, for you are having another son.”'
EXEC add_BibleVerse @BibleId, 101035018, N'With her dying breath, she named him Ben-Oni. But his father called him Benjamin instead.'
EXEC add_BibleVerse @BibleId, 101035019, N'So Rachel died and was buried on the way to Ephrath (that is, Bethlehem).'
EXEC add_BibleVerse @BibleId, 101035020, N'Jacob set up a marker over her grave; it is the Marker of Rachel’s Grave to this day.'
EXEC add_BibleVerse @BibleId, 101035021, N'Then Israel traveled on and pitched his tent beyond Migdal Eder.'
EXEC add_BibleVerse @BibleId, 101035022, N'While Israel was living in that land, Reuben had sexual relations with Bilhah, his father’s concubine, and Israel heard about it. Jacob had twelve sons:'
EXEC add_BibleVerse @BibleId, 101035023, N'The sons of Leah were Reuben, Jacob’s firstborn, as well as Simeon, Levi, Judah, Issachar, and Zebulun.'
EXEC add_BibleVerse @BibleId, 101035024, N'The sons of Rachel were Joseph and Benjamin.'
EXEC add_BibleVerse @BibleId, 101035025, N'The sons of Bilhah, Rachel’s servant, were Dan and Naphtali.'
EXEC add_BibleVerse @BibleId, 101035026, N'The sons of Zilpah, Leah’s servant, were Gad and Asher. These were the sons of Jacob who were born to him in Paddan Aram.'
EXEC add_BibleVerse @BibleId, 101035027, N'So Jacob came back to his father Isaac in Mamre, to Kiriath Arba (that is, Hebron), where Abraham and Isaac had stayed.'
EXEC add_BibleVerse @BibleId, 101035028, N'Isaac lived to be 180 years old.'
EXEC add_BibleVerse @BibleId, 101035029, N'Then Isaac breathed his last and joined his ancestors. He died an old man who had lived a full life. His sons Esau and Jacob buried him.'
EXEC add_BibleVerse @BibleId, 101036001, N'What follows is the account of Esau (also known as Edom).'
EXEC add_BibleVerse @BibleId, 101036002, N'Esau took his wives from the Canaanites: Adah the daughter of Elon the Hittite, and Oholibamah the daughter of Anah and granddaughter of Zibeon the Hivite,'
EXEC add_BibleVerse @BibleId, 101036003, N'in addition to Basemath the daughter of Ishmael and sister of Nebaioth.'
EXEC add_BibleVerse @BibleId, 101036004, N'Adah bore Eliphaz to Esau, Basemath bore Reuel,'
EXEC add_BibleVerse @BibleId, 101036005, N'and Oholibamah bore Jeush, Jalam, and Korah. These were the sons of Esau who were born to him in the land of Canaan.'
EXEC add_BibleVerse @BibleId, 101036006, N'Esau took his wives, his sons, his daughters, all the people in his household, his livestock, his animals, and all his possessions which he had acquired in the land of Canaan and went to a land some distance away from Jacob his brother'
EXEC add_BibleVerse @BibleId, 101036007, N'because they had too many possessions to be able to stay together and the land where they had settled was not able to support them because of their livestock.'
EXEC add_BibleVerse @BibleId, 101036008, N'So Esau (also known as Edom) lived in the hill country of Seir.'
EXEC add_BibleVerse @BibleId, 101036009, N'This is the account of Esau, the father of the Edomites, in the hill country of Seir.'
EXEC add_BibleVerse @BibleId, 101036010, N'These were the names of Esau’s sons: Eliphaz, the son of Esau’s wife Adah, and Reuel, the son of Esau’s wife Basemath.'
EXEC add_BibleVerse @BibleId, 101036011, N'The sons of Eliphaz were: Teman, Omar, Zepho, Gatam, and Kenaz.'
EXEC add_BibleVerse @BibleId, 101036012, N'Timna, a concubine of Esau’s son Eliphaz, bore Amalek to Eliphaz. These were the sons of Esau’s wife Adah.'
EXEC add_BibleVerse @BibleId, 101036013, N'These were the sons of Reuel: Nahath, Zerah, Shammah, and Mizzah. These were the sons of Esau’s wife Basemath.'
EXEC add_BibleVerse @BibleId, 101036014, N'These were the sons of Esau’s wife Oholibamah the daughter of Anah and granddaughter of Zibeon: She bore Jeush, Jalam, and Korah to Esau.'
EXEC add_BibleVerse @BibleId, 101036015, N'These were the chiefs among the descendants of Esau, the sons of Eliphaz, Esau’s firstborn: chief Teman, chief Omar, chief Zepho, chief Kenaz,'
EXEC add_BibleVerse @BibleId, 101036016, N'chief Korah, chief Gatam, chief Amalek. These were the chiefs descended from Eliphaz in the land of Edom; these were the sons of Adah.'
EXEC add_BibleVerse @BibleId, 101036017, N'These were the sons of Esau’s son Reuel: chief Nahath, chief Zerah, chief Shammah, chief Mizzah. These were the chiefs descended from Reuel in the land of Edom; these were the sons of Esau’s wife Basemath.'
EXEC add_BibleVerse @BibleId, 101036018, N'These were the sons of Esau’s wife Oholibamah: chief Jeush, chief Jalam, chief Korah. These were the chiefs descended from Esau’s wife Oholibamah, the daughter of Anah.'
EXEC add_BibleVerse @BibleId, 101036019, N'These were the sons of Esau (also known as Edom), and these were their chiefs.'
EXEC add_BibleVerse @BibleId, 101036020, N'These were the sons of Seir the Horite, who were living in the land: Lotan, Shobal, Zibeon, Anah,'
EXEC add_BibleVerse @BibleId, 101036021, N'Dishon, Ezer, and Dishan. These were the chiefs of the Horites, the descendants of Seir in the land of Edom.'
EXEC add_BibleVerse @BibleId, 101036022, N'The sons of Lotan were Hori and Homam; Lotan’s sister was Timna.'
EXEC add_BibleVerse @BibleId, 101036023, N'These were the sons of Shobal: Alvan, Manahath, Ebal, Shepho, and Onam.'
EXEC add_BibleVerse @BibleId, 101036024, N'These were the sons of Zibeon: Aiah and Anah (who discovered the hot springs in the wilderness as he pastured the donkeys of his father Zibeon).'
EXEC add_BibleVerse @BibleId, 101036025, N'These were the children of Anah: Dishon and Oholibamah, the daughter of Anah.'
EXEC add_BibleVerse @BibleId, 101036026, N'These were the sons of Dishon: Hemdan, Eshban, Ithran, and Keran.'
EXEC add_BibleVerse @BibleId, 101036027, N'These were the sons of Ezer: Bilhan, Zaavan, and Akan.'
EXEC add_BibleVerse @BibleId, 101036028, N'These were the sons of Dishan: Uz and Aran.'
EXEC add_BibleVerse @BibleId, 101036029, N'These were the chiefs of the Horites: chief Lotan, chief Shobal, chief Zibeon, chief Anah,'
EXEC add_BibleVerse @BibleId, 101036030, N'chief Dishon, chief Ezer, chief Dishan. These were the chiefs of the Horites, according to their chief lists in the land of Seir.'
EXEC add_BibleVerse @BibleId, 101036031, N'These were the kings who reigned in the land of Edom before any king ruled over the Israelites:'
EXEC add_BibleVerse @BibleId, 101036032, N'Bela the son of Beor reigned in Edom; the name of his city was Dinhabah.'
EXEC add_BibleVerse @BibleId, 101036033, N'When Bela died, Jobab the son of Zerah from Bozrah reigned in his place.'
EXEC add_BibleVerse @BibleId, 101036034, N'When Jobab died, Husham from the land of the Temanites reigned in his place.'
EXEC add_BibleVerse @BibleId, 101036035, N'When Husham died, Hadad the son of Bedad, who defeated the Midianites in the land of Moab, reigned in his place; the name of his city was Avith.'
EXEC add_BibleVerse @BibleId, 101036036, N'When Hadad died, Samlah from Masrekah reigned in his place.'
EXEC add_BibleVerse @BibleId, 101036037, N'When Samlah died, Shaul from Rehoboth by the River reigned in his place.'
EXEC add_BibleVerse @BibleId, 101036038, N'When Shaul died, Baal-Hanan the son of Achbor reigned in his place.'
EXEC add_BibleVerse @BibleId, 101036039, N'When Baal-Hanan the son of Achbor died, Hadad reigned in his place; the name of his city was Pau. His wife’s name was Mehetabel, the daughter of Matred, the daughter of Me-Zahab.'
EXEC add_BibleVerse @BibleId, 101036040, N'These were the names of the chiefs of Esau, according to their families, according to their places, by their names: chief Timna, chief Alvah, chief Jetheth,'
EXEC add_BibleVerse @BibleId, 101036041, N'chief Oholibamah, chief Elah, chief Pinon,'
EXEC add_BibleVerse @BibleId, 101036042, N'chief Kenaz, chief Teman, chief Mibzar,'
EXEC add_BibleVerse @BibleId, 101036043, N'chief Magdiel, chief Iram. These were the chiefs of Edom, according to their settlements in the land they possessed. This was Esau, the father of the Edomites.'
EXEC add_BibleVerse @BibleId, 101037001, N'But Jacob lived in the land where his father had stayed, in the land of Canaan.'
EXEC add_BibleVerse @BibleId, 101037002, N'This is the account of Jacob. Joseph, his seventeen-year-old son, was taking care of the flocks with his brothers. Now he was a youngster working with the sons of Bilhah and Zilpah, his father’s wives. Joseph brought back a bad report about them to their father.'
EXEC add_BibleVerse @BibleId, 101037003, N'Now Israel loved Joseph more than all his sons because he was a son born to him late in life, and he made a special tunic for him.'
EXEC add_BibleVerse @BibleId, 101037004, N'When Joseph’s brothers saw that their father loved him more than any of them, they hated Joseph and were not able to speak to him kindly.'
EXEC add_BibleVerse @BibleId, 101037005, N'Joseph had a dream, and when he told his brothers about it, they hated him even more.'
EXEC add_BibleVerse @BibleId, 101037006, N'He said to them, “Listen to this dream I had:'
EXEC add_BibleVerse @BibleId, 101037007, N'There we were, binding sheaves of grain in the middle of the field. Suddenly my sheaf rose up and stood upright and your sheaves surrounded my sheaf and bowed down to it!”'
EXEC add_BibleVerse @BibleId, 101037008, N'Then his brothers asked him, “Do you really think you will rule over us or have dominion over us?” They hated him even more because of his dream and because of what he said.'
EXEC add_BibleVerse @BibleId, 101037009, N'Then he had another dream, and told it to his brothers. “Look,” he said. “I had another dream. The sun, the moon, and eleven stars were bowing down to me.”'
EXEC add_BibleVerse @BibleId, 101037010, N'When he told his father and his brothers, his father rebuked him, saying, “What is this dream that you had? Will I, your mother, and your brothers really come and bow down to you?”'
EXEC add_BibleVerse @BibleId, 101037011, N'His brothers were jealous of him, but his father kept in mind what Joseph said.'
EXEC add_BibleVerse @BibleId, 101037012, N'When his brothers had gone to graze their father’s flocks near Shechem,'
EXEC add_BibleVerse @BibleId, 101037013, N'Israel said to Joseph, “Your brothers are grazing the flocks near Shechem. Come, I will send you to them.” “I’m ready,” Joseph replied.'
EXEC add_BibleVerse @BibleId, 101037014, N'So Jacob said to him, “Go now and check on the welfare of your brothers and of the flocks, and bring me word.” So Jacob sent him from the valley of Hebron.'
EXEC add_BibleVerse @BibleId, 101037015, N'When Joseph reached Shechem, a man found him wandering in the field, so the man asked him, “What are you looking for?”'
EXEC add_BibleVerse @BibleId, 101037016, N'He replied, “I’m looking for my brothers. Please tell me where they are grazing their flocks.”'
EXEC add_BibleVerse @BibleId, 101037017, N'The man said, “They left this area, for I heard them say, ‘Let’s go to Dothan.’” So Joseph went after his brothers and found them at Dothan.'
EXEC add_BibleVerse @BibleId, 101037018, N'Now Joseph’s brothers saw him from a distance, and before he reached them, they plotted to kill him.'
EXEC add_BibleVerse @BibleId, 101037019, N'They said to one another, “Here comes this master of dreams!'
EXEC add_BibleVerse @BibleId, 101037020, N'Come now, let’s kill him, throw him into one of the cisterns, and then say that a wild animal ate him. Then we’ll see how his dreams turn out!”'
EXEC add_BibleVerse @BibleId, 101037021, N'When Reuben heard this, he rescued Joseph from their hands, saying, “Let’s not take his life!”'
EXEC add_BibleVerse @BibleId, 101037022, N'Reuben continued, “Don’t shed blood! Throw him into this cistern that is here in the wilderness, but don’t lay a hand on him.” (Reuben said this so he could rescue Joseph from them and take him back to his father.)'
EXEC add_BibleVerse @BibleId, 101037023, N'When Joseph reached his brothers, they stripped him of his tunic, the special tunic that he wore.'
EXEC add_BibleVerse @BibleId, 101037024, N'Then they took him and threw him into the cistern. (Now the cistern was empty; there was no water in it.)'
EXEC add_BibleVerse @BibleId, 101037025, N'When they sat down to eat their food, they looked up and saw a caravan of Ishmaelites coming from Gilead. Their camels were carrying spices, balm, and myrrh down to Egypt.'
EXEC add_BibleVerse @BibleId, 101037026, N'Then Judah said to his brothers, “What profit is there if we kill our brother and cover up his blood?'
EXEC add_BibleVerse @BibleId, 101037027, N'Come, let’s sell him to the Ishmaelites, but let’s not lay a hand on him, for after all, he is our brother, our own flesh.” His brothers agreed.'
EXEC add_BibleVerse @BibleId, 101037028, N'So when the Midianite merchants passed by, Joseph’s brothers pulled him out of the cistern and sold him to the Ishmaelites for twenty pieces of silver. The Ishmaelites then took Joseph to Egypt.'
EXEC add_BibleVerse @BibleId, 101037029, N'Later Reuben returned to the cistern to find that Joseph was not in it! He tore his clothes,'
EXEC add_BibleVerse @BibleId, 101037030, N'returned to his brothers, and said, “The boy isn’t there! And I, where can I go?”'
EXEC add_BibleVerse @BibleId, 101037031, N'So they took Joseph’s tunic, killed a young goat, and dipped the tunic in the blood.'
EXEC add_BibleVerse @BibleId, 101037032, N'Then they brought the special tunic to their father and said, “We found this. Determine now whether it is your son’s tunic or not.”'
EXEC add_BibleVerse @BibleId, 101037033, N'He recognized it and exclaimed, “It is my son’s tunic! A wild animal has eaten him! Joseph has surely been torn to pieces!”'
EXEC add_BibleVerse @BibleId, 101037034, N'Then Jacob tore his clothes, put on sackcloth, and mourned for his son many days.'
EXEC add_BibleVerse @BibleId, 101037035, N'All his sons and daughters stood by him to console him, but he refused to be consoled. “No,” he said, “I will go to the grave mourning my son.” So Joseph’s father wept for him.'
EXEC add_BibleVerse @BibleId, 101037036, N'Now in Egypt the Midianites sold Joseph to Potiphar, one of Pharaoh’s officials, the captain of the guard.'
EXEC add_BibleVerse @BibleId, 101038001, N'At that time Judah left his brothers and stayed with an Adullamite man named Hirah.'
EXEC add_BibleVerse @BibleId, 101038002, N'There Judah saw the daughter of a Canaanite man named Shua. Judah acquired her as a wife and had marital relations with her.'
EXEC add_BibleVerse @BibleId, 101038003, N'She became pregnant and had a son. Judah named him Er.'
EXEC add_BibleVerse @BibleId, 101038004, N'She became pregnant again and had another son, whom she named Onan.'
EXEC add_BibleVerse @BibleId, 101038005, N'Then she had yet another son, whom she named Shelah. She gave birth to him in Kezib.'
EXEC add_BibleVerse @BibleId, 101038006, N'Judah acquired a wife for Er his firstborn; her name was Tamar.'
EXEC add_BibleVerse @BibleId, 101038007, N'But Er, Judah’s firstborn, was evil in the Lord’s sight, so the Lord killed him.'
EXEC add_BibleVerse @BibleId, 101038008, N'Then Judah said to Onan, “Have sexual relations with your brother’s wife and fulfill the duty of a brother-in-law to her so that you may raise up a descendant for your brother.”'
EXEC add_BibleVerse @BibleId, 101038009, N'But Onan knew that the child would not be considered his. So whenever he had sexual relations with his brother’s wife, he withdrew prematurely so as not to give his brother a descendant.'
EXEC add_BibleVerse @BibleId, 101038010, N'What he did was evil in the Lord’s sight, so the Lord killed him too.'
EXEC add_BibleVerse @BibleId, 101038011, N'Then Judah said to his daughter-in-law Tamar, “Live as a widow in your father’s house until Shelah my son grows up.” For he thought, “I don’t want him to die like his brothers.” So Tamar went and lived in her father’s house.'
EXEC add_BibleVerse @BibleId, 101038012, N'After some time Judah’s wife, the daughter of Shua, died. After Judah was consoled, he left for Timnah to visit his sheepshearers, along with his friend Hirah the Adullamite.'
EXEC add_BibleVerse @BibleId, 101038013, N'Tamar was told, “Look, your father-in-law is going up to Timnah to shear his sheep.”'
EXEC add_BibleVerse @BibleId, 101038014, N'So she removed her widow’s clothes and covered herself with a veil. She wrapped herself and sat at the entrance to Enaim which is on the way to Timnah. (She did this because she saw that she had not been given to Shelah as a wife, even though he had now grown up.)'
EXEC add_BibleVerse @BibleId, 101038015, N'When Judah saw her, he thought she was a prostitute because she had covered her face.'
EXEC add_BibleVerse @BibleId, 101038016, N'He turned aside to her along the road and said, “Come on! I want to have sex with you.” (He did not realize it was his daughter-in-law.) She asked, “What will you give me in exchange for having sex with you?”'
EXEC add_BibleVerse @BibleId, 101038017, N'He replied, “I’ll send you a young goat from the flock.” She asked, “Will you give me a pledge until you send it?”'
EXEC add_BibleVerse @BibleId, 101038018, N'He said, “What pledge should I give you?” She replied, “Your seal, your cord, and the staff that’s in your hand.” So he gave them to her and had sex with her. She became pregnant by him.'
EXEC add_BibleVerse @BibleId, 101038019, N'She left immediately, removed her veil, and put on her widow’s clothes.'
EXEC add_BibleVerse @BibleId, 101038020, N'Then Judah had his friend Hirah the Adullamite take a young goat to get back from the woman the items he had given in pledge, but Hirah could not find her.'
EXEC add_BibleVerse @BibleId, 101038021, N'He asked the men who were there, “Where is the cult prostitute who was at Enaim by the road?” But they replied, “There has been no cult prostitute here.”'
EXEC add_BibleVerse @BibleId, 101038022, N'So he returned to Judah and said, “I couldn’t find her. Moreover, the men of the place said, ‘There has been no cult prostitute here.’”'
EXEC add_BibleVerse @BibleId, 101038023, N'Judah said, “Let her keep the things for herself. Otherwise we will appear to be dishonest. I did indeed send this young goat, but you couldn’t find her.”'
EXEC add_BibleVerse @BibleId, 101038024, N'After three months Judah was told, “Your daughter-in-law Tamar has turned to prostitution, and as a result she has become pregnant.” Judah said, “Bring her out and let her be burned!”'
EXEC add_BibleVerse @BibleId, 101038025, N'While they were bringing her out, she sent word to her father-in-law: “I am pregnant by the man to whom these belong.” Then she said, “Identify the one to whom the seal, cord, and staff belong.”'
EXEC add_BibleVerse @BibleId, 101038026, N'Judah recognized them and said, “She is more upright than I am, because I wouldn’t give her to Shelah my son.” He did not have sexual relations with her again.'
EXEC add_BibleVerse @BibleId, 101038027, N'When it was time for her to give birth, there were twins in her womb.'
EXEC add_BibleVerse @BibleId, 101038028, N'While she was giving birth, one child put out his hand, and the midwife took a scarlet thread and tied it on his hand, saying, “This one came out first.”'
EXEC add_BibleVerse @BibleId, 101038029, N'But then he drew back his hand, and his brother came out before him. She said, “How you have broken out of the womb!” So he was named Perez.'
EXEC add_BibleVerse @BibleId, 101038030, N'Afterward his brother came out – the one who had the scarlet thread on his hand – and he was named Zerah.'
EXEC add_BibleVerse @BibleId, 101039001, N'Now Joseph had been brought down to Egypt. An Egyptian named Potiphar, an official of Pharaoh and the captain of the guard, purchased him from the Ishmaelites who had brought him there.'
EXEC add_BibleVerse @BibleId, 101039002, N'The Lord was with Joseph. He was successful and lived in the household of his Egyptian master.'
EXEC add_BibleVerse @BibleId, 101039003, N'His master observed that the Lord was with him and that the Lord made everything he was doing successful.'
EXEC add_BibleVerse @BibleId, 101039004, N'So Joseph found favor in his sight and became his personal attendant. Potiphar appointed Joseph overseer of his household and put him in charge of everything he owned.'
EXEC add_BibleVerse @BibleId, 101039005, N'From the time Potiphar appointed him over his household and over all that he owned, the Lord blessed the Egyptian’s household for Joseph’s sake. The blessing of the Lord was on everything that he had, both in his house and in his fields.'
EXEC add_BibleVerse @BibleId, 101039006, N'So Potiphar left everything he had in Joseph’s care; he gave no thought to anything except the food he ate. Now Joseph was well built and good-looking.'
EXEC add_BibleVerse @BibleId, 101039007, N'Soon after these things, his master’s wife took notice of Joseph and said, “Have sex with me.”'
EXEC add_BibleVerse @BibleId, 101039008, N'But he refused, saying to his master’s wife, “Look, my master does not give any thought to his household with me here, and everything that he owns he has put into my care.'
EXEC add_BibleVerse @BibleId, 101039009, N'There is no one greater in this household than I am. He has withheld nothing from me except you because you are his wife. So how could I do such a great evil and sin against God?”'
EXEC add_BibleVerse @BibleId, 101039010, N'Even though she continued to speak to Joseph day after day, he did not respond to her invitation to have sex with her.'
EXEC add_BibleVerse @BibleId, 101039011, N'One day he went into the house to do his work when none of the household servants were there in the house.'
EXEC add_BibleVerse @BibleId, 101039012, N'She grabbed him by his outer garment, saying, “Have sex with me!” But he left his outer garment in her hand and ran outside.'
EXEC add_BibleVerse @BibleId, 101039013, N'When she saw that he had left his outer garment in her hand and had run outside,'
EXEC add_BibleVerse @BibleId, 101039014, N'she called for her household servants and said to them, “See, my husband brought in a Hebrew man to us to humiliate us. He tried to have sex with me, but I screamed loudly.'
EXEC add_BibleVerse @BibleId, 101039015, N'When he heard me raise my voice and scream, he left his outer garment beside me and ran outside.”'
EXEC add_BibleVerse @BibleId, 101039016, N'So she laid his outer garment beside her until his master came home.'
EXEC add_BibleVerse @BibleId, 101039017, N'This is what she said to him: “That Hebrew slave you brought to us tried to humiliate me,'
EXEC add_BibleVerse @BibleId, 101039018, N'but when I raised my voice and screamed, he left his outer garment and ran outside.”'
EXEC add_BibleVerse @BibleId, 101039019, N'When his master heard his wife say, “This is the way your slave treated me,” he became furious.'
EXEC add_BibleVerse @BibleId, 101039020, N'Joseph’s master took him and threw him into the prison, the place where the king’s prisoners were confined. So he was there in the prison.'
EXEC add_BibleVerse @BibleId, 101039021, N'But the Lord was with Joseph and showed him kindness. He granted him favor in the sight of the prison warden.'
EXEC add_BibleVerse @BibleId, 101039022, N'The warden put all the prisoners under Joseph’s care. He was in charge of whatever they were doing.'
EXEC add_BibleVerse @BibleId, 101039023, N'The warden did not concern himself with anything that was in Joseph’s care because the Lord was with him and whatever he was doing the Lord was making successful.'
EXEC add_BibleVerse @BibleId, 101040001, N'After these things happened, the cupbearer to the king of Egypt and the royal baker offended their master, the king of Egypt.'
EXEC add_BibleVerse @BibleId, 101040002, N'Pharaoh was enraged with his two officials, the cupbearer and the baker,'
EXEC add_BibleVerse @BibleId, 101040003, N'so he imprisoned them in the house of the captain of the guard in the same facility where Joseph was confined.'
EXEC add_BibleVerse @BibleId, 101040004, N'The captain of the guard appointed Joseph to be their attendant, and he served them. They spent some time in custody.'
EXEC add_BibleVerse @BibleId, 101040005, N'Both of them, the cupbearer and the baker of the king of Egypt, who were confined in the prison, had a dream the same night. Each man’s dream had its own meaning.'
EXEC add_BibleVerse @BibleId, 101040006, N'When Joseph came to them in the morning, he saw that they were looking depressed.'
EXEC add_BibleVerse @BibleId, 101040007, N'So he asked Pharaoh’s officials, who were with him in custody in his master’s house, “Why do you look so sad today?”'
EXEC add_BibleVerse @BibleId, 101040008, N'They told him, “We both had dreams, but there is no one to interpret them.” Joseph responded, “Don’t interpretations belong to God? Tell them to me.”'
EXEC add_BibleVerse @BibleId, 101040009, N'So the chief cupbearer told his dream to Joseph: “In my dream, there was a vine in front of me.'
EXEC add_BibleVerse @BibleId, 101040010, N'On the vine there were three branches. As it budded, its blossoms opened and its clusters ripened into grapes.'
EXEC add_BibleVerse @BibleId, 101040011, N'Now Pharaoh’s cup was in my hand, so I took the grapes, squeezed them into his cup, and put the cup in Pharaoh’s hand.”'
EXEC add_BibleVerse @BibleId, 101040012, N'“This is its meaning,” Joseph said to him. “The three branches represent three days.'
EXEC add_BibleVerse @BibleId, 101040013, N'In three more days Pharaoh will reinstate you and restore you to your office. You will put Pharaoh’s cup in his hand, just as you did before when you were cupbearer.'
EXEC add_BibleVerse @BibleId, 101040014, N'But remember me when it goes well for you, and show me kindness. Make mention of me to Pharaoh and bring me out of this prison,'
EXEC add_BibleVerse @BibleId, 101040015, N'for I really was kidnapped from the land of the Hebrews and I have done nothing wrong here for which they should put me in a dungeon.”'
EXEC add_BibleVerse @BibleId, 101040016, N'When the chief baker saw that the interpretation of the first dream was favorable, he said to Joseph, “I also appeared in my dream and there were three baskets of white bread on my head.'
EXEC add_BibleVerse @BibleId, 101040017, N'In the top basket there were baked goods of every kind for Pharaoh, but the birds were eating them from the basket that was on my head.”'
EXEC add_BibleVerse @BibleId, 101040018, N'Joseph replied, “This is its meaning: The three baskets represent three days.'
EXEC add_BibleVerse @BibleId, 101040019, N'In three more days Pharaoh will decapitate you and impale you on a pole. Then the birds will eat your flesh from you.”'
EXEC add_BibleVerse @BibleId, 101040020, N'On the third day it was Pharaoh’s birthday, so he gave a feast for all his servants. He “lifted up” the head of the chief cupbearer and the head of the chief baker in the midst of his servants.'
EXEC add_BibleVerse @BibleId, 101040021, N'He restored the chief cupbearer to his former position so that he placed the cup in Pharaoh’s hand,'
EXEC add_BibleVerse @BibleId, 101040022, N'but the chief baker he impaled, just as Joseph had predicted.'
EXEC add_BibleVerse @BibleId, 101040023, N'But the chief cupbearer did not remember Joseph – he forgot him.'
EXEC add_BibleVerse @BibleId, 101041001, N'At the end of two full years Pharaoh had a dream. As he was standing by the Nile,'
EXEC add_BibleVerse @BibleId, 101041002, N'seven fine-looking, fat cows were coming up out of the Nile, and they grazed in the reeds.'
EXEC add_BibleVerse @BibleId, 101041003, N'Then seven bad-looking, thin cows were coming up after them from the Nile, and they stood beside the other cows at the edge of the river.'
EXEC add_BibleVerse @BibleId, 101041004, N'The bad-looking, thin cows ate the seven fine-looking, fat cows. Then Pharaoh woke up.'
EXEC add_BibleVerse @BibleId, 101041005, N'Then he fell asleep again and had a second dream: There were seven heads of grain growing on one stalk, healthy and good.'
EXEC add_BibleVerse @BibleId, 101041006, N'Then seven heads of grain, thin and burned by the east wind, were sprouting up after them.'
EXEC add_BibleVerse @BibleId, 101041007, N'The thin heads swallowed up the seven healthy and full heads. Then Pharaoh woke up and realized it was a dream.'
EXEC add_BibleVerse @BibleId, 101041008, N'In the morning he was troubled, so he called for all the diviner-priests of Egypt and all its wise men. Pharaoh told them his dreams, but no one could interpret them for him.'
EXEC add_BibleVerse @BibleId, 101041009, N'Then the chief cupbearer said to Pharaoh, “Today I recall my failures.'
EXEC add_BibleVerse @BibleId, 101041010, N'Pharaoh was enraged with his servants, and he put me in prison in the house of the captain of the guards – me and the chief baker.'
EXEC add_BibleVerse @BibleId, 101041011, N'We each had a dream one night; each of us had a dream with its own meaning.'
EXEC add_BibleVerse @BibleId, 101041012, N'Now a young man, a Hebrew, a servant of the captain of the guards, was with us there. We told him our dreams, and he interpreted the meaning of each of our respective dreams for us.'
EXEC add_BibleVerse @BibleId, 101041013, N'It happened just as he had said to us – Pharaoh restored me to my office, but he impaled the baker.”'
EXEC add_BibleVerse @BibleId, 101041014, N'Then Pharaoh summoned Joseph. So they brought him quickly out of the dungeon; he shaved himself, changed his clothes, and came before Pharaoh.'
EXEC add_BibleVerse @BibleId, 101041015, N'Pharaoh said to Joseph, “I had a dream, and there is no one who can interpret it. But I have heard about you, that you can interpret dreams.”'
EXEC add_BibleVerse @BibleId, 101041016, N'Joseph replied to Pharaoh, “It is not within my power, but God will speak concerning the welfare of Pharaoh.”'
EXEC add_BibleVerse @BibleId, 101041017, N'Then Pharaoh said to Joseph, “In my dream I was standing by the edge of the Nile.'
EXEC add_BibleVerse @BibleId, 101041018, N'Then seven fat and fine-looking cows were coming up out of the Nile, and they grazed in the reeds.'
EXEC add_BibleVerse @BibleId, 101041019, N'Then seven other cows came up after them; they were scrawny, very bad-looking, and lean. I had never seen such bad-looking cows as these in all the land of Egypt!'
EXEC add_BibleVerse @BibleId, 101041020, N'The lean, bad-looking cows ate up the seven fat cows.'
EXEC add_BibleVerse @BibleId, 101041021, N'When they had eaten them, no one would have known that they had done so, for they were just as bad-looking as before. Then I woke up.'
EXEC add_BibleVerse @BibleId, 101041022, N'I also saw in my dream seven heads of grain growing on one stalk, full and good.'
EXEC add_BibleVerse @BibleId, 101041023, N'Then seven heads of grain, withered and thin and burned with the east wind, were sprouting up after them.'
EXEC add_BibleVerse @BibleId, 101041024, N'The thin heads of grain swallowed up the seven good heads of grain. So I told all this to the diviner-priests, but no one could tell me its meaning.”'
EXEC add_BibleVerse @BibleId, 101041025, N'Then Joseph said to Pharaoh, “Both dreams of Pharaoh have the same meaning. God has revealed to Pharaoh what he is about to do.'
EXEC add_BibleVerse @BibleId, 101041026, N'The seven good cows represent seven years, and the seven good heads of grain represent seven years. Both dreams have the same meaning.'
EXEC add_BibleVerse @BibleId, 101041027, N'The seven lean, bad-looking cows that came up after them represent seven years, as do the seven empty heads of grain burned with the east wind. They represent seven years of famine.'
EXEC add_BibleVerse @BibleId, 101041028, N'This is just what I told Pharaoh: God has shown Pharaoh what he is about to do.'
EXEC add_BibleVerse @BibleId, 101041029, N'Seven years of great abundance are coming throughout the whole land of Egypt.'
EXEC add_BibleVerse @BibleId, 101041030, N'But seven years of famine will occur after them, and all the abundance will be forgotten in the land of Egypt. The famine will devastate the land.'
EXEC add_BibleVerse @BibleId, 101041031, N'The previous abundance of the land will not be remembered because of the famine that follows, for the famine will be very severe.'
EXEC add_BibleVerse @BibleId, 101041032, N'The dream was repeated to Pharaoh because the matter has been decreed by God, and God will make it happen soon.'
EXEC add_BibleVerse @BibleId, 101041033, N'“So now Pharaoh should look for a wise and discerning man and give him authority over all the land of Egypt.'
EXEC add_BibleVerse @BibleId, 101041034, N'Pharaoh should do this – he should appoint officials throughout the land to collect one-fifth of the produce of the land of Egypt during the seven years of abundance.'
EXEC add_BibleVerse @BibleId, 101041035, N'They should gather all the excess food during these good years that are coming. By Pharaoh’s authority they should store up grain so the cities will have food, and they should preserve it.'
EXEC add_BibleVerse @BibleId, 101041036, N'This food should be held in storage for the land in preparation for the seven years of famine that will occur throughout the land of Egypt. In this way the land will survive the famine.”'
EXEC add_BibleVerse @BibleId, 101041037, N'This advice made sense to Pharaoh and all his officials.'
EXEC add_BibleVerse @BibleId, 101041038, N'So Pharaoh asked his officials, “Can we find a man like Joseph, one in whom the Spirit of God is present?”'
EXEC add_BibleVerse @BibleId, 101041039, N'So Pharaoh said to Joseph, “Because God has enabled you to know all this, there is no one as wise and discerning as you are!'
EXEC add_BibleVerse @BibleId, 101041040, N'You will oversee my household, and all my people will submit to your commands. Only I, the king, will be greater than you.'
EXEC add_BibleVerse @BibleId, 101041041, N'“See here,” Pharaoh said to Joseph, “I place you in authority over all the land of Egypt.”'
EXEC add_BibleVerse @BibleId, 101041042, N'Then Pharaoh took his signet ring from his own hand and put it on Joseph’s. He clothed him with fine linen clothes and put a gold chain around his neck.'
EXEC add_BibleVerse @BibleId, 101041043, N'Pharaoh had him ride in the chariot used by his second-in-command, and they cried out before him, “Kneel down!” So he placed him over all the land of Egypt.'
EXEC add_BibleVerse @BibleId, 101041044, N'Pharaoh also said to Joseph, “I am Pharaoh, but without your permission no one will move his hand or his foot in all the land of Egypt.”'
EXEC add_BibleVerse @BibleId, 101041045, N'Pharaoh gave Joseph the name Zaphenath-Paneah. He also gave him Asenath daughter of Potiphera, priest of On, to be his wife. So Joseph took charge of all the land of Egypt.'
EXEC add_BibleVerse @BibleId, 101041046, N'Now Joseph was 30 years old when he began serving Pharaoh king of Egypt. Joseph was commissioned by Pharaoh and was in charge of all the land of Egypt.'
EXEC add_BibleVerse @BibleId, 101041047, N'During the seven years of abundance the land produced large, bountiful harvests.'
EXEC add_BibleVerse @BibleId, 101041048, N'Joseph collected all the excess food in the land of Egypt during the seven years and stored it in the cities. In every city he put the food gathered from the fields around it.'
EXEC add_BibleVerse @BibleId, 101041049, N'Joseph stored up a vast amount of grain, like the sand of the sea, until he stopped measuring it because it was impossible to measure.'
EXEC add_BibleVerse @BibleId, 101041050, N'Two sons were born to Joseph before the famine came. Asenath daughter of Potiphera, priest of On, was their mother.'
EXEC add_BibleVerse @BibleId, 101041051, N'Joseph named the firstborn Manasseh, saying, “Certainly God has made me forget all my trouble and all my father’s house.”'
EXEC add_BibleVerse @BibleId, 101041052, N'He named the second child Ephraim, saying, “Certainly God has made me fruitful in the land of my suffering.”'
EXEC add_BibleVerse @BibleId, 101041053, N'The seven years of abundance in the land of Egypt came to an end.'
EXEC add_BibleVerse @BibleId, 101041054, N'Then the seven years of famine began, just as Joseph had predicted. There was famine in all the other lands, but throughout the land of Egypt there was food.'
EXEC add_BibleVerse @BibleId, 101041055, N'When all the land of Egypt experienced the famine, the people cried out to Pharaoh for food. Pharaoh said to all the people of Egypt, “Go to Joseph and do whatever he tells you.”'
EXEC add_BibleVerse @BibleId, 101041056, N'While the famine was over all the earth, Joseph opened the storehouses and sold grain to the Egyptians. The famine was severe throughout the land of Egypt.'
EXEC add_BibleVerse @BibleId, 101041057, N'People from every country came to Joseph in Egypt to buy grain because the famine was severe throughout the earth.'
EXEC add_BibleVerse @BibleId, 101042001, N'When Jacob heard there was grain in Egypt, he said to his sons, “Why are you looking at each other?”'
EXEC add_BibleVerse @BibleId, 101042002, N'He then said, “Look, I hear that there is grain in Egypt. Go down there and buy grain for us so that we may live and not die.”'
EXEC add_BibleVerse @BibleId, 101042003, N'So ten of Joseph’s brothers went down to buy grain from Egypt.'
EXEC add_BibleVerse @BibleId, 101042004, N'But Jacob did not send Joseph’s brother Benjamin with his brothers, for he said, “What if some accident happens to him?”'
EXEC add_BibleVerse @BibleId, 101042005, N'So Israel’s sons came to buy grain among the other travelers, for the famine was severe in the land of Canaan.'
EXEC add_BibleVerse @BibleId, 101042006, N'Now Joseph was the ruler of the country, the one who sold grain to all the people of the country. Joseph’s brothers came and bowed down before him with their faces to the ground.'
EXEC add_BibleVerse @BibleId, 101042007, N'When Joseph saw his brothers, he recognized them, but he pretended to be a stranger to them and spoke to them harshly. He asked, “Where do you come from?” They answered, “From the land of Canaan, to buy grain for food.”'
EXEC add_BibleVerse @BibleId, 101042008, N'Joseph recognized his brothers, but they did not recognize him.'
EXEC add_BibleVerse @BibleId, 101042009, N'Then Joseph remembered the dreams he had dreamed about them, and he said to them, “You are spies; you have come to see if our land is vulnerable!”'
EXEC add_BibleVerse @BibleId, 101042010, N'But they exclaimed, “No, my lord! Your servants have come to buy grain for food!'
EXEC add_BibleVerse @BibleId, 101042011, N'We are all the sons of one man; we are honest men! Your servants are not spies.”'
EXEC add_BibleVerse @BibleId, 101042012, N'“No,” he insisted, “but you have come to see if our land is vulnerable.”'
EXEC add_BibleVerse @BibleId, 101042013, N'They replied, “Your servants are from a family of twelve brothers. We are the sons of one man in the land of Canaan. The youngest is with our father at this time, and one is no longer alive.”'
EXEC add_BibleVerse @BibleId, 101042014, N'But Joseph told them, “It is just as I said to you: You are spies!'
EXEC add_BibleVerse @BibleId, 101042015, N'You will be tested in this way: As surely as Pharaoh lives, you will not depart from this place unless your youngest brother comes here.'
EXEC add_BibleVerse @BibleId, 101042016, N'One of you must go and get your brother, while the rest of you remain in prison. In this way your words may be tested to see if you are telling the truth. If not, then, as surely as Pharaoh lives, you are spies!”'
EXEC add_BibleVerse @BibleId, 101042017, N'He imprisoned them all for three days.'
EXEC add_BibleVerse @BibleId, 101042018, N'On the third day Joseph said to them, “Do as I say and you will live, for I fear God.'
EXEC add_BibleVerse @BibleId, 101042019, N'If you are honest men, leave one of your brothers confined here in prison while the rest of you go and take grain back for your hungry families.'
EXEC add_BibleVerse @BibleId, 101042020, N'But you must bring your youngest brother to me. Then your words will be verified and you will not die.” They did as he said.'
EXEC add_BibleVerse @BibleId, 101042021, N'They said to one other, “Surely we’re being punished because of our brother, because we saw how distressed he was when he cried to us for mercy, but we refused to listen. That is why this distress has come on us!”'
EXEC add_BibleVerse @BibleId, 101042022, N'Reuben said to them, “Didn’t I say to you, ‘Don’t sin against the boy,’ but you wouldn’t listen? So now we must pay for shedding his blood!”'
EXEC add_BibleVerse @BibleId, 101042023, N'(Now they did not know that Joseph could understand them, for he was speaking through an interpreter.)'
EXEC add_BibleVerse @BibleId, 101042024, N'He turned away from them and wept. When he turned around and spoke to them again, he had Simeon taken from them and tied up before their eyes.'
EXEC add_BibleVerse @BibleId, 101042025, N'Then Joseph gave orders to fill their bags with grain, to return each man’s money to his sack, and to give them provisions for the journey. His orders were carried out.'
EXEC add_BibleVerse @BibleId, 101042026, N'So they loaded their grain on their donkeys and left.'
EXEC add_BibleVerse @BibleId, 101042027, N'When one of them opened his sack to get feed for his donkey at their resting place, he saw his money in the mouth of his sack.'
EXEC add_BibleVerse @BibleId, 101042028, N'He said to his brothers, “My money was returned! Here it is in my sack!” They were dismayed; they turned trembling one to another and said, “What in the world has God done to us?”'
EXEC add_BibleVerse @BibleId, 101042029, N'They returned to their father Jacob in the land of Canaan and told him all the things that had happened to them, saying,'
EXEC add_BibleVerse @BibleId, 101042030, N'“The man, the lord of the land, spoke harshly to us and treated us as if we were spying on the land.'
EXEC add_BibleVerse @BibleId, 101042031, N'But we said to him, ‘We are honest men; we are not spies!'
EXEC add_BibleVerse @BibleId, 101042032, N'We are from a family of twelve brothers; we are the sons of one father. One is no longer alive, and the youngest is with our father at this time in the land of Canaan.’'
EXEC add_BibleVerse @BibleId, 101042033, N'“Then the man, the lord of the land, said to us, ‘This is how I will find out if you are honest men. Leave one of your brothers with me, and take grain for your hungry households and go.'
EXEC add_BibleVerse @BibleId, 101042034, N'But bring your youngest brother back to me so I will know that you are honest men and not spies. Then I will give your brother back to you and you may move about freely in the land.’”'
EXEC add_BibleVerse @BibleId, 101042035, N'When they were emptying their sacks, there was each man’s bag of money in his sack! When they and their father saw the bags of money, they were afraid.'
EXEC add_BibleVerse @BibleId, 101042036, N'Their father Jacob said to them, “You are making me childless! Joseph is gone. Simeon is gone. And now you want to take Benjamin! Everything is against me.”'
EXEC add_BibleVerse @BibleId, 101042037, N'Then Reuben said to his father, “You may put my two sons to death if I do not bring him back to you. Put him in my care and I will bring him back to you.”'
EXEC add_BibleVerse @BibleId, 101042038, N'But Jacob replied, “My son will not go down there with you, for his brother is dead and he alone is left. If an accident happens to him on the journey you have to make, then you will bring down my gray hair in sorrow to the grave.”'
EXEC add_BibleVerse @BibleId, 101043001, N'Now the famine was severe in the land.'
EXEC add_BibleVerse @BibleId, 101043002, N'When they finished eating the grain they had brought from Egypt, their father said to them, “Return, buy us a little more food.”'
EXEC add_BibleVerse @BibleId, 101043003, N'But Judah said to him, “The man solemnly warned us, ‘You will not see my face unless your brother is with you.’'
EXEC add_BibleVerse @BibleId, 101043004, N'If you send our brother with us, we’ll go down and buy food for you.'
EXEC add_BibleVerse @BibleId, 101043005, N'But if you will not send him, we won’t go down there because the man said to us, ‘You will not see my face unless your brother is with you.’”'
EXEC add_BibleVerse @BibleId, 101043006, N'Israel said, “Why did you bring this trouble on me by telling the man you had one more brother?”'
EXEC add_BibleVerse @BibleId, 101043007, N'They replied, “The man questioned us thoroughly about ourselves and our family, saying, ‘Is your father still alive? Do you have another brother?’ So we answered him in this way. How could we possibly know that he would say, ‘Bring your brother down’?”'
EXEC add_BibleVerse @BibleId, 101043008, N'Then Judah said to his father Israel, “Send the boy with me and we will go immediately. Then we will live and not die – we and you and our little ones.'
EXEC add_BibleVerse @BibleId, 101043009, N'I myself pledge security for him; you may hold me liable. If I do not bring him back to you and place him here before you, I will bear the blame before you all my life.'
EXEC add_BibleVerse @BibleId, 101043010, N'But if we had not delayed, we could have traveled there and back twice by now!”'
EXEC add_BibleVerse @BibleId, 101043011, N'Then their father Israel said to them, “If it must be so, then do this: Take some of the best products of the land in your bags, and take a gift down to the man – a little balm and a little honey, spices and myrrh, pistachios and almonds.'
EXEC add_BibleVerse @BibleId, 101043012, N'Take double the money with you; you must take back the money that was returned in the mouths of your sacks – perhaps it was an oversight.'
EXEC add_BibleVerse @BibleId, 101043013, N'Take your brother too, and go right away to the man.'
EXEC add_BibleVerse @BibleId, 101043014, N'May the sovereign God grant you mercy before the man so that he may release your other brother and Benjamin! As for me, if I lose my children I lose them.”'
EXEC add_BibleVerse @BibleId, 101043015, N'So the men took these gifts, and they took double the money with them, along with Benjamin. Then they hurried down to Egypt and stood before Joseph.'
EXEC add_BibleVerse @BibleId, 101043016, N'When Joseph saw Benjamin with them, he said to the servant who was over his household, “Bring the men to the house. Slaughter an animal and prepare it, for the men will eat with me at noon.”'
EXEC add_BibleVerse @BibleId, 101043017, N'The man did just as Joseph said; he brought the men into Joseph’s house.'
EXEC add_BibleVerse @BibleId, 101043018, N'But the men were afraid when they were brought to Joseph’s house. They said, “We are being brought in because of the money that was returned in our sacks last time. He wants to capture us, make us slaves, and take our donkeys!”'
EXEC add_BibleVerse @BibleId, 101043019, N'So they approached the man who was in charge of Joseph’s household and spoke to him at the entrance to the house.'
EXEC add_BibleVerse @BibleId, 101043020, N'They said, “My lord, we did indeed come down the first time to buy food.'
EXEC add_BibleVerse @BibleId, 101043021, N'But when we came to the place where we spent the night, we opened our sacks and each of us found his money – the full amount – in the mouth of his sack. So we have returned it.'
EXEC add_BibleVerse @BibleId, 101043022, N'We have brought additional money with us to buy food. We do not know who put the money in our sacks!”'
EXEC add_BibleVerse @BibleId, 101043023, N'“Everything is fine,” the man in charge of Joseph’s household told them. “Don’t be afraid. Your God and the God of your father has given you treasure in your sacks. I had your money.” Then he brought Simeon out to them.'
EXEC add_BibleVerse @BibleId, 101043024, N'The servant in charge brought the men into Joseph’s house. He gave them water, and they washed their feet. Then he gave food to their donkeys.'
EXEC add_BibleVerse @BibleId, 101043025, N'They got their gifts ready for Joseph’s arrival at noon, for they had heard that they were to have a meal there.'
EXEC add_BibleVerse @BibleId, 101043026, N'When Joseph came home, they presented him with the gifts they had brought inside, and they bowed down to the ground before him.'
EXEC add_BibleVerse @BibleId, 101043027, N'He asked them how they were doing. Then he said, “Is your aging father well, the one you spoke about? Is he still alive?”'
EXEC add_BibleVerse @BibleId, 101043028, N'“Your servant our father is well,” they replied. “He is still alive.” They bowed down in humility.'
EXEC add_BibleVerse @BibleId, 101043029, N'When Joseph looked up and saw his brother Benjamin, his mother’s son, he said, “Is this your youngest brother, whom you told me about?” Then he said, “May God be gracious to you, my son.”'
EXEC add_BibleVerse @BibleId, 101043030, N'Joseph hurried out, for he was overcome by affection for his brother and was at the point of tears. So he went to his room and wept there.'
EXEC add_BibleVerse @BibleId, 101043031, N'Then he washed his face and came out. With composure he said, “Set out the food.”'
EXEC add_BibleVerse @BibleId, 101043032, N'They set a place for him, a separate place for his brothers, and another for the Egyptians who were eating with him. (The Egyptians are not able to eat with Hebrews, for the Egyptians think it is disgusting to do so.)'
EXEC add_BibleVerse @BibleId, 101043033, N'They sat before him, arranged by order of birth, beginning with the firstborn and ending with the youngest. The men looked at each other in astonishment.'
EXEC add_BibleVerse @BibleId, 101043034, N'He gave them portions of the food set before him, but the portion for Benjamin was five times greater than the portions for any of the others. They drank with Joseph until they all became drunk.'
EXEC add_BibleVerse @BibleId, 101044001, N'He instructed the servant who was over his household, “Fill the sacks of the men with as much food as they can carry and put each man’s money in the mouth of his sack.'
EXEC add_BibleVerse @BibleId, 101044002, N'Then put my cup – the silver cup – in the mouth of the youngest one’s sack, along with the money for his grain.” He did as Joseph instructed.'
EXEC add_BibleVerse @BibleId, 101044003, N'When morning came, the men and their donkeys were sent off.'
EXEC add_BibleVerse @BibleId, 101044004, N'They had not gone very far from the city when Joseph said to the servant who was over his household, “Pursue the men at once! When you overtake them, say to them, ‘Why have you repaid good with evil?'
EXEC add_BibleVerse @BibleId, 101044005, N'Doesn’t my master drink from this cup and use it for divination? You have done wrong!’”'
EXEC add_BibleVerse @BibleId, 101044006, N'When the man overtook them, he spoke these words to them.'
EXEC add_BibleVerse @BibleId, 101044007, N'They answered him, “Why does my lord say such things? Far be it from your servants to do such a thing!'
EXEC add_BibleVerse @BibleId, 101044008, N'Look, the money that we found in the mouths of our sacks we brought back to you from the land of Canaan. Why then would we steal silver or gold from your master’s house?'
EXEC add_BibleVerse @BibleId, 101044009, N'If one of us has it, he will die, and the rest of us will become my lord’s slaves!”'
EXEC add_BibleVerse @BibleId, 101044010, N'He replied, “You have suggested your own punishment! The one who has it will become my slave, but the rest of you will go free.”'
EXEC add_BibleVerse @BibleId, 101044011, N'So each man quickly lowered his sack to the ground and opened it.'
EXEC add_BibleVerse @BibleId, 101044012, N'Then the man searched. He began with the oldest and finished with the youngest. The cup was found in Benjamin’s sack!'
EXEC add_BibleVerse @BibleId, 101044013, N'They all tore their clothes! Then each man loaded his donkey, and they returned to the city.'
EXEC add_BibleVerse @BibleId, 101044014, N'So Judah and his brothers came back to Joseph’s house. He was still there, and they threw themselves to the ground before him.'
EXEC add_BibleVerse @BibleId, 101044015, N'Joseph said to them, “What did you think you were doing? Don’t you know that a man like me can find out things like this by divination?”'
EXEC add_BibleVerse @BibleId, 101044016, N'Judah replied, “What can we say to my lord? What can we speak? How can we clear ourselves? God has exposed the sin of your servants! We are now my lord’s slaves, we and the one in whose possession the cup was found.”'
EXEC add_BibleVerse @BibleId, 101044017, N'But Joseph said, “Far be it from me to do this! The man in whose hand the cup was found will become my slave, but the rest of you may go back to your father in peace.”'
EXEC add_BibleVerse @BibleId, 101044018, N'Then Judah approached him and said, “My lord, please allow your servant to speak a word with you. Please do not get angry with your servant, for you are just like Pharaoh.'
EXEC add_BibleVerse @BibleId, 101044019, N'My lord asked his servants, ‘Do you have a father or a brother?’'
EXEC add_BibleVerse @BibleId, 101044020, N'We said to my lord, ‘We have an aged father, and there is a young boy who was born when our father was old. The boy’s brother is dead. He is the only one of his mother’s sons left, and his father loves him.’'
EXEC add_BibleVerse @BibleId, 101044021, N'“Then you told your servants, ‘Bring him down to me so I can see him.’'
EXEC add_BibleVerse @BibleId, 101044022, N'We said to my lord, ‘The boy cannot leave his father. If he leaves his father, his father will die.’'
EXEC add_BibleVerse @BibleId, 101044023, N'But you said to your servants, ‘If your youngest brother does not come down with you, you will not see my face again.’'
EXEC add_BibleVerse @BibleId, 101044024, N'When we returned to your servant my father, we told him the words of my lord.'
EXEC add_BibleVerse @BibleId, 101044025, N'“Then our father said, ‘Go back and buy us a little food.’'
EXEC add_BibleVerse @BibleId, 101044026, N'But we replied, ‘We cannot go down there. If our youngest brother is with us, then we will go, for we won’t be permitted to see the man’s face if our youngest brother is not with us.’'
EXEC add_BibleVerse @BibleId, 101044027, N'“Then your servant my father said to us, ‘You know that my wife gave me two sons.'
EXEC add_BibleVerse @BibleId, 101044028, N'The first disappeared and I said, “He has surely been torn to pieces.” I have not seen him since.'
EXEC add_BibleVerse @BibleId, 101044029, N'If you take this one from me too and an accident happens to him, then you will bring down my gray hair in tragedy to the grave.’'
EXEC add_BibleVerse @BibleId, 101044030, N'“So now, when I return to your servant my father, and the boy is not with us – his very life is bound up in his son’s life.'
EXEC add_BibleVerse @BibleId, 101044031, N'When he sees the boy is not with us, he will die, and your servants will bring down the gray hair of your servant our father in sorrow to the grave.'
EXEC add_BibleVerse @BibleId, 101044032, N'Indeed, your servant pledged security for the boy with my father, saying, ‘If I do not bring him back to you, then I will bear the blame before my father all my life.’'
EXEC add_BibleVerse @BibleId, 101044033, N'“So now, please let your servant remain as my lord’s slave instead of the boy. As for the boy, let him go back with his brothers.'
EXEC add_BibleVerse @BibleId, 101044034, N'For how can I go back to my father if the boy is not with me? I couldn’t bear to see my father’s pain.”'
EXEC add_BibleVerse @BibleId, 101045001, N'Joseph was no longer able to control himself before all his attendants, so he cried out, “Make everyone go out from my presence!” No one remained with Joseph when he made himself known to his brothers.'
EXEC add_BibleVerse @BibleId, 101045002, N'He wept loudly; the Egyptians heard it and Pharaoh’s household heard about it.'
EXEC add_BibleVerse @BibleId, 101045003, N'Joseph said to his brothers, “I am Joseph! Is my father still alive?” His brothers could not answer him because they were dumbfounded before him.'
EXEC add_BibleVerse @BibleId, 101045004, N'Joseph said to his brothers, “Come closer to me,” so they came near. Then he said, “I am Joseph your brother, whom you sold into Egypt.'
EXEC add_BibleVerse @BibleId, 101045005, N'Now, do not be upset and do not be angry with yourselves because you sold me here, for God sent me ahead of you to preserve life!'
EXEC add_BibleVerse @BibleId, 101045006, N'For these past two years there has been famine in the land and for five more years there will be neither plowing nor harvesting.'
EXEC add_BibleVerse @BibleId, 101045007, N'God sent me ahead of you to preserve you on the earth and to save your lives by a great deliverance.'
EXEC add_BibleVerse @BibleId, 101045008, N'So now, it is not you who sent me here, but God. He has made me an adviser to Pharaoh, lord over all his household, and ruler over all the land of Egypt.'
EXEC add_BibleVerse @BibleId, 101045009, N'Now go up to my father quickly and tell him, ‘This is what your son Joseph says: “God has made me lord of all Egypt. Come down to me; do not delay!'
EXEC add_BibleVerse @BibleId, 101045010, N'You will live in the land of Goshen, and you will be near me – you, your children, your grandchildren, your flocks, your herds, and everything you have.'
EXEC add_BibleVerse @BibleId, 101045011, N'I will provide you with food there because there will be five more years of famine. Otherwise you would become poor – you, your household, and everyone who belongs to you.”’'
EXEC add_BibleVerse @BibleId, 101045012, N'You and my brother Benjamin can certainly see with your own eyes that I really am the one who speaks to you.'
EXEC add_BibleVerse @BibleId, 101045013, N'So tell my father about all my honor in Egypt and about everything you have seen. But bring my father down here quickly!”'
EXEC add_BibleVerse @BibleId, 101045014, N'Then he threw himself on the neck of his brother Benjamin and wept, and Benjamin wept on his neck.'
EXEC add_BibleVerse @BibleId, 101045015, N'He kissed all his brothers and wept over them. After this his brothers talked with him.'
EXEC add_BibleVerse @BibleId, 101045016, N'Now it was reported in the household of Pharaoh, “Joseph’s brothers have arrived.” It pleased Pharaoh and his servants.'
EXEC add_BibleVerse @BibleId, 101045017, N'Pharaoh said to Joseph, “Say to your brothers, ‘Do this: Load your animals and go to the land of Canaan!'
EXEC add_BibleVerse @BibleId, 101045018, N'Get your father and your households and come to me! Then I will give you the best land in Egypt and you will eat the best of the land.’'
EXEC add_BibleVerse @BibleId, 101045019, N'You are also commanded to say, ‘Do this: Take for yourselves wagons from the land of Egypt for your little ones and for your wives. Bring your father and come.'
EXEC add_BibleVerse @BibleId, 101045020, N'Don’t worry about your belongings, for the best of all the land of Egypt will be yours.’”'
EXEC add_BibleVerse @BibleId, 101045021, N'So the sons of Israel did as he said. Joseph gave them wagons as Pharaoh had instructed, and he gave them provisions for the journey.'
EXEC add_BibleVerse @BibleId, 101045022, N'He gave sets of clothes to each one of them, but to Benjamin he gave three hundred pieces of silver and five sets of clothes.'
EXEC add_BibleVerse @BibleId, 101045023, N'To his father he sent the following: ten donkeys loaded with the best products of Egypt and ten female donkeys loaded with grain, food, and provisions for his father’s journey.'
EXEC add_BibleVerse @BibleId, 101045024, N'Then he sent his brothers on their way and they left. He said to them, “As you travel don’t be overcome with fear.”'
EXEC add_BibleVerse @BibleId, 101045025, N'So they went up from Egypt and came to their father Jacob in the land of Canaan.'
EXEC add_BibleVerse @BibleId, 101045026, N'They told him, “Joseph is still alive and he is ruler over all the land of Egypt!” Jacob was stunned, for he did not believe them.'
EXEC add_BibleVerse @BibleId, 101045027, N'But when they related to him everything Joseph had said to them, and when he saw the wagons that Joseph had sent to transport him, their father Jacob’s spirit revived.'
EXEC add_BibleVerse @BibleId, 101045028, N'Then Israel said, “Enough! My son Joseph is still alive! I will go and see him before I die.”'
EXEC add_BibleVerse @BibleId, 101046001, N'So Israel began his journey, taking with him all that he had. When he came to Beer Sheba he offered sacrifices to the God of his father Isaac.'
EXEC add_BibleVerse @BibleId, 101046002, N'God spoke to Israel in a vision during the night and said, “Jacob, Jacob!” He replied, “Here I am!”'
EXEC add_BibleVerse @BibleId, 101046003, N'He said, “I am God, the God of your father. Do not be afraid to go down to Egypt, for I will make you into a great nation there.'
EXEC add_BibleVerse @BibleId, 101046004, N'I will go down with you to Egypt and I myself will certainly bring you back from there. Joseph will close your eyes.”'
EXEC add_BibleVerse @BibleId, 101046005, N'Then Jacob started out from Beer Sheba, and the sons of Israel carried their father Jacob, their little children, and their wives in the wagons that Pharaoh had sent along to transport him.'
EXEC add_BibleVerse @BibleId, 101046006, N'Jacob and all his descendants took their livestock and the possessions they had acquired in the land of Canaan, and they went to Egypt.'
EXEC add_BibleVerse @BibleId, 101046007, N'He brought with him to Egypt his sons and grandsons, his daughters and granddaughters – all his descendants.'
EXEC add_BibleVerse @BibleId, 101046008, N'These are the names of the sons of Israel who went to Egypt – Jacob and his sons: Reuben, the firstborn of Jacob.'
EXEC add_BibleVerse @BibleId, 101046009, N'The sons of Reuben: Hanoch, Pallu, Hezron, and Carmi.'
EXEC add_BibleVerse @BibleId, 101046010, N'The sons of Simeon: Jemuel, Jamin, Ohad, Jakin, Zohar, and Shaul (the son of a Canaanite woman).'
EXEC add_BibleVerse @BibleId, 101046011, N'The sons of Levi: Gershon, Kohath, and Merari.'
EXEC add_BibleVerse @BibleId, 101046012, N'The sons of Judah: Er, Onan, Shelah, Perez, and Zerah (but Er and Onan died in the land of Canaan). The sons of Perez were Hezron and Hamul.'
EXEC add_BibleVerse @BibleId, 101046013, N'The sons of Issachar: Tola, Puah, Jashub, and Shimron.'
EXEC add_BibleVerse @BibleId, 101046014, N'The sons of Zebulun: Sered, Elon, and Jahleel.'
EXEC add_BibleVerse @BibleId, 101046015, N'These were the sons of Leah, whom she bore to Jacob in Paddan Aram, along with Dinah his daughter. His sons and daughters numbered thirty-three in all.'
EXEC add_BibleVerse @BibleId, 101046016, N'The sons of Gad: Zephon, Haggi, Shuni, Ezbon, Eri, Arodi, and Areli.'
EXEC add_BibleVerse @BibleId, 101046017, N'The sons of Asher: Imnah, Ishvah, Ishvi, Beriah, and Serah their sister. The sons of Beriah were Heber and Malkiel.'
EXEC add_BibleVerse @BibleId, 101046018, N'These were the sons of Zilpah, whom Laban gave to Leah his daughter. She bore these to Jacob, sixteen in all.'
EXEC add_BibleVerse @BibleId, 101046019, N'The sons of Rachel the wife of Jacob: Joseph and Benjamin.'
EXEC add_BibleVerse @BibleId, 101046020, N'Manasseh and Ephraim were born to Joseph in the land of Egypt. Asenath daughter of Potiphera, priest of On, bore them to him.'
EXEC add_BibleVerse @BibleId, 101046021, N'The sons of Benjamin: Bela, Beker, Ashbel, Gera, Naaman, Ehi, Rosh, Muppim, Huppim and Ard.'
EXEC add_BibleVerse @BibleId, 101046022, N'These were the sons of Rachel who were born to Jacob, fourteen in all.'
EXEC add_BibleVerse @BibleId, 101046023, N'The son of Dan: Hushim.'
EXEC add_BibleVerse @BibleId, 101046024, N'The sons of Naphtali: Jahziel, Guni, Jezer, and Shillem.'
EXEC add_BibleVerse @BibleId, 101046025, N'These were the sons of Bilhah, whom Laban gave to Rachel his daughter. She bore these to Jacob, seven in all.'
EXEC add_BibleVerse @BibleId, 101046026, N'All the direct descendants of Jacob who went to Egypt with him were sixty-six in number. (This number does not include the wives of Jacob’s sons.)'
EXEC add_BibleVerse @BibleId, 101046027, N'Counting the two sons of Joseph who were born to him in Egypt, all the people of the household of Jacob who were in Egypt numbered seventy.'
EXEC add_BibleVerse @BibleId, 101046028, N'Jacob sent Judah before him to Joseph to accompany him to Goshen. So they came to the land of Goshen.'
EXEC add_BibleVerse @BibleId, 101046029, N'Joseph harnessed his chariot and went up to meet his father Israel in Goshen. When he met him, he hugged his neck and wept on his neck for quite some time.'
EXEC add_BibleVerse @BibleId, 101046030, N'Israel said to Joseph, “Now let me die since I have seen your face and know that you are still alive.”'
EXEC add_BibleVerse @BibleId, 101046031, N'Then Joseph said to his brothers and his father’s household, “I will go up and tell Pharaoh, ‘My brothers and my father’s household who were in the land of Canaan have come to me.'
EXEC add_BibleVerse @BibleId, 101046032, N'The men are shepherds; they take care of livestock. They have brought their flocks and their herds and all that they have.’'
EXEC add_BibleVerse @BibleId, 101046033, N'Pharaoh will summon you and say, ‘What is your occupation?’'
EXEC add_BibleVerse @BibleId, 101046034, N'Tell him, ‘Your servants have taken care of cattle from our youth until now, both we and our fathers,’ so that you may live in the land of Goshen, for everyone who takes care of sheep is disgusting to the Egyptians.”'
EXEC add_BibleVerse @BibleId, 101047001, N'Joseph went and told Pharaoh, “My father, my brothers, their flocks and herds, and all that they own have arrived from the land of Canaan. They are now in the land of Goshen.”'
EXEC add_BibleVerse @BibleId, 101047002, N'He took five of his brothers and introduced them to Pharaoh.'
EXEC add_BibleVerse @BibleId, 101047003, N'Pharaoh said to Joseph’s brothers, “What is your occupation?” They said to Pharaoh, “Your servants take care of flocks, just as our ancestors did.”'
EXEC add_BibleVerse @BibleId, 101047004, N'Then they said to Pharaoh, “We have come to live as temporary residents in the land. There is no pasture for your servants’ flocks because the famine is severe in the land of Canaan. So now, please let your servants live in the land of Goshen.”'
EXEC add_BibleVerse @BibleId, 101047005, N'Pharaoh said to Joseph, “Your father and your brothers have come to you.'
EXEC add_BibleVerse @BibleId, 101047006, N'The land of Egypt is before you; settle your father and your brothers in the best region of the land. They may live in the land of Goshen. If you know of any highly capable men among them, put them in charge of my livestock.”'
EXEC add_BibleVerse @BibleId, 101047007, N'Then Joseph brought in his father Jacob and presented him before Pharaoh. Jacob blessed Pharaoh.'
EXEC add_BibleVerse @BibleId, 101047008, N'Pharaoh said to Jacob, “How long have you lived?”'
EXEC add_BibleVerse @BibleId, 101047009, N'Jacob said to Pharaoh, “All the years of my travels are 130. All the years of my life have been few and painful; the years of my travels are not as long as those of my ancestors.”'
EXEC add_BibleVerse @BibleId, 101047010, N'Then Jacob blessed Pharaoh and went out from his presence.'
EXEC add_BibleVerse @BibleId, 101047011, N'So Joseph settled his father and his brothers. He gave them territory in the land of Egypt, in the best region of the land, the land of Rameses, just as Pharaoh had commanded.'
EXEC add_BibleVerse @BibleId, 101047012, N'Joseph also provided food for his father, his brothers, and all his father’s household, according to the number of their little children.'
EXEC add_BibleVerse @BibleId, 101047013, N'But there was no food in all the land because the famine was very severe; the land of Egypt and the land of Canaan wasted away because of the famine.'
EXEC add_BibleVerse @BibleId, 101047014, N'Joseph collected all the money that could be found in the land of Egypt and in the land of Canaan as payment for the grain they were buying. Then Joseph brought the money into Pharaoh’s palace.'
EXEC add_BibleVerse @BibleId, 101047015, N'When the money from the lands of Egypt and Canaan was used up, all the Egyptians came to Joseph and said, “Give us food! Why should we die before your very eyes because our money has run out?”'
EXEC add_BibleVerse @BibleId, 101047016, N'Then Joseph said, “If your money is gone, bring your livestock, and I will give you food in exchange for your livestock.”'
EXEC add_BibleVerse @BibleId, 101047017, N'So they brought their livestock to Joseph, and Joseph gave them food in exchange for their horses, the livestock of their flocks and herds, and their donkeys. He got them through that year by giving them food in exchange for livestock.'
EXEC add_BibleVerse @BibleId, 101047018, N'When that year was over, they came to him the next year and said to him, “We cannot hide from our lord that the money is used up and the livestock and the animals belong to our lord. Nothing remains before our lord except our bodies and our land.'
EXEC add_BibleVerse @BibleId, 101047019, N'Why should we die before your very eyes, both we and our land? Buy us and our land in exchange for food, and we, with our land, will become Pharaoh’s slaves. Give us seed that we may live and not die. Then the land will not become desolate.”'
EXEC add_BibleVerse @BibleId, 101047020, N'So Joseph bought all the land of Egypt for Pharaoh. Each of the Egyptians sold his field, for the famine was severe. So the land became Pharaoh’s.'
EXEC add_BibleVerse @BibleId, 101047021, N'Joseph made all the people slaves from one end of Egypt’s border to the other end of it.'
EXEC add_BibleVerse @BibleId, 101047022, N'But he did not purchase the land of the priests because the priests had an allotment from Pharaoh and they ate from their allotment that Pharaoh gave them. That is why they did not sell their land.'
EXEC add_BibleVerse @BibleId, 101047023, N'Joseph said to the people, “Since I have bought you and your land today for Pharaoh, here is seed for you. Cultivate the land.'
EXEC add_BibleVerse @BibleId, 101047024, N'When you gather in the crop, give one-fifth of it to Pharaoh, and the rest will be yours for seed for the fields and for you to eat, including those in your households and your little children.”'
EXEC add_BibleVerse @BibleId, 101047025, N'They replied, “You have saved our lives! You are showing us favor, and we will be Pharaoh’s slaves.”'
EXEC add_BibleVerse @BibleId, 101047026, N'So Joseph made it a statute, which is in effect to this day throughout the land of Egypt: One-fifth belongs to Pharaoh. Only the land of the priests did not become Pharaoh’s.'
EXEC add_BibleVerse @BibleId, 101047027, N'Israel settled in the land of Egypt, in the land of Goshen, and they owned land there. They were fruitful and increased rapidly in number.'
EXEC add_BibleVerse @BibleId, 101047028, N'Jacob lived in the land of Egypt seventeen years; the years of Jacob’s life were 147 in all.'
EXEC add_BibleVerse @BibleId, 101047029, N'The time for Israel to die approached, so he called for his son Joseph and said to him, “If now I have found favor in your sight, put your hand under my thigh and show me kindness and faithfulness. Do not bury me in Egypt,'
EXEC add_BibleVerse @BibleId, 101047030, N'but when I rest with my fathers, carry me out of Egypt and bury me in their burial place.” Joseph said, “I will do as you say.”'
EXEC add_BibleVerse @BibleId, 101047031, N'Jacob said, “Swear to me that you will do so.” So Joseph gave him his word. Then Israel bowed down at the head of his bed.'
EXEC add_BibleVerse @BibleId, 101048001, N'After these things Joseph was told, “Your father is weakening.” So he took his two sons Manasseh and Ephraim with him.'
EXEC add_BibleVerse @BibleId, 101048002, N'When Jacob was told, “Your son Joseph has just come to you,” Israel regained strength and sat up on his bed.'
EXEC add_BibleVerse @BibleId, 101048003, N'Jacob said to Joseph, “The sovereign God appeared to me at Luz in the land of Canaan and blessed me.'
EXEC add_BibleVerse @BibleId, 101048004, N'He said to me, ‘I am going to make you fruitful and will multiply you. I will make you into a group of nations, and I will give this land to your descendants as an everlasting possession.’'
EXEC add_BibleVerse @BibleId, 101048005, N'“Now, as for your two sons, who were born to you in the land of Egypt before I came to you in Egypt, they will be mine. Ephraim and Manasseh will be mine just as Reuben and Simeon are.'
EXEC add_BibleVerse @BibleId, 101048006, N'Any children that you father after them will be yours; they will be listed under the names of their brothers in their inheritance.'
EXEC add_BibleVerse @BibleId, 101048007, N'But as for me, when I was returning from Paddan, Rachel died – to my sorrow – in the land of Canaan. It happened along the way, some distance from Ephrath. So I buried her there on the way to Ephrath” (that is, Bethlehem).'
EXEC add_BibleVerse @BibleId, 101048008, N'When Israel saw Joseph’s sons, he asked, “Who are these?”'
EXEC add_BibleVerse @BibleId, 101048009, N'Joseph said to his father, “They are the sons God has given me in this place.” His father said, “Bring them to me so I may bless them.”'
EXEC add_BibleVerse @BibleId, 101048010, N'Now Israel’s eyes were failing because of his age; he was not able to see well. So Joseph brought his sons near to him, and his father kissed them and embraced them.'
EXEC add_BibleVerse @BibleId, 101048011, N'Israel said to Joseph, “I never expected to see you again, but now God has allowed me to see your children too.”'
EXEC add_BibleVerse @BibleId, 101048012, N'So Joseph moved them from Israel’s knees and bowed down with his face to the ground.'
EXEC add_BibleVerse @BibleId, 101048013, N'Joseph positioned them; he put Ephraim on his right hand across from Israel’s left hand, and Manasseh on his left hand across from Israel’s right hand. Then Joseph brought them closer to his father.'
EXEC add_BibleVerse @BibleId, 101048014, N'Israel stretched out his right hand and placed it on Ephraim’s head, although he was the younger. Crossing his hands, he put his left hand on Manasseh’s head, for Manasseh was the firstborn.'
EXEC add_BibleVerse @BibleId, 101048015, N'Then he blessed Joseph and said, “May the God before whom my fathers Abraham and Isaac walked – the God who has been my shepherd all my life long to this day,'
EXEC add_BibleVerse @BibleId, 101048016, N'the Angel who has protected me from all harm – bless these boys. May my name be named in them, and the name of my fathers Abraham and Isaac. May they grow into a multitude on the earth.”'
EXEC add_BibleVerse @BibleId, 101048017, N'When Joseph saw that his father placed his right hand on Ephraim’s head, it displeased him. So he took his father’s hand to move it from Ephraim’s head to Manasseh’s head.'
EXEC add_BibleVerse @BibleId, 101048018, N'Joseph said to his father, “Not so, my father, for this is the firstborn. Put your right hand on his head.”'
EXEC add_BibleVerse @BibleId, 101048019, N'But his father refused and said, “I know, my son, I know. He too will become a nation and he too will become great. In spite of this, his younger brother will be even greater and his descendants will become a multitude of nations.”'
EXEC add_BibleVerse @BibleId, 101048020, N'So he blessed them that day, saying, “By you will Israel bless, saying, ‘May God make you like Ephraim and Manasseh.’” So he put Ephraim before Manasseh.'
EXEC add_BibleVerse @BibleId, 101048021, N'Then Israel said to Joseph, “I am about to die, but God will be with you and will bring you back to the land of your fathers.'
EXEC add_BibleVerse @BibleId, 101048022, N'As one who is above your brothers, I give to you the mountain slope, which I took from the Amorites with my sword and my bow.”'
EXEC add_BibleVerse @BibleId, 101049001, N'Jacob called for his sons and said, “Gather together so I can tell you what will happen to you in the future.'
EXEC add_BibleVerse @BibleId, 101049002, N'“Assemble and listen, you sons of Jacob; listen to Israel, your father.'
EXEC add_BibleVerse @BibleId, 101049003, N'Reuben, you are my firstborn, my might and the beginning of my strength, outstanding in dignity, outstanding in power.'
EXEC add_BibleVerse @BibleId, 101049004, N'You are destructive like water and will not excel, for you got on your father’s bed, then you defiled it – he got on my couch!'
EXEC add_BibleVerse @BibleId, 101049005, N'Simeon and Levi are brothers, weapons of violence are their knives!'
EXEC add_BibleVerse @BibleId, 101049006, N'O my soul, do not come into their council, do not be united to their assembly, my heart, for in their anger they have killed men, and for pleasure they have hamstrung oxen.'
EXEC add_BibleVerse @BibleId, 101049007, N'Cursed be their anger, for it was fierce, and their fury, for it was cruel. I will divide them in Jacob, and scatter them in Israel!'
EXEC add_BibleVerse @BibleId, 101049008, N'Judah, your brothers will praise you. Your hand will be on the neck of your enemies, your father’s sons will bow down before you.'
EXEC add_BibleVerse @BibleId, 101049009, N'You are a lion’s cub, Judah, from the prey, my son, you have gone up. He crouches and lies down like a lion; like a lioness – who will rouse him?'
EXEC add_BibleVerse @BibleId, 101049010, N'The scepter will not depart from Judah, nor the ruler’s staff from between his feet, until he comes to whom it belongs; the nations will obey him.'
EXEC add_BibleVerse @BibleId, 101049011, N'Binding his foal to the vine, and his colt to the choicest vine, he will wash his garments in wine, his robes in the blood of grapes.'
EXEC add_BibleVerse @BibleId, 101049012, N'His eyes will be dark from wine, and his teeth white from milk.'
EXEC add_BibleVerse @BibleId, 101049013, N'Zebulun will live by the haven of the sea and become a haven for ships; his border will extend to Sidon.'
EXEC add_BibleVerse @BibleId, 101049014, N'Issachar is a strong-boned donkey lying down between two saddlebags.'
EXEC add_BibleVerse @BibleId, 101049015, N'When he sees a good resting place, and the pleasant land, he will bend his shoulder to the burden and become a slave laborer.'
EXEC add_BibleVerse @BibleId, 101049016, N'Dan will judge his people as one of the tribes of Israel.'
EXEC add_BibleVerse @BibleId, 101049017, N'May Dan be a snake beside the road, a viper by the path, that bites the heels of the horse so that its rider falls backward.'
EXEC add_BibleVerse @BibleId, 101049018, N'I wait for your deliverance, O Lord.'
EXEC add_BibleVerse @BibleId, 101049019, N'Gad will be raided by marauding bands, but he will attack them at their heels.'
EXEC add_BibleVerse @BibleId, 101049020, N'Asher’s food will be rich, and he will provide delicacies to royalty.'
EXEC add_BibleVerse @BibleId, 101049021, N'Naphtali is a free running doe, he speaks delightful words.'
EXEC add_BibleVerse @BibleId, 101049022, N'Joseph is a fruitful bough, a fruitful bough near a spring whose branches climb over the wall.'
EXEC add_BibleVerse @BibleId, 101049023, N'The archers will attack him, they will shoot at him and oppose him.'
EXEC add_BibleVerse @BibleId, 101049024, N'But his bow will remain steady, and his hands will be skillful; because of the hands of the Mighty One of Jacob, because of the Shepherd, the Rock of Israel,'
EXEC add_BibleVerse @BibleId, 101049025, N'because of the God of your father, who will help you, because of the sovereign God, who will bless you with blessings from the sky above, blessings from the deep that lies below, and blessings of the breasts and womb.'
EXEC add_BibleVerse @BibleId, 101049026, N'The blessings of your father are greater than the blessings of the eternal mountains or the desirable things of the age-old hills. They will be on the head of Joseph and on the brow of the prince of his brothers.'
EXEC add_BibleVerse @BibleId, 101049027, N'Benjamin is a ravenous wolf; in the morning devouring the prey, and in the evening dividing the plunder.”'
EXEC add_BibleVerse @BibleId, 101049028, N'These are the twelve tribes of Israel. This is what their father said to them when he blessed them. He gave each of them an appropriate blessing.'
EXEC add_BibleVerse @BibleId, 101049029, N'Then he instructed them, “I am about to go to my people. Bury me with my fathers in the cave in the field of Ephron the Hittite.'
EXEC add_BibleVerse @BibleId, 101049030, N'It is the cave in the field of Machpelah, near Mamre in the land of Canaan, which Abraham bought for a burial plot from Ephron the Hittite.'
EXEC add_BibleVerse @BibleId, 101049031, N'There they buried Abraham and his wife Sarah; there they buried Isaac and his wife Rebekah; and there I buried Leah.'
EXEC add_BibleVerse @BibleId, 101049032, N'The field and the cave in it were acquired from the sons of Heth.”'
EXEC add_BibleVerse @BibleId, 101049033, N'When Jacob finished giving these instructions to his sons, he pulled his feet up onto the bed, breathed his last breath, and went to his people.'
EXEC add_BibleVerse @BibleId, 101050001, N'Then Joseph hugged his father’s face. He wept over him and kissed him.'
EXEC add_BibleVerse @BibleId, 101050002, N'Joseph instructed the physicians in his service to embalm his father, so the physicians embalmed Israel.'
EXEC add_BibleVerse @BibleId, 101050003, N'They took forty days, for that is the full time needed for embalming. The Egyptians mourned for him seventy days.'
EXEC add_BibleVerse @BibleId, 101050004, N'When the days of mourning had passed, Joseph said to Pharaoh’s royal court, “If I have found favor in your sight, please say to Pharaoh,'
EXEC add_BibleVerse @BibleId, 101050005, N'‘My father made me swear an oath. He said, “I am about to die. Bury me in my tomb that I dug for myself there in the land of Canaan.” Now let me go and bury my father; then I will return.’”'
EXEC add_BibleVerse @BibleId, 101050006, N'So Pharaoh said, “Go and bury your father, just as he made you swear to do.”'
EXEC add_BibleVerse @BibleId, 101050007, N'So Joseph went up to bury his father; all Pharaoh’s officials went with him – the senior courtiers of his household, all the senior officials of the land of Egypt,'
EXEC add_BibleVerse @BibleId, 101050008, N'all Joseph’s household, his brothers, and his father’s household. But they left their little children and their flocks and herds in the land of Goshen.'
EXEC add_BibleVerse @BibleId, 101050009, N'Chariots and horsemen also went up with him, so it was a very large entourage.'
EXEC add_BibleVerse @BibleId, 101050010, N'When they came to the threshing floor of Atad on the other side of the Jordan, they mourned there with very great and bitter sorrow. There Joseph observed a seven day period of mourning for his father.'
EXEC add_BibleVerse @BibleId, 101050011, N'When the Canaanites who lived in the land saw them mourning at the threshing floor of Atad, they said, “This is a very sad occasion for the Egyptians.” That is why its name was called Abel Mizraim, which is beyond the Jordan.'
EXEC add_BibleVerse @BibleId, 101050012, N'So the sons of Jacob did for him just as he had instructed them.'
EXEC add_BibleVerse @BibleId, 101050013, N'His sons carried him to the land of Canaan and buried him in the cave of the field of Machpelah, near Mamre. This is the field Abraham purchased as a burial plot from Ephron the Hittite.'
EXEC add_BibleVerse @BibleId, 101050014, N'After he buried his father, Joseph returned to Egypt, along with his brothers and all who had accompanied him to bury his father.'
EXEC add_BibleVerse @BibleId, 101050015, N'When Joseph’s brothers saw that their father was dead, they said, “What if Joseph bears a grudge and wants to repay us in full for all the harm we did to him?”'
EXEC add_BibleVerse @BibleId, 101050016, N'So they sent word to Joseph, saying, “Your father gave these instructions before he died:'
EXEC add_BibleVerse @BibleId, 101050017, N'‘Tell Joseph this: Please forgive the sin of your brothers and the wrong they did when they treated you so badly.’ Now please forgive the sin of the servants of the God of your father.” When this message was reported to him, Joseph wept.'
EXEC add_BibleVerse @BibleId, 101050018, N'Then his brothers also came and threw themselves down before him; they said, “Here we are; we are your slaves.”'
EXEC add_BibleVerse @BibleId, 101050019, N'But Joseph answered them, “Don’t be afraid. Am I in the place of God?'
EXEC add_BibleVerse @BibleId, 101050020, N'As for you, you meant to harm me, but God intended it for a good purpose, so he could preserve the lives of many people, as you can see this day.'
EXEC add_BibleVerse @BibleId, 101050021, N'So now, don’t be afraid. I will provide for you and your little children.” Then he consoled them and spoke kindly to them.'
EXEC add_BibleVerse @BibleId, 101050022, N'Joseph lived in Egypt, along with his father’s family. Joseph lived 110 years.'
EXEC add_BibleVerse @BibleId, 101050023, N'Joseph saw the descendants of Ephraim to the third generation. He also saw the children of Makir the son of Manasseh; they were given special inheritance rights by Joseph.'
EXEC add_BibleVerse @BibleId, 101050024, N'Then Joseph said to his brothers, “I am about to die. But God will surely come to you and lead you up from this land to the land he swore on oath to give to Abraham, Isaac, and Jacob.”'
EXEC add_BibleVerse @BibleId, 101050025, N'Joseph made the sons of Israel swear an oath. He said, “God will surely come to you. Then you must carry my bones up from this place.”'
EXEC add_BibleVerse @BibleId, 101050026, N'So Joseph died at the age of 110. After they embalmed him, his body was placed in a coffin in Egypt.'
EXEC add_BibleVerse @BibleId, 102001001, N'These are the names of the sons of Israel who entered Egypt – each man with his household entered with Jacob:'
EXEC add_BibleVerse @BibleId, 102001002, N'Reuben, Simeon, Levi, and Judah,'
EXEC add_BibleVerse @BibleId, 102001003, N'Issachar, Zebulun, and Benjamin,'
EXEC add_BibleVerse @BibleId, 102001004, N'Dan and Naphtali, Gad and Asher.'
EXEC add_BibleVerse @BibleId, 102001005, N'All the people who were directly descended from Jacob numbered seventy. But Joseph was already in Egypt,'
EXEC add_BibleVerse @BibleId, 102001006, N'and in time Joseph and his brothers and all that generation died.'
EXEC add_BibleVerse @BibleId, 102001007, N'The Israelites, however, were fruitful, increased greatly, multiplied, and became extremely strong, so that the land was filled with them.'
EXEC add_BibleVerse @BibleId, 102001008, N'Then a new king, who did not know about Joseph, came to power over Egypt.'
EXEC add_BibleVerse @BibleId, 102001009, N'He said to his people, “Look at the Israelite people, more numerous and stronger than we are!'
EXEC add_BibleVerse @BibleId, 102001010, N'Come, let’s deal wisely with them. Otherwise they will continue to multiply, and if a war breaks out, they will ally themselves with our enemies and fight against us and leave the country.”'
EXEC add_BibleVerse @BibleId, 102001011, N'So they put foremen over the Israelites to oppress them with hard labor. As a result they built Pithom and Rameses as store cities for Pharaoh.'
EXEC add_BibleVerse @BibleId, 102001012, N'But the more the Egyptians oppressed them, the more they multiplied and spread. As a result the Egyptians loathed the Israelites,'
EXEC add_BibleVerse @BibleId, 102001013, N'and they made the Israelites serve rigorously.'
EXEC add_BibleVerse @BibleId, 102001014, N'They made their lives bitter by hard service with mortar and bricks and by all kinds of service in the fields. Every kind of service the Israelites were required to give was rigorous.'
EXEC add_BibleVerse @BibleId, 102001015, N'The king of Egypt said to the Hebrew midwives, one of whom was named Shiphrah and the other Puah,'
EXEC add_BibleVerse @BibleId, 102001016, N'“When you assist the Hebrew women in childbirth, observe at the delivery: If it is a son, kill him, but if it is a daughter, she may live.”'
EXEC add_BibleVerse @BibleId, 102001017, N'But the midwives feared God and did not do what the king of Egypt had told them; they let the boys live.'
EXEC add_BibleVerse @BibleId, 102001018, N'Then the king of Egypt summoned the midwives and said to them, “Why have you done this and let the boys live?”'
EXEC add_BibleVerse @BibleId, 102001019, N'The midwives said to Pharaoh, “Because the Hebrew women are not like the Egyptian women – for the Hebrew women are vigorous; they give birth before the midwife gets to them!”'
EXEC add_BibleVerse @BibleId, 102001020, N'So God treated the midwives well, and the people multiplied and became very strong.'
EXEC add_BibleVerse @BibleId, 102001021, N'And because the midwives feared God, he made households for them.'
EXEC add_BibleVerse @BibleId, 102001022, N'Then Pharaoh commanded all his people, “All sons that are born you must throw into the river, but all daughters you may let live.”'
EXEC add_BibleVerse @BibleId, 102002001, N'A man from the household of Levi married a woman who was a descendant of Levi.'
EXEC add_BibleVerse @BibleId, 102002002, N'The woman became pregnant and gave birth to a son. When she saw that he was a healthy child, she hid him for three months.'
EXEC add_BibleVerse @BibleId, 102002003, N'But when she was no longer able to hide him, she took a papyrus basket for him and sealed it with bitumen and pitch. She put the child in it and set it among the reeds along the edge of the Nile.'
EXEC add_BibleVerse @BibleId, 102002004, N'His sister stationed herself at a distance to find out what would happen to him.'
EXEC add_BibleVerse @BibleId, 102002005, N'Then the daughter of Pharaoh came down to wash herself by the Nile, while her attendants were walking alongside the river, and she saw the basket among the reeds. She sent one of her attendants, took it,'
EXEC add_BibleVerse @BibleId, 102002006, N'opened it, and saw the child – a boy, crying! – and she felt compassion for him and said, “This is one of the Hebrews’ children.”'
EXEC add_BibleVerse @BibleId, 102002007, N'Then his sister said to Pharaoh’s daughter, “Shall I go and get a nursing woman for you from the Hebrews, so that she may nurse the child for you?”'
EXEC add_BibleVerse @BibleId, 102002008, N'Pharaoh’s daughter said to her, “Yes, do so.” So the young girl went and got the child’s mother.'
EXEC add_BibleVerse @BibleId, 102002009, N'Pharaoh’s daughter said to her, “Take this child and nurse him for me, and I will pay your wages.” So the woman took the child and nursed him.'
EXEC add_BibleVerse @BibleId, 102002010, N'When the child grew older she brought him to Pharaoh’s daughter, and he became her son. She named him Moses, saying, “Because I drew him from the water.”'
EXEC add_BibleVerse @BibleId, 102002011, N'In those days, when Moses had grown up, he went out to his people and observed their hard labor, and he saw an Egyptian man attacking a Hebrew man, one of his own people.'
EXEC add_BibleVerse @BibleId, 102002012, N'He looked this way and that and saw that no one was there, and then he attacked the Egyptian and concealed the body in the sand.'
EXEC add_BibleVerse @BibleId, 102002013, N'When he went out the next day, there were two Hebrew men fighting. So he said to the one who was in the wrong, “Why are you attacking your fellow Hebrew?”'
EXEC add_BibleVerse @BibleId, 102002014, N'The man replied, “Who made you a ruler and a judge over us? Are you planning to kill me like you killed that Egyptian?” Then Moses was afraid, thinking, “Surely what I did has become known.”'
EXEC add_BibleVerse @BibleId, 102002015, N'When Pharaoh heard about this event, he sought to kill Moses. So Moses fled from Pharaoh and settled in the land of Midian, and he settled by a certain well.'
EXEC add_BibleVerse @BibleId, 102002016, N'Now a priest of Midian had seven daughters, and they came and began to draw water and fill the troughs in order to water their father’s flock.'
EXEC add_BibleVerse @BibleId, 102002017, N'When some shepherds came and drove them away, Moses came up and defended them and then watered their flock.'
EXEC add_BibleVerse @BibleId, 102002018, N'So when they came home to their father Reuel, he asked, “Why have you come home so early today?”'
EXEC add_BibleVerse @BibleId, 102002019, N'They said, “An Egyptian man rescued us from the shepherds, and he actually drew water for us and watered the flock!”'
EXEC add_BibleVerse @BibleId, 102002020, N'He said to his daughters, “So where is he? Why in the world did you leave the man? Call him, so that he may eat a meal with us.”'
EXEC add_BibleVerse @BibleId, 102002021, N'Moses agreed to stay with the man, and he gave his daughter Zipporah to Moses in marriage.'
EXEC add_BibleVerse @BibleId, 102002022, N'When she bore a son, Moses named him Gershom, for he said, “I have become a resident foreigner in a foreign land.”'
EXEC add_BibleVerse @BibleId, 102002023, N'During that long period of time the king of Egypt died, and the Israelites groaned because of the slave labor. They cried out, and their desperate cry because of their slave labor went up to God.'
EXEC add_BibleVerse @BibleId, 102002024, N'God heard their groaning, God remembered his covenant with Abraham, with Isaac, and with Jacob,'
EXEC add_BibleVerse @BibleId, 102002025, N'God saw the Israelites, and God understood….'
EXEC add_BibleVerse @BibleId, 102003001, N'Now Moses was shepherding the flock of his father-in-law Jethro, the priest of Midian, and he led the flock to the far side of the desert and came to the mountain of God, to Horeb.'
EXEC add_BibleVerse @BibleId, 102003002, N'The angel of the Lord appeared to him in a flame of fire from within a bush. He looked – and the bush was ablaze with fire, but it was not being consumed!'
EXEC add_BibleVerse @BibleId, 102003003, N'So Moses thought, “I will turn aside to see this amazing sight. Why does the bush not burn up?”'
EXEC add_BibleVerse @BibleId, 102003004, N'When the Lord saw that he had turned aside to look, God called to him from within the bush and said, “Moses, Moses!” And Moses said, “Here I am.”'
EXEC add_BibleVerse @BibleId, 102003005, N'God said, “Do not approach any closer! Take your sandals off your feet, for the place where you are standing is holy ground.”'
EXEC add_BibleVerse @BibleId, 102003006, N'He added, “I am the God of your father, the God of Abraham, the God of Isaac, and the God of Jacob.” Then Moses hid his face, because he was afraid to look at God.'
EXEC add_BibleVerse @BibleId, 102003007, N'The Lord said, “I have surely seen the affliction of my people who are in Egypt. I have heard their cry because of their taskmasters, for I know their sorrows.'
EXEC add_BibleVerse @BibleId, 102003008, N'I have come down to deliver them from the hand of the Egyptians and to bring them up from that land to a land that is both good and spacious, to a land flowing with milk and honey, to the region of the Canaanites, Hittites, Amorites, Perizzites, Hivites, and Jebusites.'
EXEC add_BibleVerse @BibleId, 102003009, N'And now indeed the cry of the Israelites has come to me, and I have also seen how severely the Egyptians oppress them.'
EXEC add_BibleVerse @BibleId, 102003010, N'So now go, and I will send you to Pharaoh to bring my people, the Israelites, out of Egypt.”'
EXEC add_BibleVerse @BibleId, 102003011, N'Moses said to God, “Who am I, that I should go to Pharaoh, or that I should bring the Israelites out of Egypt?”'
EXEC add_BibleVerse @BibleId, 102003012, N'He replied, “Surely I will be with you, and this will be the sign to you that I have sent you: When you bring the people out of Egypt, you and they will serve God on this mountain.”'
EXEC add_BibleVerse @BibleId, 102003013, N'Moses said to God, “If I go to the Israelites and tell them, ‘The God of your fathers has sent me to you,’ and they ask me, ‘What is his name?’ – what should I say to them?”'
EXEC add_BibleVerse @BibleId, 102003014, N'God said to Moses, “I am that I am.” And he said, “You must say this to the Israelites, ‘I am has sent me to you.’”'
EXEC add_BibleVerse @BibleId, 102003015, N'God also said to Moses, “You must say this to the Israelites, ‘The Lord – the God of your fathers, the God of Abraham, the God of Isaac, and the God of Jacob – has sent me to you. This is my name forever, and this is my memorial from generation to generation.’'
EXEC add_BibleVerse @BibleId, 102003016, N'“Go and bring together the elders of Israel and tell them, ‘The Lord, the God of your fathers, appeared to me – the God of Abraham, Isaac, and Jacob – saying, “I have attended carefully to you and to what has been done to you in Egypt,'
EXEC add_BibleVerse @BibleId, 102003017, N'and I have promised that I will bring you up out of the affliction of Egypt to the land of the Canaanites, Hittites, Amorites, Perizzites, Hivites, and Jebusites, to a land flowing with milk and honey.”’'
EXEC add_BibleVerse @BibleId, 102003018, N'“The elders will listen to you, and then you and the elders of Israel must go to the king of Egypt and tell him, ‘The Lord, the God of the Hebrews, has met with us. So now, let us go three days’ journey into the wilderness, so that we may sacrifice to the Lord our God.’'
EXEC add_BibleVerse @BibleId, 102003019, N'But I know that the king of Egypt will not let you go, not even under force.'
EXEC add_BibleVerse @BibleId, 102003020, N'So I will extend my hand and strike Egypt with all my wonders that I will do among them, and after that he will release you.'
EXEC add_BibleVerse @BibleId, 102003021, N'“I will grant this people favor with the Egyptians, so that when you depart you will not leave empty-handed.'
EXEC add_BibleVerse @BibleId, 102003022, N'Every woman will ask her neighbor and the one who happens to be staying in her house for items of silver and gold and for clothing. You will put these articles on your sons and daughters – thus you will plunder Egypt!”'
EXEC add_BibleVerse @BibleId, 102004001, N'Moses answered again, “And if they do not believe me or pay attention to me, but say, ‘The Lord has not appeared to you’?”'
EXEC add_BibleVerse @BibleId, 102004002, N'The Lord said to him, “What is that in your hand?” He said, “A staff.”'
EXEC add_BibleVerse @BibleId, 102004003, N'The Lord said, “Throw it to the ground.” So he threw it to the ground, and it became a snake, and Moses ran from it.'
EXEC add_BibleVerse @BibleId, 102004004, N'But the Lord said to Moses, “Put out your hand and grab it by the tail” – so he put out his hand and caught it, and it became a staff in his hand –'
EXEC add_BibleVerse @BibleId, 102004005, N'“that they may believe that the Lord, the God of their fathers, the God of Abraham, the God of Isaac, and the God of Jacob, has appeared to you.”'
EXEC add_BibleVerse @BibleId, 102004006, N'The Lord also said to him, “Put your hand into your robe.” So he put his hand into his robe, and when he brought it out – there was his hand, leprous like snow!'
EXEC add_BibleVerse @BibleId, 102004007, N'He said, “Put your hand back into your robe.” So he put his hand back into his robe, and when he brought it out from his robe – there it was, restored like the rest of his skin!'
EXEC add_BibleVerse @BibleId, 102004008, N'“If they do not believe you or pay attention to the former sign, then they may believe the latter sign.'
EXEC add_BibleVerse @BibleId, 102004009, N'And if they do not believe even these two signs or listen to you, then take some water from the Nile and pour it out on the dry ground. The water you take out of the Nile will become blood on the dry ground.”'
EXEC add_BibleVerse @BibleId, 102004010, N'Then Moses said to the Lord, “O my Lord, I am not an eloquent man, neither in the past nor since you have spoken to your servant, for I am slow of speech and slow of tongue.”'
EXEC add_BibleVerse @BibleId, 102004011, N'The Lord said to him, “Who gave a mouth to man, or who makes a person mute or deaf or seeing or blind? Is it not I, the Lord?'
EXEC add_BibleVerse @BibleId, 102004012, N'So now go, and I will be with your mouth and will teach you what you must say.”'
EXEC add_BibleVerse @BibleId, 102004013, N'But Moses said, “O my Lord, please send anyone else whom you wish to send!”'
EXEC add_BibleVerse @BibleId, 102004014, N'Then the Lord became angry with Moses, and he said, “What about your brother Aaron the Levite? I know that he can speak very well. Moreover, he is coming to meet you, and when he sees you he will be glad in his heart.'
EXEC add_BibleVerse @BibleId, 102004015, N'“So you are to speak to him and put the words in his mouth. And as for me, I will be with your mouth and with his mouth, and I will teach you both what you must do.'
EXEC add_BibleVerse @BibleId, 102004016, N'He will speak for you to the people, and it will be as if he were your mouth and as if you were his God.'
EXEC add_BibleVerse @BibleId, 102004017, N'You will also take in your hand this staff, with which you will do the signs.”'
EXEC add_BibleVerse @BibleId, 102004018, N'So Moses went back to his father-in-law Jethro and said to him, “Let me go, so that I may return to my relatives in Egypt and see if they are still alive.” Jethro said to Moses, “Go in peace.”'
EXEC add_BibleVerse @BibleId, 102004019, N'The Lord said to Moses in Midian, “Go back to Egypt, because all the men who were seeking your life are dead.”'
EXEC add_BibleVerse @BibleId, 102004020, N'Then Moses took his wife and sons and put them on a donkey and headed back to the land of Egypt, and Moses took the staff of God in his hand.'
EXEC add_BibleVerse @BibleId, 102004021, N'The Lord said to Moses, “When you go back to Egypt, see that you do before Pharaoh all the wonders I have put under your control. But I will harden his heart and he will not let the people go.'
EXEC add_BibleVerse @BibleId, 102004022, N'You must say to Pharaoh, ‘Thus says the Lord, “Israel is my son, my firstborn,'
EXEC add_BibleVerse @BibleId, 102004023, N'and I said to you, ‘Let my son go that he may serve me,’ but since you have refused to let him go, I will surely kill your son, your firstborn!”’”'
EXEC add_BibleVerse @BibleId, 102004024, N'Now on the way, at a place where they stopped for the night, the Lord met Moses and sought to kill him.'
EXEC add_BibleVerse @BibleId, 102004025, N'But Zipporah took a flint knife, cut off the foreskin of her son and touched it to Moses’ feet, and said, “Surely you are a bridegroom of blood to me.”'
EXEC add_BibleVerse @BibleId, 102004026, N'So the Lord let him alone. (At that time she said, “A bridegroom of blood,” referring to the circumcision.)'
EXEC add_BibleVerse @BibleId, 102004027, N'The Lord said to Aaron, “Go to the wilderness to meet Moses. So he went and met him at the mountain of God and greeted him with a kiss.'
EXEC add_BibleVerse @BibleId, 102004028, N'Moses told Aaron all the words of the Lord who had sent him and all the signs that he had commanded him.'
EXEC add_BibleVerse @BibleId, 102004029, N'Then Moses and Aaron went and brought together all the Israelite elders.'
EXEC add_BibleVerse @BibleId, 102004030, N'Aaron spoke all the words that the Lord had spoken to Moses and did the signs in the sight of the people,'
EXEC add_BibleVerse @BibleId, 102004031, N'and the people believed. When they heard that the Lord had attended to the Israelites and that he had seen their affliction, they bowed down close to the ground.'
EXEC add_BibleVerse @BibleId, 102005001, N'Afterward Moses and Aaron went to Pharaoh and said, “Thus says the Lord, the God of Israel, ‘Release my people so that they may hold a pilgrim feast to me in the desert.’”'
EXEC add_BibleVerse @BibleId, 102005002, N'But Pharaoh said, “Who is the Lord that I should obey him by releasing Israel? I do not know the Lord, and I will not release Israel!”'
EXEC add_BibleVerse @BibleId, 102005003, N'And they said, “The God of the Hebrews has met with us. Let us go a three-day journey into the desert so that we may sacrifice to the Lord our God, so that he does not strike us with plague or the sword.”'
EXEC add_BibleVerse @BibleId, 102005004, N'The king of Egypt said to them, “Moses and Aaron, why do you cause the people to refrain from their work? Return to your labor!”'
EXEC add_BibleVerse @BibleId, 102005005, N'Pharaoh was thinking, “The people of the land are now many, and you are giving them rest from their labor.”'
EXEC add_BibleVerse @BibleId, 102005006, N'That same day Pharaoh commanded the slave masters and foremen who were over the people:'
EXEC add_BibleVerse @BibleId, 102005007, N'“You must no longer give straw to the people for making bricks as before. Let them go and collect straw for themselves.'
EXEC add_BibleVerse @BibleId, 102005008, N'But you must require of them the same quota of bricks that they were making before. Do not reduce it, for they are slackers. That is why they are crying, ‘Let us go sacrifice to our God.’'
EXEC add_BibleVerse @BibleId, 102005009, N'Make the work harder for the men so they will keep at it and pay no attention to lying words!”'
EXEC add_BibleVerse @BibleId, 102005010, N'So the slave masters of the people and their foremen went to the Israelites and said, “Thus says Pharaoh: ‘I am not giving you straw.'
EXEC add_BibleVerse @BibleId, 102005011, N'You go get straw for yourselves wherever you can find it, because there will be no reduction at all in your workload.’”'
EXEC add_BibleVerse @BibleId, 102005012, N'So the people spread out through all the land of Egypt to collect stubble for straw.'
EXEC add_BibleVerse @BibleId, 102005013, N'The slave masters were pressuring them, saying, “Complete your work for each day, just like when there was straw!”'
EXEC add_BibleVerse @BibleId, 102005014, N'The Israelite foremen whom Pharaoh’s slave masters had set over them were beaten and were asked, “Why did you not complete your requirement for brickmaking as in the past – both yesterday and today?”'
EXEC add_BibleVerse @BibleId, 102005015, N'The Israelite foremen went and cried out to Pharaoh, “Why are you treating your servants this way?'
EXEC add_BibleVerse @BibleId, 102005016, N'No straw is given to your servants, but we are told, ‘Make bricks!’ Your servants are even being beaten, but the fault is with your people.”'
EXEC add_BibleVerse @BibleId, 102005017, N'But Pharaoh replied, “You are slackers! Slackers! That is why you are saying, ‘Let us go sacrifice to the Lord.’'
EXEC add_BibleVerse @BibleId, 102005018, N'So now, get back to work! You will not be given straw, but you must still produce your quota of bricks!”'
EXEC add_BibleVerse @BibleId, 102005019, N'The Israelite foremen saw that they were in trouble when they were told, “You must not reduce the daily quota of your bricks.”'
EXEC add_BibleVerse @BibleId, 102005020, N'When they went out from Pharaoh, they encountered Moses and Aaron standing there to meet them,'
EXEC add_BibleVerse @BibleId, 102005021, N'and they said to them, “May the Lord look on you and judge, because you have made us stink in the opinion of Pharaoh and his servants, so that you have given them an excuse to kill us!”'
EXEC add_BibleVerse @BibleId, 102005022, N'Moses returned to the Lord, and said, “Lord, why have you caused trouble for this people? Why did you ever send me?'
EXEC add_BibleVerse @BibleId, 102005023, N'From the time I went to speak to Pharaoh in your name, he has caused trouble for this people, and you have certainly not rescued them!”'
EXEC add_BibleVerse @BibleId, 102006001, N'Then the Lord said to Moses, “Now you will see what I will do to Pharaoh, for compelled by my strong hand he will release them, and by my strong hand he will drive them out of his land.”'
EXEC add_BibleVerse @BibleId, 102006002, N'God spoke to Moses and said to him, “I am the Lord.'
EXEC add_BibleVerse @BibleId, 102006003, N'I appeared to Abraham, to Isaac, and to Jacob as God Almighty, but by my name ‘the Lord’ I was not known to them.'
EXEC add_BibleVerse @BibleId, 102006004, N'I also established my covenant with them to give them the land of Canaan, where they were living as resident foreigners.'
EXEC add_BibleVerse @BibleId, 102006005, N'I have also heard the groaning of the Israelites, whom the Egyptians are enslaving, and I have remembered my covenant.'
EXEC add_BibleVerse @BibleId, 102006006, N'Therefore, tell the Israelites, ‘I am the Lord. I will bring you out from your enslavement to the Egyptians, I will rescue you from the hard labor they impose, and I will redeem you with an outstretched arm and with great judgments.'
EXEC add_BibleVerse @BibleId, 102006007, N'I will take you to myself for a people, and I will be your God. Then you will know that I am the Lord your God, who brought you out from your enslavement to the Egyptians.'
EXEC add_BibleVerse @BibleId, 102006008, N'I will bring you to the land I swore to give to Abraham, to Isaac, and to Jacob – and I will give it to you as a possession. I am the Lord!’”'
EXEC add_BibleVerse @BibleId, 102006009, N'Moses told this to the Israelites, but they did not listen to him because of their discouragement and hard labor.'
EXEC add_BibleVerse @BibleId, 102006010, N'Then the Lord said to Moses,'
EXEC add_BibleVerse @BibleId, 102006011, N'“Go, tell Pharaoh king of Egypt that he must release the Israelites from his land.”'
EXEC add_BibleVerse @BibleId, 102006012, N'But Moses replied to the Lord, “If the Israelites did not listen to me, then how will Pharaoh listen to me, since I speak with difficulty?”'
EXEC add_BibleVerse @BibleId, 102006013, N'The Lord spoke to Moses and Aaron and gave them a charge for the Israelites and Pharaoh king of Egypt to bring the Israelites out of the land of Egypt.'
EXEC add_BibleVerse @BibleId, 102006014, N'These are the heads of their fathers’ households: The sons of Reuben, the firstborn son of Israel, were Hanoch and Pallu, Hezron and Carmi. These were the clans of Reuben.'
EXEC add_BibleVerse @BibleId, 102006015, N'The sons of Simeon were Jemuel, Jamin, Ohad, Jakin, Zohar, and Shaul, the son of a Canaanite woman. These were the clans of Simeon.'
EXEC add_BibleVerse @BibleId, 102006016, N'Now these are the names of the sons of Levi, according to their records: Gershon, Kohath, and Merari. (The length of Levi’s life was 137 years.)'
EXEC add_BibleVerse @BibleId, 102006017, N'The sons of Gershon, by their families, were Libni and Shimei.'
EXEC add_BibleVerse @BibleId, 102006018, N'The sons of Kohath were Amram, Izhar, Hebron, and Uzziel. (The length of Kohath’s life was 133 years.)'
EXEC add_BibleVerse @BibleId, 102006019, N'The sons of Merari were Mahli and Mushi. These were the clans of Levi, according to their records.'
EXEC add_BibleVerse @BibleId, 102006020, N'Amram married his father’s sister Jochebed, and she bore him Aaron and Moses. (The length of Amram’s life was 137 years.)'
EXEC add_BibleVerse @BibleId, 102006021, N'The sons of Izhar were Korah, Nepheg, and Zikri.'
EXEC add_BibleVerse @BibleId, 102006022, N'The sons of Uzziel were Mishael, Elzaphan, and Sithri.'
EXEC add_BibleVerse @BibleId, 102006023, N'Aaron married Elisheba, the daughter of Amminadab and sister of Nahshon, and she bore him Nadab and Abihu, Eleazar and Ithamar.'
EXEC add_BibleVerse @BibleId, 102006024, N'The sons of Korah were Assir, Elkanah, and Abiasaph. These were the Korahite clans.'
EXEC add_BibleVerse @BibleId, 102006025, N'Now Eleazar son of Aaron married one of the daughters of Putiel and she bore him Phinehas. These are the heads of the fathers’ households of Levi according to their clans.'
EXEC add_BibleVerse @BibleId, 102006026, N'It was the same Aaron and Moses to whom the Lord said, “Bring the Israelites out of the land of Egypt by their regiments.”'
EXEC add_BibleVerse @BibleId, 102006027, N'They were the men who were speaking to Pharaoh king of Egypt, in order to bring the Israelites out of Egypt. It was the same Moses and Aaron.'
EXEC add_BibleVerse @BibleId, 102006028, N'When the Lord spoke to Moses in the land of Egypt,'
EXEC add_BibleVerse @BibleId, 102006029, N'he said to him, “I am the Lord. Tell Pharaoh king of Egypt all that I am telling you.”'
EXEC add_BibleVerse @BibleId, 102006030, N'But Moses said before the Lord, “Since I speak with difficulty, why should Pharaoh listen to me?”'
EXEC add_BibleVerse @BibleId, 102007001, N'So the Lord said to Moses, “See, I have made you like God to Pharaoh, and your brother Aaron will be your prophet.'
EXEC add_BibleVerse @BibleId, 102007002, N'You are to speak everything I command you, and your brother Aaron is to tell Pharaoh that he must release the Israelites from his land.'
EXEC add_BibleVerse @BibleId, 102007003, N'But I will harden Pharaoh’s heart, and although I will multiply my signs and my wonders in the land of Egypt,'
EXEC add_BibleVerse @BibleId, 102007004, N'Pharaoh will not listen to you. I will reach into Egypt and bring out my regiments, my people the Israelites, from the land of Egypt with great acts of judgment.'
EXEC add_BibleVerse @BibleId, 102007005, N'Then the Egyptians will know that I am the Lord, when I extend my hand over Egypt and bring the Israelites out from among them.'
EXEC add_BibleVerse @BibleId, 102007006, N'And Moses and Aaron did so; they did just as the Lord commanded them.'
EXEC add_BibleVerse @BibleId, 102007007, N'Now Moses was eighty years old and Aaron was eighty-three years old when they spoke to Pharaoh.'
EXEC add_BibleVerse @BibleId, 102007008, N'The Lord said to Moses and Aaron,'
EXEC add_BibleVerse @BibleId, 102007009, N'“When Pharaoh says to you, ‘Do a miracle,’ and you say to Aaron, ‘Take your staff and throw it down before Pharaoh,’ it will become a snake.”'
EXEC add_BibleVerse @BibleId, 102007010, N'When Moses and Aaron went to Pharaoh, they did so, just as the Lord had commanded them – Aaron threw down his staff before Pharaoh and his servants and it became a snake.'
EXEC add_BibleVerse @BibleId, 102007011, N'Then Pharaoh also summoned wise men and sorcerers, and the magicians of Egypt by their secret arts did the same thing.'
EXEC add_BibleVerse @BibleId, 102007012, N'Each man threw down his staff, and the staffs became snakes. But Aaron’s staff swallowed up their staffs.'
EXEC add_BibleVerse @BibleId, 102007013, N'Yet Pharaoh’s heart became hard, and he did not listen to them, just as the Lord had predicted.'
EXEC add_BibleVerse @BibleId, 102007014, N'The Lord said to Moses, “Pharaoh’s heart is hard; he refuses to release the people.'
EXEC add_BibleVerse @BibleId, 102007015, N'Go to Pharaoh in the morning when he goes out to the water. Position yourself to meet him by the edge of the Nile, and take in your hand the staff that was turned into a snake.'
EXEC add_BibleVerse @BibleId, 102007016, N'Tell him, ‘The Lord, the God of the Hebrews, has sent me to you to say, “Release my people, that they may serve me in the desert!” But until now you have not listened.'
EXEC add_BibleVerse @BibleId, 102007017, N'Thus says the Lord: “By this you will know that I am the Lord: I am going to strike the water of the Nile with the staff that is in my hand, and it will be turned into blood.'
EXEC add_BibleVerse @BibleId, 102007018, N'Fish in the Nile will die, the Nile will stink, and the Egyptians will be unable to drink water from the Nile.”’”'
EXEC add_BibleVerse @BibleId, 102007019, N'Then the Lord said to Moses, “Tell Aaron, ‘Take your staff and stretch out your hand over Egypt’s waters – over their rivers, over their canals, over their ponds, and over all their reservoirs – so that it becomes blood.’ There will be blood everywhere in the land of Egypt, even in wooden and stone containers.”'
EXEC add_BibleVerse @BibleId, 102007020, N'Moses and Aaron did so, just as the Lord had commanded. Moses raised the staff and struck the water that was in the Nile right before the eyes of Pharaoh and his servants, and all the water that was in the Nile was turned to blood.'
EXEC add_BibleVerse @BibleId, 102007021, N'When the fish that were in the Nile died, the Nile began to stink, so that the Egyptians could not drink water from the Nile. There was blood everywhere in the land of Egypt!'
EXEC add_BibleVerse @BibleId, 102007022, N'But the magicians of Egypt did the same by their secret arts, and so Pharaoh’s heart remained hard, and he refused to listen to Moses and Aaron – just as the Lord had predicted.'
EXEC add_BibleVerse @BibleId, 102007023, N'And Pharaoh turned and went into his house. He did not pay any attention to this.'
EXEC add_BibleVerse @BibleId, 102007024, N'All the Egyptians dug around the Nile for water to drink, because they could not drink the water of the Nile.'
EXEC add_BibleVerse @BibleId, 102007025, N'Seven full days passed after the Lord struck the Nile.'
EXEC add_BibleVerse @BibleId, 102008001, N'Then the Lord said to Moses, “Go to Pharaoh and tell him, ‘Thus says the Lord: “Release my people in order that they may serve me!'
EXEC add_BibleVerse @BibleId, 102008002, N'But if you refuse to release them, then I am going to plague all your territory with frogs.'
EXEC add_BibleVerse @BibleId, 102008003, N'The Nile will swarm with frogs, and they will come up and go into your house, in your bedroom, and on your bed, and into the houses of your servants and your people, and into your ovens and your kneading troughs.'
EXEC add_BibleVerse @BibleId, 102008004, N'Frogs will come up against you, your people, and all your servants.”’”'
EXEC add_BibleVerse @BibleId, 102008005, N'The Lord spoke to Moses, “Tell Aaron, ‘Extend your hand with your staff over the rivers, over the canals, and over the ponds, and bring the frogs up over the land of Egypt.’”'
EXEC add_BibleVerse @BibleId, 102008006, N'So Aaron extended his hand over the waters of Egypt, and frogs came up and covered the land of Egypt.'
EXEC add_BibleVerse @BibleId, 102008007, N'The magicians did the same with their secret arts and brought up frogs on the land of Egypt too.'
EXEC add_BibleVerse @BibleId, 102008008, N'Then Pharaoh summoned Moses and Aaron and said, “Pray to the Lord that he may take the frogs away from me and my people, and I will release the people that they may sacrifice to the Lord.”'
EXEC add_BibleVerse @BibleId, 102008009, N'Moses said to Pharaoh, “You may have the honor over me – when shall I pray for you, your servants, and your people, for the frogs to be removed from you and your houses, so that they will be left only in the Nile?”'
EXEC add_BibleVerse @BibleId, 102008010, N'He said, “Tomorrow.” And Moses said, “It will be as you say, so that you may know that there is no one like the Lord our God.'
EXEC add_BibleVerse @BibleId, 102008011, N'The frogs will depart from you, your houses, your servants, and your people; they will be left only in the Nile.”'
EXEC add_BibleVerse @BibleId, 102008012, N'Then Moses and Aaron went out from Pharaoh, and Moses cried to the Lord because of the frogs that he had brought on Pharaoh.'
EXEC add_BibleVerse @BibleId, 102008013, N'The Lord did as Moses asked – the frogs died out of the houses, the villages, and the fields.'
EXEC add_BibleVerse @BibleId, 102008014, N'The Egyptians piled them in countless heaps, and the land stank.'
EXEC add_BibleVerse @BibleId, 102008015, N'But when Pharaoh saw that there was relief, he hardened his heart and did not listen to them, just as the Lord had predicted.'
EXEC add_BibleVerse @BibleId, 102008016, N'The Lord said to Moses, “Tell Aaron, ‘Extend your staff and strike the dust of the ground, and it will become gnats throughout all the land of Egypt.’”'
EXEC add_BibleVerse @BibleId, 102008017, N'They did so; Aaron extended his hand with his staff, he struck the dust of the ground, and it became gnats on people and on animals. All the dust of the ground became gnats throughout all the land of Egypt.'
EXEC add_BibleVerse @BibleId, 102008018, N'When the magicians attempted to bring forth gnats by their secret arts, they could not. So there were gnats on people and on animals.'
EXEC add_BibleVerse @BibleId, 102008019, N'The magicians said to Pharaoh, “It is the finger of God!” But Pharaoh’s heart remained hard, and he did not listen to them, just as the Lord had predicted.'
EXEC add_BibleVerse @BibleId, 102008020, N'The Lord said to Moses, “Get up early in the morning and position yourself before Pharaoh as he goes out to the water, and tell him, ‘Thus says the Lord, “Release my people that they may serve me!'
EXEC add_BibleVerse @BibleId, 102008021, N'If you do not release my people, then I am going to send swarms of flies on you and on your servants and on your people and in your houses. The houses of the Egyptians will be full of flies, and even the ground they stand on.'
EXEC add_BibleVerse @BibleId, 102008022, N'But on that day I will mark off the land of Goshen, where my people are staying, so that no swarms of flies will be there, that you may know that I am the Lord in the midst of this land.'
EXEC add_BibleVerse @BibleId, 102008023, N'I will put a division between my people and your people. This sign will take place tomorrow.”’”'
EXEC add_BibleVerse @BibleId, 102008024, N'The Lord did so; a thick swarm of flies came into Pharaoh’s house and into the houses of his servants, and throughout the whole land of Egypt the land was ruined because of the swarms of flies.'
EXEC add_BibleVerse @BibleId, 102008025, N'Then Pharaoh summoned Moses and Aaron and said, “Go, sacrifice to your God within the land.”'
EXEC add_BibleVerse @BibleId, 102008026, N'But Moses said, “That would not be the right thing to do, for the sacrifices we make to the Lord our God would be an abomination to the Egyptians. If we make sacrifices that are an abomination to the Egyptians right before their eyes, will they not stone us?'
EXEC add_BibleVerse @BibleId, 102008027, N'We must go on a three-day journey into the desert and sacrifice to the Lord our God, just as he is telling us.”'
EXEC add_BibleVerse @BibleId, 102008028, N'Pharaoh said, “I will release you so that you may sacrifice to the Lord your God in the desert. Only you must not go very far. Do pray for me.”'
EXEC add_BibleVerse @BibleId, 102008029, N'Moses said, “I am going to go out from you and pray to the Lord, and the swarms of flies will go away from Pharaoh, from his servants, and from his people tomorrow. Only do not let Pharaoh deal falsely again by not releasing the people to sacrifice to the Lord.”'
EXEC add_BibleVerse @BibleId, 102008030, N'So Moses went out from Pharaoh and prayed to the Lord,'
EXEC add_BibleVerse @BibleId, 102008031, N'and the Lord did as Moses asked – he removed the swarms of flies from Pharaoh, from his servants, and from his people. Not one remained!'
EXEC add_BibleVerse @BibleId, 102008032, N'But Pharaoh hardened his heart this time also and did not release the people.'
EXEC add_BibleVerse @BibleId, 102009001, N'Then the Lord said to Moses, “Go to Pharaoh and tell him, ‘Thus says the Lord, the God of the Hebrews, “Release my people that they may serve me!'
EXEC add_BibleVerse @BibleId, 102009002, N'For if you refuse to release them and continue holding them,'
EXEC add_BibleVerse @BibleId, 102009003, N'then the hand of the Lord will surely bring a very terrible plague on your livestock in the field, on the horses, the donkeys, the camels, the herds, and the flocks.'
EXEC add_BibleVerse @BibleId, 102009004, N'But the Lord will distinguish between the livestock of Israel and the livestock of Egypt, and nothing will die of all that the Israelites have.”’”'
EXEC add_BibleVerse @BibleId, 102009005, N'The Lord set an appointed time, saying, “Tomorrow the Lord will do this in the land.”'
EXEC add_BibleVerse @BibleId, 102009006, N'And the Lord did this on the next day; all the livestock of the Egyptians died, but of the Israelites’ livestock not one died.'
EXEC add_BibleVerse @BibleId, 102009007, N'Pharaoh sent representatives to investigate, and indeed, not even one of the livestock of Israel had died. But Pharaoh’s heart remained hard, and he did not release the people.'
EXEC add_BibleVerse @BibleId, 102009008, N'Then the Lord said to Moses and Aaron, “Take handfuls of soot from a furnace, and have Moses throw it into the air while Pharaoh is watching.'
EXEC add_BibleVerse @BibleId, 102009009, N'It will become fine dust over the whole land of Egypt and will cause boils to break out and fester on both people and animals in all the land of Egypt.”'
EXEC add_BibleVerse @BibleId, 102009010, N'So they took soot from a furnace and stood before Pharaoh, Moses threw it into the air, and it caused festering boils to break out on both people and animals.'
EXEC add_BibleVerse @BibleId, 102009011, N'The magicians could not stand before Moses because of the boils, for boils were on the magicians and on all the Egyptians.'
EXEC add_BibleVerse @BibleId, 102009012, N'But the Lord hardened Pharaoh’s heart, and he did not listen to them, just as the Lord had predicted to Moses.'
EXEC add_BibleVerse @BibleId, 102009013, N'The Lord said to Moses, “Get up early in the morning, stand before Pharaoh, and tell him, ‘Thus says the Lord, the God of the Hebrews: “Release my people so that they may serve me!'
EXEC add_BibleVerse @BibleId, 102009014, N'For this time I will send all my plagues on your very self and on your servants and your people, so that you may know that there is no one like me in all the earth.'
EXEC add_BibleVerse @BibleId, 102009015, N'For by now I could have stretched out my hand and struck you and your people with plague, and you would have been destroyed from the earth.'
EXEC add_BibleVerse @BibleId, 102009016, N'But for this purpose I have caused you to stand: to show you my strength, and so that my name may be declared in all the earth.'
EXEC add_BibleVerse @BibleId, 102009017, N'You are still exalting yourself against my people by not releasing them.'
EXEC add_BibleVerse @BibleId, 102009018, N'I am going to cause very severe hail to rain down about this time tomorrow, such hail as has never occurred in Egypt from the day it was founded until now.'
EXEC add_BibleVerse @BibleId, 102009019, N'So now, send instructions to gather your livestock and all your possessions in the fields to a safe place. Every person or animal caught in the field and not brought into the house – the hail will come down on them, and they will die!”’”'
EXEC add_BibleVerse @BibleId, 102009020, N'Those of Pharaoh’s servants who feared the word of the Lord hurried to bring their servants and livestock into the houses,'
EXEC add_BibleVerse @BibleId, 102009021, N'but those who did not take the word of the Lord seriously left their servants and their cattle in the field.'
EXEC add_BibleVerse @BibleId, 102009022, N'Then the Lord said to Moses, “Extend your hand toward the sky that there may be hail in all the land of Egypt, on people and on animals, and on everything that grows in the field in the land of Egypt.”'
EXEC add_BibleVerse @BibleId, 102009023, N'When Moses extended his staff toward the sky, the Lord sent thunder and hail, and fire fell to the earth; so the Lord caused hail to rain down on the land of Egypt.'
EXEC add_BibleVerse @BibleId, 102009024, N'Hail fell and fire mingled with the hail; the hail was so severe that there had not been any like it in all the land of Egypt since it had become a nation.'
EXEC add_BibleVerse @BibleId, 102009025, N'The hail struck everything in the open fields, both people and animals, throughout all the land of Egypt. The hail struck everything that grows in the field, and it broke all the trees of the field to pieces.'
EXEC add_BibleVerse @BibleId, 102009026, N'Only in the land of Goshen, where the Israelites lived, was there no hail.'
EXEC add_BibleVerse @BibleId, 102009027, N'So Pharaoh sent and summoned Moses and Aaron and said to them, “I have sinned this time! The Lord is righteous, and I and my people are guilty.'
EXEC add_BibleVerse @BibleId, 102009028, N'Pray to the Lord, for the mighty thunderings and hail are too much! I will release you and you will stay no longer.”'
EXEC add_BibleVerse @BibleId, 102009029, N'Moses said to him, “When I leave the city I will spread my hands to the Lord, the thunder will cease, and there will be no more hail, so that you may know that the earth belongs to the Lord.'
EXEC add_BibleVerse @BibleId, 102009030, N'But as for you and your servants, I know that you do not yet fear the Lord God.”'
EXEC add_BibleVerse @BibleId, 102009031, N'(Now the flax and the barley were struck by the hail, for the barley had ripened and the flax was in bud.'
EXEC add_BibleVerse @BibleId, 102009032, N'But the wheat and the spelt were not struck, for they are later crops.)'
EXEC add_BibleVerse @BibleId, 102009033, N'So Moses left Pharaoh, went out of the city, and spread out his hands to the Lord, and the thunder and the hail ceased, and the rain stopped pouring on the earth.'
EXEC add_BibleVerse @BibleId, 102009034, N'When Pharaoh saw that the rain and hail and thunder ceased, he sinned again: both he and his servants hardened their hearts.'
EXEC add_BibleVerse @BibleId, 102009035, N'So Pharaoh’s heart remained hard, and he did not release the Israelites, as the Lord had predicted through Moses.'
EXEC add_BibleVerse @BibleId, 102010001, N'The Lord said to Moses, “Go to Pharaoh, for I have hardened his heart and the heart of his servants, in order to display these signs of mine before him,'
EXEC add_BibleVerse @BibleId, 102010002, N'and in order that in the hearing of your son and your grandson you may tell how I made fools of the Egyptians and about my signs that I displayed among them, so that you may know that I am the Lord.”'
EXEC add_BibleVerse @BibleId, 102010003, N'So Moses and Aaron came to Pharaoh and told him, “Thus says the Lord, the God of the Hebrews: ‘How long do you refuse to humble yourself before me? Release my people so that they may serve me!'
EXEC add_BibleVerse @BibleId, 102010004, N'But if you refuse to release my people, I am going to bring locusts into your territory tomorrow.'
EXEC add_BibleVerse @BibleId, 102010005, N'They will cover the surface of the earth, so that you will be unable to see the ground. They will eat the remainder of what escaped – what is left over for you – from the hail, and they will eat every tree that grows for you from the field.'
EXEC add_BibleVerse @BibleId, 102010006, N'They will fill your houses, the houses of your servants, and all the houses of Egypt, such as neither your fathers nor your grandfathers have seen since they have been in the land until this day!’” Then Moses turned and went out from Pharaoh.'
EXEC add_BibleVerse @BibleId, 102010007, N'Pharaoh’s servants said to him, “How long will this man be a menace to us? Release the people so that they may serve the Lord their God. Do you not know that Egypt is destroyed?”'
EXEC add_BibleVerse @BibleId, 102010008, N'So Moses and Aaron were brought back to Pharaoh, and he said to them, “Go, serve the Lord your God. Exactly who is going with you?”'
EXEC add_BibleVerse @BibleId, 102010009, N'Moses said, “We will go with our young and our old, with our sons and our daughters, and with our sheep and our cattle we will go, because we are to hold a pilgrim feast for the Lord.”'
EXEC add_BibleVerse @BibleId, 102010010, N'He said to them, “The Lord will need to be with you if I release you and your dependents! Watch out! Trouble is right in front of you!'
EXEC add_BibleVerse @BibleId, 102010011, N'No! Go, you men only, and serve the Lord, for that is what you want.” Then Moses and Aaron were driven out of Pharaoh’s presence.'
EXEC add_BibleVerse @BibleId, 102010012, N'The Lord said to Moses, “Extend your hand over the land of Egypt for the locusts, that they may come up over the land of Egypt and eat everything that grows in the ground, everything that the hail has left.”'
EXEC add_BibleVerse @BibleId, 102010013, N'So Moses extended his staff over the land of Egypt, and then the Lord brought an east wind on the land all that day and all night. The morning came, and the east wind had brought up the locusts!'
EXEC add_BibleVerse @BibleId, 102010014, N'The locusts went up over all the land of Egypt and settled down in all the territory of Egypt. It was very severe; there had been no locusts like them before, nor will there be such ever again.'
EXEC add_BibleVerse @BibleId, 102010015, N'They covered the surface of all the ground, so that the ground became dark with them, and they ate all the vegetation of the ground and all the fruit of the trees that the hail had left. Nothing green remained on the trees or on anything that grew in the fields throughout the whole land of Egypt.'
EXEC add_BibleVerse @BibleId, 102010016, N'Then Pharaoh quickly summoned Moses and Aaron and said, “I have sinned against the Lord your God and against you!'
EXEC add_BibleVerse @BibleId, 102010017, N'So now, forgive my sin this time only, and pray to the Lord your God that he would only take this death away from me.”'
EXEC add_BibleVerse @BibleId, 102010018, N'Moses went out from Pharaoh and prayed to the Lord,'
EXEC add_BibleVerse @BibleId, 102010019, N'and the Lord turned a very strong west wind, and it picked up the locusts and blew them into the Red Sea. Not one locust remained in all the territory of Egypt.'
EXEC add_BibleVerse @BibleId, 102010020, N'But the Lord hardened Pharaoh’s heart, and he did not release the Israelites.'
EXEC add_BibleVerse @BibleId, 102010021, N'The Lord said to Moses, “Extend your hand toward heaven so that there may be darkness over the land of Egypt, a darkness so thick it can be felt.”'
EXEC add_BibleVerse @BibleId, 102010022, N'So Moses extended his hand toward heaven, and there was absolute darkness throughout the land of Egypt for three days.'
EXEC add_BibleVerse @BibleId, 102010023, N'No one could see another person, and no one could rise from his place for three days. But the Israelites had light in the places where they lived.'
EXEC add_BibleVerse @BibleId, 102010024, N'Then Pharaoh summoned Moses and said, “Go, serve the Lord – only your flocks and herds will be detained. Even your families may go with you.”'
EXEC add_BibleVerse @BibleId, 102010025, N'But Moses said, “Will you also provide us with sacrifices and burnt offerings that we may present them to the Lord our God?'
EXEC add_BibleVerse @BibleId, 102010026, N'Our livestock must also go with us! Not a hoof is to be left behind! For we must take these animals to serve the Lord our God. Until we arrive there, we do not know what we must use to serve the Lord.”'
EXEC add_BibleVerse @BibleId, 102010027, N'But the Lord hardened Pharaoh’s heart, and he was not willing to release them.'
EXEC add_BibleVerse @BibleId, 102010028, N'Pharaoh said to him, “Go from me! Watch out for yourself! Do not appear before me again, for when you see my face you will die!”'
EXEC add_BibleVerse @BibleId, 102010029, N'Moses said, “As you wish! I will not see your face again.”'
EXEC add_BibleVerse @BibleId, 102011001, N'The Lord said to Moses, “I will bring one more plague on Pharaoh and on Egypt; after that he will release you from this place. When he releases you, he will drive you out completely from this place.'
EXEC add_BibleVerse @BibleId, 102011002, N'Instruct the people that each man and each woman is to request from his or her neighbor items of silver and gold.”'
EXEC add_BibleVerse @BibleId, 102011003, N'(Now the Lord granted the people favor with the Egyptians. Moreover, the man Moses was very great in the land of Egypt, respected by Pharaoh’s servants and by the Egyptian people.)'
EXEC add_BibleVerse @BibleId, 102011004, N'Moses said, “Thus says the Lord: ‘About midnight I will go throughout Egypt,'
EXEC add_BibleVerse @BibleId, 102011005, N'and all the firstborn in the land of Egypt will die, from the firstborn son of Pharaoh who sits on his throne, to the firstborn son of the slave girl who is at her hand mill, and all the firstborn of the cattle.'
EXEC add_BibleVerse @BibleId, 102011006, N'There will be a great cry throughout the whole land of Egypt, such as there has never been, nor ever will be again.'
EXEC add_BibleVerse @BibleId, 102011007, N'But against any of the Israelites not even a dog will bark against either people or animals, so that you may know that the Lord distinguishes between Egypt and Israel.’'
EXEC add_BibleVerse @BibleId, 102011008, N'All these your servants will come down to me and bow down to me, saying, ‘Go, you and all the people who follow you,’ and after that I will go out.” Then Moses went out from Pharaoh in great anger.'
EXEC add_BibleVerse @BibleId, 102011009, N'The Lord said to Moses, “Pharaoh will not listen to you, so that my wonders may be multiplied in the land of Egypt.”'
EXEC add_BibleVerse @BibleId, 102011010, N'So Moses and Aaron did all these wonders before Pharaoh, but the Lord hardened Pharaoh’s heart, and he did not release the Israelites from his land.'
EXEC add_BibleVerse @BibleId, 102012001, N'The Lord said to Moses and Aaron in the land of Egypt,'
EXEC add_BibleVerse @BibleId, 102012002, N'“This month is to be your beginning of months; it will be your first month of the year.'
EXEC add_BibleVerse @BibleId, 102012003, N'Tell the whole community of Israel, ‘In the tenth day of this month they each must take a lamb for themselves according to their families – a lamb for each household.'
EXEC add_BibleVerse @BibleId, 102012004, N'If any household is too small for a lamb, the man and his next-door neighbor are to take a lamb according to the number of people – you will make your count for the lamb according to how much each one can eat.'
EXEC add_BibleVerse @BibleId, 102012005, N'Your lamb must be perfect, a male, one year old; you may take it from the sheep or from the goats.'
EXEC add_BibleVerse @BibleId, 102012006, N'You must care for it until the fourteenth day of this month, and then the whole community of Israel will kill it around sundown.'
EXEC add_BibleVerse @BibleId, 102012007, N'They will take some of the blood and put it on the two side posts and top of the doorframe of the houses where they will eat it.'
EXEC add_BibleVerse @BibleId, 102012008, N'They will eat the meat the same night; they will eat it roasted over the fire with bread made without yeast and with bitter herbs.'
EXEC add_BibleVerse @BibleId, 102012009, N'Do not eat it raw or boiled in water, but roast it over the fire with its head, its legs, and its entrails.'
EXEC add_BibleVerse @BibleId, 102012010, N'You must leave nothing until morning, but you must burn with fire whatever remains of it until morning.'
EXEC add_BibleVerse @BibleId, 102012011, N'This is how you are to eat it – dressed to travel, your sandals on your feet, and your staff in your hand. You are to eat it in haste. It is the Lord’s Passover.'
EXEC add_BibleVerse @BibleId, 102012012, N'I will pass through the land of Egypt in the same night, and I will attack all the firstborn in the land of Egypt, both of humans and of animals, and on all the gods of Egypt I will execute judgment. I am the Lord.'
EXEC add_BibleVerse @BibleId, 102012013, N'The blood will be a sign for you on the houses where you are, so that when I see the blood I will pass over you, and this plague will not fall on you to destroy you when I attack the land of Egypt.'
EXEC add_BibleVerse @BibleId, 102012014, N'This day will become a memorial for you, and you will celebrate it as a festival to the Lord – you will celebrate it perpetually as a lasting ordinance.'
EXEC add_BibleVerse @BibleId, 102012015, N'For seven days you must eat bread made without yeast. Surely on the first day you must put away yeast from your houses because anyone who eats bread made with yeast from the first day to the seventh day will be cut off from Israel.'
EXEC add_BibleVerse @BibleId, 102012016, N'On the first day there will be a holy convocation, and on the seventh day there will be a holy convocation for you. You must do no work of any kind on them, only what every person will eat – that alone may be prepared for you.'
EXEC add_BibleVerse @BibleId, 102012017, N'So you will keep the Feast of Unleavened Bread, because on this very day I brought your regiments out from the land of Egypt, and so you must keep this day perpetually as a lasting ordinance.'
EXEC add_BibleVerse @BibleId, 102012018, N'In the first month, from the fourteenth day of the month, in the evening, you will eat bread made without yeast until the twenty-first day of the month in the evening.'
EXEC add_BibleVerse @BibleId, 102012019, N'For seven days yeast must not be found in your houses, for whoever eats what is made with yeast – that person will be cut off from the community of Israel, whether a foreigner or one born in the land.'
EXEC add_BibleVerse @BibleId, 102012020, N'You will not eat anything made with yeast; in all the places where you live you must eat bread made without yeast.’”'
EXEC add_BibleVerse @BibleId, 102012021, N'Then Moses summoned all the elders of Israel, and told them, “Go and select for yourselves a lamb or young goat for your families, and kill the Passover animals.'
EXEC add_BibleVerse @BibleId, 102012022, N'Take a branch of hyssop, dip it in the blood that is in the basin, and apply to the top of the doorframe and the two side posts some of the blood that is in the basin. Not one of you is to go out the door of his house until morning.'
EXEC add_BibleVerse @BibleId, 102012023, N'For the Lord will pass through to strike Egypt, and when he sees the blood on the top of the doorframe and the two side posts, then the Lord will pass over the door, and he will not permit the destroyer to enter your houses to strike you.'
EXEC add_BibleVerse @BibleId, 102012024, N'You must observe this event as an ordinance for you and for your children forever.'
EXEC add_BibleVerse @BibleId, 102012025, N'When you enter the land that the Lord will give to you, just as he said, you must observe this ceremony.'
EXEC add_BibleVerse @BibleId, 102012026, N'When your children ask you, ‘What does this ceremony mean to you?’ –'
EXEC add_BibleVerse @BibleId, 102012027, N'then you will say, ‘It is the sacrifice of the Lord’s Passover, when he passed over the houses of the Israelites in Egypt, when he struck Egypt and delivered our households.’” The people bowed down low to the ground,'
EXEC add_BibleVerse @BibleId, 102012028, N'and the Israelites went away and did exactly as the Lord had commanded Moses and Aaron.'
EXEC add_BibleVerse @BibleId, 102012029, N'It happened at midnight – the Lord attacked all the firstborn in the land of Egypt, from the firstborn of Pharaoh who sat on his throne to the firstborn of the captive who was in the prison, and all the firstborn of the cattle.'
EXEC add_BibleVerse @BibleId, 102012030, N'Pharaoh got up in the night, along with all his servants and all Egypt, and there was a great cry in Egypt, for there was no house in which there was not someone dead.'
EXEC add_BibleVerse @BibleId, 102012031, N'Pharaoh summoned Moses and Aaron in the night and said, “Get up, get out from among my people, both you and the Israelites! Go, serve the Lord as you have requested!'
EXEC add_BibleVerse @BibleId, 102012032, N'Also, take your flocks and your herds, just as you have requested, and leave. But bless me also.”'
EXEC add_BibleVerse @BibleId, 102012033, N'The Egyptians were urging the people on, in order to send them out of the land quickly, for they were saying, “We are all dead!”'
EXEC add_BibleVerse @BibleId, 102012034, N'So the people took their dough before the yeast was added, with their kneading troughs bound up in their clothing on their shoulders.'
EXEC add_BibleVerse @BibleId, 102012035, N'Now the Israelites had done as Moses told them – they had requested from the Egyptians silver and gold items and clothing.'
EXEC add_BibleVerse @BibleId, 102012036, N'The Lord gave the people favor in the sight of the Egyptians, and they gave them whatever they wanted, and so they plundered Egypt.'
EXEC add_BibleVerse @BibleId, 102012037, N'The Israelites journeyed from Rameses to Sukkoth. There were about 600,000 men on foot, plus their dependants.'
EXEC add_BibleVerse @BibleId, 102012038, N'A mixed multitude also went up with them, and flocks and herds – a very large number of cattle.'
EXEC add_BibleVerse @BibleId, 102012039, N'They baked cakes of bread without yeast using the dough they had brought from Egypt, for it was made without yeast – because they were thrust out of Egypt and were not able to delay, they could not prepare food for themselves either.'
EXEC add_BibleVerse @BibleId, 102012040, N'Now the length of time the Israelites lived in Egypt was 430 years.'
EXEC add_BibleVerse @BibleId, 102012041, N'At the end of the 430 years, on the very day, all the regiments of the Lord went out of the land of Egypt.'
EXEC add_BibleVerse @BibleId, 102012042, N'It was a night of vigil for the Lord to bring them out from the land of Egypt, and so on this night all Israel is to keep the vigil to the Lord for generations to come.'
EXEC add_BibleVerse @BibleId, 102012043, N'The Lord said to Moses and Aaron, “This is the ordinance of the Passover. No foreigner may share in eating it.'
EXEC add_BibleVerse @BibleId, 102012044, N'But everyone’s servant who is bought for money, after you have circumcised him, may eat it.'
EXEC add_BibleVerse @BibleId, 102012045, N'A foreigner and a hired worker must not eat it.'
EXEC add_BibleVerse @BibleId, 102012046, N'It must be eaten in one house; you must not bring any of the meat outside the house, and you must not break a bone of it.'
EXEC add_BibleVerse @BibleId, 102012047, N'The whole community of Israel must observe it.'
EXEC add_BibleVerse @BibleId, 102012048, N'“When a foreigner lives with you and wants to observe the Passover to the Lord, all his males must be circumcised, and then he may approach and observe it, and he will be like one who is born in the land – but no uncircumcised person may eat of it.'
EXEC add_BibleVerse @BibleId, 102012049, N'The same law will apply to the person who is native-born and to the foreigner who lives among you.”'
EXEC add_BibleVerse @BibleId, 102012050, N'So all the Israelites did exactly as the Lord commanded Moses and Aaron.'
EXEC add_BibleVerse @BibleId, 102012051, N'And on this very day the Lord brought the Israelites out of the land of Egypt by their regiments.'
EXEC add_BibleVerse @BibleId, 102013001, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 102013002, N'“Set apart to me every firstborn male – the first offspring of every womb among the Israelites, whether human or animal; it is mine.”'
EXEC add_BibleVerse @BibleId, 102013003, N'Moses said to the people, “Remember this day on which you came out from Egypt, from the place where you were enslaved, for the Lord brought you out of there with a mighty hand – and no bread made with yeast may be eaten.'
EXEC add_BibleVerse @BibleId, 102013004, N'On this day, in the month of Abib, you are going out.'
EXEC add_BibleVerse @BibleId, 102013005, N'When the Lord brings you to the land of the Canaanites, Hittites, Amorites, Hivites, and Jebusites, which he swore to your fathers to give you, a land flowing with milk and honey, then you will keep this ceremony in this month.'
EXEC add_BibleVerse @BibleId, 102013006, N'For seven days you must eat bread made without yeast, and on the seventh day there is to be a festival to the Lord.'
EXEC add_BibleVerse @BibleId, 102013007, N'Bread made without yeast must be eaten for seven days; no bread made with yeast shall be seen among you, and you must have no yeast among you within any of your borders.'
EXEC add_BibleVerse @BibleId, 102013008, N'You are to tell your son on that day, ‘It is because of what the Lord did for me when I came out of Egypt.’'
EXEC add_BibleVerse @BibleId, 102013009, N'It will be a sign for you on your hand and a memorial on your forehead, so that the law of the Lord may be in your mouth, for with a mighty hand the Lord brought you out of Egypt.'
EXEC add_BibleVerse @BibleId, 102013010, N'So you must keep this ordinance at its appointed time from year to year.'
EXEC add_BibleVerse @BibleId, 102013011, N'When the Lord brings you into the land of the Canaanites, as he swore to you and to your fathers, and gives it to you,'
EXEC add_BibleVerse @BibleId, 102013012, N'then you must give over to the Lord the first offspring of every womb. Every firstling of a beast that you have – the males will be the Lord’s.'
EXEC add_BibleVerse @BibleId, 102013013, N'Every firstling of a donkey you must redeem with a lamb, and if you do not redeem it, then you must break its neck. Every firstborn of your sons you must redeem.'
EXEC add_BibleVerse @BibleId, 102013014, N'In the future, when your son asks you ‘What is this?’ you are to tell him, ‘With a mighty hand the Lord brought us out from Egypt, from the land of slavery.'
EXEC add_BibleVerse @BibleId, 102013015, N'When Pharaoh stubbornly refused to release us, the Lord killed all the firstborn in the land of Egypt, from the firstborn of people to the firstborn of animals. That is why I am sacrificing to the Lord the first male offspring of every womb, but all my firstborn sons I redeem.’'
EXEC add_BibleVerse @BibleId, 102013016, N'It will be for a sign on your hand and for frontlets on your forehead, for with a mighty hand the Lord brought us out of Egypt.”'
EXEC add_BibleVerse @BibleId, 102013017, N'When Pharaoh released the people, God did not lead them by the way to the land of the Philistines, although that was nearby, for God said, “Lest the people change their minds and return to Egypt when they experience war.”'
EXEC add_BibleVerse @BibleId, 102013018, N'So God brought the people around by the way of the desert to the Red Sea, and the Israelites went up from the land of Egypt prepared for battle.'
EXEC add_BibleVerse @BibleId, 102013019, N'Moses took the bones of Joseph with him, for Joseph had made the Israelites solemnly swear, “God will surely attend to you, and you will carry my bones up from this place with you.”'
EXEC add_BibleVerse @BibleId, 102013020, N'They journeyed from Sukkoth and camped in Etham, on the edge of the desert.'
EXEC add_BibleVerse @BibleId, 102013021, N'Now the Lord was going before them by day in a pillar of cloud to lead them in the way, and by night in a pillar of fire to give them light, so that they could travel day or night.'
EXEC add_BibleVerse @BibleId, 102013022, N'He did not remove the pillar of cloud by day nor the pillar of fire by night from before the people.'
EXEC add_BibleVerse @BibleId, 102014001, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 102014002, N'“Tell the Israelites that they must turn and camp before Pi-hahiroth, between Migdol and the sea; you are to camp by the sea before Baal Zephon opposite it.'
EXEC add_BibleVerse @BibleId, 102014003, N'Pharaoh will think regarding the Israelites, ‘They are wandering around confused in the land – the desert has closed in on them.’'
EXEC add_BibleVerse @BibleId, 102014004, N'I will harden Pharaoh’s heart, and he will chase after them. I will gain honor because of Pharaoh and because of all his army, and the Egyptians will know that I am the Lord.” So this is what they did.'
EXEC add_BibleVerse @BibleId, 102014005, N'When it was reported to the king of Egypt that the people had fled, the heart of Pharaoh and his servants was turned against the people, and the king and his servants said, “What in the world have we done? For we have released the people of Israel from serving us!”'
EXEC add_BibleVerse @BibleId, 102014006, N'Then he prepared his chariots and took his army with him.'
EXEC add_BibleVerse @BibleId, 102014007, N'He took six hundred select chariots, and all the rest of the chariots of Egypt, and officers on all of them.'
EXEC add_BibleVerse @BibleId, 102014008, N'But the Lord hardened the heart of Pharaoh king of Egypt, and he chased after the Israelites. Now the Israelites were going out defiantly.'
EXEC add_BibleVerse @BibleId, 102014009, N'The Egyptians chased after them, and all the horses and chariots of Pharaoh and his horsemen and his army overtook them camping by the sea, beside Pi-hahiroth, before Baal-Zephon.'
EXEC add_BibleVerse @BibleId, 102014010, N'When Pharaoh got closer, the Israelites looked up, and there were the Egyptians marching after them, and they were terrified. The Israelites cried out to the Lord,'
EXEC add_BibleVerse @BibleId, 102014011, N'and they said to Moses, “Is it because there are no graves in Egypt that you have taken us away to die in the desert? What in the world have you done to us by bringing us out of Egypt?'
EXEC add_BibleVerse @BibleId, 102014012, N'Isn’t this what we told you in Egypt, ‘Leave us alone so that we can serve the Egyptians, because it is better for us to serve the Egyptians than to die in the desert!’”'
EXEC add_BibleVerse @BibleId, 102014013, N'Moses said to the people, “Do not fear! Stand firm and see the salvation of the Lord that he will provide for you today; for the Egyptians that you see today you will never, ever see again.'
EXEC add_BibleVerse @BibleId, 102014014, N'The Lord will fight for you, and you can be still.”'
EXEC add_BibleVerse @BibleId, 102014015, N'The Lord said to Moses, “Why do you cry out to me? Tell the Israelites to move on.'
EXEC add_BibleVerse @BibleId, 102014016, N'And as for you, lift up your staff and extend your hand toward the sea and divide it, so that the Israelites may go through the middle of the sea on dry ground.'
EXEC add_BibleVerse @BibleId, 102014017, N'And as for me, I am going to harden the hearts of the Egyptians so that they will come after them, that I may be honored because of Pharaoh and his army and his chariots and his horsemen.'
EXEC add_BibleVerse @BibleId, 102014018, N'And the Egyptians will know that I am the Lord when I have gained my honor because of Pharaoh, his chariots, and his horsemen.”'
EXEC add_BibleVerse @BibleId, 102014019, N'The angel of God, who was going before the camp of Israel, moved and went behind them, and the pillar of cloud moved from before them and stood behind them.'
EXEC add_BibleVerse @BibleId, 102014020, N'It came between the Egyptian camp and the Israelite camp; it was a dark cloud and it lit up the night so that one camp did not come near the other the whole night.'
EXEC add_BibleVerse @BibleId, 102014021, N'Moses stretched out his hand toward the sea, and the Lord drove the sea apart by a strong east wind all that night, and he made the sea into dry land, and the water was divided.'
EXEC add_BibleVerse @BibleId, 102014022, N'So the Israelites went through the middle of the sea on dry ground, the water forming a wall for them on their right and on their left.'
EXEC add_BibleVerse @BibleId, 102014023, N'The Egyptians chased them and followed them into the middle of the sea – all the horses of Pharaoh, his chariots, and his horsemen.'
EXEC add_BibleVerse @BibleId, 102014024, N'In the morning watch the Lord looked down on the Egyptian army through the pillar of fire and cloud, and he threw the Egyptian army into a panic.'
EXEC add_BibleVerse @BibleId, 102014025, N'He jammed the wheels of their chariots so that they had difficulty driving, and the Egyptians said, “Let’s flee from Israel, for the Lord fights for them against Egypt!”'
EXEC add_BibleVerse @BibleId, 102014026, N'The Lord said to Moses, “Extend your hand toward the sea, so that the waters may flow back on the Egyptians, on their chariots, and on their horsemen!”'
EXEC add_BibleVerse @BibleId, 102014027, N'So Moses extended his hand toward the sea, and the sea returned to its normal state when the sun began to rise. Now the Egyptians were fleeing before it, but the Lord overthrew the Egyptians in the middle of the sea.'
EXEC add_BibleVerse @BibleId, 102014028, N'The water returned and covered the chariots and the horsemen and all the army of Pharaoh that was coming after the Israelites into the sea – not so much as one of them survived!'
EXEC add_BibleVerse @BibleId, 102014029, N'But the Israelites walked on dry ground in the middle of the sea, the water forming a wall for them on their right and on their left.'
EXEC add_BibleVerse @BibleId, 102014030, N'So the Lord saved Israel on that day from the power of the Egyptians, and Israel saw the Egyptians dead on the shore of the sea.'
EXEC add_BibleVerse @BibleId, 102014031, N'When Israel saw the great power that the Lord had exercised over the Egyptians, they feared the Lord, and they believed in the Lord and in his servant Moses.'
EXEC add_BibleVerse @BibleId, 102015001, N'Then Moses and the Israelites sang this song to the Lord. They said, “I will sing to the Lord, for he has triumphed gloriously, the horse and its rider he has thrown into the sea.'
EXEC add_BibleVerse @BibleId, 102015002, N'The Lord is my strength and my song, and he has become my salvation. This is my God, and I will praise him, my father’s God, and I will exalt him.'
EXEC add_BibleVerse @BibleId, 102015003, N'The Lord is a warrior, the Lord is his name.'
EXEC add_BibleVerse @BibleId, 102015004, N'The chariots of Pharaoh and his army he has thrown into the sea, and his chosen officers were drowned in the Red Sea.'
EXEC add_BibleVerse @BibleId, 102015005, N'The depths have covered them, they went down to the bottom like a stone.'
EXEC add_BibleVerse @BibleId, 102015006, N'Your right hand, O Lord, was majestic in power, your right hand, O Lord, shattered the enemy.'
EXEC add_BibleVerse @BibleId, 102015007, N'In the abundance of your majesty you have overthrown those who rise up against you. You sent forth your wrath; it consumed them like stubble.'
EXEC add_BibleVerse @BibleId, 102015008, N'By the blast of your nostrils the waters were piled up, the flowing water stood upright like a heap, and the deep waters were solidified in the heart of the sea.'
EXEC add_BibleVerse @BibleId, 102015009, N'The enemy said, ‘I will chase, I will overtake, I will divide the spoil; my desire will be satisfied on them. I will draw my sword, my hand will destroy them.’'
EXEC add_BibleVerse @BibleId, 102015010, N'But you blew with your breath, and the sea covered them. They sank like lead in the mighty waters.'
EXEC add_BibleVerse @BibleId, 102015011, N'Who is like you, O Lord, among the gods? Who is like you? – majestic in holiness, fearful in praises, working wonders?'
EXEC add_BibleVerse @BibleId, 102015012, N'You stretched out your right hand, the earth swallowed them.'
EXEC add_BibleVerse @BibleId, 102015013, N'By your loyal love you will lead the people whom you have redeemed; you will guide them by your strength to your holy dwelling place.'
EXEC add_BibleVerse @BibleId, 102015014, N'The nations will hear and tremble; anguish will seize the inhabitants of Philistia.'
EXEC add_BibleVerse @BibleId, 102015015, N'Then the chiefs of Edom will be terrified, trembling will seize the leaders of Moab, and the inhabitants of Canaan will shake.'
EXEC add_BibleVerse @BibleId, 102015016, N'Fear and dread will fall on them; by the greatness of your arm they will be as still as stone until your people pass by, O Lord, until the people whom you have bought pass by.'
EXEC add_BibleVerse @BibleId, 102015017, N'You will bring them in and plant them in the mountain of your inheritance, in the place you made for your residence, O Lord, the sanctuary, O Lord, that your hands have established.'
EXEC add_BibleVerse @BibleId, 102015018, N'The Lord will reign forever and ever!'
EXEC add_BibleVerse @BibleId, 102015019, N'For the horses of Pharaoh came with his chariots and his footmen into the sea, and the Lord brought back the waters of the sea on them, but the Israelites walked on dry land in the middle of the sea.”'
EXEC add_BibleVerse @BibleId, 102015020, N'Miriam the prophetess, the sister of Aaron, took a hand-drum in her hand, and all the women went out after her with hand-drums and with dances.'
EXEC add_BibleVerse @BibleId, 102015021, N'Miriam sang in response to them, “Sing to the Lord, for he has triumphed gloriously; the horse and its rider he has thrown into the sea.”'
EXEC add_BibleVerse @BibleId, 102015022, N'Then Moses led Israel to journey away from the Red Sea. They went out to the Desert of Shur, walked for three days into the desert, and found no water.'
EXEC add_BibleVerse @BibleId, 102015023, N'Then they came to Marah, but they were not able to drink the waters of Marah, because they were bitter. (That is why its name was Marah.)'
EXEC add_BibleVerse @BibleId, 102015024, N'So the people murmured against Moses, saying, “What can we drink?”'
EXEC add_BibleVerse @BibleId, 102015025, N'He cried out to the Lord, and the Lord showed him a tree. When Moses threw it into the water, the water became safe to drink. There the Lord made for them a binding ordinance, and there he tested them.'
EXEC add_BibleVerse @BibleId, 102015026, N'He said, “If you will diligently obey the Lord your God, and do what is right in his sight, and pay attention to his commandments, and keep all his statutes, then all the diseases that I brought on the Egyptians I will not bring on you, for I, the Lord, am your healer.”'
EXEC add_BibleVerse @BibleId, 102015027, N'Then they came to Elim, where there were twelve wells of water and seventy palm trees, and they camped there by the water.'
EXEC add_BibleVerse @BibleId, 102016001, N'When they journeyed from Elim, the entire company of Israelites came to the Desert of Sin, which is between Elim and Sinai, on the fifteenth day of the second month after their exodus from the land of Egypt.'
EXEC add_BibleVerse @BibleId, 102016002, N'The entire company of Israelites murmured against Moses and Aaron in the desert.'
EXEC add_BibleVerse @BibleId, 102016003, N'The Israelites said to them, “If only we had died by the hand of the Lord in the land of Egypt, when we sat by the pots of meat, when we ate bread to the full, for you have brought us out into this desert to kill this whole assembly with hunger!”'
EXEC add_BibleVerse @BibleId, 102016004, N'Then the Lord said to Moses, “I am going to rain bread from heaven for you, and the people will go out and gather the amount for each day, so that I may test them. Will they walk in my law or not?'
EXEC add_BibleVerse @BibleId, 102016005, N'On the sixth day they will prepare what they bring in, and it will be twice as much as they gather every other day.”'
EXEC add_BibleVerse @BibleId, 102016006, N'Moses and Aaron said to all the Israelites, “In the evening you will know that the Lord has brought you out of the land of Egypt,'
EXEC add_BibleVerse @BibleId, 102016007, N'and in the morning you will see the glory of the Lord, because he has heard your murmurings against the Lord. As for us, what are we, that you should murmur against us?”'
EXEC add_BibleVerse @BibleId, 102016008, N'Moses said, “You will know this when the Lord gives you meat to eat in the evening and bread in the morning to satisfy you, because the Lord has heard your murmurings that you are murmuring against him. As for us, what are we? Your murmurings are not against us, but against the Lord.”'
EXEC add_BibleVerse @BibleId, 102016009, N'Then Moses said to Aaron, “Tell the whole community of the Israelites, ‘Come before the Lord, because he has heard your murmurings.’”'
EXEC add_BibleVerse @BibleId, 102016010, N'As Aaron spoke to the whole community of the Israelites and they looked toward the desert, there the glory of the Lord appeared in the cloud,'
EXEC add_BibleVerse @BibleId, 102016011, N'and the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 102016012, N'“I have heard the murmurings of the Israelites. Tell them, ‘During the evening you will eat meat, and in the morning you will be satisfied with bread, so that you may know that I am the Lord your God.’”'
EXEC add_BibleVerse @BibleId, 102016013, N'In the evening the quail came up and covered the camp, and in the morning a layer of dew was all around the camp.'
EXEC add_BibleVerse @BibleId, 102016014, N'When the layer of dew had evaporated, there on the surface of the desert was a thin flaky substance, thin like frost on the earth.'
EXEC add_BibleVerse @BibleId, 102016015, N'When the Israelites saw it, they said to one another, “What is it?” because they did not know what it was. Moses said to them, “It is the bread that the Lord has given you for food.'
EXEC add_BibleVerse @BibleId, 102016016, N'“This is what the Lord has commanded: ‘Each person is to gather from it what he can eat, an omer per person according to the number of your people; each one will pick it up for whoever lives in his tent.’”'
EXEC add_BibleVerse @BibleId, 102016017, N'The Israelites did so, and they gathered – some more, some less.'
EXEC add_BibleVerse @BibleId, 102016018, N'When they measured with an omer, the one who gathered much had nothing left over, and the one who gathered little lacked nothing; each one had gathered what he could eat.'
EXEC add_BibleVerse @BibleId, 102016019, N'Moses said to them, “No one is to keep any of it until morning.”'
EXEC add_BibleVerse @BibleId, 102016020, N'But they did not listen to Moses; some kept part of it until morning, and it was full of worms and began to stink, and Moses was angry with them.'
EXEC add_BibleVerse @BibleId, 102016021, N'So they gathered it each morning, each person according to what he could eat, and when the sun got hot, it would melt.'
EXEC add_BibleVerse @BibleId, 102016022, N'And on the sixth day they gathered twice as much food, two omers per person; and all the leaders of the community came and told Moses.'
EXEC add_BibleVerse @BibleId, 102016023, N'He said to them, “This is what the Lord has said: ‘Tomorrow is a time of cessation from work, a holy Sabbath to the Lord. Whatever you want to bake, bake today; whatever you want to boil, boil today; whatever is left put aside for yourselves to be kept until morning.’”'
EXEC add_BibleVerse @BibleId, 102016024, N'So they put it aside until the morning, just as Moses had commanded, and it did not stink, nor were there any worms in it.'
EXEC add_BibleVerse @BibleId, 102016025, N'Moses said, “Eat it today, for today is a Sabbath to the Lord; today you will not find it in the area.'
EXEC add_BibleVerse @BibleId, 102016026, N'Six days you will gather it, but on the seventh day, the Sabbath, there will not be any.”'
EXEC add_BibleVerse @BibleId, 102016027, N'On the seventh day some of the people went out to gather it, but they found nothing.'
EXEC add_BibleVerse @BibleId, 102016028, N'So the Lord said to Moses, “How long do you refuse to obey my commandments and my instructions?'
EXEC add_BibleVerse @BibleId, 102016029, N'See, because the Lord has given you the Sabbath, that is why he is giving you food for two days on the sixth day. Each of you stay where you are; let no one go out of his place on the seventh day.”'
EXEC add_BibleVerse @BibleId, 102016030, N'So the people rested on the seventh day.'
EXEC add_BibleVerse @BibleId, 102016031, N'The house of Israel called its name “manna.” It was like coriander seed and was white, and it tasted like wafers with honey.'
EXEC add_BibleVerse @BibleId, 102016032, N'Moses said, “This is what the Lord has commanded: ‘Fill an omer with it to be kept for generations to come, so that they may see the food I fed you in the desert when I brought you out from the land of Egypt.’”'
EXEC add_BibleVerse @BibleId, 102016033, N'Moses said to Aaron, “Take a jar and put in it an omer full of manna, and place it before the Lord to be kept for generations to come.”'
EXEC add_BibleVerse @BibleId, 102016034, N'Just as the Lord commanded Moses, so Aaron placed it before the Testimony for safekeeping.'
EXEC add_BibleVerse @BibleId, 102016035, N'Now the Israelites ate manna forty years, until they came to a land that was inhabited; they ate manna until they came to the border of the land of Canaan.'
EXEC add_BibleVerse @BibleId, 102016036, N'(Now an omer is one tenth of an ephah.)'
EXEC add_BibleVerse @BibleId, 102017001, N'The whole community of the Israelites traveled on their journey from the Desert of Sin according to the Lord’s instruction, and they pitched camp in Rephidim. Now there was no water for the people to drink.'
EXEC add_BibleVerse @BibleId, 102017002, N'So the people contended with Moses, and they said, “Give us water to drink!” Moses said to them, “Why do you contend with me? Why do you test the Lord?”'
EXEC add_BibleVerse @BibleId, 102017003, N'But the people were very thirsty there for water, and they murmured against Moses and said, “Why in the world did you bring us up out of Egypt – to kill us and our children and our cattle with thirst?”'
EXEC add_BibleVerse @BibleId, 102017004, N'Then Moses cried out to the Lord, “What will I do with this people? – a little more and they will stone me!”'
EXEC add_BibleVerse @BibleId, 102017005, N'The Lord said to Moses, “Go over before the people; take with you some of the elders of Israel and take in your hand your staff with which you struck the Nile and go.'
EXEC add_BibleVerse @BibleId, 102017006, N'I will be standing before you there on the rock in Horeb, and you will strike the rock, and water will come out of it so that the people may drink.” And Moses did so in plain view of the elders of Israel.'
EXEC add_BibleVerse @BibleId, 102017007, N'He called the name of the place Massah and Meribah, because of the contending of the Israelites and because of their testing the Lord, saying, “Is the Lord among us or not?”'
EXEC add_BibleVerse @BibleId, 102017008, N'Amalek came and attacked Israel in Rephidim.'
EXEC add_BibleVerse @BibleId, 102017009, N'So Moses said to Joshua, “Choose some of our men and go out, fight against Amalek. Tomorrow I will stand on top of the hill with the staff of God in my hand.”'
EXEC add_BibleVerse @BibleId, 102017010, N'So Joshua fought against Amalek just as Moses had instructed him; and Moses and Aaron and Hur went up to the top of the hill.'
EXEC add_BibleVerse @BibleId, 102017011, N'Whenever Moses would raise his hands, then Israel prevailed, but whenever he would rest his hands, then Amalek prevailed.'
EXEC add_BibleVerse @BibleId, 102017012, N'When the hands of Moses became heavy, they took a stone and put it under him, and Aaron and Hur held up his hands, one on one side and one on the other, and so his hands were steady until the sun went down.'
EXEC add_BibleVerse @BibleId, 102017013, N'So Joshua destroyed Amalek and his army with the sword.'
EXEC add_BibleVerse @BibleId, 102017014, N'The Lord said to Moses, “Write this as a memorial in the book, and rehearse it in Joshua’s hearing; for I will surely wipe out the remembrance of Amalek from under heaven.'
EXEC add_BibleVerse @BibleId, 102017015, N'Moses built an altar, and he called it “The Lord is my Banner,”'
EXEC add_BibleVerse @BibleId, 102017016, N'for he said, “For a hand was lifted up to the throne of the Lord – that the Lord will have war with Amalek from generation to generation.”'
EXEC add_BibleVerse @BibleId, 102018001, N'Jethro, the priest of Midian, Moses’ father-in-law, heard about all that God had done for Moses and for his people Israel, that the Lord had brought Israel out of Egypt.'
EXEC add_BibleVerse @BibleId, 102018002, N'Jethro, Moses’ father-in-law, took Moses’ wife Zipporah after he had sent her back,'
EXEC add_BibleVerse @BibleId, 102018003, N'and her two sons, one of whom was named Gershom (for Moses had said, “I have been a foreigner in a foreign land”),'
EXEC add_BibleVerse @BibleId, 102018004, N'and the other Eliezer (for Moses had said, “The God of my father has been my help and delivered me from the sword of Pharaoh”).'
EXEC add_BibleVerse @BibleId, 102018005, N'Jethro, Moses’ father-in-law, together with Moses’ sons and his wife, came to Moses in the desert where he was camping by the mountain of God.'
EXEC add_BibleVerse @BibleId, 102018006, N'He said to Moses, “I, your father-in-law Jethro, am coming to you, along with your wife and her two sons with her.”'
EXEC add_BibleVerse @BibleId, 102018007, N'Moses went out to meet his father-in-law and bowed down and kissed him; they each asked about the other’s welfare, and then they went into the tent.'
EXEC add_BibleVerse @BibleId, 102018008, N'Moses told his father-in-law all that the Lord had done to Pharaoh and to Egypt for Israel’s sake, and all the hardship that had come on them along the way, and how the Lord had delivered them.'
EXEC add_BibleVerse @BibleId, 102018009, N'Jethro rejoiced because of all the good that the Lord had done for Israel, whom he had delivered from the hand of Egypt.'
EXEC add_BibleVerse @BibleId, 102018010, N'Jethro said, “Blessed be the Lord who has delivered you from the hand of Egypt, and from the hand of Pharaoh, who has delivered the people from the Egyptians’ control!'
EXEC add_BibleVerse @BibleId, 102018011, N'Now I know that the Lord is greater than all the gods, for in the thing in which they dealt proudly against them he has destroyed them.”'
EXEC add_BibleVerse @BibleId, 102018012, N'Then Jethro, Moses’ father-in-law, brought a burnt offering and sacrifices for God, and Aaron and all the elders of Israel came to eat food with the father-in-law of Moses before God.'
EXEC add_BibleVerse @BibleId, 102018013, N'On the next day Moses sat to judge the people, and the people stood around Moses from morning until evening.'
EXEC add_BibleVerse @BibleId, 102018014, N'When Moses’ father-in-law saw all that he was doing for the people, he said, “What is this that you are doing for the people? Why are you sitting by yourself, and all the people stand around you from morning until evening?”'
EXEC add_BibleVerse @BibleId, 102018015, N'Moses said to his father-in-law, “Because the people come to me to inquire of God.'
EXEC add_BibleVerse @BibleId, 102018016, N'When they have a dispute, it comes to me and I decide between a man and his neighbor, and I make known the decrees of God and his laws.”'
EXEC add_BibleVerse @BibleId, 102018017, N'Moses’ father-in-law said to him, “What you are doing is not good!'
EXEC add_BibleVerse @BibleId, 102018018, N'You will surely wear out, both you and these people who are with you, for this is too heavy a burden for you; you are not able to do it by yourself.'
EXEC add_BibleVerse @BibleId, 102018019, N'Now listen to me, I will give you advice, and may God be with you: You be a representative for the people to God, and you bring their disputes to God;'
EXEC add_BibleVerse @BibleId, 102018020, N'warn them of the statutes and the laws, and make known to them the way in which they must walk and the work they must do.'
EXEC add_BibleVerse @BibleId, 102018021, N'But you choose from the people capable men, God-fearing, men of truth, those who hate bribes, and put them over the people as rulers of thousands, rulers of hundreds, rulers of fifties, and rulers of tens.'
EXEC add_BibleVerse @BibleId, 102018022, N'They will judge the people under normal circumstances, and every difficult case they will bring to you, but every small case they themselves will judge, so that you may make it easier for yourself, and they will bear the burden with you.'
EXEC add_BibleVerse @BibleId, 102018023, N'If you do this thing, and God so commands you, then you will be able to endure, and all these people will be able to go home satisfied.”'
EXEC add_BibleVerse @BibleId, 102018024, N'Moses listened to his father-in-law and did everything he had said.'
EXEC add_BibleVerse @BibleId, 102018025, N'Moses chose capable men from all Israel, and he made them heads over the people, rulers of thousands, rulers of hundreds, rulers of fifties, and rulers of tens.'
EXEC add_BibleVerse @BibleId, 102018026, N'They judged the people under normal circumstances; the difficult cases they would bring to Moses, but every small case they would judge themselves.'
EXEC add_BibleVerse @BibleId, 102018027, N'Then Moses sent his father-in-law on his way, and so Jethro went to his own land.'
EXEC add_BibleVerse @BibleId, 102019001, N'In the third month after the Israelites went out from the land of Egypt, on the very day, they came to the Desert of Sinai.'
EXEC add_BibleVerse @BibleId, 102019002, N'After they journeyed from Rephidim, they came to the Desert of Sinai, and they camped in the desert; Israel camped there in front of the mountain.'
EXEC add_BibleVerse @BibleId, 102019003, N'Moses went up to God, and the Lord called to him from the mountain, “Thus you will tell the house of Jacob, and declare to the people of Israel:'
EXEC add_BibleVerse @BibleId, 102019004, N'‘You yourselves have seen what I did to Egypt and how I lifted you on eagles’ wings and brought you to myself.'
EXEC add_BibleVerse @BibleId, 102019005, N'And now, if you will diligently listen to me and keep my covenant, then you will be my special possession out of all the nations, for all the earth is mine,'
EXEC add_BibleVerse @BibleId, 102019006, N'and you will be to me a kingdom of priests and a holy nation.’ These are the words that you will speak to the Israelites.”'
EXEC add_BibleVerse @BibleId, 102019007, N'So Moses came and summoned the elders of Israel. He set before them all these words that the Lord had commanded him,'
EXEC add_BibleVerse @BibleId, 102019008, N'and all the people answered together, “All that the Lord has commanded we will do!” So Moses brought the words of the people back to the Lord.'
EXEC add_BibleVerse @BibleId, 102019009, N'The Lord said to Moses, “I am going to come to you in a dense cloud, so that the people may hear when I speak with you and so that they will always believe in you.” And Moses told the words of the people to the Lord.'
EXEC add_BibleVerse @BibleId, 102019010, N'The Lord said to Moses, “Go to the people and sanctify them today and tomorrow, and make them wash their clothes'
EXEC add_BibleVerse @BibleId, 102019011, N'and be ready for the third day, for on the third day the Lord will come down on Mount Sinai in the sight of all the people.'
EXEC add_BibleVerse @BibleId, 102019012, N'You must set boundaries for the people all around, saying, ‘Take heed to yourselves not to go up on the mountain nor touch its edge. Whoever touches the mountain will surely be put to death!'
EXEC add_BibleVerse @BibleId, 102019013, N'No hand will touch him – but he will surely be stoned or shot through, whether a beast or a human being; he must not live.’ When the ram’s horn sounds a long blast they may go up on the mountain.”'
EXEC add_BibleVerse @BibleId, 102019014, N'Then Moses went down from the mountain to the people and sanctified the people, and they washed their clothes.'
EXEC add_BibleVerse @BibleId, 102019015, N'He said to the people, “Be ready for the third day. Do not go near your wives.”'
EXEC add_BibleVerse @BibleId, 102019016, N'On the third day in the morning there was thunder and lightning and a dense cloud on the mountain, and the sound of a very loud horn; all the people who were in the camp trembled.'
EXEC add_BibleVerse @BibleId, 102019017, N'Moses brought the people out of the camp to meet God, and they took their place at the foot of the mountain.'
EXEC add_BibleVerse @BibleId, 102019018, N'Now Mount Sinai was completely covered with smoke because the Lord had descended on it in fire, and its smoke went up like the smoke of a great furnace, and the whole mountain shook violently.'
EXEC add_BibleVerse @BibleId, 102019019, N'When the sound of the horn grew louder and louder, Moses was speaking and God was answering him with a voice.'
EXEC add_BibleVerse @BibleId, 102019020, N'The Lord came down on Mount Sinai, on the top of the mountain, and the Lord summoned Moses to the top of the mountain, and Moses went up.'
EXEC add_BibleVerse @BibleId, 102019021, N'The Lord said to Moses, “Go down and solemnly warn the people, lest they force their way through to the Lord to look, and many of them perish.'
EXEC add_BibleVerse @BibleId, 102019022, N'Let the priests also, who approach the Lord, sanctify themselves, lest the Lord break through against them.”'
EXEC add_BibleVerse @BibleId, 102019023, N'Moses said to the Lord, “The people are not able to come up to Mount Sinai, because you solemnly warned us, ‘Set boundaries for the mountain and set it apart.’”'
EXEC add_BibleVerse @BibleId, 102019024, N'The Lord said to him, “Go, get down, and come up, and Aaron with you, but do not let the priests and the people force their way through to come up to the Lord, lest he break through against them.”'
EXEC add_BibleVerse @BibleId, 102019025, N'So Moses went down to the people and spoke to them.'
EXEC add_BibleVerse @BibleId, 102020001, N'God spoke all these words:'
EXEC add_BibleVerse @BibleId, 102020002, N'“I, the Lord, am your God, who brought you from the land of Egypt, from the house of slavery.'
EXEC add_BibleVerse @BibleId, 102020003, N'“You shall have no other gods before me.'
EXEC add_BibleVerse @BibleId, 102020004, N'“You shall not make for yourself a carved image or any likeness of anything that is in heaven above or that is on the earth beneath or that is in the water below.'
EXEC add_BibleVerse @BibleId, 102020005, N'You shall not bow down to them or serve them, for I, the Lord, your God, am a jealous God, responding to the transgression of fathers by dealing with children to the third and fourth generations of those who reject me,'
EXEC add_BibleVerse @BibleId, 102020006, N'and showing covenant faithfulness to a thousand generations of those who love me and keep my commandments.'
EXEC add_BibleVerse @BibleId, 102020007, N'“You shall not take the name of the Lord your God in vain, for the Lord will not hold guiltless anyone who takes his name in vain.'
EXEC add_BibleVerse @BibleId, 102020008, N'“Remember the Sabbath day to set it apart as holy.'
EXEC add_BibleVerse @BibleId, 102020009, N'For six days you may labor and do all your work,'
EXEC add_BibleVerse @BibleId, 102020010, N'but the seventh day is a Sabbath to the Lord your God; on it you shall not do any work, you, or your son, or your daughter, or your male servant, or your female servant, or your cattle, or the resident foreigner who is in your gates.'
EXEC add_BibleVerse @BibleId, 102020011, N'For in six days the Lord made the heavens and the earth and the sea and all that is in them, and he rested on the seventh day; therefore the Lord blessed the Sabbath day and set it apart as holy.'
EXEC add_BibleVerse @BibleId, 102020012, N'“Honor your father and your mother, that you may live a long time in the land the Lord your God is giving to you.'
EXEC add_BibleVerse @BibleId, 102020013, N'“You shall not murder.'
EXEC add_BibleVerse @BibleId, 102020014, N'“You shall not commit adultery.'
EXEC add_BibleVerse @BibleId, 102020015, N'“You shall not steal.'
EXEC add_BibleVerse @BibleId, 102020016, N'“You shall not give false testimony against your neighbor.'
EXEC add_BibleVerse @BibleId, 102020017, N'“You shall not covet your neighbor’s house. You shall not covet your neighbor’s wife, nor his male servant, nor his female servant, nor his ox, nor his donkey, nor anything that belongs to your neighbor.”'
EXEC add_BibleVerse @BibleId, 102020018, N'All the people were seeing the thundering and the lightning, and heard the sound of the horn, and saw the mountain smoking – and when the people saw it they trembled with fear and kept their distance.'
EXEC add_BibleVerse @BibleId, 102020019, N'They said to Moses, “You speak to us and we will listen, but do not let God speak with us, lest we die.”'
EXEC add_BibleVerse @BibleId, 102020020, N'Moses said to the people, “Do not fear, for God has come to test you, that the fear of him may be before you so that you do not sin.”'
EXEC add_BibleVerse @BibleId, 102020021, N'The people kept their distance, but Moses drew near the thick darkness where God was.'
EXEC add_BibleVerse @BibleId, 102020022, N'The Lord said to Moses: “Thus you will tell the Israelites: ‘You yourselves have seen that I have spoken with you from heaven.'
EXEC add_BibleVerse @BibleId, 102020023, N'You must not make gods of silver alongside me, nor make gods of gold for yourselves.'
EXEC add_BibleVerse @BibleId, 102020024, N'‘You must make for me an altar made of earth, and you will sacrifice on it your burnt offerings and your peace offerings, your sheep and your cattle. In every place where I cause my name to be honored I will come to you and I will bless you.'
EXEC add_BibleVerse @BibleId, 102020025, N'If you make me an altar of stone, you must not build it of stones shaped with tools, for if you use your tool on it you have defiled it.'
EXEC add_BibleVerse @BibleId, 102020026, N'And you must not go up by steps to my altar, so that your nakedness is not exposed.’'
EXEC add_BibleVerse @BibleId, 102021001, N'“These are the decisions that you will set before them:'
EXEC add_BibleVerse @BibleId, 102021002, N'“If you buy a Hebrew servant, he is to serve you for six years, but in the seventh year he will go out free without paying anything.'
EXEC add_BibleVerse @BibleId, 102021003, N'If he came in by himself he will go out by himself; if he had a wife when he came in, then his wife will go out with him.'
EXEC add_BibleVerse @BibleId, 102021004, N'If his master gave him a wife, and she bore sons or daughters, the wife and the children will belong to her master, and he will go out by himself.'
EXEC add_BibleVerse @BibleId, 102021005, N'But if the servant should declare, ‘I love my master, my wife, and my children; I will not go out free,’'
EXEC add_BibleVerse @BibleId, 102021006, N'then his master must bring him to the judges, and he will bring him to the door or the doorposts, and his master will pierce his ear with an awl, and he shall serve him forever.'
EXEC add_BibleVerse @BibleId, 102021007, N'“If a man sells his daughter as a female servant, she will not go out as the male servants do.'
EXEC add_BibleVerse @BibleId, 102021008, N'If she does not please her master, who has designated her for himself, then he must let her be redeemed. He has no right to sell her to a foreign nation, because he has dealt deceitfully with her.'
EXEC add_BibleVerse @BibleId, 102021009, N'If he designated her for his son, then he will deal with her according to the customary rights of daughters.'
EXEC add_BibleVerse @BibleId, 102021010, N'If he takes another wife, he must not diminish the first one’s food, her clothing, or her marital rights.'
EXEC add_BibleVerse @BibleId, 102021011, N'If he does not provide her with these three things, then she will go out free, without paying money.'
EXEC add_BibleVerse @BibleId, 102021012, N'“Whoever strikes someone so that he dies must surely be put to death.'
EXEC add_BibleVerse @BibleId, 102021013, N'But if he does not do it with premeditation, but it happens by accident, then I will appoint for you a place where he may flee.'
EXEC add_BibleVerse @BibleId, 102021014, N'But if a man willfully attacks his neighbor to kill him cunningly, you will take him even from my altar that he may die.'
EXEC add_BibleVerse @BibleId, 102021015, N'“Whoever strikes his father or his mother must surely be put to death.'
EXEC add_BibleVerse @BibleId, 102021016, N'“Whoever kidnaps someone and sells him, or is caught still holding him, must surely be put to death.'
EXEC add_BibleVerse @BibleId, 102021017, N'“Whoever treats his father or his mother disgracefully must surely be put to death.'
EXEC add_BibleVerse @BibleId, 102021018, N'“If men fight, and one strikes his neighbor with a stone or with his fist and he does not die, but must remain in bed,'
EXEC add_BibleVerse @BibleId, 102021019, N'and then if he gets up and walks about outside on his staff, then the one who struck him is innocent, except he must pay for the injured person’s loss of time and see to it that he is fully healed.'
EXEC add_BibleVerse @BibleId, 102021020, N'“If a man strikes his male servant or his female servant with a staff so that he or she dies as a result of the blow, he will surely be punished.'
EXEC add_BibleVerse @BibleId, 102021021, N'However, if the injured servant survives one or two days, the owner will not be punished, for he has suffered the loss.'
EXEC add_BibleVerse @BibleId, 102021022, N'“If men fight and hit a pregnant woman and her child is born prematurely, but there is no serious injury, he will surely be punished in accordance with what the woman’s husband demands of him, and he will pay what the court decides.'
EXEC add_BibleVerse @BibleId, 102021023, N'But if there is serious injury, then you will give a life for a life,'
EXEC add_BibleVerse @BibleId, 102021024, N'eye for eye, tooth for tooth, hand for hand, foot for foot,'
EXEC add_BibleVerse @BibleId, 102021025, N'burn for burn, wound for wound, bruise for bruise.'
EXEC add_BibleVerse @BibleId, 102021026, N'“If a man strikes the eye of his male servant or his female servant so that he destroys it, he will let the servant go free as compensation for the eye.'
EXEC add_BibleVerse @BibleId, 102021027, N'If he knocks out the tooth of his male servant or his female servant, he will let the servant go free as compensation for the tooth.'
EXEC add_BibleVerse @BibleId, 102021028, N'“If an ox gores a man or a woman so that either dies, then the ox must surely be stoned and its flesh must not be eaten, but the owner of the ox will be acquitted.'
EXEC add_BibleVerse @BibleId, 102021029, N'But if the ox had the habit of goring, and its owner was warned, and he did not take the necessary precautions, and then it killed a man or a woman, the ox must be stoned and the man must be put to death.'
EXEC add_BibleVerse @BibleId, 102021030, N'If a ransom is set for him, then he must pay the redemption for his life according to whatever amount was set for him.'
EXEC add_BibleVerse @BibleId, 102021031, N'If the ox gores a son or a daughter, the owner will be dealt with according to this rule.'
EXEC add_BibleVerse @BibleId, 102021032, N'If the ox gores a male servant or a female servant, the owner must pay thirty shekels of silver, and the ox must be stoned.'
EXEC add_BibleVerse @BibleId, 102021033, N'“If a man opens a pit or if a man digs a pit and does not cover it, and an ox or a donkey falls into it,'
EXEC add_BibleVerse @BibleId, 102021034, N'the owner of the pit must repay the loss. He must give money to its owner, and the dead animal will become his.'
EXEC add_BibleVerse @BibleId, 102021035, N'If the ox of one man injures the ox of his neighbor so that it dies, then they will sell the live ox and divide its proceeds, and they will also divide the dead ox.'
EXEC add_BibleVerse @BibleId, 102021036, N'Or if it is known that the ox had the habit of goring, and its owner did not take the necessary precautions, he must surely pay ox for ox, and the dead animal will become his.'
EXEC add_BibleVerse @BibleId, 102022001, N'“If a man steals an ox or a sheep and kills it or sells it, he must pay back five head of cattle for the ox, and four sheep for the one sheep.'
EXEC add_BibleVerse @BibleId, 102022002, N'“If a thief is caught breaking in and is struck so that he dies, there will be no blood guilt for him.'
EXEC add_BibleVerse @BibleId, 102022003, N'If the sun has risen on him, then there is blood guilt for him. A thief must surely make full restitution; if he has nothing, then he will be sold for his theft.'
EXEC add_BibleVerse @BibleId, 102022004, N'If the stolen item should in fact be found alive in his possession, whether it be an ox or a donkey or a sheep, he must pay back double.'
EXEC add_BibleVerse @BibleId, 102022005, N'“If a man grazes his livestock in a field or a vineyard, and he lets the livestock loose and they graze in the field of another man, he must make restitution from the best of his own field and the best of his own vineyard.'
EXEC add_BibleVerse @BibleId, 102022006, N'“If a fire breaks out and spreads to thorn bushes, so that stacked grain or standing grain or the whole field is consumed, the one who started the fire must surely make restitution.'
EXEC add_BibleVerse @BibleId, 102022007, N'“If a man gives his neighbor money or articles for safekeeping, and it is stolen from the man’s house, if the thief is caught, he must repay double.'
EXEC add_BibleVerse @BibleId, 102022008, N'If the thief is not caught, then the owner of the house will be brought before the judges to see whether he has laid his hand on his neighbor’s goods.'
EXEC add_BibleVerse @BibleId, 102022009, N'In all cases of illegal possessions, whether for an ox, a donkey, a sheep, a garment, or any kind of lost item, about which someone says ‘This belongs to me,’ the matter of the two of them will come before the judges, and the one whom the judges declare guilty must repay double to his neighbor.'
EXEC add_BibleVerse @BibleId, 102022010, N'If a man gives his neighbor a donkey or an ox or a sheep or any beast to keep, and it dies or is hurt or is carried away without anyone seeing it,'
EXEC add_BibleVerse @BibleId, 102022011, N'then there will be an oath to the Lord between the two of them, that he has not laid his hand on his neighbor’s goods, and its owner will accept this, and he will not have to pay.'
EXEC add_BibleVerse @BibleId, 102022012, N'But if it was stolen from him, he will pay its owner.'
EXEC add_BibleVerse @BibleId, 102022013, N'If it is torn in pieces, then he will bring it for evidence, and he will not have to pay for what was torn.'
EXEC add_BibleVerse @BibleId, 102022014, N'“If a man borrows an animal from his neighbor, and it is hurt or dies when its owner was not with it, the man who borrowed it will surely pay.'
EXEC add_BibleVerse @BibleId, 102022015, N'If its owner was with it, he will not have to pay; if it was hired, what was paid for the hire covers it.'
EXEC add_BibleVerse @BibleId, 102022016, N'“If a man seduces a virgin who is not engaged and has sexual relations with her, he must surely endow her to be his wife.'
EXEC add_BibleVerse @BibleId, 102022017, N'If her father refuses to give her to him, he must pay money for the bride price of virgins.'
EXEC add_BibleVerse @BibleId, 102022018, N'“You must not allow a sorceress to live.'
EXEC add_BibleVerse @BibleId, 102022019, N'“Whoever has sexual relations with a beast must surely be put to death.'
EXEC add_BibleVerse @BibleId, 102022020, N'“Whoever sacrifices to a god other than the Lord alone must be utterly destroyed.'
EXEC add_BibleVerse @BibleId, 102022021, N'“You must not wrong a foreigner nor oppress him, for you were foreigners in the land of Egypt.'
EXEC add_BibleVerse @BibleId, 102022022, N'“You must not afflict any widow or orphan.'
EXEC add_BibleVerse @BibleId, 102022023, N'If you afflict them in any way and they cry to me, I will surely hear their cry,'
EXEC add_BibleVerse @BibleId, 102022024, N'and my anger will burn and I will kill you with the sword, and your wives will be widows and your children will be fatherless.'
EXEC add_BibleVerse @BibleId, 102022025, N'“If you lend money to any of my people who are needy among you, do not be like a moneylender to him; do not charge him interest.'
EXEC add_BibleVerse @BibleId, 102022026, N'If you do take the garment of your neighbor in pledge, you must return it to him by the time the sun goes down,'
EXEC add_BibleVerse @BibleId, 102022027, N'for it is his only covering – it is his garment for his body. What else can he sleep in? And when he cries out to me, I will hear, for I am gracious.'
EXEC add_BibleVerse @BibleId, 102022028, N'“You must not blaspheme God or curse the ruler of your people.'
EXEC add_BibleVerse @BibleId, 102022029, N'“Do not hold back offerings from your granaries or your vats. You must give me the firstborn of your sons.'
EXEC add_BibleVerse @BibleId, 102022030, N'You must also do this for your oxen and for your sheep; seven days they may remain with their mothers, but give them to me on the eighth day.'
EXEC add_BibleVerse @BibleId, 102022031, N'“You will be holy people to me; you must not eat any meat torn by animals in the field. You must throw it to the dogs.'
EXEC add_BibleVerse @BibleId, 102023001, N'“You must not give a false report. Do not make common cause with the wicked to be a malicious witness.'
EXEC add_BibleVerse @BibleId, 102023002, N'“You must not follow a crowd in doing evil things; in a lawsuit you must not offer testimony that agrees with a crowd so as to pervert justice,'
EXEC add_BibleVerse @BibleId, 102023003, N'and you must not show partiality to a poor man in his lawsuit.'
EXEC add_BibleVerse @BibleId, 102023004, N'“If you encounter your enemy’s ox or donkey wandering off, you must by all means return it to him.'
EXEC add_BibleVerse @BibleId, 102023005, N'If you see the donkey of someone who hates you fallen under its load, you must not ignore him, but be sure to help him with it.'
EXEC add_BibleVerse @BibleId, 102023006, N'“You must not turn away justice for your poor people in their lawsuits.'
EXEC add_BibleVerse @BibleId, 102023007, N'Keep your distance from a false charge – do not kill the innocent and the righteous, for I will not justify the wicked.'
EXEC add_BibleVerse @BibleId, 102023008, N'“You must not accept a bribe, for a bribe blinds those who see and subverts the words of the righteous.'
EXEC add_BibleVerse @BibleId, 102023009, N'“You must not oppress a foreigner, since you know the life of a foreigner, for you were foreigners in the land of Egypt.'
EXEC add_BibleVerse @BibleId, 102023010, N'“For six years you are to sow your land and gather in its produce.'
EXEC add_BibleVerse @BibleId, 102023011, N'But in the seventh year you must let it lie fallow and leave it alone so that the poor of your people may eat, and what they leave any animal in the field may eat; you must do likewise with your vineyard and your olive grove.'
EXEC add_BibleVerse @BibleId, 102023012, N'For six days you are to do your work, but on the seventh day you must cease, in order that your ox and your donkey may rest and that your female servant’s son and any hired help may refresh themselves.'
EXEC add_BibleVerse @BibleId, 102023013, N'“Pay attention to do everything I have told you, and do not even mention the names of other gods – do not let them be heard on your lips.'
EXEC add_BibleVerse @BibleId, 102023014, N'“Three times in the year you must make a pilgrim feast to me.'
EXEC add_BibleVerse @BibleId, 102023015, N'You are to observe the Feast of Unleavened Bread; seven days you must eat bread made without yeast, as I commanded you, at the appointed time of the month of Abib, for at that time you came out of Egypt. No one may appear before me empty-handed.'
EXEC add_BibleVerse @BibleId, 102023016, N'“You are also to observe the Feast of Harvest, the firstfruits of your labors that you have sown in the field, and the Feast of Ingathering at the end of the year when you have gathered in your harvest out of the field.'
EXEC add_BibleVerse @BibleId, 102023017, N'At three times in the year all your males will appear before the Lord God.'
EXEC add_BibleVerse @BibleId, 102023018, N'“You must not offer the blood of my sacrifice with bread containing yeast; the fat of my festal sacrifice must not remain until morning.'
EXEC add_BibleVerse @BibleId, 102023019, N'The first of the firstfruits of your soil you must bring to the house of the Lord your God. “You must not cook a young goat in its mother’s milk.'
EXEC add_BibleVerse @BibleId, 102023020, N'“I am going to send an angel before you to protect you as you journey and to bring you into the place that I have prepared.'
EXEC add_BibleVerse @BibleId, 102023021, N'Take heed because of him, and obey his voice; do not rebel against him, for he will not pardon your transgressions, for my name is in him.'
EXEC add_BibleVerse @BibleId, 102023022, N'But if you diligently obey him and do all that I command, then I will be an enemy to your enemies, and I will be an adversary to your adversaries.'
EXEC add_BibleVerse @BibleId, 102023023, N'For my angel will go before you and bring you to the Amorites, the Hittites, the Perizzites, the Canaanites, the Hivites, and the Jebusites, and I will destroy them completely.'
EXEC add_BibleVerse @BibleId, 102023024, N'“You must not bow down to their gods; you must not serve them or do according to their practices. Instead you must completely overthrow them and smash their standing stones to pieces.'
EXEC add_BibleVerse @BibleId, 102023025, N'You must serve the Lord your God, and he will bless your bread and your water, and I will remove sickness from your midst.'
EXEC add_BibleVerse @BibleId, 102023026, N'No woman will miscarry her young or be barren in your land. I will fulfill the number of your days.'
EXEC add_BibleVerse @BibleId, 102023027, N'“I will send my terror before you, and I will destroy all the people whom you encounter; I will make all your enemies turn their backs to you.'
EXEC add_BibleVerse @BibleId, 102023028, N'I will send hornets before you that will drive out the Hivite, the Canaanite, and the Hittite before you.'
EXEC add_BibleVerse @BibleId, 102023029, N'I will not drive them out before you in one year, lest the land become desolate and the wild animals multiply against you.'
EXEC add_BibleVerse @BibleId, 102023030, N'Little by little I will drive them out before you, until you become fruitful and inherit the land.'
EXEC add_BibleVerse @BibleId, 102023031, N'I will set your boundaries from the Red Sea to the sea of the Philistines, and from the desert to the River, for I will deliver the inhabitants of the land into your hand, and you will drive them out before you.'
EXEC add_BibleVerse @BibleId, 102023032, N'“You must make no covenant with them or with their gods.'
EXEC add_BibleVerse @BibleId, 102023033, N'They must not live in your land, lest they make you sin against me, for if you serve their gods, it will surely be a snare to you.”'
EXEC add_BibleVerse @BibleId, 102024001, N'But to Moses the Lord said, “Come up to the Lord, you and Aaron, Nadab and Abihu, and seventy of the elders of Israel, and worship from a distance.'
EXEC add_BibleVerse @BibleId, 102024002, N'Moses alone may come near the Lord, but the others must not come near, nor may the people go up with him.”'
EXEC add_BibleVerse @BibleId, 102024003, N'Moses came and told the people all the Lord’s words and all the decisions. All the people answered together, “We are willing to do all the words that the Lord has said,”'
EXEC add_BibleVerse @BibleId, 102024004, N'and Moses wrote down all the words of the Lord. Early in the morning he built an altar at the foot of the mountain and arranged twelve standing stones – according to the twelve tribes of Israel.'
EXEC add_BibleVerse @BibleId, 102024005, N'He sent young Israelite men, and they offered burnt offerings and sacrificed young bulls for peace offerings to the Lord.'
EXEC add_BibleVerse @BibleId, 102024006, N'Moses took half of the blood and put it in bowls, and half of the blood he splashed on the altar.'
EXEC add_BibleVerse @BibleId, 102024007, N'He took the Book of the Covenant and read it aloud to the people, and they said, “We are willing to do and obey all that the Lord has spoken.”'
EXEC add_BibleVerse @BibleId, 102024008, N'So Moses took the blood and splashed it on the people and said, “This is the blood of the covenant that the Lord has made with you in accordance with all these words.”'
EXEC add_BibleVerse @BibleId, 102024009, N'Moses and Aaron, Nadab and Abihu, and the seventy elders of Israel went up,'
EXEC add_BibleVerse @BibleId, 102024010, N'and they saw the God of Israel. Under his feet there was something like a pavement made of sapphire, clear like the sky itself.'
EXEC add_BibleVerse @BibleId, 102024011, N'But he did not lay a hand on the leaders of the Israelites, so they saw God, and they ate and they drank.'
EXEC add_BibleVerse @BibleId, 102024012, N'The Lord said to Moses, “Come up to me to the mountain and remain there, and I will give you the stone tablets with the law and the commandments that I have written, so that you may teach them.”'
EXEC add_BibleVerse @BibleId, 102024013, N'So Moses set out with Joshua his attendant, and Moses went up the mountain of God.'
EXEC add_BibleVerse @BibleId, 102024014, N'He told the elders, “Wait for us in this place until we return to you. Here are Aaron and Hur with you. Whoever has any matters of dispute can approach them.”'
EXEC add_BibleVerse @BibleId, 102024015, N'Moses went up the mountain, and the cloud covered the mountain.'
EXEC add_BibleVerse @BibleId, 102024016, N'The glory of the Lord resided on Mount Sinai, and the cloud covered it for six days. On the seventh day he called to Moses from within the cloud.'
EXEC add_BibleVerse @BibleId, 102024017, N'Now the appearance of the glory of the Lord was like a devouring fire on the top of the mountain in plain view of the people.'
EXEC add_BibleVerse @BibleId, 102024018, N'Moses went into the cloud when he went up the mountain, and Moses was on the mountain forty days and forty nights.'
EXEC add_BibleVerse @BibleId, 102025001, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 102025002, N'“Tell the Israelites to take an offering for me; from every person motivated by a willing heart you are to receive my offering.'
EXEC add_BibleVerse @BibleId, 102025003, N'This is the offering you are to accept from them: gold, silver, bronze,'
EXEC add_BibleVerse @BibleId, 102025004, N'blue, purple, scarlet, fine linen, goat’s hair,'
EXEC add_BibleVerse @BibleId, 102025005, N'ram skins dyed red, fine leather, acacia wood,'
EXEC add_BibleVerse @BibleId, 102025006, N'oil for the light, spices for the anointing oil and for fragrant incense,'
EXEC add_BibleVerse @BibleId, 102025007, N'onyx stones, and other gems to be set in the ephod and in the breastpiece.'
EXEC add_BibleVerse @BibleId, 102025008, N'Let them make for me a sanctuary, so that I may live among them.'
EXEC add_BibleVerse @BibleId, 102025009, N'According to all that I am showing you – the pattern of the tabernacle and the pattern of all its furnishings – you must make it exactly so.'
EXEC add_BibleVerse @BibleId, 102025010, N'“They are to make an ark of acacia wood – its length is to be three feet nine inches, its width two feet three inches, and its height two feet three inches.'
EXEC add_BibleVerse @BibleId, 102025011, N'You are to overlay it with pure gold – both inside and outside you must overlay it, and you are to make a surrounding border of gold over it.'
EXEC add_BibleVerse @BibleId, 102025012, N'You are to cast four gold rings for it and put them on its four feet, with two rings on one side and two rings on the other side.'
EXEC add_BibleVerse @BibleId, 102025013, N'You are to make poles of acacia wood, overlay them with gold,'
EXEC add_BibleVerse @BibleId, 102025014, N'and put the poles into the rings at the sides of the ark in order to carry the ark with them.'
EXEC add_BibleVerse @BibleId, 102025015, N'The poles must remain in the rings of the ark; they must not be removed from it.'
EXEC add_BibleVerse @BibleId, 102025016, N'You are to put into the ark the testimony that I will give to you.'
EXEC add_BibleVerse @BibleId, 102025017, N'“You are to make an atonement lid of pure gold; its length is to be three feet nine inches, and its width is to be two feet three inches.'
EXEC add_BibleVerse @BibleId, 102025018, N'You are to make two cherubim of gold; you are to make them of hammered metal on the two ends of the atonement lid.'
EXEC add_BibleVerse @BibleId, 102025019, N'Make one cherub on one end and one cherub on the other end; from the atonement lid you are to make the cherubim on the two ends.'
EXEC add_BibleVerse @BibleId, 102025020, N'The cherubim are to be spreading their wings upward, overshadowing the atonement lid with their wings, and the cherubim are to face each other, looking toward the atonement lid.'
EXEC add_BibleVerse @BibleId, 102025021, N'You are to put the atonement lid on top of the ark, and in the ark you are to put the testimony I am giving you.'
EXEC add_BibleVerse @BibleId, 102025022, N'I will meet with you there, and from above the atonement lid, from between the two cherubim that are over the ark of the testimony, I will speak with you about all that I will command you for the Israelites.'
EXEC add_BibleVerse @BibleId, 102025023, N'“You are to make a table of acacia wood; its length is to be three feet, its width one foot six inches, and its height two feet three inches.'
EXEC add_BibleVerse @BibleId, 102025024, N'You are to overlay it with pure gold, and you are to make a surrounding border of gold for it.'
EXEC add_BibleVerse @BibleId, 102025025, N'You are to make a surrounding frame for it about three inches broad, and you are to make a surrounding border of gold for its frame.'
EXEC add_BibleVerse @BibleId, 102025026, N'You are to make four rings of gold for it and attach the rings at the four corners where its four legs are.'
EXEC add_BibleVerse @BibleId, 102025027, N'The rings are to be close to the frame to provide places for the poles to carry the table.'
EXEC add_BibleVerse @BibleId, 102025028, N'You are to make the poles of acacia wood and overlay them with gold, so that the table may be carried with them.'
EXEC add_BibleVerse @BibleId, 102025029, N'You are to make its plates, its ladles, its pitchers, and its bowls, to be used in pouring out offerings; you are to make them of pure gold.'
EXEC add_BibleVerse @BibleId, 102025030, N'You are to set the Bread of the Presence on the table before me continually.'
EXEC add_BibleVerse @BibleId, 102025031, N'“You are to make a lampstand of pure gold. The lampstand is to be made of hammered metal; its base and its shaft, its cups, its buds, and its blossoms are to be from the same piece.'
EXEC add_BibleVerse @BibleId, 102025032, N'Six branches are to extend from the sides of the lampstand, three branches of the lampstand from one side of it and three branches of the lampstand from the other side of it.'
EXEC add_BibleVerse @BibleId, 102025033, N'Three cups shaped like almond flowers with buds and blossoms are to be on one branch, and three cups shaped like almond flowers with buds and blossoms are to be on the next branch, and the same for the six branches extending from the lampstand.'
EXEC add_BibleVerse @BibleId, 102025034, N'On the lampstand there are to be four cups shaped like almond flowers with buds and blossoms,'
EXEC add_BibleVerse @BibleId, 102025035, N'with a bud under the first two branches from it, and a bud under the next two branches from it, and a bud under the third two branches from it, according to the six branches that extend from the lampstand.'
EXEC add_BibleVerse @BibleId, 102025036, N'Their buds and their branches will be one piece, all of it one hammered piece of pure gold.'
EXEC add_BibleVerse @BibleId, 102025037, N'“You are to make its seven lamps, and then set its lamps up on it, so that it will give light to the area in front of it.'
EXEC add_BibleVerse @BibleId, 102025038, N'Its trimmers and its trays are to be of pure gold.'
EXEC add_BibleVerse @BibleId, 102025039, N'About seventy-five pounds of pure gold is to be used for it and for all these utensils.'
EXEC add_BibleVerse @BibleId, 102025040, N'Now be sure to make them according to the pattern you were shown on the mountain.'
EXEC add_BibleVerse @BibleId, 102026001, N'“The tabernacle itself you are to make with ten curtains of fine twisted linen and blue and purple and scarlet; you are to make them with cherubim that are the work of an artistic designer.'
EXEC add_BibleVerse @BibleId, 102026002, N'The length of each curtain is to be forty-two feet, and the width of each curtain is to be six feet – the same size for each of the curtains.'
EXEC add_BibleVerse @BibleId, 102026003, N'Five curtains are to be joined, one to another, and the other five curtains are to be joined, one to another.'
EXEC add_BibleVerse @BibleId, 102026004, N'You are to make loops of blue material along the edge of the end curtain in one set, and in the same way you are to make loops in the outer edge of the end curtain in the second set.'
EXEC add_BibleVerse @BibleId, 102026005, N'You are to make fifty loops on the one curtain, and you are to make fifty loops on the end curtain which is on the second set, so that the loops are opposite one to another.'
EXEC add_BibleVerse @BibleId, 102026006, N'You are to make fifty gold clasps and join the curtains together with the clasps, so that the tabernacle is a unit.'
EXEC add_BibleVerse @BibleId, 102026007, N'“You are to make curtains of goats’ hair for a tent over the tabernacle; you are to make eleven curtains.'
EXEC add_BibleVerse @BibleId, 102026008, N'The length of each curtain is to be forty-five feet, and the width of each curtain is to be six feet – the same size for the eleven curtains.'
EXEC add_BibleVerse @BibleId, 102026009, N'You are to join five curtains by themselves and six curtains by themselves. You are to double over the sixth curtain at the front of the tent.'
EXEC add_BibleVerse @BibleId, 102026010, N'You are to make fifty loops along the edge of the end curtain in one set and fifty loops along the edge of the curtain that joins the second set.'
EXEC add_BibleVerse @BibleId, 102026011, N'You are to make fifty bronze clasps and put the clasps into the loops and join the tent together so that it is a unit.'
EXEC add_BibleVerse @BibleId, 102026012, N'Now the part that remains of the curtains of the tent – the half curtain that remains will hang over at the back of the tabernacle.'
EXEC add_BibleVerse @BibleId, 102026013, N'The foot and a half on the one side and the foot and a half on the other side of what remains in the length of the curtains of the tent will hang over the sides of the tabernacle, on one side and the other side, to cover it.'
EXEC add_BibleVerse @BibleId, 102026014, N'“You are to make a covering for the tent out of ram skins dyed red and over that a covering of fine leather.'
EXEC add_BibleVerse @BibleId, 102026015, N'“You are to make the frames for the tabernacle out of acacia wood as uprights.'
EXEC add_BibleVerse @BibleId, 102026016, N'Each frame is to be fifteen feet long, and each frame is to be two feet three inches wide,'
EXEC add_BibleVerse @BibleId, 102026017, N'with two projections per frame parallel one to another. You are to make all the frames of the tabernacle in this way.'
EXEC add_BibleVerse @BibleId, 102026018, N'So you are to make the frames for the tabernacle: twenty frames for the south side,'
EXEC add_BibleVerse @BibleId, 102026019, N'and you are to make forty silver bases to go under the twenty frames – two bases under the first frame for its two projections, and likewise two bases under the next frame for its two projections;'
EXEC add_BibleVerse @BibleId, 102026020, N'and for the second side of the tabernacle, the north side, twenty frames,'
EXEC add_BibleVerse @BibleId, 102026021, N'and their forty silver bases, two bases under the first frame, and two bases under the next frame.'
EXEC add_BibleVerse @BibleId, 102026022, N'And for the back of the tabernacle on the west you will make six frames.'
EXEC add_BibleVerse @BibleId, 102026023, N'You are to make two frames for the corners of the tabernacle on the back.'
EXEC add_BibleVerse @BibleId, 102026024, N'At the two corners they must be doubled at the lower end and finished together at the top in one ring. So it will be for both.'
EXEC add_BibleVerse @BibleId, 102026025, N'So there are to be eight frames and their silver bases, sixteen bases, two bases under the first frame, and two bases under the next frame.'
EXEC add_BibleVerse @BibleId, 102026026, N'“You are to make bars of acacia wood, five for the frames on one side of the tabernacle,'
EXEC add_BibleVerse @BibleId, 102026027, N'and five bars for the frames on the second side of the tabernacle, and five bars for the frames on the back of the tabernacle on the west.'
EXEC add_BibleVerse @BibleId, 102026028, N'The middle bar in the center of the frames will reach from end to end.'
EXEC add_BibleVerse @BibleId, 102026029, N'You are to overlay the frames with gold and make their rings of gold to provide places for the bars, and you are to overlay the bars with gold.'
EXEC add_BibleVerse @BibleId, 102026030, N'You are to set up the tabernacle according to the plan that you were shown on the mountain.'
EXEC add_BibleVerse @BibleId, 102026031, N'“You are to make a special curtain of blue, purple, and scarlet yarn and fine twisted linen; it is to be made with cherubim, the work of an artistic designer.'
EXEC add_BibleVerse @BibleId, 102026032, N'You are to hang it with gold hooks on four posts of acacia wood overlaid with gold, set in four silver bases.'
EXEC add_BibleVerse @BibleId, 102026033, N'You are to hang this curtain under the clasps and bring the ark of the testimony in there behind the curtain. The curtain will make a division for you between the Holy Place and the Most Holy Place.'
EXEC add_BibleVerse @BibleId, 102026034, N'You are to put the atonement lid on the ark of the testimony in the Most Holy Place.'
EXEC add_BibleVerse @BibleId, 102026035, N'You are to put the table outside the curtain and the lampstand on the south side of the tabernacle, opposite the table, and you are to place the table on the north side.'
EXEC add_BibleVerse @BibleId, 102026036, N'“You are to make a hanging for the entrance of the tent of blue, purple, and scarlet yarn and fine twined linen, the work of an embroiderer.'
EXEC add_BibleVerse @BibleId, 102026037, N'You are to make for the hanging five posts of acacia wood and overlay them with gold, and their hooks will be gold, and you are to cast five bronze bases for them.'
EXEC add_BibleVerse @BibleId, 102027001, N'“You are to make the altar of acacia wood, seven feet six inches long, and seven feet six inches wide; the altar is to be square, and its height is to be four feet six inches.'
EXEC add_BibleVerse @BibleId, 102027002, N'You are to make its four horns on its four corners; its horns will be part of it, and you are to overlay it with bronze.'
EXEC add_BibleVerse @BibleId, 102027003, N'You are to make its pots for the ashes, its shovels, its tossing bowls, its meat hooks, and its fire pans – you are to make all its utensils of bronze.'
EXEC add_BibleVerse @BibleId, 102027004, N'You are to make a grating for it, a network of bronze, and you are to make on the network four bronze rings on its four corners.'
EXEC add_BibleVerse @BibleId, 102027005, N'You are to put it under the ledge of the altar below, so that the network will come halfway up the altar.'
EXEC add_BibleVerse @BibleId, 102027006, N'You are to make poles for the altar, poles of acacia wood, and you are to overlay them with bronze.'
EXEC add_BibleVerse @BibleId, 102027007, N'The poles are to be put into the rings so that the poles will be on two sides of the altar when carrying it.'
EXEC add_BibleVerse @BibleId, 102027008, N'You are to make the altar hollow, out of boards. Just as it was shown you on the mountain, so they must make it.'
EXEC add_BibleVerse @BibleId, 102027009, N'“You are to make the courtyard of the tabernacle. For the south side there are to be hangings for the courtyard of fine twisted linen, one hundred fifty feet long for one side,'
EXEC add_BibleVerse @BibleId, 102027010, N'with twenty posts and their twenty bronze bases, with the hooks of the posts and their bands of silver.'
EXEC add_BibleVerse @BibleId, 102027011, N'Likewise for its length on the north side, there are to be hangings for one hundred fifty feet, with twenty posts and their twenty bronze bases, with silver hooks and bands on the posts.'
EXEC add_BibleVerse @BibleId, 102027012, N'The width of the court on the west side is to be seventy-five feet with hangings, with their ten posts and their ten bases.'
EXEC add_BibleVerse @BibleId, 102027013, N'The width of the court on the east side, toward the sunrise, is to be seventy-five feet.'
EXEC add_BibleVerse @BibleId, 102027014, N'The hangings on one side of the gate are to be twenty-two and a half feet long, with their three posts and their three bases.'
EXEC add_BibleVerse @BibleId, 102027015, N'On the second side there are to be hangings twenty-two and a half feet long, with their three posts and their three bases.'
EXEC add_BibleVerse @BibleId, 102027016, N'For the gate of the courtyard there is to be a curtain of thirty feet, of blue, purple, and scarlet yarn and fine twined linen, the work of an embroiderer, with four posts and their four bases.'
EXEC add_BibleVerse @BibleId, 102027017, N'All the posts around the courtyard are to have silver bands; their hooks are to be silver, and their bases bronze.'
EXEC add_BibleVerse @BibleId, 102027018, N'The length of the courtyard is to be one hundred fifty feet and the width seventy-five feet, and the height of the fine twisted linen hangings is to be seven and a half feet, with their bronze bases.'
EXEC add_BibleVerse @BibleId, 102027019, N'All the utensils of the tabernacle used in all its service, all its tent pegs, and all the tent pegs of the courtyard are to be made of bronze.'
EXEC add_BibleVerse @BibleId, 102027020, N'“You are to command the Israelites that they bring to you pure oil of pressed olives for the light, so that the lamps will burn regularly.'
EXEC add_BibleVerse @BibleId, 102027021, N'In the tent of meeting outside the curtain that is before the testimony, Aaron and his sons are to arrange it from evening to morning before the Lord. This is to be a lasting ordinance among the Israelites for generations to come.'
EXEC add_BibleVerse @BibleId, 102028001, N'“And you, bring near to you your brother Aaron and his sons with him from among the Israelites, so that they may minister as my priests – Aaron, Nadab and Abihu, Eleazar and Ithamar, Aaron’s sons.'
EXEC add_BibleVerse @BibleId, 102028002, N'You must make holy garments for your brother Aaron, for glory and for beauty.'
EXEC add_BibleVerse @BibleId, 102028003, N'You are to speak to all who are specially skilled, whom I have filled with the spirit of wisdom, so that they may make Aaron’s garments to set him apart to minister as my priest.'
EXEC add_BibleVerse @BibleId, 102028004, N'Now these are the garments that they are to make: a breastpiece, an ephod, a robe, a fitted tunic, a turban, and a sash. They are to make holy garments for your brother Aaron and for his sons, that they may minister as my priests.'
EXEC add_BibleVerse @BibleId, 102028005, N'The artisans are to use the gold, blue, purple, scarlet, and fine linen.'
EXEC add_BibleVerse @BibleId, 102028006, N'“They are to make the ephod of gold, blue, purple, scarlet, and fine twisted linen, the work of an artistic designer.'
EXEC add_BibleVerse @BibleId, 102028007, N'It is to have two shoulder pieces attached to two of its corners, so it can be joined together.'
EXEC add_BibleVerse @BibleId, 102028008, N'The artistically woven waistband of the ephod that is on it is to be like it, of one piece with the ephod, of gold, blue, purple, scarlet, and fine twisted linen.'
EXEC add_BibleVerse @BibleId, 102028009, N'“You are to take two onyx stones and engrave on them the names of the sons of Israel,'
EXEC add_BibleVerse @BibleId, 102028010, N'six of their names on one stone, and the six remaining names on the second stone, according to the order of their birth.'
EXEC add_BibleVerse @BibleId, 102028011, N'You are to engrave the two stones with the names of the sons of Israel with the work of an engraver in stone, like the engravings of a seal; you are to have them set in gold filigree settings.'
EXEC add_BibleVerse @BibleId, 102028012, N'You are to put the two stones on the shoulders of the ephod, stones of memorial for the sons of Israel, and Aaron will bear their names before the Lord on his two shoulders for a memorial.'
EXEC add_BibleVerse @BibleId, 102028013, N'You are to make filigree settings of gold'
EXEC add_BibleVerse @BibleId, 102028014, N'and two braided chains of pure gold, like a cord, and attach the chains to the settings.'
EXEC add_BibleVerse @BibleId, 102028015, N'“You are to make a breastpiece for use in making decisions, the work of an artistic designer; you are to make it in the same fashion as the ephod; you are to make it of gold, blue, purple, scarlet, and fine twisted linen.'
EXEC add_BibleVerse @BibleId, 102028016, N'It is to be square when doubled, nine inches long and nine inches wide.'
EXEC add_BibleVerse @BibleId, 102028017, N'You are to set in it a setting for stones, four rows of stones, a row with a ruby, a topaz, and a beryl – the first row;'
EXEC add_BibleVerse @BibleId, 102028018, N'and the second row, a turquoise, a sapphire, and an emerald;'
EXEC add_BibleVerse @BibleId, 102028019, N'and the third row, a jacinth, an agate, and an amethyst;'
EXEC add_BibleVerse @BibleId, 102028020, N'and the fourth row, a chrysolite, an onyx, and a jasper. They are to be enclosed in gold in their filigree settings.'
EXEC add_BibleVerse @BibleId, 102028021, N'The stones are to be for the names of the sons of Israel, twelve, according to the number of their names. Each name according to the twelve tribes is to be like the engravings of a seal.'
EXEC add_BibleVerse @BibleId, 102028022, N'“You are to make for the breastpiece braided chains like cords of pure gold,'
EXEC add_BibleVerse @BibleId, 102028023, N'and you are to make for the breastpiece two gold rings and attach the two rings to the upper two ends of the breastpiece.'
EXEC add_BibleVerse @BibleId, 102028024, N'You are to attach the two gold chains to the two rings at the ends of the breastpiece;'
EXEC add_BibleVerse @BibleId, 102028025, N'the other two ends of the two chains you will attach to the two settings and then attach them to the shoulder pieces of the ephod at the front of it.'
EXEC add_BibleVerse @BibleId, 102028026, N'You are to make two rings of gold and put them on the other two ends of the breastpiece, on its edge that is on the inner side of the ephod.'
EXEC add_BibleVerse @BibleId, 102028027, N'You are to make two more gold rings and attach them to the bottom of the two shoulder pieces on the front of the ephod, close to the juncture above the waistband of the ephod.'
EXEC add_BibleVerse @BibleId, 102028028, N'They are to tie the breastpiece by its rings to the rings of the ephod by blue cord, so that it may be above the waistband of the ephod, and so that the breastpiece will not be loose from the ephod.'
EXEC add_BibleVerse @BibleId, 102028029, N'Aaron will bear the names of the sons of Israel in the breastpiece of decision over his heart when he goes into the holy place, for a memorial before the Lord continually.'
EXEC add_BibleVerse @BibleId, 102028030, N'“You are to put the Urim and the Thummim into the breastpiece of decision; and they are to be over Aaron’s heart when he goes in before the Lord. Aaron is to bear the decisions of the Israelites over his heart before the Lord continually.'
EXEC add_BibleVerse @BibleId, 102028031, N'“You are to make the robe of the ephod completely blue.'
EXEC add_BibleVerse @BibleId, 102028032, N'There is to be an opening in its top in the center of it, with an edge all around the opening, the work of a weaver, like the opening of a collar, so that it cannot be torn.'
EXEC add_BibleVerse @BibleId, 102028033, N'You are to make pomegranates of blue, purple, and scarlet all around its hem and bells of gold between them all around.'
EXEC add_BibleVerse @BibleId, 102028034, N'The pattern is to be a gold bell and a pomegranate, a gold bell and a pomegranate, all around the hem of the robe.'
EXEC add_BibleVerse @BibleId, 102028035, N'The robe is to be on Aaron as he ministers, and his sound will be heard when he enters the Holy Place before the Lord and when he leaves, so that he does not die.'
EXEC add_BibleVerse @BibleId, 102028036, N'“You are to make a plate of pure gold and engrave on it the way a seal is engraved: “Holiness to the Lord.”'
EXEC add_BibleVerse @BibleId, 102028037, N'You are to attach to it a blue cord so that it will be on the turban; it is to be on the front of the turban,'
EXEC add_BibleVerse @BibleId, 102028038, N'It will be on Aaron’s forehead, and Aaron will bear the iniquity of the holy things, which the Israelites are to sanctify by all their holy gifts; it will always be on his forehead, for their acceptance before the Lord.'
EXEC add_BibleVerse @BibleId, 102028039, N'You are to weave the tunic of fine linen and make the turban of fine linen, and make the sash the work of an embroiderer.'
EXEC add_BibleVerse @BibleId, 102028040, N'“For Aaron’s sons you are to make tunics, sashes, and headbands for glory and for beauty.'
EXEC add_BibleVerse @BibleId, 102028041, N'“You are to clothe them – your brother Aaron and his sons with him – and anoint them and ordain them and set them apart as holy, so that they may minister as my priests.'
EXEC add_BibleVerse @BibleId, 102028042, N'Make for them linen undergarments to cover their naked bodies; they must cover from the waist to the thighs.'
EXEC add_BibleVerse @BibleId, 102028043, N'These must be on Aaron and his sons when they enter to the tent of meeting, or when they approach the altar to minister in the Holy Place, so that they bear no iniquity and die. It is to be a perpetual ordinance for him and for his descendants after him.'
EXEC add_BibleVerse @BibleId, 102029001, N'“Now this is what you are to do for them to consecrate them so that they may minister as my priests. Take a young bull and two rams without blemish;'
EXEC add_BibleVerse @BibleId, 102029002, N'and bread made without yeast, and perforated cakes without yeast mixed with oil, and wafers without yeast spread with oil – you are to make them using fine wheat flour.'
EXEC add_BibleVerse @BibleId, 102029003, N'You are to put them in one basket and present them in the basket, along with the bull and the two rams.'
EXEC add_BibleVerse @BibleId, 102029004, N'“You are to present Aaron and his sons at the entrance of the tent of meeting. You are to wash them with water'
EXEC add_BibleVerse @BibleId, 102029005, N'and take the garments and clothe Aaron with the tunic, the robe of the ephod, the ephod, and the breastpiece; you are to fasten the ephod on him by using the skillfully woven waistband.'
EXEC add_BibleVerse @BibleId, 102029006, N'You are to put the turban on his head and put the holy diadem on the turban.'
EXEC add_BibleVerse @BibleId, 102029007, N'You are to take the anointing oil and pour it on his head and anoint him.'
EXEC add_BibleVerse @BibleId, 102029008, N'You are to present his sons and clothe them with tunics'
EXEC add_BibleVerse @BibleId, 102029009, N'and wrap the sashes around Aaron and his sons and put headbands on them, and so the ministry of priesthood will belong to them by a perpetual ordinance. Thus you are to consecrate Aaron and his sons.'
EXEC add_BibleVerse @BibleId, 102029010, N'“You are to present the bull at the front of the tent of meeting, and Aaron and his sons are to put their hands on the head of the bull.'
EXEC add_BibleVerse @BibleId, 102029011, N'You are to kill the bull before the Lord at the entrance to the tent of meeting'
EXEC add_BibleVerse @BibleId, 102029012, N'and take some of the blood of the bull and put it on the horns of the altar with your finger; all the rest of the blood you are to pour out at the base of the altar.'
EXEC add_BibleVerse @BibleId, 102029013, N'You are to take all the fat that covers the entrails, and the lobe that is above the liver, and the two kidneys and the fat that is on them, and burn them on the altar.'
EXEC add_BibleVerse @BibleId, 102029014, N'But the meat of the bull, its skin, and its dung you are to burn up outside the camp. It is the purification offering.'
EXEC add_BibleVerse @BibleId, 102029015, N'“You are to take one ram, and Aaron and his sons are to lay their hands on the ram’s head,'
EXEC add_BibleVerse @BibleId, 102029016, N'and you are to kill the ram and take its blood and splash it all around on the altar.'
EXEC add_BibleVerse @BibleId, 102029017, N'Then you are to cut the ram into pieces and wash the entrails and its legs and put them on its pieces and on its head'
EXEC add_BibleVerse @BibleId, 102029018, N'and burn the whole ram on the altar. It is a burnt offering to the Lord, a soothing aroma; it is an offering made by fire to the Lord.'
EXEC add_BibleVerse @BibleId, 102029019, N'“You are to take the second ram, and Aaron and his sons are to lay their hands on the ram’s head,'
EXEC add_BibleVerse @BibleId, 102029020, N'and you are to kill the ram and take some of its blood and put it on the tip of the right ear of Aaron, on the tip of the right ear of his sons, on the thumb of their right hand, and on the big toe of their right foot, and then splash the blood all around on the altar.'
EXEC add_BibleVerse @BibleId, 102029021, N'You are to take some of the blood that is on the altar and some of the anointing oil and sprinkle it on Aaron, on his garments, on his sons, and on his sons’ garments with him, so that he may be holy, he and his garments along with his sons and his sons’ garments.'
EXEC add_BibleVerse @BibleId, 102029022, N'“You are to take from the ram the fat, the fat tail, the fat that covers the entrails, the lobe of the liver, the two kidneys and the fat that is on them, and the right thigh – for it is the ram for consecration –'
EXEC add_BibleVerse @BibleId, 102029023, N'and one round flat cake of bread, one perforated cake of oiled bread, and one wafer from the basket of bread made without yeast that is before the Lord.'
EXEC add_BibleVerse @BibleId, 102029024, N'You are to put all these in Aaron’s hands and in his sons’ hands, and you are to wave them as a wave offering before the Lord.'
EXEC add_BibleVerse @BibleId, 102029025, N'Then you are to take them from their hands and burn them on the altar for a burnt offering, for a soothing aroma before the Lord. It is an offering made by fire to the Lord.'
EXEC add_BibleVerse @BibleId, 102029026, N'You are to take the breast of the ram of Aaron’s consecration; you are to wave it as a wave offering before the Lord, and it is to be your share.'
EXEC add_BibleVerse @BibleId, 102029027, N'You are to sanctify the breast of the wave offering and the thigh of the contribution, which were waved and lifted up as a contribution from the ram of consecration, from what belongs to Aaron and to his sons.'
EXEC add_BibleVerse @BibleId, 102029028, N'It is to belong to Aaron and to his sons from the Israelites, by a perpetual ordinance, for it is a contribution. It is to be a contribution from the Israelites from their peace offerings, their contribution to the Lord.'
EXEC add_BibleVerse @BibleId, 102029029, N'“The holy garments that belong to Aaron are to belong to his sons after him, so that they may be anointed in them and consecrated in them.'
EXEC add_BibleVerse @BibleId, 102029030, N'The priest who succeeds him from his sons, when he first comes to the tent of meeting to minister in the Holy Place, is to wear them for seven days.'
EXEC add_BibleVerse @BibleId, 102029031, N'“You are to take the ram of the consecration and cook its meat in a holy place.'
EXEC add_BibleVerse @BibleId, 102029032, N'Aaron and his sons are to eat the meat of the ram and the bread that was in the basket at the entrance of the tent of meeting.'
EXEC add_BibleVerse @BibleId, 102029033, N'They are to eat those things by which atonement was made to consecrate and to set them apart, but no one else may eat them, for they are holy.'
EXEC add_BibleVerse @BibleId, 102029034, N'If any of the meat from the consecration offerings or any of the bread is left over until morning, then you are to burn up what is left over. It must not be eaten, because it is holy.'
EXEC add_BibleVerse @BibleId, 102029035, N'“Thus you are to do for Aaron and for his sons, according to all that I have commanded you; you are to consecrate them for seven days.'
EXEC add_BibleVerse @BibleId, 102029036, N'Every day you are to prepare a bull for a purification offering for atonement. You are to purge the altar by making atonement for it, and you are to anoint it to set it apart as holy.'
EXEC add_BibleVerse @BibleId, 102029037, N'For seven days you are to make atonement for the altar and set it apart as holy. Then the altar will be most holy. Anything that touches the altar will be holy.'
EXEC add_BibleVerse @BibleId, 102029038, N'“Now this is what you are to prepare on the altar every day continually: two lambs a year old.'
EXEC add_BibleVerse @BibleId, 102029039, N'The first lamb you are to prepare in the morning, and the second lamb you are to prepare around sundown.'
EXEC add_BibleVerse @BibleId, 102029040, N'With the first lamb offer a tenth of an ephah of fine flour mixed with a fourth of a hin of oil from pressed olives, and a fourth of a hin of wine as a drink offering.'
EXEC add_BibleVerse @BibleId, 102029041, N'The second lamb you are to offer around sundown; you are to prepare for it the same meal offering as for the morning and the same drink offering, for a soothing aroma, an offering made by fire to the Lord.'
EXEC add_BibleVerse @BibleId, 102029042, N'“This will be a regular burnt offering throughout your generations at the entrance of the tent of meeting before the Lord, where I will meet with you to speak to you there.'
EXEC add_BibleVerse @BibleId, 102029043, N'There I will meet with the Israelites, and it will be set apart as holy by my glory.'
EXEC add_BibleVerse @BibleId, 102029044, N'“So I will set apart as holy the tent of meeting and the altar, and I will set apart as holy Aaron and his sons, that they may minister as priests to me.'
EXEC add_BibleVerse @BibleId, 102029045, N'I will reside among the Israelites, and I will be their God,'
EXEC add_BibleVerse @BibleId, 102029046, N'and they will know that I am the Lord their God, who brought them out from the land of Egypt, so that I may reside among them. I am the Lord their God.'
EXEC add_BibleVerse @BibleId, 102030001, N'“You are to make an altar for burning incense; you are to make it of acacia wood.'
EXEC add_BibleVerse @BibleId, 102030002, N'Its length is to be a foot and a half and its width a foot and a half; it will be square. Its height is to be three feet, with its horns of one piece with it.'
EXEC add_BibleVerse @BibleId, 102030003, N'You are to overlay it with pure gold – its top, its four walls, and its horns – and make a surrounding border of gold for it.'
EXEC add_BibleVerse @BibleId, 102030004, N'You are to make two gold rings for it under its border, on its two flanks; you are to make them on its two sides. The rings will be places for poles to carry it with.'
EXEC add_BibleVerse @BibleId, 102030005, N'You are to make the poles of acacia wood and overlay them with gold.'
EXEC add_BibleVerse @BibleId, 102030006, N'“You are to put it in front of the curtain that is before the ark of the testimony (before the atonement lid that is over the testimony), where I will meet you.'
EXEC add_BibleVerse @BibleId, 102030007, N'Aaron is to burn sweet incense on it morning by morning; when he attends to the lamps he is to burn incense.'
EXEC add_BibleVerse @BibleId, 102030008, N'When Aaron sets up the lamps around sundown he is to burn incense on it; it is to be a regular incense offering before the Lord throughout your generations.'
EXEC add_BibleVerse @BibleId, 102030009, N'You must not offer strange incense on it, nor burnt offering, nor meal offering, and you must not pour out a drink offering on it.'
EXEC add_BibleVerse @BibleId, 102030010, N'Aaron is to make atonement on its horns once in the year with some of the blood of the sin offering for atonement; once in the year he is to make atonement on it throughout your generations. It is most holy to the Lord.”'
EXEC add_BibleVerse @BibleId, 102030011, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 102030012, N'“When you take a census of the Israelites according to their number, then each man is to pay a ransom for his life to the Lord when you number them, so that there will be no plague among them when you number them.'
EXEC add_BibleVerse @BibleId, 102030013, N'Everyone who crosses over to those who are numbered is to pay this: a half shekel according to the shekel of the sanctuary (a shekel weighs twenty gerahs). The half shekel is to be an offering to the Lord.'
EXEC add_BibleVerse @BibleId, 102030014, N'Everyone who crosses over to those numbered, from twenty years old and up, is to pay an offering to the Lord.'
EXEC add_BibleVerse @BibleId, 102030015, N'The rich are not to increase it, and the poor are not to pay less than the half shekel when giving the offering of the Lord, to make atonement for your lives.'
EXEC add_BibleVerse @BibleId, 102030016, N'You are to receive the atonement money from the Israelites and give it for the service of the tent of meeting. It will be a memorial for the Israelites before the Lord, to make atonement for your lives.”'
EXEC add_BibleVerse @BibleId, 102030017, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 102030018, N'“You are also to make a large bronze basin with a bronze stand for washing. You are to put it between the tent of meeting and the altar and put water in it,'
EXEC add_BibleVerse @BibleId, 102030019, N'and Aaron and his sons must wash their hands and their feet from it.'
EXEC add_BibleVerse @BibleId, 102030020, N'When they enter the tent of meeting, they must wash with water so that they do not die. Also, when they approach the altar to minister by burning incense as an offering made by fire to the Lord,'
EXEC add_BibleVerse @BibleId, 102030021, N'they must wash their hands and their feet so that they do not die. And this will be a perpetual ordinance for them and for their descendants throughout their generations.”'
EXEC add_BibleVerse @BibleId, 102030022, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 102030023, N'“Take choice spices: twelve and a half pounds of free-flowing myrrh, half that – about six and a quarter pounds – of sweet-smelling cinnamon, six and a quarter pounds of sweet-smelling cane,'
EXEC add_BibleVerse @BibleId, 102030024, N'and twelve and a half pounds of cassia, all weighed according to the sanctuary shekel, and four quarts of olive oil.'
EXEC add_BibleVerse @BibleId, 102030025, N'You are to make this into a sacred anointing oil, a perfumed compound, the work of a perfumer. It will be sacred anointing oil.'
EXEC add_BibleVerse @BibleId, 102030026, N'“With it you are to anoint the tent of meeting, the ark of the testimony,'
EXEC add_BibleVerse @BibleId, 102030027, N'the table and all its utensils, the lampstand and its utensils, the altar of incense,'
EXEC add_BibleVerse @BibleId, 102030028, N'the altar for the burnt offering and all its utensils, and the laver and its base.'
EXEC add_BibleVerse @BibleId, 102030029, N'So you are to sanctify them, and they will be most holy; anything that touches them will be holy.'
EXEC add_BibleVerse @BibleId, 102030030, N'“You are to anoint Aaron and his sons and sanctify them, so that they may minister as my priests.'
EXEC add_BibleVerse @BibleId, 102030031, N'And you are to tell the Israelites: ‘This is to be my sacred anointing oil throughout your generations.'
EXEC add_BibleVerse @BibleId, 102030032, N'It must not be applied to people’s bodies, and you must not make any like it with the same recipe. It is holy, and it must be holy to you.'
EXEC add_BibleVerse @BibleId, 102030033, N'Whoever makes perfume like it and whoever puts any of it on someone not a priest will be cut off from his people.’”'
EXEC add_BibleVerse @BibleId, 102030034, N'The Lord said to Moses: “Take spices, gum resin, onycha, galbanum, and pure frankincense of equal amounts'
EXEC add_BibleVerse @BibleId, 102030035, N'and make it into an incense, a perfume, the work of a perfumer. It is to be finely ground, and pure and sacred.'
EXEC add_BibleVerse @BibleId, 102030036, N'You are to beat some of it very fine and put some of it before the ark of the testimony in the tent of meeting where I will meet with you; it is to be most holy to you.'
EXEC add_BibleVerse @BibleId, 102030037, N'And the incense that you are to make, you must not make for yourselves using the same recipe; it is to be most holy to you, belonging to the Lord.'
EXEC add_BibleVerse @BibleId, 102030038, N'Whoever makes anything like it, to use as perfume, will be cut off from his people.”'
EXEC add_BibleVerse @BibleId, 102031001, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 102031002, N'“See, I have chosen Bezalel son of Uri, the son of Hur, of the tribe of Judah,'
EXEC add_BibleVerse @BibleId, 102031003, N'and I have filled him with the Spirit of God in skill, in understanding, in knowledge, and in all kinds of craftsmanship,'
EXEC add_BibleVerse @BibleId, 102031004, N'to make artistic designs for work with gold, with silver, and with bronze,'
EXEC add_BibleVerse @BibleId, 102031005, N'and with cutting and setting stone, and with cutting wood, to work in all kinds of craftsmanship.'
EXEC add_BibleVerse @BibleId, 102031006, N'Moreover, I have also given him Oholiab son of Ahisamach, of the tribe of Dan, and I have given ability to all the specially skilled, that they may make everything I have commanded you:'
EXEC add_BibleVerse @BibleId, 102031007, N'the tent of meeting, the ark of the testimony, the atonement lid that is on it, all the furnishings of the tent,'
EXEC add_BibleVerse @BibleId, 102031008, N'the table with its utensils, the pure lampstand with all its utensils, the altar of incense,'
EXEC add_BibleVerse @BibleId, 102031009, N'the altar for the burnt offering with all its utensils, the large basin with its base,'
EXEC add_BibleVerse @BibleId, 102031010, N'the woven garments, the holy garments for Aaron the priest and the garments for his sons, to minister as priests,'
EXEC add_BibleVerse @BibleId, 102031011, N'the anointing oil, and sweet incense for the Holy Place. They will make all these things just as I have commanded you.”'
EXEC add_BibleVerse @BibleId, 102031012, N'The Lord said to Moses,'
EXEC add_BibleVerse @BibleId, 102031013, N'“Tell the Israelites, ‘Surely you must keep my Sabbaths, for it is a sign between me and you throughout your generations, that you may know that I am the Lord who sanctifies you.'
EXEC add_BibleVerse @BibleId, 102031014, N'So you must keep the Sabbath, for it is holy for you. Everyone who defiles it must surely be put to death; indeed, if anyone does any work on it, then that person will be cut off from among his people.'
EXEC add_BibleVerse @BibleId, 102031015, N'Six days work may be done, but on the seventh day is a Sabbath of complete rest, holy to the Lord; anyone who does work on the Sabbath day must surely be put to death.'
EXEC add_BibleVerse @BibleId, 102031016, N'The Israelites must keep the Sabbath by observing the Sabbath throughout their generations as a perpetual covenant.'
EXEC add_BibleVerse @BibleId, 102031017, N'It is a sign between me and the Israelites forever; for in six days the Lord made the heavens and the earth, and on the seventh day he rested and was refreshed.’”'
EXEC add_BibleVerse @BibleId, 102031018, N'He gave Moses two tablets of testimony when he had finished speaking with him on Mount Sinai, tablets of stone written by the finger of God.'
EXEC add_BibleVerse @BibleId, 102032001, N'When the people saw that Moses delayed in coming down from the mountain, they gathered around Aaron and said to him, “Get up, make us gods that will go before us. As for this fellow Moses, the man who brought us up from the land of Egypt, we do not know what has become of him!”'
EXEC add_BibleVerse @BibleId, 102032002, N'So Aaron said to them, “Break off the gold earrings that are on the ears of your wives, your sons, and your daughters, and bring them to me.”'
EXEC add_BibleVerse @BibleId, 102032003, N'So all the people broke off the gold earrings that were on their ears and brought them to Aaron.'
EXEC add_BibleVerse @BibleId, 102032004, N'He accepted the gold from them, fashioned it with an engraving tool, and made a molten calf. Then they said, “These are your gods, O Israel, who brought you up out of Egypt.”'
EXEC add_BibleVerse @BibleId, 102032005, N'When Aaron saw this, he built an altar before it, and Aaron made a proclamation and said, “Tomorrow will be a feast to the Lord.”'
EXEC add_BibleVerse @BibleId, 102032006, N'So they got up early on the next day and offered up burnt offerings and brought peace offerings, and the people sat down to eat and drink, and they rose up to play.'
EXEC add_BibleVerse @BibleId, 102032007, N'The Lord spoke to Moses: “Go quickly, descend, because your people, whom you brought up from the land of Egypt, have acted corruptly.'
EXEC add_BibleVerse @BibleId, 102032008, N'They have quickly turned aside from the way that I commanded them – they have made for themselves a molten calf and have bowed down to it and sacrificed to it and said, ‘These are your gods, O Israel, which brought you up from the land of Egypt.’”'
EXEC add_BibleVerse @BibleId, 102032009, N'Then the Lord said to Moses: “I have seen this people. Look what a stiff-necked people they are!'
EXEC add_BibleVerse @BibleId, 102032010, N'So now, leave me alone so that my anger can burn against them and I can destroy them, and I will make from you a great nation.”'
EXEC add_BibleVerse @BibleId, 102032011, N'But Moses sought the favor of the Lord his God and said, “O Lord, why does your anger burn against your people, whom you have brought out from the land of Egypt with great power and with a mighty hand?'
EXEC add_BibleVerse @BibleId, 102032012, N'Why should the Egyptians say, ‘For evil he led them out to kill them in the mountains and to destroy them from the face of the earth’? Turn from your burning anger, and relent of this evil against your people.'
EXEC add_BibleVerse @BibleId, 102032013, N'Remember Abraham, Isaac, and Israel your servants, to whom you swore by yourself and told them, ‘I will multiply your descendants like the stars of heaven, and all this land that I have spoken about I will give to your descendants, and they will inherit it forever.’”'
EXEC add_BibleVerse @BibleId, 102032014, N'Then the Lord relented over the evil that he had said he would do to his people.'
EXEC add_BibleVerse @BibleId, 102032015, N'Moses turned and went down from the mountain with the two tablets of the testimony in his hands. The tablets were written on both sides – they were written on the front and on the back.'
EXEC add_BibleVerse @BibleId, 102032016, N'Now the tablets were the work of God, and the writing was the writing of God, engraved on the tablets.'
EXEC add_BibleVerse @BibleId, 102032017, N'When Joshua heard the noise of the people as they shouted, he said to Moses, “It is the sound of war in the camp!”'
EXEC add_BibleVerse @BibleId, 102032018, N'Moses said, “It is not the sound of those who shout for victory, nor is it the sound of those who cry because they are overcome, but the sound of singing I hear.”'
EXEC add_BibleVerse @BibleId, 102032019, N'When he approached the camp and saw the calf and the dancing, Moses became extremely angry. He threw the tablets from his hands and broke them to pieces at the bottom of the mountain.'
EXEC add_BibleVerse @BibleId, 102032020, N'He took the calf they had made and burned it in the fire, ground it to powder, poured it out on the water, and made the Israelites drink it.'
EXEC add_BibleVerse @BibleId, 102032021, N'Moses said to Aaron, “What did this people do to you, that you have brought on them so great a sin?”'
EXEC add_BibleVerse @BibleId, 102032022, N'Aaron said, “Do not let your anger burn hot, my lord; you know these people, that they tend to evil.'
EXEC add_BibleVerse @BibleId, 102032023, N'They said to me, ‘Make us gods that will go before us, for as for this fellow Moses, the man who brought us up out of the land of Egypt, we do not know what has happened to him.’'
EXEC add_BibleVerse @BibleId, 102032024, N'So I said to them, ‘Whoever has gold, break it off.’ So they gave it to me, and I threw it into the fire, and this calf came out.”'
EXEC add_BibleVerse @BibleId, 102032025, N'Moses saw that the people were running wild, for Aaron had let them get completely out of control, causing derision from their enemies.'
EXEC add_BibleVerse @BibleId, 102032026, N'So Moses stood at the entrance of the camp and said, “Whoever is for the Lord, come to me.” All the Levites gathered around him,'
EXEC add_BibleVerse @BibleId, 102032027, N'and he said to them, “Thus says the Lord, the God of Israel, ‘Each man fasten his sword on his side, and go back and forth from entrance to entrance throughout the camp, and each one kill his brother, his friend, and his neighbor.’”'
EXEC add_BibleVerse @BibleId, 102032028, N'The Levites did what Moses ordered, and that day about three thousand men of the people died.'
EXEC add_BibleVerse @BibleId, 102032029, N'Moses said, “You have been consecrated today for the Lord, for each of you was against his son or against his brother, so he has given a blessing to you today.”'
EXEC add_BibleVerse @BibleId, 102032030, N'The next day Moses said to the people, “You have committed a very serious sin, but now I will go up to the Lord – perhaps I can make atonement on behalf of your sin.”'
EXEC add_BibleVerse @BibleId, 102032031, N'So Moses returned to the Lord and said, “Alas, this people has committed a very serious sin, and they have made for themselves gods of gold.'
EXEC add_BibleVerse @BibleId, 102032032, N'But now, if you will forgive their sin…, but if not, wipe me out from your book that you have written.”'
EXEC add_BibleVerse @BibleId, 102032033, N'The Lord said to Moses, “Whoever has sinned against me – that person I will wipe out of my book.'
EXEC add_BibleVerse @BibleId, 102032034, N'So now go, lead the people to the place I have spoken to you about. See, my angel will go before you. But on the day that I punish, I will indeed punish them for their sin.”'
EXEC add_BibleVerse @BibleId, 102032035, N'And the Lord sent a plague on the people because they had made the calf – the one Aaron made.'
EXEC add_BibleVerse @BibleId, 102033001, N'The Lord said to Moses, “Go up from here, you and the people whom you brought up out of the land of Egypt, to the land I promised on oath to Abraham, to Isaac, and to Jacob, saying, ‘I will give it to your descendants.’'
EXEC add_BibleVerse @BibleId, 102033002, N'I will send an angel before you, and I will drive out the Canaanite, the Amorite, the Hittite, the Perizzite, the Hivite, and the Jebusite.'
EXEC add_BibleVerse @BibleId, 102033003, N'Go up to a land flowing with milk and honey. But I will not go up among you, for you are a stiff-necked people, and I might destroy you on the way.”'
EXEC add_BibleVerse @BibleId, 102033004, N'When the people heard this troubling word they mourned; no one put on his ornaments.'
EXEC add_BibleVerse @BibleId, 102033005, N'For the Lord had said to Moses, “Tell the Israelites, ‘You are a stiff-necked people. If I went up among you for a moment, I might destroy you. Now take off your ornaments, that I may know what I should do to you.’”'
EXEC add_BibleVerse @BibleId, 102033006, N'So the Israelites stripped off their ornaments by Mount Horeb.'
EXEC add_BibleVerse @BibleId, 102033007, N'Moses took the tent and pitched it outside the camp, at a good distance from the camp, and he called it the tent of meeting. Anyone seeking the Lord would go out to the tent of meeting that was outside the camp.'
EXEC add_BibleVerse @BibleId, 102033008, N'And when Moses went out to the tent, all the people would get up and stand at the entrance to their tents and watch Moses until he entered the tent.'
EXEC add_BibleVerse @BibleId, 102033009, N'And whenever Moses entered the tent, the pillar of cloud would descend and stand at the entrance of the tent, and the Lord would speak with Moses.'
EXEC add_BibleVerse @BibleId, 102033010, N'When all the people would see the pillar of cloud standing at the entrance of the tent, all the people, each one at the entrance of his own tent, would rise and worship.'
EXEC add_BibleVerse @BibleId, 102033011, N'The Lord would speak to Moses face to face, the way a person speaks to a friend. Then Moses would return to the camp, but his servant, Joshua son of Nun, a young man, did not leave the tent.'
EXEC add_BibleVerse @BibleId, 102033012, N'Moses said to the Lord, “See, you have been saying to me, ‘Bring this people up,’ but you have not let me know whom you will send with me. But you said, ‘I know you by name, and also you have found favor in my sight.’'
EXEC add_BibleVerse @BibleId, 102033013, N'Now if I have found favor in your sight, show me your way, that I may know you, that I may continue to find favor in your sight. And see that this nation is your people.”'
EXEC add_BibleVerse @BibleId, 102033014, N'And the Lord said, “My presence will go with you, and I will give you rest.”'
EXEC add_BibleVerse @BibleId, 102033015, N'And Moses said to him, “If your presence does not go with us, do not take us up from here.'
EXEC add_BibleVerse @BibleId, 102033016, N'For how will it be known then that I have found favor in your sight, I and your people? Is it not by your going with us, so that we will be distinguished, I and your people, from all the people who are on the face of the earth?”'
EXEC add_BibleVerse @BibleId, 102033017, N'The Lord said to Moses, “I will do this thing also that you have requested, for you have found favor in my sight, and I know you by name.”'
EXEC add_BibleVerse @BibleId, 102033018, N'And Moses said, “Show me your glory.”'
EXEC add_BibleVerse @BibleId, 102033019, N'And the Lord said, “I will make all my goodness pass before your face, and I will proclaim the Lord by name before you; I will be gracious to whom I will be gracious, I will show mercy to whom I will show mercy.”'
EXEC add_BibleVerse @BibleId, 102033020, N'But he added, “You cannot see my face, for no one can see me and live.”'
EXEC add_BibleVerse @BibleId, 102033021, N'The Lord said, “Here is a place by me; you will station yourself on a rock.'
EXEC add_BibleVerse @BibleId, 102033022, N'When my glory passes by, I will put you in a cleft in the rock and will cover you with my hand while I pass by.'
EXEC add_BibleVerse @BibleId, 102033023, N'Then I will take away my hand, and you will see my back, but my face must not be seen.”'
EXEC add_BibleVerse @BibleId, 102034001, N'The Lord said to Moses, “Cut out two tablets of stone like the first, and I will write on the tablets the words that were on the first tablets, which you smashed.'
EXEC add_BibleVerse @BibleId, 102034002, N'Be prepared in the morning, and go up in the morning to Mount Sinai, and station yourself for me there on the top of the mountain.'
EXEC add_BibleVerse @BibleId, 102034003, N'No one is to come up with you; do not let anyone be seen anywhere on the mountain; not even the flocks or the herds may graze in front of that mountain.”'
EXEC add_BibleVerse @BibleId, 102034004, N'So Moses cut out two tablets of stone like the first; early in the morning he went up to Mount Sinai, just as the Lord had commanded him, and he took in his hand the two tablets of stone.'
EXEC add_BibleVerse @BibleId, 102034005, N'The Lord descended in the cloud and stood with him there and proclaimed the Lord by name.'
EXEC add_BibleVerse @BibleId, 102034006, N'The Lord passed by before him and proclaimed: “The Lord, the Lord, the compassionate and gracious God, slow to anger, and abounding in loyal love and faithfulness,'
EXEC add_BibleVerse @BibleId, 102034007, N'keeping loyal love for thousands, forgiving iniquity and transgression and sin. But he by no means leaves the guilty unpunished, responding to the transgression of fathers by dealing with children and children’s children, to the third and fourth generation.”'
EXEC add_BibleVerse @BibleId, 102034008, N'Moses quickly bowed to the ground and worshiped'
EXEC add_BibleVerse @BibleId, 102034009, N'and said, “If now I have found favor in your sight, O Lord, let my Lord go among us, for we are a stiff-necked people; pardon our iniquity and our sin, and take us for your inheritance.”'
EXEC add_BibleVerse @BibleId, 102034010, N'He said, “See, I am going to make a covenant before all your people. I will do wonders such as have not been done in all the earth, nor in any nation. All the people among whom you live will see the work of the Lord, for it is a fearful thing that I am doing with you.'
EXEC add_BibleVerse @BibleId, 102034011, N'“Obey what I am commanding you this day. I am going to drive out before you the Amorite, the Canaanite, the Hittite, the Perizzite, the Hivite, and the Jebusite.'
EXEC add_BibleVerse @BibleId, 102034012, N'Be careful not to make a covenant with the inhabitants of the land where you are going, lest it become a snare among you.'
EXEC add_BibleVerse @BibleId, 102034013, N'Rather you must destroy their altars, smash their images, and cut down their Asherah poles.'
EXEC add_BibleVerse @BibleId, 102034014, N'For you must not worship any other god, for the Lord, whose name is Jealous, is a jealous God.'
EXEC add_BibleVerse @BibleId, 102034015, N'Be careful not to make a covenant with the inhabitants of the land, for when they prostitute themselves to their gods and sacrifice to their gods, and someone invites you, you will eat from his sacrifice;'
EXEC add_BibleVerse @BibleId, 102034016, N'and you then take his daughters for your sons, and when his daughters prostitute themselves to their gods, they will make your sons prostitute themselves to their gods as well.'
EXEC add_BibleVerse @BibleId, 102034017, N'You must not make yourselves molten gods.'
EXEC add_BibleVerse @BibleId, 102034018, N'“You must keep the Feast of Unleavened Bread. For seven days you must eat bread made without yeast, as I commanded you; do this at the appointed time of the month Abib, for in the month Abib you came out of Egypt.'
EXEC add_BibleVerse @BibleId, 102034019, N'“Every firstborn of the womb belongs to me, even every firstborn of your cattle that is a male, whether ox or sheep.'
EXEC add_BibleVerse @BibleId, 102034020, N'Now the firstling of a donkey you may redeem with a lamb, but if you do not redeem it, then break its neck. You must redeem all the firstborn of your sons. “No one will appear before me empty-handed.'
EXEC add_BibleVerse @BibleId, 102034021, N'“On six days you may labor, but on the seventh day you must rest; even at the time of plowing and of harvest you are to rest.'
EXEC add_BibleVerse @BibleId, 102034022, N'“You must observe the Feast of Weeks – the firstfruits of the harvest of wheat – and the Feast of Ingathering at the end of the year.'
EXEC add_BibleVerse @BibleId, 102034023, N'At three times in the year all your men must appear before the Lord God, the God of Israel.'
EXEC add_BibleVerse @BibleId, 102034024, N'For I will drive out the nations before you and enlarge your borders; no one will covet your land when you go up to appear before the Lord your God three times in the year.'
EXEC add_BibleVerse @BibleId, 102034025, N'“You must not offer the blood of my sacrifice with yeast; the sacrifice from the feast of Passover must not remain until the following morning.'
EXEC add_BibleVerse @BibleId, 102034026, N'“The first of the firstfruits of your soil you must bring to the house of the Lord your God. You must not cook a young goat in its mother’s milk.”'
EXEC add_BibleVerse @BibleId, 102034027, N'The Lord said to Moses, “Write down these words, for in accordance with these words I have made a covenant with you and with Israel.”'
EXEC add_BibleVerse @BibleId, 102034028, N'So he was there with the Lord forty days and forty nights; he did not eat bread, and he did not drink water. He wrote on the tablets the words of the covenant, the ten commandments.'
EXEC add_BibleVerse @BibleId, 102034029, N'Now when Moses came down from Mount Sinai with the two tablets of the testimony in his hand – when he came down from the mountain, Moses did not know that the skin of his face shone while he talked with him.'
EXEC add_BibleVerse @BibleId, 102034030, N'When Aaron and all the Israelites saw Moses, the skin of his face shone; and they were afraid to approach him.'
EXEC add_BibleVerse @BibleId, 102034031, N'But Moses called to them, so Aaron and all the leaders of the community came back to him, and Moses spoke to them.'
EXEC add_BibleVerse @BibleId, 102034032, N'After this all the Israelites approached, and he commanded them all that the Lord had spoken to him on Mount Sinai.'
EXEC add_BibleVerse @BibleId, 102034033, N'When Moses finished speaking with them, he would put a veil on his face.'
EXEC add_BibleVerse @BibleId, 102034034, N'But when Moses went in before the Lord to speak with him, he would remove the veil until he came out. Then he would come out and tell the Israelites what he had been commanded.'
EXEC add_BibleVerse @BibleId, 102034035, N'When the Israelites would see the face of Moses, that the skin of Moses’ face shone, Moses would put the veil on his face again, until he went in to speak with the Lord.'
EXEC add_BibleVerse @BibleId, 102035001, N'Moses assembled the whole community of the Israelites and said to them, “These are the things that the Lord has commanded you to do.'
EXEC add_BibleVerse @BibleId, 102035002, N'In six days work may be done, but on the seventh day there must be a holy day for you, a Sabbath of complete rest to the Lord. Anyone who does work on it will be put to death.'
EXEC add_BibleVerse @BibleId, 102035003, N'You must not kindle a fire in any of your homes on the Sabbath day.”'
EXEC add_BibleVerse @BibleId, 102035004, N'Moses spoke to the whole community of the Israelites, “This is the word that the Lord has commanded:'
EXEC add_BibleVerse @BibleId, 102035005, N'‘Take an offering for the Lord. Let everyone who has a willing heart bring an offering to the Lord: gold, silver, bronze,'
EXEC add_BibleVerse @BibleId, 102035006, N'blue, purple, and scarlet yarn, fine linen, goat’s hair,'
EXEC add_BibleVerse @BibleId, 102035007, N'ram skins dyed red, fine leather, acacia wood,'
EXEC add_BibleVerse @BibleId, 102035008, N'olive oil for the light, spices for the anointing oil and for the fragrant incense,'
EXEC add_BibleVerse @BibleId, 102035009, N'onyx stones, and other gems for mounting on the ephod and the breastpiece.'
EXEC add_BibleVerse @BibleId, 102035010, N'Every skilled person among you is to come and make all that the Lord has commanded:'
EXEC add_BibleVerse @BibleId, 102035011, N'the tabernacle with its tent, its covering, its clasps, its frames, its crossbars, its posts, and its bases;'
EXEC add_BibleVerse @BibleId, 102035012, N'the ark, with its poles, the atonement lid, and the special curtain that conceals it;'
EXEC add_BibleVerse @BibleId, 102035013, N'the table with its poles and all its vessels, and the Bread of the Presence;'
EXEC add_BibleVerse @BibleId, 102035014, N'the lampstand for the light and its accessories, its lamps, and oil for the light;'
EXEC add_BibleVerse @BibleId, 102035015, N'and the altar of incense with its poles, the anointing oil, and the fragrant incense; the hanging for the door at the entrance of the tabernacle;'
EXEC add_BibleVerse @BibleId, 102035016, N'the altar for the burnt offering with its bronze grating that is on it, its poles, and all its utensils; the large basin and its pedestal;'
EXEC add_BibleVerse @BibleId, 102035017, N'the hangings of the courtyard, its posts and its bases, and the curtain for the gateway to the courtyard;'
EXEC add_BibleVerse @BibleId, 102035018, N'tent pegs for the tabernacle and tent pegs for the courtyard and their ropes;'
EXEC add_BibleVerse @BibleId, 102035019, N'the woven garments for serving in the holy place, the holy garments for Aaron the priest, and the garments for his sons to minister as priests.”'
EXEC add_BibleVerse @BibleId, 102035020, N'So the whole community of the Israelites went out from the presence of Moses.'
EXEC add_BibleVerse @BibleId, 102035021, N'Everyone whose heart stirred him to action and everyone whose spirit was willing came and brought the offering for the Lord for the work of the tent of meeting, for all its service, and for the holy garments.'
EXEC add_BibleVerse @BibleId, 102035022, N'They came, men and women alike, all who had willing hearts. They brought brooches, earrings, rings and ornaments, all kinds of gold jewelry, and everyone came who waved a wave offering of gold to the Lord.'
EXEC add_BibleVerse @BibleId, 102035023, N'Everyone who had blue, purple, or scarlet yarn, fine linen, goats’ hair, ram skins dyed red, or fine leather brought them.'
EXEC add_BibleVerse @BibleId, 102035024, N'Everyone making an offering of silver or bronze brought it as an offering to the Lord, and everyone who had acacia wood for any work of the service brought it.'
EXEC add_BibleVerse @BibleId, 102035025, N'Every woman who was skilled spun with her hands and brought what she had spun, blue, purple, or scarlet yarn, or fine linen,'
EXEC add_BibleVerse @BibleId, 102035026, N'and all the women whose heart stirred them to action and who were skilled spun goats’ hair.'
EXEC add_BibleVerse @BibleId, 102035027, N'The leaders brought onyx stones and other gems to be mounted for the ephod and the breastpiece,'
EXEC add_BibleVerse @BibleId, 102035028, N'and spices and olive oil for the light, for the anointing oil, and for the fragrant incense.'
EXEC add_BibleVerse @BibleId, 102035029, N'The Israelites brought a freewill offering to the Lord, every man and woman whose heart was willing to bring materials for all the work that the Lord through Moses had commanded them to do.'
EXEC add_BibleVerse @BibleId, 102035030, N'Moses said to the Israelites, “See, the Lord has chosen Bezalel son of Uri, the son of Hur, of the tribe of Judah.'
EXEC add_BibleVerse @BibleId, 102035031, N'He has filled him with the Spirit of God – with skill, with understanding, with knowledge, and in all kinds of work,'
EXEC add_BibleVerse @BibleId, 102035032, N'to design artistic designs, to work in gold, in silver, and in bronze,'
EXEC add_BibleVerse @BibleId, 102035033, N'and in cutting stones for their setting, and in cutting wood, to do work in every artistic craft.'
EXEC add_BibleVerse @BibleId, 102035034, N'And he has put it in his heart to teach, he and Oholiab son of Ahisamach, of the tribe of Dan.'
EXEC add_BibleVerse @BibleId, 102035035, N'He has filled them with skill to do all kinds of work as craftsmen, as designers, as embroiderers in blue, purple, and scarlet yarn and in fine linen, and as weavers. They are craftsmen in all the work and artistic designers.'
EXEC add_BibleVerse @BibleId, 102036001, N'So Bezalel and Oholiab and every skilled person in whom the Lord has put skill and ability to know how to do all the work for the service of the sanctuary are to do the work according to all that the Lord has commanded.”'
EXEC add_BibleVerse @BibleId, 102036002, N'Moses summoned Bezalel and Oholiab and every skilled person in whom the Lord had put skill – everyone whose heart stirred him to volunteer to do the work,'
EXEC add_BibleVerse @BibleId, 102036003, N'and they received from Moses all the offerings the Israelites had brought to do the work for the service of the sanctuary, and they still continued to bring him a freewill offering each morning.'
EXEC add_BibleVerse @BibleId, 102036004, N'So all the skilled people who were doing all the work on the sanctuary came from the work they were doing'
EXEC add_BibleVerse @BibleId, 102036005, N'and told Moses, “The people are bringing much more than is needed for the completion of the work which the Lord commanded us to do!”'
EXEC add_BibleVerse @BibleId, 102036006, N'Moses instructed them to take his message throughout the camp, saying, “Let no man or woman do any more work for the offering for the sanctuary.” So the people were restrained from bringing any more.'
EXEC add_BibleVerse @BibleId, 102036007, N'Now the materials were more than enough for them to do all the work.'
EXEC add_BibleVerse @BibleId, 102036008, N'All the skilled among those who were doing the work made the tabernacle with ten curtains of fine twisted linen and blue and purple and scarlet; they were made with cherubim that were the work of an artistic designer.'
EXEC add_BibleVerse @BibleId, 102036009, N'The length of one curtain was forty-two feet, and the width of one curtain was six feet – the same size for each of the curtains.'
EXEC add_BibleVerse @BibleId, 102036010, N'He joined five of the curtains to one another, and the other five curtains he joined to one another.'
EXEC add_BibleVerse @BibleId, 102036011, N'He made loops of blue material along the edge of the end curtain in the first set; he did the same along the edge of the end curtain in the second set.'
EXEC add_BibleVerse @BibleId, 102036012, N'He made fifty loops on the first curtain, and he made fifty loops on the end curtain that was in the second set, with the loops opposite one another.'
EXEC add_BibleVerse @BibleId, 102036013, N'He made fifty gold clasps and joined the curtains together to one another with the clasps, so that the tabernacle was a unit.'
EXEC add_BibleVerse @BibleId, 102036014, N'He made curtains of goats’ hair for a tent over the tabernacle; he made eleven curtains.'
EXEC add_BibleVerse @BibleId, 102036015, N'The length of one curtain was forty-five feet, and the width of one curtain was six feet – one size for all eleven curtains.'
EXEC add_BibleVerse @BibleId, 102036016, N'He joined five curtains by themselves and six curtains by themselves.'
EXEC add_BibleVerse @BibleId, 102036017, N'He made fifty loops along the edge of the end curtain in the first set and fifty loops along the edge of the curtain that joined the second set.'
EXEC add_BibleVerse @BibleId, 102036018, N'He made fifty bronze clasps to join the tent together so that it might be a unit.'
EXEC add_BibleVerse @BibleId, 102036019, N'He made a covering for the tent out of ram skins dyed red and over that a covering of fine leather.'
EXEC add_BibleVerse @BibleId, 102036020, N'He made the frames for the tabernacle of acacia wood as uprights.'
EXEC add_BibleVerse @BibleId, 102036021, N'The length of each frame was fifteen feet, the width of each frame was two and a quarter feet,'
EXEC add_BibleVerse @BibleId, 102036022, N'with two projections per frame parallel one to another. He made all the frames of the tabernacle in this way.'
EXEC add_BibleVerse @BibleId, 102036023, N'So he made frames for the tabernacle: twenty frames for the south side.'
EXEC add_BibleVerse @BibleId, 102036024, N'He made forty silver bases under the twenty frames – two bases under the first frame for its two projections, and likewise two bases under the next frame for its two projections,'
EXEC add_BibleVerse @BibleId, 102036025, N'and for the second side of the tabernacle, the north side, he made twenty frames'
EXEC add_BibleVerse @BibleId, 102036026, N'and their forty silver bases, two bases under the first frame and two bases under the next frame.'
EXEC add_BibleVerse @BibleId, 102036027, N'And for the back of the tabernacle on the west he made six frames.'
EXEC add_BibleVerse @BibleId, 102036028, N'He made two frames for the corners of the tabernacle on the back.'
EXEC add_BibleVerse @BibleId, 102036029, N'At the two corners they were doubled at the lower end and finished together at the top in one ring. So he did for both.'
EXEC add_BibleVerse @BibleId, 102036030, N'So there were eight frames and their silver bases, sixteen bases, two bases under each frame.'
EXEC add_BibleVerse @BibleId, 102036031, N'He made bars of acacia wood, five for the frames on one side of the tabernacle'
EXEC add_BibleVerse @BibleId, 102036032, N'and five bars for the frames on the second side of the tabernacle, and five bars for the frames of the tabernacle for the back side on the west.'
EXEC add_BibleVerse @BibleId, 102036033, N'He made the middle bar to reach from end to end in the center of the frames.'
EXEC add_BibleVerse @BibleId, 102036034, N'He overlaid the frames with gold and made their rings of gold to provide places for the bars, and he overlaid the bars with gold.'
EXEC add_BibleVerse @BibleId, 102036035, N'He made the special curtain of blue, purple, and scarlet yarn and fine twisted linen; he made it with cherubim, the work of an artistic designer.'
EXEC add_BibleVerse @BibleId, 102036036, N'He made for it four posts of acacia wood and overlaid them with gold, with gold hooks, and he cast for them four silver bases.'
EXEC add_BibleVerse @BibleId, 102036037, N'He made a hanging for the entrance of the tent of blue, purple, and scarlet yarn and fine twisted linen, the work of an embroiderer,'
EXEC add_BibleVerse @BibleId, 102036038, N'and its five posts and their hooks. He overlaid their tops and their bands with gold, but their five bases were bronze.'
EXEC add_BibleVerse @BibleId, 102037001, N'Bezalel made the ark of acacia wood; its length was three feet nine inches, its width two feet three inches, and its height two feet three inches.'
EXEC add_BibleVerse @BibleId, 102037002, N'He overlaid it with pure gold, inside and out, and he made a surrounding border of gold for it.'
EXEC add_BibleVerse @BibleId, 102037003, N'He cast four gold rings for it that he put on its four feet, with two rings on one side and two rings on the other side.'
EXEC add_BibleVerse @BibleId, 102037004, N'He made poles of acacia wood, overlaid them with gold,'
EXEC add_BibleVerse @BibleId, 102037005, N'and put the poles into the rings on the sides of the ark in order to carry the ark.'
EXEC add_BibleVerse @BibleId, 102037006, N'He made an atonement lid of pure gold; its length was three feet nine inches, and its width was two feet three inches.'
EXEC add_BibleVerse @BibleId, 102037007, N'He made two cherubim of gold; he made them of hammered metal on the two ends of the atonement lid,'
EXEC add_BibleVerse @BibleId, 102037008, N'one cherub on one end and one cherub on the other end. He made the cherubim from the atonement lid on its two ends.'
EXEC add_BibleVerse @BibleId, 102037009, N'The cherubim were spreading their wings upward, overshadowing the atonement lid with their wings. The cherubim faced each other, looking toward the atonement lid.'
EXEC add_BibleVerse @BibleId, 102037010, N'He made the table of acacia wood; its length was three feet, its width one foot six inches, and its height two feet three inches.'
EXEC add_BibleVerse @BibleId, 102037011, N'He overlaid it with pure gold, and he made a surrounding border of gold for it.'
EXEC add_BibleVerse @BibleId, 102037012, N'He made a surrounding frame for it about three inches wide, and he made a surrounding border of gold for its frame.'
EXEC add_BibleVerse @BibleId, 102037013, N'He cast four gold rings for it and attached the rings at the four corners where its four legs were.'
EXEC add_BibleVerse @BibleId, 102037014, N'The rings were close to the frame to provide places for the poles to carry the table.'
EXEC add_BibleVerse @BibleId, 102037015, N'He made the poles of acacia wood and overlaid them with gold, to carry the table.'
EXEC add_BibleVerse @BibleId, 102037016, N'He made the vessels which were on the table out of pure gold, its plates, its ladles, its pitchers, and its bowls, to be used in pouring out offerings.'
EXEC add_BibleVerse @BibleId, 102037017, N'He made the lampstand of pure gold. He made the lampstand of hammered metal; its base and its shaft, its cups, its buds, and its blossoms were from the same piece.'
EXEC add_BibleVerse @BibleId, 102037018, N'Six branches were extending from its sides, three branches of the lampstand from one side of it, and three branches of the lampstand from the other side of it.'
EXEC add_BibleVerse @BibleId, 102037019, N'Three cups shaped like almond flowers with buds and blossoms were on the first branch, and three cups shaped like almond flowers with buds and blossoms were on the next branch, and the same for the six branches that were extending from the lampstand.'
EXEC add_BibleVerse @BibleId, 102037020, N'On the lampstand there were four cups shaped like almond flowers with buds and blossoms,'
EXEC add_BibleVerse @BibleId, 102037021, N'with a bud under the first two branches from it, and a bud under the next two branches from it, and a bud under the third two branches from it; according to the six branches that extended from it.'
EXEC add_BibleVerse @BibleId, 102037022, N'Their buds and their branches were of one piece; all of it was one hammered piece of pure gold.'
EXEC add_BibleVerse @BibleId, 102037023, N'He made its seven lamps, its trimmers, and its trays of pure gold.'
EXEC add_BibleVerse @BibleId, 102037024, N'He made the lampstand and all its accessories with seventy-five pounds of pure gold.'
EXEC add_BibleVerse @BibleId, 102037025, N'He made the incense altar of acacia wood. Its length was a foot and a half and its width a foot and a half – a square – and its height was three feet. Its horns were of one piece with it.'
EXEC add_BibleVerse @BibleId, 102037026, N'He overlaid it with pure gold – its top, its four walls, and its horns – and he made a surrounding border of gold for it.'
EXEC add_BibleVerse @BibleId, 102037027, N'He also made two gold rings for it under its border, on its two sides, on opposite sides, as places for poles to carry it with.'
EXEC add_BibleVerse @BibleId, 102037028, N'He made the poles of acacia wood and overlaid them with gold.'
EXEC add_BibleVerse @BibleId, 102037029, N'He made the sacred anointing oil and the pure fragrant incense, the work of a perfumer.'
EXEC add_BibleVerse @BibleId, 102038001, N'He made the altar for the burnt offering of acacia wood seven feet six inches long and seven feet six inches wide – it was square – and its height was four feet six inches.'
EXEC add_BibleVerse @BibleId, 102038002, N'He made its horns on its four corners; its horns were part of it, and he overlaid it with bronze.'
EXEC add_BibleVerse @BibleId, 102038003, N'He made all the utensils of the altar – the pots, the shovels, the tossing bowls, the meat hooks, and the fire pans – he made all its utensils of bronze.'
EXEC add_BibleVerse @BibleId, 102038004, N'He made a grating for the altar, a network of bronze under its ledge, halfway up from the bottom.'
EXEC add_BibleVerse @BibleId, 102038005, N'He cast four rings for the four corners of the bronze grating, to provide places for the poles.'
EXEC add_BibleVerse @BibleId, 102038006, N'He made the poles of acacia wood and overlaid them with bronze.'
EXEC add_BibleVerse @BibleId, 102038007, N'He put the poles into the rings on the sides of the altar, with which to carry it. He made the altar hollow, out of boards.'
EXEC add_BibleVerse @BibleId, 102038008, N'He made the large basin of bronze and its pedestal of bronze from the mirrors of the women who served at the entrance of the tent of meeting.'
EXEC add_BibleVerse @BibleId, 102038009, N'He made the courtyard. For the south side the hangings of the courtyard were of fine twisted linen, one hundred fifty feet long,'
EXEC add_BibleVerse @BibleId, 102038010, N'with their twenty posts and their twenty bronze bases, with the hooks of the posts and their bands of silver.'
EXEC add_BibleVerse @BibleId, 102038011, N'For the north side the hangings were one hundred fifty feet, with their twenty posts and their twenty bronze bases, with the hooks of the posts and their bands of silver.'
EXEC add_BibleVerse @BibleId, 102038012, N'For the west side there were hangings seventy-five feet long, with their ten posts and their ten bases, with the hooks of the posts and their bands of silver.'
EXEC add_BibleVerse @BibleId, 102038013, N'For the east side, toward the sunrise, it was seventy-five feet wide,'
EXEC add_BibleVerse @BibleId, 102038014, N'with hangings on one side of the gate that were twenty-two and a half feet long, with their three posts and their three bases,'
EXEC add_BibleVerse @BibleId, 102038015, N'and for the second side of the gate of the courtyard, just like the other, the hangings were twenty-two and a half feet long, with their three posts and their three bases.'
EXEC add_BibleVerse @BibleId, 102038016, N'All the hangings around the courtyard were of fine twisted linen.'
EXEC add_BibleVerse @BibleId, 102038017, N'The bases for the posts were bronze. The hooks of the posts and their bands were silver, their tops were overlaid with silver, and all the posts of the courtyard had silver bands.'
EXEC add_BibleVerse @BibleId, 102038018, N'The curtain for the gate of the courtyard was of blue, purple, and scarlet yarn and fine twisted linen, the work of an embroiderer. It was thirty feet long, and like the hangings in the courtyard, it was seven and a half feet high,'
EXEC add_BibleVerse @BibleId, 102038019, N'with four posts and their four bronze bases. Their hooks and their bands were silver, and their tops were overlaid with silver.'
EXEC add_BibleVerse @BibleId, 102038020, N'All the tent pegs of the tabernacle and of the courtyard all around were bronze.'
EXEC add_BibleVerse @BibleId, 102038021, N'This is the inventory of the tabernacle, the tabernacle of the testimony, which was counted by the order of Moses, being the work of the Levites under the direction of Ithamar, son of Aaron the priest.'
EXEC add_BibleVerse @BibleId, 102038022, N'Now Bezalel son of Uri, the son of Hur, of the tribe of Judah, made everything that the Lord had commanded Moses;'
EXEC add_BibleVerse @BibleId, 102038023, N'and with him was Oholiab son of Ahisamach, of the tribe of Dan, an artisan, a designer, and an embroiderer in blue, purple, and scarlet yarn and fine linen.'
EXEC add_BibleVerse @BibleId, 102038024, N'All the gold that was used for the work, in all the work of the sanctuary (namely, the gold of the wave offering) was twenty-nine talents and 730 shekels, according to the sanctuary shekel.'
EXEC add_BibleVerse @BibleId, 102038025, N'The silver of those who were numbered of the community was one hundred talents and 1,775 shekels, according to the sanctuary shekel,'
EXEC add_BibleVerse @BibleId, 102038026, N'one beka per person, that is, a half shekel, according to the sanctuary shekel, for everyone who crossed over to those numbered, from twenty years old or older, 603,550 in all.'
EXEC add_BibleVerse @BibleId, 102038027, N'The one hundred talents of silver were used for casting the bases of the sanctuary and the bases of the special curtain – one hundred bases for one hundred talents, one talent per base.'
EXEC add_BibleVerse @BibleId, 102038028, N'From the remaining 1,775 shekels he made hooks for the posts, overlaid their tops, and made bands for them.'
EXEC add_BibleVerse @BibleId, 102038029, N'The bronze of the wave offering was seventy talents and 2,400 shekels.'
EXEC add_BibleVerse @BibleId, 102038030, N'With it he made the bases for the door of the tent of meeting, the bronze altar, the bronze grating for it, and all the utensils of the altar,'
EXEC add_BibleVerse @BibleId, 102038031, N'the bases for the courtyard all around, the bases for the gate of the courtyard, all the tent pegs of the tabernacle, and all the tent pegs of the courtyard all around.'
EXEC add_BibleVerse @BibleId, 102039001, N'From the blue, purple, and scarlet yarn they made woven garments for serving in the sanctuary; they made holy garments that were for Aaron, just as the Lord had commanded Moses.'
EXEC add_BibleVerse @BibleId, 102039002, N'He made the ephod of gold, blue, purple, scarlet, and fine twisted linen.'
EXEC add_BibleVerse @BibleId, 102039003, N'They hammered the gold into thin sheets and cut it into narrow strips to weave them into the blue, purple, and scarlet yarn, and into the fine linen, the work of an artistic designer.'
EXEC add_BibleVerse @BibleId, 102039004, N'They made shoulder pieces for it, attached to two of its corners, so it could be joined together.'
EXEC add_BibleVerse @BibleId, 102039005, N'The artistically woven waistband of the ephod that was on it was like it, of one piece with it, of gold, blue, purple, and scarlet yarn and fine twisted linen, just as the Lord had commanded Moses.'
EXEC add_BibleVerse @BibleId, 102039006, N'They set the onyx stones in gold filigree settings, engraved as with the engravings of a seal with the names of the sons of Israel.'
EXEC add_BibleVerse @BibleId, 102039007, N'He put them on the shoulder pieces of the ephod as stones of memorial for the Israelites, just as the Lord had commanded Moses.'
EXEC add_BibleVerse @BibleId, 102039008, N'He made the breastpiece, the work of an artistic designer, in the same fashion as the ephod, of gold, blue, purple, and scarlet, and fine twisted linen.'
EXEC add_BibleVerse @BibleId, 102039009, N'It was square – they made the breastpiece doubled, nine inches long and nine inches wide when doubled.'
EXEC add_BibleVerse @BibleId, 102039010, N'They set on it four rows of stones: a row with a ruby, a topaz, and a beryl – the first row;'
EXEC add_BibleVerse @BibleId, 102039011, N'and the second row, a turquoise, a sapphire, and an emerald;'
EXEC add_BibleVerse @BibleId, 102039012, N'and the third row, a jacinth, an agate, and an amethyst;'
EXEC add_BibleVerse @BibleId, 102039013, N'and the fourth row, a chrysolite, an onyx, and a jasper. They were enclosed in gold filigree settings.'
EXEC add_BibleVerse @BibleId, 102039014, N'The stones were for the names of the sons of Israel, twelve, corresponding to the number of their names. Each name corresponding to one of the twelve tribes was like the engravings of a seal.'
EXEC add_BibleVerse @BibleId, 102039015, N'They made for the breastpiece braided chains like cords of pure gold,'
EXEC add_BibleVerse @BibleId, 102039016, N'and they made two gold filigree settings and two gold rings, and they attached the two rings to the upper two ends of the breastpiece.'
EXEC add_BibleVerse @BibleId, 102039017, N'They attached the two gold chains to the two rings at the ends of the breastpiece;'
EXEC add_BibleVerse @BibleId, 102039018, N'the other two ends of the two chains they attached to the two settings, and they attached them to the shoulder pieces of the ephod at the front of it.'
EXEC add_BibleVerse @BibleId, 102039019, N'They made two rings of gold and put them on the other two ends of the breastpiece on its edge, which is on the inner side of the ephod.'
EXEC add_BibleVerse @BibleId, 102039020, N'They made two more gold rings and attached them to the bottom of the two shoulder pieces on the front of the ephod, close to the juncture above the waistband of the ephod.'
EXEC add_BibleVerse @BibleId, 102039021, N'They tied the breastpiece by its rings to the rings of the ephod by blue cord, so that it was above the waistband of the ephod, so that the breastpiece would not be loose from the ephod, just as the Lord had commanded Moses.'
EXEC add_BibleVerse @BibleId, 102039022, N'He made the robe of the ephod completely blue, the work of a weaver.'
EXEC add_BibleVerse @BibleId, 102039023, N'There was an opening in the center of the robe, like the opening of a collar, with an edge all around the opening so that it could not be torn.'
EXEC add_BibleVerse @BibleId, 102039024, N'They made pomegranates of blue, purple, and scarlet yarn and twisted linen around the hem of the robe.'
EXEC add_BibleVerse @BibleId, 102039025, N'They made bells of pure gold and attached the bells between the pomegranates around the hem of the robe between the pomegranates.'
EXEC add_BibleVerse @BibleId, 102039026, N'There was a bell and a pomegranate, a bell and a pomegranate, all around the hem of the robe, to be used in ministering, just as the Lord had commanded Moses.'
EXEC add_BibleVerse @BibleId, 102039027, N'They made tunics of fine linen – the work of a weaver, for Aaron and for his sons –'
EXEC add_BibleVerse @BibleId, 102039028, N'and the turban of fine linen, the headbands of fine linen, and the undergarments of fine twisted linen.'
EXEC add_BibleVerse @BibleId, 102039029, N'The sash was of fine twisted linen and blue, purple, and scarlet yarn, the work of an embroiderer, just as the Lord had commanded Moses.'
EXEC add_BibleVerse @BibleId, 102039030, N'They made a plate, the holy diadem, of pure gold and wrote on it an inscription, as on the engravings of a seal, “Holiness to the Lord.”'
EXEC add_BibleVerse @BibleId, 102039031, N'They attached to it a blue cord, to attach it to the turban above, just as the Lord had commanded Moses.'
EXEC add_BibleVerse @BibleId, 102039032, N'So all the work of the tabernacle, the tent of meeting, was completed, and the Israelites did according to all that the Lord had commanded Moses – they did it exactly so.'
EXEC add_BibleVerse @BibleId, 102039033, N'They brought the tabernacle to Moses, the tent and all its furnishings, clasps, frames, bars, posts, and bases;'
EXEC add_BibleVerse @BibleId, 102039034, N'and the coverings of ram skins dyed red, the covering of fine leather, and the protecting curtain;'
EXEC add_BibleVerse @BibleId, 102039035, N'the ark of the testimony and its poles, and the atonement lid;'
EXEC add_BibleVerse @BibleId, 102039036, N'the table, all its utensils, and the Bread of the Presence;'
EXEC add_BibleVerse @BibleId, 102039037, N'the pure lampstand, its lamps, with the lamps set in order, and all its accessories, and oil for the light;'
EXEC add_BibleVerse @BibleId, 102039038, N'and the gold altar, and the anointing oil, and the fragrant incense; and the curtain for the entrance to the tent;'
EXEC add_BibleVerse @BibleId, 102039039, N'the bronze altar and its bronze grating, its poles, and all its utensils; the large basin with its pedestal;'
EXEC add_BibleVerse @BibleId, 102039040, N'the hangings of the courtyard, its posts and its bases, and the curtain for the gateway of the courtyard, its ropes and its tent pegs, and all the furnishings for the service of the tabernacle, for the tent of meeting;'
EXEC add_BibleVerse @BibleId, 102039041, N'the woven garments for serving in the sanctuary, the holy garments for Aaron the priest, and the garments for his sons to minister as priests.'
EXEC add_BibleVerse @BibleId, 102039042, N'The Israelites did all the work according to all that the Lord had commanded Moses.'
EXEC add_BibleVerse @BibleId, 102039043, N'Moses inspected all the work – and they had done it just as the Lord had commanded – they had done it exactly – and Moses blessed them.'
EXEC add_BibleVerse @BibleId, 102040001, N'Then the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 102040002, N'“On the first day of the first month you are to set up the tabernacle, the tent of meeting.'
EXEC add_BibleVerse @BibleId, 102040003, N'You are to place the ark of the testimony in it and shield the ark with the special curtain.'
EXEC add_BibleVerse @BibleId, 102040004, N'You are to bring in the table and set out the things that belong on it; then you are to bring in the lampstand and set up its lamps.'
EXEC add_BibleVerse @BibleId, 102040005, N'You are to put the gold altar for incense in front of the ark of the testimony and put the curtain at the entrance to the tabernacle.'
EXEC add_BibleVerse @BibleId, 102040006, N'You are to put the altar for the burnt offering in front of the entrance to the tabernacle, the tent of meeting.'
EXEC add_BibleVerse @BibleId, 102040007, N'You are to put the large basin between the tent of meeting and the altar and put water in it.'
EXEC add_BibleVerse @BibleId, 102040008, N'You are to set up the courtyard around it and put the curtain at the gate of the courtyard.'
EXEC add_BibleVerse @BibleId, 102040009, N'And take the anointing oil, and anoint the tabernacle and all that is in it, and sanctify it and all its furnishings, and it will be holy.'
EXEC add_BibleVerse @BibleId, 102040010, N'Then you are to anoint the altar for the burnt offering with all its utensils; you are to sanctify the altar, and it will be the most holy altar.'
EXEC add_BibleVerse @BibleId, 102040011, N'You must also anoint the large basin and its pedestal, and you are to sanctify it.'
EXEC add_BibleVerse @BibleId, 102040012, N'“You are to bring Aaron and his sons to the entrance of the tent of meeting and wash them with water.'
EXEC add_BibleVerse @BibleId, 102040013, N'Then you are to clothe Aaron with the holy garments and anoint him and sanctify him so that he may minister as my priest.'
EXEC add_BibleVerse @BibleId, 102040014, N'You are to bring his sons and clothe them with tunics'
EXEC add_BibleVerse @BibleId, 102040015, N'and anoint them just as you anointed their father, so that they may minister as my priests; their anointing will make them a priesthood that will continue throughout their generations.”'
EXEC add_BibleVerse @BibleId, 102040016, N'This is what Moses did, according to all the Lord had commanded him – so he did.'
EXEC add_BibleVerse @BibleId, 102040017, N'So the tabernacle was set up on the first day of the first month, in the second year.'
EXEC add_BibleVerse @BibleId, 102040018, N'When Moses set up the tabernacle and put its bases in place, he set up its frames, attached its bars, and set up its posts.'
EXEC add_BibleVerse @BibleId, 102040019, N'Then he spread the tent over the tabernacle and put the covering of the tent over it, as the Lord had commanded Moses.'
EXEC add_BibleVerse @BibleId, 102040020, N'He took the testimony and put it in the ark, attached the poles to the ark, and then put the atonement lid on the ark.'
EXEC add_BibleVerse @BibleId, 102040021, N'And he brought the ark into the tabernacle, hung the protecting curtain, and shielded the ark of the testimony from view, just as the Lord had commanded Moses.'
EXEC add_BibleVerse @BibleId, 102040022, N'And he put the table in the tent of meeting, on the north side of the tabernacle, outside the curtain.'
EXEC add_BibleVerse @BibleId, 102040023, N'And he set the bread in order on it before the Lord, just as the Lord had commanded Moses.'
EXEC add_BibleVerse @BibleId, 102040024, N'And he put the lampstand in the tent of meeting opposite the table, on the south side of the tabernacle.'
EXEC add_BibleVerse @BibleId, 102040025, N'Then he set up the lamps before the Lord, just as the Lord had commanded Moses.'
EXEC add_BibleVerse @BibleId, 102040026, N'And he put the gold altar in the tent of meeting in front of the curtain,'
EXEC add_BibleVerse @BibleId, 102040027, N'and he burned fragrant incense on it, just as the Lord had commanded Moses.'
EXEC add_BibleVerse @BibleId, 102040028, N'Then he put the curtain at the entrance to the tabernacle.'
EXEC add_BibleVerse @BibleId, 102040029, N'He also put the altar for the burnt offering by the entrance to the tabernacle, the tent of meeting, and offered on it the burnt offering and the meal offering, just as the Lord had commanded Moses.'
EXEC add_BibleVerse @BibleId, 102040030, N'Then he put the large basin between the tent of meeting and the altar and put water in it for washing.'
EXEC add_BibleVerse @BibleId, 102040031, N'Moses and Aaron and his sons would wash their hands and their feet from it.'
EXEC add_BibleVerse @BibleId, 102040032, N'Whenever they entered the tent of meeting, and whenever they approached the altar, they would wash, just as the Lord had commanded Moses.'
EXEC add_BibleVerse @BibleId, 102040033, N'And he set up the courtyard around the tabernacle and the altar, and put the curtain at the gate of the courtyard. So Moses finished the work.'
EXEC add_BibleVerse @BibleId, 102040034, N'Then the cloud covered the tent of meeting, and the glory of the Lord filled the tabernacle.'
EXEC add_BibleVerse @BibleId, 102040035, N'Moses was not able to enter the tent of meeting because the cloud settled on it and the glory of the Lord filled the tabernacle.'
EXEC add_BibleVerse @BibleId, 102040036, N'But when the cloud was lifted up from the tabernacle, the Israelites would set out on all their journeys;'
EXEC add_BibleVerse @BibleId, 102040037, N'but if the cloud was not lifted up, then they would not journey further until the day it was lifted up.'
EXEC add_BibleVerse @BibleId, 102040038, N'For the cloud of the Lord was on the tabernacle by day, but fire would be on it at night, in plain view of all the house of Israel, throughout all their journeys.'
EXEC add_BibleVerse @BibleId, 103001001, N'Then the Lord called to Moses and spoke to him from the Meeting Tent:'
EXEC add_BibleVerse @BibleId, 103001002, N'“Speak to the Israelites and tell them, ‘When someone among you presents an offering to the Lord, you must present your offering from the domesticated animals, either from the herd or from the flock.'
EXEC add_BibleVerse @BibleId, 103001003, N'“‘If his offering is a burnt offering from the herd he must present it as a flawless male; he must present it at the entrance of the Meeting Tent for its acceptance before the Lord.'
EXEC add_BibleVerse @BibleId, 103001004, N'He must lay his hand on the head of the burnt offering, and it will be accepted for him to make atonement on his behalf.'
EXEC add_BibleVerse @BibleId, 103001005, N'Then the one presenting the offering must slaughter the bull before the Lord, and the sons of Aaron, the priests, must present the blood and splash the blood against the sides of the altar which is at the entrance of the Meeting Tent.'
EXEC add_BibleVerse @BibleId, 103001006, N'Next, the one presenting the offering must skin the burnt offering and cut it into parts,'
EXEC add_BibleVerse @BibleId, 103001007, N'and the sons of Aaron, the priest, must put fire on the altar and arrange wood on the fire.'
EXEC add_BibleVerse @BibleId, 103001008, N'Then the sons of Aaron, the priests, must arrange the parts with the head and the suet on the wood that is in the fire on the altar.'
EXEC add_BibleVerse @BibleId, 103001009, N'Finally, the one presenting the offering must wash its entrails and its legs in water and the priest must offer all of it up in smoke on the altar – it is a burnt offering, a gift of a soothing aroma to the Lord.'
EXEC add_BibleVerse @BibleId, 103001010, N'“‘If his offering is from the flock for a burnt offering – from the sheep or the goats – he must present a flawless male,'
EXEC add_BibleVerse @BibleId, 103001011, N'and must slaughter it on the north side of the altar before the Lord, and the sons of Aaron, the priests, will splash its blood against the altar’s sides.'
EXEC add_BibleVerse @BibleId, 103001012, N'Next, the one presenting the offering must cut it into parts, with its head and its suet, and the priest must arrange them on the wood which is in the fire, on the altar.'
EXEC add_BibleVerse @BibleId, 103001013, N'Then the one presenting the offering must wash the entrails and the legs in water, and the priest must present all of it and offer it up in smoke on the altar – it is a burnt offering, a gift of a soothing aroma to the Lord.'
EXEC add_BibleVerse @BibleId, 103001014, N'“‘If his offering to the Lord is a burnt offering from the birds, he must present his offering from the turtledoves or from the young pigeons.'
EXEC add_BibleVerse @BibleId, 103001015, N'The priest must present it at the altar, pinch off its head and offer the head up in smoke on the altar, and its blood must be drained out against the side of the altar.'
EXEC add_BibleVerse @BibleId, 103001016, N'Then the priest must remove its entrails by cutting off its tail feathers, and throw them to the east side of the altar into the place of fatty ashes,'
EXEC add_BibleVerse @BibleId, 103001017, N'and tear it open by its wings without dividing it into two parts. Finally, the priest must offer it up in smoke on the altar on the wood which is in the fire – it is a burnt offering, a gift of a soothing aroma to the Lord.'
EXEC add_BibleVerse @BibleId, 103002001, N'“‘When a person presents a grain offering to the Lord, his offering must consist of choice wheat flour, and he must pour olive oil on it and put frankincense on it.'
EXEC add_BibleVerse @BibleId, 103002002, N'Then he must bring it to the sons of Aaron, the priests, and the priest must scoop out from there a handful of its choice wheat flour and some of its olive oil in addition to all of its frankincense, and the priest must offer its memorial portion up in smoke on the altar – it is a gift of a soothing aroma to the Lord.'
EXEC add_BibleVerse @BibleId, 103002003, N'The remainder of the grain offering belongs to Aaron and to his sons – it is most holy from the gifts of the Lord.'
EXEC add_BibleVerse @BibleId, 103002004, N'“‘When you present an offering of grain baked in an oven, it must be made of choice wheat flour baked into unleavened loaves mixed with olive oil or unleavened wafers smeared with olive oil.'
EXEC add_BibleVerse @BibleId, 103002005, N'If your offering is a grain offering made on the griddle, it must be choice wheat flour mixed with olive oil, unleavened.'
EXEC add_BibleVerse @BibleId, 103002006, N'Crumble it in pieces and pour olive oil on it – it is a grain offering.'
EXEC add_BibleVerse @BibleId, 103002007, N'If your offering is a grain offering made in a pan, it must be made of choice wheat flour deep fried in olive oil.'
EXEC add_BibleVerse @BibleId, 103002008, N'“‘You must bring the grain offering that must be made from these to the Lord. Present it to the priest, and he will bring it to the altar.'
EXEC add_BibleVerse @BibleId, 103002009, N'Then the priest must take up from the grain offering its memorial portion and offer it up in smoke on the altar – it is a gift of a soothing aroma to the Lord.'
EXEC add_BibleVerse @BibleId, 103002010, N'The remainder of the grain offering belongs to Aaron and to his sons – it is most holy from the gifts of the Lord.'
EXEC add_BibleVerse @BibleId, 103002011, N'“‘No grain offering which you present to the Lord can be made with yeast, for you must not offer up in smoke any yeast or honey as a gift to the Lord.'
EXEC add_BibleVerse @BibleId, 103002012, N'You can present them to the Lord as an offering of first fruit, but they must not go up to the altar for a soothing aroma.'
EXEC add_BibleVerse @BibleId, 103002013, N'Moreover, you must season every one of your grain offerings with salt; you must not allow the salt of the covenant of your God to be missing from your grain offering – on every one of your grain offerings you must present salt.'
EXEC add_BibleVerse @BibleId, 103002014, N'“‘If you present a grain offering of first ripe grain to the Lord, you must present your grain offering of first ripe grain as soft kernels roasted in fire – crushed bits of fresh grain.'
EXEC add_BibleVerse @BibleId, 103002015, N'And you must put olive oil on it and set frankincense on it – it is a grain offering.'
EXEC add_BibleVerse @BibleId, 103002016, N'Then the priest must offer its memorial portion up in smoke – some of its crushed bits, some of its olive oil, in addition to all of its frankincense – it is a gift to the Lord.'
EXEC add_BibleVerse @BibleId, 103003001, N'“‘Now if his offering is a peace offering sacrifice, if he presents an offering from the herd, he must present before the Lord a flawless male or a female.'
EXEC add_BibleVerse @BibleId, 103003002, N'He must lay his hand on the head of his offering and slaughter it at the entrance of the Meeting Tent, and the sons of Aaron, the priests, must splash the blood against the altar’s sides.'
EXEC add_BibleVerse @BibleId, 103003003, N'Then the one presenting the offering must present a gift to the Lord from the peace offering sacrifice: He must remove the fat that covers the entrails and all the fat that surrounds the entrails,'
EXEC add_BibleVerse @BibleId, 103003004, N'the two kidneys with the fat on their sinews, and the protruding lobe on the liver (which he is to remove along with the kidneys).'
EXEC add_BibleVerse @BibleId, 103003005, N'Then the sons of Aaron must offer it up in smoke on the altar atop the burnt offering that is on the wood in the fire as a gift of a soothing aroma to the Lord.'
EXEC add_BibleVerse @BibleId, 103003006, N'“‘If his offering for a peace offering sacrifice to the Lord is from the flock, he must present a flawless male or female.'
EXEC add_BibleVerse @BibleId, 103003007, N'If he presents a sheep as his offering, he must present it before the Lord.'
EXEC add_BibleVerse @BibleId, 103003008, N'He must lay his hand on the head of his offering and slaughter it before the Meeting Tent, and the sons of Aaron must splash its blood against the altar’s sides.'
EXEC add_BibleVerse @BibleId, 103003009, N'Then he must present a gift to the Lord from the peace offering sacrifice: He must remove all the fatty tail up to the end of the spine, the fat covering the entrails, and all the fat on the entrails,'
EXEC add_BibleVerse @BibleId, 103003010, N'the two kidneys with the fat on their sinews, and the protruding lobe on the liver (which he is to remove along with the kidneys).'
EXEC add_BibleVerse @BibleId, 103003011, N'Then the priest must offer it up in smoke on the altar as a food gift to the Lord.'
EXEC add_BibleVerse @BibleId, 103003012, N'“‘If his offering is a goat he must present it before the Lord,'
EXEC add_BibleVerse @BibleId, 103003013, N'lay his hand on its head, and slaughter it before the Meeting Tent, and the sons of Aaron must splash its blood against the altar’s sides.'
EXEC add_BibleVerse @BibleId, 103003014, N'Then he must present from it his offering as a gift to the Lord: the fat which covers the entrails and all the fat on the entrails,'
EXEC add_BibleVerse @BibleId, 103003015, N'the two kidneys with the fat on their sinews, and the protruding lobe on the liver (which he is to remove along with the kidneys).'
EXEC add_BibleVerse @BibleId, 103003016, N'Then the priest must offer them up in smoke on the altar as a food gift for a soothing aroma – all the fat belongs to the Lord.'
EXEC add_BibleVerse @BibleId, 103003017, N'This is a perpetual statute throughout your generations in all the places where you live: You must never eat any fat or any blood.’”'
EXEC add_BibleVerse @BibleId, 103004001, N'Then the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103004002, N'“Tell the Israelites, ‘When a person sins by straying unintentionally from any of the Lord’s commandments which must not be violated, and violates any one of them –'
EXEC add_BibleVerse @BibleId, 103004003, N'“‘If the high priest sins so that the people are guilty, on account of the sin he has committed he must present a flawless young bull to the Lord for a sin offering.'
EXEC add_BibleVerse @BibleId, 103004004, N'He must bring the bull to the entrance of the Meeting Tent before the Lord, lay his hand on the head of the bull, and slaughter the bull before the Lord.'
EXEC add_BibleVerse @BibleId, 103004005, N'Then that high priest must take some of the blood of the bull and bring it to the Meeting Tent.'
EXEC add_BibleVerse @BibleId, 103004006, N'The priest must dip his finger in the blood and sprinkle some of it seven times before the Lord toward the front of the veil-canopy of the sanctuary.'
EXEC add_BibleVerse @BibleId, 103004007, N'The priest must put some of the blood on the horns of the altar of fragrant incense that is before the Lord in the Meeting Tent, and all the rest of the bull’s blood he must pour out at the base of the altar of burnt offering that is at the entrance of the Meeting Tent.'
EXEC add_BibleVerse @BibleId, 103004008, N'“‘Then he must take up all the fat from the sin offering bull: the fat covering the entrails and all the fat surrounding the entrails,'
EXEC add_BibleVerse @BibleId, 103004009, N'the two kidneys with the fat on their sinews, and the protruding lobe on the liver (which he is to remove along with the kidneys)'
EXEC add_BibleVerse @BibleId, 103004010, N'– just as it is taken from the ox of the peace offering sacrifice – and the priest must offer them up in smoke on the altar of burnt offering.'
EXEC add_BibleVerse @BibleId, 103004011, N'But the hide of the bull, all its flesh along with its head and its legs, its entrails, and its dung –'
EXEC add_BibleVerse @BibleId, 103004012, N'all the rest of the bull – he must bring outside the camp to a ceremonially clean place, to the fatty ash pile, and he must burn it on a wood fire; it must be burned on the fatty ash pile.'
EXEC add_BibleVerse @BibleId, 103004013, N'“‘If the whole congregation of Israel strays unintentionally and the matter is not noticed by the assembly, and they violate one of the Lord’s commandments, which must not be violated, so they become guilty,'
EXEC add_BibleVerse @BibleId, 103004014, N'the assembly must present a young bull for a sin offering when the sin they have committed becomes known. They must bring it before the Meeting Tent,'
EXEC add_BibleVerse @BibleId, 103004015, N'the elders of the congregation must lay their hands on the head of the bull before the Lord, and someone must slaughter the bull before the Lord.'
EXEC add_BibleVerse @BibleId, 103004016, N'Then the high priest must bring some of the blood of the bull to the Meeting Tent,'
EXEC add_BibleVerse @BibleId, 103004017, N'and that priest must dip his finger in the blood and sprinkle some of the blood seven times before the Lord toward the front of the veil-canopy.'
EXEC add_BibleVerse @BibleId, 103004018, N'He must put some of the blood on the horns of the altar which is before the Lord in the Meeting Tent, and all the rest of the blood he must pour out at the base of the altar of burnt offering that is at the entrance of the Meeting Tent.'
EXEC add_BibleVerse @BibleId, 103004019, N'“‘Then the priest must take all its fat and offer the fat up in smoke on the altar.'
EXEC add_BibleVerse @BibleId, 103004020, N'He must do with the rest of the bull just as he did with the bull of the sin offering; this is what he must do with it. So the priest will make atonement on their behalf and they will be forgiven.'
EXEC add_BibleVerse @BibleId, 103004021, N'He must bring the rest of the bull outside the camp and burn it just as he burned the first bull – it is the sin offering of the assembly.'
EXEC add_BibleVerse @BibleId, 103004022, N'“‘Whenever a leader, by straying unintentionally, sins and violates one of the commandments of the Lord his God which must not be violated, and he pleads guilty,'
EXEC add_BibleVerse @BibleId, 103004023, N'or his sin that he committed is made known to him, he must bring a flawless male goat as his offering.'
EXEC add_BibleVerse @BibleId, 103004024, N'He must lay his hand on the head of the male goat and slaughter it in the place where the burnt offering is slaughtered before the Lord – it is a sin offering.'
EXEC add_BibleVerse @BibleId, 103004025, N'Then the priest must take some of the blood of the sin offering with his finger and put it on the horns of the altar of burnt offering, and he must pour out the rest of its blood at the base of the altar of burnt offering.'
EXEC add_BibleVerse @BibleId, 103004026, N'Then the priest must offer all of its fat up in smoke on the altar like the fat of the peace offering sacrifice. So the priest will make atonement on his behalf for his sin and he will be forgiven.'
EXEC add_BibleVerse @BibleId, 103004027, N'“‘If an ordinary individual sins by straying unintentionally when he violates one of the Lord’s commandments which must not be violated, and he pleads guilty'
EXEC add_BibleVerse @BibleId, 103004028, N'or his sin that he committed is made known to him, he must bring a flawless female goat as his offering for the sin that he committed.'
EXEC add_BibleVerse @BibleId, 103004029, N'He must lay his hand on the head of the sin offering and slaughter the sin offering in the place where the burnt offering is slaughtered.'
EXEC add_BibleVerse @BibleId, 103004030, N'Then the priest must take some of its blood with his finger and put it on the horns of the altar of burnt offering, and he must pour out all the rest of its blood at the base of the altar.'
EXEC add_BibleVerse @BibleId, 103004031, N'Then he must remove all of its fat (just as fat was removed from the peace offering sacrifice) and the priest must offer it up in smoke on the altar for a soothing aroma to the Lord. So the priest will make atonement on his behalf and he will be forgiven.'
EXEC add_BibleVerse @BibleId, 103004032, N'“‘But if he brings a sheep as his offering, for a sin offering, he must bring a flawless female.'
EXEC add_BibleVerse @BibleId, 103004033, N'He must lay his hand on the head of the sin offering and slaughter it for a sin offering in the place where the burnt offering is slaughtered.'
EXEC add_BibleVerse @BibleId, 103004034, N'Then the priest must take some of the blood of the sin offering with his finger and put it on the horns of the altar of burnt offering, and he must pour out all the rest of its blood at the base of the altar.'
EXEC add_BibleVerse @BibleId, 103004035, N'Then the one who brought the offering must remove all its fat (just as the fat of the sheep is removed from the peace offering sacrifice) and the priest must offer them up in smoke on the altar on top of the other gifts of the Lord. So the priest will make atonement on his behalf for his sin which he has committed and he will be forgiven.'
EXEC add_BibleVerse @BibleId, 103005001, N'“‘When a person sins in that he hears a public curse against one who fails to testify and he is a witness (he either saw or knew what had happened ) and he does not make it known, then he will bear his punishment for iniquity.'
EXEC add_BibleVerse @BibleId, 103005002, N'Or when there is a person who touches anything ceremonially unclean, whether the carcass of an unclean wild animal, or the carcass of an unclean domesticated animal, or the carcass of an unclean creeping thing, even if he did not realize it, but he himself has become unclean and is guilty;'
EXEC add_BibleVerse @BibleId, 103005003, N'or when he touches human uncleanness with regard to anything by which he can become unclean, even if he did not realize it, but he himself has later come to know it and is guilty;'
EXEC add_BibleVerse @BibleId, 103005004, N'or when a person swears an oath, speaking thoughtlessly with his lips, whether to do evil or to do good, with regard to anything which the individual might speak thoughtlessly in an oath, even if he did not realize it, but he himself has later come to know it and is guilty with regard to one of these oaths –'
EXEC add_BibleVerse @BibleId, 103005005, N'when an individual becomes guilty with regard to one of these things he must confess how he has sinned,'
EXEC add_BibleVerse @BibleId, 103005006, N'and he must bring his penalty for guilt to the Lord for his sin that he has committed, a female from the flock, whether a female sheep or a female goat, for a sin offering. So the priest will make atonement on his behalf for his sin.'
EXEC add_BibleVerse @BibleId, 103005007, N'“‘If he cannot afford an animal from the flock, he must bring his penalty for guilt for his sin that he has committed, two turtledoves or two young pigeons, to the Lord, one for a sin offering and one for a burnt offering.'
EXEC add_BibleVerse @BibleId, 103005008, N'He must bring them to the priest and present first the one that is for a sin offering. The priest must pinch its head at the nape of its neck, but must not sever the head from the body.'
EXEC add_BibleVerse @BibleId, 103005009, N'Then he must sprinkle some of the blood of the sin offering on the wall of the altar, and the remainder of the blood must be squeezed out at the base of the altar – it is a sin offering.'
EXEC add_BibleVerse @BibleId, 103005010, N'The second bird he must make a burnt offering according to the standard regulation. So the priest will make atonement on behalf of this person for his sin which he has committed, and he will be forgiven.'
EXEC add_BibleVerse @BibleId, 103005011, N'“‘If he cannot afford two turtledoves or two young pigeons, he must bring as his offering for his sin which he has committed a tenth of an ephah of choice wheat flour for a sin offering. He must not place olive oil on it and he must not put frankincense on it, because it is a sin offering.'
EXEC add_BibleVerse @BibleId, 103005012, N'He must bring it to the priest and the priest must scoop out from it a handful as its memorial portion and offer it up in smoke on the altar on top of the other gifts of the Lord – it is a sin offering.'
EXEC add_BibleVerse @BibleId, 103005013, N'So the priest will make atonement on his behalf for his sin which he has committed by doing one of these things, and he will be forgiven. The remainder of the offering will belong to the priest like the grain offering.’”'
EXEC add_BibleVerse @BibleId, 103005014, N'Then the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103005015, N'“When a person commits a trespass and sins by straying unintentionally from the regulations about the Lord’s holy things, then he must bring his penalty for guilt to the Lord, a flawless ram from the flock, convertible into silver shekels according to the standard of the sanctuary shekel, for a guilt offering.'
EXEC add_BibleVerse @BibleId, 103005016, N'And whatever holy thing he violated he must restore and must add one fifth to it and give it to the priest. So the priest will make atonement on his behalf with the guilt offering ram and he will be forgiven.”'
EXEC add_BibleVerse @BibleId, 103005017, N'“If a person sins and violates any of the Lord’s commandments which must not be violated (although he did not know it at the time, but later realizes he is guilty), then he will bear his punishment for iniquity'
EXEC add_BibleVerse @BibleId, 103005018, N'and must bring a flawless ram from the flock, convertible into silver shekels, for a guilt offering to the priest. So the priest will make atonement on his behalf for his error which he committed (although he himself had not known it) and he will be forgiven.'
EXEC add_BibleVerse @BibleId, 103005019, N'It is a guilt offering; he was surely guilty before the Lord.”'
EXEC add_BibleVerse @BibleId, 103006001, N'Then the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103006002, N'“When a person sins and commits a trespass against the Lord by deceiving his fellow citizen in regard to something held in trust, or a pledge, or something stolen, or by extorting something from his fellow citizen,'
EXEC add_BibleVerse @BibleId, 103006003, N'or has found something lost and denies it and swears falsely concerning any one of the things that someone might do to sin –'
EXEC add_BibleVerse @BibleId, 103006004, N'when it happens that he sins and he is found guilty, then he must return whatever he had stolen, or whatever he had extorted, or the thing that he had held in trust, or the lost thing that he had found,'
EXEC add_BibleVerse @BibleId, 103006005, N'or anything about which he swears falsely. He must restore it in full and add one fifth to it; he must give it to its owner when he is found guilty.'
EXEC add_BibleVerse @BibleId, 103006006, N'Then he must bring his guilt offering to the Lord, a flawless ram from the flock, convertible into silver shekels, for a guilt offering to the priest.'
EXEC add_BibleVerse @BibleId, 103006007, N'So the priest will make atonement on his behalf before the Lord and he will be forgiven for whatever he has done to become guilty.”'
EXEC add_BibleVerse @BibleId, 103006008, N'Then the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103006009, N'“Command Aaron and his sons, ‘This is the law of the burnt offering. The burnt offering is to remain on the hearth on the altar all night until morning, and the fire of the altar must be kept burning on it.'
EXEC add_BibleVerse @BibleId, 103006010, N'Then the priest must put on his linen robe and must put linen leggings over his bare flesh, and he must take up the fatty ashes of the burnt offering that the fire consumed on the altar, and he must place them beside the altar.'
EXEC add_BibleVerse @BibleId, 103006011, N'Then he must take off his clothes and put on other clothes, and he must bring the fatty ashes outside the camp to a ceremonially clean place,'
EXEC add_BibleVerse @BibleId, 103006012, N'but the fire which is on the altar must be kept burning on it. It must not be extinguished. So the priest must kindle wood on it morning by morning, and he must arrange the burnt offering on it and offer the fat of the peace offering up in smoke on it.'
EXEC add_BibleVerse @BibleId, 103006013, N'A continual fire must be kept burning on the altar. It must not be extinguished.'
EXEC add_BibleVerse @BibleId, 103006014, N'“‘This is the law of the grain offering. The sons of Aaron are to present it before the Lord in front of the altar,'
EXEC add_BibleVerse @BibleId, 103006015, N'and the priest must take up with his hand some of the choice wheat flour of the grain offering and some of its olive oil, and all of the frankincense that is on the grain offering, and he must offer its memorial portion up in smoke on the altar as a soothing aroma to the Lord.'
EXEC add_BibleVerse @BibleId, 103006016, N'Aaron and his sons are to eat what is left over from it. It must be eaten unleavened in a holy place; they are to eat it in the courtyard of the Meeting Tent.'
EXEC add_BibleVerse @BibleId, 103006017, N'It must not be baked with yeast. I have given it as their portion from my gifts. It is most holy, like the sin offering and the guilt offering.'
EXEC add_BibleVerse @BibleId, 103006018, N'Every male among the sons of Aaron may eat it. It is a perpetual allotted portion throughout your generations from the gifts of the Lord. Anyone who touches these gifts must be holy.’”'
EXEC add_BibleVerse @BibleId, 103006019, N'Then the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103006020, N'“This is the offering of Aaron and his sons which they must present to the Lord on the day when he is anointed: a tenth of an ephah of choice wheat flour as a continual grain offering, half of it in the morning and half of it in the evening.'
EXEC add_BibleVerse @BibleId, 103006021, N'It must be made with olive oil on a griddle and you must bring it well soaked, so you must present a grain offering of broken pieces as a soothing aroma to the Lord.'
EXEC add_BibleVerse @BibleId, 103006022, N'The high priest who succeeds him from among his sons must do it. It is a perpetual statute; it must be offered up in smoke as a whole offering to the Lord.'
EXEC add_BibleVerse @BibleId, 103006023, N'Every grain offering of a priest must be a whole offering; it must not be eaten.”'
EXEC add_BibleVerse @BibleId, 103006024, N'Then the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103006025, N'“Tell Aaron and his sons, ‘This is the law of the sin offering. In the place where the burnt offering is slaughtered the sin offering must be slaughtered before the Lord. It is most holy.'
EXEC add_BibleVerse @BibleId, 103006026, N'The priest who offers it for sin is to eat it. It must be eaten in a holy place, in the court of the Meeting Tent.'
EXEC add_BibleVerse @BibleId, 103006027, N'Anyone who touches its meat must be holy, and whoever spatters some of its blood on a garment, you must wash whatever he spatters it on in a holy place.'
EXEC add_BibleVerse @BibleId, 103006028, N'Any clay vessel it is boiled in must be broken, and if it was boiled in a bronze vessel, then that vessel must be rubbed out and rinsed in water.'
EXEC add_BibleVerse @BibleId, 103006029, N'Any male among the priests may eat it. It is most holy.'
EXEC add_BibleVerse @BibleId, 103006030, N'But any sin offering from which some of its blood is brought into the Meeting Tent to make atonement in the sanctuary must not be eaten. It must be burned up in the fire.'
EXEC add_BibleVerse @BibleId, 103007001, N'“‘This is the law of the guilt offering. It is most holy.'
EXEC add_BibleVerse @BibleId, 103007002, N'In the place where they slaughter the burnt offering they must slaughter the guilt offering, and the officiating priest must splash the blood against the altar’s sides.'
EXEC add_BibleVerse @BibleId, 103007003, N'Then the one making the offering must present all its fat: the fatty tail, the fat covering the entrails,'
EXEC add_BibleVerse @BibleId, 103007004, N'the two kidneys and the fat on their sinews, and the protruding lobe on the liver (which he must remove along with the kidneys).'
EXEC add_BibleVerse @BibleId, 103007005, N'Then the priest must offer them up in smoke on the altar as a gift to the Lord. It is a guilt offering.'
EXEC add_BibleVerse @BibleId, 103007006, N'Any male among the priests may eat it. It must be eaten in a holy place. It is most holy.'
EXEC add_BibleVerse @BibleId, 103007007, N'The law is the same for the sin offering and the guilt offering; it belongs to the priest who makes atonement with it.'
EXEC add_BibleVerse @BibleId, 103007008, N'“‘As for the priest who presents someone’s burnt offering, the hide of that burnt offering which he presented belongs to him.'
EXEC add_BibleVerse @BibleId, 103007009, N'Every grain offering which is baked in the oven or made in the pan or on the griddle belongs to the priest who presented it.'
EXEC add_BibleVerse @BibleId, 103007010, N'Every grain offering, whether mixed with olive oil or dry, belongs to all the sons of Aaron, each one alike.'
EXEC add_BibleVerse @BibleId, 103007011, N'“‘This is the law of the peace offering sacrifice which he is to present to the Lord.'
EXEC add_BibleVerse @BibleId, 103007012, N'If he presents it on account of thanksgiving, along with the thank offering sacrifice he must present unleavened loaves mixed with olive oil, unleavened wafers smeared with olive oil, and well soaked ring-shaped loaves made of choice wheat flour mixed with olive oil.'
EXEC add_BibleVerse @BibleId, 103007013, N'He must present this grain offering in addition to ring-shaped loaves of leavened bread which regularly accompany the sacrifice of his thanksgiving peace offering.'
EXEC add_BibleVerse @BibleId, 103007014, N'He must present one of each kind of grain offering as a contribution offering to the Lord; it belongs to the priest who splashes the blood of the peace offering.'
EXEC add_BibleVerse @BibleId, 103007015, N'The meat of his thanksgiving peace offering must be eaten on the day of his offering; he must not set any of it aside until morning.'
EXEC add_BibleVerse @BibleId, 103007016, N'“‘If his offering is a votive or freewill sacrifice, it may be eaten on the day he presents his sacrifice, and also the leftovers from it may be eaten on the next day,'
EXEC add_BibleVerse @BibleId, 103007017, N'but the leftovers from the meat of the sacrifice must be burned up in the fire on the third day.'
EXEC add_BibleVerse @BibleId, 103007018, N'If some of the meat of his peace offering sacrifice is ever eaten on the third day it will not be accepted; it will not be accounted to the one who presented it, since it is spoiled, and the person who eats from it will bear his punishment for iniquity.'
EXEC add_BibleVerse @BibleId, 103007019, N'The meat which touches anything ceremonially unclean must not be eaten; it must be burned up in the fire. As for ceremonially clean meat, everyone who is ceremonially clean may eat the meat.'
EXEC add_BibleVerse @BibleId, 103007020, N'The person who eats meat from the peace offering sacrifice which belongs to the Lord while his uncleanness persists will be cut off from his people.'
EXEC add_BibleVerse @BibleId, 103007021, N'When a person touches anything unclean (whether human uncleanness, or an unclean animal, or an unclean detestable creature) and eats some of the meat of the peace offering sacrifice which belongs to the Lord, that person will be cut off from his people.’”'
EXEC add_BibleVerse @BibleId, 103007022, N'Then the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103007023, N'“Tell the Israelites, ‘You must not eat any fat of an ox, sheep, or goat.'
EXEC add_BibleVerse @BibleId, 103007024, N'Moreover, the fat of an animal that has died of natural causes and the fat of an animal torn by beasts may be used for any other purpose, but you must certainly never eat it.'
EXEC add_BibleVerse @BibleId, 103007025, N'If anyone eats fat from the animal from which he presents a gift to the Lord, that person will be cut off from his people.'
EXEC add_BibleVerse @BibleId, 103007026, N'And you must not eat any blood of the birds or the domesticated land animals in any of the places where you live.'
EXEC add_BibleVerse @BibleId, 103007027, N'Any person who eats any blood – that person will be cut off from his people.’”'
EXEC add_BibleVerse @BibleId, 103007028, N'Then the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103007029, N'“Tell the Israelites, ‘The one who presents his peace offering sacrifice to the Lord must bring his offering to the Lord from his peace offering sacrifice.'
EXEC add_BibleVerse @BibleId, 103007030, N'With his own hands he must bring the Lord’s gifts. He must bring the fat with the breast to wave the breast as a wave offering before the Lord,'
EXEC add_BibleVerse @BibleId, 103007031, N'and the priest must offer the fat up in smoke on the altar, but the breast will belong to Aaron and his sons.'
EXEC add_BibleVerse @BibleId, 103007032, N'The right thigh you must give as a contribution offering to the priest from your peace offering sacrifices.'
EXEC add_BibleVerse @BibleId, 103007033, N'The one from Aaron’s sons who presents the blood of the peace offering and fat will have the right thigh as his share,'
EXEC add_BibleVerse @BibleId, 103007034, N'for the breast of the wave offering and the thigh of the contribution offering I have taken from the Israelites out of their peace offering sacrifices and have given them to Aaron the priest and to his sons from the people of Israel as a perpetual allotted portion.’”'
EXEC add_BibleVerse @BibleId, 103007035, N'This is the allotment of Aaron and the allotment of his sons from the Lord’s gifts on the day Moses presented them to serve as priests to the Lord.'
EXEC add_BibleVerse @BibleId, 103007036, N'This is what the Lord commanded to give to them from the Israelites on the day Moses anointed them – a perpetual allotted portion throughout their generations.'
EXEC add_BibleVerse @BibleId, 103007037, N'This is the law for the burnt offering, the grain offering, the sin offering, the guilt offering, the ordination offering, and the peace offering sacrifice,'
EXEC add_BibleVerse @BibleId, 103007038, N'which the Lord commanded Moses on Mount Sinai on the day he commanded the Israelites to present their offerings to the Lord in the wilderness of Sinai.'
EXEC add_BibleVerse @BibleId, 103008001, N'Then the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103008002, N'“Take Aaron and his sons with him, and the garments, the anointing oil, the sin offering bull, the two rams, and the basket of unleavened bread,'
EXEC add_BibleVerse @BibleId, 103008003, N'and assemble the whole congregation at the entrance of the Meeting Tent.”'
EXEC add_BibleVerse @BibleId, 103008004, N'So Moses did just as the Lord commanded him, and the congregation assembled at the entrance of the Meeting Tent.'
EXEC add_BibleVerse @BibleId, 103008005, N'Then Moses said to the congregation: “This is what the Lord has commanded to be done.”'
EXEC add_BibleVerse @BibleId, 103008006, N'So Moses brought Aaron and his sons forward and washed them with water.'
EXEC add_BibleVerse @BibleId, 103008007, N'Then he put the tunic on Aaron, wrapped the sash around him, and clothed him with the robe. Next he put the ephod on him and placed on him the decorated band of the ephod, and fastened the ephod closely to him with the band.'
EXEC add_BibleVerse @BibleId, 103008008, N'He then set the breastpiece on him and put the Urim and Thummim into the breastpiece.'
EXEC add_BibleVerse @BibleId, 103008009, N'Finally, he set the turban on his head and attached the gold plate, the holy diadem, to the front of the turban just as the Lord had commanded Moses.'
EXEC add_BibleVerse @BibleId, 103008010, N'Then Moses took the anointing oil and anointed the tabernacle and everything in it, and so consecrated them.'
EXEC add_BibleVerse @BibleId, 103008011, N'Next he sprinkled some of it on the altar seven times and so anointed the altar, all its vessels, and the wash basin and its stand to consecrate them.'
EXEC add_BibleVerse @BibleId, 103008012, N'He then poured some of the anointing oil on the head of Aaron and anointed him to consecrate him.'
EXEC add_BibleVerse @BibleId, 103008013, N'Moses also brought forward Aaron’s sons, clothed them with tunics, wrapped sashes around them, and wrapped headbands on them just as the Lord had commanded Moses.'
EXEC add_BibleVerse @BibleId, 103008014, N'Then he brought near the sin offering bull and Aaron and his sons laid their hands on the head of the sin offering bull,'
EXEC add_BibleVerse @BibleId, 103008015, N'and he slaughtered it. Moses then took the blood and put it all around on the horns of the altar with his finger and decontaminated the altar, and he poured out the rest of the blood at the base of the altar and so consecrated it to make atonement on it.'
EXEC add_BibleVerse @BibleId, 103008016, N'Then he took all the fat on the entrails, the protruding lobe of the liver, and the two kidneys and their fat, and Moses offered it all up in smoke on the altar,'
EXEC add_BibleVerse @BibleId, 103008017, N'but the rest of the bull – its hide, its flesh, and its dung – he completely burned up outside the camp just as the Lord had commanded Moses.'
EXEC add_BibleVerse @BibleId, 103008018, N'Then he presented the burnt offering ram and Aaron and his sons laid their hands on the head of the ram,'
EXEC add_BibleVerse @BibleId, 103008019, N'and he slaughtered it. Moses then splashed the blood against the altar’s sides.'
EXEC add_BibleVerse @BibleId, 103008020, N'Then he cut the ram into parts, and Moses offered the head, the parts, and the suet up in smoke,'
EXEC add_BibleVerse @BibleId, 103008021, N'but the entrails and the legs he washed with water, and Moses offered the whole ram up in smoke on the altar – it was a burnt offering for a soothing aroma, a gift to the Lord, just as the Lord had commanded Moses.'
EXEC add_BibleVerse @BibleId, 103008022, N'Then he presented the second ram, the ram of ordination, and Aaron and his sons laid their hands on the head of the ram'
EXEC add_BibleVerse @BibleId, 103008023, N'and he slaughtered it. Moses then took some of its blood and put it on Aaron’s right earlobe, on the thumb of his right hand, and on the big toe of his right foot.'
EXEC add_BibleVerse @BibleId, 103008024, N'Next he brought Aaron’s sons forward, and Moses put some of the blood on their right earlobes, on their right thumbs, and on the big toes of their right feet, and Moses splashed the rest of the blood against the altar’s sides.'
EXEC add_BibleVerse @BibleId, 103008025, N'Then he took the fat (the fatty tail, all the fat on the entrails, the protruding lobe of the liver, and the two kidneys and their fat ) and the right thigh,'
EXEC add_BibleVerse @BibleId, 103008026, N'and from the basket of unleavened bread that was before the Lord he took one unleavened loaf, one loaf of bread mixed with olive oil, and one wafer, and placed them on the fat parts and on the right thigh.'
EXEC add_BibleVerse @BibleId, 103008027, N'He then put all of them on the palms of Aaron and his sons, who waved them as a wave offering before the Lord.'
EXEC add_BibleVerse @BibleId, 103008028, N'Moses then took them from their palms and offered them up in smoke on the altar on top of the burnt offering – they were an ordination offering for a soothing aroma; it was a gift to the Lord.'
EXEC add_BibleVerse @BibleId, 103008029, N'Finally, Moses took the breast and waved it as a wave offering before the Lord from the ram of ordination. It was Moses’ share just as the Lord had commanded Moses.'
EXEC add_BibleVerse @BibleId, 103008030, N'Then Moses took some of the anointing oil and some of the blood which was on the altar and sprinkled it on Aaron and his garments, and on his sons and his sons’ garments with him. So he consecrated Aaron, his garments, and his sons and his sons’ garments with him.'
EXEC add_BibleVerse @BibleId, 103008031, N'Then Moses said to Aaron and his sons, “Boil the meat at the entrance of the Meeting Tent, and there you are to eat it and the bread which is in the ordination offering basket, just as I have commanded, saying, ‘Aaron and his sons are to eat it,’'
EXEC add_BibleVerse @BibleId, 103008032, N'but the remainder of the meat and the bread you must burn with fire.'
EXEC add_BibleVerse @BibleId, 103008033, N'And you must not go out from the entrance of the Meeting Tent for seven days, until the day when your days of ordination are completed, because you must be ordained over a seven-day period.'
EXEC add_BibleVerse @BibleId, 103008034, N'What has been done on this day the Lord has commanded to be done to make atonement for you.'
EXEC add_BibleVerse @BibleId, 103008035, N'You must reside at the entrance of the Meeting Tent day and night for seven days and keep the charge of the Lord so that you will not die, for this is what I have been commanded.”'
EXEC add_BibleVerse @BibleId, 103008036, N'So Aaron and his sons did all the things the Lord had commanded through Moses.'
EXEC add_BibleVerse @BibleId, 103009001, N'On the eighth day Moses summoned Aaron and his sons and the elders of Israel,'
EXEC add_BibleVerse @BibleId, 103009002, N'and said to Aaron, “Take for yourself a bull calf for a sin offering and a ram for a burnt offering, both flawless, and present them before the Lord.'
EXEC add_BibleVerse @BibleId, 103009003, N'Then tell the Israelites: ‘Take a male goat for a sin offering and a calf and lamb, both a year old and flawless, for a burnt offering,'
EXEC add_BibleVerse @BibleId, 103009004, N'and an ox and a ram for peace offerings to sacrifice before the Lord, and a grain offering mixed with olive oil, for today the Lord is going to appear to you.’”'
EXEC add_BibleVerse @BibleId, 103009005, N'So they took what Moses had commanded to the front of the Meeting Tent and the whole congregation presented them and stood before the Lord.'
EXEC add_BibleVerse @BibleId, 103009006, N'Then Moses said, “This is what the Lord has commanded you to do so that the glory of the Lord may appear to you.”'
EXEC add_BibleVerse @BibleId, 103009007, N'Moses then said to Aaron, “Approach the altar and make your sin offering and your burnt offering, and make atonement on behalf of yourself and on behalf of the people; and also make the people’s offering and make atonement on behalf of them just as the Lord has commanded.”'
EXEC add_BibleVerse @BibleId, 103009008, N'So Aaron approached the altar and slaughtered the sin offering calf which was for himself.'
EXEC add_BibleVerse @BibleId, 103009009, N'Then Aaron’s sons presented the blood to him and he dipped his finger in the blood and put it on the horns of the altar, and the rest of the blood he poured out at the base of the altar.'
EXEC add_BibleVerse @BibleId, 103009010, N'The fat and the kidneys and the protruding lobe of the liver from the sin offering he offered up in smoke on the altar just as the Lord had commanded Moses,'
EXEC add_BibleVerse @BibleId, 103009011, N'but the flesh and the hide he completely burned up outside the camp.'
EXEC add_BibleVerse @BibleId, 103009012, N'He then slaughtered the burnt offering, and his sons handed the blood to him and he splashed it against the altar’s sides.'
EXEC add_BibleVerse @BibleId, 103009013, N'The burnt offering itself they handed to him by its parts, including the head, and he offered them up in smoke on the altar,'
EXEC add_BibleVerse @BibleId, 103009014, N'and he washed the entrails and the legs and offered them up in smoke on top of the burnt offering on the altar.'
EXEC add_BibleVerse @BibleId, 103009015, N'Then he presented the people’s offering. He took the sin offering male goat which was for the people, slaughtered it, and performed a decontamination rite with it like the first one.'
EXEC add_BibleVerse @BibleId, 103009016, N'He then presented the burnt offering, and did it according to the standard regulation.'
EXEC add_BibleVerse @BibleId, 103009017, N'Next he presented the grain offering, filled his hand with some of it, and offered it up in smoke on the altar in addition to the morning burnt offering.'
EXEC add_BibleVerse @BibleId, 103009018, N'Then he slaughtered the ox and the ram – the peace offering sacrifices which were for the people – and Aaron’s sons handed the blood to him and he splashed it against the altar’s sides.'
EXEC add_BibleVerse @BibleId, 103009019, N'As for the fat parts from the ox and from the ram (the fatty tail, the fat covering the entrails, the kidneys, and the protruding lobe of the liver),'
EXEC add_BibleVerse @BibleId, 103009020, N'they set those on the breasts and he offered the fat parts up in smoke on the altar.'
EXEC add_BibleVerse @BibleId, 103009021, N'Finally Aaron waved the breasts and the right thigh as a wave offering before the Lord just as Moses had commanded.'
EXEC add_BibleVerse @BibleId, 103009022, N'Then Aaron lifted up his hands toward the people and blessed them and descended from making the sin offering, the burnt offering, and the peace offering.'
EXEC add_BibleVerse @BibleId, 103009023, N'Moses and Aaron then entered into the Meeting Tent. When they came out, they blessed the people, and the glory of the Lord appeared to all the people.'
EXEC add_BibleVerse @BibleId, 103009024, N'Then fire went out from the presence of the Lord and consumed the burnt offering and the fat parts on the altar, and all the people saw it, so they shouted loudly and fell down with their faces to the ground.'
EXEC add_BibleVerse @BibleId, 103010001, N'Then Aaron’s sons, Nadab and Abihu, each took his fire pan and put fire in it, set incense on it, and presented strange fire before the Lord, which he had not commanded them to do.'
EXEC add_BibleVerse @BibleId, 103010002, N'So fire went out from the presence of the Lord and consumed them so that they died before the Lord.'
EXEC add_BibleVerse @BibleId, 103010003, N'Moses then said to Aaron, “This is what the Lord spoke: ‘Among the ones close to me I will show myself holy, and in the presence of all the people I will be honored.’” So Aaron kept silent.'
EXEC add_BibleVerse @BibleId, 103010004, N'Moses then called to Mishael and Elzaphan, the sons of Uzziel, Aaron’s uncle, and said to them, “Come near, carry your brothers away from the front of the sanctuary to a place outside the camp.”'
EXEC add_BibleVerse @BibleId, 103010005, N'So they came near and carried them away in their tunics to a place outside the camp just as Moses had spoken.'
EXEC add_BibleVerse @BibleId, 103010006, N'Then Moses said to Aaron and to Eleazar and Ithamar his other two sons, “Do not dishevel the hair of your heads and do not tear your garments, so that you do not die and so that wrath does not come on the whole congregation. Your brothers, all the house of Israel, are to mourn the burning which the Lord has caused,'
EXEC add_BibleVerse @BibleId, 103010007, N'but you must not go out from the entrance of the Meeting Tent lest you die, for the Lord’s anointing oil is on you.” So they acted according to the word of Moses.'
EXEC add_BibleVerse @BibleId, 103010008, N'Then the Lord spoke to Aaron,'
EXEC add_BibleVerse @BibleId, 103010009, N'“Do not drink wine or strong drink, you and your sons with you, when you enter into the Meeting Tent, so that you do not die, which is a perpetual statute throughout your generations,'
EXEC add_BibleVerse @BibleId, 103010010, N'as well as to distinguish between the holy and the common, and between the unclean and the clean,'
EXEC add_BibleVerse @BibleId, 103010011, N'and to teach the Israelites all the statutes that the Lord has spoken to them through Moses.”'
EXEC add_BibleVerse @BibleId, 103010012, N'Then Moses spoke to Aaron and to Eleazar and Ithamar, his remaining sons, “Take the grain offering which remains from the gifts of the Lord and eat it unleavened beside the altar, for it is most holy.'
EXEC add_BibleVerse @BibleId, 103010013, N'You must eat it in a holy place because it is your allotted portion and the allotted portion of your sons from the gifts of the Lord, for this is what I have been commanded.'
EXEC add_BibleVerse @BibleId, 103010014, N'Also, the breast of the wave offering and the thigh of the contribution offering you must eat in a ceremonially clean place, you and your sons and daughters with you, for they have been given as your allotted portion and the allotted portion of your sons from the peace offering sacrifices of the Israelites.'
EXEC add_BibleVerse @BibleId, 103010015, N'The thigh of the contribution offering and the breast of the wave offering they must bring in addition to the gifts of the fat parts to wave them as a wave offering before the Lord, and it will belong to you and your sons with you for a perpetual statute just as the Lord has commanded.”'
EXEC add_BibleVerse @BibleId, 103010016, N'Later Moses sought diligently for the sin offering male goat, but it had actually been burnt. So he became angry at Eleazar and Ithamar, Aaron’s remaining sons, saying,'
EXEC add_BibleVerse @BibleId, 103010017, N'“Why did you not eat the sin offering in the sanctuary? For it is most holy and he gave it to you to bear the iniquity of the congregation, to make atonement on their behalf before the Lord.'
EXEC add_BibleVerse @BibleId, 103010018, N'See here! Its blood was not brought into the holy place within! You should certainly have eaten it in the sanctuary just as I commanded!”'
EXEC add_BibleVerse @BibleId, 103010019, N'But Aaron spoke to Moses, “See here! Just today they presented their sin offering and their burnt offering before the Lord and such things as these have happened to me! If I had eaten a sin offering today would the Lord have been pleased?”'
EXEC add_BibleVerse @BibleId, 103010020, N'When Moses heard this explanation, he was satisfied.'
EXEC add_BibleVerse @BibleId, 103011001, N'The Lord spoke to Moses and Aaron, saying to them,'
EXEC add_BibleVerse @BibleId, 103011002, N'“Tell the Israelites: ‘This is the kind of creature you may eat from among all the animals that are on the land.'
EXEC add_BibleVerse @BibleId, 103011003, N'You may eat any among the animals that has a divided hoof (the hooves are completely split in two ) and that also chews the cud.'
EXEC add_BibleVerse @BibleId, 103011004, N'However, you must not eat these from among those that chew the cud and have divided hooves: The camel is unclean to you because it chews the cud even though its hoof is not divided.'
EXEC add_BibleVerse @BibleId, 103011005, N'The rock badger is unclean to you because it chews the cud even though its hoof is not divided.'
EXEC add_BibleVerse @BibleId, 103011006, N'The hare is unclean to you because it chews the cud even though its hoof is not divided.'
EXEC add_BibleVerse @BibleId, 103011007, N'The pig is unclean to you because its hoof is divided (the hoof is completely split in two ), even though it does not chew the cud.'
EXEC add_BibleVerse @BibleId, 103011008, N'You must not eat from their meat and you must not touch their carcasses; they are unclean to you.'
EXEC add_BibleVerse @BibleId, 103011009, N'“‘These you can eat from all creatures that are in the water: Any creatures in the water that have both fins and scales, whether in the seas or in the streams, you may eat.'
EXEC add_BibleVerse @BibleId, 103011010, N'But any creatures that do not have both fins and scales, whether in the seas or in the streams, from all the swarming things of the water and from all the living creatures that are in the water, are detestable to you.'
EXEC add_BibleVerse @BibleId, 103011011, N'Since they are detestable to you, you must not eat their meat and their carcass you must detest.'
EXEC add_BibleVerse @BibleId, 103011012, N'Any creature in the water that does not have both fins and scales is detestable to you.'
EXEC add_BibleVerse @BibleId, 103011013, N'“‘These you are to detest from among the birds – they must not be eaten, because they are detestable: the griffon vulture, the bearded vulture, the black vulture,'
EXEC add_BibleVerse @BibleId, 103011014, N'the kite, the buzzard of any kind,'
EXEC add_BibleVerse @BibleId, 103011015, N'every kind of crow,'
EXEC add_BibleVerse @BibleId, 103011016, N'the eagle owl, the short-eared owl, the long-eared owl, the hawk of any kind,'
EXEC add_BibleVerse @BibleId, 103011017, N'the little owl, the cormorant, the screech owl,'
EXEC add_BibleVerse @BibleId, 103011018, N'the white owl, the scops owl, the osprey,'
EXEC add_BibleVerse @BibleId, 103011019, N'the stork, the heron of any kind, the hoopoe, and the bat.'
EXEC add_BibleVerse @BibleId, 103011020, N'“‘Every winged swarming thing that walks on all fours is detestable to you.'
EXEC add_BibleVerse @BibleId, 103011021, N'However, this you may eat from all the winged swarming things that walk on all fours, which have jointed legs to hop with on the land.'
EXEC add_BibleVerse @BibleId, 103011022, N'These you may eat from them: the locust of any kind, the bald locust of any kind, the cricket of any kind, the grasshopper of any kind.'
EXEC add_BibleVerse @BibleId, 103011023, N'But any other winged swarming thing that has four legs is detestable to you.'
EXEC add_BibleVerse @BibleId, 103011024, N'“‘By these you defile yourselves; anyone who touches their carcass will be unclean until the evening,'
EXEC add_BibleVerse @BibleId, 103011025, N'and anyone who carries their carcass must wash his clothes and will be unclean until the evening.'
EXEC add_BibleVerse @BibleId, 103011026, N'“‘All animals that divide the hoof but it is not completely split in two and do not chew the cud are unclean to you; anyone who touches them becomes unclean.'
EXEC add_BibleVerse @BibleId, 103011027, N'All that walk on their paws among all the creatures that walk on all fours are unclean to you. Anyone who touches their carcass will be unclean until the evening,'
EXEC add_BibleVerse @BibleId, 103011028, N'and the one who carries their carcass must wash his clothes and be unclean until the evening; they are unclean to you.'
EXEC add_BibleVerse @BibleId, 103011029, N'“‘Now this is what is unclean to you among the swarming things that swarm on the land: the rat, the mouse, the large lizard of any kind,'
EXEC add_BibleVerse @BibleId, 103011030, N'the Mediterranean gecko, the spotted lizard, the wall gecko, the skink, and the chameleon.'
EXEC add_BibleVerse @BibleId, 103011031, N'These are the ones that are unclean to you among all the swarming things. Anyone who touches them when they die will be unclean until evening.'
EXEC add_BibleVerse @BibleId, 103011032, N'Also, anything they fall on when they die will become unclean – any wood vessel or garment or article of leather or sackcloth. Any such vessel with which work is done must be immersed in water and will be unclean until the evening. Then it will become clean.'
EXEC add_BibleVerse @BibleId, 103011033, N'As for any clay vessel they fall into, everything in it will become unclean and you must break it.'
EXEC add_BibleVerse @BibleId, 103011034, N'Any food that may be eaten which becomes soaked with water will become unclean. Anything drinkable in any such vessel will become unclean.'
EXEC add_BibleVerse @BibleId, 103011035, N'Anything their carcass may fall on will become unclean. An oven or small stove must be smashed to pieces; they are unclean, and they will stay unclean to you.'
EXEC add_BibleVerse @BibleId, 103011036, N'However, a spring or a cistern which collects water will be clean, but one who touches their carcass will be unclean.'
EXEC add_BibleVerse @BibleId, 103011037, N'Now, if such a carcass falls on any sowing seed which is to be sown, it is clean,'
EXEC add_BibleVerse @BibleId, 103011038, N'but if water is put on the seed and such a carcass falls on it, it is unclean to you.'
EXEC add_BibleVerse @BibleId, 103011039, N'“‘Now if an animal that you may eat dies, whoever touches its carcass will be unclean until the evening.'
EXEC add_BibleVerse @BibleId, 103011040, N'One who eats from its carcass must wash his clothes and be unclean until the evening, and whoever carries its carcass must wash his clothes and be unclean until the evening.'
EXEC add_BibleVerse @BibleId, 103011041, N'Every swarming thing that swarms on the land is detestable; it must not be eaten.'
EXEC add_BibleVerse @BibleId, 103011042, N'You must not eat anything that crawls on its belly or anything that walks on all fours or on any number of legs of all the swarming things that swarm on the land, because they are detestable.'
EXEC add_BibleVerse @BibleId, 103011043, N'Do not make yourselves detestable by any of the swarming things. You must not defile yourselves by them and become unclean by them,'
EXEC add_BibleVerse @BibleId, 103011044, N'for I am the Lord your God and you are to sanctify yourselves and be holy because I am holy. You must not defile yourselves by any of the swarming things that creep on the ground,'
EXEC add_BibleVerse @BibleId, 103011045, N'for I am the Lord who brought you up from the land of Egypt to be your God, and you are to be holy because I am holy.'
EXEC add_BibleVerse @BibleId, 103011046, N'This is the law of the land animals, the birds, all the living creatures that move in the water, and all the creatures that swarm on the land,'
EXEC add_BibleVerse @BibleId, 103011047, N'to distinguish between the unclean and the clean, between the living creatures that may be eaten and the living creatures that must not be eaten.’”'
EXEC add_BibleVerse @BibleId, 103012001, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103012002, N'“Tell the Israelites, ‘When a woman produces offspring and bears a male child, she will be unclean seven days, as she is unclean during the days of her menstruation.'
EXEC add_BibleVerse @BibleId, 103012003, N'On the eighth day the flesh of his foreskin must be circumcised.'
EXEC add_BibleVerse @BibleId, 103012004, N'Then she will remain thirty-three days in blood purity. She must not touch anything holy and she must not enter the sanctuary until the days of her purification are fulfilled.'
EXEC add_BibleVerse @BibleId, 103012005, N'If she bears a female child, she will be impure fourteen days as during her menstrual flow, and she will remain sixty-six days in blood purity.'
EXEC add_BibleVerse @BibleId, 103012006, N'“‘When the days of her purification are completed for a son or for a daughter, she must bring a one year old lamb for a burnt offering and a young pigeon or turtledove for a sin offering to the entrance of the Meeting Tent, to the priest.'
EXEC add_BibleVerse @BibleId, 103012007, N'The priest is to present it before the Lord and make atonement on her behalf, and she will be clean from her flow of blood. This is the law of the one who bears a child, for the male or the female child.'
EXEC add_BibleVerse @BibleId, 103012008, N'If she cannot afford a sheep, then she must take two turtledoves or two young pigeons, one for a burnt offering and one for a sin offering, and the priest is to make atonement on her behalf, and she will be clean.’”'
EXEC add_BibleVerse @BibleId, 103013001, N'The Lord spoke to Moses and Aaron:'
EXEC add_BibleVerse @BibleId, 103013002, N'“When someone has a swelling or a scab or a bright spot on the skin of his body that may become a diseased infection, he must be brought to Aaron the priest or one of his sons, the priests.'
EXEC add_BibleVerse @BibleId, 103013003, N'The priest must then examine the infection on the skin of the body, and if the hair in the infection has turned white and the infection appears to be deeper than the skin of the body, then it is a diseased infection, so when the priest examines it he must pronounce the person unclean.'
EXEC add_BibleVerse @BibleId, 103013004, N'“If it is a white bright spot on the skin of his body, but it does not appear to be deeper than the skin, and the hair has not turned white, then the priest is to quarantine the person with the infection for seven days.'
EXEC add_BibleVerse @BibleId, 103013005, N'The priest must then examine it on the seventh day, and if, as far as he can see, the infection has stayed the same and has not spread on the skin, then the priest is to quarantine the person for another seven days.'
EXEC add_BibleVerse @BibleId, 103013006, N'The priest must then examine it again on the seventh day, and if the infection has faded and has not spread on the skin, then the priest is to pronounce the person clean. It is a scab, so he must wash his clothes and be clean.'
EXEC add_BibleVerse @BibleId, 103013007, N'If, however, the scab is spreading further on the skin after he has shown himself to the priest for his purification, then he must show himself to the priest a second time.'
EXEC add_BibleVerse @BibleId, 103013008, N'The priest must then examine it, and if the scab has spread on the skin, then the priest is to pronounce the person unclean. It is a disease.'
EXEC add_BibleVerse @BibleId, 103013009, N'“When someone has a diseased infection, he must be brought to the priest.'
EXEC add_BibleVerse @BibleId, 103013010, N'The priest will then examine it, and if a white swelling is on the skin, it has turned the hair white, and there is raw flesh in the swelling,'
EXEC add_BibleVerse @BibleId, 103013011, N'it is a chronic disease on the skin of his body, so the priest is to pronounce him unclean. The priest must not merely quarantine him, for he is unclean.'
EXEC add_BibleVerse @BibleId, 103013012, N'If, however, the disease breaks out on the skin so that the disease covers all the skin of the person with the infection from his head to his feet, as far as the priest can see,'
EXEC add_BibleVerse @BibleId, 103013013, N'the priest must then examine it, and if the disease covers his whole body, he is to pronounce the person with the infection clean. He has turned all white, so he is clean.'
EXEC add_BibleVerse @BibleId, 103013014, N'But whenever raw flesh appears in it he will be unclean,'
EXEC add_BibleVerse @BibleId, 103013015, N'so the priest is to examine the raw flesh and pronounce him unclean – it is diseased.'
EXEC add_BibleVerse @BibleId, 103013016, N'If, however, the raw flesh once again turns white, then he must come to the priest.'
EXEC add_BibleVerse @BibleId, 103013017, N'The priest will then examine it, and if the infection has turned white, the priest is to pronounce the person with the infection clean – he is clean.'
EXEC add_BibleVerse @BibleId, 103013018, N'“When someone’s body has a boil on its skin and it heals,'
EXEC add_BibleVerse @BibleId, 103013019, N'and in the place of the boil there is a white swelling or a reddish white bright spot, he must show himself to the priest.'
EXEC add_BibleVerse @BibleId, 103013020, N'The priest will then examine it, and if it appears to be deeper than the skin and its hair has turned white, then the priest is to pronounce the person unclean. It is a diseased infection that has broken out in the boil.'
EXEC add_BibleVerse @BibleId, 103013021, N'If, however, the priest examines it, and there is no white hair in it, it is not deeper than the skin, and it has faded, then the priest is to quarantine him for seven days.'
EXEC add_BibleVerse @BibleId, 103013022, N'If it is spreading further on the skin, then the priest is to pronounce him unclean. It is an infection.'
EXEC add_BibleVerse @BibleId, 103013023, N'But if the bright spot stays in its place and has not spread, it is the scar of the boil, so the priest is to pronounce him clean.'
EXEC add_BibleVerse @BibleId, 103013024, N'“When a body has a burn on its skin and the raw area of the burn becomes a reddish white or white bright spot,'
EXEC add_BibleVerse @BibleId, 103013025, N'the priest must examine it, and if the hair has turned white in the bright spot and it appears to be deeper than the skin, it is a disease that has broken out in the burn. The priest is to pronounce the person unclean. It is a diseased infection.'
EXEC add_BibleVerse @BibleId, 103013026, N'If, however, the priest examines it and there is no white hair in the bright spot, it is not deeper than the skin, and it has faded, then the priest is to quarantine him for seven days.'
EXEC add_BibleVerse @BibleId, 103013027, N'The priest must then examine it on the seventh day, and if it is spreading further on the skin, then the priest is to pronounce him unclean. It is a diseased infection.'
EXEC add_BibleVerse @BibleId, 103013028, N'But if the bright spot stays in its place, has not spread on the skin, and it has faded, then it is the swelling of the burn, so the priest is to pronounce him clean, because it is the scar of the burn.'
EXEC add_BibleVerse @BibleId, 103013029, N'“When a man or a woman has an infection on the head or in the beard,'
EXEC add_BibleVerse @BibleId, 103013030, N'the priest is to examine the infection, and if it appears to be deeper than the skin and the hair in it is reddish yellow and thin, then the priest is to pronounce the person unclean. It is scall, a disease of the head or the beard.'
EXEC add_BibleVerse @BibleId, 103013031, N'But if the priest examines the scall infection and it does not appear to be deeper than the skin, and there is no black hair in it, then the priest is to quarantine the person with the scall infection for seven days.'
EXEC add_BibleVerse @BibleId, 103013032, N'The priest must then examine the infection on the seventh day, and if the scall has not spread, there is no reddish yellow hair in it, and the scall does not appear to be deeper than the skin,'
EXEC add_BibleVerse @BibleId, 103013033, N'then the individual is to shave himself, but he must not shave the area affected by the scall, and the priest is to quarantine the person with the scall for another seven days.'
EXEC add_BibleVerse @BibleId, 103013034, N'The priest must then examine the scall on the seventh day, and if the scall has not spread on the skin and it does not appear to be deeper than the skin, then the priest is to pronounce him clean. So he is to wash his clothes and be clean.'
EXEC add_BibleVerse @BibleId, 103013035, N'If, however, the scall spreads further on the skin after his purification,'
EXEC add_BibleVerse @BibleId, 103013036, N'then the priest is to examine it, and if the scall has spread on the skin the priest is not to search further for reddish yellow hair. The person is unclean.'
EXEC add_BibleVerse @BibleId, 103013037, N'If, as far as the priest can see, the scall has stayed the same and black hair has sprouted in it, the scall has been healed; the person is clean. So the priest is to pronounce him clean.'
EXEC add_BibleVerse @BibleId, 103013038, N'“When a man or a woman has bright spots – white bright spots – on the skin of their body,'
EXEC add_BibleVerse @BibleId, 103013039, N'the priest is to examine them, and if the bright spots on the skin of their body are faded white, it is a harmless rash that has broken out on the skin. The person is clean.'
EXEC add_BibleVerse @BibleId, 103013040, N'“When a man’s head is bare so that he is balding in back, he is clean.'
EXEC add_BibleVerse @BibleId, 103013041, N'If his head is bare on the forehead so that he is balding in front, he is clean.'
EXEC add_BibleVerse @BibleId, 103013042, N'But if there is a reddish white infection in the back or front bald area, it is a disease breaking out in his back or front bald area.'
EXEC add_BibleVerse @BibleId, 103013043, N'The priest is to examine it, and if the swelling of the infection is reddish white in the back or front bald area like the appearance of a disease on the skin of the body,'
EXEC add_BibleVerse @BibleId, 103013044, N'he is a diseased man. He is unclean. The priest must surely pronounce him unclean because of his infection on his head.'
EXEC add_BibleVerse @BibleId, 103013045, N'“As for the diseased person who has the infection, his clothes must be torn, the hair of his head must be unbound, he must cover his mustache, and he must call out ‘Unclean! Unclean!’'
EXEC add_BibleVerse @BibleId, 103013046, N'The whole time he has the infection he will be continually unclean. He must live in isolation, and his place of residence must be outside the camp.'
EXEC add_BibleVerse @BibleId, 103013047, N'“When a garment has a diseased infection in it, whether a wool or linen garment,'
EXEC add_BibleVerse @BibleId, 103013048, N'or in the warp or woof of the linen or the wool, or in leather or anything made of leather,'
EXEC add_BibleVerse @BibleId, 103013049, N'if the infection in the garment or leather or warp or woof or any article of leather is yellowish green or reddish, it is a diseased infection and it must be shown to the priest.'
EXEC add_BibleVerse @BibleId, 103013050, N'The priest is to examine and then quarantine the article with the infection for seven days.'
EXEC add_BibleVerse @BibleId, 103013051, N'He must then examine the infection on the seventh day. If the infection has spread in the garment, or in the warp, or in the woof, or in the leather – whatever the article into which the leather was made – the infection is a malignant disease. It is unclean.'
EXEC add_BibleVerse @BibleId, 103013052, N'He must burn the garment or the warp or the woof, whether wool or linen, or any article of leather which has the infection in it. Because it is a malignant disease it must be burned up in the fire.'
EXEC add_BibleVerse @BibleId, 103013053, N'But if the priest examines it and the infection has not spread in the garment or in the warp or in the woof or in any article of leather,'
EXEC add_BibleVerse @BibleId, 103013054, N'the priest is to command that they wash whatever has the infection and quarantine it for another seven days.'
EXEC add_BibleVerse @BibleId, 103013055, N'The priest must then examine it after the infection has been washed out, and if the infection has not changed its appearance even though the infection has not spread, it is unclean. You must burn it up in the fire. It is a fungus, whether on the back side or front side of the article.'
EXEC add_BibleVerse @BibleId, 103013056, N'But if the priest has examined it and the infection has faded after it has been washed, he is to tear it out of the garment or the leather or the warp or the woof.'
EXEC add_BibleVerse @BibleId, 103013057, N'Then if it still appears again in the garment or the warp or the woof, or in any article of leather, it is an outbreak. Whatever has the infection in it you must burn up in the fire.'
EXEC add_BibleVerse @BibleId, 103013058, N'But the garment or the warp or the woof or any article of leather which you wash and infection disappears from it is to be washed a second time and it will be clean.”'
EXEC add_BibleVerse @BibleId, 103013059, N'This is the law of the diseased infection in the garment of wool or linen, or the warp or woof, or any article of leather, for pronouncing it clean or unclean.'
EXEC add_BibleVerse @BibleId, 103014001, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103014002, N'“This is the law of the diseased person on the day of his purification, when he is brought to the priest.'
EXEC add_BibleVerse @BibleId, 103014003, N'The priest is to go outside the camp and examine the infection. If the infection of the diseased person has been healed,'
EXEC add_BibleVerse @BibleId, 103014004, N'then the priest will command that two live clean birds, a piece of cedar wood, a scrap of crimson fabric, and some twigs of hyssop be taken up for the one being cleansed.'
EXEC add_BibleVerse @BibleId, 103014005, N'The priest will then command that one bird be slaughtered into a clay vessel over fresh water.'
EXEC add_BibleVerse @BibleId, 103014006, N'Then he is to take the live bird along with the piece of cedar wood, the scrap of crimson fabric, and the twigs of hyssop, and he is to dip them and the live bird in the blood of the bird slaughtered over the fresh water,'
EXEC add_BibleVerse @BibleId, 103014007, N'and sprinkle it seven times on the one being cleansed from the disease, pronounce him clean, and send the live bird away over the open countryside.'
EXEC add_BibleVerse @BibleId, 103014008, N'“The one being cleansed must then wash his clothes, shave off all his hair, and bathe in water, and so be clean. Then afterward he may enter the camp, but he must live outside his tent seven days.'
EXEC add_BibleVerse @BibleId, 103014009, N'When the seventh day comes he must shave all his hair – his head, his beard, his eyebrows, all his hair – and he must wash his clothes, bathe his body in water, and so be clean.'
EXEC add_BibleVerse @BibleId, 103014010, N'“On the eighth day he must take two flawless male lambs, one flawless yearling female lamb, three-tenths of an ephah of choice wheat flour as a grain offering mixed with olive oil, and one log of olive oil,'
EXEC add_BibleVerse @BibleId, 103014011, N'and the priest who pronounces him clean will have the man who is being cleansed stand along with these offerings before the Lord at the entrance of the Meeting Tent.'
EXEC add_BibleVerse @BibleId, 103014012, N'“The priest is to take one male lamb and present it for a guilt offering along with the log of olive oil and present them as a wave offering before the Lord.'
EXEC add_BibleVerse @BibleId, 103014013, N'He must then slaughter the male lamb in the place where the sin offering and the burnt offering are slaughtered, in the sanctuary, because, like the sin offering, the guilt offering belongs to the priest; it is most holy.'
EXEC add_BibleVerse @BibleId, 103014014, N'Then the priest is to take some of the blood of the guilt offering and put it on the right earlobe of the one being cleansed, on the thumb of his right hand, and on the big toe of his right foot.'
EXEC add_BibleVerse @BibleId, 103014015, N'The priest will then take some of the log of olive oil and pour it into his own left hand.'
EXEC add_BibleVerse @BibleId, 103014016, N'Then the priest is to dip his right forefinger into the olive oil that is in his left hand, and sprinkle some of the olive oil with his finger seven times before the Lord.'
EXEC add_BibleVerse @BibleId, 103014017, N'The priest will then put some of the rest of the olive oil that is in his hand on the right earlobe of the one being cleansed, on the thumb of his right hand, and on the big toe of his right foot, on the blood of the guilt offering,'
EXEC add_BibleVerse @BibleId, 103014018, N'and the remainder of the olive oil that is in his hand the priest is to put on the head of the one being cleansed. So the priest is to make atonement for him before the Lord.'
EXEC add_BibleVerse @BibleId, 103014019, N'“The priest must then perform the sin offering and make atonement for the one being cleansed from his impurity. After that he is to slaughter the burnt offering,'
EXEC add_BibleVerse @BibleId, 103014020, N'and the priest is to offer the burnt offering and the grain offering on the altar. So the priest is to make atonement for him and he will be clean.'
EXEC add_BibleVerse @BibleId, 103014021, N'“If the person is poor and does not have sufficient means, he must take one male lamb as a guilt offering for a wave offering to make atonement for himself, one-tenth of an ephah of choice wheat flour mixed with olive oil for a grain offering, a log of olive oil,'
EXEC add_BibleVerse @BibleId, 103014022, N'and two turtledoves or two young pigeons, which are within his means. One will be a sin offering and the other a burnt offering.'
EXEC add_BibleVerse @BibleId, 103014023, N'“On the eighth day he must bring them for his purification to the priest at the entrance of the Meeting Tent before the Lord,'
EXEC add_BibleVerse @BibleId, 103014024, N'and the priest is to take the male lamb of the guilt offering and the log of olive oil and wave them as a wave offering before the Lord.'
EXEC add_BibleVerse @BibleId, 103014025, N'Then he is to slaughter the male lamb of the guilt offering, and the priest is to take some of the blood of the guilt offering and put it on the right earlobe of the one being cleansed, on the thumb of his right hand, and on the big toe of his right foot.'
EXEC add_BibleVerse @BibleId, 103014026, N'The priest will then pour some of the olive oil into his own left hand,'
EXEC add_BibleVerse @BibleId, 103014027, N'and sprinkle some of the olive oil that is in his left hand with his right forefinger seven times before the Lord.'
EXEC add_BibleVerse @BibleId, 103014028, N'Then the priest is to put some of the olive oil that is in his hand on the right earlobe of the one being cleansed, on the thumb of his right hand, and on the big toe of his right foot, on the place of the blood of the guilt offering,'
EXEC add_BibleVerse @BibleId, 103014029, N'and the remainder of the olive oil that is in the hand of the priest he is to put on the head of the one being cleansed to make atonement for him before the Lord.'
EXEC add_BibleVerse @BibleId, 103014030, N'“He will then make one of the turtledoves or young pigeons, which are within his means,'
EXEC add_BibleVerse @BibleId, 103014031, N'a sin offering and the other a burnt offering along with the grain offering. So the priest is to make atonement for the one being cleansed before the Lord.'
EXEC add_BibleVerse @BibleId, 103014032, N'This is the law of the one in whom there is a diseased infection, who does not have sufficient means for his purification.”'
EXEC add_BibleVerse @BibleId, 103014033, N'The Lord spoke to Moses and Aaron:'
EXEC add_BibleVerse @BibleId, 103014034, N'“When you enter the land of Canaan which I am about to give to you for a possession, and I put a diseased infection in a house in the land you are to possess,'
EXEC add_BibleVerse @BibleId, 103014035, N'then whoever owns the house must come and declare to the priest, ‘Something like an infection is visible to me in the house.’'
EXEC add_BibleVerse @BibleId, 103014036, N'Then the priest will command that the house be cleared before the priest enters to examine the infection so that everything in the house does not become unclean, and afterward the priest will enter to examine the house.'
EXEC add_BibleVerse @BibleId, 103014037, N'He is to examine the infection, and if the infection in the walls of the house consists of yellowish green or reddish eruptions, and it appears to be deeper than the surface of the wall,'
EXEC add_BibleVerse @BibleId, 103014038, N'then the priest is to go out of the house to the doorway of the house and quarantine the house for seven days.'
EXEC add_BibleVerse @BibleId, 103014039, N'The priest must return on the seventh day and examine it, and if the infection has spread in the walls of the house,'
EXEC add_BibleVerse @BibleId, 103014040, N'then the priest is to command that the stones that had the infection in them be pulled and thrown outside the city into an unclean place.'
EXEC add_BibleVerse @BibleId, 103014041, N'Then he is to have the house scraped all around on the inside, and the plaster which is scraped off must be dumped outside the city into an unclean place.'
EXEC add_BibleVerse @BibleId, 103014042, N'They are then to take other stones and replace those stones, and he is to take other plaster and replaster the house.'
EXEC add_BibleVerse @BibleId, 103014043, N'“If the infection returns and breaks out in the house after he has pulled out the stones, scraped the house, and it is replastered,'
EXEC add_BibleVerse @BibleId, 103014044, N'the priest is to come and examine it, and if the infection has spread in the house, it is a malignant disease in the house. It is unclean.'
EXEC add_BibleVerse @BibleId, 103014045, N'He must tear down the house, its stones, its wood, and all the plaster of the house, and bring all of it outside the city to an unclean place.'
EXEC add_BibleVerse @BibleId, 103014046, N'Anyone who enters the house all the days the priest has quarantined it will be unclean until evening.'
EXEC add_BibleVerse @BibleId, 103014047, N'Anyone who lies down in the house must wash his clothes. Anyone who eats in the house must wash his clothes.'
EXEC add_BibleVerse @BibleId, 103014048, N'“If, however, the priest enters and examines it, and the infection has not spread in the house after the house has been replastered, then the priest is to pronounce the house clean because the infection has been healed.'
EXEC add_BibleVerse @BibleId, 103014049, N'Then he is to take two birds, a piece of cedar wood, a scrap of crimson fabric, and some twigs of hyssop to decontaminate the house,'
EXEC add_BibleVerse @BibleId, 103014050, N'and he is to slaughter one bird into a clay vessel over fresh water.'
EXEC add_BibleVerse @BibleId, 103014051, N'He must then take the piece of cedar wood, the twigs of hyssop, the scrap of crimson fabric, and the live bird, and dip them in the blood of the slaughtered bird and in the fresh water, and sprinkle the house seven times.'
EXEC add_BibleVerse @BibleId, 103014052, N'So he is to decontaminate the house with the blood of the bird, the fresh water, the live bird, the piece of cedar wood, the twigs of hyssop, and the scrap of crimson fabric,'
EXEC add_BibleVerse @BibleId, 103014053, N'and he is to send the live bird away outside the city into the open countryside. So he is to make atonement for the house and it will be clean.'
EXEC add_BibleVerse @BibleId, 103014054, N'“This is the law for all diseased infections, for scall,'
EXEC add_BibleVerse @BibleId, 103014055, N'for the diseased garment, for the house,'
EXEC add_BibleVerse @BibleId, 103014056, N'for the swelling, for the scab, and for the bright spot,'
EXEC add_BibleVerse @BibleId, 103014057, N'to teach when something is unclean and when it is clean. This is the law for dealing with infectious disease.”'
EXEC add_BibleVerse @BibleId, 103015001, N'The Lord spoke to Moses and Aaron:'
EXEC add_BibleVerse @BibleId, 103015002, N'“Speak to the Israelites and tell them, ‘When any man has a discharge from his body, his discharge is unclean.'
EXEC add_BibleVerse @BibleId, 103015003, N'Now this is his uncleanness in regard to his discharge – whether his body secretes his discharge or blocks his discharge, he is unclean. All the days that his body has a discharge or his body blocks his discharge, this is his uncleanness.'
EXEC add_BibleVerse @BibleId, 103015004, N'“‘Any bed the man with a discharge lies on will be unclean, and any furniture he sits on will be unclean.'
EXEC add_BibleVerse @BibleId, 103015005, N'Anyone who touches his bed must wash his clothes, bathe in water, and be unclean until evening.'
EXEC add_BibleVerse @BibleId, 103015006, N'The one who sits on the furniture the man with a discharge sits on must wash his clothes, bathe in water, and be unclean until evening.'
EXEC add_BibleVerse @BibleId, 103015007, N'The one who touches the body of the man with a discharge must wash his clothes, bathe in water, and be unclean until evening.'
EXEC add_BibleVerse @BibleId, 103015008, N'If the man with a discharge spits on a person who is ceremonially clean, that person must wash his clothes, bathe in water, and be unclean until evening.'
EXEC add_BibleVerse @BibleId, 103015009, N'Any means of riding the man with a discharge rides on will be unclean.'
EXEC add_BibleVerse @BibleId, 103015010, N'Anyone who touches anything that was under him will be unclean until evening, and the one who carries those items must wash his clothes, bathe in water, and be unclean until evening.'
EXEC add_BibleVerse @BibleId, 103015011, N'Anyone whom the man with the discharge touches without having rinsed his hands in water must wash his clothes, bathe in water, and be unclean until evening.'
EXEC add_BibleVerse @BibleId, 103015012, N'A clay vessel which the man with the discharge touches must be broken, and any wooden utensil must be rinsed in water.'
EXEC add_BibleVerse @BibleId, 103015013, N'“‘When the man with the discharge becomes clean from his discharge he is to count off for himself seven days for his purification, and he must wash his clothes, bathe in fresh water, and be clean.'
EXEC add_BibleVerse @BibleId, 103015014, N'Then on the eighth day he is to take for himself two turtledoves or two young pigeons, and he is to present himself before the Lord at the entrance of the Meeting Tent and give them to the priest,'
EXEC add_BibleVerse @BibleId, 103015015, N'and the priest is to make one of them a sin offering and the other a burnt offering. So the priest is to make atonement for him before the Lord for his discharge.'
EXEC add_BibleVerse @BibleId, 103015016, N'“‘When a man has a seminal emission, he must bathe his whole body in water and be unclean until evening,'
EXEC add_BibleVerse @BibleId, 103015017, N'and he must wash in water any clothing or leather that has semen on it, and it will be unclean until evening.'
EXEC add_BibleVerse @BibleId, 103015018, N'When a man has sexual intercourse with a woman and there is a seminal emission, they must bathe in water and be unclean until evening.'
EXEC add_BibleVerse @BibleId, 103015019, N'“‘When a woman has a discharge and her discharge is blood from her body, she is to be in her menstruation seven days, and anyone who touches her will be unclean until evening.'
EXEC add_BibleVerse @BibleId, 103015020, N'Anything she lies on during her menstruation will be unclean, and anything she sits on will be unclean.'
EXEC add_BibleVerse @BibleId, 103015021, N'Anyone who touches her bed must wash his clothes, bathe in water, and be unclean until evening.'
EXEC add_BibleVerse @BibleId, 103015022, N'Anyone who touches any furniture she sits on must wash his clothes, bathe in water, and be unclean until evening.'
EXEC add_BibleVerse @BibleId, 103015023, N'If there is something on the bed or on the furniture she sits on, when he touches it he will be unclean until evening,'
EXEC add_BibleVerse @BibleId, 103015024, N'and if a man actually has sexual intercourse with her so that her menstrual impurity touches him, then he will be unclean seven days and any bed he lies on will be unclean.'
EXEC add_BibleVerse @BibleId, 103015025, N'“‘When a woman’s discharge of blood flows many days not at the time of her menstruation, or if it flows beyond the time of her menstruation, all the days of her discharge of impurity will be like the days of her menstruation – she is unclean.'
EXEC add_BibleVerse @BibleId, 103015026, N'Any bed she lies on all the days of her discharge will be to her like the bed of her menstruation, any furniture she sits on will be unclean like the impurity of her menstruation,'
EXEC add_BibleVerse @BibleId, 103015027, N'and anyone who touches them will be unclean, and he must wash his clothes, bathe in water, and be unclean until evening.'
EXEC add_BibleVerse @BibleId, 103015028, N'“‘If she becomes clean from her discharge, then she is to count off for herself seven days, and afterward she will be clean.'
EXEC add_BibleVerse @BibleId, 103015029, N'Then on the eighth day she must take for herself two turtledoves or two young pigeons and she must bring them to the priest at the entrance of the Meeting Tent,'
EXEC add_BibleVerse @BibleId, 103015030, N'and the priest is to make one a sin offering and the other a burnt offering. So the priest is to make atonement for her before the Lord from her discharge of impurity.'
EXEC add_BibleVerse @BibleId, 103015031, N'“‘Thus you are to set the Israelites apart from their impurity so that they do not die in their impurity by defiling my tabernacle which is in their midst.'
EXEC add_BibleVerse @BibleId, 103015032, N'This is the law of the one with a discharge: the one who has a seminal emission and becomes unclean by it,'
EXEC add_BibleVerse @BibleId, 103015033, N'the one who is sick in her menstruation, the one with a discharge, whether male or female, and a man who has sexual intercourse with an unclean woman.’”'
EXEC add_BibleVerse @BibleId, 103016001, N'The Lord spoke to Moses after the death of Aaron’s two sons when they approached the presence of the Lord and died,'
EXEC add_BibleVerse @BibleId, 103016002, N'and the Lord said to Moses: “Tell Aaron your brother that he must not enter at any time into the holy place inside the veil-canopy in front of the atonement plate that is on the ark so that he may not die, for I will appear in the cloud over the atonement plate.'
EXEC add_BibleVerse @BibleId, 103016003, N'“In this way Aaron is to enter into the sanctuary – with a young bull for a sin offering and a ram for a burnt offering.'
EXEC add_BibleVerse @BibleId, 103016004, N'He must put on a holy linen tunic, linen leggings are to cover his body, and he is to wrap himself with a linen sash and wrap his head with a linen turban. They are holy garments, so he must bathe his body in water and put them on.'
EXEC add_BibleVerse @BibleId, 103016005, N'He must also take two male goats from the congregation of the Israelites for a sin offering and one ram for a burnt offering.'
EXEC add_BibleVerse @BibleId, 103016006, N'Then Aaron is to present the sin offering bull which is for himself and is to make atonement on behalf of himself and his household.'
EXEC add_BibleVerse @BibleId, 103016007, N'He must then take the two goats and stand them before the Lord at the entrance of the Meeting Tent,'
EXEC add_BibleVerse @BibleId, 103016008, N'and Aaron is to cast lots over the two goats, one lot for the Lord and one lot for Azazel.'
EXEC add_BibleVerse @BibleId, 103016009, N'Aaron must then present the goat which has been designated by lot for the Lord, and he is to make it a sin offering,'
EXEC add_BibleVerse @BibleId, 103016010, N'but the goat which has been designated by lot for Azazel is to be stood alive before the Lord to make atonement on it by sending it away to Azazel into the wilderness.'
EXEC add_BibleVerse @BibleId, 103016011, N'“Aaron is to present the sin offering bull which is for himself, and he is to make atonement on behalf of himself and his household. He is to slaughter the sin offering bull which is for himself,'
EXEC add_BibleVerse @BibleId, 103016012, N'and take a censer full of coals of fire from the altar before the Lord and a full double handful of finely ground fragrant incense, and bring them inside the veil-canopy.'
EXEC add_BibleVerse @BibleId, 103016013, N'He must then put the incense on the fire before the Lord, and the cloud of incense will cover the atonement plate which is above the ark of the testimony, so that he will not die.'
EXEC add_BibleVerse @BibleId, 103016014, N'Then he is to take some of the blood of the bull and sprinkle it with his finger on the eastern face of the atonement plate, and in front of the atonement plate he is to sprinkle some of the blood seven times with his finger.'
EXEC add_BibleVerse @BibleId, 103016015, N'“He must then slaughter the sin offering goat which is for the people. He is to bring its blood inside the veil-canopy, and he is to do with its blood just as he did to the blood of the bull: He is to sprinkle it on the atonement plate and in front of the atonement plate.'
EXEC add_BibleVerse @BibleId, 103016016, N'So he is to make atonement for the holy place from the impurities of the Israelites and from their transgressions with regard to all their sins, and thus he is to do for the Meeting Tent which resides with them in the midst of their impurities.'
EXEC add_BibleVerse @BibleId, 103016017, N'Nobody is to be in the Meeting Tent when he enters to make atonement in the holy place until he goes out, and he has made atonement on his behalf, on behalf of his household, and on behalf of the whole assembly of Israel.'
EXEC add_BibleVerse @BibleId, 103016018, N'“Then he is to go out to the altar which is before the Lord and make atonement for it. He is to take some of the blood of the bull and some of the blood of the goat, and put it all around on the horns of the altar.'
EXEC add_BibleVerse @BibleId, 103016019, N'Then he is to sprinkle on it some of the blood with his finger seven times, and cleanse and consecrate it from the impurities of the Israelites.'
EXEC add_BibleVerse @BibleId, 103016020, N'“When he has finished purifying the holy place, the Meeting Tent, and the altar, he is to present the live goat.'
EXEC add_BibleVerse @BibleId, 103016021, N'Aaron is to lay his two hands on the head of the live goat and confess over it all the iniquities of the Israelites and all their transgressions in regard to all their sins, and thus he is to put them on the head of the goat and send it away into the wilderness by the hand of a man standing ready.'
EXEC add_BibleVerse @BibleId, 103016022, N'The goat is to bear on itself all their iniquities into an inaccessible land, so he is to send the goat away in the wilderness.'
EXEC add_BibleVerse @BibleId, 103016023, N'“Aaron must then enter the Meeting Tent and take off the linen garments which he had put on when he entered the sanctuary, and leave them there.'
EXEC add_BibleVerse @BibleId, 103016024, N'Then he must bathe his body in water in a holy place, put on his clothes, and go out and make his burnt offering and the people’s burnt offering. So he is to make atonement on behalf of himself and the people.'
EXEC add_BibleVerse @BibleId, 103016025, N'“Then he is to offer up the fat of the sin offering in smoke on the altar,'
EXEC add_BibleVerse @BibleId, 103016026, N'and the one who sent the goat away to Azazel must wash his clothes, bathe his body in water, and afterward he may reenter the camp.'
EXEC add_BibleVerse @BibleId, 103016027, N'The bull of the sin offering and the goat of the sin offering, whose blood was brought to make atonement in the holy place, must be brought outside the camp and their hide, their flesh, and their dung must be burned up,'
EXEC add_BibleVerse @BibleId, 103016028, N'and the one who burns them must wash his clothes and bathe his body in water, and afterward he may reenter the camp.'
EXEC add_BibleVerse @BibleId, 103016029, N'“This is to be a perpetual statute for you. In the seventh month, on the tenth day of the month, you must humble yourselves and do no work of any kind, both the native citizen and the foreigner who resides in your midst,'
EXEC add_BibleVerse @BibleId, 103016030, N'for on this day atonement is to be made for you to cleanse you from all your sins; you must be clean before the Lord.'
EXEC add_BibleVerse @BibleId, 103016031, N'It is to be a Sabbath of complete rest for you, and you must humble yourselves. It is a perpetual statute.'
EXEC add_BibleVerse @BibleId, 103016032, N'“The priest who is anointed and ordained to act as high priest in place of his father is to make atonement. He is to put on the linen garments, the holy garments,'
EXEC add_BibleVerse @BibleId, 103016033, N'and he is to purify the Most Holy Place, he is to purify the Meeting Tent and the altar, and he is to make atonement for the priests and for all the people of the assembly.'
EXEC add_BibleVerse @BibleId, 103016034, N'This is to be a perpetual statute for you to make atonement for the Israelites for all their sins once a year.” So he did just as the Lord had commanded Moses.'
EXEC add_BibleVerse @BibleId, 103017001, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103017002, N'“Speak to Aaron, his sons, and all the Israelites, and tell them: ‘This is the word that the Lord has commanded:'
EXEC add_BibleVerse @BibleId, 103017003, N'“Blood guilt will be accounted to any man from the house of Israel who slaughters an ox or a lamb or a goat inside the camp or outside the camp,'
EXEC add_BibleVerse @BibleId, 103017004, N'but has not brought it to the entrance of the Meeting Tent to present it as an offering to the Lord before the tabernacle of the Lord. He has shed blood, so that man will be cut off from the midst of his people.'
EXEC add_BibleVerse @BibleId, 103017005, N'This is so that the Israelites will bring their sacrifices that they are sacrificing in the open field to the Lord at the entrance of the Meeting Tent to the priest and sacrifice them there as peace offering sacrifices to the Lord.'
EXEC add_BibleVerse @BibleId, 103017006, N'The priest is to splash the blood on the altar of the Lord at the entrance of the Meeting Tent, and offer the fat up in smoke for a soothing aroma to the Lord.'
EXEC add_BibleVerse @BibleId, 103017007, N'So they must no longer offer their sacrifices to the goat demons, acting like prostitutes by going after them. This is to be a perpetual statute for them throughout their generations.'
EXEC add_BibleVerse @BibleId, 103017008, N'“You are to say to them: ‘Any man from the house of Israel or from the foreigners who reside in their midst, who offers a burnt offering or a sacrifice'
EXEC add_BibleVerse @BibleId, 103017009, N'but does not bring it to the entrance of the Meeting Tent to offer it to the Lord – that person will be cut off from his people.'
EXEC add_BibleVerse @BibleId, 103017010, N'“‘Any man from the house of Israel or from the foreigners who reside in their midst who eats any blood, I will set my face against that person who eats the blood, and I will cut him off from the midst of his people,'
EXEC add_BibleVerse @BibleId, 103017011, N'for the life of every living thing is in the blood. So I myself have assigned it to you on the altar to make atonement for your lives, for the blood makes atonement by means of the life.'
EXEC add_BibleVerse @BibleId, 103017012, N'Therefore, I have said to the Israelites: No person among you is to eat blood, and no resident foreigner who lives among you is to eat blood.'
EXEC add_BibleVerse @BibleId, 103017013, N'“‘Any man from the Israelites or from the foreigners who reside in their midst who hunts a wild animal or a bird that may be eaten must pour out its blood and cover it with soil,'
EXEC add_BibleVerse @BibleId, 103017014, N'for the life of all flesh is its blood. So I have said to the Israelites: You must not eat the blood of any living thing because the life of every living thing is its blood – all who eat it will be cut off.'
EXEC add_BibleVerse @BibleId, 103017015, N'“‘Any person who eats an animal that has died of natural causes or an animal torn by beasts, whether a native citizen or a foreigner, must wash his clothes, bathe in water, and be unclean until evening; then he becomes clean.'
EXEC add_BibleVerse @BibleId, 103017016, N'But if he does not wash his clothes and does not bathe his body, he will bear his punishment for iniquity.’”'
EXEC add_BibleVerse @BibleId, 103018001, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103018002, N'“Speak to the Israelites and tell them, ‘I am the Lord your God!'
EXEC add_BibleVerse @BibleId, 103018003, N'You must not do as they do in the land of Egypt where you have been living, and you must not do as they do in the land of Canaan into which I am about to bring you; you must not walk in their statutes.'
EXEC add_BibleVerse @BibleId, 103018004, N'You must observe my regulations and you must be sure to walk in my statutes. I am the Lord your God.'
EXEC add_BibleVerse @BibleId, 103018005, N'So you must keep my statutes and my regulations; anyone who does so will live by keeping them. I am the Lord.'
EXEC add_BibleVerse @BibleId, 103018006, N'“‘No man is to approach any close relative to have sexual intercourse with her. I am the Lord.'
EXEC add_BibleVerse @BibleId, 103018007, N'You must not expose your father’s nakedness by having sexual intercourse with your mother. She is your mother; you must not have intercourse with her.'
EXEC add_BibleVerse @BibleId, 103018008, N'You must not have sexual intercourse with your father’s wife; she is your father’s nakedness.'
EXEC add_BibleVerse @BibleId, 103018009, N'You must not have sexual intercourse with your sister, whether she is your father’s daughter or your mother’s daughter, whether she is born in the same household or born outside it; you must not have sexual intercourse with either of them.'
EXEC add_BibleVerse @BibleId, 103018010, N'You must not expose the nakedness of your son’s daughter or your daughter’s daughter by having sexual intercourse with them, because they are your own nakedness.'
EXEC add_BibleVerse @BibleId, 103018011, N'You must not have sexual intercourse with the daughter of your father’s wife born of your father; she is your sister. You must not have intercourse with her.'
EXEC add_BibleVerse @BibleId, 103018012, N'You must not have sexual intercourse with your father’s sister; she is your father’s flesh.'
EXEC add_BibleVerse @BibleId, 103018013, N'You must not have sexual intercourse with your mother’s sister, because she is your mother’s flesh.'
EXEC add_BibleVerse @BibleId, 103018014, N'You must not expose the nakedness of your father’s brother; you must not approach his wife to have sexual intercourse with her. She is your aunt.'
EXEC add_BibleVerse @BibleId, 103018015, N'You must not have sexual intercourse with your daughter-in-law; she is your son’s wife. You must not have intercourse with her.'
EXEC add_BibleVerse @BibleId, 103018016, N'You must not have sexual intercourse with your brother’s wife; she is your brother’s nakedness.'
EXEC add_BibleVerse @BibleId, 103018017, N'You must not have sexual intercourse with both a woman and her daughter; you must not take as wife either her son’s daughter or her daughter’s daughter to have intercourse with them. They are closely related to her – it is lewdness.'
EXEC add_BibleVerse @BibleId, 103018018, N'You must not take a woman in marriage and then marry her sister as a rival wife while she is still alive, to have sexual intercourse with her.'
EXEC add_BibleVerse @BibleId, 103018019, N'“‘You must not approach a woman in her menstrual impurity to have sexual intercourse with her.'
EXEC add_BibleVerse @BibleId, 103018020, N'You must not have sexual intercourse with the wife of your fellow citizen to become unclean with her.'
EXEC add_BibleVerse @BibleId, 103018021, N'You must not give any of your children as an offering to Molech, so that you do not profane the name of your God. I am the Lord!'
EXEC add_BibleVerse @BibleId, 103018022, N'You must not have sexual intercourse with a male as one has sexual intercourse with a woman; it is a detestable act.'
EXEC add_BibleVerse @BibleId, 103018023, N'You must not have sexual intercourse with any animal to become defiled with it, and a woman must not stand before an animal to have sexual intercourse with it; it is a perversion.'
EXEC add_BibleVerse @BibleId, 103018024, N'“‘Do not defile yourselves with any of these things, for the nations which I am about to drive out before you have been defiled with all these things.'
EXEC add_BibleVerse @BibleId, 103018025, N'Therefore the land has become unclean and I have brought the punishment for its iniquity upon it, so that the land has vomited out its inhabitants.'
EXEC add_BibleVerse @BibleId, 103018026, N'You yourselves must obey my statutes and my regulations and must not do any of these abominations, both the native citizen and the resident foreigner in your midst,'
EXEC add_BibleVerse @BibleId, 103018027, N'for the people who were in the land before you have done all these abominations, and the land has become unclean.'
EXEC add_BibleVerse @BibleId, 103018028, N'So do not make the land vomit you out because you defile it just as it has vomited out the nations that were before you.'
EXEC add_BibleVerse @BibleId, 103018029, N'For if anyone does any of these abominations, the persons who do them will be cut off from the midst of their people.'
EXEC add_BibleVerse @BibleId, 103018030, N'You must obey my charge to not practice any of the abominable statutes that have been done before you, so that you do not defile yourselves by them. I am the Lord your God.’”'
EXEC add_BibleVerse @BibleId, 103019001, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103019002, N'“Speak to the whole congregation of the Israelites and tell them, ‘You must be holy because I, the Lord your God, am holy.'
EXEC add_BibleVerse @BibleId, 103019003, N'Each of you must respect his mother and his father, and you must keep my Sabbaths. I am the Lord your God.'
EXEC add_BibleVerse @BibleId, 103019004, N'Do not turn to idols, and you must not make for yourselves gods of cast metal. I am the Lord your God.'
EXEC add_BibleVerse @BibleId, 103019005, N'“‘When you sacrifice a peace offering sacrifice to the Lord, you must sacrifice it so that it is accepted for you.'
EXEC add_BibleVerse @BibleId, 103019006, N'It must be eaten on the day of your sacrifice and on the following day, but what is left over until the third day must be burned up.'
EXEC add_BibleVerse @BibleId, 103019007, N'If, however, it is eaten on the third day, it is spoiled, it will not be accepted,'
EXEC add_BibleVerse @BibleId, 103019008, N'and the one who eats it will bear his punishment for iniquity because he has profaned what is holy to the Lord. That person will be cut off from his people.'
EXEC add_BibleVerse @BibleId, 103019009, N'“‘When you gather in the harvest of your land, you must not completely harvest the corner of your field, and you must not gather up the gleanings of your harvest.'
EXEC add_BibleVerse @BibleId, 103019010, N'You must not pick your vineyard bare, and you must not gather up the fallen grapes of your vineyard. You must leave them for the poor and the foreigner. I am the Lord your God.'
EXEC add_BibleVerse @BibleId, 103019011, N'“‘You must not steal, you must not tell lies, and you must not deal falsely with your fellow citizen.'
EXEC add_BibleVerse @BibleId, 103019012, N'You must not swear falsely in my name, so that you do not profane the name of your God. I am the Lord.'
EXEC add_BibleVerse @BibleId, 103019013, N'You must not oppress your neighbor or commit robbery against him. You must not withhold the wages of the hired laborer overnight until morning.'
EXEC add_BibleVerse @BibleId, 103019014, N'You must not curse a deaf person or put a stumbling block in front of a blind person. You must fear your God; I am the Lord.'
EXEC add_BibleVerse @BibleId, 103019015, N'“‘You must not deal unjustly in judgment: you must neither show partiality to the poor nor honor the rich. You must judge your fellow citizen fairly.'
EXEC add_BibleVerse @BibleId, 103019016, N'You must not go about as a slanderer among your people. You must not stand idly by when your neighbor’s life is at stake. I am the Lord.'
EXEC add_BibleVerse @BibleId, 103019017, N'You must not hate your brother in your heart. You must surely reprove your fellow citizen so that you do not incur sin on account of him.'
EXEC add_BibleVerse @BibleId, 103019018, N'You must not take vengeance or bear a grudge against the children of your people, but you must love your neighbor as yourself. I am the Lord.'
EXEC add_BibleVerse @BibleId, 103019019, N'You must keep my statutes. You must not allow two different kinds of your animals to breed, you must not sow your field with two different kinds of seed, and you must not wear a garment made of two different kinds of fabric.'
EXEC add_BibleVerse @BibleId, 103019020, N'“‘When a man has sexual intercourse with a woman, although she is a slave woman designated for another man and she has not yet been ransomed, or freedom has not been granted to her, there will be an obligation to pay compensation. They must not be put to death, because she was not free.'
EXEC add_BibleVerse @BibleId, 103019021, N'He must bring his guilt offering to the Lord at the entrance of the Meeting Tent, a guilt offering ram,'
EXEC add_BibleVerse @BibleId, 103019022, N'and the priest is to make atonement for him with the ram of the guilt offering before the Lord for his sin that he has committed, and he will be forgiven of his sin that he has committed.'
EXEC add_BibleVerse @BibleId, 103019023, N'“‘When you enter the land and plant any fruit tree, you must consider its fruit to be forbidden. Three years it will be forbidden to you; it must not be eaten.'
EXEC add_BibleVerse @BibleId, 103019024, N'In the fourth year all its fruit will be holy, praise offerings to the Lord.'
EXEC add_BibleVerse @BibleId, 103019025, N'Then in the fifth year you may eat its fruit to add its produce to your harvest. I am the Lord your God.'
EXEC add_BibleVerse @BibleId, 103019026, N'“‘You must not eat anything with the blood still in it. You must not practice either divination or soothsaying.'
EXEC add_BibleVerse @BibleId, 103019027, N'You must not round off the corners of the hair on your head or ruin the corners of your beard.'
EXEC add_BibleVerse @BibleId, 103019028, N'You must not slash your body for a dead person or incise a tattoo on yourself. I am the Lord.'
EXEC add_BibleVerse @BibleId, 103019029, N'Do not profane your daughter by making her a prostitute, so that the land does not practice prostitution and become full of lewdness.'
EXEC add_BibleVerse @BibleId, 103019030, N'“‘You must keep my Sabbaths and fear my sanctuary. I am the Lord.'
EXEC add_BibleVerse @BibleId, 103019031, N'Do not turn to the spirits of the dead and do not seek familiar spirits to become unclean by them. I am the Lord your God.'
EXEC add_BibleVerse @BibleId, 103019032, N'You must stand up in the presence of the aged, honor the presence of an elder, and fear your God. I am the Lord.'
EXEC add_BibleVerse @BibleId, 103019033, N'When a foreigner resides with you in your land, you must not oppress him.'
EXEC add_BibleVerse @BibleId, 103019034, N'The foreigner who resides with you must be to you like a native citizen among you; so you must love him as yourself, because you were foreigners in the land of Egypt. I am the Lord your God.'
EXEC add_BibleVerse @BibleId, 103019035, N'You must not do injustice in the regulation of measures, whether of length, weight, or volume.'
EXEC add_BibleVerse @BibleId, 103019036, N'You must have honest balances, honest weights, an honest ephah, and an honest hin. I am the Lord your God who brought you out from the land of Egypt.'
EXEC add_BibleVerse @BibleId, 103019037, N'You must be sure to obey all my statutes and regulations. I am the Lord.’”'
EXEC add_BibleVerse @BibleId, 103020001, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103020002, N'“You are to say to the Israelites, ‘Any man from the Israelites or from the foreigners who reside in Israel who gives any of his children to Molech must be put to death; the people of the land must pelt him with stones.'
EXEC add_BibleVerse @BibleId, 103020003, N'I myself will set my face against that man and cut him off from the midst of his people, because he has given some of his children to Molech and thereby defiled my sanctuary and profaned my holy name.'
EXEC add_BibleVerse @BibleId, 103020004, N'If, however, the people of the land shut their eyes to that man when he gives some of his children to Molech so that they do not put him to death,'
EXEC add_BibleVerse @BibleId, 103020005, N'I myself will set my face against that man and his clan. I will cut off from the midst of their people both him and all who follow after him in spiritual prostitution, to commit prostitution by worshiping Molech.'
EXEC add_BibleVerse @BibleId, 103020006, N'“‘The person who turns to the spirits of the dead and familiar spirits to commit prostitution by going after them, I will set my face against that person and cut him off from the midst of his people.'
EXEC add_BibleVerse @BibleId, 103020007, N'“‘You must sanctify yourselves and be holy, because I am the Lord your God.'
EXEC add_BibleVerse @BibleId, 103020008, N'You must be sure to obey my statutes. I am the Lord who sanctifies you.'
EXEC add_BibleVerse @BibleId, 103020009, N'“‘If anyone curses his father and mother he must be put to death. He has cursed his father and mother; his blood guilt is on himself.'
EXEC add_BibleVerse @BibleId, 103020010, N'If a man commits adultery with his neighbor’s wife, both the adulterer and the adulteress must be put to death.'
EXEC add_BibleVerse @BibleId, 103020011, N'If a man has sexual intercourse with his father’s wife, he has exposed his father’s nakedness. Both of them must be put to death; their blood guilt is on themselves.'
EXEC add_BibleVerse @BibleId, 103020012, N'If a man has sexual intercourse with his daughter-in-law, both of them must be put to death. They have committed perversion; their blood guilt is on themselves.'
EXEC add_BibleVerse @BibleId, 103020013, N'If a man has sexual intercourse with a male as one has sexual intercourse with a woman, the two of them have committed an abomination. They must be put to death; their blood guilt is on themselves.'
EXEC add_BibleVerse @BibleId, 103020014, N'If a man has sexual intercourse with both a woman and her mother, it is lewdness. Both he and they must be burned to death, so there is no lewdness in your midst.'
EXEC add_BibleVerse @BibleId, 103020015, N'If a man has sexual intercourse with any animal, he must be put to death, and you must kill the animal.'
EXEC add_BibleVerse @BibleId, 103020016, N'If a woman approaches any animal to have sexual intercourse with it, you must kill the woman, and the animal must be put to death; their blood guilt is on themselves.'
EXEC add_BibleVerse @BibleId, 103020017, N'“‘If a man has sexual intercourse with his sister, whether the daughter of his father or his mother, so that he sees her nakedness and she sees his nakedness, it is a disgrace. They must be cut off in the sight of the children of their people. He has exposed his sister’s nakedness; he will bear his punishment for iniquity.'
EXEC add_BibleVerse @BibleId, 103020018, N'If a man has sexual intercourse with a menstruating woman and uncovers her nakedness, he has laid bare her fountain of blood and she has exposed the fountain of her blood, so both of them must be cut off from the midst of their people.'
EXEC add_BibleVerse @BibleId, 103020019, N'You must not expose the nakedness of your mother’s sister and your father’s sister, for such a person has laid bare his own close relative. They must bear their punishment for iniquity.'
EXEC add_BibleVerse @BibleId, 103020020, N'If a man has sexual intercourse with his aunt, he has exposed his uncle’s nakedness; they must bear responsibility for their sin, they will die childless.'
EXEC add_BibleVerse @BibleId, 103020021, N'If a man has sexual intercourse with his brother’s wife, it is indecency. He has exposed his brother’s nakedness; they will be childless.'
EXEC add_BibleVerse @BibleId, 103020022, N'“‘You must be sure to obey all my statutes and regulations, so that the land to which I am about to bring you to take up residence there does not vomit you out.'
EXEC add_BibleVerse @BibleId, 103020023, N'You must not walk in the statutes of the nation which I am about to drive out before you, because they have done all these things and I am filled with disgust against them.'
EXEC add_BibleVerse @BibleId, 103020024, N'So I have said to you: You yourselves will possess their land and I myself will give it to you for a possession, a land flowing with milk and honey. I am the Lord your God who has set you apart from the other peoples.'
EXEC add_BibleVerse @BibleId, 103020025, N'Therefore you must distinguish between the clean animal and the unclean, and between the unclean bird and the clean, and you must not make yourselves detestable by means of an animal or bird or anything that creeps on the ground – creatures I have distinguished for you as unclean.'
EXEC add_BibleVerse @BibleId, 103020026, N'You must be holy to me because I, the Lord, am holy, and I have set you apart from the other peoples to be mine.'
EXEC add_BibleVerse @BibleId, 103020027, N'“‘A man or woman who has in them a spirit of the dead or a familiar spirit must be put to death. They must pelt them with stones; their blood guilt is on themselves.’”'
EXEC add_BibleVerse @BibleId, 103021001, N'The Lord said to Moses: “Say to the priests, the sons of Aaron – say to them, ‘For a dead person no priest is to defile himself among his people,'
EXEC add_BibleVerse @BibleId, 103021002, N'except for his close relative who is near to him: his mother, his father, his son, his daughter, his brother,'
EXEC add_BibleVerse @BibleId, 103021003, N'and his virgin sister who is near to him, who has no husband; he may defile himself for her.'
EXEC add_BibleVerse @BibleId, 103021004, N'He must not defile himself as a husband among his people so as to profane himself.'
EXEC add_BibleVerse @BibleId, 103021005, N'Priests must not have a bald spot shaved on their head, they must not shave the corner of their beard, and they must not cut slashes in their body.'
EXEC add_BibleVerse @BibleId, 103021006, N'“‘They must be holy to their God, and they must not profane the name of their God, because they are the ones who present the Lord’s gifts, the food of their God. Therefore they must be holy.'
EXEC add_BibleVerse @BibleId, 103021007, N'They must not take a wife defiled by prostitution, nor are they to take a wife divorced from her husband, for the priest is holy to his God.'
EXEC add_BibleVerse @BibleId, 103021008, N'You must sanctify him because he presents the food of your God. He must be holy to you because I, the Lord who sanctifies you all, am holy.'
EXEC add_BibleVerse @BibleId, 103021009, N'If a daughter of a priest profanes herself by engaging in prostitution, she is profaning her father. She must be burned to death.'
EXEC add_BibleVerse @BibleId, 103021010, N'“‘The high priest – who is greater than his brothers, on whose head the anointing oil is poured, who has been ordained to wear the priestly garments – must neither dishevel the hair of his head nor tear his garments.'
EXEC add_BibleVerse @BibleId, 103021011, N'He must not go where there is any dead person; he must not defile himself even for his father and his mother.'
EXEC add_BibleVerse @BibleId, 103021012, N'He must not go out from the sanctuary and must not profane the sanctuary of his God, because the dedication of the anointing oil of his God is on him. I am the Lord.'
EXEC add_BibleVerse @BibleId, 103021013, N'He must take a wife who is a virgin.'
EXEC add_BibleVerse @BibleId, 103021014, N'He must not marry a widow, a divorced woman, or one profaned by prostitution; he may only take a virgin from his people as a wife.'
EXEC add_BibleVerse @BibleId, 103021015, N'He must not profane his children among his people, for I am the Lord who sanctifies him.’”'
EXEC add_BibleVerse @BibleId, 103021016, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103021017, N'“Tell Aaron, ‘No man from your descendants throughout their generations who has a physical flaw is to approach to present the food of his God.'
EXEC add_BibleVerse @BibleId, 103021018, N'Certainly no man who has a physical flaw is to approach: a blind man, or one who is lame, or one with a slit nose, or a limb too long,'
EXEC add_BibleVerse @BibleId, 103021019, N'or a man who has had a broken leg or arm,'
EXEC add_BibleVerse @BibleId, 103021020, N'or a hunchback, or a dwarf, or one with a spot in his eye, or a festering eruption, or a feverish rash, or a crushed testicle.'
EXEC add_BibleVerse @BibleId, 103021021, N'No man from the descendants of Aaron the priest who has a physical flaw may step forward to present the Lord’s gifts; he has a physical flaw, so he must not step forward to present the food of his God.'
EXEC add_BibleVerse @BibleId, 103021022, N'He may eat both the most holy and the holy food of his God,'
EXEC add_BibleVerse @BibleId, 103021023, N'but he must not go into the veil-canopy or step forward to the altar because he has a physical flaw. Thus he must not profane my holy places, for I am the Lord who sanctifies them.’”'
EXEC add_BibleVerse @BibleId, 103021024, N'So Moses spoke these things to Aaron, his sons, and all the Israelites.'
EXEC add_BibleVerse @BibleId, 103022001, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103022002, N'“Tell Aaron and his sons that they must deal respectfully with the holy offerings of the Israelites, which they consecrate to me, so that they do not profane my holy name. I am the Lord.'
EXEC add_BibleVerse @BibleId, 103022003, N'Say to them, ‘Throughout your generations, if any man from all your descendants approaches the holy offerings which the Israelites consecrate to the Lord while he is impure, that person must be cut off from before me. I am the Lord.'
EXEC add_BibleVerse @BibleId, 103022004, N'No man from the descendants of Aaron who is diseased or has a discharge may eat the holy offerings until he becomes clean. The one who touches anything made unclean by contact with a dead person, or a man who has a seminal emission,'
EXEC add_BibleVerse @BibleId, 103022005, N'or a man who touches a swarming thing by which he becomes unclean, or touches a person by which he becomes unclean, whatever that person’s impurity –'
EXEC add_BibleVerse @BibleId, 103022006, N'the person who touches any of these will be unclean until evening and must not eat from the holy offerings unless he has bathed his body in water.'
EXEC add_BibleVerse @BibleId, 103022007, N'When the sun goes down he will be clean, and afterward he may eat from the holy offerings, because they are his food.'
EXEC add_BibleVerse @BibleId, 103022008, N'He must not eat an animal that has died of natural causes or an animal torn by beasts and thus become unclean by it. I am the Lord.'
EXEC add_BibleVerse @BibleId, 103022009, N'They must keep my charge so that they do not incur sin on account of it and therefore die because they profane it. I am the Lord who sanctifies them.'
EXEC add_BibleVerse @BibleId, 103022010, N'“‘No lay person may eat anything holy. Neither a priest’s lodger nor a hired laborer may eat anything holy,'
EXEC add_BibleVerse @BibleId, 103022011, N'but if a priest buys a person with his own money, that person may eat the holy offerings, and those born in the priest’s own house may eat his food.'
EXEC add_BibleVerse @BibleId, 103022012, N'If a priest’s daughter marries a lay person, she may not eat the holy contribution offerings,'
EXEC add_BibleVerse @BibleId, 103022013, N'but if a priest’s daughter is a widow or divorced, and she has no children so that she returns to live in her father’s house as in her youth, she may eat from her father’s food, but no lay person may eat it.'
EXEC add_BibleVerse @BibleId, 103022014, N'“‘If a man eats a holy offering by mistake, he must add one fifth to it and give the holy offering to the priest.'
EXEC add_BibleVerse @BibleId, 103022015, N'They must not profane the holy offerings which the Israelites contribute to the Lord,'
EXEC add_BibleVerse @BibleId, 103022016, N'and so cause them to incur a penalty for guilt when they eat their holy offerings, for I am the Lord who sanctifies them.’”'
EXEC add_BibleVerse @BibleId, 103022017, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103022018, N'“Speak to Aaron, his sons, and all the Israelites and tell them, ‘When any man from the house of Israel or from the foreigners in Israel presents his offering for any of the votive or freewill offerings which they present to the Lord as a burnt offering,'
EXEC add_BibleVerse @BibleId, 103022019, N'if it is to be acceptable for your benefit it must be a flawless male from the cattle, sheep, or goats.'
EXEC add_BibleVerse @BibleId, 103022020, N'You must not present anything that has a flaw, because it will not be acceptable for your benefit.'
EXEC add_BibleVerse @BibleId, 103022021, N'If a man presents a peace offering sacrifice to the Lord for a special votive offering or for a freewill offering from the herd or the flock, it must be flawless to be acceptable; it must have no flaw.'
EXEC add_BibleVerse @BibleId, 103022022, N'“‘You must not present to the Lord something blind, or with a broken bone, or mutilated, or with a running sore, or with a festering eruption, or with a feverish rash. You must not give any of these as a gift on the altar to the Lord.'
EXEC add_BibleVerse @BibleId, 103022023, N'As for an ox or a sheep with a limb too long or stunted, you may present it as a freewill offering, but it will not be acceptable for a votive offering.'
EXEC add_BibleVerse @BibleId, 103022024, N'You must not present to the Lord something with testicles that are bruised, crushed, torn, or cut off; you must not do this in your land.'
EXEC add_BibleVerse @BibleId, 103022025, N'Even from a foreigner you must not present the food of your God from such animals as these, for they are ruined and flawed; they will not be acceptable for your benefit.’”'
EXEC add_BibleVerse @BibleId, 103022026, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103022027, N'“When an ox, lamb, or goat is born, it must be under the care of its mother seven days, but from the eighth day onward it will be acceptable as an offering gift to the Lord.'
EXEC add_BibleVerse @BibleId, 103022028, N'You must not slaughter an ox or a sheep and its young on the same day.'
EXEC add_BibleVerse @BibleId, 103022029, N'When you sacrifice a thanksgiving offering to the Lord, you must sacrifice it so that it is acceptable for your benefit.'
EXEC add_BibleVerse @BibleId, 103022030, N'On that very day it must be eaten; you must not leave any part of it over until morning. I am the Lord.'
EXEC add_BibleVerse @BibleId, 103022031, N'“You must be sure to do my commandments. I am the Lord.'
EXEC add_BibleVerse @BibleId, 103022032, N'You must not profane my holy name, and I will be sanctified in the midst of the Israelites. I am the Lord who sanctifies you,'
EXEC add_BibleVerse @BibleId, 103022033, N'the one who brought you out from the land of Egypt to be your God. I am the Lord.”'
EXEC add_BibleVerse @BibleId, 103023001, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103023002, N'“Speak to the Israelites and tell them, ‘These are the Lord’s appointed times which you must proclaim as holy assemblies – my appointed times:'
EXEC add_BibleVerse @BibleId, 103023003, N'“‘Six days work may be done, but on the seventh day there must be a Sabbath of complete rest, a holy assembly. You must not do any work; it is a Sabbath to the Lord in all the places where you live.'
EXEC add_BibleVerse @BibleId, 103023004, N'“‘These are the Lord’s appointed times, holy assemblies, which you must proclaim at their appointed time.'
EXEC add_BibleVerse @BibleId, 103023005, N'In the first month, on the fourteenth day of the month, at twilight, is a Passover offering to the Lord.'
EXEC add_BibleVerse @BibleId, 103023006, N'Then on the fifteenth day of the same month will be the festival of unleavened bread to the Lord; seven days you must eat unleavened bread.'
EXEC add_BibleVerse @BibleId, 103023007, N'On the first day there will be a holy assembly for you; you must not do any regular work.'
EXEC add_BibleVerse @BibleId, 103023008, N'You must present a gift to the Lord for seven days, and the seventh day is a holy assembly; you must not do any regular work.’”'
EXEC add_BibleVerse @BibleId, 103023009, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103023010, N'“Speak to the Israelites and tell them, ‘When you enter the land that I am about to give to you and you gather in its harvest, then you must bring the sheaf of the first portion of your harvest to the priest,'
EXEC add_BibleVerse @BibleId, 103023011, N'and he must wave the sheaf before the Lord to be accepted for your benefit – on the day after the Sabbath the priest is to wave it.'
EXEC add_BibleVerse @BibleId, 103023012, N'On the day you wave the sheaf you must also offer a flawless yearling lamb for a burnt offering to the Lord,'
EXEC add_BibleVerse @BibleId, 103023013, N'along with its grain offering, two tenths of an ephah of choice wheat flour mixed with olive oil, as a gift to the Lord, a soothing aroma, and its drink offering, one fourth of a hin of wine.'
EXEC add_BibleVerse @BibleId, 103023014, N'You must not eat bread, roasted grain, or fresh grain until this very day, until you bring the offering of your God. This is a perpetual statute throughout your generations in all the places where you live.'
EXEC add_BibleVerse @BibleId, 103023015, N'“‘You must count for yourselves seven weeks from the day after the Sabbath, from the day you bring the wave offering sheaf; they must be complete weeks.'
EXEC add_BibleVerse @BibleId, 103023016, N'You must count fifty days – until the day after the seventh Sabbath – and then you must present a new grain offering to the Lord.'
EXEC add_BibleVerse @BibleId, 103023017, N'From the places where you live you must bring two loaves of bread for a wave offering; they must be made from two tenths of an ephah of fine wheat flour, baked with yeast, as first fruits to the Lord.'
EXEC add_BibleVerse @BibleId, 103023018, N'Along with the loaves of bread, you must also present seven flawless yearling lambs, one young bull, and two rams. They are to be a burnt offering to the Lord along with their grain offering and drink offerings, a gift of a soothing aroma to the Lord.'
EXEC add_BibleVerse @BibleId, 103023019, N'You must also offer one male goat for a sin offering and two yearling lambs for a peace offering sacrifice,'
EXEC add_BibleVerse @BibleId, 103023020, N'and the priest is to wave them – the two lambs – along with the bread of the first fruits, as a wave offering before the Lord; they will be holy to the Lord for the priest.'
EXEC add_BibleVerse @BibleId, 103023021, N'“‘On this very day you must proclaim an assembly; it is to be a holy assembly for you. You must not do any regular work. This is a perpetual statute in all the places where you live throughout your generations.'
EXEC add_BibleVerse @BibleId, 103023022, N'When you gather in the harvest of your land, you must not completely harvest the corner of your field, and you must not gather up the gleanings of your harvest. You must leave them for the poor and the foreigner. I am the Lord your God.’”'
EXEC add_BibleVerse @BibleId, 103023023, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103023024, N'“Tell the Israelites, ‘In the seventh month, on the first day of the month, you must have a complete rest, a memorial announced by loud horn blasts, a holy assembly.'
EXEC add_BibleVerse @BibleId, 103023025, N'You must not do any regular work, but you must present a gift to the Lord.’”'
EXEC add_BibleVerse @BibleId, 103023026, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103023027, N'“The tenth day of this seventh month is the Day of Atonement. It is to be a holy assembly for you, and you must humble yourselves and present a gift to the Lord.'
EXEC add_BibleVerse @BibleId, 103023028, N'You must not do any work on this particular day, because it is a day of atonement to make atonement for yourselves before the Lord your God.'
EXEC add_BibleVerse @BibleId, 103023029, N'Indeed, any person who does not behave with humility on this particular day will be cut off from his people.'
EXEC add_BibleVerse @BibleId, 103023030, N'As for any person who does any work on this particular day, I will exterminate that person from the midst of his people!'
EXEC add_BibleVerse @BibleId, 103023031, N'You must not do any work. This is a perpetual statute throughout your generations in all the places where you live.'
EXEC add_BibleVerse @BibleId, 103023032, N'It is a Sabbath of complete rest for you, and you must humble yourselves on the ninth day of the month in the evening, from evening until evening you must observe your Sabbath.”'
EXEC add_BibleVerse @BibleId, 103023033, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103023034, N'“Tell the Israelites, ‘On the fifteenth day of this seventh month is the Festival of Temporary Shelters for seven days to the Lord.'
EXEC add_BibleVerse @BibleId, 103023035, N'On the first day is a holy assembly; you must do no regular work.'
EXEC add_BibleVerse @BibleId, 103023036, N'For seven days you must present a gift to the Lord. On the eighth day there is to be a holy assembly for you, and you must present a gift to the Lord. It is a solemn assembly day; you must not do any regular work.'
EXEC add_BibleVerse @BibleId, 103023037, N'“‘These are the appointed times of the Lord that you must proclaim as holy assemblies to present a gift to the Lord – burnt offering, grain offering, sacrifice, and drink offerings, each day according to its regulation,'
EXEC add_BibleVerse @BibleId, 103023038, N'besides the Sabbaths of the Lord and all your gifts, votive offerings, and freewill offerings which you must give to the Lord.'
EXEC add_BibleVerse @BibleId, 103023039, N'“‘On the fifteenth day of the seventh month, when you gather in the produce of the land, you must celebrate a pilgrim festival of the Lord for seven days. On the first day is a complete rest and on the eighth day is complete rest.'
EXEC add_BibleVerse @BibleId, 103023040, N'On the first day you must take for yourselves branches from majestic trees – palm branches, branches of leafy trees, and willows of the brook – and you must rejoice before the Lord your God for seven days.'
EXEC add_BibleVerse @BibleId, 103023041, N'You must celebrate it as a pilgrim festival to the Lord for seven days in the year. This is a perpetual statute throughout your generations; you must celebrate it in the seventh month.'
EXEC add_BibleVerse @BibleId, 103023042, N'You must live in temporary shelters for seven days; every native citizen in Israel must live in temporary shelters,'
EXEC add_BibleVerse @BibleId, 103023043, N'so that your future generations may know that I made the Israelites live in temporary shelters when I brought them out from the land of Egypt. I am the Lord your God.’”'
EXEC add_BibleVerse @BibleId, 103023044, N'So Moses spoke to the Israelites about the appointed times of the Lord.'
EXEC add_BibleVerse @BibleId, 103024001, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103024002, N'“Command the Israelites to bring to you pure oil of beaten olives for the light, to make a lamp burn continually.'
EXEC add_BibleVerse @BibleId, 103024003, N'Outside the veil-canopy of the congregation in the Meeting Tent Aaron must arrange it from evening until morning before the Lord continually. This is a perpetual statute throughout your generations.'
EXEC add_BibleVerse @BibleId, 103024004, N'On the ceremonially pure lampstand he must arrange the lamps before the Lord continually.'
EXEC add_BibleVerse @BibleId, 103024005, N'“You must take choice wheat flour and bake twelve loaves; there must be two tenths of an ephah of flour in each loaf,'
EXEC add_BibleVerse @BibleId, 103024006, N'and you must set them in two rows, six in a row, on the ceremonially pure table before the Lord.'
EXEC add_BibleVerse @BibleId, 103024007, N'You must put pure frankincense on each row, and it will become a memorial portion for the bread, a gift to the Lord.'
EXEC add_BibleVerse @BibleId, 103024008, N'Each Sabbath day Aaron must arrange it before the Lord continually; this portion is from the Israelites as a perpetual covenant.'
EXEC add_BibleVerse @BibleId, 103024009, N'It will belong to Aaron and his sons, and they must eat it in a holy place because it is most holy to him, a perpetual allotted portion from the gifts of the Lord.”'
EXEC add_BibleVerse @BibleId, 103024010, N'Now an Israelite woman’s son whose father was an Egyptian went out among the Israelites, and the Israelite woman’s son and an Israelite man had a fight in the camp.'
EXEC add_BibleVerse @BibleId, 103024011, N'The Israelite woman’s son misused the Name and cursed, so they brought him to Moses. (Now his mother’s name was Shelomith daughter of Dibri, of the tribe of Dan.)'
EXEC add_BibleVerse @BibleId, 103024012, N'So they placed him in custody until they were able to make a clear legal decision for themselves based on words from the mouth of the Lord.'
EXEC add_BibleVerse @BibleId, 103024013, N'Then the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103024014, N'“Bring the one who cursed outside the camp, and all who heard him are to lay their hands on his head, and the whole congregation is to stone him to death.'
EXEC add_BibleVerse @BibleId, 103024015, N'Moreover, you are to tell the Israelites, ‘If any man curses his God he will bear responsibility for his sin,'
EXEC add_BibleVerse @BibleId, 103024016, N'and one who misuses the name of the Lord must surely be put to death. The whole congregation must surely stone him, whether he is a foreigner or a native citizen; when he misuses the Name he must be put to death.'
EXEC add_BibleVerse @BibleId, 103024017, N'“‘If a man beats any person to death, he must be put to death.'
EXEC add_BibleVerse @BibleId, 103024018, N'One who beats an animal to death must make restitution for it, life for life.'
EXEC add_BibleVerse @BibleId, 103024019, N'If a man inflicts an injury on his fellow citizen, just as he has done it must be done to him –'
EXEC add_BibleVerse @BibleId, 103024020, N'fracture for fracture, eye for eye, tooth for tooth – just as he inflicts an injury on another person that same injury must be inflicted on him.'
EXEC add_BibleVerse @BibleId, 103024021, N'One who beats an animal to death must make restitution for it, but one who beats a person to death must be put to death.'
EXEC add_BibleVerse @BibleId, 103024022, N'There will be one regulation for you, whether a foreigner or a native citizen, for I am the Lord your God.’”'
EXEC add_BibleVerse @BibleId, 103024023, N'Then Moses spoke to the Israelites and they brought the one who cursed outside the camp and stoned him with stones. So the Israelites did just as the Lord had commanded Moses.'
EXEC add_BibleVerse @BibleId, 103025001, N'The Lord spoke to Moses at Mount Sinai:'
EXEC add_BibleVerse @BibleId, 103025002, N'“Speak to the Israelites and tell them, ‘When you enter the land that I am giving you, the land must observe a Sabbath to the Lord.'
EXEC add_BibleVerse @BibleId, 103025003, N'Six years you may sow your field, and six years you may prune your vineyard and gather the produce,'
EXEC add_BibleVerse @BibleId, 103025004, N'but in the seventh year the land must have a Sabbath of complete rest – a Sabbath to the Lord. You must not sow your field or prune your vineyard.'
EXEC add_BibleVerse @BibleId, 103025005, N'You must not gather in the aftergrowth of your harvest and you must not pick the grapes of your unpruned vines; the land must have a year of complete rest.'
EXEC add_BibleVerse @BibleId, 103025006, N'You may have the Sabbath produce of the land to eat – you, your male servant, your female servant, your hired worker, the resident foreigner who stays with you,'
EXEC add_BibleVerse @BibleId, 103025007, N'your cattle, and the wild animals that are in your land – all its produce will be for you to eat.'
EXEC add_BibleVerse @BibleId, 103025008, N'“‘You must count off seven weeks of years, seven times seven years, and the days of the seven weeks of years will amount to forty-nine years.'
EXEC add_BibleVerse @BibleId, 103025009, N'You must sound loud horn blasts – in the seventh month, on the tenth day of the month, on the Day of Atonement – you must sound the horn in your entire land.'
EXEC add_BibleVerse @BibleId, 103025010, N'So you must consecrate the fiftieth year, and you must proclaim a release in the land for all its inhabitants. That year will be your jubilee; each one of you must return to his property and each one of you must return to his clan.'
EXEC add_BibleVerse @BibleId, 103025011, N'That fiftieth year will be your jubilee; you must not sow the land, harvest its aftergrowth, or pick the grapes of its unpruned vines.'
EXEC add_BibleVerse @BibleId, 103025012, N'Because that year is a jubilee, it will be holy to you – you may eat its produce from the field.'
EXEC add_BibleVerse @BibleId, 103025013, N'“‘In this year of jubilee you must each return to your property.'
EXEC add_BibleVerse @BibleId, 103025014, N'If you make a sale to your fellow citizen or buy from your fellow citizen, no one is to wrong his brother.'
EXEC add_BibleVerse @BibleId, 103025015, N'You may buy it from your fellow citizen according to the number of years since the last jubilee; he may sell it to you according to the years of produce that are left.'
EXEC add_BibleVerse @BibleId, 103025016, N'The more years there are, the more you may make its purchase price, and the fewer years there are, the less you must make its purchase price, because he is only selling to you a number of years of produce.'
EXEC add_BibleVerse @BibleId, 103025017, N'No one is to oppress his fellow citizen, but you must fear your God, because I am the Lord your God.'
EXEC add_BibleVerse @BibleId, 103025018, N'You must obey my statutes and my regulations; you must be sure to keep them so that you may live securely in the land.'
EXEC add_BibleVerse @BibleId, 103025019, N'“‘The land will give its fruit and you may eat until you are satisfied, and you may live securely in the land.'
EXEC add_BibleVerse @BibleId, 103025020, N'If you say, ‘What will we eat in the seventh year if we do not sow and gather our produce?’'
EXEC add_BibleVerse @BibleId, 103025021, N'I will command my blessing for you in the sixth year so that it may yield the produce for three years,'
EXEC add_BibleVerse @BibleId, 103025022, N'and you may sow the eighth year and eat from that sixth year’s produce – old produce. Until you bring in the ninth year’s produce, you may eat old produce.'
EXEC add_BibleVerse @BibleId, 103025023, N'The land must not be sold without reclaim because the land belongs to me, for you are foreigners and residents with me.'
EXEC add_BibleVerse @BibleId, 103025024, N'In all your landed property you must provide for the right of redemption of the land.'
EXEC add_BibleVerse @BibleId, 103025025, N'“‘If your brother becomes impoverished and sells some of his property, his near redeemer is to come to you and redeem what his brother sold.'
EXEC add_BibleVerse @BibleId, 103025026, N'If a man has no redeemer, but he prospers and gains enough for its redemption,'
EXEC add_BibleVerse @BibleId, 103025027, N'he is to calculate the value of the years it was sold, refund the balance to the man to whom he had sold it, and return to his property.'
EXEC add_BibleVerse @BibleId, 103025028, N'If he has not prospered enough to refund a balance to him, then what he sold will belong to the one who bought it until the jubilee year, but it must revert in the jubilee and the original owner may return to his property.'
EXEC add_BibleVerse @BibleId, 103025029, N'“‘If a man sells a residential house in a walled city, its right of redemption must extend until one full year from its sale; its right of redemption must extend to a full calendar year.'
EXEC add_BibleVerse @BibleId, 103025030, N'If it is not redeemed before the full calendar year is ended, the house in the walled city will belong without reclaim to the one who bought it throughout his generations; it will not revert in the jubilee.'
EXEC add_BibleVerse @BibleId, 103025031, N'The houses of villages, however, which have no wall surrounding them must be considered as the field of the land; they will have the right of redemption and must revert in the jubilee.'
EXEC add_BibleVerse @BibleId, 103025032, N'As for the cities of the Levites, the houses in the cities which they possess, the Levites must have a perpetual right of redemption.'
EXEC add_BibleVerse @BibleId, 103025033, N'Whatever someone among the Levites might redeem – the sale of a house which is his property in a city – must revert in the jubilee, because the houses of the cities of the Levites are their property in the midst of the Israelites.'
EXEC add_BibleVerse @BibleId, 103025034, N'Moreover, the open field areas of their cities must not be sold, because that is their perpetual possession.'
EXEC add_BibleVerse @BibleId, 103025035, N'“‘If your brother becomes impoverished and is indebted to you, you must support him; he must live with you like a foreign resident.'
EXEC add_BibleVerse @BibleId, 103025036, N'Do not take interest or profit from him, but you must fear your God and your brother must live with you.'
EXEC add_BibleVerse @BibleId, 103025037, N'You must not lend him your money at interest and you must not sell him food for profit.'
EXEC add_BibleVerse @BibleId, 103025038, N'I am the Lord your God who brought you out from the land of Egypt to give you the land of Canaan – to be your God.'
EXEC add_BibleVerse @BibleId, 103025039, N'“‘If your brother becomes impoverished with regard to you so that he sells himself to you, you must not subject him to slave service.'
EXEC add_BibleVerse @BibleId, 103025040, N'He must be with you as a hired worker, as a resident foreigner; he must serve with you until the year of jubilee,'
EXEC add_BibleVerse @BibleId, 103025041, N'but then he may go free, he and his children with him, and may return to his family and to the property of his ancestors.'
EXEC add_BibleVerse @BibleId, 103025042, N'Since they are my servants whom I brought out from the land of Egypt, they must not be sold in a slave sale.'
EXEC add_BibleVerse @BibleId, 103025043, N'You must not rule over him harshly, but you must fear your God.'
EXEC add_BibleVerse @BibleId, 103025044, N'“‘As for your male and female slaves who may belong to you – you may buy male and female slaves from the nations all around you.'
EXEC add_BibleVerse @BibleId, 103025045, N'Also you may buy slaves from the children of the foreigners who reside with you, and from their families that are with you, whom they have fathered in your land, they may become your property.'
EXEC add_BibleVerse @BibleId, 103025046, N'You may give them as inheritance to your children after you to possess as property. You may enslave them perpetually. However, as for your brothers the Israelites, no man may rule over his brother harshly.'
EXEC add_BibleVerse @BibleId, 103025047, N'“‘If a resident foreigner who is with you prospers and your brother becomes impoverished with regard to him so that he sells himself to a resident foreigner who is with you or to a member of a foreigner’s family,'
EXEC add_BibleVerse @BibleId, 103025048, N'after he has sold himself he retains a right of redemption. One of his brothers may redeem him,'
EXEC add_BibleVerse @BibleId, 103025049, N'or his uncle or his cousin may redeem him, or anyone of the rest of his blood relatives – his family – may redeem him, or if he prospers he may redeem himself.'
EXEC add_BibleVerse @BibleId, 103025050, N'He must calculate with the one who bought him the number of years from the year he sold himself to him until the jubilee year, and the cost of his sale must correspond to the number of years, according to the rate of wages a hired worker would have earned while with him.'
EXEC add_BibleVerse @BibleId, 103025051, N'If there are still many years, in keeping with them he must refund most of the cost of his purchase for his redemption,'
EXEC add_BibleVerse @BibleId, 103025052, N'but if only a few years remain until the jubilee, he must calculate for himself in keeping with the remaining years and refund it for his redemption.'
EXEC add_BibleVerse @BibleId, 103025053, N'He must be with the one who bought him like a yearly hired worker. The one who bought him must not rule over him harshly in your sight.'
EXEC add_BibleVerse @BibleId, 103025054, N'If, however, he is not redeemed in these ways, he must go free in the jubilee year, he and his children with him,'
EXEC add_BibleVerse @BibleId, 103025055, N'because the Israelites are my own servants; they are my servants whom I brought out from the land of Egypt. I am the Lord your God.'
EXEC add_BibleVerse @BibleId, 103026001, N'“‘You must not make for yourselves idols, so you must not set up for yourselves a carved image or a pillar, and you must not place a sculpted stone in your land to bow down before it, for I am the Lord your God.'
EXEC add_BibleVerse @BibleId, 103026002, N'You must keep my Sabbaths and reverence my sanctuary. I am the Lord.'
EXEC add_BibleVerse @BibleId, 103026003, N'“‘If you walk in my statutes and are sure to obey my commandments,'
EXEC add_BibleVerse @BibleId, 103026004, N'I will give you your rains in their time so that the land will give its yield and the trees of the field will produce their fruit.'
EXEC add_BibleVerse @BibleId, 103026005, N'Threshing season will extend for you until the season for harvesting grapes, and the season for harvesting grapes will extend until sowing season, so you will eat your bread until you are satisfied, and you will live securely in your land.'
EXEC add_BibleVerse @BibleId, 103026006, N'I will grant peace in the land so that you will lie down to sleep without anyone terrifying you. I will remove harmful animals from the land, and no sword of war will pass through your land.'
EXEC add_BibleVerse @BibleId, 103026007, N'You will pursue your enemies and they will fall before you by the sword.'
EXEC add_BibleVerse @BibleId, 103026008, N'Five of you will pursue a hundred, and a hundred of you will pursue ten thousand, and your enemies will fall before you by the sword.'
EXEC add_BibleVerse @BibleId, 103026009, N'I will turn to you, make you fruitful, multiply you, and maintain my covenant with you.'
EXEC add_BibleVerse @BibleId, 103026010, N'You will still be eating stored produce from the previous year and will have to clean out what is stored from the previous year to make room for new.'
EXEC add_BibleVerse @BibleId, 103026011, N'“‘I will put my tabernacle in your midst and I will not abhor you.'
EXEC add_BibleVerse @BibleId, 103026012, N'I will walk among you, and I will be your God and you will be my people.'
EXEC add_BibleVerse @BibleId, 103026013, N'I am the Lord your God who brought you out from the land of Egypt, from being their slaves, and I broke the bars of your yoke and caused you to walk upright.'
EXEC add_BibleVerse @BibleId, 103026014, N'“‘If, however, you do not obey me and keep all these commandments –'
EXEC add_BibleVerse @BibleId, 103026015, N'if you reject my statutes and abhor my regulations so that you do not keep all my commandments and you break my covenant –'
EXEC add_BibleVerse @BibleId, 103026016, N'I for my part will do this to you: I will inflict horror on you, consumption and fever, which diminish eyesight and drain away the vitality of life. You will sow your seed in vain because your enemies will eat it.'
EXEC add_BibleVerse @BibleId, 103026017, N'I will set my face against you. You will be struck down before your enemies, those who hate you will rule over you, and you will flee when there is no one pursuing you.'
EXEC add_BibleVerse @BibleId, 103026018, N'“‘If, in spite of all these things, you do not obey me, I will discipline you seven times more on account of your sins.'
EXEC add_BibleVerse @BibleId, 103026019, N'I will break your strong pride and make your sky like iron and your land like bronze.'
EXEC add_BibleVerse @BibleId, 103026020, N'Your strength will be used up in vain, your land will not give its yield, and the trees of the land will not produce their fruit.'
EXEC add_BibleVerse @BibleId, 103026021, N'“‘If you walk in hostility against me and are not willing to obey me, I will increase your affliction seven times according to your sins.'
EXEC add_BibleVerse @BibleId, 103026022, N'I will send the wild animals against you and they will bereave you of your children, annihilate your cattle, and diminish your population so that your roads will become deserted.'
EXEC add_BibleVerse @BibleId, 103026023, N'“‘If in spite of these things you do not allow yourselves to be disciplined and you walk in hostility against me,'
EXEC add_BibleVerse @BibleId, 103026024, N'I myself will also walk in hostility against you and strike you seven times on account of your sins.'
EXEC add_BibleVerse @BibleId, 103026025, N'I will bring on you an avenging sword, a covenant vengeance. Although you will gather together into your cities, I will send pestilence among you and you will be given into enemy hands.'
EXEC add_BibleVerse @BibleId, 103026026, N'When I break off your supply of bread, ten women will bake your bread in one oven; they will ration your bread by weight, and you will eat and not be satisfied.'
EXEC add_BibleVerse @BibleId, 103026027, N'“‘If in spite of this you do not obey me but walk in hostility against me,'
EXEC add_BibleVerse @BibleId, 103026028, N'I will walk in hostile rage against you and I myself will also discipline you seven times on account of your sins.'
EXEC add_BibleVerse @BibleId, 103026029, N'You will eat the flesh of your sons and the flesh of your daughters.'
EXEC add_BibleVerse @BibleId, 103026030, N'I will destroy your high places and cut down your incense altars, and I will stack your dead bodies on top of the lifeless bodies of your idols. I will abhor you.'
EXEC add_BibleVerse @BibleId, 103026031, N'I will lay your cities waste and make your sanctuaries desolate, and I will refuse to smell your soothing aromas.'
EXEC add_BibleVerse @BibleId, 103026032, N'I myself will make the land desolate and your enemies who live in it will be appalled.'
EXEC add_BibleVerse @BibleId, 103026033, N'I will scatter you among the nations and unsheathe the sword after you, so your land will become desolate and your cities will become a waste.'
EXEC add_BibleVerse @BibleId, 103026034, N'“‘Then the land will make up for its Sabbaths all the days it lies desolate while you are in the land of your enemies; then the land will rest and make up its Sabbaths.'
EXEC add_BibleVerse @BibleId, 103026035, N'All the days of the desolation it will have the rest it did not have on your Sabbaths when you lived on it.'
EXEC add_BibleVerse @BibleId, 103026036, N'“‘As for the ones who remain among you, I will bring despair into their hearts in the lands of their enemies. The sound of a blowing leaf will pursue them, and they will flee as one who flees the sword and fall down even though there is no pursuer.'
EXEC add_BibleVerse @BibleId, 103026037, N'They will stumble over each other as those who flee before a sword, though there is no pursuer, and there will be no one to take a stand for you before your enemies.'
EXEC add_BibleVerse @BibleId, 103026038, N'You will perish among the nations; the land of your enemies will consume you.'
EXEC add_BibleVerse @BibleId, 103026039, N'“‘As for the ones who remain among you, they will rot away because of their iniquity in the lands of your enemies, and they will also rot away because of their ancestors’ iniquities which are with them.'
EXEC add_BibleVerse @BibleId, 103026040, N'However, when they confess their iniquity and their ancestors’ iniquity which they committed by trespassing against me, by which they also walked in hostility against me'
EXEC add_BibleVerse @BibleId, 103026041, N'(and I myself will walk in hostility against them and bring them into the land of their enemies), and then their uncircumcised hearts become humbled and they make up for their iniquity,'
EXEC add_BibleVerse @BibleId, 103026042, N'I will remember my covenant with Jacob and also my covenant with Isaac and also my covenant with Abraham, and I will remember the land.'
EXEC add_BibleVerse @BibleId, 103026043, N'The land will be abandoned by them in order that it may make up for its Sabbaths while it is made desolate without them, and they will make up for their iniquity because they have rejected my regulations and have abhorred my statutes.'
EXEC add_BibleVerse @BibleId, 103026044, N'In spite of this, however, when they are in the land of their enemies I will not reject them and abhor them to make a complete end of them, to break my covenant with them, for I am the Lord their God.'
EXEC add_BibleVerse @BibleId, 103026045, N'I will remember for them the covenant with their ancestors whom I brought out from the land of Egypt in the sight of the nations to be their God. I am the Lord.’”'
EXEC add_BibleVerse @BibleId, 103026046, N'These are the statutes, regulations, and instructions which the Lord established between himself and the Israelites at Mount Sinai through Moses.'
EXEC add_BibleVerse @BibleId, 103027001, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 103027002, N'“Speak to the Israelites and tell them, ‘When a man makes a special votive offering based on the conversion value of persons to the Lord,'
EXEC add_BibleVerse @BibleId, 103027003, N'the conversion value of the male from twenty years old up to sixty years old is fifty shekels by the standard of the sanctuary shekel.'
EXEC add_BibleVerse @BibleId, 103027004, N'If the person is a female, the conversion value is thirty shekels.'
EXEC add_BibleVerse @BibleId, 103027005, N'If the person is from five years old up to twenty years old, the conversion value of the male is twenty shekels, and for the female ten shekels.'
EXEC add_BibleVerse @BibleId, 103027006, N'If the person is one month old up to five years old, the conversion value of the male is five shekels of silver, and for the female the conversion value is three shekels of silver.'
EXEC add_BibleVerse @BibleId, 103027007, N'If the person is from sixty years old and older, if he is a male the conversion value is fifteen shekels, and for the female ten shekels.'
EXEC add_BibleVerse @BibleId, 103027008, N'If he is too poor to pay the conversion value, he must stand the person before the priest and the priest will establish his conversion value; according to what the man who made the vow can afford, the priest will establish his conversion value.'
EXEC add_BibleVerse @BibleId, 103027009, N'“‘If what is vowed is a kind of animal from which an offering may be presented to the Lord, anything which he gives to the Lord from this kind of animal will be holy.'
EXEC add_BibleVerse @BibleId, 103027010, N'He must not replace or exchange it, good for bad or bad for good, and if he does indeed exchange one animal for another animal, then both the original animal and its substitute will be holy.'
EXEC add_BibleVerse @BibleId, 103027011, N'If what is vowed is an unclean animal from which an offering must not be presented to the Lord, then he must stand the animal before the priest,'
EXEC add_BibleVerse @BibleId, 103027012, N'and the priest will establish its conversion value, whether good or bad. According to the assessed conversion value of the priest, thus it will be.'
EXEC add_BibleVerse @BibleId, 103027013, N'If, however, the person who made the vow redeems the animal, he must add one fifth to its conversion value.'
EXEC add_BibleVerse @BibleId, 103027014, N'“‘If a man consecrates his house as holy to the Lord, the priest will establish its conversion value, whether good or bad. Just as the priest establishes its conversion value, thus it will stand.'
EXEC add_BibleVerse @BibleId, 103027015, N'If the one who consecrates it redeems his house, he must add to it one fifth of its conversion value in silver, and it will belong to him.'
EXEC add_BibleVerse @BibleId, 103027016, N'“‘If a man consecrates to the Lord some of his own landed property, the conversion value must be calculated in accordance with the amount of seed needed to sow it, a homer of barley seed being priced at fifty shekels of silver.'
EXEC add_BibleVerse @BibleId, 103027017, N'If he consecrates his field in the jubilee year, the conversion value will stand,'
EXEC add_BibleVerse @BibleId, 103027018, N'but if he consecrates his field after the jubilee, the priest will calculate the price for him according to the years that are left until the next jubilee year, and it will be deducted from the conversion value.'
EXEC add_BibleVerse @BibleId, 103027019, N'If, however, the one who consecrated the field redeems it, he must add to it one fifth of the conversion price and it will belong to him.'
EXEC add_BibleVerse @BibleId, 103027020, N'If he does not redeem the field, but sells the field to someone else, he may never redeem it.'
EXEC add_BibleVerse @BibleId, 103027021, N'When it reverts in the jubilee, the field will be holy to the Lord like a permanently dedicated field; it will become the priest’s property.'
EXEC add_BibleVerse @BibleId, 103027022, N'“‘If he consecrates to the Lord a field he has purchased, which is not part of his own landed property,'
EXEC add_BibleVerse @BibleId, 103027023, N'the priest will calculate for him the amount of its conversion value until the jubilee year, and he must pay the conversion value on that jubilee day as something that is holy to the Lord.'
EXEC add_BibleVerse @BibleId, 103027024, N'In the jubilee year the field will return to the one from whom he bought it, the one to whom it belongs as landed property.'
EXEC add_BibleVerse @BibleId, 103027025, N'Every conversion value must be calculated by the standard of the sanctuary shekel; twenty gerahs to the shekel.'
EXEC add_BibleVerse @BibleId, 103027026, N'“‘Surely no man may consecrate a firstborn that already belongs to the Lord as a firstborn among the animals; whether it is an ox or a sheep, it belongs to the Lord.'
EXEC add_BibleVerse @BibleId, 103027027, N'If, however, it is among the unclean animals, he may ransom it according to its conversion value and must add one fifth to it, but if it is not redeemed it must be sold according to its conversion value.'
EXEC add_BibleVerse @BibleId, 103027028, N'“‘Surely anything which a man permanently dedicates to the Lord from all that belongs to him, whether from people, animals, or his landed property, must be neither sold nor redeemed; anything permanently dedicated is most holy to the Lord.'
EXEC add_BibleVerse @BibleId, 103027029, N'Any human being who is permanently dedicated must not be ransomed; such a person must be put to death.'
EXEC add_BibleVerse @BibleId, 103027030, N'“‘Any tithe of the land, from the grain of the land or from the fruit of the trees, belongs to the Lord; it is holy to the Lord.'
EXEC add_BibleVerse @BibleId, 103027031, N'If a man redeems part of his tithe, however, he must add one fifth to it.'
EXEC add_BibleVerse @BibleId, 103027032, N'All the tithe of herd or flock, everything which passes under the rod, the tenth one will be holy to the Lord.'
EXEC add_BibleVerse @BibleId, 103027033, N'The owner must not examine the animals to distinguish between good and bad, and he must not exchange it. If, however, he does exchange it, both the original animal and its substitute will be holy. It must not be redeemed.’”'
EXEC add_BibleVerse @BibleId, 103027034, N'These are the commandments which the Lord commanded Moses to tell the Israelites at Mount Sinai.'
EXEC add_BibleVerse @BibleId, 104001001, N'Now the Lord spoke to Moses in the tent of meeting in the wilderness of Sinai on the first day of the second month of the second year after the Israelites departed from the land of Egypt. He said:'
EXEC add_BibleVerse @BibleId, 104001002, N'“Take a census of the entire Israelite community by their clans and families, counting the name of every individual male.'
EXEC add_BibleVerse @BibleId, 104001003, N'You and Aaron are to number all in Israel who can serve in the army, those who are twenty years old or older, by their divisions.'
EXEC add_BibleVerse @BibleId, 104001004, N'And to help you there is to be a man from each tribe, each man the head of his family.'
EXEC add_BibleVerse @BibleId, 104001005, N'Now these are the names of the men who are to help you: from Reuben, Elizur son of Shedeur;'
EXEC add_BibleVerse @BibleId, 104001006, N'from Simeon, Shelumiel son of Zurishaddai;'
EXEC add_BibleVerse @BibleId, 104001007, N'from Judah, Nahshon son of Amminadab;'
EXEC add_BibleVerse @BibleId, 104001008, N'from Issachar, Nethanel son of Zuar;'
EXEC add_BibleVerse @BibleId, 104001009, N'from Zebulun, Eliab son of Helon;'
EXEC add_BibleVerse @BibleId, 104001010, N'from the sons of Joseph: from Ephraim, Elishama son of Ammihud; from Manasseh, Gamaliel son of Pedahzur;'
EXEC add_BibleVerse @BibleId, 104001011, N'from Benjamin, Abidan son of Gideoni;'
EXEC add_BibleVerse @BibleId, 104001012, N'from Dan, Ahiezer son of Ammishaddai;'
EXEC add_BibleVerse @BibleId, 104001013, N'from Asher, Pagiel son of Ocran;'
EXEC add_BibleVerse @BibleId, 104001014, N'from Gad, Eliasaph son of Deuel;'
EXEC add_BibleVerse @BibleId, 104001015, N'from Naphtali, Ahira son of Enan.”'
EXEC add_BibleVerse @BibleId, 104001016, N'These were the ones chosen from the community, leaders of their ancestral tribes. They were the heads of the thousands of Israel.'
EXEC add_BibleVerse @BibleId, 104001017, N'So Moses and Aaron took these men who had been mentioned specifically by name,'
EXEC add_BibleVerse @BibleId, 104001018, N'and they assembled the entire community together on the first day of the second month. Then the people recorded their ancestry by their clans and families, and the men who were twenty years old or older were listed by name individually,'
EXEC add_BibleVerse @BibleId, 104001019, N'just as the Lord had commanded Moses. And so he numbered them in the wilderness of Sinai.'
EXEC add_BibleVerse @BibleId, 104001020, N'And they were as follows: The descendants of Reuben, the firstborn son of Israel: According to the records of their clans and families, all the males twenty years old or older who could serve in the army were listed by name individually.'
EXEC add_BibleVerse @BibleId, 104001021, N'Those of them who were numbered from the tribe of Reuben were 46,500.'
EXEC add_BibleVerse @BibleId, 104001022, N'From the descendants of Simeon: According to the records of their clans and families, all the males numbered of them twenty years old or older who could serve in the army were listed by name individually.'
EXEC add_BibleVerse @BibleId, 104001023, N'Those of them who were numbered from the tribe of Simeon were 59,300.'
EXEC add_BibleVerse @BibleId, 104001024, N'From the descendants of Gad: According to the records of their clans and families, all the males twenty years old or older who could serve in the army were listed by name.'
EXEC add_BibleVerse @BibleId, 104001025, N'Those of them who were numbered from the tribe of Gad were 45,650.'
EXEC add_BibleVerse @BibleId, 104001026, N'From the descendants of Judah: According to the records of their clans and families, all the males twenty years old or older who could serve in the army were listed by name.'
EXEC add_BibleVerse @BibleId, 104001027, N'Those of them who were numbered from the tribe of Judah were 74,600.'
EXEC add_BibleVerse @BibleId, 104001028, N'From the descendants of Issachar: According to the records of their clans and families, all the males twenty years old or older who could serve in the army were listed by name.'
EXEC add_BibleVerse @BibleId, 104001029, N'Those of them who were numbered from the tribe of Issachar were 54,400.'
EXEC add_BibleVerse @BibleId, 104001030, N'From the descendants of Zebulun: According to the records of their clans and families, all the males twenty years old or older who could serve in the army were listed by name.'
EXEC add_BibleVerse @BibleId, 104001031, N'Those of them who were numbered from the tribe of Zebulun were 57,400.'
EXEC add_BibleVerse @BibleId, 104001032, N'From the sons of Joseph: From the descendants of Ephraim: According to the records of their clans and families, all the males twenty years old or older who could serve in the army were listed by name.'
EXEC add_BibleVerse @BibleId, 104001033, N'Those of them who were numbered from the tribe of Ephraim were 40,500.'
EXEC add_BibleVerse @BibleId, 104001034, N'From the descendants of Manasseh: According to the records of their clans and families, all the males twenty years old or older who could serve in the army were listed by name.'
EXEC add_BibleVerse @BibleId, 104001035, N'Those of them who were numbered from the tribe of Manasseh were 32,200.'
EXEC add_BibleVerse @BibleId, 104001036, N'From the descendants of Benjamin: According to the records of their clans and families, all the males twenty years old or older who could serve in the army were listed by name.'
EXEC add_BibleVerse @BibleId, 104001037, N'Those of them who were numbered from the tribe of Benjamin were 35,400.'
EXEC add_BibleVerse @BibleId, 104001038, N'From the descendants of Dan: According to the records of their clans and families, all the males twenty years old or older who could serve in the army were listed by name.'
EXEC add_BibleVerse @BibleId, 104001039, N'Those of them who were numbered from the tribe of Dan were 62,700.'
EXEC add_BibleVerse @BibleId, 104001040, N'From the descendants of Asher: According to the records of their clans and families, all the males twenty years old or older who could serve in the army were listed by name.'
EXEC add_BibleVerse @BibleId, 104001041, N'Those of them who were numbered from the tribe of Asher were 41,500.'
EXEC add_BibleVerse @BibleId, 104001042, N'From the descendants of Naphtali: According to the records of their clans and families, all the males twenty years old or older who could serve in the army were listed by name.'
EXEC add_BibleVerse @BibleId, 104001043, N'Those of them who were numbered from the tribe of Naphtali were 53,400.'
EXEC add_BibleVerse @BibleId, 104001044, N'These were the men whom Moses and Aaron numbered along with the twelve leaders of Israel, each of whom was from his own family.'
EXEC add_BibleVerse @BibleId, 104001045, N'All the Israelites who were twenty years old or older, who could serve in Israel’s army, were numbered according to their families.'
EXEC add_BibleVerse @BibleId, 104001046, N'And all those numbered totaled 603,550.'
EXEC add_BibleVerse @BibleId, 104001047, N'But the Levites, according to the tribe of their fathers, were not numbered among them.'
EXEC add_BibleVerse @BibleId, 104001048, N'The Lord had said to Moses,'
EXEC add_BibleVerse @BibleId, 104001049, N'“Only the tribe of Levi you must not number or count with the other Israelites.'
EXEC add_BibleVerse @BibleId, 104001050, N'But appoint the Levites over the tabernacle of the testimony, over all its furnishings and over everything in it. They must carry the tabernacle and all its furnishings; and they must attend to it and camp around it.'
EXEC add_BibleVerse @BibleId, 104001051, N'Whenever the tabernacle is to move, the Levites must take it down, and whenever the tabernacle is to be reassembled, the Levites must set it up. Any unauthorized person who approaches it must be killed.'
EXEC add_BibleVerse @BibleId, 104001052, N'“The Israelites will camp according to their divisions, each man in his camp, and each man by his standard.'
EXEC add_BibleVerse @BibleId, 104001053, N'But the Levites must camp around the tabernacle of the testimony, so that the Lord’s anger will not fall on the Israelite community. The Levites are responsible for the care of the tabernacle of the testimony.”'
EXEC add_BibleVerse @BibleId, 104001054, N'The Israelites did according to all that the Lord commanded Moses – that is what they did.'
EXEC add_BibleVerse @BibleId, 104002001, N'The Lord spoke to Moses and to Aaron:'
EXEC add_BibleVerse @BibleId, 104002002, N'“Every one of the Israelites must camp under his standard with the emblems of his family; they must camp at some distance around the tent of meeting.'
EXEC add_BibleVerse @BibleId, 104002003, N'“Now those who will be camping on the east, toward the sunrise, are the divisions of the camp of Judah under their standard. The leader of the people of Judah is Nahshon son of Amminadab.'
EXEC add_BibleVerse @BibleId, 104002004, N'Those numbered in his division are 74,600.'
EXEC add_BibleVerse @BibleId, 104002005, N'Those who will be camping next to them are the tribe of Issachar. The leader of the people of Issachar is Nethanel son of Zuar.'
EXEC add_BibleVerse @BibleId, 104002006, N'Those numbered in his division are 54,400.'
EXEC add_BibleVerse @BibleId, 104002007, N'Next will be the tribe of Zebulun. The leader of the people of Zebulun is Eliab son of Helon.'
EXEC add_BibleVerse @BibleId, 104002008, N'Those numbered in his division are 57,400.'
EXEC add_BibleVerse @BibleId, 104002009, N'All those numbered of the camp of Judah, according to their divisions, are 186,400. They will travel at the front.'
EXEC add_BibleVerse @BibleId, 104002010, N'“On the south will be the divisions of the camp of Reuben under their standard. The leader of the people of Reuben is Elizur son of Shedeur.'
EXEC add_BibleVerse @BibleId, 104002011, N'Those numbered in his division are 46,500.'
EXEC add_BibleVerse @BibleId, 104002012, N'Those who will be camping next to them are the tribe of Simeon. The leader of the people of Simeon is Shelumiel son of Zurishaddai.'
EXEC add_BibleVerse @BibleId, 104002013, N'Those numbered in his division are 59,300.'
EXEC add_BibleVerse @BibleId, 104002014, N'Next will be the tribe of Gad. The leader of the people of Gad is Eliasaph son of Deuel.'
EXEC add_BibleVerse @BibleId, 104002015, N'Those numbered in his division are 45,650.'
EXEC add_BibleVerse @BibleId, 104002016, N'All those numbered of the camp of Reuben, according to their divisions, are 151,450. They will travel second.'
EXEC add_BibleVerse @BibleId, 104002017, N'“Then the tent of meeting with the camp of the Levites will travel in the middle of the camps. They will travel in the same order as they camped, each in his own place under his standard.'
EXEC add_BibleVerse @BibleId, 104002018, N'“On the west will be the divisions of the camp of Ephraim under their standard. The leader of the people of Ephraim is Elishama son of Amihud.'
EXEC add_BibleVerse @BibleId, 104002019, N'Those numbered in his division are 40,500.'
EXEC add_BibleVerse @BibleId, 104002020, N'Next to them will be the tribe of Manasseh. The leader of the people of Manasseh is Gamaliel son of Pedahzur.'
EXEC add_BibleVerse @BibleId, 104002021, N'Those numbered in his division are 32,200.'
EXEC add_BibleVerse @BibleId, 104002022, N'Next will be the tribe of Benjamin. The leader of the people of Benjamin is Abidan son of Gideoni.'
EXEC add_BibleVerse @BibleId, 104002023, N'Those numbered in his division are 35,400.'
EXEC add_BibleVerse @BibleId, 104002024, N'All those numbered of the camp of Ephraim, according to their divisions, are 108,100. They will travel third.'
EXEC add_BibleVerse @BibleId, 104002025, N'“On the north will be the divisions of the camp of Dan, under their standards. The leader of the people of Dan is Ahiezer son of Ammishaddai.'
EXEC add_BibleVerse @BibleId, 104002026, N'Those numbered in his division are 62,700.'
EXEC add_BibleVerse @BibleId, 104002027, N'Those who will be camping next to them are the tribe of Asher. The leader of the people of Asher is Pagiel son of Ocran.'
EXEC add_BibleVerse @BibleId, 104002028, N'Those numbered in his division are 41,500.'
EXEC add_BibleVerse @BibleId, 104002029, N'Next will be the tribe of Naphtali. The leader of the people of Naphtali is Ahira son of Enan.'
EXEC add_BibleVerse @BibleId, 104002030, N'Those numbered in his division are 53,400.'
EXEC add_BibleVerse @BibleId, 104002031, N'All those numbered of the camp of Dan are 157,600. They will travel last, under their standards.”'
EXEC add_BibleVerse @BibleId, 104002032, N'These are the Israelites, numbered according to their families. All those numbered in the camps, by their divisions, are 603,550.'
EXEC add_BibleVerse @BibleId, 104002033, N'But the Levites were not numbered among the other Israelites, as the Lord commanded Moses.'
EXEC add_BibleVerse @BibleId, 104002034, N'So the Israelites did according to all that the Lord commanded Moses; that is the way they camped under their standards, and that is the way they traveled, each with his clan and family.'
EXEC add_BibleVerse @BibleId, 104003001, N'Now these are the records of Aaron and Moses when the Lord spoke with Moses on Mount Sinai.'
EXEC add_BibleVerse @BibleId, 104003002, N'These are the names of the sons of Aaron: Nadab, the firstborn, and Abihu, Eleazar, and Ithamar.'
EXEC add_BibleVerse @BibleId, 104003003, N'These are the names of the sons of Aaron, the anointed priests, whom he consecrated to minister as priests.'
EXEC add_BibleVerse @BibleId, 104003004, N'Nadab and Abihu died before the Lord when they offered strange fire before the Lord in the wilderness of Sinai, and they had no children. So Eleazar and Ithamar ministered as priests in the presence of Aaron their father.'
EXEC add_BibleVerse @BibleId, 104003005, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104003006, N'“Bring the tribe of Levi near, and present them before Aaron the priest, that they may serve him.'
EXEC add_BibleVerse @BibleId, 104003007, N'They are responsible for his needs and the needs of the whole community before the tent of meeting, by attending to the service of the tabernacle.'
EXEC add_BibleVerse @BibleId, 104003008, N'And they are responsible for all the furnishings of the tent of meeting, and for the needs of the Israelites, as they serve in the tabernacle.'
EXEC add_BibleVerse @BibleId, 104003009, N'You are to assign the Levites to Aaron and his sons; they will be assigned exclusively to him out of all the Israelites.'
EXEC add_BibleVerse @BibleId, 104003010, N'So you are to appoint Aaron and his sons, and they will be responsible for their priesthood; but the unauthorized person who comes near must be put to death.”'
EXEC add_BibleVerse @BibleId, 104003011, N'Then the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104003012, N'“Look, I myself have taken the Levites from among the Israelites instead of every firstborn who opens the womb among the Israelites. So the Levites belong to me,'
EXEC add_BibleVerse @BibleId, 104003013, N'because all the firstborn are mine. When I destroyed all the firstborn in the land of Egypt, I set apart for myself all the firstborn in Israel, both man and beast. They belong to me. I am the Lord.”'
EXEC add_BibleVerse @BibleId, 104003014, N'Then the Lord spoke to Moses in the wilderness of Sinai:'
EXEC add_BibleVerse @BibleId, 104003015, N'“Number the Levites by their clans and their families; every male from a month old and upward you are to number.”'
EXEC add_BibleVerse @BibleId, 104003016, N'So Moses numbered them according to the word of the Lord, just as he had been commanded.'
EXEC add_BibleVerse @BibleId, 104003017, N'These were the sons of Levi by their names: Gershon, Kohath, and Merari.'
EXEC add_BibleVerse @BibleId, 104003018, N'These are the names of the sons of Gershon by their families: Libni and Shimei.'
EXEC add_BibleVerse @BibleId, 104003019, N'The sons of Kohath by their families were: Amram, Izhar, Hebron, and Uzziel.'
EXEC add_BibleVerse @BibleId, 104003020, N'The sons of Merari by their families were Mahli and Mushi. These are the families of the Levites by their clans.'
EXEC add_BibleVerse @BibleId, 104003021, N'From Gershon came the family of the Libnites and the family of the Shimeites; these were the families of the Gershonites.'
EXEC add_BibleVerse @BibleId, 104003022, N'Those of them who were numbered, counting every male from a month old and upward, were 7,500.'
EXEC add_BibleVerse @BibleId, 104003023, N'The families of the Gershonites were to camp behind the tabernacle toward the west.'
EXEC add_BibleVerse @BibleId, 104003024, N'Now the leader of the clan of the Gershonites was Eliasaph son of Lael.'
EXEC add_BibleVerse @BibleId, 104003025, N'And the responsibilities of the Gershonites in the tent of meeting included the tabernacle, the tent with its covering, the curtain at the entrance of the tent of meeting,'
EXEC add_BibleVerse @BibleId, 104003026, N'the hangings of the courtyard, the curtain at the entrance to the courtyard that surrounded the tabernacle and the altar, and their ropes, plus all the service connected with these things.'
EXEC add_BibleVerse @BibleId, 104003027, N'From Kohath came the family of the Amramites, the family of the Izharites, the family of the Hebronites, and the family of the Uzzielites; these were the families of the Kohathites.'
EXEC add_BibleVerse @BibleId, 104003028, N'Counting every male from a month old and upward, there were 8,600. They were responsible for the care of the sanctuary.'
EXEC add_BibleVerse @BibleId, 104003029, N'The families of the Kohathites were to camp on the south side of the tabernacle.'
EXEC add_BibleVerse @BibleId, 104003030, N'Now the leader of the clan of the families of the Kohathites was Elizaphan son of Uzziel.'
EXEC add_BibleVerse @BibleId, 104003031, N'Their responsibilities included the ark, the table, the lampstand, the altars, and the utensils of the sanctuary with which they ministered, the curtain, and all their service.'
EXEC add_BibleVerse @BibleId, 104003032, N'Now the head of all the Levitical leaders was Eleazar son of Aaron the priest. He was appointed over those who were responsible for the sanctuary.'
EXEC add_BibleVerse @BibleId, 104003033, N'From Merari came the family of the Mahlites and the family of the Mushites; these were the families of Merari.'
EXEC add_BibleVerse @BibleId, 104003034, N'Those of them who were numbered, counting every male from a month old and upward, were 6,200.'
EXEC add_BibleVerse @BibleId, 104003035, N'Now the leader of the clan of the families of Merari was Zuriel son of Abihail. These were to camp on the north side of the tabernacle.'
EXEC add_BibleVerse @BibleId, 104003036, N'The appointed responsibilities of the Merarites included the frames of the tabernacle, its crossbars, its posts, its sockets, its utensils, plus all the service connected with these things,'
EXEC add_BibleVerse @BibleId, 104003037, N'and the pillars of the courtyard all around, with their sockets, their pegs, and their ropes.'
EXEC add_BibleVerse @BibleId, 104003038, N'But those who were to camp in front of the tabernacle on the east, in front of the tent of meeting, were Moses, Aaron, and his sons. They were responsible for the needs of the sanctuary and for the needs of the Israelites, but the unauthorized person who approached was to be put to death.'
EXEC add_BibleVerse @BibleId, 104003039, N'All who were numbered of the Levites, whom Moses and Aaron numbered by the word of the Lord, according to their families, every male from a month old and upward, were 22,000.'
EXEC add_BibleVerse @BibleId, 104003040, N'Then the Lord said to Moses, “Number all the firstborn males of the Israelites from a month old and upward, and take the number of their names.'
EXEC add_BibleVerse @BibleId, 104003041, N'And take the Levites for me – I am the Lord – instead of all the firstborn males among the Israelites, and the livestock of the Levites instead of all the firstborn of the livestock of the Israelites.”'
EXEC add_BibleVerse @BibleId, 104003042, N'So Moses numbered all the firstborn males among the Israelites, as the Lord had commanded him.'
EXEC add_BibleVerse @BibleId, 104003043, N'And all the firstborn males, by the number of the names from a month old and upward, totaled 22,273.'
EXEC add_BibleVerse @BibleId, 104003044, N'Then the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104003045, N'“Take the Levites instead of all the firstborn males among the Israelites, and the livestock of the Levites instead of their livestock. And the Levites will be mine. I am the Lord.'
EXEC add_BibleVerse @BibleId, 104003046, N'And for the redemption of the 273 firstborn males of the Israelites who exceed the number of the Levites,'
EXEC add_BibleVerse @BibleId, 104003047, N'collect five shekels for each one individually; you are to collect this amount in the currency of the sanctuary shekel (this shekel is twenty gerahs).'
EXEC add_BibleVerse @BibleId, 104003048, N'And give the money for the redemption of the excess number of them to Aaron and his sons.”'
EXEC add_BibleVerse @BibleId, 104003049, N'So Moses took the redemption money from those who were in excess of those redeemed by the Levites.'
EXEC add_BibleVerse @BibleId, 104003050, N'From the firstborn males of the Israelites he collected the money, 1,365 shekels, according to the sanctuary shekel.'
EXEC add_BibleVerse @BibleId, 104003051, N'Moses gave the redemption money to Aaron and his sons, according to the word of the Lord, as the Lord had commanded Moses.'
EXEC add_BibleVerse @BibleId, 104004001, N'Then the Lord spoke to Moses and Aaron:'
EXEC add_BibleVerse @BibleId, 104004002, N'“Take a census of the Kohathites from among the Levites, by their families and by their clans,'
EXEC add_BibleVerse @BibleId, 104004003, N'from thirty years old and upward to fifty years old, all who enter the company to do the work in the tent of meeting.'
EXEC add_BibleVerse @BibleId, 104004004, N'This is the service of the Kohathites in the tent of meeting, relating to the most holy things.'
EXEC add_BibleVerse @BibleId, 104004005, N'When it is time for the camp to journey, Aaron and his sons must come and take down the screening curtain and cover the ark of the testimony with it.'
EXEC add_BibleVerse @BibleId, 104004006, N'Then they must put over it a covering of fine leather and spread over that a cloth entirely of blue, and then they must insert its poles.'
EXEC add_BibleVerse @BibleId, 104004007, N'“On the table of the presence they must spread a blue cloth, and put on it the dishes, the pans, the bowls, and the pitchers for pouring, and the Bread of the Presence must be on it continually.'
EXEC add_BibleVerse @BibleId, 104004008, N'They must spread over them a scarlet cloth, and cover the same with a covering of fine leather; and they must insert its poles.'
EXEC add_BibleVerse @BibleId, 104004009, N'“They must take a blue cloth and cover the lampstand of the light, with its lamps, its wick-trimmers, its trays, and all its oil vessels, with which they service it.'
EXEC add_BibleVerse @BibleId, 104004010, N'Then they must put it with all its utensils in a covering of fine leather, and put it on a carrying beam.'
EXEC add_BibleVerse @BibleId, 104004011, N'“They must spread a blue cloth on the gold altar, and cover it with a covering of fine leather; and they must insert its poles.'
EXEC add_BibleVerse @BibleId, 104004012, N'Then they must take all the utensils of the service, with which they serve in the sanctuary, put them in a blue cloth, cover them with a covering of fine leather, and put them on a carrying beam.'
EXEC add_BibleVerse @BibleId, 104004013, N'Also, they must take away the ashes from the altar and spread a purple cloth over it.'
EXEC add_BibleVerse @BibleId, 104004014, N'Then they must place on it all its implements with which they serve there – the trays, the meat forks, the shovels, the basins, and all the utensils of the altar – and they must spread on it a covering of fine leather, and then insert its poles.'
EXEC add_BibleVerse @BibleId, 104004015, N'“When Aaron and his sons have finished covering the sanctuary and all the furnishings of the sanctuary, when the camp is ready to journey, then the Kohathites will come to carry them; but they must not touch any holy thing, or they will die. These are the responsibilities of the Kohathites with the tent of meeting.'
EXEC add_BibleVerse @BibleId, 104004016, N'“The appointed responsibility of Eleazar son of Aaron the priest is for the oil for the light, and the spiced incense, and the daily grain offering, and the anointing oil; he also has the appointed responsibility over all the tabernacle with all that is in it, over the sanctuary and over all its furnishings.”'
EXEC add_BibleVerse @BibleId, 104004017, N'Then the Lord spoke to Moses and Aaron:'
EXEC add_BibleVerse @BibleId, 104004018, N'“Do not allow the tribe of the families of the Kohathites to be cut off from among the Levites;'
EXEC add_BibleVerse @BibleId, 104004019, N'but in order that they will live and not die when they approach the most holy things, do this for them: Aaron and his sons will go in and appoint each man to his service and his responsibility.'
EXEC add_BibleVerse @BibleId, 104004020, N'But the Kohathites are not to go in to watch while the holy things are being covered, or they will die.”'
EXEC add_BibleVerse @BibleId, 104004021, N'Then the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104004022, N'“Also take a census of the Gershonites, by their clans and by their families.'
EXEC add_BibleVerse @BibleId, 104004023, N'You must number them from thirty years old and upward to fifty years old, all who enter the company to do the work of the tent of meeting.'
EXEC add_BibleVerse @BibleId, 104004024, N'This is the service of the families of Gershonites, as they serve and carry it.'
EXEC add_BibleVerse @BibleId, 104004025, N'They must carry the curtains for the tabernacle and the tent of meeting with its covering, the covering of fine leather that is over it, the curtains for the entrance of the tent of meeting,'
EXEC add_BibleVerse @BibleId, 104004026, N'the hangings for the courtyard, the curtain for the entrance of the gate of the court, which is around the tabernacle and the altar, and their ropes, along with all the furnishings for their service and everything that is made for them. So they are to serve.'
EXEC add_BibleVerse @BibleId, 104004027, N'“All the service of the Gershonites, whether carrying loads or for any of their work, will be at the direction of Aaron and his sons. You will assign them all their tasks as their responsibility.'
EXEC add_BibleVerse @BibleId, 104004028, N'This is the service of the families of the Gershonites concerning the tent of meeting. Their responsibilities will be under the authority of Ithamar son of Aaron the priest.'
EXEC add_BibleVerse @BibleId, 104004029, N'“As for the sons of Merari, you are to number them by their families and by their clans.'
EXEC add_BibleVerse @BibleId, 104004030, N'You must number them from thirty years old and upward to fifty years old, all who enter the company to do the work of the tent of meeting.'
EXEC add_BibleVerse @BibleId, 104004031, N'This is what they are responsible to carry as their entire service in the tent of meeting: the frames of the tabernacle, its crossbars, its posts, its sockets,'
EXEC add_BibleVerse @BibleId, 104004032, N'and the posts of the surrounding courtyard with their sockets, tent pegs, and ropes, along with all their furnishings and everything for their service. You are to assign by names the items that each man is responsible to carry.'
EXEC add_BibleVerse @BibleId, 104004033, N'This is the service of the families of the Merarites, their entire service concerning the tent of meeting, under the authority of Ithamar son of Aaron the priest.”'
EXEC add_BibleVerse @BibleId, 104004034, N'So Moses and Aaron and the leaders of the community numbered the Kohathites by their families and by clans,'
EXEC add_BibleVerse @BibleId, 104004035, N'from thirty years old and upward to fifty years old, everyone who entered the company for the work in the tent of meeting;'
EXEC add_BibleVerse @BibleId, 104004036, N'and those of them numbered by their families were 2,750.'
EXEC add_BibleVerse @BibleId, 104004037, N'These were those numbered from the families of the Kohathites, everyone who served in the tent of meeting, whom Moses and Aaron numbered according to the word of the Lord by the authority of Moses.'
EXEC add_BibleVerse @BibleId, 104004038, N'Those numbered from the Gershonites, by their families and by their clans,'
EXEC add_BibleVerse @BibleId, 104004039, N'from thirty years old and upward to fifty years old, everyone who entered the company for the work in the tent of meeting –'
EXEC add_BibleVerse @BibleId, 104004040, N'those of them numbered by their families, by their clans, were 2,630.'
EXEC add_BibleVerse @BibleId, 104004041, N'These were those numbered from the families of the Gershonites, everyone who served in the tent of meeting, whom Moses and Aaron numbered according to the word of the Lord.'
EXEC add_BibleVerse @BibleId, 104004042, N'Those numbered from the families of the Merarites, by their families, by their clans,'
EXEC add_BibleVerse @BibleId, 104004043, N'from thirty years old and upward to fifty years old, everyone who entered the company for the work in the tent of meeting –'
EXEC add_BibleVerse @BibleId, 104004044, N'those of them numbered by their families were 3,200.'
EXEC add_BibleVerse @BibleId, 104004045, N'These are those numbered from the families of the Merarites, whom Moses and Aaron numbered according to the word of the Lord by the authority of Moses.'
EXEC add_BibleVerse @BibleId, 104004046, N'All who were numbered of the Levites, whom Moses, Aaron, and the leaders of Israel numbered by their families and by their clans,'
EXEC add_BibleVerse @BibleId, 104004047, N'from thirty years old and upward to fifty years old, everyone who entered to do the work of service and the work of carrying relating to the tent of meeting –'
EXEC add_BibleVerse @BibleId, 104004048, N'those of them numbered were 8,580.'
EXEC add_BibleVerse @BibleId, 104004049, N'According to the word of the Lord they were numbered, by the authority of Moses, each according to his service and according to what he was to carry. Thus were they numbered by him, as the Lord had commanded Moses.'
EXEC add_BibleVerse @BibleId, 104005001, N'Then the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104005002, N'“Command the Israelites to expel from the camp every leper, everyone who has a discharge, and whoever becomes defiled by a corpse.'
EXEC add_BibleVerse @BibleId, 104005003, N'You must expel both men and women; you must put them outside the camp, so that they will not defile their camps, among which I live.”'
EXEC add_BibleVerse @BibleId, 104005004, N'So the Israelites did so, and expelled them outside the camp. As the Lord had spoken to Moses, so the Israelites did.'
EXEC add_BibleVerse @BibleId, 104005005, N'Then the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104005006, N'“Tell the Israelites, ‘When a man or a woman commits any sin that people commit, thereby breaking faith with the Lord, and that person is found guilty,'
EXEC add_BibleVerse @BibleId, 104005007, N'then he must confess his sin that he has committed and must make full reparation, add one fifth to it, and give it to whomever he wronged.'
EXEC add_BibleVerse @BibleId, 104005008, N'But if the individual has no close relative to whom reparation can be made for the wrong, the reparation for the wrong must be paid to the Lord for the priest, in addition to the ram of atonement by which atonement is made for him.'
EXEC add_BibleVerse @BibleId, 104005009, N'Every offering of all the Israelites’ holy things that they bring to the priest will be his.'
EXEC add_BibleVerse @BibleId, 104005010, N'Every man’s holy things will be his; whatever any man gives the priest will be his.’”'
EXEC add_BibleVerse @BibleId, 104005011, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104005012, N'“Speak to the Israelites and tell them, ‘If any man’s wife goes astray and behaves unfaithfully toward him,'
EXEC add_BibleVerse @BibleId, 104005013, N'and a man has sexual relations with her without her husband knowing it, and it is hidden that she has defiled herself, since there was no witness against her, nor was she caught –'
EXEC add_BibleVerse @BibleId, 104005014, N'and if jealous feelings come over him and he becomes suspicious of his wife, when she is defiled; or if jealous feelings come over him and he becomes suspicious of his wife, when she is not defiled –'
EXEC add_BibleVerse @BibleId, 104005015, N'then the man must bring his wife to the priest, and he must bring the offering required for her, one tenth of an ephah of barley meal; he must not pour olive oil on it or put frankincense on it, because it is a grain offering of suspicion, a grain offering for remembering, for bringing iniquity to remembrance.'
EXEC add_BibleVerse @BibleId, 104005016, N'“‘Then the priest will bring her near and have her stand before the Lord.'
EXEC add_BibleVerse @BibleId, 104005017, N'The priest will then take holy water in a pottery jar, and take some of the dust that is on the floor of the tabernacle, and put it into the water.'
EXEC add_BibleVerse @BibleId, 104005018, N'Then the priest will have the woman stand before the Lord, uncover the woman’s head, and put the grain offering for remembering in her hands, which is the grain offering of suspicion. The priest will hold in his hand the bitter water that brings a curse.'
EXEC add_BibleVerse @BibleId, 104005019, N'Then the priest will put the woman under oath and say to the her, “If no other man has had sexual relations with you, and if you have not gone astray and become defiled while under your husband’s authority, may you be free from this bitter water that brings a curse.'
EXEC add_BibleVerse @BibleId, 104005020, N'But if you have gone astray while under your husband’s authority, and if you have defiled yourself and some man other than your husband has had sexual relations with you….”'
EXEC add_BibleVerse @BibleId, 104005021, N'Then the priest will put the woman under the oath of the curse and will say to the her, “The Lord make you an attested curse among your people, if the Lord makes your thigh fall away and your abdomen swell;'
EXEC add_BibleVerse @BibleId, 104005022, N'and this water that causes the curse will go into your stomach, and make your abdomen swell and your thigh rot.” Then the woman must say, “Amen, amen.”'
EXEC add_BibleVerse @BibleId, 104005023, N'“‘Then the priest will write these curses on a scroll and then scrape them off into the bitter water.'
EXEC add_BibleVerse @BibleId, 104005024, N'He will make the woman drink the bitter water that brings a curse, and the water that brings a curse will enter her to produce bitterness.'
EXEC add_BibleVerse @BibleId, 104005025, N'The priest will take the grain offering of suspicion from the woman’s hand, wave the grain offering before the Lord, and bring it to the altar.'
EXEC add_BibleVerse @BibleId, 104005026, N'Then the priest will take a handful of the grain offering as its memorial portion, burn it on the altar, and afterward make the woman drink the water.'
EXEC add_BibleVerse @BibleId, 104005027, N'When he has made her drink the water, then, if she has defiled herself and behaved unfaithfully toward her husband, the water that brings a curse will enter her to produce bitterness – her abdomen will swell, her thigh will fall away, and the woman will become a curse among her people.'
EXEC add_BibleVerse @BibleId, 104005028, N'But if the woman has not defiled herself, and is clean, then she will be free of ill effects and will be able to bear children.'
EXEC add_BibleVerse @BibleId, 104005029, N'“‘This is the law for cases of jealousy, when a wife, while under her husband’s authority, goes astray and defiles herself,'
EXEC add_BibleVerse @BibleId, 104005030, N'or when jealous feelings come over a man and he becomes suspicious of his wife; then he must have the woman stand before the Lord, and the priest will carry out all this law upon her.'
EXEC add_BibleVerse @BibleId, 104005031, N'Then the man will be free from iniquity, but that woman will bear the consequences of her iniquity.’”'
EXEC add_BibleVerse @BibleId, 104006001, N'Then the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104006002, N'“Speak to the Israelites, and tell them, ‘When either a man or a woman takes a special vow, to take a vow as a Nazirite, to separate himself to the Lord,'
EXEC add_BibleVerse @BibleId, 104006003, N'he must separate himself from wine and strong drink, he must drink neither vinegar made from wine nor vinegar made from strong drink, nor may he drink any juice of grapes, nor eat fresh grapes or raisins.'
EXEC add_BibleVerse @BibleId, 104006004, N'All the days of his separation he must not eat anything that is produced by the grapevine, from seed to skin.'
EXEC add_BibleVerse @BibleId, 104006005, N'“‘All the days of the vow of his separation no razor may be used on his head until the time is fulfilled for which he separated himself to the Lord. He will be holy, and he must let the locks of hair on his head grow long.'
EXEC add_BibleVerse @BibleId, 104006006, N'“‘All the days that he separates himself to the Lord he must not contact a dead body.'
EXEC add_BibleVerse @BibleId, 104006007, N'He must not defile himself even for his father or his mother or his brother or his sister if they die, because the separation for his God is on his head.'
EXEC add_BibleVerse @BibleId, 104006008, N'All the days of his separation he must be holy to the Lord.'
EXEC add_BibleVerse @BibleId, 104006009, N'“‘If anyone dies very suddenly beside him and he defiles his consecrated head, then he must shave his head on the day of his purification – on the seventh day he must shave it.'
EXEC add_BibleVerse @BibleId, 104006010, N'On the eighth day he is to bring two turtledoves or two young pigeons to the priest, to the entrance to the tent of meeting.'
EXEC add_BibleVerse @BibleId, 104006011, N'Then the priest will offer one for a purification offering and the other as a burnt offering, and make atonement for him, because of his transgression in regard to the corpse. So he must reconsecrate his head on that day.'
EXEC add_BibleVerse @BibleId, 104006012, N'He must rededicate to the Lord the days of his separation and bring a male lamb in its first year as a reparation offering, but the former days will not be counted because his separation was defiled.'
EXEC add_BibleVerse @BibleId, 104006013, N'“‘Now this is the law of the Nazirite: When the days of his separation are fulfilled, he must be brought to the entrance of the tent of meeting,'
EXEC add_BibleVerse @BibleId, 104006014, N'and he must present his offering to the Lord: one male lamb in its first year without blemish for a burnt offering, one ewe lamb in its first year without blemish for a purification offering, one ram without blemish for a peace offering,'
EXEC add_BibleVerse @BibleId, 104006015, N'and a basket of bread made without yeast, cakes of fine flour mixed with olive oil, wafers made without yeast and smeared with olive oil, and their grain offering and their drink offerings.'
EXEC add_BibleVerse @BibleId, 104006016, N'“‘Then the priest must present all these before the Lord and offer his purification offering and his burnt offering.'
EXEC add_BibleVerse @BibleId, 104006017, N'Then he must offer the ram as a peace offering to the Lord, with the basket of bread made without yeast; the priest must also offer his grain offering and his drink offering.'
EXEC add_BibleVerse @BibleId, 104006018, N'“‘Then the Nazirite must shave his consecrated head at the entrance to the tent of meeting and must take the hair from his consecrated head and put it on the fire where the peace offering is burning.'
EXEC add_BibleVerse @BibleId, 104006019, N'And the priest must take the boiled shoulder of the ram, one cake made without yeast from the basket, and one wafer made without yeast, and put them on the hands of the Nazirite after he has shaved his consecrated head;'
EXEC add_BibleVerse @BibleId, 104006020, N'then the priest must wave them as a wave offering before the Lord; it is a holy portion for the priest, together with the breast of the wave offering and the thigh of the raised offering. After this the Nazirite may drink wine.’'
EXEC add_BibleVerse @BibleId, 104006021, N'“This is the law of the Nazirite who vows to the Lord his offering according to his separation, as well as whatever else he can provide. Thus he must fulfill his vow that he makes, according to the law of his separation.”'
EXEC add_BibleVerse @BibleId, 104006022, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104006023, N'“Tell Aaron and his sons, ‘This is the way you are to bless the Israelites. Say to them:'
EXEC add_BibleVerse @BibleId, 104006024, N'“The Lord bless you and protect you;'
EXEC add_BibleVerse @BibleId, 104006025, N'The Lord make his face to shine upon you, and be gracious to you;'
EXEC add_BibleVerse @BibleId, 104006026, N'The Lord lift up his countenance upon you and give you peace.”’'
EXEC add_BibleVerse @BibleId, 104006027, N'So they will put my name on the Israelites, and I will bless them.”'
EXEC add_BibleVerse @BibleId, 104007001, N'When Moses had completed setting up the tabernacle, he anointed it and consecrated it and all its furnishings, and he anointed and consecrated the altar and all its utensils.'
EXEC add_BibleVerse @BibleId, 104007002, N'Then the leaders of Israel, the heads of their clans, made an offering. They were the leaders of the tribes; they were the ones who had been supervising the numbering.'
EXEC add_BibleVerse @BibleId, 104007003, N'They brought their offering before the Lord, six covered carts and twelve oxen – one cart for every two of the leaders, and an ox for each one; and they presented them in front of the tabernacle.'
EXEC add_BibleVerse @BibleId, 104007004, N'Then the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104007005, N'“Receive these gifts from them, that they may be used in doing the work of the tent of meeting; and you must give them to the Levites, to every man as his service requires.”'
EXEC add_BibleVerse @BibleId, 104007006, N'So Moses accepted the carts and the oxen and gave them to the Levites.'
EXEC add_BibleVerse @BibleId, 104007007, N'He gave two carts and four oxen to the Gershonites, as their service required;'
EXEC add_BibleVerse @BibleId, 104007008, N'and he gave four carts and eight oxen to the Merarites, as their service required, under the authority of Ithamar son of Aaron the priest.'
EXEC add_BibleVerse @BibleId, 104007009, N'But to the Kohathites he gave none, because the service of the holy things, which they carried on their shoulders, was their responsibility.'
EXEC add_BibleVerse @BibleId, 104007010, N'The leaders offered gifts for the dedication of the altar when it was anointed. And the leaders presented their offering before the altar.'
EXEC add_BibleVerse @BibleId, 104007011, N'For the Lord said to Moses, “They must present their offering, one leader for each day, for the dedication of the altar.”'
EXEC add_BibleVerse @BibleId, 104007012, N'The one who presented his offering on the first day was Nahshon son of Amminadab, from the tribe of Judah.'
EXEC add_BibleVerse @BibleId, 104007013, N'His offering was one silver platter weighing 130 shekels, and one silver sprinkling bowl weighing 70 shekels, both according to the sanctuary shekel, each of them full of fine flour mixed with olive oil as a grain offering;'
EXEC add_BibleVerse @BibleId, 104007014, N'one gold pan weighing 10 shekels, full of incense;'
EXEC add_BibleVerse @BibleId, 104007015, N'one young bull, one ram, and one male lamb in its first year, for a burnt offering;'
EXEC add_BibleVerse @BibleId, 104007016, N'one male goat for a purification offering;'
EXEC add_BibleVerse @BibleId, 104007017, N'and for the sacrifice of peace offerings: two bulls, five rams, five male goats, and five male lambs in their first year. This was the offering of Nahshon son of Amminadab.'
EXEC add_BibleVerse @BibleId, 104007018, N'On the second day Nethanel son of Zuar, leader of Issachar, presented an offering.'
EXEC add_BibleVerse @BibleId, 104007019, N'He offered for his offering one silver platter weighing 130 shekels and one silver sprinkling bowl weighing 70, both according to the sanctuary shekel, each of them full of fine flour mixed with olive oil as a grain offering;'
EXEC add_BibleVerse @BibleId, 104007020, N'one gold pan weighing 10 shekels, full of incense;'
EXEC add_BibleVerse @BibleId, 104007021, N'one young bull, one ram, and one male lamb in its first year, for a burnt offering;'
EXEC add_BibleVerse @BibleId, 104007022, N'one male goat for a purification offering;'
EXEC add_BibleVerse @BibleId, 104007023, N'and for the sacrifice of peace offerings: two bulls, five rams, five male goats, and five male lambs in their first year. This was the offering of Nethanel son of Zuar.'
EXEC add_BibleVerse @BibleId, 104007024, N'On the third day Eliab son of Helon, leader of the Zebulunites, presented an offering.'
EXEC add_BibleVerse @BibleId, 104007025, N'His offering was one silver platter weighing 130 shekels and one silver sprinkling bowl weighing 70 shekels, both according to the sanctuary shekel, each of them full of fine flour mixed with olive oil as a grain offering;'
EXEC add_BibleVerse @BibleId, 104007026, N'one gold pan weighing 10 shekels, full of incense;'
EXEC add_BibleVerse @BibleId, 104007027, N'one young bull, one ram, and one male lamb in its first year, for a burnt offering;'
EXEC add_BibleVerse @BibleId, 104007028, N'one male goat for a purification offering;'
EXEC add_BibleVerse @BibleId, 104007029, N'and for the sacrifice of peace offerings: two bulls, five rams, five male goats, and five male lambs in their first year. This was the offering of Eliab son of Helon.'
EXEC add_BibleVerse @BibleId, 104007030, N'On the fourth day Elizur son of Shedeur, leader of the Reubenites, presented an offering.'
EXEC add_BibleVerse @BibleId, 104007031, N'His offering was one silver platter weighing 130 shekels and one silver sprinkling bowl weighing 70 shekels, both according to the sanctuary shekel, each of them full of fine flour mixed with olive oil as a grain offering;'
EXEC add_BibleVerse @BibleId, 104007032, N'one gold pan weighing 10 shekels, full of incense;'
EXEC add_BibleVerse @BibleId, 104007033, N'one young bull, one ram, and one male lamb in its first year, for a burnt offering;'
EXEC add_BibleVerse @BibleId, 104007034, N'one male goat for a purification offering;'
EXEC add_BibleVerse @BibleId, 104007035, N'and for the sacrifice of peace offerings: two bulls, five rams, five male goats, and five lambs in their first year. This was the offering of Elizur son of Shedeur.'
EXEC add_BibleVerse @BibleId, 104007036, N'On the fifth day Shelumiel son of Zurishaddai, leader of the Simeonites, presented an offering.'
EXEC add_BibleVerse @BibleId, 104007037, N'His offering was one silver platter weighing 130 shekels and one silver sprinkling bowl weighing 70 shekels, both according to the sanctuary shekel, each of them full of fine flour mixed with olive oil as a grain offering;'
EXEC add_BibleVerse @BibleId, 104007038, N'one gold pan weighing 10 shekels;'
EXEC add_BibleVerse @BibleId, 104007039, N'one young bull, one ram, and one male lamb in its first year, for a burnt offering;'
EXEC add_BibleVerse @BibleId, 104007040, N'one male goat for a purification offering;'
EXEC add_BibleVerse @BibleId, 104007041, N'and for the sacrifice of peace offerings: two bulls, five rams, five male goats, and five lambs in their first year. This was the offering of Sheloumiel son of Zurishaddai.'
EXEC add_BibleVerse @BibleId, 104007042, N'On the sixth day Eliasaph son of Deuel, leader of the Gadites, presented an offering.'
EXEC add_BibleVerse @BibleId, 104007043, N'His offering was one silver platter weighing 130 shekels and one silver sprinkling bowl weighing 70 shekels, both according to the sanctuary shekel, each of them full of fine flour mixed with olive oil as a grain offering;'
EXEC add_BibleVerse @BibleId, 104007044, N'one gold pan weighing 10 shekels;'
EXEC add_BibleVerse @BibleId, 104007045, N'one young bull, one ram, and one male lamb in its first year, for a burnt offering;'
EXEC add_BibleVerse @BibleId, 104007046, N'one male goat for a purification offering;'
EXEC add_BibleVerse @BibleId, 104007047, N'and for the sacrifice of peace offerings: two bulls, five rams, five male goats, and five lambs in their first year. This was the offering of Eliasaph son of Deuel.'
EXEC add_BibleVerse @BibleId, 104007048, N'On the seventh day Elishama son of Ammihud, leader of the Ephraimites, presented an offering.'
EXEC add_BibleVerse @BibleId, 104007049, N'His offering was one silver platter weighing 130 shekels and one silver sprinkling bowl weighing 70 shekels, both according to the sanctuary shekel, each of them full of fine flour mixed with olive oil as a grain offering;'
EXEC add_BibleVerse @BibleId, 104007050, N'one gold pan weighing 10 shekels, full of incense;'
EXEC add_BibleVerse @BibleId, 104007051, N'one young bull, one ram, and one male lamb in its first year, for a burnt offering;'
EXEC add_BibleVerse @BibleId, 104007052, N'one male goat for a purification offering;'
EXEC add_BibleVerse @BibleId, 104007053, N'and for the sacrifice of peace offerings: two bulls, five rams, five male goats, and five lambs in their first year. This was the offering of Elishama son of Ammihud.'
EXEC add_BibleVerse @BibleId, 104007054, N'On the eighth day Gamaliel son of Pedahzur, leader of the Manassehites, presented an offering.'
EXEC add_BibleVerse @BibleId, 104007055, N'His offering was one silver platter weighing 130 shekels and one silver sprinkling bowl weighing 70 shekels, both according to the sanctuary shekel, each of them full of fine flour mixed with olive oil as a grain offering;'
EXEC add_BibleVerse @BibleId, 104007056, N'one gold pan weighing 10 shekels, full of incense;'
EXEC add_BibleVerse @BibleId, 104007057, N'one young bull, one ram, and one male lamb in its first year, for a burnt offering;'
EXEC add_BibleVerse @BibleId, 104007058, N'one male goat for a purification offering;'
EXEC add_BibleVerse @BibleId, 104007059, N'and for the sacrifice of peace offerings: two bulls, five rams, five male goats, and five lambs in their first year. This was the offering of Gamaliel son of Pedahzur.'
EXEC add_BibleVerse @BibleId, 104007060, N'On the ninth day Abidan son of Gideoni, leader of the Benjaminites, presented an offering.'
EXEC add_BibleVerse @BibleId, 104007061, N'His offering was one silver platter weighing 130 shekels and one silver sprinkling bowl weighing 70 shekels, both according to the sanctuary shekel, each of them full of fine flour mixed with olive oil as a grain offering;'
EXEC add_BibleVerse @BibleId, 104007062, N'one gold pan weighing 10 shekels, full of incense;'
EXEC add_BibleVerse @BibleId, 104007063, N'one young bull, one ram, and one male lamb in its first year, for a burnt offering;'
EXEC add_BibleVerse @BibleId, 104007064, N'one male goat for a purification offering;'
EXEC add_BibleVerse @BibleId, 104007065, N'and for the sacrifice of peace offerings: two bulls, five rams, five male goats, and five lambs in their first year. This was the offering of Abidan son of Gideoni.'
EXEC add_BibleVerse @BibleId, 104007066, N'On the tenth day Ahiezer son of Amishaddai, leader of the Danites, presented an offering.'
EXEC add_BibleVerse @BibleId, 104007067, N'His offering was one silver platter weighing 130 shekels and one silver sprinkling bowl weighing 70 shekels, both according to the sanctuary shekel, each of them full of fine flour mixed with olive oil as a grain offering;'
EXEC add_BibleVerse @BibleId, 104007068, N'one gold pan weighing 10 shekels, full of incense;'
EXEC add_BibleVerse @BibleId, 104007069, N'one young bull, one ram, and one male lamb in its first year, for a burnt offering;'
EXEC add_BibleVerse @BibleId, 104007070, N'one male goat for a purification offering;'
EXEC add_BibleVerse @BibleId, 104007071, N'and for the sacrifice of peace offerings: two bulls, five rams, five male goats, and five lambs in their first year. This was the offering of Ahiezer son of Amishaddai.'
EXEC add_BibleVerse @BibleId, 104007072, N'On the eleventh day Pagiel son of Ocran, leader of the Asherites, presented an offering.'
EXEC add_BibleVerse @BibleId, 104007073, N'His offering was one silver platter weighing 130 shekels and one silver sprinkling bowl weighing 70 shekels, both according to the sanctuary shekel, each of them full of fine flour mixed with olive oil as a grain offering;'
EXEC add_BibleVerse @BibleId, 104007074, N'one gold pan weighing 10 shekels, full of incense;'
EXEC add_BibleVerse @BibleId, 104007075, N'one young bull, one ram, and one male lamb in its first year, for a burnt offering;'
EXEC add_BibleVerse @BibleId, 104007076, N'one male goat for a purification offering;'
EXEC add_BibleVerse @BibleId, 104007077, N'and for the sacrifice of peace offerings: two bulls, five rams, five male goats, and five lambs in their first year. This was the offering of Pagiel son of Ocran.'
EXEC add_BibleVerse @BibleId, 104007078, N'On the twelfth day Ahira son of Enan, leader of the Naphtalites, presented an offering.'
EXEC add_BibleVerse @BibleId, 104007079, N'His offering was one silver platter weighing 130 shekels and one silver sprinkling bowl weighing 70 shekels, both according to the sanctuary shekel, each of them full of fine flour mixed with olive oil as a grain offering;'
EXEC add_BibleVerse @BibleId, 104007080, N'one gold pan weighing 10 shekels;'
EXEC add_BibleVerse @BibleId, 104007081, N'one young bull, one ram, and one male lamb in its first year, for a burnt offering;'
EXEC add_BibleVerse @BibleId, 104007082, N'one male goat for a purification offering;'
EXEC add_BibleVerse @BibleId, 104007083, N'and for the sacrifice of peace offerings: two bulls, five rams, five male goats, and five lambs in their first year. This was the offering of Ahira son of Enan.'
EXEC add_BibleVerse @BibleId, 104007084, N'This was the dedication for the altar from the leaders of Israel, when it was anointed: twelve silver platters, twelve silver sprinkling bowls, and twelve gold pans.'
EXEC add_BibleVerse @BibleId, 104007085, N'Each silver platter weighed 130 shekels, and each silver sprinkling bowl weighed 70 shekels. All the silver of the vessels weighed 2,400 shekels, according to the sanctuary shekel.'
EXEC add_BibleVerse @BibleId, 104007086, N'The twelve gold pans full of incense weighed 10 shekels each, according to the sanctuary shekel; all the gold of the pans weighed 120 shekels.'
EXEC add_BibleVerse @BibleId, 104007087, N'All the animals for the burnt offering were 12 young bulls, 12 rams, 12 male lambs in their first year, with their grain offering, and 12 male goats for a purification offering.'
EXEC add_BibleVerse @BibleId, 104007088, N'All the animals for the sacrifice for the peace offering were 24 young bulls, 60 rams, 60 male goats, and 60 lambs in their first year. These were the dedication offerings for the altar after it was anointed.'
EXEC add_BibleVerse @BibleId, 104007089, N'Now when Moses went into the tent of meeting to speak with the Lord, he heard the voice speaking to him from above the atonement lid that was on the ark of the testimony, from between the two cherubim. Thus he spoke to him.'
EXEC add_BibleVerse @BibleId, 104008001, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104008002, N'“Speak to Aaron and tell him, ‘When you set up the lamps, the seven lamps are to give light in front of the lampstand.’”'
EXEC add_BibleVerse @BibleId, 104008003, N'And Aaron did so; he set up the lamps to face toward the front of the lampstand, as the Lord commanded Moses.'
EXEC add_BibleVerse @BibleId, 104008004, N'This is how the lampstand was made: It was beaten work in gold; from its shaft to its flowers it was beaten work. According to the pattern which the Lord had shown Moses, so he made the lampstand.'
EXEC add_BibleVerse @BibleId, 104008005, N'Then the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104008006, N'“Take the Levites from among the Israelites and purify them.'
EXEC add_BibleVerse @BibleId, 104008007, N'And do this to them to purify them: Sprinkle water of purification on them; then have them shave all their body and wash their clothes, and so purify themselves.'
EXEC add_BibleVerse @BibleId, 104008008, N'Then they are to take a young bull with its grain offering of fine flour mixed with olive oil; and you are to take a second young bull for a purification offering.'
EXEC add_BibleVerse @BibleId, 104008009, N'You are to bring the Levites before the tent of meeting and assemble the entire community of the Israelites.'
EXEC add_BibleVerse @BibleId, 104008010, N'Then you are to bring the Levites before the Lord, and the Israelites are to lay their hands on the Levites;'
EXEC add_BibleVerse @BibleId, 104008011, N'and Aaron is to offer the Levites before the Lord as a wave offering from the Israelites, that they may do the work of the Lord.'
EXEC add_BibleVerse @BibleId, 104008012, N'When the Levites lay their hands on the heads of the bulls, offer the one for a purification offering and the other for a whole burnt offering to the Lord, to make atonement for the Levites.'
EXEC add_BibleVerse @BibleId, 104008013, N'You are to have the Levites stand before Aaron and his sons, and then offer them as a wave offering to the Lord.'
EXEC add_BibleVerse @BibleId, 104008014, N'And so you are to separate the Levites from among the Israelites, and the Levites will be mine.'
EXEC add_BibleVerse @BibleId, 104008015, N'“After this, the Levites will go in to do the work of the tent of meeting. So you must cleanse them and offer them like a wave offering.'
EXEC add_BibleVerse @BibleId, 104008016, N'For they are entirely given to me from among the Israelites. I have taken them for myself instead of all who open the womb, the firstborn sons of all the Israelites.'
EXEC add_BibleVerse @BibleId, 104008017, N'For all the firstborn males among the Israelites are mine, both humans and animals; when I destroyed all the firstborn in the land of Egypt I set them apart for myself.'
EXEC add_BibleVerse @BibleId, 104008018, N'So I have taken the Levites instead of all the firstborn sons among the Israelites.'
EXEC add_BibleVerse @BibleId, 104008019, N'I have given the Levites as a gift to Aaron and his sons from among the Israelites, to do the work for the Israelites in the tent of meeting, and to make atonement for the Israelites, so there will be no plague among the Israelites when the Israelites come near the sanctuary.”'
EXEC add_BibleVerse @BibleId, 104008020, N'So Moses and Aaron and the entire community of the Israelites did this with the Levites. According to all that the Lord commanded Moses concerning the Levites, this is what the Israelites did with them.'
EXEC add_BibleVerse @BibleId, 104008021, N'The Levites purified themselves and washed their clothing; then Aaron presented them like a wave offering before the Lord, and Aaron made atonement for them to purify them.'
EXEC add_BibleVerse @BibleId, 104008022, N'After this, the Levites went in to do their work in the tent of meeting before Aaron and before his sons. As the Lord had commanded Moses concerning the Levites, so they did.'
EXEC add_BibleVerse @BibleId, 104008023, N'Then the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104008024, N'“This is what pertains to the Levites: At the age of twenty-five years and upward one may begin to join the company in the work of the tent of meeting,'
EXEC add_BibleVerse @BibleId, 104008025, N'and at the age of fifty years they must retire from performing the work and may no longer work.'
EXEC add_BibleVerse @BibleId, 104008026, N'They may assist their colleagues in the tent of meeting, to attend to needs, but they must do no work. This is the way you must establish the Levites regarding their duties.”'
EXEC add_BibleVerse @BibleId, 104009001, N'The Lord spoke to Moses in the wilderness of Sinai, in the first month of the second year after they had come out of the land of Egypt:'
EXEC add_BibleVerse @BibleId, 104009002, N'“The Israelites are to observe the Passover at its appointed time.'
EXEC add_BibleVerse @BibleId, 104009003, N'In the fourteenth day of this month, at twilight, you are to observe it at its appointed time; you must keep it in accordance with all its statutes and all its customs.”'
EXEC add_BibleVerse @BibleId, 104009004, N'So Moses instructed the Israelites to observe the Passover.'
EXEC add_BibleVerse @BibleId, 104009005, N'And they observed the Passover on the fourteenth day of the first month at twilight in the wilderness of Sinai; in accordance with all that the Lord had commanded Moses, so the Israelites did.'
EXEC add_BibleVerse @BibleId, 104009006, N'It happened that some men who were ceremonially defiled by the dead body of a man could not keep the Passover on that day, so they came before Moses and before Aaron on that day.'
EXEC add_BibleVerse @BibleId, 104009007, N'And those men said to him, “We are ceremonially defiled by the dead body of a man; why are we kept back from offering the Lord’s offering at its appointed time among the Israelites?”'
EXEC add_BibleVerse @BibleId, 104009008, N'So Moses said to them, “Remain here and I will hear what the Lord will command concerning you.”'
EXEC add_BibleVerse @BibleId, 104009009, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104009010, N'“Tell the Israelites, ‘If any of you or of your posterity become ceremonially defiled by touching a dead body, or are on a journey far away, then he may observe the Passover to the Lord.'
EXEC add_BibleVerse @BibleId, 104009011, N'They may observe it on the fourteenth day of the second month at twilight; they are to eat it with bread made without yeast and with bitter herbs.'
EXEC add_BibleVerse @BibleId, 104009012, N'They must not leave any of it until morning, nor break any of its bones; they must observe it in accordance with every statute of the Passover.'
EXEC add_BibleVerse @BibleId, 104009013, N'But the man who is ceremonially clean, and was not on a journey, and fails to keep the Passover, that person must be cut off from his people. Because he did not bring the Lord’s offering at its appointed time, that man must bear his sin.'
EXEC add_BibleVerse @BibleId, 104009014, N'If a resident foreigner lives among you and wants to keep the Passover to the Lord, he must do so according to the statute of the Passover, and according to its custom. You must have the same statute for the resident foreigner and for the one who was born in the land.’”'
EXEC add_BibleVerse @BibleId, 104009015, N'On the day that the tabernacle was set up, the cloud covered the tabernacle – the tent of the testimony – and from evening until morning there was a fiery appearance over the tabernacle.'
EXEC add_BibleVerse @BibleId, 104009016, N'This is the way it used to be continually: The cloud would cover it by day, and there was a fiery appearance by night.'
EXEC add_BibleVerse @BibleId, 104009017, N'Whenever the cloud was taken up from the tabernacle, then after that the Israelites would begin their journey; and in whatever place the cloud settled, there the Israelites would make camp.'
EXEC add_BibleVerse @BibleId, 104009018, N'At the commandment of the Lord the Israelites would begin their journey, and at the commandment of the Lord they would make camp; as long as the cloud remained settled over the tabernacle they would camp.'
EXEC add_BibleVerse @BibleId, 104009019, N'When the cloud remained over the tabernacle many days, then the Israelites obeyed the instructions of the Lord and did not journey.'
EXEC add_BibleVerse @BibleId, 104009020, N'When the cloud remained over the tabernacle a number of days, they remained camped according to the Lord’s commandment, and according to the Lord’s commandment they would journey.'
EXEC add_BibleVerse @BibleId, 104009021, N'And when the cloud remained only from evening until morning, when the cloud was taken up the following morning, then they traveled on. Whether by day or by night, when the cloud was taken up they traveled.'
EXEC add_BibleVerse @BibleId, 104009022, N'Whether it was for two days, or a month, or a year, that the cloud prolonged its stay over the tabernacle, the Israelites remained camped without traveling; but when it was taken up, they traveled on.'
EXEC add_BibleVerse @BibleId, 104009023, N'At the commandment of the Lord they camped, and at the commandment of the Lord they traveled on; they kept the instructions of the Lord according to the commandment of the Lord, by the authority of Moses.'
EXEC add_BibleVerse @BibleId, 104010001, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104010002, N'“Make two trumpets of silver; you are to make them from a single hammered piece. You will use them for assembling the community and for directing the traveling of the camps.'
EXEC add_BibleVerse @BibleId, 104010003, N'When they blow them both, all the community must come to you to the entrance of the tent of meeting.'
EXEC add_BibleVerse @BibleId, 104010004, N'“But if they blow with one trumpet, then the leaders, the heads of the thousands of Israel, must come to you.'
EXEC add_BibleVerse @BibleId, 104010005, N'When you blow an alarm, then the camps that are located on the east side must begin to travel.'
EXEC add_BibleVerse @BibleId, 104010006, N'And when you blow an alarm the second time, then the camps that are located on the south side must begin to travel. An alarm must be sounded for their journeys.'
EXEC add_BibleVerse @BibleId, 104010007, N'But when you assemble the community, you must blow, but you must not sound an alarm.'
EXEC add_BibleVerse @BibleId, 104010008, N'The sons of Aaron, the priests, must blow the trumpets; and they will be to you for an eternal ordinance throughout your generations.'
EXEC add_BibleVerse @BibleId, 104010009, N'If you go to war in your land against an adversary who opposes you, then you must sound an alarm with the trumpets, and you will be remembered before the Lord your God, and you will be saved from your enemies.'
EXEC add_BibleVerse @BibleId, 104010010, N'“Also in the time when you rejoice, such as on your appointed festivals or at the beginnings of your months, you must blow with your trumpets over your burnt offerings and over the sacrifices of your peace offerings, so that they may become a memorial for you before your God: I am the Lord your God.”'
EXEC add_BibleVerse @BibleId, 104010011, N'On the twentieth day of the second month, in the second year, the cloud was taken up from the tabernacle of the testimony.'
EXEC add_BibleVerse @BibleId, 104010012, N'So the Israelites set out on their journeys from the wilderness of Sinai; and the cloud settled in the wilderness of Paran.'
EXEC add_BibleVerse @BibleId, 104010013, N'This was the first time they set out on their journey according to the commandment of the Lord, by the authority of Moses.'
EXEC add_BibleVerse @BibleId, 104010014, N'The standard of the camp of the Judahites set out first according to their companies, and over his company was Nahshon son of Amminadab.'
EXEC add_BibleVerse @BibleId, 104010015, N'Over the company of the tribe of Issacharites was Nathanel son of Zuar,'
EXEC add_BibleVerse @BibleId, 104010016, N'and over the company of the tribe of the Zebulunites was Elion son of Helon.'
EXEC add_BibleVerse @BibleId, 104010017, N'Then the tabernacle was dismantled, and the sons of Gershon and the sons of Merari set out, carrying the tabernacle.'
EXEC add_BibleVerse @BibleId, 104010018, N'The standard of the camp of Reuben set out according to their companies; over his company was Elizur son of Shedeur.'
EXEC add_BibleVerse @BibleId, 104010019, N'Over the company of the tribe of the Simeonites was Shelumiel son of Zurishaddai,'
EXEC add_BibleVerse @BibleId, 104010020, N'and over the company of the tribe of the Gadites was Eliasaph son of Deuel.'
EXEC add_BibleVerse @BibleId, 104010021, N'And the Kohathites set out, carrying the articles for the sanctuary; the tabernacle was to be set up before they arrived.'
EXEC add_BibleVerse @BibleId, 104010022, N'And the standard of the camp of the Ephraimites set out according to their companies; over his company was Elishama son of Ammihud.'
EXEC add_BibleVerse @BibleId, 104010023, N'Over the company of the tribe of the Manassehites was Gamaliel son of Pedahzur,'
EXEC add_BibleVerse @BibleId, 104010024, N'and over the company of the tribe of Benjaminites was Abidan son of Gideoni.'
EXEC add_BibleVerse @BibleId, 104010025, N'The standard of the camp of the Danites set out, which was the rear guard of all the camps by their companies; over his company was Ahiezer son of Ammishaddai.'
EXEC add_BibleVerse @BibleId, 104010026, N'Over the company of the tribe of the Asherites was Pagiel son of Ocran,'
EXEC add_BibleVerse @BibleId, 104010027, N'and over the company of the tribe of the Naphtalites was Ahira son of Enan.'
EXEC add_BibleVerse @BibleId, 104010028, N'These were the traveling arrangements of the Israelites according to their companies when they traveled.'
EXEC add_BibleVerse @BibleId, 104010029, N'Moses said to Hobab son of Reuel, the Midianite, Moses’ father-in-law, “We are journeying to the place about which the Lord said, ‘I will give it to you.’ Come with us and we will treat you well, for the Lord has promised good things for Israel.”'
EXEC add_BibleVerse @BibleId, 104010030, N'But Hobab said to him, “I will not go, but I will go instead to my own land and to my kindred.”'
EXEC add_BibleVerse @BibleId, 104010031, N'Moses said, “Do not leave us, because you know places for us to camp in the wilderness, and you could be our guide.'
EXEC add_BibleVerse @BibleId, 104010032, N'And if you come with us, it is certain that whatever good things the Lord will favor us with, we will share with you as well.”'
EXEC add_BibleVerse @BibleId, 104010033, N'So they traveled from the mountain of the Lord three days’ journey; and the ark of the covenant of the Lord was traveling before them during the three days’ journey, to find a resting place for them.'
EXEC add_BibleVerse @BibleId, 104010034, N'And the cloud of the Lord was over them by day, when they traveled from the camp.'
EXEC add_BibleVerse @BibleId, 104010035, N'And when the ark traveled, Moses would say, “Rise up, O Lord! May your enemies be scattered, and may those who hate you flee before you!”'
EXEC add_BibleVerse @BibleId, 104010036, N'And when it came to rest he would say, “Return, O Lord, to the many thousands of Israel!”'
EXEC add_BibleVerse @BibleId, 104011001, N'When the people complained, it displeased the Lord. When the Lord heard it, his anger burned, and so the fire of the Lord burned among them and consumed some of the outer parts of the camp.'
EXEC add_BibleVerse @BibleId, 104011002, N'When the people cried to Moses, he prayed to the Lord, and the fire died out.'
EXEC add_BibleVerse @BibleId, 104011003, N'So he called the name of that place Taberah because there the fire of the Lord burned among them.'
EXEC add_BibleVerse @BibleId, 104011004, N'Now the mixed multitude who were among them craved more desirable foods, and so the Israelites wept again and said, “If only we had meat to eat!'
EXEC add_BibleVerse @BibleId, 104011005, N'We remember the fish we used to eat freely in Egypt, the cucumbers, the melons, the leeks, the onions, and the garlic.'
EXEC add_BibleVerse @BibleId, 104011006, N'But now we are dried up, and there is nothing at all before us except this manna!”'
EXEC add_BibleVerse @BibleId, 104011007, N'(Now the manna was like coriander seed, and its color like the color of bdellium.'
EXEC add_BibleVerse @BibleId, 104011008, N'And the people went about and gathered it, and ground it with mills or pounded it in mortars; they baked it in pans and made cakes of it. It tasted like fresh olive oil.'
EXEC add_BibleVerse @BibleId, 104011009, N'And when the dew came down on the camp in the night, the manna fell with it.)'
EXEC add_BibleVerse @BibleId, 104011010, N'Moses heard the people weeping throughout their families, everyone at the door of his tent; and when the anger of the Lord was kindled greatly, Moses was also displeased.'
EXEC add_BibleVerse @BibleId, 104011011, N'And Moses said to the Lord, “Why have you afflicted your servant? Why have I not found favor in your sight, that you lay the burden of this entire people on me?'
EXEC add_BibleVerse @BibleId, 104011012, N'Did I conceive this entire people? Did I give birth to them, that you should say to me, ‘Carry them in your arms, as a foster father bears a nursing child,’ to the land which you swore to their fathers?'
EXEC add_BibleVerse @BibleId, 104011013, N'From where shall I get meat to give to this entire people, for they cry to me, ‘Give us meat, that we may eat!’'
EXEC add_BibleVerse @BibleId, 104011014, N'I am not able to bear this entire people alone, because it is too heavy for me!'
EXEC add_BibleVerse @BibleId, 104011015, N'But if you are going to deal with me like this, then kill me immediately. If I have found favor in your sight then do not let me see my trouble.”'
EXEC add_BibleVerse @BibleId, 104011016, N'The Lord said to Moses, “Gather to me seventy men of the elders of Israel, whom you know are elders of the people and officials over them, and bring them to the tent of meeting; let them take their position there with you.'
EXEC add_BibleVerse @BibleId, 104011017, N'Then I will come down and speak with you there, and I will take part of the spirit that is on you, and will put it on them, and they will bear some of the burden of the people with you, so that you do not bear it all by yourself.'
EXEC add_BibleVerse @BibleId, 104011018, N'“And say to the people, ‘Sanctify yourselves for tomorrow, and you will eat meat, for you have wept in the hearing of the Lord, saying, “Who will give us meat to eat, for life was good for us in Egypt?” Therefore the Lord will give you meat, and you will eat.'
EXEC add_BibleVerse @BibleId, 104011019, N'You will eat, not just one day, nor two days, nor five days, nor ten days, nor twenty days,'
EXEC add_BibleVerse @BibleId, 104011020, N'but a whole month, until it comes out your nostrils and makes you sick, because you have despised the Lord who is among you and have wept before him, saying, “Why did we ever come out of Egypt?”’”'
EXEC add_BibleVerse @BibleId, 104011021, N'Moses said, “The people around me are 600,000 on foot; but you say, ‘I will give them meat, that they may eat for a whole month.’'
EXEC add_BibleVerse @BibleId, 104011022, N'Would they have enough if the flocks and herds were slaughtered for them? If all the fish of the sea were caught for them, would they have enough?”'
EXEC add_BibleVerse @BibleId, 104011023, N'And the Lord said to Moses, “Is the Lord’s hand shortened? Now you will see whether my word to you will come true or not!”'
EXEC add_BibleVerse @BibleId, 104011024, N'So Moses went out and told the people the words of the Lord. He then gathered seventy men of the elders of the people and had them stand around the tabernacle.'
EXEC add_BibleVerse @BibleId, 104011025, N'And the Lord came down in the cloud and spoke to them, and he took some of the Spirit that was on Moses and put it on the seventy elders. When the Spirit rested on them, they prophesied, but did not do so again.'
EXEC add_BibleVerse @BibleId, 104011026, N'But two men remained in the camp; one’s name was Eldad, and the other’s name was Medad. And the spirit rested on them. (Now they were among those in the registration, but had not gone to the tabernacle.) So they prophesied in the camp.'
EXEC add_BibleVerse @BibleId, 104011027, N'And a young man ran and told Moses, “Eldad and Medad are prophesying in the camp!”'
EXEC add_BibleVerse @BibleId, 104011028, N'Joshua son of Nun, the servant of Moses, one of his choice young men, said, “My lord Moses, stop them!”'
EXEC add_BibleVerse @BibleId, 104011029, N'Moses said to him, “Are you jealous for me? I wish that all the Lord’s people were prophets, that the Lord would put his Spirit on them!”'
EXEC add_BibleVerse @BibleId, 104011030, N'Then Moses returned to the camp along with the elders of Israel.'
EXEC add_BibleVerse @BibleId, 104011031, N'Now a wind went out from the Lord and brought quail from the sea, and let them fall near the camp, about a day’s journey on this side, and about a day’s journey on the other side, all around the camp, and about three feet high on the surface of the ground.'
EXEC add_BibleVerse @BibleId, 104011032, N'And the people stayed up all that day, all that night, and all the next day, and gathered the quail. The one who gathered the least gathered ten homers, and they spread them out for themselves all around the camp.'
EXEC add_BibleVerse @BibleId, 104011033, N'But while the meat was still between their teeth, before they chewed it, the anger of the Lord burned against the people, and the Lord struck the people with a very great plague.'
EXEC add_BibleVerse @BibleId, 104011034, N'So the name of that place was called Kibroth Hattaavah, because there they buried the people that craved different food.'
EXEC add_BibleVerse @BibleId, 104011035, N'The people traveled from Kibroth Hattaavah to Hazeroth, and they stayed at Hazeroth.'
EXEC add_BibleVerse @BibleId, 104012001, N'Then Miriam and Aaron spoke against Moses because of the Cushite woman he had married (for he had married an Ethiopian woman).'
EXEC add_BibleVerse @BibleId, 104012002, N'They said, “Has the Lord only spoken through Moses? Has he not also spoken through us?” And the Lord heard it.'
EXEC add_BibleVerse @BibleId, 104012003, N'(Now the man Moses was very humble, more so than any man on the face of the earth.)'
EXEC add_BibleVerse @BibleId, 104012004, N'The Lord spoke immediately to Moses, Aaron, and Miriam: “The three of you come to the tent of meeting.” So the three of them went.'
EXEC add_BibleVerse @BibleId, 104012005, N'And the Lord came down in a pillar of cloud and stood at the entrance of the tent; he then called Aaron and Miriam, and they both came forward.'
EXEC add_BibleVerse @BibleId, 104012006, N'The Lord said, “Hear now my words: If there is a prophet among you, I the Lord will make myself known to him in a vision; I will speak with him in a dream.'
EXEC add_BibleVerse @BibleId, 104012007, N'My servant Moses is not like this; he is faithful in all my house.'
EXEC add_BibleVerse @BibleId, 104012008, N'With him I will speak face to face, openly, and not in riddles; and he will see the form of the Lord. Why then were you not afraid to speak against my servant Moses?”'
EXEC add_BibleVerse @BibleId, 104012009, N'The anger of the Lord burned against them, and he departed.'
EXEC add_BibleVerse @BibleId, 104012010, N'When the cloud departed from above the tent, Miriam became leprous as snow. Then Aaron looked at Miriam, and she was leprous!'
EXEC add_BibleVerse @BibleId, 104012011, N'So Aaron said to Moses, “O my lord, please do not hold this sin against us, in which we have acted foolishly and have sinned!'
EXEC add_BibleVerse @BibleId, 104012012, N'Do not let her be like a baby born dead, whose flesh is half-consumed when it comes out of its mother’s womb!”'
EXEC add_BibleVerse @BibleId, 104012013, N'Then Moses cried to the Lord, “Heal her now, O God.”'
EXEC add_BibleVerse @BibleId, 104012014, N'The Lord said to Moses, “If her father had only spit in her face, would she not have been disgraced for seven days? Shut her out from the camp seven days, and afterward she can be brought back in again.”'
EXEC add_BibleVerse @BibleId, 104012015, N'So Miriam was shut outside of the camp for seven days, and the people did not journey on until Miriam was brought back in.'
EXEC add_BibleVerse @BibleId, 104012016, N'After that the people moved from Hazeroth and camped in the wilderness of Paran.'
EXEC add_BibleVerse @BibleId, 104013001, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104013002, N'“Send out men to investigate the land of Canaan, which I am giving to the Israelites. You are to send one man from each ancestral tribe, each one a leader among them.”'
EXEC add_BibleVerse @BibleId, 104013003, N'So Moses sent them from the wilderness of Paran at the command of the Lord. All of them were leaders of the Israelites.'
EXEC add_BibleVerse @BibleId, 104013004, N'Now these were their names: from the tribe of Reuben, Shammua son of Zaccur;'
EXEC add_BibleVerse @BibleId, 104013005, N'from the tribe of Simeon, Shaphat son of Hori;'
EXEC add_BibleVerse @BibleId, 104013006, N'from the tribe of Judah, Caleb son of Jephunneh;'
EXEC add_BibleVerse @BibleId, 104013007, N'from the tribe of Issachar, Igal son of Joseph;'
EXEC add_BibleVerse @BibleId, 104013008, N'from the tribe of Ephraim, Hoshea son of Nun;'
EXEC add_BibleVerse @BibleId, 104013009, N'from the tribe of Benjamin, Palti son of Raphu;'
EXEC add_BibleVerse @BibleId, 104013010, N'from the tribe of Zebulun, Gaddiel son of Sodi;'
EXEC add_BibleVerse @BibleId, 104013011, N'from the tribe of Joseph, namely, the tribe of Manasseh, Gaddi son of Susi;'
EXEC add_BibleVerse @BibleId, 104013012, N'from the tribe of Dan, Ammiel son of Gemalli;'
EXEC add_BibleVerse @BibleId, 104013013, N'from the tribe of Asher, Sethur son of Michael;'
EXEC add_BibleVerse @BibleId, 104013014, N'from the tribe of Naphtali, Nahbi son of Vopshi;'
EXEC add_BibleVerse @BibleId, 104013015, N'from the tribe of Gad, Geuel son of Maki.'
EXEC add_BibleVerse @BibleId, 104013016, N'These are the names of the men whom Moses sent to investigate the land. And Moses gave Hoshea son of Nun the name Joshua.'
EXEC add_BibleVerse @BibleId, 104013017, N'When Moses sent them to investigate the land of Canaan, he told them, “Go up through the Negev, and then go up into the hill country'
EXEC add_BibleVerse @BibleId, 104013018, N'and see what the land is like, and whether the people who live in it are strong or weak, few or many,'
EXEC add_BibleVerse @BibleId, 104013019, N'and whether the land they live in is good or bad, and whether the cities they inhabit are like camps or fortified cities,'
EXEC add_BibleVerse @BibleId, 104013020, N'and whether the land is rich or poor, and whether or not there are forests in it. And be brave, and bring back some of the fruit of the land.” Now it was the time of year for the first ripe grapes.'
EXEC add_BibleVerse @BibleId, 104013021, N'So they went up and investigated the land from the wilderness of Zin to Rehob, at the entrance of Hamath.'
EXEC add_BibleVerse @BibleId, 104013022, N'When they went up through the Negev, they came to Hebron where Ahiman, Sheshai, and Talmai, descendants of Anak, were living. (Now Hebron had been built seven years before Zoan in Egypt.)'
EXEC add_BibleVerse @BibleId, 104013023, N'When they came to the valley of Eshcol, they cut down from there a branch with one cluster of grapes, and they carried it on a staff between two men, as well as some of the pomegranates and the figs.'
EXEC add_BibleVerse @BibleId, 104013024, N'That place was called the Eshcol Valley, because of the cluster of grapes that the Israelites cut from there.'
EXEC add_BibleVerse @BibleId, 104013025, N'They returned from investigating the land after forty days.'
EXEC add_BibleVerse @BibleId, 104013026, N'They came back to Moses and Aaron and to the whole community of the Israelites in the wilderness of Paran at Kadesh. They reported to the whole community and showed the fruit of the land.'
EXEC add_BibleVerse @BibleId, 104013027, N'They told Moses, “We went to the land where you sent us. It is indeed flowing with milk and honey, and this is its fruit.'
EXEC add_BibleVerse @BibleId, 104013028, N'But the inhabitants are strong, and the cities are fortified and very large. Moreover we saw the descendants of Anak there.'
EXEC add_BibleVerse @BibleId, 104013029, N'The Amalekites live in the land of the Negev; the Hittites, Jebusites, and Amorites live in the hill country; and the Canaanites live by the sea and along the banks of the Jordan.”'
EXEC add_BibleVerse @BibleId, 104013030, N'Then Caleb silenced the people before Moses, saying, “Let us go up and occupy it, for we are well able to conquer it.”'
EXEC add_BibleVerse @BibleId, 104013031, N'But the men who had gone up with him said, “We are not able to go up against these people, because they are stronger than we are!”'
EXEC add_BibleVerse @BibleId, 104013032, N'Then they presented the Israelites with a discouraging report of the land they had investigated, saying, “The land that we passed through to investigate is a land that devours its inhabitants. All the people we saw there are of great stature.'
EXEC add_BibleVerse @BibleId, 104013033, N'We even saw the Nephilim there (the descendants of Anak came from the Nephilim), and we seemed liked grasshoppers both to ourselves and to them.”'
EXEC add_BibleVerse @BibleId, 104014001, N'Then all the community raised a loud cry, and the people wept that night.'
EXEC add_BibleVerse @BibleId, 104014002, N'And all the Israelites murmured against Moses and Aaron, and the whole congregation said to them, “If only we had died in the land of Egypt, or if only we had perished in this wilderness!'
EXEC add_BibleVerse @BibleId, 104014003, N'Why has the Lord brought us into this land only to be killed by the sword, that our wives and our children should become plunder? Wouldn’t it be better for us to return to Egypt?”'
EXEC add_BibleVerse @BibleId, 104014004, N'So they said to one another, “Let’s appoint a leader and return to Egypt.”'
EXEC add_BibleVerse @BibleId, 104014005, N'Then Moses and Aaron fell down with their faces to the ground before the whole assembled community of the Israelites.'
EXEC add_BibleVerse @BibleId, 104014006, N'And Joshua son of Nun and Caleb son of Jephunneh, two of those who had investigated the land, tore their garments.'
EXEC add_BibleVerse @BibleId, 104014007, N'They said to the whole community of the Israelites, “The land we passed through to investigate is an exceedingly good land.'
EXEC add_BibleVerse @BibleId, 104014008, N'If the Lord delights in us, then he will bring us into this land and give it to us – a land that is flowing with milk and honey.'
EXEC add_BibleVerse @BibleId, 104014009, N'Only do not rebel against the Lord, and do not fear the people of the land, for they are bread for us. Their protection has turned aside from them, but the Lord is with us. Do not fear them!”'
EXEC add_BibleVerse @BibleId, 104014010, N'However, the whole community threatened to stone them. But the glory of the Lord appeared to all the Israelites at the tent of meeting.'
EXEC add_BibleVerse @BibleId, 104014011, N'The Lord said to Moses, “How long will this people despise me, and how long will they not believe in me, in spite of the signs that I have done among them?'
EXEC add_BibleVerse @BibleId, 104014012, N'I will strike them with the pestilence, and I will disinherit them; I will make you into a nation that is greater and mightier than they!”'
EXEC add_BibleVerse @BibleId, 104014013, N'Moses said to the Lord, “When the Egyptians hear it – for you brought up this people by your power from among them –'
EXEC add_BibleVerse @BibleId, 104014014, N'then they will tell it to the inhabitants of this land. They have heard that you, Lord, are among this people, that you, Lord, are seen face to face, that your cloud stands over them, and that you go before them by day in a pillar of cloud and in a pillar of fire by night.'
EXEC add_BibleVerse @BibleId, 104014015, N'If you kill this entire people at once, then the nations that have heard of your fame will say,'
EXEC add_BibleVerse @BibleId, 104014016, N'‘Because the Lord was not able to bring this people into the land that he swore to them, he killed them in the wilderness.’'
EXEC add_BibleVerse @BibleId, 104014017, N'So now, let the power of my Lord be great, just as you have said,'
EXEC add_BibleVerse @BibleId, 104014018, N'‘The Lord is slow to anger and abounding in loyal love, forgiving iniquity and transgression, but by no means clearing the guilty, visiting the iniquity of the fathers on the children until the third and fourth generations.’'
EXEC add_BibleVerse @BibleId, 104014019, N'Please forgive the iniquity of this people according to your great loyal love, just as you have forgiven this people from Egypt even until now.”'
EXEC add_BibleVerse @BibleId, 104014020, N'Then the Lord said, “I have forgiven them as you asked.'
EXEC add_BibleVerse @BibleId, 104014021, N'But truly, as I live, all the earth will be filled with the glory of the Lord.'
EXEC add_BibleVerse @BibleId, 104014022, N'For all the people have seen my glory and my signs that I did in Egypt and in the wilderness, and yet have tempted me now these ten times, and have not obeyed me,'
EXEC add_BibleVerse @BibleId, 104014023, N'they will by no means see the land that I swore to their fathers, nor will any of them who despised me see it.'
EXEC add_BibleVerse @BibleId, 104014024, N'Only my servant Caleb, because he had a different spirit and has followed me fully – I will bring him into the land where he had gone, and his descendants will possess it.'
EXEC add_BibleVerse @BibleId, 104014025, N'(Now the Amalekites and the Canaanites were living in the valleys.) Tomorrow, turn and journey into the wilderness by the way of the Red Sea.”'
EXEC add_BibleVerse @BibleId, 104014026, N'The Lord spoke to Moses and Aaron:'
EXEC add_BibleVerse @BibleId, 104014027, N'“How long must I bear with this evil congregation that murmurs against me? I have heard the complaints of the Israelites that they murmured against me.'
EXEC add_BibleVerse @BibleId, 104014028, N'Say to them, ‘As I live, says the Lord, I will surely do to you just what you have spoken in my hearing.'
EXEC add_BibleVerse @BibleId, 104014029, N'Your dead bodies will fall in this wilderness – all those of you who were numbered, according to your full number, from twenty years old and upward, who have murmured against me.'
EXEC add_BibleVerse @BibleId, 104014030, N'You will by no means enter into the land where I swore to settle you. The only exceptions are Caleb son of Jephunneh and Joshua son of Nun.'
EXEC add_BibleVerse @BibleId, 104014031, N'But I will bring in your little ones, whom you said would become victims of war, and they will enjoy the land that you have despised.'
EXEC add_BibleVerse @BibleId, 104014032, N'But as for you, your dead bodies will fall in this wilderness,'
EXEC add_BibleVerse @BibleId, 104014033, N'and your children will wander in the wilderness forty years and suffer for your unfaithfulness, until your dead bodies lie finished in the wilderness.'
EXEC add_BibleVerse @BibleId, 104014034, N'According to the number of the days you have investigated this land, forty days – one day for a year – you will suffer for your iniquities, forty years, and you will know what it means to thwart me.'
EXEC add_BibleVerse @BibleId, 104014035, N'I, the Lord, have said, “I will surely do so to all this evil congregation that has gathered together against me. In this wilderness they will be finished, and there they will die!”’”'
EXEC add_BibleVerse @BibleId, 104014036, N'The men whom Moses sent to investigate the land, who returned and made the whole community murmur against him by producing an evil report about the land,'
EXEC add_BibleVerse @BibleId, 104014037, N'those men who produced the evil report about the land, died by the plague before the Lord.'
EXEC add_BibleVerse @BibleId, 104014038, N'But Joshua son of Nun and Caleb son of Jephunneh, who were among the men who went to investigate the land, lived.'
EXEC add_BibleVerse @BibleId, 104014039, N'When Moses told these things to all the Israelites, the people mourned greatly.'
EXEC add_BibleVerse @BibleId, 104014040, N'And early in the morning they went up to the crest of the hill country, saying, “Here we are, and we will go up to the place that the Lord commanded, for we have sinned.”'
EXEC add_BibleVerse @BibleId, 104014041, N'But Moses said, “Why are you now transgressing the commandment of the Lord? It will not succeed!'
EXEC add_BibleVerse @BibleId, 104014042, N'Do not go up, for the Lord is not among you, and you will be defeated before your enemies.'
EXEC add_BibleVerse @BibleId, 104014043, N'For the Amalekites and the Canaanites are there before you, and you will fall by the sword. Because you have turned away from the Lord, the Lord will not be with you.”'
EXEC add_BibleVerse @BibleId, 104014044, N'But they dared to go up to the crest of the hill, although neither the ark of the covenant of the Lord nor Moses departed from the camp.'
EXEC add_BibleVerse @BibleId, 104014045, N'So the Amalekites and the Canaanites who lived in that hill country swooped down and attacked them as far as Hormah.'
EXEC add_BibleVerse @BibleId, 104015001, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104015002, N'“Speak to the Israelites and tell them, ‘When you enter the land where you are to live, which I am giving you,'
EXEC add_BibleVerse @BibleId, 104015003, N'and you make an offering by fire to the Lord from the herd or from the flock (whether a burnt offering or a sacrifice for discharging a vow or as a freewill offering or in your solemn feasts) to create a pleasing aroma to the Lord,'
EXEC add_BibleVerse @BibleId, 104015004, N'then the one who presents his offering to the Lord must bring a grain offering of one-tenth of an ephah of finely ground flour mixed with one fourth of a hin of olive oil.'
EXEC add_BibleVerse @BibleId, 104015005, N'You must also prepare one-fourth of a hin of wine for a drink offering with the burnt offering or the sacrifice for each lamb.'
EXEC add_BibleVerse @BibleId, 104015006, N'Or for a ram, you must prepare as a grain offering two-tenths of an ephah of finely ground flour mixed with one-third of a hin of olive oil,'
EXEC add_BibleVerse @BibleId, 104015007, N'and for a drink offering you must offer one-third of a hin of wine as a pleasing aroma to the Lord.'
EXEC add_BibleVerse @BibleId, 104015008, N'And when you prepare a young bull as a burnt offering or a sacrifice for discharging a vow or as a peace offering to the Lord,'
EXEC add_BibleVerse @BibleId, 104015009, N'then a grain offering of three-tenths of an ephah of finely ground flour mixed with half a hin of olive oil must be presented with the young bull,'
EXEC add_BibleVerse @BibleId, 104015010, N'and you must present as the drink offering half a hin of wine with the fire offering as a pleasing aroma to the Lord.'
EXEC add_BibleVerse @BibleId, 104015011, N'This is what is to be done for each ox, or each ram, or each of the male lambs or the goats.'
EXEC add_BibleVerse @BibleId, 104015012, N'You must do so for each one according to the number that you prepare.'
EXEC add_BibleVerse @BibleId, 104015013, N'“‘Every native-born person must do these things in this way to present an offering made by fire as a pleasing aroma to the Lord.'
EXEC add_BibleVerse @BibleId, 104015014, N'If a resident foreigner is living with you – or whoever is among you in future generations – and prepares an offering made by fire as a pleasing aroma to the Lord, he must do it the same way you are to do it.'
EXEC add_BibleVerse @BibleId, 104015015, N'One statute must apply to you who belong to the congregation and to the resident foreigner who is living among you, as a permanent statute for your future generations. You and the resident foreigner will be alike before the Lord.'
EXEC add_BibleVerse @BibleId, 104015016, N'One law and one custom must apply to you and to the resident foreigner who lives alongside you.’”'
EXEC add_BibleVerse @BibleId, 104015017, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104015018, N'“Speak to the Israelites and tell them, ‘When you enter the land to which I am bringing you'
EXEC add_BibleVerse @BibleId, 104015019, N'and you eat some of the food of the land, you must offer up a raised offering to the Lord.'
EXEC add_BibleVerse @BibleId, 104015020, N'You must offer up a cake of the first of your finely ground flour as a raised offering; as you offer the raised offering of the threshing floor, so you must offer it up.'
EXEC add_BibleVerse @BibleId, 104015021, N'You must give to the Lord some of the first of your finely ground flour as a raised offering in your future generations.'
EXEC add_BibleVerse @BibleId, 104015022, N'“‘If you sin unintentionally and do not observe all these commandments that the Lord has spoken to Moses –'
EXEC add_BibleVerse @BibleId, 104015023, N'all that the Lord has commanded you by the authority of Moses, from the day that the Lord commanded Moses and continuing through your future generations –'
EXEC add_BibleVerse @BibleId, 104015024, N'then if anything is done unintentionally without the knowledge of the community, the whole community must prepare one young bull for a burnt offering – for a pleasing aroma to the Lord – along with its grain offering and its customary drink offering, and one male goat for a purification offering.'
EXEC add_BibleVerse @BibleId, 104015025, N'And the priest is to make atonement for the whole community of the Israelites, and they will be forgiven, because it was unintentional and they have brought their offering, an offering made by fire to the Lord, and their purification offering before the Lord, for their unintentional offense.'
EXEC add_BibleVerse @BibleId, 104015026, N'And the whole community of the Israelites and the resident foreigner who lives among them will be forgiven, since all the people were involved in the unintentional offense.'
EXEC add_BibleVerse @BibleId, 104015027, N'“‘If any person sins unintentionally, then he must bring a yearling female goat for a purification offering.'
EXEC add_BibleVerse @BibleId, 104015028, N'And the priest must make atonement for the person who sins unintentionally – when he sins unintentionally before the Lord – to make atonement for him, and he will be forgiven.'
EXEC add_BibleVerse @BibleId, 104015029, N'You must have one law for the person who sins unintentionally, both for the native-born among the Israelites and for the resident foreigner who lives among them.'
EXEC add_BibleVerse @BibleId, 104015030, N'“‘But the person who acts defiantly, whether native-born or a resident foreigner, insults the Lord. That person must be cut off from among his people.'
EXEC add_BibleVerse @BibleId, 104015031, N'Because he has despised the word of the Lord and has broken his commandment, that person must be completely cut off. His iniquity will be on him.’”'
EXEC add_BibleVerse @BibleId, 104015032, N'When the Israelites were in the wilderness they found a man gathering wood on the Sabbath day.'
EXEC add_BibleVerse @BibleId, 104015033, N'Those who found him gathering wood brought him to Moses and Aaron and to the whole community.'
EXEC add_BibleVerse @BibleId, 104015034, N'They put him in custody, because there was no clear instruction about what should be done to him.'
EXEC add_BibleVerse @BibleId, 104015035, N'Then the Lord said to Moses, “The man must surely be put to death; the whole community must stone him with stones outside the camp.”'
EXEC add_BibleVerse @BibleId, 104015036, N'So the whole community took him outside the camp and stoned him to death, just as the Lord commanded Moses.'
EXEC add_BibleVerse @BibleId, 104015037, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104015038, N'“Speak to the Israelites and tell them to make tassels for themselves on the corners of their garments throughout their generations, and put a blue thread on the tassel of the corners.'
EXEC add_BibleVerse @BibleId, 104015039, N'You must have this tassel so that you may look at it and remember all the commandments of the Lord and obey them and so that you do not follow after your own heart and your own eyes that lead you to unfaithfulness.'
EXEC add_BibleVerse @BibleId, 104015040, N'Thus you will remember and obey all my commandments and be holy to your God.'
EXEC add_BibleVerse @BibleId, 104015041, N'I am the Lord your God, who brought you out of the land of Egypt to be your God. I am the Lord your God.”'
EXEC add_BibleVerse @BibleId, 104016001, N'Now Korah son of Izhar, the son of Kohath, the son of Levi, and Dathan and Abiram, the sons of Eliab, and On son of Peleth, who were Reubenites, took men'
EXEC add_BibleVerse @BibleId, 104016002, N'and rebelled against Moses, along with some of the Israelites, 250 leaders of the community, chosen from the assembly, famous men.'
EXEC add_BibleVerse @BibleId, 104016003, N'And they assembled against Moses and Aaron, saying to them, “You take too much upon yourselves, seeing that the whole community is holy, every one of them, and the Lord is among them. Why then do you exalt yourselves above the community of the Lord?”'
EXEC add_BibleVerse @BibleId, 104016004, N'When Moses heard it he fell down with his face to the ground.'
EXEC add_BibleVerse @BibleId, 104016005, N'Then he said to Korah and to all his company, “In the morning the Lord will make known who are his, and who is holy. He will cause that person to approach him; the person he has chosen he will cause to approach him.'
EXEC add_BibleVerse @BibleId, 104016006, N'Do this, Korah, you and all your company: Take censers,'
EXEC add_BibleVerse @BibleId, 104016007, N'put fire in them, and set incense on them before the Lord tomorrow, and the man whom the Lord chooses will be holy. You take too much upon yourselves, you sons of Levi!”'
EXEC add_BibleVerse @BibleId, 104016008, N'Moses said to Korah, “Listen now, you sons of Levi!'
EXEC add_BibleVerse @BibleId, 104016009, N'Does it seem too small a thing to you that the God of Israel has separated you from the community of Israel to bring you near to himself, to perform the service of the tabernacle of the Lord, and to stand before the community to minister to them?'
EXEC add_BibleVerse @BibleId, 104016010, N'He has brought you near and all your brothers, the sons of Levi, with you. Do you now seek the priesthood also?'
EXEC add_BibleVerse @BibleId, 104016011, N'Therefore you and all your company have assembled together against the Lord! And Aaron – what is he that you murmur against him?”'
EXEC add_BibleVerse @BibleId, 104016012, N'Then Moses summoned Dathan and Abiram, the sons of Eliab, but they said, “We will not come up.'
EXEC add_BibleVerse @BibleId, 104016013, N'Is it a small thing that you have brought us up out of the land that flows with milk and honey, to kill us in the wilderness? Now do you want to make yourself a prince over us?'
EXEC add_BibleVerse @BibleId, 104016014, N'Moreover, you have not brought us into a land that flows with milk and honey, nor given us an inheritance of fields and vineyards. Do you think you can blind these men? We will not come up.”'
EXEC add_BibleVerse @BibleId, 104016015, N'Moses was very angry, and he said to the Lord, “Have no respect for their offering! I have not taken so much as one donkey from them, nor have I harmed any one of them!”'
EXEC add_BibleVerse @BibleId, 104016016, N'Then Moses said to Korah, “You and all your company present yourselves before the Lord – you and they, and Aaron – tomorrow.'
EXEC add_BibleVerse @BibleId, 104016017, N'And each of you take his censer, put incense in it, and then each of you present his censer before the Lord: 250 censers, along with you, and Aaron – each of you with his censer.”'
EXEC add_BibleVerse @BibleId, 104016018, N'So everyone took his censer, put fire in it, and set incense on it, and stood at the entrance of the tent of meeting, with Moses and Aaron.'
EXEC add_BibleVerse @BibleId, 104016019, N'When Korah assembled the whole community against them at the entrance of the tent of meeting, then the glory of the Lord appeared to the whole community.'
EXEC add_BibleVerse @BibleId, 104016020, N'The Lord spoke to Moses and Aaron:'
EXEC add_BibleVerse @BibleId, 104016021, N'“Separate yourselves from among this community, that I may consume them in an instant.”'
EXEC add_BibleVerse @BibleId, 104016022, N'Then they threw themselves down with their faces to the ground and said, “O God, the God of the spirits of all people, will you be angry with the whole community when only one man sins?”'
EXEC add_BibleVerse @BibleId, 104016023, N'So the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104016024, N'“Tell the community: ‘Get away from around the homes of Korah, Dathan, and Abiram.’”'
EXEC add_BibleVerse @BibleId, 104016025, N'Then Moses got up and went to Dathan and Abiram; and the elders of Israel went after him.'
EXEC add_BibleVerse @BibleId, 104016026, N'And he said to the community, “Move away from the tents of these wicked men, and do not touch anything they have, lest you be destroyed because of all their sins.”'
EXEC add_BibleVerse @BibleId, 104016027, N'So they got away from the homes of Korah, Dathan, and Abiram on every side, and Dathan and Abiram came out and stationed themselves in the entrances of their tents with their wives, their children, and their toddlers.'
EXEC add_BibleVerse @BibleId, 104016028, N'Then Moses said, “This is how you will know that the Lord has sent me to do all these works, for I have not done them of my own will.'
EXEC add_BibleVerse @BibleId, 104016029, N'If these men die a natural death, or if they share the fate of all men, then the Lord has not sent me.'
EXEC add_BibleVerse @BibleId, 104016030, N'But if the Lord does something entirely new, and the earth opens its mouth and swallows them up along with all that they have, and they go down alive to the grave, then you will know that these men have despised the Lord!”'
EXEC add_BibleVerse @BibleId, 104016031, N'When he had finished speaking all these words, the ground that was under them split open,'
EXEC add_BibleVerse @BibleId, 104016032, N'and the earth opened its mouth and swallowed them, along with their households, and all Korah’s men, and all their goods.'
EXEC add_BibleVerse @BibleId, 104016033, N'They and all that they had went down alive into the pit, and the earth closed over them. So they perished from among the community.'
EXEC add_BibleVerse @BibleId, 104016034, N'All the Israelites who were around them fled at their cry, for they said, “What if the earth swallows us too?”'
EXEC add_BibleVerse @BibleId, 104016035, N'Then a fire went out from the Lord and devoured the 250 men who offered incense.'
EXEC add_BibleVerse @BibleId, 104016036, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104016037, N'“Tell Eleazar son of Aaron the priest to pick up the censers out of the flame, for they are holy, and then scatter the coals of fire at a distance.'
EXEC add_BibleVerse @BibleId, 104016038, N'As for the censers of these men who sinned at the cost of their lives, they must be made into hammered sheets for covering the altar, because they presented them before the Lord and sanctified them. They will become a sign to the Israelites.”'
EXEC add_BibleVerse @BibleId, 104016039, N'So Eleazar the priest took the bronze censers presented by those who had been burned up, and they were hammered out as a covering for the altar.'
EXEC add_BibleVerse @BibleId, 104016040, N'It was a memorial for the Israelites, that no outsider who is not a descendant of Aaron should approach to burn incense before the Lord, that he might not become like Korah and his company – just as the Lord had spoken by the authority of Moses.'
EXEC add_BibleVerse @BibleId, 104016041, N'But on the next day the whole community of Israelites murmured against Moses and Aaron, saying, “You have killed the Lord’s people!”'
EXEC add_BibleVerse @BibleId, 104016042, N'When the community assembled against Moses and Aaron, they turned toward the tent of meeting – and the cloud covered it, and the glory of the Lord appeared.'
EXEC add_BibleVerse @BibleId, 104016043, N'Then Moses and Aaron stood before the tent of meeting.'
EXEC add_BibleVerse @BibleId, 104016044, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104016045, N'“Get away from this community, so that I can consume them in an instant!” But they threw themselves down with their faces to the ground.'
EXEC add_BibleVerse @BibleId, 104016046, N'Then Moses said to Aaron, “Take the censer, put burning coals from the altar in it, place incense on it, and go quickly into the assembly and make atonement for them, for wrath has gone out from the Lord – the plague has begun!”'
EXEC add_BibleVerse @BibleId, 104016047, N'So Aaron did as Moses commanded and ran into the middle of the assembly, where the plague was just beginning among the people. So he placed incense on the coals and made atonement for the people.'
EXEC add_BibleVerse @BibleId, 104016048, N'He stood between the dead and the living, and the plague was stopped.'
EXEC add_BibleVerse @BibleId, 104016049, N'Now 14,700 people died in the plague, in addition to those who died in the event with Korah.'
EXEC add_BibleVerse @BibleId, 104016050, N'Then Aaron returned to Moses at the entrance of the tent of meeting, and the plague was stopped.'
EXEC add_BibleVerse @BibleId, 104017001, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104017002, N'“Speak to the Israelites, and receive from them a staff from each tribe, one from every tribal leader, twelve staffs; you must write each man’s name on his staff.'
EXEC add_BibleVerse @BibleId, 104017003, N'You must write Aaron’s name on the staff of Levi; for one staff is for the head of every tribe.'
EXEC add_BibleVerse @BibleId, 104017004, N'You must place them in the tent of meeting before the ark of the covenant where I meet with you.'
EXEC add_BibleVerse @BibleId, 104017005, N'And the staff of the man whom I choose will blossom; so I will rid myself of the complaints of the Israelites, which they murmur against you.”'
EXEC add_BibleVerse @BibleId, 104017006, N'So Moses spoke to the Israelites, and each of their leaders gave him a staff, one for each leader, according to their tribes – twelve staffs; the staff of Aaron was among their staffs.'
EXEC add_BibleVerse @BibleId, 104017007, N'Then Moses placed the staffs before the Lord in the tent of the testimony.'
EXEC add_BibleVerse @BibleId, 104017008, N'On the next day Moses went into the tent of the testimony – and the staff of Aaron for the house of Levi had sprouted, and brought forth buds, and produced blossoms, and yielded almonds!'
EXEC add_BibleVerse @BibleId, 104017009, N'So Moses brought out all the staffs from before the Lord to all the Israelites. They looked at them, and each man took his staff.'
EXEC add_BibleVerse @BibleId, 104017010, N'The Lord said to Moses, “Bring Aaron’s staff back before the testimony to be preserved for a sign to the rebels, so that you may bring their murmurings to an end before me, that they will not die.”'
EXEC add_BibleVerse @BibleId, 104017011, N'So Moses did as the Lord commanded him – this is what he did.'
EXEC add_BibleVerse @BibleId, 104017012, N'The Israelites said to Moses, “We are bound to die! We perish, we all perish!'
EXEC add_BibleVerse @BibleId, 104017013, N'Anyone who even comes close to the tabernacle of the Lord will die! Are we all to die?”'
EXEC add_BibleVerse @BibleId, 104018001, N'The Lord said to Aaron, “You and your sons and your tribe with you must bear the iniquity of the sanctuary, and you and your sons with you must bear the iniquity of your priesthood.'
EXEC add_BibleVerse @BibleId, 104018002, N'“Bring with you your brothers, the tribe of Levi, the tribe of your father, so that they may join with you and minister to you while you and your sons with you are before the tent of the testimony.'
EXEC add_BibleVerse @BibleId, 104018003, N'They must be responsible to care for you and to care for the entire tabernacle. However, they must not come near the furnishings of the sanctuary and the altar, or both they and you will die.'
EXEC add_BibleVerse @BibleId, 104018004, N'They must join with you, and they will be responsible for the care of the tent of meeting, for all the service of the tent, but no unauthorized person may approach you.'
EXEC add_BibleVerse @BibleId, 104018005, N'You will be responsible for the care of the sanctuary and the care of the altar, so that there will be no more wrath on the Israelites.'
EXEC add_BibleVerse @BibleId, 104018006, N'I myself have chosen your brothers the Levites from among the Israelites. They are given to you as a gift from the Lord, to perform the duties of the tent of meeting.'
EXEC add_BibleVerse @BibleId, 104018007, N'But you and your sons with you are responsible for your priestly duties, for everything at the altar and within the curtain. And you must serve. I give you the priesthood as a gift for service; but the unauthorized person who approaches must be put to death.”'
EXEC add_BibleVerse @BibleId, 104018008, N'The Lord spoke to Aaron, “See, I have given you the responsibility for my raised offerings; I have given all the holy things of the Israelites to you as your priestly portion and to your sons as a perpetual ordinance.'
EXEC add_BibleVerse @BibleId, 104018009, N'Of all the most holy offerings reserved from the fire this will be yours: Every offering of theirs, whether from every grain offering or from every purification offering or from every reparation offering which they bring to me, will be most holy for you and for your sons.'
EXEC add_BibleVerse @BibleId, 104018010, N'You are to eat it as a most holy offering; every male may eat it. It will be holy to you.'
EXEC add_BibleVerse @BibleId, 104018011, N'“And this is yours: the raised offering of their gift, along with all the wave offerings of the Israelites. I have given them to you and to your sons and daughters with you as a perpetual ordinance. Everyone who is ceremonially clean in your household may eat of it.'
EXEC add_BibleVerse @BibleId, 104018012, N'“All the best of the olive oil and all the best of the wine and of the wheat, the first fruits of these things that they give to the Lord, I have given to you.'
EXEC add_BibleVerse @BibleId, 104018013, N'And whatever first ripe fruit in their land they bring to the Lord will be yours; everyone who is ceremonially clean in your household may eat of it.'
EXEC add_BibleVerse @BibleId, 104018014, N'“Everything devoted in Israel will be yours.'
EXEC add_BibleVerse @BibleId, 104018015, N'The firstborn of every womb which they present to the Lord, whether human or animal, will be yours. Nevertheless, the firstborn sons you must redeem, and the firstborn males of unclean animals you must redeem.'
EXEC add_BibleVerse @BibleId, 104018016, N'And those that must be redeemed you are to redeem when they are a month old, according to your estimation, for five shekels of silver according to the sanctuary shekel (which is twenty gerahs).'
EXEC add_BibleVerse @BibleId, 104018017, N'But you must not redeem the firstborn of a cow or a sheep or a goat; they are holy. You must splash their blood on the altar and burn their fat for an offering made by fire for a pleasing aroma to the Lord.'
EXEC add_BibleVerse @BibleId, 104018018, N'And their meat will be yours, just as the breast and the right hip of the raised offering is yours.'
EXEC add_BibleVerse @BibleId, 104018019, N'All the raised offerings of the holy things that the Israelites offer to the Lord, I have given to you, and to your sons and daughters with you, as a perpetual ordinance. It is a covenant of salt forever before the Lord for you and for your descendants with you.”'
EXEC add_BibleVerse @BibleId, 104018020, N'The Lord spoke to Aaron, “You will have no inheritance in their land, nor will you have any portion of property among them – I am your portion and your inheritance among the Israelites.'
EXEC add_BibleVerse @BibleId, 104018021, N'See, I have given the Levites all the tithes in Israel for an inheritance, for their service which they perform – the service of the tent of meeting.'
EXEC add_BibleVerse @BibleId, 104018022, N'No longer may the Israelites approach the tent of meeting, or else they will bear their sin and die.'
EXEC add_BibleVerse @BibleId, 104018023, N'But the Levites must perform the service of the tent of meeting, and they must bear their iniquity. It will be a perpetual ordinance throughout your generations that among the Israelites the Levites have no inheritance.'
EXEC add_BibleVerse @BibleId, 104018024, N'But I have given to the Levites for an inheritance the tithes of the Israelites that are offered to the Lord as a raised offering. That is why I said to them that among the Israelites they are to have no inheritance.”'
EXEC add_BibleVerse @BibleId, 104018025, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104018026, N'“You are to speak to the Levites, and you must tell them, ‘When you receive from the Israelites the tithe that I have given you from them as your inheritance, then you are to offer up from it as a raised offering to the Lord a tenth of the tithe.'
EXEC add_BibleVerse @BibleId, 104018027, N'And your raised offering will be credited to you as though it were grain from the threshing floor or as new wine from the winepress.'
EXEC add_BibleVerse @BibleId, 104018028, N'Thus you are to offer up a raised offering to the Lord of all your tithes which you receive from the Israelites; and you must give the Lord’s raised offering from it to Aaron the priest.'
EXEC add_BibleVerse @BibleId, 104018029, N'From all your gifts you must offer up every raised offering due the Lord, from all the best of it, and the holiest part of it.’'
EXEC add_BibleVerse @BibleId, 104018030, N'“Therefore you will say to them, ‘When you offer up the best of it, then it will be credited to the Levites as the product of the threshing floor and as the product of the winepress.'
EXEC add_BibleVerse @BibleId, 104018031, N'And you may eat it in any place, you and your household, because it is your wages for your service in the tent of meeting.'
EXEC add_BibleVerse @BibleId, 104018032, N'And you will bear no sin concerning it when you offer up the best of it. And you must not profane the holy things of the Israelites, or else you will die.’”'
EXEC add_BibleVerse @BibleId, 104019001, N'The Lord spoke to Moses and Aaron:'
EXEC add_BibleVerse @BibleId, 104019002, N'“This is the ordinance of the law which the Lord has commanded: ‘Instruct the Israelites to bring you a red heifer without blemish, which has no defect and has never carried a yoke.'
EXEC add_BibleVerse @BibleId, 104019003, N'You must give it to Eleazar the priest so that he can take it outside the camp, and it must be slaughtered before him.'
EXEC add_BibleVerse @BibleId, 104019004, N'Eleazar the priest is to take some of its blood with his finger, and sprinkle some of the blood seven times directly in front of the tent of meeting.'
EXEC add_BibleVerse @BibleId, 104019005, N'Then the heifer must be burned in his sight – its skin, its flesh, its blood, and its offal is to be burned.'
EXEC add_BibleVerse @BibleId, 104019006, N'And the priest must take cedar wood, hyssop, and scarlet wool and throw them into the midst of the fire where the heifer is burning.'
EXEC add_BibleVerse @BibleId, 104019007, N'Then the priest must wash his clothes and bathe himself in water, and afterward he may come into the camp, but the priest will be ceremonially unclean until evening.'
EXEC add_BibleVerse @BibleId, 104019008, N'The one who burns it must wash his clothes in water and bathe himself in water. He will be ceremonially unclean until evening.'
EXEC add_BibleVerse @BibleId, 104019009, N'“‘Then a man who is ceremonially clean must gather up the ashes of the red heifer and put them in a ceremonially clean place outside the camp. They must be kept for the community of the Israelites for use in the water of purification – it is a purification for sin.'
EXEC add_BibleVerse @BibleId, 104019010, N'The one who gathers the ashes of the heifer must wash his clothes and be ceremonially unclean until evening. This will be a permanent ordinance both for the Israelites and the resident foreigner who lives among them.'
EXEC add_BibleVerse @BibleId, 104019011, N'“‘Whoever touches the corpse of any person will be ceremonially unclean seven days.'
EXEC add_BibleVerse @BibleId, 104019012, N'He must purify himself with water on the third day and on the seventh day, and so will be clean. But if he does not purify himself on the third day and the seventh day, then he will not be clean.'
EXEC add_BibleVerse @BibleId, 104019013, N'Anyone who touches the corpse of any dead person and does not purify himself defiles the tabernacle of the Lord. And that person must be cut off from Israel, because the water of purification was not sprinkled on him. He will be unclean; his uncleanness remains on him.'
EXEC add_BibleVerse @BibleId, 104019014, N'“‘This is the law: When a man dies in a tent, anyone who comes into the tent and all who are in the tent will be ceremonially unclean seven days.'
EXEC add_BibleVerse @BibleId, 104019015, N'And every open container that has no covering fastened on it is unclean.'
EXEC add_BibleVerse @BibleId, 104019016, N'And whoever touches the body of someone killed with a sword in the open fields, or the body of someone who died of natural causes, or a human bone, or a grave, will be unclean seven days.'
EXEC add_BibleVerse @BibleId, 104019017, N'“‘For a ceremonially unclean person you must take some of the ashes of the heifer burnt for purification from sin and pour fresh running water over them in a vessel.'
EXEC add_BibleVerse @BibleId, 104019018, N'Then a ceremonially clean person must take hyssop, dip it in the water, and sprinkle it on the tent, on all its furnishings, and on the people who were there, or on the one who touched a bone, or one killed, or one who died, or a grave.'
EXEC add_BibleVerse @BibleId, 104019019, N'And the clean person must sprinkle the unclean on the third day and on the seventh day; and on the seventh day he must purify him, and then he must wash his clothes, and bathe in water, and he will be clean in the evening.'
EXEC add_BibleVerse @BibleId, 104019020, N'But the man who is unclean and does not purify himself, that person must be cut off from among the community, because he has polluted the sanctuary of the Lord; the water of purification was not sprinkled on him, so he is unclean.'
EXEC add_BibleVerse @BibleId, 104019021, N'“‘So this will be a perpetual ordinance for them: The one who sprinkles the water of purification must wash his clothes, and the one who touches the water of purification will be unclean until evening.'
EXEC add_BibleVerse @BibleId, 104019022, N'And whatever the unclean person touches will be unclean, and the person who touches it will be unclean until evening.’”'
EXEC add_BibleVerse @BibleId, 104020001, N'Then the entire community of Israel entered the wilderness of Zin in the first month, and the people stayed in Kadesh. Miriam died and was buried there.'
EXEC add_BibleVerse @BibleId, 104020002, N'And there was no water for the community, and so they gathered themselves together against Moses and Aaron.'
EXEC add_BibleVerse @BibleId, 104020003, N'The people contended with Moses, saying, “If only we had died when our brothers died before the Lord!'
EXEC add_BibleVerse @BibleId, 104020004, N'Why have you brought up the Lord’s community into this wilderness? So that we and our cattle should die here?'
EXEC add_BibleVerse @BibleId, 104020005, N'Why have you brought us up from Egypt only to bring us to this dreadful place? It is no place for grain, or figs, or vines, or pomegranates; nor is there any water to drink!”'
EXEC add_BibleVerse @BibleId, 104020006, N'So Moses and Aaron went from the presence of the assembly to the entrance to the tent of meeting. They then threw themselves down with their faces to the ground, and the glory of the Lord appeared to them.'
EXEC add_BibleVerse @BibleId, 104020007, N'Then the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104020008, N'“Take the staff and assemble the community, you and Aaron your brother, and then speak to the rock before their eyes. It will pour forth its water, and you will bring water out of the rock for them, and so you will give the community and their beasts water to drink.”'
EXEC add_BibleVerse @BibleId, 104020009, N'So Moses took the staff from before the Lord, just as he commanded him.'
EXEC add_BibleVerse @BibleId, 104020010, N'Then Moses and Aaron gathered the community together in front of the rock, and he said to them, “Listen, you rebels, must we bring water out of this rock for you?”'
EXEC add_BibleVerse @BibleId, 104020011, N'Then Moses raised his hand, and struck the rock twice with his staff. And water came out abundantly. So the community drank, and their beasts drank too.'
EXEC add_BibleVerse @BibleId, 104020012, N'Then the Lord spoke to Moses and Aaron, “Because you did not trust me enough to show me as holy before the Israelites, therefore you will not bring this community into the land I have given them.”'
EXEC add_BibleVerse @BibleId, 104020013, N'These are the waters of Meribah, because the Israelites contended with the Lord, and his holiness was maintained among them.'
EXEC add_BibleVerse @BibleId, 104020014, N'Moses sent messengers from Kadesh to the king of Edom: “Thus says your brother Israel: ‘You know all the hardships we have experienced,'
EXEC add_BibleVerse @BibleId, 104020015, N'how our ancestors went down into Egypt, and we lived in Egypt a long time, and the Egyptians treated us and our ancestors badly.'
EXEC add_BibleVerse @BibleId, 104020016, N'So when we cried to the Lord, he heard our voice and sent a messenger, and has brought us up out of Egypt. Now we are here in Kadesh, a town on the edge of your country.'
EXEC add_BibleVerse @BibleId, 104020017, N'Please let us pass through your country. We will not pass through the fields or through the vineyards, nor will we drink water from any well. We will go by the King’s Highway; we will not turn to the right or the left until we have passed through your region.’”'
EXEC add_BibleVerse @BibleId, 104020018, N'But Edom said to him, “You will not pass through me, or I will come out against you with the sword.”'
EXEC add_BibleVerse @BibleId, 104020019, N'Then the Israelites said to him, “We will go along the highway, and if we or our cattle drink any of your water, we will pay for it. We will only pass through on our feet, without doing anything else.”'
EXEC add_BibleVerse @BibleId, 104020020, N'But he said, “You may not pass through.” Then Edom came out against them with a large and powerful force.'
EXEC add_BibleVerse @BibleId, 104020021, N'So Edom refused to give Israel passage through his border; therefore Israel turned away from him.'
EXEC add_BibleVerse @BibleId, 104020022, N'So the entire company of Israelites traveled from Kadesh and came to Mount Hor.'
EXEC add_BibleVerse @BibleId, 104020023, N'And the Lord spoke to Moses and Aaron in Mount Hor, by the border of the land of Edom. He said:'
EXEC add_BibleVerse @BibleId, 104020024, N'“Aaron will be gathered to his ancestors, for he will not enter into the land I have given to the Israelites because both of you rebelled against my word at the waters of Meribah.'
EXEC add_BibleVerse @BibleId, 104020025, N'Take Aaron and Eleazar his son, and bring them up on Mount Hor.'
EXEC add_BibleVerse @BibleId, 104020026, N'Remove Aaron’s priestly garments and put them on Eleazar his son, and Aaron will be gathered to his ancestors and will die there.”'
EXEC add_BibleVerse @BibleId, 104020027, N'So Moses did as the Lord commanded; and they went up Mount Hor in the sight of the whole community.'
EXEC add_BibleVerse @BibleId, 104020028, N'And Moses removed Aaron’s garments and put them on his son Eleazar. So Aaron died there on the top of the mountain. And Moses and Eleazar came down from the mountain.'
EXEC add_BibleVerse @BibleId, 104020029, N'When all the community saw that Aaron was dead, the whole house of Israel mourned for Aaron thirty days.'
EXEC add_BibleVerse @BibleId, 104021001, N'When the Canaanite king of Arad who lived in the Negev heard that Israel was approaching along the road to Atharim, he fought against Israel and took some of them prisoner.'
EXEC add_BibleVerse @BibleId, 104021002, N'So Israel made a vow to the Lord and said, “If you will indeed deliver this people into our hand, then we will utterly destroy their cities.”'
EXEC add_BibleVerse @BibleId, 104021003, N'The Lord listened to the voice of Israel and delivered up the Canaanites, and they utterly destroyed them and their cities. So the name of the place was called Hormah.'
EXEC add_BibleVerse @BibleId, 104021004, N'Then they traveled from Mount Hor by the road to the Red Sea, to go around the land of Edom, but the people became impatient along the way.'
EXEC add_BibleVerse @BibleId, 104021005, N'And the people spoke against God and against Moses, “Why have you brought us up out of Egypt to die in the wilderness, for there is no bread or water, and we detest this worthless food.”'
EXEC add_BibleVerse @BibleId, 104021006, N'So the Lord sent poisonous snakes among the people, and they bit the people; many people of Israel died.'
EXEC add_BibleVerse @BibleId, 104021007, N'Then the people came to Moses and said, “We have sinned, for we have spoken against the Lord and against you. Pray to the Lord that he would take away the snakes from us.” So Moses prayed for the people.'
EXEC add_BibleVerse @BibleId, 104021008, N'The Lord said to Moses, “Make a poisonous snake and set it on a pole. When anyone who is bitten looks at it, he will live.”'
EXEC add_BibleVerse @BibleId, 104021009, N'So Moses made a bronze snake and put it on a pole, so that if a snake had bitten someone, when he looked at the bronze snake he lived.'
EXEC add_BibleVerse @BibleId, 104021010, N'The Israelites traveled on and camped in Oboth.'
EXEC add_BibleVerse @BibleId, 104021011, N'Then they traveled on from Oboth and camped at Iye Abarim, in the wilderness that is before Moab, on the eastern side.'
EXEC add_BibleVerse @BibleId, 104021012, N'From there they moved on and camped in the valley of Zered.'
EXEC add_BibleVerse @BibleId, 104021013, N'From there they moved on and camped on the other side of the Arnon, in the wilderness that extends from the regions of the Amorites, for Arnon is the border of Moab, between Moab and the Amorites.'
EXEC add_BibleVerse @BibleId, 104021014, N'This is why it is said in the Book of the Wars of the Lord, “Waheb in Suphah and the wadis, the Arnon'
EXEC add_BibleVerse @BibleId, 104021015, N'and the slope of the valleys that extends to the dwelling of Ar, and falls off at the border of Moab.”'
EXEC add_BibleVerse @BibleId, 104021016, N'And from there they traveled to Beer; that is the well where the Lord spoke to Moses, “Gather the people and I will give them water.”'
EXEC add_BibleVerse @BibleId, 104021017, N'Then Israel sang this song: “Spring up, O well, sing to it!'
EXEC add_BibleVerse @BibleId, 104021018, N'The well which the princes dug, which the leaders of the people opened with their scepters and their staffs.” And from the wilderness they traveled to Mattanah;'
EXEC add_BibleVerse @BibleId, 104021019, N'and from Mattanah to Nahaliel; and from Nahaliel to Bamoth;'
EXEC add_BibleVerse @BibleId, 104021020, N'and from Bamoth to the valley that is in the country of Moab, near the top of Pisgah, which overlooks the wilderness.'
EXEC add_BibleVerse @BibleId, 104021021, N'Then Israel sent messengers to King Sihon of the Amorites, saying,'
EXEC add_BibleVerse @BibleId, 104021022, N'“Let us pass through your land; we will not turn aside into the fields or into the vineyards, nor will we drink water from any well, but we will go along the King’s Highway until we pass your borders.”'
EXEC add_BibleVerse @BibleId, 104021023, N'But Sihon did not permit Israel to pass through his border; he gathered all his forces together and went out against Israel into the wilderness. When he came to Jahaz, he fought against Israel.'
EXEC add_BibleVerse @BibleId, 104021024, N'But the Israelites defeated him in battle and took possession of his land from the Arnon to the Jabbok, as far as the Ammonites, for the border of the Ammonites was strongly defended.'
EXEC add_BibleVerse @BibleId, 104021025, N'So Israel took all these cities; and Israel settled in all the cities of the Amorites, in Heshbon, and in all its villages.'
EXEC add_BibleVerse @BibleId, 104021026, N'For Heshbon was the city of King Sihon of the Amorites. Now he had fought against the former king of Moab and had taken all of his land from his control, as far as the Arnon.'
EXEC add_BibleVerse @BibleId, 104021027, N'That is why those who speak in proverbs say, “Come to Heshbon, let it be built. Let the city of Sihon be established!'
EXEC add_BibleVerse @BibleId, 104021028, N'For fire went out from Heshbon, a flame from the city of Sihon. It has consumed Ar of Moab and the lords of the high places of Arnon.'
EXEC add_BibleVerse @BibleId, 104021029, N'Woe to you, Moab. You are ruined, O people of Chemosh! He has made his sons fugitives, and his daughters the prisoners of King Sihon of the Amorites.'
EXEC add_BibleVerse @BibleId, 104021030, N'We have overpowered them; Heshbon has perished as far as Dibon. We have shattered them as far as Nophah, which reaches to Medeba.”'
EXEC add_BibleVerse @BibleId, 104021031, N'So the Israelites lived in the land of the Amorites.'
EXEC add_BibleVerse @BibleId, 104021032, N'Moses sent spies to reconnoiter Jaazer, and they captured its villages and dispossessed the Amorites who were there.'
EXEC add_BibleVerse @BibleId, 104021033, N'Then they turned and went up by the road to Bashan. And King Og of Bashan and all his forces marched out against them to do battle at Edrei.'
EXEC add_BibleVerse @BibleId, 104021034, N'And the Lord said to Moses, “Do not fear him, for I have delivered him and all his people and his land into your hand. You will do to him what you did to King Sihon of the Amorites, who lived in Heshbon.'
EXEC add_BibleVerse @BibleId, 104021035, N'So they defeated Og, his sons, and all his people, until there were no survivors, and they possessed his land.'
EXEC add_BibleVerse @BibleId, 104022001, N'The Israelites traveled on and camped in the plains of Moab on the side of the Jordan River across from Jericho.'
EXEC add_BibleVerse @BibleId, 104022002, N'Balak son of Zippor saw all that the Israelites had done to the Amorites.'
EXEC add_BibleVerse @BibleId, 104022003, N'And the Moabites were greatly afraid of the people, because they were so numerous. The Moabites were sick with fear because of the Israelites.'
EXEC add_BibleVerse @BibleId, 104022004, N'So the Moabites said to the elders of Midian, “Now this mass of people will lick up everything around us, as the bull devours the grass of the field. Now Balak son of Zippor was king of the Moabites at this time.'
EXEC add_BibleVerse @BibleId, 104022005, N'And he sent messengers to Balaam son of Beor at Pethor, which is by the Euphrates River in the land of Amaw, to summon him, saying, “Look, a nation has come out of Egypt. They cover the face of the earth, and they are settling next to me.'
EXEC add_BibleVerse @BibleId, 104022006, N'So now, please come and curse this nation for me, for they are too powerful for me. Perhaps I will prevail so that we may conquer them and drive them out of the land. For I know that whoever you bless is blessed, and whoever you curse is cursed.”'
EXEC add_BibleVerse @BibleId, 104022007, N'So the elders of Moab and the elders of Midian departed with the fee for divination in their hand. They came to Balaam and reported to him the words of Balak.'
EXEC add_BibleVerse @BibleId, 104022008, N'He replied to them, “Stay here tonight, and I will bring back to you whatever word the Lord may speak to me.” So the princes of Moab stayed with Balaam.'
EXEC add_BibleVerse @BibleId, 104022009, N'And God came to Balaam and said, “Who are these men with you?”'
EXEC add_BibleVerse @BibleId, 104022010, N'Balaam said to God, “Balak son of Zippor, king of Moab, has sent a message to me, saying,'
EXEC add_BibleVerse @BibleId, 104022011, N'“Look, a nation has come out of Egypt, and it covers the face of the earth. Come now and put a curse on them for me; perhaps I will be able to defeat them and drive them out.”'
EXEC add_BibleVerse @BibleId, 104022012, N'But God said to Balaam, “You must not go with them; you must not curse the people, for they are blessed.”'
EXEC add_BibleVerse @BibleId, 104022013, N'So Balaam got up in the morning, and said to the princes of Balak, “Go to your land, for the Lord has refused to permit me to go with you.”'
EXEC add_BibleVerse @BibleId, 104022014, N'So the princes of Moab departed and went back to Balak and said, “Balaam refused to come with us.”'
EXEC add_BibleVerse @BibleId, 104022015, N'Balak again sent princes, more numerous and more distinguished than the first.'
EXEC add_BibleVerse @BibleId, 104022016, N'And they came to Balaam and said to him, “Thus says Balak son of Zippor: ‘Please do not let anything hinder you from coming to me.'
EXEC add_BibleVerse @BibleId, 104022017, N'For I will honor you greatly, and whatever you tell me I will do. So come, put a curse on this nation for me.’”'
EXEC add_BibleVerse @BibleId, 104022018, N'Balaam replied to the servants of Balak, “Even if Balak would give me his palace full of silver and gold, I could not transgress the commandment of the Lord my God to do less or more.'
EXEC add_BibleVerse @BibleId, 104022019, N'Now therefore, please stay the night here also, that I may know what more the Lord might say to me.”'
EXEC add_BibleVerse @BibleId, 104022020, N'God came to Balaam that night, and said to him, “If the men have come to call you, get up and go with them; but the word that I will say to you, that you must do.”'
EXEC add_BibleVerse @BibleId, 104022021, N'So Balaam got up in the morning, saddled his donkey, and went with the princes of Moab.'
EXEC add_BibleVerse @BibleId, 104022022, N'Then God’s anger was kindled because he went, and the angel of the Lord stood in the road to oppose him. Now he was riding on his donkey and his two servants were with him.'
EXEC add_BibleVerse @BibleId, 104022023, N'And the donkey saw the angel of the Lord standing in the road with his sword drawn in his hand, so the donkey turned aside from the road and went into the field. But Balaam beat the donkey, to make her turn back to the road.'
EXEC add_BibleVerse @BibleId, 104022024, N'Then the angel of the Lord stood in a path among the vineyards, where there was a wall on either side.'
EXEC add_BibleVerse @BibleId, 104022025, N'And when the donkey saw the angel of the Lord, she pressed herself into the wall, and crushed Balaam’s foot against the wall. So he beat her again.'
EXEC add_BibleVerse @BibleId, 104022026, N'Then the angel of the Lord went farther, and stood in a narrow place, where there was no way to turn either to the right or to the left.'
EXEC add_BibleVerse @BibleId, 104022027, N'When the donkey saw the angel of the Lord, she crouched down under Balaam. Then Balaam was angry, and he beat his donkey with a staff.'
EXEC add_BibleVerse @BibleId, 104022028, N'Then the Lord opened the mouth of the donkey, and she said to Balaam, “What have I done to you that you have beaten me these three times?”'
EXEC add_BibleVerse @BibleId, 104022029, N'And Balaam said to the donkey, “You have made me look stupid; I wish there were a sword in my hand, for I would kill you right now.”'
EXEC add_BibleVerse @BibleId, 104022030, N'The donkey said to Balaam, “Am not I your donkey that you have ridden ever since I was yours until this day? Have I ever attempted to treat you this way?” And he said, “No.”'
EXEC add_BibleVerse @BibleId, 104022031, N'Then the Lord opened Balaam’s eyes, and he saw the angel of the Lord standing in the way with his sword drawn in his hand; so he bowed his head and threw himself down with his face to the ground.'
EXEC add_BibleVerse @BibleId, 104022032, N'The angel of the Lord said to him, “Why have you beaten your donkey these three times? Look, I came out to oppose you because what you are doing is perverse before me.'
EXEC add_BibleVerse @BibleId, 104022033, N'The donkey saw me and turned from me these three times. If she had not turned from me, I would have killed you but saved her alive.”'
EXEC add_BibleVerse @BibleId, 104022034, N'Balaam said to the angel of the Lord, “I have sinned, for I did not know that you stood against me in the road. So now, if it is evil in your sight, I will go back home.”'
EXEC add_BibleVerse @BibleId, 104022035, N'But the angel of the Lord said to Balaam, “Go with the men, but you may only speak the word that I will speak to you.” So Balaam went with the princes of Balak.'
EXEC add_BibleVerse @BibleId, 104022036, N'When Balak heard that Balaam was coming, he went out to meet him at a city of Moab which was on the border of the Arnon at the boundary of his territory.'
EXEC add_BibleVerse @BibleId, 104022037, N'Balak said to Balaam, “Did I not send again and again to you to summon you? Why did you not come to me? Am I not able to honor you?”'
EXEC add_BibleVerse @BibleId, 104022038, N'Balaam said to Balak, “Look, I have come to you. Now, am I able to speak just anything? I must speak only the word that God puts in my mouth.”'
EXEC add_BibleVerse @BibleId, 104022039, N'So Balaam went with Balak, and they came to Kiriath-huzoth.'
EXEC add_BibleVerse @BibleId, 104022040, N'And Balak sacrificed bulls and sheep, and sent some to Balaam, and to the princes who were with him.'
EXEC add_BibleVerse @BibleId, 104022041, N'Then on the next morning Balak took Balaam, and brought him up to Bamoth Baal. From there he saw the extent of the nation.'
EXEC add_BibleVerse @BibleId, 104023001, N'Balaam said to Balak, “Build me seven altars here, and prepare for me here seven bulls and seven rams.”'
EXEC add_BibleVerse @BibleId, 104023002, N'So Balak did just as Balaam had said. Balak and Balaam then offered on each altar a bull and a ram.'
EXEC add_BibleVerse @BibleId, 104023003, N'Balaam said to Balak, “Station yourself by your burnt offering, and I will go off; perhaps the Lord will come to meet me, and whatever he reveals to me I will tell you.” Then he went to a deserted height.'
EXEC add_BibleVerse @BibleId, 104023004, N'Then God met Balaam, who said to him, “I have prepared seven altars, and I have offered on each altar a bull and a ram.”'
EXEC add_BibleVerse @BibleId, 104023005, N'Then the Lord put a message in Balaam’s mouth and said, “Return to Balak, and speak what I tell you.”'
EXEC add_BibleVerse @BibleId, 104023006, N'So he returned to him, and he was still standing by his burnt offering, he and all the princes of Moab.'
EXEC add_BibleVerse @BibleId, 104023007, N'Then Balaam uttered his oracle, saying, “Balak, the king of Moab, brought me from Aram, out of the mountains of the east, saying, ‘Come, pronounce a curse on Jacob for me; come, denounce Israel.’'
EXEC add_BibleVerse @BibleId, 104023008, N'How can I curse one whom God has not cursed, or how can I denounce one whom the Lord has not denounced?'
EXEC add_BibleVerse @BibleId, 104023009, N'For from the top of the rocks I see them; from the hills I watch them. Indeed, a nation that lives alone, and it will not be reckoned among the nations.'
EXEC add_BibleVerse @BibleId, 104023010, N'Who can count the dust of Jacob, Or number the fourth part of Israel? Let me die the death of the upright, and let the end of my life be like theirs.”'
EXEC add_BibleVerse @BibleId, 104023011, N'Then Balak said to Balaam, “What have you done to me? I brought you to curse my enemies, but on the contrary you have only blessed them!”'
EXEC add_BibleVerse @BibleId, 104023012, N'Balaam replied, “Must I not be careful to speak what the Lord has put in my mouth?”'
EXEC add_BibleVerse @BibleId, 104023013, N'Balak said to him, “Please come with me to another place from which you can observe them. You will see only a part of them, but you will not see all of them. Curse them for me from there.”'
EXEC add_BibleVerse @BibleId, 104023014, N'So Balak brought Balaam to the field of Zophim, to the top of Pisgah, where he built seven altars and offered a bull and a ram on each altar.'
EXEC add_BibleVerse @BibleId, 104023015, N'And Balaam said to Balak, “Station yourself here by your burnt offering, while I meet the Lord there.'
EXEC add_BibleVerse @BibleId, 104023016, N'Then the Lord met Balaam and put a message in his mouth and said, “Return to Balak, and speak what I tell you.”'
EXEC add_BibleVerse @BibleId, 104023017, N'When Balaam came to him, he was still standing by his burnt offering, along with the princes of Moab. And Balak said to him, “What has the Lord spoken?”'
EXEC add_BibleVerse @BibleId, 104023018, N'Balaam uttered his oracle, and said, “Rise up, Balak, and hear; Listen to me, son of Zippor:'
EXEC add_BibleVerse @BibleId, 104023019, N'God is not a man, that he should lie, nor a human being, that he should change his mind. Has he said, and will he not do it? Or has he spoken, and will he not make it happen?'
EXEC add_BibleVerse @BibleId, 104023020, N'Indeed, I have received a command to bless; he has blessed, and I cannot reverse it.'
EXEC add_BibleVerse @BibleId, 104023021, N'He has not looked on iniquity in Jacob, nor has he seen trouble in Israel. The Lord their God is with them; his acclamation as king is among them.'
EXEC add_BibleVerse @BibleId, 104023022, N'God brought them out of Egypt. They have, as it were, the strength of a wild bull.'
EXEC add_BibleVerse @BibleId, 104023023, N'For there is no spell against Jacob, nor is there any divination against Israel. At this time it must be said of Jacob and of Israel, ‘Look at what God has done!’'
EXEC add_BibleVerse @BibleId, 104023024, N'Indeed, the people will rise up like a lioness, and like a lion raises himself up; they will not lie down until they eat their prey, and drink the blood of the slain.”'
EXEC add_BibleVerse @BibleId, 104023025, N'Balak said to Balaam, “Neither curse them at all nor bless them at all!”'
EXEC add_BibleVerse @BibleId, 104023026, N'But Balaam replied to Balak, “Did I not tell you, ‘All that the Lord speaks, I must do’?”'
EXEC add_BibleVerse @BibleId, 104023027, N'Balak said to Balaam, “Come, please; I will take you to another place. Perhaps it will please God to let you curse them for me from there.”'
EXEC add_BibleVerse @BibleId, 104023028, N'So Balak took Balaam to the top of Peor, that looks toward the wilderness.'
EXEC add_BibleVerse @BibleId, 104023029, N'Then Balaam said to Balak, “Build seven altars here for me, and prepare seven bulls and seven rams.”'
EXEC add_BibleVerse @BibleId, 104023030, N'So Balak did as Balaam had said, and offered a bull and a ram on each altar.'
EXEC add_BibleVerse @BibleId, 104024001, N'When Balaam saw that it pleased the Lord to bless Israel, he did not go as at the other times to seek for omens, but he set his face toward the wilderness.'
EXEC add_BibleVerse @BibleId, 104024002, N'When Balaam lifted up his eyes, he saw Israel camped tribe by tribe; and the Spirit of God came upon him.'
EXEC add_BibleVerse @BibleId, 104024003, N'Then he uttered this oracle: “The oracle of Balaam son of Beor; the oracle of the man whose eyes are open;'
EXEC add_BibleVerse @BibleId, 104024004, N'the oracle of the one who hears the words of God, who sees a vision from the Almighty, although falling flat on the ground with eyes open:'
EXEC add_BibleVerse @BibleId, 104024005, N'‘How beautiful are your tents, O Jacob, and your dwelling places, O Israel!'
EXEC add_BibleVerse @BibleId, 104024006, N'They are like valleys stretched forth, like gardens by the river’s side, like aloes that the Lord has planted, and like cedar trees beside the waters.'
EXEC add_BibleVerse @BibleId, 104024007, N'He will pour the water out of his buckets, and their descendants will be like abundant water; their king will be greater than Agag, and their kingdom will be exalted.'
EXEC add_BibleVerse @BibleId, 104024008, N'God brought them out of Egypt. They have, as it were, the strength of a young bull; they will devour hostile people and will break their bones and will pierce them through with arrows.'
EXEC add_BibleVerse @BibleId, 104024009, N'They crouch and lie down like a lion, and as a lioness, who can stir him? Blessed is the one who blesses you, and cursed is the one who curses you!’”'
EXEC add_BibleVerse @BibleId, 104024010, N'Then Balak became very angry at Balaam, and he struck his hands together. Balak said to Balaam, “I called you to curse my enemies, and look, you have done nothing but bless them these three times!'
EXEC add_BibleVerse @BibleId, 104024011, N'So now, go back where you came from! I said that I would greatly honor you; but now the Lord has stood in the way of your honor.”'
EXEC add_BibleVerse @BibleId, 104024012, N'Balaam said to Balak, “Did I not also tell your messengers whom you sent to me,'
EXEC add_BibleVerse @BibleId, 104024013, N'‘If Balak would give me his palace full of silver and gold, I cannot go beyond the commandment of the Lord to do either good or evil of my own will, but whatever the Lord tells me I must speak’?'
EXEC add_BibleVerse @BibleId, 104024014, N'And now, I am about to go back to my own people. Come now, and I will advise you as to what this people will do to your people in the future.”'
EXEC add_BibleVerse @BibleId, 104024015, N'Then he uttered this oracle: “The oracle of Balaam son of Beor; the oracle of the man whose eyes are open;'
EXEC add_BibleVerse @BibleId, 104024016, N'the oracle of the one who hears the words of God, and who knows the knowledge of the Most High, who sees a vision from the Almighty, although falling flat on the ground with eyes open:'
EXEC add_BibleVerse @BibleId, 104024017, N'‘I see him, but not now; I behold him, but not close at hand. A star will march forth out of Jacob, and a scepter will rise out of Israel. He will crush the skulls of Moab, and the heads of all the sons of Sheth.'
EXEC add_BibleVerse @BibleId, 104024018, N'Edom will be a possession, Seir, his enemies, will also be a possession; but Israel will act valiantly.'
EXEC add_BibleVerse @BibleId, 104024019, N'A ruler will be established from Jacob; he will destroy the remains of the city.’”'
EXEC add_BibleVerse @BibleId, 104024020, N'Then Balaam looked on Amalek and delivered this oracle: “Amalek was the first of the nations, but his end will be that he will perish.”'
EXEC add_BibleVerse @BibleId, 104024021, N'Then he looked on the Kenites and uttered this oracle: “Your dwelling place seems strong, and your nest is set on a rocky cliff.'
EXEC add_BibleVerse @BibleId, 104024022, N'Nevertheless the Kenite will be consumed. How long will Asshur take you away captive?”'
EXEC add_BibleVerse @BibleId, 104024023, N'Then he uttered this oracle: “O, who will survive when God does this!'
EXEC add_BibleVerse @BibleId, 104024024, N'Ships will come from the coast of Kittim, and will afflict Asshur, and will afflict Eber, and he will also perish forever.”'
EXEC add_BibleVerse @BibleId, 104024025, N'Balaam got up and departed and returned to his home, and Balak also went his way.'
EXEC add_BibleVerse @BibleId, 104025001, N'When Israel lived in Shittim, the people began to commit sexual immorality with the daughters of Moab.'
EXEC add_BibleVerse @BibleId, 104025002, N'These women invited the people to the sacrifices of their gods; then the people ate and bowed down to their gods.'
EXEC add_BibleVerse @BibleId, 104025003, N'When Israel joined themselves to Baal-peor, the anger of the Lord flared up against Israel.'
EXEC add_BibleVerse @BibleId, 104025004, N'The Lord said to Moses, “Arrest all the leaders of the people, and hang them up before the Lord in broad daylight, so that the fierce anger of the Lord may be turned away from Israel.”'
EXEC add_BibleVerse @BibleId, 104025005, N'So Moses said to the judges of Israel, “Each of you must execute those of his men who were joined to Baal-peor.”'
EXEC add_BibleVerse @BibleId, 104025006, N'Just then one of the Israelites came and brought to his brothers a Midianite woman in the plain view of Moses and of the whole community of the Israelites, while they were weeping at the entrance of the tent of meeting.'
EXEC add_BibleVerse @BibleId, 104025007, N'When Phinehas son of Eleazar, the son of Aaron the priest, saw it, he got up from among the assembly, took a javelin in his hand,'
EXEC add_BibleVerse @BibleId, 104025008, N'and went after the Israelite man into the tent and thrust through the Israelite man and into the woman’s abdomen. So the plague was stopped from the Israelites.'
EXEC add_BibleVerse @BibleId, 104025009, N'Those that died in the plague were 24,000.'
EXEC add_BibleVerse @BibleId, 104025010, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104025011, N'“Phinehas son of Eleazar, the son of Aaron the priest, has turned my anger away from the Israelites, when he manifested such zeal for my sake among them, so that I did not consume the Israelites in my zeal.'
EXEC add_BibleVerse @BibleId, 104025012, N'Therefore, announce: ‘I am going to give to him my covenant of peace.'
EXEC add_BibleVerse @BibleId, 104025013, N'So it will be to him and his descendants after him a covenant of a permanent priesthood, because he has been zealous for his God, and has made atonement for the Israelites.’”'
EXEC add_BibleVerse @BibleId, 104025014, N'Now the name of the Israelite who was stabbed – the one who was stabbed with the Midianite woman – was Zimri son of Salu, a leader of a clan of the Simeonites.'
EXEC add_BibleVerse @BibleId, 104025015, N'The name of the Midianite woman who was killed was Cozbi daughter of Zur. He was a leader over the people of a clan of Midian.'
EXEC add_BibleVerse @BibleId, 104025016, N'Then the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104025017, N'“Bring trouble to the Midianites, and destroy them,'
EXEC add_BibleVerse @BibleId, 104025018, N'because they bring trouble to you by their treachery with which they have deceived you in the matter of Peor, and in the matter of Cozbi, the daughter of a prince of Midian, their sister, who was killed on the day of the plague that happened as a result of Peor.”'
EXEC add_BibleVerse @BibleId, 104026001, N'After the plague the Lord said to Moses and to Eleazar son of Aaron the priest,'
EXEC add_BibleVerse @BibleId, 104026002, N'“Take a census of the whole community of Israelites, from twenty years old and upward, by their clans, everyone who can serve in the army of Israel.”'
EXEC add_BibleVerse @BibleId, 104026003, N'So Moses and Eleazar the priest spoke with them in the plains of Moab, by the Jordan River across from Jericho. They said,'
EXEC add_BibleVerse @BibleId, 104026004, N'“Number the people from twenty years old and upward, just as the Lord commanded Moses and the Israelites who went out from the land of Egypt.”'
EXEC add_BibleVerse @BibleId, 104026005, N'Reuben was the firstborn of Israel. The Reubenites: from Hanoch, the family of the Hanochites; from Pallu, the family of the Palluites;'
EXEC add_BibleVerse @BibleId, 104026006, N'from Hezron, the family of the Hezronites; from Carmi, the family of the Carmites.'
EXEC add_BibleVerse @BibleId, 104026007, N'These were the families of the Reubenites; and those numbered of them were 43,730.'
EXEC add_BibleVerse @BibleId, 104026008, N'Pallu’s descendant was Eliab.'
EXEC add_BibleVerse @BibleId, 104026009, N'Eliab’s descendants were Nemuel, Dathan, and Abiram. It was Dathan and Abiram who as leaders of the community rebelled against Moses and Aaron with the followers of Korah when they rebelled against the Lord.'
EXEC add_BibleVerse @BibleId, 104026010, N'The earth opened its mouth and swallowed them and Korah at the time that company died, when the fire consumed 250 men. So they became a warning.'
EXEC add_BibleVerse @BibleId, 104026011, N'But the descendants of Korah did not die.'
EXEC add_BibleVerse @BibleId, 104026012, N'The Simeonites by their families: from Nemuel, the family of the Nemuelites; from Jamin, the family of the Jaminites; from Jakin, the family of the Jakinites;'
EXEC add_BibleVerse @BibleId, 104026013, N'from Zerah, the family of the Zerahites; and from Shaul, the family of the Shaulites.'
EXEC add_BibleVerse @BibleId, 104026014, N'These were the families of the Simeonites, 22,200.'
EXEC add_BibleVerse @BibleId, 104026015, N'The Gadites by their families: from Zephon, the family of the Zephonites; from Haggi, the family of the Haggites; from Shuni, the family of the Shunites;'
EXEC add_BibleVerse @BibleId, 104026016, N'from Ozni, the family of the Oznites; from Eri, the family of the Erites;'
EXEC add_BibleVerse @BibleId, 104026017, N'from Arod, the family of the Arodites, and from Areli, the family of the Arelites.'
EXEC add_BibleVerse @BibleId, 104026018, N'These were the families of the Gadites according to those numbered of them, 40,500.'
EXEC add_BibleVerse @BibleId, 104026019, N'The descendants of Judah were Er and Onan, but Er and Onan died in the land of Canaan.'
EXEC add_BibleVerse @BibleId, 104026020, N'And the Judahites by their families were: from Shelah, the family of the Shelahites; from Perez, the family of the Perezites; and from Zerah, the family of the Zerahites.'
EXEC add_BibleVerse @BibleId, 104026021, N'And the Perezites were: from Hezron, the family of the Hezronites; from Hamul, the family of the Hamulites.'
EXEC add_BibleVerse @BibleId, 104026022, N'These were the families of Judah according to those numbered of them, 76,500.'
EXEC add_BibleVerse @BibleId, 104026023, N'The Issacharites by their families: from Tola, the family of the Tolaites; from Puah, the family of the Puites;'
EXEC add_BibleVerse @BibleId, 104026024, N'from Jashub, the family of the Jashubites; and from Shimron, the family of the Shimronites.'
EXEC add_BibleVerse @BibleId, 104026025, N'These were the families of Issachar, according to those numbered of them, 64,300.'
EXEC add_BibleVerse @BibleId, 104026026, N'The Zebulunites by their families: from Sered, the family of the Sardites; from Elon, the family of the Elonites; from Jahleel, the family of the Jahleelites.'
EXEC add_BibleVerse @BibleId, 104026027, N'These were the families of the Zebulunites, according to those numbered of them, 60,500.'
EXEC add_BibleVerse @BibleId, 104026028, N'The descendants of Joseph by their families: Manasseh and Ephraim.'
EXEC add_BibleVerse @BibleId, 104026029, N'The Manassehites: from Machir, the family of the Machirites (now Machir became the father of Gilead); from Gilead, the family of the Gileadites.'
EXEC add_BibleVerse @BibleId, 104026030, N'These were the Gileadites: from Iezer, the family of the Iezerites; from Helek, the family of the Helekites;'
EXEC add_BibleVerse @BibleId, 104026031, N'from Asriel, the family of the Asrielites; from Shechem, the family of the Shechemites;'
EXEC add_BibleVerse @BibleId, 104026032, N'from Shemida, the family of the Shemidaites; from Hepher, the family of the Hepherites.'
EXEC add_BibleVerse @BibleId, 104026033, N'Now Zelophehad son of Hepher had no sons, but only daughters; and the names of the daughters of Zelophehad were Mahlah, Noah, Hoglah, Milcah, and Tirzah.'
EXEC add_BibleVerse @BibleId, 104026034, N'These were the families of Manasseh; those numbered of them were 52,700.'
EXEC add_BibleVerse @BibleId, 104026035, N'These are the Ephraimites by their families: from Shuthelah, the family of the Shuthelahites; from Beker, the family of the Bekerites; from Tahan, the family of the Tahanites.'
EXEC add_BibleVerse @BibleId, 104026036, N'Now these were the Shuthelahites: from Eran, the family of the Eranites.'
EXEC add_BibleVerse @BibleId, 104026037, N'These were the families of the Ephraimites, according to those numbered of them, 32,500. These were the descendants of Joseph by their families.'
EXEC add_BibleVerse @BibleId, 104026038, N'The Benjaminites by their families: from Bela, the family of the Belaites; from Ashbel, the family of the Ashbelites; from Ahiram, the family of the Ahiramites;'
EXEC add_BibleVerse @BibleId, 104026039, N'from Shupham, the family of the Shuphamites; from Hupham, the family of the Huphamites.'
EXEC add_BibleVerse @BibleId, 104026040, N'The descendants of Bela were Ard and Naaman. From Ard, the family of the Ardites; from Naaman, the family of the Naamanites.'
EXEC add_BibleVerse @BibleId, 104026041, N'These are the Benjaminites, according to their families, and according to those numbered of them, 45,600.'
EXEC add_BibleVerse @BibleId, 104026042, N'These are the Danites by their families: from Shuham, the family of the Shuhamites. These were the families of Dan, according to their families.'
EXEC add_BibleVerse @BibleId, 104026043, N'All the families of the Shuhahites according to those numbered of them were 64,400.'
EXEC add_BibleVerse @BibleId, 104026044, N'The Asherites by their families: from Imnah, the family of the Imnahites; from Ishvi, the family of the Ishvites; from Beriah, the family of the Beriahites.'
EXEC add_BibleVerse @BibleId, 104026045, N'From the Beriahites: from Heber, the family of the Heberites; from Malkiel, the family of the Malkielites.'
EXEC add_BibleVerse @BibleId, 104026046, N'Now the name of the daughter of Asher was Serah.'
EXEC add_BibleVerse @BibleId, 104026047, N'These are the families of the Asherites, according to those numbered of them, 53,400.'
EXEC add_BibleVerse @BibleId, 104026048, N'The Naphtalites by their families: from Jahzeel, the family of the Jahzeelites; from Guni, the family of the Gunites;'
EXEC add_BibleVerse @BibleId, 104026049, N'from Jezer, the family of the Jezerites; from Shillem, the family of the Shillemites.'
EXEC add_BibleVerse @BibleId, 104026050, N'These were the families of Naphtali according to their families; and those numbered of them were 45,400.'
EXEC add_BibleVerse @BibleId, 104026051, N'These were those numbered of the Israelites, 601,730.'
EXEC add_BibleVerse @BibleId, 104026052, N'Then the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104026053, N'“To these the land must be divided as an inheritance according to the number of the names.'
EXEC add_BibleVerse @BibleId, 104026054, N'To a larger group you will give a larger inheritance, and to a smaller group you will give a smaller inheritance. To each one its inheritance must be given according to the number of people in it.'
EXEC add_BibleVerse @BibleId, 104026055, N'The land must be divided by lot; and they will inherit in accordance with the names of their ancestral tribes.'
EXEC add_BibleVerse @BibleId, 104026056, N'Their inheritance must be apportioned by lot among the larger and smaller groups.'
EXEC add_BibleVerse @BibleId, 104026057, N'And these are the Levites who were numbered according to their families: from Gershon, the family of the Gershonites; of Kohath, the family of the Kohathites; from Merari, the family of the Merarites.'
EXEC add_BibleVerse @BibleId, 104026058, N'These are the families of the Levites: the family of the Libnites, the family of the Hebronites, the family of the Mahlites, the family of the Mushites, the family of the Korahites. Kohath became the father of Amram.'
EXEC add_BibleVerse @BibleId, 104026059, N'Now the name of Amram’s wife was Jochebed, daughter of Levi, who was born to Levi in Egypt. And to Amram she bore Aaron, Moses, and Miriam their sister.'
EXEC add_BibleVerse @BibleId, 104026060, N'And to Aaron were born Nadab and Abihu, Eleazar and Ithamar.'
EXEC add_BibleVerse @BibleId, 104026061, N'But Nadab and Abihu died when they offered strange fire before the Lord.'
EXEC add_BibleVerse @BibleId, 104026062, N'Those of them who were numbered were 23,000, all males from a month old and upward, for they were not numbered among the Israelites; no inheritance was given to them among the Israelites.'
EXEC add_BibleVerse @BibleId, 104026063, N'These are those who were numbered by Moses and Eleazar the priest, who numbered the Israelites in the plains of Moab along the Jordan River opposite Jericho.'
EXEC add_BibleVerse @BibleId, 104026064, N'But there was not a man among these who had been among those numbered by Moses and Aaron the priest when they numbered the Israelites in the wilderness of Sinai.'
EXEC add_BibleVerse @BibleId, 104026065, N'For the Lord had said of them, “They will surely die in the wilderness.” And there was not left a single man of them, except Caleb son of Jephunneh and Joshua son of Nun.'
EXEC add_BibleVerse @BibleId, 104027001, N'Then the daughters of Zelophehad son of Hepher, the son of Gilead, the son of Machir, the son of Manasseh of the families of Manasseh, the son Joseph came forward. Now these are the names of his daughters: Mahlah, Noah, Hoglah, Milcah, and Tirzah.'
EXEC add_BibleVerse @BibleId, 104027002, N'And they stood before Moses and Eleazar the priest and the leaders of the whole assembly at the entrance to the tent of meeting and said,'
EXEC add_BibleVerse @BibleId, 104027003, N'“Our father died in the wilderness, although he was not part of the company of those that gathered themselves together against the Lord in the company of Korah; but he died for his own sin, and he had no sons.'
EXEC add_BibleVerse @BibleId, 104027004, N'Why should the name of our father be lost from among his family because he had no son? Give us a possession among the relatives of our father.”'
EXEC add_BibleVerse @BibleId, 104027005, N'So Moses brought their case before the Lord.'
EXEC add_BibleVerse @BibleId, 104027006, N'The Lord said to Moses:'
EXEC add_BibleVerse @BibleId, 104027007, N'“The daughters of Zelophehad have a valid claim. You must indeed give them possession of an inheritance among their father’s relatives, and you must transfer the inheritance of their father to them.'
EXEC add_BibleVerse @BibleId, 104027008, N'And you must tell the Israelites, ‘If a man dies and has no son, then you must transfer his inheritance to his daughter;'
EXEC add_BibleVerse @BibleId, 104027009, N'and if he has no daughter, then you are to give his inheritance to his brothers;'
EXEC add_BibleVerse @BibleId, 104027010, N'and if he has no brothers, then you are to give his inheritance to his father’s brothers;'
EXEC add_BibleVerse @BibleId, 104027011, N'and if his father has no brothers, then you are to give his inheritance to his relative nearest to him from his family, and he will possess it. This will be for the Israelites a legal requirement, as the Lord commanded Moses.’”'
EXEC add_BibleVerse @BibleId, 104027012, N'Then the Lord said to Moses, “Go up this mountain of the Abarim range, and see the land I have given to the Israelites.'
EXEC add_BibleVerse @BibleId, 104027013, N'When you have seen it, you will be gathered to your ancestors, as Aaron your brother was gathered to his ancestors.'
EXEC add_BibleVerse @BibleId, 104027014, N'For in the wilderness of Zin when the community rebelled against me, you rebelled against my command to show me as holy before their eyes over the water – the water of Meribah in Kadesh in the wilderness of Zin.”'
EXEC add_BibleVerse @BibleId, 104027015, N'Then Moses spoke to the Lord:'
EXEC add_BibleVerse @BibleId, 104027016, N'“Let the Lord, the God of the spirits of all humankind, appoint a man over the community,'
EXEC add_BibleVerse @BibleId, 104027017, N'who will go out before them, and who will come in before them, and who will lead them out, and who will bring them in, so that the community of the Lord may not be like sheep that have no shepherd.”'
EXEC add_BibleVerse @BibleId, 104027018, N'The Lord replied to Moses, “Take Joshua son of Nun, a man in whom is such a spirit, and lay your hand on him;'
EXEC add_BibleVerse @BibleId, 104027019, N'set him before Eleazar the priest and before the whole community, and commission him publicly.'
EXEC add_BibleVerse @BibleId, 104027020, N'Then you must delegate some of your authority to him, so that the whole community of the Israelites will be obedient.'
EXEC add_BibleVerse @BibleId, 104027021, N'And he will stand before Eleazar the priest, who will seek counsel for him before the Lord by the decision of the Urim. At his command they will go out, and at his command they will come in, he and all the Israelites with him, the whole community.”'
EXEC add_BibleVerse @BibleId, 104027022, N'So Moses did as the Lord commanded him; he took Joshua and set him before Eleazar the priest and before the whole community.'
EXEC add_BibleVerse @BibleId, 104027023, N'He laid his hands on him and commissioned him, just as the Lord commanded, by the authority of Moses.'
EXEC add_BibleVerse @BibleId, 104028001, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104028002, N'“Command the Israelites: ‘With regard to my offering, be sure to offer my food for my offering made by fire, as a pleasing aroma to me at its appointed time.’'
EXEC add_BibleVerse @BibleId, 104028003, N'You will say to them, ‘This is the offering made by fire which you must offer to the Lord: two unblemished lambs one year old each day for a continual burnt offering.'
EXEC add_BibleVerse @BibleId, 104028004, N'The first lamb you must offer in the morning, and the second lamb you must offer in the late afternoon,'
EXEC add_BibleVerse @BibleId, 104028005, N'with one-tenth of an ephah of finely ground flour as a grain offering mixed with one quarter of a hin of pressed olive oil.'
EXEC add_BibleVerse @BibleId, 104028006, N'It is a continual burnt offering that was instituted on Mount Sinai as a pleasing aroma, an offering made by fire to the Lord.'
EXEC add_BibleVerse @BibleId, 104028007, N'“‘And its drink offering must be one quarter of a hin for each lamb. You must pour out the strong drink as a drink offering to the Lord in the holy place.'
EXEC add_BibleVerse @BibleId, 104028008, N'And the second lamb you must offer in the late afternoon; just as you offered the grain offering and drink offering in the morning, you must offer it as an offering made by fire, as a pleasing aroma to the Lord.'
EXEC add_BibleVerse @BibleId, 104028009, N'“‘On the Sabbath day, you must offer two unblemished lambs a year old, and two-tenths of an ephah of finely ground flour as a grain offering, mixed with olive oil, along with its drink offering.'
EXEC add_BibleVerse @BibleId, 104028010, N'This is the burnt offering for every Sabbath, besides the continual burnt offering and its drink offering.'
EXEC add_BibleVerse @BibleId, 104028011, N'“‘On the first day of each month you must offer as a burnt offering to the Lord two young bulls, one ram, and seven unblemished lambs a year old,'
EXEC add_BibleVerse @BibleId, 104028012, N'with three-tenths of an ephah of finely ground flour mixed with olive oil as a grain offering for each bull, and two-tenths of an ephah of finely ground flour mixed with olive oil as a grain offering for the ram,'
EXEC add_BibleVerse @BibleId, 104028013, N'and one-tenth of an ephah of finely ground flour mixed with olive oil as a grain offering for each lamb, as a burnt offering for a pleasing aroma, an offering made by fire to the Lord.'
EXEC add_BibleVerse @BibleId, 104028014, N'For their drink offerings, include half a hin of wine with each bull, one-third of a hin for the ram, and one-fourth of a hin for each lamb. This is the burnt offering for each month throughout the months of the year.'
EXEC add_BibleVerse @BibleId, 104028015, N'And one male goat must be offered to the Lord as a purification offering, in addition to the continual burnt offering and its drink offering.'
EXEC add_BibleVerse @BibleId, 104028016, N'“‘On the fourteenth day of the first month is the Lord’s Passover.'
EXEC add_BibleVerse @BibleId, 104028017, N'And on the fifteenth day of this month is the festival. For seven days bread made without yeast must be eaten.'
EXEC add_BibleVerse @BibleId, 104028018, N'And on the first day there is to be a holy assembly; you must do no ordinary work on it.'
EXEC add_BibleVerse @BibleId, 104028019, N'“‘But you must offer to the Lord an offering made by fire, a burnt offering of two young bulls, one ram, and seven lambs one year old; they must all be unblemished.'
EXEC add_BibleVerse @BibleId, 104028020, N'And their grain offering is to be of finely ground flour mixed with olive oil. For each bull you must offer three-tenths of an ephah, and two-tenths for the ram.'
EXEC add_BibleVerse @BibleId, 104028021, N'For each of the seven lambs you are to offer one-tenth of an ephah,'
EXEC add_BibleVerse @BibleId, 104028022, N'as well as one goat for a purification offering, to make atonement for you.'
EXEC add_BibleVerse @BibleId, 104028023, N'You must offer these in addition to the burnt offering in the morning which is for a continual burnt offering.'
EXEC add_BibleVerse @BibleId, 104028024, N'In this manner you must offer daily throughout the seven days the food of the sacrifice made by fire as a sweet aroma to the Lord. It is to be offered in addition to the continual burnt offering and its drink offering.'
EXEC add_BibleVerse @BibleId, 104028025, N'On the seventh day you are to have a holy assembly, you must do no regular work.'
EXEC add_BibleVerse @BibleId, 104028026, N'“‘Also, on the day of the first fruits, when you bring a new grain offering to the Lord during your Feast of Weeks, you are to have a holy assembly. You must do no ordinary work.'
EXEC add_BibleVerse @BibleId, 104028027, N'But you must offer as the burnt offering, as a sweet aroma to the Lord, two young bulls, one ram, seven lambs one year old,'
EXEC add_BibleVerse @BibleId, 104028028, N'with their grain offering of finely ground flour mixed with olive oil: three-tenths of an ephah for each bull, two-tenths for the one ram,'
EXEC add_BibleVerse @BibleId, 104028029, N'with one-tenth for each of the seven lambs,'
EXEC add_BibleVerse @BibleId, 104028030, N'as well as one male goat to make an atonement for you.'
EXEC add_BibleVerse @BibleId, 104028031, N'You are to offer them with their drink offerings in addition to the continual burnt offering and its grain offering – they must be unblemished.'
EXEC add_BibleVerse @BibleId, 104029001, N'“‘On the first day of the seventh month, you are to hold a holy assembly. You must not do your ordinary work, for it is a day of blowing trumpets for you.'
EXEC add_BibleVerse @BibleId, 104029002, N'You must offer a burnt offering as a sweet aroma to the Lord: one young bull, one ram, and seven lambs one year old without blemish.'
EXEC add_BibleVerse @BibleId, 104029003, N'“‘Their grain offering is to be of finely ground flour mixed with olive oil, three-tenths of an ephah for the bull, two-tenths of an ephah for the ram,'
EXEC add_BibleVerse @BibleId, 104029004, N'and one-tenth for each of the seven lambs,'
EXEC add_BibleVerse @BibleId, 104029005, N'with one male goat for a purification offering to make an atonement for you;'
EXEC add_BibleVerse @BibleId, 104029006, N'this is in addition to the monthly burnt offering and its grain offering, and the daily burnt offering with its grain offering and their drink offerings as prescribed, as a sweet aroma, a sacrifice made by fire to the Lord.'
EXEC add_BibleVerse @BibleId, 104029007, N'“‘On the tenth day of this seventh month you are to have a holy assembly. You must humble yourselves; you must not do any work on it.'
EXEC add_BibleVerse @BibleId, 104029008, N'But you must offer a burnt offering as a pleasing aroma to the Lord, one young bull, one ram, and seven lambs one year old, all of them without blemish.'
EXEC add_BibleVerse @BibleId, 104029009, N'Their grain offering must be of finely ground flour mixed with olive oil, three-tenths of an ephah for the bull, two-tenths for the ram,'
EXEC add_BibleVerse @BibleId, 104029010, N'and one-tenth for each of the seven lambs,'
EXEC add_BibleVerse @BibleId, 104029011, N'along with one male goat for a purification offering, in addition to the purification offering for atonement and the continual burnt offering with its grain offering and their drink offerings.'
EXEC add_BibleVerse @BibleId, 104029012, N'“‘On the fifteenth day of the seventh month you are to have a holy assembly; you must do no ordinary work, and you must keep a festival to the Lord for seven days.'
EXEC add_BibleVerse @BibleId, 104029013, N'You must offer a burnt offering, an offering made by fire as a pleasing aroma to the Lord: thirteen young bulls, two rams, and fourteen lambs each one year old, all of them without blemish.'
EXEC add_BibleVerse @BibleId, 104029014, N'Their grain offering must be of finely ground flour mixed with olive oil, three-tenths of an ephah for each of the thirteen bulls, two-tenths of an ephah for each of the two rams,'
EXEC add_BibleVerse @BibleId, 104029015, N'and one-tenth for each of the fourteen lambs,'
EXEC add_BibleVerse @BibleId, 104029016, N'along with one male goat for a purification offering, in addition to the continual burnt offering with its grain offering and its drink offering.'
EXEC add_BibleVerse @BibleId, 104029017, N'“‘On the second day you must offer twelve young bulls, two rams, fourteen lambs one year old, all without blemish,'
EXEC add_BibleVerse @BibleId, 104029018, N'and their grain offering and their drink offerings for the bulls, for the rams, and for the lambs, according to their number as prescribed,'
EXEC add_BibleVerse @BibleId, 104029019, N'along with one male goat for a purification offering, in addition to the continual burnt offering with its grain offering and their drink offerings.'
EXEC add_BibleVerse @BibleId, 104029020, N'“‘On the third day you must offer eleven bulls, two rams, fourteen lambs one year old, all without blemish,'
EXEC add_BibleVerse @BibleId, 104029021, N'and their grain offering and their drink offerings for the bulls, for the rams, and for the lambs, according to their number as prescribed,'
EXEC add_BibleVerse @BibleId, 104029022, N'along with one male goat for a purification offering, in addition to the continual burnt offering with its grain offering and its drink offering.'
EXEC add_BibleVerse @BibleId, 104029023, N'“‘On the fourth day you must offer ten bulls, two rams, and fourteen lambs one year old, all without blemish,'
EXEC add_BibleVerse @BibleId, 104029024, N'and their grain offering and their drink offerings for the bulls, for the rams, and for the lambs, according to their number as prescribed,'
EXEC add_BibleVerse @BibleId, 104029025, N'along with one male goat for a purification offering, in addition to the continual burnt offering with its grain offering and its drink offering.'
EXEC add_BibleVerse @BibleId, 104029026, N'“‘On the fifth day you must offer nine bulls, two rams, and fourteen lambs one year old, all without blemish,'
EXEC add_BibleVerse @BibleId, 104029027, N'and their grain offering and their drink offerings for the bulls, for the rams, and for the lambs, according to their number as prescribed,'
EXEC add_BibleVerse @BibleId, 104029028, N'along with one male goat for a purification offering, in addition to the continual burnt offering with its grain offering and its drink offering.'
EXEC add_BibleVerse @BibleId, 104029029, N'“‘On the sixth day you must offer eight bulls, two rams, and fourteen lambs one year old, all without blemish,'
EXEC add_BibleVerse @BibleId, 104029030, N'and their grain offering and their drink offerings for the bulls, for the rams, and for the lambs, according to their number as prescribed,'
EXEC add_BibleVerse @BibleId, 104029031, N'along with one male goat for a purification offering, in addition to the continual burnt offering with its grain offering and its drink offering.'
EXEC add_BibleVerse @BibleId, 104029032, N'“‘On the seventh day you must offer seven bulls, two rams, and fourteen lambs one year old, all without blemish,'
EXEC add_BibleVerse @BibleId, 104029033, N'and their grain offering and their drink offerings for the bulls, for the rams, and for the lambs, according to their number as prescribed,'
EXEC add_BibleVerse @BibleId, 104029034, N'along with one male goat for a purification offering, in addition to the continual burnt offering with its grain offering and its drink offering.'
EXEC add_BibleVerse @BibleId, 104029035, N'“‘On the eighth day you are to have a holy assembly; you must do no ordinary work on it.'
EXEC add_BibleVerse @BibleId, 104029036, N'But you must offer a burnt offering, an offering made by fire, as a pleasing aroma to the Lord, one bull, one ram, seven lambs one year old, all of them without blemish,'
EXEC add_BibleVerse @BibleId, 104029037, N'and with their grain offering and their drink offerings for the bull, for the ram, and for the lambs, according to their number as prescribed,'
EXEC add_BibleVerse @BibleId, 104029038, N'along with one male goat for a purification offering, in addition to the continual burnt offering with its grain offering and its drink offering.'
EXEC add_BibleVerse @BibleId, 104029039, N'“‘These things you must present to the Lord at your appointed times, in addition to your vows and your freewill offerings, as your burnt offerings, your grain offerings, your drink offerings, and your peace offerings.’”'
EXEC add_BibleVerse @BibleId, 104029040, N'So Moses told the Israelites everything, just as the Lord had commanded him.'
EXEC add_BibleVerse @BibleId, 104030001, N'Moses told the leaders of the tribes concerning the Israelites, “This is what the Lord has commanded:'
EXEC add_BibleVerse @BibleId, 104030002, N'If a man makes a vow to the Lord or takes an oath of binding obligation on himself, he must not break his word, but must do whatever he has promised.'
EXEC add_BibleVerse @BibleId, 104030003, N'“If a young woman who is still living in her father’s house makes a vow to the Lord or places herself under an obligation,'
EXEC add_BibleVerse @BibleId, 104030004, N'and her father hears of her vow or the obligation to which she has pledged herself, and her father remains silent about her, then all her vows will stand, and every obligation to which she has pledged herself will stand.'
EXEC add_BibleVerse @BibleId, 104030005, N'But if her father overrules her when he hears about it, then none of her vows or her obligations which she has pledged for herself will stand. And the Lord will release her from it, because her father overruled her.'
EXEC add_BibleVerse @BibleId, 104030006, N'“And if she marries a husband while under a vow, or she uttered anything impulsively by which she has pledged herself,'
EXEC add_BibleVerse @BibleId, 104030007, N'and her husband hears about it, but remains silent about her when he hears about it, then her vows will stand and her obligations which she has pledged for herself will stand.'
EXEC add_BibleVerse @BibleId, 104030008, N'But if when her husband hears it he overrules her, then he will nullify the vow she has taken, and whatever she uttered impulsively which she has pledged for herself. And the Lord will release her from it.'
EXEC add_BibleVerse @BibleId, 104030009, N'“But every vow of a widow or of a divorced woman which she has pledged for herself will remain intact.'
EXEC add_BibleVerse @BibleId, 104030010, N'If she made the vow in her husband’s house or put herself under obligation with an oath,'
EXEC add_BibleVerse @BibleId, 104030011, N'and her husband heard about it, but remained silent about her, and did not overrule her, then all her vows will stand, and every obligation which she pledged for herself will stand.'
EXEC add_BibleVerse @BibleId, 104030012, N'But if her husband clearly nullifies them when he hears them, then whatever she says by way of vows or obligations will not stand. Her husband has made them void, and the Lord will release her from them.'
EXEC add_BibleVerse @BibleId, 104030013, N'“Any vow or sworn obligation that would bring affliction to her, her husband can confirm or nullify.'
EXEC add_BibleVerse @BibleId, 104030014, N'But if her husband remains completely silent about her from day to day, he thus confirms all her vows or all her obligations which she is under; he confirms them because he remained silent about when he heard them.'
EXEC add_BibleVerse @BibleId, 104030015, N'But if he should nullify them after he has heard them, then he will bear her iniquity.”'
EXEC add_BibleVerse @BibleId, 104030016, N'These are the statutes that the Lord commanded Moses, relating to a man and his wife, and a father and his young daughter who is still living in her father’s house.'
EXEC add_BibleVerse @BibleId, 104031001, N'The Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104031002, N'“Exact vengeance for the Israelites on the Midianites – after that you will be gathered to your people.”'
EXEC add_BibleVerse @BibleId, 104031003, N'So Moses spoke to the people: “Arm men from among you for the war, to attack the Midianites and to execute the Lord’s vengeance on Midian.'
EXEC add_BibleVerse @BibleId, 104031004, N'You must send to the battle a thousand men from every tribe throughout all the tribes of Israel.”'
EXEC add_BibleVerse @BibleId, 104031005, N'So a thousand from every tribe, twelve thousand armed for battle in all, were provided out of the thousands of Israel.'
EXEC add_BibleVerse @BibleId, 104031006, N'So Moses sent them to the war, one thousand from every tribe, with Phinehas son of Eleazar the priest, who was in charge of the holy articles and the signal trumpets.'
EXEC add_BibleVerse @BibleId, 104031007, N'They fought against the Midianites, as the Lord commanded Moses, and they killed every male.'
EXEC add_BibleVerse @BibleId, 104031008, N'They killed the kings of Midian in addition to those slain – Evi, Rekem, Zur, Hur, and Reba – five Midianite kings. They also killed Balaam son of Beor with the sword.'
EXEC add_BibleVerse @BibleId, 104031009, N'The Israelites took the women of Midian captives along with their little ones, and took all their herds, all their flocks, and all their goods as plunder.'
EXEC add_BibleVerse @BibleId, 104031010, N'They burned all their towns where they lived and all their encampments.'
EXEC add_BibleVerse @BibleId, 104031011, N'They took all the plunder and all the spoils, both people and animals.'
EXEC add_BibleVerse @BibleId, 104031012, N'They brought the captives and the spoils and the plunder to Moses, to Eleazar the priest, and to the Israelite community, to the camp on the plains of Moab, along the Jordan River across from Jericho.'
EXEC add_BibleVerse @BibleId, 104031013, N'Moses, Eleazar the priest, and all the leaders of the community went out to meet them outside the camp.'
EXEC add_BibleVerse @BibleId, 104031014, N'But Moses was furious with the officers of the army, the commanders over thousands and commanders over hundreds, who had come from service in the war.'
EXEC add_BibleVerse @BibleId, 104031015, N'Moses said to them, “Have you allowed all the women to live?'
EXEC add_BibleVerse @BibleId, 104031016, N'Look, these people through the counsel of Balaam caused the Israelites to act treacherously against the Lord in the matter of Peor – which resulted in the plague among the community of the Lord!'
EXEC add_BibleVerse @BibleId, 104031017, N'Now therefore kill every boy, and kill every woman who has had sexual intercourse with a man.'
EXEC add_BibleVerse @BibleId, 104031018, N'But all the young women who have not had sexual intercourse with a man will be yours.'
EXEC add_BibleVerse @BibleId, 104031019, N'“Any of you who has killed anyone or touched any of the dead, remain outside the camp for seven days; purify yourselves and your captives on the third day, and on the seventh day.'
EXEC add_BibleVerse @BibleId, 104031020, N'You must purify each garment and everything that is made of skin, everything made of goat’s hair, and everything made of wood.”'
EXEC add_BibleVerse @BibleId, 104031021, N'Then Eleazar the priest said to the men of war who had gone into the battle, “This is the ordinance of the law that the Lord commanded Moses:'
EXEC add_BibleVerse @BibleId, 104031022, N'‘Only the gold, the silver, the bronze, the iron, the tin, and the lead,'
EXEC add_BibleVerse @BibleId, 104031023, N'everything that may stand the fire, you are to pass through the fire, and it will be ceremonially clean, but it must still be purified with the water of purification. Anything that cannot withstand the fire you must pass through the water.'
EXEC add_BibleVerse @BibleId, 104031024, N'You must wash your clothes on the seventh day, and you will be ceremonially clean, and afterward you may enter the camp.’”'
EXEC add_BibleVerse @BibleId, 104031025, N'Then the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104031026, N'“You and Eleazar the priest, and all the family leaders of the community, take the sum of the plunder that was captured, both people and animals.'
EXEC add_BibleVerse @BibleId, 104031027, N'Divide the plunder into two parts, one for those who took part in the war – who went out to battle – and the other for all the community.'
EXEC add_BibleVerse @BibleId, 104031028, N'“You must exact a tribute for the Lord from the fighting men who went out to battle: one life out of five hundred, from the people, the cattle, and from the donkeys and the sheep.'
EXEC add_BibleVerse @BibleId, 104031029, N'You are to take it from their half-share and give it to Eleazar the priest for a raised offering to the Lord.'
EXEC add_BibleVerse @BibleId, 104031030, N'From the Israelites’ half-share you are to take one portion out of fifty of the people, the cattle, the donkeys, and the sheep – from every kind of animal – and you are to give them to the Levites, who are responsible for the care of the Lord’s tabernacle.”'
EXEC add_BibleVerse @BibleId, 104031031, N'So Moses and Eleazar the priest did as the Lord commanded Moses.'
EXEC add_BibleVerse @BibleId, 104031032, N'The spoil that remained of the plunder which the fighting men had gathered was 675,000 sheep,'
EXEC add_BibleVerse @BibleId, 104031033, N'72,000 cattle,'
EXEC add_BibleVerse @BibleId, 104031034, N'61,000 donkeys,'
EXEC add_BibleVerse @BibleId, 104031035, N'and 32,000 young women who had never had sexual intercourse with a man.'
EXEC add_BibleVerse @BibleId, 104031036, N'The half-portion of those who went to war numbered 337,500 sheep;'
EXEC add_BibleVerse @BibleId, 104031037, N'the Lord’s tribute from the sheep was 675.'
EXEC add_BibleVerse @BibleId, 104031038, N'The cattle numbered 36,000; the Lord’s tribute was 72.'
EXEC add_BibleVerse @BibleId, 104031039, N'The donkeys were 30,500, of which the Lord’s tribute was 61.'
EXEC add_BibleVerse @BibleId, 104031040, N'The people were 16,000, of which the Lord’s tribute was 32 people.'
EXEC add_BibleVerse @BibleId, 104031041, N'So Moses gave the tribute, which was the Lord’s raised offering, to Eleazar the priest, as the Lord commanded Moses.'
EXEC add_BibleVerse @BibleId, 104031042, N'From the Israelites’ half-share that Moses had separated from the fighting men,'
EXEC add_BibleVerse @BibleId, 104031043, N'there were 337,500 sheep from the portion belonging to the community,'
EXEC add_BibleVerse @BibleId, 104031044, N'36,000 cattle,'
EXEC add_BibleVerse @BibleId, 104031045, N'30,500 donkeys,'
EXEC add_BibleVerse @BibleId, 104031046, N'and 16,000 people.'
EXEC add_BibleVerse @BibleId, 104031047, N'From the Israelites’ share Moses took one of every fifty people and animals and gave them to the Levites who were responsible for the care of the Lord’s tabernacle, just as the Lord commanded Moses.'
EXEC add_BibleVerse @BibleId, 104031048, N'Then the officers who were over the thousands of the army, the commanders over thousands and the commanders over hundreds, approached Moses'
EXEC add_BibleVerse @BibleId, 104031049, N'and said to him, “Your servants have taken a count of the men who were in the battle, who were under our authority, and not one is missing.'
EXEC add_BibleVerse @BibleId, 104031050, N'So we have brought as an offering for the Lord what each man found: gold ornaments, armlets, bracelets, signet rings, earrings, and necklaces, to make atonement for ourselves before the Lord.”'
EXEC add_BibleVerse @BibleId, 104031051, N'Moses and Eleazar the priest took the gold from them, all of it in the form of ornaments.'
EXEC add_BibleVerse @BibleId, 104031052, N'All the gold of the offering they offered up to the Lord from the commanders of thousands and the commanders of hundreds weighed 16,750 shekels.'
EXEC add_BibleVerse @BibleId, 104031053, N'Each soldier had taken plunder for himself.'
EXEC add_BibleVerse @BibleId, 104031054, N'So Moses and Eleazar the priest received the gold from the commanders of thousands and commanders of hundreds and brought it into the tent of meeting as a memorial for the Israelites before the Lord.'
EXEC add_BibleVerse @BibleId, 104032001, N'Now the Reubenites and the Gadites possessed a very large number of cattle. When they saw that the lands of Jazer and Gilead were ideal for cattle,'
EXEC add_BibleVerse @BibleId, 104032002, N'the Gadites and the Reubenites came and addressed Moses, Eleazar the priest, and the leaders of the community. They said,'
EXEC add_BibleVerse @BibleId, 104032003, N'“Ataroth, Dibon, Jazer, Nimrah, Heshbon, Elealeh, Sebam, Nebo, and Beon,'
EXEC add_BibleVerse @BibleId, 104032004, N'the land that the Lord subdued before the community of Israel, is ideal for cattle, and your servants have cattle.”'
EXEC add_BibleVerse @BibleId, 104032005, N'So they said, “If we have found favor in your sight, let this land be given to your servants for our inheritance. Do not have us cross the Jordan River.”'
EXEC add_BibleVerse @BibleId, 104032006, N'Moses said to the Gadites and the Reubenites, “Must your brothers go to war while you remain here?'
EXEC add_BibleVerse @BibleId, 104032007, N'Why do you frustrate the intent of the Israelites to cross over into the land which the Lord has given them?'
EXEC add_BibleVerse @BibleId, 104032008, N'Your fathers did the same thing when I sent them from Kadesh Barnea to see the land.'
EXEC add_BibleVerse @BibleId, 104032009, N'When they went up to the Eshcol Valley and saw the land, they frustrated the intent of the Israelites so that they did not enter the land that the Lord had given them.'
EXEC add_BibleVerse @BibleId, 104032010, N'So the anger of the Lord was kindled that day, and he swore,'
EXEC add_BibleVerse @BibleId, 104032011, N'‘Because they have not followed me wholeheartedly, not one of the men twenty years old and upward who came from Egypt will see the land that I swore to give to Abraham, Isaac, and Jacob,'
EXEC add_BibleVerse @BibleId, 104032012, N'except Caleb son of Jephunneh the Kenizzite, and Joshua son of Nun, for they followed the Lord wholeheartedly.’'
EXEC add_BibleVerse @BibleId, 104032013, N'So the Lord’s anger was kindled against the Israelites, and he made them wander in the wilderness for forty years, until all that generation that had done wickedly before the Lord was finished.'
EXEC add_BibleVerse @BibleId, 104032014, N'Now look, you are standing in your fathers’ place, a brood of sinners, to increase still further the fierce wrath of the Lord against the Israelites.'
EXEC add_BibleVerse @BibleId, 104032015, N'For if you turn away from following him, he will once again abandon them in the wilderness, and you will be the reason for their destruction.”'
EXEC add_BibleVerse @BibleId, 104032016, N'Then they came very close to him and said, “We will build sheep folds here for our flocks and cities for our families,'
EXEC add_BibleVerse @BibleId, 104032017, N'but we will maintain ourselves in armed readiness and go before the Israelites until whenever we have brought them to their place. Our descendants will be living in fortified towns as a protection against the inhabitants of the land.'
EXEC add_BibleVerse @BibleId, 104032018, N'We will not return to our homes until every Israelite has his inheritance.'
EXEC add_BibleVerse @BibleId, 104032019, N'For we will not accept any inheritance on the other side of the Jordan River and beyond, because our inheritance has come to us on this eastern side of the Jordan.”'
EXEC add_BibleVerse @BibleId, 104032020, N'Then Moses replied, “If you will do this thing, and if you will arm yourselves for battle before the Lord,'
EXEC add_BibleVerse @BibleId, 104032021, N'and if all your armed men cross the Jordan before the Lord until he drives out his enemies from his presence'
EXEC add_BibleVerse @BibleId, 104032022, N'and the land is subdued before the Lord, then afterward you may return and be free of your obligation to the Lord and to Israel. This land will then be your possession in the Lord’s sight.'
EXEC add_BibleVerse @BibleId, 104032023, N'“But if you do not do this, then look, you will have sinned against the Lord. And know that your sin will find you out.'
EXEC add_BibleVerse @BibleId, 104032024, N'So build cities for your descendants and pens for your sheep, but do what you have said you would do.”'
EXEC add_BibleVerse @BibleId, 104032025, N'So the Gadites and the Reubenites replied to Moses, “Your servants will do as my lord commands.'
EXEC add_BibleVerse @BibleId, 104032026, N'Our children, our wives, our flocks, and all our livestock will be there in the cities of Gilead,'
EXEC add_BibleVerse @BibleId, 104032027, N'but your servants will cross over, every man armed for war, to do battle in the Lord’s presence, just as my lord says.”'
EXEC add_BibleVerse @BibleId, 104032028, N'So Moses gave orders about them to Eleazar the priest, to Joshua son of Nun, and to the heads of the families of the Israelite tribes.'
EXEC add_BibleVerse @BibleId, 104032029, N'Moses said to them: “If the Gadites and the Reubenites cross the Jordan with you, each one equipped for battle in the Lord’s presence, and you conquer the land, then you must allot them the territory of Gilead as their possession.'
EXEC add_BibleVerse @BibleId, 104032030, N'But if they do not cross over with you armed, they must receive possessions among you in Canaan.”'
EXEC add_BibleVerse @BibleId, 104032031, N'Then the Gadites and the Reubenites answered, “Your servants will do what the Lord has spoken.'
EXEC add_BibleVerse @BibleId, 104032032, N'We will cross armed in the Lord’s presence into the land of Canaan, and then the possession of our inheritance that we inherit will be ours on this side of the Jordan River.”'
EXEC add_BibleVerse @BibleId, 104032033, N'So Moses gave to the Gadites, the Reubenites, and to half the tribe of Manasseh son of Joseph the realm of King Sihon of the Amorites, and the realm of King Og of Bashan, the entire land with its cities and the territory surrounding them.'
EXEC add_BibleVerse @BibleId, 104032034, N'The Gadites rebuilt Dibon, Ataroth, Aroer,'
EXEC add_BibleVerse @BibleId, 104032035, N'Atroth Shophan, Jazer, Jogbehah,'
EXEC add_BibleVerse @BibleId, 104032036, N'Beth Nimrah, and Beth Haran as fortified cities, and constructed pens for their flocks.'
EXEC add_BibleVerse @BibleId, 104032037, N'The Reubenites rebuilt Heshbon, Elealeh, Kiriathaim,'
EXEC add_BibleVerse @BibleId, 104032038, N'Nebo, Baal Meon (with a change of name), and Sibmah. They renamed the cities they built.'
EXEC add_BibleVerse @BibleId, 104032039, N'The descendants of Machir son of Manasseh went to Gilead, took it, and dispossessed the Amorites who were in it.'
EXEC add_BibleVerse @BibleId, 104032040, N'So Moses gave Gilead to Machir, son of Manasseh, and he lived there.'
EXEC add_BibleVerse @BibleId, 104032041, N'Now Jair son of Manasseh went and captured their small towns and named them Havvoth Jair.'
EXEC add_BibleVerse @BibleId, 104032042, N'Then Nobah went and captured Kenath and its villages and called it Nobah after his own name.'
EXEC add_BibleVerse @BibleId, 104033001, N'These are the journeys of the Israelites, who went out of the land of Egypt by their divisions under the authority of Moses and Aaron.'
EXEC add_BibleVerse @BibleId, 104033002, N'Moses recorded their departures according to their journeys, by the commandment of the Lord; now these are their journeys according to their departures.'
EXEC add_BibleVerse @BibleId, 104033003, N'They departed from Rameses in the first month, on the fifteenth day of the first month; on the day after the Passover the Israelites went out defiantly in plain sight of all the Egyptians.'
EXEC add_BibleVerse @BibleId, 104033004, N'Now the Egyptians were burying all their firstborn, whom the Lord had killed among them; the Lord also executed judgments on their gods.'
EXEC add_BibleVerse @BibleId, 104033005, N'The Israelites traveled from Rameses and camped in Succoth.'
EXEC add_BibleVerse @BibleId, 104033006, N'They traveled from Succoth, and camped in Etham, which is on the edge of the wilderness.'
EXEC add_BibleVerse @BibleId, 104033007, N'They traveled from Etham, and turned again to Pi-hahiroth, which is before Baal-Zephon; and they camped before Migdal.'
EXEC add_BibleVerse @BibleId, 104033008, N'They traveled from Pi-hahiroth, and passed through the middle of the sea into the wilderness, and went three days’ journey in the wilderness of Etham, and camped in Marah.'
EXEC add_BibleVerse @BibleId, 104033009, N'They traveled from Marah and came to Elim; in Elim there are twelve fountains of water and seventy palm trees, so they camped there.'
EXEC add_BibleVerse @BibleId, 104033010, N'They traveled from Elim, and camped by the Red Sea.'
EXEC add_BibleVerse @BibleId, 104033011, N'They traveled from the Red Sea and camped in the wilderness of Zin.'
EXEC add_BibleVerse @BibleId, 104033012, N'They traveled from the wilderness of Zin and camped in Dophkah.'
EXEC add_BibleVerse @BibleId, 104033013, N'And they traveled from Dophkah, and camped in Alush.'
EXEC add_BibleVerse @BibleId, 104033014, N'They traveled from Alush and camped at Rephidim, where there was no water for the people to drink.'
EXEC add_BibleVerse @BibleId, 104033015, N'They traveled from Rephidim and camped in the wilderness of Sinai.'
EXEC add_BibleVerse @BibleId, 104033016, N'They traveled from the desert of Sinai and camped at Kibroth Hattaavah.'
EXEC add_BibleVerse @BibleId, 104033017, N'They traveled from Kibroth Hattaavah and camped at Hazeroth.'
EXEC add_BibleVerse @BibleId, 104033018, N'They traveled from Hazeroth and camped in Rithmah.'
EXEC add_BibleVerse @BibleId, 104033019, N'They traveled from Rithmah and camped at Rimmon-perez.'
EXEC add_BibleVerse @BibleId, 104033020, N'They traveled from Rimmon-perez and camped in Libnah.'
EXEC add_BibleVerse @BibleId, 104033021, N'They traveled from Libnah and camped at Rissah.'
EXEC add_BibleVerse @BibleId, 104033022, N'They traveled from Rissah and camped in Kehelathah.'
EXEC add_BibleVerse @BibleId, 104033023, N'They traveled from Kehelathah and camped at Mount Shepher.'
EXEC add_BibleVerse @BibleId, 104033024, N'They traveled from Mount Shepher and camped in Haradah.'
EXEC add_BibleVerse @BibleId, 104033025, N'They traveled from Haradah and camped in Makheloth.'
EXEC add_BibleVerse @BibleId, 104033026, N'They traveled from Makheloth and camped at Tahath.'
EXEC add_BibleVerse @BibleId, 104033027, N'They traveled from Tahath and camped at Terah.'
EXEC add_BibleVerse @BibleId, 104033028, N'They traveled from Terah and camped in Mithcah.'
EXEC add_BibleVerse @BibleId, 104033029, N'They traveled from Mithcah and camped in Hashmonah.'
EXEC add_BibleVerse @BibleId, 104033030, N'They traveled from Hashmonah and camped in Moseroth.'
EXEC add_BibleVerse @BibleId, 104033031, N'They traveled from Moseroth and camped in Bene-jaakan.'
EXEC add_BibleVerse @BibleId, 104033032, N'They traveled from Bene-jaakan and camped at Hor-haggidgad.'
EXEC add_BibleVerse @BibleId, 104033033, N'They traveled from Hor-haggidgad and camped in Jotbathah.'
EXEC add_BibleVerse @BibleId, 104033034, N'They traveled from Jotbathah and camped in Abronah.'
EXEC add_BibleVerse @BibleId, 104033035, N'They traveled from Abronah and camped at Ezion-geber.'
EXEC add_BibleVerse @BibleId, 104033036, N'They traveled from Ezion-geber and camped in the wilderness of Zin, which is Kadesh.'
EXEC add_BibleVerse @BibleId, 104033037, N'They traveled from Kadesh and camped in Mount Hor at the edge of the land of Edom.'
EXEC add_BibleVerse @BibleId, 104033038, N'Aaron the priest ascended Mount Hor at the command of the Lord, and he died there in the fortieth year after the Israelites had come out of the land of Egypt on the first day of the fifth month.'
EXEC add_BibleVerse @BibleId, 104033039, N'Now Aaron was 123 years old when he died in Mount Hor.'
EXEC add_BibleVerse @BibleId, 104033040, N'The king of Arad, the Canaanite king who lived in the south of the land of Canaan, heard about the approach of the Israelites.'
EXEC add_BibleVerse @BibleId, 104033041, N'They traveled from Mount Hor and camped in Zalmonah.'
EXEC add_BibleVerse @BibleId, 104033042, N'They traveled from Zalmonah and camped in Punon.'
EXEC add_BibleVerse @BibleId, 104033043, N'They traveled from Punon and camped in Oboth.'
EXEC add_BibleVerse @BibleId, 104033044, N'They traveled from Oboth and camped in Iye-abarim, on the border of Moab.'
EXEC add_BibleVerse @BibleId, 104033045, N'They traveled from Iim and camped in Dibon-gad.'
EXEC add_BibleVerse @BibleId, 104033046, N'They traveled from Dibon-gad and camped in Almon-diblathaim.'
EXEC add_BibleVerse @BibleId, 104033047, N'They traveled from Almon-diblathaim and camped in the mountains of Abarim before Nebo.'
EXEC add_BibleVerse @BibleId, 104033048, N'They traveled from the mountains of Abarim and camped in the plains of Moab by the Jordan River across from Jericho.'
EXEC add_BibleVerse @BibleId, 104033049, N'They camped by the Jordan, from Beth-jeshimoth as far as Abel-shittim in the plains of Moab.'
EXEC add_BibleVerse @BibleId, 104033050, N'The Lord spoke to Moses in the plains of Moab by the Jordan, across from Jericho. He said:'
EXEC add_BibleVerse @BibleId, 104033051, N'“Speak to the Israelites and tell them, ‘When you have crossed the Jordan into the land of Canaan,'
EXEC add_BibleVerse @BibleId, 104033052, N'you must drive out all the inhabitants of the land before you. Destroy all their carved images, all their molten images, and demolish their high places.'
EXEC add_BibleVerse @BibleId, 104033053, N'You must dispossess the inhabitants of the land and live in it, for I have given you the land to possess it.'
EXEC add_BibleVerse @BibleId, 104033054, N'You must divide the land by lot for an inheritance among your families. To a larger group you must give a larger inheritance, and to a smaller group you must give a smaller inheritance. Everyone’s inheritance must be in the place where his lot falls. You must inherit according to your ancestral tribes.'
EXEC add_BibleVerse @BibleId, 104033055, N'But if you do not drive out the inhabitants of the land before you, then those whom you allow to remain will be irritants in your eyes and thorns in your side, and will cause you trouble in the land where you will be living.'
EXEC add_BibleVerse @BibleId, 104033056, N'And what I intended to do to them I will do to you.”'
EXEC add_BibleVerse @BibleId, 104034001, N'Then the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104034002, N'“Give these instructions to the Israelites, and tell them: ‘When you enter Canaan, the land that has been assigned to you as an inheritance, the land of Canaan with its borders,'
EXEC add_BibleVerse @BibleId, 104034003, N'your southern border will extend from the wilderness of Zin along the Edomite border, and your southern border will run eastward to the extremity of the Salt Sea,'
EXEC add_BibleVerse @BibleId, 104034004, N'and then the border will turn from the south to the Scorpion Ascent, continue to Zin, and then its direction will be from the south to Kadesh Barnea. Then it will go to Hazar Addar and pass over to Azmon.'
EXEC add_BibleVerse @BibleId, 104034005, N'There the border will turn from Azmon to the Brook of Egypt, and then its direction is to the sea.'
EXEC add_BibleVerse @BibleId, 104034006, N'“‘And for a western border you will have the Great Sea. This will be your western border.'
EXEC add_BibleVerse @BibleId, 104034007, N'“‘And this will be your northern border: From the Great Sea you will draw a line to Mount Hor;'
EXEC add_BibleVerse @BibleId, 104034008, N'from Mount Hor you will draw a line to Lebo Hamath, and the direction of the border will be to Zedad.'
EXEC add_BibleVerse @BibleId, 104034009, N'The border will continue to Ziphron, and its direction will be to Hazar Enan. This will be your northern border.'
EXEC add_BibleVerse @BibleId, 104034010, N'“‘For your eastern border you will draw a line from Hazar Enan to Shepham.'
EXEC add_BibleVerse @BibleId, 104034011, N'The border will run down from Shepham to Riblah, on the east side of Ain, and the border will descend and reach the eastern side of the Sea of Chinnereth.'
EXEC add_BibleVerse @BibleId, 104034012, N'Then the border will continue down the Jordan River and its direction will be to the Salt Sea. This will be your land by its borders that surround it.’”'
EXEC add_BibleVerse @BibleId, 104034013, N'Then Moses commanded the Israelites: “This is the land which you will inherit by lot, which the Lord has commanded to be given to the nine and a half tribes,'
EXEC add_BibleVerse @BibleId, 104034014, N'because the tribe of the Reubenites by their families, the tribe of the Gadites by their families, and half of the tribe of Manasseh have received their inheritance.'
EXEC add_BibleVerse @BibleId, 104034015, N'The two and a half tribes have received their inheritance on this side of the Jordan, east of Jericho, toward the sunrise.”'
EXEC add_BibleVerse @BibleId, 104034016, N'The Lord said to Moses:'
EXEC add_BibleVerse @BibleId, 104034017, N'“These are the names of the men who are to allocate the land to you as an inheritance: Eleazar the priest and Joshua son of Nun.'
EXEC add_BibleVerse @BibleId, 104034018, N'You must take one leader from every tribe to assist in allocating the land as an inheritance.'
EXEC add_BibleVerse @BibleId, 104034019, N'These are the names of the men: from the tribe of Judah, Caleb son of Jephunneh;'
EXEC add_BibleVerse @BibleId, 104034020, N'from the tribe of the Simeonites, Shemuel son of Ammihud;'
EXEC add_BibleVerse @BibleId, 104034021, N'from the tribe of Benjamin, Elidad son of Kislon;'
EXEC add_BibleVerse @BibleId, 104034022, N'and from the tribe of the Danites, a leader, Bukki son of Jogli.'
EXEC add_BibleVerse @BibleId, 104034023, N'From the Josephites, Hanniel son of Ephod, a leader from the tribe of Manasseh;'
EXEC add_BibleVerse @BibleId, 104034024, N'from the tribe of the Ephraimites, a leader, Kemuel son of Shiphtan;'
EXEC add_BibleVerse @BibleId, 104034025, N'from the tribe of the Zebulunites, a leader, Elizaphan son of Parnach;'
EXEC add_BibleVerse @BibleId, 104034026, N'from the tribe of the Issacharites, a leader, Paltiel son of Azzan;'
EXEC add_BibleVerse @BibleId, 104034027, N'from the tribe of the Asherites, a leader, Ahihud son of Shelomi;'
EXEC add_BibleVerse @BibleId, 104034028, N'and from the tribe of the Naphtalites, a leader, Pedahel son of Ammihud.”'
EXEC add_BibleVerse @BibleId, 104034029, N'These are the ones whom the Lord commanded to divide up the inheritance among the Israelites in the land of Canaan.'
EXEC add_BibleVerse @BibleId, 104035001, N'Then the Lord spoke to Moses in the Moabite plains by the Jordan near Jericho. He said:'
EXEC add_BibleVerse @BibleId, 104035002, N'“Instruct the Israelites to give the Levites towns to live in from the inheritance the Israelites will possess. You must also give the Levites grazing land around the towns.'
EXEC add_BibleVerse @BibleId, 104035003, N'Thus they will have towns in which to live, and their grazing lands will be for their cattle, for their possessions, and for all their animals.'
EXEC add_BibleVerse @BibleId, 104035004, N'The grazing lands around the towns that you will give to the Levites must extend to a distance of 500 yards from the town wall.'
EXEC add_BibleVerse @BibleId, 104035005, N'“You must measure from outside the wall of the town on the east 1,000 yards, and on the south side 1,000 yards, and on the west side 1,000 yards, and on the north side 1,000 yards, with the town in the middle. This territory must belong to them as grazing land for the towns.'
EXEC add_BibleVerse @BibleId, 104035006, N'Now from these towns that you will give to the Levites you must select six towns of refuge to which a person who has killed someone may flee. And you must give them forty-two other towns.'
EXEC add_BibleVerse @BibleId, 104035007, N'“So the total of the towns you will give the Levites is forty-eight. You must give these together with their grazing lands.'
EXEC add_BibleVerse @BibleId, 104035008, N'The towns you will give must be from the possession of the Israelites. From the larger tribes you must give more; and from the smaller tribes fewer. Each must contribute some of its own towns to the Levites in proportion to the inheritance allocated to each.'
EXEC add_BibleVerse @BibleId, 104035009, N'Then the Lord spoke to Moses:'
EXEC add_BibleVerse @BibleId, 104035010, N'“Speak to the Israelites and tell them, ‘When you cross over the Jordan River into the land of Canaan,'
EXEC add_BibleVerse @BibleId, 104035011, N'you must then designate some towns as towns of refuge for you, to which a person who has killed someone unintentionally may flee.'
EXEC add_BibleVerse @BibleId, 104035012, N'And they must stand as your towns of refuge from the avenger in order that the killer may not die until he has stood trial before the community.'
EXEC add_BibleVerse @BibleId, 104035013, N'These towns that you must give shall be your six towns for refuge.'
EXEC add_BibleVerse @BibleId, 104035014, N'“You must give three towns on this side of the Jordan, and you must give three towns in the land of Canaan; they must be towns of refuge.'
EXEC add_BibleVerse @BibleId, 104035015, N'These six towns will be places of refuge for the Israelites, and for the foreigner, and for the settler among them, so that anyone who kills any person accidentally may flee there.'
EXEC add_BibleVerse @BibleId, 104035016, N'“But if he hits someone with an iron tool so that he dies, he is a murderer. The murderer must surely be put to death.'
EXEC add_BibleVerse @BibleId, 104035017, N'If he strikes him by throwing a stone large enough that he could die, and he dies, he is a murderer. The murderer must surely be put to death.'
EXEC add_BibleVerse @BibleId, 104035018, N'Or if he strikes him with a wooden hand weapon so that he could die, and he dies, he is a murderer. The murderer must surely be put to death.'
EXEC add_BibleVerse @BibleId, 104035019, N'The avenger of blood himself must kill the murderer; when he meets him, he must kill him.'
EXEC add_BibleVerse @BibleId, 104035020, N'“But if he strikes him out of hatred or throws something at him intentionally so that he dies,'
EXEC add_BibleVerse @BibleId, 104035021, N'or with enmity he strikes him with his hand and he dies, the one who struck him must surely be put to death, for he is a murderer. The avenger of blood must kill the murderer when he meets him.'
EXEC add_BibleVerse @BibleId, 104035022, N'“But if he strikes him suddenly, without enmity, or throws anything at him unintentionally,'
EXEC add_BibleVerse @BibleId, 104035023, N'or with any stone large enough that a man could die, without seeing him, and throws it at him, and he dies, even though he was not his enemy nor sought his harm,'
EXEC add_BibleVerse @BibleId, 104035024, N'then the community must judge between the slayer and the avenger of blood according to these decisions.'
EXEC add_BibleVerse @BibleId, 104035025, N'The community must deliver the slayer out of the hand of the avenger of blood, and the community must restore him to the town of refuge to which he fled, and he must live there until the death of the high priest, who was anointed with the consecrated oil.'
EXEC add_BibleVerse @BibleId, 104035026, N'But if the slayer at any time goes outside the boundary of the town to which he had fled,'
EXEC add_BibleVerse @BibleId, 104035027, N'and the avenger of blood finds him outside the borders of the town of refuge, and the avenger of blood kills the slayer, he will not be guilty of blood,'
EXEC add_BibleVerse @BibleId, 104035028, N'because the slayer should have stayed in his town of refuge until the death of the high priest. But after the death of the high priest, the slayer may return to the land of his possessions.'
EXEC add_BibleVerse @BibleId, 104035029, N'So these things must be a statutory ordinance for you throughout your generations, in all the places where you live.'
EXEC add_BibleVerse @BibleId, 104035030, N'“Whoever kills any person, the murderer must be put to death by the testimony of witnesses; but one witness cannot testify against any person to cause him to be put to death.'
EXEC add_BibleVerse @BibleId, 104035031, N'Moreover, you must not accept a ransom for the life of a murderer who is guilty of death; he must surely be put to death.'
EXEC add_BibleVerse @BibleId, 104035032, N'And you must not accept a ransom for anyone who has fled to a town of refuge, to allow him to return home and live on his own land before the death of the high priest.'
EXEC add_BibleVerse @BibleId, 104035033, N'“You must not pollute the land where you live, for blood defiles the land, and the land cannot be cleansed of the blood that is shed there, except by the blood of the person who shed it.'
EXEC add_BibleVerse @BibleId, 104035034, N'Therefore do not defile the land that you will inhabit, in which I live, for I the Lord live among the Israelites.”'
EXEC add_BibleVerse @BibleId, 104036001, N'Then the heads of the family groups of the Gileadites, the descendant of Machir, the descendant of Manasseh, who were from the Josephite families, approached and spoke before Moses and the leaders who were the heads of the Israelite families.'
EXEC add_BibleVerse @BibleId, 104036002, N'They said, “The Lord commanded my lord to give the land as an inheritance by lot to the Israelites; and my lord was commanded by the Lord to give the inheritance of our brother Zelophehad to his daughters.'
EXEC add_BibleVerse @BibleId, 104036003, N'Now if they should be married to one of the men from another Israelite tribe, their inheritance would be taken from the inheritance of our fathers and added to the inheritance of the tribe into which they marry. As a result, it will be taken from the lot of our inheritance.'
EXEC add_BibleVerse @BibleId, 104036004, N'And when the Jubilee of the Israelites is to take place, their inheritance will be added to the inheritance of the tribe into which they marry. So their inheritance will be taken away from the inheritance of our ancestral tribe.”'
EXEC add_BibleVerse @BibleId, 104036005, N'Then Moses gave a ruling to the Israelites by the word of the Lord: “What the tribe of the Josephites is saying is right.'
EXEC add_BibleVerse @BibleId, 104036006, N'This is what the Lord has commanded for Zelophehad’s daughters: ‘Let them marry whomever they think best, only they must marry within the family of their father’s tribe.'
EXEC add_BibleVerse @BibleId, 104036007, N'In this way the inheritance of the Israelites will not be transferred from tribe to tribe. But every one of the Israelites must retain the ancestral heritage.'
EXEC add_BibleVerse @BibleId, 104036008, N'And every daughter who possesses an inheritance from any of the tribes of the Israelites must become the wife of a man from any family in her father’s tribe, so that every Israelite may retain the inheritance of his fathers.'
EXEC add_BibleVerse @BibleId, 104036009, N'No inheritance may pass from tribe to tribe. But every one of the tribes of the Israelites must retain its inheritance.”'
EXEC add_BibleVerse @BibleId, 104036010, N'As the Lord had commanded Moses, so the daughters of Zelophehad did.'
EXEC add_BibleVerse @BibleId, 104036011, N'For the daughters of Zelophehad – Mahlah, Tirzah, Hoglah, Milcah, and Noah – were married to the sons of their uncles.'
EXEC add_BibleVerse @BibleId, 104036012, N'They were married into the families of the Manassehites, the descendants of Joseph, and their inheritance remained in the tribe of their father’s family.'
EXEC add_BibleVerse @BibleId, 104036013, N'These are the commandments and the decisions that the Lord commanded the Israelites through the authority of Moses, on the plains of Moab by the Jordan River opposite Jericho.'
EXEC add_BibleVerse @BibleId, 105001001, N'This is what Moses said to the assembly of Israel in the Transjordanian wastelands, the arid country opposite Suph, between Paran and Tophel, Laban, Hazeroth, and Di Zahab'
EXEC add_BibleVerse @BibleId, 105001002, N'Now it is ordinarily an eleven-day journey from Horeb to Kadesh Barnea by way of Mount Seir.'
EXEC add_BibleVerse @BibleId, 105001003, N'However, it was not until the first day of the eleventh month of the fortieth year that Moses addressed the Israelites just as the Lord had instructed him to do.'
EXEC add_BibleVerse @BibleId, 105001004, N'This took place after the defeat of King Sihon of the Amorites, whose capital was in Heshbon, and King Og of Bashan, whose capital was in Ashtaroth, specifically in Edrei.'
EXEC add_BibleVerse @BibleId, 105001005, N'So it was in the Transjordan, in Moab, that Moses began to deliver these words:'
EXEC add_BibleVerse @BibleId, 105001006, N'The Lord our God spoke to us at Horeb and said, “You have stayed in the area of this mountain long enough.'
EXEC add_BibleVerse @BibleId, 105001007, N'Get up now, resume your journey, heading for the Amorite hill country, to all its areas including the arid country, the highlands, the Shephelah, the Negev, and the coastal plain – all of Canaan and Lebanon as far as the Great River, that is, the Euphrates.'
EXEC add_BibleVerse @BibleId, 105001008, N'Look! I have already given the land to you. Go, occupy the territory that I, the Lord, promised to give to your ancestors Abraham, Isaac, and Jacob, and to their descendants.”'
EXEC add_BibleVerse @BibleId, 105001009, N'I also said to you at that time, “I am no longer able to sustain you by myself.'
EXEC add_BibleVerse @BibleId, 105001010, N'The Lord your God has increased your population to the point that you are now as numerous as the very stars of the sky.'
EXEC add_BibleVerse @BibleId, 105001011, N'Indeed, may the Lord, the God of your ancestors, make you a thousand times more numerous than you are now, blessing you just as he said he would!'
EXEC add_BibleVerse @BibleId, 105001012, N'But how can I alone bear up under the burden of your hardship and strife?'
EXEC add_BibleVerse @BibleId, 105001013, N'Select wise and practical men, those known among your tribes, whom I may appoint as your leaders.”'
EXEC add_BibleVerse @BibleId, 105001014, N'You replied to me that what I had said to you was good.'
EXEC add_BibleVerse @BibleId, 105001015, N'So I chose as your tribal leaders wise and well-known men, placing them over you as administrators of groups of thousands, hundreds, fifties, and tens, and also as other tribal officials.'
EXEC add_BibleVerse @BibleId, 105001016, N'I furthermore admonished your judges at that time that they should pay attention to issues among your fellow citizens and judge fairly, whether between one citizen and another or a citizen and a resident foreigner.'
EXEC add_BibleVerse @BibleId, 105001017, N'They must not discriminate in judgment, but hear the lowly and the great alike. Nor should they be intimidated by human beings, for judgment belongs to God. If the matter being adjudicated is too difficult for them, they should bring it before me for a hearing.'
EXEC add_BibleVerse @BibleId, 105001018, N'So I instructed you at that time regarding everything you should do.'
EXEC add_BibleVerse @BibleId, 105001019, N'Then we left Horeb and passed through all that immense, forbidding wilderness that you saw on the way to the Amorite hill country as the Lord our God had commanded us to do, finally arriving at Kadesh Barnea.'
EXEC add_BibleVerse @BibleId, 105001020, N'Then I said to you, “You have come to the Amorite hill country which the Lord our God is about to give us.'
EXEC add_BibleVerse @BibleId, 105001021, N'Look, he has placed the land in front of you! Go up, take possession of it, just as the Lord, the God of your ancestors, said to do. Do not be afraid or discouraged!”'
EXEC add_BibleVerse @BibleId, 105001022, N'So all of you approached me and said, “Let’s send some men ahead of us to scout out the land and bring us back word as to how we should attack it and what the cities are like there.”'
EXEC add_BibleVerse @BibleId, 105001023, N'I thought this was a good idea, so I sent twelve men from among you, one from each tribe.'
EXEC add_BibleVerse @BibleId, 105001024, N'They left and went up to the hill country, coming to the Eshcol Valley, which they scouted out.'
EXEC add_BibleVerse @BibleId, 105001025, N'Then they took some of the produce of the land and carried it back down to us. They also brought a report to us, saying, “The land that the Lord our God is about to give us is good.”'
EXEC add_BibleVerse @BibleId, 105001026, N'You were not willing to go up, however, but instead rebelled against the Lord your God.'
EXEC add_BibleVerse @BibleId, 105001027, N'You complained among yourselves privately and said, “Because the Lord hates us he brought us from Egypt to deliver us over to the Amorites so they could destroy us!'
EXEC add_BibleVerse @BibleId, 105001028, N'What is going to happen to us? Our brothers have drained away our courage by describing people who are more numerous and taller than we are, and great cities whose defenses appear to be as high as heaven itself! Moreover, they said they saw Anakites there.”'
EXEC add_BibleVerse @BibleId, 105001029, N'So I responded to you, “Do not be terrified of them!'
EXEC add_BibleVerse @BibleId, 105001030, N'The Lord your God is about to go ahead of you; he will fight for you, just as you saw him do in Egypt'
EXEC add_BibleVerse @BibleId, 105001031, N'and in the desert, where you saw him carrying you along like a man carries his son. This he did everywhere you went until you came to this very place.”'
EXEC add_BibleVerse @BibleId, 105001032, N'However, through all this you did not have confidence in the Lord your God,'
EXEC add_BibleVerse @BibleId, 105001033, N'the one who was constantly going before you to find places for you to set up camp. He appeared by fire at night and cloud by day, to show you the way you ought to go.'
EXEC add_BibleVerse @BibleId, 105001034, N'When the Lord heard you, he became angry and made this vow:'
EXEC add_BibleVerse @BibleId, 105001035, N'“Not a single person of this evil generation will see the good land that I promised to give to your ancestors!'
EXEC add_BibleVerse @BibleId, 105001036, N'The exception is Caleb son of Jephunneh; he will see it and I will give him and his descendants the territory on which he has walked, because he has wholeheartedly followed me.”'
EXEC add_BibleVerse @BibleId, 105001037, N'As for me, the Lord was also angry with me on your account. He said, “You also will not be able to go there.'
EXEC add_BibleVerse @BibleId, 105001038, N'However, Joshua son of Nun, your assistant, will go. Encourage him, because he will enable Israel to inherit the land.'
EXEC add_BibleVerse @BibleId, 105001039, N'Also, your infants, who you thought would die on the way, and your children, who as yet do not know good from bad, will go there; I will give them the land and they will possess it.'
EXEC add_BibleVerse @BibleId, 105001040, N'But as for you, turn back and head for the desert by the way to the Red Sea.”'
EXEC add_BibleVerse @BibleId, 105001041, N'Then you responded to me and admitted, “We have sinned against the Lord. We will now go up and fight as the Lord our God has told us to do.” So you each put on your battle gear and prepared to go up to the hill country.'
EXEC add_BibleVerse @BibleId, 105001042, N'But the Lord told me: “Tell them this: ‘Do not go up and fight, because I will not be with you and you will be defeated by your enemies.’”'
EXEC add_BibleVerse @BibleId, 105001043, N'I spoke to you, but you did not listen. Instead you rebelled against the Lord and recklessly went up to the hill country.'
EXEC add_BibleVerse @BibleId, 105001044, N'The Amorite inhabitants of that area confronted you and chased you like a swarm of bees, striking you down from Seir as far as Hormah.'
EXEC add_BibleVerse @BibleId, 105001045, N'Then you came back and wept before the Lord, but he paid no attention to you whatsoever.'
EXEC add_BibleVerse @BibleId, 105001046, N'Therefore, you remained at Kadesh for a long time – indeed, for the full time.'
EXEC add_BibleVerse @BibleId, 105002001, N'Then we turned and set out toward the desert land on the way to the Red Sea just as the Lord told me to do, detouring around Mount Seir for a long time.'
EXEC add_BibleVerse @BibleId, 105002002, N'At this point the Lord said to me,'
EXEC add_BibleVerse @BibleId, 105002003, N'“You have circled around this mountain long enough; now turn north.'
EXEC add_BibleVerse @BibleId, 105002004, N'Instruct these people as follows: ‘You are about to cross the border of your relatives the descendants of Esau, who inhabit Seir. They will be afraid of you, so watch yourselves carefully.'
EXEC add_BibleVerse @BibleId, 105002005, N'Do not be hostile toward them, because I am not giving you any of their land, not even a footprint, for I have given Mount Seir as an inheritance for Esau.'
EXEC add_BibleVerse @BibleId, 105002006, N'You may purchase food to eat and water to drink from them.'
EXEC add_BibleVerse @BibleId, 105002007, N'All along the way I, the Lord your God, have blessed your every effort. I have been attentive to your travels through this great wasteland. These forty years I have been with you; you have lacked for nothing.’”'
EXEC add_BibleVerse @BibleId, 105002008, N'So we turned away from our relatives the descendants of Esau, the inhabitants of Seir, turning from the desert route, from Elat and Ezion Geber, and traveling the way of the Moab wastelands.'
EXEC add_BibleVerse @BibleId, 105002009, N'Then the Lord said to me, “Do not harass Moab and provoke them to war, for I will not give you any of their land as your territory. This is because I have given Ar to the descendants of Lot as their possession.'
EXEC add_BibleVerse @BibleId, 105002010, N'(The Emites used to live there, a people as powerful, numerous, and tall as the Anakites.'
EXEC add_BibleVerse @BibleId, 105002011, N'These people, as well as the Anakites, are also considered Rephaites; the Moabites call them Emites.'
EXEC add_BibleVerse @BibleId, 105002012, N'Previously the Horites lived in Seir but the descendants of Esau dispossessed and destroyed them and settled in their place, just as Israel did to the land it came to possess, the land the Lord gave them.)'
EXEC add_BibleVerse @BibleId, 105002013, N'Now, get up and cross the Wadi Zered.” So we did so.'
EXEC add_BibleVerse @BibleId, 105002014, N'Now the length of time it took for us to go from Kadesh Barnea to the crossing of Wadi Zered was thirty-eight years, time for all the military men of that generation to die, just as the Lord had vowed to them.'
EXEC add_BibleVerse @BibleId, 105002015, N'Indeed, it was the very hand of the Lord that eliminated them from within the camp until they were all gone.'
EXEC add_BibleVerse @BibleId, 105002016, N'So it was that after all the military men had been eliminated from the community,'
EXEC add_BibleVerse @BibleId, 105002017, N'the Lord said to me,'
EXEC add_BibleVerse @BibleId, 105002018, N'“Today you are going to cross the border of Moab, that is, of Ar.'
EXEC add_BibleVerse @BibleId, 105002019, N'But when you come close to the Ammonites, do not harass or provoke them because I am not giving you any of the Ammonites’ land as your possession; I have already given it to Lot’s descendants as their possession.'
EXEC add_BibleVerse @BibleId, 105002020, N'(That also is considered to be a land of the Rephaites. The Rephaites lived there originally; the Ammonites call them Zamzummites.'
EXEC add_BibleVerse @BibleId, 105002021, N'They are a people as powerful, numerous, and tall as the Anakites. But the Lord destroyed the Rephaites in advance of the Ammonites, so they dispossessed them and settled down in their place.'
EXEC add_BibleVerse @BibleId, 105002022, N'This is exactly what he did for the descendants of Esau who lived in Seir when he destroyed the Horites before them so that they could dispossess them and settle in their area to this very day.'
EXEC add_BibleVerse @BibleId, 105002023, N'As for the Avvites who lived in settlements as far west as Gaza, Caphtorites who came from Crete destroyed them and settled down in their place.)'
EXEC add_BibleVerse @BibleId, 105002024, N'Get up, make your way across Wadi Arnon. Look! I have already delivered over to you Sihon the Amorite, king of Heshbon, and his land. Go ahead! Take it! Engage him in war!'
EXEC add_BibleVerse @BibleId, 105002025, N'This very day I will begin to fill all the people of the earth with dread and to terrify them when they hear about you. They will shiver and shake in anticipation of your approach.”'
EXEC add_BibleVerse @BibleId, 105002026, N'Then I sent messengers from the Kedemoth Desert to King Sihon of Heshbon with an offer of peace:'
EXEC add_BibleVerse @BibleId, 105002027, N'“Let me pass through your land; I will keep strictly to the roadway. I will not turn aside to the right or the left.'
EXEC add_BibleVerse @BibleId, 105002028, N'Sell me food for cash so that I can eat and sell me water to drink. Just allow me to go through on foot,'
EXEC add_BibleVerse @BibleId, 105002029, N'just as the descendants of Esau who live at Seir and the Moabites who live in Ar did for me, until I cross the Jordan to the land the Lord our God is giving us.”'
EXEC add_BibleVerse @BibleId, 105002030, N'But King Sihon of Heshbon was unwilling to allow us to pass near him because the Lord our God had made him obstinate and stubborn so that he might deliver him over to you this very day.'
EXEC add_BibleVerse @BibleId, 105002031, N'The Lord said to me, “Look! I have already begun to give over Sihon and his land to you. Start right now to take his land as your possession.”'
EXEC add_BibleVerse @BibleId, 105002032, N'When Sihon and all his troops emerged to encounter us in battle at Jahaz,'
EXEC add_BibleVerse @BibleId, 105002033, N'the Lord our God delivered him over to us and we struck him down, along with his sons and everyone else.'
EXEC add_BibleVerse @BibleId, 105002034, N'At that time we seized all his cities and put every one of them under divine judgment, including even the women and children; we left no survivors.'
EXEC add_BibleVerse @BibleId, 105002035, N'We kept only the livestock and plunder from the cities for ourselves.'
EXEC add_BibleVerse @BibleId, 105002036, N'From Aroer, which is at the edge of Wadi Arnon (it is the city in the wadi), all the way to Gilead there was not a town able to resist us – the Lord our God gave them all to us.'
EXEC add_BibleVerse @BibleId, 105002037, N'However, you did not approach the land of the Ammonites, the Wadi Jabbok, the cities of the hill country, or any place else forbidden by the Lord our God.'
EXEC add_BibleVerse @BibleId, 105003001, N'Next we set out on the route to Bashan, but King Og of Bashan and his whole army came out to meet us in battle at Edrei.'
EXEC add_BibleVerse @BibleId, 105003002, N'The Lord, however, said to me, “Don’t be afraid of him because I have already given him, his whole army, and his land to you. You will do to him exactly what you did to King Sihon of the Amorites who lived in Heshbon.”'
EXEC add_BibleVerse @BibleId, 105003003, N'So the Lord our God did indeed give over to us King Og of Bashan and his whole army and we struck them down until not a single survivor was left.'
EXEC add_BibleVerse @BibleId, 105003004, N'We captured all his cities at that time – there was not a town we did not take from them – sixty cities, all the region of Argob, the dominion of Og in Bashan.'
EXEC add_BibleVerse @BibleId, 105003005, N'All of these cities were fortified by high walls, gates, and locking bars; in addition there were a great many open villages.'
EXEC add_BibleVerse @BibleId, 105003006, N'We put all of these under divine judgment just as we had done to King Sihon of Heshbon – every occupied city, including women and children.'
EXEC add_BibleVerse @BibleId, 105003007, N'But all the livestock and plunder from the cities we kept for ourselves.'
EXEC add_BibleVerse @BibleId, 105003008, N'So at that time we took the land of the two Amorite kings in the Transjordan from Wadi Arnon to Mount Hermon'
EXEC add_BibleVerse @BibleId, 105003009, N'(the Sidonians call Hermon Sirion and the Amorites call it Senir),'
EXEC add_BibleVerse @BibleId, 105003010, N'all the cities of the plateau, all of Gilead and Bashan as far as Salecah and Edrei, cities of the kingdom of Og in Bashan.'
EXEC add_BibleVerse @BibleId, 105003011, N'Only King Og of Bashan was left of the remaining Rephaites. (It is noteworthy that his sarcophagus was made of iron. Does it not, indeed, still remain in Rabbath of the Ammonites? It is thirteen and a half feet long and six feet wide according to standard measure.)'
EXEC add_BibleVerse @BibleId, 105003012, N'This is the land we brought under our control at that time: The territory extending from Aroer by the Wadi Arnon and half the Gilead hill country with its cities I gave to the Reubenites and Gadites.'
EXEC add_BibleVerse @BibleId, 105003013, N'The rest of Gilead and all of Bashan, the kingdom of Og, I gave to half the tribe of Manasseh. (All the region of Argob, that is, all Bashan, is called the land of Rephaim.'
EXEC add_BibleVerse @BibleId, 105003014, N'Jair, son of Manasseh, took all the Argob region as far as the border with the Geshurites and Maacathites (namely Bashan) and called it by his name, Havvoth-Jair, which it retains to this very day.)'
EXEC add_BibleVerse @BibleId, 105003015, N'I gave Gilead to Machir.'
EXEC add_BibleVerse @BibleId, 105003016, N'To the Reubenites and Gadites I allocated the territory extending from Gilead as far as Wadi Arnon (the exact middle of the wadi was a boundary) all the way to the Wadi Jabbok, the Ammonite border.'
EXEC add_BibleVerse @BibleId, 105003017, N'The Arabah and the Jordan River were also a border, from the sea of Chinnereth to the sea of the Arabah (that is, the Salt Sea), beneath the watershed of Pisgah to the east.'
EXEC add_BibleVerse @BibleId, 105003018, N'At that time I instructed you as follows: “The Lord your God has given you this land for your possession. You warriors are to cross over before your fellow Israelites equipped for battle.'
EXEC add_BibleVerse @BibleId, 105003019, N'But your wives, children, and livestock (of which I know you have many) may remain in the cities I have given you.'
EXEC add_BibleVerse @BibleId, 105003020, N'You must fight until the Lord gives your countrymen victory as he did you and they take possession of the land that the Lord your God is giving them on the other side of the Jordan River. Then each of you may return to his own territory that I have given you.”'
EXEC add_BibleVerse @BibleId, 105003021, N'I also commanded Joshua at the same time, “You have seen everything the Lord your God did to these two kings; he will do the same to all the kingdoms where you are going.'
EXEC add_BibleVerse @BibleId, 105003022, N'Do not be afraid of them, for the Lord your God will personally fight for you.”'
EXEC add_BibleVerse @BibleId, 105003023, N'Moreover, at that time I pleaded with the Lord,'
EXEC add_BibleVerse @BibleId, 105003024, N'“O, Lord God, you have begun to show me your greatness and strength. (What god in heaven or earth can rival your works and mighty deeds?)'
EXEC add_BibleVerse @BibleId, 105003025, N'Let me please cross over to see the good land on the other side of the Jordan River – this good hill country and the Lebanon!”'
EXEC add_BibleVerse @BibleId, 105003026, N'But the Lord was angry at me because of you and would not listen to me. Instead, he said to me, “Enough of that! Do not speak to me anymore about this matter.'
EXEC add_BibleVerse @BibleId, 105003027, N'Go up to the top of Pisgah and take a good look to the west, north, south, and east, for you will not be allowed to cross the Jordan.'
EXEC add_BibleVerse @BibleId, 105003028, N'Commission Joshua, and encourage and strengthen him, because he will lead these people over and will enable them to inherit the land you will see.”'
EXEC add_BibleVerse @BibleId, 105003029, N'So we settled down in the valley opposite Beth Peor.'
EXEC add_BibleVerse @BibleId, 105004001, N'Now, Israel, pay attention to the statutes and ordinances I am about to teach you, so that you might live and go on to enter and take possession of the land that the Lord, the God of your ancestors, is giving you.'
EXEC add_BibleVerse @BibleId, 105004002, N'Do not add a thing to what I command you nor subtract from it, so that you may keep the commandments of the Lord your God that I am delivering to you.'
EXEC add_BibleVerse @BibleId, 105004003, N'You have witnessed what the Lord did at Baal Peor, how he eradicated from your midst everyone who followed Baal Peor.'
EXEC add_BibleVerse @BibleId, 105004004, N'But you who remained faithful to the Lord your God are still alive to this very day, every one of you.'
EXEC add_BibleVerse @BibleId, 105004005, N'Look! I have taught you statutes and ordinances just as the Lord my God told me to do, so that you might carry them out in the land you are about to enter and possess.'
EXEC add_BibleVerse @BibleId, 105004006, N'So be sure to do them, because this will testify of your wise understanding to the people who will learn of all these statutes and say, “Indeed, this great nation is a very wise people.”'
EXEC add_BibleVerse @BibleId, 105004007, N'In fact, what other great nation has a god so near to them like the Lord our God whenever we call on him?'
EXEC add_BibleVerse @BibleId, 105004008, N'And what other great nation has statutes and ordinances as just as this whole law that I am about to share with you today?'
EXEC add_BibleVerse @BibleId, 105004009, N'Again, however, pay very careful attention, lest you forget the things you have seen and disregard them for the rest of your life; instead teach them to your children and grandchildren.'
EXEC add_BibleVerse @BibleId, 105004010, N'You stood before the Lord your God at Horeb and he said to me, “Assemble the people before me so that I can tell them my commands. Then they will learn to revere me all the days they live in the land, and they will instruct their children.”'
EXEC add_BibleVerse @BibleId, 105004011, N'You approached and stood at the foot of the mountain, a mountain ablaze to the sky above it and yet dark with a thick cloud.'
EXEC add_BibleVerse @BibleId, 105004012, N'Then the Lord spoke to you from the middle of the fire; you heard speech but you could not see anything – only a voice was heard.'
EXEC add_BibleVerse @BibleId, 105004013, N'And he revealed to you the covenant he has commanded you to keep, the ten commandments, writing them on two stone tablets.'
EXEC add_BibleVerse @BibleId, 105004014, N'Moreover, at that same time the Lord commanded me to teach you statutes and ordinances for you to keep in the land which you are about to enter and possess.'
EXEC add_BibleVerse @BibleId, 105004015, N'Be very careful, then, because you saw no form at the time the Lord spoke to you at Horeb from the middle of the fire.'
EXEC add_BibleVerse @BibleId, 105004016, N'I say this so you will not corrupt yourselves by making an image in the form of any kind of figure. This includes the likeness of a human male or female,'
EXEC add_BibleVerse @BibleId, 105004017, N'any kind of land animal, any bird that flies in the sky,'
EXEC add_BibleVerse @BibleId, 105004018, N'anything that crawls on the ground, or any fish in the deep waters of the earth.'
EXEC add_BibleVerse @BibleId, 105004019, N'When you look up to the sky and see the sun, moon, and stars – the whole heavenly creation – you must not be seduced to worship and serve them, for the Lord your God has assigned them to all the people of the world.'
EXEC add_BibleVerse @BibleId, 105004020, N'You, however, the Lord has selected and brought from Egypt, that iron-smelting furnace, to be his special people as you are today.'
EXEC add_BibleVerse @BibleId, 105004021, N'But the Lord became angry with me because of you and vowed that I would never cross the Jordan nor enter the good land that he is about to give you.'
EXEC add_BibleVerse @BibleId, 105004022, N'So I must die here in this land; I will not cross the Jordan. But you are going over and will possess that good land.'
EXEC add_BibleVerse @BibleId, 105004023, N'Be on guard so that you do not forget the covenant of the Lord your God that he has made with you, and that you do not make an image of any kind, just as he has forbidden you.'
EXEC add_BibleVerse @BibleId, 105004024, N'For the Lord your God is a consuming fire; he is a jealous God.'
EXEC add_BibleVerse @BibleId, 105004025, N'After you have produced children and grandchildren and have been in the land a long time, if you become corrupt and make an image of any kind and do other evil things before the Lord your God that enrage him,'
EXEC add_BibleVerse @BibleId, 105004026, N'I invoke heaven and earth as witnesses against you today that you will surely and swiftly be removed from the very land you are about to cross the Jordan to possess. You will not last long there because you will surely be annihilated.'
EXEC add_BibleVerse @BibleId, 105004027, N'Then the Lord will scatter you among the peoples and there will be very few of you among the nations where the Lord will drive you.'
EXEC add_BibleVerse @BibleId, 105004028, N'There you will worship gods made by human hands – wood and stone that can neither see, hear, eat, nor smell.'
EXEC add_BibleVerse @BibleId, 105004029, N'But if you seek the Lord your God from there, you will find him, if, indeed, you seek him with all your heart and soul.'
EXEC add_BibleVerse @BibleId, 105004030, N'In your distress when all these things happen to you in the latter days, if you return to the Lord your God and obey him'
EXEC add_BibleVerse @BibleId, 105004031, N'(for he is a merciful God), he will not let you down or destroy you, for he cannot forget the covenant with your ancestors that he confirmed by oath to them.'
EXEC add_BibleVerse @BibleId, 105004032, N'Indeed, ask about the distant past, starting from the day God created humankind on the earth, and ask from one end of heaven to the other, whether there has ever been such a great thing as this, or even a rumor of it.'
EXEC add_BibleVerse @BibleId, 105004033, N'Have a people ever heard the voice of God speaking from the middle of fire, as you yourselves have, and lived to tell about it?'
EXEC add_BibleVerse @BibleId, 105004034, N'Or has God ever before tried to deliver a nation from the middle of another nation, accompanied by judgments, signs, wonders, war, strength, power, and other very terrifying things like the Lord your God did for you in Egypt before your very eyes?'
EXEC add_BibleVerse @BibleId, 105004035, N'You have been taught that the Lord alone is God – there is no other besides him.'
EXEC add_BibleVerse @BibleId, 105004036, N'From heaven he spoke to you in order to teach you, and on earth he showed you his great fire from which you also heard his words.'
EXEC add_BibleVerse @BibleId, 105004037, N'Moreover, because he loved your ancestors, he chose their descendants who followed them and personally brought you out of Egypt with his great power'
EXEC add_BibleVerse @BibleId, 105004038, N'to dispossess nations greater and stronger than you and brought you here this day to give you their land as your property.'
EXEC add_BibleVerse @BibleId, 105004039, N'Today realize and carefully consider that the Lord is God in heaven above and on earth below – there is no other!'
EXEC add_BibleVerse @BibleId, 105004040, N'Keep his statutes and commandments that I am setting forth today so that it may go well with you and your descendants and that you may enjoy longevity in the land that the Lord your God is about to give you as a permanent possession.'
EXEC add_BibleVerse @BibleId, 105004041, N'Then Moses selected three cities in the Transjordan, toward the east.'
EXEC add_BibleVerse @BibleId, 105004042, N'Anyone who accidentally killed someone without hating him at the time of the accident could flee to one of those cities and be safe.'
EXEC add_BibleVerse @BibleId, 105004043, N'These cities are Bezer, in the desert plateau, for the Reubenites; Ramoth in Gilead for the Gadites; and Golan in Bashan for the Manassehites.'
EXEC add_BibleVerse @BibleId, 105004044, N'This is the law that Moses set before the Israelites.'
EXEC add_BibleVerse @BibleId, 105004045, N'These are the stipulations, statutes, and ordinances that Moses spoke to the Israelites after he had brought them out of Egypt,'
EXEC add_BibleVerse @BibleId, 105004046, N'in the Transjordan, in the valley opposite Beth Peor, in the land of King Sihon of the Amorites, who lived in Heshbon. (It is he whom Moses and the Israelites attacked after they came out of Egypt.'
EXEC add_BibleVerse @BibleId, 105004047, N'They possessed his land and that of King Og of Bashan – both of whom were Amorite kings in the Transjordan, to the east.'
EXEC add_BibleVerse @BibleId, 105004048, N'Their territory extended from Aroer at the edge of the Arnon valley as far as Mount Siyon – that is, Hermon –'
EXEC add_BibleVerse @BibleId, 105004049, N'including all the Arabah of the Transjordan in the east to the sea of the Arabah, beneath the watershed of Pisgah.)'
EXEC add_BibleVerse @BibleId, 105005001, N'Then Moses called all the people of Israel together and said to them: “Listen, Israel, to the statutes and ordinances that I am about to deliver to you today; learn them and be careful to keep them!'
EXEC add_BibleVerse @BibleId, 105005002, N'The Lord our God made a covenant with us at Horeb.'
EXEC add_BibleVerse @BibleId, 105005003, N'He did not make this covenant with our ancestors but with us, we who are here today, all of us living now.'
EXEC add_BibleVerse @BibleId, 105005004, N'The Lord spoke face to face with you at the mountain, from the middle of the fire.'
EXEC add_BibleVerse @BibleId, 105005005, N'(I was standing between the Lord and you at that time to reveal to you the message of the Lord, because you were afraid of the fire and would not go up the mountain.) He said:'
EXEC add_BibleVerse @BibleId, 105005006, N'“I am the Lord your God, he who brought you from the land of Egypt, from the place of slavery.'
EXEC add_BibleVerse @BibleId, 105005007, N'You must not have any other gods besides me.'
EXEC add_BibleVerse @BibleId, 105005008, N'You must not make for yourself an image of anything in heaven above, on earth below, or in the waters beneath.'
EXEC add_BibleVerse @BibleId, 105005009, N'You must not worship or serve them, for I, the Lord your God, am a jealous God. I punish the sons, grandsons, and great-grandsons for the sin of the fathers who reject me,'
EXEC add_BibleVerse @BibleId, 105005010, N'but I show covenant faithfulness to the thousands who choose me and keep my commandments.'
EXEC add_BibleVerse @BibleId, 105005011, N'You must not make use of the name of the Lord your God for worthless purposes, for the Lord will not exonerate anyone who abuses his name that way.'
EXEC add_BibleVerse @BibleId, 105005012, N'Be careful to observe the Sabbath day just as the Lord your God has commanded you.'
EXEC add_BibleVerse @BibleId, 105005013, N'You are to work and do all your tasks in six days,'
EXEC add_BibleVerse @BibleId, 105005014, N'but the seventh day is the Sabbath of the Lord your God. On that day you must not do any work, you, your son, your daughter, your male slave, your female slave, your ox, your donkey, any other animal, or the foreigner who lives with you, so that your male and female slaves, like yourself, may have rest.'
EXEC add_BibleVerse @BibleId, 105005015, N'Recall that you were slaves in the land of Egypt and that the Lord your God brought you out of there by strength and power. That is why the Lord your God has commanded you to observe the Sabbath day.'
EXEC add_BibleVerse @BibleId, 105005016, N'Honor your father and your mother just as the Lord your God has commanded you to do, so that your days may be extended and that it may go well with you in the land that he is about to give you.'
EXEC add_BibleVerse @BibleId, 105005017, N'You must not murder.'
EXEC add_BibleVerse @BibleId, 105005018, N'You must not commit adultery.'
EXEC add_BibleVerse @BibleId, 105005019, N'You must not steal.'
EXEC add_BibleVerse @BibleId, 105005020, N'You must not offer false testimony against another.'
EXEC add_BibleVerse @BibleId, 105005021, N'You must not desire another man’s wife, nor should you crave his house, his field, his male and female servants, his ox, his donkey, or anything else he owns.”'
EXEC add_BibleVerse @BibleId, 105005022, N'The Lord said these things to your entire assembly at the mountain from the middle of the fire, the cloud, and the darkness with a loud voice, and that was all he said. Then he inscribed the words on two stone tablets and gave them to me.'
EXEC add_BibleVerse @BibleId, 105005023, N'Then, when you heard the voice from the midst of the darkness while the mountain was ablaze, all your tribal leaders and elders approached me.'
EXEC add_BibleVerse @BibleId, 105005024, N'You said, “The Lord our God has shown us his great glory and we have heard him speak from the middle of the fire. It is now clear to us that God can speak to human beings and they can keep on living.'
EXEC add_BibleVerse @BibleId, 105005025, N'But now, why should we die, because this intense fire will consume us! If we keep hearing the voice of the Lord our God we will die!'
EXEC add_BibleVerse @BibleId, 105005026, N'Who is there from the entire human race who has heard the voice of the living God speaking from the middle of the fire as we have, and has lived?'
EXEC add_BibleVerse @BibleId, 105005027, N'You go near so that you can hear everything the Lord our God is saying and then you can tell us whatever he says to you; then we will pay attention and do it.”'
EXEC add_BibleVerse @BibleId, 105005028, N'When the Lord heard you speaking to me, he said to me, “I have heard what these people have said to you – they have spoken well.'
EXEC add_BibleVerse @BibleId, 105005029, N'If only it would really be their desire to fear me and obey all my commandments in the future, so that it may go well with them and their descendants forever.'
EXEC add_BibleVerse @BibleId, 105005030, N'Go and tell them, ‘Return to your tents!’'
EXEC add_BibleVerse @BibleId, 105005031, N'But as for you, remain here with me so I can declare to you all the commandments, statutes, and ordinances that you are to teach them, so that they can carry them out in the land I am about to give them.”'
EXEC add_BibleVerse @BibleId, 105005032, N'Be careful, therefore, to do exactly what the Lord your God has commanded you; do not turn right or left!'
EXEC add_BibleVerse @BibleId, 105005033, N'Walk just as he has commanded you so that you may live, that it may go well with you, and that you may live long in the land you are going to possess.'
EXEC add_BibleVerse @BibleId, 105006001, N'Now these are the commandments, statutes, and ordinances that the Lord your God instructed me to teach you so that you may carry them out in the land where you are headed'
EXEC add_BibleVerse @BibleId, 105006002, N'and that you may so revere the Lord your God that you will keep all his statutes and commandments that I am giving you – you, your children, and your grandchildren – all your lives, to prolong your days.'
EXEC add_BibleVerse @BibleId, 105006003, N'Pay attention, Israel, and be careful to do this so that it may go well with you and that you may increase greatly in number – as the Lord, God of your ancestors, said to you, you will have a land flowing with milk and honey.'
EXEC add_BibleVerse @BibleId, 105006004, N'Listen, Israel: The Lord is our God, the Lord is one!'
EXEC add_BibleVerse @BibleId, 105006005, N'You must love the Lord your God with your whole mind, your whole being, and all your strength.'
EXEC add_BibleVerse @BibleId, 105006006, N'These words I am commanding you today must be kept in mind,'
EXEC add_BibleVerse @BibleId, 105006007, N'and you must teach them to your children and speak of them as you sit in your house, as you walk along the road, as you lie down, and as you get up.'
EXEC add_BibleVerse @BibleId, 105006008, N'You should tie them as a reminder on your forearm and fasten them as symbols on your forehead.'
EXEC add_BibleVerse @BibleId, 105006009, N'Inscribe them on the doorframes of your houses and gates.'
EXEC add_BibleVerse @BibleId, 105006010, N'Then when the Lord your God brings you to the land he promised your ancestors Abraham, Isaac, and Jacob to give you – a land with large, fine cities you did not build,'
EXEC add_BibleVerse @BibleId, 105006011, N'houses filled with choice things you did not accumulate, hewn out cisterns you did not dig, and vineyards and olive groves you did not plant – and you eat your fill,'
EXEC add_BibleVerse @BibleId, 105006012, N'be careful not to forget the Lord who brought you out of Egypt, that place of slavery.'
EXEC add_BibleVerse @BibleId, 105006013, N'You must revere the Lord your God, serve him, and take oaths using only his name.'
EXEC add_BibleVerse @BibleId, 105006014, N'You must not go after other gods, those of the surrounding peoples,'
EXEC add_BibleVerse @BibleId, 105006015, N'for the Lord your God, who is present among you, is a jealous God and his anger will erupt against you and remove you from the land.'
EXEC add_BibleVerse @BibleId, 105006016, N'You must not put the Lord your God to the test as you did at Massah.'
EXEC add_BibleVerse @BibleId, 105006017, N'Keep his commandments very carefully, as well as the stipulations and statutes he commanded you to observe.'
EXEC add_BibleVerse @BibleId, 105006018, N'Do whatever is proper and good before the Lord so that it may go well with you and that you may enter and occupy the good land that he promised your ancestors,'
EXEC add_BibleVerse @BibleId, 105006019, N'and that you may drive out all your enemies just as the Lord said.'
EXEC add_BibleVerse @BibleId, 105006020, N'When your children ask you later on, “What are the stipulations, statutes, and ordinances that the Lord our God commanded you?”'
EXEC add_BibleVerse @BibleId, 105006021, N'you must say to them, “We were Pharaoh’s slaves in Egypt, but the Lord brought us out of Egypt in a powerful way.'
EXEC add_BibleVerse @BibleId, 105006022, N'And he brought signs and great, devastating wonders on Egypt, on Pharaoh, and on his whole family before our very eyes.'
EXEC add_BibleVerse @BibleId, 105006023, N'He delivered us from there so that he could give us the land he had promised our ancestors.'
EXEC add_BibleVerse @BibleId, 105006024, N'The Lord commanded us to obey all these statutes and to revere him so that it may always go well for us and he may preserve us, as he has to this day.'
EXEC add_BibleVerse @BibleId, 105006025, N'We will be innocent if we carefully keep all these commandments before the Lord our God, just as he demands.”'
EXEC add_BibleVerse @BibleId, 105007001, N'When the Lord your God brings you to the land that you are going to occupy and forces out many nations before you – Hittites, Girgashites, Amorites, Canaanites, Perizzites, Hivites, and Jebusites, seven nations more numerous and powerful than you –'
EXEC add_BibleVerse @BibleId, 105007002, N'and he delivers them over to you and you attack them, you must utterly annihilate them. Make no treaty with them and show them no mercy!'
EXEC add_BibleVerse @BibleId, 105007003, N'You must not intermarry with them. Do not give your daughters to their sons or take their daughters for your sons,'
EXEC add_BibleVerse @BibleId, 105007004, N'for they will turn your sons away from me to worship other gods. Then the anger of the Lord will erupt against you and he will quickly destroy you.'
EXEC add_BibleVerse @BibleId, 105007005, N'Instead, this is what you must do to them: You must tear down their altars, shatter their sacred pillars, cut down their sacred Asherah poles, and burn up their idols.'
EXEC add_BibleVerse @BibleId, 105007006, N'For you are a people holy to the Lord your God. He has chosen you to be his people, prized above all others on the face of the earth.'
EXEC add_BibleVerse @BibleId, 105007007, N'It is not because you were more numerous than all the other peoples that the Lord favored and chose you – for in fact you were the least numerous of all peoples.'
EXEC add_BibleVerse @BibleId, 105007008, N'Rather it is because of his love for you and his faithfulness to the promise he solemnly vowed to your ancestors that the Lord brought you out with great power, redeeming you from the place of slavery, from the power of Pharaoh king of Egypt.'
EXEC add_BibleVerse @BibleId, 105007009, N'So realize that the Lord your God is the true God, the faithful God who keeps covenant faithfully with those who love him and keep his commandments, to a thousand generations,'
EXEC add_BibleVerse @BibleId, 105007010, N'but who pays back those who hate him as they deserve and destroys them. He will not ignore those who hate him but will repay them as they deserve!'
EXEC add_BibleVerse @BibleId, 105007011, N'So keep the commandments, statutes, and ordinances that I today am commanding you to do.'
EXEC add_BibleVerse @BibleId, 105007012, N'If you obey these ordinances and are careful to do them, the Lord your God will faithfully keep covenant with you as he promised your ancestors.'
EXEC add_BibleVerse @BibleId, 105007013, N'He will love and bless you, and make you numerous. He will bless you with many children, with the produce of your soil, your grain, your new wine, your oil, the offspring of your oxen, and the young of your flocks in the land which he promised your ancestors to give you.'
EXEC add_BibleVerse @BibleId, 105007014, N'You will be blessed beyond all peoples; there will be no barrenness among you or your livestock.'
EXEC add_BibleVerse @BibleId, 105007015, N'The Lord will protect you from all sickness, and you will not experience any of the terrible diseases that you knew in Egypt; instead he will inflict them on all those who hate you.'
EXEC add_BibleVerse @BibleId, 105007016, N'You must destroy all the people whom the Lord your God is about to deliver over to you; you must not pity them or worship their gods, for that will be a snare to you.'
EXEC add_BibleVerse @BibleId, 105007017, N'If you think, “These nations are more numerous than I – how can I dispossess them?”'
EXEC add_BibleVerse @BibleId, 105007018, N'you must not fear them. You must carefully recall what the Lord your God did to Pharaoh and all Egypt,'
EXEC add_BibleVerse @BibleId, 105007019, N'the great judgments you saw, the signs and wonders, the strength and power by which he brought you out – thus the Lord your God will do to all the people you fear.'
EXEC add_BibleVerse @BibleId, 105007020, N'Furthermore, the Lord your God will release hornets among them until the very last ones who hide from you perish.'
EXEC add_BibleVerse @BibleId, 105007021, N'You must not tremble in their presence, for the Lord your God, who is present among you, is a great and awesome God.'
EXEC add_BibleVerse @BibleId, 105007022, N'He, the God who leads you, will expel the nations little by little. You will not be allowed to destroy them all at once lest the wild animals overrun you.'
EXEC add_BibleVerse @BibleId, 105007023, N'The Lord your God will give them over to you; he will throw them into a great panic until they are destroyed.'
EXEC add_BibleVerse @BibleId, 105007024, N'He will hand over their kings to you and you will erase their very names from memory. Nobody will be able to resist you until you destroy them.'
EXEC add_BibleVerse @BibleId, 105007025, N'You must burn the images of their gods, but do not covet the silver and gold that covers them so much that you take it for yourself and thus become ensnared by it; for it is abhorrent to the Lord your God.'
EXEC add_BibleVerse @BibleId, 105007026, N'You must not bring any abhorrent thing into your house and thereby become an object of divine wrath along with it. You must absolutely detest and abhor it, for it is an object of divine wrath.'
EXEC add_BibleVerse @BibleId, 105008001, N'You must keep carefully all these commandments I am giving you today so that you may live, increase in number, and go in and occupy the land that the Lord promised to your ancestors.'
EXEC add_BibleVerse @BibleId, 105008002, N'Remember the whole way by which he has brought you these forty years through the desert so that he might, by humbling you, test you to see if you have it within you to keep his commandments or not.'
EXEC add_BibleVerse @BibleId, 105008003, N'So he humbled you by making you hungry and then feeding you with unfamiliar manna. He did this to teach you that humankind cannot live by bread alone, but also by everything that comes from the Lord’s mouth.'
EXEC add_BibleVerse @BibleId, 105008004, N'Your clothing did not wear out nor did your feet swell all these forty years.'
EXEC add_BibleVerse @BibleId, 105008005, N'Be keenly aware that just as a parent disciplines his child, the Lord your God disciplines you.'
EXEC add_BibleVerse @BibleId, 105008006, N'So you must keep his commandments, live according to his standards, and revere him.'
EXEC add_BibleVerse @BibleId, 105008007, N'For the Lord your God is bringing you to a good land, a land of brooks, springs, and fountains flowing forth in valleys and hills,'
EXEC add_BibleVerse @BibleId, 105008008, N'a land of wheat, barley, vines, fig trees, and pomegranates, of olive trees and honey,'
EXEC add_BibleVerse @BibleId, 105008009, N'a land where you may eat food in plenty and find no lack of anything, a land whose stones are iron and from whose hills you can mine copper.'
EXEC add_BibleVerse @BibleId, 105008010, N'You will eat your fill and then praise the Lord your God because of the good land he has given you.'
EXEC add_BibleVerse @BibleId, 105008011, N'Be sure you do not forget the Lord your God by not keeping his commandments, ordinances, and statutes that I am giving you today.'
EXEC add_BibleVerse @BibleId, 105008012, N'When you eat your fill, when you build and occupy good houses,'
EXEC add_BibleVerse @BibleId, 105008013, N'when your cattle and flocks increase, when you have plenty of silver and gold, and when you have abundance of everything,'
EXEC add_BibleVerse @BibleId, 105008014, N'be sure you do not feel self-important and forget the Lord your God who brought you from the land of Egypt, the place of slavery,'
EXEC add_BibleVerse @BibleId, 105008015, N'and who brought you through the great, fearful desert of venomous serpents and scorpions, an arid place with no water. He made water flow from a flint rock and'
EXEC add_BibleVerse @BibleId, 105008016, N'fed you in the desert with manna (which your ancestors had never before known) so that he might by humbling you test you and eventually bring good to you.'
EXEC add_BibleVerse @BibleId, 105008017, N'Be careful not to say, “My own ability and skill have gotten me this wealth.”'
EXEC add_BibleVerse @BibleId, 105008018, N'You must remember the Lord your God, for he is the one who gives ability to get wealth; if you do this he will confirm his covenant that he made by oath to your ancestors, even as he has to this day.'
EXEC add_BibleVerse @BibleId, 105008019, N'Now if you forget the Lord your God at all and follow other gods, worshiping and prostrating yourselves before them, I testify to you today that you will surely be annihilated.'
EXEC add_BibleVerse @BibleId, 105008020, N'Just like the nations the Lord is about to destroy from your sight, so he will do to you because you would not obey him.'
EXEC add_BibleVerse @BibleId, 105009001, N'Listen, Israel: Today you are about to cross the Jordan so you can dispossess the nations there, people greater and stronger than you who live in large cities with extremely high fortifications.'
EXEC add_BibleVerse @BibleId, 105009002, N'They include the Anakites, a numerous and tall people whom you know about and of whom it is said, “Who is able to resist the Anakites?”'
EXEC add_BibleVerse @BibleId, 105009003, N'Understand today that the Lord your God who goes before you is a devouring fire; he will defeat and subdue them before you. You will dispossess and destroy them quickly just as he has told you.'
EXEC add_BibleVerse @BibleId, 105009004, N'Do not think to yourself after the Lord your God has driven them out before you, “Because of my own righteousness the Lord has brought me here to possess this land.” It is because of the wickedness of these nations that the Lord is driving them out ahead of you.'
EXEC add_BibleVerse @BibleId, 105009005, N'It is not because of your righteousness, or even your inner uprightness, that you have come here to possess their land. Instead, because of the wickedness of these nations the Lord your God is driving them out ahead of you in order to confirm the promise he made on oath to your ancestors, to Abraham, Isaac, and Jacob.'
EXEC add_BibleVerse @BibleId, 105009006, N'Understand, therefore, that it is not because of your righteousness that the Lord your God is about to give you this good land as a possession, for you are a stubborn people!'
EXEC add_BibleVerse @BibleId, 105009007, N'Remember – don’t ever forget – how you provoked the Lord your God in the desert; from the time you left the land of Egypt until you came to this place you were constantly rebelling against him.'
EXEC add_BibleVerse @BibleId, 105009008, N'At Horeb you provoked him and he was angry enough with you to destroy you.'
EXEC add_BibleVerse @BibleId, 105009009, N'When I went up the mountain to receive the stone tablets, the tablets of the covenant that the Lord made with you, I remained there forty days and nights, eating and drinking nothing.'
EXEC add_BibleVerse @BibleId, 105009010, N'The Lord gave me the two stone tablets, written by the very finger of God, and on them was everything he said to you at the mountain from the midst of the fire at the time of that assembly.'
EXEC add_BibleVerse @BibleId, 105009011, N'Now at the end of the forty days and nights the Lord presented me with the two stone tablets, the tablets of the covenant.'
EXEC add_BibleVerse @BibleId, 105009012, N'And he said to me, “Get up, go down at once from here because your people whom you brought out of Egypt have sinned! They have quickly turned from the way I commanded them and have made for themselves a cast metal image.”'
EXEC add_BibleVerse @BibleId, 105009013, N'Moreover, he said to me, “I have taken note of these people; they are a stubborn lot!'
EXEC add_BibleVerse @BibleId, 105009014, N'Stand aside and I will destroy them, obliterating their very name from memory, and I will make you into a stronger and more numerous nation than they are.”'
EXEC add_BibleVerse @BibleId, 105009015, N'So I turned and went down the mountain while it was blazing with fire; the two tablets of the covenant were in my hands.'
EXEC add_BibleVerse @BibleId, 105009016, N'When I looked, you had indeed sinned against the Lord your God and had cast for yourselves a metal calf; you had quickly turned aside from the way he had commanded you!'
EXEC add_BibleVerse @BibleId, 105009017, N'I grabbed the two tablets, threw them down, and shattered them before your very eyes.'
EXEC add_BibleVerse @BibleId, 105009018, N'Then I again fell down before the Lord for forty days and nights; I ate and drank nothing because of all the sin you had committed, doing such evil before the Lord as to enrage him.'
EXEC add_BibleVerse @BibleId, 105009019, N'For I was terrified at the Lord’s intense anger that threatened to destroy you. But he listened to me this time as well.'
EXEC add_BibleVerse @BibleId, 105009020, N'The Lord was also angry enough at Aaron to kill him, but at that time I prayed for him too.'
EXEC add_BibleVerse @BibleId, 105009021, N'As for your sinful thing that you had made, the calf, I took it, melted it down, ground it up until it was as fine as dust, and tossed the dust into the stream that flows down the mountain.'
EXEC add_BibleVerse @BibleId, 105009022, N'Moreover, you continued to provoke the Lord at Taberah, Massah, and Kibroth-Hattaavah.'
EXEC add_BibleVerse @BibleId, 105009023, N'And when he sent you from Kadesh-Barnea and told you, “Go up and possess the land I have given you,” you rebelled against the Lord your God and would neither believe nor obey him.'
EXEC add_BibleVerse @BibleId, 105009024, N'You have been rebelling against him from the very first day I knew you!'
EXEC add_BibleVerse @BibleId, 105009025, N'I lay flat on the ground before the Lord for forty days and nights, for he had said he would destroy you.'
EXEC add_BibleVerse @BibleId, 105009026, N'I prayed to him: O, Lord God, do not destroy your people, your valued property that you have powerfully redeemed, whom you brought out of Egypt by your strength.'
EXEC add_BibleVerse @BibleId, 105009027, N'Remember your servants Abraham, Isaac, and Jacob; ignore the stubbornness, wickedness, and sin of these people.'
EXEC add_BibleVerse @BibleId, 105009028, N'Otherwise the people of the land from which you brought us will say, “The Lord was unable to bring them to the land he promised them, and because of his hatred for them he has brought them out to kill them in the desert.”'
EXEC add_BibleVerse @BibleId, 105009029, N'They are your people, your valued property, whom you brought out with great strength and power.'
EXEC add_BibleVerse @BibleId, 105010001, N'At that same time the Lord said to me, “Carve out for yourself two stone tablets like the first ones and come up the mountain to me; also make for yourself a wooden ark.'
EXEC add_BibleVerse @BibleId, 105010002, N'I will write on the tablets the same words that were on the first tablets you broke, and you must put them into the ark.”'
EXEC add_BibleVerse @BibleId, 105010003, N'So I made an ark of acacia wood and carved out two stone tablets just like the first ones. Then I went up the mountain with the two tablets in my hands.'
EXEC add_BibleVerse @BibleId, 105010004, N'The Lord then wrote on the tablets the same words, the ten commandments, which he had spoken to you at the mountain from the middle of the fire at the time of that assembly, and he gave them to me.'
EXEC add_BibleVerse @BibleId, 105010005, N'Then I turned, went down the mountain, and placed the tablets into the ark I had made – they are still there, just as the Lord commanded me.'
EXEC add_BibleVerse @BibleId, 105010006, N'“During those days the Israelites traveled from Beeroth Bene-Yaaqan to Moserah. There Aaron died and was buried, and his son Eleazar became priest in his place.'
EXEC add_BibleVerse @BibleId, 105010007, N'From there they traveled to Gudgodah, and from Gudgodah to Jotbathah, a place of flowing streams.'
EXEC add_BibleVerse @BibleId, 105010008, N'At that time the Lord set apart the tribe of Levi to carry the ark of the Lord’s covenant, to stand before the Lord to serve him, and to formulate blessings in his name, as they do to this very day.'
EXEC add_BibleVerse @BibleId, 105010009, N'Therefore Levi has no allotment or inheritance among his brothers; the Lord is his inheritance just as the Lord your God told him.'
EXEC add_BibleVerse @BibleId, 105010010, N'As for me, I stayed at the mountain as I did the first time, forty days and nights. The Lord listened to me that time as well and decided not to destroy you.'
EXEC add_BibleVerse @BibleId, 105010011, N'Then he said to me, “Get up, set out leading the people so they may go and possess the land I promised to give to their ancestors.”'
EXEC add_BibleVerse @BibleId, 105010012, N'Now, Israel, what does the Lord your God require of you except to revere him, to obey all his commandments, to love him, to serve him with all your mind and being,'
EXEC add_BibleVerse @BibleId, 105010013, N'and to keep the Lord’s commandments and statutes that I am giving you today for your own good?'
EXEC add_BibleVerse @BibleId, 105010014, N'The heavens – indeed the highest heavens – belong to the Lord your God, as does the earth and everything in it.'
EXEC add_BibleVerse @BibleId, 105010015, N'However, only to your ancestors did he show his loving favor, and he chose you, their descendants, from all peoples – as is apparent today.'
EXEC add_BibleVerse @BibleId, 105010016, N'Therefore, cleanse your heart and stop being so stubborn!'
EXEC add_BibleVerse @BibleId, 105010017, N'For the Lord your God is God of gods and Lord of lords, the great, mighty, and awesome God who is unbiased and takes no bribe,'
EXEC add_BibleVerse @BibleId, 105010018, N'who justly treats the orphan and widow, and who loves resident foreigners, giving them food and clothing.'
EXEC add_BibleVerse @BibleId, 105010019, N'So you must love the resident foreigner because you were foreigners in the land of Egypt.'
EXEC add_BibleVerse @BibleId, 105010020, N'Revere the Lord your God, serve him, be loyal to him and take oaths only in his name.'
EXEC add_BibleVerse @BibleId, 105010021, N'He is the one you should praise; he is your God, the one who has done these great and awesome things for you that you have seen.'
EXEC add_BibleVerse @BibleId, 105010022, N'When your ancestors went down to Egypt, they numbered only seventy, but now the Lord your God has made you as numerous as the stars of the sky.'
EXEC add_BibleVerse @BibleId, 105011001, N'You must love the Lord your God and do what he requires; keep his statutes, ordinances, and commandments at all times.'
EXEC add_BibleVerse @BibleId, 105011002, N'Bear in mind today that I am not speaking to your children who have not personally experienced the judgments of the Lord your God, which revealed his greatness, strength, and power.'
EXEC add_BibleVerse @BibleId, 105011003, N'They did not see the awesome deeds he performed in the midst of Egypt against Pharaoh king of Egypt and his whole land,'
EXEC add_BibleVerse @BibleId, 105011004, N'or what he did to the army of Egypt, including their horses and chariots, when he made the waters of the Red Sea overwhelm them while they were pursuing you and he annihilated them.'
EXEC add_BibleVerse @BibleId, 105011005, N'They did not see what he did to you in the desert before you reached this place,'
EXEC add_BibleVerse @BibleId, 105011006, N'or what he did to Dathan and Abiram, sons of Eliab the Reubenite, when the earth opened its mouth in the middle of the Israelite camp and swallowed them, their families, their tents, and all the property they brought with them.'
EXEC add_BibleVerse @BibleId, 105011007, N'I am speaking to you because you are the ones who saw all the great deeds of the Lord!'
EXEC add_BibleVerse @BibleId, 105011008, N'Now pay attention to all the commandments I am giving you today, so that you may be strong enough to enter and possess the land where you are headed,'
EXEC add_BibleVerse @BibleId, 105011009, N'and that you may enjoy long life in the land the Lord promised to give to your ancestors and their descendants, a land flowing with milk and honey.'
EXEC add_BibleVerse @BibleId, 105011010, N'For the land where you are headed is not like the land of Egypt from which you came, a land where you planted seed and which you irrigated by hand like a vegetable garden.'
EXEC add_BibleVerse @BibleId, 105011011, N'Instead, the land you are crossing the Jordan to occupy is one of hills and valleys, a land that drinks in water from the rains,'
EXEC add_BibleVerse @BibleId, 105011012, N'a land the Lord your God looks after. He is constantly attentive to it from the beginning to the end of the year.'
EXEC add_BibleVerse @BibleId, 105011013, N'Now, if you pay close attention to my commandments that I am giving you today and love the Lord your God and serve him with all your mind and being,'
EXEC add_BibleVerse @BibleId, 105011014, N'then he promises, “I will send rain for your land in its season, the autumn and the spring rains, so that you may gather in your grain, new wine, and olive oil.'
EXEC add_BibleVerse @BibleId, 105011015, N'I will provide pasture for your livestock and you will eat your fill.”'
EXEC add_BibleVerse @BibleId, 105011016, N'Make sure you do not turn away to serve and worship other gods!'
EXEC add_BibleVerse @BibleId, 105011017, N'Then the anger of the Lord will erupt against you and he will close up the sky so that it does not rain. The land will not yield its produce, and you will soon be removed from the good land that the Lord is about to give you.'
EXEC add_BibleVerse @BibleId, 105011018, N'Fix these words of mine into your mind and being, and tie them as a reminder on your hands and let them be symbols on your forehead.'
EXEC add_BibleVerse @BibleId, 105011019, N'Teach them to your children and speak of them as you sit in your house, as you walk along the road, as you lie down, and as you get up.'
EXEC add_BibleVerse @BibleId, 105011020, N'Inscribe them on the doorframes of your houses and on your gates'
EXEC add_BibleVerse @BibleId, 105011021, N'so that your days and those of your descendants may be extended in the land which the Lord promised to give to your ancestors, like the days of heaven itself.'
EXEC add_BibleVerse @BibleId, 105011022, N'For if you carefully observe all of these commandments I am giving you and love the Lord your God, live according to his standards, and remain loyal to him,'
EXEC add_BibleVerse @BibleId, 105011023, N'then he will drive out all these nations ahead of you, and you will dispossess nations greater and stronger than you.'
EXEC add_BibleVerse @BibleId, 105011024, N'Every place you set your foot will be yours; your border will extend from the desert to Lebanon and from the River (that is, the Euphrates) as far as the Mediterranean Sea.'
EXEC add_BibleVerse @BibleId, 105011025, N'Nobody will be able to resist you; the Lord your God will spread the fear and terror of you over the whole land on which you walk, just as he promised you.'
EXEC add_BibleVerse @BibleId, 105011026, N'Take note – I am setting before you today a blessing and a curse:'
EXEC add_BibleVerse @BibleId, 105011027, N'the blessing if you take to heart the commandments of the Lord your God that I am giving you today,'
EXEC add_BibleVerse @BibleId, 105011028, N'and the curse if you pay no attention to his commandments and turn from the way I am setting before you today to pursue other gods you have not known.'
EXEC add_BibleVerse @BibleId, 105011029, N'When the Lord your God brings you into the land you are to possess, you must pronounce the blessing on Mount Gerizim and the curse on Mount Ebal.'
EXEC add_BibleVerse @BibleId, 105011030, N'Are they not across the Jordan River, toward the west, in the land of the Canaanites who live in the Arabah opposite Gilgal near the oak of Moreh?'
EXEC add_BibleVerse @BibleId, 105011031, N'For you are about to cross the Jordan to possess the land the Lord your God is giving you, and you will possess and inhabit it.'
EXEC add_BibleVerse @BibleId, 105011032, N'Be certain to keep all the statutes and ordinances that I am presenting to you today.'
EXEC add_BibleVerse @BibleId, 105012001, N'These are the statutes and ordinances you must be careful to obey as long as you live in the land the Lord, the God of your ancestors, has given you to possess.'
EXEC add_BibleVerse @BibleId, 105012002, N'You must by all means destroy all the places where the nations you are about to dispossess worship their gods – on the high mountains and hills and under every leafy tree.'
EXEC add_BibleVerse @BibleId, 105012003, N'You must tear down their altars, shatter their sacred pillars, burn up their sacred Asherah poles, and cut down the images of their gods; you must eliminate their very memory from that place.'
EXEC add_BibleVerse @BibleId, 105012004, N'You must not worship the Lord your God the way they worship.'
EXEC add_BibleVerse @BibleId, 105012005, N'But you must seek only the place he chooses from all your tribes to establish his name as his place of residence, and you must go there.'
EXEC add_BibleVerse @BibleId, 105012006, N'And there you must take your burnt offerings, your sacrifices, your tithes, the personal offerings you have prepared, your votive offerings, your freewill offerings, and the firstborn of your herds and flocks.'
EXEC add_BibleVerse @BibleId, 105012007, N'Both you and your families must feast there before the Lord your God and rejoice in all the output of your labor with which he has blessed you.'
EXEC add_BibleVerse @BibleId, 105012008, N'You must not do like we are doing here today, with everyone doing what seems best to him,'
EXEC add_BibleVerse @BibleId, 105012009, N'for you have not yet come to the final stop and inheritance the Lord your God is giving you.'
EXEC add_BibleVerse @BibleId, 105012010, N'When you do go across the Jordan River and settle in the land he is granting you as an inheritance and you find relief from all the enemies who surround you, you will live in safety.'
EXEC add_BibleVerse @BibleId, 105012011, N'Then you must come to the place the Lord your God chooses for his name to reside, bringing everything I am commanding you – your burnt offerings, sacrifices, tithes, the personal offerings you have prepared, and all your choice votive offerings which you devote to him.'
EXEC add_BibleVerse @BibleId, 105012012, N'You shall rejoice in the presence of the Lord your God, along with your sons, daughters, male and female servants, and the Levites in your villages (since they have no allotment or inheritance with you).'
EXEC add_BibleVerse @BibleId, 105012013, N'Make sure you do not offer burnt offerings in any place you wish,'
EXEC add_BibleVerse @BibleId, 105012014, N'for you may do so only in the place the Lord chooses in one of your tribal areas – there you may do everything I am commanding you.'
EXEC add_BibleVerse @BibleId, 105012015, N'On the other hand, you may slaughter and eat meat as you please when the Lord your God blesses you in all your villages. Both the ritually pure and impure may eat it, whether it is a gazelle or an ibex.'
EXEC add_BibleVerse @BibleId, 105012016, N'However, you must not eat blood – pour it out on the ground like water.'
EXEC add_BibleVerse @BibleId, 105012017, N'You will not be allowed to eat in your villages your tithe of grain, new wine, olive oil, the firstborn of your herd and flock, any votive offerings you have vowed, or your freewill and personal offerings.'
EXEC add_BibleVerse @BibleId, 105012018, N'Only in the presence of the Lord your God may you eat these, in the place he chooses. This applies to you, your son, your daughter, your male and female servants, and the Levites in your villages. In that place you will rejoice before the Lord your God in all the output of your labor.'
EXEC add_BibleVerse @BibleId, 105012019, N'Be careful not to overlook the Levites as long as you live in the land.'
EXEC add_BibleVerse @BibleId, 105012020, N'When the Lord your God extends your borders as he said he would do and you say, “I want to eat meat just as I please,” you may do so as you wish.'
EXEC add_BibleVerse @BibleId, 105012021, N'If the place he chooses to locate his name is too far for you, you may slaughter any of your herd and flock he has given you just as I have stipulated; you may eat them in your villages just as you wish.'
EXEC add_BibleVerse @BibleId, 105012022, N'Like you eat the gazelle or ibex, so you may eat these; the ritually impure and pure alike may eat them.'
EXEC add_BibleVerse @BibleId, 105012023, N'However, by no means eat the blood, for the blood is life itself – you must not eat the life with the meat!'
EXEC add_BibleVerse @BibleId, 105012024, N'You must not eat it! You must pour it out on the ground like water.'
EXEC add_BibleVerse @BibleId, 105012025, N'You must not eat it so that it may go well with you and your children after you; you will be doing what is right in the Lord’s sight.'
EXEC add_BibleVerse @BibleId, 105012026, N'Only the holy things and votive offerings that belong to you, you must pick up and take to the place the Lord will choose.'
EXEC add_BibleVerse @BibleId, 105012027, N'You must offer your burnt offerings, both meat and blood, on the altar of the Lord your God; the blood of your other sacrifices you must pour out on his altar while you eat the meat.'
EXEC add_BibleVerse @BibleId, 105012028, N'Pay careful attention to all these things I am commanding you so that it may always go well with you and your children after you when you do what is good and right in the sight of the Lord your God.'
EXEC add_BibleVerse @BibleId, 105012029, N'When the Lord your God eliminates the nations from the place where you are headed and you dispossess them, you will settle down in their land.'
EXEC add_BibleVerse @BibleId, 105012030, N'After they have been destroyed from your presence, be careful not to be ensnared like they are; do not pursue their gods and say, “How do these nations serve their gods? I will do the same.”'
EXEC add_BibleVerse @BibleId, 105012031, N'You must not worship the Lord your God the way they do! For everything that is abhorrent to him, everything he hates, they have done when worshiping their gods. They even burn up their sons and daughters before their gods!'
EXEC add_BibleVerse @BibleId, 105012032, N'You must be careful to do everything I am commanding you. Do not add to it or subtract from it!'
EXEC add_BibleVerse @BibleId, 105013001, N'Suppose a prophet or one who foretells by dreams should appear among you and show you a sign or wonder,'
EXEC add_BibleVerse @BibleId, 105013002, N'and the sign or wonder should come to pass concerning what he said to you, namely, “Let us follow other gods” – gods whom you have not previously known – “and let us serve them.”'
EXEC add_BibleVerse @BibleId, 105013003, N'You must not listen to the words of that prophet or dreamer, for the Lord your God will be testing you to see if you love him with all your mind and being.'
EXEC add_BibleVerse @BibleId, 105013004, N'You must follow the Lord your God and revere only him; and you must observe his commandments, obey him, serve him, and remain loyal to him.'
EXEC add_BibleVerse @BibleId, 105013005, N'As for that prophet or dreamer, he must be executed because he encouraged rebellion against the Lord your God who brought you from the land of Egypt, redeeming you from that place of slavery, and because he has tried to entice you from the way the Lord your God has commanded you to go. In this way you must purge out evil from within.'
EXEC add_BibleVerse @BibleId, 105013006, N'Suppose your own full brother, your son, your daughter, your beloved wife, or your closest friend should seduce you secretly and encourage you to go and serve other gods that neither you nor your ancestors have previously known,'
EXEC add_BibleVerse @BibleId, 105013007, N'the gods of the surrounding people (whether near you or far from you, from one end of the earth to the other).'
EXEC add_BibleVerse @BibleId, 105013008, N'You must not give in to him or even listen to him; do not feel sympathy for him or spare him or cover up for him.'
EXEC add_BibleVerse @BibleId, 105013009, N'Instead, you must kill him without fail! Your own hand must be the first to strike him, and then the hands of the whole community.'
EXEC add_BibleVerse @BibleId, 105013010, N'You must stone him to death because he tried to entice you away from the Lord your God, who delivered you from the land of Egypt, that place of slavery.'
EXEC add_BibleVerse @BibleId, 105013011, N'Thus all Israel will hear and be afraid; no longer will they continue to do evil like this among you.'
EXEC add_BibleVerse @BibleId, 105013012, N'Suppose you should hear in one of your cities, which the Lord your God is giving you as a place to live, that'
EXEC add_BibleVerse @BibleId, 105013013, N'some evil people have departed from among you to entice the inhabitants of their cities, saying, “Let’s go and serve other gods” (whom you have not known before).'
EXEC add_BibleVerse @BibleId, 105013014, N'You must investigate thoroughly and inquire carefully. If it is indeed true that such a disgraceful thing is being done among you,'
EXEC add_BibleVerse @BibleId, 105013015, N'you must by all means slaughter the inhabitants of that city with the sword; annihilate with the sword everyone in it, as well as the livestock.'
EXEC add_BibleVerse @BibleId, 105013016, N'You must gather all of its plunder into the middle of the plaza and burn the city and all its plunder as a whole burnt offering to the Lord your God. It will be an abandoned ruin forever – it must never be rebuilt again.'
EXEC add_BibleVerse @BibleId, 105013017, N'You must not take for yourself anything that has been placed under judgment. Then the Lord will relent from his intense anger, show you compassion, have mercy on you, and multiply you as he promised your ancestors.'
EXEC add_BibleVerse @BibleId, 105013018, N'Thus you must obey the Lord your God, keeping all his commandments that I am giving you today and doing what is right before him.'
EXEC add_BibleVerse @BibleId, 105014001, N'You are children of the Lord your God. Do not cut yourselves or shave your forehead bald for the sake of the dead.'
EXEC add_BibleVerse @BibleId, 105014002, N'For you are a people holy to the Lord your God. He has chosen you to be his people, prized above all others on the face of the earth.'
EXEC add_BibleVerse @BibleId, 105014003, N'You must not eat any forbidden thing.'
EXEC add_BibleVerse @BibleId, 105014004, N'These are the animals you may eat: the ox, the sheep, the goat,'
EXEC add_BibleVerse @BibleId, 105014005, N'the ibex, the gazelle, the deer, the wild goat, the antelope, the wild oryx, and the mountain sheep.'
EXEC add_BibleVerse @BibleId, 105014006, N'You may eat any animal that has hooves divided into two parts and that chews the cud.'
EXEC add_BibleVerse @BibleId, 105014007, N'However, you may not eat the following animals among those that chew the cud or those that have divided hooves: the camel, the hare, and the rock badger. (Although they chew the cud, they do not have divided hooves and are therefore ritually impure to you).'
EXEC add_BibleVerse @BibleId, 105014008, N'Also the pig is ritually impure to you; though it has divided hooves, it does not chew the cud. You may not eat their meat or even touch their remains.'
EXEC add_BibleVerse @BibleId, 105014009, N'These you may eat from among water creatures: anything with fins and scales you may eat,'
EXEC add_BibleVerse @BibleId, 105014010, N'but whatever does not have fins and scales you may not eat; it is ritually impure to you.'
EXEC add_BibleVerse @BibleId, 105014011, N'All ritually clean birds you may eat.'
EXEC add_BibleVerse @BibleId, 105014012, N'These are the ones you may not eat: the eagle, the vulture, the black vulture,'
EXEC add_BibleVerse @BibleId, 105014013, N'the kite, the black kite, the dayyah after its species,'
EXEC add_BibleVerse @BibleId, 105014014, N'every raven after its species,'
EXEC add_BibleVerse @BibleId, 105014015, N'the ostrich, the owl, the seagull, the falcon after its species,'
EXEC add_BibleVerse @BibleId, 105014016, N'the little owl, the long-eared owl, the white owl,'
EXEC add_BibleVerse @BibleId, 105014017, N'the jackdaw, the carrion vulture, the cormorant,'
EXEC add_BibleVerse @BibleId, 105014018, N'the stork, the heron after its species, the hoopoe, the bat,'
EXEC add_BibleVerse @BibleId, 105014019, N'and any winged thing on the ground are impure to you – they may not be eaten.'
EXEC add_BibleVerse @BibleId, 105014020, N'You may eat any clean bird.'
EXEC add_BibleVerse @BibleId, 105014021, N'You may not eat any corpse, though you may give it to the resident foreigner who is living in your villages and he may eat it, or you may sell it to a foreigner. You are a people holy to the Lord your God. Do not boil a young goat in its mother’s milk.'
EXEC add_BibleVerse @BibleId, 105014022, N'You must be certain to tithe all the produce of your seed that comes from the field year after year.'
EXEC add_BibleVerse @BibleId, 105014023, N'In the presence of the Lord your God you must eat from the tithe of your grain, your new wine, your olive oil, and the firstborn of your herds and flocks in the place he chooses to locate his name, so that you may learn to revere the Lord your God always.'
EXEC add_BibleVerse @BibleId, 105014024, N'When he blesses you, if the place where he chooses to locate his name is distant,'
EXEC add_BibleVerse @BibleId, 105014025, N'you may convert the tithe into money, secure the money, and travel to the place the Lord your God chooses for himself.'
EXEC add_BibleVerse @BibleId, 105014026, N'Then you may spend the money however you wish for cattle, sheep, wine, beer, or whatever you desire. You and your household may eat there in the presence of the Lord your God and enjoy it.'
EXEC add_BibleVerse @BibleId, 105014027, N'As for the Levites in your villages, you must not ignore them, for they have no allotment or inheritance along with you.'
EXEC add_BibleVerse @BibleId, 105014028, N'At the end of every three years you must bring all the tithe of your produce, in that very year, and you must store it up in your villages.'
EXEC add_BibleVerse @BibleId, 105014029, N'Then the Levites (because they have no allotment or inheritance with you), the resident foreigners, the orphans, and the widows of your villages may come and eat their fill so that the Lord your God may bless you in all the work you do.'
EXEC add_BibleVerse @BibleId, 105015001, N'At the end of every seven years you must declare a cancellation of debts.'
EXEC add_BibleVerse @BibleId, 105015002, N'This is the nature of the cancellation: Every creditor must remit what he has loaned to another person; he must not force payment from his fellow Israelite, for it is to be recognized as “the Lord’s cancellation of debts.”'
EXEC add_BibleVerse @BibleId, 105015003, N'You may exact payment from a foreigner, but whatever your fellow Israelite owes you, you must remit.'
EXEC add_BibleVerse @BibleId, 105015004, N'However, there should not be any poor among you, for the Lord will surely bless you in the land that he is giving you as an inheritance,'
EXEC add_BibleVerse @BibleId, 105015005, N'if you carefully obey him by keeping all these commandments that I am giving you today.'
EXEC add_BibleVerse @BibleId, 105015006, N'For the Lord your God will bless you just as he has promised; you will lend to many nations but will not borrow from any, and you will rule over many nations but they will not rule over you.'
EXEC add_BibleVerse @BibleId, 105015007, N'If a fellow Israelite from one of your villages in the land that the Lord your God is giving you should be poor, you must not harden your heart or be insensitive to his impoverished condition.'
EXEC add_BibleVerse @BibleId, 105015008, N'Instead, you must be sure to open your hand to him and generously lend him whatever he needs.'
EXEC add_BibleVerse @BibleId, 105015009, N'Be careful lest you entertain the wicked thought that the seventh year, the year of cancellation of debts, has almost arrived, and your attitude be wrong toward your impoverished fellow Israelite and you do not lend him anything; he will cry out to the Lord against you and you will be regarded as having sinned.'
EXEC add_BibleVerse @BibleId, 105015010, N'You must by all means lend to him and not be upset by doing it, for because of this the Lord your God will bless you in all your work and in everything you attempt.'
EXEC add_BibleVerse @BibleId, 105015011, N'There will never cease to be some poor people in the land; therefore, I am commanding you to make sure you open your hand to your fellow Israelites who are needy and poor in your land.'
EXEC add_BibleVerse @BibleId, 105015012, N'If your fellow Hebrew – whether male or female – is sold to you and serves you for six years, then in the seventh year you must let that servant go free.'
EXEC add_BibleVerse @BibleId, 105015013, N'If you set them free, you must not send them away empty-handed.'
EXEC add_BibleVerse @BibleId, 105015014, N'You must supply them generously from your flock, your threshing floor, and your winepress – as the Lord your God has blessed you, you must give to them.'
EXEC add_BibleVerse @BibleId, 105015015, N'Remember that you were a slave in the land of Egypt and the Lord your God redeemed you; therefore, I am commanding you to do this thing today.'
EXEC add_BibleVerse @BibleId, 105015016, N'However, if the servant says to you, “I do not want to leave you,” because he loves you and your household, since he is well off with you,'
EXEC add_BibleVerse @BibleId, 105015017, N'you shall take an awl and pierce a hole through his ear to the door. Then he will become your servant permanently (this applies to your female servant as well).'
EXEC add_BibleVerse @BibleId, 105015018, N'You should not consider it difficult to let him go free, for he will have served you for six years, twice the time of a hired worker; the Lord your God will bless you in everything you do.'
EXEC add_BibleVerse @BibleId, 105015019, N'You must set apart for the Lord your God every firstborn male born to your herds and flocks. You must not work the firstborn of your bulls or shear the firstborn of your flocks.'
EXEC add_BibleVerse @BibleId, 105015020, N'You and your household must eat them annually before the Lord your God in the place he chooses.'
EXEC add_BibleVerse @BibleId, 105015021, N'If they have any kind of blemish – lameness, blindness, or anything else – you may not offer them as a sacrifice to the Lord your God.'
EXEC add_BibleVerse @BibleId, 105015022, N'You may eat it in your villages, whether you are ritually impure or clean, just as you would eat a gazelle or an ibex.'
EXEC add_BibleVerse @BibleId, 105015023, N'However, you must not eat its blood; you must pour it out on the ground like water.'
EXEC add_BibleVerse @BibleId, 105016001, N'Observe the month Abib and keep the Passover to the Lord your God, for in that month he brought you out of Egypt by night.'
EXEC add_BibleVerse @BibleId, 105016002, N'You must sacrifice the Passover animal (from the flock or the herd) to the Lord your God in the place where he chooses to locate his name.'
EXEC add_BibleVerse @BibleId, 105016003, N'You must not eat any yeast with it; for seven days you must eat bread made without yeast, symbolic of affliction, for you came out of Egypt hurriedly. You must do this so you will remember for the rest of your life the day you came out of the land of Egypt.'
EXEC add_BibleVerse @BibleId, 105016004, N'There must not be a scrap of yeast within your land for seven days, nor can any of the meat you sacrifice on the evening of the first day remain until the next morning.'
EXEC add_BibleVerse @BibleId, 105016005, N'You may not sacrifice the Passover in just any of your villages that the Lord your God is giving you,'
EXEC add_BibleVerse @BibleId, 105016006, N'but you must sacrifice it in the evening in the place where he chooses to locate his name, at sunset, the time of day you came out of Egypt.'
EXEC add_BibleVerse @BibleId, 105016007, N'You must cook and eat it in the place the Lord your God chooses; you may return the next morning to your tents.'
EXEC add_BibleVerse @BibleId, 105016008, N'You must eat bread made without yeast for six days. The seventh day you are to hold an assembly for the Lord your God; you must not do any work on that day.'
EXEC add_BibleVerse @BibleId, 105016009, N'You must count seven weeks; you must begin to count them from the time you begin to harvest the standing grain.'
EXEC add_BibleVerse @BibleId, 105016010, N'Then you are to celebrate the Festival of Weeks before the Lord your God with the voluntary offering that you will bring, in proportion to how he has blessed you.'
EXEC add_BibleVerse @BibleId, 105016011, N'You shall rejoice before him – you, your son, your daughter, your male and female slaves, the Levites in your villages, the resident foreigners, the orphans, and the widows among you – in the place where the Lord chooses to locate his name.'
EXEC add_BibleVerse @BibleId, 105016012, N'Furthermore, remember that you were a slave in Egypt, and so be careful to observe these statutes.'
EXEC add_BibleVerse @BibleId, 105016013, N'You must celebrate the Festival of Temporary Shelters for seven days, at the time of the grain and grape harvest.'
EXEC add_BibleVerse @BibleId, 105016014, N'You are to rejoice in your festival, you, your son, your daughter, your male and female slaves, the Levites, the resident foreigners, the orphans, and the widows who are in your villages.'
EXEC add_BibleVerse @BibleId, 105016015, N'You are to celebrate the festival seven days before the Lord your God in the place he chooses, for he will bless you in all your productivity and in whatever you do; so you will indeed rejoice!'
EXEC add_BibleVerse @BibleId, 105016016, N'Three times a year all your males must appear before the Lord your God in the place he chooses for the Festival of Unleavened Bread, the Festival of Weeks, and the Festival of Temporary Shelters; and they must not appear before him empty-handed.'
EXEC add_BibleVerse @BibleId, 105016017, N'Every one of you must give as you are able, according to the blessing of the Lord your God that he has given you.'
EXEC add_BibleVerse @BibleId, 105016018, N'You must appoint judges and civil servants for each tribe in all your villages that the Lord your God is giving you, and they must judge the people fairly.'
EXEC add_BibleVerse @BibleId, 105016019, N'You must not pervert justice or show favor. Do not take a bribe, for bribes blind the eyes of the wise and distort the words of the righteous.'
EXEC add_BibleVerse @BibleId, 105016020, N'You must pursue justice alone so that you may live and inherit the land the Lord your God is giving you.'
EXEC add_BibleVerse @BibleId, 105016021, N'You must not plant any kind of tree as a sacred Asherah pole near the altar of the Lord your God which you build for yourself.'
EXEC add_BibleVerse @BibleId, 105016022, N'You must not erect a sacred pillar, a thing the Lord your God detests.'
EXEC add_BibleVerse @BibleId, 105017001, N'You must not sacrifice to him a bull or sheep that has a blemish or any other defect, because that is considered offensive to the Lord your God.'
EXEC add_BibleVerse @BibleId, 105017002, N'Suppose a man or woman is discovered among you – in one of your villages that the Lord your God is giving you – who sins before the Lord your God and breaks his covenant'
EXEC add_BibleVerse @BibleId, 105017003, N'by serving other gods and worshiping them – the sun, moon, or any other heavenly bodies which I have not permitted you to worship.'
EXEC add_BibleVerse @BibleId, 105017004, N'When it is reported to you and you hear about it, you must investigate carefully. If it is indeed true that such a disgraceful thing is being done in Israel,'
EXEC add_BibleVerse @BibleId, 105017005, N'you must bring to your city gates that man or woman who has done this wicked thing – that very man or woman – and you must stone that person to death.'
EXEC add_BibleVerse @BibleId, 105017006, N'At the testimony of two or three witnesses they must be executed. They cannot be put to death on the testimony of only one witness.'
EXEC add_BibleVerse @BibleId, 105017007, N'The witnesses must be first to begin the execution, and then all the people are to join in afterward. In this way you will purge evil from among you.'
EXEC add_BibleVerse @BibleId, 105017008, N'If a matter is too difficult for you to judge – bloodshed, legal claim, or assault – matters of controversy in your villages – you must leave there and go up to the place the Lord your God chooses.'
EXEC add_BibleVerse @BibleId, 105017009, N'You will go to the Levitical priests and the judge in office in those days and seek a solution; they will render a verdict.'
EXEC add_BibleVerse @BibleId, 105017010, N'You must then do as they have determined at that place the Lord chooses. Be careful to do just as you are taught.'
EXEC add_BibleVerse @BibleId, 105017011, N'You must do what you are instructed, and the verdict they pronounce to you, without fail. Do not deviate right or left from what they tell you.'
EXEC add_BibleVerse @BibleId, 105017012, N'The person who pays no attention to the priest currently serving the Lord your God there, or to the verdict – that person must die, so that you may purge evil from Israel.'
EXEC add_BibleVerse @BibleId, 105017013, N'Then all the people will hear and be afraid, and not be so presumptuous again.'
EXEC add_BibleVerse @BibleId, 105017014, N'When you come to the land the Lord your God is giving you and take it over and live in it and then say, “I will select a king like all the nations surrounding me,”'
EXEC add_BibleVerse @BibleId, 105017015, N'you must select without fail a king whom the Lord your God chooses. From among your fellow citizens you must appoint a king – you may not designate a foreigner who is not one of your fellow Israelites.'
EXEC add_BibleVerse @BibleId, 105017016, N'Moreover, he must not accumulate horses for himself or allow the people to return to Egypt to do so, for the Lord has said you must never again return that way.'
EXEC add_BibleVerse @BibleId, 105017017, N'Furthermore, he must not marry many wives lest his affections turn aside, and he must not accumulate much silver and gold.'
EXEC add_BibleVerse @BibleId, 105017018, N'When he sits on his royal throne he must make a copy of this law on a scroll given to him by the Levitical priests.'
EXEC add_BibleVerse @BibleId, 105017019, N'It must be with him constantly and he must read it as long as he lives, so that he may learn to revere the Lord his God and observe all the words of this law and these statutes and carry them out.'
EXEC add_BibleVerse @BibleId, 105017020, N'Then he will not exalt himself above his fellow citizens or turn from the commandments to the right or left, and he and his descendants will enjoy many years ruling over his kingdom in Israel.'
EXEC add_BibleVerse @BibleId, 105018001, N'The Levitical priests – indeed, the entire tribe of Levi – will have no allotment or inheritance with Israel; they may eat the burnt offerings of the Lord and of his inheritance.'
EXEC add_BibleVerse @BibleId, 105018002, N'They will have no inheritance in the midst of their fellow Israelites; the Lord alone is their inheritance, just as he had told them.'
EXEC add_BibleVerse @BibleId, 105018003, N'This shall be the priests’ fair allotment from the people who offer sacrifices, whether bull or sheep – they must give to the priest the shoulder, the jowls, and the stomach.'
EXEC add_BibleVerse @BibleId, 105018004, N'You must give them the best of your grain, new wine, and olive oil, as well as the best of your wool when you shear your flocks.'
EXEC add_BibleVerse @BibleId, 105018005, N'For the Lord your God has chosen them and their sons from all your tribes to stand and serve in his name permanently.'
EXEC add_BibleVerse @BibleId, 105018006, N'Suppose a Levite comes by his own free will from one of your villages, from any part of Israel where he is living, to the place the Lord chooses'
EXEC add_BibleVerse @BibleId, 105018007, N'and serves in the name of the Lord his God like his fellow Levites who stand there before the Lord.'
EXEC add_BibleVerse @BibleId, 105018008, N'He must eat the same share they do, despite any profits he may gain from the sale of his family’s inheritance.'
EXEC add_BibleVerse @BibleId, 105018009, N'When you enter the land the Lord your God is giving you, you must not learn the abhorrent practices of those nations.'
EXEC add_BibleVerse @BibleId, 105018010, N'There must never be found among you anyone who sacrifices his son or daughter in the fire, anyone who practices divination, an omen reader, a soothsayer, a sorcerer,'
EXEC add_BibleVerse @BibleId, 105018011, N'one who casts spells, one who conjures up spirits, a practitioner of the occult, or a necromancer.'
EXEC add_BibleVerse @BibleId, 105018012, N'Whoever does these things is abhorrent to the Lord and because of these detestable things the Lord your God is about to drive them out from before you.'
EXEC add_BibleVerse @BibleId, 105018013, N'You must be blameless before the Lord your God.'
EXEC add_BibleVerse @BibleId, 105018014, N'Those nations that you are about to dispossess listen to omen readers and diviners, but the Lord your God has not given you permission to do such things.'
EXEC add_BibleVerse @BibleId, 105018015, N'The Lord your God will raise up for you a prophet like me from among you – from your fellow Israelites; you must listen to him.'
EXEC add_BibleVerse @BibleId, 105018016, N'This accords with what happened at Horeb in the day of the assembly. You asked the Lord your God: “Please do not make us hear the voice of the Lord our God any more or see this great fire any more lest we die.”'
EXEC add_BibleVerse @BibleId, 105018017, N'The Lord then said to me, “What they have said is good.'
EXEC add_BibleVerse @BibleId, 105018018, N'I will raise up a prophet like you for them from among their fellow Israelites. I will put my words in his mouth and he will speak to them whatever I command.'
EXEC add_BibleVerse @BibleId, 105018019, N'I will personally hold responsible anyone who then pays no attention to the words that prophet speaks in my name.'
EXEC add_BibleVerse @BibleId, 105018020, N'“But if any prophet presumes to speak anything in my name that I have not authorized him to speak, or speaks in the name of other gods, that prophet must die.'
EXEC add_BibleVerse @BibleId, 105018021, N'Now if you say to yourselves, ‘How can we tell that a message is not from the Lord?’ –'
EXEC add_BibleVerse @BibleId, 105018022, N'whenever a prophet speaks in my name and the prediction is not fulfilled, then I have not spoken it; the prophet has presumed to speak it, so you need not fear him.”'
EXEC add_BibleVerse @BibleId, 105019001, N'When the Lord your God destroys the nations whose land he is about to give you and you dispossess them and settle in their cities and houses,'
EXEC add_BibleVerse @BibleId, 105019002, N'you must set apart for yourselves three cities in the middle of your land that the Lord your God is giving you as a possession.'
EXEC add_BibleVerse @BibleId, 105019003, N'You shall build a roadway and divide into thirds the whole extent of your land that the Lord your God is providing as your inheritance; anyone who kills another person should flee to the closest of these cities.'
EXEC add_BibleVerse @BibleId, 105019004, N'Now this is the law pertaining to one who flees there in order to live, if he has accidentally killed another without hating him at the time of the accident.'
EXEC add_BibleVerse @BibleId, 105019005, N'Suppose he goes with someone else to the forest to cut wood and when he raises the ax to cut the tree, the ax head flies loose from the handle and strikes his fellow worker so hard that he dies. The person responsible may then flee to one of these cities to save himself.'
EXEC add_BibleVerse @BibleId, 105019006, N'Otherwise the blood avenger will chase after the killer in the heat of his anger, eventually overtake him, and kill him, though this is not a capital case since he did not hate him at the time of the accident.'
EXEC add_BibleVerse @BibleId, 105019007, N'Therefore, I am commanding you to set apart for yourselves three cities.'
EXEC add_BibleVerse @BibleId, 105019008, N'If the Lord your God enlarges your borders as he promised your ancestors and gives you all the land he pledged to them,'
EXEC add_BibleVerse @BibleId, 105019009, N'and then you are careful to observe all these commandments I am giving you today (namely, to love the Lord your God and to always walk in his ways), then you must add three more cities to these three.'
EXEC add_BibleVerse @BibleId, 105019010, N'You must not shed innocent blood in your land that the Lord your God is giving you as an inheritance, for that would make you guilty.'
EXEC add_BibleVerse @BibleId, 105019011, N'However, suppose a person hates someone else and stalks him, attacks him, kills him, and then flees to one of these cities.'
EXEC add_BibleVerse @BibleId, 105019012, N'The elders of his own city must send for him and remove him from there to deliver him over to the blood avenger to die.'
EXEC add_BibleVerse @BibleId, 105019013, N'You must not pity him, but purge out the blood of the innocent from Israel, so that it may go well with you.'
EXEC add_BibleVerse @BibleId, 105019014, N'You must not encroach on your neighbor’s property, which will have been defined in the inheritance you will obtain in the land the Lord your God is giving you.'
EXEC add_BibleVerse @BibleId, 105019015, N'A single witness may not testify against another person for any trespass or sin that he commits. A matter may be legally established only on the testimony of two or three witnesses.'
EXEC add_BibleVerse @BibleId, 105019016, N'If a false witness testifies against another person and accuses him of a crime,'
EXEC add_BibleVerse @BibleId, 105019017, N'then both parties to the controversy must stand before the Lord, that is, before the priests and judges who will be in office in those days.'
EXEC add_BibleVerse @BibleId, 105019018, N'The judges will thoroughly investigate the matter, and if the witness should prove to be false and to have given false testimony against the accused,'
EXEC add_BibleVerse @BibleId, 105019019, N'you must do to him what he had intended to do to the accused. In this way you will purge evil from among you.'
EXEC add_BibleVerse @BibleId, 105019020, N'The rest of the people will hear and become afraid to keep doing such evil among you.'
EXEC add_BibleVerse @BibleId, 105019021, N'You must not show pity; the principle will be a life for a life, an eye for an eye, a tooth for a tooth, a hand for a hand, and a foot for a foot.'
EXEC add_BibleVerse @BibleId, 105020001, N'When you go to war against your enemies and see chariotry and troops who outnumber you, do not be afraid of them, for the Lord your God, who brought you up out of the land of Egypt, is with you.'
EXEC add_BibleVerse @BibleId, 105020002, N'As you move forward for battle, the priest will approach and say to the soldiers,'
EXEC add_BibleVerse @BibleId, 105020003, N'“Listen, Israel! Today you are moving forward to do battle with your enemies. Do not be fainthearted. Do not fear and tremble or be terrified because of them,'
EXEC add_BibleVerse @BibleId, 105020004, N'for the Lord your God goes with you to fight on your behalf against your enemies to give you victory.”'
EXEC add_BibleVerse @BibleId, 105020005, N'Moreover, the officers are to say to the troops, “Who among you has built a new house and not dedicated it? He may go home, lest he die in battle and someone else dedicate it.'
EXEC add_BibleVerse @BibleId, 105020006, N'Or who among you has planted a vineyard and not benefited from it? He may go home, lest he die in battle and someone else benefit from it.'
EXEC add_BibleVerse @BibleId, 105020007, N'Or who among you has become engaged to a woman but has not married her? He may go home, lest he die in battle and someone else marry her.”'
EXEC add_BibleVerse @BibleId, 105020008, N'In addition, the officers are to say to the troops, “Who among you is afraid and fainthearted? He may go home so that he will not make his fellow soldier’s heart as fearful as his own.”'
EXEC add_BibleVerse @BibleId, 105020009, N'Then, when the officers have finished speaking, they must appoint unit commanders to lead the troops.'
EXEC add_BibleVerse @BibleId, 105020010, N'When you approach a city to wage war against it, offer it terms of peace.'
EXEC add_BibleVerse @BibleId, 105020011, N'If it accepts your terms and submits to you, all the people found in it will become your slaves.'
EXEC add_BibleVerse @BibleId, 105020012, N'If it does not accept terms of peace but makes war with you, then you are to lay siege to it.'
EXEC add_BibleVerse @BibleId, 105020013, N'The Lord your God will deliver it over to you and you must kill every single male by the sword.'
EXEC add_BibleVerse @BibleId, 105020014, N'However, the women, little children, cattle, and anything else in the city – all its plunder – you may take for yourselves as spoil. You may take from your enemies the plunder that the Lord your God has given you.'
EXEC add_BibleVerse @BibleId, 105020015, N'This is how you are to deal with all those cities located far from you, those that do not belong to these nearby nations.'
EXEC add_BibleVerse @BibleId, 105020016, N'As for the cities of these peoples that the Lord your God is going to give you as an inheritance, you must not allow a single living thing to survive.'
EXEC add_BibleVerse @BibleId, 105020017, N'Instead you must utterly annihilate them – the Hittites, Amorites, Canaanites, Perizzites, Hivites, and Jebusites – just as the Lord your God has commanded you,'
EXEC add_BibleVerse @BibleId, 105020018, N'so that they cannot teach you all the abhorrent ways they worship their gods, causing you to sin against the Lord your God.'
EXEC add_BibleVerse @BibleId, 105020019, N'If you besiege a city for a long time while attempting to capture it, you must not chop down its trees, for you may eat fruit from them and should not cut them down. A tree in the field is not human that you should besiege it!'
EXEC add_BibleVerse @BibleId, 105020020, N'However, you may chop down any tree you know is not suitable for food, and you may use it to build siege works against the city that is making war with you until that city falls.'
EXEC add_BibleVerse @BibleId, 105021001, N'If a homicide victim should be found lying in a field in the land the Lord your God is giving you, and no one knows who killed him,'
EXEC add_BibleVerse @BibleId, 105021002, N'your elders and judges must go out and measure how far it is to the cities in the vicinity of the corpse.'
EXEC add_BibleVerse @BibleId, 105021003, N'Then the elders of the city nearest to the corpse must take from the herd a heifer that has not been worked – that has never pulled with the yoke –'
EXEC add_BibleVerse @BibleId, 105021004, N'and bring the heifer down to a wadi with flowing water, to a valley that is neither plowed nor sown. There at the wadi they are to break the heifer’s neck.'
EXEC add_BibleVerse @BibleId, 105021005, N'Then the Levitical priests will approach (for the Lord your God has chosen them to serve him and to pronounce blessings in his name, and to decide every judicial verdict )'
EXEC add_BibleVerse @BibleId, 105021006, N'and all the elders of that city nearest the corpse must wash their hands over the heifer whose neck was broken in the valley.'
EXEC add_BibleVerse @BibleId, 105021007, N'Then they must proclaim, “Our hands have not spilled this blood, nor have we witnessed the crime.'
EXEC add_BibleVerse @BibleId, 105021008, N'Do not blame your people Israel whom you redeemed, O Lord, and do not hold them accountable for the bloodshed of an innocent person.” Then atonement will be made for the bloodshed.'
EXEC add_BibleVerse @BibleId, 105021009, N'In this manner you will purge out the guilt of innocent blood from among you, for you must do what is right before the Lord.'
EXEC add_BibleVerse @BibleId, 105021010, N'When you go out to do battle with your enemies and the Lord your God allows you to prevail and you take prisoners,'
EXEC add_BibleVerse @BibleId, 105021011, N'if you should see among them an attractive woman whom you wish to take as a wife,'
EXEC add_BibleVerse @BibleId, 105021012, N'you may bring her back to your house. She must shave her head, trim her nails,'
EXEC add_BibleVerse @BibleId, 105021013, N'discard the clothing she was wearing when captured, and stay in your house, lamenting for her father and mother for a full month. After that you may have sexual relations with her and become her husband and she your wife.'
EXEC add_BibleVerse @BibleId, 105021014, N'If you are not pleased with her, then you must let her go where she pleases. You cannot in any case sell her; you must not take advantage of her, since you have already humiliated her.'
EXEC add_BibleVerse @BibleId, 105021015, N'Suppose a man has two wives, one whom he loves more than the other, and they both bear him sons, with the firstborn being the child of the less loved wife.'
EXEC add_BibleVerse @BibleId, 105021016, N'In the day he divides his inheritance he must not appoint as firstborn the son of the favorite wife in place of the other wife’s son who is actually the firstborn.'
EXEC add_BibleVerse @BibleId, 105021017, N'Rather, he must acknowledge the son of the less loved wife as firstborn and give him the double portion of all he has, for that son is the beginning of his father’s procreative power – to him should go the right of the firstborn.'
EXEC add_BibleVerse @BibleId, 105021018, N'If a person has a stubborn, rebellious son who pays no attention to his father or mother, and they discipline him to no avail,'
EXEC add_BibleVerse @BibleId, 105021019, N'his father and mother must seize him and bring him to the elders at the gate of his city.'
EXEC add_BibleVerse @BibleId, 105021020, N'They must declare to the elders of his city, “Our son is stubborn and rebellious and pays no attention to what we say – he is a glutton and drunkard.”'
EXEC add_BibleVerse @BibleId, 105021021, N'Then all the men of his city must stone him to death. In this way you will purge out wickedness from among you, and all Israel will hear about it and be afraid.'
EXEC add_BibleVerse @BibleId, 105021022, N'If a person commits a sin punishable by death and is executed, and you hang the corpse on a tree,'
EXEC add_BibleVerse @BibleId, 105021023, N'his body must not remain all night on the tree; instead you must make certain you bury him that same day, for the one who is left exposed on a tree is cursed by God. You must not defile your land which the Lord your God is giving you as an inheritance.'
EXEC add_BibleVerse @BibleId, 105022001, N'When you see your neighbor’s ox or sheep going astray, do not ignore it; you must return it without fail to your neighbor.'
EXEC add_BibleVerse @BibleId, 105022002, N'If the owner does not live near you or you do not know who the owner is, then you must corral the animal at your house and let it stay with you until the owner looks for it; then you must return it to him.'
EXEC add_BibleVerse @BibleId, 105022003, N'You shall do the same to his donkey, his clothes, or anything else your neighbor has lost and you have found; you must not refuse to get involved.'
EXEC add_BibleVerse @BibleId, 105022004, N'When you see your neighbor’s donkey or ox fallen along the road, do not ignore it; instead, you must be sure to help him get the animal on its feet again.'
EXEC add_BibleVerse @BibleId, 105022005, N'A woman must not wear men’s clothing, nor should a man dress up in women’s clothing, for anyone who does this is offensive to the Lord your God.'
EXEC add_BibleVerse @BibleId, 105022006, N'If you happen to notice a bird’s nest along the road, whether in a tree or on the ground, and there are chicks or eggs with the mother bird sitting on them, you must not take the mother from the young.'
EXEC add_BibleVerse @BibleId, 105022007, N'You must be sure to let the mother go, but you may take the young for yourself. Do this so that it may go well with you and you may have a long life.'
EXEC add_BibleVerse @BibleId, 105022008, N'If you build a new house, you must construct a guard rail around your roof to avoid being culpable in the event someone should fall from it.'
EXEC add_BibleVerse @BibleId, 105022009, N'You must not plant your vineyard with two kinds of seed; otherwise the entire yield, both of the seed you plant and the produce of the vineyard, will be defiled.'
EXEC add_BibleVerse @BibleId, 105022010, N'You must not plow with an ox and a donkey harnessed together.'
EXEC add_BibleVerse @BibleId, 105022011, N'You must not wear clothing made with wool and linen meshed together.'
EXEC add_BibleVerse @BibleId, 105022012, N'You shall make yourselves tassels for the four corners of the clothing you wear.'
EXEC add_BibleVerse @BibleId, 105022013, N'Suppose a man marries a woman, has sexual relations with her, and then rejects her,'
EXEC add_BibleVerse @BibleId, 105022014, N'accusing her of impropriety and defaming her reputation by saying, “I married this woman but when I had sexual relations with her I discovered she was not a virgin!”'
EXEC add_BibleVerse @BibleId, 105022015, N'Then the father and mother of the young woman must produce the evidence of virginity for the elders of the city at the gate.'
EXEC add_BibleVerse @BibleId, 105022016, N'The young woman’s father must say to the elders, “I gave my daughter to this man and he has rejected her.'
EXEC add_BibleVerse @BibleId, 105022017, N'Moreover, he has raised accusations of impropriety by saying, ‘I discovered your daughter was not a virgin,’ but this is the evidence of my daughter’s virginity!” The cloth must then be spread out before the city’s elders.'
EXEC add_BibleVerse @BibleId, 105022018, N'The elders of that city must then seize the man and punish him.'
EXEC add_BibleVerse @BibleId, 105022019, N'They will fine him one hundred shekels of silver and give them to the young woman’s father, for the man who made the accusation ruined the reputation of an Israelite virgin. She will then become his wife and he may never divorce her as long as he lives.'
EXEC add_BibleVerse @BibleId, 105022020, N'But if the accusation is true and the young woman was not a virgin,'
EXEC add_BibleVerse @BibleId, 105022021, N'the men of her city must bring the young woman to the door of her father’s house and stone her to death, for she has done a disgraceful thing in Israel by behaving like a prostitute while living in her father’s house. In this way you will purge evil from among you.'
EXEC add_BibleVerse @BibleId, 105022022, N'If a man is caught having sexual relations with a married woman both the man who had relations with the woman and the woman herself must die; in this way you will purge evil from Israel.'
EXEC add_BibleVerse @BibleId, 105022023, N'If a virgin is engaged to a man and another man meets her in the city and has sexual relations with her,'
EXEC add_BibleVerse @BibleId, 105022024, N'you must bring the two of them to the gate of that city and stone them to death, the young woman because she did not cry out though in the city and the man because he violated his neighbor’s fiancée; in this way you will purge evil from among you.'
EXEC add_BibleVerse @BibleId, 105022025, N'But if the man came across the engaged woman in the field and overpowered her and raped her, then only the rapist must die.'
EXEC add_BibleVerse @BibleId, 105022026, N'You must not do anything to the young woman – she has done nothing deserving of death. This case is the same as when someone attacks another person and murders him,'
EXEC add_BibleVerse @BibleId, 105022027, N'for the man met her in the field and the engaged woman cried out, but there was no one to rescue her.'
EXEC add_BibleVerse @BibleId, 105022028, N'Suppose a man comes across a virgin who is not engaged and overpowers and rapes her and they are discovered.'
EXEC add_BibleVerse @BibleId, 105022029, N'The man who has raped her must pay her father fifty shekels of silver and she must become his wife because he has violated her; he may never divorce her as long as he lives.'
EXEC add_BibleVerse @BibleId, 105022030, N'A man may not marry his father’s former wife and in this way dishonor his father.'
EXEC add_BibleVerse @BibleId, 105023001, N'A man with crushed or severed genitals may not enter the assembly of the Lord.'
EXEC add_BibleVerse @BibleId, 105023002, N'A person of illegitimate birth may not enter the assembly of the Lord; to the tenth generation no one related to him may do so.'
EXEC add_BibleVerse @BibleId, 105023003, N'An Ammonite or Moabite may not enter the assembly of the Lord; to the tenth generation none of their descendants shall ever do so,'
EXEC add_BibleVerse @BibleId, 105023004, N'for they did not meet you with food and water on the way as you came from Egypt, and furthermore, they hired Balaam son of Beor of Pethor in Aram Naharaim to curse you.'
EXEC add_BibleVerse @BibleId, 105023005, N'But the Lord your God refused to listen to Balaam and changed the curse to a blessing, for the Lord your God loves you.'
EXEC add_BibleVerse @BibleId, 105023006, N'You must not seek peace and prosperity for them through all the ages to come.'
EXEC add_BibleVerse @BibleId, 105023007, N'You must not hate an Edomite, for he is your relative; you must not hate an Egyptian, for you lived as a foreigner in his land.'
EXEC add_BibleVerse @BibleId, 105023008, N'Children of the third generation born to them may enter the assembly of the Lord.'
EXEC add_BibleVerse @BibleId, 105023009, N'When you go out as an army against your enemies, guard yourselves against anything impure.'
EXEC add_BibleVerse @BibleId, 105023010, N'If there is someone among you who is impure because of some nocturnal emission, he must leave the camp; he may not reenter it immediately.'
EXEC add_BibleVerse @BibleId, 105023011, N'When evening arrives he must wash himself with water and then at sunset he may reenter the camp.'
EXEC add_BibleVerse @BibleId, 105023012, N'You are to have a place outside the camp to serve as a latrine.'
EXEC add_BibleVerse @BibleId, 105023013, N'You must have a spade among your other equipment and when you relieve yourself outside you must dig a hole with the spade and then turn and cover your excrement.'
EXEC add_BibleVerse @BibleId, 105023014, N'For the Lord your God walks about in the middle of your camp to deliver you and defeat your enemies for you. Therefore your camp should be holy, so that he does not see anything indecent among you and turn away from you.'
EXEC add_BibleVerse @BibleId, 105023015, N'You must not return an escaped slave to his master when he has run away to you.'
EXEC add_BibleVerse @BibleId, 105023016, N'Indeed, he may live among you in any place he chooses, in whichever of your villages he prefers; you must not oppress him.'
EXEC add_BibleVerse @BibleId, 105023017, N'There must never be a sacred prostitute among the young women of Israel nor a sacred male prostitute among the young men of Israel.'
EXEC add_BibleVerse @BibleId, 105023018, N'You must never bring the pay of a female prostitute or the wage of a male prostitute into the temple of the Lord your God in fulfillment of any vow, for both of these are abhorrent to the Lord your God.'
EXEC add_BibleVerse @BibleId, 105023019, N'You must not charge interest on a loan to your fellow Israelite, whether on money, food, or anything else that has been loaned with interest.'
EXEC add_BibleVerse @BibleId, 105023020, N'You may lend with interest to a foreigner, but not to your fellow Israelite; if you keep this command the Lord your God will bless you in all you undertake in the land you are about to enter to possess.'
EXEC add_BibleVerse @BibleId, 105023021, N'When you make a vow to the Lord your God you must not delay in fulfilling it, for otherwise he will surely hold you accountable as a sinner.'
EXEC add_BibleVerse @BibleId, 105023022, N'If you refrain from making a vow, it will not be sinful.'
EXEC add_BibleVerse @BibleId, 105023023, N'Whatever you vow, you must be careful to do what you have promised, such as what you have vowed to the Lord your God as a freewill offering.'
EXEC add_BibleVerse @BibleId, 105023024, N'When you enter the vineyard of your neighbor you may eat as many grapes as you please, but you must not take away any in a container.'
EXEC add_BibleVerse @BibleId, 105023025, N'When you go into the ripe grain fields of your neighbor you may pluck off the kernels with your hand, but you must not use a sickle on your neighbor’s ripe grain.'
EXEC add_BibleVerse @BibleId, 105024001, N'If a man marries a woman and she does not please him because he has found something offensive in her, then he may draw up a divorce document, give it to her, and evict her from his house.'
EXEC add_BibleVerse @BibleId, 105024002, N'When she has left him she may go and become someone else’s wife.'
EXEC add_BibleVerse @BibleId, 105024003, N'If the second husband rejects her and then divorces her, gives her the papers, and evicts her from his house, or if the second husband who married her dies,'
EXEC add_BibleVerse @BibleId, 105024004, N'her first husband who divorced her is not permitted to remarry her after she has become ritually impure, for that is offensive to the Lord. You must not bring guilt on the land which the Lord your God is giving you as an inheritance.'
EXEC add_BibleVerse @BibleId, 105024005, N'When a man is newly married, he need not go into the army nor be obligated in any way; he must be free to stay at home for a full year and bring joy to the wife he has married.'
EXEC add_BibleVerse @BibleId, 105024006, N'One must not take either lower or upper millstones as security on a loan, for that is like taking a life itself as security.'
EXEC add_BibleVerse @BibleId, 105024007, N'If a man is found kidnapping a person from among his fellow Israelites, and regards him as mere property and sells him, that kidnapper must die. In this way you will purge evil from among you.'
EXEC add_BibleVerse @BibleId, 105024008, N'Be careful during an outbreak of leprosy to follow precisely all that the Levitical priests instruct you; as I have commanded them, so you should do.'
EXEC add_BibleVerse @BibleId, 105024009, N'Remember what the Lord your God did to Miriam along the way after you left Egypt.'
EXEC add_BibleVerse @BibleId, 105024010, N'When you make any kind of loan to your neighbor, you may not go into his house to claim what he is offering as security.'
EXEC add_BibleVerse @BibleId, 105024011, N'You must stand outside and the person to whom you are making the loan will bring out to you what he is offering as security.'
EXEC add_BibleVerse @BibleId, 105024012, N'If the person is poor you may not use what he gives you as security for a covering.'
EXEC add_BibleVerse @BibleId, 105024013, N'You must by all means return to him at sunset the item he gave you as security so that he may sleep in his outer garment and bless you for it; it will be considered a just deed by the Lord your God.'
EXEC add_BibleVerse @BibleId, 105024014, N'You must not oppress a lowly and poor servant, whether one from among your fellow Israelites or from the resident foreigners who are living in your land and villages.'
EXEC add_BibleVerse @BibleId, 105024015, N'You must pay his wage that very day before the sun sets, for he is poor and his life depends on it. Otherwise he will cry out to the Lord against you, and you will be guilty of sin.'
EXEC add_BibleVerse @BibleId, 105024016, N'Fathers must not be put to death for what their children do, nor children for what their fathers do; each must be put to death for his own sin.'
EXEC add_BibleVerse @BibleId, 105024017, N'You must not pervert justice due a resident foreigner or an orphan, or take a widow’s garment as security for a loan.'
EXEC add_BibleVerse @BibleId, 105024018, N'Remember that you were slaves in Egypt and that the Lord your God redeemed you from there; therefore I am commanding you to do all this.'
EXEC add_BibleVerse @BibleId, 105024019, N'Whenever you reap your harvest in your field and leave some unraked grain there, you must not return to get it; it should go to the resident foreigner, orphan, and widow so that the Lord your God may bless all the work you do.'
EXEC add_BibleVerse @BibleId, 105024020, N'When you beat your olive tree you must not repeat the procedure; the remaining olives belong to the resident foreigner, orphan, and widow.'
EXEC add_BibleVerse @BibleId, 105024021, N'When you gather the grapes of your vineyard you must not do so a second time; they should go to the resident foreigner, orphan, and widow.'
EXEC add_BibleVerse @BibleId, 105024022, N'Remember that you were slaves in the land of Egypt; therefore, I am commanding you to do all this.'
EXEC add_BibleVerse @BibleId, 105025001, N'If controversy arises between people, they should go to court for judgment. When the judges hear the case, they shall exonerate the innocent but condemn the guilty.'
EXEC add_BibleVerse @BibleId, 105025002, N'Then, if the guilty person is sentenced to a beating, the judge shall force him to lie down and be beaten in his presence with the number of blows his wicked behavior deserves.'
EXEC add_BibleVerse @BibleId, 105025003, N'The judge may sentence him to forty blows, but no more. If he is struck with more than these, you might view your fellow Israelite with contempt.'
EXEC add_BibleVerse @BibleId, 105025004, N'You must not muzzle your ox when it is treading grain.'
EXEC add_BibleVerse @BibleId, 105025005, N'If brothers live together and one of them dies without having a son, the dead man’s wife must not remarry someone outside the family. Instead, her late husband’s brother must go to her, marry her, and perform the duty of a brother-in-law.'
EXEC add_BibleVerse @BibleId, 105025006, N'Then the first son she bears will continue the name of the dead brother, thus preventing his name from being blotted out of Israel.'
EXEC add_BibleVerse @BibleId, 105025007, N'But if the man does not want to marry his brother’s widow, then she must go to the elders at the town gate and say, “My husband’s brother refuses to preserve his brother’s name in Israel; he is unwilling to perform the duty of a brother-in-law to me!”'
EXEC add_BibleVerse @BibleId, 105025008, N'Then the elders of his city must summon him and speak to him. If he persists, saying, “I don’t want to marry her,”'
EXEC add_BibleVerse @BibleId, 105025009, N'then his sister-in-law must approach him in view of the elders, remove his sandal from his foot, and spit in his face. She will then respond, “Thus may it be done to any man who does not maintain his brother’s family line!”'
EXEC add_BibleVerse @BibleId, 105025010, N'His family name will be referred to in Israel as “the family of the one whose sandal was removed.”'
EXEC add_BibleVerse @BibleId, 105025011, N'If two men get into a hand-to-hand fight, and the wife of one of them gets involved to help her husband against his attacker, and she reaches out her hand and grabs his genitals,'
EXEC add_BibleVerse @BibleId, 105025012, N'then you must cut off her hand – do not pity her.'
EXEC add_BibleVerse @BibleId, 105025013, N'You must not have in your bag different stone weights, a heavy and a light one.'
EXEC add_BibleVerse @BibleId, 105025014, N'You must not have in your house different measuring containers, a large and a small one.'
EXEC add_BibleVerse @BibleId, 105025015, N'You must have an accurate and correct stone weight and an accurate and correct measuring container, so that your life may be extended in the land the Lord your God is about to give you.'
EXEC add_BibleVerse @BibleId, 105025016, N'For anyone who acts dishonestly in these ways is abhorrent to the Lord your God.'
EXEC add_BibleVerse @BibleId, 105025017, N'Remember what the Amalekites did to you on your way from Egypt,'
EXEC add_BibleVerse @BibleId, 105025018, N'how they met you along the way and cut off all your stragglers in the rear of the march when you were exhausted and tired; they were unafraid of God.'
EXEC add_BibleVerse @BibleId, 105025019, N'So when the Lord your God gives you relief from all the enemies who surround you in the land he is giving you as an inheritance, you must wipe out the memory of the Amalekites from under heaven – do not forget!'
EXEC add_BibleVerse @BibleId, 105026001, N'When you enter the land that the Lord your God is giving you as an inheritance, and you occupy it and live in it,'
EXEC add_BibleVerse @BibleId, 105026002, N'you must take the first of all the ground’s produce you harvest from the land the Lord your God is giving you, place it in a basket, and go to the place where he chooses to locate his name.'
EXEC add_BibleVerse @BibleId, 105026003, N'You must go to the priest in office at that time and say to him, “I declare today to the Lord your God that I have come into the land that the Lord promised to our ancestors to give us.”'
EXEC add_BibleVerse @BibleId, 105026004, N'The priest will then take the basket from you and set it before the altar of the Lord your God.'
EXEC add_BibleVerse @BibleId, 105026005, N'Then you must affirm before the Lord your God, “A wandering Aramean was my ancestor, and he went down to Egypt and lived there as a foreigner with a household few in number, but there he became a great, powerful, and numerous people.'
EXEC add_BibleVerse @BibleId, 105026006, N'But the Egyptians mistreated and oppressed us, forcing us to do burdensome labor.'
EXEC add_BibleVerse @BibleId, 105026007, N'So we cried out to the Lord, the God of our ancestors, and he heard us and saw our humiliation, toil, and oppression.'
EXEC add_BibleVerse @BibleId, 105026008, N'Therefore the Lord brought us out of Egypt with tremendous strength and power, as well as with great awe-inspiring signs and wonders.'
EXEC add_BibleVerse @BibleId, 105026009, N'Then he brought us to this place and gave us this land, a land flowing with milk and honey.'
EXEC add_BibleVerse @BibleId, 105026010, N'So now, look! I have brought the first of the ground’s produce that you, Lord, have given me.” Then you must set it down before the Lord your God and worship before him.'
EXEC add_BibleVerse @BibleId, 105026011, N'You will celebrate all the good things that the Lord your God has given you and your family, along with the Levites and the resident foreigners among you.'
EXEC add_BibleVerse @BibleId, 105026012, N'When you finish tithing all your income in the third year (the year of tithing), you must give it to the Levites, the resident foreigners, the orphans, and the widows so that they may eat to their satisfaction in your villages.'
EXEC add_BibleVerse @BibleId, 105026013, N'Then you shall say before the Lord your God, “I have removed the sacred offering from my house and given it to the Levites, the resident foreigners, the orphans, and the widows just as you have commanded me. I have not violated or forgotten your commandments.'
EXEC add_BibleVerse @BibleId, 105026014, N'I have not eaten anything when I was in mourning, or removed any of it while ceremonially unclean, or offered any of it to the dead; I have obeyed you and have done everything you have commanded me.'
EXEC add_BibleVerse @BibleId, 105026015, N'Look down from your holy dwelling place in heaven and bless your people Israel and the land you have given us, just as you promised our ancestors – a land flowing with milk and honey.”'
EXEC add_BibleVerse @BibleId, 105026016, N'Today the Lord your God is commanding you to keep these statutes and ordinances, something you must do with all your heart and soul.'
EXEC add_BibleVerse @BibleId, 105026017, N'Today you have declared the Lord to be your God, and that you will walk in his ways, keep his statutes, commandments, and ordinances, and obey him.'
EXEC add_BibleVerse @BibleId, 105026018, N'And today the Lord has declared you to be his special people (as he already promised you) so you may keep all his commandments.'
EXEC add_BibleVerse @BibleId, 105026019, N'Then he will elevate you above all the nations he has made and you will receive praise, fame, and honor. You will be a people holy to the Lord your God, as he has said.'
EXEC add_BibleVerse @BibleId, 105027001, N'Then Moses and the elders of Israel commanded the people: “Pay attention to all the commandments I am giving you today.'
EXEC add_BibleVerse @BibleId, 105027002, N'When you cross the Jordan River to the land the Lord your God is giving you, you must erect great stones and cover them with plaster.'
EXEC add_BibleVerse @BibleId, 105027003, N'Then you must inscribe on them all the words of this law when you cross over, so that you may enter the land the Lord your God is giving you, a land flowing with milk and honey just as the Lord, the God of your ancestors, said to you.'
EXEC add_BibleVerse @BibleId, 105027004, N'So when you cross the Jordan you must erect on Mount Ebal these stones about which I am commanding you today, and you must cover them with plaster.'
EXEC add_BibleVerse @BibleId, 105027005, N'Then you must build an altar there to the Lord your God, an altar of stones – do not use an iron tool on them.'
EXEC add_BibleVerse @BibleId, 105027006, N'You must build the altar of the Lord your God with whole stones and offer burnt offerings on it to the Lord your God.'
EXEC add_BibleVerse @BibleId, 105027007, N'Also you must offer fellowship offerings and eat them there, rejoicing before the Lord your God.'
EXEC add_BibleVerse @BibleId, 105027008, N'You must inscribe on the stones all the words of this law, making them clear.”'
EXEC add_BibleVerse @BibleId, 105027009, N'Then Moses and the Levitical priests spoke to all Israel: “Be quiet and pay attention, Israel. Today you have become the people of the Lord your God.'
EXEC add_BibleVerse @BibleId, 105027010, N'You must obey him and keep his commandments and statutes that I am giving you today.”'
EXEC add_BibleVerse @BibleId, 105027011, N'Moreover, Moses commanded the people that day:'
EXEC add_BibleVerse @BibleId, 105027012, N'“The following tribes must stand to bless the people on Mount Gerizim when you cross the Jordan: Simeon, Levi, Judah, Issachar, Joseph, and Benjamin.'
EXEC add_BibleVerse @BibleId, 105027013, N'And these other tribes must stand for the curse on Mount Ebal: Reuben, Gad, Asher, Zebulun, Dan, and Naphtali.'
EXEC add_BibleVerse @BibleId, 105027014, N'“The Levites will call out to every Israelite with a loud voice:'
EXEC add_BibleVerse @BibleId, 105027015, N'‘Cursed is the one who makes a carved or metal image – something abhorrent to the Lord, the work of the craftsman – and sets it up in a secret place.’ Then all the people will say, ‘Amen!’'
EXEC add_BibleVerse @BibleId, 105027016, N'‘Cursed is the one who disrespects his father and mother.’ Then all the people will say, ‘Amen!’'
EXEC add_BibleVerse @BibleId, 105027017, N'‘Cursed is the one who moves his neighbor’s boundary marker.’ Then all the people will say, ‘Amen!’'
EXEC add_BibleVerse @BibleId, 105027018, N'‘Cursed is the one who misleads a blind person on the road.’ Then all the people will say, ‘Amen!’'
EXEC add_BibleVerse @BibleId, 105027019, N'‘Cursed is the one who perverts justice for the resident foreigner, the orphan, and the widow.’ Then all the people will say, ‘Amen!’'
EXEC add_BibleVerse @BibleId, 105027020, N'‘Cursed is the one who has sexual relations with his father’s former wife, for he dishonors his father.’ Then all the people will say, ‘Amen!’'
EXEC add_BibleVerse @BibleId, 105027021, N'‘Cursed is the one who commits bestiality.’ Then all the people will say, ‘Amen!’'
EXEC add_BibleVerse @BibleId, 105027022, N'‘Cursed is the one who has sexual relations with his sister, the daughter of either his father or mother.’ Then all the people will say, ‘Amen!’'
EXEC add_BibleVerse @BibleId, 105027023, N'‘Cursed is the one who has sexual relations with his mother-in-law.’ Then all the people will say, ‘Amen!’'
EXEC add_BibleVerse @BibleId, 105027024, N'‘Cursed is the one who kills his neighbor in private.’ Then all the people will say, ‘Amen!’'
EXEC add_BibleVerse @BibleId, 105027025, N'‘Cursed is the one who takes a bribe to kill an innocent person.’ Then all the people will say, ‘Amen!’'
EXEC add_BibleVerse @BibleId, 105027026, N'‘Cursed is the one who refuses to keep the words of this law.’ Then all the people will say, ‘Amen!’'
EXEC add_BibleVerse @BibleId, 105028001, N'“If you indeed obey the Lord your God and are careful to observe all his commandments I am giving you today, the Lord your God will elevate you above all the nations of the earth.'
EXEC add_BibleVerse @BibleId, 105028002, N'All these blessings will come to you in abundance if you obey the Lord your God:'
EXEC add_BibleVerse @BibleId, 105028003, N'You will be blessed in the city and blessed in the field.'
EXEC add_BibleVerse @BibleId, 105028004, N'Your children will be blessed, as well as the produce of your soil, the offspring of your livestock, the calves of your herds, and the lambs of your flocks.'
EXEC add_BibleVerse @BibleId, 105028005, N'Your basket and your mixing bowl will be blessed.'
EXEC add_BibleVerse @BibleId, 105028006, N'You will be blessed when you come in and blessed when you go out.'
EXEC add_BibleVerse @BibleId, 105028007, N'The Lord will cause your enemies who attack you to be struck down before you; they will attack you from one direction but flee from you in seven different directions.'
EXEC add_BibleVerse @BibleId, 105028008, N'The Lord will decree blessing for you with respect to your barns and in everything you do – yes, he will bless you in the land he is giving you.'
EXEC add_BibleVerse @BibleId, 105028009, N'The Lord will designate you as his holy people just as he promised you, if you keep his commandments and obey him.'
EXEC add_BibleVerse @BibleId, 105028010, N'Then all the peoples of the earth will see that you belong to the Lord, and they will respect you.'
EXEC add_BibleVerse @BibleId, 105028011, N'The Lord will greatly multiply your children, the offspring of your livestock, and the produce of your soil in the land which he promised your ancestors he would give you.'
EXEC add_BibleVerse @BibleId, 105028012, N'The Lord will open for you his good treasure house, the heavens, to give you rain for the land in its season and to bless all you do; you will lend to many nations but you will not borrow from any.'
EXEC add_BibleVerse @BibleId, 105028013, N'The Lord will make you the head and not the tail, and you will always end up at the top and not at the bottom, if you obey his commandments which I am urging you today to be careful to do.'
EXEC add_BibleVerse @BibleId, 105028014, N'But you must not turn away from all the commandments I am giving you today, to either the right or left, nor pursue other gods and worship them.'
EXEC add_BibleVerse @BibleId, 105028015, N'“But if you ignore the Lord your God and are not careful to keep all his commandments and statutes I am giving you today, then all these curses will come upon you in full force:'
EXEC add_BibleVerse @BibleId, 105028016, N'You will be cursed in the city and cursed in the field.'
EXEC add_BibleVerse @BibleId, 105028017, N'Your basket and your mixing bowl will be cursed.'
EXEC add_BibleVerse @BibleId, 105028018, N'Your children will be cursed, as well as the produce of your soil, the calves of your herds, and the lambs of your flocks.'
EXEC add_BibleVerse @BibleId, 105028019, N'You will be cursed when you come in and cursed when you go out.'
EXEC add_BibleVerse @BibleId, 105028020, N'“The Lord will send on you a curse, confusing you and opposing you in everything you undertake until you are destroyed and quickly perish because of the evil of your deeds, in that you have forsaken me.'
EXEC add_BibleVerse @BibleId, 105028021, N'The Lord will plague you with deadly diseases until he has completely removed you from the land you are about to possess.'
EXEC add_BibleVerse @BibleId, 105028022, N'He will afflict you with weakness, fever, inflammation, infection, sword, blight, and mildew; these will attack you until you perish.'
EXEC add_BibleVerse @BibleId, 105028023, N'The sky above your heads will be bronze and the earth beneath you iron.'
EXEC add_BibleVerse @BibleId, 105028024, N'The Lord will make the rain of your land powder and dust; it will come down on you from the sky until you are destroyed.'
EXEC add_BibleVerse @BibleId, 105028025, N'“The Lord will allow you to be struck down before your enemies; you will attack them from one direction but flee from them in seven directions and will become an object of terror to all the kingdoms of the earth.'
EXEC add_BibleVerse @BibleId, 105028026, N'Your carcasses will be food for every bird of the sky and wild animal of the earth, and there will be no one to chase them off.'
EXEC add_BibleVerse @BibleId, 105028027, N'The Lord will afflict you with the boils of Egypt and with tumors, eczema, and scabies, all of which cannot be healed.'
EXEC add_BibleVerse @BibleId, 105028028, N'The Lord will also subject you to madness, blindness, and confusion of mind.'
EXEC add_BibleVerse @BibleId, 105028029, N'You will feel your way along at noon like the blind person does in darkness and you will not succeed in anything you do; you will be constantly oppressed and continually robbed, with no one to save you.'
EXEC add_BibleVerse @BibleId, 105028030, N'You will be engaged to a woman and another man will rape her. You will build a house but not live in it. You will plant a vineyard but not even begin to use it.'
EXEC add_BibleVerse @BibleId, 105028031, N'Your ox will be slaughtered before your very eyes but you will not eat of it. Your donkey will be stolen from you as you watch and will not be returned to you. Your flock of sheep will be given to your enemies and there will be no one to save you.'
EXEC add_BibleVerse @BibleId, 105028032, N'Your sons and daughters will be given to another people while you look on in vain all day, and you will be powerless to do anything about it.'
EXEC add_BibleVerse @BibleId, 105028033, N'As for the produce of your land and all your labor, a people you do not know will consume it, and you will be nothing but oppressed and crushed for the rest of your lives.'
EXEC add_BibleVerse @BibleId, 105028034, N'You will go insane from seeing all this.'
EXEC add_BibleVerse @BibleId, 105028035, N'The Lord will afflict you in your knees and on your legs with painful, incurable boils – from the soles of your feet to the top of your head.'
EXEC add_BibleVerse @BibleId, 105028036, N'The Lord will force you and your king whom you will appoint over you to go away to a people whom you and your ancestors have not known, and you will serve other gods of wood and stone there.'
EXEC add_BibleVerse @BibleId, 105028037, N'You will become an occasion of horror, a proverb, and an object of ridicule to all the peoples to whom the Lord will drive you.'
EXEC add_BibleVerse @BibleId, 105028038, N'“You will take much seed to the field but gather little harvest, because locusts will consume it.'
EXEC add_BibleVerse @BibleId, 105028039, N'You will plant vineyards and cultivate them, but you will not drink wine or gather in grapes, because worms will eat them.'
EXEC add_BibleVerse @BibleId, 105028040, N'You will have olive trees throughout your territory but you will not anoint yourself with olive oil, because the olives will drop off the trees while still unripe.'
EXEC add_BibleVerse @BibleId, 105028041, N'You will bear sons and daughters but not keep them, because they will be taken into captivity.'
EXEC add_BibleVerse @BibleId, 105028042, N'Whirring locusts will take over every tree and all the produce of your soil.'
EXEC add_BibleVerse @BibleId, 105028043, N'The foreigners who reside among you will become higher and higher over you and you will become lower and lower.'
EXEC add_BibleVerse @BibleId, 105028044, N'They will lend to you but you will not lend to them; they will become the head and you will become the tail!'
EXEC add_BibleVerse @BibleId, 105028045, N'All these curses will fall on you, pursuing and overtaking you until you are destroyed, because you would not obey the Lord your God by keeping his commandments and statutes that he has given you.'
EXEC add_BibleVerse @BibleId, 105028046, N'These curses will be a perpetual sign and wonder with reference to you and your descendants.'
EXEC add_BibleVerse @BibleId, 105028047, N'“Because you have not served the Lord your God joyfully and wholeheartedly with the abundance of everything you have,'
EXEC add_BibleVerse @BibleId, 105028048, N'instead in hunger, thirst, nakedness, and poverty you will serve your enemies whom the Lord will send against you. They will place an iron yoke on your neck until they have destroyed you.'
EXEC add_BibleVerse @BibleId, 105028049, N'The Lord will raise up a distant nation against you, one from the other side of the earth as the eagle flies, a nation whose language you will not understand,'
EXEC add_BibleVerse @BibleId, 105028050, N'a nation of stern appearance that will have no regard for the elderly or pity for the young.'
EXEC add_BibleVerse @BibleId, 105028051, N'They will devour the offspring of your livestock and the produce of your soil until you are destroyed. They will not leave you with any grain, new wine, olive oil, calves of your herds, or lambs of your flocks until they have destroyed you.'
EXEC add_BibleVerse @BibleId, 105028052, N'They will besiege all of your villages until all of your high and fortified walls collapse – those in which you put your confidence throughout the land. They will besiege all your villages throughout the land the Lord your God has given you.'
EXEC add_BibleVerse @BibleId, 105028053, N'You will then eat your own offspring, the flesh of the sons and daughters the Lord your God has given you, because of the severity of the siege by which your enemies will constrict you.'
EXEC add_BibleVerse @BibleId, 105028054, N'The man among you who is by nature tender and sensitive will turn against his brother, his beloved wife, and his remaining children.'
EXEC add_BibleVerse @BibleId, 105028055, N'He will withhold from all of them his children’s flesh that he is eating (since there is nothing else left), because of the severity of the siege by which your enemy will constrict you in your villages.'
EXEC add_BibleVerse @BibleId, 105028056, N'Likewise, the most tender and delicate of your women, who would never think of putting even the sole of her foot on the ground because of her daintiness, will turn against her beloved husband, her sons and daughters,'
EXEC add_BibleVerse @BibleId, 105028057, N'and will secretly eat her afterbirth and her newborn children (since she has nothing else), because of the severity of the siege by which your enemy will constrict you in your villages.'
EXEC add_BibleVerse @BibleId, 105028058, N'“If you refuse to obey all the words of this law, the things written in this scroll, and refuse to fear this glorious and awesome name, the Lord your God,'
EXEC add_BibleVerse @BibleId, 105028059, N'then the Lord will increase your punishments and those of your descendants – great and long-lasting afflictions and severe, enduring illnesses.'
EXEC add_BibleVerse @BibleId, 105028060, N'He will infect you with all the diseases of Egypt that you dreaded, and they will persistently afflict you.'
EXEC add_BibleVerse @BibleId, 105028061, N'Moreover, the Lord will bring upon you every kind of sickness and plague not mentioned in this scroll of commandments, until you have perished.'
EXEC add_BibleVerse @BibleId, 105028062, N'There will be very few of you left, though at one time you were as numerous as the stars in the sky, because you will have disobeyed the Lord your God.'
EXEC add_BibleVerse @BibleId, 105028063, N'This is what will happen: Just as the Lord delighted to do good for you and make you numerous, he will take delight in destroying and decimating you. You will be uprooted from the land you are about to possess.'
EXEC add_BibleVerse @BibleId, 105028064, N'The Lord will scatter you among all nations, from one end of the earth to the other. There you will worship other gods that neither you nor your ancestors have known, gods of wood and stone.'
EXEC add_BibleVerse @BibleId, 105028065, N'Among those nations you will have no rest nor will there be a place of peaceful rest for the soles of your feet, for there the Lord will give you an anxious heart, failing eyesight, and a spirit of despair.'
EXEC add_BibleVerse @BibleId, 105028066, N'Your life will hang in doubt before you; you will be terrified by night and day and will have no certainty of surviving from one day to the next.'
EXEC add_BibleVerse @BibleId, 105028067, N'In the morning you will say, ‘If only it were evening!’ And in the evening you will say, ‘I wish it were morning!’ because of the things you will fear and the things you will see.'
EXEC add_BibleVerse @BibleId, 105028068, N'Then the Lord will make you return to Egypt by ship, over a route I said to you that you would never see again. There you will sell yourselves to your enemies as male and female slaves, but no one will buy you.”'
EXEC add_BibleVerse @BibleId, 105029001, N'These are the words of the covenant that the Lord commanded Moses to make with the people of Israel in the land of Moab, in addition to the covenant he had made with them at Horeb.'
EXEC add_BibleVerse @BibleId, 105029002, N'Moses proclaimed to all Israel as follows: “You have seen all that the Lord did in the land of Egypt to Pharaoh, all his servants, and his land.'
EXEC add_BibleVerse @BibleId, 105029003, N'Your eyes have seen the great judgments, those signs and mighty wonders.'
EXEC add_BibleVerse @BibleId, 105029004, N'But to this very day the Lord has not given you an understanding mind, perceptive eyes, or discerning ears!'
EXEC add_BibleVerse @BibleId, 105029005, N'I have led you through the desert for forty years. Your clothing has not worn out nor have your sandals deteriorated.'
EXEC add_BibleVerse @BibleId, 105029006, N'You have eaten no bread and drunk no wine or beer – all so that you might know that I am the Lord your God!'
EXEC add_BibleVerse @BibleId, 105029007, N'When you came to this place King Sihon of Heshbon and King Og of Bashan came out to make war and we defeated them.'
EXEC add_BibleVerse @BibleId, 105029008, N'Then we took their land and gave it as an inheritance to Reuben, Gad, and half the tribe of Manasseh.'
EXEC add_BibleVerse @BibleId, 105029009, N'“Therefore, keep the terms of this covenant and obey them so that you may be successful in everything you do.'
EXEC add_BibleVerse @BibleId, 105029010, N'You are standing today, all of you, before the Lord your God – the heads of your tribes, your elders, your officials, every Israelite man,'
EXEC add_BibleVerse @BibleId, 105029011, N'your infants, your wives, and the foreigners living in your encampment, those who chop wood and those who carry water –'
EXEC add_BibleVerse @BibleId, 105029012, N'so that you may enter by oath into the covenant the Lord your God is making with you today.'
EXEC add_BibleVerse @BibleId, 105029013, N'Today he will affirm that you are his people and that he is your God, just as he promised you and as he swore by oath to your ancestors Abraham, Isaac, and Jacob.'
EXEC add_BibleVerse @BibleId, 105029014, N'It is not with you alone that I am making this covenant by oath,'
EXEC add_BibleVerse @BibleId, 105029015, N'but with whoever stands with us here today before the Lord our God as well as those not with us here today.'
EXEC add_BibleVerse @BibleId, 105029016, N'“(For you know how we lived in the land of Egypt and how we crossed through the nations as we traveled.'
EXEC add_BibleVerse @BibleId, 105029017, N'You have seen their detestable things and idols of wood, stone, silver, and gold.)'
EXEC add_BibleVerse @BibleId, 105029018, N'Beware that the heart of no man, woman, clan, or tribe among you turns away from the Lord our God today to pursue and serve the gods of those nations; beware that there is among you no root producing poisonous and bitter fruit.'
EXEC add_BibleVerse @BibleId, 105029019, N'When such a person hears the words of this oath he secretly blesses himself and says, “I will have peace though I continue to walk with a stubborn spirit.” This will destroy the watered ground with the parched.'
EXEC add_BibleVerse @BibleId, 105029020, N'The Lord will be unwilling to forgive him, and his intense anger will rage against that man; all the curses written in this scroll will fall upon him and the Lord will obliterate his name from memory.'
EXEC add_BibleVerse @BibleId, 105029021, N'The Lord will single him out for judgment from all the tribes of Israel according to all the curses of the covenant written in this scroll of the law.'
EXEC add_BibleVerse @BibleId, 105029022, N'The generation to come – your descendants who will rise up after you, as well as the foreigner who will come from distant places – will see the afflictions of that land and the illnesses that the Lord has brought on it.'
EXEC add_BibleVerse @BibleId, 105029023, N'The whole land will be covered with brimstone, salt, and burning debris; it will not be planted nor will it sprout or produce grass. It will resemble the destruction of Sodom and Gomorrah, Admah and Zeboiim, which the Lord destroyed in his intense anger.'
EXEC add_BibleVerse @BibleId, 105029024, N'Then all the nations will ask, “Why has the Lord done all this to this land? What is this fierce, heated display of anger all about?”'
EXEC add_BibleVerse @BibleId, 105029025, N'Then people will say, “Because they abandoned the covenant of the Lord, the God of their ancestors, which he made with them when he brought them out of the land of Egypt.'
EXEC add_BibleVerse @BibleId, 105029026, N'They went and served other gods and worshiped them, gods they did not know and that he did not permit them to worship.'
EXEC add_BibleVerse @BibleId, 105029027, N'That is why the Lord’s anger erupted against this land, bringing on it all the curses written in this scroll.'
EXEC add_BibleVerse @BibleId, 105029028, N'So the Lord has uprooted them from their land in anger, wrath, and great rage and has deported them to another land, as is clear today.”'
EXEC add_BibleVerse @BibleId, 105029029, N'Secret things belong to the Lord our God, but those that are revealed belong to us and our descendants forever, so that we might obey all the words of this law.'
EXEC add_BibleVerse @BibleId, 105030001, N'“When you have experienced all these things, both the blessings and the curses I have set before you, you will reflect upon them in all the nations where the Lord your God has banished you.'
EXEC add_BibleVerse @BibleId, 105030002, N'Then if you and your descendants turn to the Lord your God and obey him with your whole mind and being just as I am commanding you today,'
EXEC add_BibleVerse @BibleId, 105030003, N'the Lord your God will reverse your captivity and have pity on you. He will turn and gather you from all the peoples among whom he has scattered you.'
EXEC add_BibleVerse @BibleId, 105030004, N'Even if your exiles are in the most distant land, from there the Lord your God will gather you and bring you back.'
EXEC add_BibleVerse @BibleId, 105030005, N'Then he will bring you to the land your ancestors possessed and you also will possess it; he will do better for you and multiply you more than he did your ancestors.'
EXEC add_BibleVerse @BibleId, 105030006, N'The Lord your God will also cleanse your heart and the hearts of your descendants so that you may love him with all your mind and being and so that you may live.'
EXEC add_BibleVerse @BibleId, 105030007, N'Then the Lord your God will put all these curses on your enemies, on those who hate you and persecute you.'
EXEC add_BibleVerse @BibleId, 105030008, N'You will return and obey the Lord, keeping all his commandments I am giving you today.'
EXEC add_BibleVerse @BibleId, 105030009, N'The Lord your God will make the labor of your hands abundantly successful and multiply your children, the offspring of your cattle, and the produce of your soil. For the Lord your God will once more rejoice over you to make you prosperous just as he rejoiced over your ancestors,'
EXEC add_BibleVerse @BibleId, 105030010, N'if you obey the Lord your God and keep his commandments and statutes that are written in this scroll of the law. But you must turn to him with your whole mind and being.'
EXEC add_BibleVerse @BibleId, 105030011, N'“This commandment I am giving you today is not too difficult for you, nor is it too remote.'
EXEC add_BibleVerse @BibleId, 105030012, N'It is not in heaven, as though one must say, “Who will go up to heaven to get it for us and proclaim it to us so we may obey it?”'
EXEC add_BibleVerse @BibleId, 105030013, N'And it is not across the sea, as though one must say, “Who will cross over to the other side of the sea and get it for us and proclaim it to us so we may obey it?”'
EXEC add_BibleVerse @BibleId, 105030014, N'For the thing is very near you – it is in your mouth and in your mind so that you can do it.'
EXEC add_BibleVerse @BibleId, 105030015, N'“Look! I have set before you today life and prosperity on the one hand, and death and disaster on the other.'
EXEC add_BibleVerse @BibleId, 105030016, N'What I am commanding you today is to love the Lord your God, to walk in his ways, and to obey his commandments, his statutes, and his ordinances. Then you will live and become numerous and the Lord your God will bless you in the land which you are about to possess.'
EXEC add_BibleVerse @BibleId, 105030017, N'However, if you turn aside and do not obey, but are lured away to worship and serve other gods,'
EXEC add_BibleVerse @BibleId, 105030018, N'I declare to you this very day that you will certainly perish! You will not extend your time in the land you are crossing the Jordan to possess.'
EXEC add_BibleVerse @BibleId, 105030019, N'Today I invoke heaven and earth as a witness against you that I have set life and death, blessing and curse, before you. Therefore choose life so that you and your descendants may live!'
EXEC add_BibleVerse @BibleId, 105030020, N'I also call on you to love the Lord your God, to obey him and be loyal to him, for he gives you life and enables you to live continually in the land the Lord promised to give to your ancestors Abraham, Isaac, and Jacob.”'
EXEC add_BibleVerse @BibleId, 105031001, N'Then Moses went and spoke these words to all Israel.'
EXEC add_BibleVerse @BibleId, 105031002, N'He said to them, “Today I am a hundred and twenty years old. I am no longer able to get about, and the Lord has said to me, ‘You will not cross the Jordan.’'
EXEC add_BibleVerse @BibleId, 105031003, N'As for the Lord your God, he is about to cross over before you; he will destroy these nations before you and dispossess them. As for Joshua, he is about to cross before you just as the Lord has said.'
EXEC add_BibleVerse @BibleId, 105031004, N'The Lord will do to them just what he did to Sihon and Og, the Amorite kings, and to their land, which he destroyed.'
EXEC add_BibleVerse @BibleId, 105031005, N'The Lord will deliver them over to you and you will do to them according to the whole commandment I have given you.'
EXEC add_BibleVerse @BibleId, 105031006, N'Be strong and courageous! Do not fear or tremble before them, for the Lord your God is the one who is going with you. He will not fail you or abandon you!”'
EXEC add_BibleVerse @BibleId, 105031007, N'Then Moses called out to Joshua in the presence of all Israel, “Be strong and courageous, for you will accompany these people to the land that the Lord promised to give their ancestors, and you will enable them to inherit it.'
EXEC add_BibleVerse @BibleId, 105031008, N'The Lord is indeed going before you – he will be with you; he will not fail you or abandon you. Do not be afraid or discouraged!”'
EXEC add_BibleVerse @BibleId, 105031009, N'Then Moses wrote down this law and gave it to the Levitical priests, who carry the ark of the Lord’s covenant, and to all Israel’s elders.'
EXEC add_BibleVerse @BibleId, 105031010, N'He commanded them: “At the end of seven years, at the appointed time of the cancellation of debts, at the Feast of Temporary Shelters,'
EXEC add_BibleVerse @BibleId, 105031011, N'when all Israel comes to appear before the Lord your God in the place he chooses, you must read this law before them within their hearing.'
EXEC add_BibleVerse @BibleId, 105031012, N'Gather the people – men, women, and children, as well as the resident foreigners in your villages – so they may hear and thus learn about and fear the Lord your God and carefully obey all the words of this law.'
EXEC add_BibleVerse @BibleId, 105031013, N'Then their children, who have not known this law, will also hear about and learn to fear the Lord your God for as long as you live in the land you are crossing the Jordan to possess.”'
EXEC add_BibleVerse @BibleId, 105031014, N'Then the Lord said to Moses, “The day of your death is near. Summon Joshua and present yourselves in the tent of meeting so that I can commission him.” So Moses and Joshua presented themselves in the tent of meeting.'
EXEC add_BibleVerse @BibleId, 105031015, N'The Lord appeared in the tent in a pillar of cloud that stood above the door of the tent.'
EXEC add_BibleVerse @BibleId, 105031016, N'Then the Lord said to Moses, “You are about to die, and then these people will begin to prostitute themselves with the foreign gods of the land into which they are going. They will reject me and break my covenant that I have made with them.'
EXEC add_BibleVerse @BibleId, 105031017, N'At that time my anger will erupt against them and I will abandon them and hide my face from them until they are devoured. Many disasters and distresses will overcome them so that they will say at that time, ‘Have not these disasters overcome us because our God is not among us ?’'
EXEC add_BibleVerse @BibleId, 105031018, N'But I will certainly hide myself at that time because of all the wickedness they will have done by turning to other gods.'
EXEC add_BibleVerse @BibleId, 105031019, N'Now write down for yourselves the following song and teach it to the Israelites. Put it into their very mouths so that this song may serve as my witness against the Israelites!'
EXEC add_BibleVerse @BibleId, 105031020, N'For after I have brought them to the land I promised to their ancestors – one flowing with milk and honey – and they eat their fill and become fat, then they will turn to other gods and worship them; they will reject me and break my covenant.'
EXEC add_BibleVerse @BibleId, 105031021, N'Then when many disasters and distresses overcome them this song will testify against them, for their descendants will not forget it. I know the intentions they have in mind today, even before I bring them to the land I have promised.”'
EXEC add_BibleVerse @BibleId, 105031022, N'So on that day Moses wrote down this song and taught it to the Israelites,'
EXEC add_BibleVerse @BibleId, 105031023, N'and the Lord commissioned Joshua son of Nun, “Be strong and courageous, for you will take the Israelites to the land I have promised them, and I will be with you.”'
EXEC add_BibleVerse @BibleId, 105031024, N'When Moses finished writing on a scroll the words of this law in their entirety,'
EXEC add_BibleVerse @BibleId, 105031025, N'he commanded the Levites who carried the ark of the Lord’s covenant,'
EXEC add_BibleVerse @BibleId, 105031026, N'“Take this scroll of the law and place it beside the ark of the covenant of the Lord your God. It will remain there as a witness against you,'
EXEC add_BibleVerse @BibleId, 105031027, N'for I know about your rebellion and stubbornness. Indeed, even while I have been living among you to this very day, you have rebelled against the Lord; you will be even more rebellious after my death!'
EXEC add_BibleVerse @BibleId, 105031028, N'Gather to me all your tribal elders and officials so I can speak to them directly about these things and call the heavens and the earth to witness against them.'
EXEC add_BibleVerse @BibleId, 105031029, N'For I know that after I die you will totally corrupt yourselves and turn away from the path I have commanded you to walk. Disaster will confront you in the days to come because you will act wickedly before the Lord, inciting him to anger because of your actions.”'
EXEC add_BibleVerse @BibleId, 105031030, N'Then Moses recited the words of this song from start to finish in the hearing of the whole assembly of Israel.'
EXEC add_BibleVerse @BibleId, 105032001, N'Listen, O heavens, and I will speak; hear, O earth, the words of my mouth.'
EXEC add_BibleVerse @BibleId, 105032002, N'My teaching will drop like the rain, my sayings will drip like the dew, as rain drops upon the grass, and showers upon new growth.'
EXEC add_BibleVerse @BibleId, 105032003, N'For I will proclaim the name of the Lord; you must acknowledge the greatness of our God.'
EXEC add_BibleVerse @BibleId, 105032004, N'As for the Rock, his work is perfect, for all his ways are just. He is a reliable God who is never unjust, he is fair and upright.'
EXEC add_BibleVerse @BibleId, 105032005, N'His people have been unfaithful to him; they have not acted like his children – this is their sin. They are a perverse and deceitful generation.'
EXEC add_BibleVerse @BibleId, 105032006, N'Is this how you repay the Lord, you foolish, unwise people? Is he not your father, your creator? He has made you and established you.'
EXEC add_BibleVerse @BibleId, 105032007, N'Remember the ancient days; bear in mind the years of past generations. Ask your father and he will inform you, your elders, and they will tell you.'
EXEC add_BibleVerse @BibleId, 105032008, N'When the Most High gave the nations their inheritance, when he divided up humankind, he set the boundaries of the peoples, according to the number of the heavenly assembly.'
EXEC add_BibleVerse @BibleId, 105032009, N'For the Lord’s allotment is his people, Jacob is his special possession.'
EXEC add_BibleVerse @BibleId, 105032010, N'The Lord found him in a desolate land, in an empty wasteland where animals howl. He continually guarded him and taught him; he continually protected him like the pupil of his eye.'
EXEC add_BibleVerse @BibleId, 105032011, N'Like an eagle that stirs up its nest, that hovers over its young, so the Lord spread out his wings and took him, he lifted him up on his pinions.'
EXEC add_BibleVerse @BibleId, 105032012, N'The Lord alone was guiding him, no foreign god was with him.'
EXEC add_BibleVerse @BibleId, 105032013, N'He enabled him to travel over the high terrain of the land, and he ate of the produce of the fields. He provided honey for him from the cliffs, and olive oil from the hardest of rocks,'
EXEC add_BibleVerse @BibleId, 105032014, N'butter from the herd and milk from the flock, along with the fat of lambs, rams and goats of Bashan, along with the best of the kernels of wheat; and from the juice of grapes you drank wine.'
EXEC add_BibleVerse @BibleId, 105032015, N'But Jeshurun became fat and kicked, you got fat, thick, and stuffed! Then he deserted the God who made him, and treated the Rock who saved him with contempt.'
EXEC add_BibleVerse @BibleId, 105032016, N'They made him jealous with other gods, they enraged him with abhorrent idols.'
EXEC add_BibleVerse @BibleId, 105032017, N'They sacrificed to demons, not God, to gods they had not known; to new gods who had recently come along, gods your ancestors had not known about.'
EXEC add_BibleVerse @BibleId, 105032018, N'You have forgotten the Rock who fathered you, and put out of mind the God who gave you birth.'
EXEC add_BibleVerse @BibleId, 105032019, N'But the Lord took note and despised them because his sons and daughters enraged him.'
EXEC add_BibleVerse @BibleId, 105032020, N'He said, “I will reject them, I will see what will happen to them; for they are a perverse generation, children who show no loyalty.'
EXEC add_BibleVerse @BibleId, 105032021, N'They have made me jealous with false gods, enraging me with their worthless gods; so I will make them jealous with a people they do not recognize, with a nation slow to learn I will enrage them.'
EXEC add_BibleVerse @BibleId, 105032022, N'For a fire has been kindled by my anger, and it burns to lowest Sheol; it consumes the earth and its produce, and ignites the foundations of the mountains.'
EXEC add_BibleVerse @BibleId, 105032023, N'I will increase their disasters, I will use up my arrows on them.'
EXEC add_BibleVerse @BibleId, 105032024, N'They will be starved by famine, eaten by plague, and bitterly stung; I will send the teeth of wild animals against them, along with the poison of creatures that crawl in the dust.'
EXEC add_BibleVerse @BibleId, 105032025, N'The sword will make people childless outside, and terror will do so inside; they will destroy both the young man and the virgin, the infant and the gray-haired man.'
EXEC add_BibleVerse @BibleId, 105032026, N'“I said, ‘I want to cut them in pieces. I want to make people forget they ever existed.'
EXEC add_BibleVerse @BibleId, 105032027, N'But I fear the reaction of their enemies, for their adversaries would misunderstand and say, “Our power is great, and the Lord has not done all this!”’'
EXEC add_BibleVerse @BibleId, 105032028, N'They are a nation devoid of wisdom, and there is no understanding among them.'
EXEC add_BibleVerse @BibleId, 105032029, N'I wish that they were wise and could understand this, and that they could comprehend what will happen to them.”'
EXEC add_BibleVerse @BibleId, 105032030, N'How can one man chase a thousand of them, and two pursue ten thousand; unless their Rock had delivered them up, and the Lord had handed them over?'
EXEC add_BibleVerse @BibleId, 105032031, N'For our enemies’ rock is not like our Rock, as even our enemies concede.'
EXEC add_BibleVerse @BibleId, 105032032, N'For their vine is from the stock of Sodom, and from the fields of Gomorrah. Their grapes contain venom, their clusters of grapes are bitter.'
EXEC add_BibleVerse @BibleId, 105032033, N'Their wine is snakes’ poison, the deadly venom of cobras.'
EXEC add_BibleVerse @BibleId, 105032034, N'“Is this not stored up with me?” says the Lord, “Is it not sealed up in my storehouses?'
EXEC add_BibleVerse @BibleId, 105032035, N'I will get revenge and pay them back at the time their foot slips; for the day of their disaster is near, and the impending judgment is rushing upon them!”'
EXEC add_BibleVerse @BibleId, 105032036, N'The Lord will judge his people, and will change his plans concerning his servants; when he sees that their power has disappeared, and that no one is left, whether confined or set free.'
EXEC add_BibleVerse @BibleId, 105032037, N'He will say, “Where are their gods, the rock in whom they sought security,'
EXEC add_BibleVerse @BibleId, 105032038, N'who ate the best of their sacrifices, and drank the wine of their drink offerings? Let them rise and help you; let them be your refuge!'
EXEC add_BibleVerse @BibleId, 105032039, N'“See now that I, indeed I, am he!” says the Lord, “and there is no other god besides me. I kill and give life, I smash and I heal, and none can resist my power.'
EXEC add_BibleVerse @BibleId, 105032040, N'For I raise up my hand to heaven, and say, ‘As surely as I live forever,'
EXEC add_BibleVerse @BibleId, 105032041, N'I will sharpen my lightning-like sword, and my hand will grasp hold of the weapon of judgment; I will execute vengeance on my foes, and repay those who hate me!'
EXEC add_BibleVerse @BibleId, 105032042, N'I will make my arrows drunk with blood, and my sword will devour flesh – the blood of the slaughtered and captured, the chief of the enemy’s leaders!’”'
EXEC add_BibleVerse @BibleId, 105032043, N'Cry out, O nations, with his people, for he will avenge his servants’ blood; he will take vengeance against his enemies, and make atonement for his land and people.'
EXEC add_BibleVerse @BibleId, 105032044, N'Then Moses went with Joshua son of Nun and recited all the words of this song to the people.'
EXEC add_BibleVerse @BibleId, 105032045, N'When Moses finished reciting all these words to all Israel'
EXEC add_BibleVerse @BibleId, 105032046, N'he said to them, “Keep in mind all the words I am solemnly proclaiming to you today; you must command your children to observe carefully all the words of this law.'
EXEC add_BibleVerse @BibleId, 105032047, N'For this is no idle word for you – it is your life! By this word you will live a long time in the land you are about to cross the Jordan to possess.”'
EXEC add_BibleVerse @BibleId, 105032048, N'Then the Lord said to Moses that same day,'
EXEC add_BibleVerse @BibleId, 105032049, N'“Go up to this Abarim hill country, to Mount Nebo (which is in the land of Moab opposite Jericho ) and look at the land of Canaan that I am giving to the Israelites as a possession.'
EXEC add_BibleVerse @BibleId, 105032050, N'You will die on the mountain that you ascend and join your deceased ancestors, just as Aaron your brother died on Mount Hor and joined his deceased ancestors,'
EXEC add_BibleVerse @BibleId, 105032051, N'for both of you rebelled against me among the Israelites at the waters of Meribah Kadesh in the desert of Zin when you did not show me proper respect among the Israelites.'
EXEC add_BibleVerse @BibleId, 105032052, N'You will see the land before you, but you will not enter the land that I am giving to the Israelites.”'
EXEC add_BibleVerse @BibleId, 105033001, N'This is the blessing Moses the man of God pronounced upon the Israelites before his death.'
EXEC add_BibleVerse @BibleId, 105033002, N'He said: The Lord came from Sinai and revealed himself to Israel from Seir. He appeared in splendor from Mount Paran, and came forth with ten thousand holy ones. With his right hand he gave a fiery law to them.'
EXEC add_BibleVerse @BibleId, 105033003, N'Surely he loves the people; all your holy ones are in your power. And they sit at your feet, each receiving your words.'
EXEC add_BibleVerse @BibleId, 105033004, N'Moses delivered to us a law, an inheritance for the assembly of Jacob.'
EXEC add_BibleVerse @BibleId, 105033005, N'The Lord was king over Jeshurun, when the leaders of the people assembled, the tribes of Israel together.'
EXEC add_BibleVerse @BibleId, 105033006, N'May Reuben live and not die, and may his people multiply.'
EXEC add_BibleVerse @BibleId, 105033007, N'And this is the blessing to Judah. He said, Listen, O Lord, to Judah’s voice, and bring him to his people. May his power be great, and may you help him against his foes.'
EXEC add_BibleVerse @BibleId, 105033008, N'Of Levi he said: Your Thummim and Urim belong to your godly one, whose authority you challenged at Massah, and with whom you argued at the waters of Meribah.'
EXEC add_BibleVerse @BibleId, 105033009, N'He said to his father and mother, “I have not seen him,” and he did not acknowledge his own brothers or know his own children, for they kept your word, and guarded your covenant.'
EXEC add_BibleVerse @BibleId, 105033010, N'They will teach Jacob your ordinances and Israel your law; they will offer incense as a pleasant odor, and a whole offering on your altar.'
EXEC add_BibleVerse @BibleId, 105033011, N'Bless, O Lord, his goods, and be pleased with his efforts; undercut the legs of any who attack him, and of those who hate him, so that they cannot stand.'
EXEC add_BibleVerse @BibleId, 105033012, N'Of Benjamin he said: The beloved of the Lord will live safely by him; he protects him all the time, and the Lord places him on his chest.'
EXEC add_BibleVerse @BibleId, 105033013, N'Of Joseph he said: May the Lord bless his land with the harvest produced by the sky, by the dew, and by the depths crouching beneath;'
EXEC add_BibleVerse @BibleId, 105033014, N'with the harvest produced by the daylight and by the moonlight;'
EXEC add_BibleVerse @BibleId, 105033015, N'with the best of the ancient mountains and the harvest produced by the age-old hills;'
EXEC add_BibleVerse @BibleId, 105033016, N'with the harvest of the earth and its fullness and the pleasure of him who resided in the burning bush. May blessing rest on Joseph’s head, and on the top of the head of the one set apart from his brothers.'
EXEC add_BibleVerse @BibleId, 105033017, N'May the firstborn of his bull bring him honor, and may his horns be those of a wild ox; with them may he gore all peoples, all the far reaches of the earth. They are the ten thousands of Ephraim, and they are the thousands of Manasseh.'
EXEC add_BibleVerse @BibleId, 105033018, N'Of Zebulun he said: Rejoice, Zebulun, when you go outside, and Issachar, when you are in your tents.'
EXEC add_BibleVerse @BibleId, 105033019, N'They will summon peoples to the mountain, there they will sacrifice proper sacrifices; for they will enjoy the abundance of the seas, and the hidden treasures of the shores.'
EXEC add_BibleVerse @BibleId, 105033020, N'Of Gad he said: Blessed be the one who enlarges Gad. Like a lioness he will dwell; he will tear at an arm – indeed, a scalp.'
EXEC add_BibleVerse @BibleId, 105033021, N'He has selected the best part for himself, for the portion of the ruler is set aside there; he came with the leaders of the people, he obeyed the righteous laws of the Lord and his ordinances with Israel.'
EXEC add_BibleVerse @BibleId, 105033022, N'Of Dan he said: Dan is a lion’s cub; he will leap forth from Bashan.'
EXEC add_BibleVerse @BibleId, 105033023, N'Of Naphtali he said: O Naphtali, overflowing with favor, and full of the Lord’s blessing, possess the west and south.'
EXEC add_BibleVerse @BibleId, 105033024, N'Of Asher he said: Asher is blessed with children, may he be favored by his brothers and may he dip his foot in olive oil.'
EXEC add_BibleVerse @BibleId, 105033025, N'The bars of your gates will be made of iron and bronze, and may you have lifelong strength.'
EXEC add_BibleVerse @BibleId, 105033026, N'There is no one like God, O Jeshurun, who rides through the sky to help you, on the clouds in majesty.'
EXEC add_BibleVerse @BibleId, 105033027, N'The everlasting God is a refuge, and underneath you are his eternal arms; he has driven out enemies before you, and has said, “Destroy!”'
EXEC add_BibleVerse @BibleId, 105033028, N'Israel lives in safety, the fountain of Jacob is quite secure, in a land of grain and new wine; indeed, its heavens rain down dew.'
EXEC add_BibleVerse @BibleId, 105033029, N'You have joy, Israel! Who is like you? You are a people delivered by the Lord, your protective shield and your exalted sword. May your enemies cringe before you; may you trample on their backs.'
EXEC add_BibleVerse @BibleId, 105034001, N'Then Moses ascended from the deserts of Moab to Mount Nebo, to the summit of Pisgah, which is opposite Jericho. The Lord showed him the whole land – Gilead to Dan,'
EXEC add_BibleVerse @BibleId, 105034002, N'and all of Naphtali, the land of Ephraim and Manasseh, all the land of Judah as far as the distant sea,'
EXEC add_BibleVerse @BibleId, 105034003, N'the Negev, and the plain of the valley of Jericho, the city of the date palm trees, as far as Zoar.'
EXEC add_BibleVerse @BibleId, 105034004, N'Then the Lord said to him, “This is the land I promised to Abraham, Isaac, and Jacob when I said, ‘I will give it to your descendants.’ I have let you see it, but you will not cross over there.”'
EXEC add_BibleVerse @BibleId, 105034005, N'So Moses, the servant of the Lord, died there in the land of Moab as the Lord had said.'
EXEC add_BibleVerse @BibleId, 105034006, N'He buried him in the land of Moab near Beth Peor, but no one knows his exact burial place to this very day.'
EXEC add_BibleVerse @BibleId, 105034007, N'Moses was 120 years old when he died, but his eye was not dull nor had his vitality departed.'
EXEC add_BibleVerse @BibleId, 105034008, N'The Israelites mourned for Moses in the deserts of Moab for thirty days; then the days of mourning for Moses ended.'
EXEC add_BibleVerse @BibleId, 105034009, N'Now Joshua son of Nun was full of the spirit of wisdom, for Moses had placed his hands on him; and the Israelites listened to him and did just what the Lord had commanded Moses.'
EXEC add_BibleVerse @BibleId, 105034010, N'No prophet ever again arose in Israel like Moses, who knew the Lord face to face.'
EXEC add_BibleVerse @BibleId, 105034011, N'He did all the signs and wonders the Lord had sent him to do in the land of Egypt, to Pharaoh, all his servants, and the whole land,'
EXEC add_BibleVerse @BibleId, 105034012, N'and he displayed great power and awesome might in view of all Israel.'
EXEC add_BibleVerse @BibleId, 106001001, N'After Moses the Lord’s servant died, the Lord said to Joshua son of Nun, Moses’ assistant:'
EXEC add_BibleVerse @BibleId, 106001002, N'“Moses my servant is dead. Get ready! Cross the Jordan River! Lead these people into the land which I am ready to hand over to them.'
EXEC add_BibleVerse @BibleId, 106001003, N'I am handing over to you every place you set foot, as I promised Moses.'
EXEC add_BibleVerse @BibleId, 106001004, N'Your territory will extend from the wilderness in the south to Lebanon in the north. It will extend all the way to the great River Euphrates in the east (including all of Syria) and all the way to the Mediterranean Sea in the west.'
EXEC add_BibleVerse @BibleId, 106001005, N'No one will be able to resist you all the days of your life. As I was with Moses, so I will be with you. I will not abandon you or leave you alone.'
EXEC add_BibleVerse @BibleId, 106001006, N'Be strong and brave! You must lead these people in the conquest of this land that I solemnly promised their ancestors I would hand over to them.'
EXEC add_BibleVerse @BibleId, 106001007, N'Make sure you are very strong and brave! Carefully obey all the law my servant Moses charged you to keep! Do not swerve from it to the right or to the left, so that you may be successful in all you do.'
EXEC add_BibleVerse @BibleId, 106001008, N'This law scroll must not leave your lips! You must memorize it day and night so you can carefully obey all that is written in it. Then you will prosper and be successful.'
EXEC add_BibleVerse @BibleId, 106001009, N'I repeat, be strong and brave! Don’t be afraid and don’t panic, for I, the Lord your God, am with you in all you do.”'
EXEC add_BibleVerse @BibleId, 106001010, N'Joshua instructed the leaders of the people:'
EXEC add_BibleVerse @BibleId, 106001011, N'“Go through the camp and command the people, ‘Prepare your supplies, for within three days you will cross the Jordan River and begin the conquest of the land the Lord your God is ready to hand over to you.’”'
EXEC add_BibleVerse @BibleId, 106001012, N'Joshua told the Reubenites, Gadites, and the half tribe of Manasseh:'
EXEC add_BibleVerse @BibleId, 106001013, N'“Remember what Moses the Lord’s servant commanded you. The Lord your God is giving you a place to settle and is handing this land over to you.'
EXEC add_BibleVerse @BibleId, 106001014, N'Your wives, children and cattle may stay in the land that Moses assigned to you east of the Jordan River. But all you warriors must cross over armed for battle ahead of your brothers. You must help them'
EXEC add_BibleVerse @BibleId, 106001015, N'until the Lord gives your brothers a place like yours to settle and they conquer the land the Lord your God is ready to hand over to them. Then you may go back to your allotted land and occupy the land Moses the Lord’s servant assigned you east of the Jordan.”'
EXEC add_BibleVerse @BibleId, 106001016, N'They told Joshua, “We will do everything you say. We will go wherever you send us.'
EXEC add_BibleVerse @BibleId, 106001017, N'Just as we obeyed Moses, so we will obey you. But may the Lord your God be with you as he was with Moses!'
EXEC add_BibleVerse @BibleId, 106001018, N'Any man who rebels against what you say and does not obey all your commands will be executed. But be strong and brave!”'
EXEC add_BibleVerse @BibleId, 106002001, N'Joshua son of Nun sent two spies out from Shittim secretly and instructed them: “Find out what you can about the land, especially Jericho.” They stopped at the house of a prostitute named Rahab and spent the night there.'
EXEC add_BibleVerse @BibleId, 106002002, N'The king of Jericho received this report: “Note well! Israelite men have come here tonight to spy on the land.”'
EXEC add_BibleVerse @BibleId, 106002003, N'So the king of Jericho sent this order to Rahab: “Turn over the men who came to you – the ones who came to your house – for they have come to spy on the whole land!”'
EXEC add_BibleVerse @BibleId, 106002004, N'But the woman hid the two men and replied, “Yes, these men were clients of mine, but I didn’t know where they came from.'
EXEC add_BibleVerse @BibleId, 106002005, N'When it was time to shut the city gate for the night, the men left. I don’t know where they were heading. Chase after them quickly, for you have time to catch them!”'
EXEC add_BibleVerse @BibleId, 106002006, N'(Now she had taken them up to the roof and had hidden them in the stalks of flax she had spread out on the roof.)'
EXEC add_BibleVerse @BibleId, 106002007, N'Meanwhile the king’s men tried to find them on the road to the Jordan River near the fords. The city gate was shut as soon as they set out in pursuit of them.'
EXEC add_BibleVerse @BibleId, 106002008, N'Now before the spies went to sleep, Rahab went up to the roof.'
EXEC add_BibleVerse @BibleId, 106002009, N'She said to the men, “I know the Lord is handing this land over to you. We are absolutely terrified of you, and all who live in the land are cringing before you.'
EXEC add_BibleVerse @BibleId, 106002010, N'For we heard how the Lord dried up the water of the Red Sea before you when you left Egypt and how you annihilated the two Amorite kings, Sihon and Og, on the other side of the Jordan.'
EXEC add_BibleVerse @BibleId, 106002011, N'When we heard the news we lost our courage and no one could even breathe for fear of you. For the Lord your God is God in heaven above and on earth below!'
EXEC add_BibleVerse @BibleId, 106002012, N'So now, promise me this with an oath sworn in the Lord’s name. Because I have shown allegiance to you, show allegiance to my family. Give me a solemn pledge'
EXEC add_BibleVerse @BibleId, 106002013, N'that you will spare the lives of my father, mother, brothers, sisters, and all who belong to them, and rescue us from death.”'
EXEC add_BibleVerse @BibleId, 106002014, N'The men said to her, “If you die, may we die too! If you do not report what we’ve been up to, then, when the Lord hands the land over to us, we will show unswerving allegiance to you.”'
EXEC add_BibleVerse @BibleId, 106002015, N'Then Rahab let them down by a rope through the window. (Her house was built as part of the city wall; she lived in the wall.)'
EXEC add_BibleVerse @BibleId, 106002016, N'She told them, “Head to the hill country, so the ones chasing you don’t find you. Hide from them there for three days, long enough for those chasing you to return. Then you can be on your way.”'
EXEC add_BibleVerse @BibleId, 106002017, N'The men said to her, “We are not bound by this oath you made us swear unless the following conditions are met:'
EXEC add_BibleVerse @BibleId, 106002018, N'When we invade the land , tie this red rope in the window through which you let us down, and gather together in your house your father, mother, brothers, and all who live in your father’s house.'
EXEC add_BibleVerse @BibleId, 106002019, N'Anyone who leaves your house will be responsible for his own death – we are innocent in that case! But if anyone with you in the house is harmed, we will be responsible.'
EXEC add_BibleVerse @BibleId, 106002020, N'If you should report what we’ve been up to, we are not bound by this oath you made us swear.”'
EXEC add_BibleVerse @BibleId, 106002021, N'She said, “I agree to these conditions.” She sent them on their way and then tied the red rope in the window.'
EXEC add_BibleVerse @BibleId, 106002022, N'They went to the hill country and stayed there for three days, long enough for those chasing them to return. Their pursuers looked all along the way but did not find them.'
EXEC add_BibleVerse @BibleId, 106002023, N'Then the two men returned – they came down from the hills, crossed the river, came to Joshua son of Nun, and reported to him all they had discovered.'
EXEC add_BibleVerse @BibleId, 106002024, N'They told Joshua, “Surely the Lord is handing over all the land to us! All who live in the land are cringing before us!”'
EXEC add_BibleVerse @BibleId, 106003001, N'Bright and early the next morning Joshua and the Israelites left Shittim and came to the Jordan. They camped there before crossing the river.'
EXEC add_BibleVerse @BibleId, 106003002, N'After three days the leaders went through the camp'
EXEC add_BibleVerse @BibleId, 106003003, N'and commanded the people: “When you see the ark of the covenant of the Lord your God being carried by the Levitical priests, you must leave here and walk behind it.'
EXEC add_BibleVerse @BibleId, 106003004, N'But stay about three thousand feet behind it. Keep your distance so you can see which way you should go, for you have not traveled this way before.”'
EXEC add_BibleVerse @BibleId, 106003005, N'Joshua told the people, “Ritually consecrate yourselves, for tomorrow the Lord will perform miraculous deeds among you.”'
EXEC add_BibleVerse @BibleId, 106003006, N'Joshua told the priests, “Pick up the ark of the covenant and pass on ahead of the people.” So they picked up the ark of the covenant and went ahead of the people.'
EXEC add_BibleVerse @BibleId, 106003007, N'The Lord told Joshua, “This very day I will begin to honor you before all Israel so they will know that I am with you just as I was with Moses.'
EXEC add_BibleVerse @BibleId, 106003008, N'Instruct the priests carrying the ark of the covenant, ‘When you reach the bank of the Jordan River, wade into the water.’”'
EXEC add_BibleVerse @BibleId, 106003009, N'Joshua told the Israelites, “Come here and listen to the words of the Lord your God!”'
EXEC add_BibleVerse @BibleId, 106003010, N'Joshua continued, “This is how you will know the living God is among you and that he will truly drive out before you the Canaanites, Hittites, Hivites, Perizzites, Girgashites, Amorites, and Jebusites.'
EXEC add_BibleVerse @BibleId, 106003011, N'Look! The ark of the covenant of the Ruler of the whole earth is ready to enter the Jordan ahead of you.'
EXEC add_BibleVerse @BibleId, 106003012, N'Now select for yourselves twelve men from the tribes of Israel, one per tribe.'
EXEC add_BibleVerse @BibleId, 106003013, N'When the feet of the priests carrying the ark of the Lord, the Ruler of the whole earth, touch the water of the Jordan, the water coming downstream toward you will stop flowing and pile up.”'
EXEC add_BibleVerse @BibleId, 106003014, N'So when the people left their tents to cross the Jordan, the priests carrying the ark of the covenant went ahead of them.'
EXEC add_BibleVerse @BibleId, 106003015, N'When the ones carrying the ark reached the Jordan and the feet of the priests carrying the ark touched the surface of the water – (the Jordan is at flood stage all during harvest time) –'
EXEC add_BibleVerse @BibleId, 106003016, N'the water coming downstream toward them stopped flowing. It piled up far upstream at Adam (the city near Zarethan); there was no water at all flowing to the sea of the Arabah (the Salt Sea). The people crossed the river opposite Jericho.'
EXEC add_BibleVerse @BibleId, 106003017, N'The priests carrying the ark of the covenant of the Lord stood firmly on dry ground in the middle of the Jordan. All Israel crossed over on dry ground until the entire nation was on the other side.'
EXEC add_BibleVerse @BibleId, 106004001, N'When the entire nation was on the other side, the Lord told Joshua,'
EXEC add_BibleVerse @BibleId, 106004002, N'“Select for yourselves twelve men from the people, one per tribe.'
EXEC add_BibleVerse @BibleId, 106004003, N'Instruct them, ‘Pick up twelve stones from the middle of the Jordan, from the very place where the priests stand firmly, and carry them over with you and put them in the place where you camp tonight.’”'
EXEC add_BibleVerse @BibleId, 106004004, N'Joshua summoned the twelve men he had appointed from the Israelites, one per tribe.'
EXEC add_BibleVerse @BibleId, 106004005, N'Joshua told them, “Go in front of the ark of the Lord your God to the middle of the Jordan. Each of you is to put a stone on his shoulder, according to the number of the Israelite tribes.'
EXEC add_BibleVerse @BibleId, 106004006, N'The stones will be a reminder to you. When your children ask someday, ‘Why are these stones important to you?’'
EXEC add_BibleVerse @BibleId, 106004007, N'tell them how the water of the Jordan stopped flowing before the ark of the covenant of the Lord. When it crossed the Jordan, the water of the Jordan stopped flowing. These stones will be a lasting memorial for the Israelites.”'
EXEC add_BibleVerse @BibleId, 106004008, N'The Israelites did just as Joshua commanded. They picked up twelve stones, according to the number of the Israelite tribes, from the middle of the Jordan as the Lord had instructed Joshua. They carried them over with them to the camp and put them there.'
EXEC add_BibleVerse @BibleId, 106004009, N'Joshua also set up twelve stones in the middle of the Jordan in the very place where the priests carrying the ark of the covenant stood. They remain there to this very day.'
EXEC add_BibleVerse @BibleId, 106004010, N'Now the priests carrying the ark of the covenant were standing in the middle of the Jordan until everything the Lord had commanded Joshua to tell the people was accomplished, in accordance with all that Moses had commanded Joshua. The people went across quickly,'
EXEC add_BibleVerse @BibleId, 106004011, N'and when all the people had finished crossing, the ark of the Lord and the priests crossed as the people looked on.'
EXEC add_BibleVerse @BibleId, 106004012, N'The Reubenites, Gadites, and the half-tribe of Manasseh crossed over armed for battle ahead of the Israelites, just as Moses had instructed them.'
EXEC add_BibleVerse @BibleId, 106004013, N'About forty thousand battle-ready troops marched past the Lord to fight on the plains of Jericho.'
EXEC add_BibleVerse @BibleId, 106004014, N'That day the Lord brought honor to Joshua before all Israel. They respected him all his life, just as they had respected Moses.'
EXEC add_BibleVerse @BibleId, 106004015, N'The Lord told Joshua,'
EXEC add_BibleVerse @BibleId, 106004016, N'“Instruct the priests carrying the ark of the covenantal laws to come up from the Jordan.”'
EXEC add_BibleVerse @BibleId, 106004017, N'So Joshua instructed the priests, “Come up from the Jordan!”'
EXEC add_BibleVerse @BibleId, 106004018, N'The priests carrying the ark of the covenant of the Lord came up from the middle of the Jordan, and as soon as they set foot on dry land, the water of the Jordan flowed again and returned to flood stage.'
EXEC add_BibleVerse @BibleId, 106004019, N'The people went up from the Jordan on the tenth day of the first month and camped in Gilgal on the eastern border of Jericho.'
EXEC add_BibleVerse @BibleId, 106004020, N'Now Joshua set up in Gilgal the twelve stones they had taken from the Jordan.'
EXEC add_BibleVerse @BibleId, 106004021, N'He told the Israelites, “When your children someday ask their fathers, ‘What do these stones represent?’'
EXEC add_BibleVerse @BibleId, 106004022, N'explain to your children, ‘Israel crossed the Jordan River on dry ground.’'
EXEC add_BibleVerse @BibleId, 106004023, N'For the Lord your God dried up the water of the Jordan before you while you crossed over. It was just like when the Lord your God dried up the Red Sea before us while we crossed it.'
EXEC add_BibleVerse @BibleId, 106004024, N'He has done this so all the nations of the earth might recognize the Lord’s power and so you might always obey the Lord your God.”'
EXEC add_BibleVerse @BibleId, 106005001, N'When all the Amorite kings on the west side of the Jordan and all the Canaanite kings along the seacoast heard how the Lord had dried up the water of the Jordan before the Israelites while they crossed, they lost their courage and could not even breathe for fear of the Israelites.'
EXEC add_BibleVerse @BibleId, 106005002, N'At that time the Lord told Joshua, “Make flint knives and circumcise the Israelites once again.”'
EXEC add_BibleVerse @BibleId, 106005003, N'So Joshua made flint knives and circumcised the Israelites on the Hill of the Foreskins.'
EXEC add_BibleVerse @BibleId, 106005004, N'This is why Joshua had to circumcise them: All the men old enough to fight when they left Egypt died on the journey through the desert after they left Egypt.'
EXEC add_BibleVerse @BibleId, 106005005, N'Now all the men who left were circumcised, but all the sons born on the journey through the desert after they left Egypt were uncircumcised.'
EXEC add_BibleVerse @BibleId, 106005006, N'Indeed, for forty years the Israelites traveled through the desert until all the men old enough to fight when they left Egypt, the ones who had disobeyed the Lord, died off. For the Lord had sworn a solemn oath to them that he would not let them see the land he had sworn on oath to give them, a land rich in milk and honey.'
EXEC add_BibleVerse @BibleId, 106005007, N'He replaced them with their sons, whom Joshua circumcised. They were uncircumcised; their fathers had not circumcised them along the way.'
EXEC add_BibleVerse @BibleId, 106005008, N'When all the men had been circumcised, they stayed there in the camp until they had healed.'
EXEC add_BibleVerse @BibleId, 106005009, N'The Lord said to Joshua, “Today I have taken away the disgrace of Egypt from you.” So that place is called Gilgal even to this day.'
EXEC add_BibleVerse @BibleId, 106005010, N'So the Israelites camped in Gilgal and celebrated the Passover in the evening of the fourteenth day of the month on the plains of Jericho.'
EXEC add_BibleVerse @BibleId, 106005011, N'They ate some of the produce of the land the day after the Passover, including unleavened bread and roasted grain.'
EXEC add_BibleVerse @BibleId, 106005012, N'The manna stopped appearing the day they ate some of the produce of the land; the Israelites never ate manna again.'
EXEC add_BibleVerse @BibleId, 106005013, N'When Joshua was near Jericho, he looked up and saw a man standing in front of him holding a drawn sword. Joshua approached him and asked him, “Are you on our side or allied with our enemies?”'
EXEC add_BibleVerse @BibleId, 106005014, N'He answered, “Truly I am the commander of the Lord’s army. Now I have arrived!” Joshua bowed down with his face to the ground and asked, “What does my master want to say to his servant?”'
EXEC add_BibleVerse @BibleId, 106005015, N'The commander of the Lord’s army answered Joshua, “Remove your sandals from your feet, because the place where you stand is holy.” Joshua did so.'
EXEC add_BibleVerse @BibleId, 106006001, N'Now Jericho was shut tightly because of the Israelites. No one was allowed to leave or enter.'
EXEC add_BibleVerse @BibleId, 106006002, N'The Lord told Joshua, “See, I am about to defeat Jericho for you, along with its king and its warriors.'
EXEC add_BibleVerse @BibleId, 106006003, N'Have all the warriors march around the city one time; do this for six days.'
EXEC add_BibleVerse @BibleId, 106006004, N'Have seven priests carry seven rams’ horns in front of the ark. On the seventh day march around the city seven times, while the priests blow the horns.'
EXEC add_BibleVerse @BibleId, 106006005, N'When you hear the signal from the ram’s horn, have the whole army give a loud battle cry. Then the city wall will collapse and the warriors should charge straight ahead.”'
EXEC add_BibleVerse @BibleId, 106006006, N'So Joshua son of Nun summoned the priests and instructed them, “Pick up the ark of the covenant, and seven priests must carry seven rams’ horns in front of the ark of the Lord.”'
EXEC add_BibleVerse @BibleId, 106006007, N'And he told the army, “Move ahead and march around the city, with armed troops going ahead of the ark of the Lord.”'
EXEC add_BibleVerse @BibleId, 106006008, N'When Joshua gave the army its orders, the seven priests carrying the seven rams’ horns before the Lord moved ahead and blew the horns as the ark of the covenant of the Lord followed behind.'
EXEC add_BibleVerse @BibleId, 106006009, N'Armed troops marched ahead of the priests blowing the horns, while the rear guard followed along behind the ark blowing rams’ horns.'
EXEC add_BibleVerse @BibleId, 106006010, N'Now Joshua had instructed the army, “Do not give a battle cry or raise your voices; say nothing until the day I tell you, ‘Give the battle cry.’ Then give the battle cry!”'
EXEC add_BibleVerse @BibleId, 106006011, N'So Joshua made sure they marched the ark of the Lord around the city one time. Then they went back to the camp and spent the night there.'
EXEC add_BibleVerse @BibleId, 106006012, N'Bright and early the next morning Joshua had the priests pick up the ark of the Lord.'
EXEC add_BibleVerse @BibleId, 106006013, N'The seven priests carrying the seven rams’ horns before the ark of the Lord marched along blowing their horns. Armed troops marched ahead of them, while the rear guard followed along behind the ark of the Lord blowing rams’ horns.'
EXEC add_BibleVerse @BibleId, 106006014, N'They marched around the city one time on the second day, then returned to the camp. They did this six days in all.'
EXEC add_BibleVerse @BibleId, 106006015, N'On the seventh day they were up at the crack of dawn and marched around the city as before – only this time they marched around it seven times.'
EXEC add_BibleVerse @BibleId, 106006016, N'The seventh time around, the priests blew the rams’ horns and Joshua told the army, “Give the battle cry, for the Lord is handing the city over to you!'
EXEC add_BibleVerse @BibleId, 106006017, N'The city and all that is in it must be set apart for the Lord, except for Rahab the prostitute and all who are with her in her house, because she hid the spies we sent.'
EXEC add_BibleVerse @BibleId, 106006018, N'But be careful when you are setting apart the riches for the Lord. If you take any of it, you will make the Israelite camp subject to annihilation and cause a disaster.'
EXEC add_BibleVerse @BibleId, 106006019, N'All the silver and gold, as well as bronze and iron items, belong to the Lord. They must go into the Lord’s treasury.”'
EXEC add_BibleVerse @BibleId, 106006020, N'The rams’ horns sounded and when the army heard the signal, they gave a loud battle cry. The wall collapsed and the warriors charged straight ahead into the city and captured it.'
EXEC add_BibleVerse @BibleId, 106006021, N'They annihilated with the sword everything that breathed in the city, including men and women, young and old, as well as cattle, sheep, and donkeys.'
EXEC add_BibleVerse @BibleId, 106006022, N'Joshua told the two men who had spied on the land, “Enter the prostitute’s house and bring out the woman and all who belong to her as you promised her.”'
EXEC add_BibleVerse @BibleId, 106006023, N'So the young spies went and brought out Rahab, her father, mother, brothers, and all who belonged to her. They brought out her whole family and took them to a place outside the Israelite camp.'
EXEC add_BibleVerse @BibleId, 106006024, N'But they burned the city and all that was in it, except for the silver, gold, and bronze and iron items they put in the treasury of the Lord’s house.'
EXEC add_BibleVerse @BibleId, 106006025, N'Yet Joshua spared Rahab the prostitute, her father’s family, and all who belonged to her. She lives in Israel to this very day because she hid the messengers Joshua sent to spy on Jericho.'
EXEC add_BibleVerse @BibleId, 106006026, N'At that time Joshua made this solemn declaration: “The man who attempts to rebuild this city of Jericho will stand condemned before the Lord. He will lose his firstborn son when he lays its foundations and his youngest son when he erects its gates!”'
EXEC add_BibleVerse @BibleId, 106006027, N'The Lord was with Joshua and he became famous throughout the land.'
EXEC add_BibleVerse @BibleId, 106007001, N'But the Israelites disobeyed the command about the city’s riches. Achan son of Carmi, son of Zabdi, son of Zerah, from the tribe of Judah, stole some of the riches. The Lord was furious with the Israelites.'
EXEC add_BibleVerse @BibleId, 106007002, N'Joshua sent men from Jericho ) and instructed them, “Go up and spy on the land.” So the men went up and spied on Ai.'
EXEC add_BibleVerse @BibleId, 106007003, N'They returned and reported to Joshua, “Don’t send the whole army. About two or three thousand men are adequate to defeat Ai. Don’t tire out the whole army, for Ai is small.”'
EXEC add_BibleVerse @BibleId, 106007004, N'So about three thousand men went up, but they fled from the men of Ai.'
EXEC add_BibleVerse @BibleId, 106007005, N'The men of Ai killed about thirty-six of them and chased them from in front of the city gate all the way to the fissures and defeated them on the steep slope. The people’s courage melted away like water.'
EXEC add_BibleVerse @BibleId, 106007006, N'Joshua tore his clothes; he and the leaders of Israel lay face down on the ground before the ark of the Lord until evening and threw dirt on their heads.'
EXEC add_BibleVerse @BibleId, 106007007, N'Joshua prayed, “O, Master, Lord! Why did you bring these people across the Jordan to hand us over to the Amorites so they could destroy us?'
EXEC add_BibleVerse @BibleId, 106007008, N'If only we had been satisfied to live on the other side of the Jordan! O Lord, what can I say now that Israel has retreated before its enemies?'
EXEC add_BibleVerse @BibleId, 106007009, N'When the Canaanites and all who live in the land hear about this, they will turn against us and destroy the very memory of us from the earth. What will you do to protect your great reputation?”'
EXEC add_BibleVerse @BibleId, 106007010, N'The Lord responded to Joshua, “Get up! Why are you lying there face down?'
EXEC add_BibleVerse @BibleId, 106007011, N'Israel has sinned; they have violated my covenantal commandment! They have taken some of the riches; they have stolen them and deceitfully put them among their own possessions.'
EXEC add_BibleVerse @BibleId, 106007012, N'The Israelites are unable to stand before their enemies; they retreat because they have become subject to annihilation. I will no longer be with you, unless you destroy what has contaminated you.'
EXEC add_BibleVerse @BibleId, 106007013, N'Get up! Ritually consecrate the people and tell them this: ‘Ritually consecrate yourselves for tomorrow, because the Lord God of Israel says, “You are contaminated, O Israel! You will not be able to stand before your enemies until you remove what is contaminating you.”'
EXEC add_BibleVerse @BibleId, 106007014, N'In the morning you must approach in tribal order. The tribe the Lord selects must approach by clans. The clan the Lord selects must approach by families. The family the Lord selects must approach man by man.'
EXEC add_BibleVerse @BibleId, 106007015, N'The one caught with the riches must be burned up along with all who belong to him, because he violated the Lord’s covenant and did such a disgraceful thing in Israel.’”'
EXEC add_BibleVerse @BibleId, 106007016, N'Bright and early the next morning Joshua made Israel approach in tribal order and the tribe of Judah was selected.'
EXEC add_BibleVerse @BibleId, 106007017, N'He then made the clans of Judah approach and the clan of the Zerahites was selected. He made the clan of the Zerahites approach and Zabdi was selected.'
EXEC add_BibleVerse @BibleId, 106007018, N'He then made Zabdi’s family approach man by man and Achan son of Carmi, son of Zabdi, son of Zerah, from the tribe of Judah, was selected.'
EXEC add_BibleVerse @BibleId, 106007019, N'So Joshua said to Achan, “My son, honor the Lord God of Israel and give him praise! Tell me what you did; don’t hide anything from me!”'
EXEC add_BibleVerse @BibleId, 106007020, N'Achan told Joshua, “It is true. I have sinned against the Lord God of Israel in this way:'
EXEC add_BibleVerse @BibleId, 106007021, N'I saw among the goods we seized a nice robe from Babylon, two hundred silver pieces, and a bar of gold weighing fifty shekels. I wanted them, so I took them. They are hidden in the ground right in the middle of my tent with the silver underneath.”'
EXEC add_BibleVerse @BibleId, 106007022, N'Joshua sent messengers who ran to the tent. The things were hidden right in his tent, with the silver underneath.'
EXEC add_BibleVerse @BibleId, 106007023, N'They took it all from the middle of the tent, brought it to Joshua and all the Israelites, and placed it before the Lord.'
EXEC add_BibleVerse @BibleId, 106007024, N'Then Joshua and all Israel took Achan, son of Zerah, along with the silver, the robe, the bar of gold, his sons, daughters, ox, donkey, sheep, tent, and all that belonged to him and brought them up to the Valley of Disaster.'
EXEC add_BibleVerse @BibleId, 106007025, N'Joshua said, “Why have you brought disaster on us? The Lord will bring disaster on you today!” All Israel stoned him to death. (They also stoned and burned the others.)'
EXEC add_BibleVerse @BibleId, 106007026, N'Then they erected over him a large pile of stones (it remains to this very day ) and the Lord’s anger subsided. So that place is called the Valley of Disaster to this very day.'
EXEC add_BibleVerse @BibleId, 106008001, N'The Lord told Joshua, “Don’t be afraid and don’t panic! Take the whole army with you and march against Ai! See, I am handing over to you the king of Ai, along with his people, city, and land.'
EXEC add_BibleVerse @BibleId, 106008002, N'Do to Ai and its king what you did to Jericho and its king, except you may plunder its goods and cattle. Set an ambush behind the city!”'
EXEC add_BibleVerse @BibleId, 106008003, N'Joshua and the whole army marched against Ai. Joshua selected thirty thousand brave warriors and sent them out at night.'
EXEC add_BibleVerse @BibleId, 106008004, N'He told them, “Look, set an ambush behind the city. Don’t go very far from the city; all of you be ready!'
EXEC add_BibleVerse @BibleId, 106008005, N'I and all the troops who are with me will approach the city. When they come out to fight us like before, we will retreat from them.'
EXEC add_BibleVerse @BibleId, 106008006, N'They will attack us until we have lured them from the city, for they will say, ‘They are retreating from us like before.’ We will retreat from them.'
EXEC add_BibleVerse @BibleId, 106008007, N'Then you rise up from your hiding place and seize the city. The Lord your God will hand it over to you.'
EXEC add_BibleVerse @BibleId, 106008008, N'When you capture the city, set it on fire. Do as the Lord says! See, I have given you orders.”'
EXEC add_BibleVerse @BibleId, 106008009, N'Joshua sent them away and they went to their hiding place west of Ai, between Bethel and Ai. Joshua spent that night with the army.'
EXEC add_BibleVerse @BibleId, 106008010, N'Bright and early the next morning Joshua gathered the army, and he and the leaders of Israel marched at the head of it to Ai.'
EXEC add_BibleVerse @BibleId, 106008011, N'All the troops that were with him marched up and drew near the city. They camped north of Ai on the other side of the valley.'
EXEC add_BibleVerse @BibleId, 106008012, N'He took five thousand men and set an ambush west of the city between Bethel and Ai.'
EXEC add_BibleVerse @BibleId, 106008013, N'The army was in position – the main army north of the city and the rear guard west of the city. That night Joshua went into the middle of the valley.'
EXEC add_BibleVerse @BibleId, 106008014, N'When the king of Ai saw Israel, he and his whole army quickly got up the next day and went out to fight Israel at the meeting place near the Arabah. But he did not realize men were hiding behind the city.'
EXEC add_BibleVerse @BibleId, 106008015, N'Joshua and all Israel pretended to be defeated by them and they retreated along the way to the desert.'
EXEC add_BibleVerse @BibleId, 106008016, N'All the reinforcements in Ai were ordered to chase them; they chased Joshua and were lured away from the city.'
EXEC add_BibleVerse @BibleId, 106008017, N'No men were left in Ai or Bethel; they all went out after Israel. They left the city wide open and chased Israel.'
EXEC add_BibleVerse @BibleId, 106008018, N'The Lord told Joshua, “Hold out toward Ai the curved sword in your hand, for I am handing the city over to you.” So Joshua held out toward Ai the curved sword in his hand.'
EXEC add_BibleVerse @BibleId, 106008019, N'When he held out his hand, the men waiting in ambush rose up quickly from their place and attacked. They entered the city, captured it, and immediately set it on fire.'
EXEC add_BibleVerse @BibleId, 106008020, N'When the men of Ai turned around, they saw the smoke from the city ascending into the sky and were so shocked they were unable to flee in any direction. In the meantime the men who were retreating to the desert turned against their pursuers.'
EXEC add_BibleVerse @BibleId, 106008021, N'When Joshua and all Israel saw that the men in ambush had captured the city and that the city was going up in smoke, they turned around and struck down the men of Ai.'
EXEC add_BibleVerse @BibleId, 106008022, N'At the same time the men who had taken the city came out to fight, and the men of Ai were trapped in the middle. The Israelites struck them down, leaving no survivors or refugees.'
EXEC add_BibleVerse @BibleId, 106008023, N'But they captured the king of Ai alive and brought him to Joshua.'
EXEC add_BibleVerse @BibleId, 106008024, N'When Israel had finished killing all the men of Ai who had chased them toward the desert (they all fell by the sword), all Israel returned to Ai and put the sword to it.'
EXEC add_BibleVerse @BibleId, 106008025, N'Twelve thousand men and women died that day, including all the men of Ai.'
EXEC add_BibleVerse @BibleId, 106008026, N'Joshua kept holding out his curved sword until Israel had annihilated all who lived in Ai.'
EXEC add_BibleVerse @BibleId, 106008027, N'But Israel did plunder the cattle and the goods of the city, in accordance with the Lord’s orders to Joshua.'
EXEC add_BibleVerse @BibleId, 106008028, N'Joshua burned Ai and made it a permanently uninhabited mound (it remains that way to this very day).'
EXEC add_BibleVerse @BibleId, 106008029, N'He hung the king of Ai on a tree, leaving him exposed until evening. At sunset Joshua ordered that his corpse be taken down from the tree. They threw it down at the entrance of the city gate and erected over it a large pile of stones (it remains to this very day).'
EXEC add_BibleVerse @BibleId, 106008030, N'Then Joshua built an altar for the Lord God of Israel on Mount Ebal,'
EXEC add_BibleVerse @BibleId, 106008031, N'just as Moses the Lord’s servant had commanded the Israelites. As described in the law scroll of Moses, it was made with uncut stones untouched by an iron tool. They offered burnt sacrifices on it and sacrificed tokens of peace.'
EXEC add_BibleVerse @BibleId, 106008032, N'There, in the presence of the Israelites, Joshua inscribed on the stones a duplicate of the law written by Moses.'
EXEC add_BibleVerse @BibleId, 106008033, N'All the people, rulers, leaders, and judges were standing on either side of the ark, in front of the Levitical priests who carried the ark of the covenant of the Lord. Both resident foreigners and native Israelites were there. Half the people stood in front of Mount Gerizim and the other half in front of Mount Ebal, as Moses the Lord’s servant had previously instructed to them to do for the formal blessing ceremony.'
EXEC add_BibleVerse @BibleId, 106008034, N'Then Joshua read aloud all the words of the law, including the blessings and the curses, just as they are written in the law scroll.'
EXEC add_BibleVerse @BibleId, 106008035, N'Joshua read aloud every commandment Moses had given before the whole assembly of Israel, including the women, children, and resident foreigners who lived among them.'
EXEC add_BibleVerse @BibleId, 106009001, N'When the news reached all the kings on the west side of the Jordan – in the hill country, the lowlands, and all along the Mediterranean coast as far as Lebanon (including the Hittites, Amorites, Canaanites, Perizzites, Hivites, and Jebusites) –'
EXEC add_BibleVerse @BibleId, 106009002, N'they formed an alliance to fight against Joshua and Israel.'
EXEC add_BibleVerse @BibleId, 106009003, N'When the residents of Gibeon heard what Joshua did to Jericho and Ai,'
EXEC add_BibleVerse @BibleId, 106009004, N'they did something clever. They collected some provisions and put worn-out sacks on their donkeys, along with worn-out wineskins that were ripped and patched.'
EXEC add_BibleVerse @BibleId, 106009005, N'They had worn-out, patched sandals on their feet and dressed in worn-out clothes. All their bread was dry and hard.'
EXEC add_BibleVerse @BibleId, 106009006, N'They came to Joshua at the camp in Gilgal and said to him and the men of Israel, “We have come from a distant land. Make a treaty with us.”'
EXEC add_BibleVerse @BibleId, 106009007, N'The men of Israel said to the Hivites, “Perhaps you live near us. So how can we make a treaty with you?”'
EXEC add_BibleVerse @BibleId, 106009008, N'But they said to Joshua, “We are willing to be your subjects.” So Joshua said to them, “Who are you and where do you come from?”'
EXEC add_BibleVerse @BibleId, 106009009, N'They told him, “Your subjects have come from a very distant land because of the reputation of the Lord your God, for we have heard the news about all he did in Egypt'
EXEC add_BibleVerse @BibleId, 106009010, N'and all he did to the two Amorite kings on the other side of the Jordan – King Sihon of Heshbon and King Og of Bashan in Ashtaroth.'
EXEC add_BibleVerse @BibleId, 106009011, N'Our leaders and all who live in our land told us, ‘Take provisions for your journey and go meet them. Tell them, “We are willing to be your subjects. Make a treaty with us.”’'
EXEC add_BibleVerse @BibleId, 106009012, N'This bread of ours was warm when we packed it in our homes the day we started out to meet you, but now it is dry and hard.'
EXEC add_BibleVerse @BibleId, 106009013, N'These wineskins we filled were brand new, but look how they have ripped. Our clothes and sandals have worn out because it has been a very long journey.”'
EXEC add_BibleVerse @BibleId, 106009014, N'The men examined some of their provisions, but they failed to ask the Lord’s advice.'
EXEC add_BibleVerse @BibleId, 106009015, N'Joshua made a peace treaty with them and agreed to let them live. The leaders of the community sealed it with an oath.'
EXEC add_BibleVerse @BibleId, 106009016, N'Three days after they made the treaty with them, the Israelites found out they were from the local area and lived nearby.'
EXEC add_BibleVerse @BibleId, 106009017, N'So the Israelites set out and on the third day arrived at their cities – Gibeon, Kephirah, Beeroth, and Kiriath Jearim.'
EXEC add_BibleVerse @BibleId, 106009018, N'The Israelites did not attack them because the leaders of the community had sworn an oath to them in the name of the Lord God of Israel. The whole community criticized the leaders,'
EXEC add_BibleVerse @BibleId, 106009019, N'but all the leaders told the whole community, “We swore an oath to them in the name of the Lord God of Israel. So now we can’t hurt them!'
EXEC add_BibleVerse @BibleId, 106009020, N'We must let them live so we can escape the curse attached to the oath we swore to them.”'
EXEC add_BibleVerse @BibleId, 106009021, N'The leaders then added, “Let them live.” So they became woodcutters and water carriers for the whole community, as the leaders had decided.'
EXEC add_BibleVerse @BibleId, 106009022, N'Joshua summoned the Gibeonites and said to them, “Why did you trick us by saying, ‘We live far away from you,’ when you really live nearby?'
EXEC add_BibleVerse @BibleId, 106009023, N'Now you are condemned to perpetual servitude as woodcutters and water carriers for the house of my God.”'
EXEC add_BibleVerse @BibleId, 106009024, N'They said to Joshua, “It was carefully reported to your subjects how the Lord your God commanded Moses his servant to assign you the whole land and to destroy all who live in the land from before you. Because of you we were terrified we would lose our lives, so we did this thing.'
EXEC add_BibleVerse @BibleId, 106009025, N'So now we are in your power. Do to us what you think is good and appropriate.'
EXEC add_BibleVerse @BibleId, 106009026, N'Joshua did as they said; he kept the Israelites from killing them'
EXEC add_BibleVerse @BibleId, 106009027, N'and that day made them woodcutters and water carriers for the community and for the altar of the Lord at the divinely chosen site. (They continue in that capacity to this very day.)'
EXEC add_BibleVerse @BibleId, 106010001, N'Adoni-Zedek, king of Jerusalem, and its king. He also heard how the people of Gibeon made peace with Israel and lived among them.'
EXEC add_BibleVerse @BibleId, 106010002, N'All Jerusalem was terrified because Gibeon was a large city, like one of the royal cities. It was larger than Ai and all its men were warriors.'
EXEC add_BibleVerse @BibleId, 106010003, N'So King Adoni-Zedek of Jerusalem sent this message to King Hoham of Hebron, King Piram of Jarmuth, King Japhia of Lachish, and King Debir of Eglon:'
EXEC add_BibleVerse @BibleId, 106010004, N'“Come to my aid so we can attack Gibeon, for it has made peace with Joshua and the Israelites.”'
EXEC add_BibleVerse @BibleId, 106010005, N'So the five Amorite kings (the kings of Jerusalem, Hebron, Jarmuth, Lachish, and Eglon) and all their troops gathered together and advanced. They deployed their troops and fought against Gibeon.'
EXEC add_BibleVerse @BibleId, 106010006, N'The men of Gibeon sent this message to Joshua at the camp in Gilgal, “Do not abandon your subjects! Rescue us! Help us! For all the Amorite kings living in the hill country are attacking us.”'
EXEC add_BibleVerse @BibleId, 106010007, N'So Joshua and his whole army, including the bravest warriors, marched up from Gilgal.'
EXEC add_BibleVerse @BibleId, 106010008, N'The Lord told Joshua, “Don’t be afraid of them, for I am handing them over to you. Not one of them can resist you.”'
EXEC add_BibleVerse @BibleId, 106010009, N'Joshua attacked them by surprise after marching all night from Gilgal.'
EXEC add_BibleVerse @BibleId, 106010010, N'The Lord routed them before Israel. Israel thoroughly defeated them at Gibeon. They chased them up the road to the pass of Beth Horon and struck them down all the way to Azekah and Makkedah.'
EXEC add_BibleVerse @BibleId, 106010011, N'As they fled from Israel on the slope leading down from Beth Horon, the Lord threw down on them large hailstones from the sky, all the way to Azekah. They died – in fact, more died from the hailstones than the Israelites killed with the sword.'
EXEC add_BibleVerse @BibleId, 106010012, N'The day the Lord delivered the Amorites over to the Israelites, Joshua prayed to the Lord before Israel: “O sun, stand still over Gibeon! O moon, over the Valley of Aijalon!”'
EXEC add_BibleVerse @BibleId, 106010013, N'The sun stood still and the moon stood motionless while the nation took vengeance on its enemies. The event is recorded in the Scroll of the Upright One. The sun stood motionless in the middle of the sky and did not set for about a full day.'
EXEC add_BibleVerse @BibleId, 106010014, N'There has not been a day like it before or since. The Lord obeyed a man, for the Lord fought for Israel!'
EXEC add_BibleVerse @BibleId, 106010015, N'Then Joshua and all Israel returned to the camp at Gilgal.'
EXEC add_BibleVerse @BibleId, 106010016, N'The five Amorite kings ran away and hid in the cave at Makkedah.'
EXEC add_BibleVerse @BibleId, 106010017, N'Joshua was told, “The five kings have been found hiding in the cave at Makkedah.”'
EXEC add_BibleVerse @BibleId, 106010018, N'Joshua said, “Roll large stones over the mouth of the cave and post guards in front of it.'
EXEC add_BibleVerse @BibleId, 106010019, N'But don’t you delay! Chase your enemies and catch them! Don’t allow them to retreat to their cities, for the Lord your God is handing them over to you.”'
EXEC add_BibleVerse @BibleId, 106010020, N'Joshua and the Israelites almost totally wiped them out, but some survivors did escape to the fortified cities.'
EXEC add_BibleVerse @BibleId, 106010021, N'Then the whole army safely returned to Joshua at the camp in Makkedah. No one dared threaten the Israelites.'
EXEC add_BibleVerse @BibleId, 106010022, N'Joshua said, “Open the cave’s mouth and bring the five kings out of the cave to me.”'
EXEC add_BibleVerse @BibleId, 106010023, N'They did as ordered; they brought the five kings out of the cave to him – the kings of Jerusalem, Hebron, Jarmuth, Lachish, and Eglon.'
EXEC add_BibleVerse @BibleId, 106010024, N'When they brought the kings out to Joshua, he summoned all the men of Israel and said to the commanders of the troops who accompanied him, “Come here and put your feet on the necks of these kings.” So they came up and put their feet on their necks.'
EXEC add_BibleVerse @BibleId, 106010025, N'Then Joshua said to them, “Don’t be afraid and don’t panic! Be strong and brave, for the Lord will do the same thing to all your enemies you fight.'
EXEC add_BibleVerse @BibleId, 106010026, N'Then Joshua executed them and hung them on five trees. They were left hanging on the trees until evening.'
EXEC add_BibleVerse @BibleId, 106010027, N'At sunset Joshua ordered his men to take them down from the trees. They threw them into the cave where they had hidden and piled large stones over the mouth of the cave. (They remain to this very day.)'
EXEC add_BibleVerse @BibleId, 106010028, N'That day Joshua captured Makkedah and put the sword to it and its king. He annihilated everyone who lived in it; he left no survivors. He did to its king what he had done to the king of Jericho.'
EXEC add_BibleVerse @BibleId, 106010029, N'Joshua and all Israel marched from Makkedah to Libnah and fought against it.'
EXEC add_BibleVerse @BibleId, 106010030, N'The Lord handed it and its king over to Israel, and Israel put the sword to all who lived there; they left no survivors. They did to its king what they had done to the king of Jericho.'
EXEC add_BibleVerse @BibleId, 106010031, N'Joshua and all Israel marched from Libnah to Lachish. He deployed his troops and fought against it.'
EXEC add_BibleVerse @BibleId, 106010032, N'The Lord handed Lachish over to Israel and they captured it on the second day. They put the sword to all who lived there, just as they had done to Libnah.'
EXEC add_BibleVerse @BibleId, 106010033, N'Then King Horam of Gezer came up to help Lachish, but Joshua struck down him and his army until no survivors remained.'
EXEC add_BibleVerse @BibleId, 106010034, N'Joshua and all Israel marched from Lachish to Eglon. They deployed troops and fought against it.'
EXEC add_BibleVerse @BibleId, 106010035, N'That day they captured it and put the sword to all who lived there. That day they annihilated it just as they had done to Lachish.'
EXEC add_BibleVerse @BibleId, 106010036, N'Joshua and all Israel marched up from Eglon to Hebron and fought against it.'
EXEC add_BibleVerse @BibleId, 106010037, N'They captured it and put the sword to its king, all its surrounding cities, and all who lived in it; they left no survivors. As they had done at Eglon, they annihilated it and all who lived there.'
EXEC add_BibleVerse @BibleId, 106010038, N'Joshua and all Israel turned to Debir and fought against it.'
EXEC add_BibleVerse @BibleId, 106010039, N'They captured it, its king, and all its surrounding cities and put the sword to them. They annihilated everyone who lived there; they left no survivors. They did to Debir and its king what they had done to Libnah and its king and to Hebron.'
EXEC add_BibleVerse @BibleId, 106010040, N'Joshua defeated the whole land, including the hill country, the Negev, the lowlands, the slopes, and all their kings. He left no survivors. He annihilated everything that breathed, just as the Lord God of Israel had commanded.'
EXEC add_BibleVerse @BibleId, 106010041, N'Joshua conquered the area between Kadesh Barnea and Gaza and the whole region of Goshen, all the way to Gibeon.'
EXEC add_BibleVerse @BibleId, 106010042, N'Joshua captured in one campaign all these kings and their lands, for the Lord God of Israel fought for Israel.'
EXEC add_BibleVerse @BibleId, 106010043, N'Then Joshua and all Israel returned to the camp at Gilgal.'
EXEC add_BibleVerse @BibleId, 106011001, N'When King Jabin of Hazor heard the news, he organized a coalition, including King Jobab of Madon, the king of Shimron, the king of Acshaph,'
EXEC add_BibleVerse @BibleId, 106011002, N'and the northern kings who ruled in the hill country, the Arabah south of Kinnereth, the lowlands, and the heights of Dor to the west.'
EXEC add_BibleVerse @BibleId, 106011003, N'Canaanites came from the east and west; Amorites, Hittites, Perizzites, and Jebusites from the hill country; and Hivites from below Hermon in the area of Mizpah.'
EXEC add_BibleVerse @BibleId, 106011004, N'These kings came out with their armies; they were as numerous as the sand on the seashore and had a large number of horses and chariots.'
EXEC add_BibleVerse @BibleId, 106011005, N'All these kings gathered and joined forces at the Waters of Merom to fight Israel.'
EXEC add_BibleVerse @BibleId, 106011006, N'The Lord told Joshua, “Don’t be afraid of them, for about this time tomorrow I will cause all of them to lie dead before Israel. You must hamstring their horses and burn their chariots.”'
EXEC add_BibleVerse @BibleId, 106011007, N'Joshua and his whole army caught them by surprise at the Waters of Merom and attacked them.'
EXEC add_BibleVerse @BibleId, 106011008, N'The Lord handed them over to Israel and they struck them down and chased them all the way to Greater Sidon, Misrephoth Maim, and the Mizpah Valley to the east. They struck them down until no survivors remained.'
EXEC add_BibleVerse @BibleId, 106011009, N'Joshua did to them as the Lord had commanded him; he hamstrung their horses and burned their chariots.'
EXEC add_BibleVerse @BibleId, 106011010, N'At that time Joshua turned, captured Hazor, and struck down its king with the sword, for Hazor was at that time the leader of all these kingdoms.'
EXEC add_BibleVerse @BibleId, 106011011, N'They annihilated everyone who lived there with the sword – no one who breathed remained – and burned Hazor.'
EXEC add_BibleVerse @BibleId, 106011012, N'Joshua captured all these royal cities and all their kings and annihilated them with the sword, as Moses the Lord’s servant had commanded.'
EXEC add_BibleVerse @BibleId, 106011013, N'But Israel did not burn any of the cities located on mounds, except for Hazor; it was the only one Joshua burned.'
EXEC add_BibleVerse @BibleId, 106011014, N'The Israelites plundered all the goods of these cities and the cattle, but they totally destroyed all the people and allowed no one who breathed to live.'
EXEC add_BibleVerse @BibleId, 106011015, N'Moses the Lord’s servant passed on the Lord’s commands to Joshua, and Joshua did as he was told. He did not ignore any of the commands the Lord had given Moses.'
EXEC add_BibleVerse @BibleId, 106011016, N'Joshua conquered the whole land, including the hill country, all the Negev, all the land of Goshen, the lowlands, the Arabah, the hill country of Israel and its lowlands,'
EXEC add_BibleVerse @BibleId, 106011017, N'from Mount Halak on up to Seir, as far as Baal Gad in the Lebanon Valley below Mount Hermon. He captured all their kings and executed them.'
EXEC add_BibleVerse @BibleId, 106011018, N'Joshua campaigned against these kings for quite some time.'
EXEC add_BibleVerse @BibleId, 106011019, N'No city made peace with the Israelites (except the Hivites living in Gibeon); they had to conquer all of them,'
EXEC add_BibleVerse @BibleId, 106011020, N'for the Lord determined to make them obstinate so they would attack Israel. He wanted Israel to annihilate them without mercy, as he had instructed Moses.'
EXEC add_BibleVerse @BibleId, 106011021, N'At that time Joshua attacked and eliminated the Anakites from the hill country – from Hebron, Debir, Anab, and all the hill country of Judah and Israel. Joshua annihilated them and their cities.'
EXEC add_BibleVerse @BibleId, 106011022, N'No Anakites were left in Israelite territory, though some remained in Gaza, Gath, and Ashdod.'
EXEC add_BibleVerse @BibleId, 106011023, N'Joshua conquered the whole land, just as the Lord had promised Moses, and he assigned Israel their tribal portions. Then the land was free of war.'
EXEC add_BibleVerse @BibleId, 106012001, N'Now these are the kings of the land whom the Israelites defeated and drove from their land on the east side of the Jordan, from the Arnon Valley to Mount Hermon, including all the eastern Arabah:'
EXEC add_BibleVerse @BibleId, 106012002, N'King Sihon of the Amorites who lived in Heshbon and ruled from Aroer (on the edge of the Arnon Valley) – including the city in the middle of the valley and half of Gilead – all the way to the Jabbok Valley bordering Ammonite territory.'
EXEC add_BibleVerse @BibleId, 106012003, N'His kingdom included the eastern Arabah from the Sea of Kinnereth to the Sea of the Arabah (the Salt Sea), including the route to Beth Jeshimoth and the area southward below the slopes of Pisgah.'
EXEC add_BibleVerse @BibleId, 106012004, N'The territory of King Og of Bashan, one of the few remaining Rephaites, who lived in Ashtaroth and Edrei'
EXEC add_BibleVerse @BibleId, 106012005, N'and ruled over Mount Hermon, Salecah, all of Bashan to the border of the Geshurites and Maacathites, and half of Gilead as far as the border of King Sihon of Heshbon.'
EXEC add_BibleVerse @BibleId, 106012006, N'Moses the Lord’s servant and the Israelites defeated them and Moses the Lord’s servant assigned their land to Reuben, Gad, and the half tribe of Manasseh.'
EXEC add_BibleVerse @BibleId, 106012007, N'These are the kings of the land whom Joshua and the Israelites defeated on the west side of the Jordan, from Baal Gad in the Lebanon Valley to Mount Halak on up to Seir. Joshua assigned this territory to the Israelite tribes,'
EXEC add_BibleVerse @BibleId, 106012008, N'including the hill country, the lowlands, the Arabah, the slopes, the wilderness, and the Negev – the land of the Hittites, Amorites, Canaanites, Perizzites, Hivites, and Jebusites:'
EXEC add_BibleVerse @BibleId, 106012009, N'the king of Jericho (one), the king of Ai – located near Bethel – (one),'
EXEC add_BibleVerse @BibleId, 106012010, N'the king of Jerusalem (one), the king of Hebron (one),'
EXEC add_BibleVerse @BibleId, 106012011, N'the king of Jarmuth (one), the king of Lachish (one),'
EXEC add_BibleVerse @BibleId, 106012012, N'the king of Eglon (one), the king of Gezer (one),'
EXEC add_BibleVerse @BibleId, 106012013, N'the king of Debir (one), the king of Geder (one),'
EXEC add_BibleVerse @BibleId, 106012014, N'the king of Hormah (one), the king of Arad (one),'
EXEC add_BibleVerse @BibleId, 106012015, N'the king of Libnah (one), the king of Adullam (one),'
EXEC add_BibleVerse @BibleId, 106012016, N'the king of Makkedah (one), the king of Bethel (one),'
EXEC add_BibleVerse @BibleId, 106012017, N'the king of Tappuah (one), the king of Hepher (one),'
EXEC add_BibleVerse @BibleId, 106012018, N'the king of Aphek (one), the king of Lasharon (one),'
EXEC add_BibleVerse @BibleId, 106012019, N'the king of Madon (one), the king of Hazor (one),'
EXEC add_BibleVerse @BibleId, 106012020, N'the king of Shimron Meron (one), the king of Acshaph (one),'
EXEC add_BibleVerse @BibleId, 106012021, N'the king of Taanach (one), the king of Megiddo (one),'
EXEC add_BibleVerse @BibleId, 106012022, N'the king of Kedesh (one), the king of Jokneam near Carmel (one),'
EXEC add_BibleVerse @BibleId, 106012023, N'the king of Dor – near Naphath Dor – (one), the king of Goyim – near Gilgal – (one),'
EXEC add_BibleVerse @BibleId, 106012024, N'the king of Tirzah (one), a total of thirty-one kings.'
EXEC add_BibleVerse @BibleId, 106013001, N'When Joshua was very old, the Lord told him, “You are very old, and a great deal of land remains to be conquered.'
EXEC add_BibleVerse @BibleId, 106013002, N'This is the land that remains: all the territory of the Philistines and all the Geshurites,'
EXEC add_BibleVerse @BibleId, 106013003, N'from the Shihor River east of Egypt northward to the territory of Ekron (it is regarded as Canaanite territory), including the area belonging to the five Philistine lords who ruled in Gaza, Ashdod, Ashkelon, Gath, and Ekron, as well as Avvite land'
EXEC add_BibleVerse @BibleId, 106013004, N'to the south; all the Canaanite territory, from Arah in the region of Sidon to Aphek, as far as Amorite territory;'
EXEC add_BibleVerse @BibleId, 106013005, N'the territory of Byblos and all Lebanon to the east, from Baal Gad below Mount Hermon to Lebo Hamath.'
EXEC add_BibleVerse @BibleId, 106013006, N'I will drive out before the Israelites all who live in the hill country from Lebanon to Misrephoth Maim, all the Sidonians; you be sure to parcel it out to Israel as I instructed you.”'
EXEC add_BibleVerse @BibleId, 106013007, N'Now, divide up this land among the nine tribes and the half-tribe of Manasseh.”'
EXEC add_BibleVerse @BibleId, 106013008, N'The other half of Manasseh, Reuben, and Gad received their allotted tribal lands beyond the Jordan, just as Moses, the Lord’s servant, had assigned them.'
EXEC add_BibleVerse @BibleId, 106013009, N'Their territory started from Aroer (on the edge of the Arnon Valley), included the city in the middle of the valley, the whole plain of Medeba as far as Dibon,'
EXEC add_BibleVerse @BibleId, 106013010, N'and all the cities of King Sihon of the Amorites who ruled in Heshbon, and ended at the Ammonite border.'
EXEC add_BibleVerse @BibleId, 106013011, N'Their territory also included Gilead, Geshurite and Maacathite territory, all Mount Hermon, and all Bashan to Salecah –'
EXEC add_BibleVerse @BibleId, 106013012, N'the whole kingdom of Og in Bashan, who ruled in Ashtaroth and Edrei. (He was one of the few remaining Rephaites.) Moses defeated them and took their lands.'
EXEC add_BibleVerse @BibleId, 106013013, N'But the Israelites did not conquer the Geshurites and Maacathites; Geshur and Maacah live among Israel to this very day.'
EXEC add_BibleVerse @BibleId, 106013014, N'However, Moses did not assign land as an inheritance to the Levites; their inheritance is the sacrificial offerings made to the Lord God of Israel, as he instructed them.'
EXEC add_BibleVerse @BibleId, 106013015, N'Moses assigned land to the tribe of Reuben by its clans.'
EXEC add_BibleVerse @BibleId, 106013016, N'Their territory started at Aroer (on the edge of the Arnon Valley) and included the city in the middle of the valley, the whole plain of Medeba,'
EXEC add_BibleVerse @BibleId, 106013017, N'Heshbon and all its surrounding cities on the plain, including Dibon, Bamoth Baal, Beth Baal Meon,'
EXEC add_BibleVerse @BibleId, 106013018, N'Jahaz, Kedemoth, Mephaath,'
EXEC add_BibleVerse @BibleId, 106013019, N'Kiriathaim, Sibmah, Zereth Shahar on the hill in the valley,'
EXEC add_BibleVerse @BibleId, 106013020, N'Beth Peor, the slopes of Pisgah, and Beth Jeshimoth.'
EXEC add_BibleVerse @BibleId, 106013021, N'It encompassed all the cities of the plain and the whole realm of King Sihon of the Amorites who ruled in Heshbon. Moses defeated him and the Midianite leaders Evi, Rekem, Zur, Hur, and Reba (they were subjects of Sihon and lived in his territory).'
EXEC add_BibleVerse @BibleId, 106013022, N'The Israelites killed Balaam son of Beor, the omen reader, along with the others.'
EXEC add_BibleVerse @BibleId, 106013023, N'The border of the tribe of Reuben was the Jordan. The land allotted to the tribe of Reuben by its clans included these cities and their towns.'
EXEC add_BibleVerse @BibleId, 106013024, N'Moses assigned land to the tribe of Gad by its clans.'
EXEC add_BibleVerse @BibleId, 106013025, N'Their territory included Jazer, all the cities of Gilead, and half of Ammonite territory as far as Aroer near Rabbah.'
EXEC add_BibleVerse @BibleId, 106013026, N'Their territory ran from Heshbon to Ramath Mizpah and Betonim, and from Mahanaim to the territory of Debir.'
EXEC add_BibleVerse @BibleId, 106013027, N'It included the valley of Beth Haram, Beth Nimrah, Succoth, and Zaphon, and the rest of the realm of King Sihon of Heshbon, the area east of the Jordan to the end of the Sea of Kinnereth.'
EXEC add_BibleVerse @BibleId, 106013028, N'The land allotted to the tribe of Gad by its clans included these cities and their towns.'
EXEC add_BibleVerse @BibleId, 106013029, N'Moses assigned land to the half-tribe of Manasseh by its clans.'
EXEC add_BibleVerse @BibleId, 106013030, N'Their territory started at Mahanaim and encompassed all Bashan, the whole realm of King Og of Bashan, including all sixty cities in Havvoth Jair in Bashan.'
EXEC add_BibleVerse @BibleId, 106013031, N'Half of Gilead, Ashtaroth, and Edrei, cities in the kingdom of Og in Bashan, were assigned to the descendants of Makir son of Manasseh, to half the descendants of Makir by their clans.'
EXEC add_BibleVerse @BibleId, 106013032, N'These are the land assignments made by Moses on the plains of Moab east of the Jordan River opposite Jericho.'
EXEC add_BibleVerse @BibleId, 106013033, N'However, Moses did not assign land as an inheritance to the Levites; their inheritance is the Lord God of Israel, as he instructed them.'
EXEC add_BibleVerse @BibleId, 106014001, N'The following is a record of the territory assigned to the Israelites in the land of Canaan by Eleazar the priest, Joshua son of Nun, and the Israelite tribal leaders.'
EXEC add_BibleVerse @BibleId, 106014002, N'The land assignments to the nine-and-a-half tribes were made by drawing lots, as the Lord had instructed Moses.'
EXEC add_BibleVerse @BibleId, 106014003, N'Now Moses had assigned land to the two-and-a-half tribes east of the Jordan, but he assigned no land to the Levites.'
EXEC add_BibleVerse @BibleId, 106014004, N'The descendants of Joseph were considered as two tribes, Manasseh and Ephraim. The Levites were allotted no territory, though they were assigned cities in which to live, along with the grazing areas for their cattle and possessions.'
EXEC add_BibleVerse @BibleId, 106014005, N'The Israelites followed the Lord’s instructions to Moses and divided up the land.'
EXEC add_BibleVerse @BibleId, 106014006, N'The men of Judah approached Joshua in Gilgal, and Caleb son of Jephunneh the Kenizzite said to him, “You know what the Lord said about you and me to Moses, the man of God, at Kadesh Barnea.'
EXEC add_BibleVerse @BibleId, 106014007, N'I was forty years old when Moses, the Lord’s servant, sent me from Kadesh Barnea to spy on the land and I brought back to him an honest report.'
EXEC add_BibleVerse @BibleId, 106014008, N'My countrymen who accompanied me frightened the people, but I remained loyal to the Lord my God.'
EXEC add_BibleVerse @BibleId, 106014009, N'That day Moses made this solemn promise: ‘Surely the land on which you walked will belong to you and your descendants permanently, for you remained loyal to the Lord your God.’'
EXEC add_BibleVerse @BibleId, 106014010, N'So now, look, the Lord has preserved my life, just as he promised, these past forty-five years since the Lord spoke these words to Moses, during which Israel traveled through the wilderness. Now look, I am today eighty-five years old.'
EXEC add_BibleVerse @BibleId, 106014011, N'Today I am still as strong as when Moses sent me out. I can fight and go about my daily activities with the same energy I had then.'
EXEC add_BibleVerse @BibleId, 106014012, N'Now, assign me this hill country which the Lord promised me at that time! No doubt you heard at that time that the Anakites live there in large, fortified cities. But, assuming the Lord is with me, I will conquer them, as the Lord promised.”'
EXEC add_BibleVerse @BibleId, 106014013, N'Joshua asked God to empower Caleb son of Jephunneh and assigned him Hebron.'
EXEC add_BibleVerse @BibleId, 106014014, N'So Hebron remains the assigned land of Caleb son of Jephunneh the Kenizzite to this very day because he remained loyal to the Lord God of Israel.'
EXEC add_BibleVerse @BibleId, 106014015, N'(Hebron used to be called Kiriath Arba. Arba was a famous Anakite. ) Then the land was free of war.'
EXEC add_BibleVerse @BibleId, 106015001, N'The land allotted to the tribe of Judah by its clans reached to the border of Edom, to the Wilderness of Zin in the Negev far to the south.'
EXEC add_BibleVerse @BibleId, 106015002, N'Their southern border started at the southern tip of the Salt Sea,'
EXEC add_BibleVerse @BibleId, 106015003, N'extended south of the Scorpion Ascent, crossed to Zin, went up from the south to Kadesh Barnea, crossed to Hezron, went up to Addar, and turned toward Karka.'
EXEC add_BibleVerse @BibleId, 106015004, N'It then crossed to Azmon, extended to the Stream of Egypt, and ended at the sea. This was their southern border.'
EXEC add_BibleVerse @BibleId, 106015005, N'The eastern border was the Salt Sea to the mouth of the Jordan River. The northern border started north of the Salt Sea at the mouth of the Jordan,'
EXEC add_BibleVerse @BibleId, 106015006, N'went up to Beth Hoglah, crossed north of Beth Arabah, and went up to the Stone of Bohan son of Reuben.'
EXEC add_BibleVerse @BibleId, 106015007, N'It then went up to Debir from the Valley of Achor, turning northward to Gilgal (which is opposite the Pass of Adummim south of the valley), crossed to the waters of En Shemesh and extended to En Rogel.'
EXEC add_BibleVerse @BibleId, 106015008, N'It then went up the Valley of Ben Hinnom to the slope of the Jebusites on the south (that is, Jerusalem), going up to the top of the hill opposite the Valley of Ben Hinnom to the west, which is at the end of the Valley of the Rephaites to the north.'
EXEC add_BibleVerse @BibleId, 106015009, N'It then went from the top of the hill to the spring of the waters of Nephtoah, extended to the cities of Mount Ephron, and went to Baalah (that is, Kiriath Jearim).'
EXEC add_BibleVerse @BibleId, 106015010, N'It then turned from Baalah westward to Mount Seir, crossed to the slope of Mount Jearim on the north (that is Kesalon), descended to Beth Shemesh, and crossed to Timnah.'
EXEC add_BibleVerse @BibleId, 106015011, N'It then extended to the slope of Ekron to the north, went toward Shikkeron, crossed to Mount Baalah, extended to Jabneel, and ended at the sea.'
EXEC add_BibleVerse @BibleId, 106015012, N'The western border was the Mediterranean Sea. These were the borders of the tribe of Judah and its clans.'
EXEC add_BibleVerse @BibleId, 106015013, N'Caleb son of Jephunneh was assigned Kiriath Arba (that is Hebron) within the tribe of Judah, according to the Lord’s instructions to Joshua. (Arba was the father of Anak.)'
EXEC add_BibleVerse @BibleId, 106015014, N'Caleb drove out from there three Anakites – Sheshai, Ahiman, and Talmai, descendants of Anak.'
EXEC add_BibleVerse @BibleId, 106015015, N'From there he attacked the people of Debir. (Debir used to be called Kiriath Sepher.)'
EXEC add_BibleVerse @BibleId, 106015016, N'Caleb said, “To the man who attacks and captures Kiriath Sepher I will give my daughter Acsah as a wife.”'
EXEC add_BibleVerse @BibleId, 106015017, N'When Othniel son of Kenaz, Caleb’s brother, captured it, Caleb gave Acsah his daughter to him as a wife.'
EXEC add_BibleVerse @BibleId, 106015018, N'One time Acsah came and charmed her father so that she could ask him for some land. When she got down from her donkey, Caleb said to her, “What would you like?”'
EXEC add_BibleVerse @BibleId, 106015019, N'She answered, “Please give me a special present. Since you have given me land in the Negev, now give me springs of water. So he gave her both upper and lower springs.'
EXEC add_BibleVerse @BibleId, 106015020, N'This is the land assigned to the tribe of Judah by its clans:'
EXEC add_BibleVerse @BibleId, 106015021, N'These cities were located at the southern extremity of Judah’s tribal land near the border of Edom: Kabzeel, Eder, Jagur,'
EXEC add_BibleVerse @BibleId, 106015022, N'Kinah, Dimonah, Adadah,'
EXEC add_BibleVerse @BibleId, 106015023, N'Kedesh, Hazor, Ithnan,'
EXEC add_BibleVerse @BibleId, 106015024, N'Ziph, Telem, Bealoth,'
EXEC add_BibleVerse @BibleId, 106015025, N'Hazor Hadattah, Kerioth Hezron (that is, Hazor),'
EXEC add_BibleVerse @BibleId, 106015026, N'Amam, Shema, Moladah,'
EXEC add_BibleVerse @BibleId, 106015027, N'Hazar Gaddah, Heshbon, Beth Pelet,'
EXEC add_BibleVerse @BibleId, 106015028, N'Hazar Shual, Beer Sheba, Biziothiah,'
EXEC add_BibleVerse @BibleId, 106015029, N'Baalah, Iim, Ezem,'
EXEC add_BibleVerse @BibleId, 106015030, N'Eltolad, Kesil, Hormah,'
EXEC add_BibleVerse @BibleId, 106015031, N'Ziklag, Madmannah, Sansannah,'
EXEC add_BibleVerse @BibleId, 106015032, N'Lebaoth, Shilhim, Ain, and Rimmon – a total of twenty-nine cities and their towns.'
EXEC add_BibleVerse @BibleId, 106015033, N'These cities were in the lowlands: Eshtaol, Zorah, Ashnah,'
EXEC add_BibleVerse @BibleId, 106015034, N'Zanoah, En Gannim, Tappuah, Enam,'
EXEC add_BibleVerse @BibleId, 106015035, N'Jarmuth, Adullam, Socoh, Azekah,'
EXEC add_BibleVerse @BibleId, 106015036, N'Shaaraim, Adithaim, and Gederah (or Gederothaim) – a total of fourteen cities and their towns.'
EXEC add_BibleVerse @BibleId, 106015037, N'Zenan, Hadashah, Migdal Gad,'
EXEC add_BibleVerse @BibleId, 106015038, N'Dilean, Mizpah, Joktheel,'
EXEC add_BibleVerse @BibleId, 106015039, N'Lachish, Bozkath, Eglon,'
EXEC add_BibleVerse @BibleId, 106015040, N'Cabbon, Lahmas, Kitlish,'
EXEC add_BibleVerse @BibleId, 106015041, N'Gederoth, Beth Dagon, Naamah, and Makkedah – a total of sixteen cities and their towns.'
EXEC add_BibleVerse @BibleId, 106015042, N'Libnah, Ether, Ashan,'
EXEC add_BibleVerse @BibleId, 106015043, N'Iphtah, Ashnah, Nezib,'
EXEC add_BibleVerse @BibleId, 106015044, N'Keilah, Aczib, and Mareshah – a total of nine cities and their towns.'
EXEC add_BibleVerse @BibleId, 106015045, N'Ekron and its surrounding towns and settlements;'
EXEC add_BibleVerse @BibleId, 106015046, N'from Ekron westward, all those in the vicinity of Ashdod and their towns;'
EXEC add_BibleVerse @BibleId, 106015047, N'Ashdod with its surrounding towns and settlements, and Gaza with its surrounding towns and settlements, as far as the Stream of Egypt and the border at the Mediterranean Sea.'
EXEC add_BibleVerse @BibleId, 106015048, N'These cities were in the hill country: Shamir, Jattir, Socoh,'
EXEC add_BibleVerse @BibleId, 106015049, N'Dannah, Kiriath Sannah (that is, Debir),'
EXEC add_BibleVerse @BibleId, 106015050, N'Anab, Eshtemoh, Anim,'
EXEC add_BibleVerse @BibleId, 106015051, N'Goshen, Holon, and Giloh – a total of eleven cities and their towns.'
EXEC add_BibleVerse @BibleId, 106015052, N'Arab, Dumah, Eshan,'
EXEC add_BibleVerse @BibleId, 106015053, N'Janim, Beth Tappuah, Aphekah,'
EXEC add_BibleVerse @BibleId, 106015054, N'Humtah, Kiriath Arba (that is, Hebron), and Zior – a total of nine cities and their towns.'
EXEC add_BibleVerse @BibleId, 106015055, N'Maon, Carmel, Ziph, Juttah,'
EXEC add_BibleVerse @BibleId, 106015056, N'Jezreel, Jokdeam, Zanoah,'
EXEC add_BibleVerse @BibleId, 106015057, N'Kain, Gibeah, and Timnah – a total of ten cities and their towns.'
EXEC add_BibleVerse @BibleId, 106015058, N'Halhul, Beth Zur, Gedor,'
EXEC add_BibleVerse @BibleId, 106015059, N'Maarath, Beth Anoth, and Eltekon – a total of six cities and their towns.'
EXEC add_BibleVerse @BibleId, 106015060, N'Kiriath Baal (that is, Kiriath Jearim) and Rabbah – a total of two cities and their towns.'
EXEC add_BibleVerse @BibleId, 106015061, N'These cities were in the desert: Beth Arabah, Middin, Secacah,'
EXEC add_BibleVerse @BibleId, 106015062, N'Nibshan, the city of Salt, and En Gedi – a total of six cities and their towns.'
EXEC add_BibleVerse @BibleId, 106015063, N'The men of Judah were unable to conquer the Jebusites living in Jerusalem. The Jebusites live with the people of Judah in Jerusalem to this very day.'
EXEC add_BibleVerse @BibleId, 106016001, N'The land allotted to Joseph’s descendants extended from the Jordan at Jericho'
EXEC add_BibleVerse @BibleId, 106016002, N'The southern border extended from Bethel to Luz, and crossed to Arkite territory at Ataroth.'
EXEC add_BibleVerse @BibleId, 106016003, N'It then descended westward to Japhletite territory, as far as the territory of lower Beth Horon and Gezer, and ended at the sea.'
EXEC add_BibleVerse @BibleId, 106016004, N'Joseph’s descendants, Manasseh and Ephraim, were assigned their land.'
EXEC add_BibleVerse @BibleId, 106016005, N'The territory of the tribe of Ephraim by its clans included the following: The border of their assigned land to the east was Ataroth Addar as far as upper Beth Horon.'
EXEC add_BibleVerse @BibleId, 106016006, N'It then extended on to the sea, with Micmethath on the north. It turned eastward to Taanath Shiloh and crossed it on the east to Janoah.'
EXEC add_BibleVerse @BibleId, 106016007, N'It then descended from Janoah to Ataroth and Naarah, touched Jericho, and extended to the Jordan River.'
EXEC add_BibleVerse @BibleId, 106016008, N'From Tappuah it went westward to the Valley of Kanah and ended at the sea. This is the land assigned to the tribe of Ephraim by its clans.'
EXEC add_BibleVerse @BibleId, 106016009, N'Also included were the cities set apart for the tribe of Ephraim within Manasseh’s territory, along with their towns.'
EXEC add_BibleVerse @BibleId, 106016010, N'The Ephraimites did not conquer the Canaanites living in Gezer. The Canaanites live among the Ephraimites to this very day and do hard labor as their servants.'
EXEC add_BibleVerse @BibleId, 106017001, N'The tribe of Manasseh, Joseph’s firstborn son, was also allotted land. The descendants of Makir, Manasseh’s firstborn and the father of Gilead, received land, for they were warriors. They were assigned Gilead and Bashan.'
EXEC add_BibleVerse @BibleId, 106017002, N'The rest of Manasseh’s descendants were also assigned land by their clans, including the descendants of Abiezer, Helek, Asriel, Shechem, Hepher, and Shemida. These are the male descendants of Manasseh son of Joseph by their clans.'
EXEC add_BibleVerse @BibleId, 106017003, N'Now Zelophehad son of Hepher, son of Gilead, son of Makir, son of Manasseh, had no sons, only daughters. These are the names of his daughters: Mahlah, Noah, Hoglah, Milcah, and Tirzah.'
EXEC add_BibleVerse @BibleId, 106017004, N'They went before Eleazar the priest, Joshua son of Nun, and the leaders and said, “The Lord told Moses to assign us land among our relatives.” So Joshua assigned them land among their uncles, as the Lord had commanded.'
EXEC add_BibleVerse @BibleId, 106017005, N'Manasseh was allotted ten shares of land, in addition to the land of Gilead and Bashan east of the Jordan,'
EXEC add_BibleVerse @BibleId, 106017006, N'for the daughters of Manasseh were assigned land among his sons. The land of Gilead belonged to the rest of the descendants of Manasseh.'
EXEC add_BibleVerse @BibleId, 106017007, N'The border of Manasseh went from Asher to Micmethath which is near Shechem. It then went south toward those who live in Tappuah.'
EXEC add_BibleVerse @BibleId, 106017008, N'(The land of Tappuah belonged to Manasseh, but Tappuah, located on the border of Manasseh, belonged to the tribe of Ephraim.)'
EXEC add_BibleVerse @BibleId, 106017009, N'The border then descended southward to the Valley of Kanah. Ephraim was assigned cities there among the cities of Manasseh, but the border of Manasseh was north of the valley and ended at the sea.'
EXEC add_BibleVerse @BibleId, 106017010, N'Ephraim’s territory was to the south, and Manasseh’s to the north. The sea was Manasseh’s western border and their territory touched Asher on the north and Issachar on the east.'
EXEC add_BibleVerse @BibleId, 106017011, N'Within Issachar’s and Asher’s territory Manasseh was assigned Beth Shean, Ibleam, the residents of Dor, En Dor, the residents of Taanach, the residents of Megiddo, the three of Napheth, and the towns surrounding all these cities.'
EXEC add_BibleVerse @BibleId, 106017012, N'But the men of Manasseh were unable to conquer these cities; the Canaanites managed to remain in those areas.'
EXEC add_BibleVerse @BibleId, 106017013, N'Whenever the Israelites were strong militarily, they forced the Canaanites to do hard labor, but they never totally conquered them.'
EXEC add_BibleVerse @BibleId, 106017014, N'The descendants of Joseph said to Joshua, “Why have you assigned us only one tribal allotment? After all, we have many people, for until now the Lord has enabled us to increase in number.”'
EXEC add_BibleVerse @BibleId, 106017015, N'Joshua replied to them, “Since you have so many people, go up into the forest and clear out a place to live in the land of the Perizzites and Rephaites, for the hill country of Ephraim is too small for you.”'
EXEC add_BibleVerse @BibleId, 106017016, N'The descendants of Joseph said, “The whole hill country is inadequate for us, and the Canaanites living down in the valley in Beth Shean and its surrounding towns and in the Valley of Jezreel have chariots with iron-rimmed wheels.”'
EXEC add_BibleVerse @BibleId, 106017017, N'Joshua said to the family of Joseph – to both Ephraim and Manasseh: “You have many people and great military strength. You will not have just one tribal allotment.'
EXEC add_BibleVerse @BibleId, 106017018, N'The whole hill country will be yours; though it is a forest, you can clear it and it will be entirely yours. You can conquer the Canaanites, though they have chariots with iron-rimmed wheels and are strong.”'
EXEC add_BibleVerse @BibleId, 106018001, N'The entire Israelite community assembled at Shiloh and there they set up the tent of meeting. Though they had subdued the land,'
EXEC add_BibleVerse @BibleId, 106018002, N'seven Israelite tribes had not been assigned their allotted land.'
EXEC add_BibleVerse @BibleId, 106018003, N'So Joshua said to the Israelites: “How long do you intend to put off occupying the land the Lord God of your ancestors has given you?'
EXEC add_BibleVerse @BibleId, 106018004, N'Pick three men from each tribe. I will send them out to walk through the land and make a map of it for me.'
EXEC add_BibleVerse @BibleId, 106018005, N'Divide it into seven regions. Judah will stay in its territory in the south, and the family of Joseph in its territory in the north.'
EXEC add_BibleVerse @BibleId, 106018006, N'But as for you, map out the land into seven regions and bring it to me. I will draw lots for you here before the Lord our God.'
EXEC add_BibleVerse @BibleId, 106018007, N'But the Levites will not have an allotted portion among you, for their inheritance is to serve the Lord. Gad, Reuben, and the half-tribe of Manasseh have already received their allotted land east of the Jordan which Moses the Lord’s servant assigned them.”'
EXEC add_BibleVerse @BibleId, 106018008, N'When the men started out, Joshua told those going to map out the land, “Go, walk through the land, map it out, and return to me. Then I will draw lots for you before the Lord here in Shiloh.”'
EXEC add_BibleVerse @BibleId, 106018009, N'The men journeyed through the land and mapped it and its cities out into seven regions on a scroll. Then they came to Joshua at the camp in Shiloh.'
EXEC add_BibleVerse @BibleId, 106018010, N'Joshua drew lots for them in Shiloh before the Lord and divided the land among the Israelites according to their allotted portions.'
EXEC add_BibleVerse @BibleId, 106018011, N'The first lot belonged to the tribe of Benjamin by its clans. Their allotted territory was between Judah and Joseph.'
EXEC add_BibleVerse @BibleId, 106018012, N'Their northern border started at the Jordan, went up to the slope of Jericho on the north, ascended westward to the hill country, and extended to the desert of Beth Aven.'
EXEC add_BibleVerse @BibleId, 106018013, N'It then crossed from there to Luz, to the slope of Luz to the south (that is, Bethel), and descended to Ataroth Addar located on the hill that is south of lower Beth Horon.'
EXEC add_BibleVerse @BibleId, 106018014, N'It then turned on the west side southward from the hill near Beth Horon on the south and extended to Kiriath Baal (that is, Kiriath Jearim), a city belonging to the tribe of Judah. This is the western border.'
EXEC add_BibleVerse @BibleId, 106018015, N'The southern side started on the edge of Kiriath Jearim and extended westward to the spring of the waters of Nephtoah.'
EXEC add_BibleVerse @BibleId, 106018016, N'The border then descended to the edge of the hill country near the Valley of Ben Hinnom located in the Valley of the Rephaites to the north. It descended through the Valley of Hinnom to the slope of the Jebusites to the south and then down to En Rogel.'
EXEC add_BibleVerse @BibleId, 106018017, N'It went northward, extending to En Shemesh and Geliloth opposite the Pass of Adummim, and descended to the Stone of Bohan son of Reuben.'
EXEC add_BibleVerse @BibleId, 106018018, N'It crossed to the slope in front of the Arabah to the north and descended into the Arabah.'
EXEC add_BibleVerse @BibleId, 106018019, N'It then crossed to the slope of Beth Hoglah to the north and ended at the northern tip of the Salt Sea at the mouth of the Jordan River. This was the southern border.'
EXEC add_BibleVerse @BibleId, 106018020, N'The Jordan River borders it on the east. These were the borders of the land assigned to the tribe of Benjamin by its clans.'
EXEC add_BibleVerse @BibleId, 106018021, N'These cities belonged to the tribe of Benjamin by its clans: Jericho, Beth Hoglah, Emek Keziz,'
EXEC add_BibleVerse @BibleId, 106018022, N'Beth Arabah, Zemaraim, Bethel,'
EXEC add_BibleVerse @BibleId, 106018023, N'Avvim, Parah, Ophrah,'
EXEC add_BibleVerse @BibleId, 106018024, N'Kephar Ammoni, Ophni, and Geba – a total of twelve cities and their towns.'
EXEC add_BibleVerse @BibleId, 106018025, N'Gibeon, Ramah, Beeroth,'
EXEC add_BibleVerse @BibleId, 106018026, N'Mizpah, Kephirah, Mozah,'
EXEC add_BibleVerse @BibleId, 106018027, N'Rekem, Irpeel, Taralah,'
EXEC add_BibleVerse @BibleId, 106018028, N'Zelah, Haeleph, the Jebusite city (that is, Jerusalem), Gibeah, and Kiriath – a total of fourteen cities and their towns. This was the land assigned to the tribe of Benjamin by its clans.'
EXEC add_BibleVerse @BibleId, 106019001, N'The second lot belonged to the tribe of Simeon by its clans.'
EXEC add_BibleVerse @BibleId, 106019002, N'Their assigned land included Beer Sheba, Moladah,'
EXEC add_BibleVerse @BibleId, 106019003, N'Hazar Shual, Balah, Ezem,'
EXEC add_BibleVerse @BibleId, 106019004, N'Eltolad, Bethul, Hormah,'
EXEC add_BibleVerse @BibleId, 106019005, N'Ziklag, Beth Marcaboth, Hazar Susah,'
EXEC add_BibleVerse @BibleId, 106019006, N'Beth Lebaoth, and Sharuhen – a total of thirteen cities and their towns,'
EXEC add_BibleVerse @BibleId, 106019007, N'Ain, Rimmon, Ether, and Ashan – a total of four cities and their towns,'
EXEC add_BibleVerse @BibleId, 106019008, N'as well as all the towns around these cities as far as Baalath Beer (Ramah of the Negev). This was the land assigned to the tribe of Simeon by its clans.'
EXEC add_BibleVerse @BibleId, 106019009, N'Simeon’s assigned land was taken from Judah’s allotted portion, for Judah’s territory was too large for them; so Simeon was assigned land within Judah.'
EXEC add_BibleVerse @BibleId, 106019010, N'The third lot belonged to the tribe of Zebulun by its clans. The border of their territory extended to Sarid.'
EXEC add_BibleVerse @BibleId, 106019011, N'Their border went up westward to Maralah and touched Dabbesheth and the valley near Jokneam.'
EXEC add_BibleVerse @BibleId, 106019012, N'From Sarid it turned eastward to the territory of Kisloth Tabor, extended to Daberath, and went up to Japhia.'
EXEC add_BibleVerse @BibleId, 106019013, N'From there it crossed eastward to Gath Hepher and Eth Kazin and extended to Rimmon, turning toward Neah.'
EXEC add_BibleVerse @BibleId, 106019014, N'It then turned on the north to Hannathon and ended at the Valley of Iphtah El.'
EXEC add_BibleVerse @BibleId, 106019015, N'Their territory included Kattah, Nahalal, Shimron, Idalah, and Bethlehem; in all they had twelve cities and their towns.'
EXEC add_BibleVerse @BibleId, 106019016, N'This was the land assigned to the tribe of Zebulun by its clans, including these cities and their towns.'
EXEC add_BibleVerse @BibleId, 106019017, N'The fourth lot belonged to the tribe of Issachar by its clans.'
EXEC add_BibleVerse @BibleId, 106019018, N'Their assigned land included Jezreel, Kesulloth, Shunem,'
EXEC add_BibleVerse @BibleId, 106019019, N'Hapharaim, Shion, Anaharath,'
EXEC add_BibleVerse @BibleId, 106019020, N'Rabbith, Kishion, Ebez,'
EXEC add_BibleVerse @BibleId, 106019021, N'Remeth, En Gannim, En Haddah and Beth Pazzez.'
EXEC add_BibleVerse @BibleId, 106019022, N'Their border touched Tabor, Shahazumah, and Beth Shemesh, and ended at the Jordan. They had sixteen cities and their towns.'
EXEC add_BibleVerse @BibleId, 106019023, N'This was the land assigned to the tribe of Issachar by its clans, including the cities and their towns.'
EXEC add_BibleVerse @BibleId, 106019024, N'The fifth lot belonged to the tribe of Asher by its clans.'
EXEC add_BibleVerse @BibleId, 106019025, N'Their territory included Helkath, Hali, Beten, Acshaph,'
EXEC add_BibleVerse @BibleId, 106019026, N'Alammelech, Amad, and Mishal. Their border touched Carmel to the west and Shihor Libnath.'
EXEC add_BibleVerse @BibleId, 106019027, N'It turned eastward toward Beth Dagon, touched Zebulun and the Valley of Iphtah El to the north, as well as the Valley of Emek and Neiel, and extended to Cabul on the north'
EXEC add_BibleVerse @BibleId, 106019028, N'and on to Ebron, Rehob, Hammon, and Kanah, as far as Greater Sidon.'
EXEC add_BibleVerse @BibleId, 106019029, N'It then turned toward Ramah as far as the fortified city of Tyre, turned to Hosah, and ended at the sea near Hebel, Aczib,'
EXEC add_BibleVerse @BibleId, 106019030, N'Umah, Aphek, and Rehob. In all they had twenty-two cities and their towns.'
EXEC add_BibleVerse @BibleId, 106019031, N'This was the land assigned to the tribe of Asher by its clans, including these cities and their towns.'
EXEC add_BibleVerse @BibleId, 106019032, N'The sixth lot belonged to the tribe of Naphtali by its clans.'
EXEC add_BibleVerse @BibleId, 106019033, N'Their border started at Heleph and the oak of Zaanannim, went to Adami Nekeb, Jabneel and on to Lakkum, and ended at the Jordan River.'
EXEC add_BibleVerse @BibleId, 106019034, N'It turned westward to Aznoth Tabor, extended from there to Hukok, touched Zebulun on the south, Asher on the west, and the Jordan on the east.'
EXEC add_BibleVerse @BibleId, 106019035, N'The fortified cities included Ziddim, Zer, Hammath, Rakkath, Kinnereth,'
EXEC add_BibleVerse @BibleId, 106019036, N'Adamah, Ramah, Hazor,'
EXEC add_BibleVerse @BibleId, 106019037, N'Kedesh, Edrei, En Hazor,'
EXEC add_BibleVerse @BibleId, 106019038, N'Yiron, Migdal El, Horem, Beth Anath, and Beth Shemesh. In all they had nineteen cities and their towns.'
EXEC add_BibleVerse @BibleId, 106019039, N'This was the land assigned to the tribe of Naphtali by its clans, including the cities and their towns.'
EXEC add_BibleVerse @BibleId, 106019040, N'The seventh lot belonged to the tribe of Dan by its clans.'
EXEC add_BibleVerse @BibleId, 106019041, N'Their assigned land included Zorah, Eshtaol, Ir Shemesh,'
EXEC add_BibleVerse @BibleId, 106019042, N'Shaalabbin, Aijalon, Ithlah,'
EXEC add_BibleVerse @BibleId, 106019043, N'Elon, Timnah, Ekron,'
EXEC add_BibleVerse @BibleId, 106019044, N'Eltekeh, Gibbethon, Baalath,'
EXEC add_BibleVerse @BibleId, 106019045, N'Jehud, Bene Berak, Gath Rimmon,'
EXEC add_BibleVerse @BibleId, 106019046, N'the waters of Jarkon, and Rakkon, including the territory in front of Joppa.'
EXEC add_BibleVerse @BibleId, 106019047, N'(The Danites failed to conquer their territory, so they went up and fought with Leshem and captured it. They put the sword to it, took possession of it, and lived in it. They renamed it Dan after their ancestor. )'
EXEC add_BibleVerse @BibleId, 106019048, N'This was the land assigned to the tribe of Dan by its clans, including these cities and their towns.'
EXEC add_BibleVerse @BibleId, 106019049, N'When they finished dividing the land into its regions, the Israelites gave Joshua son of Nun some land.'
EXEC add_BibleVerse @BibleId, 106019050, N'As the Lord had instructed, they gave him the city he requested – Timnath Serah in the Ephraimite hill country. He built up the city and lived in it.'
EXEC add_BibleVerse @BibleId, 106019051, N'These are the land assignments which Eleazar the priest, Joshua son of Nun, and the Israelite tribal leaders made by drawing lots in Shiloh before the Lord at the entrance of the tent of meeting. So they finished dividing up the land.'
EXEC add_BibleVerse @BibleId, 106020001, N'The Lord instructed Joshua:'
EXEC add_BibleVerse @BibleId, 106020002, N'“Have the Israelites select the cities of refuge that I told you about through Moses.'
EXEC add_BibleVerse @BibleId, 106020003, N'Anyone who accidentally kills someone can escape there; these cities will be a place of asylum from the avenger of blood.'
EXEC add_BibleVerse @BibleId, 106020004, N'The one who committed manslaughter should escape to one of these cities, stand at the entrance of the city gate, and present his case to the leaders of that city. They should then bring him into the city, give him a place to stay, and let him live there.'
EXEC add_BibleVerse @BibleId, 106020005, N'When the avenger of blood comes after him, they must not hand over to him the one who committed manslaughter, for he accidentally killed his fellow man without premeditation.'
EXEC add_BibleVerse @BibleId, 106020006, N'He must remain in that city until his case is decided by the assembly and the high priest dies. Then the one who committed manslaughter may return home to the city from which he escaped.”'
EXEC add_BibleVerse @BibleId, 106020007, N'So they selected Kedesh in Galilee in the hill country of Naphtali, Shechem in the hill country of Ephraim, and Kiriath Arba (that is, Hebron) in the hill country of Judah.'
EXEC add_BibleVerse @BibleId, 106020008, N'Beyond the Jordan east of Jericho they selected Bezer in the desert on the plain belonging to the tribe of Reuben, Ramoth in Gilead belonging to the tribe of Gad, and Golan in Bashan belonging to the tribe of Manasseh.'
EXEC add_BibleVerse @BibleId, 106020009, N'These were the cities of refuge appointed for all the Israelites and for resident foreigners living among them. Anyone who accidentally killed someone could escape there and not be executed by the avenger of blood, at least until his case was reviewed by the assembly.'
EXEC add_BibleVerse @BibleId, 106021001, N'The tribal leaders of the Levites went before Eleazar the priest and Joshua son of Nun and the Israelite tribal leaders'
EXEC add_BibleVerse @BibleId, 106021002, N'in Shiloh in the land of Canaan and said, “The Lord told Moses to assign us cities in which to live along with the grazing areas for our cattle.”'
EXEC add_BibleVerse @BibleId, 106021003, N'So the Israelites assigned these cities and their grazing areas to the Levites from their own holdings, as the Lord had instructed.'
EXEC add_BibleVerse @BibleId, 106021004, N'The first lot belonged to the Kohathite clans. The Levites who were descendants of Aaron the priest were allotted thirteen cities from the tribes of Judah, Simeon, and Benjamin.'
EXEC add_BibleVerse @BibleId, 106021005, N'The rest of Kohath’s descendants were allotted ten cities from the clans of the tribe of Ephraim, and from the tribe of Dan and the half-tribe of Manasseh.'
EXEC add_BibleVerse @BibleId, 106021006, N'Gershon’s descendants were allotted thirteen cities from the clans of the tribe of Issachar, and from the tribes of Asher and Naphtali and the half-tribe of Manasseh in Bashan.'
EXEC add_BibleVerse @BibleId, 106021007, N'Merari’s descendants by their clans were allotted twelve cities from the tribes of Reuben, Gad, and Zebulun.'
EXEC add_BibleVerse @BibleId, 106021008, N'So the Israelites assigned to the Levites by lot these cities and their grazing areas, as the Lord had instructed Moses.'
EXEC add_BibleVerse @BibleId, 106021009, N'They assigned from the tribes of Judah and Simeon the cities listed below.'
EXEC add_BibleVerse @BibleId, 106021010, N'They were assigned to the Kohathite clans of the Levites who were descendants of Aaron, for the first lot belonged to them.'
EXEC add_BibleVerse @BibleId, 106021011, N'They assigned them Kiriath Arba (Arba was the father of Anak), that is, Hebron, in the hill country of Judah, along with its surrounding grazing areas.'
EXEC add_BibleVerse @BibleId, 106021012, N'(Now the city’s fields and surrounding towns they had assigned to Caleb son of Jephunneh as his property.)'
EXEC add_BibleVerse @BibleId, 106021013, N'So to the descendants of Aaron the priest they assigned Hebron (a city of refuge for one who committed manslaughter), Libnah,'
EXEC add_BibleVerse @BibleId, 106021014, N'Jattir, Eshtemoa,'
EXEC add_BibleVerse @BibleId, 106021015, N'Holon, Debir,'
EXEC add_BibleVerse @BibleId, 106021016, N'Ain, Juttah, and Beth Shemesh, along with the grazing areas of each – a total of nine cities taken from these two tribes.'
EXEC add_BibleVerse @BibleId, 106021017, N'From the tribe of Benjamin they assigned Gibeon, Geba,'
EXEC add_BibleVerse @BibleId, 106021018, N'Anathoth, and Almon, along with the grazing areas of each – a total of four cities.'
EXEC add_BibleVerse @BibleId, 106021019, N'The priests descended from Aaron received thirteen cities and their grazing areas.'
EXEC add_BibleVerse @BibleId, 106021020, N'The rest of the Kohathite clans of the Levites were allotted cities from the tribe of Ephraim.'
EXEC add_BibleVerse @BibleId, 106021021, N'They assigned them Shechem (a city of refuge for one who committed manslaughter) in the hill country of Ephraim, Gezer,'
EXEC add_BibleVerse @BibleId, 106021022, N'Kibzaim, and Beth Horon, along with the grazing areas of each – a total of four cities.'
EXEC add_BibleVerse @BibleId, 106021023, N'From the tribe of Dan they assigned Eltekeh, Gibbethon,'
EXEC add_BibleVerse @BibleId, 106021024, N'Aijalon, and Gath Rimmon, along with the grazing areas of each – a total of four cities.'
EXEC add_BibleVerse @BibleId, 106021025, N'From the half-tribe of Manasseh they assigned Taanach and Gath Rimmon, along with the grazing areas of each – a total of two cities.'
EXEC add_BibleVerse @BibleId, 106021026, N'The rest of the Kohathite clans received ten cities and their grazing areas.'
EXEC add_BibleVerse @BibleId, 106021027, N'They assigned to the Gershonite clans of the Levites the following cities: from the half-tribe of Manasseh: Golan in Bashan (a city of refuge for one who committed manslaughter) and Beeshtarah, along with the grazing areas of each – a total of two cities;'
EXEC add_BibleVerse @BibleId, 106021028, N'from the tribe of Issachar: Kishon, Daberath,'
EXEC add_BibleVerse @BibleId, 106021029, N'Jarmuth, and En Gannim, along with the grazing areas of each – a total of four cities;'
EXEC add_BibleVerse @BibleId, 106021030, N'from the tribe of Asher: Mishal, Abdon,'
EXEC add_BibleVerse @BibleId, 106021031, N'Helkath, and Rehob, along with the grazing areas of each – a total of four cities;'
EXEC add_BibleVerse @BibleId, 106021032, N'from the tribe of Naphtali: Kedesh in Galilee (a city of refuge for one who committed manslaughter), Hammoth Dor, and Kartan, along with the grazing areas of each – a total of three cities.'
EXEC add_BibleVerse @BibleId, 106021033, N'The Gershonite clans received thirteen cities and their grazing areas.'
EXEC add_BibleVerse @BibleId, 106021034, N'They assigned to the Merarite clans (the remaining Levites) the following cities: from the tribe of Zebulun: Jokneam, Kartah,'
EXEC add_BibleVerse @BibleId, 106021035, N'Dimnah, and Nahalal, along with the grazing areas of each – a total of four cities;'
EXEC add_BibleVerse @BibleId, 106021036, N'from the tribe of Reuben: Bezer, Jahaz,'
EXEC add_BibleVerse @BibleId, 106021037, N'Kedemoth, and Mephaath, along with the grazing areas of each – a total of four cities;'
EXEC add_BibleVerse @BibleId, 106021038, N'from the tribe of Gad: Ramoth in Gilead (a city of refuge for one who committed manslaughter), Mahanaim,'
EXEC add_BibleVerse @BibleId, 106021039, N'Heshbon, and Jazer, along with the grazing areas of each – a total of four cities.'
EXEC add_BibleVerse @BibleId, 106021040, N'The Merarite clans (the remaining Levites) were allotted twelve cities.'
EXEC add_BibleVerse @BibleId, 106021041, N'The Levites received within the land owned by the Israelites forty-eight cities in all and their grazing areas.'
EXEC add_BibleVerse @BibleId, 106021042, N'Each of these cities had grazing areas around it; they were alike in this regard.'
EXEC add_BibleVerse @BibleId, 106021043, N'So the Lord gave Israel all the land he had solemnly promised to their ancestors, and they conquered it and lived in it.'
EXEC add_BibleVerse @BibleId, 106021044, N'The Lord made them secure, in fulfillment of all he had solemnly promised their ancestors. None of their enemies could resist them.'
EXEC add_BibleVerse @BibleId, 106021045, N'Not one of the Lord’s faithful promises to the family of Israel was left unfulfilled; every one was realized.'
EXEC add_BibleVerse @BibleId, 106022001, N'Then Joshua summoned the Reubenites, Gadites, and the half-tribe of Manasseh'
EXEC add_BibleVerse @BibleId, 106022002, N'and told them: “You have carried out all the instructions of Moses the Lord’s servant, and you have obeyed all I have told you.'
EXEC add_BibleVerse @BibleId, 106022003, N'You have not abandoned your fellow Israelites this entire time, right up to this very day. You have completed the task given you by the Lord your God.'
EXEC add_BibleVerse @BibleId, 106022004, N'Now the Lord your God has made your fellow Israelites secure, just as he promised them. So now you may turn around and go to your homes in your own land which Moses the Lord’s servant assigned to you east of the Jordan.'
EXEC add_BibleVerse @BibleId, 106022005, N'But carefully obey the commands and instructions Moses the Lord’s servant gave you. Love the Lord your God, follow all his instructions, obey his commands, be loyal to him, and serve him with all your heart and being!”'
EXEC add_BibleVerse @BibleId, 106022006, N'Joshua rewarded them and sent them on their way; they returned to their homes.'
EXEC add_BibleVerse @BibleId, 106022007, N'(Now to one half-tribe of Manasseh, Moses had assigned land in Bashan; and to the other half Joshua had assigned land on the west side of the Jordan with their fellow Israelites.) When Joshua sent them home, he rewarded them,'
EXEC add_BibleVerse @BibleId, 106022008, N'saying, “Take home great wealth, a lot of cattle, silver, gold, bronze, iron, and a lot of clothing. Divide up the goods captured from your enemies with your brothers.”'
EXEC add_BibleVerse @BibleId, 106022009, N'So the Reubenites, Gadites, and half-tribe of Manasseh left the Israelites in Shiloh in the land of Canaan and headed home to their own land in Gilead, which they acquired by the Lord’s command through Moses.'
EXEC add_BibleVerse @BibleId, 106022010, N'The Reubenites, Gadites, and half-tribe of Manasseh came to Geliloth near the Jordan in the land of Canaan and built there, near the Jordan, an impressive altar.'
EXEC add_BibleVerse @BibleId, 106022011, N'The Israelites received this report: “Look, the Reubenites, Gadites, and half-tribe of Manasseh have built an altar at the entrance to the land of Canaan, at Geliloth near the Jordan on the Israelite side.”'
EXEC add_BibleVerse @BibleId, 106022012, N'When the Israelites heard this, the entire Israelite community assembled at Shiloh to launch an attack against them.'
EXEC add_BibleVerse @BibleId, 106022013, N'The Israelites sent Phinehas, son of Eleazar, the priest, to the land of Gilead to the Reubenites, Gadites, and the half-tribe of Manasseh.'
EXEC add_BibleVerse @BibleId, 106022014, N'He was accompanied by ten leaders, one from each of the Israelite tribes, each one a family leader among the Israelite clans.'
EXEC add_BibleVerse @BibleId, 106022015, N'They went to the land of Gilead to the Reubenites, Gadites, and the half-tribe of Manasseh, and said to them:'
EXEC add_BibleVerse @BibleId, 106022016, N'“The entire community of the Lord says, ‘Why have you disobeyed the God of Israel by turning back today from following the Lord? You built an altar for yourselves and have rebelled today against the Lord.'
EXEC add_BibleVerse @BibleId, 106022017, N'The sin we committed at Peor was bad enough. To this very day we have not purified ourselves; it even brought a plague on the community of the Lord.'
EXEC add_BibleVerse @BibleId, 106022018, N'Now today you dare to turn back from following the Lord! You are rebelling today against the Lord; tomorrow he may break out in anger against the entire community of Israel.'
EXEC add_BibleVerse @BibleId, 106022019, N'But if your own land is impure, cross over to the Lord’s own land, where the Lord himself lives, and settle down among us. But don’t rebel against the Lord or us by building for yourselves an altar aside from the altar of the Lord our God.'
EXEC add_BibleVerse @BibleId, 106022020, N'When Achan son of Zerah disobeyed the command about the city’s riches, the entire Israelite community was judged, though only one man had sinned. He most certainly died for his sin!’”'
EXEC add_BibleVerse @BibleId, 106022021, N'The Reubenites, Gadites, and the half-tribe of Manasseh answered the leaders of the Israelite clans:'
EXEC add_BibleVerse @BibleId, 106022022, N'“El, God, the Lord! El, God, the Lord! He knows the truth! Israel must also know! If we have rebelled or disobeyed the Lord, don’t spare us today!'
EXEC add_BibleVerse @BibleId, 106022023, N'If we have built an altar for ourselves to turn back from following the Lord by making burnt sacrifices and grain offerings on it, or by offering tokens of peace on it, the Lord himself will punish us.'
EXEC add_BibleVerse @BibleId, 106022024, N'We swear we have done this because we were worried that in the future your descendants would say to our descendants, ‘What relationship do you have with the Lord God of Israel?'
EXEC add_BibleVerse @BibleId, 106022025, N'The Lord made the Jordan a boundary between us and you Reubenites and Gadites. You have no right to worship the Lord.’ In this way your descendants might cause our descendants to stop obeying the Lord.'
EXEC add_BibleVerse @BibleId, 106022026, N'So we decided to build this altar, not for burnt offerings and sacrifices,'
EXEC add_BibleVerse @BibleId, 106022027, N'but as a reminder to us and you, and to our descendants who follow us, that we will honor the Lord in his very presence with burnt offerings, sacrifices, and tokens of peace. Then in the future your descendants will not be able to say to our descendants, ‘You have no right to worship the Lord.’'
EXEC add_BibleVerse @BibleId, 106022028, N'We said, ‘If in the future they say such a thing to us or to our descendants, we will reply, “See the model of the Lord’s altar that our ancestors made, not for burnt offerings or sacrifices, but as a reminder to us and you.”’'
EXEC add_BibleVerse @BibleId, 106022029, N'Far be it from us to rebel against the Lord by turning back today from following after the Lord by building an altar for burnt offerings, sacrifices, and tokens of peace aside from the altar of the Lord our God located in front of his dwelling place!”'
EXEC add_BibleVerse @BibleId, 106022030, N'When Phinehas the priest and the community leaders and clan leaders who accompanied him heard the defense of the Reubenites, Gadites, and the Manassehites, they were satisfied.'
EXEC add_BibleVerse @BibleId, 106022031, N'Phinehas, son of Eleazar, the priest, said to the Reubenites, Gadites, and the Manassehites, “Today we know that the Lord is among us, because you have not disobeyed the Lord in this. Now you have rescued the Israelites from the Lord’s judgment.”'
EXEC add_BibleVerse @BibleId, 106022032, N'Phinehas, son of Eleazar, the priest, and the leaders left the Reubenites and Gadites in the land of Gilead and reported back to the Israelites in the land of Canaan.'
EXEC add_BibleVerse @BibleId, 106022033, N'The Israelites were satisfied with their report and gave thanks to God. They said nothing more about launching an attack to destroy the land in which the Reubenites and Gadites lived.'
EXEC add_BibleVerse @BibleId, 106022034, N'The Reubenites and Gadites named the altar, “Surely it is a Reminder to us that the Lord is God.”'
EXEC add_BibleVerse @BibleId, 106023001, N'A long time passed after the Lord made Israel secure from all their enemies, and Joshua was very old.'
EXEC add_BibleVerse @BibleId, 106023002, N'So Joshua summoned all Israel, including the elders, rulers, judges, and leaders, and told them: “I am very old.'
EXEC add_BibleVerse @BibleId, 106023003, N'You saw everything the Lord your God did to all these nations on your behalf, for the Lord your God fights for you.'
EXEC add_BibleVerse @BibleId, 106023004, N'See, I have parceled out to your tribes these remaining nations, from the Jordan to the Mediterranean Sea in the west, including all the nations I defeated.'
EXEC add_BibleVerse @BibleId, 106023005, N'The Lord your God will drive them out from before you and remove them, so you can occupy their land as the Lord your God promised you.'
EXEC add_BibleVerse @BibleId, 106023006, N'Be very strong! Carefully obey all that is written in the law scroll of Moses so you won’t swerve from it to the right or the left,'
EXEC add_BibleVerse @BibleId, 106023007, N'or associate with these nations that remain near you. You must not invoke or make solemn declarations by the names of their gods! You must not worship or bow down to them!'
EXEC add_BibleVerse @BibleId, 106023008, N'But you must be loyal to the Lord your God, as you have been to this very day.'
EXEC add_BibleVerse @BibleId, 106023009, N'“The Lord drove out from before you great and mighty nations; no one has been able to resist you to this very day.'
EXEC add_BibleVerse @BibleId, 106023010, N'One of you makes a thousand run away, for the Lord your God fights for you as he promised you he would.'
EXEC add_BibleVerse @BibleId, 106023011, N'Watch yourselves carefully! Love the Lord your God!'
EXEC add_BibleVerse @BibleId, 106023012, N'But if you ever turn away and make alliances with these nations that remain near you, and intermarry with them and establish friendly relations with them,'
EXEC add_BibleVerse @BibleId, 106023013, N'know for certain that the Lord our God will no longer drive out these nations from before you. They will trap and ensnare you; they will be a whip that tears your sides and thorns that blind your eyes until you disappear from this good land the Lord your God gave you.'
EXEC add_BibleVerse @BibleId, 106023014, N'“Look, today I am about to die. You know with all your heart and being that not even one of all the faithful promises the Lord your God made to you is left unfulfilled; every one was realized – not one promise is unfulfilled!'
EXEC add_BibleVerse @BibleId, 106023015, N'But in the same way every faithful promise the Lord your God made to you has been realized, it is just as certain, if you disobey, that the Lord will bring on you every judgment until he destroys you from this good land which the Lord your God gave you.'
EXEC add_BibleVerse @BibleId, 106023016, N'If you violate the covenantal laws of the Lord your God which he commanded you to keep, and follow, worship, and bow down to other gods, the Lord will be very angry with you and you will disappear quickly from the good land which he gave to you.”'
EXEC add_BibleVerse @BibleId, 106024001, N'Joshua assembled all the Israelite tribes at Shechem. He summoned Israel’s elders, rulers, judges, and leaders, and they appeared before God.'
EXEC add_BibleVerse @BibleId, 106024002, N'Joshua told all the people, “Here is what the Lord God of Israel says: ‘In the distant past your ancestors lived beyond the Euphrates River, including Terah the father of Abraham and Nahor. They worshiped other gods,'
EXEC add_BibleVerse @BibleId, 106024003, N'but I took your father Abraham from beyond the Euphrates and brought him into the entire land of Canaan. I made his descendants numerous; I gave him Isaac,'
EXEC add_BibleVerse @BibleId, 106024004, N'and to Isaac I gave Jacob and Esau. To Esau I assigned Mount Seir, while Jacob and his sons went down to Egypt.'
EXEC add_BibleVerse @BibleId, 106024005, N'I sent Moses and Aaron, and I struck Egypt down when I intervened in their land. Then I brought you out.'
EXEC add_BibleVerse @BibleId, 106024006, N'When I brought your fathers out of Egypt, you arrived at the sea. The Egyptians chased your fathers with chariots and horsemen to the Red Sea.'
EXEC add_BibleVerse @BibleId, 106024007, N'Your fathers cried out for help to the Lord; he made the area between you and the Egyptians dark, and then drowned them in the sea. You witnessed with your very own eyes what I did in Egypt. You lived in the wilderness for a long time.'
EXEC add_BibleVerse @BibleId, 106024008, N'Then I brought you to the land of the Amorites who lived east of the Jordan. They fought with you, but I handed them over to you; you conquered their land and I destroyed them from before you.'
EXEC add_BibleVerse @BibleId, 106024009, N'Balak son of Zippor, king of Moab, launched an attack against Israel. He summoned Balaam son of Beor to call down judgment on you.'
EXEC add_BibleVerse @BibleId, 106024010, N'I refused to respond to Balaam; he kept prophesying good things about you, and I rescued you from his power.'
EXEC add_BibleVerse @BibleId, 106024011, N'You crossed the Jordan and came to Jericho. The leaders of Jericho, as well as the Amorites, Perizzites, Canaanites, Hittites, Girgashites, Hivites, and Jebusites, fought with you, but I handed them over to you.'
EXEC add_BibleVerse @BibleId, 106024012, N'I sent terror ahead of you to drive out before you the two Amorite kings. I gave you the victory; it was not by your swords or bows.'
EXEC add_BibleVerse @BibleId, 106024013, N'I gave you a land in which you had not worked hard; you took up residence in cities you did not build and you are eating the produce of vineyards and olive groves you did not plant.’'
EXEC add_BibleVerse @BibleId, 106024014, N'Now obey the Lord and worship him with integrity and loyalty. Put aside the gods your ancestors worshiped beyond the Euphrates and in Egypt and worship the Lord.'
EXEC add_BibleVerse @BibleId, 106024015, N'If you have no desire to worship the Lord, choose today whom you will worship, whether it be the gods whom your ancestors worshiped beyond the Euphrates, or the gods of the Amorites in whose land you are living. But I and my family will worship the Lord!”'
EXEC add_BibleVerse @BibleId, 106024016, N'The people responded, “Far be it from us to abandon the Lord so we can worship other gods!'
EXEC add_BibleVerse @BibleId, 106024017, N'For the Lord our God took us and our fathers out of slavery in the land of Egypt and performed these awesome miracles before our very eyes. He continually protected us as we traveled and when we passed through nations.'
EXEC add_BibleVerse @BibleId, 106024018, N'The Lord drove out from before us all the nations, including the Amorites who lived in the land. So we too will worship the Lord, for he is our God!”'
EXEC add_BibleVerse @BibleId, 106024019, N'Joshua warned the people, “You will not keep worshiping the Lord, for he is a holy God. He is a jealous God who will not forgive your rebellion or your sins.'
EXEC add_BibleVerse @BibleId, 106024020, N'If you abandon the Lord and worship foreign gods, he will turn against you; he will bring disaster on you and destroy you, though he once treated you well.”'
EXEC add_BibleVerse @BibleId, 106024021, N'The people said to Joshua, “No! We really will worship the Lord!”'
EXEC add_BibleVerse @BibleId, 106024022, N'Joshua said to the people, “Do you agree to be witnesses against yourselves that you have chosen to worship the Lord?” They replied, “We are witnesses!”'
EXEC add_BibleVerse @BibleId, 106024023, N'Joshua said, “Now put aside the foreign gods that are among you and submit to the Lord God of Israel.”'
EXEC add_BibleVerse @BibleId, 106024024, N'The people said to Joshua, “We will worship the Lord our God and obey him.”'
EXEC add_BibleVerse @BibleId, 106024025, N'That day Joshua drew up an agreement for the people, and he established rules and regulations for them in Shechem.'
EXEC add_BibleVerse @BibleId, 106024026, N'Joshua wrote these words in the Law Scroll of God. He then took a large stone and set it up there under the oak tree near the Lord’s shrine.'
EXEC add_BibleVerse @BibleId, 106024027, N'Joshua said to all the people, “Look, this stone will be a witness against you, for it has heard everything the Lord said to us. It will be a witness against you if you deny your God.”'
EXEC add_BibleVerse @BibleId, 106024028, N'When Joshua dismissed the people, they went to their allotted portions of land.'
EXEC add_BibleVerse @BibleId, 106024029, N'After all this Joshua son of Nun, the Lord’s servant, died at the age of one hundred ten.'
EXEC add_BibleVerse @BibleId, 106024030, N'They buried him in his allotted territory in Timnath Serah in the hill country of Ephraim, north of Mount Gaash.'
EXEC add_BibleVerse @BibleId, 106024031, N'Israel worshiped the Lord throughout Joshua’s lifetime and as long as the elderly men who outlived him remained alive. These men had experienced firsthand everything the Lord had done for Israel.'
EXEC add_BibleVerse @BibleId, 106024032, N'The bones of Joseph, which the Israelites had brought up from Egypt, were buried at Shechem in the part of the field that Jacob bought from the sons of Hamor, the father of Shechem, for one hundred pieces of money. So it became the inheritance of the tribe of Joseph.'
EXEC add_BibleVerse @BibleId, 106024033, N'Eleazar son of Aaron died, and they buried him in Gibeah in the hill country of Ephraim, where his son Phinehas had been assigned land.'
EXEC add_BibleVerse @BibleId, 107001001, N'After Joshua died, the Israelites asked the Lord, “Who should lead the invasion against the Canaanites and launch the attack?”'
EXEC add_BibleVerse @BibleId, 107001002, N'The Lord said, “The men of Judah should take the lead. Be sure of this! I am handing the land over to them.”'
EXEC add_BibleVerse @BibleId, 107001003, N'The men of Judah said to their relatives, the men of Simeon, “Invade our allotted land with us and help us attack the Canaanites. Then we will go with you into your allotted land.” So the men of Simeon went with them.'
EXEC add_BibleVerse @BibleId, 107001004, N'The men of Judah attacked, and the Lord handed the Canaanites and Perizzites over to them. They killed ten thousand men at Bezek.'
EXEC add_BibleVerse @BibleId, 107001005, N'They met Adoni-Bezek at Bezek and fought him. They defeated the Canaanites and Perizzites.'
EXEC add_BibleVerse @BibleId, 107001006, N'When Adoni-Bezek ran away, they chased him and captured him. Then they cut off his thumbs and big toes.'
EXEC add_BibleVerse @BibleId, 107001007, N'Adoni-Bezek said, “Seventy kings, with thumbs and big toes cut off, used to lick up food scraps under my table. God has repaid me for what I did to them.” They brought him to Jerusalem, where he died.'
EXEC add_BibleVerse @BibleId, 107001008, N'The men of Judah attacked Jerusalem and captured it. They put the sword to it and set the city on fire.'
EXEC add_BibleVerse @BibleId, 107001009, N'Later the men of Judah went down to attack the Canaanites living in the hill country, the Negev, and the lowlands.'
EXEC add_BibleVerse @BibleId, 107001010, N'The men of Judah attacked the Canaanites living in Hebron. (Hebron used to be called Kiriath Arba.) They killed Sheshai, Ahiman, and Talmai.'
EXEC add_BibleVerse @BibleId, 107001011, N'From there they attacked the people of Debir. (Debir used to be called Kiriath Sepher.)'
EXEC add_BibleVerse @BibleId, 107001012, N'Caleb said, “To the man who attacks and captures Kiriath Sepher I will give my daughter Acsah as a wife.”'
EXEC add_BibleVerse @BibleId, 107001013, N'When Othniel son of Kenaz, Caleb’s younger brother, captured it, Caleb gave him his daughter Acsah as a wife.'
EXEC add_BibleVerse @BibleId, 107001014, N'One time Acsah came and charmed her father so she could ask him for some land. When she got down from her donkey, Caleb said to her, “What would you like?”'
EXEC add_BibleVerse @BibleId, 107001015, N'She answered, “Please give me a special present. Since you have given me land in the Negev, now give me springs of water.” So Caleb gave her both the upper and lower springs.'
EXEC add_BibleVerse @BibleId, 107001016, N'Now the descendants of the Kenite, Moses’ father-in-law, went up with the people of Judah from the City of Date Palm Trees to Arad in the desert of Judah, located in the Negev. They went and lived with the people of Judah.'
EXEC add_BibleVerse @BibleId, 107001017, N'The men of Judah went with their brothers the men of Simeon and defeated the Canaanites living in Zephath. They wiped out Zephath. So people now call the city Hormah.'
EXEC add_BibleVerse @BibleId, 107001018, N'The men of Judah captured Gaza, Ashkelon, Ekron, and the territory surrounding each of these cities.'
EXEC add_BibleVerse @BibleId, 107001019, N'The Lord was with the men of Judah. They conquered the hill country, but they could not conquer the people living in the coastal plain, because they had chariots with iron-rimmed wheels.'
EXEC add_BibleVerse @BibleId, 107001020, N'Caleb received Hebron, just as Moses had promised. He drove out the three Anakites.'
EXEC add_BibleVerse @BibleId, 107001021, N'The men of Benjamin, however, did not conquer the Jebusites living in Jerusalem. The Jebusites live with the people of Benjamin in Jerusalem to this very day.'
EXEC add_BibleVerse @BibleId, 107001022, N'When the men of Joseph attacked Bethel, the Lord was with them.'
EXEC add_BibleVerse @BibleId, 107001023, N'When the men of Joseph spied out Bethel (it used to be called Luz),'
EXEC add_BibleVerse @BibleId, 107001024, N'the spies spotted a man leaving the city. They said to him, “If you show us a secret entrance into the city, we will reward you.”'
EXEC add_BibleVerse @BibleId, 107001025, N'He showed them a secret entrance into the city, and they put the city to the sword. But they let the man and his extended family leave safely.'
EXEC add_BibleVerse @BibleId, 107001026, N'He moved to Hittite country and built a city. He named it Luz, and it has kept that name to this very day.'
EXEC add_BibleVerse @BibleId, 107001027, N'The men of Manasseh did not conquer Beth Shan, Taanach, or their surrounding towns. Nor did they conquer the people living in Dor, Ibleam, Megiddo or their surrounding towns. The Canaanites managed to remain in those areas.'
EXEC add_BibleVerse @BibleId, 107001028, N'Whenever Israel was strong militarily, they forced the Canaanites to do hard labor, but they never totally conquered them.'
EXEC add_BibleVerse @BibleId, 107001029, N'The men of Ephraim did not conquer the Canaanites living in Gezer. The Canaanites lived among them in Gezer.'
EXEC add_BibleVerse @BibleId, 107001030, N'The men of Zebulun did not conquer the people living in Kitron and Nahalol. The Canaanites lived among them and were forced to do hard labor.'
EXEC add_BibleVerse @BibleId, 107001031, N'The men of Asher did not conquer the people living in Acco or Sidon, nor did they conquer Ahlab, Aczib, Helbah, Aphek, or Rehob.'
EXEC add_BibleVerse @BibleId, 107001032, N'The people of Asher live among the Canaanites residing in the land because they did not conquer them.'
EXEC add_BibleVerse @BibleId, 107001033, N'The men of Naphtali did not conquer the people living in Beth Shemesh or Beth Anath. They live among the Canaanites residing in the land. The Canaanites living in Beth Shemesh and Beth Anath were forced to do hard labor for them.'
EXEC add_BibleVerse @BibleId, 107001034, N'The Amorites forced the people of Dan to live in the hill country. They did not allow them to live in the coastal plain.'
EXEC add_BibleVerse @BibleId, 107001035, N'The Amorites managed to remain in Har Heres, Aijalon, and Shaalbim. Whenever the tribe of Joseph was strong militarily, the Amorites were forced to do hard labor.'
EXEC add_BibleVerse @BibleId, 107001036, N'The border of Amorite territory ran from the Scorpion Ascent to Sela and on up.'
EXEC add_BibleVerse @BibleId, 107002001, N'The Lord’s angelic messenger went up from Gilgal to Bokim. He said, “I brought you up from Egypt and led you into the land I had solemnly promised to give to your ancestors. I said, ‘I will never break my agreement with you,'
EXEC add_BibleVerse @BibleId, 107002002, N'but you must not make an agreement with the people who live in this land. You should tear down the altars where they worship.’ But you have disobeyed me. Why would you do such a thing?'
EXEC add_BibleVerse @BibleId, 107002003, N'At that time I also warned you, ‘If you disobey, I will not drive out the Canaanites before you. They will ensnare you and their gods will lure you away.’”'
EXEC add_BibleVerse @BibleId, 107002004, N'When the Lord’s messenger finished speaking these words to all the Israelites, the people wept loudly.'
EXEC add_BibleVerse @BibleId, 107002005, N'They named that place Bokim and offered sacrifices to the Lord there.'
EXEC add_BibleVerse @BibleId, 107002006, N'When Joshua dismissed the people, the Israelites went to their allotted portions of territory, intending to take possession of the land.'
EXEC add_BibleVerse @BibleId, 107002007, N'The people worshiped the Lord throughout Joshua’s lifetime and as long as the elderly men who outlived him remained alive. These men had witnessed all the great things the Lord had done for Israel.'
EXEC add_BibleVerse @BibleId, 107002008, N'Joshua son of Nun, the Lord’s servant, died at the age of one hundred ten.'
EXEC add_BibleVerse @BibleId, 107002009, N'The people buried him in his allotted land in Timnath Heres in the hill country of Ephraim, north of Mount Gaash.'
EXEC add_BibleVerse @BibleId, 107002010, N'That entire generation passed away; a new generation grew up that had not personally experienced the Lord’s presence or seen what he had done for Israel.'
EXEC add_BibleVerse @BibleId, 107002011, N'The Israelites did evil before the Lord by worshiping the Baals.'
EXEC add_BibleVerse @BibleId, 107002012, N'They abandoned the Lord God of their ancestors who brought them out of the land of Egypt. They followed other gods – the gods of the nations who lived around them. They worshiped them and made the Lord angry.'
EXEC add_BibleVerse @BibleId, 107002013, N'They abandoned the Lord and worshiped Baal and the Ashtars.'
EXEC add_BibleVerse @BibleId, 107002014, N'The Lord was furious with Israel and handed them over to robbers who plundered them. He turned them over to their enemies who lived around them. They could not withstand their enemies’ attacks.'
EXEC add_BibleVerse @BibleId, 107002015, N'Whenever they went out to fight, the Lord did them harm, just as he had warned and solemnly vowed he would do. They suffered greatly.'
EXEC add_BibleVerse @BibleId, 107002016, N'The Lord raised up leaders who delivered them from these robbers.'
EXEC add_BibleVerse @BibleId, 107002017, N'But they did not obey their leaders. Instead they prostituted themselves to other gods and worshiped them. They quickly turned aside from the path their ancestors had walked. Their ancestors had obeyed the Lord’s commands, but they did not.'
EXEC add_BibleVerse @BibleId, 107002018, N'When the Lord raised up leaders for them, the Lord was with each leader and delivered the people from their enemies while the leader remained alive. The Lord felt sorry for them when they cried out in agony because of what their harsh oppressors did to them.'
EXEC add_BibleVerse @BibleId, 107002019, N'When a leader died, the next generation would again act more wickedly than the previous one. They would follow after other gods, worshiping them and bowing down to them. They did not give up their practices or their stubborn ways.'
EXEC add_BibleVerse @BibleId, 107002020, N'The Lord was furious with Israel. He said, “This nation has violated the terms of the agreement I made with their ancestors by disobeying me.'
EXEC add_BibleVerse @BibleId, 107002021, N'So I will no longer remove before them any of the nations that Joshua left unconquered when he died.'
EXEC add_BibleVerse @BibleId, 107002022, N'Joshua left those nations to test Israel. I wanted to see whether or not the people would carefully walk in the path marked out by the Lord, as their ancestors were careful to do.”'
EXEC add_BibleVerse @BibleId, 107002023, N'This is why the Lord permitted these nations to remain and did not conquer them immediately; he did not hand them over to Joshua.'
EXEC add_BibleVerse @BibleId, 107003001, N'These were the nations the Lord permitted to remain so he could use them to test Israel – he wanted to test all those who had not experienced battle against the Canaanites.'
EXEC add_BibleVerse @BibleId, 107003002, N'He left those nations simply because he wanted to teach the subsequent generations of Israelites, who had not experienced the earlier battles, how to conduct holy war.'
EXEC add_BibleVerse @BibleId, 107003003, N'These were the nations: the five lords of the Philistines, all the Canaanites, the Sidonians, and the Hivites living in Mount Lebanon, from Mount Baal Hermon to Lebo-Hamath.'
EXEC add_BibleVerse @BibleId, 107003004, N'They were left to test Israel, so the Lord would know if his people would obey the commands he gave their ancestors through Moses.'
EXEC add_BibleVerse @BibleId, 107003005, N'The Israelites lived among the Canaanites, Hittites, Amorites, Perizzites, Hivites, and Jebusites.'
EXEC add_BibleVerse @BibleId, 107003006, N'They took the Canaanites’ daughters as wives and gave their daughters to the Canaanites; they worshiped their gods as well.'
EXEC add_BibleVerse @BibleId, 107003007, N'The Israelites did evil in the Lord’s sight. They forgot the Lord their God and worshiped the Baals and the Asherahs.'
EXEC add_BibleVerse @BibleId, 107003008, N'The Lord was furious with Israel and turned them over to King Cushan-Rishathaim of Aram-Naharaim. They were Cushan-Rishathaim’s subjects for eight years.'
EXEC add_BibleVerse @BibleId, 107003009, N'When the Israelites cried out for help to the Lord, he raised up a deliverer for the Israelites who rescued them. His name was Othniel son of Kenaz, Caleb’s younger brother.'
EXEC add_BibleVerse @BibleId, 107003010, N'The Lord’s spirit empowered him and he led Israel. When he went to do battle, the Lord handed over to him King Cushan-Rishathaim of Aram and he overpowered him.'
EXEC add_BibleVerse @BibleId, 107003011, N'The land had rest for forty years; then Othniel son of Kenaz died.'
EXEC add_BibleVerse @BibleId, 107003012, N'The Israelites again did evil in the Lord’s sight. The Lord gave King Eglon of Moab control over Israel because they had done evil in the Lord’s sight.'
EXEC add_BibleVerse @BibleId, 107003013, N'Eglon formed alliances with the Ammonites and Amalekites. He came and defeated Israel, and they seized the City of Date Palm Trees.'
EXEC add_BibleVerse @BibleId, 107003014, N'The Israelites were subject to King Eglon of Moab for eighteen years.'
EXEC add_BibleVerse @BibleId, 107003015, N'When the Israelites cried out for help to the Lord, he raised up a deliverer for them. His name was Ehud son of Gera the Benjaminite, a left-handed man. The Israelites sent him to King Eglon of Moab with their tribute payment.'
EXEC add_BibleVerse @BibleId, 107003016, N'Ehud made himself a sword – it had two edges and was eighteen inches long. He strapped it under his coat on his right thigh.'
EXEC add_BibleVerse @BibleId, 107003017, N'He brought the tribute payment to King Eglon of Moab. (Now Eglon was a very fat man.)'
EXEC add_BibleVerse @BibleId, 107003018, N'After Ehud brought the tribute payment, he dismissed the people who had carried it.'
EXEC add_BibleVerse @BibleId, 107003019, N'But he went back once he reached the carved images at Gilgal. He said to Eglon, “I have a secret message for you, O king.” Eglon said, “Be quiet!” All his attendants left.'
EXEC add_BibleVerse @BibleId, 107003020, N'When Ehud approached him, he was sitting in his well-ventilated upper room all by himself. Ehud said, “I have a message from God for you.” When Eglon rose up from his seat,'
EXEC add_BibleVerse @BibleId, 107003021, N'Ehud reached with his left hand, pulled the sword from his right thigh, and drove it into Eglon’s belly.'
EXEC add_BibleVerse @BibleId, 107003022, N'The handle went in after the blade, and the fat closed around the blade, for Ehud did not pull the sword out of his belly.'
EXEC add_BibleVerse @BibleId, 107003023, N'As Ehud went out into the vestibule, he closed the doors of the upper room behind him and locked them.'
EXEC add_BibleVerse @BibleId, 107003024, N'When Ehud had left, Eglon’s servants came and saw the locked doors of the upper room. They said, “He must be relieving himself in the well-ventilated inner room.”'
EXEC add_BibleVerse @BibleId, 107003025, N'They waited so long they were embarrassed, but he still did not open the doors of the upper room. Finally they took the key and opened the doors. Right before their eyes was their master, sprawled out dead on the floor!'
EXEC add_BibleVerse @BibleId, 107003026, N'Now Ehud had escaped while they were delaying. When he passed the carved images, he escaped to Seirah.'
EXEC add_BibleVerse @BibleId, 107003027, N'When he reached Seirah, he blew a trumpet in the Ephraimite hill country. The Israelites went down with him from the hill country, with Ehud in the lead.'
EXEC add_BibleVerse @BibleId, 107003028, N'He said to them, “Follow me, for the Lord is about to defeat your enemies, the Moabites!” They followed him, captured the fords of the Jordan River opposite Moab, and did not let anyone cross.'
EXEC add_BibleVerse @BibleId, 107003029, N'That day they killed about ten thousand Moabites – all strong, capable warriors; not one escaped.'
EXEC add_BibleVerse @BibleId, 107003030, N'Israel humiliated Moab that day, and the land had rest for eighty years.'
EXEC add_BibleVerse @BibleId, 107003031, N'After Ehud came Shamgar son of Anath; he killed six hundred Philistines with an oxgoad and, like Ehud, delivered Israel.'
EXEC add_BibleVerse @BibleId, 107004001, N'The Israelites again did evil in the Lord’s sight after Ehud’s death.'
EXEC add_BibleVerse @BibleId, 107004002, N'The Lord turned them over to King Jabin of Canaan, who ruled in Hazor. The general of his army was Sisera, who lived in Harosheth Haggoyim.'
EXEC add_BibleVerse @BibleId, 107004003, N'The Israelites cried out for help to the Lord, because Sisera had nine hundred chariots with iron-rimmed wheels, and he cruelly oppressed the Israelites for twenty years.'
EXEC add_BibleVerse @BibleId, 107004004, N'Now Deborah, a prophetess, wife of Lappidoth, was leading Israel at that time.'
EXEC add_BibleVerse @BibleId, 107004005, N'She would sit under the Date Palm Tree of Deborah between Ramah and Bethel in the Ephraimite hill country. The Israelites would come up to her to have their disputes settled.'
EXEC add_BibleVerse @BibleId, 107004006, N'She summoned Barak son of Abinoam from Kedesh in Naphtali. She said to him, “Is it not true that the Lord God of Israel is commanding you? Go, march to Mount Tabor! Take with you ten thousand men from Naphtali and Zebulun!'
EXEC add_BibleVerse @BibleId, 107004007, N'I will bring Sisera, the general of Jabin’s army, to you at the Kishon River, along with his chariots and huge army. I will hand him over to you.”'
EXEC add_BibleVerse @BibleId, 107004008, N'Barak said to her, “If you go with me, I will go. But if you do not go with me, I will not go.”'
EXEC add_BibleVerse @BibleId, 107004009, N'She said, “I will indeed go with you. But you will not gain fame on the expedition you are undertaking, for the Lord will turn Sisera over to a woman.” Deborah got up and went with Barak to Kedesh.'
EXEC add_BibleVerse @BibleId, 107004010, N'Barak summoned men from Zebulun and Naphtali to Kedesh. Ten thousand men followed him; Deborah went up with him as well.'
EXEC add_BibleVerse @BibleId, 107004011, N'Now Heber the Kenite had moved away from the Kenites, the descendants of Hobab, Moses’ father-in-law. He lived near the great tree in Zaanannim near Kedesh.'
EXEC add_BibleVerse @BibleId, 107004012, N'When Sisera heard that Barak son of Abinoam had gone up to Mount Tabor,'
EXEC add_BibleVerse @BibleId, 107004013, N'he ordered all his chariotry – nine hundred chariots with iron-rimmed wheels – and all the troops he had with him to go from Harosheth-Haggoyim to the River Kishon.'
EXEC add_BibleVerse @BibleId, 107004014, N'Deborah said to Barak, “Spring into action, for this is the day the Lord is handing Sisera over to you! Has the Lord not taken the lead?” Barak quickly went down from Mount Tabor with ten thousand men following him.'
EXEC add_BibleVerse @BibleId, 107004015, N'The Lord routed Sisera, all his chariotry, and all his army with the edge of the sword. Sisera jumped out of his chariot and ran away on foot.'
EXEC add_BibleVerse @BibleId, 107004016, N'Now Barak chased the chariots and the army all the way to Harosheth Haggoyim. Sisera’s whole army died by the edge of the sword; not even one survived!'
EXEC add_BibleVerse @BibleId, 107004017, N'Now Sisera ran away on foot to the tent of Jael, wife of Heber the Kenite, for King Jabin of Hazor and the family of Heber the Kenite had made a peace treaty.'
EXEC add_BibleVerse @BibleId, 107004018, N'Jael came out to welcome Sisera. She said to him, “Stop and rest, my lord. Stop and rest with me. Don’t be afraid.” So Sisera stopped to rest in her tent, and she put a blanket over him.'
EXEC add_BibleVerse @BibleId, 107004019, N'He said to her, “Give me a little water to drink, because I’m thirsty.” She opened a goatskin container of milk and gave him some milk to drink. Then she covered him up again.'
EXEC add_BibleVerse @BibleId, 107004020, N'He said to her, “Stand watch at the entrance to the tent. If anyone comes along and asks you, ‘Is there a man here?’ say ‘No.’”'
EXEC add_BibleVerse @BibleId, 107004021, N'Then Jael wife of Heber took a tent peg in one hand and a hammer in the other. She crept up on him, drove the tent peg through his temple into the ground while he was asleep from exhaustion, and he died.'
EXEC add_BibleVerse @BibleId, 107004022, N'Now Barak was chasing Sisera. Jael went out to welcome him. She said to him, “Come here and I will show you the man you are searching for.” He went with her into the tent, and there he saw Sisera sprawled out dead with the tent peg in his temple.'
EXEC add_BibleVerse @BibleId, 107004023, N'That day God humiliated King Jabin of Canaan before the Israelites.'
EXEC add_BibleVerse @BibleId, 107004024, N'Israel’s power continued to overwhelm King Jabin of Canaan until they did away with him.'
EXEC add_BibleVerse @BibleId, 107005001, N'On that day Deborah and Barak son of Abinoam sang this victory song:'
EXEC add_BibleVerse @BibleId, 107005002, N'“When the leaders took the lead in Israel, When the people answered the call to war – Praise the Lord!'
EXEC add_BibleVerse @BibleId, 107005003, N'Hear, O kings! Pay attention, O rulers! I will sing to the Lord! I will sing to the Lord God of Israel!'
EXEC add_BibleVerse @BibleId, 107005004, N'O Lord, when you departed from Seir, when you marched from Edom’s plains, the earth shook, the heavens poured down, the clouds poured down rain.'
EXEC add_BibleVerse @BibleId, 107005005, N'The mountains trembled before the Lord, the God of Sinai; before the Lord God of Israel.'
EXEC add_BibleVerse @BibleId, 107005006, N'In the days of Shamgar son of Anath, in the days of Jael caravans disappeared; travelers had to go on winding side roads.'
EXEC add_BibleVerse @BibleId, 107005007, N'Warriors were scarce, they were scarce in Israel, until you arose, Deborah, until you arose as a motherly protector in Israel.'
EXEC add_BibleVerse @BibleId, 107005008, N'God chose new leaders, then fighters appeared in the city gates; but, I swear, not a shield or spear could be found, among forty military units in Israel.'
EXEC add_BibleVerse @BibleId, 107005009, N'My heart went out to Israel’s leaders, to the people who answered the call to war. Praise the Lord!'
EXEC add_BibleVerse @BibleId, 107005010, N'You who ride on light-colored female donkeys, who sit on saddle blankets, you who walk on the road, pay attention!'
EXEC add_BibleVerse @BibleId, 107005011, N'Hear the sound of those who divide the sheep among the watering places; there they tell of the Lord’s victorious deeds, the victorious deeds of his warriors in Israel. Then the Lord’s people went down to the city gates –'
EXEC add_BibleVerse @BibleId, 107005012, N'Wake up, wake up, Deborah! Wake up, wake up, sing a song! Get up, Barak! Capture your prisoners of war, son of Abinoam!'
EXEC add_BibleVerse @BibleId, 107005013, N'Then the survivors came down to the mighty ones; the Lord’s people came down to me as warriors.'
EXEC add_BibleVerse @BibleId, 107005014, N'They came from Ephraim, who uprooted Amalek, they follow after you, Benjamin, with your soldiers. From Makir leaders came down, from Zebulun came the ones who march carrying an officer’s staff.'
EXEC add_BibleVerse @BibleId, 107005015, N'Issachar’s leaders were with Deborah, the men of Issachar supported Barak; into the valley they were sent under Barak’s command. Among the clans of Reuben there was intense heart searching.'
EXEC add_BibleVerse @BibleId, 107005016, N'Why do you remain among the sheepfolds, listening to the shepherds playing their pipes for their flocks? As for the clans of Reuben – there was intense searching of heart.'
EXEC add_BibleVerse @BibleId, 107005017, N'Gilead stayed put beyond the Jordan River. As for Dan – why did he seek temporary employment in the shipyards? Asher remained on the seacoast, he stayed by his harbors.'
EXEC add_BibleVerse @BibleId, 107005018, N'The men of Zebulun were not concerned about their lives; Naphtali charged on to the battlefields.'
EXEC add_BibleVerse @BibleId, 107005019, N'Kings came, they fought; the kings of Canaan fought, at Taanach by the waters of Megiddo, but they took no silver as plunder.'
EXEC add_BibleVerse @BibleId, 107005020, N'From the sky the stars fought, from their paths in the heavens they fought against Sisera.'
EXEC add_BibleVerse @BibleId, 107005021, N'The Kishon River carried them off; the river confronted them – the Kishon River. Step on the necks of the strong!'
EXEC add_BibleVerse @BibleId, 107005022, N'The horses’ hooves pounded the ground; the stallions galloped madly.'
EXEC add_BibleVerse @BibleId, 107005023, N'‘Call judgment down on Meroz,’ says the Lord’s angelic messenger; ‘Be sure to call judgment down on those who live there, because they did not come to help in the Lord’s battle, to help in the Lord’s battle against the warriors.’'
EXEC add_BibleVerse @BibleId, 107005024, N'The most rewarded of women should be Jael, the wife of Heber the Kenite! She should be the most rewarded of women who live in tents.'
EXEC add_BibleVerse @BibleId, 107005025, N'He asked for water, and she gave him milk; in a bowl fit for a king, she served him curds.'
EXEC add_BibleVerse @BibleId, 107005026, N'Her left hand reached for the tent peg, her right hand for the workmen’s hammer. She “hammered” Sisera, she shattered his skull, she smashed his head, she drove the tent peg through his temple.'
EXEC add_BibleVerse @BibleId, 107005027, N'Between her feet he collapsed, he fell limp and was lifeless; between her feet he collapsed and fell limp, in the spot where he collapsed, there he fell limp – violently murdered!'
EXEC add_BibleVerse @BibleId, 107005028, N'Through the window she looked; Sisera’s mother cried out through the lattice: ‘Why is his chariot so slow to return? Why are the hoofbeats of his chariot-horses delayed?’'
EXEC add_BibleVerse @BibleId, 107005029, N'The wisest of her ladies answer; indeed she even thinks to herself,'
EXEC add_BibleVerse @BibleId, 107005030, N'‘No doubt they are gathering and dividing the plunder – a girl or two for each man to rape! Sisera is grabbing up colorful cloth, he is grabbing up colorful embroidered cloth, two pieces of colorful embroidered cloth, for the neck of the plunderer!’'
EXEC add_BibleVerse @BibleId, 107005031, N'May all your enemies perish like this, O Lord! But may those who love you shine like the rising sun at its brightest!” And the land had rest for forty years.'
EXEC add_BibleVerse @BibleId, 107006001, N'The Israelites did evil in the Lord’s sight, so the Lord turned them over to Midian for seven years.'
EXEC add_BibleVerse @BibleId, 107006002, N'The Midianites overwhelmed Israel. Because of Midian the Israelites made shelters for themselves in the hills, as well as caves and strongholds.'
EXEC add_BibleVerse @BibleId, 107006003, N'Whenever the Israelites planted their crops, the Midianites, Amalekites, and the people from the east would attack them.'
EXEC add_BibleVerse @BibleId, 107006004, N'They invaded the land and devoured its crops all the way to Gaza. They left nothing for the Israelites to eat, and they took away the sheep, oxen, and donkeys.'
EXEC add_BibleVerse @BibleId, 107006005, N'When they invaded with their cattle and tents, they were as thick as locusts. Neither they nor their camels could be counted. They came to devour the land.'
EXEC add_BibleVerse @BibleId, 107006006, N'Israel was so severely weakened by Midian that the Israelites cried out to the Lord for help.'
EXEC add_BibleVerse @BibleId, 107006007, N'When the Israelites cried out to the Lord for help because of Midian,'
EXEC add_BibleVerse @BibleId, 107006008, N'he sent a prophet to the Israelites. He said to them, “This is what the Lord God of Israel says: ‘I brought you up from Egypt and took you out of that place of slavery.'
EXEC add_BibleVerse @BibleId, 107006009, N'I rescued you from Egypt’s power and from the power of all who oppressed you. I drove them out before you and gave their land to you.'
EXEC add_BibleVerse @BibleId, 107006010, N'I said to you, “I am the Lord your God! Do not worship the gods of the Amorites, in whose land you are now living!” But you have disobeyed me.’”'
EXEC add_BibleVerse @BibleId, 107006011, N'The Lord’s angelic messenger came and sat down under the oak tree in Ophrah owned by Joash the Abiezrite. He arrived while Joash’s son Gideon was threshing wheat in a winepress so he could hide it from the Midianites.'
EXEC add_BibleVerse @BibleId, 107006012, N'The Lord’s messenger appeared and said to him, “The Lord is with you, courageous warrior!”'
EXEC add_BibleVerse @BibleId, 107006013, N'Gideon said to him, “Pardon me, but if the Lord is with us, why has such disaster overtaken us? Where are all his miraculous deeds our ancestors told us about? They said, ‘Did the Lord not bring us up from Egypt?’ But now the Lord has abandoned us and handed us over to Midian.”'
EXEC add_BibleVerse @BibleId, 107006014, N'Then the Lord himself turned to him and said, “You have the strength. Deliver Israel from the power of the Midianites! Have I not sent you?”'
EXEC add_BibleVerse @BibleId, 107006015, N'Gideon said to him, “But Lord, how can I deliver Israel? Just look! My clan is the weakest in Manasseh, and I am the youngest in my family.”'
EXEC add_BibleVerse @BibleId, 107006016, N'The Lord said to him, “Ah, but I will be with you! You will strike down the whole Midianite army.”'
EXEC add_BibleVerse @BibleId, 107006017, N'Gideon said to him, “If you really are pleased with me, then give me a sign as proof that it is really you speaking with me.'
EXEC add_BibleVerse @BibleId, 107006018, N'Do not leave this place until I come back with a gift and present it to you.” The Lord said, “I will stay here until you come back.”'
EXEC add_BibleVerse @BibleId, 107006019, N'Gideon went and prepared a young goat, along with unleavened bread made from an ephah of flour. He put the meat in a basket and the broth in a pot. He brought the food to him under the oak tree and presented it to him.'
EXEC add_BibleVerse @BibleId, 107006020, N'God’s messenger said to him, “Put the meat and unleavened bread on this rock, and pour out the broth.” Gideon did as instructed.'
EXEC add_BibleVerse @BibleId, 107006021, N'The Lord’s messenger touched the meat and the unleavened bread with the tip of his staff. Fire flared up from the rock and consumed the meat and unleavened bread. The Lord’s messenger then disappeared.'
EXEC add_BibleVerse @BibleId, 107006022, N'When Gideon realized that it was the Lord’s messenger, he said, “Oh no! Master, Lord! I have seen the Lord’s messenger face to face!”'
EXEC add_BibleVerse @BibleId, 107006023, N'The Lord said to him, “You are safe! Do not be afraid! You are not going to die!”'
EXEC add_BibleVerse @BibleId, 107006024, N'Gideon built an altar for the Lord there, and named it “The Lord is on friendly terms with me.” To this day it is still there in Ophrah of the Abiezrites.'
EXEC add_BibleVerse @BibleId, 107006025, N'That night the Lord said to him, “Take the bull from your father’s herd, as well as a second bull, one that is seven years old. Pull down your father’s Baal altar and cut down the nearby Asherah pole.'
EXEC add_BibleVerse @BibleId, 107006026, N'Then build an altar for the Lord your God on the top of this stronghold according to the proper pattern. Take the second bull and offer it as a burnt sacrifice on the wood from the Asherah pole that you cut down.”'
EXEC add_BibleVerse @BibleId, 107006027, N'So Gideon took ten of his servants and did just as the Lord had told him. He was too afraid of his father’s family and the men of the city to do it in broad daylight, so he waited until nighttime.'
EXEC add_BibleVerse @BibleId, 107006028, N'When the men of the city got up the next morning, they saw the Baal altar pulled down, the nearby Asherah pole cut down, and the second bull sacrificed on the newly built altar.'
EXEC add_BibleVerse @BibleId, 107006029, N'They said to one another, “Who did this?” They investigated the matter thoroughly and concluded that Gideon son of Joash had done it.'
EXEC add_BibleVerse @BibleId, 107006030, N'The men of the city said to Joash, “Bring out your son, so we can execute him! He pulled down the Baal altar and cut down the nearby Asherah pole.”'
EXEC add_BibleVerse @BibleId, 107006031, N'But Joash said to all those who confronted him, “Must you fight Baal’s battles? Must you rescue him? Whoever takes up his cause will die by morning! If he really is a god, let him fight his own battles! After all, it was his altar that was pulled down.”'
EXEC add_BibleVerse @BibleId, 107006032, N'That very day Gideon’s father named him Jerub-Baal, because he had said, “Let Baal fight with him, for it was his altar that was pulled down.”'
EXEC add_BibleVerse @BibleId, 107006033, N'All the Midianites, Amalekites, and the people from the east assembled. They crossed the Jordan River and camped in the Jezreel Valley.'
EXEC add_BibleVerse @BibleId, 107006034, N'The Lord’s spirit took control of Gideon. He blew a trumpet, summoning the Abiezrites to follow him.'
EXEC add_BibleVerse @BibleId, 107006035, N'He sent messengers throughout Manasseh and summoned them to follow him as well. He also sent messengers throughout Asher, Zebulun, and Naphtali, and they came up to meet him.'
EXEC add_BibleVerse @BibleId, 107006036, N'Gideon said to God, “If you really intend to use me to deliver Israel, as you promised, then give me a sign as proof.'
EXEC add_BibleVerse @BibleId, 107006037, N'Look, I am putting a wool fleece on the threshing floor. If there is dew only on the fleece, and the ground around it is dry, then I will be sure that you will use me to deliver Israel, as you promised.”'
EXEC add_BibleVerse @BibleId, 107006038, N'The Lord did as he asked. When he got up the next morning, he squeezed the fleece, and enough dew dripped from it to fill a bowl.'
EXEC add_BibleVerse @BibleId, 107006039, N'Gideon said to God, “Please do not get angry at me, when I ask for just one more sign. Please allow me one more test with the fleece. This time make only the fleece dry, while the ground around it is covered with dew.”'
EXEC add_BibleVerse @BibleId, 107006040, N'That night God did as he asked. Only the fleece was dry and the ground around it was covered with dew.'
EXEC add_BibleVerse @BibleId, 107007001, N'Jerub-Baal (that is, Gideon) and his men got up the next morning and camped near the spring of Harod. The Midianites were camped north of them near the hill of Moreh in the valley.'
EXEC add_BibleVerse @BibleId, 107007002, N'The Lord said to Gideon, “You have too many men for me to hand Midian over to you. Israel might brag, ‘Our own strength has delivered us.’'
EXEC add_BibleVerse @BibleId, 107007003, N'Now, announce to the men, ‘Whoever is shaking with fear may turn around and leave Mount Gilead.’” Twenty-two thousand men went home; ten thousand remained.'
EXEC add_BibleVerse @BibleId, 107007004, N'The Lord spoke to Gideon again, “There are still too many men. Bring them down to the water and I will thin the ranks some more. When I say, ‘This one should go with you,’ pick him to go; when I say, ‘This one should not go with you,’ do not take him.”'
EXEC add_BibleVerse @BibleId, 107007005, N'So he brought the men down to the water. Then the Lord said to Gideon, “Separate those who lap the water as a dog laps from those who kneel to drink.”'
EXEC add_BibleVerse @BibleId, 107007006, N'Three hundred men lapped; the rest of the men kneeled to drink water.'
EXEC add_BibleVerse @BibleId, 107007007, N'The Lord said to Gideon, “With the three hundred men who lapped I will deliver the whole army and I will hand Midian over to you. The rest of the men should go home.”'
EXEC add_BibleVerse @BibleId, 107007008, N'The men who were chosen took supplies and their trumpets. Gideon sent all the men of Israel back to their homes; he kept only three hundred men. Now the Midianites were camped down below in the valley.'
EXEC add_BibleVerse @BibleId, 107007009, N'That night the Lord said to Gideon, “Get up! Attack the camp, for I am handing it over to you.'
EXEC add_BibleVerse @BibleId, 107007010, N'But if you are afraid to attack, go down to the camp with Purah your servant'
EXEC add_BibleVerse @BibleId, 107007011, N'and listen to what they are saying. Then you will be brave and attack the camp.” So he went down with Purah his servant to where the sentries were guarding the camp.'
EXEC add_BibleVerse @BibleId, 107007012, N'Now the Midianites, Amalekites, and the people from the east covered the valley like a swarm of locusts. Their camels could not be counted; they were as innumerable as the sand on the seashore.'
EXEC add_BibleVerse @BibleId, 107007013, N'When Gideon arrived, he heard a man telling another man about a dream he had. The man said, “Look! I had a dream. I saw a stale cake of barley bread rolling into the Midianite camp. It hit a tent so hard it knocked it over and turned it upside down. The tent just collapsed.”'
EXEC add_BibleVerse @BibleId, 107007014, N'The other man said, “Without a doubt this symbolizes the sword of Gideon son of Joash, the Israelite. God is handing Midian and all the army over to him.”'
EXEC add_BibleVerse @BibleId, 107007015, N'When Gideon heard the report of the dream and its interpretation, he praised God. Then he went back to the Israelite camp and said, “Get up, for the Lord is handing the Midianite army over to you!”'
EXEC add_BibleVerse @BibleId, 107007016, N'He divided the three hundred men into three units. He gave them all trumpets and empty jars with torches inside them.'
EXEC add_BibleVerse @BibleId, 107007017, N'He said to them, “Watch me and do as I do. Watch closely! I am going to the edge of the camp. Do as I do!'
EXEC add_BibleVerse @BibleId, 107007018, N'When I and all who are with me blow our trumpets, you also blow your trumpets all around the camp. Then say, ‘For the Lord and for Gideon!’”'
EXEC add_BibleVerse @BibleId, 107007019, N'Gideon took a hundred men to the edge of the camp at the beginning of the middle watch, just after they had changed the guards. They blew their trumpets and broke the jars they were carrying.'
EXEC add_BibleVerse @BibleId, 107007020, N'All three units blew their trumpets and broke their jars. They held the torches in their left hand and the trumpets in their right. Then they yelled, “A sword for the Lord and for Gideon!”'
EXEC add_BibleVerse @BibleId, 107007021, N'They stood in order all around the camp. The whole army ran away; they shouted as they scrambled away.'
EXEC add_BibleVerse @BibleId, 107007022, N'When the three hundred men blew their trumpets, the Lord caused the Midianites to attack one another with their swords throughout the camp. The army fled to Beth Shittah on the way to Zererah. They went to the border of Abel Meholah near Tabbath.'
EXEC add_BibleVerse @BibleId, 107007023, N'Israelites from Naphtali, Asher, and Manasseh answered the call and chased the Midianites.'
EXEC add_BibleVerse @BibleId, 107007024, N'Now Gideon sent messengers throughout the Ephraimite hill country who announced, “Go down and head off the Midianites. Take control of the fords of the streams all the way to Beth Barah and the Jordan River.” When all the Ephraimites had assembled, they took control of the fords all the way to Beth Barah and the Jordan River.'
EXEC add_BibleVerse @BibleId, 107007025, N'They captured the two Midianite generals, Oreb and Zeeb. They executed Oreb on the rock of Oreb and Zeeb in the winepress of Zeeb. They chased the Midianites and brought the heads of Oreb and Zeeb to Gideon, who was now on the other side of the Jordan River.'
EXEC add_BibleVerse @BibleId, 107008001, N'The Ephraimites said to him, “Why have you done such a thing to us? You did not summon us when you went to fight the Midianites!” They argued vehemently with him.'
EXEC add_BibleVerse @BibleId, 107008002, N'He said to them, “Now what have I accomplished compared to you? Even Ephraim’s leftover grapes are better quality than Abiezer’s harvest!'
EXEC add_BibleVerse @BibleId, 107008003, N'It was to you that God handed over the Midianite generals, Oreb and Zeeb! What did I accomplish to rival that?” When he said this, they calmed down.'
EXEC add_BibleVerse @BibleId, 107008004, N'Now Gideon and his three hundred men had crossed over the Jordan River, and even though they were exhausted, they were still chasing the Midianites.'
EXEC add_BibleVerse @BibleId, 107008005, N'He said to the men of Succoth, “Give some loaves of bread to the men who are following me, because they are exhausted. I am chasing Zebah and Zalmunna, the kings of Midian.”'
EXEC add_BibleVerse @BibleId, 107008006, N'The officials of Succoth said, “You have not yet overpowered Zebah and Zalmunna. So why should we give bread to your army?”'
EXEC add_BibleVerse @BibleId, 107008007, N'Gideon said, “Since you will not help, after the Lord hands Zebah and Zalmunna over to me, I will thresh your skin with desert thorns and briers.”'
EXEC add_BibleVerse @BibleId, 107008008, N'He went up from there to Penuel and made the same request. The men of Penuel responded the same way the men of Succoth had.'
EXEC add_BibleVerse @BibleId, 107008009, N'He also threatened the men of Penuel, warning, “When I return victoriously, I will tear down this tower.”'
EXEC add_BibleVerse @BibleId, 107008010, N'Now Zebah and Zalmunna were in Karkor with their armies. There were about fifteen thousand survivors from the army of the eastern peoples; a hundred and twenty thousand sword-wielding soldiers had been killed.'
EXEC add_BibleVerse @BibleId, 107008011, N'Gideon went up the road of the nomads east of Nobah and Jogbehah and ambushed the surprised army.'
EXEC add_BibleVerse @BibleId, 107008012, N'When Zebah and Zalmunna ran away, Gideon chased them and captured the two Midianite kings, Zebah and Zalmunna. He had surprised their entire army.'
EXEC add_BibleVerse @BibleId, 107008013, N'Gideon son of Joash returned from the battle by the pass of Heres.'
EXEC add_BibleVerse @BibleId, 107008014, N'He captured a young man from Succoth and interrogated him. The young man wrote down for him the names of Succoth’s officials and city leaders – seventy-seven men in all.'
EXEC add_BibleVerse @BibleId, 107008015, N'He approached the men of Succoth and said, “Look what I have! Zebah and Zalmunna! You insulted me, saying, ‘You have not yet overpowered Zebah and Zalmunna. So why should we give bread to your exhausted men?’”'
EXEC add_BibleVerse @BibleId, 107008016, N'He seized the leaders of the city, along with some desert thorns and briers; he then “threshed” the men of Succoth with them.'
EXEC add_BibleVerse @BibleId, 107008017, N'He also tore down the tower of Penuel and executed the city’s men.'
EXEC add_BibleVerse @BibleId, 107008018, N'He said to Zebah and Zalmunna, “Describe for me the men you killed at Tabor.” They said, “They were like you. Each one looked like a king’s son.”'
EXEC add_BibleVerse @BibleId, 107008019, N'He said, “They were my brothers, the sons of my mother. I swear, as surely as the Lord is alive, if you had let them live, I would not kill you.”'
EXEC add_BibleVerse @BibleId, 107008020, N'He ordered Jether his firstborn son, “Come on! Kill them!” But Jether was too afraid to draw his sword, because he was still young.'
EXEC add_BibleVerse @BibleId, 107008021, N'Zebah and Zalmunna said to Gideon, “Come on, you strike us, for a man is judged by his strength.” So Gideon killed Zebah and Zalmunna, and he took the crescent-shaped ornaments which were on the necks of their camels.'
EXEC add_BibleVerse @BibleId, 107008022, N'The men of Israel said to Gideon, “Rule over us – you, your son, and your grandson. For you have delivered us from Midian’s power.”'
EXEC add_BibleVerse @BibleId, 107008023, N'Gideon said to them, “I will not rule over you, nor will my son rule over you. The Lord will rule over you.”'
EXEC add_BibleVerse @BibleId, 107008024, N'Gideon continued, “I would like to make one request. Each of you give me an earring from the plunder you have taken.” (The Midianites had gold earrings because they were Ishmaelites.)'
EXEC add_BibleVerse @BibleId, 107008025, N'They said, “We are happy to give you earrings.” So they spread out a garment, and each one threw an earring from his plunder onto it.'
EXEC add_BibleVerse @BibleId, 107008026, N'The total weight of the gold earrings he requested came to seventeen hundred gold shekels. This was in addition to the crescent-shaped ornaments, jewelry, purple clothing worn by the Midianite kings, and the necklaces on the camels.'
EXEC add_BibleVerse @BibleId, 107008027, N'Gideon used all this to make an ephod, which he put in his hometown of Ophrah. All the Israelites prostituted themselves to it by worshiping it there. It became a snare to Gideon and his family.'
EXEC add_BibleVerse @BibleId, 107008028, N'The Israelites humiliated Midian; the Midianites’ fighting spirit was broken. The land had rest for forty years during Gideon’s time.'
EXEC add_BibleVerse @BibleId, 107008029, N'Then Jerub-Baal son of Joash went home and settled down.'
EXEC add_BibleVerse @BibleId, 107008030, N'Gideon fathered seventy sons through his many wives.'
EXEC add_BibleVerse @BibleId, 107008031, N'His concubine, who lived in Shechem, also gave him a son, whom he named Abimelech.'
EXEC add_BibleVerse @BibleId, 107008032, N'Gideon son of Joash died at a very old age and was buried in the tomb of his father Joash located in Ophrah of the Abiezrites.'
EXEC add_BibleVerse @BibleId, 107008033, N'After Gideon died, the Israelites again prostituted themselves to the Baals. They made Baal-Berith their god.'
EXEC add_BibleVerse @BibleId, 107008034, N'The Israelites did not remain true to the Lord their God, who had delivered them from all the enemies who lived around them.'
EXEC add_BibleVerse @BibleId, 107008035, N'They did not treat the family of Jerub-Baal (that is, Gideon) fairly in return for all the good he had done for Israel.'
EXEC add_BibleVerse @BibleId, 107009001, N'Now Abimelech son of Jerub-Baal went to Shechem to see his mother’s relatives. He said to them and to his mother’s entire extended family,'
EXEC add_BibleVerse @BibleId, 107009002, N'“Tell all the leaders of Shechem this: ‘Why would you want to have seventy men, all Jerub-Baal’s sons, ruling over you, when you can have just one ruler? Recall that I am your own flesh and blood.’”'
EXEC add_BibleVerse @BibleId, 107009003, N'His mother’s relatives spoke on his behalf to all the leaders of Shechem and reported his proposal. The leaders were drawn to Abimelech; they said, “He is our close relative.”'
EXEC add_BibleVerse @BibleId, 107009004, N'They paid him seventy silver shekels out of the temple of Baal-Berith. Abimelech then used the silver to hire some lawless, dangerous men as his followers.'
EXEC add_BibleVerse @BibleId, 107009005, N'He went to his father’s home in Ophrah and murdered his half-brothers, the seventy legitimate sons of Jerub-Baal, on one stone. Only Jotham, Jerub-Baal’s youngest son, escaped, because he hid.'
EXEC add_BibleVerse @BibleId, 107009006, N'All the leaders of Shechem and Beth Millo assembled and then went and made Abimelech king by the oak near the pillar in Shechem.'
EXEC add_BibleVerse @BibleId, 107009007, N'When Jotham heard the news, he went and stood on the top of Mount Gerizim. He spoke loudly to the people below, “Listen to me, leaders of Shechem, so that God may listen to you!'
EXEC add_BibleVerse @BibleId, 107009008, N'“The trees were determined to go out and choose a king for themselves. They said to the olive tree, ‘Be our king!’'
EXEC add_BibleVerse @BibleId, 107009009, N'But the olive tree said to them, ‘I am not going to stop producing my oil, which is used to honor gods and men, just to sway above the other trees!’'
EXEC add_BibleVerse @BibleId, 107009010, N'“So the trees said to the fig tree, ‘You come and be our king!’'
EXEC add_BibleVerse @BibleId, 107009011, N'But the fig tree said to them, ‘I am not going to stop producing my sweet figs, my excellent fruit, just to sway above the other trees!’'
EXEC add_BibleVerse @BibleId, 107009012, N'“So the trees said to the grapevine, ‘You come and be our king!’'
EXEC add_BibleVerse @BibleId, 107009013, N'But the grapevine said to them, ‘I am not going to stop producing my wine, which makes gods and men so happy, just to sway above the other trees!’'
EXEC add_BibleVerse @BibleId, 107009014, N'“So all the trees said to the thornbush, ‘You come and be our king!’'
EXEC add_BibleVerse @BibleId, 107009015, N'The thornbush said to the trees, ‘If you really want to choose me as your king, then come along, find safety under my branches! Otherwise may fire blaze from the thornbush and consume the cedars of Lebanon!’'
EXEC add_BibleVerse @BibleId, 107009016, N'“Now, if you have shown loyalty and integrity when you made Abimelech king, if you have done right to Jerub-Baal and his family, if you have properly repaid him –'
EXEC add_BibleVerse @BibleId, 107009017, N'my father fought for you; he risked his life and delivered you from Midian’s power.'
EXEC add_BibleVerse @BibleId, 107009018, N'But you have attacked my father’s family today. You murdered his seventy legitimate sons on one stone and made Abimelech, the son of his female slave, king over the leaders of Shechem, just because he is your close relative.'
EXEC add_BibleVerse @BibleId, 107009019, N'So if you have shown loyalty and integrity to Jerub-Baal and his family today, then may Abimelech bring you happiness and may you bring him happiness!'
EXEC add_BibleVerse @BibleId, 107009020, N'But if not, may fire blaze from Abimelech and consume the leaders of Shechem and Beth Millo! May fire also blaze from the leaders of Shechem and Beth Millo and consume Abimelech!”'
EXEC add_BibleVerse @BibleId, 107009021, N'Then Jotham ran away to Beer and lived there to escape from Abimelech his half-brother.'
EXEC add_BibleVerse @BibleId, 107009022, N'Abimelech commanded Israel for three years.'
EXEC add_BibleVerse @BibleId, 107009023, N'God sent a spirit to stir up hostility between Abimelech and the leaders of Shechem. He made the leaders of Shechem disloyal to Abimelech.'
EXEC add_BibleVerse @BibleId, 107009024, N'He did this so the violent deaths of Jerub-Baal’s seventy sons might be avenged and Abimelech, their half-brother who murdered them, might have to pay for their spilled blood, along with the leaders of Shechem who helped him murder them.'
EXEC add_BibleVerse @BibleId, 107009025, N'The leaders of Shechem rebelled against Abimelech by putting bandits in the hills, who robbed everyone who traveled by on the road. But Abimelech found out about it.'
EXEC add_BibleVerse @BibleId, 107009026, N'Gaal son of Ebed came through Shechem with his brothers. The leaders of Shechem transferred their loyalty to him.'
EXEC add_BibleVerse @BibleId, 107009027, N'They went out to the field, harvested their grapes, squeezed out the juice, and celebrated. They came to the temple of their god and ate, drank, and cursed Abimelech.'
EXEC add_BibleVerse @BibleId, 107009028, N'Gaal son of Ebed said, “Who is Abimelech and who is Shechem, that we should serve him? Is he not the son of Jerub-Baal, and is not Zebul the deputy he appointed? Serve the sons of Hamor, the father of Shechem! But why should we serve Abimelech?'
EXEC add_BibleVerse @BibleId, 107009029, N'If only these men were under my command, I would get rid of Abimelech!” He challenged Abimelech, “Muster your army and come out for battle!”'
EXEC add_BibleVerse @BibleId, 107009030, N'When Zebul, the city commissioner, heard the words of Gaal son of Ebed, he was furious.'
EXEC add_BibleVerse @BibleId, 107009031, N'He sent messengers to Abimelech, who was in Arumah, reporting, “Beware! Gaal son of Ebed and his brothers are coming to Shechem and inciting the city to rebel against you.'
EXEC add_BibleVerse @BibleId, 107009032, N'Now, come up at night with your men and set an ambush in the field outside the city.'
EXEC add_BibleVerse @BibleId, 107009033, N'In the morning at sunrise quickly attack the city. When he and his men come out to fight you, do what you can to him.”'
EXEC add_BibleVerse @BibleId, 107009034, N'So Abimelech and all his men came up at night and set an ambush outside Shechem – they divided into four units.'
EXEC add_BibleVerse @BibleId, 107009035, N'When Gaal son of Ebed came out and stood at the entrance to the city’s gate, Abimelech and his men got up from their hiding places.'
EXEC add_BibleVerse @BibleId, 107009036, N'Gaal saw the men and said to Zebul, “Look, men are coming down from the tops of the hills.” But Zebul said to him, “You are seeing the shadows on the hills – it just looks like men.”'
EXEC add_BibleVerse @BibleId, 107009037, N'Gaal again said, “Look, men are coming down from the very center of the land. A unit is coming by way of the Oak Tree of the Diviners.”'
EXEC add_BibleVerse @BibleId, 107009038, N'Zebul said to him, “Where now are your bragging words, ‘Who is Abimelech that we should serve him?’ Are these not the men you insulted? Go out now and fight them!”'
EXEC add_BibleVerse @BibleId, 107009039, N'So Gaal led the leaders of Shechem out and fought Abimelech.'
EXEC add_BibleVerse @BibleId, 107009040, N'Abimelech chased him, and Gaal ran from him. Many Shechemites fell wounded at the entrance of the gate.'
EXEC add_BibleVerse @BibleId, 107009041, N'Abimelech went back to Arumah; Zebul drove Gaal and his brothers out of Shechem.'
EXEC add_BibleVerse @BibleId, 107009042, N'The next day the Shechemites came out to the field. When Abimelech heard about it,'
EXEC add_BibleVerse @BibleId, 107009043, N'he took his men and divided them into three units and set an ambush in the field. When he saw the people coming out of the city, he attacked and struck them down.'
EXEC add_BibleVerse @BibleId, 107009044, N'Abimelech and his units attacked and blocked the entrance to the city’s gate. Two units then attacked all the people in the field and struck them down.'
EXEC add_BibleVerse @BibleId, 107009045, N'Abimelech fought against the city all that day. He captured the city and killed all the people in it. Then he leveled the city and spread salt over it.'
EXEC add_BibleVerse @BibleId, 107009046, N'When all the leaders of the Tower of Shechem heard the news, they went to the stronghold of the temple of El-Berith.'
EXEC add_BibleVerse @BibleId, 107009047, N'Abimelech heard that all the leaders of the Tower of Shechem were in one place.'
EXEC add_BibleVerse @BibleId, 107009048, N'He and all his men went up on Mount Zalmon. He took an ax in his hand and cut off a tree branch. He put it on his shoulder and said to his men, “Quickly, do what you have just seen me do!”'
EXEC add_BibleVerse @BibleId, 107009049, N'So each of his men also cut off a branch and followed Abimelech. They put the branches against the stronghold and set fire to it. All the people of the Tower of Shechem died – about a thousand men and women.'
EXEC add_BibleVerse @BibleId, 107009050, N'Abimelech moved on to Thebez; he besieged and captured it.'
EXEC add_BibleVerse @BibleId, 107009051, N'There was a fortified tower in the center of the city, so all the men and women, as well as the city’s leaders, ran into it and locked the entrance. Then they went up to the roof of the tower.'
EXEC add_BibleVerse @BibleId, 107009052, N'Abimelech came and attacked the tower. When he approached the entrance of the tower to set it on fire,'
EXEC add_BibleVerse @BibleId, 107009053, N'a woman threw an upper millstone down on his head and shattered his skull.'
EXEC add_BibleVerse @BibleId, 107009054, N'He quickly called to the young man who carried his weapons, “Draw your sword and kill me, so they will not say, ‘A woman killed him.’” So the young man stabbed him and he died.'
EXEC add_BibleVerse @BibleId, 107009055, N'When the Israelites saw that Abimelech was dead, they went home.'
EXEC add_BibleVerse @BibleId, 107009056, N'God repaid Abimelech for the evil he did to his father by murdering his seventy half-brothers.'
EXEC add_BibleVerse @BibleId, 107009057, N'God also repaid the men of Shechem for their evil deeds. The curse spoken by Jotham son of Jerub-Baal fell on them.'
EXEC add_BibleVerse @BibleId, 107010001, N'After Abimelech’s death, Tola son of Puah, grandson of Dodo, from the tribe of Issachar, rose up to deliver Israel. He lived in Shamir in the Ephraimite hill country.'
EXEC add_BibleVerse @BibleId, 107010002, N'He led Israel for twenty-three years, then died and was buried in Shamir.'
EXEC add_BibleVerse @BibleId, 107010003, N'Jair the Gileadite rose up after him; he led Israel for twenty-two years.'
EXEC add_BibleVerse @BibleId, 107010004, N'He had thirty sons who rode on thirty donkeys and possessed thirty cities. To this day these towns are called Havvoth Jair – they are in the land of Gilead.'
EXEC add_BibleVerse @BibleId, 107010005, N'Jair died and was buried in Kamon.'
EXEC add_BibleVerse @BibleId, 107010006, N'The Israelites again did evil in the Lord’s sight. They worshiped the Baals and the Ashtars, as well as the gods of Syria, Sidon, Moab, the Ammonites, and the Philistines. They abandoned the Lord and did not worship him.'
EXEC add_BibleVerse @BibleId, 107010007, N'The Lord was furious with Israel and turned them over to the Philistines and Ammonites.'
EXEC add_BibleVerse @BibleId, 107010008, N'They ruthlessly oppressed the Israelites that eighteenth year – that is, all the Israelites living east of the Jordan in Amorite country in Gilead.'
EXEC add_BibleVerse @BibleId, 107010009, N'The Ammonites crossed the Jordan to fight with Judah, Benjamin, and Ephraim. Israel suffered greatly.'
EXEC add_BibleVerse @BibleId, 107010010, N'The Israelites cried out for help to the Lord: “We have sinned against you. We abandoned our God and worshiped the Baals.”'
EXEC add_BibleVerse @BibleId, 107010011, N'The Lord said to the Israelites, “Did I not deliver you from Egypt, the Amorites, the Ammonites, the Philistines,'
EXEC add_BibleVerse @BibleId, 107010012, N'the Sidonians, Amalek, and Midian when they oppressed you? You cried out for help to me, and I delivered you from their power.'
EXEC add_BibleVerse @BibleId, 107010013, N'But since you abandoned me and worshiped other gods, I will not deliver you again.'
EXEC add_BibleVerse @BibleId, 107010014, N'Go and cry for help to the gods you have chosen! Let them deliver you from trouble!”'
EXEC add_BibleVerse @BibleId, 107010015, N'But the Israelites said to the Lord, “We have sinned. You do to us as you see fit, but deliver us today!”'
EXEC add_BibleVerse @BibleId, 107010016, N'They threw away the foreign gods they owned and worshiped the Lord. Finally the Lord grew tired of seeing Israel suffer so much.'
EXEC add_BibleVerse @BibleId, 107010017, N'The Ammonites assembled and camped in Gilead; the Israelites gathered together and camped in Mizpah.'
EXEC add_BibleVerse @BibleId, 107010018, N'The leaders of Gilead said to one another, “Who is willing to lead the charge against the Ammonites? He will become the leader of all who live in Gilead!”'
EXEC add_BibleVerse @BibleId, 107011001, N'Now Jephthah the Gileadite was a brave warrior. His mother was a prostitute, but Gilead was his father.'
EXEC add_BibleVerse @BibleId, 107011002, N'Gilead’s wife also gave him sons. When his wife’s sons grew up, they made Jephthah leave and said to him, “You are not going to inherit any of our father’s wealth, because you are another woman’s son.”'
EXEC add_BibleVerse @BibleId, 107011003, N'So Jephthah left his half-brothers and lived in the land of Tob. Lawless men joined Jephthah’s gang and traveled with him.'
EXEC add_BibleVerse @BibleId, 107011004, N'It was some time after this when the Ammonites fought with Israel.'
EXEC add_BibleVerse @BibleId, 107011005, N'When the Ammonites attacked, the leaders of Gilead asked Jephthah to come back from the land of Tob.'
EXEC add_BibleVerse @BibleId, 107011006, N'They said, “Come, be our commander, so we can fight with the Ammonites.”'
EXEC add_BibleVerse @BibleId, 107011007, N'Jephthah said to the leaders of Gilead, “But you hated me and made me leave my father’s house. Why do you come to me now, when you are in trouble?”'
EXEC add_BibleVerse @BibleId, 107011008, N'The leaders of Gilead said to Jephthah, “That may be true, but now we pledge to you our loyalty. Come with us and fight with the Ammonites. Then you will become the leader of all who live in Gilead.”'
EXEC add_BibleVerse @BibleId, 107011009, N'Jephthah said to the leaders of Gilead, “All right! If you take me back to fight with the Ammonites and the Lord gives them to me, I will be your leader.”'
EXEC add_BibleVerse @BibleId, 107011010, N'The leaders of Gilead said to Jephthah, “The Lord will judge any grievance you have against us, if we do not do as you say.”'
EXEC add_BibleVerse @BibleId, 107011011, N'So Jephthah went with the leaders of Gilead. The people made him their leader and commander. Jephthah repeated the terms of the agreement before the Lord in Mizpah.'
EXEC add_BibleVerse @BibleId, 107011012, N'Jephthah sent messengers to the Ammonite king, saying, “Why have you come against me to attack my land?”'
EXEC add_BibleVerse @BibleId, 107011013, N'The Ammonite king said to Jephthah’s messengers, “Because Israel stole my land when they came up from Egypt – from the Arnon River in the south to the Jabbok River in the north, and as far west as the Jordan. Now return it peaceably!”'
EXEC add_BibleVerse @BibleId, 107011014, N'Jephthah sent messengers back to the Ammonite king'
EXEC add_BibleVerse @BibleId, 107011015, N'and said to him, “This is what Jephthah says, ‘Israel did not steal the land of Moab and the land of the Ammonites.'
EXEC add_BibleVerse @BibleId, 107011016, N'When they left Egypt, Israel traveled through the desert as far as the Red Sea and then came to Kadesh.'
EXEC add_BibleVerse @BibleId, 107011017, N'Israel sent messengers to the king of Edom, saying, “Please allow us to pass through your land.” But the king of Edom rejected the request. Israel sent the same request to the king of Moab, but he was unwilling to cooperate. So Israel stayed at Kadesh.'
EXEC add_BibleVerse @BibleId, 107011018, N'Then Israel went through the desert and bypassed the land of Edom and the land of Moab. They traveled east of the land of Moab and camped on the other side of the Arnon River; they did not go through Moabite territory (the Arnon was Moab’s border).'
EXEC add_BibleVerse @BibleId, 107011019, N'Israel sent messengers to King Sihon, the Amorite king who ruled in Heshbon, and said to him, “Please allow us to pass through your land to our land.”'
EXEC add_BibleVerse @BibleId, 107011020, N'But Sihon did not trust Israel to pass through his territory. He assembled his whole army, camped in Jahaz, and fought with Israel.'
EXEC add_BibleVerse @BibleId, 107011021, N'The Lord God of Israel handed Sihon and his whole army over to Israel and they defeated them. Israel took all the land of the Amorites who lived in that land.'
EXEC add_BibleVerse @BibleId, 107011022, N'They took all the Amorite territory from the Arnon River on the south to the Jabbok River on the north, from the desert in the east to the Jordan in the west.'
EXEC add_BibleVerse @BibleId, 107011023, N'Since the Lord God of Israel has driven out the Amorites before his people Israel, do you think you can just take it from them?'
EXEC add_BibleVerse @BibleId, 107011024, N'You have the right to take what Chemosh your god gives you, but we will take the land of all whom the Lord our God has driven out before us.'
EXEC add_BibleVerse @BibleId, 107011025, N'Are you really better than Balak son of Zippor, king of Moab? Did he dare to quarrel with Israel? Did he dare to fight with them?'
EXEC add_BibleVerse @BibleId, 107011026, N'Israel has been living in Heshbon and its nearby towns, in Aroer and its nearby towns, and in all the cities along the Arnon for three hundred years! Why did you not reclaim them during that time?'
EXEC add_BibleVerse @BibleId, 107011027, N'I have not done you wrong, but you are doing wrong by attacking me. May the Lord, the Judge, judge this day between the Israelites and the Ammonites!’”'
EXEC add_BibleVerse @BibleId, 107011028, N'But the Ammonite king disregarded the message sent by Jephthah.'
EXEC add_BibleVerse @BibleId, 107011029, N'The Lord’s spirit empowered Jephthah. He passed through Gilead and Manasseh and went to Mizpah in Gilead. From there he approached the Ammonites.'
EXEC add_BibleVerse @BibleId, 107011030, N'Jephthah made a vow to the Lord, saying, “If you really do hand the Ammonites over to me,'
EXEC add_BibleVerse @BibleId, 107011031, N'then whoever is the first to come through the doors of my house to meet me when I return safely from fighting the Ammonites – he will belong to the Lord and I will offer him up as a burnt sacrifice.”'
EXEC add_BibleVerse @BibleId, 107011032, N'Jephthah approached the Ammonites to fight with them, and the Lord handed them over to him.'
EXEC add_BibleVerse @BibleId, 107011033, N'He defeated them from Aroer all the way to Minnith – twenty cities in all, even as far as Abel Keramim! He wiped them out! The Israelites humiliated the Ammonites.'
EXEC add_BibleVerse @BibleId, 107011034, N'When Jephthah came home to Mizpah, there was his daughter hurrying out to meet him, dancing to the rhythm of tambourines. She was his only child; except for her he had no son or daughter.'
EXEC add_BibleVerse @BibleId, 107011035, N'When he saw her, he ripped his clothes and said, “Oh no! My daughter! You have completely ruined me! You have brought me disaster! I made an oath to the Lord, and I cannot break it.”'
EXEC add_BibleVerse @BibleId, 107011036, N'She said to him, “My father, since you made an oath to the Lord, do to me as you promised. After all, the Lord vindicated you before your enemies, the Ammonites.”'
EXEC add_BibleVerse @BibleId, 107011037, N'She then said to her father, “Please grant me this one wish. For two months allow me to walk through the hills with my friends and mourn my virginity.”'
EXEC add_BibleVerse @BibleId, 107011038, N'He said, “You may go.” He permitted her to leave for two months. She went with her friends and mourned her virginity as she walked through the hills.'
EXEC add_BibleVerse @BibleId, 107011039, N'After two months she returned to her father, and he did to her as he had vowed. She died a virgin. Her tragic death gave rise to a custom in Israel.'
EXEC add_BibleVerse @BibleId, 107011040, N'Every year Israelite women commemorate the daughter of Jephthah the Gileadite for four days.'
EXEC add_BibleVerse @BibleId, 107012001, N'The Ephraimites assembled and crossed over to Zaphon. They said to Jephthah, “Why did you go and fight with the Ammonites without asking us to go with you? We will burn your house down right over you!”'
EXEC add_BibleVerse @BibleId, 107012002, N'Jephthah said to them, “My people and I were entangled in controversy with the Ammonites. I asked for your help, but you did not deliver me from their power.'
EXEC add_BibleVerse @BibleId, 107012003, N'When I saw that you were not going to help, I risked my life and advanced against the Ammonites, and the Lord handed them over to me. Why have you come up to fight with me today?”'
EXEC add_BibleVerse @BibleId, 107012004, N'Jephthah assembled all the men of Gilead and they fought with Ephraim. The men of Gilead defeated Ephraim, because the Ephraimites insulted them, saying, “You Gileadites are refugees in Ephraim, living within Ephraim’s and Manasseh’s territory.”'
EXEC add_BibleVerse @BibleId, 107012005, N'The Gileadites captured the fords of the Jordan River opposite Ephraim. Whenever an Ephraimite fugitive said, “Let me cross over,” the men of Gilead asked him, “Are you an Ephraimite?” If he said, “No,”'
EXEC add_BibleVerse @BibleId, 107012006, N'then they said to him, “Say ‘Shibboleth!’” If he said, “Sibboleth” (and could not pronounce the word correctly), they grabbed him and executed him right there at the fords of the Jordan. On that day forty-two thousand Ephraimites fell dead.'
EXEC add_BibleVerse @BibleId, 107012007, N'Jephthah led Israel for six years; then he died and was buried in his city in Gilead.'
EXEC add_BibleVerse @BibleId, 107012008, N'After him Ibzan of Bethlehem led Israel.'
EXEC add_BibleVerse @BibleId, 107012009, N'He had thirty sons. He arranged for thirty of his daughters to be married outside his extended family, and he arranged for thirty young women to be brought from outside as wives for his sons. Ibzan led Israel for seven years;'
EXEC add_BibleVerse @BibleId, 107012010, N'then he died and was buried in Bethlehem.'
EXEC add_BibleVerse @BibleId, 107012011, N'After him Elon the Zebulunite led Israel for ten years.'
EXEC add_BibleVerse @BibleId, 107012012, N'Then Elon the Zebulunite died and was buried in Aijalon in the land of Zebulun.'
EXEC add_BibleVerse @BibleId, 107012013, N'After him Abdon son of Hillel the Pirathonite led Israel.'
EXEC add_BibleVerse @BibleId, 107012014, N'He had forty sons and thirty grandsons who rode on seventy donkeys. He led Israel for eight years.'
EXEC add_BibleVerse @BibleId, 107012015, N'Then Abdon son of Hillel the Pirathonite died and was buried in Pirathon in the land of Ephraim, in the hill country of the Amalekites.'
EXEC add_BibleVerse @BibleId, 107013001, N'The Israelites again did evil in the Lord’s sight, so the Lord handed them over to the Philistines for forty years.'
EXEC add_BibleVerse @BibleId, 107013002, N'There was a man named Manoah from Zorah, from the Danite tribe. His wife was infertile and childless.'
EXEC add_BibleVerse @BibleId, 107013003, N'The Lord’s angelic messenger appeared to the woman and said to her, “You are infertile and childless, but you will conceive and have a son.'
EXEC add_BibleVerse @BibleId, 107013004, N'Now be careful! Do not drink wine or beer, and do not eat any food that will make you ritually unclean.'
EXEC add_BibleVerse @BibleId, 107013005, N'Look, you will conceive and have a son. You must never cut his hair, for the child will be dedicated to God from birth. He will begin to deliver Israel from the power of the Philistines.”'
EXEC add_BibleVerse @BibleId, 107013006, N'The woman went and said to her husband, “A man sent from God came to me! He looked like God’s angelic messenger – he was very awesome. I did not ask him where he came from, and he did not tell me his name.'
EXEC add_BibleVerse @BibleId, 107013007, N'He said to me, ‘Look, you will conceive and have a son. So now, do not drink wine or beer and do not eat any food that will make you ritually unclean. For the child will be dedicated to God from birth till the day he dies.’”'
EXEC add_BibleVerse @BibleId, 107013008, N'Manoah prayed to the Lord, “Please, Lord, allow the man sent from God to visit us again, so he can teach us how we should raise the child who will be born.”'
EXEC add_BibleVerse @BibleId, 107013009, N'God answered Manoah’s prayer. God’s angelic messenger visited the woman again while she was sitting in the field. But her husband Manoah was not with her.'
EXEC add_BibleVerse @BibleId, 107013010, N'The woman ran at once and told her husband, “Come quickly, the man who visited me the other day has appeared to me!”'
EXEC add_BibleVerse @BibleId, 107013011, N'So Manoah got up and followed his wife. When he met the man, he said to him, “Are you the man who spoke to my wife?” He said, “Yes.”'
EXEC add_BibleVerse @BibleId, 107013012, N'Manoah said, “Now, when your announcement comes true, how should the child be raised and what should he do?”'
EXEC add_BibleVerse @BibleId, 107013013, N'The Lord’s messenger told Manoah, “Your wife should pay attention to everything I told her.'
EXEC add_BibleVerse @BibleId, 107013014, N'She should not drink anything that the grapevine produces. She must not drink wine or beer, and she must not eat any food that will make her ritually unclean. She should obey everything I commanded her to do.”'
EXEC add_BibleVerse @BibleId, 107013015, N'Manoah said to the Lord’s messenger, “Please stay here awhile, so we can prepare a young goat for you to eat.”'
EXEC add_BibleVerse @BibleId, 107013016, N'The Lord’s messenger said to Manoah, “If I stay, I will not eat your food. But if you want to make a burnt sacrifice to the Lord, you should offer it.” (He said this because Manoah did not know that he was the Lord’s messenger.)'
EXEC add_BibleVerse @BibleId, 107013017, N'Manoah said to the Lord’s messenger, “Tell us your name, so we can honor you when your announcement comes true.”'
EXEC add_BibleVerse @BibleId, 107013018, N'The Lord’s messenger said to him, “You should not ask me my name, because you cannot comprehend it.”'
EXEC add_BibleVerse @BibleId, 107013019, N'Manoah took a young goat and a grain offering and offered them on a rock to the Lord. The Lord’s messenger did an amazing thing as Manoah and his wife watched.'
EXEC add_BibleVerse @BibleId, 107013020, N'As the flame went up from the altar toward the sky, the Lord’s messenger went up in it while Manoah and his wife watched. They fell facedown to the ground.'
EXEC add_BibleVerse @BibleId, 107013021, N'The Lord’s messenger did not appear again to Manoah and his wife. After all this happened Manoah realized that the visitor had been the Lord’s messenger.'
EXEC add_BibleVerse @BibleId, 107013022, N'Manoah said to his wife, “We will certainly die, because we have seen a supernatural being!”'
EXEC add_BibleVerse @BibleId, 107013023, N'But his wife said to him, “If the Lord wanted to kill us, he would not have accepted the burnt offering and the grain offering from us. He would not have shown us all these things, or have spoken to us like this just now.”'
EXEC add_BibleVerse @BibleId, 107013024, N'Manoah’s wife gave birth to a son and named him Samson. The child grew and the Lord empowered him.'
EXEC add_BibleVerse @BibleId, 107013025, N'The Lord’s spirit began to control him in Mahaneh Dan between Zorah and Eshtaol.'
EXEC add_BibleVerse @BibleId, 107014001, N'Samson went down to Timnah, where a Philistine girl caught his eye.'
EXEC add_BibleVerse @BibleId, 107014002, N'When he got home, he told his father and mother, “A Philistine girl in Timnah has caught my eye. Now get her for my wife.”'
EXEC add_BibleVerse @BibleId, 107014003, N'But his father and mother said to him, “Certainly you can find a wife among your relatives or among all our people! You should not have to go and get a wife from the uncircumcised Philistines.” But Samson said to his father, “Get her for me, because she is the right one for me.”'
EXEC add_BibleVerse @BibleId, 107014004, N'Now his father and mother did not realize this was the Lord’s doing, because he was looking for an opportunity to stir up trouble with the Philistines (for at that time the Philistines were ruling Israel).'
EXEC add_BibleVerse @BibleId, 107014005, N'Samson went down to Timnah. When he approached the vineyards of Timnah, he saw a roaring young lion attacking him.'
EXEC add_BibleVerse @BibleId, 107014006, N'The Lord’s spirit empowered him and he tore the lion in two with his bare hands as easily as one would tear a young goat. But he did not tell his father or mother what he had done.'
EXEC add_BibleVerse @BibleId, 107014007, N'Samson continued on down to Timnah and spoke to the girl. In his opinion, she was just the right one.'
EXEC add_BibleVerse @BibleId, 107014008, N'Some time later, when he went back to marry her, he turned aside to see the lion’s remains. He saw a swarm of bees in the lion’s carcass, as well as some honey.'
EXEC add_BibleVerse @BibleId, 107014009, N'He scooped it up with his hands and ate it as he walked along. When he returned to his father and mother, he offered them some and they ate it. But he did not tell them he had scooped the honey out of the lion’s carcass.'
EXEC add_BibleVerse @BibleId, 107014010, N'Then Samson’s father accompanied him to Timnah for the marriage. Samson hosted a party there, for this was customary for bridegrooms to do.'
EXEC add_BibleVerse @BibleId, 107014011, N'When the Philistines saw he had no attendants, they gave him thirty groomsmen who kept him company.'
EXEC add_BibleVerse @BibleId, 107014012, N'Samson said to them, “I will give you a riddle. If you really can solve it during the seven days the party lasts, I will give you thirty linen robes and thirty sets of clothes.'
EXEC add_BibleVerse @BibleId, 107014013, N'But if you cannot solve it, you will give me thirty linen robes and thirty sets of clothes.” They said to him, “Let us hear your riddle.”'
EXEC add_BibleVerse @BibleId, 107014014, N'He said to them, “Out of the one who eats came something to eat; out of the strong one came something sweet.” They could not solve the riddle for three days.'
EXEC add_BibleVerse @BibleId, 107014015, N'On the fourth day they said to Samson’s bride, “Trick your husband into giving the solution to the riddle. If you refuse, we will burn up you and your father’s family. Did you invite us here to make us poor?”'
EXEC add_BibleVerse @BibleId, 107014016, N'So Samson’s bride cried on his shoulder and said, “You must hate me; you do not love me! You told the young men a riddle, but you have not told me the solution.” He said to her, “Look, I have not even told my father or mother. Do you really expect me to tell you?”'
EXEC add_BibleVerse @BibleId, 107014017, N'She cried on his shoulder until the party was almost over. Finally, on the seventh day, he told her because she had nagged him so much. Then she told the young men the solution to the riddle.'
EXEC add_BibleVerse @BibleId, 107014018, N'On the seventh day, before the sun set, the men of the city said to him, “What is sweeter than honey? What is stronger than a lion?” He said to them, “If you had not plowed with my heifer, you would not have solved my riddle!”'
EXEC add_BibleVerse @BibleId, 107014019, N'The Lord’s spirit empowered him. He went down to Ashkelon and murdered thirty men. He took their clothes and gave them to the men who had solved the riddle. He was furious as he went back home.'
EXEC add_BibleVerse @BibleId, 107014020, N'Samson’s bride was then given to his best man.'
EXEC add_BibleVerse @BibleId, 107015001, N'Sometime later, during the wheat harvest, Samson took a young goat as a gift and went to visit his bride. He said to her father, “I want to have sex with my bride in her bedroom!” But her father would not let him enter.'
EXEC add_BibleVerse @BibleId, 107015002, N'Her father said, “I really thought you absolutely despised her, so I gave her to your best man. Her younger sister is more attractive than she is. Take her instead!”'
EXEC add_BibleVerse @BibleId, 107015003, N'Samson said to them, “This time I am justified in doing the Philistines harm!”'
EXEC add_BibleVerse @BibleId, 107015004, N'Samson went and captured three hundred jackals and got some torches. He tied the jackals in pairs by their tails and then tied a torch to each pair.'
EXEC add_BibleVerse @BibleId, 107015005, N'He lit the torches and set the jackals loose in the Philistines’ standing grain. He burned up the grain heaps and the standing grain, as well as the vineyards and olive groves.'
EXEC add_BibleVerse @BibleId, 107015006, N'The Philistines asked, “Who did this?” They were told, “Samson, the Timnite’s son-in-law, because the Timnite took Samson’s bride and gave her to his best man.” So the Philistines went up and burned her and her father.'
EXEC add_BibleVerse @BibleId, 107015007, N'Samson said to them, “Because you did this, I will get revenge against you before I quit fighting.”'
EXEC add_BibleVerse @BibleId, 107015008, N'He struck them down and defeated them. Then he went down and lived for a time in the cave in the cliff of Etam.'
EXEC add_BibleVerse @BibleId, 107015009, N'The Philistines went up and invaded Judah. They arrayed themselves for battle in Lehi.'
EXEC add_BibleVerse @BibleId, 107015010, N'The men of Judah said, “Why are you attacking us?” The Philistines said, “We have come up to take Samson prisoner so we can do to him what he has done to us.”'
EXEC add_BibleVerse @BibleId, 107015011, N'Three thousand men of Judah went down to the cave in the cliff of Etam and said to Samson, “Do you not know that the Philistines rule over us? Why have you done this to us?” He said to them, “I have only done to them what they have done to me.”'
EXEC add_BibleVerse @BibleId, 107015012, N'They said to him, “We have come down to take you prisoner so we can hand you over to the Philistines.” Samson said to them, “Promise me you will not kill me.”'
EXEC add_BibleVerse @BibleId, 107015013, N'They said to him, “We promise! We will only take you prisoner and hand you over to them. We promise not to kill you.” They tied him up with two brand new ropes and led him up from the cliff.'
EXEC add_BibleVerse @BibleId, 107015014, N'When he arrived in Lehi, the Philistines shouted as they approached him. But the Lord’s spirit empowered him. The ropes around his arms were like flax dissolving in fire, and they melted away from his hands.'
EXEC add_BibleVerse @BibleId, 107015015, N'He happened to see a solid jawbone of a donkey. He grabbed it and struck down a thousand men.'
EXEC add_BibleVerse @BibleId, 107015016, N'Samson then said, “With the jawbone of a donkey I have left them in heaps; with the jawbone of a donkey I have struck down a thousand men!”'
EXEC add_BibleVerse @BibleId, 107015017, N'When he finished speaking, he threw the jawbone down and named that place Ramath Lehi.'
EXEC add_BibleVerse @BibleId, 107015018, N'He was very thirsty, so he cried out to the Lord and said, “You have given your servant this great victory. But now must I die of thirst and fall into hands of the Philistines?”'
EXEC add_BibleVerse @BibleId, 107015019, N'So God split open the basin at Lehi and water flowed out from it. When he took a drink, his strength was restored and he revived. For this reason he named the spring En Hakkore. It remains in Lehi to this very day.'
EXEC add_BibleVerse @BibleId, 107015020, N'Samson led Israel for twenty years during the days of Philistine prominence.'
EXEC add_BibleVerse @BibleId, 107016001, N'Samson went to Gaza. There he saw a prostitute and went in to have sex with her.'
EXEC add_BibleVerse @BibleId, 107016002, N'The Gazites were told, “Samson has come here!” So they surrounded the town and hid all night at the city gate, waiting for him to leave. They relaxed all night, thinking, “He will not leave until morning comes; then we will kill him!”'
EXEC add_BibleVerse @BibleId, 107016003, N'Samson spent half the night with the prostitute; then he got up in the middle of the night and left. He grabbed the doors of the city gate, as well as the two posts, and pulled them right off, bar and all. He put them on his shoulders and carried them up to the top of a hill east of Hebron.'
EXEC add_BibleVerse @BibleId, 107016004, N'After this Samson fell in love with a woman named Delilah, who lived in the Sorek Valley.'
EXEC add_BibleVerse @BibleId, 107016005, N'The rulers of the Philistines went up to visit her and said to her, “Trick him! Find out what makes him so strong and how we can subdue him and humiliate him. Each one of us will give you eleven hundred silver pieces.”'
EXEC add_BibleVerse @BibleId, 107016006, N'So Delilah said to Samson, “Tell me what makes you so strong and how you can be subdued and humiliated.”'
EXEC add_BibleVerse @BibleId, 107016007, N'Samson said to her, “If they tie me up with seven fresh bowstrings that have not been dried, I will become weak and be just like any other man.”'
EXEC add_BibleVerse @BibleId, 107016008, N'So the rulers of the Philistines brought her seven fresh bowstrings which had not been dried and they tied him up with them.'
EXEC add_BibleVerse @BibleId, 107016009, N'They hid in the bedroom and then she said to him, “The Philistines are here, Samson!” He snapped the bowstrings as easily as a thread of yarn snaps when it is put close to fire. The secret of his strength was not discovered.'
EXEC add_BibleVerse @BibleId, 107016010, N'Delilah said to Samson, “Look, you deceived me and told me lies! Now tell me how you can be subdued.”'
EXEC add_BibleVerse @BibleId, 107016011, N'He said to her, “If they tie me tightly with brand new ropes that have never been used, I will become weak and be just like any other man.”'
EXEC add_BibleVerse @BibleId, 107016012, N'So Delilah took new ropes and tied him with them and said to him, “The Philistines are here, Samson!” (The Philistines were hiding in the bedroom.) But he tore the ropes from his arms as if they were a piece of thread.'
EXEC add_BibleVerse @BibleId, 107016013, N'Delilah said to Samson, “Up to now you have deceived me and told me lies. Tell me how you can be subdued.” He said to her, “If you weave the seven braids of my hair into the fabric on the loom and secure it with the pin, I will become weak and be like any other man.”'
EXEC add_BibleVerse @BibleId, 107016014, N'So she made him go to sleep, wove the seven braids of his hair into the fabric on the loom, fastened it with the pin, and said to him, “The Philistines are here, Samson!” He woke up and tore away the pin of the loom and the fabric.'
EXEC add_BibleVerse @BibleId, 107016015, N'She said to him, “How can you say, ‘I love you,’ when you will not share your secret with me? Three times you have deceived me and have not told me what makes you so strong.”'
EXEC add_BibleVerse @BibleId, 107016016, N'She nagged him every day and pressured him until he was sick to death of it.'
EXEC add_BibleVerse @BibleId, 107016017, N'Finally he told her his secret. He said to her, “My hair has never been cut, for I have been dedicated to God from the time I was conceived. If my head were shaved, my strength would leave me; I would become weak, and be just like all other men.”'
EXEC add_BibleVerse @BibleId, 107016018, N'When Delilah saw that he had told her his secret, she sent for the rulers of the Philistines, saying, “Come up here again, for he has told me his secret.” So the rulers of the Philistines went up to visit her, bringing the silver in their hands.'
EXEC add_BibleVerse @BibleId, 107016019, N'She made him go to sleep on her lap and then called a man in to shave off the seven braids of his hair. She made him vulnerable and his strength left him.'
EXEC add_BibleVerse @BibleId, 107016020, N'She said, “The Philistines are here, Samson!” He woke up and thought, “I will do as I did before and shake myself free.” But he did not realize that the Lord had left him.'
EXEC add_BibleVerse @BibleId, 107016021, N'The Philistines captured him and gouged out his eyes. They brought him down to Gaza and bound him in bronze chains. He became a grinder in the prison.'
EXEC add_BibleVerse @BibleId, 107016022, N'His hair began to grow back after it had been shaved off.'
EXEC add_BibleVerse @BibleId, 107016023, N'The rulers of the Philistines gathered to offer a great sacrifice to Dagon their god and to celebrate. They said, “Our god has handed Samson, our enemy, over to us.”'
EXEC add_BibleVerse @BibleId, 107016024, N'When the people saw him, they praised their god, saying, “Our god has handed our enemy over to us, the one who ruined our land and killed so many of us!”'
EXEC add_BibleVerse @BibleId, 107016025, N'When they really started celebrating, they said, “Call for Samson so he can entertain us!” So they summoned Samson from the prison and he entertained them. They made him stand between two pillars.'
EXEC add_BibleVerse @BibleId, 107016026, N'Samson said to the young man who held his hand, “Position me so I can touch the pillars that support the temple. Then I can lean on them.”'
EXEC add_BibleVerse @BibleId, 107016027, N'Now the temple was filled with men and women, and all the rulers of the Philistines were there. There were three thousand men and women on the roof watching Samson entertain.'
EXEC add_BibleVerse @BibleId, 107016028, N'Samson called to the Lord, “O Master, Lord, remember me! Strengthen me just one more time, O God, so I can get swift revenge against the Philistines for my two eyes!”'
EXEC add_BibleVerse @BibleId, 107016029, N'Samson took hold of the two middle pillars that supported the temple and he leaned against them, with his right hand on one and his left hand on the other.'
EXEC add_BibleVerse @BibleId, 107016030, N'Samson said, “Let me die with the Philistines!” He pushed hard and the temple collapsed on the rulers and all the people in it. He killed many more people in his death than he had killed during his life.'
EXEC add_BibleVerse @BibleId, 107016031, N'His brothers and all his family went down and brought him back. They buried him between Zorah and Eshtaol in the tomb of Manoah his father. He had led Israel for twenty years.'
EXEC add_BibleVerse @BibleId, 107017001, N'There was a man named Micah from the Ephraimite hill country.'
EXEC add_BibleVerse @BibleId, 107017002, N'He said to his mother, “You know the eleven hundred pieces of silver which were stolen from you, about which I heard you pronounce a curse? Look here, I have the silver. I stole it, but now I am giving it back to you.” His mother said, “May the Lord reward you, my son!”'
EXEC add_BibleVerse @BibleId, 107017003, N'When he gave back to his mother the eleven hundred pieces of silver, his mother said, “I solemnly dedicate this silver to the Lord. It will be for my son’s benefit. We will use it to make a carved image and a metal image.”'
EXEC add_BibleVerse @BibleId, 107017004, N'When he gave the silver back to his mother, she took two hundred pieces of silver to a silversmith, who made them into a carved image and a metal image. She then put them in Micah’s house.'
EXEC add_BibleVerse @BibleId, 107017005, N'Now this man Micah owned a shrine. He made an ephod and some personal idols and hired one of his sons to serve as a priest.'
EXEC add_BibleVerse @BibleId, 107017006, N'In those days Israel had no king. Each man did what he considered to be right.'
EXEC add_BibleVerse @BibleId, 107017007, N'There was a young man from Bethlehem in Judah. He was a Levite who had been temporarily residing among the tribe of Judah.'
EXEC add_BibleVerse @BibleId, 107017008, N'This man left the town of Bethlehem in Judah to find another place to live. He came to the Ephraimite hill country and made his way to Micah’s house.'
EXEC add_BibleVerse @BibleId, 107017009, N'Micah said to him, “Where do you come from?” He replied, “I am a Levite from Bethlehem in Judah. I am looking for a new place to live.”'
EXEC add_BibleVerse @BibleId, 107017010, N'Micah said to him, “Stay with me. Become my adviser and priest. I will give you ten pieces of silver per year, plus clothes and food.”'
EXEC add_BibleVerse @BibleId, 107017011, N'So the Levite agreed to stay with the man; the young man was like a son to Micah.'
EXEC add_BibleVerse @BibleId, 107017012, N'Micah paid the Levite; the young man became his priest and lived in Micah’s house.'
EXEC add_BibleVerse @BibleId, 107017013, N'Micah said, “Now I know God will make me rich, because I have this Levite as my priest.”'
EXEC add_BibleVerse @BibleId, 107018001, N'In those days Israel had no king. And in those days the Danite tribe was looking for a place to settle, because at that time they did not yet have a place to call their own among the tribes of Israel.'
EXEC add_BibleVerse @BibleId, 107018002, N'The Danites sent out from their whole tribe five representatives, capable men from Zorah and Eshtaol, to spy out the land and explore it. They said to them, “Go, explore the land.” They came to the Ephraimite hill country and spent the night at Micah’s house.'
EXEC add_BibleVerse @BibleId, 107018003, N'As they approached Micah’s house, they recognized the accent of the young Levite. So they stopped there and said to him, “Who brought you here? What are you doing in this place? What is your business here?”'
EXEC add_BibleVerse @BibleId, 107018004, N'He told them what Micah had done for him, saying, “He hired me and I became his priest.”'
EXEC add_BibleVerse @BibleId, 107018005, N'They said to him, “Seek a divine oracle for us, so we can know if we will be successful on our mission.”'
EXEC add_BibleVerse @BibleId, 107018006, N'The priest said to them, “Go with confidence. The Lord will be with you on your mission.”'
EXEC add_BibleVerse @BibleId, 107018007, N'So the five men journeyed on and arrived in Laish. They noticed that the people there were living securely, like the Sidonians do, undisturbed and unsuspecting. No conqueror was troubling them in any way. They lived far from the Sidonians and had no dealings with anyone.'
EXEC add_BibleVerse @BibleId, 107018008, N'When the Danites returned to their tribe in Zorah and Eshtaol, their kinsmen asked them, “How did it go?”'
EXEC add_BibleVerse @BibleId, 107018009, N'They said, “Come on, let’s attack them, for we saw their land and it is very good. You seem lethargic, but don’t hesitate to invade and conquer the land.'
EXEC add_BibleVerse @BibleId, 107018010, N'When you invade, you will encounter unsuspecting people. The land is wide! God is handing it over to you – a place that lacks nothing on earth!”'
EXEC add_BibleVerse @BibleId, 107018011, N'So six hundred Danites, fully armed, set out from Zorah and Eshtaol.'
EXEC add_BibleVerse @BibleId, 107018012, N'They went up and camped in Kiriath Jearim in Judah. (To this day that place is called Camp of Dan. It is west of Kiriath Jearim.)'
EXEC add_BibleVerse @BibleId, 107018013, N'From there they traveled through the Ephraimite hill country and arrived at Micah’s house.'
EXEC add_BibleVerse @BibleId, 107018014, N'The five men who had gone to spy out the land of Laish said to their kinsmen, “Do you realize that inside these houses are an ephod, some personal idols, a carved image, and a metal image? Decide now what you want to do.”'
EXEC add_BibleVerse @BibleId, 107018015, N'They stopped there, went inside the young Levite’s house (which belonged to Micah), and asked him how he was doing.'
EXEC add_BibleVerse @BibleId, 107018016, N'Meanwhile the six hundred Danites, fully armed, stood at the entrance to the gate.'
EXEC add_BibleVerse @BibleId, 107018017, N'The five men who had gone to spy out the land broke in and stole the carved image, the ephod, the personal idols, and the metal image, while the priest was standing at the entrance to the gate with the six hundred fully armed men.'
EXEC add_BibleVerse @BibleId, 107018018, N'When these men broke into Micah’s house and stole the carved image, the ephod, the personal idols, and the metal image, the priest said to them, “What are you doing?”'
EXEC add_BibleVerse @BibleId, 107018019, N'They said to him, “Shut up! Put your hand over your mouth and come with us! You can be our adviser and priest. Wouldn’t it be better to be a priest for a whole Israelite tribe than for just one man’s family?”'
EXEC add_BibleVerse @BibleId, 107018020, N'The priest was happy. He took the ephod, the personal idols, and the carved image and joined the group.'
EXEC add_BibleVerse @BibleId, 107018021, N'They turned and went on their way, but they walked behind the children, the cattle, and their possessions.'
EXEC add_BibleVerse @BibleId, 107018022, N'After they had gone a good distance from Micah’s house, Micah’s neighbors gathered together and caught up with the Danites.'
EXEC add_BibleVerse @BibleId, 107018023, N'When they called out to the Danites, the Danites turned around and said to Micah, “Why have you gathered together?”'
EXEC add_BibleVerse @BibleId, 107018024, N'He said, “You stole my gods that I made, as well as this priest, and then went away. What do I have left? How can you have the audacity to say to me, ‘What do you want?’”'
EXEC add_BibleVerse @BibleId, 107018025, N'The Danites said to him, “Don’t say another word to us, or some very angry men will attack you, and you and your family will die.”'
EXEC add_BibleVerse @BibleId, 107018026, N'The Danites went on their way; when Micah realized they were too strong to resist, he turned around and went home.'
EXEC add_BibleVerse @BibleId, 107018027, N'Now the Danites took what Micah had made, as well as his priest, and came to Laish, where the people were undisturbed and unsuspecting. They struck them down with the sword and burned the city.'
EXEC add_BibleVerse @BibleId, 107018028, N'No one came to the rescue because the city was far from Sidon and they had no dealings with anyone. The city was in a valley near Beth Rehob. The Danites rebuilt the city and occupied it.'
EXEC add_BibleVerse @BibleId, 107018029, N'They named it Dan after their ancestor, who was one of Israel’s sons. But the city’s name used to be Laish.'
EXEC add_BibleVerse @BibleId, 107018030, N'The Danites worshiped the carved image. Jonathan, descendant of Gershom, son of Moses, and his descendants served as priests for the tribe of Dan until the time of the exile.'
EXEC add_BibleVerse @BibleId, 107018031, N'They worshiped Micah’s carved image the whole time God’s authorized shrine was in Shiloh.'
EXEC add_BibleVerse @BibleId, 107019001, N'In those days Israel had no king. There was a Levite living temporarily in the remote region of the Ephraimite hill country. He acquired a concubine from Bethlehem in Judah.'
EXEC add_BibleVerse @BibleId, 107019002, N'However, she got angry at him and went home to her father’s house in Bethlehem in Judah. When she had been there four months,'
EXEC add_BibleVerse @BibleId, 107019003, N'her husband came after her, hoping he could convince her to return. He brought with him his servant and a pair of donkeys. When she brought him into her father’s house and the girl’s father saw him, he greeted him warmly.'
EXEC add_BibleVerse @BibleId, 107019004, N'His father-in-law, the girl’s father, persuaded him to stay with him for three days, and they ate and drank together, and spent the night there.'
EXEC add_BibleVerse @BibleId, 107019005, N'On the fourth day they woke up early and the Levite got ready to leave. But the girl’s father said to his son-in-law, “Have a bite to eat for some energy, then you can go.”'
EXEC add_BibleVerse @BibleId, 107019006, N'So the two of them sat down and had a meal together. Then the girl’s father said to the man, “Why not stay another night and have a good time!”'
EXEC add_BibleVerse @BibleId, 107019007, N'When the man got ready to leave, his father-in-law convinced him to stay another night.'
EXEC add_BibleVerse @BibleId, 107019008, N'He woke up early in the morning on the fifth day so he could leave, but the girl’s father said, “Get some energy. Wait until later in the day to leave!” So they ate a meal together.'
EXEC add_BibleVerse @BibleId, 107019009, N'When the man got ready to leave with his concubine and his servant, his father-in-law, the girl’s father, said to him, “Look! The day is almost over! Stay another night! Since the day is over, stay another night here and have a good time. You can get up early tomorrow and start your trip home.”'
EXEC add_BibleVerse @BibleId, 107019010, N'But the man did not want to stay another night. He left and traveled as far as Jebus (that is, Jerusalem). He had with him a pair of saddled donkeys and his concubine.'
EXEC add_BibleVerse @BibleId, 107019011, N'When they got near Jebus, it was getting quite late and the servant said to his master, “Come on, let’s stop at this Jebusite city and spend the night in it.”'
EXEC add_BibleVerse @BibleId, 107019012, N'But his master said to him, “We should not stop at a foreign city where non-Israelites live. We will travel on to Gibeah.”'
EXEC add_BibleVerse @BibleId, 107019013, N'He said to his servant, “Come on, we will go into one of the other towns and spend the night in Gibeah or Ramah.”'
EXEC add_BibleVerse @BibleId, 107019014, N'So they traveled on, and the sun went down when they were near Gibeah in the territory of Benjamin.'
EXEC add_BibleVerse @BibleId, 107019015, N'They stopped there and decided to spend the night in Gibeah. They came into the city and sat down in the town square, but no one invited them to spend the night.'
EXEC add_BibleVerse @BibleId, 107019016, N'But then an old man passed by, returning at the end of the day from his work in the field. The man was from the Ephraimite hill country; he was living temporarily in Gibeah. (The residents of the town were Benjaminites.)'
EXEC add_BibleVerse @BibleId, 107019017, N'When he looked up and saw the traveler in the town square, the old man said, “Where are you heading? Where do you come from?”'
EXEC add_BibleVerse @BibleId, 107019018, N'The Levite said to him, “We are traveling from Bethlehem in Judah to the remote region of the Ephraimite hill country. That’s where I’m from. I had business in Bethlehem in Judah, but now I’m heading home. But no one has invited me into their home.'
EXEC add_BibleVerse @BibleId, 107019019, N'We have enough straw and grain for our donkeys, and there is enough food and wine for me, your female servant, and the young man who is with your servants. We lack nothing.”'
EXEC add_BibleVerse @BibleId, 107019020, N'The old man said, “Everything is just fine! I will take care of all your needs. But don’t spend the night in the town square.”'
EXEC add_BibleVerse @BibleId, 107019021, N'So he brought him to his house and fed the donkeys. They washed their feet and had a meal.'
EXEC add_BibleVerse @BibleId, 107019022, N'They were having a good time, when suddenly some men of the city, some good-for-nothings, surrounded the house and kept beating on the door. They said to the old man who owned the house, “Send out the man who came to visit you so we can have sex with him.”'
EXEC add_BibleVerse @BibleId, 107019023, N'The man who owned the house went outside and said to them, “No, my brothers! Don’t do this wicked thing! After all, this man is a guest in my house. Don’t do such a disgraceful thing!'
EXEC add_BibleVerse @BibleId, 107019024, N'Here are my virgin daughter and my guest’s concubine. I will send them out and you can abuse them and do to them whatever you like. But don’t do such a disgraceful thing to this man!”'
EXEC add_BibleVerse @BibleId, 107019025, N'The men refused to listen to him, so the Levite grabbed his concubine and made her go outside. They raped her and abused her all night long until morning. They let her go at dawn.'
EXEC add_BibleVerse @BibleId, 107019026, N'The woman arrived back at daybreak and was sprawled out on the doorstep of the house where her master was staying until it became light.'
EXEC add_BibleVerse @BibleId, 107019027, N'When her master got up in the morning, opened the doors of the house, and went outside to start on his journey, there was the woman, his concubine, sprawled out on the doorstep of the house with her hands on the threshold.'
EXEC add_BibleVerse @BibleId, 107019028, N'He said to her, “Get up, let’s leave!” But there was no response. He put her on the donkey and went home.'
EXEC add_BibleVerse @BibleId, 107019029, N'When he got home, he took a knife, grabbed his concubine, and carved her up into twelve pieces. Then he sent the pieces throughout Israel.'
EXEC add_BibleVerse @BibleId, 107019030, N'Everyone who saw the sight said, “Nothing like this has happened or been witnessed during the entire time since the Israelites left the land of Egypt! Take careful note of it! Discuss it and speak!”'
EXEC add_BibleVerse @BibleId, 107020001, N'All the Israelites from Dan to Beer Sheba and from the land of Gilead left their homes and assembled together before the Lord at Mizpah.'
EXEC add_BibleVerse @BibleId, 107020002, N'The leaders of all the people from all the tribes of Israel took their places in the assembly of God’s people, which numbered four hundred thousand sword-wielding foot soldiers.'
EXEC add_BibleVerse @BibleId, 107020003, N'The Benjaminites heard that the Israelites had gone up to Mizpah. Then the Israelites said, “Explain how this wicked thing happened!”'
EXEC add_BibleVerse @BibleId, 107020004, N'The Levite, the husband of the murdered woman, spoke up, “I and my concubine stopped in Gibeah in the territory of Benjamin to spend the night.'
EXEC add_BibleVerse @BibleId, 107020005, N'The leaders of Gibeah attacked me and at night surrounded the house where I was staying. They wanted to kill me; instead they abused my concubine so badly that she died.'
EXEC add_BibleVerse @BibleId, 107020006, N'I grabbed hold of my concubine and carved her up and sent the pieces throughout the territory occupied by Israel, because they committed such an unthinkable atrocity in Israel.'
EXEC add_BibleVerse @BibleId, 107020007, N'All you Israelites, make a decision here!”'
EXEC add_BibleVerse @BibleId, 107020008, N'All Israel rose up in unison and said, “Not one of us will go home! Not one of us will return to his house!'
EXEC add_BibleVerse @BibleId, 107020009, N'Now this is what we will do to Gibeah: We will attack the city as the lot dictates.'
EXEC add_BibleVerse @BibleId, 107020010, N'We will take ten of every group of a hundred men from all the tribes of Israel (and a hundred of every group of a thousand, and a thousand of every group of ten thousand) to get supplies for the army. When they arrive in Gibeah of Benjamin they will punish them for the atrocity which they committed in Israel.”'
EXEC add_BibleVerse @BibleId, 107020011, N'So all the men of Israel gathered together at the city as allies.'
EXEC add_BibleVerse @BibleId, 107020012, N'The tribes of Israel sent men throughout the tribe of Benjamin, saying, “How could such a wicked thing take place?'
EXEC add_BibleVerse @BibleId, 107020013, N'Now, hand over the good-for-nothings in Gibeah so we can execute them and purge Israel of wickedness.” But the Benjaminites refused to listen to their Israelite brothers.'
EXEC add_BibleVerse @BibleId, 107020014, N'The Benjaminites came from their cities and assembled at Gibeah to make war against the Israelites.'
EXEC add_BibleVerse @BibleId, 107020015, N'That day the Benjaminites mustered from their cities twenty-six thousand sword-wielding soldiers, besides seven hundred well-trained soldiers from Gibeah.'
EXEC add_BibleVerse @BibleId, 107020016, N'Among this army were seven hundred specially-trained left-handed soldiers. Each one could sling a stone and hit even the smallest target.'
EXEC add_BibleVerse @BibleId, 107020017, N'The men of Israel (not counting Benjamin) had mustered four hundred thousand sword-wielding soldiers, every one an experienced warrior.'
EXEC add_BibleVerse @BibleId, 107020018, N'The Israelites went up to Bethel and asked God, “Who should lead the charge against the Benjaminites?” The Lord said, “Judah should lead.”'
EXEC add_BibleVerse @BibleId, 107020019, N'The Israelites got up the next morning and moved against Gibeah.'
EXEC add_BibleVerse @BibleId, 107020020, N'The men of Israel marched out to fight Benjamin; they arranged their battle lines against Gibeah.'
EXEC add_BibleVerse @BibleId, 107020021, N'The Benjaminites attacked from Gibeah and struck down twenty-two thousand Israelites that day.'
EXEC add_BibleVerse @BibleId, 107020022, N'The Israelite army took heart and once more arranged their battle lines, in the same place where they had taken their positions the day before.'
EXEC add_BibleVerse @BibleId, 107020023, N'The Israelites went up and wept before the Lord until evening. They asked the Lord, “Should we again march out to fight the Benjaminites, our brothers?” The Lord said, “Attack them!”'
EXEC add_BibleVerse @BibleId, 107020024, N'So the Israelites marched toward the Benjaminites the next day.'
EXEC add_BibleVerse @BibleId, 107020025, N'The Benjaminites again attacked them from Gibeah and struck down eighteen thousand sword-wielding Israelite soldiers.'
EXEC add_BibleVerse @BibleId, 107020026, N'So all the Israelites, the whole army, went up to Bethel. They wept and sat there before the Lord; they did not eat anything that day until evening. They offered up burnt sacrifices and tokens of peace to the Lord.'
EXEC add_BibleVerse @BibleId, 107020027, N'The Israelites asked the Lord (for the ark of God’s covenant was there in those days;'
EXEC add_BibleVerse @BibleId, 107020028, N'Phinehas son of Eleazar, son of Aaron, was serving the Lord in those days), “Should we once more march out to fight the Benjaminites our brothers, or should we quit?” The Lord said, “Attack, for tomorrow I will hand them over to you.”'
EXEC add_BibleVerse @BibleId, 107020029, N'So Israel hid men in ambush outside Gibeah.'
EXEC add_BibleVerse @BibleId, 107020030, N'The Israelites attacked the Benjaminites the next day; they took their positions against Gibeah just as they had done before.'
EXEC add_BibleVerse @BibleId, 107020031, N'The Benjaminites attacked the army, leaving the city unguarded. They began to strike down their enemy just as they had done before. On the main roads (one leads to Bethel, the other to Gibeah) and in the field, they struck down about thirty Israelites.'
EXEC add_BibleVerse @BibleId, 107020032, N'Then the Benjaminites said, “They are defeated just as before.” But the Israelites said, “Let’s retreat and lure them away from the city into the main roads.”'
EXEC add_BibleVerse @BibleId, 107020033, N'All the men of Israel got up from their places and took their positions at Baal Tamar, while the Israelites hiding in ambush jumped out of their places west of Gibeah.'
EXEC add_BibleVerse @BibleId, 107020034, N'Ten thousand men, well-trained soldiers from all Israel, then made a frontal assault against Gibeah – the battle was fierce. But the Benjaminites did not realize that disaster was at their doorstep.'
EXEC add_BibleVerse @BibleId, 107020035, N'The Lord annihilated Benjamin before Israel; the Israelites struck down that day 25,100 sword-wielding Benjaminites.'
EXEC add_BibleVerse @BibleId, 107020036, N'Then the Benjaminites saw they were defeated. The Israelites retreated before Benjamin, because they had confidence in the men they had hid in ambush outside Gibeah.'
EXEC add_BibleVerse @BibleId, 107020037, N'The men hiding in ambush made a mad dash to Gibeah. They attacked and put the sword to the entire city.'
EXEC add_BibleVerse @BibleId, 107020038, N'The Israelites and the men hiding in ambush had arranged a signal. When the men hiding in ambush sent up a smoke signal from the city,'
EXEC add_BibleVerse @BibleId, 107020039, N'the Israelites counterattacked. Benjamin had begun to strike down the Israelites; they struck down about thirty men. They said, “There’s no doubt about it! They are totally defeated as in the earlier battle.”'
EXEC add_BibleVerse @BibleId, 107020040, N'But when the signal, a pillar of smoke, began to rise up from the city, the Benjaminites turned around and saw the whole city going up in a cloud of smoke that rose high into the sky.'
EXEC add_BibleVerse @BibleId, 107020041, N'When the Israelites turned around, the Benjaminites panicked because they could see that disaster was on their doorstep.'
EXEC add_BibleVerse @BibleId, 107020042, N'They retreated before the Israelites, taking the road to the wilderness. But the battle overtook them as men from the surrounding cities struck them down.'
EXEC add_BibleVerse @BibleId, 107020043, N'They surrounded the Benjaminites, chased them from Nohah, and annihilated them all the way to a spot east of Geba.'
EXEC add_BibleVerse @BibleId, 107020044, N'Eighteen thousand Benjaminites, all of them capable warriors, fell dead.'
EXEC add_BibleVerse @BibleId, 107020045, N'The rest turned and ran toward the wilderness, heading toward the cliff of Rimmon. But the Israelites caught five thousand of them on the main roads. They stayed right on their heels all the way to Gidom and struck down two thousand more.'
EXEC add_BibleVerse @BibleId, 107020046, N'That day twenty-five thousand sword-wielding Benjaminites fell in battle, all of them capable warriors.'
EXEC add_BibleVerse @BibleId, 107020047, N'Six hundred survivors turned and ran away to the wilderness, to the cliff of Rimmon. They stayed there four months.'
EXEC add_BibleVerse @BibleId, 107020048, N'The Israelites returned to the Benjaminite towns and put the sword to them. They wiped out the cities, the animals, and everything they could find. They set fire to every city in their path.'
EXEC add_BibleVerse @BibleId, 107021001, N'The Israelites had taken an oath in Mizpah, saying, “Not one of us will allow his daughter to marry a Benjaminite.”'
EXEC add_BibleVerse @BibleId, 107021002, N'So the people came to Bethel and sat there before God until evening, weeping loudly and uncontrollably.'
EXEC add_BibleVerse @BibleId, 107021003, N'They said, “Why, O Lord God of Israel, has this happened in Israel?” An entire tribe has disappeared from Israel today!”'
EXEC add_BibleVerse @BibleId, 107021004, N'The next morning the people got up early and built an altar there. They offered up burnt sacrifices and token of peace.'
EXEC add_BibleVerse @BibleId, 107021005, N'The Israelites asked, “Who from all the Israelite tribes has not assembled before the Lord?” They had made a solemn oath that whoever did not assemble before the Lord at Mizpah must certainly be executed.'
EXEC add_BibleVerse @BibleId, 107021006, N'The Israelites regretted what had happened to their brother Benjamin. They said, “Today we cut off an entire tribe from Israel!'
EXEC add_BibleVerse @BibleId, 107021007, N'How can we find wives for those who are left? After all, we took an oath in the Lord’s name not to give them our daughters as wives.”'
EXEC add_BibleVerse @BibleId, 107021008, N'So they asked, “Who from all the Israelite tribes did not assemble before the Lord at Mizpah?” Now it just so happened no one from Jabesh Gilead had come to the gathering.'
EXEC add_BibleVerse @BibleId, 107021009, N'When they took roll call, they noticed none of the inhabitants of Jabesh Gilead were there.'
EXEC add_BibleVerse @BibleId, 107021010, N'So the assembly sent 12,000 capable warriors against Jabesh Gilead. They commanded them, “Go and kill with your swords the inhabitants of Jabesh Gilead, including the women and little children.'
EXEC add_BibleVerse @BibleId, 107021011, N'Do this: exterminate every male, as well as every woman who has had sexual relations with a male. But spare the lives of any virgins.” So they did as instructed.'
EXEC add_BibleVerse @BibleId, 107021012, N'They found among the inhabitants of Jabesh Gilead four hundred young girls who were virgins – they had never had sexual relations with a male. They brought them back to the camp at Shiloh in the land of Canaan.'
EXEC add_BibleVerse @BibleId, 107021013, N'The entire assembly sent messengers to the Benjaminites at the cliff of Rimmon and assured them they would not be harmed.'
EXEC add_BibleVerse @BibleId, 107021014, N'The Benjaminites returned at that time, and the Israelites gave to them the women they had spared from Jabesh Gilead. But there were not enough to go around.'
EXEC add_BibleVerse @BibleId, 107021015, N'The people regretted what had happened to Benjamin because the Lord had weakened the Israelite tribes.'
EXEC add_BibleVerse @BibleId, 107021016, N'The leaders of the assembly said, “How can we find wives for those who are left? After all, the Benjaminite women have been wiped out.'
EXEC add_BibleVerse @BibleId, 107021017, N'The remnant of Benjamin must be preserved. An entire Israelite tribe should not be wiped out.'
EXEC add_BibleVerse @BibleId, 107021018, N'But we can’t allow our daughters to marry them, for the Israelites took an oath, saying, ‘Whoever gives a woman to a Benjaminite will be destroyed!’'
EXEC add_BibleVerse @BibleId, 107021019, N'However, there is an annual festival to the Lord in Shiloh, which is north of Bethel (east of the main road that goes up from Bethel to Shechem) and south of Lebonah.”'
EXEC add_BibleVerse @BibleId, 107021020, N'So they commanded the Benjaminites, “Go hide in the vineyards,'
EXEC add_BibleVerse @BibleId, 107021021, N'and keep your eyes open. When you see the daughters of Shiloh coming out to dance in the celebration, jump out from the vineyards. Each one of you, catch yourself a wife from among the daughters of Shiloh and then go home to the land of Benjamin.'
EXEC add_BibleVerse @BibleId, 107021022, N'When their fathers or brothers come and protest to us, we’ll say to them, “Do us a favor and let them be, for we could not get each one a wife through battle. Don’t worry about breaking your oath! You would only be guilty if you had voluntarily given them wives.’”'
EXEC add_BibleVerse @BibleId, 107021023, N'The Benjaminites did as instructed. They abducted two hundred of the dancing girls to be their wives. They went home to their own territory, rebuilt their cities, and settled down.'
EXEC add_BibleVerse @BibleId, 107021024, N'Then the Israelites dispersed from there to their respective tribal and clan territories. Each went from there to his own property.'
EXEC add_BibleVerse @BibleId, 107021025, N'In those days Israel had no king. Each man did what he considered to be right.'
EXEC add_BibleVerse @BibleId, 108001001, N'During the time of the judges there was a famine in the land of Judah. So a man from Bethlehem in Judah went to live as a resident foreigner in the region of Moab, along with his wife and two sons.'
EXEC add_BibleVerse @BibleId, 108001002, N'(Now the man’s name was Elimelech, his wife was Naomi, and his two sons were Mahlon and Kilion. They were of the clan of Ephrath from Bethlehem in Judah.) They entered the region of Moab and settled there.'
EXEC add_BibleVerse @BibleId, 108001003, N'Sometime later Naomi’s husband Elimelech died, so she and her two sons were left alone.'
EXEC add_BibleVerse @BibleId, 108001004, N'So her sons married Moabite women. (One was named Orpah and the other Ruth.) And they continued to live there about ten years.'
EXEC add_BibleVerse @BibleId, 108001005, N'Then Naomi’s two sons, Mahlon and Kilion, also died. So the woman was left all alone – bereaved of her two children as well as her husband!'
EXEC add_BibleVerse @BibleId, 108001006, N'So she decided to return home from the region of Moab, accompanied by her daughters-in-law, because while she was living in Moab she had heard that the Lord had shown concern for his people, reversing the famine by providing abundant crops.'
EXEC add_BibleVerse @BibleId, 108001007, N'Now as she and her two daughters-in-law began to leave the place where she had been living to return to the land of Judah,'
EXEC add_BibleVerse @BibleId, 108001008, N'Naomi said to her two daughters-in-law, “Listen to me! Each of you should return to your mother’s home! May the Lord show you the same kind of devotion that you have shown to your deceased husbands and to me!'
EXEC add_BibleVerse @BibleId, 108001009, N'May the Lord enable each of you to find security in the home of a new husband!” Then she kissed them goodbye and they wept loudly.'
EXEC add_BibleVerse @BibleId, 108001010, N'But they said to her, “No! We will return with you to your people.”'
EXEC add_BibleVerse @BibleId, 108001011, N'But Naomi replied, “Go back home, my daughters! There is no reason for you to return to Judah with me! I am no longer capable of giving birth to sons who might become your husbands!'
EXEC add_BibleVerse @BibleId, 108001012, N'Go back home, my daughters! For I am too old to get married again. Even if I thought that there was hope that I could get married tonight and conceive sons,'
EXEC add_BibleVerse @BibleId, 108001013, N'surely you would not want to wait until they were old enough to marry! Surely you would not remain unmarried all that time! No, my daughters, you must not return with me. For my intense suffering is too much for you to bear. For the Lord is afflicting me!”'
EXEC add_BibleVerse @BibleId, 108001014, N'Again they wept loudly. Then Orpah kissed her mother-in-law goodbye, but Ruth clung tightly to her.'
EXEC add_BibleVerse @BibleId, 108001015, N'So Naomi said, “Look, your sister-in-law is returning to her people and to her god. Follow your sister-in-law back home!”'
EXEC add_BibleVerse @BibleId, 108001016, N'But Ruth replied, “Stop urging me to abandon you! For wherever you go, I will go. Wherever you live, I will live. Your people will become my people, and your God will become my God.'
EXEC add_BibleVerse @BibleId, 108001017, N'Wherever you die, I will die – and there I will be buried. May the Lord punish me severely if I do not keep my promise! Only death will be able to separate me from you!”'
EXEC add_BibleVerse @BibleId, 108001018, N'When Naomi realized that Ruth was determined to go with her, she stopped trying to dissuade her.'
EXEC add_BibleVerse @BibleId, 108001019, N'So the two of them journeyed together until they arrived in Bethlehem. When they entered Bethlehem, the whole village was excited about their arrival. The women of the village said, “Can this be Naomi?”'
EXEC add_BibleVerse @BibleId, 108001020, N'But she replied to them, “Don’t call me ‘Naomi’! Call me ‘Mara’ because the Sovereign One has treated me very harshly.'
EXEC add_BibleVerse @BibleId, 108001021, N'I left here full, but the Lord has caused me to return empty-handed. Why do you call me ‘Naomi,’ seeing that the Lord has opposed me, and the Sovereign One has caused me to suffer?”'
EXEC add_BibleVerse @BibleId, 108001022, N'So Naomi returned, accompanied by her Moabite daughter-in-law Ruth, who came back with her from the region of Moab. (Now they arrived in Bethlehem at the beginning of the barley harvest.)'
EXEC add_BibleVerse @BibleId, 108002001, N'Now Naomi had a relative on her husband’s side of the family named Boaz. He was a wealthy, prominent man from the clan of Elimelech.'
EXEC add_BibleVerse @BibleId, 108002002, N'One day Ruth the Moabite said to Naomi, “Let me go to the fields so I can gather grain behind whoever permits me to do so.” Naomi replied, “You may go, my daughter.”'
EXEC add_BibleVerse @BibleId, 108002003, N'So Ruth went and gathered grain in the fields behind the harvesters. Now she just happened to end up in the portion of the field belonging to Boaz, who was from the clan of Elimelech.'
EXEC add_BibleVerse @BibleId, 108002004, N'Now at that very moment, Boaz arrived from Bethlehem and greeted the harvesters, “May the Lord be with you!” They replied, “May the Lord bless you!”'
EXEC add_BibleVerse @BibleId, 108002005, N'Boaz asked his servant in charge of the harvesters, “To whom does this young woman belong?”'
EXEC add_BibleVerse @BibleId, 108002006, N'The servant in charge of the harvesters replied, “She’s the young Moabite woman who came back with Naomi from the region of Moab.'
EXEC add_BibleVerse @BibleId, 108002007, N'She asked, ‘May I follow the harvesters and gather grain among the bundles?’ Since she arrived she has been working hard from this morning until now – except for sitting in the resting hut a short time.”'
EXEC add_BibleVerse @BibleId, 108002008, N'So Boaz said to Ruth, “Listen carefully, my dear! Do not leave to gather grain in another field. You need not go beyond the limits of this field. You may go along beside my female workers.'
EXEC add_BibleVerse @BibleId, 108002009, N'Take note of the field where the men are harvesting and follow behind with the female workers. I will tell the men to leave you alone. When you are thirsty, you may go to the water jars and drink some of the water the servants draw.”'
EXEC add_BibleVerse @BibleId, 108002010, N'Ruth knelt before him with her forehead to the ground and said to him, “Why are you so kind and so attentive to me, even though I am a foreigner?”'
EXEC add_BibleVerse @BibleId, 108002011, N'Boaz replied to her, “I have been given a full report of all that you have done for your mother-in-law following the death of your husband – how you left your father and your mother, as well as your homeland, and came to live among people you did not know previously.'
EXEC add_BibleVerse @BibleId, 108002012, N'May the Lord reward your efforts! May your acts of kindness be repaid fully by the Lord God of Israel, from whom you have sought protection!”'
EXEC add_BibleVerse @BibleId, 108002013, N'She said, “You really are being kind to me, sir, for you have reassured and encouraged me, your servant, even though I am not one of your servants!”'
EXEC add_BibleVerse @BibleId, 108002014, N'Later during the mealtime Boaz said to her, “Come here and have some food! Dip your bread in the vinegar!” So she sat down beside the harvesters. Then he handed her some roasted grain. She ate until she was full and saved the rest.'
EXEC add_BibleVerse @BibleId, 108002015, N'When she got up to gather grain, Boaz told his male servants, “Let her gather grain even among the bundles! Don’t chase her off!'
EXEC add_BibleVerse @BibleId, 108002016, N'Make sure you pull out ears of grain for her and drop them so she can gather them up. Don’t tell her not to!”'
EXEC add_BibleVerse @BibleId, 108002017, N'So she gathered grain in the field until evening. When she threshed what she had gathered, it came to about thirty pounds of barley!'
EXEC add_BibleVerse @BibleId, 108002018, N'She carried it back to town, and her mother-in-law saw how much grain she had gathered. Then Ruth gave her the roasted grain she had saved from mealtime.'
EXEC add_BibleVerse @BibleId, 108002019, N'Her mother-in-law asked her, “Where did you gather grain today? Where did you work? May the one who took notice of you be rewarded!” So Ruth told her mother-in-law with whom she had worked. She said, “The name of the man with whom I worked today is Boaz.”'
EXEC add_BibleVerse @BibleId, 108002020, N'Naomi said to her daughter-in-law, “May he be rewarded by the Lord because he has shown loyalty to the living on behalf of the dead!” Then Naomi said to her, “This man is a close relative of ours; he is our guardian.”'
EXEC add_BibleVerse @BibleId, 108002021, N'Ruth the Moabite replied, “He even told me, ‘You may go along beside my servants until they have finished gathering all my harvest!’”'
EXEC add_BibleVerse @BibleId, 108002022, N'Naomi then said to her daughter-in-law Ruth, “It is good, my daughter, that you should go out to work with his female servants. That way you will not be harmed, which could happen in another field.”'
EXEC add_BibleVerse @BibleId, 108002023, N'So Ruth worked beside Boaz’s female servants, gathering grain until the end of the barley harvest as well as the wheat harvest. After that she stayed home with her mother-in-law.'
EXEC add_BibleVerse @BibleId, 108003001, N'At that time, Naomi, her mother-in-law, said to her, “My daughter, I must find a home for you so you will be secure.'
EXEC add_BibleVerse @BibleId, 108003002, N'Now Boaz, with whose female servants you worked, is our close relative. Look, tonight he is winnowing barley at the threshing floor.'
EXEC add_BibleVerse @BibleId, 108003003, N'So bathe yourself, rub on some perfumed oil, and get dressed up. Then go down to the threshing floor. But don’t let the man know you’re there until he finishes his meal.'
EXEC add_BibleVerse @BibleId, 108003004, N'When he gets ready to go to sleep, take careful notice of the place where he lies down. Then go, uncover his legs, and lie down beside him. He will tell you what you should do.”'
EXEC add_BibleVerse @BibleId, 108003005, N'Ruth replied to Naomi, “I will do everything you have told me to do.”'
EXEC add_BibleVerse @BibleId, 108003006, N'So she went down to the threshing floor and did everything her mother-in-law had instructed her to do.'
EXEC add_BibleVerse @BibleId, 108003007, N'When Boaz had finished his meal and was feeling satisfied, he lay down to sleep at the far end of the grain heap. Then Ruth crept up quietly, uncovered his legs, and lay down beside him.'
EXEC add_BibleVerse @BibleId, 108003008, N'In the middle of the night he was startled and turned over. Now he saw a woman lying beside him!'
EXEC add_BibleVerse @BibleId, 108003009, N'He said, “Who are you?” She replied, “I am Ruth, your servant. Marry your servant, for you are a guardian of the family interests.”'
EXEC add_BibleVerse @BibleId, 108003010, N'He said, “May you be rewarded by the Lord, my dear! This act of devotion is greater than what you did before. For you have not sought to marry one of the young men, whether rich or poor.'
EXEC add_BibleVerse @BibleId, 108003011, N'Now, my dear, don’t worry! I intend to do for you everything you propose, for everyone in the village knows that you are a worthy woman.'
EXEC add_BibleVerse @BibleId, 108003012, N'Now yes, it is true that I am a guardian, but there is another guardian who is a closer relative than I am.'
EXEC add_BibleVerse @BibleId, 108003013, N'Remain here tonight. Then in the morning, if he agrees to marry you, fine, let him do so. But if he does not want to do so, I promise, as surely as the Lord lives, to marry you. Sleep here until morning.”'
EXEC add_BibleVerse @BibleId, 108003014, N'So she slept beside him until morning. She woke up while it was still dark. Boaz thought, “No one must know that a woman visited the threshing floor.”'
EXEC add_BibleVerse @BibleId, 108003015, N'Then he said, “Hold out the shawl you are wearing and grip it tightly.” As she held it tightly, he measured out about sixty pounds of barley into the shawl and put it on her shoulders. Then he went into town,'
EXEC add_BibleVerse @BibleId, 108003016, N'and she returned to her mother-in-law. When Ruth returned to her mother-in-law, Naomi asked, “How did things turn out for you, my daughter?” Ruth told her about all the man had done for her.'
EXEC add_BibleVerse @BibleId, 108003017, N'She said, “He gave me these sixty pounds of barley, for he said to me, ‘Do not go to your mother-in-law empty-handed.’”'
EXEC add_BibleVerse @BibleId, 108003018, N'Then Naomi said, “Stay put, my daughter, until you know how the matter turns out. For the man will not rest until he has taken care of the matter today.”'
EXEC add_BibleVerse @BibleId, 108004001, N'Now Boaz went up to the village gate and sat there. Then along came the guardian whom Boaz had mentioned to Ruth! Boaz said, “Come here and sit down, ‘John Doe’!” So he came and sat down.'
EXEC add_BibleVerse @BibleId, 108004002, N'Boaz chose ten of the village leaders and said, “Sit down here!” So they sat down.'
EXEC add_BibleVerse @BibleId, 108004003, N'Then Boaz said to the guardian, “Naomi, who has returned from the region of Moab, is selling the portion of land that belongs to our relative Elimelech.'
EXEC add_BibleVerse @BibleId, 108004004, N'So I am legally informing you: Acquire it before those sitting here and before the leaders of my people! If you want to exercise your right to redeem it, then do so. But if not, then tell me so I will know. For you possess the first option to redeem it; I am next in line after you.” He replied, “I will redeem it.”'
EXEC add_BibleVerse @BibleId, 108004005, N'Then Boaz said, “When you acquire the field from Naomi, you must also acquire Ruth the Moabite, the wife of our deceased relative, in order to preserve his family name by raising up a descendant who will inherit his property.”'
EXEC add_BibleVerse @BibleId, 108004006, N'The guardian said, “Then I am unable to redeem it, for I would ruin my own inheritance in that case. You may exercise my redemption option, for I am unable to redeem it.”'
EXEC add_BibleVerse @BibleId, 108004007, N'(Now this used to be the customary way to finalize a transaction involving redemption in Israel: A man would remove his sandal and give it to the other party. This was a legally binding act in Israel.)'
EXEC add_BibleVerse @BibleId, 108004008, N'So the guardian said to Boaz, “You may acquire it,” and he removed his sandal.'
EXEC add_BibleVerse @BibleId, 108004009, N'Then Boaz said to the leaders and all the people, “You are witnesses today that I have acquired from Naomi all that belonged to Elimelech, Kilion, and Mahlon.'
EXEC add_BibleVerse @BibleId, 108004010, N'I have also acquired Ruth the Moabite, the wife of Mahlon, as my wife to raise up a descendant who will inherit his property so the name of the deceased might not disappear from among his relatives and from his village. You are witnesses today.”'
EXEC add_BibleVerse @BibleId, 108004011, N'All the people who were at the gate and the elders replied, “We are witnesses. May the Lord make the woman who is entering your home like Rachel and Leah, both of whom built up the house of Israel! May you prosper in Ephrathah and become famous in Bethlehem.'
EXEC add_BibleVerse @BibleId, 108004012, N'May your family become like the family of Perez – whom Tamar bore to Judah – through the descendants the Lord gives you by this young woman.”'
EXEC add_BibleVerse @BibleId, 108004013, N'So Boaz married Ruth and had sexual relations with her. The Lord enabled her to conceive and she gave birth to a son.'
EXEC add_BibleVerse @BibleId, 108004014, N'The village women said to Naomi, “May the Lord be praised because he has not left you without a guardian today! May he become famous in Israel!'
EXEC add_BibleVerse @BibleId, 108004015, N'He will encourage you and provide for you when you are old, for your daughter-in-law, who loves you, has given him birth. She is better to you than seven sons!”'
EXEC add_BibleVerse @BibleId, 108004016, N'Naomi took the child and placed him on her lap; she became his caregiver.'
EXEC add_BibleVerse @BibleId, 108004017, N'The neighbor women named him, saying, “A son has been born to Naomi.” They named him Obed. Now he became the father of Jesse – David’s father!'
EXEC add_BibleVerse @BibleId, 108004018, N'These are the descendants of Perez: Perez was the father of Hezron,'
EXEC add_BibleVerse @BibleId, 108004019, N'Hezron was the father of Ram, Ram was the father of Amminadab,'
EXEC add_BibleVerse @BibleId, 108004020, N'Amminadab was the father of Nachshon, Nachshon was the father of Salmah,'
EXEC add_BibleVerse @BibleId, 108004021, N'Salmon was the father of Boaz, Boaz was the father of Obed,'
EXEC add_BibleVerse @BibleId, 108004022, N'Obed was the father of Jesse, and Jesse was the father of David.'
EXEC add_BibleVerse @BibleId, 109001001, N'There was a man from Ramathaim Zophim, from the hill country of Ephraim, whose name was Elkanah. He was the son of Jeroham, the son of Elihu, the son of Tohu, the son of Zuph, an Ephraimite.'
EXEC add_BibleVerse @BibleId, 109001002, N'He had two wives; the name of the first was Hannah and the name of the second was Peninnah. Now Peninnah had children, but Hannah was childless.'
EXEC add_BibleVerse @BibleId, 109001003, N'Year after year this man would go up from his city to worship and to sacrifice to the Lord of hosts at Shiloh. It was there that the two sons of Eli, Hophni and Phineas, served as the Lord’s priests.'
EXEC add_BibleVerse @BibleId, 109001004, N'Whenever the day came for Elkanah to sacrifice, he used to give meat portions to his wife Peninnah and to all her sons and daughters.'
EXEC add_BibleVerse @BibleId, 109001005, N'But he would give a double portion to Hannah, because he especially loved her. Now the Lord had not enabled her to have children.'
EXEC add_BibleVerse @BibleId, 109001006, N'Her rival wife used to upset her and make her worry, for the Lord had not enabled her to have children.'
EXEC add_BibleVerse @BibleId, 109001007, N'Peninnah would behave this way year after year. Whenever Hannah went up to the Lord’s house, Peninnah would upset her so that she would weep and refuse to eat.'
EXEC add_BibleVerse @BibleId, 109001008, N'Finally her husband Elkanah said to her, “Hannah, why do you weep and not eat? Why are you so sad? Am I not better to you than ten sons?”'
EXEC add_BibleVerse @BibleId, 109001009, N'On one occasion in Shiloh, after they had finished eating and drinking, Hannah got up. (Now at the time Eli the priest was sitting in his chair by the doorpost of the Lord’s temple.)'
EXEC add_BibleVerse @BibleId, 109001010, N'She was very upset as she prayed to the Lord, and she was weeping uncontrollably.'
EXEC add_BibleVerse @BibleId, 109001011, N'She made a vow saying, “O Lord of hosts, if you will look with compassion on the suffering of your female servant, remembering me and not forgetting your servant, and give a male child to your servant, then I will dedicate him to the Lord all the days of his life. His hair will never be cut.”'
EXEC add_BibleVerse @BibleId, 109001012, N'As she continued praying to the Lord, Eli was watching her mouth.'
EXEC add_BibleVerse @BibleId, 109001013, N'Now Hannah was speaking from her heart. Although her lips were moving, her voice was inaudible. Eli therefore thought she was drunk.'
EXEC add_BibleVerse @BibleId, 109001014, N'So he said to her, “How often do you intend to get drunk? Put away your wine!”'
EXEC add_BibleVerse @BibleId, 109001015, N'But Hannah replied, “That’s not the way it is, my lord! I am under a great deal of stress. I have drunk neither wine nor beer. Rather, I have poured out my soul to the Lord.'
EXEC add_BibleVerse @BibleId, 109001016, N'Don’t consider your servant a wicked woman, for until now I have spoken from my deep pain and anguish.”'
EXEC add_BibleVerse @BibleId, 109001017, N'Eli replied, “Go in peace, and may the God of Israel grant the request that you have asked of him.”'
EXEC add_BibleVerse @BibleId, 109001018, N'She said, “May I, your servant, find favor in your sight.” So the woman went her way and got something to eat. Her face no longer looked sad.'
EXEC add_BibleVerse @BibleId, 109001019, N'They got up early the next morning and after worshiping the Lord, they returned to their home at Ramah. Elkanah had marital relations with his wife Hannah, and the Lord remembered her.'
EXEC add_BibleVerse @BibleId, 109001020, N'After some time Hannah became pregnant and gave birth to a son. She named him Samuel, thinking, “I asked the Lord for him.'
EXEC add_BibleVerse @BibleId, 109001021, N'This man Elkanah went up with all his family to make the yearly sacrifice to the Lord and to keep his vow,'
EXEC add_BibleVerse @BibleId, 109001022, N'but Hannah did not go up with them. Instead she told her husband, “Once the boy is weaned, I will bring him and appear before the Lord, and he will remain there from then on.”'
EXEC add_BibleVerse @BibleId, 109001023, N'So her husband Elkanah said to her, “Do what you think best. Stay until you have weaned him. May the Lord fulfill his promise.” So the woman stayed and nursed her son until she had weaned him.'
EXEC add_BibleVerse @BibleId, 109001024, N'Once she had weaned him, she took him up with her, along with three bulls, an ephah of flour, and a container of wine. She brought him to the Lord’s house at Shiloh, even though he was young.'
EXEC add_BibleVerse @BibleId, 109001025, N'Once the bull had been slaughtered, they brought the boy to Eli.'
EXEC add_BibleVerse @BibleId, 109001026, N'She said, “Just as surely as you are alive, my lord, I am the woman who previously stood here with you in order to pray to the Lord.'
EXEC add_BibleVerse @BibleId, 109001027, N'I prayed for this boy, and the Lord has given me the request that I asked of him.'
EXEC add_BibleVerse @BibleId, 109001028, N'Now I dedicate him to the Lord. From this time on he is dedicated to the Lord.” Then they worshiped the Lord there.'
EXEC add_BibleVerse @BibleId, 109002001, N'Hannah prayed, “My heart rejoices in the Lord; my horn is exalted high because of the Lord. I loudly denounce my enemies, for I am happy that you delivered me.'
EXEC add_BibleVerse @BibleId, 109002002, N'No one is holy like the Lord! There is no one other than you! There is no rock like our God!'
EXEC add_BibleVerse @BibleId, 109002003, N'Don’t keep speaking so arrogantly, letting proud talk come out of your mouth! For the Lord is a God who knows; he evaluates what people do.'
EXEC add_BibleVerse @BibleId, 109002004, N'The bows of warriors are shattered, but those who stumble find their strength reinforced.'
EXEC add_BibleVerse @BibleId, 109002005, N'Those who are well-fed hire themselves out to earn food, but the hungry no longer lack. Even the barren woman gives birth to seven, but the one with many children withers away.'
EXEC add_BibleVerse @BibleId, 109002006, N'The Lord both kills and gives life; he brings down to the grave and raises up.'
EXEC add_BibleVerse @BibleId, 109002007, N'The Lord impoverishes and makes wealthy; he humbles and he exalts.'
EXEC add_BibleVerse @BibleId, 109002008, N'He lifts the weak from the dust; he raises the poor from the ash heap to seat them with princes and to bestow on them an honored position. The foundations of the earth belong to the Lord, and he has placed the world on them.'
EXEC add_BibleVerse @BibleId, 109002009, N'He watches over his holy ones, but the wicked are made speechless in the darkness, for it is not by one’s own strength that one prevails.'
EXEC add_BibleVerse @BibleId, 109002010, N'The Lord shatters his adversaries; he thunders against them from the heavens. The Lord executes judgment to the ends of the earth. He will strengthen his king and exalt the power of his anointed one.”'
EXEC add_BibleVerse @BibleId, 109002011, N'Then Elkanah went back home to Ramah. But the boy was serving the Lord under the supervision of Eli the priest.'
EXEC add_BibleVerse @BibleId, 109002012, N'The sons of Eli were wicked men. They did not recognize the Lord’s authority.'
EXEC add_BibleVerse @BibleId, 109002013, N'Now the priests would always treat the people in the following way: Whenever anyone was making a sacrifice, while the meat was boiling, the priest’s attendant would come with a three-pronged fork in his hand.'
EXEC add_BibleVerse @BibleId, 109002014, N'He would jab it into the basin, kettle, caldron, or pot, and everything that the fork brought up the priest would take for himself. This is what they used to do to all the Israelites when they came there to Shiloh.'
EXEC add_BibleVerse @BibleId, 109002015, N'Even before they burned the fat, the priest’s attendant would come and say to the person who was making the sacrifice, “Hand over some meat for the priest to roast! He won’t take boiled meat from you, but only raw.”'
EXEC add_BibleVerse @BibleId, 109002016, N'If the individual said to him, “First let the fat be burned away, and then take for yourself whatever you wish,” he would say, “No! Hand it over right now! If you don’t, I will take it forcibly!”'
EXEC add_BibleVerse @BibleId, 109002017, N'The sin of these young men was very great in the Lord’s sight, for they treated the Lord’s offering with contempt.'
EXEC add_BibleVerse @BibleId, 109002018, N'Now Samuel was ministering before the Lord. The boy was dressed in a linen ephod.'
EXEC add_BibleVerse @BibleId, 109002019, N'His mother used to make him a small robe and bring it up to him at regular intervals when she would go up with her husband to make the annual sacrifice.'
EXEC add_BibleVerse @BibleId, 109002020, N'Eli would bless Elkanah and his wife saying, “May the Lord raise up for you descendants from this woman to replace the one that she dedicated to the Lord.” Then they would go to their home.'
EXEC add_BibleVerse @BibleId, 109002021, N'So the Lord graciously attended to Hannah, and she was able to conceive and gave birth to three sons and two daughters. The boy Samuel grew up at the Lord’s sanctuary.'
EXEC add_BibleVerse @BibleId, 109002022, N'Now Eli was very old when he heard about everything that his sons used to do to all the people of Israel and how they used to have sex with the women who were stationed at the entrance to the tent of meeting.'
EXEC add_BibleVerse @BibleId, 109002023, N'He said to them, “Why do you behave in this way? For I hear about these evil things from all these people.'
EXEC add_BibleVerse @BibleId, 109002024, N'This ought not to be, my sons! For the report that I hear circulating among the Lord’s people is not good.'
EXEC add_BibleVerse @BibleId, 109002025, N'If a man sins against a man, one may appeal to God on his behalf. But if a man sins against the Lord, who then will intercede for him?” But Eli’s sons would not listen to their father, for the Lord had decided to kill them.'
EXEC add_BibleVerse @BibleId, 109002026, N'Now the boy Samuel was growing up and finding favor both with the Lord and with people.'
EXEC add_BibleVerse @BibleId, 109002027, N'A man of God came to Eli and said to him, “This is what the Lord says: ‘Did I not plainly reveal myself to your ancestor’s house when they were in Egypt in the house of Pharaoh?'
EXEC add_BibleVerse @BibleId, 109002028, N'I chose your ancestor from all the tribes of Israel to be my priest, to offer sacrifice on my altar, to burn incense, and to bear the ephod before me. I gave to your ancestor’s house all the fire offerings made by the Israelites.'
EXEC add_BibleVerse @BibleId, 109002029, N'Why are you scorning my sacrifice and my offering that I commanded for my dwelling place? You have honored your sons more than you have me by having made yourselves fat from the best parts of all the offerings of my people Israel.’'
EXEC add_BibleVerse @BibleId, 109002030, N'Therefore the Lord, the God of Israel, says, ‘I really did say that your house and your ancestor’s house would serve me forever.’ But now the Lord says, ‘May it never be! For I will honor those who honor me, but those who despise me will be cursed!'
EXEC add_BibleVerse @BibleId, 109002031, N'In fact, days are coming when I will remove your strength and the strength of your father’s house. There will not be an old man in your house!'
EXEC add_BibleVerse @BibleId, 109002032, N'You will see trouble in my dwelling place! Israel will experience blessings, but there will not be an old man in your house for all time.'
EXEC add_BibleVerse @BibleId, 109002033, N'Any one of you that I do not cut off from my altar, I will cause your eyes to fail and will cause you grief. All of those born to your family will die in the prime of life.'
EXEC add_BibleVerse @BibleId, 109002034, N'This will be a confirming sign for you that will be fulfilled through your two sons, Hophni and Phinehas: in a single day they both will die!'
EXEC add_BibleVerse @BibleId, 109002035, N'Then I will raise up for myself a faithful priest. He will do what is in my heart and soul. I will build for him a secure dynasty and he will serve my chosen one for all time.'
EXEC add_BibleVerse @BibleId, 109002036, N'Everyone who remains in your house will come to bow before him for a little money and for a scrap of bread. Each will say, ‘Assign me to a priestly task so I can eat a scrap of bread.’”'
EXEC add_BibleVerse @BibleId, 109003001, N'Now the boy Samuel continued serving the Lord under Eli’s supervision. Word from the Lord was rare in those days; revelatory visions were infrequent.'
EXEC add_BibleVerse @BibleId, 109003002, N'Eli’s eyes had begun to fail, so that he was unable to see well. At that time he was lying down in his place,'
EXEC add_BibleVerse @BibleId, 109003003, N'and the lamp of God had not yet been extinguished. Samuel was lying down in the temple of the Lord as well; the ark of God was also there.'
EXEC add_BibleVerse @BibleId, 109003004, N'The Lord called to Samuel, and he replied, “Here I am!”'
EXEC add_BibleVerse @BibleId, 109003005, N'Then he ran to Eli and said, “Here I am, for you called me.” But Eli said, “I didn’t call you. Go back and lie down.” So he went back and lay down.'
EXEC add_BibleVerse @BibleId, 109003006, N'The Lord again called, “Samuel!” So Samuel got up and went to Eli and said, “Here I am, for you called me.” But Eli said, “I didn’t call you, my son. Go back and lie down.”'
EXEC add_BibleVerse @BibleId, 109003007, N'Now Samuel did not yet know the Lord; the word of the Lord had not yet been revealed to him.'
EXEC add_BibleVerse @BibleId, 109003008, N'Then the Lord called Samuel a third time. So he got up and went to Eli and said, “Here I am, for you called me!” Eli then realized that it was the Lord who was calling the boy.'
EXEC add_BibleVerse @BibleId, 109003009, N'So Eli said to Samuel, “Go back and lie down. When he calls you, say, “Speak, Lord, for your servant is listening.” So Samuel went back and lay down in his place.'
EXEC add_BibleVerse @BibleId, 109003010, N'Then the Lord came and stood nearby, calling as he had previously done, “Samuel! Samuel!” Samuel replied, “Speak, for your servant is listening!”'
EXEC add_BibleVerse @BibleId, 109003011, N'The Lord said to Samuel, “Look! I am about to do something in Israel; when anyone hears about it, both of his ears will tingle.'
EXEC add_BibleVerse @BibleId, 109003012, N'On that day I will carry out against Eli everything that I spoke about his house – from start to finish!'
EXEC add_BibleVerse @BibleId, 109003013, N'You should tell him that I am about to judge his house forever because of the sin that he knew about. For his sons were cursing God, and he did not rebuke them.'
EXEC add_BibleVerse @BibleId, 109003014, N'Therefore I swore an oath to the house of Eli, ‘The sin of the house of Eli can never be forgiven by sacrifice or by grain offering.’”'
EXEC add_BibleVerse @BibleId, 109003015, N'So Samuel lay down until morning. Then he opened the doors of the Lord’s house. But Samuel was afraid to tell Eli about the vision.'
EXEC add_BibleVerse @BibleId, 109003016, N'However, Eli called Samuel and said, “Samuel, my son!” He replied, “Here I am.”'
EXEC add_BibleVerse @BibleId, 109003017, N'Eli said, “What message did he speak to you? Don’t conceal it from me. God will judge you severely if you conceal from me anything that he said to you!”'
EXEC add_BibleVerse @BibleId, 109003018, N'So Samuel told him everything. He did not hold back anything from him. Eli said, “The Lord will do what he pleases.”'
EXEC add_BibleVerse @BibleId, 109003019, N'Samuel continued to grow, and the Lord was with him. None of his prophecies fell to the ground unfulfilled.'
EXEC add_BibleVerse @BibleId, 109003020, N'All Israel from Dan to Beer Sheba realized that Samuel was confirmed as a prophet of the Lord.'
EXEC add_BibleVerse @BibleId, 109003021, N'Then the Lord again appeared in Shiloh, for it was in Shiloh that the Lord had revealed himself to Samuel through the word of the Lord.'
EXEC add_BibleVerse @BibleId, 109004001, N'Samuel revealed the word of the Lord to all Israel. Then the Israelites went out to fight the Philistines. They camped at Ebenezer, and the Philistines camped at Aphek.'
EXEC add_BibleVerse @BibleId, 109004002, N'The Philistines arranged their forces to fight Israel. As the battle spread out, Israel was defeated by the Philistines, who killed about four thousand men in the battle line in the field.'
EXEC add_BibleVerse @BibleId, 109004003, N'When the army came back to the camp, the elders of Israel said, “Why did the Lord let us be defeated today by the Philistines? Let’s take with us the ark of the covenant of the Lord from Shiloh. When it is with us, it will save us from the hand of our enemies.'
EXEC add_BibleVerse @BibleId, 109004004, N'So the army sent to Shiloh, and they took from there the ark of the covenant of the Lord of hosts who sits between the cherubim. Now the two sons of Eli, Hophni and Phineas, were there with the ark of the covenant of God.'
EXEC add_BibleVerse @BibleId, 109004005, N'When the ark of the covenant of the Lord arrived at the camp, all Israel shouted so loudly that the ground shook.'
EXEC add_BibleVerse @BibleId, 109004006, N'When the Philistines heard the sound of the shout, they said, “What is this loud shout in the camp of the Hebrews?” Then they realized that the ark of the Lord had arrived at the camp.'
EXEC add_BibleVerse @BibleId, 109004007, N'The Philistines were scared because they thought that gods had come to the camp. They said, “Too bad for us! We’ve never seen anything like this!'
EXEC add_BibleVerse @BibleId, 109004008, N'Too bad for us! Who can deliver us from the hand of these mighty gods? These are the gods who struck the Egyptians with all sorts of plagues in the desert!'
EXEC add_BibleVerse @BibleId, 109004009, N'Be strong and act like men, you Philistines, or else you will wind up serving the Hebrews the way they have served you! Act like men and fight!”'
EXEC add_BibleVerse @BibleId, 109004010, N'So the Philistines fought. Israel was defeated; they all ran home. The slaughter was very great; thirty thousand foot soldiers fell in battle.'
EXEC add_BibleVerse @BibleId, 109004011, N'The ark of God was taken, and the two sons of Eli, Hophni and Phineas, were killed.'
EXEC add_BibleVerse @BibleId, 109004012, N'On that day a Benjaminite ran from the battle lines and came to Shiloh. His clothes were torn and dirt was on his head.'
EXEC add_BibleVerse @BibleId, 109004013, N'When he arrived in Shiloh, Eli was sitting in his chair watching by the side of the road, for he was very worried about the ark of God. As the man entered the city to give his report, the whole city cried out.'
EXEC add_BibleVerse @BibleId, 109004014, N'When Eli heard the outcry, he said, “What is this commotion?” The man quickly came and told Eli.'
EXEC add_BibleVerse @BibleId, 109004015, N'Now Eli was ninety-eight years old and his eyes looked straight ahead; he was unable to see.'
EXEC add_BibleVerse @BibleId, 109004016, N'The man said to Eli, “I am the one who came from the battle lines! Just today I fled from the battle lines!” Eli asked, “How did things go, my son?”'
EXEC add_BibleVerse @BibleId, 109004017, N'The messenger replied, “Israel has fled from the Philistines! The army has suffered a great defeat! Your two sons, Hophni and Phineas, are dead! The ark of God has been captured!”'
EXEC add_BibleVerse @BibleId, 109004018, N'When he mentioned the ark of God, Eli fell backward from his chair beside the gate. He broke his neck and died, for he was old and heavy. He had judged Israel for forty years.'
EXEC add_BibleVerse @BibleId, 109004019, N'His daughter-in-law, the wife of Phineas, was pregnant and close to giving birth. When she heard that the ark of God was captured and that her father-in-law and her husband were dead, she doubled over and gave birth. But her labor pains were too much for her.'
EXEC add_BibleVerse @BibleId, 109004020, N'As she was dying, the women who were there with her said, “Don’t be afraid! You have given birth to a son!” But she did not reply or pay any attention.'
EXEC add_BibleVerse @BibleId, 109004021, N'She named the boy Ichabod, saying, “The glory has departed from Israel,” referring to the capture of the ark of God and the deaths of her father-in-law and her husband.'
EXEC add_BibleVerse @BibleId, 109004022, N'She said, “The glory has departed from Israel, because the ark of God has been captured.”'
EXEC add_BibleVerse @BibleId, 109005001, N'Now the Philistines had captured the ark of God and brought it from Ebenezer to Ashdod.'
EXEC add_BibleVerse @BibleId, 109005002, N'The Philistines took the ark of God and brought it into the temple of Dagon, where they positioned it beside Dagon.'
EXEC add_BibleVerse @BibleId, 109005003, N'When the residents of Ashdod got up early the next day, Dagon was lying on the ground before the ark of the Lord. So they took Dagon and set him back in his place.'
EXEC add_BibleVerse @BibleId, 109005004, N'But when they got up early the following day, Dagon was again lying on the ground before the ark of the Lord. The head of Dagon and his two hands were sheared off and were lying at the threshold. Only Dagon’s body was left intact.'
EXEC add_BibleVerse @BibleId, 109005005, N'(For this reason, to this very day, neither Dagon’s priests nor anyone else who enters Dagon’s temple step on Dagon’s threshold in Ashdod.)'
EXEC add_BibleVerse @BibleId, 109005006, N'The Lord attacked the residents of Ashdod severely, bringing devastation on them. He struck the people of both Ashdod and the surrounding area with sores.'
EXEC add_BibleVerse @BibleId, 109005007, N'When the people of Ashdod saw what was happening, they said, “The ark of the God of Israel should not remain with us, for he has attacked both us and our god Dagon!”'
EXEC add_BibleVerse @BibleId, 109005008, N'So they assembled all the leaders of the Philistines and asked, “What should we do with the ark of the God of Israel?” They replied, “The ark of the God of Israel should be moved to Gath.” So they moved the ark of the God of Israel.'
EXEC add_BibleVerse @BibleId, 109005009, N'But after it had been moved the Lord attacked that city as well, causing a great deal of panic. He struck all the people of that city with sores.'
EXEC add_BibleVerse @BibleId, 109005010, N'So they sent the ark of God to Ekron. But when the ark of God arrived at Ekron, the residents of Ekron cried out saying, “They have brought the ark of the God of Israel here to kill our people!”'
EXEC add_BibleVerse @BibleId, 109005011, N'So they assembled all the leaders of the Philistines and said, “Get the ark of the God of Israel out of here! Let it go back to its own place so that it won’t kill us and our people!” The terror of death was throughout the entire city; God was attacking them very severely there.'
EXEC add_BibleVerse @BibleId, 109005012, N'The people who did not die were struck with sores; the city’s cry for help went all the way up to heaven.'
EXEC add_BibleVerse @BibleId, 109006001, N'When the ark of the Lord had been in the land of the Philistines for seven months,'
EXEC add_BibleVerse @BibleId, 109006002, N'the Philistines called the priests and the omen readers, saying, “What should we do with the ark of the Lord? Advise us as to how we should send it back to its place.”'
EXEC add_BibleVerse @BibleId, 109006003, N'They replied, “If you are going to send the ark of the God of Israel back, don’t send it away empty. Be sure to return it with a guilt offering. Then you will be healed, and you will understand why his hand is not removed from you.”'
EXEC add_BibleVerse @BibleId, 109006004, N'They inquired, “What is the guilt offering that we should send to him?” They replied, “The Philistine leaders number five. So send five gold sores and five gold mice, for it is the same plague that has afflicted both you and your leaders.'
EXEC add_BibleVerse @BibleId, 109006005, N'You should make images of the sores and images of the mice that are destroying the land. You should honor the God of Israel. Perhaps he will release his grip on you, your gods, and your land.'
EXEC add_BibleVerse @BibleId, 109006006, N'Why harden your hearts like the Egyptians and Pharaoh did? When God treated them harshly, didn’t the Egyptians send the Israelites on their way?'
EXEC add_BibleVerse @BibleId, 109006007, N'So now go and make a new cart. Get two cows that have calves and that have never had a yoke placed on them. Harness the cows to the cart and take their calves from them back to their stalls.'
EXEC add_BibleVerse @BibleId, 109006008, N'Then take the ark of the Lord and place it on the cart, and put in a chest beside it the gold objects you are sending to him as a guilt offering. You should then send it on its way.'
EXEC add_BibleVerse @BibleId, 109006009, N'But keep an eye on it. If it should go up by the way of its own border to Beth Shemesh, then he has brought this great calamity on us. But if that is not the case, then we will know that it was not his hand that struck us; rather, it just happened to us by accident.”'
EXEC add_BibleVerse @BibleId, 109006010, N'So the men did as instructed. They took two cows that had calves and harnessed them to a cart; they also removed their calves to their stalls.'
EXEC add_BibleVerse @BibleId, 109006011, N'They put the ark of the Lord on the cart, along with the chest, the gold mice, and the images of the sores.'
EXEC add_BibleVerse @BibleId, 109006012, N'Then the cows went directly on the road to Beth Shemesh. They went along, mooing as they went; they turned neither to the right nor to the left. The leaders of the Philistines were walking along behind them all the way to the border of Beth Shemesh.'
EXEC add_BibleVerse @BibleId, 109006013, N'Now the residents of Beth Shemesh were harvesting wheat in the valley. When they looked up and saw the ark, they were pleased at the sight.'
EXEC add_BibleVerse @BibleId, 109006014, N'The cart was coming to the field of Joshua, who was from Beth Shemesh. It paused there near a big stone. Then they cut up the wood of the cart and offered the cows as a burnt offering to the Lord.'
EXEC add_BibleVerse @BibleId, 109006015, N'The Levites took down the ark of the Lord and the chest that was with it, which contained the gold objects. They placed them near the big stone. At that time the people of Beth Shemesh offered burnt offerings and made sacrifices to the Lord.'
EXEC add_BibleVerse @BibleId, 109006016, N'The five leaders of the Philistines watched what was happening and then returned to Ekron on the same day.'
EXEC add_BibleVerse @BibleId, 109006017, N'These are the gold sores that the Philistines brought as a guilt offering to the Lord – one for each of the following cities: Ashdod, Gaza, Ashkelon, Gath, and Ekron.'
EXEC add_BibleVerse @BibleId, 109006018, N'The gold mice corresponded in number to all the Philistine cities of the five leaders, from the fortified cities to hamlet villages, to greater Abel, where they positioned the ark of the Lord until this very day in the field of Joshua who was from Beth Shemesh.'
EXEC add_BibleVerse @BibleId, 109006019, N'But the Lord struck down some of the people of Beth Shemesh because they had looked into the ark of the Lord; he struck down 50,070 of the men. The people grieved because the Lord had struck the people with a hard blow.'
EXEC add_BibleVerse @BibleId, 109006020, N'The residents of Beth Shemesh asked, “Who is able to stand before the Lord, this holy God? To whom will the ark go up from here?”'
EXEC add_BibleVerse @BibleId, 109006021, N'So they sent messengers to the residents of Kiriath Jearim, saying, “The Philistines have returned the ark of the Lord. Come down here and take it back home with you.”'
EXEC add_BibleVerse @BibleId, 109007001, N'Then the people of Kiriath Jearim came and took the ark of the Lord; they brought it to the house of Abinadab located on the hill. They consecrated Eleazar his son to guard the ark of the Lord.'
EXEC add_BibleVerse @BibleId, 109007002, N'It was quite a long time – some twenty years in all – that the ark stayed at Kiriath Jearim. All the people of Israel longed for the Lord.'
EXEC add_BibleVerse @BibleId, 109007003, N'Samuel said to all the people of Israel, “If you are really turning to the Lord with all your hearts, remove from among you the foreign gods and the images of Ashtoreth. Give your hearts to the Lord and serve only him. Then he will deliver you from the hand of the Philistines.”'
EXEC add_BibleVerse @BibleId, 109007004, N'So the Israelites removed the Baals and images of Ashtoreth. They served only the Lord.'
EXEC add_BibleVerse @BibleId, 109007005, N'Then Samuel said, “Gather all Israel to Mizpah, and I will pray to the Lord on your behalf.”'
EXEC add_BibleVerse @BibleId, 109007006, N'After they had assembled at Mizpah, they drew water and poured it out before the Lord. They fasted on that day, and they confessed there, “We have sinned against the Lord.” So Samuel led the people of Israel at Mizpah.'
EXEC add_BibleVerse @BibleId, 109007007, N'When the Philistines heard that the Israelites had gathered at Mizpah, the leaders of the Philistines went up against Israel. When the Israelites heard about this, they were afraid of the Philistines.'
EXEC add_BibleVerse @BibleId, 109007008, N'The Israelites said to Samuel, “Keep crying out to the Lord our God so that he may save us from the hand of the Philistines!”'
EXEC add_BibleVerse @BibleId, 109007009, N'So Samuel took a nursing lamb and offered it as a whole burnt offering to the Lord. Samuel cried out to the Lord on Israel’s behalf, and the Lord answered him.'
EXEC add_BibleVerse @BibleId, 109007010, N'As Samuel was offering burnt offerings, the Philistines approached to do battle with Israel. But on that day the Lord thundered loudly against the Philistines. He caused them to panic, and they were defeated by Israel.'
EXEC add_BibleVerse @BibleId, 109007011, N'Then the men of Israel left Mizpah and chased the Philistines, striking them down all the way to an area below Beth Car.'
EXEC add_BibleVerse @BibleId, 109007012, N'Samuel took a stone and placed it between Mizpah and Shen. He named it Ebenezer, saying, “Up to here the Lord has helped us.”'
EXEC add_BibleVerse @BibleId, 109007013, N'So the Philistines were defeated; they did not invade Israel again. The hand of the Lord was against the Philistines all the days of Samuel.'
EXEC add_BibleVerse @BibleId, 109007014, N'The cities that the Philistines had captured from Israel were returned to Israel, from Ekron to Gath. Israel also delivered their territory from the control of the Philistines. There was also peace between Israel and the Amorites.'
EXEC add_BibleVerse @BibleId, 109007015, N'So Samuel led Israel all the days of his life.'
EXEC add_BibleVerse @BibleId, 109007016, N'Year after year he used to travel the circuit of Bethel, Gilgal, and Mizpah; he used to judge Israel in all of these places.'
EXEC add_BibleVerse @BibleId, 109007017, N'Then he would return to Ramah, because his home was there. He also judged Israel there and built an altar to the Lord there.'
EXEC add_BibleVerse @BibleId, 109008001, N'In his old age Samuel appointed his sons as judges over Israel.'
EXEC add_BibleVerse @BibleId, 109008002, N'The name of his firstborn son was Joel, and the name of his second son was Abijah. They were judges in Beer Sheba.'
EXEC add_BibleVerse @BibleId, 109008003, N'But his sons did not follow his ways. Instead, they made money dishonestly, accepted bribes, and perverted justice.'
EXEC add_BibleVerse @BibleId, 109008004, N'So all the elders of Israel gathered together and approached Samuel at Ramah.'
EXEC add_BibleVerse @BibleId, 109008005, N'They said to him, “Look, you are old, and your sons don’t follow your ways. So now appoint over us a king to lead us, just like all the other nations have.”'
EXEC add_BibleVerse @BibleId, 109008006, N'But this request displeased Samuel, for they said, “Give us a king to lead us.” So Samuel prayed to the Lord.'
EXEC add_BibleVerse @BibleId, 109008007, N'The Lord said to Samuel, “Do everything the people request of you. For it is not you that they have rejected, but it is me that they have rejected as their king.'
EXEC add_BibleVerse @BibleId, 109008008, N'Just as they have done from the day that I brought them up from Egypt until this very day, they have rejected me and have served other gods. This is what they are also doing to you.'
EXEC add_BibleVerse @BibleId, 109008009, N'So now do as they say. But seriously warn them and make them aware of the policies of the king who will rule over them.”'
EXEC add_BibleVerse @BibleId, 109008010, N'So Samuel spoke all the words of the Lord to the people who were asking him for a king.'
EXEC add_BibleVerse @BibleId, 109008011, N'He said, “Here are the policies of the king who will rule over you: He will conscript your sons and put them in his chariot forces and in his cavalry; they will run in front of his chariot.'
EXEC add_BibleVerse @BibleId, 109008012, N'He will appoint for himself leaders of thousands and leaders of fifties, as well as those who plow his ground, reap his harvest, and make his weapons of war and his chariot equipment.'
EXEC add_BibleVerse @BibleId, 109008013, N'He will take your daughters to be ointment makers, cooks, and bakers.'
EXEC add_BibleVerse @BibleId, 109008014, N'He will take your best fields and vineyards and give them to his own servants.'
EXEC add_BibleVerse @BibleId, 109008015, N'He will demand a tenth of your seed and of the produce of your vineyards and give it to his administrators and his servants.'
EXEC add_BibleVerse @BibleId, 109008016, N'He will take your male and female servants, as well as your best cattle and your donkeys, and assign them for his own use.'
EXEC add_BibleVerse @BibleId, 109008017, N'He will demand a tenth of your flocks, and you yourselves will be his servants.'
EXEC add_BibleVerse @BibleId, 109008018, N'In that day you will cry out because of your king whom you have chosen for yourselves, but the Lord won’t answer you in that day.”'
EXEC add_BibleVerse @BibleId, 109008019, N'But the people refused to heed Samuel’s warning. Instead they said, “No! There will be a king over us!'
EXEC add_BibleVerse @BibleId, 109008020, N'We will be like all the other nations. Our king will judge us and lead us and fight our battles.”'
EXEC add_BibleVerse @BibleId, 109008021, N'So Samuel listened to everything the people said and then reported it to the Lord.'
EXEC add_BibleVerse @BibleId, 109008022, N'The Lord said to Samuel, “Do as they say and install a king over them.” Then Samuel said to the men of Israel, “Each of you go back to his own city.”'
EXEC add_BibleVerse @BibleId, 109009001, N'There was a Benjaminite man named Kish son of Abiel, the son of Zeror, the son of Becorath, the son of Aphiah of Benjamin. He was a prominent person.'
EXEC add_BibleVerse @BibleId, 109009002, N'He had a son named Saul, a handsome young man. There was no one among the Israelites more handsome than he was; he stood head and shoulders above all the people.'
EXEC add_BibleVerse @BibleId, 109009003, N'The donkeys of Saul’s father Kish wandered off, so Kish said to his son Saul, “Take one of the servants with you and go look for the donkeys.”'
EXEC add_BibleVerse @BibleId, 109009004, N'So Saul crossed through the hill country of Ephraim, passing through the land of Shalisha, but they did not find them. So they crossed through the land of Shaalim, but they were not there. Then he crossed through the land of Benjamin, and still they did not find them.'
EXEC add_BibleVerse @BibleId, 109009005, N'When they came to the land of Zuph, Saul said to his servant who was with him, “Come on, let’s head back before my father quits worrying about the donkeys and becomes anxious about us!”'
EXEC add_BibleVerse @BibleId, 109009006, N'But the servant said to him, “Look, there is a man of God in this town. He is highly respected. Everything that he says really happens. Now let’s go there. Perhaps he will tell us where we should go from here.”'
EXEC add_BibleVerse @BibleId, 109009007, N'So Saul said to his servant, “All right, we can go. But what can we bring the man, since the food in our bags is used up? We have no gift to take to the man of God. What do we have?”'
EXEC add_BibleVerse @BibleId, 109009008, N'The servant went on to answer Saul, “Look, I happen to have in my hand a quarter shekel of silver. I will give it to the man of God and he will tell us where we should go.”'
EXEC add_BibleVerse @BibleId, 109009009, N'(Now it used to be in Israel that whenever someone went to inquire of God he would say, “Come on, let’s go to the seer.” For today’s prophet used to be called a seer.)'
EXEC add_BibleVerse @BibleId, 109009010, N'So Saul said to his servant, “That’s a good idea! Come on. Let’s go.” So they went to the town where the man of God was.'
EXEC add_BibleVerse @BibleId, 109009011, N'As they were going up the ascent to the town, they met some girls coming out to draw water. They said to them, “Is this where the seer is?”'
EXEC add_BibleVerse @BibleId, 109009012, N'They replied, “Yes, straight ahead! But hurry now, for he came to the town today, and the people are making a sacrifice at the high place.'
EXEC add_BibleVerse @BibleId, 109009013, N'When you enter the town, you can find him before he goes up to the high place to eat. The people won’t eat until he arrives, for he must bless the sacrifice. Once that happens, those who have been invited will eat. Now go on up, for this is the time when you can find him!”'
EXEC add_BibleVerse @BibleId, 109009014, N'So they went up to the town. As they were heading for the middle of the town, Samuel was coming in their direction to go up to the high place.'
EXEC add_BibleVerse @BibleId, 109009015, N'Now the day before Saul arrived, the Lord had told Samuel:'
EXEC add_BibleVerse @BibleId, 109009016, N'“At this time tomorrow I will send to you a man from the land of Benjamin. You must consecrate him as a leader over my people Israel. He will save my people from the hand of the Philistines. For I have looked with favor on my people. Their cry has reached me!”'
EXEC add_BibleVerse @BibleId, 109009017, N'When Samuel saw Saul, the Lord said, “Here is the man that I told you about! He will rule over my people.”'
EXEC add_BibleVerse @BibleId, 109009018, N'As Saul approached Samuel in the middle of the gate, he said, “Please tell me where the seer’s house is.”'
EXEC add_BibleVerse @BibleId, 109009019, N'Samuel replied to Saul, “I am the seer! Go up in front of me to the high place! Today you will eat with me and in the morning I will send you away. I will tell you everything that you are thinking.'
EXEC add_BibleVerse @BibleId, 109009020, N'Don’t be concerned about the donkeys that you lost three days ago, for they have been found. Whom does all Israel desire? Is it not you, and all your father’s family?”'
EXEC add_BibleVerse @BibleId, 109009021, N'Saul replied, “Am I not a Benjaminite, from the smallest of Israel’s tribes, and is not my family clan the smallest of all the tribes of Benjamin? Why do you speak to me in this way?”'
EXEC add_BibleVerse @BibleId, 109009022, N'Then Samuel brought Saul and his servant into the room and gave them a place at the head of those who had been invited. There were about thirty people present.'
EXEC add_BibleVerse @BibleId, 109009023, N'Samuel said to the cook, “Give me the portion of meat that I gave to you – the one I asked you to keep with you.”'
EXEC add_BibleVerse @BibleId, 109009024, N'So the cook picked up the leg and brought it and set it in front of Saul. Samuel said, “What was kept is now set before you! Eat, for it has been kept for you for this meeting time, from the time I said, ‘I have invited the people.’” So Saul ate with Samuel that day.'
EXEC add_BibleVerse @BibleId, 109009025, N'When they came down from the high place to the town, Samuel spoke with Saul on the roof.'
EXEC add_BibleVerse @BibleId, 109009026, N'They got up at dawn and Samuel called to Saul on the roof, “Get up, so I can send you on your way.” So Saul got up and the two of them – he and Samuel – went outside.'
EXEC add_BibleVerse @BibleId, 109009027, N'While they were going down to the edge of town, Samuel said to Saul, “Tell the servant to go on ahead of us.” So he did. Samuel then said, “You remain here awhile, so I can inform you of God’s message.”'
EXEC add_BibleVerse @BibleId, 109010001, N'Then Samuel took a small container of olive oil and poured it on Saul’s head. Samuel kissed him and said, “The Lord has chosen you to lead his people Israel! You will rule over the Lord’s people and you will deliver them from the power of the enemies who surround them. This will be your sign that the Lord has chosen you as leader over his inheritance.'
EXEC add_BibleVerse @BibleId, 109010002, N'When you leave me today, you will find two men near Rachel’s tomb at Zelzah on Benjamin’s border. They will say to you, ‘The donkeys you have gone looking for have been found. Your father is no longer concerned about the donkeys but has become anxious about you two! He is asking, “What should I do about my son?”’'
EXEC add_BibleVerse @BibleId, 109010003, N'“As you continue on from there, you will come to the tall tree of Tabor. At that point three men who are going up to God at Bethel will meet you. One of them will be carrying three young goats, one of them will be carrying three round loaves of bread, and one of them will be carrying a container of wine.'
EXEC add_BibleVerse @BibleId, 109010004, N'They will ask you how you’re doing and will give you two loaves of bread. You will accept them.'
EXEC add_BibleVerse @BibleId, 109010005, N'Afterward you will go to Gibeah of God, where there are Philistine officials. When you enter the town, you will meet a company of prophets coming down from the high place. They will have harps, tambourines, flutes, and lyres, and they will be prophesying.'
EXEC add_BibleVerse @BibleId, 109010006, N'Then the spirit of the Lord will rush upon you and you will prophesy with them. You will be changed into a different person.'
EXEC add_BibleVerse @BibleId, 109010007, N'“When these signs have taken place, do whatever your hand finds to do, for God will be with you.'
EXEC add_BibleVerse @BibleId, 109010008, N'You will go down to Gilgal before me. I am going to join you there to offer burnt offerings and to make peace offerings. You should wait for seven days, until I arrive and tell you what to do.”'
EXEC add_BibleVerse @BibleId, 109010009, N'As Saul turned to leave Samuel, God changed his inmost person. All these signs happened on that very day.'
EXEC add_BibleVerse @BibleId, 109010010, N'When Saul and his servant arrived at Gibeah, a company of prophets was coming out to meet him. Then the spirit of God rushed upon Saul and he prophesied among them.'
EXEC add_BibleVerse @BibleId, 109010011, N'When everyone who had known him previously saw him prophesying with the prophets, the people all asked one another, “What on earth has happened to the son of Kish? Does even Saul belong with the prophets?”'
EXEC add_BibleVerse @BibleId, 109010012, N'A man who was from there replied, “And who is their father?” Therefore this became a proverb: “Is even Saul among the prophets?”'
EXEC add_BibleVerse @BibleId, 109010013, N'When Saul had finished prophesying, he went to the high place.'
EXEC add_BibleVerse @BibleId, 109010014, N'Saul’s uncle asked him and his servant, “Where did you go?” Saul replied, “To look for the donkeys. But when we realized they were lost, we went to Samuel.”'
EXEC add_BibleVerse @BibleId, 109010015, N'Saul’s uncle said, “Tell me what Samuel said to you.”'
EXEC add_BibleVerse @BibleId, 109010016, N'Saul said to his uncle, “He assured us that the donkeys had been found.” But Saul did not tell him what Samuel had said about the matter of kingship.'
EXEC add_BibleVerse @BibleId, 109010017, N'Then Samuel called the people together before the Lord at Mizpah.'
EXEC add_BibleVerse @BibleId, 109010018, N'He said to the Israelites, “This is what the Lord God of Israel says, ‘I brought Israel up from Egypt and I delivered you from the power of the Egyptians and from the power of all the kingdoms that oppressed you.'
EXEC add_BibleVerse @BibleId, 109010019, N'But today you have rejected your God who saves you from all your trouble and distress. You have said, “No! Appoint a king over us.” Now take your positions before the Lord by your tribes and by your clans.’”'
EXEC add_BibleVerse @BibleId, 109010020, N'Then Samuel brought all the tribes of Israel near, and the tribe of Benjamin was chosen by lot.'
EXEC add_BibleVerse @BibleId, 109010021, N'Then he brought the tribe of Benjamin near by its families, and the family of Matri was chosen by lot. At last Saul son of Kish was chosen by lot. But when they looked for him, he was nowhere to be found.'
EXEC add_BibleVerse @BibleId, 109010022, N'So they inquired again of the Lord, “Has the man arrived here yet?” The Lord said, “He has hidden himself among the equipment.”'
EXEC add_BibleVerse @BibleId, 109010023, N'So they ran and brought him from there. When he took his position among the people, he stood head and shoulders above them all.'
EXEC add_BibleVerse @BibleId, 109010024, N'Then Samuel said to all the people, “Do you see the one whom the Lord has chosen? Indeed, there is no one like him among all the people!” All the people shouted out, “Long live the king!”'
EXEC add_BibleVerse @BibleId, 109010025, N'Then Samuel talked to the people about how the kingship would work. He wrote it all down on a scroll and set it before the Lord. Then Samuel sent all the people away to their homes.'
EXEC add_BibleVerse @BibleId, 109010026, N'Even Saul went to his home in Gibeah. With him went some brave men whose hearts God had touched.'
EXEC add_BibleVerse @BibleId, 109010027, N'But some wicked men said, “How can this man save us?” They despised him and did not even bring him a gift. But Saul said nothing about it.'
EXEC add_BibleVerse @BibleId, 109011001, N'Nahash the Ammonite marched against Jabesh Gilead. All the men of Jabesh Gilead said to Nahash, “Make a treaty with us and we will serve you.”'
EXEC add_BibleVerse @BibleId, 109011002, N'But Nahash the Ammonite said to them, “The only way I will make a treaty with you is if you let me gouge out the right eye of every one of you and in so doing humiliate all Israel!”'
EXEC add_BibleVerse @BibleId, 109011003, N'The elders of Jabesh said to him, “Leave us alone for seven days so that we can send messengers throughout the territory of Israel. If there is no one who can deliver us, we will come out voluntarily to you.”'
EXEC add_BibleVerse @BibleId, 109011004, N'When the messengers went to Gibeah (where Saul lived) and informed the people of these matters, all the people wept loudly.'
EXEC add_BibleVerse @BibleId, 109011005, N'Now Saul was walking behind the oxen as he came from the field. Saul asked, “What has happened to the people? Why are they weeping?” So they told him about the men of Jabesh.'
EXEC add_BibleVerse @BibleId, 109011006, N'The Spirit of God rushed upon Saul when he heard these words, and he became very angry.'
EXEC add_BibleVerse @BibleId, 109011007, N'He took a pair of oxen and cut them up. Then he sent the pieces throughout the territory of Israel by the hand of messengers, who said, “Whoever does not go out after Saul and after Samuel should expect this to be done to his oxen!” Then the terror of the Lord fell on the people, and they went out as one army.'
EXEC add_BibleVerse @BibleId, 109011008, N'When Saul counted them at Bezek, the Israelites were 300,000 strong and the men of Judah numbered 30,000.'
EXEC add_BibleVerse @BibleId, 109011009, N'They said to the messengers who had come, “Here’s what you should say to the men of Jabesh Gilead: ‘Tomorrow deliverance will come to you when the sun is fully up.’” When the messengers went and told the men of Jabesh Gilead, they were happy.'
EXEC add_BibleVerse @BibleId, 109011010, N'The men of Jabesh said, “Tomorrow we will come out to you and you can do with us whatever you wish.”'
EXEC add_BibleVerse @BibleId, 109011011, N'The next day Saul placed the people in three groups. They went to the Ammonite camp during the morning watch and struck them down until the hottest part of the day. The survivors scattered; no two of them remained together.'
EXEC add_BibleVerse @BibleId, 109011012, N'Then the people said to Samuel, “Who were the ones asking, ‘Will Saul reign over us?’ Hand over those men so we may execute them!”'
EXEC add_BibleVerse @BibleId, 109011013, N'But Saul said, “No one will be killed on this day. For today the Lord has given Israel a victory!”'
EXEC add_BibleVerse @BibleId, 109011014, N'Samuel said to the people, “Come on! Let’s go to Gilgal and renew the kingship there.”'
EXEC add_BibleVerse @BibleId, 109011015, N'So all the people went to Gilgal, where they established Saul as king in the Lord’s presence. They offered up peace offerings there in the Lord’s presence. Saul and all the Israelites were very happy.'
EXEC add_BibleVerse @BibleId, 109012001, N'Samuel said to all Israel, “I have done everything you requested. I have given you a king.'
EXEC add_BibleVerse @BibleId, 109012002, N'Now look! This king walks before you. As for me, I am old and gray, though my sons are here with you. I have walked before you from the time of my youth till the present day.'
EXEC add_BibleVerse @BibleId, 109012003, N'Here I am. Bring a charge against me before the Lord and before his chosen king. Whose ox have I taken? Whose donkey have I taken? Whom have I wronged? Whom have I oppressed? From whose hand have I taken a bribe so that I would overlook something? Tell me, and I will return it to you!”'
EXEC add_BibleVerse @BibleId, 109012004, N'They replied, “You have not wronged us or oppressed us. You have not taken anything from the hand of anyone.”'
EXEC add_BibleVerse @BibleId, 109012005, N'He said to them, “The Lord is witness against you, and his chosen king is witness this day, that you have not found any reason to accuse me.” They said, “He is witness!”'
EXEC add_BibleVerse @BibleId, 109012006, N'Samuel said to the people, “The Lord is the one who chose Moses and Aaron and who brought your ancestors up from the land of Egypt.'
EXEC add_BibleVerse @BibleId, 109012007, N'Now take your positions, so I may confront you before the Lord regarding all the Lord’s just actions toward you and your ancestors.'
EXEC add_BibleVerse @BibleId, 109012008, N'When Jacob entered Egypt, your ancestors cried out to the Lord. The Lord sent Moses and Aaron, and they led your ancestors out of Egypt and settled them in this place.'
EXEC add_BibleVerse @BibleId, 109012009, N'“But they forgot the Lord their God, so he gave them into the hand of Sisera, the general in command of Hazor’s army, and into the hand of the Philistines and into the hand of the king of Moab, and they fought against them.'
EXEC add_BibleVerse @BibleId, 109012010, N'Then they cried out to the Lord and admitted, ‘We have sinned, for we have forsaken the Lord and have served the Baals and the images of Ashtoreth. Now deliver us from the hand of our enemies so that we may serve you.’'
EXEC add_BibleVerse @BibleId, 109012011, N'So the Lord sent Jerub-Baal, Barak, Jephthah, and Samuel, and he delivered you from the hand of the enemies all around you, and you were able to live securely.'
EXEC add_BibleVerse @BibleId, 109012012, N'“When you saw that King Nahash of the Ammonites was advancing against you, you said to me, ‘No! A king will rule over us’ – even though the Lord your God is your king!'
EXEC add_BibleVerse @BibleId, 109012013, N'Now look! Here is the king you have chosen – the one that you asked for! Look, the Lord has given you a king!'
EXEC add_BibleVerse @BibleId, 109012014, N'If you fear the Lord, serving him and obeying him and not rebelling against what he says, and if both you and the king who rules over you follow the Lord your God, all will be well.'
EXEC add_BibleVerse @BibleId, 109012015, N'But if you don’t obey the Lord and rebel against what the Lord says, the hand of the Lord will be against both you and your king.'
EXEC add_BibleVerse @BibleId, 109012016, N'“So now, take your positions and watch this great thing that the Lord is about to do in your sight.'
EXEC add_BibleVerse @BibleId, 109012017, N'Is this not the time of the wheat harvest? I will call on the Lord so that he makes it thunder and rain. Realize and see what a great sin you have committed before the Lord by asking for a king for yourselves.”'
EXEC add_BibleVerse @BibleId, 109012018, N'So Samuel called to the Lord, and the Lord made it thunder and rain that day. All the people were very afraid of both the Lord and Samuel.'
EXEC add_BibleVerse @BibleId, 109012019, N'All the people said to Samuel, “Pray to the Lord your God on behalf of us – your servants – so we won’t die, for we have added to all our sins by asking for a king.”'
EXEC add_BibleVerse @BibleId, 109012020, N'Then Samuel said to the people, “Don’t be afraid. You have indeed sinned. However, don’t turn aside from the Lord. Serve the Lord with all your heart.'
EXEC add_BibleVerse @BibleId, 109012021, N'You should not turn aside after empty things that can’t profit and can’t deliver, since they are empty.'
EXEC add_BibleVerse @BibleId, 109012022, N'The Lord will not abandon his people because he wants to uphold his great reputation. The Lord was pleased to make you his own people.'
EXEC add_BibleVerse @BibleId, 109012023, N'As far as I am concerned, far be it from me to sin against the Lord by ceasing to pray for you! I will instruct you in the way that is good and upright.'
EXEC add_BibleVerse @BibleId, 109012024, N'However, fear the Lord and serve him faithfully with all your heart. Just look at the great things he has done for you!'
EXEC add_BibleVerse @BibleId, 109012025, N'But if you continue to do evil, both you and your king will be swept away.”'
EXEC add_BibleVerse @BibleId, 109013001, N'Saul was thirty years old when he began to reign; he ruled over Israel for forty years.'
EXEC add_BibleVerse @BibleId, 109013002, N'Saul selected for himself three thousand men from Israel. Two thousand of these were with Saul at Micmash and in the hill country of Bethel; the remaining thousand were with Jonathan at Gibeah in the territory of Benjamin. He sent all the rest of the people back home.'
EXEC add_BibleVerse @BibleId, 109013003, N'Jonathan attacked the Philistine outpost that was at Geba and the Philistines heard about it. Then Saul alerted all the land saying, “Let the Hebrews pay attention!”'
EXEC add_BibleVerse @BibleId, 109013004, N'All Israel heard this message, “Saul has attacked the Philistine outpost, and now Israel is repulsive to the Philistines!” So the people were summoned to join Saul at Gilgal.'
EXEC add_BibleVerse @BibleId, 109013005, N'For the battle with Israel the Philistines had amassed 3,000 chariots, 6,000 horsemen, and an army as numerous as the sand on the seashore. They went up and camped at Micmash, east of Beth Aven.'
EXEC add_BibleVerse @BibleId, 109013006, N'The men of Israel realized they had a problem because their army was hard pressed. So the army hid in caves, thickets, cliffs, strongholds, and cisterns.'
EXEC add_BibleVerse @BibleId, 109013007, N'Some of the Hebrews crossed over the Jordan River to the land of Gad and Gilead. But Saul stayed at Gilgal; the entire army that was with him was terrified.'
EXEC add_BibleVerse @BibleId, 109013008, N'He waited for seven days, the time period indicated by Samuel. But Samuel did not come to Gilgal, and the army began to abandon Saul.'
EXEC add_BibleVerse @BibleId, 109013009, N'So Saul said, “Bring me the burnt offering and the peace offerings.” Then he offered a burnt offering.'
EXEC add_BibleVerse @BibleId, 109013010, N'Just when he had finished offering the burnt offering, Samuel appeared on the scene. Saul went out to meet him and to greet him.'
EXEC add_BibleVerse @BibleId, 109013011, N'But Samuel said, “What have you done?” Saul replied, “When I saw that the army had started to abandon me and that you didn’t come at the appointed time and that the Philistines had assembled at Micmash,'
EXEC add_BibleVerse @BibleId, 109013012, N'I thought, ‘Now the Philistines will come down on me at Gilgal and I have not sought the Lord’s favor.’ So I felt obligated to offer the burnt offering.”'
EXEC add_BibleVerse @BibleId, 109013013, N'Then Samuel said to Saul, “You have made a foolish choice! You have not obeyed the commandment that the Lord your God gave you. Had you done that, the Lord would have established your kingdom over Israel forever!'
EXEC add_BibleVerse @BibleId, 109013014, N'But now your kingdom will not continue! The Lord has sought out for himself a man who is loyal to him and the Lord has appointed him to be leader over his people, for you have not obeyed what the Lord commanded you.”'
EXEC add_BibleVerse @BibleId, 109013015, N'Then Samuel set out and went up from Gilgal to Gibeah in the territory of Benjamin. Saul mustered the army that remained with him; there were about six hundred men.'
EXEC add_BibleVerse @BibleId, 109013016, N'Saul, his son Jonathan, and the army that remained with them stayed in Gibeah in the territory of Benjamin, while the Philistines camped in Micmash.'
EXEC add_BibleVerse @BibleId, 109013017, N'Raiding bands went out from the camp of the Philistines in three groups. One band turned toward the road leading to Ophrah by the land of Shual;'
EXEC add_BibleVerse @BibleId, 109013018, N'another band turned toward the road leading to Beth Horon; and yet another band turned toward the road leading to the border that overlooks the valley of Zeboim in the direction of the desert.'
EXEC add_BibleVerse @BibleId, 109013019, N'A blacksmith could not be found in all the land of Israel, for the Philistines had said, “This will prevent the Hebrews from making swords and spears.”'
EXEC add_BibleVerse @BibleId, 109013020, N'So all Israel had to go down to the Philistines in order to get their plowshares, cutting instruments, axes, and sickles sharpened.'
EXEC add_BibleVerse @BibleId, 109013021, N'They charged two-thirds of a shekel to sharpen plowshares and cutting instruments, and a third of a shekel to sharpen picks and axes, and to set ox goads.'
EXEC add_BibleVerse @BibleId, 109013022, N'So on the day of the battle no sword or spear was to be found in the hand of anyone in the army that was with Saul and Jonathan. No one but Saul and his son Jonathan had them.'
EXEC add_BibleVerse @BibleId, 109013023, N'A garrison of the Philistines had gone out to the pass at Micmash.'
EXEC add_BibleVerse @BibleId, 109014001, N'Then one day Jonathan son of Saul said to his armor bearer, “Come on, let’s go over to the Philistine garrison that is opposite us.” But he did not let his father know.'
EXEC add_BibleVerse @BibleId, 109014002, N'Now Saul was sitting under a pomegranate tree in Migron, on the outskirts of Gibeah. The army that was with him numbered about six hundred men.'
EXEC add_BibleVerse @BibleId, 109014003, N'Now Ahijah was carrying an ephod. He was the son of Ahitub, who was the brother of Ichabod and a son of Phineas, son of Eli, the priest of the Lord in Shiloh. The army was unaware that Jonathan had left.'
EXEC add_BibleVerse @BibleId, 109014004, N'Now there was a steep cliff on each side of the pass through which Jonathan intended to go to reach the Philistine garrison. One cliff was named Bozez, the other Seneh.'
EXEC add_BibleVerse @BibleId, 109014005, N'The cliff to the north was closer to Micmash, the one to the south closer to Geba.'
EXEC add_BibleVerse @BibleId, 109014006, N'Jonathan said to his armor bearer, “Come on, let’s go over to the garrison of these uncircumcised men. Perhaps the Lord will intervene for us. Nothing can prevent the Lord from delivering, whether by many or by a few.”'
EXEC add_BibleVerse @BibleId, 109014007, N'His armor bearer said to him, “Do everything that is on your mind. Do as you’re inclined. I’m with you all the way!”'
EXEC add_BibleVerse @BibleId, 109014008, N'Jonathan replied, “All right! We’ll go over to these men and fight them.'
EXEC add_BibleVerse @BibleId, 109014009, N'If they say to us, ‘Stay put until we approach you,’ we will stay right there and not go up to them.'
EXEC add_BibleVerse @BibleId, 109014010, N'But if they say, ‘Come up against us,’ we will go up. For in that case the Lord has given them into our hand – it will be a sign to us.”'
EXEC add_BibleVerse @BibleId, 109014011, N'When they made themselves known to the Philistine garrison, the Philistines said, “Look! The Hebrews are coming out of the holes in which they hid themselves.”'
EXEC add_BibleVerse @BibleId, 109014012, N'Then the men of the garrison said to Jonathan and his armor bearer, “Come on up to us so we can teach you a thing or two!” Then Jonathan said to his armor bearer, “Come up behind me, for the Lord has given them into the hand of Israel!”'
EXEC add_BibleVerse @BibleId, 109014013, N'Jonathan crawled up on his hands and feet, with his armor bearer following behind him. Jonathan struck down the Philistines, while his armor bearer came along behind him and killed them.'
EXEC add_BibleVerse @BibleId, 109014014, N'In this initial skirmish Jonathan and his armor bearer struck down about twenty men in an area that measured half an acre.'
EXEC add_BibleVerse @BibleId, 109014015, N'Then fear overwhelmed those who were in the camp, those who were in the field, all the army in the garrison, and the raiding bands. They trembled and the ground shook. This fear was caused by God.'
EXEC add_BibleVerse @BibleId, 109014016, N'Saul’s watchmen at Gibeah in the territory of Benjamin looked on as the crowd of soldiers seemed to melt away first in one direction and then in another.'
EXEC add_BibleVerse @BibleId, 109014017, N'So Saul said to the army that was with him, “Muster the troops and see who is no longer with us.” When they mustered the troops, Jonathan and his armor bearer were not there.'
EXEC add_BibleVerse @BibleId, 109014018, N'So Saul said to Ahijah, “Bring near the ephod,” for he was at that time wearing the ephod.'
EXEC add_BibleVerse @BibleId, 109014019, N'While Saul spoke to the priest, the panic in the Philistines’ camp was becoming greater and greater. So Saul said to the priest, “Withdraw your hand!”'
EXEC add_BibleVerse @BibleId, 109014020, N'Saul and all the army that was with him assembled and marched into battle, where they found the Philistines in total panic killing one another with their swords.'
EXEC add_BibleVerse @BibleId, 109014021, N'The Hebrews who had earlier gone over to the Philistine side joined the Israelites who were with Saul and Jonathan.'
EXEC add_BibleVerse @BibleId, 109014022, N'When all the Israelites who had hidden themselves in the hill country of Ephraim heard that the Philistines had fled, they too pursued them in battle.'
EXEC add_BibleVerse @BibleId, 109014023, N'So the Lord delivered Israel that day, and the battle shifted over to Beth Aven.'
EXEC add_BibleVerse @BibleId, 109014024, N'Now the men of Israel were hard pressed that day, for Saul had made the army agree to this oath: “Cursed be the man who eats food before evening! I will get my vengeance on my enemies!” So no one in the army ate anything.'
EXEC add_BibleVerse @BibleId, 109014025, N'Now the whole army entered the forest and there was honey on the ground.'
EXEC add_BibleVerse @BibleId, 109014026, N'When the army entered the forest, they saw the honey flowing, but no one ate any of it, for the army was afraid of the oath.'
EXEC add_BibleVerse @BibleId, 109014027, N'But Jonathan had not heard about the oath his father had made the army take. He extended the end of his staff that was in his hand and dipped it in the honeycomb. When he ate it, his eyes gleamed.'
EXEC add_BibleVerse @BibleId, 109014028, N'Then someone from the army informed him, “Your father put the army under a strict oath saying, ‘Cursed be the man who eats food today!’ That is why the army is tired.”'
EXEC add_BibleVerse @BibleId, 109014029, N'Then Jonathan said, “My father has caused trouble for the land. See how my eyes gleamed when I tasted just a little of this honey.'
EXEC add_BibleVerse @BibleId, 109014030, N'Certainly if the army had eaten some of the enemies’ provisions that they came across today, would not the slaughter of the Philistines have been even greater?”'
EXEC add_BibleVerse @BibleId, 109014031, N'On that day the army struck down the Philistines from Micmash to Aijalon, and they became very tired.'
EXEC add_BibleVerse @BibleId, 109014032, N'So the army rushed greedily on the plunder, confiscating sheep, cattle, and calves. They slaughtered them right on the ground, and the army ate them blood and all.'
EXEC add_BibleVerse @BibleId, 109014033, N'Now it was reported to Saul, “Look, the army is sinning against the Lord by eating even the blood.” He said, “All of you have broken the covenant! Roll a large stone over here to me.”'
EXEC add_BibleVerse @BibleId, 109014034, N'Then Saul said, “Scatter out among the army and say to them, ‘Each of you bring to me your ox and sheep and slaughter them in this spot and eat. But don’t sin against the Lord by eating the blood.” So that night each one brought his ox and slaughtered it there.'
EXEC add_BibleVerse @BibleId, 109014035, N'Then Saul built an altar for the Lord; it was the first time he had built an altar for the Lord.'
EXEC add_BibleVerse @BibleId, 109014036, N'Saul said, “Let’s go down after the Philistines at night; we will rout them until the break of day. We won’t leave any of them alive!” They replied, “Do whatever seems best to you.” But the priest said, “Let’s approach God here.”'
EXEC add_BibleVerse @BibleId, 109014037, N'So Saul asked God, “Should I go down after the Philistines? Will you deliver them into the hand of Israel?” But he did not answer him that day.'
EXEC add_BibleVerse @BibleId, 109014038, N'Then Saul said, “All you leaders of the army come here. Find out how this sin occurred today.'
EXEC add_BibleVerse @BibleId, 109014039, N'For as surely as the Lord, the deliverer of Israel, lives, even if it turns out to be my own son Jonathan, he will certainly die!” But no one from the army said anything.'
EXEC add_BibleVerse @BibleId, 109014040, N'Then he said to all Israel, “You will be on one side, and I and my son Jonathan will be on the other side.” The army replied to Saul, “Do whatever you think is best.”'
EXEC add_BibleVerse @BibleId, 109014041, N'Then Saul said, “O Lord God of Israel! If this sin has been committed by me or by my son Jonathan, then, O Lord God of Israel, respond with Urim. But if this sin has been committed by your people Israel, respond with Thummim.” Then Jonathan and Saul were indicated by lot, while the army was exonerated.'
EXEC add_BibleVerse @BibleId, 109014042, N'Then Saul said, “Cast the lot between me and my son Jonathan!” Jonathan was indicated by lot.'
EXEC add_BibleVerse @BibleId, 109014043, N'So Saul said to Jonathan, “Tell me what you have done.” Jonathan told him, “I used the end of the staff that was in my hand to taste a little honey. I must die!”'
EXEC add_BibleVerse @BibleId, 109014044, N'Saul said, “God will punish me severely if Jonathan doesn’t die!”'
EXEC add_BibleVerse @BibleId, 109014045, N'But the army said to Saul, “Should Jonathan, who won this great victory in Israel, die? May it never be! As surely as the Lord lives, not a single hair of his head will fall to the ground! For it is with the help of God that he has acted today.” So the army rescued Jonathan from death.'
EXEC add_BibleVerse @BibleId, 109014046, N'Then Saul stopped chasing the Philistines, and the Philistines went back home.'
EXEC add_BibleVerse @BibleId, 109014047, N'After Saul had secured his royal position over Israel, he fought against all their enemies on all sides – the Moabites, Ammonites, Edomites, the kings of Zobah, and the Philistines. In every direction that he turned he was victorious.'
EXEC add_BibleVerse @BibleId, 109014048, N'He fought bravely, striking down the Amalekites and delivering Israel from the hand of its enemies.'
EXEC add_BibleVerse @BibleId, 109014049, N'The sons of Saul were Jonathan, Ishvi, and Malki-Shua. He had two daughters; the older one was named Merab and the younger Michal.'
EXEC add_BibleVerse @BibleId, 109014050, N'The name of Saul’s wife was Ahinoam, the daughter of Ahimaaz. The name of the general in command of his army was Abner son of Ner, Saul’s uncle.'
EXEC add_BibleVerse @BibleId, 109014051, N'Kish was the father of Saul, and Ner the father of Abner was the son of Abiel.'
EXEC add_BibleVerse @BibleId, 109014052, N'There was fierce war with the Philistines all the days of Saul. So whenever Saul saw anyone who was a warrior or a brave individual, he would conscript him.'
EXEC add_BibleVerse @BibleId, 109015001, N'Then Samuel said to Saul, “I was the one the Lord sent to anoint you as king over his people Israel. Now listen to what the Lord says.'
EXEC add_BibleVerse @BibleId, 109015002, N'Here is what the Lord of hosts says: ‘I carefully observed how the Amalekites opposed Israel along the way when Israel came up from Egypt.'
EXEC add_BibleVerse @BibleId, 109015003, N'So go now and strike down the Amalekites. Destroy everything that they have. Don’t spare them. Put them to death – man, woman, child, infant, ox, sheep, camel, and donkey alike.’”'
EXEC add_BibleVerse @BibleId, 109015004, N'So Saul assembled the army and mustered them at Telaim. There were 200,000 foot soldiers and 10,000 men of Judah.'
EXEC add_BibleVerse @BibleId, 109015005, N'Saul proceeded to the city of Amalek, where he set an ambush in the wadi.'
EXEC add_BibleVerse @BibleId, 109015006, N'Saul said to the Kenites, “Go on and leave! Go down from among the Amalekites! Otherwise I will sweep you away with them! After all, you were kind to all the Israelites when they came up from Egypt.” So the Kenites withdrew from among the Amalekites.'
EXEC add_BibleVerse @BibleId, 109015007, N'Then Saul struck down the Amalekites all the way from Havilah to Shur, which is next to Egypt.'
EXEC add_BibleVerse @BibleId, 109015008, N'He captured King Agag of the Amalekites alive, but he executed all Agag’s people with the sword.'
EXEC add_BibleVerse @BibleId, 109015009, N'However, Saul and the army spared Agag, along with the best of the flock, the cattle, the fatlings, and the lambs, as well as everything else that was of value. They were not willing to slaughter them. But they did slaughter everything that was despised and worthless.'
EXEC add_BibleVerse @BibleId, 109015010, N'Then the word of the Lord came to Samuel:'
EXEC add_BibleVerse @BibleId, 109015011, N'“I regret that I have made Saul king, for he has turned away from me and has not done what I told him to do.” Samuel became angry and he cried out to the Lord all that night.'
EXEC add_BibleVerse @BibleId, 109015012, N'Then Samuel got up early to meet Saul the next morning. But Samuel was informed, “Saul has gone to Carmel where he is setting up a monument for himself. Then Samuel left and went down to Gilgal.”'
EXEC add_BibleVerse @BibleId, 109015013, N'When Samuel came to him, Saul said to him, “May the Lord bless you! I have done what the Lord said.”'
EXEC add_BibleVerse @BibleId, 109015014, N'Samuel replied, “If that is the case, then what is this sound of sheep in my ears and the sound of cattle that I hear?”'
EXEC add_BibleVerse @BibleId, 109015015, N'Saul said, “They were brought from the Amalekites; the army spared the best of the flocks and cattle to sacrifice to the Lord our God. But everything else we slaughtered.”'
EXEC add_BibleVerse @BibleId, 109015016, N'Then Samuel said to Saul, “Wait a minute! Let me tell you what the Lord said to me last night.” Saul said to him, “Tell me.”'
EXEC add_BibleVerse @BibleId, 109015017, N'Samuel said, “Is it not true that when you were insignificant in your own eyes, you became head of the tribes of Israel? The Lord chose you as king over Israel.'
EXEC add_BibleVerse @BibleId, 109015018, N'The Lord sent you on a campaign saying, ‘Go and exterminate those sinful Amalekites! Fight against them until you have destroyed them.’'
EXEC add_BibleVerse @BibleId, 109015019, N'Why haven’t you obeyed the Lord? Instead you have greedily rushed upon the plunder! You have done what is wrong in the Lord’s estimation.”'
EXEC add_BibleVerse @BibleId, 109015020, N'Then Saul said to Samuel, “But I have obeyed the Lord! I went on the campaign the Lord sent me on. I brought back King Agag of the Amalekites after exterminating the Amalekites.'
EXEC add_BibleVerse @BibleId, 109015021, N'But the army took from the plunder some of the sheep and cattle – the best of what was to be slaughtered – to sacrifice to the Lord your God in Gilgal.”'
EXEC add_BibleVerse @BibleId, 109015022, N'Then Samuel said, “Does the Lord take pleasure in burnt offerings and sacrifices as much as he does in obedience? Certainly, obedience is better than sacrifice; paying attention is better than the fat of rams.'
EXEC add_BibleVerse @BibleId, 109015023, N'For rebellion is like the sin of divination, and presumption is like the evil of idolatry. Because you have rejected the word of the Lord, he has rejected you as king.”'
EXEC add_BibleVerse @BibleId, 109015024, N'Then Saul said to Samuel, “I have sinned, for I have disobeyed what the Lord commanded and what you said as well. For I was afraid of the army, and I followed their wishes.'
EXEC add_BibleVerse @BibleId, 109015025, N'Now please forgive my sin! Go back with me so I can worship the Lord.”'
EXEC add_BibleVerse @BibleId, 109015026, N'Samuel said to Saul, “I will not go back with you, for you have rejected the word of the Lord, and the Lord has rejected you from being king over Israel!”'
EXEC add_BibleVerse @BibleId, 109015027, N'When Samuel turned to leave, Saul grabbed the edge of his robe and it tore.'
EXEC add_BibleVerse @BibleId, 109015028, N'Samuel said to him, “The Lord has torn the kingdom of Israel from you this day and has given it to one of your colleagues who is better than you!'
EXEC add_BibleVerse @BibleId, 109015029, N'The Preeminent One of Israel does not go back on his word or change his mind, for he is not a human being who changes his mind.”'
EXEC add_BibleVerse @BibleId, 109015030, N'Saul again replied, “I have sinned. But please honor me before the elders of my people and before Israel. Go back with me so I may worship the Lord your God.”'
EXEC add_BibleVerse @BibleId, 109015031, N'So Samuel followed Saul back, and Saul worshiped the Lord.'
EXEC add_BibleVerse @BibleId, 109015032, N'Then Samuel said, “Bring me King Agag of the Amalekites.” So Agag came to him trembling, thinking to himself, “Surely death is bitter!”'
EXEC add_BibleVerse @BibleId, 109015033, N'Samuel said, “Just as your sword left women childless, so your mother will be the most bereaved among women!” Then Samuel hacked Agag to pieces there in Gilgal before the Lord.'
EXEC add_BibleVerse @BibleId, 109015034, N'Then Samuel went to Ramah, while Saul went up to his home in Gibeah of Saul.'
EXEC add_BibleVerse @BibleId, 109015035, N'Until the day he died Samuel did not see Saul again. Samuel did, however, mourn for Saul, but the Lord regretted that he had made Saul king over Israel.'
EXEC add_BibleVerse @BibleId, 109016001, N'The Lord said to Samuel, “How long do you intend to mourn for Saul? I have rejected him as king over Israel. Fill your horn with olive oil and go! I am sending you to Jesse in Bethlehem, for I have selected a king for myself from among his sons.”'
EXEC add_BibleVerse @BibleId, 109016002, N'Samuel replied, “How can I go? Saul will hear about it and kill me!” But the Lord said, “Take a heifer with you and say, ‘I have come to sacrifice to the Lord.’'
EXEC add_BibleVerse @BibleId, 109016003, N'Then invite Jesse to the sacrifice, and I will show you what you should do. You will anoint for me the one I point out to you.”'
EXEC add_BibleVerse @BibleId, 109016004, N'Samuel did what the Lord told him. When he arrived in Bethlehem, the elders of the city were afraid to meet him. They said, “Do you come in peace?”'
EXEC add_BibleVerse @BibleId, 109016005, N'He replied, “Yes, in peace. I have come to sacrifice to the Lord. Consecrate yourselves and come with me to the sacrifice.” So he consecrated Jesse and his sons and invited them to the sacrifice.'
EXEC add_BibleVerse @BibleId, 109016006, N'When they arrived, Samuel noticed Eliab and said to himself, “Surely, here before the Lord stands his chosen king!”'
EXEC add_BibleVerse @BibleId, 109016007, N'But the Lord said to Samuel, “Don’t be impressed by his appearance or his height, for I have rejected him. God does not view things the way men do. People look on the outward appearance, but the Lord looks at the heart.”'
EXEC add_BibleVerse @BibleId, 109016008, N'Then Jesse called Abinadab and presented him to Samuel. But Samuel said, “The Lord has not chosen this one, either.”'
EXEC add_BibleVerse @BibleId, 109016009, N'Then Jesse presented Shammah. But Samuel said, “The Lord has not chosen this one either.”'
EXEC add_BibleVerse @BibleId, 109016010, N'Jesse presented seven of his sons to Samuel. But Samuel said to Jesse, “The Lord has not chosen any of these.”'
EXEC add_BibleVerse @BibleId, 109016011, N'Then Samuel said to Jesse, “Is that all of the young men?” Jesse replied, “There is still the youngest one, but he’s taking care of the flock.” Samuel said to Jesse, “Send and get him, for we cannot turn our attention to other things until he comes here.”'
EXEC add_BibleVerse @BibleId, 109016012, N'So Jesse had him brought in. Now he was ruddy, with attractive eyes and a handsome appearance. The Lord said, “Go and anoint him. This is the one!”'
EXEC add_BibleVerse @BibleId, 109016013, N'So Samuel took the horn full of olive oil and anointed him in the presence of his brothers. The Spirit of the Lord rushed upon David from that day onward. Then Samuel got up and went to Ramah.'
EXEC add_BibleVerse @BibleId, 109016014, N'Now the Spirit of the Lord had turned away from Saul, and an evil spirit from the Lord tormented him.'
EXEC add_BibleVerse @BibleId, 109016015, N'Then Saul’s servants said to him, “Look, an evil spirit from God is tormenting you!”'
EXEC add_BibleVerse @BibleId, 109016016, N'Let our lord instruct his servants who are here before you to look for a man who knows how to play the lyre. Then whenever the evil spirit from God comes upon you, he can play the lyre and you will feel better.”'
EXEC add_BibleVerse @BibleId, 109016017, N'So Saul said to his servants, “Find me a man who plays well and bring him to me.”'
EXEC add_BibleVerse @BibleId, 109016018, N'One of his attendants replied, “I have seen a son of Jesse in Bethlehem who knows how to play the lyre. He is a brave warrior and is articulate and handsome, for the Lord is with him.”'
EXEC add_BibleVerse @BibleId, 109016019, N'So Saul sent messengers to Jesse and said, “Send me your son David, who is out with the sheep.'
EXEC add_BibleVerse @BibleId, 109016020, N'So Jesse took a donkey loaded with bread, a container of wine, and a young goat and sent them to Saul with his son David.'
EXEC add_BibleVerse @BibleId, 109016021, N'David came to Saul and stood before him. Saul liked him a great deal, and he became his armor bearer.'
EXEC add_BibleVerse @BibleId, 109016022, N'Then Saul sent word to Jesse saying, “Let David be my servant, for I really like him.”'
EXEC add_BibleVerse @BibleId, 109016023, N'So whenever the spirit from God would come upon Saul, David would take his lyre and play it. This would bring relief to Saul and make him feel better. Then the evil spirit would leave him alone.'
EXEC add_BibleVerse @BibleId, 109017001, N'The Philistines gathered their troops for battle. They assembled at Socoh in Judah. They camped in Ephes Dammim, between Socoh and Azekah.'
EXEC add_BibleVerse @BibleId, 109017002, N'Saul and the Israelite army assembled and camped in the valley of Elah, where they arranged their battle lines to fight against the Philistines.'
EXEC add_BibleVerse @BibleId, 109017003, N'The Philistines were standing on one hill, and the Israelites on another hill, with the valley between them.'
EXEC add_BibleVerse @BibleId, 109017004, N'Then a champion came out from the camp of the Philistines. His name was Goliath; he was from Gath. He was close to seven feet tall.'
EXEC add_BibleVerse @BibleId, 109017005, N'He had a bronze helmet on his head and was wearing scale body armor. The weight of his bronze body armor was five thousand shekels.'
EXEC add_BibleVerse @BibleId, 109017006, N'He had bronze shin guards on his legs, and a bronze javelin was slung over his shoulders.'
EXEC add_BibleVerse @BibleId, 109017007, N'The shaft of his spear was like a weaver’s beam, and the iron point of his spear weighed six hundred shekels. His shield bearer was walking before him.'
EXEC add_BibleVerse @BibleId, 109017008, N'Goliath stood and called to Israel’s troops, “Why do you come out to prepare for battle? Am I not the Philistine, and are you not the servants of Saul? Choose for yourselves a man so he may come down to me!'
EXEC add_BibleVerse @BibleId, 109017009, N'If he is able to fight with me and strike me down, we will become your servants. But if I prevail against him and strike him down, you will become our servants and will serve us.”'
EXEC add_BibleVerse @BibleId, 109017010, N'Then the Philistine said, “I defy Israel’s troops this day! Give me a man so we can fight each other!”'
EXEC add_BibleVerse @BibleId, 109017011, N'When Saul and all the Israelites heard these words of the Philistine, they were upset and very afraid.'
EXEC add_BibleVerse @BibleId, 109017012, N'Now David was the son of this Ephrathite named Jesse from Bethlehem in Judah. He had eight sons, and in Saul’s days he was old and well advanced in years.'
EXEC add_BibleVerse @BibleId, 109017013, N'Jesse’s three oldest sons had followed Saul to war. The names of the three sons who went to war were Eliab, his firstborn, Abinadab, the second oldest, and Shammah, the third oldest.'
EXEC add_BibleVerse @BibleId, 109017014, N'Now David was the youngest. While the three oldest sons followed Saul,'
EXEC add_BibleVerse @BibleId, 109017015, N'David was going back and forth from Saul in order to care for his father’s sheep in Bethlehem.'
EXEC add_BibleVerse @BibleId, 109017016, N'Meanwhile for forty days the Philistine approached every morning and evening and took his position.'
EXEC add_BibleVerse @BibleId, 109017017, N'Jesse said to his son David, “Take your brothers this ephah of roasted grain and these ten loaves of bread; go quickly to the camp to your brothers.'
EXEC add_BibleVerse @BibleId, 109017018, N'Also take these ten portions of cheese to their commanding officer. Find out how your brothers are doing and bring back their pledge that they received the goods.'
EXEC add_BibleVerse @BibleId, 109017019, N'They are with Saul and the whole Israelite army in the valley of Elah, fighting with the Philistines.”'
EXEC add_BibleVerse @BibleId, 109017020, N'So David got up early in the morning and entrusted the flock to someone else who would watch over it. After loading up, he went just as Jesse had instructed him. He arrived at the camp as the army was going out to the battle lines shouting its battle cry.'
EXEC add_BibleVerse @BibleId, 109017021, N'Israel and the Philistines drew up their battle lines opposite one another.'
EXEC add_BibleVerse @BibleId, 109017022, N'After David had entrusted his cargo to the care of the supply officer, he ran to the battlefront. When he arrived, he asked his brothers how they were doing.'
EXEC add_BibleVerse @BibleId, 109017023, N'As he was speaking with them, the champion named Goliath, the Philistine from Gath, was coming up from the battle lines of the Philistines. He spoke the way he usually did, and David heard it.'
EXEC add_BibleVerse @BibleId, 109017024, N'When all the men of Israel saw this man, they retreated from his presence and were very afraid.'
EXEC add_BibleVerse @BibleId, 109017025, N'The men of Israel said, “Have you seen this man who is coming up? He does so to defy Israel. But the king will make the man who can strike him down very wealthy! He will give him his daughter in marriage, and he will make his father’s house exempt from tax obligations in Israel.”'
EXEC add_BibleVerse @BibleId, 109017026, N'David asked the men who were standing near him, “What will be done for the man who strikes down this Philistine and frees Israel from this humiliation? For who is this uncircumcised Philistine, that he defies the armies of the living God?”'
EXEC add_BibleVerse @BibleId, 109017027, N'The soldiers told him what had been promised, saying, “This is what will be done for the man who can strike him down.”'
EXEC add_BibleVerse @BibleId, 109017028, N'When David’s oldest brother Eliab heard him speaking to the men, he became angry with David and said, “Why have you come down here? To whom did you entrust those few sheep in the desert? I am familiar with your pride and deceit! You have come down here to watch the battle!”'
EXEC add_BibleVerse @BibleId, 109017029, N'David replied, “What have I done now? Can’t I say anything?”'
EXEC add_BibleVerse @BibleId, 109017030, N'Then he turned from those who were nearby to someone else and asked the same question, but they gave him the same answer as before.'
EXEC add_BibleVerse @BibleId, 109017031, N'When David’s words were overheard and reported to Saul, he called for him.'
EXEC add_BibleVerse @BibleId, 109017032, N'David said to Saul, “Don’t let anyone be discouraged. Your servant will go and fight this Philistine!”'
EXEC add_BibleVerse @BibleId, 109017033, N'But Saul replied to David, “You aren’t able to go against this Philistine and fight him! You’re just a boy! He has been a warrior from his youth!”'
EXEC add_BibleVerse @BibleId, 109017034, N'David replied to Saul, “Your servant has been a shepherd for his father’s flock. Whenever a lion or bear would come and carry off a sheep from the flock,'
EXEC add_BibleVerse @BibleId, 109017035, N'I would go out after it, strike it down, and rescue the sheep from its mouth. If it rose up against me, I would grab it by its jaw, strike it, and kill it.'
EXEC add_BibleVerse @BibleId, 109017036, N'Your servant has struck down both the lion and the bear. This uncircumcised Philistine will be just like one of them. For he has defied the armies of the living God!”'
EXEC add_BibleVerse @BibleId, 109017037, N'David went on to say, “The Lord who delivered me from the lion and the bear will also deliver me from the hand of this Philistine!” Then Saul said to David, “Go! The Lord will be with you.”'
EXEC add_BibleVerse @BibleId, 109017038, N'Then Saul clothed David with his own fighting attire and put a bronze helmet on his head. He also put body armor on him.'
EXEC add_BibleVerse @BibleId, 109017039, N'David strapped on his sword over his fighting attire and tried to walk around, but he was not used to them. David said to Saul, “I can’t walk in these things, for I’m not used to them.” So David removed them.'
EXEC add_BibleVerse @BibleId, 109017040, N'He took his staff in his hand, picked out five smooth stones from the stream, placed them in the pouch of his shepherd’s bag, took his sling in hand, and approached the Philistine.'
EXEC add_BibleVerse @BibleId, 109017041, N'The Philistine kept coming closer to David, with his shield bearer walking in front of him.'
EXEC add_BibleVerse @BibleId, 109017042, N'When the Philistine looked carefully at David, he despised him, for he was only a ruddy and handsome boy.'
EXEC add_BibleVerse @BibleId, 109017043, N'The Philistine said to David, “Am I a dog, that you are coming after me with sticks?” Then the Philistine cursed David by his gods.'
EXEC add_BibleVerse @BibleId, 109017044, N'The Philistine said to David, “Come here to me, so I can give your flesh to the birds of the sky and the wild animals of the field!”'
EXEC add_BibleVerse @BibleId, 109017045, N'But David replied to the Philistine, “You are coming against me with sword and spear and javelin. But I am coming against you in the name of the Lord of hosts, the God of Israel’s armies, whom you have defied!'
EXEC add_BibleVerse @BibleId, 109017046, N'This very day the Lord will deliver you into my hand! I will strike you down and cut off your head. This day I will give the corpses of the Philistine army to the birds of the sky and the wild animals of the land. Then all the land will realize that Israel has a God'
EXEC add_BibleVerse @BibleId, 109017047, N'and all this assembly will know that it is not by sword or spear that the Lord saves! For the battle is the Lord’s, and he will deliver you into our hand.”'
EXEC add_BibleVerse @BibleId, 109017048, N'The Philistine drew steadily closer to David to attack him, while David quickly ran toward the battle line to attack the Philistine.'
EXEC add_BibleVerse @BibleId, 109017049, N'David reached his hand into the bag and took out a stone. He slung it, striking the Philistine on the forehead. The stone sank deeply into his forehead, and he fell down with his face to the ground.'
EXEC add_BibleVerse @BibleId, 109017050, N'David prevailed over the Philistine with just the sling and the stone. He struck down the Philistine and killed him. David did not even have a sword in his hand.'
EXEC add_BibleVerse @BibleId, 109017051, N'David ran and stood over the Philistine. He grabbed Goliath’s sword, drew it from its sheath, killed him, and cut off his head with it. When the Philistines saw their champion was dead, they ran away.'
EXEC add_BibleVerse @BibleId, 109017052, N'Then the men of Israel and Judah charged forward, shouting a battle cry. They chased the Philistines to the valley and to the very gates of Ekron. The Philistine corpses lay fallen along the Shaaraim road to Gath and Ekron.'
EXEC add_BibleVerse @BibleId, 109017053, N'When the Israelites returned from their hot pursuit of the Philistines, they looted their camp.'
EXEC add_BibleVerse @BibleId, 109017054, N'David took the head of the Philistine and brought it to Jerusalem, and he put Goliath’s weapons in his tent.'
EXEC add_BibleVerse @BibleId, 109017055, N'Now as Saul watched David going out to fight the Philistine, he asked Abner, the general in command of the army, “Whose son is this young man, Abner?” Abner replied, “As surely as you live, O king, I don’t know.”'
EXEC add_BibleVerse @BibleId, 109017056, N'The king said, “Find out whose son this boy is!”'
EXEC add_BibleVerse @BibleId, 109017057, N'So when David returned from striking down the Philistine, Abner took him and brought him before Saul. He still had the head of the Philistine in his hand.'
EXEC add_BibleVerse @BibleId, 109017058, N'Saul said to him, “Whose son are you, young man?” David replied, “I am the son of your servant Jesse in Bethlehem.”'
EXEC add_BibleVerse @BibleId, 109018001, N'When David had finished talking with Saul, Jonathan and David became bound together in close friendship. Jonathan loved David as much as he did his own life.'
EXEC add_BibleVerse @BibleId, 109018002, N'Saul retained David on that day and did not allow him to return to his father’s house.'
EXEC add_BibleVerse @BibleId, 109018003, N'Jonathan made a covenant with David, for he loved him as much as he did his own life.'
EXEC add_BibleVerse @BibleId, 109018004, N'Jonathan took off the robe he was wearing and gave it to David, along with the rest of his gear, including his sword, his bow, and even his belt.'
EXEC add_BibleVerse @BibleId, 109018005, N'On every mission on which Saul sent him, David achieved success. So Saul appointed him over the men of war. This pleased not only all the army, but also Saul’s servants.'
EXEC add_BibleVerse @BibleId, 109018006, N'When the men arrived after David returned from striking down the Philistine, the women from all the cities of Israel came out singing and dancing to meet King Saul. They were happy as they played their tambourines and three-stringed instruments.'
EXEC add_BibleVerse @BibleId, 109018007, N'The women who were playing the music sang, “Saul has struck down his thousands, but David his tens of thousands!”'
EXEC add_BibleVerse @BibleId, 109018008, N'This made Saul very angry. The statement displeased him and he thought, “They have attributed to David tens of thousands, but to me they have attributed only thousands. What does he lack, except the kingdom?”'
EXEC add_BibleVerse @BibleId, 109018009, N'So Saul was keeping an eye on David from that day onward.'
EXEC add_BibleVerse @BibleId, 109018010, N'The next day an evil spirit from God rushed upon Saul and he prophesied within his house. Now David was playing the lyre that day. There was a spear in Saul’s hand,'
EXEC add_BibleVerse @BibleId, 109018011, N'and Saul threw the spear, thinking, “I’ll nail David to the wall!” But David escaped from him on two different occasions.'
EXEC add_BibleVerse @BibleId, 109018012, N'So Saul feared David, because the Lord was with him but had departed from Saul.'
EXEC add_BibleVerse @BibleId, 109018013, N'Saul removed David from his presence and made him a commanding officer. David led the army out to battle and back.'
EXEC add_BibleVerse @BibleId, 109018014, N'Now David achieved success in all he did, for the Lord was with him.'
EXEC add_BibleVerse @BibleId, 109018015, N'When Saul saw how very successful he was, he was afraid of him.'
EXEC add_BibleVerse @BibleId, 109018016, N'But all Israel and Judah loved David, for he was the one leading them out to battle and back.'
EXEC add_BibleVerse @BibleId, 109018017, N'Then Saul said to David, “Here’s my oldest daughter, Merab. I want to give her to you in marriage. Only be a brave warrior for me and fight the battles of the Lord.” For Saul thought, “There’s no need for me to raise my hand against him. Let it be the hand of the Philistines!”'
EXEC add_BibleVerse @BibleId, 109018018, N'David said to Saul, “Who am I? Who are my relatives or the clan of my father in Israel that I should become the king’s son-in-law?”'
EXEC add_BibleVerse @BibleId, 109018019, N'When the time came for Merab, Saul’s daughter, to be given to David, she instead was given in marriage to Adriel, who was from Meholah.'
EXEC add_BibleVerse @BibleId, 109018020, N'Now Michal, Saul’s daughter, loved David. When they told Saul about this, it pleased him.'
EXEC add_BibleVerse @BibleId, 109018021, N'Saul said, “I will give her to him so that she may become a snare to him and the hand of the Philistines may be against him.” So Saul said to David, “Today is the second time for you to become my son-in-law.”'
EXEC add_BibleVerse @BibleId, 109018022, N'Then Saul instructed his servants, “Tell David secretly, ‘The king is pleased with you, and all his servants like you. So now become the king’s son-in-law.”'
EXEC add_BibleVerse @BibleId, 109018023, N'So Saul’s servants spoke these words privately to David. David replied, “Is becoming the king’s son-in-law something insignificant to you? I’m just a poor and lightly-esteemed man!”'
EXEC add_BibleVerse @BibleId, 109018024, N'When Saul’s servants reported what David had said,'
EXEC add_BibleVerse @BibleId, 109018025, N'Saul replied, “Here is what you should say to David: ‘There is nothing that the king wants as a price for the bride except a hundred Philistine foreskins, so that he can be avenged of his enemies.’” (Now Saul was thinking that he could kill David by the hand of the Philistines.)'
EXEC add_BibleVerse @BibleId, 109018026, N'So his servants told David these things and David agreed to become the king’s son-in-law. Now the specified time had not yet expired'
EXEC add_BibleVerse @BibleId, 109018027, N'when David, along with his men, went out and struck down two hundred Philistine men. David brought their foreskins and presented all of them to the king so he could become the king’s son-in-law. Saul then gave him his daughter Michal in marriage.'
EXEC add_BibleVerse @BibleId, 109018028, N'When Saul realized that the Lord was with David and that his daughter Michal loved David,'
EXEC add_BibleVerse @BibleId, 109018029, N'Saul became even more afraid of him. Saul continued to be at odds with David from then on.'
EXEC add_BibleVerse @BibleId, 109018030, N'Then the leaders of the Philistines would march out, and as often as they did so, David achieved more success than all of Saul’s servants. His name was held in high esteem.'
EXEC add_BibleVerse @BibleId, 109019001, N'Then Saul told his son Jonathan and all his servants to kill David. But Saul’s son Jonathan liked David very much.'
EXEC add_BibleVerse @BibleId, 109019002, N'So Jonathan told David, “My father Saul is trying to kill you. So be careful tomorrow morning. Find a hiding place and stay in seclusion.'
EXEC add_BibleVerse @BibleId, 109019003, N'I will go out and stand beside my father in the field where you are. I will speak about you to my father. When I find out what the problem is, I will let you know.”'
EXEC add_BibleVerse @BibleId, 109019004, N'So Jonathan spoke on David’s behalf to his father Saul. He said to him, “The king should not sin against his servant David, for he has not sinned against you. On the contrary, his actions have been very beneficial for you.'
EXEC add_BibleVerse @BibleId, 109019005, N'He risked his life when he struck down the Philistine and the Lord gave all Israel a great victory. When you saw it, you were happy. So why would you sin against innocent blood by putting David to death for no reason?”'
EXEC add_BibleVerse @BibleId, 109019006, N'Saul accepted Jonathan’s advice and took an oath, “As surely as the Lord lives, he will not be put to death.”'
EXEC add_BibleVerse @BibleId, 109019007, N'Then Jonathan called David and told him all these things. Jonathan brought David to Saul, and he served him as he had done formerly.'
EXEC add_BibleVerse @BibleId, 109019008, N'Now once again there was war. So David went out to fight the Philistines. He defeated them thoroughly and they ran away from him.'
EXEC add_BibleVerse @BibleId, 109019009, N'Then an evil spirit from the Lord came upon Saul. He was sitting in his house with his spear in his hand, while David was playing the lyre.'
EXEC add_BibleVerse @BibleId, 109019010, N'Saul tried to nail David to the wall with the spear, but he escaped from Saul’s presence and the spear drove into the wall. David escaped quickly that night.'
EXEC add_BibleVerse @BibleId, 109019011, N'Saul sent messengers to David’s house to guard it and to kill him in the morning. Then David’s wife Michal told him, “If you do not save yourself tonight, tomorrow you will be dead!”'
EXEC add_BibleVerse @BibleId, 109019012, N'So Michal lowered David through the window, and he ran away and escaped.'
EXEC add_BibleVerse @BibleId, 109019013, N'Then Michal took a household idol and put it on the bed. She put a quilt made of goat’s hair over its head and then covered the idol with a garment.'
EXEC add_BibleVerse @BibleId, 109019014, N'When Saul sent messengers to arrest David, she said, “He’s sick.”'
EXEC add_BibleVerse @BibleId, 109019015, N'Then Saul sent the messengers back to see David, saying, “Bring him up to me on his bed so I can kill him.”'
EXEC add_BibleVerse @BibleId, 109019016, N'When the messengers came, they found only the idol on the bed and the quilt made of goat’s hair at its head.'
EXEC add_BibleVerse @BibleId, 109019017, N'Saul said to Michal, “Why have you deceived me this way by sending my enemy away? Now he has escaped!” Michal replied to Saul, “He said to me, ‘Help me get away or else I will kill you!’”'
EXEC add_BibleVerse @BibleId, 109019018, N'Now David had run away and escaped. He went to Samuel in Ramah and told him everything that Saul had done to him. Then he and Samuel went and stayed at Naioth.'
EXEC add_BibleVerse @BibleId, 109019019, N'It was reported to Saul saying, “David is at Naioth in Ramah.”'
EXEC add_BibleVerse @BibleId, 109019020, N'So Saul sent messengers to capture David. When they saw a company of prophets prophesying with Samuel standing there as their leader, the spirit of God came upon Saul’s messengers, and they also prophesied.'
EXEC add_BibleVerse @BibleId, 109019021, N'When it was reported to Saul, he sent more messengers, but they prophesied too. So Saul sent messengers a third time, but they also prophesied.'
EXEC add_BibleVerse @BibleId, 109019022, N'Finally Saul himself went to Ramah. When he arrived at the large cistern that is in Secu, he asked, “Where are Samuel and David?” They said, “At Naioth in Ramah.”'
EXEC add_BibleVerse @BibleId, 109019023, N'So Saul went to Naioth in Ramah. The Spirit of God came upon him as well, and he walked along prophesying until he came to Naioth in Ramah.'
EXEC add_BibleVerse @BibleId, 109019024, N'He even stripped off his clothes and prophesied before Samuel. He lay there naked all that day and night. (For that reason it is asked, “Is Saul also among the prophets?”)'
EXEC add_BibleVerse @BibleId, 109020001, N'David fled from Naioth in Ramah. He came to Jonathan and asked, “What have I done? What is my offense? How have I sinned before your father? For he is seeking my life!”'
EXEC add_BibleVerse @BibleId, 109020002, N'Jonathan said to him, “By no means are you going to die! My father does nothing large or small without making me aware of it. Why would my father hide this matter from me? It just won’t happen!”'
EXEC add_BibleVerse @BibleId, 109020003, N'Taking an oath, David again said, “Your father is very much aware of the fact that I have found favor with you, and he has thought, ‘Don’t let Jonathan know about this, or he will be upset.’ But as surely as the Lord lives and you live, there is about one step between me and death!”'
EXEC add_BibleVerse @BibleId, 109020004, N'Jonathan replied to David, “Tell me what I can do for you.”'
EXEC add_BibleVerse @BibleId, 109020005, N'David said to Jonathan, “Tomorrow is the new moon, and I am certainly expected to join the king for a meal. You must send me away so I can hide in the field until the third evening from now.'
EXEC add_BibleVerse @BibleId, 109020006, N'If your father happens to miss me, you should say, ‘David urgently requested me to let him go to his city Bethlehem, for there is an annual sacrifice there for his entire family.’'
EXEC add_BibleVerse @BibleId, 109020007, N'If he should then say, ‘That’s fine,’ then your servant is safe. But if he becomes very angry, be assured that he has decided to harm me.'
EXEC add_BibleVerse @BibleId, 109020008, N'You must be loyal to your servant, for you have made a covenant with your servant in the Lord’s name. If I am guilty, you yourself kill me! Why bother taking me to your father?”'
EXEC add_BibleVerse @BibleId, 109020009, N'Jonathan said, “Far be it from you to suggest this! If I were at all aware that my father had decided to harm you, wouldn’t I tell you about it?”'
EXEC add_BibleVerse @BibleId, 109020010, N'David said to Jonathan, “Who will tell me if your father answers you harshly?”'
EXEC add_BibleVerse @BibleId, 109020011, N'Jonathan said to David, “Come on. Let’s go out to the field.” When the two of them had gone out into the field,'
EXEC add_BibleVerse @BibleId, 109020012, N'Jonathan said to David, “The Lord God of Israel is my witness. I will feel out my father about this time the day after tomorrow. If he is favorably inclined toward David, will I not then send word to you and let you know?'
EXEC add_BibleVerse @BibleId, 109020013, N'But if my father intends to do you harm, may the Lord do all this and more to Jonathan, if I don’t let you know and send word to you so you can go safely on your way. May the Lord be with you, as he was with my father.'
EXEC add_BibleVerse @BibleId, 109020014, N'While I am still alive, extend to me the loyalty of the Lord, or else I will die!'
EXEC add_BibleVerse @BibleId, 109020015, N'Don’t ever cut off your loyalty to my family, not even when the Lord has cut off every one of David’s enemies from the face of the earth'
EXEC add_BibleVerse @BibleId, 109020016, N'and called David’s enemies to account.” So Jonathan made a covenant with the house of David.'
EXEC add_BibleVerse @BibleId, 109020017, N'Jonathan once again took an oath with David, because he loved him. In fact Jonathan loved him as much as he did his own life.'
EXEC add_BibleVerse @BibleId, 109020018, N'Jonathan said to him, “Tomorrow is the new moon, and you will be missed, for your seat will be empty.'
EXEC add_BibleVerse @BibleId, 109020019, N'On the third day you should go down quickly and come to the place where you hid yourself the day this all started. Stay near the stone Ezel.'
EXEC add_BibleVerse @BibleId, 109020020, N'I will shoot three arrows near it, as though I were shooting at a target.'
EXEC add_BibleVerse @BibleId, 109020021, N'When I send a boy after them, I will say, “Go and find the arrows.” If I say to the boy, ‘Look, the arrows are on this side of you; get them,’ then come back. For as surely as the Lord lives, you will be safe and there will no problem.'
EXEC add_BibleVerse @BibleId, 109020022, N'But if I say to the boy, “Look, the arrows are on the other side of you,’ get away. For in that case the Lord has sent you away.'
EXEC add_BibleVerse @BibleId, 109020023, N'With regard to the matter that you and I discussed, the Lord is the witness between us forever!”'
EXEC add_BibleVerse @BibleId, 109020024, N'So David hid in the field. When the new moon came, the king sat down to eat his meal.'
EXEC add_BibleVerse @BibleId, 109020025, N'The king sat down in his usual place by the wall, with Jonathan opposite him and Abner at his side. But David’s place was vacant.'
EXEC add_BibleVerse @BibleId, 109020026, N'However, Saul said nothing about it that day, for he thought, “Something has happened to make him ceremonially unclean. Yes, he must be unclean.”'
EXEC add_BibleVerse @BibleId, 109020027, N'But the next morning, the second day of the new moon, David’s place was still vacant. So Saul said to his son Jonathan, “Why has Jesse’s son not come to the meal yesterday or today?”'
EXEC add_BibleVerse @BibleId, 109020028, N'Jonathan replied to Saul, “David urgently requested that he be allowed to go to Bethlehem.'
EXEC add_BibleVerse @BibleId, 109020029, N'He said, ‘Permit me to go, for we are having a family sacrifice in the city, and my brother urged me to be there. So now, if I have found favor with you, let me go to see my brothers.’ For that reason he has not come to the king’s table.”'
EXEC add_BibleVerse @BibleId, 109020030, N'Saul became angry with Jonathan and said to him, “You stupid traitor! Don’t I realize that to your own disgrace and to the disgrace of your mother’s nakedness you have chosen this son of Jesse?'
EXEC add_BibleVerse @BibleId, 109020031, N'For as long as this son of Jesse is alive on the earth, you and your kingdom will not be established. Now, send some men and bring him to me. For he is as good as dead!”'
EXEC add_BibleVerse @BibleId, 109020032, N'Jonathan responded to his father Saul, “Why should he be put to death? What has he done?”'
EXEC add_BibleVerse @BibleId, 109020033, N'Then Saul threw his spear at Jonathan in order to strike him down. So Jonathan was convinced that his father had decided to kill David.'
EXEC add_BibleVerse @BibleId, 109020034, N'Jonathan got up from the table enraged. He did not eat any food on that second day of the new moon, for he was upset that his father had humiliated David.'
EXEC add_BibleVerse @BibleId, 109020035, N'The next morning Jonathan, along with a young servant, went out to the field to meet David.'
EXEC add_BibleVerse @BibleId, 109020036, N'He said to his servant, “Run, find the arrows that I am about to shoot.” As the servant ran, Jonathan shot the arrow beyond him.'
EXEC add_BibleVerse @BibleId, 109020037, N'When the servant came to the place where Jonathan had shot the arrow, Jonathan called out to the servant, “Isn’t the arrow further beyond you?”'
EXEC add_BibleVerse @BibleId, 109020038, N'Jonathan called out to the servant, “Hurry! Go faster! Don’t delay!” Jonathan’s servant retrieved the arrow and came back to his master.'
EXEC add_BibleVerse @BibleId, 109020039, N'(Now the servant did not understand any of this. Only Jonathan and David knew what was going on.)'
EXEC add_BibleVerse @BibleId, 109020040, N'Then Jonathan gave his equipment to the servant who was with him. He said to him, “Go, take these things back to the city.”'
EXEC add_BibleVerse @BibleId, 109020041, N'When the servant had left, David got up from beside the mound, knelt with his face to the ground, and bowed three times. Then they kissed each other and they both wept, especially David.'
EXEC add_BibleVerse @BibleId, 109020042, N'Jonathan said to David, “Go in peace, for the two of us have sworn together in the name of the Lord saying, ‘The Lord will be between me and you and between my descendants and your descendants forever.’” Then David got up and left, while Jonathan went back to the city.'
EXEC add_BibleVerse @BibleId, 109021001, N'David went to Ahimelech the priest in Nob. Ahimelech was shaking with fear when he met David, and said to him, “Why are you by yourself with no one accompanying you?”'
EXEC add_BibleVerse @BibleId, 109021002, N'David replied to Ahimelech the priest, “The king instructed me to do something, but he said to me, ‘Don’t let anyone know the reason I am sending you or the instructions I have given you.’ I have told my soldiers to wait at a certain place.'
EXEC add_BibleVerse @BibleId, 109021003, N'Now what do you have at your disposal? Give me five loaves of bread, or whatever can be found.”'
EXEC add_BibleVerse @BibleId, 109021004, N'The priest replied to David, “I don’t have any ordinary bread at my disposal. Only holy bread is available, and then only if your soldiers have abstained from sexual relations with women.”'
EXEC add_BibleVerse @BibleId, 109021005, N'David said to the priest, “Certainly women have been kept away from us, just as on previous occasions when I have set out. The soldiers’ equipment is holy, even on an ordinary journey. How much more so will they be holy today, along with their equipment!”'
EXEC add_BibleVerse @BibleId, 109021006, N'So the priest gave him holy bread, for there was no bread there other than the bread of the Presence. It had been removed from before the Lord in order to replace it with hot bread on the day it had been taken away.'
EXEC add_BibleVerse @BibleId, 109021007, N'(One of Saul’s servants was there that day, detained before the Lord. His name was Doeg the Edomite, who was in charge of Saul’s shepherds.)'
EXEC add_BibleVerse @BibleId, 109021008, N'David said to Ahimelech, “Is there no sword or spear here at your disposal? I don’t have my own sword or equipment in hand due to the urgency of the king’s instructions.”'
EXEC add_BibleVerse @BibleId, 109021009, N'The priest replied, “The sword of Goliath the Philistine, whom you struck down in the valley of Elah, is wrapped in a garment behind the ephod. If you wish, take it for yourself. Other than that, there’s nothing here.” David said, “There’s nothing like it! Give it to me!”'
EXEC add_BibleVerse @BibleId, 109021010, N'So on that day David arose and fled from Saul. He went to King Achish of Gath.'
EXEC add_BibleVerse @BibleId, 109021011, N'The servants of Achish said to him, “Isn’t this David, the king of the land? Isn’t he the one that they sing about when they dance, saying, ‘Saul struck down his thousands, But David his tens of thousands’?”'
EXEC add_BibleVerse @BibleId, 109021012, N'David thought about what they said and was very afraid of King Achish of Gath.'
EXEC add_BibleVerse @BibleId, 109021013, N'He altered his behavior in their presence. Since he was in their power, he pretended to be insane, making marks on the doors of the gate and letting his saliva run down his beard.'
EXEC add_BibleVerse @BibleId, 109021014, N'Achish said to his servants, “Look at this madman! Why did you bring him to me?'
EXEC add_BibleVerse @BibleId, 109021015, N'Do I have a shortage of fools, that you have brought me this man to display his insanity in front of me? Should this man enter my house?”'
EXEC add_BibleVerse @BibleId, 109022001, N'So David left there and escaped to the cave of Adullam. When his brothers and the rest of his father’s family learned about it, they went down there to him.'
EXEC add_BibleVerse @BibleId, 109022002, N'All those who were in trouble or owed someone money or were discontented gathered around him, and he became their leader. He had about four hundred men with him.'
EXEC add_BibleVerse @BibleId, 109022003, N'Then David went from there to Mizpah in Moab, where he said to the king of Moab, “Please let my father and mother stay with you until I know what God is going to do for me.”'
EXEC add_BibleVerse @BibleId, 109022004, N'So he had them stay with the king of Moab; they stayed with him the whole time that David was in the stronghold.'
EXEC add_BibleVerse @BibleId, 109022005, N'Then Gad the prophet said to David, “Don’t stay in the stronghold. Go to the land of Judah.” So David left and went to the forest of Hereth.'
EXEC add_BibleVerse @BibleId, 109022006, N'But Saul found out the whereabouts of David and the men who were with him. Now Saul was sitting at Gibeah under the tamarisk tree at an elevated location with his spear in hand and all his servants stationed around him.'
EXEC add_BibleVerse @BibleId, 109022007, N'Saul said to his servants who were stationed around him, “Listen up, you Benjaminites! Is Jesse’s son giving fields and vineyards to all of you? Or is he making all of you commanders and officers?'
EXEC add_BibleVerse @BibleId, 109022008, N'For all of you have conspired against me! No one informs me when my own son makes an agreement with this son of Jesse! Not one of you feels sorry for me or informs me that my own son has commissioned my own servant to hide in ambush against me, as is the case today!”'
EXEC add_BibleVerse @BibleId, 109022009, N'But Doeg the Edomite, who had stationed himself with the servants of Saul, replied, “I saw this son of Jesse come to Ahimelech son of Ahitub at Nob.'
EXEC add_BibleVerse @BibleId, 109022010, N'He inquired of the Lord for him and gave him provisions. He also gave him the sword of Goliath the Philistine.”'
EXEC add_BibleVerse @BibleId, 109022011, N'Then the king arranged for a meeting with the priest Ahimelech son of Ahitub and all the priests of his father’s house who were at Nob. They all came to the king.'
EXEC add_BibleVerse @BibleId, 109022012, N'Then Saul said, “Listen, son of Ahitub.” He replied, “Here I am, my lord.”'
EXEC add_BibleVerse @BibleId, 109022013, N'Saul said to him, “Why have you conspired against me, you and this son of Jesse? You gave him bread and a sword and inquired of God on his behalf, so that he opposes me and waits in ambush, as is the case today!”'
EXEC add_BibleVerse @BibleId, 109022014, N'Ahimelech replied to the king, “Who among all your servants is faithful like David? He is the king’s son-in-law, the leader of your bodyguard, and honored in your house!'
EXEC add_BibleVerse @BibleId, 109022015, N'Was it just today that I began to inquire of God on his behalf? Far be it from me! The king should not accuse his servant or any of my father’s house. For your servant is not aware of all this – not in whole or in part!”'
EXEC add_BibleVerse @BibleId, 109022016, N'But the king said, “You will surely die, Ahimelech, you and all your father’s house!'
EXEC add_BibleVerse @BibleId, 109022017, N'Then the king said to the messengers who were stationed beside him, “Turn and kill the priests of the Lord, for they too have sided with David! They knew he was fleeing, but they did not inform me.” But the king’s servants refused to harm the priests of the Lord.'
EXEC add_BibleVerse @BibleId, 109022018, N'Then the king said to Doeg, “You turn and strike down the priests!” So Doeg the Edomite turned and struck down the priests. He killed on that day eighty-five men who wore the linen ephod.'
EXEC add_BibleVerse @BibleId, 109022019, N'As for Nob, the city of the priests, he struck down with the sword men and women, children and infants, oxen, donkeys, and sheep – all with the sword.'
EXEC add_BibleVerse @BibleId, 109022020, N'But one of the sons of Ahimelech son of Ahitub escaped and fled to David. His name was Abiathar.'
EXEC add_BibleVerse @BibleId, 109022021, N'Abiathar told David that Saul had killed the priests of the Lord.'
EXEC add_BibleVerse @BibleId, 109022022, N'Then David said to Abiathar, “I knew that day when Doeg the Edomite was there that he would certainly tell Saul! I am guilty of all the deaths in your father’s house!'
EXEC add_BibleVerse @BibleId, 109022023, N'Stay with me. Don’t be afraid! Whoever seeks my life is seeking your life as well. You are secure with me.”'
EXEC add_BibleVerse @BibleId, 109023001, N'They told David, “The Philistines are fighting in Keilah and are looting the threshing floors.”'
EXEC add_BibleVerse @BibleId, 109023002, N'So David asked the Lord, “Should I go and strike down these Philistines?” The Lord said to David, “Go, strike down the Philistines and deliver Keilah.”'
EXEC add_BibleVerse @BibleId, 109023003, N'But David’s men said to him, “We are afraid while we are still here in Judah! What will it be like if we go to Keilah against the armies of the Philistines?”'
EXEC add_BibleVerse @BibleId, 109023004, N'So David asked the Lord once again. But again the Lord replied, “Arise, go down to Keilah, for I will give the Philistines into your hand.”'
EXEC add_BibleVerse @BibleId, 109023005, N'So David and his men went to Keilah and fought the Philistines. He took away their cattle and thoroughly defeated them. David delivered the inhabitants of Keilah.'
EXEC add_BibleVerse @BibleId, 109023006, N'Now when Abiathar son of Ahimelech had fled to David at Keilah, he had brought with him an ephod.'
EXEC add_BibleVerse @BibleId, 109023007, N'When Saul was told that David had come to Keilah, Saul said, “God has delivered him into my hand, for he has boxed himself into a corner by entering a city with two barred gates.”'
EXEC add_BibleVerse @BibleId, 109023008, N'So Saul mustered all his army to go down to Keilah and besiege David and his men.'
EXEC add_BibleVerse @BibleId, 109023009, N'When David realized that Saul was planning to harm him, he told Abiathar the priest, “Bring the ephod!”'
EXEC add_BibleVerse @BibleId, 109023010, N'Then David said, “O Lord God of Israel, your servant has clearly heard that Saul is planning to come to Keilah to destroy the city because of me.'
EXEC add_BibleVerse @BibleId, 109023011, N'Will the leaders of Keilah deliver me into his hand? Will Saul come down as your servant has heard? O Lord God of Israel, please inform your servant!” Then the Lord said, “He will come down.”'
EXEC add_BibleVerse @BibleId, 109023012, N'David asked, “Will the leaders of Keilah deliver me and my men into Saul’s hand?” The Lord said, “They will deliver you over.”'
EXEC add_BibleVerse @BibleId, 109023013, N'So David and his men, who numbered about six hundred, set out and left Keilah; they moved around from one place to another. When told that David had escaped from Keilah, Saul called a halt to his expedition.'
EXEC add_BibleVerse @BibleId, 109023014, N'David stayed in the strongholds that were in the desert and in the hill country of the desert of Ziph. Saul looked for him all the time, but God did not deliver David into his hand.'
EXEC add_BibleVerse @BibleId, 109023015, N'David realized that Saul had come out to seek his life; at that time David was in Horesh in the desert of Ziph.'
EXEC add_BibleVerse @BibleId, 109023016, N'Then Jonathan son of Saul left and went to David at Horesh. He encouraged him through God.'
EXEC add_BibleVerse @BibleId, 109023017, N'He said to him, “Don’t be afraid! For the hand of my father Saul cannot find you. You will rule over Israel, and I will be your second in command. Even my father Saul realizes this.”'
EXEC add_BibleVerse @BibleId, 109023018, N'When the two of them had made a covenant before the Lord, David stayed on at Horesh, but Jonathan went to his house.'
EXEC add_BibleVerse @BibleId, 109023019, N'Then the Ziphites went up to Saul at Gibeah and said, “Isn’t David hiding among us in the strongholds at Horesh on the hill of Hakilah, south of Jeshimon?'
EXEC add_BibleVerse @BibleId, 109023020, N'Now at your own discretion, O king, come down. Delivering him into the king’s hand will be our responsibility.”'
EXEC add_BibleVerse @BibleId, 109023021, N'Saul replied, “May you be blessed by the Lord, for you have had compassion on me.'
EXEC add_BibleVerse @BibleId, 109023022, N'Go and make further arrangements. Determine precisely where he is and who has seen him there, for I am told that he is extremely cunning.'
EXEC add_BibleVerse @BibleId, 109023023, N'Locate precisely all the places where he hides and return to me with dependable information. Then I will go with you. If he is in the land, I will find him among all the thousands of Judah.”'
EXEC add_BibleVerse @BibleId, 109023024, N'So they left and went to Ziph ahead of Saul. Now David and his men were in the desert of Maon, in the Arabah to the south of Jeshimon.'
EXEC add_BibleVerse @BibleId, 109023025, N'Saul and his men went to look for him. But David was informed and went down to the rock and stayed in the desert of Maon. When Saul heard about it, he pursued David in the desert of Maon.'
EXEC add_BibleVerse @BibleId, 109023026, N'Saul went on one side of the mountain, while David and his men went on the other side of the mountain. David was hurrying to get away from Saul, but Saul and his men were surrounding David and his men so they could capture them.'
EXEC add_BibleVerse @BibleId, 109023027, N'But a messenger came to Saul saying, “Come quickly, for the Philistines have raided the land!”'
EXEC add_BibleVerse @BibleId, 109023028, N'So Saul stopped pursuing David and went to confront the Philistines. Therefore that place is called Sela Hammahlekoth.'
EXEC add_BibleVerse @BibleId, 109023029, N'Then David went up from there and stayed in the strongholds of En Gedi.'
EXEC add_BibleVerse @BibleId, 109024001, N'When Saul returned from pursuing the Philistines, they told him, “Look, David is in the desert of En Gedi.”'
EXEC add_BibleVerse @BibleId, 109024002, N'So Saul took three thousand select men from all Israel and went to find David and his men in the region of the rocks of the mountain goats.'
EXEC add_BibleVerse @BibleId, 109024003, N'He came to the sheepfolds by the road, where there was a cave. Saul went into it to relieve himself. Now David and his men were sitting in the recesses of the cave.'
EXEC add_BibleVerse @BibleId, 109024004, N'David’s men said to him, “This is the day about which the Lord said to you, ‘I will give your enemy into your hand, and you can do to him whatever seems appropriate to you.’” So David got up and quietly cut off an edge of Saul’s robe.'
EXEC add_BibleVerse @BibleId, 109024005, N'Afterward David’s conscience bothered him because he had cut off an edge of Saul’s robe.'
EXEC add_BibleVerse @BibleId, 109024006, N'He said to his men, “May the Lord keep me far away from doing such a thing to my lord, who is the Lord’s chosen one, by extending my hand against him. After all, he is the Lord’s chosen one.”'
EXEC add_BibleVerse @BibleId, 109024007, N'David restrained his men with these words and did not allow them to rise up against Saul. Then Saul left the cave and started down the road.'
EXEC add_BibleVerse @BibleId, 109024008, N'Afterward David got up and went out of the cave. He called out after Saul, “My lord, O king!” When Saul looked behind him, David kneeled down and bowed with his face to the ground.'
EXEC add_BibleVerse @BibleId, 109024009, N'David said to Saul, “Why do you pay attention when men say, ‘David is seeking to do you harm’?'
EXEC add_BibleVerse @BibleId, 109024010, N'Today your own eyes see how the Lord delivered you – this very day – into my hands in the cave. Some told me to kill you, but I had pity on you and said, ‘I will not extend my hand against my lord, for he is the Lord’s chosen one.’'
EXEC add_BibleVerse @BibleId, 109024011, N'Look, my father, and see the edge of your robe in my hand! When I cut off the edge of your robe, I didn’t kill you. So realize and understand that I am not planning evil or rebellion. Even though I have not sinned against you, you are waiting in ambush to take my life.'
EXEC add_BibleVerse @BibleId, 109024012, N'May the Lord judge between the two of us, and may the Lord vindicate me over you, but my hand will not be against you.'
EXEC add_BibleVerse @BibleId, 109024013, N'It’s like the old proverb says: ‘From evil people evil proceeds.’ But my hand will not be against you.'
EXEC add_BibleVerse @BibleId, 109024014, N'Who has the king of Israel come out after? Who is it that you are pursuing? A dead dog? A single flea?'
EXEC add_BibleVerse @BibleId, 109024015, N'May the Lord be our judge and arbiter. May he see and arbitrate my case and deliver me from your hands!”'
EXEC add_BibleVerse @BibleId, 109024016, N'When David finished speaking these words to Saul, Saul said, “Is that your voice, my son David?” Then Saul wept loudly.'
EXEC add_BibleVerse @BibleId, 109024017, N'He said to David, “You are more innocent than I, for you have treated me well, even though I have tried to harm you!'
EXEC add_BibleVerse @BibleId, 109024018, N'You have explained today how you have treated me well. The Lord delivered me into your hand, but you did not kill me.'
EXEC add_BibleVerse @BibleId, 109024019, N'Now if a man finds his enemy, does he send him on his way in good shape? May the Lord repay you with good this day for what you have done to me.'
EXEC add_BibleVerse @BibleId, 109024020, N'Now look, I realize that you will in fact be king and that the kingdom of Israel will be established in your hand.'
EXEC add_BibleVerse @BibleId, 109024021, N'So now swear to me in the Lord’s name that you will not kill my descendants after me or destroy my name from the house of my father.”'
EXEC add_BibleVerse @BibleId, 109024022, N'David promised Saul this on oath. Then Saul went to his house, and David and his men went up to the stronghold.'
EXEC add_BibleVerse @BibleId, 109025001, N'Samuel died, and all Israel assembled and mourned him. They buried him at his home in Ramah. Then David left and went down to the desert of Paran.'
EXEC add_BibleVerse @BibleId, 109025002, N'There was a man in Maon whose business was in Carmel. This man was very wealthy; he owned three thousand sheep and a thousand goats. At that time he was shearing his sheep in Carmel.'
EXEC add_BibleVerse @BibleId, 109025003, N'The man’s name was Nabal, and his wife’s name was Abigail. She was both wise and beautiful, but the man was harsh and his deeds were evil. He was a Calebite.'
EXEC add_BibleVerse @BibleId, 109025004, N'When David heard in the desert that Nabal was shearing his sheep,'
EXEC add_BibleVerse @BibleId, 109025005, N'he sent ten servants, saying to them, “Go up to Carmel to see Nabal and give him greetings in my name.'
EXEC add_BibleVerse @BibleId, 109025006, N'Then you will say to my brother, “Peace to you and your house! Peace to all that is yours!'
EXEC add_BibleVerse @BibleId, 109025007, N'Now I hear that they are shearing sheep for you. When your shepherds were with us, we neither insulted them nor harmed them the whole time they were in Carmel.'
EXEC add_BibleVerse @BibleId, 109025008, N'Ask your own servants; they can tell you! May my servants find favor in your sight, for we have come at the time of a holiday. Please provide us – your servants and your son David – with whatever you can spare.”'
EXEC add_BibleVerse @BibleId, 109025009, N'So David’s servants went and spoke all these words to Nabal in David’s name. Then they paused.'
EXEC add_BibleVerse @BibleId, 109025010, N'But Nabal responded to David’s servants, “Who is David, and who is this son of Jesse? This is a time when many servants are breaking away from their masters!'
EXEC add_BibleVerse @BibleId, 109025011, N'Should I take my bread and my water and my meat that I have slaughtered for my shearers and give them to these men? I don’t even know where they came from!”'
EXEC add_BibleVerse @BibleId, 109025012, N'So David’s servants went on their way. When they had returned, they came and told David all these things.'
EXEC add_BibleVerse @BibleId, 109025013, N'Then David instructed his men, “Each of you strap on your sword!” So each one strapped on his sword, and David also strapped on his sword. About four hundred men followed David up, while two hundred stayed behind with the equipment.'
EXEC add_BibleVerse @BibleId, 109025014, N'But one of the servants told Nabal’s wife Abigail, “David sent messengers from the desert to greet our lord, but he screamed at them.'
EXEC add_BibleVerse @BibleId, 109025015, N'These men were very good to us. They did not insult us, nor did we sustain any loss during the entire time we were together in the field.'
EXEC add_BibleVerse @BibleId, 109025016, N'Both night and day they were a protective wall for us the entire time we were with them, while we were tending our flocks.'
EXEC add_BibleVerse @BibleId, 109025017, N'Now be aware of this, and see what you can do. For disaster has been planned for our lord and his entire household. He is such a wicked person that no one tells him anything!”'
EXEC add_BibleVerse @BibleId, 109025018, N'So Abigail quickly took two hundred loaves of bread, two containers of wine, five prepared sheep, five seahs of roasted grain, a hundred bunches of raisins, and two hundred lumps of pressed figs. She loaded them on donkeys'
EXEC add_BibleVerse @BibleId, 109025019, N'and said to her servants, “Go on ahead of me. I will come after you.” But she did not tell her husband Nabal.'
EXEC add_BibleVerse @BibleId, 109025020, N'Riding on her donkey, she went down under cover of the mountain. David and his men were coming down to meet her, and she encountered them.'
EXEC add_BibleVerse @BibleId, 109025021, N'Now David had been thinking, “In vain I guarded everything that belonged to this man in the desert. I didn’t take anything from him. But he has repaid my good with evil.'
EXEC add_BibleVerse @BibleId, 109025022, N'God will severely punish David, if I leave alive until morning even one male from all those who belong to him!”'
EXEC add_BibleVerse @BibleId, 109025023, N'When Abigail saw David, she got down quickly from the donkey, threw herself down before David, and bowed to the ground.'
EXEC add_BibleVerse @BibleId, 109025024, N'Falling at his feet, she said, “My lord, I accept all the guilt! But please let your female servant speak with my lord! Please listen to the words of your servant!'
EXEC add_BibleVerse @BibleId, 109025025, N'My lord should not pay attention to this wicked man Nabal. He simply lives up to his name! His name means ‘fool,’ and he is indeed foolish! But I, your servant, did not see the servants my lord sent.'
EXEC add_BibleVerse @BibleId, 109025026, N'“Now, my lord, as surely as the Lord lives and as surely as you live, it is the Lord who has kept you from shedding blood and taking matters into your own hands. Now may your enemies and those who seek to harm my lord be like Nabal.'
EXEC add_BibleVerse @BibleId, 109025027, N'Now let this present that your servant has brought to my lord be given to the servants who follow my lord.'
EXEC add_BibleVerse @BibleId, 109025028, N'Please forgive the sin of your servant, for the Lord will certainly establish the house of my lord, because my lord fights the battles of the Lord. May no evil be found in you all your days!'
EXEC add_BibleVerse @BibleId, 109025029, N'When someone sets out to chase you and to take your life, the life of my lord will be wrapped securely in the bag of the living by the Lord your God. But he will sling away the lives of your enemies from the sling’s pocket!'
EXEC add_BibleVerse @BibleId, 109025030, N'The Lord will do for my lord everything that he promised you, and he will make you a leader over Israel.'
EXEC add_BibleVerse @BibleId, 109025031, N'Your conscience will not be overwhelmed with guilt for having poured out innocent blood and for having taken matters into your own hands. When the Lord has granted my lord success, please remember your servant.”'
EXEC add_BibleVerse @BibleId, 109025032, N'Then David said to Abigail, “Praised be the Lord, the God of Israel, who has sent you this day to meet me!'
EXEC add_BibleVerse @BibleId, 109025033, N'Praised be your good judgment! May you yourself be rewarded for having prevented me this day from shedding blood and taking matters into my own hands!'
EXEC add_BibleVerse @BibleId, 109025034, N'Otherwise, as surely as the Lord, the God of Israel, lives – he who has prevented me from harming you – if you had not come so quickly to meet me, by morning’s light not even one male belonging to Nabal would have remained alive!”'
EXEC add_BibleVerse @BibleId, 109025035, N'Then David took from her hand what she had brought to him. He said to her, “Go back to your home in peace. Be assured that I have listened to you and responded favorably.”'
EXEC add_BibleVerse @BibleId, 109025036, N'When Abigail went back to Nabal, he was holding a banquet in his house like that of the king. Nabal was having a good time and was very intoxicated. She told him absolutely nothing until morning’s light.'
EXEC add_BibleVerse @BibleId, 109025037, N'In the morning, when Nabal was sober, his wife told him about these matters. He had a stroke and was paralyzed.'
EXEC add_BibleVerse @BibleId, 109025038, N'After about ten days the Lord struck Nabal down and he died.'
EXEC add_BibleVerse @BibleId, 109025039, N'When David heard that Nabal had died, he said, “Praised be the Lord who has vindicated me and avenged the insult that I suffered from Nabal! The Lord has kept his servant from doing evil, and he has repaid Nabal for his evil deeds.” Then David sent word to Abigail and asked her to become his wife.'
EXEC add_BibleVerse @BibleId, 109025040, N'So the servants of David went to Abigail at Carmel and said to her, “David has sent us to you to bring you back to be his wife.”'
EXEC add_BibleVerse @BibleId, 109025041, N'She arose, bowed her face toward the ground, and said, “Your female servant, like a lowly servant, will wash the feet of the servants of my lord.”'
EXEC add_BibleVerse @BibleId, 109025042, N'Then Abigail quickly went and mounted her donkey, with five of her female servants accompanying her. She followed David’s messengers and became his wife.'
EXEC add_BibleVerse @BibleId, 109025043, N'David had also married Ahinoam from Jezreel; the two of them became his wives.'
EXEC add_BibleVerse @BibleId, 109025044, N'(Now Saul had given his daughter Michal, David’s wife, to Paltiel son of Laish, who was from Gallim.)'
EXEC add_BibleVerse @BibleId, 109026001, N'The Ziphites came to Saul at Gibeah and said, “Isn’t David hiding on the hill of Hakilah near Jeshimon?”'
EXEC add_BibleVerse @BibleId, 109026002, N'So Saul arose and went down to the desert of Ziph, accompanied by three thousand select men of Israel, to look for David in the desert of Ziph.'
EXEC add_BibleVerse @BibleId, 109026003, N'Saul camped by the road on the hill of Hakilah near Jeshimon, but David was staying in the desert. When he realized that Saul had come to the desert to find him,'
EXEC add_BibleVerse @BibleId, 109026004, N'David sent scouts and verified that Saul had indeed arrived.'
EXEC add_BibleVerse @BibleId, 109026005, N'So David set out and went to the place where Saul was camped. David saw the place where Saul and Abner son of Ner, the general in command of his army, were sleeping. Now Saul was lying in the entrenchment, and the army was camped all around him.'
EXEC add_BibleVerse @BibleId, 109026006, N'David said to Ahimelech the Hittite and Abishai son of Zeruiah, Joab’s brother, “Who will go down with me to Saul in the camp?” Abishai replied, “I will go down with you.”'
EXEC add_BibleVerse @BibleId, 109026007, N'So David and Abishai approached the army at night and found Saul lying asleep in the entrenchment with his spear stuck in the ground by his head. Abner and the army were lying all around him.'
EXEC add_BibleVerse @BibleId, 109026008, N'Abishai said to David, “Today God has delivered your enemy into your hands. Now let me drive the spear right through him into the ground with one swift jab! A second jab won’t be necessary!”'
EXEC add_BibleVerse @BibleId, 109026009, N'But David said to Abishai, “Don’t kill him! Who can extend his hand against the Lord’s chosen one and remain guiltless?”'
EXEC add_BibleVerse @BibleId, 109026010, N'David went on to say, “As the Lord lives, the Lord himself will strike him down. Either his day will come and he will die, or he will go down into battle and be swept away.'
EXEC add_BibleVerse @BibleId, 109026011, N'But may the Lord prevent me from extending my hand against the Lord’s chosen one! Now take the spear by Saul’s head and the jug of water, and let’s get out of here!”'
EXEC add_BibleVerse @BibleId, 109026012, N'So David took the spear and the jug of water by Saul’s head, and they got out of there. No one saw them or was aware of their presence or woke up. All of them were asleep, for the Lord had caused a deep sleep to fall on them.'
EXEC add_BibleVerse @BibleId, 109026013, N'Then David crossed to the other side and stood on the top of the hill some distance away; there was a considerable distance between them.'
EXEC add_BibleVerse @BibleId, 109026014, N'David called to the army and to Abner son of Ner, “Won’t you answer, Abner?” Abner replied, “Who are you, that you have called to the king?”'
EXEC add_BibleVerse @BibleId, 109026015, N'David said to Abner, “Aren’t you a man? After all, who is like you in Israel? Why then haven’t you protected your lord the king? One of the soldiers came to kill your lord the king.'
EXEC add_BibleVerse @BibleId, 109026016, N'This failure on your part isn’t good! As surely as the Lord lives, you people who have not protected your lord, the Lord’s chosen one, are as good as dead! Now look where the king’s spear and the jug of water that was by his head are!”'
EXEC add_BibleVerse @BibleId, 109026017, N'When Saul recognized David’s voice, he said, “Is that your voice, my son David?” David replied, “Yes, it’s my voice, my lord the king.”'
EXEC add_BibleVerse @BibleId, 109026018, N'He went on to say, “Why is my lord chasing his servant? What have I done? What wrong have I done?'
EXEC add_BibleVerse @BibleId, 109026019, N'So let my lord the king now listen to the words of his servant. If the Lord has incited you against me, may he take delight in an offering. But if men have instigated this, may they be cursed before the Lord! For they have driven me away this day from being united with the Lord’s inheritance, saying, ‘Go on, serve other gods!’'
EXEC add_BibleVerse @BibleId, 109026020, N'Now don’t let my blood fall to the ground away from the Lord’s presence, for the king of Israel has gone out to look for a flea the way one looks for a partridge in the hill country.”'
EXEC add_BibleVerse @BibleId, 109026021, N'Saul replied, “I have sinned. Come back, my son David. I won’t harm you, for you treated my life with value this day. I have behaved foolishly and have made a very terrible mistake!”'
EXEC add_BibleVerse @BibleId, 109026022, N'David replied, “Here is the king’s spear! Let one of your servants cross over and get it.'
EXEC add_BibleVerse @BibleId, 109026023, N'The Lord rewards each man for his integrity and loyalty. Even though today the Lord delivered you into my hand, I was not willing to extend my hand against the Lord’s chosen one.'
EXEC add_BibleVerse @BibleId, 109026024, N'In the same way that I valued your life this day, may the Lord value my life and deliver me from all danger.”'
EXEC add_BibleVerse @BibleId, 109026025, N'Saul replied to David, “May you be rewarded, my son David! You will without question be successful!” So David went on his way, and Saul returned to his place.'
EXEC add_BibleVerse @BibleId, 109027001, N'David thought to himself, “One of these days I’m going to be swept away by the hand of Saul! There is nothing better for me than to escape to the land of the Philistines. Then Saul will despair of searching for me through all the territory of Israel and I will escape from his hand.”'
EXEC add_BibleVerse @BibleId, 109027002, N'So David left and crossed over to King Achish son of Maoch of Gath accompanied by his six hundred men.'
EXEC add_BibleVerse @BibleId, 109027003, N'David settled with Achish in Gath, along with his men and their families. David had with him his two wives, Ahinoam the Jezreelite and Abigail the Carmelite, Nabal’s widow.'
EXEC add_BibleVerse @BibleId, 109027004, N'When Saul learned that David had fled to Gath, he did not mount a new search for him.'
EXEC add_BibleVerse @BibleId, 109027005, N'David said to Achish, “If I have found favor with you, let me be given a place in one of the country towns so that I can live there. Why should your servant settle in the royal city with you?”'
EXEC add_BibleVerse @BibleId, 109027006, N'So Achish gave him Ziklag on that day. (For that reason Ziklag has belonged to the kings of Judah until this very day.)'
EXEC add_BibleVerse @BibleId, 109027007, N'The length of time that David lived in the Philistine countryside was a year and four months.'
EXEC add_BibleVerse @BibleId, 109027008, N'Then David and his men went up and raided the Geshurites, the Girzites, and the Amalekites. (They had been living in that land for a long time, from the approach to Shur as far as the land of Egypt.)'
EXEC add_BibleVerse @BibleId, 109027009, N'When David would attack a district, he would leave neither man nor woman alive. He would take sheep, cattle, donkeys, camels, and clothing and would then go back to Achish.'
EXEC add_BibleVerse @BibleId, 109027010, N'When Achish would ask, “Where did you raid today?” David would say, “The Negev of Judah” or “The Negev of Jeharmeel” or “The Negev of the Kenites.”'
EXEC add_BibleVerse @BibleId, 109027011, N'Neither man nor woman would David leave alive so as to bring them back to Gath. He was thinking, “This way they can’t tell on us, saying, ‘This is what David did.’” Such was his practice the entire time that he lived in the country of the Philistines.'
EXEC add_BibleVerse @BibleId, 109027012, N'So Achish trusted David, thinking to himself, “He is really hated among his own people in Israel! From now on he will be my servant.”'
EXEC add_BibleVerse @BibleId, 109028001, N'In those days the Philistines gathered their troops for war in order to fight Israel. Achish said to David, “You should fully understand that you and your men must go with me into the battle.”'
EXEC add_BibleVerse @BibleId, 109028002, N'David replied to Achish, “That being the case, you will come to know what your servant can do!” Achish said to David, “Then I will make you my bodyguard from now on.”'
EXEC add_BibleVerse @BibleId, 109028003, N'Now Samuel had died, and all Israel had lamented over him and had buried him in Ramah, his hometown. In the meantime Saul had removed the mediums and magicians from the land.'
EXEC add_BibleVerse @BibleId, 109028004, N'The Philistines assembled; they came and camped at Shunem. Saul mustered all Israel and camped at Gilboa.'
EXEC add_BibleVerse @BibleId, 109028005, N'When Saul saw the camp of the Philistines, he was absolutely terrified.'
EXEC add_BibleVerse @BibleId, 109028006, N'So Saul inquired of the Lord, but the Lord did not answer him – not by dreams nor by Urim nor by the prophets.'
EXEC add_BibleVerse @BibleId, 109028007, N'So Saul instructed his servants, “Find me a woman who is a medium, so that I may go to her and inquire of her.” His servants replied to him, “There is a woman who is a medium in Endor.”'
EXEC add_BibleVerse @BibleId, 109028008, N'So Saul disguised himself and put on other clothing and left, accompanied by two of his men. They came to the woman at night and said, “Use your ritual pit to conjure up for me the one I tell you.”'
EXEC add_BibleVerse @BibleId, 109028009, N'But the woman said to him, “Look, you are aware of what Saul has done; he has removed the mediums and magicians from the land! Why are you trapping me so you can put me to death?”'
EXEC add_BibleVerse @BibleId, 109028010, N'But Saul swore an oath to her by the Lord, “As surely as the Lord lives, you will not incur guilt in this matter!”'
EXEC add_BibleVerse @BibleId, 109028011, N'The woman replied, “Who is it that I should bring up for you?” He said, “Bring up for me Samuel.”'
EXEC add_BibleVerse @BibleId, 109028012, N'When the woman saw Samuel, she cried out loudly. The woman said to Saul, “Why have you deceived me? You are Saul!”'
EXEC add_BibleVerse @BibleId, 109028013, N'The king said to her, “Don’t be afraid! What have you seen?” The woman replied to Saul, “I have seen one like a god coming up from the ground!”'
EXEC add_BibleVerse @BibleId, 109028014, N'He said to her, “What about his appearance?” She said, “An old man is coming up! He is wrapped in a robe!” Then Saul realized it was Samuel, and he bowed his face toward the ground and kneeled down.'
EXEC add_BibleVerse @BibleId, 109028015, N'Samuel said to Saul, “Why have you disturbed me by bringing me up?” Saul replied, “I am terribly troubled! The Philistines are fighting against me and God has turned away from me. He does not answer me – not by the prophets nor by dreams. So I have called on you to tell me what I should do.”'
EXEC add_BibleVerse @BibleId, 109028016, N'Samuel said, “Why are you asking me, now that the Lord has turned away from you and has become your enemy?'
EXEC add_BibleVerse @BibleId, 109028017, N'The Lord has done exactly as I prophesied! The Lord has torn the kingdom from your hand and has given it to your neighbor David!'
EXEC add_BibleVerse @BibleId, 109028018, N'Since you did not obey the Lord and did not carry out his fierce anger against the Amalekites, the Lord has done this thing to you today.'
EXEC add_BibleVerse @BibleId, 109028019, N'The Lord will hand you and Israel over to the Philistines! Tomorrow both you and your sons will be with me. The Lord will also hand the army of Israel over to the Philistines!”'
EXEC add_BibleVerse @BibleId, 109028020, N'Saul quickly fell full length on the ground and was very afraid because of Samuel’s words. He was completely drained of energy, not having eaten anything all that day and night.'
EXEC add_BibleVerse @BibleId, 109028021, N'When the woman came to Saul and saw how terrified he was, she said to him, “Your servant has done what you asked. I took my life into my own hands and did what you told me.'
EXEC add_BibleVerse @BibleId, 109028022, N'Now it’s your turn to listen to your servant! Let me set before you a bit of bread so that you can eat. When you regain your strength, you can go on your way.”'
EXEC add_BibleVerse @BibleId, 109028023, N'But he refused, saying, “I won’t eat!” Both his servants and the woman urged him to eat, so he gave in. He got up from the ground and sat down on the bed.'
EXEC add_BibleVerse @BibleId, 109028024, N'Now the woman had a well-fed calf at her home that she quickly slaughtered. Taking some flour, she kneaded bread and baked it without leaven.'
EXEC add_BibleVerse @BibleId, 109028025, N'She brought it to Saul and his servants, and they ate. Then they arose and left that same night.'
EXEC add_BibleVerse @BibleId, 109029001, N'The Philistines assembled all their troops at Aphek, while Israel camped at the spring that is in Jezreel.'
EXEC add_BibleVerse @BibleId, 109029002, N'When the leaders of the Philistines were passing in review at the head of their units of hundreds and thousands, David and his men were passing in review in the rear with Achish.'
EXEC add_BibleVerse @BibleId, 109029003, N'The leaders of the Philistines asked, “What about these Hebrews?” Achish said to the leaders of the Philistines, “Isn’t this David, the servant of King Saul of Israel, who has been with me for quite some time? I have found no fault with him from the day of his defection until the present time!”'
EXEC add_BibleVerse @BibleId, 109029004, N'But the leaders of the Philistines became angry with him and said to him, “Send the man back! Let him return to the place that you assigned him! Don’t let him go down with us into the battle, for he might become our adversary in the battle. What better way to please his lord than with the heads of these men?'
EXEC add_BibleVerse @BibleId, 109029005, N'Isn’t this David, of whom they sang as they danced, ‘Saul has struck down his thousands, but David his tens of thousands’?”'
EXEC add_BibleVerse @BibleId, 109029006, N'So Achish summoned David and said to him, “As surely as the Lord lives, you are an honest man, and I am glad to have you serving with me in the army. I have found no fault with you from the day that you first came to me until the present time. But in the opinion of the leaders, you are not reliable.'
EXEC add_BibleVerse @BibleId, 109029007, N'So turn and leave in peace. You must not do anything that the leaders of the Philistines consider improper!”'
EXEC add_BibleVerse @BibleId, 109029008, N'But David said to Achish, “What have I done? What have you found in your servant from the day that I first came into your presence until the present time, that I shouldn’t go and fight the enemies of my lord the king?”'
EXEC add_BibleVerse @BibleId, 109029009, N'Achish replied to David, “I am convinced that you are as reliable as the angel of God! However, the leaders of the Philistines have said, ‘He must not go up with us in the battle.’'
EXEC add_BibleVerse @BibleId, 109029010, N'So get up early in the morning along with the servants of your lord who have come with you. When you get up early in the morning, as soon as it is light enough to see, leave.”'
EXEC add_BibleVerse @BibleId, 109029011, N'So David and his men got up early in the morning to return to the land of the Philistines, but the Philistines went up to Jezreel.'
EXEC add_BibleVerse @BibleId, 109030001, N'On the third day David and his men came to Ziklag. Now the Amalekites had raided the Negev and Ziklag. They attacked Ziklag and burned it.'
EXEC add_BibleVerse @BibleId, 109030002, N'They took captive the women who were in it, from the youngest to the oldest, but they did not kill anyone. They simply carried them off and went on their way.'
EXEC add_BibleVerse @BibleId, 109030003, N'When David and his men came to the city, they found it burned. Their wives, sons, and daughters had been taken captive.'
EXEC add_BibleVerse @BibleId, 109030004, N'Then David and the men who were with him wept loudly until they could weep no more.'
EXEC add_BibleVerse @BibleId, 109030005, N'David’s two wives had been taken captive – Ahinoam the Jezreelite and Abigail the Carmelite, Nabal’s widow.'
EXEC add_BibleVerse @BibleId, 109030006, N'David was very upset, for the men were thinking of stoning him; each man grieved bitterly over his sons and daughters. But David drew strength from the Lord his God.'
EXEC add_BibleVerse @BibleId, 109030007, N'Then David said to the priest Abiathar son of Ahimelech, “Bring me the ephod.” So Abiathar brought the ephod to David.'
EXEC add_BibleVerse @BibleId, 109030008, N'David inquired of the Lord, saying, “Should I pursue this raiding band? Will I overtake them?” He said to him, “Pursue, for you will certainly overtake them and carry out a rescue!”'
EXEC add_BibleVerse @BibleId, 109030009, N'So David went, accompanied by his six hundred men. When he came to the Wadi Besor, those who were in the rear stayed there.'
EXEC add_BibleVerse @BibleId, 109030010, N'David and four hundred men continued the pursuit, but two hundred men who were too exhausted to cross the Wadi Besor stayed there.'
EXEC add_BibleVerse @BibleId, 109030011, N'Then they found an Egyptian in the field and brought him to David. They gave him bread to eat and water to drink.'
EXEC add_BibleVerse @BibleId, 109030012, N'They gave him a slice of pressed figs and two bunches of raisins to eat. This greatly refreshed him, for he had not eaten food or drunk water for three days and three nights.'
EXEC add_BibleVerse @BibleId, 109030013, N'David said to him, “To whom do you belong, and where are you from?” The young man said, “I am an Egyptian, the servant of an Amalekite man. My master abandoned me when I was ill for three days.'
EXEC add_BibleVerse @BibleId, 109030014, N'We conducted a raid on the Negev of the Kerethites, on the area of Judah, and on the Negev of Caleb. We burned Ziklag.”'
EXEC add_BibleVerse @BibleId, 109030015, N'David said to him, “Can you take us down to this raiding party?” He said, “Swear to me by God that you will not kill me or hand me over to my master, and I will take you down to this raiding party.”'
EXEC add_BibleVerse @BibleId, 109030016, N'So he took David down, and they found them spread out over the land. They were eating and drinking and enjoying themselves because of all the loot they had taken from the land of the Philistines and from the land of Judah.'
EXEC add_BibleVerse @BibleId, 109030017, N'But David struck them down from twilight until the following evening. None of them escaped, with the exception of four hundred young men who got away on camels.'
EXEC add_BibleVerse @BibleId, 109030018, N'David retrieved everything the Amalekites had taken; he also rescued his two wives.'
EXEC add_BibleVerse @BibleId, 109030019, N'There was nothing missing, whether small or great. He retrieved sons and daughters, the plunder, and everything else they had taken. David brought everything back.'
EXEC add_BibleVerse @BibleId, 109030020, N'David took all the flocks and herds and drove them in front of the rest of the animals. People were saying, “This is David’s plunder!”'
EXEC add_BibleVerse @BibleId, 109030021, N'Then David approached the two hundred men who had been too exhausted to go with him, those whom they had left at the Wadi Besor. They went out to meet David and the people who were with him. When David approached the people, he asked how they were doing.'
EXEC add_BibleVerse @BibleId, 109030022, N'But all the evil and worthless men among those who had gone with David said, “Since they didn’t go with us, we won’t give them any of the loot we retrieved! They may take only their wives and children. Let them lead them away and be gone!”'
EXEC add_BibleVerse @BibleId, 109030023, N'But David said, “No! You shouldn’t do this, my brothers. Look at what the Lord has given us! He has protected us and has delivered into our hands the raiding party that came against us.'
EXEC add_BibleVerse @BibleId, 109030024, N'Who will listen to you in this matter? The portion of the one who went down into the battle will be the same as the portion of the one who remained with the equipment! Let their portions be the same!”'
EXEC add_BibleVerse @BibleId, 109030025, N'From that time onward it was a binding ordinance for Israel, right up to the present time.'
EXEC add_BibleVerse @BibleId, 109030026, N'When David came to Ziklag, he sent some of the plunder to the elders of Judah who were his friends, saying, “Here’s a gift for you from the looting of the Lord’s enemies!”'
EXEC add_BibleVerse @BibleId, 109030027, N'The gift was for those in the following locations: for those in Bethel, Ramoth Negev, and Jattir;'
EXEC add_BibleVerse @BibleId, 109030028, N'for those in Aroer, Siphmoth, Eshtemoa,'
EXEC add_BibleVerse @BibleId, 109030029, N'and Racal; for those in the cities of the Jerahmeelites and Kenites;'
EXEC add_BibleVerse @BibleId, 109030030, N'for those in Hormah, Bor Ashan, Athach,'
EXEC add_BibleVerse @BibleId, 109030031, N'and Hebron; and for those in whatever other places David and his men had traveled.'
EXEC add_BibleVerse @BibleId, 109031001, N'Now the Philistines were fighting against Israel. The men of Israel fled from the Philistines and many of them fell dead on Mount Gilboa.'
EXEC add_BibleVerse @BibleId, 109031002, N'The Philistines stayed right on the heels of Saul and his sons. They struck down Saul’s sons Jonathan, Abinadab, and Malki-Shua.'
EXEC add_BibleVerse @BibleId, 109031003, N'Saul himself was in the thick of the battle; the archers spotted him and wounded him severely.'
EXEC add_BibleVerse @BibleId, 109031004, N'Saul said to his armor bearer, “Draw your sword and stab me with it! Otherwise these uncircumcised people will come, stab me, and torture me.” But his armor bearer refused to do it, because he was very afraid. So Saul took his sword and fell on it.'
EXEC add_BibleVerse @BibleId, 109031005, N'When his armor bearer saw that Saul was dead, he also fell on his own sword and died with him.'
EXEC add_BibleVerse @BibleId, 109031006, N'So Saul, his three sons, his armor bearer, and all his men died together that day.'
EXEC add_BibleVerse @BibleId, 109031007, N'When the men of Israel who were in the valley and across the Jordan saw that the men of Israel had fled and that Saul and his sons were dead, they abandoned the cities and fled. The Philistines came and occupied them.'
EXEC add_BibleVerse @BibleId, 109031008, N'The next day, when the Philistines came to strip loot from the corpses, they discovered Saul and his three sons lying dead on Mount Gilboa.'
EXEC add_BibleVerse @BibleId, 109031009, N'They cut off Saul’s head and stripped him of his armor. They sent messengers to announce the news in the temple of their idols and among their people throughout the surrounding land of the Philistines.'
EXEC add_BibleVerse @BibleId, 109031010, N'They placed Saul’s armor in the temple of the Ashtoreths and hung his corpse on the city wall of Beth Shan.'
EXEC add_BibleVerse @BibleId, 109031011, N'When the residents of Jabesh Gilead heard what the Philistines had done to Saul,'
EXEC add_BibleVerse @BibleId, 109031012, N'all their warriors set out and traveled throughout the night. They took Saul’s corpse and the corpses of his sons from the city wall of Beth Shan and went to Jabesh, where they burned them.'
EXEC add_BibleVerse @BibleId, 109031013, N'They took the bones and buried them under the tamarisk tree at Jabesh; then they fasted for seven days.'
EXEC add_BibleVerse @BibleId, 110001001, N'After the death of Saul, when David had returned from defeating the Amalekites, he stayed at Ziklag for two days.'
EXEC add_BibleVerse @BibleId, 110001002, N'On the third day a man arrived from the camp of Saul with his clothes torn and dirt on his head. When he approached David, the man threw himself to the ground.'
EXEC add_BibleVerse @BibleId, 110001003, N'David asked him, “Where are you coming from?” He replied, “I have escaped from the camp of Israel.”'
EXEC add_BibleVerse @BibleId, 110001004, N'David inquired, “How were things going? Tell me!” He replied, “The people fled from the battle and many of them fell dead. Even Saul and his son Jonathan are dead!”'
EXEC add_BibleVerse @BibleId, 110001005, N'David said to the young man who was telling him this, “How do you know that Saul and his son Jonathan are dead?”'
EXEC add_BibleVerse @BibleId, 110001006, N'The young man who was telling him this said, “I just happened to be on Mount Gilboa and came across Saul leaning on his spear for support. The chariots and leaders of the horsemen were in hot pursuit of him.'
EXEC add_BibleVerse @BibleId, 110001007, N'When he turned around and saw me, he called out to me. I answered, ‘Here I am!’'
EXEC add_BibleVerse @BibleId, 110001008, N'He asked me, ‘Who are you?’ I told him, ‘I’m an Amalekite.’'
EXEC add_BibleVerse @BibleId, 110001009, N'He said to me, ‘Stand over me and finish me off! I’m very dizzy, even though I’m still alive.’'
EXEC add_BibleVerse @BibleId, 110001010, N'So I stood over him and put him to death, since I knew that he couldn’t live in such a condition. Then I took the crown which was on his head and the bracelet which was on his arm. I have brought them here to my lord.”'
EXEC add_BibleVerse @BibleId, 110001011, N'David then grabbed his own clothes and tore them, as did all the men who were with him.'
EXEC add_BibleVerse @BibleId, 110001012, N'They lamented and wept and fasted until evening because Saul, his son Jonathan, the Lord’s people, and the house of Israel had fallen by the sword.'
EXEC add_BibleVerse @BibleId, 110001013, N'David said to the young man who told this to him, “Where are you from?” He replied, “I am an Amalekite, the son of a resident foreigner.”'
EXEC add_BibleVerse @BibleId, 110001014, N'David replied to him, “How is it that you were not afraid to reach out your hand to destroy the Lord’s anointed?”'
EXEC add_BibleVerse @BibleId, 110001015, N'Then David called one of the soldiers and said, “Come here and strike him down!” So he struck him down, and he died.'
EXEC add_BibleVerse @BibleId, 110001016, N'David said to him, “Your blood be on your own head! Your own mouth has testified against you, saying ‘I have put the Lord’s anointed to death.’”'
EXEC add_BibleVerse @BibleId, 110001017, N'Then David chanted this lament over Saul and his son Jonathan.'
EXEC add_BibleVerse @BibleId, 110001018, N'(He gave instructions that the people of Judah should be taught “The Bow.” Indeed, it is written down in the Book of Yashar.)'
EXEC add_BibleVerse @BibleId, 110001019, N'The beauty of Israel lies slain on your high places! How the mighty have fallen!'
EXEC add_BibleVerse @BibleId, 110001020, N'Don’t report it in Gath, don’t spread the news in the streets of Ashkelon, or the daughters of the Philistines will rejoice, the daughters of the uncircumcised will celebrate!'
EXEC add_BibleVerse @BibleId, 110001021, N'O mountains of Gilboa, may there be no dew or rain on you, nor fields of grain offerings! For it was there that the shield of warriors was defiled; the shield of Saul lies neglected without oil.'
EXEC add_BibleVerse @BibleId, 110001022, N'From the blood of the slain, from the fat of warriors, the bow of Jonathan was not turned away. The sword of Saul never returned empty.'
EXEC add_BibleVerse @BibleId, 110001023, N'Saul and Jonathan were greatly loved during their lives, and not even in their deaths were they separated. They were swifter than eagles, stronger than lions.'
EXEC add_BibleVerse @BibleId, 110001024, N'O daughters of Israel, weep over Saul, who clothed you in scarlet as well as jewelry, who put gold jewelry on your clothes.'
EXEC add_BibleVerse @BibleId, 110001025, N'How the warriors have fallen in the midst of battle! Jonathan lies slain on your high places!'
EXEC add_BibleVerse @BibleId, 110001026, N'I grieve over you, my brother Jonathan! You were very dear to me. Your love was more special to me than the love of women.'
EXEC add_BibleVerse @BibleId, 110001027, N'How the warriors have fallen! The weapons of war are destroyed!'
EXEC add_BibleVerse @BibleId, 110002001, N'Afterward David inquired of the Lord, “Should I go up to one of the cities of Judah?” The Lord told him, “Go up.” David asked, “Where should I go?” The Lord replied, “To Hebron.”'
EXEC add_BibleVerse @BibleId, 110002002, N'So David went up, along with his two wives, Ahinoam the Jezreelite and Abigail, formerly the wife of Nabal the Carmelite.'
EXEC add_BibleVerse @BibleId, 110002003, N'David also brought along the men who were with him, each with his family. They settled in the cities of Hebron.'
EXEC add_BibleVerse @BibleId, 110002004, N'The men of Judah came and there they anointed David as king over the people of Judah. David was told, “The people of Jabesh Gilead are the ones who buried Saul.”'
EXEC add_BibleVerse @BibleId, 110002005, N'So David sent messengers to the people of Jabesh Gilead and told them, “May you be blessed by the Lord because you have shown this kindness to your lord Saul by burying him.'
EXEC add_BibleVerse @BibleId, 110002006, N'Now may the Lord show you true kindness! I also will reward you, because you have done this deed.'
EXEC add_BibleVerse @BibleId, 110002007, N'Now be courageous and prove to be valiant warriors, for your lord Saul is dead. The people of Judah have anointed me as king over them.”'
EXEC add_BibleVerse @BibleId, 110002008, N'Now Abner son of Ner, the general in command of Saul’s army, had taken Saul’s son Ish-bosheth and had brought him to Mahanaim.'
EXEC add_BibleVerse @BibleId, 110002009, N'He appointed him king over Gilead, the Geshurites, Jezreel, Ephraim, Benjamin, and all Israel.'
EXEC add_BibleVerse @BibleId, 110002010, N'Ish-bosheth son of Saul was forty years old when he began to rule over Israel. He ruled two years. However, the people of Judah followed David.'
EXEC add_BibleVerse @BibleId, 110002011, N'David was king in Hebron over the people of Judah for seven and a half years.'
EXEC add_BibleVerse @BibleId, 110002012, N'Then Abner son of Ner and the servants of Ish-bosheth son of Saul went out from Mahanaim to Gibeon.'
EXEC add_BibleVerse @BibleId, 110002013, N'Joab son of Zeruiah and the servants of David also went out and confronted them at the pool of Gibeon. One group stationed themselves on one side of the pool, and the other group on the other side of the pool.'
EXEC add_BibleVerse @BibleId, 110002014, N'Abner said to Joab, “Let the soldiers get up and fight before us.” Joab said, “So be it!”'
EXEC add_BibleVerse @BibleId, 110002015, N'So they got up and crossed over by number: twelve belonging to Benjamin and to Ish-bosheth son of Saul, and twelve from the servants of David.'
EXEC add_BibleVerse @BibleId, 110002016, N'As they grappled with one another, each one stabbed his opponent with his sword and they fell dead together. So that place is called the Field of Flints; it is in Gibeon.'
EXEC add_BibleVerse @BibleId, 110002017, N'Now the battle was very severe that day; Abner and the men of Israel were overcome by David’s soldiers.'
EXEC add_BibleVerse @BibleId, 110002018, N'The three sons of Zeruiah were there – Joab, Abishai, and Asahel. (Now Asahel was as quick on his feet as one of the gazelles in the field.)'
EXEC add_BibleVerse @BibleId, 110002019, N'Asahel chased Abner, without turning to the right or to the left as he followed Abner.'
EXEC add_BibleVerse @BibleId, 110002020, N'Then Abner turned and asked, “Is that you, Asahel?” He replied, “Yes it is!”'
EXEC add_BibleVerse @BibleId, 110002021, N'Abner said to him, “Turn aside to your right or to your left. Capture one of the soldiers and take his equipment for yourself!” But Asahel was not willing to turn aside from following him.'
EXEC add_BibleVerse @BibleId, 110002022, N'So Abner spoke again to Asahel, “Turn aside from following me! I do not want to strike you to the ground. How then could I show my face in the presence of Joab your brother?”'
EXEC add_BibleVerse @BibleId, 110002023, N'But Asahel refused to turn aside. So Abner struck him in the abdomen with the back end of his spear. The spear came out his back; Asahel collapsed on the spot and died there right before Abner. Everyone who now comes to the place where Asahel fell dead pauses in respect.'
EXEC add_BibleVerse @BibleId, 110002024, N'So Joab and Abishai chased Abner. At sunset they came to the hill of Ammah near Giah on the way to the wilderness of Gibeon.'
EXEC add_BibleVerse @BibleId, 110002025, N'The Benjaminites formed their ranks behind Abner and were like a single army, standing at the top of a certain hill.'
EXEC add_BibleVerse @BibleId, 110002026, N'Then Abner called out to Joab, “Must the sword devour forever? Don’t you realize that this will turn bitter in the end? When will you tell the people to turn aside from pursuing their brothers?”'
EXEC add_BibleVerse @BibleId, 110002027, N'Joab replied, “As surely as God lives, if you had not said this, it would have been morning before the people would have abandoned pursuit of their brothers!”'
EXEC add_BibleVerse @BibleId, 110002028, N'Then Joab blew the ram’s horn and all the people stopped in their tracks. They stopped chasing Israel and ceased fighting.'
EXEC add_BibleVerse @BibleId, 110002029, N'Abner and his men went through the Arabah all that night. They crossed the Jordan River and went through the whole region of Bitron and came to Mahanaim.'
EXEC add_BibleVerse @BibleId, 110002030, N'Now Joab returned from chasing Abner and assembled all the people. Nineteen of David’s soldiers were missing, in addition to Asahel.'
EXEC add_BibleVerse @BibleId, 110002031, N'But David’s soldiers had slaughtered the Benjaminites and Abner’s men – in all, 360 men had died!'
EXEC add_BibleVerse @BibleId, 110002032, N'They took Asahel’s body and buried him in his father’s tomb at Bethlehem. Joab and his men then traveled all that night and reached Hebron by dawn.'
EXEC add_BibleVerse @BibleId, 110003001, N'However, the war was prolonged between the house of Saul and the house of David. David was becoming steadily stronger, while the house of Saul was becoming increasingly weaker.'
EXEC add_BibleVerse @BibleId, 110003002, N'Now sons were born to David in Hebron. His firstborn was Amnon, born to Ahinoam the Jezreelite.'
EXEC add_BibleVerse @BibleId, 110003003, N'His second son was Kileab, born to Abigail the widow of Nabal the Carmelite. His third son was Absalom, the son of Maacah daughter of King Talmai of Geshur.'
EXEC add_BibleVerse @BibleId, 110003004, N'His fourth son was Adonijah, the son of Haggith. His fifth son was Shephatiah, the son of Abitail.'
EXEC add_BibleVerse @BibleId, 110003005, N'His sixth son was Ithream, born to David’s wife Eglah. These sons were all born to David in Hebron.'
EXEC add_BibleVerse @BibleId, 110003006, N'As the war continued between the house of Saul and the house of David, Abner was becoming more influential in the house of Saul.'
EXEC add_BibleVerse @BibleId, 110003007, N'Now Saul had a concubine named Rizpah daughter of Aiah. Ish-bosheth said to Abner, “Why did you have sexual relations with my father’s concubine?”'
EXEC add_BibleVerse @BibleId, 110003008, N'These words of Ish-bosheth really angered Abner and he said, “Am I the head of a dog that belongs to Judah? This very day I am demonstrating loyalty to the house of Saul your father and to his relatives and his friends! I have not betrayed you into the hand of David. Yet you have accused me of sinning with this woman today!'
EXEC add_BibleVerse @BibleId, 110003009, N'God will severely judge Abner if I do not do for David exactly what the Lord has promised him,'
EXEC add_BibleVerse @BibleId, 110003010, N'namely, to transfer the kingdom from the house of Saul and to establish the throne of David over Israel and over Judah all the way from Dan to Beer Sheba!”'
EXEC add_BibleVerse @BibleId, 110003011, N'Ish-bosheth was unable to answer Abner with even a single word because he was afraid of him.'
EXEC add_BibleVerse @BibleId, 110003012, N'Then Abner sent messengers to David saying, “To whom does the land belong? Make an agreement with me, and I will do whatever I can to cause all Israel to turn to you.”'
EXEC add_BibleVerse @BibleId, 110003013, N'So David said, “Good! I will make an agreement with you. I ask only one thing from you. You will not see my face unless you bring Saul’s daughter Michal when you come to visit me.”'
EXEC add_BibleVerse @BibleId, 110003014, N'David sent messengers to Ish-bosheth son of Saul with this demand: “Give me my wife Michal whom I acquired for a hundred Philistine foreskins.”'
EXEC add_BibleVerse @BibleId, 110003015, N'So Ish-bosheth took her from her husband Paltiel son of Laish.'
EXEC add_BibleVerse @BibleId, 110003016, N'Her husband went along behind her, weeping all the way to Bahurim. Finally Abner said to him, “Go back!” So he returned home.'
EXEC add_BibleVerse @BibleId, 110003017, N'Abner advised the elders of Israel, “Previously you were wanting David to be your king.'
EXEC add_BibleVerse @BibleId, 110003018, N'Act now! For the Lord has said to David, ‘By the hand of my servant David I will save my people Israel from the Philistines and from all their enemies.’”'
EXEC add_BibleVerse @BibleId, 110003019, N'Then Abner spoke privately with the Benjaminites. Abner also went to Hebron to inform David privately of all that Israel and the entire house of Benjamin had agreed to.'
EXEC add_BibleVerse @BibleId, 110003020, N'When Abner, accompanied by twenty men, came to David in Hebron, David prepared a banquet for Abner and the men who were with him.'
EXEC add_BibleVerse @BibleId, 110003021, N'Abner said to David, “Let me leave so that I may go and gather all Israel to my lord the king so that they may make an agreement with you. Then you will rule over all that you desire.” So David sent Abner away, and he left in peace.'
EXEC add_BibleVerse @BibleId, 110003022, N'Now David’s soldiers and Joab were coming back from a raid, bringing a great deal of plunder with them. Abner was no longer with David in Hebron, for David had sent him away and he had left in peace.'
EXEC add_BibleVerse @BibleId, 110003023, N'When Joab and all the army that was with him arrived, Joab was told: “Abner the son of Ner came to the king; he sent him away, and he left in peace!”'
EXEC add_BibleVerse @BibleId, 110003024, N'So Joab went to the king and said, “What have you done? Abner has come to you! Why would you send him away? Now he’s gone on his way!'
EXEC add_BibleVerse @BibleId, 110003025, N'You know Abner the son of Ner! Surely he came here to spy on you and to determine when you leave and when you return and to discover everything that you are doing!”'
EXEC add_BibleVerse @BibleId, 110003026, N'Then Joab left David and sent messengers after Abner. They brought him back from the well of Sirah. (But David was not aware of it.)'
EXEC add_BibleVerse @BibleId, 110003027, N'When Abner returned to Hebron, Joab took him aside at the gate as if to speak privately with him. Joab then stabbed him in the abdomen and killed him, avenging the shed blood of his brother Asahel.'
EXEC add_BibleVerse @BibleId, 110003028, N'When David later heard about this, he said, “I and my kingdom are forever innocent before the Lord of the shed blood of Abner son of Ner!'
EXEC add_BibleVerse @BibleId, 110003029, N'May his blood whirl over the head of Joab and the entire house of his father! May the males of Joab’s house never cease to have someone with a running sore or a skin disease or one who works at the spindle or one who falls by the sword or one who lacks food!”'
EXEC add_BibleVerse @BibleId, 110003030, N'So Joab and his brother Abishai killed Abner, because he had killed their brother Asahel in Gibeon during the battle.'
EXEC add_BibleVerse @BibleId, 110003031, N'David instructed Joab and all the people who were with him, “Tear your clothes! Put on sackcloth! Lament before Abner!” Now King David followed behind the funeral bier.'
EXEC add_BibleVerse @BibleId, 110003032, N'So they buried Abner in Hebron. The king cried loudly over Abner’s grave and all the people wept too.'
EXEC add_BibleVerse @BibleId, 110003033, N'The king chanted the following lament for Abner: “Should Abner have died like a fool?'
EXEC add_BibleVerse @BibleId, 110003034, N'Your hands were not bound, and your feet were not put into irons. You fell the way one falls before criminals.” All the people wept over him again.'
EXEC add_BibleVerse @BibleId, 110003035, N'Then all the people came and encouraged David to eat food while it was still day. But David took an oath saying, “God will punish me severely if I taste bread or anything whatsoever before the sun sets!”'
EXEC add_BibleVerse @BibleId, 110003036, N'All the people noticed this and it pleased them. In fact, everything the king did pleased all the people.'
EXEC add_BibleVerse @BibleId, 110003037, N'All the people and all Israel realized on that day that the killing of Abner son of Ner was not done at the king’s instigation.'
EXEC add_BibleVerse @BibleId, 110003038, N'Then the king said to his servants, “Do you not realize that a great leader has fallen this day in Israel?'
EXEC add_BibleVerse @BibleId, 110003039, N'Today I am weak, even though I am anointed as king. These men, the sons of Zeruiah, are too much for me to bear! May the Lord punish appropriately the one who has done this evil thing!”'
EXEC add_BibleVerse @BibleId, 110004001, N'When Ish-bosheth the son of Saul heard that Abner had died in Hebron, he was very disheartened, and all Israel was afraid.'
EXEC add_BibleVerse @BibleId, 110004002, N'Now Saul’s son had two men who were in charge of raiding units; one was named Baanah and the other Recab. They were sons of Rimmon the Beerothite, who was a Benjaminite. (Beeroth is regarded as belonging to Benjamin,'
EXEC add_BibleVerse @BibleId, 110004003, N'for the Beerothites fled to Gittaim and have remained there as resident foreigners until the present time.)'
EXEC add_BibleVerse @BibleId, 110004004, N'Now Saul’s son Jonathan had a son who was crippled in both feet. He was five years old when the news about Saul and Jonathan arrived from Jezreel. His nurse picked him up and fled, but in her haste to get away, he fell and was injured. Mephibosheth was his name.'
EXEC add_BibleVerse @BibleId, 110004005, N'Now the sons of Rimmon the Beerothite – Recab and Baanah – went at the hottest part of the day to the home of Ish-bosheth, as he was enjoying his midday rest.'
EXEC add_BibleVerse @BibleId, 110004006, N'They entered the house under the pretense of getting wheat and mortally wounded him in the stomach. Then Recab and his brother Baanah escaped.'
EXEC add_BibleVerse @BibleId, 110004007, N'They had entered the house while Ish-bosheth was resting on his bed in his bedroom. They mortally wounded him and then cut off his head. Taking his head, they traveled on the way of the Arabah all that night.'
EXEC add_BibleVerse @BibleId, 110004008, N'They brought the head of Ish-bosheth to David in Hebron, saying to the king, “Look! The head of Ish-bosheth son of Saul, your enemy who sought your life! The Lord has granted vengeance to my lord the king this day against Saul and his descendants!”'
EXEC add_BibleVerse @BibleId, 110004009, N'David replied to Recab and his brother Baanah, the sons of Rimmon the Beerothite, “As surely as the Lord lives, who has delivered my life from all adversity,'
EXEC add_BibleVerse @BibleId, 110004010, N'when someone told me that Saul was dead – even though he thought he was bringing good news – I seized him and killed him in Ziklag. That was the good news I gave to him!'
EXEC add_BibleVerse @BibleId, 110004011, N'Surely when wicked men have killed an innocent man as he slept in his own house, should I not now require his blood from your hands and remove you from the earth?”'
EXEC add_BibleVerse @BibleId, 110004012, N'So David issued orders to the soldiers and they put them to death. Then they cut off their hands and feet and hung them near the pool in Hebron. But they took the head of Ish-bosheth and buried it in the tomb of Abner in Hebron.'
EXEC add_BibleVerse @BibleId, 110005001, N'All the tribes of Israel came to David at Hebron saying, “Look, we are your very flesh and blood!'
EXEC add_BibleVerse @BibleId, 110005002, N'In the past, when Saul was our king, you were the real leader in Israel. The Lord said to you, ‘You will shepherd my people Israel; you will rule over Israel.’”'
EXEC add_BibleVerse @BibleId, 110005003, N'When all the leaders of Israel came to the king at Hebron, King David made an agreement with them in Hebron before the Lord. They designated David as king over Israel.'
EXEC add_BibleVerse @BibleId, 110005004, N'David was thirty years old when he began to reign and he reigned for forty years.'
EXEC add_BibleVerse @BibleId, 110005005, N'In Hebron he reigned over Judah for seven years and six months, and in Jerusalem he reigned for thirty-three years over all Israel and Judah.'
EXEC add_BibleVerse @BibleId, 110005006, N'Then the king and his men advanced to Jerusalem against the Jebusites who lived in the land. The Jebusites said to David, “You cannot invade this place! Even the blind and the lame will turn you back, saying, ‘David cannot invade this place!’”'
EXEC add_BibleVerse @BibleId, 110005007, N'But David captured the fortress of Zion (that is, the city of David).'
EXEC add_BibleVerse @BibleId, 110005008, N'David said on that day, “Whoever attacks the Jebusites must approach the ‘lame’ and the ‘blind’ who are David’s enemies by going through the water tunnel.” For this reason it is said, “The blind and the lame cannot enter the palace.”'
EXEC add_BibleVerse @BibleId, 110005009, N'So David lived in the fortress and called it the City of David. David built all around it, from the terrace inwards.'
EXEC add_BibleVerse @BibleId, 110005010, N'David’s power grew steadily, for the Lord God who commands armies was with him.'
EXEC add_BibleVerse @BibleId, 110005011, N'King Hiram of Tyre sent messengers to David, along with cedar logs, carpenters, and stonemasons. They built a palace for David.'
EXEC add_BibleVerse @BibleId, 110005012, N'David realized that the Lord had established him as king over Israel and that he had elevated his kingdom for the sake of his people Israel.'
EXEC add_BibleVerse @BibleId, 110005013, N'David married more concubines and wives from Jerusalem after he arrived from Hebron. Even more sons and daughters were born to David.'
EXEC add_BibleVerse @BibleId, 110005014, N'These are the names of children born to him in Jerusalem: Shammua, Shobab, Nathan, Solomon,'
EXEC add_BibleVerse @BibleId, 110005015, N'Ibhar, Elishua, Nepheg, Japhia,'
EXEC add_BibleVerse @BibleId, 110005016, N'Elishama, Eliada, and Eliphelet.'
EXEC add_BibleVerse @BibleId, 110005017, N'When the Philistines heard that David had been designated king over Israel, they all went up to search for David. When David heard about it, he went down to the fortress.'
EXEC add_BibleVerse @BibleId, 110005018, N'Now the Philistines had arrived and spread out in the valley of Rephaim.'
EXEC add_BibleVerse @BibleId, 110005019, N'So David asked the Lord, “Should I march up against the Philistines? Will you hand them over to me?” The Lord said to David, “March up, for I will indeed hand the Philistines over to you.”'
EXEC add_BibleVerse @BibleId, 110005020, N'So David marched against Baal Perazim and defeated them there. Then he said, “The Lord has burst out against my enemies like water bursts out.” So he called the name of that place Baal Perazim.'
EXEC add_BibleVerse @BibleId, 110005021, N'The Philistines abandoned their idols there, and David and his men picked them up.'
EXEC add_BibleVerse @BibleId, 110005022, N'The Philistines again came up and spread out in the valley of Rephaim.'
EXEC add_BibleVerse @BibleId, 110005023, N'So David asked the Lord what he should do. This time the Lord said to him, “Don’t march straight up. Instead, circle around behind them and come against them opposite the trees.'
EXEC add_BibleVerse @BibleId, 110005024, N'When you hear the sound of marching in the tops of the trees, act decisively. For at that moment the Lord is going before you to strike down the army of the Philistines.”'
EXEC add_BibleVerse @BibleId, 110005025, N'David did just as the Lord commanded him, and he struck down the Philistines from Gibeon all the way to Gezer.'
EXEC add_BibleVerse @BibleId, 110006001, N'David again assembled all the best men in Israel, thirty thousand in number.'
EXEC add_BibleVerse @BibleId, 110006002, N'David and all the men who were with him traveled to Baalah in Judah to bring up from there the ark of God which is called by the name of the Lord of hosts, who sits enthroned between the cherubim that are on it.'
EXEC add_BibleVerse @BibleId, 110006003, N'They loaded the ark of God on a new cart and carried it from the house of Abinadab, which was on the hill. Uzzah and Ahio, the sons of Abinadab, were guiding the new cart.'
EXEC add_BibleVerse @BibleId, 110006004, N'They brought it with the ark of God up from the house of Abinadab on the hill. Ahio was walking in front of the ark,'
EXEC add_BibleVerse @BibleId, 110006005, N'while David and all Israel were energetically celebrating before the Lord, singing and playing various stringed instruments, tambourines, rattles, and cymbals.'
EXEC add_BibleVerse @BibleId, 110006006, N'When they arrived at the threshing floor of Nacon, Uzzah reached out and grabbed hold of the ark of God, because the oxen stumbled.'
EXEC add_BibleVerse @BibleId, 110006007, N'The Lord was so furious with Uzzah, he killed him on the spot for his negligence. He died right there beside the ark of God.'
EXEC add_BibleVerse @BibleId, 110006008, N'David was angry because the Lord attacked Uzzah; so he called that place Perez Uzzah, which remains its name to this very day.'
EXEC add_BibleVerse @BibleId, 110006009, N'David was afraid of the Lord that day and said, “How will the ark of the Lord ever come to me?”'
EXEC add_BibleVerse @BibleId, 110006010, N'So David was no longer willing to bring the ark of the Lord to be with him in the City of David. David left it in the house of Obed-Edom the Gittite.'
EXEC add_BibleVerse @BibleId, 110006011, N'The ark of the Lord remained in the house of Obed-Edom the Gittite for three months. The Lord blessed Obed-Edom and all his family.'
EXEC add_BibleVerse @BibleId, 110006012, N'David was told, “The Lord has blessed the family of Obed-Edom and everything he owns because of the ark of God.” So David went and joyfully brought the ark of God from the house of Obed-Edom to the City of David.'
EXEC add_BibleVerse @BibleId, 110006013, N'Those who carried the ark of the Lord took six steps and then David sacrificed an ox and a fatling calf.'
EXEC add_BibleVerse @BibleId, 110006014, N'Now David, wearing a linen ephod, was dancing with all his strength before the Lord.'
EXEC add_BibleVerse @BibleId, 110006015, N'David and all Israel were bringing up the ark of the Lord, shouting and blowing trumpets.'
EXEC add_BibleVerse @BibleId, 110006016, N'As the ark of the Lord entered the City of David, Saul’s daughter Michal looked out the window. When she saw King David leaping and dancing before the Lord, she despised him.'
EXEC add_BibleVerse @BibleId, 110006017, N'They brought the ark of the Lord and put it in its place in the middle of the tent that David had pitched for it. Then David offered burnt sacrifices and peace offerings before the Lord.'
EXEC add_BibleVerse @BibleId, 110006018, N'When David finished offering the burnt sacrifices and peace offerings, he pronounced a blessing over the people in the name of the Lord of hosts.'
EXEC add_BibleVerse @BibleId, 110006019, N'He then handed out to each member of the entire assembly of Israel, both men and women, a portion of bread, a date cake, and a raisin cake. Then all the people went home.'
EXEC add_BibleVerse @BibleId, 110006020, N'When David went home to pronounce a blessing on his own house, Michal, Saul’s daughter, came out to meet him. She said, “How the king of Israel has distinguished himself this day! He has exposed himself today before his servants’ slave girls the way a vulgar fool might do!”'
EXEC add_BibleVerse @BibleId, 110006021, N'David replied to Michal, “It was before the Lord! I was celebrating before the Lord, who chose me over your father and his entire family and appointed me as leader over the Lord’s people Israel.'
EXEC add_BibleVerse @BibleId, 110006022, N'I am willing to shame and humiliate myself even more than this! But with the slave girls whom you mentioned let me be distinguished!”'
EXEC add_BibleVerse @BibleId, 110006023, N'Now Michal, Saul’s daughter, had no children to the day of her death.'
EXEC add_BibleVerse @BibleId, 110007001, N'The king settled into his palace, for the Lord gave him relief from all his enemies on all sides.'
EXEC add_BibleVerse @BibleId, 110007002, N'The king said to Nathan the prophet, “Look! I am living in a palace made from cedar, while the ark of God sits in the middle of a tent.”'
EXEC add_BibleVerse @BibleId, 110007003, N'Nathan replied to the king, “You should go and do whatever you have in mind, for the Lord is with you.”'
EXEC add_BibleVerse @BibleId, 110007004, N'That night the Lord told Nathan,'
EXEC add_BibleVerse @BibleId, 110007005, N'“Go, tell my servant David: ‘This is what the Lord says: Do you really intend to build a house for me to live in?'
EXEC add_BibleVerse @BibleId, 110007006, N'I have not lived in a house from the time I brought the Israelites up from Egypt to the present day. Instead, I was traveling with them and living in a tent.'
EXEC add_BibleVerse @BibleId, 110007007, N'Wherever I moved among all the Israelites, I did not say to any of the leaders whom I appointed to care for my people Israel, “Why have you not built me a house made from cedar?”’'
EXEC add_BibleVerse @BibleId, 110007008, N'“So now, say this to my servant David: ‘This is what the Lord of hosts says: I took you from the pasture and from your work as a shepherd to make you leader of my people Israel.'
EXEC add_BibleVerse @BibleId, 110007009, N'I was with you wherever you went, and I defeated all your enemies before you. Now I will make you as famous as the great men of the earth.'
EXEC add_BibleVerse @BibleId, 110007010, N'I will establish a place for my people Israel and settle them there; they will live there and not be disturbed any more. Violent men will not oppress them again, as they did in the beginning'
EXEC add_BibleVerse @BibleId, 110007011, N'and during the time when I appointed judges to lead my people Israel. Instead, I will give you relief from all your enemies. The Lord declares to you that he himself will build a dynastic house for you.'
EXEC add_BibleVerse @BibleId, 110007012, N'When the time comes for you to die, I will raise up your descendant, one of your own sons, to succeed you, and I will establish his kingdom.'
EXEC add_BibleVerse @BibleId, 110007013, N'He will build a house for my name, and I will make his dynasty permanent.'
EXEC add_BibleVerse @BibleId, 110007014, N'I will become his father and he will become my son. When he sins, I will correct him with the rod of men and with wounds inflicted by human beings.'
EXEC add_BibleVerse @BibleId, 110007015, N'But my loyal love will not be removed from him as I removed it from Saul, whom I removed from before you.'
EXEC add_BibleVerse @BibleId, 110007016, N'Your house and your kingdom will stand before me permanently; your dynasty will be permanent.’”'
EXEC add_BibleVerse @BibleId, 110007017, N'Nathan told David all these words that were revealed to him.'
EXEC add_BibleVerse @BibleId, 110007018, N'King David went in, sat before the Lord, and said, “Who am I, O Lord God, and what is my family, that you should have brought me to this point?'
EXEC add_BibleVerse @BibleId, 110007019, N'And you didn’t stop there, O Lord God! You have also spoken about the future of your servant’s family. Is this your usual way of dealing with men, O Lord God?'
EXEC add_BibleVerse @BibleId, 110007020, N'What more can David say to you? You have given your servant special recognition, O Lord God!'
EXEC add_BibleVerse @BibleId, 110007021, N'For the sake of your promise and according to your purpose you have done this great thing in order to reveal it to your servant.'
EXEC add_BibleVerse @BibleId, 110007022, N'Therefore you are great, O Lord God, for there is none like you! There is no God besides you! What we have heard is true!'
EXEC add_BibleVerse @BibleId, 110007023, N'Who is like your people, Israel, a unique nation on the earth? Their God went to claim a nation for himself and to make a name for himself! You did great and awesome acts for your land, before your people whom you delivered for yourself from the Egyptian empire and its gods.'
EXEC add_BibleVerse @BibleId, 110007024, N'You made Israel your very own people for all time. You, O Lord, became their God.'
EXEC add_BibleVerse @BibleId, 110007025, N'So now, O Lord God, make this promise you have made about your servant and his family a permanent reality. Do as you promised,'
EXEC add_BibleVerse @BibleId, 110007026, N'so you may gain lasting fame, as people say, ‘The Lord of hosts is God over Israel!’ The dynasty of your servant David will be established before you,'
EXEC add_BibleVerse @BibleId, 110007027, N'for you, O Lord of hosts, the God of Israel, have told your servant, ‘I will build you a dynastic house.’ That is why your servant has had the courage to pray this prayer to you.'
EXEC add_BibleVerse @BibleId, 110007028, N'Now, O sovereign Lord, you are the true God! May your words prove to be true! You have made this good promise to your servant!'
EXEC add_BibleVerse @BibleId, 110007029, N'Now be willing to bless your servant’s dynasty so that it may stand permanently before you, for you, O sovereign Lord, have spoken. By your blessing may your servant’s dynasty be blessed on into the future!”'
EXEC add_BibleVerse @BibleId, 110008001, N'Later David defeated the Philistines and subdued them. David took Metheg Ammah from the Philistines.'
EXEC add_BibleVerse @BibleId, 110008002, N'He defeated the Moabites. He made them lie on the ground and then used a rope to measure them off. He put two-thirds of them to death and spared the other third. The Moabites became David’s subjects and brought tribute.'
EXEC add_BibleVerse @BibleId, 110008003, N'David defeated King Hadadezer son of Rehob of Zobah when he came to reestablish his authority over the Euphrates River.'
EXEC add_BibleVerse @BibleId, 110008004, N'David seized from him 1,700 charioteers and 20,000 infantrymen. David cut the hamstrings of all but a hundred of the chariot horses.'
EXEC add_BibleVerse @BibleId, 110008005, N'The Arameans of Damascus came to help King Hadadezer of Zobah, but David killed 22,000 of the Arameans.'
EXEC add_BibleVerse @BibleId, 110008006, N'David placed garrisons in the territory of the Arameans of Damascus; the Arameans became David’s subjects and brought tribute. The Lord protected David wherever he campaigned.'
EXEC add_BibleVerse @BibleId, 110008007, N'David took the golden shields that belonged to Hadadezer’s servants and brought them to Jerusalem.'
EXEC add_BibleVerse @BibleId, 110008008, N'From Tebah and Berothai, Hadadezer’s cities, King David took a great deal of bronze.'
EXEC add_BibleVerse @BibleId, 110008009, N'When King Toi of Hamath heard that David had defeated the entire army of Hadadezer,'
EXEC add_BibleVerse @BibleId, 110008010, N'he sent his son Joram to King David to extend his best wishes and to pronounce a blessing on him for his victory over Hadadezer, for Toi had been at war with Hadadezer. He brought with him various items made of silver, gold, and bronze.'
EXEC add_BibleVerse @BibleId, 110008011, N'King David dedicated these things to the Lord, along with the dedicated silver and gold that he had taken from all the nations that he had subdued,'
EXEC add_BibleVerse @BibleId, 110008012, N'including Aram, Moab, the Ammonites, the Philistines, and Amelek. This also included some of the plunder taken from King Hadadezer son of Rehob of Zobah.'
EXEC add_BibleVerse @BibleId, 110008013, N'David became famous when he returned from defeating the Arameans in the Valley of Salt, he defeated 18,000 in all.'
EXEC add_BibleVerse @BibleId, 110008014, N'He placed garrisons throughout Edom, and all the Edomites became David’s subjects. The Lord protected David wherever he campaigned.'
EXEC add_BibleVerse @BibleId, 110008015, N'David reigned over all Israel; he guaranteed justice for all his people.'
EXEC add_BibleVerse @BibleId, 110008016, N'Joab son of Zeruiah was general in command of the army; Jehoshaphat son of Ahilud was secretary;'
EXEC add_BibleVerse @BibleId, 110008017, N'Zadok son of Ahitub and Ahimelech son of Abiathar were priests; Seraiah was scribe;'
EXEC add_BibleVerse @BibleId, 110008018, N'Benaiah son of Jehoida supervised the Kerithites and Pelethites; and David’s sons were priests.'
EXEC add_BibleVerse @BibleId, 110009001, N'Then David asked, “Is anyone still left from the family of Saul, so that I may extend kindness to him for the sake of Jonathan?”'
EXEC add_BibleVerse @BibleId, 110009002, N'Now there was a servant from Saul’s house named Ziba, so he was summoned to David. The king asked him, “Are you Ziba?” He replied, “At your service.”'
EXEC add_BibleVerse @BibleId, 110009003, N'The king asked, “Is there not someone left from Saul’s family, that I may extend God’s kindness to him?” Ziba said to the king, “One of Jonathan’s sons is left; both of his feet are crippled.”'
EXEC add_BibleVerse @BibleId, 110009004, N'The king asked him, “Where is he?” Ziba told the king, “He is at the house of Makir son of Ammiel in Lo Debar.'
EXEC add_BibleVerse @BibleId, 110009005, N'So King David had him brought from the house of Makir son of Ammiel in Lo Debar.'
EXEC add_BibleVerse @BibleId, 110009006, N'When Mephibosheth son of Jonathan, the son of Saul, came to David, he bowed low with his face toward the ground. David said, “Mephibosheth?” He replied, “Yes, at your service.”'
EXEC add_BibleVerse @BibleId, 110009007, N'David said to him, “Don’t be afraid, because I will certainly extend kindness to you for the sake of Jonathan your father. You will be a regular guest at my table.”'
EXEC add_BibleVerse @BibleId, 110009008, N'Then Mephibosheth bowed and said, “Of what importance am I, your servant, that you show regard for a dead dog like me?”'
EXEC add_BibleVerse @BibleId, 110009009, N'Then the king summoned Ziba, Saul’s attendant, and said to him, “Everything that belonged to Saul and to his entire house I hereby give to your master’s grandson.'
EXEC add_BibleVerse @BibleId, 110009010, N'You will cultivate the land for him – you and your sons and your servants. You will bring its produce and it will be food for your master’s grandson to eat. But Mephibosheth, your master’s grandson, will be a regular guest at my table.” (Now Ziba had fifteen sons and twenty servants.)'
EXEC add_BibleVerse @BibleId, 110009011, N'Ziba said to the king, “Your servant will do everything that my lord the king has instructed his servant to do.” So Mephibosheth was a regular guest at David’s table, just as though he were one of the king’s sons.'
EXEC add_BibleVerse @BibleId, 110009012, N'Now Mephibosheth had a young son whose name was Mica. All the members of Ziba’s household were Mephibosheth’s servants.'
EXEC add_BibleVerse @BibleId, 110009013, N'Mephibosheth was living in Jerusalem, for he was a regular guest at the king’s table. But both his feet were crippled.'
EXEC add_BibleVerse @BibleId, 110010001, N'Later the king of the Ammonites died and his son Hanun succeeded him.'
EXEC add_BibleVerse @BibleId, 110010002, N'David said, “I will express my loyalty to Hanun son of Nahash just as his father was loyal to me.” So David sent his servants with a message expressing sympathy over his father’s death. When David’s servants entered the land of the Ammonites,'
EXEC add_BibleVerse @BibleId, 110010003, N'the Ammonite officials said to their lord Hanun, “Do you really think David is trying to honor your father by sending these messengers to express his sympathy? No, David has sent his servants to you to get information about the city and spy on it so they can overthrow it!”'
EXEC add_BibleVerse @BibleId, 110010004, N'So Hanun seized David’s servants and shaved off half of each one’s beard. He cut the lower part of their robes off so that their buttocks were exposed, and then sent them away.'
EXEC add_BibleVerse @BibleId, 110010005, N'Messengers told David what had happened, so he summoned them, for the men were thoroughly humiliated. The king said, “Stay in Jericho until your beards have grown again; then you may come back.”'
EXEC add_BibleVerse @BibleId, 110010006, N'When the Ammonites realized that David was disgusted with them, they sent and hired 20,000 foot soldiers from Aram Beth Rehob and Aram Zobah, in addition to 1,000 men from the king of Maacah and 12,000 men from Ish-tob.'
EXEC add_BibleVerse @BibleId, 110010007, N'When David heard the news, he sent Joab and the entire army to meet them.'
EXEC add_BibleVerse @BibleId, 110010008, N'The Ammonites marched out and were deployed for battle at the entrance of the city gate, while the men from Aram Zobah, Rehob, Ish-tob, and Maacah were by themselves in the field.'
EXEC add_BibleVerse @BibleId, 110010009, N'When Joab saw that the battle would be fought on two fronts, he chose some of Israel’s best men and deployed them against the Arameans.'
EXEC add_BibleVerse @BibleId, 110010010, N'He put his brother Abishai in charge of the rest of the army and they were deployed against the Ammonites.'
EXEC add_BibleVerse @BibleId, 110010011, N'Joab said, “If the Arameans start to overpower me, you come to my rescue. If the Ammonites start to overpower you, I will come to your rescue.'
EXEC add_BibleVerse @BibleId, 110010012, N'Be strong! Let’s fight bravely for the sake of our people and the cities of our God! The Lord will do what he decides is best!”'
EXEC add_BibleVerse @BibleId, 110010013, N'So Joab and his men marched out to do battle with the Arameans, and they fled before him.'
EXEC add_BibleVerse @BibleId, 110010014, N'When the Ammonites saw the Arameans flee, they fled before his brother Abishai and went into the city. Joab withdrew from fighting the Ammonites and returned to Jerusalem.'
EXEC add_BibleVerse @BibleId, 110010015, N'When the Arameans realized that they had been defeated by Israel, they consolidated their forces.'
EXEC add_BibleVerse @BibleId, 110010016, N'Then Hadadezer sent for Arameans from beyond the Euphrates River, and they came to Helam. Shobach, the general in command of Hadadezer’s army, led them.'
EXEC add_BibleVerse @BibleId, 110010017, N'When David was informed, he gathered all Israel, crossed the Jordan River, and came to Helam. The Arameans deployed their forces against David and fought with him.'
EXEC add_BibleVerse @BibleId, 110010018, N'The Arameans fled before Israel. David killed 700 Aramean charioteers and 40,000 foot soldiers. He also struck down Shobach, the general in command of the army, who died there.'
EXEC add_BibleVerse @BibleId, 110010019, N'When all the kings who were subject to Hadadezer saw they were defeated by Israel, they made peace with Israel and became subjects of Israel. The Arameans were no longer willing to help the Ammonites.'
EXEC add_BibleVerse @BibleId, 110011001, N'In the spring of the year, at the time when kings normally conduct wars, David sent out Joab with his officers and the entire Israelite army. They defeated the Ammonites and besieged Rabbah. But David stayed behind in Jerusalem.'
EXEC add_BibleVerse @BibleId, 110011002, N'One evening David got up from his bed and walked around on the roof of his palace. From the roof he saw a woman bathing. Now this woman was very attractive.'
EXEC add_BibleVerse @BibleId, 110011003, N'So David sent someone to inquire about the woman. The messenger said, “Isn’t this Bathsheba, the daughter of Eliam, the wife of Uriah the Hittite?”'
EXEC add_BibleVerse @BibleId, 110011004, N'David sent some messengers to get her. She came to him and he had sexual relations with her. (Now at that time she was in the process of purifying herself from her menstrual uncleanness.) Then she returned to her home.'
EXEC add_BibleVerse @BibleId, 110011005, N'The woman conceived and then sent word to David saying, “I’m pregnant.”'
EXEC add_BibleVerse @BibleId, 110011006, N'So David sent a message to Joab that said, “Send me Uriah the Hittite.” So Joab sent Uriah to David.'
EXEC add_BibleVerse @BibleId, 110011007, N'When Uriah came to him, David asked about how Joab and the army were doing and how the campaign was going.'
EXEC add_BibleVerse @BibleId, 110011008, N'Then David said to Uriah, “Go down to your home and relax.” When Uriah left the palace, the king sent a gift to him.'
EXEC add_BibleVerse @BibleId, 110011009, N'But Uriah stayed at the door of the palace with all the servants of his lord. He did not go down to his house.'
EXEC add_BibleVerse @BibleId, 110011010, N'So they informed David, “Uriah has not gone down to his house.” So David said to Uriah, “Haven’t you just arrived from a journey? Why haven’t you gone down to your house?”'
EXEC add_BibleVerse @BibleId, 110011011, N'Uriah replied to David, “The ark and Israel and Judah reside in temporary shelters, and my lord Joab and my lord’s soldiers are camping in the open field. Should I go to my house to eat and drink and have marital relations with my wife? As surely as you are alive, I will not do this thing!”'
EXEC add_BibleVerse @BibleId, 110011012, N'So David said to Uriah, “Stay here another day. Tomorrow I will send you back.” So Uriah stayed in Jerusalem both that day and the following one.'
EXEC add_BibleVerse @BibleId, 110011013, N'Then David summoned him. He ate and drank with him, and got him drunk. But in the evening he went out to sleep on his bed with the servants of his lord; he did not go down to his own house.'
EXEC add_BibleVerse @BibleId, 110011014, N'In the morning David wrote a letter to Joab and sent it with Uriah.'
EXEC add_BibleVerse @BibleId, 110011015, N'In the letter he wrote: “Station Uriah in the thick of the battle and then withdraw from him so he will be cut down and killed.”'
EXEC add_BibleVerse @BibleId, 110011016, N'So as Joab kept watch on the city, he stationed Uriah at the place where he knew the best enemy soldiers were.'
EXEC add_BibleVerse @BibleId, 110011017, N'When the men of the city came out and fought with Joab, some of David’s soldiers fell in battle. Uriah the Hittite also died.'
EXEC add_BibleVerse @BibleId, 110011018, N'Then Joab sent a full battle report to David.'
EXEC add_BibleVerse @BibleId, 110011019, N'He instructed the messenger as follows: “When you finish giving the battle report to the king,'
EXEC add_BibleVerse @BibleId, 110011020, N'if the king becomes angry and asks you, ‘Why did you go so close to the city to fight? Didn’t you realize they would shoot from the wall?'
EXEC add_BibleVerse @BibleId, 110011021, N'Who struck down Abimelech the son of Jerub-Besheth? Didn’t a woman throw an upper millstone down on him from the wall so that he died in Thebez? Why did you go so close to the wall?’ just say to him, ‘Your servant Uriah the Hittite is also dead.’”'
EXEC add_BibleVerse @BibleId, 110011022, N'So the messenger departed. When he arrived, he informed David of all the news that Joab had sent with him.'
EXEC add_BibleVerse @BibleId, 110011023, N'The messenger said to David, “The men overpowered us and attacked us in the field. But we forced them to retreat all the way to the door of the city gate.'
EXEC add_BibleVerse @BibleId, 110011024, N'Then the archers shot at your servants from the wall and some of the king’s soldiers died. Your servant Uriah the Hittite is also dead.”'
EXEC add_BibleVerse @BibleId, 110011025, N'David said to the messenger, “Tell Joab, ‘Don’t let this thing upset you. There is no way to anticipate whom the sword will cut down. Press the battle against the city and conquer it.’ Encourage him with these words.”'
EXEC add_BibleVerse @BibleId, 110011026, N'When Uriah’s wife heard that her husband Uriah was dead, she mourned for him.'
EXEC add_BibleVerse @BibleId, 110011027, N'When the time of mourning passed, David had her brought to his palace. She became his wife and she bore him a son. But what David had done upset the Lord.'
EXEC add_BibleVerse @BibleId, 110012001, N'So the Lord sent Nathan to David. When he came to David, Nathan said, “There were two men in a certain city, one rich and the other poor.'
EXEC add_BibleVerse @BibleId, 110012002, N'The rich man had a great many flocks and herds.'
EXEC add_BibleVerse @BibleId, 110012003, N'But the poor man had nothing except for a little lamb he had acquired. He raised it, and it grew up alongside him and his children. It used to eat his food, drink from his cup, and sleep in his arms. It was just like a daughter to him.'
EXEC add_BibleVerse @BibleId, 110012004, N'“When a traveler arrived at the rich man’s home, he did not want to use one of his own sheep or cattle to feed the traveler who had come to visit him. Instead, he took the poor man’s lamb and cooked it for the man who had come to visit him.”'
EXEC add_BibleVerse @BibleId, 110012005, N'Then David became very angry at this man. He said to Nathan, “As surely as the Lord lives, the man who did this deserves to die!'
EXEC add_BibleVerse @BibleId, 110012006, N'Because he committed this cold-hearted crime, he must pay for the lamb four times over!”'
EXEC add_BibleVerse @BibleId, 110012007, N'Nathan said to David, “You are that man! This is what the Lord God of Israel says: ‘I chose you to be king over Israel and I rescued you from the hand of Saul.'
EXEC add_BibleVerse @BibleId, 110012008, N'I gave you your master’s house, and put your master’s wives into your arms. I also gave you the house of Israel and Judah. And if all that somehow seems insignificant, I would have given you so much more as well!'
EXEC add_BibleVerse @BibleId, 110012009, N'Why have you shown contempt for the word of the Lord by doing evil in my sight? You have struck down Uriah the Hittite with the sword and you have taken his wife as your own! You have killed him with the sword of the Ammonites.'
EXEC add_BibleVerse @BibleId, 110012010, N'So now the sword will never depart from your house. For you have despised me by taking the wife of Uriah the Hittite as your own!’'
EXEC add_BibleVerse @BibleId, 110012011, N'This is what the Lord says: ‘I am about to bring disaster on you from inside your own household! Right before your eyes I will take your wives and hand them over to your companion. He will have sexual relations with your wives in broad daylight!'
EXEC add_BibleVerse @BibleId, 110012012, N'Although you have acted in secret, I will do this thing before all Israel, and in broad daylight.’”'
EXEC add_BibleVerse @BibleId, 110012013, N'Then David exclaimed to Nathan, “I have sinned against the Lord!” Nathan replied to David, “Yes, and the Lord has forgiven your sin. You are not going to die.'
EXEC add_BibleVerse @BibleId, 110012014, N'Nonetheless, because you have treated the Lord with such contempt in this matter, the son who has been born to you will certainly die.”'
EXEC add_BibleVerse @BibleId, 110012015, N'Then Nathan went to his home. The Lord struck the child that Uriah’s wife had borne to David, and the child became very ill.'
EXEC add_BibleVerse @BibleId, 110012016, N'Then David prayed to God for the child and fasted. He would even go and spend the night lying on the ground.'
EXEC add_BibleVerse @BibleId, 110012017, N'The elders of his house stood over him and tried to lift him from the ground, but he was unwilling, and refused to eat food with them.'
EXEC add_BibleVerse @BibleId, 110012018, N'On the seventh day the child died. But the servants of David were afraid to inform him that the child had died, for they said, “While the child was still alive he would not listen to us when we spoke to him. How can we tell him that the child is dead? He will do himself harm!”'
EXEC add_BibleVerse @BibleId, 110012019, N'When David saw that his servants were whispering to one another, he realized that the child was dead. So David asked his servants, “Is the child dead?” They replied, “Yes, he’s dead.”'
EXEC add_BibleVerse @BibleId, 110012020, N'So David got up from the ground, bathed, put on oil, and changed his clothes. He went to the house of the Lord and worshiped. Then, when he entered his palace, he requested that food be brought to him, and he ate.'
EXEC add_BibleVerse @BibleId, 110012021, N'His servants said to him, “What is this that you have done? While the child was still alive, you fasted and wept. Once the child was dead you got up and ate food!”'
EXEC add_BibleVerse @BibleId, 110012022, N'He replied, “While the child was still alive, I fasted and wept because I thought, ‘Perhaps the Lord will show pity and the child will live.'
EXEC add_BibleVerse @BibleId, 110012023, N'But now he is dead. Why should I fast? Am I able to bring him back? I will go to him, but he cannot return to me!’”'
EXEC add_BibleVerse @BibleId, 110012024, N'So David comforted his wife Bathsheba. He went to her and had marital relations with her. She gave birth to a son, and David named him Solomon. Now the Lord loved the child'
EXEC add_BibleVerse @BibleId, 110012025, N'and sent word through Nathan the prophet that he should be named Jedidiah for the Lord’s sake.'
EXEC add_BibleVerse @BibleId, 110012026, N'So Joab fought against Rabbah of the Ammonites and captured the royal city.'
EXEC add_BibleVerse @BibleId, 110012027, N'Joab then sent messengers to David, saying, “I have fought against Rabbah and have captured the water supply of the city.'
EXEC add_BibleVerse @BibleId, 110012028, N'So now assemble the rest of the army and besiege the city and capture it. Otherwise I will capture the city and it will be named for me.”'
EXEC add_BibleVerse @BibleId, 110012029, N'So David assembled all the army and went to Rabbah and fought against it and captured it.'
EXEC add_BibleVerse @BibleId, 110012030, N'He took the crown of their king from his head – it was gold, weighed about seventy-five pounds, and held a precious stone – and it was placed on David’s head. He also took from the city a great deal of plunder.'
EXEC add_BibleVerse @BibleId, 110012031, N'He removed the people who were in it and made them do hard labor with saws, iron picks, and iron axes, putting them to work at the brick kiln. This was his policy with all the Ammonite cities. Then David and all the army returned to Jerusalem.'
EXEC add_BibleVerse @BibleId, 110013001, N'Now David’s son Absalom had a beautiful sister named Tamar. In the course of time David’s son Amnon fell madly in love with her.'
EXEC add_BibleVerse @BibleId, 110013002, N'But Amnon became frustrated because he was so lovesick over his sister Tamar. For she was a virgin, and to Amnon it seemed out of the question to do anything to her.'
EXEC add_BibleVerse @BibleId, 110013003, N'Now Amnon had a friend named Jonadab, the son of David’s brother Shimeah. Jonadab was a very crafty man.'
EXEC add_BibleVerse @BibleId, 110013004, N'He asked Amnon, “Why are you, the king’s son, so depressed every morning? Can’t you tell me?” So Amnon said to him, “I’m in love with Tamar the sister of my brother Absalom.”'
EXEC add_BibleVerse @BibleId, 110013005, N'Jonadab replied to him, “Lie down on your bed and pretend to be sick. When your father comes in to see you, say to him, ‘Please let my sister Tamar come in so she can fix some food for me. Let her prepare the food in my sight so I can watch. Then I will eat from her hand.’”'
EXEC add_BibleVerse @BibleId, 110013006, N'So Amnon lay down and pretended to be sick. When the king came in to see him, Amnon said to the king, “Please let my sister Tamar come in so she can make a couple of cakes in my sight. Then I will eat from her hand.”'
EXEC add_BibleVerse @BibleId, 110013007, N'So David sent Tamar to the house saying, “Please go to the house of Amnon your brother and prepare some food for him.”'
EXEC add_BibleVerse @BibleId, 110013008, N'So Tamar went to the house of Amnon her brother, who was lying down. She took the dough, kneaded it, made some cakes while he watched, and baked them.'
EXEC add_BibleVerse @BibleId, 110013009, N'But when she took the pan and set it before him, he refused to eat. Instead Amnon said, “Get everyone out of here!” So everyone left.'
EXEC add_BibleVerse @BibleId, 110013010, N'Then Amnon said to Tamar, “Bring the cakes into the bedroom; then I will eat from your hand.” So Tamar took the cakes that she had prepared and brought them to her brother Amnon in the bedroom.'
EXEC add_BibleVerse @BibleId, 110013011, N'As she brought them to him to eat, he grabbed her and said to her, “Come on! Get in bed with me, my sister!”'
EXEC add_BibleVerse @BibleId, 110013012, N'But she said to him, “No, my brother! Don’t humiliate me! This just isn’t done in Israel! Don’t do this foolish thing!'
EXEC add_BibleVerse @BibleId, 110013013, N'How could I ever be rid of my humiliation? And you would be considered one of the fools in Israel! Just speak to the king, for he will not withhold me from you.”'
EXEC add_BibleVerse @BibleId, 110013014, N'But he refused to listen to her. He overpowered her and humiliated her by raping her.'
EXEC add_BibleVerse @BibleId, 110013015, N'Then Amnon greatly despised her. His disdain toward her surpassed the love he had previously felt toward her. Amnon said to her, “Get up and leave!”'
EXEC add_BibleVerse @BibleId, 110013016, N'But she said to him, “No I won’t, for sending me away now would be worse than what you did to me earlier!” But he refused to listen to her.'
EXEC add_BibleVerse @BibleId, 110013017, N'He called his personal attendant and said to him, “Take this woman out of my sight and lock the door behind her!”'
EXEC add_BibleVerse @BibleId, 110013018, N'(Now she was wearing a long robe, for this is what the king’s virgin daughters used to wear.) So Amnon’s attendant removed her and bolted the door behind her.'
EXEC add_BibleVerse @BibleId, 110013019, N'Then Tamar put ashes on her head and tore the long robe she was wearing. She put her hands on her head and went on her way, wailing as she went.'
EXEC add_BibleVerse @BibleId, 110013020, N'Her brother Absalom said to her, “Was Amnon your brother with you? Now be quiet, my sister. He is your brother. Don’t take it so seriously!” Tamar, devastated, lived in the house of her brother Absalom.'
EXEC add_BibleVerse @BibleId, 110013021, N'Now King David heard about all these things and was very angry.'
EXEC add_BibleVerse @BibleId, 110013022, N'But Absalom said nothing to Amnon, either bad or good, yet Absalom hated Amnon because he had humiliated his sister Tamar.'
EXEC add_BibleVerse @BibleId, 110013023, N'Two years later Absalom’s sheepshearers were in Baal Hazor, near Ephraim. Absalom invited all the king’s sons.'
EXEC add_BibleVerse @BibleId, 110013024, N'Then Absalom went to the king and said, “My shearers have begun their work. Let the king and his servants go with me.”'
EXEC add_BibleVerse @BibleId, 110013025, N'But the king said to Absalom, “No, my son. We shouldn’t all go. We shouldn’t burden you in that way.” Though Absalom pressed him, the king was not willing to go. Instead, David blessed him.'
EXEC add_BibleVerse @BibleId, 110013026, N'Then Absalom said, “If you will not go, then let my brother Amnon go with us.” The king replied to him, “Why should he go with you?”'
EXEC add_BibleVerse @BibleId, 110013027, N'But when Absalom pressed him, he sent Amnon and all the king’s sons along with him.'
EXEC add_BibleVerse @BibleId, 110013028, N'Absalom instructed his servants, “Look! When Amnon is drunk and I say to you, ‘Strike Amnon down,’ kill him then and there. Don’t fear! Is it not I who have given you these instructions? Be strong and courageous!”'
EXEC add_BibleVerse @BibleId, 110013029, N'So Absalom’s servants did to Amnon exactly what Absalom had instructed. Then all the king’s sons got up; each one rode away on his mule and fled.'
EXEC add_BibleVerse @BibleId, 110013030, N'While they were still on their way, the following report reached David: “Absalom has killed all the king’s sons; not one of them is left!”'
EXEC add_BibleVerse @BibleId, 110013031, N'Then the king stood up and tore his garments and lay down on the ground. All his servants were standing there with torn garments as well.'
EXEC add_BibleVerse @BibleId, 110013032, N'Jonadab, the son of David’s brother Shimeah, said, “My lord should not say, ‘They have killed all the young men who are the king’s sons.’ For only Amnon is dead. This is what Absalom has talked about from the day that Amnon humiliated his sister Tamar.'
EXEC add_BibleVerse @BibleId, 110013033, N'Now don’t let my lord the king be concerned about the report that has come saying, ‘All the king’s sons are dead.’ It is only Amnon who is dead.”'
EXEC add_BibleVerse @BibleId, 110013034, N'In the meantime Absalom fled. When the servant who was the watchman looked up, he saw many people coming from the west on a road beside the hill.'
EXEC add_BibleVerse @BibleId, 110013035, N'Jonadab said to the king, “Look! The king’s sons have come! It’s just as I said!”'
EXEC add_BibleVerse @BibleId, 110013036, N'Just as he finished speaking, the king’s sons arrived, wailing and weeping. The king and all his servants wept loudly as well.'
EXEC add_BibleVerse @BibleId, 110013037, N'But Absalom fled and went to King Talmai son of Ammihud of Geshur. And David grieved over his son every day.'
EXEC add_BibleVerse @BibleId, 110013038, N'After Absalom fled and went to Geshur, he remained there for three years.'
EXEC add_BibleVerse @BibleId, 110013039, N'The king longed to go to Absalom, for he had since been consoled over the death of Amnon.'
EXEC add_BibleVerse @BibleId, 110014001, N'Now Joab son of Zeruiah realized that the king longed to see Absalom.'
EXEC add_BibleVerse @BibleId, 110014002, N'So Joab sent to Tekoa and brought from there a wise woman. He told her, “Pretend to be in mourning and put on garments for mourning. Don’t anoint yourself with oil. Instead, act like a woman who has been mourning for the dead for some time.'
EXEC add_BibleVerse @BibleId, 110014003, N'Go to the king and speak to him in the following fashion.” Then Joab told her what to say.'
EXEC add_BibleVerse @BibleId, 110014004, N'So the Tekoan woman went to the king. She bowed down with her face to the ground in deference to him and said, “Please help me, O king!”'
EXEC add_BibleVerse @BibleId, 110014005, N'The king replied to her, “What do you want?” She answered, “I am a widow; my husband is dead.'
EXEC add_BibleVerse @BibleId, 110014006, N'Your servant has two sons. When the two of them got into a fight in the field, there was no one present who could intervene. One of them struck the other and killed him.'
EXEC add_BibleVerse @BibleId, 110014007, N'Now the entire family has risen up against your servant, saying, ‘Turn over the one who struck down his brother, so that we can execute him and avenge the death of his brother whom he killed. In so doing we will also destroy the heir.’ They want to extinguish my remaining coal, leaving no one on the face of the earth to carry on the name of my husband.”'
EXEC add_BibleVerse @BibleId, 110014008, N'Then the king told the woman, “Go to your home. I will give instructions concerning your situation.”'
EXEC add_BibleVerse @BibleId, 110014009, N'The Tekoan woman said to the king, “My lord the king, let any blame fall on me and on the house of my father. But let the king and his throne be innocent!”'
EXEC add_BibleVerse @BibleId, 110014010, N'The king said, “Bring to me whoever speaks to you, and he won’t bother you again!”'
EXEC add_BibleVerse @BibleId, 110014011, N'She replied, “In that case, let the king invoke the name of the Lord your God so that the avenger of blood may not kill! Then they will not destroy my son!” He replied, “As surely as the Lord lives, not a single hair of your son’s head will fall to the ground.”'
EXEC add_BibleVerse @BibleId, 110014012, N'Then the woman said, “Please permit your servant to speak to my lord the king about another matter.” He replied, “Tell me.”'
EXEC add_BibleVerse @BibleId, 110014013, N'The woman said, “Why have you devised something like this against God’s people? When the king speaks in this fashion, he makes himself guilty, for the king has not brought back the one he has banished.'
EXEC add_BibleVerse @BibleId, 110014014, N'Certainly we must die, and are like water spilled on the ground that cannot be gathered up again. But God does not take away life; instead he devises ways for the banished to be restored.'
EXEC add_BibleVerse @BibleId, 110014015, N'I have now come to speak with my lord the king about this matter, because the people have made me fearful. But your servant said, ‘I will speak to the king! Perhaps the king will do what his female servant asks.'
EXEC add_BibleVerse @BibleId, 110014016, N'Yes! The king may listen and deliver his female servant from the hand of the man who seeks to remove both me and my son from the inheritance God has given us!’'
EXEC add_BibleVerse @BibleId, 110014017, N'So your servant said, ‘May the word of my lord the king be my security, for my lord the king is like the angel of God when it comes to deciding between right and wrong! May the Lord your God be with you!’”'
EXEC add_BibleVerse @BibleId, 110014018, N'Then the king replied to the woman, “Don’t hide any information from me when I question you.” The woman said, “Let my lord the king speak!”'
EXEC add_BibleVerse @BibleId, 110014019, N'The king said, “Did Joab put you up to all of this?” The woman answered, “As surely as you live, my lord the king, there is no deviation to the right or to the left from all that my lord the king has said. For your servant Joab gave me instructions. He has put all these words in your servant’s mouth.'
EXEC add_BibleVerse @BibleId, 110014020, N'Your servant Joab did this so as to change this situation. But my lord has wisdom like that of the angel of God, and knows everything that is happening in the land.”'
EXEC add_BibleVerse @BibleId, 110014021, N'Then the king said to Joab, “All right! I will do this thing! Go and bring back the young man Absalom!'
EXEC add_BibleVerse @BibleId, 110014022, N'Then Joab bowed down with his face toward the ground and thanked the king. Joab said, “Today your servant knows that I have found favor in your sight, my lord the king, because the king has granted the request of your servant!”'
EXEC add_BibleVerse @BibleId, 110014023, N'So Joab got up and went to Geshur and brought Absalom back to Jerusalem.'
EXEC add_BibleVerse @BibleId, 110014024, N'But the king said, “Let him go over to his own house. He may not see my face.” So Absalom went over to his own house; he did not see the king’s face.'
EXEC add_BibleVerse @BibleId, 110014025, N'Now in all Israel everyone acknowledged that there was no man as handsome as Absalom. From the sole of his feet to the top of his head he was perfect in appearance.'
EXEC add_BibleVerse @BibleId, 110014026, N'When he would shave his head – at the end of every year he used to shave his head, for it grew too long and he would shave it – he used to weigh the hair of his head at three pounds according to the king’s weight.'
EXEC add_BibleVerse @BibleId, 110014027, N'Absalom had three sons and one daughter, whose name was Tamar. She was a very attractive woman.'
EXEC add_BibleVerse @BibleId, 110014028, N'Absalom lived in Jerusalem for two years without seeing the king’s face.'
EXEC add_BibleVerse @BibleId, 110014029, N'Then Absalom sent a message to Joab asking him to send him to the king, but Joab was not willing to come to him. So he sent a second message to him, but he still was not willing to come.'
EXEC add_BibleVerse @BibleId, 110014030, N'So he said to his servants, “Look, Joab has a portion of field adjacent to mine and he has some barley there. Go and set it on fire.” So Absalom’s servants set Joab’s portion of the field on fire.'
EXEC add_BibleVerse @BibleId, 110014031, N'Then Joab got up and came to Absalom’s house. He said to him, “Why did your servants set my portion of field on fire?”'
EXEC add_BibleVerse @BibleId, 110014032, N'Absalom said to Joab, “Look, I sent a message to you saying, ‘Come here so that I can send you to the king with this message: “Why have I come from Geshur? It would be better for me if I were still there.”’ Let me now see the face of the king. If I am at fault, let him put me to death!”'
EXEC add_BibleVerse @BibleId, 110014033, N'So Joab went to the king and informed him. The king summoned Absalom, and he came to the king. Absalom bowed down before the king with his face toward the ground and the king kissed him.'
EXEC add_BibleVerse @BibleId, 110015001, N'Some time later Absalom managed to acquire a chariot and horses, as well as fifty men to serve as his royal guard.'
EXEC add_BibleVerse @BibleId, 110015002, N'Now Absalom used to get up early and stand beside the road that led to the city gate. Whenever anyone came by who had a complaint to bring to the king for arbitration, Absalom would call out to him, “What city are you from?” The person would answer, “I, your servant, am from one of the tribes of Israel.”'
EXEC add_BibleVerse @BibleId, 110015003, N'Absalom would then say to him, “Look, your claims are legitimate and appropriate. But there is no representative of the king who will listen to you.”'
EXEC add_BibleVerse @BibleId, 110015004, N'Absalom would then say, “If only they would make me a judge in the land! Then everyone who had a judicial complaint could come to me and I would make sure he receives a just settlement.”'
EXEC add_BibleVerse @BibleId, 110015005, N'When someone approached to bow before him, Absalom would extend his hand and embrace him and kiss him.'
EXEC add_BibleVerse @BibleId, 110015006, N'Absalom acted this way toward everyone in Israel who came to the king for justice. In this way Absalom won the loyalty of the citizens of Israel.'
EXEC add_BibleVerse @BibleId, 110015007, N'After four years Absalom said to the king, “Let me go and repay my vow that I made to the Lord while I was in Hebron.'
EXEC add_BibleVerse @BibleId, 110015008, N'For I made this vow when I was living in Geshur in Aram: ‘If the Lord really does allow me to return to Jerusalem, I will serve the Lord.’”'
EXEC add_BibleVerse @BibleId, 110015009, N'The king replied to him, “Go in peace.” So Absalom got up and went to Hebron.'
EXEC add_BibleVerse @BibleId, 110015010, N'Then Absalom sent spies through all the tribes of Israel who said, “When you hear the sound of the horn, you may assume that Absalom rules in Hebron.”'
EXEC add_BibleVerse @BibleId, 110015011, N'Now two hundred men had gone with Absalom from Jerusalem. Since they were invited, they went naively and were unaware of what Absalom was planning.'
EXEC add_BibleVerse @BibleId, 110015012, N'While he was offering sacrifices, Absalom sent for Ahithophel the Gilonite, David’s adviser, to come from his city, Giloh. The conspiracy was gaining momentum, and the people were starting to side with Absalom.'
EXEC add_BibleVerse @BibleId, 110015013, N'Then a messenger came to David and reported, “The men of Israel are loyal to Absalom!”'
EXEC add_BibleVerse @BibleId, 110015014, N'So David said to all his servants who were with him in Jerusalem, “Come on! Let’s escape! Otherwise no one will be delivered from Absalom! Go immediately, or else he will quickly overtake us and bring disaster on us and kill the city’s residents with the sword.”'
EXEC add_BibleVerse @BibleId, 110015015, N'The king’s servants replied to the king, “We will do whatever our lord the king decides.”'
EXEC add_BibleVerse @BibleId, 110015016, N'So the king and all the members of his royal court set out on foot, though the king left behind ten concubines to attend to the palace.'
EXEC add_BibleVerse @BibleId, 110015017, N'The king and all the people set out on foot, pausing at a spot some distance away.'
EXEC add_BibleVerse @BibleId, 110015018, N'All his servants were leaving with him, along with all the Kerethites, all the Pelethites, and all the Gittites – some six hundred men who had come on foot from Gath. They were leaving with the king.'
EXEC add_BibleVerse @BibleId, 110015019, N'Then the king said to Ittai the Gittite, “Why should you come with us? Go back and stay with the new king, for you are a foreigner and an exile from your own country.'
EXEC add_BibleVerse @BibleId, 110015020, N'It seems like you arrived just yesterday. Today should I make you wander around by going with us? I go where I must go. But as for you, go back and take your men with you. May genuine loyal love protect you!”'
EXEC add_BibleVerse @BibleId, 110015021, N'But Ittai replied to the king, “As surely as the Lord lives and as my lord the king lives, wherever my lord the king is, whether dead or alive, there I will be as well!”'
EXEC add_BibleVerse @BibleId, 110015022, N'So David said to Ittai, “Come along then.” So Ittai the Gittite went along, accompanied by all his men and all the dependents who were with him.'
EXEC add_BibleVerse @BibleId, 110015023, N'All the land was weeping loudly as all these people were leaving. As the king was crossing over the Kidron Valley, all the people were leaving on the road that leads to the desert.'
EXEC add_BibleVerse @BibleId, 110015024, N'Zadok and all the Levites who were with him were carrying the ark of the covenant of God. When they positioned the ark of God, Abiathar offered sacrifices until all the people had finished leaving the city.'
EXEC add_BibleVerse @BibleId, 110015025, N'Then the king said to Zadok, “Take the ark of God back to the city. If I find favor in the Lord’s sight he will bring me back and enable me to see both it and his dwelling place again.'
EXEC add_BibleVerse @BibleId, 110015026, N'However, if he should say, ‘I do not take pleasure in you,’ then he will deal with me in a way that he considers appropriate.”'
EXEC add_BibleVerse @BibleId, 110015027, N'The king said to Zadok the priest, “Are you a seer? Go back to the city in peace! Your son Ahimaaz and Abiathar’s son Jonathan may go with you and Abiathar.'
EXEC add_BibleVerse @BibleId, 110015028, N'Look, I will be waiting at the fords of the desert until word from you reaches me.”'
EXEC add_BibleVerse @BibleId, 110015029, N'So Zadok and Abiathar took the ark of God back to Jerusalem and remained there.'
EXEC add_BibleVerse @BibleId, 110015030, N'As David was going up the Mount of Olives, he was weeping as he went; his head was covered and his feet were bare. All the people who were with him also had their heads covered and were weeping as they went up.'
EXEC add_BibleVerse @BibleId, 110015031, N'Now David had been told, “Ahithophel has sided with the conspirators who are with Absalom. So David prayed, “Make the advice of Ahithophel foolish, O Lord!”'
EXEC add_BibleVerse @BibleId, 110015032, N'When David reached the summit, where he used to worship God, Hushai the Arkite met him with his clothes torn and dirt on his head.'
EXEC add_BibleVerse @BibleId, 110015033, N'David said to him, “If you leave with me you will be a burden to me.'
EXEC add_BibleVerse @BibleId, 110015034, N'But you will be able to counter the advice of Ahithophel if you go back to the city and say to Absalom, ‘I will be your servant, O king! Previously I was your father’s servant, and now I will be your servant.’'
EXEC add_BibleVerse @BibleId, 110015035, N'Zadok and Abiathar the priests will be there with you. Everything you hear in the king’s palace you must tell Zadok and Abiathar the priests.'
EXEC add_BibleVerse @BibleId, 110015036, N'Furthermore, their two sons are there with them, Zadok’s son Ahimaaz and Abiathar’s son Jonathan. You must send them to me with any information you hear.”'
EXEC add_BibleVerse @BibleId, 110015037, N'So David’s friend Hushai arrived in the city, just as Absalom was entering Jerusalem.'
EXEC add_BibleVerse @BibleId, 110016001, N'When David had gone a short way beyond the summit, Ziba the servant of Mephibosheth was there to meet him. He had a couple of donkeys that were saddled, and on them were two hundred loaves of bread, a hundred raisin cakes, a hundred baskets of summer fruit, and a container of wine.'
EXEC add_BibleVerse @BibleId, 110016002, N'The king asked Ziba, “Why did you bring these things?” Ziba replied, “The donkeys are for the king’s family to ride on, the loaves of bread and the summer fruit are for the attendants to eat, and the wine is for those who get exhausted in the desert.”'
EXEC add_BibleVerse @BibleId, 110016003, N'The king asked, “Where is your master’s grandson?” Ziba replied to the king, “He remains in Jerusalem, for he said, ‘Today the house of Israel will give back to me my grandfather’s kingdom.’”'
EXEC add_BibleVerse @BibleId, 110016004, N'The king said to Ziba, “Everything that was Mephibosheth’s now belongs to you.” Ziba replied, “I bow before you. May I find favor in your sight, my lord the king.”'
EXEC add_BibleVerse @BibleId, 110016005, N'Then King David reached Bahurim. There a man from Saul’s extended family named Shimei son of Gera came out, yelling curses as he approached.'
EXEC add_BibleVerse @BibleId, 110016006, N'He threw stones at David and all of King David’s servants, as well as all the people and the soldiers who were on his right and on his left.'
EXEC add_BibleVerse @BibleId, 110016007, N'As he yelled curses, Shimei said, “Leave! Leave! You man of bloodshed, you wicked man!'
EXEC add_BibleVerse @BibleId, 110016008, N'The Lord has punished you for all the spilled blood of the house of Saul, in whose place you rule. Now the Lord has given the kingdom into the hand of your son Absalom. Disaster has overtaken you, for you are a man of bloodshed!”'
EXEC add_BibleVerse @BibleId, 110016009, N'Then Abishai son of Zeruiah said to the king, “Why should this dead dog curse my lord the king? Let me go over and cut off his head!”'
EXEC add_BibleVerse @BibleId, 110016010, N'But the king said, “What do we have in common, you sons of Zeruiah? If he curses because the Lord has said to him, ‘Curse David!’, who can say to him, ‘Why have you done this?’”'
EXEC add_BibleVerse @BibleId, 110016011, N'Then David said to Abishai and to all his servants, “My own son, my very own flesh and blood, is trying to take my life. So also now this Benjaminite! Leave him alone so that he can curse, for the Lord has spoken to him.'
EXEC add_BibleVerse @BibleId, 110016012, N'Perhaps the Lord will notice my affliction and this day grant me good in place of his curse.”'
EXEC add_BibleVerse @BibleId, 110016013, N'So David and his men went on their way. But Shimei kept going along the side of the hill opposite him, yelling curses as he threw stones and dirt at them.'
EXEC add_BibleVerse @BibleId, 110016014, N'The king and all the people who were with him arrived exhausted at their destination, where David refreshed himself.'
EXEC add_BibleVerse @BibleId, 110016015, N'Now when Absalom and all the men of Israel arrived in Jerusalem, Ahithophel was with him.'
EXEC add_BibleVerse @BibleId, 110016016, N'When David’s friend Hushai the Arkite came to Absalom, Hushai said to him, “Long live the king! Long live the king!”'
EXEC add_BibleVerse @BibleId, 110016017, N'Absalom said to Hushai, “Do you call this loyalty to your friend? Why didn’t you go with your friend?”'
EXEC add_BibleVerse @BibleId, 110016018, N'Hushai replied to Absalom, “No, I will be loyal to the one whom the Lord, these people, and all the men of Israel have chosen.'
EXEC add_BibleVerse @BibleId, 110016019, N'Moreover, whom should I serve? Should it not be his son? Just as I served your father, so I will serve you.”'
EXEC add_BibleVerse @BibleId, 110016020, N'Then Absalom said to Ahithophel, “Give us your advice. What should we do?”'
EXEC add_BibleVerse @BibleId, 110016021, N'Ahithophel replied to Absalom, “Have sex with your father’s concubines whom he left to care for the palace. All Israel will hear that you have made yourself repulsive to your father. Then your followers will be motivated to support you.”'
EXEC add_BibleVerse @BibleId, 110016022, N'So they pitched a tent for Absalom on the roof, and Absalom had sex with his father’s concubines in the sight of all Israel.'
EXEC add_BibleVerse @BibleId, 110016023, N'In those days Ahithophel’s advice was considered as valuable as a prophetic revelation. Both David and Absalom highly regarded the advice of Ahithophel.'
EXEC add_BibleVerse @BibleId, 110017001, N'Ahithophel said to Absalom, “Let me pick out twelve thousand men. Then I will go and pursue David this very night.'
EXEC add_BibleVerse @BibleId, 110017002, N'When I catch up with him he will be exhausted and worn out. I will rout him, and the entire army that is with him will flee. I will kill only the king'
EXEC add_BibleVerse @BibleId, 110017003, N'and will bring the entire army back to you. In exchange for the life of the man you are seeking, you will get back everyone. The entire army will return unharmed.”'
EXEC add_BibleVerse @BibleId, 110017004, N'This seemed like a good idea to Absalom and to all the leaders of Israel.'
EXEC add_BibleVerse @BibleId, 110017005, N'But Absalom said, “Call for Hushai the Arkite, and let’s hear what he has to say.”'
EXEC add_BibleVerse @BibleId, 110017006, N'So Hushai came to Absalom. Absalom said to him, “Here is what Ahithophel has advised. Should we follow his advice? If not, what would you recommend?”'
EXEC add_BibleVerse @BibleId, 110017007, N'Hushai replied to Absalom, “Ahithophel’s advice is not sound this time.”'
EXEC add_BibleVerse @BibleId, 110017008, N'Hushai went on to say, “You know your father and his men – they are soldiers and are as dangerous as a bear out in the wild that has been robbed of her cubs. Your father is an experienced soldier; he will not stay overnight with the army.'
EXEC add_BibleVerse @BibleId, 110017009, N'At this very moment he is hiding out in one of the caves or in some other similar place. If it should turn out that he attacks our troops first, whoever hears about it will say, ‘Absalom’s army has been slaughtered!’'
EXEC add_BibleVerse @BibleId, 110017010, N'If that happens even the bravest soldier – one who is lion-hearted – will virtually melt away. For all Israel knows that your father is a warrior and that those who are with him are brave.'
EXEC add_BibleVerse @BibleId, 110017011, N'My advice therefore is this: Let all Israel from Dan to Beer Sheba – in number like the sand by the sea! – be mustered to you, and you lead them personally into battle.'
EXEC add_BibleVerse @BibleId, 110017012, N'We will come against him wherever he happens to be found. We will descend on him like the dew falls on the ground. Neither he nor any of the men who are with him will be spared alive – not one of them!'
EXEC add_BibleVerse @BibleId, 110017013, N'If he regroups in a city, all Israel will take up ropes to that city and drag it down to the valley, so that not a single pebble will be left there!”'
EXEC add_BibleVerse @BibleId, 110017014, N'Then Absalom and all the men of Israel said, “The advice of Hushai the Arkite sounds better than the advice of Ahithophel.” Now the Lord had decided to frustrate the sound advice of Ahithophel, so that the Lord could bring disaster on Absalom.'
EXEC add_BibleVerse @BibleId, 110017015, N'Then Hushai reported to Zadok and Abiathar the priests, “Here is what Ahithophel has advised Absalom and the leaders of Israel to do, and here is what I have advised.'
EXEC add_BibleVerse @BibleId, 110017016, N'Now send word quickly to David and warn him, “Don’t spend the night at the fords of the desert tonight. Instead, be sure you cross over, or else the king and everyone who is with him may be overwhelmed.”'
EXEC add_BibleVerse @BibleId, 110017017, N'Now Jonathan and Ahimaaz were staying in En Rogel. A female servant would go and inform them, and they would then go and inform King David. It was not advisable for them to be seen going into the city.'
EXEC add_BibleVerse @BibleId, 110017018, N'But a young man saw them on one occasion and informed Absalom. So the two of them quickly departed and went to the house of a man in Bahurim. There was a well in his courtyard, and they got down in it.'
EXEC add_BibleVerse @BibleId, 110017019, N'His wife then took the covering and spread it over the top of the well and scattered some grain over it. No one was aware of what she had done.'
EXEC add_BibleVerse @BibleId, 110017020, N'When the servants of Absalom approached the woman at her home, they asked, “Where are Ahimaaz and Jonathan?” The woman replied to them, “They crossed over the stream.” Absalom’s men searched but did not find them, so they returned to Jerusalem.'
EXEC add_BibleVerse @BibleId, 110017021, N'After the men had left, Ahimaaz and Jonathan climbed out of the well. Then they left and informed King David. They advised David, “Get up and cross the stream quickly, for Ahithophel has devised a plan to catch you.”'
EXEC add_BibleVerse @BibleId, 110017022, N'So David and all the people who were with him got up and crossed the Jordan River. By dawn there was not one person left who had not crossed the Jordan.'
EXEC add_BibleVerse @BibleId, 110017023, N'When Ahithophel realized that his advice had not been followed, he saddled his donkey and returned to his house in his hometown. After setting his household in order, he hanged himself. So he died and was buried in the grave of his father.'
EXEC add_BibleVerse @BibleId, 110017024, N'Meanwhile David had gone to Mahanaim, while Absalom and all the men of Israel had crossed the Jordan River.'
EXEC add_BibleVerse @BibleId, 110017025, N'Absalom had made Amasa general in command of the army in place of Joab. (Now Amasa was the son of an Israelite man named Jether, who had married Abigail the daughter of Nahash and sister of Zeruiah, Joab’s mother.)'
EXEC add_BibleVerse @BibleId, 110017026, N'The army of Israel and Absalom camped in the land of Gilead.'
EXEC add_BibleVerse @BibleId, 110017027, N'When David came to Mahanaim, Shobi the son of Nahash from Rabbah of the Ammonites, Makir the son of Ammiel from Lo Debar, and Barzillai the Gileadite from Rogelim'
EXEC add_BibleVerse @BibleId, 110017028, N'brought bedding, basins, and pottery utensils. They also brought food for David and all who were with him, including wheat, barley, flour, roasted grain, beans, lentils,'
EXEC add_BibleVerse @BibleId, 110017029, N'honey, curds, flocks, and cheese. For they said, “The people are no doubt hungry, tired, and thirsty there in the desert.”'
EXEC add_BibleVerse @BibleId, 110018001, N'David assembled the army that was with him. He appointed leaders of thousands and leaders of hundreds.'
EXEC add_BibleVerse @BibleId, 110018002, N'David then sent out the army – a third under the leadership of Joab, a third under the leadership of Joab’s brother Abishai son of Zeruiah, and a third under the leadership of Ittai the Gittite. The king said to the troops, “I too will indeed march out with you.”'
EXEC add_BibleVerse @BibleId, 110018003, N'But the soldiers replied, “You should not do this! For if we should have to make a rapid retreat, they won’t be too concerned about us. Even if half of us should die, they won’t be too concerned about us. But you are like ten thousand of us! So it is better if you remain in the city for support.”'
EXEC add_BibleVerse @BibleId, 110018004, N'Then the king said to them, “I will do whatever seems best to you.” So the king stayed beside the city gate, while all the army marched out by hundreds and by thousands.'
EXEC add_BibleVerse @BibleId, 110018005, N'The king gave this order to Joab, Abishai, and Ittai: “For my sake deal gently with the young man Absalom.” Now the entire army was listening when the king gave all the leaders this order concerning Absalom.'
EXEC add_BibleVerse @BibleId, 110018006, N'Then the army marched out to the field to fight against Israel. The battle took place in the forest of Ephraim.'
EXEC add_BibleVerse @BibleId, 110018007, N'The army of Israel was defeated there by David’s men. The slaughter there was great that day – 20,000 soldiers were killed.'
EXEC add_BibleVerse @BibleId, 110018008, N'The battle there was spread out over the whole area, and the forest consumed more soldiers than the sword devoured that day.'
EXEC add_BibleVerse @BibleId, 110018009, N'Then Absalom happened to come across David’s men. Now as Absalom was riding on his mule, it went under the branches of a large oak tree. His head got caught in the oak and he was suspended in midair, while the mule he had been riding kept going.'
EXEC add_BibleVerse @BibleId, 110018010, N'When one of the men saw this, he reported it to Joab saying, “I saw Absalom hanging in an oak tree.'
EXEC add_BibleVerse @BibleId, 110018011, N'Joab replied to the man who was telling him this, “What! You saw this? Why didn’t you strike him down right on the spot? I would have given you ten pieces of silver and a commemorative belt!”'
EXEC add_BibleVerse @BibleId, 110018012, N'The man replied to Joab, “Even if I were receiving a thousand pieces of silver, I would not strike the king’s son! In our very presence the king gave this order to you and Abishai and Ittai, ‘Protect the young man Absalom for my sake.’'
EXEC add_BibleVerse @BibleId, 110018013, N'If I had acted at risk of my own life – and nothing is hidden from the king! – you would have abandoned me.”'
EXEC add_BibleVerse @BibleId, 110018014, N'Joab replied, “I will not wait around like this for you!” He took three spears in his hand and thrust them into the middle of Absalom while he was still alive in the middle of the oak tree.'
EXEC add_BibleVerse @BibleId, 110018015, N'Then ten soldiers who were Joab’s armor bearers struck Absalom and finished him off.'
EXEC add_BibleVerse @BibleId, 110018016, N'Then Joab blew the trumpet and the army turned back from chasing Israel, for Joab had called for the army to halt.'
EXEC add_BibleVerse @BibleId, 110018017, N'They took Absalom, threw him into a large pit in the forest, and stacked a huge pile of stones over him. In the meantime all the Israelite soldiers fled to their homes.'
EXEC add_BibleVerse @BibleId, 110018018, N'Prior to this Absalom had set up a monument and dedicated it to himself in the King’s Valley, reasoning “I have no son who will carry on my name.” He named the monument after himself, and to this day it is known as Absalom’s Memorial.'
EXEC add_BibleVerse @BibleId, 110018019, N'Then Ahimaaz the son of Zadok said, “Let me run and give the king the good news that the Lord has vindicated him before his enemies.”'
EXEC add_BibleVerse @BibleId, 110018020, N'But Joab said to him, “You will not be a bearer of good news today. You will bear good news some other day, but not today, for the king’s son is dead.”'
EXEC add_BibleVerse @BibleId, 110018021, N'Then Joab said to the Cushite, “Go and tell the king what you have seen.” After bowing to Joab, the Cushite ran off.'
EXEC add_BibleVerse @BibleId, 110018022, N'Ahimaaz the son of Zadok again spoke to Joab, “Whatever happens, let me go after the Cushite.” But Joab said, “Why is it that you want to go, my son? You have no good news that will bring you a reward.”'
EXEC add_BibleVerse @BibleId, 110018023, N'But he said, “Whatever happens, I want to go!” So Joab said to him, “Then go!” So Ahimaaz ran by the way of the Jordan plain, and he passed the Cushite.'
EXEC add_BibleVerse @BibleId, 110018024, N'Now David was sitting between the inner and outer gates, and the watchman went up to the roof over the gate at the wall. When he looked, he saw a man running by himself.'
EXEC add_BibleVerse @BibleId, 110018025, N'So the watchman called out and informed the king. The king said, “If he is by himself, he brings good news.” The runner came ever closer.'
EXEC add_BibleVerse @BibleId, 110018026, N'Then the watchman saw another man running. The watchman called out to the gatekeeper, “There is another man running by himself.” The king said, “This one also is bringing good news.”'
EXEC add_BibleVerse @BibleId, 110018027, N'The watchman said, “It appears to me that the first runner is Ahimaaz son of Zadok.” The king said, “He is a good man, and he comes with good news.”'
EXEC add_BibleVerse @BibleId, 110018028, N'Then Ahimaaz called out and said to the king, “Greetings!” He bowed down before the king with his face toward the ground and said, “May the Lord your God be praised because he has defeated the men who opposed my lord the king!”'
EXEC add_BibleVerse @BibleId, 110018029, N'The king replied, “How is the young man Absalom?” Ahimaaz replied, “I saw a great deal of confusion when Joab was sending the king’s servant and me, your servant, but I don’t know what it was all about.”'
EXEC add_BibleVerse @BibleId, 110018030, N'The king said, “Turn aside and take your place here.” So he turned aside and waited.'
EXEC add_BibleVerse @BibleId, 110018031, N'Then the Cushite arrived and said, “May my lord the king now receive the good news! The Lord has vindicated you today and delivered you from the hand of all who have rebelled against you!”'
EXEC add_BibleVerse @BibleId, 110018032, N'The king asked the Cushite, “How is the young man Absalom?” The Cushite replied, “May the enemies of my lord the king and all who have plotted against you be like that young man!”'
EXEC add_BibleVerse @BibleId, 110018033, N'The king then became very upset. He went up to the upper room over the gate and wept. As he went he said, “My son, Absalom! My son, my son, Absalom! If only I could have died in your place! Absalom, my son, my son!”'
EXEC add_BibleVerse @BibleId, 110019001, N'Joab was told, “The king is weeping and mourning over Absalom.”'
EXEC add_BibleVerse @BibleId, 110019002, N'So the victory of that day was turned to mourning as far as all the people were concerned. For the people heard on that day, “The king is grieved over his son.”'
EXEC add_BibleVerse @BibleId, 110019003, N'That day the people stole away to go to the city the way people who are embarrassed steal away in fleeing from battle.'
EXEC add_BibleVerse @BibleId, 110019004, N'The king covered his face and cried out loudly, “My son, Absalom! Absalom, my son, my son!”'
EXEC add_BibleVerse @BibleId, 110019005, N'So Joab visited the king at his home. He said, “Today you have embarrassed all your servants who have saved your life this day, as well as the lives of your sons, your daughters, your wives, and your concubines.'
EXEC add_BibleVerse @BibleId, 110019006, N'You seem to love your enemies and hate your friends! For you have as much as declared today that leaders and servants don’t matter to you. I realize now that if Absalom were alive and all of us were dead today, it would be all right with you.'
EXEC add_BibleVerse @BibleId, 110019007, N'So get up now and go out and give some encouragement to your servants. For I swear by the Lord that if you don’t go out there, not a single man will stay here with you tonight! This disaster will be worse for you than any disaster that has overtaken you from your youth right to the present time!”'
EXEC add_BibleVerse @BibleId, 110019008, N'So the king got up and sat at the city gate. When all the people were informed that the king was sitting at the city gate, they all came before him. But the Israelite soldiers had all fled to their own homes.'
EXEC add_BibleVerse @BibleId, 110019009, N'All the people throughout all the tribes of Israel were arguing among themselves saying, “The king delivered us from the hand of our enemies. He rescued us from the hand of the Philistines, but now he has fled from the land because of Absalom.'
EXEC add_BibleVerse @BibleId, 110019010, N'But Absalom, whom we anointed as our king, has died in battle. So now why do you hesitate to bring the king back?”'
EXEC add_BibleVerse @BibleId, 110019011, N'Then King David sent a message to Zadok and Abiathar the priests saying, “Tell the elders of Judah, ‘Why should you delay any further in bringing the king back to his palace, when everything Israel is saying has come to the king’s attention.'
EXEC add_BibleVerse @BibleId, 110019012, N'You are my brothers – my very own flesh and blood! Why should you delay any further in bringing the king back?’'
EXEC add_BibleVerse @BibleId, 110019013, N'Say to Amasa, ‘Are you not my flesh and blood? God will punish me severely, if from this time on you are not the commander of my army in place of Joab!’”'
EXEC add_BibleVerse @BibleId, 110019014, N'He won over the hearts of all the men of Judah as though they were one man. Then they sent word to the king saying, “Return, you and all your servants as well.”'
EXEC add_BibleVerse @BibleId, 110019015, N'So the king returned and came to the Jordan River. Now the people of Judah had come to Gilgal to meet the king and to help him cross the Jordan.'
EXEC add_BibleVerse @BibleId, 110019016, N'Shimei son of Gera the Benjaminite from Bahurim came down quickly with the men of Judah to meet King David.'
EXEC add_BibleVerse @BibleId, 110019017, N'There were a thousand men from Benjamin with him, along with Ziba the servant of Saul’s household, and with him his fifteen sons and twenty servants. They hurriedly crossed the Jordan within sight of the king.'
EXEC add_BibleVerse @BibleId, 110019018, N'They crossed at the ford in order to help the king’s household cross and to do whatever he thought appropriate. Now after he had crossed the Jordan, Shimei son of Gera threw himself down before the king.'
EXEC add_BibleVerse @BibleId, 110019019, N'He said to the king, “Don’t think badly of me, my lord, and don’t recall the sin of your servant on the day when you, my lord the king, left Jerusalem! Please don’t call it to mind!'
EXEC add_BibleVerse @BibleId, 110019020, N'For I, your servant, know that I sinned, and I have come today as the first of all the house of Joseph to come down to meet my lord the king.”'
EXEC add_BibleVerse @BibleId, 110019021, N'Abishai son of Zeruiah replied, “For this should not Shimei be put to death? After all, he cursed the Lord’s anointed!”'
EXEC add_BibleVerse @BibleId, 110019022, N'But David said, “What do we have in common, you sons of Zeruiah? You are like my enemy today! Should anyone be put to death in Israel today? Don’t you realize that today I am king over Israel?”'
EXEC add_BibleVerse @BibleId, 110019023, N'The king said to Shimei, “You won’t die.” The king vowed an oath concerning this.'
EXEC add_BibleVerse @BibleId, 110019024, N'Now Mephibosheth, Saul’s grandson, came down to meet the king. From the day the king had left until the day he safely returned, Mephibosheth had not cared for his feet nor trimmed his mustache nor washed his clothes.'
EXEC add_BibleVerse @BibleId, 110019025, N'When he came from Jerusalem to meet the king, the king asked him, “Why didn’t you go with me, Mephibosheth?”'
EXEC add_BibleVerse @BibleId, 110019026, N'He replied, “My lord the king, my servant deceived me! I said, ‘Let me get my donkey saddled so that I can ride on it and go with the king,’ for I am lame.'
EXEC add_BibleVerse @BibleId, 110019027, N'But my servant has slandered me to my lord the king. But my lord the king is like an angel of God. Do whatever seems appropriate to you.'
EXEC add_BibleVerse @BibleId, 110019028, N'After all, there was no one in the entire house of my grandfather who did not deserve death from my lord the king. But instead you allowed me to eat at your own table! What further claim do I have to ask the king for anything?”'
EXEC add_BibleVerse @BibleId, 110019029, N'Then the king replied to him, “Why should you continue speaking like this? You and Ziba will inherit the field together.”'
EXEC add_BibleVerse @BibleId, 110019030, N'Mephibosheth said to the king, “Let him have the whole thing! My lord the king has returned safely to his house!”'
EXEC add_BibleVerse @BibleId, 110019031, N'Now when Barzillai the Gileadite had come down from Rogelim, he crossed the Jordan with the king so he could send him on his way from there.'
EXEC add_BibleVerse @BibleId, 110019032, N'But Barzillai was very old – eighty years old, in fact – and he had taken care of the king when he stayed in Mahanaim, for he was a very rich man.'
EXEC add_BibleVerse @BibleId, 110019033, N'So the king said to Barzillai, “Cross over with me, and I will take care of you while you are with me in Jerusalem.”'
EXEC add_BibleVerse @BibleId, 110019034, N'Barzillai replied to the king, “How many days do I have left to my life, that I should go up with the king to Jerusalem?'
EXEC add_BibleVerse @BibleId, 110019035, N'I am presently eighty years old. Am I able to discern good and bad? Can I taste what I eat and drink? Am I still able to hear the voices of male and female singers? Why should I continue to be a burden to my lord the king?'
EXEC add_BibleVerse @BibleId, 110019036, N'I will cross the Jordan with the king and go a short distance. Why should the king reward me in this way?'
EXEC add_BibleVerse @BibleId, 110019037, N'Let me return so that I may die in my own city near the grave of my father and my mother. But look, here is your servant Kimham. Let him cross over with my lord the king. Do for him whatever seems appropriate to you.”'
EXEC add_BibleVerse @BibleId, 110019038, N'The king replied, “Kimham will cross over with me, and I will do for him whatever I deem appropriate. And whatever you choose, I will do for you.”'
EXEC add_BibleVerse @BibleId, 110019039, N'So all the people crossed the Jordan, as did the king. After the king had kissed him and blessed him, Barzillai returned to his home.'
EXEC add_BibleVerse @BibleId, 110019040, N'When the king crossed over to Gilgal, Kimham crossed over with him. Now all the soldiers of Judah along with half of the soldiers of Israel had helped the king cross over.'
EXEC add_BibleVerse @BibleId, 110019041, N'Then all the men of Israel began coming to the king. They asked the king, “Why did our brothers, the men of Judah, sneak the king away and help the king and his household cross the Jordan – and not only him but all of David’s men as well?”'
EXEC add_BibleVerse @BibleId, 110019042, N'All the men of Judah replied to the men of Israel, “Because the king is our close relative! Why are you so upset about this? Have we eaten at the king’s expense? Or have we misappropriated anything for our own use?”'
EXEC add_BibleVerse @BibleId, 110019043, N'The men of Israel replied to the men of Judah, “We have ten shares in the king, and we have a greater claim on David than you do! Why do you want to curse us? Weren’t we the first to suggest bringing back our king?” But the comments of the men of Judah were more severe than those of the men of Israel.'
EXEC add_BibleVerse @BibleId, 110020001, N'Now a wicked man named Sheba son of Bicri, a Benjaminite, happened to be there. He blew the trumpet and said, “We have no share in David; we have no inheritance in this son of Jesse! Every man go home, O Israel!”'
EXEC add_BibleVerse @BibleId, 110020002, N'So all the men of Israel deserted David and followed Sheba son of Bicri. But the men of Judah stuck by their king all the way from the Jordan River to Jerusalem.'
EXEC add_BibleVerse @BibleId, 110020003, N'Then David went to his palace in Jerusalem. The king took the ten concubines he had left to care for the palace and placed them under confinement. Though he provided for their needs, he did not have sexual relations with them. They remained in confinement until the day they died, living out the rest of their lives as widows.'
EXEC add_BibleVerse @BibleId, 110020004, N'Then the king said to Amasa, “Call the men of Judah together for me in three days, and you be present here with them too.”'
EXEC add_BibleVerse @BibleId, 110020005, N'So Amasa went out to call Judah together. But in doing so he took longer than the time that the king had allotted him.'
EXEC add_BibleVerse @BibleId, 110020006, N'Then David said to Abishai, “Now Sheba son of Bicri will cause greater disaster for us than Absalom did! Take your lord’s servants and pursue him. Otherwise he will secure fortified cities for himself and get away from us.”'
EXEC add_BibleVerse @BibleId, 110020007, N'So Joab’s men, accompanied by the Kerethites, the Pelethites, and all the warriors, left Jerusalem to pursue Sheba son of Bicri.'
EXEC add_BibleVerse @BibleId, 110020008, N'When they were near the big rock that is in Gibeon, Amasa came to them. Now Joab was dressed in military attire and had a dagger in its sheath belted to his waist. When he advanced, it fell out.'
EXEC add_BibleVerse @BibleId, 110020009, N'Joab said to Amasa, “How are you, my brother?” With his right hand Joab took hold of Amasa’s beard as if to greet him with a kiss.'
EXEC add_BibleVerse @BibleId, 110020010, N'Amasa did not protect himself from the knife in Joab’s other hand, and Joab stabbed him in the abdomen, causing Amasa’s intestines to spill out on the ground. There was no need to stab him again; the first blow was fatal. Then Joab and his brother Abishai pursued Sheba son of Bicri.'
EXEC add_BibleVerse @BibleId, 110020011, N'One of Joab’s soldiers who stood over Amasa said, “Whoever is for Joab and whoever is for David, follow Joab!”'
EXEC add_BibleVerse @BibleId, 110020012, N'Amasa was squirming in his own blood in the middle of the path, and this man had noticed that all the soldiers stopped. Having noticed that everyone who came across Amasa stopped, the man pulled him away from the path and into the field and threw a garment over him.'
EXEC add_BibleVerse @BibleId, 110020013, N'Once he had removed Amasa from the path, everyone followed Joab to pursue Sheba son of Bicri.'
EXEC add_BibleVerse @BibleId, 110020014, N'Sheba traveled through all the tribes of Israel to Abel of Beth Maacah and all the Berite region. When they had assembled, they too joined him.'
EXEC add_BibleVerse @BibleId, 110020015, N'So Joab’s men came and laid siege against him in Abel of Beth Maacah. They prepared a siege ramp outside the city which stood against its outer rampart. As all of Joab’s soldiers were trying to break through the wall so that it would collapse,'
EXEC add_BibleVerse @BibleId, 110020016, N'a wise woman called out from the city, “Listen up! Listen up! Tell Joab, ‘Come near so that I may speak to you.’”'
EXEC add_BibleVerse @BibleId, 110020017, N'When he approached her, the woman asked, “Are you Joab?” He replied, “I am.” She said to him, “Listen to the words of your servant.” He said, “Go ahead. I’m listening.”'
EXEC add_BibleVerse @BibleId, 110020018, N'She said, “In the past they would always say, ‘Let them inquire in Abel,’ and that is how they settled things.'
EXEC add_BibleVerse @BibleId, 110020019, N'I represent the peaceful and the faithful in Israel. You are attempting to destroy an important city in Israel. Why should you swallow up the Lord’s inheritance?”'
EXEC add_BibleVerse @BibleId, 110020020, N'Joab answered, “Get serious! I don’t want to swallow up or destroy anything!'
EXEC add_BibleVerse @BibleId, 110020021, N'That’s not the way things are. There is a man from the hill country of Ephraim named Sheba son of Bicri. He has rebelled against King David. Give me just this one man, and I will leave the city.” The woman said to Joab, “This very minute his head will be thrown over the wall to you!”'
EXEC add_BibleVerse @BibleId, 110020022, N'Then the woman went to all the people with her wise advice and they cut off Sheba’s head and threw it out to Joab. Joab blew the trumpet, and his men dispersed from the city, each going to his own home. Joab returned to the king in Jerusalem.'
EXEC add_BibleVerse @BibleId, 110020023, N'Now Joab was the general in command of all the army of Israel. Benaiah the son of Jehoida was over the Kerethites and the Perethites.'
EXEC add_BibleVerse @BibleId, 110020024, N'Adoniram was supervisor of the work crews. Jehoshaphat son of Ahilud was the secretary.'
EXEC add_BibleVerse @BibleId, 110020025, N'Sheva was the scribe, and Zadok and Abiathar were the priests.'
EXEC add_BibleVerse @BibleId, 110020026, N'Ira the Jairite was David’s personal priest.'
EXEC add_BibleVerse @BibleId, 110021001, N'During David’s reign there was a famine for three consecutive years. So David inquired of the Lord. The Lord said, “It is because of Saul and his bloodstained family, because he murdered the Gibeonites.”'
EXEC add_BibleVerse @BibleId, 110021002, N'So the king summoned the Gibeonites and spoke with them. (Now the Gibeonites were not descendants of Israel; they were a remnant of the Amorites. The Israelites had made a promise to them, but Saul tried to kill them because of his zeal for the people of Israel and Judah.)'
EXEC add_BibleVerse @BibleId, 110021003, N'David said to the Gibeonites, “What can I do for you, and how can I make amends so that you will bless the Lord’s inheritance?”'
EXEC add_BibleVerse @BibleId, 110021004, N'The Gibeonites said to him, “We have no claim to silver or gold from Saul or from his family, nor would we be justified in putting to death anyone in Israel.” David asked, “What then are you asking me to do for you?”'
EXEC add_BibleVerse @BibleId, 110021005, N'They replied to the king, “As for this man who exterminated us and who schemed against us so that we were destroyed and left without status throughout all the borders of Israel –'
EXEC add_BibleVerse @BibleId, 110021006, N'let seven of his male descendants be turned over to us, and we will execute them before the Lord in Gibeah of Saul, who was the Lord’s chosen one.” The king replied, “I will turn them over.”'
EXEC add_BibleVerse @BibleId, 110021007, N'The king had mercy on Mephibosheth son of Jonathan, the son of Saul, in light of the Lord’s oath that had been taken between David and Jonathan son of Saul.'
EXEC add_BibleVerse @BibleId, 110021008, N'So the king took Armoni and Mephibosheth, the two sons of Aiah’s daughter Rizpah whom she had born to Saul, and the five sons of Saul’s daughter Merab whom she had born to Adriel the son of Barzillai the Meholathite.'
EXEC add_BibleVerse @BibleId, 110021009, N'He turned them over to the Gibeonites, and they executed them on a hill before the Lord. The seven of them died together; they were put to death during harvest time – during the first days of the beginning of the barley harvest.'
EXEC add_BibleVerse @BibleId, 110021010, N'Rizpah the daughter of Aiah took sackcloth and spread it out for herself on a rock. From the beginning of the harvest until the rain fell on them, she did not allow the birds of the air to feed on them by day, nor the wild animals by night.'
EXEC add_BibleVerse @BibleId, 110021011, N'When David was told what Rizpah daughter of Aiah, Saul’s concubine, had done,'
EXEC add_BibleVerse @BibleId, 110021012, N'he went and took the bones of Saul and of his son Jonathan from the leaders of Jabesh Gilead. (They had secretly taken them from the plaza at Beth Shan. It was there that Philistines publicly exposed their corpses after they had killed Saul at Gilboa.)'
EXEC add_BibleVerse @BibleId, 110021013, N'David brought the bones of Saul and of Jonathan his son from there; they also gathered up the bones of those who had been executed.'
EXEC add_BibleVerse @BibleId, 110021014, N'They buried the bones of Saul and his son Jonathan in the land of Benjamin at Zela in the grave of his father Kish. After they had done everything that the king had commanded, God responded to their prayers for the land.'
EXEC add_BibleVerse @BibleId, 110021015, N'Another battle was fought between the Philistines and Israel. So David went down with his soldiers and fought the Philistines. David became exhausted.'
EXEC add_BibleVerse @BibleId, 110021016, N'Now Ishbi-Benob, one of the descendants of Rapha, had a spear that weighed three hundred bronze shekels, and he was armed with a new weapon. He had said that he would kill David.'
EXEC add_BibleVerse @BibleId, 110021017, N'But Abishai the son of Zeruiah came to David’s aid, striking the Philistine down and killing him. Then David’s men took an oath saying, “You will not go out to battle with us again! You must not extinguish the lamp of Israel!”'
EXEC add_BibleVerse @BibleId, 110021018, N'Later there was another battle with the Philistines, this time in Gob. On that occasion Sibbekai the Hushathite killed Saph, who was one of the descendants of Rapha.'
EXEC add_BibleVerse @BibleId, 110021019, N'Yet another battle occurred with the Philistines in Gob. On that occasion Elhanan the son of Jair the Bethlehemite killed the brother of Goliath the Gittite, the shaft of whose spear was like a weaver’s beam.'
EXEC add_BibleVerse @BibleId, 110021020, N'Yet another battle occurred in Gath. On that occasion there was a large man who had six fingers on each hand and six toes on each foot, twenty-four in all! He too was a descendant of Rapha.'
EXEC add_BibleVerse @BibleId, 110021021, N'When he taunted Israel, Jonathan, the son of David’s brother Shimeah, killed him.'
EXEC add_BibleVerse @BibleId, 110021022, N'These four were the descendants of Rapha who lived in Gath; they were killed by David and his soldiers.'
EXEC add_BibleVerse @BibleId, 110022001, N'David sang to the Lord the words of this song when the Lord rescued him from the power of all his enemies, including Saul.'
EXEC add_BibleVerse @BibleId, 110022002, N'He said: “The Lord is my high ridge, my stronghold, my deliverer.'
EXEC add_BibleVerse @BibleId, 110022003, N'My God is my rocky summit where I take shelter, my shield, the horn that saves me, my stronghold, my refuge, my savior. You save me from violence!'
EXEC add_BibleVerse @BibleId, 110022004, N'I called to the Lord, who is worthy of praise, and I was delivered from my enemies.'
EXEC add_BibleVerse @BibleId, 110022005, N'The waves of death engulfed me; the currents of chaos overwhelmed me.'
EXEC add_BibleVerse @BibleId, 110022006, N'The ropes of Sheol tightened around me; the snares of death trapped me.'
EXEC add_BibleVerse @BibleId, 110022007, N'In my distress I called to the Lord; I called to my God. From his heavenly temple he heard my voice; he listened to my cry for help.'
EXEC add_BibleVerse @BibleId, 110022008, N'The earth heaved and shook; the foundations of the sky trembled. They heaved because he was angry.'
EXEC add_BibleVerse @BibleId, 110022009, N'Smoke ascended from his nose; fire devoured as it came from his mouth; he hurled down fiery coals.'
EXEC add_BibleVerse @BibleId, 110022010, N'He made the sky sink as he descended; a thick cloud was under his feet.'
EXEC add_BibleVerse @BibleId, 110022011, N'He mounted a winged angel and flew; he glided on the wings of the wind.'
EXEC add_BibleVerse @BibleId, 110022012, N'He shrouded himself in darkness, in thick rain clouds.'
EXEC add_BibleVerse @BibleId, 110022013, N'From the brightness in front of him came coals of fire.'
EXEC add_BibleVerse @BibleId, 110022014, N'The Lord thundered from the sky; the sovereign One shouted loudly.'
EXEC add_BibleVerse @BibleId, 110022015, N'He shot arrows and scattered them, lightning and routed them.'
EXEC add_BibleVerse @BibleId, 110022016, N'The depths of the sea were exposed; the inner regions of the world were uncovered by the Lord’s battle cry, by the powerful breath from his nose.'
EXEC add_BibleVerse @BibleId, 110022017, N'He reached down from above and grabbed me; he pulled me from the surging water.'
EXEC add_BibleVerse @BibleId, 110022018, N'He rescued me from my strong enemy, from those who hate me, for they were too strong for me.'
EXEC add_BibleVerse @BibleId, 110022019, N'They confronted me in my day of calamity, but the Lord helped me.'
EXEC add_BibleVerse @BibleId, 110022020, N'He brought me out into a wide open place; he delivered me because he was pleased with me.'
EXEC add_BibleVerse @BibleId, 110022021, N'The Lord repaid me for my godly deeds; he rewarded my blameless behavior.'
EXEC add_BibleVerse @BibleId, 110022022, N'For I have obeyed the Lord’s commands; I have not rebelled against my God.'
EXEC add_BibleVerse @BibleId, 110022023, N'For I am aware of all his regulations, and I do not reject his rules.'
EXEC add_BibleVerse @BibleId, 110022024, N'I was blameless before him; I kept myself from sinning.'
EXEC add_BibleVerse @BibleId, 110022025, N'The Lord rewarded me for my godly deeds; he took notice of my blameless behavior.'
EXEC add_BibleVerse @BibleId, 110022026, N'You prove to be loyal to one who is faithful; you prove to be trustworthy to one who is innocent.'
EXEC add_BibleVerse @BibleId, 110022027, N'You prove to be reliable to one who is blameless, but you prove to be deceptive to one who is perverse.'
EXEC add_BibleVerse @BibleId, 110022028, N'You deliver oppressed people, but you watch the proud and bring them down.'
EXEC add_BibleVerse @BibleId, 110022029, N'Indeed, you are my lamp, Lord. The Lord illumines the darkness around me.'
EXEC add_BibleVerse @BibleId, 110022030, N'Indeed, with your help I can charge against an army; by my God’s power I can jump over a wall.'
EXEC add_BibleVerse @BibleId, 110022031, N'The one true God acts in a faithful manner; the Lord’s promise is reliable; he is a shield to all who take shelter in him.'
EXEC add_BibleVerse @BibleId, 110022032, N'Indeed, who is God besides the Lord? Who is a protector besides our God?'
EXEC add_BibleVerse @BibleId, 110022033, N'The one true God is my mighty refuge; he removes the obstacles in my way.'
EXEC add_BibleVerse @BibleId, 110022034, N'He gives me the agility of a deer; he enables me to negotiate the rugged terrain.'
EXEC add_BibleVerse @BibleId, 110022035, N'He trains my hands for battle; my arms can bend even the strongest bow.'
EXEC add_BibleVerse @BibleId, 110022036, N'You give me your protective shield; your willingness to help enables me to prevail.'
EXEC add_BibleVerse @BibleId, 110022037, N'You widen my path; my feet do not slip.'
EXEC add_BibleVerse @BibleId, 110022038, N'I chase my enemies and destroy them; I do not turn back until I wipe them out.'
EXEC add_BibleVerse @BibleId, 110022039, N'I wipe them out and beat them to death; they cannot get up; they fall at my feet.'
EXEC add_BibleVerse @BibleId, 110022040, N'You give me strength for battle; you make my foes kneel before me.'
EXEC add_BibleVerse @BibleId, 110022041, N'You make my enemies retreat; I destroy those who hate me.'
EXEC add_BibleVerse @BibleId, 110022042, N'They cry out, but there is no one to help them; they cry out to the Lord, but he does not answer them.'
EXEC add_BibleVerse @BibleId, 110022043, N'I grind them as fine as the dust of the ground; I crush them and stomp on them like clay in the streets.'
EXEC add_BibleVerse @BibleId, 110022044, N'You rescue me from a hostile army; you preserve me as a leader of nations; people over whom I had no authority are now my subjects.'
EXEC add_BibleVerse @BibleId, 110022045, N'Foreigners are powerless before me; when they hear of my exploits, they submit to me.'
EXEC add_BibleVerse @BibleId, 110022046, N'Foreigners lose their courage; they shake with fear as they leave their strongholds.'
EXEC add_BibleVerse @BibleId, 110022047, N'The Lord is alive! My protector is praiseworthy! The God who delivers me is exalted as king!'
EXEC add_BibleVerse @BibleId, 110022048, N'The one true God completely vindicates me; he makes nations submit to me.'
EXEC add_BibleVerse @BibleId, 110022049, N'He delivers me from my enemies; you snatch me away from those who attack me; you rescue me from violent men.'
EXEC add_BibleVerse @BibleId, 110022050, N'So I will give you thanks, O Lord, before the nations! I will sing praises to you.'
EXEC add_BibleVerse @BibleId, 110022051, N'He gives his chosen king magnificent victories; he is faithful to his chosen ruler, to David and to his descendants forever!”'
EXEC add_BibleVerse @BibleId, 110023001, N'These are the final words of David: “The oracle of David son of Jesse, the oracle of the man raised up as the ruler chosen by the God of Jacob, Israel’s beloved singer of songs:'
EXEC add_BibleVerse @BibleId, 110023002, N'The Lord’s spirit spoke through me; his word was on my tongue.'
EXEC add_BibleVerse @BibleId, 110023003, N'The God of Israel spoke, the protector of Israel spoke to me. The one who rules fairly among men, the one who rules in the fear of God,'
EXEC add_BibleVerse @BibleId, 110023004, N'is like the light of morning when the sun comes up, a morning in which there are no clouds. He is like the brightness after rain that produces grass from the earth.'
EXEC add_BibleVerse @BibleId, 110023005, N'My dynasty is approved by God, for he has made a perpetual covenant with me, arranged in all its particulars and secured. He always delivers me, and brings all I desire to fruition.'
EXEC add_BibleVerse @BibleId, 110023006, N'But evil people are like thorns – all of them are tossed away, for they cannot be held in the hand.'
EXEC add_BibleVerse @BibleId, 110023007, N'The one who touches them must use an iron instrument or the wooden shaft of a spear. They are completely burned up right where they lie!”'
EXEC add_BibleVerse @BibleId, 110023008, N'These are the names of David’s warriors: Josheb-Basshebeth, a Tahkemonite, was head of the officers. He killed eight hundred men with his spear in one battle.'
EXEC add_BibleVerse @BibleId, 110023009, N'Next in command was Eleazar son of Dodo, the son of Ahohi. He was one of the three warriors who were with David when they defied the Philistines who were assembled there for battle. When the men of Israel retreated,'
EXEC add_BibleVerse @BibleId, 110023010, N'he stood his ground and fought the Philistines until his hand grew so tired that it seemed stuck to his sword. The Lord gave a great victory on that day. When the army returned to him, the only thing left to do was to plunder the corpses.'
EXEC add_BibleVerse @BibleId, 110023011, N'Next in command was Shammah son of Agee the Hararite. When the Philistines assembled at Lehi, where there happened to be an area of a field that was full of lentils, the army retreated before the Philistines.'
EXEC add_BibleVerse @BibleId, 110023012, N'But he made a stand in the middle of that area. He defended it and defeated the Philistines; the Lord gave them a great victory.'
EXEC add_BibleVerse @BibleId, 110023013, N'At the time of the harvest three of the thirty leaders went down to David at the cave of Adullam. A band of Philistines was camped in the valley of Rephaim.'
EXEC add_BibleVerse @BibleId, 110023014, N'David was in the stronghold at the time, while a Philistine garrison was in Bethlehem.'
EXEC add_BibleVerse @BibleId, 110023015, N'David was thirsty and said, “How I wish someone would give me some water to drink from the cistern in Bethlehem near the gate!”'
EXEC add_BibleVerse @BibleId, 110023016, N'So the three elite warriors broke through the Philistine forces and drew some water from the cistern in Bethlehem near the gate. They carried it back to David, but he refused to drink it. He poured it out as a drink offering to the Lord'
EXEC add_BibleVerse @BibleId, 110023017, N'and said, “O Lord, I will not do this! It is equivalent to the blood of the men who risked their lives by going.” So he refused to drink it. Such were the exploits of the three elite warriors.'
EXEC add_BibleVerse @BibleId, 110023018, N'Abishai son of Zeruiah, the brother of Joab, was head of the three. He killed three hundred men with his spear and gained fame among the three.'
EXEC add_BibleVerse @BibleId, 110023019, N'From the three he was given honor and he became their officer, even though he was not one of the three.'
EXEC add_BibleVerse @BibleId, 110023020, N'Benaiah son of Jehoida was a brave warrior from Kabzeel who performed great exploits. He struck down the two sons of Ariel of Moab. He also went down and killed a lion in a cistern on a snowy day.'
EXEC add_BibleVerse @BibleId, 110023021, N'He also killed an impressive-looking Egyptian. The Egyptian wielded a spear, while Benaiah attacked him with a club. He grabbed the spear out of the Egyptian’s hand and killed him with his own spear.'
EXEC add_BibleVerse @BibleId, 110023022, N'Such were the exploits of Benaiah son of Jehoida, who gained fame among the three elite warriors.'
EXEC add_BibleVerse @BibleId, 110023023, N'He received honor from the thirty warriors, though he was not one of the three elite warriors. David put him in charge of his bodyguard.'
EXEC add_BibleVerse @BibleId, 110023024, N'Included with the thirty were the following: Asahel the brother of Joab, Elhanan son of Dodo from Bethlehem,'
EXEC add_BibleVerse @BibleId, 110023025, N'Shammah the Harodite, Elika the Harodite,'
EXEC add_BibleVerse @BibleId, 110023026, N'Helez the Paltite, Ira son of Ikkesh from Tekoa,'
EXEC add_BibleVerse @BibleId, 110023027, N'Abiezer the Anathothite, Mebunnai the Hushathite,'
EXEC add_BibleVerse @BibleId, 110023028, N'Zalmon the Ahohite, Maharai the Netophathite,'
EXEC add_BibleVerse @BibleId, 110023029, N'Heled son of Baanah the Netophathite, Ittai son of Ribai from Gibeah in Benjamin,'
EXEC add_BibleVerse @BibleId, 110023030, N'Benaiah the Pirathonite, Hiddai from the wadis of Gaash,'
EXEC add_BibleVerse @BibleId, 110023031, N'Abi-Albon the Arbathite, Azmaveth the Barhumite,'
EXEC add_BibleVerse @BibleId, 110023032, N'Eliahba the Shaalbonite, the sons of Jashen, Jonathan'
EXEC add_BibleVerse @BibleId, 110023033, N'son of Shammah the Hararite, Ahiam son of Sharar the Hararite,'
EXEC add_BibleVerse @BibleId, 110023034, N'Eliphelet son of Ahasbai the Maacathite, Eliam son of Ahithophel the Gilonite,'
EXEC add_BibleVerse @BibleId, 110023035, N'Hezrai the Carmelite, Paarai the Arbite,'
EXEC add_BibleVerse @BibleId, 110023036, N'Igal son of Nathan from Zobah, Bani the Gadite,'
EXEC add_BibleVerse @BibleId, 110023037, N'Zelek the Ammonite, Naharai the Beerothite (the armor-bearer of Joab son of Zeruiah),'
EXEC add_BibleVerse @BibleId, 110023038, N'Ira the Ithrite, Gareb the Ithrite'
EXEC add_BibleVerse @BibleId, 110023039, N'and Uriah the Hittite. Altogether there were thirty-seven.'
EXEC add_BibleVerse @BibleId, 110024001, N'The Lord’s anger again raged against Israel, and he incited David against them, saying, “Go count Israel and Judah.”'
EXEC add_BibleVerse @BibleId, 110024002, N'The king told Joab, the general in command of his army, “Go through all the tribes of Israel from Dan to Beer Sheba and muster the army, so I may know the size of the army.”'
EXEC add_BibleVerse @BibleId, 110024003, N'Joab replied to the king, “May the Lord your God make the army a hundred times larger right before the eyes of my lord the king! But why does my master the king want to do this?”'
EXEC add_BibleVerse @BibleId, 110024004, N'But the king’s edict stood, despite the objections of Joab and the leaders of the army. So Joab and the leaders of the army left the king’s presence in order to muster the Israelite army.'
EXEC add_BibleVerse @BibleId, 110024005, N'They crossed the Jordan and camped at Aroer, on the south side of the city, at the wadi of Gad, near Jazer.'
EXEC add_BibleVerse @BibleId, 110024006, N'Then they went on to Gilead and to the region of Tahtim Hodshi, coming to Dan Jaan and on around to Sidon.'
EXEC add_BibleVerse @BibleId, 110024007, N'Then they went to the fortress of Tyre and all the cities of the Hivites and the Canaanites. Then they went on to the Negev of Judah, to Beer Sheba.'
EXEC add_BibleVerse @BibleId, 110024008, N'They went through all the land and after nine months and twenty days came back to Jerusalem.'
EXEC add_BibleVerse @BibleId, 110024009, N'Joab reported the number of warriors to the king. In Israel there were 800,000 sword-wielding warriors, and in Judah there were 500,000 soldiers.'
EXEC add_BibleVerse @BibleId, 110024010, N'David felt guilty after he had numbered the army. David said to the Lord, “I have sinned greatly by doing this! Now, O Lord, please remove the guilt of your servant, for I have acted very foolishly.”'
EXEC add_BibleVerse @BibleId, 110024011, N'When David got up the next morning, the Lord had already spoken to Gad the prophet, David’s seer:'
EXEC add_BibleVerse @BibleId, 110024012, N'“Go, tell David, ‘This is what the Lord says: I am offering you three forms of judgment. Pick one of them and I will carry it out against you.’”'
EXEC add_BibleVerse @BibleId, 110024013, N'Gad went to David and told him, “Shall seven years of famine come upon your land? Or shall you flee for three months from your enemy with him in hot pursuit? Or shall there be three days of plague in your land? Now decide what I should tell the one who sent me.”'
EXEC add_BibleVerse @BibleId, 110024014, N'David said to Gad, “I am very upset! I prefer that we be attacked by the Lord, for his mercy is great; I do not want to be attacked by men!”'
EXEC add_BibleVerse @BibleId, 110024015, N'So the Lord sent a plague through Israel from the morning until the completion of the appointed time. Seventy thousand men died from Dan to Beer Sheba.'
EXEC add_BibleVerse @BibleId, 110024016, N'When the angel extended his hand to destroy Jerusalem, the Lord relented from his judgment. He told the angel who was killing the people, “That’s enough! Stop now!” (Now the Lord’s angel was near the threshing floor of Araunah the Jebusite.)'
EXEC add_BibleVerse @BibleId, 110024017, N'When he saw the angel who was destroying the people, David said to the Lord, “Look, it is I who have sinned and done this evil thing! As for these sheep – what have they done? Attack me and my family.”'
EXEC add_BibleVerse @BibleId, 110024018, N'So Gad went to David that day and told him, “Go up and build an altar for the Lord on the threshing floor of Araunah the Jebusite.”'
EXEC add_BibleVerse @BibleId, 110024019, N'So David went up as Gad instructed him to do, according to the Lord’s instructions.'
EXEC add_BibleVerse @BibleId, 110024020, N'When Araunah looked out and saw the king and his servants approaching him, he went out and bowed to the king with his face to the ground.'
EXEC add_BibleVerse @BibleId, 110024021, N'Araunah said, “Why has my lord the king come to his servant?” David replied, “To buy from you the threshing floor so I can build an altar for the Lord, so that the plague may be removed from the people.”'
EXEC add_BibleVerse @BibleId, 110024022, N'Araunah told David, “My lord the king may take whatever he wishes and offer it. Look! Here are oxen for burnt offerings, and threshing sledges and harnesses for wood.'
EXEC add_BibleVerse @BibleId, 110024023, N'I, the servant of my lord the king, give it all to the king!” Araunah also told the king, “May the Lord your God show you favor!”'
EXEC add_BibleVerse @BibleId, 110024024, N'But the king said to Araunah, “No, I insist on buying it from you! I will not offer to the Lord my God burnt sacrifices that cost me nothing.” So David bought the threshing floor and the oxen for fifty pieces of silver.'
EXEC add_BibleVerse @BibleId, 110024025, N'Then David built an altar for the Lord there and offered burnt sacrifices and peace offerings. And the Lord accepted prayers for the land, and the plague was removed from Israel.'
EXEC add_BibleVerse @BibleId, 111001001, N'King David was very old; even when they covered him with blankets, he could not get warm.'
EXEC add_BibleVerse @BibleId, 111001002, N'His servants advised him, “A young virgin must be found for our master, the king, to take care of the king’s needs and serve as his nurse. She can also sleep with you and keep our master, the king, warm.”'
EXEC add_BibleVerse @BibleId, 111001003, N'So they looked through all Israel for a beautiful young woman and found Abishag, a Shunammite, and brought her to the king.'
EXEC add_BibleVerse @BibleId, 111001004, N'The young woman was very beautiful; she became the king’s nurse and served him, but the king did not have sexual relations with her.'
EXEC add_BibleVerse @BibleId, 111001005, N'Now Adonijah, son of David and Haggith, was promoting himself, boasting, “I will be king!” He managed to acquire chariots and horsemen, as well as fifty men to serve as his royal guard.'
EXEC add_BibleVerse @BibleId, 111001006, N'(Now his father had never corrected him by saying, “Why do you do such things?” He was also very handsome and had been born right after Absalom. )'
EXEC add_BibleVerse @BibleId, 111001007, N'He collaborated with Joab son of Zeruiah and with Abiathar the priest, and they supported him.'
EXEC add_BibleVerse @BibleId, 111001008, N'But Zadok the priest, Benaiah son of Jehoiada, Nathan the prophet, Shimei, Rei, and David’s elite warriors did not ally themselves with Adonijah.'
EXEC add_BibleVerse @BibleId, 111001009, N'Adonijah sacrificed sheep, cattle, and fattened steers at the Stone of Zoheleth near En Rogel. He invited all his brothers, the king’s sons, as well as all the men of Judah, the king’s servants.'
EXEC add_BibleVerse @BibleId, 111001010, N'But he did not invite Nathan the prophet, Benaiah, the elite warriors, or his brother Solomon.'
EXEC add_BibleVerse @BibleId, 111001011, N'Nathan said to Bathsheba, Solomon’s mother, “Has it been reported to you that Haggith’s son Adonijah has become king behind our master David’s back?'
EXEC add_BibleVerse @BibleId, 111001012, N'Now let me give you some advice as to how you can save your life and your son Solomon’s life.'
EXEC add_BibleVerse @BibleId, 111001013, N'Visit King David and say to him, ‘My master, O king, did you not solemnly promise your servant, “Surely your son Solomon will be king after me; he will sit on my throne”? So why has Adonijah become king?’'
EXEC add_BibleVerse @BibleId, 111001014, N'While you are still there speaking to the king, I will arrive and verify your report.”'
EXEC add_BibleVerse @BibleId, 111001015, N'So Bathsheba visited the king in his private quarters. (The king was very old, and Abishag the Shunammite was serving the king.)'
EXEC add_BibleVerse @BibleId, 111001016, N'Bathsheba bowed down on the floor before the king. The king said, “What do you want?”'
EXEC add_BibleVerse @BibleId, 111001017, N'She replied to him, “My master, you swore an oath to your servant by the Lord your God, ‘Solomon your son will be king after me and he will sit on my throne.’'
EXEC add_BibleVerse @BibleId, 111001018, N'But now, look, Adonijah has become king! But you, my master the king, are not even aware of it!'
EXEC add_BibleVerse @BibleId, 111001019, N'He has sacrificed many cattle, steers, and sheep and has invited all the king’s sons, Abiathar the priest, and Joab, the commander of the army, but he has not invited your servant Solomon.'
EXEC add_BibleVerse @BibleId, 111001020, N'Now, my master, O king, all Israel is watching anxiously to see who is named to succeed my master the king on the throne.'
EXEC add_BibleVerse @BibleId, 111001021, N'If a decision is not made, when my master the king is buried with his ancestors, my son Solomon and I will be considered state criminals.”'
EXEC add_BibleVerse @BibleId, 111001022, N'Just then, while she was still speaking to the king, Nathan the prophet arrived.'
EXEC add_BibleVerse @BibleId, 111001023, N'The king was told, “Nathan the prophet is here.” Nathan entered and bowed before the king with his face to the floor.'
EXEC add_BibleVerse @BibleId, 111001024, N'Nathan said, “My master, O king, did you announce, ‘Adonijah will be king after me; he will sit on my throne’?'
EXEC add_BibleVerse @BibleId, 111001025, N'For today he has gone down and sacrificed many cattle, steers, and sheep and has invited all the king’s sons, the army commanders, and Abiathar the priest. At this moment they are having a feast in his presence, and they have declared, ‘Long live King Adonijah!’'
EXEC add_BibleVerse @BibleId, 111001026, N'But he did not invite me – your servant – or Zadok the priest, or Benaiah son of Jehoiada, or your servant Solomon.'
EXEC add_BibleVerse @BibleId, 111001027, N'Has my master the king authorized this without informing your servants who should succeed my master the king on his throne?”'
EXEC add_BibleVerse @BibleId, 111001028, N'King David responded, “Summon Bathsheba!” She came and stood before the king.'
EXEC add_BibleVerse @BibleId, 111001029, N'The king swore an oath: “As certainly as the Lord lives (he who has rescued me from every danger),'
EXEC add_BibleVerse @BibleId, 111001030, N'I will keep today the oath I swore to you by the Lord God of Israel: ‘Surely Solomon your son will be king after me; he will sit in my place on my throne.’”'
EXEC add_BibleVerse @BibleId, 111001031, N'Bathsheba bowed down to the king with her face to the floor and said, “May my master, King David, live forever!”'
EXEC add_BibleVerse @BibleId, 111001032, N'King David said, “Summon Zadok the priest, Nathan the prophet, and Benaiah son of Jehoiada.” They came before the king,'
EXEC add_BibleVerse @BibleId, 111001033, N'and he told them, “Take your master’s servants with you, put my son Solomon on my mule, and lead him down to Gihon.'
EXEC add_BibleVerse @BibleId, 111001034, N'There Zadok the priest and Nathan the prophet will anoint him king over Israel; then blow the trumpet and declare, ‘Long live King Solomon!’'
EXEC add_BibleVerse @BibleId, 111001035, N'Then follow him up as he comes and sits on my throne. He will be king in my place; I have decreed that he will be ruler over Israel and Judah.”'
EXEC add_BibleVerse @BibleId, 111001036, N'Benaiah son of Jehoiada responded to the king: “So be it! May the Lord God of my master the king confirm it!'
EXEC add_BibleVerse @BibleId, 111001037, N'As the Lord is with my master the king, so may he be with Solomon, and may he make him an even greater king than my master King David!”'
EXEC add_BibleVerse @BibleId, 111001038, N'So Zadok the priest, Nathan the prophet, Benaiah son of Jehoiada, the Kerethites, and the Pelethites went down, put Solomon on King David’s mule, and led him to Gihon.'
EXEC add_BibleVerse @BibleId, 111001039, N'Zadok the priest took a horn filled with olive oil from the tent and poured it on Solomon; the trumpet was blown and all the people declared, “Long live King Solomon!”'
EXEC add_BibleVerse @BibleId, 111001040, N'All the people followed him up, playing flutes and celebrating so loudly they made the ground shake.'
EXEC add_BibleVerse @BibleId, 111001041, N'Now Adonijah and all his guests heard the commotion just as they had finished eating. When Joab heard the sound of the trumpet, he asked, “Why is there such a noisy commotion in the city?”'
EXEC add_BibleVerse @BibleId, 111001042, N'As he was still speaking, Jonathan son of Abiathar the priest arrived. Adonijah said, “Come in, for an important man like you must be bringing good news.”'
EXEC add_BibleVerse @BibleId, 111001043, N'Jonathan replied to Adonijah: “No! Our master King David has made Solomon king.'
EXEC add_BibleVerse @BibleId, 111001044, N'The king sent with him Zadok the priest, Nathan the prophet, Benaiah son of Jehoiada, the Kerethites, and the Pelethites and they put him on the king’s mule.'
EXEC add_BibleVerse @BibleId, 111001045, N'Then Zadok the priest and Nathan the prophet anointed him king in Gihon. They went up from there rejoicing, and the city is in an uproar. That is the sound you hear.'
EXEC add_BibleVerse @BibleId, 111001046, N'Furthermore, Solomon has assumed the royal throne.'
EXEC add_BibleVerse @BibleId, 111001047, N'The king’s servants have even come to congratulate our master King David, saying, ‘May your God make Solomon more famous than you and make him an even greater king than you!’ Then the king leaned on the bed'
EXEC add_BibleVerse @BibleId, 111001048, N'and said this: ‘The Lord God of Israel is worthy of praise because today he has placed a successor on my throne and allowed me to see it.’”'
EXEC add_BibleVerse @BibleId, 111001049, N'All of Adonijah’s guests panicked; they jumped up and rushed off their separate ways.'
EXEC add_BibleVerse @BibleId, 111001050, N'Adonijah feared Solomon, so he got up and went and grabbed hold of the horns of the altar.'
EXEC add_BibleVerse @BibleId, 111001051, N'Solomon was told, “Look, Adonijah fears you; see, he has taken hold of the horns of the altar, saying, ‘May King Solomon solemnly promise me today that he will not kill his servant with the sword.’”'
EXEC add_BibleVerse @BibleId, 111001052, N'Solomon said, “If he is a loyal subject, not a hair of his head will be harmed, but if he is found to be a traitor, he will die.”'
EXEC add_BibleVerse @BibleId, 111001053, N'King Solomon sent men to bring him down from the altar. He came and bowed down to King Solomon, and Solomon told him, “Go home.”'
EXEC add_BibleVerse @BibleId, 111002001, N'When David was close to death, he told Solomon his son:'
EXEC add_BibleVerse @BibleId, 111002002, N'“I am about to die. Be strong and become a man!'
EXEC add_BibleVerse @BibleId, 111002003, N'Do the job the Lord your God has assigned you by following his instructions and obeying his rules, commandments, regulations, and laws as written in the law of Moses. Then you will succeed in all you do and seek to accomplish,'
EXEC add_BibleVerse @BibleId, 111002004, N'and the Lord will fulfill his promise to me, ‘If your descendants watch their step and live faithfully in my presence with all their heart and being, then,’ he promised, ‘you will not fail to have a successor on the throne of Israel.’'
EXEC add_BibleVerse @BibleId, 111002005, N'“You know what Joab son of Zeruiah did to me – how he murdered two commanders of the Israelite armies, Abner son of Ner and Amasa son of Jether. During peacetime he struck them down like he would in battle; when he shed their blood as if in battle, he stained his own belt and the sandals on his feet.'
EXEC add_BibleVerse @BibleId, 111002006, N'Do to him what you think is appropriate, but don’t let him live long and die a peaceful death.'
EXEC add_BibleVerse @BibleId, 111002007, N'“Treat fairly the sons of Barzillai of Gilead and provide for their needs, because they helped me when I had to flee from your brother Absalom.'
EXEC add_BibleVerse @BibleId, 111002008, N'“Note well, you still have to contend with Shimei son of Gera, the Benjaminite from Bahurim, who tried to call down upon me a horrible judgment when I went to Mahanaim. He came down and met me at the Jordan, and I solemnly promised him by the Lord, ‘I will not strike you down with the sword.’'
EXEC add_BibleVerse @BibleId, 111002009, N'But now don’t treat him as if he were innocent. You are a wise man and you know how to handle him; make sure he has a bloody death.”'
EXEC add_BibleVerse @BibleId, 111002010, N'Then David passed away and was buried in the city of David.'
EXEC add_BibleVerse @BibleId, 111002011, N'David reigned over Israel forty years; he reigned in Hebron seven years, and in Jerusalem thirty-three years.'
EXEC add_BibleVerse @BibleId, 111002012, N'Solomon sat on his father David’s throne, and his royal authority was firmly solidified.'
EXEC add_BibleVerse @BibleId, 111002013, N'Haggith’s son Adonijah visited Bathsheba, Solomon’s mother. She asked, “Do you come in peace?” He answered, “Yes.”'
EXEC add_BibleVerse @BibleId, 111002014, N'He added, “I have something to say to you.” She replied, “Speak.”'
EXEC add_BibleVerse @BibleId, 111002015, N'He said, “You know that the kingdom was mine and all Israel considered me king. But then the kingdom was given to my brother, for the Lord decided it should be his.'
EXEC add_BibleVerse @BibleId, 111002016, N'Now I’d like to ask you for just one thing. Please don’t refuse me.” She said, “Go ahead and ask.”'
EXEC add_BibleVerse @BibleId, 111002017, N'He said, “Please ask King Solomon if he would give me Abishag the Shunammite as a wife, for he won’t refuse you.”'
EXEC add_BibleVerse @BibleId, 111002018, N'Bathsheba replied, “That’s fine, I’ll speak to the king on your behalf.”'
EXEC add_BibleVerse @BibleId, 111002019, N'So Bathsheba visited King Solomon to speak to him on Adonijah’s behalf. The king got up to greet her, bowed to her, and then sat on his throne. He ordered a throne to be brought for the king’s mother, and she sat at his right hand.'
EXEC add_BibleVerse @BibleId, 111002020, N'She said, “I would like to ask you for just one small favor. Please don’t refuse me.” He said, “Go ahead and ask, my mother, for I would not refuse you.”'
EXEC add_BibleVerse @BibleId, 111002021, N'She said, “Allow Abishag the Shunammite to be given to your brother Adonijah as a wife.”'
EXEC add_BibleVerse @BibleId, 111002022, N'King Solomon answered his mother, “Why just request Abishag the Shunammite for him? Since he is my older brother, you should also request the kingdom for him, for Abiathar the priest, and for Joab son of Zeruiah!”'
EXEC add_BibleVerse @BibleId, 111002023, N'King Solomon then swore an oath by the Lord, “May God judge me severely, if Adonijah does not pay for this request with his life!'
EXEC add_BibleVerse @BibleId, 111002024, N'Now, as certainly as the Lord lives (he who made me secure, allowed me to sit on my father David’s throne, and established a dynasty for me as he promised), Adonijah will be executed today!”'
EXEC add_BibleVerse @BibleId, 111002025, N'King Solomon then sent Benaiah son of Jehoiada, and he killed Adonijah.'
EXEC add_BibleVerse @BibleId, 111002026, N'The king then told Abiathar the priest, “Go back to your property in Anathoth. You deserve to die, but today I will not kill you because you did carry the ark of the sovereign Lord before my father David and you suffered with my father through all his difficult times.”'
EXEC add_BibleVerse @BibleId, 111002027, N'Solomon dismissed Abiathar from his position as priest of the Lord, fulfilling the decree of judgment the Lord made in Shiloh against the family of Eli.'
EXEC add_BibleVerse @BibleId, 111002028, N'When the news reached Joab (for Joab had supported Adonijah, although he had not supported Absalom), he ran to the tent of the Lord and grabbed hold of the horns of the altar.'
EXEC add_BibleVerse @BibleId, 111002029, N'When King Solomon heard that Joab had run to the tent of the Lord and was right there beside the altar, he ordered Benaiah son of Jehoiada, “Go, strike him down.”'
EXEC add_BibleVerse @BibleId, 111002030, N'When Benaiah arrived at the tent of the Lord, he said to him, “The king says, ‘Come out!’” But he replied, “No, I will die here!” So Benaiah sent word to the king and reported Joab’s reply.'
EXEC add_BibleVerse @BibleId, 111002031, N'The king told him, “Do as he said! Strike him down and bury him. Take away from me and from my father’s family the guilt of Joab’s murderous, bloody deeds.'
EXEC add_BibleVerse @BibleId, 111002032, N'May the Lord punish him for the blood he shed; behind my father David’s back he struck down and murdered with the sword two men who were more innocent and morally upright than he – Abner son of Ner, commander of Israel’s army, and Amasa son of Jether, commander of Judah’s army.'
EXEC add_BibleVerse @BibleId, 111002033, N'May Joab and his descendants be perpetually guilty of their shed blood, but may the Lord give perpetual peace to David, his descendants, his family, and his dynasty.”'
EXEC add_BibleVerse @BibleId, 111002034, N'So Benaiah son of Jehoiada went up and executed Joab; he was buried at his home in the wilderness.'
EXEC add_BibleVerse @BibleId, 111002035, N'The king appointed Benaiah son of Jehoiada to take his place at the head of the army, and the king appointed Zadok the priest to take Abiathar’s place.'
EXEC add_BibleVerse @BibleId, 111002036, N'Next the king summoned Shimei and told him, “Build yourself a house in Jerusalem and live there – but you may not leave there to go anywhere!'
EXEC add_BibleVerse @BibleId, 111002037, N'If you ever do leave and cross the Kidron Valley, know for sure that you will certainly die! You will be responsible for your own death.”'
EXEC add_BibleVerse @BibleId, 111002038, N'Shimei said to the king, “My master the king’s proposal is acceptable. Your servant will do as you say.” So Shimei lived in Jerusalem for a long time.'
EXEC add_BibleVerse @BibleId, 111002039, N'Three years later two of Shimei’s servants ran away to King Achish son of Maacah of Gath. Shimei was told, “Look, your servants are in Gath.”'
EXEC add_BibleVerse @BibleId, 111002040, N'So Shimei got up, saddled his donkey, and went to Achish at Gath to find his servants; Shimei went and brought back his servants from Gath.'
EXEC add_BibleVerse @BibleId, 111002041, N'When Solomon was told that Shimei had gone from Jerusalem to Gath and had then returned,'
EXEC add_BibleVerse @BibleId, 111002042, N'the king summoned Shimei and said to him, “You will recall that I made you take an oath by the Lord, and I solemnly warned you, ‘If you ever leave and go anywhere, know for sure that you will certainly die.’ You said to me, ‘The proposal is acceptable; I agree to it.’'
EXEC add_BibleVerse @BibleId, 111002043, N'Why then have you broken the oath you made before the Lord and disobeyed the order I gave you?”'
EXEC add_BibleVerse @BibleId, 111002044, N'Then the king said to Shimei, “You are well aware of the way you mistreated my father David. The Lord will punish you for what you did.'
EXEC add_BibleVerse @BibleId, 111002045, N'But King Solomon will be empowered and David’s dynasty will endure permanently before the Lord.”'
EXEC add_BibleVerse @BibleId, 111002046, N'The king then gave the order to Benaiah son of Jehoiada who went and executed Shimei. So Solomon took firm control of the kingdom.'
EXEC add_BibleVerse @BibleId, 111003001, N'Solomon made an alliance by marriage with Pharaoh, king of Egypt; he married Pharaoh’s daughter. He brought her to the City of David until he could finish building his residence and the temple of the Lord and the wall around Jerusalem.'
EXEC add_BibleVerse @BibleId, 111003002, N'Now the people were offering sacrifices at the high places, because in those days a temple had not yet been built to honor the Lord.'
EXEC add_BibleVerse @BibleId, 111003003, N'Solomon demonstrated his loyalty to the Lord by following the practices of his father David, except that he offered sacrifices and burned incense on the high places.'
EXEC add_BibleVerse @BibleId, 111003004, N'The king went to Gibeon to offer sacrifices, for it had the most prominent of the high places. Solomon would offer up a thousand burnt sacrifices on the altar there.'
EXEC add_BibleVerse @BibleId, 111003005, N'One night in Gibeon the Lord appeared to Solomon in a dream. God said, “Tell me what I should give you.”'
EXEC add_BibleVerse @BibleId, 111003006, N'Solomon replied, “You demonstrated great loyalty to your servant, my father David, as he served you faithfully, properly, and sincerely. You have maintained this great loyalty to this day by allowing his son to sit on his throne.'
EXEC add_BibleVerse @BibleId, 111003007, N'Now, O Lord my God, you have made your servant king in my father David’s place, even though I am only a young man and am inexperienced.'
EXEC add_BibleVerse @BibleId, 111003008, N'Your servant stands among your chosen people; they are a great nation that is too numerous to count or number.'
EXEC add_BibleVerse @BibleId, 111003009, N'So give your servant a discerning mind so he can make judicial decisions for your people and distinguish right from wrong. Otherwise no one is able to make judicial decisions for this great nation of yours.”'
EXEC add_BibleVerse @BibleId, 111003010, N'The Lord was pleased that Solomon made this request.'
EXEC add_BibleVerse @BibleId, 111003011, N'God said to him, “Because you asked for the ability to make wise judicial decisions, and not for long life, or riches, or vengeance on your enemies,'
EXEC add_BibleVerse @BibleId, 111003012, N'I grant your request, and give you a wise and discerning mind superior to that of anyone who has preceded or will succeed you.'
EXEC add_BibleVerse @BibleId, 111003013, N'Furthermore, I am giving you what you did not request – riches and honor so that you will be the greatest king of your generation.'
EXEC add_BibleVerse @BibleId, 111003014, N'If you follow my instructions by obeying my rules and regulations, just as your father David did, then I will grant you long life.”'
EXEC add_BibleVerse @BibleId, 111003015, N'Solomon then woke up and realized it was a dream. He went to Jerusalem, stood before the ark of the Lord’s covenant, offered up burnt sacrifices, presented peace offerings, and held a feast for all his servants.'
EXEC add_BibleVerse @BibleId, 111003016, N'Then two prostitutes came to the king and stood before him.'
EXEC add_BibleVerse @BibleId, 111003017, N'One of the women said, “My master, this woman and I live in the same house. I had a baby while she was with me in the house.'
EXEC add_BibleVerse @BibleId, 111003018, N'Then three days after I had my baby, this woman also had a baby. We were alone; there was no one else in the house except the two of us.'
EXEC add_BibleVerse @BibleId, 111003019, N'This woman’s child suffocated during the night when she rolled on top of him.'
EXEC add_BibleVerse @BibleId, 111003020, N'She got up in the middle of the night and took my son from my side, while your servant was sleeping. She put him in her arms, and put her dead son in my arms.'
EXEC add_BibleVerse @BibleId, 111003021, N'I got up in the morning to nurse my son, and there he was, dead! But when I examined him carefully in the morning, I realized it was not my baby.”'
EXEC add_BibleVerse @BibleId, 111003022, N'The other woman said, “No! My son is alive; your son is dead!” But the first woman replied, “No, your son is dead; my son is alive.” Each presented her case before the king.'
EXEC add_BibleVerse @BibleId, 111003023, N'The king said, “One says, ‘My son is alive; your son is dead,’ while the other says, ‘No, your son is dead; my son is alive.’”'
EXEC add_BibleVerse @BibleId, 111003024, N'The king ordered, “Get me a sword!” So they placed a sword before the king.'
EXEC add_BibleVerse @BibleId, 111003025, N'The king then said, “Cut the living child in two, and give half to one and half to the other!”'
EXEC add_BibleVerse @BibleId, 111003026, N'The real mother spoke up to the king, for her motherly instincts were aroused. She said, “My master, give her the living child! Whatever you do, don’t kill him!” But the other woman said, “Neither one of us will have him! Let them cut him in two!”'
EXEC add_BibleVerse @BibleId, 111003027, N'The king responded, “Give the first woman the living child; don’t kill him. She is the mother.”'
EXEC add_BibleVerse @BibleId, 111003028, N'When all Israel heard about the judicial decision which the king had rendered, they respected the king, for they realized that he possessed supernatural wisdom to make judicial decisions.'
EXEC add_BibleVerse @BibleId, 111004001, N'King Solomon ruled over all Israel.'
EXEC add_BibleVerse @BibleId, 111004002, N'These were his officials: Azariah son of Zadok was the priest.'
EXEC add_BibleVerse @BibleId, 111004003, N'Elihoreph and Ahijah, the sons of Shisha, wrote down what happened. Jehoshaphat son of Ahilud was in charge of the records.'
EXEC add_BibleVerse @BibleId, 111004004, N'Benaiah son of Jehoiada was commander of the army. Zadok and Abiathar were priests.'
EXEC add_BibleVerse @BibleId, 111004005, N'Azariah son of Nathan was supervisor of the district governors. Zabud son of Nathan was a priest and adviser to the king.'
EXEC add_BibleVerse @BibleId, 111004006, N'Ahishar was supervisor of the palace. Adoniram son of Abda was supervisor of the work crews.'
EXEC add_BibleVerse @BibleId, 111004007, N'Solomon had twelve district governors appointed throughout Israel who acquired supplies for the king and his palace. Each was responsible for one month in the year.'
EXEC add_BibleVerse @BibleId, 111004008, N'These were their names: Ben-Hur was in charge of the hill country of Ephraim.'
EXEC add_BibleVerse @BibleId, 111004009, N'Ben-Deker was in charge of Makaz, Shaalbim, Beth Shemesh, and Elon Beth Hanan.'
EXEC add_BibleVerse @BibleId, 111004010, N'Ben-Hesed was in charge of Arubboth; he controlled Socoh and all the territory of Hepher.'
EXEC add_BibleVerse @BibleId, 111004011, N'Ben-Abinadab was in charge of Naphath Dor. (He was married to Solomon’s daughter Taphath.)'
EXEC add_BibleVerse @BibleId, 111004012, N'Baana son of Ahilud was in charge of Taanach and Megiddo, as well as all of Beth Shan next to Zarethan below Jezreel, from Beth Shan to Abel Meholah and on past Jokmeam.'
EXEC add_BibleVerse @BibleId, 111004013, N'Ben-Geber was in charge of Ramoth Gilead; he controlled the tent villages of Jair son of Manasseh in Gilead, as well as the region of Argob in Bashan, including sixty large walled cities with bronze bars locking their gates.'
EXEC add_BibleVerse @BibleId, 111004014, N'Ahinadab son of Iddo was in charge of Mahanaim.'
EXEC add_BibleVerse @BibleId, 111004015, N'Ahimaaz was in charge of Naphtali. (He married Solomon’s daughter Basemath.)'
EXEC add_BibleVerse @BibleId, 111004016, N'Baana son of Hushai was in charge of Asher and Aloth.'
EXEC add_BibleVerse @BibleId, 111004017, N'Jehoshaphat son of Paruah was in charge of Issachar.'
EXEC add_BibleVerse @BibleId, 111004018, N'Shimei son of Ela was in charge of Benjamin.'
EXEC add_BibleVerse @BibleId, 111004019, N'Geber son of Uri was in charge of the land of Gilead (the territory which had once belonged to King Sihon of the Amorites and to King Og of Bashan). He was sole governor of the area.'
EXEC add_BibleVerse @BibleId, 111004020, N'The people of Judah and Israel were as innumerable as the sand on the seashore; they had plenty to eat and drink and were happy.'
EXEC add_BibleVerse @BibleId, 111004021, N'Solomon ruled all the kingdoms from the Euphrates River to the land of the Philistines, as far as the border of Egypt. These kingdoms paid tribute as Solomon’s subjects throughout his lifetime.'
EXEC add_BibleVerse @BibleId, 111004022, N'Each day Solomon’s royal court consumed thirty cors of finely milled flour, sixty cors of cereal,'
EXEC add_BibleVerse @BibleId, 111004023, N'ten calves fattened in the stall, twenty calves from the pasture, and a hundred sheep, not to mention rams, gazelles, deer, and well-fed birds.'
EXEC add_BibleVerse @BibleId, 111004024, N'His royal court was so large because he ruled over all the kingdoms west of the Euphrates River from Tiphsah to Gaza; he was at peace with all his neighbors.'
EXEC add_BibleVerse @BibleId, 111004025, N'All the people of Judah and Israel had security; everyone from Dan to Beer Sheba enjoyed the produce of their vines and fig trees throughout Solomon’s lifetime.'
EXEC add_BibleVerse @BibleId, 111004026, N'Solomon had 4,000 stalls for his chariot horses and 12,000 horses.'
EXEC add_BibleVerse @BibleId, 111004027, N'The district governors acquired supplies for King Solomon and all who ate in his royal palace. Each was responsible for one month in the year; they made sure nothing was lacking.'
EXEC add_BibleVerse @BibleId, 111004028, N'Each one also brought to the assigned location his quota of barley and straw for the various horses.'
EXEC add_BibleVerse @BibleId, 111004029, N'God gave Solomon wisdom and very great discernment; the breadth of his understanding was as infinite as the sand on the seashore.'
EXEC add_BibleVerse @BibleId, 111004030, N'Solomon was wiser than all the men of the east and all the sages of Egypt.'
EXEC add_BibleVerse @BibleId, 111004031, N'He was wiser than any man, including Ethan the Ezrahite or Heman, Calcol, and Darda, the sons of Mahol. He was famous in all the neighboring nations.'
EXEC add_BibleVerse @BibleId, 111004032, N'He composed 3,000 proverbs and 1,005 songs.'
EXEC add_BibleVerse @BibleId, 111004033, N'He produced manuals on botany, describing every kind of plant, from the cedars of Lebanon to the hyssop that grows on walls. He also produced manuals on biology, describing animals, birds, insects, and fish.'
EXEC add_BibleVerse @BibleId, 111004034, N'People from all nations came to hear Solomon’s display of wisdom; they came from all the kings of the earth who heard about his wisdom.'
EXEC add_BibleVerse @BibleId, 111005001, N'King Hiram of Tyre sent messengers to Solomon when he heard that he had been anointed king in his father’s place. (Hiram had always been an ally of David.)'
EXEC add_BibleVerse @BibleId, 111005002, N'Solomon then sent this message to Hiram:'
EXEC add_BibleVerse @BibleId, 111005003, N'“You know that my father David was unable to build a temple to honor the Lord his God, for he was busy fighting battles on all fronts while the Lord subdued his enemies.'
EXEC add_BibleVerse @BibleId, 111005004, N'But now the Lord my God has made me secure on all fronts; there is no adversary or dangerous threat.'
EXEC add_BibleVerse @BibleId, 111005005, N'So I have decided to build a temple to honor the Lord my God, as the Lord instructed my father David, ‘Your son, whom I will put on your throne in your place, is the one who will build a temple to honor me.’'
EXEC add_BibleVerse @BibleId, 111005006, N'So now order some cedars of Lebanon to be cut for me. My servants will work with your servants. I will pay your servants whatever you say is appropriate, for you know that we have no one among us who knows how to cut down trees like the Sidonians.”'
EXEC add_BibleVerse @BibleId, 111005007, N'When Hiram heard Solomon’s message, he was very happy. He said, “The Lord is worthy of praise today because he has given David a wise son to rule over this great nation.”'
EXEC add_BibleVerse @BibleId, 111005008, N'Hiram then sent this message to Solomon: “I received the message you sent to me. I will give you all the cedars and evergreens you need.'
EXEC add_BibleVerse @BibleId, 111005009, N'My servants will bring the timber down from Lebanon to the sea. I will send it by sea in raft-like bundles to the place you designate. There I will separate the logs and you can carry them away. In exchange you will supply the food I need for my royal court.”'
EXEC add_BibleVerse @BibleId, 111005010, N'So Hiram supplied the cedars and evergreens Solomon needed,'
EXEC add_BibleVerse @BibleId, 111005011, N'and Solomon supplied Hiram annually with 20,000 cors of wheat as provision for his royal court, as well as 20,000 baths of pure olive oil.'
EXEC add_BibleVerse @BibleId, 111005012, N'So the Lord gave Solomon wisdom, as he had promised him. And Hiram and Solomon were at peace and made a treaty.'
EXEC add_BibleVerse @BibleId, 111005013, N'King Solomon conscripted work crews from throughout Israel, 30,000 men in all.'
EXEC add_BibleVerse @BibleId, 111005014, N'He sent them to Lebanon in shifts of 10,000 men per month. They worked in Lebanon for one month, and then spent two months at home. Adoniram was supervisor of the work crews.'
EXEC add_BibleVerse @BibleId, 111005015, N'Solomon also had 70,000 common laborers and 80,000 stonecutters in the hills,'
EXEC add_BibleVerse @BibleId, 111005016, N'besides 3,300 officials who supervised the workers.'
EXEC add_BibleVerse @BibleId, 111005017, N'By royal order they supplied large valuable stones in order to build the temple’s foundation with chiseled stone.'
EXEC add_BibleVerse @BibleId, 111005018, N'Solomon’s and Hiram’s construction workers, along with men from Byblos, did the chiseling and prepared the wood and stones for the building of the temple.'
EXEC add_BibleVerse @BibleId, 111006001, N'In the four hundred and eightieth year after the Israelites left Egypt, in the fourth year of Solomon’s reign over Israel, during the month Ziv (the second month), he began building the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 111006002, N'The temple King Solomon built for the Lord was 90 feet long, 30 feet wide, and 45 feet high.'
EXEC add_BibleVerse @BibleId, 111006003, N'The porch in front of the main hall of the temple was 30 feet long, corresponding to the width of the temple. It was 15 feet wide, extending out from the front of the temple.'
EXEC add_BibleVerse @BibleId, 111006004, N'He made framed windows for the temple.'
EXEC add_BibleVerse @BibleId, 111006005, N'He built an extension all around the walls of the temple’s main hall and holy place and constructed side rooms in it.'
EXEC add_BibleVerse @BibleId, 111006006, N'The bottom floor of the extension was seven and a half feet wide, the middle floor nine feet wide, and the third floor ten and a half feet wide. He made ledges on the temple’s outer walls so the beams would not have to be inserted into the walls.'
EXEC add_BibleVerse @BibleId, 111006007, N'As the temple was being built, only stones shaped at the quarry were used; the sound of hammers, pickaxes, or any other iron tool was not heard at the temple while it was being built.'
EXEC add_BibleVerse @BibleId, 111006008, N'The entrance to the bottom level of side rooms was on the south side of the temple; stairs went up to the middle floor and then on up to the third floor.'
EXEC add_BibleVerse @BibleId, 111006009, N'He finished building the temple and covered it with rafters and boards made of cedar.'
EXEC add_BibleVerse @BibleId, 111006010, N'He built an extension all around the temple; it was seven and a half feet high and it was attached to the temple by cedar beams.'
EXEC add_BibleVerse @BibleId, 111006011, N'The Lord said to Solomon:'
EXEC add_BibleVerse @BibleId, 111006012, N'“As for this temple you are building, if you follow my rules, observe my regulations, and obey all my commandments, I will fulfill through you the promise I made to your father David.'
EXEC add_BibleVerse @BibleId, 111006013, N'I will live among the Israelites and will not abandon my people Israel.”'
EXEC add_BibleVerse @BibleId, 111006014, N'So Solomon finished building the temple.'
EXEC add_BibleVerse @BibleId, 111006015, N'He constructed the walls inside the temple with cedar planks; he paneled the inside with wood from the floor of the temple to the rafters of the ceiling. He covered the temple floor with boards made from the wood of evergreens.'
EXEC add_BibleVerse @BibleId, 111006016, N'He built a wall 30 feet in from the rear of the temple as a partition for an inner sanctuary that would be the most holy place. He paneled the wall with cedar planks from the floor to the rafters.'
EXEC add_BibleVerse @BibleId, 111006017, N'The main hall in front of the inner sanctuary was 60 feet long.'
EXEC add_BibleVerse @BibleId, 111006018, N'The inside of the temple was all cedar and was adorned with carvings of round ornaments and of flowers in bloom. Everything was cedar; no stones were visible.'
EXEC add_BibleVerse @BibleId, 111006019, N'He prepared the inner sanctuary inside the temple so that the ark of the covenant of the Lord could be placed there.'
EXEC add_BibleVerse @BibleId, 111006020, N'The inner sanctuary was 30 feet long, 30 feet wide, and 30 feet high. He plated it with gold, as well as the cedar altar.'
EXEC add_BibleVerse @BibleId, 111006021, N'Solomon plated the inside of the temple with gold. He hung golden chains in front of the inner sanctuary and plated the inner sanctuary with gold.'
EXEC add_BibleVerse @BibleId, 111006022, N'He plated the entire inside of the temple with gold, as well as the altar inside the inner sanctuary.'
EXEC add_BibleVerse @BibleId, 111006023, N'In the inner sanctuary he made two cherubs of olive wood; each stood 15 feet high.'
EXEC add_BibleVerse @BibleId, 111006024, N'Each of the first cherub’s wings was seven and a half feet long; its entire wingspan was 15 feet.'
EXEC add_BibleVerse @BibleId, 111006025, N'The second cherub also had a wingspan of 15 feet; it was identical to the first in measurements and shape.'
EXEC add_BibleVerse @BibleId, 111006026, N'Each cherub stood 15 feet high.'
EXEC add_BibleVerse @BibleId, 111006027, N'He put the cherubs in the inner sanctuary of the temple. Their wings were spread out. One of the first cherub’s wings touched one wall and one of the other cherub’s wings touched the opposite wall. The first cherub’s other wing touched the second cherub’s other wing in the middle of the room.'
EXEC add_BibleVerse @BibleId, 111006028, N'He plated the cherubs with gold.'
EXEC add_BibleVerse @BibleId, 111006029, N'On all the walls around the temple, inside and out, he carved cherubs, palm trees, and flowers in bloom.'
EXEC add_BibleVerse @BibleId, 111006030, N'He plated the floor of the temple with gold, inside and out.'
EXEC add_BibleVerse @BibleId, 111006031, N'He made doors of olive wood at the entrance to the inner sanctuary; the pillar on each doorpost was five-sided.'
EXEC add_BibleVerse @BibleId, 111006032, N'On the two doors made of olive wood he carved cherubs, palm trees, and flowers in bloom, and he plated them with gold. He plated the cherubs and the palm trees with hammered gold.'
EXEC add_BibleVerse @BibleId, 111006033, N'In the same way he made doorposts of olive wood for the entrance to the main hall, only with four-sided pillars.'
EXEC add_BibleVerse @BibleId, 111006034, N'He also made two doors out of wood from evergreens; each door had two folding leaves.'
EXEC add_BibleVerse @BibleId, 111006035, N'He carved cherubs, palm trees, and flowers in bloom and plated them with gold, leveled out over the carvings.'
EXEC add_BibleVerse @BibleId, 111006036, N'He built the inner courtyard with three rows of chiseled stones and a row of cedar beams.'
EXEC add_BibleVerse @BibleId, 111006037, N'In the month Ziv of the fourth year of Solomon’s reign the foundation was laid for the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 111006038, N'In the eleventh year, in the month Bul (the eighth month) the temple was completed in accordance with all its specifications and blueprints. It took seven years to build.'
EXEC add_BibleVerse @BibleId, 111007001, N'Solomon took thirteen years to build his palace.'
EXEC add_BibleVerse @BibleId, 111007002, N'He named it “The Palace of the Lebanon Forest”; it was 150 feet long, 75 feet wide, and 45 feet high. It had four rows of cedar pillars and cedar beams above the pillars.'
EXEC add_BibleVerse @BibleId, 111007003, N'The roof above the beams supported by the pillars was also made of cedar; there were forty-five beams, fifteen per row.'
EXEC add_BibleVerse @BibleId, 111007004, N'There were three rows of windows arranged in sets of three.'
EXEC add_BibleVerse @BibleId, 111007005, N'All of the entrances were rectangular in shape and they were arranged in sets of three.'
EXEC add_BibleVerse @BibleId, 111007006, N'He made a colonnade 75 feet long and 45 feet wide. There was a porch in front of this and pillars and a roof in front of the porch.'
EXEC add_BibleVerse @BibleId, 111007007, N'He also made a throne room, called “The Hall of Judgment,” where he made judicial decisions. It was paneled with cedar from the floor to the rafters.'
EXEC add_BibleVerse @BibleId, 111007008, N'The palace where he lived was constructed in a similar way. He also constructed a palace like this hall for Pharaoh’s daughter, whom he had married.'
EXEC add_BibleVerse @BibleId, 111007009, N'All of these were built with the best stones, chiseled to the right size and cut with a saw on all sides, from the foundation to the edge of the roof and from the outside to the great courtyard.'
EXEC add_BibleVerse @BibleId, 111007010, N'The foundation was made of large valuable stones, measuring either 15 feet or 12 feet.'
EXEC add_BibleVerse @BibleId, 111007011, N'Above the foundation the best stones, chiseled to the right size, were used along with cedar.'
EXEC add_BibleVerse @BibleId, 111007012, N'Around the great courtyard were three rows of chiseled stones and one row of cedar beams, like the inner courtyard of the Lord’s temple and the hall of the palace.'
EXEC add_BibleVerse @BibleId, 111007013, N'King Solomon sent for Hiram of Tyre.'
EXEC add_BibleVerse @BibleId, 111007014, N'He was the son of a widow from the tribe of Naphtali, and his father was a craftsman in bronze from Tyre. He had the skill and knowledge to make all kinds of works of bronze. He reported to King Solomon and did all the work he was assigned.'
EXEC add_BibleVerse @BibleId, 111007015, N'He fashioned two bronze pillars; each pillar was 27 feet high and 18 feet in circumference.'
EXEC add_BibleVerse @BibleId, 111007016, N'He made two bronze tops for the pillars; each was seven-and-a-half feet high.'
EXEC add_BibleVerse @BibleId, 111007017, N'The latticework on the tops of the pillars was adorned with ornamental wreaths and chains; the top of each pillar had seven groupings of ornaments.'
EXEC add_BibleVerse @BibleId, 111007018, N'When he made the pillars, there were two rows of pomegranate-shaped ornaments around the latticework covering the top of each pillar.'
EXEC add_BibleVerse @BibleId, 111007019, N'The tops of the two pillars in the porch were shaped like lilies and were six feet high.'
EXEC add_BibleVerse @BibleId, 111007020, N'On the top of each pillar, right above the bulge beside the latticework, there were two hundred pomegranate-shaped ornaments arranged in rows all the way around.'
EXEC add_BibleVerse @BibleId, 111007021, N'He set up the pillars on the porch in front of the main hall. He erected one pillar on the right side and called it Jakin; he erected the other pillar on the left side and called it Boaz.'
EXEC add_BibleVerse @BibleId, 111007022, N'The tops of the pillars were shaped like lilies. So the construction of the pillars was completed.'
EXEC add_BibleVerse @BibleId, 111007023, N'He also made the large bronze basin called “The Sea.” It measured 15 feet from rim to rim, was circular in shape, and stood seven-and-a-half feet high. Its circumference was 45 feet.'
EXEC add_BibleVerse @BibleId, 111007024, N'Under the rim all the way around it were round ornaments arranged in settings 15 feet long. The ornaments were in two rows and had been cast with “The Sea.”'
EXEC add_BibleVerse @BibleId, 111007025, N'“The Sea” stood on top of twelve bulls. Three faced northward, three westward, three southward, and three eastward. “The Sea” was placed on top of them, and they all faced outward.'
EXEC add_BibleVerse @BibleId, 111007026, N'It was four fingers thick and its rim was like that of a cup shaped like a lily blossom. It could hold about 12,000 gallons.'
EXEC add_BibleVerse @BibleId, 111007027, N'He also made ten bronze movable stands. Each stand was six feet long, six feet wide, and four-and-a-half feet high.'
EXEC add_BibleVerse @BibleId, 111007028, N'The stands were constructed with frames between the joints.'
EXEC add_BibleVerse @BibleId, 111007029, N'On these frames and joints were ornamental lions, bulls, and cherubs. Under the lions and bulls were decorative wreaths.'
EXEC add_BibleVerse @BibleId, 111007030, N'Each stand had four bronze wheels with bronze axles and four supports. Under the basin the supports were fashioned on each side with wreaths.'
EXEC add_BibleVerse @BibleId, 111007031, N'Inside the stand was a round opening that was a foot-and-a-half deep; it had a support that was two and one-quarter feet long. On the edge of the opening were carvings in square frames.'
EXEC add_BibleVerse @BibleId, 111007032, N'The four wheels were under the frames and the crossbars of the axles were connected to the stand. Each wheel was two and one-quarter feet high.'
EXEC add_BibleVerse @BibleId, 111007033, N'The wheels were constructed like chariot wheels; their crossbars, rims, spokes, and hubs were made of cast metal.'
EXEC add_BibleVerse @BibleId, 111007034, N'Each stand had four supports, one per side projecting out from the stand.'
EXEC add_BibleVerse @BibleId, 111007035, N'On top of each stand was a round opening three-quarters of a foot deep; there were also supports and frames on top of the stands.'
EXEC add_BibleVerse @BibleId, 111007036, N'He engraved ornamental cherubs, lions, and palm trees on the plates of the supports and frames wherever there was room, with wreaths all around.'
EXEC add_BibleVerse @BibleId, 111007037, N'He made the ten stands in this way. All of them were cast in one mold and were identical in measurements and shape.'
EXEC add_BibleVerse @BibleId, 111007038, N'He also made ten bronze basins, each of which could hold about 240 gallons. Each basin was six feet in diameter; there was one basin for each stand.'
EXEC add_BibleVerse @BibleId, 111007039, N'He put five basins on the south side of the temple and five on the north side. He put “The Sea” on the south side, in the southeast corner.'
EXEC add_BibleVerse @BibleId, 111007040, N'Hiram also made basins, shovels, and bowls. He finished all the work on the Lord’s temple he had been assigned by King Solomon.'
EXEC add_BibleVerse @BibleId, 111007041, N'He made the two pillars, the two bowl-shaped tops of the pillars, the latticework for the bowl-shaped tops of the two pillars,'
EXEC add_BibleVerse @BibleId, 111007042, N'the four hundred pomegranate-shaped ornaments for the latticework of the two pillars (each latticework had two rows of these ornaments at the bowl-shaped top of the pillar),'
EXEC add_BibleVerse @BibleId, 111007043, N'the ten movable stands with their ten basins,'
EXEC add_BibleVerse @BibleId, 111007044, N'the big bronze basin called “The Sea” with its twelve bulls underneath,'
EXEC add_BibleVerse @BibleId, 111007045, N'and the pots, shovels, and bowls. All these items King Solomon assigned Hiram to make for the Lord’s temple were made from polished bronze.'
EXEC add_BibleVerse @BibleId, 111007046, N'The king had them cast in earth foundries in the region of the Jordan between Succoth and Zarethan.'
EXEC add_BibleVerse @BibleId, 111007047, N'Solomon left all these items unweighed; there were so many of them they did not weigh the bronze.'
EXEC add_BibleVerse @BibleId, 111007048, N'Solomon also made all these items for the Lord’s temple: the gold altar, the gold table on which was kept the Bread of the Presence,'
EXEC add_BibleVerse @BibleId, 111007049, N'the pure gold lampstands at the entrance to the inner sanctuary (five on the right and five on the left), the gold flower-shaped ornaments, lamps, and tongs,'
EXEC add_BibleVerse @BibleId, 111007050, N'the pure gold bowls, trimming shears, basins, pans, and censers, and the gold door sockets for the inner sanctuary (the most holy place) and for the doors of the main hall of the temple.'
EXEC add_BibleVerse @BibleId, 111007051, N'When King Solomon finished constructing the Lord’s temple, he put the holy items that belonged to his father David (the silver, gold, and other articles) in the treasuries of the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 111008001, N'Then Solomon convened in Jerusalem Israel’s elders, all the leaders of the Israelite tribes and families, so they could witness the transferal of the ark of the Lord’s covenant from the city of David (that is, Zion).'
EXEC add_BibleVerse @BibleId, 111008002, N'All the men of Israel assembled before King Solomon during the festival in the month Ethanim (the seventh month).'
EXEC add_BibleVerse @BibleId, 111008003, N'When all Israel’s elders had arrived, the priests lifted the ark.'
EXEC add_BibleVerse @BibleId, 111008004, N'The priests and Levites carried the ark of the Lord, the tent of meeting, and all the holy items in the tent.'
EXEC add_BibleVerse @BibleId, 111008005, N'Now King Solomon and all the Israelites who had assembled with him went on ahead of the ark and sacrificed more sheep and cattle than could be counted or numbered.'
EXEC add_BibleVerse @BibleId, 111008006, N'The priests brought the ark of the Lord’s covenant to its assigned place in the inner sanctuary of the temple, in the most holy place, under the wings of the cherubs.'
EXEC add_BibleVerse @BibleId, 111008007, N'The cherubs’ wings extended over the place where the ark sat; the cherubs overshadowed the ark and its poles.'
EXEC add_BibleVerse @BibleId, 111008008, N'The poles were so long their ends were visible from the holy place in front of the inner sanctuary, but they could not be seen from beyond that point. They have remained there to this very day.'
EXEC add_BibleVerse @BibleId, 111008009, N'There was nothing in the ark except the two stone tablets Moses had placed there in Horeb. It was there that the Lord made an agreement with the Israelites after he brought them out of the land of Egypt.'
EXEC add_BibleVerse @BibleId, 111008010, N'Once the priests left the holy place, a cloud filled the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 111008011, N'The priests could not carry out their duties because of the cloud; the Lord’s glory filled his temple.'
EXEC add_BibleVerse @BibleId, 111008012, N'Then Solomon said, “The Lord has said that he lives in thick darkness.'
EXEC add_BibleVerse @BibleId, 111008013, N'O Lord, truly I have built a lofty temple for you, a place where you can live permanently.”'
EXEC add_BibleVerse @BibleId, 111008014, N'Then the king turned around and pronounced a blessing over the whole Israelite assembly as they stood there.'
EXEC add_BibleVerse @BibleId, 111008015, N'He said, “The Lord God of Israel is worthy of praise because he has fulfilled what he promised my father David.'
EXEC add_BibleVerse @BibleId, 111008016, N'He told David, ‘Since the day I brought my people Israel out of Egypt, I have not chosen a city from all the tribes of Israel to build a temple in which to live. But I have chosen David to lead my people Israel.’'
EXEC add_BibleVerse @BibleId, 111008017, N'Now my father David had a strong desire to build a temple to honor the Lord God of Israel.'
EXEC add_BibleVerse @BibleId, 111008018, N'The Lord told my father David, ‘It is right for you to have a strong desire to build a temple to honor me.'
EXEC add_BibleVerse @BibleId, 111008019, N'But you will not build the temple; your very own son will build the temple for my honor.’'
EXEC add_BibleVerse @BibleId, 111008020, N'The Lord has kept the promise he made. I have taken my father David’s place and have occupied the throne of Israel, as the Lord promised. I have built this temple for the honor of the Lord God of Israel'
EXEC add_BibleVerse @BibleId, 111008021, N'and set up in it a place for the ark containing the covenant the Lord made with our ancestors when he brought them out of the land of Egypt.”'
EXEC add_BibleVerse @BibleId, 111008022, N'Solomon stood before the altar of the Lord in front of the entire assembly of Israel and spread out his hands toward the sky.'
EXEC add_BibleVerse @BibleId, 111008023, N'He prayed: “O Lord, God of Israel, there is no god like you in heaven above or on earth below! You maintain covenantal loyalty to your servants who obey you with sincerity.'
EXEC add_BibleVerse @BibleId, 111008024, N'You have kept your word to your servant, my father David; this very day you have fulfilled what you promised.'
EXEC add_BibleVerse @BibleId, 111008025, N'Now, O Lord, God of Israel, keep the promise you made to your servant, my father David, when you said, ‘You will never fail to have a successor ruling before me on the throne of Israel, provided that your descendants watch their step and serve me as you have done.’'
EXEC add_BibleVerse @BibleId, 111008026, N'Now, O God of Israel, may the promise you made to your servant, my father David, be realized.'
EXEC add_BibleVerse @BibleId, 111008027, N'“God does not really live on the earth! Look, if the sky and the highest heaven cannot contain you, how much less this temple I have built!'
EXEC add_BibleVerse @BibleId, 111008028, N'But respond favorably to your servant’s prayer and his request for help, O Lord my God. Answer the desperate prayer your servant is presenting to you today.'
EXEC add_BibleVerse @BibleId, 111008029, N'Night and day may you watch over this temple, the place where you promised you would live. May you answer your servant’s prayer for this place.'
EXEC add_BibleVerse @BibleId, 111008030, N'Respond to the request of your servant and your people Israel for this place. Hear from inside your heavenly dwelling place and respond favorably.'
EXEC add_BibleVerse @BibleId, 111008031, N'“When someone is accused of sinning against his neighbor and the latter pronounces a curse on the alleged offender before your altar in this temple, be willing to forgive the accused if the accusation is false.'
EXEC add_BibleVerse @BibleId, 111008032, N'Listen from heaven and make a just decision about your servants’ claims. Condemn the guilty party, declare the other innocent, and give both of them what they deserve.'
EXEC add_BibleVerse @BibleId, 111008033, N'“The time will come when your people Israel are defeated by an enemy because they sinned against you. If they come back to you, renew their allegiance to you, and pray for your help in this temple,'
EXEC add_BibleVerse @BibleId, 111008034, N'then listen from heaven, forgive the sin of your people Israel, and bring them back to the land you gave to their ancestors.'
EXEC add_BibleVerse @BibleId, 111008035, N'“The time will come when the skies are shut up tightly and no rain falls because your people sinned against you. When they direct their prayers toward this place, renew their allegiance to you, and turn away from their sin because you punish them,'
EXEC add_BibleVerse @BibleId, 111008036, N'then listen from heaven and forgive the sin of your servants, your people Israel. Certainly you will then teach them the right way to live and send rain on your land that you have given your people to possess.'
EXEC add_BibleVerse @BibleId, 111008037, N'“The time will come when the land suffers from a famine, a plague, blight and disease, or a locust invasion, or when their enemy lays siege to the cities of the land, or when some other type of plague or epidemic occurs.'
EXEC add_BibleVerse @BibleId, 111008038, N'When all your people Israel pray and ask for help, as they acknowledge their pain and spread out their hands toward this temple,'
EXEC add_BibleVerse @BibleId, 111008039, N'then listen from your heavenly dwelling place, forgive their sin, and act favorably toward each one based on your evaluation of his motives. (Indeed you are the only one who can correctly evaluate the motives of all people.)'
EXEC add_BibleVerse @BibleId, 111008040, N'Then they will obey you throughout their lifetimes as they live on the land you gave to our ancestors.'
EXEC add_BibleVerse @BibleId, 111008041, N'“Foreigners, who do not belong to your people Israel, will come from a distant land because of your reputation.'
EXEC add_BibleVerse @BibleId, 111008042, N'When they hear about your great reputation and your ability to accomplish mighty deeds, they will come and direct their prayers toward this temple.'
EXEC add_BibleVerse @BibleId, 111008043, N'Then listen from your heavenly dwelling place and answer all the prayers of the foreigners. Then all the nations of the earth will acknowledge your reputation, obey you like your people Israel do, and recognize that this temple I built belongs to you.'
EXEC add_BibleVerse @BibleId, 111008044, N'“When you direct your people to march out and fight their enemies, and they direct their prayers to the Lord toward his chosen city and this temple I built for your honor,'
EXEC add_BibleVerse @BibleId, 111008045, N'then listen from heaven to their prayers for help and vindicate them.'
EXEC add_BibleVerse @BibleId, 111008046, N'“The time will come when your people will sin against you (for there is no one who is sinless!) and you will be angry with them and deliver them over to their enemies, who will take them as prisoners to their own land, whether far away or close by.'
EXEC add_BibleVerse @BibleId, 111008047, N'When your people come to their senses in the land where they are held prisoner, they will repent and beg for your mercy in the land of their imprisonment, admitting, ‘We have sinned and gone astray; we have done evil.’'
EXEC add_BibleVerse @BibleId, 111008048, N'When they return to you with all their heart and being in the land where they are held prisoner, and direct their prayers to you toward the land you gave to their ancestors, your chosen city, and the temple I built for your honor,'
EXEC add_BibleVerse @BibleId, 111008049, N'then listen from your heavenly dwelling place to their prayers for help and vindicate them.'
EXEC add_BibleVerse @BibleId, 111008050, N'Forgive all the rebellious acts of your sinful people and cause their captors to have mercy on them.'
EXEC add_BibleVerse @BibleId, 111008051, N'After all, they are your people and your special possession whom you brought out of Egypt, from the middle of the iron-smelting furnace.'
EXEC add_BibleVerse @BibleId, 111008052, N'“May you be attentive to your servant’s and your people Israel’s requests for help and may you respond to all their prayers to you.'
EXEC add_BibleVerse @BibleId, 111008053, N'After all, you picked them out of all the nations of the earth to be your special possession, just as you, O sovereign Lord, announced through your servant Moses when you brought our ancestors out of Egypt.”'
EXEC add_BibleVerse @BibleId, 111008054, N'When Solomon finished presenting all these prayers and requests to the Lord, he got up from before the altar of the Lord where he had kneeled and spread out his hands toward the sky.'
EXEC add_BibleVerse @BibleId, 111008055, N'When he stood up, he pronounced a blessing over the entire assembly of Israel, saying in a loud voice:'
EXEC add_BibleVerse @BibleId, 111008056, N'“The Lord is worthy of praise because he has made Israel his people secure just as he promised! Not one of all the faithful promises he made through his servant Moses is left unfulfilled!'
EXEC add_BibleVerse @BibleId, 111008057, N'May the Lord our God be with us, as he was with our ancestors. May he not abandon us or leave us.'
EXEC add_BibleVerse @BibleId, 111008058, N'May he make us submissive, so we can follow all his instructions and obey the commandments, rules, and regulations he commanded our ancestors.'
EXEC add_BibleVerse @BibleId, 111008059, N'May the Lord our God be constantly aware of these requests of mine I have presented to him, so that he might vindicate his servant and his people Israel as the need arises.'
EXEC add_BibleVerse @BibleId, 111008060, N'Then all the nations of the earth will recognize that the Lord is the only genuine God.'
EXEC add_BibleVerse @BibleId, 111008061, N'May you demonstrate wholehearted devotion to the Lord our God by following his rules and obeying his commandments, as you are presently doing.”'
EXEC add_BibleVerse @BibleId, 111008062, N'The king and all Israel with him were presenting sacrifices to the Lord.'
EXEC add_BibleVerse @BibleId, 111008063, N'Solomon offered as peace offerings to the Lord 22,000 cattle and 120,000 sheep. Then the king and all the Israelites dedicated the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 111008064, N'That day the king consecrated the middle of the courtyard that is in front of the Lord’s temple. He offered there burnt sacrifices, grain offerings, and the fat from the peace offerings, because the bronze altar that stood before the Lord was too small to hold all these offerings.'
EXEC add_BibleVerse @BibleId, 111008065, N'At that time Solomon and all Israel with him celebrated a festival before the Lord our God for two entire weeks. This great assembly included people from all over the land, from Lebo Hamath in the north to the Brook of Egypt in the south.'
EXEC add_BibleVerse @BibleId, 111008066, N'On the fifteenth day after the festival started, he dismissed the people. They asked God to empower the king and then went to their homes, happy and content because of all the good the Lord had done for his servant David and his people Israel.'
EXEC add_BibleVerse @BibleId, 111009001, N'After Solomon finished building the Lord’s temple, the royal palace, and all the other construction projects he had planned,'
EXEC add_BibleVerse @BibleId, 111009002, N'the Lord appeared to Solomon a second time, in the same way he had appeared to him at Gibeon.'
EXEC add_BibleVerse @BibleId, 111009003, N'The Lord said to him, “I have answered your prayer and your request for help that you made to me. I have consecrated this temple you built by making it my permanent home; I will be constantly present there.'
EXEC add_BibleVerse @BibleId, 111009004, N'You must serve me with integrity and sincerity, just as your father David did. Do everything I commanded and obey my rules and regulations.'
EXEC add_BibleVerse @BibleId, 111009005, N'Then I will allow your dynasty to rule over Israel permanently, just as I promised your father David, ‘You will not fail to have a successor on the throne of Israel.’'
EXEC add_BibleVerse @BibleId, 111009006, N'“But if you or your sons ever turn away from me, fail to obey the regulations and rules I instructed you to keep, and decide to serve and worship other gods,'
EXEC add_BibleVerse @BibleId, 111009007, N'then I will remove Israel from the land I have given them, I will abandon this temple I have consecrated with my presence, and Israel will be mocked and ridiculed among all the nations.'
EXEC add_BibleVerse @BibleId, 111009008, N'This temple will become a heap of ruins; everyone who passes by it will be shocked and will hiss out their scorn, saying, ‘Why did the Lord do this to this land and this temple?’'
EXEC add_BibleVerse @BibleId, 111009009, N'Others will then answer, ‘Because they abandoned the Lord their God, who led their ancestors out of Egypt. They embraced other gods whom they worshiped and served. That is why the Lord has brought all this disaster down on them.’”'
EXEC add_BibleVerse @BibleId, 111009010, N'After twenty years, during which Solomon built the Lord’s temple and the royal palace,'
EXEC add_BibleVerse @BibleId, 111009011, N'King Solomon gave King Hiram of Tyre twenty cities in the region of Galilee, because Hiram had supplied Solomon with cedars, evergreens, and all the gold he wanted.'
EXEC add_BibleVerse @BibleId, 111009012, N'When Hiram went out from Tyre to inspect the cities Solomon had given him, he was not pleased with them.'
EXEC add_BibleVerse @BibleId, 111009013, N'Hiram asked, “Why did you give me these cities, my friend ?” He called that area the region of Cabul, a name which it has retained to this day.'
EXEC add_BibleVerse @BibleId, 111009014, N'Hiram had sent to the king one hundred twenty talents of gold.'
EXEC add_BibleVerse @BibleId, 111009015, N'Here are the details concerning the work crews King Solomon conscripted to build the Lord’s temple, his palace, the terrace, the wall of Jerusalem, and Gezer.'
EXEC add_BibleVerse @BibleId, 111009016, N'(Pharaoh, king of Egypt, had attacked and captured Gezer. He burned it and killed the Canaanites who lived in the city. He gave it as a wedding present to his daughter, who had married Solomon.)'
EXEC add_BibleVerse @BibleId, 111009017, N'Solomon built up Gezer, lower Beth Horon,'
EXEC add_BibleVerse @BibleId, 111009018, N'Baalath, Tadmor in the wilderness,'
EXEC add_BibleVerse @BibleId, 111009019, N'all the storage cities that belonged to him, and the cities where chariots and horses were kept. He built whatever he wanted in Jerusalem, Lebanon, and throughout his entire kingdom.'
EXEC add_BibleVerse @BibleId, 111009020, N'Now several non-Israelite peoples were left in the land after the conquest of Joshua, including the Amorites, Hittites, Perizzites, Hivites, and Jebusites.'
EXEC add_BibleVerse @BibleId, 111009021, N'Their descendants remained in the land (the Israelites were unable to wipe them out completely). Solomon conscripted them for his work crews, and they continue in that role to this very day.'
EXEC add_BibleVerse @BibleId, 111009022, N'Solomon did not assign Israelites to these work crews; the Israelites served as his soldiers, attendants, officers, charioteers, and commanders of his chariot forces.'
EXEC add_BibleVerse @BibleId, 111009023, N'These men were also in charge of Solomon’s work projects; there were a total of 550 men who supervised the workers.'
EXEC add_BibleVerse @BibleId, 111009024, N'Solomon built the terrace as soon as Pharaoh’s daughter moved up from the city of David to the palace Solomon built for her.'
EXEC add_BibleVerse @BibleId, 111009025, N'Three times a year Solomon offered burnt offerings and peace offerings on the altar he had built for the Lord, burning incense along with them before the Lord. He made the temple his official worship place.'
EXEC add_BibleVerse @BibleId, 111009026, N'King Solomon also built ships in Ezion Geber, which is located near Elat in the land of Edom, on the shore of the Red Sea.'
EXEC add_BibleVerse @BibleId, 111009027, N'Hiram sent his fleet and some of his sailors, who were well acquainted with the sea, to serve with Solomon’s men.'
EXEC add_BibleVerse @BibleId, 111009028, N'They sailed to Ophir, took from there four hundred twenty talents of gold, and then brought them to King Solomon.'
EXEC add_BibleVerse @BibleId, 111010001, N'When the queen of Sheba heard about Solomon, she came to challenge him with difficult questions.'
EXEC add_BibleVerse @BibleId, 111010002, N'She arrived in Jerusalem with a great display of pomp, bringing with her camels carrying spices, a very large quantity of gold, and precious gems. She visited Solomon and discussed with him everything that was on her mind.'
EXEC add_BibleVerse @BibleId, 111010003, N'Solomon answered all her questions; there was no question too complex for the king.'
EXEC add_BibleVerse @BibleId, 111010004, N'When the queen of Sheba saw for herself Solomon’s extensive wisdom, the palace he had built,'
EXEC add_BibleVerse @BibleId, 111010005, N'the food in his banquet hall, his servants and attendants, their robes, his cupbearers, and his burnt offerings which he presented in the Lord’s temple, she was amazed.'
EXEC add_BibleVerse @BibleId, 111010006, N'She said to the king, “The report I heard in my own country about your wise sayings and insight was true!'
EXEC add_BibleVerse @BibleId, 111010007, N'I did not believe these things until I came and saw them with my own eyes. Indeed, I didn’t hear even half the story! Your wisdom and wealth surpass what was reported to me.'
EXEC add_BibleVerse @BibleId, 111010008, N'Your attendants, who stand before you at all times and hear your wise sayings, are truly happy!'
EXEC add_BibleVerse @BibleId, 111010009, N'May the Lord your God be praised because he favored you by placing you on the throne of Israel! Because of the Lord’s eternal love for Israel, he made you king so you could make just and right decisions.”'
EXEC add_BibleVerse @BibleId, 111010010, N'She gave the king 120 talents of gold, a very large quantity of spices, and precious gems. The quantity of spices the queen of Sheba gave King Solomon has never been matched.'
EXEC add_BibleVerse @BibleId, 111010011, N'(Hiram’s fleet, which carried gold from Ophir, also brought from Ophir a very large quantity of fine timber and precious gems.'
EXEC add_BibleVerse @BibleId, 111010012, N'With the timber the king made supports for the Lord’s temple and for the royal palace and stringed instruments for the musicians. No one has seen so much of this fine timber to this very day. )'
EXEC add_BibleVerse @BibleId, 111010013, N'King Solomon gave the queen of Sheba everything she requested, besides what he had freely offered her. Then she left and returned to her homeland with her attendants.'
EXEC add_BibleVerse @BibleId, 111010014, N'Solomon received 666 talents of gold per year,'
EXEC add_BibleVerse @BibleId, 111010015, N'besides what he collected from the merchants, traders, Arabian kings, and governors of the land.'
EXEC add_BibleVerse @BibleId, 111010016, N'King Solomon made two hundred large shields of hammered gold; 600 measures of gold were used for each shield.'
EXEC add_BibleVerse @BibleId, 111010017, N'He also made three hundred small shields of hammered gold; three minas of gold were used for each of these shields. The king placed them in the Palace of the Lebanon Forest.'
EXEC add_BibleVerse @BibleId, 111010018, N'The king made a large throne decorated with ivory and overlaid it with pure gold.'
EXEC add_BibleVerse @BibleId, 111010019, N'There were six steps leading up to the throne, and the back of it was rounded on top. The throne had two armrests with a statue of a lion standing on each side.'
EXEC add_BibleVerse @BibleId, 111010020, N'There were twelve statues of lions on the six steps, one lion at each end of each step. There was nothing like it in any other kingdom.'
EXEC add_BibleVerse @BibleId, 111010021, N'All of King Solomon’s cups were made of gold, and all the household items in the Palace of the Lebanon Forest were made of pure gold. There were no silver items, for silver was not considered very valuable in Solomon’s time.'
EXEC add_BibleVerse @BibleId, 111010022, N'Along with Hiram’s fleet, the king had a fleet of large merchant ships that sailed the sea. Once every three years the fleet came into port with cargoes of gold, silver, ivory, apes, and peacocks.'
EXEC add_BibleVerse @BibleId, 111010023, N'King Solomon was wealthier and wiser than any of the kings of the earth.'
EXEC add_BibleVerse @BibleId, 111010024, N'Everyone in the world wanted to visit Solomon to see him display his God-given wisdom.'
EXEC add_BibleVerse @BibleId, 111010025, N'Year after year visitors brought their gifts, which included items of silver, items of gold, clothes, perfume, spices, horses, and mules.'
EXEC add_BibleVerse @BibleId, 111010026, N'Solomon accumulated chariots and horses. He had 1,400 chariots and 12,000 horses. He kept them in assigned cities and in Jerusalem.'
EXEC add_BibleVerse @BibleId, 111010027, N'The king made silver as plentiful in Jerusalem as stones; cedar was as plentiful as sycamore fig trees are in the lowlands.'
EXEC add_BibleVerse @BibleId, 111010028, N'Solomon acquired his horses from Egypt and from Que; the king’s traders purchased them from Que.'
EXEC add_BibleVerse @BibleId, 111010029, N'They paid 600 silver pieces for each chariot from Egypt and 150 silver pieces for each horse. They also sold chariots and horses to all the kings of the Hittites and to the kings of Syria.'
EXEC add_BibleVerse @BibleId, 111011001, N'King Solomon fell in love with many foreign women (besides Pharaoh’s daughter), including Moabites, Ammonites, Edomites, Sidonians, and Hittites.'
EXEC add_BibleVerse @BibleId, 111011002, N'They came from nations about which the Lord had warned the Israelites, “You must not establish friendly relations with them! If you do, they will surely shift your allegiance to their gods.” But Solomon was irresistibly attracted to them.'
EXEC add_BibleVerse @BibleId, 111011003, N'He had 700 royal wives and 300 concubines; his wives had a powerful influence over him.'
EXEC add_BibleVerse @BibleId, 111011004, N'When Solomon became old, his wives shifted his allegiance to other gods; he was not wholeheartedly devoted to the Lord his God, as his father David had been.'
EXEC add_BibleVerse @BibleId, 111011005, N'Solomon worshiped the Sidonian goddess Astarte and the detestable Ammonite god Milcom.'
EXEC add_BibleVerse @BibleId, 111011006, N'Solomon did evil in the Lord’s sight; he did not remain loyal to the Lord, like his father David had.'
EXEC add_BibleVerse @BibleId, 111011007, N'Furthermore, on the hill east of Jerusalem Solomon built a high place for the detestable Moabite god Chemosh and for the detestable Ammonite god Milcom.'
EXEC add_BibleVerse @BibleId, 111011008, N'He built high places for all his foreign wives so they could burn incense and make sacrifices to their gods.'
EXEC add_BibleVerse @BibleId, 111011009, N'The Lord was angry with Solomon because he had shifted his allegiance away from the Lord, the God of Israel, who had appeared to him on two occasions'
EXEC add_BibleVerse @BibleId, 111011010, N'and had warned him about this very thing, so that he would not follow other gods. But he did not obey the Lord’s command.'
EXEC add_BibleVerse @BibleId, 111011011, N'So the Lord said to Solomon, “Because you insist on doing these things and have not kept the covenantal rules I gave you, I will surely tear the kingdom away from you and give it to your servant.'
EXEC add_BibleVerse @BibleId, 111011012, N'However, for your father David’s sake I will not do this while you are alive. I will tear it away from your son’s hand instead.'
EXEC add_BibleVerse @BibleId, 111011013, N'But I will not tear away the entire kingdom; I will leave your son one tribe for my servant David’s sake and for the sake of my chosen city Jerusalem.”'
EXEC add_BibleVerse @BibleId, 111011014, N'The Lord brought against Solomon an enemy, Hadad the Edomite, a descendant of the Edomite king.'
EXEC add_BibleVerse @BibleId, 111011015, N'During David’s campaign against Edom, Joab, the commander of the army, while on a mission to bury the dead, killed every male in Edom.'
EXEC add_BibleVerse @BibleId, 111011016, N'For six months Joab and the entire Israelite army stayed there until they had exterminated every male in Edom.'
EXEC add_BibleVerse @BibleId, 111011017, N'Hadad, who was only a small boy at the time, escaped with some of his father’s Edomite servants and headed for Egypt.'
EXEC add_BibleVerse @BibleId, 111011018, N'They went from Midian to Paran; they took some men from Paran and went to Egypt. Pharaoh, king of Egypt, supplied him with a house and food and even assigned him some land.'
EXEC add_BibleVerse @BibleId, 111011019, N'Pharaoh liked Hadad so well he gave him his sister-in-law (Queen Tahpenes’ sister) as a wife.'
EXEC add_BibleVerse @BibleId, 111011020, N'Tahpenes’ sister gave birth to his son, named Genubath. Tahpenes raised him in Pharaoh’s palace; Genubath grew up in Pharaoh’s palace among Pharaoh’s sons.'
EXEC add_BibleVerse @BibleId, 111011021, N'While in Egypt Hadad heard that David had passed away and that Joab, the commander of the army, was dead. So Hadad asked Pharaoh, “Give me permission to leave so I can return to my homeland.”'
EXEC add_BibleVerse @BibleId, 111011022, N'Pharaoh said to him, “What do you lack here that makes you want to go to your homeland?” Hadad replied, “Nothing, but please give me permission to leave.”'
EXEC add_BibleVerse @BibleId, 111011023, N'God also brought against Solomon another enemy, Rezon son of Eliada who had run away from his master, King Hadadezer of Zobah.'
EXEC add_BibleVerse @BibleId, 111011024, N'He gathered some men and organized a raiding band. When David tried to kill them, they went to Damascus, where they settled down and gained control of the city.'
EXEC add_BibleVerse @BibleId, 111011025, N'He was Israel’s enemy throughout Solomon’s reign and, like Hadad, caused trouble. He loathed Israel and ruled over Syria.'
EXEC add_BibleVerse @BibleId, 111011026, N'Jeroboam son of Nebat, one of Solomon’s servants, rebelled against the king. He was an Ephraimite from Zeredah whose mother was a widow named Zeruah.'
EXEC add_BibleVerse @BibleId, 111011027, N'This is what prompted him to rebel against the king: Solomon built a terrace and he closed up a gap in the wall of the city of his father David.'
EXEC add_BibleVerse @BibleId, 111011028, N'Jeroboam was a talented man; when Solomon saw that the young man was an accomplished worker, he made him the leader of the work crew from the tribe of Joseph.'
EXEC add_BibleVerse @BibleId, 111011029, N'At that time, when Jeroboam had left Jerusalem, the prophet Ahijah the Shilonite met him on the road; the two of them were alone in the open country. Ahijah was wearing a brand new robe,'
EXEC add_BibleVerse @BibleId, 111011030, N'and he grabbed the robe and tore it into twelve pieces.'
EXEC add_BibleVerse @BibleId, 111011031, N'Then he told Jeroboam, “Take ten pieces, for this is what the Lord God of Israel says: ‘Look, I am about to tear the kingdom from Solomon’s hand and I will give ten tribes to you.'
EXEC add_BibleVerse @BibleId, 111011032, N'He will retain one tribe, for my servant David’s sake and for the sake of Jerusalem, the city I have chosen out of all the tribes of Israel.'
EXEC add_BibleVerse @BibleId, 111011033, N'I am taking the kingdom from him because they have abandoned me and worshiped the Sidonian goddess Astarte, the Moabite god Chemosh, and the Ammonite god Milcom. They have not followed my instructions by doing what I approve and obeying my rules and regulations, like Solomon’s father David did.'
EXEC add_BibleVerse @BibleId, 111011034, N'I will not take the whole kingdom from his hand. I will allow him to be ruler for the rest of his life for the sake of my chosen servant David who kept my commandments and rules.'
EXEC add_BibleVerse @BibleId, 111011035, N'I will take the kingdom from the hand of his son and give ten tribes to you.'
EXEC add_BibleVerse @BibleId, 111011036, N'I will leave his son one tribe so my servant David’s dynasty may continue to serve me in Jerusalem, the city I have chosen as my home.'
EXEC add_BibleVerse @BibleId, 111011037, N'I will select you; you will rule over all you desire to have and you will be king over Israel.'
EXEC add_BibleVerse @BibleId, 111011038, N'You must obey all I command you to do, follow my instructions, do what I approve, and keep my rules and commandments, like my servant David did. Then I will be with you and establish for you a lasting dynasty, as I did for David; I will give you Israel.'
EXEC add_BibleVerse @BibleId, 111011039, N'I will humiliate David’s descendants because of this, but not forever.”'
EXEC add_BibleVerse @BibleId, 111011040, N'Solomon tried to kill Jeroboam, but Jeroboam escaped to Egypt and found refuge with King Shishak of Egypt. He stayed in Egypt until Solomon died.'
EXEC add_BibleVerse @BibleId, 111011041, N'The rest of the events of Solomon’s reign, including all his accomplishments and his wise decisions, are recorded in the scroll called the Annals of Solomon.'
EXEC add_BibleVerse @BibleId, 111011042, N'Solomon ruled over all Israel from Jerusalem for forty years.'
EXEC add_BibleVerse @BibleId, 111011043, N'Then Solomon passed away and was buried in the city of his father David. His son Rehoboam replaced him as king.'
EXEC add_BibleVerse @BibleId, 111012001, N'Rehoboam traveled to Shechem, for all Israel had gathered in Shechem to make Rehoboam king.'
EXEC add_BibleVerse @BibleId, 111012002, N'When Jeroboam son of Nebat heard the news, he was still in Egypt, where he had fled from King Solomon and had been living ever since.'
EXEC add_BibleVerse @BibleId, 111012003, N'They sent for him, and Jeroboam and the whole Israelite assembly came and spoke to Rehoboam, saying,'
EXEC add_BibleVerse @BibleId, 111012004, N'“Your father made us work too hard. Now if you lighten the demands he made and don’t make us work as hard, we will serve you.”'
EXEC add_BibleVerse @BibleId, 111012005, N'He said to them, “Go away for three days, then return to me.” So the people went away.'
EXEC add_BibleVerse @BibleId, 111012006, N'King Rehoboam consulted with the older advisers who had served his father Solomon when he had been alive. He asked them, “How do you advise me to answer these people?”'
EXEC add_BibleVerse @BibleId, 111012007, N'They said to him, “Today if you show a willingness to help these people and grant their request, they will be your servants from this time forward.”'
EXEC add_BibleVerse @BibleId, 111012008, N'But Rehoboam rejected their advice and consulted the young advisers who served him, with whom he had grown up.'
EXEC add_BibleVerse @BibleId, 111012009, N'He asked them, “How do you advise me to respond to these people who said to me, ‘Lessen the demands your father placed on us’?”'
EXEC add_BibleVerse @BibleId, 111012010, N'The young advisers with whom Rehoboam had grown up said to him, “Say this to these people who have said to you, ‘Your father made us work hard, but now lighten our burden.’ Say this to them: ‘I am a lot harsher than my father!'
EXEC add_BibleVerse @BibleId, 111012011, N'My father imposed heavy demands on you; I will make them even heavier. My father punished you with ordinary whips; I will punish you with whips that really sting your flesh.’”'
EXEC add_BibleVerse @BibleId, 111012012, N'Jeroboam and all the people reported to Rehoboam on the third day, just as the king had ordered when he said, “Return to me on the third day.”'
EXEC add_BibleVerse @BibleId, 111012013, N'The king responded to the people harshly. He rejected the advice of the older men'
EXEC add_BibleVerse @BibleId, 111012014, N'and followed the advice of the younger ones. He said, “My father imposed heavy demands on you; I will make them even heavier. My father punished you with ordinary whips; I will punish you with whips that really sting your flesh.”'
EXEC add_BibleVerse @BibleId, 111012015, N'The king refused to listen to the people, because the Lord was instigating this turn of events so that he might bring to pass the prophetic announcement he had made through Ahijah the Shilonite to Jeroboam son of Nebat.'
EXEC add_BibleVerse @BibleId, 111012016, N'When all Israel saw that the king refused to listen to them, the people answered the king, “We have no portion in David, no share in the son of Jesse! Return to your homes, O Israel! Now, look after your own dynasty, O David!” So Israel returned to their homes.'
EXEC add_BibleVerse @BibleId, 111012017, N'(Rehoboam continued to rule over the Israelites who lived in the cities of Judah.)'
EXEC add_BibleVerse @BibleId, 111012018, N'King Rehoboam sent Adoniram, the supervisor of the work crews, out after them, but all Israel stoned him to death. King Rehoboam managed to jump into his chariot and escape to Jerusalem.'
EXEC add_BibleVerse @BibleId, 111012019, N'So Israel has been in rebellion against the Davidic dynasty to this very day.'
EXEC add_BibleVerse @BibleId, 111012020, N'When all Israel heard that Jeroboam had returned, they summoned him to the assembly and made him king over all Israel. No one except the tribe of Judah remained loyal to the Davidic dynasty.'
EXEC add_BibleVerse @BibleId, 111012021, N'When Rehoboam arrived in Jerusalem, he summoned 180,000 skilled warriors from all of Judah and the tribe of Benjamin to attack Israel and restore the kingdom to Rehoboam son of Solomon.'
EXEC add_BibleVerse @BibleId, 111012022, N'But God told Shemaiah the prophet,'
EXEC add_BibleVerse @BibleId, 111012023, N'“Say this to King Rehoboam son of Solomon of Judah, and to all Judah and Benjamin, as well as the rest of the people,'
EXEC add_BibleVerse @BibleId, 111012024, N'‘The Lord says this: “Do not attack and make war with your brothers, the Israelites. Each of you go home, for I have caused this to happen.”’” They obeyed the Lord and went home as the Lord had ordered them to do.'
EXEC add_BibleVerse @BibleId, 111012025, N'Jeroboam built up Shechem in the Ephraimite hill country and lived there. From there he went out and built up Penuel.'
EXEC add_BibleVerse @BibleId, 111012026, N'Jeroboam then thought to himself: “Now the Davidic dynasty could regain the kingdom.'
EXEC add_BibleVerse @BibleId, 111012027, N'If these people go up to offer sacrifices in the Lord’s temple in Jerusalem, their loyalty could shift to their former master, King Rehoboam of Judah. They might kill me and return to King Rehoboam of Judah.”'
EXEC add_BibleVerse @BibleId, 111012028, N'After the king had consulted with his advisers, he made two golden calves. Then he said to the people, “It is too much trouble for you to go up to Jerusalem. Look, Israel, here are your gods who brought you up from the land of Egypt.”'
EXEC add_BibleVerse @BibleId, 111012029, N'He put one in Bethel and the other in Dan.'
EXEC add_BibleVerse @BibleId, 111012030, N'This caused Israel to sin; the people went to Bethel and Dan to worship the calves.'
EXEC add_BibleVerse @BibleId, 111012031, N'He built temples on the high places and appointed as priests people who were not Levites.'
EXEC add_BibleVerse @BibleId, 111012032, N'Jeroboam inaugurated a festival on the fifteenth day of the eighth month, like the festival celebrated in Judah. On the altar in Bethel he offered sacrifices to the calves he had made. In Bethel he also appointed priests for the high places he had made.'
EXEC add_BibleVerse @BibleId, 111012033, N'On the fifteenth day of the eighth month (a date he had arbitrarily chosen) Jeroboam offered sacrifices on the altar he had made in Bethel. He inaugurated a festival for the Israelites and went up to the altar to offer sacrifices.'
EXEC add_BibleVerse @BibleId, 111013001, N'Just then a prophet from Judah, sent by the Lord, arrived in Bethel, as Jeroboam was standing near the altar ready to offer a sacrifice.'
EXEC add_BibleVerse @BibleId, 111013002, N'With the authority of the Lord he cried out against the altar, “O altar, altar! This is what the Lord says, ‘Look, a son named Josiah will be born to the Davidic dynasty. He will sacrifice on you the priests of the high places who offer sacrifices on you. Human bones will be burned on you.’”'
EXEC add_BibleVerse @BibleId, 111013003, N'That day he also announced a sign, “This is the sign the Lord has predetermined: The altar will be split open and the ashes on it will fall to the ground.”'
EXEC add_BibleVerse @BibleId, 111013004, N'When the king heard what the prophet cried out against the altar in Bethel, Jeroboam, standing at the altar, extended his hand and ordered, “Seize him!” The hand he had extended shriveled up and he could not pull it back.'
EXEC add_BibleVerse @BibleId, 111013005, N'The altar split open and the ashes fell from the altar to the ground, in fulfillment of the sign the prophet had announced with the Lord’s authority.'
EXEC add_BibleVerse @BibleId, 111013006, N'The king pled with the prophet, “Seek the favor of the Lord your God and pray for me, so that my hand may be restored.” So the prophet sought the Lord’s favor and the king’s hand was restored to its former condition.'
EXEC add_BibleVerse @BibleId, 111013007, N'The king then said to the prophet, “Come home with me and have something to eat. I’d like to give a present.”'
EXEC add_BibleVerse @BibleId, 111013008, N'But the prophet said to the king, “Even if you were to give me half your possessions, I could not go with you and eat and drink in this place.'
EXEC add_BibleVerse @BibleId, 111013009, N'For the Lord gave me strict orders, ‘Do not eat or drink there and do not go home the way you came.’”'
EXEC add_BibleVerse @BibleId, 111013010, N'So he started back on another road; he did not travel back on the same road he had taken to Bethel.'
EXEC add_BibleVerse @BibleId, 111013011, N'Now there was an old prophet living in Bethel. When his sons came home, they told their father everything the prophet had done in Bethel that day and all the words he had spoken to the king.'
EXEC add_BibleVerse @BibleId, 111013012, N'Their father asked them, “Which road did he take?” His sons showed him the road the prophet from Judah had taken.'
EXEC add_BibleVerse @BibleId, 111013013, N'He then told his sons, “Saddle the donkey for me.” When they had saddled the donkey for him, he mounted it'
EXEC add_BibleVerse @BibleId, 111013014, N'and took off after the prophet, whom he found sitting under an oak tree. He asked him, “Are you the prophet from Judah?” He answered, “Yes, I am.”'
EXEC add_BibleVerse @BibleId, 111013015, N'He then said to him, “Come home with me and eat something.”'
EXEC add_BibleVerse @BibleId, 111013016, N'But he replied, “I can’t go back with you or eat and drink with you in this place.'
EXEC add_BibleVerse @BibleId, 111013017, N'For the Lord gave me strict orders, ‘Do not eat or drink there; do not go back the way you came.’”'
EXEC add_BibleVerse @BibleId, 111013018, N'The old prophet then said, “I too am a prophet like you. An angel told me with the Lord’s authority, ‘Bring him back with you to your house so he can eat and drink.’” But he was lying to him.'
EXEC add_BibleVerse @BibleId, 111013019, N'So the prophet went back with him and ate and drank in his house.'
EXEC add_BibleVerse @BibleId, 111013020, N'While they were sitting at the table, the Lord spoke through the old prophet'
EXEC add_BibleVerse @BibleId, 111013021, N'and he cried out to the prophet from Judah, “This is what the Lord says, ‘You have rebelled against the Lord and have not obeyed the command the Lord your God gave you.'
EXEC add_BibleVerse @BibleId, 111013022, N'You went back and ate and drank in this place, even though he said to you, “Do not eat or drink there.” Therefore your corpse will not be buried in your ancestral tomb.’”'
EXEC add_BibleVerse @BibleId, 111013023, N'When the prophet from Judah finished his meal, the old prophet saddled his visitor’s donkey for him.'
EXEC add_BibleVerse @BibleId, 111013024, N'As the prophet from Judah was traveling, a lion attacked him on the road and killed him. His corpse was lying on the road, and the donkey and the lion just stood there beside it.'
EXEC add_BibleVerse @BibleId, 111013025, N'Some men came by and saw the corpse lying in the road with the lion standing beside it. They went and reported what they had seen in the city where the old prophet lived.'
EXEC add_BibleVerse @BibleId, 111013026, N'When the old prophet who had invited him to his house heard the news, he said, “It is the prophet who rebelled against the Lord. The Lord delivered him over to the lion and it ripped him up and killed him, just as the Lord warned him.”'
EXEC add_BibleVerse @BibleId, 111013027, N'He told his sons, “Saddle my donkey,” and they did so.'
EXEC add_BibleVerse @BibleId, 111013028, N'He went and found the corpse lying in the road with the donkey and the lion standing beside it; the lion had neither eaten the corpse nor attacked the donkey.'
EXEC add_BibleVerse @BibleId, 111013029, N'The old prophet picked up the corpse of the prophet, put it on the donkey, and brought it back. The old prophet then entered the city to mourn him and to bury him.'
EXEC add_BibleVerse @BibleId, 111013030, N'He put the corpse into his own tomb, and they mourned over him, saying, “Ah, my brother!”'
EXEC add_BibleVerse @BibleId, 111013031, N'After he buried him, he said to his sons, “When I die, bury me in the tomb where the prophet is buried; put my bones right beside his bones,'
EXEC add_BibleVerse @BibleId, 111013032, N'for the prophecy he announced with the Lord’s authority against the altar in Bethel and against all the temples on the high places in the cities of the north will certainly be fulfilled.”'
EXEC add_BibleVerse @BibleId, 111013033, N'After this happened, Jeroboam still did not change his evil ways; he continued to appoint common people as priests at the high places. Anyone who wanted the job he consecrated as a priest.'
EXEC add_BibleVerse @BibleId, 111013034, N'This sin caused Jeroboam’s dynasty to come to an end and to be destroyed from the face of the earth.'
EXEC add_BibleVerse @BibleId, 111014001, N'At that time Jeroboam’s son Abijah became sick.'
EXEC add_BibleVerse @BibleId, 111014002, N'Jeroboam told his wife, “Disguise yourself so that people cannot recognize you are Jeroboam’s wife. Then go to Shiloh; Ahijah the prophet, who told me I would rule over this nation, lives there.'
EXEC add_BibleVerse @BibleId, 111014003, N'Take ten loaves of bread, some small cakes, and a container of honey and visit him. He will tell you what will happen to the boy.”'
EXEC add_BibleVerse @BibleId, 111014004, N'Jeroboam’s wife did as she was told. She went to Shiloh and visited Ahijah. Now Ahijah could not see; he had lost his eyesight in his old age.'
EXEC add_BibleVerse @BibleId, 111014005, N'But the Lord had told Ahijah, “Look, Jeroboam’s wife is coming to find out from you what will happen to her son, for he is sick. Tell her so-and-so. When she comes, she will be in a disguise.”'
EXEC add_BibleVerse @BibleId, 111014006, N'When Ahijah heard the sound of her footsteps as she came through the door, he said, “Come on in, wife of Jeroboam! Why are you pretending to be someone else? I have been commissioned to give you bad news.'
EXEC add_BibleVerse @BibleId, 111014007, N'Go, tell Jeroboam, ‘This is what the Lord God of Israel says: “I raised you up from among the people and made you ruler over my people Israel.'
EXEC add_BibleVerse @BibleId, 111014008, N'I tore the kingdom away from the Davidic dynasty and gave it to you. But you are not like my servant David, who kept my commandments and followed me wholeheartedly by doing only what I approve.'
EXEC add_BibleVerse @BibleId, 111014009, N'You have sinned more than all who came before you. You went and angered me by making other gods, formed out of metal; you have completely disregarded me.'
EXEC add_BibleVerse @BibleId, 111014010, N'So I am ready to bring disaster on the dynasty of Jeroboam. I will cut off every last male belonging to Jeroboam in Israel, including even the weak and incapacitated. I will burn up the dynasty of Jeroboam, just as one burns manure until it is completely consumed.'
EXEC add_BibleVerse @BibleId, 111014011, N'Dogs will eat the members of your family who die in the city, and the birds of the sky will eat the ones who die in the country.”’ Indeed, the Lord has announced it!'
EXEC add_BibleVerse @BibleId, 111014012, N'“As for you, get up and go home. When you set foot in the city, the boy will die.'
EXEC add_BibleVerse @BibleId, 111014013, N'All Israel will mourn him and bury him. He is the only one in Jeroboam’s family who will receive a decent burial, for he is the only one in whom the Lord God of Israel found anything good.'
EXEC add_BibleVerse @BibleId, 111014014, N'The Lord will raise up a king over Israel who will cut off Jeroboam’s dynasty. It is ready to happen!'
EXEC add_BibleVerse @BibleId, 111014015, N'The Lord will attack Israel, making it like a reed that sways in the water. He will remove Israel from this good land he gave to their ancestors and scatter them beyond the Euphrates River, because they angered the Lord by making Asherah poles.'
EXEC add_BibleVerse @BibleId, 111014016, N'He will hand Israel over to their enemies because of the sins which Jeroboam committed and which he made Israel commit.”'
EXEC add_BibleVerse @BibleId, 111014017, N'So Jeroboam’s wife got up and went back to Tirzah. As she crossed the threshold of the house, the boy died.'
EXEC add_BibleVerse @BibleId, 111014018, N'All Israel buried him and mourned for him, just as the Lord had predicted through his servant the prophet Ahijah.'
EXEC add_BibleVerse @BibleId, 111014019, N'The rest of the events of Jeroboam’s reign, including the details of his battles and rule, are recorded in the scroll called the Annals of the Kings of Israel.'
EXEC add_BibleVerse @BibleId, 111014020, N'Jeroboam ruled for twenty-two years; then he passed away. His son Nadab replaced him as king.'
EXEC add_BibleVerse @BibleId, 111014021, N'Now Rehoboam son of Solomon ruled in Judah. He was forty-one years old when he became king and he ruled for seventeen years in Jerusalem, the city the Lord chose from all the tribes of Israel to be his home. His mother was an Ammonite woman named Naamah.'
EXEC add_BibleVerse @BibleId, 111014022, N'Judah did evil in the sight of the Lord. They made him more jealous by their sins than their ancestors had done.'
EXEC add_BibleVerse @BibleId, 111014023, N'They even built for themselves high places, sacred pillars, and Asherah poles on every high hill and under every green tree.'
EXEC add_BibleVerse @BibleId, 111014024, N'There were also male cultic prostitutes in the land. They committed the same horrible sins as the nations that the Lord had driven out from before the Israelites.'
EXEC add_BibleVerse @BibleId, 111014025, N'In King Rehoboam’s fifth year, King Shishak of Egypt attacked Jerusalem.'
EXEC add_BibleVerse @BibleId, 111014026, N'He took away the treasures of the Lord’s temple and of the royal palace; he took everything, including all the golden shields that Solomon had made.'
EXEC add_BibleVerse @BibleId, 111014027, N'King Rehoboam made bronze shields to replace them and assigned them to the officers of the royal guard who protected the entrance to the royal palace.'
EXEC add_BibleVerse @BibleId, 111014028, N'Whenever the king visited the Lord’s temple, the royal guard carried them and then brought them back to the guardroom.'
EXEC add_BibleVerse @BibleId, 111014029, N'The rest of the events of Rehoboam’s reign, including his accomplishments, are recorded in the scroll called the Annals of the Kings of Judah.'
EXEC add_BibleVerse @BibleId, 111014030, N'Rehoboam and Jeroboam were continually at war with each other.'
EXEC add_BibleVerse @BibleId, 111014031, N'Rehoboam passed away and was buried with his ancestors in the city of David. His mother was an Ammonite named Naamah. His son Abijah replaced him as king.'
EXEC add_BibleVerse @BibleId, 111015001, N'In the eighteenth year of the reign of Jeroboam son of Nebat, Abijah became king over Judah.'
EXEC add_BibleVerse @BibleId, 111015002, N'He ruled for three years in Jerusalem. His mother was Maacah, the daughter of Abishalom.'
EXEC add_BibleVerse @BibleId, 111015003, N'He followed all the sinful practices of his father before him. He was not wholeheartedly devoted to the Lord his God, as his ancestor David had been.'
EXEC add_BibleVerse @BibleId, 111015004, N'Nevertheless for David’s sake the Lord his God maintained his dynasty in Jerusalem by giving him a son to succeed him and by protecting Jerusalem.'
EXEC add_BibleVerse @BibleId, 111015005, N'He did this because David had done what he approved and had not disregarded any of his commandments his entire lifetime, except for the incident involving Uriah the Hittite.'
EXEC add_BibleVerse @BibleId, 111015006, N'Rehoboam and Jeroboam were continually at war with each other throughout Abijah’s lifetime.'
EXEC add_BibleVerse @BibleId, 111015007, N'The rest of the events of Abijah’s reign, including all his accomplishments, are recorded in the scroll called the Annals of the Kings of Judah. Abijah and Jeroboam had been at war with each other.'
EXEC add_BibleVerse @BibleId, 111015008, N'Abijah passed away and was buried in the city of David. His son Asa replaced him as king.'
EXEC add_BibleVerse @BibleId, 111015009, N'In the twentieth year of Jeroboam’s reign over Israel, Asa became the king of Judah.'
EXEC add_BibleVerse @BibleId, 111015010, N'He ruled for forty-one years in Jerusalem. His grandmother was Maacah daughter of Abishalom.'
EXEC add_BibleVerse @BibleId, 111015011, N'Asa did what the Lord approved like his ancestor David had done.'
EXEC add_BibleVerse @BibleId, 111015012, N'He removed the male cultic prostitutes from the land and got rid of all the disgusting idols his ancestors had made.'
EXEC add_BibleVerse @BibleId, 111015013, N'He also removed Maacah his grandmother from her position as queen because she had made a loathsome Asherah pole. Asa cut down her Asherah pole and burned it in the Kidron Valley.'
EXEC add_BibleVerse @BibleId, 111015014, N'The high places were not eliminated, yet Asa was wholeheartedly devoted to the Lord throughout his lifetime.'
EXEC add_BibleVerse @BibleId, 111015015, N'He brought the holy items that he and his father had made into the Lord’s temple, including the silver, gold, and other articles.'
EXEC add_BibleVerse @BibleId, 111015016, N'Now Asa and King Baasha of Israel were continually at war with each other.'
EXEC add_BibleVerse @BibleId, 111015017, N'King Baasha of Israel attacked Judah and established Ramah as a military outpost to prevent anyone from leaving or entering the land of King Asa of Judah.'
EXEC add_BibleVerse @BibleId, 111015018, N'Asa took all the silver and gold that was left in the treasuries of the Lord’s temple and of the royal palace and handed it to his servants. He then told them to deliver it to Ben Hadad son of Tabrimmon, the son of Hezion, king of Syria, ruler in Damascus, along with this message:'
EXEC add_BibleVerse @BibleId, 111015019, N'“I want to make a treaty with you, like the one our fathers made. See, I have sent you silver and gold as a present. Break your treaty with King Baasha of Israel, so he will retreat from my land.”'
EXEC add_BibleVerse @BibleId, 111015020, N'Ben Hadad accepted King Asa’s offer and ordered his army commanders to attack the cities of Israel. They conquered Ijon, Dan, Abel Beth Maacah, and all the territory of Naphtali, including the region of Kinnereth.'
EXEC add_BibleVerse @BibleId, 111015021, N'When Baasha heard the news, he stopped fortifying Ramah and settled down in Tirzah.'
EXEC add_BibleVerse @BibleId, 111015022, N'King Asa ordered all the men of Judah (no exemptions were granted) to carry away the stones and wood that Baasha had used to build Ramah. King Asa used the materials to build up Geba (in Benjamin) and Mizpah.'
EXEC add_BibleVerse @BibleId, 111015023, N'The rest of the events of Asa’s reign, including all his successes and accomplishments, as well as a record of the cities he built, are recorded in the scroll called the Annals of the Kings of Judah. Yet when he was very old he developed a foot disease.'
EXEC add_BibleVerse @BibleId, 111015024, N'Asa passed away and was buried with his ancestors in the city of his ancestor David. His son Jehoshaphat replaced him as king.'
EXEC add_BibleVerse @BibleId, 111015025, N'In the second year of Asa’s reign over Judah, Jeroboam’s son Nadab became the king of Israel; he ruled Israel for two years.'
EXEC add_BibleVerse @BibleId, 111015026, N'He did evil in the sight of the Lord. He followed in his father’s footsteps and encouraged Israel to sin.'
EXEC add_BibleVerse @BibleId, 111015027, N'Baasha son of Ahijah, from the tribe of Issachar, conspired against Nadab and assassinated him in Gibbethon, which was in Philistine territory. This happened while Nadab and all the Israelite army were besieging Gibbethon.'
EXEC add_BibleVerse @BibleId, 111015028, N'Baasha killed him in the third year of Asa’s reign over Judah and replaced him as king.'
EXEC add_BibleVerse @BibleId, 111015029, N'When he became king, he executed Jeroboam’s entire family. He wiped out everyone who breathed, just as the Lord had predicted through his servant Ahijah the Shilonite.'
EXEC add_BibleVerse @BibleId, 111015030, N'This happened because of the sins which Jeroboam committed and which he made Israel commit. These sins angered the Lord God of Israel.'
EXEC add_BibleVerse @BibleId, 111015031, N'The rest of the events of Nadab’s reign, including all his accomplishments, are recorded in the scroll called the Annals of the Kings of Israel.'
EXEC add_BibleVerse @BibleId, 111015032, N'Asa and King Nadab of Israel were continually at war with each other.'
EXEC add_BibleVerse @BibleId, 111015033, N'In the third year of Asa’s reign over Judah, Baasha son of Ahijah became king over all Israel in Tirzah; he ruled for twenty-four years.'
EXEC add_BibleVerse @BibleId, 111015034, N'He did evil in the sight of the Lord; he followed in Jeroboam’s footsteps and encouraged Israel to sin.'
EXEC add_BibleVerse @BibleId, 111016001, N'Jehu son of Hanani received from the Lord this message predicting Baasha’s downfall:'
EXEC add_BibleVerse @BibleId, 111016002, N'“I raised you up from the dust and made you ruler over my people Israel. Yet you followed in Jeroboam’s footsteps and encouraged my people Israel to sin; their sins have made me angry.'
EXEC add_BibleVerse @BibleId, 111016003, N'So I am ready to burn up Baasha and his family, and make your family like the family of Jeroboam son of Nebat.'
EXEC add_BibleVerse @BibleId, 111016004, N'Dogs will eat the members of Baasha’s family who die in the city, and the birds of the sky will eat the ones who die in the country.”'
EXEC add_BibleVerse @BibleId, 111016005, N'The rest of the events of Baasha’s reign, including his accomplishments and successes, are recorded in the scroll called the Annals of the Kings of Israel.'
EXEC add_BibleVerse @BibleId, 111016006, N'Baasha passed away and was buried in Tirzah. His son Elah replaced him as king.'
EXEC add_BibleVerse @BibleId, 111016007, N'The prophet Jehu son of Hanani received from the Lord the message predicting the downfall of Baasha and his family because of all the evil Baasha had done in the sight of the Lord. His actions angered the Lord (including the way he had destroyed Jeroboam’s dynasty), so that his family ended up like Jeroboam’s.'
EXEC add_BibleVerse @BibleId, 111016008, N'In the twenty-sixth year of King Asa’s reign over Judah, Baasha’s son Elah became king over Israel; he ruled in Tirzah for two years.'
EXEC add_BibleVerse @BibleId, 111016009, N'His servant Zimri, a commander of half of his chariot force, conspired against him. While Elah was drinking heavily at the house of Arza, who supervised the palace in Tirzah,'
EXEC add_BibleVerse @BibleId, 111016010, N'Zimri came in and struck him dead. (This happened in the twenty-seventh year of Asa’s reign over Judah.) Zimri replaced Elah as king.'
EXEC add_BibleVerse @BibleId, 111016011, N'When he became king and occupied the throne, he killed Baasha’s entire family. He did not spare any male belonging to him; he killed his relatives and his friends.'
EXEC add_BibleVerse @BibleId, 111016012, N'Zimri destroyed Baasha’s entire family, just as the Lord had predicted to Baasha through Jehu the prophet.'
EXEC add_BibleVerse @BibleId, 111016013, N'This happened because of all the sins which Baasha and his son Elah committed and which they made Israel commit. They angered the Lord God of Israel with their worthless idols.'
EXEC add_BibleVerse @BibleId, 111016014, N'The rest of the events of Elah’s reign, including all his accomplishments, are recorded in the scroll called the Annals of the Kings of Israel.'
EXEC add_BibleVerse @BibleId, 111016015, N'In the twenty-seventh year of Asa’s reign over Judah, Zimri became king over Israel; he ruled for seven days in Tirzah. Zimri’s revolt took place while the army was deployed in Gibbethon, which was in Philistine territory.'
EXEC add_BibleVerse @BibleId, 111016016, N'While deployed there, the army received this report: “Zimri has conspired against the king and assassinated him.” So all Israel made Omri, the commander of the army, king over Israel that very day in the camp.'
EXEC add_BibleVerse @BibleId, 111016017, N'Omri and all Israel went up from Gibbethon and besieged Tirzah.'
EXEC add_BibleVerse @BibleId, 111016018, N'When Zimri saw that the city was captured, he went into the fortified area of the royal palace. He set the palace on fire and died in the flames.'
EXEC add_BibleVerse @BibleId, 111016019, N'This happened because of the sins he committed. He did evil in the sight of the Lord and followed in Jeroboam’s footsteps and encouraged Israel to continue sinning.'
EXEC add_BibleVerse @BibleId, 111016020, N'The rest of the events of Zimri’s reign, including the details of his revolt, are recorded in the scroll called the Annals of the Kings of Israel.'
EXEC add_BibleVerse @BibleId, 111016021, N'At that time the people of Israel were divided in their loyalties. Half the people supported Tibni son of Ginath and wanted to make him king; the other half supported Omri.'
EXEC add_BibleVerse @BibleId, 111016022, N'Omri’s supporters were stronger than those who supported Tibni son of Ginath. Tibni died; Omri became king.'
EXEC add_BibleVerse @BibleId, 111016023, N'In the thirty-first year of Asa’s reign over Judah, Omri became king over Israel. He ruled for twelve years, six of them in Tirzah.'
EXEC add_BibleVerse @BibleId, 111016024, N'He purchased the hill of Samaria from Shemer for two talents of silver. He launched a construction project there and named the city he built after Shemer, the former owner of the hill of Samaria.'
EXEC add_BibleVerse @BibleId, 111016025, N'Omri did more evil in the sight of the Lord than all who were before him.'
EXEC add_BibleVerse @BibleId, 111016026, N'He followed in the footsteps of Jeroboam son of Nebat and encouraged Israel to sin; they angered the Lord God of Israel with their worthless idols.'
EXEC add_BibleVerse @BibleId, 111016027, N'The rest of the events of Omri’s reign, including his accomplishments and successes, are recorded in the scroll called the Annals of the Kings of Israel.'
EXEC add_BibleVerse @BibleId, 111016028, N'Omri passed away and was buried in Samaria. His son Ahab replaced him as king.'
EXEC add_BibleVerse @BibleId, 111016029, N'In the thirty-eighth year of Asa’s reign over Judah, Omri’s son Ahab became king over Israel. Ahab son of Omri ruled over Israel for twenty-two years in Samaria.'
EXEC add_BibleVerse @BibleId, 111016030, N'Ahab son of Omri did more evil in the sight of the Lord than all who were before him.'
EXEC add_BibleVerse @BibleId, 111016031, N'As if following in the sinful footsteps of Jeroboam son of Nebat were not bad enough, he married Jezebel the daughter of King Ethbaal of the Sidonians. Then he worshiped and bowed to Baal.'
EXEC add_BibleVerse @BibleId, 111016032, N'He set up an altar for Baal in the temple of Baal he had built in Samaria.'
EXEC add_BibleVerse @BibleId, 111016033, N'Ahab also made an Asherah pole; he did more to anger the Lord God of Israel than all the kings of Israel who were before him.'
EXEC add_BibleVerse @BibleId, 111016034, N'During Ahab’s reign, Hiel the Bethelite rebuilt Jericho. Abiram, his firstborn son, died when he laid the foundation; Segub, his youngest son, died when he erected its gates, just as the Lord had warned through Joshua son of Nun.'
EXEC add_BibleVerse @BibleId, 111017001, N'Elijah the Tishbite, from Tishbe in Gilead, said to Ahab, “As certainly as the Lord God of Israel lives (whom I serve), there will be no dew or rain in the years ahead unless I give the command.”'
EXEC add_BibleVerse @BibleId, 111017002, N'The Lord told him:'
EXEC add_BibleVerse @BibleId, 111017003, N'“Leave here and travel eastward. Hide out in the Kerith Valley near the Jordan.'
EXEC add_BibleVerse @BibleId, 111017004, N'Drink from the stream; I have already told the ravens to bring you food there.”'
EXEC add_BibleVerse @BibleId, 111017005, N'So he did as the Lord told him; he went and lived in the Kerith Valley near the Jordan.'
EXEC add_BibleVerse @BibleId, 111017006, N'The ravens would bring him bread and meat each morning and evening, and he would drink from the stream.'
EXEC add_BibleVerse @BibleId, 111017007, N'After a while, the stream dried up because there had been no rain in the land.'
EXEC add_BibleVerse @BibleId, 111017008, N'The Lord told him,'
EXEC add_BibleVerse @BibleId, 111017009, N'“Get up, go to Zarephath in Sidonian territory, and live there. I have already told a widow who lives there to provide for you.”'
EXEC add_BibleVerse @BibleId, 111017010, N'So he got up and went to Zarephath. When he went through the city gate, there was a widow gathering wood. He called out to her, “Please give me a cup of water, so I can take a drink.”'
EXEC add_BibleVerse @BibleId, 111017011, N'As she went to get it, he called out to her, “Please bring me a piece of bread.”'
EXEC add_BibleVerse @BibleId, 111017012, N'She said, “As certainly as the Lord your God lives, I have no food, except for a handful of flour in a jar and a little olive oil in a jug. Right now I am gathering a couple of sticks for a fire. Then I’m going home to make one final meal for my son and myself. After we have eaten that, we will die of starvation.”'
EXEC add_BibleVerse @BibleId, 111017013, N'Elijah said to her, “Don’t be afraid. Go and do as you planned. But first make a small cake for me and bring it to me; then make something for yourself and your son.'
EXEC add_BibleVerse @BibleId, 111017014, N'For this is what the Lord God of Israel says, ‘The jar of flour will not be empty and the jug of oil will not run out until the day the Lord makes it rain on the surface of the ground.’”'
EXEC add_BibleVerse @BibleId, 111017015, N'She went and did as Elijah told her; there was always enough food for Elijah and for her and her family.'
EXEC add_BibleVerse @BibleId, 111017016, N'The jar of flour was never empty and the jug of oil never ran out, just as the Lord had promised through Elijah.'
EXEC add_BibleVerse @BibleId, 111017017, N'After this the son of the woman who owned the house got sick. His illness was so severe he could no longer breathe.'
EXEC add_BibleVerse @BibleId, 111017018, N'She asked Elijah, “Why, prophet, have you come to me to confront me with my sin and kill my son?”'
EXEC add_BibleVerse @BibleId, 111017019, N'He said to her, “Hand me your son.” He took him from her arms, carried him to the upper room where he was staying, and laid him down on his bed.'
EXEC add_BibleVerse @BibleId, 111017020, N'Then he called out to the Lord, “O Lord, my God, are you also bringing disaster on this widow I am staying with by killing her son?”'
EXEC add_BibleVerse @BibleId, 111017021, N'He stretched out over the boy three times and called out to the Lord, “O Lord, my God, please let this boy’s breath return to him.”'
EXEC add_BibleVerse @BibleId, 111017022, N'The Lord answered Elijah’s prayer; the boy’s breath returned to him and he lived.'
EXEC add_BibleVerse @BibleId, 111017023, N'Elijah took the boy, brought him down from the upper room to the house, and handed him to his mother. Elijah then said, “See, your son is alive!”'
EXEC add_BibleVerse @BibleId, 111017024, N'The woman said to Elijah, “Now I know that you are a prophet and that the Lord really does speak through you.”'
EXEC add_BibleVerse @BibleId, 111018001, N'Some time later, in the third year of the famine, the Lord told Elijah, “Go, make an appearance before Ahab, so I may send rain on the surface of the ground.”'
EXEC add_BibleVerse @BibleId, 111018002, N'So Elijah went to make an appearance before Ahab. Now the famine was severe in Samaria.'
EXEC add_BibleVerse @BibleId, 111018003, N'So Ahab summoned Obadiah, who supervised the palace. (Now Obadiah was a very loyal follower of the Lord.'
EXEC add_BibleVerse @BibleId, 111018004, N'When Jezebel was killing the Lord’s prophets, Obadiah took one hundred prophets and hid them in two caves in two groups of fifty. He also brought them food and water.)'
EXEC add_BibleVerse @BibleId, 111018005, N'Ahab told Obadiah, “Go through the land to all the springs and valleys. Maybe we can find some grazing areas so we can keep the horses and mules alive and not have to kill some of the animals.”'
EXEC add_BibleVerse @BibleId, 111018006, N'They divided up the land between them; Ahab went one way and Obadiah went the other.'
EXEC add_BibleVerse @BibleId, 111018007, N'As Obadiah was traveling along, Elijah met him. When he recognized him, he fell facedown to the ground and said, “Is it really you, my master, Elijah?”'
EXEC add_BibleVerse @BibleId, 111018008, N'He replied, “Yes, go and say to your master, ‘Elijah is back.’”'
EXEC add_BibleVerse @BibleId, 111018009, N'Obadiah said, “What sin have I committed that you are ready to hand your servant over to Ahab for execution?'
EXEC add_BibleVerse @BibleId, 111018010, N'As certainly as the Lord your God lives, my master has sent to every nation and kingdom in an effort to find you. When they say, ‘He’s not here,’ he makes them swear an oath that they could not find you.'
EXEC add_BibleVerse @BibleId, 111018011, N'Now you say, ‘Go and say to your master, “Elijah is back.”’'
EXEC add_BibleVerse @BibleId, 111018012, N'But when I leave you, the Lord’s spirit will carry you away so I can’t find you. If I go tell Ahab I’ve seen you, he won’t be able to find you and he will kill me. That would not be fair, because your servant has been a loyal follower of the Lord from my youth.'
EXEC add_BibleVerse @BibleId, 111018013, N'Certainly my master is aware of what I did when Jezebel was killing the Lord’s prophets. I hid one hundred of the Lord’s prophets in two caves in two groups of fifty and I brought them food and water.'
EXEC add_BibleVerse @BibleId, 111018014, N'Now you say, ‘Go and say to your master, “Elijah is back,”’ but he will kill me.”'
EXEC add_BibleVerse @BibleId, 111018015, N'But Elijah said, “As certainly as the Lord who rules over all lives (whom I serve), I will make an appearance before him today.”'
EXEC add_BibleVerse @BibleId, 111018016, N'When Obadiah went and informed Ahab, the king went to meet Elijah.'
EXEC add_BibleVerse @BibleId, 111018017, N'When Ahab saw Elijah, he said to him, “Is it really you, the one who brings disaster on Israel?”'
EXEC add_BibleVerse @BibleId, 111018018, N'Elijah replied, “I have not brought disaster on Israel. But you and your father’s dynasty have, by abandoning the Lord’s commandments and following the Baals.'
EXEC add_BibleVerse @BibleId, 111018019, N'Now send out messengers and assemble all Israel before me at Mount Carmel, as well as the 450 prophets of Baal and 400 prophets of Asherah whom Jezebel supports.'
EXEC add_BibleVerse @BibleId, 111018020, N'Ahab sent messengers to all the Israelites and had the prophets assemble at Mount Carmel.'
EXEC add_BibleVerse @BibleId, 111018021, N'Elijah approached all the people and said, “How long are you going to be paralyzed by indecision? If the Lord is the true God, then follow him, but if Baal is, follow him!” But the people did not say a word.'
EXEC add_BibleVerse @BibleId, 111018022, N'Elijah said to them: “I am the only prophet of the Lord who is left, but there are 450 prophets of Baal.'
EXEC add_BibleVerse @BibleId, 111018023, N'Let them bring us two bulls. Let them choose one of the bulls for themselves, cut it up into pieces, and place it on the wood. But they must not set it on fire. I will do the same to the other bull and place it on the wood. But I will not set it on fire.'
EXEC add_BibleVerse @BibleId, 111018024, N'Then you will invoke the name of your god, and I will invoke the name of the Lord. The god who responds with fire will demonstrate that he is the true God.” All the people responded, “This will be a fair test.”'
EXEC add_BibleVerse @BibleId, 111018025, N'Elijah told the prophets of Baal, “Choose one of the bulls for yourselves and go first, for you are the majority. Invoke the name of your god, but do not light a fire.”'
EXEC add_BibleVerse @BibleId, 111018026, N'So they took a bull, as he had suggested, and prepared it. They invoked the name of Baal from morning until noon, saying, “Baal, answer us.” But there was no sound and no answer. They jumped around on the altar they had made.'
EXEC add_BibleVerse @BibleId, 111018027, N'At noon Elijah mocked them, “Yell louder! After all, he is a god; he may be deep in thought, or perhaps he stepped out for a moment or has taken a trip. Perhaps he is sleeping and needs to be awakened.”'
EXEC add_BibleVerse @BibleId, 111018028, N'So they yelled louder and, in accordance with their prescribed ritual, mutilated themselves with swords and spears until their bodies were covered with blood.'
EXEC add_BibleVerse @BibleId, 111018029, N'Throughout the afternoon they were in an ecstatic frenzy, but there was no sound, no answer, and no response.'
EXEC add_BibleVerse @BibleId, 111018030, N'Elijah then told all the people, “Approach me.” So all the people approached him. He repaired the altar of the Lord that had been torn down.'
EXEC add_BibleVerse @BibleId, 111018031, N'Then Elijah took twelve stones, corresponding to the number of tribes that descended from Jacob, to whom the Lord had said, “Israel will be your new name.”'
EXEC add_BibleVerse @BibleId, 111018032, N'With the stones he constructed an altar for the Lord. Around the altar he made a trench large enough to contain two seahs of seed.'
EXEC add_BibleVerse @BibleId, 111018033, N'He arranged the wood, cut up the bull, and placed it on the wood.'
EXEC add_BibleVerse @BibleId, 111018034, N'Then he said, “Fill four water jars and pour the water on the offering and the wood.” When they had done so, he said, “Do it again.” So they did it again. Then he said, “Do it a third time.” So they did it a third time.'
EXEC add_BibleVerse @BibleId, 111018035, N'The water flowed down all sides of the altar and filled the trench.'
EXEC add_BibleVerse @BibleId, 111018036, N'When it was time for the evening offering, Elijah the prophet approached the altar and prayed: “O Lord God of Abraham, Isaac, and Israel, prove today that you are God in Israel and that I am your servant and have done all these things at your command.'
EXEC add_BibleVerse @BibleId, 111018037, N'Answer me, O Lord, answer me, so these people will know that you, O Lord, are the true God and that you are winning back their allegiance.”'
EXEC add_BibleVerse @BibleId, 111018038, N'Then fire from the Lord fell from the sky. It consumed the offering, the wood, the stones, and the dirt, and licked up the water in the trench.'
EXEC add_BibleVerse @BibleId, 111018039, N'When all the people saw this, they threw themselves down with their faces to the ground and said, “The Lord is the true God! The Lord is the true God!”'
EXEC add_BibleVerse @BibleId, 111018040, N'Elijah told them, “Seize the prophets of Baal! Don’t let even one of them escape!” So they seized them, and Elijah led them down to the Kishon Valley and executed them there.'
EXEC add_BibleVerse @BibleId, 111018041, N'Then Elijah told Ahab, “Go on up and eat and drink, for the sound of a heavy rainstorm can be heard.”'
EXEC add_BibleVerse @BibleId, 111018042, N'So Ahab went on up to eat and drink, while Elijah climbed to the top of Carmel. He bent down toward the ground and put his face between his knees.'
EXEC add_BibleVerse @BibleId, 111018043, N'He told his servant, “Go on up and look in the direction of the sea.” So he went on up, looked, and reported, “There is nothing.” Seven times Elijah sent him to look.'
EXEC add_BibleVerse @BibleId, 111018044, N'The seventh time the servant said, “Look, a small cloud, the size of the palm of a man’s hand, is rising up from the sea.” Elijah then said, “Go and tell Ahab, ‘Hitch up the chariots and go down, so that the rain won’t overtake you.’”'
EXEC add_BibleVerse @BibleId, 111018045, N'Meanwhile the sky was covered with dark clouds, the wind blew, and there was a heavy rainstorm. Ahab rode toward Jezreel.'
EXEC add_BibleVerse @BibleId, 111018046, N'Now the Lord energized Elijah with power; he tucked his robe into his belt and ran ahead of Ahab all the way to Jezreel.'
EXEC add_BibleVerse @BibleId, 111019001, N'Ahab told Jezebel all that Elijah had done, including a detailed account of how he killed all the prophets with the sword.'
EXEC add_BibleVerse @BibleId, 111019002, N'Jezebel sent a messenger to Elijah with this warning, “May the gods judge me severely if by this time tomorrow I do not take your life as you did theirs!”'
EXEC add_BibleVerse @BibleId, 111019003, N'Elijah was afraid, so he got up and fled for his life to Beer Sheba in Judah. He left his servant there,'
EXEC add_BibleVerse @BibleId, 111019004, N'while he went a day’s journey into the desert. He went and sat down under a shrub and asked the Lord to take his life: “I’ve had enough! Now, O Lord, take my life. After all, I’m no better than my ancestors.”'
EXEC add_BibleVerse @BibleId, 111019005, N'He stretched out and fell asleep under the shrub. All of a sudden an angelic messenger touched him and said, “Get up and eat.”'
EXEC add_BibleVerse @BibleId, 111019006, N'He looked and right there by his head was a cake baking on hot coals and a jug of water. He ate and drank and then slept some more.'
EXEC add_BibleVerse @BibleId, 111019007, N'The Lord’s angelic messenger came back again, touched him, and said, “Get up and eat, for otherwise you won’t be able to make the journey.”'
EXEC add_BibleVerse @BibleId, 111019008, N'So he got up and ate and drank. That meal gave him the strength to travel forty days and forty nights until he reached Horeb, the mountain of God.'
EXEC add_BibleVerse @BibleId, 111019009, N'He went into a cave there and spent the night. All of a sudden the Lord spoke to him, “Why are you here, Elijah?”'
EXEC add_BibleVerse @BibleId, 111019010, N'He answered, “I have been absolutely loyal to the Lord, the sovereign God, even though the Israelites have abandoned the agreement they made with you, torn down your altars, and killed your prophets with the sword. I alone am left and now they want to take my life.”'
EXEC add_BibleVerse @BibleId, 111019011, N'The Lord said, “Go out and stand on the mountain before the Lord. Look, the Lord is ready to pass by.” A very powerful wind went before the Lord, digging into the mountain and causing landslides, but the Lord was not in the wind. After the windstorm there was an earthquake, but the Lord was not in the earthquake.'
EXEC add_BibleVerse @BibleId, 111019012, N'After the earthquake, there was a fire, but the Lord was not in the fire. After the fire, there was a soft whisper.'
EXEC add_BibleVerse @BibleId, 111019013, N'When Elijah heard it, he covered his face with his robe and went out and stood at the entrance to the cave. All of a sudden a voice asked him, “Why are you here, Elijah?”'
EXEC add_BibleVerse @BibleId, 111019014, N'He answered, “I have been absolutely loyal to the Lord, the sovereign God, even though the Israelites have abandoned the agreement they made with you, torn down your altars, and killed your prophets with the sword. I alone am left and now they want to take my life.”'
EXEC add_BibleVerse @BibleId, 111019015, N'The Lord said to him, “Go back the way you came and then head for the Desert of Damascus. Go and anoint Hazael king over Syria.'
EXEC add_BibleVerse @BibleId, 111019016, N'You must anoint Jehu son of Nimshi king over Israel, and Elisha son of Shaphat from Abel Meholah to take your place as prophet.'
EXEC add_BibleVerse @BibleId, 111019017, N'Jehu will kill anyone who escapes Hazael’s sword, and Elisha will kill anyone who escapes Jehu’s sword.'
EXEC add_BibleVerse @BibleId, 111019018, N'I still have left in Israel seven thousand followers who have not bowed their knees to Baal or kissed the images of him.”'
EXEC add_BibleVerse @BibleId, 111019019, N'Elijah went from there and found Elisha son of Shaphat. He was plowing with twelve pairs of oxen; he was near the twelfth pair. Elijah passed by him and threw his robe over him.'
EXEC add_BibleVerse @BibleId, 111019020, N'He left the oxen, ran after Elijah, and said, “Please let me kiss my father and mother goodbye, then I will follow you.” Elijah said to him, “Go back! Indeed, what have I done to you?”'
EXEC add_BibleVerse @BibleId, 111019021, N'Elisha went back and took his pair of oxen and slaughtered them. He cooked the meat over a fire that he made by burning the harness and yoke. He gave the people meat and they ate. Then he got up and followed Elijah and became his assistant.'
EXEC add_BibleVerse @BibleId, 111020001, N'Now King Ben Hadad of Syria assembled all his army, along with thirty-two other kings with their horses and chariots. He marched against Samaria and besieged and attacked it.'
EXEC add_BibleVerse @BibleId, 111020002, N'He sent messengers to King Ahab of Israel, who was in the city.'
EXEC add_BibleVerse @BibleId, 111020003, N'He said to him, “This is what Ben Hadad says, ‘Your silver and your gold are mine, as well as the best of your wives and sons.’”'
EXEC add_BibleVerse @BibleId, 111020004, N'The king of Israel replied, “It is just as you say, my master, O king. I and all I own belong to you.”'
EXEC add_BibleVerse @BibleId, 111020005, N'The messengers came again and said, “This is what Ben Hadad says, ‘I sent this message to you, “You must give me your silver, gold, wives, and sons.”'
EXEC add_BibleVerse @BibleId, 111020006, N'But now at this time tomorrow I will send my servants to you and they will search through your palace and your servants’ houses. They will carry away all your valuables.”'
EXEC add_BibleVerse @BibleId, 111020007, N'The king of Israel summoned all the leaders of the land and said, “Notice how this man is looking for trouble. Indeed, he demanded my wives, sons, silver, and gold, and I did not resist him.”'
EXEC add_BibleVerse @BibleId, 111020008, N'All the leaders and people said to him, “Do not give in or agree to his demands.”'
EXEC add_BibleVerse @BibleId, 111020009, N'So he said to the messengers of Ben Hadad, “Say this to my master, the king, ‘I will give you everything you demanded at first from your servant, but I am unable to agree to this latest demand.’” So the messengers went back and gave their report.'
EXEC add_BibleVerse @BibleId, 111020010, N'Ben Hadad sent another message to him, “May the gods judge me severely if there is enough dirt left in Samaria for my soldiers to scoop up in their hands.”'
EXEC add_BibleVerse @BibleId, 111020011, N'The king of Israel replied, “Tell him the one who puts on his battle gear should not boast like one who is taking it off.”'
EXEC add_BibleVerse @BibleId, 111020012, N'When Ben Hadad received this reply, he and the other kings were drinking in their quarters. He ordered his servants, “Get ready to attack!” So they got ready to attack the city.'
EXEC add_BibleVerse @BibleId, 111020013, N'Now a prophet visited King Ahab of Israel and said, “This is what the Lord says, ‘Do you see this huge army? Look, I am going to hand it over to you this very day. Then you will know that I am the Lord.’”'
EXEC add_BibleVerse @BibleId, 111020014, N'Ahab asked, “By whom will this be accomplished?” He answered, “This is what the Lord says, ‘By the servants of the district governors.’” Ahab asked, “Who will launch the attack?” He answered, “You will.”'
EXEC add_BibleVerse @BibleId, 111020015, N'So Ahab assembled the 232 servants of the district governors. After that he assembled all the Israelite army, numbering 7,000.'
EXEC add_BibleVerse @BibleId, 111020016, N'They marched out at noon, while Ben Hadad and the thirty-two kings allied with him were drinking heavily in their quarters.'
EXEC add_BibleVerse @BibleId, 111020017, N'The servants of the district governors led the march. When Ben Hadad sent messengers, they reported back to him, “Men are marching out of Samaria.”'
EXEC add_BibleVerse @BibleId, 111020018, N'He ordered, “Whether they come in peace or to do battle, take them alive.”'
EXEC add_BibleVerse @BibleId, 111020019, N'They marched out of the city with the servants of the district governors in the lead and the army behind them.'
EXEC add_BibleVerse @BibleId, 111020020, N'Each one struck down an enemy soldier; the Syrians fled and Israel chased them. King Ben Hadad of Syria escaped on horseback with some horsemen.'
EXEC add_BibleVerse @BibleId, 111020021, N'Then the king of Israel marched out and struck down the horses and chariots; he thoroughly defeated Syria.'
EXEC add_BibleVerse @BibleId, 111020022, N'The prophet visited the king of Israel and instructed him, “Go, fortify your defenses. Determine what you must do, for in the spring the king of Syria will attack you.”'
EXEC add_BibleVerse @BibleId, 111020023, N'Now the advisers of the king of Syria said to him: “Their God is a god of the mountains. That’s why they overpowered us. But if we fight them in the plains, we will certainly overpower them.'
EXEC add_BibleVerse @BibleId, 111020024, N'So do this: Dismiss the kings from their command, and replace them with military commanders.'
EXEC add_BibleVerse @BibleId, 111020025, N'Muster an army like the one you lost, with the same number of horses and chariots. Then we will fight them in the plains; we will certainly overpower them.” He approved their plan and did as they advised.'
EXEC add_BibleVerse @BibleId, 111020026, N'In the spring Ben Hadad mustered the Syrian army and marched to Aphek to fight Israel.'
EXEC add_BibleVerse @BibleId, 111020027, N'When the Israelites had mustered and had received their supplies, they marched out to face them in battle. When the Israelites deployed opposite them, they were like two small flocks of goats, but the Syrians filled the land.'
EXEC add_BibleVerse @BibleId, 111020028, N'The prophet visited the king of Israel and said, “This is what the Lord says: ‘Because the Syrians said, “The Lord is a god of the mountains and not a god of the valleys,” I will hand over to you this entire huge army. Then you will know that I am the Lord.’”'
EXEC add_BibleVerse @BibleId, 111020029, N'The armies were deployed opposite each other for seven days. On the seventh day the battle began, and the Israelites killed 100,000 Syrian foot soldiers in one day.'
EXEC add_BibleVerse @BibleId, 111020030, N'The remaining 27,000 ran to Aphek and went into the city, but the wall fell on them. Now Ben Hadad ran into the city and hid in an inner room.'
EXEC add_BibleVerse @BibleId, 111020031, N'His advisers said to him, “Look, we have heard that the kings of the Israelite dynasty are kind. Allow us to put sackcloth around our waists and ropes on our heads and surrender to the king of Israel. Maybe he will spare our lives.”'
EXEC add_BibleVerse @BibleId, 111020032, N'So they put sackcloth around their waists and ropes on their heads and went to the king of Israel. They said, “Your servant Ben Hadad says, ‘Please let me live!’” Ahab replied, “Is he still alive? He is my brother.”'
EXEC add_BibleVerse @BibleId, 111020033, N'The men took this as a good omen and quickly accepted his offer, saying, “Ben Hadad is your brother.” Ahab then said, “Go, get him.” So Ben Hadad came out to him, and Ahab pulled him up into his chariot.'
EXEC add_BibleVerse @BibleId, 111020034, N'Ben Hadad said, “I will return the cities my father took from your father. You may set up markets in Damascus, just as my father did in Samaria.” Ahab then said, “I want to make a treaty with you before I dismiss you.” So he made a treaty with him and then dismissed him.'
EXEC add_BibleVerse @BibleId, 111020035, N'One of the members of the prophetic guild, speaking with divine authority, ordered his companion, “Wound me!” But the man refused to wound him.'
EXEC add_BibleVerse @BibleId, 111020036, N'So the prophet said to him, “Because you have disobeyed the Lord, as soon as you leave me a lion will kill you.” When he left him, a lion attacked and killed him.'
EXEC add_BibleVerse @BibleId, 111020037, N'He found another man and said, “Wound me!” So the man wounded him severely.'
EXEC add_BibleVerse @BibleId, 111020038, N'The prophet then went and stood by the road, waiting for the king. He also disguised himself by putting a bandage down over his eyes.'
EXEC add_BibleVerse @BibleId, 111020039, N'When the king passed by, he called out to the king, “Your servant went out into the heat of the battle, and then a man turned aside and brought me a prisoner. He told me, ‘Guard this prisoner. If he ends up missing for any reason, you will pay with your life or with a talent of silver.’'
EXEC add_BibleVerse @BibleId, 111020040, N'Well, it just so happened that while your servant was doing this and that, he disappeared.” The king of Israel said to him, “Your punishment is already determined by your own testimony.”'
EXEC add_BibleVerse @BibleId, 111020041, N'The prophet quickly removed the bandage from his eyes and the king of Israel recognized he was one of the prophets.'
EXEC add_BibleVerse @BibleId, 111020042, N'The prophet then said to him, “This is what the Lord says, ‘Because you released a man I had determined should die, you will pay with your life and your people will suffer instead of his people.’”'
EXEC add_BibleVerse @BibleId, 111020043, N'The king of Israel went home to Samaria bitter and angry.'
EXEC add_BibleVerse @BibleId, 111021001, N'After this the following episode took place. Naboth the Jezreelite owned a vineyard in Jezreel adjacent to the palace of King Ahab of Samaria.'
EXEC add_BibleVerse @BibleId, 111021002, N'Ahab said to Naboth, “Give me your vineyard so I can make a vegetable garden out of it, for it is adjacent to my palace. I will give you an even better vineyard in its place, or if you prefer, I will pay you silver for it.”'
EXEC add_BibleVerse @BibleId, 111021003, N'But Naboth replied to Ahab, “The Lord forbid that I should sell you my ancestral inheritance.”'
EXEC add_BibleVerse @BibleId, 111021004, N'So Ahab went into his palace, bitter and angry that Naboth the Jezreelite had said, “I will not sell to you my ancestral inheritance.” He lay down on his bed, pouted, and would not eat.'
EXEC add_BibleVerse @BibleId, 111021005, N'Then his wife Jezebel came in and said to him, “Why do you have a bitter attitude and refuse to eat?”'
EXEC add_BibleVerse @BibleId, 111021006, N'He answered her, “While I was talking to Naboth the Jezreelite, I said to him, ‘Sell me your vineyard for silver, or if you prefer, I will give you another vineyard in its place.’ But he said, ‘I will not sell you my vineyard.’”'
EXEC add_BibleVerse @BibleId, 111021007, N'His wife Jezebel said to him, “You are the king of Israel! Get up, eat some food, and have a good time. I will get the vineyard of Naboth the Jezreelite for you.”'
EXEC add_BibleVerse @BibleId, 111021008, N'She wrote out orders, signed Ahab’s name to them, and sealed them with his seal. She then sent the orders to the leaders and to the nobles who lived in Naboth’s city.'
EXEC add_BibleVerse @BibleId, 111021009, N'This is what she wrote: “Observe a time of fasting and seat Naboth in front of the people.'
EXEC add_BibleVerse @BibleId, 111021010, N'Also seat two villains opposite him and have them testify, ‘You cursed God and the king.’ Then take him out and stone him to death.”'
EXEC add_BibleVerse @BibleId, 111021011, N'The men of the city, the leaders and the nobles who lived there, followed the written orders Jezebel had sent them.'
EXEC add_BibleVerse @BibleId, 111021012, N'They observed a time of fasting and put Naboth in front of the people.'
EXEC add_BibleVerse @BibleId, 111021013, N'The two villains arrived and sat opposite him. Then the villains testified against Naboth right before the people, saying, “Naboth cursed God and the king.” So they dragged him outside the city and stoned him to death.'
EXEC add_BibleVerse @BibleId, 111021014, N'Then they reported to Jezebel, “Naboth has been stoned to death.”'
EXEC add_BibleVerse @BibleId, 111021015, N'When Jezebel heard that Naboth had been stoned to death, she said to Ahab, “Get up, take possession of the vineyard Naboth the Jezreelite refused to sell you for silver, for Naboth is no longer alive; he’s dead.”'
EXEC add_BibleVerse @BibleId, 111021016, N'When Ahab heard that Naboth was dead, he got up and went down to take possession of the vineyard of Naboth the Jezreelite.'
EXEC add_BibleVerse @BibleId, 111021017, N'The Lord told Elijah the Tishbite:'
EXEC add_BibleVerse @BibleId, 111021018, N'“Get up, go down and meet King Ahab of Israel who lives in Samaria. He is at the vineyard of Naboth; he has gone down there to take possession of it.'
EXEC add_BibleVerse @BibleId, 111021019, N'Say to him, ‘This is what the Lord says: “Haven’t you committed murder and taken possession of the property of the deceased?”’ Then say to him, ‘This is what the Lord says: “In the spot where dogs licked up Naboth’s blood they will also lick up your blood – yes, yours!”’”'
EXEC add_BibleVerse @BibleId, 111021020, N'When Elijah arrived, Ahab said to him, “So, you have found me, my enemy!” Elijah replied, “I have found you, because you are committed to doing evil in the sight of the Lord.'
EXEC add_BibleVerse @BibleId, 111021021, N'The Lord says, ‘Look, I am ready to bring disaster on you. I will destroy you and cut off every last male belonging to Ahab in Israel, including even the weak and incapacitated.'
EXEC add_BibleVerse @BibleId, 111021022, N'I will make your dynasty like those of Jeroboam son of Nebat and Baasha son of Ahijah because you angered me and made Israel sin.’'
EXEC add_BibleVerse @BibleId, 111021023, N'The Lord says this about Jezebel, ‘Dogs will devour Jezebel by the outer wall of Jezreel.’'
EXEC add_BibleVerse @BibleId, 111021024, N'As for Ahab’s family, dogs will eat the ones who die in the city, and the birds of the sky will eat the ones who die in the country.”'
EXEC add_BibleVerse @BibleId, 111021025, N'(There had never been anyone like Ahab, who was firmly committed to doing evil in the sight of the Lord, urged on by his wife Jezebel.'
EXEC add_BibleVerse @BibleId, 111021026, N'He was so wicked he worshiped the disgusting idols, just like the Amorites whom the Lord had driven out from before the Israelites.)'
EXEC add_BibleVerse @BibleId, 111021027, N'When Ahab heard these words, he tore his clothes, put on sackcloth, and fasted. He slept in sackcloth and walked around dejected.'
EXEC add_BibleVerse @BibleId, 111021028, N'The Lord said to Elijah the Tishbite,'
EXEC add_BibleVerse @BibleId, 111021029, N'“Have you noticed how Ahab shows remorse before me? Because he shows remorse before me, I will not bring disaster on his dynasty during his lifetime, but during the reign of his son.”'
EXEC add_BibleVerse @BibleId, 111022001, N'There was no war between Syria and Israel for three years.'
EXEC add_BibleVerse @BibleId, 111022002, N'In the third year King Jehoshaphat of Judah came down to visit the king of Israel.'
EXEC add_BibleVerse @BibleId, 111022003, N'The king of Israel said to his servants, “Surely you recognize that Ramoth Gilead belongs to us, though we are hesitant to reclaim it from the king of Syria.”'
EXEC add_BibleVerse @BibleId, 111022004, N'Then he said to Jehoshaphat, “Will you go with me to attack Ramoth Gilead?” Jehoshaphat replied to the king of Israel, “I will support you; my army and horses are at your disposal.”'
EXEC add_BibleVerse @BibleId, 111022005, N'Then Jehoshaphat added, “First seek an oracle from the Lord.”'
EXEC add_BibleVerse @BibleId, 111022006, N'So the king of Israel assembled about four hundred prophets and asked them, “Should I attack Ramoth Gilead or not?” They said, “Attack! The sovereign one will hand it over to the king.”'
EXEC add_BibleVerse @BibleId, 111022007, N'But Jehoshaphat asked, “Is there not a prophet of the Lord still here, that we may ask him?”'
EXEC add_BibleVerse @BibleId, 111022008, N'The king of Israel answered Jehoshaphat, “There is still one man through whom we can seek the Lord’s will. But I despise him because he does not prophesy prosperity for me, but disaster. His name is Micaiah son of Imlah. Jehoshaphat said, “The king should not say such things.”'
EXEC add_BibleVerse @BibleId, 111022009, N'The king of Israel summoned an official and said, “Quickly bring Micaiah son of Imlah.”'
EXEC add_BibleVerse @BibleId, 111022010, N'Now the king of Israel and King Jehoshaphat of Judah were sitting on their respective thrones, dressed in their robes, at the threshing floor at the entrance of the gate of Samaria. All the prophets were prophesying before them.'
EXEC add_BibleVerse @BibleId, 111022011, N'Zedekiah son of Kenaanah made iron horns and said, “This is what the Lord says, ‘With these you will gore Syria until they are destroyed.’”'
EXEC add_BibleVerse @BibleId, 111022012, N'All the prophets were prophesying the same, saying, “Attack Ramoth Gilead! You will succeed; the Lord will hand it over to the king.”'
EXEC add_BibleVerse @BibleId, 111022013, N'Now the messenger who went to summon Micaiah said to him, “Look, the prophets are in complete agreement that the king will succeed. Your words must agree with theirs; you must predict success.”'
EXEC add_BibleVerse @BibleId, 111022014, N'But Micaiah said, “As certainly as the Lord lives, I will say what the Lord tells me to say.”'
EXEC add_BibleVerse @BibleId, 111022015, N'When he came before the king, the king asked him, “Micaiah, should we attack Ramoth Gilead or not?” He answered him, “Attack! You will succeed; the Lord will hand it over to the king.”'
EXEC add_BibleVerse @BibleId, 111022016, N'The king said to him, “How many times must I make you solemnly promise in the name of the Lord to tell me only the truth?”'
EXEC add_BibleVerse @BibleId, 111022017, N'Micaiah said, “I saw all Israel scattered on the mountains like sheep that have no shepherd. Then the Lord said, ‘They have no master. They should go home in peace.’”'
EXEC add_BibleVerse @BibleId, 111022018, N'The king of Israel said to Jehoshaphat, “Didn’t I tell you he does not prophesy prosperity for me, but disaster?”'
EXEC add_BibleVerse @BibleId, 111022019, N'Micaiah said, “That being the case, hear the word of the Lord. I saw the Lord sitting on his throne, with all the heavenly assembly standing on his right and on his left.'
EXEC add_BibleVerse @BibleId, 111022020, N'The Lord said, ‘Who will deceive Ahab, so he will attack Ramoth Gilead and die there?’ One said this and another that.'
EXEC add_BibleVerse @BibleId, 111022021, N'Then a spirit stepped forward and stood before the Lord. He said, ‘I will deceive him.’ The Lord asked him, ‘How?’'
EXEC add_BibleVerse @BibleId, 111022022, N'He replied, ‘I will go out and be a lying spirit in the mouths of all his prophets.’ The Lord said, ‘Deceive and overpower him. Go out and do as you have proposed.’'
EXEC add_BibleVerse @BibleId, 111022023, N'So now, look, the Lord has placed a lying spirit in the mouths of all these prophets of yours; but the Lord has decreed disaster for you.”'
EXEC add_BibleVerse @BibleId, 111022024, N'Zedekiah son of Kenaanah approached, hit Micaiah on the jaw, and said, “Which way did the Lord’s spirit go when he went from me to speak to you?”'
EXEC add_BibleVerse @BibleId, 111022025, N'Micaiah replied, “Look, you will see in the day when you go into an inner room to hide.”'
EXEC add_BibleVerse @BibleId, 111022026, N'Then the king of Israel said, “Take Micaiah and return him to Amon the city official and Joash the king’s son.'
EXEC add_BibleVerse @BibleId, 111022027, N'Say, ‘This is what the king says, “Put this man in prison. Give him only a little bread and water until I safely return.”’”'
EXEC add_BibleVerse @BibleId, 111022028, N'Micaiah said, “If you really do safely return, then the Lord has not spoken through me.” Then he added, “Take note, all you people.”'
EXEC add_BibleVerse @BibleId, 111022029, N'The king of Israel and King Jehoshaphat of Judah attacked Ramoth Gilead.'
EXEC add_BibleVerse @BibleId, 111022030, N'The king of Israel said to Jehoshaphat, “I will disguise myself and then enter into the battle; but you wear your royal robes.” So the king of Israel disguised himself and then entered into the battle.'
EXEC add_BibleVerse @BibleId, 111022031, N'Now the king of Syria had ordered his thirty-two chariot commanders, “Do not fight common soldiers or high-ranking officers; fight only the king of Israel.”'
EXEC add_BibleVerse @BibleId, 111022032, N'When the chariot commanders saw Jehoshaphat, they said, “He must be the king of Israel.” So they turned and attacked him, but Jehoshaphat cried out.'
EXEC add_BibleVerse @BibleId, 111022033, N'When the chariot commanders realized he was not the king of Israel, they turned away from him.'
EXEC add_BibleVerse @BibleId, 111022034, N'Now an archer shot an arrow at random, and it struck the king of Israel between the plates of his armor. The king ordered his charioteer, “Turn around and take me from the battle line, because I’m wounded.”'
EXEC add_BibleVerse @BibleId, 111022035, N'While the battle raged throughout the day, the king stood propped up in his chariot opposite the Syrians. He died in the evening; the blood from the wound ran down into the bottom of the chariot.'
EXEC add_BibleVerse @BibleId, 111022036, N'As the sun was setting, a cry went through the camp, “Each one should return to his city and to his homeland.”'
EXEC add_BibleVerse @BibleId, 111022037, N'So the king died and was taken to Samaria, where they buried him.'
EXEC add_BibleVerse @BibleId, 111022038, N'They washed off the chariot at the pool of Samaria (this was where the prostitutes bathed); dogs licked his blood, just as the Lord had said would happen.'
EXEC add_BibleVerse @BibleId, 111022039, N'The rest of the events of Ahab’s reign, including a record of his accomplishments and how he built a luxurious palace and various cities, are recorded in the scroll called the Annals of the Kings of Israel.'
EXEC add_BibleVerse @BibleId, 111022040, N'Ahab passed away. His son Ahaziah replaced him as king.'
EXEC add_BibleVerse @BibleId, 111022041, N'In the fourth year of King Ahab’s reign over Israel, Asa’s son Jehoshaphat became king over Judah.'
EXEC add_BibleVerse @BibleId, 111022042, N'Jehoshaphat was thirty-five years old when he became king and he reigned for twenty-five years in Jerusalem. His mother was Azubah, the daughter of Shilhi.'
EXEC add_BibleVerse @BibleId, 111022043, N'He followed in his father Asa’s footsteps and was careful to do what the Lord approved. However, the high places were not eliminated; the people continued to offer sacrifices and burn incense on the high places.'
EXEC add_BibleVerse @BibleId, 111022044, N'Jehoshaphat was also at peace with the king of Israel.'
EXEC add_BibleVerse @BibleId, 111022045, N'The rest of the events of Jehoshaphat’s reign, including his successes and military exploits, are recorded in the scroll called the Annals of the Kings of Judah.'
EXEC add_BibleVerse @BibleId, 111022046, N'He removed from the land any male cultic prostitutes who had managed to survive the reign of his father Asa.'
EXEC add_BibleVerse @BibleId, 111022047, N'There was no king in Edom at this time; a governor ruled.'
EXEC add_BibleVerse @BibleId, 111022048, N'Jehoshaphat built a fleet of large merchant ships to travel to Ophir for gold, but they never made the voyage because they were shipwrecked in Ezion Geber.'
EXEC add_BibleVerse @BibleId, 111022049, N'Then Ahaziah son of Ahab said to Jehoshaphat, “Let my sailors join yours in the fleet,” but Jehoshaphat refused.'
EXEC add_BibleVerse @BibleId, 111022050, N'Jehoshaphat passed away and was buried with his ancestors in the city of his ancestor David. His son Jehoram replaced him as king.'
EXEC add_BibleVerse @BibleId, 111022051, N'In the seventeenth year of King Jehoshaphat’s reign over Judah, Ahab’s son Ahaziah became king over Israel in Samaria. He ruled for two years over Israel.'
EXEC add_BibleVerse @BibleId, 111022052, N'He did evil in the sight of the Lord and followed in the footsteps of his father and mother; like Jeroboam son of Nebat, he encouraged Israel to sin.'
EXEC add_BibleVerse @BibleId, 111022053, N'He worshiped and bowed down to Baal, angering the Lord God of Israel just as his father had done.'
EXEC add_BibleVerse @BibleId, 112001001, N'After Ahab died, Moab rebelled against Israel.'
EXEC add_BibleVerse @BibleId, 112001002, N'Ahaziah fell through a window lattice in his upper chamber in Samaria and was injured. He sent messengers with these orders, “Go, ask Baal Zebub, the god of Ekron, if I will survive this injury.”'
EXEC add_BibleVerse @BibleId, 112001003, N'But the Lord’s angelic messenger told Elijah the Tishbite, “Get up, go to meet the messengers from the king of Samaria. Say this to them: ‘You must think there is no God in Israel! That explains why you are on your way to seek an oracle from Baal Zebub the god of Ekron.'
EXEC add_BibleVerse @BibleId, 112001004, N'Therefore this is what the Lord says, “You will not leave the bed you lie on, for you will certainly die!”’” So Elijah went on his way.'
EXEC add_BibleVerse @BibleId, 112001005, N'When the messengers returned to the king, he asked them, “Why have you returned?”'
EXEC add_BibleVerse @BibleId, 112001006, N'They replied, “A man came up to meet us. He told us, “Go back to the king who sent you and tell him, ‘This is what the Lord says: “You must think there is no God in Israel! That explains why you are sending for an oracle from Baal Zebub, the god of Ekron. Therefore you will not leave the bed you lie on, for you will certainly die.”’”'
EXEC add_BibleVerse @BibleId, 112001007, N'The king asked them, “Describe the appearance of this man who came up to meet you and told you these things.”'
EXEC add_BibleVerse @BibleId, 112001008, N'They replied, “He was a hairy man and had a leather belt tied around his waist.” The king said, “He is Elijah the Tishbite.”'
EXEC add_BibleVerse @BibleId, 112001009, N'The king sent a captain and his fifty soldiers to retrieve Elijah. The captain went up to him, while he was sitting on the top of a hill. He told him, “Prophet, the king says, ‘Come down!’”'
EXEC add_BibleVerse @BibleId, 112001010, N'Elijah replied to the captain, “If I am indeed a prophet, may fire come down from the sky and consume you and your fifty soldiers!” Fire then came down from the sky and consumed him and his fifty soldiers.'
EXEC add_BibleVerse @BibleId, 112001011, N'The king sent another captain and his fifty soldiers to retrieve Elijah. He went up and told him, “Prophet, this is what the king says, ‘Come down at once!’”'
EXEC add_BibleVerse @BibleId, 112001012, N'Elijah replied to them, “If I am indeed a prophet, may fire come down from the sky and consume you and your fifty soldiers!” Fire from God came down from the sky and consumed him and his fifty soldiers.'
EXEC add_BibleVerse @BibleId, 112001013, N'The king sent a third captain and his fifty soldiers. This third captain went up and fell on his knees before Elijah. He begged for mercy, “Prophet, please have respect for my life and for the lives of these fifty servants of yours.'
EXEC add_BibleVerse @BibleId, 112001014, N'Indeed, fire came down from the sky and consumed the two captains who came before me, along with their men. So now, please have respect for my life.”'
EXEC add_BibleVerse @BibleId, 112001015, N'The Lord’s angelic messenger said to Elijah, “Go down with him. Don’t be afraid of him.” So he got up and went down with him to the king.'
EXEC add_BibleVerse @BibleId, 112001016, N'Elijah said to the king, “This is what the Lord says, ‘You sent messengers to seek an oracle from Baal Zebub, the god of Ekron. You must think there is no God in Israel from whom you can seek an oracle! Therefore you will not leave the bed you lie on, for you will certainly die.’”'
EXEC add_BibleVerse @BibleId, 112001017, N'He died just as the Lord had prophesied through Elijah. In the second year of the reign of King Jehoram son of Jehoshaphat over Judah, Ahaziah’s brother Jehoram replaced him as king of Israel, because he had no son.'
EXEC add_BibleVerse @BibleId, 112001018, N'The rest of the events of Ahaziah’s reign, including his accomplishments, are recorded in the scroll called the Annals of the Kings of Israel.'
EXEC add_BibleVerse @BibleId, 112002001, N'Just before the Lord took Elijah up to heaven in a windstorm, Elijah and Elisha were traveling from Gilgal.'
EXEC add_BibleVerse @BibleId, 112002002, N'Elijah told Elisha, “Stay here, for the Lord has sent me to Bethel.” But Elisha said, “As certainly as the Lord lives and as you live, I will not leave you.” So they went down to Bethel.'
EXEC add_BibleVerse @BibleId, 112002003, N'Some members of the prophetic guild in Bethel came out to Elisha and said, “Do you know that today the Lord is going to take your master from you?” He answered, “Yes, I know. Be quiet.”'
EXEC add_BibleVerse @BibleId, 112002004, N'Elijah said to him, “Elisha, stay here, for the Lord has sent me to Jericho.” But he replied, “As certainly as the Lord lives and as you live, I will not leave you.” So they went to Jericho.'
EXEC add_BibleVerse @BibleId, 112002005, N'Some members of the prophetic guild in Jericho approached Elisha and said, “Do you know that today the Lord is going to take your master from you?” He answered, “Yes, I know. Be quiet.”'
EXEC add_BibleVerse @BibleId, 112002006, N'Elijah said to him, “Stay here, for the Lord has sent me to the Jordan.” But he replied, “As certainly as the Lord lives and as you live, I will not leave you.” So they traveled on together.'
EXEC add_BibleVerse @BibleId, 112002007, N'The fifty members of the prophetic guild went and stood opposite them at a distance, while Elijah and Elisha stood by the Jordan.'
EXEC add_BibleVerse @BibleId, 112002008, N'Elijah took his cloak, folded it up, and hit the water with it. The water divided, and the two of them crossed over on dry ground.'
EXEC add_BibleVerse @BibleId, 112002009, N'When they had crossed over, Elijah said to Elisha, “What can I do for you, before I am taken away from you?” Elisha answered, “May I receive a double portion of the prophetic spirit that energizes you.”'
EXEC add_BibleVerse @BibleId, 112002010, N'Elijah replied, “That’s a difficult request! If you see me taken from you, may it be so, but if you don’t, it will not happen.”'
EXEC add_BibleVerse @BibleId, 112002011, N'As they were walking along and talking, suddenly a fiery chariot pulled by fiery horses appeared. They went between Elijah and Elisha, and Elijah went up to heaven in a windstorm.'
EXEC add_BibleVerse @BibleId, 112002012, N'While Elisha was watching, he was crying out, “My father, my father! The chariot and horsemen of Israel!” Then he could no longer see him. He grabbed his clothes and tore them in two.'
EXEC add_BibleVerse @BibleId, 112002013, N'He picked up Elijah’s cloak, which had fallen off him, and went back and stood on the shore of the Jordan.'
EXEC add_BibleVerse @BibleId, 112002014, N'He took the cloak that had fallen off Elijah, hit the water with it, and said, “Where is the Lord, the God of Elijah?” When he hit the water, it divided and Elisha crossed over.'
EXEC add_BibleVerse @BibleId, 112002015, N'When the members of the prophetic guild in Jericho, who were standing at a distance, saw him do this, they said, “The spirit that energized Elijah rests upon Elisha.” They went to meet him and bowed down to the ground before him.'
EXEC add_BibleVerse @BibleId, 112002016, N'They said to him, “Look, there are fifty capable men with your servants. Let them go and look for your master, for the wind sent from the Lord may have carried him away and dropped him on one of the hills or in one of the valleys.” But Elisha replied, “Don’t send them out.”'
EXEC add_BibleVerse @BibleId, 112002017, N'But they were so insistent, he became embarrassed. So he said, “Send them out.” They sent the fifty men out and they looked for three days, but could not find Elijah.'
EXEC add_BibleVerse @BibleId, 112002018, N'When they came back, Elisha was staying in Jericho. He said to them, “Didn’t I tell you, ‘Don’t go’?”'
EXEC add_BibleVerse @BibleId, 112002019, N'The men of the city said to Elisha, “Look, the city has a good location, as our master can see. But the water is bad and the land doesn’t produce crops.”'
EXEC add_BibleVerse @BibleId, 112002020, N'Elisha said, “Get me a new jar and put some salt in it.” So they got it.'
EXEC add_BibleVerse @BibleId, 112002021, N'He went out to the spring and threw the salt in. Then he said, “This is what the Lord says, ‘I have purified this water. It will no longer cause death or fail to produce crops.”'
EXEC add_BibleVerse @BibleId, 112002022, N'The water has been pure to this very day, just as Elisha prophesied.'
EXEC add_BibleVerse @BibleId, 112002023, N'He went up from there to Bethel. As he was traveling up the road, some young boys came out of the city and made fun of him, saying, “Go on up, baldy! Go on up, baldy!”'
EXEC add_BibleVerse @BibleId, 112002024, N'When he turned around and saw them, he called God’s judgment down on them. Two female bears came out of the woods and ripped forty-two of the boys to pieces.'
EXEC add_BibleVerse @BibleId, 112002025, N'From there he traveled to Mount Carmel and then back to Samaria.'
EXEC add_BibleVerse @BibleId, 112003001, N'In the eighteenth year of King Jehoshaphat’s reign over Judah, Ahab’s son Jehoram became king over Israel in Samaria; he ruled for twelve years.'
EXEC add_BibleVerse @BibleId, 112003002, N'He did evil in the sight of the Lord, but not to the same degree as his father and mother. He did remove the sacred pillar of Baal that his father had made.'
EXEC add_BibleVerse @BibleId, 112003003, N'Yet he persisted in the sins of Jeroboam son of Nebat, who encouraged Israel to sin; he did not turn from them.'
EXEC add_BibleVerse @BibleId, 112003004, N'Now King Mesha of Moab was a sheep breeder. He would send as tribute to the king of Israel 100,000 male lambs and the wool of 100,000 rams.'
EXEC add_BibleVerse @BibleId, 112003005, N'When Ahab died, the king of Moab rebelled against the king of Israel.'
EXEC add_BibleVerse @BibleId, 112003006, N'At that time King Jehoram left Samaria and assembled all Israel for war.'
EXEC add_BibleVerse @BibleId, 112003007, N'He sent this message to King Jehoshaphat of Judah: “The king of Moab has rebelled against me. Will you fight with me against Moab?” Jehoshaphat replied, “I will join you in the campaign; my army and horses are at your disposal.”'
EXEC add_BibleVerse @BibleId, 112003008, N'He then asked, “Which invasion route are we going to take?” Jehoram answered, “By the road through the Desert of Edom.”'
EXEC add_BibleVerse @BibleId, 112003009, N'So the kings of Israel, Judah, and Edom set out together. They wandered around on the road for seven days and finally ran out of water for the men and animals they had with them.'
EXEC add_BibleVerse @BibleId, 112003010, N'The king of Israel said, “Oh no! Certainly the Lord has summoned these three kings so that he can hand them over to the king of Moab!”'
EXEC add_BibleVerse @BibleId, 112003011, N'Jehoshaphat asked, “Is there no prophet of the Lord here that we might seek the Lord’s direction?” One of the servants of the king of Israel answered, “Elisha son of Shapat is here; he used to be Elijah’s servant.”'
EXEC add_BibleVerse @BibleId, 112003012, N'Jehoshaphat said, “The Lord speaks through him.” So the king of Israel and Jehoshaphat and the king of Edom went down to visit him.'
EXEC add_BibleVerse @BibleId, 112003013, N'Elisha said to the king of Israel, “Why are you here? Go to your father’s prophets or your mother’s prophets!” The king of Israel replied to him, “No, for the Lord is the one who summoned these three kings so that he can hand them over to Moab.”'
EXEC add_BibleVerse @BibleId, 112003014, N'Elisha said, “As certainly as the Lord who rules over all lives (whom I serve), if I did not respect King Jehoshaphat of Judah, I would not pay attention to you or acknowledge you.'
EXEC add_BibleVerse @BibleId, 112003015, N'But now, get me a musician.” When the musician played, the Lord energized him,'
EXEC add_BibleVerse @BibleId, 112003016, N'and he said, “This is what the Lord says, ‘Make many cisterns in this valley,’'
EXEC add_BibleVerse @BibleId, 112003017, N'for this is what the Lord says, ‘You will not feel any wind or see any rain, but this valley will be full of water and you and your cattle and animals will drink.’'
EXEC add_BibleVerse @BibleId, 112003018, N'This is an easy task for the Lord; he will also hand Moab over to you.'
EXEC add_BibleVerse @BibleId, 112003019, N'You will defeat every fortified city and every important city. You must chop down every productive tree, stop up all the springs, and cover all the cultivated land with stones.”'
EXEC add_BibleVerse @BibleId, 112003020, N'Sure enough, the next morning, at the time of the morning sacrifice, water came flowing down from Edom and filled the land.'
EXEC add_BibleVerse @BibleId, 112003021, N'Now all Moab had heard that the kings were attacking, so everyone old enough to fight was mustered and placed at the border.'
EXEC add_BibleVerse @BibleId, 112003022, N'When they got up early the next morning, the sun was shining on the water. To the Moabites, who were some distance away, the water looked red like blood.'
EXEC add_BibleVerse @BibleId, 112003023, N'The Moabites said, “It’s blood! The kings are totally destroyed! They have struck one another down! Now, Moab, seize the plunder!”'
EXEC add_BibleVerse @BibleId, 112003024, N'When they approached the Israelite camp, the Israelites rose up and struck down the Moabites, who then ran from them. The Israelites thoroughly defeated Moab.'
EXEC add_BibleVerse @BibleId, 112003025, N'They tore down the cities and each man threw a stone into every cultivated field until they were covered. They stopped up every spring and chopped down every productive tree. Only Kir Hareseth was left intact, but the slingers surrounded it and attacked it.'
EXEC add_BibleVerse @BibleId, 112003026, N'When the king of Moab realized he was losing the battle, he and 700 swordsmen tried to break through and attack the king of Edom, but they failed.'
EXEC add_BibleVerse @BibleId, 112003027, N'So he took his firstborn son, who was to succeed him as king, and offered him up as a burnt sacrifice on the wall. There was an outburst of divine anger against Israel, so they broke off the attack and returned to their homeland.'
EXEC add_BibleVerse @BibleId, 112004001, N'Now a wife of one of the prophets appealed to Elisha for help, saying, “Your servant, my husband is dead. You know that your servant was a loyal follower of the Lord. Now the creditor is coming to take away my two boys to be his servants.”'
EXEC add_BibleVerse @BibleId, 112004002, N'Elisha said to her, “What can I do for you? Tell me, what do you have in the house?” She answered, “Your servant has nothing in the house except a small jar of olive oil.”'
EXEC add_BibleVerse @BibleId, 112004003, N'He said, “Go and ask all your neighbors for empty containers. Get as many as you can.'
EXEC add_BibleVerse @BibleId, 112004004, N'Go and close the door behind you and your sons. Pour the olive oil into all the containers; set aside each one when you have filled it.”'
EXEC add_BibleVerse @BibleId, 112004005, N'So she left him and closed the door behind her and her sons. As they were bringing the containers to her, she was pouring the olive oil.'
EXEC add_BibleVerse @BibleId, 112004006, N'When the containers were full, she said to one of her sons, “Bring me another container.” But he answered her, “There are no more.” Then the olive oil stopped flowing.'
EXEC add_BibleVerse @BibleId, 112004007, N'She went and told the prophet. He said, “Go, sell the olive oil. Repay your creditor, and then you and your sons can live off the rest of the profit.”'
EXEC add_BibleVerse @BibleId, 112004008, N'One day Elisha traveled to Shunem, where a prominent woman lived. She insisted that he stop for a meal. So whenever he was passing through, he would stop in there for a meal.'
EXEC add_BibleVerse @BibleId, 112004009, N'She said to her husband, “Look, I’m sure that the man who regularly passes through here is a very special prophet.'
EXEC add_BibleVerse @BibleId, 112004010, N'Let’s make a small private upper room and furnish it with a bed, table, chair, and lamp. When he visits us, he can stay there.”'
EXEC add_BibleVerse @BibleId, 112004011, N'One day Elisha came for a visit; he went into the upper room and rested.'
EXEC add_BibleVerse @BibleId, 112004012, N'He told his servant Gehazi, “Ask the Shunammite woman to come here.” So he did so and she came to him.'
EXEC add_BibleVerse @BibleId, 112004013, N'Elisha said to Gehazi, “Tell her, ‘Look, you have treated us with such great respect. What can I do for you? Can I put in a good word for you with the king or the commander of the army?’” She replied, “I’m quite secure.”'
EXEC add_BibleVerse @BibleId, 112004014, N'So he asked Gehazi, “What can I do for her?” Gehazi replied, “She has no son, and her husband is old.”'
EXEC add_BibleVerse @BibleId, 112004015, N'Elisha told him, “Ask her to come here.” So he did so and she came and stood in the doorway.'
EXEC add_BibleVerse @BibleId, 112004016, N'He said, “About this time next year you will be holding a son.” She said, “No, my master! O prophet, do not lie to your servant!”'
EXEC add_BibleVerse @BibleId, 112004017, N'The woman did conceive, and at the specified time the next year she gave birth to a son, just as Elisha had told her.'
EXEC add_BibleVerse @BibleId, 112004018, N'The boy grew and one day he went out to see his father who was with the harvest workers.'
EXEC add_BibleVerse @BibleId, 112004019, N'He said to his father, “My head! My head!” His father told a servant, “Carry him to his mother.”'
EXEC add_BibleVerse @BibleId, 112004020, N'So he picked him up and took him to his mother. He sat on her lap until noon and then died.'
EXEC add_BibleVerse @BibleId, 112004021, N'She went up and laid him down on the prophet’s bed. She shut the door behind her and left.'
EXEC add_BibleVerse @BibleId, 112004022, N'She called to her husband, “Send me one of the servants and one of the donkeys, so I can go see the prophet quickly and then return.”'
EXEC add_BibleVerse @BibleId, 112004023, N'He said, “Why do you want to go see him today? It is not the new moon or the Sabbath.” She said, “Everything’s fine.”'
EXEC add_BibleVerse @BibleId, 112004024, N'She saddled the donkey and told her servant, “Lead on. Do not stop unless I say so.”'
EXEC add_BibleVerse @BibleId, 112004025, N'So she went to visit the prophet at Mount Carmel. When he saw her at a distance, he said to his servant Gehazi, “Look, it’s the Shunammite woman.'
EXEC add_BibleVerse @BibleId, 112004026, N'Now, run to meet her and ask her, ‘Are you well? Are your husband and the boy well?’” She told Gehazi, “Everything’s fine.”'
EXEC add_BibleVerse @BibleId, 112004027, N'But when she reached the prophet on the mountain, she grabbed hold of his feet. Gehazi came near to push her away, but the prophet said, “Leave her alone, for she is very upset. The Lord has kept the matter hidden from me; he didn’t tell me about it.”'
EXEC add_BibleVerse @BibleId, 112004028, N'She said, “Did I ask my master for a son? Didn’t I say, ‘Don’t mislead me?’”'
EXEC add_BibleVerse @BibleId, 112004029, N'Elisha told Gehazi, “Tuck your robes into your belt, take my staff, and go! Don’t stop to exchange greetings with anyone! Place my staff on the child’s face.”'
EXEC add_BibleVerse @BibleId, 112004030, N'The mother of the child said, “As certainly as the Lord lives and as you live, I will not leave you.” So Elisha got up and followed her back.'
EXEC add_BibleVerse @BibleId, 112004031, N'Now Gehazi went on ahead of them. He placed the staff on the child’s face, but there was no sound or response. When he came back to Elisha he told him, “The child did not wake up.”'
EXEC add_BibleVerse @BibleId, 112004032, N'When Elisha arrived at the house, there was the child lying dead on his bed.'
EXEC add_BibleVerse @BibleId, 112004033, N'He went in by himself and closed the door. Then he prayed to the Lord.'
EXEC add_BibleVerse @BibleId, 112004034, N'He got up on the bed and spread his body out over the boy; he put his mouth on the boy’s mouth, his eyes over the boy’s eyes, and the palms of his hands against the boy’s palms. He bent down over him, and the boy’s skin grew warm.'
EXEC add_BibleVerse @BibleId, 112004035, N'Elisha went back and walked around in the house. Then he got up on the bed again and bent down over him. The child sneezed seven times and opened his eyes.'
EXEC add_BibleVerse @BibleId, 112004036, N'Elisha called to Gehazi and said, “Get the Shunammite woman.” So he did so and she came to him. He said to her, “Take your son.”'
EXEC add_BibleVerse @BibleId, 112004037, N'She came in, fell at his feet, and bowed down. Then she picked up her son and left.'
EXEC add_BibleVerse @BibleId, 112004038, N'Now Elisha went back to Gilgal, while there was famine in the land. Some of the prophets were visiting him and he told his servant, “Put the big pot on the fire and boil some stew for the prophets.”'
EXEC add_BibleVerse @BibleId, 112004039, N'Someone went out to the field to gather some herbs and found a wild vine. He picked some of its fruit, enough to fill up the fold of his robe. He came back, cut it up, and threw the slices into the stew pot, not knowing they were harmful.'
EXEC add_BibleVerse @BibleId, 112004040, N'The stew was poured out for the men to eat. When they ate some of the stew, they cried out, “Death is in the pot, O prophet!” They could not eat it.'
EXEC add_BibleVerse @BibleId, 112004041, N'He said, “Get some flour.” Then he threw it into the pot and said, “Now pour some out for the men so they may eat.” There was no longer anything harmful in the pot.'
EXEC add_BibleVerse @BibleId, 112004042, N'Now a man from Baal Shalisha brought some food for the prophet – twenty loaves of bread made from the firstfruits of the barley harvest, as well as fresh ears of grain. Elisha said, “Set it before the people so they may eat.”'
EXEC add_BibleVerse @BibleId, 112004043, N'But his attendant said, “How can I feed a hundred men with this?” He replied, “Set it before the people so they may eat, for this is what the Lord says, ‘They will eat and have some left over.’”'
EXEC add_BibleVerse @BibleId, 112004044, N'So he set it before them; they ate and had some left over, just as the Lord predicted.'
EXEC add_BibleVerse @BibleId, 112005001, N'Now Naaman, the commander of the king of Syria’s army, was esteemed and respected by his master, for through him the Lord had given Syria military victories. But this great warrior had a skin disease.'
EXEC add_BibleVerse @BibleId, 112005002, N'Raiding parties went out from Syria and took captive from the land of Israel a young girl, who became a servant to Naaman’s wife.'
EXEC add_BibleVerse @BibleId, 112005003, N'She told her mistress, “If only my master were in the presence of the prophet who is in Samaria! Then he would cure him of his skin disease.”'
EXEC add_BibleVerse @BibleId, 112005004, N'Naaman went and told his master what the girl from the land of Israel had said.'
EXEC add_BibleVerse @BibleId, 112005005, N'The king of Syria said, “Go! I will send a letter to the king of Israel.” So Naaman went, taking with him ten talents of silver, six thousand shekels of gold, and ten suits of clothes.'
EXEC add_BibleVerse @BibleId, 112005006, N'He brought the letter to king of Israel. It read: “This is a letter of introduction for my servant Naaman, whom I have sent to be cured of his skin disease.”'
EXEC add_BibleVerse @BibleId, 112005007, N'When the king of Israel read the letter, he tore his clothes and said, “Am I God? Can I kill or restore life? Why does he ask me to cure a man of his skin disease? Certainly you must see that he is looking for an excuse to fight me!”'
EXEC add_BibleVerse @BibleId, 112005008, N'When Elisha the prophet heard that the king had torn his clothes, he sent this message to the king, “Why did you tear your clothes? Send him to me so he may know there is a prophet in Israel.”'
EXEC add_BibleVerse @BibleId, 112005009, N'So Naaman came with his horses and chariots and stood in the doorway of Elisha’s house.'
EXEC add_BibleVerse @BibleId, 112005010, N'Elisha sent out a messenger who told him, “Go and wash seven times in the Jordan; your skin will be restored and you will be healed.”'
EXEC add_BibleVerse @BibleId, 112005011, N'Naaman went away angry. He said, “Look, I thought for sure he would come out, stand there, invoke the name of the Lord his God, wave his hand over the area, and cure the skin disease.'
EXEC add_BibleVerse @BibleId, 112005012, N'The rivers of Damascus, the Abana and Pharpar, are better than any of the waters of Israel! Could I not wash in them and be healed?” So he turned around and went away angry.'
EXEC add_BibleVerse @BibleId, 112005013, N'His servants approached and said to him, “O master, if the prophet had told you to do some difficult task, you would have been willing to do it. It seems you should be happy that he simply said, “Wash and you will be healed.”'
EXEC add_BibleVerse @BibleId, 112005014, N'So he went down and dipped in the Jordan seven times, as the prophet had instructed. His skin became as smooth as a young child’s and he was healed.'
EXEC add_BibleVerse @BibleId, 112005015, N'He and his entire entourage returned to the prophet. Naaman came and stood before him. He said, “For sure I know that there is no God in all the earth except in Israel! Now, please accept a gift from your servant.”'
EXEC add_BibleVerse @BibleId, 112005016, N'But Elisha replied, “As certainly as the Lord lives (whom I serve), I will take nothing from you.” Naaman insisted that he take it, but he refused.'
EXEC add_BibleVerse @BibleId, 112005017, N'Naaman said, “If not, then please give your servant a load of dirt, enough for a pair of mules to carry, for your servant will never again offer a burnt offering or sacrifice to a god other than the Lord.'
EXEC add_BibleVerse @BibleId, 112005018, N'May the Lord forgive your servant for this one thing: When my master enters the temple of Rimmon to worship, and he leans on my arm and I bow down in the temple of Rimmon, may the Lord forgive your servant for this.”'
EXEC add_BibleVerse @BibleId, 112005019, N'Elisha said to him, “Go in peace.” When he had gone a short distance,'
EXEC add_BibleVerse @BibleId, 112005020, N'Gehazi, the prophet Elisha’s servant, thought, “Look, my master did not accept what this Syrian Naaman offered him. As certainly as the Lord lives, I will run after him and accept something from him.”'
EXEC add_BibleVerse @BibleId, 112005021, N'So Gehazi ran after Naaman. When Naaman saw someone running after him, he got down from his chariot to meet him and asked, “Is everything all right?”'
EXEC add_BibleVerse @BibleId, 112005022, N'He answered, “Everything is fine. My master sent me with this message, ‘Look, two servants of the prophets just arrived from the Ephraimite hill country. Please give them a talent of silver and two suits of clothes.’”'
EXEC add_BibleVerse @BibleId, 112005023, N'Naaman said, “Please accept two talents of silver. He insisted, and tied up two talents of silver in two bags, along with two suits of clothes. He gave them to two of his servants and they carried them for Gehazi.'
EXEC add_BibleVerse @BibleId, 112005024, N'When he arrived at the hill, he took them from the servants and put them in the house. Then he sent the men on their way.'
EXEC add_BibleVerse @BibleId, 112005025, N'When he came and stood before his master, Elisha asked him, “Where have you been, Gehazi?” He answered, “Your servant hasn’t been anywhere.”'
EXEC add_BibleVerse @BibleId, 112005026, N'Elisha replied, “I was there in spirit when a man turned and got down from his chariot to meet you. This is not the proper time to accept silver or to accept clothes, olive groves, vineyards, sheep, cattle, and male and female servants.'
EXEC add_BibleVerse @BibleId, 112005027, N'Therefore Naaman’s skin disease will afflict you and your descendants forever!” When Gehazi went out from his presence, his skin was as white as snow.'
EXEC add_BibleVerse @BibleId, 112006001, N'Some of the prophets said to Elisha, “Look, the place where we meet with you is too cramped for us.'
EXEC add_BibleVerse @BibleId, 112006002, N'Let’s go to the Jordan. Each of us will get a log from there and we will build a meeting place for ourselves there.” He said, “Go.”'
EXEC add_BibleVerse @BibleId, 112006003, N'One of them said, “Please come along with your servants.” He replied, “All right, I’ll come.”'
EXEC add_BibleVerse @BibleId, 112006004, N'So he went with them. When they arrived at the Jordan, they started cutting down trees.'
EXEC add_BibleVerse @BibleId, 112006005, N'As one of them was felling a log, the ax head dropped into the water. He shouted, “Oh no, my master! It was borrowed!”'
EXEC add_BibleVerse @BibleId, 112006006, N'The prophet asked, “Where did it drop in?” When he showed him the spot, Elisha cut off a branch, threw it in at that spot, and made the ax head float.'
EXEC add_BibleVerse @BibleId, 112006007, N'He said, “Lift it out.” So he reached out his hand and grabbed it.'
EXEC add_BibleVerse @BibleId, 112006008, N'Now the king of Syria was at war with Israel. He consulted his advisers, who said, “Invade at such and such a place.”'
EXEC add_BibleVerse @BibleId, 112006009, N'But the prophet sent this message to the king of Israel, “Make sure you don’t pass through this place because Syria is invading there.”'
EXEC add_BibleVerse @BibleId, 112006010, N'So the king of Israel sent a message to the place the prophet had pointed out, warning it to be on its guard. This happened on several occasions.'
EXEC add_BibleVerse @BibleId, 112006011, N'This made the king of Syria upset. So he summoned his advisers and said to them, “One of us must be helping the king of Israel.”'
EXEC add_BibleVerse @BibleId, 112006012, N'One of his advisers said, “No, my master, O king. The prophet Elisha who lives in Israel keeps telling the king of Israel the things you say in your bedroom.”'
EXEC add_BibleVerse @BibleId, 112006013, N'The king ordered, “Go, find out where he is, so I can send some men to capture him.” The king was told, “He is in Dothan.”'
EXEC add_BibleVerse @BibleId, 112006014, N'So he sent horses and chariots there, along with a good-sized army. They arrived during the night and surrounded the city.'
EXEC add_BibleVerse @BibleId, 112006015, N'The prophet’s attendant got up early in the morning. When he went outside there was an army surrounding the city, along with horses and chariots. He said to Elisha, “Oh no, my master! What will we do?”'
EXEC add_BibleVerse @BibleId, 112006016, N'He replied, “Don’t be afraid, for our side outnumbers them.”'
EXEC add_BibleVerse @BibleId, 112006017, N'Then Elisha prayed, “O Lord, open his eyes so he can see.” The Lord opened the servant’s eyes and he saw that the hill was full of horses and chariots of fire all around Elisha.'
EXEC add_BibleVerse @BibleId, 112006018, N'As they approached him, Elisha prayed to the Lord, “Strike these people with blindness.” The Lord struck them with blindness as Elisha requested.'
EXEC add_BibleVerse @BibleId, 112006019, N'Then Elisha said to them, “This is not the right road or city. Follow me, and I will lead you to the man you’re looking for.” He led them to Samaria.'
EXEC add_BibleVerse @BibleId, 112006020, N'When they had entered Samaria, Elisha said, “O Lord, open their eyes, so they can see.” The Lord opened their eyes and they saw that they were in the middle of Samaria.'
EXEC add_BibleVerse @BibleId, 112006021, N'When the king of Israel saw them, he asked Elisha, “Should I strike them down, my master?”'
EXEC add_BibleVerse @BibleId, 112006022, N'He replied, “Do not strike them down! You did not capture them with your sword or bow, so what gives you the right to strike them down? Give them some food and water, so they can eat and drink and then go back to their master.”'
EXEC add_BibleVerse @BibleId, 112006023, N'So he threw a big banquet for them and they ate and drank. Then he sent them back to their master. After that no Syrian raiding parties again invaded the land of Israel.'
EXEC add_BibleVerse @BibleId, 112006024, N'Later King Ben Hadad of Syria assembled his entire army and attacked and besieged Samaria.'
EXEC add_BibleVerse @BibleId, 112006025, N'Samaria’s food supply ran out. They laid siege to it so long that a donkey’s head was selling for eighty shekels of silver and a quarter of a kab of dove’s droppings for five shekels of silver.'
EXEC add_BibleVerse @BibleId, 112006026, N'While the king of Israel was passing by on the city wall, a woman shouted to him, “Help us, my master, O king!”'
EXEC add_BibleVerse @BibleId, 112006027, N'He replied, “No, let the Lord help you. How can I help you? The threshing floor and winepress are empty.”'
EXEC add_BibleVerse @BibleId, 112006028, N'Then the king asked her, “What’s your problem?” She answered, “This woman said to me, ‘Hand over your son; we’ll eat him today and then eat my son tomorrow.’'
EXEC add_BibleVerse @BibleId, 112006029, N'So we boiled my son and ate him. Then I said to her the next day, ‘Hand over your son and we’ll eat him.’ But she hid her son!”'
EXEC add_BibleVerse @BibleId, 112006030, N'When the king heard what the woman said, he tore his clothes. As he was passing by on the wall, the people could see he was wearing sackcloth under his clothes.'
EXEC add_BibleVerse @BibleId, 112006031, N'Then he said, “May God judge me severely if Elisha son of Shaphat still has his head by the end of the day!”'
EXEC add_BibleVerse @BibleId, 112006032, N'Now Elisha was sitting in his house with the community leaders. The king sent a messenger on ahead, but before he arrived, Elisha said to the leaders, “Do you realize this assassin intends to cut off my head?” Look, when the messenger arrives, shut the door and lean against it. His master will certainly be right behind him.”'
EXEC add_BibleVerse @BibleId, 112006033, N'He was still talking to them when the messenger approached and said, “Look, the Lord is responsible for this disaster! Why should I continue to wait for the Lord to help?”'
EXEC add_BibleVerse @BibleId, 112007001, N'Elisha replied, “Hear the word of the Lord! This is what the Lord says, ‘About this time tomorrow a seah of finely milled flour will sell for a shekel and two seahs of barley for a shekel at the gate of Samaria.’”'
EXEC add_BibleVerse @BibleId, 112007002, N'An officer who was the king’s right-hand man responded to the prophet, “Look, even if the Lord made it rain by opening holes in the sky, could this happen so soon?” Elisha said, “Look, you will see it happen with your own eyes, but you will not eat any of the food!”'
EXEC add_BibleVerse @BibleId, 112007003, N'Now four men with a skin disease were sitting at the entrance of the city gate. They said to one another, “Why are we just sitting here waiting to die?'
EXEC add_BibleVerse @BibleId, 112007004, N'If we go into the city, we’ll die of starvation, and if we stay here we’ll die! So come on, let’s defect to the Syrian camp! If they spare us, we’ll live; if they kill us – well, we were going to die anyway.”'
EXEC add_BibleVerse @BibleId, 112007005, N'So they started toward the Syrian camp at dusk. When they reached the edge of the Syrian camp, there was no one there.'
EXEC add_BibleVerse @BibleId, 112007006, N'The Lord had caused the Syrian camp to hear the sound of chariots and horses and a large army. Then they said to one another, “Look, the king of Israel has paid the kings of the Hittites and Egypt to attack us!”'
EXEC add_BibleVerse @BibleId, 112007007, N'So they got up and fled at dusk, leaving behind their tents, horses, and donkeys. They left the camp as it was and ran for their lives.'
EXEC add_BibleVerse @BibleId, 112007008, N'When the men with a skin disease reached the edge of the camp, they entered a tent and had a meal. They also took some silver, gold, and clothes and went and hid it all. Then they went back and entered another tent. They looted it and went and hid what they had taken.'
EXEC add_BibleVerse @BibleId, 112007009, N'Then they said to one another, “It’s not right what we’re doing! This is a day to celebrate, but we haven’t told anyone. If we wait until dawn, we’ll be punished. So come on, let’s go and inform the royal palace.”'
EXEC add_BibleVerse @BibleId, 112007010, N'So they went and called out to the gatekeepers of the city. They told them, “We entered the Syrian camp and there was no one there. We didn’t even hear a man’s voice. But the horses and donkeys are still tied up, and the tents remain up.”'
EXEC add_BibleVerse @BibleId, 112007011, N'The gatekeepers relayed the news to the royal palace.'
EXEC add_BibleVerse @BibleId, 112007012, N'The king got up in the night and said to his advisers, “I will tell you what the Syrians have done to us. They know we are starving, so they left the camp and hid in the field, thinking, ‘When they come out of the city, we will capture them alive and enter the city.’”'
EXEC add_BibleVerse @BibleId, 112007013, N'One of his advisers replied, “Pick some men and have them take five of the horses that are left in the city. (Even if they are killed, their fate will be no different than that of all the Israelite people – we’re all going to die!) Let’s send them out so we can know for sure what’s going on.”'
EXEC add_BibleVerse @BibleId, 112007014, N'So they picked two horsemen and the king sent them out to track the Syrian army. He ordered them, “Go and find out what’s going on.”'
EXEC add_BibleVerse @BibleId, 112007015, N'So they tracked them as far as the Jordan. The road was filled with clothes and equipment that the Syrians had discarded in their haste. The scouts went back and told the king.'
EXEC add_BibleVerse @BibleId, 112007016, N'Then the people went out and looted the Syrian camp. A seah of finely milled flour sold for a shekel, and two seahs of barley for a shekel, just as the Lord had said they would.'
EXEC add_BibleVerse @BibleId, 112007017, N'Now the king had placed the officer who was his right-hand man at the city gate. When the people rushed out, they trampled him to death in the gate. This fulfilled the prophet’s word which he had spoken when the king tried to arrest him.'
EXEC add_BibleVerse @BibleId, 112007018, N'The prophet told the king, “Two seahs of barley will sell for a shekel, and a seah of finely milled flour for a shekel; this will happen about this time tomorrow in the gate of Samaria.”'
EXEC add_BibleVerse @BibleId, 112007019, N'But the officer replied to the prophet, “Look, even if the Lord made it rain by opening holes in the sky, could this happen so soon?” Elisha said, “Look, you will see it happen with your own eyes, but you will not eat any of the food!”'
EXEC add_BibleVerse @BibleId, 112007020, N'This is exactly what happened to him. The people trampled him to death in the city gate.'
EXEC add_BibleVerse @BibleId, 112008001, N'Now Elisha advised the woman whose son he had brought back to life, “You and your family should go and live somewhere else for a while, for the Lord has decreed that a famine will overtake the land for seven years.”'
EXEC add_BibleVerse @BibleId, 112008002, N'So the woman did as the prophet said. She and her family went and lived in the land of the Philistines for seven years.'
EXEC add_BibleVerse @BibleId, 112008003, N'After seven years the woman returned from the land of the Philistines and went to ask the king to give her back her house and field.'
EXEC add_BibleVerse @BibleId, 112008004, N'Now the king was talking to Gehazi, the prophet’s servant, and said, “Tell me all the great things which Elisha has done.”'
EXEC add_BibleVerse @BibleId, 112008005, N'While Gehazi was telling the king how Elisha had brought the dead back to life, the woman whose son he had brought back to life came to ask the king for her house and field. Gehazi said, “My master, O king, this is the very woman and this is her son whom Elisha brought back to life!”'
EXEC add_BibleVerse @BibleId, 112008006, N'The king asked the woman about it, and she gave him the details. The king assigned a eunuch to take care of her request and ordered him, “Give her back everything she owns, as well as the amount of crops her field produced from the day she left the land until now.”'
EXEC add_BibleVerse @BibleId, 112008007, N'Elisha traveled to Damascus while King Ben Hadad of Syria was sick. The king was told, “The prophet has come here.”'
EXEC add_BibleVerse @BibleId, 112008008, N'So the king told Hazael, “Take a gift and go visit the prophet. Request from him an oracle from the Lord. Ask him, ‘Will I recover from this sickness?’”'
EXEC add_BibleVerse @BibleId, 112008009, N'So Hazael went to visit Elisha. He took along a gift, as well as forty camel loads of all the fine things of Damascus. When he arrived, he stood before him and said, “Your son, King Ben Hadad of Syria, has sent me to you with this question, ‘Will I recover from this sickness?’”'
EXEC add_BibleVerse @BibleId, 112008010, N'Elisha said to him, “Go and tell him, ‘You will surely recover,’ but the Lord has revealed to me that he will surely die.”'
EXEC add_BibleVerse @BibleId, 112008011, N'Elisha just stared at him until Hazael became uncomfortable. Then the prophet started crying.'
EXEC add_BibleVerse @BibleId, 112008012, N'Hazael asked, “Why are you crying, my master?” He replied, “Because I know the trouble you will cause the Israelites. You will set fire to their fortresses, kill their young men with the sword, smash their children to bits, and rip open their pregnant women.”'
EXEC add_BibleVerse @BibleId, 112008013, N'Hazael said, “How could your servant, who is as insignificant as a dog, accomplish this great military victory?” Elisha answered, “The Lord has revealed to me that you will be the king of Syria.”'
EXEC add_BibleVerse @BibleId, 112008014, N'He left Elisha and went to his master. Ben Hadad asked him, “What did Elisha tell you?” Hazael replied, “He told me you would surely recover.”'
EXEC add_BibleVerse @BibleId, 112008015, N'The next day Hazael took a piece of cloth, dipped it in water, and spread it over Ben Hadad’s face until he died. Then Hazael replaced him as king.'
EXEC add_BibleVerse @BibleId, 112008016, N'In the fifth year of the reign of Israel’s King Joram, son of Ahab, Jehoshaphat’s son Jehoram became king over Judah.'
EXEC add_BibleVerse @BibleId, 112008017, N'He was thirty-two years old when he became king and he reigned for eight years in Jerusalem.'
EXEC add_BibleVerse @BibleId, 112008018, N'He followed in the footsteps of the kings of Israel, just as Ahab’s dynasty had done, for he married Ahab’s daughter. He did evil in the sight of the Lord.'
EXEC add_BibleVerse @BibleId, 112008019, N'But the Lord was unwilling to destroy Judah. He preserved Judah for the sake of his servant David to whom he had promised a perpetual dynasty.'
EXEC add_BibleVerse @BibleId, 112008020, N'During his reign Edom freed themselves from Judah’s control and set up their own king.'
EXEC add_BibleVerse @BibleId, 112008021, N'Joram crossed over to Zair with all his chariots. The Edomites, who had surrounded him, attacked at night and defeated him and his chariot officers. The Israelite army retreated to their homeland.'
EXEC add_BibleVerse @BibleId, 112008022, N'So Edom has remained free from Judah’s control to this very day. At that same time Libnah also rebelled.'
EXEC add_BibleVerse @BibleId, 112008023, N'The rest of the events of Joram’s reign, including a record of his accomplishments, are recorded in the scroll called the Annals of the Kings of Judah.'
EXEC add_BibleVerse @BibleId, 112008024, N'Joram passed away and was buried with his ancestors in the city of David. His son Ahaziah replaced him as king.'
EXEC add_BibleVerse @BibleId, 112008025, N'In the twelfth year of the reign of Israel’s King Joram, son of Ahab, Jehoram’s son Ahaziah became king over Judah.'
EXEC add_BibleVerse @BibleId, 112008026, N'Ahaziah was twenty-two years old when he became king and he reigned for one year in Jerusalem. His mother was Athaliah, the granddaughter of King Omri of Israel.'
EXEC add_BibleVerse @BibleId, 112008027, N'He followed in the footsteps of Ahab’s dynasty and did evil in the sight of the Lord, like Ahab’s dynasty, for he was related to Ahab’s family.'
EXEC add_BibleVerse @BibleId, 112008028, N'He joined Ahab’s son Joram in a battle against King Hazael of Syria at Ramoth Gilead in which the Syrians defeated Joram.'
EXEC add_BibleVerse @BibleId, 112008029, N'King Joram returned to Jezreel to recover from the wounds he received from the Syrians in Ramah when he fought against King Hazael of Syria. King Ahaziah son of Jehoram of Judah went down to visit Joram son of Ahab in Jezreel, for he was ill.'
EXEC add_BibleVerse @BibleId, 112009001, N'Now Elisha the prophet summoned a member of the prophetic guild and told him, “Tuck your robes into your belt, take this container of olive oil in your hand, and go to Ramoth Gilead.'
EXEC add_BibleVerse @BibleId, 112009002, N'When you arrive there, look for Jehu son of Jehoshaphat son of Nimshi and take him aside into an inner room.'
EXEC add_BibleVerse @BibleId, 112009003, N'Take the container of olive oil, pour it over his head, and say, ‘This is what the Lord says, “I have designated you as king over Israel.”’ Then open the door and run away quickly!”'
EXEC add_BibleVerse @BibleId, 112009004, N'So the young prophet went to Ramoth Gilead.'
EXEC add_BibleVerse @BibleId, 112009005, N'When he arrived, the officers of the army were sitting there. So he said, “I have a message for you, O officer.” Jehu asked, “For which one of us?” He replied, “For you, O officer.”'
EXEC add_BibleVerse @BibleId, 112009006, N'So Jehu got up and went inside. Then the prophet poured the olive oil on his head and said to him, “This is what the Lord God of Israel says, ‘I have designated you as king over the Lord’s people Israel.'
EXEC add_BibleVerse @BibleId, 112009007, N'You will destroy the family of your master Ahab. I will get revenge against Jezebel for the shed blood of my servants the prophets and for the shed blood of all the Lord’s servants.'
EXEC add_BibleVerse @BibleId, 112009008, N'Ahab’s entire family will die. I will cut off every last male belonging to Ahab in Israel, including even the weak and incapacitated.'
EXEC add_BibleVerse @BibleId, 112009009, N'I will make Ahab’s dynasty like those of Jeroboam son of Nebat and Baasha son of Ahijah.'
EXEC add_BibleVerse @BibleId, 112009010, N'Dogs will devour Jezebel on the plot of ground in Jezreel; she will not be buried.’” Then he opened the door and ran away.'
EXEC add_BibleVerse @BibleId, 112009011, N'When Jehu rejoined his master’s servants, they asked him, “Is everything all right? Why did this madman visit you?” He replied, “Ah, it’s not important. You know what kind of man he is and the kinds of things he says.”'
EXEC add_BibleVerse @BibleId, 112009012, N'But they said, “You’re lying! Tell us what he said.” So he told them what he had said. He also related how he had said, “This is what the Lord says, ‘I have designated you as king over Israel.’”'
EXEC add_BibleVerse @BibleId, 112009013, N'Each of them quickly took off his cloak and they spread them out at Jehu’s feet on the steps. The trumpet was blown and they shouted, “Jehu is king!”'
EXEC add_BibleVerse @BibleId, 112009014, N'Then Jehu son of Jehoshaphat son of Nimshi conspired against Joram. Now Joram had been in Ramoth Gilead with the whole Israelite army, guarding against an invasion by King Hazael of Syria.'
EXEC add_BibleVerse @BibleId, 112009015, N'But King Joram had returned to Jezreel to recover from the wounds he received from the Syrians when he fought against King Hazael of Syria. Jehu told his supporters, “If you really want me to be king, then don’t let anyone escape from the city to go and warn Jezreel.”'
EXEC add_BibleVerse @BibleId, 112009016, N'Jehu drove his chariot to Jezreel, for Joram was recuperating there. (Now King Ahaziah of Judah had come down to visit Joram.)'
EXEC add_BibleVerse @BibleId, 112009017, N'Now the watchman was standing on the tower in Jezreel and saw Jehu’s troops approaching. He said, “I see troops!” Jehoram ordered, “Send a rider out to meet them and have him ask, ‘Is everything all right?’”'
EXEC add_BibleVerse @BibleId, 112009018, N'So the horseman went to meet him and said, “This is what the king says, ‘Is everything all right?’” Jehu replied, “None of your business! Follow me.” The watchman reported, “The messenger reached them, but hasn’t started back.”'
EXEC add_BibleVerse @BibleId, 112009019, N'So he sent a second horseman out to them and he said, “This is what the king says, ‘Is everything all right?’” Jehu replied, “None of your business! Follow me.”'
EXEC add_BibleVerse @BibleId, 112009020, N'The watchman reported, “He reached them, but hasn’t started back. The one who drives the lead chariot drives like Jehu son of Nimshi; he drives recklessly.”'
EXEC add_BibleVerse @BibleId, 112009021, N'Jehoram ordered, “Hitch up my chariot.” When his chariot had been hitched up, King Jehoram of Israel and King Ahaziah of Judah went out in their respective chariots to meet Jehu. They met up with him in the plot of land that had once belonged to Naboth of Jezreel.'
EXEC add_BibleVerse @BibleId, 112009022, N'When Jehoram saw Jehu, he asked, “Is everything all right, Jehu?” He replied, “How can everything be all right as long as your mother Jezebel promotes idolatry and pagan practices?”'
EXEC add_BibleVerse @BibleId, 112009023, N'Jehoram turned his chariot around and took off. He said to Ahaziah, “It’s a trap, Ahaziah!”'
EXEC add_BibleVerse @BibleId, 112009024, N'Jehu aimed his bow and shot an arrow right between Jehoram’s shoulders. The arrow went through his heart and he fell to his knees in his chariot.'
EXEC add_BibleVerse @BibleId, 112009025, N'Jehu ordered his officer Bidkar, “Pick him up and throw him into the part of the field that once belonged to Naboth of Jezreel. Remember, you and I were riding together behind his father Ahab, when the Lord pronounced this judgment on him,'
EXEC add_BibleVerse @BibleId, 112009026, N'‘“Know for sure that I saw the shed blood of Naboth and his sons yesterday,” says the Lord, “and that I will give you what you deserve right here in this plot of land,” says the Lord.’ So now pick him up and throw him into this plot of land, just as the Lord said.”'
EXEC add_BibleVerse @BibleId, 112009027, N'When King Ahaziah of Judah saw what happened, he took off up the road to Beth Haggan. Jehu chased him and ordered, “Shoot him too.” They shot him while he was driving his chariot up the ascent of Gur near Ibleam. He fled to Megiddo and died there.'
EXEC add_BibleVerse @BibleId, 112009028, N'His servants took his body back to Jerusalem and buried him in his tomb with his ancestors in the city of David.'
EXEC add_BibleVerse @BibleId, 112009029, N'Ahaziah had become king over Judah in the eleventh year of Joram son of Ahab.'
EXEC add_BibleVerse @BibleId, 112009030, N'Jehu approached Jezreel. When Jezebel heard the news, she put on some eye liner, fixed up her hair, and leaned out the window.'
EXEC add_BibleVerse @BibleId, 112009031, N'When Jehu came through the gate, she said, “Is everything all right, Zimri, murderer of his master?”'
EXEC add_BibleVerse @BibleId, 112009032, N'He looked up at the window and said, “Who is on my side? Who?” Two or three eunuchs looked down at him.'
EXEC add_BibleVerse @BibleId, 112009033, N'He said, “Throw her down!” So they threw her down, and when she hit the ground, her blood splattered against the wall and the horses, and Jehu drove his chariot over her.'
EXEC add_BibleVerse @BibleId, 112009034, N'He went inside and had a meal. Then he said, “Dispose of this accursed woman’s corpse. Bury her, for after all, she was a king’s daughter.”'
EXEC add_BibleVerse @BibleId, 112009035, N'But when they went to bury her, they found nothing left but the skull, feet, and palms of the hands.'
EXEC add_BibleVerse @BibleId, 112009036, N'When they went back and told him, he said, “The Lord’s word through his servant, Elijah the Tishbite, has come to pass. He warned, ‘In the plot of land at Jezreel, dogs will devour Jezebel’s flesh.'
EXEC add_BibleVerse @BibleId, 112009037, N'Jezebel’s corpse will be like manure on the surface of the ground in the plot of land at Jezreel. People will not be able to even recognize her.’”'
EXEC add_BibleVerse @BibleId, 112010001, N'Ahab had seventy sons living in Samaria. So Jehu wrote letters and sent them to Samaria to the leading officials of Jezreel and to the guardians of Ahab’s dynasty. This is what the letters said,'
EXEC add_BibleVerse @BibleId, 112010002, N'“You have with you the sons of your master, chariots and horses, a fortified city, and weapons. So when this letter arrives,'
EXEC add_BibleVerse @BibleId, 112010003, N'pick the best and most capable of your master’s sons, place him on his father’s throne, and defend your master’s dynasty.”'
EXEC add_BibleVerse @BibleId, 112010004, N'They were absolutely terrified and said, “Look, two kings could not stop him! How can we?”'
EXEC add_BibleVerse @BibleId, 112010005, N'So the palace supervisor, the city commissioner, the leaders, and the guardians sent this message to Jehu, “We are your subjects! Whatever you say, we will do. We will not make anyone king. Do what you consider proper.”'
EXEC add_BibleVerse @BibleId, 112010006, N'He wrote them a second letter, saying, “If you are really on my side and are willing to obey me, then take the heads of your master’s sons and come to me in Jezreel at this time tomorrow.” Now the king had seventy sons, and the prominent men of the city were raising them.'
EXEC add_BibleVerse @BibleId, 112010007, N'When they received the letter, they seized the king’s sons and executed all seventy of them. They put their heads in baskets and sent them to him in Jezreel.'
EXEC add_BibleVerse @BibleId, 112010008, N'The messenger came and told Jehu, “They have brought the heads of the king’s sons.” Jehu said, “Stack them in two piles at the entrance of the city gate until morning.”'
EXEC add_BibleVerse @BibleId, 112010009, N'In the morning he went out and stood there. Then he said to all the people, “You are innocent. I conspired against my master and killed him. But who struck down all of these men?'
EXEC add_BibleVerse @BibleId, 112010010, N'Therefore take note that not one of the judgments the Lord announced against Ahab’s dynasty has failed to materialize. The Lord had done what he announced through his servant Elijah.”'
EXEC add_BibleVerse @BibleId, 112010011, N'Then Jehu killed all who were left of Ahab’s family in Jezreel, and all his nobles, close friends, and priests. He left no survivors.'
EXEC add_BibleVerse @BibleId, 112010012, N'Jehu then left there and set out for Samaria. While he was traveling through Beth Eked of the Shepherds,'
EXEC add_BibleVerse @BibleId, 112010013, N'Jehu encountered the relatives of King Ahaziah of Judah. He asked, “Who are you?” They replied, “We are Ahaziah’s relatives. We have come down to see how the king’s sons and the queen mother’s sons are doing.”'
EXEC add_BibleVerse @BibleId, 112010014, N'He said, “Capture them alive!” So they captured them alive and then executed all forty-two of them in the cistern at Beth Eked. He left no survivors.'
EXEC add_BibleVerse @BibleId, 112010015, N'When he left there, he met Jehonadab, son of Rekab, who had been looking for him. Jehu greeted him and asked, “Are you as committed to me as I am to you?” Jehonadab answered, “I am!” Jehu replied, “If so, give me your hand.” So he offered his hand and Jehu pulled him up into the chariot.'
EXEC add_BibleVerse @BibleId, 112010016, N'Jehu said, “Come with me and see how zealous I am for the Lord’s cause.” So he took him along in his chariot.'
EXEC add_BibleVerse @BibleId, 112010017, N'He went to Samaria and exterminated all the members of Ahab’s family who were still alive in Samaria, just as the Lord had announced to Elijah.'
EXEC add_BibleVerse @BibleId, 112010018, N'Jehu assembled all the people and said to them, “Ahab worshiped Baal a little; Jehu will worship him with great devotion.'
EXEC add_BibleVerse @BibleId, 112010019, N'So now, bring to me all the prophets of Baal, as well as all his servants and priests. None of them must be absent, for I am offering a great sacrifice to Baal. Any of them who fail to appear will lose their lives.” But Jehu was tricking them so he could destroy the servants of Baal.'
EXEC add_BibleVerse @BibleId, 112010020, N'Then Jehu ordered, “Make arrangements for a celebration for Baal.” So they announced it.'
EXEC add_BibleVerse @BibleId, 112010021, N'Jehu sent invitations throughout Israel, and all the servants of Baal came; not one was absent. They arrived at the temple of Baal and filled it up from end to end.'
EXEC add_BibleVerse @BibleId, 112010022, N'Jehu ordered the one who was in charge of the wardrobe, “Bring out robes for all the servants of Baal.” So he brought out robes for them.'
EXEC add_BibleVerse @BibleId, 112010023, N'Then Jehu and Jehonadab son of Rekab went to the temple of Baal. Jehu said to the servants of Baal, “Make sure there are no servants of the Lord here with you; there must be only servants of Baal.”'
EXEC add_BibleVerse @BibleId, 112010024, N'They went inside to offer sacrifices and burnt offerings. Now Jehu had stationed eighty men outside. He had told them, “If any of the men inside get away, you will pay with your lives!”'
EXEC add_BibleVerse @BibleId, 112010025, N'When he finished offering the burnt sacrifice, Jehu ordered the royal guard and officers, “Come in and strike them down! Don’t let any escape!” So the royal guard and officers struck them down with the sword and left their bodies lying there. Then they entered the inner sanctuary of the temple of Baal.'
EXEC add_BibleVerse @BibleId, 112010026, N'They hauled out the sacred pillar of the temple of Baal and burned it.'
EXEC add_BibleVerse @BibleId, 112010027, N'They demolished the sacred pillar of Baal and the temple of Baal; it is used as a latrine to this very day.'
EXEC add_BibleVerse @BibleId, 112010028, N'So Jehu eradicated Baal worship from Israel.'
EXEC add_BibleVerse @BibleId, 112010029, N'However, Jehu did not repudiate the sins which Jeroboam son of Nebat had encouraged Israel to commit; the golden calves remained in Bethel and Dan.'
EXEC add_BibleVerse @BibleId, 112010030, N'The Lord said to Jehu, “You have done well. You have accomplished my will and carried out my wishes with regard to Ahab’s dynasty. Therefore four generations of your descendants will rule over Israel.”'
EXEC add_BibleVerse @BibleId, 112010031, N'But Jehu did not carefully and wholeheartedly obey the law of the Lord God of Israel. He did not repudiate the sins which Jeroboam had encouraged Israel to commit.'
EXEC add_BibleVerse @BibleId, 112010032, N'In those days the Lord began to reduce the size of Israel’s territory. Hazael attacked their eastern border.'
EXEC add_BibleVerse @BibleId, 112010033, N'He conquered all the land of Gilead, including the territory of Gad, Reuben, and Manasseh, extending all the way from the Aroer in the Arnon Valley through Gilead to Bashan.'
EXEC add_BibleVerse @BibleId, 112010034, N'The rest of the events of Jehu’s reign, including all his accomplishments and successes, are recorded in the scroll called the Annals of the Kings of Israel.'
EXEC add_BibleVerse @BibleId, 112010035, N'Jehu passed away and was buried in Samaria. His son Jehoahaz replaced him as king.'
EXEC add_BibleVerse @BibleId, 112010036, N'Jehu reigned over Israel for twenty-eight years in Samaria.'
EXEC add_BibleVerse @BibleId, 112011001, N'When Athaliah the mother of Ahaziah saw that her son was dead, she was determined to destroy the entire royal line.'
EXEC add_BibleVerse @BibleId, 112011002, N'So Jehosheba, the daughter of King Joram and sister of Ahaziah, took Ahaziah’s son Joash and sneaked him away from the rest of the royal descendants who were to be executed. She hid him and his nurse in the room where the bed covers were stored. So he was hidden from Athaliah and escaped execution.'
EXEC add_BibleVerse @BibleId, 112011003, N'He hid out with his nurse in the Lord’s temple for six years, while Athaliah was ruling over the land.'
EXEC add_BibleVerse @BibleId, 112011004, N'In the seventh year Jehoiada summoned the officers of the units of hundreds of the Carians and the royal bodyguard. He met with them in the Lord’s temple. He made an agreement with them and made them swear an oath of allegiance in the Lord’s temple. Then he showed them the king’s son.'
EXEC add_BibleVerse @BibleId, 112011005, N'He ordered them, “This is what you must do. One third of the unit that is on duty during the Sabbath will guard the royal palace.'
EXEC add_BibleVerse @BibleId, 112011006, N'Another third of you will be stationed at the Foundation Gate. Still another third of you will be stationed at the gate behind the royal guard. You will take turns guarding the palace.'
EXEC add_BibleVerse @BibleId, 112011007, N'The two units who are off duty on the Sabbath will guard the Lord’s temple and protect the king.'
EXEC add_BibleVerse @BibleId, 112011008, N'You must surround the king. Each of you must hold his weapon in his hand. Whoever approaches your ranks must be killed. You must accompany the king wherever he goes.”'
EXEC add_BibleVerse @BibleId, 112011009, N'The officers of the units of hundreds did just as Jehoiada the priest ordered. Each of them took his men, those who were on duty during the Sabbath as well as those who were off duty on the Sabbath, and reported to Jehoiada the priest.'
EXEC add_BibleVerse @BibleId, 112011010, N'The priest gave to the officers of the units of hundreds King David’s spears and the shields that were kept in the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 112011011, N'The royal bodyguard took their stations, each holding his weapon in his hand. They lined up from the south side of the temple to the north side and stood near the altar and the temple, surrounding the king.'
EXEC add_BibleVerse @BibleId, 112011012, N'Jehoiada led out the king’s son and placed on him the crown and the royal insignia. They proclaimed him king and poured olive oil on his head. They clapped their hands and cried out, “Long live the king!”'
EXEC add_BibleVerse @BibleId, 112011013, N'When Athaliah heard the royal guard shout, she joined the crowd at the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 112011014, N'Then she saw the king standing by the pillar, according to custom. The officers stood beside the king with their trumpets and all the people of the land were celebrating and blowing trumpets. Athaliah tore her clothes and screamed, “Treason, treason!”'
EXEC add_BibleVerse @BibleId, 112011015, N'Jehoiada the priest ordered the officers of the units of hundreds, who were in charge of the army, “Bring her outside the temple to the guards. Put the sword to anyone who follows her.” The priest gave this order because he had decided she should not be executed in the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 112011016, N'They seized her and took her into the precincts of the royal palace through the horses’ entrance. There she was executed.'
EXEC add_BibleVerse @BibleId, 112011017, N'Jehoiada then drew up a covenant between the Lord and the king and people, stipulating that they should be loyal to the Lord.'
EXEC add_BibleVerse @BibleId, 112011018, N'All the people of the land went and demolished the temple of Baal. They smashed its altars and idols to bits. They killed Mattan the priest of Baal in front of the altar. Jehoiada the priest then placed guards at the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 112011019, N'He took the officers of the units of hundreds, the Carians, the royal bodyguard, and all the people of land, and together they led the king down from the Lord’s temple. They entered the royal palace through the Gate of the Royal Bodyguard, and the king sat down on the royal throne.'
EXEC add_BibleVerse @BibleId, 112011020, N'All the people of the land celebrated, for the city had rest now that they had killed Athaliah with the sword in the royal palace.'
EXEC add_BibleVerse @BibleId, 112011021, N'Jehoash was seven years old when he began to reign.'
EXEC add_BibleVerse @BibleId, 112012001, N'In Jehu’s seventh year Jehoash became king; he reigned for forty years in Jerusalem. His mother was Zibiah, who was from Beer Sheba.'
EXEC add_BibleVerse @BibleId, 112012002, N'Throughout his lifetime Jehoash did what the Lord approved, just as Jehoiada the priest taught him.'
EXEC add_BibleVerse @BibleId, 112012003, N'But the high places were not eliminated; the people continued to offer sacrifices and burn incense on the high places.'
EXEC add_BibleVerse @BibleId, 112012004, N'Jehoash said to the priests, “I place at your disposal all the consecrated silver that has been brought to the Lord’s temple, including the silver collected from the census tax, the silver received from those who have made vows, and all the silver that people have voluntarily contributed to the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 112012005, N'The priests should receive the silver they need from the treasurers and repair any damage to the temple they discover.”'
EXEC add_BibleVerse @BibleId, 112012006, N'By the twenty-third year of King Jehoash’s reign the priests had still not repaired the damage to the temple.'
EXEC add_BibleVerse @BibleId, 112012007, N'So King Jehoash summoned Jehoiada the priest along with the other priests, and said to them, “Why have you not repaired the damage to the temple? Now, take no more silver from your treasurers unless you intend to use it to repair the damage.”'
EXEC add_BibleVerse @BibleId, 112012008, N'The priests agreed not to collect silver from the people and relieved themselves of personal responsibility for the temple repairs.'
EXEC add_BibleVerse @BibleId, 112012009, N'Jehoiada the priest took a chest and drilled a hole in its lid. He placed it on the right side of the altar near the entrance of the Lord’s temple. The priests who guarded the entrance would put into it all the silver brought to the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 112012010, N'When they saw the chest was full of silver, the royal secretary and the high priest counted the silver that had been brought to the Lord’s temple and bagged it up.'
EXEC add_BibleVerse @BibleId, 112012011, N'They would then hand over the silver that had been weighed to the construction foremen assigned to the Lord’s temple. They hired carpenters and builders to work on the Lord’s temple,'
EXEC add_BibleVerse @BibleId, 112012012, N'as well as masons and stonecutters. They bought wood and chiseled stone to repair the damage to the Lord’s temple and also paid for all the other expenses.'
EXEC add_BibleVerse @BibleId, 112012013, N'The silver brought to the Lord’s temple was not used for silver bowls, trimming shears, basins, trumpets, or any kind of gold or silver implements.'
EXEC add_BibleVerse @BibleId, 112012014, N'It was handed over to the foremen who used it to repair the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 112012015, N'They did not audit the treasurers who disbursed the funds to the foremen, for they were honest.'
EXEC add_BibleVerse @BibleId, 112012016, N'(The silver collected in conjunction with reparation offerings and sin offerings was not brought to the Lord’s temple; it belonged to the priests.)'
EXEC add_BibleVerse @BibleId, 112012017, N'At that time King Hazael of Syria attacked Gath and captured it. Hazael then decided to attack Jerusalem.'
EXEC add_BibleVerse @BibleId, 112012018, N'King Jehoash of Judah collected all the sacred items that his ancestors Jehoshaphat, Jehoram, and Ahaziah, kings of Judah, had consecrated, as well as his own sacred items and all the gold that could be found in the treasuries of the Lord’s temple and the royal palace. He sent it all to King Hazael of Syria, who then withdrew from Jerusalem.'
EXEC add_BibleVerse @BibleId, 112012019, N'The rest of the events of Joash’s reign, including all his accomplishments, are recorded in the scroll called the Annals of the Kings of Judah.'
EXEC add_BibleVerse @BibleId, 112012020, N'His servants conspired against him and murdered Joash at Beth-Millo, on the road that goes down to Silla.'
EXEC add_BibleVerse @BibleId, 112012021, N'His servants Jozabad son of Shimeath and Jehozabad son of Shomer murdered him. He was buried with his ancestors in the city of David. His son Amaziah replaced him as king.'
EXEC add_BibleVerse @BibleId, 112013001, N'In the twenty-third year of the reign of Judah’s King Joash son of Ahaziah, Jehu’s son Jehoahaz became king over Israel. He reigned in Samaria for seventeen years.'
EXEC add_BibleVerse @BibleId, 112013002, N'He did evil in the sight of the Lord. He continued in the sinful ways of Jeroboam son of Nebat who had encouraged Israel to sin; he did not repudiate those sins.'
EXEC add_BibleVerse @BibleId, 112013003, N'The Lord was furious with Israel and handed them over to King Hazael of Syria and to Hazael’s son Ben Hadad for many years.'
EXEC add_BibleVerse @BibleId, 112013004, N'Jehoahaz asked for the Lord’s mercy and the Lord responded favorably, for he saw that Israel was oppressed by the king of Syria.'
EXEC add_BibleVerse @BibleId, 112013005, N'The Lord provided a deliverer for Israel and they were freed from Syria’s power. The Israelites once more lived in security.'
EXEC add_BibleVerse @BibleId, 112013006, N'But they did not repudiate the sinful ways of the family of Jeroboam, who encouraged Israel to sin; they continued in those sins. There was even an Asherah pole standing in Samaria.'
EXEC add_BibleVerse @BibleId, 112013007, N'Jehoahaz had no army left except for fifty horsemen, ten chariots, and 10,000 foot soldiers. The king of Syria had destroyed his troops and trampled on them like dust.'
EXEC add_BibleVerse @BibleId, 112013008, N'The rest of the events of Jehoahaz’s reign, including all his accomplishments and successes, are recorded in the scroll called the Annals of the Kings of Israel.'
EXEC add_BibleVerse @BibleId, 112013009, N'Jehoahaz passed away and was buried in Samaria. His son Joash replaced him as king.'
EXEC add_BibleVerse @BibleId, 112013010, N'In the thirty-seventh year of King Joash’s reign over Judah, Jehoahaz’s son Jehoash became king over Israel. He reigned in Samaria for sixteen years.'
EXEC add_BibleVerse @BibleId, 112013011, N'He did evil in the sight of the Lord. He did not repudiate the sinful ways of Jeroboam son of Nebat who encouraged Israel to sin; he continued in those sins.'
EXEC add_BibleVerse @BibleId, 112013012, N'The rest of the events of Joash’s reign, including all his accomplishments and his successful war with King Amaziah of Judah, are recorded in the scroll called the Annals of the Kings of Israel.'
EXEC add_BibleVerse @BibleId, 112013013, N'Joash passed away and Jeroboam succeeded him on the throne. Joash was buried in Samaria with the kings of Israel.'
EXEC add_BibleVerse @BibleId, 112013014, N'Now Elisha had a terminal illness. King Joash of Israel went down to visit him. He wept before him and said, “My father, my father! The chariot and horsemen of Israel!”'
EXEC add_BibleVerse @BibleId, 112013015, N'Elisha told him, “Take a bow and some arrows,” and he did so.'
EXEC add_BibleVerse @BibleId, 112013016, N'Then Elisha told the king of Israel, “Aim the bow.” He did so, and Elisha placed his hands on the king’s hands.'
EXEC add_BibleVerse @BibleId, 112013017, N'Elisha said, “Open the east window,” and he did so. Elisha said, “Shoot!” and he did so. Elisha said, “This arrow symbolizes the victory the Lord will give you over Syria. You will annihilate Syria in Aphek!”'
EXEC add_BibleVerse @BibleId, 112013018, N'Then Elisha said, “Take the arrows,” and he did so. He told the king of Israel, “Strike the ground!” He struck the ground three times and stopped.'
EXEC add_BibleVerse @BibleId, 112013019, N'The prophet got angry at him and said, “If you had struck the ground five or six times, you would have annihilated Syria! But now, you will defeat Syria only three times.”'
EXEC add_BibleVerse @BibleId, 112013020, N'Elisha died and was buried. Moabite raiding parties invaded the land at the beginning of the year.'
EXEC add_BibleVerse @BibleId, 112013021, N'One day some men were burying a man when they spotted a raiding party. So they threw the dead man into Elisha’s tomb. When the body touched Elisha’s bones, the dead man came to life and stood on his feet.'
EXEC add_BibleVerse @BibleId, 112013022, N'Now King Hazael of Syria oppressed Israel throughout Jehoahaz’s reign.'
EXEC add_BibleVerse @BibleId, 112013023, N'But the Lord had mercy on them and felt pity for them. He extended his favor to them because of the promise he had made to Abraham, Isaac, and Jacob. He has been unwilling to destroy them or remove them from his presence to this very day.'
EXEC add_BibleVerse @BibleId, 112013024, N'When King Hazael of Syria died, his son Ben Hadad replaced him as king.'
EXEC add_BibleVerse @BibleId, 112013025, N'Jehoahaz’s son Jehoash took back from Ben Hadad son of Hazael the cities that he had taken from his father Jehoahaz in war. Joash defeated him three times and recovered the Israelite cities.'
EXEC add_BibleVerse @BibleId, 112014001, N'In the second year of the reign of Israel’s King Joash son of Joahaz, Joash’s son Amaziah became king over Judah.'
EXEC add_BibleVerse @BibleId, 112014002, N'He was twenty-five years old when he began to reign, and he reigned for twenty-nine years in Jerusalem. His mother was Jehoaddan, who was from Jerusalem.'
EXEC add_BibleVerse @BibleId, 112014003, N'He did what the Lord approved, but not like David his father. He followed the example of his father Joash.'
EXEC add_BibleVerse @BibleId, 112014004, N'But the high places were not eliminated; the people continued to offer sacrifices and burn incense on the high places.'
EXEC add_BibleVerse @BibleId, 112014005, N'When he had secured control of the kingdom, he executed the servants who had assassinated his father.'
EXEC add_BibleVerse @BibleId, 112014006, N'But he did not execute the sons of the assassins. He obeyed the Lord’s commandment as recorded in the law scroll of Moses, “Fathers must not be put to death for what their sons do, and sons must not be put to death for what their fathers do. A man must be put to death only for his own sin.”'
EXEC add_BibleVerse @BibleId, 112014007, N'He defeated 10,000 Edomites in the Salt Valley; he captured Sela in battle and renamed it Joktheel, a name it has retained to this very day.'
EXEC add_BibleVerse @BibleId, 112014008, N'Then Amaziah sent messengers to Jehoash son of Jehoahaz son of Jehu, king of Israel. He said, “Come, let’s meet face to face.”'
EXEC add_BibleVerse @BibleId, 112014009, N'King Jehoash of Israel sent this message back to King Amaziah of Judah, “A thornbush in Lebanon sent this message to a cedar in Lebanon, ‘Give your daughter to my son as a wife.’ Then a wild animal of Lebanon came by and trampled down the thorn.'
EXEC add_BibleVerse @BibleId, 112014010, N'You thoroughly defeated Edom and it has gone to your head! Gloat over your success, but stay in your palace. Why bring calamity on yourself? Why bring down yourself and Judah along with you?”'
EXEC add_BibleVerse @BibleId, 112014011, N'But Amaziah would not heed the warning, so King Jehoash of Israel attacked. He and King Amaziah of Judah met face to face in Beth Shemesh of Judah.'
EXEC add_BibleVerse @BibleId, 112014012, N'Judah was defeated by Israel, and each man ran back home.'
EXEC add_BibleVerse @BibleId, 112014013, N'King Jehoash of Israel captured King Amaziah of Judah, son of Jehoash son of Ahaziah, in Beth Shemesh. He attacked Jerusalem and broke down the wall of Jerusalem from the Gate of Ephraim to the Corner Gate – a distance of about six hundred feet.'
EXEC add_BibleVerse @BibleId, 112014014, N'He took away all the gold and silver, all the items found in the Lord’s temple and in the treasuries of the royal palace, and some hostages. Then he went back to Samaria. ('
EXEC add_BibleVerse @BibleId, 112014015, N'The rest of the events of Jehoash’s reign, including all his accomplishments and his successful war with King Amaziah of Judah, are recorded in the scroll called the Annals of the Kings of Israel.'
EXEC add_BibleVerse @BibleId, 112014016, N'Jehoash passed away and was buried in Samaria with the kings of Israel. His son Jeroboam replaced him as king.)'
EXEC add_BibleVerse @BibleId, 112014017, N'King Amaziah son of Joash of Judah lived for fifteen years after the death of King Jehoash son of Jehoahaz of Israel.'
EXEC add_BibleVerse @BibleId, 112014018, N'The rest of the events of Amaziah’s reign are recorded in the scroll called the Annals of the Kings of Judah.'
EXEC add_BibleVerse @BibleId, 112014019, N'Conspirators plotted against him in Jerusalem, so he fled to Lachish. But they sent assassins after him and they killed him there.'
EXEC add_BibleVerse @BibleId, 112014020, N'His body was carried back by horses and he was buried in Jerusalem with his ancestors in the city of David.'
EXEC add_BibleVerse @BibleId, 112014021, N'All the people of Judah took Azariah, who was sixteen years old, and made him king in his father Amaziah’s place.'
EXEC add_BibleVerse @BibleId, 112014022, N'Azariah built up Elat and restored it to Judah after the king had passed away.'
EXEC add_BibleVerse @BibleId, 112014023, N'In the fifteenth year of the reign of Judah’s King Amaziah, son of Joash, Jeroboam son of Joash became king over Israel. He reigned for forty-one years in Samaria.'
EXEC add_BibleVerse @BibleId, 112014024, N'He did evil in the sight of the Lord; he did not repudiate the sinful ways of Jeroboam son of Nebat who encouraged Israel to sin.'
EXEC add_BibleVerse @BibleId, 112014025, N'He restored the border of Israel from Lebo Hamath in the north to the sea of the Arabah in the south, in accordance with the word of the Lord God of Israel announced through his servant Jonah son of Amittai, the prophet from Gath Hepher.'
EXEC add_BibleVerse @BibleId, 112014026, N'The Lord saw Israel’s intense suffering; everyone was weak and incapacitated and Israel had no deliverer.'
EXEC add_BibleVerse @BibleId, 112014027, N'The Lord had not decreed that he would blot out Israel’s memory from under heaven, so he delivered them through Jeroboam son of Joash.'
EXEC add_BibleVerse @BibleId, 112014028, N'The rest of the events of Jeroboam’s reign, including all his accomplishments, his military success in restoring Israelite control over Damascus and Hamath, are recorded in the scroll called the Annals of the Kings of Israel.'
EXEC add_BibleVerse @BibleId, 112014029, N'Jeroboam passed away and was buried in Samaria with the kings of Israel. His son Zechariah replaced him as king.'
EXEC add_BibleVerse @BibleId, 112015001, N'In the twenty-seventh year of King Jeroboam’s reign over Israel, Amaziah’s son Azariah became king over Judah.'
EXEC add_BibleVerse @BibleId, 112015002, N'He was sixteen years old when he began to reign, and he reigned for fifty-two years in Jerusalem. His mother’s name was Jecholiah, who was from Jerusalem.'
EXEC add_BibleVerse @BibleId, 112015003, N'He did what the Lord approved, just as his father Amaziah had done.'
EXEC add_BibleVerse @BibleId, 112015004, N'But the high places were not eliminated; the people continued to offer sacrifices and burn incense on the high places.'
EXEC add_BibleVerse @BibleId, 112015005, N'The Lord afflicted the king with an illness; he suffered from a skin disease until the day he died. He lived in separate quarters, while his son Jotham was in charge of the palace and ruled over the people of the land.'
EXEC add_BibleVerse @BibleId, 112015006, N'The rest of the events of Azariah’s reign, including all his accomplishments, are recorded in the scroll called the Annals of the Kings of Judah.'
EXEC add_BibleVerse @BibleId, 112015007, N'Azariah passed away and was buried with his ancestors in the city of David. His son Jotham replaced him as king.'
EXEC add_BibleVerse @BibleId, 112015008, N'In the thirty-eighth year of King Azariah’s reign over Judah, Jeroboam’s son Zechariah became king over Israel. He reigned in Samaria for six months.'
EXEC add_BibleVerse @BibleId, 112015009, N'He did evil in the sight of the Lord, as his ancestors had done. He did not repudiate the sinful ways of Jeroboam son of Nebat who encouraged Israel to sin.'
EXEC add_BibleVerse @BibleId, 112015010, N'Shallum son of Jabesh conspired against him; he assassinated him in Ibleam and took his place as king.'
EXEC add_BibleVerse @BibleId, 112015011, N'The rest of the events of Zechariah’s reign are recorded in the scroll called the Annals of the Kings of Israel.'
EXEC add_BibleVerse @BibleId, 112015012, N'His assassination brought to fulfillment the Lord’s word to Jehu, “Four generations of your descendants will rule over Israel.” That is exactly what happened.'
EXEC add_BibleVerse @BibleId, 112015013, N'Shallum son of Jabesh became king in the thirty-ninth year of King Uzziah’s reign over Judah. He reigned for one month in Samaria.'
EXEC add_BibleVerse @BibleId, 112015014, N'Menahem son of Gadi went up from Tirzah to Samaria and attacked Shallum son of Jabesh. He killed him and took his place as king.'
EXEC add_BibleVerse @BibleId, 112015015, N'The rest of the events of Shallum’s reign, including the conspiracy he organized, are recorded in the scroll called the Annals of the Kings of Israel.'
EXEC add_BibleVerse @BibleId, 112015016, N'At that time Menahem came from Tirzah and attacked Tiphsah. He struck down all who lived in the city and the surrounding territory, because they would not surrender. He even ripped open the pregnant women.'
EXEC add_BibleVerse @BibleId, 112015017, N'In the thirty-ninth year of King Azariah’s reign over Judah, Menahem son of Gadi became king over Israel. He reigned for twelve years in Samaria.'
EXEC add_BibleVerse @BibleId, 112015018, N'He did evil in the sight of the Lord; he did not repudiate the sinful ways of Jeroboam son of Nebat who encouraged Israel to sin. During his reign,'
EXEC add_BibleVerse @BibleId, 112015019, N'Pul king of Assyria invaded the land, and Menahem paid him a thousand talents of silver to gain his support and to solidify his control of the kingdom.'
EXEC add_BibleVerse @BibleId, 112015020, N'Menahem got this silver by taxing all the wealthy men in Israel; he took fifty shekels of silver from each one of them and paid it to the king of Assyria. Then the king of Assyria left; he did not stay there in the land.'
EXEC add_BibleVerse @BibleId, 112015021, N'The rest of the events of Menahem’s reign, including all his accomplishments, are recorded in the scroll called the Annals of the Kings of Israel.'
EXEC add_BibleVerse @BibleId, 112015022, N'Menahem passed away and his son Pekahiah replaced him as king.'
EXEC add_BibleVerse @BibleId, 112015023, N'In the fiftieth year of King Azariah’s reign over Judah, Menahem’s son Pekahiah became king over Israel. He reigned in Samaria for two years.'
EXEC add_BibleVerse @BibleId, 112015024, N'He did evil in the sight of the Lord; he did not repudiate the sinful ways of Jeroboam son of Nebat who encouraged Israel to sin.'
EXEC add_BibleVerse @BibleId, 112015025, N'His officer Pekah son of Remaliah conspired against him. He and fifty Gileadites assassinated Pekahiah, as well as Argob and Arieh, in Samaria in the fortress of the royal palace. Pekah then took his place as king.'
EXEC add_BibleVerse @BibleId, 112015026, N'The rest of the events of Pekahiah’s reign, including all his accomplishments, are recorded in the scroll called the Annals of the Kings of Israel.'
EXEC add_BibleVerse @BibleId, 112015027, N'In the fifty-second year of King Azariah’s reign over Judah, Pekah son of Remaliah became king over Israel. He reigned in Samaria for twenty years.'
EXEC add_BibleVerse @BibleId, 112015028, N'He did evil in the sight of the Lord; he did not repudiate the sinful ways of Jeroboam son of Nebat who encouraged Israel to sin.'
EXEC add_BibleVerse @BibleId, 112015029, N'During Pekah’s reign over Israel, King Tiglath-pileser of Assyria came and captured Ijon, Abel Beth Maacah, Janoah, Kedesh, Hazor, Gilead, and Galilee, including all the territory of Naphtali. He deported the people to Assyria.'
EXEC add_BibleVerse @BibleId, 112015030, N'Hoshea son of Elah conspired against Pekah son of Remaliah. He assassinated him and took his place as king, in the twentieth year of the reign of Jotham son of Uzziah.'
EXEC add_BibleVerse @BibleId, 112015031, N'The rest of the events of Pekah’s reign, including all his accomplishments, are recorded in the scroll called the Annals of the Kings of Israel.'
EXEC add_BibleVerse @BibleId, 112015032, N'In the second year of the reign of Israel’s King Pekah son of Remaliah, Uzziah’s son Jotham became king over Judah.'
EXEC add_BibleVerse @BibleId, 112015033, N'He was twenty-five years old when he began to reign, and he reigned for sixteen years in Jerusalem. His mother was Jerusha the daughter of Zadok.'
EXEC add_BibleVerse @BibleId, 112015034, N'He did what the Lord approved, just as his father Uzziah had done.'
EXEC add_BibleVerse @BibleId, 112015035, N'But the high places were not eliminated; the people continued to offer sacrifices and burn incense on the high places. He built the Upper Gate to the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 112015036, N'The rest of the events of Jotham’s reign, including his accomplishments, are recorded in the scroll called the Annals of the Kings of Judah.'
EXEC add_BibleVerse @BibleId, 112015037, N'In those days the Lord prompted King Rezin of Syria and Pekah son of Remaliah to attack Judah.'
EXEC add_BibleVerse @BibleId, 112015038, N'Jotham passed away and was buried with his ancestors in the city of his ancestor David. His son Ahaz replaced him as king.'
EXEC add_BibleVerse @BibleId, 112016001, N'In the seventeenth year of the reign of Pekah son of Remaliah, Jotham’s son Ahaz became king over Judah.'
EXEC add_BibleVerse @BibleId, 112016002, N'Ahaz was twenty years old when he began to reign, and he reigned for sixteen years in Jerusalem. He did not do what pleased the Lord his God, in contrast to his ancestor David.'
EXEC add_BibleVerse @BibleId, 112016003, N'He followed in the footsteps of the kings of Israel. He passed his son through the fire, a horrible sin practiced by the nations whom the Lord drove out from before the Israelites.'
EXEC add_BibleVerse @BibleId, 112016004, N'He offered sacrifices and burned incense on the high places, on the hills, and under every green tree.'
EXEC add_BibleVerse @BibleId, 112016005, N'At that time King Rezin of Syria and King Pekah son of Remaliah of Israel attacked Jerusalem. They besieged Ahaz, but were unable to conquer him.'
EXEC add_BibleVerse @BibleId, 112016006, N'(At that time King Rezin of Syria recovered Elat for Syria; he drove the Judahites from there. Syrians arrived in Elat and live there to this very day.)'
EXEC add_BibleVerse @BibleId, 112016007, N'Ahaz sent messengers to King Tiglath-pileser of Assyria, saying, “I am your servant and your dependent. March up and rescue me from the power of the king of Syria and the king of Israel, who have attacked me.”'
EXEC add_BibleVerse @BibleId, 112016008, N'Then Ahaz took the silver and gold that were in the Lord’s temple and in the treasuries of the royal palace and sent it as tribute to the king of Assyria.'
EXEC add_BibleVerse @BibleId, 112016009, N'The king of Assyria responded favorably to his request; he attacked Damascus and captured it. He deported the people to Kir and executed Rezin.'
EXEC add_BibleVerse @BibleId, 112016010, N'When King Ahaz went to meet with King Tiglath-pileser of Assyria in Damascus, he saw the altar there. King Ahaz sent to Uriah the priest a drawing of the altar and a blueprint for its design.'
EXEC add_BibleVerse @BibleId, 112016011, N'Uriah the priest built an altar in conformity to the plans King Ahaz had sent from Damascus. Uriah the priest finished it before King Ahaz arrived back from Damascus.'
EXEC add_BibleVerse @BibleId, 112016012, N'When the king arrived back from Damascus and saw the altar, he approached it and offered a sacrifice on it.'
EXEC add_BibleVerse @BibleId, 112016013, N'He offered his burnt sacrifice and his grain offering. He poured out his libation and sprinkled the blood from his peace offerings on the altar.'
EXEC add_BibleVerse @BibleId, 112016014, N'He moved the bronze altar that stood in the Lord’s presence from the front of the temple (between the altar and the Lord’s temple) and put it on the north side of the new altar.'
EXEC add_BibleVerse @BibleId, 112016015, N'King Ahaz ordered Uriah the priest, “On the large altar offer the morning burnt sacrifice, the evening grain offering, the royal burnt sacrifices and grain offering, the burnt sacrifice for all the people of Israel, their grain offering, and their libations. Sprinkle all the blood of the burnt sacrifice and other sacrifices on it. The bronze altar will be for my personal use.”'
EXEC add_BibleVerse @BibleId, 112016016, N'So Uriah the priest did exactly as King Ahaz ordered.'
EXEC add_BibleVerse @BibleId, 112016017, N'King Ahaz took off the frames of the movable stands, and removed the basins from them. He took “The Sea” down from the bronze bulls that supported it and put it on the pavement.'
EXEC add_BibleVerse @BibleId, 112016018, N'He also removed the Sabbath awning that had been built in the temple and the king’s outer entranceway, on account of the king of Assyria.'
EXEC add_BibleVerse @BibleId, 112016019, N'The rest of the events of Ahaz’s reign, including his accomplishments, are recorded in the scroll called the Annals of the Kings of Judah.'
EXEC add_BibleVerse @BibleId, 112016020, N'Ahaz passed away and was buried with his ancestors in the city of David. His son Hezekiah replaced him as king.'
EXEC add_BibleVerse @BibleId, 112017001, N'In the twelfth year of King Ahaz’s reign over Judah, Hoshea son of Elah became king over Israel. He reigned in Samaria for nine years.'
EXEC add_BibleVerse @BibleId, 112017002, N'He did evil in the sight of the Lord, but not to the same degree as the Israelite kings who preceded him.'
EXEC add_BibleVerse @BibleId, 112017003, N'King Shalmaneser of Assyria threatened him; Hoshea became his subject and paid him tribute.'
EXEC add_BibleVerse @BibleId, 112017004, N'The king of Assyria discovered that Hoshea was planning a revolt. Hoshea had sent messengers to King So of Egypt and had not sent his annual tribute to the king of Assyria. So the king of Assyria arrested him and imprisoned him.'
EXEC add_BibleVerse @BibleId, 112017005, N'The king of Assyria marched through the whole land. He attacked Samaria and besieged it for three years.'
EXEC add_BibleVerse @BibleId, 112017006, N'In the ninth year of Hoshea’s reign, the king of Assyria captured Samaria and deported the people of Israel to Assyria. He settled them in Halah, along the Habor (the river of Gozan), and in the cities of the Medes.'
EXEC add_BibleVerse @BibleId, 112017007, N'This happened because the Israelites sinned against the Lord their God, who brought them up from the land of Egypt and freed them from the power of Pharaoh king of Egypt. They worshiped other gods;'
EXEC add_BibleVerse @BibleId, 112017008, N'they observed the practices of the nations whom the Lord had driven out from before Israel, and followed the example of the kings of Israel.'
EXEC add_BibleVerse @BibleId, 112017009, N'The Israelites said things about the Lord their God that were not right. They built high places in all their cities, from the watchtower to the fortress.'
EXEC add_BibleVerse @BibleId, 112017010, N'They set up sacred pillars and Asherah poles on every high hill and under every green tree.'
EXEC add_BibleVerse @BibleId, 112017011, N'They burned incense on all the high places just like the nations whom the Lord had driven away from before them. Their evil practices made the Lord angry.'
EXEC add_BibleVerse @BibleId, 112017012, N'They worshiped the disgusting idols in blatant disregard of the Lord’s command.'
EXEC add_BibleVerse @BibleId, 112017013, N'The Lord solemnly warned Israel and Judah through all his prophets and all the seers, “Turn back from your evil ways; obey my commandments and rules that are recorded in the law. I ordered your ancestors to keep this law and sent my servants the prophets to remind you of its demands.”'
EXEC add_BibleVerse @BibleId, 112017014, N'But they did not pay attention and were as stubborn as their ancestors, who had not trusted the Lord their God.'
EXEC add_BibleVerse @BibleId, 112017015, N'They rejected his rules, the covenant he had made with their ancestors, and the laws he had commanded them to obey. They paid allegiance to worthless idols, and so became worthless to the Lord. They copied the practices of the surrounding nations in blatant disregard of the Lord’s command.'
EXEC add_BibleVerse @BibleId, 112017016, N'They abandoned all the commandments of the Lord their God; they made two metal calves and an Asherah pole, bowed down to all the stars in the sky, and worshiped Baal.'
EXEC add_BibleVerse @BibleId, 112017017, N'They passed their sons and daughters through the fire, and practiced divination and omen reading. They committed themselves to doing evil in the sight of the Lord and made him angry.'
EXEC add_BibleVerse @BibleId, 112017018, N'So the Lord was furious with Israel and rejected them; only the tribe of Judah was left.'
EXEC add_BibleVerse @BibleId, 112017019, N'Judah also failed to keep the commandments of the Lord their God; they followed Israel’s example.'
EXEC add_BibleVerse @BibleId, 112017020, N'So the Lord rejected all of Israel’s descendants; he humiliated them and handed them over to robbers, until he had thrown them from his presence.'
EXEC add_BibleVerse @BibleId, 112017021, N'He tore Israel away from David’s dynasty, and Jeroboam son of Nebat became their king. Jeroboam drove Israel away from the Lord and encouraged them to commit a serious sin.'
EXEC add_BibleVerse @BibleId, 112017022, N'The Israelites followed in the sinful ways of Jeroboam son of Nebat and did not repudiate them.'
EXEC add_BibleVerse @BibleId, 112017023, N'Finally the Lord rejected Israel just as he had warned he would do through all his servants the prophets. Israel was deported from its land to Assyria and remains there to this very day.'
EXEC add_BibleVerse @BibleId, 112017024, N'The king of Assyria brought foreigners from Babylon, Cuthah, Avva, Hamath, and Sepharvaim and settled them in the cities of Samaria in place of the Israelites. They took possession of Samaria and lived in its cities.'
EXEC add_BibleVerse @BibleId, 112017025, N'When they first moved in, they did not worship the Lord. So the Lord sent lions among them and the lions were killing them.'
EXEC add_BibleVerse @BibleId, 112017026, N'The king of Assyria was told, “The nations whom you deported and settled in the cities of Samaria do not know the requirements of the God of the land, so he has sent lions among them. They are killing the people because they do not know the requirements of the God of the land.”'
EXEC add_BibleVerse @BibleId, 112017027, N'So the king of Assyria ordered, “Take back one of the priests whom you deported from there. He must settle there and teach them the requirements of the God of the land.”'
EXEC add_BibleVerse @BibleId, 112017028, N'So one of the priests whom they had deported from Samaria went back and settled in Bethel. He taught them how to worship the Lord.'
EXEC add_BibleVerse @BibleId, 112017029, N'But each of these nations made its own gods and put them in the shrines on the high places that the people of Samaria had made. Each nation did this in the cities where they lived.'
EXEC add_BibleVerse @BibleId, 112017030, N'The people from Babylon made Succoth Benoth, the people from Cuth made Nergal, the people from Hamath made Ashima,'
EXEC add_BibleVerse @BibleId, 112017031, N'the Avvites made Nibhaz and Tartak, and the Sepharvites burned their sons in the fire as an offering to Adrammelech and Anammelech, the gods of Sepharvaim.'
EXEC add_BibleVerse @BibleId, 112017032, N'At the same time they worshiped the Lord. They appointed some of their own people to serve as priests in the shrines on the high places.'
EXEC add_BibleVerse @BibleId, 112017033, N'They were worshiping the Lord and at the same time serving their own gods in accordance with the practices of the nations from which they had been deported.'
EXEC add_BibleVerse @BibleId, 112017034, N'To this very day they observe their earlier practices. They do not worship the Lord; they do not obey the rules, regulations, law, and commandments that the Lord gave the descendants of Jacob, whom he renamed Israel.'
EXEC add_BibleVerse @BibleId, 112017035, N'The Lord made an agreement with them and instructed them, “You must not worship other gods. Do not bow down to them, serve them, or offer sacrifices to them.'
EXEC add_BibleVerse @BibleId, 112017036, N'Instead you must worship the Lord, who brought you up from the land of Egypt by his great power and military ability; bow down to him and offer sacrifices to him.'
EXEC add_BibleVerse @BibleId, 112017037, N'You must carefully obey at all times the rules, regulations, law, and commandments he wrote down for you. You must not worship other gods.'
EXEC add_BibleVerse @BibleId, 112017038, N'You must never forget the agreement I made with you, and you must not worship other gods.'
EXEC add_BibleVerse @BibleId, 112017039, N'Instead you must worship the Lord your God; then he will rescue you from the power of all your enemies.”'
EXEC add_BibleVerse @BibleId, 112017040, N'But they pay no attention; instead they observe their earlier practices.'
EXEC add_BibleVerse @BibleId, 112017041, N'These nations are worshiping the Lord and at the same time serving their idols; their sons and grandsons do just as their fathers have done, to this very day.'
EXEC add_BibleVerse @BibleId, 112018001, N'In the third year of the reign of Israel’s King Hoshea son of Elah, Ahaz’s son Hezekiah became king over Judah.'
EXEC add_BibleVerse @BibleId, 112018002, N'He was twenty-five years old when he began to reign, and he reigned twenty-nine years in Jerusalem. His mother was Abi, the daughter of Zechariah.'
EXEC add_BibleVerse @BibleId, 112018003, N'He did what the Lord approved, just as his ancestor David had done.'
EXEC add_BibleVerse @BibleId, 112018004, N'He eliminated the high places, smashed the sacred pillars to bits, and cut down the Asherah pole. He also demolished the bronze serpent that Moses had made, for up to that time the Israelites had been offering incense to it; it was called Nehushtan.'
EXEC add_BibleVerse @BibleId, 112018005, N'He trusted in the Lord God of Israel; in this regard there was none like him among the kings of Judah either before or after.'
EXEC add_BibleVerse @BibleId, 112018006, N'He was loyal to the Lord and did not abandon him. He obeyed the commandments which the Lord had given to Moses.'
EXEC add_BibleVerse @BibleId, 112018007, N'The Lord was with him; he succeeded in all his endeavors. He rebelled against the king of Assyria and refused to submit to him.'
EXEC add_BibleVerse @BibleId, 112018008, N'He defeated the Philistines as far as Gaza and its territory, from the watchtower to the city fortress.'
EXEC add_BibleVerse @BibleId, 112018009, N'In the fourth year of King Hezekiah’s reign (it was the seventh year of the reign of Israel’s King Hoshea, son of Elah), King Shalmaneser of Assyria marched up against Samaria and besieged it.'
EXEC add_BibleVerse @BibleId, 112018010, N'After three years he captured it (in the sixth year of Hezekiah’s reign); in the ninth year of King Hoshea’s reign over Israel Samaria was captured.'
EXEC add_BibleVerse @BibleId, 112018011, N'The king of Assyria deported the people of Israel to Assyria. He settled them in Halah, along the Habor (the river of Gozan), and in the cities of the Medes.'
EXEC add_BibleVerse @BibleId, 112018012, N'This happened because they did not obey the Lord their God and broke his agreement with them. They did not pay attention to and obey all that Moses, the Lord’s servant, had commanded.'
EXEC add_BibleVerse @BibleId, 112018013, N'In the fourteenth year of King Hezekiah’s reign, King Sennacherib of Assyria marched up against all the fortified cities of Judah and captured them.'
EXEC add_BibleVerse @BibleId, 112018014, N'King Hezekiah of Judah sent this message to the king of Assyria, who was at Lachish, “I have violated our treaty. If you leave, I will do whatever you demand.” So the king of Assyria demanded that King Hezekiah of Judah pay three hundred talents of silver and thirty talents of gold.'
EXEC add_BibleVerse @BibleId, 112018015, N'Hezekiah gave him all the silver in the Lord’s temple and in the treasuries of the royal palace.'
EXEC add_BibleVerse @BibleId, 112018016, N'At that time King Hezekiah of Judah stripped the metal overlays from the doors of the Lord’s temple and from the posts which he had plated and gave them to the king of Assyria.'
EXEC add_BibleVerse @BibleId, 112018017, N'The king of Assyria sent his commanding general, the chief eunuch, and the chief adviser from Lachish to King Hezekiah in Jerusalem, along with a large army. They went up and arrived at Jerusalem. They went and stood at the conduit of the upper pool which is located on the road to the field where they wash and dry cloth.'
EXEC add_BibleVerse @BibleId, 112018018, N'They summoned the king, so Eliakim son of Hilkiah, the palace supervisor, accompanied by Shebna the scribe and Joah son of Asaph, the secretary, went out to meet them.'
EXEC add_BibleVerse @BibleId, 112018019, N'The chief adviser said to them, “Tell Hezekiah: ‘This is what the great king, the king of Assyria, says: “What is your source of confidence?'
EXEC add_BibleVerse @BibleId, 112018020, N'Your claim to have a strategy and military strength is just empty talk. In whom are you trusting that you would dare to rebel against me?'
EXEC add_BibleVerse @BibleId, 112018021, N'Now look, you must be trusting in Egypt, that splintered reed staff. If a man leans for support on it, it punctures his hand and wounds him. That is what Pharaoh king of Egypt does to all who trust in him.'
EXEC add_BibleVerse @BibleId, 112018022, N'Perhaps you will tell me, ‘We are trusting in the Lord our God.’ But Hezekiah is the one who eliminated his high places and altars and then told the people of Judah and Jerusalem, ‘You must worship at this altar in Jerusalem.’'
EXEC add_BibleVerse @BibleId, 112018023, N'Now make a deal with my master the king of Assyria, and I will give you two thousand horses, provided you can find enough riders for them.'
EXEC add_BibleVerse @BibleId, 112018024, N'Certainly you will not refuse one of my master’s minor officials and trust in Egypt for chariots and horsemen.'
EXEC add_BibleVerse @BibleId, 112018025, N'Furthermore it was by the command of the Lord that I marched up against this place to destroy it. The Lord told me, ‘March up against this land and destroy it.’”’”'
EXEC add_BibleVerse @BibleId, 112018026, N'Eliakim son of Hilkiah, Shebna, and Joah said to the chief adviser, “Speak to your servants in Aramaic, for we understand it. Don’t speak with us in the Judahite dialect in the hearing of the people who are on the wall.”'
EXEC add_BibleVerse @BibleId, 112018027, N'But the chief adviser said to them, “My master did not send me to speak these words only to your master and to you. His message is also for the men who sit on the wall, for they will eat their own excrement and drink their own urine along with you.”'
EXEC add_BibleVerse @BibleId, 112018028, N'The chief adviser then stood there and called out loudly in the Judahite dialect, “Listen to the message of the great king, the king of Assyria.'
EXEC add_BibleVerse @BibleId, 112018029, N'This is what the king says: ‘Don’t let Hezekiah mislead you, for he is not able to rescue you from my hand!'
EXEC add_BibleVerse @BibleId, 112018030, N'Don’t let Hezekiah talk you into trusting in the Lord when he says, “The Lord will certainly rescue us; this city will not be handed over to the king of Assyria.”'
EXEC add_BibleVerse @BibleId, 112018031, N'Don’t listen to Hezekiah!’ For this is what the king of Assyria says, ‘Send me a token of your submission and surrender to me. Then each of you may eat from his own vine and fig tree and drink water from his own cistern,'
EXEC add_BibleVerse @BibleId, 112018032, N'until I come and take you to a land just like your own – a land of grain and new wine, a land of bread and vineyards, a land of olive trees and honey. Then you will live and not die. Don’t listen to Hezekiah, for he is misleading you when he says, “The Lord will rescue us.”'
EXEC add_BibleVerse @BibleId, 112018033, N'Have any of the gods of the nations actually rescued his land from the power of the king of Assyria?'
EXEC add_BibleVerse @BibleId, 112018034, N'Where are the gods of Hamath and Arpad? Where are the gods of Sepharvaim, Hena, and Ivvah? Indeed, did any gods rescue Samaria from my power?'
EXEC add_BibleVerse @BibleId, 112018035, N'Who among all the gods of the lands has rescued their lands from my power? So how can the Lord rescue Jerusalem from my power?’”'
EXEC add_BibleVerse @BibleId, 112018036, N'The people were silent and did not respond, for the king had ordered, “Don’t respond to him.”'
EXEC add_BibleVerse @BibleId, 112018037, N'Eliakim son of Hilkiah, the palace supervisor, accompanied by Shebna the scribe and Joah son of Asaph, the secretary, went to Hezekiah with their clothes torn and reported to him what the chief adviser had said.'
EXEC add_BibleVerse @BibleId, 112019001, N'When King Hezekiah heard this, he tore his clothes, put on sackcloth, and went to the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 112019002, N'He sent Eliakim the palace supervisor, Shebna the scribe, and the leading priests, clothed in sackcloth, with this message to the prophet Isaiah son of Amoz:'
EXEC add_BibleVerse @BibleId, 112019003, N'“This is what Hezekiah says: ‘This is a day of distress, insults, and humiliation, as when a baby is ready to leave the birth canal, but the mother lacks the strength to push it through.'
EXEC add_BibleVerse @BibleId, 112019004, N'Perhaps the Lord your God will hear all these things the chief adviser has spoken on behalf of his master, the king of Assyria, who sent him to taunt the living God. When the Lord your God hears, perhaps he will punish him for the things he has said. So pray for this remnant that remains.’”'
EXEC add_BibleVerse @BibleId, 112019005, N'When King Hezekiah’s servants came to Isaiah,'
EXEC add_BibleVerse @BibleId, 112019006, N'Isaiah said to them, “Tell your master this: ‘This is what the Lord says: “Don’t be afraid because of the things you have heard – these insults the king of Assyria’s servants have hurled against me.'
EXEC add_BibleVerse @BibleId, 112019007, N'Look, I will take control of his mind; he will receive a report and return to his own land. I will cut him down with a sword in his own land.”’”'
EXEC add_BibleVerse @BibleId, 112019008, N'When the chief adviser heard the king of Assyria had departed from Lachish, he left and went to Libnah, where the king was campaigning.'
EXEC add_BibleVerse @BibleId, 112019009, N'The king heard that King Tirhakah of Ethiopia was marching out to fight him. He again sent messengers to Hezekiah, ordering them:'
EXEC add_BibleVerse @BibleId, 112019010, N'“Tell King Hezekiah of Judah this: ‘Don’t let your God in whom you trust mislead you when he says, “Jerusalem will not be handed over to the king of Assyria.”'
EXEC add_BibleVerse @BibleId, 112019011, N'Certainly you have heard how the kings of Assyria have annihilated all lands. Do you really think you will be rescued?'
EXEC add_BibleVerse @BibleId, 112019012, N'Were the nations whom my ancestors destroyed – the nations of Gozan, Haran, Rezeph, and the people of Eden in Telassar – rescued by their gods?'
EXEC add_BibleVerse @BibleId, 112019013, N'Where are the king of Hamath, the king of Arpad, and the king of Lair, Sepharvaim, Hena, and Ivvah?’”'
EXEC add_BibleVerse @BibleId, 112019014, N'Hezekiah took the letter from the messengers and read it. Then Hezekiah went up to the Lord’s temple and spread it out before the Lord.'
EXEC add_BibleVerse @BibleId, 112019015, N'Hezekiah prayed before the Lord: “Lord God of Israel, who is enthroned on the cherubs! You alone are God over all the kingdoms of the earth. You made the sky and the earth.'
EXEC add_BibleVerse @BibleId, 112019016, N'Pay attention, Lord, and hear! Open your eyes, Lord, and observe! Listen to the message Sennacherib sent and how he taunts the living God!'
EXEC add_BibleVerse @BibleId, 112019017, N'It is true, Lord, that the kings of Assyria have destroyed the nations and their lands.'
EXEC add_BibleVerse @BibleId, 112019018, N'They have burned the gods of the nations, for they are not really gods, but only the product of human hands manufactured from wood and stone. That is why the Assyrians could destroy them.'
EXEC add_BibleVerse @BibleId, 112019019, N'Now, O Lord our God, rescue us from his power, so that all the kingdoms of the earth will know that you, Lord, are the only God.”'
EXEC add_BibleVerse @BibleId, 112019020, N'Isaiah son of Amoz sent this message to Hezekiah: “This is what the Lord God of Israel says: ‘I have heard your prayer concerning King Sennacherib of Assyria.'
EXEC add_BibleVerse @BibleId, 112019021, N'This is what the Lord says about him: “The virgin daughter Zion despises you, she makes fun of you; Daughter Jerusalem shakes her head after you.'
EXEC add_BibleVerse @BibleId, 112019022, N'Whom have you taunted and hurled insults at? At whom have you shouted, and looked so arrogantly? At the Holy One of Israel!'
EXEC add_BibleVerse @BibleId, 112019023, N'Through your messengers you taunted the sovereign master, ‘With my many chariots I climbed up the high mountains, the slopes of Lebanon. I cut down its tall cedars, and its best evergreens. I invaded its most remote regions, its thickest woods.'
EXEC add_BibleVerse @BibleId, 112019024, N'I dug wells and drank water in foreign lands. With the soles of my feet I dried up all the rivers of Egypt.’'
EXEC add_BibleVerse @BibleId, 112019025, N'Certainly you must have heard! Long ago I worked it out, In ancient times I planned it; and now I am bringing it to pass. The plan is this: Fortified cities will crash into heaps of ruins.'
EXEC add_BibleVerse @BibleId, 112019026, N'Their residents are powerless, they are terrified and ashamed. They are as short-lived as plants in the field, or green vegetation. They are as short-lived as grass on the rooftops when it is scorched by the east wind.'
EXEC add_BibleVerse @BibleId, 112019027, N'I know where you live, and everything you do.'
EXEC add_BibleVerse @BibleId, 112019028, N'Because you rage against me, and the uproar you create has reached my ears; I will put my hook in your nose, and my bridle between your lips, and I will lead you back the way you came.”'
EXEC add_BibleVerse @BibleId, 112019029, N'This will be your confirmation that I have spoken the truth: This year you will eat what grows wild, and next year what grows on its own from that. But in the third year you will plant seed and harvest crops; you will plant vines and consume their produce.'
EXEC add_BibleVerse @BibleId, 112019030, N'Those who remain in Judah will take root in the ground and bear fruit.'
EXEC add_BibleVerse @BibleId, 112019031, N'For a remnant will leave Jerusalem; survivors will come out of Mount Zion. The intense devotion of the sovereign Lord to his people will accomplish this.'
EXEC add_BibleVerse @BibleId, 112019032, N'So this is what the Lord says about the king of Assyria: “He will not enter this city, nor will he shoot an arrow here. He will not attack it with his shield-carrying warriors, nor will he build siege works against it.'
EXEC add_BibleVerse @BibleId, 112019033, N'He will go back the way he came. He will not enter this city,” says the Lord.'
EXEC add_BibleVerse @BibleId, 112019034, N'I will shield this city and rescue it for the sake of my reputation and because of my promise to David my servant.’”'
EXEC add_BibleVerse @BibleId, 112019035, N'That very night the Lord’s messenger went out and killed 185,000 men in the Assyrian camp. When they got up early the next morning, there were all the corpses.'
EXEC add_BibleVerse @BibleId, 112019036, N'So King Sennacherib of Assyria broke camp and went on his way. He went home and stayed in Nineveh.'
EXEC add_BibleVerse @BibleId, 112019037, N'One day, as he was worshiping in the temple of his god Nisroch, his sons Adrammelech and Sharezer struck him down with the sword. They escaped to the land of Ararat; his son Esarhaddon replaced him as king.'
EXEC add_BibleVerse @BibleId, 112020001, N'In those days Hezekiah was stricken with a terminal illness. The prophet Isaiah son of Amoz visited him and told him, “This is what the Lord says, ‘Give your household instructions, for you are about to die; you will not get well.’”'
EXEC add_BibleVerse @BibleId, 112020002, N'He turned his face to the wall and prayed to the Lord,'
EXEC add_BibleVerse @BibleId, 112020003, N'“Please, Lord. Remember how I have served you faithfully and with wholehearted devotion, and how I have carried out your will.” Then Hezekiah wept bitterly.'
EXEC add_BibleVerse @BibleId, 112020004, N'Isaiah was still in the middle courtyard when the Lord told him,'
EXEC add_BibleVerse @BibleId, 112020005, N'“Go back and tell Hezekiah, the leader of my people: ‘This is what the Lord God of your ancestor David says: “I have heard your prayer; I have seen your tears. Look, I will heal you. The day after tomorrow you will go up to the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 112020006, N'I will add fifteen years to your life and rescue you and this city from the king of Assyria. I will shield this city for the sake of my reputation and because of my promise to David my servant.”’”'
EXEC add_BibleVerse @BibleId, 112020007, N'Isaiah ordered, “Get a fig cake.” So they did as he ordered and placed it on the ulcerated sore, and he recovered.'
EXEC add_BibleVerse @BibleId, 112020008, N'Hezekiah had said to Isaiah, “What is the confirming sign that the Lord will heal me and that I will go up to the Lord’s temple the day after tomorrow?”'
EXEC add_BibleVerse @BibleId, 112020009, N'Isaiah replied, “This is your sign from the Lord confirming that the Lord will do what he has said. Do you want the shadow to move ahead ten steps or to go back ten steps?”'
EXEC add_BibleVerse @BibleId, 112020010, N'Hezekiah answered, “It is easy for the shadow to lengthen ten steps, but not for it to go back ten steps.”'
EXEC add_BibleVerse @BibleId, 112020011, N'Isaiah the prophet called out to the Lord, and the Lord made the shadow go back ten steps on the stairs of Ahaz.'
EXEC add_BibleVerse @BibleId, 112020012, N'At that time Merodach-Baladan son of Baladan, king of Babylon, sent letters and a gift to Hezekiah, for he had heard that Hezekiah was ill.'
EXEC add_BibleVerse @BibleId, 112020013, N'Hezekiah welcomed them and showed them his whole storehouse, with its silver, gold, spices, and high quality olive oil, as well as his armory and everything in his treasuries. Hezekiah showed them everything in his palace and in his whole kingdom.'
EXEC add_BibleVerse @BibleId, 112020014, N'Isaiah the prophet visited King Hezekiah and asked him, “What did these men say? Where do they come from?” Hezekiah replied, “They come from the distant land of Babylon.”'
EXEC add_BibleVerse @BibleId, 112020015, N'Isaiah asked, “What have they seen in your palace?” Hezekiah replied, “They have seen everything in my palace. I showed them everything in my treasuries.”'
EXEC add_BibleVerse @BibleId, 112020016, N'Isaiah said to Hezekiah, “Listen to the word of the Lord,'
EXEC add_BibleVerse @BibleId, 112020017, N'‘Look, a time is coming when everything in your palace and the things your ancestors have accumulated to this day will be carried away to Babylon; nothing will be left,’ says the Lord.'
EXEC add_BibleVerse @BibleId, 112020018, N'‘Some of your very own descendants whom you father will be taken away and will be made eunuchs in the palace of the king of Babylon.’”'
EXEC add_BibleVerse @BibleId, 112020019, N'Hezekiah said to Isaiah, “The Lord’s word which you have announced is appropriate.” Then he added, “At least there will be peace and stability during my lifetime.”'
EXEC add_BibleVerse @BibleId, 112020020, N'The rest of the events of Hezekiah’s reign and all his accomplishments, including how he built a pool and conduit to bring water into the city, are recorded in the scroll called the Annals of the Kings of Judah.'
EXEC add_BibleVerse @BibleId, 112020021, N'Hezekiah passed away and his son Manasseh replaced him as king.'
EXEC add_BibleVerse @BibleId, 112021001, N'Manasseh was twelve years old when he became king, and he reigned for fifty-five years in Jerusalem. His mother was Hephzibah.'
EXEC add_BibleVerse @BibleId, 112021002, N'He did evil in the sight of the Lord and committed the same horrible sins practiced by the nations whom the Lord drove out from before the Israelites.'
EXEC add_BibleVerse @BibleId, 112021003, N'He rebuilt the high places that his father Hezekiah had destroyed; he set up altars for Baal and made an Asherah pole just like King Ahab of Israel had done. He bowed down to all the stars in the sky and worshiped them.'
EXEC add_BibleVerse @BibleId, 112021004, N'He built altars in the Lord’s temple, about which the Lord had said, “Jerusalem will be my home.”'
EXEC add_BibleVerse @BibleId, 112021005, N'In the two courtyards of the Lord’s temple he built altars for all the stars in the sky.'
EXEC add_BibleVerse @BibleId, 112021006, N'He passed his son through the fire and practiced divination and omen reading. He set up a ritual pit to conjure up underworld spirits, and appointed magicians to supervise it. He did a great amount of evil in the sight of the Lord, provoking him to anger.'
EXEC add_BibleVerse @BibleId, 112021007, N'He put an idol of Asherah he had made in the temple, about which the Lord had said to David and to his son Solomon, “This temple in Jerusalem, which I have chosen out of all the tribes of Israel, will be my permanent home.'
EXEC add_BibleVerse @BibleId, 112021008, N'I will not make Israel again leave the land I gave to their ancestors, provided that they carefully obey all I commanded them, the whole law my servant Moses ordered them to obey.”'
EXEC add_BibleVerse @BibleId, 112021009, N'But they did not obey, and Manasseh misled them so that they sinned more than the nations whom the Lord had destroyed from before the Israelites.'
EXEC add_BibleVerse @BibleId, 112021010, N'So the Lord announced through his servants the prophets:'
EXEC add_BibleVerse @BibleId, 112021011, N'“King Manasseh of Judah has committed horrible sins. He has sinned more than the Amorites before him and has encouraged Judah to sin by worshiping his disgusting idols.'
EXEC add_BibleVerse @BibleId, 112021012, N'So this is what the Lord God of Israel says, ‘I am about to bring disaster on Jerusalem and Judah. The news will reverberate in the ears of those who hear about it.'
EXEC add_BibleVerse @BibleId, 112021013, N'I will destroy Jerusalem the same way I did Samaria and the dynasty of Ahab. I will wipe Jerusalem clean, just as one wipes a plate on both sides.'
EXEC add_BibleVerse @BibleId, 112021014, N'I will abandon this last remaining tribe among my people and hand them over to their enemies; they will be plundered and robbed by all their enemies,'
EXEC add_BibleVerse @BibleId, 112021015, N'because they have done evil in my sight and have angered me from the time their ancestors left Egypt right up to this very day!’”'
EXEC add_BibleVerse @BibleId, 112021016, N'Furthermore Manasseh killed so many innocent people, he stained Jerusalem with their blood from end to end, in addition to encouraging Judah to sin by doing evil in the sight of the Lord.'
EXEC add_BibleVerse @BibleId, 112021017, N'The rest of the events of Manasseh’s reign and all his accomplishments, as well as the sinful acts he committed, are recorded in the scroll called the Annals of the Kings of Judah.'
EXEC add_BibleVerse @BibleId, 112021018, N'Manasseh passed away and was buried in his palace garden, the garden of Uzzah, and his son Amon replaced him as king.'
EXEC add_BibleVerse @BibleId, 112021019, N'Amon was twenty-two years old when he became king, and he reigned for two years in Jerusalem. His mother was Meshullemeth, the daughter of Haruz, from Jotbah.'
EXEC add_BibleVerse @BibleId, 112021020, N'He did evil in the sight of the Lord, just like his father Manasseh had done.'
EXEC add_BibleVerse @BibleId, 112021021, N'He followed in the footsteps of his father and worshiped and bowed down to the disgusting idols which his father had worshiped.'
EXEC add_BibleVerse @BibleId, 112021022, N'He abandoned the Lord God of his ancestors and did not follow the Lord’s instructions.'
EXEC add_BibleVerse @BibleId, 112021023, N'Amon’s servants conspired against him and killed the king in his palace.'
EXEC add_BibleVerse @BibleId, 112021024, N'The people of the land executed all those who had conspired against King Amon, and they made his son Josiah king in his place.'
EXEC add_BibleVerse @BibleId, 112021025, N'The rest of Amon’s accomplishments are recorded in the scroll called the Annals of the Kings of Judah.'
EXEC add_BibleVerse @BibleId, 112021026, N'He was buried in his tomb in the garden of Uzzah, and his son Josiah replaced him as king.'
EXEC add_BibleVerse @BibleId, 112022001, N'Josiah was eight years old when he became king, and he reigned for thirty-one years in Jerusalem. His mother was Jedidah, daughter of Adaiah, from Bozkath.'
EXEC add_BibleVerse @BibleId, 112022002, N'He did what the Lord approved and followed in his ancestor David’s footsteps; he did not deviate to the right or the left.'
EXEC add_BibleVerse @BibleId, 112022003, N'In the eighteenth year of King Josiah’s reign, the king sent the scribe Shaphan son of Azaliah, son of Meshullam, to the Lord’s temple with these orders:'
EXEC add_BibleVerse @BibleId, 112022004, N'“Go up to Hilkiah the high priest and have him melt down the silver that has been brought by the people to the Lord’s temple and has been collected by the guards at the door.'
EXEC add_BibleVerse @BibleId, 112022005, N'Have them hand it over to the construction foremen assigned to the Lord’s temple. They in turn should pay the temple workers to repair it,'
EXEC add_BibleVerse @BibleId, 112022006, N'including craftsmen, builders, and masons, and should buy wood and chiseled stone for the repair work.'
EXEC add_BibleVerse @BibleId, 112022007, N'Do not audit the foremen who disburse the silver, for they are honest.”'
EXEC add_BibleVerse @BibleId, 112022008, N'Hilkiah the high priest informed Shaphan the scribe, “I found the law scroll in the Lord’s temple.” Hilkiah gave the scroll to Shaphan and he read it.'
EXEC add_BibleVerse @BibleId, 112022009, N'Shaphan the scribe went to the king and reported, “Your servants melted down the silver in the temple and handed it over to the construction foremen assigned to the Lord’s temple.”'
EXEC add_BibleVerse @BibleId, 112022010, N'Then Shaphan the scribe told the king, “Hilkiah the priest has given me a scroll.” Shaphan read it out loud before the king.'
EXEC add_BibleVerse @BibleId, 112022011, N'When the king heard the words of the law scroll, he tore his clothes.'
EXEC add_BibleVerse @BibleId, 112022012, N'The king ordered Hilkiah the priest, Ahikam son of Shaphan, Acbor son of Micaiah, Shaphan the scribe, and Asaiah the king’s servant,'
EXEC add_BibleVerse @BibleId, 112022013, N'“Go, seek an oracle from the Lord for me and the people – for all Judah. Find out about the words of this scroll that has been discovered. For the Lord’s fury has been ignited against us, because our ancestors have not obeyed the words of this scroll by doing all that it instructs us to do.”'
EXEC add_BibleVerse @BibleId, 112022014, N'So Hilkiah the priest, Ahikam, Acbor, Shaphan, and Asaiah went to Huldah the prophetess, the wife of Shullam son of Tikvah, the son of Harhas, the supervisor of the wardrobe. (She lived in Jerusalem in the Mishneh district.) They stated their business,'
EXEC add_BibleVerse @BibleId, 112022015, N'and she said to them: “This is what the Lord God of Israel says: ‘Say this to the man who sent you to me:'
EXEC add_BibleVerse @BibleId, 112022016, N'“This is what the Lord says: ‘I am about to bring disaster on this place and its residents, the details of which are recorded in the scroll which the king of Judah has read.'
EXEC add_BibleVerse @BibleId, 112022017, N'This will happen because they have abandoned me and offered sacrifices to other gods, angering me with all the idols they have made. My anger will ignite against this place and will not be extinguished!’”'
EXEC add_BibleVerse @BibleId, 112022018, N'Say this to the king of Judah, who sent you to seek an oracle from the Lord: “This is what the Lord God of Israel says concerning the words you have heard:'
EXEC add_BibleVerse @BibleId, 112022019, N'‘You displayed a sensitive spirit and humbled yourself before the Lord when you heard how I intended to make this place and its residents into an appalling example of an accursed people. You tore your clothes and wept before me, and I have heard you,’ says the Lord.'
EXEC add_BibleVerse @BibleId, 112022020, N'‘Therefore I will allow you to die and be buried in peace. You will not have to witness all the disaster I will bring on this place.’”’” Then they reported back to the king.'
EXEC add_BibleVerse @BibleId, 112023001, N'The king summoned all the leaders of Judah and Jerusalem.'
EXEC add_BibleVerse @BibleId, 112023002, N'The king went up to the Lord’s temple, accompanied by all the people of Judah, all the residents of Jerusalem, the priests, and the prophets. All the people were there, from the youngest to the oldest. He read aloud all the words of the scroll of the covenant that had been discovered in the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 112023003, N'The king stood by the pillar and renewed the covenant before the Lord, agreeing to follow the Lord and to obey his commandments, laws, and rules with all his heart and being, by carrying out the terms of this covenant recorded on this scroll. All the people agreed to keep the covenant.'
EXEC add_BibleVerse @BibleId, 112023004, N'The king ordered Hilkiah the high priest, the high-ranking priests, and the guards to bring out of the Lord’s temple all the items that were used in the worship of Baal, Asherah, and all the stars of the sky. The king burned them outside of Jerusalem in the terraces of Kidron, and carried their ashes to Bethel.'
EXEC add_BibleVerse @BibleId, 112023005, N'He eliminated the pagan priests whom the kings of Judah had appointed to offer sacrifices on the high places in the cities of Judah and in the area right around Jerusalem. (They offered sacrifices to Baal, the sun god, the moon god, the constellations, and all the stars in the sky.)'
EXEC add_BibleVerse @BibleId, 112023006, N'He removed the Asherah pole from the Lord’s temple and took it outside Jerusalem to the Kidron Valley, where he burned it. He smashed it to dust and then threw the dust in the public graveyard.'
EXEC add_BibleVerse @BibleId, 112023007, N'He tore down the quarters of the male cultic prostitutes in the Lord’s temple, where women were weaving shrines for Asherah.'
EXEC add_BibleVerse @BibleId, 112023008, N'He brought all the priests from the cities of Judah and ruined the high places where the priests had offered sacrifices, from Geba to Beer Sheba. He tore down the high place of the goat idols situated at the entrance of the gate of Joshua, the city official, on the left side of the city gate.'
EXEC add_BibleVerse @BibleId, 112023009, N'(Now the priests of the high places did not go up to the altar of the Lord in Jerusalem, but they did eat unleavened cakes among their fellow priests.)'
EXEC add_BibleVerse @BibleId, 112023010, N'The king ruined Topheth in the Valley of Ben Hinnom so that no one could pass his son or his daughter through the fire to Molech.'
EXEC add_BibleVerse @BibleId, 112023011, N'He removed from the entrance to the Lord’s temple the statues of horses that the kings of Judah had placed there in honor of the sun god. (They were kept near the room of Nathan Melech the eunuch, which was situated among the courtyards.) He burned up the chariots devoted to the sun god.'
EXEC add_BibleVerse @BibleId, 112023012, N'The king tore down the altars the kings of Judah had set up on the roof of Ahaz’s upper room, as well as the altars Manasseh had set up in the two courtyards of the Lord’s temple. He crushed them up and threw the dust in the Kidron Valley.'
EXEC add_BibleVerse @BibleId, 112023013, N'The king ruined the high places east of Jerusalem, south of the Mount of Destruction, that King Solomon of Israel had built for the detestable Sidonian goddess Astarte, the detestable Moabite god Chemosh, and the horrible Ammonite god Milcom.'
EXEC add_BibleVerse @BibleId, 112023014, N'He smashed the sacred pillars to bits, cut down the Asherah pole, and filled those shrines with human bones.'
EXEC add_BibleVerse @BibleId, 112023015, N'He also tore down the altar in Bethel at the high place made by Jeroboam son of Nebat, who encouraged Israel to sin. He burned all the combustible items at that high place and crushed them to dust; including the Asherah pole.'
EXEC add_BibleVerse @BibleId, 112023016, N'When Josiah turned around, he saw the tombs there on the hill. So he ordered the bones from the tombs to be brought; he burned them on the altar and defiled it. This fulfilled the Lord’s announcement made by the prophet while Jeroboam stood by the altar during a festival. King Josiah turned and saw the grave of the prophet who had foretold this.'
EXEC add_BibleVerse @BibleId, 112023017, N'He asked, “What is this grave marker I see?” The men from the city replied, “It’s the grave of the prophet who came from Judah and foretold these very things you have done to the altar of Bethel.”'
EXEC add_BibleVerse @BibleId, 112023018, N'The king said, “Leave it alone! No one must touch his bones.” So they left his bones undisturbed, as well as the bones of the Israelite prophet buried beside him.'
EXEC add_BibleVerse @BibleId, 112023019, N'Josiah also removed all the shrines on the high places in the cities of Samaria. The kings of Israel had made them and angered the Lord. He did to them what he had done to the high place in Bethel.'
EXEC add_BibleVerse @BibleId, 112023020, N'He sacrificed all the priests of the high places on the altars located there, and burned human bones on them. Then he returned to Jerusalem.'
EXEC add_BibleVerse @BibleId, 112023021, N'The king ordered all the people, “Observe the Passover of the Lord your God, as prescribed in this scroll of the covenant.”'
EXEC add_BibleVerse @BibleId, 112023022, N'He issued this edict because a Passover like this had not been observed since the days of the judges; it was neglected for the entire period of the kings of Israel and Judah.'
EXEC add_BibleVerse @BibleId, 112023023, N'But in the eighteenth year of King Josiah’s reign, such a Passover of the Lord was observed in Jerusalem.'
EXEC add_BibleVerse @BibleId, 112023024, N'Josiah also got rid of the ritual pits used to conjure up spirits, the magicians, personal idols, disgusting images, and all the detestable idols that had appeared in the land of Judah and in Jerusalem. In this way he carried out the terms of the law recorded on the scroll that Hilkiah the priest had discovered in the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 112023025, N'No king before or after repented before the Lord as he did, with his whole heart, soul, and being in accordance with the whole law of Moses.'
EXEC add_BibleVerse @BibleId, 112023026, N'Yet the Lord’s great anger against Judah did not subside; he was still infuriated by all the things Manasseh had done.'
EXEC add_BibleVerse @BibleId, 112023027, N'The Lord announced, “I will also spurn Judah, just as I spurned Israel. I will reject this city that I chose – both Jerusalem and the temple, about which I said, “I will live there.”'
EXEC add_BibleVerse @BibleId, 112023028, N'The rest of the events of Josiah’s reign and all his accomplishments are recorded in the scroll called the Annals of the Kings of Judah.'
EXEC add_BibleVerse @BibleId, 112023029, N'During Josiah’s reign Pharaoh Necho king of Egypt marched toward the Euphrates River to help the king of Assyria. King Josiah marched out to fight him, but Necho killed him at Megiddo when he saw him.'
EXEC add_BibleVerse @BibleId, 112023030, N'His servants transported his dead body from Megiddo in a chariot and brought it to Jerusalem, where they buried him in his tomb. The people of the land took Josiah’s son Jehoahaz, poured olive oil on his head, and made him king in his father’s place.'
EXEC add_BibleVerse @BibleId, 112023031, N'Jehoahaz was twenty-three years old when he became king, and he reigned three months in Jerusalem. His mother was Hamutal the daughter of Jeremiah, from Libnah.'
EXEC add_BibleVerse @BibleId, 112023032, N'He did evil in the sight of the Lord as his ancestors had done.'
EXEC add_BibleVerse @BibleId, 112023033, N'Pharaoh Necho imprisoned him in Riblah in the land of Hamath and prevented him from ruling in Jerusalem. He imposed on the land a special tax of one hundred talents of silver and a talent of gold.'
EXEC add_BibleVerse @BibleId, 112023034, N'Pharaoh Necho made Josiah’s son Eliakim king in Josiah’s place, and changed his name to Jehoiakim. He took Jehoahaz to Egypt, where he died.'
EXEC add_BibleVerse @BibleId, 112023035, N'Jehoiakim paid Pharaoh the required amount of silver and gold, but to meet Pharaoh’s demands Jehoiakim had to tax the land. He collected an assessed amount from each man among the people of the land in order to pay Pharaoh Necho.'
EXEC add_BibleVerse @BibleId, 112023036, N'Jehoiakim was twenty-five years old when he became king, and he reigned for eleven years in Jerusalem. His mother was Zebidah the daughter of Pedaiah, from Rumah.'
EXEC add_BibleVerse @BibleId, 112023037, N'He did evil in the sight of the Lord as his ancestors had done.'
EXEC add_BibleVerse @BibleId, 112024001, N'During Jehoiakim’s reign, King Nebuchadnezzar of Babylon attacked. Jehoiakim was his subject for three years, but then he rebelled against him.'
EXEC add_BibleVerse @BibleId, 112024002, N'The Lord sent against him Babylonian, Syrian, Moabite, and Ammonite raiding bands; he sent them to destroy Judah, as he had warned he would do through his servants the prophets.'
EXEC add_BibleVerse @BibleId, 112024003, N'Just as the Lord had announced, he rejected Judah because of all the sins which Manasseh had committed.'
EXEC add_BibleVerse @BibleId, 112024004, N'Because he killed innocent people and stained Jerusalem with their blood, the Lord was unwilling to forgive them.'
EXEC add_BibleVerse @BibleId, 112024005, N'The rest of the events of Jehoiakim’s reign and all his accomplishments, are recorded in the scroll called the Annals of the Kings of Judah.'
EXEC add_BibleVerse @BibleId, 112024006, N'He passed away and his son Jehoiachin replaced him as king.'
EXEC add_BibleVerse @BibleId, 112024007, N'The king of Egypt did not march out from his land again, for the king of Babylon conquered all the territory that the king of Egypt had formerly controlled between the Brook of Egypt and the Euphrates River.'
EXEC add_BibleVerse @BibleId, 112024008, N'Jehoiachin was eighteen years old when he became king, and he reigned three months in Jerusalem. His mother was Nehushta the daughter of Elnathan, from Jerusalem.'
EXEC add_BibleVerse @BibleId, 112024009, N'He did evil in the sight of the Lord as his ancestors had done.'
EXEC add_BibleVerse @BibleId, 112024010, N'At that time the generals of King Nebuchadnezzar of Babylon marched to Jerusalem and besieged the city.'
EXEC add_BibleVerse @BibleId, 112024011, N'King Nebuchadnezzar of Babylon came to the city while his generals were besieging it.'
EXEC add_BibleVerse @BibleId, 112024012, N'King Jehoiachin of Judah, along with his mother, his servants, his officials, and his eunuchs surrendered to the king of Babylon. The king of Babylon, in the eighth year of his reign, took Jehoiachin prisoner.'
EXEC add_BibleVerse @BibleId, 112024013, N'Nebuchadnezzar took from there all the riches in the treasuries of the Lord’s temple and of the royal palace. He removed all the gold items which King Solomon of Israel had made for the Lord’s temple, just as the Lord had warned.'
EXEC add_BibleVerse @BibleId, 112024014, N'He deported all the residents of Jerusalem, including all the officials and all the soldiers (10,000 people in all). This included all the craftsmen and those who worked with metal. No one was left except for the poorest among the people of the land.'
EXEC add_BibleVerse @BibleId, 112024015, N'He deported Jehoiachin from Jerusalem to Babylon, along with the king’s mother and wives, his eunuchs, and the high-ranking officials of the land.'
EXEC add_BibleVerse @BibleId, 112024016, N'The king of Babylon deported to Babylon all the soldiers (there were 7,000), as well as 1,000 craftsmen and metal workers. This included all the best warriors.'
EXEC add_BibleVerse @BibleId, 112024017, N'The king of Babylon made Mattaniah, Jehoiachin’s uncle, king in Jehoiachin’s place. He renamed him Zedekiah.'
EXEC add_BibleVerse @BibleId, 112024018, N'Zedekiah was twenty-one years old when he became king, and he ruled for eleven years in Jerusalem. His mother was Hamutal, the daughter of Jeremiah, from Libnah.'
EXEC add_BibleVerse @BibleId, 112024019, N'He did evil in the sight of the Lord, as Jehoiakim had done.'
EXEC add_BibleVerse @BibleId, 112024020, N'What follows is a record of what happened to Jerusalem and Judah because of the Lord’s anger; he finally threw them out of his presence. Zedekiah rebelled against the king of Babylon.'
EXEC add_BibleVerse @BibleId, 112025001, N'So King Nebuchadnezzar of Babylon came against Jerusalem with his whole army and set up camp outside it. They built siege ramps all around it. He arrived on the tenth day of the tenth month in the ninth year of Zedekiah’s reign.'
EXEC add_BibleVerse @BibleId, 112025002, N'The city remained under siege until King Zedekiah’s eleventh year.'
EXEC add_BibleVerse @BibleId, 112025003, N'By the ninth day of the fourth month the famine in the city was so severe the residents had no food.'
EXEC add_BibleVerse @BibleId, 112025004, N'The enemy broke through the city walls, and all the soldiers tried to escape. They left the city during the night. They went through the gate between the two walls that is near the king’s garden. (The Babylonians were all around the city.) Then they headed for the Jordan Valley.'
EXEC add_BibleVerse @BibleId, 112025005, N'But the Babylonian army chased after the king. They caught up with him in the plains of Jericho, and his entire army deserted him.'
EXEC add_BibleVerse @BibleId, 112025006, N'They captured the king and brought him up to the king of Babylon at Riblah, where he passed sentence on him.'
EXEC add_BibleVerse @BibleId, 112025007, N'Zedekiah’s sons were executed while Zedekiah was forced to watch. The king of Babylon then had Zedekiah’s eyes put out, bound him in bronze chains, and carried him off to Babylon.'
EXEC add_BibleVerse @BibleId, 112025008, N'On the seventh day of the fifth month, in the nineteenth year of King Nebuchadnezzar of Babylon, Nebuzaradan, the captain of the royal guard who served the king of Babylon, arrived in Jerusalem.'
EXEC add_BibleVerse @BibleId, 112025009, N'He burned down the Lord’s temple, the royal palace, and all the houses in Jerusalem, including every large house.'
EXEC add_BibleVerse @BibleId, 112025010, N'The whole Babylonian army that came with the captain of the royal guard tore down the walls that surrounded Jerusalem.'
EXEC add_BibleVerse @BibleId, 112025011, N'Nebuzaradan, the captain of the royal guard, deported the rest of the people who were left in the city, those who had deserted to the king of Babylon, and the rest of the craftsmen.'
EXEC add_BibleVerse @BibleId, 112025012, N'But he left behind some of the poor of the land and gave them fields and vineyards.'
EXEC add_BibleVerse @BibleId, 112025013, N'The Babylonians broke the two bronze pillars in the Lord’s temple, as well as the movable stands and the big bronze basin called the “The Sea.” They took the bronze to Babylon.'
EXEC add_BibleVerse @BibleId, 112025014, N'They also took the pots, shovels, trimming shears, pans, and all the bronze utensils used by the priests.'
EXEC add_BibleVerse @BibleId, 112025015, N'The captain of the royal guard took the golden and silver censers and basins.'
EXEC add_BibleVerse @BibleId, 112025016, N'The bronze of the items that King Solomon made for the Lord’s temple – including the two pillars, the big bronze basin called “The Sea,” the twelve bronze bulls under “The Sea,” and the movable stands – was too heavy to be weighed.'
EXEC add_BibleVerse @BibleId, 112025017, N'Each of the pillars was about twenty-seven feet high. The bronze top of one pillar was about four and a half feet high and had bronze latticework and pomegranate shaped ornaments all around it. The second pillar with its latticework was like it.'
EXEC add_BibleVerse @BibleId, 112025018, N'The captain of the royal guard took Seraiah the chief priest and Zephaniah, the priest who was second in rank, and the three doorkeepers.'
EXEC add_BibleVerse @BibleId, 112025019, N'From the city he took a eunuch who was in charge of the soldiers, five of the king’s advisers who were discovered in the city, an official army secretary who drafted citizens for military service, and sixty citizens from the people of the land who were discovered in the city.'
EXEC add_BibleVerse @BibleId, 112025020, N'Nebuzaradan, captain of the royal guard, took them and brought them to the king of Babylon at Riblah.'
EXEC add_BibleVerse @BibleId, 112025021, N'The king of Babylon ordered them to be executed at Riblah in the territory of Hamath. So Judah was deported from its land.'
EXEC add_BibleVerse @BibleId, 112025022, N'Now King Nebuchadnezzar of Babylon appointed Gedaliah son of Ahikam, son of Shaphan, as governor over the people whom he allowed to remain in the land of Judah.'
EXEC add_BibleVerse @BibleId, 112025023, N'All of the officers of the Judahite army and their troops heard that the king of Babylon had appointed Gedaliah to govern. So they came to Gedaliah at Mizpah. The officers who came were Ishmael son of Nethaniah, Johanan son of Kareah, Seraiah son of Tanhumeth the Netophathite, and Jaazaniah son of the Maacathite.'
EXEC add_BibleVerse @BibleId, 112025024, N'Gedaliah took an oath so as to give them and their troops some assurance of safety. He said, “You don’t need to be afraid to submit to the Babylonian officials. Settle down in the land and submit to the king of Babylon. Then things will go well for you.”'
EXEC add_BibleVerse @BibleId, 112025025, N'But in the seventh month Ishmael son of Nethaniah, son of Elishama, who was a member of the royal family, came with ten of his men and murdered Gedaliah, as well as the Judeans and Babylonians who were with him at Mizpah.'
EXEC add_BibleVerse @BibleId, 112025026, N'Then all the people, from the youngest to the oldest, as well as the army officers, left for Egypt, because they were afraid of what the Babylonians might do.'
EXEC add_BibleVerse @BibleId, 112025027, N'In the thirty-seventh year of the exile of King Jehoiachin of Judah, on the twenty-seventh day of the twelfth month, King Evil-Merodach of Babylon, in the first year of his reign, pardoned King Jehoiachin of Judah and released him from prison.'
EXEC add_BibleVerse @BibleId, 112025028, N'He spoke kindly to him and gave him a more prestigious position than the other kings who were with him in Babylon.'
EXEC add_BibleVerse @BibleId, 112025029, N'Jehoiachin took off his prison clothes and ate daily in the king’s presence for the rest of his life.'
EXEC add_BibleVerse @BibleId, 112025030, N'He was given daily provisions by the king for the rest of his life until the day he died.'
EXEC add_BibleVerse @BibleId, 113001001, N'Adam, Seth, Enosh,'
EXEC add_BibleVerse @BibleId, 113001002, N'Kenan, Mahalalel, Jered,'
EXEC add_BibleVerse @BibleId, 113001003, N'Enoch, Methuselah, Lamech,'
EXEC add_BibleVerse @BibleId, 113001004, N'Noah, Shem, Ham, and Japheth.'
EXEC add_BibleVerse @BibleId, 113001005, N'The sons of Japheth: Gomer, Magog, Madai, Javan, Tubal, Meshech, and Tiras.'
EXEC add_BibleVerse @BibleId, 113001006, N'The sons of Gomer: Ashkenaz, Riphath, and Togarmah.'
EXEC add_BibleVerse @BibleId, 113001007, N'The sons of Javan: Elishah, Tarshish, the Kittites, and the Rodanites.'
EXEC add_BibleVerse @BibleId, 113001008, N'The sons of Ham: Cush, Mizraim, Put, and Canaan.'
EXEC add_BibleVerse @BibleId, 113001009, N'The sons of Cush: Seba, Havilah, Sabta, Raamah, and Sabteca. The sons of Raamah: Sheba and Dedan.'
EXEC add_BibleVerse @BibleId, 113001010, N'Cush was the father of Nimrod, who established himself as a mighty warrior on earth.'
EXEC add_BibleVerse @BibleId, 113001011, N'Mizraim was the father of the Ludites, Anamites, Lehabites, Naphtuhites,'
EXEC add_BibleVerse @BibleId, 113001012, N'Pathrusites, Casluhites (from whom the Philistines descended ), and the Caphtorites.'
EXEC add_BibleVerse @BibleId, 113001013, N'Canaan was the father of Sidon – his firstborn – and Heth,'
EXEC add_BibleVerse @BibleId, 113001014, N'as well as the Jebusites, Amorites, Girgashites,'
EXEC add_BibleVerse @BibleId, 113001015, N'Hivites, Arkites, Sinites,'
EXEC add_BibleVerse @BibleId, 113001016, N'Arvadites, Zemarites, and Hamathites.'
EXEC add_BibleVerse @BibleId, 113001017, N'The sons of Shem: Elam, Asshur, Arphaxad, Lud, and Aram. The sons of Aram: Uz, Hul, Gether, and Meshech.'
EXEC add_BibleVerse @BibleId, 113001018, N'Arphaxad was the father of Shelah, and Shelah was the father of Eber.'
EXEC add_BibleVerse @BibleId, 113001019, N'Two sons were born to Eber: the first was named Peleg, for during his lifetime the earth was divided; his brother’s name was Joktan.'
EXEC add_BibleVerse @BibleId, 113001020, N'Joktan was the father of Almodad, Sheleph, Hazarmaveth, Jerah,'
EXEC add_BibleVerse @BibleId, 113001021, N'Hadoram, Uzal, Diklah,'
EXEC add_BibleVerse @BibleId, 113001022, N'Ebal, Abimael, Sheba,'
EXEC add_BibleVerse @BibleId, 113001023, N'Ophir, Havilah, and Jobab. All these were the sons of Joktan.'
EXEC add_BibleVerse @BibleId, 113001024, N'Shem, Arphaxad, Shelah,'
EXEC add_BibleVerse @BibleId, 113001025, N'Eber, Peleg, Reu,'
EXEC add_BibleVerse @BibleId, 113001026, N'Serug, Nahor, Terah,'
EXEC add_BibleVerse @BibleId, 113001027, N'Abram (that is, Abraham).'
EXEC add_BibleVerse @BibleId, 113001028, N'The sons of Abraham: Isaac and Ishmael.'
EXEC add_BibleVerse @BibleId, 113001029, N'These were their descendants: Ishmael’s firstborn son was Nebaioth; the others were Kedar, Adbeel, Mibsam,'
EXEC add_BibleVerse @BibleId, 113001030, N'Mishma, Dumah, Massa, Hadad, Tema,'
EXEC add_BibleVerse @BibleId, 113001031, N'Jetur, Naphish, and Kedemah. These were the sons of Ishmael.'
EXEC add_BibleVerse @BibleId, 113001032, N'The sons to whom Keturah, Abraham’s concubine, gave birth: Zimran, Jokshan, Medan, Midian, Ishbak, Shuah. The sons of Jokshan: Sheba and Dedan.'
EXEC add_BibleVerse @BibleId, 113001033, N'The sons of Midian: Ephah, Epher, Hanoch, Abida, and Eldaah. All these were the sons of Keturah.'
EXEC add_BibleVerse @BibleId, 113001034, N'Abraham was the father of Isaac. The sons of Isaac: Esau and Israel.'
EXEC add_BibleVerse @BibleId, 113001035, N'The sons of Esau: Eliphaz, Reuel, Jeush, Jalam, and Korah.'
EXEC add_BibleVerse @BibleId, 113001036, N'The sons of Eliphaz: Teman, Omar, Zephi, Gatam, Kenaz, and (by Timna) Amalek.'
EXEC add_BibleVerse @BibleId, 113001037, N'The sons of Reuel: Nahath, Zerah, Shammah, and Mizzah.'
EXEC add_BibleVerse @BibleId, 113001038, N'The sons of Seir: Lotan, Shobal, Zibeon, Anah, Dishon, Ezer, and Dishan.'
EXEC add_BibleVerse @BibleId, 113001039, N'The sons of Lotan: Hori and Homam. (Timna was Lotan’s sister.)'
EXEC add_BibleVerse @BibleId, 113001040, N'The sons of Shobal: Alyan, Manahath, Ebal, Shephi, and Onam. The sons of Zibeon: Aiah and Anah.'
EXEC add_BibleVerse @BibleId, 113001041, N'The son of Anah: Dishon. The sons of Dishon: Hamran, Eshban, Ithran, and Keran.'
EXEC add_BibleVerse @BibleId, 113001042, N'The sons of Ezer: Bilhan, Zaavan, Jaakan. The sons of Dishan: Uz and Aran.'
EXEC add_BibleVerse @BibleId, 113001043, N'These were the kings who reigned in the land of Edom before any king ruled over the Israelites: Bela son of Beor; the name of his city was Dinhabah.'
EXEC add_BibleVerse @BibleId, 113001044, N'When Bela died, Jobab son of Zerah from Bozrah, succeeded him.'
EXEC add_BibleVerse @BibleId, 113001045, N'When Jobab died, Husham from the land of the Temanites succeeded him.'
EXEC add_BibleVerse @BibleId, 113001046, N'When Husham died, Hadad son of Bedad succeeded him. He struck down the Midianites in the plains of Moab; the name of his city was Avith.'
EXEC add_BibleVerse @BibleId, 113001047, N'When Hadad died, Samlah from Masrekah succeeded him.'
EXEC add_BibleVerse @BibleId, 113001048, N'When Samlah died, Shaul from Rehoboth on the river succeeded him.'
EXEC add_BibleVerse @BibleId, 113001049, N'When Shaul died, Baal-Hanan son of Achbor succeeded him.'
EXEC add_BibleVerse @BibleId, 113001050, N'When Baal-Hanan died, Hadad succeeded him; the name of his city was Pai. His wife was Mehetabel, daughter of Matred, daughter of Me-Zahab.'
EXEC add_BibleVerse @BibleId, 113001051, N'Hadad died. The tribal chiefs of Edom were: Timna, Alvah, Jetheth,'
EXEC add_BibleVerse @BibleId, 113001052, N'Oholibamah, Elah, Pinon,'
EXEC add_BibleVerse @BibleId, 113001053, N'Kenaz, Teman, Mibzar,'
EXEC add_BibleVerse @BibleId, 113001054, N'Magdiel, Iram. These were the tribal chiefs of Edom.'
EXEC add_BibleVerse @BibleId, 113002001, N'These were the sons of Israel: Reuben, Simeon, Levi, and Judah; Issachar and Zebulun;'
EXEC add_BibleVerse @BibleId, 113002002, N'Dan, Joseph, and Benjamin; Naphtali, Gad, and Asher.'
EXEC add_BibleVerse @BibleId, 113002003, N'The sons of Judah: Er, Onan, and Shelah. These three were born to him by Bathshua, a Canaanite woman. Er, Judah’s firstborn, displeased the Lord, so the Lord killed him.'
EXEC add_BibleVerse @BibleId, 113002004, N'Tamar, Judah’s daughter-in-law, bore to him Perez and Zerah. Judah had five sons in all.'
EXEC add_BibleVerse @BibleId, 113002005, N'The sons of Perez: Hezron and Hamul.'
EXEC add_BibleVerse @BibleId, 113002006, N'The sons of Zerah: Zimri, Ethan, Heman, Kalkol, Dara – five in all.'
EXEC add_BibleVerse @BibleId, 113002007, N'The son of Carmi: Achan, who brought the disaster on Israel when he stole what was devoted to God.'
EXEC add_BibleVerse @BibleId, 113002008, N'The son of Ethan: Azariah.'
EXEC add_BibleVerse @BibleId, 113002009, N'The sons born to Hezron: Jerahmeel, Ram, and Caleb.'
EXEC add_BibleVerse @BibleId, 113002010, N'Ram was the father of Amminadab, and Amminadab was the father of Nahshon, the tribal chief of Judah.'
EXEC add_BibleVerse @BibleId, 113002011, N'Nahshon was the father of Salma, and Salma was the father of Boaz.'
EXEC add_BibleVerse @BibleId, 113002012, N'Boaz was the father of Obed, and Obed was the father of Jesse.'
EXEC add_BibleVerse @BibleId, 113002013, N'Jesse was the father of Eliab, his firstborn; Abinadab was born second, Shimea third,'
EXEC add_BibleVerse @BibleId, 113002014, N'Nethanel fourth, Raddai fifth,'
EXEC add_BibleVerse @BibleId, 113002015, N'Ozem sixth, David seventh.'
EXEC add_BibleVerse @BibleId, 113002016, N'Their sisters were Zeruiah and Abigail. Zeruiah’s three sons were Abshai, Joab, and Asahel.'
EXEC add_BibleVerse @BibleId, 113002017, N'Abigail bore Amasa, whose father was Jether the Ishmaelite.'
EXEC add_BibleVerse @BibleId, 113002018, N'Caleb son of Hezron fathered sons by his wife Azubah (also known as Jerioth). Her sons were Jesher, Shobab, and Ardon.'
EXEC add_BibleVerse @BibleId, 113002019, N'When Azubah died, Caleb married Ephrath, who bore him Hur.'
EXEC add_BibleVerse @BibleId, 113002020, N'Hur was the father of Uri, and Uri was the father of Bezalel.'
EXEC add_BibleVerse @BibleId, 113002021, N'Later Hezron had sexual relations with the daughter of Makir, the father of Gilead. (He had married her when he was sixty years old.) She bore him Segub.'
EXEC add_BibleVerse @BibleId, 113002022, N'Segub was the father of Jair, who owned twenty-three cities in the land of Gilead.'
EXEC add_BibleVerse @BibleId, 113002023, N'(Geshur and Aram captured the towns of Jair, along with Kenath and its sixty surrounding towns.) All these were descendants of Makir, the father of Gilead.'
EXEC add_BibleVerse @BibleId, 113002024, N'After Hezron’s death, Caleb had sexual relations with Ephrath, his father Hezron’s widow, and she bore to him Ashhur the father of Tekoa.'
EXEC add_BibleVerse @BibleId, 113002025, N'The sons of Jerahmeel, Hezron’s firstborn, were Ram, the firstborn, Bunah, Oren, Ozem, and Ahijah.'
EXEC add_BibleVerse @BibleId, 113002026, N'Jerahmeel had another wife named Atarah; she was Onam’s mother.'
EXEC add_BibleVerse @BibleId, 113002027, N'The sons of Ram, Jerahmeel’s firstborn, were Maaz, Jamin, and Eker.'
EXEC add_BibleVerse @BibleId, 113002028, N'The sons of Onam were Shammai and Jada. The sons of Shammai: Nadab and Abishur.'
EXEC add_BibleVerse @BibleId, 113002029, N'Abishur’s wife was Abihail, who bore him Ahban and Molid.'
EXEC add_BibleVerse @BibleId, 113002030, N'The sons of Nadab: Seled and Appaim. (Seled died without having sons.)'
EXEC add_BibleVerse @BibleId, 113002031, N'The son of Appaim: Ishi. The son of Ishi: Sheshan. The son of Sheshan: Ahlai.'
EXEC add_BibleVerse @BibleId, 113002032, N'The sons of Jada, Shammai’s brother: Jether and Jonathan. (Jether died without having sons.)'
EXEC add_BibleVerse @BibleId, 113002033, N'The sons of Jonathan: Peleth and Zaza. These were the descendants of Jerahmeel.'
EXEC add_BibleVerse @BibleId, 113002034, N'Sheshan had no sons, only daughters. Sheshan had an Egyptian servant named Jarha.'
EXEC add_BibleVerse @BibleId, 113002035, N'Sheshan gave his daughter to his servant Jarha as a wife; she bore him Attai.'
EXEC add_BibleVerse @BibleId, 113002036, N'Attai was the father of Nathan, and Nathan was the father of Zabad.'
EXEC add_BibleVerse @BibleId, 113002037, N'Zabad was the father of Ephlal, and Ephlal was the father of Obed.'
EXEC add_BibleVerse @BibleId, 113002038, N'Obed was the father of Jehu, and Jehu was the father of Azariah.'
EXEC add_BibleVerse @BibleId, 113002039, N'Azariah was the father of Helez, and Helez was the father of Eleasah.'
EXEC add_BibleVerse @BibleId, 113002040, N'Eleasah was the father of Sismai, and Sismai was the father of Shallum.'
EXEC add_BibleVerse @BibleId, 113002041, N'Shallum was the father of Jekamiah, and Jekamiah was the father of Elishama.'
EXEC add_BibleVerse @BibleId, 113002042, N'The sons of Caleb, Jerahmeel’s brother: His firstborn Mesha, the father of Ziph, and his second son Mareshah, the father of Hebron.'
EXEC add_BibleVerse @BibleId, 113002043, N'The sons of Hebron: Korah, Tappuah, Rekem, and Shema.'
EXEC add_BibleVerse @BibleId, 113002044, N'Shema was the father of Raham, the father of Jorkeam. Rekem was the father of Shammai.'
EXEC add_BibleVerse @BibleId, 113002045, N'Shammai’s son was Maon, who was the father of Beth-Zur.'
EXEC add_BibleVerse @BibleId, 113002046, N'Caleb’s concubine Ephah bore Haran, Moza, and Gazez. Haran was the father of Gazez.'
EXEC add_BibleVerse @BibleId, 113002047, N'The sons of Jahdai: Regem, Jotham, Geshan, Pelet, Ephah, and Shaaph.'
EXEC add_BibleVerse @BibleId, 113002048, N'Caleb’s concubine Maacah bore Sheber and Tirhanah.'
EXEC add_BibleVerse @BibleId, 113002049, N'She also bore Shaaph the father of Madmannah and Sheva the father of Machbenah and Gibea. Caleb’s daughter was Achsah.'
EXEC add_BibleVerse @BibleId, 113002050, N'These were the descendants of Caleb. The sons of Hur, the firstborn of Ephrath: Shobal, the father of Kiriath Jearim,'
EXEC add_BibleVerse @BibleId, 113002051, N'Salma, the father of Bethlehem, Hareph, the father of Beth-Gader.'
EXEC add_BibleVerse @BibleId, 113002052, N'The sons of Shobal, the father of Kiriath Jearim, were Haroeh, half of the Manahathites,'
EXEC add_BibleVerse @BibleId, 113002053, N'the clans of Kiriath Jearim – the Ithrites, Puthites, Shumathites, and Mishraites. (The Zorathites and Eshtaolites descended from these groups.)'
EXEC add_BibleVerse @BibleId, 113002054, N'The sons of Salma: Bethlehem, the Netophathites, Atroth Beth-Joab, half the Manahathites, the Zorites,'
EXEC add_BibleVerse @BibleId, 113002055, N'and the clans of the scribes who lived in Jabez: the Tirathites, Shimeathites, and Sucathites. These are the Kenites who descended from Hammath, the father of Beth-Rechab.'
EXEC add_BibleVerse @BibleId, 113003001, N'These were the sons of David who were born to him in Hebron: The firstborn was Amnon, whose mother was Ahinoam from Jezreel; the second was Daniel, whose mother was Abigail from Carmel;'
EXEC add_BibleVerse @BibleId, 113003002, N'the third was Absalom whose mother was Maacah, daughter of King Talmai of Geshur; the fourth was Adonijah, whose mother was Haggith;'
EXEC add_BibleVerse @BibleId, 113003003, N'the fifth was Shephatiah, whose mother was Abital; the sixth was Ithream, whose mother was Eglah.'
EXEC add_BibleVerse @BibleId, 113003004, N'These six were born to David in Hebron, where he ruled for seven years and six months. He ruled thirty-three years in Jerusalem.'
EXEC add_BibleVerse @BibleId, 113003005, N'These were the sons born to him in Jerusalem: Shimea, Shobab, Nathan, and Solomon – the mother of these four was Bathsheba the daughter of Ammiel.'
EXEC add_BibleVerse @BibleId, 113003006, N'The other nine were Ibhar, Elishua, Elpelet,'
EXEC add_BibleVerse @BibleId, 113003007, N'Nogah, Nepheg, Japhia,'
EXEC add_BibleVerse @BibleId, 113003008, N'Elishama, Eliada, and Eliphelet.'
EXEC add_BibleVerse @BibleId, 113003009, N'These were all the sons of David, not counting the sons of his concubines. Tamar was their sister.'
EXEC add_BibleVerse @BibleId, 113003010, N'Solomon’s son was Rehoboam, followed by Abijah his son, Asa his son, Jehoshaphat his son,'
EXEC add_BibleVerse @BibleId, 113003011, N'Joram his son, Ahaziah his son, Joash his son,'
EXEC add_BibleVerse @BibleId, 113003012, N'Amaziah his son, Azariah his son, Jotham his son,'
EXEC add_BibleVerse @BibleId, 113003013, N'Ahaz his son, Hezekiah his son, Manasseh his son,'
EXEC add_BibleVerse @BibleId, 113003014, N'Amon his son, Josiah his son.'
EXEC add_BibleVerse @BibleId, 113003015, N'The sons of Josiah: Johanan was the firstborn; Jehoiakim was born second; Zedekiah third; and Shallum fourth.'
EXEC add_BibleVerse @BibleId, 113003016, N'The sons of Jehoiakim: his son Jehoiachin and his son Zedekiah.'
EXEC add_BibleVerse @BibleId, 113003017, N'The sons of Jehoiachin the exile: Shealtiel his son,'
EXEC add_BibleVerse @BibleId, 113003018, N'Malkiram, Pedaiah, Shenazzar, Jekamiah, Hoshama, and Nedabiah.'
EXEC add_BibleVerse @BibleId, 113003019, N'The sons of Pedaiah: Zerubbabel and Shimei. The sons of Zerubbabel: Meshullam and Hananiah. Shelomith was their sister.'
EXEC add_BibleVerse @BibleId, 113003020, N'The five others were Hashubah, Ohel, Berechiah, Hasadiah, and Jushab-Hesed.'
EXEC add_BibleVerse @BibleId, 113003021, N'The descendants of Hananiah: Pelatiah, Jeshaiah, the sons of Rephaiah, of Arnan, of Obadiah, and of Shecaniah.'
EXEC add_BibleVerse @BibleId, 113003022, N'The descendants of Shecaniah: Shemaiah and his sons: Hattush, Igal, Bariah, Neariah, and Shaphat – six in all.'
EXEC add_BibleVerse @BibleId, 113003023, N'The sons of Neariah: Elioenai, Hizkiah, and Azrikam – three in all.'
EXEC add_BibleVerse @BibleId, 113003024, N'The sons of Elioenai: Hodaviah, Eliashib, Pelaiah, Akkub, Johanan, Delaiah, and Anani – seven in all.'
EXEC add_BibleVerse @BibleId, 113004001, N'The descendants of Judah: Perez, Hezron, Carmi, Hur, and Shobal.'
EXEC add_BibleVerse @BibleId, 113004002, N'Reaiah the son of Shobal was the father of Jahath, and Jahath was the father of Ahumai and Lahad. These were the clans of the Zorathites.'
EXEC add_BibleVerse @BibleId, 113004003, N'These were the sons of Etam: Jezreel, Ishma, and Idbash. Their sister was Hazzelelponi.'
EXEC add_BibleVerse @BibleId, 113004004, N'Penuel was the father of Gedor, and Ezer was the father of Hushah. These were the descendants of Hur, the firstborn of Ephrathah and the father of Bethlehem.'
EXEC add_BibleVerse @BibleId, 113004005, N'Ashhur the father of Tekoa had two wives, Helah and Naarah.'
EXEC add_BibleVerse @BibleId, 113004006, N'Naarah bore him Ahuzzam, Hepher, Temeni, and Haahashtari. These were the sons of Naarah.'
EXEC add_BibleVerse @BibleId, 113004007, N'The sons of Helah: Zereth, Zohar, Ethnan,'
EXEC add_BibleVerse @BibleId, 113004008, N'and Koz, who was the father of Anub, Hazzobebah, and the clans of Aharhel the son of Harum.'
EXEC add_BibleVerse @BibleId, 113004009, N'Jabez was more respected than his brothers. His mother had named him Jabez, for she said, “I experienced pain when I gave birth to him.”'
EXEC add_BibleVerse @BibleId, 113004010, N'Jabez called out to the God of Israel, “If only you would greatly bless me and expand my territory! May your hand be with me! Keep me from harm so I might not endure pain!” God answered his prayer.'
EXEC add_BibleVerse @BibleId, 113004011, N'Kelub, the brother of Shuhah, was the father of Mehir, who was the father of Eshton.'
EXEC add_BibleVerse @BibleId, 113004012, N'Eshton was the father of Beth-Rapha, Paseah, and Tehinnah, the father of Ir Nahash. These were the men of Recah.'
EXEC add_BibleVerse @BibleId, 113004013, N'The sons of Kenaz: Othniel and Seraiah. The sons of Othniel: Hathath and Meonothai.'
EXEC add_BibleVerse @BibleId, 113004014, N'Meonothai was the father of Ophrah. Seraiah was the father of Joab, the father of those who live in Ge Harashim, who were craftsmen.'
EXEC add_BibleVerse @BibleId, 113004015, N'The sons of Caleb son of Jephunneh: Iru, Elah, and Naam. The son of Elah: Kenaz.'
EXEC add_BibleVerse @BibleId, 113004016, N'The sons of Jehallelel: Ziph, Ziphah, Tiria, and Asarel.'
EXEC add_BibleVerse @BibleId, 113004017, N'The sons of Ezrah: Jether, Mered, Epher, and Jalon. Mered’s wife Bithiah gave birth to Miriam, Shammai, and Ishbah, the father of Eshtemoa.'
EXEC add_BibleVerse @BibleId, 113004018, N'(His Judahite wife gave birth to Jered the father of Gedor, Heber the father of Soco, and Jekuthiel the father of Zanoah.) These were the sons of Pharaoh’s daughter Bithiah, whom Mered married.'
EXEC add_BibleVerse @BibleId, 113004019, N'The sons of Hodiah’s wife, the sister of Naham: the father of Keilah the Garmite, and Eshtemoa the Maacathite.'
EXEC add_BibleVerse @BibleId, 113004020, N'The sons of Shimon: Amnon, Rinnah, Ben-Hanan, and Tilon. The descendants of Ishi: Zoheth and Ben Zoheth.'
EXEC add_BibleVerse @BibleId, 113004021, N'The sons of Shelah son of Judah: Er the father of Lecah, Laadah the father of Mareshah, the clans of the linen workers at Beth-Ashbea,'
EXEC add_BibleVerse @BibleId, 113004022, N'Jokim, the men of Cozeba, and Joash and Saraph, both of whom ruled in Moab and Jashubi Lehem. (This information is from ancient records.)'
EXEC add_BibleVerse @BibleId, 113004023, N'They were the potters who lived in Netaim and Gederah; they lived there and worked for the king.'
EXEC add_BibleVerse @BibleId, 113004024, N'The descendants of Simeon: Nemuel, Jamin, Jarib, Zerah, Shaul,'
EXEC add_BibleVerse @BibleId, 113004025, N'his son Shallum, his son Mibsam, and his son Mishma.'
EXEC add_BibleVerse @BibleId, 113004026, N'The descendants of Mishma: His son Hammuel, his son Zaccur, and his son Shimei.'
EXEC add_BibleVerse @BibleId, 113004027, N'Shimei had sixteen sons and six daughters. But his brothers did not have many sons, so their whole clan was not as numerous as the sons of Judah.'
EXEC add_BibleVerse @BibleId, 113004028, N'They lived in Beer Sheba, Moladah, Hazar Shual,'
EXEC add_BibleVerse @BibleId, 113004029, N'Bilhah, Ezem, Tolad,'
EXEC add_BibleVerse @BibleId, 113004030, N'Bethuel, Hormah, Ziklag,'
EXEC add_BibleVerse @BibleId, 113004031, N'Beth Marcaboth, Hazar Susim, Beth Biri, and Shaaraim. These were their towns until the reign of David.'
EXEC add_BibleVerse @BibleId, 113004032, N'Their settlements also included Etam, Ain, Rimmon, Tochen, and Ashan – five towns.'
EXEC add_BibleVerse @BibleId, 113004033, N'They also lived in all the settlements that surrounded these towns as far as Baal. These were their settlements; they kept genealogical records.'
EXEC add_BibleVerse @BibleId, 113004034, N'Their clan leaders were: Meshobab, Jamlech, Joshah son of Amaziah,'
EXEC add_BibleVerse @BibleId, 113004035, N'Joel, Jehu son of Joshibiah (son of Seraiah, son of Asiel),'
EXEC add_BibleVerse @BibleId, 113004036, N'Eleoenai, Jaakobah, Jeshohaiah, Asaiah, Adiel, Jesimiel, Benaiah,'
EXEC add_BibleVerse @BibleId, 113004037, N'Ziza son of Shipi (son of Allon, son of Jedaiah, son of Shimri, son of Shemaiah).'
EXEC add_BibleVerse @BibleId, 113004038, N'These who are named above were the leaders of their clans. Their extended families increased greatly in numbers.'
EXEC add_BibleVerse @BibleId, 113004039, N'They went to the entrance of Gedor, to the east of the valley, looking for pasture for their sheep.'
EXEC add_BibleVerse @BibleId, 113004040, N'They found fertile and rich pasture; the land was very broad, undisturbed and peaceful. Indeed some Hamites had been living there prior to that.'
EXEC add_BibleVerse @BibleId, 113004041, N'The men whose names are listed came during the time of King Hezekiah of Judah and attacked the Hamites’ settlements, as well as the Meunites they discovered there, and they wiped them out to this very day. They dispossessed them, for they found pasture for their sheep there.'
EXEC add_BibleVerse @BibleId, 113004042, N'Five hundred men of Simeon, led by Pelatiah, Neariah, Rephaiah, and Uzziel, the sons of Ishi, went to the hill country of Seir'
EXEC add_BibleVerse @BibleId, 113004043, N'and defeated the rest of the Amalekite refugees; they live there to this very day.'
EXEC add_BibleVerse @BibleId, 113005001, N'The sons of Reuben, Israel’s firstborn – (Now he was the firstborn, but when he defiled his father’s bed, his rights as firstborn were given to the sons of Joseph, Israel’s son. So Reuben is not listed as firstborn in the genealogical records.'
EXEC add_BibleVerse @BibleId, 113005002, N'Though Judah was the strongest among his brothers and a leader descended from him, the right of the firstborn belonged to Joseph.)'
EXEC add_BibleVerse @BibleId, 113005003, N'The sons of Reuben, Israel’s firstborn: Hanoch, Pallu, Hezron, and Carmi.'
EXEC add_BibleVerse @BibleId, 113005004, N'The descendants of Joel: His son Shemaiah, his son Gog, his son Shimei,'
EXEC add_BibleVerse @BibleId, 113005005, N'his son Micah, his son Reaiah, his son Baal,'
EXEC add_BibleVerse @BibleId, 113005006, N'and his son Beerah, whom King Tiglath-pileser of Assyria carried into exile. Beerah was the tribal leader of Reuben.'
EXEC add_BibleVerse @BibleId, 113005007, N'His brothers by their clans, as listed in their genealogical records: The leader Jeiel, Zechariah,'
EXEC add_BibleVerse @BibleId, 113005008, N'and Bela son of Azaz, son of Shema, son of Joel. They lived in Aroer as far as Nebo and Baal Meon.'
EXEC add_BibleVerse @BibleId, 113005009, N'In the east they settled as far as the entrance to the desert that stretches to the Euphrates River, for their cattle had increased in numbers in the land of Gilead.'
EXEC add_BibleVerse @BibleId, 113005010, N'During the time of Saul they attacked the Hagrites and defeated them. They took over their territory in the entire eastern region of Gilead.'
EXEC add_BibleVerse @BibleId, 113005011, N'The descendants of Gad lived near them in the land of Bashan, as far as Salecah.'
EXEC add_BibleVerse @BibleId, 113005012, N'They included Joel the leader, Shapham the second in command, Janai, and Shaphat in Bashan.'
EXEC add_BibleVerse @BibleId, 113005013, N'Their relatives, listed according to their families, included Michael, Meshullam, Sheba, Jorai, Jacan, Zia, and Eber – seven in all.'
EXEC add_BibleVerse @BibleId, 113005014, N'These were the sons of Abihail son of Huri, son of Jaroah, son of Gilead, son of Michael, son of Jeshishai, son of Jahdo, son of Buz.'
EXEC add_BibleVerse @BibleId, 113005015, N'Ahi son of Abdiel, son of Guni, was the leader of the family.'
EXEC add_BibleVerse @BibleId, 113005016, N'They lived in Gilead, in Bashan and its surrounding settlements, and in the pasturelands of Sharon to their very borders.'
EXEC add_BibleVerse @BibleId, 113005017, N'All of them were listed in the genealogical records in the time of King Jotham of Judah and in the time of King Jeroboam of Israel.'
EXEC add_BibleVerse @BibleId, 113005018, N'The Reubenites, Gadites, and the half-tribe of Manasseh had 44,760 men in their combined armies, warriors who carried shields and swords, were equipped with bows, and were trained for war.'
EXEC add_BibleVerse @BibleId, 113005019, N'They attacked the Hagrites, Jetur, Naphish, and Nodab.'
EXEC add_BibleVerse @BibleId, 113005020, N'They received divine help in fighting them, and the Hagrites and all their allies were handed over to them. They cried out to God during the battle; he responded to their prayers because they trusted in him.'
EXEC add_BibleVerse @BibleId, 113005021, N'They seized the Hagrites’ animals, including 50,000 camels, 250,000 sheep, and 2,000 donkeys. They also took captive 100,000 people.'
EXEC add_BibleVerse @BibleId, 113005022, N'Because God fought for them, they killed many of the enemy. They dispossessed the Hagrites and lived in their land until the exile.'
EXEC add_BibleVerse @BibleId, 113005023, N'The half-tribe of Manasseh settled in the land from Bashan as far as Baal Hermon, Senir, and Mount Hermon. They grew in number.'
EXEC add_BibleVerse @BibleId, 113005024, N'These were the leaders of their families: Epher, Ishi, Eliel, Azriel, Jeremiah, Hodaviah, and Jahdiel. They were skilled warriors, men of reputation, and leaders of their families.'
EXEC add_BibleVerse @BibleId, 113005025, N'But they were unfaithful to the God of their ancestors and worshiped instead the gods of the native peoples whom God had destroyed before them.'
EXEC add_BibleVerse @BibleId, 113005026, N'So the God of Israel stirred up King Pul of Assyria (that is, King Tiglath-pileser of Assyria), and he carried away the Reubenites, Gadites, and half-tribe of Manasseh and took them to Halah, Habor, Hara, and the river of Gozan, where they remain to this very day.'
EXEC add_BibleVerse @BibleId, 113006001, N'The sons of Levi: Gershon, Kohath, and Merari.'
EXEC add_BibleVerse @BibleId, 113006002, N'The sons of Kohath: Amram, Izhar, Hebron, and Uzziel.'
EXEC add_BibleVerse @BibleId, 113006003, N'The children of Amram: Aaron, Moses, and Miriam. The sons of Aaron: Nadab, Abihu, Eleazar, and Ithamar.'
EXEC add_BibleVerse @BibleId, 113006004, N'Eleazar was the father of Phinehas, and Phinehas was the father of Abishua.'
EXEC add_BibleVerse @BibleId, 113006005, N'Abishua was the father of Bukki, and Bukki was the father of Uzzi.'
EXEC add_BibleVerse @BibleId, 113006006, N'Uzzi was the father of Zerahiah, and Zerahiah was the father of Meraioth.'
EXEC add_BibleVerse @BibleId, 113006007, N'Meraioth was the father of Amariah, and Amariah was the father of Ahitub.'
EXEC add_BibleVerse @BibleId, 113006008, N'Ahitub was the father of Zadok, and Zadok was the father of Ahimaaz.'
EXEC add_BibleVerse @BibleId, 113006009, N'Ahimaaz was the father of Azariah, and Azariah was the father of Johanan.'
EXEC add_BibleVerse @BibleId, 113006010, N'Johanan was the father of Azariah, who served as a priest in the temple Solomon built in Jerusalem.'
EXEC add_BibleVerse @BibleId, 113006011, N'Azariah was the father of Amariah, and Amariah was the father of Ahitub.'
EXEC add_BibleVerse @BibleId, 113006012, N'Ahitub was the father of Zadok, and Zadok was the father of Shallum.'
EXEC add_BibleVerse @BibleId, 113006013, N'Shallum was the father of Hilkiah, and Hilkiah was the father of Azariah.'
EXEC add_BibleVerse @BibleId, 113006014, N'Azariah was the father of Seraiah, and Seraiah was the father of Jehozadak.'
EXEC add_BibleVerse @BibleId, 113006015, N'Jehozadak went into exile when the Lord sent the people of Judah and Jerusalem into exile by the hand of Nebuchadnezzar.'
EXEC add_BibleVerse @BibleId, 113006016, N'The sons of Levi: Gershom, Kohath, and Merari.'
EXEC add_BibleVerse @BibleId, 113006017, N'These are the names of the sons Gershom: Libni and Shimei.'
EXEC add_BibleVerse @BibleId, 113006018, N'The sons of Kohath: Amram, Izhar, Hebron, and Uzziel.'
EXEC add_BibleVerse @BibleId, 113006019, N'The sons of Merari: Mahli and Mushi. These are the clans of the Levites by their families.'
EXEC add_BibleVerse @BibleId, 113006020, N'To Gershom: His son Libni, his son Jahath, his son Zimmah,'
EXEC add_BibleVerse @BibleId, 113006021, N'his son Joah, his son Iddo, his son Zerah, and his son Jeatherai.'
EXEC add_BibleVerse @BibleId, 113006022, N'The sons of Kohath: His son Amminadab, his son Korah, his son Assir,'
EXEC add_BibleVerse @BibleId, 113006023, N'his son Elkanah, his son Ebiasaph, his son Assir,'
EXEC add_BibleVerse @BibleId, 113006024, N'his son Tahath, his son Uriel, his son Uzziah, and his son Shaul.'
EXEC add_BibleVerse @BibleId, 113006025, N'The sons of Elkanah: Amasai, Ahimoth,'
EXEC add_BibleVerse @BibleId, 113006026, N'his son Elkanah, his son Zophai, his son Nahath,'
EXEC add_BibleVerse @BibleId, 113006027, N'his son Eliab, his son Jeroham, and his son Elkanah.'
EXEC add_BibleVerse @BibleId, 113006028, N'The sons of Samuel: Joel the firstborn and Abijah the second oldest.'
EXEC add_BibleVerse @BibleId, 113006029, N'The descendants of Merari: Mahli, his son Libni, his son Shimei, his son Uzzah,'
EXEC add_BibleVerse @BibleId, 113006030, N'his son Shimea, his son Haggiah, and his son Asaiah.'
EXEC add_BibleVerse @BibleId, 113006031, N'These are the men David put in charge of music in the Lord’s sanctuary, after the ark was placed there.'
EXEC add_BibleVerse @BibleId, 113006032, N'They performed music before the sanctuary of the meeting tent until Solomon built the Lord’s temple in Jerusalem. They carried out their tasks according to regulations.'
EXEC add_BibleVerse @BibleId, 113006033, N'These are the ones who served along with their sons: From the Kohathites: Heman the musician, son of Joel, son of Samuel,'
EXEC add_BibleVerse @BibleId, 113006034, N'son of Elkanah, son of Jeroham, son of Eliel, son of Toah,'
EXEC add_BibleVerse @BibleId, 113006035, N'son of Zuph, son of Elkanah, son of Mahath, son of Amasai,'
EXEC add_BibleVerse @BibleId, 113006036, N'son of Elkanah, son of Joel, son of Azariah, son of Zephaniah,'
EXEC add_BibleVerse @BibleId, 113006037, N'son of Tahath, son of Assir, son of Ebiasaph, son of Korah,'
EXEC add_BibleVerse @BibleId, 113006038, N'son of Izhar, son of Kohath, son of Levi, son of Israel.'
EXEC add_BibleVerse @BibleId, 113006039, N'Serving beside him was his fellow Levite Asaph, son of Berechiah, son of Shimea,'
EXEC add_BibleVerse @BibleId, 113006040, N'son of Michael, son of Baaseiah, son of Malkijah,'
EXEC add_BibleVerse @BibleId, 113006041, N'son of Ethni, son of Zerah, son of Adaiah,'
EXEC add_BibleVerse @BibleId, 113006042, N'son of Ethan, son of Zimmah, son of Shimei,'
EXEC add_BibleVerse @BibleId, 113006043, N'son of Jahath, son of Gershom, son of Levi.'
EXEC add_BibleVerse @BibleId, 113006044, N'Serving beside them were their fellow Levites, the descendants of Merari, led by Ethan, son of Kishi, son of Abdi, son of Malluch,'
EXEC add_BibleVerse @BibleId, 113006045, N'son of Hashabiah, son of Amaziah, son of Hilkiah,'
EXEC add_BibleVerse @BibleId, 113006046, N'son of Amzi, son of Bani, son of Shemer,'
EXEC add_BibleVerse @BibleId, 113006047, N'son of Mahli, son of Mushi, son of Merari, son of Levi.'
EXEC add_BibleVerse @BibleId, 113006048, N'The rest of their fellow Levites were assigned to perform the remaining tasks at God’s sanctuary.'
EXEC add_BibleVerse @BibleId, 113006049, N'But Aaron and his descendants offered sacrifices on the altar for burnt offerings and on the altar for incense as they had been assigned to do in the most holy sanctuary. They made atonement for Israel, just as God’s servant Moses had ordered.'
EXEC add_BibleVerse @BibleId, 113006050, N'These were the descendants of Aaron: His son Eleazar, his son Phinehas, his son Abishua,'
EXEC add_BibleVerse @BibleId, 113006051, N'his son Bukki, his son Uzzi, his son Zerahiah,'
EXEC add_BibleVerse @BibleId, 113006052, N'his son Meraioth, his son Amariah, his son Ahitub,'
EXEC add_BibleVerse @BibleId, 113006053, N'his son Zadok, and his son Ahimaaz.'
EXEC add_BibleVerse @BibleId, 113006054, N'These were the areas where Aaron’s descendants lived: The following belonged to the Kohathite clan, for they received the first allotment:'
EXEC add_BibleVerse @BibleId, 113006055, N'They were allotted Hebron in the territory of Judah, as well as its surrounding pasturelands.'
EXEC add_BibleVerse @BibleId, 113006056, N'(But the city’s land and nearby towns were allotted to Caleb son of Jephunneh.)'
EXEC add_BibleVerse @BibleId, 113006057, N'The descendants of Aaron were also allotted as cities of refuge Hebron, Libnah and its pasturelands, Jattir, Eshtemoa and its pasturelands,'
EXEC add_BibleVerse @BibleId, 113006058, N'Hilez and its pasturelands, Debir and its pasturelands,'
EXEC add_BibleVerse @BibleId, 113006059, N'Ashan and its pasturelands, and Beth Shemesh and its pasturelands.'
EXEC add_BibleVerse @BibleId, 113006060, N'Within the territory of the tribe of Benjamin they were allotted Geba and its pasturelands, Alemeth and its pasturelands, and Anathoth and its pasturelands. Their clans were allotted thirteen cities in all.'
EXEC add_BibleVerse @BibleId, 113006061, N'The rest of Kohath’s descendants were allotted ten cities in the territory of the half-tribe of Manasseh.'
EXEC add_BibleVerse @BibleId, 113006062, N'The clans of Gershom’s descendants received thirteen cities within the territory of the tribes of Issachar, Asher, Naphtali, and Manasseh (in Bashan).'
EXEC add_BibleVerse @BibleId, 113006063, N'The clans of Merari’s descendants were allotted twelve cities within the territory of the tribes of Reuben, Gad, and Zebulun.'
EXEC add_BibleVerse @BibleId, 113006064, N'So the Israelites gave to the Levites these cities and their pasturelands.'
EXEC add_BibleVerse @BibleId, 113006065, N'They allotted these previously named cities from the territory of the tribes of Judah, Simeon, and Benjamin.'
EXEC add_BibleVerse @BibleId, 113006066, N'The clans of Kohath’s descendants also received territory within the tribe of Ephraim.'
EXEC add_BibleVerse @BibleId, 113006067, N'They were allotted as cities of refuge Shechem and its pasturelands (in the hill country of Ephraim), Gezer and its pasturelands,'
EXEC add_BibleVerse @BibleId, 113006068, N'Jokmeam and its pasturelands, Beth Horon and its pasturelands,'
EXEC add_BibleVerse @BibleId, 113006069, N'Aijalon and its pasturelands, and Gath Rimmon and its pasturelands.'
EXEC add_BibleVerse @BibleId, 113006070, N'Within the territory of the half-tribe of Manasseh, the rest of Kohath’s descendants received Aner and its pasturelands and Bileam and its pasturelands.'
EXEC add_BibleVerse @BibleId, 113006071, N'The following belonged to Gershom’s descendants: Within the territory of the half-tribe of Manasseh: Golan in Bashan and its pasturelands and Ashtaroth and its pasturelands.'
EXEC add_BibleVerse @BibleId, 113006072, N'Within the territory of the tribe of Issachar: Kedesh and its pasturelands, Daberath and its pasturelands,'
EXEC add_BibleVerse @BibleId, 113006073, N'Ramoth and its pasturelands, and Anem and its pasturelands.'
EXEC add_BibleVerse @BibleId, 113006074, N'Within the territory of the tribe of Asher: Mashal and its pasturelands, Abdon and its pasturelands,'
EXEC add_BibleVerse @BibleId, 113006075, N'Hukok and its pasturelands, and Rehob and its pasturelands.'
EXEC add_BibleVerse @BibleId, 113006076, N'Within the territory of the tribe of Naphtali: Kedesh in Galilee and its pasturelands, Hammon and its pasturelands, and Kiriathaim and its pasturelands.'
EXEC add_BibleVerse @BibleId, 113006077, N'The following belonged to the rest of Merari’s descendants: Within the territory of the tribe of Zebulun: Rimmono and its pasturelands, and Tabor and its pasturelands.'
EXEC add_BibleVerse @BibleId, 113006078, N'Within the territory of the tribe of Reuben across the Jordan River east of Jericho: Bezer in the desert and its pasturelands, Jahzah and its pasturelands,'
EXEC add_BibleVerse @BibleId, 113006079, N'Kedemoth and its pasturelands, and Mephaath and its pasturelands.'
EXEC add_BibleVerse @BibleId, 113006080, N'Within the territory of the tribe of Gad: Ramoth in Gilead and its pasturelands, Mahanaim and its pasturelands,'
EXEC add_BibleVerse @BibleId, 113006081, N'Heshbon and its pasturelands, and Jazer and its pasturelands.'
EXEC add_BibleVerse @BibleId, 113007001, N'The sons of Issachar: Tola, Puah, Jashub, and Shimron – four in all.'
EXEC add_BibleVerse @BibleId, 113007002, N'The sons of Tola: Uzzi, Rephaiah, Jeriel, Jahmai, Jibsam, and Samuel. They were leaders of their families. In the time of David there were 22,600 warriors listed in Tola’s genealogical records.'
EXEC add_BibleVerse @BibleId, 113007003, N'The son of Uzzi: Izrachiah. The sons of Izrahiah: Michael, Obadiah, Joel, and Isshiah. All five were leaders.'
EXEC add_BibleVerse @BibleId, 113007004, N'According to the genealogical records of their families, they had 36,000 warriors available for battle, for they had numerous wives and sons.'
EXEC add_BibleVerse @BibleId, 113007005, N'Altogether the genealogical records of the clans of Issachar listed 87,000 warriors.'
EXEC add_BibleVerse @BibleId, 113007006, N'The sons of Benjamin: Bela, Beker, and Jediael – three in all.'
EXEC add_BibleVerse @BibleId, 113007007, N'The sons of Bela: Ezbon, Uzzi, Uzziel, Jerimoth, and Iri. The five of them were leaders of their families. There were 22,034 warriors listed in their genealogical records.'
EXEC add_BibleVerse @BibleId, 113007008, N'The sons of Beker: Zemirah, Joash, Eliezer, Elioenai, Omri, Jeremoth, Abijah, Anathoth, and Alameth. All these were the sons of Beker.'
EXEC add_BibleVerse @BibleId, 113007009, N'There were 20,200 family leaders and warriors listed in their genealogical records.'
EXEC add_BibleVerse @BibleId, 113007010, N'The son of Jediael: Bilhan. The sons of Bilhan: Jeush, Benjamin, Ehud, Kenaanah, Zethan, Tarshish, and Ahishahar.'
EXEC add_BibleVerse @BibleId, 113007011, N'All these were the sons of Jediael. Listed in their genealogical records were 17,200 family leaders and warriors who were capable of marching out to battle.'
EXEC add_BibleVerse @BibleId, 113007012, N'The Shuppites and Huppites were descendants of Ir; the Hushites were descendants of Aher.'
EXEC add_BibleVerse @BibleId, 113007013, N'The sons of Naphtali: Jahziel, Guni, Jezer, and Shallum – sons of Bilhah.'
EXEC add_BibleVerse @BibleId, 113007014, N'The sons of Manasseh: Asriel, who was born to Manasseh’s Aramean concubine. She also gave birth to Makir the father of Gilead.'
EXEC add_BibleVerse @BibleId, 113007015, N'Now Makir married a wife from the Huppites and Shuppites. (His sister’s name was Maacah.) Zelophehad was Manasseh’s second son; he had only daughters.'
EXEC add_BibleVerse @BibleId, 113007016, N'Maacah, Makir’s wife, gave birth to a son, whom she named Peresh. His brother was Sheresh, and his sons were Ulam and Rekem.'
EXEC add_BibleVerse @BibleId, 113007017, N'The son of Ulam: Bedan. These were the sons of Gilead, son of Makir, son of Manasseh.'
EXEC add_BibleVerse @BibleId, 113007018, N'His sister Hammoleketh gave birth to Ishhod, Abiezer, and Mahlah.'
EXEC add_BibleVerse @BibleId, 113007019, N'The sons of Shemida were Ahian, Shechem, Likhi, and Aniam.'
EXEC add_BibleVerse @BibleId, 113007020, N'The descendants of Ephraim: Shuthelah, his son Bered, his son Tahath, his son Eleadah, his son Tahath,'
EXEC add_BibleVerse @BibleId, 113007021, N'his son Zabad, his son Shuthelah (Ezer and Elead were killed by the men of Gath, who were natives of the land, when they went down to steal their cattle.'
EXEC add_BibleVerse @BibleId, 113007022, N'Their father Ephraim mourned for them many days and his brothers came to console him.'
EXEC add_BibleVerse @BibleId, 113007023, N'He had sexual relations with his wife; she became pregnant and gave birth to a son. Ephraim named him Beriah because tragedy had come to his family.'
EXEC add_BibleVerse @BibleId, 113007024, N'His daughter was Sheerah, who built Lower and Upper Beth Horon, as well as Uzzen Sheerah),'
EXEC add_BibleVerse @BibleId, 113007025, N'his son Rephah, his son Resheph, his son Telah, his son Tahan,'
EXEC add_BibleVerse @BibleId, 113007026, N'his son Ladan, his son Ammihud, his son Elishama,'
EXEC add_BibleVerse @BibleId, 113007027, N'his son Nun, and his son Joshua.'
EXEC add_BibleVerse @BibleId, 113007028, N'Their property and settlements included Bethel and its surrounding towns, Naaran to the east, Gezer and its surrounding towns to the west, and Shechem and its surrounding towns as far as Ayyah and its surrounding towns.'
EXEC add_BibleVerse @BibleId, 113007029, N'On the border of Manasseh’s territory were Beth-Shean and its surrounding towns, Taanach and its surrounding towns, Megiddo and its surrounding towns, and Dor and its surrounding towns. The descendants of Joseph, Israel’s son, lived here.'
EXEC add_BibleVerse @BibleId, 113007030, N'The sons of Asher: Imnah, Ishvah, Ishvi, and Beriah. Serah was their sister.'
EXEC add_BibleVerse @BibleId, 113007031, N'The sons of Beriah: Heber and Malkiel, who was the father of Birzaith.'
EXEC add_BibleVerse @BibleId, 113007032, N'Heber was the father of Japhlet, Shomer, Hotham, and Shua their sister.'
EXEC add_BibleVerse @BibleId, 113007033, N'The sons of Japhlet: Pasach, Bimhal, and Ashvath. These were Japhlet’s sons.'
EXEC add_BibleVerse @BibleId, 113007034, N'The sons of his brother Shemer: Rohgah, Hubbah, and Aram.'
EXEC add_BibleVerse @BibleId, 113007035, N'The sons of his brother Helem: Zophah, Imna, Shelesh, and Amal.'
EXEC add_BibleVerse @BibleId, 113007036, N'The sons of Zophah: Suah, Harnepher, Shual, Beri, Imrah,'
EXEC add_BibleVerse @BibleId, 113007037, N'Bezer, Hod, Shamma, Shilshah, Ithran, and Beera.'
EXEC add_BibleVerse @BibleId, 113007038, N'The sons of Jether: Jephunneh, Pispah, and Ara.'
EXEC add_BibleVerse @BibleId, 113007039, N'The sons of Ulla: Arah, Hanniel, and Rizia.'
EXEC add_BibleVerse @BibleId, 113007040, N'All these were the descendants of Asher. They were the leaders of their families, the most capable men, who were warriors and served as head chiefs. There were 26,000 warriors listed in their genealogical records as capable of doing battle.'
EXEC add_BibleVerse @BibleId, 113008001, N'Benjamin was the father of Bela, his firstborn; Ashbel was born second, Aharah third,'
EXEC add_BibleVerse @BibleId, 113008002, N'Nohah fourth, and Rapha fifth.'
EXEC add_BibleVerse @BibleId, 113008003, N'Bela’s sons were Addar, Gera, Abihud,'
EXEC add_BibleVerse @BibleId, 113008004, N'Abishua, Naaman, Ahoah,'
EXEC add_BibleVerse @BibleId, 113008005, N'Gera, Shephuphan, and Huram.'
EXEC add_BibleVerse @BibleId, 113008006, N'These were the descendants of Ehud who were leaders of the families living in Geba who were forced to move to Manahath:'
EXEC add_BibleVerse @BibleId, 113008007, N'Naaman, Ahijah, and Gera, who moved them. Gera was the father of Uzzah and Ahihud.'
EXEC add_BibleVerse @BibleId, 113008008, N'Shaharaim fathered sons in Moab after he divorced his wives Hushim and Baara.'
EXEC add_BibleVerse @BibleId, 113008009, N'By his wife Hodesh he fathered Jobab, Zibia, Mesha, Malkam,'
EXEC add_BibleVerse @BibleId, 113008010, N'Jeuz, Sakia, and Mirmah. These were his sons; they were family leaders.'
EXEC add_BibleVerse @BibleId, 113008011, N'By Hushim he fathered Abitub and Elpaal.'
EXEC add_BibleVerse @BibleId, 113008012, N'The sons of Elpaal: Eber, Misham, Shemed (who built Ono and Lod, as well as its surrounding towns),'
EXEC add_BibleVerse @BibleId, 113008013, N'Beriah, and Shema. They were leaders of the families living in Aijalon and chased out the inhabitants of Gath.'
EXEC add_BibleVerse @BibleId, 113008014, N'Ahio, Shashak, Jeremoth,'
EXEC add_BibleVerse @BibleId, 113008015, N'Zebadiah, Arad, Eder,'
EXEC add_BibleVerse @BibleId, 113008016, N'Michael, Ishpah, and Joha were the sons of Beriah.'
EXEC add_BibleVerse @BibleId, 113008017, N'Zebadiah, Meshullam, Hizki, Heber,'
EXEC add_BibleVerse @BibleId, 113008018, N'Ishmerai, Izliah, and Jobab were the sons of Elpaal.'
EXEC add_BibleVerse @BibleId, 113008019, N'Jakim, Zikri, Zabdi,'
EXEC add_BibleVerse @BibleId, 113008020, N'Elienai, Zillethai, Eliel,'
EXEC add_BibleVerse @BibleId, 113008021, N'Adaiah, Beraiah, and Shimrath were the sons of Shimei.'
EXEC add_BibleVerse @BibleId, 113008022, N'Ishpan, Eber, Eliel,'
EXEC add_BibleVerse @BibleId, 113008023, N'Abdon, Zikri, Hanan,'
EXEC add_BibleVerse @BibleId, 113008024, N'Hananiah, Elam, Anthothijah,'
EXEC add_BibleVerse @BibleId, 113008025, N'Iphdeiah, and Penuel were the sons of Shashak.'
EXEC add_BibleVerse @BibleId, 113008026, N'Shamsherai, Shechariah, Athaliah,'
EXEC add_BibleVerse @BibleId, 113008027, N'Jaareshiah, Elijah, and Zikri were the sons of Jeroham.'
EXEC add_BibleVerse @BibleId, 113008028, N'These were the family leaders listed in the genealogical records; they lived in Jerusalem.'
EXEC add_BibleVerse @BibleId, 113008029, N'The father of Gibeon lived in Gibeon; his wife’s name was Maacah.'
EXEC add_BibleVerse @BibleId, 113008030, N'His firstborn son was Abdon, followed by Zur, Kish, Baal, Nadab,'
EXEC add_BibleVerse @BibleId, 113008031, N'Gedor, Ahio, Zeker, and Mikloth.'
EXEC add_BibleVerse @BibleId, 113008032, N'Mikloth was the father of Shimeah. They also lived near their relatives in Jerusalem.'
EXEC add_BibleVerse @BibleId, 113008033, N'Ner was the father of Kish, and Kish was the father of Saul. Saul was the father of Jonathan, Malki-Shua, Abinadab, and Eshbaal.'
EXEC add_BibleVerse @BibleId, 113008034, N'The son of Jonathan: Meribbaal. Meribbaal was the father of Micah.'
EXEC add_BibleVerse @BibleId, 113008035, N'The sons of Micah: Pithon, Melech, Tarea, and Ahaz.'
EXEC add_BibleVerse @BibleId, 113008036, N'Ahaz was the father of Jehoaddah, and Jehoaddah was the father of Alemeth, Azmaveth, and Zimri. Zimri was the father of Moza,'
EXEC add_BibleVerse @BibleId, 113008037, N'and Moza was the father of Binea. His son was Raphah, whose son was Eleasah, whose son was Azel.'
EXEC add_BibleVerse @BibleId, 113008038, N'Azel had six sons: Azrikam his firstborn, followed by Ishmael, Sheariah, Obadiah, and Hanan. All these were the sons of Azel.'
EXEC add_BibleVerse @BibleId, 113008039, N'The sons of his brother Eshek: Ulam was his firstborn, Jeush second, and Eliphelet third.'
EXEC add_BibleVerse @BibleId, 113008040, N'The sons of Ulam were warriors who were adept archers. They had many sons and grandsons, a total of 150. All these were the descendants of Benjamin.'
EXEC add_BibleVerse @BibleId, 113009001, N'Genealogical records were kept for all Israel; they are recorded in the Scroll of the Kings of Israel. The people of Judah were carried away to Babylon because of their unfaithfulness.'
EXEC add_BibleVerse @BibleId, 113009002, N'The first to resettle on their property and in their cities were some Israelites, priests, Levites, and temple servants.'
EXEC add_BibleVerse @BibleId, 113009003, N'Some from the tribes of Judah, Benjamin, and Ephraim and Manasseh settled in Jerusalem.'
EXEC add_BibleVerse @BibleId, 113009004, N'The settlers included: Uthai son of Ammihud, son of Omri, son of Imri, son of Bani, who was a descendant of Perez son of Judah.'
EXEC add_BibleVerse @BibleId, 113009005, N'From the Shilonites: Asaiah the firstborn and his sons.'
EXEC add_BibleVerse @BibleId, 113009006, N'From the descendants of Zerah: Jeuel. Their relatives numbered 690.'
EXEC add_BibleVerse @BibleId, 113009007, N'From the descendants of Benjamin: Sallu son of Meshullam, son of Hodaviah, son of Hassenuah;'
EXEC add_BibleVerse @BibleId, 113009008, N'Ibneiah son of Jeroham; Elah son of Uzzi, son of Mikri; and Meshullam son of Shephatiah, son of Reuel, son of Ibnijah.'
EXEC add_BibleVerse @BibleId, 113009009, N'Their relatives, listed in their genealogical records, numbered 956. All these men were leaders of their families.'
EXEC add_BibleVerse @BibleId, 113009010, N'From the priests: Jedaiah; Jehoiarib; Jakin;'
EXEC add_BibleVerse @BibleId, 113009011, N'Azariah son of Hilkiah, son of Meshullam, son of Zadok, son of Meraioth, son of Ahitub the leader in God’s temple;'
EXEC add_BibleVerse @BibleId, 113009012, N'Adaiah son of Jeroham, son of Pashhur, son of Malkijah; and Maasai son of Adiel, son of Jahzerah, son of Meshullam, son of Meshillemith, son of Immer.'
EXEC add_BibleVerse @BibleId, 113009013, N'Their relatives, who were leaders of their families, numbered 1,760. They were capable men who were assigned to carry out the various tasks of service in God’s temple.'
EXEC add_BibleVerse @BibleId, 113009014, N'From the Levites: Shemaiah son of Hasshub, son of Azrikam, son of Hashabiah a descendant of Merari;'
EXEC add_BibleVerse @BibleId, 113009015, N'Bakbakkar; Heresh; Galal; Mattaniah son of Mika, son of Zikri, son of Asaph;'
EXEC add_BibleVerse @BibleId, 113009016, N'Obadiah son of Shemaiah, son of Galal, son of Jeduthun; and Berechiah son of Asa, son of Elkanah, who lived among the settlements of the Netophathites.'
EXEC add_BibleVerse @BibleId, 113009017, N'The gatekeepers were: Shallum, Akkub, Talmon, Ahiman, and their brothers. Shallum was the leader;'
EXEC add_BibleVerse @BibleId, 113009018, N'he serves to this day at the King’s Gate on the east. These were the gatekeepers from the camp of the descendants of Levi.'
EXEC add_BibleVerse @BibleId, 113009019, N'Shallum son of Kore, son of Ebiasaph, son of Korah, and his relatives from his family (the Korahites) were assigned to guard the entrance to the sanctuary. Their ancestors had guarded the entrance to the Lord’s dwelling place.'
EXEC add_BibleVerse @BibleId, 113009020, N'Phinehas son of Eleazar had been their leader in earlier times, and the Lord was with him.'
EXEC add_BibleVerse @BibleId, 113009021, N'Zechariah son of Meshelemiah was the guard at the entrance to the meeting tent.'
EXEC add_BibleVerse @BibleId, 113009022, N'All those selected to be gatekeepers at the entrances numbered 212. Their names were recorded in the genealogical records of their settlements. David and Samuel the prophet had appointed them to their positions.'
EXEC add_BibleVerse @BibleId, 113009023, N'They and their descendants were assigned to guard the gates of the Lord’s sanctuary (that is, the tabernacle).'
EXEC add_BibleVerse @BibleId, 113009024, N'The gatekeepers were posted on all four sides – east, west, north, and south.'
EXEC add_BibleVerse @BibleId, 113009025, N'Their relatives, who lived in their settlements, came from time to time and served with them for seven-day periods.'
EXEC add_BibleVerse @BibleId, 113009026, N'The four head gatekeepers, who were Levites, were assigned to guard the storerooms and treasuries in God’s sanctuary.'
EXEC add_BibleVerse @BibleId, 113009027, N'They would spend the night in their posts all around God’s sanctuary, for they were assigned to guard it and would open it with the key every morning.'
EXEC add_BibleVerse @BibleId, 113009028, N'Some of them were in charge of the articles used by those who served; they counted them when they brought them in and when they brought them out.'
EXEC add_BibleVerse @BibleId, 113009029, N'Some of them were in charge of the equipment and articles of the sanctuary, as well as the flour, wine, olive oil, incense, and spices.'
EXEC add_BibleVerse @BibleId, 113009030, N'(But some of the priests mixed the spices.)'
EXEC add_BibleVerse @BibleId, 113009031, N'Mattithiah, a Levite, the firstborn son of Shallum the Korahite, was in charge of baking the bread for offerings.'
EXEC add_BibleVerse @BibleId, 113009032, N'Some of the Kohathites, their relatives, were in charge of preparing the bread that is displayed each Sabbath.'
EXEC add_BibleVerse @BibleId, 113009033, N'The musicians and Levite family leaders stayed in rooms at the sanctuary and were exempt from other duties, for day and night they had to carry out their assigned tasks.'
EXEC add_BibleVerse @BibleId, 113009034, N'These were the family leaders of the Levites, as listed in their genealogical records. They lived in Jerusalem.'
EXEC add_BibleVerse @BibleId, 113009035, N'Jeiel (the father of Gibeon) lived in Gibeon. His wife was Maacah.'
EXEC add_BibleVerse @BibleId, 113009036, N'His firstborn son was Abdon, followed by Zur, Kish, Baal, Ner, Nadab,'
EXEC add_BibleVerse @BibleId, 113009037, N'Gedor, Ahio, Zechariah, and Mikloth.'
EXEC add_BibleVerse @BibleId, 113009038, N'Mikloth was the father of Shimeam. They also lived near their relatives in Jerusalem.'
EXEC add_BibleVerse @BibleId, 113009039, N'Ner was the father of Kish, and Kish was the father of Saul. Saul was the father of Jonathan, Malki-Shua, Abinadab, and Eshbaal.'
EXEC add_BibleVerse @BibleId, 113009040, N'The son of Jonathan: Meribbaal, who was the father of Micah.'
EXEC add_BibleVerse @BibleId, 113009041, N'The sons of Micah: Pithon, Melech, Tahrea, and Ahaz.'
EXEC add_BibleVerse @BibleId, 113009042, N'Ahaz was the father of Jarah, and Jarah was the father of Alemeth, Azmaveth, and Zimri. Zimri was the father of Moza,'
EXEC add_BibleVerse @BibleId, 113009043, N'and Moza was the father of Binea. His son was Rephaiah, whose son was Eleasah, whose son was Azel.'
EXEC add_BibleVerse @BibleId, 113009044, N'Azel had six sons: Azrikam his firstborn, followed by Ishmael, Sheariah, Obadiah, and Hanan. These were the sons of Azel.'
EXEC add_BibleVerse @BibleId, 113010001, N'Now the Philistines fought against Israel. The Israelites fled before the Philistines and many of them fell dead on Mount Gilboa.'
EXEC add_BibleVerse @BibleId, 113010002, N'The Philistines stayed right on the heels of Saul and his sons. They struck down Saul’s sons Jonathan, Abinadab, and Malki-Shua.'
EXEC add_BibleVerse @BibleId, 113010003, N'The battle was thick around Saul; the archers spotted him and wounded him.'
EXEC add_BibleVerse @BibleId, 113010004, N'Saul told his armor bearer, “Draw your sword and stab me with it. Otherwise these uncircumcised people will come and torture me.” But his armor bearer refused to do it, because he was very afraid. So Saul took the sword and fell on it.'
EXEC add_BibleVerse @BibleId, 113010005, N'When his armor bearer saw that Saul was dead, he also fell on his sword and died.'
EXEC add_BibleVerse @BibleId, 113010006, N'So Saul and his three sons died; his whole household died together.'
EXEC add_BibleVerse @BibleId, 113010007, N'When all the Israelites who were in the valley saw that the army had fled and that Saul and his sons were dead, they abandoned their cities and fled. The Philistines came and occupied them.'
EXEC add_BibleVerse @BibleId, 113010008, N'The next day, when the Philistines came to strip loot from the corpses, they discovered Saul and his sons lying dead on Mount Gilboa.'
EXEC add_BibleVerse @BibleId, 113010009, N'They stripped his corpse, and then carried off his head and his armor. They sent messengers throughout the land of the Philistines proclaiming the news to their idols and their people.'
EXEC add_BibleVerse @BibleId, 113010010, N'They placed his armor in the temple of their gods and hung his head in the temple of Dagon.'
EXEC add_BibleVerse @BibleId, 113010011, N'When all the residents of Jabesh Gilead heard about everything the Philistines had done to Saul,'
EXEC add_BibleVerse @BibleId, 113010012, N'all the warriors went and recovered the bodies of Saul and his sons and brought them to Jabesh. They buried their remains under the oak tree in Jabesh and fasted for seven days.'
EXEC add_BibleVerse @BibleId, 113010013, N'So Saul died because he was unfaithful to the Lord and did not obey the Lord’s instructions; he even tried to conjure up underworld spirits.'
EXEC add_BibleVerse @BibleId, 113010014, N'He did not seek the Lord’s guidance, so the Lord killed him and transferred the kingdom to David son of Jesse.'
EXEC add_BibleVerse @BibleId, 113011001, N'All Israel joined David at Hebron and said, “Look, we are your very flesh and blood!'
EXEC add_BibleVerse @BibleId, 113011002, N'In the past, even when Saul was king, you were Israel’s commanding general. The Lord your God said to you, ‘You will shepherd my people Israel; you will rule over my people Israel.’”'
EXEC add_BibleVerse @BibleId, 113011003, N'When all the leaders of Israel came to the king at Hebron, David made an agreement with them in Hebron before the Lord. They anointed David king over Israel, just as the Lord had announced through Samuel.'
EXEC add_BibleVerse @BibleId, 113011004, N'David and the whole Israelite army advanced to Jerusalem (that is, Jebus). (The Jebusites, the land’s original inhabitants, lived there.)'
EXEC add_BibleVerse @BibleId, 113011005, N'The residents of Jebus said to David, “You cannot invade this place!” But David captured the fortress of Zion (that is, the City of David).'
EXEC add_BibleVerse @BibleId, 113011006, N'David said, “Whoever attacks the Jebusites first will become commanding general!” So Joab son of Zeruiah attacked first and became commander.'
EXEC add_BibleVerse @BibleId, 113011007, N'David lived in the fortress; for this reason it is called the City of David.'
EXEC add_BibleVerse @BibleId, 113011008, N'He built up the city around it, from the terrace to the surrounding walls; Joab restored the rest of the city.'
EXEC add_BibleVerse @BibleId, 113011009, N'David’s power steadily grew, for the Lord who commands armies was with him.'
EXEC add_BibleVerse @BibleId, 113011010, N'These were the leaders of David’s warriors who helped establish and stabilize his rule over all Israel, in accordance with the Lord’s word.'
EXEC add_BibleVerse @BibleId, 113011011, N'This is the list of David’s warriors: Jashobeam, a Hacmonite, was head of the officers. He killed three hundred men with his spear in a single battle.'
EXEC add_BibleVerse @BibleId, 113011012, N'Next in command was Eleazar son of Dodo the Ahohite. He was one of the three elite warriors.'
EXEC add_BibleVerse @BibleId, 113011013, N'He was with David in Pas Dammim when the Philistines assembled there for battle. In an area of the field that was full of barley, the army retreated before the Philistines,'
EXEC add_BibleVerse @BibleId, 113011014, N'but then they made a stand in the middle of that area. They defended it and defeated the Philistines; the Lord gave them a great victory.'
EXEC add_BibleVerse @BibleId, 113011015, N'Three of the thirty leaders went down to David at the rocky cliff at the cave of Adullam, while a Philistine force was camped in the Valley of Rephaim.'
EXEC add_BibleVerse @BibleId, 113011016, N'David was in the stronghold at the time, while a Philistine garrison was in Bethlehem.'
EXEC add_BibleVerse @BibleId, 113011017, N'David was thirsty and said, “How I wish someone would give me some water to drink from the cistern in Bethlehem near the city gate!”'
EXEC add_BibleVerse @BibleId, 113011018, N'So the three elite warriors broke through the Philistine forces and drew some water from the cistern in Bethlehem near the city gate. They carried it back to David, but David refused to drink it. He poured it out as a drink offering to the Lord'
EXEC add_BibleVerse @BibleId, 113011019, N'and said, “God forbid that I should do this! Should I drink the blood of these men who risked their lives?” Because they risked their lives to bring it to him, he refused to drink it. Such were the exploits of the three elite warriors.'
EXEC add_BibleVerse @BibleId, 113011020, N'Abishai the brother of Joab was head of the three elite warriors. He killed three hundred men with his spear and gained fame along with the three elite warriors.'
EXEC add_BibleVerse @BibleId, 113011021, N'From the three he was given double honor and he became their officer, even though he was not one of them.'
EXEC add_BibleVerse @BibleId, 113011022, N'Benaiah son of Jehoiada was a brave warrior from Kabzeel who performed great exploits. He struck down the two sons of Ariel of Moab; he also went down and killed a lion inside a cistern on a snowy day.'
EXEC add_BibleVerse @BibleId, 113011023, N'He even killed an Egyptian who was seven and a half feet tall. The Egyptian had a spear as big as the crossbeam of a weaver’s loom; Benaiah attacked him with a club. He grabbed the spear out of the Egyptian’s hand and killed him with his own spear.'
EXEC add_BibleVerse @BibleId, 113011024, N'Such were the exploits of Benaiah son of Jehoiada, who gained fame along with the three elite warriors.'
EXEC add_BibleVerse @BibleId, 113011025, N'He received honor from the thirty warriors, though he was not one of the three elite warriors. David put him in charge of his bodyguard.'
EXEC add_BibleVerse @BibleId, 113011026, N'The mighty warriors were: Asahel the brother of Joab, Elhanan son of Dodo, from Bethlehem,'
EXEC add_BibleVerse @BibleId, 113011027, N'Shammoth the Harorite, Helez the Pelonite,'
EXEC add_BibleVerse @BibleId, 113011028, N'Ira son of Ikkesh the Tekoite, Abiezer the Anathothite,'
EXEC add_BibleVerse @BibleId, 113011029, N'Sibbekai the Hushathite, Ilai the Ahohite,'
EXEC add_BibleVerse @BibleId, 113011030, N'Maharai the Netophathite, Heled son of Baanah the Netophathite,'
EXEC add_BibleVerse @BibleId, 113011031, N'Ithai son of Ribai from Gibeah in Benjaminite territory, Benaiah the Pirathonite,'
EXEC add_BibleVerse @BibleId, 113011032, N'Hurai from the valleys of Gaash, Abiel the Arbathite,'
EXEC add_BibleVerse @BibleId, 113011033, N'Azmaveth the Baharumite, Eliahba the Shaalbonite,'
EXEC add_BibleVerse @BibleId, 113011034, N'the sons of Hashem the Gizonite, Jonathan son of Shageh the Hararite,'
EXEC add_BibleVerse @BibleId, 113011035, N'Ahiam son of Sakar the Hararite, Eliphal son of Ur,'
EXEC add_BibleVerse @BibleId, 113011036, N'Hepher the Mekerathite, Ahijah the Pelonite,'
EXEC add_BibleVerse @BibleId, 113011037, N'Hezro the Carmelite, Naarai son of Ezbai,'
EXEC add_BibleVerse @BibleId, 113011038, N'Joel the brother of Nathan, Mibhar son of Hagri,'
EXEC add_BibleVerse @BibleId, 113011039, N'Zelek the Ammonite, Naharai the Beerothite, the armor-bearer of Joab son of Zeruiah,'
EXEC add_BibleVerse @BibleId, 113011040, N'Ira the Ithrite, Gareb the Ithrite,'
EXEC add_BibleVerse @BibleId, 113011041, N'Uriah the Hittite, Zabad son of Achli,'
EXEC add_BibleVerse @BibleId, 113011042, N'Adina son of Shiza the Reubenite, leader of the Reubenites and the thirty warriors with him,'
EXEC add_BibleVerse @BibleId, 113011043, N'Hanan son of Maacah, Joshaphat the Mithnite,'
EXEC add_BibleVerse @BibleId, 113011044, N'Uzzia the Ashterathite, Shama and Jeiel, the sons of Hotham the Aroerite,'
EXEC add_BibleVerse @BibleId, 113011045, N'Jediael son of Shimri, and Joha his brother, the Tizite,'
EXEC add_BibleVerse @BibleId, 113011046, N'Eliel the Mahavite, and Jeribai and Joshaviah, the sons of Elnaam, and Ithmah the Moabite,'
EXEC add_BibleVerse @BibleId, 113011047, N'Eliel, and Obed, and Jaasiel the Mezobaite.'
EXEC add_BibleVerse @BibleId, 113012001, N'These were the men who joined David in Ziklag, when he was banished from the presence of Saul son of Kish. (They were among the warriors who assisted him in battle.'
EXEC add_BibleVerse @BibleId, 113012002, N'They were armed with bows and could shoot arrows or sling stones right or left-handed. They were fellow tribesmen of Saul from Benjamin. ) These were:'
EXEC add_BibleVerse @BibleId, 113012003, N'Ahiezer, the leader, and Joash, the sons of Shemaah the Gibeathite; Jeziel and Pelet, the sons of Azmaveth; Berachah, Jehu the Anathothite,'
EXEC add_BibleVerse @BibleId, 113012004, N'Ishmaiah the Gibeonite, one of the thirty warriors and their leader, Jeremiah, Jahaziel, Johanan, Jozabad the Gederathite,'
EXEC add_BibleVerse @BibleId, 113012005, N'Eluzai, Jerimoth, Bealiah, Shemariah, Shephatiah the Haruphite,'
EXEC add_BibleVerse @BibleId, 113012006, N'Elkanah, Isshiah, Azarel, Joezer, and Jashobeam, who were Korahites,'
EXEC add_BibleVerse @BibleId, 113012007, N'and Joelah and Zebadiah, the sons of Jeroham from Gedor.'
EXEC add_BibleVerse @BibleId, 113012008, N'Some of the Gadites joined David at the stronghold in the desert. They were warriors who were trained for battle; they carried shields and spears. They were as fierce as lions and could run as quickly as gazelles across the hills.'
EXEC add_BibleVerse @BibleId, 113012009, N'Ezer was the leader, Obadiah the second in command, Eliab the third,'
EXEC add_BibleVerse @BibleId, 113012010, N'Mishmannah the fourth, Jeremiah the fifth,'
EXEC add_BibleVerse @BibleId, 113012011, N'Attai the sixth, Eliel the seventh,'
EXEC add_BibleVerse @BibleId, 113012012, N'Johanan the eighth, Elzabad the ninth,'
EXEC add_BibleVerse @BibleId, 113012013, N'Jeremiah the tenth, and Machbannai the eleventh.'
EXEC add_BibleVerse @BibleId, 113012014, N'These Gadites were military leaders; the least led a hundred men, the greatest a thousand.'
EXEC add_BibleVerse @BibleId, 113012015, N'They crossed the Jordan River in the first month, when it was overflowing its banks, and routed those living in all the valleys to the east and west.'
EXEC add_BibleVerse @BibleId, 113012016, N'Some from Benjamin and Judah also came to David’s stronghold.'
EXEC add_BibleVerse @BibleId, 113012017, N'David went out to meet them and said, “If you come to me in peace and want to help me, then I will make an alliance with you. But if you come to betray me to my enemies when I have not harmed you, may the God of our ancestors take notice and judge!”'
EXEC add_BibleVerse @BibleId, 113012018, N'But a spirit empowered Amasai, the leader of the thirty warriors, and he said: “We are yours, O David! We support you, O son of Jesse! May you greatly prosper! May those who help you prosper! Indeed your God helps you!” So David accepted them and made them leaders of raiding bands.'
EXEC add_BibleVerse @BibleId, 113012019, N'Some men from Manasseh joined David when he went with the Philistines to fight against Saul. (But in the end they did not help the Philistines because, after taking counsel, the Philistine lords sent David away, saying: “It would be disastrous for us if he deserts to his master Saul.”)'
EXEC add_BibleVerse @BibleId, 113012020, N'When David went to Ziklag, the men of Manasseh who joined him were Adnach, Jozabad, Jediael, Michael, Jozabad, Elihu, and Zillethai, leaders of a thousand soldiers each in the tribe of Manasseh.'
EXEC add_BibleVerse @BibleId, 113012021, N'They helped David fight against raiding bands, for all of them were warriors and leaders in the army.'
EXEC add_BibleVerse @BibleId, 113012022, N'Each day men came to help David until his army became very large.'
EXEC add_BibleVerse @BibleId, 113012023, N'The following is a record of the armed warriors who came with their leaders and joined David in Hebron in order to make David king in Saul’s place, in accordance with the Lord’s decree:'
EXEC add_BibleVerse @BibleId, 113012024, N'From Judah came 6,800 trained warriors carrying shields and spears.'
EXEC add_BibleVerse @BibleId, 113012025, N'From Simeon there were 7,100 warriors.'
EXEC add_BibleVerse @BibleId, 113012026, N'From Levi there were 4,600.'
EXEC add_BibleVerse @BibleId, 113012027, N'Jehoiada, the leader of Aaron’s descendants, brought 3,700 men with him,'
EXEC add_BibleVerse @BibleId, 113012028, N'along with Zadok, a young warrior, and twenty-two leaders from his family.'
EXEC add_BibleVerse @BibleId, 113012029, N'From Benjamin, Saul’s tribe, there were 3,000, most of whom, up to that time, had been loyal to Saul.'
EXEC add_BibleVerse @BibleId, 113012030, N'From Ephraim there were 20,800 warriors, who had brought fame to their families.'
EXEC add_BibleVerse @BibleId, 113012031, N'From the half tribe of Manasseh there were 18,000 who had been designated by name to come and make David king.'
EXEC add_BibleVerse @BibleId, 113012032, N'From Issachar there were 200 leaders and all their relatives at their command – they understood the times and knew what Israel should do.'
EXEC add_BibleVerse @BibleId, 113012033, N'From Zebulun there were 50,000 warriors who were prepared for battle, equipped with all kinds of weapons, and ready to give their undivided loyalty.'
EXEC add_BibleVerse @BibleId, 113012034, N'From Naphtali there were 1,000 officers, along with 37,000 men carrying shields and spears.'
EXEC add_BibleVerse @BibleId, 113012035, N'From Dan there were 28,600 men prepared for battle.'
EXEC add_BibleVerse @BibleId, 113012036, N'From Asher there were 40,000 warriors prepared for battle.'
EXEC add_BibleVerse @BibleId, 113012037, N'From the other side of the Jordan, from Reuben, Gad, and the half tribe of Manasseh, there were 120,000 men armed with all kinds of weapons.'
EXEC add_BibleVerse @BibleId, 113012038, N'All these men were warriors who were ready to march. They came to Hebron to make David king over all Israel by acclamation; all the rest of the Israelites also were in agreement that David should become king.'
EXEC add_BibleVerse @BibleId, 113012039, N'They spent three days feasting there with David, for their relatives had given them provisions.'
EXEC add_BibleVerse @BibleId, 113012040, N'Also their neighbors, from as far away as Issachar, Zebulun, and Naphtali, were bringing food on donkeys, camels, mules, and oxen. There were large supplies of flour, fig cakes, raisins, wine, olive oil, beef, and lamb, for Israel was celebrating.'
EXEC add_BibleVerse @BibleId, 113013001, N'David consulted with his military officers, including those who led groups of a thousand and those who led groups of a hundred.'
EXEC add_BibleVerse @BibleId, 113013002, N'David said to the whole Israelite assembly, “If you so desire and the Lord our God approves, let’s spread the word to our brothers who remain in all the regions of Israel, and to the priests and Levites in their cities, so they may join us.'
EXEC add_BibleVerse @BibleId, 113013003, N'Let’s move the ark of our God back here, for we did not seek his will throughout Saul’s reign.”'
EXEC add_BibleVerse @BibleId, 113013004, N'The whole assembly agreed to do this, for the proposal seemed right to all the people.'
EXEC add_BibleVerse @BibleId, 113013005, N'So David assembled all Israel from the Shihor River in Egypt to Lebo Hamath, to bring the ark of God from Kiriath Jearim.'
EXEC add_BibleVerse @BibleId, 113013006, N'David and all Israel went up to Baalah (that is, Kiriath Jearim) in Judah to bring up from there the ark of God the Lord, who sits enthroned between the cherubim – the ark that is called by his name.'
EXEC add_BibleVerse @BibleId, 113013007, N'They transported the ark on a new cart from the house of Abinadab; Uzzah and Ahio were guiding the cart,'
EXEC add_BibleVerse @BibleId, 113013008, N'while David and all Israel were energetically celebrating before God, singing and playing various stringed instruments, tambourines, cymbals, and trumpets.'
EXEC add_BibleVerse @BibleId, 113013009, N'When they arrived at the threshing floor of Kidon, Uzzah reached out his hand to take hold of the ark, because the oxen stumbled.'
EXEC add_BibleVerse @BibleId, 113013010, N'The Lord was so furious with Uzzah, he killed him, because he reached out his hand and touched the ark. He died right there before God.'
EXEC add_BibleVerse @BibleId, 113013011, N'David was angry because the Lord attacked Uzzah; so he called that place Perez Uzzah, which remains its name to this very day.'
EXEC add_BibleVerse @BibleId, 113013012, N'David was afraid of God that day and said, “How will I ever be able to bring the ark of God up here?”'
EXEC add_BibleVerse @BibleId, 113013013, N'So David did not move the ark to the City of David; he left it in the house of Obed-Edom the Gittite.'
EXEC add_BibleVerse @BibleId, 113013014, N'The ark of God remained in Obed-Edom’s house for three months; the Lord blessed Obed-Edom’s family and everything that belonged to him.'
EXEC add_BibleVerse @BibleId, 113014001, N'King Hiram of Tyre sent messengers to David, along with cedar logs, stonemasons, and carpenters to build a palace for him.'
EXEC add_BibleVerse @BibleId, 113014002, N'David realized that the Lord had established him as king over Israel and that he had elevated his kingdom for the sake of his people Israel.'
EXEC add_BibleVerse @BibleId, 113014003, N'In Jerusalem David married more wives and fathered more sons and daughters.'
EXEC add_BibleVerse @BibleId, 113014004, N'These are the names of children born to him in Jerusalem: Shammua, Shobab, Nathan, Solomon,'
EXEC add_BibleVerse @BibleId, 113014005, N'Ibhar, Elishua, Elpelet,'
EXEC add_BibleVerse @BibleId, 113014006, N'Nogah, Nepheg, Japhia,'
EXEC add_BibleVerse @BibleId, 113014007, N'Elishama, Beeliada, and Eliphelet.'
EXEC add_BibleVerse @BibleId, 113014008, N'When the Philistines heard that David had been anointed king of all Israel, all the Philistines marched up to confront him. When David heard about it, he marched out against them.'
EXEC add_BibleVerse @BibleId, 113014009, N'Now the Philistines had come and raided the Valley of Rephaim.'
EXEC add_BibleVerse @BibleId, 113014010, N'David asked God, “Should I march up against the Philistines? Will you hand them over to me?” The Lord said to him, “March up! I will hand them over to you!”'
EXEC add_BibleVerse @BibleId, 113014011, N'So they marched against Baal Perazim and David defeated them there. David said, “Using me as his instrument, God has burst out against my enemies like water bursts out.” So that place is called Baal Perazim.'
EXEC add_BibleVerse @BibleId, 113014012, N'The Philistines left their idols there, so David ordered that they be burned.'
EXEC add_BibleVerse @BibleId, 113014013, N'The Philistines again raided the valley.'
EXEC add_BibleVerse @BibleId, 113014014, N'So David again asked God what he should do. This time God told him, “Don’t march up after them; circle around them and come against them in front of the trees.'
EXEC add_BibleVerse @BibleId, 113014015, N'When you hear the sound of marching in the tops of the trees, then attack. For at that moment the Lord is going before you to strike down the army of the Philistines.”'
EXEC add_BibleVerse @BibleId, 113014016, N'David did just as God commanded him, and they struck down the Philistine army from Gibeon to Gezer.'
EXEC add_BibleVerse @BibleId, 113014017, N'So David became famous in all the lands; the Lord caused all the nations to fear him.'
EXEC add_BibleVerse @BibleId, 113015001, N'David constructed buildings in the City of David; he then prepared a place for the ark of God and pitched a tent for it.'
EXEC add_BibleVerse @BibleId, 113015002, N'Then David said, “Only the Levites may carry the ark of God, for the Lord chose them to carry the ark of the Lord and to serve before him perpetually.'
EXEC add_BibleVerse @BibleId, 113015003, N'David assembled all Israel at Jerusalem to bring the ark of the Lord up to the place he had prepared for it.'
EXEC add_BibleVerse @BibleId, 113015004, N'David gathered together the descendants of Aaron and the Levites:'
EXEC add_BibleVerse @BibleId, 113015005, N'From the descendants of Kohath: Uriel the leader and 120 of his relatives.'
EXEC add_BibleVerse @BibleId, 113015006, N'From the descendants of Merari: Asaiah the leader and 220 of his relatives.'
EXEC add_BibleVerse @BibleId, 113015007, N'From the descendants of Gershom: Joel the leader and 130 of his relatives.'
EXEC add_BibleVerse @BibleId, 113015008, N'From the descendants of Elizaphan: Shemaiah the leader and 200 of his relatives.'
EXEC add_BibleVerse @BibleId, 113015009, N'From the descendants of Hebron: Eliel the leader and 80 of his relatives.'
EXEC add_BibleVerse @BibleId, 113015010, N'From the descendants of Uzziel: Amminadab the leader and 112 of his relatives.'
EXEC add_BibleVerse @BibleId, 113015011, N'David summoned the priests Zadok and Abiathar, along with the Levites Uriel, Asaiah, Joel, Shemaiah, Eliel, and Amminadab.'
EXEC add_BibleVerse @BibleId, 113015012, N'He told them: “You are the leaders of the Levites’ families. You and your relatives must consecrate yourselves and bring the ark of the Lord God of Israel up to the place I have prepared for it.'
EXEC add_BibleVerse @BibleId, 113015013, N'The first time you did not carry it; that is why the Lord God attacked us, because we did not ask him about the proper way to carry it.”'
EXEC add_BibleVerse @BibleId, 113015014, N'The priests and Levites consecrated themselves so they could bring up the ark of the Lord God of Israel.'
EXEC add_BibleVerse @BibleId, 113015015, N'The descendants of Levi carried the ark of God on their shoulders with poles, just as Moses had ordered according to the divine command.'
EXEC add_BibleVerse @BibleId, 113015016, N'David told the leaders of the Levites to appoint some of their relatives as musicians; they were to play various instruments, including stringed instruments and cymbals, and to sing loudly and joyfully.'
EXEC add_BibleVerse @BibleId, 113015017, N'So the Levites appointed Heman son of Joel; one of his relatives, Asaph son of Berechiah; one of the descendants of Merari, Ethan son of Kushaiah;'
EXEC add_BibleVerse @BibleId, 113015018, N'along with some of their relatives who were second in rank, including Zechariah, Jaaziel, Shemiramoth, Jehiel, Unni, Eliab, Benaiah, Maaseiah, Mattithiah, Eliphelehu, Mikneiah, Obed-Edom, and Jeiel, the gatekeepers.'
EXEC add_BibleVerse @BibleId, 113015019, N'The musicians Heman, Asaph, and Ethan were to sound the bronze cymbals;'
EXEC add_BibleVerse @BibleId, 113015020, N'Zechariah, Aziel, Shemiramoth, Jehiel, Unni, Eliab, Maaseiah, and Benaiah were to play the harps according to the alamoth style;'
EXEC add_BibleVerse @BibleId, 113015021, N'Mattithiah, Eliphelehu, Mikneiah, Obed-Edom, Jeiel, and Azaziah were to play the lyres according to the sheminith style, as led by the director;'
EXEC add_BibleVerse @BibleId, 113015022, N'Kenaniah, the leader of the Levites, was in charge of transport, for he was well-informed on this matter;'
EXEC add_BibleVerse @BibleId, 113015023, N'Berechiah and Elkanah were guardians of the ark;'
EXEC add_BibleVerse @BibleId, 113015024, N'Shebaniah, Joshaphat, Nethanel, Amasai, Zechariah, Benaiah, and Eliezer the priests were to blow the trumpets before the ark of God; Obed-Edom and Jehiel were also guardians of the ark.'
EXEC add_BibleVerse @BibleId, 113015025, N'So David, the leaders of Israel, and the commanders of units of a thousand went to bring up the ark of the Lord’s covenant from the house of Obed-Edom with celebration.'
EXEC add_BibleVerse @BibleId, 113015026, N'When God helped the Levites who were carrying the ark of the Lord’s covenant, they sacrificed seven bulls and seven rams.'
EXEC add_BibleVerse @BibleId, 113015027, N'David was wrapped in a linen robe, as were all the Levites carrying the ark, the musicians, and Kenaniah the supervisor of transport and the musicians; David also wore a linen ephod.'
EXEC add_BibleVerse @BibleId, 113015028, N'All Israel brought up the ark of the Lord’s covenant; they were shouting, blowing trumpets, sounding cymbals, and playing stringed instruments.'
EXEC add_BibleVerse @BibleId, 113015029, N'As the ark of the Lord’s covenant entered the City of David, Michal, Saul’s daughter, looked out the window. When she saw King David jumping and celebrating, she despised him.'
EXEC add_BibleVerse @BibleId, 113016001, N'They brought the ark of God and put it in the middle of the tent David had pitched for it. Then they offered burnt sacrifices and peace offerings before God.'
EXEC add_BibleVerse @BibleId, 113016002, N'When David finished offering burnt sacrifices and peace offerings, he pronounced a blessing over the people in the Lord’s name.'
EXEC add_BibleVerse @BibleId, 113016003, N'He then handed out to each Israelite man and woman a loaf of bread, a date cake, and a raisin cake.'
EXEC add_BibleVerse @BibleId, 113016004, N'He appointed some of the Levites to serve before the ark of the Lord, to offer prayers, songs of thanks, and hymns to the Lord God of Israel.'
EXEC add_BibleVerse @BibleId, 113016005, N'Asaph was the leader and Zechariah second in command, followed by Jeiel, Shemiramoth, Jehiel, Mattithiah, Eliab, Benaiah, Obed-Edom, and Jeiel. They were to play stringed instruments; Asaph was to sound the cymbals;'
EXEC add_BibleVerse @BibleId, 113016006, N'and the priests Benaiah and Jahaziel were to blow trumpets regularly before the ark of God’s covenant.'
EXEC add_BibleVerse @BibleId, 113016007, N'That day David first gave to Asaph and his colleagues this song of thanks to the Lord:'
EXEC add_BibleVerse @BibleId, 113016008, N'Give thanks to the Lord! Call on his name! Make known his accomplishments among the nations!'
EXEC add_BibleVerse @BibleId, 113016009, N'Sing to him! Make music to him! Tell about all his miraculous deeds!'
EXEC add_BibleVerse @BibleId, 113016010, N'Boast about his holy name! Let the hearts of those who seek the Lord rejoice!'
EXEC add_BibleVerse @BibleId, 113016011, N'Seek the Lord and the strength he gives! Seek his presence continually!'
EXEC add_BibleVerse @BibleId, 113016012, N'Recall the miraculous deeds he performed, his mighty acts and the judgments he decreed,'
EXEC add_BibleVerse @BibleId, 113016013, N'O children of Israel, God’s servant, you descendants of Jacob, God’s chosen ones!'
EXEC add_BibleVerse @BibleId, 113016014, N'He is the Lord our God; he carries out judgment throughout the earth.'
EXEC add_BibleVerse @BibleId, 113016015, N'Remember continually his covenantal decree, the promise he made to a thousand generations –'
EXEC add_BibleVerse @BibleId, 113016016, N'the promise he made to Abraham, the promise he made by oath to Isaac!'
EXEC add_BibleVerse @BibleId, 113016017, N'He gave it to Jacob as a decree, to Israel as a lasting promise,'
EXEC add_BibleVerse @BibleId, 113016018, N'saying, “To you I will give the land of Canaan as the portion of your inheritance.”'
EXEC add_BibleVerse @BibleId, 113016019, N'When they were few in number, just a very few, and foreign residents within it,'
EXEC add_BibleVerse @BibleId, 113016020, N'they wandered from nation to nation, and from one kingdom to another.'
EXEC add_BibleVerse @BibleId, 113016021, N'He let no one oppress them, he disciplined kings for their sake,'
EXEC add_BibleVerse @BibleId, 113016022, N'saying, “Don’t touch my anointed ones! Don’t harm my prophets!”'
EXEC add_BibleVerse @BibleId, 113016023, N'Sing to the Lord, all the earth! Announce every day how he delivers!'
EXEC add_BibleVerse @BibleId, 113016024, N'Tell the nations about his splendor, tell all the nations about his miraculous deeds!'
EXEC add_BibleVerse @BibleId, 113016025, N'For the Lord is great and certainly worthy of praise, he is more awesome than all gods.'
EXEC add_BibleVerse @BibleId, 113016026, N'For all the gods of the nations are worthless, but the Lord made the heavens.'
EXEC add_BibleVerse @BibleId, 113016027, N'Majestic splendor emanates from him, he is the source of strength and joy.'
EXEC add_BibleVerse @BibleId, 113016028, N'Ascribe to the Lord, O families of the nations, ascribe to the Lord splendor and strength!'
EXEC add_BibleVerse @BibleId, 113016029, N'Ascribe to the Lord the splendor he deserves! Bring an offering and enter his presence! Worship the Lord in holy attire!'
EXEC add_BibleVerse @BibleId, 113016030, N'Tremble before him, all the earth! The world is established, it cannot be moved.'
EXEC add_BibleVerse @BibleId, 113016031, N'Let the heavens rejoice, and the earth be happy! Let the nations say, ‘The Lord reigns!’'
EXEC add_BibleVerse @BibleId, 113016032, N'Let the sea and everything in it shout! Let the fields and everything in them celebrate!'
EXEC add_BibleVerse @BibleId, 113016033, N'Then let the trees of the forest shout with joy before the Lord, for he comes to judge the earth!'
EXEC add_BibleVerse @BibleId, 113016034, N'Give thanks to the Lord, for he is good and his loyal love endures.'
EXEC add_BibleVerse @BibleId, 113016035, N'Say this prayer: “Deliver us, O God who delivers us! Gather us! Rescue us from the nations! Then we will give thanks to your holy name, and boast about your praiseworthy deeds.”'
EXEC add_BibleVerse @BibleId, 113016036, N'May the Lord God of Israel be praised, in the future and forevermore. Then all the people said, “We agree! Praise the Lord!”'
EXEC add_BibleVerse @BibleId, 113016037, N'David left Asaph and his colleagues there before the ark of the Lord’s covenant to serve before the ark regularly and fulfill each day’s requirements,'
EXEC add_BibleVerse @BibleId, 113016038, N'including Obed-Edom and sixty-eight colleagues. Obed-Edom son of Jeduthun and Hosah were gatekeepers.'
EXEC add_BibleVerse @BibleId, 113016039, N'Zadok the priest and his fellow priests served before the Lord’s tabernacle at the worship center in Gibeon,'
EXEC add_BibleVerse @BibleId, 113016040, N'regularly offering burnt sacrifices to the Lord on the altar for burnt sacrifice, morning and evening, according to what is prescribed in the law of the Lord which he charged Israel to observe.'
EXEC add_BibleVerse @BibleId, 113016041, N'Joining them were Heman, Jeduthun, and the rest of those chosen and designated by name to give thanks to the Lord. (For his loyal love endures!)'
EXEC add_BibleVerse @BibleId, 113016042, N'Heman and Jeduthun were in charge of the music, including the trumpets, cymbals, and the other musical instruments used in praising God. The sons of Jeduthun guarded the entrance.'
EXEC add_BibleVerse @BibleId, 113016043, N'Then all the people returned to their homes, and David went to pronounce a blessing on his family.'
EXEC add_BibleVerse @BibleId, 113017001, N'When David had settled into his palace, he said to Nathan the prophet, “Look, I am living in a palace made from cedar, while the ark of the Lord’s covenant is under a tent.”'
EXEC add_BibleVerse @BibleId, 113017002, N'Nathan said to David, “You should do whatever you have in mind, for God is with you.”'
EXEC add_BibleVerse @BibleId, 113017003, N'That night God told Nathan the prophet,'
EXEC add_BibleVerse @BibleId, 113017004, N'“Go, tell my servant David: ‘This is what the Lord says: “You must not build me a house in which to live.'
EXEC add_BibleVerse @BibleId, 113017005, N'For I have not lived in a house from the time I brought Israel up from Egypt to the present day. I have lived in a tent that has been in various places.'
EXEC add_BibleVerse @BibleId, 113017006, N'Wherever I moved throughout Israel, I did not say to any of the leaders whom I appointed to care for my people Israel, ‘Why have you not built me a house made from cedar?’”’'
EXEC add_BibleVerse @BibleId, 113017007, N'“So now, say this to my servant David: ‘This is what the Lord who commands armies says: “I took you from the pasture and from your work as a shepherd to make you a leader of my people Israel.'
EXEC add_BibleVerse @BibleId, 113017008, N'I was with you wherever you went and I defeated all your enemies before you. Now I will make you as famous as the great men of the earth.'
EXEC add_BibleVerse @BibleId, 113017009, N'I will establish a place for my people Israel and settle them there; they will live there and not be disturbed anymore. Violent men will not oppress them again, as they did in the beginning'
EXEC add_BibleVerse @BibleId, 113017010, N'and during the time when I appointed judges to lead my people Israel. I will subdue all your enemies. “‘“I declare to you that the Lord will build a dynastic house for you!'
EXEC add_BibleVerse @BibleId, 113017011, N'When the time comes for you to die, I will raise up your descendant, one of your own sons, to succeed you, and I will establish his kingdom.'
EXEC add_BibleVerse @BibleId, 113017012, N'He will build me a house, and I will make his dynasty permanent.'
EXEC add_BibleVerse @BibleId, 113017013, N'I will become his father and he will become my son. I will never withhold my loyal love from him, as I withheld it from the one who ruled before you.'
EXEC add_BibleVerse @BibleId, 113017014, N'I will put him in permanent charge of my house and my kingdom; his dynasty will be permanent.”’”'
EXEC add_BibleVerse @BibleId, 113017015, N'Nathan told David all these words that were revealed to him.'
EXEC add_BibleVerse @BibleId, 113017016, N'David went in, sat before the Lord, and said: “Who am I, O Lord God, and what is my family, that you should have brought me to this point?'
EXEC add_BibleVerse @BibleId, 113017017, N'And you did not stop there, O God! You have also spoken about the future of your servant’s family. You have revealed to me what men long to know, O Lord God.'
EXEC add_BibleVerse @BibleId, 113017018, N'What more can David say to you? You have honored your servant; you have given your servant special recognition.'
EXEC add_BibleVerse @BibleId, 113017019, N'O Lord, for the sake of your servant and according to your will, you have done this great thing in order to reveal your greatness.'
EXEC add_BibleVerse @BibleId, 113017020, N'O Lord, there is none like you; there is no God besides you! What we heard is true!'
EXEC add_BibleVerse @BibleId, 113017021, N'And who is like your people, Israel, a unique nation in the earth? Their God went to claim a nation for himself! You made a name for yourself by doing great and awesome deeds when you drove out nations before your people whom you had delivered from the Egyptian empire and its gods.'
EXEC add_BibleVerse @BibleId, 113017022, N'You made Israel your very own nation for all time. You, O Lord, became their God.'
EXEC add_BibleVerse @BibleId, 113017023, N'So now, O Lord, may the promise you made about your servant and his family become a permanent reality! Do as you promised,'
EXEC add_BibleVerse @BibleId, 113017024, N'so it may become a reality and you may gain lasting fame, as people say, ‘The Lord who commands armies is the God of Israel.’ David’s dynasty will be established before you,'
EXEC add_BibleVerse @BibleId, 113017025, N'for you, my God, have revealed to your servant that you will build a dynasty for him. That is why your servant has had the courage to pray to you.'
EXEC add_BibleVerse @BibleId, 113017026, N'Now, O Lord, you are the true God; you have made this good promise to your servant.'
EXEC add_BibleVerse @BibleId, 113017027, N'Now you are willing to bless your servant’s dynasty so that it may stand permanently before you, for you, O Lord, have blessed it and it will be blessed from now on into the future.”'
EXEC add_BibleVerse @BibleId, 113018001, N'Later David defeated the Philistines and subdued them. He took Gath and its surrounding towns away from the Philistines.'
EXEC add_BibleVerse @BibleId, 113018002, N'He defeated the Moabites; the Moabites became David’s subjects and brought tribute.'
EXEC add_BibleVerse @BibleId, 113018003, N'David defeated King Hadadezer of Zobah as far as Hamath, when he went to extend his authority to the Euphrates River.'
EXEC add_BibleVerse @BibleId, 113018004, N'David seized from him 1,000 chariots, 7,000 charioteers, and 20,000 infantrymen. David cut the hamstrings of all but a hundred of Hadadezer’s chariot horses.'
EXEC add_BibleVerse @BibleId, 113018005, N'The Arameans of Damascus came to help King Hadadezer of Zobah, but David killed 22,000 of the Arameans.'
EXEC add_BibleVerse @BibleId, 113018006, N'David placed garrisons in the territory of the Arameans of Damascus; the Arameans became David’s subjects and brought tribute. The Lord protected David wherever he campaigned.'
EXEC add_BibleVerse @BibleId, 113018007, N'David took the golden shields which Hadadezer’s servants had carried and brought them to Jerusalem.'
EXEC add_BibleVerse @BibleId, 113018008, N'From Tibhath and Kun, Hadadezer’s cities, David took a great deal of bronze. (Solomon used it to make the big bronze basin called “The Sea,” the pillars, and other bronze items.'
EXEC add_BibleVerse @BibleId, 113018009, N'When King Tou of Hamath heard that David had defeated the entire army of King Hadadezer of Zobah,'
EXEC add_BibleVerse @BibleId, 113018010, N'he sent his son Hadoram to King David to extend his best wishes and to pronounce a blessing on him for his victory over Hadadezer, for Tou had been at war with Hadadezer. He also sent various items made of gold, silver, and bronze.'
EXEC add_BibleVerse @BibleId, 113018011, N'King David dedicated these things to the Lord, along with the silver and gold which he had carried off from all the nations, including Edom, Moab, the Ammonites, the Philistines, and Amalek.'
EXEC add_BibleVerse @BibleId, 113018012, N'Abishai son of Zeruiah killed 18,000 Edomites in the Valley of Salt.'
EXEC add_BibleVerse @BibleId, 113018013, N'He placed garrisons in Edom, and all the Edomites became David’s subjects. The Lord protected David wherever he campaigned.'
EXEC add_BibleVerse @BibleId, 113018014, N'David reigned over all Israel; he guaranteed justice for all his people.'
EXEC add_BibleVerse @BibleId, 113018015, N'Joab son of Zeruiah was commanding general of the army; Jehoshaphat son of Ahilud was secretary;'
EXEC add_BibleVerse @BibleId, 113018016, N'Zadok son of Ahitub and Abimelech son of Abiathar were priests; Shavsha was scribe;'
EXEC add_BibleVerse @BibleId, 113018017, N'Benaiah son of Jehoiada supervised the Kerethites and Pelethites; and David’s sons were the king’s leading officials.'
EXEC add_BibleVerse @BibleId, 113019001, N'Later King Nahash of the Ammonites died and his son succeeded him.'
EXEC add_BibleVerse @BibleId, 113019002, N'David said, “I will express my loyalty to Hanun son of Nahash, for his father was loyal to me.” So David sent messengers to express his sympathy over his father’s death. When David’s servants entered Ammonite territory to visit Hanun and express the king’s sympathy,'
EXEC add_BibleVerse @BibleId, 113019003, N'the Ammonite officials said to Hanun, “Do you really think David is trying to honor your father by sending these messengers to express his sympathy? No, his servants have come to you so they can get information and spy out the land!”'
EXEC add_BibleVerse @BibleId, 113019004, N'So Hanun seized David’s servants and shaved their beards off. He cut off the lower part of their robes so that their buttocks were exposed and then sent them away.'
EXEC add_BibleVerse @BibleId, 113019005, N'Messengers came and told David what had happened to the men, so he summoned them, for the men were thoroughly humiliated. The king said, “Stay in Jericho until your beards grow again; then you may come back.”'
EXEC add_BibleVerse @BibleId, 113019006, N'When the Ammonites realized that David was disgusted with them, Hanun and the Ammonites sent 1,000 talents of silver to hire chariots and charioteers from Aram Naharaim, Aram Maacah, and Zobah.'
EXEC add_BibleVerse @BibleId, 113019007, N'They hired 32,000 chariots, along with the king of Maacah and his army, who came and camped in front of Medeba. The Ammonites also assembled from their cities and marched out to do battle.'
EXEC add_BibleVerse @BibleId, 113019008, N'When David heard the news, he sent Joab and the entire army to meet them.'
EXEC add_BibleVerse @BibleId, 113019009, N'The Ammonites marched out and were deployed for battle at the entrance to the city, while the kings who had come were by themselves in the field.'
EXEC add_BibleVerse @BibleId, 113019010, N'When Joab saw that the battle would be fought on two fronts, he chose some of Israel’s best men and deployed them against the Arameans.'
EXEC add_BibleVerse @BibleId, 113019011, N'He put his brother Abishai in charge of the rest of the army and they were deployed against the Ammonites.'
EXEC add_BibleVerse @BibleId, 113019012, N'Joab said, “If the Arameans start to overpower me, you come to my rescue. If the Ammonites start to overpower you, I will come to your rescue.'
EXEC add_BibleVerse @BibleId, 113019013, N'Be strong! Let’s fight bravely for the sake of our people and the cities of our God! The Lord will do what he decides is best!”'
EXEC add_BibleVerse @BibleId, 113019014, N'So Joab and his men marched toward the Arameans to do battle, and they fled before him.'
EXEC add_BibleVerse @BibleId, 113019015, N'When the Ammonites saw the Arameans flee, they fled before Joab’s brother Abishai and withdrew into the city. Joab went back to Jerusalem.'
EXEC add_BibleVerse @BibleId, 113019016, N'When the Arameans realized they had been defeated by Israel, they sent for reinforcements from beyond the Euphrates River, led by Shophach the commanding general of Hadadezer’s army.'
EXEC add_BibleVerse @BibleId, 113019017, N'When David was informed, he gathered all Israel, crossed the Jordan River, and marched against them. David deployed his army against the Arameans for battle and they fought against him.'
EXEC add_BibleVerse @BibleId, 113019018, N'The Arameans fled before Israel. David killed 7,000 Aramean charioteers and 40,000 infantrymen; he also killed Shophach the commanding general.'
EXEC add_BibleVerse @BibleId, 113019019, N'When Hadadezer’s subjects saw they were defeated by Israel, they made peace with David and became his subjects. The Arameans were no longer willing to help the Ammonites.'
EXEC add_BibleVerse @BibleId, 113020001, N'In the spring, at the time when kings normally conduct wars, Joab led the army into battle and devastated the land of the Ammonites. He went and besieged Rabbah, while David stayed in Jerusalem. Joab defeated Rabbah and tore it down.'
EXEC add_BibleVerse @BibleId, 113020002, N'David took the crown from the head of their king and wore it (its weight was a talent of gold and it was set with precious stones). He took a large amount of plunder from the city.'
EXEC add_BibleVerse @BibleId, 113020003, N'He removed the city’s residents and made them do hard labor with saws, iron picks, and axes. This was his policy with all the Ammonite cities. Then David and all the army returned to Jerusalem.'
EXEC add_BibleVerse @BibleId, 113020004, N'Later there was a battle with the Philistines in Gezer. At that time Sibbekai the Hushathite killed Sippai, one of the descendants of the Rephaim, and the Philistines were subdued.'
EXEC add_BibleVerse @BibleId, 113020005, N'There was another battle with the Philistines in which Elhanan son of Jair the Bethlehemite killed the brother of Goliath the Gittite, whose spear had a shaft as big as the crossbeam of a weaver’s loom.'
EXEC add_BibleVerse @BibleId, 113020006, N'In a battle in Gath there was a large man who had six fingers on each hand and six toes on each foot – twenty-four in all! He too was a descendant of Rapha.'
EXEC add_BibleVerse @BibleId, 113020007, N'When he taunted Israel, Jonathan son of Shimea, David’s brother, killed him.'
EXEC add_BibleVerse @BibleId, 113020008, N'These were the descendants of Rapha who lived in Gath; they were killed by the hand of David and his soldiers.'
EXEC add_BibleVerse @BibleId, 113021001, N'An adversary opposed Israel, inciting David to count how many warriors Israel had.'
EXEC add_BibleVerse @BibleId, 113021002, N'David told Joab and the leaders of the army, “Go, count the number of warriors from Beer Sheba to Dan. Then bring back a report to me so I may know how many we have.”'
EXEC add_BibleVerse @BibleId, 113021003, N'Joab replied, “May the Lord make his army a hundred times larger! My master, O king, do not all of them serve my master? Why does my master want to do this? Why bring judgment on Israel?”'
EXEC add_BibleVerse @BibleId, 113021004, N'But the king’s edict stood, despite Joab’s objections. So Joab left and traveled throughout Israel before returning to Jerusalem.'
EXEC add_BibleVerse @BibleId, 113021005, N'Joab reported to David the number of warriors. In all Israel there were 1,100,000 sword-wielding soldiers; Judah alone had 470,000 sword-wielding soldiers.'
EXEC add_BibleVerse @BibleId, 113021006, N'Now Joab did not number Levi and Benjamin, for the king’s edict disgusted him.'
EXEC add_BibleVerse @BibleId, 113021007, N'God was also offended by it, so he attacked Israel.'
EXEC add_BibleVerse @BibleId, 113021008, N'David said to God, “I have sinned greatly by doing this! Now, please remove the guilt of your servant, for I have acted very foolishly.”'
EXEC add_BibleVerse @BibleId, 113021009, N'The Lord told Gad, David’s prophet,'
EXEC add_BibleVerse @BibleId, 113021010, N'“Go, tell David, ‘This is what the Lord says: “I am offering you three forms of judgment from which to choose. Pick one of them.”’”'
EXEC add_BibleVerse @BibleId, 113021011, N'Gad went to David and told him, “This is what the Lord says: ‘Pick one of these:'
EXEC add_BibleVerse @BibleId, 113021012, N'three years of famine, or three months being chased by your enemies and struck down by their swords, or three days being struck down by the Lord, during which a plague will invade the land and the Lord’s messenger will destroy throughout Israel’s territory.’ Now, decide what I should tell the one who sent me.”'
EXEC add_BibleVerse @BibleId, 113021013, N'David said to Gad, “I am very upset! I prefer to be attacked by the Lord, for his mercy is very great; I do not want to be attacked by men!”'
EXEC add_BibleVerse @BibleId, 113021014, N'So the Lord sent a plague through Israel, and 70,000 Israelite men died.'
EXEC add_BibleVerse @BibleId, 113021015, N'God sent an angel to ravage Jerusalem. As he was doing so, the Lord watched and relented from his judgment. He told the angel who was destroying, “That’s enough! Stop now!” Now the Lord’s angel was standing near the threshing floor of Ornan the Jebusite.'
EXEC add_BibleVerse @BibleId, 113021016, N'David looked up and saw the Lord’s messenger standing between the earth and sky with his sword drawn and in his hand, stretched out over Jerusalem. David and the leaders, covered with sackcloth, threw themselves down with their faces to the ground.'
EXEC add_BibleVerse @BibleId, 113021017, N'David said to God, “Was I not the one who decided to number the army? I am the one who sinned and committed this awful deed! As for these sheep – what have they done? O Lord my God, attack me and my family, but remove the plague from your people!”'
EXEC add_BibleVerse @BibleId, 113021018, N'So the Lord’s messenger told Gad to instruct David to go up and build an altar for the Lord on the threshing floor of Ornan the Jebusite.'
EXEC add_BibleVerse @BibleId, 113021019, N'So David went up as Gad instructed him to do in the name of the Lord.'
EXEC add_BibleVerse @BibleId, 113021020, N'While Ornan was threshing wheat, he turned and saw the messenger, and he and his four sons hid themselves.'
EXEC add_BibleVerse @BibleId, 113021021, N'When David came to Ornan, Ornan looked and saw David; he came out from the threshing floor and bowed to David with his face to the ground.'
EXEC add_BibleVerse @BibleId, 113021022, N'David said to Ornan, “Sell me the threshing floor so I can build on it an altar for the Lord – I’ll pay top price – so that the plague may be removed from the people.”'
EXEC add_BibleVerse @BibleId, 113021023, N'Ornan told David, “You can have it! My master, the king, may do what he wants. Look, I am giving you the oxen for burnt sacrifices, the threshing sledges for wood, and the wheat for an offering. I give it all to you.”'
EXEC add_BibleVerse @BibleId, 113021024, N'King David replied to Ornan, “No, I insist on buying it for top price. I will not offer to the Lord what belongs to you or offer a burnt sacrifice that cost me nothing.'
EXEC add_BibleVerse @BibleId, 113021025, N'So David bought the place from Ornan for 600 pieces of gold.'
EXEC add_BibleVerse @BibleId, 113021026, N'David built there an altar to the Lord and offered burnt sacrifices and peace offerings. He called out to the Lord, and the Lord responded by sending fire from the sky and consuming the burnt sacrifice on the altar.'
EXEC add_BibleVerse @BibleId, 113021027, N'The Lord ordered the messenger to put his sword back into its sheath.'
EXEC add_BibleVerse @BibleId, 113021028, N'At that time, when David saw that the Lord responded to him at the threshing floor of Ornan the Jebusite, he sacrificed there.'
EXEC add_BibleVerse @BibleId, 113021029, N'Now the Lord’s tabernacle (which Moses had made in the wilderness) and the altar for burnt sacrifices were at that time at the worship center in Gibeon.'
EXEC add_BibleVerse @BibleId, 113021030, N'But David could not go before it to seek God’s will, for he was afraid of the sword of the Lord’s messenger.'
EXEC add_BibleVerse @BibleId, 113022001, N'David then said, “This is the place where the temple of the Lord God will be, along with the altar for burnt sacrifices for Israel.”'
EXEC add_BibleVerse @BibleId, 113022002, N'David ordered the resident foreigners in the land of Israel to be called together. He appointed some of them to be stonecutters to chisel stones for the building of God’s temple.'
EXEC add_BibleVerse @BibleId, 113022003, N'David supplied a large amount of iron for the nails of the doors of the gates and for braces, more bronze than could be weighed,'
EXEC add_BibleVerse @BibleId, 113022004, N'and more cedar logs than could be counted. (The Sidonians and Tyrians had brought a large amount of cedar logs to David.)'
EXEC add_BibleVerse @BibleId, 113022005, N'David said, “My son Solomon is just an inexperienced young man, and the temple to be built for the Lord must be especially magnificent so it will become famous and be considered splendid by all the nations. Therefore I will make preparations for its construction.” So David made extensive preparations before he died.'
EXEC add_BibleVerse @BibleId, 113022006, N'He summoned his son Solomon and charged him to build a temple for the Lord God of Israel.'
EXEC add_BibleVerse @BibleId, 113022007, N'David said to Solomon: “My son, I really wanted to build a temple to honor the Lord my God.'
EXEC add_BibleVerse @BibleId, 113022008, N'But the Lord said to me: ‘You have spilled a great deal of blood and fought many battles. You must not build a temple to honor me, for you have spilled a great deal of blood on the ground before me.'
EXEC add_BibleVerse @BibleId, 113022009, N'Look, you will have a son, who will be a peaceful man. I will give him rest from all his enemies on every side. Indeed, Solomon will be his name; I will give Israel peace and quiet during his reign.'
EXEC add_BibleVerse @BibleId, 113022010, N'He will build a temple to honor me; he will become my son, and I will become his father. I will grant to his dynasty permanent rule over Israel.’'
EXEC add_BibleVerse @BibleId, 113022011, N'“Now, my son, may the Lord be with you! May you succeed and build a temple for the Lord your God, just as he announced you would.'
EXEC add_BibleVerse @BibleId, 113022012, N'Only may the Lord give you insight and understanding when he places you in charge of Israel, so you may obey the law of the Lord your God.'
EXEC add_BibleVerse @BibleId, 113022013, N'Then you will succeed, if you carefully obey the rules and regulations which the Lord ordered Moses to give to Israel. Be strong and brave! Don’t be afraid and don’t panic!'
EXEC add_BibleVerse @BibleId, 113022014, N'Now, look, I have made every effort to supply what is needed to build the Lord’s temple. I have stored up 100,000 talents of gold, 1,000,000 talents of silver, and so much bronze and iron it cannot be weighed, as well as wood and stones. Feel free to add more!'
EXEC add_BibleVerse @BibleId, 113022015, N'You also have available many workers, including stonecutters, masons, carpenters, and an innumerable array of workers who are skilled'
EXEC add_BibleVerse @BibleId, 113022016, N'in using gold, silver, bronze, and iron. Get up and begin the work! May the Lord be with you!”'
EXEC add_BibleVerse @BibleId, 113022017, N'David ordered all the officials of Israel to support his son Solomon.'
EXEC add_BibleVerse @BibleId, 113022018, N'He told them, “The Lord your God is with you! He has made you secure on every side, for he handed over to me the inhabitants of the region and the region is subdued before the Lord and his people.'
EXEC add_BibleVerse @BibleId, 113022019, N'Now seek the Lord your God wholeheartedly and with your entire being! Get up and build the sanctuary of the Lord God! Then you can bring the ark of the Lord’s covenant and the holy items dedicated to God’s service into the temple that is built to honor the Lord.”'
EXEC add_BibleVerse @BibleId, 113023001, N'When David was old and approaching the end of his life, he made his son Solomon king over Israel.'
EXEC add_BibleVerse @BibleId, 113023002, N'David assembled all the leaders of Israel, along with the priests and the Levites.'
EXEC add_BibleVerse @BibleId, 113023003, N'The Levites who were thirty years old and up were counted; there were 38,000 men.'
EXEC add_BibleVerse @BibleId, 113023004, N'David said, “Of these, 24,000 are to direct the work of the Lord’s temple; 6,000 are to be officials and judges;'
EXEC add_BibleVerse @BibleId, 113023005, N'4,000 are to be gatekeepers; and 4,000 are to praise the Lord with the instruments I supplied for worship.”'
EXEC add_BibleVerse @BibleId, 113023006, N'David divided them into groups corresponding to the sons of Levi: Gershon, Kohath, and Merari.'
EXEC add_BibleVerse @BibleId, 113023007, N'The Gershonites included Ladan and Shimei.'
EXEC add_BibleVerse @BibleId, 113023008, N'The sons of Ladan: Jehiel the oldest, Zetham, and Joel – three in all.'
EXEC add_BibleVerse @BibleId, 113023009, N'The sons of Shimei: Shelomoth, Haziel, and Haran – three in all. These were the leaders of the family of Ladan.'
EXEC add_BibleVerse @BibleId, 113023010, N'The sons of Shimei: Jahath, Zina, Jeush, and Beriah. These were Shimei’s sons – four in all.'
EXEC add_BibleVerse @BibleId, 113023011, N'Jahath was the oldest and Zizah the second oldest. Jeush and Beriah did not have many sons, so they were considered one family with one responsibility.'
EXEC add_BibleVerse @BibleId, 113023012, N'The sons of Kohath: Amram, Izhar, Hebron, and Uzziel – four in all.'
EXEC add_BibleVerse @BibleId, 113023013, N'The sons of Amram: Aaron and Moses. Aaron and his descendants were chosen on a permanent basis to consecrate the most holy items, to offer sacrifices before the Lord, to serve him, and to praise his name.'
EXEC add_BibleVerse @BibleId, 113023014, N'The descendants of Moses the man of God were considered Levites.'
EXEC add_BibleVerse @BibleId, 113023015, N'The sons of Moses: Gershom and Eliezer.'
EXEC add_BibleVerse @BibleId, 113023016, N'The son of Gershom: Shebuel the oldest.'
EXEC add_BibleVerse @BibleId, 113023017, N'The son of Eliezer was Rehabiah, the oldest. Eliezer had no other sons, but Rehabiah had many descendants.'
EXEC add_BibleVerse @BibleId, 113023018, N'The son of Izhar: Shelomith the oldest.'
EXEC add_BibleVerse @BibleId, 113023019, N'The sons of Hebron: Jeriah the oldest, Amariah the second, Jahaziel the third, and Jekameam the fourth.'
EXEC add_BibleVerse @BibleId, 113023020, N'The sons of Uzziel: Micah the oldest, and Isshiah the second.'
EXEC add_BibleVerse @BibleId, 113023021, N'The sons of Merari: Mahli and Mushi. The sons of Mahli: Eleazar and Kish.'
EXEC add_BibleVerse @BibleId, 113023022, N'Eleazar died without having sons; he had only daughters. The sons of Kish, their cousins, married them.'
EXEC add_BibleVerse @BibleId, 113023023, N'The sons of Mushi: Mahli, Eder, and Jeremoth – three in all.'
EXEC add_BibleVerse @BibleId, 113023024, N'These were the descendants of Levi according to their families, that is, the leaders of families as counted and individually listed who carried out assigned tasks in the Lord’s temple and were twenty years old and up.'
EXEC add_BibleVerse @BibleId, 113023025, N'For David said, “The Lord God of Israel has given his people rest and has permanently settled in Jerusalem.'
EXEC add_BibleVerse @BibleId, 113023026, N'So the Levites no longer need to carry the tabernacle or any of the items used in its service.”'
EXEC add_BibleVerse @BibleId, 113023027, N'According to David’s final instructions, the Levites twenty years old and up were counted.'
EXEC add_BibleVerse @BibleId, 113023028, N'Their job was to help Aaron’s descendants in the service of the Lord’s temple. They were to take care of the courtyards, the rooms, ceremonial purification of all holy items, and other jobs related to the service of God’s temple.'
EXEC add_BibleVerse @BibleId, 113023029, N'They also took care of the bread that is displayed, the flour for offerings, the unleavened wafers, the round cakes, the mixing, and all the measuring.'
EXEC add_BibleVerse @BibleId, 113023030, N'They also stood in a designated place every morning and offered thanks and praise to the Lord. They also did this in the evening'
EXEC add_BibleVerse @BibleId, 113023031, N'and whenever burnt sacrifices were offered to the Lord on the Sabbath and at new moon festivals and assemblies. A designated number were to serve before the Lord regularly in accordance with regulations.'
EXEC add_BibleVerse @BibleId, 113023032, N'They were in charge of the meeting tent and the holy place, and helped their relatives, the descendants of Aaron, in the service of the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 113024001, N'The divisions of Aaron’s descendants were as follows: The sons of Aaron: Nadab, Abihu, Eleazar, and Ithamar.'
EXEC add_BibleVerse @BibleId, 113024002, N'Nadab and Abihu died before their father did; they had no sons. Eleazar and Ithamar served as priests.'
EXEC add_BibleVerse @BibleId, 113024003, N'David, Zadok (a descendant of Eleazar), and Ahimelech (a descendant of Ithamar) divided them into groups to carry out their assigned responsibilities.'
EXEC add_BibleVerse @BibleId, 113024004, N'The descendants of Eleazar had more leaders than the descendants of Ithamar, so they divided them up accordingly; the descendants of Eleazar had sixteen leaders, while the descendants of Ithamar had eight.'
EXEC add_BibleVerse @BibleId, 113024005, N'They divided them by lots, for there were officials of the holy place and officials designated by God among the descendants of both Eleazar and Ithamar.'
EXEC add_BibleVerse @BibleId, 113024006, N'The scribe Shemaiah son of Nethanel, a Levite, wrote down their names before the king, the officials, Zadok the priest, Ahimelech son of Abiathar, and the leaders of the priestly and Levite families. One family was drawn by lot from Eleazar, and then the next from Ithamar.'
EXEC add_BibleVerse @BibleId, 113024007, N'The first lot went to Jehoiarib, the second to Jedaiah,'
EXEC add_BibleVerse @BibleId, 113024008, N'the third to Harim, the fourth to Seorim,'
EXEC add_BibleVerse @BibleId, 113024009, N'the fifth to Malkijah, the sixth to Mijamin,'
EXEC add_BibleVerse @BibleId, 113024010, N'the seventh to Hakkoz, the eighth to Abijah,'
EXEC add_BibleVerse @BibleId, 113024011, N'the ninth to Jeshua, the tenth to Shecaniah,'
EXEC add_BibleVerse @BibleId, 113024012, N'the eleventh to Eliashib, the twelfth to Jakim,'
EXEC add_BibleVerse @BibleId, 113024013, N'the thirteenth to Huppah, the fourteenth to Jeshebeab,'
EXEC add_BibleVerse @BibleId, 113024014, N'the fifteenth to Bilgah, the sixteenth to Immer,'
EXEC add_BibleVerse @BibleId, 113024015, N'the seventeenth to Hezir, the eighteenth to Happizzez,'
EXEC add_BibleVerse @BibleId, 113024016, N'the nineteenth to Pethahiah, the twentieth to Jehezkel,'
EXEC add_BibleVerse @BibleId, 113024017, N'the twenty-first to Jakin, the twenty-second to Gamul,'
EXEC add_BibleVerse @BibleId, 113024018, N'the twenty-third to Delaiah, the twenty-fourth to Maaziah.'
EXEC add_BibleVerse @BibleId, 113024019, N'This was the order in which they carried out their assigned responsibilities when they entered the Lord’s temple, according to the regulations given them by their ancestor Aaron, just as the Lord God of Israel had instructed him.'
EXEC add_BibleVerse @BibleId, 113024020, N'The rest of the Levites included: Shubael from the sons of Amram, Jehdeiah from the sons of Shubael,'
EXEC add_BibleVerse @BibleId, 113024021, N'the firstborn Isshiah from Rehabiah and the sons of Rehabiah,'
EXEC add_BibleVerse @BibleId, 113024022, N'Shelomoth from the Izharites, Jahath from the sons of Shelomoth.'
EXEC add_BibleVerse @BibleId, 113024023, N'The sons of Hebron: Jeriah, Amariah the second, Jahaziel the third, and Jekameam the fourth.'
EXEC add_BibleVerse @BibleId, 113024024, N'The son of Uzziel: Micah; Shamir from the sons of Micah.'
EXEC add_BibleVerse @BibleId, 113024025, N'The brother of Micah: Isshiah. Zechariah from the sons of Isshiah.'
EXEC add_BibleVerse @BibleId, 113024026, N'The sons of Merari: Mahli and Mushi. The son of Jaaziah: Beno.'
EXEC add_BibleVerse @BibleId, 113024027, N'The sons of Merari, from Jaaziah: Beno, Shoham, Zaccur, and Ibri.'
EXEC add_BibleVerse @BibleId, 113024028, N'From Mahli: Eleazar, who had no sons.'
EXEC add_BibleVerse @BibleId, 113024029, N'From Kish: Jerahmeel.'
EXEC add_BibleVerse @BibleId, 113024030, N'The sons of Mushi: Mahli, Eder, and Jerimoth. These were the Levites, listed by their families.'
EXEC add_BibleVerse @BibleId, 113024031, N'Just like their relatives, the descendants of Aaron, they also cast lots before King David, Zadok, Ahimelech, the leaders of families, the priests, and the Levites. The families of the oldest son cast lots along with the those of the youngest.'
EXEC add_BibleVerse @BibleId, 113025001, N'David and the army officers selected some of the sons of Asaph, Heman, and Jeduthun to prophesy as they played stringed instruments and cymbals. The following men were assigned this responsibility:'
EXEC add_BibleVerse @BibleId, 113025002, N'From the sons of Asaph: Zaccur, Joseph, Nethaniah, and Asarelah. The sons of Asaph were supervised by Asaph, who prophesied under the king’s supervision.'
EXEC add_BibleVerse @BibleId, 113025003, N'From the sons of Jeduthun: Gedaliah, Zeri, Jeshaiah, Hashabiah, and Mattithiah – six in all, under supervision of their father Jeduthun, who prophesied as he played a harp, giving thanks and praise to the Lord.'
EXEC add_BibleVerse @BibleId, 113025004, N'From the sons of Heman: Bukkiah, Mattaniah, Uzziel, Shebuel, Jerimoth, Hananiah, Hanani, Eliathah, Giddalti, Romamti-Ezer, Joshbekashah, Mallothi, Hothir, and Mahazioth.'
EXEC add_BibleVerse @BibleId, 113025005, N'All these were the sons of Heman, the king’s prophet. God had promised him these sons in order to make him prestigious. God gave Heman fourteen sons and three daughters.'
EXEC add_BibleVerse @BibleId, 113025006, N'All of these were under the supervision of their fathers; they were musicians in the Lord’s temple, playing cymbals and stringed instruments as they served in God’s temple. Asaph, Jeduthun, and Heman were under the supervision of the king.'
EXEC add_BibleVerse @BibleId, 113025007, N'They and their relatives, all of them skilled and trained to make music to the Lord, numbered two hundred eighty-eight.'
EXEC add_BibleVerse @BibleId, 113025008, N'They cast lots to determine their responsibilities – oldest as well as youngest, teacher as well as student.'
EXEC add_BibleVerse @BibleId, 113025009, N'The first lot went to Asaph’s son Joseph and his relatives and sons – twelve in all, the second to Gedaliah and his relatives and sons – twelve in all,'
EXEC add_BibleVerse @BibleId, 113025010, N'the third to Zaccur and his sons and relatives – twelve in all,'
EXEC add_BibleVerse @BibleId, 113025011, N'the fourth to Izri and his sons and relatives – twelve in all,'
EXEC add_BibleVerse @BibleId, 113025012, N'the fifth to Nethaniah and his sons and relatives – twelve in all,'
EXEC add_BibleVerse @BibleId, 113025013, N'the sixth to Bukkiah and his sons and relatives – twelve in all,'
EXEC add_BibleVerse @BibleId, 113025014, N'the seventh to Jesharelah and his sons and relatives – twelve in all,'
EXEC add_BibleVerse @BibleId, 113025015, N'the eighth to Jeshaiah and his sons and relatives – twelve in all,'
EXEC add_BibleVerse @BibleId, 113025016, N'the ninth to Mattaniah and his sons and relatives – twelve in all,'
EXEC add_BibleVerse @BibleId, 113025017, N'the tenth to Shimei and his sons and relatives – twelve in all,'
EXEC add_BibleVerse @BibleId, 113025018, N'the eleventh to Azarel and his sons and relatives – twelve in all,'
EXEC add_BibleVerse @BibleId, 113025019, N'the twelfth to Hashabiah and his sons and relatives – twelve in all,'
EXEC add_BibleVerse @BibleId, 113025020, N'the thirteenth to Shubael and his sons and relatives – twelve in all,'
EXEC add_BibleVerse @BibleId, 113025021, N'the fourteenth to Mattithiah and his sons and relatives – twelve in all,'
EXEC add_BibleVerse @BibleId, 113025022, N'the fifteenth to Jerimoth and his sons and relatives – twelve in all,'
EXEC add_BibleVerse @BibleId, 113025023, N'the sixteenth to Hananiah and his sons and relatives – twelve in all,'
EXEC add_BibleVerse @BibleId, 113025024, N'the seventeenth to Joshbekashah and his sons and relatives – twelve in all,'
EXEC add_BibleVerse @BibleId, 113025025, N'the eighteenth to Hanani and his sons and relatives – twelve in all,'
EXEC add_BibleVerse @BibleId, 113025026, N'the nineteenth to Mallothi and his sons and relatives – twelve in all,'
EXEC add_BibleVerse @BibleId, 113025027, N'the twentieth to Eliathah and his sons and relatives – twelve in all,'
EXEC add_BibleVerse @BibleId, 113025028, N'the twenty-first to Hothir and his sons and relatives – twelve in all,'
EXEC add_BibleVerse @BibleId, 113025029, N'the twenty-second to Giddalti and his sons and relatives – twelve in all,'
EXEC add_BibleVerse @BibleId, 113025030, N'the twenty-third to Mahazioth and his sons and relatives – twelve in all,'
EXEC add_BibleVerse @BibleId, 113025031, N'the twenty-fourth to Romamti-Ezer and his sons and relatives – twelve in all.'
EXEC add_BibleVerse @BibleId, 113026001, N'The divisions of the gatekeepers: From the Korahites: Meshelemiah, son of Kore, one of the sons of Asaph.'
EXEC add_BibleVerse @BibleId, 113026002, N'Meshelemiah’s sons: The firstborn Zechariah, the second Jediael, the third Zebadiah, the fourth Jathniel,'
EXEC add_BibleVerse @BibleId, 113026003, N'the fifth Elam, the sixth Jehohanan, and the seventh Elihoenai.'
EXEC add_BibleVerse @BibleId, 113026004, N'Obed-Edom’s sons: The firstborn Shemaiah, the second Jehozabad, the third Joah, the fourth Sakar, the fifth Nethanel,'
EXEC add_BibleVerse @BibleId, 113026005, N'the sixth Ammiel, the seventh Issachar, and the eighth Peullethai. (Indeed, God blessed Obed-Edom.)'
EXEC add_BibleVerse @BibleId, 113026006, N'His son Shemaiah also had sons, who were leaders of their families, for they were highly respected.'
EXEC add_BibleVerse @BibleId, 113026007, N'The sons of Shemaiah: Othni, Rephael, Obed, and Elzabad. His relatives Elihu and Semakiah were also respected.'
EXEC add_BibleVerse @BibleId, 113026008, N'All these were the descendants of Obed-Edom. They and their sons and relatives were respected men, capable of doing their responsibilities. There were sixty-two of them related to Obed-Edom.'
EXEC add_BibleVerse @BibleId, 113026009, N'Meshelemiah had sons and relatives who were respected – eighteen in all.'
EXEC add_BibleVerse @BibleId, 113026010, N'Hosah, one of the descendants of Merari, had sons: The firstborn Shimri (he was not actually the firstborn, but his father gave him that status),'
EXEC add_BibleVerse @BibleId, 113026011, N'the second Hilkiah, the third Tebaliah, and the fourth Zechariah. All of Hosah’s sons and relatives numbered thirteen.'
EXEC add_BibleVerse @BibleId, 113026012, N'These divisions of the gatekeepers, corresponding to their leaders, had assigned responsibilities, like their relatives, as they served in the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 113026013, N'They cast lots, both young and old, according to their families, to determine which gate they would be responsible for.'
EXEC add_BibleVerse @BibleId, 113026014, N'The lot for the east gate went to Shelemiah. They then cast lots for his son Zechariah, a wise adviser, and the lot for the north gate went to him.'
EXEC add_BibleVerse @BibleId, 113026015, N'Obed-Edom was assigned the south gate, and his sons were assigned the storehouses.'
EXEC add_BibleVerse @BibleId, 113026016, N'Shuppim and Hosah were assigned the west gate, along with the Shalleketh gate on the upper road. One guard was adjacent to another.'
EXEC add_BibleVerse @BibleId, 113026017, N'Each day there were six Levites posted on the east, four on the north, and four on the south. At the storehouses they were posted in pairs.'
EXEC add_BibleVerse @BibleId, 113026018, N'At the court on the west there were four posted on the road and two at the court.'
EXEC add_BibleVerse @BibleId, 113026019, N'These were the divisions of the gatekeepers who were descendants of Korah and Merari.'
EXEC add_BibleVerse @BibleId, 113026020, N'Their fellow Levites were in charge of the storehouses in God’s temple and the storehouses containing consecrated items.'
EXEC add_BibleVerse @BibleId, 113026021, N'The descendants of Ladan, who were descended from Gershon through Ladan and were leaders of the families of Ladan the Gershonite, included Jehieli'
EXEC add_BibleVerse @BibleId, 113026022, N'and the sons of Jehieli, Zetham and his brother Joel. They were in charge of the storehouses in the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 113026023, N'As for the Amramites, Izharites, Hebronites, and Uzzielites:'
EXEC add_BibleVerse @BibleId, 113026024, N'Shebuel son of Gershom, the son of Moses, was the supervisor of the storehouses.'
EXEC add_BibleVerse @BibleId, 113026025, N'His relatives through Eliezer included: Rehabiah his son, Jeshaiah his son, Joram his son, Zikri his son, and Shelomith his son.'
EXEC add_BibleVerse @BibleId, 113026026, N'Shelomith and his relatives were in charge of all the storehouses containing the consecrated items dedicated by King David, the family leaders who led units of a thousand and a hundred, and the army officers.'
EXEC add_BibleVerse @BibleId, 113026027, N'They had dedicated some of the plunder taken in battles to be used for repairs on the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 113026028, N'They were also in charge of everything dedicated by Samuel the prophet, Saul son of Kish, Abner son of Ner, and Joab son of Zeruiah; Shelomith and his relatives were in charge of everything that had been dedicated.'
EXEC add_BibleVerse @BibleId, 113026029, N'As for the Izharites: Kenaniah and his sons were given responsibilities outside the temple as officers and judges over Israel.'
EXEC add_BibleVerse @BibleId, 113026030, N'As for the Hebronites: Hashabiah and his relatives, 1,700 respected men, were assigned responsibilities in Israel west of the Jordan; they did the Lord’s work and the king’s service.'
EXEC add_BibleVerse @BibleId, 113026031, N'As for the Hebronites: Jeriah was the leader of the Hebronites according to the genealogical records. In the fortieth year of David’s reign, they examined the records and discovered there were highly respected men in Jazer in Gilead.'
EXEC add_BibleVerse @BibleId, 113026032, N'Jeriah had 2,700 relatives who were respected family leaders. King David placed them in charge of the Reubenites, the Gadites, and the half-tribe of Manasseh; they took care of all matters pertaining to God and the king.'
EXEC add_BibleVerse @BibleId, 113027001, N'What follows is a list of Israelite family leaders and commanders of units of a thousand and a hundred, as well as their officers who served the king in various matters. Each division was assigned to serve for one month during the year; each consisted of 24,000 men.'
EXEC add_BibleVerse @BibleId, 113027002, N'Jashobeam son of Zabdiel was in charge of the first division, which was assigned the first month. His division consisted of 24,000 men.'
EXEC add_BibleVerse @BibleId, 113027003, N'He was a descendant of Perez; he was in charge of all the army officers for the first month.'
EXEC add_BibleVerse @BibleId, 113027004, N'Dodai the Ahohite was in charge of the division assigned the second month; Mikloth was the next in rank. His division consisted of 24,000 men.'
EXEC add_BibleVerse @BibleId, 113027005, N'The third army commander, assigned the third month, was Benaiah son of Jehoiada the priest. He was the leader of his division, which consisted of 24,000 men.'
EXEC add_BibleVerse @BibleId, 113027006, N'Benaiah was the leader of the thirty warriors and his division; his son was Ammizabad.'
EXEC add_BibleVerse @BibleId, 113027007, N'The fourth, assigned the fourth month, was Asahel, brother of Joab; his son Zebadiah succeeded him. His division consisted of 24,000 men.'
EXEC add_BibleVerse @BibleId, 113027008, N'The fifth, assigned the fifth month, was the commander Shamhuth the Izrahite. His division consisted of 24,000 men.'
EXEC add_BibleVerse @BibleId, 113027009, N'The sixth, assigned the sixth month, was Ira son of Ikkesh the Tekoite. His division consisted of 24,000 men.'
EXEC add_BibleVerse @BibleId, 113027010, N'The seventh, assigned the seventh month, was Helez the Pelonite, an Ephraimite. His division consisted of 24,000 men.'
EXEC add_BibleVerse @BibleId, 113027011, N'The eighth, assigned the eighth month, was Sibbekai the Hushathite, a Zerahite. His division consisted of 24,000 men.'
EXEC add_BibleVerse @BibleId, 113027012, N'The ninth, assigned the ninth month, was Abiezer the Anathothite, a Benjaminite. His division consisted of 24,000 men.'
EXEC add_BibleVerse @BibleId, 113027013, N'The tenth, assigned the tenth month, was Maharai the Netophathite, a Zerahite. His division consisted of 24,000 men.'
EXEC add_BibleVerse @BibleId, 113027014, N'The eleventh, assigned the eleventh month, was Benaiah the Pirathonite, an Ephraimite. His division consisted of 24,000 men.'
EXEC add_BibleVerse @BibleId, 113027015, N'The twelfth, assigned the twelfth month, was Heldai the Netophathite, a descendant of Othniel. His division consisted of 24,000 men.'
EXEC add_BibleVerse @BibleId, 113027016, N'The officers of the Israelite tribes: Eliezer son of Zikri was the leader of the Reubenites, Shephatiah son of Maacah led the Simeonites,'
EXEC add_BibleVerse @BibleId, 113027017, N'Hashabiah son of Kemuel led the Levites, Zadok led the descendants of Aaron,'
EXEC add_BibleVerse @BibleId, 113027018, N'Elihu, a brother of David, led Judah, Omri son of Michael led Issachar,'
EXEC add_BibleVerse @BibleId, 113027019, N'Ishmaiah son of Obadiah led Zebulun, Jerimoth son of Azriel led Naphtali,'
EXEC add_BibleVerse @BibleId, 113027020, N'Hoshea son of Azaziah led the Ephraimites, Joel son of Pedaiah led the half-tribe of Manasseh,'
EXEC add_BibleVerse @BibleId, 113027021, N'Iddo son of Zechariah led the half-tribe of Manasseh in Gilead, Jaasiel son of Abner led Benjamin,'
EXEC add_BibleVerse @BibleId, 113027022, N'Azarel son of Jeroham led Dan. These were the commanders of the Israelite tribes.'
EXEC add_BibleVerse @BibleId, 113027023, N'David did not count the males twenty years old and under, for the Lord had promised to make Israel as numerous as the stars in the sky.'
EXEC add_BibleVerse @BibleId, 113027024, N'Joab son of Zeruiah started to count the men but did not finish. God was angry with Israel because of this, so the number was not recorded in the scroll called The Annals of King David.'
EXEC add_BibleVerse @BibleId, 113027025, N'Azmaveth son of Adiel was in charge of the king’s storehouses; Jonathan son of Uzziah was in charge of the storehouses in the field, in the cities, in the towns, and in the towers.'
EXEC add_BibleVerse @BibleId, 113027026, N'Ezri son of Kelub was in charge of the field workers who farmed the land.'
EXEC add_BibleVerse @BibleId, 113027027, N'Shimei the Ramathite was in charge of the vineyards; Zabdi the Shiphmite was in charge of the wine stored in the vineyards.'
EXEC add_BibleVerse @BibleId, 113027028, N'Baal-Hanan the Gederite was in charge of the olive and sycamore trees in the lowlands; Joash was in charge of the storehouses of olive oil.'
EXEC add_BibleVerse @BibleId, 113027029, N'Shitrai the Sharonite was in charge of the cattle grazing in Sharon; Shaphat son of Adlai was in charge of the cattle in the valleys.'
EXEC add_BibleVerse @BibleId, 113027030, N'Obil the Ishmaelite was in charge of the camels; Jehdeiah the Meronothite was in charge of the donkeys.'
EXEC add_BibleVerse @BibleId, 113027031, N'Jaziz the Hagrite was in charge of the sheep. All these were the officials in charge of King David’s property.'
EXEC add_BibleVerse @BibleId, 113027032, N'Jonathan, David’s uncle, was a wise adviser and scribe; Jehiel son of Hacmoni cared for the king’s sons.'
EXEC add_BibleVerse @BibleId, 113027033, N'Ahithophel was the king’s adviser; Hushai the Arkite was the king’s confidant.'
EXEC add_BibleVerse @BibleId, 113027034, N'Ahithophel was succeeded by Jehoiada son of Benaiah and by Abiathar. Joab was the commanding general of the king’s army.'
EXEC add_BibleVerse @BibleId, 113028001, N'David assembled in Jerusalem all the officials of Israel, including the commanders of the tribes, the commanders of the army divisions that served the king, the commanders of units of a thousand and a hundred, the officials who were in charge of all the property and livestock of the king and his sons, the eunuchs, and the warriors, including the most skilled of them.'
EXEC add_BibleVerse @BibleId, 113028002, N'King David rose to his feet and said: “Listen to me, my brothers and my people. I wanted to build a temple where the ark of the Lord’s covenant could be placed as a footstool for our God. I have made the preparations for building it.'
EXEC add_BibleVerse @BibleId, 113028003, N'But God said to me, ‘You must not build a temple to honor me, for you are a warrior and have spilled blood.’'
EXEC add_BibleVerse @BibleId, 113028004, N'The Lord God of Israel chose me out of my father’s entire family to become king over Israel and have a permanent dynasty. Indeed, he chose Judah as leader, and my father’s family within Judah, and then he picked me out from among my father’s sons and made me king over all Israel.'
EXEC add_BibleVerse @BibleId, 113028005, N'From all the many sons the Lord has given me, he chose Solomon my son to rule on his behalf over Israel.'
EXEC add_BibleVerse @BibleId, 113028006, N'He said to me, ‘Solomon your son is the one who will build my temple and my courts, for I have chosen him to become my son and I will become his father.'
EXEC add_BibleVerse @BibleId, 113028007, N'I will establish his kingdom permanently, if he remains committed to obeying my commands and regulations, as you are doing this day.’'
EXEC add_BibleVerse @BibleId, 113028008, N'So now, in the sight of all Israel, the Lord’s assembly, and in the hearing of our God, I say this: Carefully observe all the commands of the Lord your God, so that you may possess this good land and may leave it as a permanent inheritance for your children after you.'
EXEC add_BibleVerse @BibleId, 113028009, N'“And you, Solomon my son, obey the God of your father and serve him with a submissive attitude and a willing spirit, for the Lord examines all minds and understands every motive of one’s thoughts. If you seek him, he will let you find him, but if you abandon him, he will reject you permanently.'
EXEC add_BibleVerse @BibleId, 113028010, N'Realize now that the Lord has chosen you to build a temple as his sanctuary. Be strong and do it!”'
EXEC add_BibleVerse @BibleId, 113028011, N'David gave to his son Solomon the blueprints for the temple porch, its buildings, its treasuries, its upper areas, its inner rooms, and the room for atonement.'
EXEC add_BibleVerse @BibleId, 113028012, N'He gave him the blueprints of all he envisioned for the courts of the Lord’s temple, all the surrounding rooms, the storehouses of God’s temple, and the storehouses for the holy items.'
EXEC add_BibleVerse @BibleId, 113028013, N'He gave him the regulations for the divisions of priests and Levites, for all the assigned responsibilities within the Lord’s temple, and for all the items used in the service of the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 113028014, N'He gave him the prescribed weight for all the gold items to be used in various types of service in the Lord’s temple, for all the silver items to be used in various types of service,'
EXEC add_BibleVerse @BibleId, 113028015, N'for the gold lampstands and their gold lamps, including the weight of each lampstand and its lamps, for the silver lampstands, including the weight of each lampstand and its lamps, according to the prescribed use of each lampstand,'
EXEC add_BibleVerse @BibleId, 113028016, N'for the gold used in the display tables, including the amount to be used in each table, for the silver to be used in the silver tables,'
EXEC add_BibleVerse @BibleId, 113028017, N'for the pure gold used for the meat forks, bowls, and jars, for the small gold bowls, including the weight for each bowl, for the small silver bowls, including the weight for each bowl,'
EXEC add_BibleVerse @BibleId, 113028018, N'and for the refined gold of the incense altar. He gave him the blueprint for the seat of the gold cherubim that spread their wings and provide shelter for the ark of the Lord’s covenant.'
EXEC add_BibleVerse @BibleId, 113028019, N'David said, “All of this I put in writing as the Lord directed me and gave me insight regarding the details of the blueprints.”'
EXEC add_BibleVerse @BibleId, 113028020, N'David said to his son Solomon: “Be strong and brave! Do it! Don’t be afraid and don’t panic! For the Lord God, my God, is with you. He will not leave you or abandon you before all the work for the service of the Lord’s temple is finished.'
EXEC add_BibleVerse @BibleId, 113028021, N'Here are the divisions of the priests and Levites who will perform all the service of God’s temple. All the willing and skilled men are ready to assist you in all the work and perform their service. The officials and all the people are ready to follow your instructions.”'
EXEC add_BibleVerse @BibleId, 113029001, N'King David said to the entire assembly: “My son Solomon, the one whom God has chosen, is just an inexperienced young man, and the task is great, for this palace is not for man, but for the Lord God.'
EXEC add_BibleVerse @BibleId, 113029002, N'So I have made every effort to provide what is needed for the temple of my God, including the gold, silver, bronze, iron, wood, as well as a large amount of onyx, settings of antimony and other stones, all kinds of precious stones, and alabaster.'
EXEC add_BibleVerse @BibleId, 113029003, N'Now, to show my commitment to the temple of my God, I donate my personal treasure of gold and silver to the temple of my God, in addition to all that I have already supplied for this holy temple.'
EXEC add_BibleVerse @BibleId, 113029004, N'This includes 3,000 talents of gold from Ophir and 7,000 talents of refined silver for overlaying the walls of the buildings,'
EXEC add_BibleVerse @BibleId, 113029005, N'for gold and silver items, and for all the work of the craftsmen. Who else wants to contribute to the Lord today?”'
EXEC add_BibleVerse @BibleId, 113029006, N'The leaders of the families, the leaders of the Israelite tribes, the commanders of units of a thousand and a hundred, and the supervisors of the king’s work contributed willingly.'
EXEC add_BibleVerse @BibleId, 113029007, N'They donated for the service of God’s temple 5,000 talents and ten thousand darics of gold, 10,000 talents of silver, 18,000 talents of bronze, and 100,000 talents of iron.'
EXEC add_BibleVerse @BibleId, 113029008, N'All who possessed precious stones donated them to the treasury of the Lord’s temple, which was under the supervision of Jehiel the Gershonite.'
EXEC add_BibleVerse @BibleId, 113029009, N'The people were delighted with their donations, for they contributed to the Lord with a willing attitude; King David was also very happy.'
EXEC add_BibleVerse @BibleId, 113029010, N'David praised the Lord before the entire assembly: “O Lord God of our father Israel, you deserve praise forevermore!'
EXEC add_BibleVerse @BibleId, 113029011, N'O Lord, you are great, mighty, majestic, magnificent, glorious, and sovereign over all the sky and earth! You have dominion and exalt yourself as the ruler of all.'
EXEC add_BibleVerse @BibleId, 113029012, N'You are the source of wealth and honor; you rule over all. You possess strength and might to magnify and give strength to all.'
EXEC add_BibleVerse @BibleId, 113029013, N'Now, our God, we give thanks to you and praise your majestic name!'
EXEC add_BibleVerse @BibleId, 113029014, N'“But who am I and who are my people, that we should be in a position to contribute this much? Indeed, everything comes from you, and we have simply given back to you what is yours.'
EXEC add_BibleVerse @BibleId, 113029015, N'For we are resident foreigners and nomads in your presence, like all our ancestors; our days are like a shadow on the earth, without security.'
EXEC add_BibleVerse @BibleId, 113029016, N'O Lord our God, all this wealth, which we have collected to build a temple for you to honor your holy name, comes from you; it all belongs to you.'
EXEC add_BibleVerse @BibleId, 113029017, N'I know, my God, that you examine thoughts and are pleased with integrity. With pure motives I contribute all this; and now I look with joy as your people who have gathered here contribute to you.'
EXEC add_BibleVerse @BibleId, 113029018, N'O Lord God of our ancestors Abraham, Isaac, and Israel, maintain the motives of your people and keep them devoted to you.'
EXEC add_BibleVerse @BibleId, 113029019, N'Make my son Solomon willing to obey your commands, rules, and regulations, and to complete building the palace for which I have made preparations.”'
EXEC add_BibleVerse @BibleId, 113029020, N'David told the entire assembly: “Praise the Lord your God!” So the entire assembly praised the Lord God of their ancestors; they bowed down and stretched out flat on the ground before the Lord and the king.'
EXEC add_BibleVerse @BibleId, 113029021, N'The next day they made sacrifices and offered burnt sacrifices to the Lord (1,000 bulls, 1,000 rams, 1,000 lambs), along with their accompanying drink offerings and many other sacrifices for all Israel.'
EXEC add_BibleVerse @BibleId, 113029022, N'They held a feast before the Lord that day and celebrated. Then they designated Solomon, David’s son, as king a second time; before the Lord they anointed him as ruler and Zadok as priest.'
EXEC add_BibleVerse @BibleId, 113029023, N'Solomon sat on the Lord’s throne as king in place of his father David; he was successful and all Israel was loyal to him.'
EXEC add_BibleVerse @BibleId, 113029024, N'All the officers and warriors, as well as all of King David’s sons, pledged their allegiance to King Solomon.'
EXEC add_BibleVerse @BibleId, 113029025, N'The Lord greatly magnified Solomon before all Israel and bestowed on him greater majesty than any king of Israel before him.'
EXEC add_BibleVerse @BibleId, 113029026, N'David son of Jesse reigned over all Israel.'
EXEC add_BibleVerse @BibleId, 113029027, N'He reigned over Israel forty years; he reigned in Hebron seven years and in Jerusalem thirty-three years.'
EXEC add_BibleVerse @BibleId, 113029028, N'He died at a good old age, having enjoyed long life, wealth, and honor. His son Solomon succeeded him.'
EXEC add_BibleVerse @BibleId, 113029029, N'King David’s accomplishments, from start to finish, are recorded in the Annals of Samuel the prophet, the Annals of Nathan the prophet, and the Annals of Gad the prophet.'
EXEC add_BibleVerse @BibleId, 113029030, N'Recorded there are all the facts about his reign and accomplishments, and an account of the events that involved him, Israel, and all the neighboring kingdoms.'
EXEC add_BibleVerse @BibleId, 114001001, N'Solomon son of David solidified his royal authority, for the Lord his God was with him and magnified him greatly.'
EXEC add_BibleVerse @BibleId, 114001002, N'Solomon addressed all Israel, including those who commanded units of a thousand and a hundred, the judges, and all the leaders of all Israel who were heads of families.'
EXEC add_BibleVerse @BibleId, 114001003, N'Solomon and the entire assembly went to the worship center in Gibeon, for the tent where they met God was located there, which Moses the Lord’s servant had made in the wilderness.'
EXEC add_BibleVerse @BibleId, 114001004, N'(Now David had brought up the ark of God from Kiriath Jearim to the place he had prepared for it, for he had pitched a tent for it in Jerusalem.'
EXEC add_BibleVerse @BibleId, 114001005, N'But the bronze altar made by Bezalel son of Uri, son of Hur, was in front of the Lord’s tabernacle. Solomon and the entire assembly prayed to him there.)'
EXEC add_BibleVerse @BibleId, 114001006, N'Solomon went up to the bronze altar before the Lord which was at the meeting tent, and he offered up a thousand burnt sacrifices.'
EXEC add_BibleVerse @BibleId, 114001007, N'That night God appeared to Solomon and said to him, “Tell me what I should give you.”'
EXEC add_BibleVerse @BibleId, 114001008, N'Solomon replied to God, “You demonstrated great loyalty to my father David and have made me king in his place.'
EXEC add_BibleVerse @BibleId, 114001009, N'Now, Lord God, may your promise to my father David be realized, for you have made me king over a great nation as numerous as the dust of the earth.'
EXEC add_BibleVerse @BibleId, 114001010, N'Now give me wisdom and discernment so I can effectively lead this nation. Otherwise no one is able to make judicial decisions for this great nation of yours.”'
EXEC add_BibleVerse @BibleId, 114001011, N'God said to Solomon, “Because you desire this, and did not ask for riches, wealth, and honor, or for vengeance on your enemies, and because you did not ask for long life, but requested wisdom and discernment so you can make judicial decisions for my people over whom I have made you king,'
EXEC add_BibleVerse @BibleId, 114001012, N'you are granted wisdom and discernment. Furthermore I am giving you riches, wealth, and honor surpassing that of any king before or after you.”'
EXEC add_BibleVerse @BibleId, 114001013, N'Solomon left the meeting tent at the worship center in Gibeon and went to Jerusalem, where he reigned over Israel.'
EXEC add_BibleVerse @BibleId, 114001014, N'Solomon accumulated chariots and horses. He had 1,400 chariots and 12,000 horses. He kept them in assigned cities and in Jerusalem.'
EXEC add_BibleVerse @BibleId, 114001015, N'The king made silver and gold as plentiful in Jerusalem as stones; cedar was as plentiful as sycamore fig trees are in the lowlands.'
EXEC add_BibleVerse @BibleId, 114001016, N'Solomon acquired his horses from Egypt and from Que; the king’s traders purchased them from Que.'
EXEC add_BibleVerse @BibleId, 114001017, N'They paid 600 silver pieces for each chariot from Egypt, and 150 silver pieces for each horse. They also sold chariots and horses to all the kings of the Hittites and to the kings of Syria.'
EXEC add_BibleVerse @BibleId, 114002001, N'Solomon ordered a temple to be built to honor the Lord, as well as a royal palace for himself.'
EXEC add_BibleVerse @BibleId, 114002002, N'Solomon had 70,000 common laborers and 80,000 stonecutters in the hills, in addition to 3,600 supervisors.'
EXEC add_BibleVerse @BibleId, 114002003, N'Solomon sent a message to King Huram of Tyre: “Help me as you did my father David, when you sent him cedar logs for the construction of his palace.'
EXEC add_BibleVerse @BibleId, 114002004, N'Look, I am ready to build a temple to honor the Lord my God and to dedicate it to him in order to burn fragrant incense before him, to set out the bread that is regularly displayed, and to offer burnt sacrifices each morning and evening, and on Sabbaths, new moon festivals, and at other times appointed by the Lord our God. This is something Israel must do on a permanent basis.'
EXEC add_BibleVerse @BibleId, 114002005, N'I will build a great temple, for our God is greater than all gods.'
EXEC add_BibleVerse @BibleId, 114002006, N'Of course, who can really build a temple for him, since the sky and the highest heavens cannot contain him? Who am I that I should build him a temple! It will really be only a place to offer sacrifices before him.'
EXEC add_BibleVerse @BibleId, 114002007, N'“Now send me a man who is skilled in working with gold, silver, bronze, and iron, as well as purple, crimson, and violet colored fabrics, and who knows how to engrave. He will work with my skilled craftsmen here in Jerusalem and Judah, whom my father David provided.'
EXEC add_BibleVerse @BibleId, 114002008, N'Send me cedars, evergreens, and algum trees from Lebanon, for I know your servants are adept at cutting down trees in Lebanon. My servants will work with your servants'
EXEC add_BibleVerse @BibleId, 114002009, N'to supply me with large quantities of timber, for I am building a great, magnificent temple.'
EXEC add_BibleVerse @BibleId, 114002010, N'Look, I will pay your servants who cut the timber 20,000 kors of ground wheat, 20,000 kors of barley, 120,000 gallons of wine, and 120,000 gallons of olive oil.”'
EXEC add_BibleVerse @BibleId, 114002011, N'King Huram of Tyre sent this letter to Solomon: “Because the Lord loves his people, he has made you their king.”'
EXEC add_BibleVerse @BibleId, 114002012, N'Huram also said, “Worthy of praise is the Lord God of Israel, who made the sky and the earth! He has given David a wise son who has discernment and insight and will build a temple for the Lord, as well as a royal palace for himself.'
EXEC add_BibleVerse @BibleId, 114002013, N'Now I am sending you Huram Abi, a skilled and capable man,'
EXEC add_BibleVerse @BibleId, 114002014, N'whose mother is a Danite and whose father is a Tyrian. He knows how to work with gold, silver, bronze, iron, stones, and wood, as well as purple, violet, white, and crimson fabrics. He knows how to do all kinds of engraving and understands any design given to him. He will work with your skilled craftsmen and the skilled craftsmen of my lord David your father.'
EXEC add_BibleVerse @BibleId, 114002015, N'Now let my lord send to his servants the wheat, barley, olive oil, and wine he has promised;'
EXEC add_BibleVerse @BibleId, 114002016, N'we will get all the timber you need from Lebanon and bring it in raft-like bundles by sea to Joppa. You can then haul it on up to Jerusalem.”'
EXEC add_BibleVerse @BibleId, 114002017, N'Solomon took a census of all the male resident foreigners in the land of Israel, after the census his father David had taken. There were 153,600 in all.'
EXEC add_BibleVerse @BibleId, 114002018, N'He designated 70,000 as common laborers, 80,000 as stonecutters in the hills, and 3,600 as supervisors to make sure the people completed the work.'
EXEC add_BibleVerse @BibleId, 114003001, N'Solomon began building the Lord’s temple in Jerusalem on Mount Moriah, where the Lord had appeared to his father David. This was the place that David prepared at the threshing floor of Ornan the Jebusite.'
EXEC add_BibleVerse @BibleId, 114003002, N'He began building on the second day of the second month of the fourth year of his reign.'
EXEC add_BibleVerse @BibleId, 114003003, N'Solomon laid the foundation for God’s temple; its length (determined according to the old standard of measure) was 90 feet, and its width 30 feet.'
EXEC add_BibleVerse @BibleId, 114003004, N'The porch in front of the main hall was 30 feet long, corresponding to the width of the temple, and its height was 30 feet. He plated the inside with pure gold.'
EXEC add_BibleVerse @BibleId, 114003005, N'He paneled the main hall with boards made from evergreen trees and plated it with fine gold, decorated with palm trees and chains.'
EXEC add_BibleVerse @BibleId, 114003006, N'He decorated the temple with precious stones; the gold he used came from Parvaim.'
EXEC add_BibleVerse @BibleId, 114003007, N'He overlaid the temple’s rafters, thresholds, walls and doors with gold; he carved decorative cherubim on the walls.'
EXEC add_BibleVerse @BibleId, 114003008, N'He made the most holy place; its length was 30 feet, corresponding to the width of the temple, and its width 30 feet. He plated it with 600 talents of fine gold.'
EXEC add_BibleVerse @BibleId, 114003009, N'The gold nails weighed 50 shekels; he also plated the upper areas with gold.'
EXEC add_BibleVerse @BibleId, 114003010, N'In the most holy place he made two images of cherubim and plated them with gold.'
EXEC add_BibleVerse @BibleId, 114003011, N'The combined wing span of the cherubs was 30 feet. One of the first cherub’s wings was seven and one-half feet long and touched one wall of the temple; its other wing was also seven and one-half feet long and touched one of the second cherub’s wings.'
EXEC add_BibleVerse @BibleId, 114003012, N'Likewise one of the second cherub’s wings was seven and one-half feet long and touched the other wall of the temple; its other wing was also seven and one-half feet long and touched one of the first cherub’s wings.'
EXEC add_BibleVerse @BibleId, 114003013, N'The combined wingspan of these cherubim was 30 feet. They stood upright, facing inward.'
EXEC add_BibleVerse @BibleId, 114003014, N'He made the curtain out of violet, purple, crimson, and white fabrics, and embroidered on it decorative cherubim.'
EXEC add_BibleVerse @BibleId, 114003015, N'In front of the temple he made two pillars which had a combined length of 52½ feet, with each having a plated capital seven and one-half feet high.'
EXEC add_BibleVerse @BibleId, 114003016, N'He made ornamental chains and put them on top of the pillars. He also made one hundred pomegranate-shaped ornaments and arranged them within the chains.'
EXEC add_BibleVerse @BibleId, 114003017, N'He set up the pillars in front of the temple, one on the right side and the other on the left. He named the one on the right Jachin, and the one on the left Boaz.'
EXEC add_BibleVerse @BibleId, 114004001, N'He made a bronze altar, 30 feet long, 30 feet wide, and 15 feet high.'
EXEC add_BibleVerse @BibleId, 114004002, N'He also made the big bronze basin called “The Sea.” It measured 15 feet from rim to rim, was circular in shape, and stood seven and one-half feet high. Its circumference was 45 feet.'
EXEC add_BibleVerse @BibleId, 114004003, N'Images of bulls were under it all the way around, ten every eighteen inches all the way around. The bulls were in two rows and had been cast with “The Sea.”'
EXEC add_BibleVerse @BibleId, 114004004, N'“The Sea” stood on top of twelve bulls. Three faced northward, three westward, three southward, and three eastward. “The Sea” was placed on top of them, and they all faced outward.'
EXEC add_BibleVerse @BibleId, 114004005, N'It was four fingers thick and its rim was like that of a cup shaped like a lily blossom. It could hold 18,000 gallons.'
EXEC add_BibleVerse @BibleId, 114004006, N'He made ten washing basins; he put five on the south side and five on the north side. In them they rinsed the items used for burnt sacrifices; the priests washed in “The Sea.”'
EXEC add_BibleVerse @BibleId, 114004007, N'He made ten gold lampstands according to specifications and put them in the temple, five on the right and five on the left.'
EXEC add_BibleVerse @BibleId, 114004008, N'He made ten tables and set them in the temple, five on the right and five on the left. He also made one hundred gold bowls.'
EXEC add_BibleVerse @BibleId, 114004009, N'He made the courtyard of the priests and the large enclosure and its doors; he plated their doors with bronze.'
EXEC add_BibleVerse @BibleId, 114004010, N'He put “The Sea” on the south side, in the southeast corner.'
EXEC add_BibleVerse @BibleId, 114004011, N'Huram Abi made the pots, shovels, and bowls. He finished all the work on God’s temple he had been assigned by King Solomon.'
EXEC add_BibleVerse @BibleId, 114004012, N'He made the two pillars, the two bowl-shaped tops of the pillars, the latticework for the bowl-shaped tops of the two pillars,'
EXEC add_BibleVerse @BibleId, 114004013, N'the four hundred pomegranate-shaped ornaments for the latticework of the two pillars (each latticework had two rows of these ornaments at the bowl-shaped top of the pillar),'
EXEC add_BibleVerse @BibleId, 114004014, N'the ten movable stands with their ten basins,'
EXEC add_BibleVerse @BibleId, 114004015, N'the big bronze basin called “The Sea” with its twelve bulls underneath,'
EXEC add_BibleVerse @BibleId, 114004016, N'and the pots, shovels, and meat forks. All the items King Solomon assigned Huram Abi to make for the Lord’s temple were made from polished bronze.'
EXEC add_BibleVerse @BibleId, 114004017, N'The king had them cast in earthen foundries in the region of the Jordan between Succoth and Zarethan.'
EXEC add_BibleVerse @BibleId, 114004018, N'Solomon made so many of these items they did not weigh the bronze.'
EXEC add_BibleVerse @BibleId, 114004019, N'Solomon also made these items for God’s temple: the gold altar, the tables on which the Bread of the Presence was kept,'
EXEC add_BibleVerse @BibleId, 114004020, N'the pure gold lampstands and their lamps which burned as specified at the entrance to the inner sanctuary,'
EXEC add_BibleVerse @BibleId, 114004021, N'the pure gold flower-shaped ornaments, lamps, and tongs,'
EXEC add_BibleVerse @BibleId, 114004022, N'the pure gold trimming shears, basins, pans, and censers, and the gold door sockets for the inner sanctuary (the most holy place) and for the doors of the main hall of the temple.'
EXEC add_BibleVerse @BibleId, 114005001, N'When Solomon had finished constructing the Lord’s temple, he put the holy items that belonged to his father David (the silver, gold, and all the other articles) in the treasuries of God’s temple.'
EXEC add_BibleVerse @BibleId, 114005002, N'Then Solomon convened Israel’s elders – all the leaders of the Israelite tribes and families – in Jerusalem, so they could witness the transferal of the ark of the covenant of the Lord from the City of David (that is, Zion).'
EXEC add_BibleVerse @BibleId, 114005003, N'All the men of Israel assembled before the king during the festival in the seventh month.'
EXEC add_BibleVerse @BibleId, 114005004, N'When all Israel’s elders had arrived, the Levites lifted the ark.'
EXEC add_BibleVerse @BibleId, 114005005, N'The priests and Levites carried the ark, the tent where God appeared to his people, and all the holy items in the tent.'
EXEC add_BibleVerse @BibleId, 114005006, N'Now King Solomon and all the Israelites who had assembled with him went on ahead of the ark and sacrificed more sheep and cattle than could be counted or numbered.'
EXEC add_BibleVerse @BibleId, 114005007, N'The priests brought the ark of the covenant of the Lord to its assigned place in the inner sanctuary of the temple, in the most holy place under the wings of the cherubs.'
EXEC add_BibleVerse @BibleId, 114005008, N'The cherubs’ wings extended over the place where the ark sat; the cherubs overshadowed the ark and its poles.'
EXEC add_BibleVerse @BibleId, 114005009, N'The poles were so long their ends extending out from the ark were visible from in front of the inner sanctuary, but they could not be seen from beyond that point. They have remained there to this very day.'
EXEC add_BibleVerse @BibleId, 114005010, N'There was nothing in the ark except the two tablets Moses had placed there in Horeb. (It was there that the Lord made an agreement with the Israelites after he brought them out of the land of Egypt.)'
EXEC add_BibleVerse @BibleId, 114005011, N'The priests left the holy place. All the priests who participated had consecrated themselves, no matter which division they represented.'
EXEC add_BibleVerse @BibleId, 114005012, N'All the Levites who were musicians, including Asaph, Heman, Jeduthun, and their sons and relatives, wore linen. They played cymbals and stringed instruments as they stood east of the altar. They were accompanied by 120 priests who blew trumpets.'
EXEC add_BibleVerse @BibleId, 114005013, N'The trumpeters and musicians played together, praising and giving thanks to the Lord. Accompanied by trumpets, cymbals, and other instruments, they loudly praised the Lord, singing: “Certainly he is good; certainly his loyal love endures!” Then a cloud filled the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 114005014, N'The priests could not carry out their duties because of the cloud; the Lord’s splendor filled God’s temple.'
EXEC add_BibleVerse @BibleId, 114006001, N'Then Solomon said, “The Lord has said that he lives in thick darkness.'
EXEC add_BibleVerse @BibleId, 114006002, N'O Lord, I have built a lofty temple for you, a place where you can live permanently.”'
EXEC add_BibleVerse @BibleId, 114006003, N'Then the king turned around and pronounced a blessing over the whole Israelite assembly as they stood there.'
EXEC add_BibleVerse @BibleId, 114006004, N'He said, “The Lord God of Israel is worthy of praise because he has fulfilled what he promised my father David.'
EXEC add_BibleVerse @BibleId, 114006005, N'He told David, ‘Since the day I brought my people out of the land of Egypt, I have not chosen a city from all the tribes of Israel to build a temple in which to live. Nor did I choose a man as leader of my people Israel.'
EXEC add_BibleVerse @BibleId, 114006006, N'But now I have chosen Jerusalem as a place to live, and I have chosen David to lead my people Israel.’'
EXEC add_BibleVerse @BibleId, 114006007, N'Now my father David had a strong desire to build a temple to honor the Lord God of Israel.'
EXEC add_BibleVerse @BibleId, 114006008, N'The Lord told my father David, ‘It is right for you to have a strong desire to build a temple to honor me.'
EXEC add_BibleVerse @BibleId, 114006009, N'But you will not build the temple; your very own son will build the temple for my honor.’'
EXEC add_BibleVerse @BibleId, 114006010, N'The Lord has kept the promise he made. I have taken my father David’s place and have occupied the throne of Israel, as the Lord promised. I have built this temple for the honor of the Lord God of Israel'
EXEC add_BibleVerse @BibleId, 114006011, N'and set up in it a place for the ark containing the covenant the Lord made with the Israelites.”'
EXEC add_BibleVerse @BibleId, 114006012, N'He stood before the altar of the Lord in front of the entire assembly of Israel and spread out his hands.'
EXEC add_BibleVerse @BibleId, 114006013, N'Solomon had made a bronze platform and had placed it in the middle of the enclosure. It was seven and one-half feet long, seven and one-half feet wide, and four and one-half feet high. He stood on it and then got down on his knees in front of the entire assembly of Israel. He spread out his hands toward the sky,'
EXEC add_BibleVerse @BibleId, 114006014, N'and prayed: “O Lord God of Israel, there is no god like you in heaven or on earth! You maintain covenantal loyalty to your servants who obey you with sincerity.'
EXEC add_BibleVerse @BibleId, 114006015, N'You have kept your word to your servant, my father David; this very day you have fulfilled what you promised.'
EXEC add_BibleVerse @BibleId, 114006016, N'Now, O Lord God of Israel, keep the promise you made to your servant, my father David, when you said, ‘You will never fail to have a successor ruling before me on the throne of Israel, provided that your descendants watch their step and obey my law as you have done.’'
EXEC add_BibleVerse @BibleId, 114006017, N'Now, O Lord God of Israel, may the promise you made to your servant David be realized.'
EXEC add_BibleVerse @BibleId, 114006018, N'“God does not really live with humankind on the earth! Look, if the sky and the highest heaven cannot contain you, how much less this temple I have built!'
EXEC add_BibleVerse @BibleId, 114006019, N'But respond favorably to your servant’s prayer and his request for help, O Lord my God. Answer the desperate prayer your servant is presenting to you.'
EXEC add_BibleVerse @BibleId, 114006020, N'Night and day may you watch over this temple, the place where you promised you would live. May you answer your servant’s prayer for this place.'
EXEC add_BibleVerse @BibleId, 114006021, N'Respond to the requests of your servant and your people Israel for this place. Hear from your heavenly dwelling place and respond favorably and forgive.'
EXEC add_BibleVerse @BibleId, 114006022, N'“When someone is accused of sinning against his neighbor and the latter pronounces a curse on the alleged offender before your altar in this temple,'
EXEC add_BibleVerse @BibleId, 114006023, N'listen from heaven and make a just decision about your servants’ claims. Condemn the guilty party, declare the other innocent, and give both of them what they deserve.'
EXEC add_BibleVerse @BibleId, 114006024, N'“If your people Israel are defeated by an enemy because they sinned against you, then if they come back to you, renew their allegiance to you, and pray for your help before you in this temple,'
EXEC add_BibleVerse @BibleId, 114006025, N'then listen from heaven, forgive the sin of your people Israel, and bring them back to the land you gave to them and their ancestors.'
EXEC add_BibleVerse @BibleId, 114006026, N'“The time will come when the skies are shut up tightly and no rain falls because your people sinned against you. When they direct their prayers toward this place, renew their allegiance to you, and turn away from their sin because you punish them,'
EXEC add_BibleVerse @BibleId, 114006027, N'then listen from heaven and forgive the sin of your servants, your people Israel. Certainly you will then teach them the right way to live and send rain on your land that you have given your people to possess.'
EXEC add_BibleVerse @BibleId, 114006028, N'“The time will come when the land suffers from a famine, a plague, blight, and disease, or a locust invasion, or when their enemy lays siege to the cities of the land, or when some other type of plague or epidemic occurs.'
EXEC add_BibleVerse @BibleId, 114006029, N'When all your people Israel pray and ask for help, as they acknowledge their intense pain and spread out their hands toward this temple,'
EXEC add_BibleVerse @BibleId, 114006030, N'then listen from your heavenly dwelling place, forgive their sin, and act favorably toward each one based on your evaluation of their motives. (Indeed you are the only one who can correctly evaluate the motives of all people.)'
EXEC add_BibleVerse @BibleId, 114006031, N'Then they will honor you by obeying you throughout their lifetimes as they live on the land you gave to our ancestors.'
EXEC add_BibleVerse @BibleId, 114006032, N'“Foreigners, who do not belong to your people Israel, will come from a distant land because of your great reputation and your ability to accomplish mighty deeds; they will come and direct their prayers toward this temple.'
EXEC add_BibleVerse @BibleId, 114006033, N'Then listen from your heavenly dwelling place and answer all the prayers of the foreigners. Then all the nations of the earth will acknowledge your reputation, obey you like your people Israel do, and recognize that this temple I built belongs to you.'
EXEC add_BibleVerse @BibleId, 114006034, N'“When you direct your people to march out and fight their enemies, and they direct their prayers to you toward this chosen city and this temple I built for your honor,'
EXEC add_BibleVerse @BibleId, 114006035, N'then listen from heaven to their prayers for help and vindicate them.'
EXEC add_BibleVerse @BibleId, 114006036, N'“The time will come when your people will sin against you (for there is no one who is sinless!) and you will be angry at them and deliver them over to their enemies, who will take them as prisoners to their land, whether far away or close by.'
EXEC add_BibleVerse @BibleId, 114006037, N'When your people come to their senses in the land where they are held prisoner, they will repent and beg for your mercy in the land of their imprisonment, admitting, ‘We have sinned and gone astray , we have done evil!’'
EXEC add_BibleVerse @BibleId, 114006038, N'When they return to you with all their heart and being in the land where they are held prisoner and direct their prayers toward the land you gave to their ancestors, your chosen city, and the temple I built for your honor,'
EXEC add_BibleVerse @BibleId, 114006039, N'then listen from your heavenly dwelling place to their prayers for help, vindicate them, and forgive your sinful people.'
EXEC add_BibleVerse @BibleId, 114006040, N'“Now, my God, may you be attentive and responsive to the prayers offered in this place.'
EXEC add_BibleVerse @BibleId, 114006041, N'Now ascend, O Lord God, to your resting place, you and the ark of your strength! May your priests, O Lord God, experience your deliverance! May your loyal followers rejoice in the prosperity you give!'
EXEC add_BibleVerse @BibleId, 114006042, N'O Lord God, do not reject your chosen ones! Remember the faithful promises you made to your servant David!”'
EXEC add_BibleVerse @BibleId, 114007001, N'When Solomon finished praying, fire came down from heaven and consumed the burnt offering and the sacrifices, and the Lord’s splendor filled the temple.'
EXEC add_BibleVerse @BibleId, 114007002, N'The priests were unable to enter the Lord’s temple because the Lord’s splendor filled the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 114007003, N'When all the Israelites saw the fire come down and the Lord’s splendor over the temple, they got on their knees with their faces downward toward the pavement. They worshiped and gave thanks to the Lord, saying, “Certainly he is good; certainly his loyal love endures!”'
EXEC add_BibleVerse @BibleId, 114007004, N'The king and all the people were presenting sacrifices to the Lord.'
EXEC add_BibleVerse @BibleId, 114007005, N'King Solomon sacrificed 22,000 cattle and 120,000 sheep. Then the king and all the people dedicated God’s temple.'
EXEC add_BibleVerse @BibleId, 114007006, N'The priests stood in their assigned spots, along with the Levites who had the musical instruments used for praising the Lord. (These were the ones King David made for giving thanks to the Lord and which were used by David when he offered praise, saying, “Certainly his loyal love endures.”) Opposite the Levites, the priests were blowing the trumpets, while all Israel stood there.'
EXEC add_BibleVerse @BibleId, 114007007, N'Solomon consecrated the middle of the courtyard that is in front of the Lord’s temple. He offered burnt sacrifices, grain offerings, and the fat from the peace offerings there, because the bronze altar that Solomon had made was too small to hold all these offerings.'
EXEC add_BibleVerse @BibleId, 114007008, N'At that time Solomon and all Israel with him celebrated a festival for seven days. This great assembly included people from Lebo Hamath in the north to the Brook of Egypt in the south.'
EXEC add_BibleVerse @BibleId, 114007009, N'On the eighth day they held an assembly, for they had dedicated the altar for seven days and celebrated the festival for seven more days.'
EXEC add_BibleVerse @BibleId, 114007010, N'On the twenty-third day of the seventh month, Solomon sent the people home. They left happy and contented because of the good the Lord had done for David, Solomon, and his people Israel.'
EXEC add_BibleVerse @BibleId, 114007011, N'After Solomon finished building the Lord’s temple and the royal palace, and accomplished all his plans for the Lord’s temple and his royal palace,'
EXEC add_BibleVerse @BibleId, 114007012, N'the Lord appeared to Solomon at night and said to him: “I have answered your prayer and chosen this place to be my temple where sacrifices are to be made.'
EXEC add_BibleVerse @BibleId, 114007013, N'When I close up the sky so that it doesn’t rain, or command locusts to devour the land’s vegetation, or send a plague among my people,'
EXEC add_BibleVerse @BibleId, 114007014, N'if my people, who belong to me, humble themselves, pray, seek to please me, and repudiate their sinful practices, then I will respond from heaven, forgive their sin, and heal their land.'
EXEC add_BibleVerse @BibleId, 114007015, N'Now I will be attentive and responsive to the prayers offered in this place.'
EXEC add_BibleVerse @BibleId, 114007016, N'Now I have chosen and consecrated this temple by making it my permanent home; I will be constantly present there.'
EXEC add_BibleVerse @BibleId, 114007017, N'You must serve me as your father David did. Do everything I commanded and obey my rules and regulations.'
EXEC add_BibleVerse @BibleId, 114007018, N'Then I will establish your dynasty, just as I promised your father David, ‘You will not fail to have a successor ruling over Israel.’'
EXEC add_BibleVerse @BibleId, 114007019, N'“But if you people ever turn away from me, fail to obey the regulations and rules I instructed you to keep, and decide to serve and worship other gods,'
EXEC add_BibleVerse @BibleId, 114007020, N'then I will remove you from my land I have given you, I will abandon this temple I have consecrated with my presence, and I will make you an object of mockery and ridicule among all the nations.'
EXEC add_BibleVerse @BibleId, 114007021, N'As for this temple, which was once majestic, everyone who passes by it will be shocked and say, ‘Why did the Lord do this to this land and this temple?’'
EXEC add_BibleVerse @BibleId, 114007022, N'Others will then answer, ‘Because they abandoned the Lord God of their ancestors, who led them out of Egypt. They embraced other gods whom they worshiped and served. That is why he brought all this disaster down on them.’”'
EXEC add_BibleVerse @BibleId, 114008001, N'After twenty years, during which Solomon built the Lord’s temple and his royal palace,'
EXEC add_BibleVerse @BibleId, 114008002, N'Solomon rebuilt the cities that Huram had given him and settled Israelites there.'
EXEC add_BibleVerse @BibleId, 114008003, N'Solomon went to Hamath Zobah and seized it.'
EXEC add_BibleVerse @BibleId, 114008004, N'He built up Tadmor in the wilderness and all the storage cities he had built in Hamath.'
EXEC add_BibleVerse @BibleId, 114008005, N'He made upper Beth Horon and lower Beth Horon fortified cities with walls and barred gates,'
EXEC add_BibleVerse @BibleId, 114008006, N'and built up Baalath, all the storage cities that belonged to him, and all the cities where chariots and horses were kept. He built whatever he wanted in Jerusalem, Lebanon, and throughout his entire kingdom.'
EXEC add_BibleVerse @BibleId, 114008007, N'Now several non-Israelite peoples were left in the land after the conquest of Joshua, including the Hittites, Amorites, Perizzites, Hivites, and Jebusites.'
EXEC add_BibleVerse @BibleId, 114008008, N'Their descendants remained in the land (the Israelites were unable to wipe them out). Solomon conscripted them for his work crews and they continue in that role to this very day.'
EXEC add_BibleVerse @BibleId, 114008009, N'Solomon did not assign Israelites to these work crews; the Israelites served as his soldiers, officers, charioteers, and commanders of his chariot forces.'
EXEC add_BibleVerse @BibleId, 114008010, N'These men worked for Solomon as supervisors; there were a total of 250 of them who were in charge of the people.'
EXEC add_BibleVerse @BibleId, 114008011, N'Solomon moved Pharaoh’s daughter up from the City of David to the palace he had built for her, for he said, “My wife must not live in the palace of King David of Israel, for the places where the ark of the Lord has entered are holy.”'
EXEC add_BibleVerse @BibleId, 114008012, N'Then Solomon offered burnt sacrifices to the Lord on the altar of the Lord which he had built in front of the temple’s porch.'
EXEC add_BibleVerse @BibleId, 114008013, N'He observed the daily requirements for sacrifices that Moses had specified for Sabbaths, new moon festivals, and the three annual celebrations – the Feast of Unleavened Bread, the Feast of Weeks, and the Feast of Temporary Shelters.'
EXEC add_BibleVerse @BibleId, 114008014, N'As his father David had decreed, Solomon appointed the divisions of the priests to do their assigned tasks, the Levitical orders to lead worship and help the priests with their daily tasks, and the divisions of the gatekeepers to serve at their assigned gates. This was what David the man of God had ordered.'
EXEC add_BibleVerse @BibleId, 114008015, N'They did not neglect any detail of the king’s orders pertaining to the priests, Levites, and treasuries.'
EXEC add_BibleVerse @BibleId, 114008016, N'All the work ordered by Solomon was completed, from the day the foundation of the Lord’s temple was laid until it was finished; the Lord’s temple was completed.'
EXEC add_BibleVerse @BibleId, 114008017, N'Then Solomon went to Ezion Geber and to Elat on the coast in the land of Edom.'
EXEC add_BibleVerse @BibleId, 114008018, N'Huram sent him ships and some of his sailors, men who were well acquainted with the sea. They sailed with Solomon’s men to Ophir, and took from there 450 talents of gold, which they brought back to King Solomon.'
EXEC add_BibleVerse @BibleId, 114009001, N'When the queen of Sheba heard about Solomon, she came to challenge him with difficult questions. She arrived in Jerusalem with a great display of pomp, bringing with her camels carrying spices, a very large quantity of gold, and precious gems. She visited Solomon and discussed with him everything that was on her mind.'
EXEC add_BibleVerse @BibleId, 114009002, N'Solomon answered all her questions; there was no question too complex for the king.'
EXEC add_BibleVerse @BibleId, 114009003, N'When the queen of Sheba saw for herself Solomon’s extensive wisdom, the palace he had built,'
EXEC add_BibleVerse @BibleId, 114009004, N'the food in his banquet hall, his servants and attendants in their robes, his cupbearers in their robes, and his burnt sacrifices which he presented in the Lord’s temple, she was amazed.'
EXEC add_BibleVerse @BibleId, 114009005, N'She said to the king, “The report I heard in my own country about your wise sayings and insight was true!'
EXEC add_BibleVerse @BibleId, 114009006, N'I did not believe these things until I came and saw them with my own eyes. Indeed, I didn’t hear even half the story! Your wisdom surpasses what was reported to me.'
EXEC add_BibleVerse @BibleId, 114009007, N'Your attendants, who stand before you at all times and hear your wise sayings, are truly happy!'
EXEC add_BibleVerse @BibleId, 114009008, N'May the Lord your God be praised because he favored you by placing you on his throne as the one ruling on his behalf! Because of your God’s love for Israel and his lasting commitment to them, he made you king over them so you could make just and right decisions.”'
EXEC add_BibleVerse @BibleId, 114009009, N'She gave the king 120 talents of gold and a very large quantity of spices and precious gems. The quantity of spices the queen of Sheba gave King Solomon has never been matched.'
EXEC add_BibleVerse @BibleId, 114009010, N'(Huram’s servants, aided by Solomon’s servants, brought gold from Ophir, as well as fine timber and precious gems.'
EXEC add_BibleVerse @BibleId, 114009011, N'With the timber the king made steps for the Lord’s temple and royal palace as well as stringed instruments for the musicians. No one had seen anything like them in the land of Judah prior to that. )'
EXEC add_BibleVerse @BibleId, 114009012, N'King Solomon gave the queen of Sheba everything she requested, more than what she had brought him. Then she left and returned to her homeland with her attendants.'
EXEC add_BibleVerse @BibleId, 114009013, N'Solomon received 666 talents of gold per year,'
EXEC add_BibleVerse @BibleId, 114009014, N'besides what he collected from the merchants and traders. All the Arabian kings and the governors of the land also brought gold and silver to Solomon.'
EXEC add_BibleVerse @BibleId, 114009015, N'King Solomon made two hundred large shields of hammered gold; 600 measures of hammered gold were used for each shield.'
EXEC add_BibleVerse @BibleId, 114009016, N'He also made three hundred small shields of hammered gold; 300 measures of gold were used for each of those shields. The king placed them in the Palace of the Lebanon Forest.'
EXEC add_BibleVerse @BibleId, 114009017, N'The king made a large throne decorated with ivory and overlaid it with pure gold.'
EXEC add_BibleVerse @BibleId, 114009018, N'There were six steps leading up to the throne, and a gold footstool was attached to the throne. The throne had two armrests with a statue of a lion standing on each side.'
EXEC add_BibleVerse @BibleId, 114009019, N'There were twelve statues of lions on the six steps, one lion at each end of each step. There was nothing like it in any other kingdom.'
EXEC add_BibleVerse @BibleId, 114009020, N'All of King Solomon’s cups were made of gold, and all the household items in the Palace of the Lebanon Forest were made of pure gold. There were no silver items, for silver was not considered very valuable in Solomon’s time.'
EXEC add_BibleVerse @BibleId, 114009021, N'The king had a fleet of large merchant ships manned by Huram’s men that sailed the sea. Once every three years the fleet came into port with cargoes of gold, silver, ivory, apes, and peacocks.'
EXEC add_BibleVerse @BibleId, 114009022, N'King Solomon was wealthier and wiser than any of the kings of the earth.'
EXEC add_BibleVerse @BibleId, 114009023, N'All the kings of the earth wanted to visit Solomon to see him display his God-given wisdom.'
EXEC add_BibleVerse @BibleId, 114009024, N'Year after year visitors brought their gifts, which included items of silver, items of gold, clothes, perfume, spices, horses, and mules.'
EXEC add_BibleVerse @BibleId, 114009025, N'Solomon had 4,000 stalls for his chariot horses and 12,000 horses. He kept them in assigned cities and in Jerusalem.'
EXEC add_BibleVerse @BibleId, 114009026, N'He ruled all the kingdoms from the Euphrates River to the land of the Philistines as far as the border of Egypt.'
EXEC add_BibleVerse @BibleId, 114009027, N'The king made silver as plentiful in Jerusalem as stones; cedar was as plentiful as sycamore fig trees are in the lowlands .'
EXEC add_BibleVerse @BibleId, 114009028, N'Solomon acquired horses from Egypt and from all the lands.'
EXEC add_BibleVerse @BibleId, 114009029, N'The rest of the events of Solomon’s reign, from start to finish, are recorded in the Annals of Nathan the Prophet, the Prophecy of Ahijah the Shilonite, and the Vision of Iddo the Seer pertaining to Jeroboam son of Nebat.'
EXEC add_BibleVerse @BibleId, 114009030, N'Solomon ruled over all Israel from Jerusalem for forty years.'
EXEC add_BibleVerse @BibleId, 114009031, N'Then Solomon passed away and was buried in the city of his father David. His son Rehoboam replaced him as king.'
EXEC add_BibleVerse @BibleId, 114010001, N'Rehoboam traveled to Shechem, for all Israel had gathered in Shechem to make Rehoboam king.'
EXEC add_BibleVerse @BibleId, 114010002, N'When Jeroboam son of Nebat heard the news, he was still in Egypt, where he had fled from King Solomon. Jeroboam returned from Egypt.'
EXEC add_BibleVerse @BibleId, 114010003, N'They sent for him and Jeroboam and all Israel came and spoke to Rehoboam, saying,'
EXEC add_BibleVerse @BibleId, 114010004, N'“Your father made us work too hard! Now if you lighten the demands he made and don’t make us work as hard, we will serve you.”'
EXEC add_BibleVerse @BibleId, 114010005, N'He said to them, “Go away for three days, then return to me.” So the people went away.'
EXEC add_BibleVerse @BibleId, 114010006, N'King Rehoboam consulted with the older advisers who had served his father Solomon when he had been alive. He asked them, “How do you advise me to answer these people?”'
EXEC add_BibleVerse @BibleId, 114010007, N'They said to him, “If you are fair to these people, grant their request, and are cordial to them, they will be your servants from this time forward.”'
EXEC add_BibleVerse @BibleId, 114010008, N'But Rehoboam rejected their advice and consulted the young advisers who served him, with whom he had grown up.'
EXEC add_BibleVerse @BibleId, 114010009, N'He asked them, “How do you advise me to respond to these people who said to me, ‘Lessen the demands your father placed on us’?”'
EXEC add_BibleVerse @BibleId, 114010010, N'The young advisers with whom Rehoboam had grown up said to him, “Say this to these people who have said to you, ‘Your father made us work hard, but now lighten our burden’ – say this to them: ‘I am a lot harsher than my father!'
EXEC add_BibleVerse @BibleId, 114010011, N'My father imposed heavy demands on you; I will make them even heavier. My father punished you with ordinary whips; I will punish you with whips that really sting your flesh.’”'
EXEC add_BibleVerse @BibleId, 114010012, N'Jeroboam and all the people reported to Rehoboam on the third day, just as the king had ordered when he said, “Return to me on the third day.”'
EXEC add_BibleVerse @BibleId, 114010013, N'The king responded to the people harshly. He rejected the advice of the older men'
EXEC add_BibleVerse @BibleId, 114010014, N'and followed the advice of the younger ones. He said, “My father imposed heavy demands on you; I will make them even heavier. My father punished you with ordinary whips; I will punish you with whips that really sting your flesh.”'
EXEC add_BibleVerse @BibleId, 114010015, N'The king refused to listen to the people, because God was instigating this turn of events so that he might bring to pass the prophetic announcement he had made through Ahijah the Shilonite to Jeroboam son of Nebat.'
EXEC add_BibleVerse @BibleId, 114010016, N'When all Israel saw that the king refused to listen to them, the people answered the king, “We have no portion in David – no share in the son of Jesse! Return to your homes, O Israel! Now, look after your own dynasty, O David!” So all Israel returned to their homes.'
EXEC add_BibleVerse @BibleId, 114010017, N'(Rehoboam continued to rule over the Israelites who lived in the cities of Judah.)'
EXEC add_BibleVerse @BibleId, 114010018, N'King Rehoboam sent Hadoram, the supervisor of the work crews, out after them, but the Israelites stoned him to death. King Rehoboam managed to jump into his chariot and escape to Jerusalem.'
EXEC add_BibleVerse @BibleId, 114010019, N'So Israel has been in rebellion against the Davidic dynasty to this very day.'
EXEC add_BibleVerse @BibleId, 114011001, N'When Rehoboam arrived in Jerusalem, he summoned 180,000 skilled warriors from Judah and Benjamin to attack Israel and restore the kingdom to Rehoboam.'
EXEC add_BibleVerse @BibleId, 114011002, N'But the Lord told Shemaiah the prophet,'
EXEC add_BibleVerse @BibleId, 114011003, N'“Say this to King Rehoboam son of Solomon of Judah and to all the Israelites in Judah and Benjamin,'
EXEC add_BibleVerse @BibleId, 114011004, N'‘The Lord says this: “Do not attack and make war with your brothers. Each of you go home, for I have caused this to happen.”’” They obeyed the Lord and called off the attack against Jeroboam.'
EXEC add_BibleVerse @BibleId, 114011005, N'Rehoboam lived in Jerusalem; he built up these fortified cities throughout Judah:'
EXEC add_BibleVerse @BibleId, 114011006, N'Bethlehem, Etam, Tekoa,'
EXEC add_BibleVerse @BibleId, 114011007, N'Beth Zur, Soco, Adullam,'
EXEC add_BibleVerse @BibleId, 114011008, N'Gath, Mareshah, Ziph,'
EXEC add_BibleVerse @BibleId, 114011009, N'Adoraim, Lachish, Azekah,'
EXEC add_BibleVerse @BibleId, 114011010, N'Zorah, Aijalon, and Hebron. These were the fortified cities in Judah and Benjamin.'
EXEC add_BibleVerse @BibleId, 114011011, N'He fortified these cities and placed officers in them, as well as storehouses of food, olive oil, and wine.'
EXEC add_BibleVerse @BibleId, 114011012, N'In each city there were shields and spears; he strongly fortified them. Judah and Benjamin belonged to him.'
EXEC add_BibleVerse @BibleId, 114011013, N'The priests and Levites who lived throughout Israel supported him, no matter where they resided.'
EXEC add_BibleVerse @BibleId, 114011014, N'The Levites even left their pasturelands and their property behind and came to Judah and Jerusalem, for Jeroboam and his sons prohibited them from serving as the Lord’s priests.'
EXEC add_BibleVerse @BibleId, 114011015, N'Jeroboam appointed his own priests to serve at the worship centers and to lead in the worship of the goat idols and calf idols he had made.'
EXEC add_BibleVerse @BibleId, 114011016, N'Those among all the Israelite tribes who were determined to worship the Lord God of Israel followed them to Jerusalem to sacrifice to the Lord God of their ancestors.'
EXEC add_BibleVerse @BibleId, 114011017, N'They supported the kingdom of Judah and were loyal to Rehoboam son of Solomon for three years; they followed the edicts of David and Solomon for three years.'
EXEC add_BibleVerse @BibleId, 114011018, N'Rehoboam married Mahalath the daughter of David’s son Jerimoth and of Abihail, the daughter of Jesse’s son Eliab.'
EXEC add_BibleVerse @BibleId, 114011019, N'She bore him sons named Jeush, Shemariah, and Zaham.'
EXEC add_BibleVerse @BibleId, 114011020, N'He later married Maacah the daughter of Absalom. She bore to him Abijah, Attai, Ziza, and Shelomith.'
EXEC add_BibleVerse @BibleId, 114011021, N'Rehoboam loved Maacah daughter of Absalom more than his other wives and concubines. He had eighteen wives and sixty concubines; he fathered twenty-eight sons and sixty daughters.'
EXEC add_BibleVerse @BibleId, 114011022, N'Rehoboam appointed Abijah son of Maacah as the leader over his brothers, for he intended to name him his successor.'
EXEC add_BibleVerse @BibleId, 114011023, N'He wisely placed some of his many sons throughout the regions of Judah and Benjamin in the various fortified cities. He supplied them with abundant provisions and acquired many wives for them.'
EXEC add_BibleVerse @BibleId, 114012001, N'After Rehoboam’s rule was established and solidified, he and all Israel rejected the law of the Lord.'
EXEC add_BibleVerse @BibleId, 114012002, N'Because they were unfaithful to the Lord, in King Rehoboam’s fifth year, King Shishak of Egypt attacked Jerusalem.'
EXEC add_BibleVerse @BibleId, 114012003, N'He had 1,200 chariots, 60,000 horsemen, and an innumerable number of soldiers who accompanied him from Egypt, including Libyans, Sukkites, and Cushites.'
EXEC add_BibleVerse @BibleId, 114012004, N'He captured the fortified cities of Judah and marched against Jerusalem.'
EXEC add_BibleVerse @BibleId, 114012005, N'Shemaiah the prophet visited Rehoboam and the leaders of Judah who were assembled in Jerusalem because of Shishak. He said to them, “This is what the Lord says: ‘You have rejected me, so I have rejected you and will hand you over to Shishak.’”'
EXEC add_BibleVerse @BibleId, 114012006, N'The leaders of Israel and the king humbled themselves and said, “The Lord is just.”'
EXEC add_BibleVerse @BibleId, 114012007, N'When the Lord saw that they humbled themselves, he gave this message to Shemaiah: “They have humbled themselves, so I will not destroy them. I will deliver them soon. My anger will not be unleashed against Jerusalem through Shishak.'
EXEC add_BibleVerse @BibleId, 114012008, N'Yet they will become his subjects, so they can experience how serving me differs from serving the surrounding nations.”'
EXEC add_BibleVerse @BibleId, 114012009, N'King Shishak of Egypt attacked Jerusalem and took away the treasures of the Lord’s temple and of the royal palace; he took everything, including the gold shields that Solomon had made.'
EXEC add_BibleVerse @BibleId, 114012010, N'King Rehoboam made bronze shields to replace them and assigned them to the officers of the royal guard who protected the entrance to the royal palace.'
EXEC add_BibleVerse @BibleId, 114012011, N'Whenever the king visited the Lord’s temple, the royal guards carried them and then brought them back to the guardroom.'
EXEC add_BibleVerse @BibleId, 114012012, N'So when Rehoboam humbled himself, the Lord relented from his anger and did not annihilate him; Judah experienced some good things.'
EXEC add_BibleVerse @BibleId, 114012013, N'King Rehoboam solidified his rule in Jerusalem; he was forty-one years old when he became king and he ruled for seventeen years in Jerusalem, the city the Lord chose from all the tribes of Israel to be his home. Rehoboam’s mother was an Ammonite named Naamah.'
EXEC add_BibleVerse @BibleId, 114012014, N'He did evil because he was not determined to follow the Lord.'
EXEC add_BibleVerse @BibleId, 114012015, N'The events of Rehoboam’s reign, from start to finish, are recorded in the Annals of Shemaiah the prophet and of Iddo the seer that include genealogical records.'
EXEC add_BibleVerse @BibleId, 114012016, N'Then Rehoboam passed away and was buried in the City of David. His son Abijah replaced him as king.'
EXEC add_BibleVerse @BibleId, 114013001, N'In the eighteenth year of the reign of King Jeroboam, Abijah became king over Judah.'
EXEC add_BibleVerse @BibleId, 114013002, N'He ruled for three years in Jerusalem. His mother was Michaiah, the daughter of Uriel from Gibeah. There was war between Abijah and Jeroboam.'
EXEC add_BibleVerse @BibleId, 114013003, N'Abijah launched the attack with 400,000 well-trained warriors, while Jeroboam deployed against him 800,000 well-trained warriors.'
EXEC add_BibleVerse @BibleId, 114013004, N'Abijah ascended Mount Zemaraim, in the Ephraimite hill country, and said: “Listen to me, Jeroboam and all Israel!'
EXEC add_BibleVerse @BibleId, 114013005, N'Don’t you realize that the Lord God of Israel has given David and his dynasty lasting dominion over Israel by a formal agreement?'
EXEC add_BibleVerse @BibleId, 114013006, N'Jeroboam son of Nebat, a servant of Solomon son of David, rose up and rebelled against his master.'
EXEC add_BibleVerse @BibleId, 114013007, N'Lawless good-for-nothing men gathered around him and conspired against Rehoboam son of Solomon, when Rehoboam was an inexperienced young man and could not resist them.'
EXEC add_BibleVerse @BibleId, 114013008, N'Now you are declaring that you will resist the Lord’s rule through the Davidic dynasty. You have a huge army, and bring with you the gold calves that Jeroboam made for you as gods.'
EXEC add_BibleVerse @BibleId, 114013009, N'But you banished the Lord’s priests, Aaron’s descendants, and the Levites, and appointed your own priests just as the surrounding nations do! Anyone who comes to consecrate himself with a young bull or seven rams becomes a priest of these fake gods!'
EXEC add_BibleVerse @BibleId, 114013010, N'But as for us, the Lord is our God and we have not rejected him. Aaron’s descendants serve as the Lord’s priests and the Levites assist them with the work.'
EXEC add_BibleVerse @BibleId, 114013011, N'They offer burnt sacrifices to the Lord every morning and every evening, along with fragrant incense. They arrange the Bread of the Presence on a ritually clean table and light the lamps on the gold lampstand every evening. Certainly we are observing the Lord our God’s regulations, but you have rejected him.'
EXEC add_BibleVerse @BibleId, 114013012, N'Now look, God is with us as our leader. His priests are ready to blow the trumpets to signal the attack against you. You Israelites, don’t fight against the Lord God of your ancestors, for you will not win!”'
EXEC add_BibleVerse @BibleId, 114013013, N'Now Jeroboam had sent some men to ambush the Judahite army from behind. The main army was in front of the Judahite army; the ambushers were behind it.'
EXEC add_BibleVerse @BibleId, 114013014, N'The men of Judah turned around and realized they were being attacked from the front and the rear. So they cried out for help to the Lord. The priests blew their trumpets,'
EXEC add_BibleVerse @BibleId, 114013015, N'and the men of Judah gave the battle cry. As the men of Judah gave the battle cry, the Lord struck down Jeroboam and all Israel before Abijah and Judah.'
EXEC add_BibleVerse @BibleId, 114013016, N'The Israelites fled from before the Judahite army, and God handed them over to the men of Judah.'
EXEC add_BibleVerse @BibleId, 114013017, N'Abijah and his army thoroughly defeated them; 500,000 well-trained Israelite men fell dead.'
EXEC add_BibleVerse @BibleId, 114013018, N'That day the Israelites were defeated; the men of Judah prevailed because they relied on the Lord God of their ancestors.'
EXEC add_BibleVerse @BibleId, 114013019, N'Abijah chased Jeroboam; he seized from him these cities: Bethel and its surrounding towns, Jeshanah and its surrounding towns, and Ephron and its surrounding towns.'
EXEC add_BibleVerse @BibleId, 114013020, N'Jeroboam did not regain power during the reign of Abijah. The Lord struck him down and he died.'
EXEC add_BibleVerse @BibleId, 114013021, N'Abijah’s power grew; he had fourteen wives and fathered twenty-two sons and sixteen daughters.'
EXEC add_BibleVerse @BibleId, 114013022, N'The rest of the events of Abijah’s reign, including his deeds and sayings, are recorded in the writings of the prophet Iddo.'
EXEC add_BibleVerse @BibleId, 114014001, N'Abijah passed away and was buried in the City of David. His son Asa replaced him as king. During his reign the land had rest for ten years.'
EXEC add_BibleVerse @BibleId, 114014002, N'Asa did what the Lord his God desired and approved.'
EXEC add_BibleVerse @BibleId, 114014003, N'He removed the pagan altars and the high places, smashed the sacred pillars, and cut down the Asherah poles.'
EXEC add_BibleVerse @BibleId, 114014004, N'He ordered Judah to seek the Lord God of their ancestors and to observe his law and commands.'
EXEC add_BibleVerse @BibleId, 114014005, N'He removed the high places and the incense altars from all the cities of Judah. The kingdom had rest under his rule.'
EXEC add_BibleVerse @BibleId, 114014006, N'He built fortified cities throughout Judah, for the land was at rest and there was no war during those years; the Lord gave him peace.'
EXEC add_BibleVerse @BibleId, 114014007, N'He said to the people of Judah: “Let’s build these cities and fortify them with walls, towers, and barred gates. The land remains ours because we have followed the Lord our God and he has made us secure on all sides.” So they built the cities and prospered.'
EXEC add_BibleVerse @BibleId, 114014008, N'Asa had an army of 300,000 men from Judah, equipped with large shields and spears. He also had 280,000 men from Benjamin who carried small shields and were adept archers; they were all skilled warriors.'
EXEC add_BibleVerse @BibleId, 114014009, N'Zerah the Cushite marched against them with an army of 1,000,000 men and 300 chariots. He arrived at Mareshah,'
EXEC add_BibleVerse @BibleId, 114014010, N'and Asa went out to oppose him. They deployed for battle in the Valley of Zephathah near Mareshah.'
EXEC add_BibleVerse @BibleId, 114014011, N'Asa prayed to the Lord his God: “O Lord, there is no one but you who can help the weak when they are vastly outnumbered. Help us, O Lord our God, for we rely on you and have marched on your behalf against this huge army. O Lord our God, don’t let men prevail against you!”'
EXEC add_BibleVerse @BibleId, 114014012, N'The Lord struck down the Cushites before Asa and Judah. The Cushites fled,'
EXEC add_BibleVerse @BibleId, 114014013, N'and Asa and his army chased them as far as Gerar. The Cushites were wiped out; they were shattered before the Lord and his army. The men of Judah carried off a huge amount of plunder.'
EXEC add_BibleVerse @BibleId, 114014014, N'They defeated all the cities surrounding Gerar, for the Lord caused them to panic. The men of Judah looted all the cities, for they contained a huge amount of goods.'
EXEC add_BibleVerse @BibleId, 114014015, N'They also attacked the tents of the herdsmen in charge of the livestock. They carried off many sheep and camels and then returned to Jerusalem.'
EXEC add_BibleVerse @BibleId, 114015001, N'God’s Spirit came upon Azariah son of Oded.'
EXEC add_BibleVerse @BibleId, 114015002, N'He met Asa and told him, “Listen to me, Asa and all Judah and Benjamin! The Lord is with you when you are loyal to him. If you seek him, he will respond to you, but if you reject him, he will reject you.'
EXEC add_BibleVerse @BibleId, 114015003, N'For a long time Israel had no true God, or priest to instruct them, or law.'
EXEC add_BibleVerse @BibleId, 114015004, N'Because of their distress, they turned back to the Lord God of Israel. They sought him and he responded to them.'
EXEC add_BibleVerse @BibleId, 114015005, N'In those days no one could travel safely, for total chaos had overtaken all the people of the surrounding lands.'
EXEC add_BibleVerse @BibleId, 114015006, N'One nation was crushed by another, and one city by another, for God caused them to be in great turmoil.'
EXEC add_BibleVerse @BibleId, 114015007, N'But as for you, be strong and don’t get discouraged, for your work will be rewarded.”'
EXEC add_BibleVerse @BibleId, 114015008, N'When Asa heard these words and the prophecy of Oded the prophet, he was encouraged. He removed the detestable idols from the entire land of Judah and Benjamin and from the cities he had seized in the Ephraimite hill country. He repaired the altar of the Lord in front of the porch of the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 114015009, N'He assembled all Judah and Benjamin, as well as the settlers from Ephraim, Manasseh, and Simeon who had come to live with them. Many people from Israel had come there to live when they saw that the Lord his God was with him.'
EXEC add_BibleVerse @BibleId, 114015010, N'They assembled in Jerusalem in the third month of the fifteenth year of Asa’s reign.'
EXEC add_BibleVerse @BibleId, 114015011, N'At that time they sacrificed to the Lord some of the plunder they had brought back, including 700 head of cattle and 7,000 sheep.'
EXEC add_BibleVerse @BibleId, 114015012, N'They solemnly agreed to seek the Lord God of their ancestors with their whole heart and being.'
EXEC add_BibleVerse @BibleId, 114015013, N'Anyone who would not seek the Lord God of Israel would be executed, whether they were young or old, male or female.'
EXEC add_BibleVerse @BibleId, 114015014, N'They swore their allegiance to the Lord, shouting their approval loudly and sounding trumpets and horns.'
EXEC add_BibleVerse @BibleId, 114015015, N'All Judah was happy about the oath, because they made the vow with their whole heart. They willingly sought the Lord and he responded to them. He made them secure on every side.'
EXEC add_BibleVerse @BibleId, 114015016, N'King Asa also removed Maacah his grandmother from her position as queen mother because she had made a loathsome Asherah pole. Asa cut down her Asherah pole and crushed and burned it in the Kidron Valley.'
EXEC add_BibleVerse @BibleId, 114015017, N'The high places were not eliminated from Israel, yet Asa was wholeheartedly devoted to the Lord throughout his lifetime.'
EXEC add_BibleVerse @BibleId, 114015018, N'He brought the holy items that his father and he had made into God’s temple, including the silver, gold, and other articles.'
EXEC add_BibleVerse @BibleId, 114015019, N'There was no more war until the thirty-fifth year of Asa’s reign.'
EXEC add_BibleVerse @BibleId, 114016001, N'In the thirty-sixth year of Asa’s reign, King Baasha of Israel attacked Judah, and he established Ramah as a military outpost to prevent anyone from leaving or entering the land of King Asa of Judah.'
EXEC add_BibleVerse @BibleId, 114016002, N'Asa took all the silver and gold that was left in the treasuries of the Lord’s temple and of the royal palace and sent it to King Ben Hadad of Syria, ruler in Damascus, along with this message:'
EXEC add_BibleVerse @BibleId, 114016003, N'“I want to make a treaty with you, like the one our fathers made. See, I have sent you silver and gold. Break your treaty with King Baasha of Israel, so he will retreat from my land.”'
EXEC add_BibleVerse @BibleId, 114016004, N'Ben Hadad accepted King Asa’s offer and ordered his army commanders to attack the cities of Israel. They conquered Ijon, Dan, Abel Maim, and all the storage cities of Naphtali.'
EXEC add_BibleVerse @BibleId, 114016005, N'When Baasha heard the news, he stopped fortifying Ramah and abandoned the project.'
EXEC add_BibleVerse @BibleId, 114016006, N'King Asa ordered all the men of Judah to carry away the stones and wood that Baasha had used to build Ramah. He used the materials to build up Geba and Mizpah.'
EXEC add_BibleVerse @BibleId, 114016007, N'At that time Hanani the prophet visited King Asa of Judah and said to him: “Because you relied on the king of Syria and did not rely on the Lord your God, the army of the king of Syria has escaped from your hand.'
EXEC add_BibleVerse @BibleId, 114016008, N'Did not the Cushites and Libyans have a huge army with chariots and a very large number of horsemen? But when you relied on the Lord, he handed them over to you!'
EXEC add_BibleVerse @BibleId, 114016009, N'Certainly the Lord watches the whole earth carefully and is ready to strengthen those who are devoted to him. You have acted foolishly in this matter; from now on you will have war.'
EXEC add_BibleVerse @BibleId, 114016010, N'Asa was so angry at the prophet, he put him in jail. Asa also oppressed some of the people at that time.'
EXEC add_BibleVerse @BibleId, 114016011, N'The events of Asa’s reign, from start to finish, are recorded in the Scroll of the Kings of Judah and Israel.'
EXEC add_BibleVerse @BibleId, 114016012, N'In the thirty-ninth year of his reign, Asa developed a foot disease. Though his disease was severe, he did not seek the Lord, but only the doctors.'
EXEC add_BibleVerse @BibleId, 114016013, N'Asa passed away in the forty-first year of his reign.'
EXEC add_BibleVerse @BibleId, 114016014, N'He was buried in the tomb he had carved out in the City of David. They laid him to rest on a bier covered with spices and assorted mixtures of ointments. They made a huge bonfire to honor him.'
EXEC add_BibleVerse @BibleId, 114017001, N'His son Jehoshaphat replaced him as king and solidified his rule over Israel.'
EXEC add_BibleVerse @BibleId, 114017002, N'He placed troops in all of Judah’s fortified cities and posted garrisons throughout the land of Judah and in the cities of Ephraim that his father Asa had seized.'
EXEC add_BibleVerse @BibleId, 114017003, N'The Lord was with Jehoshaphat because he followed in his ancestor David’s footsteps at the beginning of his reign. He did not seek the Baals,'
EXEC add_BibleVerse @BibleId, 114017004, N'but instead sought the God of his ancestors and obeyed his commands, unlike the Israelites.'
EXEC add_BibleVerse @BibleId, 114017005, N'The Lord made his kingdom secure; all Judah brought tribute to Jehoshaphat, and he became very wealthy and greatly respected.'
EXEC add_BibleVerse @BibleId, 114017006, N'He was committed to following the Lord; he even removed the high places and Asherah poles from Judah.'
EXEC add_BibleVerse @BibleId, 114017007, N'In the third year of his reign he sent his officials Ben-Hail, Obadiah, Zechariah, Nethanel, and Micaiah to teach in the cities of Judah.'
EXEC add_BibleVerse @BibleId, 114017008, N'They were accompanied by the Levites Shemaiah, Nethaniah, Zebadiah, Asahel, Shemiramoth, Jehonathan, Adonijah, Tobijah, and Tob-Adonijah, and by the priests Elishama and Jehoram.'
EXEC add_BibleVerse @BibleId, 114017009, N'They taught throughout Judah, taking with them the scroll of the law of the Lord. They traveled to all the cities of Judah and taught the people.'
EXEC add_BibleVerse @BibleId, 114017010, N'The Lord put fear into all the kingdoms surrounding Judah; they did not make war with Jehoshaphat.'
EXEC add_BibleVerse @BibleId, 114017011, N'Some of the Philistines brought Jehoshaphat tribute, including a load of silver. The Arabs brought him 7,700 rams and 7,700 goats from their flocks.'
EXEC add_BibleVerse @BibleId, 114017012, N'Jehoshaphat’s power kept increasing. He built fortresses and storage cities throughout Judah.'
EXEC add_BibleVerse @BibleId, 114017013, N'He had many supplies stored in the cities of Judah and an army of skilled warriors stationed in Jerusalem.'
EXEC add_BibleVerse @BibleId, 114017014, N'These were their divisions by families: There were a thousand officers from Judah. Adnah the commander led 300,000 skilled warriors,'
EXEC add_BibleVerse @BibleId, 114017015, N'Jehochanan the commander led 280,000,'
EXEC add_BibleVerse @BibleId, 114017016, N'and Amasiah son of Zikri, who volunteered to serve the Lord, led 200,000 skilled warriors.'
EXEC add_BibleVerse @BibleId, 114017017, N'From Benjamin, Eliada, a skilled warrior, led 200,000 men who were equipped with bows and shields,'
EXEC add_BibleVerse @BibleId, 114017018, N'and Jehozabad led 180,000 trained warriors.'
EXEC add_BibleVerse @BibleId, 114017019, N'These were the ones who served the king, besides those whom the king placed in the fortified cities throughout Judah.'
EXEC add_BibleVerse @BibleId, 114018001, N'Jehoshaphat was very wealthy and greatly respected. He made an alliance by marriage with Ahab,'
EXEC add_BibleVerse @BibleId, 114018002, N'and after several years went down to visit Ahab in Samaria. Ahab slaughtered many sheep and cattle to honor Jehoshaphat and those who came with him. He persuaded him to join in an attack against Ramoth Gilead.'
EXEC add_BibleVerse @BibleId, 114018003, N'King Ahab of Israel said to Jehoshaphat, “Will you go with me to attack Ramoth Gilead?” Jehoshaphat replied to the king of Israel, “I will support you; my army is at your disposal and will support you in battle.”'
EXEC add_BibleVerse @BibleId, 114018004, N'Then Jehoshaphat added, “First seek an oracle from the Lord.”'
EXEC add_BibleVerse @BibleId, 114018005, N'So the king of Israel assembled 400 prophets and asked them, “Should we attack Ramoth Gilead or not?” They said, “Attack! God will hand it over to the king.”'
EXEC add_BibleVerse @BibleId, 114018006, N'But Jehoshaphat asked, “Is there not a prophet of the Lord still here, that we may ask him?”'
EXEC add_BibleVerse @BibleId, 114018007, N'The king of Israel answered Jehoshaphat, “There is still one man through whom we can seek the Lord’s will. But I despise him because he does not prophesy prosperity for me, but always disaster. His name is Micaiah son of Imlah. Jehoshaphat said, “The king should not say such things!”'
EXEC add_BibleVerse @BibleId, 114018008, N'The king of Israel summoned an officer and said, “Quickly bring Micaiah son of Imlah.”'
EXEC add_BibleVerse @BibleId, 114018009, N'Now the king of Israel and King Jehoshaphat of Judah were sitting on their respective thrones, dressed in their royal robes, at the threshing floor at the entrance of the gate of Samaria. All the prophets were prophesying before them.'
EXEC add_BibleVerse @BibleId, 114018010, N'Zedekiah son of Kenaanah made iron horns and said, “This is what the Lord says, ‘With these you will gore Syria until they are destroyed!’”'
EXEC add_BibleVerse @BibleId, 114018011, N'All the prophets were prophesying the same, saying, “Attack Ramoth Gilead! You will succeed; the Lord will hand it over to the king!”'
EXEC add_BibleVerse @BibleId, 114018012, N'Now the messenger who went to summon Micaiah said to him, “Look, the prophets are in complete agreement that the king will succeed. Your words must agree with theirs; you must predict success!”'
EXEC add_BibleVerse @BibleId, 114018013, N'But Micaiah said, “As certainly as the Lord lives, I will say what my God tells me to say!”'
EXEC add_BibleVerse @BibleId, 114018014, N'Micaiah came before the king and the king asked him, “Micaiah, should we attack Ramoth Gilead or not?” He answered him, “Attack! You will succeed; they will be handed over to you.”'
EXEC add_BibleVerse @BibleId, 114018015, N'The king said to him, “How many times must I make you solemnly promise in the name of the Lord to tell me only the truth?”'
EXEC add_BibleVerse @BibleId, 114018016, N'Micaiah replied, “I saw all Israel scattered on the mountains like sheep that have no shepherd. Then the Lord said, ‘They have no master. They should go home in peace.’”'
EXEC add_BibleVerse @BibleId, 114018017, N'The king of Israel said to Jehoshaphat, “Didn’t I tell you he does not prophesy prosperity for me, but disaster?”'
EXEC add_BibleVerse @BibleId, 114018018, N'Micaiah said, “That being the case, hear the word of the Lord: I saw the Lord sitting on his throne, with all the heavenly assembly standing on his right and on his left.'
EXEC add_BibleVerse @BibleId, 114018019, N'The Lord said, ‘Who will deceive King Ahab of Israel, so he will attack Ramoth Gilead and die there?’ One said this and another that.'
EXEC add_BibleVerse @BibleId, 114018020, N'Then a spirit stepped forward and stood before the Lord. He said, ‘I will deceive him.’ The Lord asked him, ‘How?’'
EXEC add_BibleVerse @BibleId, 114018021, N'He replied, ‘I will go out and be a lying spirit in the mouths of all his prophets.’ The Lord said, ‘Deceive and overpower him. Go out and do as you have proposed.’'
EXEC add_BibleVerse @BibleId, 114018022, N'So now, look, the Lord has placed a lying spirit in the mouths of all these prophets of yours; but the Lord has decreed disaster for you.”'
EXEC add_BibleVerse @BibleId, 114018023, N'Zedekiah son of Kenaanah approached, hit Micaiah on the jaw, and said, “Which way did the Lord’s spirit go when he went from me to speak to you?”'
EXEC add_BibleVerse @BibleId, 114018024, N'Micaiah replied, “Look, you will see in the day when you go into an inner room to hide.”'
EXEC add_BibleVerse @BibleId, 114018025, N'Then the king of Israel said, “Take Micaiah and return him to Amon the city official and Joash the king’s son.'
EXEC add_BibleVerse @BibleId, 114018026, N'Say, ‘This is what the king says: “Put this man in prison. Give him only a little bread and water until I return safely.”’”'
EXEC add_BibleVerse @BibleId, 114018027, N'Micaiah said, “If you really do return safely, then the Lord has not spoken through me!” Then he added, “Take note, all you people.”'
EXEC add_BibleVerse @BibleId, 114018028, N'The king of Israel and King Jehoshaphat of Judah attacked Ramoth Gilead.'
EXEC add_BibleVerse @BibleId, 114018029, N'The king of Israel said to Jehoshaphat, “I will disguise myself and then enter the battle; but you wear your royal attire.” So the king of Israel disguised himself and they entered the battle.'
EXEC add_BibleVerse @BibleId, 114018030, N'Now the king of Syria had ordered his chariot commanders, “Do not fight common soldiers or high ranking officers; fight only the king of Israel!”'
EXEC add_BibleVerse @BibleId, 114018031, N'When the chariot commanders saw Jehoshaphat, they said, “He must be the king of Israel!” So they turned and attacked him, but Jehoshaphat cried out. The Lord helped him; God lured them away from him.'
EXEC add_BibleVerse @BibleId, 114018032, N'When the chariot commanders realized he was not the king of Israel, they turned away from him.'
EXEC add_BibleVerse @BibleId, 114018033, N'Now an archer shot an arrow at random and it struck the king of Israel between the plates of his armor. The king ordered his charioteer, “Turn around and take me from the battle line, for I am wounded.”'
EXEC add_BibleVerse @BibleId, 114018034, N'While the battle raged throughout the day, the king stood propped up in his chariot opposite the Syrians. He died in the evening as the sun was setting.'
EXEC add_BibleVerse @BibleId, 114019001, N'When King Jehoshaphat of Judah returned home safely to Jerusalem,'
EXEC add_BibleVerse @BibleId, 114019002, N'the prophet Jehu son of Hanani confronted him; he said to King Jehoshaphat, “Is it right to help the wicked and be an ally of those who oppose the Lord? Because you have done this the Lord is angry with you!'
EXEC add_BibleVerse @BibleId, 114019003, N'Nevertheless you have done some good things; you removed the Asherah poles from the land and you were determined to follow the Lord.”'
EXEC add_BibleVerse @BibleId, 114019004, N'Jehoshaphat lived in Jerusalem. He went out among the people from Beer Sheba to the hill country of Ephraim and encouraged them to follow the Lord God of their ancestors.'
EXEC add_BibleVerse @BibleId, 114019005, N'He appointed judges throughout the land and in each of the fortified cities of Judah.'
EXEC add_BibleVerse @BibleId, 114019006, N'He told the judges, “Be careful what you do, for you are not judging for men, but for the Lord, who will be with you when you make judicial decisions.'
EXEC add_BibleVerse @BibleId, 114019007, N'Respect the Lord and make careful decisions, for the Lord our God disapproves of injustice, partiality, and bribery.”'
EXEC add_BibleVerse @BibleId, 114019008, N'In Jerusalem Jehoshaphat appointed some Levites, priests, and Israelite family leaders to judge on behalf of the Lord and to settle disputes among the residents of Jerusalem.'
EXEC add_BibleVerse @BibleId, 114019009, N'He commanded them: “Carry out your duties with respect for the Lord, with honesty, and with pure motives.'
EXEC add_BibleVerse @BibleId, 114019010, N'Whenever your countrymen who live in the cities bring a case before you (whether it involves a violent crime or other matters related to the law, commandments, rules, and regulations), warn them that they must not sin against the Lord. If you fail to do so, God will be angry with you and your colleagues; but if you obey, you will be free of guilt.'
EXEC add_BibleVerse @BibleId, 114019011, N'You will report to Amariah the chief priest in all matters pertaining to the Lord’s law, and to Zebadiah son of Ishmael, the leader of the family of Judah, in all matters pertaining to the king. The Levites will serve as officials before you. Confidently carry out your duties! May the Lord be with those who do well!”'
EXEC add_BibleVerse @BibleId, 114020001, N'Later the Moabites and Ammonites, along with some of the Meunites, attacked Jehoshaphat.'
EXEC add_BibleVerse @BibleId, 114020002, N'Messengers arrived and reported to Jehoshaphat, “A huge army is attacking you from the other side of the Dead Sea, from the direction of Edom. Look, they are in Hazezon Tamar (that is, En Gedi).”'
EXEC add_BibleVerse @BibleId, 114020003, N'Jehoshaphat was afraid, so he decided to seek the Lord’s advice. He decreed that all Judah should observe a fast.'
EXEC add_BibleVerse @BibleId, 114020004, N'The people of Judah assembled to ask for the Lord’s help; they came from all the cities of Judah to ask for the Lord’s help.'
EXEC add_BibleVerse @BibleId, 114020005, N'Jehoshaphat stood before the assembly of Judah and Jerusalem at the Lord’s temple, in front of the new courtyard.'
EXEC add_BibleVerse @BibleId, 114020006, N'He prayed: “O Lord God of our ancestors, you are the God who lives in heaven and rules over all the kingdoms of the nations. You possess strength and power; no one can stand against you.'
EXEC add_BibleVerse @BibleId, 114020007, N'Our God, you drove out the inhabitants of this land before your people Israel and gave it as a permanent possession to the descendants of your friend Abraham.'
EXEC add_BibleVerse @BibleId, 114020008, N'They settled down in it and built in it a temple to honor you, saying,'
EXEC add_BibleVerse @BibleId, 114020009, N'‘If disaster comes on us in the form of military attack, judgment, plague, or famine, we will stand in front of this temple before you, for you are present in this temple. We will cry out to you for help in our distress, so that you will hear and deliver us.’'
EXEC add_BibleVerse @BibleId, 114020010, N'Now the Ammonites, Moabites, and men from Mount Seir are coming! When Israel came from the land of Egypt, you did not allow them to invade these lands. They bypassed them and did not destroy them.'
EXEC add_BibleVerse @BibleId, 114020011, N'Look how they are repaying us! They come to drive us out of our allotted land which you assigned to us!'
EXEC add_BibleVerse @BibleId, 114020012, N'Our God, will you not judge them? For we are powerless against this huge army that attacks us! We don’t know what we should do; we look to you for help.”'
EXEC add_BibleVerse @BibleId, 114020013, N'All the men of Judah were standing before the Lord, along with their infants, wives, and children.'
EXEC add_BibleVerse @BibleId, 114020014, N'Then in the midst of the assembly, the Lord’s Spirit came upon Jachaziel son of Zechariah, son of Benaiah, son of Jeiel, son of Mattaniah, a Levite and descendant of Asaph.'
EXEC add_BibleVerse @BibleId, 114020015, N'He said: “Pay attention, all you people of Judah, residents of Jerusalem, and King Jehoshaphat! This is what the Lord says to you: ‘Don’t be afraid and don’t panic because of this huge army! For the battle is not yours, but God’s.'
EXEC add_BibleVerse @BibleId, 114020016, N'Tomorrow march down against them as they come up the Ascent of Ziz. You will find them at the end of the ravine in front of the Desert of Jeruel.'
EXEC add_BibleVerse @BibleId, 114020017, N'You will not fight in this battle. Take your positions, stand, and watch the Lord deliver you, O Judah and Jerusalem. Don’t be afraid and don’t panic! Tomorrow march out toward them; the Lord is with you!’”'
EXEC add_BibleVerse @BibleId, 114020018, N'Jehoshaphat bowed down with his face toward the ground, and all the people of Judah and the residents of Jerusalem fell down before the Lord and worshiped him.'
EXEC add_BibleVerse @BibleId, 114020019, N'Then some Levites, from the Kohathites and Korahites, got up and loudly praised the Lord God of Israel.'
EXEC add_BibleVerse @BibleId, 114020020, N'Early the next morning they marched out to the Desert of Tekoa. When they were ready to march, Jehoshaphat stood up and said: “Listen to me, you people of Judah and residents of Jerusalem! Trust in the Lord your God and you will be safe! Trust in the message of his prophets and you will win.”'
EXEC add_BibleVerse @BibleId, 114020021, N'He met with the people and appointed musicians to play before the Lord and praise his majestic splendor. As they marched ahead of the warriors they said: “Give thanks to the Lord, for his loyal love endures.”'
EXEC add_BibleVerse @BibleId, 114020022, N'When they began to shout and praise, the Lord suddenly attacked the Ammonites, Moabites, and men from Mount Seir who were invading Judah, and they were defeated.'
EXEC add_BibleVerse @BibleId, 114020023, N'The Ammonites and Moabites attacked the men from Mount Seir and annihilated them. When they had finished off the men of Seir, they attacked and destroyed one another.'
EXEC add_BibleVerse @BibleId, 114020024, N'When the men of Judah arrived at the observation post overlooking the desert and looked at the huge army, they saw dead bodies on the ground; there were no survivors!'
EXEC add_BibleVerse @BibleId, 114020025, N'Jehoshaphat and his men went to gather the plunder; they found a huge amount of supplies, clothing and valuable items. They carried away everything they could. There was so much plunder, it took them three days to haul it off.'
EXEC add_BibleVerse @BibleId, 114020026, N'On the fourth day they assembled in the Valley of Berachah, where they praised the Lord. So that place is called the Valley of Berachah to this very day.'
EXEC add_BibleVerse @BibleId, 114020027, N'Then all the men of Judah and Jerusalem returned joyfully to Jerusalem with Jehoshaphat leading them; the Lord had given them reason to rejoice over their enemies.'
EXEC add_BibleVerse @BibleId, 114020028, N'They entered Jerusalem to the sound of stringed instruments and trumpets and proceeded to the temple of the Lord.'
EXEC add_BibleVerse @BibleId, 114020029, N'All the kingdoms of the surrounding lands were afraid of God when they heard how the Lord had fought against Israel’s enemies.'
EXEC add_BibleVerse @BibleId, 114020030, N'Jehoshaphat’s kingdom enjoyed peace; his God made him secure on every side.'
EXEC add_BibleVerse @BibleId, 114020031, N'Jehoshaphat reigned over Judah. He was thirty-five years old when he became king and he reigned for twenty-five years in Jerusalem. His mother was Azubah, the daughter of Shilhi.'
EXEC add_BibleVerse @BibleId, 114020032, N'He followed in his father Asa’s footsteps and was careful to do what the Lord approved.'
EXEC add_BibleVerse @BibleId, 114020033, N'However, the high places were not eliminated; the people were still not devoted to the God of their ancestors.'
EXEC add_BibleVerse @BibleId, 114020034, N'The rest of the events of Jehoshaphat’s reign, from start to finish, are recorded in the Annals of Jehu son of Hanani which are included in Scroll of the Kings of Israel.'
EXEC add_BibleVerse @BibleId, 114020035, N'Later King Jehoshaphat of Judah made an alliance with King Ahaziah of Israel, who did evil.'
EXEC add_BibleVerse @BibleId, 114020036, N'They agreed to make large seagoing merchant ships; they built the ships in Ezion Geber.'
EXEC add_BibleVerse @BibleId, 114020037, N'Eliezer son of Dodavahu from Mareshah prophesied against Jehoshaphat, “Because you made an alliance with Ahaziah, the Lord will shatter what you have made.” The ships were wrecked and unable to go to sea.'
EXEC add_BibleVerse @BibleId, 114021001, N'Jehoshaphat passed away and was buried with his ancestors in the City of David. His son Jehoram replaced him as king.'
EXEC add_BibleVerse @BibleId, 114021002, N'His brothers, Jehoshaphat’s sons, were Azariah, Jechiel, Zechariah, Azariahu, Michael, and Shephatiah. All of these were sons of King Jehoshaphat of Israel.'
EXEC add_BibleVerse @BibleId, 114021003, N'Their father gave them many presents, including silver, gold, and other precious items, along with fortified cities in Judah. But he gave the kingdom to Jehoram because he was the firstborn.'
EXEC add_BibleVerse @BibleId, 114021004, N'Jehoram took control of his father’s kingdom and became powerful. Then he killed all his brothers, as well as some of the officials of Israel.'
EXEC add_BibleVerse @BibleId, 114021005, N'Jehoram was thirty-two years old when he became king and he reigned for eight years in Jerusalem.'
EXEC add_BibleVerse @BibleId, 114021006, N'He followed in the footsteps of the kings of Israel, just as Ahab’s dynasty had done, for he married Ahab’s daughter. He did evil in the sight of the Lord.'
EXEC add_BibleVerse @BibleId, 114021007, N'But the Lord was unwilling to destroy David’s dynasty because of the promise he had made to give David a perpetual dynasty.'
EXEC add_BibleVerse @BibleId, 114021008, N'During Jehoram’s reign Edom freed themselves from Judah’s control and set up their own king.'
EXEC add_BibleVerse @BibleId, 114021009, N'Jehoram crossed over to Zair with his officers and all his chariots. The Edomites, who had surrounded him, attacked at night and defeated him and his chariot officers.'
EXEC add_BibleVerse @BibleId, 114021010, N'So Edom has remained free from Judah’s control to this very day. At that same time Libnah also rebelled and freed themselves from Judah’s control because Jehoram rejected the Lord God of his ancestors.'
EXEC add_BibleVerse @BibleId, 114021011, N'He also built high places on the hills of Judah; he encouraged the residents of Jerusalem to be unfaithful to the Lord and led Judah away from the Lord.'
EXEC add_BibleVerse @BibleId, 114021012, N'Jehoram received this letter from Elijah the prophet: “This is what the Lord God of your ancestor David says: ‘You have not followed in the footsteps of your father Jehoshaphat and of King Asa of Judah,'
EXEC add_BibleVerse @BibleId, 114021013, N'but have instead followed in the footsteps of the kings of Israel. You encouraged the people of Judah and the residents of Jerusalem to be unfaithful to the Lord, just as the family of Ahab does in Israel. You also killed your brothers, members of your father’s family, who were better than you.'
EXEC add_BibleVerse @BibleId, 114021014, N'So look, the Lord is about to severely afflict your people, your sons, your wives, and all you own.'
EXEC add_BibleVerse @BibleId, 114021015, N'And you will get a serious, chronic intestinal disease which will cause your intestines to come out.”'
EXEC add_BibleVerse @BibleId, 114021016, N'The Lord stirred up against Jehoram the Philistines and the Arabs who lived beside the Cushites.'
EXEC add_BibleVerse @BibleId, 114021017, N'They attacked Judah and swept through it. They carried off everything they found in the royal palace, including his sons and wives. None of his sons was left, except for his youngest, Ahaziah.'
EXEC add_BibleVerse @BibleId, 114021018, N'After all this happened, the Lord afflicted him with an incurable intestinal disease.'
EXEC add_BibleVerse @BibleId, 114021019, N'After about two years his intestines came out because of the disease, so that he died a very painful death. His people did not make a bonfire to honor him, as they had done for his ancestors.'
EXEC add_BibleVerse @BibleId, 114021020, N'Jehoram was thirty-two years old when he became king and he reigned eight years in Jerusalem. No one regretted his death; he was buried in the City of David, but not in the royal tombs.'
EXEC add_BibleVerse @BibleId, 114022001, N'The residents of Jerusalem made his youngest son Ahaziah king in his place, for the raiding party that invaded the city with the Arabs had killed all the older sons. So Ahaziah son of Jehoram became king of Judah.'
EXEC add_BibleVerse @BibleId, 114022002, N'Ahaziah was twenty-two years old when he became king and he reigned for one year in Jerusalem. His mother was Athaliah, the granddaughter of Omri.'
EXEC add_BibleVerse @BibleId, 114022003, N'He followed in the footsteps of Ahab’s dynasty, for his mother gave him evil advice.'
EXEC add_BibleVerse @BibleId, 114022004, N'He did evil in the sight of the Lord like Ahab’s dynasty because, after his father’s death, they gave him advice that led to his destruction.'
EXEC add_BibleVerse @BibleId, 114022005, N'He followed their advice and joined Ahab’s son King Joram of Israel in a battle against King Hazael of Syria at Ramoth Gilead in which the Syrians defeated Joram.'
EXEC add_BibleVerse @BibleId, 114022006, N'Joram returned to Jezreel to recover from the wounds he received from the Syrians in Ramah when he fought against King Hazael of Syria. Ahaziah son of King Jehoram of Judah went down to visit Joram son of Ahab in Jezreel, because he had been wounded.'
EXEC add_BibleVerse @BibleId, 114022007, N'God brought about Ahaziah’s downfall through his visit to Joram. When Ahaziah arrived, he went out with Joram to meet Jehu son of Nimshi, whom the Lord had commissioned to wipe out Ahab’s family.'
EXEC add_BibleVerse @BibleId, 114022008, N'While Jehu was dishing out punishment to Ahab’s family, he discovered the officials of Judah and the sons of Ahaziah’s relatives who were serving Ahaziah and killed them.'
EXEC add_BibleVerse @BibleId, 114022009, N'He looked for Ahaziah, who was captured while hiding in Samaria. They brought him to Jehu and then executed him. They did give him a burial, for they reasoned, “He is the son of Jehoshaphat, who sought the Lord with his whole heart.” There was no one in Ahaziah’s family strong enough to rule in his place.'
EXEC add_BibleVerse @BibleId, 114022010, N'When Athaliah the mother of Ahaziah saw that her son was dead, she was determined to destroy the entire royal line of Judah.'
EXEC add_BibleVerse @BibleId, 114022011, N'So Jehoshabeath, the daughter of King Jehoram, took Ahaziah’s son Joash and sneaked him away from the rest of the royal descendants who were to be executed. She hid him and his nurse in the room where the bed covers were stored. So Jehoshabeath the daughter of King Jehoram, wife of Jehoiada the priest and sister of Ahaziah, hid him from Athaliah so she could not execute him.'
EXEC add_BibleVerse @BibleId, 114022012, N'He remained in hiding in God’s temple for six years, while Athaliah was ruling over the land.'
EXEC add_BibleVerse @BibleId, 114023001, N'In the seventh year Jehoiada made a bold move. He made a pact with the officers of the units of hundreds: Azariah son of Jehoram, Ishmael son of Jehochanan, Azariah son of Obed, Maaseiah son of Adaiah, and Elishaphat son of Zikri.'
EXEC add_BibleVerse @BibleId, 114023002, N'They traveled throughout Judah and assembled the Levites from all the cities of Judah, as well as the Israelite family leaders. They came to Jerusalem,'
EXEC add_BibleVerse @BibleId, 114023003, N'and the whole assembly made a covenant with the king in the temple of God. Jehoiada said to them, “The king’s son will rule, just as the Lord promised David’s descendants.'
EXEC add_BibleVerse @BibleId, 114023004, N'This is what you must do. One third of you priests and Levites who are on duty during the Sabbath will guard the doors.'
EXEC add_BibleVerse @BibleId, 114023005, N'Another third of you will be stationed at the royal palace and still another third at the Foundation Gate. All the others will stand in the courtyards of the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 114023006, N'No one must enter the Lord’s temple except the priests and Levites who are on duty. They may enter because they are ceremonially pure. All the others should carry out their assigned service to the Lord.'
EXEC add_BibleVerse @BibleId, 114023007, N'The Levites must surround the king. Each of you must hold his weapon in his hand. Whoever tries to enter the temple must be killed. You must accompany the king wherever he goes.”'
EXEC add_BibleVerse @BibleId, 114023008, N'The Levites and all the men of Judah did just as Jehoiada the priest ordered. Each of them took his men, those who were on duty during the Sabbath as well as those who were off duty on the Sabbath. Jehoiada the priest did not release his divisions from their duties.'
EXEC add_BibleVerse @BibleId, 114023009, N'Jehoiada the priest gave to the officers of the units of hundreds King David’s spears and shields that were kept in God’s temple.'
EXEC add_BibleVerse @BibleId, 114023010, N'He placed the men at their posts, each holding his weapon in his hand. They lined up from the south side of the temple to the north side and stood near the altar and the temple, surrounding the king.'
EXEC add_BibleVerse @BibleId, 114023011, N'Jehoiada and his sons led out the king’s son and placed on him the crown and the royal insignia. They proclaimed him king and poured olive oil on his head. They declared, “Long live the king!”'
EXEC add_BibleVerse @BibleId, 114023012, N'When Athaliah heard the royal guard shouting and praising the king, she joined the crowd at the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 114023013, N'Then she saw the king standing by his pillar at the entrance. The officers and trumpeters stood beside the king and all the people of the land were celebrating and blowing trumpets, and the musicians with various instruments were leading the celebration. Athaliah tore her clothes and yelled, “Treason! Treason!”'
EXEC add_BibleVerse @BibleId, 114023014, N'Jehoiada the priest sent out the officers of the units of hundreds, who were in charge of the army, and ordered them, “Bring her outside the temple to the guards. Put the sword to anyone who follows her.” The priest gave this order because he had decided she should not be executed in the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 114023015, N'They seized her and took her into the precincts of the royal palace through the horses’ entrance. There they executed her.'
EXEC add_BibleVerse @BibleId, 114023016, N'Jehoiada then drew up a covenant stipulating that he, all the people, and the king should be loyal to the Lord.'
EXEC add_BibleVerse @BibleId, 114023017, N'All the people went and demolished the temple of Baal. They smashed its altars and idols. They killed Mattan the priest of Baal in front of the altars.'
EXEC add_BibleVerse @BibleId, 114023018, N'Jehoiada then assigned the duties of the Lord’s temple to the priests, the Levites whom David had assigned to the Lord’s temple. They were responsible for offering burnt sacrifices to the Lord with joy and music, according to the law of Moses and the edict of David.'
EXEC add_BibleVerse @BibleId, 114023019, N'He posted guards at the gates of the Lord’s temple, so no one who was ceremonially unclean in any way could enter.'
EXEC add_BibleVerse @BibleId, 114023020, N'He summoned the officers of the units of hundreds, the nobles, the rulers of the people, and all the people of land, and he then led the king down from the Lord’s temple. They entered the royal palace through the Upper Gate and seated the king on the royal throne.'
EXEC add_BibleVerse @BibleId, 114023021, N'All the people of the land celebrated, for the city had rest now that they had killed Athaliah.'
EXEC add_BibleVerse @BibleId, 114024001, N'Joash was seven years old when he began to reign. He reigned for forty years in Jerusalem. His mother was Zibiah, who was from Beer Sheba.'
EXEC add_BibleVerse @BibleId, 114024002, N'Joash did what the Lord approved throughout the lifetime of Jehoiada the priest.'
EXEC add_BibleVerse @BibleId, 114024003, N'Jehoiada chose two wives for him who gave him sons and daughters.'
EXEC add_BibleVerse @BibleId, 114024004, N'Joash was determined to repair the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 114024005, N'He assembled the priests and Levites and ordered them, “Go out to the cities of Judah and collect the annual quota of silver from all Israel for repairs on the temple of your God. Be quick about it!” But the Levites delayed.'
EXEC add_BibleVerse @BibleId, 114024006, N'So the king summoned Jehoiada the chief priest, and said to him, “Why have you not made the Levites collect from Judah and Jerusalem the tax authorized by Moses the Lord’s servant and by the assembly of Israel at the tent containing the tablets of the law?”'
EXEC add_BibleVerse @BibleId, 114024007, N'(Wicked Athaliah and her sons had broken into God’s temple and used all the holy items of the Lord’s temple in their worship of the Baals.)'
EXEC add_BibleVerse @BibleId, 114024008, N'The king ordered a chest to be made and placed outside the gate of the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 114024009, N'An edict was sent throughout Judah and Jerusalem requiring the people to bring to the Lord the tax that Moses, God’s servant, imposed on Israel in the wilderness.'
EXEC add_BibleVerse @BibleId, 114024010, N'All the officials and all the people gladly brought their silver and threw it into the chest until it was full.'
EXEC add_BibleVerse @BibleId, 114024011, N'Whenever the Levites brought the chest to the royal accountant and they saw there was a lot of silver, the royal scribe and the accountant of the high priest emptied the chest and then took it back to its place. They went through this routine every day and collected a large amount of silver.'
EXEC add_BibleVerse @BibleId, 114024012, N'The king and Jehoiada gave it to the construction foremen assigned to the Lord’s temple. They hired carpenters and craftsmen to repair the Lord’s temple, as well as those skilled in working with iron and bronze to restore the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 114024013, N'They worked hard and made the repairs. They followed the measurements specified for God’s temple and restored it.'
EXEC add_BibleVerse @BibleId, 114024014, N'When they were finished, they brought the rest of the silver to the king and Jehoiada. They used it to make items for the Lord’s temple, including items used in the temple service and for burnt sacrifices, pans, and various other gold and silver items. Throughout Jehoiada’s lifetime, burnt sacrifices were offered regularly in the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 114024015, N'Jehoiada grew old and died at the age of 130.'
EXEC add_BibleVerse @BibleId, 114024016, N'He was buried in the City of David with the kings, because he had accomplished good in Israel and for God and his temple.'
EXEC add_BibleVerse @BibleId, 114024017, N'After Jehoiada died, the officials of Judah visited the king and declared their loyalty to him. The king listened to their advice.'
EXEC add_BibleVerse @BibleId, 114024018, N'They abandoned the temple of the Lord God of their ancestors, and worshiped the Asherah poles and idols. Because of this sinful activity, God was angry with Judah and Jerusalem.'
EXEC add_BibleVerse @BibleId, 114024019, N'The Lord sent prophets among them to lead them back to him. They warned the people, but they would not pay attention.'
EXEC add_BibleVerse @BibleId, 114024020, N'God’s Spirit energized Zechariah son of Jehoiada the priest. He stood up before the people and said to them, “This is what God says: ‘Why are you violating the commands of the Lord? You will not be prosperous! Because you have rejected the Lord, he has rejected you!’”'
EXEC add_BibleVerse @BibleId, 114024021, N'They plotted against him and by royal decree stoned him to death in the courtyard of the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 114024022, N'King Joash disregarded the loyalty his father Jehoiada had shown him and killed Jehoiada’s son. As Zechariah was dying, he said, “May the Lord take notice and seek vengeance!”'
EXEC add_BibleVerse @BibleId, 114024023, N'At the beginning of the year the Syrian army attacked Joash and invaded Judah and Jerusalem. They wiped out all the leaders of the people and sent all the plunder they gathered to the king of Damascus.'
EXEC add_BibleVerse @BibleId, 114024024, N'Even though the invading Syrian army was relatively weak, the Lord handed over to them Judah’s very large army, for the people of Judah had abandoned the Lord God of their ancestors. The Syrians gave Joash what he deserved.'
EXEC add_BibleVerse @BibleId, 114024025, N'When they withdrew, they left Joash badly wounded. His servants plotted against him because of what he had done to the son of Jehoiada the priest. They murdered him on his bed. Thus he died and was buried in the City of David, but not in the tombs of the kings.'
EXEC add_BibleVerse @BibleId, 114024026, N'The conspirators were Zabad son of Shimeath (an Ammonite woman) and Jehozabad son of Shimrith (a Moabite woman).'
EXEC add_BibleVerse @BibleId, 114024027, N'The list of Joash’s sons, the many prophetic oracles pertaining to him, and the account of his building project on God’s temple are included in the record of the Scroll of the Kings. His son Amaziah replaced him as king.'
EXEC add_BibleVerse @BibleId, 114025001, N'Amaziah was twenty-five years old when he began to reign, and he reigned for twenty-nine years in Jerusalem. His mother was Jehoaddan, who was from Jerusalem.'
EXEC add_BibleVerse @BibleId, 114025002, N'He did what the Lord approved, but not with wholehearted devotion.'
EXEC add_BibleVerse @BibleId, 114025003, N'When he had secured control of the kingdom, he executed the servants who had assassinated his father.'
EXEC add_BibleVerse @BibleId, 114025004, N'However, he did not execute their sons. He obeyed the Lord’s commandment as recorded in the law scroll of Moses, “Fathers must not be executed for what their sons do, and sons must not be executed for what their fathers do. A man must be executed only for his own sin.”'
EXEC add_BibleVerse @BibleId, 114025005, N'Amaziah assembled the people of Judah and assigned them by families to the commanders of units of a thousand and the commanders of units of a hundred for all Judah and Benjamin. He counted those twenty years old and up and discovered there were 300,000 young men of fighting age equipped with spears and shields.'
EXEC add_BibleVerse @BibleId, 114025006, N'He hired 100,000 Israelite warriors for a hundred talents of silver.'
EXEC add_BibleVerse @BibleId, 114025007, N'But a prophet visited him and said: “O king, the Israelite troops must not go with you, for the Lord is not with Israel or any of the Ephraimites.'
EXEC add_BibleVerse @BibleId, 114025008, N'Even if you go and fight bravely in battle, God will defeat you before the enemy. God is capable of helping or defeating.”'
EXEC add_BibleVerse @BibleId, 114025009, N'Amaziah asked the prophet: “But what should I do about the hundred talents of silver I paid the Israelite troops?” The prophet replied, “The Lord is capable of giving you more than that.”'
EXEC add_BibleVerse @BibleId, 114025010, N'So Amaziah dismissed the troops that had come to him from Ephraim and sent them home. They were very angry at Judah and returned home incensed.'
EXEC add_BibleVerse @BibleId, 114025011, N'Amaziah boldly led his army to the Valley of Salt, where he defeated 10,000 Edomites.'
EXEC add_BibleVerse @BibleId, 114025012, N'The men of Judah captured 10,000 men alive. They took them to the top of a cliff and threw them over. All the captives fell to their death.'
EXEC add_BibleVerse @BibleId, 114025013, N'Now the troops Amaziah had dismissed and had not allowed to fight in the battle raided the cities of Judah from Samaria to Beth Horon. They killed 3,000 people and carried off a large amount of plunder.'
EXEC add_BibleVerse @BibleId, 114025014, N'When Amaziah returned from defeating the Edomites, he brought back the gods of the people of Seir and made them his personal gods. He bowed down before them and offered them sacrifices.'
EXEC add_BibleVerse @BibleId, 114025015, N'The Lord was angry at Amaziah and sent a prophet to him, who said, “Why are you following these gods that could not deliver their own people from your power?”'
EXEC add_BibleVerse @BibleId, 114025016, N'While he was speaking, Amaziah said to him, “Did we appoint you to be a royal counselor? Stop prophesying or else you will be killed!” So the prophet stopped, but added, “I know that the Lord has decided to destroy you, because you have done this thing and refused to listen to my advice.”'
EXEC add_BibleVerse @BibleId, 114025017, N'After King Amaziah of Judah consulted with his advisers, he sent this message to the king of Israel, Joash son of Jehoahaz, the son of Jehu, “Come, face me on the battlefield.”'
EXEC add_BibleVerse @BibleId, 114025018, N'King Joash of Israel sent this message back to King Amaziah of Judah, “A thorn bush in Lebanon sent this message to a cedar in Lebanon, ‘Give your daughter to my son as a wife.’ Then a wild animal of Lebanon came by and trampled down the thorn bush.'
EXEC add_BibleVerse @BibleId, 114025019, N'You defeated Edom and it has gone to your head. Gloat over your success, but stay in your palace. Why bring calamity on yourself? Why bring down yourself and Judah along with you?”'
EXEC add_BibleVerse @BibleId, 114025020, N'But Amaziah did not heed the warning, for God wanted to hand them over to Joash because they followed the gods of Edom.'
EXEC add_BibleVerse @BibleId, 114025021, N'So King Joash of Israel attacked. He and King Amaziah of Judah faced each other on the battlefield in Beth Shemesh of Judah.'
EXEC add_BibleVerse @BibleId, 114025022, N'Judah was defeated by Israel, and each man ran back home.'
EXEC add_BibleVerse @BibleId, 114025023, N'King Joash of Israel captured King Amaziah of Judah, son of Joash son of Jehoahaz, in Beth Shemesh and brought him to Jerusalem. He broke down the wall of Jerusalem from the Gate of Ephraim to the Corner Gate – a distance of about six hundred feet.'
EXEC add_BibleVerse @BibleId, 114025024, N'He took away all the gold and silver, all the items found in God’s temple that were in the care of Obed-Edom, the riches in the royal palace, and some hostages. Then he went back to Samaria.'
EXEC add_BibleVerse @BibleId, 114025025, N'King Amaziah son of Joash of Judah lived for fifteen years after the death of King Joash son of Jehoahaz of Israel.'
EXEC add_BibleVerse @BibleId, 114025026, N'The rest of the events of Amaziah’s reign, from start to finish, are recorded in the Scroll of the Kings of Judah and Israel.'
EXEC add_BibleVerse @BibleId, 114025027, N'From the time Amaziah turned from following the Lord, conspirators plotted against him in Jerusalem, so he fled to Lachish. But they sent assassins after him and they killed him there.'
EXEC add_BibleVerse @BibleId, 114025028, N'His body was carried back by horses, and he was buried in Jerusalem with his ancestors in the City of David.'
EXEC add_BibleVerse @BibleId, 114026001, N'All the people of Judah took Uzziah, who was sixteen years old, and made him king in his father Amaziah’s place.'
EXEC add_BibleVerse @BibleId, 114026002, N'Uzziah built up Elat and restored it to Judah after King Amaziah had passed away.'
EXEC add_BibleVerse @BibleId, 114026003, N'Uzziah was sixteen years old when he began to reign, and he reigned for fifty-two years in Jerusalem. His mother’s name was Jecholiah, who was from Jerusalem.'
EXEC add_BibleVerse @BibleId, 114026004, N'He did what the Lord approved, just as his father Amaziah had done.'
EXEC add_BibleVerse @BibleId, 114026005, N'He followed God during the lifetime of Zechariah, who taught him how to honor God. As long as he followed the Lord, God caused him to succeed.'
EXEC add_BibleVerse @BibleId, 114026006, N'Uzziah attacked the Philistines and broke down the walls of Gath, Jabneh, and Ashdod. He built cities in the region of Ashdod and throughout Philistine territory.'
EXEC add_BibleVerse @BibleId, 114026007, N'God helped him in his campaigns against the Philistines, the Arabs living in Gur Baal, and the Meunites.'
EXEC add_BibleVerse @BibleId, 114026008, N'The Ammonites paid tribute to Uzziah and his fame reached the border of Egypt, for he grew in power.'
EXEC add_BibleVerse @BibleId, 114026009, N'Uzziah built and fortified towers in Jerusalem at the Corner Gate, Valley Gate, and at the Angle.'
EXEC add_BibleVerse @BibleId, 114026010, N'He built towers in the desert and dug many cisterns, for he owned many herds in the lowlands and on the plain. He had workers in the fields and vineyards in the hills and in Carmel, for he loved agriculture.'
EXEC add_BibleVerse @BibleId, 114026011, N'Uzziah had an army of skilled warriors trained for battle. They were organized by divisions according to the muster rolls made by Jeiel the scribe and Maaseiah the officer under the authority of Hananiah, a royal official.'
EXEC add_BibleVerse @BibleId, 114026012, N'The total number of family leaders who led warriors was 2,600.'
EXEC add_BibleVerse @BibleId, 114026013, N'They commanded an army of 307,500 skilled and able warriors who were ready to defend the king against his enemies.'
EXEC add_BibleVerse @BibleId, 114026014, N'Uzziah supplied shields, spears, helmets, breastplates, bows, and slingstones for the entire army.'
EXEC add_BibleVerse @BibleId, 114026015, N'In Jerusalem he made war machines carefully designed to shoot arrows and large stones from the towers and corners of the walls. He became very famous, for he received tremendous support and became powerful.'
EXEC add_BibleVerse @BibleId, 114026016, N'But once he became powerful, his pride destroyed him. He disobeyed the Lord his God. He entered the Lord’s temple to offer incense on the incense altar.'
EXEC add_BibleVerse @BibleId, 114026017, N'Azariah the priest and eighty other brave priests of the Lord followed him in.'
EXEC add_BibleVerse @BibleId, 114026018, N'They confronted King Uzziah and said to him, “It is not proper for you, Uzziah, to offer incense to the Lord. That is the responsibility of the priests, the descendants of Aaron, who are consecrated to offer incense. Leave the sanctuary, for you have disobeyed and the Lord God will not honor you!”'
EXEC add_BibleVerse @BibleId, 114026019, N'Uzziah, who had an incense censer in his hand, became angry. While he was ranting and raving at the priests, a skin disease appeared on his forehead right there in front of the priests in the Lord’s temple near the incense altar.'
EXEC add_BibleVerse @BibleId, 114026020, N'When Azariah the high priest and the other priests looked at him, there was a skin disease on his forehead. They hurried him out of there; even the king himself wanted to leave quickly because the Lord had afflicted him.'
EXEC add_BibleVerse @BibleId, 114026021, N'King Uzziah suffered from a skin disease until the day he died. He lived in separate quarters, afflicted by a skin disease and banned from the Lord’s temple. His son Jotham was in charge of the palace and ruled over the people of the land.'
EXEC add_BibleVerse @BibleId, 114026022, N'The rest of the events of Uzziah’s reign, from start to finish, were recorded by the prophet Isaiah son of Amoz.'
EXEC add_BibleVerse @BibleId, 114026023, N'Uzziah passed away and was buried near his ancestors in a cemetery belonging to the kings. (This was because he had a skin disease.) His son Jotham replaced him as king.'
EXEC add_BibleVerse @BibleId, 114027001, N'Jotham was twenty-five years old when he began to reign, and he reigned for sixteen years in Jerusalem. His mother was Jerusha the daughter of Zadok.'
EXEC add_BibleVerse @BibleId, 114027002, N'He did what the Lord approved, just as his father Uzziah had done. (He did not, however, have the audacity to enter the temple.) Yet the people were still sinning.'
EXEC add_BibleVerse @BibleId, 114027003, N'He built the Upper Gate to the Lord’s temple and did a lot of work on the wall in the area known as Ophel.'
EXEC add_BibleVerse @BibleId, 114027004, N'He built cities in the hill country of Judah and fortresses and towers in the forests.'
EXEC add_BibleVerse @BibleId, 114027005, N'He launched a military campaign against the king of the Ammonites and defeated them. That year the Ammonites paid him 100 talents of silver, 10,000 kors of wheat, and 10,000 kors of barley. The Ammonites also paid this same amount of annual tribute the next two years.'
EXEC add_BibleVerse @BibleId, 114027006, N'Jotham grew powerful because he was determined to please the Lord his God.'
EXEC add_BibleVerse @BibleId, 114027007, N'The rest of the events of Jotham’s reign, including all his military campaigns and his accomplishments, are recorded in the scroll of the kings of Israel and Judah.'
EXEC add_BibleVerse @BibleId, 114027008, N'He was twenty-five years old when he began to reign, and he reigned for sixteen years in Jerusalem.'
EXEC add_BibleVerse @BibleId, 114027009, N'Jotham passed away and was buried in the City of David. His son Ahaz replaced him as king.'
EXEC add_BibleVerse @BibleId, 114028001, N'Ahaz was twenty years old when he began to reign, and he reigned for sixteen years in Jerusalem. He did not do what pleased the Lord, in contrast to his ancestor David.'
EXEC add_BibleVerse @BibleId, 114028002, N'He followed in the footsteps of the kings of Israel; he also made images of the Baals.'
EXEC add_BibleVerse @BibleId, 114028003, N'He offered sacrifices in the Valley of Ben-Hinnom and passed his sons through the fire, a horrible sin practiced by the nations whom the Lord drove out before the Israelites.'
EXEC add_BibleVerse @BibleId, 114028004, N'He offered sacrifices and burned incense on the high places, on the hills, and under every green tree.'
EXEC add_BibleVerse @BibleId, 114028005, N'The Lord his God handed him over to the king of Syria. The Syrians defeated him and deported many captives to Damascus. He was also handed over to the king of Israel, who thoroughly defeated him.'
EXEC add_BibleVerse @BibleId, 114028006, N'In one day King Pekah son of Remaliah of Israel killed 120,000 warriors in Judah, because they had abandoned the Lord God of their ancestors.'
EXEC add_BibleVerse @BibleId, 114028007, N'Zikri, an Ephraimite warrior, killed the king’s son Maaseiah, Azrikam, the supervisor of the palace, and Elkanah, the king’s second-in-command.'
EXEC add_BibleVerse @BibleId, 114028008, N'The Israelites seized from their brothers 200,000 wives, sons, and daughters. They also carried off a huge amount of plunder and took it back to Samaria.'
EXEC add_BibleVerse @BibleId, 114028009, N'Oded, a prophet of the Lord, was there. He went to meet the army as they arrived in Samaria and said to them: “Look, because the Lord God of your ancestors was angry with Judah he handed them over to you. You have killed them so mercilessly that God has taken notice.'
EXEC add_BibleVerse @BibleId, 114028010, N'And now you are planning to enslave the people of Judah and Jerusalem. Yet are you not also guilty before the Lord your God?'
EXEC add_BibleVerse @BibleId, 114028011, N'Now listen to me! Send back those you have seized from your brothers, for the Lord is very angry at you!”'
EXEC add_BibleVerse @BibleId, 114028012, N'So some of the Ephraimite family leaders, Azariah son of Jehochanan, Berechiah son of Meshillemoth, Jechizkiah son of Shallum, and Amasa son of Hadlai confronted those returning from the battle.'
EXEC add_BibleVerse @BibleId, 114028013, N'They said to them, “Don’t bring those captives here! Are you planning on making us even more sinful and guilty before the Lord? Our guilt is already great and the Lord is very angry at Israel.”'
EXEC add_BibleVerse @BibleId, 114028014, N'So the soldiers released the captives and the plunder before the officials and the entire assembly.'
EXEC add_BibleVerse @BibleId, 114028015, N'Men were assigned to take the prisoners and find clothes among the plunder for those who were naked. So they clothed them, supplied them with sandals, gave them food and drink, and provided them with oil to rub on their skin. They put the ones who couldn’t walk on donkeys. They brought them back to their brothers at Jericho, the city of the date palm trees, and then returned to Samaria.'
EXEC add_BibleVerse @BibleId, 114028016, N'At that time King Ahaz asked the king of Assyria for help.'
EXEC add_BibleVerse @BibleId, 114028017, N'The Edomites had again invaded and defeated Judah and carried off captives.'
EXEC add_BibleVerse @BibleId, 114028018, N'The Philistines had raided the cities of Judah in the lowlands and the Negev. They captured and settled in Beth Shemesh, Aijalon, Gederoth, Soco and its surrounding villages, Timnah and its surrounding villages, and Gimzo and its surrounding villages.'
EXEC add_BibleVerse @BibleId, 114028019, N'The Lord humiliated Judah because of King Ahaz of Israel, for he encouraged Judah to sin and was very unfaithful to the Lord.'
EXEC add_BibleVerse @BibleId, 114028020, N'King Tiglath-pileser of Assyria came, but he gave him more trouble than support.'
EXEC add_BibleVerse @BibleId, 114028021, N'Ahaz gathered riches from the Lord’s temple, the royal palace, and the officials and gave them to the king of Assyria, but that did not help.'
EXEC add_BibleVerse @BibleId, 114028022, N'During his time of trouble King Ahaz was even more unfaithful to the Lord.'
EXEC add_BibleVerse @BibleId, 114028023, N'He offered sacrifices to the gods of Damascus whom he thought had defeated him. He reasoned, “Since the gods of the kings of Damascus helped them, I will sacrifice to them so they will help me.” But they caused him and all Israel to stumble.'
EXEC add_BibleVerse @BibleId, 114028024, N'Ahaz gathered the items in God’s temple and removed them. He shut the doors of the Lord’s temple and erected altars on every street corner in Jerusalem.'
EXEC add_BibleVerse @BibleId, 114028025, N'In every city throughout Judah he set up high places to offer sacrifices to other gods. He angered the Lord God of his ancestors.'
EXEC add_BibleVerse @BibleId, 114028026, N'The rest of the events of Ahaz’s reign, including his accomplishments from start to finish, are recorded in the Scroll of the Kings of Judah and Israel.'
EXEC add_BibleVerse @BibleId, 114028027, N'Ahaz passed away and was buried in the City of David; they did not bring him to the tombs of the kings of Israel. His son Hezekiah replaced him as king.'
EXEC add_BibleVerse @BibleId, 114029001, N'Hezekiah was twenty-five years old when he began to reign, and he reigned twenty-nine years in Jerusalem. His mother was Abijah, the daughter of Zechariah.'
EXEC add_BibleVerse @BibleId, 114029002, N'He did what the Lord approved, just as his ancestor David had done.'
EXEC add_BibleVerse @BibleId, 114029003, N'In the first month of the first year of his reign, he opened the doors of the Lord’s temple and repaired them.'
EXEC add_BibleVerse @BibleId, 114029004, N'He brought in the priests and Levites and assembled them in the square on the east side.'
EXEC add_BibleVerse @BibleId, 114029005, N'He said to them: “Listen to me, you Levites! Now consecrate yourselves, so you can consecrate the temple of the Lord God of your ancestors! Remove from the sanctuary what is ceremonially unclean!'
EXEC add_BibleVerse @BibleId, 114029006, N'For our fathers were unfaithful; they did what is evil in the sight of the Lord our God and abandoned him! They turned away from the Lord’s dwelling place and rejected him.'
EXEC add_BibleVerse @BibleId, 114029007, N'They closed the doors of the temple porch and put out the lamps; they did not offer incense or burnt sacrifices in the sanctuary of the God of Israel.'
EXEC add_BibleVerse @BibleId, 114029008, N'The Lord was angry at Judah and Jerusalem and made them an appalling object of horror at which people hiss out their scorn, as you can see with your own eyes.'
EXEC add_BibleVerse @BibleId, 114029009, N'Look, our fathers died violently and our sons, daughters, and wives were carried off because of this.'
EXEC add_BibleVerse @BibleId, 114029010, N'Now I intend to make a covenant with the Lord God of Israel, so that he may relent from his raging anger.'
EXEC add_BibleVerse @BibleId, 114029011, N'My sons, do not be negligent now, for the Lord has chosen you to serve in his presence and offer sacrifices.”'
EXEC add_BibleVerse @BibleId, 114029012, N'The following Levites prepared to carry out the king’s orders: From the Kohathites: Mahath son of Amasai and Joel son of Azariah; from the Merarites: Kish son of Abdi and Azariah son of Jehallelel; from the Gershonites: Joah son of Zimmah and Eden son of Joah;'
EXEC add_BibleVerse @BibleId, 114029013, N'from the descendants of Elizaphan: Shimri and Jeiel; from the descendants of Asaph: Zechariah and Mattaniah;'
EXEC add_BibleVerse @BibleId, 114029014, N'from the descendants of Heman: Jehiel and Shimei; from the descendants of Jeduthun: Shemaiah and Uzziel.'
EXEC add_BibleVerse @BibleId, 114029015, N'They assembled their brothers and consecrated themselves. Then they went in to purify the Lord’s temple, just as the king had ordered, in accordance with the word of the Lord.'
EXEC add_BibleVerse @BibleId, 114029016, N'The priests then entered the Lord’s temple to purify it; they brought out to the courtyard of the Lord’s temple every ceremonially unclean thing they discovered inside. The Levites took them out to the Kidron Valley.'
EXEC add_BibleVerse @BibleId, 114029017, N'On the first day of the first month they began consecrating; by the eighth day of the month they reached the porch of the Lord’s temple. For eight more days they consecrated the Lord’s temple. On the sixteenth day of the first month they were finished.'
EXEC add_BibleVerse @BibleId, 114029018, N'They went to King Hezekiah and said: “We have purified the entire temple of the Lord, including the altar of burnt sacrifice and all its equipment, and the table for the Bread of the Presence and all its equipment.'
EXEC add_BibleVerse @BibleId, 114029019, N'We have prepared and consecrated all the items that King Ahaz removed during his reign when he acted unfaithfully. They are in front of the altar of the Lord.”'
EXEC add_BibleVerse @BibleId, 114029020, N'Early the next morning King Hezekiah assembled the city officials and went up to the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 114029021, N'They brought seven bulls, seven rams, seven lambs, and seven goats as a sin offering for the kingdom, the sanctuary, and Judah. The king told the priests, the descendants of Aaron, to offer burnt sacrifices on the altar of the Lord.'
EXEC add_BibleVerse @BibleId, 114029022, N'They slaughtered the bulls, and the priests took the blood and splashed it on the altar. Then they slaughtered the rams and splashed the blood on the altar; next they slaughtered the lambs and splashed the blood on the altar.'
EXEC add_BibleVerse @BibleId, 114029023, N'Finally they brought the goats for the sin offering before the king and the assembly, and they placed their hands on them.'
EXEC add_BibleVerse @BibleId, 114029024, N'Then the priests slaughtered them. They offered their blood as a sin offering on the altar to make atonement for all Israel, because the king had decreed that the burnt sacrifice and sin offering were for all Israel.'
EXEC add_BibleVerse @BibleId, 114029025, N'King Hezekiah stationed the Levites in the Lord’s temple with cymbals and stringed instruments, just as David, Gad the king’s prophet, and Nathan the prophet had ordered. (The Lord had actually given these orders through his prophets.)'
EXEC add_BibleVerse @BibleId, 114029026, N'The Levites had David’s musical instruments and the priests had trumpets.'
EXEC add_BibleVerse @BibleId, 114029027, N'Hezekiah ordered the burnt sacrifice to be offered on the altar. As they began to offer the sacrifice, they also began to sing to the Lord, accompanied by the trumpets and the musical instruments of King David of Israel.'
EXEC add_BibleVerse @BibleId, 114029028, N'The entire assembly worshiped, as the singers sang and the trumpeters played. They continued until the burnt sacrifice was completed.'
EXEC add_BibleVerse @BibleId, 114029029, N'When the sacrifices were completed, the king and all who were with him bowed down and worshiped.'
EXEC add_BibleVerse @BibleId, 114029030, N'King Hezekiah and the officials told the Levites to praise the Lord, using the psalms of David and Asaph the prophet. So they joyfully offered praise and bowed down and worshiped.'
EXEC add_BibleVerse @BibleId, 114029031, N'Hezekiah said, “Now you have consecrated yourselves to the Lord. Come and bring sacrifices and thank offerings to the Lord’s temple.” So the assembly brought sacrifices and thank offerings, and whoever desired to do so brought burnt sacrifices.'
EXEC add_BibleVerse @BibleId, 114029032, N'The assembly brought a total of 70 bulls, 100 rams, and 200 lambs as burnt sacrifices to the Lord,'
EXEC add_BibleVerse @BibleId, 114029033, N'and 600 bulls and 3,000 sheep were consecrated.'
EXEC add_BibleVerse @BibleId, 114029034, N'But there were not enough priests to skin all the animals, so their brothers, the Levites, helped them until the work was finished and the priests could consecrate themselves. (The Levites had been more conscientious about consecrating themselves than the priests.)'
EXEC add_BibleVerse @BibleId, 114029035, N'There was a large number of burnt sacrifices, as well as fat from the peace offerings and drink offerings that accompanied the burnt sacrifices. So the service of the Lord’s temple was reinstituted.'
EXEC add_BibleVerse @BibleId, 114029036, N'Hezekiah and all the people were happy about what God had done for them, for it had been done quickly.'
EXEC add_BibleVerse @BibleId, 114030001, N'Hezekiah sent messages throughout Israel and Judah; he even wrote letters to Ephraim and Manasseh, summoning them to come to the Lord’s temple in Jerusalem and observe a Passover celebration for the Lord God of Israel.'
EXEC add_BibleVerse @BibleId, 114030002, N'The king, his officials, and the entire assembly in Jerusalem decided to observe the Passover in the second month.'
EXEC add_BibleVerse @BibleId, 114030003, N'They were unable to observe it at the regular time because not enough priests had consecrated themselves and the people had not assembled in Jerusalem.'
EXEC add_BibleVerse @BibleId, 114030004, N'The proposal seemed appropriate to the king and the entire assembly.'
EXEC add_BibleVerse @BibleId, 114030005, N'So they sent an edict throughout Israel from Beer Sheba to Dan, summoning the people to come and observe a Passover for the Lord God of Israel in Jerusalem, for they had not observed it on a nationwide scale as prescribed in the law.'
EXEC add_BibleVerse @BibleId, 114030006, N'Messengers delivered the letters from the king and his officials throughout Israel and Judah. This royal edict read: “O Israelites, return to the Lord God of Abraham, Isaac, and Israel, so he may return to you who have been spared from the kings of Assyria.'
EXEC add_BibleVerse @BibleId, 114030007, N'Don’t be like your fathers and brothers who were unfaithful to the Lord God of their ancestors, provoking him to destroy them, as you can see.'
EXEC add_BibleVerse @BibleId, 114030008, N'Now, don’t be stubborn like your fathers! Submit to the Lord and come to his sanctuary which he has permanently consecrated. Serve the Lord your God so that he might relent from his raging anger.'
EXEC add_BibleVerse @BibleId, 114030009, N'For if you return to the Lord, your brothers and sons will be shown mercy by their captors and return to this land. The Lord your God is merciful and compassionate; he will not reject you if you return to him.”'
EXEC add_BibleVerse @BibleId, 114030010, N'The messengers journeyed from city to city through the land of Ephraim and Manasseh as far as Zebulun, but people mocked and ridiculed them.'
EXEC add_BibleVerse @BibleId, 114030011, N'But some men from Asher, Manasseh, and Zebulun humbled themselves and came to Jerusalem.'
EXEC add_BibleVerse @BibleId, 114030012, N'In Judah God moved the people to unite and carry out the edict the king and the officers had issued at the Lord’s command.'
EXEC add_BibleVerse @BibleId, 114030013, N'A huge crowd assembled in Jerusalem to observe the Feast of Unleavened Bread in the second month.'
EXEC add_BibleVerse @BibleId, 114030014, N'They removed the altars in Jerusalem; they also removed all the incense altars and threw them into the Kidron Valley.'
EXEC add_BibleVerse @BibleId, 114030015, N'They slaughtered the Passover lamb on the fourteenth day of the second month. The priests and Levites were ashamed, so they consecrated themselves and brought burnt sacrifices to the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 114030016, N'They stood at their posts according to the regulations outlined in the law of Moses, the man of God. The priests were splashing the blood as the Levites handed it to them.'
EXEC add_BibleVerse @BibleId, 114030017, N'Because many in the assembly had not consecrated themselves, the Levites slaughtered the Passover lambs of all who were ceremonially unclean and could not consecrate their sacrifice to the Lord.'
EXEC add_BibleVerse @BibleId, 114030018, N'The majority of the many people from Ephraim, Manasseh, Issachar, and Zebulun were ceremonially unclean, yet they ate the Passover in violation of what is prescribed in the law. For Hezekiah prayed for them, saying: “May the Lord, who is good, forgive'
EXEC add_BibleVerse @BibleId, 114030019, N'everyone who has determined to follow God, the Lord God of his ancestors, even if he is not ceremonially clean according to the standards of the temple.”'
EXEC add_BibleVerse @BibleId, 114030020, N'The Lord responded favorably to Hezekiah and forgave the people.'
EXEC add_BibleVerse @BibleId, 114030021, N'The Israelites who were in Jerusalem observed the Feast of Unleavened Bread for seven days with great joy. The Levites and priests were praising the Lord every day with all their might.'
EXEC add_BibleVerse @BibleId, 114030022, N'Hezekiah expressed his appreciation to all the Levites, who demonstrated great skill in serving the Lord. They feasted for the seven days of the festival, and were making peace offerings and giving thanks to the Lord God of their ancestors.'
EXEC add_BibleVerse @BibleId, 114030023, N'The entire assembly then decided to celebrate for seven more days; so they joyfully celebrated for seven more days.'
EXEC add_BibleVerse @BibleId, 114030024, N'King Hezekiah of Judah supplied 1,000 bulls and 7,000 sheep for the assembly, while the officials supplied them with 1,000 bulls and 10,000 sheep. Many priests consecrated themselves.'
EXEC add_BibleVerse @BibleId, 114030025, N'The celebration included the entire assembly of Judah, the priests, the Levites, the entire assembly of those who came from Israel, the resident foreigners who came from the land of Israel, and the residents of Judah.'
EXEC add_BibleVerse @BibleId, 114030026, N'There was a great celebration in Jerusalem, unlike anything that had occurred in Jerusalem since the time of King Solomon son of David of Israel.'
EXEC add_BibleVerse @BibleId, 114030027, N'The priests and Levites got up and pronounced blessings on the people. The Lord responded favorably to them as their prayers reached his holy dwelling place in heaven.'
EXEC add_BibleVerse @BibleId, 114031001, N'When all this was over, the Israelites who were in the cities of Judah went out and smashed the sacred pillars, cut down the Asherah poles, and demolished all the high places and altars throughout Judah, Benjamin, Ephraim, and Manasseh. Then all the Israelites returned to their own homes in their cities.'
EXEC add_BibleVerse @BibleId, 114031002, N'Hezekiah appointed the divisions of the priests and Levites to do their assigned tasks – to offer burnt sacrifices and present offerings and to serve, give thanks, and offer praise in the gates of the Lord’s sanctuary.'
EXEC add_BibleVerse @BibleId, 114031003, N'The king contributed some of what he owned for burnt sacrifices, including the morning and evening burnt sacrifices and the burnt sacrifices made on Sabbaths, new moon festivals, and at other appointed times prescribed in the law of the Lord.'
EXEC add_BibleVerse @BibleId, 114031004, N'He ordered the people living in Jerusalem to contribute the portion prescribed for the priests and Levites so they might be obedient to the law of the Lord.'
EXEC add_BibleVerse @BibleId, 114031005, N'When the edict was issued, the Israelites freely contributed the initial portion of their grain, wine, olive oil, honey, and all the produce of their fields. They brought a tenth of everything, which added up to a huge amount.'
EXEC add_BibleVerse @BibleId, 114031006, N'The Israelites and people of Judah who lived in the cities of Judah also contributed a tenth of their cattle and sheep, as well as a tenth of the holy items consecrated to the Lord their God. They brought them and placed them in many heaps.'
EXEC add_BibleVerse @BibleId, 114031007, N'In the third month they began piling their contributions in heaps and finished in the seventh month.'
EXEC add_BibleVerse @BibleId, 114031008, N'When Hezekiah and the officials came and saw the heaps, they praised the Lord and pronounced blessings on his people Israel.'
EXEC add_BibleVerse @BibleId, 114031009, N'When Hezekiah asked the priests and Levites about the heaps,'
EXEC add_BibleVerse @BibleId, 114031010, N'Azariah, the head priest from the family of Zadok, said to him, “Since the contributions began arriving in the Lord’s temple, we have had plenty to eat and have a large quantity left over. For the Lord has blessed his people, and this large amount remains.”'
EXEC add_BibleVerse @BibleId, 114031011, N'Hezekiah ordered that storerooms be prepared in the Lord’s temple. When this was done,'
EXEC add_BibleVerse @BibleId, 114031012, N'they brought in the contributions, tithes, and consecrated items that had been offered. Konaniah, a Levite, was in charge of all this, assisted by his brother Shimei.'
EXEC add_BibleVerse @BibleId, 114031013, N'Jehiel, Azaziah, Nahath, Asahel, Jerimoth, Jozabad, Eliel, Ismakiah, Mahath, and Benaiah worked under the supervision of Konaniah and his brother Shimei, as directed by King Hezekiah and Azariah, the supervisor of God’s temple.'
EXEC add_BibleVerse @BibleId, 114031014, N'Kore son of Imnah, a Levite and the guard on the east side, was in charge of the voluntary offerings made to God and disbursed the contributions made to the Lord and the consecrated items.'
EXEC add_BibleVerse @BibleId, 114031015, N'In the cities of the priests, Eden, Miniamin, Jeshua, Shemaiah, Amariah, and Shecaniah faithfully assisted him in making disbursements to their fellow priests according to their divisions, regardless of age.'
EXEC add_BibleVerse @BibleId, 114031016, N'They made disbursements to all the males three years old and up who were listed in the genealogical records – to all who would enter the Lord’s temple to serve on a daily basis and fulfill their duties as assigned to their divisions.'
EXEC add_BibleVerse @BibleId, 114031017, N'They made disbursements to the priests listed in the genealogical records by their families, and to the Levites twenty years old and up, according to their duties as assigned to their divisions,'
EXEC add_BibleVerse @BibleId, 114031018, N'and to all the infants, wives, sons, and daughters of the entire assembly listed in the genealogical records, for they faithfully consecrated themselves.'
EXEC add_BibleVerse @BibleId, 114031019, N'As for the descendants of Aaron, the priests who lived in the outskirts of all their cities, men were assigned to disburse portions to every male among the priests and to every Levite listed in the genealogical records.'
EXEC add_BibleVerse @BibleId, 114031020, N'This is what Hezekiah did throughout Judah. He did what the Lord his God considered good and right and faithful.'
EXEC add_BibleVerse @BibleId, 114031021, N'He wholeheartedly and successfully reinstituted service in God’s temple and obedience to the law, in order to follow his God.'
EXEC add_BibleVerse @BibleId, 114032001, N'After these faithful deeds were accomplished, King Sennacherib of Assyria invaded Judah. He besieged the fortified cities, intending to seize them.'
EXEC add_BibleVerse @BibleId, 114032002, N'When Hezekiah saw that Sennacherib had invaded and intended to attack Jerusalem,'
EXEC add_BibleVerse @BibleId, 114032003, N'he consulted with his advisers and military officers about stopping up the springs outside the city, and they supported him.'
EXEC add_BibleVerse @BibleId, 114032004, N'A large number of people gathered together and stopped up all the springs and the stream that flowed through the district. They reasoned, “Why should the kings of Assyria come and find plenty of water?”'
EXEC add_BibleVerse @BibleId, 114032005, N'Hezekiah energetically rebuilt every broken wall. He erected towers and an outer wall, and fortified the terrace of the City of David. He made many weapons and shields.'
EXEC add_BibleVerse @BibleId, 114032006, N'He appointed military officers over the army and assembled them in the square at the city gate. He encouraged them, saying,'
EXEC add_BibleVerse @BibleId, 114032007, N'“Be strong and brave! Don’t be afraid and don’t panic because of the king of Assyria and this huge army that is with him! We have with us one who is stronger than those who are with him.'
EXEC add_BibleVerse @BibleId, 114032008, N'He has with him mere human strength, but the Lord our God is with us to help us and fight our battles!” The army was encouraged by the words of King Hezekiah of Judah.'
EXEC add_BibleVerse @BibleId, 114032009, N'Afterward King Sennacherib of Assyria, while attacking Lachish with all his military might, sent his messengers to Jerusalem. The message was for King Hezekiah of Judah and all the people of Judah who were in Jerusalem. It read:'
EXEC add_BibleVerse @BibleId, 114032010, N'“This is what King Sennacherib of Assyria says: ‘Why are you so confident that you remain in Jerusalem while it is under siege?'
EXEC add_BibleVerse @BibleId, 114032011, N'Hezekiah says, “The Lord our God will rescue us from the power of the king of Assyria.” But he is misleading you and you will die of hunger and thirst!'
EXEC add_BibleVerse @BibleId, 114032012, N'Hezekiah is the one who eliminated the Lord’s high places and altars and then told Judah and Jerusalem, “At one altar you must worship and offer sacrifices.”'
EXEC add_BibleVerse @BibleId, 114032013, N'Are you not aware of what I and my predecessors have done to all the nations of the surrounding lands? Have the gods of the surrounding lands actually been able to rescue their lands from my power?'
EXEC add_BibleVerse @BibleId, 114032014, N'Who among all the gods of these nations whom my predecessors annihilated was able to rescue his people from my power?'
EXEC add_BibleVerse @BibleId, 114032015, N'Now don’t let Hezekiah deceive you or mislead you like this. Don’t believe him, for no god of any nation or kingdom has been able to rescue his people from my power or the power of my predecessors. So how can your gods rescue you from my power?’”'
EXEC add_BibleVerse @BibleId, 114032016, N'Sennacherib’s servants further insulted the Lord God and his servant Hezekiah.'
EXEC add_BibleVerse @BibleId, 114032017, N'He wrote letters mocking the Lord God of Israel and insulting him with these words: “The gods of the surrounding nations could not rescue their people from my power. Neither can Hezekiah’s god rescue his people from my power.”'
EXEC add_BibleVerse @BibleId, 114032018, N'They called out loudly in the Judahite dialect to the people of Jerusalem who were on the wall, trying to scare and terrify them so they could seize the city.'
EXEC add_BibleVerse @BibleId, 114032019, N'They talked about the God of Jerusalem as if he were one of the man-made gods of the nations of the earth.'
EXEC add_BibleVerse @BibleId, 114032020, N'King Hezekiah and the prophet Isaiah son of Amoz prayed about this and cried out to heaven.'
EXEC add_BibleVerse @BibleId, 114032021, N'The Lord sent a messenger and he wiped out all the soldiers, princes, and officers in the army of the king of Assyria. So Sennacherib returned home humiliated. When he entered the temple of his god, some of his own sons struck him down with the sword.'
EXEC add_BibleVerse @BibleId, 114032022, N'The Lord delivered Hezekiah and the residents of Jerusalem from the power of King Sennacherib of Assyria and from all the other nations. He made them secure on every side.'
EXEC add_BibleVerse @BibleId, 114032023, N'Many were bringing presents to the Lord in Jerusalem and precious gifts to King Hezekiah of Judah. From that time on he was respected by all the nations.'
EXEC add_BibleVerse @BibleId, 114032024, N'In those days Hezekiah was stricken with a terminal illness. He prayed to the Lord, who answered him and gave him a sign confirming that he would be healed.'
EXEC add_BibleVerse @BibleId, 114032025, N'But Hezekiah was ungrateful; he had a proud attitude, provoking God to be angry at him, as well as Judah and Jerusalem.'
EXEC add_BibleVerse @BibleId, 114032026, N'But then Hezekiah and the residents of Jerusalem humbled themselves and abandoned their pride, and the Lord was not angry with them for the rest of Hezekiah’s reign.'
EXEC add_BibleVerse @BibleId, 114032027, N'Hezekiah was very wealthy and greatly respected. He made storehouses for his silver, gold, precious stones, spices, and all his other valuable possessions.'
EXEC add_BibleVerse @BibleId, 114032028, N'He made storerooms for the harvest of grain, wine, and olive oil, and stalls for all his various kinds of livestock and his flocks.'
EXEC add_BibleVerse @BibleId, 114032029, N'He built royal cities and owned a large number of sheep and cattle, for God gave him a huge amount of possessions.'
EXEC add_BibleVerse @BibleId, 114032030, N'Hezekiah dammed up the source of the waters of the Upper Gihon and directed them down to the west side of the City of David. Hezekiah succeeded in all that he did.'
EXEC add_BibleVerse @BibleId, 114032031, N'So when the envoys arrived from the Babylonian officials to visit him and inquire about the sign that occurred in the land, God left him alone to test him, in order to know his true motives.'
EXEC add_BibleVerse @BibleId, 114032032, N'The rest of the events of Hezekiah’s reign, including his faithful deeds, are recorded in the vision of the prophet Isaiah son of Amoz, included in the Scroll of the Kings of Judah and Israel.'
EXEC add_BibleVerse @BibleId, 114032033, N'Hezekiah passed away and was buried on the ascent of the tombs of the descendants of David. All the people of Judah and the residents of Jerusalem buried him with great honor. His son Manasseh replaced him as king.'
EXEC add_BibleVerse @BibleId, 114033001, N'Manasseh was twelve years old when he became king, and he reigned for fifty-five years in Jerusalem.'
EXEC add_BibleVerse @BibleId, 114033002, N'He did evil in the sight of the Lord and committed the same horrible sins practiced by the nations whom the Lord drove out ahead of the Israelites.'
EXEC add_BibleVerse @BibleId, 114033003, N'He rebuilt the high places that his father Hezekiah had destroyed; he set up altars for the Baals and made Asherah poles. He bowed down to all the stars in the sky and worshiped them.'
EXEC add_BibleVerse @BibleId, 114033004, N'He built altars in the Lord’s temple, about which the Lord had said, “Jerusalem will be my permanent home.”'
EXEC add_BibleVerse @BibleId, 114033005, N'In the two courtyards of the Lord’s temple he built altars for all the stars in the sky.'
EXEC add_BibleVerse @BibleId, 114033006, N'He passed his sons through the fire in the Valley of Ben-Hinnom and practiced divination, omen reading, and sorcery. He set up a ritual pit to conjure up underworld spirits and appointed magicians to supervise it. He did a great amount of evil in the sight of the Lord and angered him.'
EXEC add_BibleVerse @BibleId, 114033007, N'He put an idolatrous image he had made in God’s temple, about which God had said to David and to his son Solomon, “This temple in Jerusalem, which I have chosen out of all the tribes of Israel, will be my permanent home.'
EXEC add_BibleVerse @BibleId, 114033008, N'I will not make Israel again leave the land I gave to their ancestors, provided that they carefully obey all I commanded them, the whole law, the rules and regulations given to Moses.”'
EXEC add_BibleVerse @BibleId, 114033009, N'But Manasseh misled the people of Judah and the residents of Jerusalem so that they sinned more than the nations whom the Lord had destroyed ahead of the Israelites.'
EXEC add_BibleVerse @BibleId, 114033010, N'The Lord confronted Manasseh and his people, but they paid no attention.'
EXEC add_BibleVerse @BibleId, 114033011, N'So the Lord brought against them the commanders of the army of the king of Assyria. They seized Manasseh, put hooks in his nose, bound him with bronze chains, and carried him away to Babylon.'
EXEC add_BibleVerse @BibleId, 114033012, N'In his pain Manasseh asked the Lord his God for mercy and truly humbled himself before the God of his ancestors.'
EXEC add_BibleVerse @BibleId, 114033013, N'When he prayed to the Lord, the Lord responded to him and answered favorably his cry for mercy. The Lord brought him back to Jerusalem to his kingdom. Then Manasseh realized that the Lord is the true God.'
EXEC add_BibleVerse @BibleId, 114033014, N'After this Manasseh built up the outer wall of the City of David on the west side of the Gihon in the valley to the entrance of the Fish Gate and all around the terrace; he made it much higher. He placed army officers in all the fortified cities in Judah.'
EXEC add_BibleVerse @BibleId, 114033015, N'He removed the foreign gods and images from the Lord’s temple and all the altars he had built on the hill of the Lord’s temple and in Jerusalem; he threw them outside the city.'
EXEC add_BibleVerse @BibleId, 114033016, N'He erected the altar of the Lord and offered on it peace offerings and thank offerings. He told the people of Judah to serve the Lord God of Israel.'
EXEC add_BibleVerse @BibleId, 114033017, N'The people continued to offer sacrifices at the high places, but only to the Lord their God.'
EXEC add_BibleVerse @BibleId, 114033018, N'The rest of the events of Manasseh’s reign, including his prayer to his God and the words the prophets spoke to him in the name of the Lord God of Israel, are recorded in the Annals of the Kings of Israel.'
EXEC add_BibleVerse @BibleId, 114033019, N'The Annals of the Prophets include his prayer, give an account of how the Lord responded to it, record all his sins and unfaithful acts, and identify the sites where he built high places and erected Asherah poles and idols before he humbled himself.'
EXEC add_BibleVerse @BibleId, 114033020, N'Manasseh passed away and was buried in his palace. His son Amon replaced him as king.'
EXEC add_BibleVerse @BibleId, 114033021, N'Amon was twenty-two years old when he became king, and he reigned for two years in Jerusalem.'
EXEC add_BibleVerse @BibleId, 114033022, N'He did evil in the sight of the Lord, just like his father Manasseh had done. He offered sacrifices to all the idols his father Manasseh had made, and worshiped them.'
EXEC add_BibleVerse @BibleId, 114033023, N'He did not humble himself before the Lord as his father Manasseh had done. Amon was guilty of great sin.'
EXEC add_BibleVerse @BibleId, 114033024, N'His servants conspired against him and killed him in his palace.'
EXEC add_BibleVerse @BibleId, 114033025, N'The people of the land executed all who had conspired against King Amon, and they made his son Josiah king in his place.'
EXEC add_BibleVerse @BibleId, 114034001, N'Josiah was eight years old when he became king, and he reigned for thirty-one years in Jerusalem.'
EXEC add_BibleVerse @BibleId, 114034002, N'He did what the Lord approved and followed in his ancestor David’s footsteps; he did not deviate to the right or the left.'
EXEC add_BibleVerse @BibleId, 114034003, N'In the eighth year of his reign, while he was still young, he began to seek the God of his ancestor David. In his twelfth year he began ridding Judah and Jerusalem of the high places, Asherah poles, idols, and images.'
EXEC add_BibleVerse @BibleId, 114034004, N'He ordered the altars of the Baals to be torn down, and broke the incense altars that were above them. He smashed the Asherah poles, idols and images, crushed them up and sprinkled the dust over the tombs of those who had sacrificed to them.'
EXEC add_BibleVerse @BibleId, 114034005, N'He burned the bones of the pagan priests on their altars; he purified Judah and Jerusalem.'
EXEC add_BibleVerse @BibleId, 114034006, N'In the cities of Manasseh, Ephraim, and Simeon, as far as Naphtali, and in the ruins around them,'
EXEC add_BibleVerse @BibleId, 114034007, N'he tore down the altars and Asherah poles, demolished the idols, and smashed all the incense altars throughout the land of Israel. Then he returned to Jerusalem.'
EXEC add_BibleVerse @BibleId, 114034008, N'In the eighteenth year of his reign, he continued his policy of purifying the land and the temple. He sent Shaphan son of Azaliah, Maaseiah the city official, and Joah son of Joahaz the secretary to repair the temple of the Lord his God.'
EXEC add_BibleVerse @BibleId, 114034009, N'They went to Hilkiah the high priest and gave him the silver that had been brought to God’s temple. The Levites who guarded the door had collected it from the people of Manasseh and Ephraim and from all who were left in Israel, as well as from all the people of Judah and Benjamin and the residents of Jerusalem.'
EXEC add_BibleVerse @BibleId, 114034010, N'They handed it over to the construction foremen assigned to the Lord’s temple. They in turn paid the temple workers to restore and repair it.'
EXEC add_BibleVerse @BibleId, 114034011, N'They gave money to the craftsmen and builders to buy chiseled stone and wood for the braces and rafters of the buildings that the kings of Judah had allowed to fall into disrepair.'
EXEC add_BibleVerse @BibleId, 114034012, N'The men worked faithfully. Their supervisors were Jahath and Obadiah (Levites descended from Merari), as well as Zechariah and Meshullam (descendants of Kohath). The Levites, all of whom were skilled musicians,'
EXEC add_BibleVerse @BibleId, 114034013, N'supervised the laborers and all the foremen on their various jobs. Some of the Levites were scribes, officials, and guards.'
EXEC add_BibleVerse @BibleId, 114034014, N'When they took out the silver that had been brought to the Lord’s temple, Hilkiah the priest found the law scroll the Lord had given to Moses.'
EXEC add_BibleVerse @BibleId, 114034015, N'Hilkiah informed Shaphan the scribe, “I found the law scroll in the Lord’s temple.” Hilkiah gave the scroll to Shaphan.'
EXEC add_BibleVerse @BibleId, 114034016, N'Shaphan brought the scroll to the king and reported, “Your servants are doing everything assigned to them.'
EXEC add_BibleVerse @BibleId, 114034017, N'They melted down the silver in the Lord’s temple and handed it over to the supervisors of the construction foremen.”'
EXEC add_BibleVerse @BibleId, 114034018, N'Then Shaphan the scribe told the king, “Hilkiah the priest has given me a scroll.” Shaphan read it out loud before the king.'
EXEC add_BibleVerse @BibleId, 114034019, N'When the king heard the words of the law scroll, he tore his clothes.'
EXEC add_BibleVerse @BibleId, 114034020, N'The king ordered Hilkiah, Ahikam son of Shaphan, Abdon son of Micah, Shaphan the scribe, and Asaiah the king’s servant,'
EXEC add_BibleVerse @BibleId, 114034021, N'“Go, seek an oracle from the Lord for me and those who remain in Israel and Judah. Find out about the words of this scroll that has been discovered. For the Lord’s fury has been ignited against us, because our ancestors have not obeyed the word of the Lord by doing all that this scroll instructs!”'
EXEC add_BibleVerse @BibleId, 114034022, N'So Hilkiah and the others sent by the king went to Huldah the prophetess, the wife of Shallum son of Tokhath, the son of Hasrah, the supervisor of the wardrobe. (She lived in Jerusalem in the Mishneh district.) They stated their business,'
EXEC add_BibleVerse @BibleId, 114034023, N'and she said to them: “This is what the Lord God of Israel says: ‘Say this to the man who sent you to me:'
EXEC add_BibleVerse @BibleId, 114034024, N'“This is what the Lord says: ‘I am about to bring disaster on this place and its residents, the details of which are recorded in the scroll which they read before the king of Judah.'
EXEC add_BibleVerse @BibleId, 114034025, N'This will happen because they have abandoned me and offered sacrifices to other gods, angering me with all the idols they have made. My anger will ignite against this place and will not be extinguished!’”'
EXEC add_BibleVerse @BibleId, 114034026, N'Say this to the king of Judah, who sent you to seek an oracle from the Lord: “This is what the Lord God of Israel says concerning the words you have heard:'
EXEC add_BibleVerse @BibleId, 114034027, N'‘You displayed a sensitive spirit and humbled yourself before God when you heard his words concerning this place and its residents. You humbled yourself before me, tore your clothes and wept before me, and I have heard you,’ says the Lord.'
EXEC add_BibleVerse @BibleId, 114034028, N'‘Therefore I will allow you to die and be buried in peace. You will not have to witness all the disaster I will bring on this place and its residents.’”’” Then they reported back to the king.'
EXEC add_BibleVerse @BibleId, 114034029, N'The king summoned all the leaders of Judah and Jerusalem.'
EXEC add_BibleVerse @BibleId, 114034030, N'The king went up to the Lord’s temple, accompanied by all the people of Judah, the residents of Jerusalem, the priests, and the Levites. All the people were there, from the oldest to the youngest. He read aloud all the words of the scroll of the covenant that had been discovered in the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 114034031, N'The king stood by his pillar and renewed the covenant before the Lord, agreeing to follow the Lord and to obey his commandments, laws, and rules with all his heart and being, by carrying out the terms of this covenant recorded on this scroll.'
EXEC add_BibleVerse @BibleId, 114034032, N'He made all who were in Jerusalem and Benjamin agree to it. The residents of Jerusalem acted in accordance with the covenant of God, the God of their ancestors.'
EXEC add_BibleVerse @BibleId, 114034033, N'Josiah removed all the detestable idols from all the areas belonging to the Israelites and encouraged all who were in Israel to worship the Lord their God. Throughout the rest of his reign they did not turn aside from following the Lord God of their ancestors.'
EXEC add_BibleVerse @BibleId, 114035001, N'Josiah observed a Passover festival for the Lord in Jerusalem. They slaughtered the Passover lambs on the fourteenth day of the first month.'
EXEC add_BibleVerse @BibleId, 114035002, N'He appointed the priests to fulfill their duties and encouraged them to carry out their service in the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 114035003, N'He told the Levites, who instructed all Israel about things consecrated to the Lord, “Place the holy ark in the temple which King Solomon son of David of Israel built. Don’t carry it on your shoulders. Now serve the Lord your God and his people Israel!'
EXEC add_BibleVerse @BibleId, 114035004, N'Prepare yourselves by your families according to your divisions, as instructed by King David of Israel and his son Solomon.'
EXEC add_BibleVerse @BibleId, 114035005, N'Stand in the sanctuary and, together with the Levites, represent the family divisions of your countrymen.'
EXEC add_BibleVerse @BibleId, 114035006, N'Slaughter the Passover lambs, consecrate yourselves, and make preparations for your countrymen to do what the Lord commanded through Moses.”'
EXEC add_BibleVerse @BibleId, 114035007, N'From his own royal flocks and herds, Josiah supplied the people with 30,000 lambs and goats for the Passover sacrifice, as well as 3,000 cattle.'
EXEC add_BibleVerse @BibleId, 114035008, N'His officials also willingly contributed to the people, priests, and Levites. Hilkiah, Zechariah, and Jehiel, the leaders of God’s temple, supplied 2,600 Passover sacrifices and 300 cattle.'
EXEC add_BibleVerse @BibleId, 114035009, N'Konaniah and his brothers Shemaiah and Nethanel, along with Hashabiah, Jeiel, and Jozabad, the officials of the Levites, supplied the Levites with 5,000 Passover sacrifices and 500 cattle.'
EXEC add_BibleVerse @BibleId, 114035010, N'Preparations were made, and the priests stood at their posts and the Levites in their divisions as prescribed by the king.'
EXEC add_BibleVerse @BibleId, 114035011, N'They slaughtered the Passover lambs and the priests splashed the blood, while the Levites skinned the animals.'
EXEC add_BibleVerse @BibleId, 114035012, N'They reserved the burnt offerings and the cattle for the family divisions of the people to present to the Lord, as prescribed in the scroll of Moses.'
EXEC add_BibleVerse @BibleId, 114035013, N'They cooked the Passover sacrifices over the open fire as prescribed and cooked the consecrated offerings in pots, kettles, and pans. They quickly served them to all the people.'
EXEC add_BibleVerse @BibleId, 114035014, N'Afterward they made preparations for themselves and for the priests, because the priests, the descendants of Aaron, were offering burnt sacrifices and fat portions until evening. The Levites made preparations for themselves and for the priests, the descendants of Aaron.'
EXEC add_BibleVerse @BibleId, 114035015, N'The musicians, the descendants of Asaph, manned their posts, as prescribed by David, Asaph, Heman, and Jeduthun the king’s prophet. The guards at the various gates did not need to leave their posts, for their fellow Levites made preparations for them.'
EXEC add_BibleVerse @BibleId, 114035016, N'So all the preparations for the Lord’s service were made that day, as the Passover was observed and the burnt sacrifices were offered on the altar of the Lord, as prescribed by King Josiah.'
EXEC add_BibleVerse @BibleId, 114035017, N'So the Israelites who were present observed the Passover at that time, as well as the Feast of Unleavened Bread for seven days.'
EXEC add_BibleVerse @BibleId, 114035018, N'A Passover like this had not been observed in Israel since the days of Samuel the prophet. None of the kings of Israel had observed a Passover like the one celebrated by Josiah, the priests, the Levites, all the people of Judah and Israel who were there, and the residents of Jerusalem.'
EXEC add_BibleVerse @BibleId, 114035019, N'This Passover was observed in the eighteenth year of Josiah’s reign.'
EXEC add_BibleVerse @BibleId, 114035020, N'After Josiah had done all this for the temple, King Necho of Egypt marched up to do battle at Carchemish on the Euphrates River. Josiah marched out to oppose him.'
EXEC add_BibleVerse @BibleId, 114035021, N'Necho sent messengers to him, saying, “Why are you opposing me, O king of Judah? I am not attacking you today, but the kingdom with which I am at war. God told me to hurry. Stop opposing God, who is with me, or else he will destroy you.”'
EXEC add_BibleVerse @BibleId, 114035022, N'But Josiah did not turn back from him; he disguised himself for battle. He did not take seriously the words of Necho which he had received from God; he went to fight him in the Plain of Megiddo.'
EXEC add_BibleVerse @BibleId, 114035023, N'Archers shot King Josiah; the king ordered his servants, “Take me out of this chariot, for I am seriously wounded.”'
EXEC add_BibleVerse @BibleId, 114035024, N'So his servants took him out of the chariot, put him in another chariot that he owned, and brought him to Jerusalem, where he died. He was buried in the tombs of his ancestors; all the people of Judah and Jerusalem mourned Josiah.'
EXEC add_BibleVerse @BibleId, 114035025, N'Jeremiah composed laments for Josiah which all the male and female singers use to mourn Josiah to this very day. It has become customary in Israel to sing these; they are recorded in the Book of Laments.'
EXEC add_BibleVerse @BibleId, 114035026, N'The rest of the events of Josiah’s reign, including the faithful acts he did in obedience to what is written in the law of the Lord'
EXEC add_BibleVerse @BibleId, 114035027, N'and his accomplishments, from start to finish, are recorded in the Scroll of the Kings of Israel and Judah.'
EXEC add_BibleVerse @BibleId, 114036001, N'The people of the land took Jehoahaz son of Josiah and made him king in his father’s place in Jerusalem.'
EXEC add_BibleVerse @BibleId, 114036002, N'Jehoahaz was twenty-three years old when he became king, and he reigned three months in Jerusalem.'
EXEC add_BibleVerse @BibleId, 114036003, N'The king of Egypt prevented him from ruling in Jerusalem and imposed on the land a special tax of one hundred talents of silver and a talent of gold.'
EXEC add_BibleVerse @BibleId, 114036004, N'The king of Egypt made Jehoahaz’s brother Eliakim king over Judah and Jerusalem, and changed his name to Jehoiakim. Necho seized his brother Jehoahaz and took him to Egypt.'
EXEC add_BibleVerse @BibleId, 114036005, N'Jehoiakim was twenty-five years old when he became king, and he reigned for eleven years in Jerusalem. He did evil in the sight of the Lord his God.'
EXEC add_BibleVerse @BibleId, 114036006, N'King Nebuchadnezzar of Babylon attacked him, bound him with bronze chains, and carried him away to Babylon.'
EXEC add_BibleVerse @BibleId, 114036007, N'Nebuchadnezzar took some of the items in the Lord’s temple to Babylon and put them in his palace there.'
EXEC add_BibleVerse @BibleId, 114036008, N'The rest of the events of Jehoiakim’s reign, including the horrible sins he committed and his shortcomings, are recorded in the Scroll of the Kings of Israel and Judah. His son Jehoiachin replaced him as king.'
EXEC add_BibleVerse @BibleId, 114036009, N'Jehoiachin was eighteen years old when he became king, and he reigned three months and ten days in Jerusalem. He did evil in the sight of the Lord.'
EXEC add_BibleVerse @BibleId, 114036010, N'At the beginning of the year King Nebuchadnezzar ordered him to be brought to Babylon, along with the valuable items in the Lord’s temple. In his place he made his relative Zedekiah king over Judah and Jerusalem.'
EXEC add_BibleVerse @BibleId, 114036011, N'Zedekiah was twenty-one years old when he became king, and he ruled for eleven years in Jerusalem.'
EXEC add_BibleVerse @BibleId, 114036012, N'He did evil in the sight of the Lord his God. He did not humble himself before Jeremiah the prophet, the Lord’s spokesman.'
EXEC add_BibleVerse @BibleId, 114036013, N'He also rebelled against King Nebuchadnezzar, who had made him vow allegiance in the name of God. He was stubborn and obstinate, and refused to return to the Lord God of Israel.'
EXEC add_BibleVerse @BibleId, 114036014, N'All the leaders of the priests and people became more unfaithful and committed the same horrible sins practiced by the nations. They defiled the Lord’s temple which he had consecrated in Jerusalem.'
EXEC add_BibleVerse @BibleId, 114036015, N'The Lord God of their ancestors continually warned them through his messengers, for he felt compassion for his people and his dwelling place.'
EXEC add_BibleVerse @BibleId, 114036016, N'But they mocked God’s messengers, despised his warnings, and ridiculed his prophets. Finally the Lord got very angry at his people and there was no one who could prevent his judgment.'
EXEC add_BibleVerse @BibleId, 114036017, N'He brought against them the king of the Babylonians, who slaughtered their young men in their temple. He did not spare young men or women, or even the old and aging. God handed everyone over to him.'
EXEC add_BibleVerse @BibleId, 114036018, N'He carried away to Babylon all the items in God’s temple, whether large or small, as well as what was in the treasuries of the Lord’s temple and in the treasuries of the king and his officials.'
EXEC add_BibleVerse @BibleId, 114036019, N'They burned down the Lord’s temple and tore down the wall of Jerusalem. They burned all its fortified buildings and destroyed all its valuable items.'
EXEC add_BibleVerse @BibleId, 114036020, N'He deported to Babylon all who escaped the sword. They served him and his sons until the Persian kingdom rose to power.'
EXEC add_BibleVerse @BibleId, 114036021, N'This took place to fulfill the Lord’s message delivered through Jeremiah. The land experienced its sabbatical years; it remained desolate for seventy years, as prophesied.'
EXEC add_BibleVerse @BibleId, 114036022, N'In the first year of the reign of King Cyrus of Persia, in fulfillment of the promise he delivered through Jeremiah, the Lord moved King Cyrus of Persia to issue a written decree throughout his kingdom.'
EXEC add_BibleVerse @BibleId, 114036023, N'It read: “This is what King Cyrus of Persia says: ‘The Lord God of the heavens has given to me all the kingdoms of the earth. He has appointed me to build for him a temple in Jerusalem in Judah. May the Lord your God energize you who belong to his people, so you may be able to go back there!”'
EXEC add_BibleVerse @BibleId, 115001001, N'In the first year of King Cyrus of Persia, in order to fulfill the Lord’s message spoken through Jeremiah, the Lord stirred the mind of King Cyrus of Persia. He disseminated a proclamation throughout his entire kingdom, announcing in a written edict the following:'
EXEC add_BibleVerse @BibleId, 115001002, N'“Thus says King Cyrus of Persia: “‘The Lord God of heaven has given me all the kingdoms of the earth. He has instructed me to build a temple for him in Jerusalem, which is in Judah.'
EXEC add_BibleVerse @BibleId, 115001003, N'Anyone from his people among you (may his God be with him!) may go up to Jerusalem, which is in Judah, and may build the temple of the Lord God of Israel – he is the God who is in Jerusalem.'
EXEC add_BibleVerse @BibleId, 115001004, N'Anyone who survives in any of those places where he is a resident foreigner must be helped by his neighbors with silver, gold, equipment, and animals, along with voluntary offerings for the temple of God which is in Jerusalem.’”'
EXEC add_BibleVerse @BibleId, 115001005, N'Then the leaders of Judah and Benjamin, along with the priests and the Levites – all those whose mind God had stirred – got ready to go up in order to build the temple of the Lord in Jerusalem.'
EXEC add_BibleVerse @BibleId, 115001006, N'All their neighbors assisted them with silver utensils, gold, equipment, animals, and expensive gifts, not to mention all the voluntary offerings.'
EXEC add_BibleVerse @BibleId, 115001007, N'Then King Cyrus brought out the vessels of the Lord’s temple which Nebuchadnezzar had brought from Jerusalem and had displayed in the temple of his gods.'
EXEC add_BibleVerse @BibleId, 115001008, N'King Cyrus of Persia entrusted them to Mithredath the treasurer, who counted them out to Sheshbazzar the leader of the Judahite exiles.'
EXEC add_BibleVerse @BibleId, 115001009, N'The inventory of these items was as follows: 30 gold basins, 1,000 silver basins, 29 silver utensils,'
EXEC add_BibleVerse @BibleId, 115001010, N'30 gold bowls, 410 other silver bowls, and 1,000 other vessels.'
EXEC add_BibleVerse @BibleId, 115001011, N'All these gold and silver vessels totaled 5,400. Sheshbazzar brought them all along when the captives were brought up from Babylon to Jerusalem.'
EXEC add_BibleVerse @BibleId, 115002001, N'These are the people of the province who were going up, from the captives of the exile whom King Nebuchadnezzar of Babylon had forced into exile in Babylon. They returned to Jerusalem and Judah, each to his own city.'
EXEC add_BibleVerse @BibleId, 115002002, N'They came with Zerubbabel, Jeshua, Nehemiah, Seraiah, Reelaiah, Mordecai, Bilshan, Mispar, Bigvai, Rehum, and Baanah. The number of Israelites was as follows:'
EXEC add_BibleVerse @BibleId, 115002003, N'the descendants of Parosh: 2,172;'
EXEC add_BibleVerse @BibleId, 115002004, N'the descendants of Shephatiah: 372;'
EXEC add_BibleVerse @BibleId, 115002005, N'the descendants of Arah: 775;'
EXEC add_BibleVerse @BibleId, 115002006, N'the descendants of Pahath-Moab (from the line of Jeshua and Joab): 2,812;'
EXEC add_BibleVerse @BibleId, 115002007, N'the descendants of Elam: 1,254;'
EXEC add_BibleVerse @BibleId, 115002008, N'the descendants of Zattu: 945;'
EXEC add_BibleVerse @BibleId, 115002009, N'the descendants of Zaccai: 760;'
EXEC add_BibleVerse @BibleId, 115002010, N'the descendants of Bani: 642;'
EXEC add_BibleVerse @BibleId, 115002011, N'the descendants of Bebai: 623;'
EXEC add_BibleVerse @BibleId, 115002012, N'the descendants of Azgad: 1,222;'
EXEC add_BibleVerse @BibleId, 115002013, N'the descendants of Adonikam: 666;'
EXEC add_BibleVerse @BibleId, 115002014, N'the descendants of Bigvai: 2,056;'
EXEC add_BibleVerse @BibleId, 115002015, N'the descendants of Adin: 454;'
EXEC add_BibleVerse @BibleId, 115002016, N'the descendants of Ater (through Hezekiah): 98;'
EXEC add_BibleVerse @BibleId, 115002017, N'the descendants of Bezai: 323;'
EXEC add_BibleVerse @BibleId, 115002018, N'the descendants of Jorah: 112;'
EXEC add_BibleVerse @BibleId, 115002019, N'the descendants of Hashum: 223;'
EXEC add_BibleVerse @BibleId, 115002020, N'the descendants of Gibbar: 95.'
EXEC add_BibleVerse @BibleId, 115002021, N'The men of Bethlehem: 123;'
EXEC add_BibleVerse @BibleId, 115002022, N'the men of Netophah: 56;'
EXEC add_BibleVerse @BibleId, 115002023, N'the men of Anathoth: 128;'
EXEC add_BibleVerse @BibleId, 115002024, N'the men of the family of Azmaveth: 42;'
EXEC add_BibleVerse @BibleId, 115002025, N'the men of Kiriath Jearim, Kephirah and Beeroth: 743;'
EXEC add_BibleVerse @BibleId, 115002026, N'the men of Ramah and Geba: 621;'
EXEC add_BibleVerse @BibleId, 115002027, N'the men of Micmash: 122;'
EXEC add_BibleVerse @BibleId, 115002028, N'the men of Bethel and Ai: 223;'
EXEC add_BibleVerse @BibleId, 115002029, N'the descendants of Nebo: 52;'
EXEC add_BibleVerse @BibleId, 115002030, N'the descendants of Magbish: 156;'
EXEC add_BibleVerse @BibleId, 115002031, N'the descendants of the other Elam: 1,254;'
EXEC add_BibleVerse @BibleId, 115002032, N'the descendants of Harim: 320;'
EXEC add_BibleVerse @BibleId, 115002033, N'the men of Lod, Hadid, and Ono: 725;'
EXEC add_BibleVerse @BibleId, 115002034, N'the men of Jericho: 345;'
EXEC add_BibleVerse @BibleId, 115002035, N'the descendants of Senaah: 3,630.'
EXEC add_BibleVerse @BibleId, 115002036, N'The priests: the descendants of Jedaiah (through the family of Jeshua): 973;'
EXEC add_BibleVerse @BibleId, 115002037, N'the descendants of Immer: 1,052;'
EXEC add_BibleVerse @BibleId, 115002038, N'the descendants of Pashhur: 1,247;'
EXEC add_BibleVerse @BibleId, 115002039, N'the descendants of Harim: 1,017.'
EXEC add_BibleVerse @BibleId, 115002040, N'The Levites: the descendants of Jeshua and Kadmiel (through the line of Hodaviah): 74.'
EXEC add_BibleVerse @BibleId, 115002041, N'The singers: the descendants of Asaph: 128.'
EXEC add_BibleVerse @BibleId, 115002042, N'The gatekeepers: the descendants of Shallum, the descendants of Ater, the descendants of Talmon, the descendants of Akkub, the descendants of Hatita, and the descendants of Shobai: 139.'
EXEC add_BibleVerse @BibleId, 115002043, N'The temple servants: the descendants of Ziha, the descendants of Hasupha, the descendants of Tabbaoth,'
EXEC add_BibleVerse @BibleId, 115002044, N'the descendants of Keros, the descendants of Siaha, the descendants of Padon,'
EXEC add_BibleVerse @BibleId, 115002045, N'the descendants of Lebanah, the descendants of Hagabah, the descendants of Akkub,'
EXEC add_BibleVerse @BibleId, 115002046, N'the descendants of Hagab, the descendants of Shalmai, the descendants of Hanan,'
EXEC add_BibleVerse @BibleId, 115002047, N'the descendants of Giddel, the descendants of Gahar, the descendants of Reaiah,'
EXEC add_BibleVerse @BibleId, 115002048, N'the descendants of Rezin, the descendants of Nekoda, the descendants of Gazzam,'
EXEC add_BibleVerse @BibleId, 115002049, N'the descendants of Uzzah, the descendants of Paseah, the descendants of Besai,'
EXEC add_BibleVerse @BibleId, 115002050, N'the descendants of Asnah, the descendants of Meunim, the descendants of Nephussim,'
EXEC add_BibleVerse @BibleId, 115002051, N'the descendants of Bakbuk, the descendants of Hakupha, the descendants of Harhur,'
EXEC add_BibleVerse @BibleId, 115002052, N'the descendants of Bazluth, the descendants of Mehida, the descendants of Harsha,'
EXEC add_BibleVerse @BibleId, 115002053, N'the descendants of Barkos, the descendants of Sisera, the descendants of Temah,'
EXEC add_BibleVerse @BibleId, 115002054, N'the descendants of Neziah, and the descendants of Hatipha.'
EXEC add_BibleVerse @BibleId, 115002055, N'The descendants of the servants of Solomon: the descendants of Sotai, the descendants of Hassophereth, the descendants of Peruda,'
EXEC add_BibleVerse @BibleId, 115002056, N'the descendants of Jaala, the descendants of Darkon, the descendants of Giddel,'
EXEC add_BibleVerse @BibleId, 115002057, N'the descendants of Shephatiah, the descendants of Hattil, the descendants of Pokereth-Hazzebaim, and the descendants of Ami.'
EXEC add_BibleVerse @BibleId, 115002058, N'All the temple servants and the descendants of the servants of Solomon: 392.'
EXEC add_BibleVerse @BibleId, 115002059, N'These are the ones that came up from Tel Melah, Tel Harsha, Kerub, Addon, and Immer (although they were unable to certify their family connection or their ancestry, as to whether they really were from Israel):'
EXEC add_BibleVerse @BibleId, 115002060, N'the descendants of Delaiah, the descendants of Tobiah, and the descendants of Nekoda: 652.'
EXEC add_BibleVerse @BibleId, 115002061, N'And from among the priests: the descendants of Hobaiah, the descendants of Hakkoz, and the descendants of Barzillai (who had taken a wife from the daughters of Barzillai the Gileadite and was called by that name).'
EXEC add_BibleVerse @BibleId, 115002062, N'They searched for their records in the genealogical materials, but did not find them. They were therefore excluded from the priesthood.'
EXEC add_BibleVerse @BibleId, 115002063, N'The governor instructed them not to eat any of the sacred food until there was a priest who could consult the Urim and Thummim.'
EXEC add_BibleVerse @BibleId, 115002064, N'The entire group numbered 42,360,'
EXEC add_BibleVerse @BibleId, 115002065, N'not counting their male and female servants, who numbered 7,337. They also had 200 male and female singers'
EXEC add_BibleVerse @BibleId, 115002066, N'and 736 horses, 245 mules,'
EXEC add_BibleVerse @BibleId, 115002067, N'435 camels, and 6,720 donkeys.'
EXEC add_BibleVerse @BibleId, 115002068, N'When they came to the Lord’s temple in Jerusalem, some of the family leaders offered voluntary offerings for the temple of God in order to rebuild it on its site.'
EXEC add_BibleVerse @BibleId, 115002069, N'As they were able, they gave to the treasury for this work 61,000 drachmas of gold, 5,000 minas of silver, and 100 priestly robes.'
EXEC add_BibleVerse @BibleId, 115002070, N'The priests, the Levites, some of the people, the singers, the gatekeepers, and the temple servants lived in their towns, and all the rest of Israel lived in their towns.'
EXEC add_BibleVerse @BibleId, 115003001, N'When the seventh month arrived and the Israelites were living in their towns, the people assembled in Jerusalem.'
EXEC add_BibleVerse @BibleId, 115003002, N'Then Jeshua the son of Jozadak and his priestly colleagues and Zerubbabel son of Shealtiel and his colleagues started to build the altar of the God of Israel so they could offer burnt offerings on it as required by the law of Moses the man of God.'
EXEC add_BibleVerse @BibleId, 115003003, N'They established the altar on its foundations, even though they were in terror of the local peoples, and they offered burnt offerings on it to the Lord, both the morning and the evening offerings.'
EXEC add_BibleVerse @BibleId, 115003004, N'They observed the Festival of Temporary Shelters as required and offered the proper number of daily burnt offerings according to the requirement for each day.'
EXEC add_BibleVerse @BibleId, 115003005, N'Afterward they offered the continual burnt offerings and those for the new moons and those for all the holy assemblies of the Lord and all those that were being voluntarily offered to the Lord.'
EXEC add_BibleVerse @BibleId, 115003006, N'From the first day of the seventh month they began to offer burnt offerings to the Lord. However, the Lord’s temple was not at that time established.'
EXEC add_BibleVerse @BibleId, 115003007, N'So they provided money for the masons and carpenters, and food, beverages, and olive oil for the people of Sidon so that they would bring cedar timber from Lebanon to the seaport at Joppa, in accord with the edict of King Cyrus of Persia.'
EXEC add_BibleVerse @BibleId, 115003008, N'In the second year after they had come to the temple of God in Jerusalem, in the second month, Zerubbabel the son of Shealtiel and Jeshua the son of Jozadak initiated the work, along with the rest of their associates, the priests and the Levites, and all those who were coming to Jerusalem from the exile. They appointed the Levites who were at least twenty years old to take charge of the work on the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 115003009, N'So Jeshua appointed both his sons and his relatives, Kadmiel and his sons (the sons of Yehudah ), to take charge of the workers in the temple of God, along with the sons of Henadad, their sons, and their relatives the Levites.'
EXEC add_BibleVerse @BibleId, 115003010, N'When the builders established the Lord’s temple, the priests, ceremonially attired and with their clarions, and the Levites (the sons of Asaph) with their cymbals, stood to praise the Lord according to the instructions left by King David of Israel.'
EXEC add_BibleVerse @BibleId, 115003011, N'With antiphonal response they sang, praising and glorifying the Lord: “For he is good; his loyal love toward Israel is forever.” All the people gave a loud shout as they praised the Lord when the temple of the Lord was established.'
EXEC add_BibleVerse @BibleId, 115003012, N'Many of the priests, the Levites, and the leaders – older people who had seen with their own eyes the former temple while it was still established – were weeping loudly, and many others raised their voice in a joyous shout.'
EXEC add_BibleVerse @BibleId, 115003013, N'People were unable to tell the difference between the sound of joyous shouting and the sound of the people’s weeping, for the people were shouting so loudly that the sound was heard a long way off.'
EXEC add_BibleVerse @BibleId, 115004001, N'When the enemies of Judah and Benjamin learned that the former exiles were building a temple for the Lord God of Israel,'
EXEC add_BibleVerse @BibleId, 115004002, N'they came to Zerubbabel and the leaders and said to them, “Let us help you build, for like you we seek your God and we have been sacrificing to him from the time of King Esarhaddon of Assyria, who brought us here.”'
EXEC add_BibleVerse @BibleId, 115004003, N'But Zerubbabel, Jeshua, and the rest of the leaders of Israel said to them, “You have no right to help us build the temple of our God. We will build it by ourselves for the Lord God of Israel, just as King Cyrus, the king of Persia, has commanded us.”'
EXEC add_BibleVerse @BibleId, 115004004, N'Then the local people began to discourage the people of Judah and to dishearten them from building.'
EXEC add_BibleVerse @BibleId, 115004005, N'They were hiring advisers to oppose them, so as to frustrate their plans, throughout the time of King Cyrus of Persia until the reign of King Darius of Persia.'
EXEC add_BibleVerse @BibleId, 115004006, N'At the beginning of the reign of Ahasuerus they filed an accusation against the inhabitants of Judah and Jerusalem.'
EXEC add_BibleVerse @BibleId, 115004007, N'And during the reign of Artaxerxes, Bishlam, Mithredath, Tabeel, and the rest of their colleagues wrote to King Artaxerxes of Persia. This letter was first written in Aramaic but then translated. Aramaic:'
EXEC add_BibleVerse @BibleId, 115004008, N'Rehum the commander and Shimshai the scribe wrote a letter concerning Jerusalem to King Artaxerxes as follows:'
EXEC add_BibleVerse @BibleId, 115004009, N'From Rehum the commander, Shimshai the scribe, and the rest of their colleagues – the judges, the rulers, the officials, the secretaries, the Erechites, the Babylonians, the people of Susa (that is, the Elamites),'
EXEC add_BibleVerse @BibleId, 115004010, N'and the rest of nations whom the great and noble Ashurbanipal deported and settled in the cities of Samaria and other places in Trans-Euphrates.'
EXEC add_BibleVerse @BibleId, 115004011, N'(This is a copy of the letter they sent to him:) “To King Artaxerxes, from your servants in Trans-Euphrates:'
EXEC add_BibleVerse @BibleId, 115004012, N'Now let the king be aware that the Jews who came up to us from you have gone to Jerusalem. They are rebuilding that rebellious and odious city. They are completing its walls and repairing its foundations.'
EXEC add_BibleVerse @BibleId, 115004013, N'Let the king also be aware that if this city is built and its walls are completed, no more tax, custom, or toll will be paid, and the royal treasury will suffer loss.'
EXEC add_BibleVerse @BibleId, 115004014, N'In light of the fact that we are loyal to the king, and since it does not seem appropriate to us that the king should sustain damage, we are sending the king this information'
EXEC add_BibleVerse @BibleId, 115004015, N'so that he may initiate a search of the records of his predecessors and discover in those records that this city is rebellious and injurious to both kings and provinces, producing internal revolts from long ago. It is for this very reason that this city was destroyed.'
EXEC add_BibleVerse @BibleId, 115004016, N'We therefore are informing the king that if this city is rebuilt and its walls are completed, you will not retain control of this portion of Trans-Euphrates.”'
EXEC add_BibleVerse @BibleId, 115004017, N'The king sent the following response: “To Rehum the commander, Shimshai the scribe, and the rest of their colleagues who live in Samaria and other parts of Trans-Euphrates: Greetings!'
EXEC add_BibleVerse @BibleId, 115004018, N'The letter you sent to us has been translated and read in my presence.'
EXEC add_BibleVerse @BibleId, 115004019, N'So I gave orders, and it was determined that this city from long ago has been engaging in insurrection against kings. It has continually engaged in rebellion and revolt.'
EXEC add_BibleVerse @BibleId, 115004020, N'Powerful kings have been over Jerusalem who ruled throughout the entire Trans-Euphrates and who were the beneficiaries of tribute, custom, and toll.'
EXEC add_BibleVerse @BibleId, 115004021, N'Now give orders that these men cease their work and that this city not be rebuilt until such time as I so instruct.'
EXEC add_BibleVerse @BibleId, 115004022, N'Exercise appropriate caution so that there is no negligence in this matter. Why should danger increase to the point that kings sustain damage?”'
EXEC add_BibleVerse @BibleId, 115004023, N'Then, as soon as the copy of the letter from King Artaxerxes was read in the presence of Rehum, Shimshai the scribe, and their colleagues, they proceeded promptly to the Jews in Jerusalem and stopped them with threat of armed force.'
EXEC add_BibleVerse @BibleId, 115004024, N'So the work on the temple of God in Jerusalem came to a halt. It remained halted until the second year of the reign of King Darius of Persia.'
EXEC add_BibleVerse @BibleId, 115005001, N'Then the prophets Haggai and Zechariah son of Iddo prophesied concerning the Jews who were in Judah and Jerusalem in the name of the God of Israel who was over them.'
EXEC add_BibleVerse @BibleId, 115005002, N'Then Zerubbabel the son of Shealtiel and Jeshua the son of Jozadak began to rebuild the temple of God in Jerusalem. The prophets of God were with them, supporting them.'
EXEC add_BibleVerse @BibleId, 115005003, N'At that time Tattenai governor of Trans-Euphrates, Shethar-Bozenai, and their colleagues came to them and asked, “Who gave you authority to rebuild this temple and to complete this structure?”'
EXEC add_BibleVerse @BibleId, 115005004, N'They also asked them, “What are the names of the men who are building this edifice?”'
EXEC add_BibleVerse @BibleId, 115005005, N'But God was watching over the elders of Judah, and they were not stopped until a report could be dispatched to Darius and a letter could be sent back concerning this.'
EXEC add_BibleVerse @BibleId, 115005006, N'This is a copy of the letter that Tattenai governor of Trans-Euphrates, Shethar-Bozenai, and his colleagues who were the officials of Trans-Euphrates sent to King Darius.'
EXEC add_BibleVerse @BibleId, 115005007, N'The report they sent to him was written as follows: “To King Darius: All greetings!'
EXEC add_BibleVerse @BibleId, 115005008, N'Let it be known to the king that we have gone to the province of Judah, to the temple of the great God. It is being built with large stones, and timbers are being placed in the walls. This work is being done with all diligence and is prospering in their hands.'
EXEC add_BibleVerse @BibleId, 115005009, N'We inquired of those elders, asking them, ‘Who gave you the authority to rebuild this temple and to complete this structure?’'
EXEC add_BibleVerse @BibleId, 115005010, N'We also inquired of their names in order to inform you, so that we might write the names of the men who were their leaders.'
EXEC add_BibleVerse @BibleId, 115005011, N'They responded to us in the following way: ‘We are servants of the God of heaven and earth. We are rebuilding the temple which was previously built many years ago. A great king of Israel built it and completed it.'
EXEC add_BibleVerse @BibleId, 115005012, N'But after our ancestors angered the God of heaven, he delivered them into the hands of King Nebuchadnezzar of Babylon, the Chaldean, who destroyed this temple and exiled the people to Babylon.'
EXEC add_BibleVerse @BibleId, 115005013, N'But in the first year of King Cyrus of Babylon, King Cyrus enacted a decree to rebuild this temple of God.'
EXEC add_BibleVerse @BibleId, 115005014, N'Even the gold and silver vessels of the temple of God that Nebuchadnezzar had taken from the temple in Jerusalem and had brought to the palace of Babylon – even those things King Cyrus brought from the palace of Babylon and presented to a man by the name of Sheshbazzar whom he had appointed as governor.'
EXEC add_BibleVerse @BibleId, 115005015, N'He said to him, “Take these vessels and go deposit them in the temple in Jerusalem, and let the house of God be rebuilt in its proper location.”'
EXEC add_BibleVerse @BibleId, 115005016, N'Then this Sheshbazzar went and laid the foundations of the temple of God in Jerusalem. From that time to the present moment it has been in the process of being rebuilt, although it is not yet finished.’'
EXEC add_BibleVerse @BibleId, 115005017, N'“Now if the king is so inclined, let a search be conducted in the royal archives there in Babylon in order to determine whether King Cyrus did in fact issue orders for this temple of God to be rebuilt in Jerusalem. Then let the king send us a decision concerning this matter.”'
EXEC add_BibleVerse @BibleId, 115006001, N'So Darius the king issued orders, and they searched in the archives of the treasury which were deposited there in Babylon.'
EXEC add_BibleVerse @BibleId, 115006002, N'A scroll was found in the citadel of Ecbatana which is in the province of Media, and it was inscribed as follows: “Memorandum:'
EXEC add_BibleVerse @BibleId, 115006003, N'In the first year of his reign, King Cyrus gave orders concerning the temple of God in Jerusalem: ‘Let the temple be rebuilt as a place where sacrifices are offered. Let its foundations be set in place. Its height is to be ninety feet and its width ninety feet,'
EXEC add_BibleVerse @BibleId, 115006004, N'with three layers of large stones and one layer of timber. The expense is to be subsidized by the royal treasury.'
EXEC add_BibleVerse @BibleId, 115006005, N'Furthermore let the gold and silver vessels of the temple of God, which Nebuchadnezzar brought from the temple in Jerusalem and carried to Babylon, be returned and brought to their proper place in the temple in Jerusalem. Let them be deposited in the temple of God.’'
EXEC add_BibleVerse @BibleId, 115006006, N'“Now Tattenai governor of Trans-Euphrates, Shethar Bozenai, and their colleagues, the officials of Trans-Euphrates – all of you stay far away from there!'
EXEC add_BibleVerse @BibleId, 115006007, N'Leave the work on this temple of God alone. Let the governor of the Jews and the elders of the Jews rebuild this temple of God in its proper place.'
EXEC add_BibleVerse @BibleId, 115006008, N'“I also hereby issue orders as to what you are to do with those elders of the Jews in order to rebuild this temple of God. From the royal treasury, from the taxes of Trans-Euphrates the complete costs are to be given to these men, so that there may be no interruption of the work.'
EXEC add_BibleVerse @BibleId, 115006009, N'Whatever is needed – whether oxen or rams or lambs or burnt offerings for the God of heaven or wheat or salt or wine or oil, as required by the priests who are in Jerusalem – must be given to them daily without any neglect,'
EXEC add_BibleVerse @BibleId, 115006010, N'so that they may be offering incense to the God of heaven and may be praying for the good fortune of the king and his family.'
EXEC add_BibleVerse @BibleId, 115006011, N'“I hereby give orders that if anyone changes this directive a beam is to be pulled out from his house and he is to be raised up and impaled on it, and his house is to be reduced to a rubbish heap for this indiscretion.'
EXEC add_BibleVerse @BibleId, 115006012, N'May God who makes his name to reside there overthrow any king or nation who reaches out to cause such change so as to destroy this temple of God in Jerusalem. I, Darius, have given orders. Let them be carried out with precision!”'
EXEC add_BibleVerse @BibleId, 115006013, N'Then Tattenai governor of Trans-Euphrates, Shethar-Bozenai, and their colleagues acted accordingly – with precision, just as Darius the king had given instructions.'
EXEC add_BibleVerse @BibleId, 115006014, N'The elders of the Jews continued building and prospering, while at the same time Haggai the prophet and Zechariah the son of Iddo continued prophesying. They built and brought it to completion by the command of the God of Israel and by the command of Cyrus and Darius and Artaxerxes king of Persia.'
EXEC add_BibleVerse @BibleId, 115006015, N'They finished this temple on the third day of the month Adar, which is the sixth year of the reign of King Darius.'
EXEC add_BibleVerse @BibleId, 115006016, N'The people of Israel – the priests, the Levites, and the rest of the exiles – observed the dedication of this temple of God with joy.'
EXEC add_BibleVerse @BibleId, 115006017, N'For the dedication of this temple of God they offered one hundred bulls, two hundred rams, four hundred lambs, and twelve male goats for the sin of all Israel, according to the number of the tribes of Israel.'
EXEC add_BibleVerse @BibleId, 115006018, N'They appointed the priests by their divisions and the Levites by their divisions over the worship of God at Jerusalem, in accord with the book of Moses.'
EXEC add_BibleVerse @BibleId, 115006019, N'The exiles observed the Passover on the fourteenth day of the first month.'
EXEC add_BibleVerse @BibleId, 115006020, N'The priests and the Levites had purified themselves, every last one, and they all were ceremonially pure. They sacrificed the Passover lamb for all the exiles, for their colleagues the priests, and for themselves.'
EXEC add_BibleVerse @BibleId, 115006021, N'The Israelites who were returning from the exile ate it, along with all those who had joined them in separating themselves from the uncleanness of the nations of the land to seek the Lord God of Israel.'
EXEC add_BibleVerse @BibleId, 115006022, N'They observed the Feast of Unleavened Bread for seven days with joy, for the Lord had given them joy and had changed the opinion of the king of Assyria toward them, so that he assisted them in the work on the temple of God, the God of Israel.'
EXEC add_BibleVerse @BibleId, 115007001, N'Now after these things had happened, during the reign of King Artaxerxes of Persia, Ezra came up from Babylon. Ezra was the son of Seraiah, who was the son of Azariah, who was the son of Hilkiah,'
EXEC add_BibleVerse @BibleId, 115007002, N'who was the son of Shallum, who was the son of Zadok, who was the son of Ahitub,'
EXEC add_BibleVerse @BibleId, 115007003, N'who was the son of Amariah, who was the son of Azariah, who was the son of Meraioth,'
EXEC add_BibleVerse @BibleId, 115007004, N'who was the son of Zerahiah, who was the son of Uzzi, who was the son of Bukki,'
EXEC add_BibleVerse @BibleId, 115007005, N'who was the son of Abishua, who was the son of Phinehas, who was the son of Eleazar, who was the son of Aaron the chief priest.'
EXEC add_BibleVerse @BibleId, 115007006, N'This Ezra is the one who came up from Babylon. He was a scribe who was skilled in the law of Moses which the Lord God of Israel had given. The king supplied him with everything he requested, for the hand of the Lord his God was on him.'
EXEC add_BibleVerse @BibleId, 115007007, N'In the seventh year of King Artaxerxes, Ezra brought up to Jerusalem some of the Israelites and some of the priests, the Levites, the attendants, the gatekeepers, and the temple servants.'
EXEC add_BibleVerse @BibleId, 115007008, N'He entered Jerusalem in the fifth month of the seventh year of the king.'
EXEC add_BibleVerse @BibleId, 115007009, N'On the first day of the first month he had determined to make the ascent from Babylon, and on the first day of the fifth month he arrived at Jerusalem, for the good hand of his God was on him.'
EXEC add_BibleVerse @BibleId, 115007010, N'Now Ezra had dedicated himself to the study of the law of the Lord, to its observance, and to teaching its statutes and judgments in Israel.'
EXEC add_BibleVerse @BibleId, 115007011, N'What follows is a copy of the letter that King Artaxerxes gave to Ezra the priestly scribe. Ezra was a scribe in matters pertaining to the commandments of the Lord and his statutes over Israel:'
EXEC add_BibleVerse @BibleId, 115007012, N'“Artaxerxes, king of kings, to Ezra the priest, a scribe of the perfect law of the God of heaven:'
EXEC add_BibleVerse @BibleId, 115007013, N'I have now issued a decree that anyone in my kingdom from the people of Israel – even the priests and Levites – who wishes to do so may go up with you to Jerusalem.'
EXEC add_BibleVerse @BibleId, 115007014, N'You are authorized by the king and his seven advisers to inquire concerning Judah and Jerusalem, according to the law of your God which is in your possession,'
EXEC add_BibleVerse @BibleId, 115007015, N'and to bring silver and gold which the king and his advisers have freely contributed to the God of Israel, who resides in Jerusalem,'
EXEC add_BibleVerse @BibleId, 115007016, N'along with all the silver and gold that you may collect throughout all the province of Babylon and the contributions of the people and the priests for the temple of their God which is in Jerusalem.'
EXEC add_BibleVerse @BibleId, 115007017, N'With this money you should be sure to purchase bulls, rams, and lambs, along with the appropriate meal offerings and libations. You should bring them to the altar of the temple of your God which is in Jerusalem.'
EXEC add_BibleVerse @BibleId, 115007018, N'You may do whatever seems appropriate to you and your colleagues with the rest of the silver and the gold, in keeping with the will of your God.'
EXEC add_BibleVerse @BibleId, 115007019, N'Deliver to the God of Jerusalem the vessels that are given to you for the service of the temple of your God.'
EXEC add_BibleVerse @BibleId, 115007020, N'The rest of the needs for the temple of your God that you may have to supply, you may do so from the royal treasury.'
EXEC add_BibleVerse @BibleId, 115007021, N'“I, King Artaxerxes, hereby issue orders to all the treasurers of Trans-Euphrates, that you precisely execute all that Ezra the priestly scribe of the law of the God of heaven may request of you –'
EXEC add_BibleVerse @BibleId, 115007022, N'up to 100 talents of silver, 100 cors of wheat, 100 baths of wine, 100 baths of olive oil, and unlimited salt.'
EXEC add_BibleVerse @BibleId, 115007023, N'Everything that the God of heaven has required should be precisely done for the temple of the God of heaven. Why should there be wrath against the empire of the king and his sons?'
EXEC add_BibleVerse @BibleId, 115007024, N'Furthermore, be aware of the fact that you have no authority to impose tax, tribute, or toll on any of the priests, the Levites, the musicians, the doorkeepers, the temple servants, or the attendants at the temple of this God.'
EXEC add_BibleVerse @BibleId, 115007025, N'“Now you, Ezra, in keeping with the wisdom of your God which you possess, appoint judges and court officials who can arbitrate cases on behalf of all the people who are in Trans-Euphrates who know the laws of your God. Those who do not know this law should be taught.'
EXEC add_BibleVerse @BibleId, 115007026, N'Everyone who does not observe both the law of your God and the law of the king will be completely liable to the appropriate penalty, whether it is death or banishment or confiscation of property or detainment in prison.”'
EXEC add_BibleVerse @BibleId, 115007027, N'Blessed be the Lord God of our fathers, who so moved in the heart of the king to so honor the temple of the Lord which is in Jerusalem!'
EXEC add_BibleVerse @BibleId, 115007028, N'He has also conferred his favor on me before the king, his advisers, and all the influential leaders of the king. I gained strength as the hand of the Lord my God was on me, and I gathered leaders from Israel to go up with me.'
EXEC add_BibleVerse @BibleId, 115008001, N'These are the leaders and those enrolled with them by genealogy who were coming up with me from Babylon during the reign of King Artaxerxes:'
EXEC add_BibleVerse @BibleId, 115008002, N'from the descendants of Phinehas, Gershom; from the descendants of Ithamar, Daniel; from the descendants of David, Hattush'
EXEC add_BibleVerse @BibleId, 115008003, N'the son of Shecaniah; from the descendants of Parosh, Zechariah, and with him were enrolled by genealogy 150 men;'
EXEC add_BibleVerse @BibleId, 115008004, N'from the descendants of Pahath-Moab, Eliehoenai son of Zerahiah, and with him 200 men;'
EXEC add_BibleVerse @BibleId, 115008005, N'from the descendants of Zattu, Shecaniah son of Jahaziel, and with him 300 men;'
EXEC add_BibleVerse @BibleId, 115008006, N'from the descendants of Adin, Ebed son of Jonathan, and with him 50 men;'
EXEC add_BibleVerse @BibleId, 115008007, N'from the descendants of Elam, Jeshaiah son of Athaliah, and with him 70 men;'
EXEC add_BibleVerse @BibleId, 115008008, N'from the descendants of Shephatiah, Zebadiah son of Michael, and with him 80 men;'
EXEC add_BibleVerse @BibleId, 115008009, N'from the descendants of Joab, Obadiah son of Jehiel, and with him 218 men;'
EXEC add_BibleVerse @BibleId, 115008010, N'from the descendants of Bani, Shelomith son of Josiphiah, and with him 160 men;'
EXEC add_BibleVerse @BibleId, 115008011, N'from the descendants of Bebai, Zechariah son of Bebai, and with him 28 men;'
EXEC add_BibleVerse @BibleId, 115008012, N'from the descendants of Azgad, Johanan son of Hakkatan, and with him 110 men;'
EXEC add_BibleVerse @BibleId, 115008013, N'from the descendants of Adonikam there were the latter ones. Their names were Eliphelet, Jeuel, and Shemaiah, and with them 60 men;'
EXEC add_BibleVerse @BibleId, 115008014, N'from the descendants of Bigvai, Uthai, and Zaccur, and with them 70 men.'
EXEC add_BibleVerse @BibleId, 115008015, N'I had them assemble at the canal that flows toward Ahava, and we camped there for three days. I observed that the people and the priests were present, but I found no Levites there.'
EXEC add_BibleVerse @BibleId, 115008016, N'So I sent for Eliezer, Ariel, Shemaiah, Elnathan, Jarib, Elnathan, Nathan, Zechariah, and Meshullam, who were leaders, and Joiarib and Elnathan, who were teachers.'
EXEC add_BibleVerse @BibleId, 115008017, N'I sent them to Iddo, who was the leader in the place called Casiphia. I told them what to say to Iddo and his relatives, who were the temple servants in Casiphia, so they would bring us attendants for the temple of our God.'
EXEC add_BibleVerse @BibleId, 115008018, N'Due to the fact that the good hand of our God was on us, they brought us a skilled man, from the descendants of Mahli the son of Levi son of Israel. This man was Sherebiah, who was accompanied by his sons and brothers, 18 men,'
EXEC add_BibleVerse @BibleId, 115008019, N'and Hashabiah, along with Jeshaiah from the descendants of Merari, with his brothers and their sons, 20 men,'
EXEC add_BibleVerse @BibleId, 115008020, N'and some of the temple servants that David and his officials had established for the work of the Levites – 220 of them. They were all designated by name.'
EXEC add_BibleVerse @BibleId, 115008021, N'I called for a fast there by the Ahava Canal, so that we might humble ourselves before our God and seek from him a safe journey for us, our children, and all our property.'
EXEC add_BibleVerse @BibleId, 115008022, N'I was embarrassed to request soldiers and horsemen from the king to protect us from the enemy along the way, because we had said to the king, “The good hand of our God is on everyone who is seeking him, but his great anger is against everyone who forsakes him.”'
EXEC add_BibleVerse @BibleId, 115008023, N'So we fasted and prayed to our God about this, and he answered us.'
EXEC add_BibleVerse @BibleId, 115008024, N'Then I set apart twelve of the leading priests, together with Sherebiah, Hashabiah, and ten of their brothers,'
EXEC add_BibleVerse @BibleId, 115008025, N'and I weighed out to them the silver, the gold, and the vessels intended for the temple of our God – items that the king, his advisers, his officials, and all Israel who were present had contributed.'
EXEC add_BibleVerse @BibleId, 115008026, N'I weighed out to them 650 talents of silver, silver vessels worth 100 talents, 100 talents of gold,'
EXEC add_BibleVerse @BibleId, 115008027, N'20 gold bowls worth 1,000 darics, and two exquisite vessels of gleaming bronze, as valuable as gold.'
EXEC add_BibleVerse @BibleId, 115008028, N'Then I said to them, “You are holy to the Lord, just as these vessels are holy. The silver and the gold are a voluntary offering to the Lord, the God of your fathers.'
EXEC add_BibleVerse @BibleId, 115008029, N'Be careful with them and protect them, until you weigh them out before the leading priests and the Levites and the family leaders of Israel in Jerusalem, in the storerooms of the temple of the Lord.”'
EXEC add_BibleVerse @BibleId, 115008030, N'Then the priests and the Levites took charge of the silver, the gold, and the vessels that had been weighed out, to transport them to Jerusalem to the temple of our God.'
EXEC add_BibleVerse @BibleId, 115008031, N'On the twelfth day of the first month we began traveling from the Ahava Canal to go to Jerusalem. The hand of our God was on us, and he delivered us from our enemy and from bandits along the way.'
EXEC add_BibleVerse @BibleId, 115008032, N'So we came to Jerusalem, and we stayed there for three days.'
EXEC add_BibleVerse @BibleId, 115008033, N'On the fourth day we weighed out the silver, the gold, and the vessels in the house of our God into the care of Meremoth son of Uriah, the priest, and Eleazar son of Phinehas, who were accompanied by Jozabad son of Jeshua and Noadiah son of Binnui, who were Levites.'
EXEC add_BibleVerse @BibleId, 115008034, N'Everything was verified by number and by weight, and the total weight was written down at that time.'
EXEC add_BibleVerse @BibleId, 115008035, N'The exiles who were returning from the captivity offered burnt offerings to the God of Israel – twelve bulls for all Israel, ninety-six rams, seventy-seven male lambs, along with twelve male goats as a sin offering. All this was a burnt offering to the Lord.'
EXEC add_BibleVerse @BibleId, 115008036, N'Then they presented the decrees of the king to the king’s satraps and to the governors of Trans-Euphrates, who gave help to the people and to the temple of God.'
EXEC add_BibleVerse @BibleId, 115009001, N'Now when these things had been completed, the leaders approached me and said, “The people of Israel, the priests, and the Levites have not separated themselves from the local residents who practice detestable things similar to those of the Canaanites, the Hittites, the Perizzites, the Jebusites, the Ammonites, the Moabites, the Egyptians, and the Amorites.'
EXEC add_BibleVerse @BibleId, 115009002, N'Indeed, they have taken some of their daughters as wives for themselves and for their sons, so that the holy race has become intermingled with the local residents. Worse still, the leaders and the officials have been at the forefront of all of this!”'
EXEC add_BibleVerse @BibleId, 115009003, N'When I heard this report, I tore my tunic and my robe and ripped out some of the hair from my head and beard. Then I sat down, quite devastated.'
EXEC add_BibleVerse @BibleId, 115009004, N'Everyone who held the words of the God of Israel in awe gathered around me because of the unfaithful acts of the people of the exile. Devastated, I continued to sit there until the evening offering.'
EXEC add_BibleVerse @BibleId, 115009005, N'At the time of the evening offering I got up from my self-abasement, with my tunic and robe torn, and then dropped to my knees and spread my hands to the Lord my God.'
EXEC add_BibleVerse @BibleId, 115009006, N'I prayed, “O my God, I am ashamed and embarrassed to lift my face to you, my God! For our iniquities have climbed higher than our heads, and our guilt extends to the heavens.'
EXEC add_BibleVerse @BibleId, 115009007, N'From the days of our fathers until this very day our guilt has been great. Because of our iniquities we, along with our kings and priests, have been delivered over by the local kings to sword, captivity, plunder, and embarrassment – right up to the present time.'
EXEC add_BibleVerse @BibleId, 115009008, N'“But now briefly we have received mercy from the Lord our God, in that he has left us a remnant and has given us a secure position in his holy place. Thus our God has enlightened our eyes and has given us a little relief in our time of servitude.'
EXEC add_BibleVerse @BibleId, 115009009, N'Although we are slaves, our God has not abandoned us in our servitude. He has extended kindness to us in the sight of the kings of Persia, in that he has revived us to restore the temple of our God and to raise up its ruins and to give us a protective wall in Judah and Jerusalem.'
EXEC add_BibleVerse @BibleId, 115009010, N'“And now what are we able to say after this, our God? For we have forsaken your commandments'
EXEC add_BibleVerse @BibleId, 115009011, N'which you commanded us through your servants the prophets with these words: ‘The land that you are entering to possess is a land defiled by the impurities of the local residents! With their abominations they have filled it from one end to the other with their filthiness.'
EXEC add_BibleVerse @BibleId, 115009012, N'Therefore do not give your daughters in marriage to their sons, and do not take their daughters in marriage for your sons. Do not ever seek their peace or welfare, so that you may be strong and may eat the good of the land and may leave it as an inheritance for your children forever.’'
EXEC add_BibleVerse @BibleId, 115009013, N'“Everything that has happened to us has come about because of our wicked actions and our great guilt. Even so, our God, you have exercised restraint toward our iniquities and have given us a remnant such as this.'
EXEC add_BibleVerse @BibleId, 115009014, N'Shall we once again break your commandments and intermarry with these abominable peoples? Would you not be so angered by us that you would wipe us out, with no survivor or remnant?'
EXEC add_BibleVerse @BibleId, 115009015, N'O Lord God of Israel, you are righteous, for we are left as a remnant this day. Indeed, we stand before you in our guilt. However, because of this guilt no one can really stand before you.”'
EXEC add_BibleVerse @BibleId, 115010001, N'While Ezra was praying and confessing, weeping and throwing himself to the ground before the temple of God, a very large crowd of Israelites – men, women, and children alike – gathered around him. The people wept loudly.'
EXEC add_BibleVerse @BibleId, 115010002, N'Then Shecaniah son of Jehiel, from the descendants of Elam, addressed Ezra: “We have been unfaithful to our God by marrying foreign women from the local peoples. Nonetheless, there is still hope for Israel in this regard.'
EXEC add_BibleVerse @BibleId, 115010003, N'Therefore let us enact a covenant with our God to send away all these women and their offspring, in keeping with your counsel, my lord, and that of those who respect the commandments of our God. And let it be done according to the law.'
EXEC add_BibleVerse @BibleId, 115010004, N'Get up, for this matter concerns you. We are with you, so be strong and act decisively!”'
EXEC add_BibleVerse @BibleId, 115010005, N'So Ezra got up and made the leading priests and Levites and all Israel take an oath to carry out this plan. And they all took a solemn oath.'
EXEC add_BibleVerse @BibleId, 115010006, N'Then Ezra got up from in front of the temple of God and went to the room of Jehohanan son of Eliashib. While he stayed there, he did not eat food or drink water, for he was in mourning over the infidelity of the exiles.'
EXEC add_BibleVerse @BibleId, 115010007, N'A proclamation was circulated throughout Judah and Jerusalem that all the exiles were to be assembled in Jerusalem.'
EXEC add_BibleVerse @BibleId, 115010008, N'Everyone who did not come within three days would thereby forfeit all his property, in keeping with the counsel of the officials and the elders. Furthermore, he himself would be excluded from the assembly of the exiles.'
EXEC add_BibleVerse @BibleId, 115010009, N'All the men of Judah and Benjamin were gathered in Jerusalem within the three days. (It was in the ninth month, on the twentieth day of that month.) All the people sat in the square at the temple of God, trembling because of this matter and because of the rains.'
EXEC add_BibleVerse @BibleId, 115010010, N'Then Ezra the priest stood up and said to them, “You have behaved in an unfaithful manner by taking foreign wives! This has contributed to the guilt of Israel.'
EXEC add_BibleVerse @BibleId, 115010011, N'Now give praise to the Lord God of your fathers, and do his will. Separate yourselves from the local residents and from these foreign wives.”'
EXEC add_BibleVerse @BibleId, 115010012, N'All the assembly replied in a loud voice: “We will do just as you have said!'
EXEC add_BibleVerse @BibleId, 115010013, N'However, the people are numerous and it is the rainy season. We are unable to stand here outside. Furthermore, this business cannot be resolved in a day or two, for we have sinned greatly in this matter.'
EXEC add_BibleVerse @BibleId, 115010014, N'Let our leaders take steps on behalf of all the assembly. Let all those in our towns who have married foreign women come at an appointed time, and with them the elders of each town and its judges, until the hot anger of our God is turned away from us in this matter.”'
EXEC add_BibleVerse @BibleId, 115010015, N'Only Jonathan son of Asahel and Jahzeiah son of Tikvah were against this, assisted by Meshullam and Shabbethai the Levite.'
EXEC add_BibleVerse @BibleId, 115010016, N'So the exiles proceeded accordingly. Ezra the priest separated out by name men who were leaders in their family groups. They sat down to consider this matter on the first day of the tenth month,'
EXEC add_BibleVerse @BibleId, 115010017, N'and on the first day of the first month they finished considering all the men who had married foreign wives.'
EXEC add_BibleVerse @BibleId, 115010018, N'It was determined that from the descendants of the priests, the following had taken foreign wives: from the descendants of Jeshua son of Jozadak, and his brothers: Maaseiah, Eliezer, Jarib, and Gedaliah.'
EXEC add_BibleVerse @BibleId, 115010019, N'(They gave their word to send away their wives; their guilt offering was a ram from the flock for their guilt.)'
EXEC add_BibleVerse @BibleId, 115010020, N'From the descendants of Immer: Hanani and Zebadiah.'
EXEC add_BibleVerse @BibleId, 115010021, N'From the descendants of Harim: Maaseiah, Elijah, Shemaiah, Jehiel, and Uzziah.'
EXEC add_BibleVerse @BibleId, 115010022, N'From the descendants of Pashhur: Elioenai, Maaseiah, Ishmael, Nethanel, Jozabad, and Elasah.'
EXEC add_BibleVerse @BibleId, 115010023, N'From the Levites: Jozabad, Shimei, Kelaiah (also known as Kelita), Pethahiah, Judah, and Eliezer.'
EXEC add_BibleVerse @BibleId, 115010024, N'From the singers: Eliashib. From the gatekeepers: Shallum, Telem, and Uri.'
EXEC add_BibleVerse @BibleId, 115010025, N'From the Israelites: from the descendants of Parosh: Ramiah, Izziah, Malkijah, Mijamin, Eleazar, Malkijah, and Benaiah.'
EXEC add_BibleVerse @BibleId, 115010026, N'From the descendants of Elam: Mattaniah, Zechariah, Jehiel, Abdi, Jeremoth, and Elijah.'
EXEC add_BibleVerse @BibleId, 115010027, N'From the descendants of Zattu: Elioenai, Eliashib, Mattaniah, Jeremoth, Zabad, and Aziza.'
EXEC add_BibleVerse @BibleId, 115010028, N'From the descendants of Bebai: Jehohanan, Hananiah, Zabbai, and Athlai.'
EXEC add_BibleVerse @BibleId, 115010029, N'From the descendants of Bani: Meshullam, Malluch, Adaiah, Jashub, Sheal, and Jeremoth.'
EXEC add_BibleVerse @BibleId, 115010030, N'From the descendants of Pahath-Moab: Adna, Kelal, Benaiah, Maaseiah, Mattaniah, Bezalel, Binnui, and Manasseh.'
EXEC add_BibleVerse @BibleId, 115010031, N'From the descendants of Harim: Eliezer, Ishijah, Malkijah, Shemaiah, Shimeon,'
EXEC add_BibleVerse @BibleId, 115010032, N'Benjamin, Malluch, and Shemariah.'
EXEC add_BibleVerse @BibleId, 115010033, N'From the descendants of Hashum: Mattenai, Mattattah, Zabad, Eliphelet, Jeremai, Manasseh, and Shimei.'
EXEC add_BibleVerse @BibleId, 115010034, N'From the descendants of Bani: Maadai, Amram, Uel,'
EXEC add_BibleVerse @BibleId, 115010035, N'Benaiah, Bedeiah, Keluhi,'
EXEC add_BibleVerse @BibleId, 115010036, N'Vaniah, Meremoth, Eliashib,'
EXEC add_BibleVerse @BibleId, 115010037, N'Mattaniah, Mattenai, and Jaasu.'
EXEC add_BibleVerse @BibleId, 115010038, N'From the descendants of Binnui: Shimei,'
EXEC add_BibleVerse @BibleId, 115010039, N'Shelemiah, Nathan, Adaiah,'
EXEC add_BibleVerse @BibleId, 115010040, N'Machnadebai, Shashai, Sharai,'
EXEC add_BibleVerse @BibleId, 115010041, N'Azarel, Shelemiah, Shemariah,'
EXEC add_BibleVerse @BibleId, 115010042, N'Shallum, Amariah, and Joseph.'
EXEC add_BibleVerse @BibleId, 115010043, N'From the descendants of Nebo: Jeiel, Mattithiah, Zabad, Zebina, Jaddai, Joel, and Benaiah.'
EXEC add_BibleVerse @BibleId, 115010044, N'All these had taken foreign wives, and some of them also had children by these women.'
EXEC add_BibleVerse @BibleId, 116001001, N'These are the words of Nehemiah son of Hacaliah: It so happened that in the month of Kislev, in the twentieth year, I was in Susa the citadel.'
EXEC add_BibleVerse @BibleId, 116001002, N'Hanani, who was one of my relatives, along with some of the men from Judah, came to me, and I asked them about the Jews who had escaped and had survived the exile, and about Jerusalem.'
EXEC add_BibleVerse @BibleId, 116001003, N'They said to me, “The remnant that remains from the exile there in the province are experiencing considerable adversity and reproach. The wall of Jerusalem lies breached, and its gates have been burned down!”'
EXEC add_BibleVerse @BibleId, 116001004, N'When I heard these things I sat down abruptly, crying and mourning for several days. I continued fasting and praying before the God of heaven.'
EXEC add_BibleVerse @BibleId, 116001005, N'Then I said, “Please, O LORD God of heaven, great and awesome God, who keeps his loving covenant with those who love him and obey his commandments,'
EXEC add_BibleVerse @BibleId, 116001006, N'may your ear be attentive and your eyes be open to hear the prayer of your servant that I am praying to you today throughout both day and night on behalf of your servants the Israelites. I am confessing the sins of the Israelites that we have committed against you – both I myself and my family have sinned.'
EXEC add_BibleVerse @BibleId, 116001007, N'We have behaved corruptly against you, not obeying the commandments, the statutes, and the judgments that you commanded your servant Moses.'
EXEC add_BibleVerse @BibleId, 116001008, N'Please recall the word you commanded your servant Moses: ‘If you act unfaithfully, I will scatter you among the nations.'
EXEC add_BibleVerse @BibleId, 116001009, N'But if you repent and obey my commandments and do them, then even if your dispersed people are in the most remote location, I will gather them from there and bring them to the place I have chosen for my name to reside.’'
EXEC add_BibleVerse @BibleId, 116001010, N'They are your servants and your people, whom you have redeemed by your mighty strength and by your powerful hand.'
EXEC add_BibleVerse @BibleId, 116001011, N'Please, O Lord, listen attentively to the prayer of your servant and to the prayer of your servants who take pleasure in showing respect to your name. Grant your servant success today and show compassion to me in the presence of this man.” Now I was cupbearer for the king.'
EXEC add_BibleVerse @BibleId, 116002001, N'Then in the month of Nisan, in the twentieth year of King Artaxerxes, when wine was brought to me, I took the wine and gave it to the king. Previously I had not been depressed in the king’s presence.'
EXEC add_BibleVerse @BibleId, 116002002, N'So the king said to me, “Why do you appear to be depressed when you aren’t sick? What can this be other than sadness of heart?” This made me very fearful.'
EXEC add_BibleVerse @BibleId, 116002003, N'I replied to the king, “O king, live forever! Why would I not appear dejected when the city with the graves of my ancestors lies desolate and its gates destroyed by fire?”'
EXEC add_BibleVerse @BibleId, 116002004, N'The king responded, “What is it you are seeking?” Then I quickly prayed to the God of heaven'
EXEC add_BibleVerse @BibleId, 116002005, N'and said to the king, “If the king is so inclined and if your servant has found favor in your sight, dispatch me to Judah, to the city with the graves of my ancestors, so that I can rebuild it.”'
EXEC add_BibleVerse @BibleId, 116002006, N'Then the king, with his consort sitting beside him, replied, “How long would your trip take, and when would you return?” Since the king was amenable to dispatching me, I gave him a time.'
EXEC add_BibleVerse @BibleId, 116002007, N'I said to the king, “If the king is so inclined, let him give me letters for the governors of Trans-Euphrates that will enable me to travel safely until I reach Judah,'
EXEC add_BibleVerse @BibleId, 116002008, N'and a letter for Asaph the keeper of the king’s nature preserve, so that he will give me timber for beams for the gates of the fortress adjacent to the temple and for the city wall and for the house to which I go.” So the king granted me these requests, for the good hand of my God was on me.'
EXEC add_BibleVerse @BibleId, 116002009, N'Then I went to the governors of Trans-Euphrates, and I presented to them the letters from the king. The king had sent with me officers of the army and horsemen.'
EXEC add_BibleVerse @BibleId, 116002010, N'When Sanballat the Horonite and Tobiah the Ammonite official heard all this, they were very displeased that someone had come to seek benefit for the Israelites.'
EXEC add_BibleVerse @BibleId, 116002011, N'So I came to Jerusalem. When I had been there for three days,'
EXEC add_BibleVerse @BibleId, 116002012, N'I got up during the night, along with a few men who were with me. But I did not tell anyone what my God was putting on my heart to do for Jerusalem. There were no animals with me, except for the one I was riding.'
EXEC add_BibleVerse @BibleId, 116002013, N'I proceeded through the Valley Gate by night, in the direction of the Well of the Dragons and the Dung Gate, inspecting the walls of Jerusalem that had been breached and its gates that had been destroyed by fire.'
EXEC add_BibleVerse @BibleId, 116002014, N'I passed on to the Gate of the Well and the King’s Pool, where there was not enough room for my animal to pass with me.'
EXEC add_BibleVerse @BibleId, 116002015, N'I continued up the valley during the night, inspecting the wall. Then I turned back and came to the Valley Gate, and so returned.'
EXEC add_BibleVerse @BibleId, 116002016, N'The officials did not know where I had gone or what I had been doing, for up to this point I had not told any of the Jews or the priests or the nobles or the officials or the rest of the workers.'
EXEC add_BibleVerse @BibleId, 116002017, N'Then I said to them, “You see the problem that we have: Jerusalem is desolate and its gates are burned. Come on! Let’s rebuild the wall of Jerusalem so that this reproach will not continue.”'
EXEC add_BibleVerse @BibleId, 116002018, N'Then I related to them how the good hand of my God was on me and what the king had said to me. Then they replied, “Let’s begin rebuilding right away!” So they readied themselves for this good project.'
EXEC add_BibleVerse @BibleId, 116002019, N'But when Sanballat the Horonite, Tobiah the Ammonite official, and Geshem the Arab heard all this, they derided us and expressed contempt toward us. They said, “What is this you are doing? Are you rebelling against the king?”'
EXEC add_BibleVerse @BibleId, 116002020, N'I responded to them by saying, “The God of heaven will prosper us. We his servants will start the rebuilding. But you have no just or ancient right in Jerusalem.”'
EXEC add_BibleVerse @BibleId, 116003001, N'Then Eliashib the high priest and his priestly colleagues arose and built the Sheep Gate. They dedicated it and erected its doors, working as far as the Tower of the Hundred and the Tower of Hananel.'
EXEC add_BibleVerse @BibleId, 116003002, N'The men of Jericho built adjacent to it, and Zaccur son of Imri built adjacent to them.'
EXEC add_BibleVerse @BibleId, 116003003, N'The sons of Hassenaah rebuilt the Fish Gate. They laid its beams and positioned its doors, its bolts, and its bars.'
EXEC add_BibleVerse @BibleId, 116003004, N'Meremoth son of Uriah, the son of Hakoz, worked on the section adjacent to them. Meshullam son of Berechiah the son of Meshezabel worked on the section next to them. And Zadok son of Baana worked on the section adjacent to them.'
EXEC add_BibleVerse @BibleId, 116003005, N'The men of Tekoa worked on the section adjacent to them, but their town leaders would not assist with the work of their master.'
EXEC add_BibleVerse @BibleId, 116003006, N'Joiada son of Paseah and Meshullam son of Besodeiah worked on the Jeshanah Gate. They laid its beams and positioned its doors, its bolts, and its bars.'
EXEC add_BibleVerse @BibleId, 116003007, N'Adjacent to them worked Melatiah the Gibeonite and Jadon the Meronothite, who were men of Gibeon and Mizpah. These towns were under the jurisdiction of the governor of Trans-Euphrates.'
EXEC add_BibleVerse @BibleId, 116003008, N'Uzziel son of Harhaiah, a member of the goldsmiths’ guild, worked on the section adjacent to him. Hananiah, a member of the perfumers’ guild, worked on the section adjacent to him. They plastered the city wall of Jerusalem as far as the Broad Wall.'
EXEC add_BibleVerse @BibleId, 116003009, N'Rephaiah son of Hur, head of a half-district of Jerusalem, worked on the section adjacent to them.'
EXEC add_BibleVerse @BibleId, 116003010, N'Jedaiah son of Harumaph worked on the section adjacent to them opposite his house, and Hattush son of Hashabneiah worked on the section adjacent to him.'
EXEC add_BibleVerse @BibleId, 116003011, N'Malkijah son of Harim and Hasshub son of Pahath-Moab worked on another section and the Tower of the Fire Pots.'
EXEC add_BibleVerse @BibleId, 116003012, N'Shallum son of Hallohesh, head of a half-district of Jerusalem, worked on the section adjacent to him, assisted by his daughters.'
EXEC add_BibleVerse @BibleId, 116003013, N'Hanun and the residents of Zanoah worked on the Valley Gate. They rebuilt it and positioned its doors, its bolts, and its bars, in addition to working on fifteen hundred feet of the wall as far as the Dung Gate.'
EXEC add_BibleVerse @BibleId, 116003014, N'Malkijah son of Recab, head of the district of Beth Hakkerem, worked on the Dung Gate. He rebuilt it and positioned its doors, its bolts, and its bars.'
EXEC add_BibleVerse @BibleId, 116003015, N'Shallun son of Col-Hozeh, head of the district of Mizpah, worked on the Fountain Gate. He rebuilt it, put on its roof, and positioned its doors, its bolts, and its bars. In addition, he rebuilt the wall of the Pool of Siloam, by the royal garden, as far as the steps that go down from the City of David.'
EXEC add_BibleVerse @BibleId, 116003016, N'Nehemiah son of Azbuk, head of a half-district of Beth Zur, worked after him as far as the tombs of David and the artificial pool and the House of the Warriors.'
EXEC add_BibleVerse @BibleId, 116003017, N'After him the Levites worked – Rehum son of Bani and after him Hashabiah, head of half the district of Keilah, for his district.'
EXEC add_BibleVerse @BibleId, 116003018, N'After him their relatives worked – Binnui son of Henadad, head of a half-district of Keilah.'
EXEC add_BibleVerse @BibleId, 116003019, N'Adjacent to him Ezer son of Jeshua, head of Mizpah, worked on another section, opposite the ascent to the armory at the buttress.'
EXEC add_BibleVerse @BibleId, 116003020, N'After him Baruch son of Zabbai worked on another section, from the buttress to the door of the house of Eliashib the high priest.'
EXEC add_BibleVerse @BibleId, 116003021, N'After him Meremoth son of Uriah, the son of Hakkoz, worked on another section from the door of Eliashib’s house to the end of it.'
EXEC add_BibleVerse @BibleId, 116003022, N'After him the priests worked, men of the nearby district.'
EXEC add_BibleVerse @BibleId, 116003023, N'After them Benjamin and Hasshub worked opposite their house. After them Azariah son of Maaseiah, the son of Ananiah, worked near his house.'
EXEC add_BibleVerse @BibleId, 116003024, N'After him Binnui son of Henadad worked on another section, from the house of Azariah to the buttress and the corner.'
EXEC add_BibleVerse @BibleId, 116003025, N'After him Palal son of Uzai worked opposite the buttress and the tower that protrudes from the upper palace of the court of the guard. After him Pedaiah son of Parosh'
EXEC add_BibleVerse @BibleId, 116003026, N'and the temple servants who were living on Ophel worked up to the area opposite the Water Gate toward the east and the protruding tower.'
EXEC add_BibleVerse @BibleId, 116003027, N'After them the men of Tekoa worked on another section, from opposite the great protruding tower to the wall of Ophel.'
EXEC add_BibleVerse @BibleId, 116003028, N'Above the Horse Gate the priests worked, each in front of his house.'
EXEC add_BibleVerse @BibleId, 116003029, N'After them Zadok son of Immer worked opposite his house, and after him Shemaiah son of Shecaniah, guard at the East Gate, worked.'
EXEC add_BibleVerse @BibleId, 116003030, N'After him Hananiah son of Shelemiah, and Hanun, the sixth son of Zalaph, worked on another section. After them Meshullam son of Berechiah worked opposite his quarters.'
EXEC add_BibleVerse @BibleId, 116003031, N'After him Malkijah, one of the goldsmiths, worked as far as the house of the temple servants and the traders, opposite the Inspection Gate, and up to the room above the corner.'
EXEC add_BibleVerse @BibleId, 116003032, N'And between the room above the corner and the Sheep Gate the goldsmiths and traders worked.'
EXEC add_BibleVerse @BibleId, 116004001, N'Now when Sanballat heard that we were rebuilding the wall he became angry and was quite upset. He derided the Jews,'
EXEC add_BibleVerse @BibleId, 116004002, N'and in the presence of his colleagues and the army of Samaria he said, “What are these feeble Jews doing? Will they be left to themselves? Will they again offer sacrifice? Will they finish this in a day? Can they bring these burnt stones to life again from piles of dust?”'
EXEC add_BibleVerse @BibleId, 116004003, N'Then Tobiah the Ammonite, who was close by, said, “If even a fox were to climb up on what they are building, it would break down their wall of stones!”'
EXEC add_BibleVerse @BibleId, 116004004, N'Hear, O our God, for we are despised! Return their reproach on their own head! Reduce them to plunder in a land of exile!'
EXEC add_BibleVerse @BibleId, 116004005, N'Do not cover their iniquity, and do not wipe out their sin from before them. For they have bitterly offended the builders!'
EXEC add_BibleVerse @BibleId, 116004006, N'So we rebuilt the wall, and the entire wall was joined together up to half its height. The people were enthusiastic in their work.'
EXEC add_BibleVerse @BibleId, 116004007, N'When Sanballat, Tobiah, the Arabs, the Ammonites, and the people of Ashdod heard that the restoration of the walls of Jerusalem had moved ahead and that the breaches had begun to be closed, they were very angry.'
EXEC add_BibleVerse @BibleId, 116004008, N'All of them conspired together to move with armed forces against Jerusalem and to create a disturbance in it.'
EXEC add_BibleVerse @BibleId, 116004009, N'So we prayed to our God and stationed a guard to protect against them both day and night.'
EXEC add_BibleVerse @BibleId, 116004010, N'Then those in Judah said, “The strength of the laborers has failed! The debris is so great that we are unable to rebuild the wall.”'
EXEC add_BibleVerse @BibleId, 116004011, N'Our adversaries also boasted, “Before they are aware or anticipate anything, we will come in among them and kill them, and we will bring this work to a halt!”'
EXEC add_BibleVerse @BibleId, 116004012, N'So it happened that the Jews who were living near them came and warned us repeatedly about all the schemes they were plotting against us.'
EXEC add_BibleVerse @BibleId, 116004013, N'So I stationed people at the lower places behind the wall in the exposed places. I stationed the people by families, with their swords, spears, and bows.'
EXEC add_BibleVerse @BibleId, 116004014, N'When I had made an inspection, I stood up and said to the nobles, the officials, and the rest of the people, “Don’t be afraid of them. Remember the great and awesome Lord, and fight on behalf of your brothers, your sons, your daughters, your wives, and your families!”'
EXEC add_BibleVerse @BibleId, 116004015, N'It so happened that when our adversaries heard that we were aware of these matters, God frustrated their intentions. Then all of us returned to the wall, each to his own work.'
EXEC add_BibleVerse @BibleId, 116004016, N'From that day forward, half of my men were doing the work and half of them were taking up spears, shields, bows, and body armor. Now the officers were behind all the people of Judah'
EXEC add_BibleVerse @BibleId, 116004017, N'who were rebuilding the wall. Those who were carrying loads did so by keeping one hand on the work and the other on their weapon.'
EXEC add_BibleVerse @BibleId, 116004018, N'The builders to a man had their swords strapped to their sides while they were building. But the trumpeter remained with me.'
EXEC add_BibleVerse @BibleId, 116004019, N'I said to the nobles, the officials, and the rest of the people, “The work is demanding and extensive, and we are spread out on the wall, far removed from one another.'
EXEC add_BibleVerse @BibleId, 116004020, N'Wherever you hear the sound of the trumpet, gather there with us. Our God will fight for us!”'
EXEC add_BibleVerse @BibleId, 116004021, N'So we worked on, with half holding spears, from dawn till dusk.'
EXEC add_BibleVerse @BibleId, 116004022, N'At that time I instructed the people, “Let every man and his coworker spend the night in Jerusalem and let them be guards for us by night and workers by day.'
EXEC add_BibleVerse @BibleId, 116004023, N'We did not change clothes – not I, nor my relatives, nor my workers, nor the watchmen who were with me. Each had his weapon, even when getting a drink of water.'
EXEC add_BibleVerse @BibleId, 116005001, N'Then there was a great outcry from the people and their wives against their fellow Jews.'
EXEC add_BibleVerse @BibleId, 116005002, N'There were those who said, “With our sons and daughters, we are many. We must obtain grain in order to eat and stay alive.”'
EXEC add_BibleVerse @BibleId, 116005003, N'There were others who said, “We are putting up our fields, our vineyards, and our houses as collateral in order to obtain grain during the famine.”'
EXEC add_BibleVerse @BibleId, 116005004, N'Then there were those who said, “We have borrowed money to pay our taxes to the king on our fields and our vineyards.'
EXEC add_BibleVerse @BibleId, 116005005, N'And now, though we share the same flesh and blood as our fellow countrymen, and our children are just like their children, still we have found it necessary to subject our sons and daughters to slavery. Some of our daughters have been subjected to slavery, while we are powerless to help, since our fields and vineyards now belong to other people.”'
EXEC add_BibleVerse @BibleId, 116005006, N'I was very angry when I heard their outcry and these complaints.'
EXEC add_BibleVerse @BibleId, 116005007, N'I considered these things carefully and then registered a complaint with the wealthy and the officials. I said to them, “Each one of you is seizing the collateral from your own countrymen!” Because of them I called for a great public assembly.'
EXEC add_BibleVerse @BibleId, 116005008, N'I said to them, “To the extent possible we have bought back our fellow Jews who had been sold to the Gentiles. But now you yourselves want to sell your own countrymen, so that we can then buy them back!” They were utterly silent, and could find nothing to say.'
EXEC add_BibleVerse @BibleId, 116005009, N'Then I said, “The thing that you are doing is wrong! Should you not conduct yourselves in the fear of our God in order to avoid the reproach of the Gentiles who are our enemies?'
EXEC add_BibleVerse @BibleId, 116005010, N'Even I and my relatives and my associates are lending them money and grain. But let us abandon this practice of seizing collateral!'
EXEC add_BibleVerse @BibleId, 116005011, N'This very day return to them their fields, their vineyards, their olive trees, and their houses, along with the interest that you are exacting from them on the money, the grain, the new wine, and the olive oil.”'
EXEC add_BibleVerse @BibleId, 116005012, N'They replied, “We will return these things, and we will no longer demand anything from them. We will do just as you say.” Then I called the priests and made the wealthy and the officials swear to do what had been promised.'
EXEC add_BibleVerse @BibleId, 116005013, N'I also shook out my garment, and I said, “In this way may God shake out from his house and his property every person who does not carry out this matter. In this way may he be shaken out and emptied!” All the assembly replied, “So be it!” and they praised the LORD. Then the people did as they had promised.'
EXEC add_BibleVerse @BibleId, 116005014, N'From the day that I was appointed governor in the land of Judah, that is, from the twentieth year until the thirty-second year of King Artaxerxes – twelve years in all – neither I nor my relatives ate the food allotted to the governor.'
EXEC add_BibleVerse @BibleId, 116005015, N'But the former governors who preceded me had burdened the people and had taken food and wine from them, in addition to forty shekels of silver. Their associates were also domineering over the people. But I did not behave in this way, due to my fear of God.'
EXEC add_BibleVerse @BibleId, 116005016, N'I gave myself to the work on this wall, without even purchasing a field. All my associates were gathered there for the work.'
EXEC add_BibleVerse @BibleId, 116005017, N'There were 150 Jews and officials who dined with me routinely, in addition to those who came to us from the nations all around us.'
EXEC add_BibleVerse @BibleId, 116005018, N'Every day one ox, six select sheep, and some birds were prepared for me, and every ten days all kinds of wine in abundance. Despite all this I did not require the food allotted to the governor, for the work was demanding on this people.'
EXEC add_BibleVerse @BibleId, 116005019, N'Please remember me for good, O my God, for all that I have done for this people.'
EXEC add_BibleVerse @BibleId, 116006001, N'When Sanballat, Tobiah, Geshem the Arab, and the rest of our enemies heard that I had rebuilt the wall and no breach remained in it (even though up to that time I had not positioned doors in the gates),'
EXEC add_BibleVerse @BibleId, 116006002, N'Sanballat and Geshem sent word to me saying, “Come on! Let’s set up a time to meet together at Kephirim in the plain of Ono.” Now they intended to do me harm.'
EXEC add_BibleVerse @BibleId, 116006003, N'So I sent messengers to them saying, “I am engaged in an important work, and I am unable to come down. Why should the work come to a halt when I leave it to come down to you?”'
EXEC add_BibleVerse @BibleId, 116006004, N'They contacted me four times in this way, and I responded the same way each time.'
EXEC add_BibleVerse @BibleId, 116006005, N'The fifth time that Sanballat sent his assistant to me in this way, he had an open letter in his hand.'
EXEC add_BibleVerse @BibleId, 116006006, N'Written in it were the following words: “Among the nations it is rumored (and Geshem has substantiated this) that you and the Jews have intentions of revolting, and for this reason you are building the wall. Furthermore, according to these rumors you are going to become their king.'
EXEC add_BibleVerse @BibleId, 116006007, N'You have also established prophets to announce in Jerusalem on your behalf, ‘We have a king in Judah!’ Now the king is going to hear about these rumors. So come on! Let’s talk about this.”'
EXEC add_BibleVerse @BibleId, 116006008, N'I sent word back to him, “We are not engaged in these activities you are describing. All of this is a figment of your imagination.”'
EXEC add_BibleVerse @BibleId, 116006009, N'All of them were wanting to scare us, supposing, “Their hands will grow slack from the work, and it won’t get done.” So now, strengthen my hands!'
EXEC add_BibleVerse @BibleId, 116006010, N'Then I went to the house of Shemaiah son of Delaiah, the son of Mehetabel. He was confined to his home. He said, “Let’s set up a time to meet in the house of God, within the temple. Let’s close the doors of the temple, for they are coming to kill you. It will surely be at night that they will come to kill you.”'
EXEC add_BibleVerse @BibleId, 116006011, N'But I replied, “Should a man like me run away? Would someone like me flee to the temple in order to save his life? I will not go!”'
EXEC add_BibleVerse @BibleId, 116006012, N'I recognized the fact that God had not sent him, for he had spoken the prophecy against me as a hired agent of Tobiah and Sanballat.'
EXEC add_BibleVerse @BibleId, 116006013, N'He had been hired to scare me so that I would do this and thereby sin. They would thus bring reproach on me and I would be discredited.'
EXEC add_BibleVerse @BibleId, 116006014, N'Remember, O my God, Tobiah and Sanballat in light of these actions of theirs – also Noadiah the prophetess and the other prophets who were trying to scare me!'
EXEC add_BibleVerse @BibleId, 116006015, N'So the wall was completed on the twenty-fifth day of Elul, in just fifty-two days.'
EXEC add_BibleVerse @BibleId, 116006016, N'When all our enemies heard and all the nations who were around us saw this, they were greatly disheartened. They knew that this work had been accomplished with the help of our God.'
EXEC add_BibleVerse @BibleId, 116006017, N'In those days the aristocrats of Judah repeatedly sent letters to Tobiah, and responses from Tobiah were repeatedly coming to them.'
EXEC add_BibleVerse @BibleId, 116006018, N'For many in Judah had sworn allegiance to him, because he was the son-in-law of Shecaniah son of Arah. His son Jonathan had married the daughter of Meshullam son of Berechiah.'
EXEC add_BibleVerse @BibleId, 116006019, N'They were telling me about his good deeds and then taking back to him the things I said. Tobiah, on the other hand, sent letters in order to scare me.'
EXEC add_BibleVerse @BibleId, 116007001, N'When the wall had been rebuilt and I had positioned the doors, and the gatekeepers, the singers, and the Levites had been appointed,'
EXEC add_BibleVerse @BibleId, 116007002, N'I then put in charge over Jerusalem my brother Hanani and Hananiah the chief of the citadel, for he was a faithful man and feared God more than many do.'
EXEC add_BibleVerse @BibleId, 116007003, N'I said to them, “The gates of Jerusalem must not be opened in the early morning, until those who are standing guard close the doors and lock them. Position residents of Jerusalem as guards, some at their guard stations and some near their homes.”'
EXEC add_BibleVerse @BibleId, 116007004, N'Now the city was spread out and large, and there were not a lot of people in it. At that time houses had not been rebuilt.'
EXEC add_BibleVerse @BibleId, 116007005, N'My God placed it on my heart to gather the leaders, the officials, and the ordinary people so they could be enrolled on the basis of genealogy. I found the genealogical records of those who had formerly returned. Here is what I found written in that record:'
EXEC add_BibleVerse @BibleId, 116007006, N'These are the people of the province who returned from the captivity of the exiles, whom King Nebuchadnezzar of Babylon had forced into exile. They returned to Jerusalem and to Judah, each to his own city.'
EXEC add_BibleVerse @BibleId, 116007007, N'They came with Zerubbabel, Jeshua, Nehemiah, Azariah, Raamiah, Nahamani, Mordecai, Bilshan, Mispereth, Bigvai, Nehum, and Baanah. The number of Israelite men was as follows:'
EXEC add_BibleVerse @BibleId, 116007008, N'the descendants of Parosh, 2,172;'
EXEC add_BibleVerse @BibleId, 116007009, N'the descendants of Shephatiah, 372;'
EXEC add_BibleVerse @BibleId, 116007010, N'the descendants of Arah, 652;'
EXEC add_BibleVerse @BibleId, 116007011, N'the descendants of Pahath-Moab (from the line of Jeshua and Joab), 2,818;'
EXEC add_BibleVerse @BibleId, 116007012, N'the descendants of Elam, 1,254;'
EXEC add_BibleVerse @BibleId, 116007013, N'the descendants of Zattu, 845;'
EXEC add_BibleVerse @BibleId, 116007014, N'the descendants of Zaccai, 760;'
EXEC add_BibleVerse @BibleId, 116007015, N'the descendants of Binnui, 648;'
EXEC add_BibleVerse @BibleId, 116007016, N'the descendants of Bebai, 628;'
EXEC add_BibleVerse @BibleId, 116007017, N'the descendants of Azgad, 2,322;'
EXEC add_BibleVerse @BibleId, 116007018, N'the descendants of Adonikam, 667;'
EXEC add_BibleVerse @BibleId, 116007019, N'the descendants of Bigvai, 2,067;'
EXEC add_BibleVerse @BibleId, 116007020, N'the descendants of Adin, 655;'
EXEC add_BibleVerse @BibleId, 116007021, N'the descendants of Ater (through Hezekiah), 98;'
EXEC add_BibleVerse @BibleId, 116007022, N'the descendants of Hashum, 328;'
EXEC add_BibleVerse @BibleId, 116007023, N'the descendants of Bezai, 324;'
EXEC add_BibleVerse @BibleId, 116007024, N'the descendants of Harif, 112;'
EXEC add_BibleVerse @BibleId, 116007025, N'the descendants of Gibeon, 95;'
EXEC add_BibleVerse @BibleId, 116007026, N'The men of Bethlehem and Netophah, 188;'
EXEC add_BibleVerse @BibleId, 116007027, N'the men of Anathoth, 128;'
EXEC add_BibleVerse @BibleId, 116007028, N'the men of the family of Azmaveth, 42;'
EXEC add_BibleVerse @BibleId, 116007029, N'the men of Kiriath Jearim, Kephirah, and Beeroth, 743;'
EXEC add_BibleVerse @BibleId, 116007030, N'the men of Ramah and Geba, 621;'
EXEC add_BibleVerse @BibleId, 116007031, N'the men of Micmash, 122;'
EXEC add_BibleVerse @BibleId, 116007032, N'the men of Bethel and Ai, 123;'
EXEC add_BibleVerse @BibleId, 116007033, N'the men of the other Nebo, 52;'
EXEC add_BibleVerse @BibleId, 116007034, N'the descendants of the other Elam, 1,254;'
EXEC add_BibleVerse @BibleId, 116007035, N'the descendants of Harim, 320;'
EXEC add_BibleVerse @BibleId, 116007036, N'the descendants of Jericho, 345;'
EXEC add_BibleVerse @BibleId, 116007037, N'the descendants of Lod, Hadid, and Ono, 721;'
EXEC add_BibleVerse @BibleId, 116007038, N'the descendants of Senaah, 3,930.'
EXEC add_BibleVerse @BibleId, 116007039, N'The priests: the descendants of Jedaiah (through the family of Jeshua), 973;'
EXEC add_BibleVerse @BibleId, 116007040, N'the descendants of Immer, 1,052;'
EXEC add_BibleVerse @BibleId, 116007041, N'the descendants of Pashhur, 1,247;'
EXEC add_BibleVerse @BibleId, 116007042, N'the descendants of Harim, 1,017.'
EXEC add_BibleVerse @BibleId, 116007043, N'The Levites: the descendants of Jeshua (through Kadmiel, through the line of Hodaviah), 74.'
EXEC add_BibleVerse @BibleId, 116007044, N'The singers: the descendants of Asaph, 148.'
EXEC add_BibleVerse @BibleId, 116007045, N'The gatekeepers: the descendants of Shallum, the descendants of Ater, the descendants of Talmon, the descendants of Akkub, the descendants of Hatita, and the descendants of Shobai, 138.'
EXEC add_BibleVerse @BibleId, 116007046, N'The temple servants: the descendants of Ziha, the descendants of Hasupha, the descendants of Tabbaoth,'
EXEC add_BibleVerse @BibleId, 116007047, N'the descendants of Keros, the descendants of Sia, the descendants of Padon,'
EXEC add_BibleVerse @BibleId, 116007048, N'the descendants of Lebanah, the descendants of Hagabah, the descendants of Shalmai,'
EXEC add_BibleVerse @BibleId, 116007049, N'the descendants of Hanan, the descendants of Giddel, the descendants of Gahar,'
EXEC add_BibleVerse @BibleId, 116007050, N'the descendants of Reaiah, the descendants of Rezin, the descendants of Nekoda,'
EXEC add_BibleVerse @BibleId, 116007051, N'the descendants of Gazzam, the descendants of Uzzah, the descendants of Paseah,'
EXEC add_BibleVerse @BibleId, 116007052, N'the descendants of Besai, the descendants of Meunim, the descendants of Nephussim,'
EXEC add_BibleVerse @BibleId, 116007053, N'the descendants of Bakbuk, the descendants of Hakupha, the descendants of Harhur,'
EXEC add_BibleVerse @BibleId, 116007054, N'the descendants of Bazluth, the descendants of Mehida, the descendants of Harsha,'
EXEC add_BibleVerse @BibleId, 116007055, N'the descendants of Barkos, the descendants of Sisera, the descendants of Temah,'
EXEC add_BibleVerse @BibleId, 116007056, N'the descendants of Neziah, the descendants of Hatipha.'
EXEC add_BibleVerse @BibleId, 116007057, N'The descendants of the servants of Solomon: the descendants of Sotai, the descendants of Sophereth, the descendants of Perida,'
EXEC add_BibleVerse @BibleId, 116007058, N'the descendants of Jaala, the descendants of Darkon, the descendants of Giddel,'
EXEC add_BibleVerse @BibleId, 116007059, N'the descendants of Shephatiah, the descendants of Hattil, the descendants of Pokereth-Hazzebaim, and the descendants of Amon.'
EXEC add_BibleVerse @BibleId, 116007060, N'All the temple servants and the descendants of the servants of Solomon, 392.'
EXEC add_BibleVerse @BibleId, 116007061, N'These are the ones who came up from Tel Melah, Tel Harsha, Kerub, Addon, and Immer (although they were unable to certify their family connection or their ancestry, as to whether they were really from Israel):'
EXEC add_BibleVerse @BibleId, 116007062, N'the descendants of Delaiah, the descendants of Tobiah, and the descendants of Nekoda, 642.'
EXEC add_BibleVerse @BibleId, 116007063, N'And from among the priests: the descendants of Hobaiah, the descendants of Hakkoz, and the descendants of Barzillai (who had married a woman from the daughters of Barzillai the Gileadite and was called by that name).'
EXEC add_BibleVerse @BibleId, 116007064, N'They searched for their records in the genealogical materials, but none were found. They were therefore excluded from the priesthood.'
EXEC add_BibleVerse @BibleId, 116007065, N'The governor instructed them not to eat any of the sacred food until there was a priest who could consult the Urim and Thummim.'
EXEC add_BibleVerse @BibleId, 116007066, N'The entire group numbered 42,360,'
EXEC add_BibleVerse @BibleId, 116007067, N'not counting their 7,337 male and female servants. They also had 245 male and female singers.'
EXEC add_BibleVerse @BibleId, 116007068, N'They had 736 horses, 245 mules,'
EXEC add_BibleVerse @BibleId, 116007069, N'435 camels, and 6,720 donkeys.'
EXEC add_BibleVerse @BibleId, 116007070, N'Some of the family leaders contributed to the work. The governor contributed to the treasury 1,000 gold drachmas, 50 bowls, and 530 priestly garments.'
EXEC add_BibleVerse @BibleId, 116007071, N'Some of the family leaders gave to the project treasury 20,000 gold drachmas and 2,200 silver minas.'
EXEC add_BibleVerse @BibleId, 116007072, N'What the rest of the people gave amounted to 20,000 gold drachmas, 2,000 silver minas, and 67 priestly garments.'
EXEC add_BibleVerse @BibleId, 116007073, N'The priests, the Levites, the gatekeepers, the singers, some of the people, the temple servants, and all the rest of Israel lived in their cities. When the seventh month arrived and the Israelites were settled in their cities,'
EXEC add_BibleVerse @BibleId, 116008001, N'all the people gathered together in the plaza which was in front of the Water Gate. They asked Ezra the scribe to bring the book of the law of Moses which the LORD had commanded Israel.'
EXEC add_BibleVerse @BibleId, 116008002, N'So Ezra the priest brought the law before the assembly which included men and women and all those able to understand what they heard. (This happened on the first day of the seventh month.)'
EXEC add_BibleVerse @BibleId, 116008003, N'So he read it before the plaza in front of the Water Gate from dawn till noon before the men and women and those children who could understand. All the people were eager to hear the book of the law.'
EXEC add_BibleVerse @BibleId, 116008004, N'Ezra the scribe stood on a towering wooden platform constructed for this purpose. Standing near him on his right were Mattithiah, Shema, Anaiah, Uriah, Hilkiah, and Masseiah. On his left were Pedaiah, Mishael, Malkijah, Hashum, Hashbaddanah, Zechariah, and Meshullam.'
EXEC add_BibleVerse @BibleId, 116008005, N'Ezra opened the book in plain view of all the people, for he was elevated above all the people. When he opened the book, all the people stood up.'
EXEC add_BibleVerse @BibleId, 116008006, N'Ezra blessed the LORD, the great God, and all the people replied “Amen! Amen!” as they lifted their hands. Then they bowed down and worshiped the LORD with their faces to the ground.'
EXEC add_BibleVerse @BibleId, 116008007, N'Jeshua, Bani, Sherebiah, Jamin, Akkub, Shabbethai, Hodiah, Maaseiah, Kelita, Azariah, Jozabad, Hanan, and Pelaiah – all of whom were Levites – were teaching the people the law, as the people remained standing.'
EXEC add_BibleVerse @BibleId, 116008008, N'They read from the book of God’s law, explaining it and imparting insight. Thus the people gained understanding from what was read.'
EXEC add_BibleVerse @BibleId, 116008009, N'Then Nehemiah the governor, Ezra the priestly scribe, and the Levites who were imparting understanding to the people said to all of them, “This day is holy to the LORD your God. Do not mourn or weep.” For all the people had been weeping when they heard the words of the law.'
EXEC add_BibleVerse @BibleId, 116008010, N'He said to them, “Go and eat delicacies and drink sweet drinks and send portions to those for whom nothing is prepared. For this day is holy to our Lord. Do not grieve, for the joy of the LORD is your strength.”'
EXEC add_BibleVerse @BibleId, 116008011, N'Then the Levites quieted all the people saying, “Be quiet, for this day is holy. Do not grieve.”'
EXEC add_BibleVerse @BibleId, 116008012, N'So all the people departed to eat and drink and to share their food with others and to enjoy tremendous joy, for they had gained insight in the matters that had been made known to them.'
EXEC add_BibleVerse @BibleId, 116008013, N'On the second day of the month the family leaders met with Ezra the scribe, together with all the people, the priests, and the Levites, to consider the words of the law.'
EXEC add_BibleVerse @BibleId, 116008014, N'They discovered written in the law that the LORD had commanded through Moses that the Israelites should live in temporary shelters during the festival of the seventh month,'
EXEC add_BibleVerse @BibleId, 116008015, N'and that they should make a proclamation and disseminate this message in all their cities and in Jerusalem: “Go to the hill country and bring back olive branches and branches of wild olive trees, myrtle trees, date palms, and other leafy trees to construct temporary shelters, as it is written.”'
EXEC add_BibleVerse @BibleId, 116008016, N'So the people went out and brought these things back and constructed temporary shelters for themselves, each on his roof and in his courtyard and in the courtyards of the temple of God and in the plaza of the Water Gate and the plaza of the Ephraim Gate.'
EXEC add_BibleVerse @BibleId, 116008017, N'So all the assembly which had returned from the exile constructed temporary shelters and lived in them. The Israelites had not done so from the days of Joshua son of Nun until that day. Everyone experienced very great joy.'
EXEC add_BibleVerse @BibleId, 116008018, N'Ezra read in the book of the law of God day by day, from the first day to the last. They observed the festival for seven days, and on the eighth day they held an assembly as was required.'
EXEC add_BibleVerse @BibleId, 116009001, N'On the twenty-fourth day of this same month the Israelites assembled; they were fasting and wearing sackcloth, their heads covered with dust.'
EXEC add_BibleVerse @BibleId, 116009002, N'Those truly of Israelite descent separated from all the foreigners, standing and confessing their sins and the iniquities of their ancestors.'
EXEC add_BibleVerse @BibleId, 116009003, N'For one-fourth of the day they stood in their place and read from the book of the law of the LORD their God, and for another fourth they were confessing their sins and worshiping the LORD their God.'
EXEC add_BibleVerse @BibleId, 116009004, N'Then the Levites – Jeshua, Binnui, Kadmiel, Shebaniah, Bunni, Sherebiah, Bani, and Kenani – stood on the steps and called out loudly to the LORD their God.'
EXEC add_BibleVerse @BibleId, 116009005, N'The Levites – Jeshua, Kadmiel, Bani, Hashabneiah, Sherebiah, Hodiah, Shebaniah, and Pethahiah – said, “Stand up and bless the LORD your God!” “May you be blessed, O LORD our God, from age to age. May your glorious name be blessed; may it be lifted up above all blessing and praise.'
EXEC add_BibleVerse @BibleId, 116009006, N'You alone are the LORD. You made the heavens, even the highest heavens, along with all their multitude of stars, the earth and all that is on it, the seas and all that is in them. You impart life to them all, and the multitudes of heaven worship you.'
EXEC add_BibleVerse @BibleId, 116009007, N'“You are the LORD God who chose Abram and brought him forth from Ur of the Chaldeans. You changed his name to Abraham.'
EXEC add_BibleVerse @BibleId, 116009008, N'When you perceived that his heart was faithful toward you, you established a covenant with him to give his descendants the land of the Canaanites, the Hittites, the Amorites, the Perizzites, the Jebusites, and the Girgashites. You have fulfilled your promise, for you are righteous.'
EXEC add_BibleVerse @BibleId, 116009009, N'“You saw the affliction of our ancestors in Egypt, and you heard their cry at the Red Sea.'
EXEC add_BibleVerse @BibleId, 116009010, N'You performed awesome signs against Pharaoh, against his servants, and against all the people of his land, for you knew that the Egyptians had acted presumptuously against them. You made for yourself a name that is celebrated to this day.'
EXEC add_BibleVerse @BibleId, 116009011, N'You split the sea before them, and they crossed through the sea on dry ground! But you threw their pursuers into the depths, like a stone into surging waters.'
EXEC add_BibleVerse @BibleId, 116009012, N'You guided them with a pillar of cloud by day and with a pillar of fire by night to illumine for them the path they were to travel.'
EXEC add_BibleVerse @BibleId, 116009013, N'“You came down on Mount Sinai and spoke with them from heaven. You provided them with just judgments, true laws, and good statutes and commandments.'
EXEC add_BibleVerse @BibleId, 116009014, N'You made known to them your holy Sabbath; you issued commandments, statutes, and law to them through Moses your servant.'
EXEC add_BibleVerse @BibleId, 116009015, N'You provided bread from heaven for them in their time of hunger, and you brought forth water from the rock for them in their time of thirst. You told them to enter in order to possess the land that you had sworn to give them.'
EXEC add_BibleVerse @BibleId, 116009016, N'“But they – our ancestors – behaved presumptuously; they rebelled and did not obey your commandments.'
EXEC add_BibleVerse @BibleId, 116009017, N'They refused to obey and did not recall your miracles that you had performed among them. Instead, they rebelled and appointed a leader to return to their bondage in Egypt. But you are a God of forgiveness, merciful and compassionate, slow to get angry and unfailing in your loyal love. You did not abandon them,'
EXEC add_BibleVerse @BibleId, 116009018, N'even when they made a cast image of a calf for themselves and said, ‘This is your God who brought you up from Egypt,’ or when they committed atrocious blasphemies.'
EXEC add_BibleVerse @BibleId, 116009019, N'“Due to your great compassion you did not abandon them in the desert. The pillar of cloud did not stop guiding them in the path by day, nor did the pillar of fire stop illuminating for them by night the path on which they should travel.'
EXEC add_BibleVerse @BibleId, 116009020, N'You imparted your good Spirit to instruct them. You did not withhold your manna from their mouths; you provided water for their thirst.'
EXEC add_BibleVerse @BibleId, 116009021, N'For forty years you sustained them. Even in the desert they never lacked anything. Their clothes did not wear out and their feet did not swell.'
EXEC add_BibleVerse @BibleId, 116009022, N'“You gave them kingdoms and peoples, and you allocated them to every corner of the land. They inherited the land of King Sihon of Heshbon and the land of King Og of Bashan.'
EXEC add_BibleVerse @BibleId, 116009023, N'You multiplied their descendants like the stars of the sky. You brought them to the land you had told their ancestors to enter in order to possess.'
EXEC add_BibleVerse @BibleId, 116009024, N'Their descendants entered and possessed the land. You subdued before them the Canaanites who were the inhabitants of the land. You delivered them into their hand, together with their kings and the peoples of the land, to deal with as they pleased.'
EXEC add_BibleVerse @BibleId, 116009025, N'They captured fortified cities and fertile land. They took possession of houses full of all sorts of good things – wells previously dug, vineyards, olive trees, and fruit trees in abundance. They ate until they were full and grew fat. They enjoyed to the full your great goodness.'
EXEC add_BibleVerse @BibleId, 116009026, N'“Nonetheless they grew disobedient and rebelled against you; they disregarded your law. They killed your prophets who had solemnly admonished them in order to cause them to return to you. They committed atrocious blasphemies.'
EXEC add_BibleVerse @BibleId, 116009027, N'Therefore you delivered them into the hand of their adversaries, who oppressed them. But in the time of their distress they called to you, and you heard from heaven. In your abundant compassion you provided them with deliverers to rescue them from their adversaries.'
EXEC add_BibleVerse @BibleId, 116009028, N'“Then, when they were at rest again, they went back to doing evil before you. Then you abandoned them to their enemies, and they gained dominion over them. When they again cried out to you, in your compassion you heard from heaven and rescued them time and again.'
EXEC add_BibleVerse @BibleId, 116009029, N'And you solemnly admonished them in order to return them to your law, but they behaved presumptuously and did not obey your commandments. They sinned against your ordinances – those by which an individual, if he obeys them, will live. They boldly turned from you; they rebelled and did not obey.'
EXEC add_BibleVerse @BibleId, 116009030, N'You prolonged your kindness with them for many years, and you solemnly admonished them by your Spirit through your prophets. Still they paid no attention, so you delivered them into the hands of the neighboring peoples.'
EXEC add_BibleVerse @BibleId, 116009031, N'However, due to your abundant mercy you did not do away with them altogether; you did not abandon them. For you are a merciful and compassionate God.'
EXEC add_BibleVerse @BibleId, 116009032, N'“So now, our God – the great, powerful, and awesome God, who keeps covenant fidelity – do not regard as inconsequential all the hardship that has befallen us – our kings, our leaders, our priests, our prophets, our ancestors, and all your people – from the days of the kings of Assyria until this very day!'
EXEC add_BibleVerse @BibleId, 116009033, N'You are righteous with regard to all that has happened to us, for you have acted faithfully. It is we who have been in the wrong!'
EXEC add_BibleVerse @BibleId, 116009034, N'Our kings, our leaders, our priests, and our ancestors have not kept your law. They have not paid attention to your commandments or your testimonies by which you have solemnly admonished them.'
EXEC add_BibleVerse @BibleId, 116009035, N'Even when they were in their kingdom and benefiting from your incredible goodness that you had lavished on them in the spacious and fertile land you had set before them, they did not serve you, nor did they turn from their evil practices.'
EXEC add_BibleVerse @BibleId, 116009036, N'“So today we are slaves! In the very land you gave to our ancestors to eat its fruit and to enjoy its good things – we are slaves!'
EXEC add_BibleVerse @BibleId, 116009037, N'Its abundant produce goes to the kings you have placed over us due to our sins. They rule over our bodies and our livestock as they see fit, and we are in great distress!'
EXEC add_BibleVerse @BibleId, 116009038, N'“Because of all of this we are entering into a binding covenant in written form; our leaders, our Levites, and our priests have affixed their names on the sealed document.”'
EXEC add_BibleVerse @BibleId, 116010001, N'On the sealed documents were the following names: Nehemiah the governor, son of Hacaliah, along with Zedekiah,'
EXEC add_BibleVerse @BibleId, 116010002, N'Seraiah, Azariah, Jeremiah,'
EXEC add_BibleVerse @BibleId, 116010003, N'Pashhur, Amariah, Malkijah,'
EXEC add_BibleVerse @BibleId, 116010004, N'Hattush, Shebaniah, Malluch,'
EXEC add_BibleVerse @BibleId, 116010005, N'Harim, Meremoth, Obadiah,'
EXEC add_BibleVerse @BibleId, 116010006, N'Daniel, Ginnethon, Baruch,'
EXEC add_BibleVerse @BibleId, 116010007, N'Meshullam, Abijah, Mijamin,'
EXEC add_BibleVerse @BibleId, 116010008, N'Maaziah, Bilgai, and Shemaiah. These were the priests.'
EXEC add_BibleVerse @BibleId, 116010009, N'The Levites were as follows: Jeshua son of Azaniah, Binnui of the sons of Henadad, Kadmiel.'
EXEC add_BibleVerse @BibleId, 116010010, N'Their colleagues were as follows: Shebaniah, Hodiah, Kelita, Pelaiah, Hanan,'
EXEC add_BibleVerse @BibleId, 116010011, N'Mica, Rehob, Hashabiah,'
EXEC add_BibleVerse @BibleId, 116010012, N'Zaccur, Sherebiah, Shebaniah,'
EXEC add_BibleVerse @BibleId, 116010013, N'Hodiah, Bani, and Beninu.'
EXEC add_BibleVerse @BibleId, 116010014, N'The leaders of the people were as follows: Parosh, Pahath-Moab, Elam, Zattu, Bani,'
EXEC add_BibleVerse @BibleId, 116010015, N'Bunni, Azgad, Bebai,'
EXEC add_BibleVerse @BibleId, 116010016, N'Adonijah, Bigvai, Adin,'
EXEC add_BibleVerse @BibleId, 116010017, N'Ater, Hezekiah, Azzur,'
EXEC add_BibleVerse @BibleId, 116010018, N'Hodiah, Hashum, Bezai,'
EXEC add_BibleVerse @BibleId, 116010019, N'Hariph, Anathoth, Nebai,'
EXEC add_BibleVerse @BibleId, 116010020, N'Magpiash, Meshullam, Hezir,'
EXEC add_BibleVerse @BibleId, 116010021, N'Meshezabel, Zadok, Jaddua,'
EXEC add_BibleVerse @BibleId, 116010022, N'Pelatiah, Hanan, Anaiah,'
EXEC add_BibleVerse @BibleId, 116010023, N'Hoshea, Hananiah, Hasshub,'
EXEC add_BibleVerse @BibleId, 116010024, N'Hallohesh, Pilha, Shobek,'
EXEC add_BibleVerse @BibleId, 116010025, N'Rehum, Hashabnah, Maaseiah,'
EXEC add_BibleVerse @BibleId, 116010026, N'Ahiah, Hanan, Anan,'
EXEC add_BibleVerse @BibleId, 116010027, N'Malluch, Harim, and Baanah.'
EXEC add_BibleVerse @BibleId, 116010028, N'“Now the rest of the people – the priests, the Levites, the gatekeepers, the singers, the temple attendants, and all those who have separated themselves from the neighboring peoples because of the law of God, along with their wives, their sons, and their daughters, all of whom are able to understand –'
EXEC add_BibleVerse @BibleId, 116010029, N'hereby participate with their colleagues the town leaders and enter into a curse and an oath to adhere to the law of God which was given through Moses the servant of God, and to obey carefully all the commandments of the LORD our Lord, along with his ordinances and his statutes.'
EXEC add_BibleVerse @BibleId, 116010030, N'“We will not give our daughters in marriage to the neighboring peoples, and we will not take their daughters in marriage for our sons.'
EXEC add_BibleVerse @BibleId, 116010031, N'We will not buy on the Sabbath or on a holy day from the neighboring peoples who bring their wares and all kinds of grain to sell on the Sabbath day. We will let the fields lie fallow every seventh year, and we will cancel every loan.'
EXEC add_BibleVerse @BibleId, 116010032, N'We accept responsibility for fulfilling the commands to give one third of a shekel each year for the work of the temple of our God,'
EXEC add_BibleVerse @BibleId, 116010033, N'for the loaves of presentation and for the regular grain offerings and regular burnt offerings, for the Sabbaths, for the new moons, for the appointed meetings, for the holy offerings, for the sin offerings to make atonement for Israel, and for all the work of the temple of our God.'
EXEC add_BibleVerse @BibleId, 116010034, N'“We – the priests, the Levites, and the people – have cast lots concerning the wood offerings, to bring them to the temple of our God according to our families at the designated times year by year to burn on the altar of the LORD our God, as is written in the law.'
EXEC add_BibleVerse @BibleId, 116010035, N'We also accept responsibility for bringing the first fruits of our land and the first fruits of every fruit tree year by year to the temple of the LORD.'
EXEC add_BibleVerse @BibleId, 116010036, N'We also accept responsibility, as is written in the law, for bringing the firstborn of our sons and our cattle and the firstborn of our herds and of our flocks to the temple of our God, to the priests who are ministering in the temple of our God.'
EXEC add_BibleVerse @BibleId, 116010037, N'We will also bring the first of our coarse meal, of our contributions, of the fruit of every tree, of new wine, and of olive oil to the priests at the storerooms of the temple of our God, along with a tenth of the produce of our land to the Levites, for the Levites are the ones who collect the tithes in all the cities where we work.'
EXEC add_BibleVerse @BibleId, 116010038, N'A priest of Aaron’s line will be with the Levites when the Levites collect the tithes, and the Levites will bring up a tenth of the tithes to the temple of our God, to the storerooms of the treasury.'
EXEC add_BibleVerse @BibleId, 116010039, N'The Israelites and the Levites will bring the contribution of the grain, the new wine, and the olive oil to the storerooms where the utensils of the sanctuary are kept, and where the priests who minister stay, along with the gatekeepers and the singers. We will not neglect the temple of our God.”'
EXEC add_BibleVerse @BibleId, 116011001, N'So the leaders of the people settled in Jerusalem, while the rest of the people cast lots to bring one out of every ten to settle in Jerusalem, the holy city, while the other nine remained in other cities.'
EXEC add_BibleVerse @BibleId, 116011002, N'The people gave their blessing on all the men who volunteered to settle in Jerusalem.'
EXEC add_BibleVerse @BibleId, 116011003, N'These are the provincial leaders who settled in Jerusalem. (While other Israelites, the priests, the Levites, the temple attendants, and the sons of the servants of Solomon settled in the cities of Judah, each on his own property in their cities,'
EXEC add_BibleVerse @BibleId, 116011004, N'some of the descendants of Judah and some of the descendants of Benjamin settled in Jerusalem.) Of the descendants of Judah: Athaiah son of Uzziah, the son of Zechariah, the son of Amariah, the son of Shephatiah, the son of Mahalalel, from the descendants of Perez;'
EXEC add_BibleVerse @BibleId, 116011005, N'and Maaseiah son of Baruch, the son of Col-Hozeh, the son of Hazaiah, the son of Adaiah, the son of Joiarib, the son of Zechariah, from the descendants of Shelah.'
EXEC add_BibleVerse @BibleId, 116011006, N'The sum total of the descendants of Perez who were settling in Jerusalem was 468 exceptional men.'
EXEC add_BibleVerse @BibleId, 116011007, N'These are the descendants of Benjamin: Sallu son of Meshullam, the son of Joed, the son of Pedaiah, the son of Kolaiah, the son of Maaseiah, the son of Ithiel, the son of Jeshaiah,'
EXEC add_BibleVerse @BibleId, 116011008, N'and his followers, Gabbai and Sallai – 928 in all.'
EXEC add_BibleVerse @BibleId, 116011009, N'Joel son of Zicri was the officer in charge of them, and Judah son of Hassenuah was second-in-command over the city.'
EXEC add_BibleVerse @BibleId, 116011010, N'From the priests: Jedaiah son of Joiarib, Jakin,'
EXEC add_BibleVerse @BibleId, 116011011, N'Seraiah son of Hilkiah, the son of Meshullam, the son of Zadok, the son of Meraioth, the son of Ahitub, supervisor in the temple of God,'
EXEC add_BibleVerse @BibleId, 116011012, N'and their colleagues who were carrying out work for the temple – 822; and Adaiah son of Jeroham, the son of Pelaliah, the son of Amzi, the son of Zechariah, the son of Pashhur, the son of Malkijah,'
EXEC add_BibleVerse @BibleId, 116011013, N'and his colleagues who were heads of families – 242; and Amashsai son of Azarel, the son of Ahzai, the son of Meshillemoth, the son of Immer,'
EXEC add_BibleVerse @BibleId, 116011014, N'and his colleagues who were exceptional men – 128. The officer over them was Zabdiel the son of Haggedolim.'
EXEC add_BibleVerse @BibleId, 116011015, N'From the Levites: Shemaiah son of Hasshub, the son of Azrikam, the son of Hashabiah, the son of Bunni;'
EXEC add_BibleVerse @BibleId, 116011016, N'Shabbethai and Jozabad, leaders of the Levites, were in charge of the external work for the temple of God;'
EXEC add_BibleVerse @BibleId, 116011017, N'Mattaniah son of Mica, the son of Zabdi, the son of Asaph, the praise leader who led in thanksgiving and prayer; Bakbukiah, second among his colleagues; and Abda son of Shammua, the son of Galal, the son of Jeduthun.'
EXEC add_BibleVerse @BibleId, 116011018, N'The sum total of the Levites in the holy city was 284.'
EXEC add_BibleVerse @BibleId, 116011019, N'And the gatekeepers: Akkub, Talmon and their colleagues who were guarding the gates – 172.'
EXEC add_BibleVerse @BibleId, 116011020, N'And the rest of the Israelites, with the priests and the Levites, were in all the cities of Judah, each on his own property.'
EXEC add_BibleVerse @BibleId, 116011021, N'The temple attendants were living on Ophel, and Ziha and Gishpa were over them.'
EXEC add_BibleVerse @BibleId, 116011022, N'The overseer of the Levites in Jerusalem was Uzzi son of Bani, the son of Hashabiah, the son of Mattaniah, the son of Mica. He was one of Asaph’s descendants who were the singers responsible for the service of the temple of God.'
EXEC add_BibleVerse @BibleId, 116011023, N'For they were under royal orders which determined their activity day by day.'
EXEC add_BibleVerse @BibleId, 116011024, N'Pethahiah son of Meshezabel, one of the descendants of Zerah son of Judah, was an adviser to the king in every matter pertaining to the people.'
EXEC add_BibleVerse @BibleId, 116011025, N'As for the settlements with their fields, some of the people of Judah settled in Kiriath Arba and its neighboring villages, in Dibon and its villages, in Jekabzeel and its settlements,'
EXEC add_BibleVerse @BibleId, 116011026, N'in Jeshua, in Moladah, in Beth Pelet,'
EXEC add_BibleVerse @BibleId, 116011027, N'in Hazar Shual, in Beer Sheba and its villages,'
EXEC add_BibleVerse @BibleId, 116011028, N'in Ziklag, in Meconah and its villages,'
EXEC add_BibleVerse @BibleId, 116011029, N'in En Rimmon, in Zorah, in Jarmuth,'
EXEC add_BibleVerse @BibleId, 116011030, N'Zanoah, Adullam and their settlements, in Lachish and its fields, and in Azekah and its villages. So they were encamped from Beer Sheba to the Valley of Hinnom.'
EXEC add_BibleVerse @BibleId, 116011031, N'Some of the descendants of Benjamin settled in Geba, Micmash, Aija, Bethel and its villages,'
EXEC add_BibleVerse @BibleId, 116011032, N'in Anathoth, Nob, and Ananiah,'
EXEC add_BibleVerse @BibleId, 116011033, N'in Hazor, Ramah, and Gittaim,'
EXEC add_BibleVerse @BibleId, 116011034, N'in Hadid, Zeboim, and Neballat,'
EXEC add_BibleVerse @BibleId, 116011035, N'in Lod, Ono, and the Valley of the Craftsmen.'
EXEC add_BibleVerse @BibleId, 116011036, N'Some of the Judean divisions of the Levites settled in Benjamin.'
EXEC add_BibleVerse @BibleId, 116012001, N'These are the priests and Levites who returned with Zerubbabel son of Shealtiel and Jeshua: Seraiah, Jeremiah, Ezra,'
EXEC add_BibleVerse @BibleId, 116012002, N'Amariah, Malluch, Hattush,'
EXEC add_BibleVerse @BibleId, 116012003, N'Shecaniah, Rehum, Meremoth,'
EXEC add_BibleVerse @BibleId, 116012004, N'Iddo, Ginnethon, Abijah,'
EXEC add_BibleVerse @BibleId, 116012005, N'Mijamin, Moadiah, Bilgah,'
EXEC add_BibleVerse @BibleId, 116012006, N'Shemaiah, Joiarib, Jedaiah,'
EXEC add_BibleVerse @BibleId, 116012007, N'Sallu, Amok, Hilkiah, and Jedaiah. These were the leaders of the priests and their colleagues in the days of Jeshua.'
EXEC add_BibleVerse @BibleId, 116012008, N'And the Levites: Jeshua, Binnui, Kadmiel, Sherebiah, Judah, and Mattaniah, who together with his colleagues was in charge of the songs of thanksgiving.'
EXEC add_BibleVerse @BibleId, 116012009, N'Bakbukiah and Unni, their colleagues, stood opposite them in the services.'
EXEC add_BibleVerse @BibleId, 116012010, N'Jeshua was the father of Joiakim, Joiakim was the father of Eliashib, Eliashib was the father of Joiada,'
EXEC add_BibleVerse @BibleId, 116012011, N'Joiada was the father of Jonathan, and Jonathan was the father of Jaddua.'
EXEC add_BibleVerse @BibleId, 116012012, N'In the days of Joiakim, these were the priests who were leaders of the families: of Seraiah, Meraiah; of Jeremiah, Hananiah;'
EXEC add_BibleVerse @BibleId, 116012013, N'of Ezra, Meshullam; of Amariah, Jehohanan;'
EXEC add_BibleVerse @BibleId, 116012014, N'of Malluch, Jonathan; of Shecaniah, Joseph;'
EXEC add_BibleVerse @BibleId, 116012015, N'of Harim, Adna; of Meremoth, Helkai;'
EXEC add_BibleVerse @BibleId, 116012016, N'of Iddo, Zechariah; of Ginnethon, Meshullam;'
EXEC add_BibleVerse @BibleId, 116012017, N'of Abijah, Zicri; of Miniamin and of Moadiah, Piltai;'
EXEC add_BibleVerse @BibleId, 116012018, N'of Bilgah, Shammua; of Shemaiah, Jehonathan;'
EXEC add_BibleVerse @BibleId, 116012019, N'of Joiarib, Mattenai; of Jedaiah, Uzzi;'
EXEC add_BibleVerse @BibleId, 116012020, N'of Sallu, Kallai; of Amok, Eber;'
EXEC add_BibleVerse @BibleId, 116012021, N'of Hilkiah, Hashabiah; of Jedaiah, Nethanel.'
EXEC add_BibleVerse @BibleId, 116012022, N'As for the Levites, in the days of Eliashib, Joiada, Johanan and Jaddua the heads of families were recorded, as were the priests during the reign of Darius the Persian.'
EXEC add_BibleVerse @BibleId, 116012023, N'The descendants of Levi were recorded in the Book of the Chronicles as heads of families up to the days of Johanan son of Eliashib.'
EXEC add_BibleVerse @BibleId, 116012024, N'And the leaders of the Levites were Hashabiah, Sherebiah, Jeshua son of Kadmiel, and their colleagues, who stood opposite them to offer praise and thanks, one contingent corresponding to the other, as specified by David the man of God.'
EXEC add_BibleVerse @BibleId, 116012025, N'Mattaniah, Bakbukiah, Obadiah, Meshullam, Talmon, and Akkub were gatekeepers who were guarding the storerooms at the gates.'
EXEC add_BibleVerse @BibleId, 116012026, N'These all served in the days of Joiakim son of Jeshua, the son of Jozadak, and in the days of Nehemiah the governor and of Ezra the priestly scribe.'
EXEC add_BibleVerse @BibleId, 116012027, N'At the dedication of the wall of Jerusalem, they sought out the Levites from all the places they lived to bring them to Jerusalem to celebrate the dedication joyfully with songs of thanksgiving and songs accompanied by cymbals, harps, and lyres.'
EXEC add_BibleVerse @BibleId, 116012028, N'The singers were also assembled from the district around Jerusalem and from the settlements of the Netophathites'
EXEC add_BibleVerse @BibleId, 116012029, N'and from Beth Gilgal and from the fields of Geba and Azmaveth, for the singers had built settlements for themselves around Jerusalem.'
EXEC add_BibleVerse @BibleId, 116012030, N'When the priests and Levites had purified themselves, they purified the people, the gates, and the wall.'
EXEC add_BibleVerse @BibleId, 116012031, N'I brought the leaders of Judah up on top of the wall, and I appointed two large choirs to give thanks. One was to proceed on the top of the wall southward toward the Dung Gate.'
EXEC add_BibleVerse @BibleId, 116012032, N'Going after them were Hoshaiah, half the leaders of Judah,'
EXEC add_BibleVerse @BibleId, 116012033, N'Azariah, Ezra, Meshullam,'
EXEC add_BibleVerse @BibleId, 116012034, N'Judah, Benjamin, Shemaiah, Jeremiah,'
EXEC add_BibleVerse @BibleId, 116012035, N'some of the priests with trumpets, Zechariah son of Jonathan, the son of Shemaiah, the son of Mattaniah, the son of Micaiah, the son of Zaccur, the son of Asaph,'
EXEC add_BibleVerse @BibleId, 116012036, N'and his colleagues – Shemaiah, Azarel, Milalai, Gilalai, Maai, Nethanel, Judah, and Hanani – with musical instruments of David the man of God. (Ezra the scribe led them.)'
EXEC add_BibleVerse @BibleId, 116012037, N'They went over the Fountain Gate and continued directly up the steps of the City of David on the ascent to the wall. They passed the house of David and continued on to the Water Gate toward the east.'
EXEC add_BibleVerse @BibleId, 116012038, N'The second choir was proceeding in the opposite direction. I followed them, along with half the people, on top of the wall, past the Tower of the Ovens to the Broad Wall,'
EXEC add_BibleVerse @BibleId, 116012039, N'over the Ephraim Gate, the Jeshanah Gate, the Fish Gate, the Tower of Hananel, and the Tower of the Hundred, to the Sheep Gate. They stopped at the Gate of the Guard.'
EXEC add_BibleVerse @BibleId, 116012040, N'Then the two choirs that gave thanks took their stations in the temple of God. I did also, along with half the officials with me,'
EXEC add_BibleVerse @BibleId, 116012041, N'and the priests – Eliakim, Maaseiah, Miniamin, Micaiah, Elioenai, Zechariah, and Hananiah, with their trumpets –'
EXEC add_BibleVerse @BibleId, 116012042, N'and also Maaseiah, Shemaiah, Eleazar, Uzzi, Jehohanan, Malkijah, Elam, and Ezer. The choirs sang loudly under the direction of Jezrahiah.'
EXEC add_BibleVerse @BibleId, 116012043, N'And on that day they offered great sacrifices and rejoiced, for God had given them great joy. The women and children also rejoiced. The rejoicing in Jerusalem could be heard from far away.'
EXEC add_BibleVerse @BibleId, 116012044, N'On that day men were appointed over the storerooms for the contributions, first fruits, and tithes, to gather into them from the fields of the cities the portions prescribed by the law for the priests and the Levites, for the people of Judah took delight in the priests and Levites who were ministering.'
EXEC add_BibleVerse @BibleId, 116012045, N'They performed the service of their God and the service of purification, along with the singers and gatekeepers, according to the commandment of David and his son Solomon.'
EXEC add_BibleVerse @BibleId, 116012046, N'For long ago, in the days of David and Asaph, there had been directors for the singers and for the songs of praise and thanks to God.'
EXEC add_BibleVerse @BibleId, 116012047, N'So in the days of Zerubbabel and in the days of Nehemiah, all Israel was contributing the portions for the singers and gatekeepers, according to the daily need. They also set aside the portion for the Levites, and the Levites set aside the portion for the descendants of Aaron.'
EXEC add_BibleVerse @BibleId, 116013001, N'On that day the book of Moses was read aloud in the hearing of the people. They found written in it that no Ammonite or Moabite may ever enter the assembly of God,'
EXEC add_BibleVerse @BibleId, 116013002, N'for they had not met the Israelites with food and water, but instead had hired Balaam to curse them. (Our God, however, turned the curse into blessing.)'
EXEC add_BibleVerse @BibleId, 116013003, N'When they heard the law, they removed from Israel all who were of mixed ancestry.'
EXEC add_BibleVerse @BibleId, 116013004, N'But prior to this time, Eliashib the priest, a relative of Tobiah, had been appointed over the storerooms of the temple of our God.'
EXEC add_BibleVerse @BibleId, 116013005, N'He made for himself a large storeroom where previously they had been keeping the grain offering, the incense, and the vessels, along with the tithes of the grain, the new wine, and the olive oil as commanded for the Levites, the singers, the gate keepers, and the offering for the priests.'
EXEC add_BibleVerse @BibleId, 116013006, N'During all this time I was not in Jerusalem, for in the thirty-second year of King Artaxerxes of Babylon, I had gone back to the king. After some time I had requested leave of the king,'
EXEC add_BibleVerse @BibleId, 116013007, N'and I returned to Jerusalem. Then I discovered the evil that Eliashib had done for Tobiah by supplying him with a storeroom in the courts of the temple of God.'
EXEC add_BibleVerse @BibleId, 116013008, N'I was very upset, and I threw all of Tobiah’s household possessions out of the storeroom.'
EXEC add_BibleVerse @BibleId, 116013009, N'Then I gave instructions that the storerooms should be purified, and I brought back the equipment of the temple of God, along with the grain offering and the incense.'
EXEC add_BibleVerse @BibleId, 116013010, N'I also discovered that the grain offerings for the Levites had not been provided, and that as a result the Levites and the singers who performed this work had all gone off to their fields.'
EXEC add_BibleVerse @BibleId, 116013011, N'So I registered a complaint with the leaders, asking “Why is the temple of God neglected?” Then I gathered them and reassigned them to their positions.'
EXEC add_BibleVerse @BibleId, 116013012, N'Then all of Judah brought the tithe of the grain, the new wine, and the olive oil to the storerooms.'
EXEC add_BibleVerse @BibleId, 116013013, N'I gave instructions that Shelemiah the priest, Zadok the scribe, and a certain Levite named Pedaiah be put in charge of the storerooms, and that Hanan son of Zaccur, the son of Mattaniah, be their assistant, for they were regarded as trustworthy. It was then their responsibility to oversee the distribution to their colleagues.'
EXEC add_BibleVerse @BibleId, 116013014, N'Please remember me for this, O my God, and do not wipe out the kindness that I have done for the temple of my God and for its services!'
EXEC add_BibleVerse @BibleId, 116013015, N'In those days I saw people in Judah treading winepresses on the Sabbath, bringing in heaps of grain and loading them onto donkeys, along with wine, grapes, figs, and all kinds of loads, and bringing them to Jerusalem on the Sabbath day. So I warned them on the day that they sold these provisions.'
EXEC add_BibleVerse @BibleId, 116013016, N'The people from Tyre who lived there were bringing fish and all kinds of merchandise and were selling it on the Sabbath to the people of Judah – and in Jerusalem, of all places!'
EXEC add_BibleVerse @BibleId, 116013017, N'So I registered a complaint with the nobles of Judah, saying to them, “What is this evil thing that you are doing, profaning the Sabbath day?'
EXEC add_BibleVerse @BibleId, 116013018, N'Isn’t this the way your ancestors acted, causing our God to bring on them and on this city all this misfortune? And now you are causing even more wrath on Israel, profaning the Sabbath like this!”'
EXEC add_BibleVerse @BibleId, 116013019, N'When the evening shadows began to fall on the gates of Jerusalem before the Sabbath, I ordered the doors to be closed. I further directed that they were not to be opened until after the Sabbath. I positioned some of my young men at the gates so that no load could enter on the Sabbath day.'
EXEC add_BibleVerse @BibleId, 116013020, N'The traders and sellers of all kinds of merchandise spent the night outside Jerusalem once or twice.'
EXEC add_BibleVerse @BibleId, 116013021, N'But I warned them and said, “Why do you spend the night by the wall? If you repeat this, I will forcibly remove you!” From that time on they did not show up on the Sabbath.'
EXEC add_BibleVerse @BibleId, 116013022, N'Then I directed the Levites to purify themselves and come and guard the gates in order to keep the Sabbath day holy. For this please remember me, O my God, and have pity on me in keeping with your great love.'
EXEC add_BibleVerse @BibleId, 116013023, N'Also in those days I saw the men of Judah who had married women from Ashdod, Ammon, and Moab.'
EXEC add_BibleVerse @BibleId, 116013024, N'Half of their children spoke the language of Ashdod (or the language of one of the other peoples mentioned ) and were unable to speak the language of Judah.'
EXEC add_BibleVerse @BibleId, 116013025, N'So I entered a complaint with them. I called down a curse on them, and I struck some of the men and pulled out their hair. I had them swear by God saying, “You will not marry off your daughters to their sons, and you will not take any of their daughters as wives for your sons or for yourselves!'
EXEC add_BibleVerse @BibleId, 116013026, N'Was it not because of things like these that King Solomon of Israel sinned? Among the many nations there was no king like him. He was loved by his God, and God made him king over all Israel. But the foreign wives made even him sin!'
EXEC add_BibleVerse @BibleId, 116013027, N'Should we then in your case hear that you do all this great evil, thereby being unfaithful to our God by marrying foreign wives?”'
EXEC add_BibleVerse @BibleId, 116013028, N'Now one of the sons of Joiada son of Eliashib the high priest was a son-in-law of Sanballat the Horonite. So I banished him from my sight.'
EXEC add_BibleVerse @BibleId, 116013029, N'Please remember them, O my God, because they have defiled the priesthood, the covenant of the priesthood, and the Levites.'
EXEC add_BibleVerse @BibleId, 116013030, N'So I purified them of everything foreign, and I assigned specific duties to the priests and the Levites.'
EXEC add_BibleVerse @BibleId, 116013031, N'I also provided for the wood offering at the appointed times and also for the first fruits. Please remember me for good, O my God.'
EXEC add_BibleVerse @BibleId, 117001001, N'The following events happened in the days of Ahasuerus. (I am referring to that Ahasuerus who used to rule over a hundred and twenty-seven provinces extending all the way from India to Ethiopia. )'
EXEC add_BibleVerse @BibleId, 117001002, N'In those days, as King Ahasuerus sat on his royal throne in Susa the citadel,'
EXEC add_BibleVerse @BibleId, 117001003, N'in the third year of his reign he provided a banquet for all his officials and his servants. The army of Persia and Media was present, as well as the nobles and the officials of the provinces.'
EXEC add_BibleVerse @BibleId, 117001004, N'He displayed the riches of his royal glory and the splendor of his majestic greatness for a lengthy period of time – a hundred and eighty days, to be exact!'
EXEC add_BibleVerse @BibleId, 117001005, N'When those days were completed, the king then provided a seven-day banquet for all the people who were present in Susa the citadel, for those of highest standing to the most lowly. It was held in the court located in the garden of the royal palace.'
EXEC add_BibleVerse @BibleId, 117001006, N'The furnishings included linen and purple curtains hung by cords of the finest linen and purple wool on silver rings, alabaster columns, gold and silver couches displayed on a floor made of valuable stones of alabaster, mother-of-pearl, and mineral stone.'
EXEC add_BibleVerse @BibleId, 117001007, N'Drinks were served in golden containers, all of which differed from one another. Royal wine was available in abundance at the king’s expense.'
EXEC add_BibleVerse @BibleId, 117001008, N'There were no restrictions on the drinking, for the king had instructed all of his supervisors that they should do as everyone so desired.'
EXEC add_BibleVerse @BibleId, 117001009, N'Queen Vashti also gave a banquet for the women in King Ahasuerus’ royal palace.'
EXEC add_BibleVerse @BibleId, 117001010, N'On the seventh day, as King Ahasuerus was feeling the effects of the wine, he ordered Mehuman, Biztha, Harbona, Bigtha, Abagtha, Zethar, and Carcas, the seven eunuchs who attended him,'
EXEC add_BibleVerse @BibleId, 117001011, N'to bring Queen Vashti into the king’s presence wearing her royal high turban. He wanted to show the people and the officials her beauty, for she was very attractive.'
EXEC add_BibleVerse @BibleId, 117001012, N'But Queen Vashti refused to come at the king’s bidding conveyed through the eunuchs. Then the king became extremely angry, and his rage consumed him.'
EXEC add_BibleVerse @BibleId, 117001013, N'The king then inquired of the wise men who were discerners of the times – for it was the royal custom to confer with all those who were proficient in laws and legalities.'
EXEC add_BibleVerse @BibleId, 117001014, N'Those who were closest to him were Carshena, Shethar, Admatha, Tarshish, Meres, Marsena, and Memucan. These men were the seven officials of Persia and Media who saw the king on a regular basis and had the most prominent offices in the kingdom.'
EXEC add_BibleVerse @BibleId, 117001015, N'The king asked, “By law, what should be done to Queen Vashti in light of the fact that she has not obeyed the instructions of King Ahasuerus conveyed through the eunuchs?”'
EXEC add_BibleVerse @BibleId, 117001016, N'Memucan then replied to the king and the officials, “The wrong of Queen Vashti is not against the king alone, but against all the officials and all the people who are throughout all the provinces of King Ahasuerus.'
EXEC add_BibleVerse @BibleId, 117001017, N'For the matter concerning the queen will spread to all the women, leading them to treat their husbands with contempt, saying, ‘When King Ahasuerus gave orders to bring Queen Vashti into his presence, she would not come.’'
EXEC add_BibleVerse @BibleId, 117001018, N'And this very day the noble ladies of Persia and Media who have heard the matter concerning the queen will respond in the same way to all the royal officials, and there will be more than enough contempt and anger!'
EXEC add_BibleVerse @BibleId, 117001019, N'If the king is so inclined, let a royal edict go forth from him, and let it be written in the laws of Persia and Media that cannot be repealed, that Vashti may not come into the presence of King Ahasuerus, and let the king convey her royalty to another who is more deserving than she.'
EXEC add_BibleVerse @BibleId, 117001020, N'And let the king’s decision which he will enact be disseminated throughout all his kingdom, vast though it is. Then all the women will give honor to their husbands, from the most prominent to the lowly.”'
EXEC add_BibleVerse @BibleId, 117001021, N'The matter seemed appropriate to the king and the officials. So the king acted on the advice of Memucan.'
EXEC add_BibleVerse @BibleId, 117001022, N'He sent letters throughout all the royal provinces, to each province according to its own script and to each people according to its own language, that every man should be ruling his family and should be speaking the language of his own people.'
EXEC add_BibleVerse @BibleId, 117002001, N'When these things had been accomplished and the rage of King Ahasuerus had diminished, he remembered Vashti and what she had done and what had been decided against her.'
EXEC add_BibleVerse @BibleId, 117002002, N'The king’s servants who attended him said, “Let a search be conducted in the king’s behalf for attractive young women.'
EXEC add_BibleVerse @BibleId, 117002003, N'And let the king appoint officers throughout all the provinces of his kingdom to gather all the attractive young women to Susa the citadel, to the harem under the authority of Hegai, the king’s eunuch who oversees the women, and let him provide whatever cosmetics they desire.'
EXEC add_BibleVerse @BibleId, 117002004, N'Let the young woman whom the king finds most attractive become queen in place of Vashti.” This seemed like a good idea to the king, so he acted accordingly.'
EXEC add_BibleVerse @BibleId, 117002005, N'Now there happened to be a Jewish man in Susa the citadel whose name was Mordecai. He was the son of Jair, the son of Shimei, the son of Kish, a Benjaminite,'
EXEC add_BibleVerse @BibleId, 117002006, N'who had been taken into exile from Jerusalem with the captives who had been carried into exile with Jeconiah king of Judah, whom Nebuchadnezzar king of Babylon had taken into exile.'
EXEC add_BibleVerse @BibleId, 117002007, N'Now he was acting as the guardian of Hadassah (that is, Esther), the daughter of his uncle, for neither her father nor her mother was alive. This young woman was very attractive and had a beautiful figure. When her father and mother died, Mordecai had raised her as if she were his own daughter.'
EXEC add_BibleVerse @BibleId, 117002008, N'It so happened that when the king’s edict and his law became known many young women were taken to Susa the citadel to be placed under the authority of Hegai. Esther also was taken to the royal palace to be under the authority of Hegai, who was overseeing the women.'
EXEC add_BibleVerse @BibleId, 117002009, N'This young woman pleased him, and she found favor with him. He quickly provided her with her cosmetics and her rations; he also provided her with the seven specially chosen young women who were from the palace. He then transferred her and her young women to the best quarters in the harem.'
EXEC add_BibleVerse @BibleId, 117002010, N'Now Esther had not disclosed her people or her lineage, for Mordecai had instructed her not to do so.'
EXEC add_BibleVerse @BibleId, 117002011, N'And day after day Mordecai used to walk back and forth in front of the court of the harem in order to learn how Esther was doing and what might happen to her.'
EXEC add_BibleVerse @BibleId, 117002012, N'At the end of the twelve months that were required for the women, when the turn of each young woman arrived to go to King Ahasuerus – for in this way they had to fulfill their time of cosmetic treatment: six months with oil of myrrh, and six months with perfume and various ointments used by women –'
EXEC add_BibleVerse @BibleId, 117002013, N'the woman would go to the king in the following way: Whatever she asked for would be provided for her to take with her from the harem to the royal palace.'
EXEC add_BibleVerse @BibleId, 117002014, N'In the evening she went, and in the morning she returned to a separate part of the harem, to the authority of Shaashgaz the king’s eunuch who was overseeing the concubines. She would not go back to the king unless the king was pleased with her and she was requested by name.'
EXEC add_BibleVerse @BibleId, 117002015, N'When it became the turn of Esther daughter of Abihail the uncle of Mordecai (who had raised her as if she were his own daughter ) to go to the king, she did not request anything except what Hegai the king’s eunuch, who was overseer of the women, had recommended. Yet Esther met with the approval of all who saw her.'
EXEC add_BibleVerse @BibleId, 117002016, N'Then Esther was taken to King Ahasuerus at his royal residence in the tenth month (that is, the month of Tebeth) in the seventh year of his reign.'
EXEC add_BibleVerse @BibleId, 117002017, N'And the king loved Esther more than all the other women, and she met with his loving approval more than all the other young women. So he placed the royal high turban on her head and appointed her queen in place of Vashti.'
EXEC add_BibleVerse @BibleId, 117002018, N'Then the king prepared a large banquet for all his officials and his servants – it was actually Esther’s banquet. He also set aside a holiday for the provinces, and he provided for offerings at the king’s expense.'
EXEC add_BibleVerse @BibleId, 117002019, N'Now when the young women were being gathered again, Mordecai was sitting at the king’s gate.'
EXEC add_BibleVerse @BibleId, 117002020, N'Esther was still not divulging her lineage or her people, just as Mordecai had instructed her. Esther continued to do whatever Mordecai said, just as she had done when he was raising her.'
EXEC add_BibleVerse @BibleId, 117002021, N'In those days while Mordecai was sitting at the king’s gate, Bigthan and Teresh, two of the king’s eunuchs who protected the entrance, became angry and plotted to assassinate King Ahasuerus.'
EXEC add_BibleVerse @BibleId, 117002022, N'When Mordecai learned of the conspiracy, he informed Queen Esther, and Esther told the king in Mordecai’s behalf.'
EXEC add_BibleVerse @BibleId, 117002023, N'The king then had the matter investigated and, finding it to be so, had the two conspirators hanged on a gallows. It was then recorded in the daily chronicles in the king’s presence.'
EXEC add_BibleVerse @BibleId, 117003001, N'Some time later King Ahasuerus promoted Haman the son of Hammedatha, the Agagite, exalting him and setting his position above that of all the officials who were with him.'
EXEC add_BibleVerse @BibleId, 117003002, N'As a result, all the king’s servants who were at the king’s gate were bowing and paying homage to Haman, for the king had so commanded. However, Mordecai did not bow, nor did he pay him homage.'
EXEC add_BibleVerse @BibleId, 117003003, N'Then the servants of the king who were at the king’s gate asked Mordecai, “Why are you violating the king’s commandment?”'
EXEC add_BibleVerse @BibleId, 117003004, N'And after they had spoken to him day after day without his paying any attention to them, they informed Haman to see whether this attitude on Mordecai’s part would be permitted. Furthermore, he had disclosed to them that he was a Jew.'
EXEC add_BibleVerse @BibleId, 117003005, N'When Haman saw that Mordecai was not bowing or paying homage to him, he was filled with rage.'
EXEC add_BibleVerse @BibleId, 117003006, N'But the thought of striking out against Mordecai alone was repugnant to him, for he had been informed of the identity of Mordecai’s people. So Haman sought to destroy all the Jews (that is, the people of Mordecai) who were in all the kingdom of Ahasuerus.'
EXEC add_BibleVerse @BibleId, 117003007, N'In the first month (that is, the month of Nisan), in the twelfth year of King Ahasuerus’ reign, pur (that is, the lot) was cast before Haman in order to determine a day and a month. It turned out to be the twelfth month (that is, the month of Adar).'
EXEC add_BibleVerse @BibleId, 117003008, N'Then Haman said to King Ahasuerus, “There is a particular people that is dispersed and spread among the inhabitants throughout all the provinces of your kingdom whose laws differ from those of all other peoples. Furthermore, they do not observe the king’s laws. It is not appropriate for the king to provide a haven for them.'
EXEC add_BibleVerse @BibleId, 117003009, N'If the king is so inclined, let an edict be issued to destroy them. I will pay ten thousand talents of silver to be conveyed to the king’s treasuries for the officials who carry out this business.”'
EXEC add_BibleVerse @BibleId, 117003010, N'So the king removed his signet ring from his hand and gave it to Haman the son of Hammedatha, the Agagite, who was hostile toward the Jews.'
EXEC add_BibleVerse @BibleId, 117003011, N'The king replied to Haman, “Keep your money, and do with those people whatever you wish.”'
EXEC add_BibleVerse @BibleId, 117003012, N'So the royal scribes were summoned in the first month, on the thirteenth day of the month. Everything Haman commanded was written to the king’s satraps and governors who were in every province and to the officials of every people, province by province according to its script and people by people according to its language. In the name of King Ahasuerus it was written and sealed with the king’s signet ring.'
EXEC add_BibleVerse @BibleId, 117003013, N'Letters were sent by the runners to all the king’s provinces stating that they should destroy, kill, and annihilate all the Jews, from youth to elderly, both women and children, on a particular day, namely the thirteenth day of the twelfth month (that is, the month of Adar), and to loot and plunder their possessions.'
EXEC add_BibleVerse @BibleId, 117003014, N'A copy of this edict was to be presented as law throughout every province; it was to be made known to all the inhabitants, so that they would be prepared for this day.'
EXEC add_BibleVerse @BibleId, 117003015, N'The messengers scurried forth with the king’s order. The edict was issued in Susa the citadel. While the king and Haman sat down to drink, the city of Susa was in an uproar!'
EXEC add_BibleVerse @BibleId, 117004001, N'Now when Mordecai became aware of all that had been done, he tore his garments and put on sackcloth and ashes. He went out into the city, crying out in a loud and bitter voice.'
EXEC add_BibleVerse @BibleId, 117004002, N'But he went no further than the king’s gate, for no one was permitted to enter the king’s gate clothed in sackcloth.'
EXEC add_BibleVerse @BibleId, 117004003, N'Throughout each and every province where the king’s edict and law were announced there was considerable mourning among the Jews, along with fasting, weeping, and sorrow. Sackcloth and ashes were characteristic of many.'
EXEC add_BibleVerse @BibleId, 117004004, N'When Esther’s female attendants and her eunuchs came and informed her about Mordecai’s behavior, the queen was overcome with anguish. Although she sent garments for Mordecai to put on so that he could remove his sackcloth, he would not accept them.'
EXEC add_BibleVerse @BibleId, 117004005, N'So Esther called for Hathach, one of the king’s eunuchs who had been placed at her service, and instructed him to find out the cause and reason for Mordecai’s behavior.'
EXEC add_BibleVerse @BibleId, 117004006, N'So Hathach went to Mordecai at the plaza of the city in front of the king’s gate.'
EXEC add_BibleVerse @BibleId, 117004007, N'Then Mordecai related to him everything that had happened to him, even the specific amount of money that Haman had offered to pay to the king’s treasuries for the Jews to be destroyed.'
EXEC add_BibleVerse @BibleId, 117004008, N'He also gave him a written copy of the law that had been disseminated in Susa for their destruction so that he could show it to Esther and talk to her about it. He also gave instructions that she should go to the king to implore him and petition him on behalf of her people.'
EXEC add_BibleVerse @BibleId, 117004009, N'So Hathach returned and related Mordecai’s instructions to Esther.'
EXEC add_BibleVerse @BibleId, 117004010, N'Then Esther replied to Hathach with instructions for Mordecai:'
EXEC add_BibleVerse @BibleId, 117004011, N'“All the servants of the king and the people of the king’s provinces know that there is only one law applicable to any man or woman who comes uninvited to the king in the inner court – that person will be put to death, unless the king extends to him the gold scepter, permitting him to be spared. Now I have not been invited to come to the king for some thirty days!”'
EXEC add_BibleVerse @BibleId, 117004012, N'When Esther’s reply was conveyed to Mordecai,'
EXEC add_BibleVerse @BibleId, 117004013, N'he said to take back this answer to Esther:'
EXEC add_BibleVerse @BibleId, 117004014, N'“Don’t imagine that because you are part of the king’s household you will be the one Jew who will escape. If you keep quiet at this time, liberation and protection for the Jews will appear from another source, while you and your father’s household perish. It may very well be that you have achieved royal status for such a time as this!”'
EXEC add_BibleVerse @BibleId, 117004015, N'Then Esther sent this reply to Mordecai:'
EXEC add_BibleVerse @BibleId, 117004016, N'“Go, assemble all the Jews who are found in Susa and fast in my behalf. Don’t eat and don’t drink for three days, night or day. My female attendants and I will also fast in the same way. Afterward I will go to the king, even though it violates the law. If I perish, I perish!”'
EXEC add_BibleVerse @BibleId, 117004017, N'So Mordecai set out to do everything that Esther had instructed him.'
EXEC add_BibleVerse @BibleId, 117005001, N'It so happened that on the third day Esther put on her royal attire and stood in the inner court of the palace, opposite the king’s quarters. The king was sitting on his royal throne in the palace, opposite the entrance.'
EXEC add_BibleVerse @BibleId, 117005002, N'When the king saw Queen Esther standing in the court, she met with his approval. The king extended to Esther the gold scepter that was in his hand, and Esther approached and touched the end of the scepter.'
EXEC add_BibleVerse @BibleId, 117005003, N'The king said to her, “What is on your mind, Queen Esther? What is your request? Even as much as half the kingdom will be given to you!”'
EXEC add_BibleVerse @BibleId, 117005004, N'Esther replied, “If the king is so inclined, let the king and Haman come today to the banquet that I have prepared for him.”'
EXEC add_BibleVerse @BibleId, 117005005, N'The king replied, “Find Haman quickly so that we can do as Esther requests.” So the king and Haman went to the banquet that Esther had prepared.'
EXEC add_BibleVerse @BibleId, 117005006, N'While at the banquet of wine, the king said to Esther, “What is your request? It shall be given to you. What is your petition? Ask for as much as half the kingdom, and it shall be done!”'
EXEC add_BibleVerse @BibleId, 117005007, N'Esther responded, “My request and my petition is this:'
EXEC add_BibleVerse @BibleId, 117005008, N'If I have found favor in the king’s sight and if the king is inclined to grant my request and perform my petition, let the king and Haman come tomorrow to the banquet that I will prepare for them. At that time I will do as the king wishes.'
EXEC add_BibleVerse @BibleId, 117005009, N'Now Haman went forth that day pleased and very much encouraged. But when Haman saw Mordecai at the king’s gate, and he did not rise nor tremble in his presence, Haman was filled with rage toward Mordecai.'
EXEC add_BibleVerse @BibleId, 117005010, N'But Haman restrained himself and went on to his home. He then sent for his friends to join him, along with his wife Zeresh.'
EXEC add_BibleVerse @BibleId, 117005011, N'Haman then recounted to them his fabulous wealth, his many sons, and how the king had magnified him and exalted him over the king’s other officials and servants.'
EXEC add_BibleVerse @BibleId, 117005012, N'Haman said, “Furthermore, Queen Esther invited only me to accompany the king to the banquet that she prepared! And also tomorrow I am invited along with the king.'
EXEC add_BibleVerse @BibleId, 117005013, N'Yet all of this fails to satisfy me so long as I have to see Mordecai the Jew sitting at the king’s gate.”'
EXEC add_BibleVerse @BibleId, 117005014, N'Haman’s wife Zeresh and all his friends said to him, “Have a gallows seventy-five feet high built, and in the morning tell the king that Mordecai should be hanged on it. Then go with the king to the banquet contented.” It seemed like a good idea to Haman, so he had the gallows built.'
EXEC add_BibleVerse @BibleId, 117006001, N'Throughout that night the king was unable to sleep, so he asked for the book containing the historical records to be brought. As the records were being read in the king’s presence,'
EXEC add_BibleVerse @BibleId, 117006002, N'it was found written that Mordecai had disclosed that Bigthana and Teresh, two of the king’s eunuchs who guarded the entrance, had plotted to assassinate King Ahasuerus.'
EXEC add_BibleVerse @BibleId, 117006003, N'The king asked, “What great honor was bestowed on Mordecai because of this?” The king’s attendants who served him responded, “Not a thing was done for him.”'
EXEC add_BibleVerse @BibleId, 117006004, N'Then the king said, “Who is that in the courtyard?” Now Haman had come to the outer courtyard of the palace to suggest that the king hang Mordecai on the gallows that he had constructed for him.'
EXEC add_BibleVerse @BibleId, 117006005, N'The king’s attendants said to him, “It is Haman who is standing in the courtyard.” The king said, “Let him enter.”'
EXEC add_BibleVerse @BibleId, 117006006, N'So Haman came in, and the king said to him, “What should be done for the man whom the king wishes to honor?” Haman thought to himself, “Who is it that the king would want to honor more than me?”'
EXEC add_BibleVerse @BibleId, 117006007, N'So Haman said to the king, “For the man whom the king wishes to honor,'
EXEC add_BibleVerse @BibleId, 117006008, N'let them bring royal attire which the king himself has worn and a horse on which the king himself has ridden – one bearing the royal insignia!'
EXEC add_BibleVerse @BibleId, 117006009, N'Then let this clothing and this horse be given to one of the king’s noble officials. Let him then clothe the man whom the king wishes to honor, and let him lead him about through the plaza of the city on the horse, calling before him, ‘So shall it be done to the man whom the king wishes to honor!’”'
EXEC add_BibleVerse @BibleId, 117006010, N'The king then said to Haman, “Go quickly! Take the clothing and the horse, just as you have described, and do as you just indicated to Mordecai the Jew who sits at the king’s gate. Don’t neglect a single thing of all that you have said.”'
EXEC add_BibleVerse @BibleId, 117006011, N'So Haman took the clothing and the horse, and he clothed Mordecai. He led him about on the horse throughout the plaza of the city, calling before him, “So shall it be done to the man whom the king wishes to honor!”'
EXEC add_BibleVerse @BibleId, 117006012, N'Then Mordecai again sat at the king’s gate, while Haman hurried away to his home, mournful and with a veil over his head.'
EXEC add_BibleVerse @BibleId, 117006013, N'Haman then related to his wife Zeresh and to all his friends everything that had happened to him. These wise men, along with his wife Zeresh, said to him, “If indeed this Mordecai before whom you have begun to fall is Jewish, you will not prevail against him. No, you will surely fall before him!”'
EXEC add_BibleVerse @BibleId, 117006014, N'While they were still speaking with him, the king’s eunuchs arrived. They quickly brought Haman to the banquet that Esther had prepared.'
EXEC add_BibleVerse @BibleId, 117007001, N'So the king and Haman came to dine with Queen Esther.'
EXEC add_BibleVerse @BibleId, 117007002, N'On the second day of the banquet of wine the king asked Esther, “What is your request, Queen Esther? It shall be granted to you. And what is your petition? Ask up to half the kingdom, and it shall be done!”'
EXEC add_BibleVerse @BibleId, 117007003, N'Queen Esther replied, “If I have met with your approval, O king, and if the king is so inclined, grant me my life as my request, and my people as my petition.'
EXEC add_BibleVerse @BibleId, 117007004, N'For we have been sold – both I and my people – to destruction and to slaughter and to annihilation! If we had simply been sold as male and female slaves, I would have remained silent, for such distress would not have been sufficient for troubling the king.”'
EXEC add_BibleVerse @BibleId, 117007005, N'Then King Ahasuerus responded to Queen Esther, “Who is this individual? Where is this person to be found who is presumptuous enough to act in this way?”'
EXEC add_BibleVerse @BibleId, 117007006, N'Esther replied, “The oppressor and enemy is this evil Haman!” Then Haman became terrified in the presence of the king and queen.'
EXEC add_BibleVerse @BibleId, 117007007, N'In rage the king arose from the banquet of wine and withdrew to the palace garden. Meanwhile, Haman stood to beg Queen Esther for his life, for he realized that the king had now determined a catastrophic end for him.'
EXEC add_BibleVerse @BibleId, 117007008, N'When the king returned from the palace garden to the banquet of wine, Haman was throwing himself down on the couch where Esther was lying. The king exclaimed, “Will he also attempt to rape the queen while I am still in the building!” As these words left the king’s mouth, they covered Haman’s face.'
EXEC add_BibleVerse @BibleId, 117007009, N'Harbona, one of the king’s eunuchs, said, “Indeed, there is the gallows that Haman made for Mordecai, who spoke out in the king’s behalf. It stands near Haman’s home and is seventy-five feet high.” The king said, “Hang him on it!”'
EXEC add_BibleVerse @BibleId, 117007010, N'So they hanged Haman on the very gallows that he had prepared for Mordecai. The king’s rage then abated.'
EXEC add_BibleVerse @BibleId, 117008001, N'On that same day King Ahasuerus gave the estate of Haman, that adversary of the Jews, to Queen Esther. Now Mordecai had come before the king, for Esther had revealed how he was related to her.'
EXEC add_BibleVerse @BibleId, 117008002, N'The king then removed his signet ring (the very one he had taken back from Haman) and gave it to Mordecai. And Esther designated Mordecai to be in charge of Haman’s estate.'
EXEC add_BibleVerse @BibleId, 117008003, N'Then Esther again spoke with the king, falling at his feet. She wept and begged him for mercy, that he might nullify the evil of Haman the Agagite which he had intended against the Jews.'
EXEC add_BibleVerse @BibleId, 117008004, N'When the king extended to Esther the gold scepter, she arose and stood before the king.'
EXEC add_BibleVerse @BibleId, 117008005, N'She said, “If the king is so inclined and if I have met with his approval and if the matter is agreeable to the king and if I am attractive to him, let an edict be written rescinding those recorded intentions of Haman the son of Hammedatha, the Agagite, which he wrote in order to destroy the Jews who are throughout all the king’s provinces.'
EXEC add_BibleVerse @BibleId, 117008006, N'For how can I watch the calamity that will befall my people, and how can I watch the destruction of my relatives?”'
EXEC add_BibleVerse @BibleId, 117008007, N'King Ahasuerus replied to Queen Esther and to Mordecai the Jew, “Look, I have already given Haman’s estate to Esther, and he has been hanged on the gallows because he took hostile action against the Jews.'
EXEC add_BibleVerse @BibleId, 117008008, N'Now you write in the king’s name whatever in your opinion is appropriate concerning the Jews and seal it with the king’s signet ring. Any decree that is written in the king’s name and sealed with the king’s signet ring cannot be rescinded.'
EXEC add_BibleVerse @BibleId, 117008009, N'The king’s scribes were quickly summoned – in the third month (that is, the month of Sivan), on the twenty-third day. They wrote out everything that Mordecai instructed to the Jews and to the satraps and the governors and the officials of the provinces all the way from India to Ethiopia – a hundred and twenty-seven provinces in all – to each province in its own script and to each people in their own language, and to the Jews according to their own script and their own language.'
EXEC add_BibleVerse @BibleId, 117008010, N'Mordecai wrote in the name of King Ahasuerus and sealed it with the king’s signet ring. He then sent letters by couriers on horses, who rode royal horses that were very swift.'
EXEC add_BibleVerse @BibleId, 117008011, N'The king thereby allowed the Jews who were in every city to assemble and to stand up for themselves – to destroy, to kill, and to annihilate any army of whatever people or province that should become their adversaries, including their women and children, and to confiscate their property.'
EXEC add_BibleVerse @BibleId, 117008012, N'This was to take place on a certain day throughout all the provinces of King Ahasuerus – namely, on the thirteenth day of the twelfth month (that is, the month of Adar).'
EXEC add_BibleVerse @BibleId, 117008013, N'A copy of the edict was to be presented as law throughout each and every province and made known to all peoples, so that the Jews might be prepared on that day to avenge themselves from their enemies.'
EXEC add_BibleVerse @BibleId, 117008014, N'The couriers who were riding the royal horses went forth with the king’s edict without delay. And the law was presented in Susa the citadel as well.'
EXEC add_BibleVerse @BibleId, 117008015, N'Now Mordecai went out from the king’s presence in purple and white royal attire, with a large golden crown and a purple linen mantle. The city of Susa shouted with joy.'
EXEC add_BibleVerse @BibleId, 117008016, N'For the Jews there was radiant happiness and joyous honor.'
EXEC add_BibleVerse @BibleId, 117008017, N'Throughout every province and throughout every city where the king’s edict and his law arrived, the Jews experienced happiness and joy, banquets and holidays. Many of the resident peoples pretended to be Jews, because the fear of the Jews had overcome them.'
EXEC add_BibleVerse @BibleId, 117009001, N'In the twelfth month (that is, the month of Adar), on its thirteenth day, the edict of the king and his law were to be executed. It was on this day that the enemies of the Jews had supposed that they would gain power over them. But contrary to expectations, the Jews gained power over their enemies.'
EXEC add_BibleVerse @BibleId, 117009002, N'The Jews assembled themselves in their cities throughout all the provinces of King Ahasuerus to strike out against those who were seeking their harm. No one was able to stand before them, for dread of them fell on all the peoples.'
EXEC add_BibleVerse @BibleId, 117009003, N'All the officials of the provinces, the satraps, the governors and those who performed the king’s business were assisting the Jews, for the dread of Mordecai had fallen on them.'
EXEC add_BibleVerse @BibleId, 117009004, N'Mordecai was of high rank in the king’s palace, and word about him was spreading throughout all the provinces. His influence continued to become greater and greater.'
EXEC add_BibleVerse @BibleId, 117009005, N'The Jews struck all their enemies with the sword, bringing death and destruction, and they did as they pleased with their enemies.'
EXEC add_BibleVerse @BibleId, 117009006, N'In Susa the citadel the Jews killed and destroyed five hundred men.'
EXEC add_BibleVerse @BibleId, 117009007, N'In addition, they also killed Parshandatha, Dalphon, Aspatha,'
EXEC add_BibleVerse @BibleId, 117009008, N'Poratha, Adalia, Aridatha,'
EXEC add_BibleVerse @BibleId, 117009009, N'Parmashta, Arisai, Aridai, and Vaizatha,'
EXEC add_BibleVerse @BibleId, 117009010, N'the ten sons of Haman son of Hammedatha, the enemy of the Jews. But they did not confiscate their property.'
EXEC add_BibleVerse @BibleId, 117009011, N'On that same day the number of those killed in Susa the citadel was brought to the king’s attention.'
EXEC add_BibleVerse @BibleId, 117009012, N'Then the king said to Queen Esther, “In Susa the citadel the Jews have killed and destroyed five hundred men and the ten sons of Haman! What then have they done in the rest of the king’s provinces? What is your request? It shall be given to you. What other petition do you have? It shall be done.”'
EXEC add_BibleVerse @BibleId, 117009013, N'Esther replied, “If the king is so inclined, let the Jews who are in Susa be permitted to act tomorrow also according to today’s law, and let them hang the ten sons of Haman on the gallows.”'
EXEC add_BibleVerse @BibleId, 117009014, N'So the king issued orders for this to be done. A law was passed in Susa, and the ten sons of Haman were hanged.'
EXEC add_BibleVerse @BibleId, 117009015, N'The Jews who were in Susa then assembled on the fourteenth day of the month of Adar, and they killed three hundred men in Susa. But they did not confiscate their property.'
EXEC add_BibleVerse @BibleId, 117009016, N'The rest of the Jews who were throughout the provinces of the king assembled in order to stand up for themselves and to have rest from their enemies. They killed seventy-five thousand of their adversaries, but they did not confiscate their property.'
EXEC add_BibleVerse @BibleId, 117009017, N'All of this happened on the thirteenth day of the month of Adar. They then rested on the fourteenth day and made it a day for banqueting and happiness.'
EXEC add_BibleVerse @BibleId, 117009018, N'But the Jews who were in Susa assembled on the thirteenth and fourteenth days, and rested on the fifteenth, making it a day for banqueting and happiness.'
EXEC add_BibleVerse @BibleId, 117009019, N'This is why the Jews who are in the rural country – those who live in rural cities – set aside the fourteenth day of the month of Adar as a holiday for happiness, banqueting, holiday, and sending gifts to one another.'
EXEC add_BibleVerse @BibleId, 117009020, N'Mordecai wrote these matters down and sent letters to all the Jews who were throughout all the provinces of King Ahasuerus, both near and far,'
EXEC add_BibleVerse @BibleId, 117009021, N'to have them observe the fourteenth and the fifteenth day of the month of Adar each year'
EXEC add_BibleVerse @BibleId, 117009022, N'as the time when the Jews gave themselves rest from their enemies – the month when their trouble was turned to happiness and their mourning to a holiday. These were to be days of banqueting, happiness, sending gifts to one another, and providing for the poor.'
EXEC add_BibleVerse @BibleId, 117009023, N'So the Jews committed themselves to continue what they had begun to do and to what Mordecai had written to them.'
EXEC add_BibleVerse @BibleId, 117009024, N'For Haman the son of Hammedatha, the Agagite, the enemy of all the Jews, had devised plans against the Jews to destroy them. He had cast pur (that is, the lot) in order to afflict and destroy them.'
EXEC add_BibleVerse @BibleId, 117009025, N'But when the matter came to the king’s attention, the king gave written orders that Haman’s evil intentions that he had devised against the Jews should fall on his own head. He and his sons were hanged on the gallows.'
EXEC add_BibleVerse @BibleId, 117009026, N'For this reason these days are known as Purim, after the name of pur.'
EXEC add_BibleVerse @BibleId, 117009027, N'Therefore, because of the account found in this letter and what they had faced in this regard and what had happened to them, the Jews established as binding on themselves, their descendants, and all who joined their company that they should observe these two days without fail, just as written and at the appropriate time on an annual basis.'
EXEC add_BibleVerse @BibleId, 117009028, N'These days were to be remembered and to be celebrated in every generation and in every family, every province, and every city. The Jews were not to fail to observe these days of Purim; the remembrance of them was not to cease among their descendants.'
EXEC add_BibleVerse @BibleId, 117009029, N'So Queen Esther, the daughter of Abihail, and Mordecai the Jew wrote with full authority to confirm this second letter about Purim.'
EXEC add_BibleVerse @BibleId, 117009030, N'Letters were sent to all the Jews in the hundred and twenty-seven provinces of the empire of Ahasuerus – words of true peace –'
EXEC add_BibleVerse @BibleId, 117009031, N'to establish these days of Purim in their proper times, just as Mordecai the Jew and Queen Esther had established, and just as they had established both for themselves and their descendants, matters pertaining to fasting and lamentation.'
EXEC add_BibleVerse @BibleId, 117009032, N'Esther’s command established these matters of Purim, and the matter was officially recorded.'
EXEC add_BibleVerse @BibleId, 117010001, N'King Ahasuerus then imposed forced labor on the land and on the coastlands of the sea.'
EXEC add_BibleVerse @BibleId, 117010002, N'Now all the actions carried out under his authority and his great achievements, along with an exact statement concerning the greatness of Mordecai, whom the king promoted, are they not written in the Book of the Chronicles of the Kings of Media and Persia?'
EXEC add_BibleVerse @BibleId, 117010003, N'Mordecai the Jew was second only to King Ahasuerus. He was the highest-ranking Jew, and he was admired by his numerous relatives. He worked enthusiastically for the good of his people and was an advocate for the welfare of all his descendants.'
EXEC add_BibleVerse @BibleId, 118001001, N'There was a man in the land of Uz whose name was Job. And that man was pure and upright, one who feared God and turned away from evil.'
EXEC add_BibleVerse @BibleId, 118001002, N'Seven sons and three daughters were born to him.'
EXEC add_BibleVerse @BibleId, 118001003, N'His possessions included 7,000 sheep, 3,000 camels, 500 yoke of oxen, and 500 female donkeys; in addition he had a very great household. Thus he was the greatest of all the people in the east.'
EXEC add_BibleVerse @BibleId, 118001004, N'Now his sons used to go and hold a feast in the house of each one in turn, and they would send and invite their three sisters to eat and to drink with them.'
EXEC add_BibleVerse @BibleId, 118001005, N'When the days of their feasting were finished, Job would send for them and sanctify them; he would get up early in the morning and offer burnt offerings according to the number of them all. For Job thought, “Perhaps my children have sinned and cursed God in their hearts.” This was Job’s customary practice.'
EXEC add_BibleVerse @BibleId, 118001006, N'Now the day came when the sons of God came to present themselves before the Lord – and Satan also arrived among them.'
EXEC add_BibleVerse @BibleId, 118001007, N'The Lord said to Satan, “Where have you come from?” And Satan answered the Lord, “From roving about on the earth, and from walking back and forth across it.”'
EXEC add_BibleVerse @BibleId, 118001008, N'So the Lord said to Satan, “Have you considered my servant Job? There is no one like him on the earth, a pure and upright man, one who fears God and turns away from evil.”'
EXEC add_BibleVerse @BibleId, 118001009, N'Then Satan answered the Lord, “Is it for nothing that Job fears God?'
EXEC add_BibleVerse @BibleId, 118001010, N'Have you not made a hedge around him and his household and all that he has on every side? You have blessed the work of his hands, and his livestock have increased in the land.'
EXEC add_BibleVerse @BibleId, 118001011, N'But extend your hand and strike everything he has, and he will no doubt curse you to your face!”'
EXEC add_BibleVerse @BibleId, 118001012, N'So the Lord said to Satan, “All right then, everything he has is in your power. Only do not extend your hand against the man himself!” So Satan went out from the presence of the Lord.'
EXEC add_BibleVerse @BibleId, 118001013, N'Now the day came when Job’s sons and daughters were eating and drinking wine in their oldest brother’s house,'
EXEC add_BibleVerse @BibleId, 118001014, N'and a messenger came to Job, saying, “The oxen were plowing and the donkeys were grazing beside them,'
EXEC add_BibleVerse @BibleId, 118001015, N'and the Sabeans swooped down and carried them all away, and they killed the servants with the sword! And I – only I alone – escaped to tell you!”'
EXEC add_BibleVerse @BibleId, 118001016, N'While this one was still speaking, another messenger arrived and said, “The fire of God has fallen from heaven and has burned up the sheep and the servants – it has consumed them! And I – only I alone – escaped to tell you!”'
EXEC add_BibleVerse @BibleId, 118001017, N'While this one was still speaking another messenger arrived and said, “The Chaldeans formed three bands and made a raid on the camels and carried them all away, and they killed the servants with the sword! And I – only I alone – escaped to tell you!”'
EXEC add_BibleVerse @BibleId, 118001018, N'While this one was still speaking another messenger arrived and said, “Your sons and your daughters were eating and drinking wine in their oldest brother’s house,'
EXEC add_BibleVerse @BibleId, 118001019, N'and suddenly a great wind swept across the wilderness and struck the four corners of the house, and it fell on the young people, and they died! And I – only I alone – escaped to tell you!”'
EXEC add_BibleVerse @BibleId, 118001020, N'Then Job got up and tore his robe. He shaved his head, and then he threw himself down with his face to the ground.'
EXEC add_BibleVerse @BibleId, 118001021, N'He said, “Naked I came from my mother’s womb, and naked I will return there. The Lord gives, and the Lord takes away. May the name of the Lord be blessed!”'
EXEC add_BibleVerse @BibleId, 118001022, N'In all this Job did not sin, nor did he charge God with moral impropriety.'
EXEC add_BibleVerse @BibleId, 118002001, N'Again the day came when the sons of God came to present themselves before the Lord, and Satan also arrived among them to present himself before the Lord.'
EXEC add_BibleVerse @BibleId, 118002002, N'And the Lord said to Satan, “Where do you come from?” Satan answered the Lord, “From roving about on the earth, and from walking back and forth across it.”'
EXEC add_BibleVerse @BibleId, 118002003, N'Then the Lord said to Satan, “Have you considered my servant Job? For there is no one like him on the earth, a pure and upright man, one who fears God and turns away from evil. And he still holds firmly to his integrity, so that you stirred me up to destroy him without reason.”'
EXEC add_BibleVerse @BibleId, 118002004, N'But Satan answered the Lord, “Skin for skin! Indeed, a man will give up all that he has to save his life!'
EXEC add_BibleVerse @BibleId, 118002005, N'But extend your hand and strike his bone and his flesh, and he will no doubt curse you to your face!”'
EXEC add_BibleVerse @BibleId, 118002006, N'So the Lord said to Satan, “All right, he is in your power; only preserve his life.”'
EXEC add_BibleVerse @BibleId, 118002007, N'So Satan went out from the presence of the Lord, and he afflicted Job with a malignant ulcer from the sole of his feet to the top of his head.'
EXEC add_BibleVerse @BibleId, 118002008, N'Job took a shard of broken pottery to scrape himself with while he was sitting among the ashes.'
EXEC add_BibleVerse @BibleId, 118002009, N'Then his wife said to him, “Are you still holding firmly to your integrity? Curse God, and die!”'
EXEC add_BibleVerse @BibleId, 118002010, N'But he replied, “You’re talking like one of the godless women would do! Should we receive what is good from God, and not also receive what is evil?” In all this Job did not sin by what he said.'
EXEC add_BibleVerse @BibleId, 118002011, N'When Job’s three friends heard about all this calamity that had happened to him, each of them came from his own country – Eliphaz the Temanite, Bildad the Shuhite, and Zophar the Naamathite. They met together to come to show sympathy for him and to console him.'
EXEC add_BibleVerse @BibleId, 118002012, N'But when they gazed intently from a distance but did not recognize him, they began to weep loudly. Each of them tore his robes, and they threw dust into the air over their heads.'
EXEC add_BibleVerse @BibleId, 118002013, N'Then they sat down with him on the ground for seven days and seven nights, yet no one spoke a word to him, for they saw that his pain was very great.'
EXEC add_BibleVerse @BibleId, 118003001, N'After this Job opened his mouth and cursed the day he was born.'
EXEC add_BibleVerse @BibleId, 118003002, N'Job spoke up and said:'
EXEC add_BibleVerse @BibleId, 118003003, N'“Let the day on which I was born perish, and the night that said, ‘A man has been conceived!’'
EXEC add_BibleVerse @BibleId, 118003004, N'That day – let it be darkness; let not God on high regard it, nor let light shine on it!'
EXEC add_BibleVerse @BibleId, 118003005, N'Let darkness and the deepest shadow claim it; let a cloud settle on it; let whatever blackens the day terrify it!'
EXEC add_BibleVerse @BibleId, 118003006, N'That night – let darkness seize it; let it not be included among the days of the year; let it not enter among the number of the months!'
EXEC add_BibleVerse @BibleId, 118003007, N'Indeed, let that night be barren; let no shout of joy penetrate it!'
EXEC add_BibleVerse @BibleId, 118003008, N'Let those who curse the day curse it – those who are prepared to rouse Leviathan.'
EXEC add_BibleVerse @BibleId, 118003009, N'Let its morning stars be darkened; let it wait for daylight but find none, nor let it see the first rays of dawn,'
EXEC add_BibleVerse @BibleId, 118003010, N'because it did not shut the doors of my mother’s womb on me, nor did it hide trouble from my eyes!'
EXEC add_BibleVerse @BibleId, 118003011, N'“Why did I not die at birth, and why did I not expire as I came out of the womb?'
EXEC add_BibleVerse @BibleId, 118003012, N'Why did the knees welcome me, and why were there two breasts that I might nurse at them?'
EXEC add_BibleVerse @BibleId, 118003013, N'For now I would be lying down and would be quiet, I would be asleep and then at peace'
EXEC add_BibleVerse @BibleId, 118003014, N'with kings and counselors of the earth who built for themselves places now desolate,'
EXEC add_BibleVerse @BibleId, 118003015, N'or with princes who possessed gold, who filled their palaces with silver.'
EXEC add_BibleVerse @BibleId, 118003016, N'Or why was I not buried like a stillborn infant, like infants who have never seen the light?'
EXEC add_BibleVerse @BibleId, 118003017, N'There the wicked cease from turmoil, and there the weary are at rest.'
EXEC add_BibleVerse @BibleId, 118003018, N'There the prisoners relax together; they do not hear the voice of the oppressor.'
EXEC add_BibleVerse @BibleId, 118003019, N'Small and great are there, and the slave is free from his master.'
EXEC add_BibleVerse @BibleId, 118003020, N'“Why does God give light to one who is in misery, and life to those whose soul is bitter,'
EXEC add_BibleVerse @BibleId, 118003021, N'to those who wait for death that does not come, and search for it more than for hidden treasures,'
EXEC add_BibleVerse @BibleId, 118003022, N'who rejoice even to jubilation, and are exultant when they find the grave?'
EXEC add_BibleVerse @BibleId, 118003023, N'Why is light given to a man whose way is hidden, and whom God has hedged in?'
EXEC add_BibleVerse @BibleId, 118003024, N'For my sighing comes in place of my food, and my groanings flow forth like water.'
EXEC add_BibleVerse @BibleId, 118003025, N'For the very thing I dreaded has happened to me, and what I feared has come upon me.'
EXEC add_BibleVerse @BibleId, 118003026, N'I have no ease, I have no quietness; I cannot rest; turmoil has come upon me.”'
EXEC add_BibleVerse @BibleId, 118004001, N'Then Eliphaz the Temanite answered:'
EXEC add_BibleVerse @BibleId, 118004002, N'“If someone should attempt a word with you, will you be impatient? But who can refrain from speaking ?'
EXEC add_BibleVerse @BibleId, 118004003, N'Look, you have instructed many; you have strengthened feeble hands.'
EXEC add_BibleVerse @BibleId, 118004004, N'Your words have supported those who stumbled, and you have strengthened the knees that gave way.'
EXEC add_BibleVerse @BibleId, 118004005, N'But now the same thing comes to you, and you are discouraged; it strikes you, and you are terrified.'
EXEC add_BibleVerse @BibleId, 118004006, N'Is not your piety your confidence, and your blameless ways your hope?'
EXEC add_BibleVerse @BibleId, 118004007, N'Call to mind now: Who, being innocent, ever perished? And where were upright people ever destroyed?'
EXEC add_BibleVerse @BibleId, 118004008, N'Even as I have seen, those who plow iniquity and those who sow trouble reap the same.'
EXEC add_BibleVerse @BibleId, 118004009, N'By the breath of God they perish, and by the blast of his anger they are consumed.'
EXEC add_BibleVerse @BibleId, 118004010, N'There is the roaring of the lion and the growling of the young lion, but the teeth of the young lions are broken.'
EXEC add_BibleVerse @BibleId, 118004011, N'The mighty lion perishes for lack of prey, and the cubs of the lioness are scattered.'
EXEC add_BibleVerse @BibleId, 118004012, N'“Now a word was secretly brought to me, and my ear caught a whisper of it.'
EXEC add_BibleVerse @BibleId, 118004013, N'In the troubling thoughts of the dreams in the night when a deep sleep falls on men,'
EXEC add_BibleVerse @BibleId, 118004014, N'a trembling gripped me – and a terror! – and made all my bones shake.'
EXEC add_BibleVerse @BibleId, 118004015, N'Then a breath of air passes by my face; it makes the hair of my flesh stand up.'
EXEC add_BibleVerse @BibleId, 118004016, N'It stands still, but I cannot recognize its appearance; an image is before my eyes, and I hear a murmuring voice:'
EXEC add_BibleVerse @BibleId, 118004017, N'“Is a mortal man righteous before God? Or a man pure before his Creator?'
EXEC add_BibleVerse @BibleId, 118004018, N'If God puts no trust in his servants and attributes folly to his angels,'
EXEC add_BibleVerse @BibleId, 118004019, N'how much more to those who live in houses of clay, whose foundation is in the dust, who are crushed like a moth?'
EXEC add_BibleVerse @BibleId, 118004020, N'They are destroyed between morning and evening; they perish forever without anyone regarding it.'
EXEC add_BibleVerse @BibleId, 118004021, N'Is not their excess wealth taken away from them? They die, yet without attaining wisdom.'
EXEC add_BibleVerse @BibleId, 118005001, N'“Call now! Is there anyone who will answer you? To which of the holy ones will you turn?'
EXEC add_BibleVerse @BibleId, 118005002, N'For wrath kills the foolish person, and anger slays the silly one.'
EXEC add_BibleVerse @BibleId, 118005003, N'I myself have seen the fool taking root, but suddenly I cursed his place of residence.'
EXEC add_BibleVerse @BibleId, 118005004, N'His children are far from safety, and they are crushed at the place where judgment is rendered, nor is there anyone to deliver them.'
EXEC add_BibleVerse @BibleId, 118005005, N'The hungry eat up his harvest, and take it even from behind the thorns, and the thirsty swallow up their fortune.'
EXEC add_BibleVerse @BibleId, 118005006, N'For evil does not come up from the dust, nor does trouble spring up from the ground,'
EXEC add_BibleVerse @BibleId, 118005007, N'but people are born to trouble, as surely as the sparks fly upward.'
EXEC add_BibleVerse @BibleId, 118005008, N'“But as for me, I would seek God, and to God I would set forth my case.'
EXEC add_BibleVerse @BibleId, 118005009, N'He does great and unsearchable things, marvelous things without number;'
EXEC add_BibleVerse @BibleId, 118005010, N'he gives rain on the earth, and sends water on the fields;'
EXEC add_BibleVerse @BibleId, 118005011, N'he sets the lowly on high, that those who mourn are raised to safety.'
EXEC add_BibleVerse @BibleId, 118005012, N'He frustrates the plans of the crafty so that their hands cannot accomplish what they had planned!'
EXEC add_BibleVerse @BibleId, 118005013, N'He catches the wise in their own craftiness, and the counsel of the cunning is brought to a quick end.'
EXEC add_BibleVerse @BibleId, 118005014, N'They meet with darkness in the daytime, and grope about in the noontime as if it were night.'
EXEC add_BibleVerse @BibleId, 118005015, N'So he saves from the sword that comes from their mouth, even the poor from the hand of the powerful.'
EXEC add_BibleVerse @BibleId, 118005016, N'Thus the poor have hope, and iniquity shuts its mouth.'
EXEC add_BibleVerse @BibleId, 118005017, N'“Therefore, blessed is the man whom God corrects, so do not despise the discipline of the Almighty.'
EXEC add_BibleVerse @BibleId, 118005018, N'For he wounds, but he also bandages; he strikes, but his hands also heal.'
EXEC add_BibleVerse @BibleId, 118005019, N'He will deliver you from six calamities; yes, in seven no evil will touch you.'
EXEC add_BibleVerse @BibleId, 118005020, N'In time of famine he will redeem you from death, and in time of war from the power of the sword.'
EXEC add_BibleVerse @BibleId, 118005021, N'You will be protected from malicious gossip, and will not be afraid of the destruction when it comes.'
EXEC add_BibleVerse @BibleId, 118005022, N'You will laugh at destruction and famine and need not be afraid of the beasts of the earth.'
EXEC add_BibleVerse @BibleId, 118005023, N'For you will have a pact with the stones of the field, and the wild animals will be at peace with you.'
EXEC add_BibleVerse @BibleId, 118005024, N'And you will know that your home will be secure, and when you inspect your domains, you will not be missing anything.'
EXEC add_BibleVerse @BibleId, 118005025, N'You will also know that your children will be numerous, and your descendants like the grass of the earth.'
EXEC add_BibleVerse @BibleId, 118005026, N'You will come to your grave in a full age, As stacks of grain are harvested in their season.'
EXEC add_BibleVerse @BibleId, 118005027, N'Look, we have investigated this, so it is true. Hear it, and apply it for your own good.”'
EXEC add_BibleVerse @BibleId, 118006001, N'Then Job responded:'
EXEC add_BibleVerse @BibleId, 118006002, N'“Oh, if only my grief could be weighed, and my misfortune laid on the scales too!'
EXEC add_BibleVerse @BibleId, 118006003, N'But because it is heavier than the sand of the sea, that is why my words have been wild.'
EXEC add_BibleVerse @BibleId, 118006004, N'For the arrows of the Almighty are within me; my spirit drinks their poison; God’s sudden terrors are arrayed against me.'
EXEC add_BibleVerse @BibleId, 118006005, N'“Does the wild donkey bray when it is near grass? Or does the ox low near its fodder?'
EXEC add_BibleVerse @BibleId, 118006006, N'Can food that is tasteless be eaten without salt? Or is there any taste in the white of an egg?'
EXEC add_BibleVerse @BibleId, 118006007, N'I have refused to touch such things; they are like loathsome food to me.'
EXEC add_BibleVerse @BibleId, 118006008, N'“Oh that my request would be realized, and that God would grant me what I long for!'
EXEC add_BibleVerse @BibleId, 118006009, N'And that God would be willing to crush me, that he would let loose his hand and kill me.'
EXEC add_BibleVerse @BibleId, 118006010, N'Then I would yet have my comfort, then I would rejoice, in spite of pitiless pain, for I have not concealed the words of the Holy One.'
EXEC add_BibleVerse @BibleId, 118006011, N'What is my strength, that I should wait? and what is my end, that I should prolong my life?'
EXEC add_BibleVerse @BibleId, 118006012, N'Is my strength like that of stones? or is my flesh made of bronze?'
EXEC add_BibleVerse @BibleId, 118006013, N'Is not my power to help myself nothing, and has not every resource been driven from me?'
EXEC add_BibleVerse @BibleId, 118006014, N'“To the one in despair, kindness should come from his friend even if he forsakes the fear of the Almighty.'
EXEC add_BibleVerse @BibleId, 118006015, N'My brothers have been as treacherous as a seasonal stream, and as the riverbeds of the intermittent streams that flow away.'
EXEC add_BibleVerse @BibleId, 118006016, N'They are dark because of ice; snow is piled up over them.'
EXEC add_BibleVerse @BibleId, 118006017, N'When they are scorched, they dry up, when it is hot, they vanish from their place.'
EXEC add_BibleVerse @BibleId, 118006018, N'Caravans turn aside from their routes; they go into the wasteland and perish.'
EXEC add_BibleVerse @BibleId, 118006019, N'The caravans of Tema looked intently for these streams; the traveling merchants of Sheba hoped for them.'
EXEC add_BibleVerse @BibleId, 118006020, N'They were distressed, because each one had been so confident; they arrived there, but were disappointed.'
EXEC add_BibleVerse @BibleId, 118006021, N'For now you have become like these streams that are no help; you see a terror, and are afraid.'
EXEC add_BibleVerse @BibleId, 118006022, N'“Have I ever said, ‘Give me something, and from your fortune make gifts in my favor’?'
EXEC add_BibleVerse @BibleId, 118006023, N'Or ‘Deliver me from the enemy’s power, and from the hand of tyrants ransom me’?'
EXEC add_BibleVerse @BibleId, 118006024, N'“Teach me and I, for my part, will be silent; explain to me how I have been mistaken.'
EXEC add_BibleVerse @BibleId, 118006025, N'How painful are honest words! But what does your reproof prove?'
EXEC add_BibleVerse @BibleId, 118006026, N'Do you intend to criticize mere words, and treat the words of a despairing man as wind?'
EXEC add_BibleVerse @BibleId, 118006027, N'Yes, you would gamble for the fatherless, and auction off your friend.'
EXEC add_BibleVerse @BibleId, 118006028, N'“Now then, be good enough to look at me; and I will not lie to your face!'
EXEC add_BibleVerse @BibleId, 118006029, N'Relent, let there be no falsehood; reconsider, for my righteousness is intact!'
EXEC add_BibleVerse @BibleId, 118006030, N'Is there any falsehood on my lips? Can my mouth not discern evil things?'
EXEC add_BibleVerse @BibleId, 118007001, N'“Does not humanity have hard service on earth? Are not their days also like the days of a hired man?'
EXEC add_BibleVerse @BibleId, 118007002, N'Like a servant longing for the evening shadow, and like a hired man looking for his wages,'
EXEC add_BibleVerse @BibleId, 118007003, N'thus I have been made to inherit months of futility, and nights of sorrow have been appointed to me.'
EXEC add_BibleVerse @BibleId, 118007004, N'If I lie down, I say, ‘When will I arise?’, and the night stretches on and I toss and turn restlessly until the day dawns.'
EXEC add_BibleVerse @BibleId, 118007005, N'My body is clothed with worms and dirty scabs; my skin is broken and festering.'
EXEC add_BibleVerse @BibleId, 118007006, N'My days are swifter than a weaver’s shuttle and they come to an end without hope.'
EXEC add_BibleVerse @BibleId, 118007007, N'Remember that my life is but a breath, that my eyes will never again see happiness.'
EXEC add_BibleVerse @BibleId, 118007008, N'The eye of him who sees me now will see me no more; your eyes will look for me, but I will be gone.'
EXEC add_BibleVerse @BibleId, 118007009, N'As a cloud is dispersed and then disappears, so the one who goes down to the grave does not come up again.'
EXEC add_BibleVerse @BibleId, 118007010, N'He returns no more to his house, nor does his place of residence know him any more.'
EXEC add_BibleVerse @BibleId, 118007011, N'“Therefore, I will not refrain my mouth; I will speak in the anguish of my spirit; I will complain in the bitterness of my soul.'
EXEC add_BibleVerse @BibleId, 118007012, N'Am I the sea, or the creature of the deep, that you must put me under guard?'
EXEC add_BibleVerse @BibleId, 118007013, N'If I say, “My bed will comfort me, my couch will ease my complaint,”'
EXEC add_BibleVerse @BibleId, 118007014, N'then you scare me with dreams and terrify me with visions,'
EXEC add_BibleVerse @BibleId, 118007015, N'so that I would prefer strangling, and death more than life.'
EXEC add_BibleVerse @BibleId, 118007016, N'I loathe it; I do not want to live forever; leave me alone, for my days are a vapor!'
EXEC add_BibleVerse @BibleId, 118007017, N'“What is mankind that you make so much of them, and that you pay attention to them?'
EXEC add_BibleVerse @BibleId, 118007018, N'And that you visit them every morning, and try them every moment?'
EXEC add_BibleVerse @BibleId, 118007019, N'Will you never look away from me, will you not let me alone long enough to swallow my spittle?'
EXEC add_BibleVerse @BibleId, 118007020, N'If I have sinned – what have I done to you, O watcher of men? Why have you set me as your target? Have I become a burden to you?'
EXEC add_BibleVerse @BibleId, 118007021, N'And why do you not pardon my transgression, and take away my iniquity? For now I will lie down in the dust, and you will seek me diligently, but I will be gone.”'
EXEC add_BibleVerse @BibleId, 118008001, N'Then Bildad the Shuhite spoke up and said:'
EXEC add_BibleVerse @BibleId, 118008002, N'“How long will you speak these things, seeing that the words of your mouth are like a great wind?'
EXEC add_BibleVerse @BibleId, 118008003, N'Does God pervert justice? Or does the Almighty pervert what is right?'
EXEC add_BibleVerse @BibleId, 118008004, N'If your children sinned against him, he gave them over to the penalty of their sin.'
EXEC add_BibleVerse @BibleId, 118008005, N'But if you will look to God, and make your supplication to the Almighty,'
EXEC add_BibleVerse @BibleId, 118008006, N'if you become pure and upright, even now he will rouse himself for you, and will restore your righteous abode.'
EXEC add_BibleVerse @BibleId, 118008007, N'Your beginning will seem so small, since your future will flourish.'
EXEC add_BibleVerse @BibleId, 118008008, N'“For inquire now of the former generation, and pay attention to the findings of their ancestors;'
EXEC add_BibleVerse @BibleId, 118008009, N'For we were born yesterday and do not have knowledge, since our days on earth are but a shadow.'
EXEC add_BibleVerse @BibleId, 118008010, N'Will they not instruct you and speak to you, and bring forth words from their understanding?'
EXEC add_BibleVerse @BibleId, 118008011, N'Can the papyrus plant grow tall where there is no marsh? Can reeds flourish without water?'
EXEC add_BibleVerse @BibleId, 118008012, N'While they are still beginning to flower and not ripe for cutting, they can wither away faster than any grass!'
EXEC add_BibleVerse @BibleId, 118008013, N'Such is the destiny of all who forget God; the hope of the godless perishes,'
EXEC add_BibleVerse @BibleId, 118008014, N'whose trust is in something futile, whose security is a spider’s web.'
EXEC add_BibleVerse @BibleId, 118008015, N'He leans against his house but it does not hold up, he takes hold of it but it does not stand.'
EXEC add_BibleVerse @BibleId, 118008016, N'He is a well-watered plant in the sun, its shoots spread over its garden.'
EXEC add_BibleVerse @BibleId, 118008017, N'It wraps its roots around a heap of stones and it looks for a place among stones.'
EXEC add_BibleVerse @BibleId, 118008018, N'If he is uprooted from his place, then that place will disown him, saying, ‘I have never seen you!’'
EXEC add_BibleVerse @BibleId, 118008019, N'Indeed, this is the joy of his way, and out of the earth others spring up.'
EXEC add_BibleVerse @BibleId, 118008020, N'“Surely, God does not reject a blameless man, nor does he grasp the hand of the evildoers.'
EXEC add_BibleVerse @BibleId, 118008021, N'He will yet fill your mouth with laughter, and your lips with gladness.'
EXEC add_BibleVerse @BibleId, 118008022, N'Those who hate you will be clothed with shame, and the tent of the wicked will be no more.”'
EXEC add_BibleVerse @BibleId, 118009001, N'Then Job answered:'
EXEC add_BibleVerse @BibleId, 118009002, N'“Truly, I know that this is so. But how can a human be just before God?'
EXEC add_BibleVerse @BibleId, 118009003, N'If someone wishes to contend with him, he cannot answer him one time in a thousand.'
EXEC add_BibleVerse @BibleId, 118009004, N'He is wise in heart and mighty in strength – who has resisted him and remained safe?'
EXEC add_BibleVerse @BibleId, 118009005, N'He who removes mountains suddenly, who overturns them in his anger;'
EXEC add_BibleVerse @BibleId, 118009006, N'he who shakes the earth out of its place so that its pillars tremble;'
EXEC add_BibleVerse @BibleId, 118009007, N'he who commands the sun and it does not shine and seals up the stars;'
EXEC add_BibleVerse @BibleId, 118009008, N'he alone spreads out the heavens, and treads on the waves of the sea;'
EXEC add_BibleVerse @BibleId, 118009009, N'he makes the Bear, Orion, and the Pleiades, and the constellations of the southern sky;'
EXEC add_BibleVerse @BibleId, 118009010, N'he does great and unsearchable things, and wonderful things without number.'
EXEC add_BibleVerse @BibleId, 118009011, N'If he passes by me, I cannot see him, if he goes by, I cannot perceive him.'
EXEC add_BibleVerse @BibleId, 118009012, N'If he snatches away, who can turn him back? Who dares to say to him, ‘What are you doing?’'
EXEC add_BibleVerse @BibleId, 118009013, N'God does not restrain his anger; under him the helpers of Rahab lie crushed.'
EXEC add_BibleVerse @BibleId, 118009014, N'“How much less, then, can I answer him and choose my words to argue with him!'
EXEC add_BibleVerse @BibleId, 118009015, N'Although I am innocent, I could not answer him; I could only plead with my judge for mercy.'
EXEC add_BibleVerse @BibleId, 118009016, N'If I summoned him, and he answered me, I would not believe that he would be listening to my voice –'
EXEC add_BibleVerse @BibleId, 118009017, N'he who crushes me with a tempest, and multiplies my wounds for no reason.'
EXEC add_BibleVerse @BibleId, 118009018, N'He does not allow me to recover my breath, for he fills me with bitterness.'
EXEC add_BibleVerse @BibleId, 118009019, N'If it is a matter of strength, most certainly he is the strong one! And if it is a matter of justice, he will say, ‘Who will summon me?’'
EXEC add_BibleVerse @BibleId, 118009020, N'Although I am innocent, my mouth would condemn me; although I am blameless, it would declare me perverse.'
EXEC add_BibleVerse @BibleId, 118009021, N'I am blameless. I do not know myself. I despise my life.'
EXEC add_BibleVerse @BibleId, 118009022, N'“It is all one! That is why I say, ‘He destroys the blameless and the guilty.’'
EXEC add_BibleVerse @BibleId, 118009023, N'If a scourge brings sudden death, he mocks at the despair of the innocent.'
EXEC add_BibleVerse @BibleId, 118009024, N'If a land has been given into the hand of a wicked man, he covers the faces of its judges; if it is not he, then who is it?'
EXEC add_BibleVerse @BibleId, 118009025, N'“My days are swifter than a runner, they speed by without seeing happiness.'
EXEC add_BibleVerse @BibleId, 118009026, N'They glide by like reed boats, like an eagle that swoops down on its prey.'
EXEC add_BibleVerse @BibleId, 118009027, N'If I say, ‘I will forget my complaint, I will change my expression and be cheerful,’'
EXEC add_BibleVerse @BibleId, 118009028, N'I dread all my sufferings, for I know that you do not hold me blameless.'
EXEC add_BibleVerse @BibleId, 118009029, N'If I am guilty, why then weary myself in vain?'
EXEC add_BibleVerse @BibleId, 118009030, N'If I wash myself with snow water, and make my hands clean with lye,'
EXEC add_BibleVerse @BibleId, 118009031, N'then you plunge me into a slimy pit and my own clothes abhor me.'
EXEC add_BibleVerse @BibleId, 118009032, N'For he is not a human being like I am, that I might answer him, that we might come together in judgment.'
EXEC add_BibleVerse @BibleId, 118009033, N'Nor is there an arbiter between us, who might lay his hand on us both,'
EXEC add_BibleVerse @BibleId, 118009034, N'who would take his rod away from me so that his terror would not make me afraid.'
EXEC add_BibleVerse @BibleId, 118009035, N'Then would I speak and not fear him, but it is not so with me.'
EXEC add_BibleVerse @BibleId, 118010001, N'“I am weary of my life; I will complain without restraint; I will speak in the bitterness of my soul.'
EXEC add_BibleVerse @BibleId, 118010002, N'I will say to God, ‘Do not condemn me; tell me why you are contending with me.’'
EXEC add_BibleVerse @BibleId, 118010003, N'Is it good for you to oppress, to despise the work of your hands, while you smile on the schemes of the wicked?'
EXEC add_BibleVerse @BibleId, 118010004, N'“Do you have eyes of flesh, or do you see as a human being sees?'
EXEC add_BibleVerse @BibleId, 118010005, N'Are your days like the days of a mortal, or your years like the years of a mortal,'
EXEC add_BibleVerse @BibleId, 118010006, N'that you must search out my iniquity, and inquire about my sin,'
EXEC add_BibleVerse @BibleId, 118010007, N'although you know that I am not guilty, and that there is no one who can deliver out of your hand?'
EXEC add_BibleVerse @BibleId, 118010008, N'“Your hands have shaped me and made me, but now you destroy me completely.'
EXEC add_BibleVerse @BibleId, 118010009, N'Remember that you have made me as with the clay; will you return me to dust?'
EXEC add_BibleVerse @BibleId, 118010010, N'Did you not pour me out like milk, and curdle me like cheese?'
EXEC add_BibleVerse @BibleId, 118010011, N'You clothed me with skin and flesh and knit me together with bones and sinews.'
EXEC add_BibleVerse @BibleId, 118010012, N'You gave me life and favor, and your intervention watched over my spirit.'
EXEC add_BibleVerse @BibleId, 118010013, N'“But these things you have concealed in your heart; I know that this is with you:'
EXEC add_BibleVerse @BibleId, 118010014, N'If I sinned, then you would watch me and you would not acquit me of my iniquity.'
EXEC add_BibleVerse @BibleId, 118010015, N'If I am guilty, woe to me, and if I am innocent, I cannot lift my head; I am full of shame, and satiated with my affliction.'
EXEC add_BibleVerse @BibleId, 118010016, N'If I lift myself up, you hunt me as a fierce lion, and again you display your power against me.'
EXEC add_BibleVerse @BibleId, 118010017, N'You bring new witnesses against me, and increase your anger against me; relief troops come against me.'
EXEC add_BibleVerse @BibleId, 118010018, N'“Why then did you bring me out from the womb? I should have died and no eye would have seen me!'
EXEC add_BibleVerse @BibleId, 118010019, N'I should have been as though I had never existed; I should have been carried right from the womb to the grave!'
EXEC add_BibleVerse @BibleId, 118010020, N'Are not my days few? Cease, then, and leave me alone, that I may find a little comfort,'
EXEC add_BibleVerse @BibleId, 118010021, N'before I depart, never to return, to the land of darkness and the deepest shadow,'
EXEC add_BibleVerse @BibleId, 118010022, N'to the land of utter darkness, like the deepest darkness, and the deepest shadow and disorder, where even the light is like darkness.”'
EXEC add_BibleVerse @BibleId, 118011001, N'Then Zophar the Naamathite spoke up and said:'
EXEC add_BibleVerse @BibleId, 118011002, N'“Should not this abundance of words be answered, or should this talkative man be vindicated?'
EXEC add_BibleVerse @BibleId, 118011003, N'Will your idle talk reduce people to silence, and will no one rebuke you when you mock?'
EXEC add_BibleVerse @BibleId, 118011004, N'For you have said, ‘My teaching is flawless, and I am pure in your sight.’'
EXEC add_BibleVerse @BibleId, 118011005, N'But if only God would speak, if only he would open his lips against you,'
EXEC add_BibleVerse @BibleId, 118011006, N'and reveal to you the secrets of wisdom – for true wisdom has two sides – so that you would know that God has forgiven some of your sins.'
EXEC add_BibleVerse @BibleId, 118011007, N'“Can you discover the essence of God? Can you find out the perfection of the Almighty?'
EXEC add_BibleVerse @BibleId, 118011008, N'It is higher than the heavens – what can you do? It is deeper than Sheol – what can you know?'
EXEC add_BibleVerse @BibleId, 118011009, N'Its measure is longer than the earth, and broader than the sea.'
EXEC add_BibleVerse @BibleId, 118011010, N'If he comes by and confines you and convenes a court, then who can prevent him?'
EXEC add_BibleVerse @BibleId, 118011011, N'For he knows deceitful men; when he sees evil, will he not consider it?'
EXEC add_BibleVerse @BibleId, 118011012, N'But an empty man will become wise, when a wild donkey’s colt is born a human being.'
EXEC add_BibleVerse @BibleId, 118011013, N'“As for you, if you prove faithful, and if you stretch out your hands toward him,'
EXEC add_BibleVerse @BibleId, 118011014, N'if iniquity is in your hand – put it far away, and do not let evil reside in your tents.'
EXEC add_BibleVerse @BibleId, 118011015, N'For then you will lift up your face without blemish; you will be securely established and will not fear.'
EXEC add_BibleVerse @BibleId, 118011016, N'For you will forget your trouble; you will remember it like water that has flowed away.'
EXEC add_BibleVerse @BibleId, 118011017, N'And life will be brighter than the noonday; though there be darkness, it will be like the morning.'
EXEC add_BibleVerse @BibleId, 118011018, N'And you will be secure, because there is hope; you will be protected and will take your rest in safety.'
EXEC add_BibleVerse @BibleId, 118011019, N'You will lie down with no one to make you afraid, and many will seek your favor.'
EXEC add_BibleVerse @BibleId, 118011020, N'But the eyes of the wicked fail, and escape eludes them; their one hope is to breathe their last.”'
EXEC add_BibleVerse @BibleId, 118012001, N'Then Job answered:'
EXEC add_BibleVerse @BibleId, 118012002, N'“Without a doubt you are the people, and wisdom will die with you.'
EXEC add_BibleVerse @BibleId, 118012003, N'I also have understanding as well as you; I am not inferior to you. Who does not know such things as these?'
EXEC add_BibleVerse @BibleId, 118012004, N'I am a laughingstock to my friends, I, who called on God and whom he answered – a righteous and blameless man is a laughingstock!'
EXEC add_BibleVerse @BibleId, 118012005, N'For calamity, there is derision (according to the ideas of the fortunate ) – a fate for those whose feet slip!'
EXEC add_BibleVerse @BibleId, 118012006, N'But the tents of robbers are peaceful, and those who provoke God are confident – who carry their god in their hands.'
EXEC add_BibleVerse @BibleId, 118012007, N'“But now, ask the animals and they will teach you, or the birds of the sky and they will tell you.'
EXEC add_BibleVerse @BibleId, 118012008, N'Or speak to the earth and it will teach you, or let the fish of the sea declare to you.'
EXEC add_BibleVerse @BibleId, 118012009, N'Which of all these does not know that the hand of the Lord has done this,'
EXEC add_BibleVerse @BibleId, 118012010, N'in whose hand is the life of every creature and the breath of all the human race.'
EXEC add_BibleVerse @BibleId, 118012011, N'Does not the ear test words, as the tongue tastes food?'
EXEC add_BibleVerse @BibleId, 118012012, N'Is not wisdom found among the aged? Does not long life bring understanding?'
EXEC add_BibleVerse @BibleId, 118012013, N'“With God are wisdom and power; counsel and understanding are his.'
EXEC add_BibleVerse @BibleId, 118012014, N'If he tears down, it cannot be rebuilt; if he imprisons a person, there is no escape.'
EXEC add_BibleVerse @BibleId, 118012015, N'If he holds back the waters, then they dry up; if he releases them, they destroy the land.'
EXEC add_BibleVerse @BibleId, 118012016, N'With him are strength and prudence; both the one who goes astray and the one who misleads are his.'
EXEC add_BibleVerse @BibleId, 118012017, N'He leads counselors away stripped and makes judges into fools.'
EXEC add_BibleVerse @BibleId, 118012018, N'He loosens the bonds of kings and binds a loincloth around their waist.'
EXEC add_BibleVerse @BibleId, 118012019, N'He leads priests away stripped and overthrows the potentates.'
EXEC add_BibleVerse @BibleId, 118012020, N'He deprives the trusted advisers of speech and takes away the discernment of elders.'
EXEC add_BibleVerse @BibleId, 118012021, N'He pours contempt on noblemen and disarms the powerful.'
EXEC add_BibleVerse @BibleId, 118012022, N'He reveals the deep things of darkness, and brings deep shadows into the light.'
EXEC add_BibleVerse @BibleId, 118012023, N'He makes nations great, and destroys them; he extends the boundaries of nations and disperses them.'
EXEC add_BibleVerse @BibleId, 118012024, N'He deprives the leaders of the earth of their understanding; he makes them wander in a trackless desert waste.'
EXEC add_BibleVerse @BibleId, 118012025, N'They grope about in darkness without light; he makes them stagger like drunkards.'
EXEC add_BibleVerse @BibleId, 118013001, N'“Indeed, my eyes have seen all this, my ears have heard and understood it.'
EXEC add_BibleVerse @BibleId, 118013002, N'What you know, I know also; I am not inferior to you!'
EXEC add_BibleVerse @BibleId, 118013003, N'But I wish to speak to the Almighty, and I desire to argue my case with God.'
EXEC add_BibleVerse @BibleId, 118013004, N'But you, however, are inventors of lies; all of you are worthless physicians!'
EXEC add_BibleVerse @BibleId, 118013005, N'If only you would keep completely silent! For you, that would be wisdom.'
EXEC add_BibleVerse @BibleId, 118013006, N'“Listen now to my argument, and be attentive to my lips’ contentions.'
EXEC add_BibleVerse @BibleId, 118013007, N'Will you speak wickedly on God’s behalf? Will you speak deceitfully for him?'
EXEC add_BibleVerse @BibleId, 118013008, N'Will you show him partiality? Will you argue the case for God?'
EXEC add_BibleVerse @BibleId, 118013009, N'Would it turn out well if he would examine you? Or as one deceives a man would you deceive him?'
EXEC add_BibleVerse @BibleId, 118013010, N'He would certainly rebuke you if you secretly showed partiality!'
EXEC add_BibleVerse @BibleId, 118013011, N'Would not his splendor terrify you and the fear he inspires fall on you?'
EXEC add_BibleVerse @BibleId, 118013012, N'Your maxims are proverbs of ashes; your defenses are defenses of clay.'
EXEC add_BibleVerse @BibleId, 118013013, N'“Refrain from talking with me so that I may speak; then let come to me what may.'
EXEC add_BibleVerse @BibleId, 118013014, N'Why do I put myself in peril, and take my life in my hands?'
EXEC add_BibleVerse @BibleId, 118013015, N'Even if he slays me, I will hope in him; I will surely defend my ways to his face!'
EXEC add_BibleVerse @BibleId, 118013016, N'Moreover, this will become my deliverance, for no godless person would come before him.'
EXEC add_BibleVerse @BibleId, 118013017, N'Listen carefully to my words; let your ears be attentive to my explanation.'
EXEC add_BibleVerse @BibleId, 118013018, N'See now, I have prepared my case; I know that I am right.'
EXEC add_BibleVerse @BibleId, 118013019, N'Who will contend with me? If anyone can, I will be silent and die.'
EXEC add_BibleVerse @BibleId, 118013020, N'Only in two things spare me, O God, and then I will not hide from your face:'
EXEC add_BibleVerse @BibleId, 118013021, N'Remove your hand far from me and stop making me afraid with your terror.'
EXEC add_BibleVerse @BibleId, 118013022, N'Then call, and I will answer, or I will speak, and you respond to me.'
EXEC add_BibleVerse @BibleId, 118013023, N'How many are my iniquities and sins? Show me my transgression and my sin.'
EXEC add_BibleVerse @BibleId, 118013024, N'Why do you hide your face and regard me as your enemy?'
EXEC add_BibleVerse @BibleId, 118013025, N'Do you wish to torment a windblown leaf and chase after dry chaff?'
EXEC add_BibleVerse @BibleId, 118013026, N'For you write down bitter things against me and cause me to inherit the sins of my youth.'
EXEC add_BibleVerse @BibleId, 118013027, N'And you put my feet in the stocks and you watch all my movements; you put marks on the soles of my feet.'
EXEC add_BibleVerse @BibleId, 118013028, N'So I waste away like something rotten, like a garment eaten by moths.'
EXEC add_BibleVerse @BibleId, 118014001, N'“Man, born of woman, lives but a few days, and they are full of trouble.'
EXEC add_BibleVerse @BibleId, 118014002, N'He grows up like a flower and then withers away; he flees like a shadow, and does not remain.'
EXEC add_BibleVerse @BibleId, 118014003, N'Do you fix your eye on such a one? And do you bring me before you for judgment?'
EXEC add_BibleVerse @BibleId, 118014004, N'Who can make a clean thing come from an unclean? No one!'
EXEC add_BibleVerse @BibleId, 118014005, N'Since man’s days are determined, the number of his months is under your control; you have set his limit and he cannot pass it.'
EXEC add_BibleVerse @BibleId, 118014006, N'Look away from him and let him desist, until he fulfills his time like a hired man.'
EXEC add_BibleVerse @BibleId, 118014007, N'“But there is hope for a tree: If it is cut down, it will sprout again, and its new shoots will not fail.'
EXEC add_BibleVerse @BibleId, 118014008, N'Although its roots may grow old in the ground and its stump begins to die in the soil,'
EXEC add_BibleVerse @BibleId, 118014009, N'at the scent of water it will flourish and put forth shoots like a new plant.'
EXEC add_BibleVerse @BibleId, 118014010, N'But man dies and is powerless; he expires – and where is he?'
EXEC add_BibleVerse @BibleId, 118014011, N'As water disappears from the sea, or a river drains away and dries up,'
EXEC add_BibleVerse @BibleId, 118014012, N'so man lies down and does not rise; until the heavens are no more, they will not awake nor arise from their sleep.'
EXEC add_BibleVerse @BibleId, 118014013, N'“O that you would hide me in Sheol, and conceal me till your anger has passed! O that you would set me a time and then remember me!'
EXEC add_BibleVerse @BibleId, 118014014, N'If a man dies, will he live again? All the days of my hard service I will wait until my release comes.'
EXEC add_BibleVerse @BibleId, 118014015, N'You will call and I – I will answer you; you will long for the creature you have made.'
EXEC add_BibleVerse @BibleId, 118014016, N'“Surely now you count my steps; then you would not mark my sin.'
EXEC add_BibleVerse @BibleId, 118014017, N'My offenses would be sealed up in a bag; you would cover over my sin.'
EXEC add_BibleVerse @BibleId, 118014018, N'But as a mountain falls away and crumbles, and as a rock will be removed from its place,'
EXEC add_BibleVerse @BibleId, 118014019, N'as water wears away stones, and torrents wash away the soil, so you destroy man’s hope.'
EXEC add_BibleVerse @BibleId, 118014020, N'You overpower him once for all, and he departs; you change his appearance and send him away.'
EXEC add_BibleVerse @BibleId, 118014021, N'If his sons are honored, he does not know it; if they are brought low, he does not see it.'
EXEC add_BibleVerse @BibleId, 118014022, N'Only his flesh has pain for himself, and he mourns for himself.”'
EXEC add_BibleVerse @BibleId, 118015001, N'Then Eliphaz the Temanite answered:'
EXEC add_BibleVerse @BibleId, 118015002, N'“Does a wise man answer with blustery knowledge, or fill his belly with the east wind?'
EXEC add_BibleVerse @BibleId, 118015003, N'Does he argue with useless talk, with words that have no value in them?'
EXEC add_BibleVerse @BibleId, 118015004, N'But you even break off piety, and hinder meditation before God.'
EXEC add_BibleVerse @BibleId, 118015005, N'Your sin inspires your mouth; you choose the language of the crafty.'
EXEC add_BibleVerse @BibleId, 118015006, N'Your own mouth condemns you, not I; your own lips testify against you.'
EXEC add_BibleVerse @BibleId, 118015007, N'“Were you the first man ever born? Were you brought forth before the hills?'
EXEC add_BibleVerse @BibleId, 118015008, N'Do you listen in on God’s secret council? Do you limit wisdom to yourself?'
EXEC add_BibleVerse @BibleId, 118015009, N'What do you know that we don’t know? What do you understand that we don’t understand?'
EXEC add_BibleVerse @BibleId, 118015010, N'The gray-haired and the aged are on our side, men far older than your father.'
EXEC add_BibleVerse @BibleId, 118015011, N'Are God’s consolations too trivial for you; or a word spoken in gentleness to you?'
EXEC add_BibleVerse @BibleId, 118015012, N'Why has your heart carried you away, and why do your eyes flash,'
EXEC add_BibleVerse @BibleId, 118015013, N'when you turn your rage against God and allow such words to escape from your mouth?'
EXEC add_BibleVerse @BibleId, 118015014, N'What is man that he should be pure, or one born of woman, that he should be righteous?'
EXEC add_BibleVerse @BibleId, 118015015, N'If God places no trust in his holy ones, if even the heavens are not pure in his eyes,'
EXEC add_BibleVerse @BibleId, 118015016, N'how much less man, who is abominable and corrupt, who drinks in evil like water!'
EXEC add_BibleVerse @BibleId, 118015017, N'“I will explain to you; listen to me, and what I have seen, I will declare,'
EXEC add_BibleVerse @BibleId, 118015018, N'what wise men declare, hiding nothing, from the tradition of their ancestors,'
EXEC add_BibleVerse @BibleId, 118015019, N'to whom alone the land was given when no foreigner passed among them.'
EXEC add_BibleVerse @BibleId, 118015020, N'All his days the wicked man suffers torment, throughout the number of the years that are stored up for the tyrant.'
EXEC add_BibleVerse @BibleId, 118015021, N'Terrifying sounds fill his ears; in a time of peace marauders attack him.'
EXEC add_BibleVerse @BibleId, 118015022, N'He does not expect to escape from darkness; he is marked for the sword;'
EXEC add_BibleVerse @BibleId, 118015023, N'he wanders about – food for vultures; he knows that the day of darkness is at hand.'
EXEC add_BibleVerse @BibleId, 118015024, N'Distress and anguish terrify him; they prevail against him like a king ready to launch an attack,'
EXEC add_BibleVerse @BibleId, 118015025, N'for he stretches out his hand against God, and vaunts himself against the Almighty,'
EXEC add_BibleVerse @BibleId, 118015026, N'defiantly charging against him with a thick, strong shield!'
EXEC add_BibleVerse @BibleId, 118015027, N'Because he covered his face with fat, and made his hips bulge with fat,'
EXEC add_BibleVerse @BibleId, 118015028, N'he lived in ruined towns and in houses where no one lives, where they are ready to crumble into heaps.'
EXEC add_BibleVerse @BibleId, 118015029, N'He will not grow rich, and his wealth will not endure, nor will his possessions spread over the land.'
EXEC add_BibleVerse @BibleId, 118015030, N'He will not escape the darkness; a flame will wither his shoots and he will depart by the breath of God’s mouth.'
EXEC add_BibleVerse @BibleId, 118015031, N'Let him not trust in what is worthless, deceiving himself; for worthlessness will be his reward.'
EXEC add_BibleVerse @BibleId, 118015032, N'Before his time he will be paid in full, and his branches will not flourish.'
EXEC add_BibleVerse @BibleId, 118015033, N'Like a vine he will let his sour grapes fall, and like an olive tree he will shed his blossoms.'
EXEC add_BibleVerse @BibleId, 118015034, N'For the company of the godless is barren, and fire consumes the tents of those who accept bribes.'
EXEC add_BibleVerse @BibleId, 118015035, N'They conceive trouble and bring forth evil; their belly prepares deception.”'
EXEC add_BibleVerse @BibleId, 118016001, N'Then Job replied:'
EXEC add_BibleVerse @BibleId, 118016002, N'“I have heard many things like these before. What miserable comforters are you all!'
EXEC add_BibleVerse @BibleId, 118016003, N'Will there be an end to your windy words? Or what provokes you that you answer?'
EXEC add_BibleVerse @BibleId, 118016004, N'I also could speak like you, if you were in my place; I could pile up words against you and I could shake my head at you.'
EXEC add_BibleVerse @BibleId, 118016005, N'But I would strengthen you with my words; comfort from my lips would bring you relief.'
EXEC add_BibleVerse @BibleId, 118016006, N'“But if I speak, my pain is not relieved, and if I refrain from speaking – how much of it goes away?'
EXEC add_BibleVerse @BibleId, 118016007, N'Surely now he has worn me out, you have devastated my entire household.'
EXEC add_BibleVerse @BibleId, 118016008, N'You have seized me, and it has become a witness; my leanness has risen up against me and testifies against me.'
EXEC add_BibleVerse @BibleId, 118016009, N'His anger has torn me and persecuted me; he has gnashed at me with his teeth; my adversary locks his eyes on me.'
EXEC add_BibleVerse @BibleId, 118016010, N'People have opened their mouths against me, they have struck my cheek in scorn; they unite together against me.'
EXEC add_BibleVerse @BibleId, 118016011, N'God abandons me to evil men, and throws me into the hands of wicked men.'
EXEC add_BibleVerse @BibleId, 118016012, N'I was in peace, and he has shattered me. He has seized me by the neck and crushed me. He has made me his target;'
EXEC add_BibleVerse @BibleId, 118016013, N'his archers surround me. Without pity he pierces my kidneys and pours out my gall on the ground.'
EXEC add_BibleVerse @BibleId, 118016014, N'He breaks through against me, time and time again; he rushes against me like a warrior.'
EXEC add_BibleVerse @BibleId, 118016015, N'I have sewed sackcloth on my skin, and buried my horn in the dust;'
EXEC add_BibleVerse @BibleId, 118016016, N'my face is reddened because of weeping, and on my eyelids there is a deep darkness,'
EXEC add_BibleVerse @BibleId, 118016017, N'although there is no violence in my hands and my prayer is pure.'
EXEC add_BibleVerse @BibleId, 118016018, N'“O earth, do not cover my blood, nor let there be a secret place for my cry.'
EXEC add_BibleVerse @BibleId, 118016019, N'Even now my witness is in heaven; my advocate is on high.'
EXEC add_BibleVerse @BibleId, 118016020, N'My intercessor is my friend as my eyes pour out tears to God;'
EXEC add_BibleVerse @BibleId, 118016021, N'and he contends with God on behalf of man as a man pleads for his friend.'
EXEC add_BibleVerse @BibleId, 118016022, N'For the years that lie ahead are few, and then I will go on the way of no return.'
EXEC add_BibleVerse @BibleId, 118017001, N'My spirit is broken, my days have faded out, the grave awaits me.'
EXEC add_BibleVerse @BibleId, 118017002, N'Surely mockery is with me; my eyes must dwell on their hostility.'
EXEC add_BibleVerse @BibleId, 118017003, N'Make then my pledge with you. Who else will put up security for me?'
EXEC add_BibleVerse @BibleId, 118017004, N'Because you have closed their minds to understanding, therefore you will not exalt them.'
EXEC add_BibleVerse @BibleId, 118017005, N'If a man denounces his friends for personal gain, the eyes of his children will fail.'
EXEC add_BibleVerse @BibleId, 118017006, N'He has made me a byword to people, I am the one in whose face they spit.'
EXEC add_BibleVerse @BibleId, 118017007, N'My eyes have grown dim with grief; my whole frame is but a shadow.'
EXEC add_BibleVerse @BibleId, 118017008, N'Upright men are appalled at this; the innocent man is troubled with the godless.'
EXEC add_BibleVerse @BibleId, 118017009, N'But the righteous man holds to his way, and the one with clean hands grows stronger.'
EXEC add_BibleVerse @BibleId, 118017010, N'“But turn, all of you, and come now! I will not find a wise man among you.'
EXEC add_BibleVerse @BibleId, 118017011, N'My days have passed, my plans are shattered, even the desires of my heart.'
EXEC add_BibleVerse @BibleId, 118017012, N'These men change night into day; they say, ‘The light is near in the face of darkness.’'
EXEC add_BibleVerse @BibleId, 118017013, N'If I hope for the grave to be my home, if I spread out my bed in darkness,'
EXEC add_BibleVerse @BibleId, 118017014, N'If I cry to corruption, ‘You are my father,’ and to the worm, ‘My Mother,’ or ‘My sister,’'
EXEC add_BibleVerse @BibleId, 118017015, N'where then is my hope? And my hope, who sees it?'
EXEC add_BibleVerse @BibleId, 118017016, N'Will it go down to the barred gates of death? Will we descend together into the dust?”'
EXEC add_BibleVerse @BibleId, 118018001, N'Then Bildad the Shuhite answered:'
EXEC add_BibleVerse @BibleId, 118018002, N'“How long until you make an end of words? You must consider, and then we can talk.'
EXEC add_BibleVerse @BibleId, 118018003, N'Why should we be regarded as beasts, and considered stupid in your sight?'
EXEC add_BibleVerse @BibleId, 118018004, N'You who tear yourself to pieces in your anger, will the earth be abandoned for your sake? Or will a rock be moved from its place?'
EXEC add_BibleVerse @BibleId, 118018005, N'“Yes, the lamp of the wicked is extinguished; his flame of fire does not shine.'
EXEC add_BibleVerse @BibleId, 118018006, N'The light in his tent grows dark; his lamp above him is extinguished.'
EXEC add_BibleVerse @BibleId, 118018007, N'His vigorous steps are restricted, and his own counsel throws him down.'
EXEC add_BibleVerse @BibleId, 118018008, N'For he has been thrown into a net by his feet and he wanders into a mesh.'
EXEC add_BibleVerse @BibleId, 118018009, N'A trap seizes him by the heel; a snare grips him.'
EXEC add_BibleVerse @BibleId, 118018010, N'A rope is hidden for him on the ground and a trap for him lies on the path.'
EXEC add_BibleVerse @BibleId, 118018011, N'Terrors frighten him on all sides and dog his every step.'
EXEC add_BibleVerse @BibleId, 118018012, N'Calamity is hungry for him, and misfortune is ready at his side.'
EXEC add_BibleVerse @BibleId, 118018013, N'It eats away parts of his skin; the most terrible death devours his limbs.'
EXEC add_BibleVerse @BibleId, 118018014, N'He is dragged from the security of his tent, and marched off to the king of terrors.'
EXEC add_BibleVerse @BibleId, 118018015, N'Fire resides in his tent; over his residence burning sulfur is scattered.'
EXEC add_BibleVerse @BibleId, 118018016, N'Below his roots dry up, and his branches wither above.'
EXEC add_BibleVerse @BibleId, 118018017, N'His memory perishes from the earth, he has no name in the land.'
EXEC add_BibleVerse @BibleId, 118018018, N'He is driven from light into darkness and is banished from the world.'
EXEC add_BibleVerse @BibleId, 118018019, N'He has neither children nor descendants among his people, no survivor in those places he once stayed.'
EXEC add_BibleVerse @BibleId, 118018020, N'People of the west are appalled at his fate; people of the east are seized with horror, saying,'
EXEC add_BibleVerse @BibleId, 118018021, N'‘Surely such is the residence of an evil man; and this is the place of one who has not known God.’”'
EXEC add_BibleVerse @BibleId, 118019001, N'Then Job answered:'
EXEC add_BibleVerse @BibleId, 118019002, N'“How long will you torment me and crush me with your words?'
EXEC add_BibleVerse @BibleId, 118019003, N'These ten times you have been reproaching me; you are not ashamed to attack me!'
EXEC add_BibleVerse @BibleId, 118019004, N'But even if it were true that I have erred, my error remains solely my concern!'
EXEC add_BibleVerse @BibleId, 118019005, N'If indeed you would exalt yourselves above me and plead my disgrace against me,'
EXEC add_BibleVerse @BibleId, 118019006, N'know then that God has wronged me and encircled me with his net.'
EXEC add_BibleVerse @BibleId, 118019007, N'“If I cry out, ‘Violence!’ I receive no answer; I cry for help, but there is no justice.'
EXEC add_BibleVerse @BibleId, 118019008, N'He has blocked my way so I cannot pass, and has set darkness over my paths.'
EXEC add_BibleVerse @BibleId, 118019009, N'He has stripped me of my honor and has taken the crown off my head.'
EXEC add_BibleVerse @BibleId, 118019010, N'He tears me down on every side until I perish; he uproots my hope like one uproots a tree.'
EXEC add_BibleVerse @BibleId, 118019011, N'Thus his anger burns against me, and he considers me among his enemies.'
EXEC add_BibleVerse @BibleId, 118019012, N'His troops advance together; they throw up a siege ramp against me, and they camp around my tent.'
EXEC add_BibleVerse @BibleId, 118019013, N'“He has put my relatives far from me; my acquaintances only turn away from me.'
EXEC add_BibleVerse @BibleId, 118019014, N'My kinsmen have failed me; my friends have forgotten me.'
EXEC add_BibleVerse @BibleId, 118019015, N'My guests and my servant girls consider me a stranger; I am a foreigner in their eyes.'
EXEC add_BibleVerse @BibleId, 118019016, N'I summon my servant, but he does not respond, even though I implore him with my own mouth.'
EXEC add_BibleVerse @BibleId, 118019017, N'My breath is repulsive to my wife; I am loathsome to my brothers.'
EXEC add_BibleVerse @BibleId, 118019018, N'Even youngsters have scorned me; when I get up, they scoff at me.'
EXEC add_BibleVerse @BibleId, 118019019, N'All my closest friends detest me; and those whom I love have turned against me.'
EXEC add_BibleVerse @BibleId, 118019020, N'My bones stick to my skin and my flesh; I have escaped alive with only the skin of my teeth.'
EXEC add_BibleVerse @BibleId, 118019021, N'Have pity on me, my friends, have pity on me, for the hand of God has struck me.'
EXEC add_BibleVerse @BibleId, 118019022, N'Why do you pursue me like God does? Will you never be satiated with my flesh?'
EXEC add_BibleVerse @BibleId, 118019023, N'“O that my words were written down, O that they were written on a scroll,'
EXEC add_BibleVerse @BibleId, 118019024, N'that with an iron chisel and with lead they were engraved in a rock forever!'
EXEC add_BibleVerse @BibleId, 118019025, N'As for me, I know that my Redeemer lives, and that as the last he will stand upon the earth.'
EXEC add_BibleVerse @BibleId, 118019026, N'And after my skin has been destroyed, yet in my flesh I will see God,'
EXEC add_BibleVerse @BibleId, 118019027, N'whom I will see for myself, and whom my own eyes will behold, and not another. My heart grows faint within me.'
EXEC add_BibleVerse @BibleId, 118019028, N'If you say, ‘How we will pursue him, since the root of the trouble is found in him!’'
EXEC add_BibleVerse @BibleId, 118019029, N'Fear the sword yourselves, for wrath brings the punishment by the sword, so that you may know that there is judgment.”'
EXEC add_BibleVerse @BibleId, 118020001, N'Then Zophar the Naamathite answered:'
EXEC add_BibleVerse @BibleId, 118020002, N'“This is why my troubled thoughts bring me back – because of my feelings within me.'
EXEC add_BibleVerse @BibleId, 118020003, N'When I hear a reproof that dishonors me, then my understanding prompts me to answer.'
EXEC add_BibleVerse @BibleId, 118020004, N'“Surely you know that it has been from old, ever since humankind was placed on the earth,'
EXEC add_BibleVerse @BibleId, 118020005, N'that the elation of the wicked is brief, the joy of the godless lasts but a moment.'
EXEC add_BibleVerse @BibleId, 118020006, N'Even though his stature reaches to the heavens and his head touches the clouds,'
EXEC add_BibleVerse @BibleId, 118020007, N'he will perish forever, like his own excrement; those who used to see him will say, ‘Where is he?’'
EXEC add_BibleVerse @BibleId, 118020008, N'Like a dream he flies away, never again to be found, and like a vision of the night he is put to flight.'
EXEC add_BibleVerse @BibleId, 118020009, N'People who had seen him will not see him again, and the place where he was will recognize him no longer.'
EXEC add_BibleVerse @BibleId, 118020010, N'His sons must recompense the poor; his own hands must return his wealth.'
EXEC add_BibleVerse @BibleId, 118020011, N'His bones were full of his youthful vigor, but that vigor will lie down with him in the dust.'
EXEC add_BibleVerse @BibleId, 118020012, N'“If evil is sweet in his mouth and he hides it under his tongue,'
EXEC add_BibleVerse @BibleId, 118020013, N'if he retains it for himself and does not let it go, and holds it fast in his mouth,'
EXEC add_BibleVerse @BibleId, 118020014, N'his food is turned sour in his stomach; it becomes the venom of serpents within him.'
EXEC add_BibleVerse @BibleId, 118020015, N'The wealth that he consumed he vomits up, God will make him throw it out of his stomach.'
EXEC add_BibleVerse @BibleId, 118020016, N'He sucks the poison of serpents; the fangs of a viper kill him.'
EXEC add_BibleVerse @BibleId, 118020017, N'He will not look on the streams, the rivers, which are the torrents of honey and butter.'
EXEC add_BibleVerse @BibleId, 118020018, N'He gives back the ill-gotten gain without assimilating it; he will not enjoy the wealth from his commerce.'
EXEC add_BibleVerse @BibleId, 118020019, N'For he has oppressed the poor and abandoned them; he has seized a house which he did not build.'
EXEC add_BibleVerse @BibleId, 118020020, N'For he knows no satisfaction in his appetite; he does not let anything he desires escape.'
EXEC add_BibleVerse @BibleId, 118020021, N'“Nothing is left for him to devour; that is why his prosperity does not last.'
EXEC add_BibleVerse @BibleId, 118020022, N'In the fullness of his sufficiency, distress overtakes him. the full force of misery will come upon him.'
EXEC add_BibleVerse @BibleId, 118020023, N'“While he is filling his belly, God sends his burning anger against him, and rains down his blows upon him.'
EXEC add_BibleVerse @BibleId, 118020024, N'If he flees from an iron weapon, then an arrow from a bronze bow pierces him.'
EXEC add_BibleVerse @BibleId, 118020025, N'When he pulls it out and it comes out of his back, the gleaming point out of his liver, terrors come over him.'
EXEC add_BibleVerse @BibleId, 118020026, N'Total darkness waits to receive his treasures; a fire which has not been kindled will consume him and devour what is left in his tent.'
EXEC add_BibleVerse @BibleId, 118020027, N'The heavens reveal his iniquity; the earth rises up against him.'
EXEC add_BibleVerse @BibleId, 118020028, N'A flood will carry off his house, rushing waters on the day of God’s wrath.'
EXEC add_BibleVerse @BibleId, 118020029, N'Such is the lot God allots the wicked, and the heritage of his appointment from God.”'
EXEC add_BibleVerse @BibleId, 118021001, N'Then Job answered:'
EXEC add_BibleVerse @BibleId, 118021002, N'“Listen carefully to my words; let this be the consolation you offer me.'
EXEC add_BibleVerse @BibleId, 118021003, N'Bear with me and I will speak, and after I have spoken you may mock.'
EXEC add_BibleVerse @BibleId, 118021004, N'Is my complaint against a man? If so, why should I not be impatient?'
EXEC add_BibleVerse @BibleId, 118021005, N'Look at me and be appalled; put your hands over your mouths.'
EXEC add_BibleVerse @BibleId, 118021006, N'For, when I think about this, I am terrified and my body feels a shudder.'
EXEC add_BibleVerse @BibleId, 118021007, N'“Why do the wicked go on living, grow old, even increase in power?'
EXEC add_BibleVerse @BibleId, 118021008, N'Their children are firmly established in their presence, their offspring before their eyes.'
EXEC add_BibleVerse @BibleId, 118021009, N'Their houses are safe and without fear; and no rod of punishment from God is upon them.'
EXEC add_BibleVerse @BibleId, 118021010, N'Their bulls breed without fail; their cows calve and do not miscarry.'
EXEC add_BibleVerse @BibleId, 118021011, N'They allow their children to run like a flock; their little ones dance about.'
EXEC add_BibleVerse @BibleId, 118021012, N'They sing to the accompaniment of tambourine and harp, and make merry to the sound of the flute.'
EXEC add_BibleVerse @BibleId, 118021013, N'They live out their years in prosperity and go down to the grave in peace.'
EXEC add_BibleVerse @BibleId, 118021014, N'So they say to God, ‘Turn away from us! We do not want to know your ways.'
EXEC add_BibleVerse @BibleId, 118021015, N'Who is the Almighty, that we should serve him? What would we gain if we were to pray to him?’'
EXEC add_BibleVerse @BibleId, 118021016, N'But their prosperity is not their own doing. The counsel of the wicked is far from me!'
EXEC add_BibleVerse @BibleId, 118021017, N'“How often is the lamp of the wicked extinguished? How often does their misfortune come upon them? How often does God apportion pain to them in his anger?'
EXEC add_BibleVerse @BibleId, 118021018, N'How often are they like straw before the wind, and like chaff swept away by a whirlwind?'
EXEC add_BibleVerse @BibleId, 118021019, N'You may say, ‘God stores up a man’s punishment for his children!’ Instead let him repay the man himself so that he may know it!'
EXEC add_BibleVerse @BibleId, 118021020, N'Let his own eyes see his destruction; let him drink of the anger of the Almighty.'
EXEC add_BibleVerse @BibleId, 118021021, N'For what is his interest in his home after his death, when the number of his months has been broken off?'
EXEC add_BibleVerse @BibleId, 118021022, N'Can anyone teach God knowledge, since he judges those that are on high?'
EXEC add_BibleVerse @BibleId, 118021023, N'“One man dies in his full vigor, completely secure and prosperous,'
EXEC add_BibleVerse @BibleId, 118021024, N'his body well nourished, and the marrow of his bones moist.'
EXEC add_BibleVerse @BibleId, 118021025, N'And another man dies in bitterness of soul, never having tasted anything good.'
EXEC add_BibleVerse @BibleId, 118021026, N'Together they lie down in the dust, and worms cover over them both.'
EXEC add_BibleVerse @BibleId, 118021027, N'“Yes, I know what you are thinking, the schemes by which you would wrong me.'
EXEC add_BibleVerse @BibleId, 118021028, N'For you say, ‘Where now is the nobleman’s house, and where are the tents in which the wicked lived?’'
EXEC add_BibleVerse @BibleId, 118021029, N'Have you never questioned those who travel the roads? Do you not recognize their accounts –'
EXEC add_BibleVerse @BibleId, 118021030, N'that the evil man is spared from the day of his misfortune, that he is delivered from the day of God’s wrath?'
EXEC add_BibleVerse @BibleId, 118021031, N'No one denounces his conduct to his face; no one repays him for what he has done.'
EXEC add_BibleVerse @BibleId, 118021032, N'And when he is carried to the tombs, and watch is kept over the funeral mound,'
EXEC add_BibleVerse @BibleId, 118021033, N'The clods of the torrent valley are sweet to him; behind him everybody follows in procession, and before him goes a countless throng.'
EXEC add_BibleVerse @BibleId, 118021034, N'So how can you console me with your futile words? Nothing is left of your answers but deception!”'
EXEC add_BibleVerse @BibleId, 118022001, N'Then Eliphaz the Temanite answered:'
EXEC add_BibleVerse @BibleId, 118022002, N'“Is it to God that a strong man is of benefit? Is it to him that even a wise man is profitable?'
EXEC add_BibleVerse @BibleId, 118022003, N'Is it of any special benefit to the Almighty that you should be righteous, or is it any gain to him that you make your ways blameless?'
EXEC add_BibleVerse @BibleId, 118022004, N'Is it because of your piety that he rebukes you and goes to judgment with you?'
EXEC add_BibleVerse @BibleId, 118022005, N'Is not your wickedness great and is there no end to your iniquity?'
EXEC add_BibleVerse @BibleId, 118022006, N'“For you took pledges from your brothers for no reason, and you stripped the clothing from the naked.'
EXEC add_BibleVerse @BibleId, 118022007, N'You gave the weary no water to drink and from the hungry you withheld food.'
EXEC add_BibleVerse @BibleId, 118022008, N'Although you were a powerful man, owning land, an honored man living on it,'
EXEC add_BibleVerse @BibleId, 118022009, N'you sent widows away empty-handed, and the arms of the orphans you crushed.'
EXEC add_BibleVerse @BibleId, 118022010, N'That is why snares surround you, and why sudden fear terrifies you,'
EXEC add_BibleVerse @BibleId, 118022011, N'why it is so dark you cannot see, and why a flood of water covers you.'
EXEC add_BibleVerse @BibleId, 118022012, N'“Is not God on high in heaven? And see the lofty stars, how high they are!'
EXEC add_BibleVerse @BibleId, 118022013, N'But you have said, ‘What does God know? Does he judge through such deep darkness?'
EXEC add_BibleVerse @BibleId, 118022014, N'Thick clouds are a veil for him, so he does not see us, as he goes back and forth in the vault of heaven.’'
EXEC add_BibleVerse @BibleId, 118022015, N'Will you keep to the old path that evil men have walked –'
EXEC add_BibleVerse @BibleId, 118022016, N'men who were carried off before their time, when the flood was poured out on their foundations?'
EXEC add_BibleVerse @BibleId, 118022017, N'They were saying to God, ‘Turn away from us,’ and ‘What can the Almighty do to us?’'
EXEC add_BibleVerse @BibleId, 118022018, N'But it was he who filled their houses with good things – yet the counsel of the wicked was far from me.'
EXEC add_BibleVerse @BibleId, 118022019, N'The righteous see their destruction and rejoice; the innocent mock them scornfully, saying,'
EXEC add_BibleVerse @BibleId, 118022020, N'‘Surely our enemies are destroyed, and fire consumes their wealth.’'
EXEC add_BibleVerse @BibleId, 118022021, N'“Reconcile yourself with God, and be at peace with him; in this way your prosperity will be good.'
EXEC add_BibleVerse @BibleId, 118022022, N'Accept instruction from his mouth and store up his words in your heart.'
EXEC add_BibleVerse @BibleId, 118022023, N'If you return to the Almighty, you will be built up; if you remove wicked behavior far from your tent,'
EXEC add_BibleVerse @BibleId, 118022024, N'and throw your gold in the dust – your gold of Ophir among the rocks in the ravines –'
EXEC add_BibleVerse @BibleId, 118022025, N'then the Almighty himself will be your gold, and the choicest silver for you.'
EXEC add_BibleVerse @BibleId, 118022026, N'Surely then you will delight yourself in the Almighty, and will lift up your face toward God.'
EXEC add_BibleVerse @BibleId, 118022027, N'You will pray to him and he will hear you, and you will fulfill your vows to him.'
EXEC add_BibleVerse @BibleId, 118022028, N'Whatever you decide on a matter, it will be established for you, and light will shine on your ways.'
EXEC add_BibleVerse @BibleId, 118022029, N'When people are brought low and you say ‘Lift them up!’ then he will save the downcast;'
EXEC add_BibleVerse @BibleId, 118022030, N'he will deliver even someone who is not innocent, who will escape through the cleanness of your hands.”'
EXEC add_BibleVerse @BibleId, 118023001, N'Then Job answered:'
EXEC add_BibleVerse @BibleId, 118023002, N'“Even today my complaint is still bitter; his hand is heavy despite my groaning.'
EXEC add_BibleVerse @BibleId, 118023003, N'O that I knew where I might find him, that I could come to his place of residence!'
EXEC add_BibleVerse @BibleId, 118023004, N'I would lay out my case before him and fill my mouth with arguments.'
EXEC add_BibleVerse @BibleId, 118023005, N'I would know with what words he would answer me, and understand what he would say to me.'
EXEC add_BibleVerse @BibleId, 118023006, N'Would he contend with me with great power? No, he would only pay attention to me.'
EXEC add_BibleVerse @BibleId, 118023007, N'There an upright person could present his case before him, and I would be delivered forever from my judge.'
EXEC add_BibleVerse @BibleId, 118023008, N'“If I go to the east, he is not there, and to the west, yet I do not perceive him.'
EXEC add_BibleVerse @BibleId, 118023009, N'In the north when he is at work, I do not see him; when he turns to the south, I see no trace of him.'
EXEC add_BibleVerse @BibleId, 118023010, N'But he knows the pathway that I take; if he tested me, I would come forth like gold.'
EXEC add_BibleVerse @BibleId, 118023011, N'My feet have followed his steps closely; I have kept to his way and have not turned aside.'
EXEC add_BibleVerse @BibleId, 118023012, N'I have not departed from the commands of his lips; I have treasured the words of his mouth more than my allotted portion.'
EXEC add_BibleVerse @BibleId, 118023013, N'But he is unchangeable, and who can change him? Whatever he has desired, he does.'
EXEC add_BibleVerse @BibleId, 118023014, N'For he fulfills his decree against me, and many such things are his plans.'
EXEC add_BibleVerse @BibleId, 118023015, N'That is why I am terrified in his presence; when I consider, I am afraid because of him.'
EXEC add_BibleVerse @BibleId, 118023016, N'Indeed, God has made my heart faint; the Almighty has terrified me.'
EXEC add_BibleVerse @BibleId, 118023017, N'Yet I have not been silent because of the darkness, because of the thick darkness that covered my face.'
EXEC add_BibleVerse @BibleId, 118024001, N'“Why are times not appointed by the Almighty? Why do those who know him not see his days?'
EXEC add_BibleVerse @BibleId, 118024002, N'Men move boundary stones; they seize the flock and pasture them.'
EXEC add_BibleVerse @BibleId, 118024003, N'They drive away the orphan’s donkey; they take the widow’s ox as a pledge.'
EXEC add_BibleVerse @BibleId, 118024004, N'They turn the needy from the pathway, and the poor of the land hide themselves together.'
EXEC add_BibleVerse @BibleId, 118024005, N'Like wild donkeys in the desert they go out to their labor, seeking diligently for food; the wasteland provides food for them and for their children.'
EXEC add_BibleVerse @BibleId, 118024006, N'They reap fodder in the field, and glean in the vineyard of the wicked.'
EXEC add_BibleVerse @BibleId, 118024007, N'They spend the night naked because they lack clothing; they have no covering against the cold.'
EXEC add_BibleVerse @BibleId, 118024008, N'They are soaked by mountain rains and huddle in the rocks because they lack shelter.'
EXEC add_BibleVerse @BibleId, 118024009, N'The fatherless child is snatched from the breast, the infant of the poor is taken as a pledge.'
EXEC add_BibleVerse @BibleId, 118024010, N'They go about naked, without clothing, and go hungry while they carry the sheaves.'
EXEC add_BibleVerse @BibleId, 118024011, N'They press out the olive oil between the rows of olive trees; they tread the winepresses while they are thirsty.'
EXEC add_BibleVerse @BibleId, 118024012, N'From the city the dying groan, and the wounded cry out for help, but God charges no one with wrongdoing.'
EXEC add_BibleVerse @BibleId, 118024013, N'There are those who rebel against the light; they do not know its ways and they do not stay on its paths.'
EXEC add_BibleVerse @BibleId, 118024014, N'Before daybreak the murderer rises up; he kills the poor and the needy; in the night he is like a thief.'
EXEC add_BibleVerse @BibleId, 118024015, N'And the eye of the adulterer watches for the twilight, thinking, ‘No eye can see me,’ and covers his face with a mask.'
EXEC add_BibleVerse @BibleId, 118024016, N'In the dark the robber breaks into houses, but by day they shut themselves in; they do not know the light.'
EXEC add_BibleVerse @BibleId, 118024017, N'For all of them, the morning is to them like deep darkness; they are friends with the terrors of darkness.'
EXEC add_BibleVerse @BibleId, 118024018, N'“You say, ‘He is foam on the face of the waters; their portion of the land is cursed so that no one goes to their vineyard.'
EXEC add_BibleVerse @BibleId, 118024019, N'The drought as well as the heat carry away the melted snow; so the grave takes away those who have sinned.'
EXEC add_BibleVerse @BibleId, 118024020, N'The womb forgets him, the worm feasts on him, no longer will he be remembered. Like a tree, wickedness will be broken down.'
EXEC add_BibleVerse @BibleId, 118024021, N'He preys on the barren and childless woman, and does not treat the widow well.'
EXEC add_BibleVerse @BibleId, 118024022, N'But God drags off the mighty by his power; when God rises up against him, he has no faith in his life.'
EXEC add_BibleVerse @BibleId, 118024023, N'God may let them rest in a feeling of security, but he is constantly watching all their ways.'
EXEC add_BibleVerse @BibleId, 118024024, N'They are exalted for a little while, and then they are gone, they are brought low like all others, and gathered in, and like a head of grain they are cut off.’'
EXEC add_BibleVerse @BibleId, 118024025, N'“If this is not so, who can prove me a liar and reduce my words to nothing?”'
EXEC add_BibleVerse @BibleId, 118025001, N'Then Bildad the Shuhite answered:'
EXEC add_BibleVerse @BibleId, 118025002, N'“Dominion and awesome might belong to God; he establishes peace in his heights.'
EXEC add_BibleVerse @BibleId, 118025003, N'Can his armies be numbered? On whom does his light not rise?'
EXEC add_BibleVerse @BibleId, 118025004, N'How then can a human being be righteous before God? How can one born of a woman be pure?'
EXEC add_BibleVerse @BibleId, 118025005, N'If even the moon is not bright, and the stars are not pure as far as he is concerned,'
EXEC add_BibleVerse @BibleId, 118025006, N'how much less a mortal man, who is but a maggot – a son of man, who is only a worm!”'
EXEC add_BibleVerse @BibleId, 118026001, N'Then Job replied:'
EXEC add_BibleVerse @BibleId, 118026002, N'“How you have helped the powerless! How you have saved the person who has no strength!'
EXEC add_BibleVerse @BibleId, 118026003, N'How you have advised the one without wisdom, and abundantly revealed your insight!'
EXEC add_BibleVerse @BibleId, 118026004, N'To whom did you utter these words? And whose spirit has come forth from your mouth?'
EXEC add_BibleVerse @BibleId, 118026005, N'“The dead tremble – those beneath the waters and all that live in them.'
EXEC add_BibleVerse @BibleId, 118026006, N'The underworld is naked before God; the place of destruction lies uncovered.'
EXEC add_BibleVerse @BibleId, 118026007, N'He spreads out the northern skies over empty space; he suspends the earth on nothing.'
EXEC add_BibleVerse @BibleId, 118026008, N'He locks the waters in his clouds, and the clouds do not burst with the weight of them.'
EXEC add_BibleVerse @BibleId, 118026009, N'He conceals the face of the full moon, shrouding it with his clouds.'
EXEC add_BibleVerse @BibleId, 118026010, N'He marks out the horizon on the surface of the waters as a boundary between light and darkness.'
EXEC add_BibleVerse @BibleId, 118026011, N'The pillars of the heavens tremble and are amazed at his rebuke.'
EXEC add_BibleVerse @BibleId, 118026012, N'By his power he stills the sea; by his wisdom he cut Rahab the great sea monster to pieces.'
EXEC add_BibleVerse @BibleId, 118026013, N'By his breath the skies became fair; his hand pierced the fleeing serpent.'
EXEC add_BibleVerse @BibleId, 118026014, N'Indeed, these are but the outer fringes of his ways! How faint is the whisper we hear of him! But who can understand the thunder of his power?”'
EXEC add_BibleVerse @BibleId, 118027001, N'And Job took up his discourse again:'
EXEC add_BibleVerse @BibleId, 118027002, N'“As surely as God lives, who has denied me justice, the Almighty, who has made my life bitter –'
EXEC add_BibleVerse @BibleId, 118027003, N'for while my spirit is still in me, and the breath from God is in my nostrils,'
EXEC add_BibleVerse @BibleId, 118027004, N'my lips will not speak wickedness, and my tongue will whisper no deceit.'
EXEC add_BibleVerse @BibleId, 118027005, N'I will never declare that you three are in the right; until I die, I will not set aside my integrity!'
EXEC add_BibleVerse @BibleId, 118027006, N'I will maintain my righteousness and never let it go; my conscience will not reproach me for as long as I live.'
EXEC add_BibleVerse @BibleId, 118027007, N'“May my enemy be like the wicked, my adversary like the unrighteous.'
EXEC add_BibleVerse @BibleId, 118027008, N'For what hope does the godless have when he is cut off, when God takes away his life?'
EXEC add_BibleVerse @BibleId, 118027009, N'Does God listen to his cry when distress overtakes him?'
EXEC add_BibleVerse @BibleId, 118027010, N'Will he find delight in the Almighty? Will he call out to God at all times?'
EXEC add_BibleVerse @BibleId, 118027011, N'I will teach you about the power of God; What is on the Almighty’s mind I will not conceal.'
EXEC add_BibleVerse @BibleId, 118027012, N'If you yourselves have all seen this, Why in the world do you continue this meaningless talk?'
EXEC add_BibleVerse @BibleId, 118027013, N'This is the portion of the wicked man allotted by God, the inheritance that evildoers receive from the Almighty.'
EXEC add_BibleVerse @BibleId, 118027014, N'If his children increase – it is for the sword! His offspring never have enough to eat.'
EXEC add_BibleVerse @BibleId, 118027015, N'Those who survive him are buried by the plague, and their widows do not mourn for them.'
EXEC add_BibleVerse @BibleId, 118027016, N'If he piles up silver like dust and stores up clothing like mounds of clay,'
EXEC add_BibleVerse @BibleId, 118027017, N'what he stores up a righteous man will wear, and an innocent man will inherit his silver.'
EXEC add_BibleVerse @BibleId, 118027018, N'The house he builds is as fragile as a moth’s cocoon, like a hut that a watchman has made.'
EXEC add_BibleVerse @BibleId, 118027019, N'He goes to bed wealthy, but will do so no more. When he opens his eyes, it is all gone.'
EXEC add_BibleVerse @BibleId, 118027020, N'Terrors overwhelm him like a flood; at night a whirlwind carries him off.'
EXEC add_BibleVerse @BibleId, 118027021, N'The east wind carries him away, and he is gone; it sweeps him out of his place.'
EXEC add_BibleVerse @BibleId, 118027022, N'It hurls itself against him without pity as he flees headlong from its power.'
EXEC add_BibleVerse @BibleId, 118027023, N'It claps its hands at him in derision and hisses him away from his place.'
EXEC add_BibleVerse @BibleId, 118028001, N'“Surely there is a mine for silver, and a place where gold is refined.'
EXEC add_BibleVerse @BibleId, 118028002, N'Iron is taken from the ground, and rock is poured out as copper.'
EXEC add_BibleVerse @BibleId, 118028003, N'Man puts an end to the darkness; he searches the farthest recesses for the ore in the deepest darkness.'
EXEC add_BibleVerse @BibleId, 118028004, N'Far from where people live he sinks a shaft, in places travelers have long forgotten, far from other people he dangles and sways.'
EXEC add_BibleVerse @BibleId, 118028005, N'The earth, from which food comes, is overturned below as though by fire;'
EXEC add_BibleVerse @BibleId, 118028006, N'a place whose stones are sapphires and which contains dust of gold;'
EXEC add_BibleVerse @BibleId, 118028007, N'a hidden path no bird of prey knows – no falcon’s eye has spotted it.'
EXEC add_BibleVerse @BibleId, 118028008, N'Proud beasts have not set foot on it, and no lion has passed along it.'
EXEC add_BibleVerse @BibleId, 118028009, N'On the flinty rock man has set to work with his hand; he has overturned mountains at their bases.'
EXEC add_BibleVerse @BibleId, 118028010, N'He has cut out channels through the rocks; his eyes have spotted every precious thing.'
EXEC add_BibleVerse @BibleId, 118028011, N'He has searched the sources of the rivers and what was hidden he has brought into the light.'
EXEC add_BibleVerse @BibleId, 118028012, N'“But wisdom – where can it be found? Where is the place of understanding?'
EXEC add_BibleVerse @BibleId, 118028013, N'Mankind does not know its place; it cannot be found in the land of the living.'
EXEC add_BibleVerse @BibleId, 118028014, N'The deep says, ‘It is not with me.’ And the sea says, ‘It is not with me.’'
EXEC add_BibleVerse @BibleId, 118028015, N'Fine gold cannot be given in exchange for it, nor can its price be weighed out in silver.'
EXEC add_BibleVerse @BibleId, 118028016, N'It cannot be measured out for purchase with the gold of Ophir, with precious onyx or sapphires.'
EXEC add_BibleVerse @BibleId, 118028017, N'Neither gold nor crystal can be compared with it, nor can a vase of gold match its worth.'
EXEC add_BibleVerse @BibleId, 118028018, N'Of coral and jasper no mention will be made; the price of wisdom is more than pearls.'
EXEC add_BibleVerse @BibleId, 118028019, N'The topaz of Cush cannot be compared with it; it cannot be purchased with pure gold.'
EXEC add_BibleVerse @BibleId, 118028020, N'“But wisdom – where does it come from? Where is the place of understanding?'
EXEC add_BibleVerse @BibleId, 118028021, N'For it has been hidden from the eyes of every living creature, and from the birds of the sky it has been concealed.'
EXEC add_BibleVerse @BibleId, 118028022, N'Destruction and Death say, ‘With our ears we have heard a rumor about where it can be found.’'
EXEC add_BibleVerse @BibleId, 118028023, N'God understands the way to it, and he alone knows its place.'
EXEC add_BibleVerse @BibleId, 118028024, N'For he looks to the ends of the earth and observes everything under the heavens.'
EXEC add_BibleVerse @BibleId, 118028025, N'When he made the force of the wind and measured the waters with a gauge.'
EXEC add_BibleVerse @BibleId, 118028026, N'When he imposed a limit for the rain, and a path for the thunderstorm,'
EXEC add_BibleVerse @BibleId, 118028027, N'then he looked at wisdom and assessed its value; he established it and examined it closely.'
EXEC add_BibleVerse @BibleId, 118028028, N'And he said to mankind, ‘The fear of the Lord – that is wisdom, and to turn away from evil is understanding.’”'
EXEC add_BibleVerse @BibleId, 118029001, N'Then Job continued his speech:'
EXEC add_BibleVerse @BibleId, 118029002, N'“O that I could be as I was in the months now gone, in the days when God watched over me,'
EXEC add_BibleVerse @BibleId, 118029003, N'when he caused his lamp to shine upon my head, and by his light I walked through darkness;'
EXEC add_BibleVerse @BibleId, 118029004, N'just as I was in my most productive time, when God’s intimate friendship was experienced in my tent,'
EXEC add_BibleVerse @BibleId, 118029005, N'when the Almighty was still with me and my children were around me;'
EXEC add_BibleVerse @BibleId, 118029006, N'when my steps were bathed with butter and the rock poured out for me streams of olive oil!'
EXEC add_BibleVerse @BibleId, 118029007, N'When I went out to the city gate and secured my seat in the public square,'
EXEC add_BibleVerse @BibleId, 118029008, N'the young men would see me and step aside, and the old men would get up and remain standing;'
EXEC add_BibleVerse @BibleId, 118029009, N'the chief men refrained from talking and covered their mouths with their hands;'
EXEC add_BibleVerse @BibleId, 118029010, N'the voices of the nobles fell silent, and their tongues stuck to the roof of their mouths.'
EXEC add_BibleVerse @BibleId, 118029011, N'“As soon as the ear heard these things, it blessed me, and when the eye saw them, it bore witness to me,'
EXEC add_BibleVerse @BibleId, 118029012, N'for I rescued the poor who cried out for help, and the orphan who had no one to assist him;'
EXEC add_BibleVerse @BibleId, 118029013, N'the blessing of the dying man descended on me, and I made the widow’s heart rejoice;'
EXEC add_BibleVerse @BibleId, 118029014, N'I put on righteousness and it clothed me, my just dealing was like a robe and a turban;'
EXEC add_BibleVerse @BibleId, 118029015, N'I was eyes for the blind and feet for the lame;'
EXEC add_BibleVerse @BibleId, 118029016, N'I was a father to the needy, and I investigated the case of the person I did not know;'
EXEC add_BibleVerse @BibleId, 118029017, N'I broke the fangs of the wicked, and made him drop his prey from his teeth.'
EXEC add_BibleVerse @BibleId, 118029018, N'“Then I thought, ‘I will die in my own home, my days as numerous as the grains of sand.'
EXEC add_BibleVerse @BibleId, 118029019, N'My roots reach the water, and the dew lies on my branches all night long.'
EXEC add_BibleVerse @BibleId, 118029020, N'My glory will always be fresh in me, and my bow ever new in my hand.’'
EXEC add_BibleVerse @BibleId, 118029021, N'“People listened to me and waited silently; they kept silent for my advice.'
EXEC add_BibleVerse @BibleId, 118029022, N'After I had spoken, they did not respond; my words fell on them drop by drop.'
EXEC add_BibleVerse @BibleId, 118029023, N'They waited for me as people wait for the rain, and they opened their mouths as for the spring rains.'
EXEC add_BibleVerse @BibleId, 118029024, N'If I smiled at them, they hardly believed it; and they did not cause the light of my face to darken.'
EXEC add_BibleVerse @BibleId, 118029025, N'I chose the way for them and sat as their chief; I lived like a king among his troops; I was like one who comforts mourners.'
EXEC add_BibleVerse @BibleId, 118030001, N'“But now they mock me, those who are younger than I, whose fathers I disdained too much to put with my sheep dogs.'
EXEC add_BibleVerse @BibleId, 118030002, N'Moreover, the strength of their hands – what use was it to me? Men whose strength had perished;'
EXEC add_BibleVerse @BibleId, 118030003, N'gaunt with want and hunger, they would gnaw the parched land, in former time desolate and waste.'
EXEC add_BibleVerse @BibleId, 118030004, N'By the brush they would gather herbs from the salt marshes, and the root of the broom tree was their food.'
EXEC add_BibleVerse @BibleId, 118030005, N'They were banished from the community – people shouted at them like they would shout at thieves –'
EXEC add_BibleVerse @BibleId, 118030006, N'so that they had to live in the dry stream beds, in the holes of the ground, and among the rocks.'
EXEC add_BibleVerse @BibleId, 118030007, N'They brayed like animals among the bushes and were huddled together under the nettles.'
EXEC add_BibleVerse @BibleId, 118030008, N'Sons of senseless and nameless people, they were driven out of the land with whips.'
EXEC add_BibleVerse @BibleId, 118030009, N'“And now I have become their taunt song; I have become a byword among them.'
EXEC add_BibleVerse @BibleId, 118030010, N'They detest me and maintain their distance; they do not hesitate to spit in my face.'
EXEC add_BibleVerse @BibleId, 118030011, N'Because God has untied my tent cord and afflicted me, people throw off all restraint in my presence.'
EXEC add_BibleVerse @BibleId, 118030012, N'On my right the young rabble rise up; they drive me from place to place, and build up siege ramps against me.'
EXEC add_BibleVerse @BibleId, 118030013, N'They destroy my path; they succeed in destroying me without anyone assisting them.'
EXEC add_BibleVerse @BibleId, 118030014, N'They come in as through a wide breach; amid the crash they come rolling in.'
EXEC add_BibleVerse @BibleId, 118030015, N'Terrors are turned loose on me; they drive away my honor like the wind, and like a cloud my deliverance has passed away.'
EXEC add_BibleVerse @BibleId, 118030016, N'“And now my soul pours itself out within me; days of suffering take hold of me.'
EXEC add_BibleVerse @BibleId, 118030017, N'Night pierces my bones; my gnawing pains never cease.'
EXEC add_BibleVerse @BibleId, 118030018, N'With great power God grasps my clothing; he binds me like the collar of my tunic.'
EXEC add_BibleVerse @BibleId, 118030019, N'He has flung me into the mud, and I have come to resemble dust and ashes.'
EXEC add_BibleVerse @BibleId, 118030020, N'I cry out to you, but you do not answer me; I stand up, and you only look at me.'
EXEC add_BibleVerse @BibleId, 118030021, N'You have become cruel to me; with the strength of your hand you attack me.'
EXEC add_BibleVerse @BibleId, 118030022, N'You pick me up on the wind and make me ride on it; you toss me about in the storm.'
EXEC add_BibleVerse @BibleId, 118030023, N'I know that you are bringing me to death, to the meeting place for all the living.'
EXEC add_BibleVerse @BibleId, 118030024, N'“Surely one does not stretch out his hand against a broken man when he cries for help in his distress.'
EXEC add_BibleVerse @BibleId, 118030025, N'Have I not wept for the unfortunate? Was not my soul grieved for the poor?'
EXEC add_BibleVerse @BibleId, 118030026, N'But when I hoped for good, trouble came; when I expected light, then darkness came.'
EXEC add_BibleVerse @BibleId, 118030027, N'My heart is in turmoil unceasingly; the days of my affliction confront me.'
EXEC add_BibleVerse @BibleId, 118030028, N'I go about blackened, but not by the sun; in the assembly I stand up and cry for help.'
EXEC add_BibleVerse @BibleId, 118030029, N'I have become a brother to jackals and a companion of ostriches.'
EXEC add_BibleVerse @BibleId, 118030030, N'My skin has turned dark on me; my body is hot with fever.'
EXEC add_BibleVerse @BibleId, 118030031, N'My harp is used for mourning and my flute for the sound of weeping.'
EXEC add_BibleVerse @BibleId, 118031001, N'“I made a covenant with my eyes; how then could I entertain thoughts against a virgin?'
EXEC add_BibleVerse @BibleId, 118031002, N'What then would be one’s lot from God above, one’s heritage from the Almighty on high?'
EXEC add_BibleVerse @BibleId, 118031003, N'Is it not misfortune for the unjust, and disaster for those who work iniquity?'
EXEC add_BibleVerse @BibleId, 118031004, N'Does he not see my ways and count all my steps?'
EXEC add_BibleVerse @BibleId, 118031005, N'If I have walked in falsehood, and if my foot has hastened to deceit –'
EXEC add_BibleVerse @BibleId, 118031006, N'let him weigh me with honest scales; then God will discover my integrity.'
EXEC add_BibleVerse @BibleId, 118031007, N'If my footsteps have strayed from the way, if my heart has gone after my eyes, or if anything has defiled my hands,'
EXEC add_BibleVerse @BibleId, 118031008, N'then let me sow and let another eat, and let my crops be uprooted.'
EXEC add_BibleVerse @BibleId, 118031009, N'If my heart has been enticed by a woman, and I have lain in wait at my neighbor’s door,'
EXEC add_BibleVerse @BibleId, 118031010, N'then let my wife turn the millstone for another man, and may other men have sexual relations with her.'
EXEC add_BibleVerse @BibleId, 118031011, N'For I would have committed a shameful act, an iniquity to be judged.'
EXEC add_BibleVerse @BibleId, 118031012, N'For it is a fire that devours even to Destruction, and it would uproot all my harvest.'
EXEC add_BibleVerse @BibleId, 118031013, N'“If I have disregarded the right of my male servants or my female servants when they disputed with me,'
EXEC add_BibleVerse @BibleId, 118031014, N'then what will I do when God confronts me in judgment; when he intervenes, how will I respond to him?'
EXEC add_BibleVerse @BibleId, 118031015, N'Did not the one who made me in the womb make them? Did not the same one form us in the womb?'
EXEC add_BibleVerse @BibleId, 118031016, N'If I have refused to give the poor what they desired, or caused the eyes of the widow to fail,'
EXEC add_BibleVerse @BibleId, 118031017, N'If I ate my morsel of bread myself, and did not share any of it with orphans –'
EXEC add_BibleVerse @BibleId, 118031018, N'but from my youth I raised the orphan like a father, and from my mother’s womb I guided the widow!'
EXEC add_BibleVerse @BibleId, 118031019, N'If I have seen anyone about to perish for lack of clothing, or a poor man without a coat,'
EXEC add_BibleVerse @BibleId, 118031020, N'whose heart did not bless me as he warmed himself with the fleece of my sheep,'
EXEC add_BibleVerse @BibleId, 118031021, N'if I have raised my hand to vote against the orphan, when I saw my support in the court,'
EXEC add_BibleVerse @BibleId, 118031022, N'then let my arm fall from the shoulder, let my arm be broken off at the socket.'
EXEC add_BibleVerse @BibleId, 118031023, N'For the calamity from God was a terror to me, and by reason of his majesty I was powerless.'
EXEC add_BibleVerse @BibleId, 118031024, N'“If I have put my confidence in gold or said to pure gold, ‘You are my security!’'
EXEC add_BibleVerse @BibleId, 118031025, N'if I have rejoiced because of the extent of my wealth, or because of the great wealth my hand had gained,'
EXEC add_BibleVerse @BibleId, 118031026, N'if I looked at the sun when it was shining, and the moon advancing as a precious thing,'
EXEC add_BibleVerse @BibleId, 118031027, N'so that my heart was secretly enticed, and my hand threw them a kiss from my mouth,'
EXEC add_BibleVerse @BibleId, 118031028, N'then this also would be iniquity to be judged, for I would have been false to God above.'
EXEC add_BibleVerse @BibleId, 118031029, N'If I have rejoiced over the misfortune of my enemy or exulted because calamity found him –'
EXEC add_BibleVerse @BibleId, 118031030, N'I have not even permitted my mouth to sin by asking for his life through a curse –'
EXEC add_BibleVerse @BibleId, 118031031, N'if the members of my household have never said, ‘If only there were someone who has not been satisfied from Job’s meat!’ –'
EXEC add_BibleVerse @BibleId, 118031032, N'But no stranger had to spend the night outside, for I opened my doors to the traveler –'
EXEC add_BibleVerse @BibleId, 118031033, N'if I have covered my transgressions as men do, by hiding iniquity in my heart,'
EXEC add_BibleVerse @BibleId, 118031034, N'because I was terrified of the great multitude, and the contempt of families terrified me, so that I remained silent and would not go outdoors –'
EXEC add_BibleVerse @BibleId, 118031035, N'“If only I had someone to hear me! Here is my signature – let the Almighty answer me! If only I had an indictment that my accuser had written.'
EXEC add_BibleVerse @BibleId, 118031036, N'Surely I would wear it proudly on my shoulder, I would bind it on me like a crown;'
EXEC add_BibleVerse @BibleId, 118031037, N'I would give him an accounting of my steps; like a prince I would approach him.'
EXEC add_BibleVerse @BibleId, 118031038, N'“If my land cried out against me and all its furrows wept together,'
EXEC add_BibleVerse @BibleId, 118031039, N'if I have eaten its produce without paying, or caused the death of its owners,'
EXEC add_BibleVerse @BibleId, 118031040, N'then let thorns sprout up in place of wheat, and in place of barley, weeds!” The words of Job are ended.'
EXEC add_BibleVerse @BibleId, 118032001, N'So these three men refused to answer Job further, because he was righteous in his own eyes.'
EXEC add_BibleVerse @BibleId, 118032002, N'Then Elihu son of Barakel the Buzite, of the family of Ram, became very angry. He was angry with Job for justifying himself rather than God.'
EXEC add_BibleVerse @BibleId, 118032003, N'With Job’s three friends he was also angry, because they could not find an answer, and so declared Job guilty.'
EXEC add_BibleVerse @BibleId, 118032004, N'Now Elihu had waited before speaking to Job, because the others were older than he was.'
EXEC add_BibleVerse @BibleId, 118032005, N'But when Elihu saw that the three men had no further reply, he became very angry.'
EXEC add_BibleVerse @BibleId, 118032006, N'So Elihu son of Barakel the Buzite spoke up: “I am young, but you are elderly; that is why I was fearful, and afraid to explain to you what I know.'
EXEC add_BibleVerse @BibleId, 118032007, N'I said to myself, ‘Age should speak, and length of years should make wisdom known.’'
EXEC add_BibleVerse @BibleId, 118032008, N'But it is a spirit in people, the breath of the Almighty, that makes them understand.'
EXEC add_BibleVerse @BibleId, 118032009, N'It is not the aged who are wise, nor old men who understand what is right.'
EXEC add_BibleVerse @BibleId, 118032010, N'Therefore I say, ‘Listen to me. I, even I, will explain what I know.’'
EXEC add_BibleVerse @BibleId, 118032011, N'Look, I waited for you to speak; I listened closely to your wise thoughts, while you were searching for words.'
EXEC add_BibleVerse @BibleId, 118032012, N'Now I was paying you close attention, yet there was no one proving Job wrong, not one of you was answering his statements!'
EXEC add_BibleVerse @BibleId, 118032013, N'So do not say, ‘We have found wisdom! God will refute him, not man!’'
EXEC add_BibleVerse @BibleId, 118032014, N'Job has not directed his words to me, and so I will not reply to him with your arguments.'
EXEC add_BibleVerse @BibleId, 118032015, N'“They are dismayed and cannot answer any more; they have nothing left to say.'
EXEC add_BibleVerse @BibleId, 118032016, N'And I have waited. But because they do not speak, because they stand there and answer no more,'
EXEC add_BibleVerse @BibleId, 118032017, N'I too will answer my part, I too will explain what I know.'
EXEC add_BibleVerse @BibleId, 118032018, N'For I am full of words, and the spirit within me constrains me.'
EXEC add_BibleVerse @BibleId, 118032019, N'Inside I am like wine which has no outlet, like new wineskins ready to burst!'
EXEC add_BibleVerse @BibleId, 118032020, N'I will speak, so that I may find relief; I will open my lips, so that I may answer.'
EXEC add_BibleVerse @BibleId, 118032021, N'I will not show partiality to anyone, nor will I confer a title on any man.'
EXEC add_BibleVerse @BibleId, 118032022, N'for I do not know how to give honorary titles, if I did, my Creator would quickly do away with me.'
EXEC add_BibleVerse @BibleId, 118033001, N'“But now, O Job, listen to my words, and hear everything I have to say!'
EXEC add_BibleVerse @BibleId, 118033002, N'See now, I have opened my mouth; my tongue in my mouth has spoken.'
EXEC add_BibleVerse @BibleId, 118033003, N'My words come from the uprightness of my heart, and my lips will utter knowledge sincerely.'
EXEC add_BibleVerse @BibleId, 118033004, N'The Spirit of God has made me, and the breath of the Almighty gives me life.'
EXEC add_BibleVerse @BibleId, 118033005, N'Reply to me, if you can; set your arguments in order before me and take your stand!'
EXEC add_BibleVerse @BibleId, 118033006, N'Look, I am just like you in relation to God; I too have been molded from clay.'
EXEC add_BibleVerse @BibleId, 118033007, N'Therefore no fear of me should terrify you, nor should my pressure be heavy on you.'
EXEC add_BibleVerse @BibleId, 118033008, N'“Indeed, you have said in my hearing (I heard the sound of the words!):'
EXEC add_BibleVerse @BibleId, 118033009, N'‘I am pure, without transgression; I am clean and have no iniquity.'
EXEC add_BibleVerse @BibleId, 118033010, N'Yet God finds occasions with me; he regards me as his enemy!'
EXEC add_BibleVerse @BibleId, 118033011, N'He puts my feet in shackles; he watches closely all my paths.’'
EXEC add_BibleVerse @BibleId, 118033012, N'Now in this, you are not right – I answer you, for God is greater than a human being.'
EXEC add_BibleVerse @BibleId, 118033013, N'Why do you contend against him, that he does not answer all a person’s words?'
EXEC add_BibleVerse @BibleId, 118033014, N'“For God speaks, the first time in one way, the second time in another, though a person does not perceive it.'
EXEC add_BibleVerse @BibleId, 118033015, N'In a dream, a night vision, when deep sleep falls on people as they sleep in their beds.'
EXEC add_BibleVerse @BibleId, 118033016, N'Then he gives a revelation to people, and terrifies them with warnings,'
EXEC add_BibleVerse @BibleId, 118033017, N'to turn a person from his sin, and to cover a person’s pride.'
EXEC add_BibleVerse @BibleId, 118033018, N'He spares a person’s life from corruption, his very life from crossing over the river.'
EXEC add_BibleVerse @BibleId, 118033019, N'Or a person is chastened by pain on his bed, and with the continual strife of his bones,'
EXEC add_BibleVerse @BibleId, 118033020, N'so that his life loathes food, and his soul rejects appetizing fare.'
EXEC add_BibleVerse @BibleId, 118033021, N'His flesh wastes away from sight, and his bones, which were not seen, are easily visible.'
EXEC add_BibleVerse @BibleId, 118033022, N'He draws near to the place of corruption, and his life to the messengers of death.'
EXEC add_BibleVerse @BibleId, 118033023, N'If there is an angel beside him, one mediator out of a thousand, to tell a person what constitutes his uprightness;'
EXEC add_BibleVerse @BibleId, 118033024, N'and if God is gracious to him and says, ‘Spare him from going down to the place of corruption, I have found a ransom for him,’'
EXEC add_BibleVerse @BibleId, 118033025, N'then his flesh is restored like a youth’s; he returns to the days of his youthful vigor.'
EXEC add_BibleVerse @BibleId, 118033026, N'He entreats God, and God delights in him, he sees God’s face with rejoicing, and God restores to him his righteousness.'
EXEC add_BibleVerse @BibleId, 118033027, N'That person sings to others, saying: ‘I have sinned and falsified what is right, but I was not punished according to what I deserved.'
EXEC add_BibleVerse @BibleId, 118033028, N'He redeemed my life from going down to the place of corruption, and my life sees the light!’'
EXEC add_BibleVerse @BibleId, 118033029, N'“Indeed, God does all these things, twice, three times, in his dealings with a person,'
EXEC add_BibleVerse @BibleId, 118033030, N'to turn back his life from the place of corruption, that he may be enlightened with the light of life.'
EXEC add_BibleVerse @BibleId, 118033031, N'Pay attention, Job – listen to me; be silent, and I will speak.'
EXEC add_BibleVerse @BibleId, 118033032, N'If you have any words, reply to me; speak, for I want to justify you.'
EXEC add_BibleVerse @BibleId, 118033033, N'If not, you listen to me; be silent, and I will teach you wisdom.”'
EXEC add_BibleVerse @BibleId, 118034001, N'Elihu answered:'
EXEC add_BibleVerse @BibleId, 118034002, N'“Listen to my words, you wise men; hear me, you learned men.'
EXEC add_BibleVerse @BibleId, 118034003, N'For the ear assesses words as the mouth tastes food.'
EXEC add_BibleVerse @BibleId, 118034004, N'Let us evaluate for ourselves what is right; let us come to know among ourselves what is good.'
EXEC add_BibleVerse @BibleId, 118034005, N'For Job says, ‘I am innocent, but God turns away my right.'
EXEC add_BibleVerse @BibleId, 118034006, N'Concerning my right, should I lie? My wound is incurable, although I am without transgression.’'
EXEC add_BibleVerse @BibleId, 118034007, N'What man is like Job, who drinks derision like water!'
EXEC add_BibleVerse @BibleId, 118034008, N'He goes about in company with evildoers, he goes along with wicked men.'
EXEC add_BibleVerse @BibleId, 118034009, N'For he says, ‘It does not profit a man when he makes his delight with God.’'
EXEC add_BibleVerse @BibleId, 118034010, N'“Therefore, listen to me, you men of understanding. Far be it from God to do wickedness, from the Almighty to do evil.'
EXEC add_BibleVerse @BibleId, 118034011, N'For he repays a person for his work, and according to the conduct of a person, he causes the consequences to find him.'
EXEC add_BibleVerse @BibleId, 118034012, N'Indeed, in truth, God does not act wickedly, and the Almighty does not pervert justice.'
EXEC add_BibleVerse @BibleId, 118034013, N'Who entrusted to him the earth? And who put him over the whole world?'
EXEC add_BibleVerse @BibleId, 118034014, N'If God were to set his heart on it, and gather in his spirit and his breath,'
EXEC add_BibleVerse @BibleId, 118034015, N'all flesh would perish together and human beings would return to dust.'
EXEC add_BibleVerse @BibleId, 118034016, N'“If you have understanding, listen to this, hear what I have to say.'
EXEC add_BibleVerse @BibleId, 118034017, N'Do you really think that one who hates justice can govern? And will you declare guilty the supremely righteous One,'
EXEC add_BibleVerse @BibleId, 118034018, N'who says to a king, ‘Worthless man’ and to nobles, ‘Wicked men,’'
EXEC add_BibleVerse @BibleId, 118034019, N'who shows no partiality to princes, and does not take note of the rich more than the poor, because all of them are the work of his hands?'
EXEC add_BibleVerse @BibleId, 118034020, N'In a moment they die, in the middle of the night, people are shaken and they pass away. The mighty are removed effortlessly.'
EXEC add_BibleVerse @BibleId, 118034021, N'For his eyes are on the ways of an individual, he observes all a person’s steps.'
EXEC add_BibleVerse @BibleId, 118034022, N'There is no darkness, and no deep darkness, where evildoers can hide themselves.'
EXEC add_BibleVerse @BibleId, 118034023, N'For he does not still consider a person, that he should come before God in judgment.'
EXEC add_BibleVerse @BibleId, 118034024, N'He shatters the great without inquiry, and sets up others in their place.'
EXEC add_BibleVerse @BibleId, 118034025, N'Therefore, he knows their deeds, he overthrows them in the night and they are crushed.'
EXEC add_BibleVerse @BibleId, 118034026, N'He strikes them for their wickedness, in a place where people can see,'
EXEC add_BibleVerse @BibleId, 118034027, N'because they have turned away from following him, and have not understood any of his ways,'
EXEC add_BibleVerse @BibleId, 118034028, N'so that they caused the cry of the poor to come before him, so that he hears the cry of the needy.'
EXEC add_BibleVerse @BibleId, 118034029, N'But if God is quiet, who can condemn him? If he hides his face, then who can see him? Yet he is over the individual and the nation alike,'
EXEC add_BibleVerse @BibleId, 118034030, N'so that the godless man should not rule, and not lay snares for the people.'
EXEC add_BibleVerse @BibleId, 118034031, N'“Has anyone said to God, ‘I have endured chastisement, but I will not act wrongly any more.'
EXEC add_BibleVerse @BibleId, 118034032, N'Teach me what I cannot see. If I have done evil, I will do so no more.’'
EXEC add_BibleVerse @BibleId, 118034033, N'Is it your opinion that God should recompense it, because you reject this? But you must choose, and not I, so tell us what you know.'
EXEC add_BibleVerse @BibleId, 118034034, N'Men of understanding say to me – any wise man listening to me says –'
EXEC add_BibleVerse @BibleId, 118034035, N'that Job speaks without knowledge and his words are without understanding.'
EXEC add_BibleVerse @BibleId, 118034036, N'But Job will be tested to the end, because his answers are like those of wicked men.'
EXEC add_BibleVerse @BibleId, 118034037, N'For he adds transgression to his sin; in our midst he claps his hands, and multiplies his words against God.”'
EXEC add_BibleVerse @BibleId, 118035001, N'Then Elihu answered:'
EXEC add_BibleVerse @BibleId, 118035002, N'“Do you think this to be just: when you say, ‘My right before God.’'
EXEC add_BibleVerse @BibleId, 118035003, N'But you say, ‘What will it profit you,’ and, ‘What do I gain by not sinning?’'
EXEC add_BibleVerse @BibleId, 118035004, N'I will reply to you, and to your friends with you.'
EXEC add_BibleVerse @BibleId, 118035005, N'Gaze at the heavens and see; consider the clouds, which are higher than you!'
EXEC add_BibleVerse @BibleId, 118035006, N'If you sin, how does it affect God? If your transgressions are many, what does it do to him?'
EXEC add_BibleVerse @BibleId, 118035007, N'If you are righteous, what do you give to God, or what does he receive from your hand?'
EXEC add_BibleVerse @BibleId, 118035008, N'Your wickedness affects only a person like yourself, and your righteousness only other people.'
EXEC add_BibleVerse @BibleId, 118035009, N'“People cry out because of the excess of oppression; they cry out for help because of the power of the mighty.'
EXEC add_BibleVerse @BibleId, 118035010, N'But no one says, ‘Where is God, my Creator, who gives songs in the night,'
EXEC add_BibleVerse @BibleId, 118035011, N'who teaches us more than the wild animals of the earth, and makes us wiser than the birds of the sky?’'
EXEC add_BibleVerse @BibleId, 118035012, N'Then they cry out – but he does not answer – because of the arrogance of the wicked.'
EXEC add_BibleVerse @BibleId, 118035013, N'Surely it is an empty cry – God does not hear it; the Almighty does not take notice of it.'
EXEC add_BibleVerse @BibleId, 118035014, N'How much less, then, when you say that you do not perceive him, that the case is before him and you are waiting for him!'
EXEC add_BibleVerse @BibleId, 118035015, N'And further, when you say that his anger does not punish, and that he does not know transgression!'
EXEC add_BibleVerse @BibleId, 118035016, N'So Job opens his mouth to no purpose; without knowledge he multiplies words.”'
EXEC add_BibleVerse @BibleId, 118036001, N'Elihu said further:'
EXEC add_BibleVerse @BibleId, 118036002, N'“Be patient with me a little longer and I will instruct you, for I still have words to speak on God’s behalf.'
EXEC add_BibleVerse @BibleId, 118036003, N'With my knowledge I will speak comprehensively, and to my Creator I will ascribe righteousness.'
EXEC add_BibleVerse @BibleId, 118036004, N'For in truth, my words are not false; it is one complete in knowledge who is with you.'
EXEC add_BibleVerse @BibleId, 118036005, N'Indeed, God is mighty; and he does not despise people, he is mighty, and firm in his intent.'
EXEC add_BibleVerse @BibleId, 118036006, N'He does not allow the wicked to live, but he gives justice to the poor.'
EXEC add_BibleVerse @BibleId, 118036007, N'He does not take his eyes off the righteous; but with kings on the throne he seats the righteous and exalts them forever.'
EXEC add_BibleVerse @BibleId, 118036008, N'But if they are bound in chains, and held captive by the cords of affliction,'
EXEC add_BibleVerse @BibleId, 118036009, N'then he reveals to them what they have done, and their transgressions, that they were behaving proudly.'
EXEC add_BibleVerse @BibleId, 118036010, N'And he reveals this for correction, and says that they must turn from evil.'
EXEC add_BibleVerse @BibleId, 118036011, N'If they obey and serve him, they live out their days in prosperity and their years in pleasantness.'
EXEC add_BibleVerse @BibleId, 118036012, N'But if they refuse to listen, they pass over the river of death, and expire without knowledge.'
EXEC add_BibleVerse @BibleId, 118036013, N'The godless at heart nourish anger, they do not cry out even when he binds them.'
EXEC add_BibleVerse @BibleId, 118036014, N'They die in their youth, and their life ends among the male cultic prostitutes.'
EXEC add_BibleVerse @BibleId, 118036015, N'He delivers the afflicted by their afflictions, he reveals himself to them by their suffering.'
EXEC add_BibleVerse @BibleId, 118036016, N'And surely, he drew you from the mouth of distress, to a wide place, unrestricted, and to the comfort of your table filled with rich food.'
EXEC add_BibleVerse @BibleId, 118036017, N'But now you are preoccupied with the judgment due the wicked, judgment and justice take hold of you.'
EXEC add_BibleVerse @BibleId, 118036018, N'Be careful that no one entices you with riches; do not let a large bribe turn you aside.'
EXEC add_BibleVerse @BibleId, 118036019, N'Would your wealth sustain you, so that you would not be in distress, even all your mighty efforts?'
EXEC add_BibleVerse @BibleId, 118036020, N'Do not long for the cover of night to drag people away from their homes.'
EXEC add_BibleVerse @BibleId, 118036021, N'Take heed, do not turn to evil, for because of this you have been tested by affliction.'
EXEC add_BibleVerse @BibleId, 118036022, N'Indeed, God is exalted in his power; who is a teacher like him?'
EXEC add_BibleVerse @BibleId, 118036023, N'Who has prescribed his ways for him? Or said to him, ‘You have done what is wicked’?'
EXEC add_BibleVerse @BibleId, 118036024, N'Remember to extol his work, which people have praised in song.'
EXEC add_BibleVerse @BibleId, 118036025, N'All humanity has seen it; people gaze on it from afar.'
EXEC add_BibleVerse @BibleId, 118036026, N'“Yes, God is great – beyond our knowledge! The number of his years is unsearchable.'
EXEC add_BibleVerse @BibleId, 118036027, N'He draws up drops of water; they distill the rain into its mist,'
EXEC add_BibleVerse @BibleId, 118036028, N'which the clouds pour down and shower on humankind abundantly.'
EXEC add_BibleVerse @BibleId, 118036029, N'Who can understand the spreading of the clouds, the thunderings of his pavilion?'
EXEC add_BibleVerse @BibleId, 118036030, N'See how he scattered his lightning about him; he has covered the depths of the sea.'
EXEC add_BibleVerse @BibleId, 118036031, N'It is by these that he judges the nations and supplies food in abundance.'
EXEC add_BibleVerse @BibleId, 118036032, N'With his hands he covers the lightning, and directs it against its target.'
EXEC add_BibleVerse @BibleId, 118036033, N'His thunder announces the coming storm, the cattle also, concerning the storm’s approach.'
EXEC add_BibleVerse @BibleId, 118037001, N'At this also my heart pounds and leaps from its place.'
EXEC add_BibleVerse @BibleId, 118037002, N'Listen carefully to the thunder of his voice, to the rumbling that proceeds from his mouth.'
EXEC add_BibleVerse @BibleId, 118037003, N'Under the whole heaven he lets it go, even his lightning to the far corners of the earth.'
EXEC add_BibleVerse @BibleId, 118037004, N'After that a voice roars; he thunders with an exalted voice, and he does not hold back his lightning bolts when his voice is heard.'
EXEC add_BibleVerse @BibleId, 118037005, N'God thunders with his voice in marvelous ways; he does great things beyond our understanding.'
EXEC add_BibleVerse @BibleId, 118037006, N'For to the snow he says, ‘Fall to earth,’ and to the torrential rains, ‘Pour down.’'
EXEC add_BibleVerse @BibleId, 118037007, N'He causes everyone to stop working, so that all people may know his work.'
EXEC add_BibleVerse @BibleId, 118037008, N'The wild animals go to their lairs, and in their dens they remain.'
EXEC add_BibleVerse @BibleId, 118037009, N'A tempest blows out from its chamber, icy cold from the driving winds.'
EXEC add_BibleVerse @BibleId, 118037010, N'The breath of God produces ice, and the breadth of the waters freeze solid.'
EXEC add_BibleVerse @BibleId, 118037011, N'He loads the clouds with moisture; he scatters his lightning through the clouds.'
EXEC add_BibleVerse @BibleId, 118037012, N'The clouds go round in circles, wheeling about according to his plans, to carry out all that he commands them over the face of the whole inhabited world.'
EXEC add_BibleVerse @BibleId, 118037013, N'Whether it is for punishment for his land, or whether it is for mercy, he causes it to find its mark.'
EXEC add_BibleVerse @BibleId, 118037014, N'“Pay attention to this, Job! Stand still and consider the wonders God works.'
EXEC add_BibleVerse @BibleId, 118037015, N'Do you know how God commands them, how he makes lightning flash in his storm cloud?'
EXEC add_BibleVerse @BibleId, 118037016, N'Do you know about the balancing of the clouds, that wondrous activity of him who is perfect in knowledge?'
EXEC add_BibleVerse @BibleId, 118037017, N'You, whose garments are hot when the earth is still because of the south wind,'
EXEC add_BibleVerse @BibleId, 118037018, N'will you, with him, spread out the clouds, solid as a mirror of molten metal?'
EXEC add_BibleVerse @BibleId, 118037019, N'Tell us what we should say to him. We cannot prepare a case because of the darkness.'
EXEC add_BibleVerse @BibleId, 118037020, N'Should he be informed that I want to speak? If a man speaks, surely he would be swallowed up!'
EXEC add_BibleVerse @BibleId, 118037021, N'But now, the sun cannot be looked at – it is bright in the skies – after a wind passed and swept the clouds away.'
EXEC add_BibleVerse @BibleId, 118037022, N'From the north he comes in golden splendor; around God is awesome majesty.'
EXEC add_BibleVerse @BibleId, 118037023, N'As for the Almighty, we cannot attain to him! He is great in power, but justice and abundant righteousness he does not oppress.'
EXEC add_BibleVerse @BibleId, 118037024, N'Therefore people fear him, for he does not regard all the wise in heart.”'
EXEC add_BibleVerse @BibleId, 118038001, N'Then the Lord answered Job out of the whirlwind:'
EXEC add_BibleVerse @BibleId, 118038002, N'“Who is this who darkens counsel with words without knowledge?'
EXEC add_BibleVerse @BibleId, 118038003, N'Get ready for a difficult task like a man; I will question you and you will inform me!'
EXEC add_BibleVerse @BibleId, 118038004, N'“Where were you when I laid the foundation of the earth? Tell me, if you possess understanding!'
EXEC add_BibleVerse @BibleId, 118038005, N'Who set its measurements – if you know – or who stretched a measuring line across it?'
EXEC add_BibleVerse @BibleId, 118038006, N'On what were its bases set, or who laid its cornerstone –'
EXEC add_BibleVerse @BibleId, 118038007, N'when the morning stars sang in chorus, and all the sons of God shouted for joy?'
EXEC add_BibleVerse @BibleId, 118038008, N'“Who shut up the sea with doors when it burst forth, coming out of the womb,'
EXEC add_BibleVerse @BibleId, 118038009, N'when I made the storm clouds its garment, and thick darkness its swaddling band,'
EXEC add_BibleVerse @BibleId, 118038010, N'when I prescribed its limits, and set in place its bolts and doors,'
EXEC add_BibleVerse @BibleId, 118038011, N'when I said, ‘To here you may come and no farther, here your proud waves will be confined’?'
EXEC add_BibleVerse @BibleId, 118038012, N'Have you ever in your life commanded the morning, or made the dawn know its place,'
EXEC add_BibleVerse @BibleId, 118038013, N'that it might seize the corners of the earth, and shake the wicked out of it?'
EXEC add_BibleVerse @BibleId, 118038014, N'The earth takes shape like clay under a seal; its features are dyed like a garment.'
EXEC add_BibleVerse @BibleId, 118038015, N'Then from the wicked the light is withheld, and the arm raised in violence is broken.'
EXEC add_BibleVerse @BibleId, 118038016, N'Have you gone to the springs that fill the sea, or walked about in the recesses of the deep?'
EXEC add_BibleVerse @BibleId, 118038017, N'Have the gates of death been revealed to you? Have you seen the gates of deepest darkness?'
EXEC add_BibleVerse @BibleId, 118038018, N'Have you considered the vast expanses of the earth? Tell me, if you know it all!'
EXEC add_BibleVerse @BibleId, 118038019, N'“In what direction does light reside, and darkness, where is its place,'
EXEC add_BibleVerse @BibleId, 118038020, N'that you may take them to their borders and perceive the pathways to their homes?'
EXEC add_BibleVerse @BibleId, 118038021, N'You know, for you were born before them; and the number of your days is great!'
EXEC add_BibleVerse @BibleId, 118038022, N'Have you entered the storehouse of the snow, or seen the armory of the hail,'
EXEC add_BibleVerse @BibleId, 118038023, N'which I reserve for the time of trouble, for the day of war and battle?'
EXEC add_BibleVerse @BibleId, 118038024, N'In what direction is lightning dispersed, or the east winds scattered over the earth?'
EXEC add_BibleVerse @BibleId, 118038025, N'Who carves out a channel for the heavy rains, and a path for the rumble of thunder,'
EXEC add_BibleVerse @BibleId, 118038026, N'to cause it to rain on an uninhabited land, a desert where there are no human beings,'
EXEC add_BibleVerse @BibleId, 118038027, N'to satisfy a devastated and desolate land, and to cause it to sprout with vegetation?'
EXEC add_BibleVerse @BibleId, 118038028, N'Does the rain have a father, or who has fathered the drops of the dew?'
EXEC add_BibleVerse @BibleId, 118038029, N'From whose womb does the ice emerge, and the frost from the sky, who gives birth to it,'
EXEC add_BibleVerse @BibleId, 118038030, N'when the waters become hard like stone, when the surface of the deep is frozen solid?'
EXEC add_BibleVerse @BibleId, 118038031, N'Can you tie the bands of the Pleiades, or release the cords of Orion?'
EXEC add_BibleVerse @BibleId, 118038032, N'Can you lead out the constellations in their seasons, or guide the Bear with its cubs?'
EXEC add_BibleVerse @BibleId, 118038033, N'Do you know the laws of the heavens, or can you set up their rule over the earth?'
EXEC add_BibleVerse @BibleId, 118038034, N'Can you raise your voice to the clouds so that a flood of water covers you?'
EXEC add_BibleVerse @BibleId, 118038035, N'Can you send out lightning bolts, and they go? Will they say to you, ‘Here we are’?'
EXEC add_BibleVerse @BibleId, 118038036, N'Who has put wisdom in the heart, or has imparted understanding to the mind?'
EXEC add_BibleVerse @BibleId, 118038037, N'Who by wisdom can count the clouds, and who can tip over the water jars of heaven,'
EXEC add_BibleVerse @BibleId, 118038038, N'when the dust hardens into a mass, and the clumps of earth stick together?'
EXEC add_BibleVerse @BibleId, 118038039, N'“Do you hunt prey for the lioness, and satisfy the appetite of the lions,'
EXEC add_BibleVerse @BibleId, 118038040, N'when they crouch in their dens, when they wait in ambush in the thicket?'
EXEC add_BibleVerse @BibleId, 118038041, N'Who prepares prey for the raven, when its young cry out to God and wander about for lack of food?'
EXEC add_BibleVerse @BibleId, 118039001, N'“Are you acquainted with the way the mountain goats give birth? Do you watch as the wild deer give birth to their young?'
EXEC add_BibleVerse @BibleId, 118039002, N'Do you count the months they must fulfill, and do you know the time they give birth?'
EXEC add_BibleVerse @BibleId, 118039003, N'They crouch, they bear their young, they bring forth the offspring they have carried.'
EXEC add_BibleVerse @BibleId, 118039004, N'Their young grow strong, and grow up in the open; they go off, and do not return to them.'
EXEC add_BibleVerse @BibleId, 118039005, N'Who let the wild donkey go free? Who released the bonds of the donkey,'
EXEC add_BibleVerse @BibleId, 118039006, N'to whom I appointed the steppe for its home, the salt wastes as its dwelling place?'
EXEC add_BibleVerse @BibleId, 118039007, N'It scorns the tumult in the town; it does not hear the shouts of a driver.'
EXEC add_BibleVerse @BibleId, 118039008, N'It ranges the hills as its pasture, and searches after every green plant.'
EXEC add_BibleVerse @BibleId, 118039009, N'Is the wild ox willing to be your servant? Will it spend the night at your feeding trough?'
EXEC add_BibleVerse @BibleId, 118039010, N'Can you bind the wild ox to a furrow with its rope, will it till the valleys, following after you?'
EXEC add_BibleVerse @BibleId, 118039011, N'Will you rely on it because its strength is great? Will you commit your labor to it?'
EXEC add_BibleVerse @BibleId, 118039012, N'Can you count on it to bring in your grain, and gather the grain to your threshing floor?'
EXEC add_BibleVerse @BibleId, 118039013, N'“The wings of the ostrich flap with joy, but are they the pinions and plumage of a stork?'
EXEC add_BibleVerse @BibleId, 118039014, N'For she leaves her eggs on the ground, and lets them be warmed on the soil.'
EXEC add_BibleVerse @BibleId, 118039015, N'She forgets that a foot might crush them, or that a wild animal might trample them.'
EXEC add_BibleVerse @BibleId, 118039016, N'She is harsh with her young, as if they were not hers; she is unconcerned about the uselessness of her labor.'
EXEC add_BibleVerse @BibleId, 118039017, N'For God deprived her of wisdom, and did not impart understanding to her.'
EXEC add_BibleVerse @BibleId, 118039018, N'But as soon as she springs up, she laughs at the horse and its rider.'
EXEC add_BibleVerse @BibleId, 118039019, N'“Do you give the horse its strength? Do you clothe its neck with a mane?'
EXEC add_BibleVerse @BibleId, 118039020, N'Do you make it leap like a locust? Its proud neighing is terrifying!'
EXEC add_BibleVerse @BibleId, 118039021, N'It paws the ground in the valley, exulting mightily, it goes out to meet the weapons.'
EXEC add_BibleVerse @BibleId, 118039022, N'It laughs at fear and is not dismayed; it does not shy away from the sword.'
EXEC add_BibleVerse @BibleId, 118039023, N'On it the quiver rattles; the lance and javelin flash.'
EXEC add_BibleVerse @BibleId, 118039024, N'In excitement and impatience it consumes the ground; it cannot stand still when the trumpet is blown.'
EXEC add_BibleVerse @BibleId, 118039025, N'At the sound of the trumpet, it says, ‘Aha!’ And from a distance it catches the scent of battle, the thunderous shouting of commanders, and the battle cries.'
EXEC add_BibleVerse @BibleId, 118039026, N'“Is it by your understanding that the hawk soars, and spreads its wings toward the south?'
EXEC add_BibleVerse @BibleId, 118039027, N'Is it at your command that the eagle soars, and builds its nest on high?'
EXEC add_BibleVerse @BibleId, 118039028, N'It lives on a rock and spends the night there, on a rocky crag and a fortress.'
EXEC add_BibleVerse @BibleId, 118039029, N'From there it spots its prey, its eyes gaze intently from a distance.'
EXEC add_BibleVerse @BibleId, 118039030, N'And its young ones devour the blood, and where the dead carcasses are, there it is.”'
EXEC add_BibleVerse @BibleId, 118040001, N'Then the Lord answered Job:'
EXEC add_BibleVerse @BibleId, 118040002, N'“Will the one who contends with the Almighty correct him? Let the person who accuses God give him an answer!”'
EXEC add_BibleVerse @BibleId, 118040003, N'Then Job answered the Lord:'
EXEC add_BibleVerse @BibleId, 118040004, N'“Indeed, I am completely unworthy – how could I reply to you? I put my hand over my mouth to silence myself.'
EXEC add_BibleVerse @BibleId, 118040005, N'I have spoken once, but I cannot answer; twice, but I will say no more.”'
EXEC add_BibleVerse @BibleId, 118040006, N'Then the Lord answered Job from the whirlwind:'
EXEC add_BibleVerse @BibleId, 118040007, N'“Get ready for a difficult task like a man. I will question you and you will inform me!'
EXEC add_BibleVerse @BibleId, 118040008, N'Would you indeed annul my justice? Would you declare me guilty so that you might be right?'
EXEC add_BibleVerse @BibleId, 118040009, N'Do you have an arm as powerful as God’s, and can you thunder with a voice like his?'
EXEC add_BibleVerse @BibleId, 118040010, N'Adorn yourself, then, with majesty and excellency, and clothe yourself with glory and honor!'
EXEC add_BibleVerse @BibleId, 118040011, N'Scatter abroad the abundance of your anger. Look at every proud man and bring him low;'
EXEC add_BibleVerse @BibleId, 118040012, N'Look at every proud man and abase him; crush the wicked on the spot!'
EXEC add_BibleVerse @BibleId, 118040013, N'Hide them in the dust together, imprison them in the grave.'
EXEC add_BibleVerse @BibleId, 118040014, N'Then I myself will acknowledge to you that your own right hand can save you.'
EXEC add_BibleVerse @BibleId, 118040015, N'“Look now at Behemoth, which I made as I made you; it eats grass like the ox.'
EXEC add_BibleVerse @BibleId, 118040016, N'Look at its strength in its loins, and its power in the muscles of its belly.'
EXEC add_BibleVerse @BibleId, 118040017, N'It makes its tail stiff like a cedar, the sinews of its thighs are tightly wound.'
EXEC add_BibleVerse @BibleId, 118040018, N'Its bones are tubes of bronze, its limbs like bars of iron.'
EXEC add_BibleVerse @BibleId, 118040019, N'It ranks first among the works of God, the One who made it has furnished it with a sword.'
EXEC add_BibleVerse @BibleId, 118040020, N'For the hills bring it food, where all the wild animals play.'
EXEC add_BibleVerse @BibleId, 118040021, N'Under the lotus trees it lies, in the secrecy of the reeds and the marsh.'
EXEC add_BibleVerse @BibleId, 118040022, N'The lotus trees conceal it in their shadow; the poplars by the stream conceal it.'
EXEC add_BibleVerse @BibleId, 118040023, N'If the river rages, it is not disturbed, it is secure, though the Jordan should surge up to its mouth.'
EXEC add_BibleVerse @BibleId, 118040024, N'Can anyone catch it by its eyes, or pierce its nose with a snare?'
EXEC add_BibleVerse @BibleId, 118041001, N'“Can you pull in Leviathan with a hook, and tie down its tongue with a rope?'
EXEC add_BibleVerse @BibleId, 118041002, N'Can you put a cord through its nose, or pierce its jaw with a hook?'
EXEC add_BibleVerse @BibleId, 118041003, N'Will it make numerous supplications to you, will it speak to you with tender words?'
EXEC add_BibleVerse @BibleId, 118041004, N'Will it make a pact with you, so you could take it as your slave for life?'
EXEC add_BibleVerse @BibleId, 118041005, N'Can you play with it, like a bird, or tie it on a leash for your girls?'
EXEC add_BibleVerse @BibleId, 118041006, N'Will partners bargain for it? Will they divide it up among the merchants?'
EXEC add_BibleVerse @BibleId, 118041007, N'Can you fill its hide with harpoons or its head with fishing spears?'
EXEC add_BibleVerse @BibleId, 118041008, N'If you lay your hand on it, you will remember the fight, and you will never do it again!'
EXEC add_BibleVerse @BibleId, 118041009, N'See, his expectation is wrong, he is laid low even at the sight of it.'
EXEC add_BibleVerse @BibleId, 118041010, N'Is it not fierce when it is awakened? Who is he, then, who can stand before it?'
EXEC add_BibleVerse @BibleId, 118041011, N'(Who has confronted me that I should repay? Everything under heaven belongs to me!)'
EXEC add_BibleVerse @BibleId, 118041012, N'I will not keep silent about its limbs, and the extent of its might, and the grace of its arrangement.'
EXEC add_BibleVerse @BibleId, 118041013, N'Who can uncover its outer covering? Who can penetrate to the inside of its armor?'
EXEC add_BibleVerse @BibleId, 118041014, N'Who can open the doors of its mouth? Its teeth all around are fearsome.'
EXEC add_BibleVerse @BibleId, 118041015, N'Its back has rows of shields, shut up closely together as with a seal;'
EXEC add_BibleVerse @BibleId, 118041016, N'each one is so close to the next that no air can come between them.'
EXEC add_BibleVerse @BibleId, 118041017, N'They lock tightly together, one to the next; they cling together and cannot be separated.'
EXEC add_BibleVerse @BibleId, 118041018, N'Its snorting throws out flashes of light; its eyes are like the red glow of dawn.'
EXEC add_BibleVerse @BibleId, 118041019, N'Out of its mouth go flames, sparks of fire shoot forth!'
EXEC add_BibleVerse @BibleId, 118041020, N'Smoke streams from its nostrils as from a boiling pot over burning rushes.'
EXEC add_BibleVerse @BibleId, 118041021, N'Its breath sets coals ablaze and a flame shoots from its mouth.'
EXEC add_BibleVerse @BibleId, 118041022, N'Strength lodges in its neck, and despair runs before it.'
EXEC add_BibleVerse @BibleId, 118041023, N'The folds of its flesh are tightly joined; they are firm on it, immovable.'
EXEC add_BibleVerse @BibleId, 118041024, N'Its heart is hard as rock, hard as a lower millstone.'
EXEC add_BibleVerse @BibleId, 118041025, N'When it rises up, the mighty are terrified, at its thrashing about they withdraw.'
EXEC add_BibleVerse @BibleId, 118041026, N'Whoever strikes it with a sword will have no effect, nor with the spear, arrow, or dart.'
EXEC add_BibleVerse @BibleId, 118041027, N'It regards iron as straw and bronze as rotten wood.'
EXEC add_BibleVerse @BibleId, 118041028, N'Arrows do not make it flee; slingstones become like chaff to it.'
EXEC add_BibleVerse @BibleId, 118041029, N'A club is counted as a piece of straw; it laughs at the rattling of the lance.'
EXEC add_BibleVerse @BibleId, 118041030, N'Its underparts are the sharp points of potsherds, it leaves its mark in the mud like a threshing sledge.'
EXEC add_BibleVerse @BibleId, 118041031, N'It makes the deep boil like a cauldron and stirs up the sea like a pot of ointment,'
EXEC add_BibleVerse @BibleId, 118041032, N'It leaves a glistening wake behind it; one would think the deep had a head of white hair.'
EXEC add_BibleVerse @BibleId, 118041033, N'The likes of it is not on earth, a creature without fear.'
EXEC add_BibleVerse @BibleId, 118041034, N'It looks on every haughty being; it is king over all that are proud.”'
EXEC add_BibleVerse @BibleId, 118042001, N'Then Job answered the Lord:'
EXEC add_BibleVerse @BibleId, 118042002, N'“I know that you can do all things; no purpose of yours can be thwarted;'
EXEC add_BibleVerse @BibleId, 118042003, N'you asked, ‘Who is this who darkens counsel without knowledge?’ But I have declared without understanding things too wonderful for me to know.'
EXEC add_BibleVerse @BibleId, 118042004, N'You said, ‘Pay attention, and I will speak; I will question you, and you will answer me.’'
EXEC add_BibleVerse @BibleId, 118042005, N'I had heard of you by the hearing of the ear, but now my eye has seen you.'
EXEC add_BibleVerse @BibleId, 118042006, N'Therefore I despise myself, and I repent in dust and ashes!'
EXEC add_BibleVerse @BibleId, 118042007, N'After the Lord had spoken these things to Job, he said to Eliphaz the Temanite, “My anger is stirred up against you and your two friends, because you have not spoken about me what is right, as my servant Job has.'
EXEC add_BibleVerse @BibleId, 118042008, N'So now take seven bulls and seven rams and go to my servant Job and offer a burnt offering for yourselves. And my servant Job will intercede for you, and I will respect him, so that I do not deal with you according to your folly, because you have not spoken about me what is right, as my servant Job has.”'
EXEC add_BibleVerse @BibleId, 118042009, N'So they went, Eliphaz the Temanite, Bildad the Shuhite, and Zophar the Naamathite, and did just as the Lord had told them; and the Lord had respect for Job.'
EXEC add_BibleVerse @BibleId, 118042010, N'So the Lord restored what Job had lost after he prayed for his friends, and the Lord doubled all that had belonged to Job.'
EXEC add_BibleVerse @BibleId, 118042011, N'So they came to him, all his brothers and sisters and all who had known him before, and they dined with him in his house. They comforted him and consoled him for all the trouble the Lord had brought on him, and each one gave him a piece of silver and a gold ring.'
EXEC add_BibleVerse @BibleId, 118042012, N'So the Lord blessed the second part of Job’s life more than the first. He had 14,000 sheep, 6,000 camels, 1,000 yoke of oxen, and 1,000 female donkeys.'
EXEC add_BibleVerse @BibleId, 118042013, N'And he also had seven sons and three daughters.'
EXEC add_BibleVerse @BibleId, 118042014, N'The first daughter he named Jemimah, the second Keziah, and the third Keren-Happuch.'
EXEC add_BibleVerse @BibleId, 118042015, N'Nowhere in all the land could women be found who were as beautiful as Job’s daughters, and their father granted them an inheritance alongside their brothers.'
EXEC add_BibleVerse @BibleId, 118042016, N'After this Job lived 140 years; he saw his children and their children to the fourth generation.'
EXEC add_BibleVerse @BibleId, 118042017, N'And so Job died, old and full of days.'
EXEC add_BibleVerse @BibleId, 119001001, N'How blessed is the one who does not follow the advice of the wicked, or stand in the pathway with sinners, or sit in the assembly of scoffers!'
EXEC add_BibleVerse @BibleId, 119001002, N'Instead he finds pleasure in obeying the Lord’s commands; he meditates on his commands day and night.'
EXEC add_BibleVerse @BibleId, 119001003, N'He is like a tree planted by flowing streams; it yields its fruit at the proper time, and its leaves never fall off. He succeeds in everything he attempts.'
EXEC add_BibleVerse @BibleId, 119001004, N'Not so with the wicked! Instead they are like wind-driven chaff.'
EXEC add_BibleVerse @BibleId, 119001005, N'For this reason the wicked cannot withstand judgment, nor can sinners join the assembly of the godly.'
EXEC add_BibleVerse @BibleId, 119001006, N'Certainly the Lord guards the way of the godly, but the way of the wicked ends in destruction.'
EXEC add_BibleVerse @BibleId, 119002001, N'Why do the nations rebel? Why are the countries devising plots that will fail?'
EXEC add_BibleVerse @BibleId, 119002002, N'The kings of the earth form a united front; the rulers collaborate against the Lord and his anointed king.'
EXEC add_BibleVerse @BibleId, 119002003, N'They say, “Let’s tear off the shackles they’ve put on us! Let’s free ourselves from their ropes!”'
EXEC add_BibleVerse @BibleId, 119002004, N'The one enthroned in heaven laughs in disgust; the Lord taunts them.'
EXEC add_BibleVerse @BibleId, 119002005, N'Then he angrily speaks to them and terrifies them in his rage, saying,'
EXEC add_BibleVerse @BibleId, 119002006, N'“I myself have installed my king on Zion, my holy hill.”'
EXEC add_BibleVerse @BibleId, 119002007, N'The king says, “I will announce the Lord’s decree. He said to me: ‘You are my son! This very day I have become your father!'
EXEC add_BibleVerse @BibleId, 119002008, N'Ask me, and I will give you the nations as your inheritance, the ends of the earth as your personal property.'
EXEC add_BibleVerse @BibleId, 119002009, N'You will break them with an iron scepter; you will smash them like a potter’s jar!’”'
EXEC add_BibleVerse @BibleId, 119002010, N'So now, you kings, do what is wise; you rulers of the earth, submit to correction!'
EXEC add_BibleVerse @BibleId, 119002011, N'Serve the Lord in fear! Repent in terror!'
EXEC add_BibleVerse @BibleId, 119002012, N'Give sincere homage! Otherwise he will be angry, and you will die because of your behavior, when his anger quickly ignites. How blessed are all who take shelter in him!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119003001, @markup=N'Lord, how numerous are my enemies! Many attack me. ', @premarkup=N'A psalm of David, written when he fled from his son Absalom.'
EXEC add_BibleVerse @BibleId, 119003002, N'Many say about me, “God will not deliver him.” (Selah)'
EXEC add_BibleVerse @BibleId, 119003003, N'But you, Lord, are a shield that protects me; you are my glory and the one who restores me.'
EXEC add_BibleVerse @BibleId, 119003004, N'To the Lord I cried out, and he answered me from his holy hill. (Selah)'
EXEC add_BibleVerse @BibleId, 119003005, N'I rested and slept; I awoke, for the Lord protects me.'
EXEC add_BibleVerse @BibleId, 119003006, N'I am not afraid of the multitude of people who attack me from all directions.'
EXEC add_BibleVerse @BibleId, 119003007, N'Rise up, Lord! Deliver me, my God! Yes, you will strike all my enemies on the jaw; you will break the teeth of the wicked.'
EXEC add_BibleVerse @BibleId, 119003008, N'The Lord delivers; you show favor to your people. (Selah)'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119004001, @markup=N'When I call out, answer me, O God who vindicates me! Though I am hemmed in, you will lead me into a wide, open place. Have mercy on me and respond to my prayer! ', @premarkup=N'For the music director, to be accompanied by stringed instruments; a psalm of David.'
EXEC add_BibleVerse @BibleId, 119004002, N'You men, how long will you try to turn my honor into shame? How long will you love what is worthless and search for what is deceptive? (Selah)'
EXEC add_BibleVerse @BibleId, 119004003, N'Realize that the Lord shows the godly special favor; the Lord responds when I cry out to him.'
EXEC add_BibleVerse @BibleId, 119004004, N'Tremble with fear and do not sin! Meditate as you lie in bed, and repent of your ways! (Selah)'
EXEC add_BibleVerse @BibleId, 119004005, N'Offer the prescribed sacrifices and trust in the Lord!'
EXEC add_BibleVerse @BibleId, 119004006, N'Many say, “Who can show us anything good?” Smile upon us, Lord!'
EXEC add_BibleVerse @BibleId, 119004007, N'You make me happier than those who have abundant grain and wine.'
EXEC add_BibleVerse @BibleId, 119004008, N'I will lie down and sleep peacefully, for you, Lord, make me safe and secure.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119005001, @markup=N'Listen to what I say, Lord! Carefully consider my complaint! ', @premarkup=N'For the music director, to be accompanied by wind instruments; a psalm of David.'
EXEC add_BibleVerse @BibleId, 119005002, N'Pay attention to my cry for help, my king and my God, for I am praying to you!'
EXEC add_BibleVerse @BibleId, 119005003, N'Lord, in the morning you will hear me; in the morning I will present my case to you and then wait expectantly for an answer.'
EXEC add_BibleVerse @BibleId, 119005004, N'Certainly you are not a God who approves of evil; evil people cannot dwell with you.'
EXEC add_BibleVerse @BibleId, 119005005, N'Arrogant people cannot stand in your presence; you hate all who behave wickedly.'
EXEC add_BibleVerse @BibleId, 119005006, N'You destroy liars; the Lord despises violent and deceitful people.'
EXEC add_BibleVerse @BibleId, 119005007, N'But as for me, because of your great faithfulness I will enter your house; I will bow down toward your holy temple as I worship you.'
EXEC add_BibleVerse @BibleId, 119005008, N'Lord, lead me in your righteousness because of those who wait to ambush me, remove the obstacles in the way in which you are guiding me!'
EXEC add_BibleVerse @BibleId, 119005009, N'For they do not speak the truth; their stomachs are like the place of destruction, their throats like an open grave, their tongues like a steep slope leading into it.'
EXEC add_BibleVerse @BibleId, 119005010, N'Condemn them, O God! May their own schemes be their downfall! Drive them away because of their many acts of insurrection, for they have rebelled against you.'
EXEC add_BibleVerse @BibleId, 119005011, N'But may all who take shelter in you be happy! May they continually shout for joy! Shelter them so that those who are loyal to you may rejoice!'
EXEC add_BibleVerse @BibleId, 119005012, N'Certainly you reward the godly, Lord. Like a shield you protect them in your good favor.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119006001, @markup=N'Lord, do not rebuke me in your anger! Do not discipline me in your raging fury! ', @premarkup=N'For the music director, to be accompanied by stringed instruments, according to the sheminith style; a psalm of David.'
EXEC add_BibleVerse @BibleId, 119006002, N'Have mercy on me, Lord, for I am frail! Heal me, Lord, for my bones are shaking!'
EXEC add_BibleVerse @BibleId, 119006003, N'I am absolutely terrified, and you, Lord – how long will this continue?'
EXEC add_BibleVerse @BibleId, 119006004, N'Relent, Lord, rescue me! Deliver me because of your faithfulness!'
EXEC add_BibleVerse @BibleId, 119006005, N'For no one remembers you in the realm of death, In Sheol who gives you thanks?'
EXEC add_BibleVerse @BibleId, 119006006, N'I am exhausted as I groan; all night long I drench my bed in tears; my tears saturate the cushion beneath me.'
EXEC add_BibleVerse @BibleId, 119006007, N'My eyes grow dim from suffering; they grow weak because of all my enemies.'
EXEC add_BibleVerse @BibleId, 119006008, N'Turn back from me, all you who behave wickedly, for the Lord has heard the sound of my weeping!'
EXEC add_BibleVerse @BibleId, 119006009, N'The Lord has heard my appeal for mercy; the Lord has accepted my prayer.'
EXEC add_BibleVerse @BibleId, 119006010, N'May all my enemies be humiliated and absolutely terrified! May they turn back and be suddenly humiliated!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119007001, @markup=N'O Lord my God, in you I have taken shelter. Deliver me from all who chase me! Rescue me! ', @premarkup=N'A musical composition by David, which he sang to the Lord concerning a Benjaminite named Cush.'
EXEC add_BibleVerse @BibleId, 119007002, N'Otherwise they will rip me to shreds like a lion; they will tear me to bits and no one will be able to rescue me.'
EXEC add_BibleVerse @BibleId, 119007003, N'O Lord my God, if I have done what they say, or am guilty of unjust actions,'
EXEC add_BibleVerse @BibleId, 119007004, N'or have wronged my ally, or helped his lawless enemy,'
EXEC add_BibleVerse @BibleId, 119007005, N'may an enemy relentlessly chase me and catch me; may he trample me to death and leave me lying dishonored in the dust. (Selah)'
EXEC add_BibleVerse @BibleId, 119007006, N'Stand up angrily, Lord! Rise up with raging fury against my enemies! Wake up for my sake and execute the judgment you have decreed for them!'
EXEC add_BibleVerse @BibleId, 119007007, N'The countries are assembled all around you; take once more your rightful place over them!'
EXEC add_BibleVerse @BibleId, 119007008, N'The Lord judges the nations. Vindicate me, Lord, because I am innocent, because I am blameless, O Exalted One!'
EXEC add_BibleVerse @BibleId, 119007009, N'May the evil deeds of the wicked come to an end! But make the innocent secure, O righteous God, you who examine inner thoughts and motives!'
EXEC add_BibleVerse @BibleId, 119007010, N'The Exalted God is my shield, the one who delivers the morally upright.'
EXEC add_BibleVerse @BibleId, 119007011, N'God is a just judge; he is angry throughout the day.'
EXEC add_BibleVerse @BibleId, 119007012, N'If a person does not repent, God sharpens his sword and prepares to shoot his bow.'
EXEC add_BibleVerse @BibleId, 119007013, N'He prepares to use deadly weapons against him; he gets ready to shoot flaming arrows.'
EXEC add_BibleVerse @BibleId, 119007014, N'See the one who is pregnant with wickedness, who conceives destructive plans, and gives birth to harmful lies –'
EXEC add_BibleVerse @BibleId, 119007015, N'he digs a pit and then falls into the hole he has made.'
EXEC add_BibleVerse @BibleId, 119007016, N'He becomes the victim of his own destructive plans and the violence he intended for others falls on his own head.'
EXEC add_BibleVerse @BibleId, 119007017, N'I will thank the Lord for his justice; I will sing praises to the sovereign Lord!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119008001, @markup=N'O Lord, our Lord, how magnificent is your reputation throughout the earth! You reveal your majesty in the heavens above! ', @premarkup=N'For the music director, according to the gittith style; a psalm of David.'
EXEC add_BibleVerse @BibleId, 119008002, N'From the mouths of children and nursing babies you have ordained praise on account of your adversaries, so that you might put an end to the vindictive enemy.'
EXEC add_BibleVerse @BibleId, 119008003, N'When I look up at the heavens, which your fingers made, and see the moon and the stars, which you set in place,'
EXEC add_BibleVerse @BibleId, 119008004, N'Of what importance is the human race, that you should notice them? Of what importance is mankind, that you should pay attention to them,'
EXEC add_BibleVerse @BibleId, 119008005, N'and make them a little less than the heavenly beings? You grant mankind honor and majesty;'
EXEC add_BibleVerse @BibleId, 119008006, N'you appoint them to rule over your creation; you have placed everything under their authority,'
EXEC add_BibleVerse @BibleId, 119008007, N'including all the sheep and cattle, as well as the wild animals,'
EXEC add_BibleVerse @BibleId, 119008008, N'the birds in the sky, the fish in the sea and everything that moves through the currents of the seas.'
EXEC add_BibleVerse @BibleId, 119008009, N'O Lord, our Lord, how magnificent is your reputation throughout the earth!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119009001, @markup=N'For the music director; according to the alumoth-labben style; a psalm of David. I will thank the Lord with all my heart! I will tell about all your amazing deeds! ', @premarkup=N'To the chief Musician upon Muthlabben, A Psalm of David.'
EXEC add_BibleVerse @BibleId, 119009002, N'I will be happy and rejoice in you! I will sing praises to you, O sovereign One!'
EXEC add_BibleVerse @BibleId, 119009003, N'When my enemies turn back, they trip and are defeated before you.'
EXEC add_BibleVerse @BibleId, 119009004, N'For you defended my just cause; from your throne you pronounced a just decision.'
EXEC add_BibleVerse @BibleId, 119009005, N'You terrified the nations with your battle cry; you destroyed the wicked; you permanently wiped out all memory of them.'
EXEC add_BibleVerse @BibleId, 119009006, N'The enemy’s cities have been reduced to permanent ruins; you destroyed their cities; all memory of the enemies has perished.'
EXEC add_BibleVerse @BibleId, 119009007, N'But the Lord rules forever; he reigns in a just manner.'
EXEC add_BibleVerse @BibleId, 119009008, N'He judges the world fairly; he makes just legal decisions for the nations.'
EXEC add_BibleVerse @BibleId, 119009009, N'Consequently the Lord provides safety for the oppressed; he provides safety in times of trouble.'
EXEC add_BibleVerse @BibleId, 119009010, N'Your loyal followers trust in you, for you, Lord, do not abandon those who seek your help.'
EXEC add_BibleVerse @BibleId, 119009011, N'Sing praises to the Lord, who rules in Zion! Tell the nations what he has done!'
EXEC add_BibleVerse @BibleId, 119009012, N'For the one who takes revenge against murderers took notice of the oppressed; he did not overlook their cry for help'
EXEC add_BibleVerse @BibleId, 119009013, N'when they prayed: “Have mercy on me, Lord! See how I am oppressed by those who hate me, O one who can snatch me away from the gates of death!'
EXEC add_BibleVerse @BibleId, 119009014, N'Then I will tell about all your praiseworthy acts; in the gates of Daughter Zion I will rejoice because of your deliverance.”'
EXEC add_BibleVerse @BibleId, 119009015, N'The nations fell into the pit they had made; their feet were caught in the net they had hidden.'
EXEC add_BibleVerse @BibleId, 119009016, N'The Lord revealed himself; he accomplished justice; the wicked were ensnared by their own actions. (Higgaion. Selah)'
EXEC add_BibleVerse @BibleId, 119009017, N'The wicked are turned back and sent to Sheol; this is the destiny of all the nations that ignore God,'
EXEC add_BibleVerse @BibleId, 119009018, N'for the needy are not permanently ignored, the hopes of the oppressed are not forever dashed.'
EXEC add_BibleVerse @BibleId, 119009019, N'Rise up, Lord! Don’t let men be defiant! May the nations be judged in your presence!'
EXEC add_BibleVerse @BibleId, 119009020, N'Terrify them, Lord! Let the nations know they are mere mortals! (Selah)'
EXEC add_BibleVerse @BibleId, 119010001, N'Why, Lord, do you stand far off? Why do you pay no attention during times of trouble?'
EXEC add_BibleVerse @BibleId, 119010002, N'The wicked arrogantly chase the oppressed; the oppressed are trapped by the schemes the wicked have dreamed up.'
EXEC add_BibleVerse @BibleId, 119010003, N'Yes, the wicked man boasts because he gets what he wants; the one who robs others curses and rejects the Lord.'
EXEC add_BibleVerse @BibleId, 119010004, N'The wicked man is so arrogant he always thinks, “God won’t hold me accountable; he doesn’t care.”'
EXEC add_BibleVerse @BibleId, 119010005, N'He is secure at all times. He has no regard for your commands; he disdains all his enemies.'
EXEC add_BibleVerse @BibleId, 119010006, N'He says to himself, “I will never be upended, because I experience no calamity.”'
EXEC add_BibleVerse @BibleId, 119010007, N'His mouth is full of curses and deceptive, harmful words; his tongue injures and destroys.'
EXEC add_BibleVerse @BibleId, 119010008, N'He waits in ambush near the villages; in hidden places he kills the innocent. His eyes look for some unfortunate victim.'
EXEC add_BibleVerse @BibleId, 119010009, N'He lies in ambush in a hidden place, like a lion in a thicket; he lies in ambush, waiting to catch the oppressed; he catches the oppressed by pulling in his net.'
EXEC add_BibleVerse @BibleId, 119010010, N'His victims are crushed and beaten down; they are trapped in his sturdy nets.'
EXEC add_BibleVerse @BibleId, 119010011, N'He says to himself, “God overlooks it; he does not pay attention; he never notices.”'
EXEC add_BibleVerse @BibleId, 119010012, N'Rise up, Lord! O God, strike him down! Do not forget the oppressed!'
EXEC add_BibleVerse @BibleId, 119010013, N'Why does the wicked man reject God? He says to himself, “You will not hold me accountable.”'
EXEC add_BibleVerse @BibleId, 119010014, N'You have taken notice, for you always see one who inflicts pain and suffering. The unfortunate victim entrusts his cause to you; you deliver the fatherless.'
EXEC add_BibleVerse @BibleId, 119010015, N'Break the arm of the wicked and evil man! Hold him accountable for his wicked deeds, which he thought you would not discover.'
EXEC add_BibleVerse @BibleId, 119010016, N'The Lord rules forever! The nations are driven out of his land.'
EXEC add_BibleVerse @BibleId, 119010017, N'Lord, you have heard the request of the oppressed; you make them feel secure because you listen to their prayer.'
EXEC add_BibleVerse @BibleId, 119010018, N'You defend the fatherless and oppressed, so that mere mortals may no longer terrorize them.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119011001, @markup=N'In the Lord I have taken shelter. How can you say to me, “Flee to a mountain like a bird! ', @premarkup=N'For the music director; by David.'
EXEC add_BibleVerse @BibleId, 119011002, N'For look, the wicked prepare their bows, they put their arrows on the strings, to shoot in the darkness at the morally upright.'
EXEC add_BibleVerse @BibleId, 119011003, N'When the foundations are destroyed, what can the godly accomplish?”'
EXEC add_BibleVerse @BibleId, 119011004, N'The Lord is in his holy temple; the Lord’s throne is in heaven. His eyes watch; his eyes examine all people.'
EXEC add_BibleVerse @BibleId, 119011005, N'The Lord approves of the godly, but he hates the wicked and those who love to do violence.'
EXEC add_BibleVerse @BibleId, 119011006, N'May the Lord rain down burning coals and brimstone on the wicked! A whirlwind is what they deserve!'
EXEC add_BibleVerse @BibleId, 119011007, N'Certainly the Lord is just; he rewards godly deeds; the upright will experience his favor.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119012001, @markup=N'Deliver, Lord! For the godly have disappeared; people of integrity have vanished. ', @premarkup=N'For the music director; according to the sheminith style; a psalm of David.'
EXEC add_BibleVerse @BibleId, 119012002, N'People lie to one another; they flatter and deceive.'
EXEC add_BibleVerse @BibleId, 119012003, N'May the Lord cut off all flattering lips, and the tongue that boasts!'
EXEC add_BibleVerse @BibleId, 119012004, N'They say, “We speak persuasively; we know how to flatter and boast. Who is our master?”'
EXEC add_BibleVerse @BibleId, 119012005, N'“Because of the violence done to the oppressed, because of the painful cries of the needy, I will spring into action,” says the Lord. “I will provide the safety they so desperately desire.”'
EXEC add_BibleVerse @BibleId, 119012006, N'The Lord’s words are absolutely reliable. They are as untainted as silver purified in a furnace on the ground, where it is thoroughly refined.'
EXEC add_BibleVerse @BibleId, 119012007, N'You, Lord, will protect them; you will continually shelter each one from these evil people,'
EXEC add_BibleVerse @BibleId, 119012008, N'for the wicked seem to be everywhere, when people promote evil.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119013001, @markup=N'How long, Lord, will you continue to ignore me? How long will you pay no attention to me? ', @premarkup=N'For the music director; a psalm of David.'
EXEC add_BibleVerse @BibleId, 119013002, N'How long must I worry, and suffer in broad daylight? How long will my enemy gloat over me?'
EXEC add_BibleVerse @BibleId, 119013003, N'Look at me! Answer me, O Lord my God! Revive me, or else I will die!'
EXEC add_BibleVerse @BibleId, 119013004, N'Then my enemy will say, “I have defeated him!” Then my foes will rejoice because I am upended.'
EXEC add_BibleVerse @BibleId, 119013005, N'But I trust in your faithfulness. May I rejoice because of your deliverance!'
EXEC add_BibleVerse @BibleId, 119013006, N'I will sing praises to the Lord when he vindicates me.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119014001, @markup=N'Fools say to themselves, “There is no God.” They sin and commit evil deeds; none of them does what is right. ', @premarkup=N'For the music director; by David.'
EXEC add_BibleVerse @BibleId, 119014002, N'The Lord looks down from heaven at the human race, to see if there is anyone who is wise and seeks God.'
EXEC add_BibleVerse @BibleId, 119014003, N'Everyone rejects God; they are all morally corrupt. None of them does what is right, not even one!'
EXEC add_BibleVerse @BibleId, 119014004, N'All those who behave wickedly do not understand – those who devour my people as if they were eating bread, and do not call out to the Lord.'
EXEC add_BibleVerse @BibleId, 119014005, N'They are absolutely terrified, for God defends the godly.'
EXEC add_BibleVerse @BibleId, 119014006, N'You want to humiliate the oppressed, even though the Lord is their shelter.'
EXEC add_BibleVerse @BibleId, 119014007, N'I wish the deliverance of Israel would come from Zion! When the Lord restores the well-being of his people, may Jacob rejoice, may Israel be happy!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119015001, @markup=N'Lord, who may be a guest in your home? Who may live on your holy hill? ', @premarkup=N'A Psalm of David.'
EXEC add_BibleVerse @BibleId, 119015002, N'Whoever lives a blameless life, does what is right, and speaks honestly.'
EXEC add_BibleVerse @BibleId, 119015003, N'He does not slander, or do harm to others, or insult his neighbor.'
EXEC add_BibleVerse @BibleId, 119015004, N'He despises a reprobate, but honors the Lord’s loyal followers. He makes firm commitments and does not renege on his promise.'
EXEC add_BibleVerse @BibleId, 119015005, N'He does not charge interest when he lends his money. He does not take bribes to testify against the innocent. The one who lives like this will never be upended.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119016001, @markup=N'A prayer of David. Protect me, O God, for I have taken shelter in you. ', @premarkup=N'Michtam of David.'
EXEC add_BibleVerse @BibleId, 119016002, N'I say to the Lord, “You are the Lord, my only source of well-being.”'
EXEC add_BibleVerse @BibleId, 119016003, N'As for God’s chosen people who are in the land, and the leading officials I admired so much –'
EXEC add_BibleVerse @BibleId, 119016004, N'their troubles multiply, they desire other gods. I will not pour out drink offerings of blood to their gods, nor will I make vows in the name of their gods.'
EXEC add_BibleVerse @BibleId, 119016005, N'Lord, you give me stability and prosperity; you make my future secure.'
EXEC add_BibleVerse @BibleId, 119016006, N'It is as if I have been given fertile fields or received a beautiful tract of land.'
EXEC add_BibleVerse @BibleId, 119016007, N'I will praise the Lord who guides me; yes, during the night I reflect and learn.'
EXEC add_BibleVerse @BibleId, 119016008, N'I constantly trust in the Lord; because he is at my right hand, I will not be upended.'
EXEC add_BibleVerse @BibleId, 119016009, N'So my heart rejoices and I am happy; My life is safe.'
EXEC add_BibleVerse @BibleId, 119016010, N'You will not abandon me to Sheol; you will not allow your faithful follower to see the Pit.'
EXEC add_BibleVerse @BibleId, 119016011, N'You lead me in the path of life; I experience absolute joy in your presence; you always give me sheer delight.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119017001, @markup=N'Lord, consider my just cause! Pay attention to my cry for help! Listen to the prayer I sincerely offer! ', @premarkup=N'A Prayer of David.'
EXEC add_BibleVerse @BibleId, 119017002, N'Make a just decision on my behalf! Decide what is right!'
EXEC add_BibleVerse @BibleId, 119017003, N'You have scrutinized my inner motives; you have examined me during the night. You have carefully evaluated me, but you find no sin. I am determined I will say nothing sinful.'
EXEC add_BibleVerse @BibleId, 119017004, N'As for the actions of people – just as you have commanded, I have not followed in the footsteps of violent men.'
EXEC add_BibleVerse @BibleId, 119017005, N'I carefully obey your commands; I do not deviate from them.'
EXEC add_BibleVerse @BibleId, 119017006, N'I call to you for you will answer me, O God. Listen to me! Hear what I say!'
EXEC add_BibleVerse @BibleId, 119017007, N'Accomplish awesome, faithful deeds, you who powerfully deliver those who look to you for protection from their enemies.'
EXEC add_BibleVerse @BibleId, 119017008, N'Protect me as you would protect the pupil of your eye! Hide me in the shadow of your wings!'
EXEC add_BibleVerse @BibleId, 119017009, N'Protect me from the wicked men who attack me, my enemies who crowd around me for the kill.'
EXEC add_BibleVerse @BibleId, 119017010, N'They are calloused; they speak arrogantly.'
EXEC add_BibleVerse @BibleId, 119017011, N'They attack me, now they surround me; they intend to throw me to the ground.'
EXEC add_BibleVerse @BibleId, 119017012, N'He is like a lion that wants to tear its prey to bits, like a young lion crouching in hidden places.'
EXEC add_BibleVerse @BibleId, 119017013, N'Rise up, Lord! Confront him! Knock him down! Use your sword to rescue me from the wicked man!'
EXEC add_BibleVerse @BibleId, 119017014, N'Lord, use your power to deliver me from these murderers, from the murderers of this world! They enjoy prosperity; you overwhelm them with the riches they desire. They have many children, and leave their wealth to their offspring.'
EXEC add_BibleVerse @BibleId, 119017015, N'As for me, because I am innocent I will see your face; when I awake you will reveal yourself to me.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119018001, @markup=N'For the music director; by the Lord’s servant David, who sang to the Lord the words of this song when the Lord rescued him from the power of all his enemies, including Saul. He said: “I love you, Lord, my source of strength! ', @premarkup=N'To the chief Musician, A Psalm of David, the servant of the LORD, who spake unto the LORD the words of this song in the day that the LORD delivered him from the hand of all his enemies, and from the hand of Saul: And he said,'
EXEC add_BibleVerse @BibleId, 119018002, N'The Lord is my high ridge, my stronghold, my deliverer. My God is my rocky summit where I take shelter, my shield, the horn that saves me, and my refuge.'
EXEC add_BibleVerse @BibleId, 119018003, N'I called to the Lord, who is worthy of praise, and I was delivered from my enemies.'
EXEC add_BibleVerse @BibleId, 119018004, N'The waves of death engulfed me, the currents of chaos overwhelmed me.'
EXEC add_BibleVerse @BibleId, 119018005, N'The ropes of Sheol tightened around me, the snares of death trapped me.'
EXEC add_BibleVerse @BibleId, 119018006, N'In my distress I called to the Lord; I cried out to my God. From his heavenly temple he heard my voice; he listened to my cry for help.'
EXEC add_BibleVerse @BibleId, 119018007, N'The earth heaved and shook; the roots of the mountains trembled; they heaved because he was angry.'
EXEC add_BibleVerse @BibleId, 119018008, N'Smoke ascended from his nose; fire devoured as it came from his mouth; he hurled down fiery coals.'
EXEC add_BibleVerse @BibleId, 119018009, N'He made the sky sink as he descended; a thick cloud was under his feet.'
EXEC add_BibleVerse @BibleId, 119018010, N'He mounted a winged angel and flew; he glided on the wings of the wind.'
EXEC add_BibleVerse @BibleId, 119018011, N'He shrouded himself in darkness, in thick rain clouds.'
EXEC add_BibleVerse @BibleId, 119018012, N'From the brightness in front of him came hail and fiery coals.'
EXEC add_BibleVerse @BibleId, 119018013, N'The Lord thundered in the sky; the sovereign One shouted.'
EXEC add_BibleVerse @BibleId, 119018014, N'He shot his arrows and scattered them, many lightning bolts and routed them.'
EXEC add_BibleVerse @BibleId, 119018015, N'The depths of the sea were exposed; the inner regions of the world were uncovered by your battle cry, Lord, by the powerful breath from your nose.'
EXEC add_BibleVerse @BibleId, 119018016, N'He reached down from above and took hold of me; he pulled me from the surging water.'
EXEC add_BibleVerse @BibleId, 119018017, N'He rescued me from my strong enemy, from those who hate me, for they were too strong for me.'
EXEC add_BibleVerse @BibleId, 119018018, N'They confronted me in my day of calamity, but the Lord helped me.'
EXEC add_BibleVerse @BibleId, 119018019, N'He brought me out into a wide open place; he delivered me because he was pleased with me.'
EXEC add_BibleVerse @BibleId, 119018020, N'The Lord repaid me for my godly deeds; he rewarded my blameless behavior.'
EXEC add_BibleVerse @BibleId, 119018021, N'For I have obeyed the Lord’s commands; I have not rebelled against my God.'
EXEC add_BibleVerse @BibleId, 119018022, N'For I am aware of all his regulations, and I do not reject his rules.'
EXEC add_BibleVerse @BibleId, 119018023, N'I was innocent before him, and kept myself from sinning.'
EXEC add_BibleVerse @BibleId, 119018024, N'The Lord rewarded me for my godly deeds; he took notice of my blameless behavior.'
EXEC add_BibleVerse @BibleId, 119018025, N'You prove to be loyal to one who is faithful; you prove to be trustworthy to one who is innocent.'
EXEC add_BibleVerse @BibleId, 119018026, N'You prove to be reliable to one who is blameless, but you prove to be deceptive to one who is perverse.'
EXEC add_BibleVerse @BibleId, 119018027, N'For you deliver oppressed people, but you bring down those who have a proud look.'
EXEC add_BibleVerse @BibleId, 119018028, N'Indeed, you are my lamp, Lord. My God illuminates the darkness around me.'
EXEC add_BibleVerse @BibleId, 119018029, N'Indeed, with your help I can charge against an army; by my God’s power I can jump over a wall.'
EXEC add_BibleVerse @BibleId, 119018030, N'The one true God acts in a faithful manner; the Lord’s promise is reliable; he is a shield to all who take shelter in him.'
EXEC add_BibleVerse @BibleId, 119018031, N'Indeed, who is God besides the Lord? Who is a protector besides our God?'
EXEC add_BibleVerse @BibleId, 119018032, N'The one true God gives me strength; he removes the obstacles in my way.'
EXEC add_BibleVerse @BibleId, 119018033, N'He gives me the agility of a deer; he enables me to negotiate the rugged terrain.'
EXEC add_BibleVerse @BibleId, 119018034, N'He trains my hands for battle; my arms can bend even the strongest bow.'
EXEC add_BibleVerse @BibleId, 119018035, N'You give me your protective shield; your right hand supports me; your willingness to help enables me to prevail.'
EXEC add_BibleVerse @BibleId, 119018036, N'You widen my path; my feet do not slip.'
EXEC add_BibleVerse @BibleId, 119018037, N'I chase my enemies and catch them; I do not turn back until I wipe them out.'
EXEC add_BibleVerse @BibleId, 119018038, N'I beat them to death; they fall at my feet.'
EXEC add_BibleVerse @BibleId, 119018039, N'You give me strength for battle; you make my foes kneel before me.'
EXEC add_BibleVerse @BibleId, 119018040, N'You make my enemies retreat; I destroy those who hate me.'
EXEC add_BibleVerse @BibleId, 119018041, N'They cry out, but there is no one to help them; they cry out to the Lord, but he does not answer them.'
EXEC add_BibleVerse @BibleId, 119018042, N'I grind them as fine windblown dust; I beat them underfoot like clay in the streets.'
EXEC add_BibleVerse @BibleId, 119018043, N'You rescue me from a hostile army; you make me a leader of nations; people over whom I had no authority are now my subjects.'
EXEC add_BibleVerse @BibleId, 119018044, N'When they hear of my exploits, they submit to me. Foreigners are powerless before me;'
EXEC add_BibleVerse @BibleId, 119018045, N'foreigners lose their courage; they shake with fear as they leave their strongholds.'
EXEC add_BibleVerse @BibleId, 119018046, N'The Lord is alive! My protector is praiseworthy! The God who delivers me is exalted as king!'
EXEC add_BibleVerse @BibleId, 119018047, N'The one true God completely vindicates me; he makes nations submit to me.'
EXEC add_BibleVerse @BibleId, 119018048, N'He delivers me from my enemies; you snatch me away from those who attack me; you rescue me from violent men.'
EXEC add_BibleVerse @BibleId, 119018049, N'So I will give you thanks before the nations, O Lord! I will sing praises to you!'
EXEC add_BibleVerse @BibleId, 119018050, N'He gives his chosen king magnificent victories; he is faithful to his chosen ruler, to David and his descendants forever.”'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119019001, @markup=N'The heavens declare the glory of God; the sky displays his handiwork. ', @premarkup=N'For the music director; a psalm of David.'
EXEC add_BibleVerse @BibleId, 119019002, N'Day after day it speaks out; night after night it reveals his greatness.'
EXEC add_BibleVerse @BibleId, 119019003, N'There is no actual speech or word, nor is its voice literally heard.'
EXEC add_BibleVerse @BibleId, 119019004, N'Yet its voice echoes throughout the earth; its words carry to the distant horizon. In the sky he has pitched a tent for the sun.'
EXEC add_BibleVerse @BibleId, 119019005, N'Like a bridegroom it emerges from its chamber; like a strong man it enjoys running its course.'
EXEC add_BibleVerse @BibleId, 119019006, N'It emerges from the distant horizon, and goes from one end of the sky to the other; nothing can escape its heat.'
EXEC add_BibleVerse @BibleId, 119019007, N'The law of the Lord is perfect and preserves one’s life. The rules set down by the Lord are reliable and impart wisdom to the inexperienced.'
EXEC add_BibleVerse @BibleId, 119019008, N'The Lord’s precepts are fair and make one joyful. The Lord’s commands are pure and give insight for life.'
EXEC add_BibleVerse @BibleId, 119019009, N'The commands to fear the Lord are right and endure forever. The judgments given by the Lord are trustworthy and absolutely just.'
EXEC add_BibleVerse @BibleId, 119019010, N'They are of greater value than gold, than even a great amount of pure gold; they bring greater delight than honey, than even the sweetest honey from a honeycomb.'
EXEC add_BibleVerse @BibleId, 119019011, N'Yes, your servant finds moral guidance there; those who obey them receive a rich reward.'
EXEC add_BibleVerse @BibleId, 119019012, N'Who can know all his errors? Please do not punish me for sins I am unaware of.'
EXEC add_BibleVerse @BibleId, 119019013, N'Moreover, keep me from committing flagrant sins; do not allow such sins to control me. Then I will be blameless, and innocent of blatant rebellion.'
EXEC add_BibleVerse @BibleId, 119019014, N'May my words and my thoughts be acceptable in your sight, O Lord, my sheltering rock and my redeemer.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119020001, @markup=N'May the Lord answer you when you are in trouble; may the God of Jacob make you secure! ', @premarkup=N'For the music director; a psalm of David.'
EXEC add_BibleVerse @BibleId, 119020002, N'May he send you help from his temple; from Zion may he give you support!'
EXEC add_BibleVerse @BibleId, 119020003, N'May he take notice of your offerings; may he accept your burnt sacrifice! (Selah)'
EXEC add_BibleVerse @BibleId, 119020004, N'May he grant your heart’s desire; may he bring all your plans to pass!'
EXEC add_BibleVerse @BibleId, 119020005, N'Then we will shout for joy over your victory; we will rejoice in the name of our God! May the Lord grant all your requests!'
EXEC add_BibleVerse @BibleId, 119020006, N'Now I am sure that the Lord will deliver his chosen king; he will intervene for him from his holy heavenly temple, and display his mighty ability to deliver.'
EXEC add_BibleVerse @BibleId, 119020007, N'Some trust in chariots and others in horses, but we depend on the Lord our God.'
EXEC add_BibleVerse @BibleId, 119020008, N'They will fall down, but we will stand firm.'
EXEC add_BibleVerse @BibleId, 119020009, N'The Lord will deliver the king; he will answer us when we call to him for help!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119021001, @markup=N'O Lord, the king rejoices in the strength you give; he takes great delight in the deliverance you provide. ', @premarkup=N'For the music director; a psalm of David.'
EXEC add_BibleVerse @BibleId, 119021002, N'You grant him his heart’s desire; you do not refuse his request. (Selah)'
EXEC add_BibleVerse @BibleId, 119021003, N'For you bring him rich blessings; you place a golden crown on his head.'
EXEC add_BibleVerse @BibleId, 119021004, N'He asked you to sustain his life, and you have granted him long life and an enduring dynasty.'
EXEC add_BibleVerse @BibleId, 119021005, N'Your deliverance brings him great honor; you give him majestic splendor.'
EXEC add_BibleVerse @BibleId, 119021006, N'For you grant him lasting blessings; you give him great joy by allowing him into your presence.'
EXEC add_BibleVerse @BibleId, 119021007, N'For the king trusts in the Lord, and because of the sovereign Lord’s faithfulness he is not upended.'
EXEC add_BibleVerse @BibleId, 119021008, N'You prevail over all your enemies; your power is too great for those who hate you.'
EXEC add_BibleVerse @BibleId, 119021009, N'You burn them up like a fiery furnace when you appear; the Lord angrily devours them; the fire consumes them.'
EXEC add_BibleVerse @BibleId, 119021010, N'You destroy their offspring from the earth, their descendants from among the human race.'
EXEC add_BibleVerse @BibleId, 119021011, N'Yes, they intend to do you harm; they dream up a scheme, but they do not succeed.'
EXEC add_BibleVerse @BibleId, 119021012, N'For you make them retreat when you shoot your arrows at them.'
EXEC add_BibleVerse @BibleId, 119021013, N'Rise up, O Lord, in strength! We will sing and praise your power!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119022001, @markup=N'My God, my God, why have you abandoned me? I groan in prayer, but help seems far away. ', @premarkup=N'For the music director; according to the tune “Morning Doe;” a psalm of David.'
EXEC add_BibleVerse @BibleId, 119022002, N'My God, I cry out during the day, but you do not answer, and during the night my prayers do not let up.'
EXEC add_BibleVerse @BibleId, 119022003, N'You are holy; you sit as king receiving the praises of Israel.'
EXEC add_BibleVerse @BibleId, 119022004, N'In you our ancestors trusted; they trusted in you and you rescued them.'
EXEC add_BibleVerse @BibleId, 119022005, N'To you they cried out, and they were saved; in you they trusted and they were not disappointed.'
EXEC add_BibleVerse @BibleId, 119022006, N'But I am a worm, not a man; people insult me and despise me.'
EXEC add_BibleVerse @BibleId, 119022007, N'All who see me taunt me; they mock me and shake their heads.'
EXEC add_BibleVerse @BibleId, 119022008, N'They say, “Commit yourself to the Lord! Let the Lord rescue him! Let the Lord deliver him, for he delights in him.”'
EXEC add_BibleVerse @BibleId, 119022009, N'Yes, you are the one who brought me out from the womb and made me feel secure on my mother’s breasts.'
EXEC add_BibleVerse @BibleId, 119022010, N'I have been dependent on you since birth; from the time I came out of my mother’s womb you have been my God.'
EXEC add_BibleVerse @BibleId, 119022011, N'Do not remain far away from me, for trouble is near and I have no one to help me.'
EXEC add_BibleVerse @BibleId, 119022012, N'Many bulls surround me; powerful bulls of Bashan hem me in.'
EXEC add_BibleVerse @BibleId, 119022013, N'They open their mouths to devour me like a roaring lion that rips its prey.'
EXEC add_BibleVerse @BibleId, 119022014, N'My strength drains away like water; all my bones are dislocated; my heart is like wax; it melts away inside me.'
EXEC add_BibleVerse @BibleId, 119022015, N'The roof of my mouth is as dry as a piece of pottery; my tongue sticks to my gums. You set me in the dust of death.'
EXEC add_BibleVerse @BibleId, 119022016, N'Yes, wild dogs surround me – a gang of evil men crowd around me; like a lion they pin my hands and feet.'
EXEC add_BibleVerse @BibleId, 119022017, N'I can count all my bones; my enemies are gloating over me in triumph.'
EXEC add_BibleVerse @BibleId, 119022018, N'They are dividing up my clothes among themselves; they are rolling dice for my garments.'
EXEC add_BibleVerse @BibleId, 119022019, N'But you, O Lord, do not remain far away! You are my source of strength! Hurry and help me!'
EXEC add_BibleVerse @BibleId, 119022020, N'Deliver me from the sword! Save my life from the claws of the wild dogs!'
EXEC add_BibleVerse @BibleId, 119022021, N'Rescue me from the mouth of the lion, and from the horns of the wild oxen! You have answered me!'
EXEC add_BibleVerse @BibleId, 119022022, N'I will declare your name to my countrymen! In the middle of the assembly I will praise you!'
EXEC add_BibleVerse @BibleId, 119022023, N'You loyal followers of the Lord, praise him! All you descendants of Jacob, honor him! All you descendants of Israel, stand in awe of him!'
EXEC add_BibleVerse @BibleId, 119022024, N'For he did not despise or detest the suffering of the oppressed; he did not ignore him; when he cried out to him, he responded.'
EXEC add_BibleVerse @BibleId, 119022025, N'You are the reason I offer praise in the great assembly; I will fulfill my promises before the Lord’s loyal followers.'
EXEC add_BibleVerse @BibleId, 119022026, N'Let the oppressed eat and be filled! Let those who seek his help praise the Lord! May you live forever!'
EXEC add_BibleVerse @BibleId, 119022027, N'Let all the people of the earth acknowledge the Lord and turn to him! Let all the nations worship you!'
EXEC add_BibleVerse @BibleId, 119022028, N'For the Lord is king and rules over the nations.'
EXEC add_BibleVerse @BibleId, 119022029, N'All of the thriving people of the earth will join the celebration and worship; all those who are descending into the grave will bow before him, including those who cannot preserve their lives.'
EXEC add_BibleVerse @BibleId, 119022030, N'A whole generation will serve him; they will tell the next generation about the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 119022031, N'They will come and tell about his saving deeds; they will tell a future generation what he has accomplished.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119023001, @markup=N'The Lord is my shepherd, I lack nothing. ', @premarkup=N'A Psalm of David.'
EXEC add_BibleVerse @BibleId, 119023002, N'He takes me to lush pastures, he leads me to refreshing water.'
EXEC add_BibleVerse @BibleId, 119023003, N'He restores my strength. He leads me down the right paths for the sake of his reputation.'
EXEC add_BibleVerse @BibleId, 119023004, N'Even when I must walk through the darkest valley, I fear no danger, for you are with me; your rod and your staff reassure me.'
EXEC add_BibleVerse @BibleId, 119023005, N'You prepare a feast before me in plain sight of my enemies. You refresh my head with oil; my cup is completely full.'
EXEC add_BibleVerse @BibleId, 119023006, N'Surely your goodness and faithfulness will pursue me all my days, and I will live in the Lord’s house for the rest of my life.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119024001, @markup=N'The Lord owns the earth and all it contains, the world and all who live in it. ', @premarkup=N'A Psalm of David.'
EXEC add_BibleVerse @BibleId, 119024002, N'For he set its foundation upon the seas, and established it upon the ocean currents.'
EXEC add_BibleVerse @BibleId, 119024003, N'Who is allowed to ascend the mountain of the Lord? Who may go up to his holy dwelling place?'
EXEC add_BibleVerse @BibleId, 119024004, N'The one whose deeds are blameless and whose motives are pure, who does not lie, or make promises with no intention of keeping them.'
EXEC add_BibleVerse @BibleId, 119024005, N'Such godly people are rewarded by the Lord, and vindicated by the God who delivers them.'
EXEC add_BibleVerse @BibleId, 119024006, N'Such purity characterizes the people who seek his favor, Jacob’s descendants, who pray to him. (Selah)'
EXEC add_BibleVerse @BibleId, 119024007, N'Look up, you gates! Rise up, you eternal doors! Then the majestic king will enter!'
EXEC add_BibleVerse @BibleId, 119024008, N'Who is this majestic king? The Lord who is strong and mighty! The Lord who is mighty in battle!'
EXEC add_BibleVerse @BibleId, 119024009, N'Look up, you gates! Rise up, you eternal doors! Then the majestic king will enter!'
EXEC add_BibleVerse @BibleId, 119024010, N'Who is this majestic king? The Lord who commands armies! He is the majestic king! (Selah)'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119025001, @markup=N'O Lord, I come before you in prayer. ', @premarkup=N'By David.'
EXEC add_BibleVerse @BibleId, 119025002, N'My God, I trust in you. Please do not let me be humiliated; do not let my enemies triumphantly rejoice over me!'
EXEC add_BibleVerse @BibleId, 119025003, N'Certainly none who rely on you will be humiliated. Those who deal in treachery will be thwarted and humiliated.'
EXEC add_BibleVerse @BibleId, 119025004, N'Make me understand your ways, O Lord! Teach me your paths!'
EXEC add_BibleVerse @BibleId, 119025005, N'Guide me into your truth and teach me. For you are the God who delivers me; on you I rely all day long.'
EXEC add_BibleVerse @BibleId, 119025006, N'Remember your compassionate and faithful deeds, O Lord, for you have always acted in this manner.'
EXEC add_BibleVerse @BibleId, 119025007, N'Do not hold against me the sins of my youth or my rebellious acts! Because you are faithful to me, extend to me your favor, O Lord!'
EXEC add_BibleVerse @BibleId, 119025008, N'The Lord is both kind and fair; that is why he teaches sinners the right way to live.'
EXEC add_BibleVerse @BibleId, 119025009, N'May he show the humble what is right! May he teach the humble his way!'
EXEC add_BibleVerse @BibleId, 119025010, N'The Lord always proves faithful and reliable to those who follow the demands of his covenant.'
EXEC add_BibleVerse @BibleId, 119025011, N'For the sake of your reputation, O Lord, forgive my sin, because it is great.'
EXEC add_BibleVerse @BibleId, 119025012, N'The Lord shows his faithful followers the way they should live.'
EXEC add_BibleVerse @BibleId, 119025013, N'They experience his favor; their descendants inherit the land.'
EXEC add_BibleVerse @BibleId, 119025014, N'The Lord’s loyal followers receive his guidance, and he reveals his covenantal demands to them.'
EXEC add_BibleVerse @BibleId, 119025015, N'I continually look to the Lord for help, for he will free my feet from the enemy’s net.'
EXEC add_BibleVerse @BibleId, 119025016, N'Turn toward me and have mercy on me, for I am alone and oppressed!'
EXEC add_BibleVerse @BibleId, 119025017, N'Deliver me from my distress; rescue me from my suffering!'
EXEC add_BibleVerse @BibleId, 119025018, N'See my pain and suffering! Forgive all my sins!'
EXEC add_BibleVerse @BibleId, 119025019, N'Watch my enemies, for they outnumber me; they hate me and want to harm me.'
EXEC add_BibleVerse @BibleId, 119025020, N'Protect me and deliver me! Please do not let me be humiliated, for I have taken shelter in you!'
EXEC add_BibleVerse @BibleId, 119025021, N'May integrity and godliness protect me, for I rely on you!'
EXEC add_BibleVerse @BibleId, 119025022, N'O God, rescue Israel from all their distress!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119026001, @markup=N'Vindicate me, O Lord, for I have integrity, and I trust in the Lord without wavering. ', @premarkup=N'By David.'
EXEC add_BibleVerse @BibleId, 119026002, N'Examine me, O Lord, and test me! Evaluate my inner thoughts and motives!'
EXEC add_BibleVerse @BibleId, 119026003, N'For I am ever aware of your faithfulness, and your loyalty continually motivates me.'
EXEC add_BibleVerse @BibleId, 119026004, N'I do not associate with deceitful men, or consort with those who are dishonest.'
EXEC add_BibleVerse @BibleId, 119026005, N'I hate the mob of evil men, and do not associate with the wicked.'
EXEC add_BibleVerse @BibleId, 119026006, N'I maintain a pure lifestyle, so I can appear before your altar, O Lord,'
EXEC add_BibleVerse @BibleId, 119026007, N'to give you thanks, and to tell about all your amazing deeds.'
EXEC add_BibleVerse @BibleId, 119026008, N'O Lord, I love the temple where you live, the place where your splendor is revealed.'
EXEC add_BibleVerse @BibleId, 119026009, N'Do not sweep me away with sinners, or execute me along with violent people,'
EXEC add_BibleVerse @BibleId, 119026010, N'who are always ready to do wrong or offer a bribe.'
EXEC add_BibleVerse @BibleId, 119026011, N'But I have integrity! Rescue me and have mercy on me!'
EXEC add_BibleVerse @BibleId, 119026012, N'I am safe, and among the worshipers I will praise the Lord.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119027001, @markup=N'The Lord delivers and vindicates me! I fear no one! The Lord protects my life! I am afraid of no one! ', @premarkup=N'By David.'
EXEC add_BibleVerse @BibleId, 119027002, N'When evil men attack me to devour my flesh, when my adversaries and enemies attack me, they stumble and fall.'
EXEC add_BibleVerse @BibleId, 119027003, N'Even when an army is deployed against me, I do not fear. Even when war is imminent, I remain confident.'
EXEC add_BibleVerse @BibleId, 119027004, N'I have asked the Lord for one thing – this is what I desire! I want to live in the Lord’s house all the days of my life, so I can gaze at the splendor of the Lord and contemplate in his temple.'
EXEC add_BibleVerse @BibleId, 119027005, N'He will surely give me shelter in the day of danger; he will hide me in his home; he will place me on an inaccessible rocky summit.'
EXEC add_BibleVerse @BibleId, 119027006, N'Now I will triumph over my enemies who surround me! I will offer sacrifices in his dwelling place and shout for joy! I will sing praises to the Lord!'
EXEC add_BibleVerse @BibleId, 119027007, N'Hear me, O Lord, when I cry out! Have mercy on me and answer me!'
EXEC add_BibleVerse @BibleId, 119027008, N'My heart tells me to pray to you, and I do pray to you, O Lord.'
EXEC add_BibleVerse @BibleId, 119027009, N'Do not reject me! Do not push your servant away in anger! You are my deliverer! Do not forsake or abandon me, O God who vindicates me!'
EXEC add_BibleVerse @BibleId, 119027010, N'Even if my father and mother abandoned me, the Lord would take me in.'
EXEC add_BibleVerse @BibleId, 119027011, N'Teach me how you want me to live; lead me along a level path because of those who wait to ambush me!'
EXEC add_BibleVerse @BibleId, 119027012, N'Do not turn me over to my enemies, for false witnesses who want to destroy me testify against me.'
EXEC add_BibleVerse @BibleId, 119027013, N'Where would I be if I did not believe I would experience the Lord’s favor in the land of the living?'
EXEC add_BibleVerse @BibleId, 119027014, N'Rely on the Lord! Be strong and confident! Rely on the Lord!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119028001, @markup=N'To you, O Lord, I cry out! My protector, do not ignore me! If you do not respond to me, I will join those who are descending into the grave. ', @premarkup=N'By David.'
EXEC add_BibleVerse @BibleId, 119028002, N'Hear my plea for mercy when I cry out to you for help, when I lift my hands toward your holy temple!'
EXEC add_BibleVerse @BibleId, 119028003, N'Do not drag me away with evil men, with those who behave wickedly, who talk so friendly to their neighbors, while they plan to harm them!'
EXEC add_BibleVerse @BibleId, 119028004, N'Pay them back for their evil deeds! Pay them back for what they do! Punish them!'
EXEC add_BibleVerse @BibleId, 119028005, N'For they do not understand the Lord’s actions, or the way he carries out justice. The Lord will permanently demolish them.'
EXEC add_BibleVerse @BibleId, 119028006, N'The Lord deserves praise, for he has heard my plea for mercy!'
EXEC add_BibleVerse @BibleId, 119028007, N'The Lord strengthens and protects me; I trust in him with all my heart. I am rescued and my heart is full of joy; I will sing to him in gratitude.'
EXEC add_BibleVerse @BibleId, 119028008, N'The Lord strengthens his people; he protects and delivers his chosen king.'
EXEC add_BibleVerse @BibleId, 119028009, N'Deliver your people! Empower the nation that belongs to you! Care for them like a shepherd and carry them in your arms at all times!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119029001, @markup=N'Acknowledge the Lord, you heavenly beings, acknowledge the Lord’s majesty and power! ', @premarkup=N'A Psalm of David.'
EXEC add_BibleVerse @BibleId, 119029002, N'Acknowledge the majesty of the Lord’s reputation! Worship the Lord in holy attire!'
EXEC add_BibleVerse @BibleId, 119029003, N'The Lord’s shout is heard over the water; the majestic God thunders, the Lord appears over the surging water.'
EXEC add_BibleVerse @BibleId, 119029004, N'The Lord’s shout is powerful, the Lord’s shout is majestic.'
EXEC add_BibleVerse @BibleId, 119029005, N'The Lord’s shout breaks the cedars, the Lord shatters the cedars of Lebanon.'
EXEC add_BibleVerse @BibleId, 119029006, N'He makes Lebanon skip like a calf and Sirion like a young ox.'
EXEC add_BibleVerse @BibleId, 119029007, N'The Lord’s shout strikes with flaming fire.'
EXEC add_BibleVerse @BibleId, 119029008, N'The Lord’s shout shakes the wilderness, the Lord shakes the wilderness of Kadesh.'
EXEC add_BibleVerse @BibleId, 119029009, N'The Lord’s shout bends the large trees and strips the leaves from the forests. Everyone in his temple says, “Majestic!”'
EXEC add_BibleVerse @BibleId, 119029010, N'The Lord sits enthroned over the engulfing waters, the Lord sits enthroned as the eternal king.'
EXEC add_BibleVerse @BibleId, 119029011, N'The Lord gives his people strength; the Lord grants his people security.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119030001, @markup=N'I will praise you, O Lord, for you lifted me up, and did not allow my enemies to gloat over me. ', @premarkup=N'A psalm – a song used at the dedication of the temple; by David.'
EXEC add_BibleVerse @BibleId, 119030002, N'O Lord my God, I cried out to you and you healed me.'
EXEC add_BibleVerse @BibleId, 119030003, N'O Lord, you pulled me up from Sheol; you rescued me from among those descending into the grave.'
EXEC add_BibleVerse @BibleId, 119030004, N'Sing to the Lord, you faithful followers of his; give thanks to his holy name.'
EXEC add_BibleVerse @BibleId, 119030005, N'For his anger lasts only a brief moment, and his good favor restores one’s life. One may experience sorrow during the night, but joy arrives in the morning.'
EXEC add_BibleVerse @BibleId, 119030006, N'In my self-confidence I said, “I will never be upended.”'
EXEC add_BibleVerse @BibleId, 119030007, N'O Lord, in your good favor you made me secure. Then you rejected me and I was terrified.'
EXEC add_BibleVerse @BibleId, 119030008, N'To you, O Lord, I cried out; I begged the Lord for mercy:'
EXEC add_BibleVerse @BibleId, 119030009, N'“What profit is there in taking my life, in my descending into the Pit? Can the dust of the grave praise you? Can it declare your loyalty?'
EXEC add_BibleVerse @BibleId, 119030010, N'Hear, O Lord, and have mercy on me! O Lord, deliver me!”'
EXEC add_BibleVerse @BibleId, 119030011, N'Then you turned my lament into dancing; you removed my sackcloth and covered me with joy.'
EXEC add_BibleVerse @BibleId, 119030012, N'So now my heart will sing to you and not be silent; O Lord my God, I will always give thanks to you.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119031001, @markup=N'In you, O Lord, I have taken shelter! Never let me be humiliated! Vindicate me by rescuing me! ', @premarkup=N'For the music director; a psalm of David.'
EXEC add_BibleVerse @BibleId, 119031002, N'Listen to me! Quickly deliver me! Be my protector and refuge, a stronghold where I can be safe!'
EXEC add_BibleVerse @BibleId, 119031003, N'For you are my high ridge and my stronghold; for the sake of your own reputation you lead me and guide me.'
EXEC add_BibleVerse @BibleId, 119031004, N'You will free me from the net they hid for me, for you are my place of refuge.'
EXEC add_BibleVerse @BibleId, 119031005, N'Into your hand I entrust my life; you will rescue me, O Lord, the faithful God.'
EXEC add_BibleVerse @BibleId, 119031006, N'I hate those who serve worthless idols, but I trust in the Lord.'
EXEC add_BibleVerse @BibleId, 119031007, N'I will be happy and rejoice in your faithfulness, because you notice my pain and you are aware of how distressed I am.'
EXEC add_BibleVerse @BibleId, 119031008, N'You do not deliver me over to the power of the enemy; you enable me to stand in a wide open place.'
EXEC add_BibleVerse @BibleId, 119031009, N'Have mercy on me, for I am in distress! My eyes grow dim from suffering. I have lost my strength.'
EXEC add_BibleVerse @BibleId, 119031010, N'For my life nears its end in pain; my years draw to a close as I groan. My strength fails me because of my sin, and my bones become brittle.'
EXEC add_BibleVerse @BibleId, 119031011, N'Because of all my enemies, people disdain me; my neighbors are appalled by my suffering – those who know me are horrified by my condition; those who see me in the street run away from me.'
EXEC add_BibleVerse @BibleId, 119031012, N'I am forgotten, like a dead man no one thinks about; I am regarded as worthless, like a broken jar.'
EXEC add_BibleVerse @BibleId, 119031013, N'For I hear what so many are saying, the terrifying news that comes from every direction. When they plot together against me, they figure out how they can take my life.'
EXEC add_BibleVerse @BibleId, 119031014, N'But I trust in you, O Lord! I declare, “You are my God!”'
EXEC add_BibleVerse @BibleId, 119031015, N'You determine my destiny! Rescue me from the power of my enemies and those who chase me.'
EXEC add_BibleVerse @BibleId, 119031016, N'Smile on your servant! Deliver me because of your faithfulness!'
EXEC add_BibleVerse @BibleId, 119031017, N'O Lord, do not let me be humiliated, for I call out to you! May evil men be humiliated! May they go wailing to the grave!'
EXEC add_BibleVerse @BibleId, 119031018, N'May lying lips be silenced – lips that speak defiantly against the innocent with arrogance and contempt!'
EXEC add_BibleVerse @BibleId, 119031019, N'How great is your favor, which you store up for your loyal followers! In plain sight of everyone you bestow it on those who take shelter in you.'
EXEC add_BibleVerse @BibleId, 119031020, N'You hide them with you, where they are safe from the attacks of men; you conceal them in a shelter, where they are safe from slanderous attacks.'
EXEC add_BibleVerse @BibleId, 119031021, N'The Lord deserves praise for he demonstrated his amazing faithfulness to me when I was besieged by enemies.'
EXEC add_BibleVerse @BibleId, 119031022, N'I jumped to conclusions and said, “I am cut off from your presence!” But you heard my plea for mercy when I cried out to you for help.'
EXEC add_BibleVerse @BibleId, 119031023, N'Love the Lord, all you faithful followers of his! The Lord protects those who have integrity, but he pays back in full the one who acts arrogantly.'
EXEC add_BibleVerse @BibleId, 119031024, N'Be strong and confident, all you who wait on the Lord!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119032001, @markup=N'How blessed is the one whose rebellious acts are forgiven, whose sin is pardoned! ', @premarkup=N'By David; a well-written song.'
EXEC add_BibleVerse @BibleId, 119032002, N'How blessed is the one whose wrongdoing the Lord does not punish, in whose spirit there is no deceit.'
EXEC add_BibleVerse @BibleId, 119032003, N'When I refused to confess my sin, my whole body wasted away, while I groaned in pain all day long.'
EXEC add_BibleVerse @BibleId, 119032004, N'For day and night you tormented me; you tried to destroy me in the intense heat of summer. (Selah)'
EXEC add_BibleVerse @BibleId, 119032005, N'Then I confessed my sin; I no longer covered up my wrongdoing. I said, “I will confess my rebellious acts to the Lord.” And then you forgave my sins. (Selah)'
EXEC add_BibleVerse @BibleId, 119032006, N'For this reason every one of your faithful followers should pray to you while there is a window of opportunity. Certainly when the surging water rises, it will not reach them.'
EXEC add_BibleVerse @BibleId, 119032007, N'You are my hiding place; you protect me from distress. You surround me with shouts of joy from those celebrating deliverance. (Selah)'
EXEC add_BibleVerse @BibleId, 119032008, N'I will instruct and teach you about how you should live. I will advise you as I look you in the eye.'
EXEC add_BibleVerse @BibleId, 119032009, N'Do not be like an unintelligent horse or mule, which will not obey you unless they are controlled by a bridle and bit.'
EXEC add_BibleVerse @BibleId, 119032010, N'An evil person suffers much pain, but the Lord’s faithfulness overwhelms the one who trusts in him.'
EXEC add_BibleVerse @BibleId, 119032011, N'Rejoice in the Lord and be happy, you who are godly! Shout for joy, all you who are morally upright!'
EXEC add_BibleVerse @BibleId, 119033001, N'You godly ones, shout for joy because of the Lord! It is appropriate for the morally upright to offer him praise.'
EXEC add_BibleVerse @BibleId, 119033002, N'Give thanks to the Lord with the harp! Sing to him to the accompaniment of a ten-stringed instrument!'
EXEC add_BibleVerse @BibleId, 119033003, N'Sing to him a new song! Play skillfully as you shout out your praises to him!'
EXEC add_BibleVerse @BibleId, 119033004, N'For the Lord’s decrees are just, and everything he does is fair.'
EXEC add_BibleVerse @BibleId, 119033005, N'The Lord promotes equity and justice; the Lord’s faithfulness extends throughout the earth.'
EXEC add_BibleVerse @BibleId, 119033006, N'By the Lord’s decree the heavens were made; by a mere word from his mouth all the stars in the sky were created.'
EXEC add_BibleVerse @BibleId, 119033007, N'He piles up the water of the sea; he puts the oceans in storehouses.'
EXEC add_BibleVerse @BibleId, 119033008, N'Let the whole earth fear the Lord! Let all who live in the world stand in awe of him!'
EXEC add_BibleVerse @BibleId, 119033009, N'For he spoke, and it came into existence, he issued the decree, and it stood firm.'
EXEC add_BibleVerse @BibleId, 119033010, N'The Lord frustrates the decisions of the nations; he nullifies the plans of the peoples.'
EXEC add_BibleVerse @BibleId, 119033011, N'The Lord’s decisions stand forever; his plans abide throughout the ages.'
EXEC add_BibleVerse @BibleId, 119033012, N'How blessed is the nation whose God is the Lord, the people whom he has chosen to be his special possession.'
EXEC add_BibleVerse @BibleId, 119033013, N'The Lord watches from heaven; he sees all people.'
EXEC add_BibleVerse @BibleId, 119033014, N'From the place where he lives he looks carefully at all the earth’s inhabitants.'
EXEC add_BibleVerse @BibleId, 119033015, N'He is the one who forms every human heart, and takes note of all their actions.'
EXEC add_BibleVerse @BibleId, 119033016, N'No king is delivered by his vast army; a warrior is not saved by his great might.'
EXEC add_BibleVerse @BibleId, 119033017, N'A horse disappoints those who trust in it for victory; despite its great strength, it cannot deliver.'
EXEC add_BibleVerse @BibleId, 119033018, N'Look, the Lord takes notice of his loyal followers, those who wait for him to demonstrate his faithfulness'
EXEC add_BibleVerse @BibleId, 119033019, N'by saving their lives from death and sustaining them during times of famine.'
EXEC add_BibleVerse @BibleId, 119033020, N'We wait for the Lord; he is our deliverer and shield.'
EXEC add_BibleVerse @BibleId, 119033021, N'For our hearts rejoice in him, for we trust in his holy name.'
EXEC add_BibleVerse @BibleId, 119033022, N'May we experience your faithfulness, O Lord, for we wait for you.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119034001, @markup=N'I will praise the Lord at all times; my mouth will continually praise him. ', @premarkup=N'Written by David, when he pretended to be insane before Abimelech, causing the king to send him away.'
EXEC add_BibleVerse @BibleId, 119034002, N'I will boast in the Lord; let the oppressed hear and rejoice!'
EXEC add_BibleVerse @BibleId, 119034003, N'Magnify the Lord with me! Let’s praise his name together!'
EXEC add_BibleVerse @BibleId, 119034004, N'I sought the Lord’s help and he answered me; he delivered me from all my fears.'
EXEC add_BibleVerse @BibleId, 119034005, N'Those who look to him for help are happy; their faces are not ashamed.'
EXEC add_BibleVerse @BibleId, 119034006, N'This oppressed man cried out and the Lord heard; he saved him from all his troubles.'
EXEC add_BibleVerse @BibleId, 119034007, N'The Lord’s angel camps around the Lord’s loyal followers and delivers them.'
EXEC add_BibleVerse @BibleId, 119034008, N'Taste and see that the Lord is good! How blessed is the one who takes shelter in him!'
EXEC add_BibleVerse @BibleId, 119034009, N'Remain loyal to the Lord, you chosen people of his, for his loyal followers lack nothing!'
EXEC add_BibleVerse @BibleId, 119034010, N'Even young lions sometimes lack food and are hungry, but those who seek the Lord lack no good thing.'
EXEC add_BibleVerse @BibleId, 119034011, N'Come children! Listen to me! I will teach you what it means to fear the Lord.'
EXEC add_BibleVerse @BibleId, 119034012, N'Do you want to really live? Would you love to live a long, happy life?'
EXEC add_BibleVerse @BibleId, 119034013, N'Then make sure you don’t speak evil words or use deceptive speech!'
EXEC add_BibleVerse @BibleId, 119034014, N'Turn away from evil and do what is right! Strive for peace and promote it!'
EXEC add_BibleVerse @BibleId, 119034015, N'The Lord pays attention to the godly and hears their cry for help.'
EXEC add_BibleVerse @BibleId, 119034016, N'But the Lord opposes evildoers and wipes out all memory of them from the earth.'
EXEC add_BibleVerse @BibleId, 119034017, N'The godly cry out and the Lord hears; he saves them from all their troubles.'
EXEC add_BibleVerse @BibleId, 119034018, N'The Lord is near the brokenhearted; he delivers those who are discouraged.'
EXEC add_BibleVerse @BibleId, 119034019, N'The godly face many dangers, but the Lord saves them from each one of them.'
EXEC add_BibleVerse @BibleId, 119034020, N'He protects all his bones; not one of them is broken.'
EXEC add_BibleVerse @BibleId, 119034021, N'Evil people self-destruct; those who hate the godly are punished.'
EXEC add_BibleVerse @BibleId, 119034022, N'The Lord rescues his servants; all who take shelter in him escape punishment.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119035001, @markup=N'O Lord, fight those who fight with me! Attack those who attack me! ', @premarkup=N'By David.'
EXEC add_BibleVerse @BibleId, 119035002, N'Grab your small shield and large shield, and rise up to help me!'
EXEC add_BibleVerse @BibleId, 119035003, N'Use your spear and lance against those who chase me! Assure me with these words: “I am your deliverer!”'
EXEC add_BibleVerse @BibleId, 119035004, N'May those who seek my life be embarrassed and humiliated! May those who plan to harm me be turned back and ashamed!'
EXEC add_BibleVerse @BibleId, 119035005, N'May they be like wind-driven chaff, as the Lord’s angel attacks them!'
EXEC add_BibleVerse @BibleId, 119035006, N'May their path be dark and slippery, as the Lord’s angel chases them!'
EXEC add_BibleVerse @BibleId, 119035007, N'I did not harm them, but they hid a net to catch me and dug a pit to trap me.'
EXEC add_BibleVerse @BibleId, 119035008, N'Let destruction take them by surprise! Let the net they hid catch them! Let them fall into destruction!'
EXEC add_BibleVerse @BibleId, 119035009, N'Then I will rejoice in the Lord and be happy because of his deliverance.'
EXEC add_BibleVerse @BibleId, 119035010, N'With all my strength I will say, “O Lord, who can compare to you? You rescue the oppressed from those who try to overpower them; the oppressed and needy from those who try to rob them.”'
EXEC add_BibleVerse @BibleId, 119035011, N'Violent men perjure themselves, and falsely accuse me.'
EXEC add_BibleVerse @BibleId, 119035012, N'They repay me evil for the good I have done; I am overwhelmed with sorrow.'
EXEC add_BibleVerse @BibleId, 119035013, N'When they were sick, I wore sackcloth, and refrained from eating food. (If I am lying, may my prayers go unanswered!)'
EXEC add_BibleVerse @BibleId, 119035014, N'I mourned for them as I would for a friend or my brother. I bowed down in sorrow as if I were mourning for my mother.'
EXEC add_BibleVerse @BibleId, 119035015, N'But when I stumbled, they rejoiced and gathered together; they gathered together to ambush me. They tore at me without stopping to rest.'
EXEC add_BibleVerse @BibleId, 119035016, N'When I tripped, they taunted me relentlessly, and tried to bite me.'
EXEC add_BibleVerse @BibleId, 119035017, N'O Lord, how long are you going to just stand there and watch this? Rescue me from their destructive attacks; guard my life from the young lions!'
EXEC add_BibleVerse @BibleId, 119035018, N'Then I will give you thanks in the great assembly; I will praise you before a large crowd of people!'
EXEC add_BibleVerse @BibleId, 119035019, N'Do not let those who are my enemies for no reason gloat over me! Do not let those who hate me without cause carry out their wicked schemes!'
EXEC add_BibleVerse @BibleId, 119035020, N'For they do not try to make peace with others, but plan ways to deceive those who are unsuspecting.'
EXEC add_BibleVerse @BibleId, 119035021, N'They are ready to devour me; they say, “Aha! Aha! We’ve got you!”'
EXEC add_BibleVerse @BibleId, 119035022, N'But you take notice, Lord! O Lord, do not remain far away from me!'
EXEC add_BibleVerse @BibleId, 119035023, N'Rouse yourself, wake up and vindicate me! My God and Lord, defend my just cause!'
EXEC add_BibleVerse @BibleId, 119035024, N'Vindicate me by your justice, O Lord my God! Do not let them gloat over me!'
EXEC add_BibleVerse @BibleId, 119035025, N'Do not let them say to themselves, “Aha! We have what we wanted!” Do not let them say, “We have devoured him!”'
EXEC add_BibleVerse @BibleId, 119035026, N'May those who want to harm me be totally embarrassed and ashamed! May those who arrogantly taunt me be covered with shame and humiliation!'
EXEC add_BibleVerse @BibleId, 119035027, N'May those who desire my vindication shout for joy and rejoice! May they continually say, “May the Lord be praised, for he wants his servant to be secure.”'
EXEC add_BibleVerse @BibleId, 119035028, N'Then I will tell others about your justice, and praise you all day long.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119036001, @markup=N'An evil man is rebellious to the core. He does not fear God, ', @premarkup=N'For the music director; written by the Lord’s servant, David; an oracle.'
EXEC add_BibleVerse @BibleId, 119036002, N'for he is too proud to recognize and give up his sin.'
EXEC add_BibleVerse @BibleId, 119036003, N'The words he speaks are sinful and deceitful; he does not care about doing what is wise and right.'
EXEC add_BibleVerse @BibleId, 119036004, N'He plans ways to sin while he lies in bed; he is committed to a sinful lifestyle; he does not reject what is evil.'
EXEC add_BibleVerse @BibleId, 119036005, N'O Lord, your loyal love reaches to the sky; your faithfulness to the clouds.'
EXEC add_BibleVerse @BibleId, 119036006, N'Your justice is like the highest mountains, your fairness like the deepest sea; you preserve mankind and the animal kingdom.'
EXEC add_BibleVerse @BibleId, 119036007, N'How precious is your loyal love, O God! The human race finds shelter under your wings.'
EXEC add_BibleVerse @BibleId, 119036008, N'They are filled with food from your house, and you allow them to drink from the river of your delicacies.'
EXEC add_BibleVerse @BibleId, 119036009, N'For you are the one who gives and sustains life.'
EXEC add_BibleVerse @BibleId, 119036010, N'Extend your loyal love to your faithful followers, and vindicate the morally upright!'
EXEC add_BibleVerse @BibleId, 119036011, N'Do not let arrogant men overtake me, or let evil men make me homeless!'
EXEC add_BibleVerse @BibleId, 119036012, N'I can see the evildoers! They have fallen! They have been knocked down and are unable to get up!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119037001, @markup=N'Do not fret when wicked men seem to succeed! Do not envy evildoers! ', @premarkup=N'By David.'
EXEC add_BibleVerse @BibleId, 119037002, N'For they will quickly dry up like grass, and wither away like plants.'
EXEC add_BibleVerse @BibleId, 119037003, N'Trust in the Lord and do what is right! Settle in the land and maintain your integrity!'
EXEC add_BibleVerse @BibleId, 119037004, N'Then you will take delight in the Lord, and he will answer your prayers.'
EXEC add_BibleVerse @BibleId, 119037005, N'Commit your future to the Lord! Trust in him, and he will act on your behalf.'
EXEC add_BibleVerse @BibleId, 119037006, N'He will vindicate you in broad daylight, and publicly defend your just cause.'
EXEC add_BibleVerse @BibleId, 119037007, N'Wait patiently for the Lord! Wait confidently for him! Do not fret over the apparent success of a sinner, a man who carries out wicked schemes!'
EXEC add_BibleVerse @BibleId, 119037008, N'Do not be angry and frustrated! Do not fret! That only leads to trouble!'
EXEC add_BibleVerse @BibleId, 119037009, N'Wicked men will be wiped out, but those who rely on the Lord are the ones who will possess the land.'
EXEC add_BibleVerse @BibleId, 119037010, N'Evil men will soon disappear; you will stare at the spot where they once were, but they will be gone.'
EXEC add_BibleVerse @BibleId, 119037011, N'But the oppressed will possess the land and enjoy great prosperity.'
EXEC add_BibleVerse @BibleId, 119037012, N'Evil men plot against the godly and viciously attack them.'
EXEC add_BibleVerse @BibleId, 119037013, N'The Lord laughs in disgust at them, for he knows that their day is coming.'
EXEC add_BibleVerse @BibleId, 119037014, N'Evil men draw their swords and prepare their bows, to bring down the oppressed and needy, and to slaughter those who are godly.'
EXEC add_BibleVerse @BibleId, 119037015, N'Their swords will pierce their own hearts, and their bows will be broken.'
EXEC add_BibleVerse @BibleId, 119037016, N'The little bit that a godly man owns is better than the wealth of many evil men,'
EXEC add_BibleVerse @BibleId, 119037017, N'for evil men will lose their power, but the Lord sustains the godly.'
EXEC add_BibleVerse @BibleId, 119037018, N'The Lord watches over the innocent day by day and they possess a permanent inheritance.'
EXEC add_BibleVerse @BibleId, 119037019, N'They will not be ashamed when hard times come; when famine comes they will have enough to eat.'
EXEC add_BibleVerse @BibleId, 119037020, N'But evil men will die; the Lord’s enemies will be incinerated – they will go up in smoke.'
EXEC add_BibleVerse @BibleId, 119037021, N'Evil men borrow, but do not repay their debt, but the godly show compassion and are generous.'
EXEC add_BibleVerse @BibleId, 119037022, N'Surely those favored by the Lord will possess the land, but those rejected by him will be wiped out.'
EXEC add_BibleVerse @BibleId, 119037023, N'The Lord grants success to the one whose behavior he finds commendable.'
EXEC add_BibleVerse @BibleId, 119037024, N'Even if he trips, he will not fall headlong, for the Lord holds his hand.'
EXEC add_BibleVerse @BibleId, 119037025, N'I was once young, now I am old. I have never seen a godly man abandoned, or his children forced to search for food.'
EXEC add_BibleVerse @BibleId, 119037026, N'All day long he shows compassion and lends to others, and his children are blessed.'
EXEC add_BibleVerse @BibleId, 119037027, N'Turn away from evil! Do what is right! Then you will enjoy lasting security.'
EXEC add_BibleVerse @BibleId, 119037028, N'For the Lord promotes justice, and never abandons his faithful followers. They are permanently secure, but the children of evil men are wiped out.'
EXEC add_BibleVerse @BibleId, 119037029, N'The godly will possess the land and will dwell in it permanently.'
EXEC add_BibleVerse @BibleId, 119037030, N'The godly speak wise words and promote justice.'
EXEC add_BibleVerse @BibleId, 119037031, N'The law of their God controls their thinking; their feet do not slip.'
EXEC add_BibleVerse @BibleId, 119037032, N'Evil men set an ambush for the godly and try to kill them.'
EXEC add_BibleVerse @BibleId, 119037033, N'But the Lord does not surrender the godly, or allow them to be condemned in a court of law.'
EXEC add_BibleVerse @BibleId, 119037034, N'Rely on the Lord! Obey his commands! Then he will permit you to possess the land; you will see the demise of evil men.'
EXEC add_BibleVerse @BibleId, 119037035, N'I have seen ruthless evil men growing in influence, like a green tree grows in its native soil.'
EXEC add_BibleVerse @BibleId, 119037036, N'But then one passes by, and suddenly they have disappeared! I looked for them, but they could not be found.'
EXEC add_BibleVerse @BibleId, 119037037, N'Take note of the one who has integrity! Observe the godly! For the one who promotes peace has a future.'
EXEC add_BibleVerse @BibleId, 119037038, N'Sinful rebels are totally destroyed; evil men have no future.'
EXEC add_BibleVerse @BibleId, 119037039, N'But the Lord delivers the godly; he protects them in times of trouble.'
EXEC add_BibleVerse @BibleId, 119037040, N'The Lord helps them and rescues them; he rescues them from evil men and delivers them, for they seek his protection.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119038001, @markup=N'O Lord, do not continue to rebuke me in your anger! Do not continue to punish me in your raging fury! ', @premarkup=N'A psalm of David, written to get God’s attention.'
EXEC add_BibleVerse @BibleId, 119038002, N'For your arrows pierce me, and your hand presses me down.'
EXEC add_BibleVerse @BibleId, 119038003, N'My whole body is sick because of your judgment; I am deprived of health because of my sin.'
EXEC add_BibleVerse @BibleId, 119038004, N'For my sins overwhelm me; like a heavy load, they are too much for me to bear.'
EXEC add_BibleVerse @BibleId, 119038005, N'My wounds are infected and starting to smell, because of my foolish sins.'
EXEC add_BibleVerse @BibleId, 119038006, N'I am dazed and completely humiliated; all day long I walk around mourning.'
EXEC add_BibleVerse @BibleId, 119038007, N'For I am overcome with shame and my whole body is sick.'
EXEC add_BibleVerse @BibleId, 119038008, N'I am numb with pain and severely battered; I groan loudly because of the anxiety I feel.'
EXEC add_BibleVerse @BibleId, 119038009, N'O Lord, you understand my heart’s desire; my groaning is not hidden from you.'
EXEC add_BibleVerse @BibleId, 119038010, N'My heart beats quickly; my strength leaves me; I can hardly see.'
EXEC add_BibleVerse @BibleId, 119038011, N'Because of my condition, even my friends and acquaintances keep their distance; my neighbors stand far away.'
EXEC add_BibleVerse @BibleId, 119038012, N'Those who seek my life try to entrap me; those who want to harm me speak destructive words; all day long they say deceitful things.'
EXEC add_BibleVerse @BibleId, 119038013, N'But I am like a deaf man – I hear nothing; I am like a mute who cannot speak.'
EXEC add_BibleVerse @BibleId, 119038014, N'I am like a man who cannot hear and is incapable of arguing his defense.'
EXEC add_BibleVerse @BibleId, 119038015, N'Yet I wait for you, O Lord! You will respond, O Lord, my God!'
EXEC add_BibleVerse @BibleId, 119038016, N'I have prayed for deliverance, because otherwise they will gloat over me; when my foot slips they will arrogantly taunt me.'
EXEC add_BibleVerse @BibleId, 119038017, N'For I am about to stumble, and I am in constant pain.'
EXEC add_BibleVerse @BibleId, 119038018, N'Yes, I confess my wrongdoing, and I am concerned about my sins.'
EXEC add_BibleVerse @BibleId, 119038019, N'But those who are my enemies for no reason are numerous; those who hate me without cause outnumber me.'
EXEC add_BibleVerse @BibleId, 119038020, N'They repay me evil for the good I have done; though I have tried to do good to them, they hurl accusations at me.'
EXEC add_BibleVerse @BibleId, 119038021, N'Do not abandon me, O Lord! My God, do not remain far away from me!'
EXEC add_BibleVerse @BibleId, 119038022, N'Hurry and help me, O Lord, my deliverer!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119039001, @markup=N'I decided, “I will watch what I say and make sure I do not sin with my tongue. I will put a muzzle over my mouth while in the presence of an evil man.” ', @premarkup=N'For the music director, Jeduthun; a psalm of David.'
EXEC add_BibleVerse @BibleId, 119039002, N'I was stone silent; I held back the urge to speak. My frustration grew;'
EXEC add_BibleVerse @BibleId, 119039003, N'my anxiety intensified. As I thought about it, I became impatient. Finally I spoke these words:'
EXEC add_BibleVerse @BibleId, 119039004, N'“O Lord, help me understand my mortality and the brevity of life! Let me realize how quickly my life will pass!'
EXEC add_BibleVerse @BibleId, 119039005, N'Look, you make my days short-lived, and my life span is nothing from your perspective. Surely all people, even those who seem secure, are nothing but vapor.'
EXEC add_BibleVerse @BibleId, 119039006, N'Surely people go through life as mere ghosts. Surely they accumulate worthless wealth without knowing who will eventually haul it away.”'
EXEC add_BibleVerse @BibleId, 119039007, N'But now, O Lord, upon what am I relying? You are my only hope!'
EXEC add_BibleVerse @BibleId, 119039008, N'Deliver me from all my sins of rebellion! Do not make me the object of fools’ insults!'
EXEC add_BibleVerse @BibleId, 119039009, N'I am silent and cannot open my mouth because of what you have done.'
EXEC add_BibleVerse @BibleId, 119039010, N'Please stop wounding me! You have almost beaten me to death!'
EXEC add_BibleVerse @BibleId, 119039011, N'You severely discipline people for their sins; like a moth you slowly devour their strength. Surely all people are a mere vapor. (Selah)'
EXEC add_BibleVerse @BibleId, 119039012, N'Hear my prayer, O Lord! Listen to my cry for help! Do not ignore my sobbing! For I am dependent on you, like one residing outside his native land; I am at your mercy, just as all my ancestors were.'
EXEC add_BibleVerse @BibleId, 119039013, N'Turn your angry gaze away from me, so I can be happy before I pass away.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119040001, @markup=N'I relied completely on the Lord, and he turned toward me and heard my cry for help. ', @premarkup=N'For the music director; By David, a psalm.'
EXEC add_BibleVerse @BibleId, 119040002, N'He lifted me out of the watery pit, out of the slimy mud. He placed my feet on a rock and gave me secure footing.'
EXEC add_BibleVerse @BibleId, 119040003, N'He gave me reason to sing a new song, praising our God. May many see what God has done, so that they might swear allegiance to him and trust in the Lord!'
EXEC add_BibleVerse @BibleId, 119040004, N'How blessed is the one who trusts in the Lord and does not seek help from the proud or from liars!'
EXEC add_BibleVerse @BibleId, 119040005, N'O Lord, my God, you have accomplished many things; you have done amazing things and carried out your purposes for us. No one can thwart you! I want to declare them and talk about them, but they are too numerous to recount!'
EXEC add_BibleVerse @BibleId, 119040006, N'Receiving sacrifices and offerings are not your primary concern. You make that quite clear to me! You do not ask for burnt sacrifices and sin offerings.'
EXEC add_BibleVerse @BibleId, 119040007, N'Then I say, “Look! I come! What is written in the scroll pertains to me.'
EXEC add_BibleVerse @BibleId, 119040008, N'I want to do what pleases you, my God. Your law dominates my thoughts.”'
EXEC add_BibleVerse @BibleId, 119040009, N'I have told the great assembly about your justice. Look! I spare no words! O Lord, you know this is true.'
EXEC add_BibleVerse @BibleId, 119040010, N'I have not failed to tell about your justice; I spoke about your reliability and deliverance; I have not neglected to tell the great assembly about your loyal love and faithfulness.'
EXEC add_BibleVerse @BibleId, 119040011, N'O Lord, you do not withhold your compassion from me. May your loyal love and faithfulness continually protect me!'
EXEC add_BibleVerse @BibleId, 119040012, N'For innumerable dangers surround me. My sins overtake me so I am unable to see; they outnumber the hairs of my head so my strength fails me.'
EXEC add_BibleVerse @BibleId, 119040013, N'Please be willing, O Lord, to rescue me! O Lord, hurry and help me!'
EXEC add_BibleVerse @BibleId, 119040014, N'May those who are trying to snatch away my life be totally embarrassed and ashamed! May those who want to harm me be turned back and ashamed!'
EXEC add_BibleVerse @BibleId, 119040015, N'May those who say to me, “Aha! Aha!” be humiliated and disgraced!'
EXEC add_BibleVerse @BibleId, 119040016, N'May all those who seek you be happy and rejoice in you! May those who love to experience your deliverance say continually, “May the Lord be praised!”'
EXEC add_BibleVerse @BibleId, 119040017, N'I am oppressed and needy! May the Lord pay attention to me! You are my helper and my deliverer! O my God, do not delay!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119041001, @markup=N'How blessed is the one who treats the poor properly! When trouble comes, the Lord delivers him. ', @premarkup=N'For the music director; a psalm of David.'
EXEC add_BibleVerse @BibleId, 119041002, N'May the Lord protect him and save his life! May he be blessed in the land! Do not turn him over to his enemies!'
EXEC add_BibleVerse @BibleId, 119041003, N'The Lord supports him on his sickbed; you completely heal him from his illness.'
EXEC add_BibleVerse @BibleId, 119041004, N'As for me, I said: “O Lord, have mercy on me! Heal me, for I have sinned against you!'
EXEC add_BibleVerse @BibleId, 119041005, N'My enemies ask this cruel question about me, ‘When will he finally die and be forgotten?’'
EXEC add_BibleVerse @BibleId, 119041006, N'When someone comes to visit, he pretends to be friendly; he thinks of ways to defame me, and when he leaves he slanders me.'
EXEC add_BibleVerse @BibleId, 119041007, N'All who hate me whisper insults about me to one another; they plan ways to harm me.'
EXEC add_BibleVerse @BibleId, 119041008, N'They say, ‘An awful disease overwhelms him, and now that he is bed-ridden he will never recover.’'
EXEC add_BibleVerse @BibleId, 119041009, N'Even my close friend whom I trusted, he who shared meals with me, has turned against me.'
EXEC add_BibleVerse @BibleId, 119041010, N'As for you, O Lord, have mercy on me and raise me up, so I can pay them back!”'
EXEC add_BibleVerse @BibleId, 119041011, N'By this I know that you are pleased with me, for my enemy does not triumph over me.'
EXEC add_BibleVerse @BibleId, 119041012, N'As for me, you uphold me because of my integrity; you allow me permanent access to your presence.'
EXEC add_BibleVerse @BibleId, 119041013, N'The Lord God of Israel deserves praise in the future and forevermore! We agree! We agree!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119042001, @markup=N'As a deer longs for streams of water, so I long for you, O God! ', @premarkup=N'For the music director; a well-written song by the Korahites.'
EXEC add_BibleVerse @BibleId, 119042002, N'I thirst for God, for the living God. I say, “When will I be able to go and appear in God’s presence?”'
EXEC add_BibleVerse @BibleId, 119042003, N'I cannot eat, I weep day and night; all day long they say to me, “Where is your God?”'
EXEC add_BibleVerse @BibleId, 119042004, N'I will remember and weep! For I was once walking along with the great throng to the temple of God, shouting and giving thanks along with the crowd as we celebrated the holy festival.'
EXEC add_BibleVerse @BibleId, 119042005, N'Why are you depressed, O my soul? Why are you upset? Wait for God! For I will again give thanks to my God for his saving intervention.'
EXEC add_BibleVerse @BibleId, 119042006, N'I am depressed, so I will pray to you while I am trapped here in the region of the upper Jordan, from Hermon, from Mount Mizar.'
EXEC add_BibleVerse @BibleId, 119042007, N'One deep stream calls out to another at the sound of your waterfalls; all your billows and waves overwhelm me.'
EXEC add_BibleVerse @BibleId, 119042008, N'By day the Lord decrees his loyal love, and by night he gives me a song, a prayer to the living God.'
EXEC add_BibleVerse @BibleId, 119042009, N'I will pray to God, my high ridge: “Why do you ignore me? Why must I walk around mourning because my enemies oppress me?”'
EXEC add_BibleVerse @BibleId, 119042010, N'My enemies’ taunts cut into me to the bone, as they say to me all day long, “Where is your God?”'
EXEC add_BibleVerse @BibleId, 119042011, N'Why are you depressed, O my soul? Why are you upset? Wait for God! For I will again give thanks to my God for his saving intervention.'
EXEC add_BibleVerse @BibleId, 119043001, N'Vindicate me, O God! Fight for me against an ungodly nation! Deliver me from deceitful and evil men!'
EXEC add_BibleVerse @BibleId, 119043002, N'For you are the God who shelters me. Why do you reject me? Why must I walk around mourning because my enemies oppress me?'
EXEC add_BibleVerse @BibleId, 119043003, N'Reveal your light and your faithfulness! They will lead me, they will escort me back to your holy hill, and to the place where you live.'
EXEC add_BibleVerse @BibleId, 119043004, N'Then I will go to the altar of God, to the God who gives me ecstatic joy, so that I express my thanks to you, O God, my God, with a harp.'
EXEC add_BibleVerse @BibleId, 119043005, N'Why are you depressed, O my soul? Why are you upset? Wait for God! For I will again give thanks to my God for his saving intervention.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119044001, @markup=N'O God, we have clearly heard; our ancestors have told us what you did in their days, in ancient times. ', @premarkup=N'For the music director; by the Korahites, a well-written song.'
EXEC add_BibleVerse @BibleId, 119044002, N'You, by your power, defeated nations and settled our fathers on their land; you crushed the people living there and enabled our ancestors to occupy it.'
EXEC add_BibleVerse @BibleId, 119044003, N'For they did not conquer the land by their swords, and they did not prevail by their strength, but rather by your power, strength and good favor, for you were partial to them.'
EXEC add_BibleVerse @BibleId, 119044004, N'You are my king, O God! Decree Jacob’s deliverance!'
EXEC add_BibleVerse @BibleId, 119044005, N'By your power we will drive back our enemies; by your strength we will trample down our foes!'
EXEC add_BibleVerse @BibleId, 119044006, N'For I do not trust in my bow, and I do not prevail by my sword.'
EXEC add_BibleVerse @BibleId, 119044007, N'For you deliver us from our enemies; you humiliate those who hate us.'
EXEC add_BibleVerse @BibleId, 119044008, N'In God I boast all day long, and we will continually give thanks to your name. (Selah)'
EXEC add_BibleVerse @BibleId, 119044009, N'But you rejected and embarrassed us! You did not go into battle with our armies.'
EXEC add_BibleVerse @BibleId, 119044010, N'You made us retreat from the enemy. Those who hate us take whatever they want from us.'
EXEC add_BibleVerse @BibleId, 119044011, N'You handed us over like sheep to be eaten; you scattered us among the nations.'
EXEC add_BibleVerse @BibleId, 119044012, N'You sold your people for a pittance; you did not ask a high price for them.'
EXEC add_BibleVerse @BibleId, 119044013, N'You made us an object of disdain to our neighbors; those who live on our borders taunt and insult us.'
EXEC add_BibleVerse @BibleId, 119044014, N'You made us an object of ridicule among the nations; foreigners treat us with contempt.'
EXEC add_BibleVerse @BibleId, 119044015, N'All day long I feel humiliated and am overwhelmed with shame,'
EXEC add_BibleVerse @BibleId, 119044016, N'before the vindictive enemy who ridicules and insults me.'
EXEC add_BibleVerse @BibleId, 119044017, N'All this has happened to us, even though we have not rejected you or violated your covenant with us.'
EXEC add_BibleVerse @BibleId, 119044018, N'We have not been unfaithful, nor have we disobeyed your commands.'
EXEC add_BibleVerse @BibleId, 119044019, N'Yet you have battered us, leaving us a heap of ruins overrun by wild dogs; you have covered us with darkness.'
EXEC add_BibleVerse @BibleId, 119044020, N'If we had rejected our God, and spread out our hands in prayer to another god,'
EXEC add_BibleVerse @BibleId, 119044021, N'would not God discover it, for he knows one’s thoughts?'
EXEC add_BibleVerse @BibleId, 119044022, N'Yet because of you we are killed all day long; we are treated like sheep at the slaughtering block.'
EXEC add_BibleVerse @BibleId, 119044023, N'Rouse yourself! Why do you sleep, O Lord? Wake up! Do not reject us forever!'
EXEC add_BibleVerse @BibleId, 119044024, N'Why do you look the other way, and ignore the way we are oppressed and mistreated?'
EXEC add_BibleVerse @BibleId, 119044025, N'For we lie in the dirt, with our bellies pressed to the ground.'
EXEC add_BibleVerse @BibleId, 119044026, N'Rise up and help us! Rescue us because of your loyal love!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119045001, @markup=N'My heart is stirred by a beautiful song. I say, “I have composed this special song for the king; my tongue is as skilled as the stylus of an experienced scribe.” ', @premarkup=N'For the music director; according to the tune of “Lilies;” by the Korahites, a well-written poem, a love song.'
EXEC add_BibleVerse @BibleId, 119045002, N'You are the most handsome of all men! You speak in an impressive and fitting manner! For this reason God grants you continual blessings.'
EXEC add_BibleVerse @BibleId, 119045003, N'Strap your sword to your thigh, O warrior! Appear in your majestic splendor!'
EXEC add_BibleVerse @BibleId, 119045004, N'Appear in your majesty and be victorious! Ride forth for the sake of what is right, on behalf of justice! Then your right hand will accomplish mighty acts!'
EXEC add_BibleVerse @BibleId, 119045005, N'Your arrows are sharp and penetrate the hearts of the king’s enemies. Nations fall at your feet.'
EXEC add_BibleVerse @BibleId, 119045006, N'Your throne, O God, is permanent. The scepter of your kingdom is a scepter of justice.'
EXEC add_BibleVerse @BibleId, 119045007, N'You love justice and hate evil. For this reason God, your God has anointed you with the oil of joy, elevating you above your companions.'
EXEC add_BibleVerse @BibleId, 119045008, N'All your garments are perfumed with myrrh, aloes, and cassia. From the luxurious palaces comes the music of stringed instruments that makes you happy.'
EXEC add_BibleVerse @BibleId, 119045009, N'Princesses are among your honored guests, your bride stands at your right hand, wearing jewelry made with gold from Ophir.'
EXEC add_BibleVerse @BibleId, 119045010, N'Listen, O princess! Observe and pay attention! Forget your homeland and your family!'
EXEC add_BibleVerse @BibleId, 119045011, N'Then the king will be attracted by your beauty. After all, he is your master! Submit to him!'
EXEC add_BibleVerse @BibleId, 119045012, N'Rich people from Tyre will seek your favor by bringing a gift.'
EXEC add_BibleVerse @BibleId, 119045013, N'The princess looks absolutely magnificent, decked out in pearls and clothed in a brocade trimmed with gold.'
EXEC add_BibleVerse @BibleId, 119045014, N'In embroidered robes she is escorted to the king. Her attendants, the maidens of honor who follow her, are led before you.'
EXEC add_BibleVerse @BibleId, 119045015, N'They are bubbling with joy as they walk in procession and enter the royal palace.'
EXEC add_BibleVerse @BibleId, 119045016, N'Your sons will carry on the dynasty of your ancestors; you will make them princes throughout the land.'
EXEC add_BibleVerse @BibleId, 119045017, N'I will proclaim your greatness through the coming years, then the nations will praise you forever.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119046001, @markup=N'God is our strong refuge; he is truly our helper in times of trouble. ', @premarkup=N'For the music director; by the Korahites; according to the alamoth style; a song.'
EXEC add_BibleVerse @BibleId, 119046002, N'For this reason we do not fear when the earth shakes, and the mountains tumble into the depths of the sea,'
EXEC add_BibleVerse @BibleId, 119046003, N'when its waves crash and foam, and the mountains shake before the surging sea. (Selah)'
EXEC add_BibleVerse @BibleId, 119046004, N'The river’s channels bring joy to the city of God, the special, holy dwelling place of the sovereign One.'
EXEC add_BibleVerse @BibleId, 119046005, N'God lives within it, it cannot be moved. God rescues it at the break of dawn.'
EXEC add_BibleVerse @BibleId, 119046006, N'Nations are in uproar, kingdoms are overthrown. God gives a shout, the earth dissolves.'
EXEC add_BibleVerse @BibleId, 119046007, N'The Lord who commands armies is on our side! The God of Jacob is our protector! (Selah)'
EXEC add_BibleVerse @BibleId, 119046008, N'Come! Witness the exploits of the Lord, who brings devastation to the earth!'
EXEC add_BibleVerse @BibleId, 119046009, N'He brings an end to wars throughout the earth; he shatters the bow and breaks the spear; he burns the shields with fire.'
EXEC add_BibleVerse @BibleId, 119046010, N'He says, “Stop your striving and recognize that I am God! I will be exalted over the nations! I will be exalted over the earth!”'
EXEC add_BibleVerse @BibleId, 119046011, N'The Lord who commands armies is on our side! The God of Jacob is our protector! (Selah)'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119047001, @markup=N'All you nations, clap your hands! Shout out to God in celebration! ', @premarkup=N'For the music director; by the Korahites; a psalm.'
EXEC add_BibleVerse @BibleId, 119047002, N'For the sovereign Lord is awe-inspiring; he is the great king who rules the whole earth!'
EXEC add_BibleVerse @BibleId, 119047003, N'He subdued nations beneath us and countries under our feet.'
EXEC add_BibleVerse @BibleId, 119047004, N'He picked out for us a special land to be a source of pride for Jacob, whom he loves. (Selah)'
EXEC add_BibleVerse @BibleId, 119047005, N'God has ascended his throne amid loud shouts; the Lord has ascended his throne amid the blaring of ram’s horns.'
EXEC add_BibleVerse @BibleId, 119047006, N'Sing to God! Sing! Sing to our king! Sing!'
EXEC add_BibleVerse @BibleId, 119047007, N'For God is king of the whole earth! Sing a well-written song!'
EXEC add_BibleVerse @BibleId, 119047008, N'God reigns over the nations! God sits on his holy throne!'
EXEC add_BibleVerse @BibleId, 119047009, N'The nobles of the nations assemble, along with the people of the God of Abraham, for God has authority over the rulers of the earth. He is highly exalted!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119048001, @markup=N'The Lord is great and certainly worthy of praise in the city of our God, his holy hill. ', @premarkup=N'A song, a psalm by the Korahites.'
EXEC add_BibleVerse @BibleId, 119048002, N'It is lofty and pleasing to look at, a source of joy to the whole earth. Mount Zion resembles the peaks of Zaphon; it is the city of the great king.'
EXEC add_BibleVerse @BibleId, 119048003, N'God is in its fortresses; he reveals himself as its defender.'
EXEC add_BibleVerse @BibleId, 119048004, N'For look, the kings assemble; they advance together.'
EXEC add_BibleVerse @BibleId, 119048005, N'As soon as they see, they are shocked; they are terrified, they quickly retreat.'
EXEC add_BibleVerse @BibleId, 119048006, N'Look at them shake uncontrollably, like a woman writhing in childbirth.'
EXEC add_BibleVerse @BibleId, 119048007, N'With an east wind you shatter the large ships.'
EXEC add_BibleVerse @BibleId, 119048008, N'We heard about God’s mighty deeds, now we have seen them, in the city of the Lord, the invincible Warrior, in the city of our God. God makes it permanently secure. (Selah)'
EXEC add_BibleVerse @BibleId, 119048009, N'We reflect on your loyal love, O God, within your temple.'
EXEC add_BibleVerse @BibleId, 119048010, N'The praise you receive as far away as the ends of the earth is worthy of your reputation, O God. You execute justice!'
EXEC add_BibleVerse @BibleId, 119048011, N'Mount Zion rejoices; the towns of Judah are happy, because of your acts of judgment.'
EXEC add_BibleVerse @BibleId, 119048012, N'Walk around Zion! Encircle it! Count its towers!'
EXEC add_BibleVerse @BibleId, 119048013, N'Consider its defenses! Walk through its fortresses, so you can tell the next generation about it!'
EXEC add_BibleVerse @BibleId, 119048014, N'For God, our God, is our defender forever! He guides us!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119049001, @markup=N'Listen to this, all you nations! Pay attention, all you inhabitants of the world! ', @premarkup=N'For the music director, a psalm by the Korahites.'
EXEC add_BibleVerse @BibleId, 119049002, N'Pay attention, all you people, both rich and poor!'
EXEC add_BibleVerse @BibleId, 119049003, N'I will declare a wise saying; I will share my profound thoughts.'
EXEC add_BibleVerse @BibleId, 119049004, N'I will learn a song that imparts wisdom; I will then sing my insightful song to the accompaniment of a harp.'
EXEC add_BibleVerse @BibleId, 119049005, N'Why should I be afraid in times of trouble, when the sinful deeds of deceptive men threaten to overwhelm me?'
EXEC add_BibleVerse @BibleId, 119049006, N'They trust in their wealth and boast in their great riches.'
EXEC add_BibleVerse @BibleId, 119049007, N'Certainly a man cannot rescue his brother; he cannot pay God an adequate ransom price'
EXEC add_BibleVerse @BibleId, 119049008, N'(the ransom price for a human life is too high, and people go to their final destiny),'
EXEC add_BibleVerse @BibleId, 119049009, N'so that he might continue to live forever and not experience death.'
EXEC add_BibleVerse @BibleId, 119049010, N'Surely one sees that even wise people die; fools and spiritually insensitive people all pass away and leave their wealth to others.'
EXEC add_BibleVerse @BibleId, 119049011, N'Their grave becomes their permanent residence, their eternal dwelling place. They name their lands after themselves,'
EXEC add_BibleVerse @BibleId, 119049012, N'but, despite their wealth, people do not last, they are like animals that perish.'
EXEC add_BibleVerse @BibleId, 119049013, N'This is the destiny of fools, and of those who approve of their philosophy. (Selah)'
EXEC add_BibleVerse @BibleId, 119049014, N'They will travel to Sheol like sheep, with death as their shepherd. The godly will rule over them when the day of vindication dawns; Sheol will consume their bodies and they will no longer live in impressive houses.'
EXEC add_BibleVerse @BibleId, 119049015, N'But God will rescue my life from the power of Sheol; certainly he will pull me to safety. (Selah)'
EXEC add_BibleVerse @BibleId, 119049016, N'Do not be afraid when a man becomes rich and his wealth multiplies!'
EXEC add_BibleVerse @BibleId, 119049017, N'For he will take nothing with him when he dies; his wealth will not follow him down into the grave.'
EXEC add_BibleVerse @BibleId, 119049018, N'He pronounces this blessing on himself while he is alive: “May men praise you, for you have done well!”'
EXEC add_BibleVerse @BibleId, 119049019, N'But he will join his ancestors; they will never again see the light of day.'
EXEC add_BibleVerse @BibleId, 119049020, N'Wealthy people do not understand; they are like animals that perish.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119050001, @markup=N'El, God, the Lord speaks, and summons the earth to come from the east and west. ', @premarkup=N'A psalm by Asaph.'
EXEC add_BibleVerse @BibleId, 119050002, N'From Zion, the most beautiful of all places, God comes in splendor.'
EXEC add_BibleVerse @BibleId, 119050003, N'Our God approaches and is not silent; consuming fire goes ahead of him and all around him a storm rages.'
EXEC add_BibleVerse @BibleId, 119050004, N'He summons the heavens above, as well as the earth, so that he might judge his people.'
EXEC add_BibleVerse @BibleId, 119050005, N'He says: “Assemble my covenant people before me, those who ratified a covenant with me by sacrifice!”'
EXEC add_BibleVerse @BibleId, 119050006, N'The heavens declare his fairness, for God is judge. (Selah)'
EXEC add_BibleVerse @BibleId, 119050007, N'He says: “Listen my people! I am speaking! Listen Israel! I am accusing you! I am God, your God!'
EXEC add_BibleVerse @BibleId, 119050008, N'I am not condemning you because of your sacrifices, or because of your burnt sacrifices that you continually offer me.'
EXEC add_BibleVerse @BibleId, 119050009, N'I do not need to take a bull from your household or goats from your sheepfolds.'
EXEC add_BibleVerse @BibleId, 119050010, N'For every wild animal in the forest belongs to me, as well as the cattle that graze on a thousand hills.'
EXEC add_BibleVerse @BibleId, 119050011, N'I keep track of every bird in the hills, and the insects of the field are mine.'
EXEC add_BibleVerse @BibleId, 119050012, N'Even if I were hungry, I would not tell you, for the world and all it contains belong to me.'
EXEC add_BibleVerse @BibleId, 119050013, N'Do I eat the flesh of bulls? Do I drink the blood of goats?'
EXEC add_BibleVerse @BibleId, 119050014, N'Present to God a thank-offering! Repay your vows to the sovereign One!'
EXEC add_BibleVerse @BibleId, 119050015, N'Pray to me when you are in trouble! I will deliver you, and you will honor me!”'
EXEC add_BibleVerse @BibleId, 119050016, N'God says this to the evildoer: “How can you declare my commands, and talk about my covenant?'
EXEC add_BibleVerse @BibleId, 119050017, N'For you hate instruction and reject my words.'
EXEC add_BibleVerse @BibleId, 119050018, N'When you see a thief, you join him; you associate with men who are unfaithful to their wives.'
EXEC add_BibleVerse @BibleId, 119050019, N'You do damage with words, and use your tongue to deceive.'
EXEC add_BibleVerse @BibleId, 119050020, N'You plot against your brother; you slander your own brother.'
EXEC add_BibleVerse @BibleId, 119050021, N'When you did these things, I was silent, so you thought I was exactly like you. But now I will condemn you and state my case against you!'
EXEC add_BibleVerse @BibleId, 119050022, N'Carefully consider this, you who reject God! Otherwise I will rip you to shreds and no one will be able to rescue you.'
EXEC add_BibleVerse @BibleId, 119050023, N'Whoever presents a thank-offering honors me. To whoever obeys my commands, I will reveal my power to deliver.”'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119051001, @markup=N'Have mercy on me, O God, because of your loyal love! Because of your great compassion, wipe away my rebellious acts! ', @premarkup=N'For the music director; a psalm of David, written when Nathan the prophet confronted him after David’s affair with Bathsheba.'
EXEC add_BibleVerse @BibleId, 119051002, N'Wash away my wrongdoing! Cleanse me of my sin!'
EXEC add_BibleVerse @BibleId, 119051003, N'For I am aware of my rebellious acts; I am forever conscious of my sin.'
EXEC add_BibleVerse @BibleId, 119051004, N'Against you – you above all – I have sinned; I have done what is evil in your sight. So you are just when you confront me; you are right when you condemn me.'
EXEC add_BibleVerse @BibleId, 119051005, N'Look, I was guilty of sin from birth, a sinner the moment my mother conceived me.'
EXEC add_BibleVerse @BibleId, 119051006, N'Look, you desire integrity in the inner man; you want me to possess wisdom.'
EXEC add_BibleVerse @BibleId, 119051007, N'Sprinkle me with water and I will be pure; wash me and I will be whiter than snow.'
EXEC add_BibleVerse @BibleId, 119051008, N'Grant me the ultimate joy of being forgiven! May the bones you crushed rejoice!'
EXEC add_BibleVerse @BibleId, 119051009, N'Hide your face from my sins! Wipe away all my guilt!'
EXEC add_BibleVerse @BibleId, 119051010, N'Create for me a pure heart, O God! Renew a resolute spirit within me!'
EXEC add_BibleVerse @BibleId, 119051011, N'Do not reject me! Do not take your Holy Spirit away from me!'
EXEC add_BibleVerse @BibleId, 119051012, N'Let me again experience the joy of your deliverance! Sustain me by giving me the desire to obey!'
EXEC add_BibleVerse @BibleId, 119051013, N'Then I will teach rebels your merciful ways, and sinners will turn to you.'
EXEC add_BibleVerse @BibleId, 119051014, N'Rescue me from the guilt of murder, O God, the God who delivers me! Then my tongue will shout for joy because of your deliverance.'
EXEC add_BibleVerse @BibleId, 119051015, N'O Lord, give me the words! Then my mouth will praise you.'
EXEC add_BibleVerse @BibleId, 119051016, N'Certainly you do not want a sacrifice, or else I would offer it; you do not desire a burnt sacrifice.'
EXEC add_BibleVerse @BibleId, 119051017, N'The sacrifices God desires are a humble spirit – O God, a humble and repentant heart you will not reject.'
EXEC add_BibleVerse @BibleId, 119051018, N'Because you favor Zion, do what is good for her! Fortify the walls of Jerusalem!'
EXEC add_BibleVerse @BibleId, 119051019, N'Then you will accept the proper sacrifices, burnt sacrifices and whole offerings; then bulls will be sacrificed on your altar.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119052001, @markup=N'Why do you boast about your evil plans, O powerful man? God’s loyal love protects me all day long! ', @premarkup=N'For the music director; a well-written song by David. It was written when Doeg the Edomite went and informed Saul: “David has arrived at the home of Ahimelech.”'
EXEC add_BibleVerse @BibleId, 119052002, N'Your tongue carries out your destructive plans; it is as effective as a sharp razor, O deceiver.'
EXEC add_BibleVerse @BibleId, 119052003, N'You love evil more than good, lies more than speaking the truth. (Selah)'
EXEC add_BibleVerse @BibleId, 119052004, N'You love to use all the words that destroy, and the tongue that deceives.'
EXEC add_BibleVerse @BibleId, 119052005, N'Yet God will make you a permanent heap of ruins. He will scoop you up and remove you from your home; he will uproot you from the land of the living. (Selah)'
EXEC add_BibleVerse @BibleId, 119052006, N'When the godly see this, they will be filled with awe, and will mock the evildoer, saying:'
EXEC add_BibleVerse @BibleId, 119052007, N'“Look, here is the man who would not make God his protector! He trusted in his great wealth and was confident about his plans to destroy others.”'
EXEC add_BibleVerse @BibleId, 119052008, N'But I am like a flourishing olive tree in the house of God; I continually trust in God’s loyal love.'
EXEC add_BibleVerse @BibleId, 119052009, N'I will continually thank you when you execute judgment; I will rely on you, for your loyal followers know you are good.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119053001, @markup=N'Fools say to themselves, “There is no God.” They sin and commit evil deeds; none of them does what is right. ', @premarkup=N'For the music director; according to the machalath style; a well-written song by David.'
EXEC add_BibleVerse @BibleId, 119053002, N'God looks down from heaven at the human race, to see if there is anyone who is wise and seeks God.'
EXEC add_BibleVerse @BibleId, 119053003, N'Everyone rejects God; they are all morally corrupt. None of them does what is right, not even one!'
EXEC add_BibleVerse @BibleId, 119053004, N'All those who behave wickedly do not understand – those who devour my people as if they were eating bread, and do not call out to God.'
EXEC add_BibleVerse @BibleId, 119053005, N'They are absolutely terrified, even by things that do not normally cause fear. For God annihilates those who attack you. You are able to humiliate them because God has rejected them.'
EXEC add_BibleVerse @BibleId, 119053006, N'I wish the deliverance of Israel would come from Zion! When God restores the well-being of his people, may Jacob rejoice, may Israel be happy!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119054001, @markup=N'O God, deliver me by your name! Vindicate me by your power! ', @premarkup=N'For the music director, to be accompanied by stringed instruments; a well-written song by David. It was written when the Ziphites came and informed Saul: “David is hiding with us.”'
EXEC add_BibleVerse @BibleId, 119054002, N'O God, listen to my prayer! Pay attention to what I say!'
EXEC add_BibleVerse @BibleId, 119054003, N'For foreigners attack me; ruthless men, who do not respect God, seek my life. (Selah)'
EXEC add_BibleVerse @BibleId, 119054004, N'Look, God is my deliverer! The Lord is among those who support me.'
EXEC add_BibleVerse @BibleId, 119054005, N'May those who wait to ambush me be repaid for their evil! As a demonstration of your faithfulness, destroy them!'
EXEC add_BibleVerse @BibleId, 119054006, N'With a freewill offering I will sacrifice to you! I will give thanks to your name, O Lord, for it is good!'
EXEC add_BibleVerse @BibleId, 119054007, N'Surely he rescues me from all trouble, and I triumph over my enemies.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119055001, @markup=N'Listen, O God, to my prayer! Do not ignore my appeal for mercy! ', @premarkup=N'For the music director, to be accompanied by stringed instruments; a well-written song by David.'
EXEC add_BibleVerse @BibleId, 119055002, N'Pay attention to me and answer me! I am so upset and distressed, I am beside myself,'
EXEC add_BibleVerse @BibleId, 119055003, N'because of what the enemy says, and because of how the wicked pressure me, for they hurl trouble down upon me and angrily attack me.'
EXEC add_BibleVerse @BibleId, 119055004, N'My heart beats violently within me; the horrors of death overcome me.'
EXEC add_BibleVerse @BibleId, 119055005, N'Fear and panic overpower me; terror overwhelms me.'
EXEC add_BibleVerse @BibleId, 119055006, N'I say, “I wish I had wings like a dove! I would fly away and settle in a safe place!'
EXEC add_BibleVerse @BibleId, 119055007, N'Look, I will escape to a distant place; I will stay in the wilderness. (Selah)'
EXEC add_BibleVerse @BibleId, 119055008, N'I will hurry off to a place that is safe from the strong wind and the gale.”'
EXEC add_BibleVerse @BibleId, 119055009, N'Confuse them, O Lord! Frustrate their plans! For I see violence and conflict in the city.'
EXEC add_BibleVerse @BibleId, 119055010, N'Day and night they walk around on its walls, while wickedness and destruction are within it.'
EXEC add_BibleVerse @BibleId, 119055011, N'Disaster is within it; violence and deceit do not depart from its public square.'
EXEC add_BibleVerse @BibleId, 119055012, N'Indeed, it is not an enemy who insults me, or else I could bear it; it is not one who hates me who arrogantly taunts me, or else I could hide from him.'
EXEC add_BibleVerse @BibleId, 119055013, N'But it is you, a man like me, my close friend in whom I confided.'
EXEC add_BibleVerse @BibleId, 119055014, N'We would share personal thoughts with each other; in God’s temple we would walk together among the crowd.'
EXEC add_BibleVerse @BibleId, 119055015, N'May death destroy them! May they go down alive into Sheol! For evil is in their dwelling place and in their midst.'
EXEC add_BibleVerse @BibleId, 119055016, N'As for me, I will call out to God, and the Lord will deliver me.'
EXEC add_BibleVerse @BibleId, 119055017, N'During the evening, morning, and noontime I will lament and moan, and he will hear me.'
EXEC add_BibleVerse @BibleId, 119055018, N'He will rescue me and protect me from those who attack me, even though they greatly outnumber me.'
EXEC add_BibleVerse @BibleId, 119055019, N'God, the one who has reigned as king from long ago, will hear and humiliate them. (Selah) They refuse to change, and do not fear God.'
EXEC add_BibleVerse @BibleId, 119055020, N'He attacks his friends; he breaks his solemn promises to them.'
EXEC add_BibleVerse @BibleId, 119055021, N'His words are as smooth as butter, but he harbors animosity in his heart. His words seem softer than oil, but they are really like sharp swords.'
EXEC add_BibleVerse @BibleId, 119055022, N'Throw your burden upon the Lord, and he will sustain you. He will never allow the godly to be upended.'
EXEC add_BibleVerse @BibleId, 119055023, N'But you, O God, will bring them down to the deep Pit. Violent and deceitful people will not live even half a normal lifespan. But as for me, I trust in you.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119056001, @markup=N'Have mercy on me, O God, for men are attacking me! All day long hostile enemies are tormenting me. ', @premarkup=N'For the music director; according to the yonath-elem-rechovim style; a prayer of David, written when the Philistines captured him in Gath.'
EXEC add_BibleVerse @BibleId, 119056002, N'Those who anticipate my defeat attack me all day long. Indeed, many are fighting against me, O Exalted One.'
EXEC add_BibleVerse @BibleId, 119056003, N'When I am afraid, I trust in you.'
EXEC add_BibleVerse @BibleId, 119056004, N'In God – I boast in his promise – in God I trust, I am not afraid. What can mere men do to me?'
EXEC add_BibleVerse @BibleId, 119056005, N'All day long they cause me trouble; they make a habit of plotting my demise.'
EXEC add_BibleVerse @BibleId, 119056006, N'They stalk and lurk; they watch my every step, as they prepare to take my life.'
EXEC add_BibleVerse @BibleId, 119056007, N'Because they are bent on violence, do not let them escape! In your anger bring down the nations, O God!'
EXEC add_BibleVerse @BibleId, 119056008, N'You keep track of my misery. Put my tears in your leather container! Are they not recorded in your scroll?'
EXEC add_BibleVerse @BibleId, 119056009, N'My enemies will turn back when I cry out to you for help; I know that God is on my side.'
EXEC add_BibleVerse @BibleId, 119056010, N'In God – I boast in his promise – in the Lord – I boast in his promise –'
EXEC add_BibleVerse @BibleId, 119056011, N'in God I trust, I am not afraid. What can mere men do to me?'
EXEC add_BibleVerse @BibleId, 119056012, N'I am obligated to fulfill the vows I made to you, O God; I will give you the thank-offerings you deserve,'
EXEC add_BibleVerse @BibleId, 119056013, N'when you deliver my life from death. You keep my feet from stumbling, so that I might serve God as I enjoy life.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119057001, @markup=N'Have mercy on me, O God! Have mercy on me! For in you I have taken shelter. In the shadow of your wings I take shelter until trouble passes. ', @premarkup=N'For the music director; according to the al-tashcheth style; a prayer of David, written when he fled from Saul into the cave.'
EXEC add_BibleVerse @BibleId, 119057002, N'I cry out for help to the sovereign God, to the God who vindicates me.'
EXEC add_BibleVerse @BibleId, 119057003, N'May he send help from heaven and deliver me from my enemies who hurl insults! (Selah) May God send his loyal love and faithfulness!'
EXEC add_BibleVerse @BibleId, 119057004, N'I am surrounded by lions; I lie down among those who want to devour me; men whose teeth are spears and arrows, whose tongues are a sharp sword.'
EXEC add_BibleVerse @BibleId, 119057005, N'Rise up above the sky, O God! May your splendor cover the whole earth!'
EXEC add_BibleVerse @BibleId, 119057006, N'They have prepared a net to trap me; I am discouraged. They have dug a pit for me. They will fall into it! (Selah)'
EXEC add_BibleVerse @BibleId, 119057007, N'I am determined, O God! I am determined! I will sing and praise you!'
EXEC add_BibleVerse @BibleId, 119057008, N'Awake, my soul! Awake, O stringed instrument and harp! I will wake up at dawn!'
EXEC add_BibleVerse @BibleId, 119057009, N'I will give you thanks before the nations, O Master! I will sing praises to you before foreigners!'
EXEC add_BibleVerse @BibleId, 119057010, N'For your loyal love extends beyond the sky, and your faithfulness reaches the clouds.'
EXEC add_BibleVerse @BibleId, 119057011, N'Rise up above the sky, O God! May your splendor cover the whole earth!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119058001, @markup=N'Do you rulers really pronounce just decisions? Do you judge people fairly? ', @premarkup=N'For the music director; according to the al-tashcheth style; a prayer of David.'
EXEC add_BibleVerse @BibleId, 119058002, N'No! You plan how to do what is unjust; you deal out violence in the earth.'
EXEC add_BibleVerse @BibleId, 119058003, N'The wicked turn aside from birth; liars go astray as soon as they are born.'
EXEC add_BibleVerse @BibleId, 119058004, N'Their venom is like that of a snake, like a deaf serpent that does not hear,'
EXEC add_BibleVerse @BibleId, 119058005, N'that does not respond to the magicians, or to a skilled snake-charmer.'
EXEC add_BibleVerse @BibleId, 119058006, N'O God, break the teeth in their mouths! Smash the jawbones of the lions, O Lord!'
EXEC add_BibleVerse @BibleId, 119058007, N'Let them disappear like water that flows away! Let them wither like grass!'
EXEC add_BibleVerse @BibleId, 119058008, N'Let them be like a snail that melts away as it moves along! Let them be like stillborn babies that never see the sun!'
EXEC add_BibleVerse @BibleId, 119058009, N'Before the kindling is even placed under your pots, he will sweep it away along with both the raw and cooked meat.'
EXEC add_BibleVerse @BibleId, 119058010, N'The godly will rejoice when they see vengeance carried out; they will bathe their feet in the blood of the wicked.'
EXEC add_BibleVerse @BibleId, 119058011, N'Then observers will say, “Yes indeed, the godly are rewarded! Yes indeed, there is a God who judges in the earth!”'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119059001, @markup=N'Deliver me from my enemies, my God! Protect me from those who attack me! ', @premarkup=N'For the music director; according to the al-tashcheth style; a prayer of David, written when Saul sent men to surround his house and murder him.'
EXEC add_BibleVerse @BibleId, 119059002, N'Deliver me from evildoers! Rescue me from violent men!'
EXEC add_BibleVerse @BibleId, 119059003, N'For look, they wait to ambush me; powerful men stalk me, but not because I have rebelled or sinned, O Lord.'
EXEC add_BibleVerse @BibleId, 119059004, N'Though I have done nothing wrong, they are anxious to attack. Spring into action and help me! Take notice of me!'
EXEC add_BibleVerse @BibleId, 119059005, N'You, O Lord God, the invincible warrior, the God of Israel, rouse yourself and punish all the nations! Have no mercy on any treacherous evildoers! (Selah)'
EXEC add_BibleVerse @BibleId, 119059006, N'They return in the evening; they growl like a dog and prowl around outside the city.'
EXEC add_BibleVerse @BibleId, 119059007, N'Look, they hurl insults at me and openly threaten to kill me, for they say, “Who hears?”'
EXEC add_BibleVerse @BibleId, 119059008, N'But you, O Lord, laugh in disgust at them; you taunt all the nations.'
EXEC add_BibleVerse @BibleId, 119059009, N'You are my source of strength! I will wait for you! For God is my refuge.'
EXEC add_BibleVerse @BibleId, 119059010, N'The God who loves me will help me; God will enable me to triumph over my enemies.'
EXEC add_BibleVerse @BibleId, 119059011, N'Do not strike them dead suddenly, because then my people might forget the lesson. Use your power to make them homeless vagabonds and then bring them down, O Lord who shields us!'
EXEC add_BibleVerse @BibleId, 119059012, N'They speak sinful words. So let them be trapped by their own pride and by the curses and lies they speak!'
EXEC add_BibleVerse @BibleId, 119059013, N'Angrily wipe them out! Wipe them out so they vanish! Let them know that God rules in Jacob and to the ends of the earth! (Selah)'
EXEC add_BibleVerse @BibleId, 119059014, N'They return in the evening; they growl like a dog and prowl around outside the city.'
EXEC add_BibleVerse @BibleId, 119059015, N'They wander around looking for something to eat; they refuse to sleep until they are full.'
EXEC add_BibleVerse @BibleId, 119059016, N'As for me, I will sing about your strength; I will praise your loyal love in the morning. For you are my refuge and my place of shelter when I face trouble.'
EXEC add_BibleVerse @BibleId, 119059017, N'You are my source of strength! I will sing praises to you! For God is my refuge, the God who loves me.'
EXEC add_BibleVerse @BibleId, 119060001, N'For the music director; according to the shushan-eduth style; a prayer of David written to instruct others. It was written when he fought against Aram Naharaim and Aram-Zobah. That was when Joab turned back and struck down 12,000 Edomites in the Valley of Salt. O God, you have rejected us. You suddenly turned on us in your anger. Please restore us!'
EXEC add_BibleVerse @BibleId, 119060002, N'You made the earth quake; you split it open. Repair its breaches, for it is ready to fall.'
EXEC add_BibleVerse @BibleId, 119060003, N'You have made your people experience hard times; you have made us drink intoxicating wine.'
EXEC add_BibleVerse @BibleId, 119060004, N'You have given your loyal followers a rallying flag, so that they might seek safety from the bow. (Selah)'
EXEC add_BibleVerse @BibleId, 119060005, N'Deliver by your power and answer me, so that the ones you love may be safe.'
EXEC add_BibleVerse @BibleId, 119060006, N'God has spoken in his sanctuary: “I will triumph! I will parcel out Shechem; the Valley of Succoth I will measure off.'
EXEC add_BibleVerse @BibleId, 119060007, N'Gilead belongs to me, as does Manasseh! Ephraim is my helmet, Judah my royal scepter.'
EXEC add_BibleVerse @BibleId, 119060008, N'Moab is my washbasin. I will make Edom serve me. I will shout in triumph over Philistia.”'
EXEC add_BibleVerse @BibleId, 119060009, N'Who will lead me into the fortified city? Who will bring me to Edom?'
EXEC add_BibleVerse @BibleId, 119060010, N'Have you not rejected us, O God? O God, you do not go into battle with our armies.'
EXEC add_BibleVerse @BibleId, 119060011, N'Give us help against the enemy, for any help men might offer is futile.'
EXEC add_BibleVerse @BibleId, 119060012, N'By God’s power we will conquer; he will trample down our enemies.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119061001, @markup=N'O God, hear my cry for help! Pay attention to my prayer! ', @premarkup=N'For the music director; to be played on a stringed instrument; written by David.'
EXEC add_BibleVerse @BibleId, 119061002, N'From the most remote place on earth I call out to you in my despair. Lead me up to an inaccessible rocky summit!'
EXEC add_BibleVerse @BibleId, 119061003, N'Indeed, you are my shelter, a strong tower that protects me from the enemy.'
EXEC add_BibleVerse @BibleId, 119061004, N'I will be a permanent guest in your home; I will find shelter in the protection of your wings. (Selah)'
EXEC add_BibleVerse @BibleId, 119061005, N'For you, O God, hear my vows; you grant me the reward that belongs to your loyal followers.'
EXEC add_BibleVerse @BibleId, 119061006, N'Give the king long life! Make his lifetime span several generations!'
EXEC add_BibleVerse @BibleId, 119061007, N'May he reign forever before God! Decree that your loyal love and faithfulness should protect him.'
EXEC add_BibleVerse @BibleId, 119061008, N'Then I will sing praises to your name continually, as I fulfill my vows day after day.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119062001, @markup=N'For God alone I patiently wait; he is the one who delivers me. ', @premarkup=N'For the music director, Jeduthun; a psalm of David.'
EXEC add_BibleVerse @BibleId, 119062002, N'He alone is my protector and deliverer. He is my refuge; I will not be upended.'
EXEC add_BibleVerse @BibleId, 119062003, N'How long will you threaten a man? All of you are murderers, as dangerous as a leaning wall or an unstable fence.'
EXEC add_BibleVerse @BibleId, 119062004, N'They spend all their time planning how to bring him down. They love to use deceit; they pronounce blessings with their mouths, but inwardly they utter curses. (Selah)'
EXEC add_BibleVerse @BibleId, 119062005, N'Patiently wait for God alone, my soul! For he is the one who gives me confidence.'
EXEC add_BibleVerse @BibleId, 119062006, N'He alone is my protector and deliverer. He is my refuge; I will not be upended.'
EXEC add_BibleVerse @BibleId, 119062007, N'God delivers me and exalts me; God is my strong protector and my shelter.'
EXEC add_BibleVerse @BibleId, 119062008, N'Trust in him at all times, you people! Pour out your hearts before him! God is our shelter! (Selah)'
EXEC add_BibleVerse @BibleId, 119062009, N'Men are nothing but a mere breath; human beings are unreliable. When they are weighed in the scales, all of them together are lighter than air.'
EXEC add_BibleVerse @BibleId, 119062010, N'Do not trust in what you can gain by oppression! Do not put false confidence in what you can gain by robbery! If wealth increases, do not become attached to it!'
EXEC add_BibleVerse @BibleId, 119062011, N'God has declared one principle; two principles I have heard: God is strong,'
EXEC add_BibleVerse @BibleId, 119062012, N'and you, O Lord, demonstrate loyal love. For you repay men for what they do.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119063001, @markup=N'O God, you are my God! I long for you! My soul thirsts for you, my flesh yearns for you, in a dry and parched land where there is no water. ', @premarkup=N'A psalm of David, written when he was in the Judean wilderness.'
EXEC add_BibleVerse @BibleId, 119063002, N'Yes, in the sanctuary I have seen you, and witnessed your power and splendor.'
EXEC add_BibleVerse @BibleId, 119063003, N'Because experiencing your loyal love is better than life itself, my lips will praise you.'
EXEC add_BibleVerse @BibleId, 119063004, N'For this reason I will praise you while I live; in your name I will lift up my hands.'
EXEC add_BibleVerse @BibleId, 119063005, N'As if with choice meat you satisfy my soul. My mouth joyfully praises you,'
EXEC add_BibleVerse @BibleId, 119063006, N'whenever I remember you on my bed, and think about you during the nighttime hours.'
EXEC add_BibleVerse @BibleId, 119063007, N'For you are my deliverer; under your wings I rejoice.'
EXEC add_BibleVerse @BibleId, 119063008, N'My soul pursues you; your right hand upholds me.'
EXEC add_BibleVerse @BibleId, 119063009, N'Enemies seek to destroy my life, but they will descend into the depths of the earth.'
EXEC add_BibleVerse @BibleId, 119063010, N'Each one will be handed over to the sword; their corpses will be eaten by jackals.'
EXEC add_BibleVerse @BibleId, 119063011, N'But the king will rejoice in God; everyone who takes oaths in his name will boast, for the mouths of those who speak lies will be shut up.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119064001, @markup=N'Listen to me, O God, as I offer my lament! Protect my life from the enemy’s terrifying attacks. ', @premarkup=N'For the music director; a psalm of David.'
EXEC add_BibleVerse @BibleId, 119064002, N'Hide me from the plots of evil men, from the crowd of evildoers.'
EXEC add_BibleVerse @BibleId, 119064003, N'They sharpen their tongues like a sword; they aim their arrow, a slanderous charge,'
EXEC add_BibleVerse @BibleId, 119064004, N'in order to shoot down the innocent in secluded places. They shoot at him suddenly and are unafraid of retaliation.'
EXEC add_BibleVerse @BibleId, 119064005, N'They encourage one another to carry out their evil deed. They plan how to hide snares, and boast, “Who will see them?”'
EXEC add_BibleVerse @BibleId, 119064006, N'They devise unjust schemes; they disguise a well-conceived plot. Man’s inner thoughts cannot be discovered.'
EXEC add_BibleVerse @BibleId, 119064007, N'But God will shoot at them; suddenly they will be wounded by an arrow.'
EXEC add_BibleVerse @BibleId, 119064008, N'Their slander will bring about their demise. All who see them will shudder,'
EXEC add_BibleVerse @BibleId, 119064009, N'and all people will fear. They will proclaim what God has done, and reflect on his deeds.'
EXEC add_BibleVerse @BibleId, 119064010, N'The godly will rejoice in the Lord and take shelter in him. All the morally upright will boast.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119065001, @markup=N'Praise awaits you, O God, in Zion. Vows made to you are fulfilled. ', @premarkup=N'For the music director; a psalm of David, a song.'
EXEC add_BibleVerse @BibleId, 119065002, N'You hear prayers; all people approach you.'
EXEC add_BibleVerse @BibleId, 119065003, N'Our record of sins overwhelms me, but you forgive our acts of rebellion.'
EXEC add_BibleVerse @BibleId, 119065004, N'How blessed is the one whom you choose, and allow to live in your palace courts. May we be satisfied with the good things of your house – your holy palace.'
EXEC add_BibleVerse @BibleId, 119065005, N'You answer our prayers by performing awesome acts of deliverance, O God, our savior. All the ends of the earth trust in you, as well as those living across the wide seas.'
EXEC add_BibleVerse @BibleId, 119065006, N'You created the mountains by your power, and demonstrated your strength.'
EXEC add_BibleVerse @BibleId, 119065007, N'You calm the raging seas and their roaring waves, as well as the commotion made by the nations.'
EXEC add_BibleVerse @BibleId, 119065008, N'Even those living in the most remote areas are awestruck by your acts; you cause those living in the east and west to praise you.'
EXEC add_BibleVerse @BibleId, 119065009, N'You visit the earth and give it rain; you make it rich and fertile with overflowing streams full of water. You provide grain for them, for you prepare the earth to yield its crops.'
EXEC add_BibleVerse @BibleId, 119065010, N'You saturate its furrows, and soak its plowed ground. With rain showers you soften its soil, and make its crops grow.'
EXEC add_BibleVerse @BibleId, 119065011, N'You crown the year with your good blessings, and you leave abundance in your wake.'
EXEC add_BibleVerse @BibleId, 119065012, N'The pastures in the wilderness glisten with moisture, and the hills are clothed with joy.'
EXEC add_BibleVerse @BibleId, 119065013, N'The meadows are clothed with sheep, and the valleys are covered with grain. They shout joyfully, yes, they sing.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119066001, @markup=N'Shout out praise to God, all the earth! ', @premarkup=N'For the music director; a song, a psalm.'
EXEC add_BibleVerse @BibleId, 119066002, N'Sing praises about the majesty of his reputation! Give him the honor he deserves!'
EXEC add_BibleVerse @BibleId, 119066003, N'Say to God: “How awesome are your deeds! Because of your great power your enemies cower in fear before you.'
EXEC add_BibleVerse @BibleId, 119066004, N'All the earth worships you and sings praises to you! They sing praises to your name!” (Selah)'
EXEC add_BibleVerse @BibleId, 119066005, N'Come and witness God’s exploits! His acts on behalf of people are awesome!'
EXEC add_BibleVerse @BibleId, 119066006, N'He turned the sea into dry land; they passed through the river on foot. Let us rejoice in him there!'
EXEC add_BibleVerse @BibleId, 119066007, N'He rules by his power forever; he watches the nations. Stubborn rebels should not exalt themselves. (Selah)'
EXEC add_BibleVerse @BibleId, 119066008, N'Praise our God, you nations! Loudly proclaim his praise!'
EXEC add_BibleVerse @BibleId, 119066009, N'He preserves our lives and does not allow our feet to slip.'
EXEC add_BibleVerse @BibleId, 119066010, N'For you, O God, tested us; you purified us like refined silver.'
EXEC add_BibleVerse @BibleId, 119066011, N'You led us into a trap; you caused us to suffer.'
EXEC add_BibleVerse @BibleId, 119066012, N'You allowed men to ride over our heads; we passed through fire and water, but you brought us out into a wide open place.'
EXEC add_BibleVerse @BibleId, 119066013, N'I will enter your temple with burnt sacrifices; I will fulfill the vows I made to you,'
EXEC add_BibleVerse @BibleId, 119066014, N'which my lips uttered and my mouth spoke when I was in trouble.'
EXEC add_BibleVerse @BibleId, 119066015, N'I will offer up to you fattened animals as burnt sacrifices, along with the smell of sacrificial rams. I will offer cattle and goats. (Selah)'
EXEC add_BibleVerse @BibleId, 119066016, N'Come! Listen, all you who are loyal to God! I will declare what he has done for me.'
EXEC add_BibleVerse @BibleId, 119066017, N'I cried out to him for help and praised him with my tongue.'
EXEC add_BibleVerse @BibleId, 119066018, N'If I had harbored sin in my heart, the Lord would not have listened.'
EXEC add_BibleVerse @BibleId, 119066019, N'However, God heard; he listened to my prayer.'
EXEC add_BibleVerse @BibleId, 119066020, N'God deserves praise, for he did not reject my prayer or abandon his love for me!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119067001, @markup=N'May God show us his favor and bless us! May he smile on us! (Selah) ', @premarkup=N'For the music director; to be accompanied by stringed instruments; a psalm, a song.'
EXEC add_BibleVerse @BibleId, 119067002, N'Then those living on earth will know what you are like; all nations will know how you deliver your people.'
EXEC add_BibleVerse @BibleId, 119067003, N'Let the nations thank you, O God! Let all the nations thank you!'
EXEC add_BibleVerse @BibleId, 119067004, N'Let foreigners rejoice and celebrate! For you execute justice among the nations, and govern the people living on earth. (Selah)'
EXEC add_BibleVerse @BibleId, 119067005, N'Let the nations thank you, O God! Let all the nations thank you!'
EXEC add_BibleVerse @BibleId, 119067006, N'The earth yields its crops. May God, our God, bless us!'
EXEC add_BibleVerse @BibleId, 119067007, N'May God bless us! Then all the ends of the earth will give him the honor he deserves.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119068001, @markup=N'God springs into action! His enemies scatter; his adversaries run from him. ', @premarkup=N'For the music director; by David, a psalm, a song.'
EXEC add_BibleVerse @BibleId, 119068002, N'As smoke is driven away by the wind, so you drive them away. As wax melts before fire, so the wicked are destroyed before God.'
EXEC add_BibleVerse @BibleId, 119068003, N'But the godly are happy; they rejoice before God and are overcome with joy.'
EXEC add_BibleVerse @BibleId, 119068004, N'Sing to God! Sing praises to his name! Exalt the one who rides on the clouds! For the Lord is his name! Rejoice before him!'
EXEC add_BibleVerse @BibleId, 119068005, N'He is a father to the fatherless and an advocate for widows. God rules from his holy palace.'
EXEC add_BibleVerse @BibleId, 119068006, N'God settles those who have been deserted in their own homes; he frees prisoners and grants them prosperity. But sinful rebels live in the desert.'
EXEC add_BibleVerse @BibleId, 119068007, N'O God, when you lead your people into battle, when you march through the desert, (Selah)'
EXEC add_BibleVerse @BibleId, 119068008, N'the earth shakes, yes, the heavens pour down rain before God, the God of Sinai, before God, the God of Israel.'
EXEC add_BibleVerse @BibleId, 119068009, N'O God, you cause abundant showers to fall on your chosen people. When they are tired, you sustain them,'
EXEC add_BibleVerse @BibleId, 119068010, N'for you live among them. You sustain the oppressed with your good blessings, O God.'
EXEC add_BibleVerse @BibleId, 119068011, N'The Lord speaks; many, many women spread the good news.'
EXEC add_BibleVerse @BibleId, 119068012, N'Kings leading armies run away – they run away! The lovely lady of the house divides up the loot.'
EXEC add_BibleVerse @BibleId, 119068013, N'When you lie down among the sheepfolds, the wings of the dove are covered with silver and with glittering gold.'
EXEC add_BibleVerse @BibleId, 119068014, N'When the sovereign judge scatters kings, let it snow on Zalmon!'
EXEC add_BibleVerse @BibleId, 119068015, N'The mountain of Bashan is a towering mountain; the mountain of Bashan is a mountain with many peaks.'
EXEC add_BibleVerse @BibleId, 119068016, N'Why do you look with envy, O mountains with many peaks, at the mountain where God has decided to live? Indeed the Lord will live there permanently!'
EXEC add_BibleVerse @BibleId, 119068017, N'God has countless chariots; they number in the thousands. The Lord comes from Sinai in holy splendor.'
EXEC add_BibleVerse @BibleId, 119068018, N'You ascend on high, you have taken many captives. You receive tribute from men, including even sinful rebels. Indeed the Lord God lives there!'
EXEC add_BibleVerse @BibleId, 119068019, N'The Lord deserves praise! Day after day he carries our burden, the God who delivers us. (Selah)'
EXEC add_BibleVerse @BibleId, 119068020, N'Our God is a God who delivers; the Lord, the sovereign Lord, can rescue from death.'
EXEC add_BibleVerse @BibleId, 119068021, N'Indeed God strikes the heads of his enemies, the hairy foreheads of those who persist in rebellion.'
EXEC add_BibleVerse @BibleId, 119068022, N'The Lord says, “I will retrieve them from Bashan, I will bring them back from the depths of the sea,'
EXEC add_BibleVerse @BibleId, 119068023, N'so that your feet may stomp in their blood, and your dogs may eat their portion of the enemies’ corpses.”'
EXEC add_BibleVerse @BibleId, 119068024, N'They see your processions, O God – the processions of my God, my king, who marches along in holy splendor.'
EXEC add_BibleVerse @BibleId, 119068025, N'Singers walk in front; musicians follow playing their stringed instruments, in the midst of young women playing tambourines.'
EXEC add_BibleVerse @BibleId, 119068026, N'In your large assemblies praise God, the Lord, in the assemblies of Israel!'
EXEC add_BibleVerse @BibleId, 119068027, N'There is little Benjamin, their ruler, and the princes of Judah in their robes, along with the princes of Zebulun and the princes of Naphtali.'
EXEC add_BibleVerse @BibleId, 119068028, N'God has decreed that you will be powerful. O God, you who have acted on our behalf, demonstrate your power,'
EXEC add_BibleVerse @BibleId, 119068029, N'as you come out of your temple in Jerusalem! Kings bring tribute to you.'
EXEC add_BibleVerse @BibleId, 119068030, N'Sound your battle cry against the wild beast of the reeds, and the nations that assemble like a herd of calves led by bulls! They humble themselves and offer gold and silver as tribute. God scatters the nations that like to do battle.'
EXEC add_BibleVerse @BibleId, 119068031, N'They come with red cloth from Egypt, Ethiopia voluntarily offers tribute to God.'
EXEC add_BibleVerse @BibleId, 119068032, N'O kingdoms of the earth, sing to God! Sing praises to the Lord, (Selah)'
EXEC add_BibleVerse @BibleId, 119068033, N'to the one who rides through the sky from ancient times! Look! He thunders loudly.'
EXEC add_BibleVerse @BibleId, 119068034, N'Acknowledge God’s power, his sovereignty over Israel, and the power he reveals in the skies!'
EXEC add_BibleVerse @BibleId, 119068035, N'You are awe-inspiring, O God, as you emerge from your holy temple! It is the God of Israel who gives the people power and strength. God deserves praise!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119069001, @markup=N'Deliver me, O God, for the water has reached my neck. ', @premarkup=N'For the music director; according to the tune of “Lilies;” by David.'
EXEC add_BibleVerse @BibleId, 119069002, N'I sink into the deep mire where there is no solid ground; I am in deep water, and the current overpowers me.'
EXEC add_BibleVerse @BibleId, 119069003, N'I am exhausted from shouting for help; my throat is sore; my eyes grow tired of looking for my God.'
EXEC add_BibleVerse @BibleId, 119069004, N'Those who hate me without cause are more numerous than the hairs of my head. Those who want to destroy me, my enemies for no reason, outnumber me. They make me repay what I did not steal!'
EXEC add_BibleVerse @BibleId, 119069005, N'O God, you are aware of my foolish sins; my guilt is not hidden from you.'
EXEC add_BibleVerse @BibleId, 119069006, N'Let none who rely on you be disgraced because of me, O sovereign Lord and king! Let none who seek you be ashamed because of me, O God of Israel!'
EXEC add_BibleVerse @BibleId, 119069007, N'For I suffer humiliation for your sake and am thoroughly disgraced.'
EXEC add_BibleVerse @BibleId, 119069008, N'My own brothers treat me like a stranger; they act as if I were a foreigner.'
EXEC add_BibleVerse @BibleId, 119069009, N'Certainly zeal for your house consumes me; I endure the insults of those who insult you.'
EXEC add_BibleVerse @BibleId, 119069010, N'I weep and refrain from eating food, which causes others to insult me.'
EXEC add_BibleVerse @BibleId, 119069011, N'I wear sackcloth and they ridicule me.'
EXEC add_BibleVerse @BibleId, 119069012, N'Those who sit at the city gate gossip about me; drunkards mock me in their songs.'
EXEC add_BibleVerse @BibleId, 119069013, N'O Lord, may you hear my prayer and be favorably disposed to me! O God, because of your great loyal love, answer me with your faithful deliverance!'
EXEC add_BibleVerse @BibleId, 119069014, N'Rescue me from the mud! Don’t let me sink! Deliver me from those who hate me, from the deep water!'
EXEC add_BibleVerse @BibleId, 119069015, N'Don’t let the current overpower me! Don’t let the deep swallow me up! Don’t let the pit devour me!'
EXEC add_BibleVerse @BibleId, 119069016, N'Answer me, O Lord, for your loyal love is good! Because of your great compassion, turn toward me!'
EXEC add_BibleVerse @BibleId, 119069017, N'Do not ignore your servant, for I am in trouble! Answer me right away!'
EXEC add_BibleVerse @BibleId, 119069018, N'Come near me and redeem me! Because of my enemies, rescue me!'
EXEC add_BibleVerse @BibleId, 119069019, N'You know how I am insulted, humiliated and disgraced; you can see all my enemies.'
EXEC add_BibleVerse @BibleId, 119069020, N'Their insults are painful and make me lose heart; I look for sympathy, but receive none, for comforters, but find none.'
EXEC add_BibleVerse @BibleId, 119069021, N'They put bitter poison into my food, and to quench my thirst they give me vinegar to drink.'
EXEC add_BibleVerse @BibleId, 119069022, N'May their dining table become a trap before them! May it be a snare for that group of friends!'
EXEC add_BibleVerse @BibleId, 119069023, N'May their eyes be blinded! Make them shake violently!'
EXEC add_BibleVerse @BibleId, 119069024, N'Pour out your judgment on them! May your raging anger overtake them!'
EXEC add_BibleVerse @BibleId, 119069025, N'May their camp become desolate, their tents uninhabited!'
EXEC add_BibleVerse @BibleId, 119069026, N'For they harass the one whom you discipline; they spread the news about the suffering of those whom you punish.'
EXEC add_BibleVerse @BibleId, 119069027, N'Hold them accountable for all their sins! Do not vindicate them!'
EXEC add_BibleVerse @BibleId, 119069028, N'May their names be deleted from the scroll of the living! Do not let their names be listed with the godly!'
EXEC add_BibleVerse @BibleId, 119069029, N'I am oppressed and suffering! O God, deliver and protect me!'
EXEC add_BibleVerse @BibleId, 119069030, N'I will sing praises to God’s name! I will magnify him as I give him thanks!'
EXEC add_BibleVerse @BibleId, 119069031, N'That will please the Lord more than an ox or a bull with horns and hooves.'
EXEC add_BibleVerse @BibleId, 119069032, N'The oppressed look on – let them rejoice! You who seek God, may you be encouraged!'
EXEC add_BibleVerse @BibleId, 119069033, N'For the Lord listens to the needy; he does not despise his captive people.'
EXEC add_BibleVerse @BibleId, 119069034, N'Let the heavens and the earth praise him, along with the seas and everything that swims in them!'
EXEC add_BibleVerse @BibleId, 119069035, N'For God will deliver Zion and rebuild the cities of Judah, and his people will again live in them and possess Zion.'
EXEC add_BibleVerse @BibleId, 119069036, N'The descendants of his servants will inherit it, and those who are loyal to him will live in it.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119070001, @markup=N'O God, please be willing to rescue me! O Lord, hurry and help me! ', @premarkup=N'For the music director; by David; written to get God’s attention.'
EXEC add_BibleVerse @BibleId, 119070002, N'May those who are trying to take my life be embarrassed and ashamed! May those who want to harm me be turned back and ashamed!'
EXEC add_BibleVerse @BibleId, 119070003, N'May those who say, “Aha! Aha!” be driven back and disgraced!'
EXEC add_BibleVerse @BibleId, 119070004, N'May all those who seek you be happy and rejoice in you! May those who love to experience your deliverance say continually, “May God be praised!”'
EXEC add_BibleVerse @BibleId, 119070005, N'I am oppressed and needy! O God, hurry to me! You are my helper and my deliverer! O Lord, do not delay!'
EXEC add_BibleVerse @BibleId, 119071001, N'In you, O Lord, I have taken shelter! Never let me be humiliated!'
EXEC add_BibleVerse @BibleId, 119071002, N'Vindicate me by rescuing me! Listen to me! Deliver me!'
EXEC add_BibleVerse @BibleId, 119071003, N'Be my protector and refuge, a stronghold where I can be safe! For you are my high ridge and my stronghold.'
EXEC add_BibleVerse @BibleId, 119071004, N'My God, rescue me from the power of the wicked, from the hand of the cruel oppressor!'
EXEC add_BibleVerse @BibleId, 119071005, N'For you give me confidence, O Lord; O Lord, I have trusted in you since I was young.'
EXEC add_BibleVerse @BibleId, 119071006, N'I have leaned on you since birth; you pulled me from my mother’s womb. I praise you continually.'
EXEC add_BibleVerse @BibleId, 119071007, N'Many are appalled when they see me, but you are my secure shelter.'
EXEC add_BibleVerse @BibleId, 119071008, N'I praise you constantly and speak of your splendor all day long.'
EXEC add_BibleVerse @BibleId, 119071009, N'Do not reject me in my old age! When my strength fails, do not abandon me!'
EXEC add_BibleVerse @BibleId, 119071010, N'For my enemies talk about me; those waiting for a chance to kill me plot my demise.'
EXEC add_BibleVerse @BibleId, 119071011, N'They say, “God has abandoned him. Run and seize him, for there is no one who will rescue him!”'
EXEC add_BibleVerse @BibleId, 119071012, N'O God, do not remain far away from me! My God, hurry and help me!'
EXEC add_BibleVerse @BibleId, 119071013, N'May my accusers be humiliated and defeated! May those who want to harm me be covered with scorn and disgrace!'
EXEC add_BibleVerse @BibleId, 119071014, N'As for me, I will wait continually, and will continue to praise you.'
EXEC add_BibleVerse @BibleId, 119071015, N'I will tell about your justice, and all day long proclaim your salvation, though I cannot fathom its full extent.'
EXEC add_BibleVerse @BibleId, 119071016, N'I will come and tell about the mighty acts of the sovereign Lord. I will proclaim your justice – yours alone.'
EXEC add_BibleVerse @BibleId, 119071017, N'O God, you have taught me since I was young, and I am still declaring your amazing deeds.'
EXEC add_BibleVerse @BibleId, 119071018, N'Even when I am old and gray, O God, do not abandon me, until I tell the next generation about your strength, and those coming after me about your power.'
EXEC add_BibleVerse @BibleId, 119071019, N'Your justice, O God, extends to the skies above; you have done great things. O God, who can compare to you?'
EXEC add_BibleVerse @BibleId, 119071020, N'Though you have allowed me to experience much trouble and distress, revive me once again! Bring me up once again from the depths of the earth!'
EXEC add_BibleVerse @BibleId, 119071021, N'Raise me to a position of great honor! Turn and comfort me!'
EXEC add_BibleVerse @BibleId, 119071022, N'I will express my thanks to you with a stringed instrument, praising your faithfulness, O my God! I will sing praises to you accompanied by a harp, O Holy One of Israel!'
EXEC add_BibleVerse @BibleId, 119071023, N'My lips will shout for joy! Yes, I will sing your praises! I will praise you when you rescue me!'
EXEC add_BibleVerse @BibleId, 119071024, N'All day long my tongue will also tell about your justice, for those who want to harm me will be embarrassed and ashamed.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119072001, @markup=N'O God, grant the king the ability to make just decisions! Grant the king’s son the ability to make fair decisions! ', @premarkup=N'For Solomon.'
EXEC add_BibleVerse @BibleId, 119072002, N'Then he will judge your people fairly, and your oppressed ones equitably.'
EXEC add_BibleVerse @BibleId, 119072003, N'The mountains will bring news of peace to the people, and the hills will announce justice.'
EXEC add_BibleVerse @BibleId, 119072004, N'He will defend the oppressed among the people; he will deliver the children of the poor and crush the oppressor.'
EXEC add_BibleVerse @BibleId, 119072005, N'People will fear you as long as the sun and moon remain in the sky, for generation after generation.'
EXEC add_BibleVerse @BibleId, 119072006, N'He will descend like rain on the mown grass, like showers that drench the earth.'
EXEC add_BibleVerse @BibleId, 119072007, N'During his days the godly will flourish; peace will prevail as long as the moon remains in the sky.'
EXEC add_BibleVerse @BibleId, 119072008, N'May he rule from sea to sea, and from the Euphrates River to the ends of the earth!'
EXEC add_BibleVerse @BibleId, 119072009, N'Before him the coastlands will bow down, and his enemies will lick the dust.'
EXEC add_BibleVerse @BibleId, 119072010, N'The kings of Tarshish and the coastlands will offer gifts; the kings of Sheba and Seba will bring tribute.'
EXEC add_BibleVerse @BibleId, 119072011, N'All kings will bow down to him; all nations will serve him.'
EXEC add_BibleVerse @BibleId, 119072012, N'For he will rescue the needy when they cry out for help, and the oppressed who have no defender.'
EXEC add_BibleVerse @BibleId, 119072013, N'He will take pity on the poor and needy; the lives of the needy he will save.'
EXEC add_BibleVerse @BibleId, 119072014, N'From harm and violence he will defend them; he will value their lives.'
EXEC add_BibleVerse @BibleId, 119072015, N'May he live! May they offer him gold from Sheba! May they continually pray for him! May they pronounce blessings on him all day long!'
EXEC add_BibleVerse @BibleId, 119072016, N'May there be an abundance of grain in the earth; on the tops of the mountains may it sway! May its fruit trees flourish like the forests of Lebanon! May its crops be as abundant as the grass of the earth!'
EXEC add_BibleVerse @BibleId, 119072017, N'May his fame endure! May his dynasty last as long as the sun remains in the sky! May they use his name when they formulate their blessings! May all nations consider him to be favored by God!'
EXEC add_BibleVerse @BibleId, 119072018, N'The Lord God, the God of Israel, deserves praise! He alone accomplishes amazing things!'
EXEC add_BibleVerse @BibleId, 119072019, N'His glorious name deserves praise forevermore! May his majestic splendor fill the whole earth! We agree! We agree!'
EXEC add_BibleVerse @BibleId, 119072020, N'This collection of the prayers of David son of Jesse ends here.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119073001, @markup=N'Certainly God is good to Israel, and to those whose motives are pure! ', @premarkup=N'A psalm by Asaph.'
EXEC add_BibleVerse @BibleId, 119073002, N'But as for me, my feet almost slipped; my feet almost slid out from under me.'
EXEC add_BibleVerse @BibleId, 119073003, N'For I envied those who are proud, as I observed the prosperity of the wicked.'
EXEC add_BibleVerse @BibleId, 119073004, N'For they suffer no pain; their bodies are strong and well-fed.'
EXEC add_BibleVerse @BibleId, 119073005, N'They are immune to the trouble common to men; they do not suffer as other men do.'
EXEC add_BibleVerse @BibleId, 119073006, N'Arrogance is their necklace, and violence their clothing.'
EXEC add_BibleVerse @BibleId, 119073007, N'Their prosperity causes them to do wrong; their thoughts are sinful.'
EXEC add_BibleVerse @BibleId, 119073008, N'They mock and say evil things; they proudly threaten violence.'
EXEC add_BibleVerse @BibleId, 119073009, N'They speak as if they rule in heaven, and lay claim to the earth.'
EXEC add_BibleVerse @BibleId, 119073010, N'Therefore they have more than enough food to eat, and even suck up the water of the sea.'
EXEC add_BibleVerse @BibleId, 119073011, N'They say, “How does God know what we do? Is the sovereign one aware of what goes on?”'
EXEC add_BibleVerse @BibleId, 119073012, N'Take a good look! This is what the wicked are like, those who always have it so easy and get richer and richer.'
EXEC add_BibleVerse @BibleId, 119073013, N'I concluded, “Surely in vain I have kept my motives pure and maintained a pure lifestyle.'
EXEC add_BibleVerse @BibleId, 119073014, N'I suffer all day long, and am punished every morning.”'
EXEC add_BibleVerse @BibleId, 119073015, N'If I had publicized these thoughts, I would have betrayed your loyal followers.'
EXEC add_BibleVerse @BibleId, 119073016, N'When I tried to make sense of this, it was troubling to me.'
EXEC add_BibleVerse @BibleId, 119073017, N'Then I entered the precincts of God’s temple, and understood the destiny of the wicked.'
EXEC add_BibleVerse @BibleId, 119073018, N'Surely you put them in slippery places; you bring them down to ruin.'
EXEC add_BibleVerse @BibleId, 119073019, N'How desolate they become in a mere moment! Terrifying judgments make their demise complete!'
EXEC add_BibleVerse @BibleId, 119073020, N'They are like a dream after one wakes up. O Lord, when you awake you will despise them.'
EXEC add_BibleVerse @BibleId, 119073021, N'Yes, my spirit was bitter, and my insides felt sharp pain.'
EXEC add_BibleVerse @BibleId, 119073022, N'I was ignorant and lacked insight; I was as senseless as an animal before you.'
EXEC add_BibleVerse @BibleId, 119073023, N'But I am continually with you; you hold my right hand.'
EXEC add_BibleVerse @BibleId, 119073024, N'You guide me by your wise advice, and then you will lead me to a position of honor.'
EXEC add_BibleVerse @BibleId, 119073025, N'Whom do I have in heaven but you? I desire no one but you on earth.'
EXEC add_BibleVerse @BibleId, 119073026, N'My flesh and my heart may grow weak, but God always protects my heart and gives me stability.'
EXEC add_BibleVerse @BibleId, 119073027, N'Yes, look! Those far from you die; you destroy everyone who is unfaithful to you.'
EXEC add_BibleVerse @BibleId, 119073028, N'But as for me, God’s presence is all I need. I have made the sovereign Lord my shelter, as I declare all the things you have done.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119074001, @markup=N'Why, O God, have you permanently rejected us? Why does your anger burn against the sheep of your pasture? ', @premarkup=N'A well-written song by Asaph.'
EXEC add_BibleVerse @BibleId, 119074002, N'Remember your people whom you acquired in ancient times, whom you rescued so they could be your very own nation, as well as Mount Zion, where you dwell!'
EXEC add_BibleVerse @BibleId, 119074003, N'Hurry and look at the permanent ruins, and all the damage the enemy has done to the temple!'
EXEC add_BibleVerse @BibleId, 119074004, N'Your enemies roar in the middle of your sanctuary; they set up their battle flags.'
EXEC add_BibleVerse @BibleId, 119074005, N'They invade like lumberjacks swinging their axes in a thick forest.'
EXEC add_BibleVerse @BibleId, 119074006, N'And now they are tearing down all its engravings with axes and crowbars.'
EXEC add_BibleVerse @BibleId, 119074007, N'They set your sanctuary on fire; they desecrate your dwelling place by knocking it to the ground.'
EXEC add_BibleVerse @BibleId, 119074008, N'They say to themselves, “We will oppress all of them.” They burn down all the places where people worship God in the land.'
EXEC add_BibleVerse @BibleId, 119074009, N'We do not see any signs of God’s presence; there are no longer any prophets and we have no one to tell us how long this will last.'
EXEC add_BibleVerse @BibleId, 119074010, N'How long, O God, will the adversary hurl insults? Will the enemy blaspheme your name forever?'
EXEC add_BibleVerse @BibleId, 119074011, N'Why do you remain inactive? Intervene and destroy him!'
EXEC add_BibleVerse @BibleId, 119074012, N'But God has been my king from ancient times, performing acts of deliverance on the earth.'
EXEC add_BibleVerse @BibleId, 119074013, N'You destroyed the sea by your strength; you shattered the heads of the sea monster in the water.'
EXEC add_BibleVerse @BibleId, 119074014, N'You crushed the heads of Leviathan; you fed him to the people who live along the coast.'
EXEC add_BibleVerse @BibleId, 119074015, N'You broke open the spring and the stream; you dried up perpetually flowing rivers.'
EXEC add_BibleVerse @BibleId, 119074016, N'You established the cycle of day and night; you put the moon and sun in place.'
EXEC add_BibleVerse @BibleId, 119074017, N'You set up all the boundaries of the earth; you created the cycle of summer and winter.'
EXEC add_BibleVerse @BibleId, 119074018, N'Remember how the enemy hurls insults, O Lord, and how a foolish nation blasphemes your name!'
EXEC add_BibleVerse @BibleId, 119074019, N'Do not hand the life of your dove over to a wild animal! Do not continue to disregard the lives of your oppressed people!'
EXEC add_BibleVerse @BibleId, 119074020, N'Remember your covenant promises, for the dark regions of the earth are full of places where violence rules.'
EXEC add_BibleVerse @BibleId, 119074021, N'Do not let the afflicted be turned back in shame! Let the oppressed and poor praise your name!'
EXEC add_BibleVerse @BibleId, 119074022, N'Rise up, O God! Defend your honor! Remember how fools insult you all day long!'
EXEC add_BibleVerse @BibleId, 119074023, N'Do not disregard what your enemies say, or the unceasing shouts of those who defy you.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119075001, @markup=N'We give thanks to you, O God! We give thanks! You reveal your presence; people tell about your amazing deeds. ', @premarkup=N'For the music director; according to the al-tashcheth style; a psalm of Asaph; a song.'
EXEC add_BibleVerse @BibleId, 119075002, N'God says, “At the appointed times, I judge fairly.'
EXEC add_BibleVerse @BibleId, 119075003, N'When the earth and all its inhabitants dissolve in fear, I make its pillars secure.” (Selah)'
EXEC add_BibleVerse @BibleId, 119075004, N'I say to the proud, “Do not be proud,” and to the wicked, “Do not be so confident of victory!'
EXEC add_BibleVerse @BibleId, 119075005, N'Do not be so certain you have won! Do not speak with your head held so high!'
EXEC add_BibleVerse @BibleId, 119075006, N'For victory does not come from the east or west, or from the wilderness.'
EXEC add_BibleVerse @BibleId, 119075007, N'For God is the judge! He brings one down and exalts another.'
EXEC add_BibleVerse @BibleId, 119075008, N'For the Lord holds in his hand a cup full of foaming wine mixed with spices, and pours it out. Surely all the wicked of the earth will slurp it up and drink it to its very last drop.”'
EXEC add_BibleVerse @BibleId, 119075009, N'As for me, I will continually tell what you have done; I will sing praises to the God of Jacob!'
EXEC add_BibleVerse @BibleId, 119075010, N'God says, “I will bring down all the power of the wicked; the godly will be victorious.”'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119076001, @markup=N'God has revealed himself in Judah; in Israel his reputation is great. ', @premarkup=N'For the music director; to be accompanied by stringed instruments; a psalm of Asaph, a song.'
EXEC add_BibleVerse @BibleId, 119076002, N'He lives in Salem; he dwells in Zion.'
EXEC add_BibleVerse @BibleId, 119076003, N'There he shattered the arrows, the shield, the sword, and the rest of the weapons of war. (Selah)'
EXEC add_BibleVerse @BibleId, 119076004, N'You shine brightly and reveal your majesty, as you descend from the hills where you killed your prey.'
EXEC add_BibleVerse @BibleId, 119076005, N'The bravehearted were plundered; they “fell asleep.” All the warriors were helpless.'
EXEC add_BibleVerse @BibleId, 119076006, N'At the sound of your battle cry, O God of Jacob, both rider and horse “fell asleep.”'
EXEC add_BibleVerse @BibleId, 119076007, N'You are awesome! Yes, you! Who can withstand your intense anger?'
EXEC add_BibleVerse @BibleId, 119076008, N'From heaven you announced what their punishment would be. The earth was afraid and silent'
EXEC add_BibleVerse @BibleId, 119076009, N'when God arose to execute judgment, and to deliver all the oppressed of the earth. (Selah)'
EXEC add_BibleVerse @BibleId, 119076010, N'Certainly your angry judgment upon men will bring you praise; you reveal your anger in full measure.'
EXEC add_BibleVerse @BibleId, 119076011, N'Make vows to the Lord your God and repay them! Let all those who surround him bring tribute to the awesome one!'
EXEC add_BibleVerse @BibleId, 119076012, N'He humbles princes; the kings of the earth regard him as awesome.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119077001, @markup=N'I will cry out to God and call for help! I will cry out to God and he will pay attention to me. ', @premarkup=N'For the music director, Jeduthun; a psalm of Asaph.'
EXEC add_BibleVerse @BibleId, 119077002, N'In my time of trouble I sought the Lord. I kept my hand raised in prayer throughout the night. I refused to be comforted.'
EXEC add_BibleVerse @BibleId, 119077003, N'I said, “I will remember God while I groan; I will think about him while my strength leaves me.” (Selah)'
EXEC add_BibleVerse @BibleId, 119077004, N'You held my eyelids open; I was troubled and could not speak.'
EXEC add_BibleVerse @BibleId, 119077005, N'I thought about the days of old, about ancient times.'
EXEC add_BibleVerse @BibleId, 119077006, N'I said, “During the night I will remember the song I once sang; I will think very carefully.” I tried to make sense of what was happening.'
EXEC add_BibleVerse @BibleId, 119077007, N'I asked, “Will the Lord reject me forever? Will he never again show me his favor?'
EXEC add_BibleVerse @BibleId, 119077008, N'Has his loyal love disappeared forever? Has his promise failed forever?'
EXEC add_BibleVerse @BibleId, 119077009, N'Has God forgotten to be merciful? Has his anger stifled his compassion?”'
EXEC add_BibleVerse @BibleId, 119077010, N'Then I said, “I am sickened by the thought that the sovereign One might become inactive.'
EXEC add_BibleVerse @BibleId, 119077011, N'I will remember the works of the Lord. Yes, I will remember the amazing things you did long ago!'
EXEC add_BibleVerse @BibleId, 119077012, N'I will think about all you have done; I will reflect upon your deeds!”'
EXEC add_BibleVerse @BibleId, 119077013, N'O God, your deeds are extraordinary! What god can compare to our great God?'
EXEC add_BibleVerse @BibleId, 119077014, N'You are the God who does amazing things; you have revealed your strength among the nations.'
EXEC add_BibleVerse @BibleId, 119077015, N'You delivered your people by your strength – the children of Jacob and Joseph. (Selah)'
EXEC add_BibleVerse @BibleId, 119077016, N'The waters saw you, O God, the waters saw you and trembled. Yes, the depths of the sea shook with fear.'
EXEC add_BibleVerse @BibleId, 119077017, N'The clouds poured down rain; the skies thundered. Yes, your arrows flashed about.'
EXEC add_BibleVerse @BibleId, 119077018, N'Your thunderous voice was heard in the wind; the lightning bolts lit up the world; the earth trembled and shook.'
EXEC add_BibleVerse @BibleId, 119077019, N'You walked through the sea; you passed through the surging waters, but left no footprints.'
EXEC add_BibleVerse @BibleId, 119077020, N'You led your people like a flock of sheep, by the hand of Moses and Aaron.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119078001, @markup=N'Pay attention, my people, to my instruction! Listen to the words I speak! ', @premarkup=N'A well-written song by Asaph.'
EXEC add_BibleVerse @BibleId, 119078002, N'I will sing a song that imparts wisdom; I will make insightful observations about the past.'
EXEC add_BibleVerse @BibleId, 119078003, N'What we have heard and learned – that which our ancestors have told us –'
EXEC add_BibleVerse @BibleId, 119078004, N'we will not hide from their descendants. We will tell the next generation about the Lord’s praiseworthy acts, about his strength and the amazing things he has done.'
EXEC add_BibleVerse @BibleId, 119078005, N'He established a rule in Jacob; he set up a law in Israel. He commanded our ancestors to make his deeds known to their descendants,'
EXEC add_BibleVerse @BibleId, 119078006, N'so that the next generation, children yet to be born, might know about them. They will grow up and tell their descendants about them.'
EXEC add_BibleVerse @BibleId, 119078007, N'Then they will place their confidence in God. They will not forget the works of God, and they will obey his commands.'
EXEC add_BibleVerse @BibleId, 119078008, N'Then they will not be like their ancestors, who were a stubborn and rebellious generation, a generation that was not committed and faithful to God.'
EXEC add_BibleVerse @BibleId, 119078009, N'The Ephraimites were armed with bows, but they retreated in the day of battle.'
EXEC add_BibleVerse @BibleId, 119078010, N'They did not keep their covenant with God, and they refused to obey his law.'
EXEC add_BibleVerse @BibleId, 119078011, N'They forgot what he had done, the amazing things he had shown them.'
EXEC add_BibleVerse @BibleId, 119078012, N'He did amazing things in the sight of their ancestors, in the land of Egypt, in the region of Zoan.'
EXEC add_BibleVerse @BibleId, 119078013, N'He divided the sea and led them across it; he made the water stand in a heap.'
EXEC add_BibleVerse @BibleId, 119078014, N'He led them with a cloud by day, and with the light of a fire all night long.'
EXEC add_BibleVerse @BibleId, 119078015, N'He broke open rocks in the wilderness, and gave them enough water to fill the depths of the sea.'
EXEC add_BibleVerse @BibleId, 119078016, N'He caused streams to flow from the rock, and made the water flow like rivers.'
EXEC add_BibleVerse @BibleId, 119078017, N'Yet they continued to sin against him, and rebelled against the sovereign One in the desert.'
EXEC add_BibleVerse @BibleId, 119078018, N'They willfully challenged God by asking for food to satisfy their appetite.'
EXEC add_BibleVerse @BibleId, 119078019, N'They insulted God, saying, “Is God really able to give us food in the wilderness?'
EXEC add_BibleVerse @BibleId, 119078020, N'Yes, he struck a rock and water flowed out, streams gushed forth. But can he also give us food? Will he provide meat for his people?”'
EXEC add_BibleVerse @BibleId, 119078021, N'When the Lord heard this, he was furious. A fire broke out against Jacob, and his anger flared up against Israel,'
EXEC add_BibleVerse @BibleId, 119078022, N'because they did not have faith in God, and did not trust his ability to deliver them.'
EXEC add_BibleVerse @BibleId, 119078023, N'He gave a command to the clouds above, and opened the doors in the sky.'
EXEC add_BibleVerse @BibleId, 119078024, N'He rained down manna for them to eat; he gave them the grain of heaven.'
EXEC add_BibleVerse @BibleId, 119078025, N'Man ate the food of the mighty ones. He sent them more than enough to eat.'
EXEC add_BibleVerse @BibleId, 119078026, N'He brought the east wind through the sky, and by his strength led forth the south wind.'
EXEC add_BibleVerse @BibleId, 119078027, N'He rained down meat on them like dust, birds as numerous as the sand on the seashores.'
EXEC add_BibleVerse @BibleId, 119078028, N'He caused them to fall right in the middle of their camp, all around their homes.'
EXEC add_BibleVerse @BibleId, 119078029, N'They ate until they were stuffed; he gave them what they desired.'
EXEC add_BibleVerse @BibleId, 119078030, N'They were not yet filled up, their food was still in their mouths,'
EXEC add_BibleVerse @BibleId, 119078031, N'when the anger of God flared up against them. He killed some of the strongest of them; he brought the young men of Israel to their knees.'
EXEC add_BibleVerse @BibleId, 119078032, N'Despite all this, they continued to sin, and did not trust him to do amazing things.'
EXEC add_BibleVerse @BibleId, 119078033, N'So he caused them to die unsatisfied and filled with terror.'
EXEC add_BibleVerse @BibleId, 119078034, N'When he struck them down, they sought his favor; they turned back and longed for God.'
EXEC add_BibleVerse @BibleId, 119078035, N'They remembered that God was their protector, and that the sovereign God was their deliverer.'
EXEC add_BibleVerse @BibleId, 119078036, N'But they deceived him with their words, and lied to him.'
EXEC add_BibleVerse @BibleId, 119078037, N'They were not really committed to him, and they were unfaithful to his covenant.'
EXEC add_BibleVerse @BibleId, 119078038, N'Yet he is compassionate. He forgives sin and does not destroy. He often holds back his anger, and does not stir up his fury.'
EXEC add_BibleVerse @BibleId, 119078039, N'He remembered that they were made of flesh, and were like a wind that blows past and does not return.'
EXEC add_BibleVerse @BibleId, 119078040, N'How often they rebelled against him in the wilderness, and insulted him in the desert!'
EXEC add_BibleVerse @BibleId, 119078041, N'They again challenged God, and offended the Holy One of Israel.'
EXEC add_BibleVerse @BibleId, 119078042, N'They did not remember what he had done, how he delivered them from the enemy,'
EXEC add_BibleVerse @BibleId, 119078043, N'when he performed his awesome deeds in Egypt, and his acts of judgment in the region of Zoan.'
EXEC add_BibleVerse @BibleId, 119078044, N'He turned their rivers into blood, and they could not drink from their streams.'
EXEC add_BibleVerse @BibleId, 119078045, N'He sent swarms of biting insects against them, as well as frogs that overran their land.'
EXEC add_BibleVerse @BibleId, 119078046, N'He gave their crops to the grasshopper, the fruit of their labor to the locust.'
EXEC add_BibleVerse @BibleId, 119078047, N'He destroyed their vines with hail, and their sycamore-fig trees with driving rain.'
EXEC add_BibleVerse @BibleId, 119078048, N'He rained hail down on their cattle, and hurled lightning bolts down on their livestock.'
EXEC add_BibleVerse @BibleId, 119078049, N'His raging anger lashed out against them, He sent fury, rage, and trouble as messengers who bring disaster.'
EXEC add_BibleVerse @BibleId, 119078050, N'He sent his anger in full force; he did not spare them from death; he handed their lives over to destruction.'
EXEC add_BibleVerse @BibleId, 119078051, N'He struck down all the firstborn in Egypt, the firstfruits of their reproductive power in the tents of Ham.'
EXEC add_BibleVerse @BibleId, 119078052, N'Yet he brought out his people like sheep; he led them through the wilderness like a flock.'
EXEC add_BibleVerse @BibleId, 119078053, N'He guided them safely along, while the sea covered their enemies.'
EXEC add_BibleVerse @BibleId, 119078054, N'He brought them to the border of his holy land, to this mountainous land which his right hand acquired.'
EXEC add_BibleVerse @BibleId, 119078055, N'He drove the nations out from before them; he assigned them their tribal allotments and allowed the tribes of Israel to settle down.'
EXEC add_BibleVerse @BibleId, 119078056, N'Yet they challenged and defied the sovereign God, and did not obey his commands.'
EXEC add_BibleVerse @BibleId, 119078057, N'They were unfaithful and acted as treacherously as their ancestors; they were as unreliable as a malfunctioning bow.'
EXEC add_BibleVerse @BibleId, 119078058, N'They made him angry with their pagan shrines, and made him jealous with their idols.'
EXEC add_BibleVerse @BibleId, 119078059, N'God heard and was angry; he completely rejected Israel.'
EXEC add_BibleVerse @BibleId, 119078060, N'He abandoned the sanctuary at Shiloh, the tent where he lived among men.'
EXEC add_BibleVerse @BibleId, 119078061, N'He allowed the symbol of his strong presence to be captured; he gave the symbol of his splendor into the hand of the enemy.'
EXEC add_BibleVerse @BibleId, 119078062, N'He delivered his people over to the sword, and was angry with his chosen nation.'
EXEC add_BibleVerse @BibleId, 119078063, N'Fire consumed their young men, and their virgins remained unmarried.'
EXEC add_BibleVerse @BibleId, 119078064, N'Their priests fell by the sword, but their widows did not weep.'
EXEC add_BibleVerse @BibleId, 119078065, N'But then the Lord awoke from his sleep; he was like a warrior in a drunken rage.'
EXEC add_BibleVerse @BibleId, 119078066, N'He drove his enemies back; he made them a permanent target for insults.'
EXEC add_BibleVerse @BibleId, 119078067, N'He rejected the tent of Joseph; he did not choose the tribe of Ephraim.'
EXEC add_BibleVerse @BibleId, 119078068, N'He chose the tribe of Judah, and Mount Zion, which he loves.'
EXEC add_BibleVerse @BibleId, 119078069, N'He made his sanctuary as enduring as the heavens above; as secure as the earth, which he established permanently.'
EXEC add_BibleVerse @BibleId, 119078070, N'He chose David, his servant, and took him from the sheepfolds.'
EXEC add_BibleVerse @BibleId, 119078071, N'He took him away from following the mother sheep, and made him the shepherd of Jacob, his people, and of Israel, his chosen nation.'
EXEC add_BibleVerse @BibleId, 119078072, N'David cared for them with pure motives; he led them with skill.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119079001, @markup=N'O God, foreigners have invaded your chosen land; they have polluted your holy temple and turned Jerusalem into a heap of ruins. ', @premarkup=N'A Psalm of Asaph.'
EXEC add_BibleVerse @BibleId, 119079002, N'They have given the corpses of your servants to the birds of the sky; the flesh of your loyal followers to the beasts of the earth.'
EXEC add_BibleVerse @BibleId, 119079003, N'They have made their blood flow like water all around Jerusalem, and there is no one to bury them.'
EXEC add_BibleVerse @BibleId, 119079004, N'We have become an object of disdain to our neighbors; those who live on our borders taunt and insult us.'
EXEC add_BibleVerse @BibleId, 119079005, N'How long will this go on, O Lord? Will you stay angry forever? How long will your rage burn like fire?'
EXEC add_BibleVerse @BibleId, 119079006, N'Pour out your anger on the nations that do not acknowledge you, on the kingdoms that do not pray to you!'
EXEC add_BibleVerse @BibleId, 119079007, N'For they have devoured Jacob and destroyed his home.'
EXEC add_BibleVerse @BibleId, 119079008, N'Do not hold us accountable for the sins of earlier generations! Quickly send your compassion our way, for we are in serious trouble!'
EXEC add_BibleVerse @BibleId, 119079009, N'Help us, O God, our deliverer! For the sake of your glorious reputation, rescue us! Forgive our sins for the sake of your reputation!'
EXEC add_BibleVerse @BibleId, 119079010, N'Why should the nations say, “Where is their God?” Before our very eyes may the shed blood of your servants be avenged among the nations!'
EXEC add_BibleVerse @BibleId, 119079011, N'Listen to the painful cries of the prisoners! Use your great strength to set free those condemned to die!'
EXEC add_BibleVerse @BibleId, 119079012, N'Pay back our neighbors in full! May they be insulted the same way they insulted you, O Lord!'
EXEC add_BibleVerse @BibleId, 119079013, N'Then we, your people, the sheep of your pasture, will continually thank you. We will tell coming generations of your praiseworthy acts.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119080001, @markup=N'O shepherd of Israel, pay attention, you who lead Joseph like a flock of sheep! You who sit enthroned above the winged angels, reveal your splendor! ', @premarkup=N'For the music director; according to the shushan-eduth style; a psalm of Asaph.'
EXEC add_BibleVerse @BibleId, 119080002, N'In the sight of Ephraim, Benjamin, and Manasseh reveal your power! Come and deliver us!'
EXEC add_BibleVerse @BibleId, 119080003, N'O God, restore us! Smile on us! Then we will be delivered!'
EXEC add_BibleVerse @BibleId, 119080004, N'O Lord God, invincible warrior! How long will you remain angry at your people while they pray to you?'
EXEC add_BibleVerse @BibleId, 119080005, N'You have given them tears as food; you have made them drink tears by the measure.'
EXEC add_BibleVerse @BibleId, 119080006, N'You have made our neighbors dislike us, and our enemies insult us.'
EXEC add_BibleVerse @BibleId, 119080007, N'O God, invincible warrior, restore us! Smile on us! Then we will be delivered!'
EXEC add_BibleVerse @BibleId, 119080008, N'You uprooted a vine from Egypt; you drove out nations and transplanted it.'
EXEC add_BibleVerse @BibleId, 119080009, N'You cleared the ground for it; it took root, and filled the land.'
EXEC add_BibleVerse @BibleId, 119080010, N'The mountains were covered by its shadow, the highest cedars by its branches.'
EXEC add_BibleVerse @BibleId, 119080011, N'Its branches reached the Mediterranean Sea, and its shoots the Euphrates River.'
EXEC add_BibleVerse @BibleId, 119080012, N'Why did you break down its walls, so that all who pass by pluck its fruit?'
EXEC add_BibleVerse @BibleId, 119080013, N'The wild boars of the forest ruin it; the insects of the field feed on it.'
EXEC add_BibleVerse @BibleId, 119080014, N'O God, invincible warrior, come back! Look down from heaven and take notice! Take care of this vine,'
EXEC add_BibleVerse @BibleId, 119080015, N'the root your right hand planted, the shoot you made to grow!'
EXEC add_BibleVerse @BibleId, 119080016, N'It is burned and cut down. They die because you are displeased with them.'
EXEC add_BibleVerse @BibleId, 119080017, N'May you give support to the one you have chosen, to the one whom you raised up for yourself!'
EXEC add_BibleVerse @BibleId, 119080018, N'Then we will not turn away from you. Revive us and we will pray to you!'
EXEC add_BibleVerse @BibleId, 119080019, N'O Lord God, invincible warrior, restore us! Smile on us! Then we will be delivered!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119081001, @markup=N'Shout for joy to God, our source of strength! Shout out to the God of Jacob! ', @premarkup=N'For the music director; according to the gittith style; by Asaph.'
EXEC add_BibleVerse @BibleId, 119081002, N'Sing a song and play the tambourine, the pleasant sounding harp, and the ten-stringed instrument!'
EXEC add_BibleVerse @BibleId, 119081003, N'Sound the ram’s horn on the day of the new moon, and on the day of the full moon when our festival begins.'
EXEC add_BibleVerse @BibleId, 119081004, N'For observing the festival is a requirement for Israel; it is an ordinance given by the God of Jacob.'
EXEC add_BibleVerse @BibleId, 119081005, N'He decreed it as a regulation in Joseph, when he attacked the land of Egypt. I heard a voice I did not recognize.'
EXEC add_BibleVerse @BibleId, 119081006, N'It said: “I removed the burden from his shoulder; his hands were released from holding the basket.'
EXEC add_BibleVerse @BibleId, 119081007, N'In your distress you called out and I rescued you. I answered you from a dark thundercloud. I tested you at the waters of Meribah. (Selah)'
EXEC add_BibleVerse @BibleId, 119081008, N'I said, ‘Listen, my people! I will warn you! O Israel, if only you would obey me!'
EXEC add_BibleVerse @BibleId, 119081009, N'There must be no other god among you. You must not worship a foreign god.'
EXEC add_BibleVerse @BibleId, 119081010, N'I am the Lord, your God, the one who brought you out of the land of Egypt. Open your mouth wide and I will fill it!’'
EXEC add_BibleVerse @BibleId, 119081011, N'But my people did not obey me; Israel did not submit to me.'
EXEC add_BibleVerse @BibleId, 119081012, N'I gave them over to their stubborn desires; they did what seemed right to them.'
EXEC add_BibleVerse @BibleId, 119081013, N'If only my people would obey me! If only Israel would keep my commands!'
EXEC add_BibleVerse @BibleId, 119081014, N'Then I would quickly subdue their enemies, and attack their adversaries.”'
EXEC add_BibleVerse @BibleId, 119081015, N'(May those who hate the Lord cower in fear before him! May they be permanently humiliated!)'
EXEC add_BibleVerse @BibleId, 119081016, N'“I would feed Israel the best wheat, and would satisfy your appetite with honey from the rocky cliffs.”'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119082001, @markup=N'God stands in the assembly of El; in the midst of the gods he renders judgment. ', @premarkup=N'A Psalm of Asaph.'
EXEC add_BibleVerse @BibleId, 119082002, N'He says, “How long will you make unjust legal decisions and show favoritism to the wicked? (Selah)'
EXEC add_BibleVerse @BibleId, 119082003, N'Defend the cause of the poor and the fatherless! Vindicate the oppressed and suffering!'
EXEC add_BibleVerse @BibleId, 119082004, N'Rescue the poor and needy! Deliver them from the power of the wicked!'
EXEC add_BibleVerse @BibleId, 119082005, N'They neither know nor understand. They stumble around in the dark, while all the foundations of the earth crumble.'
EXEC add_BibleVerse @BibleId, 119082006, N'I thought, ‘You are gods; all of you are sons of the Most High.’'
EXEC add_BibleVerse @BibleId, 119082007, N'Yet you will die like mortals; you will fall like all the other rulers.”'
EXEC add_BibleVerse @BibleId, 119082008, N'Rise up, O God, and execute judgment on the earth! For you own all the nations.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119083001, @markup=N'O God, do not be silent! Do not ignore us! Do not be inactive, O God! ', @premarkup=N'A song, a psalm of Asaph.'
EXEC add_BibleVerse @BibleId, 119083002, N'For look, your enemies are making a commotion; those who hate you are hostile.'
EXEC add_BibleVerse @BibleId, 119083003, N'They carefully plot against your people, and make plans to harm the ones you cherish.'
EXEC add_BibleVerse @BibleId, 119083004, N'They say, “Come on, let’s annihilate them so they are no longer a nation! Then the name of Israel will be remembered no more.”'
EXEC add_BibleVerse @BibleId, 119083005, N'Yes, they devise a unified strategy; they form an alliance against you.'
EXEC add_BibleVerse @BibleId, 119083006, N'It includes the tents of Edom and the Ishmaelites, Moab and the Hagrites,'
EXEC add_BibleVerse @BibleId, 119083007, N'Gebal, Ammon, and Amalek, Philistia and the inhabitants of Tyre.'
EXEC add_BibleVerse @BibleId, 119083008, N'Even Assyria has allied with them, lending its strength to the descendants of Lot. (Selah)'
EXEC add_BibleVerse @BibleId, 119083009, N'Do to them as you did to Midian – as you did to Sisera and Jabin at the Kishon River!'
EXEC add_BibleVerse @BibleId, 119083010, N'They were destroyed at Endor; their corpses were like manure on the ground.'
EXEC add_BibleVerse @BibleId, 119083011, N'Make their nobles like Oreb and Zeeb, and all their rulers like Zebah and Zalmunna,'
EXEC add_BibleVerse @BibleId, 119083012, N'who said, “Let’s take over the pastures of God!”'
EXEC add_BibleVerse @BibleId, 119083013, N'O my God, make them like dead thistles, like dead weeds blown away by the wind!'
EXEC add_BibleVerse @BibleId, 119083014, N'Like the fire that burns down the forest, or the flames that consume the mountainsides,'
EXEC add_BibleVerse @BibleId, 119083015, N'chase them with your gale winds, and terrify them with your windstorm.'
EXEC add_BibleVerse @BibleId, 119083016, N'Cover their faces with shame, so they might seek you, O Lord.'
EXEC add_BibleVerse @BibleId, 119083017, N'May they be humiliated and continually terrified! May they die in shame!'
EXEC add_BibleVerse @BibleId, 119083018, N'Then they will know that you alone are the Lord, the sovereign king over all the earth.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119084001, @markup=N'How lovely is the place where you live, O Lord who rules over all! ', @premarkup=N'For the music director; according to the gittith style; written by the Korahites, a psalm.'
EXEC add_BibleVerse @BibleId, 119084002, N'I desperately want to be in the courts of the Lord’s temple. My heart and my entire being shout for joy to the living God.'
EXEC add_BibleVerse @BibleId, 119084003, N'Even the birds find a home there, and the swallow builds a nest, where she can protect her young near your altars, O Lord who rules over all, my king and my God.'
EXEC add_BibleVerse @BibleId, 119084004, N'How blessed are those who live in your temple and praise you continually! (Selah)'
EXEC add_BibleVerse @BibleId, 119084005, N'How blessed are those who find their strength in you, and long to travel the roads that lead to your temple!'
EXEC add_BibleVerse @BibleId, 119084006, N'As they pass through the Baca Valley, he provides a spring for them. The rain even covers it with pools of water.'
EXEC add_BibleVerse @BibleId, 119084007, N'They are sustained as they travel along; each one appears before God in Zion.'
EXEC add_BibleVerse @BibleId, 119084008, N'O Lord, sovereign God, hear my prayer! Listen, O God of Jacob! (Selah)'
EXEC add_BibleVerse @BibleId, 119084009, N'O God, take notice of our shield! Show concern for your chosen king!'
EXEC add_BibleVerse @BibleId, 119084010, N'Certainly spending just one day in your temple courts is better than spending a thousand elsewhere. I would rather stand at the entrance to the temple of my God than live in the tents of the wicked.'
EXEC add_BibleVerse @BibleId, 119084011, N'For the Lord God is our sovereign protector. The Lord bestows favor and honor; he withholds no good thing from those who have integrity.'
EXEC add_BibleVerse @BibleId, 119084012, N'O Lord who rules over all, how blessed are those who trust in you!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119085001, @markup=N'O Lord, you showed favor to your land; you restored the well-being of Jacob. ', @premarkup=N'For the music director; written by the Korahites, a psalm.'
EXEC add_BibleVerse @BibleId, 119085002, N'You pardoned the wrongdoing of your people; you forgave all their sin. (Selah)'
EXEC add_BibleVerse @BibleId, 119085003, N'You withdrew all your fury; you turned back from your raging anger.'
EXEC add_BibleVerse @BibleId, 119085004, N'Restore us, O God our deliverer! Do not be displeased with us!'
EXEC add_BibleVerse @BibleId, 119085005, N'Will you stay mad at us forever? Will you remain angry throughout future generations?'
EXEC add_BibleVerse @BibleId, 119085006, N'Will you not revive us once more? Then your people will rejoice in you!'
EXEC add_BibleVerse @BibleId, 119085007, N'O Lord, show us your loyal love! Bestow on us your deliverance!'
EXEC add_BibleVerse @BibleId, 119085008, N'I will listen to what God the Lord says. For he will make peace with his people, his faithful followers. Yet they must not return to their foolish ways.'
EXEC add_BibleVerse @BibleId, 119085009, N'Certainly his loyal followers will soon experience his deliverance; then his splendor will again appear in our land.'
EXEC add_BibleVerse @BibleId, 119085010, N'Loyal love and faithfulness meet; deliverance and peace greet each other with a kiss.'
EXEC add_BibleVerse @BibleId, 119085011, N'Faithfulness grows from the ground, and deliverance looks down from the sky.'
EXEC add_BibleVerse @BibleId, 119085012, N'Yes, the Lord will bestow his good blessings, and our land will yield its crops.'
EXEC add_BibleVerse @BibleId, 119085013, N'Deliverance goes before him, and prepares a pathway for him.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119086001, @markup=N'Listen O Lord! Answer me! For I am oppressed and needy. ', @premarkup=N'A Prayer of David.'
EXEC add_BibleVerse @BibleId, 119086002, N'Protect me, for I am loyal! O my God, deliver your servant, who trusts in you!'
EXEC add_BibleVerse @BibleId, 119086003, N'Have mercy on me, O Lord, for I cry out to you all day long!'
EXEC add_BibleVerse @BibleId, 119086004, N'Make your servant glad, for to you, O Lord, I pray!'
EXEC add_BibleVerse @BibleId, 119086005, N'Certainly O Lord, you are kind and forgiving, and show great faithfulness to all who cry out to you.'
EXEC add_BibleVerse @BibleId, 119086006, N'O Lord, hear my prayer! Pay attention to my plea for mercy!'
EXEC add_BibleVerse @BibleId, 119086007, N'In my time of trouble I cry out to you, for you will answer me.'
EXEC add_BibleVerse @BibleId, 119086008, N'None can compare to you among the gods, O Lord! Your exploits are incomparable!'
EXEC add_BibleVerse @BibleId, 119086009, N'All the nations, whom you created, will come and worship you, O Lord. They will honor your name.'
EXEC add_BibleVerse @BibleId, 119086010, N'For you are great and do amazing things. You alone are God.'
EXEC add_BibleVerse @BibleId, 119086011, N'O Lord, teach me how you want me to live! Then I will obey your commands. Make me wholeheartedly committed to you!'
EXEC add_BibleVerse @BibleId, 119086012, N'O Lord, my God, I will give you thanks with my whole heart! I will honor your name continually!'
EXEC add_BibleVerse @BibleId, 119086013, N'For you will extend your great loyal love to me, and will deliver my life from the depths of Sheol.'
EXEC add_BibleVerse @BibleId, 119086014, N'O God, arrogant men attack me; a gang of ruthless men, who do not respect you, seek my life.'
EXEC add_BibleVerse @BibleId, 119086015, N'But you, O Lord, are a compassionate and merciful God. You are patient and demonstrate great loyal love and faithfulness.'
EXEC add_BibleVerse @BibleId, 119086016, N'Turn toward me and have mercy on me! Give your servant your strength! Deliver your slave!'
EXEC add_BibleVerse @BibleId, 119086017, N'Show me evidence of your favor! Then those who hate me will see it and be ashamed, for you, O Lord, will help me and comfort me.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119087001, @markup=N'The Lord’s city is in the holy hills. ', @premarkup=N'Written by the Korahites; a psalm, a song.'
EXEC add_BibleVerse @BibleId, 119087002, N'The Lord loves the gates of Zion more than all the dwelling places of Jacob.'
EXEC add_BibleVerse @BibleId, 119087003, N'People say wonderful things about you, O city of God. (Selah)'
EXEC add_BibleVerse @BibleId, 119087004, N'I mention Rahab and Babylon to my followers. Here are Philistia and Tyre, along with Ethiopia. It is said of them, “This one was born there.”'
EXEC add_BibleVerse @BibleId, 119087005, N'But it is said of Zion’s residents, “Each one of these was born in her, and the sovereign One makes her secure.”'
EXEC add_BibleVerse @BibleId, 119087006, N'The Lord writes in the census book of the nations, “This one was born there.” (Selah)'
EXEC add_BibleVerse @BibleId, 119087007, N'As for the singers, as well as the pipers – all of them sing within your walls.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119088001, @markup=N'O Lord God who delivers me! By day I cry out and at night I pray before you. ', @premarkup=N'A song, a psalm written by the Korahites; for the music director; according to the machalath-leannoth style; a well-written song by Heman the Ezrachite.'
EXEC add_BibleVerse @BibleId, 119088002, N'Listen to my prayer! Pay attention to my cry for help!'
EXEC add_BibleVerse @BibleId, 119088003, N'For my life is filled with troubles and I am ready to enter Sheol.'
EXEC add_BibleVerse @BibleId, 119088004, N'They treat me like those who descend into the grave. I am like a helpless man,'
EXEC add_BibleVerse @BibleId, 119088005, N'adrift among the dead, like corpses lying in the grave, whom you remember no more, and who are cut off from your power.'
EXEC add_BibleVerse @BibleId, 119088006, N'You place me in the lowest regions of the pit, in the dark places, in the watery depths.'
EXEC add_BibleVerse @BibleId, 119088007, N'Your anger bears down on me, and you overwhelm me with all your waves. (Selah)'
EXEC add_BibleVerse @BibleId, 119088008, N'You cause those who know me to keep their distance; you make me an appalling sight to them. I am trapped and cannot get free.'
EXEC add_BibleVerse @BibleId, 119088009, N'My eyes grow weak because of oppression. I call out to you, O Lord, all day long; I spread out my hands in prayer to you.'
EXEC add_BibleVerse @BibleId, 119088010, N'Do you accomplish amazing things for the dead? Do the departed spirits rise up and give you thanks? (Selah)'
EXEC add_BibleVerse @BibleId, 119088011, N'Is your loyal love proclaimed in the grave, or your faithfulness in the place of the dead?'
EXEC add_BibleVerse @BibleId, 119088012, N'Are your amazing deeds experienced in the dark region, or your deliverance in the land of oblivion?'
EXEC add_BibleVerse @BibleId, 119088013, N'As for me, I cry out to you, O Lord; in the morning my prayer confronts you.'
EXEC add_BibleVerse @BibleId, 119088014, N'O Lord, why do you reject me, and pay no attention to me?'
EXEC add_BibleVerse @BibleId, 119088015, N'I am oppressed and have been on the verge of death since my youth. I have been subjected to your horrors and am numb with pain.'
EXEC add_BibleVerse @BibleId, 119088016, N'Your anger overwhelms me; your terrors destroy me.'
EXEC add_BibleVerse @BibleId, 119088017, N'They surround me like water all day long; they join forces and encircle me.'
EXEC add_BibleVerse @BibleId, 119088018, N'You cause my friends and neighbors to keep their distance; those who know me leave me alone in the darkness.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119089001, @markup=N'I will sing continually about the Lord’s faithful deeds; to future generations I will proclaim your faithfulness. ', @premarkup=N'A well-written song by Ethan the Ezrachite.'
EXEC add_BibleVerse @BibleId, 119089002, N'For I say, “Loyal love is permanently established; in the skies you set up your faithfulness.”'
EXEC add_BibleVerse @BibleId, 119089003, N'The Lord said, “I have made a covenant with my chosen one; I have made a promise on oath to David, my servant:'
EXEC add_BibleVerse @BibleId, 119089004, N'‘I will give you an eternal dynasty and establish your throne throughout future generations.’” (Selah)'
EXEC add_BibleVerse @BibleId, 119089005, N'O Lord, the heavens praise your amazing deeds, as well as your faithfulness in the angelic assembly.'
EXEC add_BibleVerse @BibleId, 119089006, N'For who in the skies can compare to the Lord? Who is like the Lord among the heavenly beings,'
EXEC add_BibleVerse @BibleId, 119089007, N'a God who is honored in the great angelic assembly, and more awesome than all who surround him?'
EXEC add_BibleVerse @BibleId, 119089008, N'O Lord, sovereign God! Who is strong like you, O Lord? Your faithfulness surrounds you.'
EXEC add_BibleVerse @BibleId, 119089009, N'You rule over the proud sea. When its waves surge, you calm them.'
EXEC add_BibleVerse @BibleId, 119089010, N'You crushed the Proud One and killed it; with your strong arm you scattered your enemies.'
EXEC add_BibleVerse @BibleId, 119089011, N'The heavens belong to you, as does the earth. You made the world and all it contains.'
EXEC add_BibleVerse @BibleId, 119089012, N'You created the north and the south. Tabor and Hermon rejoice in your name.'
EXEC add_BibleVerse @BibleId, 119089013, N'Your arm is powerful, your hand strong, your right hand victorious.'
EXEC add_BibleVerse @BibleId, 119089014, N'Equity and justice are the foundation of your throne. Loyal love and faithfulness characterize your rule.'
EXEC add_BibleVerse @BibleId, 119089015, N'How blessed are the people who worship you! O Lord, they experience your favor.'
EXEC add_BibleVerse @BibleId, 119089016, N'They rejoice in your name all day long, and are vindicated by your justice.'
EXEC add_BibleVerse @BibleId, 119089017, N'For you give them splendor and strength. By your favor we are victorious.'
EXEC add_BibleVerse @BibleId, 119089018, N'For our shield belongs to the Lord, our king to the Holy One of Israel.'
EXEC add_BibleVerse @BibleId, 119089019, N'Then you spoke through a vision to your faithful followers and said: “I have energized a warrior; I have raised up a young man from the people.'
EXEC add_BibleVerse @BibleId, 119089020, N'I have discovered David, my servant. With my holy oil I have anointed him as king.'
EXEC add_BibleVerse @BibleId, 119089021, N'My hand will support him, and my arm will strengthen him.'
EXEC add_BibleVerse @BibleId, 119089022, N'No enemy will be able to exact tribute from him; a violent oppressor will not be able to humiliate him.'
EXEC add_BibleVerse @BibleId, 119089023, N'I will crush his enemies before him; I will strike down those who hate him.'
EXEC add_BibleVerse @BibleId, 119089024, N'He will experience my faithfulness and loyal love, and by my name he will win victories.'
EXEC add_BibleVerse @BibleId, 119089025, N'I will place his hand over the sea, his right hand over the rivers.'
EXEC add_BibleVerse @BibleId, 119089026, N'He will call out to me, ‘You are my father, my God, and the protector who delivers me.’'
EXEC add_BibleVerse @BibleId, 119089027, N'I will appoint him to be my firstborn son, the most exalted of the earth’s kings.'
EXEC add_BibleVerse @BibleId, 119089028, N'I will always extend my loyal love to him, and my covenant with him is secure.'
EXEC add_BibleVerse @BibleId, 119089029, N'I will give him an eternal dynasty, and make his throne as enduring as the skies above.'
EXEC add_BibleVerse @BibleId, 119089030, N'If his sons reject my law and disobey my regulations,'
EXEC add_BibleVerse @BibleId, 119089031, N'if they break my rules and do not keep my commandments,'
EXEC add_BibleVerse @BibleId, 119089032, N'I will punish their rebellion by beating them with a club, their sin by inflicting them with bruises.'
EXEC add_BibleVerse @BibleId, 119089033, N'But I will not remove my loyal love from him, nor be unfaithful to my promise.'
EXEC add_BibleVerse @BibleId, 119089034, N'I will not break my covenant or go back on what I promised.'
EXEC add_BibleVerse @BibleId, 119089035, N'Once and for all I have vowed by my own holiness, I will never deceive David.'
EXEC add_BibleVerse @BibleId, 119089036, N'His dynasty will last forever. His throne will endure before me, like the sun,'
EXEC add_BibleVerse @BibleId, 119089037, N'it will remain stable, like the moon, his throne will endure like the skies.” (Selah)'
EXEC add_BibleVerse @BibleId, 119089038, N'But you have spurned and rejected him; you are angry with your chosen king.'
EXEC add_BibleVerse @BibleId, 119089039, N'You have repudiated your covenant with your servant; you have thrown his crown to the ground.'
EXEC add_BibleVerse @BibleId, 119089040, N'You have broken down all his walls; you have made his strongholds a heap of ruins.'
EXEC add_BibleVerse @BibleId, 119089041, N'All who pass by have robbed him; he has become an object of disdain to his neighbors.'
EXEC add_BibleVerse @BibleId, 119089042, N'You have allowed his adversaries to be victorious, and all his enemies to rejoice.'
EXEC add_BibleVerse @BibleId, 119089043, N'You turn back his sword from the adversary, and have not sustained him in battle.'
EXEC add_BibleVerse @BibleId, 119089044, N'You have brought to an end his splendor, and have knocked his throne to the ground.'
EXEC add_BibleVerse @BibleId, 119089045, N'You have cut short his youth, and have covered him with shame. (Selah)'
EXEC add_BibleVerse @BibleId, 119089046, N'How long, O Lord, will this last? Will you remain hidden forever? Will your anger continue to burn like fire?'
EXEC add_BibleVerse @BibleId, 119089047, N'Take note of my brief lifespan! Why do you make all people so mortal?'
EXEC add_BibleVerse @BibleId, 119089048, N'No man can live on without experiencing death, or deliver his life from the power of Sheol. (Selah)'
EXEC add_BibleVerse @BibleId, 119089049, N'Where are your earlier faithful deeds, O Lord, the ones performed in accordance with your reliable oath to David?'
EXEC add_BibleVerse @BibleId, 119089050, N'Take note, O Lord, of the way your servants are taunted, and of how I must bear so many insults from people!'
EXEC add_BibleVerse @BibleId, 119089051, N'Your enemies, O Lord, hurl insults; they insult your chosen king as they dog his footsteps.'
EXEC add_BibleVerse @BibleId, 119089052, N'The Lord deserves praise forevermore! We agree! We agree!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119090001, @markup=N'O Lord, you have been our protector through all generations! ', @premarkup=N'A prayer of Moses, the man of God.'
EXEC add_BibleVerse @BibleId, 119090002, N'Even before the mountains came into existence, or you brought the world into being, you were the eternal God.'
EXEC add_BibleVerse @BibleId, 119090003, N'You make mankind return to the dust, and say, “Return, O people!”'
EXEC add_BibleVerse @BibleId, 119090004, N'Yes, in your eyes a thousand years are like yesterday that quickly passes, or like one of the divisions of the nighttime.'
EXEC add_BibleVerse @BibleId, 119090005, N'You bring their lives to an end and they “fall asleep.” In the morning they are like the grass that sprouts up;'
EXEC add_BibleVerse @BibleId, 119090006, N'in the morning it glistens and sprouts up; at evening time it withers and dries up.'
EXEC add_BibleVerse @BibleId, 119090007, N'Yes, we are consumed by your anger; we are terrified by your wrath.'
EXEC add_BibleVerse @BibleId, 119090008, N'You are aware of our sins; you even know about our hidden sins.'
EXEC add_BibleVerse @BibleId, 119090009, N'Yes, throughout all our days we experience your raging fury; the years of our lives pass quickly, like a sigh.'
EXEC add_BibleVerse @BibleId, 119090010, N'The days of our lives add up to seventy years, or eighty, if one is especially strong. But even one’s best years are marred by trouble and oppression. Yes, they pass quickly and we fly away.'
EXEC add_BibleVerse @BibleId, 119090011, N'Who can really fathom the intensity of your anger? Your raging fury causes people to fear you.'
EXEC add_BibleVerse @BibleId, 119090012, N'So teach us to consider our mortality, so that we might live wisely.'
EXEC add_BibleVerse @BibleId, 119090013, N'Turn back toward us, O Lord! How long must this suffering last? Have pity on your servants!'
EXEC add_BibleVerse @BibleId, 119090014, N'Satisfy us in the morning with your loyal love! Then we will shout for joy and be happy all our days!'
EXEC add_BibleVerse @BibleId, 119090015, N'Make us happy in proportion to the days you have afflicted us, in proportion to the years we have experienced trouble!'
EXEC add_BibleVerse @BibleId, 119090016, N'May your servants see your work! May their sons see your majesty!'
EXEC add_BibleVerse @BibleId, 119090017, N'May our sovereign God extend his favor to us! Make our endeavors successful! Yes, make them successful!'
EXEC add_BibleVerse @BibleId, 119091001, N'As for you, the one who lives in the shelter of the sovereign One, and resides in the protective shadow of the mighty king –'
EXEC add_BibleVerse @BibleId, 119091002, N'I say this about the Lord, my shelter and my stronghold, my God in whom I trust –'
EXEC add_BibleVerse @BibleId, 119091003, N'he will certainly rescue you from the snare of the hunter and from the destructive plague.'
EXEC add_BibleVerse @BibleId, 119091004, N'He will shelter you with his wings; you will find safety under his wings. His faithfulness is like a shield or a protective wall.'
EXEC add_BibleVerse @BibleId, 119091005, N'You need not fear the terrors of the night, the arrow that flies by day,'
EXEC add_BibleVerse @BibleId, 119091006, N'the plague that comes in the darkness, or the disease that comes at noon.'
EXEC add_BibleVerse @BibleId, 119091007, N'Though a thousand may fall beside you, and a multitude on your right side, it will not reach you.'
EXEC add_BibleVerse @BibleId, 119091008, N'Certainly you will see it with your very own eyes – you will see the wicked paid back.'
EXEC add_BibleVerse @BibleId, 119091009, N'For you have taken refuge in the Lord, my shelter, the sovereign One.'
EXEC add_BibleVerse @BibleId, 119091010, N'No harm will overtake you; no illness will come near your home.'
EXEC add_BibleVerse @BibleId, 119091011, N'For he will order his angels to protect you in all you do.'
EXEC add_BibleVerse @BibleId, 119091012, N'They will lift you up in their hands, so you will not slip and fall on a stone.'
EXEC add_BibleVerse @BibleId, 119091013, N'You will subdue a lion and a snake; you will trample underfoot a young lion and a serpent.'
EXEC add_BibleVerse @BibleId, 119091014, N'The Lord says, “Because he is devoted to me, I will deliver him; I will protect him because he is loyal to me.'
EXEC add_BibleVerse @BibleId, 119091015, N'When he calls out to me, I will answer him. I will be with him when he is in trouble; I will rescue him and bring him honor.'
EXEC add_BibleVerse @BibleId, 119091016, N'I will satisfy him with long life, and will let him see my salvation.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119092001, @markup=N'It is fitting to thank the Lord, and to sing praises to your name, O sovereign One! ', @premarkup=N'A psalm; a song for the Sabbath day.'
EXEC add_BibleVerse @BibleId, 119092002, N'It is fitting to proclaim your loyal love in the morning, and your faithfulness during the night,'
EXEC add_BibleVerse @BibleId, 119092003, N'to the accompaniment of a ten-stringed instrument and a lyre, to the accompaniment of the meditative tone of the harp.'
EXEC add_BibleVerse @BibleId, 119092004, N'For you, O Lord, have made me happy by your work. I will sing for joy because of what you have done.'
EXEC add_BibleVerse @BibleId, 119092005, N'How great are your works, O Lord! Your plans are very intricate!'
EXEC add_BibleVerse @BibleId, 119092006, N'The spiritually insensitive do not recognize this; the fool does not understand this.'
EXEC add_BibleVerse @BibleId, 119092007, N'When the wicked sprout up like grass, and all the evildoers glisten, it is so that they may be annihilated.'
EXEC add_BibleVerse @BibleId, 119092008, N'But you, O Lord, reign forever!'
EXEC add_BibleVerse @BibleId, 119092009, N'Indeed, look at your enemies, O Lord! Indeed, look at how your enemies perish! All the evildoers are scattered!'
EXEC add_BibleVerse @BibleId, 119092010, N'You exalt my horn like that of a wild ox. I am covered with fresh oil.'
EXEC add_BibleVerse @BibleId, 119092011, N'I gloat in triumph over those who tried to ambush me; I hear the defeated cries of the evil foes who attacked me.'
EXEC add_BibleVerse @BibleId, 119092012, N'The godly grow like a palm tree; they grow high like a cedar in Lebanon.'
EXEC add_BibleVerse @BibleId, 119092013, N'Planted in the Lord’s house, they grow in the courts of our God.'
EXEC add_BibleVerse @BibleId, 119092014, N'They bear fruit even when they are old; they are filled with vitality and have many leaves.'
EXEC add_BibleVerse @BibleId, 119092015, N'So they proclaim that the Lord, my protector, is just and never unfair.'
EXEC add_BibleVerse @BibleId, 119093001, N'The Lord reigns! He is robed in majesty, the Lord is robed, he wears strength around his waist. Indeed, the world is established, it cannot be moved.'
EXEC add_BibleVerse @BibleId, 119093002, N'Your throne has been secure from ancient times; you have always been king.'
EXEC add_BibleVerse @BibleId, 119093003, N'The waves roar, O Lord, the waves roar, the waves roar and crash.'
EXEC add_BibleVerse @BibleId, 119093004, N'Above the sound of the surging water, and the mighty waves of the sea, the Lord sits enthroned in majesty.'
EXEC add_BibleVerse @BibleId, 119093005, N'The rules you set down are completely reliable. Holiness aptly adorns your house, O Lord, forever.'
EXEC add_BibleVerse @BibleId, 119094001, N'O Lord, the God who avenges! O God who avenges, reveal your splendor!'
EXEC add_BibleVerse @BibleId, 119094002, N'Rise up, O judge of the earth! Pay back the proud!'
EXEC add_BibleVerse @BibleId, 119094003, N'O Lord, how long will the wicked, how long will the wicked celebrate?'
EXEC add_BibleVerse @BibleId, 119094004, N'They spew out threats and speak defiantly; all the evildoers boast.'
EXEC add_BibleVerse @BibleId, 119094005, N'O Lord, they crush your people; they oppress the nation that belongs to you.'
EXEC add_BibleVerse @BibleId, 119094006, N'They kill the widow and the one residing outside his native land, and they murder the fatherless.'
EXEC add_BibleVerse @BibleId, 119094007, N'Then they say, “The Lord does not see this; the God of Jacob does not take notice of it.”'
EXEC add_BibleVerse @BibleId, 119094008, N'Take notice of this, you ignorant people! You fools, when will you ever understand?'
EXEC add_BibleVerse @BibleId, 119094009, N'Does the one who makes the human ear not hear? Does the one who forms the human eye not see?'
EXEC add_BibleVerse @BibleId, 119094010, N'Does the one who disciplines the nations not punish? He is the one who imparts knowledge to human beings!'
EXEC add_BibleVerse @BibleId, 119094011, N'The Lord knows that peoples’ thoughts are morally bankrupt.'
EXEC add_BibleVerse @BibleId, 119094012, N'How blessed is the one whom you instruct, O Lord, the one whom you teach from your law,'
EXEC add_BibleVerse @BibleId, 119094013, N'in order to protect him from times of trouble, until the wicked are destroyed.'
EXEC add_BibleVerse @BibleId, 119094014, N'Certainly the Lord does not forsake his people; he does not abandon the nation that belongs to him.'
EXEC add_BibleVerse @BibleId, 119094015, N'For justice will prevail, and all the morally upright will be vindicated.'
EXEC add_BibleVerse @BibleId, 119094016, N'Who will rise up to defend me against the wicked? Who will stand up for me against the evildoers?'
EXEC add_BibleVerse @BibleId, 119094017, N'If the Lord had not helped me, I would have laid down in the silence of death.'
EXEC add_BibleVerse @BibleId, 119094018, N'If I say, “My foot is slipping,” your loyal love, O Lord, supports me.'
EXEC add_BibleVerse @BibleId, 119094019, N'When worries threaten to overwhelm me, your soothing touch makes me happy.'
EXEC add_BibleVerse @BibleId, 119094020, N'Cruel rulers are not your allies, those who make oppressive laws.'
EXEC add_BibleVerse @BibleId, 119094021, N'They conspire against the blameless, and condemn to death the innocent.'
EXEC add_BibleVerse @BibleId, 119094022, N'But the Lord will protect me, and my God will shelter me.'
EXEC add_BibleVerse @BibleId, 119094023, N'He will pay them back for their sin. He will destroy them because of their evil; the Lord our God will destroy them.'
EXEC add_BibleVerse @BibleId, 119095001, N'Come! Let’s sing for joy to the Lord! Let’s shout out praises to our protector who delivers us!'
EXEC add_BibleVerse @BibleId, 119095002, N'Let’s enter his presence with thanksgiving! Let’s shout out to him in celebration!'
EXEC add_BibleVerse @BibleId, 119095003, N'For the Lord is a great God, a great king who is superior to all gods.'
EXEC add_BibleVerse @BibleId, 119095004, N'The depths of the earth are in his hand, and the mountain peaks belong to him.'
EXEC add_BibleVerse @BibleId, 119095005, N'The sea is his, for he made it. His hands formed the dry land.'
EXEC add_BibleVerse @BibleId, 119095006, N'Come! Let’s bow down and worship! Let’s kneel before the Lord, our creator!'
EXEC add_BibleVerse @BibleId, 119095007, N'For he is our God; we are the people of his pasture, the sheep he owns. Today, if only you would obey him!'
EXEC add_BibleVerse @BibleId, 119095008, N'He says, “Do not be stubborn like they were at Meribah, like they were that day at Massah in the wilderness,'
EXEC add_BibleVerse @BibleId, 119095009, N'where your ancestors challenged my authority, and tried my patience, even though they had seen my work.'
EXEC add_BibleVerse @BibleId, 119095010, N'For forty years I was continually disgusted with that generation, and I said, ‘These people desire to go astray; they do not obey my commands.’'
EXEC add_BibleVerse @BibleId, 119095011, N'So I made a vow in my anger, ‘They will never enter into the resting place I had set aside for them.’”'
EXEC add_BibleVerse @BibleId, 119096001, N'Sing to the Lord a new song! Sing to the Lord, all the earth!'
EXEC add_BibleVerse @BibleId, 119096002, N'Sing to the Lord! Praise his name! Announce every day how he delivers!'
EXEC add_BibleVerse @BibleId, 119096003, N'Tell the nations about his splendor! Tell all the nations about his amazing deeds!'
EXEC add_BibleVerse @BibleId, 119096004, N'For the Lord is great and certainly worthy of praise; he is more awesome than all gods.'
EXEC add_BibleVerse @BibleId, 119096005, N'For all the gods of the nations are worthless, but the Lord made the sky.'
EXEC add_BibleVerse @BibleId, 119096006, N'Majestic splendor emanates from him; his sanctuary is firmly established and beautiful.'
EXEC add_BibleVerse @BibleId, 119096007, N'Ascribe to the Lord, O families of the nations, ascribe to the Lord splendor and strength!'
EXEC add_BibleVerse @BibleId, 119096008, N'Ascribe to the Lord the splendor he deserves! Bring an offering and enter his courts!'
EXEC add_BibleVerse @BibleId, 119096009, N'Worship the Lord in holy attire! Tremble before him, all the earth!'
EXEC add_BibleVerse @BibleId, 119096010, N'Say among the nations, “The Lord reigns! The world is established, it cannot be moved. He judges the nations fairly.”'
EXEC add_BibleVerse @BibleId, 119096011, N'Let the sky rejoice, and the earth be happy! Let the sea and everything in it shout!'
EXEC add_BibleVerse @BibleId, 119096012, N'Let the fields and everything in them celebrate! Then let the trees of the forest shout with joy'
EXEC add_BibleVerse @BibleId, 119096013, N'before the Lord, for he comes! For he comes to judge the earth! He judges the world fairly, and the nations in accordance with his justice.'
EXEC add_BibleVerse @BibleId, 119097001, N'The Lord reigns! Let the earth be happy! Let the many coastlands rejoice!'
EXEC add_BibleVerse @BibleId, 119097002, N'Dark clouds surround him; equity and justice are the foundation of his throne.'
EXEC add_BibleVerse @BibleId, 119097003, N'Fire goes before him; on every side it burns up his enemies.'
EXEC add_BibleVerse @BibleId, 119097004, N'His lightning bolts light up the world; the earth sees and trembles.'
EXEC add_BibleVerse @BibleId, 119097005, N'The mountains melt like wax before the Lord, before the Lord of the whole earth.'
EXEC add_BibleVerse @BibleId, 119097006, N'The sky declares his justice, and all the nations see his splendor.'
EXEC add_BibleVerse @BibleId, 119097007, N'All who worship idols are ashamed, those who boast about worthless idols. All the gods bow down before him.'
EXEC add_BibleVerse @BibleId, 119097008, N'Zion hears and rejoices, the towns of Judah are happy, because of your judgments, O Lord.'
EXEC add_BibleVerse @BibleId, 119097009, N'For you, O Lord, are the sovereign king over the whole earth; you are elevated high above all gods.'
EXEC add_BibleVerse @BibleId, 119097010, N'You who love the Lord, hate evil! He protects the lives of his faithful followers; he delivers them from the power of the wicked.'
EXEC add_BibleVerse @BibleId, 119097011, N'The godly bask in the light; the morally upright experience joy.'
EXEC add_BibleVerse @BibleId, 119097012, N'You godly ones, rejoice in the Lord! Give thanks to his holy name.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119098001, @markup=N'Sing to the Lord a new song, for he performs amazing deeds! His right hand and his mighty arm accomplish deliverance. ', @premarkup=N'A Psalm.'
EXEC add_BibleVerse @BibleId, 119098002, N'The Lord demonstrates his power to deliver; in the sight of the nations he reveals his justice.'
EXEC add_BibleVerse @BibleId, 119098003, N'He remains loyal and faithful to the family of Israel. All the ends of the earth see our God deliver us.'
EXEC add_BibleVerse @BibleId, 119098004, N'Shout out praises to the Lord, all the earth! Break out in a joyful shout and sing!'
EXEC add_BibleVerse @BibleId, 119098005, N'Sing to the Lord accompanied by a harp, accompanied by a harp and the sound of music!'
EXEC add_BibleVerse @BibleId, 119098006, N'With trumpets and the blaring of the ram’s horn, shout out praises before the king, the Lord!'
EXEC add_BibleVerse @BibleId, 119098007, N'Let the sea and everything in it shout, along with the world and those who live in it!'
EXEC add_BibleVerse @BibleId, 119098008, N'Let the rivers clap their hands! Let the mountains sing in unison'
EXEC add_BibleVerse @BibleId, 119098009, N'before the Lord! For he comes to judge the earth! He judges the world fairly, and the nations in a just manner.'
EXEC add_BibleVerse @BibleId, 119099001, N'The Lord reigns! The nations tremble. He sits enthroned above the winged angels; the earth shakes.'
EXEC add_BibleVerse @BibleId, 119099002, N'The Lord is elevated in Zion; he is exalted over all the nations.'
EXEC add_BibleVerse @BibleId, 119099003, N'Let them praise your great and awesome name! He is holy!'
EXEC add_BibleVerse @BibleId, 119099004, N'The king is strong; he loves justice. You ensure that legal decisions will be made fairly; you promote justice and equity in Jacob.'
EXEC add_BibleVerse @BibleId, 119099005, N'Praise the Lord our God! Worship before his footstool! He is holy!'
EXEC add_BibleVerse @BibleId, 119099006, N'Moses and Aaron were among his priests; Samuel was one of those who prayed to him. They prayed to the Lord and he answered them.'
EXEC add_BibleVerse @BibleId, 119099007, N'He spoke to them from a pillar of cloud; they obeyed his regulations and the ordinance he gave them.'
EXEC add_BibleVerse @BibleId, 119099008, N'O Lord our God, you answered them. They found you to be a forgiving God, but also one who punished their sinful deeds.'
EXEC add_BibleVerse @BibleId, 119099009, N'Praise the Lord our God! Worship on his holy hill, for the Lord our God is holy!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119100001, @markup=N'Shout out praises to the Lord, all the earth! ', @premarkup=N'A thanksgiving psalm.'
EXEC add_BibleVerse @BibleId, 119100002, N'Worship the Lord with joy! Enter his presence with joyful singing!'
EXEC add_BibleVerse @BibleId, 119100003, N'Acknowledge that the Lord is God! He made us and we belong to him; we are his people, the sheep of his pasture.'
EXEC add_BibleVerse @BibleId, 119100004, N'Enter his gates with thanksgiving, and his courts with praise! Give him thanks! Praise his name!'
EXEC add_BibleVerse @BibleId, 119100005, N'For the Lord is good. His loyal love endures, and he is faithful through all generations.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119101001, @markup=N'I will sing about loyalty and justice! To you, O Lord, I will sing praises! ', @premarkup=N'A Psalm of David.'
EXEC add_BibleVerse @BibleId, 119101002, N'I will walk in the way of integrity. When will you come to me? I will conduct my business with integrity in the midst of my palace.'
EXEC add_BibleVerse @BibleId, 119101003, N'I will not even consider doing what is dishonest. I hate doing evil; I will have no part of it.'
EXEC add_BibleVerse @BibleId, 119101004, N'I will have nothing to do with a perverse person; I will not permit evil.'
EXEC add_BibleVerse @BibleId, 119101005, N'I will destroy anyone who slanders his neighbor in secret. I will not tolerate anyone who has a cocky demeanor and an arrogant attitude.'
EXEC add_BibleVerse @BibleId, 119101006, N'I will favor the honest people of the land, and allow them to live with me. Those who walk in the way of integrity will attend me.'
EXEC add_BibleVerse @BibleId, 119101007, N'Deceitful people will not live in my palace. Liars will not be welcome in my presence.'
EXEC add_BibleVerse @BibleId, 119101008, N'Each morning I will destroy all the wicked people in the land, and remove all evildoers from the city of the Lord.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119102001, @markup=N'The prayer of an oppressed man, as he grows faint and pours out his lament before the Lord. O Lord, hear my prayer! Pay attention to my cry for help! ', @premarkup=N'A Prayer of the afflicted, when he is overwhelmed, and poureth out his complaint before the LORD.'
EXEC add_BibleVerse @BibleId, 119102002, N'Do not ignore me in my time of trouble! Listen to me! When I call out to you, quickly answer me!'
EXEC add_BibleVerse @BibleId, 119102003, N'For my days go up in smoke, and my bones are charred like a fireplace.'
EXEC add_BibleVerse @BibleId, 119102004, N'My heart is parched and withered like grass, for I am unable to eat food.'
EXEC add_BibleVerse @BibleId, 119102005, N'Because of the anxiety that makes me groan, my bones protrude from my skin.'
EXEC add_BibleVerse @BibleId, 119102006, N'I am like an owl in the wilderness; I am like a screech owl among the ruins.'
EXEC add_BibleVerse @BibleId, 119102007, N'I stay awake; I am like a solitary bird on a roof.'
EXEC add_BibleVerse @BibleId, 119102008, N'All day long my enemies taunt me; those who mock me use my name in their curses.'
EXEC add_BibleVerse @BibleId, 119102009, N'For I eat ashes as if they were bread, and mix my drink with my tears,'
EXEC add_BibleVerse @BibleId, 119102010, N'because of your anger and raging fury. Indeed, you pick me up and throw me away.'
EXEC add_BibleVerse @BibleId, 119102011, N'My days are coming to an end, and I am withered like grass.'
EXEC add_BibleVerse @BibleId, 119102012, N'But you, O Lord, rule forever, and your reputation endures.'
EXEC add_BibleVerse @BibleId, 119102013, N'You will rise up and have compassion on Zion. For it is time to have mercy on her, for the appointed time has come.'
EXEC add_BibleVerse @BibleId, 119102014, N'Indeed, your servants take delight in her stones, and feel compassion for the dust of her ruins.'
EXEC add_BibleVerse @BibleId, 119102015, N'The nations will respect the reputation of the Lord, and all the kings of the earth will respect his splendor,'
EXEC add_BibleVerse @BibleId, 119102016, N'when the Lord rebuilds Zion, and reveals his splendor,'
EXEC add_BibleVerse @BibleId, 119102017, N'when he responds to the prayer of the destitute, and does not reject their request.'
EXEC add_BibleVerse @BibleId, 119102018, N'The account of his intervention will be recorded for future generations; people yet to be born will praise the Lord.'
EXEC add_BibleVerse @BibleId, 119102019, N'For he will look down from his sanctuary above; from heaven the Lord will look toward earth,'
EXEC add_BibleVerse @BibleId, 119102020, N'in order to hear the painful cries of the prisoners, and to set free those condemned to die,'
EXEC add_BibleVerse @BibleId, 119102021, N'so they may proclaim the name of the Lord in Zion, and praise him in Jerusalem,'
EXEC add_BibleVerse @BibleId, 119102022, N'when the nations gather together, and the kingdoms pay tribute to the Lord.'
EXEC add_BibleVerse @BibleId, 119102023, N'He has taken away my strength in the middle of life; he has cut short my days.'
EXEC add_BibleVerse @BibleId, 119102024, N'I say, “O my God, please do not take me away in the middle of my life! You endure through all generations.'
EXEC add_BibleVerse @BibleId, 119102025, N'In earlier times you established the earth; the skies are your handiwork.'
EXEC add_BibleVerse @BibleId, 119102026, N'They will perish, but you will endure. They will wear out like a garment; like clothes you will remove them and they will disappear.'
EXEC add_BibleVerse @BibleId, 119102027, N'But you remain; your years do not come to an end.'
EXEC add_BibleVerse @BibleId, 119102028, N'The children of your servants will settle down here, and their descendants will live securely in your presence.”'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119103001, @markup=N'Praise the Lord, O my soul! With all that is within me, praise his holy name! ', @premarkup=N'By David.'
EXEC add_BibleVerse @BibleId, 119103002, N'Praise the Lord, O my soul! Do not forget all his kind deeds!'
EXEC add_BibleVerse @BibleId, 119103003, N'He is the one who forgives all your sins, who heals all your diseases,'
EXEC add_BibleVerse @BibleId, 119103004, N'who delivers your life from the Pit, who crowns you with his loyal love and compassion,'
EXEC add_BibleVerse @BibleId, 119103005, N'who satisfies your life with good things, so your youth is renewed like an eagle’s.'
EXEC add_BibleVerse @BibleId, 119103006, N'The Lord does what is fair, and executes justice for all the oppressed.'
EXEC add_BibleVerse @BibleId, 119103007, N'The Lord revealed his faithful acts to Moses, his deeds to the Israelites.'
EXEC add_BibleVerse @BibleId, 119103008, N'The Lord is compassionate and merciful; he is patient and demonstrates great loyal love.'
EXEC add_BibleVerse @BibleId, 119103009, N'He does not always accuse, and does not stay angry.'
EXEC add_BibleVerse @BibleId, 119103010, N'He does not deal with us as our sins deserve; he does not repay us as our misdeeds deserve.'
EXEC add_BibleVerse @BibleId, 119103011, N'For as the skies are high above the earth, so his loyal love towers over his faithful followers.'
EXEC add_BibleVerse @BibleId, 119103012, N'As far as the eastern horizon is from the west, so he removes the guilt of our rebellious actions from us.'
EXEC add_BibleVerse @BibleId, 119103013, N'As a father has compassion on his children, so the Lord has compassion on his faithful followers.'
EXEC add_BibleVerse @BibleId, 119103014, N'For he knows what we are made of; he realizes we are made of clay.'
EXEC add_BibleVerse @BibleId, 119103015, N'A person’s life is like grass. Like a flower in the field it flourishes,'
EXEC add_BibleVerse @BibleId, 119103016, N'but when the hot wind blows by, it disappears, and one can no longer even spot the place where it once grew.'
EXEC add_BibleVerse @BibleId, 119103017, N'But the Lord continually shows loyal love to his faithful followers, and is faithful to their descendants,'
EXEC add_BibleVerse @BibleId, 119103018, N'to those who keep his covenant, who are careful to obey his commands.'
EXEC add_BibleVerse @BibleId, 119103019, N'The Lord has established his throne in heaven; his kingdom extends over everything.'
EXEC add_BibleVerse @BibleId, 119103020, N'Praise the Lord, you angels of his, you powerful warriors who carry out his decrees and obey his orders!'
EXEC add_BibleVerse @BibleId, 119103021, N'Praise the Lord, all you warriors of his, you servants of his who carry out his desires!'
EXEC add_BibleVerse @BibleId, 119103022, N'Praise the Lord, all that he has made, in all the regions of his kingdom! Praise the Lord, O my soul!'
EXEC add_BibleVerse @BibleId, 119104001, N'Praise the Lord, O my soul! O Lord my God, you are magnificent. You are robed in splendor and majesty.'
EXEC add_BibleVerse @BibleId, 119104002, N'He covers himself with light as if it were a garment. He stretches out the skies like a tent curtain,'
EXEC add_BibleVerse @BibleId, 119104003, N'and lays the beams of the upper rooms of his palace on the rain clouds. He makes the clouds his chariot, and travels along on the wings of the wind.'
EXEC add_BibleVerse @BibleId, 119104004, N'He makes the winds his messengers, and the flaming fire his attendant.'
EXEC add_BibleVerse @BibleId, 119104005, N'He established the earth on its foundations; it will never be upended.'
EXEC add_BibleVerse @BibleId, 119104006, N'The watery deep covered it like a garment; the waters reached above the mountains.'
EXEC add_BibleVerse @BibleId, 119104007, N'Your shout made the waters retreat; at the sound of your thunderous voice they hurried off –'
EXEC add_BibleVerse @BibleId, 119104008, N'as the mountains rose up, and the valleys went down – to the place you appointed for them.'
EXEC add_BibleVerse @BibleId, 119104009, N'You set up a boundary for them that they could not cross, so that they would not cover the earth again.'
EXEC add_BibleVerse @BibleId, 119104010, N'He turns springs into streams; they flow between the mountains.'
EXEC add_BibleVerse @BibleId, 119104011, N'They provide water for all the animals in the field; the wild donkeys quench their thirst.'
EXEC add_BibleVerse @BibleId, 119104012, N'The birds of the sky live beside them; they chirp among the bushes.'
EXEC add_BibleVerse @BibleId, 119104013, N'He waters the mountains from the upper rooms of his palace; the earth is full of the fruit you cause to grow.'
EXEC add_BibleVerse @BibleId, 119104014, N'He provides grass for the cattle, and crops for people to cultivate, so they can produce food from the ground,'
EXEC add_BibleVerse @BibleId, 119104015, N'as well as wine that makes people feel so good, and so they can have oil to make their faces shine, as well as food that sustains people’s lives.'
EXEC add_BibleVerse @BibleId, 119104016, N'The trees of the Lord receive all the rain they need, the cedars of Lebanon which he planted,'
EXEC add_BibleVerse @BibleId, 119104017, N'where the birds make nests, near the evergreens in which the herons live.'
EXEC add_BibleVerse @BibleId, 119104018, N'The wild goats live in the high mountains; the rock badgers find safety in the cliffs.'
EXEC add_BibleVerse @BibleId, 119104019, N'He made the moon to mark the months, and the sun sets according to a regular schedule.'
EXEC add_BibleVerse @BibleId, 119104020, N'You make it dark and night comes, during which all the beasts of the forest prowl around.'
EXEC add_BibleVerse @BibleId, 119104021, N'The lions roar for prey, seeking their food from God.'
EXEC add_BibleVerse @BibleId, 119104022, N'When the sun rises, they withdraw and sleep in their dens.'
EXEC add_BibleVerse @BibleId, 119104023, N'Men then go out to do their work, and labor away until evening.'
EXEC add_BibleVerse @BibleId, 119104024, N'How many living things you have made, O Lord! You have exhibited great skill in making all of them; the earth is full of the living things you have made.'
EXEC add_BibleVerse @BibleId, 119104025, N'Over here is the deep, wide sea, which teems with innumerable swimming creatures, living things both small and large.'
EXEC add_BibleVerse @BibleId, 119104026, N'The ships travel there, and over here swims the whale you made to play in it.'
EXEC add_BibleVerse @BibleId, 119104027, N'All of your creatures wait for you to provide them with food on a regular basis.'
EXEC add_BibleVerse @BibleId, 119104028, N'You give food to them and they receive it; you open your hand and they are filled with food.'
EXEC add_BibleVerse @BibleId, 119104029, N'When you ignore them, they panic. When you take away their life’s breath, they die and return to dust.'
EXEC add_BibleVerse @BibleId, 119104030, N'When you send your life-giving breath, they are created, and you replenish the surface of the ground.'
EXEC add_BibleVerse @BibleId, 119104031, N'May the splendor of the Lord endure! May the Lord find pleasure in the living things he has made!'
EXEC add_BibleVerse @BibleId, 119104032, N'He looks down on the earth and it shakes; he touches the mountains and they start to smolder.'
EXEC add_BibleVerse @BibleId, 119104033, N'I will sing to the Lord as long as I live; I will sing praise to my God as long as I exist!'
EXEC add_BibleVerse @BibleId, 119104034, N'May my thoughts be pleasing to him! I will rejoice in the Lord.'
EXEC add_BibleVerse @BibleId, 119104035, N'May sinners disappear from the earth, and the wicked vanish! Praise the Lord, O my soul! Praise the Lord!'
EXEC add_BibleVerse @BibleId, 119105001, N'Give thanks to the Lord! Call on his name! Make known his accomplishments among the nations!'
EXEC add_BibleVerse @BibleId, 119105002, N'Sing to him! Make music to him! Tell about all his miraculous deeds!'
EXEC add_BibleVerse @BibleId, 119105003, N'Boast about his holy name! Let the hearts of those who seek the Lord rejoice!'
EXEC add_BibleVerse @BibleId, 119105004, N'Seek the Lord and the strength he gives! Seek his presence continually!'
EXEC add_BibleVerse @BibleId, 119105005, N'Recall the miraculous deeds he performed, his mighty acts and the judgments he decreed,'
EXEC add_BibleVerse @BibleId, 119105006, N'O children of Abraham, God’s servant, you descendants of Jacob, God’s chosen ones!'
EXEC add_BibleVerse @BibleId, 119105007, N'He is the Lord our God; he carries out judgment throughout the earth.'
EXEC add_BibleVerse @BibleId, 119105008, N'He always remembers his covenantal decree, the promise he made to a thousand generations –'
EXEC add_BibleVerse @BibleId, 119105009, N'the promise he made to Abraham, the promise he made by oath to Isaac!'
EXEC add_BibleVerse @BibleId, 119105010, N'He gave it to Jacob as a decree, to Israel as a lasting promise,'
EXEC add_BibleVerse @BibleId, 119105011, N'saying, “To you I will give the land of Canaan as the portion of your inheritance.”'
EXEC add_BibleVerse @BibleId, 119105012, N'When they were few in number, just a very few, and resident aliens within it,'
EXEC add_BibleVerse @BibleId, 119105013, N'they wandered from nation to nation, and from one kingdom to another.'
EXEC add_BibleVerse @BibleId, 119105014, N'He let no one oppress them; he disciplined kings for their sake,'
EXEC add_BibleVerse @BibleId, 119105015, N'saying, “Don’t touch my chosen ones! Don’t harm my prophets!”'
EXEC add_BibleVerse @BibleId, 119105016, N'He called down a famine upon the earth; he cut off all the food supply.'
EXEC add_BibleVerse @BibleId, 119105017, N'He sent a man ahead of them – Joseph was sold as a servant.'
EXEC add_BibleVerse @BibleId, 119105018, N'The shackles hurt his feet; his neck was placed in an iron collar,'
EXEC add_BibleVerse @BibleId, 119105019, N'until the time when his prediction came true. The Lord’s word proved him right.'
EXEC add_BibleVerse @BibleId, 119105020, N'The king authorized his release; the ruler of nations set him free.'
EXEC add_BibleVerse @BibleId, 119105021, N'He put him in charge of his palace, and made him manager of all his property,'
EXEC add_BibleVerse @BibleId, 119105022, N'giving him authority to imprison his officials and to teach his advisers.'
EXEC add_BibleVerse @BibleId, 119105023, N'Israel moved to Egypt; Jacob lived for a time in the land of Ham.'
EXEC add_BibleVerse @BibleId, 119105024, N'The Lord made his people very fruitful, and made them more numerous than their enemies.'
EXEC add_BibleVerse @BibleId, 119105025, N'He caused them to hate his people, and to mistreat his servants.'
EXEC add_BibleVerse @BibleId, 119105026, N'He sent his servant Moses, and Aaron, whom he had chosen.'
EXEC add_BibleVerse @BibleId, 119105027, N'They executed his miraculous signs among them, and his amazing deeds in the land of Ham.'
EXEC add_BibleVerse @BibleId, 119105028, N'He made it dark; they did not disobey his orders.'
EXEC add_BibleVerse @BibleId, 119105029, N'He turned their water into blood, and killed their fish.'
EXEC add_BibleVerse @BibleId, 119105030, N'Their land was overrun by frogs, which even got into the rooms of their kings.'
EXEC add_BibleVerse @BibleId, 119105031, N'He ordered flies to come; gnats invaded their whole territory.'
EXEC add_BibleVerse @BibleId, 119105032, N'He sent hail along with the rain; there was lightning in their land.'
EXEC add_BibleVerse @BibleId, 119105033, N'He destroyed their vines and fig trees, and broke the trees throughout their territory.'
EXEC add_BibleVerse @BibleId, 119105034, N'He ordered locusts to come, innumerable grasshoppers.'
EXEC add_BibleVerse @BibleId, 119105035, N'They ate all the vegetation in their land, and devoured the crops of their fields.'
EXEC add_BibleVerse @BibleId, 119105036, N'He struck down all the firstborn in their land, the firstfruits of their reproductive power.'
EXEC add_BibleVerse @BibleId, 119105037, N'He brought his people out enriched with silver and gold; none of his tribes stumbled.'
EXEC add_BibleVerse @BibleId, 119105038, N'Egypt was happy when they left, for they were afraid of them.'
EXEC add_BibleVerse @BibleId, 119105039, N'He spread out a cloud for a cover, and provided a fire to light up the night.'
EXEC add_BibleVerse @BibleId, 119105040, N'They asked for food, and he sent quails; he satisfied them with food from the sky.'
EXEC add_BibleVerse @BibleId, 119105041, N'He opened up a rock and water flowed out; a river ran through dry regions.'
EXEC add_BibleVerse @BibleId, 119105042, N'Yes, he remembered the sacred promise he made to Abraham his servant.'
EXEC add_BibleVerse @BibleId, 119105043, N'When he led his people out, they rejoiced; his chosen ones shouted with joy.'
EXEC add_BibleVerse @BibleId, 119105044, N'He handed the territory of nations over to them, and they took possession of what other peoples had produced,'
EXEC add_BibleVerse @BibleId, 119105045, N'so that they might keep his commands and obey his laws. Praise the Lord!'
EXEC add_BibleVerse @BibleId, 119106001, N'Praise the Lord! Give thanks to the Lord, for he is good, and his loyal love endures!'
EXEC add_BibleVerse @BibleId, 119106002, N'Who can adequately recount the Lord’s mighty acts, or relate all his praiseworthy deeds?'
EXEC add_BibleVerse @BibleId, 119106003, N'How blessed are those who promote justice, and do what is right all the time!'
EXEC add_BibleVerse @BibleId, 119106004, N'Remember me, O Lord, when you show favor to your people! Pay attention to me, when you deliver,'
EXEC add_BibleVerse @BibleId, 119106005, N'so I may see the prosperity of your chosen ones, rejoice along with your nation, and boast along with the people who belong to you.'
EXEC add_BibleVerse @BibleId, 119106006, N'We have sinned like our ancestors; we have done wrong, we have done evil.'
EXEC add_BibleVerse @BibleId, 119106007, N'Our ancestors in Egypt failed to appreciate your miraculous deeds, they failed to remember your many acts of loyal love, and they rebelled at the sea, by the Red Sea.'
EXEC add_BibleVerse @BibleId, 119106008, N'Yet he delivered them for the sake of his reputation, that he might reveal his power.'
EXEC add_BibleVerse @BibleId, 119106009, N'He shouted at the Red Sea and it dried up; he led them through the deep water as if it were a desert.'
EXEC add_BibleVerse @BibleId, 119106010, N'He delivered them from the power of the one who hated them, and rescued them from the power of the enemy.'
EXEC add_BibleVerse @BibleId, 119106011, N'The water covered their enemies; not even one of them survived.'
EXEC add_BibleVerse @BibleId, 119106012, N'They believed his promises; they sang praises to him.'
EXEC add_BibleVerse @BibleId, 119106013, N'They quickly forgot what he had done; they did not wait for his instructions.'
EXEC add_BibleVerse @BibleId, 119106014, N'In the wilderness they had an insatiable craving for meat; they challenged God in the desert.'
EXEC add_BibleVerse @BibleId, 119106015, N'He granted their request, then struck them with a disease.'
EXEC add_BibleVerse @BibleId, 119106016, N'In the camp they resented Moses, and Aaron, the Lord’s holy priest.'
EXEC add_BibleVerse @BibleId, 119106017, N'The earth opened up and swallowed Dathan; it engulfed the group led by Abiram.'
EXEC add_BibleVerse @BibleId, 119106018, N'Fire burned their group; the flames scorched the wicked.'
EXEC add_BibleVerse @BibleId, 119106019, N'They made an image of a calf at Horeb, and worshiped a metal idol.'
EXEC add_BibleVerse @BibleId, 119106020, N'They traded their majestic God for the image of an ox that eats grass.'
EXEC add_BibleVerse @BibleId, 119106021, N'They rejected the God who delivered them, the one who performed great deeds in Egypt,'
EXEC add_BibleVerse @BibleId, 119106022, N'amazing feats in the land of Ham, mighty acts by the Red Sea.'
EXEC add_BibleVerse @BibleId, 119106023, N'He threatened to destroy them, but Moses, his chosen one, interceded with him and turned back his destructive anger.'
EXEC add_BibleVerse @BibleId, 119106024, N'They rejected the fruitful land; they did not believe his promise.'
EXEC add_BibleVerse @BibleId, 119106025, N'They grumbled in their tents; they did not obey the Lord.'
EXEC add_BibleVerse @BibleId, 119106026, N'So he made a solemn vow that he would make them die in the desert,'
EXEC add_BibleVerse @BibleId, 119106027, N'make their descendants die among the nations, and scatter them among foreign lands.'
EXEC add_BibleVerse @BibleId, 119106028, N'They worshiped Baal of Peor, and ate sacrifices offered to the dead.'
EXEC add_BibleVerse @BibleId, 119106029, N'They made the Lord angry by their actions, and a plague broke out among them.'
EXEC add_BibleVerse @BibleId, 119106030, N'Phinehas took a stand and intervened, and the plague subsided.'
EXEC add_BibleVerse @BibleId, 119106031, N'This brought him a reward, an eternal gift.'
EXEC add_BibleVerse @BibleId, 119106032, N'They made him angry by the waters of Meribah, and Moses suffered because of them,'
EXEC add_BibleVerse @BibleId, 119106033, N'for they aroused his temper, and he spoke rashly.'
EXEC add_BibleVerse @BibleId, 119106034, N'They did not destroy the nations, as the Lord had commanded them to do.'
EXEC add_BibleVerse @BibleId, 119106035, N'They mixed in with the nations and learned their ways.'
EXEC add_BibleVerse @BibleId, 119106036, N'They worshiped their idols, which became a snare to them.'
EXEC add_BibleVerse @BibleId, 119106037, N'They sacrificed their sons and daughters to demons.'
EXEC add_BibleVerse @BibleId, 119106038, N'They shed innocent blood – the blood of their sons and daughters, whom they sacrificed to the idols of Canaan. The land was polluted by bloodshed.'
EXEC add_BibleVerse @BibleId, 119106039, N'They were defiled by their deeds, and unfaithful in their actions.'
EXEC add_BibleVerse @BibleId, 119106040, N'So the Lord was angry with his people and despised the people who belong to him.'
EXEC add_BibleVerse @BibleId, 119106041, N'He handed them over to the nations, and those who hated them ruled over them.'
EXEC add_BibleVerse @BibleId, 119106042, N'Their enemies oppressed them; they were subject to their authority.'
EXEC add_BibleVerse @BibleId, 119106043, N'Many times he delivered them, but they had a rebellious attitude, and degraded themselves by their sin.'
EXEC add_BibleVerse @BibleId, 119106044, N'Yet he took notice of their distress, when he heard their cry for help.'
EXEC add_BibleVerse @BibleId, 119106045, N'He remembered his covenant with them, and relented because of his great loyal love.'
EXEC add_BibleVerse @BibleId, 119106046, N'He caused all their conquerors to have pity on them.'
EXEC add_BibleVerse @BibleId, 119106047, N'Deliver us, O Lord, our God! Gather us from among the nations! Then we will give thanks to your holy name, and boast about your praiseworthy deeds.'
EXEC add_BibleVerse @BibleId, 119106048, N'The Lord God of Israel deserves praise, in the future and forevermore. Let all the people say, “We agree! Praise the Lord!”'
EXEC add_BibleVerse @BibleId, 119107001, N'Give thanks to the Lord, for he is good, and his loyal love endures!'
EXEC add_BibleVerse @BibleId, 119107002, N'Let those delivered by the Lord speak out, those whom he delivered from the power of the enemy,'
EXEC add_BibleVerse @BibleId, 119107003, N'and gathered from foreign lands, from east and west, from north and south.'
EXEC add_BibleVerse @BibleId, 119107004, N'They wandered through the wilderness on a desert road; they found no city in which to live.'
EXEC add_BibleVerse @BibleId, 119107005, N'They were hungry and thirsty; they fainted from exhaustion.'
EXEC add_BibleVerse @BibleId, 119107006, N'They cried out to the Lord in their distress; he delivered them from their troubles.'
EXEC add_BibleVerse @BibleId, 119107007, N'He led them on a level road, that they might find a city in which to live.'
EXEC add_BibleVerse @BibleId, 119107008, N'Let them give thanks to the Lord for his loyal love, and for the amazing things he has done for people!'
EXEC add_BibleVerse @BibleId, 119107009, N'For he has satisfied those who thirst, and those who hunger he has filled with food.'
EXEC add_BibleVerse @BibleId, 119107010, N'They sat in utter darkness, bound in painful iron chains,'
EXEC add_BibleVerse @BibleId, 119107011, N'because they had rebelled against God’s commands, and rejected the instructions of the sovereign king.'
EXEC add_BibleVerse @BibleId, 119107012, N'So he used suffering to humble them; they stumbled and no one helped them up.'
EXEC add_BibleVerse @BibleId, 119107013, N'They cried out to the Lord in their distress; he delivered them from their troubles.'
EXEC add_BibleVerse @BibleId, 119107014, N'He brought them out of the utter darkness, and tore off their shackles.'
EXEC add_BibleVerse @BibleId, 119107015, N'Let them give thanks to the Lord for his loyal love, and for the amazing things he has done for people!'
EXEC add_BibleVerse @BibleId, 119107016, N'For he shattered the bronze gates, and hacked through the iron bars.'
EXEC add_BibleVerse @BibleId, 119107017, N'They acted like fools in their rebellious ways, and suffered because of their sins.'
EXEC add_BibleVerse @BibleId, 119107018, N'They lost their appetite for all food, and they drew near the gates of death.'
EXEC add_BibleVerse @BibleId, 119107019, N'They cried out to the Lord in their distress; he delivered them from their troubles.'
EXEC add_BibleVerse @BibleId, 119107020, N'He sent them an assuring word and healed them; he rescued them from the pits where they were trapped.'
EXEC add_BibleVerse @BibleId, 119107021, N'Let them give thanks to the Lord for his loyal love, and for the amazing things he has done for people!'
EXEC add_BibleVerse @BibleId, 119107022, N'Let them present thank offerings, and loudly proclaim what he has done!'
EXEC add_BibleVerse @BibleId, 119107023, N'Some traveled on the sea in ships, and carried cargo over the vast waters.'
EXEC add_BibleVerse @BibleId, 119107024, N'They witnessed the acts of the Lord, his amazing feats on the deep water.'
EXEC add_BibleVerse @BibleId, 119107025, N'He gave the order for a windstorm, and it stirred up the waves of the sea.'
EXEC add_BibleVerse @BibleId, 119107026, N'They reached up to the sky, then dropped into the depths. The sailors’ strength left them because the danger was so great.'
EXEC add_BibleVerse @BibleId, 119107027, N'They swayed and staggered like a drunk, and all their skill proved ineffective.'
EXEC add_BibleVerse @BibleId, 119107028, N'They cried out to the Lord in their distress; he delivered them from their troubles.'
EXEC add_BibleVerse @BibleId, 119107029, N'He calmed the storm, and the waves grew silent.'
EXEC add_BibleVerse @BibleId, 119107030, N'The sailors rejoiced because the waves grew quiet, and he led them to the harbor they desired.'
EXEC add_BibleVerse @BibleId, 119107031, N'Let them give thanks to the Lord for his loyal love, and for the amazing things he has done for people!'
EXEC add_BibleVerse @BibleId, 119107032, N'Let them exalt him in the assembly of the people! Let them praise him in the place where the leaders preside!'
EXEC add_BibleVerse @BibleId, 119107033, N'He turned streams into a desert, springs of water into arid land,'
EXEC add_BibleVerse @BibleId, 119107034, N'and a fruitful land into a barren place, because of the sin of its inhabitants.'
EXEC add_BibleVerse @BibleId, 119107035, N'As for his people, he turned a desert into a pool of water, and a dry land into springs of water.'
EXEC add_BibleVerse @BibleId, 119107036, N'He allowed the hungry to settle there, and they established a city in which to live.'
EXEC add_BibleVerse @BibleId, 119107037, N'They cultivated fields, and planted vineyards, which yielded a harvest of fruit.'
EXEC add_BibleVerse @BibleId, 119107038, N'He blessed them so that they became very numerous. He would not allow their cattle to decrease in number.'
EXEC add_BibleVerse @BibleId, 119107039, N'As for their enemies, they decreased in number and were beaten down, because of painful distress and suffering.'
EXEC add_BibleVerse @BibleId, 119107040, N'He would pour contempt upon princes, and he made them wander in a wasteland with no road.'
EXEC add_BibleVerse @BibleId, 119107041, N'Yet he protected the needy from oppression, and cared for his families like a flock of sheep.'
EXEC add_BibleVerse @BibleId, 119107042, N'When the godly see this, they rejoice, and every sinner shuts his mouth.'
EXEC add_BibleVerse @BibleId, 119107043, N'Whoever is wise, let him take note of these things! Let them consider the Lord’s acts of loyal love!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119108001, @markup=N'I am determined, O God! I will sing and praise you with my whole heart. ', @premarkup=N'A song, a psalm of David.'
EXEC add_BibleVerse @BibleId, 119108002, N'Awake, O stringed instrument and harp! I will wake up at dawn!'
EXEC add_BibleVerse @BibleId, 119108003, N'I will give you thanks before the nations, O Lord! I will sing praises to you before foreigners!'
EXEC add_BibleVerse @BibleId, 119108004, N'For your loyal love extends beyond the sky, and your faithfulness reaches the clouds.'
EXEC add_BibleVerse @BibleId, 119108005, N'Rise up above the sky, O God! May your splendor cover the whole earth!'
EXEC add_BibleVerse @BibleId, 119108006, N'Deliver by your power and answer me, so that the ones you love may be safe.'
EXEC add_BibleVerse @BibleId, 119108007, N'God has spoken in his sanctuary: “I will triumph! I will parcel out Shechem, the valley of Succoth I will measure off.'
EXEC add_BibleVerse @BibleId, 119108008, N'Gilead belongs to me, as does Manasseh! Ephraim is my helmet, Judah my royal scepter.'
EXEC add_BibleVerse @BibleId, 119108009, N'Moab is my wash basin. I will make Edom serve me. I will shout in triumph over Philistia.”'
EXEC add_BibleVerse @BibleId, 119108010, N'Who will lead me into the fortified city? Who will bring me to Edom?'
EXEC add_BibleVerse @BibleId, 119108011, N'Have you not rejected us, O God? O God, you do not go into battle with our armies.'
EXEC add_BibleVerse @BibleId, 119108012, N'Give us help against the enemy, for any help men might offer is futile.'
EXEC add_BibleVerse @BibleId, 119108013, N'By God’s power we will conquer; he will trample down our enemies.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119109001, @markup=N'O God whom I praise, do not ignore me! ', @premarkup=N'For the music director, a psalm of David.'
EXEC add_BibleVerse @BibleId, 119109002, N'For they say cruel and deceptive things to me; they lie to me.'
EXEC add_BibleVerse @BibleId, 119109003, N'They surround me and say hateful things; they attack me for no reason.'
EXEC add_BibleVerse @BibleId, 119109004, N'They repay my love with accusations, but I continue to pray.'
EXEC add_BibleVerse @BibleId, 119109005, N'They repay me evil for good, and hate for love.'
EXEC add_BibleVerse @BibleId, 119109006, N'Appoint an evil man to testify against him! May an accuser stand at his right side!'
EXEC add_BibleVerse @BibleId, 119109007, N'When he is judged, he will be found guilty! Then his prayer will be regarded as sinful.'
EXEC add_BibleVerse @BibleId, 119109008, N'May his days be few! May another take his job!'
EXEC add_BibleVerse @BibleId, 119109009, N'May his children be fatherless, and his wife a widow!'
EXEC add_BibleVerse @BibleId, 119109010, N'May his children roam around begging, asking for handouts as they leave their ruined home!'
EXEC add_BibleVerse @BibleId, 119109011, N'May the creditor seize all he owns! May strangers loot his property!'
EXEC add_BibleVerse @BibleId, 119109012, N'May no one show him kindness! May no one have compassion on his fatherless children!'
EXEC add_BibleVerse @BibleId, 119109013, N'May his descendants be cut off! May the memory of them be wiped out by the time the next generation arrives!'
EXEC add_BibleVerse @BibleId, 119109014, N'May his ancestors’ sins be remembered by the Lord! May his mother’s sin not be forgotten!'
EXEC add_BibleVerse @BibleId, 119109015, N'May the Lord be constantly aware of them, and cut off the memory of his children from the earth!'
EXEC add_BibleVerse @BibleId, 119109016, N'For he never bothered to show kindness; he harassed the oppressed and needy, and killed the disheartened.'
EXEC add_BibleVerse @BibleId, 119109017, N'He loved to curse others, so those curses have come upon him. He had no desire to bless anyone, so he has experienced no blessings.'
EXEC add_BibleVerse @BibleId, 119109018, N'He made cursing a way of life, so curses poured into his stomach like water and seeped into his bones like oil.'
EXEC add_BibleVerse @BibleId, 119109019, N'May a curse attach itself to him, like a garment one puts on, or a belt one wears continually!'
EXEC add_BibleVerse @BibleId, 119109020, N'May the Lord repay my accusers in this way, those who say evil things about me!'
EXEC add_BibleVerse @BibleId, 119109021, N'O sovereign Lord, intervene on my behalf for the sake of your reputation! Because your loyal love is good, deliver me!'
EXEC add_BibleVerse @BibleId, 119109022, N'For I am oppressed and needy, and my heart beats violently within me.'
EXEC add_BibleVerse @BibleId, 119109023, N'I am fading away like a shadow at the end of the day; I am shaken off like a locust.'
EXEC add_BibleVerse @BibleId, 119109024, N'I am so starved my knees shake; I have turned into skin and bones.'
EXEC add_BibleVerse @BibleId, 119109025, N'I am disdained by them. When they see me, they shake their heads.'
EXEC add_BibleVerse @BibleId, 119109026, N'Help me, O Lord my God! Because you are faithful to me, deliver me!'
EXEC add_BibleVerse @BibleId, 119109027, N'Then they will realize this is your work, and that you, Lord, have accomplished it.'
EXEC add_BibleVerse @BibleId, 119109028, N'They curse, but you will bless. When they attack, they will be humiliated, but your servant will rejoice.'
EXEC add_BibleVerse @BibleId, 119109029, N'My accusers will be covered with shame, and draped in humiliation as if it were a robe.'
EXEC add_BibleVerse @BibleId, 119109030, N'I will thank the Lord profusely, in the middle of a crowd I will praise him,'
EXEC add_BibleVerse @BibleId, 119109031, N'because he stands at the right hand of the needy, to deliver him from those who threaten his life.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119110001, @markup=N'Here is the Lord’s proclamation to my lord: “Sit down at my right hand until I make your enemies your footstool!” ', @premarkup=N'A Psalm of David.'
EXEC add_BibleVerse @BibleId, 119110002, N'The Lord extends your dominion from Zion. Rule in the midst of your enemies!'
EXEC add_BibleVerse @BibleId, 119110003, N'Your people willingly follow you when you go into battle. On the holy hills at sunrise the dew of your youth belongs to you.'
EXEC add_BibleVerse @BibleId, 119110004, N'The Lord makes this promise on oath and will not revoke it: “You are an eternal priest after the pattern of Melchizedek.”'
EXEC add_BibleVerse @BibleId, 119110005, N'O sovereign Lord, at your right hand he strikes down kings in the day he unleashes his anger.'
EXEC add_BibleVerse @BibleId, 119110006, N'He executes judgment against the nations; he fills the valleys with corpses; he shatters their heads over the vast battlefield.'
EXEC add_BibleVerse @BibleId, 119110007, N'From the stream along the road he drinks; then he lifts up his head.'
EXEC add_BibleVerse @BibleId, 119111001, N'Praise the Lord! I will give thanks to the Lord with my whole heart, in the assembly of the godly and the congregation.'
EXEC add_BibleVerse @BibleId, 119111002, N'The Lord’s deeds are great, eagerly awaited by all who desire them.'
EXEC add_BibleVerse @BibleId, 119111003, N'His work is majestic and glorious, and his faithfulness endures forever.'
EXEC add_BibleVerse @BibleId, 119111004, N'He does amazing things that will be remembered; the Lord is merciful and compassionate.'
EXEC add_BibleVerse @BibleId, 119111005, N'He gives food to his faithful followers; he always remembers his covenant.'
EXEC add_BibleVerse @BibleId, 119111006, N'He announced that he would do mighty deeds for his people, giving them a land that belonged to other nations.'
EXEC add_BibleVerse @BibleId, 119111007, N'His acts are characterized by faithfulness and justice; all his precepts are reliable.'
EXEC add_BibleVerse @BibleId, 119111008, N'They are forever firm, and should be faithfully and properly carried out.'
EXEC add_BibleVerse @BibleId, 119111009, N'He delivered his people; he ordained that his covenant be observed forever. His name is holy and awesome.'
EXEC add_BibleVerse @BibleId, 119111010, N'To obey the Lord is the fundamental principle for wise living; all who carry out his precepts acquire good moral insight. He will receive praise forever.'
EXEC add_BibleVerse @BibleId, 119112001, N'Praise the Lord! How blessed is the one who obeys the Lord, who takes great delight in keeping his commands.'
EXEC add_BibleVerse @BibleId, 119112002, N'His descendants will be powerful on the earth; the godly will be blessed.'
EXEC add_BibleVerse @BibleId, 119112003, N'His house contains wealth and riches; his integrity endures.'
EXEC add_BibleVerse @BibleId, 119112004, N'In the darkness a light shines for the godly, for each one who is merciful, compassionate, and just.'
EXEC add_BibleVerse @BibleId, 119112005, N'It goes well for the one who generously lends money, and conducts his business honestly.'
EXEC add_BibleVerse @BibleId, 119112006, N'For he will never be upended; others will always remember one who is just.'
EXEC add_BibleVerse @BibleId, 119112007, N'He does not fear bad news. He is confident; he trusts in the Lord.'
EXEC add_BibleVerse @BibleId, 119112008, N'His resolve is firm; he will not succumb to fear before he looks in triumph on his enemies.'
EXEC add_BibleVerse @BibleId, 119112009, N'He generously gives to the needy; his integrity endures. He will be vindicated and honored.'
EXEC add_BibleVerse @BibleId, 119112010, N'When the wicked see this, they will worry; they will grind their teeth in frustration and melt away; the desire of the wicked will perish.'
EXEC add_BibleVerse @BibleId, 119113001, N'Praise the Lord! Praise, you servants of the Lord, praise the name of the Lord!'
EXEC add_BibleVerse @BibleId, 119113002, N'May the Lord’s name be praised now and forevermore!'
EXEC add_BibleVerse @BibleId, 119113003, N'From east to west the Lord’s name is deserving of praise.'
EXEC add_BibleVerse @BibleId, 119113004, N'The Lord is exalted over all the nations; his splendor reaches beyond the sky.'
EXEC add_BibleVerse @BibleId, 119113005, N'Who can compare to the Lord our God, who sits on a high throne?'
EXEC add_BibleVerse @BibleId, 119113006, N'He bends down to look at the sky and the earth.'
EXEC add_BibleVerse @BibleId, 119113007, N'He raises the poor from the dirt, and lifts up the needy from the garbage pile,'
EXEC add_BibleVerse @BibleId, 119113008, N'that he might seat him with princes, with the princes of his people.'
EXEC add_BibleVerse @BibleId, 119113009, N'He makes the barren woman of the family a happy mother of children. Praise the Lord!'
EXEC add_BibleVerse @BibleId, 119114001, N'When Israel left Egypt, when the family of Jacob left a foreign nation behind,'
EXEC add_BibleVerse @BibleId, 119114002, N'Judah became his sanctuary, Israel his kingdom.'
EXEC add_BibleVerse @BibleId, 119114003, N'The sea looked and fled; the Jordan River turned back.'
EXEC add_BibleVerse @BibleId, 119114004, N'The mountains skipped like rams, the hills like lambs.'
EXEC add_BibleVerse @BibleId, 119114005, N'Why do you flee, O sea? Why do you turn back, O Jordan River?'
EXEC add_BibleVerse @BibleId, 119114006, N'Why do you skip like rams, O mountains, like lambs, O hills?'
EXEC add_BibleVerse @BibleId, 119114007, N'Tremble, O earth, before the Lord – before the God of Jacob,'
EXEC add_BibleVerse @BibleId, 119114008, N'who turned a rock into a pool of water, a hard rock into springs of water!'
EXEC add_BibleVerse @BibleId, 119115001, N'Not to us, O Lord, not to us! But to your name bring honor, for the sake of your loyal love and faithfulness.'
EXEC add_BibleVerse @BibleId, 119115002, N'Why should the nations say, “Where is their God?”'
EXEC add_BibleVerse @BibleId, 119115003, N'Our God is in heaven! He does whatever he pleases!'
EXEC add_BibleVerse @BibleId, 119115004, N'Their idols are made of silver and gold – they are man-made.'
EXEC add_BibleVerse @BibleId, 119115005, N'They have mouths, but cannot speak, eyes, but cannot see,'
EXEC add_BibleVerse @BibleId, 119115006, N'ears, but cannot hear, noses, but cannot smell,'
EXEC add_BibleVerse @BibleId, 119115007, N'hands, but cannot touch, feet, but cannot walk. They cannot even clear their throats.'
EXEC add_BibleVerse @BibleId, 119115008, N'Those who make them will end up like them, as will everyone who trusts in them.'
EXEC add_BibleVerse @BibleId, 119115009, N'O Israel, trust in the Lord! He is their deliverer and protector.'
EXEC add_BibleVerse @BibleId, 119115010, N'O family of Aaron, trust in the Lord! He is their deliverer and protector.'
EXEC add_BibleVerse @BibleId, 119115011, N'You loyal followers of the Lord, trust in the Lord! He is their deliverer and protector.'
EXEC add_BibleVerse @BibleId, 119115012, N'The Lord takes notice of us, he will bless – he will bless the family of Israel, he will bless the family of Aaron.'
EXEC add_BibleVerse @BibleId, 119115013, N'He will bless his loyal followers, both young and old.'
EXEC add_BibleVerse @BibleId, 119115014, N'May he increase your numbers, yours and your children’s!'
EXEC add_BibleVerse @BibleId, 119115015, N'May you be blessed by the Lord, the creator of heaven and earth!'
EXEC add_BibleVerse @BibleId, 119115016, N'The heavens belong to the Lord, but the earth he has given to mankind.'
EXEC add_BibleVerse @BibleId, 119115017, N'The dead do not praise the Lord, nor do any of those who descend into the silence of death.'
EXEC add_BibleVerse @BibleId, 119115018, N'But we will praise the Lord now and forevermore. Praise the Lord!'
EXEC add_BibleVerse @BibleId, 119116001, N'I love the Lord because he heard my plea for mercy,'
EXEC add_BibleVerse @BibleId, 119116002, N'and listened to me. As long as I live, I will call to him when I need help.'
EXEC add_BibleVerse @BibleId, 119116003, N'The ropes of death tightened around me, the snares of Sheol confronted me. I was confronted with trouble and sorrow.'
EXEC add_BibleVerse @BibleId, 119116004, N'I called on the name of the Lord, “Please Lord, rescue my life!”'
EXEC add_BibleVerse @BibleId, 119116005, N'The Lord is merciful and fair; our God is compassionate.'
EXEC add_BibleVerse @BibleId, 119116006, N'The Lord protects the untrained; I was in serious trouble and he delivered me.'
EXEC add_BibleVerse @BibleId, 119116007, N'Rest once more, my soul, for the Lord has vindicated you.'
EXEC add_BibleVerse @BibleId, 119116008, N'Yes, Lord, you rescued my life from death, and kept my feet from stumbling.'
EXEC add_BibleVerse @BibleId, 119116009, N'I will serve the Lord in the land of the living.'
EXEC add_BibleVerse @BibleId, 119116010, N'I had faith when I said, “I am severely oppressed.”'
EXEC add_BibleVerse @BibleId, 119116011, N'I rashly declared, “All men are liars.”'
EXEC add_BibleVerse @BibleId, 119116012, N'How can I repay the Lord for all his acts of kindness to me?'
EXEC add_BibleVerse @BibleId, 119116013, N'I will celebrate my deliverance, and call on the name of the Lord.'
EXEC add_BibleVerse @BibleId, 119116014, N'I will fulfill my vows to the Lord before all his people.'
EXEC add_BibleVerse @BibleId, 119116015, N'The Lord values the lives of his faithful followers.'
EXEC add_BibleVerse @BibleId, 119116016, N'Yes, Lord! I am indeed your servant; I am your lowest slave. You saved me from death.'
EXEC add_BibleVerse @BibleId, 119116017, N'I will present a thank offering to you, and call on the name of the Lord.'
EXEC add_BibleVerse @BibleId, 119116018, N'I will fulfill my vows to the Lord before all his people,'
EXEC add_BibleVerse @BibleId, 119116019, N'in the courts of the Lord’s temple, in your midst, O Jerusalem. Praise the Lord!'
EXEC add_BibleVerse @BibleId, 119117001, N'Praise the Lord, all you nations! Applaud him, all you foreigners!'
EXEC add_BibleVerse @BibleId, 119117002, N'For his loyal love towers over us, and the Lord’s faithfulness endures. Praise the Lord!'
EXEC add_BibleVerse @BibleId, 119118001, N'Give thanks to the Lord, for he is good and his loyal love endures!'
EXEC add_BibleVerse @BibleId, 119118002, N'Let Israel say, “Yes, his loyal love endures!”'
EXEC add_BibleVerse @BibleId, 119118003, N'Let the family of Aaron say, “Yes, his loyal love endures!”'
EXEC add_BibleVerse @BibleId, 119118004, N'Let the loyal followers of the Lord say, “Yes, his loyal love endures!”'
EXEC add_BibleVerse @BibleId, 119118005, N'In my distress I cried out to the Lord. The Lord answered me and put me in a wide open place.'
EXEC add_BibleVerse @BibleId, 119118006, N'The Lord is on my side, I am not afraid! What can people do to me?'
EXEC add_BibleVerse @BibleId, 119118007, N'The Lord is on my side as my helper. I look in triumph on those who hate me.'
EXEC add_BibleVerse @BibleId, 119118008, N'It is better to take shelter in the Lord than to trust in people.'
EXEC add_BibleVerse @BibleId, 119118009, N'It is better to take shelter in the Lord than to trust in princes.'
EXEC add_BibleVerse @BibleId, 119118010, N'All the nations surrounded me. Indeed, in the name of the Lord I pushed them away.'
EXEC add_BibleVerse @BibleId, 119118011, N'They surrounded me, yes, they surrounded me. Indeed, in the name of the Lord I pushed them away.'
EXEC add_BibleVerse @BibleId, 119118012, N'They surrounded me like bees. But they disappeared as quickly as a fire among thorns. Indeed, in the name of the Lord I pushed them away.'
EXEC add_BibleVerse @BibleId, 119118013, N'“You aggressively attacked me and tried to knock me down, but the Lord helped me.'
EXEC add_BibleVerse @BibleId, 119118014, N'The Lord gives me strength and protects me; he has become my deliverer.”'
EXEC add_BibleVerse @BibleId, 119118015, N'They celebrate deliverance in the tents of the godly. The Lord’s right hand conquers,'
EXEC add_BibleVerse @BibleId, 119118016, N'the Lord’s right hand gives victory, the Lord’s right hand conquers.'
EXEC add_BibleVerse @BibleId, 119118017, N'I will not die, but live, and I will proclaim what the Lord has done.'
EXEC add_BibleVerse @BibleId, 119118018, N'The Lord severely punished me, but he did not hand me over to death.'
EXEC add_BibleVerse @BibleId, 119118019, N'Open for me the gates of the just king’s temple! I will enter through them and give thanks to the Lord.'
EXEC add_BibleVerse @BibleId, 119118020, N'This is the Lord’s gate – the godly enter through it.'
EXEC add_BibleVerse @BibleId, 119118021, N'I will give you thanks, for you answered me, and have become my deliverer.'
EXEC add_BibleVerse @BibleId, 119118022, N'The stone which the builders discarded has become the cornerstone.'
EXEC add_BibleVerse @BibleId, 119118023, N'This is the Lord’s work. We consider it amazing!'
EXEC add_BibleVerse @BibleId, 119118024, N'This is the day the Lord has brought about. We will be happy and rejoice in it.'
EXEC add_BibleVerse @BibleId, 119118025, N'Please Lord, deliver! Please Lord, grant us success!'
EXEC add_BibleVerse @BibleId, 119118026, N'May the one who comes in the name of the Lord be blessed! We will pronounce blessings on you in the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 119118027, N'The Lord is God and he has delivered us. Tie the offering with ropes to the horns of the altar!'
EXEC add_BibleVerse @BibleId, 119118028, N'You are my God and I will give you thanks! You are my God and I will praise you!'
EXEC add_BibleVerse @BibleId, 119118029, N'Give thanks to the Lord, for he is good and his loyal love endures!'
EXEC add_BibleVerse @BibleId, 119119001, N'How blessed are those whose actions are blameless, who obey the law of the Lord.'
EXEC add_BibleVerse @BibleId, 119119002, N'How blessed are those who observe his rules, and seek him with all their heart,'
EXEC add_BibleVerse @BibleId, 119119003, N'who, moreover, do no wrong, but follow in his footsteps.'
EXEC add_BibleVerse @BibleId, 119119004, N'You demand that your precepts be carefully kept.'
EXEC add_BibleVerse @BibleId, 119119005, N'If only I were predisposed to keep your statutes!'
EXEC add_BibleVerse @BibleId, 119119006, N'Then I would not be ashamed, if I were focused on all your commands.'
EXEC add_BibleVerse @BibleId, 119119007, N'I will give you sincere thanks, when I learn your just regulations.'
EXEC add_BibleVerse @BibleId, 119119008, N'I will keep your statutes. Do not completely abandon me!'
EXEC add_BibleVerse @BibleId, 119119009, N'How can a young person maintain a pure life? By guarding it according to your instructions!'
EXEC add_BibleVerse @BibleId, 119119010, N'With all my heart I seek you. Do not allow me to stray from your commands!'
EXEC add_BibleVerse @BibleId, 119119011, N'In my heart I store up your words, so I might not sin against you.'
EXEC add_BibleVerse @BibleId, 119119012, N'You deserve praise, O Lord! Teach me your statutes!'
EXEC add_BibleVerse @BibleId, 119119013, N'With my lips I proclaim all the regulations you have revealed.'
EXEC add_BibleVerse @BibleId, 119119014, N'I rejoice in the lifestyle prescribed by your rules as if they were riches of all kinds.'
EXEC add_BibleVerse @BibleId, 119119015, N'I will meditate on your precepts and focus on your behavior.'
EXEC add_BibleVerse @BibleId, 119119016, N'I find delight in your statutes; I do not forget your instructions.'
EXEC add_BibleVerse @BibleId, 119119017, N'Be kind to your servant! Then I will live and keep your instructions.'
EXEC add_BibleVerse @BibleId, 119119018, N'Open my eyes so I can truly see the marvelous things in your law!'
EXEC add_BibleVerse @BibleId, 119119019, N'I am like a foreigner in this land. Do not hide your commands from me!'
EXEC add_BibleVerse @BibleId, 119119020, N'I desperately long to know your regulations at all times.'
EXEC add_BibleVerse @BibleId, 119119021, N'You reprimand arrogant people. Those who stray from your commands are doomed.'
EXEC add_BibleVerse @BibleId, 119119022, N'Spare me shame and humiliation, for I observe your rules.'
EXEC add_BibleVerse @BibleId, 119119023, N'Though rulers plot and slander me, your servant meditates on your statutes.'
EXEC add_BibleVerse @BibleId, 119119024, N'Yes, I find delight in your rules; they give me guidance.'
EXEC add_BibleVerse @BibleId, 119119025, N'I collapse in the dirt. Revive me with your word!'
EXEC add_BibleVerse @BibleId, 119119026, N'I told you about my ways and you answered me. Teach me your statutes!'
EXEC add_BibleVerse @BibleId, 119119027, N'Help me to understand what your precepts mean! Then I can meditate on your marvelous teachings.'
EXEC add_BibleVerse @BibleId, 119119028, N'I collapse from grief. Sustain me by your word!'
EXEC add_BibleVerse @BibleId, 119119029, N'Remove me from the path of deceit! Graciously give me your law!'
EXEC add_BibleVerse @BibleId, 119119030, N'I choose the path of faithfulness; I am committed to your regulations.'
EXEC add_BibleVerse @BibleId, 119119031, N'I hold fast to your rules. O Lord, do not let me be ashamed!'
EXEC add_BibleVerse @BibleId, 119119032, N'I run along the path of your commands, for you enable me to do so.'
EXEC add_BibleVerse @BibleId, 119119033, N'Teach me, O Lord, the lifestyle prescribed by your statutes, so that I might observe it continually.'
EXEC add_BibleVerse @BibleId, 119119034, N'Give me understanding so that I might observe your law, and keep it with all my heart.'
EXEC add_BibleVerse @BibleId, 119119035, N'Guide me in the path of your commands, for I delight to walk in it.'
EXEC add_BibleVerse @BibleId, 119119036, N'Give me a desire for your rules, rather than for wealth gained unjustly.'
EXEC add_BibleVerse @BibleId, 119119037, N'Turn my eyes away from what is worthless! Revive me with your word!'
EXEC add_BibleVerse @BibleId, 119119038, N'Confirm to your servant your promise, which you made to the one who honors you.'
EXEC add_BibleVerse @BibleId, 119119039, N'Take away the insults that I dread! Indeed, your regulations are good.'
EXEC add_BibleVerse @BibleId, 119119040, N'Look, I long for your precepts. Revive me with your deliverance!'
EXEC add_BibleVerse @BibleId, 119119041, N'May I experience your loyal love, O Lord, and your deliverance, as you promised.'
EXEC add_BibleVerse @BibleId, 119119042, N'Then I will have a reply for the one who insults me, for I trust in your word.'
EXEC add_BibleVerse @BibleId, 119119043, N'Do not completely deprive me of a truthful testimony, for I await your justice.'
EXEC add_BibleVerse @BibleId, 119119044, N'Then I will keep your law continually now and for all time.'
EXEC add_BibleVerse @BibleId, 119119045, N'I will be secure, for I seek your precepts.'
EXEC add_BibleVerse @BibleId, 119119046, N'I will speak about your regulations before kings and not be ashamed.'
EXEC add_BibleVerse @BibleId, 119119047, N'I will find delight in your commands, which I love.'
EXEC add_BibleVerse @BibleId, 119119048, N'I will lift my hands to your commands, which I love, and I will meditate on your statutes.'
EXEC add_BibleVerse @BibleId, 119119049, N'Remember your word to your servant, for you have given me hope.'
EXEC add_BibleVerse @BibleId, 119119050, N'This is what comforts me in my trouble, for your promise revives me.'
EXEC add_BibleVerse @BibleId, 119119051, N'Arrogant people do nothing but scoff at me. Yet I do not turn aside from your law.'
EXEC add_BibleVerse @BibleId, 119119052, N'I remember your ancient regulations, O Lord, and console myself.'
EXEC add_BibleVerse @BibleId, 119119053, N'Rage takes hold of me because of the wicked, those who reject your law.'
EXEC add_BibleVerse @BibleId, 119119054, N'Your statutes have been my songs in the house where I live.'
EXEC add_BibleVerse @BibleId, 119119055, N'I remember your name during the night, O Lord, and I will keep your law.'
EXEC add_BibleVerse @BibleId, 119119056, N'This has been my practice, for I observe your precepts.'
EXEC add_BibleVerse @BibleId, 119119057, N'The Lord is my source of security. I have determined to follow your instructions.'
EXEC add_BibleVerse @BibleId, 119119058, N'I seek your favor with all my heart. Have mercy on me as you promised!'
EXEC add_BibleVerse @BibleId, 119119059, N'I consider my actions and follow your rules.'
EXEC add_BibleVerse @BibleId, 119119060, N'I keep your commands eagerly and without delay.'
EXEC add_BibleVerse @BibleId, 119119061, N'The ropes of the wicked tighten around me, but I do not forget your law.'
EXEC add_BibleVerse @BibleId, 119119062, N'In the middle of the night I arise to thank you for your just regulations.'
EXEC add_BibleVerse @BibleId, 119119063, N'I am a friend to all your loyal followers, and to those who keep your precepts.'
EXEC add_BibleVerse @BibleId, 119119064, N'O Lord, your loyal love fills the earth. Teach me your statutes!'
EXEC add_BibleVerse @BibleId, 119119065, N'You are good to your servant, O Lord, just as you promised.'
EXEC add_BibleVerse @BibleId, 119119066, N'Teach me proper discernment and understanding! For I consider your commands to be reliable.'
EXEC add_BibleVerse @BibleId, 119119067, N'Before I was afflicted I used to stray off, but now I keep your instructions.'
EXEC add_BibleVerse @BibleId, 119119068, N'You are good and you do good. Teach me your statutes!'
EXEC add_BibleVerse @BibleId, 119119069, N'Arrogant people smear my reputation with lies, but I observe your precepts with all my heart.'
EXEC add_BibleVerse @BibleId, 119119070, N'Their hearts are calloused, but I find delight in your law.'
EXEC add_BibleVerse @BibleId, 119119071, N'It was good for me to suffer, so that I might learn your statutes.'
EXEC add_BibleVerse @BibleId, 119119072, N'The law you have revealed is more important to me than thousands of pieces of gold and silver.'
EXEC add_BibleVerse @BibleId, 119119073, N'Your hands made me and formed me. Give me understanding so that I might learn your commands.'
EXEC add_BibleVerse @BibleId, 119119074, N'Your loyal followers will be glad when they see me, for I find hope in your word.'
EXEC add_BibleVerse @BibleId, 119119075, N'I know, Lord, that your regulations are just. You disciplined me because of your faithful devotion to me.'
EXEC add_BibleVerse @BibleId, 119119076, N'May your loyal love console me, as you promised your servant.'
EXEC add_BibleVerse @BibleId, 119119077, N'May I experience your compassion, so I might live! For I find delight in your law.'
EXEC add_BibleVerse @BibleId, 119119078, N'May the arrogant be humiliated, for they have slandered me! But I meditate on your precepts.'
EXEC add_BibleVerse @BibleId, 119119079, N'May your loyal followers turn to me, those who know your rules.'
EXEC add_BibleVerse @BibleId, 119119080, N'May I be fully committed to your statutes, so that I might not be ashamed.'
EXEC add_BibleVerse @BibleId, 119119081, N'I desperately long for your deliverance. I find hope in your word.'
EXEC add_BibleVerse @BibleId, 119119082, N'My eyes grow tired as I wait for your promise to be fulfilled. I say, “When will you comfort me?”'
EXEC add_BibleVerse @BibleId, 119119083, N'For I am like a wineskin dried up in smoke. I do not forget your statutes.'
EXEC add_BibleVerse @BibleId, 119119084, N'How long must your servant endure this? When will you judge those who pursue me?'
EXEC add_BibleVerse @BibleId, 119119085, N'The arrogant dig pits to trap me, which violates your law.'
EXEC add_BibleVerse @BibleId, 119119086, N'All your commands are reliable. I am pursued without reason. Help me!'
EXEC add_BibleVerse @BibleId, 119119087, N'They have almost destroyed me here on the earth, but I do not reject your precepts.'
EXEC add_BibleVerse @BibleId, 119119088, N'Revive me with your loyal love, that I might keep the rules you have revealed.'
EXEC add_BibleVerse @BibleId, 119119089, N'O Lord, your instructions endure; they stand secure in heaven.'
EXEC add_BibleVerse @BibleId, 119119090, N'You demonstrate your faithfulness to all generations. You established the earth and it stood firm.'
EXEC add_BibleVerse @BibleId, 119119091, N'Today they stand firm by your decrees, for all things are your servants.'
EXEC add_BibleVerse @BibleId, 119119092, N'If I had not found encouragement in your law, I would have died in my sorrow.'
EXEC add_BibleVerse @BibleId, 119119093, N'I will never forget your precepts, for by them you have revived me.'
EXEC add_BibleVerse @BibleId, 119119094, N'I belong to you. Deliver me! For I seek your precepts.'
EXEC add_BibleVerse @BibleId, 119119095, N'The wicked prepare to kill me, yet I concentrate on your rules.'
EXEC add_BibleVerse @BibleId, 119119096, N'I realize that everything has its limits, but your commands are beyond full comprehension.'
EXEC add_BibleVerse @BibleId, 119119097, N'O how I love your law! All day long I meditate on it.'
EXEC add_BibleVerse @BibleId, 119119098, N'Your commandments make me wiser than my enemies, for I am always aware of them.'
EXEC add_BibleVerse @BibleId, 119119099, N'I have more insight than all my teachers, for I meditate on your rules.'
EXEC add_BibleVerse @BibleId, 119119100, N'I am more discerning than those older than I, for I observe your precepts.'
EXEC add_BibleVerse @BibleId, 119119101, N'I stay away from the evil path, so that I might keep your instructions.'
EXEC add_BibleVerse @BibleId, 119119102, N'I do not turn aside from your regulations, for you teach me.'
EXEC add_BibleVerse @BibleId, 119119103, N'Your words are sweeter in my mouth than honey!'
EXEC add_BibleVerse @BibleId, 119119104, N'Your precepts give me discernment. Therefore I hate all deceitful actions.'
EXEC add_BibleVerse @BibleId, 119119105, N'Your word is a lamp to walk by, and a light to illumine my path.'
EXEC add_BibleVerse @BibleId, 119119106, N'I have vowed and solemnly sworn to keep your just regulations.'
EXEC add_BibleVerse @BibleId, 119119107, N'I am suffering terribly. O Lord, revive me with your word!'
EXEC add_BibleVerse @BibleId, 119119108, N'O Lord, please accept the freewill offerings of my praise! Teach me your regulations!'
EXEC add_BibleVerse @BibleId, 119119109, N'My life is in continual danger, but I do not forget your law.'
EXEC add_BibleVerse @BibleId, 119119110, N'The wicked lay a trap for me, but I do not wander from your precepts.'
EXEC add_BibleVerse @BibleId, 119119111, N'I claim your rules as my permanent possession, for they give me joy.'
EXEC add_BibleVerse @BibleId, 119119112, N'I am determined to obey your statutes at all times, to the very end.'
EXEC add_BibleVerse @BibleId, 119119113, N'I hate people with divided loyalties, but I love your law.'
EXEC add_BibleVerse @BibleId, 119119114, N'You are my hiding place and my shield. I find hope in your word.'
EXEC add_BibleVerse @BibleId, 119119115, N'Turn away from me, you evil men, so that I can observe the commands of my God.'
EXEC add_BibleVerse @BibleId, 119119116, N'Sustain me as you promised, so that I will live. Do not disappoint me!'
EXEC add_BibleVerse @BibleId, 119119117, N'Support me, so that I will be delivered. Then I will focus on your statutes continually.'
EXEC add_BibleVerse @BibleId, 119119118, N'You despise all who stray from your statutes, for they are deceptive and unreliable.'
EXEC add_BibleVerse @BibleId, 119119119, N'You remove all the wicked of the earth like slag. Therefore I love your rules.'
EXEC add_BibleVerse @BibleId, 119119120, N'My body trembles because I fear you; I am afraid of your judgments.'
EXEC add_BibleVerse @BibleId, 119119121, N'I do what is fair and right. Do not abandon me to my oppressors!'
EXEC add_BibleVerse @BibleId, 119119122, N'Guarantee the welfare of your servant! Do not let the arrogant oppress me!'
EXEC add_BibleVerse @BibleId, 119119123, N'My eyes grow tired as I wait for your deliverance, for your reliable promise to be fulfilled.'
EXEC add_BibleVerse @BibleId, 119119124, N'Show your servant your loyal love! Teach me your statutes!'
EXEC add_BibleVerse @BibleId, 119119125, N'I am your servant. Give me insight, so that I can understand your rules.'
EXEC add_BibleVerse @BibleId, 119119126, N'It is time for the Lord to act – they break your law!'
EXEC add_BibleVerse @BibleId, 119119127, N'For this reason I love your commands more than gold, even purest gold.'
EXEC add_BibleVerse @BibleId, 119119128, N'For this reason I carefully follow all your precepts. I hate all deceitful actions.'
EXEC add_BibleVerse @BibleId, 119119129, N'Your rules are marvelous. Therefore I observe them.'
EXEC add_BibleVerse @BibleId, 119119130, N'Your instructions are a doorway through which light shines. They give insight to the untrained.'
EXEC add_BibleVerse @BibleId, 119119131, N'I open my mouth and pant, because I long for your commands.'
EXEC add_BibleVerse @BibleId, 119119132, N'Turn toward me and extend mercy to me, as you typically do to your loyal followers.'
EXEC add_BibleVerse @BibleId, 119119133, N'Direct my steps by your word! Do not let any sin dominate me!'
EXEC add_BibleVerse @BibleId, 119119134, N'Deliver me from oppressive men, so that I can keep your precepts.'
EXEC add_BibleVerse @BibleId, 119119135, N'Smile on your servant! Teach me your statutes!'
EXEC add_BibleVerse @BibleId, 119119136, N'Tears stream down from my eyes, because people do not keep your law.'
EXEC add_BibleVerse @BibleId, 119119137, N'You are just, O Lord, and your judgments are fair.'
EXEC add_BibleVerse @BibleId, 119119138, N'The rules you impose are just, and absolutely reliable.'
EXEC add_BibleVerse @BibleId, 119119139, N'My zeal consumes me, for my enemies forget your instructions.'
EXEC add_BibleVerse @BibleId, 119119140, N'Your word is absolutely pure, and your servant loves it!'
EXEC add_BibleVerse @BibleId, 119119141, N'I am insignificant and despised, yet I do not forget your precepts.'
EXEC add_BibleVerse @BibleId, 119119142, N'Your justice endures, and your law is reliable.'
EXEC add_BibleVerse @BibleId, 119119143, N'Distress and hardship confront me, yet I find delight in your commands.'
EXEC add_BibleVerse @BibleId, 119119144, N'Your rules remain just. Give me insight so that I can live.'
EXEC add_BibleVerse @BibleId, 119119145, N'I cried out with all my heart, “Answer me, O Lord! I will observe your statutes.”'
EXEC add_BibleVerse @BibleId, 119119146, N'I cried out to you, “Deliver me, so that I can keep your rules.”'
EXEC add_BibleVerse @BibleId, 119119147, N'I am up before dawn crying for help. I find hope in your word.'
EXEC add_BibleVerse @BibleId, 119119148, N'My eyes anticipate the nighttime hours, so that I can meditate on your word.'
EXEC add_BibleVerse @BibleId, 119119149, N'Listen to me because of your loyal love! O Lord, revive me, as you typically do!'
EXEC add_BibleVerse @BibleId, 119119150, N'Those who are eager to do wrong draw near; they are far from your law.'
EXEC add_BibleVerse @BibleId, 119119151, N'You are near, O Lord, and all your commands are reliable.'
EXEC add_BibleVerse @BibleId, 119119152, N'I learned long ago that you ordained your rules to last.'
EXEC add_BibleVerse @BibleId, 119119153, N'See my pain and rescue me! For I do not forget your law.'
EXEC add_BibleVerse @BibleId, 119119154, N'Fight for me and defend me! Revive me with your word!'
EXEC add_BibleVerse @BibleId, 119119155, N'The wicked have no chance for deliverance, for they do not seek your statutes.'
EXEC add_BibleVerse @BibleId, 119119156, N'Your compassion is great, O Lord. Revive me, as you typically do!'
EXEC add_BibleVerse @BibleId, 119119157, N'The enemies who chase me are numerous. Yet I do not turn aside from your rules.'
EXEC add_BibleVerse @BibleId, 119119158, N'I take note of the treacherous and despise them, because they do not keep your instructions.'
EXEC add_BibleVerse @BibleId, 119119159, N'See how I love your precepts! O Lord, revive me with your loyal love!'
EXEC add_BibleVerse @BibleId, 119119160, N'Your instructions are totally reliable; all your just regulations endure.'
EXEC add_BibleVerse @BibleId, 119119161, N'Rulers pursue me for no reason, yet I am more afraid of disobeying your instructions.'
EXEC add_BibleVerse @BibleId, 119119162, N'I rejoice in your instructions, like one who finds much plunder.'
EXEC add_BibleVerse @BibleId, 119119163, N'I hate and despise deceit; I love your law.'
EXEC add_BibleVerse @BibleId, 119119164, N'Seven times a day I praise you because of your just regulations.'
EXEC add_BibleVerse @BibleId, 119119165, N'Those who love your law are completely secure; nothing causes them to stumble.'
EXEC add_BibleVerse @BibleId, 119119166, N'I hope for your deliverance, O Lord, and I obey your commands.'
EXEC add_BibleVerse @BibleId, 119119167, N'I keep your rules; I love them greatly.'
EXEC add_BibleVerse @BibleId, 119119168, N'I keep your precepts and rules, for you are aware of everything I do.'
EXEC add_BibleVerse @BibleId, 119119169, N'Listen to my cry for help, O Lord! Give me insight by your word!'
EXEC add_BibleVerse @BibleId, 119119170, N'Listen to my appeal for mercy! Deliver me, as you promised.'
EXEC add_BibleVerse @BibleId, 119119171, N'May praise flow freely from my lips, for you teach me your statutes.'
EXEC add_BibleVerse @BibleId, 119119172, N'May my tongue sing about your instructions, for all your commands are just.'
EXEC add_BibleVerse @BibleId, 119119173, N'May your hand help me, for I choose to obey your precepts.'
EXEC add_BibleVerse @BibleId, 119119174, N'I long for your deliverance, O Lord; I find delight in your law.'
EXEC add_BibleVerse @BibleId, 119119175, N'May I live and praise you! May your regulations help me!'
EXEC add_BibleVerse @BibleId, 119119176, N'I have wandered off like a lost sheep. Come looking for your servant, for I do not forget your commands.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119120001, @markup=N'In my distress I cried out to the Lord and he answered me. ', @premarkup=N'A song of ascents.'
EXEC add_BibleVerse @BibleId, 119120002, N'I said, “O Lord, rescue me from those who lie with their lips and those who deceive with their tongue.'
EXEC add_BibleVerse @BibleId, 119120003, N'How will he severely punish you, you deceptive talker?'
EXEC add_BibleVerse @BibleId, 119120004, N'Here’s how! With the sharp arrows of warriors, with arrowheads forged over the hot coals.'
EXEC add_BibleVerse @BibleId, 119120005, N'How miserable I am! For I have lived temporarily in Meshech; I have resided among the tents of Kedar.'
EXEC add_BibleVerse @BibleId, 119120006, N'For too long I have had to reside with those who hate peace.'
EXEC add_BibleVerse @BibleId, 119120007, N'I am committed to peace, but when I speak, they want to make war.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119121001, @markup=N'I look up toward the hills. From where does my help come? ', @premarkup=N'A song of ascents.'
EXEC add_BibleVerse @BibleId, 119121002, N'My help comes from the Lord, the Creator of heaven and earth!'
EXEC add_BibleVerse @BibleId, 119121003, N'May he not allow your foot to slip! May your protector not sleep!'
EXEC add_BibleVerse @BibleId, 119121004, N'Look! Israel’s protector does not sleep or slumber!'
EXEC add_BibleVerse @BibleId, 119121005, N'The Lord is your protector; the Lord is the shade at your right hand.'
EXEC add_BibleVerse @BibleId, 119121006, N'The sun will not harm you by day, or the moon by night.'
EXEC add_BibleVerse @BibleId, 119121007, N'The Lord will protect you from all harm; he will protect your life.'
EXEC add_BibleVerse @BibleId, 119121008, N'The Lord will protect you in all you do, now and forevermore.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119122001, @markup=N'I was glad because they said to me, “We will go to the Lord’s temple.” ', @premarkup=N'A song of ascents, by David.'
EXEC add_BibleVerse @BibleId, 119122002, N'Our feet are standing inside your gates, O Jerusalem.'
EXEC add_BibleVerse @BibleId, 119122003, N'Jerusalem is a city designed to accommodate an assembly.'
EXEC add_BibleVerse @BibleId, 119122004, N'The tribes go up there, the tribes of the Lord, where it is required that Israel give thanks to the name of the Lord.'
EXEC add_BibleVerse @BibleId, 119122005, N'Indeed, the leaders sit there on thrones and make legal decisions, on the thrones of the house of David.'
EXEC add_BibleVerse @BibleId, 119122006, N'Pray for the peace of Jerusalem! May those who love her prosper!'
EXEC add_BibleVerse @BibleId, 119122007, N'May there be peace inside your defenses, and prosperity inside your fortresses!'
EXEC add_BibleVerse @BibleId, 119122008, N'For the sake of my brothers and my neighbors I will say, “May there be peace in you!”'
EXEC add_BibleVerse @BibleId, 119122009, N'For the sake of the temple of the Lord our God I will pray for you to prosper.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119123001, @markup=N'I look up toward you, the one enthroned in heaven. ', @premarkup=N'A song of ascents.'
EXEC add_BibleVerse @BibleId, 119123002, N'Look, as the eyes of servants look to the hand of their master, as the eyes of a female servant look to the hand of her mistress, so my eyes will look to the Lord, our God, until he shows us favor.'
EXEC add_BibleVerse @BibleId, 119123003, N'Show us favor, O Lord, show us favor! For we have had our fill of humiliation, and then some.'
EXEC add_BibleVerse @BibleId, 119123004, N'We have had our fill of the taunts of the self-assured, of the contempt of the proud.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119124001, @markup=N'“If the Lord had not been on our side” – let Israel say this! – ', @premarkup=N'A song of ascents, by David.'
EXEC add_BibleVerse @BibleId, 119124002, N'if the Lord had not been on our side, when men attacked us,'
EXEC add_BibleVerse @BibleId, 119124003, N'they would have swallowed us alive, when their anger raged against us.'
EXEC add_BibleVerse @BibleId, 119124004, N'The water would have overpowered us; the current would have overwhelmed us.'
EXEC add_BibleVerse @BibleId, 119124005, N'The raging water would have overwhelmed us.'
EXEC add_BibleVerse @BibleId, 119124006, N'The Lord deserves praise, for he did not hand us over as prey to their teeth.'
EXEC add_BibleVerse @BibleId, 119124007, N'We escaped with our lives, like a bird from a hunter’s snare. The snare broke, and we escaped.'
EXEC add_BibleVerse @BibleId, 119124008, N'Our deliverer is the Lord, the Creator of heaven and earth.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119125001, @markup=N'Those who trust in the Lord are like Mount Zion; it cannot be upended and will endure forever. ', @premarkup=N'A song of ascents.'
EXEC add_BibleVerse @BibleId, 119125002, N'As the mountains surround Jerusalem, so the Lord surrounds his people, now and forevermore.'
EXEC add_BibleVerse @BibleId, 119125003, N'Indeed, the scepter of a wicked king will not settle upon the allotted land of the godly. Otherwise the godly might do what is wrong.'
EXEC add_BibleVerse @BibleId, 119125004, N'Do good, O Lord, to those who are good, to the morally upright!'
EXEC add_BibleVerse @BibleId, 119125005, N'As for those who are bent on traveling a sinful path, may the Lord remove them, along with those who behave wickedly! May Israel experience peace!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119126001, @markup=N'When the Lord restored the well-being of Zion, we thought we were dreaming. ', @premarkup=N'A song of ascents.'
EXEC add_BibleVerse @BibleId, 119126002, N'At that time we laughed loudly and shouted for joy. At that time the nations said, “The Lord has accomplished great things for these people.”'
EXEC add_BibleVerse @BibleId, 119126003, N'The Lord did indeed accomplish great things for us. We were happy.'
EXEC add_BibleVerse @BibleId, 119126004, N'O Lord, restore our well-being, just as the streams in the arid south are replenished.'
EXEC add_BibleVerse @BibleId, 119126005, N'Those who shed tears as they plant will shout for joy when they reap the harvest.'
EXEC add_BibleVerse @BibleId, 119126006, N'The one who weeps as he walks along, carrying his bag of seed, will certainly come in with a shout of joy, carrying his sheaves of grain.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119127001, @markup=N'If the Lord does not build a house, then those who build it work in vain. If the Lord does not guard a city, then the watchman stands guard in vain. ', @premarkup=N'A song of ascents, by Solomon.'
EXEC add_BibleVerse @BibleId, 119127002, N'It is vain for you to rise early, come home late, and work so hard for your food. Yes, he can provide for those whom he loves even when they sleep.'
EXEC add_BibleVerse @BibleId, 119127003, N'Yes, sons are a gift from the Lord, the fruit of the womb is a reward.'
EXEC add_BibleVerse @BibleId, 119127004, N'Sons born during one’s youth are like arrows in a warrior’s hand.'
EXEC add_BibleVerse @BibleId, 119127005, N'How blessed is the man who fills his quiver with them! They will not be put to shame when they confront enemies at the city gate.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119128001, @markup=N'How blessed is every one of the Lord’s loyal followers, each one who keeps his commands! ', @premarkup=N'A song of ascents.'
EXEC add_BibleVerse @BibleId, 119128002, N'You will eat what you worked so hard to grow. You will be blessed and secure.'
EXEC add_BibleVerse @BibleId, 119128003, N'Your wife will be like a fruitful vine in the inner rooms of your house; your children will be like olive branches, as they sit all around your table.'
EXEC add_BibleVerse @BibleId, 119128004, N'Yes indeed, the man who fears the Lord will be blessed in this way.'
EXEC add_BibleVerse @BibleId, 119128005, N'May the Lord bless you from Zion, that you might see Jerusalem prosper all the days of your life,'
EXEC add_BibleVerse @BibleId, 119128006, N'and that you might see your grandchildren. May Israel experience peace!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119129001, @markup=N'“Since my youth they have often attacked me,” let Israel say. ', @premarkup=N'A song of ascents.'
EXEC add_BibleVerse @BibleId, 119129002, N'“Since my youth they have often attacked me, but they have not defeated me.'
EXEC add_BibleVerse @BibleId, 119129003, N'The plowers plowed my back; they made their furrows long.'
EXEC add_BibleVerse @BibleId, 119129004, N'The Lord is just; he cut the ropes of the wicked.”'
EXEC add_BibleVerse @BibleId, 119129005, N'May all who hate Zion be humiliated and turned back!'
EXEC add_BibleVerse @BibleId, 119129006, N'May they be like the grass on the rooftops which withers before one can even pull it up,'
EXEC add_BibleVerse @BibleId, 119129007, N'which cannot fill the reaper’s hand, or the lap of the one who gathers the grain!'
EXEC add_BibleVerse @BibleId, 119129008, N'Those who pass by will not say, “May you experience the Lord’s blessing! We pronounce a blessing on you in the name of the Lord.”'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119130001, @markup=N'From the deep water I cry out to you, O Lord. ', @premarkup=N'A song of ascents.'
EXEC add_BibleVerse @BibleId, 119130002, N'O Lord, listen to me! Pay attention to my plea for mercy!'
EXEC add_BibleVerse @BibleId, 119130003, N'If you, O Lord, were to keep track of sins, O Lord, who could stand before you?'
EXEC add_BibleVerse @BibleId, 119130004, N'But you are willing to forgive, so that you might be honored.'
EXEC add_BibleVerse @BibleId, 119130005, N'I rely on the Lord, I rely on him with my whole being; I wait for his assuring word.'
EXEC add_BibleVerse @BibleId, 119130006, N'I yearn for the Lord, more than watchmen do for the morning, yes, more than watchmen do for the morning.'
EXEC add_BibleVerse @BibleId, 119130007, N'O Israel, hope in the Lord, for the Lord exhibits loyal love, and is more than willing to deliver.'
EXEC add_BibleVerse @BibleId, 119130008, N'He will deliver Israel from all the consequences of their sins.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119131001, @markup=N'O Lord, my heart is not proud, nor do I have a haughty look. I do not have great aspirations, or concern myself with things that are beyond me. ', @premarkup=N'A song of ascents, by David.'
EXEC add_BibleVerse @BibleId, 119131002, N'Indeed I am composed and quiet, like a young child carried by its mother; I am content like the young child I carry.'
EXEC add_BibleVerse @BibleId, 119131003, N'O Israel, hope in the Lord now and forevermore!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119132001, @markup=N'O Lord, for David’s sake remember all his strenuous effort, ', @premarkup=N'A song of ascents.'
EXEC add_BibleVerse @BibleId, 119132002, N'and how he made a vow to the Lord, and swore an oath to the powerful ruler of Jacob.'
EXEC add_BibleVerse @BibleId, 119132003, N'He said, “I will not enter my own home, or get into my bed.'
EXEC add_BibleVerse @BibleId, 119132004, N'I will not allow my eyes to sleep, or my eyelids to slumber,'
EXEC add_BibleVerse @BibleId, 119132005, N'until I find a place for the Lord, a fine dwelling place for the powerful ruler of Jacob.”'
EXEC add_BibleVerse @BibleId, 119132006, N'Look, we heard about it in Ephrathah, we found it in the territory of Jaar.'
EXEC add_BibleVerse @BibleId, 119132007, N'Let us go to his dwelling place! Let us worship before his footstool!'
EXEC add_BibleVerse @BibleId, 119132008, N'Ascend, O Lord, to your resting place, you and the ark of your strength!'
EXEC add_BibleVerse @BibleId, 119132009, N'May your priests be clothed with integrity! May your loyal followers shout for joy!'
EXEC add_BibleVerse @BibleId, 119132010, N'For the sake of David, your servant, do not reject your chosen king!'
EXEC add_BibleVerse @BibleId, 119132011, N'The Lord made a reliable promise to David; he will not go back on his word. He said, “I will place one of your descendants on your throne.'
EXEC add_BibleVerse @BibleId, 119132012, N'If your sons keep my covenant and the rules I teach them, their sons will also sit on your throne forever.”'
EXEC add_BibleVerse @BibleId, 119132013, N'Certainly the Lord has chosen Zion; he decided to make it his home.'
EXEC add_BibleVerse @BibleId, 119132014, N'He said, “This will be my resting place forever; I will live here, for I have chosen it.'
EXEC add_BibleVerse @BibleId, 119132015, N'I will abundantly supply what she needs; I will give her poor all the food they need.'
EXEC add_BibleVerse @BibleId, 119132016, N'I will protect her priests, and her godly people will shout exuberantly.'
EXEC add_BibleVerse @BibleId, 119132017, N'There I will make David strong; I have determined that my chosen king’s dynasty will continue.'
EXEC add_BibleVerse @BibleId, 119132018, N'I will humiliate his enemies, and his crown will shine.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119133001, @markup=N'Look! How good and how pleasant it is when brothers live together! ', @premarkup=N'A song of ascents, by David.'
EXEC add_BibleVerse @BibleId, 119133002, N'It is like fine oil poured on the head which flows down the beard – Aaron’s beard, and then flows down his garments.'
EXEC add_BibleVerse @BibleId, 119133003, N'It is like the dew of Hermon, which flows down upon the hills of Zion. Indeed that is where the Lord has decreed a blessing will be available – eternal life.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119134001, @markup=N'Attention! Praise the Lord, all you servants of the Lord, who serve in the Lord’s temple during the night. ', @premarkup=N'A song of ascents.'
EXEC add_BibleVerse @BibleId, 119134002, N'Lift your hands toward the sanctuary and praise the Lord!'
EXEC add_BibleVerse @BibleId, 119134003, N'May the Lord, the Creator of heaven and earth, bless you from Zion!'
EXEC add_BibleVerse @BibleId, 119135001, N'Praise the Lord! Praise the name of the Lord! Offer praise, you servants of the Lord,'
EXEC add_BibleVerse @BibleId, 119135002, N'who serve in the Lord’s temple, in the courts of the temple of our God.'
EXEC add_BibleVerse @BibleId, 119135003, N'Praise the Lord, for the Lord is good! Sing praises to his name, for it is pleasant!'
EXEC add_BibleVerse @BibleId, 119135004, N'Indeed, the Lord has chosen Jacob for himself, Israel to be his special possession.'
EXEC add_BibleVerse @BibleId, 119135005, N'Yes, I know the Lord is great, and our Lord is superior to all gods.'
EXEC add_BibleVerse @BibleId, 119135006, N'He does whatever he pleases in heaven and on earth, in the seas and all the ocean depths.'
EXEC add_BibleVerse @BibleId, 119135007, N'He causes the clouds to arise from the end of the earth, makes lightning bolts accompany the rain, and brings the wind out of his storehouses.'
EXEC add_BibleVerse @BibleId, 119135008, N'He struck down the firstborn of Egypt, including both men and animals.'
EXEC add_BibleVerse @BibleId, 119135009, N'He performed awesome deeds and acts of judgment in your midst, O Egypt, against Pharaoh and all his servants.'
EXEC add_BibleVerse @BibleId, 119135010, N'He defeated many nations, and killed mighty kings –'
EXEC add_BibleVerse @BibleId, 119135011, N'Sihon, king of the Amorites, and Og, king of Bashan, and all the kingdoms of Canaan.'
EXEC add_BibleVerse @BibleId, 119135012, N'He gave their land as an inheritance, as an inheritance to Israel his people.'
EXEC add_BibleVerse @BibleId, 119135013, N'O Lord, your name endures, your reputation, O Lord, lasts.'
EXEC add_BibleVerse @BibleId, 119135014, N'For the Lord vindicates his people, and has compassion on his servants.'
EXEC add_BibleVerse @BibleId, 119135015, N'The nations’ idols are made of silver and gold, they are man-made.'
EXEC add_BibleVerse @BibleId, 119135016, N'They have mouths, but cannot speak, eyes, but cannot see,'
EXEC add_BibleVerse @BibleId, 119135017, N'and ears, but cannot hear. Indeed, they cannot breathe.'
EXEC add_BibleVerse @BibleId, 119135018, N'Those who make them will end up like them, as will everyone who trusts in them.'
EXEC add_BibleVerse @BibleId, 119135019, N'O family of Israel, praise the Lord! O family of Aaron, praise the Lord!'
EXEC add_BibleVerse @BibleId, 119135020, N'O family of Levi, praise the Lord! You loyal followers of the Lord, praise the Lord!'
EXEC add_BibleVerse @BibleId, 119135021, N'The Lord deserves praise in Zion – he who dwells in Jerusalem. Praise the Lord!'
EXEC add_BibleVerse @BibleId, 119136001, N'Give thanks to the Lord, for he is good, for his loyal love endures.'
EXEC add_BibleVerse @BibleId, 119136002, N'Give thanks to the God of gods, for his loyal love endures.'
EXEC add_BibleVerse @BibleId, 119136003, N'Give thanks to the Lord of lords, for his loyal love endures,'
EXEC add_BibleVerse @BibleId, 119136004, N'to the one who performs magnificent, amazing deeds all by himself, for his loyal love endures,'
EXEC add_BibleVerse @BibleId, 119136005, N'to the one who used wisdom to make the heavens, for his loyal love endures,'
EXEC add_BibleVerse @BibleId, 119136006, N'to the one who spread out the earth over the water, for his loyal love endures,'
EXEC add_BibleVerse @BibleId, 119136007, N'to the one who made the great lights, for his loyal love endures,'
EXEC add_BibleVerse @BibleId, 119136008, N'the sun to rule by day, for his loyal love endures,'
EXEC add_BibleVerse @BibleId, 119136009, N'the moon and stars to rule by night, for his loyal love endures,'
EXEC add_BibleVerse @BibleId, 119136010, N'to the one who struck down the firstborn of Egypt, for his loyal love endures,'
EXEC add_BibleVerse @BibleId, 119136011, N'and led Israel out from their midst, for his loyal love endures,'
EXEC add_BibleVerse @BibleId, 119136012, N'with a strong hand and an outstretched arm, for his loyal love endures,'
EXEC add_BibleVerse @BibleId, 119136013, N'to the one who divided the Red Sea in two, for his loyal love endures,'
EXEC add_BibleVerse @BibleId, 119136014, N'and led Israel through its midst, for his loyal love endures,'
EXEC add_BibleVerse @BibleId, 119136015, N'and tossed Pharaoh and his army into the Red Sea, for his loyal love endures,'
EXEC add_BibleVerse @BibleId, 119136016, N'to the one who led his people through the wilderness, for his loyal love endures,'
EXEC add_BibleVerse @BibleId, 119136017, N'to the one who struck down great kings, for his loyal love endures,'
EXEC add_BibleVerse @BibleId, 119136018, N'and killed powerful kings, for his loyal love endures,'
EXEC add_BibleVerse @BibleId, 119136019, N'Sihon, king of the Amorites, for his loyal love endures,'
EXEC add_BibleVerse @BibleId, 119136020, N'Og, king of Bashan, for his loyal love endures,'
EXEC add_BibleVerse @BibleId, 119136021, N'and gave their land as an inheritance, for his loyal love endures,'
EXEC add_BibleVerse @BibleId, 119136022, N'as an inheritance to Israel his servant, for his loyal love endures,'
EXEC add_BibleVerse @BibleId, 119136023, N'to the one who remembered us when we were down, for his loyal love endures,'
EXEC add_BibleVerse @BibleId, 119136024, N'and snatched us away from our enemies, for his loyal love endures,'
EXEC add_BibleVerse @BibleId, 119136025, N'to the one who gives food to all living things, for his loyal love endures.'
EXEC add_BibleVerse @BibleId, 119136026, N'Give thanks to the God of heaven, for his loyal love endures!'
EXEC add_BibleVerse @BibleId, 119137001, N'By the rivers of Babylon we sit down and weep when we remember Zion.'
EXEC add_BibleVerse @BibleId, 119137002, N'On the poplars in her midst we hang our harps,'
EXEC add_BibleVerse @BibleId, 119137003, N'for there our captors ask us to compose songs; those who mock us demand that we be happy, saying: “Sing for us a song about Zion!”'
EXEC add_BibleVerse @BibleId, 119137004, N'How can we sing a song to the Lord in a foreign land?'
EXEC add_BibleVerse @BibleId, 119137005, N'If I forget you, O Jerusalem, may my right hand be crippled!'
EXEC add_BibleVerse @BibleId, 119137006, N'May my tongue stick to the roof of my mouth, if I do not remember you, and do not give Jerusalem priority over whatever gives me the most joy.'
EXEC add_BibleVerse @BibleId, 119137007, N'Remember, O Lord, what the Edomites did on the day Jerusalem fell. They said, “Tear it down, tear it down, right to its very foundation!”'
EXEC add_BibleVerse @BibleId, 119137008, N'O daughter Babylon, soon to be devastated! How blessed will be the one who repays you for what you dished out to us!'
EXEC add_BibleVerse @BibleId, 119137009, N'How blessed will be the one who grabs your babies and smashes them on a rock!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119138001, @markup=N'I will give you thanks with all my heart; before the heavenly assembly I will sing praises to you. ', @premarkup=N'By David.'
EXEC add_BibleVerse @BibleId, 119138002, N'I will bow down toward your holy temple, and give thanks to your name, because of your loyal love and faithfulness, for you have exalted your promise above the entire sky.'
EXEC add_BibleVerse @BibleId, 119138003, N'When I cried out for help, you answered me. You made me bold and energized me.'
EXEC add_BibleVerse @BibleId, 119138004, N'Let all the kings of the earth give thanks to you, O Lord, when they hear the words you speak.'
EXEC add_BibleVerse @BibleId, 119138005, N'Let them sing about the Lord’s deeds, for the Lord’s splendor is magnificent.'
EXEC add_BibleVerse @BibleId, 119138006, N'Though the Lord is exalted, he takes note of the lowly, and recognizes the proud from far away.'
EXEC add_BibleVerse @BibleId, 119138007, N'Even when I must walk in the midst of danger, you revive me. You oppose my angry enemies, and your right hand delivers me.'
EXEC add_BibleVerse @BibleId, 119138008, N'The Lord avenges me. O Lord, your loyal love endures. Do not abandon those whom you have made!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119139001, @markup=N'O Lord, you examine me and know. ', @premarkup=N'For the music director, a psalm of David.'
EXEC add_BibleVerse @BibleId, 119139002, N'You know when I sit down and when I get up; even from far away you understand my motives.'
EXEC add_BibleVerse @BibleId, 119139003, N'You carefully observe me when I travel or when I lie down to rest; you are aware of everything I do.'
EXEC add_BibleVerse @BibleId, 119139004, N'Certainly my tongue does not frame a word without you, O Lord, being thoroughly aware of it.'
EXEC add_BibleVerse @BibleId, 119139005, N'You squeeze me in from behind and in front; you place your hand on me.'
EXEC add_BibleVerse @BibleId, 119139006, N'Your knowledge is beyond my comprehension; it is so far beyond me, I am unable to fathom it.'
EXEC add_BibleVerse @BibleId, 119139007, N'Where can I go to escape your spirit? Where can I flee to escape your presence?'
EXEC add_BibleVerse @BibleId, 119139008, N'If I were to ascend to heaven, you would be there. If I were to sprawl out in Sheol, there you would be.'
EXEC add_BibleVerse @BibleId, 119139009, N'If I were to fly away on the wings of the dawn, and settle down on the other side of the sea,'
EXEC add_BibleVerse @BibleId, 119139010, N'even there your hand would guide me, your right hand would grab hold of me.'
EXEC add_BibleVerse @BibleId, 119139011, N'If I were to say, “Certainly the darkness will cover me, and the light will turn to night all around me,”'
EXEC add_BibleVerse @BibleId, 119139012, N'even the darkness is not too dark for you to see, and the night is as bright as day; darkness and light are the same to you.'
EXEC add_BibleVerse @BibleId, 119139013, N'Certainly you made my mind and heart; you wove me together in my mother’s womb.'
EXEC add_BibleVerse @BibleId, 119139014, N'I will give you thanks because your deeds are awesome and amazing. You knew me thoroughly;'
EXEC add_BibleVerse @BibleId, 119139015, N'my bones were not hidden from you, when I was made in secret and sewed together in the depths of the earth.'
EXEC add_BibleVerse @BibleId, 119139016, N'Your eyes saw me when I was inside the womb. All the days ordained for me were recorded in your scroll before one of them came into existence.'
EXEC add_BibleVerse @BibleId, 119139017, N'How difficult it is for me to fathom your thoughts about me, O God! How vast is their sum total!'
EXEC add_BibleVerse @BibleId, 119139018, N'If I tried to count them, they would outnumber the grains of sand. Even if I finished counting them, I would still have to contend with you.'
EXEC add_BibleVerse @BibleId, 119139019, N'If only you would kill the wicked, O God! Get away from me, you violent men!'
EXEC add_BibleVerse @BibleId, 119139020, N'They rebel against you and act deceitfully; your enemies lie.'
EXEC add_BibleVerse @BibleId, 119139021, N'O Lord, do I not hate those who hate you, and despise those who oppose you?'
EXEC add_BibleVerse @BibleId, 119139022, N'I absolutely hate them, they have become my enemies!'
EXEC add_BibleVerse @BibleId, 119139023, N'Examine me, and probe my thoughts! Test me, and know my concerns!'
EXEC add_BibleVerse @BibleId, 119139024, N'See if there is any idolatrous tendency in me, and lead me in the reliable ancient path!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119140001, @markup=N'O Lord, rescue me from wicked men! Protect me from violent men, ', @premarkup=N'For the music director; a psalm of David.'
EXEC add_BibleVerse @BibleId, 119140002, N'who plan ways to harm me. All day long they stir up conflict.'
EXEC add_BibleVerse @BibleId, 119140003, N'Their tongues wound like a serpent; a viper’s venom is behind their lips. (Selah)'
EXEC add_BibleVerse @BibleId, 119140004, N'O Lord, shelter me from the power of the wicked! Protect me from violent men, who plan to knock me over.'
EXEC add_BibleVerse @BibleId, 119140005, N'Proud men hide a snare for me; evil men spread a net by the path; they set traps for me. (Selah)'
EXEC add_BibleVerse @BibleId, 119140006, N'I say to the Lord, “You are my God.” O Lord, pay attention to my plea for mercy!'
EXEC add_BibleVerse @BibleId, 119140007, N'O sovereign Lord, my strong deliverer, you shield my head in the day of battle.'
EXEC add_BibleVerse @BibleId, 119140008, N'O Lord, do not let the wicked have their way! Do not allow their plan to succeed when they attack! (Selah)'
EXEC add_BibleVerse @BibleId, 119140009, N'As for the heads of those who surround me – may the harm done by their lips overwhelm them!'
EXEC add_BibleVerse @BibleId, 119140010, N'May he rain down fiery coals upon them! May he throw them into the fire! From bottomless pits they will not escape.'
EXEC add_BibleVerse @BibleId, 119140011, N'A slanderer will not endure on the earth; calamity will hunt down a violent man and strike him down.'
EXEC add_BibleVerse @BibleId, 119140012, N'I know that the Lord defends the cause of the oppressed and vindicates the poor.'
EXEC add_BibleVerse @BibleId, 119140013, N'Certainly the godly will give thanks to your name; the morally upright will live in your presence.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119141001, @markup=N'O Lord, I cry out to you. Come quickly to me! Pay attention to me when I cry out to you! ', @premarkup=N'A Psalm of David.'
EXEC add_BibleVerse @BibleId, 119141002, N'May you accept my prayer like incense, my uplifted hands like the evening offering!'
EXEC add_BibleVerse @BibleId, 119141003, N'O Lord, place a guard on my mouth! Protect the opening of my lips!'
EXEC add_BibleVerse @BibleId, 119141004, N'Do not let me have evil desires, or participate in sinful activities with men who behave wickedly. I will not eat their delicacies.'
EXEC add_BibleVerse @BibleId, 119141005, N'May the godly strike me in love and correct me! May my head not refuse choice oil! Indeed, my prayer is a witness against their evil deeds.'
EXEC add_BibleVerse @BibleId, 119141006, N'They will be thrown down the side of a cliff by their judges. They will listen to my words, for they are pleasant.'
EXEC add_BibleVerse @BibleId, 119141007, N'As when one plows and breaks up the soil, so our bones are scattered at the mouth of Sheol.'
EXEC add_BibleVerse @BibleId, 119141008, N'Surely I am looking to you, O sovereign Lord. In you I take shelter. Do not expose me to danger!'
EXEC add_BibleVerse @BibleId, 119141009, N'Protect me from the snare they have laid for me, and the traps the evildoers have set.'
EXEC add_BibleVerse @BibleId, 119141010, N'Let the wicked fall into their own nets, while I escape.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119142001, @markup=N'To the Lord I cry out; to the Lord I plead for mercy. ', @premarkup=N'A well-written song by David, when he was in the cave; a prayer.'
EXEC add_BibleVerse @BibleId, 119142002, N'I pour out my lament before him; I tell him about my troubles.'
EXEC add_BibleVerse @BibleId, 119142003, N'Even when my strength leaves me, you watch my footsteps. In the path where I walk they have hidden a trap for me.'
EXEC add_BibleVerse @BibleId, 119142004, N'Look to the right and see! No one cares about me. I have nowhere to run; no one is concerned about my life.'
EXEC add_BibleVerse @BibleId, 119142005, N'I cry out to you, O Lord; I say, “You are my shelter, my security in the land of the living.”'
EXEC add_BibleVerse @BibleId, 119142006, N'Listen to my cry for help, for I am in serious trouble! Rescue me from those who chase me, for they are stronger than I am.'
EXEC add_BibleVerse @BibleId, 119142007, N'Free me from prison, that I may give thanks to your name. Because of me the godly will assemble, for you will vindicate me.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119143001, @markup=N'O Lord, hear my prayer! Pay attention to my plea for help! Because of your faithfulness and justice, answer me! ', @premarkup=N'A Psalm of David.'
EXEC add_BibleVerse @BibleId, 119143002, N'Do not sit in judgment on your servant, for no one alive is innocent before you.'
EXEC add_BibleVerse @BibleId, 119143003, N'Certainly my enemies chase me. They smash me into the ground. They force me to live in dark regions, like those who have been dead for ages.'
EXEC add_BibleVerse @BibleId, 119143004, N'My strength leaves me; I am absolutely shocked.'
EXEC add_BibleVerse @BibleId, 119143005, N'I recall the old days; I meditate on all you have done; I reflect on your accomplishments.'
EXEC add_BibleVerse @BibleId, 119143006, N'I spread my hands out to you in prayer; my soul thirsts for you in a parched land.'
EXEC add_BibleVerse @BibleId, 119143007, N'Answer me quickly, Lord! My strength is fading. Do not reject me, or I will join those descending into the grave.'
EXEC add_BibleVerse @BibleId, 119143008, N'May I hear about your loyal love in the morning, for I trust in you. Show me the way I should go, because I long for you.'
EXEC add_BibleVerse @BibleId, 119143009, N'Rescue me from my enemies, O Lord! I run to you for protection.'
EXEC add_BibleVerse @BibleId, 119143010, N'Teach me to do what pleases you, for you are my God. May your kind presence lead me into a level land.'
EXEC add_BibleVerse @BibleId, 119143011, N'O Lord, for the sake of your reputation, revive me! Because of your justice, rescue me from trouble!'
EXEC add_BibleVerse @BibleId, 119143012, N'As a demonstration of your loyal love, destroy my enemies! Annihilate all who threaten my life, for I am your servant.'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119144001, @markup=N'The Lord, my protector, deserves praise – the one who trains my hands for battle, and my fingers for war, ', @premarkup=N'By David.'
EXEC add_BibleVerse @BibleId, 119144002, N'who loves me and is my stronghold, my refuge and my deliverer, my shield and the one in whom I take shelter, who makes nations submit to me.'
EXEC add_BibleVerse @BibleId, 119144003, N'O Lord, of what importance is the human race, that you should notice them? Of what importance is mankind, that you should be concerned about them?'
EXEC add_BibleVerse @BibleId, 119144004, N'People are like a vapor, their days like a shadow that disappears.'
EXEC add_BibleVerse @BibleId, 119144005, N'O Lord, make the sky sink and come down! Touch the mountains and make them smolder!'
EXEC add_BibleVerse @BibleId, 119144006, N'Hurl lightning bolts and scatter them! Shoot your arrows and rout them!'
EXEC add_BibleVerse @BibleId, 119144007, N'Reach down from above! Grab me and rescue me from the surging water, from the power of foreigners,'
EXEC add_BibleVerse @BibleId, 119144008, N'who speak lies, and make false promises.'
EXEC add_BibleVerse @BibleId, 119144009, N'O God, I will sing a new song to you! Accompanied by a ten-stringed instrument, I will sing praises to you,'
EXEC add_BibleVerse @BibleId, 119144010, N'the one who delivers kings, and rescued David his servant from a deadly sword.'
EXEC add_BibleVerse @BibleId, 119144011, N'Grab me and rescue me from the power of foreigners, who speak lies, and make false promises.'
EXEC add_BibleVerse @BibleId, 119144012, N'Then our sons will be like plants, that quickly grow to full size. Our daughters will be like corner pillars, carved like those in a palace.'
EXEC add_BibleVerse @BibleId, 119144013, N'Our storehouses will be full, providing all kinds of food. Our sheep will multiply by the thousands and fill our pastures.'
EXEC add_BibleVerse @BibleId, 119144014, N'Our cattle will be weighted down with produce. No one will break through our walls, no one will be taken captive, and there will be no terrified cries in our city squares.'
EXEC add_BibleVerse @BibleId, 119144015, N'How blessed are the people who experience these things! How blessed are the people whose God is the Lord!'
EXEC add_BibleVerse @bibleId=@BibleId, @verseId=119145001, @markup=N'I will extol you, my God, O king! I will praise your name continually! ', @premarkup=N'A psalm of praise, by David.'
EXEC add_BibleVerse @BibleId, 119145002, N'Every day I will praise you! I will praise your name continually!'
EXEC add_BibleVerse @BibleId, 119145003, N'The Lord is great and certainly worthy of praise! No one can fathom his greatness!'
EXEC add_BibleVerse @BibleId, 119145004, N'One generation will praise your deeds to another, and tell about your mighty acts!'
EXEC add_BibleVerse @BibleId, 119145005, N'I will focus on your honor and majestic splendor, and your amazing deeds!'
EXEC add_BibleVerse @BibleId, 119145006, N'They will proclaim the power of your awesome acts! I will declare your great deeds!'
EXEC add_BibleVerse @BibleId, 119145007, N'They will talk about the fame of your great kindness, and sing about your justice.'
EXEC add_BibleVerse @BibleId, 119145008, N'The Lord is merciful and compassionate; he is patient and demonstrates great loyal love.'
EXEC add_BibleVerse @BibleId, 119145009, N'The Lord is good to all, and has compassion on all he has made.'
EXEC add_BibleVerse @BibleId, 119145010, N'All he has made will give thanks to the Lord. Your loyal followers will praise you.'
EXEC add_BibleVerse @BibleId, 119145011, N'They will proclaim the splendor of your kingdom; they will tell about your power,'
EXEC add_BibleVerse @BibleId, 119145012, N'so that mankind might acknowledge your mighty acts, and the majestic splendor of your kingdom.'
EXEC add_BibleVerse @BibleId, 119145013, N'Your kingdom is an eternal kingdom, and your dominion endures through all generations.'
EXEC add_BibleVerse @BibleId, 119145014, N'The Lord supports all who fall, and lifts up all who are bent over.'
EXEC add_BibleVerse @BibleId, 119145015, N'Everything looks to you in anticipation, and you provide them with food on a regular basis.'
EXEC add_BibleVerse @BibleId, 119145016, N'You open your hand, and fill every living thing with the food they desire.'
EXEC add_BibleVerse @BibleId, 119145017, N'The Lord is just in all his actions, and exhibits love in all he does.'
EXEC add_BibleVerse @BibleId, 119145018, N'The Lord is near all who cry out to him, all who cry out to him sincerely.'
EXEC add_BibleVerse @BibleId, 119145019, N'He satisfies the desire of his loyal followers; he hears their cry for help and delivers them.'
EXEC add_BibleVerse @BibleId, 119145020, N'The Lord protects those who love him, but he destroys all the wicked.'
EXEC add_BibleVerse @BibleId, 119145021, N'My mouth will praise the Lord. Let all who live praise his holy name forever!'
EXEC add_BibleVerse @BibleId, 119146001, N'Praise the Lord! Praise the Lord, O my soul!'
EXEC add_BibleVerse @BibleId, 119146002, N'I will praise the Lord as long as I live! I will sing praises to my God as long as I exist!'
EXEC add_BibleVerse @BibleId, 119146003, N'Do not trust in princes, or in human beings, who cannot deliver!'
EXEC add_BibleVerse @BibleId, 119146004, N'Their life’s breath departs, they return to the ground; on that day their plans die.'
EXEC add_BibleVerse @BibleId, 119146005, N'How blessed is the one whose helper is the God of Jacob, whose hope is in the Lord his God,'
EXEC add_BibleVerse @BibleId, 119146006, N'the one who made heaven and earth, the sea, and all that is in them, who remains forever faithful,'
EXEC add_BibleVerse @BibleId, 119146007, N'vindicates the oppressed, and gives food to the hungry. The Lord releases the imprisoned.'
EXEC add_BibleVerse @BibleId, 119146008, N'The Lord gives sight to the blind. The Lord lifts up all who are bent over. The Lord loves the godly.'
EXEC add_BibleVerse @BibleId, 119146009, N'The Lord protects those residing outside their native land; he lifts up the fatherless and the widow, but he opposes the wicked.'
EXEC add_BibleVerse @BibleId, 119146010, N'The Lord rules forever, your God, O Zion, throughout the generations to come! Praise the Lord!'
EXEC add_BibleVerse @BibleId, 119147001, N'Praise the Lord, for it is good to sing praises to our God! Yes, praise is pleasant and appropriate!'
EXEC add_BibleVerse @BibleId, 119147002, N'The Lord rebuilds Jerusalem, and gathers the exiles of Israel.'
EXEC add_BibleVerse @BibleId, 119147003, N'He heals the brokenhearted, and bandages their wounds.'
EXEC add_BibleVerse @BibleId, 119147004, N'He counts the number of the stars; he names all of them.'
EXEC add_BibleVerse @BibleId, 119147005, N'Our Lord is great and has awesome power; there is no limit to his wisdom.'
EXEC add_BibleVerse @BibleId, 119147006, N'The Lord lifts up the oppressed, but knocks the wicked to the ground.'
EXEC add_BibleVerse @BibleId, 119147007, N'Offer to the Lord a song of thanks! Sing praises to our God to the accompaniment of a harp!'
EXEC add_BibleVerse @BibleId, 119147008, N'He covers the sky with clouds, provides the earth with rain, and causes grass to grow on the hillsides.'
EXEC add_BibleVerse @BibleId, 119147009, N'He gives food to the animals, and to the young ravens when they chirp.'
EXEC add_BibleVerse @BibleId, 119147010, N'He is not enamored with the strength of a horse, nor is he impressed by the warrior’s strong legs.'
EXEC add_BibleVerse @BibleId, 119147011, N'The Lord takes delight in his faithful followers, and in those who wait for his loyal love.'
EXEC add_BibleVerse @BibleId, 119147012, N'Extol the Lord, O Jerusalem! Praise your God, O Zion!'
EXEC add_BibleVerse @BibleId, 119147013, N'For he makes the bars of your gates strong. He blesses your children within you.'
EXEC add_BibleVerse @BibleId, 119147014, N'He brings peace to your territory. He abundantly provides for you the best grain.'
EXEC add_BibleVerse @BibleId, 119147015, N'He sends his command through the earth; swiftly his order reaches its destination.'
EXEC add_BibleVerse @BibleId, 119147016, N'He sends the snow that is white like wool; he spreads the frost that is white like ashes.'
EXEC add_BibleVerse @BibleId, 119147017, N'He throws his hailstones like crumbs. Who can withstand the cold wind he sends?'
EXEC add_BibleVerse @BibleId, 119147018, N'He then orders it all to melt; he breathes on it, and the water flows.'
EXEC add_BibleVerse @BibleId, 119147019, N'He proclaims his word to Jacob, his statutes and regulations to Israel.'
EXEC add_BibleVerse @BibleId, 119147020, N'He has not done so with any other nation; they are not aware of his regulations. Praise the Lord!'
EXEC add_BibleVerse @BibleId, 119148001, N'Praise the Lord! Praise the Lord from the sky! Praise him in the heavens!'
EXEC add_BibleVerse @BibleId, 119148002, N'Praise him, all his angels! Praise him, all his heavenly assembly!'
EXEC add_BibleVerse @BibleId, 119148003, N'Praise him, O sun and moon! Praise him, all you shiny stars!'
EXEC add_BibleVerse @BibleId, 119148004, N'Praise him, O highest heaven, and you waters above the sky!'
EXEC add_BibleVerse @BibleId, 119148005, N'Let them praise the name of the Lord, for he gave the command and they came into existence.'
EXEC add_BibleVerse @BibleId, 119148006, N'He established them so they would endure; he issued a decree that will not be revoked.'
EXEC add_BibleVerse @BibleId, 119148007, N'Praise the Lord from the earth, you sea creatures and all you ocean depths,'
EXEC add_BibleVerse @BibleId, 119148008, N'O fire and hail, snow and clouds, O stormy wind that carries out his orders,'
EXEC add_BibleVerse @BibleId, 119148009, N'you mountains and all you hills, you fruit trees and all you cedars,'
EXEC add_BibleVerse @BibleId, 119148010, N'you animals and all you cattle, you creeping things and birds,'
EXEC add_BibleVerse @BibleId, 119148011, N'you kings of the earth and all you nations, you princes and all you leaders on the earth,'
EXEC add_BibleVerse @BibleId, 119148012, N'you young men and young women, you elderly, along with you children!'
EXEC add_BibleVerse @BibleId, 119148013, N'Let them praise the name of the Lord, for his name alone is exalted; his majesty extends over the earth and sky.'
EXEC add_BibleVerse @BibleId, 119148014, N'He has made his people victorious, and given all his loyal followers reason to praise – the Israelites, the people who are close to him. Praise the Lord!'
EXEC add_BibleVerse @BibleId, 119149001, N'Praise the Lord! Sing to the Lord a new song! Praise him in the assembly of the godly!'
EXEC add_BibleVerse @BibleId, 119149002, N'Let Israel rejoice in their Creator! Let the people of Zion delight in their king!'
EXEC add_BibleVerse @BibleId, 119149003, N'Let them praise his name with dancing! Let them sing praises to him to the accompaniment of the tambourine and harp!'
EXEC add_BibleVerse @BibleId, 119149004, N'For the Lord takes delight in his people; he exalts the oppressed by delivering them.'
EXEC add_BibleVerse @BibleId, 119149005, N'Let the godly rejoice because of their vindication! Let them shout for joy upon their beds!'
EXEC add_BibleVerse @BibleId, 119149006, N'May they praise God while they hold a two-edged sword in their hand,'
EXEC add_BibleVerse @BibleId, 119149007, N'in order to take revenge on the nations, and punish foreigners.'
EXEC add_BibleVerse @BibleId, 119149008, N'They bind their kings in chains, and their nobles in iron shackles,'
EXEC add_BibleVerse @BibleId, 119149009, N'and execute the judgment to which their enemies have been sentenced. All his loyal followers will be vindicated. Praise the Lord!'
EXEC add_BibleVerse @BibleId, 119150001, N'Praise the Lord! Praise God in his sanctuary! Praise him in the sky, which testifies to his strength!'
EXEC add_BibleVerse @BibleId, 119150002, N'Praise him for his mighty acts! Praise him for his surpassing greatness!'
EXEC add_BibleVerse @BibleId, 119150003, N'Praise him with the blast of the horn! Praise him with the lyre and the harp!'
EXEC add_BibleVerse @BibleId, 119150004, N'Praise him with the tambourine and with dancing! Praise him with stringed instruments and the flute!'
EXEC add_BibleVerse @BibleId, 119150005, N'Praise him with loud cymbals! Praise him with clanging cymbals!'
EXEC add_BibleVerse @BibleId, 119150006, N'Let everything that has breath praise the Lord! Praise the Lord!'
EXEC add_BibleVerse @BibleId, 120001001, N'The Proverbs of Solomon son of David, king of Israel:'
EXEC add_BibleVerse @BibleId, 120001002, N'To learn wisdom and moral instruction, and to discern wise counsel.'
EXEC add_BibleVerse @BibleId, 120001003, N'To receive moral instruction in skillful living, in righteousness, justice, and equity.'
EXEC add_BibleVerse @BibleId, 120001004, N'To impart shrewdness to the morally naive, and a discerning plan to the young person.'
EXEC add_BibleVerse @BibleId, 120001005, N'(Let the wise also hear and gain instruction, and let the discerning acquire guidance! )'
EXEC add_BibleVerse @BibleId, 120001006, N'To discern the meaning of a proverb and a parable, the sayings of the wise and their riddles.'
EXEC add_BibleVerse @BibleId, 120001007, N'Fearing the Lord is the beginning of moral knowledge, but fools despise wisdom and instruction.'
EXEC add_BibleVerse @BibleId, 120001008, N'Listen, my child, to the instruction from your father, and do not forsake the teaching from your mother.'
EXEC add_BibleVerse @BibleId, 120001009, N'For they will be like an elegant garland on your head, and like pendants around your neck.'
EXEC add_BibleVerse @BibleId, 120001010, N'My child, if sinners try to entice you, do not consent!'
EXEC add_BibleVerse @BibleId, 120001011, N'If they say, “Come with us! We will lie in wait to shed blood; we will ambush an innocent person capriciously.'
EXEC add_BibleVerse @BibleId, 120001012, N'We will swallow them alive like Sheol, those full of vigor like those going down to the Pit.'
EXEC add_BibleVerse @BibleId, 120001013, N'We will seize all kinds of precious wealth; we will fill our houses with plunder.'
EXEC add_BibleVerse @BibleId, 120001014, N'Join with us! We will all share equally in what we steal.”'
EXEC add_BibleVerse @BibleId, 120001015, N'My child, do not go down their way, withhold yourself from their path;'
EXEC add_BibleVerse @BibleId, 120001016, N'for they are eager to inflict harm, and they hasten to shed blood.'
EXEC add_BibleVerse @BibleId, 120001017, N'Surely it is futile to spread a net in plain sight of any bird,'
EXEC add_BibleVerse @BibleId, 120001018, N'but these men lie in wait for their own blood, they ambush their own lives!'
EXEC add_BibleVerse @BibleId, 120001019, N'Such are the ways of all who gain profit unjustly; it takes away the life of those who obtain it!'
EXEC add_BibleVerse @BibleId, 120001020, N'Wisdom calls out in the street, she shouts loudly in the plazas;'
EXEC add_BibleVerse @BibleId, 120001021, N'at the head of the noisy streets she calls, in the entrances of the gates in the city she utters her words:'
EXEC add_BibleVerse @BibleId, 120001022, N'“How long will you simpletons love naiveté? How long will mockers delight in mockery and fools hate knowledge?'
EXEC add_BibleVerse @BibleId, 120001023, N'If only you will respond to my rebuke, then I will pour out my thoughts to you and I will make my words known to you.'
EXEC add_BibleVerse @BibleId, 120001024, N'However, because I called but you refused to listen, because I stretched out my hand but no one paid attention,'
EXEC add_BibleVerse @BibleId, 120001025, N'because you neglected all my advice, and did not comply with my rebuke,'
EXEC add_BibleVerse @BibleId, 120001026, N'so I myself will laugh when disaster strikes you, I will mock when what you dread comes,'
EXEC add_BibleVerse @BibleId, 120001027, N'when what you dread comes like a whirlwind, and disaster strikes you like a devastating storm, when distressing trouble comes on you.'
EXEC add_BibleVerse @BibleId, 120001028, N'Then they will call to me, but I will not answer; they will diligently seek me, but they will not find me.'
EXEC add_BibleVerse @BibleId, 120001029, N'Because they hated moral knowledge, and did not choose to fear the Lord,'
EXEC add_BibleVerse @BibleId, 120001030, N'they did not comply with my advice, they spurned all my rebuke.'
EXEC add_BibleVerse @BibleId, 120001031, N'Therefore they will eat from the fruit of their way, and they will be stuffed full of their own counsel.'
EXEC add_BibleVerse @BibleId, 120001032, N'For the waywardness of the simpletons will kill them, and the careless ease of fools will destroy them.'
EXEC add_BibleVerse @BibleId, 120001033, N'But the one who listens to me will live in security, and will be at ease from the dread of harm.'
EXEC add_BibleVerse @BibleId, 120002001, N'My child, if you receive my words, and store up my commands within you,'
EXEC add_BibleVerse @BibleId, 120002002, N'by making your ear attentive to wisdom, and by turning your heart to understanding,'
EXEC add_BibleVerse @BibleId, 120002003, N'indeed, if you call out for discernment – raise your voice for understanding –'
EXEC add_BibleVerse @BibleId, 120002004, N'if you seek it like silver, and search for it like hidden treasure,'
EXEC add_BibleVerse @BibleId, 120002005, N'then you will understand how to fear the Lord, and you will discover knowledge about God.'
EXEC add_BibleVerse @BibleId, 120002006, N'For the Lord gives wisdom, and from his mouth comes knowledge and understanding.'
EXEC add_BibleVerse @BibleId, 120002007, N'He stores up effective counsel for the upright, and is like a shield for those who live with integrity,'
EXEC add_BibleVerse @BibleId, 120002008, N'to guard the paths of the righteous and to protect the way of his pious ones.'
EXEC add_BibleVerse @BibleId, 120002009, N'Then you will understand righteousness and justice and equity – every good way.'
EXEC add_BibleVerse @BibleId, 120002010, N'For wisdom will enter your heart, and moral knowledge will be attractive to you.'
EXEC add_BibleVerse @BibleId, 120002011, N'Discretion will protect you, understanding will guard you,'
EXEC add_BibleVerse @BibleId, 120002012, N'to deliver you from the way of the wicked, from those speaking perversity,'
EXEC add_BibleVerse @BibleId, 120002013, N'who leave the upright paths to walk on the dark ways,'
EXEC add_BibleVerse @BibleId, 120002014, N'who delight in doing evil, they rejoice in perverse evil;'
EXEC add_BibleVerse @BibleId, 120002015, N'whose paths are morally crooked, and who are devious in their ways;'
EXEC add_BibleVerse @BibleId, 120002016, N'to deliver you from the adulteress, from the sexually loose woman who speaks flattering words;'
EXEC add_BibleVerse @BibleId, 120002017, N'who leaves the husband from her younger days, and forgets her marriage covenant made before God.'
EXEC add_BibleVerse @BibleId, 120002018, N'For her house sinks down to death, and her paths lead to the place of the departed spirits.'
EXEC add_BibleVerse @BibleId, 120002019, N'None who go in to her will return, nor will they reach the paths of life.'
EXEC add_BibleVerse @BibleId, 120002020, N'So you will walk in the way of good people, and will keep on the paths of the righteous.'
EXEC add_BibleVerse @BibleId, 120002021, N'For the upright will reside in the land, and those with integrity will remain in it,'
EXEC add_BibleVerse @BibleId, 120002022, N'but the wicked will be removed from the land, and the treacherous will be torn away from it.'
EXEC add_BibleVerse @BibleId, 120003001, N'My child, do not forget my teaching, but let your heart keep my commandments,'
EXEC add_BibleVerse @BibleId, 120003002, N'for they will provide a long and full life, and they will add well-being to you.'
EXEC add_BibleVerse @BibleId, 120003003, N'Do not let truth and mercy leave you; bind them around your neck, write them on the tablet of your heart.'
EXEC add_BibleVerse @BibleId, 120003004, N'Then you will find favor and good understanding, in the sight of God and people.'
EXEC add_BibleVerse @BibleId, 120003005, N'Trust in the Lord with all your heart, and do not rely on your own understanding.'
EXEC add_BibleVerse @BibleId, 120003006, N'Acknowledge him in all your ways, and he will make your paths straight.'
EXEC add_BibleVerse @BibleId, 120003007, N'Do not be wise in your own estimation; fear the Lord and turn away from evil.'
EXEC add_BibleVerse @BibleId, 120003008, N'This will bring healing to your body, and refreshment to your inner self.'
EXEC add_BibleVerse @BibleId, 120003009, N'Honor the Lord from your wealth and from the first fruits of all your crops;'
EXEC add_BibleVerse @BibleId, 120003010, N'then your barns will be filled completely, and your vats will overflow with new wine.'
EXEC add_BibleVerse @BibleId, 120003011, N'My child, do not despise discipline from the Lord, and do not loathe his rebuke.'
EXEC add_BibleVerse @BibleId, 120003012, N'For the Lord disciplines those he loves, just as a father disciplines the son in whom he delights.'
EXEC add_BibleVerse @BibleId, 120003013, N'Blessed is the one who finds wisdom, and the one who obtains understanding.'
EXEC add_BibleVerse @BibleId, 120003014, N'For her benefit is more profitable than silver, and her gain is better than gold.'
EXEC add_BibleVerse @BibleId, 120003015, N'She is more precious than rubies, and none of the things you desire can compare with her.'
EXEC add_BibleVerse @BibleId, 120003016, N'Long life is in her right hand; in her left hand are riches and honor.'
EXEC add_BibleVerse @BibleId, 120003017, N'Her ways are very pleasant, and all her paths are peaceful.'
EXEC add_BibleVerse @BibleId, 120003018, N'She is like a tree of life to those who obtain her, and everyone who grasps hold of her will be blessed.'
EXEC add_BibleVerse @BibleId, 120003019, N'By wisdom the Lord laid the foundation of the earth; he established the heavens by understanding.'
EXEC add_BibleVerse @BibleId, 120003020, N'By his knowledge the primordial sea was broken open, and the clouds drip down dew.'
EXEC add_BibleVerse @BibleId, 120003021, N'My child, do not let them escape from your sight; safeguard sound wisdom and discretion.'
EXEC add_BibleVerse @BibleId, 120003022, N'So they will give life to you, and grace to adorn your neck.'
EXEC add_BibleVerse @BibleId, 120003023, N'Then you will walk on your way with security, and you will not stumble.'
EXEC add_BibleVerse @BibleId, 120003024, N'When you lie down you will not be filled with fear; when you lie down your sleep will be pleasant.'
EXEC add_BibleVerse @BibleId, 120003025, N'You will not be afraid of sudden disaster, or when destruction overtakes the wicked;'
EXEC add_BibleVerse @BibleId, 120003026, N'for the Lord will be the source of your confidence, and he will guard your foot from being caught in a trap.'
EXEC add_BibleVerse @BibleId, 120003027, N'Do not withhold good from those who need it, when you have the ability to help.'
EXEC add_BibleVerse @BibleId, 120003028, N'Do not say to your neighbor, “Go! Return tomorrow and I will give it,” when you have it with you at the time.'
EXEC add_BibleVerse @BibleId, 120003029, N'Do not plot evil against your neighbor when he dwells by you unsuspectingly.'
EXEC add_BibleVerse @BibleId, 120003030, N'Do not accuse anyone without legitimate cause, if he has not treated you wrongly.'
EXEC add_BibleVerse @BibleId, 120003031, N'Do not envy a violent man, and do not choose to imitate any of his ways;'
EXEC add_BibleVerse @BibleId, 120003032, N'for one who goes astray is an abomination to the Lord, but he reveals his intimate counsel to the upright.'
EXEC add_BibleVerse @BibleId, 120003033, N'The Lord’s curse is on the household of the wicked, but he blesses the home of the righteous.'
EXEC add_BibleVerse @BibleId, 120003034, N'Although he is scornful to arrogant scoffers, yet he shows favor to the humble.'
EXEC add_BibleVerse @BibleId, 120003035, N'The wise inherit honor, but he holds fools up to public contempt.'
EXEC add_BibleVerse @BibleId, 120004001, N'Listen, children, to a father’s instruction, and pay attention so that you may gain discernment.'
EXEC add_BibleVerse @BibleId, 120004002, N'Because I give you good instruction, do not forsake my teaching.'
EXEC add_BibleVerse @BibleId, 120004003, N'When I was a son to my father, a tender only child before my mother,'
EXEC add_BibleVerse @BibleId, 120004004, N'he taught me, and he said to me: “Let your heart lay hold of my words; keep my commands so that you will live.'
EXEC add_BibleVerse @BibleId, 120004005, N'Acquire wisdom, acquire understanding; do not forget and do not turn aside from the words I speak.'
EXEC add_BibleVerse @BibleId, 120004006, N'Do not forsake wisdom, and she will protect you; love her, and she will guard you.'
EXEC add_BibleVerse @BibleId, 120004007, N'Wisdom is supreme – so acquire wisdom, and whatever you acquire, acquire understanding!'
EXEC add_BibleVerse @BibleId, 120004008, N'Esteem her highly and she will exalt you; she will honor you if you embrace her.'
EXEC add_BibleVerse @BibleId, 120004009, N'She will place a fair garland on your head; she will bestow a beautiful crown on you.”'
EXEC add_BibleVerse @BibleId, 120004010, N'Listen, my child, and accept my words, so that the years of your life will be many.'
EXEC add_BibleVerse @BibleId, 120004011, N'I will guide you in the way of wisdom and I will lead you in upright paths.'
EXEC add_BibleVerse @BibleId, 120004012, N'When you walk, your steps will not be hampered, and when you run, you will not stumble.'
EXEC add_BibleVerse @BibleId, 120004013, N'Hold on to instruction, do not let it go; protect it, because it is your life.'
EXEC add_BibleVerse @BibleId, 120004014, N'Do not enter the path of the wicked or walk in the way of those who are evil.'
EXEC add_BibleVerse @BibleId, 120004015, N'Avoid it, do not go on it; turn away from it, and go on.'
EXEC add_BibleVerse @BibleId, 120004016, N'For they cannot sleep unless they cause harm; they are robbed of sleep until they make someone stumble.'
EXEC add_BibleVerse @BibleId, 120004017, N'For they eat bread gained from wickedness and drink wine obtained from violence.'
EXEC add_BibleVerse @BibleId, 120004018, N'But the path of the righteous is like the bright morning light, growing brighter and brighter until full day.'
EXEC add_BibleVerse @BibleId, 120004019, N'The way of the wicked is like gloomy darkness; they do not know what causes them to stumble.'
EXEC add_BibleVerse @BibleId, 120004020, N'My child, pay attention to my words; listen attentively to my sayings.'
EXEC add_BibleVerse @BibleId, 120004021, N'Do not let them depart from your sight, guard them within your heart;'
EXEC add_BibleVerse @BibleId, 120004022, N'for they are life to those who find them and healing to one’s entire body.'
EXEC add_BibleVerse @BibleId, 120004023, N'Guard your heart with all vigilance, for from it are the sources of life.'
EXEC add_BibleVerse @BibleId, 120004024, N'Remove perverse speech from your mouth; keep devious talk far from your lips.'
EXEC add_BibleVerse @BibleId, 120004025, N'Let your eyes look directly in front of you and let your gaze look straight before you.'
EXEC add_BibleVerse @BibleId, 120004026, N'Make the path for your feet level, so that all your ways may be established.'
EXEC add_BibleVerse @BibleId, 120004027, N'Do not turn to the right or to the left; turn yourself away from evil.'
EXEC add_BibleVerse @BibleId, 120005001, N'My child, be attentive to my wisdom, pay close attention to my understanding,'
EXEC add_BibleVerse @BibleId, 120005002, N'in order to safeguard discretion, and that your lips may guard knowledge.'
EXEC add_BibleVerse @BibleId, 120005003, N'For the lips of the adulterous woman drip honey, and her seductive words are smoother than olive oil,'
EXEC add_BibleVerse @BibleId, 120005004, N'but in the end she is bitter as wormwood, sharp as a two-edged sword.'
EXEC add_BibleVerse @BibleId, 120005005, N'Her feet go down to death; her steps lead straight to the grave.'
EXEC add_BibleVerse @BibleId, 120005006, N'Lest she should make level the path leading to life, her paths are unstable but she does not know it.'
EXEC add_BibleVerse @BibleId, 120005007, N'So now, children, listen to me; do not turn aside from the words I speak.'
EXEC add_BibleVerse @BibleId, 120005008, N'Keep yourself far from her, and do not go near the door of her house,'
EXEC add_BibleVerse @BibleId, 120005009, N'lest you give your vigor to others and your years to a cruel person,'
EXEC add_BibleVerse @BibleId, 120005010, N'lest strangers devour your strength, and your labor benefit another man’s house.'
EXEC add_BibleVerse @BibleId, 120005011, N'And at the end of your life you will groan when your flesh and your body are wasted away.'
EXEC add_BibleVerse @BibleId, 120005012, N'And you will say, “How I hated discipline! My heart spurned reproof!'
EXEC add_BibleVerse @BibleId, 120005013, N'For I did not obey my teachers and I did not heed my instructors.'
EXEC add_BibleVerse @BibleId, 120005014, N'I almost came to complete ruin in the midst of the whole congregation!”'
EXEC add_BibleVerse @BibleId, 120005015, N'Drink water from your own cistern and running water from your own well.'
EXEC add_BibleVerse @BibleId, 120005016, N'Should your springs be dispersed outside, your streams of water in the wide plazas?'
EXEC add_BibleVerse @BibleId, 120005017, N'Let them be for yourself alone, and not for strangers with you.'
EXEC add_BibleVerse @BibleId, 120005018, N'May your fountain be blessed, and may you rejoice in your young wife –'
EXEC add_BibleVerse @BibleId, 120005019, N'a loving doe, a graceful deer; may her breasts satisfy you at all times, may you be captivated by her love always.'
EXEC add_BibleVerse @BibleId, 120005020, N'But why should you be captivated, my son, by an adulteress, and embrace the bosom of a different woman?'
EXEC add_BibleVerse @BibleId, 120005021, N'For the ways of a person are in front of the Lord’s eyes, and the Lord weighs all that person’s paths.'
EXEC add_BibleVerse @BibleId, 120005022, N'The wicked will be captured by his own iniquities, and he will be held by the cords of his own sin.'
EXEC add_BibleVerse @BibleId, 120005023, N'He will die because there was no discipline; because of the greatness of his folly he will reel.'
EXEC add_BibleVerse @BibleId, 120006001, N'My child, if you have made a pledge for your neighbor, and have become a guarantor for a stranger,'
EXEC add_BibleVerse @BibleId, 120006002, N'if you have been ensnared by the words you have uttered, and have been caught by the words you have spoken,'
EXEC add_BibleVerse @BibleId, 120006003, N'then, my child, do this in order to deliver yourself, because you have fallen into your neighbor’s power: go, humble yourself, and appeal firmly to your neighbor.'
EXEC add_BibleVerse @BibleId, 120006004, N'Permit no sleep to your eyes or slumber to your eyelids.'
EXEC add_BibleVerse @BibleId, 120006005, N'Deliver yourself like a gazelle from a snare, and like a bird from the trap of the fowler.'
EXEC add_BibleVerse @BibleId, 120006006, N'Go to the ant, you sluggard; observe its ways and be wise!'
EXEC add_BibleVerse @BibleId, 120006007, N'It has no commander, overseer, or ruler,'
EXEC add_BibleVerse @BibleId, 120006008, N'yet it prepares its food in the summer; it gathers at the harvest what it will eat.'
EXEC add_BibleVerse @BibleId, 120006009, N'How long, you sluggard, will you lie there? When will you rise from your sleep?'
EXEC add_BibleVerse @BibleId, 120006010, N'A little sleep, a little slumber, a little folding of the hands to relax,'
EXEC add_BibleVerse @BibleId, 120006011, N'and your poverty will come like a robber, and your need like an armed man.'
EXEC add_BibleVerse @BibleId, 120006012, N'A worthless and wicked person walks around saying perverse things;'
EXEC add_BibleVerse @BibleId, 120006013, N'he winks with his eyes, signals with his feet, and points with his fingers;'
EXEC add_BibleVerse @BibleId, 120006014, N'he plots evil with perverse thoughts in his heart, he spreads contention at all times.'
EXEC add_BibleVerse @BibleId, 120006015, N'Therefore, his disaster will come suddenly; in an instant he will be broken, and there will be no remedy.'
EXEC add_BibleVerse @BibleId, 120006016, N'There are six things that the Lord hates, even seven things that are an abomination to him:'
EXEC add_BibleVerse @BibleId, 120006017, N'haughty eyes, a lying tongue, and hands that shed innocent blood,'
EXEC add_BibleVerse @BibleId, 120006018, N'a heart that devises wicked plans, feet that are swift to run to evil,'
EXEC add_BibleVerse @BibleId, 120006019, N'a false witness who pours out lies, and a person who spreads discord among family members.'
EXEC add_BibleVerse @BibleId, 120006020, N'My child, guard the commands of your father and do not forsake the instruction of your mother.'
EXEC add_BibleVerse @BibleId, 120006021, N'Bind them on your heart continually; fasten them around your neck.'
EXEC add_BibleVerse @BibleId, 120006022, N'When you walk about, they will guide you; when you lie down, they will watch over you; when you wake up, they will talk to you.'
EXEC add_BibleVerse @BibleId, 120006023, N'For the commandments are like a lamp, instruction is like a light, and rebukes of discipline are like the road leading to life,'
EXEC add_BibleVerse @BibleId, 120006024, N'by keeping you from the evil woman, from the smooth tongue of the loose woman.'
EXEC add_BibleVerse @BibleId, 120006025, N'Do not lust in your heart for her beauty, and do not let her captivate you with her alluring eyes;'
EXEC add_BibleVerse @BibleId, 120006026, N'for on account of a prostitute one is brought down to a loaf of bread, but the wife of another man preys on your precious life.'
EXEC add_BibleVerse @BibleId, 120006027, N'Can a man hold fire against his chest without burning his clothes?'
EXEC add_BibleVerse @BibleId, 120006028, N'Can a man walk on hot coals without scorching his feet?'
EXEC add_BibleVerse @BibleId, 120006029, N'So it is with the one who has sex with his neighbor’s wife; no one who touches her will escape punishment.'
EXEC add_BibleVerse @BibleId, 120006030, N'People do not despise a thief when he steals to fulfill his need when he is hungry.'
EXEC add_BibleVerse @BibleId, 120006031, N'Yet if he is caught he must repay seven times over, he might even have to give all the wealth of his house.'
EXEC add_BibleVerse @BibleId, 120006032, N'A man who commits adultery with a woman lacks wisdom, whoever does it destroys his own life.'
EXEC add_BibleVerse @BibleId, 120006033, N'He will be beaten and despised, and his reproach will not be wiped away;'
EXEC add_BibleVerse @BibleId, 120006034, N'for jealousy kindles a husband’s rage, and he will not show mercy when he takes revenge.'
EXEC add_BibleVerse @BibleId, 120006035, N'He will not consider any compensation; he will not be willing, even if you multiply the compensation.'
EXEC add_BibleVerse @BibleId, 120007001, N'My child, keep my words and treasure up my commands in your own keeping.'
EXEC add_BibleVerse @BibleId, 120007002, N'Keep my commands so that you may live, and obey my instruction as your most prized possession.'
EXEC add_BibleVerse @BibleId, 120007003, N'Bind them on your forearm; write them on the tablet of your heart.'
EXEC add_BibleVerse @BibleId, 120007004, N'Say to wisdom, “You are my sister,” and call understanding a close relative,'
EXEC add_BibleVerse @BibleId, 120007005, N'so that they may keep you from the adulterous woman, from the loose woman who flatters you with her words.'
EXEC add_BibleVerse @BibleId, 120007006, N'For at the window of my house through my window lattice I looked out'
EXEC add_BibleVerse @BibleId, 120007007, N'and I saw among the naive – I discerned among the youths – a young man who lacked wisdom.'
EXEC add_BibleVerse @BibleId, 120007008, N'He was passing by the street near her corner, making his way along the road to her house'
EXEC add_BibleVerse @BibleId, 120007009, N'in the twilight, the evening, in the dark of the night.'
EXEC add_BibleVerse @BibleId, 120007010, N'Suddenly a woman came out to meet him! She was dressed like a prostitute and with secret intent.'
EXEC add_BibleVerse @BibleId, 120007011, N'(She is loud and rebellious, she does not remain at home –'
EXEC add_BibleVerse @BibleId, 120007012, N'at one time outside, at another in the wide plazas, and by every corner she lies in wait.)'
EXEC add_BibleVerse @BibleId, 120007013, N'So she grabbed him and kissed him, and with a bold expression she said to him,'
EXEC add_BibleVerse @BibleId, 120007014, N'“I have fresh meat at home; today I have fulfilled my vows!'
EXEC add_BibleVerse @BibleId, 120007015, N'That is why I came out to meet you, to look for you, and I found you!'
EXEC add_BibleVerse @BibleId, 120007016, N'I have spread my bed with elegant coverings, with richly colored fabric from Egypt.'
EXEC add_BibleVerse @BibleId, 120007017, N'I have perfumed my bed with myrrh, aloes, and cinnamon.'
EXEC add_BibleVerse @BibleId, 120007018, N'Come, let’s drink deeply of lovemaking until morning, let’s delight ourselves with sexual intercourse.'
EXEC add_BibleVerse @BibleId, 120007019, N'For my husband is not at home; he has gone on a journey of some distance.'
EXEC add_BibleVerse @BibleId, 120007020, N'He has taken a bag of money with him; he will not return until the end of the month.”'
EXEC add_BibleVerse @BibleId, 120007021, N'She persuaded him with persuasive words; with her smooth talk she compelled him.'
EXEC add_BibleVerse @BibleId, 120007022, N'Suddenly he went after her like an ox that goes to the slaughter, like a stag prancing into a trapper’s snare'
EXEC add_BibleVerse @BibleId, 120007023, N'till an arrow pierces his liver – like a bird hurrying into a trap, and he does not know that it will cost him his life.'
EXEC add_BibleVerse @BibleId, 120007024, N'So now, sons, listen to me, and pay attention to the words I speak.'
EXEC add_BibleVerse @BibleId, 120007025, N'Do not let your heart turn aside to her ways – do not wander into her pathways;'
EXEC add_BibleVerse @BibleId, 120007026, N'for she has brought down many fatally wounded, and all those she has slain are many.'
EXEC add_BibleVerse @BibleId, 120007027, N'Her house is the way to the grave, going down to the chambers of death.'
EXEC add_BibleVerse @BibleId, 120008001, N'Does not wisdom call out? Does not understanding raise her voice?'
EXEC add_BibleVerse @BibleId, 120008002, N'At the top of the elevated places along the way, at the intersection of the paths she takes her stand;'
EXEC add_BibleVerse @BibleId, 120008003, N'beside the gates opening into the city, at the entrance of the doorways she cries out:'
EXEC add_BibleVerse @BibleId, 120008004, N'“To you, O people, I call out, and my voice calls to all mankind.'
EXEC add_BibleVerse @BibleId, 120008005, N'You who are naive, discern wisdom! And you fools, understand discernment!'
EXEC add_BibleVerse @BibleId, 120008006, N'Listen, for I will speak excellent things, and my lips will utter what is right.'
EXEC add_BibleVerse @BibleId, 120008007, N'For my mouth speaks truth, and my lips hate wickedness.'
EXEC add_BibleVerse @BibleId, 120008008, N'All the words of my mouth are righteous; there is nothing in them twisted or crooked.'
EXEC add_BibleVerse @BibleId, 120008009, N'All of them are clear to the discerning and upright to those who find knowledge.'
EXEC add_BibleVerse @BibleId, 120008010, N'Receive my instruction rather than silver, and knowledge rather than choice gold.'
EXEC add_BibleVerse @BibleId, 120008011, N'For wisdom is better than rubies, and desirable things cannot be compared to her.'
EXEC add_BibleVerse @BibleId, 120008012, N'“I, wisdom, live with prudence, and I find knowledge and discretion.'
EXEC add_BibleVerse @BibleId, 120008013, N'The fear of the Lord is to hate evil; I hate arrogant pride and the evil way and perverse utterances.'
EXEC add_BibleVerse @BibleId, 120008014, N'Counsel and sound wisdom belong to me; I possess understanding and might.'
EXEC add_BibleVerse @BibleId, 120008015, N'Kings reign by means of me, and potentates decree righteousness;'
EXEC add_BibleVerse @BibleId, 120008016, N'by me princes rule, as well as nobles and all righteous judges.'
EXEC add_BibleVerse @BibleId, 120008017, N'I love those who love me, and those who seek me find me.'
EXEC add_BibleVerse @BibleId, 120008018, N'Riches and honor are with me, long-lasting wealth and righteousness.'
EXEC add_BibleVerse @BibleId, 120008019, N'My fruit is better than the purest gold, and what I produce is better than choice silver.'
EXEC add_BibleVerse @BibleId, 120008020, N'I walk in the path of righteousness, in the pathway of justice,'
EXEC add_BibleVerse @BibleId, 120008021, N'that I may cause those who love me to inherit wealth, and that I may fill their treasuries.'
EXEC add_BibleVerse @BibleId, 120008022, N'The Lord created me as the beginning of his works, before his deeds of long ago.'
EXEC add_BibleVerse @BibleId, 120008023, N'From eternity I was appointed, from the beginning, from before the world existed.'
EXEC add_BibleVerse @BibleId, 120008024, N'When there were no deep oceans I was born, when there were no springs overflowing with water;'
EXEC add_BibleVerse @BibleId, 120008025, N'before the mountains were set in place – before the hills – I was born,'
EXEC add_BibleVerse @BibleId, 120008026, N'before he made the earth and its fields, or the beginning of the dust of the world.'
EXEC add_BibleVerse @BibleId, 120008027, N'When he established the heavens, I was there; when he marked out the horizon over the face of the deep,'
EXEC add_BibleVerse @BibleId, 120008028, N'when he established the clouds above, when the fountains of the deep grew strong,'
EXEC add_BibleVerse @BibleId, 120008029, N'when he gave the sea his decree that the waters should not pass over his command, when he marked out the foundations of the earth,'
EXEC add_BibleVerse @BibleId, 120008030, N'then I was beside him as a master craftsman, and I was his delight day by day, rejoicing before him at all times,'
EXEC add_BibleVerse @BibleId, 120008031, N'rejoicing in the habitable part of his earth, and delighting in its people.'
EXEC add_BibleVerse @BibleId, 120008032, N'“So now, children, listen to me; blessed are those who keep my ways.'
EXEC add_BibleVerse @BibleId, 120008033, N'Listen to my instruction so that you may be wise, and do not neglect it.'
EXEC add_BibleVerse @BibleId, 120008034, N'Blessed is the one who listens to me, watching at my doors day by day, waiting beside my doorway.'
EXEC add_BibleVerse @BibleId, 120008035, N'For the one who finds me finds life and receives favor from the Lord.'
EXEC add_BibleVerse @BibleId, 120008036, N'But the one who does not find me brings harm to himself; all who hate me love death.”'
EXEC add_BibleVerse @BibleId, 120009001, N'Wisdom has built her house; she has carved out its seven pillars.'
EXEC add_BibleVerse @BibleId, 120009002, N'She has prepared her meat, she has mixed her wine; she also has arranged her table.'
EXEC add_BibleVerse @BibleId, 120009003, N'She has sent out her female servants; she calls out on the highest places of the city.'
EXEC add_BibleVerse @BibleId, 120009004, N'“Whoever is naive, let him turn in here,” she says to those who lack understanding.'
EXEC add_BibleVerse @BibleId, 120009005, N'“Come, eat some of my food, and drink some of the wine I have mixed.'
EXEC add_BibleVerse @BibleId, 120009006, N'Abandon your foolish ways so that you may live, and proceed in the way of understanding.”'
EXEC add_BibleVerse @BibleId, 120009007, N'Whoever corrects a mocker is asking for insult; whoever reproves a wicked person receives abuse.'
EXEC add_BibleVerse @BibleId, 120009008, N'Do not reprove a mocker or he will hate you; reprove a wise person and he will love you.'
EXEC add_BibleVerse @BibleId, 120009009, N'Give instruction to a wise person, and he will become wiser still; teach a righteous person and he will add to his learning.'
EXEC add_BibleVerse @BibleId, 120009010, N'The beginning of wisdom is to fear the Lord, and acknowledging the Holy One is understanding.'
EXEC add_BibleVerse @BibleId, 120009011, N'For because of me your days will be many, and years will be added to your life.'
EXEC add_BibleVerse @BibleId, 120009012, N'If you are wise, you are wise to your own advantage, but if you are a mocker, you alone must bear it.'
EXEC add_BibleVerse @BibleId, 120009013, N'The woman called Folly is brash, she is naive and does not know anything.'
EXEC add_BibleVerse @BibleId, 120009014, N'So she sits at the door of her house, on a seat at the highest point of the city,'
EXEC add_BibleVerse @BibleId, 120009015, N'calling out to those who are passing by her in the way, who go straight on their way.'
EXEC add_BibleVerse @BibleId, 120009016, N'“Whoever is simple, let him turn in here,” she says to those who lack understanding.'
EXEC add_BibleVerse @BibleId, 120009017, N'“Stolen waters are sweet, and food obtained in secret is pleasant!”'
EXEC add_BibleVerse @BibleId, 120009018, N'But they do not realize that the dead are there, that her guests are in the depths of the grave.'
EXEC add_BibleVerse @BibleId, 120010001, N'The Proverbs of Solomon: A wise child makes a father rejoice, but a foolish child is a grief to his mother.'
EXEC add_BibleVerse @BibleId, 120010002, N'Treasures gained by wickedness do not profit, but righteousness delivers from mortal danger.'
EXEC add_BibleVerse @BibleId, 120010003, N'The Lord satisfies the appetite of the righteous, but he thwarts the craving of the wicked.'
EXEC add_BibleVerse @BibleId, 120010004, N'The one who is lazy becomes poor, but the one who works diligently becomes wealthy.'
EXEC add_BibleVerse @BibleId, 120010005, N'The one who gathers crops in the summer is a wise son, but the one who sleeps during the harvest is a son who brings shame to himself.'
EXEC add_BibleVerse @BibleId, 120010006, N'Blessings are on the head of the righteous, but the speech of the wicked conceals violence.'
EXEC add_BibleVerse @BibleId, 120010007, N'The memory of the righteous is a blessing, but the reputation of the wicked will rot.'
EXEC add_BibleVerse @BibleId, 120010008, N'The wise person accepts instructions, but the one who speaks foolishness will come to ruin.'
EXEC add_BibleVerse @BibleId, 120010009, N'The one who conducts himself in integrity will live securely, but the one who behaves perversely will be found out.'
EXEC add_BibleVerse @BibleId, 120010010, N'The one who winks his eye causes trouble, and the one who speaks foolishness will come to ruin.'
EXEC add_BibleVerse @BibleId, 120010011, N'The teaching of the righteous is a fountain of life, but the speech of the wicked conceals violence.'
EXEC add_BibleVerse @BibleId, 120010012, N'Hatred stirs up dissension, but love covers all transgressions.'
EXEC add_BibleVerse @BibleId, 120010013, N'Wisdom is found in the words of the discerning person, but the one who lacks wisdom will be disciplined.'
EXEC add_BibleVerse @BibleId, 120010014, N'Those who are wise store up knowledge, but foolish speech leads to imminent destruction.'
EXEC add_BibleVerse @BibleId, 120010015, N'The wealth of a rich person is like a fortified city, but the poor are brought to ruin by their poverty.'
EXEC add_BibleVerse @BibleId, 120010016, N'The reward which the righteous receive is life; the recompense which the wicked receive is judgment.'
EXEC add_BibleVerse @BibleId, 120010017, N'The one who heeds instruction is on the way to life, but the one who rejects rebuke goes astray.'
EXEC add_BibleVerse @BibleId, 120010018, N'The one who conceals hatred utters lies, and the one who spreads slander is certainly a fool.'
EXEC add_BibleVerse @BibleId, 120010019, N'When words abound, transgression is inevitable, but the one who restrains his words is wise.'
EXEC add_BibleVerse @BibleId, 120010020, N'What the righteous say is like the best silver, but what the wicked think is of little value.'
EXEC add_BibleVerse @BibleId, 120010021, N'The teaching of the righteous feeds many, but fools die for lack of wisdom.'
EXEC add_BibleVerse @BibleId, 120010022, N'The blessing from the Lord makes a person rich, and he adds no sorrow to it.'
EXEC add_BibleVerse @BibleId, 120010023, N'Carrying out a wicked scheme is enjoyable to a fool, and so is wisdom for the one who has discernment.'
EXEC add_BibleVerse @BibleId, 120010024, N'What the wicked fears will come on him; what the righteous desire will be granted.'
EXEC add_BibleVerse @BibleId, 120010025, N'When the storm passes through, the wicked are swept away, but the righteous are an everlasting foundation.'
EXEC add_BibleVerse @BibleId, 120010026, N'Like vinegar to the teeth and like smoke to the eyes, so is the sluggard to those who send him.'
EXEC add_BibleVerse @BibleId, 120010027, N'Fearing the Lord prolongs life, but the life span of the wicked will be shortened.'
EXEC add_BibleVerse @BibleId, 120010028, N'The hope of the righteous is joy, but the expectation of the wicked will remain unfulfilled.'
EXEC add_BibleVerse @BibleId, 120010029, N'The way of the Lord is like a stronghold for the upright, but it is destruction to evildoers.'
EXEC add_BibleVerse @BibleId, 120010030, N'The righteous will never be moved, but the wicked will not inhabit the land.'
EXEC add_BibleVerse @BibleId, 120010031, N'The speech of the righteous bears the fruit of wisdom, but the one who speaks perversion will be destroyed.'
EXEC add_BibleVerse @BibleId, 120010032, N'The lips of the righteous know what is pleasing, but the speech of the wicked is perverse.'
EXEC add_BibleVerse @BibleId, 120011001, N'The Lord abhors dishonest scales, but an accurate weight is his delight.'
EXEC add_BibleVerse @BibleId, 120011002, N'When pride comes, then comes disgrace, but with humility comes wisdom.'
EXEC add_BibleVerse @BibleId, 120011003, N'The integrity of the upright guides them, but the crookedness of the unfaithful destroys them.'
EXEC add_BibleVerse @BibleId, 120011004, N'Wealth does not profit in the day of wrath, but righteousness delivers from mortal danger.'
EXEC add_BibleVerse @BibleId, 120011005, N'The righteousness of the blameless will make straight their way, but the wicked person will fall by his own wickedness.'
EXEC add_BibleVerse @BibleId, 120011006, N'The righteousness of the upright will deliver them, but the faithless will be captured by their own desires.'
EXEC add_BibleVerse @BibleId, 120011007, N'When a wicked person dies, his expectation perishes, and the hope of his strength perishes.'
EXEC add_BibleVerse @BibleId, 120011008, N'The righteous person is delivered out of trouble, and the wicked turns up in his stead.'
EXEC add_BibleVerse @BibleId, 120011009, N'With his speech the godless person destroys his neighbor, but by knowledge the righteous will be delivered.'
EXEC add_BibleVerse @BibleId, 120011010, N'When the righteous do well, the city rejoices; when the wicked perish, there is joy.'
EXEC add_BibleVerse @BibleId, 120011011, N'A city is exalted by the blessing provided from the upright, but it is destroyed by the counsel of the wicked.'
EXEC add_BibleVerse @BibleId, 120011012, N'The one who denounces his neighbor lacks wisdom, but the one who has discernment keeps silent.'
EXEC add_BibleVerse @BibleId, 120011013, N'The one who goes about slandering others reveals secrets, but the one who is trustworthy conceals a matter.'
EXEC add_BibleVerse @BibleId, 120011014, N'When there is no guidance a nation falls, but there is success in the abundance of counselors.'
EXEC add_BibleVerse @BibleId, 120011015, N'The one who puts up security for a stranger will surely have trouble, but whoever avoids shaking hands will be secure.'
EXEC add_BibleVerse @BibleId, 120011016, N'A generous woman gains honor, and ruthless men seize wealth.'
EXEC add_BibleVerse @BibleId, 120011017, N'A kind person benefits himself, but a cruel person brings himself trouble.'
EXEC add_BibleVerse @BibleId, 120011018, N'The wicked person earns deceitful wages, but the one who sows righteousness reaps a genuine reward.'
EXEC add_BibleVerse @BibleId, 120011019, N'True righteousness leads to life, but the one who pursues evil pursues it to his own death.'
EXEC add_BibleVerse @BibleId, 120011020, N'The Lord abhors those who are perverse in heart, but those who are blameless in their ways are his delight.'
EXEC add_BibleVerse @BibleId, 120011021, N'Be assured that the evil person will certainly be punished, but the descendants of the righteous will not suffer unjust judgment.'
EXEC add_BibleVerse @BibleId, 120011022, N'Like a gold ring in a pig’s snout is a beautiful woman who rejects discretion.'
EXEC add_BibleVerse @BibleId, 120011023, N'What the righteous desire leads only to good, but what the wicked hope for leads to wrath.'
EXEC add_BibleVerse @BibleId, 120011024, N'One person is generous and yet grows more wealthy, but another withholds more than he should and comes to poverty.'
EXEC add_BibleVerse @BibleId, 120011025, N'A generous person will be enriched, and the one who provides water for others will himself be satisfied.'
EXEC add_BibleVerse @BibleId, 120011026, N'People will curse the one who withholds grain, but they will praise the one who sells it.'
EXEC add_BibleVerse @BibleId, 120011027, N'The one who diligently seeks good seeks favor, but the one who searches for evil – it will come to him.'
EXEC add_BibleVerse @BibleId, 120011028, N'The one who trusts in his riches will fall, but the righteous will flourish like a green leaf.'
EXEC add_BibleVerse @BibleId, 120011029, N'The one who troubles his family will inherit nothing, and the fool will be a servant to the wise person.'
EXEC add_BibleVerse @BibleId, 120011030, N'The fruit of the righteous is like a tree producing life, and the one who wins souls is wise.'
EXEC add_BibleVerse @BibleId, 120011031, N'If the righteous are recompensed on earth, how much more the wicked sinner!'
EXEC add_BibleVerse @BibleId, 120012001, N'The one who loves discipline loves knowledge, but the one who hates reproof is stupid.'
EXEC add_BibleVerse @BibleId, 120012002, N'A good person obtains favor from the Lord, but the Lord condemns a person with wicked schemes.'
EXEC add_BibleVerse @BibleId, 120012003, N'No one can be established through wickedness, but a righteous root cannot be moved.'
EXEC add_BibleVerse @BibleId, 120012004, N'A noble wife is the crown of her husband, but the wife who acts shamefully is like rottenness in his bones.'
EXEC add_BibleVerse @BibleId, 120012005, N'The plans of the righteous are just; the counsels of the wicked are deceitful.'
EXEC add_BibleVerse @BibleId, 120012006, N'The words of the wicked lie in wait to shed innocent blood, but the words of the upright will deliver them.'
EXEC add_BibleVerse @BibleId, 120012007, N'The wicked are overthrown and perish, but the righteous household will stand.'
EXEC add_BibleVerse @BibleId, 120012008, N'A person is praised in accordance with his wisdom, but the one who has a twisted mind is despised.'
EXEC add_BibleVerse @BibleId, 120012009, N'Better is a person of humble standing who nevertheless has a servant, than one who pretends to be somebody important yet has no food.'
EXEC add_BibleVerse @BibleId, 120012010, N'A righteous person cares for the life of his animal, but even the most compassionate acts of the wicked are cruel.'
EXEC add_BibleVerse @BibleId, 120012011, N'The one who works his field will have plenty of food, but whoever chases daydreams lacks wisdom.'
EXEC add_BibleVerse @BibleId, 120012012, N'The wicked person desires a stronghold, but the righteous root endures.'
EXEC add_BibleVerse @BibleId, 120012013, N'The evil person is ensnared by the transgression of his speech, but the righteous person escapes out of trouble.'
EXEC add_BibleVerse @BibleId, 120012014, N'A person will be satisfied with good from the fruit of his words, and the work of his hands will be rendered to him.'
EXEC add_BibleVerse @BibleId, 120012015, N'The way of a fool is right in his own opinion, but the one who listens to advice is wise.'
EXEC add_BibleVerse @BibleId, 120012016, N'A fool’s annoyance is known at once, but the prudent overlooks an insult.'
EXEC add_BibleVerse @BibleId, 120012017, N'The faithful witness tells what is right, but a false witness speaks deceit.'
EXEC add_BibleVerse @BibleId, 120012018, N'Speaking recklessly is like the thrusts of a sword, but the words of the wise bring healing.'
EXEC add_BibleVerse @BibleId, 120012019, N'The one who tells the truth will endure forever, but the one who lies will last only for a moment.'
EXEC add_BibleVerse @BibleId, 120012020, N'Deceit is in the heart of those who plot evil, but those who promote peace have joy.'
EXEC add_BibleVerse @BibleId, 120012021, N'The righteous do not encounter any harm, but the wicked are filled with calamity.'
EXEC add_BibleVerse @BibleId, 120012022, N'The Lord abhors a person who lies, but those who deal truthfully are his delight.'
EXEC add_BibleVerse @BibleId, 120012023, N'The shrewd person conceals knowledge, but foolish people publicize folly.'
EXEC add_BibleVerse @BibleId, 120012024, N'The diligent person will rule, but the slothful will become a slave.'
EXEC add_BibleVerse @BibleId, 120012025, N'Anxiety in a person’s heart weighs him down, but an encouraging word brings him joy.'
EXEC add_BibleVerse @BibleId, 120012026, N'The righteous person is cautious in his friendship, but the way of the wicked leads them astray.'
EXEC add_BibleVerse @BibleId, 120012027, N'The lazy person does not roast his prey, but personal possessions are precious to the diligent.'
EXEC add_BibleVerse @BibleId, 120012028, N'In the path of righteousness there is life, but another path leads to death.'
EXEC add_BibleVerse @BibleId, 120013001, N'A wise son accepts his father’s discipline, but a scoffer does not listen to rebuke.'
EXEC add_BibleVerse @BibleId, 120013002, N'From the fruit of his speech a person eats good things, but the faithless desire the fruit of violence.'
EXEC add_BibleVerse @BibleId, 120013003, N'The one who guards his words guards his life, but whoever is talkative will come to ruin.'
EXEC add_BibleVerse @BibleId, 120013004, N'The appetite of the sluggard craves but gets nothing, but the desire of the diligent will be abundantly satisfied.'
EXEC add_BibleVerse @BibleId, 120013005, N'The righteous person hates anything false, but the wicked person acts in shameful disgrace.'
EXEC add_BibleVerse @BibleId, 120013006, N'Righteousness guards the one who lives with integrity, but wickedness overthrows the sinner.'
EXEC add_BibleVerse @BibleId, 120013007, N'There is one who pretends to be rich and yet has nothing; another pretends to be poor and yet possesses great wealth.'
EXEC add_BibleVerse @BibleId, 120013008, N'The ransom of a person’s life is his wealth, but the poor person hears no threat.'
EXEC add_BibleVerse @BibleId, 120013009, N'The light of the righteous shines brightly, but the lamp of the wicked goes out.'
EXEC add_BibleVerse @BibleId, 120013010, N'With pride comes only contention, but wisdom is with the well-advised.'
EXEC add_BibleVerse @BibleId, 120013011, N'Wealth gained quickly will dwindle away, but the one who gathers it little by little will become rich.'
EXEC add_BibleVerse @BibleId, 120013012, N'Hope deferred makes the heart sick, but a longing fulfilled is like a tree of life.'
EXEC add_BibleVerse @BibleId, 120013013, N'The one who despises instruction will pay the penalty, but whoever esteems instruction will be rewarded.'
EXEC add_BibleVerse @BibleId, 120013014, N'Instruction from the wise is like a life-giving fountain, to turn a person from deadly snares.'
EXEC add_BibleVerse @BibleId, 120013015, N'Keen insight wins favor, but the conduct of the unfaithful is harsh.'
EXEC add_BibleVerse @BibleId, 120013016, N'Every shrewd person acts with knowledge, but a fool displays his folly.'
EXEC add_BibleVerse @BibleId, 120013017, N'An unreliable messenger falls into trouble, but a faithful envoy brings healing.'
EXEC add_BibleVerse @BibleId, 120013018, N'The one who neglects discipline ends up in poverty and shame, but the one who accepts reproof is honored.'
EXEC add_BibleVerse @BibleId, 120013019, N'A desire fulfilled is sweet to the soul, but fools abhor turning away from evil.'
EXEC add_BibleVerse @BibleId, 120013020, N'The one who associates with the wise grows wise, but a companion of fools suffers harm.'
EXEC add_BibleVerse @BibleId, 120013021, N'Calamity pursues sinners, but prosperity rewards the righteous.'
EXEC add_BibleVerse @BibleId, 120013022, N'A benevolent person leaves an inheritance for his grandchildren, but the wealth of a sinner is stored up for the righteous.'
EXEC add_BibleVerse @BibleId, 120013023, N'There is abundant food in the field of the poor, but it is swept away by injustice.'
EXEC add_BibleVerse @BibleId, 120013024, N'The one who spares his rod hates his child, but the one who loves his child is diligent in disciplining him.'
EXEC add_BibleVerse @BibleId, 120013025, N'The righteous has enough food to satisfy his appetite, but the belly of the wicked lacks food.'
EXEC add_BibleVerse @BibleId, 120014001, N'Every wise woman builds her household, but a foolish woman tears it down with her own hands.'
EXEC add_BibleVerse @BibleId, 120014002, N'The one who walks in his uprightness fears the Lord, but the one who is perverted in his ways despises him.'
EXEC add_BibleVerse @BibleId, 120014003, N'In the speech of a fool is a rod for his back, but the words of the wise protect them.'
EXEC add_BibleVerse @BibleId, 120014004, N'Where there are no oxen, the feeding trough is clean, but an abundant harvest is produced by strong oxen.'
EXEC add_BibleVerse @BibleId, 120014005, N'A truthful witness does not lie, but a false witness breathes out lies.'
EXEC add_BibleVerse @BibleId, 120014006, N'The scorner seeks wisdom but finds none, but understanding is easy for a discerning person.'
EXEC add_BibleVerse @BibleId, 120014007, N'Leave the presence of a foolish person, or you will not understand wise counsel.'
EXEC add_BibleVerse @BibleId, 120014008, N'The wisdom of the shrewd person is to discern his way, but the folly of fools is deception.'
EXEC add_BibleVerse @BibleId, 120014009, N'Fools mock at reparation, but among the upright there is favor.'
EXEC add_BibleVerse @BibleId, 120014010, N'The heart knows its own bitterness, and with its joy no one else can share.'
EXEC add_BibleVerse @BibleId, 120014011, N'The household of the wicked will be destroyed, but the tent of the upright will flourish.'
EXEC add_BibleVerse @BibleId, 120014012, N'There is a way that seems right to a person, but its end is the way that leads to death.'
EXEC add_BibleVerse @BibleId, 120014013, N'Even in laughter the heart may ache, and the end of joy may be grief.'
EXEC add_BibleVerse @BibleId, 120014014, N'The backslider will be paid back from his own ways, but a good person will be rewarded for his.'
EXEC add_BibleVerse @BibleId, 120014015, N'A naive person believes everything, but the shrewd person discerns his steps.'
EXEC add_BibleVerse @BibleId, 120014016, N'A wise person is cautious and turns from evil, but a fool throws off restraint and is overconfident.'
EXEC add_BibleVerse @BibleId, 120014017, N'A person who has a quick temper does foolish things, and a person with crafty schemes is hated.'
EXEC add_BibleVerse @BibleId, 120014018, N'The naive inherit folly, but the shrewd are crowned with knowledge.'
EXEC add_BibleVerse @BibleId, 120014019, N'Those who are evil will bow before those who are good, and the wicked will bow at the gates of the righteous.'
EXEC add_BibleVerse @BibleId, 120014020, N'A poor person is disliked even by his neighbors, but those who love the rich are many.'
EXEC add_BibleVerse @BibleId, 120014021, N'The one who despises his neighbor sins, but whoever is kind to the needy is blessed.'
EXEC add_BibleVerse @BibleId, 120014022, N'Do not those who devise evil go astray? But those who plan good exhibit faithful covenant love.'
EXEC add_BibleVerse @BibleId, 120014023, N'In all hard work there is profit, but merely talking about it only brings poverty.'
EXEC add_BibleVerse @BibleId, 120014024, N'The crown of the wise is their riches, but the folly of fools is folly.'
EXEC add_BibleVerse @BibleId, 120014025, N'A truthful witness rescues lives, but the one who breathes lies brings deception.'
EXEC add_BibleVerse @BibleId, 120014026, N'In the fear of the Lord one has strong confidence, and it will be a refuge for his children.'
EXEC add_BibleVerse @BibleId, 120014027, N'The fear of the Lord is like a life-giving fountain, to turn people from deadly snares.'
EXEC add_BibleVerse @BibleId, 120014028, N'A king’s glory is the abundance of people, but the lack of subjects is the ruin of a ruler.'
EXEC add_BibleVerse @BibleId, 120014029, N'The one who is slow to anger has great understanding, but the one who has a quick temper exalts folly.'
EXEC add_BibleVerse @BibleId, 120014030, N'A tranquil spirit revives the body, but envy is rottenness to the bones.'
EXEC add_BibleVerse @BibleId, 120014031, N'The one who oppresses the poor insults his Creator, but whoever shows favor to the needy honors him.'
EXEC add_BibleVerse @BibleId, 120014032, N'The wicked will be thrown down in his trouble, but the righteous have refuge even in the threat of death.'
EXEC add_BibleVerse @BibleId, 120014033, N'Wisdom rests in the heart of the discerning; it is known even in the heart of fools.'
EXEC add_BibleVerse @BibleId, 120014034, N'Righteousness exalts a nation, but sin is a disgrace to any people.'
EXEC add_BibleVerse @BibleId, 120014035, N'The king shows favor to a wise servant, but his wrath falls on one who acts shamefully.'
EXEC add_BibleVerse @BibleId, 120015001, N'A gentle response turns away anger, but a harsh word stirs up wrath.'
EXEC add_BibleVerse @BibleId, 120015002, N'The tongue of the wise treats knowledge correctly, but the mouth of the fool spouts out folly.'
EXEC add_BibleVerse @BibleId, 120015003, N'The eyes of the Lord are in every place, keeping watch on those who are evil and those who are good.'
EXEC add_BibleVerse @BibleId, 120015004, N'Speech that heals is like a life-giving tree, but a perverse tongue breaks the spirit.'
EXEC add_BibleVerse @BibleId, 120015005, N'A fool rejects his father’s discipline, but whoever heeds reproof shows good sense.'
EXEC add_BibleVerse @BibleId, 120015006, N'In the house of the righteous is abundant wealth, but the income of the wicked brings trouble.'
EXEC add_BibleVerse @BibleId, 120015007, N'The lips of the wise spread knowledge, but not so the heart of fools.'
EXEC add_BibleVerse @BibleId, 120015008, N'The Lord abhors the sacrifices of the wicked, but the prayer of the upright pleases him.'
EXEC add_BibleVerse @BibleId, 120015009, N'The Lord abhors the way of the wicked, but he loves those who pursue righteousness.'
EXEC add_BibleVerse @BibleId, 120015010, N'Severe discipline is for the one who abandons the way; the one who hates reproof will die.'
EXEC add_BibleVerse @BibleId, 120015011, N'Death and Destruction are before the Lord – how much more the hearts of humans!'
EXEC add_BibleVerse @BibleId, 120015012, N'The scorner does not love one who corrects him; he will not go to the wise.'
EXEC add_BibleVerse @BibleId, 120015013, N'A joyful heart makes the face cheerful, but by a painful heart the spirit is broken.'
EXEC add_BibleVerse @BibleId, 120015014, N'The discerning heart seeks knowledge, but the mouth of fools feeds on folly.'
EXEC add_BibleVerse @BibleId, 120015015, N'All the days of the afflicted are bad, but one with a cheerful heart has a continual feast.'
EXEC add_BibleVerse @BibleId, 120015016, N'Better is little with the fear of the Lord than great wealth and turmoil with it.'
EXEC add_BibleVerse @BibleId, 120015017, N'Better a meal of vegetables where there is love than a fattened ox where there is hatred.'
EXEC add_BibleVerse @BibleId, 120015018, N'A quick-tempered person stirs up dissension, but one who is slow to anger calms a quarrel.'
EXEC add_BibleVerse @BibleId, 120015019, N'The way of the sluggard is like a hedge of thorns, but the path of the upright is like a highway.'
EXEC add_BibleVerse @BibleId, 120015020, N'A wise child brings joy to his father, but a foolish person despises his mother.'
EXEC add_BibleVerse @BibleId, 120015021, N'Folly is a joy to one who lacks sense, but one who has understanding follows an upright course.'
EXEC add_BibleVerse @BibleId, 120015022, N'Plans fail when there is no counsel, but with abundant advisers they are established.'
EXEC add_BibleVerse @BibleId, 120015023, N'A person has joy in giving an appropriate answer, and a word at the right time – how good it is!'
EXEC add_BibleVerse @BibleId, 120015024, N'The path of life is upward for the wise person, to keep him from going downward to Sheol.'
EXEC add_BibleVerse @BibleId, 120015025, N'The Lord tears down the house of the proud, but he maintains the boundaries of the widow.'
EXEC add_BibleVerse @BibleId, 120015026, N'The Lord abhors the plans of the wicked, but pleasant words are pure.'
EXEC add_BibleVerse @BibleId, 120015027, N'The one who is greedy for gain troubles his household, but whoever hates bribes will live.'
EXEC add_BibleVerse @BibleId, 120015028, N'The heart of the righteous considers how to answer, but the mouth of the wicked pours out evil things.'
EXEC add_BibleVerse @BibleId, 120015029, N'The Lord is far from the wicked, but he hears the prayer of the righteous.'
EXEC add_BibleVerse @BibleId, 120015030, N'A bright look brings joy to the heart, and good news gives health to the body.'
EXEC add_BibleVerse @BibleId, 120015031, N'The person who hears the reproof that leads to life is at home among the wise.'
EXEC add_BibleVerse @BibleId, 120015032, N'The one who refuses correction despises himself, but whoever hears reproof acquires understanding.'
EXEC add_BibleVerse @BibleId, 120015033, N'The fear of the Lord provides wise instruction, and before honor comes humility.'
EXEC add_BibleVerse @BibleId, 120016001, N'The intentions of the heart belong to a man, but the answer of the tongue comes from the Lord.'
EXEC add_BibleVerse @BibleId, 120016002, N'All a person’s ways seem right in his own opinion, but the Lord evaluates the motives.'
EXEC add_BibleVerse @BibleId, 120016003, N'Commit your works to the Lord, and your plans will be established.'
EXEC add_BibleVerse @BibleId, 120016004, N'The Lord works everything for its own ends – even the wicked for the day of disaster.'
EXEC add_BibleVerse @BibleId, 120016005, N'The Lord abhors every arrogant person; rest assured that they will not go unpunished.'
EXEC add_BibleVerse @BibleId, 120016006, N'Through loyal love and truth iniquity is appeased; through fearing the Lord one avoids evil.'
EXEC add_BibleVerse @BibleId, 120016007, N'When a person’s ways are pleasing to the Lord, he even reconciles his enemies to himself.'
EXEC add_BibleVerse @BibleId, 120016008, N'Better to have a little with righteousness than to have abundant income without justice.'
EXEC add_BibleVerse @BibleId, 120016009, N'A person plans his course, but the Lord directs his steps.'
EXEC add_BibleVerse @BibleId, 120016010, N'The divine verdict is in the words of the king, his pronouncements must not act treacherously against justice.'
EXEC add_BibleVerse @BibleId, 120016011, N'Honest scales and balances are from the Lord; all the weights in the bag are his handiwork.'
EXEC add_BibleVerse @BibleId, 120016012, N'Doing wickedness is an abomination to kings, because a throne is established in righteousness.'
EXEC add_BibleVerse @BibleId, 120016013, N'The delight of kings is righteous counsel, and they love the one who speaks uprightly.'
EXEC add_BibleVerse @BibleId, 120016014, N'A king’s wrath is like a messenger of death, but a wise person appeases it.'
EXEC add_BibleVerse @BibleId, 120016015, N'In the light of the king’s face there is life, and his favor is like the clouds of the spring rain.'
EXEC add_BibleVerse @BibleId, 120016016, N'How much better it is to acquire wisdom than gold; to acquire understanding is more desirable than silver.'
EXEC add_BibleVerse @BibleId, 120016017, N'The highway of the upright is to turn away from evil; the one who guards his way safeguards his life.'
EXEC add_BibleVerse @BibleId, 120016018, N'Pride goes before destruction, and a haughty spirit before a fall.'
EXEC add_BibleVerse @BibleId, 120016019, N'It is better to be lowly in spirit with the afflicted than to share the spoils with the proud.'
EXEC add_BibleVerse @BibleId, 120016020, N'The one who deals wisely in a matter will find success, and blessed is the one who trusts in the Lord.'
EXEC add_BibleVerse @BibleId, 120016021, N'The one who is wise in heart is called discerning, and kind speech increases persuasiveness.'
EXEC add_BibleVerse @BibleId, 120016022, N'Insight is like a life-giving fountain to the one who possesses it, but folly leads to the discipline of fools.'
EXEC add_BibleVerse @BibleId, 120016023, N'A wise person’s heart makes his speech wise and it adds persuasiveness to his words.'
EXEC add_BibleVerse @BibleId, 120016024, N'Pleasant words are like a honeycomb, sweet to the soul and healing to the bones.'
EXEC add_BibleVerse @BibleId, 120016025, N'There is a way that seems right to a person, but its end is the way that leads to death.'
EXEC add_BibleVerse @BibleId, 120016026, N'A laborer’s appetite works on his behalf, for his hunger urges him to work.'
EXEC add_BibleVerse @BibleId, 120016027, N'A wicked scoundrel digs up evil, and his slander is like a scorching fire.'
EXEC add_BibleVerse @BibleId, 120016028, N'A perverse person spreads dissension, and a gossip separates the closest friends.'
EXEC add_BibleVerse @BibleId, 120016029, N'A violent person entices his neighbor, and leads him down a path that is terrible.'
EXEC add_BibleVerse @BibleId, 120016030, N'The one who winks his eyes devises perverse things, and one who compresses his lips brings about evil.'
EXEC add_BibleVerse @BibleId, 120016031, N'Gray hair is like a crown of glory; it is attained in the path of righteousness.'
EXEC add_BibleVerse @BibleId, 120016032, N'Better to be slow to anger than to be a mighty warrior, and one who controls his temper is better than one who captures a city.'
EXEC add_BibleVerse @BibleId, 120016033, N'The dice are thrown into the lap, but their every decision is from the Lord.'
EXEC add_BibleVerse @BibleId, 120017001, N'Better is a dry crust of bread where there is quietness than a house full of feasting with strife.'
EXEC add_BibleVerse @BibleId, 120017002, N'A servant who acts wisely will rule over an heir who behaves shamefully, and will share the inheritance along with the relatives.'
EXEC add_BibleVerse @BibleId, 120017003, N'The crucible is for refining silver and the furnace is for gold, likewise the Lord tests hearts.'
EXEC add_BibleVerse @BibleId, 120017004, N'One who acts wickedly pays attention to evil counsel; a liar listens to a malicious tongue.'
EXEC add_BibleVerse @BibleId, 120017005, N'The one who mocks the poor insults his Creator; whoever rejoices over disaster will not go unpunished.'
EXEC add_BibleVerse @BibleId, 120017006, N'Grandchildren are like a crown to the elderly, and the glory of children is their parents.'
EXEC add_BibleVerse @BibleId, 120017007, N'Excessive speech is not becoming for a fool; how much less are lies for a ruler!'
EXEC add_BibleVerse @BibleId, 120017008, N'A bribe works like a charm for the one who offers it; in whatever he does he succeeds.'
EXEC add_BibleVerse @BibleId, 120017009, N'The one who forgives an offense seeks love, but whoever repeats a matter separates close friends.'
EXEC add_BibleVerse @BibleId, 120017010, N'A rebuke makes a greater impression on a discerning person than a hundred blows on a fool.'
EXEC add_BibleVerse @BibleId, 120017011, N'An evil person seeks only rebellion, and so a cruel messenger will be sent against him.'
EXEC add_BibleVerse @BibleId, 120017012, N'It is better for a person to meet a mother bear being robbed of her cubs, than to encounter a fool in his folly.'
EXEC add_BibleVerse @BibleId, 120017013, N'As for the one who repays evil for good, evil will not leave his house.'
EXEC add_BibleVerse @BibleId, 120017014, N'Starting a quarrel is like letting out water; stop it before strife breaks out!'
EXEC add_BibleVerse @BibleId, 120017015, N'The one who acquits the guilty and the one who condemns the innocent – both of them are an abomination to the Lord.'
EXEC add_BibleVerse @BibleId, 120017016, N'Of what use is money in the hand of a fool, since he has no intention of acquiring wisdom?'
EXEC add_BibleVerse @BibleId, 120017017, N'A friend loves at all times, and a relative is born to help in adversity.'
EXEC add_BibleVerse @BibleId, 120017018, N'The one who lacks wisdom strikes hands in pledge, and puts up financial security for his neighbor.'
EXEC add_BibleVerse @BibleId, 120017019, N'The one who loves a quarrel loves transgression; whoever builds his gate high seeks destruction.'
EXEC add_BibleVerse @BibleId, 120017020, N'The one who has a perverse heart does not find good, and the one who is deceitful in speech falls into trouble.'
EXEC add_BibleVerse @BibleId, 120017021, N'Whoever brings a fool into the world does so to his grief, and the father of a fool has no joy.'
EXEC add_BibleVerse @BibleId, 120017022, N'A cheerful heart brings good healing, but a crushed spirit dries up the bones.'
EXEC add_BibleVerse @BibleId, 120017023, N'A wicked person receives a bribe secretly to pervert the ways of justice.'
EXEC add_BibleVerse @BibleId, 120017024, N'Wisdom is directly in front of the discerning person, but the eyes of a fool run to the ends of the earth.'
EXEC add_BibleVerse @BibleId, 120017025, N'A foolish child is a grief to his father, and bitterness to the mother who bore him.'
EXEC add_BibleVerse @BibleId, 120017026, N'It is terrible to punish a righteous person, and to flog honorable men is wrong.'
EXEC add_BibleVerse @BibleId, 120017027, N'The truly wise person restrains his words, and the one who stays calm is discerning.'
EXEC add_BibleVerse @BibleId, 120017028, N'Even a fool who remains silent is considered wise, and the one who holds his tongue is deemed discerning.'
EXEC add_BibleVerse @BibleId, 120018001, N'One who has isolated himself seeks his own desires; he rejects all sound judgment.'
EXEC add_BibleVerse @BibleId, 120018002, N'A fool takes no pleasure in understanding but only in disclosing what is on his mind.'
EXEC add_BibleVerse @BibleId, 120018003, N'When a wicked person arrives, contempt shows up with him, and with shame comes a reproach.'
EXEC add_BibleVerse @BibleId, 120018004, N'The words of a person’s mouth are like deep waters, and the fountain of wisdom is like a flowing brook.'
EXEC add_BibleVerse @BibleId, 120018005, N'It is terrible to show partiality to the wicked, by depriving a righteous man of justice.'
EXEC add_BibleVerse @BibleId, 120018006, N'The lips of a fool enter into strife, and his mouth invites a flogging.'
EXEC add_BibleVerse @BibleId, 120018007, N'The mouth of a fool is his ruin, and his lips are a snare for his life.'
EXEC add_BibleVerse @BibleId, 120018008, N'The words of a gossip are like choice morsels; they go down into the person’s innermost being.'
EXEC add_BibleVerse @BibleId, 120018009, N'The one who is slack in his work is a brother to one who destroys.'
EXEC add_BibleVerse @BibleId, 120018010, N'The name of the Lord is like a strong tower; the righteous person runs to it and is set safely on high.'
EXEC add_BibleVerse @BibleId, 120018011, N'The wealth of a rich person is like a strong city, and it is like a high wall in his imagination.'
EXEC add_BibleVerse @BibleId, 120018012, N'Before destruction the heart of a person is proud, but humility comes before honor.'
EXEC add_BibleVerse @BibleId, 120018013, N'The one who gives an answer before he listens – that is his folly and his shame.'
EXEC add_BibleVerse @BibleId, 120018014, N'A person’s spirit sustains him through sickness – but who can bear a crushed spirit?'
EXEC add_BibleVerse @BibleId, 120018015, N'The discerning person acquires knowledge, and the wise person seeks knowledge.'
EXEC add_BibleVerse @BibleId, 120018016, N'A person’s gift makes room for him, and leads him before important people.'
EXEC add_BibleVerse @BibleId, 120018017, N'The first to state his case seems right, until his opponent begins to cross-examine him.'
EXEC add_BibleVerse @BibleId, 120018018, N'A toss of a coin ends disputes, and settles the issue between strong opponents.'
EXEC add_BibleVerse @BibleId, 120018019, N'A relative offended is harder to reach than a strong city, and disputes are like the barred gates of a fortified citadel.'
EXEC add_BibleVerse @BibleId, 120018020, N'From the fruit of a person’s mouth his stomach is satisfied, with the product of his lips is he satisfied.'
EXEC add_BibleVerse @BibleId, 120018021, N'Death and life are in the power of the tongue, and those who love its use will eat its fruit.'
EXEC add_BibleVerse @BibleId, 120018022, N'The one who finds a wife finds what is enjoyable, and receives a pleasurable gift from the Lord.'
EXEC add_BibleVerse @BibleId, 120018023, N'A poor person makes supplications, but a rich man answers harshly.'
EXEC add_BibleVerse @BibleId, 120018024, N'A person who has friends may be harmed by them, but there is a friend who sticks closer than a brother.'
EXEC add_BibleVerse @BibleId, 120019001, N'Better is a poor person who walks in his integrity than one who is perverse in his speech and is a fool.'
EXEC add_BibleVerse @BibleId, 120019002, N'It is dangerous to have zeal without knowledge, and the one who acts hastily makes poor choices.'
EXEC add_BibleVerse @BibleId, 120019003, N'A person’s folly subverts his way, and his heart rages against the Lord.'
EXEC add_BibleVerse @BibleId, 120019004, N'Wealth adds many friends, but a poor person is separated from his friend.'
EXEC add_BibleVerse @BibleId, 120019005, N'A false witness will not go unpunished, and the one who spouts out lies will not escape punishment.'
EXEC add_BibleVerse @BibleId, 120019006, N'Many people entreat the favor of a generous person, and everyone is the friend of the person who gives gifts.'
EXEC add_BibleVerse @BibleId, 120019007, N'All the relatives of a poor person hate him; how much more do his friends avoid him – he pursues them with words, but they do not respond.'
EXEC add_BibleVerse @BibleId, 120019008, N'The one who acquires wisdom loves himself; the one who preserves understanding will prosper.'
EXEC add_BibleVerse @BibleId, 120019009, N'A false witness will not go unpunished, and the one who spouts out lies will perish.'
EXEC add_BibleVerse @BibleId, 120019010, N'Luxury is not appropriate for a fool; how much less for a servant to rule over princes!'
EXEC add_BibleVerse @BibleId, 120019011, N'A person’s wisdom makes him slow to anger, and it is his glory to overlook an offense.'
EXEC add_BibleVerse @BibleId, 120019012, N'A king’s wrath is like the roar of a lion, but his favor is like dew on the grass.'
EXEC add_BibleVerse @BibleId, 120019013, N'A foolish child is the ruin of his father, and a contentious wife is like a constant dripping.'
EXEC add_BibleVerse @BibleId, 120019014, N'A house and wealth are inherited from parents, but a prudent wife is from the Lord.'
EXEC add_BibleVerse @BibleId, 120019015, N'Laziness brings on a deep sleep, and the idle person will go hungry.'
EXEC add_BibleVerse @BibleId, 120019016, N'The one who obeys commandments guards his life; the one who despises his ways will die.'
EXEC add_BibleVerse @BibleId, 120019017, N'The one who is gracious to the poor lends to the Lord, and the Lord will repay him for his good deed.'
EXEC add_BibleVerse @BibleId, 120019018, N'Discipline your child, for there is hope, but do not set your heart on causing his death.'
EXEC add_BibleVerse @BibleId, 120019019, N'A person with great anger bears the penalty, but if you deliver him from it once, you will have to do it again.'
EXEC add_BibleVerse @BibleId, 120019020, N'Listen to advice and receive discipline, that you may become wise by the end of your life.'
EXEC add_BibleVerse @BibleId, 120019021, N'There are many plans in a person’s mind, but it is the counsel of the Lord which will stand.'
EXEC add_BibleVerse @BibleId, 120019022, N'What is desirable for a person is to show loyal love, and a poor person is better than a liar.'
EXEC add_BibleVerse @BibleId, 120019023, N'Fearing the Lord leads to life, and one who does so will live satisfied; he will not be afflicted by calamity.'
EXEC add_BibleVerse @BibleId, 120019024, N'The sluggard plunges his hand in the dish, and he will not even bring it back to his mouth!'
EXEC add_BibleVerse @BibleId, 120019025, N'Flog a scorner, and as a result the simpleton will learn prudence; correct a discerning person, and as a result he will understand knowledge.'
EXEC add_BibleVerse @BibleId, 120019026, N'The one who robs his father and chases away his mother is a son who brings shame and disgrace.'
EXEC add_BibleVerse @BibleId, 120019027, N'If you stop listening to instruction, my child, you will stray from the words of knowledge.'
EXEC add_BibleVerse @BibleId, 120019028, N'A crooked witness scorns justice, and the mouth of the wicked devours iniquity.'
EXEC add_BibleVerse @BibleId, 120019029, N'Judgments are prepared for scorners, and floggings for the backs of fools.'
EXEC add_BibleVerse @BibleId, 120020001, N'Wine is a mocker and strong drink is a brawler; whoever goes astray by them is not wise.'
EXEC add_BibleVerse @BibleId, 120020002, N'The king’s terrifying anger is like the roar of a lion; whoever provokes him sins against himself.'
EXEC add_BibleVerse @BibleId, 120020003, N'It is an honor for a person to cease from strife, but every fool quarrels.'
EXEC add_BibleVerse @BibleId, 120020004, N'The sluggard will not plow during the planting season, so at harvest time he looks for the crop but has nothing.'
EXEC add_BibleVerse @BibleId, 120020005, N'Counsel in a person’s heart is like deep water, but an understanding person draws it out.'
EXEC add_BibleVerse @BibleId, 120020006, N'Many people profess their loyalty, but a faithful person – who can find?'
EXEC add_BibleVerse @BibleId, 120020007, N'The righteous person behaves in integrity; blessed are his children after him.'
EXEC add_BibleVerse @BibleId, 120020008, N'A king sitting on the throne to judge separates out all evil with his eyes.'
EXEC add_BibleVerse @BibleId, 120020009, N'Who can say, “I have kept my heart clean; I am pure from my sin”?'
EXEC add_BibleVerse @BibleId, 120020010, N'Diverse weights and diverse measures – the Lord abhors both of them.'
EXEC add_BibleVerse @BibleId, 120020011, N'Even a young man is known by his actions, whether his activity is pure and whether it is right.'
EXEC add_BibleVerse @BibleId, 120020012, N'The ear that hears and the eye that sees – the Lord has made them both.'
EXEC add_BibleVerse @BibleId, 120020013, N'Do not love sleep, lest you become impoverished; open your eyes so that you might be satisfied with food.'
EXEC add_BibleVerse @BibleId, 120020014, N'“It’s worthless! It’s worthless!” says the buyer, but when he goes on his way, he boasts.'
EXEC add_BibleVerse @BibleId, 120020015, N'There is gold, and an abundance of rubies, but words of knowledge are like a precious jewel.'
EXEC add_BibleVerse @BibleId, 120020016, N'Take a man’s garment when he has given security for a stranger, and when he gives surety for strangers, hold him in pledge.'
EXEC add_BibleVerse @BibleId, 120020017, N'Bread gained by deceit tastes sweet to a person, but afterward his mouth will be filled with gravel.'
EXEC add_BibleVerse @BibleId, 120020018, N'Plans are established by counsel, so make war with guidance.'
EXEC add_BibleVerse @BibleId, 120020019, N'The one who goes about gossiping reveals secrets; therefore do not associate with someone who is always opening his mouth.'
EXEC add_BibleVerse @BibleId, 120020020, N'The one who curses his father and his mother, his lamp will be extinguished in the blackest darkness.'
EXEC add_BibleVerse @BibleId, 120020021, N'An inheritance gained easily in the beginning will not be blessed in the end.'
EXEC add_BibleVerse @BibleId, 120020022, N'Do not say, “I will pay back evil!” Wait for the Lord, so that he may vindicate you.'
EXEC add_BibleVerse @BibleId, 120020023, N'The Lord abhors differing weights, and dishonest scales are wicked.'
EXEC add_BibleVerse @BibleId, 120020024, N'The steps of a person are ordained by the Lord – so how can anyone understand his own way?'
EXEC add_BibleVerse @BibleId, 120020025, N'It is a snare for a person to rashly cry, “Holy!” and only afterward to consider what he has vowed.'
EXEC add_BibleVerse @BibleId, 120020026, N'A wise king separates out the wicked; he turns the threshing wheel over them.'
EXEC add_BibleVerse @BibleId, 120020027, N'The human spirit is like the lamp of the Lord, searching all his innermost parts.'
EXEC add_BibleVerse @BibleId, 120020028, N'Loyal love and truth preserve a king, and his throne is upheld by loyal love.'
EXEC add_BibleVerse @BibleId, 120020029, N'The glory of young men is their strength, and the splendor of old men is gray hair.'
EXEC add_BibleVerse @BibleId, 120020030, N'Beatings and wounds cleanse away evil, and floggings cleanse the innermost being.'
EXEC add_BibleVerse @BibleId, 120021001, N'The king’s heart is in the hand of the Lord like channels of water; he turns it wherever he wants.'
EXEC add_BibleVerse @BibleId, 120021002, N'All of a person’s ways seem right in his own opinion, but the Lord evaluates the motives.'
EXEC add_BibleVerse @BibleId, 120021003, N'To do righteousness and justice is more acceptable to the Lord than sacrifice.'
EXEC add_BibleVerse @BibleId, 120021004, N'Haughty eyes and a proud heart – the agricultural product of the wicked is sin.'
EXEC add_BibleVerse @BibleId, 120021005, N'The plans of the diligent lead only to plenty, but everyone who is hasty comes only to poverty.'
EXEC add_BibleVerse @BibleId, 120021006, N'Making a fortune by a lying tongue is like a vapor driven back and forth; they seek death.'
EXEC add_BibleVerse @BibleId, 120021007, N'The violence done by the wicked will drag them away because they refuse to do what is right.'
EXEC add_BibleVerse @BibleId, 120021008, N'The way of the guilty person is devious, but as for the pure, his way is upright.'
EXEC add_BibleVerse @BibleId, 120021009, N'It is better to live on a corner of the housetop than in a house in company with a quarrelsome wife.'
EXEC add_BibleVerse @BibleId, 120021010, N'The appetite of the wicked desires evil; his neighbor is shown no favor in his eyes.'
EXEC add_BibleVerse @BibleId, 120021011, N'When a scorner is punished, the naive becomes wise; when a wise person is instructed, he gains knowledge.'
EXEC add_BibleVerse @BibleId, 120021012, N'The Righteous One considers the house of the wicked; he overthrows the wicked to their ruin.'
EXEC add_BibleVerse @BibleId, 120021013, N'The one who shuts his ears to the cry of the poor, he too will cry out and will not be answered.'
EXEC add_BibleVerse @BibleId, 120021014, N'A gift given in secret subdues anger, and a bribe given secretly subdues strong wrath.'
EXEC add_BibleVerse @BibleId, 120021015, N'Doing justice brings joy to the righteous and terror to those who do evil.'
EXEC add_BibleVerse @BibleId, 120021016, N'The one who wanders from the way of wisdom will end up in the company of the departed.'
EXEC add_BibleVerse @BibleId, 120021017, N'The one who loves pleasure will be a poor person; whoever loves wine and anointing oil will not be rich.'
EXEC add_BibleVerse @BibleId, 120021018, N'The wicked become a ransom for the righteous, and the faithless are taken in the place of the upright.'
EXEC add_BibleVerse @BibleId, 120021019, N'It is better to live in a desert land than with a quarrelsome and easily-provoked woman.'
EXEC add_BibleVerse @BibleId, 120021020, N'There is desirable treasure and olive oil in the dwelling of the wise, but a foolish person devours all he has.'
EXEC add_BibleVerse @BibleId, 120021021, N'The one who pursues righteousness and love finds life, bounty, and honor.'
EXEC add_BibleVerse @BibleId, 120021022, N'The wise person can scale the city of the mighty and bring down the stronghold in which they trust.'
EXEC add_BibleVerse @BibleId, 120021023, N'The one who guards his mouth and his tongue keeps his life from troubles.'
EXEC add_BibleVerse @BibleId, 120021024, N'A proud and arrogant person, whose name is “Scoffer,” acts with overbearing pride.'
EXEC add_BibleVerse @BibleId, 120021025, N'What the sluggard desires will kill him, for his hands refuse to work.'
EXEC add_BibleVerse @BibleId, 120021026, N'All day long he craves greedily, but the righteous gives and does not hold back.'
EXEC add_BibleVerse @BibleId, 120021027, N'The wicked person’s sacrifice is an abomination; how much more when he brings it with evil intent!'
EXEC add_BibleVerse @BibleId, 120021028, N'A lying witness will perish, but the one who reports accurately speaks forever.'
EXEC add_BibleVerse @BibleId, 120021029, N'A wicked person shows boldness with his face, but as for the upright, he discerns his ways.'
EXEC add_BibleVerse @BibleId, 120021030, N'There is no wisdom and there is no understanding, and there is no counsel against the Lord.'
EXEC add_BibleVerse @BibleId, 120021031, N'A horse is prepared for the day of battle, but the victory is from the Lord.'
EXEC add_BibleVerse @BibleId, 120022001, N'A good name is to be chosen rather than great wealth, good favor more than silver or gold.'
EXEC add_BibleVerse @BibleId, 120022002, N'The rich and the poor meet together; the Lord is the creator of them both.'
EXEC add_BibleVerse @BibleId, 120022003, N'A shrewd person sees danger and hides himself, but the naive keep right on going and suffer for it.'
EXEC add_BibleVerse @BibleId, 120022004, N'The reward for humility and fearing the Lord is riches and honor and life.'
EXEC add_BibleVerse @BibleId, 120022005, N'Thorns and snares are in the path of the perverse, but the one who guards himself keeps far from them.'
EXEC add_BibleVerse @BibleId, 120022006, N'Train a child in the way that he should go, and when he is old he will not turn from it.'
EXEC add_BibleVerse @BibleId, 120022007, N'The rich rule over the poor, and the borrower is servant to the lender.'
EXEC add_BibleVerse @BibleId, 120022008, N'The one who sows iniquity will reap trouble, and the rod of his fury will end.'
EXEC add_BibleVerse @BibleId, 120022009, N'A generous person will be blessed, for he gives some of his food to the poor.'
EXEC add_BibleVerse @BibleId, 120022010, N'Drive out the scorner and contention will leave; strife and insults will cease.'
EXEC add_BibleVerse @BibleId, 120022011, N'The one who loves a pure heart and whose speech is gracious – the king will be his friend.'
EXEC add_BibleVerse @BibleId, 120022012, N'The eyes of the Lord guard knowledge, but he overthrows the words of the faithless person.'
EXEC add_BibleVerse @BibleId, 120022013, N'The sluggard says, “There is a lion outside! I will be killed in the middle of the streets!”'
EXEC add_BibleVerse @BibleId, 120022014, N'The mouth of an adulteress is like a deep pit; the one against whom the Lord is angry will fall into it.'
EXEC add_BibleVerse @BibleId, 120022015, N'Folly is bound up in the heart of a child, but the rod of discipline will drive it far from him.'
EXEC add_BibleVerse @BibleId, 120022016, N'The one who oppresses the poor to increase his own gain and the one who gives to the rich – both end up only in poverty.'
EXEC add_BibleVerse @BibleId, 120022017, N'Incline your ear and listen to the words of the wise, and apply your heart to my instruction.'
EXEC add_BibleVerse @BibleId, 120022018, N'For it is pleasing if you keep these sayings within you, and they are ready on your lips.'
EXEC add_BibleVerse @BibleId, 120022019, N'So that your confidence may be in the Lord, I am making them known to you today – even you.'
EXEC add_BibleVerse @BibleId, 120022020, N'Have I not written thirty sayings for you, sayings of counsel and knowledge,'
EXEC add_BibleVerse @BibleId, 120022021, N'to show you true and reliable words, so that you may give accurate answers to those who sent you?'
EXEC add_BibleVerse @BibleId, 120022022, N'Do not exploit a poor person because he is poor and do not crush the needy in court,'
EXEC add_BibleVerse @BibleId, 120022023, N'for the Lord will plead their case and will rob those who are robbing them.'
EXEC add_BibleVerse @BibleId, 120022024, N'Do not make friends with an angry person, and do not associate with a wrathful person,'
EXEC add_BibleVerse @BibleId, 120022025, N'lest you learn his ways and entangle yourself in a snare.'
EXEC add_BibleVerse @BibleId, 120022026, N'Do not be one who strikes hands in pledge or who puts up security for debts.'
EXEC add_BibleVerse @BibleId, 120022027, N'If you do not have enough to pay, your bed will be taken right out from under you!'
EXEC add_BibleVerse @BibleId, 120022028, N'Do not move an ancient boundary stone which was put in place by your ancestors.'
EXEC add_BibleVerse @BibleId, 120022029, N'Do you see a person skilled in his work? He will take his position before kings; he will not take his position before obscure people.'
EXEC add_BibleVerse @BibleId, 120023001, N'When you sit down to eat with a ruler, consider carefully what is before you,'
EXEC add_BibleVerse @BibleId, 120023002, N'and put a knife to your throat if you possess a large appetite.'
EXEC add_BibleVerse @BibleId, 120023003, N'Do not crave that ruler’s delicacies, for that food is deceptive.'
EXEC add_BibleVerse @BibleId, 120023004, N'Do not wear yourself out to become rich; be wise enough to restrain yourself.'
EXEC add_BibleVerse @BibleId, 120023005, N'When you gaze upon riches, they are gone, for they surely make wings for themselves, and fly off into the sky like an eagle!'
EXEC add_BibleVerse @BibleId, 120023006, N'Do not eat the food of a stingy person, do not crave his delicacies;'
EXEC add_BibleVerse @BibleId, 120023007, N'for he is like someone calculating the cost in his mind. “Eat and drink,” he says to you, but his heart is not with you;'
EXEC add_BibleVerse @BibleId, 120023008, N'you will vomit up the little bit you have eaten, and will have wasted your pleasant words.'
EXEC add_BibleVerse @BibleId, 120023009, N'Do not speak in the ears of a fool, for he will despise the wisdom of your words.'
EXEC add_BibleVerse @BibleId, 120023010, N'Do not move an ancient boundary stone, or take over the fields of the fatherless,'
EXEC add_BibleVerse @BibleId, 120023011, N'for their Protector is strong; he will plead their case against you.'
EXEC add_BibleVerse @BibleId, 120023012, N'Apply your heart to instruction and your ears to the words of knowledge.'
EXEC add_BibleVerse @BibleId, 120023013, N'Do not withhold discipline from a child; even if you strike him with the rod, he will not die.'
EXEC add_BibleVerse @BibleId, 120023014, N'If you strike him with the rod, you will deliver him from death.'
EXEC add_BibleVerse @BibleId, 120023015, N'My child, if your heart is wise, then my heart also will be glad;'
EXEC add_BibleVerse @BibleId, 120023016, N'my soul will rejoice when your lips speak what is right.'
EXEC add_BibleVerse @BibleId, 120023017, N'Do not let your heart envy sinners, but rather be zealous in fearing the Lord all the time.'
EXEC add_BibleVerse @BibleId, 120023018, N'For surely there is a future, and your hope will not be cut off.'
EXEC add_BibleVerse @BibleId, 120023019, N'Listen, my child, and be wise, and guide your heart on the right way.'
EXEC add_BibleVerse @BibleId, 120023020, N'Do not spend time among drunkards, among those who eat too much meat,'
EXEC add_BibleVerse @BibleId, 120023021, N'because drunkards and gluttons become impoverished, and drowsiness clothes them with rags.'
EXEC add_BibleVerse @BibleId, 120023022, N'Listen to your father who begot you, and do not despise your mother when she is old.'
EXEC add_BibleVerse @BibleId, 120023023, N'Acquire truth and do not sell it – wisdom, and discipline, and understanding.'
EXEC add_BibleVerse @BibleId, 120023024, N'The father of a righteous person will rejoice greatly; whoever fathers a wise child will have joy in him.'
EXEC add_BibleVerse @BibleId, 120023025, N'May your father and your mother have joy; may she who bore you rejoice.'
EXEC add_BibleVerse @BibleId, 120023026, N'Give me your heart, my son, and let your eyes observe my ways;'
EXEC add_BibleVerse @BibleId, 120023027, N'for a prostitute is like a deep pit; a harlot is like a narrow well.'
EXEC add_BibleVerse @BibleId, 120023028, N'Indeed, she lies in wait like a robber, and increases the unfaithful among men.'
EXEC add_BibleVerse @BibleId, 120023029, N'Who has woe? Who has sorrow? Who has contentions? Who has complaints? Who has wounds without cause? Who has dullness of the eyes?'
EXEC add_BibleVerse @BibleId, 120023030, N'Those who linger over wine, those who go looking for mixed wine.'
EXEC add_BibleVerse @BibleId, 120023031, N'Do not look on the wine when it is red, when it sparkles in the cup, when it goes down smoothly.'
EXEC add_BibleVerse @BibleId, 120023032, N'Afterward it bites like a snake, and stings like a viper.'
EXEC add_BibleVerse @BibleId, 120023033, N'Your eyes will see strange things, and your mind will speak perverse things.'
EXEC add_BibleVerse @BibleId, 120023034, N'And you will be like one who lies down in the midst of the sea, and like one who lies down on the top of the rigging.'
EXEC add_BibleVerse @BibleId, 120023035, N'You will say, “They have struck me, but I am not harmed! They beat me, but I did not know it! When will I awake? I will look for another drink.”'
EXEC add_BibleVerse @BibleId, 120024001, N'Do not envy evil people, do not desire to be with them;'
EXEC add_BibleVerse @BibleId, 120024002, N'for their hearts contemplate violence, and their lips speak harm.'
EXEC add_BibleVerse @BibleId, 120024003, N'By wisdom a house is built, and through understanding it is established;'
EXEC add_BibleVerse @BibleId, 120024004, N'by knowledge its rooms are filled with all kinds of precious and pleasing treasures.'
EXEC add_BibleVerse @BibleId, 120024005, N'A wise warrior is strong, and a man of knowledge makes his strength stronger;'
EXEC add_BibleVerse @BibleId, 120024006, N'for with guidance you wage your war, and with numerous advisers there is victory.'
EXEC add_BibleVerse @BibleId, 120024007, N'Wisdom is unattainable for a fool; in court he does not open his mouth.'
EXEC add_BibleVerse @BibleId, 120024008, N'The one who plans to do evil will be called a scheming person.'
EXEC add_BibleVerse @BibleId, 120024009, N'A foolish scheme is sin, and the scorner is an abomination to people.'
EXEC add_BibleVerse @BibleId, 120024010, N'If you faint in the day of trouble, your strength is small!'
EXEC add_BibleVerse @BibleId, 120024011, N'Deliver those being taken away to death, and hold back those slipping to the slaughter.'
EXEC add_BibleVerse @BibleId, 120024012, N'If you say, “But we did not know about this,” does not the one who evaluates hearts consider? Does not the one who guards your life know? Will he not repay each person according to his deeds?'
EXEC add_BibleVerse @BibleId, 120024013, N'Eat honey, my child, for it is good, and honey from the honeycomb is sweet to your taste.'
EXEC add_BibleVerse @BibleId, 120024014, N'Likewise, know that wisdom is sweet to your soul; if you find it, you will have a future, and your hope will not be cut off.'
EXEC add_BibleVerse @BibleId, 120024015, N'Do not lie in wait like the wicked against the place where the righteous live; do not assault his home.'
EXEC add_BibleVerse @BibleId, 120024016, N'Although a righteous person may fall seven times, he gets up again, but the wicked will be brought down by calamity.'
EXEC add_BibleVerse @BibleId, 120024017, N'Do not rejoice when your enemy falls, and when he stumbles do not let your heart rejoice,'
EXEC add_BibleVerse @BibleId, 120024018, N'lest the Lord see it, and be displeased, and turn his wrath away from him.'
EXEC add_BibleVerse @BibleId, 120024019, N'Do not fret because of evil people or be envious of wicked people,'
EXEC add_BibleVerse @BibleId, 120024020, N'for the evil person has no future, and the lamp of the wicked will be extinguished.'
EXEC add_BibleVerse @BibleId, 120024021, N'Fear the Lord, my child, as well as the king, and do not associate with rebels,'
EXEC add_BibleVerse @BibleId, 120024022, N'for suddenly their destruction will overtake them, and who knows the ruinous judgment both the Lord and the king can bring?'
EXEC add_BibleVerse @BibleId, 120024023, N'These sayings also are from the wise: To show partiality in judgment is terrible:'
EXEC add_BibleVerse @BibleId, 120024024, N'The one who says to the guilty, “You are innocent,” peoples will curse him, and nations will denounce him.'
EXEC add_BibleVerse @BibleId, 120024025, N'But there will be delight for those who convict the guilty, and a pleasing blessing will come on them.'
EXEC add_BibleVerse @BibleId, 120024026, N'Like a kiss on the lips is the one who gives an honest answer.'
EXEC add_BibleVerse @BibleId, 120024027, N'Establish your work outside and get your fields ready; afterward build your house.'
EXEC add_BibleVerse @BibleId, 120024028, N'Do not be a witness against your neighbor without cause, and do not deceive with your words.'
EXEC add_BibleVerse @BibleId, 120024029, N'Do not say, “I will do to him just as he has done to me; I will pay him back according to what he has done.”'
EXEC add_BibleVerse @BibleId, 120024030, N'I passed by the field of a sluggard, by the vineyard of one who lacks wisdom.'
EXEC add_BibleVerse @BibleId, 120024031, N'I saw that thorns had grown up all over it, the ground was covered with weeds, and its stone wall was broken down.'
EXEC add_BibleVerse @BibleId, 120024032, N'When I saw this, I gave careful consideration to it; I received instruction from what I saw:'
EXEC add_BibleVerse @BibleId, 120024033, N'“A little sleep, a little slumber, a little folding of the hands to relax,'
EXEC add_BibleVerse @BibleId, 120024034, N'and your poverty will come like a bandit, and your need like an armed robber.”'
EXEC add_BibleVerse @BibleId, 120025001, N'These also are proverbs of Solomon, which the men of King Hezekiah of Judah copied:'
EXEC add_BibleVerse @BibleId, 120025002, N'It is the glory of God to conceal a matter, and it is the glory of a king to search out a matter.'
EXEC add_BibleVerse @BibleId, 120025003, N'As the heaven is high and the earth is deep so the hearts of kings are unsearchable.'
EXEC add_BibleVerse @BibleId, 120025004, N'Remove the dross from the silver, and material for the silversmith will emerge;'
EXEC add_BibleVerse @BibleId, 120025005, N'remove the wicked from before the king, and his throne will be established in righteousness.'
EXEC add_BibleVerse @BibleId, 120025006, N'Do not honor yourself before the king, and do not stand in the place of great men;'
EXEC add_BibleVerse @BibleId, 120025007, N'for it is better for him to say to you, “Come up here,” than to put you lower before a prince, whom your eyes have seen.'
EXEC add_BibleVerse @BibleId, 120025008, N'Do not go out hastily to litigation, or what will you do afterward when your neighbor puts you to shame?'
EXEC add_BibleVerse @BibleId, 120025009, N'When you argue a case with your neighbor, do not reveal the secret of another person,'
EXEC add_BibleVerse @BibleId, 120025010, N'lest the one who hears it put you to shame and your infamy will never go away.'
EXEC add_BibleVerse @BibleId, 120025011, N'Like apples of gold in settings of silver, so is a word skillfully spoken.'
EXEC add_BibleVerse @BibleId, 120025012, N'Like an earring of gold and an ornament of fine gold, so is a wise reprover to the ear of the one who listens.'
EXEC add_BibleVerse @BibleId, 120025013, N'Like the cold of snow in the time of harvest, so is a faithful messenger to those who send him, for he refreshes the heart of his masters.'
EXEC add_BibleVerse @BibleId, 120025014, N'Like cloudy skies and wind that produce no rain, so is the one who boasts of a gift not given.'
EXEC add_BibleVerse @BibleId, 120025015, N'Through patience a ruler can be persuaded, and a soft tongue can break a bone.'
EXEC add_BibleVerse @BibleId, 120025016, N'When you find honey, eat only what is sufficient for you, lest you become stuffed with it and vomit it up.'
EXEC add_BibleVerse @BibleId, 120025017, N'Don’t set foot too frequently in your neighbor’s house, lest he become weary of you and hate you.'
EXEC add_BibleVerse @BibleId, 120025018, N'Like a club or a sword or a sharp arrow, so is the one who testifies against his neighbor as a false witness.'
EXEC add_BibleVerse @BibleId, 120025019, N'Like a bad tooth or a foot out of joint, so is confidence in an unfaithful person at the time of trouble.'
EXEC add_BibleVerse @BibleId, 120025020, N'Like one who takes off a garment on a cold day, or like vinegar poured on soda, so is one who sings songs to a heavy heart.'
EXEC add_BibleVerse @BibleId, 120025021, N'If your enemy is hungry, give him food to eat, and if he is thirsty, give him water to drink,'
EXEC add_BibleVerse @BibleId, 120025022, N'for you will heap coals of fire on his head, and the Lord will reward you.'
EXEC add_BibleVerse @BibleId, 120025023, N'The north wind brings forth rain, and a gossiping tongue brings forth an angry look.'
EXEC add_BibleVerse @BibleId, 120025024, N'It is better to live on a corner of the housetop than in a house in company with a quarrelsome wife.'
EXEC add_BibleVerse @BibleId, 120025025, N'Like cold water to a weary person, so is good news from a distant land.'
EXEC add_BibleVerse @BibleId, 120025026, N'Like a muddied spring and a polluted well, so is a righteous person who gives way before the wicked.'
EXEC add_BibleVerse @BibleId, 120025027, N'It is not good to eat too much honey, nor is it honorable for people to seek their own glory.'
EXEC add_BibleVerse @BibleId, 120025028, N'Like a city that is broken down and without a wall, so is a person who cannot control his temper.'
EXEC add_BibleVerse @BibleId, 120026001, N'Like snow in summer or rain in harvest, so honor is not fitting for a fool.'
EXEC add_BibleVerse @BibleId, 120026002, N'Like a fluttering bird or like a flying swallow, so a curse without cause does not come to rest.'
EXEC add_BibleVerse @BibleId, 120026003, N'A whip for the horse and a bridle for the donkey, and a rod for the backs of fools!'
EXEC add_BibleVerse @BibleId, 120026004, N'Do not answer a fool according to his folly, lest you yourself also be like him.'
EXEC add_BibleVerse @BibleId, 120026005, N'Answer a fool according to his folly, lest he be wise in his own estimation.'
EXEC add_BibleVerse @BibleId, 120026006, N'Like cutting off the feet or drinking violence, so is sending a message by the hand of a fool.'
EXEC add_BibleVerse @BibleId, 120026007, N'Like legs that hang limp from the lame, so is a proverb in the mouth of fools.'
EXEC add_BibleVerse @BibleId, 120026008, N'Like tying a stone in a sling, so is giving honor to a fool.'
EXEC add_BibleVerse @BibleId, 120026009, N'Like a thorn that goes into the hand of a drunkard, so is a proverb in the mouth of a fool.'
EXEC add_BibleVerse @BibleId, 120026010, N'Like an archer who wounds at random, so is the one who hires a fool or hires any passer-by.'
EXEC add_BibleVerse @BibleId, 120026011, N'Like a dog that returns to its vomit, so a fool repeats his folly.'
EXEC add_BibleVerse @BibleId, 120026012, N'Do you see a man wise in his own eyes? There is more hope for a fool than for him.'
EXEC add_BibleVerse @BibleId, 120026013, N'The sluggard says, “There is a lion in the road! A lion in the streets!”'
EXEC add_BibleVerse @BibleId, 120026014, N'Like a door that turns on its hinges, so a sluggard turns on his bed.'
EXEC add_BibleVerse @BibleId, 120026015, N'The sluggard plunges his hand in the dish; he is too lazy to bring it back to his mouth.'
EXEC add_BibleVerse @BibleId, 120026016, N'The sluggard is wiser in his own estimation than seven people who respond with good sense.'
EXEC add_BibleVerse @BibleId, 120026017, N'Like one who grabs a wild dog by the ears, so is the person passing by who becomes furious over a quarrel not his own.'
EXEC add_BibleVerse @BibleId, 120026018, N'Like a madman who shoots firebrands and deadly arrows,'
EXEC add_BibleVerse @BibleId, 120026019, N'so is a person who deceives his neighbor, and says, “Was I not only joking?”'
EXEC add_BibleVerse @BibleId, 120026020, N'Where there is no wood, a fire goes out, and where there is no gossip, contention ceases.'
EXEC add_BibleVerse @BibleId, 120026021, N'Like charcoal is to burning coals, and wood to fire, so is a contentious person to kindle strife.'
EXEC add_BibleVerse @BibleId, 120026022, N'The words of a gossip are like delicious morsels; they go down into a person’s innermost being.'
EXEC add_BibleVerse @BibleId, 120026023, N'Like a coating of glaze over earthenware are fervent lips with an evil heart.'
EXEC add_BibleVerse @BibleId, 120026024, N'The one who hates others disguises it with his lips, but he stores up deceit within him.'
EXEC add_BibleVerse @BibleId, 120026025, N'When he speaks graciously, do not believe him, for there are seven abominations within him.'
EXEC add_BibleVerse @BibleId, 120026026, N'Though his hatred may be concealed by deceit, his evil will be uncovered in the assembly.'
EXEC add_BibleVerse @BibleId, 120026027, N'The one who digs a pit will fall into it; the one who rolls a stone – it will come back on him.'
EXEC add_BibleVerse @BibleId, 120026028, N'A lying tongue hates those crushed by it, and a flattering mouth works ruin.'
EXEC add_BibleVerse @BibleId, 120027001, N'Do not boast about tomorrow; for you do not know what a day may bring forth.'
EXEC add_BibleVerse @BibleId, 120027002, N'Let another praise you, and not your own mouth; someone else, and not your own lips.'
EXEC add_BibleVerse @BibleId, 120027003, N'A stone is heavy and sand is weighty, but vexation by a fool is more burdensome than the two of them.'
EXEC add_BibleVerse @BibleId, 120027004, N'Wrath is cruel and anger is overwhelming, but who can stand before jealousy?'
EXEC add_BibleVerse @BibleId, 120027005, N'Better is open rebuke than hidden love.'
EXEC add_BibleVerse @BibleId, 120027006, N'Faithful are the wounds of a friend, but the kisses of an enemy are excessive.'
EXEC add_BibleVerse @BibleId, 120027007, N'The one whose appetite is satisfied loathes honey, but to the hungry mouth every bitter thing is sweet.'
EXEC add_BibleVerse @BibleId, 120027008, N'Like a bird that wanders from its nest, so is a person who wanders from his home.'
EXEC add_BibleVerse @BibleId, 120027009, N'Ointment and incense make the heart rejoice, likewise the sweetness of one’s friend from sincere counsel.'
EXEC add_BibleVerse @BibleId, 120027010, N'Do not forsake your friend and your father’s friend, and do not enter your brother’s house in the day of your disaster; a neighbor nearby is better than a brother far away.'
EXEC add_BibleVerse @BibleId, 120027011, N'Be wise, my son, and make my heart glad, so that I may answer anyone who taunts me.'
EXEC add_BibleVerse @BibleId, 120027012, N'A shrewd person sees danger and hides himself, but the naive keep right on going and suffer for it.'
EXEC add_BibleVerse @BibleId, 120027013, N'Take a man’s garment when he has given security for a stranger, and when he gives surety for a stranger, hold him in pledge.'
EXEC add_BibleVerse @BibleId, 120027014, N'If someone blesses his neighbor with a loud voice early in the morning, it will be counted as a curse to him.'
EXEC add_BibleVerse @BibleId, 120027015, N'A continual dripping on a rainy day and a contentious wife are alike.'
EXEC add_BibleVerse @BibleId, 120027016, N'Whoever hides her hides the wind or grasps oil with his right hand.'
EXEC add_BibleVerse @BibleId, 120027017, N'As iron sharpens iron, so a person sharpens his friend.'
EXEC add_BibleVerse @BibleId, 120027018, N'The one who tends a fig tree will eat its fruit, and whoever takes care of his master will be honored.'
EXEC add_BibleVerse @BibleId, 120027019, N'As in water the face is reflected as a face, so a person’s heart reflects the person.'
EXEC add_BibleVerse @BibleId, 120027020, N'As Death and Destruction are never satisfied, so the eyes of a person are never satisfied.'
EXEC add_BibleVerse @BibleId, 120027021, N'As the crucible is for silver and the furnace is for gold, so a person is proved by the praise he receives.'
EXEC add_BibleVerse @BibleId, 120027022, N'If you should pound the fool in the mortar among the grain with the pestle, his foolishness would not depart from him.'
EXEC add_BibleVerse @BibleId, 120027023, N'Pay careful attention to the condition of your flocks, give careful attention to your herds,'
EXEC add_BibleVerse @BibleId, 120027024, N'for riches do not last forever, nor does a crown last from generation to generation.'
EXEC add_BibleVerse @BibleId, 120027025, N'When the hay is removed and new grass appears, and the grass from the hills is gathered in,'
EXEC add_BibleVerse @BibleId, 120027026, N'the lambs will be for your clothing, and the goats will be for the price of a field.'
EXEC add_BibleVerse @BibleId, 120027027, N'And there will be enough goat’s milk for your food, for the food of your household, and for the sustenance of your servant girls.'
EXEC add_BibleVerse @BibleId, 120028001, N'The wicked person flees when there is no one pursuing, but the righteous person is as confident as a lion.'
EXEC add_BibleVerse @BibleId, 120028002, N'When a country is rebellious it has many princes, but by someone who is discerning and knowledgeable order is maintained.'
EXEC add_BibleVerse @BibleId, 120028003, N'A poor person who oppresses the weak is like a driving rain without food.'
EXEC add_BibleVerse @BibleId, 120028004, N'Those who forsake the law praise the wicked, but those who keep the law contend with them.'
EXEC add_BibleVerse @BibleId, 120028005, N'Evil people do not understand justice, but those who seek the Lord understand it all.'
EXEC add_BibleVerse @BibleId, 120028006, N'A poor person who walks in his integrity is better than one who is perverse in his ways even though he is rich.'
EXEC add_BibleVerse @BibleId, 120028007, N'The one who keeps the law is a discerning child, but a companion of gluttons brings shame to his parents.'
EXEC add_BibleVerse @BibleId, 120028008, N'The one who increases his wealth by increasing interest gathers it for someone who is gracious to the needy.'
EXEC add_BibleVerse @BibleId, 120028009, N'The one who turns away his ear from hearing the law, even his prayer is an abomination.'
EXEC add_BibleVerse @BibleId, 120028010, N'The one who leads the upright astray in an evil way will himself fall into his own pit, but the blameless will inherit what is good.'
EXEC add_BibleVerse @BibleId, 120028011, N'A rich person is wise in his own eyes, but a discerning poor person can evaluate him properly.'
EXEC add_BibleVerse @BibleId, 120028012, N'When the righteous rejoice, great is the glory, but when the wicked rise to power, people are sought out.'
EXEC add_BibleVerse @BibleId, 120028013, N'The one who covers his transgressions will not prosper, but whoever confesses them and forsakes them will find mercy.'
EXEC add_BibleVerse @BibleId, 120028014, N'Blessed is the one who is always cautious, but whoever hardens his heart will fall into evil.'
EXEC add_BibleVerse @BibleId, 120028015, N'Like a roaring lion or a roving bear, so is a wicked ruler over a poor people.'
EXEC add_BibleVerse @BibleId, 120028016, N'The prince who is a great oppressor lacks wisdom, but the one who hates unjust gain will prolong his days.'
EXEC add_BibleVerse @BibleId, 120028017, N'The one who is tormented by the murder of another will flee to the pit; let no one support him.'
EXEC add_BibleVerse @BibleId, 120028018, N'The one who walks blamelessly will be delivered, but whoever is perverse in his ways will fall at once.'
EXEC add_BibleVerse @BibleId, 120028019, N'The one who works his land will be satisfied with food, but whoever chases daydreams will have his fill of poverty.'
EXEC add_BibleVerse @BibleId, 120028020, N'A faithful person will have an abundance of blessings, but the one who hastens to gain riches will not go unpunished.'
EXEC add_BibleVerse @BibleId, 120028021, N'To show partiality is terrible, for a person will transgress over the smallest piece of bread.'
EXEC add_BibleVerse @BibleId, 120028022, N'The stingy person hastens after riches and does not know that poverty will overtake him.'
EXEC add_BibleVerse @BibleId, 120028023, N'The one who reproves another will in the end find more favor than the one who flatters with the tongue.'
EXEC add_BibleVerse @BibleId, 120028024, N'The one who robs his father and mother and says, “There is no transgression,” is a companion to the one who destroys.'
EXEC add_BibleVerse @BibleId, 120028025, N'The greedy person stirs up dissension, but the one who trusts in the Lord will prosper.'
EXEC add_BibleVerse @BibleId, 120028026, N'The one who trusts in his own heart is a fool, but the one who walks in wisdom will escape.'
EXEC add_BibleVerse @BibleId, 120028027, N'The one who gives to the poor will not lack, but whoever shuts his eyes to them will receive many curses.'
EXEC add_BibleVerse @BibleId, 120028028, N'When the wicked gain control, people hide themselves, but when they perish, the righteous increase.'
EXEC add_BibleVerse @BibleId, 120029001, N'The one who stiffens his neck after numerous rebukes will suddenly be destroyed without remedy.'
EXEC add_BibleVerse @BibleId, 120029002, N'When the righteous become numerous, the people rejoice; when the wicked rule, the people groan.'
EXEC add_BibleVerse @BibleId, 120029003, N'The man who loves wisdom brings joy to his father, but whoever associates with prostitutes wastes his wealth.'
EXEC add_BibleVerse @BibleId, 120029004, N'A king brings stability to a land by justice, but one who exacts tribute tears it down.'
EXEC add_BibleVerse @BibleId, 120029005, N'The one who flatters his neighbor spreads a net for his steps.'
EXEC add_BibleVerse @BibleId, 120029006, N'In the transgression of an evil person there is a snare, but a righteous person can sing and rejoice.'
EXEC add_BibleVerse @BibleId, 120029007, N'The righteous person cares for the legal rights of the poor; the wicked does not understand such knowledge.'
EXEC add_BibleVerse @BibleId, 120029008, N'Scornful people inflame a city, but those who are wise turn away wrath.'
EXEC add_BibleVerse @BibleId, 120029009, N'If a wise person goes to court with a foolish person, there is no peace whether he is angry or laughs.'
EXEC add_BibleVerse @BibleId, 120029010, N'Bloodthirsty people hate someone with integrity; as for the upright, they seek his life.'
EXEC add_BibleVerse @BibleId, 120029011, N'A fool lets fly with all his temper, but a wise person keeps it back.'
EXEC add_BibleVerse @BibleId, 120029012, N'If a ruler listens to lies, all his ministers will be wicked.'
EXEC add_BibleVerse @BibleId, 120029013, N'The poor person and the oppressor have this in common: the Lord gives light to the eyes of them both.'
EXEC add_BibleVerse @BibleId, 120029014, N'If a king judges the poor in truth, his throne will be established forever.'
EXEC add_BibleVerse @BibleId, 120029015, N'A rod and reproof impart wisdom, but a child who is unrestrained brings shame to his mother.'
EXEC add_BibleVerse @BibleId, 120029016, N'When the wicked increase, transgression increases, but the righteous will see their downfall.'
EXEC add_BibleVerse @BibleId, 120029017, N'Discipline your child, and he will give you rest; he will bring you happiness.'
EXEC add_BibleVerse @BibleId, 120029018, N'When there is no prophetic vision the people cast off restraint, but the one who keeps the law, blessed is he!'
EXEC add_BibleVerse @BibleId, 120029019, N'A servant cannot be corrected by words, for although he understands, there is no answer.'
EXEC add_BibleVerse @BibleId, 120029020, N'Do you see someone who is hasty in his words? There is more hope for a fool than for him.'
EXEC add_BibleVerse @BibleId, 120029021, N'If someone pampers his servant from youth, he will be a weakling in the end.'
EXEC add_BibleVerse @BibleId, 120029022, N'An angry person stirs up dissension, and a wrathful person is abounding in transgression.'
EXEC add_BibleVerse @BibleId, 120029023, N'A person’s pride will bring him low, but one who has a lowly spirit will gain honor.'
EXEC add_BibleVerse @BibleId, 120029024, N'Whoever shares with a thief is his own enemy; he hears the oath to testify, but does not talk.'
EXEC add_BibleVerse @BibleId, 120029025, N'The fear of people becomes a snare, but whoever trusts in the Lord will be set on high.'
EXEC add_BibleVerse @BibleId, 120029026, N'Many people seek the face of a ruler, but it is from the Lord that one receives justice.'
EXEC add_BibleVerse @BibleId, 120029027, N'An unjust person is an abomination to the righteous, and the one who lives an upright life is an abomination to the wicked.'
EXEC add_BibleVerse @BibleId, 120030001, N'The words of Agur, the son of Jakeh; an oracle: This man says to Ithiel, to Ithiel and to Ukal:'
EXEC add_BibleVerse @BibleId, 120030002, N'Surely I am more brutish than any other human being, and I do not have human understanding;'
EXEC add_BibleVerse @BibleId, 120030003, N'I have not learned wisdom, nor do I have knowledge of the Holy One.'
EXEC add_BibleVerse @BibleId, 120030004, N'Who has ascended into heaven, and then descended? Who has gathered up the winds in his fists? Who has bound up the waters in his cloak? Who has established all the ends of the earth? What is his name, and what is his son’s name? – if you know!'
EXEC add_BibleVerse @BibleId, 120030005, N'Every word of God is purified; he is like a shield for those who take refuge in him.'
EXEC add_BibleVerse @BibleId, 120030006, N'Do not add to his words, lest he reprove you, and prove you to be a liar.'
EXEC add_BibleVerse @BibleId, 120030007, N'Two things I ask from you; do not refuse me before I die:'
EXEC add_BibleVerse @BibleId, 120030008, N'Remove falsehood and lies far from me; do not give me poverty or riches, feed me with my allotted portion of bread,'
EXEC add_BibleVerse @BibleId, 120030009, N'lest I become satisfied and act deceptively and say, “Who is the Lord?” Or lest I become poor and steal and demean the name of my God.'
EXEC add_BibleVerse @BibleId, 120030010, N'Do not slander a servant to his master, lest he curse you, and you are found guilty.'
EXEC add_BibleVerse @BibleId, 120030011, N'There is a generation who curse their fathers and do not bless their mothers.'
EXEC add_BibleVerse @BibleId, 120030012, N'There is a generation who are pure in their own eyes and yet are not washed from their filthiness.'
EXEC add_BibleVerse @BibleId, 120030013, N'There is a generation whose eyes are so lofty, and whose eyelids are lifted up disdainfully.'
EXEC add_BibleVerse @BibleId, 120030014, N'There is a generation whose teeth are like swords and whose molars are like knives to devour the poor from the earth and the needy from among the human race.'
EXEC add_BibleVerse @BibleId, 120030015, N'The leech has two daughters: “Give! Give!” There are three things that are never satisfied, four that never say, “Enough” –'
EXEC add_BibleVerse @BibleId, 120030016, N'the grave, the barren womb, land that is not satisfied with water, and fire that never says, “Enough!”'
EXEC add_BibleVerse @BibleId, 120030017, N'The eye that mocks at a father and despises obeying a mother – the ravens of the valley will peck it out and the young vultures will eat it.'
EXEC add_BibleVerse @BibleId, 120030018, N'There are three things that are too wonderful for me, four that I do not understand:'
EXEC add_BibleVerse @BibleId, 120030019, N'the way of an eagle in the sky, the way of a snake on a rock, the way of a ship in the sea, and the way of a man with a woman.'
EXEC add_BibleVerse @BibleId, 120030020, N'This is the way of an adulterous woman: she eats and wipes her mouth and says, “I have not done wrong.”'
EXEC add_BibleVerse @BibleId, 120030021, N'Under three things the earth trembles, and under four things it cannot bear up:'
EXEC add_BibleVerse @BibleId, 120030022, N'under a servant who becomes king, under a fool who is stuffed with food,'
EXEC add_BibleVerse @BibleId, 120030023, N'under an unloved woman who is married, and under a female servant who dispossesses her mistress.'
EXEC add_BibleVerse @BibleId, 120030024, N'There are four things on earth that are small, but they are exceedingly wise:'
EXEC add_BibleVerse @BibleId, 120030025, N'ants are creatures with little strength, but they prepare their food in the summer;'
EXEC add_BibleVerse @BibleId, 120030026, N'rock badgers are creatures with little power, but they make their homes in the crags;'
EXEC add_BibleVerse @BibleId, 120030027, N'locusts have no king, but they all go forward by ranks;'
EXEC add_BibleVerse @BibleId, 120030028, N'a lizard you can catch with the hand, but it gets into the palaces of the king.'
EXEC add_BibleVerse @BibleId, 120030029, N'There are three things that are magnificent in their step, four things that move about magnificently:'
EXEC add_BibleVerse @BibleId, 120030030, N'a lion, mightiest of the beasts, who does not retreat from anything;'
EXEC add_BibleVerse @BibleId, 120030031, N'a strutting rooster, a male goat, and a king with his army around him.'
EXEC add_BibleVerse @BibleId, 120030032, N'If you have done foolishly by exalting yourself or if you have planned evil, put your hand over your mouth!'
EXEC add_BibleVerse @BibleId, 120030033, N'For as the churning of milk produces butter and as punching the nose produces blood, so stirring up anger produces strife.'
EXEC add_BibleVerse @BibleId, 120031001, N'The words of King Lemuel, an oracle that his mother taught him:'
EXEC add_BibleVerse @BibleId, 120031002, N'O my son, O son of my womb, O son of my vows,'
EXEC add_BibleVerse @BibleId, 120031003, N'Do not give your strength to women, nor your ways to that which ruins kings.'
EXEC add_BibleVerse @BibleId, 120031004, N'It is not for kings, O Lemuel, it is not for kings to drink wine, or for rulers to crave strong drink,'
EXEC add_BibleVerse @BibleId, 120031005, N'lest they drink and forget what is decreed, and remove from all the poor their legal rights.'
EXEC add_BibleVerse @BibleId, 120031006, N'Give strong drink to the one who is perishing, and wine to those who are bitterly distressed;'
EXEC add_BibleVerse @BibleId, 120031007, N'let them drink and forget their poverty, and remember their misery no more.'
EXEC add_BibleVerse @BibleId, 120031008, N'Open your mouth on behalf of those unable to speak, for the legal rights of all the dying.'
EXEC add_BibleVerse @BibleId, 120031009, N'Open your mouth, judge in righteousness, and plead the cause of the poor and needy.'
EXEC add_BibleVerse @BibleId, 120031010, N'Who can find a wife of noble character? For her value is far more than rubies.'
EXEC add_BibleVerse @BibleId, 120031011, N'The heart of her husband has confidence in her, and he has no lack of gain.'
EXEC add_BibleVerse @BibleId, 120031012, N'She brings him good and not evil all the days of her life.'
EXEC add_BibleVerse @BibleId, 120031013, N'She obtains wool and flax, and she is pleased to work with her hands.'
EXEC add_BibleVerse @BibleId, 120031014, N'She is like the merchant ships; she brings her food from afar.'
EXEC add_BibleVerse @BibleId, 120031015, N'She also gets up while it is still night, and provides food for her household and a portion to her female servants.'
EXEC add_BibleVerse @BibleId, 120031016, N'She considers a field and buys it; from her own income she plants a vineyard.'
EXEC add_BibleVerse @BibleId, 120031017, N'She begins her work vigorously, and she strengthens her arms.'
EXEC add_BibleVerse @BibleId, 120031018, N'She knows that her merchandise is good, and her lamp does not go out in the night.'
EXEC add_BibleVerse @BibleId, 120031019, N'Her hands take hold of the distaff, and her hands grasp the spindle.'
EXEC add_BibleVerse @BibleId, 120031020, N'She extends her hand to the poor, and reaches out her hand to the needy.'
EXEC add_BibleVerse @BibleId, 120031021, N'She is not afraid of the snow for her household, for all of her household are clothed with scarlet.'
EXEC add_BibleVerse @BibleId, 120031022, N'She makes for herself coverlets; her clothing is fine linen and purple.'
EXEC add_BibleVerse @BibleId, 120031023, N'Her husband is well-known in the city gate when he sits with the elders of the land.'
EXEC add_BibleVerse @BibleId, 120031024, N'She makes linen garments and sells them, and supplies the merchants with sashes.'
EXEC add_BibleVerse @BibleId, 120031025, N'She is clothed with strength and honor, and she can laugh at the time to come.'
EXEC add_BibleVerse @BibleId, 120031026, N'She opens her mouth with wisdom, and loving instruction is on her tongue.'
EXEC add_BibleVerse @BibleId, 120031027, N'She watches over the ways of her household, and does not eat the bread of idleness.'
EXEC add_BibleVerse @BibleId, 120031028, N'Her children rise up and call her blessed, her husband also praises her:'
EXEC add_BibleVerse @BibleId, 120031029, N'“Many daughters have done valiantly, but you surpass them all!”'
EXEC add_BibleVerse @BibleId, 120031030, N'Charm is deceitful and beauty is fleeting, but a woman who fears the Lord will be praised.'
EXEC add_BibleVerse @BibleId, 120031031, N'Give her credit for what she has accomplished, and let her works praise her in the city gates.'
EXEC add_BibleVerse @BibleId, 121001001, N'The words of the Teacher, the son of David, king in Jerusalem:'
EXEC add_BibleVerse @BibleId, 121001002, N'“Futile! Futile!” laments the Teacher, “Absolutely futile! Everything is futile!”'
EXEC add_BibleVerse @BibleId, 121001003, N'What benefit do people get from all the effort which they expend on earth?'
EXEC add_BibleVerse @BibleId, 121001004, N'A generation comes and a generation goes, but the earth remains the same through the ages.'
EXEC add_BibleVerse @BibleId, 121001005, N'The sun rises and the sun sets; it hurries away to a place from which it rises again.'
EXEC add_BibleVerse @BibleId, 121001006, N'The wind goes to the south and circles around to the north; round and round the wind goes and on its rounds it returns.'
EXEC add_BibleVerse @BibleId, 121001007, N'All the streams flow into the sea, but the sea is not full, and to the place where the streams flow, there they will flow again.'
EXEC add_BibleVerse @BibleId, 121001008, N'All this monotony is tiresome; no one can bear to describe it: The eye is never satisfied with seeing, nor is the ear ever content with hearing.'
EXEC add_BibleVerse @BibleId, 121001009, N'What exists now is what will be, and what has been done is what will be done; there is nothing truly new on earth.'
EXEC add_BibleVerse @BibleId, 121001010, N'Is there anything about which someone can say, “Look at this! It is new!”? It was already done long ago, before our time.'
EXEC add_BibleVerse @BibleId, 121001011, N'No one remembers the former events, nor will anyone remember the events that are yet to happen; they will not be remembered by the future generations.'
EXEC add_BibleVerse @BibleId, 121001012, N'I, the Teacher, have been king over Israel in Jerusalem.'
EXEC add_BibleVerse @BibleId, 121001013, N'I decided to carefully and thoroughly examine all that has been accomplished on earth. I concluded: God has given people a burdensome task that keeps them occupied.'
EXEC add_BibleVerse @BibleId, 121001014, N'I reflected on everything that is accomplished by man on earth, and I concluded: Everything he has accomplished is futile – like chasing the wind!'
EXEC add_BibleVerse @BibleId, 121001015, N'What is bent cannot be straightened, and what is missing cannot be supplied.'
EXEC add_BibleVerse @BibleId, 121001016, N'I thought to myself, “I have become much wiser than any of my predecessors who ruled over Jerusalem; I have acquired much wisdom and knowledge.”'
EXEC add_BibleVerse @BibleId, 121001017, N'So I decided to discern the benefit of wisdom and knowledge over foolish behavior and ideas; however, I concluded that even this endeavor is like trying to chase the wind!'
EXEC add_BibleVerse @BibleId, 121001018, N'For with great wisdom comes great frustration; whoever increases his knowledge merely increases his heartache.'
EXEC add_BibleVerse @BibleId, 121002001, N'“Come now, I will try self-indulgent pleasure to see if it is worthwhile.” But I found that it also is futile.'
EXEC add_BibleVerse @BibleId, 121002002, N'I said of partying, “It is folly,” and of self-indulgent pleasure, “It accomplishes nothing!”'
EXEC add_BibleVerse @BibleId, 121002003, N'I thought deeply about the effects of indulging myself with wine (all the while my mind was guiding me with wisdom) and the effects of behaving foolishly, so that I might discover what is profitable for people to do on earth during the few days of their lives.'
EXEC add_BibleVerse @BibleId, 121002004, N'I increased my possessions: I built houses for myself; I planted vineyards for myself.'
EXEC add_BibleVerse @BibleId, 121002005, N'I designed royal gardens and parks for myself, and I planted all kinds of fruit trees in them.'
EXEC add_BibleVerse @BibleId, 121002006, N'I constructed pools of water for myself, to irrigate my grove of flourishing trees.'
EXEC add_BibleVerse @BibleId, 121002007, N'I purchased male and female slaves, and I owned slaves who were born in my house; I also possessed more livestock – both herds and flocks – than any of my predecessors in Jerusalem.'
EXEC add_BibleVerse @BibleId, 121002008, N'I also amassed silver and gold for myself, as well as valuable treasures taken from kingdoms and provinces. I acquired male singers and female singers for myself, and what gives a man sensual delight – a harem of beautiful concubines!'
EXEC add_BibleVerse @BibleId, 121002009, N'So I was far wealthier than all my predecessors in Jerusalem, yet I maintained my objectivity:'
EXEC add_BibleVerse @BibleId, 121002010, N'I did not restrain myself from getting whatever I wanted; I did not deny myself anything that would bring me pleasure. So all my accomplishments gave me joy; this was my reward for all my effort.'
EXEC add_BibleVerse @BibleId, 121002011, N'Yet when I reflected on everything I had accomplished and on all the effort that I had expended to accomplish it, I concluded: “All these achievements and possessions are ultimately profitless – like chasing the wind! There is nothing gained from them on earth.”'
EXEC add_BibleVerse @BibleId, 121002012, N'Next, I decided to consider wisdom, as well as foolish behavior and ideas. For what more can the king’s successor do than what the king has already done?'
EXEC add_BibleVerse @BibleId, 121002013, N'I realized that wisdom is preferable to folly, just as light is preferable to darkness:'
EXEC add_BibleVerse @BibleId, 121002014, N'The wise man can see where he is going, but the fool walks in darkness. Yet I also realized that the same fate happens to them both.'
EXEC add_BibleVerse @BibleId, 121002015, N'So I thought to myself, “The fate of the fool will happen even to me! Then what did I gain by becoming so excessively wise?” So I lamented to myself, “The benefits of wisdom are ultimately meaningless!”'
EXEC add_BibleVerse @BibleId, 121002016, N'For the wise man, like the fool, will not be remembered for very long, because in the days to come, both will already have been forgotten. Alas, the wise man dies – just like the fool!'
EXEC add_BibleVerse @BibleId, 121002017, N'So I loathed life because what happens on earth seems awful to me; for all the benefits of wisdom are futile – like chasing the wind.'
EXEC add_BibleVerse @BibleId, 121002018, N'So I loathed all the fruit of my effort, for which I worked so hard on earth, because I must leave it behind in the hands of my successor.'
EXEC add_BibleVerse @BibleId, 121002019, N'Who knows if he will be a wise man or a fool? Yet he will be master over all the fruit of my labor for which I worked so wisely on earth! This also is futile!'
EXEC add_BibleVerse @BibleId, 121002020, N'So I began to despair about all the fruit of my labor for which I worked so hard on earth.'
EXEC add_BibleVerse @BibleId, 121002021, N'For a man may do his work with wisdom, knowledge, and skill; however, he must hand over the fruit of his labor as an inheritance to someone else who did not work for it. This also is futile, and an awful injustice!'
EXEC add_BibleVerse @BibleId, 121002022, N'What does a man acquire from all his labor and from the anxiety that accompanies his toil on earth?'
EXEC add_BibleVerse @BibleId, 121002023, N'For all day long his work produces pain and frustration, and even at night his mind cannot relax! This also is futile!'
EXEC add_BibleVerse @BibleId, 121002024, N'There is nothing better for people than to eat and drink, and to find enjoyment in their work. I also perceived that this ability to find enjoyment comes from God.'
EXEC add_BibleVerse @BibleId, 121002025, N'For no one can eat and drink or experience joy apart from him.'
EXEC add_BibleVerse @BibleId, 121002026, N'For to the one who pleases him, God gives wisdom, knowledge, and joy, but to the sinner, he gives the task of amassing wealth – only to give it to the one who pleases God. This task of the wicked is futile – like chasing the wind!'
EXEC add_BibleVerse @BibleId, 121003001, N'For everything there is an appointed time, and an appropriate time for every activity on earth:'
EXEC add_BibleVerse @BibleId, 121003002, N'A time to be born, and a time to die; a time to plant, and a time to uproot what was planted;'
EXEC add_BibleVerse @BibleId, 121003003, N'A time to kill, and a time to heal; a time to break down, and a time to build up;'
EXEC add_BibleVerse @BibleId, 121003004, N'A time to weep, and a time to laugh; a time to mourn, and a time to dance.'
EXEC add_BibleVerse @BibleId, 121003005, N'A time to throw away stones, and a time to gather stones; a time to embrace, and a time to refrain from embracing;'
EXEC add_BibleVerse @BibleId, 121003006, N'A time to search, and a time to give something up as lost; a time to keep, and a time to throw away;'
EXEC add_BibleVerse @BibleId, 121003007, N'A time to rip, and a time to sew; a time to keep silent, and a time to speak.'
EXEC add_BibleVerse @BibleId, 121003008, N'A time to love, and a time to hate; a time for war, and a time for peace.'
EXEC add_BibleVerse @BibleId, 121003009, N'What benefit can a worker gain from his toil?'
EXEC add_BibleVerse @BibleId, 121003010, N'I have observed the burden that God has given to people to keep them occupied.'
EXEC add_BibleVerse @BibleId, 121003011, N'God has made everything fit beautifully in its appropriate time, but he has also placed ignorance in the human heart so that people cannot discover what God has ordained, from the beginning to the end of their lives.'
EXEC add_BibleVerse @BibleId, 121003012, N'I have concluded that there is nothing better for people than to be happy and to enjoy themselves as long as they live,'
EXEC add_BibleVerse @BibleId, 121003013, N'and also that everyone should eat and drink, and find enjoyment in all his toil, for these things are a gift from God.'
EXEC add_BibleVerse @BibleId, 121003014, N'I also know that whatever God does will endure forever; nothing can be added to it, and nothing taken away from it. God has made it this way, so that men will fear him.'
EXEC add_BibleVerse @BibleId, 121003015, N'Whatever exists now has already been, and whatever will be has already been; for God will seek to do again what has occurred in the past.'
EXEC add_BibleVerse @BibleId, 121003016, N'I saw something else on earth: In the place of justice, there was wickedness, and in the place of fairness, there was wickedness.'
EXEC add_BibleVerse @BibleId, 121003017, N'I thought to myself, “God will judge both the righteous and the wicked; for there is an appropriate time for every activity, and there is a time of judgment for every deed.'
EXEC add_BibleVerse @BibleId, 121003018, N'I also thought to myself, “It is for the sake of people, so God can clearly show them that they are like animals.'
EXEC add_BibleVerse @BibleId, 121003019, N'For the fate of humans and the fate of animals are the same: As one dies, so dies the other; both have the same breath. There is no advantage for humans over animals, for both are fleeting.'
EXEC add_BibleVerse @BibleId, 121003020, N'Both go to the same place, both come from the dust, and to dust both return.'
EXEC add_BibleVerse @BibleId, 121003021, N'Who really knows if the human spirit ascends upward, and the animal’s spirit descends into the earth?'
EXEC add_BibleVerse @BibleId, 121003022, N'So I perceived there is nothing better than for people to enjoy their work, because that is their reward; for who can show them what the future holds?'
EXEC add_BibleVerse @BibleId, 121004001, N'So I again considered all the oppression that continually occurs on earth. This is what I saw: The oppressed were in tears, but no one was comforting them; no one delivers them from the power of their oppressors.'
EXEC add_BibleVerse @BibleId, 121004002, N'So I considered those who are dead and gone more fortunate than those who are still alive.'
EXEC add_BibleVerse @BibleId, 121004003, N'But better than both is the one who has not been born and has not seen the evil things that are done on earth.'
EXEC add_BibleVerse @BibleId, 121004004, N'Then I considered all the skillful work that is done: Surely it is nothing more than competition between one person and another. This also is profitless – like chasing the wind.'
EXEC add_BibleVerse @BibleId, 121004005, N'The fool folds his hands and does no work, so he has nothing to eat but his own flesh.'
EXEC add_BibleVerse @BibleId, 121004006, N'Better is one handful with some rest than two hands full of toil and chasing the wind.'
EXEC add_BibleVerse @BibleId, 121004007, N'So I again considered another futile thing on earth:'
EXEC add_BibleVerse @BibleId, 121004008, N'A man who is all alone with no companion, he has no children nor siblings; yet there is no end to all his toil, and he is never satisfied with riches. He laments, “For whom am I toiling and depriving myself of pleasure?” This also is futile and a burdensome task!'
EXEC add_BibleVerse @BibleId, 121004009, N'Two people are better than one, because they can reap more benefit from their labor.'
EXEC add_BibleVerse @BibleId, 121004010, N'For if they fall, one will help his companion up, but pity the person who falls down and has no one to help him up.'
EXEC add_BibleVerse @BibleId, 121004011, N'Furthermore, if two lie down together, they can keep each other warm, but how can one person keep warm by himself?'
EXEC add_BibleVerse @BibleId, 121004012, N'Although an assailant may overpower one person, two can withstand him. Moreover, a three-stranded cord is not quickly broken.'
EXEC add_BibleVerse @BibleId, 121004013, N'A poor but wise youth is better than an old and foolish king who no longer knows how to receive advice.'
EXEC add_BibleVerse @BibleId, 121004014, N'For he came out of prison to become king, even though he had been born poor in what would become his kingdom.'
EXEC add_BibleVerse @BibleId, 121004015, N'I considered all the living who walk on earth, as well as the successor who would arise in his place.'
EXEC add_BibleVerse @BibleId, 121004016, N'There is no end to all the people nor to the past generations, yet future generations will not rejoice in him. This also is profitless and like chasing the wind.'
EXEC add_BibleVerse @BibleId, 121005001, N'Be careful what you do when you go to the temple of God; draw near to listen rather than to offer a sacrifice like fools, for they do not realize that they are doing wrong.'
EXEC add_BibleVerse @BibleId, 121005002, N'Do not be rash with your mouth or hasty in your heart to bring up a matter before God, for God is in heaven and you are on earth! Therefore, let your words be few.'
EXEC add_BibleVerse @BibleId, 121005003, N'Just as dreams come when there are many cares, so the rash vow of a fool occurs when there are many words.'
EXEC add_BibleVerse @BibleId, 121005004, N'When you make a vow to God, do not delay in paying it. For God takes no pleasure in fools: Pay what you vow!'
EXEC add_BibleVerse @BibleId, 121005005, N'It is better for you not to vow than to vow and not pay it.'
EXEC add_BibleVerse @BibleId, 121005006, N'Do not let your mouth cause you to sin, and do not tell the priest, “It was a mistake!” Why make God angry at you so that he would destroy the work of your hands?”'
EXEC add_BibleVerse @BibleId, 121005007, N'Just as there is futility in many dreams, so also in many words. Therefore, fear God!'
EXEC add_BibleVerse @BibleId, 121005008, N'If you see the extortion of the poor, or the perversion of justice and fairness in the government, do not be astonished by the matter. For the high official is watched by a higher official, and there are higher ones over them!'
EXEC add_BibleVerse @BibleId, 121005009, N'The produce of the land is seized by all of them, even the king is served by the fields.'
EXEC add_BibleVerse @BibleId, 121005010, N'The one who loves money will never be satisfied with money, he who loves wealth will never be satisfied with his income. This also is futile.'
EXEC add_BibleVerse @BibleId, 121005011, N'When someone’s prosperity increases, those who consume it also increase; so what does its owner gain, except that he gets to see it with his eyes?'
EXEC add_BibleVerse @BibleId, 121005012, N'The sleep of the laborer is pleasant – whether he eats little or much – but the wealth of the rich will not allow him to sleep.'
EXEC add_BibleVerse @BibleId, 121005013, N'Here is a misfortune on earth that I have seen: Wealth hoarded by its owner to his own misery.'
EXEC add_BibleVerse @BibleId, 121005014, N'Then that wealth was lost through bad luck; although he fathered a son, he has nothing left to give him.'
EXEC add_BibleVerse @BibleId, 121005015, N'Just as he came forth from his mother''s womb, naked will he return as he came, and he will take nothing in his hand that he may carry away from his toil.'
EXEC add_BibleVerse @BibleId, 121005016, N'This is another misfortune: Just as he came, so will he go. What did he gain from toiling for the wind?'
EXEC add_BibleVerse @BibleId, 121005017, N'Surely, he ate in darkness every day of his life, and he suffered greatly with sickness and anger.'
EXEC add_BibleVerse @BibleId, 121005018, N'I have seen personally what is the only beneficial and appropriate course of action for people: to eat and drink, and find enjoyment in all their hard work on earth during the few days of their life which God has given them, for this is their reward.'
EXEC add_BibleVerse @BibleId, 121005019, N'To every man whom God has given wealth, and possessions, he has also given him the ability to eat from them, to receive his reward and to find enjoyment in his toil; these things are the gift of God.'
EXEC add_BibleVerse @BibleId, 121005020, N'For he does not think much about the fleeting days of his life because God keeps him preoccupied with the joy he derives from his activity.'
EXEC add_BibleVerse @BibleId, 121006001, N'Here is another misfortune that I have seen on earth, and it weighs heavily on people:'
EXEC add_BibleVerse @BibleId, 121006002, N'God gives a man riches, property, and wealth so that he lacks nothing that his heart desires, yet God does not enable him to enjoy the fruit of his labor – instead, someone else enjoys it! This is fruitless and a grave misfortune.'
EXEC add_BibleVerse @BibleId, 121006003, N'Even if a man fathers a hundred children and lives many years – even if he lives a long, long time, but cannot enjoy his prosperity – even if he were to live forever – I would say, “A stillborn child is better off than he is!”'
EXEC add_BibleVerse @BibleId, 121006004, N'Though the stillborn child came into the world for no reason and departed into darkness, though its name is shrouded in darkness,'
EXEC add_BibleVerse @BibleId, 121006005, N'though it never saw the light of day nor knew anything, yet it has more rest than that man –'
EXEC add_BibleVerse @BibleId, 121006006, N'if he should live a thousand years twice, yet does not enjoy his prosperity. For both of them die!'
EXEC add_BibleVerse @BibleId, 121006007, N'All of man’s labor is for nothing more than to fill his stomach – yet his appetite is never satisfied!'
EXEC add_BibleVerse @BibleId, 121006008, N'So what advantage does a wise man have over a fool? And what advantage does a pauper gain by knowing how to survive?'
EXEC add_BibleVerse @BibleId, 121006009, N'It is better to be content with what the eyes can see than for one’s heart always to crave more. This continual longing is futile – like chasing the wind.'
EXEC add_BibleVerse @BibleId, 121006010, N'Whatever has happened was foreordained, and what happens to a person was also foreknown. It is useless for him to argue with God about his fate because God is more powerful than he is.'
EXEC add_BibleVerse @BibleId, 121006011, N'The more one argues with words, the less he accomplishes. How does that benefit him?'
EXEC add_BibleVerse @BibleId, 121006012, N'For no one knows what is best for a person during his life – during the few days of his fleeting life – for they pass away like a shadow. Nor can anyone tell him what the future will hold for him on earth.'
EXEC add_BibleVerse @BibleId, 121007001, N'A good reputation is better than precious perfume; likewise, the day of one’s death is better than the day of one’s birth.'
EXEC add_BibleVerse @BibleId, 121007002, N'It is better to go to a funeral than a feast. For death is the destiny of every person, and the living should take this to heart.'
EXEC add_BibleVerse @BibleId, 121007003, N'Sorrow is better than laughter, because sober reflection is good for the heart.'
EXEC add_BibleVerse @BibleId, 121007004, N'The heart of the wise is in the house of mourning, but the heart of fools is in the house of merrymaking.'
EXEC add_BibleVerse @BibleId, 121007005, N'It is better for a person to receive a rebuke from those who are wise than to listen to the song of fools.'
EXEC add_BibleVerse @BibleId, 121007006, N'For like the crackling of quick-burning thorns under a cooking pot, so is the laughter of the fool. This kind of folly also is useless.'
EXEC add_BibleVerse @BibleId, 121007007, N'Surely oppression can turn a wise person into a fool; likewise, a bribe corrupts the heart.'
EXEC add_BibleVerse @BibleId, 121007008, N'The end of a matter is better than its beginning; likewise, patience is better than pride.'
EXEC add_BibleVerse @BibleId, 121007009, N'Do not let yourself be quickly provoked, for anger resides in the lap of fools.'
EXEC add_BibleVerse @BibleId, 121007010, N'Do not say, “Why were the old days better than these days?” for it is not wise to ask that.'
EXEC add_BibleVerse @BibleId, 121007011, N'Wisdom, like an inheritance, is a good thing; it benefits those who see the light of day.'
EXEC add_BibleVerse @BibleId, 121007012, N'For wisdom provides protection, just as money provides protection. But the advantage of knowledge is this: Wisdom preserves the life of its owner.'
EXEC add_BibleVerse @BibleId, 121007013, N'Consider the work of God: For who can make straight what he has bent?'
EXEC add_BibleVerse @BibleId, 121007014, N'In times of prosperity be joyful, but in times of adversity consider this: God has made one as well as the other, so that no one can discover what the future holds.'
EXEC add_BibleVerse @BibleId, 121007015, N'During the days of my fleeting life I have seen both of these things: Sometimes a righteous person dies prematurely in spite of his righteousness, and sometimes a wicked person lives long in spite of his evil deeds.'
EXEC add_BibleVerse @BibleId, 121007016, N'So do not be excessively righteous or excessively wise; otherwise you might be disappointed.'
EXEC add_BibleVerse @BibleId, 121007017, N'Do not be excessively wicked and do not be a fool; otherwise you might die before your time.'
EXEC add_BibleVerse @BibleId, 121007018, N'It is best to take hold of one warning without letting go of the other warning; for the one who fears God will follow both warnings.'
EXEC add_BibleVerse @BibleId, 121007019, N'Wisdom gives a wise person more protection than ten rulers in a city.'
EXEC add_BibleVerse @BibleId, 121007020, N'For there is not one truly righteous person on the earth who continually does good and never sins.'
EXEC add_BibleVerse @BibleId, 121007021, N'Also, do not pay attention to everything that people say; otherwise, you might even hear your servant cursing you.'
EXEC add_BibleVerse @BibleId, 121007022, N'For you know in your own heart that you also have cursed others many times.'
EXEC add_BibleVerse @BibleId, 121007023, N'I have examined all this by wisdom; I said, “I am determined to comprehend this” – but it was beyond my grasp.'
EXEC add_BibleVerse @BibleId, 121007024, N'Whatever has happened is beyond human understanding; it is far deeper than anyone can fathom.'
EXEC add_BibleVerse @BibleId, 121007025, N'I tried to understand, examine, and comprehend the role of wisdom in the scheme of things, and to understand the stupidity of wickedness and the insanity of folly.'
EXEC add_BibleVerse @BibleId, 121007026, N'I discovered this: More bitter than death is the kind of woman who is like a hunter’s snare; her heart is like a hunter’s net and her hands are like prison chains. The man who pleases God escapes her, but the sinner is captured by her.'
EXEC add_BibleVerse @BibleId, 121007027, N'The Teacher says: I discovered this while trying to discover the scheme of things, item by item.'
EXEC add_BibleVerse @BibleId, 121007028, N'What I have continually sought, I have not found; I have found only one upright man among a thousand, but I have not found one upright woman among all of them.'
EXEC add_BibleVerse @BibleId, 121007029, N'This alone have I discovered: God made humankind upright, but they have sought many evil schemes.'
EXEC add_BibleVerse @BibleId, 121008001, N'Who is a wise person? Who knows the solution to a problem? A person’s wisdom brightens his appearance, and softens his harsh countenance.'
EXEC add_BibleVerse @BibleId, 121008002, N'Obey the king’s command, because you took an oath before God to be loyal to him.'
EXEC add_BibleVerse @BibleId, 121008003, N'Do not rush out of the king’s presence in haste – do not delay when the matter is unpleasant, for he can do whatever he pleases.'
EXEC add_BibleVerse @BibleId, 121008004, N'Surely the king’s authority is absolute; no one can say to him, “What are you doing?”'
EXEC add_BibleVerse @BibleId, 121008005, N'Whoever obeys his command will not experience harm, and a wise person knows the proper time and procedure.'
EXEC add_BibleVerse @BibleId, 121008006, N'For there is a proper time and procedure for every matter, for the oppression of the king is severe upon his victim.'
EXEC add_BibleVerse @BibleId, 121008007, N'Surely no one knows the future, and no one can tell another person what will happen.'
EXEC add_BibleVerse @BibleId, 121008008, N'Just as no one has power over the wind to restrain it, so no one has power over the day of his death. Just as no one can be discharged during the battle, so wickedness cannot rescue the wicked.'
EXEC add_BibleVerse @BibleId, 121008009, N'While applying my mind to everything that happens in this world, I have seen all this: Sometimes one person dominates other people to their harm.'
EXEC add_BibleVerse @BibleId, 121008010, N'Not only that, but I have seen the wicked approaching and entering the temple, and as they left the holy temple, they boasted in the city that they had done so. This also is an enigma.'
EXEC add_BibleVerse @BibleId, 121008011, N'When a sentence is not executed at once against a crime, the human heart is encouraged to do evil.'
EXEC add_BibleVerse @BibleId, 121008012, N'Even though a sinner might commit a hundred crimes and still live a long time, yet I know that it will go well with God-fearing people – for they stand in fear before him.'
EXEC add_BibleVerse @BibleId, 121008013, N'But it will not go well with the wicked, nor will they prolong their days like a shadow, because they do not stand in fear before God.'
EXEC add_BibleVerse @BibleId, 121008014, N'Here is another enigma that occurs on earth: Sometimes there are righteous people who get what the wicked deserve, and sometimes there are wicked people who get what the righteous deserve. I said, “This also is an enigma.”'
EXEC add_BibleVerse @BibleId, 121008015, N'So I recommend the enjoyment of life, for there is nothing better on earth for a person to do except to eat, drink, and enjoy life. So joy will accompany him in his toil during the days of his life which God gives him on earth.'
EXEC add_BibleVerse @BibleId, 121008016, N'When I tried to gain wisdom and to observe the activity on earth – even though it prevents anyone from sleeping day or night –'
EXEC add_BibleVerse @BibleId, 121008017, N'then I discerned all that God has done: No one really comprehends what happens on earth. Despite all human efforts to discover it, no one can ever grasp it. Even if a wise person claimed that he understood, he would not really comprehend it.'
EXEC add_BibleVerse @BibleId, 121009001, N'So I reflected on all this, attempting to clear it all up. I concluded that the righteous and the wise, as well as their works, are in the hand of God; whether a person will be loved or hated – no one knows what lies ahead.'
EXEC add_BibleVerse @BibleId, 121009002, N'Everyone shares the same fate – the righteous and the wicked, the good and the bad, the ceremonially clean and unclean, those who offer sacrifices and those who do not. What happens to the good person, also happens to the sinner; what happens to those who make vows, also happens to those who are afraid to make vows.'
EXEC add_BibleVerse @BibleId, 121009003, N'This is the unfortunate fact about everything that happens on earth: the same fate awaits everyone. In addition to this, the hearts of all people are full of evil, and there is folly in their hearts during their lives – then they die.'
EXEC add_BibleVerse @BibleId, 121009004, N'But whoever is among the living has hope; a live dog is better than a dead lion.'
EXEC add_BibleVerse @BibleId, 121009005, N'For the living know that they will die, but the dead do not know anything; they have no further reward – and even the memory of them disappears.'
EXEC add_BibleVerse @BibleId, 121009006, N'What they loved, as well as what they hated and envied, perished long ago, and they no longer have a part in anything that happens on earth.'
EXEC add_BibleVerse @BibleId, 121009007, N'Go, eat your food with joy, and drink your wine with a happy heart, because God has already approved your works.'
EXEC add_BibleVerse @BibleId, 121009008, N'Let your clothes always be white, and do not spare precious ointment on your head.'
EXEC add_BibleVerse @BibleId, 121009009, N'Enjoy life with your beloved wife during all the days of your fleeting life that God has given you on earth during all your fleeting days; for that is your reward in life and in your burdensome work on earth.'
EXEC add_BibleVerse @BibleId, 121009010, N'Whatever you find to do with your hands, do it with all your might, because there is neither work nor planning nor knowledge nor wisdom in the grave, the place where you will eventually go.'
EXEC add_BibleVerse @BibleId, 121009011, N'Again, I observed this on the earth: the race is not always won by the swiftest, the battle is not always won by the strongest; prosperity does not always belong to those who are the wisest, wealth does not always belong to those who are the most discerning, nor does success always come to those with the most knowledge – for time and chance may overcome them all.'
EXEC add_BibleVerse @BibleId, 121009012, N'Surely, no one knows his appointed time! Like fish that are caught in a deadly net, and like birds that are caught in a snare – just like them, all people are ensnared at an unfortunate time that falls upon them suddenly.'
EXEC add_BibleVerse @BibleId, 121009013, N'This is what I also observed about wisdom on earth, and it is a great burden to me:'
EXEC add_BibleVerse @BibleId, 121009014, N'There was once a small city with a few men in it, and a mighty king attacked it, besieging it and building strong siege works against it.'
EXEC add_BibleVerse @BibleId, 121009015, N'However, a poor but wise man lived in the city, and he could have delivered the city by his wisdom, but no one listened to that poor man.'
EXEC add_BibleVerse @BibleId, 121009016, N'So I concluded that wisdom is better than might, but a poor man’s wisdom is despised; no one ever listens to his advice.'
EXEC add_BibleVerse @BibleId, 121009017, N'The words of the wise are heard in quiet, more than the shouting of a ruler is heard among fools.'
EXEC add_BibleVerse @BibleId, 121009018, N'Wisdom is better than weapons of war, but one sinner can destroy much that is good.'
EXEC add_BibleVerse @BibleId, 121010001, N'One dead fly makes the perfumer’s ointment give off a rancid stench, so a little folly can outweigh much wisdom.'
EXEC add_BibleVerse @BibleId, 121010002, N'A wise person’s good sense protects him, but a fool’s lack of sense leaves him vulnerable.'
EXEC add_BibleVerse @BibleId, 121010003, N'Even when a fool walks along the road he lacks sense, and shows everyone what a fool he is.'
EXEC add_BibleVerse @BibleId, 121010004, N'If the anger of the ruler flares up against you, do not resign from your position, for a calm response can undo great offenses.'
EXEC add_BibleVerse @BibleId, 121010005, N'I have seen another misfortune on the earth: It is an error a ruler makes.'
EXEC add_BibleVerse @BibleId, 121010006, N'Fools are placed in many positions of authority, while wealthy men sit in lowly positions.'
EXEC add_BibleVerse @BibleId, 121010007, N'I have seen slaves on horseback and princes walking on foot like slaves.'
EXEC add_BibleVerse @BibleId, 121010008, N'One who digs a pit may fall into it, and one who breaks through a wall may be bitten by a snake.'
EXEC add_BibleVerse @BibleId, 121010009, N'One who quarries stones may be injured by them; one who splits logs may be endangered by them.'
EXEC add_BibleVerse @BibleId, 121010010, N'If an iron axhead is blunt and a workman does not sharpen its edge, he must exert a great deal of effort; so wisdom has the advantage of giving success.'
EXEC add_BibleVerse @BibleId, 121010011, N'If the snake should bite before it is charmed, the snake charmer is in trouble.'
EXEC add_BibleVerse @BibleId, 121010012, N'The words of a wise person win him favor, but the words of a fool are self-destructive.'
EXEC add_BibleVerse @BibleId, 121010013, N'At the beginning his words are foolish and at the end his talk is wicked madness,'
EXEC add_BibleVerse @BibleId, 121010014, N'yet a fool keeps on babbling. No one knows what will happen; who can tell him what will happen in the future?'
EXEC add_BibleVerse @BibleId, 121010015, N'The toil of a stupid fool wears him out, because he does not even know the way to the city.'
EXEC add_BibleVerse @BibleId, 121010016, N'Woe to you, O land, when your king is childish, and your princes feast in the morning!'
EXEC add_BibleVerse @BibleId, 121010017, N'Blessed are you, O land, when your king is the son of nobility, and your princes feast at the proper time – with self-control and not in drunkenness.'
EXEC add_BibleVerse @BibleId, 121010018, N'Because of laziness the roof caves in, and because of idle hands the house leaks.'
EXEC add_BibleVerse @BibleId, 121010019, N'Feasts are made for laughter, and wine makes life merry, but money is the answer for everything.'
EXEC add_BibleVerse @BibleId, 121010020, N'Do not curse a king even in your thoughts, and do not curse the rich while in your bedroom; for a bird might report what you are thinking, or some winged creature might repeat your words.'
EXEC add_BibleVerse @BibleId, 121011001, N'Send your grain overseas, for after many days you will get a return.'
EXEC add_BibleVerse @BibleId, 121011002, N'Divide your merchandise among seven or even eight investments, for you do not know what calamity may happen on earth.'
EXEC add_BibleVerse @BibleId, 121011003, N'If the clouds are full of rain, they will empty themselves on the earth, and whether a tree falls to the south or to the north, the tree will lie wherever it falls.'
EXEC add_BibleVerse @BibleId, 121011004, N'He who watches the wind will not sow, and he who observes the clouds will not reap.'
EXEC add_BibleVerse @BibleId, 121011005, N'Just as you do not know the path of the wind, or how the bones form in the womb of a pregnant woman, so you do not know the work of God who makes everything.'
EXEC add_BibleVerse @BibleId, 121011006, N'Sow your seed in the morning, and do not stop working until the evening; for you do not know which activity will succeed – whether this one or that one, or whether both will prosper equally.'
EXEC add_BibleVerse @BibleId, 121011007, N'Light is sweet, and it is pleasant for a person to see the sun.'
EXEC add_BibleVerse @BibleId, 121011008, N'So, if a man lives many years, let him rejoice in them all, but let him remember that the days of darkness will be many – all that is about to come is obscure.'
EXEC add_BibleVerse @BibleId, 121011009, N'Rejoice, young man, while you are young, and let your heart cheer you in the days of your youth. Follow the impulses of your heart and the desires of your eyes, but know that God will judge your motives and actions.'
EXEC add_BibleVerse @BibleId, 121011010, N'Banish emotional stress from your mind. and put away pain from your body; for youth and the prime of life are fleeting.'
EXEC add_BibleVerse @BibleId, 121012001, N'So remember your Creator in the days of your youth – before the difficult days come, and the years draw near when you will say, “I have no pleasure in them”;'
EXEC add_BibleVerse @BibleId, 121012002, N'before the sun and the light of the moon and the stars grow dark, and the clouds disappear after the rain;'
EXEC add_BibleVerse @BibleId, 121012003, N'when those who keep watch over the house begin to tremble, and the virile men begin to stoop over, and the grinders begin to cease because they grow few, and those who look through the windows grow dim,'
EXEC add_BibleVerse @BibleId, 121012004, N'and the doors along the street are shut; when the sound of the grinding mill grows low, and one is awakened by the sound of a bird, and all their songs grow faint,'
EXEC add_BibleVerse @BibleId, 121012005, N'and they are afraid of heights and the dangers in the street; the almond blossoms grow white, and the grasshopper drags itself along, and the caper berry shrivels up – because man goes to his eternal home, and the mourners go about in the streets –'
EXEC add_BibleVerse @BibleId, 121012006, N'before the silver cord is removed, or the golden bowl is broken, or the pitcher is shattered at the well, or the water wheel is broken at the cistern –'
EXEC add_BibleVerse @BibleId, 121012007, N'and the dust returns to the earth as it was, and the life’s breath returns to God who gave it.'
EXEC add_BibleVerse @BibleId, 121012008, N'“Absolutely futile!” laments the Teacher, “All of these things are futile!”'
EXEC add_BibleVerse @BibleId, 121012009, N'Not only was the Teacher wise, but he also taught knowledge to the people; he carefully evaluated and arranged many proverbs.'
EXEC add_BibleVerse @BibleId, 121012010, N'The Teacher sought to find delightful words, and to write accurately truthful sayings.'
EXEC add_BibleVerse @BibleId, 121012011, N'The words of the sages are like prods, and the collected sayings are like firmly fixed nails; they are given by one shepherd.'
EXEC add_BibleVerse @BibleId, 121012012, N'Be warned, my son, of anything in addition to them. There is no end to the making of many books, and much study is exhausting to the body.'
EXEC add_BibleVerse @BibleId, 121012013, N'Having heard everything, I have reached this conclusion: Fear God and keep his commandments, because this is the whole duty of man.'
EXEC add_BibleVerse @BibleId, 121012014, N'For God will evaluate every deed, including every secret thing, whether good or evil.'
EXEC add_BibleVerse @BibleId, 122001001, N'Solomon’s Most Excellent Love Song.'
EXEC add_BibleVerse @BibleId, 122001002, N'Oh, how I wish you would kiss me passionately! For your lovemaking is more delightful than wine.'
EXEC add_BibleVerse @BibleId, 122001003, N'The fragrance of your colognes is delightful; your name is like the finest perfume. No wonder the young women adore you!'
EXEC add_BibleVerse @BibleId, 122001004, N'Draw me after you; let us hurry! May the king bring me into his bedroom chambers! We will rejoice and delight in you; we will praise your love more than wine. The Beloved to Her Lover: How rightly the young women adore you!'
EXEC add_BibleVerse @BibleId, 122001005, N'I am dark but lovely, O maidens of Jerusalem, dark like the tents of Qedar, lovely like the tent curtains of Salmah.'
EXEC add_BibleVerse @BibleId, 122001006, N'Do not stare at me because I am dark, for the sun has burned my skin. My brothers were angry with me; they made me the keeper of the vineyards. Alas, my own vineyard I could not keep!'
EXEC add_BibleVerse @BibleId, 122001007, N'Tell me, O you whom my heart loves, where do you pasture your sheep? Where do you rest your sheep during the midday heat? Tell me lest I wander around beside the flocks of your companions!'
EXEC add_BibleVerse @BibleId, 122001008, N'If you do not know, O most beautiful of women, simply follow the tracks of my flock, and pasture your little lambs beside the tents of the shepherds.'
EXEC add_BibleVerse @BibleId, 122001009, N'O my beloved, you are like a mare among Pharaoh’s stallions.'
EXEC add_BibleVerse @BibleId, 122001010, N'Your cheeks are beautiful with ornaments; your neck is lovely with strings of jewels.'
EXEC add_BibleVerse @BibleId, 122001011, N'We will make for you gold ornaments studded with silver.'
EXEC add_BibleVerse @BibleId, 122001012, N'While the king was at his banqueting table, my nard gave forth its fragrance.'
EXEC add_BibleVerse @BibleId, 122001013, N'My beloved is like a fragrant pouch of myrrh spending the night between my breasts.'
EXEC add_BibleVerse @BibleId, 122001014, N'My beloved is like a cluster of henna blossoms in the vineyards of En-Gedi.'
EXEC add_BibleVerse @BibleId, 122001015, N'Oh, how beautiful you are, my beloved! Oh, how beautiful you are! Your eyes are like doves!'
EXEC add_BibleVerse @BibleId, 122001016, N'Oh, how handsome you are, my lover! Oh, how delightful you are! The lush foliage is our canopied bed;'
EXEC add_BibleVerse @BibleId, 122001017, N'the cedars are the beams of our bedroom chamber; the pines are the rafters of our bedroom.'
EXEC add_BibleVerse @BibleId, 122002001, N'I am a meadow flower from Sharon, a lily from the valleys.'
EXEC add_BibleVerse @BibleId, 122002002, N'Like a lily among the thorns, so is my darling among the maidens.'
EXEC add_BibleVerse @BibleId, 122002003, N'Like an apple tree among the trees of the forest, so is my beloved among the young men. I delight to sit in his shade, and his fruit is sweet to my taste.'
EXEC add_BibleVerse @BibleId, 122002004, N'He brought me into the banquet hall, and he looked at me lovingly.'
EXEC add_BibleVerse @BibleId, 122002005, N'Sustain me with raisin cakes, refresh me with apples, for I am faint with love. The Double Refrain: Embracing and Adjuration'
EXEC add_BibleVerse @BibleId, 122002006, N'His left hand caresses my head, and his right hand stimulates me.'
EXEC add_BibleVerse @BibleId, 122002007, N'I adjure you, O maidens of Jerusalem, by the gazelles and by the young does of the open fields: Do not awaken or arouse love until it pleases!'
EXEC add_BibleVerse @BibleId, 122002008, N'Listen! My lover is approaching! Look! Here he comes, leaping over the mountains, bounding over the hills!'
EXEC add_BibleVerse @BibleId, 122002009, N'My lover is like a gazelle or a young stag. Look! There he stands behind our wall, gazing through the window, peering through the lattice.'
EXEC add_BibleVerse @BibleId, 122002010, N'My lover spoke to me, saying: “Arise, my darling; My beautiful one, come away with me!'
EXEC add_BibleVerse @BibleId, 122002011, N'Look! The winter has passed, the winter rains are over and gone.'
EXEC add_BibleVerse @BibleId, 122002012, N'The pomegranates have appeared in the land, the time for pruning and singing has come; the voice of the turtledove is heard in our land.'
EXEC add_BibleVerse @BibleId, 122002013, N'The fig tree has budded, the vines have blossomed and give off their fragrance. Arise, come away my darling; my beautiful one, come away with me!”'
EXEC add_BibleVerse @BibleId, 122002014, N'O my dove, in the clefts of the rock, in the hiding places of the mountain crags, let me see your face, let me hear your voice; for your voice is sweet, and your face is lovely.'
EXEC add_BibleVerse @BibleId, 122002015, N'Catch the foxes for us, the little foxes, that ruin the vineyards – for our vineyard is in bloom.'
EXEC add_BibleVerse @BibleId, 122002016, N'My lover is mine and I am his; he grazes among the lilies.'
EXEC add_BibleVerse @BibleId, 122002017, N'Until the dawn arrives and the shadows flee, turn, my beloved – be like a gazelle or a young stag on the mountain gorges.'
EXEC add_BibleVerse @BibleId, 122003001, N'All night long on my bed I longed for my lover. I longed for him but he never appeared.'
EXEC add_BibleVerse @BibleId, 122003002, N'“I will arise and look all around throughout the town, and throughout the streets and squares; I will search for my beloved.” I searched for him but I did not find him.'
EXEC add_BibleVerse @BibleId, 122003003, N'The night watchmen found me – the ones who guard the city walls. “Have you seen my beloved?”'
EXEC add_BibleVerse @BibleId, 122003004, N'Scarcely had I passed them by when I found my beloved! I held onto him tightly and would not let him go until I brought him to my mother’s house, to the bedroom chamber of the one who conceived me.'
EXEC add_BibleVerse @BibleId, 122003005, N'I admonish you, O maidens of Jerusalem, by the gazelles and by the young does of the open fields: “Do not awake or arouse love until it pleases!”'
EXEC add_BibleVerse @BibleId, 122003006, N'Who is this coming up from the desert like a column of smoke, like a fragrant billow of myrrh and frankincense, every kind of fragrant powder of the traveling merchants?'
EXEC add_BibleVerse @BibleId, 122003007, N'Look! It is Solomon’s portable couch! It is surrounded by sixty warriors, some of Israel’s mightiest warriors.'
EXEC add_BibleVerse @BibleId, 122003008, N'All of them are skilled with a sword, well-trained in the art of warfare. Each has his sword at his side, to guard against the terrors of the night.'
EXEC add_BibleVerse @BibleId, 122003009, N'King Solomon made a sedan chair for himself of wood imported from Lebanon.'
EXEC add_BibleVerse @BibleId, 122003010, N'Its posts were made of silver; its back was made of gold. Its seat was upholstered with purple wool; its interior was inlaid with leather by the maidens of Jerusalem.'
EXEC add_BibleVerse @BibleId, 122003011, N'Come out, O maidens of Zion, and gaze upon King Solomon! He is wearing the crown with which his mother crowned him on his wedding day, on the most joyous day of his life!'
EXEC add_BibleVerse @BibleId, 122004001, N'Oh, you are beautiful, my darling! Oh, you are beautiful! Your eyes behind your veil are like doves. Your hair is like a flock of female goats descending from Mount Gilead.'
EXEC add_BibleVerse @BibleId, 122004002, N'Your teeth are like a flock of newly-shorn sheep coming up from the washing place; each of them has a twin, and not one of them is missing.'
EXEC add_BibleVerse @BibleId, 122004003, N'Your lips are like a scarlet thread; your mouth is lovely. Your forehead behind your veil is like a slice of pomegranate.'
EXEC add_BibleVerse @BibleId, 122004004, N'Your neck is like the tower of David built with courses of stones; one thousand shields are hung on it – all shields of valiant warriors.'
EXEC add_BibleVerse @BibleId, 122004005, N'Your two breasts are like two fawns, twins of the gazelle grazing among the lilies.'
EXEC add_BibleVerse @BibleId, 122004006, N'Until the dawn arrives and the shadows flee, I will go up to the mountain of myrrh, and to the hill of frankincense.'
EXEC add_BibleVerse @BibleId, 122004007, N'You are altogether beautiful, my darling! There is no blemish in you!'
EXEC add_BibleVerse @BibleId, 122004008, N'Come with me from Lebanon, my bride, come with me from Lebanon. Descend from the crest of Amana, from the top of Senir, the summit of Hermon, from the lions’ dens and the mountain haunts of the leopards.'
EXEC add_BibleVerse @BibleId, 122004009, N'You have stolen my heart, my sister, my bride! You have stolen my heart with one glance of your eyes, with one jewel of your necklace.'
EXEC add_BibleVerse @BibleId, 122004010, N'How delightful is your love, my sister, my bride! How much better is your love than wine; the fragrance of your perfume is better than any spice!'
EXEC add_BibleVerse @BibleId, 122004011, N'Your lips drip sweetness like the honeycomb, my bride, honey and milk are under your tongue. The fragrance of your garments is like the fragrance of Lebanon.'
EXEC add_BibleVerse @BibleId, 122004012, N'You are a locked garden, my sister, my bride; you are an enclosed spring, a sealed-up fountain.'
EXEC add_BibleVerse @BibleId, 122004013, N'Your shoots are a royal garden full of pomegranates with choice fruits: henna with nard,'
EXEC add_BibleVerse @BibleId, 122004014, N'nard and saffron; calamus and cinnamon with every kind of spice, myrrh and aloes with all the finest spices.'
EXEC add_BibleVerse @BibleId, 122004015, N'You are a garden spring, a well of fresh water flowing down from Lebanon.'
EXEC add_BibleVerse @BibleId, 122004016, N'Awake, O north wind; come, O south wind! Blow on my garden so that its fragrant spices may send out their sweet smell. May my beloved come into his garden and eat its delightful fruit!'
EXEC add_BibleVerse @BibleId, 122005001, N'I have entered my garden, O my sister, my bride; I have gathered my myrrh with my balsam spice. I have eaten my honeycomb and my honey; I have drunk my wine and my milk! Eat, friends, and drink! Drink freely, O lovers!'
EXEC add_BibleVerse @BibleId, 122005002, N'I was asleep, but my mind was dreaming. Listen! My lover is knocking at the door! “Open for me, my sister, my darling, my dove, my flawless one! My head is drenched with dew, my hair with the dampness of the night.”'
EXEC add_BibleVerse @BibleId, 122005003, N'“I have already taken off my robe – must I put it on again? I have already washed my feet – must I soil them again?”'
EXEC add_BibleVerse @BibleId, 122005004, N'My lover thrust his hand through the hole, and my feelings were stirred for him.'
EXEC add_BibleVerse @BibleId, 122005005, N'I arose to open for my beloved; my hands dripped with myrrh – my fingers flowed with myrrh on the handles of the lock.'
EXEC add_BibleVerse @BibleId, 122005006, N'I opened for my beloved, but my lover had already turned and gone away. I fell into despair when he departed. I looked for him but did not find him; I called him but he did not answer me.'
EXEC add_BibleVerse @BibleId, 122005007, N'The watchmen found me as they made their rounds in the city. They beat me, they bruised me; they took away my cloak, those watchmen on the walls!'
EXEC add_BibleVerse @BibleId, 122005008, N'O maidens of Jerusalem, I command you – If you find my beloved, what will you tell him? Tell him that I am lovesick!'
EXEC add_BibleVerse @BibleId, 122005009, N'Why is your beloved better than others, O most beautiful of women? Why is your beloved better than others, that you would command us in this manner?'
EXEC add_BibleVerse @BibleId, 122005010, N'My beloved is dazzling and ruddy; he stands out in comparison to all other men.'
EXEC add_BibleVerse @BibleId, 122005011, N'His head is like the most pure gold. His hair is curly – black like a raven.'
EXEC add_BibleVerse @BibleId, 122005012, N'His eyes are like doves by streams of water, washed in milk, mounted like jewels.'
EXEC add_BibleVerse @BibleId, 122005013, N'His cheeks are like garden beds full of balsam trees yielding perfume. His lips are like lilies dripping with drops of myrrh.'
EXEC add_BibleVerse @BibleId, 122005014, N'His arms are like rods of gold set with chrysolite. His abdomen is like polished ivory inlaid with sapphires.'
EXEC add_BibleVerse @BibleId, 122005015, N'His legs are like pillars of marble set on bases of pure gold. His appearance is like Lebanon, choice as its cedars.'
EXEC add_BibleVerse @BibleId, 122005016, N'His mouth is very sweet; he is totally desirable. This is my beloved! This is my companion, O maidens of Jerusalem!'
EXEC add_BibleVerse @BibleId, 122006001, N'Where has your beloved gone, O most beautiful among women? Where has your beloved turned? Tell us, that we may seek him with you.'
EXEC add_BibleVerse @BibleId, 122006002, N'My beloved has gone down to his garden, to the flowerbeds of balsam spices, to graze in the gardens, and to gather lilies.'
EXEC add_BibleVerse @BibleId, 122006003, N'I am my lover’s and my lover is mine; he grazes among the lilies.'
EXEC add_BibleVerse @BibleId, 122006004, N'My darling, you are as beautiful as Tirzah, as lovely as Jerusalem, as awe-inspiring as bannered armies!'
EXEC add_BibleVerse @BibleId, 122006005, N'Turn your eyes away from me – they overwhelm me! Your hair is like a flock of goats descending from Mount Gilead.'
EXEC add_BibleVerse @BibleId, 122006006, N'Your teeth are like a flock of sheep coming up from the washing; each has its twin; not one of them is missing.'
EXEC add_BibleVerse @BibleId, 122006007, N'Like a slice of pomegranate is your forehead behind your veil.'
EXEC add_BibleVerse @BibleId, 122006008, N'There may be sixty queens, and eighty concubines, and young women without number.'
EXEC add_BibleVerse @BibleId, 122006009, N'But she is unique! My dove, my perfect one! She is the special daughter of her mother, she is the favorite of the one who bore her. The maidens saw her and complimented her; the queens and concubines praised her:'
EXEC add_BibleVerse @BibleId, 122006010, N'“Who is this who appears like the dawn? Beautiful as the moon, bright as the sun, awe-inspiring as the stars in procession?”'
EXEC add_BibleVerse @BibleId, 122006011, N'I went down to the orchard of walnut trees, to look for the blossoms of the valley, to see if the vines had budded or if the pomegranates were in bloom.'
EXEC add_BibleVerse @BibleId, 122006012, N'I was beside myself with joy! There please give me your myrrh, O daughter of my princely people.'
EXEC add_BibleVerse @BibleId, 122006013, N'Turn , turn, O Perfect One! Turn, turn, that I may stare at you! Why do you gaze upon the Perfect One like the dance of the Mahanaim?'
EXEC add_BibleVerse @BibleId, 122007001, N'How beautiful are your sandaled feet, O nobleman’s daughter! The curves of your thighs are like jewels, the work of the hands of a master craftsman.'
EXEC add_BibleVerse @BibleId, 122007002, N'Your navel is a round mixing bowl – may it never lack mixed wine! Your belly is a mound of wheat, encircled by lilies.'
EXEC add_BibleVerse @BibleId, 122007003, N'Your two breasts are like two fawns, twins of a gazelle.'
EXEC add_BibleVerse @BibleId, 122007004, N'Your neck is like a tower made of ivory. Your eyes are the pools in Heshbon by the gate of Bath-Rabbim. Your nose is like the tower of Lebanon overlooking Damascus.'
EXEC add_BibleVerse @BibleId, 122007005, N'Your head crowns you like Mount Carmel. The locks of your hair are like royal tapestries – the king is held captive in its tresses!'
EXEC add_BibleVerse @BibleId, 122007006, N'How beautiful you are! How lovely, O love, with your delights!'
EXEC add_BibleVerse @BibleId, 122007007, N'Your stature is like a palm tree, and your breasts are like clusters of grapes.'
EXEC add_BibleVerse @BibleId, 122007008, N'I want to climb the palm tree, and take hold of its fruit stalks. May your breasts be like the clusters of grapes, and may the fragrance of your breath be like apricots!'
EXEC add_BibleVerse @BibleId, 122007009, N'May your mouth be like the best wine, flowing smoothly for my beloved, gliding gently over our lips as we sleep together.'
EXEC add_BibleVerse @BibleId, 122007010, N'I am my beloved’s, and he desires me!'
EXEC add_BibleVerse @BibleId, 122007011, N'Come, my beloved, let us go to the countryside; let us spend the night in the villages.'
EXEC add_BibleVerse @BibleId, 122007012, N'Let us rise early to go to the vineyards, to see if the vines have budded, to see if their blossoms have opened, if the pomegranates are in bloom – there I will give you my love.'
EXEC add_BibleVerse @BibleId, 122007013, N'The mandrakes send out their fragrance; over our door is every delicacy, both new and old, which I have stored up for you, my lover.'
EXEC add_BibleVerse @BibleId, 122008001, N'Oh, how I wish you were my little brother, nursing at my mother’s breasts; if I saw you outside, I could kiss you – surely no one would despise me!'
EXEC add_BibleVerse @BibleId, 122008002, N'I would lead you and bring you to my mother’s house, the one who taught me. I would give you spiced wine to drink, the nectar of my pomegranates.'
EXEC add_BibleVerse @BibleId, 122008003, N'His left hand caresses my head, and his right hand stimulates me.'
EXEC add_BibleVerse @BibleId, 122008004, N'I admonish you, O maidens of Jerusalem: “Do not arouse or awaken love until it pleases!”'
EXEC add_BibleVerse @BibleId, 122008005, N'Who is this coming up from the desert, leaning on her beloved? Under the apple tree I aroused you; there your mother conceived you, there she who bore you was in labor of childbirth.'
EXEC add_BibleVerse @BibleId, 122008006, N'Set me like a cylinder seal over your heart, like a signet on your arm. For love is as strong as death, passion is as unrelenting as Sheol. Its flames burst forth, it is a blazing flame.'
EXEC add_BibleVerse @BibleId, 122008007, N'Surging waters cannot quench love; floodwaters cannot overflow it. If someone were to offer all his possessions to buy love, the offer would be utterly despised.'
EXEC add_BibleVerse @BibleId, 122008008, N'We have a little sister, and as yet she has no breasts. What shall we do for our sister on the day when she is spoken for?'
EXEC add_BibleVerse @BibleId, 122008009, N'If she is a wall, we will build on her a battlement of silver; but if she is a door, we will barricade her with boards of cedar.'
EXEC add_BibleVerse @BibleId, 122008010, N'I was a wall, and my breasts were like fortress towers. Then I found favor in his eyes.'
EXEC add_BibleVerse @BibleId, 122008011, N'Solomon had a vineyard at Baal-Hamon; he leased out the vineyard to those who maintained it. Each was to bring a thousand shekels of silver for its fruit.'
EXEC add_BibleVerse @BibleId, 122008012, N'My vineyard, which belongs to me, is at my disposal alone. The thousand shekels belong to you, O Solomon, and two hundred shekels belong to those who maintain it for its fruit.'
EXEC add_BibleVerse @BibleId, 122008013, N'O you who stay in the gardens, my companions are listening attentively for your voice; let me be the one to hear it!'
EXEC add_BibleVerse @BibleId, 122008014, N'Make haste, my beloved! Be like a gazelle or a young stag on the mountains of spices.'
EXEC add_BibleVerse @BibleId, 123001001, N'Here is the message about Judah and Jerusalem that was revealed to Isaiah son of Amoz during the time when Uzziah, Jotham, Ahaz, and Hezekiah reigned over Judah.'
EXEC add_BibleVerse @BibleId, 123001002, N'Listen, O heavens, pay attention, O earth! For the Lord speaks: “I raised children, I brought them up, but they have rebelled against me!'
EXEC add_BibleVerse @BibleId, 123001003, N'An ox recognizes its owner, a donkey recognizes where its owner puts its food; but Israel does not recognize me, my people do not understand.”'
EXEC add_BibleVerse @BibleId, 123001004, N'The sinful nation is as good as dead, the people weighed down by evil deeds. They are offspring who do wrong, children who do wicked things. They have abandoned the Lord, and rejected the Holy One of Israel. They are alienated from him.'
EXEC add_BibleVerse @BibleId, 123001005, N'Why do you insist on being battered? Why do you continue to rebel? Your head has a massive wound, your whole body is weak.'
EXEC add_BibleVerse @BibleId, 123001006, N'From the soles of your feet to your head, there is no spot that is unharmed. There are only bruises, cuts, and open wounds. They have not been cleansed or bandaged, nor have they been treated with olive oil.'
EXEC add_BibleVerse @BibleId, 123001007, N'Your land is devastated, your cities burned with fire. Right before your eyes your crops are being destroyed by foreign invaders. They leave behind devastation and destruction.'
EXEC add_BibleVerse @BibleId, 123001008, N'Daughter Zion is left isolated, like a hut in a vineyard, or a shelter in a cucumber field; she is a besieged city.'
EXEC add_BibleVerse @BibleId, 123001009, N'If the Lord who commands armies had not left us a few survivors, we would have quickly become like Sodom, we would have become like Gomorrah.'
EXEC add_BibleVerse @BibleId, 123001010, N'Listen to the Lord’s word, you leaders of Sodom! Pay attention to our God’s rebuke, people of Gomorrah!'
EXEC add_BibleVerse @BibleId, 123001011, N'“Of what importance to me are your many sacrifices?” says the Lord. “I am stuffed with burnt sacrifices of rams and the fat from steers. The blood of bulls, lambs, and goats I do not want.'
EXEC add_BibleVerse @BibleId, 123001012, N'When you enter my presence, do you actually think I want this – animals trampling on my courtyards?'
EXEC add_BibleVerse @BibleId, 123001013, N'Do not bring any more meaningless offerings; I consider your incense detestable! You observe new moon festivals, Sabbaths, and convocations, but I cannot tolerate sin-stained celebrations!'
EXEC add_BibleVerse @BibleId, 123001014, N'I hate your new moon festivals and assemblies; they are a burden that I am tired of carrying.'
EXEC add_BibleVerse @BibleId, 123001015, N'When you spread out your hands in prayer, I look the other way; when you offer your many prayers, I do not listen, because your hands are covered with blood.'
EXEC add_BibleVerse @BibleId, 123001016, N'Wash! Cleanse yourselves! Remove your sinful deeds from my sight. Stop sinning!'
EXEC add_BibleVerse @BibleId, 123001017, N'Learn to do what is right! Promote justice! Give the oppressed reason to celebrate! Take up the cause of the orphan! Defend the rights of the widow!'
EXEC add_BibleVerse @BibleId, 123001018, N'Come, let’s consider your options,” says the Lord. “Though your sins have stained you like the color red, you can become white like snow; though they are as easy to see as the color scarlet, you can become white like wool.'
EXEC add_BibleVerse @BibleId, 123001019, N'If you have a willing attitude and obey, then you will again eat the good crops of the land.'
EXEC add_BibleVerse @BibleId, 123001020, N'But if you refuse and rebel, you will be devoured by the sword.” Know for certain that the Lord has spoken.'
EXEC add_BibleVerse @BibleId, 123001021, N'How tragic that the once-faithful city has become a prostitute! She was once a center of justice, fairness resided in her, but now only murderers.'
EXEC add_BibleVerse @BibleId, 123001022, N'Your silver has become scum, your beer is diluted with water.'
EXEC add_BibleVerse @BibleId, 123001023, N'Your officials are rebels, they associate with thieves. All of them love bribery, and look for payoffs. They do not take up the cause of the orphan, or defend the rights of the widow.'
EXEC add_BibleVerse @BibleId, 123001024, N'Therefore, the sovereign Lord who commands armies, the powerful ruler of Israel, says this: “Ah, I will seek vengeance against my adversaries, I will take revenge against my enemies.'
EXEC add_BibleVerse @BibleId, 123001025, N'I will attack you; I will purify your metal with flux. I will remove all your slag.'
EXEC add_BibleVerse @BibleId, 123001026, N'I will reestablish honest judges as in former times, wise advisers as in earlier days. Then you will be called, ‘The Just City, Faithful Town.’”'
EXEC add_BibleVerse @BibleId, 123001027, N'Zion will be freed by justice, and her returnees by righteousness.'
EXEC add_BibleVerse @BibleId, 123001028, N'All rebellious sinners will be shattered, those who abandon the Lord will perish.'
EXEC add_BibleVerse @BibleId, 123001029, N'Indeed, they will be ashamed of the sacred trees you find so desirable; you will be embarrassed because of the sacred orchards where you choose to worship.'
EXEC add_BibleVerse @BibleId, 123001030, N'For you will be like a tree whose leaves wither, like an orchard that is unwatered.'
EXEC add_BibleVerse @BibleId, 123001031, N'The powerful will be like a thread of yarn, their deeds like a spark; both will burn together, and no one will put out the fire.'
EXEC add_BibleVerse @BibleId, 123002001, N'Here is the message about Judah and Jerusalem that was revealed to Isaiah son of Amoz.'
EXEC add_BibleVerse @BibleId, 123002002, N'In the future the mountain of the Lord’s temple will endure as the most important of mountains, and will be the most prominent of hills. All the nations will stream to it,'
EXEC add_BibleVerse @BibleId, 123002003, N'many peoples will come and say, “Come, let us go up to the Lord’s mountain, to the temple of the God of Jacob, so he can teach us his requirements, and we can follow his standards.” For Zion will be the center for moral instruction; the Lord will issue edicts from Jerusalem.'
EXEC add_BibleVerse @BibleId, 123002004, N'He will judge disputes between nations; he will settle cases for many peoples. They will beat their swords into plowshares, and their spears into pruning hooks. Nations will not take up the sword against other nations, and they will no longer train for war.'
EXEC add_BibleVerse @BibleId, 123002005, N'O descendants of Jacob, come, let us walk in the Lord’s guiding light.'
EXEC add_BibleVerse @BibleId, 123002006, N'Indeed, O Lord, you have abandoned your people, the descendants of Jacob. For diviners from the east are everywhere; they consult omen readers like the Philistines do. Plenty of foreigners are around.'
EXEC add_BibleVerse @BibleId, 123002007, N'Their land is full of gold and silver; there is no end to their wealth. Their land is full of horses; there is no end to their chariots.'
EXEC add_BibleVerse @BibleId, 123002008, N'Their land is full of worthless idols; they worship the product of their own hands, what their own fingers have fashioned.'
EXEC add_BibleVerse @BibleId, 123002009, N'Men bow down to them in homage, they lie flat on the ground in worship. Don’t spare them!'
EXEC add_BibleVerse @BibleId, 123002010, N'Go up into the rocky cliffs, hide in the ground. Get away from the dreadful judgment of the Lord, from his royal splendor!'
EXEC add_BibleVerse @BibleId, 123002011, N'Proud men will be brought low, arrogant men will be humiliated; the Lord alone will be exalted in that day.'
EXEC add_BibleVerse @BibleId, 123002012, N'Indeed, the Lord who commands armies has planned a day of judgment, for all the high and mighty, for all who are proud – they will be humiliated;'
EXEC add_BibleVerse @BibleId, 123002013, N'for all the cedars of Lebanon, that are so high and mighty, for all the oaks of Bashan;'
EXEC add_BibleVerse @BibleId, 123002014, N'for all the tall mountains, for all the high hills,'
EXEC add_BibleVerse @BibleId, 123002015, N'for every high tower, for every fortified wall,'
EXEC add_BibleVerse @BibleId, 123002016, N'for all the large ships, for all the impressive ships.'
EXEC add_BibleVerse @BibleId, 123002017, N'Proud men will be humiliated, arrogant men will be brought low; the Lord alone will be exalted in that day.'
EXEC add_BibleVerse @BibleId, 123002018, N'The worthless idols will be completely eliminated.'
EXEC add_BibleVerse @BibleId, 123002019, N'They will go into caves in the rocky cliffs and into holes in the ground, trying to escape the dreadful judgment of the Lord and his royal splendor, when he rises up to terrify the earth.'
EXEC add_BibleVerse @BibleId, 123002020, N'At that time men will throw their silver and gold idols, which they made for themselves to worship, into the caves where rodents and bats live,'
EXEC add_BibleVerse @BibleId, 123002021, N'so they themselves can go into the crevices of the rocky cliffs and the openings under the rocky overhangs, trying to escape the dreadful judgment of the Lord and his royal splendor, when he rises up to terrify the earth.'
EXEC add_BibleVerse @BibleId, 123002022, N'Stop trusting in human beings, whose life’s breath is in their nostrils. For why should they be given special consideration?'
EXEC add_BibleVerse @BibleId, 123003001, N'Look, the sovereign Lord who commands armies is about to remove from Jerusalem and Judah every source of security, including all the food and water,'
EXEC add_BibleVerse @BibleId, 123003002, N'the mighty men and warriors, judges and prophets, omen readers and leaders,'
EXEC add_BibleVerse @BibleId, 123003003, N'captains of groups of fifty, the respected citizens, advisers and those skilled in magical arts, and those who know incantations.'
EXEC add_BibleVerse @BibleId, 123003004, N'The Lord says, “I will make youths their officials; malicious young men will rule over them.'
EXEC add_BibleVerse @BibleId, 123003005, N'The people will treat each other harshly; men will oppose each other; neighbors will fight. Youths will proudly defy the elderly and riffraff will challenge those who were once respected.'
EXEC add_BibleVerse @BibleId, 123003006, N'Indeed, a man will grab his brother right in his father’s house and say, ‘You own a coat – you be our leader! This heap of ruins will be under your control.’'
EXEC add_BibleVerse @BibleId, 123003007, N'At that time the brother will shout, ‘I am no doctor, I have no food or coat in my house; don’t make me a leader of the people!’”'
EXEC add_BibleVerse @BibleId, 123003008, N'Jerusalem certainly stumbles, Judah falls, for their words and their actions offend the Lord; they rebel against his royal authority.'
EXEC add_BibleVerse @BibleId, 123003009, N'The look on their faces testifies to their guilt; like the people of Sodom they openly boast of their sin. Too bad for them! For they bring disaster on themselves.'
EXEC add_BibleVerse @BibleId, 123003010, N'Tell the innocent it will go well with them, for they will be rewarded for what they have done.'
EXEC add_BibleVerse @BibleId, 123003011, N'Too bad for the wicked sinners! For they will get exactly what they deserve.'
EXEC add_BibleVerse @BibleId, 123003012, N'Oppressors treat my people cruelly; creditors rule over them. My people’s leaders mislead them; they give you confusing directions.'
EXEC add_BibleVerse @BibleId, 123003013, N'The Lord takes his position to judge; he stands up to pass sentence on his people.'
EXEC add_BibleVerse @BibleId, 123003014, N'The Lord comes to pronounce judgment on the leaders of his people and their officials. He says, “It is you who have ruined the vineyard! You have stashed in your houses what you have stolen from the poor.'
EXEC add_BibleVerse @BibleId, 123003015, N'Why do you crush my people and grind the faces of the poor?” The sovereign Lord who commands armies has spoken.'
EXEC add_BibleVerse @BibleId, 123003016, N'The Lord says, “The women of Zion are proud. They walk with their heads high and flirt with their eyes. They skip along and the jewelry on their ankles jingles.'
EXEC add_BibleVerse @BibleId, 123003017, N'So the sovereign master will afflict the foreheads of Zion’s women with skin diseases, the Lord will make the front of their heads bald.”'
EXEC add_BibleVerse @BibleId, 123003018, N'At that time the sovereign master will remove their beautiful ankle jewelry, neck ornaments, crescent shaped ornaments,'
EXEC add_BibleVerse @BibleId, 123003019, N'earrings, bracelets, veils,'
EXEC add_BibleVerse @BibleId, 123003020, N'headdresses, ankle ornaments, sashes, sachets, amulets,'
EXEC add_BibleVerse @BibleId, 123003021, N'rings, nose rings,'
EXEC add_BibleVerse @BibleId, 123003022, N'festive dresses, robes, shawls, purses,'
EXEC add_BibleVerse @BibleId, 123003023, N'garments, vests, head coverings, and gowns.'
EXEC add_BibleVerse @BibleId, 123003024, N'A putrid stench will replace the smell of spices, a rope will replace a belt, baldness will replace braided locks of hair, a sackcloth garment will replace a fine robe, and a prisoner’s brand will replace beauty.'
EXEC add_BibleVerse @BibleId, 123003025, N'Your men will fall by the sword, your strong men will die in battle.'
EXEC add_BibleVerse @BibleId, 123003026, N'Her gates will mourn and lament; deprived of her people, she will sit on the ground.'
EXEC add_BibleVerse @BibleId, 123004001, N'Seven women will grab hold of one man at that time. They will say, “We will provide our own food, we will provide our own clothes; but let us belong to you – take away our shame!”'
EXEC add_BibleVerse @BibleId, 123004002, N'At that time the crops given by the Lord will bring admiration and honor; the produce of the land will be a source of pride and delight to those who remain in Israel.'
EXEC add_BibleVerse @BibleId, 123004003, N'Those remaining in Zion, those left in Jerusalem, will be called “holy,” all in Jerusalem who are destined to live.'
EXEC add_BibleVerse @BibleId, 123004004, N'At that time the sovereign master will wash the excrement from Zion’s women, he will rinse the bloodstains from Jerusalem’s midst, as he comes to judge and to bring devastation.'
EXEC add_BibleVerse @BibleId, 123004005, N'Then the Lord will create over all of Mount Zion and over its convocations a cloud and smoke by day and a bright flame of fire by night; indeed a canopy will accompany the Lord’s glorious presence.'
EXEC add_BibleVerse @BibleId, 123004006, N'By day it will be a shelter to provide shade from the heat, as well as safety and protection from the heavy downpour.'
EXEC add_BibleVerse @BibleId, 123005001, N'I will sing to my love – a song to my lover about his vineyard. My love had a vineyard on a fertile hill.'
EXEC add_BibleVerse @BibleId, 123005002, N'He built a hedge around it, removed its stones, and planted a vine. He built a tower in the middle of it, and constructed a winepress. He waited for it to produce edible grapes, but it produced sour ones instead.'
EXEC add_BibleVerse @BibleId, 123005003, N'So now, residents of Jerusalem, people of Judah, you decide between me and my vineyard!'
EXEC add_BibleVerse @BibleId, 123005004, N'What more can I do for my vineyard beyond what I have already done? When I waited for it to produce edible grapes, why did it produce sour ones instead?'
EXEC add_BibleVerse @BibleId, 123005005, N'Now I will inform you what I am about to do to my vineyard: I will remove its hedge and turn it into pasture, I will break its wall and allow animals to graze there.'
EXEC add_BibleVerse @BibleId, 123005006, N'I will make it a wasteland; no one will prune its vines or hoe its ground, and thorns and briers will grow there. I will order the clouds not to drop any rain on it.'
EXEC add_BibleVerse @BibleId, 123005007, N'Indeed Israel is the vineyard of the Lord who commands armies, the people of Judah are the cultivated place in which he took delight. He waited for justice, but look what he got – disobedience! He waited for fairness, but look what he got – cries for help!'
EXEC add_BibleVerse @BibleId, 123005008, N'Those who accumulate houses are as good as dead, those who also accumulate landed property until there is no land left, and you are the only landowners remaining within the land.'
EXEC add_BibleVerse @BibleId, 123005009, N'The Lord who commands armies told me this: “Many houses will certainly become desolate, large, impressive houses will have no one living in them.'
EXEC add_BibleVerse @BibleId, 123005010, N'Indeed, a large vineyard will produce just a few gallons, and enough seed to yield several bushels will produce less than a bushel.”'
EXEC add_BibleVerse @BibleId, 123005011, N'Those who get up early to drink beer are as good as dead, those who keep drinking long after dark until they are intoxicated with wine.'
EXEC add_BibleVerse @BibleId, 123005012, N'They have stringed instruments, tambourines, flutes, and wine at their parties. So they do not recognize what the Lord is doing, they do not perceive what he is bringing about.'
EXEC add_BibleVerse @BibleId, 123005013, N'Therefore my people will be deported because of their lack of understanding. Their leaders will have nothing to eat, their masses will have nothing to drink.'
EXEC add_BibleVerse @BibleId, 123005014, N'So Death will open up its throat, and open wide its mouth; Zion’s dignitaries and masses will descend into it, including those who revel and celebrate within her.'
EXEC add_BibleVerse @BibleId, 123005015, N'Men will be humiliated, they will be brought low; the proud will be brought low.'
EXEC add_BibleVerse @BibleId, 123005016, N'The Lord who commands armies will be exalted when he punishes, the sovereign God’s authority will be recognized when he judges.'
EXEC add_BibleVerse @BibleId, 123005017, N'Lambs will graze as if in their pastures, amid the ruins the rich sojourners will graze.'
EXEC add_BibleVerse @BibleId, 123005018, N'Those who pull evil along using cords of emptiness are as good as dead, who pull sin as with cart ropes.'
EXEC add_BibleVerse @BibleId, 123005019, N'They say, “Let him hurry, let him act quickly, so we can see; let the plan of the Holy One of Israel take shape and come to pass, then we will know it!”'
EXEC add_BibleVerse @BibleId, 123005020, N'Those who call evil good and good evil are as good as dead, who turn darkness into light and light into darkness, who turn bitter into sweet and sweet into bitter.'
EXEC add_BibleVerse @BibleId, 123005021, N'Those who think they are wise are as good as dead, those who think they possess understanding.'
EXEC add_BibleVerse @BibleId, 123005022, N'Those who are champions at drinking wine are as good as dead, who display great courage when mixing strong drinks.'
EXEC add_BibleVerse @BibleId, 123005023, N'They pronounce the guilty innocent for a payoff, they ignore the just cause of the innocent.'
EXEC add_BibleVerse @BibleId, 123005024, N'Therefore, as flaming fire devours straw, and dry grass disintegrates in the flames, so their root will rot, and their flower will blow away like dust. For they have rejected the law of the Lord who commands armies, they have spurned the commands of the Holy One of Israel.'
EXEC add_BibleVerse @BibleId, 123005025, N'So the Lord is furious with his people; he lifts his hand and strikes them. The mountains shake, and corpses lie like manure in the middle of the streets. Despite all this, his anger does not subside, and his hand is ready to strike again.'
EXEC add_BibleVerse @BibleId, 123005026, N'He lifts a signal flag for a distant nation, he whistles for it to come from the far regions of the earth. Look, they come quickly and swiftly.'
EXEC add_BibleVerse @BibleId, 123005027, N'None tire or stumble, they don’t stop to nap or sleep. They don’t loosen their belts, or unstrap their sandals to rest.'
EXEC add_BibleVerse @BibleId, 123005028, N'Their arrows are sharpened, and all their bows are prepared. The hooves of their horses are hard as flint, and their chariot wheels are like a windstorm.'
EXEC add_BibleVerse @BibleId, 123005029, N'Their roar is like a lion’s; they roar like young lions. They growl and seize their prey; they drag it away and no one can come to the rescue.'
EXEC add_BibleVerse @BibleId, 123005030, N'At that time they will growl over their prey, it will sound like sea waves crashing against rocks. One will look out over the land and see the darkness of disaster, clouds will turn the light into darkness.'
EXEC add_BibleVerse @BibleId, 123006001, N'In the year of King Uzziah’s death, I saw the sovereign master seated on a high, elevated throne. The hem of his robe filled the temple.'
EXEC add_BibleVerse @BibleId, 123006002, N'Seraphs stood over him; each one had six wings. With two wings they covered their faces, with two they covered their feet, and they used the remaining two to fly.'
EXEC add_BibleVerse @BibleId, 123006003, N'They called out to one another, “Holy, holy, holy is the Lord who commands armies! His majestic splendor fills the entire earth!”'
EXEC add_BibleVerse @BibleId, 123006004, N'The sound of their voices shook the door frames, and the temple was filled with smoke.'
EXEC add_BibleVerse @BibleId, 123006005, N'I said, “Too bad for me! I am destroyed, for my lips are contaminated by sin, and I live among people whose lips are contaminated by sin. My eyes have seen the king, the Lord who commands armies.”'
EXEC add_BibleVerse @BibleId, 123006006, N'But then one of the seraphs flew toward me. In his hand was a hot coal he had taken from the altar with tongs.'
EXEC add_BibleVerse @BibleId, 123006007, N'He touched my mouth with it and said, “Look, this coal has touched your lips. Your evil is removed; your sin is forgiven.”'
EXEC add_BibleVerse @BibleId, 123006008, N'I heard the voice of the sovereign master say, “Whom will I send? Who will go on our behalf?” I answered, “Here I am, send me!”'
EXEC add_BibleVerse @BibleId, 123006009, N'He said, “Go and tell these people: ‘Listen continually, but don’t understand! Look continually, but don’t perceive!’'
EXEC add_BibleVerse @BibleId, 123006010, N'Make the hearts of these people calloused; make their ears deaf and their eyes blind! Otherwise they might see with their eyes and hear with their ears, their hearts might understand and they might repent and be healed.”'
EXEC add_BibleVerse @BibleId, 123006011, N'I replied, “How long, sovereign master?” He said, “Until cities are in ruins and unpopulated, and houses are uninhabited, and the land is ruined and devastated,'
EXEC add_BibleVerse @BibleId, 123006012, N'and the Lord has sent the people off to a distant place, and the very heart of the land is completely abandoned.'
EXEC add_BibleVerse @BibleId, 123006013, N'Even if only a tenth of the people remain in the land, it will again be destroyed, like one of the large sacred trees or an Asherah pole, when a sacred pillar on a high place is thrown down. That sacred pillar symbolizes the special chosen family.”'
EXEC add_BibleVerse @BibleId, 123007001, N'During the reign of Ahaz son of Jotham, son of Uzziah, king of Judah, King Rezin of Syria and King Pekah son of Remaliah of Israel marched up to Jerusalem to do battle, but they were unable to prevail against it.'
EXEC add_BibleVerse @BibleId, 123007002, N'It was reported to the family of David, “Syria has allied with Ephraim.” They and their people were emotionally shaken, just as the trees of the forest shake before the wind.'
EXEC add_BibleVerse @BibleId, 123007003, N'So the Lord told Isaiah, “Go out with your son Shear-jashub and meet Ahaz at the end of the conduit of the upper pool which is located on the road to the field where they wash and dry cloth.'
EXEC add_BibleVerse @BibleId, 123007004, N'Tell him, ‘Make sure you stay calm! Don’t be afraid! Don’t be intimidated by these two stubs of smoking logs, or by the raging anger of Rezin, Syria, and the son of Remaliah.'
EXEC add_BibleVerse @BibleId, 123007005, N'Syria has plotted with Ephraim and the son of Remaliah to bring about your demise.'
EXEC add_BibleVerse @BibleId, 123007006, N'They say, “Let’s attack Judah, terrorize it, and conquer it. Then we’ll set up the son of Tabeel as its king.”'
EXEC add_BibleVerse @BibleId, 123007007, N'For this reason the sovereign master, the Lord, says: “It will not take place; it will not happen.'
EXEC add_BibleVerse @BibleId, 123007008, N'For Syria’s leader is Damascus, and the leader of Damascus is Rezin. Within sixty-five years Ephraim will no longer exist as a nation.'
EXEC add_BibleVerse @BibleId, 123007009, N'Ephraim’s leader is Samaria, and Samaria’s leader is the son of Remaliah. If your faith does not remain firm, then you will not remain secure.”'
EXEC add_BibleVerse @BibleId, 123007010, N'The Lord again spoke to Ahaz:'
EXEC add_BibleVerse @BibleId, 123007011, N'“Ask for a confirming sign from the Lord your God. You can even ask for something miraculous.”'
EXEC add_BibleVerse @BibleId, 123007012, N'But Ahaz responded, “I don’t want to ask; I don’t want to put the Lord to a test.”'
EXEC add_BibleVerse @BibleId, 123007013, N'So Isaiah replied, “Pay attention, family of David. Do you consider it too insignificant to try the patience of men? Is that why you are also trying the patience of my God?'
EXEC add_BibleVerse @BibleId, 123007014, N'For this reason the sovereign master himself will give you a confirming sign. Look, this young woman is about to conceive and will give birth to a son. You, young woman, will name him Immanuel.'
EXEC add_BibleVerse @BibleId, 123007015, N'He will eat sour milk and honey, which will help him know how to reject evil and choose what is right.'
EXEC add_BibleVerse @BibleId, 123007016, N'Here is why this will be so: Before the child knows how to reject evil and choose what is right, the land whose two kings you fear will be desolate.'
EXEC add_BibleVerse @BibleId, 123007017, N'The Lord will bring on you, your people, and your father’s family a time unlike any since Ephraim departed from Judah – the king of Assyria!”'
EXEC add_BibleVerse @BibleId, 123007018, N'At that time the Lord will whistle for flies from the distant streams of Egypt and for bees from the land of Assyria.'
EXEC add_BibleVerse @BibleId, 123007019, N'All of them will come and make their home in the ravines between the cliffs, and in the crevices of the cliffs, in all the thorn bushes, and in all the watering holes.'
EXEC add_BibleVerse @BibleId, 123007020, N'At that time the sovereign master will use a razor hired from the banks of the Euphrates River, the king of Assyria, to shave the head and the pubic hair; it will also shave off the beard.'
EXEC add_BibleVerse @BibleId, 123007021, N'At that time a man will keep alive a young cow from the herd and a couple of goats.'
EXEC add_BibleVerse @BibleId, 123007022, N'From the abundance of milk they produce, he will have sour milk for his meals. Indeed, everyone left in the heart of the land will eat sour milk and honey.'
EXEC add_BibleVerse @BibleId, 123007023, N'At that time every place where there had been a thousand vines worth a thousand shekels will be overrun with thorns and briers.'
EXEC add_BibleVerse @BibleId, 123007024, N'With bow and arrow men will hunt there, for the whole land will be covered with thorns and briers.'
EXEC add_BibleVerse @BibleId, 123007025, N'They will stay away from all the hills that were cultivated, for fear of the thorns and briers. Cattle will graze there and sheep will trample on them.'
EXEC add_BibleVerse @BibleId, 123008001, N'The Lord told me, “Take a large tablet and inscribe these words on it with an ordinary stylus: ‘Maher-Shalal-Hash-Baz.’'
EXEC add_BibleVerse @BibleId, 123008002, N'Then I will summon as my reliable witnesses Uriah the priest and Zechariah son of Jeberekiah.”'
EXEC add_BibleVerse @BibleId, 123008003, N'I then had sexual relations with the prophetess; she conceived and gave birth to a son. The Lord told me, “Name him Maher-Shalal-Hash-Baz,'
EXEC add_BibleVerse @BibleId, 123008004, N'for before the child knows how to cry out, ‘My father’ or ‘My mother,’ the wealth of Damascus and the plunder of Samaria will be carried off by the king of Assyria.”'
EXEC add_BibleVerse @BibleId, 123008005, N'The Lord spoke to me again:'
EXEC add_BibleVerse @BibleId, 123008006, N'“These people have rejected the gently flowing waters of Shiloah and melt in fear over Rezin and the son of Remaliah.'
EXEC add_BibleVerse @BibleId, 123008007, N'So look, the sovereign master is bringing up against them the turbulent and mighty waters of the Euphrates River – the king of Assyria and all his majestic power. It will reach flood stage and overflow its banks.'
EXEC add_BibleVerse @BibleId, 123008008, N'It will spill into Judah, flooding and engulfing, as it reaches to the necks of its victims. He will spread his wings out over your entire land, O Immanuel.”'
EXEC add_BibleVerse @BibleId, 123008009, N'You will be broken, O nations; you will be shattered! Pay attention, all you distant lands of the earth! Get ready for battle, and you will be shattered! Get ready for battle, and you will be shattered!'
EXEC add_BibleVerse @BibleId, 123008010, N'Devise your strategy, but it will be thwarted! Issue your orders, but they will not be executed! For God is with us!'
EXEC add_BibleVerse @BibleId, 123008011, N'Indeed this is what the Lord told me. He took hold of me firmly and warned me not to act like these people:'
EXEC add_BibleVerse @BibleId, 123008012, N'“Do not say, ‘Conspiracy,’ every time these people say the word. Don’t be afraid of what scares them; don’t be terrified.'
EXEC add_BibleVerse @BibleId, 123008013, N'You must recognize the authority of the Lord who commands armies. He is the one you must respect; he is the one you must fear.'
EXEC add_BibleVerse @BibleId, 123008014, N'He will become a sanctuary, but a stone that makes a person trip, and a rock that makes one stumble – to the two houses of Israel. He will become a trap and a snare to the residents of Jerusalem.'
EXEC add_BibleVerse @BibleId, 123008015, N'Many will stumble over the stone and the rock, and will fall and be seriously injured, and will be ensnared and captured.”'
EXEC add_BibleVerse @BibleId, 123008016, N'Tie up the scroll as legal evidence, seal the official record of God’s instructions and give it to my followers.'
EXEC add_BibleVerse @BibleId, 123008017, N'I will wait patiently for the Lord, who has rejected the family of Jacob; I will wait for him.'
EXEC add_BibleVerse @BibleId, 123008018, N'Look, I and the sons whom the Lord has given me are reminders and object lessons in Israel, sent from the Lord who commands armies, who lives on Mount Zion.'
EXEC add_BibleVerse @BibleId, 123008019, N'They will say to you, “Seek oracles at the pits used to conjure up underworld spirits, from the magicians who chirp and mutter incantations. Should people not seek oracles from their gods, by asking the dead about the destiny of the living?”'
EXEC add_BibleVerse @BibleId, 123008020, N'Then you must recall the Lord’s instructions and the prophetic testimony of what would happen. Certainly they say such things because their minds are spiritually darkened.'
EXEC add_BibleVerse @BibleId, 123008021, N'They will pass through the land destitute and starving. Their hunger will make them angry, and they will curse their king and their God as they look upward.'
EXEC add_BibleVerse @BibleId, 123008022, N'When one looks out over the land, he sees distress and darkness, gloom and anxiety, darkness and people forced from the land.'
EXEC add_BibleVerse @BibleId, 123009001, N'The gloom will be dispelled for those who were anxious. In earlier times he humiliated the land of Zebulun, and the land of Naphtali; but now he brings honor to the way of the sea, the region beyond the Jordan, and Galilee of the nations.'
EXEC add_BibleVerse @BibleId, 123009002, N'The people walking in darkness see a bright light; light shines on those who live in a land of deep darkness.'
EXEC add_BibleVerse @BibleId, 123009003, N'You have enlarged the nation; you give them great joy. They rejoice in your presence as harvesters rejoice; as warriors celebrate when they divide up the plunder.'
EXEC add_BibleVerse @BibleId, 123009004, N'For their oppressive yoke and the club that strikes their shoulders, the cudgel the oppressor uses on them, you have shattered, as in the day of Midian’s defeat.'
EXEC add_BibleVerse @BibleId, 123009005, N'Indeed every boot that marches and shakes the earth and every garment dragged through blood is used as fuel for the fire.'
EXEC add_BibleVerse @BibleId, 123009006, N'For a child has been born to us, a son has been given to us. He shoulders responsibility and is called: Extraordinary Strategist, Mighty God, Everlasting Father, Prince of Peace.'
EXEC add_BibleVerse @BibleId, 123009007, N'His dominion will be vast and he will bring immeasurable prosperity. He will rule on David’s throne and over David’s kingdom, establishing it and strengthening it by promoting justice and fairness, from this time forward and forevermore. The Lord’s intense devotion to his people will accomplish this.'
EXEC add_BibleVerse @BibleId, 123009008, N'The sovereign master decreed judgment on Jacob, and it fell on Israel.'
EXEC add_BibleVerse @BibleId, 123009009, N'All the people were aware of it, the people of Ephraim and those living in Samaria. Yet with pride and an arrogant attitude, they said,'
EXEC add_BibleVerse @BibleId, 123009010, N'“The bricks have fallen, but we will rebuild with chiseled stone; the sycamore fig trees have been cut down, but we will replace them with cedars.”'
EXEC add_BibleVerse @BibleId, 123009011, N'Then the Lord provoked their adversaries to attack them, he stirred up their enemies –'
EXEC add_BibleVerse @BibleId, 123009012, N'Syria from the east, and the Philistines from the west, they gobbled up Israelite territory. Despite all this, his anger does not subside, and his hand is ready to strike again.'
EXEC add_BibleVerse @BibleId, 123009013, N'The people did not return to the one who struck them, they did not seek reconciliation with the Lord who commands armies.'
EXEC add_BibleVerse @BibleId, 123009014, N'So the Lord cut off Israel’s head and tail, both the shoots and stalk in one day.'
EXEC add_BibleVerse @BibleId, 123009015, N'The leaders and the highly respected people are the head, the prophets who teach lies are the tail.'
EXEC add_BibleVerse @BibleId, 123009016, N'The leaders of this nation were misleading people, and the people being led were destroyed.'
EXEC add_BibleVerse @BibleId, 123009017, N'So the sovereign master was not pleased with their young men, he took no pity on their orphans and widows; for the whole nation was godless and did wicked things, every mouth was speaking disgraceful words. Despite all this, his anger does not subside, and his hand is ready to strike again.'
EXEC add_BibleVerse @BibleId, 123009018, N'For evil burned like a fire, it consumed thorns and briers; it burned up the thickets of the forest, and they went up in smoke.'
EXEC add_BibleVerse @BibleId, 123009019, N'Because of the anger of the Lord who commands armies, the land was scorched, and the people became fuel for the fire. People had no compassion on one another.'
EXEC add_BibleVerse @BibleId, 123009020, N'They devoured on the right, but were still hungry, they ate on the left, but were not satisfied. People even ate the flesh of their own arm!'
EXEC add_BibleVerse @BibleId, 123009021, N'Manasseh fought against Ephraim, and Ephraim against Manasseh; together they fought against Judah. Despite all this, his anger does not subside, and his hand is ready to strike again.'
EXEC add_BibleVerse @BibleId, 123010001, N'Those who enact unjust policies are as good as dead, those who are always instituting unfair regulations,'
EXEC add_BibleVerse @BibleId, 123010002, N'to keep the poor from getting fair treatment, and to deprive the oppressed among my people of justice, so they can steal what widows own, and loot what belongs to orphans.'
EXEC add_BibleVerse @BibleId, 123010003, N'What will you do on judgment day, when destruction arrives from a distant place? To whom will you run for help? Where will you leave your wealth?'
EXEC add_BibleVerse @BibleId, 123010004, N'You will have no place to go, except to kneel with the prisoners, or to fall among those who have been killed. Despite all this, his anger does not subside, and his hand is ready to strike again.'
EXEC add_BibleVerse @BibleId, 123010005, N'Assyria, the club I use to vent my anger, is as good as dead, a cudgel with which I angrily punish.'
EXEC add_BibleVerse @BibleId, 123010006, N'I sent him against a godless nation, I ordered him to attack the people with whom I was angry, to take plunder and to carry away loot, to trample them down like dirt in the streets.'
EXEC add_BibleVerse @BibleId, 123010007, N'But he does not agree with this, his mind does not reason this way, for his goal is to destroy, and to eliminate many nations.'
EXEC add_BibleVerse @BibleId, 123010008, N'Indeed, he says: “Are not my officials all kings?'
EXEC add_BibleVerse @BibleId, 123010009, N'Is not Calneh like Carchemish? Hamath like Arpad? Samaria like Damascus?'
EXEC add_BibleVerse @BibleId, 123010010, N'I overpowered kingdoms ruled by idols, whose carved images were more impressive than Jerusalem’s or Samaria’s.'
EXEC add_BibleVerse @BibleId, 123010011, N'As I have done to Samaria and its idols, so I will do to Jerusalem and its idols.”'
EXEC add_BibleVerse @BibleId, 123010012, N'But when the sovereign master finishes judging Mount Zion and Jerusalem, then I will punish the king of Assyria for what he has proudly planned and for the arrogant attitude he displays.'
EXEC add_BibleVerse @BibleId, 123010013, N'For he says: “By my strong hand I have accomplished this, by my strategy that I devised. I invaded the territory of nations, and looted their storehouses. Like a mighty conqueror, I brought down rulers.'
EXEC add_BibleVerse @BibleId, 123010014, N'My hand discovered the wealth of the nations, as if it were in a nest, as one gathers up abandoned eggs, I gathered up the whole earth. There was no wing flapping, or open mouth chirping.”'
EXEC add_BibleVerse @BibleId, 123010015, N'Does an ax exalt itself over the one who wields it, or a saw magnify itself over the one who cuts with it? As if a scepter should brandish the one who raises it, or a staff should lift up what is not made of wood!'
EXEC add_BibleVerse @BibleId, 123010016, N'For this reason the sovereign master, the Lord who commands armies, will make his healthy ones emaciated. His majestic glory will go up in smoke.'
EXEC add_BibleVerse @BibleId, 123010017, N'The light of Israel will become a fire, their Holy One will become a flame; it will burn and consume the Assyrian king’s briers and his thorns in one day.'
EXEC add_BibleVerse @BibleId, 123010018, N'The splendor of his forest and his orchard will be completely destroyed, as when a sick man’s life ebbs away.'
EXEC add_BibleVerse @BibleId, 123010019, N'There will be so few trees left in his forest, a child will be able to count them.'
EXEC add_BibleVerse @BibleId, 123010020, N'At that time those left in Israel, those who remain of the family of Jacob, will no longer rely on a foreign leader that abuses them. Instead they will truly rely on the Lord, the Holy One of Israel.'
EXEC add_BibleVerse @BibleId, 123010021, N'A remnant will come back, a remnant of Jacob, to the mighty God.'
EXEC add_BibleVerse @BibleId, 123010022, N'For though your people, Israel, are as numerous as the sand on the seashore, only a remnant will come back. Destruction has been decreed; just punishment is about to engulf you.'
EXEC add_BibleVerse @BibleId, 123010023, N'The sovereign master, the Lord who commands armies, is certainly ready to carry out the decreed destruction throughout the land.'
EXEC add_BibleVerse @BibleId, 123010024, N'So here is what the sovereign master, the Lord who commands armies, says: “My people who live in Zion, do not be afraid of Assyria, even though they beat you with a club and lift their cudgel against you as Egypt did.'
EXEC add_BibleVerse @BibleId, 123010025, N'For very soon my fury will subside, and my anger will be directed toward their destruction.”'
EXEC add_BibleVerse @BibleId, 123010026, N'The Lord who commands armies is about to beat them with a whip, similar to the way he struck down Midian at the rock of Oreb. He will use his staff against the sea, lifting it up as he did in Egypt.'
EXEC add_BibleVerse @BibleId, 123010027, N'At that time the Lord will remove their burden from your shoulders, and their yoke from your neck; the yoke will be taken off because your neck will be too large.'
EXEC add_BibleVerse @BibleId, 123010028, N'They attacked Aiath, moved through Migron, depositing their supplies at Micmash.'
EXEC add_BibleVerse @BibleId, 123010029, N'They went through the pass, spent the night at Geba. Ramah trembled, Gibeah of Saul ran away.'
EXEC add_BibleVerse @BibleId, 123010030, N'Shout out, daughter of Gallim! Pay attention, Laishah! Answer her, Anathoth!'
EXEC add_BibleVerse @BibleId, 123010031, N'Madmenah flees, the residents of Gebim have hidden.'
EXEC add_BibleVerse @BibleId, 123010032, N'This very day, standing in Nob, they shake their fist at Daughter Zion’s mountain – at the hill of Jerusalem.'
EXEC add_BibleVerse @BibleId, 123010033, N'Look, the sovereign master, the Lord who commands armies, is ready to cut off the branches with terrifying power. The tallest trees will be cut down, the loftiest ones will be brought low.'
EXEC add_BibleVerse @BibleId, 123010034, N'The thickets of the forest will be chopped down with an ax, and mighty Lebanon will fall.'
EXEC add_BibleVerse @BibleId, 123011001, N'A shoot will grow out of Jesse’s root stock, a bud will sprout from his roots.'
EXEC add_BibleVerse @BibleId, 123011002, N'The Lord’s spirit will rest on him – a spirit that gives extraordinary wisdom, a spirit that provides the ability to execute plans, a spirit that produces absolute loyalty to the Lord.'
EXEC add_BibleVerse @BibleId, 123011003, N'He will take delight in obeying the Lord. He will not judge by mere appearances, or make decisions on the basis of hearsay.'
EXEC add_BibleVerse @BibleId, 123011004, N'He will treat the poor fairly, and make right decisions for the downtrodden of the earth. He will strike the earth with the rod of his mouth, and order the wicked to be executed.'
EXEC add_BibleVerse @BibleId, 123011005, N'Justice will be like a belt around his waist, integrity will be like a belt around his hips.'
EXEC add_BibleVerse @BibleId, 123011006, N'A wolf will reside with a lamb, and a leopard will lie down with a young goat; an ox and a young lion will graze together, as a small child leads them along.'
EXEC add_BibleVerse @BibleId, 123011007, N'A cow and a bear will graze together, their young will lie down together. A lion, like an ox, will eat straw.'
EXEC add_BibleVerse @BibleId, 123011008, N'A baby will play over the hole of a snake; over the nest of a serpent an infant will put his hand.'
EXEC add_BibleVerse @BibleId, 123011009, N'They will no longer injure or destroy on my entire royal mountain. For there will be universal submission to the Lord’s sovereignty, just as the waters completely cover the sea.'
EXEC add_BibleVerse @BibleId, 123011010, N'At that time a root from Jesse will stand like a signal flag for the nations. Nations will look to him for guidance, and his residence will be majestic.'
EXEC add_BibleVerse @BibleId, 123011011, N'At that time the sovereign master will again lift his hand to reclaim the remnant of his people from Assyria, Egypt, Pathros, Cush, Elam, Shinar, Hamath, and the seacoasts.'
EXEC add_BibleVerse @BibleId, 123011012, N'He will lift a signal flag for the nations; he will gather Israel’s dispersed people and assemble Judah’s scattered people from the four corners of the earth.'
EXEC add_BibleVerse @BibleId, 123011013, N'Ephraim’s jealousy will end, and Judah’s hostility will be eliminated. Ephraim will no longer be jealous of Judah, and Judah will no longer be hostile toward Ephraim.'
EXEC add_BibleVerse @BibleId, 123011014, N'They will swoop down on the Philistine hills to the west; together they will loot the people of the east. They will take over Edom and Moab, and the Ammonites will be their subjects.'
EXEC add_BibleVerse @BibleId, 123011015, N'The Lord will divide the gulf of the Egyptian Sea; he will wave his hand over the Euphrates River and send a strong wind, he will turn it into seven dried-up streams, and enable them to walk across in their sandals.'
EXEC add_BibleVerse @BibleId, 123011016, N'There will be a highway leading out of Assyria for the remnant of his people, just as there was for Israel, when they went up from the land of Egypt.'
EXEC add_BibleVerse @BibleId, 123012001, N'At that time you will say: “I praise you, O Lord, for even though you were angry with me, your anger subsided, and you consoled me.'
EXEC add_BibleVerse @BibleId, 123012002, N'Look, God is my deliverer! I will trust in him and not fear. For the Lord gives me strength and protects me; he has become my deliverer.”'
EXEC add_BibleVerse @BibleId, 123012003, N'Joyfully you will draw water from the springs of deliverance.'
EXEC add_BibleVerse @BibleId, 123012004, N'At that time you will say: “Praise the Lord! Ask him for help! Publicize his mighty acts among the nations! Make it known that he is unique!'
EXEC add_BibleVerse @BibleId, 123012005, N'Sing to the Lord, for he has done magnificent things, let this be known throughout the earth!'
EXEC add_BibleVerse @BibleId, 123012006, N'Cry out and shout for joy, O citizens of Zion, for the Holy One of Israel acts mightily among you!”'
EXEC add_BibleVerse @BibleId, 123013001, N'This is a message about Babylon that God revealed to Isaiah son of Amoz:'
EXEC add_BibleVerse @BibleId, 123013002, N'On a bare hill raise a signal flag, shout to them, wave your hand, so they might enter the gates of the princes!'
EXEC add_BibleVerse @BibleId, 123013003, N'I have given orders to my chosen soldiers; I have summoned the warriors through whom I will vent my anger, my boasting, arrogant ones.'
EXEC add_BibleVerse @BibleId, 123013004, N'There is a loud noise on the mountains – it sounds like a large army! There is great commotion among the kingdoms – nations are being assembled! The Lord who commands armies is mustering forces for battle.'
EXEC add_BibleVerse @BibleId, 123013005, N'They come from a distant land, from the horizon. It is the Lord with his instruments of judgment, coming to destroy the whole earth.'
EXEC add_BibleVerse @BibleId, 123013006, N'Wail, for the Lord’s day of judgment is near; it comes with all the destructive power of the sovereign judge.'
EXEC add_BibleVerse @BibleId, 123013007, N'For this reason all hands hang limp, every human heart loses its courage.'
EXEC add_BibleVerse @BibleId, 123013008, N'They panic – cramps and pain seize hold of them like those of a woman who is straining to give birth. They look at one another in astonishment; their faces are flushed red.'
EXEC add_BibleVerse @BibleId, 123013009, N'Look, the Lord’s day of judgment is coming; it is a day of cruelty and savage, raging anger, destroying the earth and annihilating its sinners.'
EXEC add_BibleVerse @BibleId, 123013010, N'Indeed the stars in the sky and their constellations no longer give out their light; the sun is darkened as soon as it rises, and the moon does not shine.'
EXEC add_BibleVerse @BibleId, 123013011, N'I will punish the world for its evil, and wicked people for their sin. I will put an end to the pride of the insolent, I will bring down the arrogance of tyrants.'
EXEC add_BibleVerse @BibleId, 123013012, N'I will make human beings more scarce than pure gold, and people more scarce than gold from Ophir.'
EXEC add_BibleVerse @BibleId, 123013013, N'So I will shake the heavens, and the earth will shake loose from its foundation, because of the fury of the Lord who commands armies, in the day he vents his raging anger.'
EXEC add_BibleVerse @BibleId, 123013014, N'Like a frightened gazelle or a sheep with no shepherd, each will turn toward home, each will run to his homeland.'
EXEC add_BibleVerse @BibleId, 123013015, N'Everyone who is caught will be stabbed; everyone who is seized will die by the sword.'
EXEC add_BibleVerse @BibleId, 123013016, N'Their children will be smashed to pieces before their very eyes; their houses will be looted and their wives raped.'
EXEC add_BibleVerse @BibleId, 123013017, N'Look, I am stirring up the Medes to attack them; they are not concerned about silver, nor are they interested in gold.'
EXEC add_BibleVerse @BibleId, 123013018, N'Their arrows will cut young men to ribbons; they have no compassion on a person’s offspring, they will not look with pity on children.'
EXEC add_BibleVerse @BibleId, 123013019, N'Babylon, the most admired of kingdoms, the Chaldeans’ source of honor and pride, will be destroyed by God just as Sodom and Gomorrah were.'
EXEC add_BibleVerse @BibleId, 123013020, N'No one will live there again; no one will ever reside there again. No bedouin will camp there, no shepherds will rest their flocks there.'
EXEC add_BibleVerse @BibleId, 123013021, N'Wild animals will rest there, the ruined houses will be full of hyenas. Ostriches will live there, wild goats will skip among the ruins.'
EXEC add_BibleVerse @BibleId, 123013022, N'Wild dogs will yip in her ruined fortresses, jackals will yelp in the once-splendid palaces. Her time is almost up, her days will not be prolonged.'
EXEC add_BibleVerse @BibleId, 123014001, N'The Lord will certainly have compassion on Jacob; he will again choose Israel as his special people and restore them to their land. Resident foreigners will join them and unite with the family of Jacob.'
EXEC add_BibleVerse @BibleId, 123014002, N'Nations will take them and bring them back to their own place. Then the family of Jacob will make foreigners their servants as they settle in the Lord’s land. They will make their captors captives and rule over the ones who oppressed them.'
EXEC add_BibleVerse @BibleId, 123014003, N'When the Lord gives you relief from your suffering and anxiety, and from the hard labor which you were made to perform,'
EXEC add_BibleVerse @BibleId, 123014004, N'you will taunt the king of Babylon with these words: “Look how the oppressor has met his end! Hostility has ceased!'
EXEC add_BibleVerse @BibleId, 123014005, N'The Lord has broken the club of the wicked, the scepter of rulers.'
EXEC add_BibleVerse @BibleId, 123014006, N'It furiously struck down nations with unceasing blows. It angrily ruled over nations, oppressing them without restraint.'
EXEC add_BibleVerse @BibleId, 123014007, N'The whole earth rests and is quiet; they break into song.'
EXEC add_BibleVerse @BibleId, 123014008, N'The evergreens also rejoice over your demise, as do the cedars of Lebanon, singing, ‘Since you fell asleep, no woodsman comes up to chop us down!’'
EXEC add_BibleVerse @BibleId, 123014009, N'Sheol below is stirred up about you, ready to meet you when you arrive. It rouses the spirits of the dead for you, all the former leaders of the earth; it makes all the former kings of the nations rise from their thrones.'
EXEC add_BibleVerse @BibleId, 123014010, N'All of them respond to you, saying: ‘You too have become weak like us! You have become just like us!'
EXEC add_BibleVerse @BibleId, 123014011, N'Your splendor has been brought down to Sheol, as well as the sound of your stringed instruments. You lie on a bed of maggots, with a blanket of worms over you.'
EXEC add_BibleVerse @BibleId, 123014012, N'Look how you have fallen from the sky, O shining one, son of the dawn! You have been cut down to the ground, O conqueror of the nations!'
EXEC add_BibleVerse @BibleId, 123014013, N'You said to yourself, “I will climb up to the sky. Above the stars of El I will set up my throne. I will rule on the mountain of assembly on the remote slopes of Zaphon.'
EXEC add_BibleVerse @BibleId, 123014014, N'I will climb up to the tops of the clouds; I will make myself like the Most High!”'
EXEC add_BibleVerse @BibleId, 123014015, N'But you were brought down to Sheol, to the remote slopes of the pit.'
EXEC add_BibleVerse @BibleId, 123014016, N'Those who see you stare at you, they look at you carefully, thinking: “Is this the man who shook the earth, the one who made kingdoms tremble?'
EXEC add_BibleVerse @BibleId, 123014017, N'Is this the one who made the world like a desert, who ruined its cities, and refused to free his prisoners so they could return home?”’'
EXEC add_BibleVerse @BibleId, 123014018, N'As for all the kings of the nations, all of them lie down in splendor, each in his own tomb.'
EXEC add_BibleVerse @BibleId, 123014019, N'But you have been thrown out of your grave like a shoot that is thrown away. You lie among the slain, among those who have been slashed by the sword, among those headed for the stones of the pit, as if you were a mangled corpse.'
EXEC add_BibleVerse @BibleId, 123014020, N'You will not be buried with them, because you destroyed your land and killed your people. The offspring of the wicked will never be mentioned again.'
EXEC add_BibleVerse @BibleId, 123014021, N'Prepare to execute his sons for the sins their ancestors have committed. They must not rise up and take possession of the earth, or fill the surface of the world with cities.”'
EXEC add_BibleVerse @BibleId, 123014022, N'“I will rise up against them,” says the Lord who commands armies. “I will blot out all remembrance of Babylon and destroy all her people, including the offspring she produces,” says the Lord.'
EXEC add_BibleVerse @BibleId, 123014023, N'“I will turn her into a place that is overrun with wild animals and covered with pools of stagnant water. I will get rid of her, just as one sweeps away dirt with a broom,” says the Lord who commands armies.'
EXEC add_BibleVerse @BibleId, 123014024, N'The Lord who commands armies makes this solemn vow: “Be sure of this: Just as I have intended, so it will be; just as I have planned, it will happen.'
EXEC add_BibleVerse @BibleId, 123014025, N'I will break Assyria in my land, I will trample them underfoot on my hills. Their yoke will be removed from my people, the burden will be lifted from their shoulders.'
EXEC add_BibleVerse @BibleId, 123014026, N'This is the plan I have devised for the whole earth; my hand is ready to strike all the nations.”'
EXEC add_BibleVerse @BibleId, 123014027, N'Indeed, the Lord who commands armies has a plan, and who can possibly frustrate it? His hand is ready to strike, and who can possibly stop it?'
EXEC add_BibleVerse @BibleId, 123014028, N'In the year King Ahaz died, this message was revealed:'
EXEC add_BibleVerse @BibleId, 123014029, N'Don’t be so happy, all you Philistines, just because the club that beat you has been broken! For a viper will grow out of the serpent’s root, and its fruit will be a darting adder.'
EXEC add_BibleVerse @BibleId, 123014030, N'The poor will graze in my pastures; the needy will rest securely. But I will kill your root by famine; it will put to death all your survivors.'
EXEC add_BibleVerse @BibleId, 123014031, N'Wail, O city gate! Cry out, O city! Melt with fear, all you Philistines! For out of the north comes a cloud of smoke, and there are no stragglers in its ranks.'
EXEC add_BibleVerse @BibleId, 123014032, N'How will they respond to the messengers of this nation? Indeed, the Lord has made Zion secure; the oppressed among his people will find safety in her.'
EXEC add_BibleVerse @BibleId, 123015001, N'Here is a message about Moab: Indeed, in a night it is devastated, Ar of Moab is destroyed! Indeed, in a night it is devastated, Kir of Moab is destroyed!'
EXEC add_BibleVerse @BibleId, 123015002, N'They went up to the temple, the people of Dibon went up to the high places to lament. Because of what happened to Nebo and Medeba, Moab wails. Every head is shaved bare, every beard is trimmed off.'
EXEC add_BibleVerse @BibleId, 123015003, N'In their streets they wear sackcloth; on their roofs and in their town squares all of them wail, they fall down weeping.'
EXEC add_BibleVerse @BibleId, 123015004, N'The people of Heshbon and Elealeh cry out, their voices are heard as far away as Jahaz. For this reason Moab’s soldiers shout in distress; their courage wavers.'
EXEC add_BibleVerse @BibleId, 123015005, N'My heart cries out because of Moab’s plight, and for the fugitives stretched out as far as Zoar and Eglath Shelishiyah. For they weep as they make their way up the ascent of Luhith; they loudly lament their demise on the road to Horonaim.'
EXEC add_BibleVerse @BibleId, 123015006, N'For the waters of Nimrim are gone; the grass is dried up, the vegetation has disappeared, and there are no plants.'
EXEC add_BibleVerse @BibleId, 123015007, N'For this reason what they have made and stored up, they carry over the Stream of the Poplars.'
EXEC add_BibleVerse @BibleId, 123015008, N'Indeed, the cries of distress echo throughout Moabite territory; their wailing can be heard in Eglaim and Beer Elim.'
EXEC add_BibleVerse @BibleId, 123015009, N'Indeed, the waters of Dimon are full of blood! Indeed, I will heap even more trouble on Dimon. A lion will attack the Moabite fugitives and the people left in the land.'
EXEC add_BibleVerse @BibleId, 123016001, N'Send rams as tribute to the ruler of the land, from Sela in the desert to the hill of Daughter Zion.'
EXEC add_BibleVerse @BibleId, 123016002, N'At the fords of the Arnon the Moabite women are like a bird that flies about when forced from its nest.'
EXEC add_BibleVerse @BibleId, 123016003, N'“Bring a plan, make a decision! Provide some shade in the middle of the day! Hide the fugitives! Do not betray the one who tries to escape!'
EXEC add_BibleVerse @BibleId, 123016004, N'Please let the Moabite fugitives live among you. Hide them from the destroyer!” Certainly the one who applies pressure will cease, the destroyer will come to an end, those who trample will disappear from the earth.'
EXEC add_BibleVerse @BibleId, 123016005, N'Then a trustworthy king will be established; he will rule in a reliable manner, this one from David’s family. He will be sure to make just decisions and will be experienced in executing justice.'
EXEC add_BibleVerse @BibleId, 123016006, N'We have heard about Moab’s pride, their great arrogance, their boasting, pride, and excess. But their boastful claims are empty!'
EXEC add_BibleVerse @BibleId, 123016007, N'So Moab wails over its demise – they all wail! Completely devastated, they moan about what has happened to the raisin cakes of Kir Hareseth.'
EXEC add_BibleVerse @BibleId, 123016008, N'For the fields of Heshbon are dried up, as well as the vines of Sibmah. The rulers of the nations trample all over its vines, which reach Jazer and spread to the desert; their shoots spread out and cross the sea.'
EXEC add_BibleVerse @BibleId, 123016009, N'So I weep along with Jazer over the vines of Sibmah. I will saturate you with my tears, Heshbon and Elealeh, for the conquering invaders shout triumphantly over your fruit and crops.'
EXEC add_BibleVerse @BibleId, 123016010, N'Joy and happiness disappear from the orchards, and in the vineyards no one rejoices or shouts; no one treads out juice in the wine vats – I have brought the joyful shouts to an end.'
EXEC add_BibleVerse @BibleId, 123016011, N'So my heart constantly sighs for Moab, like the strumming of a harp, my inner being sighs for Kir Hareseth.'
EXEC add_BibleVerse @BibleId, 123016012, N'When the Moabites plead with all their might at their high places, and enter their temples to pray, their prayers will be ineffective!'
EXEC add_BibleVerse @BibleId, 123016013, N'This is the message the Lord previously announced about Moab.'
EXEC add_BibleVerse @BibleId, 123016014, N'Now the Lord makes this announcement: “Within exactly three years Moab’s splendor will disappear, along with all her many people; there will be just a few, insignificant survivors left.”'
EXEC add_BibleVerse @BibleId, 123017001, N'Here is a message about Damascus: “Look, Damascus is no longer a city, it is a heap of ruins!'
EXEC add_BibleVerse @BibleId, 123017002, N'The cities of Aroer are abandoned. They will be used for herds, which will lie down there in peace.'
EXEC add_BibleVerse @BibleId, 123017003, N'Fortified cities will disappear from Ephraim, and Damascus will lose its kingdom. The survivors in Syria will end up like the splendor of the Israelites,” says the Lord who commands armies.'
EXEC add_BibleVerse @BibleId, 123017004, N'“At that time Jacob’s splendor will be greatly diminished, and he will become skin and bones.'
EXEC add_BibleVerse @BibleId, 123017005, N'It will be as when one gathers the grain harvest, and his hand gleans the ear of grain. It will be like one gathering the ears of grain in the Valley of Rephaim.'
EXEC add_BibleVerse @BibleId, 123017006, N'There will be some left behind, like when an olive tree is beaten – two or three ripe olives remain toward the very top, four or five on its fruitful branches,” says the Lord God of Israel.'
EXEC add_BibleVerse @BibleId, 123017007, N'At that time men will trust in their creator; they will depend on the Holy One of Israel.'
EXEC add_BibleVerse @BibleId, 123017008, N'They will no longer trust in the altars their hands made, or depend on the Asherah poles and incense altars their fingers made.'
EXEC add_BibleVerse @BibleId, 123017009, N'At that time their fortified cities will be like the abandoned summits of the Amorites, which they abandoned because of the Israelites; there will be desolation.'
EXEC add_BibleVerse @BibleId, 123017010, N'For you ignore the God who rescues you; you pay no attention to your strong protector. So this is what happens: You cultivate beautiful plants and plant exotic vines.'
EXEC add_BibleVerse @BibleId, 123017011, N'The day you begin cultivating, you do what you can to make it grow; the morning you begin planting, you do what you can to make it sprout. Yet the harvest will disappear in the day of disease and incurable pain.'
EXEC add_BibleVerse @BibleId, 123017012, N'The many nations massing together are as good as dead, those who make a commotion as loud as the roaring of the sea’s waves. The people making such an uproar are as good as dead, those who make an uproar as loud as the roaring of powerful waves.'
EXEC add_BibleVerse @BibleId, 123017013, N'Though these people make an uproar as loud as the roaring of powerful waves, when he shouts at them, they will flee to a distant land, driven before the wind like dead weeds on the hills, or like dead thistles before a strong gale.'
EXEC add_BibleVerse @BibleId, 123017014, N'In the evening there is sudden terror; by morning they vanish. This is the fate of those who try to plunder us, the destiny of those who try to loot us!'
EXEC add_BibleVerse @BibleId, 123018001, N'The land of buzzing wings is as good as dead, the one beyond the rivers of Cush,'
EXEC add_BibleVerse @BibleId, 123018002, N'that sends messengers by sea, who glide over the water’s surface in boats made of papyrus. Go, you swift messengers, to a nation of tall, smooth-skinned people, to a people that are feared far and wide, to a nation strong and victorious, whose land rivers divide.'
EXEC add_BibleVerse @BibleId, 123018003, N'All you who live in the world, who reside on the earth, you will see a signal flag raised on the mountains; you will hear a trumpet being blown.'
EXEC add_BibleVerse @BibleId, 123018004, N'For this is what the Lord has told me: “I will wait and watch from my place, like scorching heat produced by the sunlight, like a cloud of mist in the heat of harvest.”'
EXEC add_BibleVerse @BibleId, 123018005, N'For before the harvest, when the bud has sprouted, and the ripening fruit appears, he will cut off the unproductive shoots with pruning knives; he will prune the tendrils.'
EXEC add_BibleVerse @BibleId, 123018006, N'They will all be left for the birds of the hills and the wild animals; the birds will eat them during the summer, and all the wild animals will eat them during the winter.'
EXEC add_BibleVerse @BibleId, 123018007, N'At that time tribute will be brought to the Lord who commands armies, by a people that are tall and smooth-skinned, a people that are feared far and wide, a nation strong and victorious, whose land rivers divide. The tribute will be brought to the place where the Lord who commands armies has chosen to reside, on Mount Zion.'
EXEC add_BibleVerse @BibleId, 123019001, N'Here is a message about Egypt: Look, the Lord rides on a swift-moving cloud and approaches Egypt. The idols of Egypt tremble before him; the Egyptians lose their courage.'
EXEC add_BibleVerse @BibleId, 123019002, N'“I will provoke civil strife in Egypt, brothers will fight with each other, as will neighbors, cities, and kingdoms.'
EXEC add_BibleVerse @BibleId, 123019003, N'The Egyptians will panic, and I will confuse their strategy. They will seek guidance from the idols and from the spirits of the dead, from the pits used to conjure up underworld spirits, and from the magicians.'
EXEC add_BibleVerse @BibleId, 123019004, N'I will hand Egypt over to a harsh master; a powerful king will rule over them,” says the sovereign master, the Lord who commands armies.'
EXEC add_BibleVerse @BibleId, 123019005, N'The water of the sea will be dried up, and the river will dry up and be empty.'
EXEC add_BibleVerse @BibleId, 123019006, N'The canals will stink; the streams of Egypt will trickle and then dry up; the bulrushes and reeds will decay,'
EXEC add_BibleVerse @BibleId, 123019007, N'along with the plants by the mouth of the river. All the cultivated land near the river will turn to dust and be blown away.'
EXEC add_BibleVerse @BibleId, 123019008, N'The fishermen will mourn and lament, all those who cast a fishhook into the river, and those who spread out a net on the water’s surface will grieve.'
EXEC add_BibleVerse @BibleId, 123019009, N'Those who make clothes from combed flax will be embarrassed; those who weave will turn pale.'
EXEC add_BibleVerse @BibleId, 123019010, N'Those who make cloth will be demoralized; all the hired workers will be depressed.'
EXEC add_BibleVerse @BibleId, 123019011, N'The officials of Zoan are nothing but fools; Pharaoh’s wise advisers give stupid advice. How dare you say to Pharaoh, “I am one of the sages, one well-versed in the writings of the ancient kings?”'
EXEC add_BibleVerse @BibleId, 123019012, N'But where, oh where, are your wise men? Let them tell you, let them find out what the Lord who commands armies has planned for Egypt.'
EXEC add_BibleVerse @BibleId, 123019013, N'The officials of Zoan are fools, the officials of Memphis are misled; the rulers of her tribes lead Egypt astray.'
EXEC add_BibleVerse @BibleId, 123019014, N'The Lord has made them undiscerning; they lead Egypt astray in all she does, so that she is like a drunk sliding around in his own vomit.'
EXEC add_BibleVerse @BibleId, 123019015, N'Egypt will not be able to do a thing, head or tail, shoots and stalk.'
EXEC add_BibleVerse @BibleId, 123019016, N'At that time the Egyptians will be like women. They will tremble and fear because the Lord who commands armies brandishes his fist against them.'
EXEC add_BibleVerse @BibleId, 123019017, N'The land of Judah will humiliate Egypt. Everyone who hears about Judah will be afraid because of what the Lord who commands armies is planning to do to them.'
EXEC add_BibleVerse @BibleId, 123019018, N'At that time five cities in the land of Egypt will speak the language of Canaan and swear allegiance to the Lord who commands armies. One will be called the City of the Sun.'
EXEC add_BibleVerse @BibleId, 123019019, N'At that time there will be an altar for the Lord in the middle of the land of Egypt, as well as a sacred pillar dedicated to the Lord at its border.'
EXEC add_BibleVerse @BibleId, 123019020, N'It will become a visual reminder in the land of Egypt of the Lord who commands armies. When they cry out to the Lord because of oppressors, he will send them a deliverer and defender who will rescue them.'
EXEC add_BibleVerse @BibleId, 123019021, N'The Lord will reveal himself to the Egyptians, and they will acknowledge the Lord’s authority at that time. They will present sacrifices and offerings; they will make vows to the Lord and fulfill them.'
EXEC add_BibleVerse @BibleId, 123019022, N'The Lord will strike Egypt, striking and then healing them. They will turn to the Lord and he will listen to their prayers and heal them.'
EXEC add_BibleVerse @BibleId, 123019023, N'At that time there will be a highway from Egypt to Assyria. The Assyrians will visit Egypt, and the Egyptians will visit Assyria. The Egyptians and Assyrians will worship together.'
EXEC add_BibleVerse @BibleId, 123019024, N'At that time Israel will be the third member of the group, along with Egypt and Assyria, and will be a recipient of blessing in the earth.'
EXEC add_BibleVerse @BibleId, 123019025, N'The Lord who commands armies will pronounce a blessing over the earth, saying, “Blessed be my people, Egypt, and the work of my hands, Assyria, and my special possession, Israel!”'
EXEC add_BibleVerse @BibleId, 123020001, N'The Lord revealed the following message during the year in which King Sargon of Assyria sent his commanding general to Ashdod, and he fought against it and captured it.'
EXEC add_BibleVerse @BibleId, 123020002, N'At that time the Lord announced through Isaiah son of Amoz: “Go, remove the sackcloth from your waist and take your sandals off your feet.” He did as instructed and walked around in undergarments and barefoot.'
EXEC add_BibleVerse @BibleId, 123020003, N'Later the Lord explained, “In the same way that my servant Isaiah has walked around in undergarments and barefoot for the past three years, as an object lesson and omen pertaining to Egypt and Cush,'
EXEC add_BibleVerse @BibleId, 123020004, N'so the king of Assyria will lead away the captives of Egypt and the exiles of Cush, both young and old. They will be in undergarments and barefoot, with the buttocks exposed; the Egyptians will be publicly humiliated.'
EXEC add_BibleVerse @BibleId, 123020005, N'Those who put their hope in Cush and took pride in Egypt will be afraid and embarrassed.'
EXEC add_BibleVerse @BibleId, 123020006, N'At that time those who live on this coast will say, ‘Look what has happened to our source of hope to whom we fled for help, expecting to be rescued from the king of Assyria! How can we escape now?’”'
EXEC add_BibleVerse @BibleId, 123021001, N'Here is a message about the Desert by the Sea: Like strong winds blowing in the south, one invades from the desert, from a land that is feared.'
EXEC add_BibleVerse @BibleId, 123021002, N'I have received a distressing message: “The deceiver deceives, the destroyer destroys. Attack, you Elamites! Lay siege, you Medes! I will put an end to all the groaning!”'
EXEC add_BibleVerse @BibleId, 123021003, N'For this reason my stomach churns; cramps overwhelm me like the contractions of a woman in labor. I am disturbed by what I hear, horrified by what I see.'
EXEC add_BibleVerse @BibleId, 123021004, N'My heart palpitates, I shake in fear; the twilight I desired has brought me terror.'
EXEC add_BibleVerse @BibleId, 123021005, N'Arrange the table, lay out the carpet, eat and drink! Get up, you officers, smear oil on the shields!'
EXEC add_BibleVerse @BibleId, 123021006, N'For this is what the sovereign master has told me: “Go, post a guard! He must report what he sees.'
EXEC add_BibleVerse @BibleId, 123021007, N'When he sees chariots, teams of horses, riders on donkeys, riders on camels, he must be alert, very alert.”'
EXEC add_BibleVerse @BibleId, 123021008, N'Then the guard cries out: “On the watchtower, O sovereign master, I stand all day long; at my post I am stationed every night.'
EXEC add_BibleVerse @BibleId, 123021009, N'Look what’s coming! A charioteer, a team of horses.” When questioned, he replies, “Babylon has fallen, fallen! All the idols of her gods lie shattered on the ground!”'
EXEC add_BibleVerse @BibleId, 123021010, N'O my downtrodden people, crushed like stalks on the threshing floor, what I have heard from the Lord who commands armies, the God of Israel, I have reported to you.'
EXEC add_BibleVerse @BibleId, 123021011, N'Here is a message about Dumah: Someone calls to me from Seir, “Watchman, what is left of the night? Watchman, what is left of the night?”'
EXEC add_BibleVerse @BibleId, 123021012, N'The watchman replies, “Morning is coming, but then night. If you want to ask, ask; come back again.”'
EXEC add_BibleVerse @BibleId, 123021013, N'Here is a message about Arabia: In the thicket of Arabia you spend the night, you Dedanite caravans.'
EXEC add_BibleVerse @BibleId, 123021014, N'Bring out some water for the thirsty. You who live in the land of Tema, bring some food for the fugitives.'
EXEC add_BibleVerse @BibleId, 123021015, N'For they flee from the swords – from the drawn sword and from the battle-ready bow and from the severity of the battle.'
EXEC add_BibleVerse @BibleId, 123021016, N'For this is what the sovereign master has told me: “Within exactly one year all the splendor of Kedar will come to an end.'
EXEC add_BibleVerse @BibleId, 123021017, N'Just a handful of archers, the warriors of Kedar, will be left.” Indeed, the Lord God of Israel has spoken.'
EXEC add_BibleVerse @BibleId, 123022001, N'Here is a message about the Valley of Vision: What is the reason that all of you go up to the rooftops?'
EXEC add_BibleVerse @BibleId, 123022002, N'The noisy city is full of raucous sounds; the town is filled with revelry. Your slain were not cut down by the sword; they did not die in battle.'
EXEC add_BibleVerse @BibleId, 123022003, N'All your leaders ran away together – they fled to a distant place; all your refugees were captured together – they were captured without a single arrow being shot.'
EXEC add_BibleVerse @BibleId, 123022004, N'So I say: “Don’t look at me! I am weeping bitterly. Don’t try to console me concerning the destruction of my defenseless people.”'
EXEC add_BibleVerse @BibleId, 123022005, N'For the sovereign master, the Lord who commands armies, has planned a day of panic, defeat, and confusion. In the Valley of Vision people shout and cry out to the hill.'
EXEC add_BibleVerse @BibleId, 123022006, N'The Elamites picked up the quiver, and came with chariots and horsemen; the men of Kir prepared the shield.'
EXEC add_BibleVerse @BibleId, 123022007, N'Your very best valleys were full of chariots; horsemen confidently took their positions at the gate.'
EXEC add_BibleVerse @BibleId, 123022008, N'They removed the defenses of Judah. At that time you looked for the weapons in the House of the Forest.'
EXEC add_BibleVerse @BibleId, 123022009, N'You saw the many breaks in the walls of the city of David; you stored up water in the lower pool.'
EXEC add_BibleVerse @BibleId, 123022010, N'You counted the houses in Jerusalem, and demolished houses so you could have material to reinforce the wall.'
EXEC add_BibleVerse @BibleId, 123022011, N'You made a reservoir between the two walls for the water of the old pool – but you did not trust in the one who made it; you did not depend on the one who formed it long ago!'
EXEC add_BibleVerse @BibleId, 123022012, N'At that time the sovereign master, the Lord who commands armies, called for weeping and mourning, for shaved heads and sackcloth.'
EXEC add_BibleVerse @BibleId, 123022013, N'But look, there is outright celebration! You say, “Kill the ox and slaughter the sheep, eat meat and drink wine. Eat and drink, for tomorrow we die!”'
EXEC add_BibleVerse @BibleId, 123022014, N'The Lord who commands armies told me this: “Certainly this sin will not be forgiven as long as you live,” says the sovereign master, the Lord who commands armies.'
EXEC add_BibleVerse @BibleId, 123022015, N'This is what the sovereign master, the Lord who commands armies, says: “Go visit this administrator, Shebna, who supervises the palace, and tell him:'
EXEC add_BibleVerse @BibleId, 123022016, N'‘What right do you have to be here? What relatives do you have buried here? Why do you chisel out a tomb for yourself here? He chisels out his burial site in an elevated place, he carves out his tomb on a cliff.'
EXEC add_BibleVerse @BibleId, 123022017, N'Look, the Lord will throw you far away, you mere man! He will wrap you up tightly.'
EXEC add_BibleVerse @BibleId, 123022018, N'He will wind you up tightly into a ball and throw you into a wide, open land. There you will die, and there with you will be your impressive chariots, which bring disgrace to the house of your master.'
EXEC add_BibleVerse @BibleId, 123022019, N'I will remove you from your office; you will be thrown down from your position.'
EXEC add_BibleVerse @BibleId, 123022020, N'“At that time I will summon my servant Eliakim, son of Hilkiah.'
EXEC add_BibleVerse @BibleId, 123022021, N'I will put your robe on him, tie your belt around him, and transfer your authority to him. He will become a protector of the residents of Jerusalem and of the people of Judah.'
EXEC add_BibleVerse @BibleId, 123022022, N'I will place the key to the house of David on his shoulder. When he opens the door, no one can close it; when he closes the door, no one can open it.'
EXEC add_BibleVerse @BibleId, 123022023, N'I will fasten him like a peg into a solid place; he will bring honor and respect to his father’s family.'
EXEC add_BibleVerse @BibleId, 123022024, N'His father’s family will gain increasing prominence because of him, including the offspring and the offshoots. All the small containers, including the bowls and all the jars will hang from this peg.’'
EXEC add_BibleVerse @BibleId, 123022025, N'“At that time,” says the Lord who commands armies, “the peg fastened into a solid place will come loose. It will be cut off and fall, and the load hanging on it will be cut off.” Indeed, the Lord has spoken.'
EXEC add_BibleVerse @BibleId, 123023001, N'Here is a message about Tyre: Wail, you large ships, for the port is too devastated to enter! From the land of Cyprus this news is announced to them.'
EXEC add_BibleVerse @BibleId, 123023002, N'Lament, you residents of the coast, you merchants of Sidon who travel over the sea, whose agents sail over'
EXEC add_BibleVerse @BibleId, 123023003, N'the deep waters! Grain from the Shihor region, crops grown near the Nile she receives; she is the trade center of the nations.'
EXEC add_BibleVerse @BibleId, 123023004, N'Be ashamed, O Sidon, for the sea says this, O fortress of the sea: “I have not gone into labor or given birth; I have not raised young men or brought up young women.”'
EXEC add_BibleVerse @BibleId, 123023005, N'When the news reaches Egypt, they will be shaken by what has happened to Tyre.'
EXEC add_BibleVerse @BibleId, 123023006, N'Travel to Tarshish! Wail, you residents of the coast!'
EXEC add_BibleVerse @BibleId, 123023007, N'Is this really your boisterous city whose origins are in the distant past, and whose feet led her to a distant land to reside?'
EXEC add_BibleVerse @BibleId, 123023008, N'Who planned this for royal Tyre, whose merchants are princes, whose traders are the dignitaries of the earth?'
EXEC add_BibleVerse @BibleId, 123023009, N'The Lord who commands armies planned it – to dishonor the pride that comes from all her beauty, to humiliate all the dignitaries of the earth.'
EXEC add_BibleVerse @BibleId, 123023010, N'Daughter Tarshish, travel back to your land, as one crosses the Nile; there is no longer any marketplace in Tyre.'
EXEC add_BibleVerse @BibleId, 123023011, N'The Lord stretched out his hand over the sea, he shook kingdoms; he gave the order to destroy Canaan’s fortresses.'
EXEC add_BibleVerse @BibleId, 123023012, N'He said, “You will no longer celebrate, oppressed virgin daughter Sidon! Get up, travel to Cyprus, but you will find no relief there.”'
EXEC add_BibleVerse @BibleId, 123023013, N'Look at the land of the Chaldeans, these people who have lost their identity! The Assyrians have made it a home for wild animals. They erected their siege towers, demolished its fortresses, and turned it into a heap of ruins.'
EXEC add_BibleVerse @BibleId, 123023014, N'Wail, you large ships, for your fortress is destroyed!'
EXEC add_BibleVerse @BibleId, 123023015, N'At that time Tyre will be forgotten for seventy years, the typical life span of a king. At the end of seventy years Tyre will try to attract attention again, like the prostitute in the popular song:'
EXEC add_BibleVerse @BibleId, 123023016, N'“Take the harp, go through the city, forgotten prostitute! Play it well, play lots of songs, so you’ll be noticed!”'
EXEC add_BibleVerse @BibleId, 123023017, N'At the end of seventy years the Lord will revive Tyre. She will start making money again by selling her services to all the earth’s kingdoms.'
EXEC add_BibleVerse @BibleId, 123023018, N'Her profits and earnings will be set apart for the Lord. They will not be stored up or accumulated, for her profits will be given to those who live in the Lord’s presence and will be used to purchase large quantities of food and beautiful clothes.'
EXEC add_BibleVerse @BibleId, 123024001, N'Look, the Lord is ready to devastate the earth and leave it in ruins; he will mar its surface and scatter its inhabitants.'
EXEC add_BibleVerse @BibleId, 123024002, N'Everyone will suffer – the priest as well as the people, the master as well as the servant, the elegant lady as well as the female attendant, the seller as well as the buyer, the borrower as well as the lender, the creditor as well as the debtor.'
EXEC add_BibleVerse @BibleId, 123024003, N'The earth will be completely devastated and thoroughly ransacked. For the Lord has decreed this judgment.'
EXEC add_BibleVerse @BibleId, 123024004, N'The earth dries up and withers, the world shrivels up and withers; the prominent people of the earth fade away.'
EXEC add_BibleVerse @BibleId, 123024005, N'The earth is defiled by its inhabitants, for they have violated laws, disregarded the regulation, and broken the permanent treaty.'
EXEC add_BibleVerse @BibleId, 123024006, N'So a treaty curse devours the earth; its inhabitants pay for their guilt. This is why the inhabitants of the earth disappear, and are reduced to just a handful of people.'
EXEC add_BibleVerse @BibleId, 123024007, N'The new wine dries up, the vines shrivel up, all those who like to celebrate groan.'
EXEC add_BibleVerse @BibleId, 123024008, N'The happy sound of the tambourines stops, the revelry of those who celebrate comes to a halt, the happy sound of the harp ceases.'
EXEC add_BibleVerse @BibleId, 123024009, N'They no longer sing and drink wine; the beer tastes bitter to those who drink it.'
EXEC add_BibleVerse @BibleId, 123024010, N'The ruined town is shattered; all of the houses are shut up tight.'
EXEC add_BibleVerse @BibleId, 123024011, N'They howl in the streets because of what happened to the wine; all joy turns to sorrow; celebrations disappear from the earth.'
EXEC add_BibleVerse @BibleId, 123024012, N'The city is left in ruins; the gate is reduced to rubble.'
EXEC add_BibleVerse @BibleId, 123024013, N'This is what will happen throughout the earth, among the nations. It will be like when they beat an olive tree, and just a few olives are left at the end of the harvest.'
EXEC add_BibleVerse @BibleId, 123024014, N'They lift their voices and shout joyfully; they praise the majesty of the Lord in the west.'
EXEC add_BibleVerse @BibleId, 123024015, N'So in the east extol the Lord, along the seacoasts extol the fame of the Lord God of Israel.'
EXEC add_BibleVerse @BibleId, 123024016, N'From the ends of the earth we hear songs – the Just One is majestic. But I say, “I’m wasting away! I’m wasting away! I’m doomed! Deceivers deceive, deceivers thoroughly deceive!”'
EXEC add_BibleVerse @BibleId, 123024017, N'Terror, pit, and snare are ready to overtake you inhabitants of the earth!'
EXEC add_BibleVerse @BibleId, 123024018, N'The one who runs away from the sound of the terror will fall into the pit; the one who climbs out of the pit, will be trapped by the snare. For the floodgates of the heavens are opened up and the foundations of the earth shake.'
EXEC add_BibleVerse @BibleId, 123024019, N'The earth is broken in pieces, the earth is ripped to shreds, the earth shakes violently.'
EXEC add_BibleVerse @BibleId, 123024020, N'The earth will stagger around like a drunk; it will sway back and forth like a hut in a windstorm. Its sin will weigh it down, and it will fall and never get up again.'
EXEC add_BibleVerse @BibleId, 123024021, N'At that time the Lord will punish the heavenly forces in the heavens and the earthly kings on the earth.'
EXEC add_BibleVerse @BibleId, 123024022, N'They will be imprisoned in a pit, locked up in a prison, and after staying there for a long time, they will be punished.'
EXEC add_BibleVerse @BibleId, 123024023, N'The full moon will be covered up, the bright sun will be darkened; for the Lord who commands armies will rule on Mount Zion in Jerusalem in the presence of his assembly, in majestic splendor.'
EXEC add_BibleVerse @BibleId, 123025001, N'O Lord, you are my God! I will exalt you in praise, I will extol your fame. For you have done extraordinary things, and executed plans made long ago exactly as you decreed.'
EXEC add_BibleVerse @BibleId, 123025002, N'Indeed, you have made the city into a heap of rubble, the fortified town into a heap of ruins; the fortress of foreigners is no longer a city, it will never be rebuilt.'
EXEC add_BibleVerse @BibleId, 123025003, N'So a strong nation will extol you; the towns of powerful nations will fear you.'
EXEC add_BibleVerse @BibleId, 123025004, N'For you are a protector for the poor, a protector for the needy in their distress, a shelter from the rainstorm, a shade from the heat. Though the breath of tyrants is like a winter rainstorm,'
EXEC add_BibleVerse @BibleId, 123025005, N'like heat in a dry land, you humble the boasting foreigners. Just as the shadow of a cloud causes the heat to subside, so he causes the song of tyrants to cease.'
EXEC add_BibleVerse @BibleId, 123025006, N'The Lord who commands armies will hold a banquet for all the nations on this mountain. At this banquet there will be plenty of meat and aged wine – tender meat and choicest wine.'
EXEC add_BibleVerse @BibleId, 123025007, N'On this mountain he will swallow up the shroud that is over all the peoples, the woven covering that is over all the nations;'
EXEC add_BibleVerse @BibleId, 123025008, N'he will swallow up death permanently. The sovereign Lord will wipe away the tears from every face, and remove his people’s disgrace from all the earth. Indeed, the Lord has announced it!'
EXEC add_BibleVerse @BibleId, 123025009, N'At that time they will say, “Look, here is our God! We waited for him and he delivered us. Here is the Lord! We waited for him. Let’s rejoice and celebrate his deliverance!”'
EXEC add_BibleVerse @BibleId, 123025010, N'For the Lord’s power will make this mountain secure. Moab will be trampled down where it stands, as a heap of straw is trampled down in a manure pile.'
EXEC add_BibleVerse @BibleId, 123025011, N'Moab will spread out its hands in the middle of it, just as a swimmer spreads his hands to swim; the Lord will bring down Moab’s pride as it spreads its hands.'
EXEC add_BibleVerse @BibleId, 123025012, N'The fortified city (along with the very tops of your walls) he will knock down, he will bring it down, he will throw it down to the dusty ground.'
EXEC add_BibleVerse @BibleId, 123026001, N'At that time this song will be sung in the land of Judah: “We have a strong city! The Lord’s deliverance, like walls and a rampart, makes it secure.'
EXEC add_BibleVerse @BibleId, 123026002, N'Open the gates so a righteous nation can enter – one that remains trustworthy.'
EXEC add_BibleVerse @BibleId, 123026003, N'You keep completely safe the people who maintain their faith, for they trust in you.'
EXEC add_BibleVerse @BibleId, 123026004, N'Trust in the Lord from this time forward, even in Yah, the Lord, an enduring protector!'
EXEC add_BibleVerse @BibleId, 123026005, N'Indeed, the Lord knocks down those who live in a high place, he brings down an elevated town; he brings it down to the ground, he throws it down to the dust.'
EXEC add_BibleVerse @BibleId, 123026006, N'It is trampled underfoot by the feet of the oppressed, by the soles of the poor.”'
EXEC add_BibleVerse @BibleId, 123026007, N'The way of the righteous is level, the path of the righteous that you make is straight.'
EXEC add_BibleVerse @BibleId, 123026008, N'Yes, as your judgments unfold, O Lord, we wait for you. We desire your fame and reputation to grow.'
EXEC add_BibleVerse @BibleId, 123026009, N'I look for you during the night, my spirit within me seeks you at dawn, for when your judgments come upon the earth, those who live in the world learn about justice.'
EXEC add_BibleVerse @BibleId, 123026010, N'If the wicked are shown mercy, they do not learn about justice. Even in a land where right is rewarded, they act unjustly; they do not see the Lord’s majesty revealed.'
EXEC add_BibleVerse @BibleId, 123026011, N'O Lord, you are ready to act, but they don’t even notice. They will see and be put to shame by your angry judgment against humankind, yes, fire will consume your enemies.'
EXEC add_BibleVerse @BibleId, 123026012, N'O Lord, you make us secure, for even all we have accomplished, you have done for us.'
EXEC add_BibleVerse @BibleId, 123026013, N'O Lord, our God, masters other than you have ruled us, but we praise your name alone.'
EXEC add_BibleVerse @BibleId, 123026014, N'The dead do not come back to life, the spirits of the dead do not rise. That is because you came in judgment and destroyed them, you wiped out all memory of them.'
EXEC add_BibleVerse @BibleId, 123026015, N'You have made the nation larger, O Lord, you have made the nation larger and revealed your splendor, you have extended all the borders of the land.'
EXEC add_BibleVerse @BibleId, 123026016, N'O Lord, in distress they looked for you; they uttered incantations because of your discipline.'
EXEC add_BibleVerse @BibleId, 123026017, N'As when a pregnant woman gets ready to deliver and strains and cries out because of her labor pains, so were we because of you, O Lord.'
EXEC add_BibleVerse @BibleId, 123026018, N'We were pregnant, we strained, we gave birth, as it were, to wind. We cannot produce deliverance on the earth; people to populate the world are not born.'
EXEC add_BibleVerse @BibleId, 123026019, N'Your dead will come back to life; your corpses will rise up. Wake up and shout joyfully, you who live in the ground! For you will grow like plants drenched with the morning dew, and the earth will bring forth its dead spirits.'
EXEC add_BibleVerse @BibleId, 123026020, N'Go, my people! Enter your inner rooms! Close your doors behind you! Hide for a little while, until his angry judgment is over!'
EXEC add_BibleVerse @BibleId, 123026021, N'For look, the Lord is coming out of the place where he lives, to punish the sin of those who live on the earth. The earth will display the blood shed on it; it will no longer cover up its slain.'
EXEC add_BibleVerse @BibleId, 123027001, N'At that time the Lord will punish with his destructive, great, and powerful sword Leviathan the fast-moving serpent, Leviathan the squirming serpent; he will kill the sea monster.'
EXEC add_BibleVerse @BibleId, 123027002, N'When that time comes, sing about a delightful vineyard!'
EXEC add_BibleVerse @BibleId, 123027003, N'I, the Lord, protect it; I water it regularly. I guard it night and day, so no one can harm it.'
EXEC add_BibleVerse @BibleId, 123027004, N'I am not angry. I wish I could confront some thorns and briers! Then I would march against them for battle; I would set them all on fire,'
EXEC add_BibleVerse @BibleId, 123027005, N'unless they became my subjects and made peace with me; let them make peace with me.'
EXEC add_BibleVerse @BibleId, 123027006, N'The time is coming when Jacob will take root; Israel will blossom and grow branches. The produce will fill the surface of the world.'
EXEC add_BibleVerse @BibleId, 123027007, N'Has the Lord struck down Israel like he did their oppressors? Has Israel been killed like their enemies?'
EXEC add_BibleVerse @BibleId, 123027008, N'When you summon her for divorce, you prosecute her; he drives her away with his strong wind in the day of the east wind.'
EXEC add_BibleVerse @BibleId, 123027009, N'So in this way Jacob’s sin will be forgiven, and this is how they will show they are finished sinning: They will make all the stones of the altars like crushed limestone, and the Asherah poles and the incense altars will no longer stand.'
EXEC add_BibleVerse @BibleId, 123027010, N'For the fortified city is left alone; it is a deserted settlement and abandoned like the desert. Calves graze there; they lie down there and eat its branches bare.'
EXEC add_BibleVerse @BibleId, 123027011, N'When its branches get brittle, they break; women come and use them for kindling. For these people lack understanding, therefore the one who made them has no compassion on them; the one who formed them has no mercy on them.'
EXEC add_BibleVerse @BibleId, 123027012, N'At that time the Lord will shake the tree, from the Euphrates River to the Stream of Egypt. Then you will be gathered up one by one, O Israelites.'
EXEC add_BibleVerse @BibleId, 123027013, N'At that time a large trumpet will be blown, and the ones lost in the land of Assyria will come, as well as the refugees in the land of Egypt. They will worship the Lord on the holy mountain in Jerusalem.'
EXEC add_BibleVerse @BibleId, 123028001, N'The splendid crown of Ephraim’s drunkards is doomed, the withering flower, its beautiful splendor, situated at the head of a rich valley, the crown of those overcome with wine.'
EXEC add_BibleVerse @BibleId, 123028002, N'Look, the sovereign master sends a strong, powerful one. With the force of a hailstorm or a destructive windstorm, with the might of a driving, torrential rainstorm, he will knock that crown to the ground with his hand.'
EXEC add_BibleVerse @BibleId, 123028003, N'The splendid crown of Ephraim’s drunkards will be trampled underfoot.'
EXEC add_BibleVerse @BibleId, 123028004, N'The withering flower, its beautiful splendor, situated at the head of a rich valley, will be like an early fig before harvest – as soon as someone notices it, he grabs it and swallows it.'
EXEC add_BibleVerse @BibleId, 123028005, N'At that time the Lord who commands armies will become a beautiful crown and a splendid diadem for the remnant of his people.'
EXEC add_BibleVerse @BibleId, 123028006, N'He will give discernment to the one who makes judicial decisions, and strength to those who defend the city from attackers.'
EXEC add_BibleVerse @BibleId, 123028007, N'Even these men stagger because of wine, they stumble around because of beer – priests and prophets stagger because of beer, they are confused because of wine, they stumble around because of beer; they stagger while seeing prophetic visions, they totter while making legal decisions.'
EXEC add_BibleVerse @BibleId, 123028008, N'Indeed, all the tables are covered with vomit; no place is untouched.'
EXEC add_BibleVerse @BibleId, 123028009, N'Who is the Lord trying to teach? To whom is he explaining a message? Those just weaned from milk! Those just taken from their mother’s breast!'
EXEC add_BibleVerse @BibleId, 123028010, N'Indeed, they will hear meaningless gibberish, senseless babbling, a syllable here, a syllable there.'
EXEC add_BibleVerse @BibleId, 123028011, N'For with mocking lips and a foreign tongue he will speak to these people.'
EXEC add_BibleVerse @BibleId, 123028012, N'In the past he said to them, “This is where security can be found. Provide security for the one who is exhausted! This is where rest can be found.” But they refused to listen.'
EXEC add_BibleVerse @BibleId, 123028013, N'So the Lord’s word to them will sound like meaningless gibberish, senseless babbling, a syllable here, a syllable there. As a result, they will fall on their backsides when they try to walk, and be injured, ensnared, and captured.'
EXEC add_BibleVerse @BibleId, 123028014, N'Therefore, listen to the Lord’s word, you who mock, you rulers of these people who reside in Jerusalem!'
EXEC add_BibleVerse @BibleId, 123028015, N'For you say, “We have made a treaty with death, with Sheol we have made an agreement. When the overwhelming judgment sweeps by it will not reach us. For we have made a lie our refuge, we have hidden ourselves in a deceitful word.”'
EXEC add_BibleVerse @BibleId, 123028016, N'Therefore, this is what the sovereign master, the Lord, says: “Look, I am laying a stone in Zion, an approved stone, set in place as a precious cornerstone for the foundation. The one who maintains his faith will not panic.'
EXEC add_BibleVerse @BibleId, 123028017, N'I will make justice the measuring line, fairness the plumb line; hail will sweep away the unreliable refuge, the floodwaters will overwhelm the hiding place.'
EXEC add_BibleVerse @BibleId, 123028018, N'Your treaty with death will be dissolved; your agreement with Sheol will not last. When the overwhelming judgment sweeps by, you will be overrun by it.'
EXEC add_BibleVerse @BibleId, 123028019, N'Whenever it sweeps by, it will overtake you; indeed, every morning it will sweep by, it will come through during the day and the night.” When this announcement is understood, it will cause nothing but terror.'
EXEC add_BibleVerse @BibleId, 123028020, N'For the bed is too short to stretch out on, and the blanket is too narrow to wrap around oneself.'
EXEC add_BibleVerse @BibleId, 123028021, N'For the Lord will rise up, as he did at Mount Perazim, he will rouse himself, as he did in the Valley of Gibeon, to accomplish his work, his peculiar work, to perform his task, his strange task.'
EXEC add_BibleVerse @BibleId, 123028022, N'So now, do not mock, or your chains will become heavier! For I have heard a message about decreed destruction, from the sovereign master, the Lord who commands armies, against the entire land.'
EXEC add_BibleVerse @BibleId, 123028023, N'Pay attention and listen to my message! Be attentive and listen to what I have to say!'
EXEC add_BibleVerse @BibleId, 123028024, N'Does a farmer just keep on plowing at planting time? Does he keep breaking up and harrowing his ground?'
EXEC add_BibleVerse @BibleId, 123028025, N'Once he has leveled its surface, does he not scatter the seed of the caraway plant, sow the seed of the cumin plant, and plant the wheat, barley, and grain in their designated places?'
EXEC add_BibleVerse @BibleId, 123028026, N'His God instructs him; he teaches him the principles of agriculture.'
EXEC add_BibleVerse @BibleId, 123028027, N'Certainly caraway seed is not threshed with a sledge, nor is the wheel of a cart rolled over cumin seed. Certainly caraway seed is beaten with a stick, and cumin seed with a flail.'
EXEC add_BibleVerse @BibleId, 123028028, N'Grain is crushed, though one certainly does not thresh it forever. The wheel of one’s wagon rolls over it, but his horses do not crush it.'
EXEC add_BibleVerse @BibleId, 123028029, N'This also comes from the Lord who commands armies, who gives supernatural guidance and imparts great wisdom.'
EXEC add_BibleVerse @BibleId, 123029001, N'Ariel is as good as dead – Ariel, the town David besieged! Keep observing your annual rituals, celebrate your festivals on schedule.'
EXEC add_BibleVerse @BibleId, 123029002, N'I will threaten Ariel, and she will mourn intensely and become like an altar hearth before me.'
EXEC add_BibleVerse @BibleId, 123029003, N'I will lay siege to you on all sides; I will besiege you with troops; I will raise siege works against you.'
EXEC add_BibleVerse @BibleId, 123029004, N'You will fall; while lying on the ground you will speak; from the dust where you lie, your words will be heard. Your voice will sound like a spirit speaking from the underworld; from the dust you will chirp as if muttering an incantation.'
EXEC add_BibleVerse @BibleId, 123029005, N'But the horde of invaders will be like fine dust, the horde of tyrants like chaff that is blown away. It will happen suddenly, in a flash.'
EXEC add_BibleVerse @BibleId, 123029006, N'Judgment will come from the Lord who commands armies, accompanied by thunder, earthquake, and a loud noise, by a strong gale, a windstorm, and a consuming flame of fire.'
EXEC add_BibleVerse @BibleId, 123029007, N'It will be like a dream, a night vision. There will be a horde from all the nations that fight against Ariel, those who attack her and her stronghold and besiege her.'
EXEC add_BibleVerse @BibleId, 123029008, N'It will be like a hungry man dreaming that he is eating, only to awaken and find that his stomach is empty. It will be like a thirsty man dreaming that he is drinking, only to awaken and find that he is still weak and his thirst unquenched. So it will be for the horde from all the nations that fight against Mount Zion.'
EXEC add_BibleVerse @BibleId, 123029009, N'You will be shocked and amazed! You are totally blind! They are drunk, but not because of wine; they stagger, but not because of beer.'
EXEC add_BibleVerse @BibleId, 123029010, N'For the Lord has poured out on you a strong urge to sleep deeply. He has shut your eyes (the prophets), and covered your heads (the seers).'
EXEC add_BibleVerse @BibleId, 123029011, N'To you this entire prophetic revelation is like words in a sealed scroll. When they hand it to one who can read and say, “Read this,” he responds, “I can’t, because it is sealed.”'
EXEC add_BibleVerse @BibleId, 123029012, N'Or when they hand the scroll to one who can’t read and say, “Read this,” he says, “I can’t read.”'
EXEC add_BibleVerse @BibleId, 123029013, N'The sovereign master says, “These people say they are loyal to me; they say wonderful things about me, but they are not really loyal to me. Their worship consists of nothing but man-made ritual.'
EXEC add_BibleVerse @BibleId, 123029014, N'Therefore I will again do an amazing thing for these people – an absolutely extraordinary deed. Wise men will have nothing to say, the sages will have no explanations.”'
EXEC add_BibleVerse @BibleId, 123029015, N'Those who try to hide their plans from the Lord are as good as dead, who do their work in secret and boast, “Who sees us? Who knows what we’re doing?”'
EXEC add_BibleVerse @BibleId, 123029016, N'Your thinking is perverse! Should the potter be regarded as clay? Should the thing made say about its maker, “He didn’t make me”? Or should the pottery say about the potter, “He doesn’t understand”?'
EXEC add_BibleVerse @BibleId, 123029017, N'In just a very short time Lebanon will turn into an orchard, and the orchard will be considered a forest.'
EXEC add_BibleVerse @BibleId, 123029018, N'At that time the deaf will be able to hear words read from a scroll, and the eyes of the blind will be able to see through deep darkness.'
EXEC add_BibleVerse @BibleId, 123029019, N'The downtrodden will again rejoice in the Lord; the poor among humankind will take delight in the Holy One of Israel.'
EXEC add_BibleVerse @BibleId, 123029020, N'For tyrants will disappear, those who taunt will vanish, and all those who love to do wrong will be eliminated –'
EXEC add_BibleVerse @BibleId, 123029021, N'those who bear false testimony against a person, who entrap the one who arbitrates at the city gate and deprive the innocent of justice by making false charges.'
EXEC add_BibleVerse @BibleId, 123029022, N'So this is what the Lord, the one who delivered Abraham, says to the family of Jacob: “Jacob will no longer be ashamed; their faces will no longer show their embarrassment.'
EXEC add_BibleVerse @BibleId, 123029023, N'For when they see their children, whom I will produce among them, they will honor my name. They will honor the Holy One of Jacob; they will respect the God of Israel.'
EXEC add_BibleVerse @BibleId, 123029024, N'Those who stray morally will gain understanding; those who complain will acquire insight.'
EXEC add_BibleVerse @BibleId, 123030001, N'“The rebellious children are as good as dead,” says the Lord, “those who make plans without consulting me, who form alliances without consulting my Spirit, and thereby compound their sin.'
EXEC add_BibleVerse @BibleId, 123030002, N'They travel down to Egypt without seeking my will, seeking Pharaoh’s protection, and looking for safety in Egypt’s protective shade.'
EXEC add_BibleVerse @BibleId, 123030003, N'But Pharaoh’s protection will bring you nothing but shame, and the safety of Egypt’s protective shade nothing but humiliation.'
EXEC add_BibleVerse @BibleId, 123030004, N'Though his officials are in Zoan and his messengers arrive at Hanes,'
EXEC add_BibleVerse @BibleId, 123030005, N'all will be put to shame because of a nation that cannot help them, who cannot give them aid or help, but only shame and disgrace.”'
EXEC add_BibleVerse @BibleId, 123030006, N'This is a message about the animals in the Negev: Through a land of distress and danger, inhabited by lionesses and roaring lions, by snakes and darting adders, they transport their wealth on the backs of donkeys, their riches on the humps of camels, to a nation that cannot help them.'
EXEC add_BibleVerse @BibleId, 123030007, N'Egypt is totally incapable of helping. For this reason I call her ‘Proud one who is silenced.’”'
EXEC add_BibleVerse @BibleId, 123030008, N'Now go, write it down on a tablet in their presence, inscribe it on a scroll, so that it might be preserved for a future time as an enduring witness.'
EXEC add_BibleVerse @BibleId, 123030009, N'For these are rebellious people – they are lying children, children unwilling to obey the Lord’s law.'
EXEC add_BibleVerse @BibleId, 123030010, N'They say to the visionaries, “See no more visions!” and to the seers, “Don’t relate messages to us about what is right! Tell us nice things, relate deceptive messages.'
EXEC add_BibleVerse @BibleId, 123030011, N'Turn aside from the way, stray off the path. Remove from our presence the Holy One of Israel.”'
EXEC add_BibleVerse @BibleId, 123030012, N'For this reason this is what the Holy One of Israel says: “You have rejected this message; you trust instead in your ability to oppress and trick, and rely on that kind of behavior.'
EXEC add_BibleVerse @BibleId, 123030013, N'So this sin will become your downfall. You will be like a high wall that bulges and cracks and is ready to collapse; it crumbles suddenly, in a flash.'
EXEC add_BibleVerse @BibleId, 123030014, N'It shatters in pieces like a clay jar, so shattered to bits that none of it can be salvaged. Among its fragments one cannot find a shard large enough to scoop a hot coal from a fire or to skim off water from a cistern.”'
EXEC add_BibleVerse @BibleId, 123030015, N'For this is what the master, the Lord, the Holy One of Israel says: “If you repented and patiently waited for me, you would be delivered; if you calmly trusted in me you would find strength, but you are unwilling.'
EXEC add_BibleVerse @BibleId, 123030016, N'You say, ‘No, we will flee on horses,’ so you will indeed flee. You say, ‘We will ride on fast horses,’ so your pursuers will be fast.'
EXEC add_BibleVerse @BibleId, 123030017, N'One thousand will scurry at the battle cry of one enemy soldier; at the battle cry of five enemy soldiers you will all run away, until the remaining few are as isolated as a flagpole on a mountaintop or a signal flag on a hill.”'
EXEC add_BibleVerse @BibleId, 123030018, N'For this reason the Lord is ready to show you mercy; he sits on his throne, ready to have compassion on you. Indeed, the Lord is a just God; all who wait for him in faith will be blessed.'
EXEC add_BibleVerse @BibleId, 123030019, N'For people will live in Zion; in Jerusalem you will weep no more. When he hears your cry of despair, he will indeed show you mercy; when he hears it, he will respond to you.'
EXEC add_BibleVerse @BibleId, 123030020, N'The sovereign master will give you distress to eat and suffering to drink; but your teachers will no longer be hidden; your eyes will see them.'
EXEC add_BibleVerse @BibleId, 123030021, N'You will hear a word spoken behind you, saying, “This is the correct way, walk in it,” whether you are heading to the right or the left.'
EXEC add_BibleVerse @BibleId, 123030022, N'You will desecrate your silver-plated idols and your gold-plated images. You will throw them away as if they were a menstrual rag, saying to them, “Get out!”'
EXEC add_BibleVerse @BibleId, 123030023, N'He will water the seed you plant in the ground, and the ground will produce crops in abundance. At that time your cattle will graze in wide pastures.'
EXEC add_BibleVerse @BibleId, 123030024, N'The oxen and donkeys used in plowing will eat seasoned feed winnowed with a shovel and pitchfork.'
EXEC add_BibleVerse @BibleId, 123030025, N'On every high mountain and every high hill there will be streams flowing with water, at the time of great slaughter when the fortified towers collapse.'
EXEC add_BibleVerse @BibleId, 123030026, N'The light of the full moon will be like the sun’s glare and the sun’s glare will be seven times brighter, like the light of seven days, when the Lord binds up his people’s fractured bones and heals their severe wound.'
EXEC add_BibleVerse @BibleId, 123030027, N'Look, the name of the Lord comes from a distant place in raging anger and awesome splendor. He speaks angrily and his word is like destructive fire.'
EXEC add_BibleVerse @BibleId, 123030028, N'His battle cry overwhelms like a flooding river that reaches one’s neck. He shakes the nations in a sieve that isolates the chaff; he puts a bit into the mouth of the nations and leads them to destruction.'
EXEC add_BibleVerse @BibleId, 123030029, N'You will sing as you do in the evening when you are celebrating a festival. You will be happy like one who plays a flute as he goes to the mountain of the Lord, the Rock who shelters Israel.'
EXEC add_BibleVerse @BibleId, 123030030, N'The Lord will give a mighty shout and intervene in power, with furious anger and flaming, destructive fire, with a driving rainstorm and hailstones.'
EXEC add_BibleVerse @BibleId, 123030031, N'Indeed, the Lord’s shout will shatter Assyria; he will beat them with a club.'
EXEC add_BibleVerse @BibleId, 123030032, N'Every blow from his punishing cudgel, with which the Lord will beat them, will be accompanied by music from the tambourine and harp, and he will attack them with his weapons.'
EXEC add_BibleVerse @BibleId, 123030033, N'For the burial place is already prepared; it has been made deep and wide for the king. The firewood is piled high on it. The Lord’s breath, like a stream flowing with brimstone, will ignite it.'
EXEC add_BibleVerse @BibleId, 123031001, N'Those who go down to Egypt for help are as good as dead, those who rely on war horses, and trust in Egypt’s many chariots and in their many, many horsemen. But they do not rely on the Holy One of Israel and do not seek help from the Lord.'
EXEC add_BibleVerse @BibleId, 123031002, N'Yet he too is wise and he will bring disaster; he does not retract his decree. He will attack the wicked nation, and the nation that helps those who commit sin.'
EXEC add_BibleVerse @BibleId, 123031003, N'The Egyptians are mere humans, not God; their horses are made of flesh, not spirit. The Lord will strike with his hand; the one who helps will stumble and the one being helped will fall. Together they will perish.'
EXEC add_BibleVerse @BibleId, 123031004, N'Indeed, this is what the Lord says to me: “The Lord will be like a growling lion, like a young lion growling over its prey. Though a whole group of shepherds gathers against it, it is not afraid of their shouts or intimidated by their yelling. In this same way the Lord who commands armies will descend to do battle on Mount Zion and on its hill.'
EXEC add_BibleVerse @BibleId, 123031005, N'Just as birds hover over a nest, so the Lord who commands armies will protect Jerusalem. He will protect and deliver it; as he passes over he will rescue it.'
EXEC add_BibleVerse @BibleId, 123031006, N'You Israelites! Return to the one against whom you have so blatantly rebelled!'
EXEC add_BibleVerse @BibleId, 123031007, N'For at that time everyone will get rid of the silver and gold idols your hands sinfully made.'
EXEC add_BibleVerse @BibleId, 123031008, N'Assyria will fall by a sword, but not one human-made; a sword not made by humankind will destroy them. They will run away from this sword and their young men will be forced to do hard labor.'
EXEC add_BibleVerse @BibleId, 123031009, N'They will surrender their stronghold because of fear; their officers will be afraid of the Lord’s battle flag.” This is what the Lord says – the one whose fire is in Zion, whose firepot is in Jerusalem.'
EXEC add_BibleVerse @BibleId, 123032001, N'Look, a king will promote fairness; officials will promote justice.'
EXEC add_BibleVerse @BibleId, 123032002, N'Each of them will be like a shelter from the wind and a refuge from a rainstorm; like streams of water in a dry region and like the shade of a large cliff in a parched land.'
EXEC add_BibleVerse @BibleId, 123032003, N'Eyes will no longer be blind and ears will be attentive.'
EXEC add_BibleVerse @BibleId, 123032004, N'The mind that acts rashly will possess discernment and the tongue that stutters will speak with ease and clarity.'
EXEC add_BibleVerse @BibleId, 123032005, N'A fool will no longer be called honorable; a deceiver will no longer be called principled.'
EXEC add_BibleVerse @BibleId, 123032006, N'For a fool speaks disgraceful things; his mind plans out sinful deeds. He commits godless deeds and says misleading things about the Lord; he gives the hungry nothing to satisfy their appetite and gives the thirsty nothing to drink.'
EXEC add_BibleVerse @BibleId, 123032007, N'A deceiver’s methods are evil; he dreams up evil plans to ruin the poor with lies, even when the needy are in the right.'
EXEC add_BibleVerse @BibleId, 123032008, N'An honorable man makes honorable plans; his honorable character gives him security.'
EXEC add_BibleVerse @BibleId, 123032009, N'You complacent women, get up and listen to me! You carefree daughters, pay attention to what I say!'
EXEC add_BibleVerse @BibleId, 123032010, N'In a year’s time you carefree ones will shake with fear, for the grape harvest will fail, and the fruit harvest will not arrive.'
EXEC add_BibleVerse @BibleId, 123032011, N'Tremble, you complacent ones! Shake with fear, you carefree ones! Strip off your clothes and expose yourselves – put sackcloth on your waist!'
EXEC add_BibleVerse @BibleId, 123032012, N'Mourn over the field, over the delightful fields and the fruitful vine!'
EXEC add_BibleVerse @BibleId, 123032013, N'Mourn over the land of my people, which is overgrown with thorns and briers, and over all the once-happy houses in the city filled with revelry.'
EXEC add_BibleVerse @BibleId, 123032014, N'For the fortress is neglected; the once-crowded city is abandoned. Hill and watchtower are permanently uninhabited. Wild donkeys love to go there, and flocks graze there.'
EXEC add_BibleVerse @BibleId, 123032015, N'This desolation will continue until new life is poured out on us from heaven. Then the desert will become an orchard and the orchard will be considered a forest.'
EXEC add_BibleVerse @BibleId, 123032016, N'Justice will settle down in the desert and fairness will live in the orchard.'
EXEC add_BibleVerse @BibleId, 123032017, N'Fairness will produce peace and result in lasting security.'
EXEC add_BibleVerse @BibleId, 123032018, N'My people will live in peaceful settlements, in secure homes, and in safe, quiet places.'
EXEC add_BibleVerse @BibleId, 123032019, N'Even if the forest is destroyed and the city is annihilated,'
EXEC add_BibleVerse @BibleId, 123032020, N'you will be blessed, you who plant seed by all the banks of the streams, you who let your ox and donkey graze.'
EXEC add_BibleVerse @BibleId, 123033001, N'The destroyer is as good as dead, you who have not been destroyed! The deceitful one is as good as dead, the one whom others have not deceived! When you are through destroying, you will be destroyed; when you finish deceiving, others will deceive you!'
EXEC add_BibleVerse @BibleId, 123033002, N'Lord, be merciful to us! We wait for you. Give us strength each morning! Deliver us when distress comes.'
EXEC add_BibleVerse @BibleId, 123033003, N'The nations run away when they hear a loud noise; the nations scatter when you spring into action!'
EXEC add_BibleVerse @BibleId, 123033004, N'Your plunder disappears as if locusts were eating it; they swarm over it like locusts!'
EXEC add_BibleVerse @BibleId, 123033005, N'The Lord is exalted, indeed, he lives in heaven; he fills Zion with justice and fairness.'
EXEC add_BibleVerse @BibleId, 123033006, N'He is your constant source of stability; he abundantly provides safety and great wisdom; he gives all this to those who fear him.'
EXEC add_BibleVerse @BibleId, 123033007, N'Look, ambassadors cry out in the streets; messengers sent to make peace weep bitterly.'
EXEC add_BibleVerse @BibleId, 123033008, N'Highways are empty, there are no travelers. Treaties are broken, witnesses are despised, human life is treated with disrespect.'
EXEC add_BibleVerse @BibleId, 123033009, N'The land dries up and withers away; the forest of Lebanon shrivels up and decays. Sharon is like the desert; Bashan and Carmel are parched.'
EXEC add_BibleVerse @BibleId, 123033010, N'“Now I will rise up,” says the Lord. “Now I will exalt myself; now I will magnify myself.'
EXEC add_BibleVerse @BibleId, 123033011, N'You conceive straw, you give birth to chaff; your breath is a fire that destroys you.'
EXEC add_BibleVerse @BibleId, 123033012, N'The nations will be burned to ashes; like thorn bushes that have been cut down, they will be set on fire.'
EXEC add_BibleVerse @BibleId, 123033013, N'You who are far away, listen to what I have done! You who are close by, recognize my strength!”'
EXEC add_BibleVerse @BibleId, 123033014, N'Sinners are afraid in Zion; panic grips the godless. They say, ‘Who among us can coexist with destructive fire? Who among us can coexist with unquenchable fire?’'
EXEC add_BibleVerse @BibleId, 123033015, N'The one who lives uprightly and speaks honestly; the one who refuses to profit from oppressive measures and rejects a bribe; the one who does not plot violent crimes and does not seek to harm others –'
EXEC add_BibleVerse @BibleId, 123033016, N'This is the person who will live in a secure place; he will find safety in the rocky, mountain strongholds; he will have food and a constant supply of water.'
EXEC add_BibleVerse @BibleId, 123033017, N'You will see a king in his splendor; you will see a wide land.'
EXEC add_BibleVerse @BibleId, 123033018, N'Your mind will recall the terror you experienced, and you will ask yourselves, “Where is the scribe? Where is the one who weighs the money? Where is the one who counts the towers?”'
EXEC add_BibleVerse @BibleId, 123033019, N'You will no longer see a defiant people whose language you do not comprehend, whose derisive speech you do not understand.'
EXEC add_BibleVerse @BibleId, 123033020, N'Look at Zion, the city where we hold religious festivals! You will see Jerusalem, a peaceful settlement, a tent that stays put; its stakes will never be pulled up; none of its ropes will snap in two.'
EXEC add_BibleVerse @BibleId, 123033021, N'Instead the Lord will rule there as our mighty king. Rivers and wide streams will flow through it; no war galley will enter; no large ships will sail through.'
EXEC add_BibleVerse @BibleId, 123033022, N'For the Lord, our ruler, the Lord, our commander, the Lord, our king – he will deliver us.'
EXEC add_BibleVerse @BibleId, 123033023, N'Though at this time your ropes are slack, the mast is not secured, and the sail is not unfurled, at that time you will divide up a great quantity of loot; even the lame will drag off plunder.'
EXEC add_BibleVerse @BibleId, 123033024, N'No resident of Zion will say, “I am ill”; the people who live there will have their sin forgiven.'
EXEC add_BibleVerse @BibleId, 123034001, N'Come near, you nations, and listen! Pay attention, you people! The earth and everything it contains must listen, the world and everything that lives in it.'
EXEC add_BibleVerse @BibleId, 123034002, N'For the Lord is angry at all the nations and furious with all their armies. He will annihilate them and slaughter them.'
EXEC add_BibleVerse @BibleId, 123034003, N'Their slain will be left unburied, their corpses will stink; the hills will soak up their blood.'
EXEC add_BibleVerse @BibleId, 123034004, N'All the stars in the sky will fade away, the sky will roll up like a scroll; all its stars will wither, like a leaf withers and falls from a vine or a fig withers and falls from a tree.'
EXEC add_BibleVerse @BibleId, 123034005, N'He says, “Indeed, my sword has slaughtered heavenly powers. Look, it now descends on Edom, on the people I will annihilate in judgment.”'
EXEC add_BibleVerse @BibleId, 123034006, N'The Lord’s sword is dripping with blood, it is covered with fat; it drips with the blood of young rams and goats and is covered with the fat of rams’ kidneys. For the Lord is holding a sacrifice in Bozrah, a bloody slaughter in the land of Edom.'
EXEC add_BibleVerse @BibleId, 123034007, N'Wild oxen will be slaughtered along with them, as well as strong bulls. Their land is drenched with blood, their soil is covered with fat.'
EXEC add_BibleVerse @BibleId, 123034008, N'For the Lord has planned a day of revenge, a time when he will repay Edom for her hostility toward Zion.'
EXEC add_BibleVerse @BibleId, 123034009, N'Edom’s streams will be turned into pitch and her soil into brimstone; her land will become burning pitch.'
EXEC add_BibleVerse @BibleId, 123034010, N'Night and day it will burn; its smoke will ascend continually. Generation after generation it will be a wasteland and no one will ever pass through it again.'
EXEC add_BibleVerse @BibleId, 123034011, N'Owls and wild animals will live there, all kinds of wild birds will settle in it. The Lord will stretch out over her the measuring line of ruin and the plumb line of destruction.'
EXEC add_BibleVerse @BibleId, 123034012, N'Her nobles will have nothing left to call a kingdom and all her officials will disappear.'
EXEC add_BibleVerse @BibleId, 123034013, N'Her fortresses will be overgrown with thorns; thickets and weeds will grow in her fortified cities. Jackals will settle there; ostriches will live there.'
EXEC add_BibleVerse @BibleId, 123034014, N'Wild animals and wild dogs will congregate there; wild goats will bleat to one another. Yes, nocturnal animals will rest there and make for themselves a nest.'
EXEC add_BibleVerse @BibleId, 123034015, N'Owls will make nests and lay eggs there; they will hatch them and protect them. Yes, hawks will gather there, each with its mate.'
EXEC add_BibleVerse @BibleId, 123034016, N'Carefully read the scroll of the Lord! Not one of these creatures will be missing, none will lack a mate. For the Lord has issued the decree, and his own spirit gathers them.'
EXEC add_BibleVerse @BibleId, 123034017, N'He assigns them their allotment; he measures out their assigned place. They will live there permanently; they will settle in it through successive generations.'
EXEC add_BibleVerse @BibleId, 123035001, N'Let the desert and dry region be happy; let the wilderness rejoice and bloom like a lily!'
EXEC add_BibleVerse @BibleId, 123035002, N'Let it richly bloom; let it rejoice and shout with delight! It is given the grandeur of Lebanon, the splendor of Carmel and Sharon. They will see the grandeur of the Lord, the splendor of our God.'
EXEC add_BibleVerse @BibleId, 123035003, N'Strengthen the hands that have gone limp, steady the knees that shake!'
EXEC add_BibleVerse @BibleId, 123035004, N'Tell those who panic, “Be strong! Do not fear! Look, your God comes to avenge! With divine retribution he comes to deliver you.”'
EXEC add_BibleVerse @BibleId, 123035005, N'Then blind eyes will open, deaf ears will hear.'
EXEC add_BibleVerse @BibleId, 123035006, N'Then the lame will leap like a deer, the mute tongue will shout for joy; for water will flow in the desert, streams in the wilderness.'
EXEC add_BibleVerse @BibleId, 123035007, N'The dry soil will become a pool of water, the parched ground springs of water. Where jackals once lived and sprawled out, grass, reeds, and papyrus will grow.'
EXEC add_BibleVerse @BibleId, 123035008, N'A thoroughfare will be there – it will be called the Way of Holiness. The unclean will not travel on it; it is reserved for those authorized to use it – fools will not stray into it.'
EXEC add_BibleVerse @BibleId, 123035009, N'No lions will be there, no ferocious wild animals will be on it – they will not be found there. Those delivered from bondage will travel on it,'
EXEC add_BibleVerse @BibleId, 123035010, N'those whom the Lord has ransomed will return that way. They will enter Zion with a happy shout. Unending joy will crown them, happiness and joy will overwhelm them; grief and suffering will disappear.'
EXEC add_BibleVerse @BibleId, 123036001, N'In the fourteenth year of King Hezekiah’s reign, King Sennacherib of Assyria marched up against all the fortified cities of Judah and captured them.'
EXEC add_BibleVerse @BibleId, 123036002, N'The king of Assyria sent his chief adviser from Lachish to King Hezekiah in Jerusalem, along with a large army. The chief adviser stood at the conduit of the upper pool which is located on the road to the field where they wash and dry cloth.'
EXEC add_BibleVerse @BibleId, 123036003, N'Eliakim son of Hilkiah, the palace supervisor, accompanied by Shebna the scribe and Joah son of Asaph, the secretary, went out to meet him.'
EXEC add_BibleVerse @BibleId, 123036004, N'The chief adviser said to them, “Tell Hezekiah: ‘This is what the great king, the king of Assyria, says: “What is your source of confidence?'
EXEC add_BibleVerse @BibleId, 123036005, N'Your claim to have a strategy and military strength is just empty talk. In whom are you trusting, that you would dare to rebel against me?'
EXEC add_BibleVerse @BibleId, 123036006, N'Look, you must be trusting in Egypt, that splintered reed staff. If someone leans on it for support, it punctures his hand and wounds him. That is what Pharaoh king of Egypt does to all who trust in him!'
EXEC add_BibleVerse @BibleId, 123036007, N'Perhaps you will tell me, ‘We are trusting in the Lord our God.’ But Hezekiah is the one who eliminated his high places and altars and then told the people of Judah and Jerusalem, ‘You must worship at this altar.’'
EXEC add_BibleVerse @BibleId, 123036008, N'Now make a deal with my master the king of Assyria, and I will give you two thousand horses, provided you can find enough riders for them.'
EXEC add_BibleVerse @BibleId, 123036009, N'Certainly you will not refuse one of my master’s minor officials and trust in Egypt for chariots and horsemen.'
EXEC add_BibleVerse @BibleId, 123036010, N'Furthermore it was by the command of the Lord that I marched up against this land to destroy it. The Lord told me, ‘March up against this land and destroy it!’”’”'
EXEC add_BibleVerse @BibleId, 123036011, N'Eliakim, Shebna, and Joah said to the chief adviser, “Speak to your servants in Aramaic, for we understand it. Don’t speak with us in the Judahite dialect in the hearing of the people who are on the wall.”'
EXEC add_BibleVerse @BibleId, 123036012, N'But the chief adviser said, “My master did not send me to speak these words only to your master and to you. His message is also for the men who sit on the wall, for they will eat their own excrement and drink their own urine along with you!”'
EXEC add_BibleVerse @BibleId, 123036013, N'The chief adviser then stood there and called out loudly in the Judahite dialect, “Listen to the message of the great king, the king of Assyria.'
EXEC add_BibleVerse @BibleId, 123036014, N'This is what the king says: ‘Don’t let Hezekiah mislead you, for he is not able to rescue you!'
EXEC add_BibleVerse @BibleId, 123036015, N'Don’t let Hezekiah talk you into trusting in the Lord by saying, “The Lord will certainly rescue us; this city will not be handed over to the king of Assyria.”'
EXEC add_BibleVerse @BibleId, 123036016, N'Don’t listen to Hezekiah!’ For this is what the king of Assyria says, ‘Send me a token of your submission and surrender to me. Then each of you may eat from his own vine and fig tree and drink water from his own cistern,'
EXEC add_BibleVerse @BibleId, 123036017, N'until I come and take you to a land just like your own – a land of grain and new wine, a land of bread and vineyards.'
EXEC add_BibleVerse @BibleId, 123036018, N'Hezekiah is misleading you when he says, “The Lord will rescue us.” Has any of the gods of the nations rescued his land from the power of the king of Assyria?'
EXEC add_BibleVerse @BibleId, 123036019, N'Where are the gods of Hamath and Arpad? Where are the gods of Sepharvaim? Indeed, did any gods rescue Samaria from my power?'
EXEC add_BibleVerse @BibleId, 123036020, N'Who among all the gods of these lands have rescued their lands from my power? So how can the Lord rescue Jerusalem from my power?’”'
EXEC add_BibleVerse @BibleId, 123036021, N'They were silent and did not respond, for the king had ordered, “Don’t respond to him.”'
EXEC add_BibleVerse @BibleId, 123036022, N'Eliakim son of Hilkiah, the palace supervisor, accompanied by Shebna the scribe and Joah son of Asaph, the secretary, went to Hezekiah with their clothes torn in grief and reported to him what the chief adviser had said.'
EXEC add_BibleVerse @BibleId, 123037001, N'When King Hezekiah heard this, he tore his clothes, put on sackcloth, and went to the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 123037002, N'Eliakim the palace supervisor, Shebna the scribe, and the leading priests, clothed in sackcloth, sent this message to the prophet Isaiah son of Amoz:'
EXEC add_BibleVerse @BibleId, 123037003, N'“This is what Hezekiah says: ‘This is a day of distress, insults, and humiliation, as when a baby is ready to leave the birth canal, but the mother lacks the strength to push it through.'
EXEC add_BibleVerse @BibleId, 123037004, N'Perhaps the Lord your God will hear all these things the chief adviser has spoken on behalf of his master, the king of Assyria, who sent him to taunt the living God. When the Lord your God hears, perhaps he will punish him for the things he has said. So pray for this remnant that remains.’”'
EXEC add_BibleVerse @BibleId, 123037005, N'When King Hezekiah’s servants came to Isaiah,'
EXEC add_BibleVerse @BibleId, 123037006, N'Isaiah said to them, “Tell your master this: ‘This is what the Lord says: “Don’t be afraid because of the things you have heard – these insults the king of Assyria’s servants have hurled against me.'
EXEC add_BibleVerse @BibleId, 123037007, N'Look, I will take control of his mind; he will receive a report and return to his own land. I will cut him down with a sword in his own land.”’”'
EXEC add_BibleVerse @BibleId, 123037008, N'When the chief adviser heard the king of Assyria had departed from Lachish, he left and went to Libnah, where the king was campaigning.'
EXEC add_BibleVerse @BibleId, 123037009, N'The king heard that King Tirhakah of Ethiopia was marching out to fight him. He again sent messengers to Hezekiah, ordering them:'
EXEC add_BibleVerse @BibleId, 123037010, N'“Tell King Hezekiah of Judah this: ‘Don’t let your God in whom you trust mislead you when he says, “Jerusalem will not be handed over to the king of Assyria.”'
EXEC add_BibleVerse @BibleId, 123037011, N'Certainly you have heard how the kings of Assyria have annihilated all lands. Do you really think you will be rescued?'
EXEC add_BibleVerse @BibleId, 123037012, N'Were the nations whom my predecessors destroyed – the nations of Gozan, Haran, Rezeph, and the people of Eden in Telassar – rescued by their gods?'
EXEC add_BibleVerse @BibleId, 123037013, N'Where are the king of Hamath, the king of Arpad, and the kings of Lair, Sepharvaim, Hena, and Ivvah?’”'
EXEC add_BibleVerse @BibleId, 123037014, N'Hezekiah took the letter from the messengers and read it. Then Hezekiah went up to the Lord’s temple and spread it out before the Lord.'
EXEC add_BibleVerse @BibleId, 123037015, N'Hezekiah prayed before the Lord:'
EXEC add_BibleVerse @BibleId, 123037016, N'“O Lord who commands armies, O God of Israel, who is enthroned on the cherubim! You alone are God over all the kingdoms of the earth. You made the sky and the earth.'
EXEC add_BibleVerse @BibleId, 123037017, N'Pay attention, Lord, and hear! Open your eyes, Lord, and observe! Listen to this entire message Sennacherib sent and how he taunts the living God!'
EXEC add_BibleVerse @BibleId, 123037018, N'It is true, Lord, that the kings of Assyria have destroyed all the nations and their lands.'
EXEC add_BibleVerse @BibleId, 123037019, N'They have burned the gods of the nations, for they are not really gods, but only the product of human hands manufactured from wood and stone. That is why the Assyrians could destroy them.'
EXEC add_BibleVerse @BibleId, 123037020, N'Now, O Lord our God, rescue us from his power, so all the kingdoms of the earth may know that you alone are the Lord.”'
EXEC add_BibleVerse @BibleId, 123037021, N'Isaiah son of Amoz sent this message to Hezekiah: “This is what the Lord God of Israel says: ‘Because you prayed to me concerning King Sennacherib of Assyria,'
EXEC add_BibleVerse @BibleId, 123037022, N'this is what the Lord says about him: “The virgin daughter Zion despises you – she makes fun of you; daughter Jerusalem shakes her head after you.'
EXEC add_BibleVerse @BibleId, 123037023, N'Whom have you taunted and hurled insults at? At whom have you shouted and looked so arrogantly? At the Holy One of Israel!'
EXEC add_BibleVerse @BibleId, 123037024, N'Through your messengers you taunted the sovereign master, ‘With my many chariots I climbed up the high mountains, the slopes of Lebanon. I cut down its tall cedars and its best evergreens. I invaded its most remote regions, its thickest woods.'
EXEC add_BibleVerse @BibleId, 123037025, N'I dug wells and drank water. With the soles of my feet I dried up all the rivers of Egypt.’'
EXEC add_BibleVerse @BibleId, 123037026, N'Certainly you must have heard! Long ago I worked it out, in ancient times I planned it, and now I am bringing it to pass. The plan is this: Fortified cities will crash into heaps of ruins.'
EXEC add_BibleVerse @BibleId, 123037027, N'Their residents are powerless; they are terrified and ashamed. They are as short-lived as plants in the field or green vegetation. They are as short-lived as grass on the rooftops when it is scorched by the east wind.'
EXEC add_BibleVerse @BibleId, 123037028, N'I know where you live and everything you do and how you rage against me.'
EXEC add_BibleVerse @BibleId, 123037029, N'Because you rage against me and the uproar you create has reached my ears, I will put my hook in your nose, and my bridle between your lips, and I will lead you back the way you came.”'
EXEC add_BibleVerse @BibleId, 123037030, N'“This will be your reminder that I have spoken the truth: This year you will eat what grows wild, and next year what grows on its own. But the year after that you will plant seed and harvest crops; you will plant vines and consume their produce.'
EXEC add_BibleVerse @BibleId, 123037031, N'Those who remain in Judah will take root in the ground and bear fruit.'
EXEC add_BibleVerse @BibleId, 123037032, N'“For a remnant will leave Jerusalem; survivors will come out of Mount Zion. The intense devotion of the Lord who commands armies will accomplish this.'
EXEC add_BibleVerse @BibleId, 123037033, N'So this is what the Lord says about the king of Assyria: ‘He will not enter this city, nor will he shoot an arrow here. He will not attack it with his shielded warriors, nor will he build siege works against it.'
EXEC add_BibleVerse @BibleId, 123037034, N'He will go back the way he came – he will not enter this city,’ says the Lord.'
EXEC add_BibleVerse @BibleId, 123037035, N'I will shield this city and rescue it for the sake of my reputation and because of my promise to David my servant.”’”'
EXEC add_BibleVerse @BibleId, 123037036, N'The Lord’s messenger went out and killed 185,000 troops in the Assyrian camp. When they got up early the next morning, there were all the corpses!'
EXEC add_BibleVerse @BibleId, 123037037, N'So King Sennacherib of Assyria broke camp and went on his way. He went home and stayed in Nineveh.'
EXEC add_BibleVerse @BibleId, 123037038, N'One day, as he was worshiping in the temple of his god Nisroch, his sons Adrammelech and Sharezer struck him down with the sword. They ran away to the land of Ararat; his son Esarhaddon replaced him as king.'
EXEC add_BibleVerse @BibleId, 123038001, N'In those days Hezekiah was stricken with a terminal illness. The prophet Isaiah son of Amoz visited him and told him, “This is what the Lord says, ‘Give instructions to your household, for you are about to die; you will not get well.’”'
EXEC add_BibleVerse @BibleId, 123038002, N'Hezekiah turned his face to the wall and prayed to the Lord,'
EXEC add_BibleVerse @BibleId, 123038003, N'“Please, Lord. Remember how I have served you faithfully and with wholehearted devotion, and how I have carried out your will.” Then Hezekiah wept bitterly.'
EXEC add_BibleVerse @BibleId, 123038004, N'The Lord told Isaiah,'
EXEC add_BibleVerse @BibleId, 123038005, N'“Go and tell Hezekiah: ‘This is what the Lord God of your ancestor David says: “I have heard your prayer; I have seen your tears. Look, I will add fifteen years to your life,'
EXEC add_BibleVerse @BibleId, 123038006, N'and rescue you and this city from the king of Assyria. I will shield this city.”’”'
EXEC add_BibleVerse @BibleId, 123038007, N'Isaiah replied, “This is your sign from the Lord confirming that the Lord will do what he has said:'
EXEC add_BibleVerse @BibleId, 123038008, N'Look, I will make the shadow go back ten steps on the stairs of Ahaz.” And then the shadow went back ten steps.'
EXEC add_BibleVerse @BibleId, 123038009, N'This is the prayer of King Hezekiah of Judah when he was sick and then recovered from his illness:'
EXEC add_BibleVerse @BibleId, 123038010, N'“I thought, ‘In the middle of my life I must walk through the gates of Sheol, I am deprived of the rest of my years.’'
EXEC add_BibleVerse @BibleId, 123038011, N'“I thought, ‘I will no longer see the Lord in the land of the living, I will no longer look on humankind with the inhabitants of the world.'
EXEC add_BibleVerse @BibleId, 123038012, N'My dwelling place is removed and taken away from me like a shepherd’s tent. I rolled up my life like a weaver rolls cloth; from the loom he cuts me off. You turn day into night and end my life.'
EXEC add_BibleVerse @BibleId, 123038013, N'I cry out until morning; like a lion he shatters all my bones; you turn day into night and end my life.'
EXEC add_BibleVerse @BibleId, 123038014, N'Like a swallow or a thrush I chirp, I coo like a dove; my eyes grow tired from looking up to the sky. O sovereign master, I am oppressed; help me!'
EXEC add_BibleVerse @BibleId, 123038015, N'What can I say? He has decreed and acted. I will walk slowly all my years because I am overcome with grief.'
EXEC add_BibleVerse @BibleId, 123038016, N'O sovereign master, your decrees can give men life; may years of life be restored to me. Restore my health and preserve my life.’'
EXEC add_BibleVerse @BibleId, 123038017, N'“Look, the grief I experienced was for my benefit. You delivered me from the pit of oblivion. For you removed all my sins from your sight.'
EXEC add_BibleVerse @BibleId, 123038018, N'Indeed Sheol does not give you thanks; death does not praise you. Those who descend into the pit do not anticipate your faithfulness.'
EXEC add_BibleVerse @BibleId, 123038019, N'The living person, the living person, he gives you thanks, as I do today. A father tells his sons about your faithfulness.'
EXEC add_BibleVerse @BibleId, 123038020, N'The Lord is about to deliver me, and we will celebrate with music for the rest of our lives in the Lord’s temple.”'
EXEC add_BibleVerse @BibleId, 123038021, N'Isaiah ordered, “Let them take a fig cake and apply it to the ulcerated sore and he will get well.”'
EXEC add_BibleVerse @BibleId, 123038022, N'Hezekiah said, “What is the confirming sign that I will go up to the Lord’s temple?”'
EXEC add_BibleVerse @BibleId, 123039001, N'At that time Merodach-Baladan son of Baladan, king of Babylon, sent letters and a gift to Hezekiah, for he heard that Hezekiah had been ill and had recovered.'
EXEC add_BibleVerse @BibleId, 123039002, N'Hezekiah welcomed them and showed them his storehouse with its silver, gold, spices, and high-quality olive oil, as well as his whole armory and everything in his treasuries. Hezekiah showed them everything in his palace and in his whole kingdom.'
EXEC add_BibleVerse @BibleId, 123039003, N'Isaiah the prophet visited King Hezekiah and asked him, “What did these men say? Where do they come from?” Hezekiah replied, “They come from the distant land of Babylon.”'
EXEC add_BibleVerse @BibleId, 123039004, N'Isaiah asked, “What have they seen in your palace?” Hezekiah replied, “They have seen everything in my palace. I showed them everything in my treasuries.”'
EXEC add_BibleVerse @BibleId, 123039005, N'Isaiah said to Hezekiah, “Listen to the word of the Lord who commands armies:'
EXEC add_BibleVerse @BibleId, 123039006, N'‘Look, a time is coming when everything in your palace and the things your ancestors have accumulated to this day will be carried away to Babylon; nothing will be left,’ says the Lord.'
EXEC add_BibleVerse @BibleId, 123039007, N'‘Some of your very own descendants whom you father will be taken away and will be made eunuchs in the palace of the king of Babylon.’”'
EXEC add_BibleVerse @BibleId, 123039008, N'Hezekiah said to Isaiah, “The Lord’s word which you have announced is appropriate.” Then he thought, “For there will be peace and stability during my lifetime.”'
EXEC add_BibleVerse @BibleId, 123040001, N'“Comfort, comfort my people,” says your God.'
EXEC add_BibleVerse @BibleId, 123040002, N'“Speak kindly to Jerusalem, and tell her that her time of warfare is over, that her punishment is completed. For the Lord has made her pay double for all her sins.”'
EXEC add_BibleVerse @BibleId, 123040003, N'A voice cries out, “In the wilderness clear a way for the Lord; construct in the desert a road for our God.'
EXEC add_BibleVerse @BibleId, 123040004, N'Every valley must be elevated, and every mountain and hill leveled. The rough terrain will become a level plain, the rugged landscape a wide valley.'
EXEC add_BibleVerse @BibleId, 123040005, N'The splendor of the Lord will be revealed, and all people will see it at the same time. For the Lord has decreed it.”'
EXEC add_BibleVerse @BibleId, 123040006, N'A voice says, “Cry out!” Another asks, “What should I cry out?” The first voice responds: “All people are like grass, and all their promises are like the flowers in the field.'
EXEC add_BibleVerse @BibleId, 123040007, N'The grass dries up, the flowers wither, when the wind sent by the Lord blows on them. Surely humanity is like grass.'
EXEC add_BibleVerse @BibleId, 123040008, N'The grass dries up, the flowers wither, but the decree of our God is forever reliable.”'
EXEC add_BibleVerse @BibleId, 123040009, N'Go up on a high mountain, O herald Zion! Shout out loudly, O herald Jerusalem! Shout, don’t be afraid! Say to the towns of Judah, “Here is your God!”'
EXEC add_BibleVerse @BibleId, 123040010, N'Look, the sovereign Lord comes as a victorious warrior; his military power establishes his rule. Look, his reward is with him; his prize goes before him.'
EXEC add_BibleVerse @BibleId, 123040011, N'Like a shepherd he tends his flock; he gathers up the lambs with his arm; he carries them close to his heart; he leads the ewes along.'
EXEC add_BibleVerse @BibleId, 123040012, N'Who has measured out the waters in the hollow of his hand, or carefully measured the sky, or carefully weighed the soil of the earth, or weighed the mountains in a balance, or the hills on scales?'
EXEC add_BibleVerse @BibleId, 123040013, N'Who comprehends the mind of the Lord, or gives him instruction as his counselor?'
EXEC add_BibleVerse @BibleId, 123040014, N'From whom does he receive directions? Who teaches him the correct way to do things, or imparts knowledge to him, or instructs him in skillful design?'
EXEC add_BibleVerse @BibleId, 123040015, N'Look, the nations are like a drop in a bucket; they are regarded as dust on the scales. He lifts the coastlands as if they were dust.'
EXEC add_BibleVerse @BibleId, 123040016, N'Not even Lebanon could supply enough firewood for a sacrifice; its wild animals would not provide enough burnt offerings.'
EXEC add_BibleVerse @BibleId, 123040017, N'All the nations are insignificant before him; they are regarded as absolutely nothing.'
EXEC add_BibleVerse @BibleId, 123040018, N'To whom can you compare God? To what image can you liken him?'
EXEC add_BibleVerse @BibleId, 123040019, N'A craftsman casts an idol; a metalsmith overlays it with gold and forges silver chains for it.'
EXEC add_BibleVerse @BibleId, 123040020, N'To make a contribution one selects wood that will not rot; he then seeks a skilled craftsman to make an idol that will not fall over.'
EXEC add_BibleVerse @BibleId, 123040021, N'Do you not know? Do you not hear? Has it not been told to you since the very beginning? Have you not understood from the time the earth’s foundations were made?'
EXEC add_BibleVerse @BibleId, 123040022, N'He is the one who sits on the earth’s horizon; its inhabitants are like grasshoppers before him. He is the one who stretches out the sky like a thin curtain, and spreads it out like a pitched tent.'
EXEC add_BibleVerse @BibleId, 123040023, N'He is the one who reduces rulers to nothing; he makes the earth’s leaders insignificant.'
EXEC add_BibleVerse @BibleId, 123040024, N'Indeed, they are barely planted; yes, they are barely sown; yes, they barely take root in the earth, and then he blows on them, causing them to dry up, and the wind carries them away like straw.'
EXEC add_BibleVerse @BibleId, 123040025, N'“To whom can you compare me? Whom do I resemble?” says the Holy One.'
EXEC add_BibleVerse @BibleId, 123040026, N'Look up at the sky! Who created all these heavenly lights? He is the one who leads out their ranks; he calls them all by name. Because of his absolute power and awesome strength, not one of them is missing.'
EXEC add_BibleVerse @BibleId, 123040027, N'Why do you say, Jacob, Why do you say, Israel, “The Lord is not aware of what is happening to me, My God is not concerned with my vindication”?'
EXEC add_BibleVerse @BibleId, 123040028, N'Do you not know? Have you not heard? The Lord is an eternal God, the creator of the whole earth. He does not get tired or weary; there is no limit to his wisdom.'
EXEC add_BibleVerse @BibleId, 123040029, N'He gives strength to those who are tired; to the ones who lack power, he gives renewed energy.'
EXEC add_BibleVerse @BibleId, 123040030, N'Even youths get tired and weary; even strong young men clumsily stumble.'
EXEC add_BibleVerse @BibleId, 123040031, N'But those who wait for the Lord’s help find renewed strength; they rise up as if they had eagles’ wings, they run without growing weary, they walk without getting tired.'
EXEC add_BibleVerse @BibleId, 123041001, N'“Listen to me in silence, you coastlands! Let the nations find renewed strength! Let them approach and then speak; let us come together for debate!'
EXEC add_BibleVerse @BibleId, 123041002, N'Who stirs up this one from the east? Who officially commissions him for service? He hands nations over to him, and enables him to subdue kings. He makes them like dust with his sword, like windblown straw with his bow.'
EXEC add_BibleVerse @BibleId, 123041003, N'He pursues them and passes by unharmed; he advances with great speed.'
EXEC add_BibleVerse @BibleId, 123041004, N'Who acts and carries out decrees? Who summons the successive generations from the beginning? I, the Lord, am present at the very beginning, and at the very end – I am the one.'
EXEC add_BibleVerse @BibleId, 123041005, N'The coastlands see and are afraid; the whole earth trembles; they approach and come.'
EXEC add_BibleVerse @BibleId, 123041006, N'They help one another; one says to the other, ‘Be strong!’'
EXEC add_BibleVerse @BibleId, 123041007, N'The craftsman encourages the metalsmith, the one who wields the hammer encourages the one who pounds on the anvil. He approves the quality of the welding, and nails it down so it won’t fall over.”'
EXEC add_BibleVerse @BibleId, 123041008, N'“You, my servant Israel, Jacob whom I have chosen, offspring of Abraham my friend,'
EXEC add_BibleVerse @BibleId, 123041009, N'you whom I am bringing back from the earth’s extremities, and have summoned from the remote regions – I told you, “You are my servant.” I have chosen you and not rejected you.'
EXEC add_BibleVerse @BibleId, 123041010, N'Don’t be afraid, for I am with you! Don’t be frightened, for I am your God! I strengthen you – yes, I help you – yes, I uphold you with my saving right hand!'
EXEC add_BibleVerse @BibleId, 123041011, N'Look, all who were angry at you will be ashamed and humiliated; your adversaries will be reduced to nothing and perish.'
EXEC add_BibleVerse @BibleId, 123041012, N'When you will look for your opponents, you will not find them; your enemies will be reduced to absolutely nothing.'
EXEC add_BibleVerse @BibleId, 123041013, N'For I am the Lord your God, the one who takes hold of your right hand, who says to you, ‘Don’t be afraid, I am helping you.’'
EXEC add_BibleVerse @BibleId, 123041014, N'Don’t be afraid, despised insignificant Jacob, men of Israel. I am helping you,” says the Lord, your protector, the Holy One of Israel.'
EXEC add_BibleVerse @BibleId, 123041015, N'“Look, I am making you like a sharp threshing sledge, new and double-edged. You will thresh the mountains and crush them; you will make the hills like straw.'
EXEC add_BibleVerse @BibleId, 123041016, N'You will winnow them and the wind will blow them away; the wind will scatter them. You will rejoice in the Lord; you will boast in the Holy One of Israel.'
EXEC add_BibleVerse @BibleId, 123041017, N'The oppressed and the poor look for water, but there is none; their tongues are parched from thirst. I, the Lord, will respond to their prayers; I, the God of Israel, will not abandon them.'
EXEC add_BibleVerse @BibleId, 123041018, N'I will make streams flow down the slopes and produce springs in the middle of the valleys. I will turn the desert into a pool of water and the arid land into springs.'
EXEC add_BibleVerse @BibleId, 123041019, N'I will make cedars, acacias, myrtles, and olive trees grow in the wilderness; I will make evergreens, firs, and cypresses grow together in the desert.'
EXEC add_BibleVerse @BibleId, 123041020, N'I will do this so people will observe and recognize, so they will pay attention and understand that the Lord’s power has accomplished this, and that the Holy One of Israel has brought it into being.”'
EXEC add_BibleVerse @BibleId, 123041021, N'“Present your argument,” says the Lord. “Produce your evidence,” says Jacob’s king.'
EXEC add_BibleVerse @BibleId, 123041022, N'“Let them produce evidence! Let them tell us what will happen! Tell us about your earlier predictive oracles, so we may examine them and see how they were fulfilled. Or decree for us some future events!'
EXEC add_BibleVerse @BibleId, 123041023, N'Predict how future events will turn out, so we might know you are gods. Yes, do something good or bad, so we might be frightened and in awe.'
EXEC add_BibleVerse @BibleId, 123041024, N'Look, you are nothing, and your accomplishments are nonexistent; the one who chooses to worship you is disgusting.'
EXEC add_BibleVerse @BibleId, 123041025, N'I have stirred up one out of the north and he advances, one from the eastern horizon who prays in my name. He steps on rulers as if they were clay, like a potter treading the clay.'
EXEC add_BibleVerse @BibleId, 123041026, N'Who decreed this from the beginning, so we could know? Who announced it ahead of time, so we could say, ‘He’s correct’? Indeed, none of them decreed it! Indeed, none of them announced it! Indeed, no one heard you say anything!'
EXEC add_BibleVerse @BibleId, 123041027, N'I first decreed to Zion, ‘Look, here’s what will happen!’ I sent a herald to Jerusalem.'
EXEC add_BibleVerse @BibleId, 123041028, N'I look, but there is no one, among them there is no one who serves as an adviser, that I might ask questions and receive answers.'
EXEC add_BibleVerse @BibleId, 123041029, N'Look, all of them are nothing, their accomplishments are nonexistent; their metal images lack any real substance.'
EXEC add_BibleVerse @BibleId, 123042001, N'“Here is my servant whom I support, my chosen one in whom I take pleasure. I have placed my spirit on him; he will make just decrees for the nations.'
EXEC add_BibleVerse @BibleId, 123042002, N'He will not cry out or shout; he will not publicize himself in the streets.'
EXEC add_BibleVerse @BibleId, 123042003, N'A crushed reed he will not break, a dim wick he will not extinguish; he will faithfully make just decrees.'
EXEC add_BibleVerse @BibleId, 123042004, N'He will not grow dim or be crushed before establishing justice on the earth; the coastlands will wait in anticipation for his decrees.”'
EXEC add_BibleVerse @BibleId, 123042005, N'This is what the true God, the Lord, says – the one who created the sky and stretched it out, the one who fashioned the earth and everything that lives on it, the one who gives breath to the people on it, and life to those who live on it:'
EXEC add_BibleVerse @BibleId, 123042006, N'“I, the Lord, officially commission you; I take hold of your hand. I protect you and make you a covenant mediator for people, and a light to the nations,'
EXEC add_BibleVerse @BibleId, 123042007, N'to open blind eyes, to release prisoners from dungeons, those who live in darkness from prisons.'
EXEC add_BibleVerse @BibleId, 123042008, N'I am the Lord! That is my name! I will not share my glory with anyone else, or the praise due me with idols.'
EXEC add_BibleVerse @BibleId, 123042009, N'Look, my earlier predictive oracles have come to pass; now I announce new events. Before they begin to occur, I reveal them to you.”'
EXEC add_BibleVerse @BibleId, 123042010, N'Sing to the Lord a brand new song! Praise him from the horizon of the earth, you who go down to the sea, and everything that lives in it, you coastlands and those who live there!'
EXEC add_BibleVerse @BibleId, 123042011, N'Let the desert and its cities shout out, the towns where the nomads of Kedar live! Let the residents of Sela shout joyfully; let them shout loudly from the mountaintops.'
EXEC add_BibleVerse @BibleId, 123042012, N'Let them give the Lord the honor he deserves; let them praise his deeds in the coastlands.'
EXEC add_BibleVerse @BibleId, 123042013, N'The Lord emerges like a hero, like a warrior he inspires himself for battle; he shouts, yes, he yells, he shows his enemies his power.'
EXEC add_BibleVerse @BibleId, 123042014, N'“I have been inactive for a long time; I kept quiet and held back. Like a woman in labor I groan; I pant and gasp.'
EXEC add_BibleVerse @BibleId, 123042015, N'I will make the trees on the mountains and hills wither up; I will dry up all their vegetation. I will turn streams into islands, and dry up pools of water.'
EXEC add_BibleVerse @BibleId, 123042016, N'I will lead the blind along an unfamiliar way; I will guide them down paths they have never traveled. I will turn the darkness in front of them into light, and level out the rough ground. This is what I will do for them. I will not abandon them.'
EXEC add_BibleVerse @BibleId, 123042017, N'Those who trust in idols will turn back and be utterly humiliated, those who say to metal images, ‘You are our gods.’”'
EXEC add_BibleVerse @BibleId, 123042018, N'“Listen, you deaf ones! Take notice, you blind ones!'
EXEC add_BibleVerse @BibleId, 123042019, N'My servant is truly blind, my messenger is truly deaf. My covenant partner, the servant of the Lord, is truly blind.'
EXEC add_BibleVerse @BibleId, 123042020, N'You see many things, but don’t comprehend; their ears are open, but do not hear.”'
EXEC add_BibleVerse @BibleId, 123042021, N'The Lord wanted to exhibit his justice by magnifying his law and displaying it.'
EXEC add_BibleVerse @BibleId, 123042022, N'But these people are looted and plundered; all of them are trapped in pits and held captive in prisons. They were carried away as loot with no one to rescue them; they were carried away as plunder, and no one says, “Bring that back!”'
EXEC add_BibleVerse @BibleId, 123042023, N'Who among you will pay attention to this? Who will listen attentively in the future?'
EXEC add_BibleVerse @BibleId, 123042024, N'Who handed Jacob over to the robber? Who handed Israel over to the looters? Was it not the Lord, against whom we sinned? They refused to follow his commands; they disobeyed his law.'
EXEC add_BibleVerse @BibleId, 123042025, N'So he poured out his fierce anger on them, along with the devastation of war. Its flames encircled them, but they did not realize it; it burned against them, but they did notice.'
EXEC add_BibleVerse @BibleId, 123043001, N'Now, this is what the Lord says, the one who created you, O Jacob, and formed you, O Israel: “Don’t be afraid, for I will protect you. I call you by name, you are mine.'
EXEC add_BibleVerse @BibleId, 123043002, N'When you pass through the waters, I am with you; when you pass through the streams, they will not overwhelm you. When you walk through the fire, you will not be burned; the flames will not harm you.'
EXEC add_BibleVerse @BibleId, 123043003, N'For I am the Lord your God, the Holy One of Israel, your deliverer. I have handed over Egypt as a ransom price, Ethiopia and Seba in place of you.'
EXEC add_BibleVerse @BibleId, 123043004, N'Since you are precious and special in my sight, and I love you, I will hand over people in place of you, nations in place of your life.'
EXEC add_BibleVerse @BibleId, 123043005, N'Don’t be afraid, for I am with you. From the east I will bring your descendants; from the west I will gather you.'
EXEC add_BibleVerse @BibleId, 123043006, N'I will say to the north, ‘Hand them over!’ and to the south, ‘Don’t hold any back!’ Bring my sons from distant lands, and my daughters from the remote regions of the earth,'
EXEC add_BibleVerse @BibleId, 123043007, N'everyone who belongs to me, whom I created for my glory, whom I formed – yes, whom I made!'
EXEC add_BibleVerse @BibleId, 123043008, N'Bring out the people who are blind, even though they have eyes, those who are deaf, even though they have ears!'
EXEC add_BibleVerse @BibleId, 123043009, N'All nations gather together, the peoples assemble. Who among them announced this? Who predicted earlier events for us? Let them produce their witnesses to testify they were right; let them listen and affirm, ‘It is true.’'
EXEC add_BibleVerse @BibleId, 123043010, N'You are my witnesses,” says the Lord, “my servant whom I have chosen, so that you may consider and believe in me, and understand that I am he. No god was formed before me, and none will outlive me.'
EXEC add_BibleVerse @BibleId, 123043011, N'I, I am the Lord, and there is no deliverer besides me.'
EXEC add_BibleVerse @BibleId, 123043012, N'I decreed and delivered and proclaimed, and there was no other god among you. You are my witnesses,” says the Lord, “that I am God.'
EXEC add_BibleVerse @BibleId, 123043013, N'From this day forward I am he; no one can deliver from my power; I will act, and who can prevent it?”'
EXEC add_BibleVerse @BibleId, 123043014, N'This is what the LORD says, your protector, the Holy One of Israel: “For your sake I send to Babylon and make them all fugitives, turning the Babylonians'' joyful shouts into mourning songs.'
EXEC add_BibleVerse @BibleId, 123043015, N'I am the LORD, your Holy One, the one who created Israel, your king.”'
EXEC add_BibleVerse @BibleId, 123043016, N'This is what the LORD says, the one who made a road through the sea, a pathway through the surging waters,'
EXEC add_BibleVerse @BibleId, 123043017, N'the one who led chariots and horses to destruction, together with a mighty army. They fell down, never to rise again; they were extinguished, put out like a burning wick:'
EXEC add_BibleVerse @BibleId, 123043018, N'“Don''t remember these earlier events; don''t recall these former events.'
EXEC add_BibleVerse @BibleId, 123043019, N'“Look, I am about to do something new. Now it begins to happen! Do you not recognize it? Yes, I will make a road in the desert and paths in the wilderness.'
EXEC add_BibleVerse @BibleId, 123043020, N'The wild animals of the desert honor me, the jackals and ostriches, because I put water in the desert and streams in the wilderness, to quench the thirst of my chosen people,'
EXEC add_BibleVerse @BibleId, 123043021, N'the people whom I formed for myself, so they might praise me.”'
EXEC add_BibleVerse @BibleId, 123043022, N'“But you did not call for me, O Jacob; you did not long for me, O Israel.'
EXEC add_BibleVerse @BibleId, 123043023, N'You did not bring me lambs for your burnt offerings; you did not honor me with your sacrifices. I did not burden you with offerings; I did not make you weary by demanding incense.'
EXEC add_BibleVerse @BibleId, 123043024, N'You did not buy me aromatic reeds; you did not present to me the fat of your sacrifices. Yet you burdened me with your sins; you made me weary with your evil deeds.'
EXEC add_BibleVerse @BibleId, 123043025, N'I, I am the one who blots out your rebellious deeds for my sake; your sins I do not remember.'
EXEC add_BibleVerse @BibleId, 123043026, N'Remind me of what happened! Let''s debate! You, prove to me that you are right!'
EXEC add_BibleVerse @BibleId, 123043027, N'The father of your nation sinned; your spokesmen rebelled against me.'
EXEC add_BibleVerse @BibleId, 123043028, N'So I defiled your holy princes, and handed Jacob over to destruction, and subjected Israel to humiliating abuse.”'
EXEC add_BibleVerse @BibleId, 123044001, N'“Now, listen, Jacob my servant, Israel whom I have chosen!”'
EXEC add_BibleVerse @BibleId, 123044002, N'This is what the Lord, the one who made you, says – the one who formed you in the womb and helps you: “Don’t be afraid, my servant Jacob, Jeshurun, whom I have chosen!'
EXEC add_BibleVerse @BibleId, 123044003, N'For I will pour water on the parched ground and cause streams to flow on the dry land. I will pour my spirit on your offspring and my blessing on your children.'
EXEC add_BibleVerse @BibleId, 123044004, N'They will sprout up like a tree in the grass, like poplars beside channels of water.'
EXEC add_BibleVerse @BibleId, 123044005, N'One will say, ‘I belong to the Lord,’ and another will use the name ‘Jacob.’ One will write on his hand, ‘The Lord’s,’ and use the name ‘Israel.’”'
EXEC add_BibleVerse @BibleId, 123044006, N'This is what the Lord, Israel’s king, says, their protector, the Lord who commands armies: “I am the first and I am the last, there is no God but me.'
EXEC add_BibleVerse @BibleId, 123044007, N'Who is like me? Let him make his claim! Let him announce it and explain it to me – since I established an ancient people – let them announce future events!'
EXEC add_BibleVerse @BibleId, 123044008, N'Don’t panic! Don’t be afraid! Did I not tell you beforehand and decree it? You are my witnesses! Is there any God but me? There is no other sheltering rock; I know of none.'
EXEC add_BibleVerse @BibleId, 123044009, N'All who form idols are nothing; the things in which they delight are worthless. Their witnesses cannot see; they recognize nothing, so they are put to shame.'
EXEC add_BibleVerse @BibleId, 123044010, N'Who forms a god and casts an idol that will prove worthless?'
EXEC add_BibleVerse @BibleId, 123044011, N'Look, all his associates will be put to shame; the craftsmen are mere humans. Let them all assemble and take their stand! They will panic and be put to shame.'
EXEC add_BibleVerse @BibleId, 123044012, N'A blacksmith works with his tool and forges metal over the coals. He forms it with hammers; he makes it with his strong arm. He gets hungry and loses his energy; he drinks no water and gets tired.'
EXEC add_BibleVerse @BibleId, 123044013, N'A carpenter takes measurements; he marks out an outline of its form; he scrapes it with chisels, and marks it with a compass. He patterns it after the human form, like a well-built human being, and puts it in a shrine.'
EXEC add_BibleVerse @BibleId, 123044014, N'He cuts down cedars and acquires a cypress or an oak. He gets trees from the forest; he plants a cedar and the rain makes it grow.'
EXEC add_BibleVerse @BibleId, 123044015, N'A man uses it to make a fire; he takes some of it and warms himself. Yes, he kindles a fire and bakes bread. Then he makes a god and worships it; he makes an idol and bows down to it.'
EXEC add_BibleVerse @BibleId, 123044016, N'Half of it he burns in the fire – over that half he cooks meat; he roasts a meal and fills himself. Yes, he warms himself and says, ‘Ah! I am warm as I look at the fire.’'
EXEC add_BibleVerse @BibleId, 123044017, N'With the rest of it he makes a god, his idol; he bows down to it and worships it. He prays to it, saying, ‘Rescue me, for you are my god!’'
EXEC add_BibleVerse @BibleId, 123044018, N'They do not comprehend or understand, for their eyes are blind and cannot see; their minds do not discern.'
EXEC add_BibleVerse @BibleId, 123044019, N'No one thinks to himself, nor do they comprehend or understand and say to themselves: ‘I burned half of it in the fire – yes, I baked bread over the coals; I roasted meat and ate it. With the rest of it should I make a disgusting idol? Should I bow down to dry wood?’'
EXEC add_BibleVerse @BibleId, 123044020, N'He feeds on ashes; his deceived mind misleads him. He cannot rescue himself, nor does he say, ‘Is this not a false god I hold in my right hand?’'
EXEC add_BibleVerse @BibleId, 123044021, N'Remember these things, O Jacob, O Israel, for you are my servant. I formed you to be my servant; O Israel, I will not forget you!'
EXEC add_BibleVerse @BibleId, 123044022, N'I remove the guilt of your rebellious deeds as if they were a cloud, the guilt of your sins as if they were a cloud. Come back to me, for I protect you.”'
EXEC add_BibleVerse @BibleId, 123044023, N'Shout for joy, O sky, for the Lord intervenes; shout out, you subterranean regions of the earth. O mountains, give a joyful shout; you too, O forest and all your trees! For the Lord protects Jacob; he reveals his splendor through Israel.'
EXEC add_BibleVerse @BibleId, 123044024, N'This is what the Lord, your protector, says, the one who formed you in the womb: “I am the Lord, who made everything, who alone stretched out the sky, who fashioned the earth all by myself,'
EXEC add_BibleVerse @BibleId, 123044025, N'who frustrates the omens of the empty talkers and humiliates the omen readers, who overturns the counsel of the wise men and makes their advice seem foolish,'
EXEC add_BibleVerse @BibleId, 123044026, N'who fulfills the oracles of his prophetic servants and brings to pass the announcements of his messengers, who says about Jerusalem, ‘She will be inhabited,’ and about the towns of Judah, ‘They will be rebuilt, her ruins I will raise up,’'
EXEC add_BibleVerse @BibleId, 123044027, N'who says to the deep sea, ‘Be dry! I will dry up your sea currents,’'
EXEC add_BibleVerse @BibleId, 123044028, N'who commissions Cyrus, the one I appointed as shepherd to carry out all my wishes and to decree concerning Jerusalem, ‘She will be rebuilt,’ and concerning the temple, ‘It will be reconstructed.’”'
EXEC add_BibleVerse @BibleId, 123045001, N'This is what the Lord says to his chosen one, to Cyrus, whose right hand I hold in order to subdue nations before him, and disarm kings, to open doors before him, so gates remain unclosed:'
EXEC add_BibleVerse @BibleId, 123045002, N'“I will go before you and level mountains. Bronze doors I will shatter and iron bars I will hack through.'
EXEC add_BibleVerse @BibleId, 123045003, N'I will give you hidden treasures, riches stashed away in secret places, so you may recognize that I am the Lord, the one who calls you by name, the God of Israel.'
EXEC add_BibleVerse @BibleId, 123045004, N'For the sake of my servant Jacob, Israel, my chosen one, I call you by name and give you a title of respect, even though you do not recognize me.'
EXEC add_BibleVerse @BibleId, 123045005, N'I am the Lord, I have no peer, there is no God but me. I arm you for battle, even though you do not recognize me.'
EXEC add_BibleVerse @BibleId, 123045006, N'I do this so people will recognize from east to west that there is no God but me; I am the Lord, I have no peer.'
EXEC add_BibleVerse @BibleId, 123045007, N'I am the one who forms light and creates darkness; the one who brings about peace and creates calamity. I am the Lord, who accomplishes all these things.'
EXEC add_BibleVerse @BibleId, 123045008, N'O sky, rain down from above! Let the clouds send down showers of deliverance! Let the earth absorb it so salvation may grow, and deliverance may sprout up along with it. I, the Lord, create it.'
EXEC add_BibleVerse @BibleId, 123045009, N'One who argues with his creator is in grave danger, one who is like a mere shard among the other shards on the ground! The clay should not say to the potter, “What in the world are you doing? Your work lacks skill!”'
EXEC add_BibleVerse @BibleId, 123045010, N'Danger awaits one who says to his father, “What in the world are you fathering?” and to his mother, “What in the world are you bringing forth?”'
EXEC add_BibleVerse @BibleId, 123045011, N'This is what the Lord says, the Holy One of Israel, the one who formed him, concerning things to come: “How dare you question me about my children! How dare you tell me what to do with the work of my own hands!'
EXEC add_BibleVerse @BibleId, 123045012, N'I made the earth, I created the people who live on it. It was me – my hands stretched out the sky, I give orders to all the heavenly lights.'
EXEC add_BibleVerse @BibleId, 123045013, N'It is me – I stir him up and commission him; I will make all his ways level. He will rebuild my city; he will send my exiled people home, but not for a price or a bribe,” says the Lord who commands armies.'
EXEC add_BibleVerse @BibleId, 123045014, N'This is what the Lord says: “The profit of Egypt and the revenue of Ethiopia, along with the Sabeans, those tall men, will be brought to you and become yours. They will walk behind you, coming along in chains. They will bow down to you and pray to you: ‘Truly God is with you; he has no peer; there is no other God!’”'
EXEC add_BibleVerse @BibleId, 123045015, N'Yes, you are a God who keeps hidden, O God of Israel, deliverer!'
EXEC add_BibleVerse @BibleId, 123045016, N'They will all be ashamed and embarrassed; those who fashion idols will all be humiliated.'
EXEC add_BibleVerse @BibleId, 123045017, N'Israel will be delivered once and for all by the Lord; you will never again be ashamed or humiliated.'
EXEC add_BibleVerse @BibleId, 123045018, N'For this is what the Lord says, the one who created the sky – he is the true God, the one who formed the earth and made it; he established it, he did not create it without order, he formed it to be inhabited – “I am the Lord, I have no peer.'
EXEC add_BibleVerse @BibleId, 123045019, N'I have not spoken in secret, in some hidden place. I did not tell Jacob’s descendants, ‘Seek me in vain!’ I am the Lord, the one who speaks honestly, who makes reliable announcements.'
EXEC add_BibleVerse @BibleId, 123045020, N'Gather together and come! Approach together, you refugees from the nations! Those who carry wooden idols know nothing, those who pray to a god that cannot deliver.'
EXEC add_BibleVerse @BibleId, 123045021, N'Tell me! Present the evidence! Let them consult with one another! Who predicted this in the past? Who announced it beforehand? Was it not I, the Lord? I have no peer, there is no God but me, a God who vindicates and delivers; there is none but me.'
EXEC add_BibleVerse @BibleId, 123045022, N'Turn to me so you can be delivered, all you who live in the earth’s remote regions! For I am God, and I have no peer.'
EXEC add_BibleVerse @BibleId, 123045023, N'I solemnly make this oath – what I say is true and reliable: ‘Surely every knee will bow to me, every tongue will solemnly affirm;'
EXEC add_BibleVerse @BibleId, 123045024, N'they will say about me, “Yes, the Lord is a powerful deliverer.”’” All who are angry at him will cower before him.'
EXEC add_BibleVerse @BibleId, 123045025, N'All the descendants of Israel will be vindicated by the Lord and will boast in him.'
EXEC add_BibleVerse @BibleId, 123046001, N'Bel kneels down, Nebo bends low. Their images weigh down animals and beasts. Your heavy images are burdensome to tired animals.'
EXEC add_BibleVerse @BibleId, 123046002, N'Together they bend low and kneel down; they are unable to rescue the images; they themselves head off into captivity.'
EXEC add_BibleVerse @BibleId, 123046003, N'“Listen to me, O family of Jacob, all you who are left from the family of Israel, you who have been carried from birth, you who have been supported from the time you left the womb.'
EXEC add_BibleVerse @BibleId, 123046004, N'Even when you are old, I will take care of you, even when you have gray hair, I will carry you. I made you and I will support you; I will carry you and rescue you.'
EXEC add_BibleVerse @BibleId, 123046005, N'To whom can you compare and liken me? Tell me whom you think I resemble, so we can be compared!'
EXEC add_BibleVerse @BibleId, 123046006, N'Those who empty out gold from a purse and weigh out silver on the scale hire a metalsmith, who makes it into a god. They then bow down and worship it.'
EXEC add_BibleVerse @BibleId, 123046007, N'They put it on their shoulder and carry it; they put it in its place and it just stands there; it does not move from its place. Even when someone cries out to it, it does not reply; it does not deliver him from his distress.'
EXEC add_BibleVerse @BibleId, 123046008, N'Remember this, so you can be brave! Think about it, you rebels!'
EXEC add_BibleVerse @BibleId, 123046009, N'Remember what I accomplished in antiquity! Truly I am God, I have no peer; I am God, and there is none like me,'
EXEC add_BibleVerse @BibleId, 123046010, N'who announces the end from the beginning and reveals beforehand what has not yet occurred, who says, ‘My plan will be realized, I will accomplish what I desire,’'
EXEC add_BibleVerse @BibleId, 123046011, N'who summons an eagle from the east, from a distant land, one who carries out my plan. Yes, I have decreed, yes, I will bring it to pass; I have formulated a plan, yes, I will carry it out.'
EXEC add_BibleVerse @BibleId, 123046012, N'Listen to me, you stubborn people, you who distance yourself from doing what is right.'
EXEC add_BibleVerse @BibleId, 123046013, N'I am bringing my deliverance near, it is not far away; I am bringing my salvation near, it does not wait. I will save Zion; I will adorn Israel with my splendor.”'
EXEC add_BibleVerse @BibleId, 123047001, N'“Fall down! Sit in the dirt, O virgin daughter Babylon! Sit on the ground, not on a throne, O daughter of the Babylonians! Indeed, you will no longer be called delicate and pampered.'
EXEC add_BibleVerse @BibleId, 123047002, N'Pick up millstones and grind flour! Remove your veil, strip off your skirt, expose your legs, cross the streams!'
EXEC add_BibleVerse @BibleId, 123047003, N'Let your private parts be exposed! Your genitals will be on display! I will get revenge; I will not have pity on anyone,”'
EXEC add_BibleVerse @BibleId, 123047004, N'says our protector – the Lord who commands armies is his name, the Holy One of Israel.'
EXEC add_BibleVerse @BibleId, 123047005, N'“Sit silently! Go to a hiding place, O daughter of the Babylonians! Indeed, you will no longer be called ‘Queen of kingdoms.’'
EXEC add_BibleVerse @BibleId, 123047006, N'I was angry at my people; I defiled my special possession and handed them over to you. You showed them no mercy; you even placed a very heavy burden on old people.'
EXEC add_BibleVerse @BibleId, 123047007, N'You said, ‘I will rule forever as permanent queen!’ You did not think about these things; you did not consider how it would turn out.'
EXEC add_BibleVerse @BibleId, 123047008, N'So now, listen to this, O one who lives so lavishly, who lives securely, who says to herself, ‘I am unique! No one can compare to me! I will never have to live as a widow; I will never lose my children.’'
EXEC add_BibleVerse @BibleId, 123047009, N'Both of these will come upon you suddenly, in one day! You will lose your children and be widowed. You will be overwhelmed by these tragedies, despite your many incantations and your numerous amulets.'
EXEC add_BibleVerse @BibleId, 123047010, N'You were complacent in your evil deeds; you thought, ‘No one sees me.’ Your self-professed wisdom and knowledge lead you astray, when you say, ‘I am unique! No one can compare to me!’'
EXEC add_BibleVerse @BibleId, 123047011, N'Disaster will overtake you; you will not know how to charm it away. Destruction will fall on you; you will not be able to appease it. Calamity will strike you suddenly, before you recognize it.'
EXEC add_BibleVerse @BibleId, 123047012, N'Persist in trusting your amulets and your many incantations, which you have faithfully recited since your youth! Maybe you will be successful – maybe you will scare away disaster.'
EXEC add_BibleVerse @BibleId, 123047013, N'You are tired out from listening to so much advice. Let them take their stand – the ones who see omens in the sky, who gaze at the stars, who make monthly predictions – let them rescue you from the disaster that is about to overtake you!'
EXEC add_BibleVerse @BibleId, 123047014, N'Look, they are like straw, which the fire burns up; they cannot rescue themselves from the heat of the flames. There are no coals to warm them, no firelight to enjoy.'
EXEC add_BibleVerse @BibleId, 123047015, N'They will disappoint you, those you have so faithfully dealt with since your youth. Each strays off in his own direction, leaving no one to rescue you.”'
EXEC add_BibleVerse @BibleId, 123048001, N'Listen to this, O family of Jacob, you who are called by the name ‘Israel,’ and are descended from Judah, who take oaths in the name of the Lord, and invoke the God of Israel – but not in an honest and just manner.'
EXEC add_BibleVerse @BibleId, 123048002, N'Indeed, they live in the holy city; they trust in the God of Israel, whose name is the Lord who commands armies.'
EXEC add_BibleVerse @BibleId, 123048003, N'“I announced events beforehand, I issued the decrees and made the predictions; suddenly I acted and they came to pass.'
EXEC add_BibleVerse @BibleId, 123048004, N'I did this because I know how stubborn you are. Your neck muscles are like iron and your forehead like bronze.'
EXEC add_BibleVerse @BibleId, 123048005, N'I announced them to you beforehand; before they happened, I predicted them for you, so you could never say, ‘My image did these things, my idol, my cast image, decreed them.’'
EXEC add_BibleVerse @BibleId, 123048006, N'You have heard; now look at all the evidence! Will you not admit that what I say is true? From this point on I am announcing to you new events that are previously unrevealed and you do not know about.'
EXEC add_BibleVerse @BibleId, 123048007, N'Now they come into being, not in the past; before today you did not hear about them, so you could not say, ‘Yes, I know about them.’'
EXEC add_BibleVerse @BibleId, 123048008, N'You did not hear, you do not know, you were not told beforehand. For I know that you are very deceitful; you were labeled a rebel from birth.'
EXEC add_BibleVerse @BibleId, 123048009, N'For the sake of my reputation I hold back my anger; for the sake of my prestige I restrain myself from destroying you.'
EXEC add_BibleVerse @BibleId, 123048010, N'Look, I have refined you, but not as silver; I have purified you in the furnace of misery.'
EXEC add_BibleVerse @BibleId, 123048011, N'For my sake alone I will act, for how can I allow my name to be defiled? I will not share my glory with anyone else!'
EXEC add_BibleVerse @BibleId, 123048012, N'Listen to me, O Jacob, Israel, whom I summoned! I am the one; I am present at the very beginning and at the very end.'
EXEC add_BibleVerse @BibleId, 123048013, N'Yes, my hand founded the earth; my right hand spread out the sky. I summon them; they stand together.'
EXEC add_BibleVerse @BibleId, 123048014, N'All of you, gather together and listen! Who among them announced these things? The Lord’s ally will carry out his desire against Babylon; he will exert his power against the Babylonians.'
EXEC add_BibleVerse @BibleId, 123048015, N'I, I have spoken – yes, I have summoned him; I lead him and he will succeed.'
EXEC add_BibleVerse @BibleId, 123048016, N'Approach me! Listen to this! From the very first I have not spoken in secret; when it happens, I am there.” So now, the sovereign Lord has sent me, accompanied by his spirit.'
EXEC add_BibleVerse @BibleId, 123048017, N'This is what the Lord, your protector, says, the Holy One of Israel: “I am the Lord your God, who teaches you how to succeed, who leads you in the way you should go.'
EXEC add_BibleVerse @BibleId, 123048018, N'If only you had obeyed my commandments, prosperity would have flowed to you like a river, deliverance would have come to you like the waves of the sea.'
EXEC add_BibleVerse @BibleId, 123048019, N'Your descendants would have been as numerous as sand, and your children like its granules. Their name would not have been cut off and eliminated from my presence.'
EXEC add_BibleVerse @BibleId, 123048020, N'Leave Babylon! Flee from the Babylonians! Announce it with a shout of joy! Make this known! Proclaim it throughout the earth! Say, ‘The Lord protects his servant Jacob.'
EXEC add_BibleVerse @BibleId, 123048021, N'They do not thirst as he leads them through dry regions; he makes water flow out of a rock for them; he splits open a rock and water flows out.’'
EXEC add_BibleVerse @BibleId, 123048022, N'There will be no prosperity for the wicked,” says the Lord.'
EXEC add_BibleVerse @BibleId, 123049001, N'Listen to me, you coastlands! Pay attention, you people who live far away! The Lord summoned me from birth; he commissioned me when my mother brought me into the world.'
EXEC add_BibleVerse @BibleId, 123049002, N'He made my mouth like a sharp sword, he hid me in the hollow of his hand; he made me like a sharpened arrow, he hid me in his quiver.'
EXEC add_BibleVerse @BibleId, 123049003, N'He said to me, “You are my servant, Israel, through whom I will reveal my splendor.”'
EXEC add_BibleVerse @BibleId, 123049004, N'But I thought, “I have worked in vain; I have expended my energy for absolutely nothing.” But the Lord will vindicate me; my God will reward me.'
EXEC add_BibleVerse @BibleId, 123049005, N'So now the Lord says, the one who formed me from birth to be his servant – he did this to restore Jacob to himself, so that Israel might be gathered to him; and I will be honored in the Lord’s sight, for my God is my source of strength –'
EXEC add_BibleVerse @BibleId, 123049006, N'he says, “Is it too insignificant a task for you to be my servant, to reestablish the tribes of Jacob, and restore the remnant of Israel? I will make you a light to the nations, so you can bring my deliverance to the remote regions of the earth.”'
EXEC add_BibleVerse @BibleId, 123049007, N'This is what the Lord, the protector of Israel, their Holy One, says to the one who is despised and rejected by nations, a servant of rulers: “Kings will see and rise in respect, princes will bow down, because of the faithful Lord, the Holy One of Israel who has chosen you.”'
EXEC add_BibleVerse @BibleId, 123049008, N'This is what the Lord says: “At the time I decide to show my favor, I will respond to you; in the day of deliverance I will help you; I will protect you and make you a covenant mediator for people, to rebuild the land and to reassign the desolate property.'
EXEC add_BibleVerse @BibleId, 123049009, N'You will say to the prisoners, ‘Come out,’ and to those who are in dark dungeons, ‘Emerge.’ They will graze beside the roads; on all the slopes they will find pasture.'
EXEC add_BibleVerse @BibleId, 123049010, N'They will not be hungry or thirsty; the sun’s oppressive heat will not beat down on them, for one who has compassion on them will guide them; he will lead them to springs of water.'
EXEC add_BibleVerse @BibleId, 123049011, N'I will make all my mountains into a road; I will construct my roadways.”'
EXEC add_BibleVerse @BibleId, 123049012, N'Look, they come from far away! Look, some come from the north and west, and others from the land of Sinim!'
EXEC add_BibleVerse @BibleId, 123049013, N'Shout for joy, O sky! Rejoice, O earth! Let the mountains give a joyful shout! For the Lord consoles his people and shows compassion to the oppressed.'
EXEC add_BibleVerse @BibleId, 123049014, N'“Zion said, ‘The Lord has abandoned me, the sovereign master has forgotten me.’'
EXEC add_BibleVerse @BibleId, 123049015, N'Can a woman forget her baby who nurses at her breast? Can she withhold compassion from the child she has borne? Even if mothers were to forget, I could never forget you!'
EXEC add_BibleVerse @BibleId, 123049016, N'Look, I have inscribed your name on my palms; your walls are constantly before me.'
EXEC add_BibleVerse @BibleId, 123049017, N'Your children hurry back, while those who destroyed and devastated you depart.'
EXEC add_BibleVerse @BibleId, 123049018, N'Look all around you! All of them gather to you. As surely as I live,” says the Lord, “you will certainly wear all of them like jewelry; you will put them on as if you were a bride.'
EXEC add_BibleVerse @BibleId, 123049019, N'Yes, your land lies in ruins; it is desolate and devastated. But now you will be too small to hold your residents, and those who devoured you will be far away.'
EXEC add_BibleVerse @BibleId, 123049020, N'Yet the children born during your time of bereavement will say within your hearing, ‘This place is too cramped for us, make room for us so we can live here.’'
EXEC add_BibleVerse @BibleId, 123049021, N'Then you will think to yourself, ‘Who bore these children for me? I was bereaved and barren, dismissed and divorced. Who raised these children? Look, I was left all alone; where did these children come from?’”'
EXEC add_BibleVerse @BibleId, 123049022, N'This is what the sovereign Lord says: “Look I will raise my hand to the nations; I will raise my signal flag to the peoples. They will bring your sons in their arms and carry your daughters on their shoulders.'
EXEC add_BibleVerse @BibleId, 123049023, N'Kings will be your children’s guardians; their princesses will nurse your children. With their faces to the ground they will bow down to you and they will lick the dirt on your feet. Then you will recognize that I am the Lord; those who wait patiently for me are not put to shame.'
EXEC add_BibleVerse @BibleId, 123049024, N'Can spoils be taken from a warrior, or captives be rescued from a conqueror?'
EXEC add_BibleVerse @BibleId, 123049025, N'Indeed,” says the Lord, “captives will be taken from a warrior; spoils will be rescued from a conqueror. I will oppose your adversary and I will rescue your children.'
EXEC add_BibleVerse @BibleId, 123049026, N'I will make your oppressors eat their own flesh; they will get drunk on their own blood, as if it were wine. Then all humankind will recognize that I am the Lord, your deliverer, your protector, the powerful ruler of Jacob.”'
EXEC add_BibleVerse @BibleId, 123050001, N'This is what the Lord says: “Where is your mother’s divorce certificate by which I divorced her? Or to which of my creditors did I sell you? Look, you were sold because of your sins; because of your rebellious acts I divorced your mother.'
EXEC add_BibleVerse @BibleId, 123050002, N'Why does no one challenge me when I come? Why does no one respond when I call? Is my hand too weak to deliver you? Do I lack the power to rescue you? Look, with a mere shout I can dry up the sea; I can turn streams into a desert, so the fish rot away and die from lack of water.'
EXEC add_BibleVerse @BibleId, 123050003, N'I can clothe the sky in darkness; I can cover it with sackcloth.”'
EXEC add_BibleVerse @BibleId, 123050004, N'The sovereign Lord has given me the capacity to be his spokesman, so that I know how to help the weary. He wakes me up every morning; he makes me alert so I can listen attentively as disciples do.'
EXEC add_BibleVerse @BibleId, 123050005, N'The sovereign Lord has spoken to me clearly; I have not rebelled, I have not turned back.'
EXEC add_BibleVerse @BibleId, 123050006, N'I offered my back to those who attacked, my jaws to those who tore out my beard; I did not hide my face from insults and spitting.'
EXEC add_BibleVerse @BibleId, 123050007, N'But the sovereign Lord helps me, so I am not humiliated. For that reason I am steadfastly resolved; I know I will not be put to shame.'
EXEC add_BibleVerse @BibleId, 123050008, N'The one who vindicates me is close by. Who dares to argue with me? Let us confront each other! Who is my accuser? Let him challenge me!'
EXEC add_BibleVerse @BibleId, 123050009, N'Look, the sovereign Lord helps me. Who dares to condemn me? Look, all of them will wear out like clothes; a moth will eat away at them.'
EXEC add_BibleVerse @BibleId, 123050010, N'Who among you fears the Lord? Who obeys his servant? Whoever walks in deep darkness, without light, should trust in the name of the Lord and rely on his God.'
EXEC add_BibleVerse @BibleId, 123050011, N'Look, all of you who start a fire and who equip yourselves with flaming arrows, walk in the light of the fire you started and among the flaming arrows you ignited! This is what you will receive from me: you will lie down in a place of pain.'
EXEC add_BibleVerse @BibleId, 123051001, N'“Listen to me, you who pursue godliness, who seek the Lord! Look at the rock from which you were chiseled, at the quarry from which you were dug!'
EXEC add_BibleVerse @BibleId, 123051002, N'Look at Abraham, your father, and Sarah, who gave you birth. When I summoned him, he was a lone individual, but I blessed him and gave him numerous descendants.'
EXEC add_BibleVerse @BibleId, 123051003, N'Certainly the Lord will console Zion; he will console all her ruins. He will make her wilderness like Eden, her desert like the Garden of the Lord. Happiness and joy will be restored to her, thanksgiving and the sound of music.'
EXEC add_BibleVerse @BibleId, 123051004, N'Pay attention to me, my people! Listen to me, my people! For I will issue a decree, I will make my justice a light to the nations.'
EXEC add_BibleVerse @BibleId, 123051005, N'I am ready to vindicate, I am ready to deliver, I will establish justice among the nations. The coastlands wait patiently for me; they wait in anticipation for the revelation of my power.'
EXEC add_BibleVerse @BibleId, 123051006, N'Look up at the sky! Look at the earth below! For the sky will dissipate like smoke, and the earth will wear out like clothes; its residents will die like gnats. But the deliverance I give is permanent; the vindication I provide will not disappear.'
EXEC add_BibleVerse @BibleId, 123051007, N'Listen to me, you who know what is right, you people who are aware of my law! Don’t be afraid of the insults of men; don’t be discouraged because of their abuse!'
EXEC add_BibleVerse @BibleId, 123051008, N'For a moth will eat away at them like clothes; a clothes moth will devour them like wool. But the vindication I provide will be permanent; the deliverance I give will last.”'
EXEC add_BibleVerse @BibleId, 123051009, N'Wake up! Wake up! Clothe yourself with strength, O arm of the Lord! Wake up as in former times, as in antiquity! Did you not smash the Proud One? Did you not wound the sea monster?'
EXEC add_BibleVerse @BibleId, 123051010, N'Did you not dry up the sea, the waters of the great deep? Did you not make a path through the depths of the sea, so those delivered from bondage could cross over?'
EXEC add_BibleVerse @BibleId, 123051011, N'Those whom the Lord has ransomed will return; they will enter Zion with a happy shout. Unending joy will crown them, happiness and joy will overwhelm them; grief and suffering will disappear.'
EXEC add_BibleVerse @BibleId, 123051012, N'“I, I am the one who consoles you. Why are you afraid of mortal men, of mere human beings who are as short-lived as grass?'
EXEC add_BibleVerse @BibleId, 123051013, N'Why do you forget the Lord, who made you, who stretched out the sky and founded the earth? Why do you constantly tremble all day long at the anger of the oppressor, when he makes plans to destroy? Where is the anger of the oppressor?'
EXEC add_BibleVerse @BibleId, 123051014, N'The one who suffers will soon be released; he will not die in prison, he will not go hungry.'
EXEC add_BibleVerse @BibleId, 123051015, N'I am the Lord your God, who churns up the sea so that its waves surge. The Lord who commands armies is his name!'
EXEC add_BibleVerse @BibleId, 123051016, N'I commission you as my spokesman; I cover you with the palm of my hand, to establish the sky and to found the earth, to say to Zion, ‘You are my people.’”'
EXEC add_BibleVerse @BibleId, 123051017, N'Wake up! Wake up! Get up, O Jerusalem! You drank from the cup the Lord passed to you, which was full of his anger! You drained dry the goblet full of intoxicating wine.'
EXEC add_BibleVerse @BibleId, 123051018, N'There was no one to lead her among all the children she bore; there was no one to take her by the hand among all the children she raised.'
EXEC add_BibleVerse @BibleId, 123051019, N'These double disasters confronted you. But who feels sorry for you? Destruction and devastation, famine and sword. But who consoles you?'
EXEC add_BibleVerse @BibleId, 123051020, N'Your children faint; they lie at the head of every street like an antelope in a snare. They are left in a stupor by the Lord’s anger, by the battle cry of your God.'
EXEC add_BibleVerse @BibleId, 123051021, N'So listen to this, oppressed one, who is drunk, but not from wine!'
EXEC add_BibleVerse @BibleId, 123051022, N'This is what your sovereign master, the Lord your God, says: “Look, I have removed from your hand the cup of intoxicating wine, the goblet full of my anger. You will no longer have to drink it.'
EXEC add_BibleVerse @BibleId, 123051023, N'I will put it into the hand of your tormentors who said to you, ‘Lie down, so we can walk over you.’ You made your back like the ground, and like the street for those who walked over you.”'
EXEC add_BibleVerse @BibleId, 123052001, N'Wake up! Wake up! Clothe yourself with strength, O Zion! Put on your beautiful clothes, O Jerusalem, holy city! For uncircumcised and unclean pagans will no longer invade you.'
EXEC add_BibleVerse @BibleId, 123052002, N'Shake off the dirt! Get up, captive Jerusalem! Take off the iron chains around your neck, O captive daughter Zion!'
EXEC add_BibleVerse @BibleId, 123052003, N'For this is what the Lord says: “You were sold for nothing, and you will not be redeemed for money.”'
EXEC add_BibleVerse @BibleId, 123052004, N'For this is what the sovereign Lord says: “In the beginning my people went to live temporarily in Egypt; Assyria oppressed them for no good reason.'
EXEC add_BibleVerse @BibleId, 123052005, N'And now, what do we have here?” says the Lord. “Indeed my people have been carried away for nothing, those who rule over them taunt,” says the Lord, “and my name is constantly slandered all day long.'
EXEC add_BibleVerse @BibleId, 123052006, N'For this reason my people will know my name, for this reason they will know at that time that I am the one who says, ‘Here I am.’”'
EXEC add_BibleVerse @BibleId, 123052007, N'How delightful it is to see approaching over the mountains the feet of a messenger who announces peace, a messenger who brings good news, who announces deliverance, who says to Zion, “Your God reigns!”'
EXEC add_BibleVerse @BibleId, 123052008, N'Listen, your watchmen shout; in unison they shout for joy, for they see with their very own eyes the Lord’s return to Zion.'
EXEC add_BibleVerse @BibleId, 123052009, N'In unison give a joyful shout, O ruins of Jerusalem! For the Lord consoles his people; he protects Jerusalem.'
EXEC add_BibleVerse @BibleId, 123052010, N'The Lord reveals his royal power in the sight of all the nations; the entire earth sees our God deliver.'
EXEC add_BibleVerse @BibleId, 123052011, N'Leave! Leave! Get out of there! Don’t touch anything unclean! Get out of it! Stay pure, you who carry the Lord’s holy items!'
EXEC add_BibleVerse @BibleId, 123052012, N'Yet do not depart quickly or leave in a panic. For the Lord goes before you; the God of Israel is your rear guard.'
EXEC add_BibleVerse @BibleId, 123052013, N'“Look, my servant will succeed! He will be elevated, lifted high, and greatly exalted –'
EXEC add_BibleVerse @BibleId, 123052014, N'(just as many were horrified by the sight of you) he was so disfigured he no longer looked like a man;'
EXEC add_BibleVerse @BibleId, 123052015, N'his form was so marred he no longer looked human – so now he will startle many nations. Kings will be shocked by his exaltation, for they will witness something unannounced to them, and they will understand something they had not heard about.'
EXEC add_BibleVerse @BibleId, 123053001, N'Who would have believed what we just heard? When was the Lord’s power revealed through him?'
EXEC add_BibleVerse @BibleId, 123053002, N'He sprouted up like a twig before God, like a root out of parched soil; he had no stately form or majesty that might catch our attention, no special appearance that we should want to follow him.'
EXEC add_BibleVerse @BibleId, 123053003, N'He was despised and rejected by people, one who experienced pain and was acquainted with illness; people hid their faces from him; he was despised, and we considered him insignificant.'
EXEC add_BibleVerse @BibleId, 123053004, N'But he lifted up our illnesses, he carried our pain; even though we thought he was being punished, attacked by God, and afflicted for something he had done.'
EXEC add_BibleVerse @BibleId, 123053005, N'He was wounded because of our rebellious deeds, crushed because of our sins; he endured punishment that made us well; because of his wounds we have been healed.'
EXEC add_BibleVerse @BibleId, 123053006, N'All of us had wandered off like sheep; each of us had strayed off on his own path, but the Lord caused the sin of all of us to attack him.'
EXEC add_BibleVerse @BibleId, 123053007, N'He was treated harshly and afflicted, but he did not even open his mouth. Like a lamb led to the slaughtering block, like a sheep silent before her shearers, he did not even open his mouth.'
EXEC add_BibleVerse @BibleId, 123053008, N'He was led away after an unjust trial – but who even cared? Indeed, he was cut off from the land of the living; because of the rebellion of his own people he was wounded.'
EXEC add_BibleVerse @BibleId, 123053009, N'They intended to bury him with criminals, but he ended up in a rich man’s tomb, because he had committed no violent deeds, nor had he spoken deceitfully.'
EXEC add_BibleVerse @BibleId, 123053010, N'Though the Lord desired to crush him and make him ill, once restitution is made, he will see descendants and enjoy long life, and the Lord’s purpose will be accomplished through him.'
EXEC add_BibleVerse @BibleId, 123053011, N'Having suffered, he will reflect on his work, he will be satisfied when he understands what he has done. “My servant will acquit many, for he carried their sins.'
EXEC add_BibleVerse @BibleId, 123053012, N'So I will assign him a portion with the multitudes, he will divide the spoils of victory with the powerful, because he willingly submitted to death and was numbered with the rebels, when he lifted up the sin of many and intervened on behalf of the rebels.”'
EXEC add_BibleVerse @BibleId, 123054001, N'“Shout for joy, O barren one who has not given birth! Give a joyful shout and cry out, you who have not been in labor! For the children of the desolate one are more numerous than the children of the married woman,” says the Lord.'
EXEC add_BibleVerse @BibleId, 123054002, N'Make your tent larger, stretch your tent curtains farther out! Spare no effort, lengthen your ropes, and pound your stakes deep.'
EXEC add_BibleVerse @BibleId, 123054003, N'For you will spread out to the right and to the left; your children will conquer nations and will resettle desolate cities.'
EXEC add_BibleVerse @BibleId, 123054004, N'Don’t be afraid, for you will not be put to shame! Don’t be intimidated, for you will not be humiliated! You will forget about the shame you experienced in your youth; you will no longer remember the disgrace of your abandonment.'
EXEC add_BibleVerse @BibleId, 123054005, N'For your husband is the one who made you – the Lord who commands armies is his name. He is your protector, the Holy One of Israel. He is called “God of the entire earth.”'
EXEC add_BibleVerse @BibleId, 123054006, N'“Indeed, the Lord will call you back like a wife who has been abandoned and suffers from depression, like a young wife when she has been rejected,” says your God.'
EXEC add_BibleVerse @BibleId, 123054007, N'“For a short time I abandoned you, but with great compassion I will gather you.'
EXEC add_BibleVerse @BibleId, 123054008, N'In a burst of anger I rejected you momentarily, but with lasting devotion I will have compassion on you,” says your protector, the Lord.'
EXEC add_BibleVerse @BibleId, 123054009, N'“As far as I am concerned, this is like in Noah’s time, when I vowed that the waters of Noah’s flood would never again cover the earth. In the same way I have vowed that I will not be angry at you or shout at you.'
EXEC add_BibleVerse @BibleId, 123054010, N'Even if the mountains are removed and the hills displaced, my devotion will not be removed from you, nor will my covenant of friendship be displaced,” says the Lord, the one who has compassion on you.'
EXEC add_BibleVerse @BibleId, 123054011, N'“O afflicted one, driven away, and unconsoled! Look, I am about to set your stones in antimony and I lay your foundation with lapis-lazuli.'
EXEC add_BibleVerse @BibleId, 123054012, N'I will make your pinnacles out of gems, your gates out of beryl, and your outer wall out of beautiful stones.'
EXEC add_BibleVerse @BibleId, 123054013, N'All your children will be followers of the Lord, and your children will enjoy great prosperity.'
EXEC add_BibleVerse @BibleId, 123054014, N'You will be reestablished when I vindicate you. You will not experience oppression; indeed, you will not be afraid. You will not be terrified, for nothing frightening will come near you.'
EXEC add_BibleVerse @BibleId, 123054015, N'If anyone dares to challenge you, it will not be my doing! Whoever tries to challenge you will be defeated.'
EXEC add_BibleVerse @BibleId, 123054016, N'Look, I create the craftsman, who fans the coals into a fire and forges a weapon. I create the destroyer so he might devastate.'
EXEC add_BibleVerse @BibleId, 123054017, N'No weapon forged to be used against you will succeed; you will refute everyone who tries to accuse you. This is what the Lord will do for his servants – I will vindicate them,” says the Lord.'
EXEC add_BibleVerse @BibleId, 123055001, N'“Hey, all who are thirsty, come to the water! You who have no money, come! Buy and eat! Come! Buy wine and milk without money and without cost!'
EXEC add_BibleVerse @BibleId, 123055002, N'Why pay money for something that will not nourish you? Why spend your hard-earned money on something that will not satisfy? Listen carefully to me and eat what is nourishing! Enjoy fine food!'
EXEC add_BibleVerse @BibleId, 123055003, N'Pay attention and come to me! Listen, so you can live! Then I will make an unconditional covenantal promise to you, just like the reliable covenantal promises I made to David.'
EXEC add_BibleVerse @BibleId, 123055004, N'Look, I made him a witness to nations, a ruler and commander of nations.”'
EXEC add_BibleVerse @BibleId, 123055005, N'Look, you will summon nations you did not previously know; nations that did not previously know you will run to you, because of the Lord your God, the Holy One of Israel, for he bestows honor on you.'
EXEC add_BibleVerse @BibleId, 123055006, N'Seek the Lord while he makes himself available; call to him while he is nearby!'
EXEC add_BibleVerse @BibleId, 123055007, N'The wicked need to abandon their lifestyle and sinful people their plans. They should return to the Lord, and he will show mercy to them, and to their God, for he will freely forgive them.'
EXEC add_BibleVerse @BibleId, 123055008, N'“Indeed, my plans are not like your plans, and my deeds are not like your deeds,'
EXEC add_BibleVerse @BibleId, 123055009, N'for just as the sky is higher than the earth, so my deeds are superior to your deeds and my plans superior to your plans.'
EXEC add_BibleVerse @BibleId, 123055010, N'The rain and snow fall from the sky and do not return, but instead water the earth and make it produce and yield crops, and provide seed for the planter and food for those who must eat.'
EXEC add_BibleVerse @BibleId, 123055011, N'In the same way, the promise that I make does not return to me, having accomplished nothing. No, it is realized as I desire and is fulfilled as I intend.”'
EXEC add_BibleVerse @BibleId, 123055012, N'Indeed you will go out with joy; you will be led along in peace; the mountains and hills will give a joyful shout before you, and all the trees in the field will clap their hands.'
EXEC add_BibleVerse @BibleId, 123055013, N'Evergreens will grow in place of thorn bushes, firs will grow in place of nettles; they will be a monument to the Lord, a permanent reminder that will remain.'
EXEC add_BibleVerse @BibleId, 123056001, N'This is what the Lord says, “Promote justice! Do what is right! For I am ready to deliver you; I am ready to vindicate you openly.'
EXEC add_BibleVerse @BibleId, 123056002, N'The people who do this will be blessed, the people who commit themselves to obedience, who observe the Sabbath and do not defile it, who refrain from doing anything that is wrong.'
EXEC add_BibleVerse @BibleId, 123056003, N'No foreigner who becomes a follower of the Lord should say, ‘The Lord will certainly exclude me from his people.’ The eunuch should not say, ‘Look, I am like a dried-up tree.’”'
EXEC add_BibleVerse @BibleId, 123056004, N'For this is what the Lord says: “For the eunuchs who observe my Sabbaths and choose what pleases me and are faithful to my covenant,'
EXEC add_BibleVerse @BibleId, 123056005, N'I will set up within my temple and my walls a monument that will be better than sons and daughters. I will set up a permanent monument for them that will remain.'
EXEC add_BibleVerse @BibleId, 123056006, N'As for foreigners who become followers of the Lord and serve him, who love the name of the Lord and want to be his servants – all who observe the Sabbath and do not defile it, and who are faithful to my covenant –'
EXEC add_BibleVerse @BibleId, 123056007, N'I will bring them to my holy mountain; I will make them happy in the temple where people pray to me. Their burnt offerings and sacrifices will be accepted on my altar, for my temple will be known as a temple where all nations may pray.”'
EXEC add_BibleVerse @BibleId, 123056008, N'The sovereign Lord says this, the one who gathers the dispersed of Israel: “I will still gather them up.”'
EXEC add_BibleVerse @BibleId, 123056009, N'All you wild animals in the fields, come and devour, all you wild animals in the forest!'
EXEC add_BibleVerse @BibleId, 123056010, N'All their watchmen are blind, they are unaware. All of them are like mute dogs, unable to bark. They pant, lie down, and love to snooze.'
EXEC add_BibleVerse @BibleId, 123056011, N'The dogs have big appetites; they are never full. They are shepherds who have no understanding; they all go their own way, each one looking for monetary gain.'
EXEC add_BibleVerse @BibleId, 123056012, N'Each one says, ‘Come on, I’ll get some wine! Let’s guzzle some beer! Tomorrow will be just like today! We’ll have everything we want!’'
EXEC add_BibleVerse @BibleId, 123057001, N'The godly perish, but no one cares. Honest people disappear, when no one minds that the godly disappear because of evil.'
EXEC add_BibleVerse @BibleId, 123057002, N'Those who live uprightly enter a place of peace; they rest on their beds.'
EXEC add_BibleVerse @BibleId, 123057003, N'But approach, you sons of omen readers, you offspring of adulteresses and prostitutes!'
EXEC add_BibleVerse @BibleId, 123057004, N'At whom are you laughing? At whom are you opening your mouth and sticking out your tongue? You are the children of rebels, the offspring of liars,'
EXEC add_BibleVerse @BibleId, 123057005, N'you who practice ritual sex under the oaks and every green tree, who slaughter children near the streams under the rocky overhangs.'
EXEC add_BibleVerse @BibleId, 123057006, N'Among the smooth stones of the stream are the idols you love; they, they are the object of your devotion. You pour out liquid offerings to them, you make an offering. Because of these things I will seek vengeance.'
EXEC add_BibleVerse @BibleId, 123057007, N'On every high, elevated hill you prepare your bed; you go up there to offer sacrifices.'
EXEC add_BibleVerse @BibleId, 123057008, N'Behind the door and doorpost you put your symbols. Indeed, you depart from me and go up and invite them into bed with you. You purchase favors from them, you love their bed, and gaze longingly on their genitals.'
EXEC add_BibleVerse @BibleId, 123057009, N'You take olive oil as tribute to your king, along with many perfumes. You send your messengers to a distant place; you go all the way to Sheol.'
EXEC add_BibleVerse @BibleId, 123057010, N'Because of the long distance you must travel, you get tired, but you do not say, ‘I give up.’ You get renewed energy, so you don’t collapse.'
EXEC add_BibleVerse @BibleId, 123057011, N'Whom are you worried about? Whom do you fear, that you would act so deceitfully and not remember me or think about me? Because I have been silent for so long, you are not afraid of me.'
EXEC add_BibleVerse @BibleId, 123057012, N'I will denounce your so-called righteousness and your deeds, but they will not help you.'
EXEC add_BibleVerse @BibleId, 123057013, N'When you cry out for help, let your idols help you! The wind blows them all away, a breeze carries them away. But the one who looks to me for help will inherit the land and will have access to my holy mountain.”'
EXEC add_BibleVerse @BibleId, 123057014, N'He says, “Build it! Build it! Clear a way! Remove all the obstacles out of the way of my people!”'
EXEC add_BibleVerse @BibleId, 123057015, N'For this is what the high and exalted one says, the one who rules forever, whose name is holy: “I dwell in an exalted and holy place, but also with the discouraged and humiliated, in order to cheer up the humiliated and to encourage the discouraged.'
EXEC add_BibleVerse @BibleId, 123057016, N'For I will not be hostile forever or perpetually angry, for then man’s spirit would grow faint before me, the life-giving breath I created.'
EXEC add_BibleVerse @BibleId, 123057017, N'I was angry because of their sinful greed; I attacked them and angrily rejected them, yet they remained disobedient and stubborn.'
EXEC add_BibleVerse @BibleId, 123057018, N'I have seen their behavior, but I will heal them and give them rest, and I will once again console those who mourn.'
EXEC add_BibleVerse @BibleId, 123057019, N'I am the one who gives them reason to celebrate. Complete prosperity is available both to those who are far away and those who are nearby,” says the Lord, “and I will heal them.'
EXEC add_BibleVerse @BibleId, 123057020, N'But the wicked are like a surging sea that is unable to be quiet; its waves toss up mud and sand.'
EXEC add_BibleVerse @BibleId, 123057021, N'There will be no prosperity,” says my God, “for the wicked.”'
EXEC add_BibleVerse @BibleId, 123058001, N'“Shout loudly! Don’t be quiet! Yell as loud as a trumpet! Confront my people with their rebellious deeds; confront Jacob’s family with their sin!'
EXEC add_BibleVerse @BibleId, 123058002, N'They seek me day after day; they want to know my requirements, like a nation that does what is right and does not reject the law of their God. They ask me for just decrees; they want to be near God.'
EXEC add_BibleVerse @BibleId, 123058003, N'They lament, ‘Why don’t you notice when we fast? Why don’t you pay attention when we humble ourselves?’ Look, at the same time you fast, you satisfy your selfish desires, you oppress your workers.'
EXEC add_BibleVerse @BibleId, 123058004, N'Look, your fasting is accompanied by arguments, brawls, and fistfights. Do not fast as you do today, trying to make your voice heard in heaven.'
EXEC add_BibleVerse @BibleId, 123058005, N'Is this really the kind of fasting I want? Do I want a day when people merely humble themselves, bowing their heads like a reed and stretching out on sackcloth and ashes? Is this really what you call a fast, a day that is pleasing to the Lord?'
EXEC add_BibleVerse @BibleId, 123058006, N'No, this is the kind of fast I want. I want you to remove the sinful chains, to tear away the ropes of the burdensome yoke, to set free the oppressed, and to break every burdensome yoke.'
EXEC add_BibleVerse @BibleId, 123058007, N'I want you to share your food with the hungry and to provide shelter for homeless, oppressed people. When you see someone naked, clothe him! Don’t turn your back on your own flesh and blood!'
EXEC add_BibleVerse @BibleId, 123058008, N'Then your light will shine like the sunrise; your restoration will quickly arrive; your godly behavior will go before you, and the Lord’s splendor will be your rear guard.'
EXEC add_BibleVerse @BibleId, 123058009, N'Then you will call out, and the Lord will respond; you will cry out, and he will reply, ‘Here I am.’ You must remove the burdensome yoke from among you and stop pointing fingers and speaking sinfully.'
EXEC add_BibleVerse @BibleId, 123058010, N'You must actively help the hungry and feed the oppressed. Then your light will dispel the darkness, and your darkness will be transformed into noonday.'
EXEC add_BibleVerse @BibleId, 123058011, N'The Lord will continually lead you; he will feed you even in parched regions. He will give you renewed strength, and you will be like a well-watered garden, like a spring that continually produces water.'
EXEC add_BibleVerse @BibleId, 123058012, N'Your perpetual ruins will be rebuilt; you will reestablish the ancient foundations. You will be called, ‘The one who repairs broken walls, the one who makes the streets inhabitable again.’'
EXEC add_BibleVerse @BibleId, 123058013, N'You must observe the Sabbath rather than doing anything you please on my holy day. You must look forward to the Sabbath and treat the Lord’s holy day with respect. You must treat it with respect by refraining from your normal activities, and by refraining from your selfish pursuits and from making business deals.'
EXEC add_BibleVerse @BibleId, 123058014, N'Then you will find joy in your relationship to the Lord, and I will give you great prosperity, and cause crops to grow on the land I gave to your ancestor Jacob.” Know for certain that the Lord has spoken.'
EXEC add_BibleVerse @BibleId, 123059001, N'Look, the Lord’s hand is not too weak to deliver you; his ear is not too deaf to hear you.'
EXEC add_BibleVerse @BibleId, 123059002, N'But your sinful acts have alienated you from your God; your sins have caused him to reject you and not listen to your prayers.'
EXEC add_BibleVerse @BibleId, 123059003, N'For your hands are stained with blood and your fingers with sin; your lips speak lies, your tongue utters malicious words.'
EXEC add_BibleVerse @BibleId, 123059004, N'No one is concerned about justice; no one sets forth his case truthfully. They depend on false words and tell lies; they conceive of oppression and give birth to sin.'
EXEC add_BibleVerse @BibleId, 123059005, N'They hatch the eggs of a poisonous snake and spin a spider’s web. Whoever eats their eggs will die, a poisonous snake is hatched.'
EXEC add_BibleVerse @BibleId, 123059006, N'Their webs cannot be used for clothing; they cannot cover themselves with what they make. Their deeds are sinful; they commit violent crimes.'
EXEC add_BibleVerse @BibleId, 123059007, N'They are eager to do evil, quick to shed innocent blood. Their thoughts are sinful; they crush and destroy.'
EXEC add_BibleVerse @BibleId, 123059008, N'They are unfamiliar with peace; their deeds are unjust. They use deceitful methods, and whoever deals with them is unfamiliar with peace.'
EXEC add_BibleVerse @BibleId, 123059009, N'For this reason deliverance is far from us and salvation does not reach us. We wait for light, but see only darkness; we wait for a bright light, but live in deep darkness.'
EXEC add_BibleVerse @BibleId, 123059010, N'We grope along the wall like the blind, we grope like those who cannot see; we stumble at noontime as if it were evening. Though others are strong, we are like dead men.'
EXEC add_BibleVerse @BibleId, 123059011, N'We all growl like bears, we coo mournfully like doves; we wait for deliverance, but there is none, for salvation, but it is far from us.'
EXEC add_BibleVerse @BibleId, 123059012, N'For you are aware of our many rebellious deeds, and our sins testify against us; indeed, we are aware of our rebellious deeds; we know our sins all too well.'
EXEC add_BibleVerse @BibleId, 123059013, N'We have rebelled and tried to deceive the Lord; we turned back from following our God. We stir up oppression and rebellion; we tell lies we concocted in our minds.'
EXEC add_BibleVerse @BibleId, 123059014, N'Justice is driven back; godliness stands far off. Indeed, honesty stumbles in the city square and morality is not even able to enter.'
EXEC add_BibleVerse @BibleId, 123059015, N'Honesty has disappeared; the one who tries to avoid evil is robbed. The Lord watches and is displeased, for there is no justice.'
EXEC add_BibleVerse @BibleId, 123059016, N'He sees there is no advocate; he is shocked that no one intervenes. So he takes matters into his own hands; his desire for justice drives him on.'
EXEC add_BibleVerse @BibleId, 123059017, N'He wears his desire for justice like body armor, and his desire to deliver is like a helmet on his head. He puts on the garments of vengeance and wears zeal like a robe.'
EXEC add_BibleVerse @BibleId, 123059018, N'He repays them for what they have done, dispensing angry judgment to his adversaries and punishing his enemies. He repays the coastlands.'
EXEC add_BibleVerse @BibleId, 123059019, N'In the west, people respect the Lord’s reputation; in the east they recognize his splendor. For he comes like a rushing stream driven on by wind sent from the Lord.'
EXEC add_BibleVerse @BibleId, 123059020, N'“A protector comes to Zion, to those in Jacob who repent of their rebellious deeds,” says the Lord.'
EXEC add_BibleVerse @BibleId, 123059021, N'“As for me, this is my promise to them,” says the Lord. “My spirit, who is upon you, and my words, which I have placed in your mouth, will not depart from your mouth or from the mouths of your children and descendants from this time forward,” says the Lord.'
EXEC add_BibleVerse @BibleId, 123060001, N'“Arise! Shine! For your light arrives! The splendor of the Lord shines on you!'
EXEC add_BibleVerse @BibleId, 123060002, N'For, look, darkness covers the earth and deep darkness covers the nations, but the Lord shines on you; his splendor appears over you.'
EXEC add_BibleVerse @BibleId, 123060003, N'Nations come to your light, kings to your bright light.'
EXEC add_BibleVerse @BibleId, 123060004, N'Look all around you! They all gather and come to you – your sons come from far away and your daughters are escorted by guardians.'
EXEC add_BibleVerse @BibleId, 123060005, N'Then you will look and smile, you will be excited and your heart will swell with pride. For the riches of distant lands will belong to you and the wealth of nations will come to you.'
EXEC add_BibleVerse @BibleId, 123060006, N'Camel caravans will cover your roads, young camels from Midian and Ephah. All the merchants of Sheba will come, bringing gold and incense and singing praises to the Lord.'
EXEC add_BibleVerse @BibleId, 123060007, N'All the sheep of Kedar will be gathered to you; the rams of Nebaioth will be available to you as sacrifices. They will go up on my altar acceptably, and I will bestow honor on my majestic temple.'
EXEC add_BibleVerse @BibleId, 123060008, N'Who are these who float along like a cloud, who fly like doves to their shelters?'
EXEC add_BibleVerse @BibleId, 123060009, N'Indeed, the coastlands look eagerly for me, the large ships are in the lead, bringing your sons from far away, along with their silver and gold, to honor the Lord your God, the Holy One of Israel, for he has bestowed honor on you.'
EXEC add_BibleVerse @BibleId, 123060010, N'Foreigners will rebuild your walls; their kings will serve you. Even though I struck you down in my anger, I will restore my favor and have compassion on you.'
EXEC add_BibleVerse @BibleId, 123060011, N'Your gates will remain open at all times; they will not be shut during the day or at night, so that the wealth of nations may be delivered, with their kings leading the way.'
EXEC add_BibleVerse @BibleId, 123060012, N'Indeed, nations or kingdoms that do not serve you will perish; such nations will be totally destroyed.'
EXEC add_BibleVerse @BibleId, 123060013, N'The splendor of Lebanon will come to you, its evergreens, firs, and cypresses together, to beautify my palace; I will bestow honor on my throne room.'
EXEC add_BibleVerse @BibleId, 123060014, N'The children of your oppressors will come bowing to you; all who treated you with disrespect will bow down at your feet. They will call you, ‘The City of the Lord, Zion of the Holy One of Israel.’'
EXEC add_BibleVerse @BibleId, 123060015, N'You were once abandoned and despised, with no one passing through, but I will make you a permanent source of pride and joy to coming generations.'
EXEC add_BibleVerse @BibleId, 123060016, N'You will drink the milk of nations; you will nurse at the breasts of kings. Then you will recognize that I, the Lord, am your deliverer, your protector, the powerful ruler of Jacob.'
EXEC add_BibleVerse @BibleId, 123060017, N'Instead of bronze, I will bring you gold, instead of iron, I will bring you silver, instead of wood, I will bring you bronze, instead of stones, I will bring you iron. I will make prosperity your overseer, and vindication your sovereign ruler.'
EXEC add_BibleVerse @BibleId, 123060018, N'Sounds of violence will no longer be heard in your land, or the sounds of destruction and devastation within your borders. You will name your walls, ‘Deliverance,’ and your gates, ‘Praise.’'
EXEC add_BibleVerse @BibleId, 123060019, N'The sun will no longer supply light for you by day, nor will the moon’s brightness shine on you; the Lord will be your permanent source of light – the splendor of your God will shine upon you.'
EXEC add_BibleVerse @BibleId, 123060020, N'Your sun will no longer set; your moon will not disappear; the Lord will be your permanent source of light; your time of sorrow will be over.'
EXEC add_BibleVerse @BibleId, 123060021, N'All of your people will be godly; they will possess the land permanently. I will plant them like a shoot; they will be the product of my labor, through whom I reveal my splendor.'
EXEC add_BibleVerse @BibleId, 123060022, N'The least of you will multiply into a thousand; the smallest of you will become a large nation. When the right time comes, I the Lord will quickly do this!”'
EXEC add_BibleVerse @BibleId, 123061001, N'The spirit of the sovereign Lord is upon me, because the Lord has chosen me. He has commissioned me to encourage the poor, to help the brokenhearted, to decree the release of captives, and the freeing of prisoners,'
EXEC add_BibleVerse @BibleId, 123061002, N'to announce the year when the Lord will show his favor, the day when our God will seek vengeance, to console all who mourn,'
EXEC add_BibleVerse @BibleId, 123061003, N'to strengthen those who mourn in Zion, by giving them a turban, instead of ashes, oil symbolizing joy, instead of mourning, a garment symbolizing praise, instead of discouragement. They will be called oaks of righteousness, trees planted by the Lord to reveal his splendor.'
EXEC add_BibleVerse @BibleId, 123061004, N'They will rebuild the perpetual ruins and restore the places that were desolate; they will reestablish the ruined cities, the places that have been desolate since ancient times.'
EXEC add_BibleVerse @BibleId, 123061005, N'“Foreigners will take care of your sheep; foreigners will work in your fields and vineyards.'
EXEC add_BibleVerse @BibleId, 123061006, N'You will be called, ‘the Lord’s priests, servants of our God.’ You will enjoy the wealth of nations and boast about the riches you receive from them.'
EXEC add_BibleVerse @BibleId, 123061007, N'Instead of shame, you will get a double portion; instead of humiliation, they will rejoice over the land they receive. Yes, they will possess a double portion in their land and experience lasting joy.'
EXEC add_BibleVerse @BibleId, 123061008, N'For I, the Lord, love justice and hate robbery and sin. I will repay them because of my faithfulness; I will make a permanent covenant with them.'
EXEC add_BibleVerse @BibleId, 123061009, N'Their descendants will be known among the nations, their offspring among the peoples. All who see them will recognize that the Lord has blessed them.”'
EXEC add_BibleVerse @BibleId, 123061010, N'I will greatly rejoice in the Lord; I will be overjoyed because of my God. For he clothes me in garments of deliverance; he puts on me a robe symbolizing vindication. I look like a bridegroom when he wears a turban as a priest would; I look like a bride when she puts on her jewelry.'
EXEC add_BibleVerse @BibleId, 123061011, N'For just as the ground produces its crops and a garden yields its produce, so the sovereign Lord will cause deliverance to grow, and give his people reason to praise him in the sight of all the nations.'
EXEC add_BibleVerse @BibleId, 123062001, N'“For the sake of Zion I will not be silent; for the sake of Jerusalem I will not be quiet, until her vindication shines brightly and her deliverance burns like a torch.”'
EXEC add_BibleVerse @BibleId, 123062002, N'Nations will see your vindication, and all kings your splendor. You will be called by a new name that the Lord himself will give you.'
EXEC add_BibleVerse @BibleId, 123062003, N'You will be a majestic crown in the hand of the Lord, a royal turban in the hand of your God.'
EXEC add_BibleVerse @BibleId, 123062004, N'You will no longer be called, “Abandoned,” and your land will no longer be called “Desolate.” Indeed, you will be called “My Delight is in Her,” and your land “Married.” For the Lord will take delight in you, and your land will be married to him.'
EXEC add_BibleVerse @BibleId, 123062005, N'As a young man marries a young woman, so your sons will marry you. As a bridegroom rejoices over a bride, so your God will rejoice over you.'
EXEC add_BibleVerse @BibleId, 123062006, N'I post watchmen on your walls, O Jerusalem; they should keep praying all day and all night. You who pray to the Lord, don’t be silent!'
EXEC add_BibleVerse @BibleId, 123062007, N'Don’t allow him to rest until he reestablishes Jerusalem, until he makes Jerusalem the pride of the earth.'
EXEC add_BibleVerse @BibleId, 123062008, N'The Lord swears an oath by his right hand, by his strong arm: “I will never again give your grain to your enemies as food, and foreigners will not drink your wine, which you worked hard to produce.'
EXEC add_BibleVerse @BibleId, 123062009, N'But those who harvest the grain will eat it, and will praise the Lord. Those who pick the grapes will drink the wine in the courts of my holy sanctuary.”'
EXEC add_BibleVerse @BibleId, 123062010, N'Come through! Come through the gates! Prepare the way for the people! Build it! Build the roadway! Remove the stones! Lift a signal flag for the nations!'
EXEC add_BibleVerse @BibleId, 123062011, N'Look, the Lord announces to the entire earth: “Say to Daughter Zion, ‘Look, your deliverer comes! Look, his reward is with him and his reward goes before him!’”'
EXEC add_BibleVerse @BibleId, 123062012, N'They will be called, “The Holy People, the Ones Protected by the Lord.” You will be called, “Sought After, City Not Abandoned.”'
EXEC add_BibleVerse @BibleId, 123063001, N'Who is this who comes from Edom, dressed in bright red, coming from Bozrah? Who is this one wearing royal attire, who marches confidently because of his great strength? “It is I, the one who announces vindication, and who is able to deliver!”'
EXEC add_BibleVerse @BibleId, 123063002, N'Why are your clothes red? Why do you look like someone who has stomped on grapes in a vat?'
EXEC add_BibleVerse @BibleId, 123063003, N'“I have stomped grapes in the winepress all by myself; no one from the nations joined me. I stomped on them in my anger; I trampled them down in my rage. Their juice splashed on my garments, and stained all my clothes.'
EXEC add_BibleVerse @BibleId, 123063004, N'For I looked forward to the day of vengeance, and then payback time arrived.'
EXEC add_BibleVerse @BibleId, 123063005, N'I looked, but there was no one to help; I was shocked because there was no one offering support. So my right arm accomplished deliverance; my raging anger drove me on.'
EXEC add_BibleVerse @BibleId, 123063006, N'I trampled nations in my anger, I made them drunk in my rage, I splashed their blood on the ground.”'
EXEC add_BibleVerse @BibleId, 123063007, N'I will tell of the faithful acts of the Lord, of the Lord’s praiseworthy deeds. I will tell about all the Lord did for us, the many good things he did for the family of Israel, because of his compassion and great faithfulness.'
EXEC add_BibleVerse @BibleId, 123063008, N'He said, “Certainly they will be my people, children who are not disloyal.” He became their deliverer.'
EXEC add_BibleVerse @BibleId, 123063009, N'Through all that they suffered, he suffered too. The messenger sent from his very presence delivered them. In his love and mercy he protected them; he lifted them up and carried them throughout ancient times.'
EXEC add_BibleVerse @BibleId, 123063010, N'But they rebelled and offended his holy Spirit, so he turned into an enemy and fought against them.'
EXEC add_BibleVerse @BibleId, 123063011, N'His people remembered the ancient times. Where is the one who brought them up out of the sea, along with the shepherd of his flock? Where is the one who placed his holy Spirit among them,'
EXEC add_BibleVerse @BibleId, 123063012, N'the one who made his majestic power available to Moses, who divided the water before them, gaining for himself a lasting reputation,'
EXEC add_BibleVerse @BibleId, 123063013, N'who led them through the deep water? Like a horse running on flat land they did not stumble.'
EXEC add_BibleVerse @BibleId, 123063014, N'Like an animal that goes down into a valley to graze, so the Spirit of the Lord granted them rest. In this way you guided your people, gaining for yourself an honored reputation.'
EXEC add_BibleVerse @BibleId, 123063015, N'Look down from heaven and take notice, from your holy, majestic palace! Where are your zeal and power? Do not hold back your tender compassion!'
EXEC add_BibleVerse @BibleId, 123063016, N'For you are our father, though Abraham does not know us and Israel does not recognize us. You, Lord, are our father; you have been called our protector from ancient times.'
EXEC add_BibleVerse @BibleId, 123063017, N'Why, Lord, do you make us stray from your ways, and make our minds stubborn so that we do not obey you? Return for the sake of your servants, the tribes of your inheritance!'
EXEC add_BibleVerse @BibleId, 123063018, N'For a short time your special nation possessed a land, but then our adversaries knocked down your holy sanctuary.'
EXEC add_BibleVerse @BibleId, 123063019, N'We existed from ancient times, but you did not rule over them, they were not your subjects.'
EXEC add_BibleVerse @BibleId, 123064001, N'If only you would tear apart the sky and come down! The mountains would tremble before you!'
EXEC add_BibleVerse @BibleId, 123064002, N'As when fire ignites dry wood, or fire makes water boil, let your adversaries know who you are, and may the nations shake at your presence!'
EXEC add_BibleVerse @BibleId, 123064003, N'When you performed awesome deeds that took us by surprise, you came down, and the mountains trembled before you.'
EXEC add_BibleVerse @BibleId, 123064004, N'Since ancient times no one has heard or perceived, no eye has seen any God besides you, who intervenes for those who wait for him.'
EXEC add_BibleVerse @BibleId, 123064005, N'You assist those who delight in doing what is right, who observe your commandments. Look, you were angry because we violated them continually. How then can we be saved?'
EXEC add_BibleVerse @BibleId, 123064006, N'We are all like one who is unclean, all our so-called righteous acts are like a menstrual rag in your sight. We all wither like a leaf; our sins carry us away like the wind.'
EXEC add_BibleVerse @BibleId, 123064007, N'No one invokes your name, or makes an effort to take hold of you. For you have rejected us and handed us over to our own sins.'
EXEC add_BibleVerse @BibleId, 123064008, N'Yet, Lord, you are our father. We are the clay, and you are our potter; we are all the product of your labor.'
EXEC add_BibleVerse @BibleId, 123064009, N'Lord, do not be too angry! Do not hold our sins against us continually! Take a good look at your people, at all of us!'
EXEC add_BibleVerse @BibleId, 123064010, N'Your chosen cities have become a desert; Zion has become a desert, Jerusalem is a desolate ruin.'
EXEC add_BibleVerse @BibleId, 123064011, N'Our holy temple, our pride and joy, the place where our ancestors praised you, has been burned with fire; all our prized possessions have been destroyed.'
EXEC add_BibleVerse @BibleId, 123064012, N'In light of all this, how can you still hold back, Lord? How can you be silent and continue to humiliate us?'
EXEC add_BibleVerse @BibleId, 123065001, N'“I made myself available to those who did not ask for me; I appeared to those who did not look for me. I said, ‘Here I am! Here I am!’ to a nation that did not invoke my name.'
EXEC add_BibleVerse @BibleId, 123065002, N'I spread out my hands all day long to my rebellious people, who lived in a way that is morally unacceptable, and who did what they desired.'
EXEC add_BibleVerse @BibleId, 123065003, N'These people continually and blatantly offend me as they sacrifice in their sacred orchards and burn incense on brick altars.'
EXEC add_BibleVerse @BibleId, 123065004, N'They sit among the tombs and keep watch all night long. They eat pork, and broth from unclean sacrificial meat is in their pans.'
EXEC add_BibleVerse @BibleId, 123065005, N'They say, ‘Keep to yourself! Don’t get near me, for I am holier than you!’ These people are like smoke in my nostrils, like a fire that keeps burning all day long.'
EXEC add_BibleVerse @BibleId, 123065006, N'Look, I have decreed: I will not keep silent, but will pay them back; I will pay them back exactly what they deserve,'
EXEC add_BibleVerse @BibleId, 123065007, N'for your sins and your ancestors’ sins,” says the Lord. “Because they burned incense on the mountains and offended me on the hills, I will punish them in full measure.”'
EXEC add_BibleVerse @BibleId, 123065008, N'This is what the Lord says: “When juice is discovered in a cluster of grapes, someone says, ‘Don’t destroy it, for it contains juice.’ So I will do for the sake of my servants – I will not destroy everyone.'
EXEC add_BibleVerse @BibleId, 123065009, N'I will bring forth descendants from Jacob, and from Judah people to take possession of my mountains. My chosen ones will take possession of the land; my servants will live there.'
EXEC add_BibleVerse @BibleId, 123065010, N'Sharon will become a pasture for sheep, and the Valley of Achor a place where cattle graze; they will belong to my people, who seek me.'
EXEC add_BibleVerse @BibleId, 123065011, N'But as for you who abandon the Lord and forget about worshiping at my holy mountain, who prepare a feast for the god called ‘Fortune,’ and fill up wine jugs for the god called ‘Destiny’ –'
EXEC add_BibleVerse @BibleId, 123065012, N'I predestine you to die by the sword, all of you will kneel down at the slaughtering block, because I called to you, and you did not respond, I spoke and you did not listen. You did evil before me; you chose to do what displeases me.”'
EXEC add_BibleVerse @BibleId, 123065013, N'So this is what the sovereign Lord says: “Look, my servants will eat, but you will be hungry! Look, my servants will drink, but you will be thirsty! Look, my servants will rejoice, but you will be humiliated!'
EXEC add_BibleVerse @BibleId, 123065014, N'Look, my servants will shout for joy as happiness fills their hearts! But you will cry out as sorrow fills your hearts; you will wail because your spirits will be crushed.'
EXEC add_BibleVerse @BibleId, 123065015, N'Your names will live on in the curse formulas of my chosen ones. The sovereign Lord will kill you, but he will give his servants another name.'
EXEC add_BibleVerse @BibleId, 123065016, N'Whoever pronounces a blessing in the earth will do so in the name of the faithful God; whoever makes an oath in the earth will do so in the name of the faithful God. For past problems will be forgotten; I will no longer think about them.'
EXEC add_BibleVerse @BibleId, 123065017, N'For look, I am ready to create new heavens and a new earth! The former ones will not be remembered; no one will think about them anymore.'
EXEC add_BibleVerse @BibleId, 123065018, N'But be happy and rejoice forevermore over what I am about to create! For look, I am ready to create Jerusalem to be a source of joy, and her people to be a source of happiness.'
EXEC add_BibleVerse @BibleId, 123065019, N'Jerusalem will bring me joy, and my people will bring me happiness. The sound of weeping or cries of sorrow will never be heard in her again.'
EXEC add_BibleVerse @BibleId, 123065020, N'Never again will one of her infants live just a few days or an old man die before his time. Indeed, no one will die before the age of a hundred, anyone who fails to reach the age of a hundred will be considered cursed.'
EXEC add_BibleVerse @BibleId, 123065021, N'They will build houses and live in them; they will plant vineyards and eat their fruit.'
EXEC add_BibleVerse @BibleId, 123065022, N'No longer will they build a house only to have another live in it, or plant a vineyard only to have another eat its fruit, for my people will live as long as trees, and my chosen ones will enjoy to the fullest what they have produced.'
EXEC add_BibleVerse @BibleId, 123065023, N'They will not work in vain, or give birth to children that will experience disaster. For the Lord will bless their children and their descendants.'
EXEC add_BibleVerse @BibleId, 123065024, N'Before they even call out, I will respond; while they are still speaking, I will hear.'
EXEC add_BibleVerse @BibleId, 123065025, N'A wolf and a lamb will graze together; a lion, like an ox, will eat straw, and a snake’s food will be dirt. They will no longer injure or destroy on my entire royal mountain,” says the Lord.'
EXEC add_BibleVerse @BibleId, 123066001, N'This is what the Lord says: “The heavens are my throne and the earth is my footstool. Where then is the house you will build for me? Where is the place where I will rest?'
EXEC add_BibleVerse @BibleId, 123066002, N'My hand made them; that is how they came to be,” says the Lord. I show special favor to the humble and contrite, who respect what I have to say.'
EXEC add_BibleVerse @BibleId, 123066003, N'The one who slaughters a bull also strikes down a man; the one who sacrifices a lamb also breaks a dog’s neck; the one who presents an offering includes pig’s blood with it; the one who offers incense also praises an idol. They have decided to behave this way; they enjoy these disgusting practices.'
EXEC add_BibleVerse @BibleId, 123066004, N'So I will choose severe punishment for them; I will bring on them what they dread, because I called, and no one responded, I spoke and they did not listen. They did evil before me; they chose to do what displeases me.”'
EXEC add_BibleVerse @BibleId, 123066005, N'Hear the word of the Lord, you who respect what he has to say! Your countrymen, who hate you and exclude you, supposedly for the sake of my name, say, “May the Lord be glorified, then we will witness your joy.” But they will be put to shame.'
EXEC add_BibleVerse @BibleId, 123066006, N'The sound of battle comes from the city; the sound comes from the temple! It is the sound of the Lord paying back his enemies.'
EXEC add_BibleVerse @BibleId, 123066007, N'Before she goes into labor, she gives birth! Before her contractions begin, she delivers a boy!'
EXEC add_BibleVerse @BibleId, 123066008, N'Who has ever heard of such a thing? Who has ever seen this? Can a country be brought forth in one day? Can a nation be born in a single moment? Yet as soon as Zion goes into labor she gives birth to sons!'
EXEC add_BibleVerse @BibleId, 123066009, N'“Do I bring a baby to the birth opening and then not deliver it?” asks the Lord. “Or do I bring a baby to the point of delivery and then hold it back?” asks your God.'
EXEC add_BibleVerse @BibleId, 123066010, N'Be happy for Jerusalem and rejoice with her, all you who love her! Share in her great joy, all you who have mourned over her!'
EXEC add_BibleVerse @BibleId, 123066011, N'For you will nurse from her satisfying breasts and be nourished; you will feed with joy from her milk-filled breasts.'
EXEC add_BibleVerse @BibleId, 123066012, N'For this is what the Lord says: “Look, I am ready to extend to her prosperity that will flow like a river, the riches of nations will flow into her like a stream that floods its banks. You will nurse from her breast and be carried at her side; you will play on her knees.'
EXEC add_BibleVerse @BibleId, 123066013, N'As a mother consoles a child, so I will console you, and you will be consoled over Jerusalem.”'
EXEC add_BibleVerse @BibleId, 123066014, N'When you see this, you will be happy, and you will be revived. The Lord will reveal his power to his servants and his anger to his enemies.'
EXEC add_BibleVerse @BibleId, 123066015, N'For look, the Lord comes with fire, his chariots come like a windstorm, to reveal his raging anger, his battle cry, and his flaming arrows.'
EXEC add_BibleVerse @BibleId, 123066016, N'For the Lord judges all humanity with fire and his sword; the Lord will kill many.'
EXEC add_BibleVerse @BibleId, 123066017, N'“As for those who consecrate and ritually purify themselves so they can follow their leader and worship in the sacred orchards, those who eat the flesh of pigs and other disgusting creatures, like mice – they will all be destroyed together,” says the Lord.'
EXEC add_BibleVerse @BibleId, 123066018, N'“I hate their deeds and thoughts! So I am coming to gather all the nations and ethnic groups; they will come and witness my splendor.'
EXEC add_BibleVerse @BibleId, 123066019, N'I will perform a mighty act among them and then send some of those who remain to the nations – to Tarshish, Pul, Lud (known for its archers ), Tubal, Javan, and to the distant coastlands that have not heard about me or seen my splendor. They will tell the nations of my splendor.'
EXEC add_BibleVerse @BibleId, 123066020, N'They will bring back all your countrymen from all the nations as an offering to the Lord. They will bring them on horses, in chariots, in wagons, on mules, and on camels to my holy hill Jerusalem,” says the Lord, “just as the Israelites bring offerings to the Lord’s temple in ritually pure containers.'
EXEC add_BibleVerse @BibleId, 123066021, N'And I will choose some of them as priests and Levites,” says the Lord.'
EXEC add_BibleVerse @BibleId, 123066022, N'“For just as the new heavens and the new earth I am about to make will remain standing before me,” says the Lord, “so your descendants and your name will remain.'
EXEC add_BibleVerse @BibleId, 123066023, N'From one month to the next and from one Sabbath to the next, all people will come to worship me,” says the Lord.'
EXEC add_BibleVerse @BibleId, 123066024, N'“They will go out and observe the corpses of those who rebelled against me, for the maggots that eat them will not die, and the fire that consumes them will not die out. All people will find the sight abhorrent.”'
EXEC add_BibleVerse @BibleId, 124001001, N'The following is a record of what Jeremiah son of Hilkiah prophesied. He was one of the priests who lived at Anathoth in the territory of the tribe of Benjamin.'
EXEC add_BibleVerse @BibleId, 124001002, N'The Lord began to speak to him in the thirteenth year that Josiah son of Amon ruled over Judah.'
EXEC add_BibleVerse @BibleId, 124001003, N'The Lord also spoke to him when Jehoiakim son of Josiah ruled over Judah, and he continued to speak to him until the fifth month of the eleventh year that Zedekiah son of Josiah ruled over Judah. That was when the people of Jerusalem were taken into exile.'
EXEC add_BibleVerse @BibleId, 124001004, N'The Lord said to me,'
EXEC add_BibleVerse @BibleId, 124001005, N'“Before I formed you in your mother’s womb I chose you. Before you were born I set you apart. I appointed you to be a prophet to the nations.”'
EXEC add_BibleVerse @BibleId, 124001006, N'I answered, “Oh, Lord God, I really do not know how to speak well enough for that, for I am too young.”'
EXEC add_BibleVerse @BibleId, 124001007, N'The Lord said to me, “Do not say, ‘I am too young.’ But go to whomever I send you and say whatever I tell you.'
EXEC add_BibleVerse @BibleId, 124001008, N'Do not be afraid of those to whom I send you, for I will be with you to protect you,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124001009, N'Then the Lord reached out his hand and touched my mouth and said to me, “I will most assuredly give you the words you are to speak for me.'
EXEC add_BibleVerse @BibleId, 124001010, N'Know for certain that I hereby give you the authority to announce to nations and kingdoms that they will be uprooted and torn down, destroyed and demolished, rebuilt and firmly planted.”'
EXEC add_BibleVerse @BibleId, 124001011, N'Later the Lord asked me, “What do you see, Jeremiah?” I answered, “I see a branch of an almond tree.”'
EXEC add_BibleVerse @BibleId, 124001012, N'Then the Lord said, “You have observed correctly. This means I am watching to make sure my threats are carried out.”'
EXEC add_BibleVerse @BibleId, 124001013, N'The Lord again asked me, “What do you see?” I answered, “I see a pot of boiling water; it is tipped toward us from the north.”'
EXEC add_BibleVerse @BibleId, 124001014, N'Then the Lord said, “This means destruction will break out from the north on all who live in the land.'
EXEC add_BibleVerse @BibleId, 124001015, N'For I will soon summon all the peoples of the kingdoms of the north,” says the Lord. “They will come and their kings will set up their thrones near the entrances of the gates of Jerusalem. They will attack all the walls surrounding it, and all the towns in Judah.'
EXEC add_BibleVerse @BibleId, 124001016, N'In this way I will pass sentence on the people of Jerusalem and Judah because of all their wickedness. For they rejected me and offered sacrifices to other gods, worshiping what they made with their own hands.”'
EXEC add_BibleVerse @BibleId, 124001017, N'“But you, Jeremiah, get yourself ready! Go and tell these people everything I instruct you to say. Do not be terrified of them, or I will give you good reason to be terrified of them.'
EXEC add_BibleVerse @BibleId, 124001018, N'I, the Lord, hereby promise to make you as strong as a fortified city, an iron pillar, and a bronze wall. You will be able to stand up against all who live in the land, including the kings of Judah, its officials, its priests and all the people of the land.'
EXEC add_BibleVerse @BibleId, 124001019, N'They will attack you but they will not be able to overcome you, for I will be with you to rescue you,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124002001, N'The Lord spoke to me. He said:'
EXEC add_BibleVerse @BibleId, 124002002, N'“Go and declare in the hearing of the people of Jerusalem: ‘This is what the Lord says: “I have fond memories of you, how devoted you were to me in your early years. I remember how you loved me like a new bride; you followed me through the wilderness, through a land that had never been planted.'
EXEC add_BibleVerse @BibleId, 124002003, N'Israel was set apart to the Lord; they were like the first fruits of a harvest to him. All who tried to devour them were punished; disaster came upon them,” says the Lord.’”'
EXEC add_BibleVerse @BibleId, 124002004, N'Now listen to what the Lord has to say, you descendants of Jacob, all you family groups from the nation of Israel.'
EXEC add_BibleVerse @BibleId, 124002005, N'This is what the Lord says: “What fault could your ancestors have possibly found in me that they strayed so far from me? They paid allegiance to worthless idols, and so became worthless to me.'
EXEC add_BibleVerse @BibleId, 124002006, N'They did not ask: ‘Where is the Lord who delivered us out of Egypt, who brought us through the wilderness, through a land of desert sands and rift valleys, through a land of drought and deep darkness, through a land in which no one travels, and where no one lives?’'
EXEC add_BibleVerse @BibleId, 124002007, N'I brought you into a fertile land so you could enjoy its fruits and its rich bounty. But when you entered my land, you defiled it; you made the land I call my own loathsome to me.'
EXEC add_BibleVerse @BibleId, 124002008, N'Your priests did not ask, ‘Where is the Lord?’ Those responsible for teaching my law did not really know me. Your rulers rebelled against me. Your prophets prophesied in the name of the god Baal. They all worshiped idols that could not help them.'
EXEC add_BibleVerse @BibleId, 124002009, N'“So, once more I will state my case against you,” says the Lord. “I will also state it against your children and grandchildren.'
EXEC add_BibleVerse @BibleId, 124002010, N'Go west across the sea to the coasts of Cyprus and see. Send someone east to Kedar and have them look carefully. See if such a thing as this has ever happened:'
EXEC add_BibleVerse @BibleId, 124002011, N'Has a nation ever changed its gods (even though they are not really gods at all)? But my people have exchanged me, their glorious God, for a god that cannot help them at all!'
EXEC add_BibleVerse @BibleId, 124002012, N'Be amazed at this, O heavens! Be shocked and utterly dumbfounded,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124002013, N'“Do so because my people have committed a double wrong: they have rejected me, the fountain of life-giving water, and they have dug cisterns for themselves, cracked cisterns which cannot even hold water.”'
EXEC add_BibleVerse @BibleId, 124002014, N'“Israel is not a slave, is he? He was not born into slavery, was he? If not, why then is he being carried off?'
EXEC add_BibleVerse @BibleId, 124002015, N'Like lions his enemies roar victoriously over him; they raise their voices in triumph. They have laid his land waste; his cities have been burned down and deserted.'
EXEC add_BibleVerse @BibleId, 124002016, N'Even the soldiers from Memphis and Tahpanhes have cracked your skulls, people of Israel.'
EXEC add_BibleVerse @BibleId, 124002017, N'You have brought all this on yourself, Israel, by deserting the Lord your God when he was leading you along the right path.'
EXEC add_BibleVerse @BibleId, 124002018, N'What good will it do you then to go down to Egypt to seek help from the Egyptians? What good will it do you to go over to Assyria to seek help from the Assyrians?'
EXEC add_BibleVerse @BibleId, 124002019, N'Your own wickedness will bring about your punishment. Your unfaithful acts will bring down discipline on you. Know, then, and realize how utterly harmful it was for you to reject me, the Lord your God, to show no respect for me,” says the Lord God who rules over all.'
EXEC add_BibleVerse @BibleId, 124002020, N'“Indeed, long ago you threw off my authority and refused to be subject to me. You said, ‘I will not serve you.’ Instead, you gave yourself to other gods on every high hill and under every green tree, like a prostitute sprawls out before her lovers.'
EXEC add_BibleVerse @BibleId, 124002021, N'I planted you in the land like a special vine of the very best stock. Why in the world have you turned into something like a wild vine that produces rotten, foul-smelling grapes?'
EXEC add_BibleVerse @BibleId, 124002022, N'You can try to wash away your guilt with a strong detergent. You can use as much soap as you want. But the stain of your guilt is still there for me to see,” says the Lord God.'
EXEC add_BibleVerse @BibleId, 124002023, N'“How can you say, ‘I have not made myself unclean. I have not paid allegiance to the gods called Baal.’ Just look at the way you have behaved in the Valley of Hinnom! Think about the things you have done there! You are like a flighty, young female camel that rushes here and there, crisscrossing its path.'
EXEC add_BibleVerse @BibleId, 124002024, N'You are like a wild female donkey brought up in the wilderness. In her lust she sniffs the wind to get the scent of a male. No one can hold her back when she is in heat. None of the males need wear themselves out chasing after her. At mating time she is easy to find.'
EXEC add_BibleVerse @BibleId, 124002025, N'Do not chase after other gods until your shoes wear out and your throats become dry. But you say, ‘It is useless for you to try and stop me because I love those foreign gods and want to pursue them!’'
EXEC add_BibleVerse @BibleId, 124002026, N'Just as a thief has to suffer dishonor when he is caught, so the people of Israel will suffer dishonor for what they have done. So will their kings and officials, their priests and their prophets.'
EXEC add_BibleVerse @BibleId, 124002027, N'They say to a wooden idol, ‘You are my father.’ They say to a stone image, ‘You gave birth to me.’ Yes, they have turned away from me instead of turning to me. Yet when they are in trouble, they say, ‘Come and save us!’'
EXEC add_BibleVerse @BibleId, 124002028, N'But where are the gods you made for yourselves? Let them save you when you are in trouble. The sad fact is that you have as many gods as you have towns, Judah.'
EXEC add_BibleVerse @BibleId, 124002029, N'“Why do you try to refute me? All of you have rebelled against me,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124002030, N'“It did no good for me to punish your people. They did not respond to such correction. You slaughtered your prophets like a voracious lion.”'
EXEC add_BibleVerse @BibleId, 124002031, N'You people of this generation, listen to what the Lord says. “Have I been like a wilderness to you, Israel? Have I been like a dark and dangerous land to you? Why then do you say, ‘We are free to wander. We will not come to you any more?’'
EXEC add_BibleVerse @BibleId, 124002032, N'Does a young woman forget to put on her jewels? Does a bride forget to put on her bridal attire? But my people have forgotten me for more days than can even be counted.'
EXEC add_BibleVerse @BibleId, 124002033, N'“My, how good you have become at chasing after your lovers! Why, you could even teach prostitutes a thing or two!'
EXEC add_BibleVerse @BibleId, 124002034, N'Even your clothes are stained with the lifeblood of the poor who had not done anything wrong; you did not catch them breaking into your homes. Yet, in spite of all these things you have done,'
EXEC add_BibleVerse @BibleId, 124002035, N'you say, ‘I have not done anything wrong, so the Lord cannot really be angry with me any more.’ But, watch out! I will bring down judgment on you because you say, ‘I have not committed any sin.’'
EXEC add_BibleVerse @BibleId, 124002036, N'Why do you constantly go about changing your political allegiances? You will get no help from Egypt just as you got no help from Assyria.'
EXEC add_BibleVerse @BibleId, 124002037, N'Moreover, you will come away from Egypt with your hands covering your faces in sorrow and shame because the Lord will not allow your reliance on them to be successful and you will not gain any help from them.'
EXEC add_BibleVerse @BibleId, 124003001, N'“If a man divorces his wife and she leaves him and becomes another man’s wife, he may not take her back again. Doing that would utterly defile the land. But you, Israel, have given yourself as a prostitute to many gods. So what makes you think you can return to me?” says the Lord.'
EXEC add_BibleVerse @BibleId, 124003002, N'“Look up at the hilltops and consider this. You have had sex with other gods on every one of them. You waited for those gods like a thief lying in wait in the desert. You defiled the land by your wicked prostitution to other gods.'
EXEC add_BibleVerse @BibleId, 124003003, N'That is why the rains have been withheld, and the spring rains have not come. Yet in spite of this you are obstinate as a prostitute. You refuse to be ashamed of what you have done.'
EXEC add_BibleVerse @BibleId, 124003004, N'Even now you say to me, ‘You are my father! You have been my faithful companion ever since I was young.'
EXEC add_BibleVerse @BibleId, 124003005, N'You will not always be angry with me, will you? You will not be mad at me forever, will you?’ That is what you say, but you continually do all the evil that you can.”'
EXEC add_BibleVerse @BibleId, 124003006, N'When Josiah was king of Judah, the Lord said to me, “Jeremiah, you have no doubt seen what wayward Israel has done. You have seen how she went up to every high hill and under every green tree to give herself like a prostitute to other gods.'
EXEC add_BibleVerse @BibleId, 124003007, N'Yet even after she had done all that, I thought that she might come back to me. But she did not. Her sister, unfaithful Judah, saw what she did.'
EXEC add_BibleVerse @BibleId, 124003008, N'She also saw that I gave wayward Israel her divorce papers and sent her away because of her adulterous worship of other gods. Even after her unfaithful sister Judah had seen this, she still was not afraid, and she too went and gave herself like a prostitute to other gods.'
EXEC add_BibleVerse @BibleId, 124003009, N'Because she took her prostitution so lightly, she defiled the land through her adulterous worship of gods made of wood and stone.'
EXEC add_BibleVerse @BibleId, 124003010, N'In spite of all this, Israel’s sister, unfaithful Judah, has not turned back to me with any sincerity; she has only pretended to do so,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124003011, N'Then the Lord said to me, “Under the circumstances, wayward Israel could even be considered less guilty than unfaithful Judah.'
EXEC add_BibleVerse @BibleId, 124003012, N'“Go and shout this message to my people in the countries in the north. Tell them, ‘Come back to me, wayward Israel,’ says the Lord. ‘I will not continue to look on you with displeasure. For I am merciful,’ says the Lord. ‘I will not be angry with you forever.'
EXEC add_BibleVerse @BibleId, 124003013, N'However, you must confess that you have done wrong, and that you have rebelled against the Lord your God. You must confess that you have given yourself to foreign gods under every green tree, and have not obeyed my commands,’ says the Lord.'
EXEC add_BibleVerse @BibleId, 124003014, N'“Come back to me, my wayward sons,” says the Lord, “for I am your true master. If you do, I will take one of you from each town and two of you from each family group, and I will bring you back to Zion.'
EXEC add_BibleVerse @BibleId, 124003015, N'I will give you leaders who will be faithful to me. They will lead you with knowledge and insight.'
EXEC add_BibleVerse @BibleId, 124003016, N'In those days, your population will greatly increase in the land. At that time,” says the Lord, “people will no longer talk about having the ark that contains the Lord’s covenant with us. They will not call it to mind, remember it, or miss it. No, that will not be done any more!'
EXEC add_BibleVerse @BibleId, 124003017, N'At that time the city of Jerusalem will be called the Lord’s throne. All nations will gather there in Jerusalem to honor the Lord’s name. They will no longer follow the stubborn inclinations of their own evil hearts.'
EXEC add_BibleVerse @BibleId, 124003018, N'At that time the nation of Judah and the nation of Israel will be reunited. Together they will come back from a land in the north to the land that I gave to your ancestors as a permanent possession. ”'
EXEC add_BibleVerse @BibleId, 124003019, N'“I thought to myself, ‘Oh what a joy it would be for me to treat you like a son! What a joy it would be for me to give you a pleasant land, the most beautiful piece of property there is in all the world!’ I thought you would call me, ‘Father’ and would never cease being loyal to me.'
EXEC add_BibleVerse @BibleId, 124003020, N'But, you have been unfaithful to me, nation of Israel, like an unfaithful wife who has left her husband,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124003021, N'“A noise is heard on the hilltops. It is the sound of the people of Israel crying and pleading to their gods. Indeed they have followed sinful ways; they have forgotten to be true to the Lord their God.'
EXEC add_BibleVerse @BibleId, 124003022, N'Come back to me, you wayward people. I want to cure your waywardness. Say, ‘Here we are. We come to you because you are the Lord our God.'
EXEC add_BibleVerse @BibleId, 124003023, N'We know our noisy worship of false gods on the hills and mountains did not help us. We know that the Lord our God is the only one who can deliver Israel.'
EXEC add_BibleVerse @BibleId, 124003024, N'From earliest times our worship of that shameful god, Baal, has taken away all that our ancestors worked for. It has taken away our flocks and our herds, and even our sons and daughters.'
EXEC add_BibleVerse @BibleId, 124003025, N'Let us acknowledge our shame. Let us bear the disgrace that we deserve. For we have sinned against the Lord our God, both we and our ancestors. From earliest times to this very day we have not obeyed the Lord our God.’'
EXEC add_BibleVerse @BibleId, 124004001, N'“If you, Israel, want to come back,” says the Lord, “if you want to come back to me you must get those disgusting idols out of my sight and must no longer go astray.'
EXEC add_BibleVerse @BibleId, 124004002, N'You must be truthful, honest and upright when you take an oath saying, ‘As surely as the Lord lives!’ If you do, the nations will pray to be as blessed by him as you are and will make him the object of their boasting.”'
EXEC add_BibleVerse @BibleId, 124004003, N'Yes, the Lord has this to say to the people of Judah and Jerusalem: “Like a farmer breaking up hard unplowed ground, you must break your rebellious will and make a new beginning; just as a farmer must clear away thorns lest the seed is wasted, you must get rid of the sin that is ruining your lives.'
EXEC add_BibleVerse @BibleId, 124004004, N'Just as ritual circumcision cuts away the foreskin as an external symbol of dedicated covenant commitment, you must genuinely dedicate yourselves to the Lord and get rid of everything that hinders your commitment to me, people of Judah and inhabitants of Jerusalem. If you do not, my anger will blaze up like a flaming fire against you that no one will be able to extinguish. That will happen because of the evil you have done.”'
EXEC add_BibleVerse @BibleId, 124004005, N'The Lord said, “Announce this in Judah and proclaim it in Jerusalem: ‘Sound the trumpet throughout the land!’ Shout out loudly, ‘Gather together! Let us flee into the fortified cities!’'
EXEC add_BibleVerse @BibleId, 124004006, N'Raise a signal flag that tells people to go to Zion. Run for safety! Do not delay! For I am about to bring disaster out of the north. It will bring great destruction.'
EXEC add_BibleVerse @BibleId, 124004007, N'Like a lion that has come up from its lair the one who destroys nations has set out from his home base. He is coming out to lay your land waste. Your cities will become ruins and lie uninhabited.'
EXEC add_BibleVerse @BibleId, 124004008, N'So put on sackcloth! Mourn and wail, saying, ‘The fierce anger of the Lord has not turned away from us!’”'
EXEC add_BibleVerse @BibleId, 124004009, N'“When this happens,” says the Lord, “the king and his officials will lose their courage. The priests will be struck with horror, and the prophets will be speechless in astonishment.”'
EXEC add_BibleVerse @BibleId, 124004010, N'In response to all this I said, “Ah, Lord God, you have surely allowed the people of Judah and Jerusalem to be deceived by those who say, ‘You will be safe!’ But in fact a sword is already at our throats.”'
EXEC add_BibleVerse @BibleId, 124004011, N'“At that time the people of Judah and Jerusalem will be told, ‘A scorching wind will sweep down from the hilltops in the desert on my dear people. It will not be a gentle breeze for winnowing the grain and blowing away the chaff.'
EXEC add_BibleVerse @BibleId, 124004012, N'No, a wind too strong for that will come at my bidding. Yes, even now I, myself, am calling down judgment on them.’'
EXEC add_BibleVerse @BibleId, 124004013, N'Look! The enemy is approaching like gathering clouds. The roar of his chariots is like that of a whirlwind. His horses move more swiftly than eagles.” I cry out, “We are doomed, for we will be destroyed!”'
EXEC add_BibleVerse @BibleId, 124004014, N'“Oh people of Jerusalem, purify your hearts from evil so that you may yet be delivered. How long will you continue to harbor up wicked schemes within you?'
EXEC add_BibleVerse @BibleId, 124004015, N'For messengers are coming, heralding disaster, from the city of Dan and from the hills of Ephraim.'
EXEC add_BibleVerse @BibleId, 124004016, N'They are saying, ‘Announce to the surrounding nations, “The enemy is coming!” Proclaim this message to Jerusalem: “Those who besiege cities are coming from a distant land. They are ready to raise the battle cry against the towns in Judah.”’'
EXEC add_BibleVerse @BibleId, 124004017, N'They will surround Jerusalem like men guarding a field because they have rebelled against me,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124004018, N'“The way you have lived and the things you have done will bring this on you. This is the punishment you deserve, and it will be painful indeed. The pain will be so bad it will pierce your heart.”'
EXEC add_BibleVerse @BibleId, 124004019, N'I said, “Oh, the feeling in the pit of my stomach! I writhe in anguish. Oh, the pain in my heart! My heart pounds within me. I cannot keep silent. For I hear the sound of the trumpet; the sound of the battle cry pierces my soul!'
EXEC add_BibleVerse @BibleId, 124004020, N'I see one destruction after another taking place, so that the whole land lies in ruins. I see our tents suddenly destroyed, their curtains torn down in a mere instant.'
EXEC add_BibleVerse @BibleId, 124004021, N'“How long must I see the enemy’s battle flags and hear the military signals of their bugles?”'
EXEC add_BibleVerse @BibleId, 124004022, N'The Lord answered, “This will happen because my people are foolish. They do not know me. They are like children who have no sense. They have no understanding. They are skilled at doing evil. They do not know how to do good.”'
EXEC add_BibleVerse @BibleId, 124004023, N'“I looked at the land and saw that it was an empty wasteland. I looked up at the sky, and its light had vanished.'
EXEC add_BibleVerse @BibleId, 124004024, N'I looked at the mountains and saw that they were shaking. All the hills were swaying back and forth!'
EXEC add_BibleVerse @BibleId, 124004025, N'I looked and saw that there were no more people, and that all the birds in the sky had flown away.'
EXEC add_BibleVerse @BibleId, 124004026, N'I looked and saw that the fruitful land had become a desert and that all of the cities had been laid in ruins. The Lord had brought this all about because of his blazing anger.'
EXEC add_BibleVerse @BibleId, 124004027, N'All this will happen because the Lord said, “The whole land will be desolate; however, I will not completely destroy it.'
EXEC add_BibleVerse @BibleId, 124004028, N'Because of this the land will mourn and the sky above will grow black. For I have made my purpose known and I will not relent or turn back from carrying it out.”'
EXEC add_BibleVerse @BibleId, 124004029, N'At the sound of the approaching horsemen and archers the people of every town will flee. Some of them will hide in the thickets. Others will climb up among the rocks. All the cities will be deserted. No one will remain in them.'
EXEC add_BibleVerse @BibleId, 124004030, N'And you, Zion, city doomed to destruction, you accomplish nothing by wearing a beautiful dress, decking yourself out in jewels of gold, and putting on eye shadow! You are making yourself beautiful for nothing. Your lovers spurn you. They want to kill you.'
EXEC add_BibleVerse @BibleId, 124004031, N'In fact, I hear a cry like that of a woman in labor, a cry of anguish like that of a woman giving birth to her first baby. It is the cry of Daughter Zion gasping for breath, reaching out for help, saying, “I am done in! My life is ebbing away before these murderers!”'
EXEC add_BibleVerse @BibleId, 124005001, N'The Lord said, “Go up and down through the streets of Jerusalem. Look around and see for yourselves. Search through its public squares. See if any of you can find a single person who deals honestly and tries to be truthful. If you can, then I will not punish this city.'
EXEC add_BibleVerse @BibleId, 124005002, N'These people make promises in the name of the Lord. But the fact is, what they swear to is really a lie.”'
EXEC add_BibleVerse @BibleId, 124005003, N'Lord, I know you look for faithfulness. But even when you punish these people, they feel no remorse. Even when you nearly destroy them, they refuse to be corrected. They have become as hardheaded as a rock. They refuse to change their ways.'
EXEC add_BibleVerse @BibleId, 124005004, N'I thought, “Surely it is only the ignorant poor who act this way. They act like fools because they do not know what the Lord demands. They do not know what their God requires of them.'
EXEC add_BibleVerse @BibleId, 124005005, N'I will go to the leaders and speak with them. Surely they know what the Lord demands. Surely they know what their God requires of them.” Yet all of them, too, have rejected his authority and refuse to submit to him.'
EXEC add_BibleVerse @BibleId, 124005006, N'So like a lion from the thicket their enemies will kill them. Like a wolf from the desert they will destroy them. Like a leopard they will lie in wait outside their cities and totally destroy anyone who ventures out. For they have rebelled so much and done so many unfaithful things.'
EXEC add_BibleVerse @BibleId, 124005007, N'The Lord asked, “How can I leave you unpunished, Jerusalem? Your people have rejected me and have worshiped gods that are not gods at all. Even though I supplied all their needs, they were like an unfaithful wife to me. They went flocking to the houses of prostitutes.'
EXEC add_BibleVerse @BibleId, 124005008, N'They are like lusty, well-fed stallions. Each of them lusts after his neighbor’s wife.'
EXEC add_BibleVerse @BibleId, 124005009, N'I will surely punish them for doing such things!” says the Lord. “I will surely bring retribution on such a nation as this!”'
EXEC add_BibleVerse @BibleId, 124005010, N'The Lord commanded the enemy, “March through the vineyards of Israel and Judah and ruin them. But do not destroy them completely. Strip off their branches for these people do not belong to the Lord.'
EXEC add_BibleVerse @BibleId, 124005011, N'For the nations of Israel and Judah have been very unfaithful to me,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124005012, N'“These people have denied what the Lord says. They have said, ‘That is not so! No harm will come to us. We will not experience war and famine.'
EXEC add_BibleVerse @BibleId, 124005013, N'The prophets will prove to be full of wind. The Lord has not spoken through them. So, let what they say happen to them.’”'
EXEC add_BibleVerse @BibleId, 124005014, N'Because of that, the Lord, the God who rules over all, said to me, “Because these people have spoken like this, I will make the words that I put in your mouth like fire. And I will make this people like wood which the fiery judgments you speak will burn up.”'
EXEC add_BibleVerse @BibleId, 124005015, N'The Lord says, “Listen, nation of Israel! I am about to bring a nation from far away to attack you. It will be a nation that was founded long ago and has lasted for a long time. It will be a nation whose language you will not know. Its people will speak words that you will not be able to understand.'
EXEC add_BibleVerse @BibleId, 124005016, N'All of its soldiers are strong and mighty. Their arrows will send you to your grave.'
EXEC add_BibleVerse @BibleId, 124005017, N'They will eat up your crops and your food. They will kill off your sons and your daughters. They will eat up your sheep and your cattle. They will destroy your vines and your fig trees. Their weapons will batter down the fortified cities you trust in.'
EXEC add_BibleVerse @BibleId, 124005018, N'Yet even then I will not completely destroy you,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124005019, N'“So then, Jeremiah, when your people ask, ‘Why has the Lord our God done all this to us?’ tell them, ‘It is because you rejected me and served foreign gods in your own land. So you must serve foreigners in a land that does not belong to you.’'
EXEC add_BibleVerse @BibleId, 124005020, N'“Proclaim this message among the descendants of Jacob. Make it known throughout Judah.'
EXEC add_BibleVerse @BibleId, 124005021, N'Tell them: ‘Hear this, you foolish people who have no understanding, who have eyes but do not discern, who have ears but do not perceive:'
EXEC add_BibleVerse @BibleId, 124005022, N'“You should fear me!” says the Lord. “You should tremble in awe before me! I made the sand to be a boundary for the sea, a permanent barrier that it can never cross. Its waves may roll, but they can never prevail. They may roar, but they can never cross beyond that boundary.”'
EXEC add_BibleVerse @BibleId, 124005023, N'But these people have stubborn and rebellious hearts. They have turned aside and gone their own way.'
EXEC add_BibleVerse @BibleId, 124005024, N'They do not say to themselves, “Let us revere the Lord our God. It is he who gives us the autumn rains and the spring rains at the proper time. It is he who assures us of the regular weeks of harvest.”'
EXEC add_BibleVerse @BibleId, 124005025, N'Your misdeeds have stopped these things from coming. Your sins have deprived you of my bounty.’'
EXEC add_BibleVerse @BibleId, 124005026, N'“Indeed, there are wicked scoundrels among my people. They lie in wait like bird catchers hiding in ambush. They set deadly traps to catch people.'
EXEC add_BibleVerse @BibleId, 124005027, N'Like a cage filled with the birds that have been caught, their houses are filled with the gains of their fraud and deceit. That is how they have gotten so rich and powerful.'
EXEC add_BibleVerse @BibleId, 124005028, N'That is how they have grown fat and sleek. There is no limit to the evil things they do. They do not plead the cause of the fatherless in such a way as to win it. They do not defend the rights of the poor.'
EXEC add_BibleVerse @BibleId, 124005029, N'I will certainly punish them for doing such things!” says the Lord. “I will certainly bring retribution on such a nation as this!'
EXEC add_BibleVerse @BibleId, 124005030, N'“Something horrible and shocking is going on in the land of Judah:'
EXEC add_BibleVerse @BibleId, 124005031, N'The prophets prophesy lies. The priests exercise power by their own authority. And my people love to have it this way. But they will not be able to help you when the time of judgment comes!'
EXEC add_BibleVerse @BibleId, 124006001, N'“Run for safety, people of Benjamin! Get out of Jerusalem! Sound the trumpet in Tekoa! Light the signal fires at Beth Hakkerem! For disaster lurks out of the north; it will bring great destruction.'
EXEC add_BibleVerse @BibleId, 124006002, N'I will destroy Daughter Zion, who is as delicate and defenseless as a young maiden.'
EXEC add_BibleVerse @BibleId, 124006003, N'Kings will come against it with their armies. They will encamp in siege all around it. Each of them will devastate the portion assigned to him.'
EXEC add_BibleVerse @BibleId, 124006004, N'They will say, ‘Prepare to do battle against it! Come on! Let’s attack it at noon!’ But later they will say, ‘Oh, oh! Too bad! The day is almost over and the shadows of evening are getting long.'
EXEC add_BibleVerse @BibleId, 124006005, N'So come on, let’s go ahead and attack it by night and destroy all its fortified buildings.’'
EXEC add_BibleVerse @BibleId, 124006006, N'All of this is because the Lord who rules over all has said: ‘Cut down the trees around Jerusalem and build up a siege ramp against its walls. This is the city which is to be punished. Nothing but oppression happens in it.'
EXEC add_BibleVerse @BibleId, 124006007, N'As a well continually pours out fresh water so it continually pours out wicked deeds. Sounds of violence and destruction echo throughout it. All I see are sick and wounded people.’'
EXEC add_BibleVerse @BibleId, 124006008, N'So take warning, Jerusalem, or I will abandon you in disgust and make you desolate, a place where no one can live.”'
EXEC add_BibleVerse @BibleId, 124006009, N'This is what the Lord who rules over all said to me: “Those who remain in Israel will be like the grapes thoroughly gleaned from a vine. So go over them again, as though you were a grape harvester passing your hand over the branches one last time.”'
EXEC add_BibleVerse @BibleId, 124006010, N'I answered, “Who would listen if I spoke to them and warned them? Their ears are so closed that they cannot hear! Indeed, what the Lord says is offensive to them. They do not like it at all.'
EXEC add_BibleVerse @BibleId, 124006011, N'I am as full of anger as you are, Lord, I am tired of trying to hold it in.” The Lord answered, “Vent it, then, on the children who play in the street and on the young men who are gathered together. Husbands and wives are to be included, as well as the old and those who are advanced in years.'
EXEC add_BibleVerse @BibleId, 124006012, N'Their houses will be turned over to others as will their fields and their wives. For I will unleash my power against those who live in this land,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124006013, N'“That is because, from the least important to the most important of them, all of them are greedy for dishonest gain. Prophets and priests alike, all of them practice deceit.'
EXEC add_BibleVerse @BibleId, 124006014, N'They offer only superficial help for the harm my people have suffered. They say, ‘Everything will be all right!’ But everything is not all right!'
EXEC add_BibleVerse @BibleId, 124006015, N'Are they ashamed because they have done such shameful things? No, they are not at all ashamed. They do not even know how to blush! So they will die, just like others have died. They will be brought to ruin when I punish them,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124006016, N'The Lord said to his people: “You are standing at the crossroads. So consider your path. Ask where the old, reliable paths are. Ask where the path is that leads to blessing and follow it. If you do, you will find rest for your souls.” But they said, “We will not follow it!”'
EXEC add_BibleVerse @BibleId, 124006017, N'The Lord said, “I appointed prophets as watchmen to warn you, saying: ‘Pay attention to the warning sound of the trumpet!’” But they said, “We will not pay attention!”'
EXEC add_BibleVerse @BibleId, 124006018, N'So the Lord said, “Hear, you nations! Be witnesses and take note of what will happen to these people.'
EXEC add_BibleVerse @BibleId, 124006019, N'Hear this, you peoples of the earth: ‘Take note! I am about to bring disaster on these people. It will come as punishment for their scheming. For they have paid no attention to what I have said, and they have rejected my law.'
EXEC add_BibleVerse @BibleId, 124006020, N'I take no delight when they offer up to me frankincense that comes from Sheba or sweet-smelling cane imported from a faraway land. I cannot accept the burnt offerings they bring me. I get no pleasure from the sacrifices they offer to me.’'
EXEC add_BibleVerse @BibleId, 124006021, N'So, this is what the Lord says: ‘I will assuredly make these people stumble to their doom. Parents and children will stumble and fall to their destruction. Friends and neighbors will die.’'
EXEC add_BibleVerse @BibleId, 124006022, N'“This is what the Lord says: ‘Beware! An army is coming from a land in the north. A mighty nation is stirring into action in faraway parts of the earth.'
EXEC add_BibleVerse @BibleId, 124006023, N'Its soldiers are armed with bows and spears. They are cruel and show no mercy. They sound like the roaring sea as they ride forth on their horses. Lined up in formation like men going into battle to attack you, Daughter Zion.’”'
EXEC add_BibleVerse @BibleId, 124006024, N'The people cry out, “We have heard reports about them! We have become helpless with fear! Anguish grips us, agony like that of a woman giving birth to a baby!'
EXEC add_BibleVerse @BibleId, 124006025, N'Do not go out into the countryside. Do not travel on the roads. For the enemy is there with sword in hand. They are spreading terror everywhere.”'
EXEC add_BibleVerse @BibleId, 124006026, N'So I said, “Oh, my dear people, put on sackcloth and roll in ashes. Mourn with painful sobs as though you had lost your only child. For any moment now that destructive army will come against us.”'
EXEC add_BibleVerse @BibleId, 124006027, N'The Lord said to me, “I have made you like a metal assayer to test my people like ore. You are to observe them and evaluate how they behave.”'
EXEC add_BibleVerse @BibleId, 124006028, N'I reported, “All of them are the most stubborn of rebels! They are as hard as bronze or iron. They go about telling lies. They all deal corruptly.'
EXEC add_BibleVerse @BibleId, 124006029, N'The fiery bellows of judgment burn fiercely. But there is too much dross to be removed. The process of refining them has proved useless. The wicked have not been purged.'
EXEC add_BibleVerse @BibleId, 124006030, N'They are regarded as ‘rejected silver’ because the Lord rejects them.”'
EXEC add_BibleVerse @BibleId, 124007001, N'The Lord said to Jeremiah:'
EXEC add_BibleVerse @BibleId, 124007002, N'“Stand in the gate of the Lord’s temple and proclaim this message: ‘Listen, all you people of Judah who have passed through these gates to worship the Lord. Hear what the Lord has to say.'
EXEC add_BibleVerse @BibleId, 124007003, N'The Lord God of Israel who rules over all says: Change the way you have been living and do what is right. If you do, I will allow you to continue to live in this land.'
EXEC add_BibleVerse @BibleId, 124007004, N'Stop putting your confidence in the false belief that says, “We are safe! The temple of the Lord is here! The temple of the Lord is here! The temple of the Lord is here!”'
EXEC add_BibleVerse @BibleId, 124007005, N'You must change the way you have been living and do what is right. You must treat one another fairly.'
EXEC add_BibleVerse @BibleId, 124007006, N'Stop oppressing foreigners who live in your land, children who have lost their fathers, and women who have lost their husbands. Stop killing innocent people in this land. Stop paying allegiance to other gods. That will only bring about your ruin.'
EXEC add_BibleVerse @BibleId, 124007007, N'If you stop doing these things, I will allow you to continue to live in this land which I gave to your ancestors as a lasting possession.'
EXEC add_BibleVerse @BibleId, 124007008, N'“‘But just look at you! You are putting your confidence in a false belief that will not deliver you.'
EXEC add_BibleVerse @BibleId, 124007009, N'You steal. You murder. You commit adultery. You lie when you swear on oath. You sacrifice to the god Baal. You pay allegiance to other gods whom you have not previously known.'
EXEC add_BibleVerse @BibleId, 124007010, N'Then you come and stand in my presence in this temple I have claimed as my own and say, “We are safe!” You think you are so safe that you go on doing all those hateful sins!'
EXEC add_BibleVerse @BibleId, 124007011, N'Do you think this temple I have claimed as my own is to be a hideout for robbers? You had better take note! I have seen for myself what you have done! says the Lord.'
EXEC add_BibleVerse @BibleId, 124007012, N'So, go to the place in Shiloh where I allowed myself to be worshiped in the early days. See what I did to it because of the wicked things my people Israel did.'
EXEC add_BibleVerse @BibleId, 124007013, N'You also have done all these things, says the Lord, and I have spoken to you over and over again. But you have not listened! You have refused to respond when I called you to repent!'
EXEC add_BibleVerse @BibleId, 124007014, N'So I will destroy this temple which I have claimed as my own, this temple that you are trusting to protect you. I will destroy this place that I gave to you and your ancestors, just like I destroyed Shiloh.'
EXEC add_BibleVerse @BibleId, 124007015, N'And I will drive you out of my sight just like I drove out your relatives, the people of Israel.’”'
EXEC add_BibleVerse @BibleId, 124007016, N'Then the Lord said, “As for you, Jeremiah, do not pray for these people! Do not cry out to me or petition me on their behalf! Do not plead with me to save them, because I will not listen to you.'
EXEC add_BibleVerse @BibleId, 124007017, N'Do you see what they are doing in the towns of Judah and in the streets of Jerusalem?'
EXEC add_BibleVerse @BibleId, 124007018, N'Children are gathering firewood, fathers are building fires with it, and women are mixing dough to bake cakes to offer to the goddess they call the Queen of Heaven. They are also pouring out drink offerings to other gods. They seem to do all this just to trouble me.'
EXEC add_BibleVerse @BibleId, 124007019, N'But I am not really the one being troubled!” says the Lord. “Rather they are bringing trouble on themselves to their own shame!'
EXEC add_BibleVerse @BibleId, 124007020, N'So,” the Lord God says, “my raging fury will be poured out on this land. It will be poured out on human beings and animals, on trees and crops. And it will burn like a fire which cannot be extinguished.”'
EXEC add_BibleVerse @BibleId, 124007021, N'The Lord said to the people of Judah, “The Lord God of Israel who rules over all says: ‘You might as well go ahead and add the meat of your burnt offerings to that of the other sacrifices and eat it, too!'
EXEC add_BibleVerse @BibleId, 124007022, N'Consider this: When I spoke to your ancestors after I brought them out of Egypt, I did not merely give them commands about burnt offerings and sacrifices.'
EXEC add_BibleVerse @BibleId, 124007023, N'I also explicitly commanded them: “Obey me. If you do, I will be your God and you will be my people. Live exactly the way I tell you and things will go well with you.”'
EXEC add_BibleVerse @BibleId, 124007024, N'But they did not listen to me or pay any attention to me. They followed the stubborn inclinations of their own wicked hearts. They acted worse and worse instead of better.'
EXEC add_BibleVerse @BibleId, 124007025, N'From the time your ancestors departed the land of Egypt until now, I sent my servants the prophets to you again and again, day after day.'
EXEC add_BibleVerse @BibleId, 124007026, N'But your ancestors did not listen to me nor pay attention to me. They became obstinate and were more wicked than even their own forefathers.’”'
EXEC add_BibleVerse @BibleId, 124007027, N'Then the Lord said to me, “When you tell them all this, they will not listen to you. When you call out to them, they will not respond to you.'
EXEC add_BibleVerse @BibleId, 124007028, N'So tell them: ‘This is a nation that has not obeyed the Lord their God and has not accepted correction. Faithfulness is nowhere to be found in it. These people do not even profess it anymore.'
EXEC add_BibleVerse @BibleId, 124007029, N'So, mourn, you people of this nation. Cut off your hair and throw it away. Sing a song of mourning on the hilltops. For the Lord has decided to reject and forsake this generation that has provoked his wrath!’”'
EXEC add_BibleVerse @BibleId, 124007030, N'The Lord says, “I have rejected them because the people of Judah have done what I consider evil. They have set up their disgusting idols in the temple which I have claimed for my own and have defiled it.'
EXEC add_BibleVerse @BibleId, 124007031, N'They have also built places of worship in a place called Topheth in the Valley of Ben Hinnom so that they can sacrifice their sons and daughters by fire. That is something I never commanded them to do! Indeed, it never even entered my mind to command such a thing!'
EXEC add_BibleVerse @BibleId, 124007032, N'So, watch out!” says the Lord. “The time will soon come when people will no longer call those places Topheth or the Valley of Ben Hinnom. But they will call that valley the Valley of Slaughter and they will bury so many people in Topheth they will run out of room.'
EXEC add_BibleVerse @BibleId, 124007033, N'Then the dead bodies of these people will be left on the ground for the birds and wild animals to eat. There will not be any survivors to scare them away.'
EXEC add_BibleVerse @BibleId, 124007034, N'I will put an end to the sounds of joy and gladness, or the glad celebration of brides and grooms throughout the towns of Judah and the streets of Jerusalem. For the whole land will become a desolate wasteland.”'
EXEC add_BibleVerse @BibleId, 124008001, N'The Lord says, “When that time comes, the bones of the kings of Judah and its leaders, the bones of the priests and prophets and of all the other people who lived in Jerusalem will be dug up from their graves.'
EXEC add_BibleVerse @BibleId, 124008002, N'They will be spread out and exposed to the sun, the moon and the stars. These are things they adored and served, things to which they paid allegiance, from which they sought guidance, and worshiped. The bones of these people will never be regathered and reburied. They will be like manure used to fertilize the ground.'
EXEC add_BibleVerse @BibleId, 124008003, N'However, I will leave some of these wicked people alive and banish them to other places. But wherever these people who survive may go, they will wish they had died rather than lived,” says the Lord who rules over all.'
EXEC add_BibleVerse @BibleId, 124008004, N'The Lord said to me, “Tell them, ‘The Lord says, Do people not get back up when they fall down? Do they not turn around when they go the wrong way?'
EXEC add_BibleVerse @BibleId, 124008005, N'Why, then, do these people of Jerusalem continually turn away from me in apostasy? They hold fast to their deception. They refuse to turn back to me.'
EXEC add_BibleVerse @BibleId, 124008006, N'I have listened to them very carefully, but they do not speak honestly. None of them regrets the evil he has done. None of them says, “I have done wrong!” All of them persist in their own wayward course like a horse charging recklessly into battle.'
EXEC add_BibleVerse @BibleId, 124008007, N'Even the stork knows when it is time to move on. The turtledove, swallow, and crane recognize the normal times for their migration. But my people pay no attention to what I, the Lord, require of them.'
EXEC add_BibleVerse @BibleId, 124008008, N'How can you say, “We are wise! We have the law of the Lord”? The truth is, those who teach it have used their writings to make it say what it does not really mean.'
EXEC add_BibleVerse @BibleId, 124008009, N'Your wise men will be put to shame. They will be dumbfounded and be brought to judgment. Since they have rejected the word of the Lord, what wisdom do they really have?'
EXEC add_BibleVerse @BibleId, 124008010, N'So I will give their wives to other men and their fields to new owners. For from the least important to the most important of them, all of them are greedy for dishonest gain. Prophets and priests alike, all practice deceit.'
EXEC add_BibleVerse @BibleId, 124008011, N'They offer only superficial help for the hurt my dear people have suffered. They say, “Everything will be all right!” But everything is not all right!'
EXEC add_BibleVerse @BibleId, 124008012, N'Are they ashamed because they have done such disgusting things? No, they are not at all ashamed! They do not even know how to blush! So they will die just like others have died. They will be brought to ruin when I punish them, says the Lord.'
EXEC add_BibleVerse @BibleId, 124008013, N'I will take away their harvests, says the Lord. There will be no grapes on their vines. There will be no figs on their fig trees. Even the leaves on their trees will wither. The crops that I gave them will be taken away.’”'
EXEC add_BibleVerse @BibleId, 124008014, N'The people say, “Why are we just sitting here? Let us gather together inside the fortified cities. Let us at least die there fighting, since the Lord our God has condemned us to die. He has condemned us to drink the poison waters of judgment because we have sinned against him.'
EXEC add_BibleVerse @BibleId, 124008015, N'We hoped for good fortune, but nothing good has come of it. We hoped for a time of relief, but instead we experience terror.'
EXEC add_BibleVerse @BibleId, 124008016, N'The snorting of the enemy’s horses is already being heard in the city of Dan. The sound of the neighing of their stallions causes the whole land to tremble with fear. They are coming to destroy the land and everything in it! They are coming to destroy the cities and everyone who lives in them!”'
EXEC add_BibleVerse @BibleId, 124008017, N'The Lord says, “Yes indeed, I am sending an enemy against you that will be like poisonous snakes which cannot be charmed away. And they will inflict fatal wounds on you.”'
EXEC add_BibleVerse @BibleId, 124008018, N'Then I said, “There is no cure for my grief! I am sick at heart!'
EXEC add_BibleVerse @BibleId, 124008019, N'I hear my dear people crying out throughout the length and breadth of the land. They are crying, ‘Is the Lord no longer in Zion? Is her divine King no longer there?’” The Lord answers, “Why then do they provoke me to anger with their images, with their worthless foreign idols?”'
EXEC add_BibleVerse @BibleId, 124008020, N'“They cry, ‘Harvest time has come and gone, and the summer is over, and still we have not been delivered.’'
EXEC add_BibleVerse @BibleId, 124008021, N'My heart is crushed because my dear people are being crushed. I go about crying and grieving. I am overwhelmed with dismay.'
EXEC add_BibleVerse @BibleId, 124008022, N'There is still medicinal ointment available in Gilead! There is still a physician there! Why then have my dear people not been restored to health?'
EXEC add_BibleVerse @BibleId, 124009001, N'I wish that my head were a well full of water and my eyes were a fountain full of tears! If they were, I could cry day and night for those of my dear people who have been killed.'
EXEC add_BibleVerse @BibleId, 124009002, N'I wish I had a lodging place in the desert where I could spend some time like a weary traveler. Then I would desert my people and walk away from them because they are all unfaithful to God, a congregation of people that has been disloyal to him.'
EXEC add_BibleVerse @BibleId, 124009003, N'The Lord says, “These people are like soldiers who have readied their bows. Their tongues are always ready to shoot out lies. They have become powerful in the land, but they have not done so by honest means. Indeed, they do one evil thing after another and do not pay attention to me.'
EXEC add_BibleVerse @BibleId, 124009004, N'Everyone must be on his guard around his friends. He must not even trust any of his relatives. For every one of them will find some way to cheat him. And all of his friends will tell lies about him.'
EXEC add_BibleVerse @BibleId, 124009005, N'One friend deceives another and no one tells the truth. These people have trained themselves to tell lies. They do wrong and are unable to repent.'
EXEC add_BibleVerse @BibleId, 124009006, N'They do one act of violence after another, and one deceitful thing after another. They refuse to pay attention to me,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124009007, N'Therefore the Lord who rules over all says, “I will now purify them in the fires of affliction and test them. The wickedness of my dear people has left me no choice. What else can I do?'
EXEC add_BibleVerse @BibleId, 124009008, N'Their tongues are like deadly arrows. They are always telling lies. Friendly words for their neighbors come from their mouths. But their minds are thinking up ways to trap them.'
EXEC add_BibleVerse @BibleId, 124009009, N'I will certainly punish them for doing such things!” says the Lord. “I will certainly bring retribution on such a nation as this!”'
EXEC add_BibleVerse @BibleId, 124009010, N'I said, “I will weep and mourn for the grasslands on the mountains, I will sing a mournful song for the pastures in the wilderness because they are so scorched no one travels through them. The sound of livestock is no longer heard there. Even the birds in the sky and the wild animals in the fields have fled and are gone.”'
EXEC add_BibleVerse @BibleId, 124009011, N'The Lord said, “I will make Jerusalem a heap of ruins. Jackals will make their home there. I will destroy the towns of Judah so that no one will be able to live in them.”'
EXEC add_BibleVerse @BibleId, 124009012, N'I said, “Who is wise enough to understand why this has happened? Who has a word from the Lord that can explain it? Why does the land lie in ruins? Why is it as scorched as a desert through which no one travels?”'
EXEC add_BibleVerse @BibleId, 124009013, N'The Lord answered, “This has happened because these people have rejected my laws which I gave them. They have not obeyed me or followed those laws.'
EXEC add_BibleVerse @BibleId, 124009014, N'Instead they have followed the stubborn inclinations of their own hearts. They have paid allegiance to the gods called Baal, as their fathers taught them to do.'
EXEC add_BibleVerse @BibleId, 124009015, N'So then, listen to what I, the Lord God of Israel who rules over all, say. ‘I will make these people eat the bitter food of suffering and drink the poison water of judgment.'
EXEC add_BibleVerse @BibleId, 124009016, N'I will scatter them among nations that neither they nor their ancestors have known anything about. I will send people chasing after them with swords until I have destroyed them.’”'
EXEC add_BibleVerse @BibleId, 124009017, N'The Lord who rules over all told me to say to this people, “Take note of what I say. Call for the women who mourn for the dead! Summon those who are the most skilled at it!”'
EXEC add_BibleVerse @BibleId, 124009018, N'I said, “Indeed, let them come quickly and sing a song of mourning for us. Let them wail loudly until tears stream from our own eyes and our eyelids overflow with water.'
EXEC add_BibleVerse @BibleId, 124009019, N'For the sound of wailing is soon to be heard in Zion. They will wail, ‘We are utterly ruined! We are completely disgraced! For our houses have been torn down and we must leave our land.’”'
EXEC add_BibleVerse @BibleId, 124009020, N'I said, “So now, you wailing women, hear what the Lord says. Open your ears to the words from his mouth. Teach your daughters this mournful song, and each of you teach your neighbor this lament.'
EXEC add_BibleVerse @BibleId, 124009021, N'‘Death has climbed in through our windows. It has entered into our fortified houses. It has taken away our children who play in the streets. It has taken away our young men who gather in the city squares.’'
EXEC add_BibleVerse @BibleId, 124009022, N'Tell your daughters and neighbors, ‘The Lord says, “The dead bodies of people will lie scattered everywhere like manure scattered on a field. They will lie scattered on the ground like grain that has been cut down but has not been gathered.”’”'
EXEC add_BibleVerse @BibleId, 124009023, N'The Lord says, “Wise people should not boast that they are wise. Powerful people should not boast that they are powerful. Rich people should not boast that they are rich.'
EXEC add_BibleVerse @BibleId, 124009024, N'If people want to boast, they should boast about this: They should boast that they understand and know me. They should boast that they know and understand that I, the Lord, act out of faithfulness, fairness, and justice in the earth and that I desire people to do these things,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124009025, N'The Lord says, “Watch out! The time is soon coming when I will punish all those who are circumcised only in the flesh.'
EXEC add_BibleVerse @BibleId, 124009026, N'That is, I will punish the Egyptians, the Judeans, the Edomites, the Ammonites, the Moabites, and all the desert people who cut their hair short at the temples. I will do so because none of the people of those nations are really circumcised in the Lord’s sight. Moreover, none of the people of Israel are circumcised when it comes to their hearts.”'
EXEC add_BibleVerse @BibleId, 124010001, N'You people of Israel, listen to what the Lord has to say to you.'
EXEC add_BibleVerse @BibleId, 124010002, N'The Lord says, “Do not start following pagan religious practices. Do not be in awe of signs that occur in the sky even though the nations hold them in awe.'
EXEC add_BibleVerse @BibleId, 124010003, N'For the religion of these people is worthless. They cut down a tree in the forest, and a craftsman makes it into an idol with his tools.'
EXEC add_BibleVerse @BibleId, 124010004, N'He decorates it with overlays of silver and gold. He uses hammer and nails to fasten it together so that it will not fall over.'
EXEC add_BibleVerse @BibleId, 124010005, N'Such idols are like scarecrows in a cucumber field. They cannot talk. They must be carried because they cannot walk. Do not be afraid of them because they cannot hurt you. And they do not have any power to help you.”'
EXEC add_BibleVerse @BibleId, 124010006, N'I said, “There is no one like you, Lord. You are great. And you are renowned for your power.'
EXEC add_BibleVerse @BibleId, 124010007, N'Everyone should revere you, O King of all nations, because you deserve to be revered. For there is no one like you among any of the wise people of the nations nor among any of their kings.'
EXEC add_BibleVerse @BibleId, 124010008, N'The people of those nations are both stupid and foolish. Instruction from a wooden idol is worthless!'
EXEC add_BibleVerse @BibleId, 124010009, N'Hammered-out silver is brought from Tarshish and gold is brought from Uphaz to cover those idols. They are the handiwork of carpenters and goldsmiths. They are clothed in blue and purple clothes. They are all made by skillful workers.'
EXEC add_BibleVerse @BibleId, 124010010, N'The Lord is the only true God. He is the living God and the everlasting King. When he shows his anger the earth shakes. None of the nations can stand up to his fury.'
EXEC add_BibleVerse @BibleId, 124010011, N'You people of Israel should tell those nations this: ‘These gods did not make heaven and earth. They will disappear from the earth and from under the heavens.’'
EXEC add_BibleVerse @BibleId, 124010012, N'The Lord is the one who by his power made the earth. He is the one who by his wisdom established the world. And by his understanding he spread out the skies.'
EXEC add_BibleVerse @BibleId, 124010013, N'When his voice thunders, the heavenly ocean roars. He makes the clouds rise from the far-off horizons. He makes the lightning flash out in the midst of the rain. He unleashes the wind from the places where he stores it.'
EXEC add_BibleVerse @BibleId, 124010014, N'All these idolaters will prove to be stupid and ignorant. Every goldsmith will be disgraced by the idol he made. For the image he forges is merely a sham. There is no breath in any of those idols.'
EXEC add_BibleVerse @BibleId, 124010015, N'They are worthless, mere objects to be mocked. When the time comes to punish them, they will be destroyed.'
EXEC add_BibleVerse @BibleId, 124010016, N'The Lord, who is the inheritance of Jacob’s descendants, is not like them. He is the one who created everything. And the people of Israel are those he claims as his own. He is known as the Lord who rules over all.”'
EXEC add_BibleVerse @BibleId, 124010017, N'Gather your belongings together and prepare to leave the land, you people of Jerusalem who are being besieged.'
EXEC add_BibleVerse @BibleId, 124010018, N'For the Lord says, “I will now throw out those who live in this land. I will bring so much trouble on them that they will actually feel it.”'
EXEC add_BibleVerse @BibleId, 124010019, N'And I cried out, “We are doomed! Our wound is severe! We once thought, ‘This is only an illness. And we will be able to bear it!’'
EXEC add_BibleVerse @BibleId, 124010020, N'But our tents have been destroyed. The ropes that held them in place have been ripped apart. Our children are gone and are not coming back. There is no survivor to put our tents back up, no one left to hang their tent curtains in place.'
EXEC add_BibleVerse @BibleId, 124010021, N'For our leaders are stupid. They have not sought the Lord’s advice. So they do not act wisely, and the people they are responsible for have all been scattered.'
EXEC add_BibleVerse @BibleId, 124010022, N'Listen! News is coming even now. The rumble of a great army is heard approaching from a land in the north. It is coming to turn the towns of Judah into rubble, places where only jackals live.'
EXEC add_BibleVerse @BibleId, 124010023, N'Lord, we know that people do not control their own destiny. It is not in their power to determine what will happen to them.'
EXEC add_BibleVerse @BibleId, 124010024, N'Correct us, Lord, but only in due measure. Do not punish us in anger or you will reduce us to nothing.'
EXEC add_BibleVerse @BibleId, 124010025, N'Vent your anger on the nations that do not acknowledge you. Vent it on the peoples who do not worship you. For they have destroyed the people of Jacob. They have completely destroyed them and left their homeland in utter ruin.'
EXEC add_BibleVerse @BibleId, 124011001, N'The Lord said to Jeremiah:'
EXEC add_BibleVerse @BibleId, 124011002, N'“Hear the terms of the covenant I made with Israel and pass them on to the people of Judah and the citizens of Jerusalem.'
EXEC add_BibleVerse @BibleId, 124011003, N'Tell them that the Lord, the God of Israel, says, ‘Anyone who does not keep the terms of the covenant will be under a curse.'
EXEC add_BibleVerse @BibleId, 124011004, N'Those are the terms that I charged your ancestors to keep when I brought them out of Egypt, that place which was like an iron-smelting furnace. I said at that time, “Obey me and carry out the terms of the agreement exactly as I commanded you. If you do, you will be my people and I will be your God.'
EXEC add_BibleVerse @BibleId, 124011005, N'Then I will keep the promise I swore on oath to your ancestors to give them a land flowing with milk and honey.” That is the very land that you still live in today.’” And I responded, “Amen! Let it be so, Lord!”'
EXEC add_BibleVerse @BibleId, 124011006, N'The Lord said to me, “Announce all the following words in the towns of Judah and in the streets of Jerusalem: ‘Listen to the terms of my covenant with you and carry them out!'
EXEC add_BibleVerse @BibleId, 124011007, N'For I solemnly warned your ancestors to obey me. I warned them again and again, ever since I delivered them out of Egypt until this very day.'
EXEC add_BibleVerse @BibleId, 124011008, N'But they did not listen to me or pay any attention to me! Each one of them followed the stubborn inclinations of his own wicked heart. So I brought on them all the punishments threatened in the covenant because they did not carry out its terms as I commanded them to do.’”'
EXEC add_BibleVerse @BibleId, 124011009, N'The Lord said to me, “The people of Judah and the citizens of Jerusalem have plotted rebellion against me!'
EXEC add_BibleVerse @BibleId, 124011010, N'They have gone back to the evil ways of their ancestors of old who refused to obey what I told them. They, too, have paid allegiance to other gods and worshiped them. Both the nation of Israel and the nation of Judah have violated the covenant I made with their ancestors.'
EXEC add_BibleVerse @BibleId, 124011011, N'So I, the Lord, say this: ‘I will soon bring disaster on them which they will not be able to escape! When they cry out to me for help, I will not listen to them.'
EXEC add_BibleVerse @BibleId, 124011012, N'Then those living in the towns of Judah and in Jerusalem will go and cry out for help to the gods to whom they have been sacrificing. However, those gods will by no means be able to save them when disaster strikes them.'
EXEC add_BibleVerse @BibleId, 124011013, N'This is in spite of the fact that the people of Judah have as many gods as they have towns and the citizens of Jerusalem have set up as many altars to sacrifice to that disgusting god, Baal, as they have streets in the city!’'
EXEC add_BibleVerse @BibleId, 124011014, N'So, Jeremiah, do not pray for these people. Do not cry out to me or petition me on their behalf. Do not plead with me to save them. For I will not listen to them when they call out to me for help when disaster strikes them.”'
EXEC add_BibleVerse @BibleId, 124011015, N'The Lord says to the people of Judah, “What right do you have to be in my temple, my beloved people? Many of you have done wicked things. Can your acts of treachery be so easily canceled by sacred offerings that you take joy in doing evil even while you make them?'
EXEC add_BibleVerse @BibleId, 124011016, N'I, the Lord, once called you a thriving olive tree, one that produced beautiful fruit. But I will set you on fire, fire that will blaze with a mighty roar. Then all your branches will be good for nothing.'
EXEC add_BibleVerse @BibleId, 124011017, N'For though I, the Lord who rules over all, planted you in the land, I now decree that disaster will come on you because the nations of Israel and Judah have done evil and have made me angry by offering sacrifices to the god Baal.”'
EXEC add_BibleVerse @BibleId, 124011018, N'The Lord gave me knowledge, that I might have understanding. Then he showed me what the people were doing.'
EXEC add_BibleVerse @BibleId, 124011019, N'Before this I had been like a docile lamb ready to be led to the slaughter. I did not know they were making plans to kill me. I did not know they were saying, “Let’s destroy the tree along with its fruit! Let’s remove Jeremiah from the world of the living so people will not even be reminded of him any more.”'
EXEC add_BibleVerse @BibleId, 124011020, N'So I said to the Lord, “O Lord who rules over all, you are a just judge! You examine people’s hearts and minds. I want to see you pay them back for what they have done because I trust you to vindicate my cause.”'
EXEC add_BibleVerse @BibleId, 124011021, N'Then the Lord told me about some men from Anathoth who were threatening to kill me. They had threatened, “Stop prophesying in the name of the Lord or we will kill you!”'
EXEC add_BibleVerse @BibleId, 124011022, N'So the Lord who rules over all said, “I will surely punish them! Their young men will be killed in battle. Their sons and daughters will die of starvation.'
EXEC add_BibleVerse @BibleId, 124011023, N'Not one of them will survive. I will bring disaster on those men from Anathoth who threatened you. A day of reckoning is coming for them.”'
EXEC add_BibleVerse @BibleId, 124012001, N'Lord, you have always been fair whenever I have complained to you. However, I would like to speak with you about the disposition of justice. Why are wicked people successful? Why do all dishonest people have such easy lives?'
EXEC add_BibleVerse @BibleId, 124012002, N'You plant them like trees and they put down their roots. They grow prosperous and are very fruitful. They always talk about you, but they really care nothing about you.'
EXEC add_BibleVerse @BibleId, 124012003, N'But you, Lord, know all about me. You watch me and test my devotion to you. Drag these wicked men away like sheep to be slaughtered! Appoint a time when they will be killed!'
EXEC add_BibleVerse @BibleId, 124012004, N'How long must the land be parched and the grass in every field be withered? How long must the animals and the birds die because of the wickedness of the people who live in this land? For these people boast, “God will not see what happens to us.”'
EXEC add_BibleVerse @BibleId, 124012005, N'The Lord answered, “If you have raced on foot against men and they have worn you out, how will you be able to compete with horses? And if you feel secure only in safe and open country, how will you manage in the thick undergrowth along the Jordan River?'
EXEC add_BibleVerse @BibleId, 124012006, N'As a matter of fact, even your own brothers and the members of your own family have betrayed you too. Even they have plotted to do away with you. So do not trust them even when they say kind things to you.'
EXEC add_BibleVerse @BibleId, 124012007, N'“I will abandon my nation. I will forsake the people I call my own. I will turn my beloved people over to the power of their enemies.'
EXEC add_BibleVerse @BibleId, 124012008, N'The people I call my own have turned on me like a lion in the forest. They have roared defiantly at me. So I will treat them as though I hate them.'
EXEC add_BibleVerse @BibleId, 124012009, N'The people I call my own attack me like birds of prey or like hyenas. But other birds of prey are all around them. Let all the nations gather together like wild beasts. Let them come and destroy these people I call my own.'
EXEC add_BibleVerse @BibleId, 124012010, N'Many foreign rulers will ruin the land where I planted my people. They will trample all over my chosen land. They will turn my beautiful land into a desolate wasteland.'
EXEC add_BibleVerse @BibleId, 124012011, N'They will lay it waste. It will lie parched and empty before me. The whole land will be laid waste. But no one living in it will pay any heed.'
EXEC add_BibleVerse @BibleId, 124012012, N'A destructive army will come marching over the hilltops in the desert. For the Lord will use them as his destructive weapon against everyone from one end of the land to the other. No one will be safe.'
EXEC add_BibleVerse @BibleId, 124012013, N'My people will sow wheat, but will harvest weeds. They will work until they are exhausted, but will get nothing from it. They will be disappointed in their harvests because the Lord will take them away in his fierce anger.'
EXEC add_BibleVerse @BibleId, 124012014, N'“I, the Lord, also have something to say concerning the wicked nations who surround my land and have attacked and plundered the land that I gave to my people as a permanent possession. I say: ‘I will uproot the people of those nations from their lands and I will free the people of Judah who have been taken there.'
EXEC add_BibleVerse @BibleId, 124012015, N'But after I have uprooted the people of those nations, I will relent and have pity on them. I will restore the people of each of those nations to their own lands and to their own country.'
EXEC add_BibleVerse @BibleId, 124012016, N'But they must make sure you learn to follow the religious practices of my people. Once they taught my people to swear their oaths using the name of the god Baal. But then, they must swear oaths using my name, saying, “As surely as the Lord lives, I swear.” If they do these things, then they will be included among the people I call my own.'
EXEC add_BibleVerse @BibleId, 124012017, N'But I will completely uproot and destroy any of those nations that will not pay heed,’” says the Lord.'
EXEC add_BibleVerse @BibleId, 124013001, N'The Lord said to me, “Go and buy some linen shorts and put them on. Do not put them in water.”'
EXEC add_BibleVerse @BibleId, 124013002, N'So I bought the shorts as the Lord had told me to do and put them on.'
EXEC add_BibleVerse @BibleId, 124013003, N'Then the Lord spoke to me again and said,'
EXEC add_BibleVerse @BibleId, 124013004, N'“Take the shorts that you bought and are wearing and go at once to Perath. Bury the shorts there in a crack in the rocks.”'
EXEC add_BibleVerse @BibleId, 124013005, N'So I went and buried them at Perath as the Lord had ordered me to do.'
EXEC add_BibleVerse @BibleId, 124013006, N'Many days later the Lord said to me, “Go at once to Perath and get the shorts I ordered you to bury there.”'
EXEC add_BibleVerse @BibleId, 124013007, N'So I went to Perath and dug up the shorts from the place where I had buried them. I found that they were ruined; they were good for nothing.'
EXEC add_BibleVerse @BibleId, 124013008, N'Then the Lord said to me,'
EXEC add_BibleVerse @BibleId, 124013009, N'“I, the Lord, say: ‘This shows how I will ruin the highly exalted position in which Judah and Jerusalem take pride.'
EXEC add_BibleVerse @BibleId, 124013010, N'These wicked people refuse to obey what I have said. They follow the stubborn inclinations of their own hearts and pay allegiance to other gods by worshiping and serving them. So they will become just like these linen shorts which are good for nothing.'
EXEC add_BibleVerse @BibleId, 124013011, N'For,’ I say, ‘just as shorts cling tightly to a person’s body, so I bound the whole nation of Israel and the whole nation of Judah tightly to me.’ I intended for them to be my special people and to bring me fame, honor, and praise. But they would not obey me.'
EXEC add_BibleVerse @BibleId, 124013012, N'“So tell them, ‘The Lord, the God of Israel, says, “Every wine jar is made to be filled with wine.”’ And they will probably say to you, ‘Do you not think we know that every wine jar is supposed to be filled with wine?’'
EXEC add_BibleVerse @BibleId, 124013013, N'Then tell them, ‘The Lord says, “I will soon fill all the people who live in this land with stupor. I will also fill the kings from David’s dynasty, the priests, the prophets, and the citizens of Jerusalem with stupor.'
EXEC add_BibleVerse @BibleId, 124013014, N'And I will smash them like wine bottles against one another, children and parents alike. I will not show any pity, mercy, or compassion. Nothing will keep me from destroying them,’ says the Lord.”'
EXEC add_BibleVerse @BibleId, 124013015, N'Then I said to the people of Judah, “Listen and pay attention! Do not be arrogant! For the Lord has spoken.'
EXEC add_BibleVerse @BibleId, 124013016, N'Show the Lord your God the respect that is due him. Do it before he brings the darkness of disaster. Do it before you stumble into distress like a traveler on the mountains at twilight. Do it before he turns the light of deliverance you hope for into the darkness and gloom of exile.'
EXEC add_BibleVerse @BibleId, 124013017, N'But if you will not pay attention to this warning, I will weep alone because of your arrogant pride. I will weep bitterly and my eyes will overflow with tears because you, the Lord’s flock, will be carried into exile.”'
EXEC add_BibleVerse @BibleId, 124013018, N'The Lord told me, “Tell the king and the queen mother, ‘Surrender your thrones, for your glorious crowns will be removed from your heads.'
EXEC add_BibleVerse @BibleId, 124013019, N'The gates of the towns in southern Judah will be shut tight. No one will be able to go in or out of them. All Judah will be carried off into exile. They will be completely carried off into exile.’”'
EXEC add_BibleVerse @BibleId, 124013020, N'Then I said, “Look up, Jerusalem, and see the enemy that is coming from the north. Where now is the flock of people that were entrusted to your care? Where now are the ‘sheep’ that you take such pride in?'
EXEC add_BibleVerse @BibleId, 124013021, N'What will you say when the Lord appoints as rulers over you those allies that you, yourself, had actually prepared as such? Then anguish and agony will grip you like that of a woman giving birth to a baby.'
EXEC add_BibleVerse @BibleId, 124013022, N'You will probably ask yourself, ‘Why have these things happened to me? Why have I been treated like a disgraced adulteress whose skirt has been torn off and her limbs exposed?’ It is because you have sinned so much.'
EXEC add_BibleVerse @BibleId, 124013023, N'But there is little hope for you ever doing good, you who are so accustomed to doing evil. Can an Ethiopian change the color of his skin? Can a leopard remove its spots?'
EXEC add_BibleVerse @BibleId, 124013024, N'“The Lord says, ‘That is why I will scatter your people like chaff that is blown away by a desert wind.'
EXEC add_BibleVerse @BibleId, 124013025, N'This is your fate, the destiny to which I have appointed you, because you have forgotten me and have trusted in false gods.'
EXEC add_BibleVerse @BibleId, 124013026, N'So I will pull your skirt up over your face and expose you to shame like a disgraced adulteress!'
EXEC add_BibleVerse @BibleId, 124013027, N'People of Jerusalem, I have seen your adulterous worship, your shameless prostitution to, and your lustful pursuit of, other gods. I have seen your disgusting acts of worship on the hills throughout the countryside. You are doomed to destruction! How long will you continue to be unclean?’”'
EXEC add_BibleVerse @BibleId, 124014001, N'The Lord spoke to Jeremiah about the drought.'
EXEC add_BibleVerse @BibleId, 124014002, N'“The people of Judah are in mourning. The people in her cities are pining away. They lie on the ground expressing their sorrow. Cries of distress come up to me from Jerusalem.'
EXEC add_BibleVerse @BibleId, 124014003, N'The leading men of the cities send their servants for water. They go to the cisterns, but they do not find any water there. They return with their containers empty. Disappointed and dismayed, they bury their faces in their hands.'
EXEC add_BibleVerse @BibleId, 124014004, N'They are dismayed because the ground is cracked because there has been no rain in the land. The farmers, too, are dismayed and bury their faces in their hands.'
EXEC add_BibleVerse @BibleId, 124014005, N'Even the doe abandons her newborn fawn in the field because there is no grass.'
EXEC add_BibleVerse @BibleId, 124014006, N'Wild donkeys stand on the hilltops and pant for breath like jackals. Their eyes are strained looking for food, because there is none to be found.”'
EXEC add_BibleVerse @BibleId, 124014007, N'Then I said, “O Lord, intervene for the honor of your name even though our sins speak out against us. Indeed, we have turned away from you many times. We have sinned against you.'
EXEC add_BibleVerse @BibleId, 124014008, N'You have been the object of Israel’s hopes. You have saved them when they were in trouble. Why have you become like a resident foreigner in the land? Why have you become like a traveler who only stops in to spend the night?'
EXEC add_BibleVerse @BibleId, 124014009, N'Why should you be like someone who is helpless, like a champion who cannot save anyone? You are indeed with us, and we belong to you. Do not abandon us!”'
EXEC add_BibleVerse @BibleId, 124014010, N'Then the Lord spoke about these people. “They truly love to go astray. They cannot keep from running away from me. So I am not pleased with them. I will now call to mind the wrongs they have done and punish them for their sins.”'
EXEC add_BibleVerse @BibleId, 124014011, N'Then the Lord said to me, “Do not pray for good to come to these people!'
EXEC add_BibleVerse @BibleId, 124014012, N'Even if they fast, I will not hear their cries for help. Even if they offer burnt offerings and grain offerings, I will not accept them. Instead, I will kill them through wars, famines, and plagues.”'
EXEC add_BibleVerse @BibleId, 124014013, N'Then I said, “Oh, Lord God, look! The prophets are telling them that you said, ‘You will not experience war or suffer famine. I will give you lasting peace and prosperity in this land.’”'
EXEC add_BibleVerse @BibleId, 124014014, N'Then the Lord said to me, “Those prophets are prophesying lies while claiming my authority! I did not send them. I did not commission them. I did not speak to them. They are prophesying to these people false visions, worthless predictions, and the delusions of their own mind.'
EXEC add_BibleVerse @BibleId, 124014015, N'I did not send those prophets, though they claim to be prophesying in my name. They may be saying, ‘No war or famine will happen in this land.’ But I, the Lord, say this about them: ‘War and starvation will kill those prophets.’'
EXEC add_BibleVerse @BibleId, 124014016, N'The people to whom they are prophesying will die through war and famine. Their bodies will be thrown out into the streets of Jerusalem and there will be no one to bury them. This will happen to the men and their wives, their sons, and their daughters. For I will pour out on them the destruction they deserve.”'
EXEC add_BibleVerse @BibleId, 124014017, N'“Tell these people this, Jeremiah: ‘My eyes overflow with tears day and night without ceasing. For my people, my dear children, have suffered a crushing blow. They have suffered a serious wound.'
EXEC add_BibleVerse @BibleId, 124014018, N'If I go out into the countryside, I see those who have been killed in battle. If I go into the city, I see those who are sick because of starvation. For both prophet and priest go about their own business in the land without having any real understanding.’”'
EXEC add_BibleVerse @BibleId, 124014019, N'Then I said, “Lord, have you completely rejected the nation of Judah? Do you despise the city of Zion? Why have you struck us with such force that we are beyond recovery? We hope for peace, but nothing good has come of it. We hope for a time of relief from our troubles, but experience terror.'
EXEC add_BibleVerse @BibleId, 124014020, N'Lord, we confess that we have been wicked. We confess that our ancestors have done wrong. We have indeed sinned against you.'
EXEC add_BibleVerse @BibleId, 124014021, N'For the honor of your name, do not treat Jerusalem with contempt. Do not treat with disdain the place where your glorious throne sits. Be mindful of your covenant with us. Do not break it!'
EXEC add_BibleVerse @BibleId, 124014022, N'Do any of the worthless idols of the nations cause rain to fall? Do the skies themselves send showers? Is it not you, O Lord our God, who does this? So we put our hopes in you because you alone do all this.”'
EXEC add_BibleVerse @BibleId, 124015001, N'Then the Lord said to me, “Even if Moses and Samuel stood before me pleading for these people, I would not feel pity for them! Get them away from me! Tell them to go away!'
EXEC add_BibleVerse @BibleId, 124015002, N'If they ask you, ‘Where should we go?’ tell them the Lord says this: “Those who are destined to die of disease will go to death by disease. Those who are destined to die in war will go to death in war. Those who are destined to die of starvation will go to death by starvation. Those who are destined to go into exile will go into exile.”'
EXEC add_BibleVerse @BibleId, 124015003, N'“I will punish them in four different ways: I will have war kill them. I will have dogs drag off their dead bodies. I will have birds and wild beasts devour and destroy their corpses.'
EXEC add_BibleVerse @BibleId, 124015004, N'I will make all the people in all the kingdoms of the world horrified at what has happened to them because of what Hezekiah’s son Manasseh, king of Judah, did in Jerusalem.”'
EXEC add_BibleVerse @BibleId, 124015005, N'The Lord cried out, “Who in the world will have pity on you, Jerusalem? Who will grieve over you? Who will stop long enough to inquire about how you are doing?'
EXEC add_BibleVerse @BibleId, 124015006, N'I, the Lord, say: ‘You people have deserted me! You keep turning your back on me.’ So I have unleashed my power against you and have begun to destroy you. I have grown tired of feeling sorry for you!”'
EXEC add_BibleVerse @BibleId, 124015007, N'The Lord continued, “In every town in the land I will purge them like straw blown away by the wind. I will destroy my people. I will kill off their children. I will do so because they did not change their behavior.'
EXEC add_BibleVerse @BibleId, 124015008, N'Their widows will become in my sight more numerous than the grains of sand on the seashores. At noontime I will bring a destroyer against the mothers of their young men. I will cause anguish and terror to fall suddenly upon them.'
EXEC add_BibleVerse @BibleId, 124015009, N'The mother who had seven children will grow faint. All the breath will go out of her. Her pride and joy will be taken from her in the prime of their life. It will seem as if the sun had set while it was still day. She will suffer shame and humiliation. I will cause any of them who are still left alive to be killed in war by the onslaughts of their enemies,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124015010, N'I said, “Oh, mother, how I regret that you ever gave birth to me! I am always starting arguments and quarrels with the people of this land. I have not lent money to anyone and I have not borrowed from anyone. Yet all of these people are treating me with contempt.”'
EXEC add_BibleVerse @BibleId, 124015011, N'The Lord said, “Jerusalem, I will surely send you away for your own good. I will surely bring the enemy upon you in a time of trouble and distress.'
EXEC add_BibleVerse @BibleId, 124015012, N'Can you people who are like iron and bronze break that iron fist from the north?'
EXEC add_BibleVerse @BibleId, 124015013, N'I will give away your wealth and your treasures as plunder. I will give it away free of charge for the sins you have committed throughout your land.'
EXEC add_BibleVerse @BibleId, 124015014, N'I will make you serve your enemies in a land that you know nothing about. For my anger is like a fire that will burn against you.”'
EXEC add_BibleVerse @BibleId, 124015015, N'I said, “Lord, you know how I suffer. Take thought of me and care for me. Pay back for me those who have been persecuting me. Do not be so patient with them that you allow them to kill me. Be mindful of how I have put up with their insults for your sake.'
EXEC add_BibleVerse @BibleId, 124015016, N'As your words came to me I drank them in, and they filled my heart with joy and happiness because I belong to you.'
EXEC add_BibleVerse @BibleId, 124015017, N'I did not spend my time in the company of other people, laughing and having a good time. I stayed to myself because I felt obligated to you and because I was filled with anger at what they had done.'
EXEC add_BibleVerse @BibleId, 124015018, N'Why must I continually suffer such painful anguish? Why must I endure the sting of their insults like an incurable wound? Will you let me down when I need you like a brook one goes to for water, but that cannot be relied on?”'
EXEC add_BibleVerse @BibleId, 124015019, N'Because of this, the Lord said, “You must repent of such words and thoughts! If you do, I will restore you to the privilege of serving me. If you say what is worthwhile instead of what is worthless, I will again allow you to be my spokesman. They must become as you have been. You must not become like them.'
EXEC add_BibleVerse @BibleId, 124015020, N'I will make you as strong as a wall to these people, a fortified wall of bronze. They will attack you, but they will not be able to overcome you. For I will be with you to rescue you and deliver you,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124015021, N'“I will deliver you from the power of the wicked. I will free you from the clutches of violent people.”'
EXEC add_BibleVerse @BibleId, 124016001, N'The Lord said to me,'
EXEC add_BibleVerse @BibleId, 124016002, N'“Do not get married and do not have children here in this land.'
EXEC add_BibleVerse @BibleId, 124016003, N'For I, the Lord, tell you what will happen to the children who are born here in this land and to the men and women who are their mothers and fathers.'
EXEC add_BibleVerse @BibleId, 124016004, N'They will die of deadly diseases. No one will mourn for them. They will not be buried. Their dead bodies will lie like manure spread on the ground. They will be killed in war or die of starvation. Their corpses will be food for the birds and wild animals.'
EXEC add_BibleVerse @BibleId, 124016005, N'“Moreover I, the Lord, tell you: ‘Do not go into a house where they are having a funeral meal. Do not go there to mourn and express your sorrow for them. For I have stopped showing them my good favor, my love, and my compassion. I, the Lord, so affirm it!'
EXEC add_BibleVerse @BibleId, 124016006, N'Rich and poor alike will die in this land. They will not be buried or mourned. People will not cut their bodies or shave off their hair to show their grief for them.'
EXEC add_BibleVerse @BibleId, 124016007, N'No one will take any food to those who mourn for the dead to comfort them. No one will give them any wine to drink to console them for the loss of their father or mother.'
EXEC add_BibleVerse @BibleId, 124016008, N'“‘Do not go to a house where people are feasting and sit down to eat and drink with them either.'
EXEC add_BibleVerse @BibleId, 124016009, N'For I, the Lord God of Israel who rules over all, tell you what will happen. I will put an end to the sounds of joy and gladness, to the glad celebration of brides and grooms in this land. You and the rest of the people will live to see this happen.’”'
EXEC add_BibleVerse @BibleId, 124016010, N'“When you tell these people about all this, they will undoubtedly ask you, ‘Why has the Lord threatened us with such great disaster? What wrong have we done? What sin have we done to offend the Lord our God?’'
EXEC add_BibleVerse @BibleId, 124016011, N'Then tell them that the Lord says, ‘It is because your ancestors rejected me and paid allegiance to other gods. They have served them and worshiped them. But they have rejected me and not obeyed my law.'
EXEC add_BibleVerse @BibleId, 124016012, N'And you have acted even more wickedly than your ancestors! Each one of you has followed the stubborn inclinations of your own wicked heart and not obeyed me.'
EXEC add_BibleVerse @BibleId, 124016013, N'So I will throw you out of this land into a land that neither you nor your ancestors have ever known. There you must worship other gods day and night, for I will show you no mercy.’”'
EXEC add_BibleVerse @BibleId, 124016014, N'Yet I, the Lord, say: “A new time will certainly come. People now affirm their oaths with ‘I swear as surely as the Lord lives who delivered the people of Israel out of Egypt.’'
EXEC add_BibleVerse @BibleId, 124016015, N'But in that time they will affirm them with ‘I swear as surely as the Lord lives who delivered the people of Israel from the land of the north and from all the other lands where he had banished them.’ At that time I will bring them back to the land I gave their ancestors.”'
EXEC add_BibleVerse @BibleId, 124016016, N'But for now I, the Lord, say: “I will send many enemies who will catch these people like fishermen. After that I will send others who will hunt them out like hunters from all the mountains, all the hills, and the crevices in the rocks.'
EXEC add_BibleVerse @BibleId, 124016017, N'For I see everything they do. Their wicked ways are not hidden from me. Their sin is not hidden away where I cannot see it.'
EXEC add_BibleVerse @BibleId, 124016018, N'Before I restore them I will punish them in full for their sins and the wrongs they have done. For they have polluted my land with the lifeless statues of their disgusting idols. They have filled the land I have claimed as my own with their detestable idols.”'
EXEC add_BibleVerse @BibleId, 124016019, N'Then I said, “Lord, you give me strength and protect me. You are the one I can run to for safety when I am in trouble. Nations from all over the earth will come to you and say, ‘Our ancestors had nothing but false gods – worthless idols that could not help them at all.'
EXEC add_BibleVerse @BibleId, 124016020, N'Can people make their own gods? No, what they make are not gods at all.”'
EXEC add_BibleVerse @BibleId, 124016021, N'The Lord said, “So I will now let this wicked people know – I will let them know my mighty power in judgment. Then they will know that my name is the Lord.”'
EXEC add_BibleVerse @BibleId, 124017001, N'The sin of Judah is engraved with an iron chisel on their stone-hard hearts. It is inscribed with a diamond point on the horns of their altars.'
EXEC add_BibleVerse @BibleId, 124017002, N'Their children are always thinking about their altars and their sacred poles dedicated to the goddess Asherah, set up beside the green trees on the high hills'
EXEC add_BibleVerse @BibleId, 124017003, N'and on the mountains and in the fields. I will give your wealth and all your treasures away as plunder. I will give it away as the price for the sins you have committed throughout your land.'
EXEC add_BibleVerse @BibleId, 124017004, N'You will lose your hold on the land which I gave to you as a permanent possession. I will make you serve your enemies in a land that you know nothing about. For you have made my anger burn like a fire that will never be put out.”'
EXEC add_BibleVerse @BibleId, 124017005, N'The Lord says, “I will put a curse on people who trust in mere human beings, who depend on mere flesh and blood for their strength, and whose hearts have turned away from the Lord.'
EXEC add_BibleVerse @BibleId, 124017006, N'They will be like a shrub in the desert. They will not experience good things even when they happen. It will be as though they were growing in the desert, in a salt land where no one can live.'
EXEC add_BibleVerse @BibleId, 124017007, N'My blessing is on those people who trust in me, who put their confidence in me.'
EXEC add_BibleVerse @BibleId, 124017008, N'They will be like a tree planted near a stream whose roots spread out toward the water. It has nothing to fear when the heat comes. Its leaves are always green. It has no need to be concerned in a year of drought. It does not stop bearing fruit.'
EXEC add_BibleVerse @BibleId, 124017009, N'The human mind is more deceitful than anything else. It is incurably bad. Who can understand it?'
EXEC add_BibleVerse @BibleId, 124017010, N'I, the Lord, probe into people’s minds. I examine people’s hearts. I deal with each person according to how he has behaved. I give them what they deserve based on what they have done.'
EXEC add_BibleVerse @BibleId, 124017011, N'The person who gathers wealth by unjust means is like the partridge that broods over eggs but does not hatch them. Before his life is half over he will lose his ill-gotten gains. At the end of his life it will be clear he was a fool.”'
EXEC add_BibleVerse @BibleId, 124017012, N'Then I said, “Lord, from the very beginning you have been seated on your glorious throne on high. You are the place where we can find refuge.'
EXEC add_BibleVerse @BibleId, 124017013, N'You are the one in whom Israel may find hope. All who leave you will suffer shame. Those who turn away from you will be consigned to the nether world. For they have rejected you, the Lord, the fountain of life.'
EXEC add_BibleVerse @BibleId, 124017014, N'Lord, grant me relief from my suffering so that I may have some relief. Rescue me from those who persecute me so that I may be rescued.'
EXEC add_BibleVerse @BibleId, 124017015, N'Listen to what they are saying to me. They are saying, “Where are the things the Lord threatens us with? Come on! Let’s see them happen!”'
EXEC add_BibleVerse @BibleId, 124017016, N'But I have not pestered you to bring disaster. I have not desired the time of irreparable devastation. You know that. You are fully aware of every word that I have spoken.'
EXEC add_BibleVerse @BibleId, 124017017, N'Do not cause me dismay! You are my source of safety in times of trouble.'
EXEC add_BibleVerse @BibleId, 124017018, N'May those who persecute me be disgraced. Do not let me be disgraced. May they be dismayed. Do not let me be dismayed. Bring days of disaster on them. Bring on them the destruction they deserve.”'
EXEC add_BibleVerse @BibleId, 124017019, N'The Lord told me, “Go and stand in the People’s Gate through which the kings of Judah enter and leave the city. Then go and stand in all the other gates of the city of Jerusalem.'
EXEC add_BibleVerse @BibleId, 124017020, N'As you stand in those places announce, ‘Listen, all you people who pass through these gates. Listen, all you kings of Judah, all you people of Judah and all you citizens of Jerusalem. Listen to what the Lord says.'
EXEC add_BibleVerse @BibleId, 124017021, N'The Lord says, ‘Be very careful if you value your lives! Do not carry any loads in through the gates of Jerusalem on the Sabbath day.'
EXEC add_BibleVerse @BibleId, 124017022, N'Do not carry any loads out of your houses or do any work on the Sabbath day. But observe the Sabbath day as a day set apart to the Lord, as I commanded your ancestors.'
EXEC add_BibleVerse @BibleId, 124017023, N'Your ancestors, however, did not listen to me or pay any attention to me. They stubbornly refused to pay attention or to respond to any discipline.’'
EXEC add_BibleVerse @BibleId, 124017024, N'The Lord says, ‘You must make sure to obey me. You must not bring any loads through the gates of this city on the Sabbath day. You must set the Sabbath day apart to me. You must not do any work on that day.'
EXEC add_BibleVerse @BibleId, 124017025, N'If you do this, then the kings and princes who follow in David’s succession and ride in chariots or on horses will continue to enter through these gates, as well as their officials and the people of Judah and the citizens of Jerusalem. This city will always be filled with people.'
EXEC add_BibleVerse @BibleId, 124017026, N'Then people will come here from the towns in Judah, from the villages surrounding Jerusalem, from the territory of Benjamin, from the western foothills, from the southern hill country, and from the southern part of Judah. They will come bringing offerings to the temple of the Lord: burnt offerings, sacrifices, grain offerings, and incense along with their thank offerings.'
EXEC add_BibleVerse @BibleId, 124017027, N'But you must obey me and set the Sabbath day apart to me. You must not carry any loads in through the gates of Jerusalem on the Sabbath day. If you disobey, I will set the gates of Jerusalem on fire. It will burn down all the fortified dwellings in Jerusalem and no one will be able to put it out.’”'
EXEC add_BibleVerse @BibleId, 124018001, N'The Lord said to Jeremiah:'
EXEC add_BibleVerse @BibleId, 124018002, N'“Go down at once to the potter’s house. I will speak to you further there.”'
EXEC add_BibleVerse @BibleId, 124018003, N'So I went down to the potter’s house and found him working at his wheel.'
EXEC add_BibleVerse @BibleId, 124018004, N'Now and then there would be something wrong with the pot he was molding from the clay with his hands. So he would rework the clay into another kind of pot as he saw fit.'
EXEC add_BibleVerse @BibleId, 124018005, N'Then the Lord said to me,'
EXEC add_BibleVerse @BibleId, 124018006, N'“I, the Lord, say: ‘O nation of Israel, can I not deal with you as this potter deals with the clay? In my hands, you, O nation of Israel, are just like the clay in this potter’s hand.’'
EXEC add_BibleVerse @BibleId, 124018007, N'There are times, Jeremiah, when I threaten to uproot, tear down, and destroy a nation or kingdom.'
EXEC add_BibleVerse @BibleId, 124018008, N'But if that nation I threatened stops doing wrong, I will cancel the destruction I intended to do to it.'
EXEC add_BibleVerse @BibleId, 124018009, N'And there are times when I promise to build up and establish a nation or kingdom.'
EXEC add_BibleVerse @BibleId, 124018010, N'But if that nation does what displeases me and does not obey me, then I will cancel the good I promised to do to it.'
EXEC add_BibleVerse @BibleId, 124018011, N'So now, tell the people of Judah and the citizens of Jerusalem this: The Lord says, ‘I am preparing to bring disaster on you! I am making plans to punish you. So, every one of you, stop the evil things you have been doing. Correct the way you have been living and do what is right.’'
EXEC add_BibleVerse @BibleId, 124018012, N'But they just keep saying, ‘We do not care what you say! We will do whatever we want to do! We will continue to behave wickedly and stubbornly!’”'
EXEC add_BibleVerse @BibleId, 124018013, N'Therefore, the Lord says, “Ask the people of other nations whether they have heard of anything like this. Israel should have been like a virgin. But she has done something utterly revolting!'
EXEC add_BibleVerse @BibleId, 124018014, N'Does the snow ever completely vanish from the rocky slopes of Lebanon? Do the cool waters from those distant mountains ever cease to flow?'
EXEC add_BibleVerse @BibleId, 124018015, N'Yet my people have forgotten me and offered sacrifices to worthless idols! This makes them stumble along in the way they live and leave the old reliable path of their fathers. They have left them to walk in bypaths, in roads that are not smooth and level.'
EXEC add_BibleVerse @BibleId, 124018016, N'So their land will become an object of horror. People will forever hiss out their scorn over it. All who pass that way will be filled with horror and will shake their heads in derision.'
EXEC add_BibleVerse @BibleId, 124018017, N'I will scatter them before their enemies like dust blowing in front of a burning east wind. I will turn my back on them and not look favorably on them when disaster strikes them.”'
EXEC add_BibleVerse @BibleId, 124018018, N'Then some people said, “Come on! Let us consider how to deal with Jeremiah! There will still be priests to instruct us, wise men to give us advice, and prophets to declare God’s word. Come on! Let’s bring charges against him and get rid of him! Then we will not need to pay attention to anything he says.”'
EXEC add_BibleVerse @BibleId, 124018019, N'Then I said, “Lord, pay attention to me. Listen to what my enemies are saying.'
EXEC add_BibleVerse @BibleId, 124018020, N'Should good be paid back with evil? Yet they are virtually digging a pit to kill me. Just remember how I stood before you pleading on their behalf to keep you from venting your anger on them.'
EXEC add_BibleVerse @BibleId, 124018021, N'So let their children die of starvation. Let them be cut down by the sword. Let their wives lose their husbands and children. Let the older men die of disease and the younger men die by the sword in battle.'
EXEC add_BibleVerse @BibleId, 124018022, N'Let cries of terror be heard in their houses when you send bands of raiders unexpectedly to plunder them. For they have virtually dug a pit to capture me and have hidden traps for me to step into.'
EXEC add_BibleVerse @BibleId, 124018023, N'But you, Lord, know all their plots to kill me. Do not pardon their crimes! Do not ignore their sins as though you had erased them! Let them be brought down in defeat before you! Deal with them while you are still angry!'
EXEC add_BibleVerse @BibleId, 124019001, N'The Lord told Jeremiah, “Go and buy a clay jar from a potter. Take with you some of the leaders of the people and some of the leaders of the priests.'
EXEC add_BibleVerse @BibleId, 124019002, N'Go out to the part of the Hinnom Valley which is near the entrance of the Potsherd Gate. Announce there what I tell you.'
EXEC add_BibleVerse @BibleId, 124019003, N'Say, ‘Listen to what the Lord says, you kings of Judah and citizens of Jerusalem! The Lord God of Israel who rules over all says, “I will bring a disaster on this place that will make the ears of everyone who hears about it ring!'
EXEC add_BibleVerse @BibleId, 124019004, N'I will do so because these people have rejected me and have defiled this place. They have offered sacrifices in it to other gods which neither they nor their ancestors nor the kings of Judah knew anything about. They have filled it with the blood of innocent children.'
EXEC add_BibleVerse @BibleId, 124019005, N'They have built places here for worship of the god Baal so that they could sacrifice their children as burnt offerings to him in the fire. Such sacrifices are something I never commanded them to make! They are something I never told them to do! Indeed, such a thing never even entered my mind!'
EXEC add_BibleVerse @BibleId, 124019006, N'So I, the Lord, say: “The time will soon come that people will no longer call this place Topheth or the Hinnom Valley. But they will call this valley the Valley of Slaughter!'
EXEC add_BibleVerse @BibleId, 124019007, N'In this place I will thwart the plans of the people of Judah and Jerusalem. I will deliver them over to the power of their enemies who are seeking to kill them. They will die by the sword at the hands of their enemies. I will make their dead bodies food for the birds and wild beasts to eat.'
EXEC add_BibleVerse @BibleId, 124019008, N'I will make this city an object of horror, a thing to be hissed at. All who pass by it will be filled with horror and will hiss out their scorn because of all the disasters that have happened to it.'
EXEC add_BibleVerse @BibleId, 124019009, N'I will reduce the people of this city to desperate straits during the siege imposed on it by their enemies who are seeking to kill them. I will make them so desperate that they will eat the flesh of their own sons and daughters and the flesh of one another.”’”'
EXEC add_BibleVerse @BibleId, 124019010, N'The Lord continued, “Now break the jar in front of those who have come here with you.'
EXEC add_BibleVerse @BibleId, 124019011, N'Tell them the Lord who rules over all says, ‘I will do just as Jeremiah has done. I will smash this nation and this city as though it were a potter’s vessel which is broken beyond repair. The dead will be buried here in Topheth until there is no more room to bury them.’'
EXEC add_BibleVerse @BibleId, 124019012, N'I, the Lord, say: ‘That is how I will deal with this city and its citizens. I will make it like Topheth.'
EXEC add_BibleVerse @BibleId, 124019013, N'The houses in Jerusalem and the houses of the kings of Judah will be defiled by dead bodies just like this place, Topheth. For they offered sacrifice to the stars and poured out drink offerings to other gods on the roofs of those houses.’”'
EXEC add_BibleVerse @BibleId, 124019014, N'Then Jeremiah left Topheth where the Lord had sent him to give that prophecy. He went to the Lord’s temple and stood in its courtyard and called out to all the people.'
EXEC add_BibleVerse @BibleId, 124019015, N'“The Lord God of Israel who rules over all says, ‘I will soon bring on this city and all the towns surrounding it all the disaster I threatened to do to it. I will do so because they have stubbornly refused to pay any attention to what I have said!’”'
EXEC add_BibleVerse @BibleId, 124020001, N'Now Pashhur son of Immer heard Jeremiah prophesy these things. He was the priest who was chief of security in the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 124020002, N'When he heard Jeremiah’s prophecy, he had the prophet flogged. Then he put him in the stocks which were at the Upper Gate of Benjamin in the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 124020003, N'But the next day Pashhur released Jeremiah from the stocks. When he did, Jeremiah said to him, “The Lord’s name for you is not ‘Pashhur’ but ‘Terror is Everywhere.’'
EXEC add_BibleVerse @BibleId, 124020004, N'For the Lord says, ‘I will make both you and your friends terrified of what will happen to you. You will see all of them die by the swords of their enemies. I will hand all the people of Judah over to the king of Babylon. He will carry some of them away into exile in Babylon and he will kill others of them with the sword.'
EXEC add_BibleVerse @BibleId, 124020005, N'I will hand over all the wealth of this city to their enemies. I will hand over to them all the fruits of the labor of the people of this city and all their prized possessions, as well as all the treasures of the kings of Judah. Their enemies will seize it all as plunder and carry it off to Babylon.'
EXEC add_BibleVerse @BibleId, 124020006, N'You, Pashhur, and all your household will go into exile in Babylon. You will die there and you will be buried there. The same thing will happen to all your friends to whom you have prophesied lies.’”'
EXEC add_BibleVerse @BibleId, 124020007, N'Lord, you coerced me into being a prophet, and I allowed you to do it. You overcame my resistance and prevailed over me. Now I have become a constant laughingstock. Everyone ridicules me.'
EXEC add_BibleVerse @BibleId, 124020008, N'For whenever I prophesy, I must cry out, “Violence and destruction are coming!” This message from the Lord has made me an object of continual insults and derision.'
EXEC add_BibleVerse @BibleId, 124020009, N'Sometimes I think, “I will make no mention of his message. I will not speak as his messenger any more.” But then his message becomes like a fire locked up inside of me, burning in my heart and soul. I grow weary of trying to hold it in; I cannot contain it.'
EXEC add_BibleVerse @BibleId, 124020010, N'I hear many whispering words of intrigue against me. Those who would cause me terror are everywhere! They are saying, “Come on, let’s publicly denounce him!” All my so-called friends are just watching for something that would lead to my downfall. They say, “Perhaps he can be enticed into slipping up, so we can prevail over him and get our revenge on him.'
EXEC add_BibleVerse @BibleId, 124020011, N'But the Lord is with me to help me like an awe-inspiring warrior. Therefore those who persecute me will fail and will not prevail over me. They will be thoroughly disgraced because they did not succeed. Their disgrace will never be forgotten.'
EXEC add_BibleVerse @BibleId, 124020012, N'O Lord who rules over all, you test and prove the righteous. You see into people’s hearts and minds. Pay them back for what they have done because I trust you to vindicate my cause.'
EXEC add_BibleVerse @BibleId, 124020013, N'Sing to the Lord! Praise the Lord! For he rescues the oppressed from the clutches of evildoers.'
EXEC add_BibleVerse @BibleId, 124020014, N'Cursed be the day I was born! May that day not be blessed when my mother gave birth to me.'
EXEC add_BibleVerse @BibleId, 124020015, N'Cursed be the man who made my father very glad when he brought him the news that a baby boy had been born to him!'
EXEC add_BibleVerse @BibleId, 124020016, N'May that man be like the cities that the Lord destroyed without showing any mercy. May he hear a cry of distress in the morning and a battle cry at noon.'
EXEC add_BibleVerse @BibleId, 124020017, N'For he did not kill me before I came from the womb, making my pregnant mother’s womb my grave forever.'
EXEC add_BibleVerse @BibleId, 124020018, N'Why did I ever come forth from my mother’s womb? All I experience is trouble and grief, and I spend my days in shame.'
EXEC add_BibleVerse @BibleId, 124021001, N'The Lord spoke to Jeremiah when King Zedekiah sent to him Pashhur son of Malkijah and the priest Zephaniah son of Maaseiah. Zedekiah sent them to Jeremiah to ask,'
EXEC add_BibleVerse @BibleId, 124021002, N'“Please ask the Lord to come and help us, because King Nebuchadnezzar of Babylon is attacking us. Maybe the Lord will perform one of his miracles as in times past and make him stop attacking us and leave.”'
EXEC add_BibleVerse @BibleId, 124021003, N'Jeremiah answered them, “Tell Zedekiah'
EXEC add_BibleVerse @BibleId, 124021004, N'that the Lord, the God of Israel, says, ‘The forces at your disposal are now outside the walls fighting against King Nebuchadnezzar of Babylon and the Babylonians who have you under siege. I will gather those forces back inside the city.'
EXEC add_BibleVerse @BibleId, 124021005, N'In anger, in fury, and in wrath I myself will fight against you with my mighty power and great strength!'
EXEC add_BibleVerse @BibleId, 124021006, N'I will kill everything living in Jerusalem, people and animals alike! They will die from terrible diseases.'
EXEC add_BibleVerse @BibleId, 124021007, N'Then I, the Lord, promise that I will hand over King Zedekiah of Judah, his officials, and any of the people who survive the war, starvation, and disease. I will hand them over to King Nebuchadnezzar of Babylon and to their enemies who want to kill them. He will slaughter them with the sword. He will not show them any mercy, compassion, or pity.’'
EXEC add_BibleVerse @BibleId, 124021008, N'“But tell the people of Jerusalem that the Lord says, ‘I will give you a choice between two courses of action. One will result in life; the other will result in death.'
EXEC add_BibleVerse @BibleId, 124021009, N'Those who stay in this city will die in battle or of starvation or disease. Those who leave the city and surrender to the Babylonians who are besieging it will live. They will escape with their lives.'
EXEC add_BibleVerse @BibleId, 124021010, N'For I, the Lord, say that I am determined not to deliver this city but to bring disaster on it. It will be handed over to the king of Babylon and he will destroy it with fire.’”'
EXEC add_BibleVerse @BibleId, 124021011, N'The Lord told me to say to the royal court of Judah, “Listen to what the Lord says,'
EXEC add_BibleVerse @BibleId, 124021012, N'O royal family descended from David. The Lord says: ‘See to it that people each day are judged fairly. Deliver those who have been robbed from those who oppress them. Otherwise, my wrath will blaze out against you. It will burn like a fire that cannot be put out because of the evil that you have done.'
EXEC add_BibleVerse @BibleId, 124021013, N'Listen, you who sit enthroned above the valley on a rocky plateau. I am opposed to you,’ says the Lord. ‘You boast, “No one can swoop down on us. No one can penetrate into our places of refuge.”'
EXEC add_BibleVerse @BibleId, 124021014, N'But I will punish you as your deeds deserve,’ says the Lord. ‘I will set fire to your palace; it will burn up everything around it.’”'
EXEC add_BibleVerse @BibleId, 124022001, N'The Lord told me, “Go down to the palace of the king of Judah. Give him a message from me there.'
EXEC add_BibleVerse @BibleId, 124022002, N'Say: ‘Listen, O king of Judah who follows in David’s succession. You, your officials, and your subjects who pass through the gates of this palace must listen to what the Lord says.'
EXEC add_BibleVerse @BibleId, 124022003, N'The Lord says, “Do what is just and right. Deliver those who have been robbed from those who oppress them. Do not exploit or mistreat foreigners who live in your land, children who have no fathers, or widows. Do not kill innocent people in this land.'
EXEC add_BibleVerse @BibleId, 124022004, N'If you are careful to obey these commands, then the kings who follow in David’s succession and ride in chariots or on horses will continue to come through the gates of this palace, as will their officials and their subjects.'
EXEC add_BibleVerse @BibleId, 124022005, N'But, if you do not obey these commands, I solemnly swear that this palace will become a pile of rubble. I, the Lord, affirm it!”'
EXEC add_BibleVerse @BibleId, 124022006, N'“‘For the Lord says concerning the palace of the king of Judah, “This place looks like a veritable forest of Gilead to me. It is like the wooded heights of Lebanon in my eyes. But I swear that I will make it like a wilderness whose towns have all been deserted.'
EXEC add_BibleVerse @BibleId, 124022007, N'I will send men against it to destroy it with their axes and hatchets. They will hack up its fine cedar panels and columns and throw them into the fire.'
EXEC add_BibleVerse @BibleId, 124022008, N'“‘People from other nations will pass by this city. They will ask one another, “Why has the Lord done such a thing to this great city?”'
EXEC add_BibleVerse @BibleId, 124022009, N'The answer will come back, “It is because they broke their covenant with the Lord their God and worshiped and served other gods.”'
EXEC add_BibleVerse @BibleId, 124022010, N'“‘Do not weep for the king who was killed. Do not grieve for him. But weep mournfully for the king who has gone into exile. For he will never return to see his native land again.'
EXEC add_BibleVerse @BibleId, 124022011, N'“‘For the Lord has spoken about Shallum son of Josiah, who succeeded his father as king of Judah but was carried off into exile. He has said, “He will never return to this land.'
EXEC add_BibleVerse @BibleId, 124022012, N'For he will die in the country where they took him as a captive. He will never see this land again.”'
EXEC add_BibleVerse @BibleId, 124022013, N'“‘Sure to be judged is the king who builds his palace using injustice and treats people unfairly while adding its upper rooms. He makes his countrymen work for him for nothing. He does not pay them for their labor.'
EXEC add_BibleVerse @BibleId, 124022014, N'He says, “I will build myself a large palace with spacious upper rooms.” He cuts windows in its walls, panels it with cedar, and paints its rooms red.'
EXEC add_BibleVerse @BibleId, 124022015, N'Does it make you any more of a king that you outstrip everyone else in building with cedar? Just think about your father. He was content that he had food and drink. He did what was just and right. So things went well with him.'
EXEC add_BibleVerse @BibleId, 124022016, N'He upheld the cause of the poor and needy. So things went well for Judah.’ The Lord says, ‘That is a good example of what it means to know me.’'
EXEC add_BibleVerse @BibleId, 124022017, N'But you are always thinking and looking for ways to increase your wealth by dishonest means. Your eyes and your heart are set on killing some innocent person and committing fraud and oppression.'
EXEC add_BibleVerse @BibleId, 124022018, N'So the Lord has this to say about Josiah’s son, King Jehoiakim of Judah: People will not mourn for him, saying, “This makes me sad, my brother! This makes me sad, my sister!” They will not mourn for him, saying, “Poor, poor lord! Poor, poor majesty!”'
EXEC add_BibleVerse @BibleId, 124022019, N'He will be left unburied just like a dead donkey. His body will be dragged off and thrown outside the gates of Jerusalem.’”'
EXEC add_BibleVerse @BibleId, 124022020, N'People of Jerusalem, go up to Lebanon and cry out in mourning. Go to the land of Bashan and cry out loudly. Cry out in mourning from the mountains of Moab. For your allies have all been defeated.'
EXEC add_BibleVerse @BibleId, 124022021, N'While you were feeling secure I gave you warning. But you said, “I refuse to listen to you.” That is the way you have acted from your earliest history onward. Indeed, you have never paid attention to me.'
EXEC add_BibleVerse @BibleId, 124022022, N'My judgment will carry off all your leaders like a storm wind! Your allies will go into captivity. Then you will certainly be disgraced and put to shame because of all the wickedness you have done.'
EXEC add_BibleVerse @BibleId, 124022023, N'You may feel as secure as a bird nesting in the cedars of Lebanon. But oh how you will groan when the pains of judgment come on you. They will be like those of a woman giving birth to a baby.'
EXEC add_BibleVerse @BibleId, 124022024, N'The Lord says, “As surely as I am the living God, you, Jeconiah, king of Judah, son of Jehoiakim, will not be the earthly representative of my authority. Indeed, I will take that right away from you.'
EXEC add_BibleVerse @BibleId, 124022025, N'I will hand you over to those who want to take your life and of whom you are afraid. I will hand you over to King Nebuchadnezzar of Babylon and his Babylonian soldiers.'
EXEC add_BibleVerse @BibleId, 124022026, N'I will force you and your mother who gave you birth into exile. You will be exiled to a country where neither of you were born, and you will both die there.'
EXEC add_BibleVerse @BibleId, 124022027, N'You will never come back to this land to which you will long to return!”'
EXEC add_BibleVerse @BibleId, 124022028, N'This man, Jeconiah, will be like a broken pot someone threw away. He will be like a clay vessel that no one wants. Why will he and his children be forced into exile? Why will they be thrown out into a country they know nothing about?'
EXEC add_BibleVerse @BibleId, 124022029, N'O land of Judah, land of Judah, land of Judah! Listen to what the Lord has to say!'
EXEC add_BibleVerse @BibleId, 124022030, N'The Lord says, “Enroll this man in the register as though he were childless. Enroll him as a man who will not enjoy success during his lifetime. For none of his sons will succeed in occupying the throne of David or ever succeed in ruling over Judah.”'
EXEC add_BibleVerse @BibleId, 124023001, N'The Lord says, “The leaders of my people are sure to be judged. They were supposed to watch over my people like shepherds watch over their sheep. But they are causing my people to be destroyed and scattered.'
EXEC add_BibleVerse @BibleId, 124023002, N'So the Lord God of Israel has this to say about the leaders who are ruling over his people: “You have caused my people to be dispersed and driven into exile. You have not taken care of them. So I will punish you for the evil that you have done. I, the Lord, affirm it!'
EXEC add_BibleVerse @BibleId, 124023003, N'Then I myself will regather those of my people who are still alive from all the countries where I have driven them. I will bring them back to their homeland. They will greatly increase in number.'
EXEC add_BibleVerse @BibleId, 124023004, N'I will install rulers over them who will care for them. Then they will no longer need to fear or be terrified. None of them will turn up missing. I, the Lord, promise it!'
EXEC add_BibleVerse @BibleId, 124023005, N'“I, the Lord, promise that a new time will certainly come when I will raise up for them a righteous branch, a descendant of David. He will rule over them with wisdom and understanding and will do what is just and right in the land.'
EXEC add_BibleVerse @BibleId, 124023006, N'Under his rule Judah will enjoy safety and Israel will live in security. This is the name he will go by: ‘The Lord has provided us with justice.’'
EXEC add_BibleVerse @BibleId, 124023007, N'“So I, the Lord, say: ‘A new time will certainly come. People now affirm their oaths with “I swear as surely as the Lord lives who delivered the people of Israel out of Egypt.”'
EXEC add_BibleVerse @BibleId, 124023008, N'But at that time they will affirm them with “I swear as surely as the Lord lives who delivered the descendants of the former nation of Israel from the land of the north and from all the other lands where he had banished them.” At that time they will live in their own land.’”'
EXEC add_BibleVerse @BibleId, 124023009, N'Here is what the Lord says concerning the false prophets: My heart and my mind are deeply disturbed. I tremble all over. I am like a drunk person, like a person who has had too much wine, because of the way the Lord and his holy word are being mistreated.'
EXEC add_BibleVerse @BibleId, 124023010, N'For the land is full of people unfaithful to him. They live wicked lives and they misuse their power. So the land is dried up because it is under his curse. The pastures in the wilderness are withered.'
EXEC add_BibleVerse @BibleId, 124023011, N'Moreover, the Lord says, “Both the prophets and priests are godless. I have even found them doing evil in my temple!'
EXEC add_BibleVerse @BibleId, 124023012, N'So the paths they follow will be dark and slippery. They will stumble and fall headlong. For I will bring disaster on them. A day of reckoning is coming for them.” The Lord affirms it!'
EXEC add_BibleVerse @BibleId, 124023013, N'The Lord says, “I saw the prophets of Samaria doing something that was disgusting. They prophesied in the name of the god Baal and led my people Israel astray.'
EXEC add_BibleVerse @BibleId, 124023014, N'But I see the prophets of Jerusalem doing something just as shocking. They are unfaithful to me and continually prophesy lies. So they give encouragement to people who are doing evil, with the result that they do not stop their evildoing. I consider all of them as bad as the people of Sodom, and the citizens of Jerusalem as bad as the people of Gomorrah.'
EXEC add_BibleVerse @BibleId, 124023015, N'So then I, the Lord who rules over all, have something to say concerning the prophets of Jerusalem: ‘I will make these prophets eat the bitter food of suffering and drink the poison water of judgment. For the prophets of Jerusalem are the reason that ungodliness has spread throughout the land.’”'
EXEC add_BibleVerse @BibleId, 124023016, N'The Lord who rules over all says to the people of Jerusalem: “Do not listen to what those prophets are saying to you. They are filling you with false hopes. They are reporting visions of their own imaginations, not something the Lord has given them to say.'
EXEC add_BibleVerse @BibleId, 124023017, N'They continually say to those who reject what the Lord has said, ‘Things will go well for you!’ They say to all those who follow the stubborn inclinations of their own hearts, ‘Nothing bad will happen to you!’'
EXEC add_BibleVerse @BibleId, 124023018, N'Yet which of them has ever stood in the Lord’s inner circle so they could see and hear what he has to say? Which of them have ever paid attention or listened to what he has said?'
EXEC add_BibleVerse @BibleId, 124023019, N'But just watch! The wrath of the Lord will come like a storm! Like a raging storm it will rage down on the heads of those who are wicked.'
EXEC add_BibleVerse @BibleId, 124023020, N'The anger of the Lord will not turn back until he has fully carried out his intended purposes. In days to come you people will come to understand this clearly.'
EXEC add_BibleVerse @BibleId, 124023021, N'I did not send those prophets. Yet they were in a hurry to give their message. I did not tell them anything. Yet they prophesied anyway.'
EXEC add_BibleVerse @BibleId, 124023022, N'But if they had stood in my inner circle, they would have proclaimed my message to my people. They would have caused my people to turn from their wicked ways and stop doing the evil things they are doing.'
EXEC add_BibleVerse @BibleId, 124023023, N'Do you people think that I am some local deity and not the transcendent God?” the Lord asks.'
EXEC add_BibleVerse @BibleId, 124023024, N'“Do you really think anyone can hide himself where I cannot see him?” the Lord asks. “Do you not know that I am everywhere?” the Lord asks.'
EXEC add_BibleVerse @BibleId, 124023025, N'The Lord says, “I have heard what those prophets who are prophesying lies in my name are saying. They are saying, ‘I have had a dream! I have had a dream!’'
EXEC add_BibleVerse @BibleId, 124023026, N'Those prophets are just prophesying lies. They are prophesying the delusions of their own minds.'
EXEC add_BibleVerse @BibleId, 124023027, N'How long will they go on plotting to make my people forget who I am through the dreams they tell one another? That is just as bad as what their ancestors did when they forgot who I am by worshiping the god Baal.'
EXEC add_BibleVerse @BibleId, 124023028, N'Let the prophet who has had a dream go ahead and tell his dream. Let the person who has received my message report that message faithfully. What is like straw cannot compare to what is like grain! I, the Lord, affirm it!'
EXEC add_BibleVerse @BibleId, 124023029, N'My message is like a fire that purges dross! It is like a hammer that breaks a rock in pieces! I, the Lord, so affirm it!'
EXEC add_BibleVerse @BibleId, 124023030, N'So I, the Lord, affirm that I am opposed to those prophets who steal messages from one another that they claim are from me.'
EXEC add_BibleVerse @BibleId, 124023031, N'I, the Lord, affirm that I am opposed to those prophets who are using their own tongues to declare, ‘The Lord declares….’'
EXEC add_BibleVerse @BibleId, 124023032, N'I, the Lord, affirm that I am opposed to those prophets who dream up lies and report them. They are misleading my people with their reckless lies. I did not send them. I did not commission them. They are not helping these people at all. I, the Lord, affirm it!”'
EXEC add_BibleVerse @BibleId, 124023033, N'The Lord said to me, “Jeremiah, when one of these people, or a prophet, or a priest asks you, ‘What burdensome message do you have from the Lord?’ Tell them, ‘You are the burden, and I will cast you away. I, the Lord, affirm it!'
EXEC add_BibleVerse @BibleId, 124023034, N'I will punish any prophet, priest, or other person who says “The Lord’s message is burdensome.” I will punish both that person and his whole family.’”'
EXEC add_BibleVerse @BibleId, 124023035, N'So I, Jeremiah, tell you, “Each of you people should say to his friend or his relative, ‘How did the Lord answer? Or what did the Lord say?’'
EXEC add_BibleVerse @BibleId, 124023036, N'You must no longer say that the Lord’s message is burdensome. For what is ‘burdensome’ really pertains to what a person himself says. You are misrepresenting the words of our God, the living God, the Lord who rules over all.'
EXEC add_BibleVerse @BibleId, 124023037, N'Each of you should merely ask the prophet, ‘What answer did the Lord give you? Or what did the Lord say?’'
EXEC add_BibleVerse @BibleId, 124023038, N'But just suppose you continue to say, ‘The message of the Lord is burdensome.’ Here is what the Lord says will happen: ‘I sent word to you that you must not say, “The Lord’s message is burdensome.” But you used the words “The Lord’s message is burdensome” anyway.'
EXEC add_BibleVerse @BibleId, 124023039, N'So I will carry you far off and throw you away. I will send both you and the city I gave to you and to your ancestors out of my sight.'
EXEC add_BibleVerse @BibleId, 124023040, N'I will bring on you lasting shame and lasting disgrace which will never be forgotten!’”'
EXEC add_BibleVerse @BibleId, 124024001, N'The Lord showed me two baskets of figs sitting before his temple. This happened after King Nebuchadnezzar of Babylon deported Jehoiakim’s son, King Jeconiah of Judah. He deported him and the leaders of Judah, along with the craftsmen and metal workers, and took them to Babylon.'
EXEC add_BibleVerse @BibleId, 124024002, N'One basket had very good-looking figs in it. They looked like those that had ripened early. The other basket had very bad-looking figs in it, so bad they could not be eaten.'
EXEC add_BibleVerse @BibleId, 124024003, N'The Lord said to me, “What do you see, Jeremiah?” I answered, “I see figs. The good ones look very good. But the bad ones look very bad, so bad that they cannot be eaten.”'
EXEC add_BibleVerse @BibleId, 124024004, N'The Lord said to me,'
EXEC add_BibleVerse @BibleId, 124024005, N'“I, the Lord, the God of Israel, say: ‘The exiles whom I sent away from here to the land of Babylon are like those good figs. I consider them to be good.'
EXEC add_BibleVerse @BibleId, 124024006, N'I will look after their welfare and will restore them to this land. There I will build them up and will not tear them down. I will plant them firmly in the land and will not uproot them.'
EXEC add_BibleVerse @BibleId, 124024007, N'I will give them the desire to acknowledge that I am the Lord. I will be their God and they will be my people. For they will wholeheartedly return to me.’'
EXEC add_BibleVerse @BibleId, 124024008, N'“I, the Lord, also solemnly assert: ‘King Zedekiah of Judah, his officials, and the people who remain in Jerusalem or who have gone to live in Egypt are like those bad figs. I consider them to be just like those bad figs that are so bad they cannot be eaten.'
EXEC add_BibleVerse @BibleId, 124024009, N'I will bring such disaster on them that all the kingdoms of the earth will be horrified. I will make them an object of reproach, a proverbial example of disaster. I will make them an object of ridicule, an example to be used in curses. That is how they will be remembered wherever I banish them.'
EXEC add_BibleVerse @BibleId, 124024010, N'I will bring war, starvation, and disease on them until they are completely destroyed from the land I gave them and their ancestors.’”'
EXEC add_BibleVerse @BibleId, 124025001, N'In the fourth year that Jehoiakim son of Josiah was king of Judah, the Lord spoke to Jeremiah concerning all the people of Judah. (That was the same as the first year that Nebuchadnezzar was king of Babylon.)'
EXEC add_BibleVerse @BibleId, 124025002, N'So the prophet Jeremiah spoke to all the people of Judah and to all the people who were living in Jerusalem.'
EXEC add_BibleVerse @BibleId, 124025003, N'“For the last twenty-three years, from the thirteenth year that Josiah son of Amon was ruling in Judah until now, the Lord has been speaking to me. I told you over and over again what he said. But you would not listen.'
EXEC add_BibleVerse @BibleId, 124025004, N'Over and over again the Lord has sent his servants the prophets to you. But you have not listened or paid attention.'
EXEC add_BibleVerse @BibleId, 124025005, N'He said through them, ‘Each of you must turn from your wicked ways and stop doing the evil things you are doing. If you do, I will allow you to continue to live here in the land that I gave to you and your ancestors as a lasting possession.'
EXEC add_BibleVerse @BibleId, 124025006, N'Do not pay allegiance to other gods and worship and serve them. Do not make me angry by the things that you do. Then I will not cause you any harm.’'
EXEC add_BibleVerse @BibleId, 124025007, N'So, now the Lord says, ‘You have not listened to me. But you have made me angry by the things that you have done. Thus you have brought harm on yourselves.’'
EXEC add_BibleVerse @BibleId, 124025008, N'“Therefore, the Lord who rules over all says, ‘You have not listened to what I said.'
EXEC add_BibleVerse @BibleId, 124025009, N'So I, the Lord, affirm that I will send for all the peoples of the north and my servant, King Nebuchadnezzar of Babylon. I will bring them against this land and its inhabitants and all the nations that surround it. I will utterly destroy this land, its inhabitants, and all the nations that surround it and make them everlasting ruins. I will make them objects of horror and hissing scorn.'
EXEC add_BibleVerse @BibleId, 124025010, N'I will put an end to the sounds of joy and gladness, to the glad celebration of brides and grooms in these lands. I will put an end to the sound of people grinding meal. I will put an end to lamps shining in their houses.'
EXEC add_BibleVerse @BibleId, 124025011, N'This whole area will become a desolate wasteland. These nations will be subject to the king of Babylon for seventy years.’'
EXEC add_BibleVerse @BibleId, 124025012, N'“‘But when the seventy years are over, I will punish the king of Babylon and his nation for their sins. I will make the land of Babylon an everlasting ruin. I, the Lord, affirm it!'
EXEC add_BibleVerse @BibleId, 124025013, N'I will bring on that land everything that I said I would. I will bring on it everything that is written in this book. I will bring on it everything that Jeremiah has prophesied against all the nations.'
EXEC add_BibleVerse @BibleId, 124025014, N'For many nations and great kings will make slaves of the king of Babylon and his nation too. I will repay them for all they have done!’”'
EXEC add_BibleVerse @BibleId, 124025015, N'So the Lord, the God of Israel, spoke to me in a vision. “Take this cup from my hand. It is filled with the wine of my wrath. Take it and make the nations to whom I send you drink it.'
EXEC add_BibleVerse @BibleId, 124025016, N'When they have drunk it, they will stagger to and fro and act insane. For I will send wars sweeping through them.”'
EXEC add_BibleVerse @BibleId, 124025017, N'So I took the cup from the Lord’s hand. I made all the nations to whom he sent me drink the wine of his wrath.'
EXEC add_BibleVerse @BibleId, 124025018, N'I made Jerusalem and the cities of Judah, its kings and its officials drink it. I did it so Judah would become a ruin. I did it so Judah, its kings, and its officials would become an object of horror and of hissing scorn, an example used in curses. Such is already becoming the case!'
EXEC add_BibleVerse @BibleId, 124025019, N'I made all of these other people drink it: Pharaoh, king of Egypt; his attendants, his officials, his people,'
EXEC add_BibleVerse @BibleId, 124025020, N'the foreigners living in Egypt; all the kings of the land of Uz; all the kings of the land of the Philistines, the people of Ashkelon, Gaza, Ekron, the people who had been left alive from Ashdod;'
EXEC add_BibleVerse @BibleId, 124025021, N'all the people of Edom, Moab, Ammon;'
EXEC add_BibleVerse @BibleId, 124025022, N'all the kings of Tyre, all the kings of the coastlands along the sea;'
EXEC add_BibleVerse @BibleId, 124025023, N'the people of Dedan, Tema, Buz, all the desert people who cut their hair short at the temples;'
EXEC add_BibleVerse @BibleId, 124025024, N'all the kings of Arabia who live in the desert;'
EXEC add_BibleVerse @BibleId, 124025025, N'all the kings of Zimri; all the kings of Elam; all the kings of Media;'
EXEC add_BibleVerse @BibleId, 124025026, N'all the kings of the north, whether near or far from one another; and all the other kingdoms which are on the face of the earth. After all of them have drunk the wine of the Lord’s wrath, the king of Babylon must drink it.'
EXEC add_BibleVerse @BibleId, 124025027, N'Then the Lord said to me, “Tell them that the Lord God of Israel who rules over all says, ‘Drink this cup until you get drunk and vomit. Drink until you fall down and can’t get up. For I will send wars sweeping through you.’'
EXEC add_BibleVerse @BibleId, 124025028, N'If they refuse to take the cup from your hand and drink it, tell them that the Lord who rules over all says ‘You most certainly must drink it!'
EXEC add_BibleVerse @BibleId, 124025029, N'For take note, I am already beginning to bring disaster on the city that I call my own. So how can you possibly avoid being punished? You will not go unpunished! For I am proclaiming war against all who live on the earth. I, the Lord who rules over all, affirm it!’'
EXEC add_BibleVerse @BibleId, 124025030, N'“Then, Jeremiah, make the following prophecy against them: ‘Like a lion about to attack, the Lord will roar from the heights of heaven; from his holy dwelling on high he will roar loudly. He will roar mightily against his land. He will shout in triumph like those stomping juice from the grapes against all those who live on the earth.'
EXEC add_BibleVerse @BibleId, 124025031, N'The sounds of battle will resound to the ends of the earth. For the Lord will bring charges against the nations. He will pass judgment on all humankind and will hand the wicked over to be killed in war.’ The Lord so affirms it!'
EXEC add_BibleVerse @BibleId, 124025032, N'The Lord who rules over all says, ‘Disaster will soon come on one nation after another. A mighty storm of military destruction is rising up from the distant parts of the earth.’'
EXEC add_BibleVerse @BibleId, 124025033, N'Those who have been killed by the Lord at that time will be scattered from one end of the earth to the other. They will not be mourned over, gathered up, or buried. Their dead bodies will lie scattered over the ground like manure.'
EXEC add_BibleVerse @BibleId, 124025034, N'Wail and cry out in anguish, you rulers! Roll in the dust, you who shepherd flocks of people! The time for you to be slaughtered has come. You will lie scattered and fallen like broken pieces of fine pottery.'
EXEC add_BibleVerse @BibleId, 124025035, N'The leaders will not be able to run away and hide. The shepherds of the flocks will not be able to escape.'
EXEC add_BibleVerse @BibleId, 124025036, N'Listen to the cries of anguish of the leaders. Listen to the wails of the shepherds of the flocks. They are wailing because the Lord is about to destroy their lands.'
EXEC add_BibleVerse @BibleId, 124025037, N'Their peaceful dwelling places will be laid waste by the fierce anger of the Lord.'
EXEC add_BibleVerse @BibleId, 124025038, N'The Lord is like a lion who has left his lair. So their lands will certainly be laid waste by the warfare of the oppressive nation and by the fierce anger of the Lord.”'
EXEC add_BibleVerse @BibleId, 124026001, N'The Lord spoke to Jeremiah at the beginning of the reign of Josiah’s son, King Jehoiakim of Judah.'
EXEC add_BibleVerse @BibleId, 124026002, N'The Lord said, “Go stand in the courtyard of the Lord’s temple. Speak out to all the people who are coming from the towns of Judah to worship in the Lord’s temple. Tell them everything I command you to tell them. Do not leave out a single word!'
EXEC add_BibleVerse @BibleId, 124026003, N'Maybe they will pay attention and each of them will stop living the evil way they do. If they do that, then I will forgo destroying them as I had intended to do because of the wicked things they have been doing.'
EXEC add_BibleVerse @BibleId, 124026004, N'Tell them that the Lord says, ‘You must obey me! You must live according to the way I have instructed you in my laws.'
EXEC add_BibleVerse @BibleId, 124026005, N'You must pay attention to the exhortations of my servants the prophets. I have sent them to you over and over again. But you have not paid any attention to them.'
EXEC add_BibleVerse @BibleId, 124026006, N'If you do not obey me, then I will do to this temple what I did to Shiloh. And I will make this city an example to be used in curses by people from all the nations on the earth.’”'
EXEC add_BibleVerse @BibleId, 124026007, N'The priests, the prophets, and all the people heard Jeremiah say these things in the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 124026008, N'Jeremiah had just barely finished saying all the Lord had commanded him to say to all the people. All at once some of the priests, the prophets, and the people grabbed him and shouted, “You deserve to die!'
EXEC add_BibleVerse @BibleId, 124026009, N'How dare you claim the Lord’s authority to prophesy such things! How dare you claim his authority to prophesy that this temple will become like Shiloh and that this city will become an uninhabited ruin!” Then all the people crowded around Jeremiah.'
EXEC add_BibleVerse @BibleId, 124026010, N'However, some of the officials of Judah heard about what was happening and they rushed up to the Lord’s temple from the royal palace. They set up court at the entrance of the New Gate of the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 124026011, N'Then the priests and the prophets made their charges before the officials and all the people. They said, “This man should be condemned to die because he prophesied against this city. You have heard him do so with your own ears.”'
EXEC add_BibleVerse @BibleId, 124026012, N'Then Jeremiah made his defense before all the officials and all the people. “The Lord sent me to prophesy everything you have heard me say against this temple and against this city.'
EXEC add_BibleVerse @BibleId, 124026013, N'But correct the way you have been living and do what is right. Obey the Lord your God. If you do, the Lord will forgo destroying you as he threatened he would.'
EXEC add_BibleVerse @BibleId, 124026014, N'As to my case, I am in your power. Do to me what you deem fair and proper.'
EXEC add_BibleVerse @BibleId, 124026015, N'But you should take careful note of this: If you put me to death, you will bring on yourselves and this city and those who live in it the guilt of murdering an innocent man. For the Lord has sent me to speak all this where you can hear it. That is the truth!”'
EXEC add_BibleVerse @BibleId, 124026016, N'Then the officials and all the people rendered their verdict to the priests and the prophets. They said, “This man should not be condemned to die. For he has spoken to us under the authority of the Lord our God.”'
EXEC add_BibleVerse @BibleId, 124026017, N'Then some of the elders of Judah stepped forward and spoke to all the people gathered there. They said,'
EXEC add_BibleVerse @BibleId, 124026018, N'“Micah from Moresheth prophesied during the time Hezekiah was king of Judah. He told all the people of Judah, ‘The Lord who rules over all says, “Zion will become a plowed field. Jerusalem will become a pile of rubble. The temple mount will become a mere wooded ridge.”’'
EXEC add_BibleVerse @BibleId, 124026019, N'King Hezekiah and all the people of Judah did not put him to death, did they? Did not Hezekiah show reverence for the Lord and seek the Lord’s favor? Did not the Lord forgo destroying them as he threatened he would? But we are on the verge of bringing great disaster on ourselves.”'
EXEC add_BibleVerse @BibleId, 124026020, N'Now there was another man who prophesied as the Lord’s representative against this city and this land just as Jeremiah did. His name was Uriah son of Shemaiah from Kiriath Jearim.'
EXEC add_BibleVerse @BibleId, 124026021, N'When the king and all his bodyguards and officials heard what he was prophesying, the king sought to have him executed. But Uriah found out about it and fled to Egypt out of fear.'
EXEC add_BibleVerse @BibleId, 124026022, N'However, King Jehoiakim sent some men to Egypt, including Elnathan son of Achbor,'
EXEC add_BibleVerse @BibleId, 124026023, N'and they brought Uriah back from there. They took him to King Jehoiakim, who had him executed and had his body thrown into the burial place of the common people.'
EXEC add_BibleVerse @BibleId, 124026024, N'However, Ahikam son of Shaphan used his influence to keep Jeremiah from being handed over and executed by the people.'
EXEC add_BibleVerse @BibleId, 124027001, N'The Lord spoke to Jeremiah early in the reign of Josiah’s son, King Zedekiah of Judah.'
EXEC add_BibleVerse @BibleId, 124027002, N'The Lord told me, “Make a yoke out of leather straps and wooden crossbars and put it on your neck.'
EXEC add_BibleVerse @BibleId, 124027003, N'Use it to send messages to the kings of Edom, Moab, Ammon, Tyre, to King Zedekiah of Judah.'
EXEC add_BibleVerse @BibleId, 124027004, N'Charge them to give their masters a message from me. Tell them, ‘The Lord God of Israel who rules over all says to give your masters this message.'
EXEC add_BibleVerse @BibleId, 124027005, N'“I made the earth and the people and animals on it by my mighty power and great strength, and I give it to whomever I see fit.'
EXEC add_BibleVerse @BibleId, 124027006, N'I have at this time placed all these nations of yours under the power of my servant, King Nebuchadnezzar of Babylon. I have even made all the wild animals subject to him.'
EXEC add_BibleVerse @BibleId, 124027007, N'All nations must serve him and his son and grandson until the time comes for his own nation to fall. Then many nations and great kings will in turn subjugate Babylon.'
EXEC add_BibleVerse @BibleId, 124027008, N'But suppose a nation or a kingdom will not be subject to King Nebuchadnezzar of Babylon. Suppose it will not submit to the yoke of servitude to him. I, the Lord, affirm that I will punish that nation. I will use the king of Babylon to punish it with war, starvation, and disease until I have destroyed it.'
EXEC add_BibleVerse @BibleId, 124027009, N'So do not listen to your prophets or to those who claim to predict the future by divination, by dreams, by consulting the dead, or by practicing magic. They keep telling you, ‘You do not need to be subject to the king of Babylon.’'
EXEC add_BibleVerse @BibleId, 124027010, N'Do not listen to them, because their prophecies are lies. Listening to them will only cause you to be taken far away from your native land. I will drive you out of your country and you will die in exile.'
EXEC add_BibleVerse @BibleId, 124027011, N'Things will go better for the nation that submits to the yoke of servitude to the king of Babylon and is subject to him. I will leave that nation in its native land. Its people can continue to farm it and live in it. I, the Lord, affirm it!”’”'
EXEC add_BibleVerse @BibleId, 124027012, N'I told King Zedekiah of Judah the same thing. I said, “Submit to the yoke of servitude to the king of Babylon. Be subject to him and his people. Then you will continue to live.'
EXEC add_BibleVerse @BibleId, 124027013, N'There is no reason why you and your people should die in war or from starvation or disease! That’s what the Lord says will happen to any nation that will not be subject to the king of Babylon.'
EXEC add_BibleVerse @BibleId, 124027014, N'Do not listen to the prophets who are telling you that you do not need to serve the king of Babylon. For they are prophesying lies to you.'
EXEC add_BibleVerse @BibleId, 124027015, N'For I, the Lord, affirm that I did not send them. They are prophesying lies to you. If you listen to them, I will drive you and the prophets who are prophesying lies out of the land and you will all die in exile.”'
EXEC add_BibleVerse @BibleId, 124027016, N'I also told the priests and all the people, “The Lord says, ‘Do not listen to what your prophets are saying. They are prophesying to you that the valuable articles taken from the Lord’s temple will be brought back from Babylon very soon. But they are prophesying a lie to you.'
EXEC add_BibleVerse @BibleId, 124027017, N'Do not listen to them. Be subject to the king of Babylon. Then you will continue to live. Why should this city be made a pile of rubble?’”'
EXEC add_BibleVerse @BibleId, 124027018, N'I also told them, “If they are really prophets and the Lord is speaking to them, let them pray earnestly to the Lord who rules over all. Let them plead with him not to let the valuable articles that are still left in the Lord’s temple, in the royal palace, and in Jerusalem be taken away to Babylon.'
EXEC add_BibleVerse @BibleId, 124027019, N'For the Lord who rules over all has already spoken about the two bronze pillars, the large bronze basin called ‘The Sea,’ and the movable bronze stands. He has already spoken about the rest of the valuable articles that are left in this city.'
EXEC add_BibleVerse @BibleId, 124027020, N'He has already spoken about these things that King Nebuchadnezzar of Babylon did not take away when he carried Jehoiakim’s son King Jeconiah of Judah and the nobles of Judah and Jerusalem away as captives.'
EXEC add_BibleVerse @BibleId, 124027021, N'Indeed, the Lord God of Israel who rules over all has already spoken about the valuable articles that are left in the Lord’s temple, in the royal palace of Judah, and in Jerusalem.'
EXEC add_BibleVerse @BibleId, 124027022, N'He has said, ‘They will be carried off to Babylon. They will remain there until it is time for me to show consideration for them again. Then I will bring them back and restore them to this place.’ I, the Lord, affirm this!”'
EXEC add_BibleVerse @BibleId, 124028001, N'The following events occurred in that same year, early in the reign of King Zedekiah of Judah. To be more precise, it was the fifth month of the fourth year of his reign. The prophet Hananiah son of Azzur, who was from Gibeon, spoke to Jeremiah in the Lord’s temple in the presence of the priests and all the people.'
EXEC add_BibleVerse @BibleId, 124028002, N'“The Lord God of Israel who rules over all says, ‘I will break the yoke of servitude to the king of Babylon.'
EXEC add_BibleVerse @BibleId, 124028003, N'Before two years are over, I will bring back to this place everything that King Nebuchadnezzar of Babylon took from it and carried away to Babylon.'
EXEC add_BibleVerse @BibleId, 124028004, N'I will also bring back to this place Jehoiakim’s son King Jeconiah of Judah and all the exiles who were taken to Babylon.’ Indeed, the Lord affirms, ‘I will break the yoke of servitude to the king of Babylon.’”'
EXEC add_BibleVerse @BibleId, 124028005, N'Then the prophet Jeremiah responded to the prophet Hananiah in the presence of the priests and all the people who were standing in the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 124028006, N'The prophet Jeremiah said, “Amen! May the Lord do all this! May the Lord make your prophecy come true! May he bring back to this place from Babylon all the valuable articles taken from the Lord’s temple and the people who were carried into exile.'
EXEC add_BibleVerse @BibleId, 124028007, N'But listen to what I say to you and to all these people.'
EXEC add_BibleVerse @BibleId, 124028008, N'From earliest times, the prophets who preceded you and me invariably prophesied war, disaster, and plagues against many countries and great kingdoms.'
EXEC add_BibleVerse @BibleId, 124028009, N'So if a prophet prophesied peace and prosperity, it was only known that the Lord truly sent him when what he prophesied came true.”'
EXEC add_BibleVerse @BibleId, 124028010, N'The prophet Hananiah then took the yoke off the prophet Jeremiah’s neck and broke it.'
EXEC add_BibleVerse @BibleId, 124028011, N'Then he spoke up in the presence of all the people. “The Lord says, ‘In the same way I will break the yoke of servitude of all the nations to King Nebuchadnezzar of Babylon before two years are over.’” After he heard this, the prophet Jeremiah departed and went on his way.'
EXEC add_BibleVerse @BibleId, 124028012, N'But shortly after the prophet Hananiah had broken the yoke off the prophet Jeremiah’s neck, the Lord spoke to Jeremiah.'
EXEC add_BibleVerse @BibleId, 124028013, N'“Go and tell Hananiah that the Lord says, ‘You have indeed broken the wooden yoke. But you have only succeeded in replacing it with an iron one!'
EXEC add_BibleVerse @BibleId, 124028014, N'For the Lord God of Israel who rules over all says, “I have put an irresistible yoke of servitude on all these nations so they will serve King Nebuchadnezzar of Babylon. And they will indeed serve him. I have even given him control over the wild animals.”’”'
EXEC add_BibleVerse @BibleId, 124028015, N'Then the prophet Jeremiah told the prophet Hananiah, “Listen, Hananiah! The Lord did not send you! You are making these people trust in a lie!'
EXEC add_BibleVerse @BibleId, 124028016, N'So the Lord says, ‘I will most assuredly remove you from the face of the earth. You will die this very year because you have counseled rebellion against the Lord.’”'
EXEC add_BibleVerse @BibleId, 124028017, N'In the seventh month of that very same year the prophet Hananiah died.'
EXEC add_BibleVerse @BibleId, 124029001, N'The prophet Jeremiah sent a letter to the exiles Nebuchadnezzar had carried off from Jerusalem to Babylon. It was addressed to the elders who were left among the exiles, to the priests, to the prophets, and to all the other people who were exiled in Babylon.'
EXEC add_BibleVerse @BibleId, 124029002, N'He sent it after King Jeconiah, the queen mother, the palace officials, the leaders of Judah and Jerusalem, the craftsmen, and the metal workers had been exiled from Jerusalem.'
EXEC add_BibleVerse @BibleId, 124029003, N'He sent it with Elasah son of Shaphan and Gemariah son of Hilkiah. King Zedekiah of Judah had sent these men to Babylon to King Nebuchadnezzar of Babylon. The letter said:'
EXEC add_BibleVerse @BibleId, 124029004, N'“The Lord God of Israel who rules over all says to all those he sent into exile to Babylon from Jerusalem,'
EXEC add_BibleVerse @BibleId, 124029005, N'‘Build houses and settle down. Plant gardens and eat what they produce.'
EXEC add_BibleVerse @BibleId, 124029006, N'Marry and have sons and daughters. Find wives for your sons and allow your daughters get married so that they too can have sons and daughters. Grow in number; do not dwindle away.'
EXEC add_BibleVerse @BibleId, 124029007, N'Work to see that the city where I sent you as exiles enjoys peace and prosperity. Pray to the Lord for it. For as it prospers you will prosper.’'
EXEC add_BibleVerse @BibleId, 124029008, N'“For the Lord God of Israel who rules over all says, ‘Do not let the prophets or those among you who claim to be able to predict the future by divination deceive you. And do not pay any attention to the dreams that you are encouraging them to dream.'
EXEC add_BibleVerse @BibleId, 124029009, N'They are prophesying lies to you and claiming my authority to do so. But I did not send them. I, the Lord, affirm it!’'
EXEC add_BibleVerse @BibleId, 124029010, N'“For the Lord says, ‘Only when the seventy years of Babylonian rule are over will I again take up consideration for you. Then I will fulfill my gracious promise to you and restore you to your homeland.'
EXEC add_BibleVerse @BibleId, 124029011, N'For I know what I have planned for you,’ says the Lord. ‘I have plans to prosper you, not to harm you. I have plans to give you a future filled with hope.'
EXEC add_BibleVerse @BibleId, 124029012, N'When you call out to me and come to me in prayer, I will hear your prayers.'
EXEC add_BibleVerse @BibleId, 124029013, N'When you seek me in prayer and worship, you will find me available to you. If you seek me with all your heart and soul,'
EXEC add_BibleVerse @BibleId, 124029014, N'I will make myself available to you,’ says the Lord. ‘Then I will reverse your plight and will regather you from all the nations and all the places where I have exiled you,’ says the Lord. ‘I will bring you back to the place from which I exiled you.’'
EXEC add_BibleVerse @BibleId, 124029015, N'“You say, ‘The Lord has raised up prophets of good news for us here in Babylon.’'
EXEC add_BibleVerse @BibleId, 124029016, N'But just listen to what the Lord has to say about the king who occupies David’s throne and all your fellow countrymen who are still living in this city of Jerusalem and were not carried off into exile with you.'
EXEC add_BibleVerse @BibleId, 124029017, N'The Lord who rules over all says, ‘I will bring war, starvation, and disease on them. I will treat them like figs that are so rotten they cannot be eaten.'
EXEC add_BibleVerse @BibleId, 124029018, N'I will chase after them with war, starvation, and disease. I will make all the kingdoms of the earth horrified at what happens to them. I will make them examples of those who are cursed, objects of horror, hissing scorn, and ridicule among all the nations where I exile them.'
EXEC add_BibleVerse @BibleId, 124029019, N'For they have not paid attention to what I said to them through my servants the prophets whom I sent to them over and over again,’ says the Lord. ‘And you exiles have not paid any attention to them either,’ says the Lord.'
EXEC add_BibleVerse @BibleId, 124029020, N'‘So pay attention to what I, the Lord, have said, all you exiles whom I have sent to Babylon from Jerusalem.’'
EXEC add_BibleVerse @BibleId, 124029021, N'“The Lord God of Israel who rules over all also has something to say about Ahab son of Kolaiah and Zedekiah son of Maaseiah, who are prophesying lies to you and claiming my authority to do so. ‘I will hand them over to King Nebuchadnezzar of Babylon and he will execute them before your very eyes.'
EXEC add_BibleVerse @BibleId, 124029022, N'And all the exiles of Judah who are in Babylon will use them as examples when they put a curse on anyone. They will say, “May the Lord treat you like Zedekiah and Ahab whom the king of Babylon roasted to death in the fire!”'
EXEC add_BibleVerse @BibleId, 124029023, N'This will happen to them because they have done what is shameful in Israel. They have committed adultery with their neighbors’ wives and have spoken lies while claiming my authority. They have spoken words that I did not command them to speak. I know what they have done. I have been a witness to it,’ says the Lord.”'
EXEC add_BibleVerse @BibleId, 124029024, N'The Lord told Jeremiah, “Tell Shemaiah the Nehelamite'
EXEC add_BibleVerse @BibleId, 124029025, N'that the Lord God of Israel who rules over all has a message for him. Tell him, ‘On your own initiative you sent a letter to the priest Zephaniah son of Maaseiah and to all the other priests and to all the people in Jerusalem. In your letter you said to Zephaniah,'
EXEC add_BibleVerse @BibleId, 124029026, N'“The Lord has made you priest in place of Jehoiada. He has put you in charge in the Lord’s temple of controlling any lunatic who pretends to be a prophet. And it is your duty to put any such person in the stocks with an iron collar around his neck.'
EXEC add_BibleVerse @BibleId, 124029027, N'You should have reprimanded Jeremiah from Anathoth who is pretending to be a prophet among you!'
EXEC add_BibleVerse @BibleId, 124029028, N'For he has even sent a message to us here in Babylon. He wrote and told us, “You will be there a long time. Build houses and settle down. Plant gardens and eat what they produce.”’”'
EXEC add_BibleVerse @BibleId, 124029029, N'Zephaniah the priest read that letter to the prophet Jeremiah.'
EXEC add_BibleVerse @BibleId, 124029030, N'Then the Lord spoke to Jeremiah.'
EXEC add_BibleVerse @BibleId, 124029031, N'“Send a message to all the exiles in Babylon. Tell them, ‘The Lord has spoken about Shemaiah the Nehelamite. “Shemaiah has spoken to you as a prophet even though I did not send him. He is making you trust in a lie.'
EXEC add_BibleVerse @BibleId, 124029032, N'Because he has done this,” the Lord says, “I will punish Shemaiah the Nehelamite and his whole family. There will not be any of them left to experience the good things that I will do for my people. I, the Lord, affirm it! For he counseled rebellion against the Lord.”’”'
EXEC add_BibleVerse @BibleId, 124030001, N'The Lord spoke to Jeremiah.'
EXEC add_BibleVerse @BibleId, 124030002, N'“The Lord God of Israel says, ‘Write everything that I am about to tell you in a scroll.'
EXEC add_BibleVerse @BibleId, 124030003, N'For I, the Lord, affirm that the time will come when I will reverse the plight of my people, Israel and Judah,’ says the Lord. ‘I will bring them back to the land I gave their ancestors and they will take possession of it once again.’”'
EXEC add_BibleVerse @BibleId, 124030004, N'So here is what the Lord has to say about Israel and Judah.'
EXEC add_BibleVerse @BibleId, 124030005, N'Yes, here is what he says: “You hear cries of panic and of terror; there is no peace in sight.'
EXEC add_BibleVerse @BibleId, 124030006, N'Ask yourselves this and consider it carefully: Have you ever seen a man give birth to a baby? Why then do I see all these strong men grabbing their stomachs in pain like a woman giving birth? And why do their faces turn so deathly pale?'
EXEC add_BibleVerse @BibleId, 124030007, N'Alas, what a terrible time of trouble it is! There has never been any like it. It is a time of trouble for the descendants of Jacob, but some of them will be rescued out of it.'
EXEC add_BibleVerse @BibleId, 124030008, N'When the time for them to be rescued comes,” says the Lord who rules over all, “I will rescue you from foreign subjugation. I will deliver you from captivity. Foreigners will then no longer subjugate them.'
EXEC add_BibleVerse @BibleId, 124030009, N'But they will be subject to the Lord their God and to the Davidic ruler whom I will raise up as king over them.'
EXEC add_BibleVerse @BibleId, 124030010, N'So I, the Lord, tell you not to be afraid, you descendants of Jacob, my servants. Do not be terrified, people of Israel. For I will rescue you and your descendants from a faraway land where you are captives. The descendants of Jacob will return to their land and enjoy peace. They will be secure and no one will terrify them.'
EXEC add_BibleVerse @BibleId, 124030011, N'For I, the Lord, affirm that I will be with you and will rescue you. I will completely destroy all the nations where I scattered you. But I will not completely destroy you. I will indeed discipline you, but only in due measure. I will not allow you to go entirely unpunished.”'
EXEC add_BibleVerse @BibleId, 124030012, N'Moreover, the Lord says to the people of Zion, “Your injuries are incurable; your wounds are severe.'
EXEC add_BibleVerse @BibleId, 124030013, N'There is no one to plead your cause. There are no remedies for your wounds. There is no healing for you.'
EXEC add_BibleVerse @BibleId, 124030014, N'All your allies have abandoned you. They no longer have any concern for you. For I have attacked you like an enemy would. I have chastened you cruelly. For your wickedness is so great and your sin is so much.'
EXEC add_BibleVerse @BibleId, 124030015, N'Why do you complain about your injuries, that your pain is incurable? I have done all this to you because your wickedness is so great and your sin is so much.'
EXEC add_BibleVerse @BibleId, 124030016, N'But all who destroyed you will be destroyed. All your enemies will go into exile. Those who plundered you will be plundered. I will cause those who pillaged you to be pillaged.'
EXEC add_BibleVerse @BibleId, 124030017, N'Yes, I will restore you to health. I will heal your wounds. I, the Lord, affirm it! For you have been called an outcast, Zion, whom no one cares for.”'
EXEC add_BibleVerse @BibleId, 124030018, N'The Lord says, “I will restore the ruined houses of the descendants of Jacob. I will show compassion on their ruined homes. Every city will be rebuilt on its former ruins. Every fortified dwelling will occupy its traditional site.'
EXEC add_BibleVerse @BibleId, 124030019, N'Out of those places you will hear songs of thanksgiving and the sounds of laughter and merriment. I will increase their number and they will not dwindle away. I will bring them honor and they will no longer be despised.'
EXEC add_BibleVerse @BibleId, 124030020, N'The descendants of Jacob will enjoy their former privileges. Their community will be reestablished in my favor and I will punish all who try to oppress them.'
EXEC add_BibleVerse @BibleId, 124030021, N'One of their own people will be their leader. Their ruler will come from their own number. I will invite him to approach me, and he will do so. For no one would dare approach me on his own. I, the Lord, affirm it!'
EXEC add_BibleVerse @BibleId, 124030022, N'Then you will again be my people and I will be your God.'
EXEC add_BibleVerse @BibleId, 124030023, N'Just watch! The wrath of the Lord will come like a storm. Like a raging storm it will rage down on the heads of those who are wicked.'
EXEC add_BibleVerse @BibleId, 124030024, N'The anger of the Lord will not turn back until he has fully carried out his intended purposes. In days to come you will come to understand this.'
EXEC add_BibleVerse @BibleId, 124031001, N'At that time I will be the God of all the clans of Israel and they will be my people. I, the Lord, affirm it!”'
EXEC add_BibleVerse @BibleId, 124031002, N'The Lord says, “The people of Israel who survived death at the hands of the enemy will find favor in the wilderness as they journey to find rest for themselves.'
EXEC add_BibleVerse @BibleId, 124031003, N'In a far-off land the Lord will manifest himself to them. He will say to them, ‘I have loved you with an everlasting love. That is why I have continued to be faithful to you.'
EXEC add_BibleVerse @BibleId, 124031004, N'I will rebuild you, my dear children Israel, so that you will once again be built up. Once again you will take up the tambourine and join in the happy throng of dancers.'
EXEC add_BibleVerse @BibleId, 124031005, N'Once again you will plant vineyards on the hills of Samaria. Those who plant them will once again enjoy their fruit.'
EXEC add_BibleVerse @BibleId, 124031006, N'Yes, a time is coming when watchmen will call out on the mountains of Ephraim, “Come! Let us go to Zion to worship the Lord our God!”’”'
EXEC add_BibleVerse @BibleId, 124031007, N'Moreover, the Lord says, “Sing for joy for the descendants of Jacob. Utter glad shouts for that foremost of the nations. Make your praises heard. Then say, ‘Lord, rescue your people. Deliver those of Israel who remain alive.’'
EXEC add_BibleVerse @BibleId, 124031008, N'Then I will reply, ‘I will bring them back from the land of the north. I will gather them in from the distant parts of the earth. Blind and lame people will come with them, so will pregnant women and women about to give birth. A vast throng of people will come back here.'
EXEC add_BibleVerse @BibleId, 124031009, N'They will come back shedding tears of contrition. I will bring them back praying prayers of repentance. I will lead them besides streams of water, along smooth paths where they will never stumble. I will do this because I am Israel’s father; Ephraim is my firstborn son.’”'
EXEC add_BibleVerse @BibleId, 124031010, N'Hear what the Lord has to say, O nations. Proclaim it in the faraway lands along the sea. Say, “The one who scattered Israel will regather them. He will watch over his people like a shepherd watches over his flock.”'
EXEC add_BibleVerse @BibleId, 124031011, N'For the Lord will rescue the descendants of Jacob. He will secure their release from those who had overpowered them.'
EXEC add_BibleVerse @BibleId, 124031012, N'They will come and shout for joy on Mount Zion. They will be radiant with joy over the good things the Lord provides, the grain, the fresh wine, the olive oil, the young sheep and calves he has given to them. They will be like a well-watered garden and will not grow faint or weary any more.'
EXEC add_BibleVerse @BibleId, 124031013, N'The Lord says, “At that time young women will dance and be glad. Young men and old men will rejoice. I will turn their grief into gladness. I will give them comfort and joy in place of their sorrow.'
EXEC add_BibleVerse @BibleId, 124031014, N'I will provide the priests with abundant provisions. My people will be filled to the full with the good things I provide.”'
EXEC add_BibleVerse @BibleId, 124031015, N'The Lord says, “A sound is heard in Ramah, a sound of crying in bitter grief. It is the sound of Rachel weeping for her children and refusing to be comforted, because her children are gone.”'
EXEC add_BibleVerse @BibleId, 124031016, N'The Lord says to her, “Stop crying! Do not shed any more tears! For your heartfelt repentance will be rewarded. Your children will return from the land of the enemy. I, the Lord, affirm it!'
EXEC add_BibleVerse @BibleId, 124031017, N'Indeed, there is hope for your posterity. Your children will return to their own territory. I, the Lord, affirm it!'
EXEC add_BibleVerse @BibleId, 124031018, N'I have indeed heard the people of Israel say mournfully, ‘We were like a calf untrained to the yoke. You disciplined us and we learned from it. Let us come back to you and we will do so, for you are the Lord our God.'
EXEC add_BibleVerse @BibleId, 124031019, N'For after we turned away from you we repented. After we came to our senses we beat our breasts in sorrow. We are ashamed and humiliated because of the disgraceful things we did previously.’'
EXEC add_BibleVerse @BibleId, 124031020, N'Indeed, the people of Israel are my dear children. They are the children I take delight in. For even though I must often rebuke them, I still remember them with fondness. So I am deeply moved with pity for them and will surely have compassion on them. I, the Lord, affirm it!'
EXEC add_BibleVerse @BibleId, 124031021, N'I will say, ‘My dear children of Israel, keep in mind the road you took when you were carried off. Mark off in your minds the landmarks. Make a mental note of telltale signs marking the way back. Return, my dear children of Israel. Return to these cities of yours.'
EXEC add_BibleVerse @BibleId, 124031022, N'How long will you vacillate, you who were once like an unfaithful daughter? For I, the Lord, promise to bring about something new on the earth, something as unique as a woman protecting a man!’”'
EXEC add_BibleVerse @BibleId, 124031023, N'The Lord God of Israel who rules over all says, “I will restore the people of Judah to their land and to their towns. When I do, they will again say of Jerusalem, ‘May the Lord bless you, you holy mountain, the place where righteousness dwells.’'
EXEC add_BibleVerse @BibleId, 124031024, N'The land of Judah will be inhabited by people who live in its towns as well as by farmers and shepherds with their flocks.'
EXEC add_BibleVerse @BibleId, 124031025, N'I will fully satisfy the needs of those who are weary and fully refresh the souls of those who are faint.'
EXEC add_BibleVerse @BibleId, 124031026, N'Then they will say, ‘Under these conditions I can enjoy sweet sleep when I wake up and look around.’”'
EXEC add_BibleVerse @BibleId, 124031027, N'“Indeed, a time is coming,” says the Lord, “when I will cause people and animals to sprout up in the lands of Israel and Judah.'
EXEC add_BibleVerse @BibleId, 124031028, N'In the past I saw to it that they were uprooted and torn down, that they were destroyed and demolished. But now I will see to it that they are built up and firmly planted. I, the Lord, affirm it!”'
EXEC add_BibleVerse @BibleId, 124031029, N'“When that time comes, people will no longer say, ‘The parents have eaten sour grapes, but the children’s teeth have grown numb.’'
EXEC add_BibleVerse @BibleId, 124031030, N'Rather, each person will die for his own sins. The teeth of the person who eats the sour grapes will themselves grow numb.'
EXEC add_BibleVerse @BibleId, 124031031, N'“Indeed, a time is coming,” says the Lord, “when I will make a new covenant with the people of Israel and Judah.'
EXEC add_BibleVerse @BibleId, 124031032, N'It will not be like the old covenant that I made with their ancestors when I delivered them from Egypt. For they violated that covenant, even though I was like a faithful husband to them,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124031033, N'“But I will make a new covenant with the whole nation of Israel after I plant them back in the land,” says the Lord. “I will put my law within them and write it on their hearts and minds. I will be their God and they will be my people.'
EXEC add_BibleVerse @BibleId, 124031034, N'“People will no longer need to teach their neighbors and relatives to know me. For all of them, from the least important to the most important, will know me,” says the Lord. “For I will forgive their sin and will no longer call to mind the wrong they have done.”'
EXEC add_BibleVerse @BibleId, 124031035, N'The Lord has made a promise to Israel. He promises it as the one who fixed the sun to give light by day and the moon and stars to give light by night. He promises it as the one who stirs up the sea so that its waves roll. He promises it as the one who is known as the Lord who rules over all.'
EXEC add_BibleVerse @BibleId, 124031036, N'The Lord affirms, “The descendants of Israel will not cease forever to be a nation in my sight. That could only happen if the fixed ordering of the heavenly lights were to cease to operate before me.”'
EXEC add_BibleVerse @BibleId, 124031037, N'The Lord says, “I will not reject all the descendants of Israel because of all that they have done. That could only happen if the heavens above could be measured or the foundations of the earth below could all be explored,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124031038, N'“Indeed a time is coming,” says the Lord, “when the city of Jerusalem will be rebuilt as my special city. It will be built from the Tower of Hananel westward to the Corner Gate.'
EXEC add_BibleVerse @BibleId, 124031039, N'The boundary line will extend beyond that, straight west from there to the Hill of Gareb and then turn southward to Goah.'
EXEC add_BibleVerse @BibleId, 124031040, N'The whole valley where dead bodies and sacrificial ashes are thrown and all the terraced fields out to the Kidron Valley on the east as far north as the Horse Gate will be included within this city that is sacred to the Lord. The city will never again be torn down or destroyed.”'
EXEC add_BibleVerse @BibleId, 124032001, N'In the tenth year that Zedekiah was ruling over Judah the Lord spoke to Jeremiah. That was the same as the eighteenth year of Nebuchadnezzar.'
EXEC add_BibleVerse @BibleId, 124032002, N'Now at that time, the armies of the king of Babylon were besieging Jerusalem. The prophet Jeremiah was confined in the courtyard of the guardhouse attached to the royal palace of Judah.'
EXEC add_BibleVerse @BibleId, 124032003, N'For King Zedekiah had confined Jeremiah there after he had reproved him for prophesying as he did. He had asked Jeremiah, “Why do you keep prophesying these things? Why do you keep saying that the Lord says, ‘I will hand this city over to the king of Babylon? I will let him capture it.'
EXEC add_BibleVerse @BibleId, 124032004, N'King Zedekiah of Judah will not escape from the Babylonians. He will certainly be handed over to the king of Babylon. He must answer personally to the king of Babylon and confront him face to face.'
EXEC add_BibleVerse @BibleId, 124032005, N'Zedekiah will be carried off to Babylon and will remain there until I have fully dealt with him. I, the Lord, affirm it! Even if you continue to fight against the Babylonians, you cannot win.’”'
EXEC add_BibleVerse @BibleId, 124032006, N'So now, Jeremiah said, “The Lord told me,'
EXEC add_BibleVerse @BibleId, 124032007, N'‘Hanamel, the son of your uncle Shallum, will come to you soon. He will say to you, “Buy my field at Anathoth because you are entitled as my closest relative to buy it.”’'
EXEC add_BibleVerse @BibleId, 124032008, N'Now it happened just as the Lord had said! My cousin Hanamel came to me in the courtyard of the guardhouse. He said to me, ‘Buy my field which is at Anathoth in the territory of the tribe of Benjamin. Buy it for yourself since you are entitled as my closest relative to take possession of it for yourself.’ When this happened, I recognized that the Lord had indeed spoken to me.'
EXEC add_BibleVerse @BibleId, 124032009, N'So I bought the field at Anathoth from my cousin Hanamel. I weighed out seven ounces of silver and gave it to him to pay for it.'
EXEC add_BibleVerse @BibleId, 124032010, N'I signed the deed of purchase, sealed it, and had some men serve as witnesses to the purchase. I weighed out the silver for him on a scale.'
EXEC add_BibleVerse @BibleId, 124032011, N'There were two copies of the deed of purchase. One was sealed and contained the order of transfer and the conditions of purchase. The other was left unsealed.'
EXEC add_BibleVerse @BibleId, 124032012, N'I took both copies of the deed of purchase and gave them to Baruch son of Neriah, the son of Mahseiah. I gave them to him in the presence of my cousin Hanamel, the witnesses who had signed the deed of purchase, and all the Judeans who were housed in the courtyard of the guardhouse.'
EXEC add_BibleVerse @BibleId, 124032013, N'In the presence of all these people I instructed Baruch,'
EXEC add_BibleVerse @BibleId, 124032014, N'‘The Lord God of Israel who rules over all says, “Take these documents, both the sealed copy of the deed of purchase and the unsealed copy. Put them in a clay jar so that they may be preserved for a long time to come.”’'
EXEC add_BibleVerse @BibleId, 124032015, N'For the Lord God of Israel who rules over all says, “Houses, fields, and vineyards will again be bought in this land.”’'
EXEC add_BibleVerse @BibleId, 124032016, N'“After I had given the copies of the deed of purchase to Baruch son of Neriah, I prayed to the Lord,'
EXEC add_BibleVerse @BibleId, 124032017, N'‘Oh, Lord God, you did indeed make heaven and earth by your mighty power and great strength. Nothing is too hard for you!'
EXEC add_BibleVerse @BibleId, 124032018, N'You show unfailing love to thousands. But you also punish children for the sins of their parents. You are the great and powerful God who is known as the Lord who rules over all.'
EXEC add_BibleVerse @BibleId, 124032019, N'You plan great things and you do mighty deeds. You see everything people do. You reward each of them for the way they live and for the things they do.'
EXEC add_BibleVerse @BibleId, 124032020, N'You did miracles and amazing deeds in the land of Egypt which have had lasting effect. By this means you gained both in Israel and among humankind a renown that lasts to this day.'
EXEC add_BibleVerse @BibleId, 124032021, N'You used your mighty power and your great strength to perform miracles and amazing deeds and to bring great terror on the Egyptians. By this means you brought your people Israel out of the land of Egypt.'
EXEC add_BibleVerse @BibleId, 124032022, N'You kept the promise that you swore on oath to their ancestors. You gave them a land flowing with milk and honey.'
EXEC add_BibleVerse @BibleId, 124032023, N'But when they came in and took possession of it, they did not obey you or live as you had instructed them. They did not do anything that you commanded them to do. So you brought all this disaster on them.'
EXEC add_BibleVerse @BibleId, 124032024, N'Even now siege ramps have been built up around the city in order to capture it. War, starvation, and disease are sure to make the city fall into the hands of the Babylonians who are attacking it. Lord, you threatened that this would happen. Now you can see that it is already taking place.'
EXEC add_BibleVerse @BibleId, 124032025, N'The city is sure to fall into the hands of the Babylonians. Yet, in spite of this, you, Lord God, have said to me, “Buy that field with silver and have the transaction legally witnessed.”’”'
EXEC add_BibleVerse @BibleId, 124032026, N'The Lord answered Jeremiah.'
EXEC add_BibleVerse @BibleId, 124032027, N'“I am the Lord, the God of all humankind. There is, indeed, nothing too difficult for me.'
EXEC add_BibleVerse @BibleId, 124032028, N'Therefore I, the Lord, say: ‘I will indeed hand this city over to King Nebuchadnezzar of Babylon and the Babylonian army. They will capture it.'
EXEC add_BibleVerse @BibleId, 124032029, N'The Babylonian soldiers that are attacking this city will break into it and set it on fire. They will burn it down along with the houses where people have made me angry by offering sacrifices to the god Baal and by pouring out drink offerings to other gods on their rooftops.'
EXEC add_BibleVerse @BibleId, 124032030, N'This will happen because the people of Israel and Judah have repeatedly done what displeases me from their earliest history until now and because they have repeatedly made me angry by the things they have done. I, the Lord, affirm it!'
EXEC add_BibleVerse @BibleId, 124032031, N'This will happen because the people of this city have aroused my anger and my wrath since the time they built it until now. They have made me so angry that I am determined to remove it from my sight.'
EXEC add_BibleVerse @BibleId, 124032032, N'I am determined to do so because the people of Israel and Judah have made me angry with all their wickedness – they, their kings, their officials, their priests, their prophets, and especially the people of Judah and the citizens of Jerusalem have done this wickedness.'
EXEC add_BibleVerse @BibleId, 124032033, N'They have turned away from me instead of turning to me. I tried over and over again to instruct them, but they did not listen and respond to correction.'
EXEC add_BibleVerse @BibleId, 124032034, N'They set up their disgusting idols in the temple which I have claimed for my own and defiled it.'
EXEC add_BibleVerse @BibleId, 124032035, N'They built places of worship for the god Baal in the Valley of Ben Hinnom so that they could sacrifice their sons and daughters to the god Molech. Such a disgusting practice was not something I commanded them to do! It never even entered my mind to command them to do such a thing! So Judah is certainly liable for punishment.’'
EXEC add_BibleVerse @BibleId, 124032036, N'“You and your people are right in saying, ‘War, starvation, and disease are sure to make this city fall into the hands of the king of Babylon.’ But now I, the Lord God of Israel, have something further to say about this city:'
EXEC add_BibleVerse @BibleId, 124032037, N'‘I will certainly regather my people from all the countries where I will have exiled them in my anger, fury, and great wrath. I will bring them back to this place and allow them to live here in safety.'
EXEC add_BibleVerse @BibleId, 124032038, N'They will be my people, and I will be their God.'
EXEC add_BibleVerse @BibleId, 124032039, N'I will give them a single-minded purpose to live in a way that always shows respect for me. They will want to do that for their own good and the good of the children who descend from them.'
EXEC add_BibleVerse @BibleId, 124032040, N'I will make a lasting covenant with them that I will never stop doing good to them. I will fill their hearts and minds with respect for me so that they will never again turn away from me.'
EXEC add_BibleVerse @BibleId, 124032041, N'I will take delight in doing good to them. I will faithfully and wholeheartedly plant them firmly in the land.’'
EXEC add_BibleVerse @BibleId, 124032042, N'“For I, the Lord, say: ‘I will surely bring on these people all the good fortune that I am hereby promising them. I will be just as sure to do that as I have been in bringing all this great disaster on them.'
EXEC add_BibleVerse @BibleId, 124032043, N'You and your people are saying that this land will become desolate, uninhabited by either people or animals. You are saying that it will be handed over to the Babylonians. But fields will again be bought in this land.'
EXEC add_BibleVerse @BibleId, 124032044, N'Fields will again be bought with silver, and deeds of purchase signed, sealed, and witnessed. This will happen in the territory of Benjamin, the villages surrounding Jerusalem, the towns in Judah, the southern hill country, the western foothills, and southern Judah. For I will restore them to their land. I, the Lord, affirm it!’”'
EXEC add_BibleVerse @BibleId, 124033001, N'The Lord spoke to Jeremiah a second time while he was still confined in the courtyard of the guardhouse.'
EXEC add_BibleVerse @BibleId, 124033002, N'“I, the Lord, do these things. I, the Lord, form the plan to bring them about. I am known as the Lord. I say to you,'
EXEC add_BibleVerse @BibleId, 124033003, N'‘Call on me in prayer and I will answer you. I will show you great and mysterious things which you still do not know about.’'
EXEC add_BibleVerse @BibleId, 124033004, N'For I, the Lord God of Israel, have something more to say about the houses in this city and the royal buildings which have been torn down for defenses against the siege ramps and military incursions of the Babylonians:'
EXEC add_BibleVerse @BibleId, 124033005, N'‘The defenders of the city will go out and fight with the Babylonians. But they will only fill those houses and buildings with the dead bodies of the people that I will kill in my anger and my wrath. That will happen because I have decided to turn my back on this city on account of the wicked things they have done.'
EXEC add_BibleVerse @BibleId, 124033006, N'But I will most surely heal the wounds of this city and restore it and its people to health. I will show them abundant peace and security.'
EXEC add_BibleVerse @BibleId, 124033007, N'I will restore Judah and Israel and will rebuild them as they were in days of old.'
EXEC add_BibleVerse @BibleId, 124033008, N'I will purify them from all the sin that they committed against me. I will forgive all their sins which they committed in rebelling against me.'
EXEC add_BibleVerse @BibleId, 124033009, N'All the nations will hear about all the good things which I will do to them. This city will bring me fame, honor, and praise before them for the joy that I bring it. The nations will tremble in awe at all the peace and prosperity that I will provide for it.’'
EXEC add_BibleVerse @BibleId, 124033010, N'“I, the Lord, say: ‘You and your people are saying about this place, “It lies in ruins. There are no people or animals in it.” That is true. The towns of Judah and the streets of Jerusalem will soon be desolate, uninhabited either by people or by animals. But happy sounds will again be heard in these places.'
EXEC add_BibleVerse @BibleId, 124033011, N'Once again there will be sounds of joy and gladness and the glad celebrations of brides and grooms. Once again people will bring their thank offerings to the temple of the Lord and will say, “Give thanks to the Lord who rules over all. For the Lord is good and his unfailing love lasts forever.” For I, the Lord, affirm that I will restore the land to what it was in days of old.’'
EXEC add_BibleVerse @BibleId, 124033012, N'“I, the Lord who rules over all, say: ‘This place will indeed lie in ruins. There will be no people or animals in it. But there will again be in it and in its towns sheepfolds where shepherds can rest their sheep.'
EXEC add_BibleVerse @BibleId, 124033013, N'I, the Lord, say that shepherds will once again count their sheep as they pass into the fold. They will do this in all the towns in the southern hill country, the western foothills, the southern hill country, the territory of Benjamin, the villages surrounding Jerusalem, and the towns of Judah.’'
EXEC add_BibleVerse @BibleId, 124033014, N'“I, the Lord, affirm: ‘The time will certainly come when I will fulfill my gracious promise concerning the nations of Israel and Judah.'
EXEC add_BibleVerse @BibleId, 124033015, N'In those days and at that time I will raise up for them a righteous descendant of David. “‘He will do what is just and right in the land.'
EXEC add_BibleVerse @BibleId, 124033016, N'Under his rule Judah will enjoy safety and Jerusalem will live in security. At that time Jerusalem will be called “The Lord has provided us with justice.”'
EXEC add_BibleVerse @BibleId, 124033017, N'For I, the Lord, promise: “David will never lack a successor to occupy the throne over the nation of Israel.'
EXEC add_BibleVerse @BibleId, 124033018, N'Nor will the Levitical priests ever lack someone to stand before me and continually offer up burnt offerings, sacrifice cereal offerings, and offer the other sacrifices.”’”'
EXEC add_BibleVerse @BibleId, 124033019, N'The Lord spoke further to Jeremiah.'
EXEC add_BibleVerse @BibleId, 124033020, N'“I, Lord, make the following promise: ‘I have made a covenant with the day and with the night that they will always come at their proper times. Only if you people could break that covenant'
EXEC add_BibleVerse @BibleId, 124033021, N'could my covenant with my servant David and my covenant with the Levites ever be broken. So David will by all means always have a descendant to occupy his throne as king and the Levites will by all means always have priests who will minister before me.'
EXEC add_BibleVerse @BibleId, 124033022, N'I will make the children who follow one another in the line of my servant David very numerous. I will also make the Levites who minister before me very numerous. I will make them all as numerous as the stars in the sky and as the sands which are on the seashore.’”'
EXEC add_BibleVerse @BibleId, 124033023, N'The Lord spoke still further to Jeremiah.'
EXEC add_BibleVerse @BibleId, 124033024, N'“You have surely noticed what these people are saying, haven’t you? They are saying, ‘The Lord has rejected the two families of Israel and Judah that he chose.’ So they have little regard that my people will ever again be a nation.'
EXEC add_BibleVerse @BibleId, 124033025, N'But I, the Lord, make the following promise: I have made a covenant governing the coming of day and night. I have established the fixed laws governing heaven and earth.'
EXEC add_BibleVerse @BibleId, 124033026, N'Just as surely as I have done this, so surely will I never reject the descendants of Jacob. Nor will I ever refuse to choose one of my servant David’s descendants to rule over the descendants of Abraham, Isaac, and Jacob. Indeed, I will restore them and show mercy to them.”'
EXEC add_BibleVerse @BibleId, 124034001, N'The Lord spoke to Jeremiah while King Nebuchadnezzar of Babylon was attacking Jerusalem and the towns around it with a large army. This army consisted of troops from his own army and from the kingdoms and peoples of the lands under his dominion.'
EXEC add_BibleVerse @BibleId, 124034002, N'The Lord God of Israel told Jeremiah to go and give King Zedekiah of Judah a message. He told Jeremiah to tell him, “The Lord says, ‘I am going to hand this city over to the king of Babylon and he will burn it down.'
EXEC add_BibleVerse @BibleId, 124034003, N'You yourself will not escape his clutches, but will certainly be captured and handed over to him. You must confront the king of Babylon face to face and answer to him personally. Then you must go to Babylon.'
EXEC add_BibleVerse @BibleId, 124034004, N'However, listen to what I, the Lord, promise you, King Zedekiah of Judah. I, the Lord, promise that you will not die in battle or be executed.'
EXEC add_BibleVerse @BibleId, 124034005, N'You will die a peaceful death. They will burn incense at your burial just as they did at the burial of your ancestors, the former kings who preceded you. They will mourn for you, saying, “Poor, poor master!” Indeed, you have my own word on this. I, the Lord, affirm it!’”'
EXEC add_BibleVerse @BibleId, 124034006, N'The prophet Jeremiah told all this to King Zedekiah of Judah in Jerusalem.'
EXEC add_BibleVerse @BibleId, 124034007, N'He did this while the army of the king of Babylon was attacking Jerusalem and the cities of Lachish and Azekah. He was attacking these cities because they were the only fortified cities of Judah which were still holding out.'
EXEC add_BibleVerse @BibleId, 124034008, N'The Lord spoke to Jeremiah after King Zedekiah had made a covenant with all the people in Jerusalem to grant their slaves their freedom.'
EXEC add_BibleVerse @BibleId, 124034009, N'Everyone was supposed to free their male and female Hebrew slaves. No one was supposed to keep a fellow Judean enslaved.'
EXEC add_BibleVerse @BibleId, 124034010, N'All the people and their leaders had agreed to this. They had agreed to free their male and female slaves and not keep them enslaved any longer. They originally complied with the covenant and freed them.'
EXEC add_BibleVerse @BibleId, 124034011, N'But later they had changed their minds. They had taken back their male and female slaves that they had freed and forced them to be slaves again.'
EXEC add_BibleVerse @BibleId, 124034012, N'That was when the Lord spoke to Jeremiah,'
EXEC add_BibleVerse @BibleId, 124034013, N'“The Lord God of Israel has a message for you. ‘I made a covenant with your ancestors when I brought them out of Egypt where they had been slaves. It stipulated,'
EXEC add_BibleVerse @BibleId, 124034014, N'“Every seven years each of you must free any fellow Hebrews who have sold themselves to you. After they have served you for six years, you shall set them free.” But your ancestors did not obey me or pay any attention to me.'
EXEC add_BibleVerse @BibleId, 124034015, N'Recently, however, you yourselves showed a change of heart and did what is pleasing to me. You granted your fellow countrymen their freedom and you made a covenant to that effect in my presence in the house that I have claimed for my own.'
EXEC add_BibleVerse @BibleId, 124034016, N'But then you turned right around and showed that you did not honor me. Each of you took back your male and female slaves whom you had freed as they desired, and you forced them to be your slaves again.'
EXEC add_BibleVerse @BibleId, 124034017, N'So I, the Lord, say: “You have not really obeyed me and granted freedom to your neighbor and fellow countryman. Therefore, I will grant you freedom, the freedom to die in war, or by starvation or disease. I, the Lord, affirm it! I will make all the kingdoms of the earth horrified at what happens to you.'
EXEC add_BibleVerse @BibleId, 124034018, N'I will punish those people who have violated their covenant with me. I will make them like the calf they cut in two and passed between its pieces. I will do so because they did not keep the terms of the covenant they made in my presence.'
EXEC add_BibleVerse @BibleId, 124034019, N'I will punish the leaders of Judah and Jerusalem, the court officials, the priests, and all the other people of the land who passed between the pieces of the calf.'
EXEC add_BibleVerse @BibleId, 124034020, N'I will hand them over to their enemies who want to kill them. Their dead bodies will become food for the birds and the wild animals.'
EXEC add_BibleVerse @BibleId, 124034021, N'I will also hand King Zedekiah of Judah and his officials over to their enemies who want to kill them. I will hand them over to the army of the king of Babylon, even though they have temporarily withdrawn from attacking you.'
EXEC add_BibleVerse @BibleId, 124034022, N'For I, the Lord, affirm that I will soon give the order and bring them back to this city. They will fight against it and capture it and burn it down. I will also make the towns of Judah desolate so that there will be no one living in them.”’”'
EXEC add_BibleVerse @BibleId, 124035001, N'The Lord spoke to Jeremiah when Jehoiakim son of Josiah was ruling over Judah.'
EXEC add_BibleVerse @BibleId, 124035002, N'“Go to the Rechabite community. Invite them to come into one of the side rooms of the Lord’s temple and offer them some wine to drink.”'
EXEC add_BibleVerse @BibleId, 124035003, N'So I went and got Jaazaniah son of Jeremiah the grandson of Habazziniah, his brothers, all his sons, and all the rest of the Rechabite community.'
EXEC add_BibleVerse @BibleId, 124035004, N'I took them to the Lord’s temple. I took them into the room where the disciples of the prophet Hanan son of Igdaliah stayed. That room was next to the one where the temple officers stayed and above the room where Maaseiah son of Shallum, one of the doorkeepers of the temple, stayed.'
EXEC add_BibleVerse @BibleId, 124035005, N'Then I set cups and pitchers full of wine in front of the members of the Rechabite community and said to them, “Have some wine.”'
EXEC add_BibleVerse @BibleId, 124035006, N'But they answered, “We do not drink wine because our ancestor Jonadab son of Rechab commanded us not to. He told us, ‘You and your children must never drink wine.'
EXEC add_BibleVerse @BibleId, 124035007, N'Do not build houses. Do not plant crops. Do not plant a vineyard or own one. Live in tents all your lives. If you do these things you will live a long time in the land that you wander about on.’'
EXEC add_BibleVerse @BibleId, 124035008, N'We and our wives and our sons and daughters have obeyed everything our ancestor Jonadab commanded us. We have never drunk wine.'
EXEC add_BibleVerse @BibleId, 124035009, N'We have not built any houses to live in. We do not own any vineyards, fields, or crops.'
EXEC add_BibleVerse @BibleId, 124035010, N'We have lived in tents. We have obeyed our ancestor Jonadab and done exactly as he commanded us.'
EXEC add_BibleVerse @BibleId, 124035011, N'But when King Nebuchadnezzar of Babylon invaded the land we said, ‘Let’s get up and go to Jerusalem to get away from the Babylonian and Aramean armies.’ That is why we are staying here in Jerusalem.”'
EXEC add_BibleVerse @BibleId, 124035012, N'Then the Lord spoke to Jeremiah.'
EXEC add_BibleVerse @BibleId, 124035013, N'The Lord God of Israel who rules over all told him, “Go and speak to the people of Judah and the citizens of Jerusalem. Tell them, ‘I, the Lord, say: “You must learn a lesson from this about obeying what I say!'
EXEC add_BibleVerse @BibleId, 124035014, N'Jonadab son of Rechab ordered his descendants not to drink wine. His orders have been carried out. To this day his descendants have drunk no wine because they have obeyed what their ancestor commanded them. But I have spoken to you over and over again, but you have not obeyed me!'
EXEC add_BibleVerse @BibleId, 124035015, N'I sent all my servants the prophets to warn you over and over again. They said, “Every one of you, stop doing the evil things you have been doing and do what is right. Do not pay allegiance to other gods and worship them. Then you can continue to live in this land that I gave to you and your ancestors.” But you did not pay any attention or listen to me.'
EXEC add_BibleVerse @BibleId, 124035016, N'Yes, the descendants of Jonadab son of Rechab have carried out the orders that their ancestor gave them. But you people have not obeyed me!'
EXEC add_BibleVerse @BibleId, 124035017, N'So I, the Lord, the God who rules over all, the God of Israel, say: “I will soon bring on Judah and all the citizens of Jerusalem all the disaster that I threatened to bring on them. I will do this because I spoke to them but they did not listen. I called out to them but they did not answer.”’”'
EXEC add_BibleVerse @BibleId, 124035018, N'Then Jeremiah spoke to the Rechabite community, “The Lord God of Israel who rules over all says, ‘You have obeyed the orders of your ancestor Jonadab. You have followed all his instructions. You have done exactly as he commanded you.’'
EXEC add_BibleVerse @BibleId, 124035019, N'So the Lord God of Israel who rules over all says, ‘Jonadab son of Rechab will never lack a male descendant to serve me.’”'
EXEC add_BibleVerse @BibleId, 124036001, N'The Lord spoke to Jeremiah in the fourth year that Jehoiakim son of Josiah was ruling over Judah.'
EXEC add_BibleVerse @BibleId, 124036002, N'“Get a scroll. Write on it everything I have told you to say about Israel, Judah, and all the other nations since I began to speak to you in the reign of Josiah until now.'
EXEC add_BibleVerse @BibleId, 124036003, N'Perhaps when the people of Judah hear about all the disaster I intend to bring on them, they will all stop doing the evil things they have been doing. If they do, I will forgive their sins and the wicked things they have done.”'
EXEC add_BibleVerse @BibleId, 124036004, N'So Jeremiah summoned Baruch son of Neriah. Then Jeremiah dictated to Baruch everything the Lord had told him to say and Baruch wrote it all down in a scroll.'
EXEC add_BibleVerse @BibleId, 124036005, N'Then Jeremiah told Baruch, “I am no longer allowed to go into the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 124036006, N'So you go there the next time all the people of Judah come in from their towns to fast in the Lord’s temple. Read out loud where all of them can hear you what I told you the Lord said, which you wrote in the scroll.'
EXEC add_BibleVerse @BibleId, 124036007, N'Perhaps then they will ask the Lord for mercy and will all stop doing the evil things they have been doing. For the Lord has threatened to bring great anger and wrath against these people.”'
EXEC add_BibleVerse @BibleId, 124036008, N'So Baruch son of Neriah did exactly what the prophet Jeremiah had told him to do. He read what the Lord had said from the scroll in the temple of the Lord.'
EXEC add_BibleVerse @BibleId, 124036009, N'All the people living in Jerusalem and all the people who came into Jerusalem from the towns of Judah came to observe a fast before the Lord. The fast took place in the ninth month of the fifth year that Jehoiakim son of Josiah was ruling over Judah.'
EXEC add_BibleVerse @BibleId, 124036010, N'At that time Baruch went into the temple of the Lord. He stood in the entrance of the room of Gemariah the son of Shaphan who had been the royal secretary. That room was in the upper court near the entrance of the New Gate. There, where all the people could hear him, he read from the scroll what Jeremiah had said.'
EXEC add_BibleVerse @BibleId, 124036011, N'Micaiah, who was the son of Gemariah and the grandson of Shaphan, heard Baruch read from the scroll everything the Lord had said.'
EXEC add_BibleVerse @BibleId, 124036012, N'He went down to the chamber of the royal secretary in the king’s palace and found all the court officials in session there. Elishama the royal secretary, Delaiah son of Shemaiah, Elnathan son of Achbor, Gemariah son of Shaphan, Zedekiah son of Hananiah, and all the other officials were seated there.'
EXEC add_BibleVerse @BibleId, 124036013, N'Micaiah told them everything he had heard Baruch read from the scroll in the hearing of the people.'
EXEC add_BibleVerse @BibleId, 124036014, N'All the officials sent Jehudi, who was the son of Nethaniah and the grandson of Cushi, to Baruch. They ordered him to tell Baruch, “Come here and bring with you the scroll you read in the hearing of the people.” So Baruch son of Neriah went to them, carrying the scroll in his hand.'
EXEC add_BibleVerse @BibleId, 124036015, N'They said to him, “Please sit down and read it to us.” So Baruch sat down and read it to them.'
EXEC add_BibleVerse @BibleId, 124036016, N'When they had heard it all, they expressed their alarm to one another. Then they said to Baruch, “We must certainly give the king a report about everything you have read!”'
EXEC add_BibleVerse @BibleId, 124036017, N'Then they asked Baruch, “How did you come to write all these words? Do they actually come from Jeremiah’s mouth?”'
EXEC add_BibleVerse @BibleId, 124036018, N'Baruch answered, “Yes, they came from his own mouth. He dictated all these words to me and I wrote them down in ink on this scroll.”'
EXEC add_BibleVerse @BibleId, 124036019, N'Then the officials said to Baruch, “You and Jeremiah must go and hide. You must not let anyone know where you are.”'
EXEC add_BibleVerse @BibleId, 124036020, N'The officials put the scroll in the room of Elishama, the royal secretary, for safekeeping. Then they went to the court and reported everything to the king.'
EXEC add_BibleVerse @BibleId, 124036021, N'The king sent Jehudi to get the scroll. He went and got it from the room of Elishama, the royal secretary. Then he himself read it to the king and all the officials who were standing around him.'
EXEC add_BibleVerse @BibleId, 124036022, N'Since it was the ninth month of the year, the king was sitting in his winter quarters. A fire was burning in the firepot in front of him.'
EXEC add_BibleVerse @BibleId, 124036023, N'As soon as Jehudi had read three or four columns of the scroll, the king would cut them off with a penknife and throw them on the fire in the firepot. He kept doing so until the whole scroll was burned up in the fire.'
EXEC add_BibleVerse @BibleId, 124036024, N'Neither he nor any of his attendants showed any alarm when they heard all that had been read. Nor did they tear their clothes to show any grief or sorrow.'
EXEC add_BibleVerse @BibleId, 124036025, N'The king did not even listen to Elnathan, Delaiah, and Gemariah, who had urged him not to burn the scroll.'
EXEC add_BibleVerse @BibleId, 124036026, N'He also ordered Jerahmeel, who was one of the royal princes, Seraiah son of Azriel, and Shelemiah son of Abdeel to arrest the scribe Baruch and the prophet Jeremiah. However, the Lord hid them.'
EXEC add_BibleVerse @BibleId, 124036027, N'The Lord spoke to Jeremiah after Jehoiakim had burned the scroll containing what Jeremiah had spoken and Baruch had written down.'
EXEC add_BibleVerse @BibleId, 124036028, N'“Get another scroll and write on it everything that was written on the original scroll that King Jehoiakim of Judah burned.'
EXEC add_BibleVerse @BibleId, 124036029, N'Tell King Jehoiakim of Judah, ‘The Lord says, “You burned the scroll. You asked Jeremiah, ‘How dare you write in this scroll that the king of Babylon will certainly come and destroy this land and wipe out all the people and animals on it?’”'
EXEC add_BibleVerse @BibleId, 124036030, N'So the Lord says concerning King Jehoiakim of Judah, “None of his line will occupy the throne of David. His dead body will be thrown out to be exposed to scorching heat by day and frost by night.'
EXEC add_BibleVerse @BibleId, 124036031, N'I will punish him and his descendants and the officials who serve him for the wicked things they have done. I will bring on them, the citizens of Jerusalem, and the people of Judah all the disaster that I threatened to do to them. I will punish them because I threatened them but they still paid no heed.”’”'
EXEC add_BibleVerse @BibleId, 124036032, N'Then Jeremiah got another scroll and gave it to the scribe Baruch son of Neriah. As Jeremiah dictated, Baruch wrote on this scroll everything that had been on the scroll that King Jehoiakim of Judah burned in the fire. They also added on this scroll several other messages of the same kind.'
EXEC add_BibleVerse @BibleId, 124037001, N'Zedekiah son of Josiah succeeded Jeconiah son of Jehoiakim as king. He was elevated to the throne of the land of Judah by King Nebuchadnezzar of Babylon.'
EXEC add_BibleVerse @BibleId, 124037002, N'Neither he nor the officials who served him nor the people of Judah paid any attention to what the Lord said through the prophet Jeremiah.'
EXEC add_BibleVerse @BibleId, 124037003, N'King Zedekiah sent Jehucal son of Shelemiah and the priest Zephaniah son of Maaseiah to the prophet Jeremiah. He told them to say, “Please pray to the Lord our God on our behalf.”'
EXEC add_BibleVerse @BibleId, 124037004, N'(Now Jeremiah had not yet been put in prison. So he was still free to come and go among the people as he pleased.'
EXEC add_BibleVerse @BibleId, 124037005, N'At that time the Babylonian forces had temporarily given up their siege against Jerusalem. They had had it under siege, but withdrew when they heard that the army of Pharaoh had set out from Egypt. )'
EXEC add_BibleVerse @BibleId, 124037006, N'The Lord gave the prophet Jeremiah a message for them. He told him to tell them,'
EXEC add_BibleVerse @BibleId, 124037007, N'“The Lord God of Israel says, ‘Give a message to the king of Judah who sent you to ask me to help him. Tell him, “The army of Pharaoh that was on its way to help you will go back home to Egypt.'
EXEC add_BibleVerse @BibleId, 124037008, N'Then the Babylonian forces will return. They will attack the city and will capture it and burn it down.'
EXEC add_BibleVerse @BibleId, 124037009, N'Moreover, I, the Lord, warn you not to deceive yourselves into thinking that the Babylonian forces will go away and leave you alone. For they will not go away.'
EXEC add_BibleVerse @BibleId, 124037010, N'For even if you were to defeat all the Babylonian forces fighting against you so badly that only wounded men were left lying in their tents, they would get up and burn this city down.”’”'
EXEC add_BibleVerse @BibleId, 124037011, N'The following events also occurred while the Babylonian forces had temporarily withdrawn from Jerusalem because the army of Pharaoh was coming.'
EXEC add_BibleVerse @BibleId, 124037012, N'Jeremiah started to leave Jerusalem to go to the territory of Benjamin. He wanted to make sure he got his share of the property that was being divided up among his family there.'
EXEC add_BibleVerse @BibleId, 124037013, N'But he only got as far as the Benjamin Gate. There an officer in charge of the guards named Irijah, who was the son of Shelemiah and the grandson of Hananiah, stopped him. He seized Jeremiah and said, “You are deserting to the Babylonians!”'
EXEC add_BibleVerse @BibleId, 124037014, N'Jeremiah answered, “That’s a lie! I am not deserting to the Babylonians.” But Irijah would not listen to him. Irijah put Jeremiah under arrest and took him to the officials.'
EXEC add_BibleVerse @BibleId, 124037015, N'The officials were very angry at Jeremiah. They had him flogged and put in prison in the house of Jonathan, the royal secretary, which they had converted into a place for confining prisoners.'
EXEC add_BibleVerse @BibleId, 124037016, N'So Jeremiah was put in prison in a cell in the dungeon in Jonathan’s house. He was kept there for a long time.'
EXEC add_BibleVerse @BibleId, 124037017, N'Then King Zedekiah had him brought to the palace. There he questioned him privately and asked him, “Is there any message from the Lord?” Jeremiah answered, “Yes, there is.” Then he announced, “You will be handed over to the king of Babylon.”'
EXEC add_BibleVerse @BibleId, 124037018, N'Then Jeremiah asked King Zedekiah, “What crime have I committed against you, or the officials who serve you, or the people of Judah? What have I done to make you people throw me into prison?'
EXEC add_BibleVerse @BibleId, 124037019, N'Where now are the prophets who prophesied to you that the king of Babylon would not attack you or this land?'
EXEC add_BibleVerse @BibleId, 124037020, N'But now please listen, your royal Majesty, and grant my plea for mercy. Do not send me back to the house of Jonathan, the royal secretary. If you do, I will die there.”'
EXEC add_BibleVerse @BibleId, 124037021, N'Then King Zedekiah ordered that Jeremiah be committed to the courtyard of the guardhouse. He also ordered that a loaf of bread be given to him every day from the baker’s street until all the bread in the city was gone. So Jeremiah was kept in the courtyard of the guardhouse.'
EXEC add_BibleVerse @BibleId, 124038001, N'Now Shephatiah son of Mattan, Gedaliah son of Pashhur, Jehucal son of Shelemiah, and Pashhur son of Malkijah had heard the things that Jeremiah had been telling the people. They had heard him say,'
EXEC add_BibleVerse @BibleId, 124038002, N'“The Lord says, ‘Those who stay in this city will die in battle or of starvation or disease. Those who leave the city and surrender to the Babylonians will live. They will escape with their lives.’”'
EXEC add_BibleVerse @BibleId, 124038003, N'They had also heard him say, “The Lord says, ‘This city will certainly be handed over to the army of the king of Babylon. They will capture it.’”'
EXEC add_BibleVerse @BibleId, 124038004, N'So these officials said to the king, “This man must be put to death. For he is demoralizing the soldiers who are left in the city as well as all the other people there by these things he is saying. This man is not seeking to help these people but is trying to harm them.”'
EXEC add_BibleVerse @BibleId, 124038005, N'King Zedekiah said to them, “Very well, you can do what you want with him. For I cannot do anything to stop you.”'
EXEC add_BibleVerse @BibleId, 124038006, N'So the officials took Jeremiah and put him in the cistern of Malkijah, one of the royal princes, that was in the courtyard of the guardhouse. There was no water in the cistern, only mud. So when they lowered Jeremiah into the cistern with ropes he sank in the mud.'
EXEC add_BibleVerse @BibleId, 124038007, N'An Ethiopian, Ebed Melech, a court official in the royal palace, heard that Jeremiah had been put in the cistern. While the king was holding court at the Benjamin Gate,'
EXEC add_BibleVerse @BibleId, 124038008, N'Ebed Melech departed the palace and went to speak to the king. He said to him,'
EXEC add_BibleVerse @BibleId, 124038009, N'“Your royal Majesty, those men have been very wicked in all that they have done to the prophet Jeremiah. They have thrown him into a cistern and he is sure to die of starvation there because there is no food left in the city.'
EXEC add_BibleVerse @BibleId, 124038010, N'Then the king gave Ebed Melech the Ethiopian the following order: “Take thirty men with you from here and go pull the prophet Jeremiah out of the cistern before he dies.”'
EXEC add_BibleVerse @BibleId, 124038011, N'So Ebed Melech took the men with him and went to a room under the treasure room in the palace. He got some worn-out clothes and old rags from there and let them down by ropes to Jeremiah in the cistern.'
EXEC add_BibleVerse @BibleId, 124038012, N'Ebed Melech called down to Jeremiah, “Put these rags and worn-out clothes under your armpits to pad the ropes. Jeremiah did as Ebed Melech instructed.'
EXEC add_BibleVerse @BibleId, 124038013, N'So they pulled Jeremiah up from the cistern with ropes. Jeremiah, however, still remained confined to the courtyard of the guardhouse.'
EXEC add_BibleVerse @BibleId, 124038014, N'Some time later Zedekiah sent and had Jeremiah brought to him at the third entrance of the Lord’s temple. The king said to Jeremiah, “I would like to ask you a question. Do not hide anything from me when you answer.”'
EXEC add_BibleVerse @BibleId, 124038015, N'Jeremiah said to Zedekiah, “If I answer you, you will certainly kill me. If I give you advice, you will not listen to me.”'
EXEC add_BibleVerse @BibleId, 124038016, N'So King Zedekiah made a secret promise to Jeremiah and sealed it with an oath. He promised, “As surely as the Lord lives who has given us life and breath, I promise you this: I will not kill you or hand you over to those men who want to kill you.”'
EXEC add_BibleVerse @BibleId, 124038017, N'Then Jeremiah said to Zedekiah, “The Lord, the God who rules over all, the God of Israel, says, ‘You must surrender to the officers of the king of Babylon. If you do, your life will be spared and this city will not be burned down. Indeed, you and your whole family will be spared.'
EXEC add_BibleVerse @BibleId, 124038018, N'But if you do not surrender to the officers of the king of Babylon, this city will be handed over to the Babylonians and they will burn it down. You yourself will not escape from them.’”'
EXEC add_BibleVerse @BibleId, 124038019, N'Then King Zedekiah said to Jeremiah, “I am afraid of the Judeans who have deserted to the Babylonians. The Babylonians might hand me over to them and they will torture me.”'
EXEC add_BibleVerse @BibleId, 124038020, N'Then Jeremiah answered, “You will not be handed over to them. Please obey the Lord by doing what I have been telling you. Then all will go well with you and your life will be spared.'
EXEC add_BibleVerse @BibleId, 124038021, N'But if you refuse to surrender, the Lord has shown me a vision of what will happen. Here is what I saw:'
EXEC add_BibleVerse @BibleId, 124038022, N'All the women who are left in the royal palace of Judah will be led out to the officers of the king of Babylon. They will taunt you saying, ‘Your trusted friends misled you; they have gotten the best of you. Now that your feet are stuck in the mud, they have turned their backs on you.’'
EXEC add_BibleVerse @BibleId, 124038023, N'“All your wives and your children will be turned over to the Babylonians. You yourself will not escape from them but will be captured by the king of Babylon. This city will be burned down.”'
EXEC add_BibleVerse @BibleId, 124038024, N'Then Zedekiah told Jeremiah, “Do not let anyone know about the conversation we have had. If you do, you will die.'
EXEC add_BibleVerse @BibleId, 124038025, N'The officials may hear that I have talked with you. They may come to you and say, ‘Tell us what you said to the king and what the king said to you. Do not hide anything from us. If you do, we will kill you.’'
EXEC add_BibleVerse @BibleId, 124038026, N'If they do this, tell them, ‘I was pleading with the king not to send me back to die in the dungeon of Jonathan’s house.’”'
EXEC add_BibleVerse @BibleId, 124038027, N'All the officials did indeed come and question Jeremiah. He told them exactly what the king had instructed him to say. They stopped questioning him any further because no one had actually heard their conversation.'
EXEC add_BibleVerse @BibleId, 124038028, N'So Jeremiah remained confined in the courtyard of the guardhouse until the day Jerusalem was captured. The following events occurred when Jerusalem was captured.'
EXEC add_BibleVerse @BibleId, 124039001, N'King Nebuchadnezzar of Babylon came against Jerusalem with his whole army and laid siege to it. The siege began in the tenth month of the ninth year that Zedekiah ruled over Judah.'
EXEC add_BibleVerse @BibleId, 124039002, N'It lasted until the ninth day of the fourth month of Zedekiah’s eleventh year. On that day they broke through the city walls.'
EXEC add_BibleVerse @BibleId, 124039003, N'Then Nergal-Sharezer of Samgar, Nebo-Sarsekim, who was a chief officer, Nergal-Sharezer, who was a high official, and all the other officers of the king of Babylon came and set up quarters in the Middle Gate.'
EXEC add_BibleVerse @BibleId, 124039004, N'When King Zedekiah of Judah and all his soldiers saw them, they tried to escape. They departed from the city during the night. They took a path through the king’s garden and passed out through the gate between the two walls. Then they headed for the Jordan Valley.'
EXEC add_BibleVerse @BibleId, 124039005, N'But the Babylonian army chased after them. They caught up with Zedekiah in the plains of Jericho and captured him. They took him to King Nebuchadnezzar of Babylon at Riblah in the territory of Hamath and Nebuchadnezzar passed sentence on him there.'
EXEC add_BibleVerse @BibleId, 124039006, N'There at Riblah the king of Babylon had Zedekiah’s sons put to death while Zedekiah was forced to watch. The king of Babylon also had all the nobles of Judah put to death.'
EXEC add_BibleVerse @BibleId, 124039007, N'Then he had Zedekiah’s eyes put out and had him bound in chains to be led off to Babylon.'
EXEC add_BibleVerse @BibleId, 124039008, N'The Babylonians burned down the royal palace, the temple of the Lord, and the people’s homes, and they tore down the wall of Jerusalem.'
EXEC add_BibleVerse @BibleId, 124039009, N'Then Nebuzaradan, the captain of the royal guard, took captive the rest of the people who were left in the city. He carried them off to Babylon along with the people who had deserted to him.'
EXEC add_BibleVerse @BibleId, 124039010, N'But he left behind in the land of Judah some of the poor people who owned nothing. He gave them fields and vineyards at that time.'
EXEC add_BibleVerse @BibleId, 124039011, N'Now King Nebuchadnezzar of Babylon had issued orders concerning Jeremiah. He had passed them on through Nebuzaradan, the captain of his royal guard,'
EXEC add_BibleVerse @BibleId, 124039012, N'“Find Jeremiah and look out for him. Do not do anything to harm him, but do with him whatever he tells you.”'
EXEC add_BibleVerse @BibleId, 124039013, N'So Nebuzaradan, the captain of the royal guard, Nebushazban, who was a chief officer, Nergal-Sharezer, who was a high official, and all the other officers of the king of Babylon'
EXEC add_BibleVerse @BibleId, 124039014, N'sent and had Jeremiah brought from the courtyard of the guardhouse. They turned him over to Gedaliah, the son of Ahikam and the grandson of Shaphan, to take him home with him. But Jeremiah stayed among the people.'
EXEC add_BibleVerse @BibleId, 124039015, N'Now the Lord had spoken to Jeremiah while he was still confined in the courtyard of the guardhouse,'
EXEC add_BibleVerse @BibleId, 124039016, N'“Go and tell Ebed-Melech the Ethiopian, ‘The Lord God of Israel who rules over all says, “I will carry out against this city what I promised. It will mean disaster and not good fortune for it. When that disaster happens, you will be there to see it.'
EXEC add_BibleVerse @BibleId, 124039017, N'But I will rescue you when it happens. I, the Lord, affirm it! You will not be handed over to those whom you fear.'
EXEC add_BibleVerse @BibleId, 124039018, N'I will certainly save you. You will not fall victim to violence. You will escape with your life because you trust in me. I, the Lord, affirm it!”’”'
EXEC add_BibleVerse @BibleId, 124040001, N'The Lord spoke to Jeremiah after Nebuzaradan the captain of the royal guard had set him free at Ramah. He had taken him there in chains along with all the people from Jerusalem and Judah who were being carried off to exile to Babylon.'
EXEC add_BibleVerse @BibleId, 124040002, N'The captain of the royal guard took Jeremiah aside and said to him, “The Lord your God threatened this place with this disaster.'
EXEC add_BibleVerse @BibleId, 124040003, N'Now he has brought it about. The Lord has done just as he threatened to do. This disaster has happened because you people sinned against the Lord and did not obey him.'
EXEC add_BibleVerse @BibleId, 124040004, N'But now, Jeremiah, today I will set you free from the chains on your wrists. If you would like to come to Babylon with me, come along and I will take care of you. But if you prefer not to come to Babylon with me, you are not required to do so. You are free to go anywhere in the land you want to go. Go wherever you choose.”'
EXEC add_BibleVerse @BibleId, 124040005, N'Before Jeremiah could turn to leave, the captain of the guard added, “Go back to Gedaliah, the son of Ahikam and grandson of Shaphan, whom the king of Babylon appointed to govern the towns of Judah. Go back and live with him among the people. Or go wherever else you choose.” Then the captain of the guard gave Jeremiah some food and a present and let him go.'
EXEC add_BibleVerse @BibleId, 124040006, N'So Jeremiah went to Gedaliah son of Ahikam at Mizpah and lived there with him. He stayed there to live among the people who had been left in the land of Judah.'
EXEC add_BibleVerse @BibleId, 124040007, N'Now some of the officers of the Judean army and their troops had been hiding in the countryside. They heard that the king of Babylon had appointed Gedaliah son of Ahikam to govern the country. They also heard that he had been put in charge over the men, women, and children from the poorer classes of the land who had not been carried off into exile in Babylon.'
EXEC add_BibleVerse @BibleId, 124040008, N'So all these officers and their troops came to Gedaliah at Mizpah. The officers who came were Ishmael son of Nethaniah, Johanan and Jonathan the sons of Kareah, Seraiah son of Tanhumeth, the sons of Ephai the Netophathite, and Jezaniah son of the Maacathite.'
EXEC add_BibleVerse @BibleId, 124040009, N'Gedaliah, the son of Ahikam and grandson of Shaphan, took an oath so as to give them and their troops some assurance of safety. “Do not be afraid to submit to the Babylonians. Settle down in the land and submit to the king of Babylon. Then things will go well for you.'
EXEC add_BibleVerse @BibleId, 124040010, N'I for my part will stay at Mizpah to represent you before the Babylonians whenever they come to us. You for your part go ahead and harvest the wine, the dates, the figs, and the olive oil, and store them in jars. Go ahead and settle down in the towns that you have taken over.”'
EXEC add_BibleVerse @BibleId, 124040011, N'Moreover, all the Judeans who were in Moab, Ammon, Edom, and all the other countries heard what had happened. They heard that the king of Babylon had allowed some people to stay in Judah and that he had appointed Gedaliah, the son of Ahikam and grandson of Shaphan, to govern them.'
EXEC add_BibleVerse @BibleId, 124040012, N'So all these Judeans returned to the land of Judah from the places where they had been scattered. They came to Gedaliah at Mizpah. Thus they harvested a large amount of wine and dates and figs.'
EXEC add_BibleVerse @BibleId, 124040013, N'Johanan and all the officers of the troops that had been hiding in the open country came to Gedaliah at Mizpah.'
EXEC add_BibleVerse @BibleId, 124040014, N'They said to him, “Are you at all aware that King Baalis of Ammon has sent Ishmael son of Nethaniah to kill you?” But Gedaliah son of Ahikam would not believe them.'
EXEC add_BibleVerse @BibleId, 124040015, N'Then Johanan son of Kareah spoke privately to Gedaliah there at Mizpah, “Let me go and kill Ishmael the son of Nethaniah before anyone knows about it. Otherwise he will kill you and all the Judeans who have rallied around you will be scattered. Then what remains of Judah will disappear.”'
EXEC add_BibleVerse @BibleId, 124040016, N'But Gedaliah son of Ahikam said to Johanan son of Kareah, “Do not do that because what you are saying about Ishmael is not true.”'
EXEC add_BibleVerse @BibleId, 124041001, N'But in the seventh month Ishmael, the son of Nethaniah and grandson of Elishama who was a member of the royal family and had been one of Zedekiah’s chief officers, came with ten of his men to Gedaliah son of Ahikam at Mizpah. While they were eating a meal together with him there at Mizpah,'
EXEC add_BibleVerse @BibleId, 124041002, N'Ishmael son of Nethaniah and the ten men who were with him stood up, pulled out their swords, and killed Gedaliah, the son of Ahikam and grandson of Shaphan. Thus Ishmael killed the man that the king of Babylon had appointed to govern the country.'
EXEC add_BibleVerse @BibleId, 124041003, N'Ishmael also killed all the Judeans who were with Gedaliah at Mizpah and the Babylonian soldiers who happened to be there.'
EXEC add_BibleVerse @BibleId, 124041004, N'On the day after Gedaliah had been murdered, before anyone even knew about it,'
EXEC add_BibleVerse @BibleId, 124041005, N'eighty men arrived from Shechem, Shiloh, and Samaria.'
EXEC add_BibleVerse @BibleId, 124041006, N'Ishmael son of Nethaniah went out from Mizpah to meet them. He was pretending to cry as he walked along. When he met them, he said to them, “Come with me to meet Gedaliah son of Ahikam.”'
EXEC add_BibleVerse @BibleId, 124041007, N'But as soon as they were inside the city, Ishmael son of Nethaniah and the men who were with him slaughtered them and threw their bodies in a cistern.'
EXEC add_BibleVerse @BibleId, 124041008, N'But there were ten men among them who said to Ishmael, “Do not kill us. For we will give you the stores of wheat, barley, olive oil, and honey we have hidden in a field. So he spared their lives and did not kill them along with the rest.'
EXEC add_BibleVerse @BibleId, 124041009, N'Now the cistern where Ishmael threw all the dead bodies of those he had killed was a large one that King Asa had constructed as part of his defenses against King Baasha of Israel. Ishmael son of Nethaniah filled it with dead bodies.'
EXEC add_BibleVerse @BibleId, 124041010, N'Then Ishmael took captive all the people who were still left alive in Mizpah. This included the royal princesses and all the rest of the people in Mizpah that Nebuzaradan, the captain of the royal guard, had put under the authority of Gedaliah son of Ahikam. Ishmael son of Nethaniah took all these people captive and set out to cross over to the Ammonites.'
EXEC add_BibleVerse @BibleId, 124041011, N'Johanan son of Kareah and all the army officers who were with him heard about all the atrocities that Ishmael son of Nethaniah had committed.'
EXEC add_BibleVerse @BibleId, 124041012, N'So they took all their troops and went to fight against Ishmael son of Nethaniah. They caught up with him near the large pool at Gibeon.'
EXEC add_BibleVerse @BibleId, 124041013, N'When all the people that Ishmael had taken captive saw Johanan son of Kareah and all the army officers with him, they were glad.'
EXEC add_BibleVerse @BibleId, 124041014, N'All those people that Ishmael had taken captive from Mizpah turned and went over to Johanan son of Kareah.'
EXEC add_BibleVerse @BibleId, 124041015, N'But Ishmael son of Nethaniah managed to escape from Johanan along with eight of his men, and he went on over to Ammon.'
EXEC add_BibleVerse @BibleId, 124041016, N'Johanan son of Kareah and all the army officers who were with him led off all the people who had been left alive at Mizpah. They had rescued them from Ishmael son of Nethaniah after he killed Gedaliah son of Ahikam. They led off the men, women, children, soldiers, and court officials whom they had brought away from Gibeon.'
EXEC add_BibleVerse @BibleId, 124041017, N'They set out to go to Egypt to get away from the Babylonians, but stopped at Geruth Kimham near Bethlehem.'
EXEC add_BibleVerse @BibleId, 124041018, N'They were afraid of what the Babylonians might do because Ishmael son of Nethaniah had killed Gedaliah son of Ahikam, whom the king of Babylon had appointed to govern the country.'
EXEC add_BibleVerse @BibleId, 124042001, N'Then all the army officers, including Johanan son of Kareah and Jezaniah son of Hoshaiah and all the people of every class, went to the prophet Jeremiah.'
EXEC add_BibleVerse @BibleId, 124042002, N'They said to him, “Please grant our request and pray to the Lord your God for all those of us who are still left alive here. For, as you yourself can see, there are only a few of us left out of the many there were before.'
EXEC add_BibleVerse @BibleId, 124042003, N'Pray that the Lord your God will tell us where we should go and what we should do.”'
EXEC add_BibleVerse @BibleId, 124042004, N'The prophet Jeremiah answered them, “Agreed! I will indeed pray to the Lord your God as you have asked. I will tell you everything the Lord replies in response to you. I will not keep anything back from you.”'
EXEC add_BibleVerse @BibleId, 124042005, N'They answered Jeremiah, “May the Lord be a true and faithful witness against us if we do not do just as the Lord sends you to tell us to do.'
EXEC add_BibleVerse @BibleId, 124042006, N'We will obey what the Lord our God to whom we are sending you tells us to do. It does not matter whether we like what he tells us or not. We will obey what he tells us to do so that things will go well for us.”'
EXEC add_BibleVerse @BibleId, 124042007, N'Ten days later the Lord spoke to Jeremiah.'
EXEC add_BibleVerse @BibleId, 124042008, N'So Jeremiah summoned Johanan son of Kareah and all the army officers who were with him and all the people of every class.'
EXEC add_BibleVerse @BibleId, 124042009, N'Then Jeremiah said to them, “You sent me to the Lord God of Israel to make your request known to him. Here is what he says to you:'
EXEC add_BibleVerse @BibleId, 124042010, N'‘If you will just stay in this land, I will build you up. I will not tear you down. I will firmly plant you. I will not uproot you. For I am filled with sorrow because of the disaster that I have brought on you.'
EXEC add_BibleVerse @BibleId, 124042011, N'Do not be afraid of the king of Babylon whom you now fear. Do not be afraid of him because I will be with you to save you and to rescue you from his power. I, the Lord, affirm it!'
EXEC add_BibleVerse @BibleId, 124042012, N'I will have compassion on you so that he in turn will have mercy on you and allow you to return to your land.’'
EXEC add_BibleVerse @BibleId, 124042013, N'“You must not disobey the Lord your God by saying, ‘We will not stay in this land.’'
EXEC add_BibleVerse @BibleId, 124042014, N'You must not say, ‘No, we will not stay. Instead we will go and live in the land of Egypt where we will not face war, or hear the enemy’s trumpet calls, or starve for lack of food.’'
EXEC add_BibleVerse @BibleId, 124042015, N'If you people who remain in Judah do that, then listen to what the Lord says. The Lord God of Israel who rules over all says, ‘If you are so determined to go to Egypt that you go and settle there,'
EXEC add_BibleVerse @BibleId, 124042016, N'the wars you fear will catch up with you there in the land of Egypt. The starvation you are worried about will follow you there to Egypt. You will die there.'
EXEC add_BibleVerse @BibleId, 124042017, N'All the people who are determined to go and settle in Egypt will die from war, starvation, or disease. No one will survive or escape the disaster I will bring on them.’'
EXEC add_BibleVerse @BibleId, 124042018, N'For the Lord God of Israel who rules over all says, ‘If you go to Egypt, I will pour out my wrath on you just as I poured out my anger and wrath on the citizens of Jerusalem. You will become an object of horror and ridicule, an example of those who have been cursed and that people use in pronouncing a curse. You will never see this place again.’'
EXEC add_BibleVerse @BibleId, 124042019, N'“The Lord has told you people who remain in Judah, ‘Do not go to Egypt.’ Be very sure of this: I warn you here and now.'
EXEC add_BibleVerse @BibleId, 124042020, N'You are making a fatal mistake. For you sent me to the Lord your God and asked me, ‘Pray to the Lord our God for us. Tell us what the Lord our God says and we will do it.’'
EXEC add_BibleVerse @BibleId, 124042021, N'This day I have told you what he said. But you do not want to obey the Lord by doing what he sent me to tell you.'
EXEC add_BibleVerse @BibleId, 124042022, N'So now be very sure of this: You will die from war, starvation, or disease in the place where you want to go and live.”'
EXEC add_BibleVerse @BibleId, 124043001, N'Jeremiah finished telling all the people all these things the Lord their God had sent him to tell them.'
EXEC add_BibleVerse @BibleId, 124043002, N'Then Azariah son of Hoshaiah, Johanan son of Kareah, and other arrogant men said to Jeremiah, “You are telling a lie! The Lord our God did not send you to tell us, ‘You must not go to Egypt and settle there.’'
EXEC add_BibleVerse @BibleId, 124043003, N'But Baruch son of Neriah is stirring you up against us. He wants to hand us over to the Babylonians so that they will kill us or carry us off into exile in Babylon.”'
EXEC add_BibleVerse @BibleId, 124043004, N'So Johanan son of Kareah, all the army officers, and all the rest of the people did not obey the Lord’s command to stay in the land.'
EXEC add_BibleVerse @BibleId, 124043005, N'Instead Johanan son of Kareah and all the army officers led off all the Judean remnant who had come back to live in the land of Judah from all the nations where they had been scattered.'
EXEC add_BibleVerse @BibleId, 124043006, N'They also led off all the men, women, children, and royal princesses that Nebuzaradan, the captain of the royal guard, had left with Gedaliah, the son of Ahikam and grandson of Shaphan. This included the prophet Jeremiah and Baruch son of Neriah.'
EXEC add_BibleVerse @BibleId, 124043007, N'They went on to Egypt because they refused to obey the Lord, and came to Tahpanhes.'
EXEC add_BibleVerse @BibleId, 124043008, N'At Tahpanhes the Lord spoke to Jeremiah.'
EXEC add_BibleVerse @BibleId, 124043009, N'“Take some large stones and bury them in the mortar of the clay pavement at the entrance of Pharaoh’s residence here in Tahpanhes. Do it while the people of Judah present there are watching.'
EXEC add_BibleVerse @BibleId, 124043010, N'Then tell them, ‘The Lord God of Israel who rules over all says, “I will bring my servant King Nebuchadnezzar of Babylon. I will set his throne over these stones which I have buried. He will pitch his royal tent over them.'
EXEC add_BibleVerse @BibleId, 124043011, N'He will come and attack Egypt. Those who are destined to die of disease will die of disease. Those who are destined to be carried off into exile will be carried off into exile. Those who are destined to die in war will die in war.'
EXEC add_BibleVerse @BibleId, 124043012, N'He will set fire to the temples of the gods of Egypt. He will burn their gods or carry them off as captives. He will pick Egypt clean like a shepherd picks the lice from his clothing. He will leave there unharmed.'
EXEC add_BibleVerse @BibleId, 124043013, N'He will demolish the sacred pillars in the temple of the sun in Egypt and will burn down the temples of the gods of Egypt.”’”'
EXEC add_BibleVerse @BibleId, 124044001, N'The Lord spoke to Jeremiah concerning all the Judeans who were living in the land of Egypt, those in Migdol, Tahpanhes, Memphis, and in the region of southern Egypt.'
EXEC add_BibleVerse @BibleId, 124044002, N'“The Lord God of Israel who rules over all says, ‘You have seen all the disaster I brought on Jerusalem and all the towns of Judah. Indeed, they now lie in ruins and are deserted.'
EXEC add_BibleVerse @BibleId, 124044003, N'This happened because of the wickedness the people living there did. They made me angry by worshiping and offering sacrifice to other gods whom neither they nor you nor your ancestors previously knew.'
EXEC add_BibleVerse @BibleId, 124044004, N'I sent my servants the prophets to you people over and over again warning you not to do this disgusting thing I hate.'
EXEC add_BibleVerse @BibleId, 124044005, N'But the people of Jerusalem and Judah would not listen or pay any attention. They would not stop the wickedness they were doing nor quit sacrificing to other gods.'
EXEC add_BibleVerse @BibleId, 124044006, N'So my anger and my wrath were poured out and burned like a fire through the towns of Judah and the streets of Jerusalem. That is why they have become the desolate ruins that they are today.’'
EXEC add_BibleVerse @BibleId, 124044007, N'“So now the Lord, the God who rules over all, the God of Israel, asks, ‘Why will you do such great harm to yourselves? Why should every man, woman, child, and baby of yours be destroyed from the midst of Judah? Why should you leave yourselves without a remnant?'
EXEC add_BibleVerse @BibleId, 124044008, N'That is what will result from your making me angry by what you are doing. You are making me angry by sacrificing to other gods here in the land of Egypt where you live. You will be destroyed for doing that! You will become an example used in curses and an object of ridicule among all the nations of the earth.'
EXEC add_BibleVerse @BibleId, 124044009, N'Have you forgotten all the wicked things that have been done in the towns of Judah and in the streets of Jerusalem by your ancestors, by the kings of Judah and their wives, by you and your wives?'
EXEC add_BibleVerse @BibleId, 124044010, N'To this day your people have shown no contrition! They have not revered me nor followed the laws and statutes I commanded you and your ancestors.’'
EXEC add_BibleVerse @BibleId, 124044011, N'“Because of this, the Lord God of Israel who rules over all says, ‘I am determined to bring disaster on you, even to the point of destroying all the Judeans here.'
EXEC add_BibleVerse @BibleId, 124044012, N'I will see to it that all the Judean remnant that was determined to go and live in the land of Egypt will be destroyed. Here in the land of Egypt they will fall in battle or perish from starvation. People of every class will die in war or from starvation. They will become an object of horror and ridicule, an example of those who have been cursed and that people use in pronouncing a curse.'
EXEC add_BibleVerse @BibleId, 124044013, N'I will punish those who live in the land of Egypt with war, starvation, and disease just as I punished Jerusalem.'
EXEC add_BibleVerse @BibleId, 124044014, N'None of the Judean remnant who have come to live in the land of Egypt will escape or survive to return to the land of Judah. Though they long to return and live there, none of them shall return except a few fugitives.’”'
EXEC add_BibleVerse @BibleId, 124044015, N'Then all the men who were aware that their wives were sacrificing to other gods, as well as all their wives, answered Jeremiah. There was a great crowd of them representing all the people who lived in northern and southern Egypt. They answered,'
EXEC add_BibleVerse @BibleId, 124044016, N'“We will not listen to what you claim the Lord has spoken to us!'
EXEC add_BibleVerse @BibleId, 124044017, N'Instead we will do everything we vowed we would do. We will sacrifice and pour out drink offerings to the goddess called the Queen of Heaven just as we and our ancestors, our kings, and our leaders previously did in the towns of Judah and in the streets of Jerusalem. For then we had plenty of food, were well-off, and had no troubles.'
EXEC add_BibleVerse @BibleId, 124044018, N'But ever since we stopped sacrificing and pouring out drink offerings to the Queen of Heaven, we have been in great need. Our people have died in wars or of starvation.”'
EXEC add_BibleVerse @BibleId, 124044019, N'The women added, “We did indeed sacrifice and pour out drink offerings to the Queen of Heaven. But it was with the full knowledge and approval of our husbands that we made cakes in her image and poured out drink offerings to her.”'
EXEC add_BibleVerse @BibleId, 124044020, N'Then Jeremiah replied to all the people, both men and women, who responded to him in this way.'
EXEC add_BibleVerse @BibleId, 124044021, N'“The Lord did indeed remember and call to mind what you did! He remembered the sacrifices you and your ancestors, your kings, your leaders, and all the rest of the people of the land offered to other gods in the towns of Judah and in the streets of Jerusalem.'
EXEC add_BibleVerse @BibleId, 124044022, N'Finally the Lord could no longer endure your wicked deeds and the disgusting things you did. That is why your land has become the desolate, uninhabited ruin that it is today. That is why it has become a proverbial example used in curses.'
EXEC add_BibleVerse @BibleId, 124044023, N'You have sacrificed to other gods! You have sinned against the Lord! You have not obeyed the Lord! You have not followed his laws, his statutes, and his decrees! That is why this disaster that is evident to this day has happened to you.”'
EXEC add_BibleVerse @BibleId, 124044024, N'Then Jeremiah spoke to all the people, particularly to all the women. “Listen to what the Lord has to say all you people of Judah who are in Egypt.'
EXEC add_BibleVerse @BibleId, 124044025, N'The Lord God of Israel who rules over all says, ‘You women have confirmed by your actions what you vowed with your lips! You said, “We will certainly carry out our vows to sacrifice and pour out drink offerings to the Queen of Heaven.” Well, then fulfill your vows! Carry them out!’'
EXEC add_BibleVerse @BibleId, 124044026, N'But listen to what the Lord has to say, all you people of Judah who are living in the land of Egypt. The Lord says, ‘I hereby swear by my own great name that none of the people of Judah who are living anywhere in Egypt will ever again invoke my name in their oaths! Never again will any of them use it in an oath saying, “As surely as the Lord God lives….”'
EXEC add_BibleVerse @BibleId, 124044027, N'I will indeed see to it that disaster, not prosperity, happens to them. All the people of Judah who are in the land of Egypt will die in war or from starvation until not one of them is left.'
EXEC add_BibleVerse @BibleId, 124044028, N'Some who survive in battle will return to the land of Judah from the land of Egypt. But they will be very few indeed! Then the Judean remnant who have come to live in the land of Egypt will know whose word proves true, mine or theirs.’'
EXEC add_BibleVerse @BibleId, 124044029, N'Moreover the Lord says, ‘I will make something happen to prove that I will punish you in this place. I will do it so that you will know that my threats to bring disaster on you will prove true.'
EXEC add_BibleVerse @BibleId, 124044030, N'I, the Lord, promise that I will hand Pharaoh Hophra king of Egypt over to his enemies who are seeking to kill him. I will do that just as surely as I handed King Zedekiah of Judah over to King Nebuchadnezzar of Babylon, his enemy who was seeking to kill him.’”'
EXEC add_BibleVerse @BibleId, 124045001, N'The prophet Jeremiah spoke to Baruch son of Neriah while he was writing down in a scroll the words that Jeremiah spoke to him. This happened in the fourth year that Jehoiakim son of Josiah was ruling over Judah.'
EXEC add_BibleVerse @BibleId, 124045002, N'“The Lord God of Israel has a message for you, Baruch.'
EXEC add_BibleVerse @BibleId, 124045003, N'‘You have said, “I feel so hopeless! For the Lord has added sorrow to my suffering. I am worn out from groaning. I can’t find any rest.”’”'
EXEC add_BibleVerse @BibleId, 124045004, N'The Lord told Jeremiah, “Tell Baruch, ‘The Lord says, “I am about to tear down what I have built and to uproot what I have planted. I will do this throughout the whole earth.'
EXEC add_BibleVerse @BibleId, 124045005, N'Are you looking for great things for yourself? Do not look for such things. For I, the Lord, affirm that I am about to bring disaster on all humanity. But I will allow you to escape with your life wherever you go.”’”'
EXEC add_BibleVerse @BibleId, 124046001, N'The Lord spoke to Jeremiah about the nations.'
EXEC add_BibleVerse @BibleId, 124046002, N'He spoke about Egypt and the army of Pharaoh Necho king of Egypt which was encamped along the Euphrates River at Carchemish. Now this was the army that King Nebuchadnezzar of Babylon defeated in the fourth year that Jehoiakim son of Josiah was ruling over Judah.'
EXEC add_BibleVerse @BibleId, 124046003, N'“Fall into ranks with your shields ready! Prepare to march into battle!'
EXEC add_BibleVerse @BibleId, 124046004, N'Harness the horses to the chariots! Mount your horses! Put on your helmets and take your positions! Sharpen you spears! Put on your armor!'
EXEC add_BibleVerse @BibleId, 124046005, N'What do I see?” says the Lord. “The soldiers are terrified. They are retreating. They have been defeated. They are overcome with terror; they desert quickly without looking back.'
EXEC add_BibleVerse @BibleId, 124046006, N'But even the swiftest cannot get away. Even the strongest cannot escape. There in the north by the Euphrates River they stumble and fall in defeat.'
EXEC add_BibleVerse @BibleId, 124046007, N'“Who is this that rises like the Nile, like its streams turbulent at flood stage?'
EXEC add_BibleVerse @BibleId, 124046008, N'Egypt rises like the Nile, like its streams turbulent at flood stage. Egypt says, ‘I will arise and cover the earth. I will destroy cities and the people who inhabit them.’'
EXEC add_BibleVerse @BibleId, 124046009, N'Go ahead and charge into battle, you horsemen! Drive furiously, you charioteers! Let the soldiers march out into battle, those from Ethiopia and Libya who carry shields, and those from Lydia who are armed with the bow.'
EXEC add_BibleVerse @BibleId, 124046010, N'But that day belongs to the Lord God who rules over all. It is the day when he will pay back his enemies. His sword will devour them until its appetite is satisfied! It will drink their blood until it is full! For the Lord God who rules over all will offer them up as a sacrifice in the land of the north by the Euphrates River.'
EXEC add_BibleVerse @BibleId, 124046011, N'Go up to Gilead and get medicinal ointment, you dear poor people of Egypt. But it will prove useless no matter how much medicine you use; there will be no healing for you.'
EXEC add_BibleVerse @BibleId, 124046012, N'The nations will hear of your devastating defeat. your cries of distress will echo throughout the earth. In the panic of their flight one soldier will trip over another and both of them will fall down defeated.”'
EXEC add_BibleVerse @BibleId, 124046013, N'The Lord spoke to the prophet Jeremiah about Nebuchadnezzar coming to attack the land of Egypt.'
EXEC add_BibleVerse @BibleId, 124046014, N'“Make an announcement throughout Egypt. Proclaim it in Migdol, Memphis, and Tahpanhes. ‘Take your positions and prepare to do battle. For the enemy army is destroying all the nations around you.’'
EXEC add_BibleVerse @BibleId, 124046015, N'Why will your soldiers be defeated? They will not stand because I, the Lord, will thrust them down.'
EXEC add_BibleVerse @BibleId, 124046016, N'I will make many stumble. They will fall over one another in their hurry to flee. They will say, ‘Get up! Let’s go back to our own people. Let’s go back to our homelands because the enemy is coming to destroy us.’'
EXEC add_BibleVerse @BibleId, 124046017, N'There at home they will say, ‘Pharaoh king of Egypt is just a big noise! He has let the most opportune moment pass by.’'
EXEC add_BibleVerse @BibleId, 124046018, N'I the King, whose name is the Lord who rules over all, swear this: I swear as surely as I live that a conqueror is coming. He will be as imposing as Mount Tabor is among the mountains, as Mount Carmel is against the backdrop of the sea.'
EXEC add_BibleVerse @BibleId, 124046019, N'Pack your bags for exile, you inhabitants of poor dear Egypt. For Memphis will be laid waste. It will lie in ruins and be uninhabited.'
EXEC add_BibleVerse @BibleId, 124046020, N'Egypt is like a beautiful young cow. But northern armies will attack her like swarms of stinging flies.'
EXEC add_BibleVerse @BibleId, 124046021, N'Even her mercenaries will prove to be like pampered, well-fed calves. For they too will turn and run away. They will not stand their ground when the time for them to be destroyed comes, the time for them to be punished.'
EXEC add_BibleVerse @BibleId, 124046022, N'Egypt will run away, hissing like a snake, as the enemy comes marching up in force. They will come against her with axes as if they were woodsmen chopping down trees.'
EXEC add_BibleVerse @BibleId, 124046023, N'The population of Egypt is like a vast, impenetrable forest. But I, the Lord, affirm that the enemy will cut them down. For those who chop them down will be more numerous than locusts. They will be too numerous to count.'
EXEC add_BibleVerse @BibleId, 124046024, N'Poor dear Egypt will be put to shame. She will be handed over to the people from the north.”'
EXEC add_BibleVerse @BibleId, 124046025, N'The Lord God of Israel who rules over all says, “I will punish Amon, the god of Thebes. I will punish Egypt, its gods, and its kings. I will punish Pharaoh and all who trust in him.'
EXEC add_BibleVerse @BibleId, 124046026, N'I will hand them over to Nebuchadnezzar and his troops, who want to kill them. But later on, people will live in Egypt again as they did in former times. I, the Lord, affirm it!”'
EXEC add_BibleVerse @BibleId, 124046027, N'“You descendants of Jacob, my servants, do not be afraid; do not be terrified, people of Israel. For I will rescue you and your descendants from the faraway lands where you are captives. The descendants of Jacob will return to their land and enjoy peace. They will be secure and no one will terrify them.'
EXEC add_BibleVerse @BibleId, 124046028, N'I, the Lord, tell you not to be afraid, you descendants of Jacob, my servant, for I am with you. Though I completely destroy all the nations where I scatter you, I will not completely destroy you. I will indeed discipline you but only in due measure. I will not allow you to go entirely unpunished.”'
EXEC add_BibleVerse @BibleId, 124047001, N'The Lord spoke to the prophet Jeremiah about the Philistines before Pharaoh attacked Gaza.'
EXEC add_BibleVerse @BibleId, 124047002, N'“Look! Enemies are gathering in the north like water rising in a river. They will be like an overflowing stream. They will overwhelm the whole country and everything in it like a flood. They will overwhelm the cities and their inhabitants. People will cry out in alarm. Everyone living in the country will cry out in pain.'
EXEC add_BibleVerse @BibleId, 124047003, N'Fathers will hear the hoofbeats of the enemies’ horses, the clatter of their chariots and the rumbling of their wheels. They will not turn back to save their children because they will be paralyzed with fear.'
EXEC add_BibleVerse @BibleId, 124047004, N'For the time has come to destroy all the Philistines. The time has come to destroy all the help that remains for Tyre For I, the Lord, will destroy the Philistines, that remnant that came from the island of Crete.'
EXEC add_BibleVerse @BibleId, 124047005, N'The people of Gaza will shave their heads in mourning. The people of Ashkelon will be struck dumb. How long will you gash yourselves to show your sorrow, you who remain of Philistia’s power?'
EXEC add_BibleVerse @BibleId, 124047006, N'How long will you cry out, ‘Oh, sword of the Lord, how long will it be before you stop killing? Go back into your sheath! Stay there and rest!’'
EXEC add_BibleVerse @BibleId, 124047007, N'But how can it rest when I, the Lord, have given it orders? I have ordered it to attack the people of Ashkelon and the seacoast.'
EXEC add_BibleVerse @BibleId, 124048001, N'The Lord God of Israel who rules over all spoke about Moab. “Sure to be judged is Nebo! Indeed, it will be destroyed! Kiriathaim will suffer disgrace. It will be captured! Its fortress will suffer disgrace. It will be torn down!'
EXEC add_BibleVerse @BibleId, 124048002, N'People will not praise Moab any more. The enemy will capture Heshbon and plot how to destroy Moab, saying, ‘Come, let’s put an end to that nation!’ City of Madmen, you will also be destroyed. A destructive army will march against you.'
EXEC add_BibleVerse @BibleId, 124048003, N'Cries of anguish will arise in Horonaim, ‘Oh, the ruin and great destruction!’'
EXEC add_BibleVerse @BibleId, 124048004, N'“Moab will be crushed. Her children will cry out in distress.'
EXEC add_BibleVerse @BibleId, 124048005, N'Indeed they will climb the slopes of Luhith, weeping continually as they go. For on the road down to Horonaim they will hear the cries of distress over the destruction.'
EXEC add_BibleVerse @BibleId, 124048006, N'They will hear, ‘Run! Save yourselves! Even if you must be like a lonely shrub in the desert!’'
EXEC add_BibleVerse @BibleId, 124048007, N'“Moab, you trust in the things you do and in your riches. So you too will be conquered. Your god Chemosh will go into exile along with his priests and his officials.'
EXEC add_BibleVerse @BibleId, 124048008, N'The destroyer will come against every town. Not one town will escape. The towns in the valley will be destroyed. The cities on the high plain will be laid waste. I, the Lord, have spoken!'
EXEC add_BibleVerse @BibleId, 124048009, N'Set up a gravestone for Moab, for it will certainly be laid in ruins! Its cities will be laid waste and become uninhabited.”'
EXEC add_BibleVerse @BibleId, 124048010, N'A curse on anyone who is lax in doing the Lord’s work! A curse on anyone who keeps from carrying out his destruction!'
EXEC add_BibleVerse @BibleId, 124048011, N'“From its earliest days Moab has lived undisturbed. It has never been taken into exile. Its people are like wine allowed to settle undisturbed on its dregs, never poured out from one jar to another. They are like wine which tastes like it always did, whose aroma has remained unchanged.'
EXEC add_BibleVerse @BibleId, 124048012, N'But the time is coming when I will send men against Moab who will empty it out. They will empty the towns of their people, then will lay those towns in ruins. I, the Lord, affirm it!'
EXEC add_BibleVerse @BibleId, 124048013, N'The people of Moab will be disappointed by their god Chemosh. They will be as disappointed as the people of Israel were when they put their trust in the calf god at Bethel.'
EXEC add_BibleVerse @BibleId, 124048014, N'How can you men of Moab say, ‘We are heroes, men who are mighty in battle?’'
EXEC add_BibleVerse @BibleId, 124048015, N'Moab will be destroyed. Its towns will be invaded. Its finest young men will be slaughtered. I, the King, the Lord who rules over all, affirm it!'
EXEC add_BibleVerse @BibleId, 124048016, N'Moab’s destruction is at hand. Disaster will come on it quickly.'
EXEC add_BibleVerse @BibleId, 124048017, N'Mourn for that nation, all you nations living around it, all of you nations that know of its fame. Mourn and say, ‘Alas, its powerful influence has been broken! Its glory and power have been done away!’'
EXEC add_BibleVerse @BibleId, 124048018, N'Come down from your place of honor; sit on the dry ground, you who live in Dibon. For the one who will destroy Moab will attack you; he will destroy your fortifications.'
EXEC add_BibleVerse @BibleId, 124048019, N'You who live in Aroer, stand by the road and watch. Question the man who is fleeing and the woman who is escaping. Ask them, ‘What has happened?’'
EXEC add_BibleVerse @BibleId, 124048020, N'They will answer, ‘Moab is disgraced, for it has fallen! Wail and cry out in mourning! Announce along the Arnon River that Moab has been destroyed.’'
EXEC add_BibleVerse @BibleId, 124048021, N'“Judgment will come on the cities on the high plain: on Holon, Jahzah, and Mephaath,'
EXEC add_BibleVerse @BibleId, 124048022, N'on Dibon, Nebo, and Beth Diblathaim,'
EXEC add_BibleVerse @BibleId, 124048023, N'on Kiriathaim, Beth Gamul, and Beth Meon,'
EXEC add_BibleVerse @BibleId, 124048024, N'on Kerioth and Bozrah. It will come on all the towns of Moab, both far and near.'
EXEC add_BibleVerse @BibleId, 124048025, N'Moab’s might will be crushed. Its power will be broken. I, the Lord, affirm it!'
EXEC add_BibleVerse @BibleId, 124048026, N'“Moab has vaunted itself against me. So make him drunk with the wine of my wrath until he splashes around in his own vomit, until others treat him as a laughingstock.'
EXEC add_BibleVerse @BibleId, 124048027, N'For did not you people of Moab laugh at the people of Israel? Did you think that they were nothing but thieves, that you shook your head in contempt every time you talked about them?'
EXEC add_BibleVerse @BibleId, 124048028, N'Leave your towns, you inhabitants of Moab. Go and live in the cliffs. Be like a dove that makes its nest high on the sides of a ravine.'
EXEC add_BibleVerse @BibleId, 124048029, N'I have heard how proud the people of Moab are, I know how haughty they are. I have heard how arrogant, proud, and haughty they are, what a high opinion they have of themselves.'
EXEC add_BibleVerse @BibleId, 124048030, N'I, the Lord, affirm that I know how arrogant they are. But their pride is ill-founded. Their boastings will prove to be false.'
EXEC add_BibleVerse @BibleId, 124048031, N'So I will weep with sorrow for Moab. I will cry out in sadness for all of Moab. I will moan for the people of Kir Heres.'
EXEC add_BibleVerse @BibleId, 124048032, N'I will weep for the grapevines of Sibmah just like the town of Jazer weeps over them. Their branches once spread as far as the Dead Sea. They reached as far as the town of Jazer. The destroyer will ravage her fig, date, and grape crops.'
EXEC add_BibleVerse @BibleId, 124048033, N'Joy and gladness will disappear from the fruitful land of Moab. I will stop the flow of wine from the winepresses. No one will stomp on the grapes there and shout for joy. The shouts there will be shouts of soldiers, not the shouts of those making wine.'
EXEC add_BibleVerse @BibleId, 124048034, N'Cries of anguish raised from Heshbon and Elealeh will be sounded as far as Jahaz. They will be sounded from Zoar as far as Horonaim and Eglath Shelishiyah. For even the waters of Nimrim will be dried up.'
EXEC add_BibleVerse @BibleId, 124048035, N'I will put an end in Moab to those who make offerings at her places of worship. I will put an end to those who sacrifice to other gods. I, the Lord, affirm it!'
EXEC add_BibleVerse @BibleId, 124048036, N'So my heart moans for Moab like a flute playing a funeral song. Yes, like a flute playing a funeral song, my heart moans for the people of Kir Heres. For the wealth they have gained will perish.'
EXEC add_BibleVerse @BibleId, 124048037, N'For all of them will shave their heads in mourning. They will all cut off their beards to show their sorrow. They will all make gashes in their hands. They will all put on sackcloth.'
EXEC add_BibleVerse @BibleId, 124048038, N'On all the housetops in Moab and in all its public squares there will be nothing but mourning. For I will break Moab like an unwanted jar. I, the Lord, affirm it!'
EXEC add_BibleVerse @BibleId, 124048039, N'Oh, how shattered Moab will be! Oh, how her people will wail! Oh, how she will turn away in shame! Moab will become an object of ridicule, a terrifying sight to all the nations that surround her.”'
EXEC add_BibleVerse @BibleId, 124048040, N'For the Lord says, “Look! Like an eagle with outspread wings a nation will swoop down on Moab.'
EXEC add_BibleVerse @BibleId, 124048041, N'Her towns will be captured. Her fortresses will be taken. At that time the soldiers of Moab will be frightened like a woman in labor.'
EXEC add_BibleVerse @BibleId, 124048042, N'Moab will be destroyed and no longer be a nation, because she has vaunted herself against the Lord.'
EXEC add_BibleVerse @BibleId, 124048043, N'Terror, pits, and traps are in store for the people who live in Moab. I, the Lord, affirm it!'
EXEC add_BibleVerse @BibleId, 124048044, N'Anyone who flees at the sound of terror will fall into a pit. Anyone who climbs out of the pit will be caught in a trap. For the time is coming when I will punish the people of Moab. I, the Lord, affirm it!'
EXEC add_BibleVerse @BibleId, 124048045, N'In the shadows of the walls of Heshbon those trying to escape will stand helpless. For a fire will burst forth from Heshbon. Flames will shoot out from the former territory of Sihon. They will burn the foreheads of the people of Moab, the skulls of those war-loving people.'
EXEC add_BibleVerse @BibleId, 124048046, N'Moab, you are doomed! You people who worship Chemosh will be destroyed. Your sons will be taken away captive. Your daughters will be carried away into exile.'
EXEC add_BibleVerse @BibleId, 124048047, N'Yet in days to come I will reverse Moab’s ill fortune.” says the Lord. The judgment against Moab ends here.'
EXEC add_BibleVerse @BibleId, 124049001, N'The Lord spoke about the Ammonites. “Do you think there are not any people of the nation of Israel remaining? Do you think there are not any of them remaining to reinherit their land? Is that why you people who worship the god Milcom have taken possession of the territory of Gad and live in his cities?'
EXEC add_BibleVerse @BibleId, 124049002, N'Because you did that, I, the Lord, affirm that a time is coming when I will make Rabbah, the capital city of Ammon, hear the sound of the battle cry. It will become a mound covered with ruins. Its villages will be burned to the ground. Then Israel will take back its land from those who took their land from them. I, the Lord, affirm it!'
EXEC add_BibleVerse @BibleId, 124049003, N'Wail, you people in Heshbon, because Ai in Ammon is destroyed. Cry out in anguish, you people in the villages surrounding Rabbah. Put on sackcloth and cry out in mourning. Run about covered with gashes. For your god Milcom will go into exile along with his priests and officials.'
EXEC add_BibleVerse @BibleId, 124049004, N'Why do you brag about your great power? Your power is ebbing away, you rebellious people of Ammon, who trust in your riches and say, ‘Who would dare to attack us?’'
EXEC add_BibleVerse @BibleId, 124049005, N'I will bring terror on you from every side,” says the Lord God who rules over all. “You will be scattered in every direction. No one will gather the fugitives back together.'
EXEC add_BibleVerse @BibleId, 124049006, N'Yet in days to come I will reverse Ammon’s ill fortune.” says the Lord.'
EXEC add_BibleVerse @BibleId, 124049007, N'The Lord who rules over all spoke about Edom. “Is wisdom no longer to be found in Teman? Can Edom’s counselors not give her any good advice? Has all of their wisdom turned bad?'
EXEC add_BibleVerse @BibleId, 124049008, N'Turn and flee! Take up refuge in remote places, you people who live in Dedan. For I will bring disaster on the descendants of Esau. I have decided it is time for me to punish them.'
EXEC add_BibleVerse @BibleId, 124049009, N'If grape pickers came to pick your grapes, would they not leave a few grapes behind? If robbers came at night, would they not pillage only what they needed?'
EXEC add_BibleVerse @BibleId, 124049010, N'But I will strip everything away from Esau’s descendants. I will uncover their hiding places so they cannot hide. Their children, relatives, and neighbors will all be destroyed. Not one of them will be left!'
EXEC add_BibleVerse @BibleId, 124049011, N'Leave your orphans behind and I will keep them alive. Your widows too can depend on me.”'
EXEC add_BibleVerse @BibleId, 124049012, N'For the Lord says, “If even those who did not deserve to drink from the cup of my wrath must drink from it, do you think you will go unpunished? You will not go unpunished, but must certainly drink from the cup of my wrath.'
EXEC add_BibleVerse @BibleId, 124049013, N'For I solemnly swear,” says the Lord, “that Bozrah will become a pile of ruins. It will become an object of horror and ridicule, an example to be used in curses. All the towns around it will lie in ruins forever.”'
EXEC add_BibleVerse @BibleId, 124049014, N'I said, “I have heard a message from the Lord. A messenger has been sent among the nations to say, ‘Gather your armies and march out against her! Prepare to do battle with her!’”'
EXEC add_BibleVerse @BibleId, 124049015, N'The Lord says to Edom, “I will certainly make you small among nations. I will make you despised by all humankind.'
EXEC add_BibleVerse @BibleId, 124049016, N'The terror you inspire in others and the arrogance of your heart have deceived you. You may make your home in the clefts of the rocks; you may occupy the highest places in the hills. But even if you made your home where the eagles nest, I would bring you down from there,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124049017, N'“Edom will become an object of horror. All who pass by it will be filled with horror; they will hiss out their scorn because of all the disasters that have happened to it.'
EXEC add_BibleVerse @BibleId, 124049018, N'Edom will be destroyed like Sodom and Gomorrah and the towns that were around them. No one will live there. No human being will settle in it,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124049019, N'“A lion coming up from the thick undergrowth along the Jordan scatters the sheep in the pastureland around it. So too I will chase the Edomites off their land. Then I will appoint over it whomever I choose. For there is no one like me, and there is no one who can call me to account. There is no ruler who can stand up against me.'
EXEC add_BibleVerse @BibleId, 124049020, N'So listen to what I, the Lord, have planned against Edom, what I intend to do to the people who live in Teman. Their little ones will be dragged off. I will completely destroy their land because of what they have done.'
EXEC add_BibleVerse @BibleId, 124049021, N'The people of the earth will quake when they hear of their downfall. Their cries of anguish will be heard all the way to the Gulf of Aqaba.'
EXEC add_BibleVerse @BibleId, 124049022, N'Look! Like an eagle with outspread wings, a nation will soar up and swoop down on Bozrah. At that time the soldiers of Edom will be as fearful as a woman in labor.”'
EXEC add_BibleVerse @BibleId, 124049023, N'The Lord spoke about Damascus. “The people of Hamath and Arpad will be dismayed because they have heard bad news. Their courage will melt away because of worry. Their hearts will not be able to rest.'
EXEC add_BibleVerse @BibleId, 124049024, N'The people of Damascus will lose heart and turn to flee. Panic will grip them. Pain and anguish will seize them like a woman in labor.'
EXEC add_BibleVerse @BibleId, 124049025, N'How deserted will that once-famous city be, that city that was once filled with joy!'
EXEC add_BibleVerse @BibleId, 124049026, N'For her young men will fall in her city squares. All her soldiers will be destroyed at that time,” says the Lord who rules over all.'
EXEC add_BibleVerse @BibleId, 124049027, N'“I will set fire to the walls of Damascus; it will burn up the palaces of Ben Hadad.”'
EXEC add_BibleVerse @BibleId, 124049028, N'The Lord spoke about Kedar and the kingdoms of Hazor that King Nebuchadnezzar of Babylon conquered. “Army of Babylon, go and attack Kedar. Lay waste those who live in the eastern desert.'
EXEC add_BibleVerse @BibleId, 124049029, N'Their tents and their flocks will be taken away. Their tent curtains, equipment, and camels will be carried off. People will shout to them, ‘Terror is all around you!’”'
EXEC add_BibleVerse @BibleId, 124049030, N'The Lord says, “Flee quickly, you who live in Hazor. Take up refuge in remote places. For King Nebuchadnezzar of Babylon has laid out plans to attack you. He has formed his strategy on how to defeat you.”'
EXEC add_BibleVerse @BibleId, 124049031, N'The Lord says, “Army of Babylon, go and attack a nation that lives in peace and security. They have no gates or walls to protect them. They live all alone.'
EXEC add_BibleVerse @BibleId, 124049032, N'Their camels will be taken as plunder. Their vast herds will be taken as spoil. I will scatter to the four winds those desert peoples who cut their hair short at the temples. I will bring disaster against them from every direction,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124049033, N'“Hazor will become a permanent wasteland, a place where only jackals live. No one will live there. No human being will settle in it.”'
EXEC add_BibleVerse @BibleId, 124049034, N'Early in the reign of King Zedekiah of Judah, the Lord spoke to the prophet Jeremiah about Elam.'
EXEC add_BibleVerse @BibleId, 124049035, N'The Lord who rules over all said, “I will kill all the archers of Elam, who are the chief source of her military might.'
EXEC add_BibleVerse @BibleId, 124049036, N'I will cause enemies to blow through Elam from every direction like the winds blowing in from the four quarters of heaven. I will scatter the people of Elam to the four winds. There will not be any nation where the refugees of Elam will not go.'
EXEC add_BibleVerse @BibleId, 124049037, N'I will make the people of Elam terrified of their enemies, who are seeking to kill them. I will vent my fierce anger and bring disaster upon them,” says the Lord. “I will send armies chasing after them until I have completely destroyed them.'
EXEC add_BibleVerse @BibleId, 124049038, N'I will establish my sovereignty over Elam. I will destroy their king and their leaders,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124049039, N'“Yet in days to come I will reverse Elam’s ill fortune.” says the Lord.'
EXEC add_BibleVerse @BibleId, 124050001, N'The Lord spoke concerning Babylon and the land of Babylonia through the prophet Jeremiah.'
EXEC add_BibleVerse @BibleId, 124050002, N'“Announce the news among the nations! Proclaim it! Signal for people to pay attention! Declare the news! Do not hide it! Say: ‘Babylon will be captured. Bel will be put to shame. Marduk will be dismayed. Babylon’s idols will be put to shame. Her disgusting images will be dismayed.'
EXEC add_BibleVerse @BibleId, 124050003, N'For a nation from the north will attack Babylon. It will lay her land waste. People and animals will flee out of it. No one will inhabit it.’'
EXEC add_BibleVerse @BibleId, 124050004, N'“When that time comes,” says the Lord, “the people of Israel and Judah will return to the land together. They will come back with tears of repentance as they seek the Lord their God.'
EXEC add_BibleVerse @BibleId, 124050005, N'They will ask the way to Zion; they will turn their faces toward it. They will come and bind themselves to the Lord in a lasting covenant that will never be forgotten.'
EXEC add_BibleVerse @BibleId, 124050006, N'“My people have been lost sheep. Their shepherds have allowed them to go astray. They have wandered around in the mountains. They have roamed from one mountain and hill to another. They have forgotten their resting place.'
EXEC add_BibleVerse @BibleId, 124050007, N'All who encountered them devoured them. Their enemies who did this said, ‘We are not liable for punishment! For those people have sinned against the Lord, their true pasture. They have sinned against the Lord in whom their ancestors trusted.’'
EXEC add_BibleVerse @BibleId, 124050008, N'“People of Judah, get out of Babylon quickly! Leave the land of Babylonia! Be the first to depart! Be like the male goats that lead the herd.'
EXEC add_BibleVerse @BibleId, 124050009, N'For I will rouse into action and bring against Babylon a host of mighty nations from the land of the north. They will set up their battle lines against her. They will come from the north and capture her. Their arrows will be like a skilled soldier who does not return from the battle empty-handed.'
EXEC add_BibleVerse @BibleId, 124050010, N'Babylonia will be plundered. Those who plunder it will take all they want,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124050011, N'“People of Babylonia, you plundered my people. That made you happy and glad. You frolic about like calves in a pasture. Your joyous sounds are like the neighs of a stallion.'
EXEC add_BibleVerse @BibleId, 124050012, N'But Babylonia will be put to great shame. The land where you were born will be disgraced. Indeed, Babylonia will become the least important of all nations. It will become a dry and barren desert.'
EXEC add_BibleVerse @BibleId, 124050013, N'After I vent my wrath on it Babylon will be uninhabited. It will be totally desolate. All who pass by will be filled with horror and will hiss out their scorn because of all the disasters that have happened to it.'
EXEC add_BibleVerse @BibleId, 124050014, N'“Take up your battle positions all around Babylon, all you soldiers who are armed with bows. Shoot all your arrows at her! Do not hold any back! For she has sinned against the Lord.'
EXEC add_BibleVerse @BibleId, 124050015, N'Shout the battle cry from all around the city. She will throw up her hands in surrender. Her towers will fall. Her walls will be torn down. Because I, the Lord, am wreaking revenge, take out your vengeance on her! Do to her as she has done!'
EXEC add_BibleVerse @BibleId, 124050016, N'Kill all the farmers who sow the seed in the land of Babylon. Kill all those who wield the sickle at harvest time. Let all the foreigners return to their own people. Let them hurry back to their own lands to escape destruction by that enemy army.'
EXEC add_BibleVerse @BibleId, 124050017, N'“The people of Israel are like scattered sheep which lions have chased away. First the king of Assyria devoured them. Now last of all King Nebuchadnezzar of Babylon has gnawed their bones.'
EXEC add_BibleVerse @BibleId, 124050018, N'So I, the Lord God of Israel who rules over all, say: ‘I will punish the king of Babylon and his land just as I punished the king of Assyria.'
EXEC add_BibleVerse @BibleId, 124050019, N'But I will restore the flock of Israel to their own pasture. They will graze on Mount Carmel and the land of Bashan. They will eat until they are full on the hills of Ephraim and the land of Gilead.'
EXEC add_BibleVerse @BibleId, 124050020, N'When that time comes, no guilt will be found in Israel. No sin will be found in Judah. For I will forgive those of them I have allowed to survive. I, the Lord, affirm it!’”'
EXEC add_BibleVerse @BibleId, 124050021, N'The Lord says, “Attack the land of Merathaim and the people who live in Pekod! Pursue, kill, and completely destroy them! Do just as I have commanded you!'
EXEC add_BibleVerse @BibleId, 124050022, N'The noise of battle can be heard in the land of Babylonia. There is the sound of great destruction.'
EXEC add_BibleVerse @BibleId, 124050023, N'Babylon hammered the whole world to pieces. But see how that ‘hammer’ has been broken and shattered! See what an object of horror Babylon has become among the nations!'
EXEC add_BibleVerse @BibleId, 124050024, N'I set a trap for you, Babylon; you were caught before you knew it. You fought against me. So you were found and captured.'
EXEC add_BibleVerse @BibleId, 124050025, N'I have opened up the place where my weapons are stored. I have brought out the weapons for carrying out my wrath. For I, the Lord God who rules over all, have work to carry out in the land of Babylonia.'
EXEC add_BibleVerse @BibleId, 124050026, N'Come from far away and attack Babylonia! Open up the places where she stores her grain! Pile her up in ruins! Destroy her completely! Do not leave anyone alive!'
EXEC add_BibleVerse @BibleId, 124050027, N'Kill all her soldiers! Let them be slaughtered! They are doomed, for their day of reckoning has come, the time for them to be punished.”'
EXEC add_BibleVerse @BibleId, 124050028, N'Listen! Fugitives and refugees are coming from the land of Babylon. They are coming to Zion to declare there how the Lord our God is getting revenge, getting revenge for what they have done to his temple.'
EXEC add_BibleVerse @BibleId, 124050029, N'“Call for archers to come against Babylon! Summon against her all who draw the bow! Set up camp all around the city! Do not allow anyone to escape! Pay her back for what she has done. Do to her what she has done to others. For she has proudly defied me, the Holy One of Israel.'
EXEC add_BibleVerse @BibleId, 124050030, N'So her young men will fall in her city squares. All her soldiers will be destroyed at that time,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124050031, N'“Listen! I am opposed to you, you proud city,” says the Lord God who rules over all. “Indeed, your day of reckoning has come, the time when I will punish you.'
EXEC add_BibleVerse @BibleId, 124050032, N'You will stumble and fall, you proud city; no one will help you get up. I will set fire to your towns; it will burn up everything that surrounds you.”'
EXEC add_BibleVerse @BibleId, 124050033, N'The Lord who rules over all says, “The people of Israel are oppressed. So too are the people of Judah. All those who took them captive are holding them prisoners. They refuse to set them free.'
EXEC add_BibleVerse @BibleId, 124050034, N'But the one who will rescue them is strong. He is known as the Lord who rules over all. He will strongly champion their cause. As a result he will bring peace and rest to the earth, but trouble and turmoil to the people who inhabit Babylonia.'
EXEC add_BibleVerse @BibleId, 124050035, N'“Destructive forces will come against the Babylonians,” says the Lord. “They will come against the people who inhabit Babylonia, against her leaders and her men of wisdom.'
EXEC add_BibleVerse @BibleId, 124050036, N'Destructive forces will come against her false prophets; they will be shown to be fools! Destructive forces will come against her soldiers; they will be filled with terror!'
EXEC add_BibleVerse @BibleId, 124050037, N'Destructive forces will come against her horses and her chariots. Destructive forces will come against all the foreign troops within her; they will be as frightened as women! Destructive forces will come against her treasures; they will be taken away as plunder!'
EXEC add_BibleVerse @BibleId, 124050038, N'A drought will come upon her land; her rivers and canals will be dried up. All of this will happen because her land is filled with idols. Her people act like madmen because of those idols they fear.'
EXEC add_BibleVerse @BibleId, 124050039, N'Therefore desert creatures and jackals will live there. Ostriches will dwell in it too. But no people will ever live there again. No one will dwell there for all time to come.'
EXEC add_BibleVerse @BibleId, 124050040, N'I will destroy Babylonia just like I did Sodom and Gomorrah and the neighboring towns. No one will live there. No human being will settle in it,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124050041, N'“Look! An army is about to come from the north. A mighty nation and many kings are stirring into action in faraway parts of the earth.'
EXEC add_BibleVerse @BibleId, 124050042, N'Its soldiers are armed with bows and spears. They are cruel and show no mercy. They sound like the roaring sea as they ride forth on their horses. Lined up in formation like men going into battle, they are coming against you, fair Babylon!'
EXEC add_BibleVerse @BibleId, 124050043, N'The king of Babylon will become paralyzed with fear when he hears news of their coming. Anguish will grip him, agony like that of a woman giving birth to a baby.'
EXEC add_BibleVerse @BibleId, 124050044, N'“A lion coming up from the thick undergrowth along the Jordan scatters the sheep in the pastureland around it. So too I will chase the Babylonians off of their land. Then I will appoint over it whomever I choose. For there is no one like me. There is no one who can call me to account. There is no ruler that can stand up against me.'
EXEC add_BibleVerse @BibleId, 124050045, N'So listen to what I, the Lord, have planned against Babylon, what I intend to do to the people who inhabit the land of Babylonia. Their little ones will be dragged off. I will completely destroy their land because of what they have done.'
EXEC add_BibleVerse @BibleId, 124050046, N'The people of the earth will quake when they hear Babylon has been captured. Her cries of anguish will be heard by the other nations.”'
EXEC add_BibleVerse @BibleId, 124051001, N'The Lord says, “I will cause a destructive wind to blow against Babylon and the people who inhabit Babylonia.'
EXEC add_BibleVerse @BibleId, 124051002, N'I will send people to winnow Babylonia like a wind blowing away chaff. They will winnow her and strip her land bare. This will happen when they come against her from every direction, when it is time to destroy her.'
EXEC add_BibleVerse @BibleId, 124051003, N'Do not give her archers time to string their bows or to put on their coats of armor. Do not spare any of her young men. Completely destroy her whole army.'
EXEC add_BibleVerse @BibleId, 124051004, N'Let them fall slain in the land of Babylonia, mortally wounded in the streets of her cities.'
EXEC add_BibleVerse @BibleId, 124051005, N'“For Israel and Judah will not be forsaken by their God, the Lord who rules over all. For the land of Babylonia is full of guilt against the Holy One of Israel.'
EXEC add_BibleVerse @BibleId, 124051006, N'Get out of Babylonia quickly, you foreign people. Flee to save your lives. Do not let yourselves be killed because of her sins. For it is time for the Lord to wreak his revenge. He will pay Babylonia back for what she has done.'
EXEC add_BibleVerse @BibleId, 124051007, N'Babylonia had been a gold cup in the Lord’s hand. She had made the whole world drunk. The nations had drunk from the wine of her wrath. So they have all gone mad.'
EXEC add_BibleVerse @BibleId, 124051008, N'But suddenly Babylonia will fall and be destroyed. Cry out in mourning over it! Get medicine for her wounds! Perhaps she can be healed!'
EXEC add_BibleVerse @BibleId, 124051009, N'Foreigners living there will say, ‘We tried to heal her, but she could not be healed. Let’s leave Babylonia and each go back to his own country. For judgment on her will be vast in its proportions. It will be like it is piled up to heaven, stacked up into the clouds.’'
EXEC add_BibleVerse @BibleId, 124051010, N'The exiles from Judah will say, ‘The Lord has brought about a great deliverance for us! Come on, let’s go and proclaim in Zion what the Lord our God has done!’'
EXEC add_BibleVerse @BibleId, 124051011, N'“Sharpen your arrows! Fill your quivers! The Lord will arouse a spirit of hostility in the kings of Media. For he intends to destroy Babylonia. For that is how the Lord will get his revenge – how he will get his revenge for the Babylonians’ destruction of his temple.'
EXEC add_BibleVerse @BibleId, 124051012, N'Give the signal to attack Babylon’s wall! Bring more guards! Post them all around the city! Put men in ambush! For the Lord will do what he has planned. He will do what he said he would do to the people of Babylon.'
EXEC add_BibleVerse @BibleId, 124051013, N'“You who live along the rivers of Babylon, the time of your end has come. You who are rich in plundered treasure, it is time for your lives to be cut off.'
EXEC add_BibleVerse @BibleId, 124051014, N'The Lord who rules over all has solemnly sworn, ‘I will fill your land with enemy soldiers. They will swarm over it like locusts. They will raise up shouts of victory over it.’'
EXEC add_BibleVerse @BibleId, 124051015, N'He is the one who by his power made the earth. He is the one who by his wisdom fixed the world in place, by his understanding he spread out the heavens.'
EXEC add_BibleVerse @BibleId, 124051016, N'When his voice thunders, the waters in the heavens roar. He makes the clouds rise from the far-off horizons. He makes the lightning flash out in the midst of the rain. He unleashes the wind from the places where he stores it.'
EXEC add_BibleVerse @BibleId, 124051017, N'All idolaters will prove to be stupid and ignorant. Every goldsmith will be disgraced by the idol he made. For the image he forges is merely a sham. There is no breath in any of those idols.'
EXEC add_BibleVerse @BibleId, 124051018, N'They are worthless, objects to be ridiculed. When the time comes to punish them, they will be destroyed.'
EXEC add_BibleVerse @BibleId, 124051019, N'The Lord, who is the portion of the descendants of Jacob, is not like them. For he is the one who created everything, including the people of Israel whom he claims as his own. He is known as the Lord who rules over all.'
EXEC add_BibleVerse @BibleId, 124051020, N'“Babylon, you are my war club, my weapon for battle. I used you to smash nations. I used you to destroy kingdoms.'
EXEC add_BibleVerse @BibleId, 124051021, N'I used you to smash horses and their riders. I used you to smash chariots and their drivers.'
EXEC add_BibleVerse @BibleId, 124051022, N'I used you to smash men and women. I used you to smash old men and young men. I used you to smash young men and young women.'
EXEC add_BibleVerse @BibleId, 124051023, N'I used you to smash shepherds and their flocks. I used you to smash farmers and their teams of oxen. I used you to smash governors and leaders.”'
EXEC add_BibleVerse @BibleId, 124051024, N'“But I will repay Babylon and all who live in Babylonia for all the wicked things they did in Zion right before the eyes of you Judeans,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124051025, N'The Lord says, “Beware! I am opposed to you, Babylon! You are like a destructive mountain that destroys all the earth. I will unleash my power against you; I will roll you off the cliffs and make you like a burned-out mountain.'
EXEC add_BibleVerse @BibleId, 124051026, N'No one will use any of your stones as a cornerstone. No one will use any of them in the foundation of his house. For you will lie desolate forever,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124051027, N'“Raise up battle flags throughout the lands. Sound the trumpets calling the nations to do battle. Prepare the nations to do battle against Babylonia. Call for these kingdoms to attack her: Ararat, Minni, and Ashkenaz. Appoint a commander to lead the attack. Send horses against her like a swarm of locusts.'
EXEC add_BibleVerse @BibleId, 124051028, N'Prepare the nations to do battle against her. Prepare the kings of the Medes. Prepare their governors and all their leaders. Prepare all the countries they rule to do battle against her.'
EXEC add_BibleVerse @BibleId, 124051029, N'The earth will tremble and writhe in agony. For the Lord will carry out his plan. He plans to make the land of Babylonia a wasteland where no one lives.'
EXEC add_BibleVerse @BibleId, 124051030, N'The soldiers of Babylonia will stop fighting. They will remain in their fortified cities. They will lose their strength to do battle. They will be as frightened as women. The houses in her cities will be set on fire. The gates of her cities will be broken down.'
EXEC add_BibleVerse @BibleId, 124051031, N'One runner after another will come to the king of Babylon. One messenger after another will come bringing news. They will bring news to the king of Babylon that his whole city has been captured.'
EXEC add_BibleVerse @BibleId, 124051032, N'They will report that the fords have been captured, the reed marshes have been burned, the soldiers are terrified.'
EXEC add_BibleVerse @BibleId, 124051033, N'For the Lord God of Israel who rules over all says, ‘Fair Babylon will be like a threshing floor which has been trampled flat for harvest. The time for her to be cut down and harvested will come very soon.’'
EXEC add_BibleVerse @BibleId, 124051034, N'“King Nebuchadnezzar of Babylon devoured me and drove my people out. Like a monster from the deep he swallowed me. He filled his belly with my riches. He made me an empty dish. He completely cleaned me out.”'
EXEC add_BibleVerse @BibleId, 124051035, N'The person who lives in Zion says, “May Babylon pay for the violence done to me and to my relatives.” Jerusalem says, “May those living in Babylonia pay for the bloodshed of my people.”'
EXEC add_BibleVerse @BibleId, 124051036, N'Therefore the Lord says, “I will stand up for your cause. I will pay the Babylonians back for what they have done to you. I will dry up their sea. I will make their springs run dry.'
EXEC add_BibleVerse @BibleId, 124051037, N'Babylon will become a heap of ruins. Jackals will make their home there. It will become an object of horror and of hissing scorn, a place where no one lives.'
EXEC add_BibleVerse @BibleId, 124051038, N'The Babylonians are all like lions roaring for prey. They are like lion cubs growling for something to eat.'
EXEC add_BibleVerse @BibleId, 124051039, N'When their appetites are all stirred up, I will set out a banquet for them. I will make them drunk so that they will pass out, they will fall asleep forever, they will never wake up,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124051040, N'“I will lead them off to be slaughtered like lambs, rams, and male goats.”'
EXEC add_BibleVerse @BibleId, 124051041, N'“See how Babylon has been captured! See how the pride of the whole earth has been taken! See what an object of horror Babylon has become among the nations!'
EXEC add_BibleVerse @BibleId, 124051042, N'The sea has swept over Babylon. She has been covered by a multitude of its waves.'
EXEC add_BibleVerse @BibleId, 124051043, N'The towns of Babylonia have become heaps of ruins. She has become a dry and barren desert. No one lives in those towns any more. No one even passes through them.'
EXEC add_BibleVerse @BibleId, 124051044, N'I will punish the god Bel in Babylon. I will make him spit out what he has swallowed. The nations will not come streaming to him any longer. Indeed, the walls of Babylon will fall.”'
EXEC add_BibleVerse @BibleId, 124051045, N'“Get out of Babylon, my people! Flee to save your lives from the fierce anger of the Lord!'
EXEC add_BibleVerse @BibleId, 124051046, N'Do not lose your courage or become afraid because of the reports that are heard in the land. For a report will come in one year. Another report will follow it in the next. There will be violence in the land with ruler fighting against ruler.”'
EXEC add_BibleVerse @BibleId, 124051047, N'“So the time will certainly come when I will punish the idols of Babylon. Her whole land will be put to shame. All her mortally wounded will collapse in her midst.'
EXEC add_BibleVerse @BibleId, 124051048, N'Then heaven and earth and all that is in them will sing for joy over Babylon. For destroyers from the north will attack it,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124051049, N'“Babylon must fall because of the Israelites she has killed, just as the earth’s mortally wounded fell because of Babylon.'
EXEC add_BibleVerse @BibleId, 124051050, N'You who have escaped the sword, go, do not delay. Remember the Lord in a faraway land. Think about Jerusalem.'
EXEC add_BibleVerse @BibleId, 124051051, N'‘We are ashamed because we have been insulted. Our faces show our disgrace. For foreigners have invaded the holy rooms in the Lord’s temple.’'
EXEC add_BibleVerse @BibleId, 124051052, N'Yes, but the time will certainly come,” says the Lord, “when I will punish her idols. Throughout her land the mortally wounded will groan.'
EXEC add_BibleVerse @BibleId, 124051053, N'Even if Babylon climbs high into the sky and fortifies her elevated stronghold, I will send destroyers against her,” says the Lord.'
EXEC add_BibleVerse @BibleId, 124051054, N'Cries of anguish will come from Babylon, the sound of great destruction from the land of the Babylonians.'
EXEC add_BibleVerse @BibleId, 124051055, N'For the Lord is ready to destroy Babylon, and put an end to her loud noise. Their waves will roar like turbulent waters. They will make a deafening noise.'
EXEC add_BibleVerse @BibleId, 124051056, N'For a destroyer is attacking Babylon. Her warriors will be captured; their bows will be broken. For the Lord is a God who punishes; he pays back in full.'
EXEC add_BibleVerse @BibleId, 124051057, N'“I will make her officials and wise men drunk, along with her governors, leaders, and warriors. They will fall asleep forever and never wake up,” says the King whose name is the Lord who rules over all.'
EXEC add_BibleVerse @BibleId, 124051058, N'This is what the Lord who rules over all says, “Babylon’s thick wall will be completely demolished. Her high gates will be set on fire. The peoples strive for what does not satisfy. The nations grow weary trying to get what will be destroyed.”'
EXEC add_BibleVerse @BibleId, 124051059, N'This is the order Jeremiah the prophet gave to Seraiah son of Neriah, son of Mahseiah, when he went to King Zedekiah of Judah in Babylon during the fourth year of his reign. (Seraiah was a quartermaster.)'
EXEC add_BibleVerse @BibleId, 124051060, N'Jeremiah recorded on one scroll all the judgments that would come upon Babylon – all these prophecies written about Babylon.'
EXEC add_BibleVerse @BibleId, 124051061, N'Then Jeremiah said to Seraiah, “When you arrive in Babylon, make sure you read aloud all these prophecies.'
EXEC add_BibleVerse @BibleId, 124051062, N'Then say, ‘O Lord, you have announced that you will destroy this place so that no people or animals live in it any longer. Certainly it will lie desolate forever!’'
EXEC add_BibleVerse @BibleId, 124051063, N'When you finish reading this scroll aloud, tie a stone to it and throw it into the middle of the Euphrates River.'
EXEC add_BibleVerse @BibleId, 124051064, N'Then say, ‘In the same way Babylon will sink and never rise again because of the judgments I am ready to bring upon her; they will grow faint.’” The prophecies of Jeremiah end here.'
EXEC add_BibleVerse @BibleId, 124052001, N'Zedekiah was twenty-one years old when he became king, and he ruled in Jerusalem for eleven years. His mother’s name was Hamutal daughter of Jeremiah, from Libnah.'
EXEC add_BibleVerse @BibleId, 124052002, N'He did what displeased the Lord just as Jehoiakim had done.'
EXEC add_BibleVerse @BibleId, 124052003, N'What follows is a record of what happened to Jerusalem and Judah because of the Lord’s anger when he drove them out of his sight. Zedekiah rebelled against the king of Babylon.'
EXEC add_BibleVerse @BibleId, 124052004, N'King Nebuchadnezzar of Babylon came against Jerusalem with his whole army and set up camp outside it. They built siege ramps all around it. He arrived on the tenth day of the tenth month in the ninth year that Zedekiah ruled over Judah.'
EXEC add_BibleVerse @BibleId, 124052005, N'The city remained under siege until Zedekiah’s eleventh year.'
EXEC add_BibleVerse @BibleId, 124052006, N'By the ninth day of the fourth month the famine in the city was so severe the residents had no food.'
EXEC add_BibleVerse @BibleId, 124052007, N'They broke through the city walls, and all the soldiers tried to escape. They left the city during the night. They went through the gate between the two walls that is near the king’s garden. (The Babylonians had the city surrounded.) Then they headed for the Jordan Valley.'
EXEC add_BibleVerse @BibleId, 124052008, N'But the Babylonian army chased after the king. They caught up with Zedekiah in the plains of Jericho, and his entire army deserted him.'
EXEC add_BibleVerse @BibleId, 124052009, N'They captured him and brought him up to the king of Babylon at Riblah in the territory of Hamath and he passed sentence on him there.'
EXEC add_BibleVerse @BibleId, 124052010, N'The king of Babylon had Zedekiah’s sons put to death while Zedekiah was forced to watch. He also had all the nobles of Judah put to death there at Riblah.'
EXEC add_BibleVerse @BibleId, 124052011, N'He had Zedekiah’s eyes put out and had him bound in chains. Then the king of Babylon had him led off to Babylon and he was imprisoned there until the day he died.'
EXEC add_BibleVerse @BibleId, 124052012, N'On the tenth day of the fifth month, in the nineteenth year of King Nebuchadnezzar of Babylon, Nebuzaradan, the captain of the royal guard who served the king of Babylon, arrived in Jerusalem.'
EXEC add_BibleVerse @BibleId, 124052013, N'He burned down the Lord’s temple, the royal palace, and all the houses in Jerusalem, including every large house.'
EXEC add_BibleVerse @BibleId, 124052014, N'The whole Babylonian army that came with the captain of the royal guard tore down the walls that surrounded Jerusalem.'
EXEC add_BibleVerse @BibleId, 124052015, N'Nebuzaradan, the captain of the royal guard, took into exile some of the poor, the rest of the people who remained in the city, those who had deserted to him, and the rest of the craftsmen.'
EXEC add_BibleVerse @BibleId, 124052016, N'But he left behind some of the poor and gave them fields and vineyards.'
EXEC add_BibleVerse @BibleId, 124052017, N'The Babylonians broke the two bronze pillars in the temple of the Lord, as well as the movable stands and the large bronze basin called the “The Sea.” They took all the bronze to Babylon.'
EXEC add_BibleVerse @BibleId, 124052018, N'They also took the pots, shovels, trimming shears, basins, pans, and all the bronze utensils used by the priests.'
EXEC add_BibleVerse @BibleId, 124052019, N'The captain of the royal guard took the gold and silver bowls, censers, basins, pots, lampstands, pans, and vessels.'
EXEC add_BibleVerse @BibleId, 124052020, N'The bronze of the items that King Solomon made for the Lord’s temple (including the two pillars, the large bronze basin called “The Sea,” the twelve bronze bulls under “The Sea,” and the movable stands ) was too heavy to be weighed.'
EXEC add_BibleVerse @BibleId, 124052021, N'Each of the pillars was about 27 feet high, about 18 feet in circumference, three inches thick, and hollow.'
EXEC add_BibleVerse @BibleId, 124052022, N'The bronze top of one pillar was about seven and one-half feet high and had bronze latticework and pomegranate-shaped ornaments all around it. The second pillar with its pomegranate-shaped ornaments was like it.'
EXEC add_BibleVerse @BibleId, 124052023, N'There were ninety-six pomegranate-shaped ornaments on the sides; in all there were one hundred pomegranate-shaped ornaments over the latticework that went around it.'
EXEC add_BibleVerse @BibleId, 124052024, N'The captain of the royal guard took Seraiah the chief priest, Zephaniah the priest who was second in rank, and the three doorkeepers.'
EXEC add_BibleVerse @BibleId, 124052025, N'From the city he took an official who was in charge of the soldiers, seven of the king’s advisers who were discovered in the city, an official army secretary who drafted citizens for military service, and sixty citizens who were discovered in the middle of the city.'
EXEC add_BibleVerse @BibleId, 124052026, N'Nebuzaradan, the captain of the royal guard, took them and brought them to the king of Babylon at Riblah.'
EXEC add_BibleVerse @BibleId, 124052027, N'The king of Babylon ordered them to be executed at Riblah in the territory of Hamath. So Judah was taken into exile away from its land.'
EXEC add_BibleVerse @BibleId, 124052028, N'Here is the official record of the number of people Nebuchadnezzar carried into exile: In the seventh year, 3,023 Jews;'
EXEC add_BibleVerse @BibleId, 124052029, N'in Nebuchadnezzar’s eighteenth year, 832 people from Jerusalem;'
EXEC add_BibleVerse @BibleId, 124052030, N'in Nebuchadnezzar’s twenty-third year, Nebuzaradan, the captain of the royal guard, carried into exile 745 Judeans. In all 4,600 people went into exile.'
EXEC add_BibleVerse @BibleId, 124052031, N'In the thirty-seventh year of the exile of King Jehoiachin of Judah, on the twenty-fifth day of the twelfth month, Evil-Merodach, in the first year of his reign, pardoned King Jehoiachin of Judah and released him from prison.'
EXEC add_BibleVerse @BibleId, 124052032, N'He spoke kindly to him and gave him a more prestigious position than the other kings who were with him in Babylon.'
EXEC add_BibleVerse @BibleId, 124052033, N'Jehoiachin took off his prison clothes and ate daily in the king’s presence for the rest of his life.'
EXEC add_BibleVerse @BibleId, 124052034, N'He was given daily provisions by the king of Babylon for the rest of his life until the day he died.'
EXEC add_BibleVerse @BibleId, 125001001, N'Alas! The city once full of people now sits all alone! The prominent lady among the nations has become a widow! The princess who once ruled the provinces has become a forced laborer!'
EXEC add_BibleVerse @BibleId, 125001002, N'She weeps bitterly at night; tears stream down her cheeks. She has no one to comfort her among all her lovers. All her friends have betrayed her; they have become her enemies.'
EXEC add_BibleVerse @BibleId, 125001003, N'Judah has departed into exile under affliction and harsh oppression. She lives among the nations; she has found no resting place. All who pursued her overtook her in narrow straits.'
EXEC add_BibleVerse @BibleId, 125001004, N'The roads to Zion mourn because no one travels to the festivals. All her city gates are deserted; her priests groan. Her virgins grieve; she is in bitter anguish!'
EXEC add_BibleVerse @BibleId, 125001005, N'Her foes subjugated her; her enemies are at ease. For the Lord afflicted her because of her many acts of rebellion. Her children went away captive before the enemy.'
EXEC add_BibleVerse @BibleId, 125001006, N'All of Daughter Zion’s splendor has departed. Her leaders became like deer; they found no pasture, so they were too exhausted to escape from the hunter.'
EXEC add_BibleVerse @BibleId, 125001007, N'Jerusalem remembers, when she became a poor homeless person, all her treasures that she owned in days of old. When her people fell into an enemy’s grip, none of her allies came to her rescue. Her enemies gloated over her; they sneered at her downfall.'
EXEC add_BibleVerse @BibleId, 125001008, N'Jerusalem committed terrible sin; therefore she became an object of scorn. All who admired her have despised her because they have seen her nakedness. She groans aloud and turns away in shame.'
EXEC add_BibleVerse @BibleId, 125001009, N'Her menstrual flow has soiled her clothing; she did not consider the consequences of her sin. Her demise was astonishing, and there was no one to comfort her. She cried, “Look, O Lord, on my affliction because my enemy boasts!”'
EXEC add_BibleVerse @BibleId, 125001010, N'An enemy grabbed all her valuables. Indeed she watched in horror as Gentiles invaded her holy temple – those whom you had commanded: “They must not enter your assembly place.”'
EXEC add_BibleVerse @BibleId, 125001011, N'All her people groaned as they searched for a morsel of bread. They exchanged their valuables for just enough food to stay alive. “Look, O Lord! Consider that I have become worthless!”'
EXEC add_BibleVerse @BibleId, 125001012, N'Is it nothing to you, all you who pass by on the road? Look and see! Is there any pain like mine? The Lord has afflicted me, he has inflicted it on me when he burned with anger.'
EXEC add_BibleVerse @BibleId, 125001013, N'He sent down fire into my bones, and it overcame them. He spread out a trapper’s net for my feet; he made me turn back. He has made me desolate; I am faint all day long.'
EXEC add_BibleVerse @BibleId, 125001014, N'My sins are bound around my neck like a yoke; they are fastened together by his hand. He has placed his yoke on my neck; he has sapped my strength. The Lord has handed me over to those whom I cannot resist.'
EXEC add_BibleVerse @BibleId, 125001015, N'He rounded up all my mighty ones; The Lord did this in my midst. He summoned an assembly against me to shatter my young men. The Lord has stomped like grapes the virgin daughter, Judah.'
EXEC add_BibleVerse @BibleId, 125001016, N'I weep because of these things; my eyes flow with tears. For there is no one in sight who can comfort me or encourage me. My children are desolated because an enemy has prevailed.'
EXEC add_BibleVerse @BibleId, 125001017, N'Zion spread out her hands, but there is no one to comfort her. The Lord has issued a decree against Jacob; his neighbors have become his enemies. Jerusalem has become like filthy garbage in their midst.'
EXEC add_BibleVerse @BibleId, 125001018, N'The Lord is right to judge me! Yes, I rebelled against his commands. Please listen, all you nations, and look at my suffering! My young women and men have gone into exile.'
EXEC add_BibleVerse @BibleId, 125001019, N'I called for my lovers, but they had deceived me. My priests and my elders perished in the city. Truly they had searched for food to keep themselves alive.'
EXEC add_BibleVerse @BibleId, 125001020, N'Look, O Lord! I am distressed; my stomach is in knots! My heart is pounding inside me. Yes, I was terribly rebellious! Out in the street the sword bereaves a mother of her children; Inside the house death is present.'
EXEC add_BibleVerse @BibleId, 125001021, N'They have heard that I groan, yet there is no one to comfort me. All my enemies have heard of my trouble; they are glad that you have brought it about. Bring about the day of judgment that you promised so that they may end up like me!'
EXEC add_BibleVerse @BibleId, 125001022, N'Let all their wickedness come before you; afflict them just as you have afflicted me because of all my acts of rebellion. For my groans are many, and my heart is sick with sorrow.'
EXEC add_BibleVerse @BibleId, 125002001, N'Alas! The Lord has covered Daughter Zion with his anger. He has thrown down the splendor of Israel from heaven to earth; he did not protect his temple when he displayed his anger.'
EXEC add_BibleVerse @BibleId, 125002002, N'The Lord destroyed mercilessly all the homes of Jacob’s descendants. In his anger he tore down the fortified cities of Daughter Judah. He knocked to the ground and humiliated the kingdom and its rulers.'
EXEC add_BibleVerse @BibleId, 125002003, N'In fierce anger he destroyed the whole army of Israel. He withdrew his right hand as the enemy attacked. He was like a raging fire in the land of Jacob; it consumed everything around it.'
EXEC add_BibleVerse @BibleId, 125002004, N'He prepared his bow like an enemy; his right hand was ready to shoot. Like a foe he killed everyone, even our strong young men; he has poured out his anger like fire on the tent of Daughter Zion.'
EXEC add_BibleVerse @BibleId, 125002005, N'The Lord, like an enemy, destroyed Israel. He destroyed all her palaces; he ruined her fortified cities. He made everyone in Daughter Judah mourn and lament.'
EXEC add_BibleVerse @BibleId, 125002006, N'He destroyed his temple as if it were a vineyard; he destroyed his appointed meeting place. The Lord has made those in Zion forget both the festivals and the Sabbaths. In his fierce anger he has spurned both king and priest.'
EXEC add_BibleVerse @BibleId, 125002007, N'The Lord rejected his altar and abhorred his temple. He handed over to the enemy her palace walls; the enemy shouted in the Lord’s temple as if it were a feast day.'
EXEC add_BibleVerse @BibleId, 125002008, N'The Lord was determined to tear down Daughter Zion’s wall. He prepared to knock it down; he did not withdraw his hand from destroying. He made the ramparts and fortified walls lament; together they mourned their ruin.'
EXEC add_BibleVerse @BibleId, 125002009, N'Her city gates have fallen to the ground; he smashed to bits the bars that lock her gates. Her king and princes were taken into exile; there is no more guidance available. As for her prophets, they no longer receive a vision from the Lord.'
EXEC add_BibleVerse @BibleId, 125002010, N'The elders of Daughter Zion sit on the ground in silence. They have thrown dirt on their heads; They have dressed in sackcloth. Jerusalem’s young women stare down at the ground.'
EXEC add_BibleVerse @BibleId, 125002011, N'My eyes are worn out from weeping; my stomach is in knots. My heart is poured out on the ground due to the destruction of my helpless people; children and infants faint in the town squares.'
EXEC add_BibleVerse @BibleId, 125002012, N'Children say to their mothers, “Where are food and drink?” They faint like a wounded warrior in the city squares. They die slowly in their mothers’ arms.'
EXEC add_BibleVerse @BibleId, 125002013, N'With what can I equate you? To what can I compare you, O Daughter Jerusalem? To what can I liken you so that I might comfort you, O Virgin Daughter Zion? Your wound is as deep as the sea. Who can heal you?'
EXEC add_BibleVerse @BibleId, 125002014, N'Your prophets saw visions for you that were worthless lies. They failed to expose your sin so as to restore your fortunes. They saw oracles for you that were worthless lies.'
EXEC add_BibleVerse @BibleId, 125002015, N'All who passed by on the road clapped their hands to mock you. They sneered and shook their heads at Daughter Jerusalem. “Ha! Is this the city they called ‘The perfection of beauty, the source of joy of the whole earth!’?”'
EXEC add_BibleVerse @BibleId, 125002016, N'All your enemies gloated over you. They sneered and gnashed their teeth; they said, “We have destroyed her! Ha! We have waited a long time for this day. We have lived to see it!”'
EXEC add_BibleVerse @BibleId, 125002017, N'The Lord has done what he planned; he has fulfilled his promise that he threatened long ago: He has overthrown you without mercy and has enabled the enemy to gloat over you; he has exalted your adversaries’ power.'
EXEC add_BibleVerse @BibleId, 125002018, N'Cry out from your heart to the Lord, O wall of Daughter Zion! Make your tears flow like a river all day and all night long! Do not rest; do not let your tears stop!'
EXEC add_BibleVerse @BibleId, 125002019, N'Get up! Cry out in the night when the night watches start! Pour out your heart like water before the face of the Lord! Lift up your hands to him for your children’s lives; they are fainting at every street corner.'
EXEC add_BibleVerse @BibleId, 125002020, N'Look, O Lord! Consider! Whom have you ever afflicted like this? Should women eat their offspring, their healthy infants? Should priest and prophet be killed in the Lord’s sanctuary?'
EXEC add_BibleVerse @BibleId, 125002021, N'The young boys and old men lie dead on the ground in the streets. My young women and my young men have fallen by the sword. You killed them when you were angry; you slaughtered them without mercy.'
EXEC add_BibleVerse @BibleId, 125002022, N'As if it were a feast day, you call enemies to terrify me on every side. On the day of the Lord’s anger no one escaped or survived. My enemy has finished off those healthy infants whom I bore and raised.'
EXEC add_BibleVerse @BibleId, 125003001, N'I am the man who has experienced affliction from the rod of his wrath.'
EXEC add_BibleVerse @BibleId, 125003002, N'He drove me into captivity and made me walk in darkness and not light.'
EXEC add_BibleVerse @BibleId, 125003003, N'He repeatedly attacks me, he turns his hand against me all day long.'
EXEC add_BibleVerse @BibleId, 125003004, N'He has made my mortal skin waste away; he has broken my bones.'
EXEC add_BibleVerse @BibleId, 125003005, N'He has besieged and surrounded me with bitter hardship.'
EXEC add_BibleVerse @BibleId, 125003006, N'He has made me reside in deepest darkness like those who died long ago.'
EXEC add_BibleVerse @BibleId, 125003007, N'He has walled me in so that I cannot get out; he has weighted me down with heavy prison chains.'
EXEC add_BibleVerse @BibleId, 125003008, N'Also, when I cry out desperately for help, he has shut out my prayer.'
EXEC add_BibleVerse @BibleId, 125003009, N'He has blocked every road I take with a wall of hewn stones; he has made every path impassable.'
EXEC add_BibleVerse @BibleId, 125003010, N'To me he is like a bear lying in ambush, like a hidden lion stalking its prey.'
EXEC add_BibleVerse @BibleId, 125003011, N'He has obstructed my paths and torn me to pieces; he has made me desolate.'
EXEC add_BibleVerse @BibleId, 125003012, N'He drew his bow and made me the target for his arrow.'
EXEC add_BibleVerse @BibleId, 125003013, N'He shot his arrows into my heart.'
EXEC add_BibleVerse @BibleId, 125003014, N'I have become the laughingstock of all people, their mocking song all day long.'
EXEC add_BibleVerse @BibleId, 125003015, N'He has given me my fill of bitter herbs and made me drunk with bitterness.'
EXEC add_BibleVerse @BibleId, 125003016, N'He ground my teeth in gravel; he trampled me in the dust.'
EXEC add_BibleVerse @BibleId, 125003017, N'I am deprived of peace; I have forgotten what happiness is.'
EXEC add_BibleVerse @BibleId, 125003018, N'So I said, “My endurance has expired; I have lost all hope of deliverance from the Lord.”'
EXEC add_BibleVerse @BibleId, 125003019, N'Remember my impoverished and homeless condition, which is a bitter poison.'
EXEC add_BibleVerse @BibleId, 125003020, N'I continually think about this, and I am depressed.'
EXEC add_BibleVerse @BibleId, 125003021, N'But this I call to mind; therefore I have hope:'
EXEC add_BibleVerse @BibleId, 125003022, N'The Lord’s loyal kindness never ceases; his compassions never end.'
EXEC add_BibleVerse @BibleId, 125003023, N'They are fresh every morning; your faithfulness is abundant!'
EXEC add_BibleVerse @BibleId, 125003024, N'“My portion is the Lord,” I have said to myself, so I will put my hope in him.'
EXEC add_BibleVerse @BibleId, 125003025, N'The Lord is good to those who trust in him, to the one who seeks him.'
EXEC add_BibleVerse @BibleId, 125003026, N'It is good to wait patiently for deliverance from the Lord.'
EXEC add_BibleVerse @BibleId, 125003027, N'It is good for a man to bear the yoke while he is young.'
EXEC add_BibleVerse @BibleId, 125003028, N'Let a person sit alone in silence, when the Lord is disciplining him.'
EXEC add_BibleVerse @BibleId, 125003029, N'Let him bury his face in the dust; perhaps there is hope.'
EXEC add_BibleVerse @BibleId, 125003030, N'Let him offer his cheek to the one who hits him; let him have his fill of insults.'
EXEC add_BibleVerse @BibleId, 125003031, N'For the Lord will not reject us forever.'
EXEC add_BibleVerse @BibleId, 125003032, N'Though he causes us grief, he then has compassion on us according to the abundance of his loyal kindness.'
EXEC add_BibleVerse @BibleId, 125003033, N'For he is not predisposed to afflict or to grieve people.'
EXEC add_BibleVerse @BibleId, 125003034, N'To crush underfoot all the earth’s prisoners,'
EXEC add_BibleVerse @BibleId, 125003035, N'to deprive a person of his rights in the presence of the Most High,'
EXEC add_BibleVerse @BibleId, 125003036, N'to defraud a person in a lawsuit – the Lord does not approve of such things!'
EXEC add_BibleVerse @BibleId, 125003037, N'Whose command was ever fulfilled unless the Lord decreed it?'
EXEC add_BibleVerse @BibleId, 125003038, N'Is it not from the mouth of the Most High that everything comes – both calamity and blessing?'
EXEC add_BibleVerse @BibleId, 125003039, N'Why should any living person complain when punished for his sins?'
EXEC add_BibleVerse @BibleId, 125003040, N'Let us carefully examine our ways, and let us return to the Lord.'
EXEC add_BibleVerse @BibleId, 125003041, N'Let us lift up our hearts and our hands to God in heaven:'
EXEC add_BibleVerse @BibleId, 125003042, N'“We have blatantly rebelled; you have not forgiven.”'
EXEC add_BibleVerse @BibleId, 125003043, N'You shrouded yourself with anger and then pursued us; you killed without mercy.'
EXEC add_BibleVerse @BibleId, 125003044, N'You shrouded yourself with a cloud so that no prayer can get through.'
EXEC add_BibleVerse @BibleId, 125003045, N'You make us like filthy scum in the estimation of the nations.'
EXEC add_BibleVerse @BibleId, 125003046, N'All our enemies have gloated over us;'
EXEC add_BibleVerse @BibleId, 125003047, N'Panic and pitfall have come upon us, devastation and destruction.'
EXEC add_BibleVerse @BibleId, 125003048, N'Streams of tears flow from my eyes because my people are destroyed.'
EXEC add_BibleVerse @BibleId, 125003049, N'Tears flow from my eyes and will not stop; there will be no break'
EXEC add_BibleVerse @BibleId, 125003050, N'until the Lord looks down from heaven and sees what has happened.'
EXEC add_BibleVerse @BibleId, 125003051, N'What my eyes see grieves me – all the suffering of the daughters in my city.'
EXEC add_BibleVerse @BibleId, 125003052, N'For no good reason my enemies hunted me down like a bird.'
EXEC add_BibleVerse @BibleId, 125003053, N'They shut me up in a pit and threw stones at me.'
EXEC add_BibleVerse @BibleId, 125003054, N'The waters closed over my head; I thought I was about to die.'
EXEC add_BibleVerse @BibleId, 125003055, N'I have called on your name, O Lord, from the deepest pit.'
EXEC add_BibleVerse @BibleId, 125003056, N'You heard my plea: “Do not close your ears to my cry for relief!”'
EXEC add_BibleVerse @BibleId, 125003057, N'You came near on the day I called to you; you said, “Do not fear!”'
EXEC add_BibleVerse @BibleId, 125003058, N'O Lord, you championed my cause, you redeemed my life.'
EXEC add_BibleVerse @BibleId, 125003059, N'You have seen the wrong done to me, O Lord; pronounce judgment on my behalf!'
EXEC add_BibleVerse @BibleId, 125003060, N'You have seen all their vengeance, all their plots against me.'
EXEC add_BibleVerse @BibleId, 125003061, N'You have heard their taunts, O Lord, all their plots against me.'
EXEC add_BibleVerse @BibleId, 125003062, N'My assailants revile and conspire against me all day long.'
EXEC add_BibleVerse @BibleId, 125003063, N'Watch them from morning to evening; I am the object of their mocking songs.'
EXEC add_BibleVerse @BibleId, 125003064, N'Pay them back what they deserve, O Lord, according to what they have done.'
EXEC add_BibleVerse @BibleId, 125003065, N'Give them a distraught heart; may your curse be on them!'
EXEC add_BibleVerse @BibleId, 125003066, N'Pursue them in anger and eradicate them from under the Lord’s heaven.'
EXEC add_BibleVerse @BibleId, 125004001, N'Alas! Gold has lost its luster; pure gold loses value. Jewels are scattered on every street corner.'
EXEC add_BibleVerse @BibleId, 125004002, N'The precious sons of Zion were worth their weight in gold – Alas! – but now they are treated like broken clay pots, made by a potter.'
EXEC add_BibleVerse @BibleId, 125004003, N'Even the jackals nurse their young at their breast, but my people are cruel, like ostriches in the desert.'
EXEC add_BibleVerse @BibleId, 125004004, N'The infant’s tongue sticks to the roof of its mouth due to thirst; little children beg for bread, but no one gives them even a morsel.'
EXEC add_BibleVerse @BibleId, 125004005, N'Those who once feasted on delicacies are now starving to death in the streets. Those who grew up wearing expensive clothes are now dying amid garbage.'
EXEC add_BibleVerse @BibleId, 125004006, N'The punishment of my people exceeded that of of Sodom, which was overthrown in a moment with no one to help her.'
EXEC add_BibleVerse @BibleId, 125004007, N'Her consecrated ones were brighter than snow, whiter than milk; their bodies more ruddy than corals, their hair like lapis lazuli.'
EXEC add_BibleVerse @BibleId, 125004008, N'Now their appearance is darker than soot; they are not recognized in the streets. Their skin has shriveled on their bones; it is dried up, like tree bark.'
EXEC add_BibleVerse @BibleId, 125004009, N'Those who died by the sword are better off than those who die of hunger, those who waste away, struck down from lack of food.'
EXEC add_BibleVerse @BibleId, 125004010, N'The hands of tenderhearted women cooked their own children, who became their food, when my people were destroyed.'
EXEC add_BibleVerse @BibleId, 125004011, N'The Lord fully vented his wrath; he poured out his fierce anger. He started a fire in Zion; it consumed her foundations.'
EXEC add_BibleVerse @BibleId, 125004012, N'Neither the kings of the earth nor the people of the lands ever thought that enemy or foe would enter the gates of Jerusalem.'
EXEC add_BibleVerse @BibleId, 125004013, N'But it happened due to the sins of her prophets and the iniquities of her priests, who poured out in her midst the blood of the righteous.'
EXEC add_BibleVerse @BibleId, 125004014, N'They wander blindly through the streets, defiled by the blood they shed, while no one dares to touch their garments.'
EXEC add_BibleVerse @BibleId, 125004015, N'People cry to them, “Turn away! You are unclean! Turn away! Turn away! Don’t touch us!” So they have fled and wander about; but the nations say, “They may not stay here any longer.”'
EXEC add_BibleVerse @BibleId, 125004016, N'The Lord himself has scattered them; he no longer watches over them. They did not honor the priests; they did not show favor to the elders.'
EXEC add_BibleVerse @BibleId, 125004017, N'Our eyes continually failed us as we looked in vain for help. From our watchtowers we watched for a nation that could not rescue us.'
EXEC add_BibleVerse @BibleId, 125004018, N'Our enemies hunted us down at every step so that we could not walk about in our streets. Our end drew near, our days were numbered, for our end had come!'
EXEC add_BibleVerse @BibleId, 125004019, N'Those who pursued us were swifter than eagles in the sky. They chased us over the mountains; they ambushed us in the wilderness.'
EXEC add_BibleVerse @BibleId, 125004020, N'Our very life breath – the Lord’s anointed king – was caught in their traps, of whom we thought, “Under his protection we will survive among the nations.”'
EXEC add_BibleVerse @BibleId, 125004021, N'Rejoice and be glad for now, O people of Edom, who reside in the land of Uz. But the cup of judgment will pass to you also; you will get drunk and take off your clothes.'
EXEC add_BibleVerse @BibleId, 125004022, N'O people of Zion, your punishment will come to an end; he will not prolong your exile. But, O people of Edom, he will punish your sin and reveal your offenses!'
EXEC add_BibleVerse @BibleId, 125005001, N'O Lord, reflect on what has happened to us; consider and look at our disgrace.'
EXEC add_BibleVerse @BibleId, 125005002, N'Our inheritance is turned over to strangers; foreigners now occupy our homes.'
EXEC add_BibleVerse @BibleId, 125005003, N'We have become fatherless orphans; our mothers have become widows.'
EXEC add_BibleVerse @BibleId, 125005004, N'We must pay money for our own water; we must buy our own wood at a steep price.'
EXEC add_BibleVerse @BibleId, 125005005, N'We are pursued – they are breathing down our necks; we are weary and have no rest.'
EXEC add_BibleVerse @BibleId, 125005006, N'We have submitted to Egypt and Assyria in order to buy food to eat.'
EXEC add_BibleVerse @BibleId, 125005007, N'Our forefathers sinned and are dead, but we suffer their punishment.'
EXEC add_BibleVerse @BibleId, 125005008, N'Slaves rule over us; there is no one to rescue us from their power.'
EXEC add_BibleVerse @BibleId, 125005009, N'At the risk of our lives we get our food because robbers lurk in the countryside.'
EXEC add_BibleVerse @BibleId, 125005010, N'Our skin is hot as an oven due to a fever from hunger.'
EXEC add_BibleVerse @BibleId, 125005011, N'They raped women in Zion, virgins in the towns of Judah.'
EXEC add_BibleVerse @BibleId, 125005012, N'Princes were hung by their hands; elders were mistreated.'
EXEC add_BibleVerse @BibleId, 125005013, N'The young men perform menial labor; boys stagger from their labor.'
EXEC add_BibleVerse @BibleId, 125005014, N'The elders are gone from the city gate; the young men have stopped playing their music.'
EXEC add_BibleVerse @BibleId, 125005015, N'Our hearts no longer have any joy; our dancing is turned to mourning.'
EXEC add_BibleVerse @BibleId, 125005016, N'The crown has fallen from our head; woe to us, for we have sinned!'
EXEC add_BibleVerse @BibleId, 125005017, N'Because of this, our hearts are sick; because of these things, we can hardly see through our tears.'
EXEC add_BibleVerse @BibleId, 125005018, N'For wild animals are prowling over Mount Zion, which lies desolate.'
EXEC add_BibleVerse @BibleId, 125005019, N'But you, O Lord, reign forever; your throne endures from generation to generation.'
EXEC add_BibleVerse @BibleId, 125005020, N'Why do you keep on forgetting us? Why do you forsake us so long?'
EXEC add_BibleVerse @BibleId, 125005021, N'Bring us back to yourself, O Lord, so that we may return to you; renew our life as in days before,'
EXEC add_BibleVerse @BibleId, 125005022, N'unless you have utterly rejected us and are angry with us beyond measure.'
EXEC add_BibleVerse @BibleId, 126001001, N'In the thirtieth year, on the fifth day of the fourth month, while I was among the exiles at the Kebar River, the heavens opened and I saw a divine vision.'
EXEC add_BibleVerse @BibleId, 126001002, N'(On the fifth day of the month – it was the fifth year of King Jehoiachin’s exile –'
EXEC add_BibleVerse @BibleId, 126001003, N'the word of the Lord came to the priest Ezekiel the son of Buzi, at the Kebar River in the land of the Babylonians. The hand of the Lord came on him there).'
EXEC add_BibleVerse @BibleId, 126001004, N'As I watched, I noticed a windstorm coming from the north – an enormous cloud, with lightning flashing, such that bright light rimmed it and came from it like glowing amber from the middle of a fire.'
EXEC add_BibleVerse @BibleId, 126001005, N'In the fire were what looked like four living beings. In their appearance they had human form,'
EXEC add_BibleVerse @BibleId, 126001006, N'but each had four faces and four wings.'
EXEC add_BibleVerse @BibleId, 126001007, N'Their legs were straight, but the soles of their feet were like calves’ feet. They gleamed like polished bronze.'
EXEC add_BibleVerse @BibleId, 126001008, N'They had human hands under their wings on their four sides. As for the faces and wings of the four of them,'
EXEC add_BibleVerse @BibleId, 126001009, N'their wings touched each other; they did not turn as they moved, but went straight ahead.'
EXEC add_BibleVerse @BibleId, 126001010, N'Their faces had this appearance: Each of the four had the face of a man, with the face of a lion on the right, the face of an ox on the left and also the face of an eagle.'
EXEC add_BibleVerse @BibleId, 126001011, N'Their wings were spread out above them; each had two wings touching the wings of one of the other beings on either side and two wings covering their bodies.'
EXEC add_BibleVerse @BibleId, 126001012, N'Each moved straight ahead – wherever the spirit would go, they would go, without turning as they went.'
EXEC add_BibleVerse @BibleId, 126001013, N'In the middle of the living beings was something like burning coals of fire or like torches. It moved back and forth among the living beings. It was bright, and lightning was flashing out of the fire.'
EXEC add_BibleVerse @BibleId, 126001014, N'The living beings moved backward and forward as quickly as flashes of lightning.'
EXEC add_BibleVerse @BibleId, 126001015, N'Then I looked, and I saw one wheel on the ground beside each of the four beings.'
EXEC add_BibleVerse @BibleId, 126001016, N'The appearance of the wheels and their construction was like gleaming jasper, and all four wheels looked alike. Their structure was like a wheel within a wheel.'
EXEC add_BibleVerse @BibleId, 126001017, N'When they moved they would go in any of the four directions they faced without turning as they moved.'
EXEC add_BibleVerse @BibleId, 126001018, N'Their rims were high and awesome, and the rims of all four wheels were full of eyes all around.'
EXEC add_BibleVerse @BibleId, 126001019, N'When the living beings moved, the wheels beside them moved; when the living beings rose up from the ground, the wheels rose up too.'
EXEC add_BibleVerse @BibleId, 126001020, N'Wherever the spirit would go, they would go, and the wheels would rise up beside them because the spirit of the living being was in the wheel.'
EXEC add_BibleVerse @BibleId, 126001021, N'When the living beings moved, the wheels moved, and when they stopped moving, the wheels stopped. When they rose up from the ground, the wheels rose up from the ground; the wheels rose up beside them because the spirit of the living being was in the wheel.'
EXEC add_BibleVerse @BibleId, 126001022, N'Over the heads of the living beings was something like a platform, glittering awesomely like ice, stretched out over their heads.'
EXEC add_BibleVerse @BibleId, 126001023, N'Under the platform their wings were stretched out, each toward the other. Each of the beings also had two wings covering its body.'
EXEC add_BibleVerse @BibleId, 126001024, N'When they moved, I heard the sound of their wings – it was like the sound of rushing waters, or the voice of the Almighty, or the tumult of an army. When they stood still, they lowered their wings.'
EXEC add_BibleVerse @BibleId, 126001025, N'Then there was a voice from above the platform over their heads when they stood still.'
EXEC add_BibleVerse @BibleId, 126001026, N'Above the platform over their heads was something like a sapphire shaped like a throne. High above on the throne was a form that appeared to be a man.'
EXEC add_BibleVerse @BibleId, 126001027, N'I saw an amber glow like a fire enclosed all around from his waist up. From his waist down I saw something that looked like fire. There was a brilliant light around it,'
EXEC add_BibleVerse @BibleId, 126001028, N'like the appearance of a rainbow in the clouds after the rain. This was the appearance of the surrounding brilliant light; it looked like the glory of the Lord. When I saw it, I threw myself face down, and I heard a voice speaking.'
EXEC add_BibleVerse @BibleId, 126002001, N'He said to me, “Son of man, stand on your feet and I will speak with you.”'
EXEC add_BibleVerse @BibleId, 126002002, N'As he spoke to me, a wind came into me and stood me on my feet, and I heard the one speaking to me.'
EXEC add_BibleVerse @BibleId, 126002003, N'He said to me, “Son of man, I am sending you to the house of Israel, to rebellious nations who have rebelled against me; both they and their fathers have revolted against me to this very day.'
EXEC add_BibleVerse @BibleId, 126002004, N'The people to whom I am sending you are obstinate and hard-hearted, and you must say to them, ‘This is what the sovereign Lord says.’'
EXEC add_BibleVerse @BibleId, 126002005, N'And as for them, whether they listen or not – for they are a rebellious house – they will know that a prophet has been among them.'
EXEC add_BibleVerse @BibleId, 126002006, N'But you, son of man, do not fear them, and do not fear their words – even though briers and thorns surround you and you live among scorpions – do not fear their words and do not be terrified of the looks they give you, for they are a rebellious house!'
EXEC add_BibleVerse @BibleId, 126002007, N'You must speak my words to them whether they listen or not, for they are rebellious.'
EXEC add_BibleVerse @BibleId, 126002008, N'As for you, son of man, listen to what I am saying to you: Do not rebel like that rebellious house! Open your mouth and eat what I am giving you.”'
EXEC add_BibleVerse @BibleId, 126002009, N'Then I looked and realized a hand was stretched out to me, and in it was a written scroll.'
EXEC add_BibleVerse @BibleId, 126002010, N'He unrolled it before me, and it had writing on the front and back; written on it were laments, mourning, and woe.'
EXEC add_BibleVerse @BibleId, 126003001, N'He said to me, “Son of man, eat what you see in front of you – eat this scroll – and then go and speak to the house of Israel.”'
EXEC add_BibleVerse @BibleId, 126003002, N'So I opened my mouth and he fed me the scroll.'
EXEC add_BibleVerse @BibleId, 126003003, N'He said to me, “Son of man, feed your stomach and fill your belly with this scroll I am giving to you.” So I ate it, and it was sweet like honey in my mouth.'
EXEC add_BibleVerse @BibleId, 126003004, N'He said to me, “Son of man, go to the house of Israel and speak my words to them.'
EXEC add_BibleVerse @BibleId, 126003005, N'For you are not being sent to a people of unintelligible speech and difficult language, but to the house of Israel –'
EXEC add_BibleVerse @BibleId, 126003006, N'not to many peoples of unintelligible speech and difficult language, whose words you cannot understand – surely if I had sent you to them, they would listen to you!'
EXEC add_BibleVerse @BibleId, 126003007, N'But the house of Israel is unwilling to listen to you, because they are not willing to listen to me, for the whole house of Israel is hard-headed and hard-hearted.'
EXEC add_BibleVerse @BibleId, 126003008, N'“I have made your face adamant to match their faces, and your forehead hard to match their foreheads.'
EXEC add_BibleVerse @BibleId, 126003009, N'I have made your forehead harder than flint – like diamond! Do not fear them or be terrified of the looks they give you, for they are a rebellious house.”'
EXEC add_BibleVerse @BibleId, 126003010, N'And he said to me, “Son of man, take all my words that I speak to you to heart and listen carefully.'
EXEC add_BibleVerse @BibleId, 126003011, N'Go to the exiles, to your fellow countrymen, and speak to them – say to them, ‘This is what the sovereign Lord says,’ whether they pay attention or not.”'
EXEC add_BibleVerse @BibleId, 126003012, N'Then a wind lifted me up and I heard a great rumbling sound behind me as the glory of the Lord rose from its place,'
EXEC add_BibleVerse @BibleId, 126003013, N'and the sound of the living beings’ wings brushing against each other, and the sound of the wheels alongside them, a great rumbling sound.'
EXEC add_BibleVerse @BibleId, 126003014, N'A wind lifted me up and carried me away. I went bitterly, my spirit full of fury, and the hand of the Lord rested powerfully on me.'
EXEC add_BibleVerse @BibleId, 126003015, N'I came to the exiles at Tel Abib, who lived by the Kebar River. I sat dumbfounded among them there, where they were living, for seven days.'
EXEC add_BibleVerse @BibleId, 126003016, N'At the end of seven days the word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126003017, N'“Son of man, I have appointed you a watchman for the house of Israel. Whenever you hear a word from my mouth, you must give them a warning from me.'
EXEC add_BibleVerse @BibleId, 126003018, N'When I say to the wicked, “You will certainly die,” and you do not warn him – you do not speak out to warn the wicked to turn from his wicked deed and wicked lifestyle so that he may live – that wicked person will die for his iniquity, but I will hold you accountable for his death.'
EXEC add_BibleVerse @BibleId, 126003019, N'But as for you, if you warn the wicked and he does not turn from his wicked deed and from his wicked lifestyle, he will die for his iniquity but you will have saved your own life.'
EXEC add_BibleVerse @BibleId, 126003020, N'“When a righteous person turns from his righteousness and commits iniquity, and I set an obstacle before him, he will die. If you have not warned him, he will die for his sin. The righteous deeds he performed will not be considered, but I will hold you accountable for his death.'
EXEC add_BibleVerse @BibleId, 126003021, N'However, if you warn the righteous person not to sin, and he does not sin, he will certainly live because he was warned, and you will have saved your own life.”'
EXEC add_BibleVerse @BibleId, 126003022, N'The hand of the Lord rested on me there, and he said to me, “Get up, go out to the valley, and I will speak with you there.”'
EXEC add_BibleVerse @BibleId, 126003023, N'So I got up and went out to the valley, and the glory of the Lord was standing there, just like the glory I had seen by the Kebar River, and I threw myself face down.'
EXEC add_BibleVerse @BibleId, 126003024, N'Then a wind came into me and stood me on my feet. The Lord spoke to me and said, “Go shut yourself in your house.'
EXEC add_BibleVerse @BibleId, 126003025, N'As for you, son of man, they will put ropes on you and tie you up with them, so you cannot go out among them.'
EXEC add_BibleVerse @BibleId, 126003026, N'I will make your tongue stick to the roof of your mouth so that you will be silent and unable to reprove them, for they are a rebellious house.'
EXEC add_BibleVerse @BibleId, 126003027, N'But when I speak with you, I will loosen your tongue and you must say to them, ‘This is what the sovereign Lord says.’ Those who listen will listen, but the indifferent will refuse, for they are a rebellious house.'
EXEC add_BibleVerse @BibleId, 126004001, N'“And you, son of man, take a brick and set it in front of you. Inscribe a city on it – Jerusalem.'
EXEC add_BibleVerse @BibleId, 126004002, N'Lay siege to it! Build siege works against it. Erect a siege ramp against it! Post soldiers outside it and station battering rams around it.'
EXEC add_BibleVerse @BibleId, 126004003, N'Then for your part take an iron frying pan and set it up as an iron wall between you and the city. Set your face toward it. It is to be under siege; you are to besiege it. This is a sign for the house of Israel.'
EXEC add_BibleVerse @BibleId, 126004004, N'“Also for your part lie on your left side and place the iniquity of the house of Israel on it. For the number of days you lie on your side you will bear their iniquity.'
EXEC add_BibleVerse @BibleId, 126004005, N'I have determined that the number of the years of their iniquity are to be the number of days for you – 390 days. So bear the iniquity of the house of Israel.'
EXEC add_BibleVerse @BibleId, 126004006, N'“When you have completed these days, then lie down a second time, but on your right side, and bear the iniquity of the house of Judah 40 days – I have assigned one day for each year.'
EXEC add_BibleVerse @BibleId, 126004007, N'You must turn your face toward the siege of Jerusalem with your arm bared and prophesy against it.'
EXEC add_BibleVerse @BibleId, 126004008, N'Look here, I will tie you up with ropes, so you cannot turn from one side to the other until you complete the days of your siege.'
EXEC add_BibleVerse @BibleId, 126004009, N'“As for you, take wheat, barley, beans, lentils, millet, and spelt, put them in a single container, and make food from them for yourself. For the same number of days that you lie on your side – 390 days – you will eat it.'
EXEC add_BibleVerse @BibleId, 126004010, N'The food you eat will be eight ounces a day by weight; you must eat it at fixed times.'
EXEC add_BibleVerse @BibleId, 126004011, N'And you must drink water by measure, a pint and a half; you must drink it at fixed times.'
EXEC add_BibleVerse @BibleId, 126004012, N'And you must eat the food like you would a barley cake. You must bake it in front of them over a fire made with dried human excrement.”'
EXEC add_BibleVerse @BibleId, 126004013, N'And the Lord said, “This is how the people of Israel will eat their unclean food among the nations where I will banish them.”'
EXEC add_BibleVerse @BibleId, 126004014, N'And I said, “Ah, sovereign Lord, I have never been ceremonially defiled before. I have never eaten a carcass or an animal torn by wild beasts; from my youth up, unclean meat has never entered my mouth.”'
EXEC add_BibleVerse @BibleId, 126004015, N'So he said to me, “All right then, I will substitute cow’s manure instead of human excrement. You will cook your food over it.”'
EXEC add_BibleVerse @BibleId, 126004016, N'Then he said to me, “Son of man, I am about to remove the bread supply in Jerusalem. They will eat their bread ration anxiously, and they will drink their water ration in terror'
EXEC add_BibleVerse @BibleId, 126004017, N'because they will lack bread and water. Each one will be terrified, and they will rot for their iniquity.'
EXEC add_BibleVerse @BibleId, 126005001, N'“As for you, son of man, take a sharp sword and use it as a barber’s razor. Shave off some of the hair from your head and your beard. Then take scales and divide up the hair you cut off.'
EXEC add_BibleVerse @BibleId, 126005002, N'Burn a third of it in the fire inside the city when the days of your siege are completed. Take a third and slash it with a sword all around the city. Scatter a third to the wind, and I will unleash a sword behind them.'
EXEC add_BibleVerse @BibleId, 126005003, N'But take a few strands of hair from those and tie them in the ends of your garment.'
EXEC add_BibleVerse @BibleId, 126005004, N'Again, take more of them and throw them into the fire, and burn them up. From there a fire will spread to all the house of Israel.'
EXEC add_BibleVerse @BibleId, 126005005, N'“This is what the sovereign Lord says: This is Jerusalem; I placed her in the center of the nations with countries all around her.'
EXEC add_BibleVerse @BibleId, 126005006, N'Then she defied my regulations and my statutes, becoming more wicked than the nations and the countries around her. Indeed, they have rejected my regulations, and they do not follow my statutes.'
EXEC add_BibleVerse @BibleId, 126005007, N'“Therefore this is what the sovereign Lord says: Because you are more arrogant than the nations around you, you have not followed my statutes and have not carried out my regulations. You have not even carried out the regulations of the nations around you!'
EXEC add_BibleVerse @BibleId, 126005008, N'“Therefore this is what the sovereign Lord says: I – even I – am against you, and I will execute judgment among you while the nations watch.'
EXEC add_BibleVerse @BibleId, 126005009, N'I will do to you what I have never done before and will never do again because of all your abominable practices.'
EXEC add_BibleVerse @BibleId, 126005010, N'Therefore fathers will eat their sons within you, Jerusalem, and sons will eat their fathers. I will execute judgments on you, and I will scatter any survivors to the winds.'
EXEC add_BibleVerse @BibleId, 126005011, N'“Therefore, as surely as I live, says the sovereign Lord, because you defiled my sanctuary with all your detestable idols and with all your abominable practices, I will withdraw; my eye will not pity you, nor will I spare you.'
EXEC add_BibleVerse @BibleId, 126005012, N'A third of your people will die of plague or be overcome by the famine within you. A third of your people will fall by the sword surrounding you, and a third I will scatter to the winds. I will unleash a sword behind them.'
EXEC add_BibleVerse @BibleId, 126005013, N'Then my anger will be fully vented; I will exhaust my rage on them, and I will be appeased. Then they will know that I, the Lord, have spoken in my jealousy when I have fully vented my rage against them.'
EXEC add_BibleVerse @BibleId, 126005014, N'“I will make you desolate and an object of scorn among the nations around you, in the sight of everyone who passes by.'
EXEC add_BibleVerse @BibleId, 126005015, N'You will be an object of scorn and taunting, a prime example of destruction among the nations around you when I execute judgments against you in anger and raging fury. I, the Lord, have spoken!'
EXEC add_BibleVerse @BibleId, 126005016, N'I will shoot against them deadly, destructive arrows of famine, which I will shoot to destroy you. I will prolong a famine on you and will remove the bread supply.'
EXEC add_BibleVerse @BibleId, 126005017, N'I will send famine and wild beasts against you and they will take your children from you. Plague and bloodshed will overwhelm you, and I will bring a sword against you. I, the Lord, have spoken!”'
EXEC add_BibleVerse @BibleId, 126006001, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126006002, N'“Son of man, turn toward the mountains of Israel and prophesy against them:'
EXEC add_BibleVerse @BibleId, 126006003, N'Say, ‘Mountains of Israel, Hear the word of the sovereign Lord! This is what the sovereign Lord says to the mountains and the hills, to the ravines and the valleys: I am bringing a sword against you, and I will destroy your high places.'
EXEC add_BibleVerse @BibleId, 126006004, N'Your altars will be ruined and your incense altars will be broken. I will throw down your slain in front of your idols.'
EXEC add_BibleVerse @BibleId, 126006005, N'I will place the corpses of the people of Israel in front of their idols, and I will scatter your bones around your altars.'
EXEC add_BibleVerse @BibleId, 126006006, N'In all your dwellings, the cities will be laid waste and the high places ruined so that your altars will be laid waste and ruined, your idols will be shattered and demolished, your incense altars will be broken down, and your works wiped out.'
EXEC add_BibleVerse @BibleId, 126006007, N'The slain will fall among you and then you will know that I am the Lord.'
EXEC add_BibleVerse @BibleId, 126006008, N'“‘But I will spare some of you. Some will escape the sword when you are scattered in foreign lands.'
EXEC add_BibleVerse @BibleId, 126006009, N'Then your survivors will remember me among the nations where they are exiled. They will realize how I was crushed by their unfaithful heart which turned from me and by their eyes which lusted after their idols. They will loathe themselves because of the evil they have done and because of all their abominable practices.'
EXEC add_BibleVerse @BibleId, 126006010, N'They will know that I am the Lord; my threats to bring this catastrophe on them were not empty.’'
EXEC add_BibleVerse @BibleId, 126006011, N'“‘This is what the sovereign Lord says: Clap your hands, stamp your feet, and say, “Ah!” because of all the evil, abominable practices of the house of Israel, for they will fall by the sword, famine, and pestilence.'
EXEC add_BibleVerse @BibleId, 126006012, N'The one far away will die by pestilence, the one close by will fall by the sword, and whoever is left and has escaped these will die by famine. I will fully vent my rage against them.'
EXEC add_BibleVerse @BibleId, 126006013, N'Then you will know that I am the Lord – when their dead lie among their idols around their altars, on every high hill and all the mountaintops, under every green tree and every leafy oak, the places where they have offered fragrant incense to all their idols.'
EXEC add_BibleVerse @BibleId, 126006014, N'I will stretch out my hand against them and make the land a desolate waste from the wilderness to Riblah, in all the places where they live. Then they will know that I am the Lord!”'
EXEC add_BibleVerse @BibleId, 126007001, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126007002, N'“You, son of man – this is what the sovereign Lord says to the land of Israel: An end! The end is coming on the four corners of the land!'
EXEC add_BibleVerse @BibleId, 126007003, N'The end is now upon you, and I will release my anger against you; I will judge you according to your behavior, I will hold you accountable for all your abominable practices.'
EXEC add_BibleVerse @BibleId, 126007004, N'My eye will not pity you; I will not spare you. For I will hold you responsible for your behavior, and you will suffer the consequences of your abominable practices. Then you will know that I am the Lord!'
EXEC add_BibleVerse @BibleId, 126007005, N'“This is what the sovereign Lord says: A disaster – a one-of-a-kind disaster – is coming!'
EXEC add_BibleVerse @BibleId, 126007006, N'An end comes – the end comes! It has awakened against you – the end is upon you! Look, it is coming!'
EXEC add_BibleVerse @BibleId, 126007007, N'Doom is coming upon you who live in the land! The time is coming, the day is near. There are sounds of tumult, not shouts of joy, on the mountains.'
EXEC add_BibleVerse @BibleId, 126007008, N'Soon now I will pour out my rage on you; I will fully vent my anger against you. I will judge you according to your behavior. I will hold you accountable for all your abominable practices.'
EXEC add_BibleVerse @BibleId, 126007009, N'My eye will not pity you; I will not spare you. For your behavior I will hold you accountable, and you will suffer the consequences of your abominable practices. Then you will know that it is I, the Lord, who is striking you.'
EXEC add_BibleVerse @BibleId, 126007010, N'“Look, the day! Look, it is coming! Doom has gone out! The staff has budded, pride has blossomed!'
EXEC add_BibleVerse @BibleId, 126007011, N'Violence has grown into a staff that supports wickedness. Not one of them will be left – not from their crowd, not from their wealth, not from their prominence.'
EXEC add_BibleVerse @BibleId, 126007012, N'The time has come; the day has struck! The customer should not rejoice, nor the seller mourn; for divine wrath comes against their whole crowd.'
EXEC add_BibleVerse @BibleId, 126007013, N'The customer will no longer pay the seller while both parties are alive, for the vision against their whole crowd will not be revoked. Each person, for his iniquity, will fail to preserve his life.'
EXEC add_BibleVerse @BibleId, 126007014, N'“They have blown the trumpet and everyone is ready, but no one goes to battle, because my anger is against their whole crowd.'
EXEC add_BibleVerse @BibleId, 126007015, N'The sword is outside; pestilence and famine are inside the house. Whoever is in the open field will die by the sword, and famine and pestilence will consume everyone in the city.'
EXEC add_BibleVerse @BibleId, 126007016, N'Their survivors will escape to the mountains and become like doves of the valleys; all of them will moan – each one for his iniquity.'
EXEC add_BibleVerse @BibleId, 126007017, N'All of their hands will hang limp; their knees will be wet with urine.'
EXEC add_BibleVerse @BibleId, 126007018, N'They will wear sackcloth, terror will cover them; shame will be on all their faces, and all of their heads will be shaved bald.'
EXEC add_BibleVerse @BibleId, 126007019, N'They will discard their silver in the streets, and their gold will be treated like filth. Their silver and gold will not be able to deliver them on the day of the Lord’s fury. They will not satisfy their hunger or fill their stomachs because their wealth was the obstacle leading to their iniquity.'
EXEC add_BibleVerse @BibleId, 126007020, N'They rendered the beauty of his ornaments into pride, and with it they made their abominable images – their detestable idols. Therefore I will render it filthy to them.'
EXEC add_BibleVerse @BibleId, 126007021, N'I will give it to foreigners as loot, to the world’s wicked ones as plunder, and they will desecrate it.'
EXEC add_BibleVerse @BibleId, 126007022, N'I will turn my face away from them and they will desecrate my treasured place. Vandals will enter it and desecrate it.'
EXEC add_BibleVerse @BibleId, 126007023, N'(Make the chain, because the land is full of murder and the city is full of violence.)'
EXEC add_BibleVerse @BibleId, 126007024, N'I will bring the most wicked of the nations and they will take possession of their houses. I will put an end to the arrogance of the strong, and their sanctuaries will be desecrated.'
EXEC add_BibleVerse @BibleId, 126007025, N'Terror is coming! They will seek peace, but find none.'
EXEC add_BibleVerse @BibleId, 126007026, N'Disaster after disaster will come, and one rumor after another. They will seek a vision from a prophet; priestly instruction will disappear, along with counsel from the elders.'
EXEC add_BibleVerse @BibleId, 126007027, N'The king will mourn and the prince will be clothed with shuddering; the hands of the people of the land will tremble. Based on their behavior I will deal with them, and by their standard of justice I will judge them. Then they will know that I am the Lord!”'
EXEC add_BibleVerse @BibleId, 126008001, N'In the sixth year, in the sixth month, on the fifth of the month, as I was sitting in my house with the elders of Judah sitting in front of me, the hand of the sovereign Lord seized me.'
EXEC add_BibleVerse @BibleId, 126008002, N'As I watched, I noticed a form that appeared to be a man. From his waist downward was something like fire, and from his waist upward something like a brightness, like an amber glow.'
EXEC add_BibleVerse @BibleId, 126008003, N'He stretched out the form of a hand and grabbed me by a lock of hair on my head. Then a wind lifted me up between the earth and sky and brought me to Jerusalem by means of divine visions, to the door of the inner gate which faces north where the statue which provokes to jealousy was located.'
EXEC add_BibleVerse @BibleId, 126008004, N'Then I perceived that the glory of the God of Israel was there, as in the vision I had seen earlier in the valley.'
EXEC add_BibleVerse @BibleId, 126008005, N'He said to me, “Son of man, look up toward the north.” So I looked up toward the north, and I noticed to the north of the altar gate was this statue of jealousy at the entrance.'
EXEC add_BibleVerse @BibleId, 126008006, N'He said to me, “Son of man, do you see what they are doing – the great abominations that the people of Israel are practicing here, to drive me far from my sanctuary? But you will see greater abominations than these!”'
EXEC add_BibleVerse @BibleId, 126008007, N'He brought me to the entrance of the court, and as I watched, I noticed a hole in the wall.'
EXEC add_BibleVerse @BibleId, 126008008, N'He said to me, “Son of man, dig into the wall.” So I dug into the wall and discovered a doorway.'
EXEC add_BibleVerse @BibleId, 126008009, N'He said to me, “Go in and see the evil abominations they are practicing here.”'
EXEC add_BibleVerse @BibleId, 126008010, N'So I went in and looked. I noticed every figure of creeping thing and beast – detestable images – and every idol of the house of Israel, engraved on the wall all around.'
EXEC add_BibleVerse @BibleId, 126008011, N'Seventy men from the elders of the house of Israel (with Jaazaniah son of Shaphan standing among them) were standing in front of them, each with a censer in his hand, and fragrant vapors from a cloud of incense were swirling upward.'
EXEC add_BibleVerse @BibleId, 126008012, N'He said to me, “Do you see, son of man, what the elders of the house of Israel are doing in the dark, each in the chamber of his idolatrous images? For they think, ‘The Lord does not see us! The Lord has abandoned the land!’”'
EXEC add_BibleVerse @BibleId, 126008013, N'He said to me, “You will see them practicing even greater abominations!”'
EXEC add_BibleVerse @BibleId, 126008014, N'Then he brought me to the entrance of the north gate of the Lord’s house. I noticed women sitting there weeping for Tammuz.'
EXEC add_BibleVerse @BibleId, 126008015, N'He said to me, “Do you see this, son of man? You will see even greater abominations than these!”'
EXEC add_BibleVerse @BibleId, 126008016, N'Then he brought me to the inner court of the Lord’s house. Right there at the entrance to the Lord’s temple, between the porch and the altar, were about twenty-five men with their backs to the Lord’s temple, facing east – they were worshiping the sun toward the east!'
EXEC add_BibleVerse @BibleId, 126008017, N'He said to me, “Do you see, son of man? Is it a trivial thing that the house of Judah commits these abominations they are practicing here? For they have filled the land with violence and provoked me to anger still further. Look, they are putting the branch to their nose!'
EXEC add_BibleVerse @BibleId, 126008018, N'Therefore I will act with fury! My eye will not pity them nor will I spare them. When they have shouted in my ears, I will not listen to them.”'
EXEC add_BibleVerse @BibleId, 126009001, N'Then he shouted in my ears, “Approach, you who are to visit destruction on the city, each with his destructive weapon in his hand!”'
EXEC add_BibleVerse @BibleId, 126009002, N'Next, I noticed six men coming from the direction of the upper gate which faces north, each with his war club in his hand. Among them was a man dressed in linen with a writing kit at his side. They came and stood beside the bronze altar.'
EXEC add_BibleVerse @BibleId, 126009003, N'Then the glory of the God of Israel went up from the cherub where it had rested to the threshold of the temple. He called to the man dressed in linen who had the writing kit at his side.'
EXEC add_BibleVerse @BibleId, 126009004, N'The Lord said to him, “Go through the city of Jerusalem and put a mark on the foreheads of the people who moan and groan over all the abominations practiced in it.”'
EXEC add_BibleVerse @BibleId, 126009005, N'While I listened, he said to the others, “Go through the city after him and strike people down; do no let your eye pity nor spare anyone!'
EXEC add_BibleVerse @BibleId, 126009006, N'Old men, young men, young women, little children, and women – wipe them out! But do not touch anyone who has the mark. Begin at my sanctuary!” So they began with the elders who were at the front of the temple.'
EXEC add_BibleVerse @BibleId, 126009007, N'He said to them, “Defile the temple and fill the courtyards with corpses. Go!” So they went out and struck people down throughout the city.'
EXEC add_BibleVerse @BibleId, 126009008, N'While they were striking them down, I was left alone, and I threw myself face down and cried out, “Ah, sovereign Lord! Will you destroy the entire remnant of Israel when you pour out your fury on Jerusalem?”'
EXEC add_BibleVerse @BibleId, 126009009, N'He said to me, “The sin of the house of Israel and Judah is extremely great; the land is full of murder, and the city is full of corruption, for they say, ‘The Lord has abandoned the land, and the Lord does not see!’'
EXEC add_BibleVerse @BibleId, 126009010, N'But as for me, my eye will not pity them nor will I spare them; I hereby repay them for what they have done.”'
EXEC add_BibleVerse @BibleId, 126009011, N'Next I noticed the man dressed in linen with the writing kit at his side bringing back word: “I have done just as you commanded me.”'
EXEC add_BibleVerse @BibleId, 126010001, N'As I watched, I saw on the platform above the top of the cherubim something like a sapphire, resembling the shape of a throne, appearing above them.'
EXEC add_BibleVerse @BibleId, 126010002, N'The Lord said to the man dressed in linen, “Go between the wheelwork underneath the cherubim. Fill your hands with burning coals from among the cherubim and scatter them over the city.” He went as I watched.'
EXEC add_BibleVerse @BibleId, 126010003, N'(The cherubim were standing on the south side of the temple when the man went in, and a cloud filled the inner court.)'
EXEC add_BibleVerse @BibleId, 126010004, N'Then the glory of the Lord arose from the cherub and moved to the threshold of the temple. The temple was filled with the cloud while the court was filled with the brightness of the Lord’s glory.'
EXEC add_BibleVerse @BibleId, 126010005, N'The sound of the wings of the cherubim could be heard from the outer court, like the sound of the sovereign God when he speaks.'
EXEC add_BibleVerse @BibleId, 126010006, N'When the Lord commanded the man dressed in linen, “Take fire from within the wheelwork, from among the cherubim,” the man went in and stood by one of the wheels.'
EXEC add_BibleVerse @BibleId, 126010007, N'Then one of the cherubim stretched out his hand toward the fire which was among the cherubim. He took some and put it into the hands of the man dressed in linen, who took it and left.'
EXEC add_BibleVerse @BibleId, 126010008, N'(The cherubim appeared to have the form of human hands under their wings.)'
EXEC add_BibleVerse @BibleId, 126010009, N'As I watched, I noticed four wheels by the cherubim, one wheel beside each cherub; the wheels gleamed like jasper.'
EXEC add_BibleVerse @BibleId, 126010010, N'As for their appearance, all four of them looked the same, something like a wheel within a wheel.'
EXEC add_BibleVerse @BibleId, 126010011, N'When they moved, they would go in any of the four directions they faced without turning as they moved; in the direction the head would turn they would follow without turning as they moved,'
EXEC add_BibleVerse @BibleId, 126010012, N'along with their entire bodies, their backs, their hands, and their wings. The wheels of the four of them were full of eyes all around.'
EXEC add_BibleVerse @BibleId, 126010013, N'As for their wheels, they were called “the wheelwork” as I listened.'
EXEC add_BibleVerse @BibleId, 126010014, N'Each of the cherubim had four faces: The first was the face of a cherub, the second that of a man, the third that of a lion, and the fourth that of an eagle.'
EXEC add_BibleVerse @BibleId, 126010015, N'The cherubim rose up; these were the living beings I saw at the Kebar River.'
EXEC add_BibleVerse @BibleId, 126010016, N'When the cherubim moved, the wheels moved beside them; when the cherubim spread their wings to rise from the ground, the wheels did not move from their side.'
EXEC add_BibleVerse @BibleId, 126010017, N'When the cherubim stood still, the wheels stood still, and when they rose up, the wheels rose up with them, for the spirit of the living beings was in the wheels.'
EXEC add_BibleVerse @BibleId, 126010018, N'Then the glory of the Lord moved away from the threshold of the temple and stopped above the cherubim.'
EXEC add_BibleVerse @BibleId, 126010019, N'The cherubim spread their wings, and they rose up from the earth while I watched (when they went the wheels went alongside them). They stopped at the entrance to the east gate of the Lord’s temple as the glory of the God of Israel hovered above them.'
EXEC add_BibleVerse @BibleId, 126010020, N'These were the living creatures which I saw at the Kebar River underneath the God of Israel; I knew that they were cherubim.'
EXEC add_BibleVerse @BibleId, 126010021, N'Each had four faces; each had four wings and the form of human hands under the wings.'
EXEC add_BibleVerse @BibleId, 126010022, N'As for the form of their faces, they were the faces whose appearance I had seen at the Kebar River. Each one moved straight ahead.'
EXEC add_BibleVerse @BibleId, 126011001, N'A wind lifted me up and brought me to the east gate of the Lord’s temple that faces the east. There, at the entrance of the gate, I noticed twenty-five men. Among them I saw Jaazaniah son of Azzur and Pelatiah son of Benaiah, officials of the people.'
EXEC add_BibleVerse @BibleId, 126011002, N'The Lord said to me, “Son of man, these are the men who plot evil and give wicked advice in this city.'
EXEC add_BibleVerse @BibleId, 126011003, N'They say, ‘The time is not near to build houses; the city is a cooking pot and we are the meat in it.’'
EXEC add_BibleVerse @BibleId, 126011004, N'Therefore, prophesy against them! Prophesy, son of man!”'
EXEC add_BibleVerse @BibleId, 126011005, N'Then the Spirit of the Lord came upon me and said to me, “Say: This is what the Lord says: ‘This is what you are thinking, O house of Israel; I know what goes through your minds.'
EXEC add_BibleVerse @BibleId, 126011006, N'You have killed many people in this city; you have filled its streets with corpses.’'
EXEC add_BibleVerse @BibleId, 126011007, N'Therefore, this is what the sovereign Lord says: ‘The corpses you have dumped in the midst of the city are the meat, and this city is the cooking pot, but I will take you out of it.'
EXEC add_BibleVerse @BibleId, 126011008, N'You fear the sword, so the sword I will bring against you,’ declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126011009, N'‘But I will take you out of the city. And I will hand you over to foreigners. I will execute judgments on you.'
EXEC add_BibleVerse @BibleId, 126011010, N'You will die by the sword; I will judge you at the border of Israel. Then you will know that I am the Lord.'
EXEC add_BibleVerse @BibleId, 126011011, N'This city will not be a cooking pot for you, and you will not be meat within it; I will judge you at the border of Israel.'
EXEC add_BibleVerse @BibleId, 126011012, N'Then you will know that I am the Lord, whose statutes you have not followed and whose regulations you have not carried out. Instead you have behaved according to the regulations of the nations around you!’”'
EXEC add_BibleVerse @BibleId, 126011013, N'Now, while I was prophesying, Pelatiah son of Benaiah died. Then I threw myself face down and cried out with a loud voice, “Alas, sovereign Lord! You are completely wiping out the remnant of Israel!”'
EXEC add_BibleVerse @BibleId, 126011014, N'Then the word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126011015, N'“Son of man, your brothers, your relatives, and the whole house of Israel, all of them are those to whom the inhabitants of Jerusalem have said, ‘They have gone far away from the Lord; to us this land has been given as a possession.’'
EXEC add_BibleVerse @BibleId, 126011016, N'“Therefore say: ‘This is what the sovereign Lord says: Although I have removed them far away among the nations and have dispersed them among the countries, I have been a little sanctuary for them among the lands where they have gone.’'
EXEC add_BibleVerse @BibleId, 126011017, N'“Therefore say: ‘This is what the sovereign Lord says: When I regather you from the peoples and assemble you from the lands where you have been dispersed, I will give you back the country of Israel.’'
EXEC add_BibleVerse @BibleId, 126011018, N'“When they return to it, they will remove from it all its detestable things and all its abominations.'
EXEC add_BibleVerse @BibleId, 126011019, N'I will give them one heart and I will put a new spirit within them; I will remove the hearts of stone from their bodies and I will give them tender hearts,'
EXEC add_BibleVerse @BibleId, 126011020, N'so that they may follow my statutes and observe my regulations and carry them out. Then they will be my people, and I will be their God.'
EXEC add_BibleVerse @BibleId, 126011021, N'But those whose hearts are devoted to detestable things and abominations, I hereby repay them for what they have done, says the sovereign Lord.”'
EXEC add_BibleVerse @BibleId, 126011022, N'Then the cherubim spread their wings with their wheels alongside them while the glory of the God of Israel hovered above them.'
EXEC add_BibleVerse @BibleId, 126011023, N'The glory of the Lord rose up from within the city and stopped over the mountain east of it.'
EXEC add_BibleVerse @BibleId, 126011024, N'Then a wind lifted me up and carried me to the exiles in Babylonia, in the vision given to me by the Spirit of God. Then the vision I had seen went up from me.'
EXEC add_BibleVerse @BibleId, 126011025, N'So I told the exiles everything the Lord had shown me.'
EXEC add_BibleVerse @BibleId, 126012001, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126012002, N'“Son of man, you are living in the midst of a rebellious house. They have eyes to see, but do not see, and ears to hear, but do not hear, because they are a rebellious house.'
EXEC add_BibleVerse @BibleId, 126012003, N'“Therefore, son of man, pack up your belongings as if for exile. During the day, while they are watching, pretend to go into exile. Go from where you live to another place. Perhaps they will understand, although they are a rebellious house.'
EXEC add_BibleVerse @BibleId, 126012004, N'Bring out your belongings packed for exile during the day while they are watching. And go out at evening, while they are watching, as if for exile.'
EXEC add_BibleVerse @BibleId, 126012005, N'While they are watching, dig a hole in the wall and carry your belongings out through it.'
EXEC add_BibleVerse @BibleId, 126012006, N'While they are watching, raise your baggage onto your shoulder and carry it out in the dark. You must cover your face so that you cannot see the ground because I have made you an object lesson to the house of Israel.”'
EXEC add_BibleVerse @BibleId, 126012007, N'So I did just as I was commanded. I carried out my belongings packed for exile during the day, and at evening I dug myself a hole through the wall with my hands. I went out in the darkness, carrying my baggage on my shoulder while they watched.'
EXEC add_BibleVerse @BibleId, 126012008, N'The word of the Lord came to me in the morning:'
EXEC add_BibleVerse @BibleId, 126012009, N'“Son of man, has not the house of Israel, that rebellious house, said to you, ‘What are you doing?’'
EXEC add_BibleVerse @BibleId, 126012010, N'Say to them, ‘This is what the sovereign Lord says: The prince will raise this burden in Jerusalem, and all the house of Israel within it.’'
EXEC add_BibleVerse @BibleId, 126012011, N'Say, ‘I am an object lesson for you. Just as I have done, it will be done to them; they will go into exile and captivity.’'
EXEC add_BibleVerse @BibleId, 126012012, N'“The prince who is among them will raise his belongings onto his shoulder in darkness, and will go out. He will dig a hole in the wall to leave through. He will cover his face so that he cannot see the land with his eyes.'
EXEC add_BibleVerse @BibleId, 126012013, N'But I will throw my net over him, and he will be caught in my snare. I will bring him to Babylon, the land of the Chaldeans (but he will not see it), and there he will die.'
EXEC add_BibleVerse @BibleId, 126012014, N'All his retinue – his attendants and his troops – I will scatter to every wind; I will unleash a sword behind them.'
EXEC add_BibleVerse @BibleId, 126012015, N'“Then they will know that I am the Lord when I disperse them among the nations and scatter them among foreign countries.'
EXEC add_BibleVerse @BibleId, 126012016, N'But I will let a small number of them survive the sword, famine, and pestilence, so that they can confess all their abominable practices to the nations where they go. Then they will know that I am the Lord.”'
EXEC add_BibleVerse @BibleId, 126012017, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126012018, N'“Son of man, eat your bread with trembling, and drink your water with anxious shaking.'
EXEC add_BibleVerse @BibleId, 126012019, N'Then say to the people of the land, ‘This is what the sovereign Lord says about the inhabitants of Jerusalem and of the land of Israel: They will eat their bread with anxiety and drink their water in fright, for their land will be stripped bare of all it contains because of the violence of all who live in it.'
EXEC add_BibleVerse @BibleId, 126012020, N'The inhabited towns will be left in ruins and the land will be devastated. Then you will know that I am the Lord.’”'
EXEC add_BibleVerse @BibleId, 126012021, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126012022, N'“Son of man, what is this proverb you have in the land of Israel, ‘The days pass slowly, and every vision fails’?'
EXEC add_BibleVerse @BibleId, 126012023, N'Therefore tell them, ‘This is what the sovereign Lord says: I hereby end this proverb; they will not recite it in Israel any longer.’ But say to them, ‘The days are at hand when every vision will be fulfilled.'
EXEC add_BibleVerse @BibleId, 126012024, N'For there will no longer be any false visions or flattering omens amidst the house of Israel.'
EXEC add_BibleVerse @BibleId, 126012025, N'For I, the Lord, will speak. Whatever word I speak will be accomplished. It will not be delayed any longer. Indeed in your days, O rebellious house, I will speak the word and accomplish it, declares the sovereign Lord.’”'
EXEC add_BibleVerse @BibleId, 126012026, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126012027, N'“Take note, son of man, the house of Israel is saying, ‘The vision that he sees is for distant days; he is prophesying about the far future.’'
EXEC add_BibleVerse @BibleId, 126012028, N'Therefore say to them, ‘This is what the sovereign Lord says: None of my words will be delayed any longer! The word I speak will come to pass, declares the sovereign Lord.’”'
EXEC add_BibleVerse @BibleId, 126013001, N'Then the word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126013002, N'“Son of man, prophesy against the prophets of Israel who are now prophesying. Say to the prophets who prophesy from their imagination: ‘Hear the word of the Lord!'
EXEC add_BibleVerse @BibleId, 126013003, N'This is what the sovereign Lord says: Woe to the foolish prophets who follow their own spirit but have seen nothing!'
EXEC add_BibleVerse @BibleId, 126013004, N'Your prophets have become like jackals among the ruins, O Israel.'
EXEC add_BibleVerse @BibleId, 126013005, N'You have not gone up in the breaks in the wall, nor repaired a wall for the house of Israel that it would stand strong in the battle on the day of the Lord.'
EXEC add_BibleVerse @BibleId, 126013006, N'They see delusion and their omens are a lie. They say, “the Lord declares,” though the Lord has not sent them; yet they expect their word to be confirmed.'
EXEC add_BibleVerse @BibleId, 126013007, N'Have you not seen a false vision and announced a lying omen when you say, “the Lord declares,” although I myself never spoke?'
EXEC add_BibleVerse @BibleId, 126013008, N'“‘Therefore, this is what the sovereign Lord says: Because you have spoken false words and forecast delusion, look, I am against you, declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126013009, N'My hand will be against the prophets who see delusion and announce lying omens. They will not be included in the council of my people, nor be written in the registry of the house of Israel, nor enter the land of Israel. Then you will know that I am the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126013010, N'“‘This is because they have led my people astray saying, “All is well,” when things are not well. When anyone builds a wall without mortar, they coat it with whitewash.'
EXEC add_BibleVerse @BibleId, 126013011, N'Tell the ones who coat it with whitewash that it will fall. When there is a deluge of rain, hailstones will fall and a violent wind will break out.'
EXEC add_BibleVerse @BibleId, 126013012, N'When the wall has collapsed, people will ask you, “Where is the whitewash you coated it with?”'
EXEC add_BibleVerse @BibleId, 126013013, N'“‘Therefore this is what the sovereign Lord says: In my rage I will make a violent wind break out. In my anger there will be a deluge of rain and hailstones in destructive fury.'
EXEC add_BibleVerse @BibleId, 126013014, N'I will break down the wall you coated with whitewash and knock it to the ground so that its foundation is exposed. When it falls you will be destroyed beneath it, and you will know that I am the Lord.'
EXEC add_BibleVerse @BibleId, 126013015, N'I will vent my rage against the wall, and against those who coated it with whitewash. Then I will say to you, “The wall is no more and those who whitewashed it are no more –'
EXEC add_BibleVerse @BibleId, 126013016, N'those prophets of Israel who would prophesy about Jerusalem and would see visions of peace for it, when there was no peace,” declares the sovereign Lord.’'
EXEC add_BibleVerse @BibleId, 126013017, N'“As for you, son of man, turn toward the daughters of your people who are prophesying from their imagination. Prophesy against them'
EXEC add_BibleVerse @BibleId, 126013018, N'and say ‘This is what the sovereign Lord says: Woe to those who sew bands on all their wrists and make headbands for heads of every size to entrap people’s lives! Will you entrap my people’s lives, yet preserve your own lives?'
EXEC add_BibleVerse @BibleId, 126013019, N'You have profaned me among my people for handfuls of barley and scraps of bread. You have put to death people who should not die and kept alive those who should not live by your lies to my people, who listen to lies!'
EXEC add_BibleVerse @BibleId, 126013020, N'“‘Therefore, this is what the sovereign Lord says: Take note that I am against your wristbands with which you entrap people’s lives like birds. I will tear them from your arms and will release the people’s lives, which you hunt like birds.'
EXEC add_BibleVerse @BibleId, 126013021, N'I will tear off your headbands and rescue my people from your power; they will no longer be prey in your hands. Then you will know that I am the Lord.'
EXEC add_BibleVerse @BibleId, 126013022, N'This is because you have disheartened the righteous person with lies (although I have not grieved him), and because you have encouraged the wicked person not to turn from his evil conduct and preserve his life.'
EXEC add_BibleVerse @BibleId, 126013023, N'Therefore you will no longer see false visions and practice divination. I will rescue my people from your power, and you will know that I am the Lord.’”'
EXEC add_BibleVerse @BibleId, 126014001, N'Then some men from Israel’s elders came to me and sat down in front of me.'
EXEC add_BibleVerse @BibleId, 126014002, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126014003, N'“Son of man, these men have erected their idols in their hearts and placed the obstacle leading to their iniquity right before their faces. Should I really allow them to seek me?'
EXEC add_BibleVerse @BibleId, 126014004, N'Therefore speak to them and say to them, ‘This is what the sovereign Lord says: When any one from the house of Israel erects his idols in his heart and sets the obstacle leading to his iniquity before his face, and then consults a prophet, I the Lord am determined to answer him personally according to the enormity of his idolatry.'
EXEC add_BibleVerse @BibleId, 126014005, N'I will do this in order to capture the hearts of the house of Israel, who have alienated themselves from me on account of all their idols.’'
EXEC add_BibleVerse @BibleId, 126014006, N'“Therefore say to the house of Israel, ‘This is what the sovereign Lord says: Return! Turn from your idols, and turn your faces away from your abominations.'
EXEC add_BibleVerse @BibleId, 126014007, N'For when anyone from the house of Israel, or the foreigner who lives in Israel, separates himself from me and erects his idols in his heart and sets the obstacle leading to his iniquity before his face, and then consults a prophet to seek something from me, I the Lord am determined to answer him personally.'
EXEC add_BibleVerse @BibleId, 126014008, N'I will set my face against that person and will make him an object lesson and a byword and will cut him off from among my people. Then you will know that I am the Lord.'
EXEC add_BibleVerse @BibleId, 126014009, N'“‘As for the prophet, if he is made a fool by being deceived into speaking a prophetic word – I, the Lord, have made a fool of that prophet, and I will stretch out my hand against him and destroy him from among my people Israel.'
EXEC add_BibleVerse @BibleId, 126014010, N'They will bear their punishment; the punishment of the one who sought an oracle will be the same as the punishment of the prophet who gave it'
EXEC add_BibleVerse @BibleId, 126014011, N'so that the house of Israel will no longer go astray from me, nor continue to defile themselves by all their sins. They will be my people and I will be their God, declares the sovereign Lord.’”'
EXEC add_BibleVerse @BibleId, 126014012, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126014013, N'“Son of man, suppose a country sins against me by being unfaithful, and I stretch out my hand against it, cut off its bread supply, cause famine to come on it, and kill both people and animals.'
EXEC add_BibleVerse @BibleId, 126014014, N'Even if these three men, Noah, Daniel, and Job, were in it, they would save only their own lives by their righteousness, declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126014015, N'“Suppose I were to send wild animals through the land and kill its children, leaving it desolate, without travelers due to the wild animals.'
EXEC add_BibleVerse @BibleId, 126014016, N'Even if these three men were in it, as surely as I live, declares the sovereign Lord, they could not save their own sons or daughters; they would save only their own lives, and the land would become desolate.'
EXEC add_BibleVerse @BibleId, 126014017, N'“Or suppose I were to bring a sword against that land and say, ‘Let a sword pass through the land,’ and I were to kill both people and animals.'
EXEC add_BibleVerse @BibleId, 126014018, N'Even if these three men were in it, as surely as I live, declares the sovereign Lord, they could not save their own sons or daughters – they would save only their own lives.'
EXEC add_BibleVerse @BibleId, 126014019, N'“Or suppose I were to send a plague into that land, and pour out my rage on it with bloodshed, killing both people and animals.'
EXEC add_BibleVerse @BibleId, 126014020, N'Even if Noah, Daniel, and Job were in it, as surely as I live, declares the sovereign Lord, they could not save their own son or daughter; they would save only their own lives by their righteousness.'
EXEC add_BibleVerse @BibleId, 126014021, N'“For this is what the sovereign Lord says: How much worse will it be when I send my four terrible judgments – sword, famine, wild animals, and plague – to Jerusalem to kill both people and animals!'
EXEC add_BibleVerse @BibleId, 126014022, N'Yet some survivors will be left in it, sons and daughters who will be brought out. They will come out to you, and when you see their behavior and their deeds, you will be consoled about the catastrophe I have brought on Jerusalem – for everything I brought on it.'
EXEC add_BibleVerse @BibleId, 126014023, N'They will console you when you see their behavior and their deeds, because you will know that it was not without reason that I have done everything which I have done in it, declares the sovereign Lord.”'
EXEC add_BibleVerse @BibleId, 126015001, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126015002, N'“Son of man, of all the woody branches among the trees of the forest, what happens to the wood of the vine?'
EXEC add_BibleVerse @BibleId, 126015003, N'Can wood be taken from it to make anything useful? Or can anyone make a peg from it to hang things on?'
EXEC add_BibleVerse @BibleId, 126015004, N'No! It is thrown in the fire for fuel; when the fire has burned up both ends of it and it is charred in the middle, will it be useful for anything?'
EXEC add_BibleVerse @BibleId, 126015005, N'Indeed! If it was not made into anything useful when it was whole, how much less can it be made into anything when the fire has burned it up and it is charred?'
EXEC add_BibleVerse @BibleId, 126015006, N'“Therefore, this is what the sovereign Lord says: Like the wood of the vine is among the trees of the forest which I have provided as fuel for the fire – so I will provide the residents of Jerusalem as fuel.'
EXEC add_BibleVerse @BibleId, 126015007, N'I will set my face against them – although they have escaped from the fire, the fire will still consume them! Then you will know that I am the Lord, when I set my face against them.'
EXEC add_BibleVerse @BibleId, 126015008, N'I will make the land desolate because they have acted unfaithfully, declares the sovereign Lord.”'
EXEC add_BibleVerse @BibleId, 126016001, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126016002, N'“Son of man, confront Jerusalem with her abominable practices'
EXEC add_BibleVerse @BibleId, 126016003, N'and say, ‘This is what the sovereign Lord says to Jerusalem: Your origin and your birth were in the land of the Canaanites; your father was an Amorite and your mother a Hittite.'
EXEC add_BibleVerse @BibleId, 126016004, N'As for your birth, on the day you were born your umbilical cord was not cut, nor were you washed in water; you were certainly not rubbed down with salt, nor wrapped with blankets.'
EXEC add_BibleVerse @BibleId, 126016005, N'No eye took pity on you to do even one of these things for you to spare you; you were thrown out into the open field because you were detested on the day you were born.'
EXEC add_BibleVerse @BibleId, 126016006, N'“‘I passed by you and saw you kicking around helplessly in your blood. I said to you as you lay there in your blood, “Live!” I said to you as you lay there in your blood, “Live!”'
EXEC add_BibleVerse @BibleId, 126016007, N'I made you plentiful like sprouts in a field; you grew tall and came of age so that you could wear jewelry. Your breasts had formed and your hair had grown, but you were still naked and bare.'
EXEC add_BibleVerse @BibleId, 126016008, N'“‘Then I passed by you and watched you, noticing that you had reached the age for love. I spread my cloak over you and covered your nakedness. I swore a solemn oath to you and entered into a marriage covenant with you, declares the sovereign Lord, and you became mine.'
EXEC add_BibleVerse @BibleId, 126016009, N'“‘Then I bathed you in water, washed the blood off you, and anointed you with fragrant oil.'
EXEC add_BibleVerse @BibleId, 126016010, N'I dressed you in embroidered clothing and put fine leather sandals on your feet. I wrapped you with fine linen and covered you with silk.'
EXEC add_BibleVerse @BibleId, 126016011, N'I adorned you with jewelry. I put bracelets on your hands and a necklace around your neck.'
EXEC add_BibleVerse @BibleId, 126016012, N'I put a ring in your nose, earrings on your ears, and a beautiful crown on your head.'
EXEC add_BibleVerse @BibleId, 126016013, N'You were adorned with gold and silver, while your clothing was of fine linen, silk, and embroidery. You ate the finest flour, honey, and olive oil. You became extremely beautiful and attained the position of royalty.'
EXEC add_BibleVerse @BibleId, 126016014, N'Your fame spread among the nations because of your beauty; your beauty was perfect because of the splendor which I bestowed on you, declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126016015, N'“‘But you trusted in your beauty and capitalized on your fame by becoming a prostitute. You offered your sexual favors to every man who passed by so that your beauty became his.'
EXEC add_BibleVerse @BibleId, 126016016, N'You took some of your clothing and made for yourself decorated high places; you engaged in prostitution on them. You went to him to become his.'
EXEC add_BibleVerse @BibleId, 126016017, N'You also took your beautiful jewelry, made of my gold and my silver I had given to you, and made for yourself male images and engaged in prostitution with them.'
EXEC add_BibleVerse @BibleId, 126016018, N'You took your embroidered clothing and used it to cover them; you offered my olive oil and my incense to them.'
EXEC add_BibleVerse @BibleId, 126016019, N'As for my food that I gave you – the fine flour, olive oil, and honey I fed you – you placed it before them as a soothing aroma. That is exactly what happened, declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126016020, N'“‘You took your sons and your daughters whom you bore to me and you sacrificed them as food for the idols to eat. As if your prostitution not enough,'
EXEC add_BibleVerse @BibleId, 126016021, N'you slaughtered my children and sacrificed them to the idols.'
EXEC add_BibleVerse @BibleId, 126016022, N'And with all your abominable practices and prostitution you did not remember the days of your youth when you were naked and bare, kicking around in your blood.'
EXEC add_BibleVerse @BibleId, 126016023, N'“‘After all of your evil – “Woe! Woe to you!” declares the sovereign Lord –'
EXEC add_BibleVerse @BibleId, 126016024, N'you built yourself a chamber and put up a pavilion in every public square.'
EXEC add_BibleVerse @BibleId, 126016025, N'At the head of every street you erected your pavilion and you disgraced your beauty when you spread your legs to every passerby and multiplied your promiscuity.'
EXEC add_BibleVerse @BibleId, 126016026, N'You engaged in prostitution with the Egyptians, your sexually aroused neighbors, multiplying your promiscuity and provoking me to anger.'
EXEC add_BibleVerse @BibleId, 126016027, N'So see here, I have stretched out my hand against you and cut off your rations. I have delivered you into the power of those who hate you, the daughters of the Philistines, who were ashamed by your obscene conduct.'
EXEC add_BibleVerse @BibleId, 126016028, N'You engaged in prostitution with the Assyrians because your sexual desires were insatiable; you prostituted yourself with them and yet you were still not satisfied.'
EXEC add_BibleVerse @BibleId, 126016029, N'Then you multiplied your promiscuity to the land of merchants, Babylonia, but you were not satisfied there either.'
EXEC add_BibleVerse @BibleId, 126016030, N'“‘How sick is your heart, declares the sovereign Lord, when you perform all of these acts, the deeds of a bold prostitute.'
EXEC add_BibleVerse @BibleId, 126016031, N'When you built your chamber at the head of every street and put up your pavilion in every public square, you were not like a prostitute, because you scoffed at payment.'
EXEC add_BibleVerse @BibleId, 126016032, N'“‘Adulterous wife, who prefers strangers instead of her own husband!'
EXEC add_BibleVerse @BibleId, 126016033, N'All prostitutes receive payment, but instead you give gifts to every one of your lovers. You bribe them to come to you from all around for your sexual favors!'
EXEC add_BibleVerse @BibleId, 126016034, N'You were different from other prostitutes because no one solicited you. When you gave payment and no payment was given to you, you became the opposite!'
EXEC add_BibleVerse @BibleId, 126016035, N'“‘Therefore O prostitute, hear the word of the Lord:'
EXEC add_BibleVerse @BibleId, 126016036, N'This is what the sovereign Lord says: Because your lust was poured out and your nakedness was uncovered in your prostitution with your lovers, and because of all your detestable idols, and because of the blood of your children you have given to them,'
EXEC add_BibleVerse @BibleId, 126016037, N'therefore, take note: I am about to gather all your lovers whom you enjoyed, both all those you loved and all those you hated. I will gather them against you from all around, and I will expose your nakedness to them, and they will see all your nakedness.'
EXEC add_BibleVerse @BibleId, 126016038, N'I will punish you as an adulteress and murderer deserves. I will avenge your bloody deeds with furious rage.'
EXEC add_BibleVerse @BibleId, 126016039, N'I will give you into their hands and they will destroy your chambers and tear down your pavilions. They will strip you of your clothing and take your beautiful jewelry and leave you naked and bare.'
EXEC add_BibleVerse @BibleId, 126016040, N'They will summon a mob who will stone you and hack you in pieces with their swords.'
EXEC add_BibleVerse @BibleId, 126016041, N'They will burn down your houses and execute judgments on you in front of many women. Thus I will put a stop to your prostitution, and you will no longer give gifts to your clients.'
EXEC add_BibleVerse @BibleId, 126016042, N'I will exhaust my rage on you, and then my fury will turn from you. I will calm down and no longer be angry.'
EXEC add_BibleVerse @BibleId, 126016043, N'“‘Because you did not remember the days of your youth and have enraged me with all these deeds, I hereby repay you for what you have done, declares the sovereign Lord. Have you not engaged in prostitution on top of all your other abominable practices?'
EXEC add_BibleVerse @BibleId, 126016044, N'“‘Observe – everyone who quotes proverbs will quote this proverb about you: “Like mother, like daughter.”'
EXEC add_BibleVerse @BibleId, 126016045, N'You are the daughter of your mother, who detested her husband and her sons, and you are the sister of your sisters who detested their husbands and their sons. Your mother was a Hittite and your father an Amorite.'
EXEC add_BibleVerse @BibleId, 126016046, N'Your older sister was Samaria, who lived north of you with her daughters, and your younger sister, who lived south of you, was Sodom with her daughters.'
EXEC add_BibleVerse @BibleId, 126016047, N'Have you not copied their behavior and practiced their abominable deeds? In a short time you became even more depraved in all your conduct than they were!'
EXEC add_BibleVerse @BibleId, 126016048, N'As surely as I live, declares the sovereign Lord, your sister Sodom and her daughters never behaved as wickedly as you and your daughters have behaved.'
EXEC add_BibleVerse @BibleId, 126016049, N'“‘See here – this was the iniquity of your sister Sodom: She and her daughters had majesty, abundance of food, and enjoyed carefree ease, but they did not help the poor and needy.'
EXEC add_BibleVerse @BibleId, 126016050, N'They were haughty and practiced abominable deeds before me. Therefore when I saw it I removed them.'
EXEC add_BibleVerse @BibleId, 126016051, N'Samaria has not committed half the sins you have; you have done more abominable deeds than they did. You have made your sisters appear righteous with all the abominable things you have done.'
EXEC add_BibleVerse @BibleId, 126016052, N'So now, bear your disgrace, because you have given your sisters reason to justify their behavior. Because the sins you have committed were more abominable than those of your sisters; they have become more righteous than you. So now, be ashamed and bear the disgrace of making your sisters appear righteous.'
EXEC add_BibleVerse @BibleId, 126016053, N'“‘I will restore their fortunes, the fortunes of Sodom and her daughters, and the fortunes of Samaria and her daughters (along with your fortunes among them),'
EXEC add_BibleVerse @BibleId, 126016054, N'so that you may bear your disgrace and be ashamed of all you have done in consoling them.'
EXEC add_BibleVerse @BibleId, 126016055, N'As for your sisters, Sodom and her daughters will be restored to their former status, Samaria and her daughters will be restored to their former status, and you and your daughters will be restored to your former status.'
EXEC add_BibleVerse @BibleId, 126016056, N'In your days of majesty, was not Sodom your sister a byword in your mouth,'
EXEC add_BibleVerse @BibleId, 126016057, N'before your evil was exposed? Now you have become an object of scorn to the daughters of Aram and all those around her and to the daughters of the Philistines – those all around you who despise you.'
EXEC add_BibleVerse @BibleId, 126016058, N'You must bear your punishment for your obscene conduct and your abominable practices, declares the Lord.'
EXEC add_BibleVerse @BibleId, 126016059, N'“‘For this is what the sovereign Lord says: I will deal with you according to what you have done when you despised your oath by breaking your covenant.'
EXEC add_BibleVerse @BibleId, 126016060, N'Yet I will remember the covenant I made with you in the days of your youth, and I will establish a lasting covenant with you.'
EXEC add_BibleVerse @BibleId, 126016061, N'Then you will remember your conduct, and be ashamed when you receive your older and younger sisters. I will give them to you as daughters, but not on account of my covenant with you.'
EXEC add_BibleVerse @BibleId, 126016062, N'I will establish my covenant with you, and then you will know that I am the Lord.'
EXEC add_BibleVerse @BibleId, 126016063, N'Then you will remember, be ashamed, and remain silent when I make atonement for all you have done, declares the sovereign Lord.’”'
EXEC add_BibleVerse @BibleId, 126017001, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126017002, N'“Son of man, offer a riddle, and tell a parable to the house of Israel.'
EXEC add_BibleVerse @BibleId, 126017003, N'Say to them: ‘This is what the sovereign Lord says: “‘A great eagle with broad wings, long feathers, with full plumage which was multi-hued, came to Lebanon and took the top of the cedar.'
EXEC add_BibleVerse @BibleId, 126017004, N'He plucked off its topmost shoot; he brought it to a land of merchants and planted it in a city of traders.'
EXEC add_BibleVerse @BibleId, 126017005, N'He took one of the seedlings of the land, placed it in a cultivated plot; a shoot by abundant water, like a willow he planted it.'
EXEC add_BibleVerse @BibleId, 126017006, N'It sprouted and became a vine, spreading low to the ground; its branches turning toward him, its roots were under itself. So it became a vine; it produced shoots and sent out branches.'
EXEC add_BibleVerse @BibleId, 126017007, N'“‘There was another great eagle with broad wings and thick plumage. Now this vine twisted its roots toward him and sent its branches toward him to be watered from the soil where it was planted.'
EXEC add_BibleVerse @BibleId, 126017008, N'In a good field, by abundant waters, it was planted to grow branches, bear fruit, and become a beautiful vine.'
EXEC add_BibleVerse @BibleId, 126017009, N'“‘Say to them: This is what the sovereign Lord says: “‘Will it prosper? Will he not rip out its roots and cause its fruit to rot and wither? All its foliage will wither. No strong arm or large army will be needed to pull it out by its roots.'
EXEC add_BibleVerse @BibleId, 126017010, N'Consider! It is planted, but will it prosper? Will it not wither completely when the east wind blows on it? Will it not wither in the soil where it sprouted?’”'
EXEC add_BibleVerse @BibleId, 126017011, N'Then the word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126017012, N'“Say to the rebellious house of Israel: ‘Don’t you know what these things mean?’ Say: ‘See here, the king of Babylon came to Jerusalem and took her king and her officials prisoner and brought them to himself in Babylon.'
EXEC add_BibleVerse @BibleId, 126017013, N'He took one from the royal family, made a treaty with him, and put him under oath. He then took the leaders of the land'
EXEC add_BibleVerse @BibleId, 126017014, N'so it would be a lowly kingdom which could not rise on its own but must keep its treaty with him in order to stand.'
EXEC add_BibleVerse @BibleId, 126017015, N'But this one from Israel’s royal family rebelled against the king of Babylon by sending his emissaries to Egypt to obtain horses and a large army. Will he prosper? Will the one doing these things escape? Can he break the covenant and escape?'
EXEC add_BibleVerse @BibleId, 126017016, N'“‘As surely as I live, declares the sovereign Lord, surely in the city of the king who crowned him, whose oath he despised and whose covenant he broke – in the middle of Babylon he will die!'
EXEC add_BibleVerse @BibleId, 126017017, N'Pharaoh with his great army and mighty horde will not help him in battle, when siege ramps are erected and siege-walls are built to kill many people.'
EXEC add_BibleVerse @BibleId, 126017018, N'He despised the oath by breaking the covenant. Take note – he gave his promise and did all these things – he will not escape!'
EXEC add_BibleVerse @BibleId, 126017019, N'“‘Therefore this is what the sovereign Lord says: As surely as I live, I will certainly repay him for despising my oath and breaking my covenant!'
EXEC add_BibleVerse @BibleId, 126017020, N'I will throw my net over him and he will be caught in my snare; I will bring him to Babylon and judge him there because of the unfaithfulness he committed against me.'
EXEC add_BibleVerse @BibleId, 126017021, N'All the choice men among his troops will die by the sword and the survivors will be scattered to every wind. Then you will know that I, the Lord, have spoken!'
EXEC add_BibleVerse @BibleId, 126017022, N'“‘This is what the sovereign Lord says: “‘I will take a sprig from the lofty top of the cedar and plant it. I will pluck from the top one of its tender twigs; I myself will plant it on a high and lofty mountain.'
EXEC add_BibleVerse @BibleId, 126017023, N'I will plant it on a high mountain of Israel, and it will raise branches and produce fruit and become a beautiful cedar. Every bird will live under it; Every winged creature will live in the shade of its branches.'
EXEC add_BibleVerse @BibleId, 126017024, N'All the trees of the field will know that I am the Lord. I make the high tree low; I raise up the low tree. I make the green tree wither, and I make the dry tree sprout. I, the Lord, have spoken, and I will do it!’”'
EXEC add_BibleVerse @BibleId, 126018001, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126018002, N'“What do you mean by quoting this proverb concerning the land of Israel, “‘The fathers eat sour grapes And the children’s teeth become numb?’'
EXEC add_BibleVerse @BibleId, 126018003, N'“As surely as I live, declares the sovereign Lord, you will not quote this proverb in Israel anymore!'
EXEC add_BibleVerse @BibleId, 126018004, N'Indeed! All lives are mine – the life of the father as well as the life of the son is mine. The one who sins will die.'
EXEC add_BibleVerse @BibleId, 126018005, N'“Suppose a man is righteous. He practices what is just and right,'
EXEC add_BibleVerse @BibleId, 126018006, N'does not eat pagan sacrifices on the mountains or pray to the idols of the house of Israel, does not defile his neighbor’s wife, does not have sexual relations with a woman during her period,'
EXEC add_BibleVerse @BibleId, 126018007, N'does not oppress anyone, but gives the debtor back whatever was given in pledge, does not commit robbery, but gives his bread to the hungry and clothes the naked,'
EXEC add_BibleVerse @BibleId, 126018008, N'does not engage in usury or charge interest, but refrains from wrongdoing, promotes true justice between men,'
EXEC add_BibleVerse @BibleId, 126018009, N'and follows my statutes and observes my regulations by carrying them out. That man is righteous; he will certainly live, declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126018010, N'“Suppose such a man has a violent son who sheds blood and does any of these things mentioned previously'
EXEC add_BibleVerse @BibleId, 126018011, N'(though the father did not do any of them). He eats pagan sacrifices on the mountains, defiles his neighbor’s wife,'
EXEC add_BibleVerse @BibleId, 126018012, N'oppresses the poor and the needy, commits robbery, does not give back what was given in pledge, prays to idols, performs abominable acts,'
EXEC add_BibleVerse @BibleId, 126018013, N'engages in usury and charges interest. Will he live? He will not! Because he has done all these abominable deeds he will certainly die. He will bear the responsibility for his own death.'
EXEC add_BibleVerse @BibleId, 126018014, N'“But suppose he in turn has a son who notices all the sins his father commits, considers them, and does not follow his father’s example.'
EXEC add_BibleVerse @BibleId, 126018015, N'He does not eat pagan sacrifices on the mountains, does not pray to the idols of the house of Israel, does not defile his neighbor’s wife,'
EXEC add_BibleVerse @BibleId, 126018016, N'does not oppress anyone or keep what has been given in pledge, does not commit robbery, gives his food to the hungry, and clothes the naked,'
EXEC add_BibleVerse @BibleId, 126018017, N'refrains from wrongdoing, does not engage in usury or charge interest, carries out my regulations and follows my statutes. He will not die for his father’s iniquity; he will surely live.'
EXEC add_BibleVerse @BibleId, 126018018, N'As for his father, because he practices extortion, robs his brother, and does what is not good among his people, he will die for his iniquity.'
EXEC add_BibleVerse @BibleId, 126018019, N'“Yet you say, ‘Why should the son not suffer for his father’s iniquity?’ When the son does what is just and right, and observes all my statutes and carries them out, he will surely live.'
EXEC add_BibleVerse @BibleId, 126018020, N'The person who sins is the one who will die. A son will not suffer for his father’s iniquity, and a father will not suffer for his son’s iniquity; the righteous person will be judged according to his righteousness, and the wicked person according to his wickedness.'
EXEC add_BibleVerse @BibleId, 126018021, N'“But if the wicked person turns from all the sin he has committed and observes all my statutes and does what is just and right, he will surely live; he will not die.'
EXEC add_BibleVerse @BibleId, 126018022, N'None of the sins he has committed will be held against him; because of the righteousness he has done, he will live.'
EXEC add_BibleVerse @BibleId, 126018023, N'Do I actually delight in the death of the wicked, declares the sovereign Lord? Do I not prefer that he turn from his wicked conduct and live?'
EXEC add_BibleVerse @BibleId, 126018024, N'“But if a righteous man turns away from his righteousness and practices wrongdoing according to all the abominable practices the wicked carry out, will he live? All his righteous acts will not be remembered; because of the unfaithful acts he has done and the sin he has committed, he will die.'
EXEC add_BibleVerse @BibleId, 126018025, N'“Yet you say, ‘The Lord’s conduct is unjust!’ Hear, O house of Israel: Is my conduct unjust? Is it not your conduct that is unjust?'
EXEC add_BibleVerse @BibleId, 126018026, N'When a righteous person turns back from his righteousness and practices wrongdoing, he will die for it; because of the wrongdoing he has done, he will die.'
EXEC add_BibleVerse @BibleId, 126018027, N'When a wicked person turns from the wickedness he has committed and does what is just and right, he will preserve his life.'
EXEC add_BibleVerse @BibleId, 126018028, N'Because he considered and turned from all the sins he had done, he will surely live; he will not die.'
EXEC add_BibleVerse @BibleId, 126018029, N'Yet the house of Israel says, ‘The Lord’s conduct is unjust!’ Is my conduct unjust, O house of Israel? Is it not your conduct that is unjust?'
EXEC add_BibleVerse @BibleId, 126018030, N'“Therefore I will judge each person according to his conduct, O house of Israel, declares the sovereign Lord. Repent and turn from all your wickedness; then it will not be an obstacle leading to iniquity.'
EXEC add_BibleVerse @BibleId, 126018031, N'Throw away all your sins you have committed and fashion yourselves a new heart and a new spirit! Why should you die, O house of Israel?'
EXEC add_BibleVerse @BibleId, 126018032, N'For I take no delight in the death of anyone, declares the sovereign Lord. Repent and live!'
EXEC add_BibleVerse @BibleId, 126019001, N'“And you, sing a lament for the princes of Israel,'
EXEC add_BibleVerse @BibleId, 126019002, N'and say: “‘What a lioness was your mother among the lions! She lay among young lions; she reared her cubs.'
EXEC add_BibleVerse @BibleId, 126019003, N'She reared one of her cubs; he became a young lion. He learned to tear prey; he devoured people.'
EXEC add_BibleVerse @BibleId, 126019004, N'The nations heard about him; he was trapped in their pit. They brought him with hooks to the land of Egypt.'
EXEC add_BibleVerse @BibleId, 126019005, N'“‘When she realized that she waited in vain, her hope was lost. She took another of her cubs and made him a young lion.'
EXEC add_BibleVerse @BibleId, 126019006, N'He walked about among the lions; he became a young lion. He learned to tear prey; he devoured people.'
EXEC add_BibleVerse @BibleId, 126019007, N'He broke down their strongholds and devastated their cities. The land and everything in it was frightened at the sound of his roaring.'
EXEC add_BibleVerse @BibleId, 126019008, N'The nations – the surrounding regions – attacked him. They threw their net over him; he was caught in their pit.'
EXEC add_BibleVerse @BibleId, 126019009, N'They put him in a collar with hooks; they brought him to the king of Babylon; they brought him to prison so that his voice would not be heard any longer on the mountains of Israel.'
EXEC add_BibleVerse @BibleId, 126019010, N'“‘Your mother was like a vine in your vineyard, planted by water. It was fruitful and full of branches because it was well-watered.'
EXEC add_BibleVerse @BibleId, 126019011, N'Its boughs were strong, fit for rulers’ scepters; it reached up into the clouds. It stood out because of its height and its many branches.'
EXEC add_BibleVerse @BibleId, 126019012, N'But it was plucked up in anger; it was thrown down to the ground. The east wind dried up its fruit; its strong branches broke off and withered – a fire consumed them.'
EXEC add_BibleVerse @BibleId, 126019013, N'Now it is planted in the wilderness, in a dry and thirsty land.'
EXEC add_BibleVerse @BibleId, 126019014, N'A fire has gone out from its branch; it has consumed its shoot and its fruit. No strong branch was left in it, nor a scepter to rule.’ This is a lament song, and has become a lament song.”'
EXEC add_BibleVerse @BibleId, 126020001, N'In the seventh year, in the fifth month, on the tenth of the month, some of the elders of Israel came to seek the Lord, and they sat down in front of me.'
EXEC add_BibleVerse @BibleId, 126020002, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126020003, N'“Son of man, speak to the elders of Israel, and tell them: ‘This is what the sovereign Lord says: Are you coming to seek me? As surely as I live, I will not allow you to seek me, declares the sovereign Lord.’'
EXEC add_BibleVerse @BibleId, 126020004, N'“Are you willing to pronounce judgment? Are you willing to pronounce judgment, son of man? Then confront them with the abominable practices of their fathers,'
EXEC add_BibleVerse @BibleId, 126020005, N'and say to them: “‘This is what the sovereign Lord says: On the day I chose Israel I swore to the descendants of the house of Jacob and made myself known to them in the land of Egypt. I swore to them, “I am the Lord your God.”'
EXEC add_BibleVerse @BibleId, 126020006, N'On that day I swore to bring them out of the land of Egypt to a land which I had picked out for them, a land flowing with milk and honey, the most beautiful of all lands.'
EXEC add_BibleVerse @BibleId, 126020007, N'I said to them, “Each of you must get rid of the detestable idols you keep before you, and do not defile yourselves with the idols of Egypt; I am the Lord your God.”'
EXEC add_BibleVerse @BibleId, 126020008, N'But they rebelled against me, and refused to listen to me; no one got rid of their detestable idols, nor did they abandon the idols of Egypt. Then I decided to pour out my rage on them and fully vent my anger against them in the midst of the land of Egypt.'
EXEC add_BibleVerse @BibleId, 126020009, N'I acted for the sake of my reputation, so that I would not be profaned before the nations among whom they lived, before whom I revealed myself by bringing them out of the land of Egypt.'
EXEC add_BibleVerse @BibleId, 126020010, N'“‘So I brought them out of the land of Egypt and led them to the wilderness.'
EXEC add_BibleVerse @BibleId, 126020011, N'I gave them my statutes and revealed my regulations to them. The one who carries them out will live by them!'
EXEC add_BibleVerse @BibleId, 126020012, N'I also gave them my Sabbaths as a reminder of our relationship, so that they would know that I, the Lord, sanctify them.'
EXEC add_BibleVerse @BibleId, 126020013, N'But the house of Israel rebelled against me in the wilderness; they did not follow my statutes and they rejected my regulations (the one who obeys them will live by them), and they utterly desecrated my Sabbaths. So I decided to pour out my rage on them in the wilderness and destroy them.'
EXEC add_BibleVerse @BibleId, 126020014, N'I acted for the sake of my reputation, so that I would not be profaned before the nations in whose sight I had brought them out.'
EXEC add_BibleVerse @BibleId, 126020015, N'I also swore to them in the wilderness that I would not bring them to the land I had given them – a land flowing with milk and honey, the most beautiful of all lands.'
EXEC add_BibleVerse @BibleId, 126020016, N'I did this because they rejected my regulations, did not follow my statutes, and desecrated my Sabbaths; for their hearts followed their idols.'
EXEC add_BibleVerse @BibleId, 126020017, N'Yet I had pity on them and did not destroy them, so I did not make an end of them in the wilderness.'
EXEC add_BibleVerse @BibleId, 126020018, N'“‘But I said to their children in the wilderness, “Do not follow the practices of your fathers; do not observe their regulations, nor defile yourselves with their idols.'
EXEC add_BibleVerse @BibleId, 126020019, N'I am the Lord your God; follow my statutes, observe my regulations, and carry them out.'
EXEC add_BibleVerse @BibleId, 126020020, N'Treat my Sabbaths as holy and they will be a reminder of our relationship, and then you will know that I am the Lord your God.”'
EXEC add_BibleVerse @BibleId, 126020021, N'“‘But the children rebelled against me, did not follow my statutes, did not observe my regulations by carrying them out (the one who obeys them will live by them), and desecrated my Sabbaths. I decided to pour out my rage on them and fully vent my anger against them in the wilderness.'
EXEC add_BibleVerse @BibleId, 126020022, N'But I refrained from doing so, and acted instead for the sake of my reputation, so that I would not be profaned before the nations in whose sight I had brought them out.'
EXEC add_BibleVerse @BibleId, 126020023, N'I also swore to them in the wilderness that I would scatter them among the nations and disperse them throughout the lands.'
EXEC add_BibleVerse @BibleId, 126020024, N'I did this because they did not observe my regulations, they rejected my statutes, they desecrated my Sabbaths, and their eyes were fixed on their fathers’ idols.'
EXEC add_BibleVerse @BibleId, 126020025, N'I also gave them decrees which were not good and regulations by which they could not live.'
EXEC add_BibleVerse @BibleId, 126020026, N'I declared them to be defiled because of their sacrifices – they caused all their first born to pass through the fire – so that I would devastate them, so that they will know that I am the Lord.’'
EXEC add_BibleVerse @BibleId, 126020027, N'“Therefore, speak to the house of Israel, son of man, and tell them, ‘This is what the sovereign Lord says: In this way too your fathers blasphemed me when they were unfaithful to me.'
EXEC add_BibleVerse @BibleId, 126020028, N'I brought them to the land which I swore to give them, but whenever they saw any high hill or leafy tree, they offered their sacrifices there and presented the offerings that provoke me to anger. They offered their soothing aroma there and poured out their drink offerings.'
EXEC add_BibleVerse @BibleId, 126020029, N'So I said to them, What is this high place you go to?’” (So it is called “High Place” to this day.)'
EXEC add_BibleVerse @BibleId, 126020030, N'“Therefore say to the house of Israel, ‘This is what the sovereign Lord says: Will you defile yourselves like your fathers and engage in prostitution with detestable idols?'
EXEC add_BibleVerse @BibleId, 126020031, N'When you present your sacrifices – when you make your sons pass through the fire – you defile yourselves with all your idols to this very day. Will I allow you to seek me, O house of Israel? As surely as I live, declares the sovereign Lord, I will not allow you to seek me!'
EXEC add_BibleVerse @BibleId, 126020032, N'“‘What you plan will never happen. You say, “We will be like the nations, like the clans of the lands, who serve gods of wood and stone.”'
EXEC add_BibleVerse @BibleId, 126020033, N'As surely as I live, declares the sovereign Lord, with a powerful hand and an outstretched arm, and with an outpouring of rage, I will be king over you.'
EXEC add_BibleVerse @BibleId, 126020034, N'I will bring you out from the nations, and will gather you from the lands where you are scattered, with a powerful hand and an outstretched arm and with an outpouring of rage!'
EXEC add_BibleVerse @BibleId, 126020035, N'I will bring you into the wilderness of the nations, and there I will enter into judgment with you face to face.'
EXEC add_BibleVerse @BibleId, 126020036, N'Just as I entered into judgment with your fathers in the wilderness of the land of Egypt, so I will enter into judgment with you, declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126020037, N'I will make you pass under the shepherd’s staff, and I will bring you into the bond of the covenant.'
EXEC add_BibleVerse @BibleId, 126020038, N'I will eliminate from among you the rebels and those who revolt against me. I will bring them out from the land where they have been residing, but they will not come to the land of Israel. Then you will know that I am the Lord.'
EXEC add_BibleVerse @BibleId, 126020039, N'“‘As for you, O house of Israel, this is what the sovereign Lord says: Each of you go and serve your idols, if you will not listen to me. But my holy name will not be profaned again by your sacrifices and your idols.'
EXEC add_BibleVerse @BibleId, 126020040, N'For there on my holy mountain, the high mountain of Israel, declares the sovereign Lord, all the house of Israel will serve me, all of them in the land. I will accept them there, and there I will seek your contributions and your choice gifts, with all your holy things.'
EXEC add_BibleVerse @BibleId, 126020041, N'When I bring you out from the nations and gather you from the lands where you are scattered, I will accept you along with your soothing aroma. I will display my holiness among you in the sight of the nations.'
EXEC add_BibleVerse @BibleId, 126020042, N'Then you will know that I am the Lord when I bring you to the land of Israel, to the land I swore to give to your fathers.'
EXEC add_BibleVerse @BibleId, 126020043, N'And there you will remember your conduct and all your deeds by which you defiled yourselves. You will despise yourselves because of all the evil deeds you have done.'
EXEC add_BibleVerse @BibleId, 126020044, N'Then you will know that I am the Lord, when I deal with you for the sake of my reputation and not according to your wicked conduct and corrupt deeds, O house of Israel, declares the sovereign Lord.’”'
EXEC add_BibleVerse @BibleId, 126020045, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126020046, N'“Son of man, turn toward the south, and speak out against the south. Prophesy against the open scrub land of the Negev,'
EXEC add_BibleVerse @BibleId, 126020047, N'and say to the scrub land of the Negev, ‘Hear the word of the Lord: This is what the sovereign Lord says: Look here, I am about to start a fire in you, and it will devour every green tree and every dry tree in you. The flaming fire will not be extinguished, and the whole surface of the ground from the Negev to the north will be scorched by it.'
EXEC add_BibleVerse @BibleId, 126020048, N'And everyone will see that I, the Lord, have burned it; it will not be extinguished.’”'
EXEC add_BibleVerse @BibleId, 126020049, N'Then I said, “O sovereign Lord! They are saying of me, ‘Does he not simply speak in eloquent figures of speech?’”'
EXEC add_BibleVerse @BibleId, 126021001, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126021002, N'“Son of man, turn toward Jerusalem and speak out against the sanctuaries. Prophesy against the land of Israel'
EXEC add_BibleVerse @BibleId, 126021003, N'and say to them, ‘This is what the Lord says: Look, I am against you. I will draw my sword from its sheath and cut off from you both the righteous and the wicked.'
EXEC add_BibleVerse @BibleId, 126021004, N'Because I will cut off from you both the righteous and the wicked, my sword will go out from its sheath against everyone from the south to the north.'
EXEC add_BibleVerse @BibleId, 126021005, N'Then everyone will know that I am the Lord, who drew my sword from its sheath – it will not be sheathed again!’'
EXEC add_BibleVerse @BibleId, 126021006, N'“And you, son of man, groan with an aching heart and bitterness; groan before their eyes.'
EXEC add_BibleVerse @BibleId, 126021007, N'When they ask you, ‘Why are you groaning?’ you will reply, ‘Because of the report that has come. Every heart will melt with fear and every hand will be limp; everyone will faint and every knee will be wet with urine.’ Pay attention – it is coming and it will happen, declares the sovereign Lord.”'
EXEC add_BibleVerse @BibleId, 126021008, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126021009, N'“Son of man, prophesy and say: ‘This is what the Lord says: “‘A sword, a sword is sharpened, and also polished.'
EXEC add_BibleVerse @BibleId, 126021010, N'It is sharpened for slaughter, it is polished to flash like lightning! “‘Should we rejoice in the scepter of my son? No! The sword despises every tree!'
EXEC add_BibleVerse @BibleId, 126021011, N'“‘He gave it to be polished, to be grasped in the hand – the sword is sharpened, it is polished – giving it into the hand of the executioner.'
EXEC add_BibleVerse @BibleId, 126021012, N'Cry out and moan, son of man, for it is wielded against my people; against all the princes of Israel. They are delivered up to the sword, along with my people. Therefore, strike your thigh.'
EXEC add_BibleVerse @BibleId, 126021013, N'“‘For testing will come, and what will happen when the scepter, which the sword despises, is no more? declares the sovereign Lord.’'
EXEC add_BibleVerse @BibleId, 126021014, N'“And you, son of man, prophesy, and clap your hands together. Let the sword strike twice, even three times! It is a sword for slaughter, a sword for the great slaughter surrounding them.'
EXEC add_BibleVerse @BibleId, 126021015, N'So hearts melt with fear and many stumble. At all their gates I have stationed the sword for slaughter. Ah! It is made to flash, it is drawn for slaughter!'
EXEC add_BibleVerse @BibleId, 126021016, N'Cut sharply on the right! Swing to the left, wherever your edge is appointed to strike.'
EXEC add_BibleVerse @BibleId, 126021017, N'I too will clap my hands together, I will exhaust my rage; I the Lord have spoken.”'
EXEC add_BibleVerse @BibleId, 126021018, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126021019, N'“You, son of man, mark out two routes for the king of Babylon’s sword to take; both of them will originate in a single land. Make a signpost and put it at the beginning of the road leading to the city.'
EXEC add_BibleVerse @BibleId, 126021020, N'Mark out the routes for the sword to take: “Rabbah of the Ammonites” and “Judah with Jerusalem in it.”'
EXEC add_BibleVerse @BibleId, 126021021, N'For the king of Babylon stands at the fork in the road at the head of the two routes. He looks for omens: He shakes arrows, he consults idols, he examines animal livers.'
EXEC add_BibleVerse @BibleId, 126021022, N'Into his right hand comes the portent for Jerusalem – to set up battering rams, to give the signal for slaughter, to shout out the battle cry, to set up battering rams against the gates, to erect a siege ramp, to build a siege wall.'
EXEC add_BibleVerse @BibleId, 126021023, N'But those in Jerusalem will view it as a false omen. They have sworn solemn oaths, but the king of Babylon will accuse them of violations in order to seize them.'
EXEC add_BibleVerse @BibleId, 126021024, N'“Therefore this is what the sovereign Lord says: ‘Because you have brought up your own guilt by uncovering your transgressions and revealing your sins through all your actions, for this reason you will be taken by force.'
EXEC add_BibleVerse @BibleId, 126021025, N'“‘As for you, profane and wicked prince of Israel, whose day has come, the time of final punishment,'
EXEC add_BibleVerse @BibleId, 126021026, N'this is what the sovereign Lord says: Tear off the turban, take off the crown! Things must change! Exalt the lowly, bring down the proud!'
EXEC add_BibleVerse @BibleId, 126021027, N'A total ruin I will make it! It will come to an end when the one arrives to whom I have assigned judgment.’'
EXEC add_BibleVerse @BibleId, 126021028, N'“As for you, son of man, prophesy and say, ‘This is what the sovereign Lord says concerning the Ammonites and their coming humiliation; say: “‘A sword, a sword drawn for slaughter, polished to consume, to flash like lightning –'
EXEC add_BibleVerse @BibleId, 126021029, N'while seeing false visions for you and reading lying omens for you – to place that sword on the necks of the profane wicked, whose day has come, the time of final punishment.'
EXEC add_BibleVerse @BibleId, 126021030, N'Return it to its sheath! In the place where you were created, in your native land, I will judge you.'
EXEC add_BibleVerse @BibleId, 126021031, N'I will pour out my anger on you; the fire of my fury I will blow on you. I will hand you over to brutal men, who are skilled in destruction.'
EXEC add_BibleVerse @BibleId, 126021032, N'You will become fuel for the fire – your blood will stain the middle of the land; you will no longer be remembered, for I, the Lord, have spoken.’”'
EXEC add_BibleVerse @BibleId, 126022001, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126022002, N'“As for you, son of man, are you willing to pronounce judgment, are you willing to pronounce judgment on the bloody city? Then confront her with all her abominable deeds!'
EXEC add_BibleVerse @BibleId, 126022003, N'Then say, ‘This is what the sovereign Lord says: O city, who spills blood within herself (which brings on her doom), and who makes herself idols (which results in impurity),'
EXEC add_BibleVerse @BibleId, 126022004, N'you are guilty because of the blood you shed and defiled by the idols you made. You have hastened the day of your doom; the end of your years has come. Therefore I will make you an object of scorn to the nations, an object to be mocked by all lands.'
EXEC add_BibleVerse @BibleId, 126022005, N'Those both near and far from you will mock you, you with your bad reputation, full of turmoil.'
EXEC add_BibleVerse @BibleId, 126022006, N'“‘See how each of the princes of Israel living within you has used his authority to shed blood.'
EXEC add_BibleVerse @BibleId, 126022007, N'They have treated father and mother with contempt within you; they have oppressed the foreigner among you; they have wronged the orphan and the widow within you.'
EXEC add_BibleVerse @BibleId, 126022008, N'You have despised my holy things and desecrated my Sabbaths!'
EXEC add_BibleVerse @BibleId, 126022009, N'Slanderous men shed blood within you. Those who live within you eat pagan sacrifices on the mountains; they commit obscene acts among you.'
EXEC add_BibleVerse @BibleId, 126022010, N'They have sex with their father’s wife within you; they violate women during their menstrual period within you.'
EXEC add_BibleVerse @BibleId, 126022011, N'One commits an abominable act with his neighbor’s wife; another obscenely defiles his daughter-in-law; another violates his sister – his father’s daughter – within you.'
EXEC add_BibleVerse @BibleId, 126022012, N'They take bribes within you to shed blood. You engage in usury and charge interest; you extort money from your neighbors. You have forgotten me, declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126022013, N'“‘See, I strike my hands together at the dishonest profit you have made, and at the bloodshed they have done among you.'
EXEC add_BibleVerse @BibleId, 126022014, N'Can your heart endure, or can your hands be strong when I deal with you? I, the Lord, have spoken, and I will do it!'
EXEC add_BibleVerse @BibleId, 126022015, N'I will scatter you among the nations and disperse you among various countries; I will remove your impurity from you.'
EXEC add_BibleVerse @BibleId, 126022016, N'You will be profaned within yourself in the sight of the nations; then you will know that I am the Lord.’”'
EXEC add_BibleVerse @BibleId, 126022017, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126022018, N'“Son of man, the house of Israel has become slag to me. All of them are like bronze, tin, iron, and lead in the furnace; they are the worthless slag of silver.'
EXEC add_BibleVerse @BibleId, 126022019, N'Therefore this is what the sovereign Lord says: ‘Because all of you have become slag, look out! – I am about to gather you in the middle of Jerusalem.'
EXEC add_BibleVerse @BibleId, 126022020, N'As silver, bronze, iron, lead, and tin are gathered in a furnace so that the fire can melt them, so I will gather you in my anger and in my rage. I will deposit you there and melt you.'
EXEC add_BibleVerse @BibleId, 126022021, N'I will gather you and blow on you with the fire of my fury, and you will be melted in it.'
EXEC add_BibleVerse @BibleId, 126022022, N'As silver is melted in a furnace, so you will be melted in it, and you will know that I, the Lord, have poured out my anger on you.’”'
EXEC add_BibleVerse @BibleId, 126022023, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126022024, N'“Son of man, say to her: ‘You are a land that receives no rain or showers in the day of my anger.’'
EXEC add_BibleVerse @BibleId, 126022025, N'Her princes within her are like a roaring lion tearing its prey; they have devoured lives. They take away riches and valuable things; they have made many women widows within it.'
EXEC add_BibleVerse @BibleId, 126022026, N'Her priests abuse my law and have desecrated my holy things. They do not distinguish between the holy and the profane, or recognize any distinction between the unclean and the clean. They ignore my Sabbaths and I am profaned in their midst.'
EXEC add_BibleVerse @BibleId, 126022027, N'Her officials are like wolves in her midst rending their prey – shedding blood and destroying lives – so they can get dishonest profit.'
EXEC add_BibleVerse @BibleId, 126022028, N'Her prophets coat their messages with whitewash. They see false visions and announce lying omens for them, saying, ‘This is what the sovereign Lord says,’ when the Lord has not spoken.'
EXEC add_BibleVerse @BibleId, 126022029, N'The people of the land have practiced extortion and committed robbery. They have wronged the poor and needy; they have oppressed the foreigner who lives among them and denied them justice.'
EXEC add_BibleVerse @BibleId, 126022030, N'“I looked for a man from among them who would repair the wall and stand in the gap before me on behalf of the land, so that I would not destroy it, but I found no one.'
EXEC add_BibleVerse @BibleId, 126022031, N'So I have poured my anger on them, and destroyed them with the fire of my fury. I hereby repay them for what they have done, declares the sovereign Lord.”'
EXEC add_BibleVerse @BibleId, 126023001, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126023002, N'“Son of man, there were two women who were daughters of the same mother.'
EXEC add_BibleVerse @BibleId, 126023003, N'They engaged in prostitution in Egypt; in their youth they engaged in prostitution. Their breasts were squeezed there; lovers fondled their virgin nipples there.'
EXEC add_BibleVerse @BibleId, 126023004, N'Oholah was the name of the older and Oholibah the name of her younger sister. They became mine, and gave birth to sons and daughters. Oholah is Samaria and Oholibah is Jerusalem.'
EXEC add_BibleVerse @BibleId, 126023005, N'“Oholah engaged in prostitution while she was mine. She lusted after her lovers, the Assyrians – warriors'
EXEC add_BibleVerse @BibleId, 126023006, N'clothed in blue, governors and officials, all of them desirable young men, horsemen riding on horses.'
EXEC add_BibleVerse @BibleId, 126023007, N'She bestowed her sexual favors on them; all of them were the choicest young men of Assyria. She defiled herself with all whom she desired – with all their idols.'
EXEC add_BibleVerse @BibleId, 126023008, N'She did not abandon the prostitution she had practiced in Egypt; for in her youth men had sex with her, fondled her virgin breasts, and ravished her.'
EXEC add_BibleVerse @BibleId, 126023009, N'Therefore I handed her over to her lovers, the Assyrians for whom she lusted.'
EXEC add_BibleVerse @BibleId, 126023010, N'They exposed her nakedness, seized her sons and daughters, and killed her with the sword. She became notorious among women, and they executed judgments against her.'
EXEC add_BibleVerse @BibleId, 126023011, N'“Her sister Oholibah watched this, but she became more corrupt in her lust than her sister had been, and her acts of prostitution were more numerous than those of her sister.'
EXEC add_BibleVerse @BibleId, 126023012, N'She lusted after the Assyrians – governors and officials, warriors in full armor, horsemen riding on horses, all of them desirable young men.'
EXEC add_BibleVerse @BibleId, 126023013, N'I saw that she was defiled; both of them followed the same path.'
EXEC add_BibleVerse @BibleId, 126023014, N'But she increased her prostitution. She saw men carved on the wall, images of the Chaldeans carved in bright red,'
EXEC add_BibleVerse @BibleId, 126023015, N'wearing belts on their waists and flowing turbans on their heads, all of them looking like officers, the image of Babylonians whose native land is Chaldea.'
EXEC add_BibleVerse @BibleId, 126023016, N'When she saw them, she lusted after them and sent messengers to them in Chaldea.'
EXEC add_BibleVerse @BibleId, 126023017, N'The Babylonians crawled into bed with her. They defiled her with their lust; after she was defiled by them, she became disgusted with them.'
EXEC add_BibleVerse @BibleId, 126023018, N'When she lustfully exposed her nakedness, I was disgusted with her, just as I had been disgusted with her sister.'
EXEC add_BibleVerse @BibleId, 126023019, N'Yet she increased her prostitution, remembering the days of her youth when she engaged in prostitution in the land of Egypt.'
EXEC add_BibleVerse @BibleId, 126023020, N'She lusted after their genitals – as large as those of donkeys, and their seminal emission was as strong as that of stallions.'
EXEC add_BibleVerse @BibleId, 126023021, N'This is how you assessed the obscene conduct of your youth, when the Egyptians fondled your nipples and squeezed your young breasts.'
EXEC add_BibleVerse @BibleId, 126023022, N'“Therefore, Oholibah, this is what the sovereign Lord says: Look here, I am about to stir up against you the lovers with whom you were disgusted; I will bring them against you from every side:'
EXEC add_BibleVerse @BibleId, 126023023, N'the Babylonians and all the Chaldeans, Pekod, Shoa, and Koa, and all the Assyrians with them, desirable young men, all of them governors and officials, officers and nobles, all of them riding on horses.'
EXEC add_BibleVerse @BibleId, 126023024, N'They will attack you with weapons, chariots, wagons, and with a huge army; they will array themselves against you on every side with large shields, small shields, and helmets. I will assign them the task of judgment; they will punish you according to their laws.'
EXEC add_BibleVerse @BibleId, 126023025, N'I will direct my jealous anger against you, and they will deal with you in rage. They will cut off your nose and your ears, and your survivors will die by the sword. They will seize your sons and daughters, and your survivors will be consumed by fire.'
EXEC add_BibleVerse @BibleId, 126023026, N'They will strip your clothes off you and take away your beautiful jewelry.'
EXEC add_BibleVerse @BibleId, 126023027, N'So I will put an end to your obscene conduct and your prostitution which you have practiced in the land of Egypt. You will not seek their help or remember Egypt anymore.'
EXEC add_BibleVerse @BibleId, 126023028, N'“For this is what the sovereign Lord says: Look here, I am about to deliver you over to those whom you hate, to those with whom you were disgusted.'
EXEC add_BibleVerse @BibleId, 126023029, N'They will treat you with hatred, take away all you have labored for, and leave you naked and bare. Your nakedness will be exposed, just as when you engaged in prostitution and obscene conduct.'
EXEC add_BibleVerse @BibleId, 126023030, N'I will do these things to you because you engaged in prostitution with the nations, polluting yourself with their idols.'
EXEC add_BibleVerse @BibleId, 126023031, N'You have followed the ways of your sister, so I will place her cup of judgment in your hand.'
EXEC add_BibleVerse @BibleId, 126023032, N'“This is what the sovereign Lord says: “You will drink your sister’s deep and wide cup; you will be scorned and derided, for it holds a great deal.'
EXEC add_BibleVerse @BibleId, 126023033, N'You will be overcome by drunkenness and sorrow. The cup of your sister Samaria is a cup of horror and desolation.'
EXEC add_BibleVerse @BibleId, 126023034, N'You will drain it dry, gnaw its pieces, and tear out your breasts, for I have spoken, declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126023035, N'“Therefore this is what the sovereign Lord says: Because you have forgotten me and completely disregarded me, you must bear now the punishment for your obscene conduct and prostitution.”'
EXEC add_BibleVerse @BibleId, 126023036, N'The Lord said to me: “Son of man, are you willing to pronounce judgment on Oholah and Oholibah? Then declare to them their abominable deeds!'
EXEC add_BibleVerse @BibleId, 126023037, N'For they have committed adultery and blood is on their hands. They have committed adultery with their idols, and their sons, whom they bore to me, they have passed through the fire as food to their idols.'
EXEC add_BibleVerse @BibleId, 126023038, N'Moreover, they have done this to me: In the very same day they desecrated my sanctuary and profaned my Sabbaths.'
EXEC add_BibleVerse @BibleId, 126023039, N'On the same day they slaughtered their sons for their idols, they came to my sanctuary to desecrate it. This is what they have done in the middle of my house.'
EXEC add_BibleVerse @BibleId, 126023040, N'“They even sent for men from far away; when the messenger arrived, those men set out. For them you bathed, painted your eyes, and decorated yourself with jewelry.'
EXEC add_BibleVerse @BibleId, 126023041, N'You sat on a magnificent couch, with a table arranged in front of it where you placed my incense and my olive oil.'
EXEC add_BibleVerse @BibleId, 126023042, N'The sound of a carefree crowd accompanied her, including all kinds of men; even Sabeans were brought from the desert. The sisters put bracelets on their wrists and beautiful crowns on their heads.'
EXEC add_BibleVerse @BibleId, 126023043, N'Then I said about the one worn out by adultery, ‘Now they will commit immoral acts with her.’'
EXEC add_BibleVerse @BibleId, 126023044, N'They had sex with her as one does with a prostitute. In this way they had sex with Oholah and Oholibah, promiscuous women.'
EXEC add_BibleVerse @BibleId, 126023045, N'But upright men will punish them appropriately for their adultery and bloodshed, because they are adulteresses and blood is on their hands.'
EXEC add_BibleVerse @BibleId, 126023046, N'“For this is what the sovereign Lord says: Bring up an army against them and subject them to terror and plunder.'
EXEC add_BibleVerse @BibleId, 126023047, N'That army will pelt them with stones and slash them with their swords; they will kill their sons and daughters and burn their houses.'
EXEC add_BibleVerse @BibleId, 126023048, N'I will put an end to the obscene conduct in the land; all the women will learn a lesson from this and not engage in obscene conduct.'
EXEC add_BibleVerse @BibleId, 126023049, N'They will repay you for your obscene conduct, and you will be punished for idol worship. Then you will know that I am the sovereign Lord.”'
EXEC add_BibleVerse @BibleId, 126024001, N'The word of the Lord came to me in the ninth year, in the tenth month, on the tenth day of the month :'
EXEC add_BibleVerse @BibleId, 126024002, N'“Son of man, write down the name of this day, this very day. The king of Babylon has laid siege to Jerusalem this very day.'
EXEC add_BibleVerse @BibleId, 126024003, N'Recite a proverb to this rebellious house and say to them, ‘This is what the sovereign Lord says: “‘Set on the pot, set it on, pour water in it too;'
EXEC add_BibleVerse @BibleId, 126024004, N'add the pieces of meat to it, every good piece, the thigh and the shoulder; fill it with choice bones.'
EXEC add_BibleVerse @BibleId, 126024005, N'Take the choice bone of the flock, heap up bones under it; boil rapidly, and boil its bones in it.'
EXEC add_BibleVerse @BibleId, 126024006, N'“‘Therefore this is what the sovereign Lord says: Woe to the city of bloodshed, the pot whose rot is in it, whose rot has not been removed from it! Empty it piece by piece. No lot has fallen on it.'
EXEC add_BibleVerse @BibleId, 126024007, N'For her blood was in it; she poured it on an exposed rock; she did not pour it on the ground to cover it up with dust.'
EXEC add_BibleVerse @BibleId, 126024008, N'To arouse anger, to take vengeance, I have placed her blood on an exposed rock so that it cannot be covered up.'
EXEC add_BibleVerse @BibleId, 126024009, N'“‘Therefore this is what the sovereign Lord says: Woe to the city of bloodshed! I will also make the pile high.'
EXEC add_BibleVerse @BibleId, 126024010, N'Pile up the bones, kindle the fire; cook the meat well, mix in the spices, let the bones be charred.'
EXEC add_BibleVerse @BibleId, 126024011, N'Set the empty pot on the coals, until it becomes hot and its copper glows, until its uncleanness melts within it and its rot is consumed.'
EXEC add_BibleVerse @BibleId, 126024012, N'It has tried my patience; yet its thick rot is not removed from it. Subject its rot to the fire!'
EXEC add_BibleVerse @BibleId, 126024013, N'You mix uncleanness with obscene conduct. I tried to cleanse you, but you are not clean. You will not be cleansed from your uncleanness until I have exhausted my anger on you.'
EXEC add_BibleVerse @BibleId, 126024014, N'“‘I the Lord have spoken; judgment is coming and I will act! I will not relent, or show pity, or be sorry! I will judge you according to your conduct and your deeds, declares the sovereign Lord.’”'
EXEC add_BibleVerse @BibleId, 126024015, N'The word of Lord came to me:'
EXEC add_BibleVerse @BibleId, 126024016, N'“Son of man, realize that I am about to take the delight of your eyes away from you with a jolt, but you must not mourn or weep or shed tears.'
EXEC add_BibleVerse @BibleId, 126024017, N'Groan in silence for the dead, but do not perform mourning rites. Bind on your turban and put your sandals on your feet. Do not cover your lip and do not eat food brought by others.”'
EXEC add_BibleVerse @BibleId, 126024018, N'So I spoke to the people in the morning, and my wife died in the evening. In the morning I acted just as I was commanded.'
EXEC add_BibleVerse @BibleId, 126024019, N'Then the people said to me, “Will you not tell us what these things you are doing mean for us?”'
EXEC add_BibleVerse @BibleId, 126024020, N'So I said to them: “The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126024021, N'Say to the house of Israel, ‘This is what the sovereign Lord says: Realize I am about to desecrate my sanctuary – the source of your confident pride, the object in which your eyes delight, and your life’s passion. Your very own sons and daughters whom you have left behind will die by the sword.'
EXEC add_BibleVerse @BibleId, 126024022, N'Then you will do as I have done: You will not cover your lip or eat food brought by others.'
EXEC add_BibleVerse @BibleId, 126024023, N'Your turbans will be on your heads and your sandals on your feet; you will not mourn or weep, but you will rot for your iniquities and groan among yourselves.'
EXEC add_BibleVerse @BibleId, 126024024, N'Ezekiel will be an object lesson for you; you will do all that he has done. When it happens, then you will know that I am the sovereign Lord.’'
EXEC add_BibleVerse @BibleId, 126024025, N'“And you, son of man, this is what will happen on the day I take from them their stronghold – their beautiful source of joy, the object in which their eyes delight, and the main concern of their lives, as well as their sons and daughters:'
EXEC add_BibleVerse @BibleId, 126024026, N'On that day a fugitive will come to you to report the news.'
EXEC add_BibleVerse @BibleId, 126024027, N'On that day you will be able to speak again; you will talk with the fugitive and be silent no longer. You will be an object lesson for them, and they will know that I am the Lord.”'
EXEC add_BibleVerse @BibleId, 126025001, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126025002, N'“Son of man, turn toward the Ammonites and prophesy against them.'
EXEC add_BibleVerse @BibleId, 126025003, N'Say to the Ammonites, ‘Hear the word of the sovereign Lord: This is what the sovereign Lord says: You said “Aha!” about my sanctuary when it was desecrated, about the land of Israel when it was made desolate, and about the house of Judah when they went into exile.'
EXEC add_BibleVerse @BibleId, 126025004, N'So take note, I am about to make you slaves of the tribes of the east. They will make camps among you and pitch their tents among you. They will eat your fruit and drink your milk.'
EXEC add_BibleVerse @BibleId, 126025005, N'I will make Rabbah a pasture for camels and Ammon a resting place for sheep. Then you will know that I am the Lord.'
EXEC add_BibleVerse @BibleId, 126025006, N'For this is what the sovereign Lord says: Because you clapped your hands, stamped your feet, and rejoiced with intense scorn over the land of Israel,'
EXEC add_BibleVerse @BibleId, 126025007, N'take note, I have stretched out my hand against you, and I will hand you over as plunder to the nations. I will cut you off from the peoples and make you perish from the lands. I will destroy you; then you will know that I am the Lord.’”'
EXEC add_BibleVerse @BibleId, 126025008, N'“This is what the sovereign Lord says: ‘Moab and Seir say, “Look, the house of Judah is like all the other nations.”'
EXEC add_BibleVerse @BibleId, 126025009, N'So look, I am about to open up Moab’s flank, eliminating the cities, including its frontier cities, the beauty of the land – Beth Jeshimoth, Baal Meon, and Kiriathaim.'
EXEC add_BibleVerse @BibleId, 126025010, N'I will hand it over, along with the Ammonites, to the tribes of the east, so that the Ammonites will no longer be remembered among the nations.'
EXEC add_BibleVerse @BibleId, 126025011, N'I will execute judgments against Moab. Then they will know that I am the Lord.’”'
EXEC add_BibleVerse @BibleId, 126025012, N'“This is what the sovereign Lord says: ‘Edom has taken vengeance against the house of Judah; they have made themselves fully culpable by taking vengeance on them.'
EXEC add_BibleVerse @BibleId, 126025013, N'So this is what the sovereign Lord says: I will stretch out my hand against Edom, and I will kill the people and animals within her, and I will make her desolate; from Teman to Dedan they will die by the sword.'
EXEC add_BibleVerse @BibleId, 126025014, N'I will exact my vengeance upon Edom by the hand of my people Israel. They will carry out in Edom my anger and rage; they will experience my vengeance, declares the sovereign Lord.’”'
EXEC add_BibleVerse @BibleId, 126025015, N'“This is what the sovereign Lord says: ‘The Philistines have exacted merciless revenge, showing intense scorn in their effort to destroy Judah with unrelenting hostility.'
EXEC add_BibleVerse @BibleId, 126025016, N'So this is what the sovereign Lord says: Take note, I am about to stretch out my hand against the Philistines. I will kill the Cherethites and destroy those who remain on the seacoast.'
EXEC add_BibleVerse @BibleId, 126025017, N'I will exact great vengeance upon them with angry rebukes. Then they will know that I am the Lord, when I exact my vengeance upon them.’”'
EXEC add_BibleVerse @BibleId, 126026001, N'In the eleventh year, on the first day of the month, the word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126026002, N'“Son of man, because Tyre has said about Jerusalem, ‘Aha, the gateway of the peoples is broken; it has swung open to me. I will become rich, now that she has been destroyed,’'
EXEC add_BibleVerse @BibleId, 126026003, N'therefore this is what the sovereign Lord says: Look, I am against you, O Tyre! I will bring up many nations against you, as the sea brings up its waves.'
EXEC add_BibleVerse @BibleId, 126026004, N'They will destroy the walls of Tyre and break down her towers. I will scrape her soil from her and make her a bare rock.'
EXEC add_BibleVerse @BibleId, 126026005, N'She will be a place where fishing nets are spread, surrounded by the sea. For I have spoken, declares the sovereign Lord. She will become plunder for the nations,'
EXEC add_BibleVerse @BibleId, 126026006, N'and her daughters who are in the field will be slaughtered by the sword. Then they will know that I am the Lord.'
EXEC add_BibleVerse @BibleId, 126026007, N'“For this is what the sovereign Lord says: Take note that I am about to bring King Nebuchadrezzar of Babylon, king of kings, against Tyre from the north, with horses, chariots, and horsemen, an army and hordes of people.'
EXEC add_BibleVerse @BibleId, 126026008, N'He will kill your daughters in the field with the sword. He will build a siege wall against you, erect a siege ramp against you, and raise a great shield against you.'
EXEC add_BibleVerse @BibleId, 126026009, N'He will direct the blows of his battering rams against your walls and tear down your towers with his weapons.'
EXEC add_BibleVerse @BibleId, 126026010, N'He will cover you with the dust kicked up by his many horses. Your walls will shake from the noise of the horsemen, wheels, and chariots when he enters your gates like those who invade through a city’s broken walls.'
EXEC add_BibleVerse @BibleId, 126026011, N'With his horses’ hoofs he will trample all your streets. He will kill your people with the sword, and your strong pillars will tumble down to the ground.'
EXEC add_BibleVerse @BibleId, 126026012, N'They will steal your wealth and loot your merchandise. They will tear down your walls and destroy your luxurious homes. Your stones, your trees, and your soil he will throw into the water.'
EXEC add_BibleVerse @BibleId, 126026013, N'I will silence the noise of your songs; the sound of your harps will be heard no more.'
EXEC add_BibleVerse @BibleId, 126026014, N'I will make you a bare rock; you will be a place where fishing nets are spread. You will never be built again, for I, the Lord, have spoken, declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126026015, N'“This is what the sovereign Lord says to Tyre: Oh, how the coastlands will shake at the sound of your fall, when the wounded groan, at the massive slaughter in your midst!'
EXEC add_BibleVerse @BibleId, 126026016, N'All the princes of the sea will vacate their thrones. They will remove their robes and strip off their embroidered clothes; they will clothe themselves with trembling. They will sit on the ground; they will tremble continually and be shocked at what has happened to you.'
EXEC add_BibleVerse @BibleId, 126026017, N'They will sing this lament over you: “‘How you have perished – you have vanished from the seas, O renowned city, once mighty in the sea, she and her inhabitants, who spread their terror!'
EXEC add_BibleVerse @BibleId, 126026018, N'Now the coastlands will tremble on the day of your fall; the coastlands by the sea will be terrified by your passing.’'
EXEC add_BibleVerse @BibleId, 126026019, N'“For this is what the sovereign Lord says: When I make you desolate like the uninhabited cities, when I bring up the deep over you and the surging waters overwhelm you,'
EXEC add_BibleVerse @BibleId, 126026020, N'then I will bring you down to bygone people, to be with those who descend to the pit. I will make you live in the lower parts of the earth, among the primeval ruins, with those who descend to the pit, so that you will not be inhabited or stand in the land of the living.'
EXEC add_BibleVerse @BibleId, 126026021, N'I will bring terrors on you, and you will be no more! Though you are sought after, you will never be found again, declares the sovereign Lord.”'
EXEC add_BibleVerse @BibleId, 126027001, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126027002, N'“You, son of man, sing a lament for Tyre.'
EXEC add_BibleVerse @BibleId, 126027003, N'Say to Tyre, who sits at the entrance of the sea, merchant to the peoples on many coasts, ‘This is what the sovereign Lord says: “‘O Tyre, you have said, “I am perfectly beautiful.”'
EXEC add_BibleVerse @BibleId, 126027004, N'Your borders are in the heart of the seas; your builders have perfected your beauty.'
EXEC add_BibleVerse @BibleId, 126027005, N'They crafted all your planks out of fir trees from Senir; they took a cedar from Lebanon to make your mast.'
EXEC add_BibleVerse @BibleId, 126027006, N'They made your oars from oaks of Bashan; they made your deck with cypresses from the Kittean isles.'
EXEC add_BibleVerse @BibleId, 126027007, N'Fine linen from Egypt, woven with patterns, was used for your sail to serve as your banner; blue and purple from the coastlands of Elishah was used for your deck’s awning.'
EXEC add_BibleVerse @BibleId, 126027008, N'The leaders of Sidon and Arvad were your rowers; your skilled men, O Tyre, were your captains.'
EXEC add_BibleVerse @BibleId, 126027009, N'The elders of Gebal and her skilled men were within you, mending cracks; all the ships of the sea and their mariners were within you to trade for your merchandise.'
EXEC add_BibleVerse @BibleId, 126027010, N'Men of Persia, Lud, and Put were in your army, men of war. They hung shield and helmet on you; they gave you your splendor.'
EXEC add_BibleVerse @BibleId, 126027011, N'The Arvadites joined your army on your walls all around, and the Gammadites were in your towers. They hung their quivers on your walls all around; they perfected your beauty.'
EXEC add_BibleVerse @BibleId, 126027012, N'“‘Tarshish was your trade partner because of your abundant wealth; they exchanged silver, iron, tin, and lead for your products.'
EXEC add_BibleVerse @BibleId, 126027013, N'Javan, Tubal, and Meshech were your clients; they exchanged slaves and bronze items for your merchandise.'
EXEC add_BibleVerse @BibleId, 126027014, N'Beth Togarmah exchanged horses, chargers, and mules for your products.'
EXEC add_BibleVerse @BibleId, 126027015, N'The Dedanites were your clients. Many coastlands were your customers; they paid you with ivory tusks and ebony.'
EXEC add_BibleVerse @BibleId, 126027016, N'Edom was your trade partner because of the abundance of your goods; they exchanged turquoise, purple, embroidered work, fine linen, coral, and rubies for your products.'
EXEC add_BibleVerse @BibleId, 126027017, N'Judah and the land of Israel were your clients; they traded wheat from Minnith, millet, honey, olive oil, and balm for your merchandise.'
EXEC add_BibleVerse @BibleId, 126027018, N'Damascus was your trade partner because of the abundance of your goods and of all your wealth: wine from Helbon, white wool from Zahar,'
EXEC add_BibleVerse @BibleId, 126027019, N'and casks of wine from Izal they exchanged for your products. Wrought iron, cassia, and sweet cane were among your merchandise.'
EXEC add_BibleVerse @BibleId, 126027020, N'Dedan was your client in saddlecloths for riding.'
EXEC add_BibleVerse @BibleId, 126027021, N'Arabia and all the princes of Kedar were your trade partners; for lambs, rams, and goats they traded with you.'
EXEC add_BibleVerse @BibleId, 126027022, N'The merchants of Sheba and Raamah engaged in trade with you; they traded the best kinds of spices along with precious stones and gold for your products.'
EXEC add_BibleVerse @BibleId, 126027023, N'Haran, Kanneh, Eden, merchants from Sheba, Asshur, and Kilmad were your clients.'
EXEC add_BibleVerse @BibleId, 126027024, N'They traded with you choice garments, purple clothes and embroidered work, and multicolored carpets, bound and reinforced with cords; these were among your merchandise.'
EXEC add_BibleVerse @BibleId, 126027025, N'The ships of Tarshish were the transports for your merchandise. “‘So you were filled and weighed down in the heart of the seas.'
EXEC add_BibleVerse @BibleId, 126027026, N'Your rowers have brought you into surging waters. The east wind has wrecked you in the heart of the seas.'
EXEC add_BibleVerse @BibleId, 126027027, N'Your wealth, products, and merchandise, your sailors and captains, your ship’s carpenters, your merchants, and all your fighting men within you, along with all your crew who are in you, will fall into the heart of the seas on the day of your downfall.'
EXEC add_BibleVerse @BibleId, 126027028, N'At the sound of your captains’ cry the waves will surge;'
EXEC add_BibleVerse @BibleId, 126027029, N'They will descend from their ships – all who handle the oar, the sailors and all the sea captains – they will stand on the land.'
EXEC add_BibleVerse @BibleId, 126027030, N'They will lament loudly over you and cry bitterly. They will throw dust on their heads and roll in the ashes;'
EXEC add_BibleVerse @BibleId, 126027031, N'they will tear out their hair because of you and put on sackcloth, and they will weep bitterly over you with intense mourning.'
EXEC add_BibleVerse @BibleId, 126027032, N'As they wail they will lament over you, chanting: “Who was like Tyre, like a tower in the midst of the sea?”'
EXEC add_BibleVerse @BibleId, 126027033, N'When your products went out from the seas, you satisfied many peoples; with the abundance of your wealth and merchandise you enriched the kings of the earth.'
EXEC add_BibleVerse @BibleId, 126027034, N'Now you are wrecked by the seas, in the depths of the waters; your merchandise and all your company have sunk along with you.'
EXEC add_BibleVerse @BibleId, 126027035, N'All the inhabitants of the coastlands are shocked at you, and their kings are horribly afraid – their faces are troubled.'
EXEC add_BibleVerse @BibleId, 126027036, N'The traders among the peoples hiss at you; you have become a horror, and will be no more.’”'
EXEC add_BibleVerse @BibleId, 126028001, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126028002, N'“Son of man, say to the prince of Tyre, ‘This is what the sovereign Lord says: “‘Your heart is proud and you said, “I am a god; I sit in the seat of gods, in the heart of the seas” – yet you are a man and not a god, though you think you are godlike.'
EXEC add_BibleVerse @BibleId, 126028003, N'Look, you are wiser than Daniel; no secret is hidden from you.'
EXEC add_BibleVerse @BibleId, 126028004, N'By your wisdom and understanding you have gained wealth for yourself; you have amassed gold and silver in your treasuries.'
EXEC add_BibleVerse @BibleId, 126028005, N'By your great skill in trade you have increased your wealth, and your heart is proud because of your wealth.'
EXEC add_BibleVerse @BibleId, 126028006, N'“‘Therefore this is what the sovereign Lord says: Because you think you are godlike,'
EXEC add_BibleVerse @BibleId, 126028007, N'I am about to bring foreigners against you, the most terrifying of nations. They will draw their swords against the grandeur made by your wisdom, and they will defile your splendor.'
EXEC add_BibleVerse @BibleId, 126028008, N'They will bring you down to the pit, and you will die violently in the heart of the seas.'
EXEC add_BibleVerse @BibleId, 126028009, N'Will you still say, “I am a god,” before the one who kills you – though you are a man and not a god – when you are in the power of those who wound you?'
EXEC add_BibleVerse @BibleId, 126028010, N'You will die the death of the uncircumcised by the hand of foreigners; for I have spoken, declares the sovereign Lord.’”'
EXEC add_BibleVerse @BibleId, 126028011, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126028012, N'“Son of man, sing a lament for the king of Tyre, and say to him, ‘This is what the sovereign Lord says: “‘You were the sealer of perfection, full of wisdom, and perfect in beauty.'
EXEC add_BibleVerse @BibleId, 126028013, N'You were in Eden, the garden of God. Every precious stone was your covering, the ruby, topaz, and emerald, the chrysolite, onyx, and jasper, the sapphire, turquoise, and beryl; your settings and mounts were made of gold. On the day you were created they were prepared.'
EXEC add_BibleVerse @BibleId, 126028014, N'I placed you there with an anointed guardian cherub; you were on the holy mountain of God; you walked about amidst fiery stones.'
EXEC add_BibleVerse @BibleId, 126028015, N'You were blameless in your behavior from the day you were created, until sin was discovered in you.'
EXEC add_BibleVerse @BibleId, 126028016, N'In the abundance of your trade you were filled with violence, and you sinned; so I defiled you and banished you from the mountain of God – the guardian cherub expelled you from the midst of the stones of fire.'
EXEC add_BibleVerse @BibleId, 126028017, N'Your heart was proud because of your beauty; you corrupted your wisdom on account of your splendor. I threw you down to the ground; I placed you before kings, that they might see you.'
EXEC add_BibleVerse @BibleId, 126028018, N'By the multitude of your iniquities, through the sinfulness of your trade, you desecrated your sanctuaries. So I drew fire out from within you; it consumed you, and I turned you to ashes on the earth before the eyes of all who saw you.'
EXEC add_BibleVerse @BibleId, 126028019, N'All who know you among the peoples are shocked at you; you have become terrified and will be no more.’”'
EXEC add_BibleVerse @BibleId, 126028020, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126028021, N'“Son of man, turn toward Sidon and prophesy against it.'
EXEC add_BibleVerse @BibleId, 126028022, N'Say, ‘This is what the sovereign Lord says: “‘Look, I am against you, Sidon, and I will magnify myself in your midst. Then they will know that I am the Lord when I execute judgments on her and reveal my sovereign power in her.'
EXEC add_BibleVerse @BibleId, 126028023, N'I will send a plague into the city and bloodshed into its streets; the slain will fall within it, by the sword that attacks it from every side. Then they will know that I am the Lord.'
EXEC add_BibleVerse @BibleId, 126028024, N'“‘No longer will Israel suffer from the sharp briers or painful thorns of all who surround and scorn them. Then they will know that I am the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126028025, N'“‘This is what the sovereign Lord says: When I regather the house of Israel from the peoples where they are dispersed, I will reveal my sovereign power over them in the sight of the nations, and they will live in their land that I gave to my servant Jacob.'
EXEC add_BibleVerse @BibleId, 126028026, N'They will live securely in it; they will build houses and plant vineyards. They will live securely when I execute my judgments on all those who scorn them and surround them. Then they will know that I am the Lord their God.’”'
EXEC add_BibleVerse @BibleId, 126029001, N'In the tenth year, in the tenth month, on the twelfth day of the month, the word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126029002, N'“Son of man, turn toward Pharaoh king of Egypt, and prophesy against him and against all Egypt.'
EXEC add_BibleVerse @BibleId, 126029003, N'Tell them, ‘This is what the sovereign Lord says: “‘Look, I am against you, Pharaoh king of Egypt, the great monster lying in the midst of its waterways, who has said, “My Nile is my own, I made it for myself.”'
EXEC add_BibleVerse @BibleId, 126029004, N'I will put hooks in your jaws and stick the fish of your waterways to your scales. I will haul you up from the midst of your waterways, and all the fish of your waterways will stick to your scales.'
EXEC add_BibleVerse @BibleId, 126029005, N'I will leave you in the wilderness, you and all the fish of your waterways; you will fall in the open field and will not be gathered up or collected. I have given you as food to the beasts of the earth and the birds of the skies.'
EXEC add_BibleVerse @BibleId, 126029006, N'Then all those living in Egypt will know that I am the Lord because they were a reed staff for the house of Israel;'
EXEC add_BibleVerse @BibleId, 126029007, N'when they grasped you with their hand, you broke and tore their shoulders, and when they leaned on you, you splintered and caused their legs to be unsteady.'
EXEC add_BibleVerse @BibleId, 126029008, N'“‘Therefore, this is what the sovereign Lord says: Look, I am about to bring a sword against you, and I will kill every person and every animal.'
EXEC add_BibleVerse @BibleId, 126029009, N'The land of Egypt will become a desolate ruin. Then they will know that I am the Lord. Because he said, “The Nile is mine and I made it,”'
EXEC add_BibleVerse @BibleId, 126029010, N'I am against you and your waterways. I will turn the land of Egypt into an utter desolate ruin from Migdol to Syene, as far as the border with Ethiopia.'
EXEC add_BibleVerse @BibleId, 126029011, N'No human foot will pass through it, and no animal’s foot will pass through it; it will be uninhabited for forty years.'
EXEC add_BibleVerse @BibleId, 126029012, N'I will turn the land of Egypt into a desolation in the midst of desolate lands; for forty years her cities will lie desolate in the midst of ruined cities. I will scatter Egypt among the nations and disperse them among foreign countries.'
EXEC add_BibleVerse @BibleId, 126029013, N'“‘For this is what the sovereign Lord says: At the end of forty years I will gather Egypt from the peoples where they were scattered.'
EXEC add_BibleVerse @BibleId, 126029014, N'I will restore the fortunes of Egypt, and will bring them back to the land of Pathros, to the land of their origin; there they will be an insignificant kingdom.'
EXEC add_BibleVerse @BibleId, 126029015, N'It will be the most insignificant of the kingdoms; it will never again exalt itself over the nations. I will make them so small that they will not rule over the nations.'
EXEC add_BibleVerse @BibleId, 126029016, N'It will never again be Israel’s source of confidence, but a reminder of how they sinned by turning to Egypt for help. Then they will know that I am the sovereign Lord.’”'
EXEC add_BibleVerse @BibleId, 126029017, N'In the twenty-seventh year, in the first month, on the first day of the month, the word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126029018, N'“Son of man, King Nebuchadrezzar of Babylon made his army labor hard against Tyre. Every head was rubbed bald and every shoulder rubbed bare; yet he and his army received no wages from Tyre for the work he carried out against it.'
EXEC add_BibleVerse @BibleId, 126029019, N'Therefore this is what the sovereign Lord says: Look, I am about to give the land of Egypt to King Nebuchadrezzar of Babylon. He will carry off her wealth, capture her loot, and seize her plunder; it will be his army’s wages.'
EXEC add_BibleVerse @BibleId, 126029020, N'I have given him the land of Egypt as his compensation for attacking Tyre , because they did it for me, declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126029021, N'On that day I will make Israel powerful, and I will give you the right to be heard among them. Then they will know that I am the Lord.”'
EXEC add_BibleVerse @BibleId, 126030001, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126030002, N'“Son of man, prophesy and say, ‘This is what the sovereign Lord says: “‘Wail, “Alas, the day is here!”'
EXEC add_BibleVerse @BibleId, 126030003, N'For the day is near, the day of the Lord is near; it will be a day of storm clouds, it will be a time of judgment for the nations.'
EXEC add_BibleVerse @BibleId, 126030004, N'A sword will come against Egypt and panic will overtake Ethiopia when the slain fall in Egypt and they carry away her wealth and dismantle her foundations.'
EXEC add_BibleVerse @BibleId, 126030005, N'Ethiopia, Put, Lud, all the foreigners, Libya, and the people of the covenant land will die by the sword along with them.'
EXEC add_BibleVerse @BibleId, 126030006, N'“‘This is what the Lord says: Egypt’s supporters will fall; her confident pride will crumble. From Migdol to Syene they will die by the sword within her, declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126030007, N'They will be desolate among desolate lands, and their cities will be among ruined cities.'
EXEC add_BibleVerse @BibleId, 126030008, N'They will know that I am the Lord when I ignite a fire in Egypt and all her allies are defeated.'
EXEC add_BibleVerse @BibleId, 126030009, N'On that day messengers will go out from me in ships to frighten overly confident Ethiopia; panic will overtake them on the day of Egypt’s doom; for beware – it is coming!'
EXEC add_BibleVerse @BibleId, 126030010, N'“‘This is what the sovereign Lord says: I will put an end to the hordes of Egypt, by the hand of King Nebuchadrezzar of Babylon.'
EXEC add_BibleVerse @BibleId, 126030011, N'He and his people with him, the most terrifying of the nations, will be brought there to destroy the land. They will draw their swords against Egypt, and fill the land with corpses.'
EXEC add_BibleVerse @BibleId, 126030012, N'I will dry up the waterways and hand the land over to evil men. I will make the land and everything in it desolate by the hand of foreigners. I, the Lord, have spoken!'
EXEC add_BibleVerse @BibleId, 126030013, N'“‘This is what the sovereign Lord says: I will destroy the idols, and put an end to the gods of Memphis. There will no longer be a prince from the land of Egypt; so I will make the land of Egypt fearful.'
EXEC add_BibleVerse @BibleId, 126030014, N'I will desolate Pathros, I will ignite a fire in Zoan, and I will execute judgments on Thebes.'
EXEC add_BibleVerse @BibleId, 126030015, N'I will pour out my anger upon Pelusium, the stronghold of Egypt; I will cut off the hordes of Thebes.'
EXEC add_BibleVerse @BibleId, 126030016, N'I will ignite a fire in Egypt; Syene will writhe in agony, Thebes will be broken down, and Memphis will face enemies every day.'
EXEC add_BibleVerse @BibleId, 126030017, N'The young men of On and of Pi-beseth will die by the sword; and the cities will go into captivity.'
EXEC add_BibleVerse @BibleId, 126030018, N'In Tahpanhes the day will be dark when I break the yoke of Egypt there. Her confident pride will cease within her; a cloud will cover her, and her daughters will go into captivity.'
EXEC add_BibleVerse @BibleId, 126030019, N'I will execute judgments on Egypt. Then they will know that I am the Lord.’”'
EXEC add_BibleVerse @BibleId, 126030020, N'In the eleventh year, in the first month, on the seventh day of the month, the word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126030021, N'“Son of man, I have broken the arm of Pharaoh king of Egypt. Look, it has not been bandaged for healing or set with a dressing so that it might become strong enough to grasp a sword.'
EXEC add_BibleVerse @BibleId, 126030022, N'Therefore this is what the sovereign Lord says: Look, I am against Pharaoh king of Egypt, and I will break his arms, the strong arm and the broken one, and I will make the sword drop from his hand.'
EXEC add_BibleVerse @BibleId, 126030023, N'I will scatter the Egyptians among the nations, and disperse them among foreign countries.'
EXEC add_BibleVerse @BibleId, 126030024, N'I will strengthen the arms of the king of Babylon, and I will place my sword in his hand, but I will break the arms of Pharaoh, and he will groan like the fatally wounded before the king of Babylon.'
EXEC add_BibleVerse @BibleId, 126030025, N'I will strengthen the arms of the king of Babylon, but the arms of Pharaoh will fall limp. Then they will know that I am the Lord when I place my sword in the hand of the king of Babylon and he extends it against the land of Egypt.'
EXEC add_BibleVerse @BibleId, 126030026, N'I will scatter the Egyptians among the nations and disperse them among foreign countries. Then they will know that I am the Lord.”'
EXEC add_BibleVerse @BibleId, 126031001, N'In the eleventh year, in the third month, on the first day of the month, the word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126031002, N'“Son of man, say to Pharaoh king of Egypt and his hordes: “‘Who are you like in your greatness?'
EXEC add_BibleVerse @BibleId, 126031003, N'Consider Assyria, a cedar in Lebanon, with beautiful branches, like a forest giving shade, and extremely tall; its top reached into the clouds.'
EXEC add_BibleVerse @BibleId, 126031004, N'The water made it grow; underground springs made it grow tall. Rivers flowed all around the place it was planted, while smaller channels watered all the trees of the field.'
EXEC add_BibleVerse @BibleId, 126031005, N'Therefore it grew taller than all the trees of the field; its boughs grew large and its branches grew long, because of the plentiful water in its shoots.'
EXEC add_BibleVerse @BibleId, 126031006, N'All the birds of the sky nested in its boughs; under its branches all the beasts of the field gave birth, in its shade all the great nations lived.'
EXEC add_BibleVerse @BibleId, 126031007, N'It was beautiful in its loftiness, in the length of its branches; for its roots went down deep to plentiful waters.'
EXEC add_BibleVerse @BibleId, 126031008, N'The cedars in the garden of God could not eclipse it, nor could the fir trees match its boughs; the plane trees were as nothing compared to its branches; no tree in the garden of God could rival its beauty.'
EXEC add_BibleVerse @BibleId, 126031009, N'I made it beautiful with its many branches; all the trees of Eden, in the garden of God, envied it.'
EXEC add_BibleVerse @BibleId, 126031010, N'“‘Therefore this is what the sovereign Lord says: Because it was tall in stature, and its top reached into the clouds, and it was proud of its height,'
EXEC add_BibleVerse @BibleId, 126031011, N'I gave it over to the leader of the nations. He has judged it thoroughly, as its sinfulness deserves. I have thrown it out.'
EXEC add_BibleVerse @BibleId, 126031012, N'Foreigners from the most terrifying nations have cut it down and left it to lie there on the mountains. In all the valleys its branches have fallen, and its boughs lie broken in the ravines of the land. All the peoples of the land have departed from its shade and left it.'
EXEC add_BibleVerse @BibleId, 126031013, N'On its ruins all the birds of the sky will live, and all the wild animals will walk on its branches.'
EXEC add_BibleVerse @BibleId, 126031014, N'For this reason no watered trees will grow so tall; their tops will not reach into the clouds, nor will the well-watered ones grow that high. For all of them have been appointed to die in the lower parts of the earth; they will be among mere mortals, with those who descend to the pit.'
EXEC add_BibleVerse @BibleId, 126031015, N'“‘This is what the sovereign Lord says: On the day it went down to Sheol I caused observers to lament. I covered it with the deep and held back its rivers; its plentiful water was restrained. I clothed Lebanon in black for it, and all the trees of the field wilted because of it.'
EXEC add_BibleVerse @BibleId, 126031016, N'I made the nations shake at the sound of its fall, when I threw it down to Sheol, along with those who descend to the pit. Then all the trees of Eden, the choicest and the best of Lebanon, all that were well-watered, were comforted in the earth below.'
EXEC add_BibleVerse @BibleId, 126031017, N'Those who lived in its shade, its allies among the nations, also went down with it to Sheol, to those killed by the sword.'
EXEC add_BibleVerse @BibleId, 126031018, N'Which of the trees of Eden was like you in majesty and loftiness? You will be brought down with the trees of Eden to the lower parts of the earth; you will lie among the uncircumcised, with those killed by the sword! This is what will happen to Pharaoh and all his hordes, declares the sovereign Lord.’”'
EXEC add_BibleVerse @BibleId, 126032001, N'In the twelfth year, in the twelfth month, on the first of the month, the word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126032002, N'“Son of man, sing a lament for Pharaoh king of Egypt, and say to him: “‘You were like a lion among the nations, but you are a monster in the seas; you thrash about in your streams, stir up the water with your feet, and muddy your streams.'
EXEC add_BibleVerse @BibleId, 126032003, N'“‘This is what the sovereign Lord says: “‘I will throw my net over you in the assembly of many peoples; and they will haul you up in my dragnet.'
EXEC add_BibleVerse @BibleId, 126032004, N'I will leave you on the ground, I will fling you on the open field, I will allow all the birds of the sky to settle on you, and I will permit all the wild animals to gorge themselves on you.'
EXEC add_BibleVerse @BibleId, 126032005, N'I will put your flesh on the mountains, and fill the valleys with your maggot-infested carcass.'
EXEC add_BibleVerse @BibleId, 126032006, N'I will drench the land with the flow of your blood up to the mountains, and the ravines will be full of your blood.'
EXEC add_BibleVerse @BibleId, 126032007, N'When I extinguish you, I will cover the sky; I will darken its stars. I will cover the sun with a cloud, and the moon will not shine.'
EXEC add_BibleVerse @BibleId, 126032008, N'I will darken all the lights in the sky over you, and I will darken your land, declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126032009, N'I will disturb many peoples, when I bring about your destruction among the nations, among countries you do not know.'
EXEC add_BibleVerse @BibleId, 126032010, N'I will shock many peoples with you, and their kings will shiver with horror because of you. When I brandish my sword before them, every moment each one will tremble for his life, on the day of your fall.'
EXEC add_BibleVerse @BibleId, 126032011, N'“‘For this is what the sovereign Lord says: “‘The sword of the king of Babylon will attack you.'
EXEC add_BibleVerse @BibleId, 126032012, N'By the swords of the mighty warriors I will cause your hordes to fall – all of them are the most terrifying among the nations. They will devastate the pride of Egypt, and all its hordes will be destroyed.'
EXEC add_BibleVerse @BibleId, 126032013, N'I will destroy all its cattle beside the plentiful waters; and no human foot will disturb the waters again, nor will the hooves of cattle disturb them.'
EXEC add_BibleVerse @BibleId, 126032014, N'Then I will make their waters calm, and will make their streams flow like olive oil, declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126032015, N'When I turn the land of Egypt into desolation and the land is destitute of everything that fills it, when I strike all those who live in it, then they will know that I am the Lord.’'
EXEC add_BibleVerse @BibleId, 126032016, N'This is a lament; they will chant it. The daughters of the nations will chant it. They will chant it over Egypt and over all her hordes, declares the sovereign Lord.”'
EXEC add_BibleVerse @BibleId, 126032017, N'In the twelfth year, on the fifteenth day of the month, the word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126032018, N'“Son of man, wail over the horde of Egypt. Bring it down; bring her and the daughters of powerful nations down to the lower parts of the earth, along with those who descend to the pit.'
EXEC add_BibleVerse @BibleId, 126032019, N'Say to them, ‘Whom do you surpass in beauty? Go down and be laid to rest with the uncircumcised!’'
EXEC add_BibleVerse @BibleId, 126032020, N'They will fall among those killed by the sword. The sword is drawn; they carry her and all her hordes away.'
EXEC add_BibleVerse @BibleId, 126032021, N'The bravest of the warriors will speak to him from the midst of Sheol along with his allies, saying: ‘The uncircumcised have come down; they lie still, killed by the sword.’'
EXEC add_BibleVerse @BibleId, 126032022, N'“Assyria is there with all her assembly around her grave, all of them struck down by the sword.'
EXEC add_BibleVerse @BibleId, 126032023, N'Their graves are located in the remote slopes of the pit. Her assembly is around her grave, all of them struck down by the sword, those who spread terror in the land of the living.'
EXEC add_BibleVerse @BibleId, 126032024, N'“Elam is there with all her hordes around her grave; all of them struck down by the sword. They went down uncircumcised to the lower parts of the earth, those who spread terror in the land of the living. Now they will bear their shame with those who descend to the pit.'
EXEC add_BibleVerse @BibleId, 126032025, N'Among the dead they have made a bed for her, along with all her hordes around her grave. All of them are uncircumcised, killed by the sword, for their terror had spread in the land of the living. They bear their shame along with those who descend to the pit; they are placed among the dead.'
EXEC add_BibleVerse @BibleId, 126032026, N'“Meshech-Tubal is there, along with all her hordes around her grave. All of them are uncircumcised, killed by the sword, for they spread their terror in the land of the living.'
EXEC add_BibleVerse @BibleId, 126032027, N'They do not lie with the fallen warriors of ancient times, who went down to Sheol with their weapons of war, having their swords placed under their heads and their shields on their bones, when the terror of these warriors was in the land of the living.'
EXEC add_BibleVerse @BibleId, 126032028, N'“But as for you, in the midst of the uncircumcised you will be broken, and you will lie with those killed by the sword.'
EXEC add_BibleVerse @BibleId, 126032029, N'“Edom is there with her kings and all her princes. Despite their might they are laid with those killed by the sword; they lie with the uncircumcised and those who descend to the pit.'
EXEC add_BibleVerse @BibleId, 126032030, N'“All the leaders of the north are there, along with all the Sidonians; despite their might they have gone down in shameful terror with the dead. They lie uncircumcised with those killed by the sword, and bear their shame with those who descend to the pit.'
EXEC add_BibleVerse @BibleId, 126032031, N'“Pharaoh will see them and be consoled over all his hordes who were killed by the sword, Pharaoh and all his army, declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126032032, N'Indeed, I terrified him in the land of the living, yet he will lie in the midst of the uncircumcised with those killed by the sword, Pharaoh and all his hordes, declares the sovereign Lord.”'
EXEC add_BibleVerse @BibleId, 126033001, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126033002, N'“Son of man, speak to your people, and say to them, ‘Suppose I bring a sword against the land, and the people of the land take one man from their borders and make him their watchman.'
EXEC add_BibleVerse @BibleId, 126033003, N'He sees the sword coming against the land, blows the trumpet, and warns the people,'
EXEC add_BibleVerse @BibleId, 126033004, N'but there is one who hears the sound of the trumpet yet does not heed the warning. Then the sword comes and sweeps him away. He will be responsible for his own death.'
EXEC add_BibleVerse @BibleId, 126033005, N'He heard the sound of the trumpet but did not heed the warning, so he is responsible for himself. If he had heeded the warning, he would have saved his life.'
EXEC add_BibleVerse @BibleId, 126033006, N'But suppose the watchman sees the sword coming and does not blow the trumpet to warn the people. Then the sword comes and takes one of their lives. He is swept away for his iniquity, but I will hold the watchman accountable for that person’s death.’'
EXEC add_BibleVerse @BibleId, 126033007, N'“As for you, son of man, I have made you a watchman for the house of Israel. Whenever you hear a word from my mouth, you must warn them on my behalf.'
EXEC add_BibleVerse @BibleId, 126033008, N'When I say to the wicked, ‘O wicked man, you must certainly die,’ and you do not warn the wicked about his behavior, the wicked man will die for his iniquity, but I will hold you accountable for his death.'
EXEC add_BibleVerse @BibleId, 126033009, N'But if you warn the wicked man to change his behavior, and he refuses to change, he will die for his iniquity, but you have saved your own life.'
EXEC add_BibleVerse @BibleId, 126033010, N'“And you, son of man, say to the house of Israel, ‘This is what you have said: “Our rebellious acts and our sins have caught up with us, and we are wasting away because of them. How then can we live?”’'
EXEC add_BibleVerse @BibleId, 126033011, N'Say to them, ‘As surely as I live, declares the sovereign Lord, I take no pleasure in the death of the wicked, but prefer that the wicked change his behavior and live. Turn back, turn back from your evil deeds! Why should you die, O house of Israel?’'
EXEC add_BibleVerse @BibleId, 126033012, N'“And you, son of man, say to your people, ‘The righteousness of the righteous will not deliver him if he rebels. As for the wicked, his wickedness will not make him stumble if he turns from it. The righteous will not be able to live by his righteousness if he sins.’'
EXEC add_BibleVerse @BibleId, 126033013, N'Suppose I tell the righteous that he will certainly live, but he becomes confident in his righteousness and commits iniquity. None of his righteous deeds will be remembered; because of the iniquity he has committed he will die.'
EXEC add_BibleVerse @BibleId, 126033014, N'Suppose I say to the wicked, ‘You must certainly die,’ but he turns from his sin and does what is just and right.'
EXEC add_BibleVerse @BibleId, 126033015, N'He returns what was taken in pledge, pays back what he has stolen, and follows the statutes that give life, committing no iniquity. He will certainly live – he will not die.'
EXEC add_BibleVerse @BibleId, 126033016, N'None of the sins he has committed will be counted against him. He has done what is just and right; he will certainly live.'
EXEC add_BibleVerse @BibleId, 126033017, N'“Yet your people say, ‘The behavior of the Lord is not right,’ when it is their behavior that is not right.'
EXEC add_BibleVerse @BibleId, 126033018, N'When a righteous man turns from his godliness and commits iniquity, he will die for it.'
EXEC add_BibleVerse @BibleId, 126033019, N'When the wicked turns from his sin and does what is just and right, he will live because of it.'
EXEC add_BibleVerse @BibleId, 126033020, N'Yet you say, ‘The behavior of the Lord is not right.’ House of Israel, I will judge each of you according to his behavior.”'
EXEC add_BibleVerse @BibleId, 126033021, N'In the twelfth year of our exile, in the tenth month, on the fifth of the month, a refugee came to me from Jerusalem saying, “The city has been defeated!”'
EXEC add_BibleVerse @BibleId, 126033022, N'Now the hand of the Lord had been on me the evening before the refugee reached me, but the Lord opened my mouth by the time the refugee arrived in the morning; he opened my mouth and I was no longer unable to speak.'
EXEC add_BibleVerse @BibleId, 126033023, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126033024, N'“Son of man, the ones living in these ruins in the land of Israel are saying, ‘Abraham was only one man, yet he possessed the land, but we are many; surely the land has been given to us for a possession.’'
EXEC add_BibleVerse @BibleId, 126033025, N'Therefore say to them, ‘This is what the sovereign Lord says: You eat the meat with the blood still in it, pray to your idols, and shed blood. Do you really think you will possess the land?'
EXEC add_BibleVerse @BibleId, 126033026, N'You rely on your swords and commit abominable deeds; each of you defiles his neighbor’s wife. Will you possess the land?’'
EXEC add_BibleVerse @BibleId, 126033027, N'“This is what you must say to them, ‘This is what the sovereign Lord says: As surely as I live, those living in the ruins will die by the sword, those in the open field I will give to the wild beasts for food, and those who are in the strongholds and caves will die of disease.'
EXEC add_BibleVerse @BibleId, 126033028, N'I will turn the land into a desolate ruin; her confident pride will come to an end. The mountains of Israel will be so desolate no one will pass through them.'
EXEC add_BibleVerse @BibleId, 126033029, N'Then they will know that I am the Lord when I turn the land into a desolate ruin because of all the abominable deeds they have committed.’'
EXEC add_BibleVerse @BibleId, 126033030, N'“But as for you, son of man, your people (who are talking about you by the walls and at the doors of the houses) say to one another, ‘Come hear the word that comes from the Lord.’'
EXEC add_BibleVerse @BibleId, 126033031, N'They come to you in crowds, and they sit in front of you as my people. They hear your words, but do not obey them. For they talk lustfully, and their heart is set on their own advantage.'
EXEC add_BibleVerse @BibleId, 126033032, N'Realize that to them you are like a sensual song, a beautiful voice and skilled musician. They hear your words, but they do not obey them.'
EXEC add_BibleVerse @BibleId, 126033033, N'When all this comes true – and it certainly will – then they will know that a prophet was among them.”'
EXEC add_BibleVerse @BibleId, 126034001, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126034002, N'“Son of man, prophesy against the shepherds of Israel; prophesy, and say to them – to the shepherds: ‘This is what the sovereign Lord says: Woe to the shepherds of Israel who have been feeding themselves! Should not shepherds feed the flock?'
EXEC add_BibleVerse @BibleId, 126034003, N'You eat the fat, you clothe yourselves with the wool, you slaughter the choice animals, but you do not feed the sheep!'
EXEC add_BibleVerse @BibleId, 126034004, N'You have not strengthened the weak, healed the sick, bandaged the injured, brought back the strays, or sought the lost, but with force and harshness you have ruled over them.'
EXEC add_BibleVerse @BibleId, 126034005, N'They were scattered because they had no shepherd, and they became food for every wild beast.'
EXEC add_BibleVerse @BibleId, 126034006, N'My sheep wandered over all the mountains and on every high hill. My sheep were scattered over the entire face of the earth with no one looking or searching for them.'
EXEC add_BibleVerse @BibleId, 126034007, N'“‘Therefore, you shepherds, hear the word of the Lord:'
EXEC add_BibleVerse @BibleId, 126034008, N'As surely as I live, declares the sovereign Lord, my sheep have become prey and have become food for all the wild beasts. There was no shepherd, and my shepherds did not search for my flock, but fed themselves and did not feed my sheep,'
EXEC add_BibleVerse @BibleId, 126034009, N'Therefore, you shepherds, hear the word of the Lord:'
EXEC add_BibleVerse @BibleId, 126034010, N'This is what the sovereign Lord says: Look, I am against the shepherds, and I will demand my sheep from their hand. I will no longer let them be shepherds; the shepherds will not feed themselves anymore. I will rescue my sheep from their mouth, so that they will no longer be food for them.'
EXEC add_BibleVerse @BibleId, 126034011, N'“‘For this is what the sovereign Lord says: Look, I myself will search for my sheep and seek them out.'
EXEC add_BibleVerse @BibleId, 126034012, N'As a shepherd seeks out his flock when he is among his scattered sheep, so I will seek out my flock. I will rescue them from all the places where they have been scattered on a cloudy, dark day.'
EXEC add_BibleVerse @BibleId, 126034013, N'I will bring them out from among the peoples and gather them from foreign countries; I will bring them to their own land. I will feed them on the mountains of Israel, by the streams and all the inhabited places of the land.'
EXEC add_BibleVerse @BibleId, 126034014, N'In a good pasture I will feed them; the mountain heights of Israel will be their pasture. There they will lie down in a lush pasture, and they will feed on rich grass on the mountains of Israel.'
EXEC add_BibleVerse @BibleId, 126034015, N'I myself will feed my sheep and I myself will make them lie down, declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126034016, N'I will seek the lost and bring back the strays; I will bandage the injured and strengthen the sick, but the fat and the strong I will destroy. I will feed them – with judgment!'
EXEC add_BibleVerse @BibleId, 126034017, N'“‘As for you, my sheep, this is what the sovereign Lord says: Look, I am about to judge between one sheep and another, between rams and goats.'
EXEC add_BibleVerse @BibleId, 126034018, N'Is it not enough for you to feed on the good pasture, that you must trample the rest of your pastures with your feet? When you drink clean water, must you muddy the rest of the water by trampling it with your feet?'
EXEC add_BibleVerse @BibleId, 126034019, N'As for my sheep, they must eat what you trampled with your feet, and drink what you have muddied with your feet!'
EXEC add_BibleVerse @BibleId, 126034020, N'“‘Therefore, this is what the sovereign Lord says to them: Look, I myself will judge between the fat sheep and the lean sheep.'
EXEC add_BibleVerse @BibleId, 126034021, N'Because you push with your side and your shoulder, and thrust your horns at all the weak sheep until you scatter them abroad,'
EXEC add_BibleVerse @BibleId, 126034022, N'I will save my sheep; they will no longer be prey. I will judge between one sheep and another.'
EXEC add_BibleVerse @BibleId, 126034023, N'I will set one shepherd over them, and he will feed them – namely, my servant David. He will feed them and will be their shepherd.'
EXEC add_BibleVerse @BibleId, 126034024, N'I, the Lord, will be their God, and my servant David will be prince among them; I, the Lord, have spoken!'
EXEC add_BibleVerse @BibleId, 126034025, N'“‘I will make a covenant of peace with them and will rid the land of wild beasts, so that they can live securely in the wilderness and even sleep in the woods.'
EXEC add_BibleVerse @BibleId, 126034026, N'I will turn them and the regions around my hill into a blessing. I will make showers come down in their season; they will be showers that bring blessing.'
EXEC add_BibleVerse @BibleId, 126034027, N'The trees of the field will yield their fruit and the earth will yield its crops. They will live securely on their land; they will know that I am the Lord, when I break the bars of their yoke and rescue them from the hand of those who enslaved them.'
EXEC add_BibleVerse @BibleId, 126034028, N'They will no longer be prey for the nations and the wild beasts will not devour them. They will live securely and no one will make them afraid.'
EXEC add_BibleVerse @BibleId, 126034029, N'I will prepare for them a healthy planting. They will no longer be victims of famine in the land and will no longer bear the insults of the nations.'
EXEC add_BibleVerse @BibleId, 126034030, N'Then they will know that I, the Lord their God, am with them, and that they are my people, the house of Israel, declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126034031, N'And you, my sheep, the sheep of my pasture, are my people, and I am your God, declares the sovereign Lord.’”'
EXEC add_BibleVerse @BibleId, 126035001, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126035002, N'“Son of man, turn toward Mount Seir, and prophesy against it.'
EXEC add_BibleVerse @BibleId, 126035003, N'Say to it, ‘This is what the sovereign Lord says: “‘Look, I am against you, Mount Seir; I will stretch out my hand against you and turn you into a desolate ruin.'
EXEC add_BibleVerse @BibleId, 126035004, N'I will lay waste your cities; and you will become desolate. Then you will know that I am the Lord!'
EXEC add_BibleVerse @BibleId, 126035005, N'“‘You have shown unrelenting hostility and poured the people of Israel onto the blades of a sword at the time of their calamity, at the time of their final punishment.'
EXEC add_BibleVerse @BibleId, 126035006, N'Therefore, as surely as I live, declares the sovereign Lord, I will subject you to bloodshed, and bloodshed will pursue you. Since you did not hate bloodshed, bloodshed will pursue you.'
EXEC add_BibleVerse @BibleId, 126035007, N'I will turn Mount Seir into a desolate ruin; I will cut off from it the one who passes through or returns.'
EXEC add_BibleVerse @BibleId, 126035008, N'I will fill its mountains with its dead; on your hills and in your valleys and in all your ravines, those killed by the sword will fall.'
EXEC add_BibleVerse @BibleId, 126035009, N'I will turn you into a perpetual desolation, and your cities will not be inhabited. Then you will know that I am the Lord.'
EXEC add_BibleVerse @BibleId, 126035010, N'“‘You said, “These two nations, these two lands will be mine, and we will possess them,” – although the Lord was there –'
EXEC add_BibleVerse @BibleId, 126035011, N'therefore, as surely as I live, declares the sovereign Lord, I will deal with you according to your anger, and according to your envy, by which you acted spitefully against them. I will reveal myself to them when I judge you.'
EXEC add_BibleVerse @BibleId, 126035012, N'Then you will know that I, the Lord, have heard all the insults you spoke against the mountains of Israel, saying, “They are desolate, they have been given to us for food.”'
EXEC add_BibleVerse @BibleId, 126035013, N'You exalted yourselves against me with your speech and hurled many insults against me – I have heard them all!'
EXEC add_BibleVerse @BibleId, 126035014, N'This is what the sovereign Lord says: While the whole earth rejoices, I will turn you into a desolation.'
EXEC add_BibleVerse @BibleId, 126035015, N'As you rejoiced over the inheritance of the house of Israel because it was desolate, so will I deal with you – you will be desolate, Mount Seir, and all of Edom – all of it! Then they will know that I am the Lord.’”'
EXEC add_BibleVerse @BibleId, 126036001, N'“As for you, son of man, prophesy to the mountains of Israel, and say: ‘O mountains of Israel, hear the word of the Lord!'
EXEC add_BibleVerse @BibleId, 126036002, N'This is what the sovereign Lord says: The enemy has spoken against you, saying “Aha!” and, “The ancient heights have become our property!”’'
EXEC add_BibleVerse @BibleId, 126036003, N'So prophesy and say: ‘This is what the sovereign Lord says: Surely because they have made you desolate and crushed you from all directions, so that you have become the property of the rest of the nations, and have become the subject of gossip and slander among the people,'
EXEC add_BibleVerse @BibleId, 126036004, N'therefore, O mountains of Israel, hear the word of the sovereign Lord: This is what the sovereign Lord says to the mountains and hills, the ravines and valleys, and to the desolate ruins and the abandoned cities that have become prey and an object of derision to the rest of the nations round about –'
EXEC add_BibleVerse @BibleId, 126036005, N'therefore this is what the sovereign Lord says: Surely I have spoken in the fire of my zeal against the rest of the nations, and against all Edom, who with great joy and utter contempt have made my land their property and prey, because of its pasture.’'
EXEC add_BibleVerse @BibleId, 126036006, N'“Therefore prophesy concerning the land of Israel, and say to the mountains and hills, the ravines and valleys, ‘This is what the sovereign Lord says: Look, I have spoken in my zeal and in my anger, because you have endured the insults of the nations.'
EXEC add_BibleVerse @BibleId, 126036007, N'So this is what the sovereign Lord says: I vow that the nations around you will endure insults as well.'
EXEC add_BibleVerse @BibleId, 126036008, N'“‘But you, mountains of Israel, will grow your branches, and bear your fruit for my people Israel; for they will arrive soon.'
EXEC add_BibleVerse @BibleId, 126036009, N'For indeed, I am on your side; I will turn to you, and you will be plowed and planted.'
EXEC add_BibleVerse @BibleId, 126036010, N'I will multiply your people – the whole house of Israel, all of it. The cities will be populated and the ruins rebuilt.'
EXEC add_BibleVerse @BibleId, 126036011, N'I will increase the number of people and animals on you; they will increase and be fruitful. I will cause you to be inhabited as in ancient times, and will do more good for you than at the beginning of your history. Then you will know that I am the Lord.'
EXEC add_BibleVerse @BibleId, 126036012, N'I will lead people, my people Israel, across you; they will possess you and you will become their inheritance. No longer will you bereave them of their children.'
EXEC add_BibleVerse @BibleId, 126036013, N'“‘This is what the sovereign Lord says: Because they are saying to you, “You are a devourer of men, and bereave your nation of children,”'
EXEC add_BibleVerse @BibleId, 126036014, N'therefore you will no longer devour people and no longer bereave your nation of children, declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126036015, N'I will no longer subject you to the nations’ insults; no longer will you bear the shame of the peoples, and no longer will you bereave your nation, declares the sovereign Lord.’”'
EXEC add_BibleVerse @BibleId, 126036016, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126036017, N'“Son of man, when the house of Israel was living on their own land, they defiled it by their behavior and their deeds. In my sight their behavior was like the uncleanness of a woman having her monthly period.'
EXEC add_BibleVerse @BibleId, 126036018, N'So I poured my anger on them because of the blood they shed on the land and because of the idols with which they defiled it.'
EXEC add_BibleVerse @BibleId, 126036019, N'I scattered them among the nations; they were dispersed throughout foreign countries. In accordance with their behavior and their deeds I judged them.'
EXEC add_BibleVerse @BibleId, 126036020, N'But when they arrived in the nations where they went, they profaned my holy name. It was said of them, ‘These are the people of the Lord, yet they have departed from his land.’'
EXEC add_BibleVerse @BibleId, 126036021, N'I was concerned for my holy reputation which the house of Israel profaned among the nations where they went.'
EXEC add_BibleVerse @BibleId, 126036022, N'“Therefore say to the house of Israel, ‘This is what the sovereign Lord says: It is not for your sake that I am about to act, O house of Israel, but for the sake of my holy reputation which you profaned among the nations where you went.'
EXEC add_BibleVerse @BibleId, 126036023, N'I will magnify my great name that has been profaned among the nations, that you have profaned among them. The nations will know that I am the Lord, declares the sovereign Lord, when I magnify myself among you in their sight.'
EXEC add_BibleVerse @BibleId, 126036024, N'“‘I will take you from the nations and gather you from all the countries; then I will bring you to your land.'
EXEC add_BibleVerse @BibleId, 126036025, N'I will sprinkle you with pure water and you will be clean from all your impurities. I will purify you from all your idols.'
EXEC add_BibleVerse @BibleId, 126036026, N'I will give you a new heart, and I will put a new spirit within you. I will remove the heart of stone from your body and give you a heart of flesh.'
EXEC add_BibleVerse @BibleId, 126036027, N'I will put my Spirit within you; I will take the initiative and you will obey my statutes and carefully observe my regulations.'
EXEC add_BibleVerse @BibleId, 126036028, N'Then you will live in the land I gave to your fathers; you will be my people, and I will be your God.'
EXEC add_BibleVerse @BibleId, 126036029, N'I will save you from all your uncleanness. I will call for the grain and multiply it; I will not bring a famine on you.'
EXEC add_BibleVerse @BibleId, 126036030, N'I will multiply the fruit of the trees and the produce of the fields, so that you will never again suffer the disgrace of famine among the nations.'
EXEC add_BibleVerse @BibleId, 126036031, N'Then you will remember your evil behavior and your deeds which were not good; you will loathe yourselves on account of your sins and your abominable deeds.'
EXEC add_BibleVerse @BibleId, 126036032, N'Understand that it is not for your sake I am about to act, declares the sovereign Lord. Be ashamed and embarrassed by your behavior, O house of Israel.'
EXEC add_BibleVerse @BibleId, 126036033, N'“‘This is what the sovereign Lord says: In the day I cleanse you from all your sins, I will populate the cities and the ruins will be rebuilt.'
EXEC add_BibleVerse @BibleId, 126036034, N'The desolate land will be plowed, instead of being desolate in the sight of everyone who passes by.'
EXEC add_BibleVerse @BibleId, 126036035, N'They will say, “This desolate land has become like the garden of Eden; the ruined, desolate, and destroyed cities are now fortified and inhabited.”'
EXEC add_BibleVerse @BibleId, 126036036, N'Then the nations which remain around you will know that I, the Lord, have rebuilt the ruins and replanted what was desolate. I, the Lord, have spoken – and I will do it!’'
EXEC add_BibleVerse @BibleId, 126036037, N'“This is what the sovereign Lord says: I will allow the house of Israel to ask me to do this for them: I will multiply their people like sheep.'
EXEC add_BibleVerse @BibleId, 126036038, N'Like the sheep for offerings, like the sheep of Jerusalem during her appointed feasts, so will the ruined cities be filled with flocks of people. Then they will know that I am the Lord.”'
EXEC add_BibleVerse @BibleId, 126037001, N'The hand of the Lord was on me, and he brought me out by the Spirit of the Lord and placed me in the midst of the valley, and it was full of bones.'
EXEC add_BibleVerse @BibleId, 126037002, N'He made me walk all around among them. I realized there were a great many bones in the valley and they were very dry.'
EXEC add_BibleVerse @BibleId, 126037003, N'He said to me, “Son of man, can these bones live?” I said to him, “Sovereign Lord, you know.”'
EXEC add_BibleVerse @BibleId, 126037004, N'Then he said to me, “Prophesy over these bones, and tell them: ‘Dry bones, hear the word of the Lord.'
EXEC add_BibleVerse @BibleId, 126037005, N'This is what the sovereign Lord says to these bones: Look, I am about to infuse breath into you and you will live.'
EXEC add_BibleVerse @BibleId, 126037006, N'I will put tendons on you and muscles over you and will cover you with skin; I will put breath in you and you will live. Then you will know that I am the Lord.’”'
EXEC add_BibleVerse @BibleId, 126037007, N'So I prophesied as I was commanded. There was a sound when I prophesied – I heard a rattling, and the bones came together, bone to bone.'
EXEC add_BibleVerse @BibleId, 126037008, N'As I watched, I saw tendons on them, then muscles appeared, and skin covered over them from above, but there was no breath in them.'
EXEC add_BibleVerse @BibleId, 126037009, N'He said to me, “Prophesy to the breath, – prophesy, son of man – and say to the breath: ‘This is what the sovereign Lord says: Come from the four winds, O breath, and breathe on these corpses so that they may live.’”'
EXEC add_BibleVerse @BibleId, 126037010, N'So I prophesied as I was commanded, and the breath came into them; they lived and stood on their feet, an extremely great army.'
EXEC add_BibleVerse @BibleId, 126037011, N'Then he said to me, “Son of man, these bones are all the house of Israel. Look, they are saying, ‘Our bones are dry, our hope has perished; we are cut off.’'
EXEC add_BibleVerse @BibleId, 126037012, N'Therefore prophesy, and tell them, ‘This is what the sovereign Lord says: Look, I am about to open your graves and will raise you from your graves, my people. I will bring you to the land of Israel.'
EXEC add_BibleVerse @BibleId, 126037013, N'Then you will know that I am the Lord, when I open your graves and raise you from your graves, my people.'
EXEC add_BibleVerse @BibleId, 126037014, N'I will place my breath in you and you will live; I will give you rest in your own land. Then you will know that I am the Lord – I have spoken and I will act, declares the Lord.’”'
EXEC add_BibleVerse @BibleId, 126037015, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126037016, N'“As for you, son of man, take one branch, and write on it, ‘For Judah, and for the Israelites associated with him.’ Then take another branch and write on it, ‘For Joseph, the branch of Ephraim and all the house of Israel associated with him.’'
EXEC add_BibleVerse @BibleId, 126037017, N'Join them as one stick; they will be as one in your hand.'
EXEC add_BibleVerse @BibleId, 126037018, N'When your people say to you, ‘Will you not tell us what these things mean?’'
EXEC add_BibleVerse @BibleId, 126037019, N'tell them, ‘This is what the sovereign Lord says: Look, I am about to take the branch of Joseph which is in the hand of Ephraim and the tribes of Israel associated with him, and I will place them on the stick of Judah, and make them into one stick – they will be one in my hand.’'
EXEC add_BibleVerse @BibleId, 126037020, N'The sticks you write on will be in your hand in front of them.'
EXEC add_BibleVerse @BibleId, 126037021, N'Then tell them, ‘This is what the sovereign Lord says: Look, I am about to take the Israelites from among the nations where they have gone. I will gather them from round about and bring them to their land.'
EXEC add_BibleVerse @BibleId, 126037022, N'I will make them one nation in the land, on the mountains of Israel, and one king will rule over them all. They will never again be two nations and never again be divided into two kingdoms.'
EXEC add_BibleVerse @BibleId, 126037023, N'They will not defile themselves with their idols, their detestable things, and all their rebellious deeds. I will save them from all their unfaithfulness by which they sinned. I will purify them; they will become my people and I will become their God.'
EXEC add_BibleVerse @BibleId, 126037024, N'“‘My servant David will be king over them; there will be one shepherd for all of them. They will follow my regulations and carefully observe my statutes.'
EXEC add_BibleVerse @BibleId, 126037025, N'They will live in the land I gave to my servant Jacob, in which your fathers lived; they will live in it – they and their children and their grandchildren forever. David my servant will be prince over them forever.'
EXEC add_BibleVerse @BibleId, 126037026, N'I will make a covenant of peace with them; it will be a perpetual covenant with them. I will establish them, increase their numbers, and place my sanctuary among them forever.'
EXEC add_BibleVerse @BibleId, 126037027, N'My dwelling place will be with them; I will be their God, and they will be my people.'
EXEC add_BibleVerse @BibleId, 126037028, N'Then, when my sanctuary is among them forever, the nations will know that I, the Lord, sanctify Israel.’”'
EXEC add_BibleVerse @BibleId, 126038001, N'The word of the Lord came to me:'
EXEC add_BibleVerse @BibleId, 126038002, N'“Son of man, turn toward Gog, of the land of Magog, the chief prince of Meshech and Tubal. Prophesy against him'
EXEC add_BibleVerse @BibleId, 126038003, N'and say: ‘This is what the sovereign Lord says: Look, I am against you, Gog, chief prince of Meshech and Tubal.'
EXEC add_BibleVerse @BibleId, 126038004, N'I will turn you around, put hooks into your jaws, and bring you out with all your army, horses and horsemen, all of them fully armed, a great company with shields of different types, all of them armed with swords.'
EXEC add_BibleVerse @BibleId, 126038005, N'Persia, Ethiopia, and Put are with them, all of them with shields and helmets.'
EXEC add_BibleVerse @BibleId, 126038006, N'They are joined by Gomer with all its troops, and by Beth Togarmah from the remote parts of the north with all its troops – many peoples are with you.'
EXEC add_BibleVerse @BibleId, 126038007, N'“‘Be ready and stay ready, you and all your companies assembled around you, and be a guard for them.'
EXEC add_BibleVerse @BibleId, 126038008, N'After many days you will be summoned; in the latter years you will come to a land restored from the ravages of war, with many peoples gathered on the mountains of Israel that had long been in ruins. Its people were brought out from the peoples, and all of them will be living securely.'
EXEC add_BibleVerse @BibleId, 126038009, N'You will advance; you will come like a storm. You will be like a cloud covering the earth, you, all your troops, and the many other peoples with you.'
EXEC add_BibleVerse @BibleId, 126038010, N'“‘This is what the sovereign Lord says: On that day thoughts will come into your mind, and you will devise an evil plan.'
EXEC add_BibleVerse @BibleId, 126038011, N'You will say, “I will invade a land of unwalled towns; I will advance against those living quietly in security – all of them living without walls and barred gates –'
EXEC add_BibleVerse @BibleId, 126038012, N'to loot and plunder, to attack the inhabited ruins and the people gathered from the nations, who are acquiring cattle and goods, who live at the center of the earth.”'
EXEC add_BibleVerse @BibleId, 126038013, N'Sheba and Dedan and the traders of Tarshish with all its young warriors will say to you, “Have you come to loot? Have you assembled your armies to plunder, to carry away silver and gold, to take away cattle and goods, to haul away a great amount of spoils?”’'
EXEC add_BibleVerse @BibleId, 126038014, N'“Therefore, prophesy, son of man, and say to Gog: ‘This is what the sovereign Lord says: On that day when my people Israel are living securely, you will take notice'
EXEC add_BibleVerse @BibleId, 126038015, N'and come from your place, from the remote parts of the north, you and many peoples with you, all of them riding on horses, a great company and a vast army.'
EXEC add_BibleVerse @BibleId, 126038016, N'You will advance against my people Israel like a cloud covering the earth. In the latter days I will bring you against my land so that the nations may acknowledge me, when before their eyes I magnify myself through you, O Gog.'
EXEC add_BibleVerse @BibleId, 126038017, N'“‘This is what the sovereign Lord says: Are you the one of whom I spoke in former days by my servants the prophets of Israel, who prophesied in those days that I would bring you against them?'
EXEC add_BibleVerse @BibleId, 126038018, N'On that day, when Gog invades the land of Israel, declares the sovereign Lord, my rage will mount up in my anger.'
EXEC add_BibleVerse @BibleId, 126038019, N'In my zeal, in the fire of my fury, I declare that on that day there will be a great earthquake in the land of Israel.'
EXEC add_BibleVerse @BibleId, 126038020, N'The fish of the sea, the birds of the sky, the wild beasts, all the things that creep on the ground, and all people who live on the face of the earth will shake at my presence. The mountains will topple, the cliffs will fall, and every wall will fall to the ground.'
EXEC add_BibleVerse @BibleId, 126038021, N'I will call for a sword to attack Gog on all my mountains, declares the sovereign Lord; every man’s sword will be against his brother.'
EXEC add_BibleVerse @BibleId, 126038022, N'I will judge him with plague and bloodshed. I will rain down on him, his troops and the many peoples who are with him a torrential downpour, hailstones, fire, and brimstone.'
EXEC add_BibleVerse @BibleId, 126038023, N'I will exalt and magnify myself; I will reveal myself before many nations. Then they will know that I am the Lord.’'
EXEC add_BibleVerse @BibleId, 126039001, N'“As for you, son of man, prophesy against Gog, and say: ‘This is what the sovereign Lord says: Look, I am against you, O Gog, chief prince of Meshech and Tubal!'
EXEC add_BibleVerse @BibleId, 126039002, N'I will turn you around and drag you along; I will lead you up from the remotest parts of the north and bring you against the mountains of Israel.'
EXEC add_BibleVerse @BibleId, 126039003, N'I will knock your bow out of your left hand and make your arrows fall from your right hand.'
EXEC add_BibleVerse @BibleId, 126039004, N'You will fall dead on the mountains of Israel, you and all your troops and the people who are with you. I give you as food to every kind of bird and every wild beast.'
EXEC add_BibleVerse @BibleId, 126039005, N'You will fall dead in the open field; for I have spoken, declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126039006, N'I will send fire on Magog and those who live securely in the coastlands; then they will know that I am the Lord.'
EXEC add_BibleVerse @BibleId, 126039007, N'“‘I will make my holy name known in the midst of my people Israel; I will not let my holy name be profaned anymore. Then the nations will know that I am the Lord, the Holy One of Israel.'
EXEC add_BibleVerse @BibleId, 126039008, N'Realize that it is coming and it will be done, declares the sovereign Lord. It is the day I have spoken about.'
EXEC add_BibleVerse @BibleId, 126039009, N'“‘Then those who live in the cities of Israel will go out and use the weapons for kindling – the shields, bows and arrows, war clubs and spears – they will burn them for seven years.'
EXEC add_BibleVerse @BibleId, 126039010, N'They will not need to take wood from the field or cut down trees from the forests, because they will make fires with the weapons. They will take the loot from those who looted them and seize the plunder of those who plundered them, declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126039011, N'“‘On that day I will assign Gog a grave in Israel. It will be the valley of those who travel east of the sea; it will block the way of the travelers. There they will bury Gog and all his horde; they will call it the valley of Hamon-Gog.'
EXEC add_BibleVerse @BibleId, 126039012, N'For seven months Israel will bury them, in order to cleanse the land.'
EXEC add_BibleVerse @BibleId, 126039013, N'All the people of the land will bury them, and it will be a memorial for them on the day I magnify myself, declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126039014, N'They will designate men to scout continually through the land, burying those who remain on the surface of the ground, in order to cleanse it. They will search for seven full months.'
EXEC add_BibleVerse @BibleId, 126039015, N'When the scouts survey the land and see a human bone, they will place a sign by it, until those assigned to burial duty have buried it in the valley of Hamon-Gog.'
EXEC add_BibleVerse @BibleId, 126039016, N'(A city by the name of Hamonah will also be there.) They will cleanse the land.’'
EXEC add_BibleVerse @BibleId, 126039017, N'“As for you, son of man, this is what the sovereign Lord says: Tell every kind of bird and every wild beast: ‘Assemble and come! Gather from all around to my slaughter which I am going to make for you, a great slaughter on the mountains of Israel! You will eat flesh and drink blood.'
EXEC add_BibleVerse @BibleId, 126039018, N'You will eat the flesh of warriors and drink the blood of the princes of the earth – the rams, lambs, goats, and bulls, all of them fattened animals of Bashan.'
EXEC add_BibleVerse @BibleId, 126039019, N'You will eat fat until you are full, and drink blood until you are drunk, at my slaughter which I have made for you.'
EXEC add_BibleVerse @BibleId, 126039020, N'You will fill up at my table with horses and charioteers, with warriors and all the soldiers,’ declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126039021, N'“I will display my majesty among the nations. All the nations will witness the judgment I have executed, and the power I have exhibited among them.'
EXEC add_BibleVerse @BibleId, 126039022, N'Then the house of Israel will know that I am the Lord their God, from that day forward.'
EXEC add_BibleVerse @BibleId, 126039023, N'The nations will know that the house of Israel went into exile due to their iniquity, for they were unfaithful to me. So I hid my face from them and handed them over to their enemies; all of them died by the sword.'
EXEC add_BibleVerse @BibleId, 126039024, N'According to their uncleanness and rebellion I have dealt with them, and I hid my face from them.'
EXEC add_BibleVerse @BibleId, 126039025, N'“Therefore this is what the sovereign Lord says: Now I will restore the fortunes of Jacob, and I will have mercy on the entire house of Israel. I will be zealous for my holy name.'
EXEC add_BibleVerse @BibleId, 126039026, N'They will bear their shame for all their unfaithful acts against me, when they live securely on their land with no one to make them afraid.'
EXEC add_BibleVerse @BibleId, 126039027, N'When I have brought them back from the peoples and gathered them from the countries of their enemies, I will magnify myself among them in the sight of many nations.'
EXEC add_BibleVerse @BibleId, 126039028, N'Then they will know that I am the Lord their God, because I sent them into exile among the nations, and then gathered them into their own land. I will not leave any of them in exile any longer.'
EXEC add_BibleVerse @BibleId, 126039029, N'I will no longer hide my face from them, when I pour out my Spirit on the house of Israel, declares the sovereign Lord.”'
EXEC add_BibleVerse @BibleId, 126040001, N'In the twenty-fifth year of our exile, at the beginning of the year, on the tenth day of the month, in the fourteenth year after the city was struck down, on this very day, the hand of the Lord was on me, and he brought me there.'
EXEC add_BibleVerse @BibleId, 126040002, N'By means of divine visions he brought me to the land of Israel and placed me on a very high mountain, and on it was a structure like a city, to the south.'
EXEC add_BibleVerse @BibleId, 126040003, N'When he brought me there, I saw a man whose appearance was like bronze, with a linen cord and a measuring stick in his hand. He was standing in the gateway.'
EXEC add_BibleVerse @BibleId, 126040004, N'The man said to me, “Son of man, watch closely, listen carefully, and pay attention to everything I show you, for you have been brought here so that I can show it to you. Tell the house of Israel everything you see.”'
EXEC add_BibleVerse @BibleId, 126040005, N'I saw a wall all around the outside of the temple. In the man’s hand was a measuring stick 10½ feet long. He measured the thickness of the wall as 10½ feet, and its height as 10½ feet.'
EXEC add_BibleVerse @BibleId, 126040006, N'Then he went to the gate facing east. He climbed its steps and measured the threshold of the gate as 10½ feet deep.'
EXEC add_BibleVerse @BibleId, 126040007, N'The alcoves were 10½ feet long and 10½ feet wide; between the alcoves were 8¾ feet. The threshold of the gate by the porch of the gate facing inward was 10½ feet.'
EXEC add_BibleVerse @BibleId, 126040008, N'Then he measured the porch of the gate facing inward as 10½ feet.'
EXEC add_BibleVerse @BibleId, 126040009, N'He measured the porch of the gate as 14 feet, and its jambs as 3½ feet; the porch of the gate faced inward.'
EXEC add_BibleVerse @BibleId, 126040010, N'There were three alcoves on each side of the east gate; the three had the same measurement, and the jambs on either side had the same measurement.'
EXEC add_BibleVerse @BibleId, 126040011, N'He measured the width of the entrance of the gateway as 17½ feet, and the length of the gateway as 22¾ feet.'
EXEC add_BibleVerse @BibleId, 126040012, N'There was a barrier in front of the alcoves, 1¾ feet on either side; the alcoves were 10½ feet on either side.'
EXEC add_BibleVerse @BibleId, 126040013, N'He measured the gateway from the roof of one alcove to the roof of the other, a width of 43¾ feet from one entrance to the opposite one.'
EXEC add_BibleVerse @BibleId, 126040014, N'He measured the porch at 105 feet high; the gateway went all around to the jamb of the courtyard.'
EXEC add_BibleVerse @BibleId, 126040015, N'From the front of the entrance gate to the porch of the inner gate was 87½ feet.'
EXEC add_BibleVerse @BibleId, 126040016, N'There were closed windows toward the alcoves and toward their jambs within the gate all around, and likewise for the porches. There were windows all around the inside, and on each jamb were decorative palm trees.'
EXEC add_BibleVerse @BibleId, 126040017, N'Then he brought me to the outer court. I saw chambers there, and a pavement made for the court all around; thirty chambers faced the pavement.'
EXEC add_BibleVerse @BibleId, 126040018, N'The pavement was beside the gates, corresponding to the length of the gates; this was the lower pavement.'
EXEC add_BibleVerse @BibleId, 126040019, N'Then he measured the width from before the lower gate to the front of the exterior of the inner court as 175 feet on the east and on the north.'
EXEC add_BibleVerse @BibleId, 126040020, N'He measured the length and width of the gate of the outer court which faces north.'
EXEC add_BibleVerse @BibleId, 126040021, N'Its alcoves, three on each side, and its jambs and porches had the same measurement as the first gate; 87½ feet long and 43¾ feet wide.'
EXEC add_BibleVerse @BibleId, 126040022, N'Its windows, its porches, and its decorative palm trees had the same measurement as the gate which faced east. Seven steps led up to it, and its porch was in front of them.'
EXEC add_BibleVerse @BibleId, 126040023, N'Opposite the gate on the north and the east was a gate of the inner court; he measured the distance from gate to gate at 175 feet.'
EXEC add_BibleVerse @BibleId, 126040024, N'Then he led me toward the south. I saw a gate on the south. He measured its jambs and its porches; they had the same dimensions as the others.'
EXEC add_BibleVerse @BibleId, 126040025, N'There were windows all around it and its porches, like the windows of the others; 87½ feet long and 43¾ feet wide.'
EXEC add_BibleVerse @BibleId, 126040026, N'There were seven steps going up to it; its porches were in front of them. It had decorative palm trees on its jambs, one on either side.'
EXEC add_BibleVerse @BibleId, 126040027, N'The inner court had a gate toward the south; he measured it from gate to gate toward the south as 175 feet.'
EXEC add_BibleVerse @BibleId, 126040028, N'Then he brought me to the inner court by the south gate. He measured the south gate; it had the same dimensions as the others.'
EXEC add_BibleVerse @BibleId, 126040029, N'Its alcoves, its jambs, and its porches had the same dimensions as the others, and there were windows all around it and its porches; its length was 87½ feet and its width 43¾ feet.'
EXEC add_BibleVerse @BibleId, 126040030, N'There were porches all around, 43¾ feet long and 8¾ feet wide.'
EXEC add_BibleVerse @BibleId, 126040031, N'Its porches faced the outer court, and decorative palm trees were on its jambs, and its stairway had eight steps.'
EXEC add_BibleVerse @BibleId, 126040032, N'Then he brought me to the inner court on the east side. He measured the gate; it had the same dimensions as the others.'
EXEC add_BibleVerse @BibleId, 126040033, N'Its alcoves, its jambs, and its porches had the same dimensions as the others, and there were windows all around it and its porches; its length was 87½ feet and its width 43¾ feet.'
EXEC add_BibleVerse @BibleId, 126040034, N'Its porches faced the outer court, it had decorative palm trees on its jambs, and its stairway had eight steps.'
EXEC add_BibleVerse @BibleId, 126040035, N'Then he brought me to the north gate, and he measured it; it had the same dimensions as the others –'
EXEC add_BibleVerse @BibleId, 126040036, N'its alcoves, its jambs, and its porches. It had windows all around it; its length was 87½ feet and its width 43¾ feet.'
EXEC add_BibleVerse @BibleId, 126040037, N'Its jambs faced the outer court, and it had decorative palm trees on its jambs, on either side, and its stairway had eight steps.'
EXEC add_BibleVerse @BibleId, 126040038, N'There was a chamber with its door by the porch of the gate; there they washed the burnt offering.'
EXEC add_BibleVerse @BibleId, 126040039, N'In the porch of the gate were two tables on either side on which to slaughter the burnt offering, the sin offering, and the guilt offering.'
EXEC add_BibleVerse @BibleId, 126040040, N'On the outside of the porch as one goes up at the entrance of the north gate were two tables, and on the other side of the porch of the gate were two tables.'
EXEC add_BibleVerse @BibleId, 126040041, N'Four tables were on each side of the gate, eight tables on which the sacrifices were to be slaughtered.'
EXEC add_BibleVerse @BibleId, 126040042, N'The four tables for the burnt offering were of carved stone, 32 inches long, 32 inches wide, and 21 inches high. They would put the instruments which they used to slaughter the burnt offering and the sacrifice on them.'
EXEC add_BibleVerse @BibleId, 126040043, N'There were hooks three inches long, fastened in the house all around, and on the tables was the flesh of the offering.'
EXEC add_BibleVerse @BibleId, 126040044, N'On the outside of the inner gate were chambers for the singers of the inner court, one at the side of the north gate facing south, and the other at the side of the south gate facing north.'
EXEC add_BibleVerse @BibleId, 126040045, N'He said to me, “This chamber which faces south is for the priests who keep charge of the temple,'
EXEC add_BibleVerse @BibleId, 126040046, N'and the chamber which faces north is for the priests who keep charge of the altar. These are the descendants of Zadok, from the descendants of Levi, who may approach the Lord to minister to him.”'
EXEC add_BibleVerse @BibleId, 126040047, N'He measured the court as a square 175 feet long and 175 feet wide; the altar was in front of the temple.'
EXEC add_BibleVerse @BibleId, 126040048, N'Then he brought me to the porch of the temple and measured the jambs of the porch as 8¾ feet on either side, and the width of the gate was 24½ feet and the sides were 5¼ feet on each side.'
EXEC add_BibleVerse @BibleId, 126040049, N'The length of the porch was 35 feet and the width 19¼ feet; steps led up to it, and there were pillars beside the jambs on either side.'
EXEC add_BibleVerse @BibleId, 126041001, N'Then he brought me to the outer sanctuary, and measured the jambs; the jambs were 10½ feet wide on each side.'
EXEC add_BibleVerse @BibleId, 126041002, N'The width of the entrance was 17½ feet, and the sides of the entrance were 8¾ feet on each side. He measured the length of the outer sanctuary as 70 feet, and its width as 35 feet.'
EXEC add_BibleVerse @BibleId, 126041003, N'Then he went into the inner sanctuary and measured the jambs of the entrance as 3½ feet, the entrance as 10½ feet, and the width of the entrance as 12¼ feet'
EXEC add_BibleVerse @BibleId, 126041004, N'Then he measured its length as 35 feet, and its width as 35 feet, before the outer sanctuary. He said to me, “This is the most holy place.”'
EXEC add_BibleVerse @BibleId, 126041005, N'Then he measured the wall of the temple as 10½ feet, and the width of the side chambers as 7 feet, all around the temple.'
EXEC add_BibleVerse @BibleId, 126041006, N'The side chambers were in three stories, one above the other, thirty in each story. There were offsets in the wall all around to serve as supports for the side chambers, so that the supports were not in the wall of the temple.'
EXEC add_BibleVerse @BibleId, 126041007, N'The side chambers surrounding the temple were wider at each successive story; for the structure surrounding the temple went up story by story all around the temple. For this reason the width of the temple increased as it went up, and one went up from the lowest story to the highest by the way of the middle story.'
EXEC add_BibleVerse @BibleId, 126041008, N'I saw that the temple had a raised platform all around; the foundations of the side chambers were a full measuring stick of 10½ feet high.'
EXEC add_BibleVerse @BibleId, 126041009, N'The width of the outer wall of the side chambers was 8¾ feet, and the open area between the side chambers of the temple'
EXEC add_BibleVerse @BibleId, 126041010, N'and the chambers of the court was 35 feet in width all around the temple on every side.'
EXEC add_BibleVerse @BibleId, 126041011, N'There were entrances from the side chambers toward the open area, one entrance toward the north, and another entrance toward the south; the width of the open area was 8¾ feet all around.'
EXEC add_BibleVerse @BibleId, 126041012, N'The building that was facing the temple courtyard at the west side was 122½ feet wide; the wall of the building was 8¾ feet all around, and its length 157½ feet.'
EXEC add_BibleVerse @BibleId, 126041013, N'Then he measured the temple as 175 feet long, the courtyard of the temple and the building and its walls as 175 feet long,'
EXEC add_BibleVerse @BibleId, 126041014, N'and also the width of the front of the temple and the courtyard on the east as 175 feet.'
EXEC add_BibleVerse @BibleId, 126041015, N'Then he measured the length of the building facing the courtyard at the rear of the temple, with its galleries on either side as 175 feet. The interior of the outer sanctuary and the porch of the court,'
EXEC add_BibleVerse @BibleId, 126041016, N'as well as the thresholds, narrow windows and galleries all around on three sides facing the threshold were paneled with wood all around, from the ground up to the windows (now the windows were covered),'
EXEC add_BibleVerse @BibleId, 126041017, N'to the space above the entrance, to the inner room, and on the outside, and on all the walls in the inner room and outside, by measurement.'
EXEC add_BibleVerse @BibleId, 126041018, N'It was made with cherubim and decorative palm trees, with a palm tree between each cherub. Each cherub had two faces:'
EXEC add_BibleVerse @BibleId, 126041019, N'a human face toward the palm tree on one side and a lion’s face toward the palm tree on the other side. They were carved on the whole temple all around;'
EXEC add_BibleVerse @BibleId, 126041020, N'from the ground to the area above the entrance, cherubim and decorative palm trees were carved on the wall of the outer sanctuary.'
EXEC add_BibleVerse @BibleId, 126041021, N'The doorposts of the outer sanctuary were square. In front of the sanctuary one doorpost looked just like the other.'
EXEC add_BibleVerse @BibleId, 126041022, N'The altar was of wood, 5¼ feet high, with its length 3½ feet; its corners, its length, and its walls were of wood. He said to me, “This is the table that is before the Lord.”'
EXEC add_BibleVerse @BibleId, 126041023, N'The outer sanctuary and the inner sanctuary each had a double door.'
EXEC add_BibleVerse @BibleId, 126041024, N'Each of the doors had two leaves, two swinging leaves; two leaves for one door and two leaves for the other.'
EXEC add_BibleVerse @BibleId, 126041025, N'On the doors of the outer sanctuary were carved cherubim and palm trees, like those carved on the walls, and there was a canopy of wood on the front of the outside porch.'
EXEC add_BibleVerse @BibleId, 126041026, N'There were narrow windows and decorative palm trees on either side of the side walls of the porch; this is what the side chambers of the temple and the canopies were like.'
EXEC add_BibleVerse @BibleId, 126042001, N'Then he led me out to the outer court, toward the north, and brought me to the chamber which was opposite the courtyard and opposite the building on the north.'
EXEC add_BibleVerse @BibleId, 126042002, N'Its length was 175 feet on the north side, and its width 87½ feet.'
EXEC add_BibleVerse @BibleId, 126042003, N'Opposite the 35 feet that belonged to the inner court, and opposite the pavement which belonged to the outer court, gallery faced gallery in the three stories.'
EXEC add_BibleVerse @BibleId, 126042004, N'In front of the chambers was a walkway on the inner side, 17½ feet wide at a distance of 1¾ feet, and their entrances were on the north.'
EXEC add_BibleVerse @BibleId, 126042005, N'Now the upper chambers were narrower, because the galleries took more space from them than from the lower and middle chambers of the building.'
EXEC add_BibleVerse @BibleId, 126042006, N'For they were in three stories and had no pillars like the pillars of the courts; therefore the upper chambers were set back from the ground more than the lower and upper ones.'
EXEC add_BibleVerse @BibleId, 126042007, N'As for the outer wall by the side of the chambers, toward the outer court facing the chambers, it was 87½ feet long.'
EXEC add_BibleVerse @BibleId, 126042008, N'For the chambers on the outer court were 87½ feet long, while those facing the temple were 175 feet long.'
EXEC add_BibleVerse @BibleId, 126042009, N'Below these chambers was a passage on the east side as one enters from the outer court.'
EXEC add_BibleVerse @BibleId, 126042010, N'At the beginning of the wall of the court toward the south, facing the courtyard and the building, were chambers'
EXEC add_BibleVerse @BibleId, 126042011, N'with a passage in front of them. They looked like the chambers on the north. Of the same length and width, and all their exits according to their arrangements and entrances'
EXEC add_BibleVerse @BibleId, 126042012, N'were the chambers which were toward the south. There was an opening at the head of the passage, the passage in front of the corresponding wall toward the east when one enters.'
EXEC add_BibleVerse @BibleId, 126042013, N'Then he said to me, “The north chambers and the south chambers which face the courtyard are holy chambers where the priests who approach the Lord will eat the most holy offerings. There they will place the most holy offerings – the grain offering, the sin offering, and the guilt offering, because the place is holy.'
EXEC add_BibleVerse @BibleId, 126042014, N'When the priests enter, then they will not go out from the sanctuary to the outer court without taking off their garments in which they minister, for these are holy; they will put on other garments, then they will go near the places where the people are.”'
EXEC add_BibleVerse @BibleId, 126042015, N'Now when he had finished measuring the interior of the temple, he led me out by the gate which faces east and measured all around.'
EXEC add_BibleVerse @BibleId, 126042016, N'He measured the east side with the measuring stick as 875 feet by the measuring stick.'
EXEC add_BibleVerse @BibleId, 126042017, N'He measured the north side as 875 feet by the measuring stick.'
EXEC add_BibleVerse @BibleId, 126042018, N'He measured the south side as 875 feet by the measuring stick.'
EXEC add_BibleVerse @BibleId, 126042019, N'He turned to the west side and measured 875 feet by the measuring stick.'
EXEC add_BibleVerse @BibleId, 126042020, N'He measured it on all four sides. It had a wall around it, 875 feet long and 875 feet wide, to separate the holy and common places.'
EXEC add_BibleVerse @BibleId, 126043001, N'Then he brought me to the gate that faced toward the east.'
EXEC add_BibleVerse @BibleId, 126043002, N'I saw the glory of the God of Israel coming from the east; the sound was like that of rushing water; and the earth radiated his glory.'
EXEC add_BibleVerse @BibleId, 126043003, N'It was like the vision I saw when he came to destroy the city, and the vision I saw by the Kebar River. I threw myself face down.'
EXEC add_BibleVerse @BibleId, 126043004, N'The glory of the Lord came into the temple by way of the gate that faces east.'
EXEC add_BibleVerse @BibleId, 126043005, N'Then a wind lifted me up and brought me to the inner court; I watched the glory of the Lord filling the temple.'
EXEC add_BibleVerse @BibleId, 126043006, N'I heard someone speaking to me from the temple, while the man was standing beside me.'
EXEC add_BibleVerse @BibleId, 126043007, N'He said to me: “Son of man, this is the place of my throne and the place for the soles of my feet, where I will live among the people of Israel forever. The house of Israel will no longer profane my holy name, neither they nor their kings, by their spiritual prostitution or by the pillars of their kings set up when they die.'
EXEC add_BibleVerse @BibleId, 126043008, N'When they placed their threshold by my threshold and their doorpost by my doorpost, with only the wall between me and them, they profaned my holy name by the abominable deeds they committed. So I consumed them in my anger.'
EXEC add_BibleVerse @BibleId, 126043009, N'Now they must put away their spiritual prostitution and the pillars of their kings far from me, and then I will live among them forever.'
EXEC add_BibleVerse @BibleId, 126043010, N'“As for you, son of man, describe the temple to the house of Israel, so that they will be ashamed of their sins and measure the pattern.'
EXEC add_BibleVerse @BibleId, 126043011, N'When they are ashamed of all that they have done, make known to them the design of the temple, its pattern, its exits and entrances, and its whole design – all its statutes, its entire design, and all its laws; write it all down in their sight, so that they may observe its entire design and all its statutes and do them.'
EXEC add_BibleVerse @BibleId, 126043012, N'“This is the law of the temple: The entire area on top of the mountain all around will be most holy. Indeed, this is the law of the temple.'
EXEC add_BibleVerse @BibleId, 126043013, N'“And these are the measurements of the altar: Its base is 1¾ feet high, and 1¾ feet wide, and its border nine inches on its edge. This is to be the height of the altar.'
EXEC add_BibleVerse @BibleId, 126043014, N'From the base of the ground to the lower edge is 3½ feet, and the width 1¾ feet; and from the smaller ledge to the larger edge, 7 feet, and the width 1¾ feet;'
EXEC add_BibleVerse @BibleId, 126043015, N'and the altar hearth, 7 feet, and from the altar hearth four horns projecting upward.'
EXEC add_BibleVerse @BibleId, 126043016, N'Now the altar hearth is a perfect square, 21 feet long and 21 feet wide.'
EXEC add_BibleVerse @BibleId, 126043017, N'The ledge is 24½ feet long and 24½ feet wide on four sides; the border around it is 10½ inches, and its surrounding base 1¾ feet. Its steps face east.”'
EXEC add_BibleVerse @BibleId, 126043018, N'Then he said to me: “Son of man, this is what the sovereign Lord says: These are the statutes of the altar: On the day it is built to offer up burnt offerings on it and to sprinkle blood on it,'
EXEC add_BibleVerse @BibleId, 126043019, N'you will give a young bull for a sin offering to the Levitical priests who are descended from Zadok, who approach me to minister to me, declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126043020, N'You will take some of its blood, and place it on the four horns of the altar, on the four corners of the ledge, and on the border all around; you will cleanse it and make atonement for it.'
EXEC add_BibleVerse @BibleId, 126043021, N'You will also take the bull for the sin offering, and it will be burned in the appointed place in the temple, outside the sanctuary.'
EXEC add_BibleVerse @BibleId, 126043022, N'“On the second day, you will offer a male goat without blemish for a sin offering. They will purify the altar just as they purified it with the bull.'
EXEC add_BibleVerse @BibleId, 126043023, N'When you have finished purifying it, you will offer an unblemished young bull and an unblemished ram from the flock.'
EXEC add_BibleVerse @BibleId, 126043024, N'You will present them before the Lord, and the priests will scatter salt on them and offer them up as a burnt offering to the Lord.'
EXEC add_BibleVerse @BibleId, 126043025, N'“For seven days you will provide every day a goat for a sin offering; a young bull and a ram from the flock, both without blemish, will be provided.'
EXEC add_BibleVerse @BibleId, 126043026, N'For seven days they will make atonement for the altar and cleanse it, so they will consecrate it.'
EXEC add_BibleVerse @BibleId, 126043027, N'When the prescribed period is over, on the eighth day and thereafter the priests will offer up on the altar your burnt offerings and your peace offerings; I will accept you, declares the sovereign Lord.”'
EXEC add_BibleVerse @BibleId, 126044001, N'Then he brought me back by way of the outer gate of the sanctuary which faces east, but it was shut.'
EXEC add_BibleVerse @BibleId, 126044002, N'The Lord said to me: “This gate will be shut; it will not be opened, and no one will enter by it. For the Lord, the God of Israel, has entered by it; therefore it will remain shut.'
EXEC add_BibleVerse @BibleId, 126044003, N'Only the prince may sit in it to eat a sacrificial meal before the Lord; he will enter by way of the porch of the gate and will go out by the same way.”'
EXEC add_BibleVerse @BibleId, 126044004, N'Then he brought me by way of the north gate to the front of the temple. As I watched, I noticed the glory of the Lord filling the Lord’s temple, and I threw myself face down.'
EXEC add_BibleVerse @BibleId, 126044005, N'The Lord said to me: “Son of man, pay attention, watch closely and listen carefully to everything I tell you concerning all the statutes of the Lord’s house and all its laws. Pay attention to the entrances to the temple with all the exits of the sanctuary.'
EXEC add_BibleVerse @BibleId, 126044006, N'Say to the rebellious, to the house of Israel, ‘This is what the sovereign Lord says: Enough of all your abominable practices, O house of Israel!'
EXEC add_BibleVerse @BibleId, 126044007, N'When you bring foreigners, those uncircumcised in heart and in flesh, into my sanctuary, you desecrate it – even my house – when you offer my food, the fat and the blood. You have broken my covenant by all your abominable practices.'
EXEC add_BibleVerse @BibleId, 126044008, N'You have not kept charge of my holy things, but you have assigned foreigners to keep charge of my sanctuary for you.'
EXEC add_BibleVerse @BibleId, 126044009, N'This is what the sovereign Lord says: No foreigner, who is uncircumcised in heart and flesh among all the foreigners who are among the people of Israel, will enter into my sanctuary.'
EXEC add_BibleVerse @BibleId, 126044010, N'“‘But the Levites who went far from me, straying off from me after their idols when Israel went astray, will be responsible for their sin.'
EXEC add_BibleVerse @BibleId, 126044011, N'Yet they will be ministers in my sanctuary, having oversight at the gates of the temple, and serving the temple. They will slaughter the burnt offerings and the sacrifices for the people, and they will stand before them to minister to them.'
EXEC add_BibleVerse @BibleId, 126044012, N'Because they used to minister to them before their idols, and became a sinful obstacle to the house of Israel, consequently I have made a vow concerning them, declares the sovereign Lord, that they will be responsible for their sin.'
EXEC add_BibleVerse @BibleId, 126044013, N'They will not come near me to serve me as priest, nor will they come near any of my holy things, the things which are most sacred. They will bear the shame of the abominable deeds they have committed.'
EXEC add_BibleVerse @BibleId, 126044014, N'Yet I will appoint them to keep charge of the temple, all of its service and all that will be done in it.'
EXEC add_BibleVerse @BibleId, 126044015, N'“‘But the Levitical priests, the descendants of Zadok who kept the charge of my sanctuary when the people of Israel went astray from me, will approach me to minister to me; they will stand before me to offer me the fat and the blood, declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126044016, N'They will enter my sanctuary, and approach my table to minister to me; they will keep my charge.'
EXEC add_BibleVerse @BibleId, 126044017, N'“‘When they enter the gates of the inner court, they must wear linen garments; they must not have any wool on them when they minister in the inner gates of the court and in the temple.'
EXEC add_BibleVerse @BibleId, 126044018, N'Linen turbans will be on their heads and linen undergarments will be around their waists; they must not bind themselves with anything that causes sweat.'
EXEC add_BibleVerse @BibleId, 126044019, N'When they go out to the outer court to the people, they must remove the garments they were ministering in, and place them in the holy chambers; they must put on other garments so that they will not transmit holiness to the people with their garments.'
EXEC add_BibleVerse @BibleId, 126044020, N'“‘They must not shave their heads nor let their hair grow long; they must only trim their heads.'
EXEC add_BibleVerse @BibleId, 126044021, N'No priest may drink wine when he enters the inner court.'
EXEC add_BibleVerse @BibleId, 126044022, N'They must not marry a widow or a divorcee, but they may marry a virgin from the house of Israel or a widow who is a priest’s widow.'
EXEC add_BibleVerse @BibleId, 126044023, N'Moreover, they will teach my people the difference between the holy and the common, and show them how to distinguish between the ceremonially unclean and the clean.'
EXEC add_BibleVerse @BibleId, 126044024, N'“‘In a controversy they will act as judges; they will judge according to my ordinances. They will keep my laws and my statutes regarding all my appointed festivals and will observe my Sabbaths.'
EXEC add_BibleVerse @BibleId, 126044025, N'“‘They must not come near a dead person or they will be defiled; however, for father, mother, son, daughter, brother or sister, they may defile themselves.'
EXEC add_BibleVerse @BibleId, 126044026, N'After a priest has become ceremonially clean, they must count off a period of seven days for him.'
EXEC add_BibleVerse @BibleId, 126044027, N'On the day he enters the sanctuary, into the inner court to serve in the sanctuary, he must offer his sin offering, declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126044028, N'“‘This will be their inheritance: I am their inheritance, and you must give them no property in Israel; I am their property.'
EXEC add_BibleVerse @BibleId, 126044029, N'They may eat the grain offering, the sin offering, and the guilt offering, and every devoted thing in Israel will be theirs.'
EXEC add_BibleVerse @BibleId, 126044030, N'The first of all the first fruits and all contributions of any kind will be for the priests; you will also give to the priest the first portion of your dough, so that a blessing may rest on your house.'
EXEC add_BibleVerse @BibleId, 126044031, N'The priests will not eat any bird or animal that has died a natural death or was torn to pieces by a wild animal.'
EXEC add_BibleVerse @BibleId, 126045001, N'“‘When you allot the land as an inheritance, you will offer an allotment to the Lord, a holy portion from the land; the length will be eight and a quarter miles and the width three and one-third miles. This entire area will be holy.'
EXEC add_BibleVerse @BibleId, 126045002, N'Of this area a square 875 feet by 875 feet will be designated for the sanctuary, with 87½ feet set aside for its open space round about.'
EXEC add_BibleVerse @BibleId, 126045003, N'From this measured area you will measure a length of eight and a quarter miles and a width of three and one-third miles; in it will be the sanctuary, the most holy place.'
EXEC add_BibleVerse @BibleId, 126045004, N'It will be a holy portion of the land; it will be for the priests, the ministers of the sanctuary who approach the Lord to minister to him. It will be a place for their houses and a holy place for the sanctuary.'
EXEC add_BibleVerse @BibleId, 126045005, N'An area eight and a quarter miles in length and three and one-third miles in width will be for the Levites, who minister at the temple, as the place for the cities in which they will live.'
EXEC add_BibleVerse @BibleId, 126045006, N'“‘Alongside the portion set apart as the holy allotment, you will allot for the city an area one and two-thirds miles wide and eight and a quarter miles long; it will be for the whole house of Israel.'
EXEC add_BibleVerse @BibleId, 126045007, N'“‘For the prince there will be land on both sides of the holy allotment and the allotted city, alongside the holy allotment and the allotted city, on the west side and on the east side; it will be comparable in length to one of the portions, from the west border to the east border'
EXEC add_BibleVerse @BibleId, 126045008, N'of the land. This will be his property in Israel. My princes will no longer oppress my people, but the land will be allotted to the house of Israel according to their tribes.'
EXEC add_BibleVerse @BibleId, 126045009, N'“‘This is what the sovereign Lord says: Enough, you princes of Israel! Put away violence and destruction, and do what is just and right. Put an end to your evictions of my people, declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126045010, N'You must use just balances, a just dry measure (an ephah), and a just liquid measure (a bath).'
EXEC add_BibleVerse @BibleId, 126045011, N'The dry and liquid measures will be the same, the bath will contain a tenth of a homer, and the ephah a tenth of a homer; the homer will be the standard measure.'
EXEC add_BibleVerse @BibleId, 126045012, N'The shekel will be twenty gerahs. Sixty shekels will be a mina for you.'
EXEC add_BibleVerse @BibleId, 126045013, N'“‘This is the offering you must offer: a sixth of an ephah from a homer of wheat; a sixth of an ephah from a homer of barley,'
EXEC add_BibleVerse @BibleId, 126045014, N'and as the prescribed portion of olive oil, one tenth of a bath from each kor (which is ten baths or a homer, for ten baths make a homer);'
EXEC add_BibleVerse @BibleId, 126045015, N'and one sheep from each flock of two hundred, from the watered places of Israel, for a grain offering, burnt offering, and peace offering, to make atonement for them, declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126045016, N'All the people of the land will contribute to this offering for the prince of Israel.'
EXEC add_BibleVerse @BibleId, 126045017, N'It will be the duty of the prince to provide the burnt offerings, the grain offering, and the drink offering at festivals, on the new moons and Sabbaths, at all the appointed feasts of the house of Israel; he will provide the sin offering, the grain offering, the burnt offering, and the peace offerings to make atonement for the house of Israel.'
EXEC add_BibleVerse @BibleId, 126045018, N'“‘This is what the sovereign Lord says: In the first month, on the first day of the month, you must take an unblemished young bull and purify the sanctuary.'
EXEC add_BibleVerse @BibleId, 126045019, N'The priest will take some of the blood of the sin offering and place it on the doorpost of the temple, on the four corners of the ledge of the altar, and on the doorpost of the gate of the inner court.'
EXEC add_BibleVerse @BibleId, 126045020, N'This is what you must do on the seventh day of the month for anyone who sins inadvertently or through ignorance; so you will make atonement for the temple.'
EXEC add_BibleVerse @BibleId, 126045021, N'“‘In the first month, on the fourteenth day of the month, you will celebrate the Passover, and for seven days bread made without yeast will be eaten.'
EXEC add_BibleVerse @BibleId, 126045022, N'On that day the prince will provide for himself and for all the people of the land a bull for a sin offering.'
EXEC add_BibleVerse @BibleId, 126045023, N'And during the seven days of the feast he will provide as a burnt offering to the Lord seven bulls and seven rams, all without blemish, on each of the seven days, and a male goat daily for a sin offering.'
EXEC add_BibleVerse @BibleId, 126045024, N'He will provide as a grain offering an ephah for each bull, an ephah for each ram, and a gallon of olive oil for each ephah of grain.'
EXEC add_BibleVerse @BibleId, 126045025, N'In the seventh month, on the fifteenth day of the month, at the feast, he will make the same provisions for the sin offering, burnt offering, and grain offering, and for the olive oil, for the seven days.'
EXEC add_BibleVerse @BibleId, 126046001, N'“‘This is what the sovereign Lord says: The gate of the inner court that faces east will be closed six working days, but on the Sabbath day it will be opened and on the day of the new moon it will be opened.'
EXEC add_BibleVerse @BibleId, 126046002, N'The prince will enter by way of the porch of the gate from the outside, and will stand by the doorpost of the gate. The priests will provide his burnt offering and his peace offerings, and he will bow down at the threshold of the gate and then go out. But the gate will not be closed until evening.'
EXEC add_BibleVerse @BibleId, 126046003, N'The people of the land will bow down at the entrance of that gate before the Lord on the Sabbaths and on the new moons.'
EXEC add_BibleVerse @BibleId, 126046004, N'The burnt offering which the prince will offer to the Lord on the Sabbath day will be six unblemished lambs and one unblemished ram.'
EXEC add_BibleVerse @BibleId, 126046005, N'The grain offering will be an ephah with the ram, and the grain offering with the lambs will be as much as he is able to give, and a gallon of olive oil with an ephah.'
EXEC add_BibleVerse @BibleId, 126046006, N'On the day of the new moon he will offer an unblemished young bull, and six lambs and a ram, all without blemish.'
EXEC add_BibleVerse @BibleId, 126046007, N'He will provide a grain offering: an ephah with the bull and an ephah with the ram, and with the lambs as much as he wishes, and a gallon of olive oil with each ephah of grain.'
EXEC add_BibleVerse @BibleId, 126046008, N'When the prince enters, he will come by way of the porch of the gate and will go out the same way.'
EXEC add_BibleVerse @BibleId, 126046009, N'“‘When the people of the land come before the Lord at the appointed feasts, whoever enters by way of the north gate to worship will go out by way of the south gate; whoever enters by way of the south gate will go out by way of the north gate. No one will return by way of the gate they entered but will go out straight ahead.'
EXEC add_BibleVerse @BibleId, 126046010, N'When they come in, the prince will come in with them, and when they go out, he will go out.'
EXEC add_BibleVerse @BibleId, 126046011, N'“‘At the festivals and at the appointed feasts the grain offering will be an ephah with the bull and an ephah with the ram, and with the lambs as much as one is able, and a gallon of olive oil with each ephah of grain.'
EXEC add_BibleVerse @BibleId, 126046012, N'When the prince provides a freewill offering, a burnt offering, or peace offerings as a voluntary offering to the Lord, the gate facing east will be opened for him, and he will provide his burnt offering and his peace offerings just as he did on the Sabbath. Then he will go out, and the gate will be closed after he goes out.'
EXEC add_BibleVerse @BibleId, 126046013, N'“‘You will provide a lamb a year old without blemish for a burnt offering daily to the Lord; morning by morning he will provide it.'
EXEC add_BibleVerse @BibleId, 126046014, N'And you will provide a grain offering with it morning by morning, a sixth of an ephah, and a third of a gallon of olive oil to moisten the choice flour, as a grain offering to the Lord; this is a perpetual statute.'
EXEC add_BibleVerse @BibleId, 126046015, N'Thus they will provide the lamb, the grain offering, and the olive oil morning by morning, as a perpetual burnt offering.'
EXEC add_BibleVerse @BibleId, 126046016, N'“‘This is what the sovereign Lord says: If the prince should give a gift to one of his sons as his inheritance, it will belong to his sons, it is their property by inheritance.'
EXEC add_BibleVerse @BibleId, 126046017, N'But if he gives a gift from his inheritance to one of his servants, it will be his until the year of liberty; then it will revert to the prince. His inheritance will only remain with his sons.'
EXEC add_BibleVerse @BibleId, 126046018, N'The prince will not take away any of the people’s inheritance by oppressively removing them from their property. He will give his sons an inheritance from his own possessions so that my people will not be scattered, each from his own property.’”'
EXEC add_BibleVerse @BibleId, 126046019, N'Then he brought me through the entrance, which was at the side of the gate, into the holy chambers for the priests which faced north. There I saw a place at the extreme western end.'
EXEC add_BibleVerse @BibleId, 126046020, N'He said to me, “This is the place where the priests will boil the guilt offering and the sin offering, and where they will bake the grain offering, so that they do not bring them out to the outer court to transmit holiness to the people.”'
EXEC add_BibleVerse @BibleId, 126046021, N'Then he brought me out to the outer court and led me past the four corners of the court, and I noticed that in every corner of the court there was a court.'
EXEC add_BibleVerse @BibleId, 126046022, N'In the four corners of the court were small courts, 70 feet in length and 52½ feet in width; the four were all the same size.'
EXEC add_BibleVerse @BibleId, 126046023, N'There was a row of masonry around each of the four courts, and places for boiling offerings were made under the rows all around.'
EXEC add_BibleVerse @BibleId, 126046024, N'Then he said to me, “These are the houses for boiling, where the ministers of the temple boil the sacrifices of the people.”'
EXEC add_BibleVerse @BibleId, 126047001, N'Then he brought me back to the entrance of the temple. I noticed that water was flowing from under the threshold of the temple toward the east (for the temple faced east). The water was flowing down from under the right side of the temple, from south of the altar.'
EXEC add_BibleVerse @BibleId, 126047002, N'He led me out by way of the north gate and brought me around the outside of the outer gate that faces toward the east; I noticed that the water was trickling out from the south side.'
EXEC add_BibleVerse @BibleId, 126047003, N'When the man went out toward the east with a measuring line in his hand, he measured 1,750 feet, and then he led me through water, which was ankle deep.'
EXEC add_BibleVerse @BibleId, 126047004, N'Again he measured 1,750 feet and led me through the water, which was now knee deep. Once more he measured 1,750 feet and led me through the water, which was waist deep.'
EXEC add_BibleVerse @BibleId, 126047005, N'Again he measured 1,750 feet and it was a river I could not cross, for the water had risen; it was deep enough to swim in, a river that could not be crossed.'
EXEC add_BibleVerse @BibleId, 126047006, N'He said to me, “Son of man, have you seen this?” Then he led me back to the bank of the river.'
EXEC add_BibleVerse @BibleId, 126047007, N'When I had returned, I noticed a vast number of trees on the banks of the river, on both sides.'
EXEC add_BibleVerse @BibleId, 126047008, N'He said to me, “These waters go out toward the eastern region and flow down into the Arabah; when they enter the Dead Sea, where the sea is stagnant, the waters become fresh.'
EXEC add_BibleVerse @BibleId, 126047009, N'Every living creature which swarms where the river flows will live; there will be many fish, for these waters flow there. It will become fresh and everything will live where the river flows.'
EXEC add_BibleVerse @BibleId, 126047010, N'Fishermen will stand beside it; from Engedi to En-eglaim they will spread nets. They will catch many kinds of fish, like the fish of the Great Sea.'
EXEC add_BibleVerse @BibleId, 126047011, N'But its swamps and its marshes will not become fresh; they will remain salty.'
EXEC add_BibleVerse @BibleId, 126047012, N'On both sides of the river’s banks, every kind of tree will grow for food. Their leaves will not wither nor will their fruit fail, but they will bear fruit every month, because their water source flows from the sanctuary. Their fruit will be for food and their leaves for healing.”'
EXEC add_BibleVerse @BibleId, 126047013, N'This is what the sovereign Lord says: “Here are the borders you will observe as you allot the land to the twelve tribes of Israel. (Joseph will have two portions.)'
EXEC add_BibleVerse @BibleId, 126047014, N'You must divide it equally just as I vowed to give it to your forefathers; this land will be assigned as your inheritance.'
EXEC add_BibleVerse @BibleId, 126047015, N'“This will be the border of the land: On the north side, from the Great Sea by way of Hethlon to the entrance of Zedad;'
EXEC add_BibleVerse @BibleId, 126047016, N'Hamath, Berothah, Sibraim, which is between the border of Damascus and the border of Hamath, as far as Hazer-hattikon, which is on the border of Hauran.'
EXEC add_BibleVerse @BibleId, 126047017, N'The border will run from the sea to Hazar-enan, at the border of Damascus, and on the north is the border of Hamath. This is the north side.'
EXEC add_BibleVerse @BibleId, 126047018, N'On the east side, between Hauran and Damascus, and between Gilead and the land of Israel, will be the Jordan. You will measure from the border to the eastern sea. This is the east side.'
EXEC add_BibleVerse @BibleId, 126047019, N'On the south side it will run from Tamar to the waters of Meribath Kadesh, the river, to the Great Sea. This is the south side.'
EXEC add_BibleVerse @BibleId, 126047020, N'On the west side the Great Sea will be the boundary to a point opposite Lebo-hamath. This is the west side.'
EXEC add_BibleVerse @BibleId, 126047021, N'“This is how you will divide this land for yourselves among the tribes of Israel.'
EXEC add_BibleVerse @BibleId, 126047022, N'You must allot it as an inheritance among yourselves and for the foreigners who reside among you, who have fathered sons among you. You must treat them as native-born among the people of Israel; they will be allotted an inheritance with you among the tribes of Israel.'
EXEC add_BibleVerse @BibleId, 126047023, N'In whatever tribe the foreigner resides, there you will give him his inheritance,” declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126048001, N'“These are the names of the tribes: From the northern end beside the road of Hethlon to Lebo-hamath, as far as Hazar-enan (which is on the border of Damascus, toward the north beside Hamath), extending from the east side to the west, Dan will have one portion.'
EXEC add_BibleVerse @BibleId, 126048002, N'Next to the border of Dan, from the east side to the west, Asher will have one portion.'
EXEC add_BibleVerse @BibleId, 126048003, N'Next to the border of Asher from the east side to the west, Naphtali will have one portion.'
EXEC add_BibleVerse @BibleId, 126048004, N'Next to the border of Naphtali from the east side to the west, Manasseh will have one portion.'
EXEC add_BibleVerse @BibleId, 126048005, N'Next to the border of Manasseh from the east side to the west, Ephraim will have one portion.'
EXEC add_BibleVerse @BibleId, 126048006, N'Next to the border of Ephraim from the east side to the west, Reuben will have one portion.'
EXEC add_BibleVerse @BibleId, 126048007, N'Next to the border of Reuben from the east side to the west, Judah will have one portion.'
EXEC add_BibleVerse @BibleId, 126048008, N'“Next to the border of Judah from the east side to the west will be the allotment you must set apart. It is to be eight and a quarter miles wide, and the same length as one of the tribal portions, from the east side to the west; the sanctuary will be in the middle of it.'
EXEC add_BibleVerse @BibleId, 126048009, N'The allotment you set apart to the Lord will be eight and a quarter miles in length and three and one-third miles in width.'
EXEC add_BibleVerse @BibleId, 126048010, N'These will be the allotments for the holy portion: for the priests, toward the north eight and a quarter miles in length, toward the west three and one-third miles in width, toward the east three and one-third miles in width, and toward the south eight and a quarter miles in length; the sanctuary of the Lord will be in the middle.'
EXEC add_BibleVerse @BibleId, 126048011, N'This will be for the priests who are set apart from the descendants of Zadok who kept my charge and did not go astray when the people of Israel strayed off, like the Levites did.'
EXEC add_BibleVerse @BibleId, 126048012, N'It will be their portion from the allotment of the land, a most holy place, next to the border of the Levites.'
EXEC add_BibleVerse @BibleId, 126048013, N'“Alongside the border of the priests, the Levites will have an allotment eight and a quarter miles in length and three and one-third miles in width. The whole length will be eight and a quarter miles and the width three and one-third miles.'
EXEC add_BibleVerse @BibleId, 126048014, N'They must not sell or exchange any of it; they must not transfer this choice portion of land, for it is set apart to the Lord.'
EXEC add_BibleVerse @BibleId, 126048015, N'“The remainder, one and two-thirds miles in width and eight and a quarter miles in length, will be for common use by the city, for houses and for open space. The city will be in the middle of it;'
EXEC add_BibleVerse @BibleId, 126048016, N'these will be its measurements: The north side will be one and one-half miles, the south side one and one-half miles, the east side one and one-half miles, and the west side one and one-half miles.'
EXEC add_BibleVerse @BibleId, 126048017, N'The city will have open spaces: On the north there will be 437½ feet, on the south 437½ feet, on the east 437½ feet, and on the west 437½ feet.'
EXEC add_BibleVerse @BibleId, 126048018, N'The remainder of the length alongside the holy allotment will be three and one-third miles to the east and three and one-third miles toward the west, and it will be beside the holy allotment. Its produce will be for food for the workers of the city.'
EXEC add_BibleVerse @BibleId, 126048019, N'The workers of the city from all the tribes of Israel will cultivate it.'
EXEC add_BibleVerse @BibleId, 126048020, N'The whole allotment will be eight and a quarter miles square, you must set apart the holy allotment with the possession of the city.'
EXEC add_BibleVerse @BibleId, 126048021, N'“The rest, on both sides of the holy allotment and the property of the city, will belong to the prince. Extending from the eight and a quarter miles of the holy allotment to the east border, and westward from the eight and a quarter miles to the west border, alongside the portions, it will belong to the prince. The holy allotment and the sanctuary of the temple will be in the middle of it.'
EXEC add_BibleVerse @BibleId, 126048022, N'The property of the Levites and of the city will be in the middle of that which belongs to the prince. The portion between the border of Judah and the border of Benjamin will be for the prince.'
EXEC add_BibleVerse @BibleId, 126048023, N'“As for the rest of the tribes: From the east side to the west side, Benjamin will have one portion.'
EXEC add_BibleVerse @BibleId, 126048024, N'Next to the border of Benjamin, from the east side to the west side, Simeon will have one portion.'
EXEC add_BibleVerse @BibleId, 126048025, N'Next to the border of Simeon, from the east side to the west side, Issachar will have one portion.'
EXEC add_BibleVerse @BibleId, 126048026, N'Next to the border of Issachar, from the east side to the west side, Zebulun will have one portion.'
EXEC add_BibleVerse @BibleId, 126048027, N'Next to the border of Zebulun, from the east side to the west side, Gad will have one portion.'
EXEC add_BibleVerse @BibleId, 126048028, N'Next to the border of Gad, at the south side, the border will run from Tamar to the waters of Meribath Kadesh, to the Stream of Egypt and on to the Great Sea.'
EXEC add_BibleVerse @BibleId, 126048029, N'This is the land which you will allot to the tribes of Israel, and these are their portions, declares the sovereign Lord.'
EXEC add_BibleVerse @BibleId, 126048030, N'“These are the exits of the city: On the north side, one and one-half miles by measure,'
EXEC add_BibleVerse @BibleId, 126048031, N'the gates of the city will be named for the tribes of Israel; there will be three gates to the north: one gate for Reuben, one gate for Judah, and one gate for Levi.'
EXEC add_BibleVerse @BibleId, 126048032, N'On the east side, one and one-half miles in length, there will be three gates: one gate for Joseph, one gate for Benjamin, and one gate for Dan.'
EXEC add_BibleVerse @BibleId, 126048033, N'On the south side, one and one-half miles by measure, there will be three gates: one gate for Simeon, one gate for Issachar, and one gate for Zebulun.'
EXEC add_BibleVerse @BibleId, 126048034, N'On the west side, one and one-half miles in length, there will be three gates: one gate for Gad, one gate for Asher, and one gate for Naphtali.'
EXEC add_BibleVerse @BibleId, 126048035, N'The circumference of the city will be six miles. The name of the city from that day forward will be: ‘The Lord Is There.’”'
EXEC add_BibleVerse @BibleId, 127001001, N'In the third year of the reign of King Jehoiakim of Judah, King Nebuchadnezzar of Babylon advanced against Jerusalem and laid it under siege.'
EXEC add_BibleVerse @BibleId, 127001002, N'Now the Lord delivered King Jehoiakim of Judah into his power, along with some of the vessels of the temple of God. He brought them to the land of Babylonia to the temple of his god and put the vessels in the treasury of his god.'
EXEC add_BibleVerse @BibleId, 127001003, N'The king commanded Ashpenaz, who was in charge of his court officials, to choose some of the Israelites who were of royal and noble descent –'
EXEC add_BibleVerse @BibleId, 127001004, N'young men in whom there was no physical defect and who were handsome, well versed in all kinds of wisdom, well educated and having keen insight, and who were capable of entering the king’s royal service – and to teach them the literature and language of the Babylonians.'
EXEC add_BibleVerse @BibleId, 127001005, N'So the king assigned them a daily ration from his royal delicacies and from the wine he himself drank. They were to be trained for the next three years. At the end of that time they were to enter the king’s service.'
EXEC add_BibleVerse @BibleId, 127001006, N'As it turned out, among these young men were some from Judah: Daniel, Hananiah, Mishael, and Azariah.'
EXEC add_BibleVerse @BibleId, 127001007, N'But the overseer of the court officials renamed them. He gave Daniel the name Belteshazzar, Hananiah he named Shadrach, Mishael he named Meshach, and Azariah he named Abednego.'
EXEC add_BibleVerse @BibleId, 127001008, N'But Daniel made up his mind that he would not defile himself with the royal delicacies or the royal wine. He therefore asked the overseer of the court officials for permission not to defile himself.'
EXEC add_BibleVerse @BibleId, 127001009, N'Then God made the overseer of the court officials sympathetic to Daniel.'
EXEC add_BibleVerse @BibleId, 127001010, N'But he responded to Daniel, “I fear my master the king. He is the one who has decided your food and drink. What would happen if he saw that you looked malnourished in comparison to the other young men your age? If that happened, you would endanger my life with the king!”'
EXEC add_BibleVerse @BibleId, 127001011, N'Daniel then spoke to the warden whom the overseer of the court officials had appointed over Daniel, Hananiah, Mishael, and Azariah:'
EXEC add_BibleVerse @BibleId, 127001012, N'“Please test your servants for ten days by providing us with some vegetables to eat and water to drink.'
EXEC add_BibleVerse @BibleId, 127001013, N'Then compare our appearance with that of the young men who are eating the royal delicacies; deal with us in light of what you see.”'
EXEC add_BibleVerse @BibleId, 127001014, N'So the warden agreed to their proposal and tested them for ten days.'
EXEC add_BibleVerse @BibleId, 127001015, N'At the end of the ten days their appearance was better and their bodies were healthier than all the young men who had been eating the royal delicacies.'
EXEC add_BibleVerse @BibleId, 127001016, N'So the warden removed the delicacies and the wine from their diet and gave them a diet of vegetables instead.'
EXEC add_BibleVerse @BibleId, 127001017, N'Now as for these four young men, God endowed them with knowledge and skill in all sorts of literature and wisdom – and Daniel had insight into all kinds of visions and dreams.'
EXEC add_BibleVerse @BibleId, 127001018, N'When the time appointed by the king arrived, the overseer of the court officials brought them into Nebuchadnezzar’s presence.'
EXEC add_BibleVerse @BibleId, 127001019, N'When the king spoke with them, he did not find among the entire group anyone like Daniel, Hananiah, Mishael, or Azariah. So they entered the king’s service.'
EXEC add_BibleVerse @BibleId, 127001020, N'In every matter of wisdom and insight the king asked them about, he found them to be ten times better than any of the magicians and astrologers that were in his entire empire.'
EXEC add_BibleVerse @BibleId, 127001021, N'Now Daniel lived on until the first year of Cyrus the king.'
EXEC add_BibleVerse @BibleId, 127002001, N'In the second year of his reign Nebuchadnezzar had many dreams. His mind was disturbed and he suffered from insomnia.'
EXEC add_BibleVerse @BibleId, 127002002, N'The king issued an order to summon the magicians, astrologers, sorcerers, and wise men in order to explain his dreams to him. So they came and awaited the king’s instructions.'
EXEC add_BibleVerse @BibleId, 127002003, N'The king told them, “I have had a dream, and I am anxious to understand the dream.”'
EXEC add_BibleVerse @BibleId, 127002004, N'The wise men replied to the king: What follows is in Aramaic “O king, live forever! Tell your servants the dream, and we will disclose its interpretation.”'
EXEC add_BibleVerse @BibleId, 127002005, N'The king replied to the wise men, “My decision is firm. If you do not inform me of both the dream and its interpretation, you will be dismembered and your homes reduced to rubble!'
EXEC add_BibleVerse @BibleId, 127002006, N'But if you can disclose the dream and its interpretation, you will receive from me gifts, a reward, and considerable honor. So disclose to me the dream and its interpretation!”'
EXEC add_BibleVerse @BibleId, 127002007, N'They again replied, “Let the king inform us of the dream; then we will disclose its interpretation.”'
EXEC add_BibleVerse @BibleId, 127002008, N'The king replied, “I know for sure that you are attempting to gain time, because you see that my decision is firm.'
EXEC add_BibleVerse @BibleId, 127002009, N'If you don’t inform me of the dream, there is only one thing that is going to happen to you. For you have agreed among yourselves to report to me something false and deceitful until such time as things might change. So tell me the dream, and I will have confidence that you can disclose its interpretation.”'
EXEC add_BibleVerse @BibleId, 127002010, N'The wise men replied to the king, “There is no man on earth who is able to disclose the king’s secret, for no king, regardless of his position and power, has ever requested such a thing from any magician, astrologer, or wise man.'
EXEC add_BibleVerse @BibleId, 127002011, N'What the king is asking is too difficult, and no one exists who can disclose it to the king, except for the gods – but they don’t live among mortals!”'
EXEC add_BibleVerse @BibleId, 127002012, N'Because of this the king got furiously angry and gave orders to destroy all the wise men of Babylon.'
EXEC add_BibleVerse @BibleId, 127002013, N'So a decree went out, and the wise men were about to be executed. They also sought Daniel and his friends so that they could be executed.'
EXEC add_BibleVerse @BibleId, 127002014, N'Then Daniel spoke with prudent counsel to Arioch, who was in charge of the king’s executioners and who had gone out to execute the wise men of Babylon.'
EXEC add_BibleVerse @BibleId, 127002015, N'He inquired of Arioch the king’s deputy, “Why is the decree from the king so urgent?” Then Arioch informed Daniel about the matter.'
EXEC add_BibleVerse @BibleId, 127002016, N'So Daniel went in and requested the king to grant him time, that he might disclose the interpretation to the king.'
EXEC add_BibleVerse @BibleId, 127002017, N'Then Daniel went to his home and informed his friends Hananiah, Mishael, and Azariah of the matter.'
EXEC add_BibleVerse @BibleId, 127002018, N'He asked them to pray for mercy from the God of heaven concerning this mystery so that he and his friends would not be destroyed along with the rest of the wise men of Babylon.'
EXEC add_BibleVerse @BibleId, 127002019, N'Then in a night vision the mystery was revealed to Daniel. So Daniel praised the God of heaven,'
EXEC add_BibleVerse @BibleId, 127002020, N'saying, “Let the name of God be praised forever and ever, for wisdom and power belong to him.'
EXEC add_BibleVerse @BibleId, 127002021, N'He changes times and seasons, deposing some kings and establishing others. He gives wisdom to the wise; he imparts knowledge to those with understanding;'
EXEC add_BibleVerse @BibleId, 127002022, N'he reveals deep and hidden things. He knows what is in the darkness, and light resides with him.'
EXEC add_BibleVerse @BibleId, 127002023, N'O God of my fathers, I acknowledge and glorify you, for you have bestowed wisdom and power on me. Now you have enabled me to understand what I requested from you. For you have enabled me to understand the king’s dilemma.”'
EXEC add_BibleVerse @BibleId, 127002024, N'Then Daniel went in to see Arioch (whom the king had appointed to destroy the wise men of Babylon). He came and said to him, “Don’t destroy the wise men of Babylon! Escort me to the king, and I will disclose the interpretation to him!”'
EXEC add_BibleVerse @BibleId, 127002025, N'So Arioch quickly ushered Daniel into the king’s presence, saying to him, “I have found a man from the captives of Judah who can make known the interpretation to the king.”'
EXEC add_BibleVerse @BibleId, 127002026, N'The king then asked Daniel (whose name was also Belteshazzar), “Are you able to make known to me the dream that I saw, as well as its interpretation?”'
EXEC add_BibleVerse @BibleId, 127002027, N'Daniel replied to the king, “The mystery that the king is asking about is such that no wise men, astrologers, magicians, or diviners can possibly disclose it to the king.'
EXEC add_BibleVerse @BibleId, 127002028, N'However, there is a God in heaven who reveals mysteries, and he has made known to King Nebuchadnezzar what will happen in the times to come. The dream and the visions you had while lying on your bed are as follows.'
EXEC add_BibleVerse @BibleId, 127002029, N'“As for you, O king, while you were in your bed your thoughts turned to future things. The revealer of mysteries has made known to you what will take place.'
EXEC add_BibleVerse @BibleId, 127002030, N'As for me, this mystery was revealed to me not because I possess more wisdom than any other living person, but so that the king may understand the interpretation and comprehend the thoughts of your mind.'
EXEC add_BibleVerse @BibleId, 127002031, N'“You, O king, were watching as a great statue – one of impressive size and extraordinary brightness – was standing before you. Its appearance caused alarm.'
EXEC add_BibleVerse @BibleId, 127002032, N'As for that statue, its head was of fine gold, its chest and arms were of silver, its belly and thighs were of bronze.'
EXEC add_BibleVerse @BibleId, 127002033, N'Its legs were of iron; its feet were partly of iron and partly of clay.'
EXEC add_BibleVerse @BibleId, 127002034, N'You were watching as a stone was cut out, but not by human hands. It struck the statue on its iron and clay feet, breaking them in pieces.'
EXEC add_BibleVerse @BibleId, 127002035, N'Then the iron, clay, bronze, silver, and gold were broken in pieces without distinction and became like chaff from the summer threshing floors that the wind carries away. Not a trace of them could be found. But the stone that struck the statue became a large mountain that filled the entire earth.'
EXEC add_BibleVerse @BibleId, 127002036, N'This was the dream. Now we will set forth before the king its interpretation.'
EXEC add_BibleVerse @BibleId, 127002037, N'“You, O king, are the king of kings. The God of heaven has granted you sovereignty, power, strength, and honor.'
EXEC add_BibleVerse @BibleId, 127002038, N'Wherever human beings, wild animals, and birds of the sky live – he has given them into your power. He has given you authority over them all. You are the head of gold.'
EXEC add_BibleVerse @BibleId, 127002039, N'Now after you another kingdom will arise, one inferior to yours. Then a third kingdom, one of bronze, will rule in all the earth.'
EXEC add_BibleVerse @BibleId, 127002040, N'Then there will be a fourth kingdom, one strong like iron. Just like iron breaks in pieces and shatters everything, and as iron breaks in pieces all of these metals, so it will break in pieces and crush the others.'
EXEC add_BibleVerse @BibleId, 127002041, N'In that you were seeing feet and toes partly of wet clay and partly of iron, so this will be a divided kingdom. Some of the strength of iron will be in it, for you saw iron mixed with wet clay.'
EXEC add_BibleVerse @BibleId, 127002042, N'In that the toes of the feet were partly of iron and partly of clay, the latter stages of this kingdom will be partly strong and partly fragile.'
EXEC add_BibleVerse @BibleId, 127002043, N'And in that you saw iron mixed with wet clay, so people will be mixed with one another without adhering to one another, just as iron does not mix with clay.'
EXEC add_BibleVerse @BibleId, 127002044, N'In the days of those kings the God of heaven will raise up an everlasting kingdom that will not be destroyed and a kingdom that will not be left to another people. It will break in pieces and bring about the demise of all these kingdoms. But it will stand forever.'
EXEC add_BibleVerse @BibleId, 127002045, N'You saw that a stone was cut from a mountain, but not by human hands; it smashed the iron, bronze, clay, silver, and gold into pieces. The great God has made known to the king what will occur in the future. The dream is certain, and its interpretation is reliable.”'
EXEC add_BibleVerse @BibleId, 127002046, N'Then King Nebuchadnezzar bowed down with his face to the ground and paid homage to Daniel. He gave orders to offer sacrifice and incense to him.'
EXEC add_BibleVerse @BibleId, 127002047, N'The king replied to Daniel, “Certainly your God is a God of gods and Lord of kings and revealer of mysteries, for you were able to reveal this mystery!”'
EXEC add_BibleVerse @BibleId, 127002048, N'Then the king elevated Daniel to high position and bestowed on him many marvelous gifts. He granted him authority over the entire province of Babylon and made him the main prefect over all the wise men of Babylon.'
EXEC add_BibleVerse @BibleId, 127002049, N'And at Daniel’s request, the king appointed Shadrach, Meshach, and Abednego over the administration of the province of Babylon. Daniel himself served in the king’s court.'
EXEC add_BibleVerse @BibleId, 127003001, N'King Nebuchadnezzar had a golden statue made. It was ninety feet tall and nine feet wide. He erected it on the plain of Dura in the province of Babylon.'
EXEC add_BibleVerse @BibleId, 127003002, N'Then King Nebuchadnezzar sent out a summons to assemble the satraps, prefects, governors, counselors, treasurers, judges, magistrates, and all the other authorities of the province to attend the dedication of the statue that he had erected.'
EXEC add_BibleVerse @BibleId, 127003003, N'So the satraps, prefects, governors, counselors, treasurers, judges, magistrates, and all the other provincial authorities assembled for the dedication of the statue that King Nebuchadnezzar had erected. They were standing in front of the statue that Nebuchadnezzar had erected.'
EXEC add_BibleVerse @BibleId, 127003004, N'Then the herald made a loud proclamation: “To you, O peoples, nations, and language groups, the following command is given:'
EXEC add_BibleVerse @BibleId, 127003005, N'When you hear the sound of the horn, flute, zither, trigon, harp, pipes, and all kinds of music, you must bow down and pay homage to the golden statue that King Nebuchadnezzar has erected.'
EXEC add_BibleVerse @BibleId, 127003006, N'Whoever does not bow down and pay homage will immediately be thrown into the midst of a furnace of blazing fire!”'
EXEC add_BibleVerse @BibleId, 127003007, N'Therefore when they all heard the sound of the horn, flute, zither, trigon, harp, pipes, and all kinds of music, all the peoples, nations, and language groups began bowing down and paying homage to the golden statue that King Nebuchadnezzar had erected.'
EXEC add_BibleVerse @BibleId, 127003008, N'Now at that time certain Chaldeans came forward and brought malicious accusations against the Jews.'
EXEC add_BibleVerse @BibleId, 127003009, N'They said to King Nebuchadnezzar, “O king, live forever!'
EXEC add_BibleVerse @BibleId, 127003010, N'You have issued an edict, O king, that everyone must bow down and pay homage to the golden statue when they hear the sound of the horn, flute, zither, trigon, harp, pipes, and all kinds of music.'
EXEC add_BibleVerse @BibleId, 127003011, N'And whoever does not bow down and pay homage must be thrown into the midst of a furnace of blazing fire.'
EXEC add_BibleVerse @BibleId, 127003012, N'But there are Jewish men whom you appointed over the administration of the province of Babylon – Shadrach, Meshach, and Abednego – and these men have not shown proper respect to you, O king. They don’t serve your gods and they don’t pay homage to the golden statue that you have erected.”'
EXEC add_BibleVerse @BibleId, 127003013, N'Then Nebuchadnezzar in a fit of rage demanded that they bring Shadrach, Meshach, and Abednego before him. So they brought them before the king.'
EXEC add_BibleVerse @BibleId, 127003014, N'Nebuchadnezzar said to them, “Is it true, Shadrach, Meshach, and Abednego, that you don’t serve my gods and that you don’t pay homage to the golden statue that I erected?'
EXEC add_BibleVerse @BibleId, 127003015, N'Now if you are ready, when you hear the sound of the horn, flute, zither, trigon, harp, pipes, and all kinds of music, you must bow down and pay homage to the statue that I had made. If you don’t pay homage to it, you will immediately be thrown into the midst of the furnace of blazing fire. Now, who is that god who can rescue you from my power?”'
EXEC add_BibleVerse @BibleId, 127003016, N'Shadrach, Meshach, and Abednego replied to King Nebuchadnezzar, “We do not need to give you a reply concerning this.'
EXEC add_BibleVerse @BibleId, 127003017, N'If our God whom we are serving exists, he is able to rescue us from the furnace of blazing fire, and he will rescue us, O king, from your power as well.'
EXEC add_BibleVerse @BibleId, 127003018, N'But if not, let it be known to you, O king, that we don’t serve your gods, and we will not pay homage to the golden statue that you have erected.”'
EXEC add_BibleVerse @BibleId, 127003019, N'Then Nebuchadnezzar was filled with rage, and his disposition changed toward Shadrach, Meshach, and Abednego. He gave orders to heat the furnace seven times hotter than it was normally heated.'
EXEC add_BibleVerse @BibleId, 127003020, N'He ordered strong soldiers in his army to tie up Shadrach, Meshach, and Abednego and to throw them into the furnace of blazing fire.'
EXEC add_BibleVerse @BibleId, 127003021, N'So those men were tied up while still wearing their cloaks, trousers, turbans, and other clothes, and were thrown into the furnace of blazing fire.'
EXEC add_BibleVerse @BibleId, 127003022, N'But since the king’s command was so urgent, and the furnace was so excessively hot, the men who escorted Shadrach, Meshach, and Abednego were killed by the leaping flames.'
EXEC add_BibleVerse @BibleId, 127003023, N'But those three men, Shadrach, Meshach, and Abednego, fell into the furnace of blazing fire while still securely bound.'
EXEC add_BibleVerse @BibleId, 127003024, N'Then King Nebuchadnezzar was startled and quickly got up. He said to his ministers, “Wasn’t it three men that we tied up and threw into the fire?” They replied to the king, “For sure, O king.”'
EXEC add_BibleVerse @BibleId, 127003025, N'He answered, “But I see four men, untied and walking around in the midst of the fire! No harm has come to them! And the appearance of the fourth is like that of a god!”'
EXEC add_BibleVerse @BibleId, 127003026, N'Then Nebuchadnezzar approached the door of the furnace of blazing fire. He called out, “Shadrach, Meshach, and Abednego, servants of the most high God, come out! Come here!” Then Shadrach, Meshach, and Abednego emerged from the fire.'
EXEC add_BibleVerse @BibleId, 127003027, N'Once the satraps, prefects, governors, and ministers of the king had gathered around, they saw that those men were physically unharmed by the fire. The hair of their heads was not singed, nor were their trousers damaged. Not even the smell of fire was to be found on them!'
EXEC add_BibleVerse @BibleId, 127003028, N'Nebuchadnezzar exclaimed, “Praised be the God of Shadrach, Meshach, and Abednego, who has sent forth his angel and has rescued his servants who trusted in him, ignoring the edict of the king and giving up their bodies rather than serve or pay homage to any god other than their God!'
EXEC add_BibleVerse @BibleId, 127003029, N'I hereby decree that any people, nation, or language group that blasphemes the god of Shadrach, Meshach, or Abednego will be dismembered and his home reduced to rubble! For there exists no other god who can deliver in this way.”'
EXEC add_BibleVerse @BibleId, 127003030, N'Then Nebuchadnezzar promoted Shadrach, Meshach, and Abednego in the province of Babylon.'
EXEC add_BibleVerse @BibleId, 127004001, N'“King Nebuchadnezzar, to all peoples, nations, and language groups that live in all the land: Peace and prosperity!'
EXEC add_BibleVerse @BibleId, 127004002, N'I am delighted to tell you about the signs and wonders that the most high God has done for me.'
EXEC add_BibleVerse @BibleId, 127004003, N'“How great are his signs! How mighty are his wonders! His kingdom will last forever, and his authority continues from one generation to the next.”'
EXEC add_BibleVerse @BibleId, 127004004, N'I, Nebuchadnezzar, was relaxing in my home, living luxuriously in my palace.'
EXEC add_BibleVerse @BibleId, 127004005, N'I saw a dream that frightened me badly. The things I imagined while lying on my bed – these visions of my mind – were terrifying me.'
EXEC add_BibleVerse @BibleId, 127004006, N'So I issued an order for all the wise men of Babylon to be brought before me so that they could make known to me the interpretation of the dream.'
EXEC add_BibleVerse @BibleId, 127004007, N'When the magicians, astrologers, wise men, and diviners entered, I recounted the dream for them. But they were unable to make known its interpretation to me.'
EXEC add_BibleVerse @BibleId, 127004008, N'Later Daniel entered (whose name is Belteshazzar after the name of my god, and in whom there is a spirit of the holy gods). I recounted the dream for him as well,'
EXEC add_BibleVerse @BibleId, 127004009, N'saying, “Belteshazzar, chief of the magicians, in whom I know there to be a spirit of the holy gods and whom no mystery baffles, consider my dream that I saw and set forth its interpretation!'
EXEC add_BibleVerse @BibleId, 127004010, N'Here are the visions of my mind while I was on my bed. While I was watching, there was a tree in the middle of the land. It was enormously tall.'
EXEC add_BibleVerse @BibleId, 127004011, N'The tree grew large and strong. Its top reached far into the sky; it could be seen from the borders of all the land.'
EXEC add_BibleVerse @BibleId, 127004012, N'Its foliage was attractive and its fruit plentiful; on it there was food enough for all. Under it the wild animals used to seek shade, and in its branches the birds of the sky used to nest. All creatures used to feed themselves from it.'
EXEC add_BibleVerse @BibleId, 127004013, N'While I was watching in my mind’s visions on my bed, a holy sentinel came down from heaven.'
EXEC add_BibleVerse @BibleId, 127004014, N'He called out loudly as follows: ‘Chop down the tree and lop off its branches! Strip off its foliage and scatter its fruit! Let the animals flee from under it and the birds from its branches!'
EXEC add_BibleVerse @BibleId, 127004015, N'But leave its taproot in the ground, with a band of iron and bronze around it surrounded by the grass of the field. Let it become damp with the dew of the sky, and let it live with the animals in the grass of the land.'
EXEC add_BibleVerse @BibleId, 127004016, N'Let his mind be altered from that of a human being, and let an animal’s mind be given to him, and let seven periods of time go by for him.'
EXEC add_BibleVerse @BibleId, 127004017, N'This announcement is by the decree of the sentinels; this decision is by the pronouncement of the holy ones, so that those who are alive may understand that the Most High has authority over human kingdoms, and he bestows them on whomever he wishes. He establishes over them even the lowliest of human beings.’'
EXEC add_BibleVerse @BibleId, 127004018, N'“This is the dream that I, King Nebuchadnezzar, saw. Now you, Belteshazzar, declare its interpretation, for none of the wise men in my kingdom are able to make known to me the interpretation. But you can do so, for a spirit of the holy gods is in you.”'
EXEC add_BibleVerse @BibleId, 127004019, N'Then Daniel (whose name is also Belteshazzar) was upset for a brief time; his thoughts were alarming him. The king said, “Belteshazzar, don’t let the dream and its interpretation alarm you.” But Belteshazzar replied, “Sir, if only the dream were for your enemies and its interpretation applied to your adversaries!'
EXEC add_BibleVerse @BibleId, 127004020, N'The tree that you saw that grew large and strong, whose top reached to the sky, and which could be seen in all the land,'
EXEC add_BibleVerse @BibleId, 127004021, N'whose foliage was attractive and its fruit plentiful, and from which there was food available for all, under whose branches wild animals used to live, and in whose branches birds of the sky used to nest –'
EXEC add_BibleVerse @BibleId, 127004022, N'it is you, O king! For you have become great and strong. Your greatness is such that it reaches to heaven, and your authority to the ends of the earth.'
EXEC add_BibleVerse @BibleId, 127004023, N'As for the king seeing a holy sentinel coming down from heaven and saying, ‘Chop down the tree and destroy it, but leave its taproot in the ground, with a band of iron and bronze around it, surrounded by the grass of the field. Let it become damp with the dew of the sky, and let it live with the wild animals, until seven periods of time go by for him’ –'
EXEC add_BibleVerse @BibleId, 127004024, N'this is the interpretation, O king! It is the decision of the Most High that this has happened to my lord the king.'
EXEC add_BibleVerse @BibleId, 127004025, N'You will be driven from human society, and you will live with the wild animals. You will be fed grass like oxen, and you will become damp with the dew of the sky. Seven periods of time will pass by for you, before you understand that the Most High is ruler over human kingdoms and gives them to whomever he wishes.'
EXEC add_BibleVerse @BibleId, 127004026, N'They said to leave the taproot of the tree, for your kingdom will be restored to you when you come to understand that heaven rules.'
EXEC add_BibleVerse @BibleId, 127004027, N'Therefore, O king, may my advice be pleasing to you. Break away from your sins by doing what is right, and from your iniquities by showing mercy to the poor. Perhaps your prosperity will be prolonged.”'
EXEC add_BibleVerse @BibleId, 127004028, N'Now all of this happened to King Nebuchadnezzar.'
EXEC add_BibleVerse @BibleId, 127004029, N'After twelve months, he happened to be walking around on the battlements of the royal palace of Babylon.'
EXEC add_BibleVerse @BibleId, 127004030, N'The king uttered these words: “Is this not the great Babylon that I have built for a royal residence by my own mighty strength and for my majestic honor?”'
EXEC add_BibleVerse @BibleId, 127004031, N'While these words were still on the king’s lips, a voice came down from heaven: “It is hereby announced to you, King Nebuchadnezzar, that your kingdom has been removed from you!'
EXEC add_BibleVerse @BibleId, 127004032, N'You will be driven from human society, and you will live with the wild animals. You will be fed grass like oxen, and seven periods of time will pass by for you before you understand that the Most High is ruler over human kingdoms and gives them to whomever he wishes.”'
EXEC add_BibleVerse @BibleId, 127004033, N'Now in that very moment this pronouncement about Nebuchadnezzar came true. He was driven from human society, he ate grass like oxen, and his body became damp with the dew of the sky, until his hair became long like an eagle’s feathers, and his nails like a bird’s claws.'
EXEC add_BibleVerse @BibleId, 127004034, N'But at the end of the appointed time I, Nebuchadnezzar, looked up toward heaven, and my sanity returned to me. I extolled the Most High, and I praised and glorified the one who lives forever. For his authority is an everlasting authority, and his kingdom extends from one generation to the next.'
EXEC add_BibleVerse @BibleId, 127004035, N'All the inhabitants of the earth are regarded as nothing. He does as he wishes with the army of heaven and with those who inhabit the earth. No one slaps his hand and says to him, ‘What have you done?’'
EXEC add_BibleVerse @BibleId, 127004036, N'At that time my sanity returned to me. I was restored to the honor of my kingdom, and my splendor returned to me. My ministers and my nobles were seeking me out, and I was reinstated over my kingdom. I became even greater than before.'
EXEC add_BibleVerse @BibleId, 127004037, N'Now I, Nebuchadnezzar, praise and exalt and glorify the King of heaven, for all his deeds are right and his ways are just. He is able to bring down those who live in pride.'
EXEC add_BibleVerse @BibleId, 127005001, N'King Belshazzar prepared a great banquet for a thousand of his nobles, and he was drinking wine in front of them all.'
EXEC add_BibleVerse @BibleId, 127005002, N'While under the influence of the wine, Belshazzar issued an order to bring in the gold and silver vessels – the ones that Nebuchadnezzar his father had confiscated from the temple in Jerusalem – so that the king and his nobles, together with his wives and his concubines, could drink from them.'
EXEC add_BibleVerse @BibleId, 127005003, N'So they brought the gold and silver vessels that had been confiscated from the temple, the house of God in Jerusalem, and the king and his nobles, together with his wives and concubines, drank from them.'
EXEC add_BibleVerse @BibleId, 127005004, N'As they drank wine, they praised the gods of gold and silver, bronze, iron, wood, and stone.'
EXEC add_BibleVerse @BibleId, 127005005, N'At that very moment the fingers of a human hand appeared and wrote on the plaster of the royal palace wall, opposite the lampstand. The king was watching the back of the hand that was writing.'
EXEC add_BibleVerse @BibleId, 127005006, N'Then all the color drained from the king’s face and he became alarmed. The joints of his hips gave way, and his knees began knocking together.'
EXEC add_BibleVerse @BibleId, 127005007, N'The king called out loudly to summon the astrologers, wise men, and diviners. The king proclaimed to the wise men of Babylon that anyone who could read this inscription and disclose its interpretation would be clothed in purple and have a golden collar placed on his neck and be third ruler in the kingdom.'
EXEC add_BibleVerse @BibleId, 127005008, N'So all the king’s wise men came in, but they were unable to read the writing or to make known its interpretation to the king.'
EXEC add_BibleVerse @BibleId, 127005009, N'Then King Belshazzar was very terrified, and he was visibly shaken. His nobles were completely dumbfounded.'
EXEC add_BibleVerse @BibleId, 127005010, N'Due to the noise caused by the king and his nobles, the queen mother then entered the banquet room. She said, “O king, live forever! Don’t be alarmed! Don’t be shaken!'
EXEC add_BibleVerse @BibleId, 127005011, N'There is a man in your kingdom who has within him a spirit of the holy gods. In the days of your father, he proved to have insight, discernment, and wisdom like that of the gods. King Nebuchadnezzar your father appointed him chief of the magicians, astrologers, wise men, and diviners.'
EXEC add_BibleVerse @BibleId, 127005012, N'Thus there was found in this man Daniel, whom the king renamed Belteshazzar, an extraordinary spirit, knowledge, and skill to interpret dreams, solve riddles, and decipher knotty problems. Now summon Daniel, and he will disclose the interpretation.”'
EXEC add_BibleVerse @BibleId, 127005013, N'So Daniel was brought in before the king. The king said to Daniel, “Are you that Daniel who is one of the captives of Judah, whom my father the king brought from Judah?'
EXEC add_BibleVerse @BibleId, 127005014, N'I have heard about you, how there is a spirit of the gods in you, and how you have insight, discernment, and extraordinary wisdom.'
EXEC add_BibleVerse @BibleId, 127005015, N'Now the wise men and astrologers were brought before me to read this writing and make known to me its interpretation. But they were unable to disclose the interpretation of the message.'
EXEC add_BibleVerse @BibleId, 127005016, N'However, I have heard that you are able to provide interpretations and to decipher knotty problems. Now if you are able to read this writing and make known to me its interpretation, you will wear purple and have a golden collar around your neck and be third ruler in the kingdom.”'
EXEC add_BibleVerse @BibleId, 127005017, N'But Daniel replied to the king, “Keep your gifts, and give your rewards to someone else! However, I will read the writing for the king and make known its interpretation.'
EXEC add_BibleVerse @BibleId, 127005018, N'As for you, O king, the most high God bestowed on your father Nebuchadnezzar a kingdom, greatness, honor, and majesty.'
EXEC add_BibleVerse @BibleId, 127005019, N'Due to the greatness that he bestowed on him, all peoples, nations, and language groups were trembling with fear before him. He killed whom he wished, he spared whom he wished, he exalted whom he wished, and he brought low whom he wished.'
EXEC add_BibleVerse @BibleId, 127005020, N'And when his mind became arrogant and his spirit filled with pride, he was deposed from his royal throne and his honor was removed from him.'
EXEC add_BibleVerse @BibleId, 127005021, N'He was driven from human society, his mind was changed to that of an animal, he lived with the wild donkeys, he was fed grass like oxen, and his body became damp with the dew of the sky, until he came to understand that the most high God rules over human kingdoms, and he appoints over them whomever he wishes.'
EXEC add_BibleVerse @BibleId, 127005022, N'“But you, his son Belshazzar, have not humbled yourself, although you knew all this.'
EXEC add_BibleVerse @BibleId, 127005023, N'Instead, you have exalted yourself against the Lord of heaven. You brought before you the vessels from his temple, and you and your nobles, together with your wives and concubines, drank wine from them. You praised the gods of silver, gold, bronze, iron, wood, and stone – gods that cannot see or hear or comprehend! But you have not glorified the God who has in his control your very breath and all your ways!'
EXEC add_BibleVerse @BibleId, 127005024, N'Therefore the palm of a hand was sent from him, and this writing was inscribed.'
EXEC add_BibleVerse @BibleId, 127005025, N'“This is the writing that was inscribed: MENE, MENE, TEQEL, and PHARSIN.'
EXEC add_BibleVerse @BibleId, 127005026, N'This is the interpretation of the words: As for mene – God has numbered your kingdom’s days and brought it to an end.'
EXEC add_BibleVerse @BibleId, 127005027, N'As for teqel – you are weighed on the balances and found to be lacking.'
EXEC add_BibleVerse @BibleId, 127005028, N'As for peres – your kingdom is divided and given over to the Medes and Persians.”'
EXEC add_BibleVerse @BibleId, 127005029, N'Then, on Belshazzar’s orders, Daniel was clothed in purple, a golden collar was placed around his neck, and he was proclaimed third ruler in the kingdom.'
EXEC add_BibleVerse @BibleId, 127005030, N'And in that very night Belshazzar, the Babylonian king, was killed.'
EXEC add_BibleVerse @BibleId, 127005031, N'So Darius the Mede took control of the kingdom when he was about sixty-two years old.'
EXEC add_BibleVerse @BibleId, 127006001, N'It seemed like a good idea to Darius to appoint over the kingdom 120 satraps who would be in charge of the entire kingdom.'
EXEC add_BibleVerse @BibleId, 127006002, N'Over them would be three supervisors, one of whom was Daniel. These satraps were accountable to them, so that the king’s interests might not incur damage.'
EXEC add_BibleVerse @BibleId, 127006003, N'Now this Daniel was distinguishing himself above the other supervisors and the satraps, for he had an extraordinary spirit. In fact, the king intended to appoint him over the entire kingdom.'
EXEC add_BibleVerse @BibleId, 127006004, N'Consequently the supervisors and satraps were trying to find some pretext against Daniel in connection with administrative matters. But they were unable to find any such damaging evidence, because he was trustworthy and guilty of no negligence or corruption.'
EXEC add_BibleVerse @BibleId, 127006005, N'So these men concluded, “We won’t find any pretext against this man Daniel unless it is in connection with the law of his God.”'
EXEC add_BibleVerse @BibleId, 127006006, N'So these supervisors and satraps came by collusion to the king and said to him, “O King Darius, live forever!'
EXEC add_BibleVerse @BibleId, 127006007, N'To all the supervisors of the kingdom, the prefects, satraps, counselors, and governors it seemed like a good idea for a royal edict to be issued and an interdict to be enforced. For the next thirty days anyone who prays to any god or human other than you, O king, should be thrown into a den of lions.'
EXEC add_BibleVerse @BibleId, 127006008, N'Now let the king issue a written interdict so that it cannot be altered, according to the law of the Medes and Persians, which cannot be changed.'
EXEC add_BibleVerse @BibleId, 127006009, N'So King Darius issued the written interdict.'
EXEC add_BibleVerse @BibleId, 127006010, N'When Daniel realized that a written decree had been issued, he entered his home, where the windows in his upper room opened toward Jerusalem. Three times daily he was kneeling and offering prayers and thanks to his God just as he had been accustomed to do previously.'
EXEC add_BibleVerse @BibleId, 127006011, N'Then those officials who had gone to the king came by collusion and found Daniel praying and asking for help before his God.'
EXEC add_BibleVerse @BibleId, 127006012, N'So they approached the king and said to him, “Did you not issue an edict to the effect that for the next thirty days anyone who prays to any god or human other than to you, O king, would be thrown into a den of lions?” The king replied, “That is correct, according to the law of the Medes and Persians, which cannot be changed.”'
EXEC add_BibleVerse @BibleId, 127006013, N'Then they said to the king, “Daniel, who is one of the captives from Judah, pays no attention to you, O king, or to the edict that you issued. Three times daily he offers his prayer.”'
EXEC add_BibleVerse @BibleId, 127006014, N'When the king heard this, he was very upset and began thinking about how he might rescue Daniel. Until late afternoon he was struggling to find a way to rescue him.'
EXEC add_BibleVerse @BibleId, 127006015, N'Then those men came by collusion to the king and said to him, “Recall, O king, that it is a law of the Medes and Persians that no edict or decree that the king issues can be changed.”'
EXEC add_BibleVerse @BibleId, 127006016, N'So the king gave the order, and Daniel was brought and thrown into a den of lions. The king consoled Daniel by saying, “Your God whom you continually serve will rescue you!”'
EXEC add_BibleVerse @BibleId, 127006017, N'Then a stone was brought and placed over the opening to the den. The king sealed it with his signet ring and with those of his nobles so that nothing could be changed with regard to Daniel.'
EXEC add_BibleVerse @BibleId, 127006018, N'Then the king departed to his palace. But he spent the night without eating, and no diversions were brought to him. He was unable to sleep.'
EXEC add_BibleVerse @BibleId, 127006019, N'In the morning, at the earliest sign of daylight, the king got up and rushed to the lions’ den.'
EXEC add_BibleVerse @BibleId, 127006020, N'As he approached the den, he called out to Daniel in a worried voice, “Daniel, servant of the living God, was your God whom you continually serve able to rescue you from the lions?”'
EXEC add_BibleVerse @BibleId, 127006021, N'Then Daniel spoke to the king, “O king, live forever!'
EXEC add_BibleVerse @BibleId, 127006022, N'My God sent his angel and closed the lions’ mouths so that they have not harmed me, because I was found to be innocent before him. Nor have I done any harm to you, O king.”'
EXEC add_BibleVerse @BibleId, 127006023, N'Then the king was delighted and gave an order to haul Daniel up from the den. So Daniel was hauled up out of the den. He had no injury of any kind, because he had trusted in his God.'
EXEC add_BibleVerse @BibleId, 127006024, N'The king gave another order, and those men who had maliciously accused Daniel were brought and thrown into the lions’ den – they, their children, and their wives. They did not even reach the bottom of the den before the lions overpowered them and crushed all their bones.'
EXEC add_BibleVerse @BibleId, 127006025, N'Then King Darius wrote to all the peoples, nations, and language groups who were living in all the land: “Peace and prosperity!'
EXEC add_BibleVerse @BibleId, 127006026, N'I have issued an edict that throughout all the dominion of my kingdom people are to revere and fear the God of Daniel. “For he is the living God; he endures forever. His kingdom will not be destroyed; his authority is forever.'
EXEC add_BibleVerse @BibleId, 127006027, N'He rescues and delivers and performs signs and wonders in the heavens and on the earth. He has rescued Daniel from the power of the lions!”'
EXEC add_BibleVerse @BibleId, 127006028, N'So this Daniel prospered during the reign of Darius and the reign of Cyrus the Persian.'
EXEC add_BibleVerse @BibleId, 127007001, N'In the first year of King Belshazzar of Babylon, Daniel had a dream filled with visions while he was lying on his bed. Then he wrote down the dream in summary fashion.'
EXEC add_BibleVerse @BibleId, 127007002, N'Daniel explained: “I was watching in my vision during the night as the four winds of the sky were stirring up the great sea.'
EXEC add_BibleVerse @BibleId, 127007003, N'Then four large beasts came up from the sea; they were different from one another.'
EXEC add_BibleVerse @BibleId, 127007004, N'“The first one was like a lion with eagles’ wings. As I watched, its wings were pulled off and it was lifted up from the ground. It was made to stand on two feet like a human being, and a human mind was given to it.'
EXEC add_BibleVerse @BibleId, 127007005, N'“Then a second beast appeared, like a bear. It was raised up on one side, and there were three ribs in its mouth between its teeth. It was told, ‘Get up and devour much flesh!’'
EXEC add_BibleVerse @BibleId, 127007006, N'“After these things, as I was watching, another beast like a leopard appeared, with four bird-like wings on its back. This beast had four heads, and ruling authority was given to it.'
EXEC add_BibleVerse @BibleId, 127007007, N'“After these things, as I was watching in the night visions a fourth beast appeared – one dreadful, terrible, and very strong. It had two large rows of iron teeth. It devoured and crushed, and anything that was left it trampled with its feet. It was different from all the beasts that came before it, and it had ten horns.'
EXEC add_BibleVerse @BibleId, 127007008, N'“As I was contemplating the horns, another horn – a small one – came up between them, and three of the former horns were torn out by the roots to make room for it. This horn had eyes resembling human eyes and a mouth speaking arrogant things.'
EXEC add_BibleVerse @BibleId, 127007009, N'“While I was watching, thrones were set up, and the Ancient of Days took his seat. His attire was white like snow; the hair of his head was like lamb’s wool. His throne was ablaze with fire and its wheels were all aflame.'
EXEC add_BibleVerse @BibleId, 127007010, N'A river of fire was streaming forth and proceeding from his presence. Many thousands were ministering to him; Many tens of thousands stood ready to serve him. The court convened and the books were opened.'
EXEC add_BibleVerse @BibleId, 127007011, N'“Then I kept on watching because of the arrogant words of the horn that was speaking. I was watching until the beast was killed and its body destroyed and thrown into the flaming fire.'
EXEC add_BibleVerse @BibleId, 127007012, N'As for the rest of the beasts, their ruling authority had already been removed, though they were permitted to go on living for a time and a season.'
EXEC add_BibleVerse @BibleId, 127007013, N'I was watching in the night visions, “And with the clouds of the sky one like a son of man was approaching. He went up to the Ancient of Days and was escorted before him.'
EXEC add_BibleVerse @BibleId, 127007014, N'To him was given ruling authority, honor, and sovereignty. All peoples, nations, and language groups were serving him. His authority is eternal and will not pass away. His kingdom will not be destroyed.'
EXEC add_BibleVerse @BibleId, 127007015, N'“As for me, Daniel, my spirit was distressed, and the visions of my mind were alarming me.'
EXEC add_BibleVerse @BibleId, 127007016, N'I approached one of those standing nearby and asked him about the meaning of all this. So he spoke with me and revealed to me the interpretation of the vision:'
EXEC add_BibleVerse @BibleId, 127007017, N'‘These large beasts, which are four in number, represent four kings who will arise from the earth.'
EXEC add_BibleVerse @BibleId, 127007018, N'The holy ones of the Most High will receive the kingdom and will take possession of the kingdom forever and ever.’'
EXEC add_BibleVerse @BibleId, 127007019, N'“Then I wanted to know the meaning of the fourth beast, which was different from all the others. It was very dreadful, with two rows of iron teeth and bronze claws, and it devoured, crushed, and trampled anything that was left with its feet.'
EXEC add_BibleVerse @BibleId, 127007020, N'I also wanted to know the meaning of the ten horns on its head, and of that other horn which came up and before which three others fell. This was the horn that had eyes and a mouth speaking arrogant things, whose appearance was more formidable than the others.'
EXEC add_BibleVerse @BibleId, 127007021, N'While I was watching, that horn began to wage war against the holy ones and was defeating them,'
EXEC add_BibleVerse @BibleId, 127007022, N'until the Ancient of Days arrived and judgment was rendered in favor of the holy ones of the Most High. Then the time came for the holy ones to take possession of the kingdom.'
EXEC add_BibleVerse @BibleId, 127007023, N'“This is what he told me: ‘The fourth beast means that there will be a fourth kingdom on earth that will differ from all the other kingdoms. It will devour all the earth and will trample and crush it.'
EXEC add_BibleVerse @BibleId, 127007024, N'The ten horns mean that ten kings will arise from that kingdom. Another king will arise after them, but he will be different from the earlier ones. He will humiliate three kings.'
EXEC add_BibleVerse @BibleId, 127007025, N'He will speak words against the Most High. He will harass the holy ones of the Most High continually. His intention will be to change times established by law. They will be delivered into his hand For a time, times, and half a time.'
EXEC add_BibleVerse @BibleId, 127007026, N'But the court will convene, and his ruling authority will be removed – destroyed and abolished forever!'
EXEC add_BibleVerse @BibleId, 127007027, N'Then the kingdom, authority, and greatness of the kingdoms under all of heaven will be delivered to the people of the holy ones of the Most High. His kingdom is an eternal kingdom; all authorities will serve him and obey him.’'
EXEC add_BibleVerse @BibleId, 127007028, N'“This is the conclusion of the matter. As for me, Daniel, my thoughts troubled me greatly, and the color drained from my face. But I kept the matter to myself.”'
EXEC add_BibleVerse @BibleId, 127008001, N'In the third year of King Belshazzar’s reign, a vision appeared to me, Daniel, after the one that had appeared to me previously.'
EXEC add_BibleVerse @BibleId, 127008002, N'In this vision I saw myself in Susa the citadel, which is located in the province of Elam. In the vision I saw myself at the Ulai Canal.'
EXEC add_BibleVerse @BibleId, 127008003, N'I looked up and saw a ram with two horns standing at the canal. Its two horns were both long, but one was longer than the other. The longer one was coming up after the shorter one.'
EXEC add_BibleVerse @BibleId, 127008004, N'I saw that the ram was butting westward, northward, and southward. No animal was able to stand before it, and there was none who could deliver from its power. It did as it pleased and acted arrogantly.'
EXEC add_BibleVerse @BibleId, 127008005, N'While I was contemplating all this, a male goat was coming from the west over the surface of all the land without touching the ground. This goat had a conspicuous horn between its eyes.'
EXEC add_BibleVerse @BibleId, 127008006, N'It came to the two-horned ram that I had seen standing beside the canal and rushed against it with raging strength.'
EXEC add_BibleVerse @BibleId, 127008007, N'I saw it approaching the ram. It went into a fit of rage against the ram and struck it and broke off its two horns. The ram had no ability to resist it. The goat hurled the ram to the ground and trampled it. No one could deliver the ram from its power.'
EXEC add_BibleVerse @BibleId, 127008008, N'The male goat acted even more arrogantly. But no sooner had the large horn become strong than it was broken, and there arose four conspicuous horns in its place, extending toward the four winds of the sky.'
EXEC add_BibleVerse @BibleId, 127008009, N'From one of them came a small horn. But it grew to be very big, toward the south and the east and toward the beautiful land.'
EXEC add_BibleVerse @BibleId, 127008010, N'It grew so big it reached the army of heaven, and it brought about the fall of some of the army and some of the stars to the ground, where it trampled them.'
EXEC add_BibleVerse @BibleId, 127008011, N'It also acted arrogantly against the Prince of the army, from whom the daily sacrifice was removed and whose sanctuary was thrown down.'
EXEC add_BibleVerse @BibleId, 127008012, N'The army was given over, along with the daily sacrifice, in the course of his sinful rebellion. It hurled truth to the ground and enjoyed success.'
EXEC add_BibleVerse @BibleId, 127008013, N'Then I heard a holy one speaking. Another holy one said to the one who was speaking, “To what period of time does the vision pertain – this vision concerning the daily sacrifice and the destructive act of rebellion and the giving over of both the sanctuary and army to be trampled?”'
EXEC add_BibleVerse @BibleId, 127008014, N'He said to me, “To 2,300 evenings and mornings; then the sanctuary will be put right again.”'
EXEC add_BibleVerse @BibleId, 127008015, N'While I, Daniel, was watching the vision, I sought to understand it. Now one who appeared to be a man was standing before me.'
EXEC add_BibleVerse @BibleId, 127008016, N'Then I heard a human voice coming from between the banks of the Ulai. It called out, “Gabriel, enable this person to understand the vision.”'
EXEC add_BibleVerse @BibleId, 127008017, N'So he approached the place where I was standing. As he came, I felt terrified and fell flat on the ground. Then he said to me, “Understand, son of man, that the vision pertains to the time of the end.”'
EXEC add_BibleVerse @BibleId, 127008018, N'As he spoke with me, I fell into a trance with my face to the ground. But he touched me and stood me upright.'
EXEC add_BibleVerse @BibleId, 127008019, N'Then he said, “I am going to inform you about what will happen in the latter time of wrath, for the vision pertains to the appointed time of the end.'
EXEC add_BibleVerse @BibleId, 127008020, N'The ram that you saw with the two horns stands for the kings of Media and Persia.'
EXEC add_BibleVerse @BibleId, 127008021, N'The male goat is the king of Greece, and the large horn between its eyes is the first king.'
EXEC add_BibleVerse @BibleId, 127008022, N'The horn that was broken and in whose place there arose four others stands for four kingdoms that will arise from his nation, though they will not have his strength.'
EXEC add_BibleVerse @BibleId, 127008023, N'Toward the end of their rule, when rebellious acts are complete, a rash and deceitful king will arise.'
EXEC add_BibleVerse @BibleId, 127008024, N'His power will be great, but it will not be by his strength alone. He will cause terrible destruction. He will be successful in what he undertakes. He will destroy powerful people and the people of the holy ones.'
EXEC add_BibleVerse @BibleId, 127008025, N'By his treachery he will succeed through deceit. He will have an arrogant attitude, and he will destroy many who are unaware of his schemes. He will rise up against the Prince of princes, yet he will be broken apart – but not by human agency.'
EXEC add_BibleVerse @BibleId, 127008026, N'The vision of the evenings and mornings that was told to you is correct. But you should seal up the vision, for it refers to a time many days from now.”'
EXEC add_BibleVerse @BibleId, 127008027, N'I, Daniel, was exhausted and sick for days. Then I got up and again carried out the king’s business. But I was astonished at the vision, and there was no one to explain it.'
EXEC add_BibleVerse @BibleId, 127009001, N'In the first year of Darius son of Ahasuerus, who was of Median descent and who had been appointed king over the Babylonian empire –'
EXEC add_BibleVerse @BibleId, 127009002, N'in the first year of his reign I, Daniel, came to understand from the sacred books that, according to the word of the LORD disclosed to the prophet Jeremiah, the years for the fulfilling of the desolation of Jerusalem were seventy in number.'
EXEC add_BibleVerse @BibleId, 127009003, N'So I turned my attention to the Lord God to implore him by prayer and requests, with fasting, sackcloth, and ashes.'
EXEC add_BibleVerse @BibleId, 127009004, N'I prayed to the LORD my God, confessing in this way: “O Lord, great and awesome God who is faithful to his covenant with those who love him and keep his commandments,'
EXEC add_BibleVerse @BibleId, 127009005, N'we have sinned! We have done what is wrong and wicked; we have rebelled by turning away from your commandments and standards.'
EXEC add_BibleVerse @BibleId, 127009006, N'We have not paid attention to your servants the prophets, who spoke by your authority to our kings, our leaders, and our ancestors, and to all the inhabitants of the land as well.'
EXEC add_BibleVerse @BibleId, 127009007, N'“You are righteous, O Lord, but we are humiliated this day – the people of Judah and the inhabitants of Jerusalem and all Israel, both near and far away in all the countries in which you have scattered them, because they have behaved unfaithfully toward you.'
EXEC add_BibleVerse @BibleId, 127009008, N'O LORD, we have been humiliated – our kings, our leaders, and our ancestors – because we have sinned against you.'
EXEC add_BibleVerse @BibleId, 127009009, N'Yet the Lord our God is compassionate and forgiving, even though we have rebelled against him.'
EXEC add_BibleVerse @BibleId, 127009010, N'We have not obeyed the LORD our God by living according to his laws that he set before us through his servants the prophets.'
EXEC add_BibleVerse @BibleId, 127009011, N'“All Israel has broken your law and turned away by not obeying you. Therefore you have poured out on us the judgment solemnly threatened in the law of Moses the servant of God, for we have sinned against you.'
EXEC add_BibleVerse @BibleId, 127009012, N'He has carried out his threats against us and our rulers who were over us by bringing great calamity on us – what has happened to Jerusalem has never been equaled under all heaven!'
EXEC add_BibleVerse @BibleId, 127009013, N'Just as it is written in the law of Moses, so all this calamity has come on us. Still we have not tried to pacify the LORD our God by turning back from our sin and by seeking wisdom from your reliable moral standards.'
EXEC add_BibleVerse @BibleId, 127009014, N'The LORD was mindful of the calamity, and he brought it on us. For the LORD our God is just in all he has done, and we have not obeyed him.'
EXEC add_BibleVerse @BibleId, 127009015, N'“Now, O Lord our God, who brought your people out of the land of Egypt with great power and made a name for yourself that is remembered to this day – we have sinned and behaved wickedly.'
EXEC add_BibleVerse @BibleId, 127009016, N'O Lord, according to all your justice, please turn your raging anger away from your city Jerusalem, your holy mountain. For due to our sins and the iniquities of our ancestors, Jerusalem and your people are mocked by all our neighbors.'
EXEC add_BibleVerse @BibleId, 127009017, N'“So now, our God, accept the prayer and requests of your servant, and show favor to your devastated sanctuary for your own sake.'
EXEC add_BibleVerse @BibleId, 127009018, N'Listen attentively, my God, and hear! Open your eyes and look on our desolated ruins and the city called by your name. For it is not because of our own righteous deeds that we are praying to you, but because your compassion is abundant.'
EXEC add_BibleVerse @BibleId, 127009019, N'O Lord, hear! O Lord, forgive! O Lord, pay attention, and act! Don’t delay, for your own sake, O my God! For your city and your people are called by your name.”'
EXEC add_BibleVerse @BibleId, 127009020, N'While I was still speaking and praying, confessing my sin and the sin of my people Israel and presenting my request before the LORD my God concerning his holy mountain –'
EXEC add_BibleVerse @BibleId, 127009021, N'yes, while I was still praying, the man Gabriel, whom I had seen previously in a vision, was approaching me in my state of extreme weariness, around the time of the evening offering.'
EXEC add_BibleVerse @BibleId, 127009022, N'He spoke with me, instructing me as follows: “Daniel, I have now come to impart understanding to you.'
EXEC add_BibleVerse @BibleId, 127009023, N'At the beginning of your requests a message went out, and I have come to convey it to you, for you are of great value in God’s sight. Therefore consider the message and understand the vision:'
EXEC add_BibleVerse @BibleId, 127009024, N'“Seventy weeks have been determined concerning your people and your holy city to put an end to rebellion, to bring sin to completion, to atone for iniquity, to bring in perpetual righteousness, to seal up the prophetic vision, and to anoint a most holy place.'
EXEC add_BibleVerse @BibleId, 127009025, N'So know and understand: From the issuing of the command to restore and rebuild Jerusalem until an anointed one, a prince arrives, there will be a period of seven weeks and sixty-two weeks. It will again be built, with plaza and moat, but in distressful times.'
EXEC add_BibleVerse @BibleId, 127009026, N'Now after the sixty-two weeks, an anointed one will be cut off and have nothing. As for the city and the sanctuary, the people of the coming prince will destroy them. But his end will come speedily like a flood. Until the end of the war that has been decreed there will be destruction.'
EXEC add_BibleVerse @BibleId, 127009027, N'He will confirm a covenant with many for one week. But in the middle of that week he will bring sacrifices and offerings to a halt. On the wing of abominations will come one who destroys, until the decreed end is poured out on the one who destroys.”'
EXEC add_BibleVerse @BibleId, 127010001, N'In the third year of King Cyrus of Persia a message was revealed to Daniel (who was also called Belteshazzar). This message was true and concerned a great war. He understood the message and gained insight by the vision.'
EXEC add_BibleVerse @BibleId, 127010002, N'In those days I, Daniel, was mourning for three whole weeks.'
EXEC add_BibleVerse @BibleId, 127010003, N'I ate no choice food; no meat or wine came to my lips, nor did I anoint myself with oil until the end of those three weeks.'
EXEC add_BibleVerse @BibleId, 127010004, N'On the twenty-fourth day of the first month I was beside the great river, the Tigris.'
EXEC add_BibleVerse @BibleId, 127010005, N'I looked up and saw a man clothed in linen; around his waist was a belt made of gold from Upaz.'
EXEC add_BibleVerse @BibleId, 127010006, N'His body resembled yellow jasper, and his face had an appearance like lightning. His eyes were like blazing torches; his arms and feet had the gleam of polished bronze. His voice thundered forth like the sound of a large crowd.'
EXEC add_BibleVerse @BibleId, 127010007, N'Only I, Daniel, saw the vision; the men who were with me did not see it. On the contrary, they were overcome with fright and ran away to hide.'
EXEC add_BibleVerse @BibleId, 127010008, N'I alone was left to see this great vision. My strength drained from me, and my vigor disappeared; I was without energy.'
EXEC add_BibleVerse @BibleId, 127010009, N'I listened to his voice, and as I did so I fell into a trance-like sleep with my face to the ground.'
EXEC add_BibleVerse @BibleId, 127010010, N'Then a hand touched me and set me on my hands and knees.'
EXEC add_BibleVerse @BibleId, 127010011, N'He said to me, “Daniel, you are of great value. Understand the words that I am about to speak to you. So stand up, for I have now been sent to you.” When he said this to me, I stood up shaking.'
EXEC add_BibleVerse @BibleId, 127010012, N'Then he said to me, “Don’t be afraid, Daniel, for from the very first day you applied your mind to understand and to humble yourself before your God, your words were heard. I have come in response to your words.'
EXEC add_BibleVerse @BibleId, 127010013, N'However, the prince of the kingdom of Persia was opposing me for twenty-one days. But Michael, one of the leading princes, came to help me, because I was left there with the kings of Persia.'
EXEC add_BibleVerse @BibleId, 127010014, N'Now I have come to help you understand what will happen to your people in the latter days, for the vision pertains to future days.”'
EXEC add_BibleVerse @BibleId, 127010015, N'While he was saying this to me, I was flat on the ground and unable to speak.'
EXEC add_BibleVerse @BibleId, 127010016, N'Then one who appeared to be a human being was touching my lips. I opened my mouth and started to speak, saying to the one who was standing before me, “Sir, due to the vision, anxiety has gripped me and I have no strength.'
EXEC add_BibleVerse @BibleId, 127010017, N'How, sir, am I able to speak with you? My strength is gone, and I am breathless.”'
EXEC add_BibleVerse @BibleId, 127010018, N'Then the one who appeared to be a human being touched me again and strengthened me.'
EXEC add_BibleVerse @BibleId, 127010019, N'He said to me, “Don’t be afraid, you who are valued. Peace be to you! Be strong! Be really strong!” When he spoke to me, I was strengthened. I said, “Sir, you may speak now, for you have given me strength.”'
EXEC add_BibleVerse @BibleId, 127010020, N'He said, “Do you know why I have come to you? Now I am about to return to engage in battle with the prince of Persia. When I go, the prince of Greece is coming.'
EXEC add_BibleVerse @BibleId, 127010021, N'However, I will first tell you what is written in a dependable book. (There is no one who strengthens me against these princes, except Michael your prince.'
EXEC add_BibleVerse @BibleId, 127011001, N'And in the first year of Darius the Mede, I stood to strengthen him and to provide protection for him.)'
EXEC add_BibleVerse @BibleId, 127011002, N'Now I will tell you the truth. “Three more kings will arise for Persia. Then a fourth king will be unusually rich, more so than all who preceded him. When he has amassed power through his riches, he will stir up everyone against the kingdom of Greece.'
EXEC add_BibleVerse @BibleId, 127011003, N'Then a powerful king will arise, exercising great authority and doing as he pleases.'
EXEC add_BibleVerse @BibleId, 127011004, N'Shortly after his rise to power, his kingdom will be broken up and distributed toward the four winds of the sky – but not to his posterity or with the authority he exercised, for his kingdom will be uprooted and distributed to others besides these.'
EXEC add_BibleVerse @BibleId, 127011005, N'“Then the king of the south and one of his subordinates will grow strong. His subordinate will resist him and will rule a kingdom greater than his.'
EXEC add_BibleVerse @BibleId, 127011006, N'After some years have passed, they will form an alliance. Then the daughter of the king of the south will come to the king of the north to make an agreement, but she will not retain her power, nor will he continue in his strength. She, together with the one who brought her, her child, and her benefactor will all be delivered over at that time.'
EXEC add_BibleVerse @BibleId, 127011007, N'“There will arise in his place one from her family line who will come against their army and will enter the stronghold of the king of the north and will move against them successfully.'
EXEC add_BibleVerse @BibleId, 127011008, N'He will also take their gods into captivity to Egypt, along with their cast images and prized utensils of silver and gold. Then he will withdraw for some years from the king of the north.'
EXEC add_BibleVerse @BibleId, 127011009, N'Then the king of the north will advance against the empire of the king of the south, but will withdraw to his own land.'
EXEC add_BibleVerse @BibleId, 127011010, N'His sons will wage war, mustering a large army which will advance like an overflowing river and carrying the battle all the way to the enemy’s fortress.'
EXEC add_BibleVerse @BibleId, 127011011, N'“Then the king of the south will be enraged and will march out to fight against the king of the north, who will also muster a large army, but that army will be delivered into his hand.'
EXEC add_BibleVerse @BibleId, 127011012, N'When the army is taken away, the king of the south will become arrogant. He will be responsible for the death of thousands and thousands of people, but he will not continue to prevail.'
EXEC add_BibleVerse @BibleId, 127011013, N'For the king of the north will again muster an army, one larger than before. At the end of some years he will advance with a huge army and enormous supplies.'
EXEC add_BibleVerse @BibleId, 127011014, N'“In those times many will oppose the king of the south. Those who are violent among your own people will rise up in confirmation of the vision, but they will falter.'
EXEC add_BibleVerse @BibleId, 127011015, N'Then the king of the north will advance and will build siege mounds and capture a well-fortified city. The forces of the south will not prevail, not even his finest contingents. They will have no strength to prevail.'
EXEC add_BibleVerse @BibleId, 127011016, N'The one advancing against him will do as he pleases, and no one will be able to stand before him. He will prevail in the beautiful land, and its annihilation will be within his power.'
EXEC add_BibleVerse @BibleId, 127011017, N'His intention will be to come with the strength of his entire kingdom, and he will form alliances. He will give the king of the south a daughter in marriage in order to destroy the kingdom, but it will not turn out to his advantage.'
EXEC add_BibleVerse @BibleId, 127011018, N'Then he will turn his attention to the coastal regions and will capture many of them. But a commander will bring his shameful conduct to a halt; in addition, he will make him pay for his shameful conduct.'
EXEC add_BibleVerse @BibleId, 127011019, N'He will then turn his attention to the fortresses of his own land, but he will stumble and fall, not to be found again.'
EXEC add_BibleVerse @BibleId, 127011020, N'There will arise after him one who will send out an exactor of tribute to enhance the splendor of the kingdom, but after a few days he will be destroyed, though not in anger or battle.'
EXEC add_BibleVerse @BibleId, 127011021, N'“Then there will arise in his place a despicable person to whom the royal honor has not been rightfully conferred. He will come on the scene in a time of prosperity and will seize the kingdom through deceit.'
EXEC add_BibleVerse @BibleId, 127011022, N'Armies will be suddenly swept away in defeat before him; both they and a covenant leader will be destroyed.'
EXEC add_BibleVerse @BibleId, 127011023, N'After entering into an alliance with him, he will behave treacherously; he will ascend to power with only a small force.'
EXEC add_BibleVerse @BibleId, 127011024, N'In a time of prosperity for the most productive areas of the province he will come and accomplish what neither his fathers nor their fathers accomplished. He will distribute loot, spoils, and property to his followers, and he will devise plans against fortified cities, but not for long.'
EXEC add_BibleVerse @BibleId, 127011025, N'He will rouse his strength and enthusiasm against the king of the south with a large army. The king of the south will wage war with a large and very powerful army, but he will not be able to prevail because of the plans devised against him.'
EXEC add_BibleVerse @BibleId, 127011026, N'Those who share the king’s fine food will attempt to destroy him, and his army will be swept away; many will be killed in battle.'
EXEC add_BibleVerse @BibleId, 127011027, N'These two kings, their minds filled with evil intentions, will trade lies with one another at the same table. But it will not succeed, for there is still an end at the appointed time.'
EXEC add_BibleVerse @BibleId, 127011028, N'Then the king of the north will return to his own land with much property. His mind will be set against the holy covenant. He will take action, and then return to his own land.'
EXEC add_BibleVerse @BibleId, 127011029, N'At an appointed time he will again invade the south, but this latter visit will not turn out the way the former one did.'
EXEC add_BibleVerse @BibleId, 127011030, N'The ships of Kittim will come against him, leaving him disheartened. He will turn back and direct his indignation against the holy covenant. He will return and honor those who forsake the holy covenant.'
EXEC add_BibleVerse @BibleId, 127011031, N'His forces will rise up and profane the fortified sanctuary, stopping the daily sacrifice. In its place they will set up the abomination that causes desolation.'
EXEC add_BibleVerse @BibleId, 127011032, N'Then with smooth words he will defile those who have rejected the covenant. But the people who are loyal to their God will act valiantly.'
EXEC add_BibleVerse @BibleId, 127011033, N'These who are wise among the people will teach the masses. However, they will fall by the sword and by the flame, and they will be imprisoned and plundered for some time.'
EXEC add_BibleVerse @BibleId, 127011034, N'When they stumble, they will be granted some help. But many will unite with them deceitfully.'
EXEC add_BibleVerse @BibleId, 127011035, N'Even some of the wise will stumble, resulting in their refinement, purification, and cleansing until the time of the end, for it is still for the appointed time.'
EXEC add_BibleVerse @BibleId, 127011036, N'“Then the king will do as he pleases. He will exalt and magnify himself above every deity and he will utter presumptuous things against the God of gods. He will succeed until the time of wrath is completed, for what has been decreed must occur.'
EXEC add_BibleVerse @BibleId, 127011037, N'He will not respect the gods of his fathers – not even the god loved by women. He will not respect any god; he will elevate himself above them all.'
EXEC add_BibleVerse @BibleId, 127011038, N'What he will honor is a god of fortresses – a god his fathers did not acknowledge he will honor with gold, silver, valuable stones, and treasured commodities.'
EXEC add_BibleVerse @BibleId, 127011039, N'He will attack mighty fortresses, aided by a foreign deity. To those who recognize him he will grant considerable honor. He will place them in authority over many people, and he will parcel out land for a price.'
EXEC add_BibleVerse @BibleId, 127011040, N'“At the time of the end the king of the south will attack him. Then the king of the north will storm against him with chariots, horsemen, and a large armada of ships. He will invade lands, passing through them like an overflowing river.'
EXEC add_BibleVerse @BibleId, 127011041, N'Then he will enter the beautiful land. Many will fall, but these will escape: Edom, Moab, and the Ammonite leadership.'
EXEC add_BibleVerse @BibleId, 127011042, N'He will extend his power against other lands; the land of Egypt will not escape.'
EXEC add_BibleVerse @BibleId, 127011043, N'He will have control over the hidden stores of gold and silver, as well as all the treasures of Egypt. Libyans and Ethiopians will submit to him.'
EXEC add_BibleVerse @BibleId, 127011044, N'But reports will trouble him from the east and north, and he will set out in a tremendous rage to destroy and wipe out many.'
EXEC add_BibleVerse @BibleId, 127011045, N'He will pitch his royal tents between the seas toward the beautiful holy mountain. But he will come to his end, with no one to help him.'
EXEC add_BibleVerse @BibleId, 127012001, N'“At that time Michael, the great prince who watches over your people, will arise. There will be a time of distress unlike any other from the nation’s beginning up to that time. But at that time your own people, all those whose names are found written in the book, will escape.'
EXEC add_BibleVerse @BibleId, 127012002, N'Many of those who sleep in the dusty ground will awake – some to everlasting life, and others to shame and everlasting abhorrence.'
EXEC add_BibleVerse @BibleId, 127012003, N'But the wise will shine like the brightness of the heavenly expanse. And those bringing many to righteousness will be like the stars forever and ever.'
EXEC add_BibleVerse @BibleId, 127012004, N'“But you, Daniel, close up these words and seal the book until the time of the end. Many will dash about, and knowledge will increase.”'
EXEC add_BibleVerse @BibleId, 127012005, N'I, Daniel, watched as two others stood there, one on each side of the river.'
EXEC add_BibleVerse @BibleId, 127012006, N'One said to the man clothed in linen who was above the waters of the river, “When will the end of these wondrous events occur?”'
EXEC add_BibleVerse @BibleId, 127012007, N'Then I heard the man clothed in linen who was over the waters of the river as he raised both his right and left hands to the sky and made an oath by the one who lives forever: “It is for a time, times, and half a time. Then, when the power of the one who shatters the holy people has been exhausted, all these things will be finished.”'
EXEC add_BibleVerse @BibleId, 127012008, N'I heard, but I did not understand. So I said, “Sir, what will happen after these things?”'
EXEC add_BibleVerse @BibleId, 127012009, N'He said, “Go, Daniel. For these matters are closed and sealed until the time of the end.'
EXEC add_BibleVerse @BibleId, 127012010, N'Many will be purified, made clean, and refined, but the wicked will go on being wicked. None of the wicked will understand, though the wise will understand.'
EXEC add_BibleVerse @BibleId, 127012011, N'From the time that the daily sacrifice is removed and the abomination that causes desolation is set in place, there are 1,290 days.'
EXEC add_BibleVerse @BibleId, 127012012, N'Blessed is the one who waits and attains to the 1,335 days.'
EXEC add_BibleVerse @BibleId, 127012013, N'But you should go your way until the end. You will rest and then at the end of the days you will arise to receive what you have been allotted.”'
EXEC add_BibleVerse @BibleId, 128001001, N'This is the word of the Lord which was revealed to Hosea son of Beeri during the time when Uzziah, Jotham, Ahaz, and Hezekiah ruled Judah, and during the time when Jeroboam son of Joash ruled Israel.'
EXEC add_BibleVerse @BibleId, 128001002, N'When the Lord first spoke through Hosea, he said to him, “Go marry a prostitute who will bear illegitimate children conceived through prostitution, because the nation continually commits spiritual prostitution by turning away from the Lord.”'
EXEC add_BibleVerse @BibleId, 128001003, N'So Hosea married Gomer, the daughter of Diblaim. Then she conceived and gave birth to a son for him.'
EXEC add_BibleVerse @BibleId, 128001004, N'Then the Lord said to Hosea, “Name him ‘Jezreel,’ because in a little while I will punish the dynasty of Jehu on account of the bloodshed in the valley of Jezreel, and I will put an end to the kingdom of Israel.'
EXEC add_BibleVerse @BibleId, 128001005, N'At that time, I will destroy the military power of Israel in the valley of Jezreel.”'
EXEC add_BibleVerse @BibleId, 128001006, N'She conceived again and gave birth to a daughter. Then the Lord said to him, “Name her ‘No Pity’ (Lo-Ruhamah) because I will no longer have pity on the nation of Israel. For I will certainly not forgive their guilt.'
EXEC add_BibleVerse @BibleId, 128001007, N'But I will have pity on the nation of Judah. I will deliver them by the Lord their God; I will not deliver them by the warrior’s bow, by sword, by military victory, by chariot horses, or by chariots.”'
EXEC add_BibleVerse @BibleId, 128001008, N'When she had weaned ‘No Pity’ (Lo-Ruhamah) she conceived again and gave birth to another son.'
EXEC add_BibleVerse @BibleId, 128001009, N'Then the Lord said: “Name him ‘Not My People’ (Lo-Ammi), because you are not my people and I am not your God.”'
EXEC add_BibleVerse @BibleId, 128001010, N'However, in the future the number of the people of Israel will be like the sand of the sea which can be neither measured nor numbered. Although it was said to them, “You are not my people,” it will be said to them, “You are children of the living God!”'
EXEC add_BibleVerse @BibleId, 128001011, N'Then the people of Judah and the people of Israel will be gathered together. They will appoint for themselves one leader, and will flourish in the land. Certainly, the day of Jezreel will be great!'
EXEC add_BibleVerse @BibleId, 128002001, N'Then you will call your brother, “My People” (Ammi)! You will call your sister, “Pity” (Ruhamah)!'
EXEC add_BibleVerse @BibleId, 128002002, N'Plead earnestly with your mother (for she is not my wife, and I am not her husband), so that she might put an end to her adulterous lifestyle, and turn away from her sexually immoral behavior.'
EXEC add_BibleVerse @BibleId, 128002003, N'Otherwise, I will strip her naked, and expose her like she was when she was born. I will turn her land into a wilderness and make her country a parched land, so that I might kill her with thirst.'
EXEC add_BibleVerse @BibleId, 128002004, N'I will have no pity on her children, because they are children conceived in adultery.'
EXEC add_BibleVerse @BibleId, 128002005, N'For their mother has committed adultery; she who conceived them has acted shamefully. For she said, “I will seek out my lovers; they are the ones who give me my bread and my water, my wool, my flax, my olive oil, and my wine.'
EXEC add_BibleVerse @BibleId, 128002006, N'Therefore, I will soon fence her in with thorns; I will wall her in so that she cannot find her way.'
EXEC add_BibleVerse @BibleId, 128002007, N'Then she will pursue her lovers, but she will not catch them; she will seek them, but she will not find them. Then she will say, “I will go back to my husband, because I was better off then than I am now.”'
EXEC add_BibleVerse @BibleId, 128002008, N'Yet until now she has refused to acknowledge that I was the one who gave her the grain, the new wine, and the olive oil; and that it was I who lavished on her the silver and gold – which they used in worshiping Baal!'
EXEC add_BibleVerse @BibleId, 128002009, N'Therefore, I will take back my grain during the harvest time and my new wine when it ripens; I will take away my wool and my flax which I had provided in order to clothe her.'
EXEC add_BibleVerse @BibleId, 128002010, N'Soon I will expose her lewd nakedness in front of her lovers, and no one will be able to rescue her from me!'
EXEC add_BibleVerse @BibleId, 128002011, N'I will put an end to all her celebration: her annual religious festivals, monthly new moon celebrations, and weekly Sabbath festivities – all her appointed festivals.'
EXEC add_BibleVerse @BibleId, 128002012, N'I will destroy her vines and fig trees, about which she said, “These are my wages for prostitution that my lovers gave to me!” I will turn her cultivated vines and fig trees into an uncultivated thicket, so that wild animals will devour them.'
EXEC add_BibleVerse @BibleId, 128002013, N'“I will punish her for the festival days when she burned incense to the Baal idols; she adorned herself with earrings and jewelry, and went after her lovers, but she forgot me!” says the Lord.'
EXEC add_BibleVerse @BibleId, 128002014, N'However, in the future I will allure her; I will lead her back into the wilderness, and speak tenderly to her.'
EXEC add_BibleVerse @BibleId, 128002015, N'From there I will give back her vineyards to her, and turn the “Valley of Trouble” into an “Opportunity for Hope.” There she will sing as she did when she was young, when she came up from the land of Egypt.'
EXEC add_BibleVerse @BibleId, 128002016, N'“At that time,” declares the Lord, “you will call, ‘My husband’; you will never again call me, ‘My master.’'
EXEC add_BibleVerse @BibleId, 128002017, N'For I will remove the names of the Baal idols from your lips, so that you will never again utter their names!”'
EXEC add_BibleVerse @BibleId, 128002018, N'“At that time I will make a covenant for them with the wild animals, the birds of the air, and the creatures that crawl on the ground. I will abolish the warrior’s bow and sword – that is, every weapon of warfare – from the land, and I will allow them to live securely.”'
EXEC add_BibleVerse @BibleId, 128002019, N'I will commit myself to you forever; I will commit myself to you in righteousness and justice, in steadfast love and tender compassion.'
EXEC add_BibleVerse @BibleId, 128002020, N'I will commit myself to you in faithfulness; then you will acknowledge the Lord.”'
EXEC add_BibleVerse @BibleId, 128002021, N'“At that time, I will willingly respond,” declares the Lord. “I will respond to the sky, and the sky will respond to the ground;'
EXEC add_BibleVerse @BibleId, 128002022, N'then the ground will respond to the grain, the new wine, and the olive oil; and they will respond to ‘God Plants’ (Jezreel)!'
EXEC add_BibleVerse @BibleId, 128002023, N'Then I will plant her as my own in the land. I will have pity on ‘No Pity’ (Lo-Ruhamah). I will say to ‘Not My People’ (Lo-Ammi), ‘You are my people!’ And he will say, ‘You are my God!’”'
EXEC add_BibleVerse @BibleId, 128003001, N'The Lord said to me, “Go, show love to your wife again, even though she loves another man and continually commits adultery. Likewise, the Lord loves the Israelites although they turn to other gods and love to offer raisin cakes to idols.”'
EXEC add_BibleVerse @BibleId, 128003002, N'So I paid fifteen shekels of silver and about seven bushels of barley to purchase her.'
EXEC add_BibleVerse @BibleId, 128003003, N'Then I told her, “You must live with me many days; you must not commit adultery or have sexual intercourse with another man, and I also will wait for you.”'
EXEC add_BibleVerse @BibleId, 128003004, N'For the Israelites must live many days without a king or prince, without sacrifice or sacred fertility pillar, without ephod or idols.'
EXEC add_BibleVerse @BibleId, 128003005, N'Afterward, the Israelites will turn and seek the Lord their God and their Davidic king. Then they will submit to the Lord in fear and receive his blessings in the future.'
EXEC add_BibleVerse @BibleId, 128004001, N'Hear the word of the Lord, you Israelites! For the Lord has a covenant lawsuit against the people of Israel. For there is neither faithfulness nor loyalty in the land, nor do they acknowledge God.'
EXEC add_BibleVerse @BibleId, 128004002, N'There is only cursing, lying, murder, stealing, and adultery. They resort to violence and bloodshed.'
EXEC add_BibleVerse @BibleId, 128004003, N'Therefore the land will mourn, and all its inhabitants will perish. The wild animals, the birds of the sky, and even the fish in the sea will perish.'
EXEC add_BibleVerse @BibleId, 128004004, N'Do not let anyone accuse or contend against anyone else: for my case is against you priests!'
EXEC add_BibleVerse @BibleId, 128004005, N'You stumble day and night, and the false prophets stumble with you; You have destroyed your own people!'
EXEC add_BibleVerse @BibleId, 128004006, N'You have destroyed my people by failing to acknowledge me! Because you refuse to acknowledge me, I will reject you as my priests. Because you reject the law of your God, I will reject your descendants.'
EXEC add_BibleVerse @BibleId, 128004007, N'The more the priests increased in numbers, the more they rebelled against me. They have turned their glorious calling into a shameful disgrace!'
EXEC add_BibleVerse @BibleId, 128004008, N'They feed on the sin offerings of my people; their appetites long for their iniquity!'
EXEC add_BibleVerse @BibleId, 128004009, N'I will deal with the people and priests together: I will punish them both for their ways, and I will repay them for their deeds.'
EXEC add_BibleVerse @BibleId, 128004010, N'They will eat, but not be satisfied; they will engage in prostitution, but not increase in numbers; because they have abandoned the Lord by pursuing other gods.'
EXEC add_BibleVerse @BibleId, 128004011, N'Old and new wine take away the understanding of my people.'
EXEC add_BibleVerse @BibleId, 128004012, N'They consult their wooden idols, and their diviner’s staff answers with an oracle. The wind of prostitution blows them astray; they commit spiritual adultery against their God.'
EXEC add_BibleVerse @BibleId, 128004013, N'They sacrifice on the mountaintops, and burn offerings on the hills; they sacrifice under oak, poplar, and terebinth, because their shade is so pleasant. As a result, your daughters have become cult prostitutes, and your daughters-in-law commit adultery!'
EXEC add_BibleVerse @BibleId, 128004014, N'I will not punish your daughters when they commit prostitution, nor your daughters-in-law when they commit adultery. For the men consort with harlots, they sacrifice with temple prostitutes. It is true: “A people that lacks understanding will come to ruin!”'
EXEC add_BibleVerse @BibleId, 128004015, N'Although you, O Israel, commit adultery, do not let Judah become guilty! Do not journey to Gilgal! Do not go up to Beth Aven! Do not swear, “As surely as the Lord lives!”'
EXEC add_BibleVerse @BibleId, 128004016, N'Israel has rebelled like a stubborn heifer! Soon the Lord will put them out to pasture like a lamb in a broad field!'
EXEC add_BibleVerse @BibleId, 128004017, N'Ephraim has attached himself to idols; Do not go near him!'
EXEC add_BibleVerse @BibleId, 128004018, N'They consume their alcohol, then engage in cult prostitution; they dearly love their shameful behavior.'
EXEC add_BibleVerse @BibleId, 128004019, N'A whirlwind has wrapped them in its wings; they will be brought to shame because of their idolatrous worship.'
EXEC add_BibleVerse @BibleId, 128005001, N'Hear this, you priests! Pay attention, you Israelites! Listen closely, O king! For judgment is about to overtake you! For you were like a trap to Mizpah, like a net spread out to catch Tabor.'
EXEC add_BibleVerse @BibleId, 128005002, N'Those who revolt are knee-deep in slaughter, but I will discipline them all.'
EXEC add_BibleVerse @BibleId, 128005003, N'I know Ephraim all too well; the evil of Israel is not hidden from me. For you have engaged in prostitution, O Ephraim; Israel has defiled itself.'
EXEC add_BibleVerse @BibleId, 128005004, N'Their wicked deeds do not allow them to return to their God; because a spirit of idolatry controls their heart, and they do not acknowledge the Lord.'
EXEC add_BibleVerse @BibleId, 128005005, N'The arrogance of Israel testifies against it; Israel and Ephraim will be overthrown because of their iniquity. Even Judah will be brought down with them.'
EXEC add_BibleVerse @BibleId, 128005006, N'Although they bring their flocks and herds to seek the favor of the Lord, They will not find him – he has withdrawn himself from them!'
EXEC add_BibleVerse @BibleId, 128005007, N'They have committed treason against the Lord, because they bore illegitimate children. Soon the new moon festival will devour them and their fields.'
EXEC add_BibleVerse @BibleId, 128005008, N'Blow the ram’s horn in Gibeah! Sound the trumpet in Ramah! Sound the alarm in Beth Aven! Tremble in fear, O Benjamin!'
EXEC add_BibleVerse @BibleId, 128005009, N'Ephraim will be ruined in the day of judgment! What I am declaring to the tribes of Israel will certainly take place!'
EXEC add_BibleVerse @BibleId, 128005010, N'The princes of Judah are like those who move boundary markers. I will pour out my rage on them like a torrential flood!'
EXEC add_BibleVerse @BibleId, 128005011, N'Ephraim will be oppressed, crushed under judgment, because he was determined to pursue worthless idols.'
EXEC add_BibleVerse @BibleId, 128005012, N'I will be like a moth to Ephraim, like wood rot to the house of Judah.'
EXEC add_BibleVerse @BibleId, 128005013, N'When Ephraim saw his sickness and Judah saw his wound, then Ephraim turned to Assyria, and begged its great king for help. But he will not be able to heal you! He cannot cure your wound!'
EXEC add_BibleVerse @BibleId, 128005014, N'I will be like a lion to Ephraim, like a young lion to the house of Judah. I myself will tear them to pieces, then I will carry them off, and no one will be able to rescue them!'
EXEC add_BibleVerse @BibleId, 128005015, N'Then I will return again to my lair until they have suffered their punishment. Then they will seek me; in their distress they will earnestly seek me.'
EXEC add_BibleVerse @BibleId, 128006001, N'“Come on! Let’s return to the Lord! He himself has torn us to pieces, but he will heal us! He has injured us, but he will bandage our wounds!'
EXEC add_BibleVerse @BibleId, 128006002, N'He will restore us in a very short time; he will heal us in a little while, so that we may live in his presence.'
EXEC add_BibleVerse @BibleId, 128006003, N'So let us acknowledge him! Let us seek to acknowledge the Lord! He will come to our rescue as certainly as the appearance of the dawn, as certainly as the winter rain comes, as certainly as the spring rain that waters the land.”'
EXEC add_BibleVerse @BibleId, 128006004, N'What am I going to do with you, O Ephraim? What am I going to do with you, O Judah? For your faithfulness is as fleeting as the morning mist; it disappears as quickly as dawn’s dew!'
EXEC add_BibleVerse @BibleId, 128006005, N'Therefore, I will certainly cut you into pieces at the hands of the prophets; I will certainly kill you in fulfillment of my oracles of judgment; for my judgment will come forth like the light of the dawn.'
EXEC add_BibleVerse @BibleId, 128006006, N'For I delight in faithfulness, not simply in sacrifice; I delight in acknowledging God, not simply in whole burnt offerings.'
EXEC add_BibleVerse @BibleId, 128006007, N'At Adam they broke the covenant; Oh how they were unfaithful to me!'
EXEC add_BibleVerse @BibleId, 128006008, N'Gilead is a city full of evildoers; its streets are stained with bloody footprints!'
EXEC add_BibleVerse @BibleId, 128006009, N'The company of priests is like a gang of robbers, lying in ambush to pounce on a victim. They commit murder on the road to Shechem; they have done heinous crimes!'
EXEC add_BibleVerse @BibleId, 128006010, N'I have seen a disgusting thing in the temple of Israel: there Ephraim practices temple prostitution and Judah defiles itself.'
EXEC add_BibleVerse @BibleId, 128006011, N'I have appointed a time to reap judgment for you also, O Judah! Whenever I want to restore the fortunes of my people,'
EXEC add_BibleVerse @BibleId, 128007001, N'whenever I want to heal Israel, the sin of Ephraim is revealed, and the evil deeds of Samaria are exposed. For they do what is wrong; thieves break into houses, and gangs rob people out in the streets.'
EXEC add_BibleVerse @BibleId, 128007002, N'They do not realize that I remember all of their wicked deeds. Their evil deeds have now surrounded them; their sinful deeds are always before me.'
EXEC add_BibleVerse @BibleId, 128007003, N'The royal advisers delight the king with their evil schemes, the princes make him glad with their lies.'
EXEC add_BibleVerse @BibleId, 128007004, N'They are all like bakers, they are like a smoldering oven; they are like a baker who does not stoke the fire until the kneaded dough is ready for baking.'
EXEC add_BibleVerse @BibleId, 128007005, N'At the celebration of their king, his princes become inflamed with wine; they conspire with evildoers.'
EXEC add_BibleVerse @BibleId, 128007006, N'They approach him, all the while plotting against him. Their hearts are like an oven; their anger smolders all night long, but in the morning it bursts into a flaming fire.'
EXEC add_BibleVerse @BibleId, 128007007, N'All of them are blazing like an oven; they devour their rulers. All of their kings fall – and none of them call on me!'
EXEC add_BibleVerse @BibleId, 128007008, N'Ephraim has mixed itself like flour among the nations; Ephraim is like a ruined cake of bread that is scorched on one side.'
EXEC add_BibleVerse @BibleId, 128007009, N'Foreigners are consuming what his strenuous labor produced, but he does not recognize it! His head is filled with gray hair, but he does not realize it!'
EXEC add_BibleVerse @BibleId, 128007010, N'The arrogance of Israel testifies against him, yet they refuse to return to the Lord their God! In spite of all this they refuse to seek him!'
EXEC add_BibleVerse @BibleId, 128007011, N'Ephraim has been like a dove, easily deceived and lacking discernment. They called to Egypt for help; they turned to Assyria for protection.'
EXEC add_BibleVerse @BibleId, 128007012, N'I will throw my bird net over them while they are flying, I will bring them down like birds in the sky; I will discipline them when I hear them flocking together.'
EXEC add_BibleVerse @BibleId, 128007013, N'Woe to them! For they have fled from me! Destruction to them! For they have rebelled against me! I want to deliver them, but they have lied to me.'
EXEC add_BibleVerse @BibleId, 128007014, N'They do not pray to me, but howl in distress on their beds; They slash themselves for grain and new wine, but turn away from me.'
EXEC add_BibleVerse @BibleId, 128007015, N'Although I trained and strengthened them, they plot evil against me!'
EXEC add_BibleVerse @BibleId, 128007016, N'They turn to Baal; they are like an unreliable bow. Their leaders will fall by the sword because their prayers to Baal have made me angry. So people will disdain them in the land of Egypt.'
EXEC add_BibleVerse @BibleId, 128008001, N'Sound the alarm! An eagle looms over the temple of the Lord! For they have broken their covenant with me, and have rebelled against my law.'
EXEC add_BibleVerse @BibleId, 128008002, N'Israel cries out to me, “My God, we acknowledge you!”'
EXEC add_BibleVerse @BibleId, 128008003, N'But Israel has rejected what is morally good; so an enemy will pursue him.'
EXEC add_BibleVerse @BibleId, 128008004, N'They enthroned kings without my consent! They appointed princes without my approval! They made idols out of their silver and gold, but they will be destroyed!'
EXEC add_BibleVerse @BibleId, 128008005, N'O Samaria, he has rejected your calf idol! My anger burns against them! They will not survive much longer without being punished, even though they are Israelites!'
EXEC add_BibleVerse @BibleId, 128008006, N'That idol was made by a workman – it is not God! The calf idol of Samaria will be broken to bits.'
EXEC add_BibleVerse @BibleId, 128008007, N'They sow the wind, and so they will reap the whirlwind! The stalk does not have any standing grain; it will not produce any flour. Even if it were to yield grain, foreigners would swallow it all up.'
EXEC add_BibleVerse @BibleId, 128008008, N'Israel will be swallowed up among the nations; they will be like a worthless piece of pottery.'
EXEC add_BibleVerse @BibleId, 128008009, N'They have gone up to Assyria, like a wild donkey that wanders off. Ephraim has hired prostitutes as lovers.'
EXEC add_BibleVerse @BibleId, 128008010, N'Even though they have hired lovers among the nations, I will soon gather them together for judgment. Then they will begin to waste away under the oppression of a mighty king.'
EXEC add_BibleVerse @BibleId, 128008011, N'Although Ephraim has built many altars for sin offerings, these have become altars for sinning!'
EXEC add_BibleVerse @BibleId, 128008012, N'I spelled out my law for him in great detail, but they regard it as something totally unknown to them!'
EXEC add_BibleVerse @BibleId, 128008013, N'They offer up sacrificial gifts to me, and eat the meat, but the Lord does not accept their sacrifices. Soon he will remember their wrongdoing, he will punish their sins, and they will return to Egypt.'
EXEC add_BibleVerse @BibleId, 128008014, N'Israel has forgotten his Maker and built royal palaces, and Judah has built many fortified cities. But I will send fire on their cities; it will consume their royal citadels.'
EXEC add_BibleVerse @BibleId, 128009001, N'O Israel, do not rejoice jubilantly like the nations, for you are unfaithful to your God. You love to receive a prostitute''s wages on all the floors where you thresh your grain.'
EXEC add_BibleVerse @BibleId, 128009002, N'Threshing floors and wine vats will not feed the people, and new wine only deceives them.'
EXEC add_BibleVerse @BibleId, 128009003, N'They will not remain in the Lord’s land. Ephraim will return to Egypt; they will eat ritually unclean food in Assyria.'
EXEC add_BibleVerse @BibleId, 128009004, N'They will not pour out drink offerings of wine to the Lord; they will not please him with their sacrifices. Their sacrifices will be like bread eaten while in mourning; all those who eat them will make themselves ritually unclean. For their bread will be only to satisfy their appetite; it will not come into the temple of the Lord.'
EXEC add_BibleVerse @BibleId, 128009005, N'So what will you do on the festival day, on the festival days of the Lord?'
EXEC add_BibleVerse @BibleId, 128009006, N'Look! Even if they flee from the destruction, Egypt will take hold of them, and Memphis will bury them. The weeds will inherit the silver they treasure – thorn bushes will occupy their homes.'
EXEC add_BibleVerse @BibleId, 128009007, N'The time of judgment is about to arrive! The time of retribution is imminent! Let Israel know! The prophet is considered a fool – the inspired man is viewed as a madman – because of the multitude of your sins and your intense animosity.'
EXEC add_BibleVerse @BibleId, 128009008, N'The prophet is a watchman over Ephraim on behalf of God, yet traps are laid for him along all of his paths; animosity rages against him in the land of his God.'
EXEC add_BibleVerse @BibleId, 128009009, N'They have sunk deep into corruption as in the days of Gibeah. He will remember their wrongdoing. He will repay them for their sins.'
EXEC add_BibleVerse @BibleId, 128009010, N'When I found Israel, it was like finding grapes in the wilderness. I viewed your ancestors like an early fig on a fig tree in its first season. Then they came to Baal-Peor and they dedicated themselves to shame – they became as detestable as what they loved.'
EXEC add_BibleVerse @BibleId, 128009011, N'Ephraim will be like a bird; what they value will fly away. They will not bear children – they will not enjoy pregnancy – they will not even conceive!'
EXEC add_BibleVerse @BibleId, 128009012, N'Even if they raise their children, I will take away every last one of them. Woe to them! For I will turn away from them.'
EXEC add_BibleVerse @BibleId, 128009013, N'Just as lion cubs are born predators, so Ephraim will bear his sons for slaughter.'
EXEC add_BibleVerse @BibleId, 128009014, N'Give them, O Lord – what will you give them? Give them wombs that miscarry, and breasts that cannot nurse!'
EXEC add_BibleVerse @BibleId, 128009015, N'Because of all their evil in Gilgal, I hate them there. On account of their evil deeds, I will drive them out of my land. I will no longer love them; all their rulers are rebels.'
EXEC add_BibleVerse @BibleId, 128009016, N'Ephraim will be struck down – their root will be dried up; they will not yield any fruit. Even if they do bear children, I will kill their precious offspring.'
EXEC add_BibleVerse @BibleId, 128009017, N'My God will reject them, for they have not obeyed him; so they will be fugitives among the nations.'
EXEC add_BibleVerse @BibleId, 128010001, N'Israel was a fertile vine that yielded fruit. As his fruit multiplied, he multiplied altars to Baal. As his land prospered, they adorned the fertility pillars.'
EXEC add_BibleVerse @BibleId, 128010002, N'Their heart is slipping; soon they will be punished for their guilt. The Lord will break their altars; he will completely destroy their fertility pillars.'
EXEC add_BibleVerse @BibleId, 128010003, N'Very soon they will say, “We have no king since we did not fear the Lord. But what can a king do for us anyway?”'
EXEC add_BibleVerse @BibleId, 128010004, N'They utter empty words, taking false oaths and making empty agreements. Therefore legal disputes sprout up like poisonous weeds in the furrows of a plowed field.'
EXEC add_BibleVerse @BibleId, 128010005, N'The inhabitants of Samaria will lament over the calf idol of Beth Aven. Its people will mourn over it; its idolatrous priests will wail over it, because its splendor will be taken from them into exile.'
EXEC add_BibleVerse @BibleId, 128010006, N'Even the calf idol will be carried to Assyria, as tribute for the great king. Ephraim will be disgraced; Israel will be put to shame because of its wooden idol.'
EXEC add_BibleVerse @BibleId, 128010007, N'Samaria and its king will be carried off like a twig on the surface of the waters.'
EXEC add_BibleVerse @BibleId, 128010008, N'The high places of the “House of Wickedness” will be destroyed; it is the place where Israel sins. Thorns and thistles will grow up over its altars. Then they will say to the mountains, “Cover us!” and to the hills, “Fall on us!”'
EXEC add_BibleVerse @BibleId, 128010009, N'O Israel, you have sinned since the time of Gibeah, and there you have remained. Did not war overtake the evildoers in Gibeah?'
EXEC add_BibleVerse @BibleId, 128010010, N'When I please, I will discipline them; I will gather nations together to attack them, to bind them in chains for their two sins.'
EXEC add_BibleVerse @BibleId, 128010011, N'Ephraim was a well-trained heifer who loved to thresh grain; I myself put a fine yoke on her neck. I will harness Ephraim. Let Judah plow! Let Jacob break up the unplowed ground for himself!'
EXEC add_BibleVerse @BibleId, 128010012, N'Sow righteousness for yourselves, reap unfailing love. Break up the unplowed ground for yourselves, for it is time to seek the Lord, until he comes and showers deliverance on you.'
EXEC add_BibleVerse @BibleId, 128010013, N'But you have plowed wickedness; you have reaped injustice; you have eaten the fruit of deception. Because you have depended on your chariots; you have relied on your many warriors.'
EXEC add_BibleVerse @BibleId, 128010014, N'The roar of battle will rise against your people; all your fortresses will be devastated, just as Shalman devastated Beth Arbel on the day of battle, when mothers were dashed to the ground with their children.'
EXEC add_BibleVerse @BibleId, 128010015, N'So will it happen to you, O Bethel, because of your great wickedness! When that day dawns, the king of Israel will be destroyed.'
EXEC add_BibleVerse @BibleId, 128011001, N'When Israel was a young man, I loved him like a son, and I summoned my son out of Egypt.'
EXEC add_BibleVerse @BibleId, 128011002, N'But the more I summoned them, the farther they departed from me. They sacrificed to the Baal idols and burned incense to images.'
EXEC add_BibleVerse @BibleId, 128011003, N'Yet it was I who led Ephraim, I took them by the arm; but they did not acknowledge that I had healed them.'
EXEC add_BibleVerse @BibleId, 128011004, N'I led them with leather cords, with leather ropes; I lifted the yoke from their neck, and gently fed them.'
EXEC add_BibleVerse @BibleId, 128011005, N'They will return to Egypt! Assyria will rule over them because they refuse to repent!'
EXEC add_BibleVerse @BibleId, 128011006, N'A sword will flash in their cities, it will destroy the bars of their city gates, and will devour them in their fortresses.'
EXEC add_BibleVerse @BibleId, 128011007, N'My people are obsessed with turning away from me; they call to Baal, but he will never exalt them!'
EXEC add_BibleVerse @BibleId, 128011008, N'How can I give you up, O Ephraim? How can I surrender you, O Israel? How can I treat you like Admah? How can I make you like Zeboiim? I have had a change of heart! All my tender compassions are aroused!'
EXEC add_BibleVerse @BibleId, 128011009, N'I cannot carry out my fierce anger! I cannot totally destroy Ephraim! Because I am God, and not man – the Holy One among you – I will not come in wrath!'
EXEC add_BibleVerse @BibleId, 128011010, N'He will roar like a lion, and they will follow the Lord; when he roars, his children will come trembling from the west.'
EXEC add_BibleVerse @BibleId, 128011011, N'They will return in fear and trembling like birds from Egypt, like doves from Assyria, and I will settle them in their homes,” declares the Lord.'
EXEC add_BibleVerse @BibleId, 128011012, N'Ephraim has surrounded me with lies; the house of Israel has surrounded me with deceit. But Judah still roams about with God; he remains faithful to the Holy One.'
EXEC add_BibleVerse @BibleId, 128012001, N'Ephraim continually feeds on the wind; he chases the east wind all day; he multiplies lies and violence. They make treaties with Assyria, and send olive oil as tribute to Egypt.'
EXEC add_BibleVerse @BibleId, 128012002, N'The Lord also has a covenant lawsuit against Judah; he will punish Jacob according to his ways and repay him according to his deeds.'
EXEC add_BibleVerse @BibleId, 128012003, N'In the womb he attacked his brother; in his manly vigor he struggled with God.'
EXEC add_BibleVerse @BibleId, 128012004, N'He struggled with an angel and prevailed; he wept and begged for his favor. He found God at Bethel, and there he spoke with him!'
EXEC add_BibleVerse @BibleId, 128012005, N'As for the Lord God Almighty, the Lord is the name by which he is remembered!'
EXEC add_BibleVerse @BibleId, 128012006, N'But you must return to your God, by maintaining love and justice, and by waiting for your God to return to you.'
EXEC add_BibleVerse @BibleId, 128012007, N'The businessmen love to cheat; they use dishonest scales.'
EXEC add_BibleVerse @BibleId, 128012008, N'Ephraim boasts, “I am very rich! I have become wealthy! In all that I have done to gain my wealth, no one can accuse me of any offense that is actually sinful.”'
EXEC add_BibleVerse @BibleId, 128012009, N'“I am the Lord your God who brought you out of Egypt; I will make you live in tents again as in the days of old.'
EXEC add_BibleVerse @BibleId, 128012010, N'I spoke to the prophets; I myself revealed many visions; I spoke in parables through the prophets.”'
EXEC add_BibleVerse @BibleId, 128012011, N'Is there idolatry in Gilead? Certainly its inhabitants will come to nothing! Do they sacrifice bulls in Gilgal? Surely their altars will be like stones heaped up on a plowed field!'
EXEC add_BibleVerse @BibleId, 128012012, N'Jacob fled to the country of Aram, then Israel worked to acquire a wife; he tended sheep to pay for her.'
EXEC add_BibleVerse @BibleId, 128012013, N'The Lord brought Israel out of Egypt by a prophet, and due to a prophet Israel was preserved alive.'
EXEC add_BibleVerse @BibleId, 128012014, N'But Ephraim bitterly provoked him to anger; so he will hold him accountable for the blood he has shed, his Lord will repay him for the contempt he has shown.'
EXEC add_BibleVerse @BibleId, 128013001, N'When Ephraim spoke, there was terror; he was exalted in Israel, but he became guilty by worshiping Baal and died.'
EXEC add_BibleVerse @BibleId, 128013002, N'Even now they persist in sin! They make metal images for themselves, idols that they skillfully fashion from their own silver; all of them are nothing but the work of craftsmen! There is a saying about them: “Those who sacrifice to the calf idol are calf kissers!”'
EXEC add_BibleVerse @BibleId, 128013003, N'Therefore they will disappear like the morning mist, like early morning dew that evaporates, like chaff that is blown away from a threshing floor, like smoke that disappears through an open window.'
EXEC add_BibleVerse @BibleId, 128013004, N'But I am the Lord your God, who brought you out of Egypt. Therefore, you must not acknowledge any God but me; except me there is no Savior.'
EXEC add_BibleVerse @BibleId, 128013005, N'I cared for you in the wilderness, in the dry desert where no water was.'
EXEC add_BibleVerse @BibleId, 128013006, N'When they were fed, they became satisfied; when they were satisfied, they became proud; as a result, they forgot me!'
EXEC add_BibleVerse @BibleId, 128013007, N'So I will pounce on them like a lion; like a leopard I will lurk by the path.'
EXEC add_BibleVerse @BibleId, 128013008, N'I will attack them like a bear robbed of her cubs – I will rip open their chests. I will devour them there like a lion – like a wild animal would tear them apart.'
EXEC add_BibleVerse @BibleId, 128013009, N'I will destroy you, O Israel! Who is there to help you?'
EXEC add_BibleVerse @BibleId, 128013010, N'Where then is your king, that he may save you in all your cities? Where are your rulers for whom you asked, saying, “Give me a king and princes”?'
EXEC add_BibleVerse @BibleId, 128013011, N'I granted you a king in my anger, and I will take him away in my wrath!'
EXEC add_BibleVerse @BibleId, 128013012, N'The punishment of Ephraim has been decreed; his punishment is being stored up for the future.'
EXEC add_BibleVerse @BibleId, 128013013, N'The labor pains of a woman will overtake him, but the baby will lack wisdom; when the time arrives, he will not come out of the womb!'
EXEC add_BibleVerse @BibleId, 128013014, N'Will I deliver them from the power of Sheol? No, I will not! Will I redeem them from death? No, I will not! O Death, bring on your plagues! O Sheol, bring on your destruction! My eyes will not show any compassion!'
EXEC add_BibleVerse @BibleId, 128013015, N'Even though he flourishes like a reed plant, a scorching east wind will come, a wind from the Lord rising up from the desert. As a result, his spring will dry up; his well will become dry. That wind will spoil all his delightful foods in the containers in his storehouse.'
EXEC add_BibleVerse @BibleId, 128013016, N'Samaria will be held guilty, because she rebelled against her God. They will fall by the sword, their infants will be dashed to the ground – their pregnant women will be ripped open.'
EXEC add_BibleVerse @BibleId, 128014001, N'Return, O Israel, to the Lord your God, for your sin has been your downfall!'
EXEC add_BibleVerse @BibleId, 128014002, N'Return to the Lord and repent! Say to him: “Completely forgive our iniquity; accept our penitential prayer, that we may offer the praise of our lips as sacrificial bulls.'
EXEC add_BibleVerse @BibleId, 128014003, N'Assyria cannot save us; we will not ride warhorses. We will never again say, ‘Our gods’ to what our own hands have made. For only you will show compassion to Orphan Israel!”'
EXEC add_BibleVerse @BibleId, 128014004, N'“I will heal their waywardness and love them freely, for my anger will turn away from them.'
EXEC add_BibleVerse @BibleId, 128014005, N'I will be like the dew to Israel; he will blossom like a lily, he will send down his roots like a cedar of Lebanon.'
EXEC add_BibleVerse @BibleId, 128014006, N'His young shoots will grow; his splendor will be like an olive tree, his fragrance like a cedar of Lebanon.'
EXEC add_BibleVerse @BibleId, 128014007, N'People will reside again in his shade; they will plant and harvest grain in abundance. They will blossom like a vine, and his fame will be like the wine from Lebanon.'
EXEC add_BibleVerse @BibleId, 128014008, N'O Ephraim, I do not want to have anything to do with idols anymore! I will answer him and care for him. I am like a luxuriant cypress tree; your fruitfulness comes from me!'
EXEC add_BibleVerse @BibleId, 128014009, N'Who is wise? Let him discern these things! Who is discerning? Let him understand them! For the ways of the Lord are right; the godly walk in them, but in them the rebellious stumble.'
EXEC add_BibleVerse @BibleId, 129001001, N'This is the Lord’s message that was given to Joel the son of Pethuel:'
EXEC add_BibleVerse @BibleId, 129001002, N'Listen to this, you elders; pay attention, all inhabitants of the land. Has anything like this ever happened in your whole life or in the lifetime of your ancestors?'
EXEC add_BibleVerse @BibleId, 129001003, N'Tell your children about it, have your children tell their children, and their children the following generation.'
EXEC add_BibleVerse @BibleId, 129001004, N'What the gazam-locust left the ‘arbeh-locust consumed, what the ‘arbeh-locust left the yeleq-locust consumed, and what the yeleq-locust left the hasil-locust consumed!'
EXEC add_BibleVerse @BibleId, 129001005, N'Wake up, you drunkards, and weep! Wail, all you wine drinkers, because the sweet wine has been taken away from you.'
EXEC add_BibleVerse @BibleId, 129001006, N'For a nation has invaded our land. There are so many of them they are too numerous to count. Their teeth are like those of a lion; they tear apart their prey like a lioness.'
EXEC add_BibleVerse @BibleId, 129001007, N'They have destroyed our vines; they have turned our fig trees into mere splinters. They have completely stripped off the bark and thrown them aside; the twigs are stripped bare.'
EXEC add_BibleVerse @BibleId, 129001008, N'Wail like a young virgin clothed in sackcloth, lamenting the death of her husband-to-be.'
EXEC add_BibleVerse @BibleId, 129001009, N'No one brings grain offerings or drink offerings to the temple of the Lord anymore. So the priests, those who serve the Lord, are in mourning.'
EXEC add_BibleVerse @BibleId, 129001010, N'The crops of the fields have been destroyed. The ground is in mourning because the grain has perished. The fresh wine has dried up; the olive oil languishes.'
EXEC add_BibleVerse @BibleId, 129001011, N'Be distressed, farmers; wail, vinedressers, over the wheat and the barley. For the harvest of the field has perished.'
EXEC add_BibleVerse @BibleId, 129001012, N'The vine has dried up; the fig tree languishes – the pomegranate, date, and apple as well. In fact, all the trees of the field have dried up. Indeed, the joy of the people has dried up!'
EXEC add_BibleVerse @BibleId, 129001013, N'Get dressed and lament, you priests! Wail, you who minister at the altar! Come, spend the night in sackcloth, you servants of my God, because no one brings grain offerings or drink offerings to the temple of your God anymore.'
EXEC add_BibleVerse @BibleId, 129001014, N'Announce a holy fast; proclaim a sacred assembly. Gather the elders and all the inhabitants of the land to the temple of the Lord your God, and cry out to the Lord.'
EXEC add_BibleVerse @BibleId, 129001015, N'How awful that day will be! For the day of the Lord is near; it will come as destruction from the Divine Destroyer.'
EXEC add_BibleVerse @BibleId, 129001016, N'Our food has been cut off right before our eyes! There is no longer any joy or gladness in the temple of our God!'
EXEC add_BibleVerse @BibleId, 129001017, N'The grains of seed have shriveled beneath their shovels. Storehouses have been decimated and granaries have been torn down, for the grain has dried up.'
EXEC add_BibleVerse @BibleId, 129001018, N'Listen to the cattle groan! The herds of livestock wander around in confusion because they have no pasture. Even the flocks of sheep are suffering.'
EXEC add_BibleVerse @BibleId, 129001019, N'To you, O Lord, I call out for help, for fire has burned up the grassy pastures, flames have razed all the trees in the fields.'
EXEC add_BibleVerse @BibleId, 129001020, N'Even the wild animals cry out to you; for the river beds have dried up; fire has destroyed the grassy pastures.'
EXEC add_BibleVerse @BibleId, 129002001, N'Blow the trumpet in Zion; sound the alarm signal on my holy mountain! Let all the inhabitants of the land shake with fear, for the day of the Lord is about to come. Indeed, it is near!'
EXEC add_BibleVerse @BibleId, 129002002, N'It will be a day of dreadful darkness, a day of foreboding storm clouds, like blackness spread over the mountains. It is a huge and powerful army – there has never been anything like it ever before, and there will not be anything like it for many generations to come!'
EXEC add_BibleVerse @BibleId, 129002003, N'Like fire they devour everything in their path; a flame blazes behind them. The land looks like the Garden of Eden before them, but behind them there is only a desolate wilderness – for nothing escapes them!'
EXEC add_BibleVerse @BibleId, 129002004, N'They look like horses; they charge ahead like war horses.'
EXEC add_BibleVerse @BibleId, 129002005, N'They sound like chariots rumbling over mountain tops, like the crackling of blazing fire consuming stubble, like the noise of a mighty army being drawn up for battle.'
EXEC add_BibleVerse @BibleId, 129002006, N'People writhe in fear when they see them. All of their faces turn pale with fright.'
EXEC add_BibleVerse @BibleId, 129002007, N'They charge like warriors; they scale walls like soldiers. Each one proceeds on his course; they do not alter their path.'
EXEC add_BibleVerse @BibleId, 129002008, N'They do not jostle one another; each of them marches straight ahead. They burst through the city defenses and do not break ranks.'
EXEC add_BibleVerse @BibleId, 129002009, N'They rush into the city; they scale its walls. They climb up into the houses; they go in through the windows like a thief.'
EXEC add_BibleVerse @BibleId, 129002010, N'The earth quakes before them; the sky reverberates. The sun and the moon grow dark; the stars refuse to shine.'
EXEC add_BibleVerse @BibleId, 129002011, N'The voice of the Lord thunders as he leads his army. Indeed, his warriors are innumerable; Surely his command is carried out! Yes, the day of the Lord is awesome and very terrifying – who can survive it?'
EXEC add_BibleVerse @BibleId, 129002012, N'“Yet even now,” the Lord says, “return to me with all your heart – with fasting, weeping, and mourning. Tear your hearts, not just your garments!”'
EXEC add_BibleVerse @BibleId, 129002013, N'Return to the Lord your God, for he is merciful and compassionate, slow to anger and boundless in loyal love – often relenting from calamitous punishment.'
EXEC add_BibleVerse @BibleId, 129002014, N'Who knows? Perhaps he will be compassionate and grant a reprieve, and leave blessing in his wake – a meal offering and a drink offering for you to offer to the Lord your God!'
EXEC add_BibleVerse @BibleId, 129002015, N'Blow the trumpet in Zion. Announce a holy fast; proclaim a sacred assembly!'
EXEC add_BibleVerse @BibleId, 129002016, N'Gather the people; sanctify an assembly! Gather the elders; gather the children and the nursing infants. Let the bridegroom come out from his bedroom and the bride from her private quarters.'
EXEC add_BibleVerse @BibleId, 129002017, N'Let the priests, those who serve the Lord, weep from the vestibule all the way back to the altar. Let them say, “Have pity, O Lord, on your people; please do not turn over your inheritance to be mocked, to become a proverb among the nations. Why should it be said among the peoples, “Where is their God?”'
EXEC add_BibleVerse @BibleId, 129002018, N'Then the Lord became zealous for his land; he had compassion on his people.'
EXEC add_BibleVerse @BibleId, 129002019, N'The Lord responded to his people, “Look! I am about to restore your grain as well as fresh wine and olive oil. You will be fully satisfied. I will never again make you an object of mockery among the nations.'
EXEC add_BibleVerse @BibleId, 129002020, N'I will remove the one from the north far from you. I will drive him out to a dry and desolate place. Those in front will be driven eastward into the Dead Sea, and those in back westward into the Mediterranean Sea. His stench will rise up as a foul smell.” Indeed, the Lord has accomplished great things.'
EXEC add_BibleVerse @BibleId, 129002021, N'Do not fear, my land! Rejoice and be glad, because the Lord has accomplished great things!'
EXEC add_BibleVerse @BibleId, 129002022, N'Do not fear, wild animals! For the pastures of the wilderness are again green with grass. Indeed, the trees bear their fruit; the fig tree and the vine yield to their fullest.'
EXEC add_BibleVerse @BibleId, 129002023, N'Citizens of Zion, rejoice! Be glad because of what the Lord your God has done! For he has given to you the early rains as vindication. He has sent to you the rains – both the early and the late rains as formerly.'
EXEC add_BibleVerse @BibleId, 129002024, N'The threshing floors are full of grain; the vats overflow with fresh wine and olive oil.'
EXEC add_BibleVerse @BibleId, 129002025, N'I will make up for the years that the ‘arbeh-locust consumed your crops – the yeleq-locust, the hasil-locust, and the gazam-locust – my great army that I sent against you.'
EXEC add_BibleVerse @BibleId, 129002026, N'You will have plenty to eat, and your hunger will be fully satisfied; you will praise the name of the Lord your God, who has acted wondrously in your behalf. My people will never again be put to shame.'
EXEC add_BibleVerse @BibleId, 129002027, N'You will be convinced that I am in the midst of Israel. I am the Lord your God; there is no other. My people will never again be put to shame.'
EXEC add_BibleVerse @BibleId, 129002028, N'After all of this I will pour out my Spirit on all kinds of people. Your sons and daughters will prophesy. Your elderly will have revelatory dreams; your young men will see prophetic visions.'
EXEC add_BibleVerse @BibleId, 129002029, N'Even on male and female servants I will pour out my Spirit in those days.'
EXEC add_BibleVerse @BibleId, 129002030, N'I will produce portents both in the sky and on the earth – blood, fire, and columns of smoke.'
EXEC add_BibleVerse @BibleId, 129002031, N'The sunlight will be turned to darkness and the moon to the color of blood, before the day of the Lord comes – that great and terrible day!'
EXEC add_BibleVerse @BibleId, 129002032, N'It will so happen that everyone who calls on the name of the Lord will be delivered. For on Mount Zion and in Jerusalem there will be those who survive, just as the Lord has promised; the remnant will be those whom the Lord will call.'
EXEC add_BibleVerse @BibleId, 129003001, N'For look! In those days and at that time I will return the exiles to Judah and Jerusalem.'
EXEC add_BibleVerse @BibleId, 129003002, N'Then I will gather all the nations, and bring them down to the valley of Jehoshaphat. I will enter into judgment against them there concerning my people Israel who are my inheritance, whom they scattered among the nations. They partitioned my land,'
EXEC add_BibleVerse @BibleId, 129003003, N'and they cast lots for my people. They traded a boy for a prostitute; they sold a little girl for wine so they could drink.'
EXEC add_BibleVerse @BibleId, 129003004, N'Why are you doing these things to me, Tyre and Sidon? Are you trying to get even with me, land of Philistia? I will very quickly repay you for what you have done!'
EXEC add_BibleVerse @BibleId, 129003005, N'For you took my silver and my gold and brought my precious valuables to your own palaces.'
EXEC add_BibleVerse @BibleId, 129003006, N'You sold Judeans and Jerusalemites to the Greeks, removing them far from their own country.'
EXEC add_BibleVerse @BibleId, 129003007, N'Look! I am rousing them from that place to which you sold them. I will repay you for what you have done!'
EXEC add_BibleVerse @BibleId, 129003008, N'I will sell your sons and daughters to the people of Judah. They will sell them to the Sabeans, a nation far away. Indeed, the Lord has spoken!'
EXEC add_BibleVerse @BibleId, 129003009, N'Proclaim this among the nations: “Prepare for a holy war! Call out the warriors! Let all these fighting men approach and attack!'
EXEC add_BibleVerse @BibleId, 129003010, N'Beat your plowshares into swords, and your pruning hooks into spears! Let the weak say, ‘I too am a warrior!’'
EXEC add_BibleVerse @BibleId, 129003011, N'Lend your aid and come, all you surrounding nations, and gather yourselves to that place.” Bring down, O Lord, your warriors!'
EXEC add_BibleVerse @BibleId, 129003012, N'Let the nations be roused and let them go up to the valley of Jehoshaphat, for there I will sit in judgment on all the surrounding nations.'
EXEC add_BibleVerse @BibleId, 129003013, N'Rush forth with the sickle, for the harvest is ripe! Come, stomp the grapes, for the winepress is full! The vats overflow. Indeed, their evil is great!'
EXEC add_BibleVerse @BibleId, 129003014, N'Crowds, great crowds are in the valley of decision, for the day of the Lord is near in the valley of decision!'
EXEC add_BibleVerse @BibleId, 129003015, N'The sun and moon are darkened; the stars withhold their brightness.'
EXEC add_BibleVerse @BibleId, 129003016, N'The Lord roars from Zion; from Jerusalem his voice bellows out. The heavens and the earth shake. But the Lord is a refuge for his people; he is a stronghold for the citizens of Israel.'
EXEC add_BibleVerse @BibleId, 129003017, N'You will be convinced that I the Lord am your God, dwelling on Zion, my holy mountain. Jerusalem will be holy – conquering armies will no longer pass through it.'
EXEC add_BibleVerse @BibleId, 129003018, N'On that day the mountains will drip with sweet wine, and the hills will flow with milk. All the dry stream beds of Judah will flow with water. A spring will flow out from the temple of the Lord, watering the Valley of Acacia Trees.'
EXEC add_BibleVerse @BibleId, 129003019, N'Egypt will be desolate and Edom will be a desolate wilderness, because of the violence they did to the people of Judah, in whose land they shed innocent blood.'
EXEC add_BibleVerse @BibleId, 129003020, N'But Judah will reside securely forever, and Jerusalem will be secure from one generation to the next.'
EXEC add_BibleVerse @BibleId, 129003021, N'I will avenge their blood which I had not previously acquitted. It is the Lord who dwells in Zion!'
EXEC add_BibleVerse @BibleId, 130001001, N'The following is a record of what Amos prophesied. He was one of the herdsmen from Tekoa. These prophecies about Israel were revealed to him during the time of King Uzziah of Judah and King Jeroboam son of Joash of Israel, two years before the earthquake.'
EXEC add_BibleVerse @BibleId, 130001002, N'Amos said: “The Lord comes roaring out of Zion; from Jerusalem he comes bellowing! The shepherds’ pastures wilt; the summit of Carmel withers.”'
EXEC add_BibleVerse @BibleId, 130001003, N'This is what the Lord says: “Because Damascus has committed three crimes – make that four! – I will not revoke my decree of judgment. They ripped through Gilead like threshing sledges with iron teeth.'
EXEC add_BibleVerse @BibleId, 130001004, N'So I will set Hazael’s house on fire; fire will consume Ben Hadad’s fortresses.'
EXEC add_BibleVerse @BibleId, 130001005, N'I will break the bar on the gate of Damascus. I will remove the ruler from Wicked Valley, the one who holds the royal scepter from Beth Eden. The people of Aram will be deported to Kir.” The Lord has spoken!'
EXEC add_BibleVerse @BibleId, 130001006, N'This is what the Lord says: “Because Gaza has committed three crimes – make that four! – I will not revoke my decree of judgment. They deported a whole community and sold them to Edom.'
EXEC add_BibleVerse @BibleId, 130001007, N'So I will set Gaza’s city wall on fire; fire will consume her fortresses.'
EXEC add_BibleVerse @BibleId, 130001008, N'I will remove the ruler from Ashdod, the one who holds the royal scepter from Ashkelon. I will strike Ekron with my hand; the rest of the Philistines will also die.” The sovereign Lord has spoken!'
EXEC add_BibleVerse @BibleId, 130001009, N'This is what the Lord says: “Because Tyre has committed three crimes – make that four! – I will not revoke my decree of judgment. They sold a whole community to Edom; they failed to observe a treaty of brotherhood.'
EXEC add_BibleVerse @BibleId, 130001010, N'So I will set fire to Tyre’s city wall; fire will consume her fortresses.”'
EXEC add_BibleVerse @BibleId, 130001011, N'This is what the Lord says: “Because Edom has committed three crimes – make that four! – I will not revoke my decree of judgment. He chased his brother with a sword; he wiped out his allies. In his anger he tore them apart without stopping to rest; in his fury he relentlessly attacked them.'
EXEC add_BibleVerse @BibleId, 130001012, N'So I will set Teman on fire; fire will consume Bozrah’s fortresses.”'
EXEC add_BibleVerse @BibleId, 130001013, N'This is what the Lord says: “Because the Ammonites have committed three crimes – make that four! – I will not revoke my decree of judgment. They ripped open Gilead’s pregnant women so they could expand their territory.'
EXEC add_BibleVerse @BibleId, 130001014, N'So I will set fire to Rabbah’s city wall; fire will consume her fortresses. War cries will be heard on the day of battle; a strong gale will blow on the day of the windstorm.'
EXEC add_BibleVerse @BibleId, 130001015, N'Ammon’s king will be deported; he and his officials will be carried off together.” The Lord has spoken!'
EXEC add_BibleVerse @BibleId, 130002001, N'This is what the Lord says: “Because Moab has committed three crimes – make that four! – I will not revoke my decree of judgment. They burned the bones of Edom’s king into lime.'
EXEC add_BibleVerse @BibleId, 130002002, N'So I will set Moab on fire, and it will consume Kerioth’s fortresses. Moab will perish in the heat of battle amid war cries and the blaring of the ram’s horn.'
EXEC add_BibleVerse @BibleId, 130002003, N'I will remove Moab’s leader; I will kill all Moab’s officials with him.” The Lord has spoken!'
EXEC add_BibleVerse @BibleId, 130002004, N'This is what the Lord says: “Because Judah has committed three covenant transgressions – make that four! – I will not revoke my decree of judgment. They rejected the Lord’s law; they did not obey his commands. Their false gods, to which their fathers were loyal, led them astray.'
EXEC add_BibleVerse @BibleId, 130002005, N'So I will set Judah on fire, and it will consume Jerusalem’s fortresses.”'
EXEC add_BibleVerse @BibleId, 130002006, N'This is what the Lord says: “Because Israel has committed three covenant transgressions – make that four! – I will not revoke my decree of judgment. They sold the innocent for silver, the needy for a pair of sandals.'
EXEC add_BibleVerse @BibleId, 130002007, N'They trample on the dirt-covered heads of the poor; they push the destitute away. A man and his father go to the same girl; in this way they show disrespect for my moral purity.'
EXEC add_BibleVerse @BibleId, 130002008, N'They stretch out on clothing seized as collateral; they do so right beside every altar! They drink wine bought with the fines they have levied; they do so right in the temple of their God!'
EXEC add_BibleVerse @BibleId, 130002009, N'For Israel’s sake I destroyed the Amorites. They were as tall as cedars and as strong as oaks, but I destroyed the fruit on their branches and their roots in the ground.'
EXEC add_BibleVerse @BibleId, 130002010, N'I brought you up from the land of Egypt; I led you through the wilderness for forty years so you could take the Amorites’ land as your own.'
EXEC add_BibleVerse @BibleId, 130002011, N'I made some of your sons prophets and some of your young men Nazirites. Is this not true, you Israelites?” The Lord is speaking!'
EXEC add_BibleVerse @BibleId, 130002012, N'“But you made the Nazirites drink wine; you commanded the prophets, ‘Do not prophesy!’'
EXEC add_BibleVerse @BibleId, 130002013, N'Look! I will press you down, like a cart loaded down with grain presses down.'
EXEC add_BibleVerse @BibleId, 130002014, N'Fast runners will find no place to hide; strong men will have no strength left; warriors will not be able to save their lives.'
EXEC add_BibleVerse @BibleId, 130002015, N'Archers will not hold their ground; fast runners will not save their lives, nor will those who ride horses.'
EXEC add_BibleVerse @BibleId, 130002016, N'Bravehearted warriors will run away naked in that day.” The Lord is speaking!'
EXEC add_BibleVerse @BibleId, 130003001, N'Listen, you Israelites, to this message which the Lord is proclaiming against you! This message is for the entire clan I brought up from the land of Egypt:'
EXEC add_BibleVerse @BibleId, 130003002, N'“I have chosen you alone from all the clans of the earth. Therefore I will punish you for all your sins.”'
EXEC add_BibleVerse @BibleId, 130003003, N'Do two walk together without having met?'
EXEC add_BibleVerse @BibleId, 130003004, N'Does a lion roar in the woods if he has not cornered his prey? Does a young lion bellow from his den if he has not caught something?'
EXEC add_BibleVerse @BibleId, 130003005, N'Does a bird swoop down into a trap on the ground if there is no bait? Does a trap spring up from the ground unless it has surely caught something?'
EXEC add_BibleVerse @BibleId, 130003006, N'If an alarm sounds in a city, do people not fear? If disaster overtakes a city, is the Lord not responsible?'
EXEC add_BibleVerse @BibleId, 130003007, N'Certainly the sovereign Lord does nothing without first revealing his plan to his servants the prophets.'
EXEC add_BibleVerse @BibleId, 130003008, N'A lion has roared! Who is not afraid? The sovereign Lord has spoken! Who can refuse to prophesy?'
EXEC add_BibleVerse @BibleId, 130003009, N'Make this announcement in the fortresses of Ashdod and in the fortresses in the land of Egypt. Say this: “Gather on the hills around Samaria! Observe the many acts of violence taking place within the city, the oppressive deeds occurring in it.”'
EXEC add_BibleVerse @BibleId, 130003010, N'“They do not know how to do what is right.” (The Lord is speaking.) “They store up the spoils of destructive violence in their fortresses.'
EXEC add_BibleVerse @BibleId, 130003011, N'Therefore,” says the sovereign Lord, “an enemy will encircle the land. He will take away your power; your fortresses will be looted.”'
EXEC add_BibleVerse @BibleId, 130003012, N'This is what the Lord says: “Just as a shepherd salvages from the lion’s mouth a couple of leg bones or a piece of an ear, so the Israelites who live in Samaria will be salvaged. They will be left with just a corner of a bed, and a part of a couch.”'
EXEC add_BibleVerse @BibleId, 130003013, N'Listen and warn the family of Jacob! The sovereign Lord, the God who commands armies, is speaking!'
EXEC add_BibleVerse @BibleId, 130003014, N'“Certainly when I punish Israel for their covenant transgressions, I will destroy Bethel’s altars. The horns of the altar will be cut off and fall to the ground.'
EXEC add_BibleVerse @BibleId, 130003015, N'I will destroy both the winter and summer houses. The houses filled with ivory will be ruined, the great houses will be swept away.” The Lord is speaking!'
EXEC add_BibleVerse @BibleId, 130004001, N'Listen to this message, you cows of Bashan who live on Mount Samaria! You oppress the poor; you crush the needy. You say to your husbands, “Bring us more to drink!”'
EXEC add_BibleVerse @BibleId, 130004002, N'The sovereign Lord confirms this oath by his own holy character: “Certainly the time is approaching when you will be carried away in baskets, every last one of you in fishermen’s pots.'
EXEC add_BibleVerse @BibleId, 130004003, N'Each of you will go straight through the gaps in the walls; you will be thrown out toward Harmon.” The Lord is speaking!'
EXEC add_BibleVerse @BibleId, 130004004, N'“Go to Bethel and rebel! At Gilgal rebel some more! Bring your sacrifices in the morning, your tithes on the third day!'
EXEC add_BibleVerse @BibleId, 130004005, N'Burn a thank offering of bread made with yeast! Make a public display of your voluntary offerings! For you love to do this, you Israelites.” The sovereign Lord is speaking!'
EXEC add_BibleVerse @BibleId, 130004006, N'“But surely I gave you no food to eat in any of your cities; you lacked food everywhere you live. Still you did not come back to me.” The Lord is speaking!'
EXEC add_BibleVerse @BibleId, 130004007, N'“I withheld rain from you three months before the harvest. I gave rain to one city, but not to another. One field would get rain, but the field that received no rain dried up.'
EXEC add_BibleVerse @BibleId, 130004008, N'People from two or three cities staggered into one city to get water, but remained thirsty. Still you did not come back to me.” The Lord is speaking!'
EXEC add_BibleVerse @BibleId, 130004009, N'“I destroyed your crops with blight and disease. Locusts kept devouring your orchards, vineyards, fig trees, and olive trees. Still you did not come back to me.” The Lord is speaking!'
EXEC add_BibleVerse @BibleId, 130004010, N'“I sent against you a plague like one of the Egyptian plagues. I killed your young men with the sword, along with the horses you had captured. I made the stench from the corpses rise up into your nostrils. Still you did not come back to me.” The Lord is speaking!'
EXEC add_BibleVerse @BibleId, 130004011, N'“I overthrew some of you the way God overthrew Sodom and Gomorrah. You were like a burning stick snatched from the flames. Still you did not come back to me.” The Lord is speaking!'
EXEC add_BibleVerse @BibleId, 130004012, N'“Therefore this is what I will do to you, Israel. Because I will do this to you, prepare to meet your God, Israel!'
EXEC add_BibleVerse @BibleId, 130004013, N'For here he is! He formed the mountains and created the wind. He reveals his plans to men. He turns the dawn into darkness and marches on the heights of the earth. The Lord, the God who commands armies, is his name!”'
EXEC add_BibleVerse @BibleId, 130005001, N'Listen to this funeral song I am ready to sing about you, family of Israel:'
EXEC add_BibleVerse @BibleId, 130005002, N'“The virgin Israel has fallen down and will not get up again. She is abandoned on her own land with no one to help her get up.”'
EXEC add_BibleVerse @BibleId, 130005003, N'The sovereign Lord says this: “The city that marches out with a thousand soldiers will have only a hundred left; the town that marches out with a hundred soldiers will have only ten left for the family of Israel.”'
EXEC add_BibleVerse @BibleId, 130005004, N'The Lord says this to the family of Israel: “Seek me so you can live!'
EXEC add_BibleVerse @BibleId, 130005005, N'Do not seek Bethel! Do not visit Gilgal! Do not journey down to Beer Sheba! For the people of Gilgal will certainly be carried into exile; and Bethel will become a place where disaster abounds.”'
EXEC add_BibleVerse @BibleId, 130005006, N'Seek the Lord so you can live! Otherwise he will break out like fire against Joseph’s family; the fire will consume and no one will be able to quench it and save Bethel.'
EXEC add_BibleVerse @BibleId, 130005007, N'The Israelites turn justice into bitterness; they throw what is fair and right to the ground.'
EXEC add_BibleVerse @BibleId, 130005008, N'(But there is one who made the constellations Pleiades and Orion; he can turn the darkness into morning and daylight into night. He summons the water of the seas and pours it out on the earth’s surface. The Lord is his name!'
EXEC add_BibleVerse @BibleId, 130005009, N'He flashes destruction down upon the strong so that destruction overwhelms the fortified places.)'
EXEC add_BibleVerse @BibleId, 130005010, N'The Israelites hate anyone who arbitrates at the city gate; they despise anyone who speaks honestly.'
EXEC add_BibleVerse @BibleId, 130005011, N'Therefore, because you make the poor pay taxes on their crops and exact a grain tax from them, you will not live in the houses you built with chiseled stone, nor will you drink the wine from the fine vineyards you planted.'
EXEC add_BibleVerse @BibleId, 130005012, N'Certainly I am aware of your many rebellious acts and your numerous sins. You torment the innocent, you take bribes, and you deny justice to the needy at the city gate.'
EXEC add_BibleVerse @BibleId, 130005013, N'For this reason whoever is smart keeps quiet in such a time, for it is an evil time.'
EXEC add_BibleVerse @BibleId, 130005014, N'Seek good and not evil so you can live! Then the Lord, the God who commands armies, just might be with you, as you claim he is.'
EXEC add_BibleVerse @BibleId, 130005015, N'Hate what is wrong, love what is right! Promote justice at the city gate! Maybe the Lord, the God who commands armies, will have mercy on those who are left from Joseph.'
EXEC add_BibleVerse @BibleId, 130005016, N'Because of Israel’s sins this is what the Lord, the God who commands armies, the sovereign One, says: “In all the squares there will be wailing, in all the streets they will mourn the dead. They will tell the field workers to lament and the professional mourners to wail.'
EXEC add_BibleVerse @BibleId, 130005017, N'In all the vineyards there will be wailing, for I will pass through your midst,” says the Lord.'
EXEC add_BibleVerse @BibleId, 130005018, N'Woe to those who wish for the day of the Lord Why do you want the Lord’s day of judgment to come? It will bring darkness, not light.'
EXEC add_BibleVerse @BibleId, 130005019, N'Disaster will be inescapable, as if a man ran from a lion only to meet a bear, then escaped into a house, leaned his hand against the wall, and was bitten by a poisonous snake.'
EXEC add_BibleVerse @BibleId, 130005020, N'Don’t you realize the Lord’s day of judgment will bring darkness, not light – gloomy blackness, not bright light?'
EXEC add_BibleVerse @BibleId, 130005021, N'“I absolutely despise your festivals! I get no pleasure from your religious assemblies!'
EXEC add_BibleVerse @BibleId, 130005022, N'Even if you offer me burnt and grain offerings, I will not be satisfied; I will not look with favor on your peace offerings of fattened calves.'
EXEC add_BibleVerse @BibleId, 130005023, N'Take away from me your noisy songs; I don’t want to hear the music of your stringed instruments.'
EXEC add_BibleVerse @BibleId, 130005024, N'Justice must flow like torrents of water, righteous actions like a stream that never dries up.'
EXEC add_BibleVerse @BibleId, 130005025, N'You did not bring me sacrifices and grain offerings during the forty years you spent in the wilderness, family of Israel.'
EXEC add_BibleVerse @BibleId, 130005026, N'You will pick up your images of Sikkuth, your king, and Kiyyun, your star god, which you made for yourselves,'
EXEC add_BibleVerse @BibleId, 130005027, N'and I will drive you into exile beyond Damascus,” says the Lord. He is called the God who commands armies!'
EXEC add_BibleVerse @BibleId, 130006001, N'Woe to those who live in ease in Zion, to those who feel secure on Mount Samaria. They think of themselves as the elite class of the best nation. The family of Israel looks to them for leadership.'
EXEC add_BibleVerse @BibleId, 130006002, N'They say to the people: “Journey over to Calneh and look at it! Then go from there to Hamath-Rabbah! Then go down to Gath of the Philistines! Are they superior to our two kingdoms? Is their territory larger than yours?”'
EXEC add_BibleVerse @BibleId, 130006003, N'You refuse to believe a day of disaster will come, but you establish a reign of violence.'
EXEC add_BibleVerse @BibleId, 130006004, N'They lie around on beds decorated with ivory, and sprawl out on their couches. They eat lambs from the flock, and calves from the middle of the pen.'
EXEC add_BibleVerse @BibleId, 130006005, N'They sing to the tune of stringed instruments; like David they invent musical instruments.'
EXEC add_BibleVerse @BibleId, 130006006, N'They drink wine from sacrificial bowls, and pour the very best oils on themselves. Yet they are not concerned over the ruin of Joseph.'
EXEC add_BibleVerse @BibleId, 130006007, N'Therefore they will now be the first to go into exile, and the religious banquets where they sprawl on couches will end.'
EXEC add_BibleVerse @BibleId, 130006008, N'The sovereign Lord confirms this oath by his very own life. The Lord, the God who commands armies, is speaking: “I despise Jacob’s arrogance; I hate their fortresses. I will hand over to their enemies the city of Samaria and everything in it.”'
EXEC add_BibleVerse @BibleId, 130006009, N'If ten men are left in one house, they too will die.'
EXEC add_BibleVerse @BibleId, 130006010, N'When their close relatives, the ones who will burn the corpses, pick up their bodies to remove the bones from the house, they will say to anyone who is in the inner rooms of the house, “Is anyone else with you?” He will respond, “Be quiet! Don’t invoke the Lord’s name!”'
EXEC add_BibleVerse @BibleId, 130006011, N'Indeed, look! The Lord is giving the command. He will smash the large house to bits, and the small house into little pieces.'
EXEC add_BibleVerse @BibleId, 130006012, N'Can horses run on rocky cliffs? Can one plow the sea with oxen? Yet you have turned justice into a poisonous plant, and the fruit of righteous actions into a bitter plant.'
EXEC add_BibleVerse @BibleId, 130006013, N'You are happy because you conquered Lo-Debar. You say, “Did we not conquer Karnaim by our own power?”'
EXEC add_BibleVerse @BibleId, 130006014, N'“Look! I am about to bring a nation against you, family of Israel.” The Lord, the God who commands armies, is speaking. “They will oppress you all the way from Lebo-Hamath to the Stream of the Arabah.”'
EXEC add_BibleVerse @BibleId, 130007001, N'The sovereign Lord showed me this: I saw him making locusts just as the crops planted late were beginning to sprout. (The crops planted late sprout after the royal harvest. )'
EXEC add_BibleVerse @BibleId, 130007002, N'When they had completely consumed the earth’s vegetation, I said, “Sovereign Lord, forgive Israel! How can Jacob survive? He is too weak!”'
EXEC add_BibleVerse @BibleId, 130007003, N'The Lord decided not to do this. “It will not happen,” the Lord said.'
EXEC add_BibleVerse @BibleId, 130007004, N'The sovereign Lord showed me this: I saw the sovereign Lord summoning a shower of fire. It consumed the great deep and devoured the fields.'
EXEC add_BibleVerse @BibleId, 130007005, N'I said, “Sovereign Lord, stop! How can Jacob survive? He is too weak!”'
EXEC add_BibleVerse @BibleId, 130007006, N'The Lord decided not to do this. The sovereign Lord said, “This will not happen either.”'
EXEC add_BibleVerse @BibleId, 130007007, N'He showed me this: I saw the sovereign One standing by a tin wall holding tin in his hand.'
EXEC add_BibleVerse @BibleId, 130007008, N'The Lord said to me, “What do you see, Amos?” I said, “Tin.” The sovereign One then said, “Look, I am about to place tin among my people Israel. I will no longer overlook their sin.'
EXEC add_BibleVerse @BibleId, 130007009, N'Isaac’s centers of worship will become desolate; Israel’s holy places will be in ruins. I will attack Jeroboam’s dynasty with the sword.”'
EXEC add_BibleVerse @BibleId, 130007010, N'Amaziah the priest of Bethel sent this message to King Jeroboam of Israel: “Amos is conspiring against you in the very heart of the kingdom of Israel! The land cannot endure all his prophecies.'
EXEC add_BibleVerse @BibleId, 130007011, N'As a matter of fact, Amos is saying this: ‘Jeroboam will die by the sword and Israel will certainly be carried into exile away from its land.’”'
EXEC add_BibleVerse @BibleId, 130007012, N'Amaziah then said to Amos, “Leave, you visionary! Run away to the land of Judah! Earn your living and prophesy there!'
EXEC add_BibleVerse @BibleId, 130007013, N'Don’t prophesy at Bethel any longer, for a royal temple and palace are here!”'
EXEC add_BibleVerse @BibleId, 130007014, N'Amos replied to Amaziah, “I was not a prophet by profession. No, I was a herdsman who also took care of sycamore fig trees.'
EXEC add_BibleVerse @BibleId, 130007015, N'Then the Lord took me from tending flocks and gave me this commission, ‘Go! Prophesy to my people Israel!’'
EXEC add_BibleVerse @BibleId, 130007016, N'So now listen to the Lord’s message! You say, ‘Don’t prophesy against Israel! Don’t preach against the family of Isaac!’'
EXEC add_BibleVerse @BibleId, 130007017, N'“Therefore this is what the Lord says: ‘Your wife will become a prostitute in the streets and your sons and daughters will die violently. Your land will be given to others and you will die in a foreign land. Israel will certainly be carried into exile away from its land.’”'
EXEC add_BibleVerse @BibleId, 130008001, N'The sovereign Lord showed me this: I saw a basket of summer fruit.'
EXEC add_BibleVerse @BibleId, 130008002, N'He said, “What do you see, Amos?” I replied, “A basket of summer fruit.” Then the Lord said to me, “The end has come for my people Israel! I will no longer overlook their sins.'
EXEC add_BibleVerse @BibleId, 130008003, N'The women singing in the temple will wail in that day.” The sovereign Lord is speaking. “There will be many corpses littered everywhere! Be quiet!”'
EXEC add_BibleVerse @BibleId, 130008004, N'Listen to this, you who trample the needy, and do away with the destitute in the land.'
EXEC add_BibleVerse @BibleId, 130008005, N'You say, “When will the new moon festival be over, so we can sell grain? When will the Sabbath end, so we can open up the grain bins? We’re eager to sell less for a higher price, and to cheat the buyer with rigged scales!'
EXEC add_BibleVerse @BibleId, 130008006, N'We’re eager to trade silver for the poor, a pair of sandals for the needy! We want to mix in some chaff with the grain!”'
EXEC add_BibleVerse @BibleId, 130008007, N'The Lord confirms this oath by the arrogance of Jacob: “I swear I will never forget all you have done!'
EXEC add_BibleVerse @BibleId, 130008008, N'Because of this the earth will quake, and all who live in it will mourn. The whole earth will rise like the River Nile, it will surge upward and then grow calm, like the Nile in Egypt.'
EXEC add_BibleVerse @BibleId, 130008009, N'In that day,” says the sovereign Lord, “I will make the sun set at noon, and make the earth dark in the middle of the day.'
EXEC add_BibleVerse @BibleId, 130008010, N'I will turn your festivals into funerals, and all your songs into funeral dirges. I will make everyone wear funeral clothes and cause every head to be shaved bald. I will make you mourn as if you had lost your only son; when it ends it will indeed have been a bitter day.'
EXEC add_BibleVerse @BibleId, 130008011, N'Be certain of this, the time is coming,” says the sovereign Lord, “when I will send a famine through the land – not a shortage of food or water but an end to divine revelation!'
EXEC add_BibleVerse @BibleId, 130008012, N'People will stagger from sea to sea, and from the north around to the east. They will wander about looking for a revelation from the Lord, but they will not find any.'
EXEC add_BibleVerse @BibleId, 130008013, N'In that day your beautiful young women and your young men will faint from thirst.'
EXEC add_BibleVerse @BibleId, 130008014, N'These are the ones who now take oaths in the name of the sinful idol goddess of Samaria. They vow, ‘As surely as your god lives, O Dan,’ or ‘As surely as your beloved one lives, O Beer Sheba!’ But they will fall down and not get up again.”'
EXEC add_BibleVerse @BibleId, 130009001, N'I saw the sovereign One standing by the altar and he said, “Strike the tops of the support pillars, so the thresholds shake! Knock them down on the heads of all the people, and I will kill the survivors with the sword. No one will be able to run away; no one will be able to escape.'
EXEC add_BibleVerse @BibleId, 130009002, N'Even if they could dig down into the netherworld, my hand would pull them up from there. Even if they could climb up to heaven, I would drag them down from there.'
EXEC add_BibleVerse @BibleId, 130009003, N'Even if they were to hide on the top of Mount Carmel, I would hunt them down and take them from there. Even if they tried to hide from me at the bottom of the sea, from there I would command the Sea Serpent to bite them.'
EXEC add_BibleVerse @BibleId, 130009004, N'Even when their enemies drive them into captivity, from there I will command the sword to kill them. I will not let them out of my sight; they will experience disaster, not prosperity.”'
EXEC add_BibleVerse @BibleId, 130009005, N'The sovereign Lord who commands armies will do this. He touches the earth and it dissolves; all who live on it mourn. The whole earth rises like the River Nile, and then grows calm like the Nile in Egypt.'
EXEC add_BibleVerse @BibleId, 130009006, N'He builds the upper rooms of his palace in heaven and sets its foundation supports on the earth. He summons the water of the sea and pours it out on the earth’s surface. The Lord is his name.'
EXEC add_BibleVerse @BibleId, 130009007, N'“You Israelites are just like the Ethiopians in my sight,” says the Lord. “Certainly I brought Israel up from the land of Egypt, but I also brought the Philistines from Caphtor and the Arameans from Kir.'
EXEC add_BibleVerse @BibleId, 130009008, N'Look, the sovereign Lord is watching the sinful nation, and I will destroy it from the face of the earth. But I will not completely destroy the family of Jacob,” says the Lord.'
EXEC add_BibleVerse @BibleId, 130009009, N'“For look, I am giving a command and I will shake the family of Israel together with all the nations. It will resemble a sieve being shaken, when not even a pebble falls to the ground.'
EXEC add_BibleVerse @BibleId, 130009010, N'All the sinners among my people will die by the sword – the ones who say, ‘Disaster will not come near, it will not confront us.’'
EXEC add_BibleVerse @BibleId, 130009011, N'“In that day I will rebuild the collapsing hut of David. I will seal its gaps, repair its ruins, and restore it to what it was like in days gone by.'
EXEC add_BibleVerse @BibleId, 130009012, N'As a result they will conquer those left in Edom and all the nations subject to my rule.” The Lord, who is about to do this, is speaking!'
EXEC add_BibleVerse @BibleId, 130009013, N'“Be sure of this, the time is coming,” says the Lord, “when the plowman will catch up to the reaper and the one who stomps the grapes will overtake the planter. Juice will run down the slopes, it will flow down all the hillsides.'
EXEC add_BibleVerse @BibleId, 130009014, N'I will bring back my people, Israel; they will rebuild the cities lying in rubble and settle down. They will plant vineyards and drink the wine they produce; they will grow orchards and eat the fruit they produce.'
EXEC add_BibleVerse @BibleId, 130009015, N'I will plant them on their land and they will never again be uprooted from the land I have given them,” says the Lord your God.'
EXEC add_BibleVerse @BibleId, 131001001, N'The vision that Obadiah saw. The Lord God says this concerning Edom: We have heard a report from the Lord. An envoy was sent among the nations, saying, “Arise! Let us make war against Edom!”'
EXEC add_BibleVerse @BibleId, 131001002, N'The Lord says, “Look! I will make you a weak nation; you will be greatly despised!'
EXEC add_BibleVerse @BibleId, 131001003, N'Your presumptuous heart has deceived you – you who reside in the safety of the rocky cliffs, whose home is high in the mountains. You think to yourself, ‘No one can bring me down to the ground!’'
EXEC add_BibleVerse @BibleId, 131001004, N'Even if you were to soar high like an eagle, even if you were to make your nest among the stars, I can bring you down even from there!” says the Lord.'
EXEC add_BibleVerse @BibleId, 131001005, N'“If thieves came to rob you during the night, they would steal only as much as they wanted! If grape pickers came to harvest your vineyards, they would leave some behind for the poor! But you will be totally destroyed!'
EXEC add_BibleVerse @BibleId, 131001006, N'How the people of Esau will be thoroughly plundered! Their hidden valuables will be ransacked!'
EXEC add_BibleVerse @BibleId, 131001007, N'All your allies will force you from your homeland! Your treaty partners will deceive you and overpower you. Your trusted friends will set an ambush for you that will take you by surprise!'
EXEC add_BibleVerse @BibleId, 131001008, N'At that time,” the Lord says, “I will destroy the wise sages of Edom! the advisers from Esau’s mountain!'
EXEC add_BibleVerse @BibleId, 131001009, N'Your warriors will be shattered, O Teman, so that everyone will be destroyed from Esau’s mountain!'
EXEC add_BibleVerse @BibleId, 131001010, N'“Because you violently slaughtered your relatives, the people of Jacob, shame will cover you, and you will be destroyed forever.'
EXEC add_BibleVerse @BibleId, 131001011, N'You stood aloof while strangers took his army captive, and foreigners advanced to his gates. When they cast lots over Jerusalem, you behaved as though you were in league with them.'
EXEC add_BibleVerse @BibleId, 131001012, N'You should not have gloated when your relatives suffered calamity. You should not have rejoiced over the people of Judah when they were destroyed. You should not have boasted when they suffered adversity.'
EXEC add_BibleVerse @BibleId, 131001013, N'You should not have entered the city of my people when they experienced distress. You should not have joined in gloating over their misfortune when they suffered distress. You should not have looted their wealth when they endured distress.'
EXEC add_BibleVerse @BibleId, 131001014, N'You should not have stood at the fork in the road to slaughter those trying to escape. You should not have captured their refugees when they suffered adversity.'
EXEC add_BibleVerse @BibleId, 131001015, N'“For the day of the Lord is approaching for all the nations! Just as you have done, so it will be done to you. You will get exactly what your deeds deserve.'
EXEC add_BibleVerse @BibleId, 131001016, N'For just as you have drunk on my holy mountain, so all the nations will drink continually. They will drink, and they will gulp down; they will be as though they had never been.'
EXEC add_BibleVerse @BibleId, 131001017, N'But on Mount Zion there will be a remnant of those who escape, and it will be a holy place once again. The descendants of Jacob will conquer those who had conquered them.'
EXEC add_BibleVerse @BibleId, 131001018, N'The descendants of Jacob will be a fire, and the descendants of Joseph a flame. The descendants of Esau will be like stubble. They will burn them up and devour them. There will not be a single survivor of the descendants of Esau!” Indeed, the Lord has spoken it.'
EXEC add_BibleVerse @BibleId, 131001019, N'The people of the Negev will take possession of Esau’s mountain, and the people of the Shephelah will take possession of the land of the Philistines. They will also take possession of the territory of Ephraim and the territory of Samaria, and the people of Benjamin will take possession of Gilead.'
EXEC add_BibleVerse @BibleId, 131001020, N'The exiles of this fortress of the people of Israel will take possession of what belongs to the people of Canaan, as far as Zarephath, and the exiles of Jerusalem who are in Sepharad will take possession of the towns of the Negev.'
EXEC add_BibleVerse @BibleId, 131001021, N'Those who have been delivered will go up on Mount Zion in order to rule over Esau’s mountain. Then the Lord will reign as King!'
EXEC add_BibleVerse @BibleId, 132001001, N'The Lord said to Jonah son of Amittai,'
EXEC add_BibleVerse @BibleId, 132001002, N'“Go immediately to Nineveh, that large capital city, and announce judgment against its people because their wickedness has come to my attention.”'
EXEC add_BibleVerse @BibleId, 132001003, N'Instead, Jonah immediately headed off to Tarshish to escape from the commission of the Lord. He traveled to Joppa and found a merchant ship heading to Tarshish. So he paid the fare and went aboard it to go with them to Tarshish far away from the Lord.'
EXEC add_BibleVerse @BibleId, 132001004, N'But the Lord hurled a powerful wind on the sea. Such a violent tempest arose on the sea that the ship threatened to break up!'
EXEC add_BibleVerse @BibleId, 132001005, N'The sailors were so afraid that each cried out to his own god and they flung the ship’s cargo overboard to make the ship lighter. Jonah, meanwhile, had gone down into the hold below deck, had lain down, and was sound asleep.'
EXEC add_BibleVerse @BibleId, 132001006, N'The ship’s captain approached him and said, “What are you doing asleep? Get up! Cry out to your god! Perhaps your god might take notice of us so that we might not die!”'
EXEC add_BibleVerse @BibleId, 132001007, N'The sailors said to one another, “Come on, let’s cast lots to find out whose fault it is that this disaster has overtaken us. ” So they cast lots, and Jonah was singled out.'
EXEC add_BibleVerse @BibleId, 132001008, N'They said to him, “Tell us, whose fault is it that this disaster has overtaken us? What’s your occupation? Where do you come from? What’s your country? And who are your people?”'
EXEC add_BibleVerse @BibleId, 132001009, N'He said to them, “I am a Hebrew! And I worship the Lord, the God of heaven, who made the sea and the dry land.”'
EXEC add_BibleVerse @BibleId, 132001010, N'Hearing this, the men became even more afraid and said to him, “What have you done?” (The men said this because they knew that he was trying to escape from the Lord, because he had previously told them. )'
EXEC add_BibleVerse @BibleId, 132001011, N'Because the storm was growing worse and worse, they said to him, “What should we do to you to make the sea calm down for us?”'
EXEC add_BibleVerse @BibleId, 132001012, N'He said to them, “Pick me up and throw me into the sea to make the sea quiet down, because I know it’s my fault you are in this severe storm.”'
EXEC add_BibleVerse @BibleId, 132001013, N'Instead, they tried to row back to land, but they were not able to do so because the storm kept growing worse and worse.'
EXEC add_BibleVerse @BibleId, 132001014, N'So they cried out to the Lord, “Oh, please, Lord, don’t let us die on account of this man! Don’t hold us guilty of shedding innocent blood. After all, you, Lord, have done just as you pleased.”'
EXEC add_BibleVerse @BibleId, 132001015, N'So they picked Jonah up and threw him into the sea, and the sea stopped raging.'
EXEC add_BibleVerse @BibleId, 132001016, N'The men feared the Lord greatly, and earnestly vowed to offer lavish sacrifices to the Lord.'
EXEC add_BibleVerse @BibleId, 132001017, N'The Lord sent a huge fish to swallow Jonah, and Jonah was in the stomach of the fish three days and three nights.'
EXEC add_BibleVerse @BibleId, 132002001, N'Jonah prayed to the Lord his God from the stomach of the fish'
EXEC add_BibleVerse @BibleId, 132002002, N'and said, “I called out to the Lord from my distress, and he answered me; from the belly of Sheol I cried out for help, and you heard my prayer.'
EXEC add_BibleVerse @BibleId, 132002003, N'You threw me into the deep waters, into the middle of the sea; the ocean current engulfed me; all the mighty waves you sent swept over me.'
EXEC add_BibleVerse @BibleId, 132002004, N'I thought I had been banished from your sight, that I would never again see your holy temple!'
EXEC add_BibleVerse @BibleId, 132002005, N'Water engulfed me up to my neck; the deep ocean surrounded me; seaweed was wrapped around my head.'
EXEC add_BibleVerse @BibleId, 132002006, N'I went down to the very bottoms of the mountains; the gates of the netherworld barred me in forever; but you brought me up from the Pit, O Lord, my God.'
EXEC add_BibleVerse @BibleId, 132002007, N'When my life was ebbing away, I called out to the Lord, and my prayer came to your holy temple.'
EXEC add_BibleVerse @BibleId, 132002008, N'Those who worship worthless idols forfeit the mercy that could be theirs.'
EXEC add_BibleVerse @BibleId, 132002009, N'But as for me, I promise to offer a sacrifice to you with a public declaration of praise; I will surely do what I have promised. Salvation belongs to the Lord!”'
EXEC add_BibleVerse @BibleId, 132002010, N'Then the Lord commanded the fish and it disgorged Jonah on dry land.'
EXEC add_BibleVerse @BibleId, 132003001, N'The Lord said to Jonah a second time,'
EXEC add_BibleVerse @BibleId, 132003002, N'“Go immediately to Nineveh, that large city, and proclaim to it the message that I tell you.”'
EXEC add_BibleVerse @BibleId, 132003003, N'So Jonah went immediately to Nineveh, as the Lord had said. (Now Nineveh was an enormous city – it required three days to walk through it!)'
EXEC add_BibleVerse @BibleId, 132003004, N'When Jonah began to enter the city one day’s walk, he announced, “At the end of forty days, Nineveh will be overthrown!”'
EXEC add_BibleVerse @BibleId, 132003005, N'The people of Nineveh believed in God, and they declared a fast and put on sackcloth, from the greatest to the least of them.'
EXEC add_BibleVerse @BibleId, 132003006, N'When the news reached the king of Nineveh, he got up from his throne, took off his royal robe, put on sackcloth, and sat on ashes.'
EXEC add_BibleVerse @BibleId, 132003007, N'He issued a proclamation and said, “In Nineveh, by the decree of the king and his nobles: No human or animal, cattle or sheep, is to taste anything; they must not eat and they must not drink water.'
EXEC add_BibleVerse @BibleId, 132003008, N'Every person and animal must put on sackcloth and must cry earnestly to God, and everyone must turn from their evil way of living and from the violence that they do.'
EXEC add_BibleVerse @BibleId, 132003009, N'Who knows? Perhaps God might be willing to change his mind and relent and turn from his fierce anger so that we might not die.”'
EXEC add_BibleVerse @BibleId, 132003010, N'When God saw their actions – they turned from their evil way of living! – God relented concerning the judgment he had threatened them with and he did not destroy them.'
EXEC add_BibleVerse @BibleId, 132004001, N'This displeased Jonah terribly and he became very angry.'
EXEC add_BibleVerse @BibleId, 132004002, N'He prayed to the Lord and said, “Oh, Lord, this is just what I thought would happen when I was in my own country. This is what I tried to prevent by attempting to escape to Tarshish! – because I knew that you are gracious and compassionate, slow to anger and abounding in mercy, and one who relents concerning threatened judgment.'
EXEC add_BibleVerse @BibleId, 132004003, N'So now, Lord, kill me instead, because I would rather die than live!”'
EXEC add_BibleVerse @BibleId, 132004004, N'The Lord said, “Are you really so very angry?”'
EXEC add_BibleVerse @BibleId, 132004005, N'Jonah left the city and sat down east of it. He made a shelter for himself there and sat down under it in the shade to see what would happen to the city.'
EXEC add_BibleVerse @BibleId, 132004006, N'The Lord God appointed a little plant and caused it to grow up over Jonah to be a shade over his head to rescue him from his misery. Now Jonah was very delighted about the little plant.'
EXEC add_BibleVerse @BibleId, 132004007, N'So God sent a worm at dawn the next day, and it attacked the little plant so that it dried up.'
EXEC add_BibleVerse @BibleId, 132004008, N'When the sun began to shine, God sent a hot east wind. So the sun beat down on Jonah’s head, and he grew faint. So he despaired of life, and said, “I would rather die than live!”'
EXEC add_BibleVerse @BibleId, 132004009, N'God said to Jonah, “Are you really so very angry about the little plant?” And he said, “I am as angry as I could possibly be!”'
EXEC add_BibleVerse @BibleId, 132004010, N'The Lord said, “You were upset about this little plant, something for which you have not worked nor did you do anything to make it grow. It grew up overnight and died the next day.'
EXEC add_BibleVerse @BibleId, 132004011, N'Should I not be even more concerned about Nineveh, this enormous city? There are more than one hundred twenty thousand people in it who do not know right from wrong, as well as many animals!”'
EXEC add_BibleVerse @BibleId, 133001001, N'This is the prophetic message that the Lord gave to Micah of Moresheth. He delivered this message during the reigns of Jotham, Ahaz, and Hezekiah, kings of Judah. The prophecies pertain to Samaria'
EXEC add_BibleVerse @BibleId, 133001002, N'Listen, all you nations! Pay attention, all inhabitants of earth! The sovereign Lord will testify against you; the Lord will accuse you from his majestic palace.'
EXEC add_BibleVerse @BibleId, 133001003, N'Look, the Lord is coming out of his dwelling place! He will descend and march on the earth’s mountaintops!'
EXEC add_BibleVerse @BibleId, 133001004, N'The mountains will disintegrate beneath him, and the valleys will be split in two. The mountains will melt like wax in a fire, the rocks will slide down like water cascading down a steep slope.'
EXEC add_BibleVerse @BibleId, 133001005, N'All this is because of Jacob’s rebellion and the sins of the nation of Israel. How has Jacob rebelled, you ask? Samaria epitomizes their rebellion! Where are Judah’s pagan worship centers, you ask? They are right in Jerusalem!'
EXEC add_BibleVerse @BibleId, 133001006, N'“I will turn Samaria into a heap of ruins in an open field – vineyards will be planted there! I will tumble the rubble of her stone walls down into the valley, and tear down her fortifications to their foundations.'
EXEC add_BibleVerse @BibleId, 133001007, N'All her carved idols will be smashed to pieces; all her metal cult statues will be destroyed by fire. I will make a waste heap of all her images. Since she gathered the metal as a prostitute collects her wages, the idols will become a prostitute’s wages again.”'
EXEC add_BibleVerse @BibleId, 133001008, N'For this reason I will mourn and wail; I will walk around barefoot and without my outer garments. I will howl like a wild dog, and screech like an owl.'
EXEC add_BibleVerse @BibleId, 133001009, N'For Samaria’s disease is incurable. It has infected Judah; it has spread to the leadership of my people and has even contaminated Jerusalem!'
EXEC add_BibleVerse @BibleId, 133001010, N'Don’t spread the news in Gath! Don’t shed even a single tear! In Beth Leaphrah sit in the dust!'
EXEC add_BibleVerse @BibleId, 133001011, N'Residents of Shaphir, pass by in nakedness and humiliation! The residents of Zaanan can’t leave their city. Beth Ezel mourns, “He takes from you what he desires.”'
EXEC add_BibleVerse @BibleId, 133001012, N'Indeed, the residents of Maroth hope for something good to happen, though the Lord has sent disaster against the city of Jerusalem.'
EXEC add_BibleVerse @BibleId, 133001013, N'Residents of Lachish, hitch the horses to the chariots! You influenced Daughter Zion to sin, for Israel’s rebellious deeds can be traced back to you!'
EXEC add_BibleVerse @BibleId, 133001014, N'Therefore you will have to say farewell to Moresheth Gath. The residents of Achzib will be as disappointing as a dried up well to the kings of Israel.'
EXEC add_BibleVerse @BibleId, 133001015, N'Residents of Mareshah, a conqueror will attack you, the leaders of Israel shall flee to Adullam.'
EXEC add_BibleVerse @BibleId, 133001016, N'Shave your heads bald as you mourn for the children you love; shave your foreheads as bald as an eagle, for they are taken from you into exile.'
EXEC add_BibleVerse @BibleId, 133002001, N'Those who devise sinful plans are as good as dead, those who dream about doing evil as they lie in bed. As soon as morning dawns they carry out their plans, because they have the power to do so.'
EXEC add_BibleVerse @BibleId, 133002002, N'They confiscate the fields they desire, and seize the houses they want. They defraud people of their homes, and deprive people of the land they have inherited.'
EXEC add_BibleVerse @BibleId, 133002003, N'Therefore the Lord says this: “Look, I am devising disaster for this nation! It will be like a yoke from which you cannot free your neck. You will no longer walk proudly, for it will be a time of catastrophe.'
EXEC add_BibleVerse @BibleId, 133002004, N'In that day people will sing this taunt song to you – they will mock you with this lament: ‘We are completely destroyed; they sell off the property of my people. How they remove it from me! They assign our fields to the conqueror.’'
EXEC add_BibleVerse @BibleId, 133002005, N'Therefore no one will assign you land in the Lord’s community.'
EXEC add_BibleVerse @BibleId, 133002006, N'‘Don’t preach with such impassioned rhetoric,’ they say excitedly. ‘These prophets should not preach of such things; we will not be overtaken by humiliation.’'
EXEC add_BibleVerse @BibleId, 133002007, N'Does the family of Jacob say, ‘The Lord’s patience can’t be exhausted – he would never do such things’? To be sure, my commands bring a reward for those who obey them,'
EXEC add_BibleVerse @BibleId, 133002008, N'but you rise up as an enemy against my people. You steal a robe from a friend, from those who pass by peacefully as if returning from a war.'
EXEC add_BibleVerse @BibleId, 133002009, N'You wrongly evict widows among my people from their cherished homes. You defraud their children of their prized inheritance.'
EXEC add_BibleVerse @BibleId, 133002010, N'But you are the ones who will be forced to leave! For this land is not secure! Sin will thoroughly destroy it!'
EXEC add_BibleVerse @BibleId, 133002011, N'If a lying windbag should come and say, ‘I’ll promise you blessings of wine and beer,’ he would be just the right preacher for these people!'
EXEC add_BibleVerse @BibleId, 133002012, N'I will certainly gather all of you, O Jacob, I will certainly assemble those Israelites who remain. I will bring them together like sheep in a fold, like a flock in the middle of a pasture; they will be so numerous that they will make a lot of noise.'
EXEC add_BibleVerse @BibleId, 133002013, N'The one who can break through barriers will lead them out they will break out, pass through the gate, and leave. Their king will advance before them, The Lord himself will lead them.'
EXEC add_BibleVerse @BibleId, 133003001, N'I said, “Listen, you leaders of Jacob, you rulers of the nation of Israel! You ought to know what is just,'
EXEC add_BibleVerse @BibleId, 133003002, N'yet you hate what is good, and love what is evil. You flay my people’s skin and rip the flesh from their bones.'
EXEC add_BibleVerse @BibleId, 133003003, N'You devour my people’s flesh, strip off their skin, and crush their bones. You chop them up like flesh in a pot – like meat in a kettle.'
EXEC add_BibleVerse @BibleId, 133003004, N'Someday these sinners will cry to the Lord for help, but he will not answer them. He will hide his face from them at that time, because they have done such wicked deeds.”'
EXEC add_BibleVerse @BibleId, 133003005, N'This is what the Lord says: “The prophets who mislead my people are as good as dead. If someone gives them enough to eat, they offer an oracle of peace. But if someone does not give them food, they are ready to declare war on him.'
EXEC add_BibleVerse @BibleId, 133003006, N'Therefore night will fall, and you will receive no visions; it will grow dark, and you will no longer be able to read the omens. The sun will set on these prophets, and the daylight will turn to darkness over their heads.'
EXEC add_BibleVerse @BibleId, 133003007, N'The prophets will be ashamed; the omen readers will be humiliated. All of them will cover their mouths, for they will receive no divine oracles.”'
EXEC add_BibleVerse @BibleId, 133003008, N'But I am full of the courage that the Lord’s Spirit gives, and have a strong commitment to justice. This enables me to confront Jacob with its rebellion, and Israel with its sin.'
EXEC add_BibleVerse @BibleId, 133003009, N'Listen to this, you leaders of the family of Jacob, you rulers of the nation of Israel! You hate justice and pervert all that is right.'
EXEC add_BibleVerse @BibleId, 133003010, N'You build Zion through bloody crimes, Jerusalem through unjust violence.'
EXEC add_BibleVerse @BibleId, 133003011, N'Her leaders take bribes when they decide legal cases, her priests proclaim rulings for profit, and her prophets read omens for pay. Yet they claim to trust the Lord and say, “The Lord is among us. Disaster will not overtake us!”'
EXEC add_BibleVerse @BibleId, 133003012, N'Therefore, because of you, Zion will be plowed up like a field, Jerusalem will become a heap of ruins, and the Temple Mount will become a hill overgrown with brush!'
EXEC add_BibleVerse @BibleId, 133004001, N'In the future the Lord’s Temple Mount will be the most important mountain of all; it will be more prominent than other hills. People will stream to it.'
EXEC add_BibleVerse @BibleId, 133004002, N'Many nations will come, saying, “Come on! Let’s go up to the Lord’s mountain, to the temple of Jacob’s God, so he can teach us his commands and we can live by his laws.” For Zion will be the source of instruction; the Lord’s teachings will proceed from Jerusalem.'
EXEC add_BibleVerse @BibleId, 133004003, N'He will arbitrate between many peoples and settle disputes between many distant nations. They will beat their swords into plowshares, and their spears into pruning hooks. Nations will not use weapons against other nations, and they will no longer train for war.'
EXEC add_BibleVerse @BibleId, 133004004, N'Each will sit under his own grapevine or under his own fig tree without any fear. The Lord who commands armies has decreed it.'
EXEC add_BibleVerse @BibleId, 133004005, N'Though all the nations follow their respective gods, we will follow the Lord our God forever.'
EXEC add_BibleVerse @BibleId, 133004006, N'“In that day,” says the Lord, “I will gather the lame, and assemble the outcasts whom I injured.'
EXEC add_BibleVerse @BibleId, 133004007, N'I will transform the lame into the nucleus of a new nation, and those far off into a mighty nation. The Lord will reign over them on Mount Zion, from that day forward and forevermore.”'
EXEC add_BibleVerse @BibleId, 133004008, N'As for you, watchtower for the flock, fortress of Daughter Zion – your former dominion will be restored, the sovereignty that belongs to Daughter Jerusalem.'
EXEC add_BibleVerse @BibleId, 133004009, N'Jerusalem, why are you now shouting so loudly? Has your king disappeared? Has your wise leader been destroyed? Is this why pain grips you as if you were a woman in labor?'
EXEC add_BibleVerse @BibleId, 133004010, N'Twist and strain, Daughter Zion, as if you were in labor! For you will leave the city and live in the open field. You will go to Babylon, but there you will be rescued. There the Lord will deliver you from the power of your enemies.'
EXEC add_BibleVerse @BibleId, 133004011, N'Many nations have now assembled against you. They say, “Jerusalem must be desecrated, so we can gloat over Zion!”'
EXEC add_BibleVerse @BibleId, 133004012, N'But they do not know what the Lord is planning; they do not understand his strategy. He has gathered them like stalks of grain to be threshed at the threshing floor.'
EXEC add_BibleVerse @BibleId, 133004013, N'“Get up and thresh, Daughter Zion! For I will give you iron horns; I will give you bronze hooves, and you will crush many nations.” You will devote to the Lord the spoils you take from them, and dedicate their wealth to the sovereign Ruler of the whole earth.'
EXEC add_BibleVerse @BibleId, 133005001, N'But now slash yourself, daughter surrounded by soldiers! We are besieged! With a scepter they strike Israel’s ruler on the side of his face.'
EXEC add_BibleVerse @BibleId, 133005002, N'As for you, Bethlehem Ephrathah, seemingly insignificant among the clans of Judah – from you a king will emerge who will rule over Israel on my behalf, one whose origins are in the distant past.'
EXEC add_BibleVerse @BibleId, 133005003, N'So the Lord will hand the people of Israel over to their enemies until the time when the woman in labor gives birth. Then the rest of the king’s countrymen will return to be reunited with the people of Israel.'
EXEC add_BibleVerse @BibleId, 133005004, N'He will assume his post and shepherd the people by the Lord’s strength, by the sovereign authority of the Lord his God. They will live securely, for at that time he will be honored even in the distant regions of the earth.'
EXEC add_BibleVerse @BibleId, 133005005, N'He will give us peace. Should the Assyrians try to invade our land and attempt to set foot in our fortresses, we will send against them seven shepherd-rulers, make that eight commanders.'
EXEC add_BibleVerse @BibleId, 133005006, N'They will rule the land of Assyria with the sword, the land of Nimrod with a drawn sword. Our king will rescue us from the Assyrians should they attempt to invade our land and try to set foot in our territory.'
EXEC add_BibleVerse @BibleId, 133005007, N'Those survivors from Jacob will live in the midst of many nations. They will be like the dew the Lord sends, like the rain on the grass, that does not hope for men to come or wait around for humans to arrive.'
EXEC add_BibleVerse @BibleId, 133005008, N'Those survivors from Jacob will live among the nations, in the midst of many peoples. They will be like a lion among the animals of the forest, like a young lion among the flocks of sheep, which attacks when it passes through; it rips its prey and there is no one to stop it.'
EXEC add_BibleVerse @BibleId, 133005009, N'Lift your hand triumphantly against your adversaries; may all your enemies be destroyed!'
EXEC add_BibleVerse @BibleId, 133005010, N'“In that day,” says the Lord, “I will destroy your horses from your midst, and smash your chariots.'
EXEC add_BibleVerse @BibleId, 133005011, N'I will destroy the cities of your land, and tear down all your fortresses.'
EXEC add_BibleVerse @BibleId, 133005012, N'I will remove the sorcery that you practice, and you will no longer have omen readers living among you.'
EXEC add_BibleVerse @BibleId, 133005013, N'I will remove your idols and sacred pillars from your midst; you will no longer worship what your own hands made.'
EXEC add_BibleVerse @BibleId, 133005014, N'I will uproot your images of Asherah from your midst, and destroy your idols.'
EXEC add_BibleVerse @BibleId, 133005015, N'I will angrily seek vengeance on the nations that do not obey me.”'
EXEC add_BibleVerse @BibleId, 133006001, N'Listen to what the Lord says: “Get up! Defend yourself before the mountains! Present your case before the hills!”'
EXEC add_BibleVerse @BibleId, 133006002, N'Hear the Lord’s accusation, you mountains, you enduring foundations of the earth! For the Lord has a case against his people; he has a dispute with Israel!'
EXEC add_BibleVerse @BibleId, 133006003, N'“My people, how have I wronged you? How have I wearied you? Answer me!'
EXEC add_BibleVerse @BibleId, 133006004, N'In fact, I brought you up from the land of Egypt, I delivered you from that place of slavery. I sent Moses, Aaron, and Miriam to lead you.'
EXEC add_BibleVerse @BibleId, 133006005, N'My people, recall how King Balak of Moab planned to harm you, how Balaam son of Beor responded to him. Recall how you journeyed from Shittim to Gilgal, so you might acknowledge that the Lord has treated you fairly.”'
EXEC add_BibleVerse @BibleId, 133006006, N'With what should I enter the Lord’s presence? With what should I bow before the sovereign God? Should I enter his presence with burnt offerings, with year-old calves?'
EXEC add_BibleVerse @BibleId, 133006007, N'Will the Lord accept a thousand rams, or ten thousand streams of olive oil? Should I give him my firstborn child as payment for my rebellion, my offspring – my own flesh and blood – for my sin?'
EXEC add_BibleVerse @BibleId, 133006008, N'He has told you, O man, what is good, and what the Lord really wants from you: He wants you to promote justice, to be faithful, and to live obediently before your God.'
EXEC add_BibleVerse @BibleId, 133006009, N'Listen! The Lord is calling to the city! It is wise to respect your authority, O Lord! Listen, O nation, and those assembled in the city!'
EXEC add_BibleVerse @BibleId, 133006010, N'“I will not overlook, O sinful house, the dishonest gain you have hoarded away, or the smaller-than-standard measure I hate so much.'
EXEC add_BibleVerse @BibleId, 133006011, N'I do not condone the use of rigged scales, or a bag of deceptive weights.'
EXEC add_BibleVerse @BibleId, 133006012, N'The city’s rich men think nothing of resorting to violence; her inhabitants lie, their tongues speak deceptive words.'
EXEC add_BibleVerse @BibleId, 133006013, N'I will strike you brutally and destroy you because of your sin.'
EXEC add_BibleVerse @BibleId, 133006014, N'You will eat, but not be satisfied. Even if you have the strength to overtake some prey, you will not be able to carry it away; if you do happen to carry away something, I will deliver it over to the sword.'
EXEC add_BibleVerse @BibleId, 133006015, N'You will plant crops, but will not harvest them; you will squeeze oil from the olives, but you will have no oil to rub on your bodies; you will squeeze juice from the grapes, but you will have no wine to drink.'
EXEC add_BibleVerse @BibleId, 133006016, N'You implement the regulations of Omri, and all the practices of Ahab’s dynasty; you follow their policies. Therefore I will make you an appalling sight, the city’s inhabitants will be taunted derisively, and nations will mock all of you.”'
EXEC add_BibleVerse @BibleId, 133007001, N'I am depressed! Indeed, it is as if the summer fruit has been gathered, and the grapes have been harvested. There is no grape cluster to eat, no fresh figs that I crave so much.'
EXEC add_BibleVerse @BibleId, 133007002, N'Faithful men have disappeared from the land; there are no godly men left. They all wait in ambush so they can shed blood; they hunt their own brother with a net.'
EXEC add_BibleVerse @BibleId, 133007003, N'They are determined to be experts at doing evil; government officials and judges take bribes, prominent men make demands, and they all do what is necessary to satisfy them.'
EXEC add_BibleVerse @BibleId, 133007004, N'The best of them is like a thorn; the most godly among them are more dangerous than a row of thorn bushes. The day you try to avoid by posting watchmen – your appointed time of punishment – is on the way, and then you will experience confusion.'
EXEC add_BibleVerse @BibleId, 133007005, N'Do not rely on a friend; do not trust a companion! Don’t even share secrets with the one who lies in your arms!'
EXEC add_BibleVerse @BibleId, 133007006, N'For a son thinks his father is a fool, a daughter challenges her mother, and a daughter-in-law her mother-in-law; a man’s enemies are his own servants.'
EXEC add_BibleVerse @BibleId, 133007007, N'But I will keep watching for the Lord; I will wait for the God who delivers me. My God will hear my lament.'
EXEC add_BibleVerse @BibleId, 133007008, N'My enemies, do not gloat over me! Though I have fallen, I will get up. Though I sit in darkness, the Lord will be my light.'
EXEC add_BibleVerse @BibleId, 133007009, N'I must endure the Lord’s anger, for I have sinned against him. But then he will defend my cause, and accomplish justice on my behalf. He will lead me out into the light; I will experience firsthand his deliverance.'
EXEC add_BibleVerse @BibleId, 133007010, N'When my enemies see this, they will be covered with shame. They say to me, “Where is the Lord your God?” I will gloat over them. Then they will be trampled down like mud in the streets.'
EXEC add_BibleVerse @BibleId, 133007011, N'It will be a day for rebuilding your walls; in that day your boundary will be extended.'
EXEC add_BibleVerse @BibleId, 133007012, N'In that day people will come to you from Assyria as far as Egypt, from Egypt as far as the Euphrates River, from the seacoasts and the mountains.'
EXEC add_BibleVerse @BibleId, 133007013, N'The earth will become desolate because of what its inhabitants have done.'
EXEC add_BibleVerse @BibleId, 133007014, N'Shepherd your people with your shepherd’s rod, the flock that belongs to you, the one that lives alone in a thicket, in the midst of a pastureland. Allow them to graze in Bashan and Gilead, as they did in the old days.'
EXEC add_BibleVerse @BibleId, 133007015, N'“As in the days when you departed from the land of Egypt, I will show you miraculous deeds.”'
EXEC add_BibleVerse @BibleId, 133007016, N'Nations will see this and be disappointed by all their strength, they will put their hands over their mouths, and act as if they were deaf.'
EXEC add_BibleVerse @BibleId, 133007017, N'They will lick the dust like a snake, like serpents crawling on the ground. They will come trembling from their strongholds to the Lord our God; they will be terrified of you.'
EXEC add_BibleVerse @BibleId, 133007018, N'There is no other God like you! You forgive sin and pardon the rebellion of those who remain among your people. You do not remain angry forever, but delight in showing loyal love.'
EXEC add_BibleVerse @BibleId, 133007019, N'You will once again have mercy on us; you will conquer our evil deeds; you will hurl our sins into the depths of the sea.'
EXEC add_BibleVerse @BibleId, 133007020, N'You will be loyal to Jacob and extend your loyal love to Abraham, which you promised on oath to our ancestors in ancient times.'
EXEC add_BibleVerse @BibleId, 134001001, N'The oracle against Nineveh; the book of the vision of Nahum the Elkoshite:'
EXEC add_BibleVerse @BibleId, 134001002, N'The Lord is a zealous and avenging God; the Lord is avenging and very angry. The Lord takes vengeance against his foes; he sustains his rage against his enemies.'
EXEC add_BibleVerse @BibleId, 134001003, N'The Lord is slow to anger but great in power; the Lord will certainly not allow the wicked to go unpunished. He marches out in the whirlwind and the raging storm; dark storm clouds billow like dust under his feet.'
EXEC add_BibleVerse @BibleId, 134001004, N'He shouts a battle cry against the sea and makes it dry up; he makes all the rivers run dry. Bashan and Carmel wither; the blossom of Lebanon withers.'
EXEC add_BibleVerse @BibleId, 134001005, N'The mountains tremble before him, the hills convulse; the earth is laid waste before him, the world and all its inhabitants are laid waste.'
EXEC add_BibleVerse @BibleId, 134001006, N'No one can withstand his indignation! No one can resist his fierce anger! His wrath is poured out like volcanic fire, boulders are broken up as he approaches.'
EXEC add_BibleVerse @BibleId, 134001007, N'The Lord is good – indeed, he is a fortress in time of distress, and he protects those who seek refuge in him.'
EXEC add_BibleVerse @BibleId, 134001008, N'But with an overwhelming flood he will make a complete end of Nineveh; he will drive his enemies into darkness.'
EXEC add_BibleVerse @BibleId, 134001009, N'Whatever you plot against the Lord, he will completely destroy! Distress will not arise a second time.'
EXEC add_BibleVerse @BibleId, 134001010, N'Surely they will be totally consumed like entangled thorn bushes, like the drink of drunkards, like very dry stubble.'
EXEC add_BibleVerse @BibleId, 134001011, N'From you, O Nineveh, one has marched forth who plots evil against the Lord, a wicked military strategist.'
EXEC add_BibleVerse @BibleId, 134001012, N'This is what the Lord says: “Even though they are powerful – and what is more, even though their army is numerous – nevertheless, they will be destroyed and trickle away! Although I afflicted you, I will afflict you no more.'
EXEC add_BibleVerse @BibleId, 134001013, N'And now, I will break Assyria’s yoke bar from your neck; I will tear apart the shackles that are on you.”'
EXEC add_BibleVerse @BibleId, 134001014, N'The Lord has issued a decree against you: “Your dynasty will come to an end. I will destroy the idols and images in the temples of your gods. I will desecrate your grave – because you are accursed!”'
EXEC add_BibleVerse @BibleId, 134001015, N'Look! A herald is running on the mountains! A messenger is proclaiming deliverance: “Celebrate your sacred festivals, O Judah! Fulfill your sacred vows to praise God! For never again will the wicked Assyrians invade you, they have been completely destroyed.”'
EXEC add_BibleVerse @BibleId, 134002001, N'The watchmen of Nineveh shout: “An enemy who will scatter you is marching out to attack you!” “Guard the rampart! Watch the road! Prepare yourselves for battle! Muster your mighty strength!”'
EXEC add_BibleVerse @BibleId, 134002002, N'For the Lord will restore the majesty of Jacob, as well as the majesty of Israel, though their enemies have plundered them and have destroyed their fields.'
EXEC add_BibleVerse @BibleId, 134002003, N'The shields of his warriors are dyed red; the mighty soldiers are dressed in scarlet garments. The metal fittings of the chariots shine like fire on the day of battle; the soldiers brandish their spears.'
EXEC add_BibleVerse @BibleId, 134002004, N'The chariots race madly through the streets, they rush back and forth in the broad plazas; they look like lightning bolts, they dash here and there like flashes of lightning.'
EXEC add_BibleVerse @BibleId, 134002005, N'The commander orders his officers; they stumble as they advance; they rush to the city wall and they set up the covered siege tower.'
EXEC add_BibleVerse @BibleId, 134002006, N'The sluice gates are opened; the royal palace is deluged and dissolves.'
EXEC add_BibleVerse @BibleId, 134002007, N'Nineveh is taken into exile and is led away; her slave girls moan like doves while they beat their breasts.'
EXEC add_BibleVerse @BibleId, 134002008, N'Nineveh was like a pool of water throughout her days, but now her people are running away; she cries out: “Stop! Stop!” – but no one turns back.'
EXEC add_BibleVerse @BibleId, 134002009, N'Her conquerors cry out: “Plunder the silver! Plunder the gold!” There is no end to the treasure; riches of every kind of precious thing.'
EXEC add_BibleVerse @BibleId, 134002010, N'Destruction, devastation, and desolation! Their hearts faint, their knees tremble, each stomach churns, each face turns pale!'
EXEC add_BibleVerse @BibleId, 134002011, N'Where now is the den of the lions, the feeding place of the young lions, where the lion, lioness, and lion cub once prowled and no one disturbed them?'
EXEC add_BibleVerse @BibleId, 134002012, N'The lion tore apart as much prey as his cubs needed and strangled prey to provide food for his lionesses; he filled his lairs with prey and his dens with torn flesh.'
EXEC add_BibleVerse @BibleId, 134002013, N'“I am against you!” declares the Lord who commands armies: “I will burn your chariots with fire; the sword will devour your young lions; you will no longer prey upon the land; the voices of your messengers will no longer be heard.”'
EXEC add_BibleVerse @BibleId, 134003001, N'Woe to the city guilty of bloodshed! She is full of lies; she is filled with plunder; she has hoarded her spoil!'
EXEC add_BibleVerse @BibleId, 134003002, N'The chariot drivers will crack their whips; the chariot wheels will shake the ground; the chariot horses will gallop; the war chariots will bolt forward!'
EXEC add_BibleVerse @BibleId, 134003003, N'The charioteers will charge ahead; their swords will flash and their spears will glimmer! There will be many people slain; there will be piles of the dead, and countless casualties – so many that people will stumble over the corpses.'
EXEC add_BibleVerse @BibleId, 134003004, N'“Because you have acted like a wanton prostitute – a seductive mistress who practices sorcery, who enslaves nations by her harlotry, and entices peoples by her sorcery –'
EXEC add_BibleVerse @BibleId, 134003005, N'I am against you,” declares the Lord who commands armies. “I will strip off your clothes! I will show your nakedness to the nations and your shame to the kingdoms;'
EXEC add_BibleVerse @BibleId, 134003006, N'I will pelt you with filth; I will treat you with contempt; I will make you a public spectacle.'
EXEC add_BibleVerse @BibleId, 134003007, N'Everyone who sees you will turn away from you in disgust; they will say, ‘Nineveh has been devastated! Who will lament for her?’ There will be no one to comfort you!”'
EXEC add_BibleVerse @BibleId, 134003008, N'You are no more secure than Thebes – she was located on the banks of the Nile; the waters surrounded her, her rampart was the sea, the water was her wall.'
EXEC add_BibleVerse @BibleId, 134003009, N'Cush and Egypt had limitless strength; Put and the Libyans were among her allies.'
EXEC add_BibleVerse @BibleId, 134003010, N'Yet she went into captivity as an exile; even her infants were smashed to pieces at the head of every street. They cast lots for her nobility; all her dignitaries were bound with chains.'
EXEC add_BibleVerse @BibleId, 134003011, N'You too will act like drunkards; you will go into hiding; you too will seek refuge from the enemy.'
EXEC add_BibleVerse @BibleId, 134003012, N'All your fortifications will be like fig trees with first-ripe fruit: If they are shaken, their figs will fall into the mouth of the eater!'
EXEC add_BibleVerse @BibleId, 134003013, N'Your warriors will be like women in your midst; the gates of your land will be wide open to your enemies; fire will consume the bars of your gates.'
EXEC add_BibleVerse @BibleId, 134003014, N'Draw yourselves water for a siege! Strengthen your fortifications! Trample the mud and tread the clay! Make mud bricks to strengthen your walls!'
EXEC add_BibleVerse @BibleId, 134003015, N'There the fire will consume you; the sword will cut you down; it will devour you like the young locust would. Multiply yourself like the young locust; multiply yourself like the flying locust!'
EXEC add_BibleVerse @BibleId, 134003016, N'Increase your merchants more than the stars of heaven! They are like the young locust which sheds its skin and flies away.'
EXEC add_BibleVerse @BibleId, 134003017, N'Your courtiers are like locusts, your officials are like a swarm of locusts! They encamp in the walls on a cold day, yet when the sun rises, they fly away; and no one knows where they are.'
EXEC add_BibleVerse @BibleId, 134003018, N'Your shepherds are sleeping, O king of Assyria! Your officers are slumbering! Your people are scattered like sheep on the mountains and there is no one to regather them!'
EXEC add_BibleVerse @BibleId, 134003019, N'Your destruction is like an incurable wound; your demise is like a fatal injury! All who hear what has happened to you will clap their hands for joy, for no one ever escaped your endless cruelty!'
EXEC add_BibleVerse @BibleId, 135001001, N'The following is the message which God revealed to Habakkuk the prophet:'
EXEC add_BibleVerse @BibleId, 135001002, N'How long, Lord, must I cry for help? But you do not listen! I call out to you, “Violence!” But you do not intervene!'
EXEC add_BibleVerse @BibleId, 135001003, N'Why do you force me to witness injustice? Why do you put up with wrongdoing? Destruction and violence confront me; conflict is present and one must endure strife.'
EXEC add_BibleVerse @BibleId, 135001004, N'For this reason the law lacks power, and justice is never carried out. Indeed, the wicked intimidate the innocent. For this reason justice is perverted.'
EXEC add_BibleVerse @BibleId, 135001005, N'“Look at the nations and pay attention! You will be shocked and amazed! For I will do something in your lifetime that you will not believe even though you are forewarned.'
EXEC add_BibleVerse @BibleId, 135001006, N'Look, I am about to empower the Babylonians, that ruthless and greedy nation. They sweep across the surface of the earth, seizing dwelling places that do not belong to them.'
EXEC add_BibleVerse @BibleId, 135001007, N'They are frightening and terrifying; they decide for themselves what is right.'
EXEC add_BibleVerse @BibleId, 135001008, N'Their horses are faster than leopards and more alert than wolves in the desert. Their horses gallop, their horses come a great distance; like a vulture they swoop down quickly to devour their prey.'
EXEC add_BibleVerse @BibleId, 135001009, N'All of them intend to do violence; every face is determined. They take prisoners as easily as one scoops up sand.'
EXEC add_BibleVerse @BibleId, 135001010, N'They mock kings and laugh at rulers. They laugh at every fortified city; they build siege ramps and capture them.'
EXEC add_BibleVerse @BibleId, 135001011, N'They sweep by like the wind and pass on. But the one who considers himself a god will be held guilty.”'
EXEC add_BibleVerse @BibleId, 135001012, N'Lord, you have been active from ancient times; my sovereign God, you are immortal. Lord, you have made them your instrument of judgment. Protector, you have appointed them as your instrument of punishment.'
EXEC add_BibleVerse @BibleId, 135001013, N'You are too just to tolerate evil; you are unable to condone wrongdoing. So why do you put up with such treacherous people? Why do you say nothing when the wicked devour those more righteous than they are?'
EXEC add_BibleVerse @BibleId, 135001014, N'You made people like fish in the sea, like animals in the sea that have no ruler.'
EXEC add_BibleVerse @BibleId, 135001015, N'The Babylonian tyrant pulls them all up with a fishhook; he hauls them in with his throw net. When he catches them in his dragnet, he is very happy.'
EXEC add_BibleVerse @BibleId, 135001016, N'Because of his success he offers sacrifices to his throw net and burns incense to his dragnet; for because of them he has plenty of food, and more than enough to eat.'
EXEC add_BibleVerse @BibleId, 135001017, N'Will he then continue to fill and empty his throw net? Will he always destroy nations and spare none?'
EXEC add_BibleVerse @BibleId, 135002001, N'I will stand at my watch post; I will remain stationed on the city wall. I will keep watching, so I can see what he says to me and can know how I should answer when he counters my argument.'
EXEC add_BibleVerse @BibleId, 135002002, N'The Lord responded: “Write down this message! Record it legibly on tablets, so the one who announces it may read it easily.'
EXEC add_BibleVerse @BibleId, 135002003, N'For the message is a witness to what is decreed; it gives reliable testimony about how matters will turn out. Even if the message is not fulfilled right away, wait patiently; for it will certainly come to pass – it will not arrive late.'
EXEC add_BibleVerse @BibleId, 135002004, N'Look, the one whose desires are not upright will faint from exhaustion, but the person of integrity will live because of his faithfulness.'
EXEC add_BibleVerse @BibleId, 135002005, N'Indeed, wine will betray the proud, restless man! His appetite is as big as Sheol’s; like death, he is never satisfied. He gathers all the nations; he seizes all peoples.'
EXEC add_BibleVerse @BibleId, 135002006, N'“But all these nations will someday taunt him and ridicule him with proverbial sayings: ‘The one who accumulates what does not belong to him is as good as dead (How long will this go on?) – he who gets rich by extortion!’'
EXEC add_BibleVerse @BibleId, 135002007, N'Your creditors will suddenly attack; those who terrify you will spring into action, and they will rob you.'
EXEC add_BibleVerse @BibleId, 135002008, N'Because you robbed many countries, all who are left among the nations will rob you. You have shed human blood and committed violent acts against lands, cities, and those who live in them.'
EXEC add_BibleVerse @BibleId, 135002009, N'The one who builds his house by unjust gain is as good as dead. He does this so he can build his nest way up high and escape the clutches of disaster.'
EXEC add_BibleVerse @BibleId, 135002010, N'Your schemes will bring shame to your house. Because you destroyed many nations, you will self-destruct.'
EXEC add_BibleVerse @BibleId, 135002011, N'For the stones in the walls will cry out, and the wooden rafters will answer back.'
EXEC add_BibleVerse @BibleId, 135002012, N'The one who builds a city by bloodshed is as good as dead – he who starts a town by unjust deeds.'
EXEC add_BibleVerse @BibleId, 135002013, N'Be sure of this! The Lord who commands armies has decreed: The nations’ efforts will go up in smoke; their exhausting work will be for nothing.'
EXEC add_BibleVerse @BibleId, 135002014, N'For recognition of the Lord’s sovereign majesty will fill the earth just as the waters fill up the sea.'
EXEC add_BibleVerse @BibleId, 135002015, N'“You who force your neighbor to drink wine are as good as dead – you who make others intoxicated by forcing them to drink from the bowl of your furious anger, so you can look at their genitals.'
EXEC add_BibleVerse @BibleId, 135002016, N'But you will become drunk with shame, not majesty. Now it is your turn to drink and expose your uncircumcised foreskin! The cup of wine in the Lord’s right hand is coming to you, and disgrace will replace your majestic glory!'
EXEC add_BibleVerse @BibleId, 135002017, N'For you will pay in full for your violent acts against Lebanon; terrifying judgment will come upon you because of the way you destroyed the wild animals living there. You have shed human blood and committed violent acts against lands, cities, and those who live in them.'
EXEC add_BibleVerse @BibleId, 135002018, N'What good is an idol? Why would a craftsman make it? What good is a metal image that gives misleading oracles? Why would its creator place his trust in it and make such mute, worthless things?'
EXEC add_BibleVerse @BibleId, 135002019, N'The one who says to wood, ‘Wake up!’ is as good as dead – he who says to speechless stone, ‘Awake!’ Can it give reliable guidance? It is overlaid with gold and silver; it has no life’s breath inside it.'
EXEC add_BibleVerse @BibleId, 135002020, N'But the Lord is in his majestic palace. The whole earth is speechless in his presence!”'
EXEC add_BibleVerse @BibleId, 135003001, N'This is a prayer of Habakkuk the prophet:'
EXEC add_BibleVerse @BibleId, 135003002, N'Lord, I have heard the report of what you did; I am awed, Lord, by what you accomplished. In our time repeat those deeds; in our time reveal them again. But when you cause turmoil, remember to show us mercy!'
EXEC add_BibleVerse @BibleId, 135003003, N'God comes from Teman, the sovereign one from Mount Paran. Selah. His splendor covers the skies, his glory fills the earth.'
EXEC add_BibleVerse @BibleId, 135003004, N'He is as bright as lightning; a two-pronged lightning bolt flashes from his hand. This is the outward display of his power.'
EXEC add_BibleVerse @BibleId, 135003005, N'Plague goes before him; pestilence marches right behind him.'
EXEC add_BibleVerse @BibleId, 135003006, N'He takes his battle position and shakes the earth; with a mere look he frightens the nations. The ancient mountains disintegrate; the primeval hills are flattened. He travels on the ancient roads.'
EXEC add_BibleVerse @BibleId, 135003007, N'I see the tents of Cushan overwhelmed by trouble; the tent curtains of the land of Midian are shaking.'
EXEC add_BibleVerse @BibleId, 135003008, N'Is the Lord mad at the rivers? Are you angry with the rivers? Are you enraged at the sea? Is this why you climb into your horse-drawn chariots, your victorious chariots?'
EXEC add_BibleVerse @BibleId, 135003009, N'Your bow is ready for action; you commission your arrows. Selah. You cause flash floods on the earth’s surface.'
EXEC add_BibleVerse @BibleId, 135003010, N'When the mountains see you, they shake. The torrential downpour sweeps through. The great deep shouts out; it lifts its hands high.'
EXEC add_BibleVerse @BibleId, 135003011, N'The sun and moon stand still in their courses; the flash of your arrows drives them away, the bright light of your lightning-quick spear.'
EXEC add_BibleVerse @BibleId, 135003012, N'You furiously stomp on the earth, you angrily trample down the nations.'
EXEC add_BibleVerse @BibleId, 135003013, N'You march out to deliver your people, to deliver your special servant. You strike the leader of the wicked nation, laying him open from the lower body to the neck. Selah.'
EXEC add_BibleVerse @BibleId, 135003014, N'You pierce the heads of his warriors with a spear. They storm forward to scatter us; they shout with joy as if they were plundering the poor with no opposition.'
EXEC add_BibleVerse @BibleId, 135003015, N'But you trample on the sea with your horses, on the surging, raging waters.'
EXEC add_BibleVerse @BibleId, 135003016, N'I listened and my stomach churned; the sound made my lips quiver. My frame went limp, as if my bones were decaying, and I shook as I tried to walk. I long for the day of distress to come upon the people who attack us.'
EXEC add_BibleVerse @BibleId, 135003017, N'When the fig tree does not bud, and there are no grapes on the vines; when the olive trees do not produce, and the fields yield no crops; when the sheep disappear from the pen, and there are no cattle in the stalls,'
EXEC add_BibleVerse @BibleId, 135003018, N'I will rejoice because of the Lord; I will be happy because of the God who delivers me!'
EXEC add_BibleVerse @BibleId, 135003019, N'The sovereign Lord is my source of strength. He gives me the agility of a deer; he enables me to negotiate the rugged terrain. (This prayer is for the song leader. It is to be accompanied by stringed instruments.)'
EXEC add_BibleVerse @BibleId, 136001001, N'This is the prophetic message that the Lord gave to Zephaniah son of Cushi, son of Gedaliah, son of Amariah, son of Hezekiah. Zephaniah delivered this message during the reign of King Josiah son of Amon of Judah:'
EXEC add_BibleVerse @BibleId, 136001002, N'“I will destroy everything from the face of the earth,” says the Lord.'
EXEC add_BibleVerse @BibleId, 136001003, N'“I will destroy people and animals; I will destroy the birds in the sky and the fish in the sea. (The idolatrous images of these creatures will be destroyed along with evil people.) I will remove humanity from the face of the earth,” says the Lord.'
EXEC add_BibleVerse @BibleId, 136001004, N'“I will attack Judah and all who live in Jerusalem. I will remove from this place every trace of Baal worship, as well as the very memory of the pagan priests.'
EXEC add_BibleVerse @BibleId, 136001005, N'I will remove those who worship the stars in the sky from their rooftops, those who swear allegiance to the Lord while taking oaths in the name of their ‘king,’'
EXEC add_BibleVerse @BibleId, 136001006, N'and those who turn their backs on the Lord and do not want the Lord’s help or guidance.”'
EXEC add_BibleVerse @BibleId, 136001007, N'Be silent before the Lord God, for the Lord’s day of judgment is almost here. The Lord has prepared a sacrificial meal; he has ritually purified his guests.'
EXEC add_BibleVerse @BibleId, 136001008, N'“On the day of the Lord’s sacrificial meal, I will punish the princes and the king’s sons, and all who wear foreign styles of clothing.'
EXEC add_BibleVerse @BibleId, 136001009, N'On that day I will punish all who leap over the threshold, who fill the house of their master with wealth taken by violence and deceit.'
EXEC add_BibleVerse @BibleId, 136001010, N'On that day,” says the Lord, “a loud cry will go up from the Fish Gate, wailing from the city’s newer district, and a loud crash from the hills.'
EXEC add_BibleVerse @BibleId, 136001011, N'Wail, you who live in the market district, for all the merchants will disappear and those who count money will be removed.'
EXEC add_BibleVerse @BibleId, 136001012, N'At that time I will search through Jerusalem with lamps. I will punish the people who are entrenched in their sin, those who think to themselves, ‘The Lord neither rewards nor punishes.’'
EXEC add_BibleVerse @BibleId, 136001013, N'Their wealth will be stolen and their houses ruined! They will not live in the houses they have built, nor will they drink the wine from the vineyards they have planted.'
EXEC add_BibleVerse @BibleId, 136001014, N'The Lord’s great day of judgment is almost here; it is approaching very rapidly! There will be a bitter sound on the Lord’s day of judgment; at that time warriors will cry out in battle.'
EXEC add_BibleVerse @BibleId, 136001015, N'That day will be a day of God’s anger, a day of distress and hardship, a day of devastation and ruin, a day of darkness and gloom, a day of clouds and dark skies,'
EXEC add_BibleVerse @BibleId, 136001016, N'a day of trumpet blasts and battle cries. Judgment will fall on the fortified cities and the high corner towers.'
EXEC add_BibleVerse @BibleId, 136001017, N'I will bring distress on the people and they will stumble like blind men, for they have sinned against the Lord. Their blood will be poured out like dirt; their flesh will be scattered like manure.'
EXEC add_BibleVerse @BibleId, 136001018, N'Neither their silver nor their gold will be able to deliver them in the day of the Lord’s angry judgment. The whole earth will be consumed by his fiery wrath. Indeed, he will bring terrifying destruction on all who live on the earth.”'
EXEC add_BibleVerse @BibleId, 136002001, N'Bunch yourselves together like straw, you undesirable nation,'
EXEC add_BibleVerse @BibleId, 136002002, N'before God’s decree becomes reality and the day of opportunity disappears like windblown chaff, before the Lord’s raging anger overtakes you – before the day of the Lord’s angry judgment overtakes you!'
EXEC add_BibleVerse @BibleId, 136002003, N'Seek the Lord’s favor, all you humble people of the land who have obeyed his commands! Strive to do what is right! Strive to be humble! Maybe you will be protected on the day of the Lord’s angry judgment.'
EXEC add_BibleVerse @BibleId, 136002004, N'Indeed, Gaza will be deserted and Ashkelon will become a heap of ruins. Invaders will drive away the people of Ashdod by noon, and Ekron will be overthrown.'
EXEC add_BibleVerse @BibleId, 136002005, N'Those who live by the sea, the people who came from Crete, are as good as dead. The Lord has decreed your downfall, Canaan, land of the Philistines: “I will destroy everyone who lives there!”'
EXEC add_BibleVerse @BibleId, 136002006, N'The seacoast will be used as pasture lands by the shepherds and as pens for their flocks.'
EXEC add_BibleVerse @BibleId, 136002007, N'Those who are left from the kingdom of Judah will take possession of it. By the sea they will graze, in the houses of Ashkelon they will lie down in the evening, for the Lord their God will intervene for them and restore their prosperity.'
EXEC add_BibleVerse @BibleId, 136002008, N'“I have heard Moab’s taunts and the Ammonites’ insults. They taunted my people and verbally harassed those living in Judah.'
EXEC add_BibleVerse @BibleId, 136002009, N'Therefore, as surely as I live,” says the Lord who commands armies, the God of Israel, “be certain that Moab will become like Sodom and the Ammonites like Gomorrah. They will be overrun by weeds, filled with salt pits, and permanently desolate. Those of my people who are left will plunder their belongings; those who are left in Judah will take possession of their land.”'
EXEC add_BibleVerse @BibleId, 136002010, N'This is how they will be repaid for their arrogance, for they taunted and verbally harassed the people of the Lord who commands armies.'
EXEC add_BibleVerse @BibleId, 136002011, N'The Lord will terrify them, for he will weaken all the gods of the earth. All the distant nations will worship the Lord in their own lands.'
EXEC add_BibleVerse @BibleId, 136002012, N'“You Ethiopians will also die by my sword!”'
EXEC add_BibleVerse @BibleId, 136002013, N'The Lord will attack the north and destroy Assyria. He will make Nineveh a heap of ruins; it will be as barren as the desert.'
EXEC add_BibleVerse @BibleId, 136002014, N'Flocks and herds will lie down in the middle of it, as well as every kind of wild animal. Owls will sleep in the tops of its support pillars; they will hoot through the windows. Rubble will cover the thresholds; even the cedar work will be exposed to the elements.'
EXEC add_BibleVerse @BibleId, 136002015, N'This is how the once-proud city will end up – the city that was so secure. She thought to herself, “I am unique! No one can compare to me!” What a heap of ruins she has become, a place where wild animals live! Everyone who passes by her taunts her and shakes his fist.'
EXEC add_BibleVerse @BibleId, 136003001, N'The filthy, stained city is as good as dead; the city filled with oppressors is finished!'
EXEC add_BibleVerse @BibleId, 136003002, N'She is disobedient; she refuses correction. She does not trust the Lord; she does not seek the advice of her God.'
EXEC add_BibleVerse @BibleId, 136003003, N'Her princes are as fierce as roaring lions; her rulers are as hungry as wolves in the desert, who completely devour their prey by morning.'
EXEC add_BibleVerse @BibleId, 136003004, N'Her prophets are proud; they are deceitful men. Her priests defile what is holy; they break God’s laws.'
EXEC add_BibleVerse @BibleId, 136003005, N'The just Lord resides within her; he commits no unjust acts. Every morning he reveals his justice. At dawn he appears without fail. Yet the unjust know no shame.'
EXEC add_BibleVerse @BibleId, 136003006, N'“I destroyed nations; their walled cities are in ruins. I turned their streets into ruins; no one passes through them. Their cities are desolate; no one lives there.'
EXEC add_BibleVerse @BibleId, 136003007, N'I thought, ‘Certainly you will respect me! Now you will accept correction!’ If she had done so, her home would not be destroyed by all the punishments I have threatened. But they eagerly sinned in everything they did.'
EXEC add_BibleVerse @BibleId, 136003008, N'Therefore you must wait patiently for me,” says the Lord, “for the day when I attack and take plunder. I have decided to gather nations together and assemble kingdoms, so I can pour out my fury on them – all my raging anger. For the whole earth will be consumed by my fiery anger.'
EXEC add_BibleVerse @BibleId, 136003009, N'Know for sure that I will then enable the nations to give me acceptable praise. All of them will invoke the Lord’s name when they pray, and will worship him in unison.'
EXEC add_BibleVerse @BibleId, 136003010, N'From beyond the rivers of Ethiopia, those who pray to me will bring me tribute.'
EXEC add_BibleVerse @BibleId, 136003011, N'In that day you will not be ashamed of all your rebelliousness against me, for then I will remove from your midst those who proudly boast, and you will never again be arrogant on my holy hill.'
EXEC add_BibleVerse @BibleId, 136003012, N'I will leave in your midst a humble and meek group of people, and they will find safety in the Lord’s presence.'
EXEC add_BibleVerse @BibleId, 136003013, N'The Israelites who remain will not act deceitfully. They will not lie, and a deceitful tongue will not be found in their mouth. Indeed, they will graze peacefully like sheep and lie down; no one will terrify them.”'
EXEC add_BibleVerse @BibleId, 136003014, N'Shout for joy, Daughter Zion! Shout out, Israel! Be happy and boast with all your heart, Daughter Jerusalem!'
EXEC add_BibleVerse @BibleId, 136003015, N'The Lord has removed the judgment against you; he has turned back your enemy. Israel’s king, the Lord, is in your midst! You no longer need to fear disaster.'
EXEC add_BibleVerse @BibleId, 136003016, N'On that day they will say to Jerusalem, “Don’t be afraid, Zion! Your hands must not be paralyzed from panic!'
EXEC add_BibleVerse @BibleId, 136003017, N'The Lord your God is in your midst; he is a warrior who can deliver. He takes great delight in you; he renews you by his love; he shouts for joy over you.”'
EXEC add_BibleVerse @BibleId, 136003018, N'“As for those who grieve because they cannot attend the festivals – I took them away from you; they became tribute and were a source of shame to you.'
EXEC add_BibleVerse @BibleId, 136003019, N'Look, at that time I will deal with those who mistreated you. I will rescue the lame sheep and gather together the scattered sheep. I will take away their humiliation and make the whole earth admire and respect them.'
EXEC add_BibleVerse @BibleId, 136003020, N'At that time I will lead you – at the time I gather you together. Be sure of this! I will make all the nations of the earth respect and admire you when you see me restore you,” says the Lord.'
EXEC add_BibleVerse @BibleId, 137001001, N'On the first day of the sixth month of King Darius’ second year, the Lord spoke this message through the prophet Haggai to Zerubbabel son of Shealtiel, governor of Judah, and to the high priest Joshua son of Jehozadak:'
EXEC add_BibleVerse @BibleId, 137001002, N'The Lord who rules over all says this: “These people have said, ‘The time for rebuilding the Lord’s temple has not yet come.’”'
EXEC add_BibleVerse @BibleId, 137001003, N'So the Lord spoke through the prophet Haggai as follows:'
EXEC add_BibleVerse @BibleId, 137001004, N'“Is it right for you to live in richly paneled houses while my temple is in ruins?'
EXEC add_BibleVerse @BibleId, 137001005, N'Here then is what the Lord who rules over all says: ‘Think carefully about what you are doing.'
EXEC add_BibleVerse @BibleId, 137001006, N'You have planted much, but have harvested little. You eat, but are never filled. You drink, but are still thirsty. You put on clothes, but are not warm. Those who earn wages end up with holes in their money bags.’”'
EXEC add_BibleVerse @BibleId, 137001007, N'“Moreover, the Lord who rules over all says: ‘Pay close attention to these things also.'
EXEC add_BibleVerse @BibleId, 137001008, N'Go up to the hill country and bring back timber to build the temple. Then I will be pleased and honored,’ says the Lord.'
EXEC add_BibleVerse @BibleId, 137001009, N'‘You expected a large harvest, but instead there was little, and when you brought it home it disappeared right away. Why?’ asks the Lord who rules over all. ‘Because my temple remains in ruins, thanks to each of you favoring his own house!'
EXEC add_BibleVerse @BibleId, 137001010, N'This is why the sky has held back its dew and the earth its produce.'
EXEC add_BibleVerse @BibleId, 137001011, N'Moreover, I have called for a drought that will affect the fields, the hill country, the grain, new wine, fresh olive oil, and everything that grows from the ground; it also will harm people, animals, and everything they produce.’”'
EXEC add_BibleVerse @BibleId, 137001012, N'Then Zerubbabel son of Shealtiel and the high priest Joshua son of Jehozadak, along with the whole remnant of the people, obeyed the Lord their God. They responded favorably to the message of the prophet Haggai, who spoke just as the Lord their God had instructed him, and the people began to respect the Lord.'
EXEC add_BibleVerse @BibleId, 137001013, N'Then Haggai, the Lord’s messenger, spoke the Lord’s word to the people: “I am with you!” says the Lord.'
EXEC add_BibleVerse @BibleId, 137001014, N'So the Lord energized and encouraged Zerubbabel son of Shealtiel, governor of Judah, the high priest Joshua son of Jehozadak, and the whole remnant of the people. They came and worked on the temple of their God, the Lord who rules over all.'
EXEC add_BibleVerse @BibleId, 137001015, N'This took place on the twenty-fourth day of the sixth month of King Darius’ second year.'
EXEC add_BibleVerse @BibleId, 137002001, N'On the twenty-first day of the seventh month, the Lord spoke again through the prophet Haggai:'
EXEC add_BibleVerse @BibleId, 137002002, N'“Ask the following questions to Zerubbabel son of Shealtiel, governor of Judah, the high priest Joshua son of Jehozadak, and the remnant of the people:'
EXEC add_BibleVerse @BibleId, 137002003, N'‘Who among you survivors saw the former splendor of this temple? How does it look to you now? Isn’t it nothing by comparison?'
EXEC add_BibleVerse @BibleId, 137002004, N'Even so, take heart, Zerubbabel,’ says the Lord. ‘Take heart, Joshua son of Jehozadak, the high priest, and all you citizens of the land,’ says the Lord, ‘and begin to work. For I am with you,’ says the Lord who rules over all.'
EXEC add_BibleVerse @BibleId, 137002005, N'‘Do not fear, because I made a promise to your ancestors when they left Egypt, and my spirit even now testifies to you.’'
EXEC add_BibleVerse @BibleId, 137002006, N'Moreover, the Lord who rules over all says: ‘In just a little while I will once again shake the sky and the earth, the sea and the dry ground.'
EXEC add_BibleVerse @BibleId, 137002007, N'I will also shake up all the nations, and they will offer their treasures; then I will fill this temple with glory,’ says the Lord who rules over all.'
EXEC add_BibleVerse @BibleId, 137002008, N'‘The silver and gold will be mine,’ says the Lord who rules over all.'
EXEC add_BibleVerse @BibleId, 137002009, N'‘The future splendor of this temple will be greater than that of former times,’ the Lord who rules over all declares, ‘and in this place I will give peace.’”'
EXEC add_BibleVerse @BibleId, 137002010, N'On the twenty-fourth day of the ninth month of Darius’ second year, the Lord spoke again to the prophet Haggai:'
EXEC add_BibleVerse @BibleId, 137002011, N'“The Lord who rules over all says, ‘Ask the priests about the law.'
EXEC add_BibleVerse @BibleId, 137002012, N'If someone carries holy meat in a fold of his garment and that fold touches bread, a boiled dish, wine, olive oil, or any other food, will that item become holy?’” The priests answered, “It will not.”'
EXEC add_BibleVerse @BibleId, 137002013, N'Then Haggai asked, “If a person who is ritually unclean because of touching a dead body comes in contact with one of these items, will it become unclean?” The priests answered, “It will be unclean.”'
EXEC add_BibleVerse @BibleId, 137002014, N'Then Haggai responded, “‘The people of this nation are unclean in my sight,’ says the Lord. ‘And so is all their effort; everything they offer is also unclean.'
EXEC add_BibleVerse @BibleId, 137002015, N'Now therefore reflect carefully on the recent past, before one stone was laid on another in the Lord’s temple.'
EXEC add_BibleVerse @BibleId, 137002016, N'From that time when one came expecting a heap of twenty measures, there were only ten; when one came to the wine vat to draw out fifty measures from it, there were only twenty.'
EXEC add_BibleVerse @BibleId, 137002017, N'I struck all the products of your labor with blight, disease, and hail, and yet you brought nothing to me,’ says the Lord.'
EXEC add_BibleVerse @BibleId, 137002018, N'‘Think carefully about the past: from today, the twenty-fourth day of the ninth month, to the day work on the temple of the Lord was resumed, think about it.'
EXEC add_BibleVerse @BibleId, 137002019, N'The seed is still in the storehouse, isn’t it? And the vine, fig tree, pomegranate, and olive tree have not produced. Nevertheless, from today on I will bless you.’”'
EXEC add_BibleVerse @BibleId, 137002020, N'Then the Lord spoke again to Haggai on the twenty-fourth day of the month:'
EXEC add_BibleVerse @BibleId, 137002021, N'Tell Zerubbabel governor of Judah: ‘I am ready to shake the sky and the earth.'
EXEC add_BibleVerse @BibleId, 137002022, N'I will overthrow royal thrones and shatter the might of earthly kingdoms. I will overthrow chariots and those who ride them, and horses and their riders will fall as people kill one another.'
EXEC add_BibleVerse @BibleId, 137002023, N'On that day,’ says the Lord who rules over all, ‘I will take you, Zerubbabel son of Shealtiel, my servant,’ says the Lord, ‘and I will make you like a signet ring, for I have chosen you,’ says the Lord who rules over all.”'
EXEC add_BibleVerse @BibleId, 138001001, N'In the eighth month of Darius’ second year, the word of the Lord came to the prophet Zechariah, son of Berechiah son of Iddo, as follows:'
EXEC add_BibleVerse @BibleId, 138001002, N'The Lord was very angry with your ancestors.'
EXEC add_BibleVerse @BibleId, 138001003, N'Therefore say to the people: The Lord who rules over all says, “Turn to me,” says the Lord who rules over all, “and I will turn to you,” says the Lord who rules over all.'
EXEC add_BibleVerse @BibleId, 138001004, N'“Do not be like your ancestors, to whom the former prophets called out, saying, ‘The Lord who rules over all says, “Turn now from your evil wickedness,”’ but they would by no means obey me,” says the Lord.'
EXEC add_BibleVerse @BibleId, 138001005, N'“As for your ancestors, where are they? And did the prophets live forever?'
EXEC add_BibleVerse @BibleId, 138001006, N'But have my words and statutes, which I commanded my servants the prophets, not outlived your fathers? Then they paid attention and confessed, ‘The Lord who rules over all has indeed done what he said he would do to us, because of our sinful ways.’”'
EXEC add_BibleVerse @BibleId, 138001007, N'On the twenty-fourth day of the eleventh month, the month Shebat, in Darius’ second year, the word of the Lord came to the prophet Zechariah son of Berechiah son of Iddo, as follows:'
EXEC add_BibleVerse @BibleId, 138001008, N'I was attentive that night and saw a man seated on a red horse that stood among some myrtle trees in the ravine. Behind him were red, sorrel, and white horses.'
EXEC add_BibleVerse @BibleId, 138001009, N'Then I asked one nearby, “What are these, sir?” The angelic messenger who replied to me said, “I will show you what these are.”'
EXEC add_BibleVerse @BibleId, 138001010, N'Then the man standing among the myrtle trees spoke up and said, “These are the ones whom the Lord has sent to walk about on the earth.”'
EXEC add_BibleVerse @BibleId, 138001011, N'The riders then agreed with the angel of the Lord, who was standing among the myrtle trees, “We have been walking about on the earth, and now everything is at rest and quiet.”'
EXEC add_BibleVerse @BibleId, 138001012, N'The angel of the Lord then asked, “Lord who rules over all, how long before you have compassion on Jerusalem and the other cities of Judah which you have been so angry with for these seventy years?”'
EXEC add_BibleVerse @BibleId, 138001013, N'The Lord then addressed good, comforting words to the angelic messenger who was speaking to me.'
EXEC add_BibleVerse @BibleId, 138001014, N'Turning to me, the messenger then said, “Cry out that the Lord who rules over all says, ‘I am very much moved for Jerusalem and for Zion.'
EXEC add_BibleVerse @BibleId, 138001015, N'But I am greatly displeased with the nations that take my grace for granted. I was a little displeased with them, but they have only made things worse for themselves.'
EXEC add_BibleVerse @BibleId, 138001016, N'“‘Therefore,’ says the Lord, ‘I have become compassionate toward Jerusalem and will rebuild my temple in it,’ says the Lord who rules over all. ‘Once more a surveyor’s measuring line will be stretched out over Jerusalem.’'
EXEC add_BibleVerse @BibleId, 138001017, N'Speak up again with the message of the Lord who rules over all: ‘My cities will once more overflow with prosperity, and once more the Lord will comfort Zion and validate his choice of Jerusalem.’”'
EXEC add_BibleVerse @BibleId, 138001018, N'Once again I looked and this time I saw four horns.'
EXEC add_BibleVerse @BibleId, 138001019, N'So I asked the angelic messenger who spoke with me, “What are these?” He replied, “These are the horns that have scattered Judah, Israel, and Jerusalem.”'
EXEC add_BibleVerse @BibleId, 138001020, N'Next the Lord showed me four blacksmiths.'
EXEC add_BibleVerse @BibleId, 138001021, N'I asked, “What are these going to do?” He answered, “These horns are the ones that have scattered Judah so that there is no one to be seen. But the blacksmiths have come to terrify Judah’s enemies and cut off the horns of the nations that have thrust themselves against the land of Judah in order to scatter its people.”'
EXEC add_BibleVerse @BibleId, 138002001, N'I looked again, and there was a man with a measuring line in his hand.'
EXEC add_BibleVerse @BibleId, 138002002, N'I asked, “Where are you going?” He replied, “To measure Jerusalem in order to determine its width and its length.”'
EXEC add_BibleVerse @BibleId, 138002003, N'At this point the angelic messenger who spoke to me went out, and another messenger came to meet him'
EXEC add_BibleVerse @BibleId, 138002004, N'and said to him, “Hurry, speak to this young man as follows: ‘Jerusalem will no longer be enclosed by walls because of the multitude of people and animals there.'
EXEC add_BibleVerse @BibleId, 138002005, N'But I (the Lord says) will be a wall of fire surrounding Jerusalem and the source of glory in her midst.’”'
EXEC add_BibleVerse @BibleId, 138002006, N'“You there! Flee from the northland!” says the Lord, “for like the four winds of heaven I have scattered you,” says the Lord.'
EXEC add_BibleVerse @BibleId, 138002007, N'“Escape, Zion, you who live among the Babylonians!”'
EXEC add_BibleVerse @BibleId, 138002008, N'For the Lord who rules over all says to me that for his own glory he has sent me to the nations that plundered you – for anyone who touches you touches the pupil of his eye.'
EXEC add_BibleVerse @BibleId, 138002009, N'“I am about to punish them in such a way,” he says, “that they will be looted by their own slaves.” Then you will know that the Lord who rules over all has sent me.'
EXEC add_BibleVerse @BibleId, 138002010, N'“Sing out and be happy, Zion my daughter! For look, I have come; I will settle in your midst,” says the Lord.'
EXEC add_BibleVerse @BibleId, 138002011, N'“Many nations will join themselves to the Lord on the day of salvation, and they will also be my people. Indeed, I will settle in the midst of you all.” Then you will know that the Lord who rules over all has sent me to you.'
EXEC add_BibleVerse @BibleId, 138002012, N'The Lord will take possession of Judah as his portion in the holy land and he will choose Jerusalem once again.'
EXEC add_BibleVerse @BibleId, 138002013, N'Be silent in the Lord’s presence, all people everywhere, for he is being moved to action in his holy dwelling place.'
EXEC add_BibleVerse @BibleId, 138003001, N'Next I saw Joshua the high priest standing before the angel of the Lord, with Satan standing at his right hand to accuse him.'
EXEC add_BibleVerse @BibleId, 138003002, N'The Lord said to Satan, “May the Lord rebuke you, Satan! May the Lord, who has chosen Jerusalem, rebuke you! Isn’t this man like a burning stick snatched from the fire?”'
EXEC add_BibleVerse @BibleId, 138003003, N'Now Joshua was dressed in filthy clothes as he stood there before the angel.'
EXEC add_BibleVerse @BibleId, 138003004, N'The angel spoke up to those standing all around, “Remove his filthy clothes.” Then he said to Joshua, “I have freely forgiven your iniquity and will dress you in fine clothing.”'
EXEC add_BibleVerse @BibleId, 138003005, N'Then I spoke up, “Let a clean turban be put on his head.” So they put a clean turban on his head and clothed him, while the angel of the Lord stood nearby.'
EXEC add_BibleVerse @BibleId, 138003006, N'Then the angel of the Lord exhorted Joshua solemnly:'
EXEC add_BibleVerse @BibleId, 138003007, N'“The Lord who rules over all says, ‘If you live and work according to my requirements, you will be able to preside over my temple and attend to my courtyards, and I will allow you to come and go among these others who are standing by you.'
EXEC add_BibleVerse @BibleId, 138003008, N'Listen now, Joshua the high priest, both you and your colleagues who are sitting before you, all of you are a symbol that I am about to introduce my servant, the Branch.'
EXEC add_BibleVerse @BibleId, 138003009, N'As for the stone I have set before Joshua – on the one stone there are seven eyes. I am about to engrave an inscription on it,’ says the Lord who rules over all, ‘to the effect that I will remove the iniquity of this land in a single day.'
EXEC add_BibleVerse @BibleId, 138003010, N'In that day,’ says the Lord who rules over all, ‘everyone will invite his friend to fellowship under his vine and under his fig tree.’”'
EXEC add_BibleVerse @BibleId, 138004001, N'The angelic messenger who had been speaking with me then returned and woke me, as a person is wakened from sleep.'
EXEC add_BibleVerse @BibleId, 138004002, N'He asked me, “What do you see?” I replied, “I see a menorah of pure gold with a receptacle at the top and seven lamps, with fourteen pipes going to the lamps.'
EXEC add_BibleVerse @BibleId, 138004003, N'There are also two olive trees beside it, one on the right of the receptacle and the other on the left.”'
EXEC add_BibleVerse @BibleId, 138004004, N'Then I asked the messenger who spoke with me, “What are these, sir?”'
EXEC add_BibleVerse @BibleId, 138004005, N'He replied, “Don’t you know what these are?” So I responded, “No, sir.”'
EXEC add_BibleVerse @BibleId, 138004006, N'Therefore he told me, “These signify the word of the Lord to Zerubbabel: ‘Not by strength and not by power, but by my Spirit,’ says the Lord who rules over all.”'
EXEC add_BibleVerse @BibleId, 138004007, N'“What are you, you great mountain? Because of Zerubbabel you will become a level plain! And he will bring forth the temple capstone with shoutings of ‘Grace! Grace!’ because of this.”'
EXEC add_BibleVerse @BibleId, 138004008, N'Moreover, the word of the Lord came to me as follows:'
EXEC add_BibleVerse @BibleId, 138004009, N'“The hands of Zerubbabel have laid the foundations of this temple, and his hands will complete it.” Then you will know that the Lord who rules over all has sent me to you.'
EXEC add_BibleVerse @BibleId, 138004010, N'For who dares make light of small beginnings? These seven eyes will joyfully look on the tin tablet in Zerubbabel’s hand. (These are the eyes of the Lord, which constantly range across the whole earth.)'
EXEC add_BibleVerse @BibleId, 138004011, N'Next I asked the messenger, “What are these two olive trees on the right and the left of the menorah?”'
EXEC add_BibleVerse @BibleId, 138004012, N'Before he could reply I asked again, “What are these two extensions of the olive trees, which are emptying out the golden oil through the two golden pipes?”'
EXEC add_BibleVerse @BibleId, 138004013, N'He replied, “Don’t you know what these are?” And I said, “No, sir.”'
EXEC add_BibleVerse @BibleId, 138004014, N'So he said, “These are the two anointed ones who stand by the Lord of the whole earth.”'
EXEC add_BibleVerse @BibleId, 138005001, N'Then I turned to look, and there was a flying scroll!'
EXEC add_BibleVerse @BibleId, 138005002, N'Someone asked me, “What do you see?” I replied, “I see a flying scroll thirty feet long and fifteen feet wide.”'
EXEC add_BibleVerse @BibleId, 138005003, N'The speaker went on to say, “This is a curse traveling across the whole earth. For example, according to the curse whoever steals will be removed from the community; or on the other hand (according to the curse) whoever swears falsely will suffer the same fate.”'
EXEC add_BibleVerse @BibleId, 138005004, N'“I will send it out,” says the Lord who rules over all, “and it will enter the house of the thief and of the person who swears falsely in my name. It will land in the middle of his house and destroy both timber and stones.”'
EXEC add_BibleVerse @BibleId, 138005005, N'After this the angelic messenger who had been speaking to me went out and said, “Look, see what is leaving.”'
EXEC add_BibleVerse @BibleId, 138005006, N'I asked, “What is it?” And he replied, “It is a basket for measuring grain that is moving away from here.” Moreover, he said, “This is their ‘eye’ throughout all the earth.”'
EXEC add_BibleVerse @BibleId, 138005007, N'Then a round lead cover was raised up, revealing a woman sitting inside the basket.'
EXEC add_BibleVerse @BibleId, 138005008, N'He then said, “This woman represents wickedness,” and he pushed her down into the basket and placed the lead cover on top.'
EXEC add_BibleVerse @BibleId, 138005009, N'Then I looked again and saw two women going forth with the wind in their wings (they had wings like those of a stork) and they lifted up the basket between the earth and the sky.'
EXEC add_BibleVerse @BibleId, 138005010, N'I asked the messenger who was speaking to me, “Where are they taking the basket?”'
EXEC add_BibleVerse @BibleId, 138005011, N'He replied, “To build a temple for her in the land of Babylonia. When it is finished, she will be placed there in her own residence.”'
EXEC add_BibleVerse @BibleId, 138006001, N'Once more I looked, and this time I saw four chariots emerging from between two mountains of bronze.'
EXEC add_BibleVerse @BibleId, 138006002, N'Harnessed to the first chariot were red horses, to the second black horses,'
EXEC add_BibleVerse @BibleId, 138006003, N'to the third white horses, and to the fourth spotted horses, all of them strong.'
EXEC add_BibleVerse @BibleId, 138006004, N'Then I asked the angelic messenger who was speaking with me, “What are these, sir?”'
EXEC add_BibleVerse @BibleId, 138006005, N'The messenger replied, “These are the four spirits of heaven that have been presenting themselves before the Lord of all the earth.'
EXEC add_BibleVerse @BibleId, 138006006, N'The chariot with the black horses is going to the north country and the white ones are going after them, but the spotted ones are going to the south country.'
EXEC add_BibleVerse @BibleId, 138006007, N'All these strong ones are scattering; they have sought permission to go and walk about over the earth.” The Lord had said, “Go! Walk about over the earth!” So they are doing so.'
EXEC add_BibleVerse @BibleId, 138006008, N'Then he cried out to me, “Look! The ones going to the northland have brought me peace about the northland.”'
EXEC add_BibleVerse @BibleId, 138006009, N'The word of the Lord came to me as follows:'
EXEC add_BibleVerse @BibleId, 138006010, N'“Choose some people from among the exiles, namely, Heldai, Tobijah, and Jedaiah, all of whom have come from Babylon, and when you have done so go to the house of Josiah son of Zephaniah.'
EXEC add_BibleVerse @BibleId, 138006011, N'Then take some silver and gold to make a crown and set it on the head of Joshua son of Jehozadak, the high priest.'
EXEC add_BibleVerse @BibleId, 138006012, N'Then say to him, ‘The Lord who rules over all says, “Look – here is the man whose name is Branch, who will sprout up from his place and build the temple of the Lord.'
EXEC add_BibleVerse @BibleId, 138006013, N'Indeed, he will build the temple of the Lord, and he will be clothed in splendor, sitting as king on his throne. Moreover, there will be a priest with him on his throne and they will see eye to eye on everything.'
EXEC add_BibleVerse @BibleId, 138006014, N'The crown will then be turned over to Helem, Tobijah, Jedaiah, and Hen son of Zephaniah as a memorial in the temple of the Lord.'
EXEC add_BibleVerse @BibleId, 138006015, N'Then those who are far away will come and build the temple of the Lord so that you may know that the Lord who rules over all has sent me to you. This will all come to pass if you completely obey the voice of the Lord your God.”’”'
EXEC add_BibleVerse @BibleId, 138007001, N'In King Darius’ fourth year, on the fourth day of Kislev, the ninth month, the word of the Lord came to Zechariah.'
EXEC add_BibleVerse @BibleId, 138007002, N'Now the people of Bethel had sent Sharezer and Regem-Melech and their companions to seek the Lord’s favor'
EXEC add_BibleVerse @BibleId, 138007003, N'by asking both the priests of the temple of the Lord who rules over all and the prophets, “Should we weep in the fifth month, fasting as we have done over the years?”'
EXEC add_BibleVerse @BibleId, 138007004, N'The word of the Lord who rules over all then came to me,'
EXEC add_BibleVerse @BibleId, 138007005, N'“Speak to all the people and priests of the land as follows: ‘When you fasted and lamented in the fifth and seventh months through all these seventy years, did you truly fast for me – for me, indeed?'
EXEC add_BibleVerse @BibleId, 138007006, N'And now when you eat and drink, are you not doing so for yourselves?’”'
EXEC add_BibleVerse @BibleId, 138007007, N'Should you not have obeyed the words that the Lord cried out through the former prophets when Jerusalem was peacefully inhabited and her surrounding cities, the Negev, and the Shephelah were also populated?'
EXEC add_BibleVerse @BibleId, 138007008, N'Again the word of the Lord came to Zechariah:'
EXEC add_BibleVerse @BibleId, 138007009, N'“The Lord who rules over all said, ‘Exercise true judgment and show brotherhood and compassion to each other.'
EXEC add_BibleVerse @BibleId, 138007010, N'You must not oppress the widow, the orphan, the foreigner, or the poor, nor should anyone secretly plot evil against his fellow human being.’'
EXEC add_BibleVerse @BibleId, 138007011, N'“But they refused to pay attention, turning away stubbornly and stopping their ears so they could not hear.'
EXEC add_BibleVerse @BibleId, 138007012, N'Indeed, they made their heart as hard as diamond, so that they could not obey the Torah and the other words the Lord who rules over all had sent by his Spirit through the former prophets. Therefore, the Lord who rules over all had poured out great wrath.'
EXEC add_BibleVerse @BibleId, 138007013, N'“‘It then came about that just as I cried out, but they would not obey, so they will cry out, but I will not listen,’ the Lord Lord who rules over all had said.'
EXEC add_BibleVerse @BibleId, 138007014, N'‘Rather, I will sweep them away in a storm into all the nations they are not familiar with.’ Thus the land had become desolate because of them, with no one crossing through or returning, for they had made the fruitful land a waste.”'
EXEC add_BibleVerse @BibleId, 138008001, N'Then the word of the Lord who rules over all came to me as follows:'
EXEC add_BibleVerse @BibleId, 138008002, N'“The Lord who rules over all says, ‘I am very much concerned for Zion; indeed, I am so concerned for her that my rage will fall on those who hurt her.’'
EXEC add_BibleVerse @BibleId, 138008003, N'The Lord says, ‘I have returned to Zion and will live within Jerusalem. Now Jerusalem will be called “truthful city,” “mountain of the Lord who rules over all,” “holy mountain.”’'
EXEC add_BibleVerse @BibleId, 138008004, N'Moreover, the Lord who rules over all says, ‘Old men and women will once more live in the plazas of Jerusalem, each one leaning on a cane because of advanced age.'
EXEC add_BibleVerse @BibleId, 138008005, N'And the streets of the city will be full of boys and girls playing.'
EXEC add_BibleVerse @BibleId, 138008006, N'And,’ says the Lord who rules over all, ‘though such a thing may seem to be difficult in the opinion of the small community of those days, will it also appear difficult to me?’ asks the Lord who rules over all.'
EXEC add_BibleVerse @BibleId, 138008007, N'“The Lord who rules over all asserts, ‘I am about to save my people from the lands of the east and the west.'
EXEC add_BibleVerse @BibleId, 138008008, N'And I will bring them to settle within Jerusalem. They will be my people, and I will be their God, in truth and righteousness.’'
EXEC add_BibleVerse @BibleId, 138008009, N'“The Lord who rules over all also says, ‘Gather strength, you who are listening to these words today from the mouths of the prophets who were there at the founding of the house of the Lord who rules over all, so that the temple might be built.'
EXEC add_BibleVerse @BibleId, 138008010, N'Before that time there was no compensation for man or animal, nor was there any relief from adversity for those who came and went, because I had pitted everybody – each one – against everyone else.'
EXEC add_BibleVerse @BibleId, 138008011, N'But I will be different now to this remnant of my people from the way I was in those days,’ says the Lord who rules over all,'
EXEC add_BibleVerse @BibleId, 138008012, N'‘for there will be a peaceful time of sowing, the vine will produce its fruit and the ground its yield, and the skies will rain down dew. Then I will allow the remnant of my people to possess all these things.'
EXEC add_BibleVerse @BibleId, 138008013, N'And it will come about that just as you (both Judah and Israel) were a curse to the nations, so I will save you and you will be a blessing. Do not be afraid! Instead, be strong!’'
EXEC add_BibleVerse @BibleId, 138008014, N'“For the Lord who rules over all says, ‘As I had planned to hurt you when your fathers made me angry,’ says the Lord who rules over all, ‘and I was not sorry,'
EXEC add_BibleVerse @BibleId, 138008015, N'so, to the contrary, I have planned in these days to do good to Jerusalem and Judah – do not fear!'
EXEC add_BibleVerse @BibleId, 138008016, N'These are the things you must do: Speak the truth, each of you, to one another. Practice true and righteous judgment in your courts.'
EXEC add_BibleVerse @BibleId, 138008017, N'Do not plan evil in your hearts against one another. Do not favor a false oath – these are all things that I hate,’ says the Lord.”'
EXEC add_BibleVerse @BibleId, 138008018, N'The word of the Lord who rules over all came to me as follows:'
EXEC add_BibleVerse @BibleId, 138008019, N'“The Lord who rules over all says, ‘The fast of the fourth, fifth, seventh, and tenth months will become joyful and happy, pleasant feasts for the house of Judah, so love truth and peace.’'
EXEC add_BibleVerse @BibleId, 138008020, N'The Lord who rules over all says, ‘It will someday come to pass that people – residents of many cities – will come.'
EXEC add_BibleVerse @BibleId, 138008021, N'The inhabitants of one will go to another and say, “Let’s go up at once to ask the favor of the Lord, to seek the Lord who rules over all. Indeed, I’ll go with you.”’'
EXEC add_BibleVerse @BibleId, 138008022, N'Many peoples and powerful nations will come to Jerusalem to seek the Lord who rules over all and to ask his favor.'
EXEC add_BibleVerse @BibleId, 138008023, N'The Lord who rules over all says, ‘In those days ten people from all languages and nations will grasp hold of – indeed, grab – the robe of one Jew and say, “Let us go with you, for we have heard that God is with you.”’”'
EXEC add_BibleVerse @BibleId, 138009001, N'An oracle of the word of the Lord concerning the land of Hadrach, with its focus on Damascus: The eyes of all humanity, especially of the tribes of Israel, are toward the Lord,'
EXEC add_BibleVerse @BibleId, 138009002, N'as are those of Hamath also, which adjoins Damascus, and Tyre though they consider themselves to be very wise.'
EXEC add_BibleVerse @BibleId, 138009003, N'Tyre built herself a fortification and piled up silver like dust and gold like the mud of the streets!'
EXEC add_BibleVerse @BibleId, 138009004, N'Nevertheless the Lord will evict her and shove her fortifications into the sea – she will be consumed by fire.'
EXEC add_BibleVerse @BibleId, 138009005, N'Ashkelon will see and be afraid; Gaza will be in great anguish, as will Ekron, for her hope will have been dried up. Gaza will lose her king, and Ashkelon will no longer be inhabited.'
EXEC add_BibleVerse @BibleId, 138009006, N'A mongrel people will live in Ashdod, for I will greatly humiliate the Philistines.'
EXEC add_BibleVerse @BibleId, 138009007, N'I will take away their abominable religious practices; then those who survive will become a community of believers in our God, like a clan in Judah, and Ekron will be like the Jebusites.'
EXEC add_BibleVerse @BibleId, 138009008, N'Then I will surround my temple to protect it like a guard from anyone crossing back and forth; so no one will cross over against them anymore as an oppressor, for now I myself have seen it.'
EXEC add_BibleVerse @BibleId, 138009009, N'Rejoice greatly, daughter of Zion! Shout, daughter of Jerusalem! Look! Your king is coming to you: he is legitimate and victorious, humble and riding on a donkey – on a young donkey, the foal of a female donkey.'
EXEC add_BibleVerse @BibleId, 138009010, N'I will remove the chariot from Ephraim and the warhorse from Jerusalem, and the battle bow will be removed. Then he will announce peace to the nations. His dominion will be from sea to sea and from the Euphrates River to the ends of the earth.'
EXEC add_BibleVerse @BibleId, 138009011, N'Moreover, as for you, because of our covenant relationship secured with blood, I will release your prisoners from the waterless pit.'
EXEC add_BibleVerse @BibleId, 138009012, N'Return to the stronghold, you prisoners, with hope; today I declare that I will return double what was taken from you.'
EXEC add_BibleVerse @BibleId, 138009013, N'I will bend Judah as my bow; I will load the bow with Ephraim, my arrow! I will stir up your sons, Zion, against yours, Greece, and I will make you, Zion, like a warrior’s sword.'
EXEC add_BibleVerse @BibleId, 138009014, N'Then the Lord will appear above them, and his arrow will shoot forth like lightning; the Lord God will blow the trumpet and will sally forth on the southern storm winds.'
EXEC add_BibleVerse @BibleId, 138009015, N'The Lord who rules over all will guard them, and they will prevail and overcome with sling stones. Then they will drink, and will become noisy like drunkards, full like the sacrificial basin or like the corners of the altar.'
EXEC add_BibleVerse @BibleId, 138009016, N'On that day the Lord their God will deliver them as the flock of his people, for they are the precious stones of a crown sparkling over his land.'
EXEC add_BibleVerse @BibleId, 138009017, N'How precious and fair! Grain will make the young men flourish and new wine the young women.'
EXEC add_BibleVerse @BibleId, 138010001, N'Ask the Lord for rain in the season of the late spring rains – the Lord who causes thunderstorms – and he will give everyone showers of rain and green growth in the field.'
EXEC add_BibleVerse @BibleId, 138010002, N'For the household gods have spoken wickedness, the soothsayers have seen a lie, and as for the dreamers, they have disclosed emptiness and give comfort in vain. Therefore the people set out like sheep and become scattered because they have no shepherd.'
EXEC add_BibleVerse @BibleId, 138010003, N'I am enraged at the shepherds and will punish the lead-goats. For the Lord who rules over all has brought blessing to his flock, the house of Judah, and will transform them into his majestic warhorse.'
EXEC add_BibleVerse @BibleId, 138010004, N'From him will come the cornerstone, the wall peg, the battle bow, and every ruler.'
EXEC add_BibleVerse @BibleId, 138010005, N'And they will be like warriors trampling the mud of the streets in battle. They will fight, for the Lord will be with them, and will defeat the enemy cavalry.'
EXEC add_BibleVerse @BibleId, 138010006, N'“I (says the Lord) will strengthen the kingdom of Judah and deliver the people of Joseph and will bring them back because of my compassion for them. They will be as though I had never rejected them, for I am the Lord their God and therefore I will hear them.'
EXEC add_BibleVerse @BibleId, 138010007, N'The Ephraimites will be like warriors and will rejoice as if they had drunk wine. Their children will see it and rejoice; they will celebrate in the things of the Lord.'
EXEC add_BibleVerse @BibleId, 138010008, N'I will signal for them and gather them, for I have already redeemed them; then they will become as numerous as they were before.'
EXEC add_BibleVerse @BibleId, 138010009, N'Though I scatter them among the nations, they will remember in far-off places – they and their children will sprout forth and return.'
EXEC add_BibleVerse @BibleId, 138010010, N'I will bring them back from Egypt and gather them from Assyria. I will bring them to the lands of Gilead and Lebanon, for there will not be enough room for them in their own land.'
EXEC add_BibleVerse @BibleId, 138010011, N'The Lord will cross the sea of storms and will calm its turbulence. The depths of the Nile will dry up, the pride of Assyria will be humbled, and the domination of Egypt will be no more.'
EXEC add_BibleVerse @BibleId, 138010012, N'Thus I will strengthen them by my power, and they will walk about in my name,” says the Lord.'
EXEC add_BibleVerse @BibleId, 138011001, N'Open your gates, Lebanon, so that the fire may consume your cedars.'
EXEC add_BibleVerse @BibleId, 138011002, N'Howl, fir tree, because the cedar has fallen; the majestic trees have been destroyed. Howl, oaks of Bashan, because the impenetrable forest has fallen.'
EXEC add_BibleVerse @BibleId, 138011003, N'Listen to the howling of shepherds, because their magnificence has been destroyed. Listen to the roaring of young lions, because the thickets of the Jordan have been devastated.'
EXEC add_BibleVerse @BibleId, 138011004, N'The Lord my God says this: “Shepherd the flock set aside for slaughter.'
EXEC add_BibleVerse @BibleId, 138011005, N'Those who buy them slaughter them and are not held guilty; those who sell them say, ‘Blessed be the Lord, for I am rich.’ Their own shepherds have no compassion for them.'
EXEC add_BibleVerse @BibleId, 138011006, N'Indeed, I will no longer have compassion on the people of the land,” says the Lord, “but instead I will turn every last person over to his neighbor and his king. They will devastate the land, and I will not deliver it from them.”'
EXEC add_BibleVerse @BibleId, 138011007, N'So I began to shepherd the flock destined for slaughter, the most afflicted of all the flock. Then I took two staffs, calling one “Pleasantness” and the other “Binders,” and I tended the flock.'
EXEC add_BibleVerse @BibleId, 138011008, N'Next I eradicated the three shepherds in one month, for I ran out of patience with them and, indeed, they detested me as well.'
EXEC add_BibleVerse @BibleId, 138011009, N'I then said, “I will not shepherd you. What is to die, let it die, and what is to be eradicated, let it be eradicated. As for those who survive, let them eat each other’s flesh!”'
EXEC add_BibleVerse @BibleId, 138011010, N'Then I took my staff “Pleasantness” and cut it in two to annul my covenant that I had made with all the people.'
EXEC add_BibleVerse @BibleId, 138011011, N'So it was annulled that very day, and then the most afflicted of the flock who kept faith with me knew that that was the word of the Lord.'
EXEC add_BibleVerse @BibleId, 138011012, N'Then I said to them, “If it seems good to you, pay me my wages, but if not, forget it.” So they weighed out my payment – thirty pieces of silver.'
EXEC add_BibleVerse @BibleId, 138011013, N'The Lord then said to me, “Throw to the potter that exorbitant sum at which they valued me!” So I took the thirty pieces of silver and threw them to the potter at the temple of the Lord.'
EXEC add_BibleVerse @BibleId, 138011014, N'Then I cut the second staff “Binders” in two in order to annul the covenant of brotherhood between Judah and Israel.'
EXEC add_BibleVerse @BibleId, 138011015, N'Again the Lord said to me, “Take up once more the equipment of a foolish shepherd.'
EXEC add_BibleVerse @BibleId, 138011016, N'Indeed, I am about to raise up a shepherd in the land who will not take heed to the sheep headed to slaughter, will not seek the scattered, and will not heal the injured. Moreover, he will not nourish the one that is healthy but instead will eat the meat of the fat sheep and tear off their hooves.'
EXEC add_BibleVerse @BibleId, 138011017, N'Woe to the worthless shepherd who abandons the flock! May a sword fall on his arm and his right eye! May his arm wither completely away, and his right eye become completely blind!”'
EXEC add_BibleVerse @BibleId, 138012001, N'The revelation of the word of the Lord concerning Israel: The Lord – he who stretches out the heavens and lays the foundations of the earth, who forms the human spirit within a person – says,'
EXEC add_BibleVerse @BibleId, 138012002, N'“I am about to make Jerusalem a cup that brings dizziness to all the surrounding nations; indeed, Judah will also be included when Jerusalem is besieged.'
EXEC add_BibleVerse @BibleId, 138012003, N'Moreover, on that day I will make Jerusalem a heavy burden for all the nations, and all who try to carry it will be seriously injured; yet all the peoples of the earth will be assembled against it.'
EXEC add_BibleVerse @BibleId, 138012004, N'In that day,” says the Lord, “I will strike every horse with confusion and its rider with madness. I will pay close attention to the house of Judah, but will strike all the horses of the nations with blindness.'
EXEC add_BibleVerse @BibleId, 138012005, N'Then the leaders of Judah will say to themselves, ‘The inhabitants of Jerusalem are a means of strength to us through their God, the Lord who rules over all.’'
EXEC add_BibleVerse @BibleId, 138012006, N'On that day I will make the leaders of Judah like an igniter among sticks and a burning torch among sheaves, and they will burn up all the surrounding nations right and left. Then the people of Jerusalem will settle once more in their place, the city of Jerusalem.'
EXEC add_BibleVerse @BibleId, 138012007, N'The Lord also will deliver the homes of Judah first, so that the splendor of the kingship of David and of the people of Jerusalem may not exceed that of Judah.'
EXEC add_BibleVerse @BibleId, 138012008, N'On that day the Lord himself will defend the inhabitants of Jerusalem, so that the weakest among them will be like mighty David, and the dynasty of David will be like God, like the angel of the Lord before them.'
EXEC add_BibleVerse @BibleId, 138012009, N'So on that day I will set out to destroy all the nations that come against Jerusalem.”'
EXEC add_BibleVerse @BibleId, 138012010, N'“I will pour out on the kingship of David and the population of Jerusalem a spirit of grace and supplication so that they will look to me, the one they have pierced. They will lament for him as one laments for an only son, and there will be a bitter cry for him like the bitter cry for a firstborn.'
EXEC add_BibleVerse @BibleId, 138012011, N'On that day the lamentation in Jerusalem will be as great as the lamentation at Hadad-Rimmon in the plain of Megiddo.'
EXEC add_BibleVerse @BibleId, 138012012, N'The land will mourn, clan by clan – the clan of the royal household of David by itself and their wives by themselves; the clan of the family of Nathan by itself and their wives by themselves;'
EXEC add_BibleVerse @BibleId, 138012013, N'the clan of the descendants of Levi by itself and their wives by themselves; and the clan of the Shimeites by itself and their wives by themselves –'
EXEC add_BibleVerse @BibleId, 138012014, N'all the clans that remain, each separately with their wives.”'
EXEC add_BibleVerse @BibleId, 138013001, N'“In that day there will be a fountain opened up for the dynasty of David and the people of Jerusalem to cleanse them from sin and impurity.'
EXEC add_BibleVerse @BibleId, 138013002, N'And also on that day,” says the Lord who rules over all, “I will remove the names of the idols from the land and they will never again be remembered. Moreover, I will remove the prophets and the unclean spirit from the land.'
EXEC add_BibleVerse @BibleId, 138013003, N'Then, if anyone prophesies in spite of this, his father and mother to whom he was born will say to him, ‘You cannot live, for you lie in the name of the Lord.’ Then his father and mother to whom he was born will run him through with a sword when he prophesies.'
EXEC add_BibleVerse @BibleId, 138013004, N'“Therefore, on that day each prophet will be ashamed of his vision when he prophesies and will no longer wear the hairy garment of a prophet to deceive the people.'
EXEC add_BibleVerse @BibleId, 138013005, N'Instead he will say, ‘I am no prophet – indeed, I am a farmer, for a man has made me his indentured servant since my youth.’'
EXEC add_BibleVerse @BibleId, 138013006, N'Then someone will ask him, ‘What are these wounds on your chest?’ and he will answer, ‘Some that I received in the house of my friends.’'
EXEC add_BibleVerse @BibleId, 138013007, N'“Awake, sword, against my shepherd, against the man who is my associate,” says the Lord who rules over all. Strike the shepherd that the flock may be scattered; I will turn my hand against the insignificant ones.'
EXEC add_BibleVerse @BibleId, 138013008, N'It will happen in all the land, says the Lord, that two-thirds of the people in it will be cut off and die, but one-third will be left in it.'
EXEC add_BibleVerse @BibleId, 138013009, N'Then I will bring the remaining third into the fire; I will refine them like silver is refined and will test them like gold is tested. They will call on my name and I will answer; I will say, ‘These are my people,’ and they will say, ‘The Lord is my God.’”'
EXEC add_BibleVerse @BibleId, 138014001, N'A day of the Lord is about to come when your possessions will be divided as plunder in your midst.'
EXEC add_BibleVerse @BibleId, 138014002, N'For I will gather all the nations against Jerusalem to wage war; the city will be taken, its houses plundered, and the women raped. Then half of the city will go into exile, but the remainder of the people will not be taken away.'
EXEC add_BibleVerse @BibleId, 138014003, N'Then the Lord will go to battle and fight against those nations, just as he fought battles in ancient days.'
EXEC add_BibleVerse @BibleId, 138014004, N'On that day his feet will stand on the Mount of Olives which lies to the east of Jerusalem, and the Mount of Olives will be split in half from east to west, leaving a great valley. Half the mountain will move northward and the other half southward.'
EXEC add_BibleVerse @BibleId, 138014005, N'Then you will escape through my mountain valley, for the mountains will extend to Azal. Indeed, you will flee as you fled from the earthquake in the days of King Uzziah of Judah. Then the Lord my God will come with all his holy ones with him.'
EXEC add_BibleVerse @BibleId, 138014006, N'On that day there will be no light – the sources of light in the heavens will congeal.'
EXEC add_BibleVerse @BibleId, 138014007, N'It will happen in one day (a day known to the Lord); not in the day or the night, but in the evening there will be light.'
EXEC add_BibleVerse @BibleId, 138014008, N'Moreover, on that day living waters will flow out from Jerusalem, half of them to the eastern sea and half of them to the western sea; it will happen both in summer and in winter.'
EXEC add_BibleVerse @BibleId, 138014009, N'The Lord will then be king over all the earth. In that day the Lord will be seen as one with a single name.'
EXEC add_BibleVerse @BibleId, 138014010, N'All the land will change and become like the Arabah from Geba to Rimmon, south of Jerusalem; and Jerusalem will be raised up and will stay in its own place from the Benjamin Gate to the site of the First Gate and on to the Corner Gate, and from the Tower of Hananel to the royal winepresses.'
EXEC add_BibleVerse @BibleId, 138014011, N'And people will settle there, and there will no longer be the threat of divine extermination – Jerusalem will dwell in security.'
EXEC add_BibleVerse @BibleId, 138014012, N'But this will be the nature of the plague with which the Lord will strike all the nations that have fought against Jerusalem: Their flesh will decay while they stand on their feet, their eyes will rot away in their sockets, and their tongues will dissolve in their mouths.'
EXEC add_BibleVerse @BibleId, 138014013, N'On that day there will be great confusion from the Lord among them; they will seize each other and attack one another violently.'
EXEC add_BibleVerse @BibleId, 138014014, N'Moreover, Judah will fight at Jerusalem, and the wealth of all the surrounding nations will be gathered up – gold, silver, and clothing in great abundance.'
EXEC add_BibleVerse @BibleId, 138014015, N'This is the kind of plague that will devastate horses, mules, camels, donkeys, and all the other animals in those camps.'
EXEC add_BibleVerse @BibleId, 138014016, N'Then all who survive from all the nations that came to attack Jerusalem will go up annually to worship the King, the Lord who rules over all, and to observe the Feast of Tabernacles.'
EXEC add_BibleVerse @BibleId, 138014017, N'But if any of the nations anywhere on earth refuse to go up to Jerusalem to worship the King, the Lord who rules over all, they will get no rain.'
EXEC add_BibleVerse @BibleId, 138014018, N'If the Egyptians will not do so, they will get no rain – instead there will be the kind of plague which the Lord inflicts on any nations that do not go up to celebrate the Feast of Tabernacles.'
EXEC add_BibleVerse @BibleId, 138014019, N'This will be the punishment of Egypt and of all nations that do not go up to celebrate the Feast of Tabernacles.'
EXEC add_BibleVerse @BibleId, 138014020, N'On that day the bells of the horses will bear the inscription “Holy to the Lord.” The cooking pots in the Lord’s temple will be as holy as the bowls in front of the altar.'
EXEC add_BibleVerse @BibleId, 138014021, N'Every cooking pot in Jerusalem and Judah will become holy in the sight of the Lord who rules over all, so that all who offer sacrifices may come and use some of them to boil their sacrifices in them. On that day there will no longer be a Canaanite in the house of the Lord who rules over all.'
EXEC add_BibleVerse @BibleId, 139001001, N'What follows is divine revelation. The word of the Lord came to Israel through Malachi:'
EXEC add_BibleVerse @BibleId, 139001002, N'“I have shown love to you,” says the Lord, but you say, “How have you shown love to us?” “Esau was Jacob’s brother,” the Lord explains, “yet I chose Jacob'
EXEC add_BibleVerse @BibleId, 139001003, N'and rejected Esau. I turned Esau’s mountains into a deserted wasteland and gave his territory to the wild jackals.”'
EXEC add_BibleVerse @BibleId, 139001004, N'Edom says, “Though we are devastated, we will once again build the ruined places.” So the Lord who rules over all responds, “They indeed may build, but I will overthrow. They will be known as the land of evil, the people with whom the Lord is permanently displeased.'
EXEC add_BibleVerse @BibleId, 139001005, N'Your eyes will see it, and then you will say, ‘May the Lord be magnified even beyond the border of Israel!’”'
EXEC add_BibleVerse @BibleId, 139001006, N'“A son naturally honors his father and a slave respects his master. If I am your father, where is my honor? If I am your master, where is my respect? The Lord who rules over all asks you this, you priests who make light of my name! But you reply, ‘How have we made light of your name?’'
EXEC add_BibleVerse @BibleId, 139001007, N'You are offering improper sacrifices on my altar, yet you ask, ‘How have we offended you?’ By treating the table of the Lord as if it is of no importance!'
EXEC add_BibleVerse @BibleId, 139001008, N'For when you offer blind animals as a sacrifice, is that not wrong? And when you offer the lame and sick, is that not wrong as well? Indeed, try offering them to your governor! Will he be pleased with you or show you favor?” asks the Lord who rules over all.'
EXEC add_BibleVerse @BibleId, 139001009, N'But now plead for God’s favor that he might be gracious to us. “With this kind of offering in your hands, how can he be pleased with you?” asks the Lord who rules over all.'
EXEC add_BibleVerse @BibleId, 139001010, N'“I wish that one of you would close the temple doors, so that you no longer would light useless fires on my altar. I am not pleased with you,” says the Lord who rules over all, “and I will no longer accept an offering from you.'
EXEC add_BibleVerse @BibleId, 139001011, N'For from the east to the west my name will be great among the nations. Incense and pure offerings will be offered in my name everywhere, for my name will be great among the nations,” says the Lord who rules over all.'
EXEC add_BibleVerse @BibleId, 139001012, N'“But you are profaning it by saying that the table of the Lord is common and its offerings despicable.'
EXEC add_BibleVerse @BibleId, 139001013, N'You also say, ‘How tiresome it is.’ You turn up your nose at it,” says the Lord who rules over all, “and instead bring what is stolen, lame, or sick. You bring these things for an offering! Should I accept this from you?” asks the Lord.'
EXEC add_BibleVerse @BibleId, 139001014, N'“There will be harsh condemnation for the hypocrite who has a valuable male animal in his flock but vows and sacrifices something inferior to the Lord. For I am a great king,” says the Lord who rules over all, “and my name is awesome among the nations.”'
EXEC add_BibleVerse @BibleId, 139002001, N'“Now, you priests, this commandment is for you.'
EXEC add_BibleVerse @BibleId, 139002002, N'If you do not listen and take seriously the need to honor my name,” says the Lord who rules over all, “I will send judgment on you and turn your blessings into curses – indeed, I have already done so because you are not taking it to heart.'
EXEC add_BibleVerse @BibleId, 139002003, N'I am about to discipline your children and will spread offal on your faces, the very offal produced at your festivals, and you will be carried away along with it.'
EXEC add_BibleVerse @BibleId, 139002004, N'Then you will know that I sent this commandment to you so that my covenant may continue to be with Levi,” says the Lord who rules over all.'
EXEC add_BibleVerse @BibleId, 139002005, N'“My covenant with him was designed to bring life and peace. I gave its statutes to him to fill him with awe, and he indeed revered me and stood in awe before me.'
EXEC add_BibleVerse @BibleId, 139002006, N'He taught what was true; sinful words were not found on his lips. He walked with me in peace and integrity, and he turned many people away from sin.'
EXEC add_BibleVerse @BibleId, 139002007, N'For the lips of a priest should preserve knowledge of sacred things, and people should seek instruction from him because he is the messenger of the Lord who rules over all.'
EXEC add_BibleVerse @BibleId, 139002008, N'You, however, have turned from the way. You have caused many to violate the law; you have corrupted the covenant with Levi,” says the Lord who rules over all.'
EXEC add_BibleVerse @BibleId, 139002009, N'“Therefore, I have caused you to be ignored and belittled before all people to the extent to which you are not following after me and are showing partiality in your instruction.”'
EXEC add_BibleVerse @BibleId, 139002010, N'Do we not all have one father? Did not one God create us? Why do we betray one another, in this way making light of the covenant of our ancestors?'
EXEC add_BibleVerse @BibleId, 139002011, N'Judah has become disloyal, and unspeakable sins have been committed in Israel and Jerusalem. For Judah has profaned the holy things that the Lord loves and has turned to a foreign god!'
EXEC add_BibleVerse @BibleId, 139002012, N'May the Lord cut off from the community of Jacob every last person who does this, as well as the person who presents improper offerings to the Lord who rules over all!'
EXEC add_BibleVerse @BibleId, 139002013, N'You also do this: You cover the altar of the Lord with tears as you weep and groan, because he no longer pays any attention to the offering nor accepts it favorably from you.'
EXEC add_BibleVerse @BibleId, 139002014, N'Yet you ask, “Why?” The Lord is testifying against you on behalf of the wife you married when you were young, to whom you have become unfaithful even though she is your companion and wife by law.'
EXEC add_BibleVerse @BibleId, 139002015, N'No one who has even a small portion of the Spirit in him does this. What did our ancestor do when seeking a child from God? Be attentive, then, to your own spirit, for one should not be disloyal to the wife he took in his youth.'
EXEC add_BibleVerse @BibleId, 139002016, N'“I hate divorce,” says the Lord God of Israel, “and the one who is guilty of violence,” says the Lord who rules over all. “Pay attention to your conscience, and do not be unfaithful.”'
EXEC add_BibleVerse @BibleId, 139002017, N'You have wearied the Lord with your words. But you say, “How have we wearied him?” Because you say, “Everyone who does evil is good in the Lord’s opinion, and he delights in them,” or “Where is the God of justice?”'
EXEC add_BibleVerse @BibleId, 139003001, N'“I am about to send my messenger, who will clear the way before me. Indeed, the Lord you are seeking will suddenly come to his temple, and the messenger of the covenant, whom you long for, is certainly coming,” says the Lord who rules over all.'
EXEC add_BibleVerse @BibleId, 139003002, N'Who can endure the day of his coming? Who can keep standing when he appears? For he will be like a refiner’s fire, like a launderer’s soap.'
EXEC add_BibleVerse @BibleId, 139003003, N'He will act like a refiner and purifier of silver and will cleanse the Levites and refine them like gold and silver. Then they will offer the Lord a proper offering.'
EXEC add_BibleVerse @BibleId, 139003004, N'The offerings of Judah and Jerusalem will be pleasing to the Lord as in former times and years past.'
EXEC add_BibleVerse @BibleId, 139003005, N'“I will come to you in judgment. I will be quick to testify against those who practice divination, those who commit adultery, those who break promises, and those who exploit workers, widows, and orphans, who refuse to help the immigrant and in this way show they do not fear me,” says the Lord who rules over all.'
EXEC add_BibleVerse @BibleId, 139003006, N'“Since, I, the Lord, do not go back on my promises, you, sons of Jacob, have not perished.'
EXEC add_BibleVerse @BibleId, 139003007, N'From the days of your ancestors you have ignored my commandments and have not kept them! Return to me, and I will return to you,” says the Lord who rules over all. “But you say, ‘How should we return?’'
EXEC add_BibleVerse @BibleId, 139003008, N'Can a person rob God? You indeed are robbing me, but you say, ‘How are we robbing you?’ In tithes and contributions!'
EXEC add_BibleVerse @BibleId, 139003009, N'You are bound for judgment because you are robbing me – this whole nation is guilty.'
EXEC add_BibleVerse @BibleId, 139003010, N'“Bring the entire tithe into the storehouse so that there may be food in my temple. Test me in this matter,” says the Lord who rules over all, “to see if I will not open for you the windows of heaven and pour out for you a blessing until there is no room for it all.'
EXEC add_BibleVerse @BibleId, 139003011, N'Then I will stop the plague from ruining your crops, and the vine will not lose its fruit before harvest,” says the Lord who rules over all.'
EXEC add_BibleVerse @BibleId, 139003012, N'“All nations will call you happy, for you indeed will live in a delightful land,” says the Lord who rules over all.'
EXEC add_BibleVerse @BibleId, 139003013, N'“You have criticized me sharply,” says the Lord, “but you ask, ‘How have we criticized you?’'
EXEC add_BibleVerse @BibleId, 139003014, N'You have said, ‘It is useless to serve God. How have we been helped by keeping his requirements and going about like mourners before the Lord who rules over all?'
EXEC add_BibleVerse @BibleId, 139003015, N'So now we consider the arrogant to be happy; indeed, those who practice evil are successful. In fact, those who challenge God escape!’”'
EXEC add_BibleVerse @BibleId, 139003016, N'Then those who respected the Lord spoke to one another, and the Lord took notice. A scroll was prepared before him in which were recorded the names of those who respected the Lord and honored his name.'
EXEC add_BibleVerse @BibleId, 139003017, N'“They will belong to me,” says the Lord who rules over all, “in the day when I prepare my own special property. I will spare them as a man spares his son who serves him.'
EXEC add_BibleVerse @BibleId, 139003018, N'Then once more you will see that I make a distinction between the righteous and the wicked, between the one who serves God and the one who does not.'
EXEC add_BibleVerse @BibleId, 139004001, N'“For indeed the day is coming, burning like a furnace, and all the arrogant evildoers will be chaff. The coming day will burn them up,” says the Lord who rules over all. “It will not leave even a root or branch.'
EXEC add_BibleVerse @BibleId, 139004002, N'But for you who respect my name, the sun of vindication will rise with healing wings, and you will skip about like calves released from the stall.'
EXEC add_BibleVerse @BibleId, 139004003, N'You will trample on the wicked, for they will be like ashes under the soles of your feet on the day which I am preparing,” says the Lord who rules over all.'
EXEC add_BibleVerse @BibleId, 139004004, N'“Remember the law of my servant Moses, to whom at Horeb I gave rules and regulations for all Israel to obey.'
EXEC add_BibleVerse @BibleId, 139004005, N'Look, I will send you Elijah the prophet before the great and terrible day of the Lord arrives.'
EXEC add_BibleVerse @BibleId, 139004006, N'He will encourage fathers and their children to return to me, so that I will not come and strike the earth with judgment.”'
EXEC add_BibleVerse @BibleId, 340001001, N'This is the record of the genealogy of Jesus Christ, the son of David, the son of Abraham.'
EXEC add_BibleVerse @BibleId, 340001002, N'Abraham was the father of Isaac, Isaac the father of Jacob, Jacob the father of Judah and his brothers,'
EXEC add_BibleVerse @BibleId, 340001003, N'Judah the father of Perez and Zerah (by Tamar), Perez the father of Hezron, Hezron the father of Ram,'
EXEC add_BibleVerse @BibleId, 340001004, N'Ram the father of Amminadab, Amminadab the father of Nahshon, Nahshon the father of Salmon,'
EXEC add_BibleVerse @BibleId, 340001005, N'Salmon the father of Boaz (by Rahab), Boaz the father of Obed (by Ruth), Obed the father of Jesse,'
EXEC add_BibleVerse @BibleId, 340001006, N'and Jesse the father of David the king. David was the father of Solomon (by the wife of Uriah ),'
EXEC add_BibleVerse @BibleId, 340001007, N'Solomon the father of Rehoboam, Rehoboam the father of Abijah, Abijah the father of Asa,'
EXEC add_BibleVerse @BibleId, 340001008, N'Asa the father of Jehoshaphat, Jehoshaphat the father of Joram, Joram the father of Uzziah,'
EXEC add_BibleVerse @BibleId, 340001009, N'Uzziah the father of Jotham, Jotham the father of Ahaz, Ahaz the father of Hezekiah,'
EXEC add_BibleVerse @BibleId, 340001010, N'Hezekiah the father of Manasseh, Manasseh the father of Amon, Amon the father of Josiah,'
EXEC add_BibleVerse @BibleId, 340001011, N'and Josiah the father of Jeconiah and his brothers, at the time of the deportation to Babylon.'
EXEC add_BibleVerse @BibleId, 340001012, N'After the deportation to Babylon, Jeconiah became the father of Shealtiel, Shealtiel the father of Zerubbabel,'
EXEC add_BibleVerse @BibleId, 340001013, N'Zerubbabel the father of Abiud, Abiud the father of Eliakim, Eliakim the father of Azor,'
EXEC add_BibleVerse @BibleId, 340001014, N'Azor the father of Zadok, Zadok the father of Achim, Achim the father of Eliud,'
EXEC add_BibleVerse @BibleId, 340001015, N'Eliud the father of Eleazar, Eleazar the father of Matthan, Matthan the father of Jacob,'
EXEC add_BibleVerse @BibleId, 340001016, N'and Jacob the father of Joseph, the husband of Mary, by whom Jesus was born, who is called Christ.'
EXEC add_BibleVerse @BibleId, 340001017, N'So all the generations from Abraham to David are fourteen generations, and from David to the deportation to Babylon, fourteen generations, and from the deportation to Babylon to Christ, fourteen generations.'
EXEC add_BibleVerse @BibleId, 340001018, N'Now the birth of Jesus Christ happened this way. While his mother Mary was engaged to Joseph, but before they came together, she was found to be pregnant through the Holy Spirit.'
EXEC add_BibleVerse @BibleId, 340001019, N'Because Joseph, her husband to be, was a righteous man, and because he did not want to disgrace her, he intended to divorce her privately.'
EXEC add_BibleVerse @BibleId, 340001020, N'When he had contemplated this, an angel of the Lord appeared to him in a dream and said, “Joseph, son of David, do not be afraid to take Mary as your wife, because the child conceived in her is from the Holy Spirit.'
EXEC add_BibleVerse @BibleId, 340001021, N'She will give birth to a son and you will name him Jesus, because he will save his people from their sins.”'
EXEC add_BibleVerse @BibleId, 340001022, N'This all happened so that what was spoken by the Lord through the prophet would be fulfilled:'
EXEC add_BibleVerse @BibleId, 340001023, N'“ Look! The virgin will conceive and bear a son, and they will call him Emmanuel,” which means “ God with us.”'
EXEC add_BibleVerse @BibleId, 340001024, N'When Joseph awoke from sleep he did what the angel of the Lord told him. He took his wife,'
EXEC add_BibleVerse @BibleId, 340001025, N'but did not have marital relations with her until she gave birth to a son, whom he named Jesus.'
EXEC add_BibleVerse @BibleId, 340002001, N'After Jesus was born in Bethlehem'
EXEC add_BibleVerse @BibleId, 340002002, N'saying, “Where is the one who is born king of the Jews? For we saw his star when it rose and have come to worship him.”'
EXEC add_BibleVerse @BibleId, 340002003, N'When King Herod heard this he was alarmed, and all Jerusalem with him.'
EXEC add_BibleVerse @BibleId, 340002004, N'After assembling all the chief priests and experts in the law, he asked them where the Christ was to be born.'
EXEC add_BibleVerse @BibleId, 340002005, N'“In Bethlehem of Judea,” they said, “for it is written this way by the prophet:'
EXEC add_BibleVerse @BibleId, 340002006, N'‘ And you, Bethlehem, in the land of Judah, are in no way least among the rulers of Judah, for out of you will come a ruler who will shepherd my people Israel.’”'
EXEC add_BibleVerse @BibleId, 340002007, N'Then Herod privately summoned the wise men and determined from them when the star had appeared.'
EXEC add_BibleVerse @BibleId, 340002008, N'He sent them to Bethlehem and said, “Go and look carefully for the child. When you find him, inform me so that I can go and worship him as well.”'
EXEC add_BibleVerse @BibleId, 340002009, N'After listening to the king they left, and once again the star they saw when it rose led them until it stopped above the place where the child was.'
EXEC add_BibleVerse @BibleId, 340002010, N'When they saw the star they shouted joyfully.'
EXEC add_BibleVerse @BibleId, 340002011, N'As they came into the house and saw the child with Mary his mother, they bowed down and worshiped him. They opened their treasure boxes and gave him gifts of gold, frankincense, and myrrh.'
EXEC add_BibleVerse @BibleId, 340002012, N'After being warned in a dream not to return to Herod, they went back by another route to their own country.'
EXEC add_BibleVerse @BibleId, 340002013, N'After they had gone, an angel of the Lord appeared to Joseph in a dream and said, “Get up, take the child and his mother and flee to Egypt, and stay there until I tell you, for Herod is going to look for the child to kill him.”'
EXEC add_BibleVerse @BibleId, 340002014, N'Then he got up, took the child and his mother during the night, and went to Egypt.'
EXEC add_BibleVerse @BibleId, 340002015, N'He stayed there until Herod died. In this way what was spoken by the Lord through the prophet was fulfilled : “I called my Son out of Egypt.”'
EXEC add_BibleVerse @BibleId, 340002016, N'When Herod saw that he had been tricked by the wise men, he became enraged. He sent men to kill all the children in Bethlehem and throughout the surrounding region from the age of two and under, according to the time he had learned from the wise men.'
EXEC add_BibleVerse @BibleId, 340002017, N'Then what was spoken by Jeremiah the prophet was fulfilled:'
EXEC add_BibleVerse @BibleId, 340002018, N'“ A voice was heard in Ramah, weeping and loud wailing, Rachel weeping for her children, and she did not want to be comforted, because they were gone.”'
EXEC add_BibleVerse @BibleId, 340002019, N'After Herod had died, an angel of the Lord appeared in a dream to Joseph in Egypt'
EXEC add_BibleVerse @BibleId, 340002020, N'saying, “Get up, take the child and his mother, and go to the land of Israel, for those who were seeking the child’s life are dead.”'
EXEC add_BibleVerse @BibleId, 340002021, N'So he got up and took the child and his mother and returned to the land of Israel.'
EXEC add_BibleVerse @BibleId, 340002022, N'But when he heard that Archelaus was reigning over Judea in place of his father Herod, he was afraid to go there. After being warned in a dream, he went to the regions of Galilee.'
EXEC add_BibleVerse @BibleId, 340002023, N'He came to a town called Nazareth and lived there. Then what had been spoken by the prophets was fulfilled, that Jesus would be called a Nazarene.'
EXEC add_BibleVerse @BibleId, 340003001, N'In those days John the Baptist came into the wilderness of Judea proclaiming,'
EXEC add_BibleVerse @BibleId, 340003002, N'“Repent, for the kingdom of heaven is near.”'
EXEC add_BibleVerse @BibleId, 340003003, N'For he is the one about whom Isaiah the prophet had spoken: “ The voice of one shouting in the wilderness, ‘ Prepare the way for the Lord, make his paths straight.’”'
EXEC add_BibleVerse @BibleId, 340003004, N'Now John wore clothing made from camel’s hair with a leather belt around his waist, and his diet consisted of locusts and wild honey.'
EXEC add_BibleVerse @BibleId, 340003005, N'Then people from Jerusalem, as well as all Judea and all the region around the Jordan, were going out to him,'
EXEC add_BibleVerse @BibleId, 340003006, N'and he was baptizing them in the Jordan River as they confessed their sins.'
EXEC add_BibleVerse @BibleId, 340003007, N'But when he saw many Pharisees and Sadducees coming to his baptism, he said to them, “You offspring of vipers! Who warned you to flee from the coming wrath?'
EXEC add_BibleVerse @BibleId, 340003008, N'Therefore produce fruit that proves your repentance,'
EXEC add_BibleVerse @BibleId, 340003009, N'and don’t think you can say to yourselves, ‘We have Abraham as our father.’ For I tell you that God can raise up children for Abraham from these stones!'
EXEC add_BibleVerse @BibleId, 340003010, N'Even now the ax is laid at the root of the trees, and every tree that does not produce good fruit will be cut down and thrown into the fire.'
EXEC add_BibleVerse @BibleId, 340003011, N'“I baptize you with water, for repentance, but the one coming after me is more powerful than I am – I am not worthy to carry his sandals. He will baptize you with the Holy Spirit and fire.'
EXEC add_BibleVerse @BibleId, 340003012, N'His winnowing fork is in his hand, and he will clean out his threshing floor and will gather his wheat into the storehouse, but the chaff he will burn up with inextinguishable fire.”'
EXEC add_BibleVerse @BibleId, 340003013, N'Then Jesus came from Galilee to John to be baptized by him in the Jordan River.'
EXEC add_BibleVerse @BibleId, 340003014, N'But John tried to prevent him, saying, “I need to be baptized by you, and yet you come to me?”'
EXEC add_BibleVerse @BibleId, 340003015, N'So Jesus replied to him, “Let it happen now, for it is right for us to fulfill all righteousness.” Then John yielded to him.'
EXEC add_BibleVerse @BibleId, 340003016, N'After Jesus was baptized, just as he was coming up out of the water, the heavens opened and he saw the Spirit of God descending like a dove and coming on him.'
EXEC add_BibleVerse @BibleId, 340003017, N'And a voice from heaven said, “This is my one dear Son; in him I take great delight.”'
EXEC add_BibleVerse @BibleId, 340004001, N'Then Jesus was led by the Spirit into the wilderness to be tempted by the devil.'
EXEC add_BibleVerse @BibleId, 340004002, N'After he fasted forty days and forty nights he was famished.'
EXEC add_BibleVerse @BibleId, 340004003, N'The tempter came and said to him, “If you are the Son of God, command these stones to become bread.”'
EXEC add_BibleVerse @BibleId, 340004004, N'But he answered, “It is written, ‘ Man does not live by bread alone, but by every word that comes from the mouth of God*.’”'
EXEC add_BibleVerse @BibleId, 340004005, N'Then the devil took him to the holy city, had him stand on the highest point of the temple,'
EXEC add_BibleVerse @BibleId, 340004006, N'and said to him, “If you are the Son of God, throw yourself down. For it is written, ‘ He will command his angels concerning you’ and ‘ with their hands they will lift you up, so that you will not strike your foot against a stone.’”'
EXEC add_BibleVerse @BibleId, 340004007, N'Jesus said to him, “Once again it is written: ‘ You are not to put the Lord your God to the test.’”'
EXEC add_BibleVerse @BibleId, 340004008, N'Again, the devil took him to a very high mountain, and showed him all the kingdoms of the world and their grandeur.'
EXEC add_BibleVerse @BibleId, 340004009, N'And he said to him, “I will give you all these things if you throw yourself to the ground and worship me.”'
EXEC add_BibleVerse @BibleId, 340004010, N'Then Jesus said to him, “Go away, Satan! For it is written: ‘ You are to worship the Lord your God and serve only him.’”'
EXEC add_BibleVerse @BibleId, 340004011, N'Then the devil left him, and angels came and began ministering to his needs.'
EXEC add_BibleVerse @BibleId, 340004012, N'Now when Jesus heard that John had been imprisoned, he went into Galilee.'
EXEC add_BibleVerse @BibleId, 340004013, N'While in Galilee, he moved from Nazareth by the sea, in the region of Zebulun and Naphtali,'
EXEC add_BibleVerse @BibleId, 340004014, N'so that what was spoken by Isaiah the prophet would be fulfilled:'
EXEC add_BibleVerse @BibleId, 340004015, N'“ Land of Zebulun and land of Naphtali, the way by the sea, beyond the Jordan, Galilee of the Gentiles –'
EXEC add_BibleVerse @BibleId, 340004016, N'the people who sit in darkness have seen a great light, and on those who sit in the region and shadow of death a light has dawned.”'
EXEC add_BibleVerse @BibleId, 340004017, N'From that time Jesus began to preach this message: “Repent, for the kingdom of heaven is near.”'
EXEC add_BibleVerse @BibleId, 340004018, N'As he was walking by the Sea of Galilee he saw two brothers, Simon (called Peter) and Andrew his brother, casting a net into the sea (for they were fishermen).'
EXEC add_BibleVerse @BibleId, 340004019, N'He said to them, “Follow me, and I will turn you into fishers of people.”'
EXEC add_BibleVerse @BibleId, 340004020, N'They left their nets immediately and followed him.'
EXEC add_BibleVerse @BibleId, 340004021, N'Going on from there he saw two other brothers, James the son of Zebedee and John his brother, in a boat with Zebedee their father, mending their nets. Then he called them.'
EXEC add_BibleVerse @BibleId, 340004022, N'They immediately left the boat and their father and followed him.'
EXEC add_BibleVerse @BibleId, 340004023, N'Jesus went throughout all of Galilee, teaching in their synagogues, preaching the gospel of the kingdom, and healing all kinds of disease and sickness among the people.'
EXEC add_BibleVerse @BibleId, 340004024, N'So a report about him spread throughout Syria. People brought to him all who suffered with various illnesses and afflictions, those who had seizures, paralytics, and those possessed by demons, and he healed them.'
EXEC add_BibleVerse @BibleId, 340004025, N'And large crowds followed him from Galilee, the Decapolis, Jerusalem, Judea, and beyond the Jordan River.'
EXEC add_BibleVerse @BibleId, 340005001, N'When he saw the crowds, he went up the mountain. After he sat down his disciples came to him.'
EXEC add_BibleVerse @BibleId, 340005002, N'Then he began to teach them by saying:'
EXEC add_BibleVerse @BibleId, 340005003, N'“Blessed are the poor in spirit, for the kingdom of heaven belongs to them.'
EXEC add_BibleVerse @BibleId, 340005004, N'“Blessed are those who mourn, for they will be comforted.'
EXEC add_BibleVerse @BibleId, 340005005, N'“Blessed are the meek, for they will inherit the earth.'
EXEC add_BibleVerse @BibleId, 340005006, N'“Blessed are those who hunger and thirst for righteousness, for they will be satisfied.'
EXEC add_BibleVerse @BibleId, 340005007, N'“Blessed are the merciful, for they will be shown mercy.'
EXEC add_BibleVerse @BibleId, 340005008, N'“Blessed are the pure in heart, for they will see God.'
EXEC add_BibleVerse @BibleId, 340005009, N'“Blessed are the peacemakers, for they will be called the children of God.'
EXEC add_BibleVerse @BibleId, 340005010, N'“Blessed are those who are persecuted for righteousness, for the kingdom of heaven belongs to them.'
EXEC add_BibleVerse @BibleId, 340005011, N'“Blessed are you when people insult you and persecute you and say all kinds of evil things about you falsely on account of me.'
EXEC add_BibleVerse @BibleId, 340005012, N'Rejoice and be glad because your reward is great in heaven, for they persecuted the prophets before you in the same way.'
EXEC add_BibleVerse @BibleId, 340005013, N'“You are the salt of the earth. But if salt loses its flavor, how can it be made salty again? It is no longer good for anything except to be thrown out and trampled on by people.'
EXEC add_BibleVerse @BibleId, 340005014, N'You are the light of the world. A city located on a hill cannot be hidden.'
EXEC add_BibleVerse @BibleId, 340005015, N'People do not light a lamp and put it under a basket but on a lampstand, and it gives light to all in the house.'
EXEC add_BibleVerse @BibleId, 340005016, N'In the same way, let your light shine before people, so that they can see your good deeds and give honor to your Father in heaven.'
EXEC add_BibleVerse @BibleId, 340005017, N'“Do not think that I have come to abolish the law or the prophets. I have not come to abolish these things but to fulfill them.'
EXEC add_BibleVerse @BibleId, 340005018, N'I tell you the truth, until heaven and earth pass away not the smallest letter or stroke of a letter will pass from the law until everything takes place.'
EXEC add_BibleVerse @BibleId, 340005019, N'So anyone who breaks one of the least of these commands and teaches others to do so will be called least in the kingdom of heaven, but whoever obeys them and teaches others to do so will be called great in the kingdom of heaven.'
EXEC add_BibleVerse @BibleId, 340005020, N'For I tell you, unless your righteousness goes beyond that of the experts in the law and the Pharisees, you will never enter the kingdom of heaven.'
EXEC add_BibleVerse @BibleId, 340005021, N'“You have heard that it was said to an older generation, ‘ Do not murder,’ and ‘whoever murders will be subjected to judgment.’'
EXEC add_BibleVerse @BibleId, 340005022, N'But I say to you that anyone who is angry with a brother will be subjected to judgment. And whoever insults a brother will be brought before the council, and whoever says ‘Fool’ will be sent to fiery hell.'
EXEC add_BibleVerse @BibleId, 340005023, N'So then, if you bring your gift to the altar and there remember that your brother has something against you,'
EXEC add_BibleVerse @BibleId, 340005024, N'leave your gift there in front of the altar. First go and be reconciled to your brother and then come and present your gift.'
EXEC add_BibleVerse @BibleId, 340005025, N'Reach agreement quickly with your accuser while on the way to court, or he may hand you over to the judge, and the judge hand you over to the warden, and you will be thrown into prison.'
EXEC add_BibleVerse @BibleId, 340005026, N'I tell you the truth, you will never get out of there until you have paid the last penny!'
EXEC add_BibleVerse @BibleId, 340005027, N'“You have heard that it was said, ‘ Do not commit adultery.’'
EXEC add_BibleVerse @BibleId, 340005028, N'But I say to you that whoever looks at a woman to desire her has already committed adultery with her in his heart.'
EXEC add_BibleVerse @BibleId, 340005029, N'If your right eye causes you to sin, tear it out and throw it away! It is better to lose one of your members than to have your whole body thrown into hell.'
EXEC add_BibleVerse @BibleId, 340005030, N'If your right hand causes you to sin, cut it off and throw it away! It is better to lose one of your members than to have your whole body go into hell.'
EXEC add_BibleVerse @BibleId, 340005031, N'“It was said, ‘ Whoever divorces his wife must give her a legal document.’'
EXEC add_BibleVerse @BibleId, 340005032, N'But I say to you that everyone who divorces his wife, except for immorality, makes her commit adultery, and whoever marries a divorced woman commits adultery.'
EXEC add_BibleVerse @BibleId, 340005033, N'“Again, you have heard that it was said to an older generation, ‘ Do not break an oath, but fulfill your vows to the Lord break an oath, but fulfill your vows to the Lord.’'
EXEC add_BibleVerse @BibleId, 340005034, N'But I say to you, do not take oaths at all – not by heaven, because it is the throne of God,'
EXEC add_BibleVerse @BibleId, 340005035, N'not by earth, because it is his footstool, and not by Jerusalem, because it is the city of the great King.'
EXEC add_BibleVerse @BibleId, 340005036, N'Do not take an oath by your head, because you are not able to make one hair white or black.'
EXEC add_BibleVerse @BibleId, 340005037, N'Let your word be ‘Yes, yes’ or ‘No, no.’ More than this is from the evil one.'
EXEC add_BibleVerse @BibleId, 340005038, N'“You have heard that it was said, ‘ An eye for an eye and a tooth for a tooth.’'
EXEC add_BibleVerse @BibleId, 340005039, N'But I say to you, do not resist the evildoer. But whoever strikes you on the right cheek, turn the other to him as well.'
EXEC add_BibleVerse @BibleId, 340005040, N'And if someone wants to sue you and to take your tunic, give him your coat also.'
EXEC add_BibleVerse @BibleId, 340005041, N'And if anyone forces you to go one mile, go with him two.'
EXEC add_BibleVerse @BibleId, 340005042, N'Give to the one who asks you, and do not reject the one who wants to borrow from you.'
EXEC add_BibleVerse @BibleId, 340005043, N'“You have heard that it was said, ‘ Love your neighbor’ and ‘hate your enemy.’'
EXEC add_BibleVerse @BibleId, 340005044, N'But I say to you, love your enemy and pray for those who persecute you,'
EXEC add_BibleVerse @BibleId, 340005045, N'so that you may be like your Father in heaven, since he causes the sun to rise on the evil and the good, and sends rain on the righteous and the unrighteous.'
EXEC add_BibleVerse @BibleId, 340005046, N'For if you love those who love you, what reward do you have? Even the tax collectors do the same, don’t they?'
EXEC add_BibleVerse @BibleId, 340005047, N'And if you only greet your brothers, what more do you do? Even the Gentiles do the same, don’t they?'
EXEC add_BibleVerse @BibleId, 340005048, N'So then, be perfect, as your heavenly Father is perfect.'
EXEC add_BibleVerse @BibleId, 340006001, N'“Be careful not to display your righteousness merely to be seen by people. Otherwise you have no reward with your Father in heaven.'
EXEC add_BibleVerse @BibleId, 340006002, N'Thus whenever you do charitable giving, do not blow a trumpet before you, as the hypocrites do in synagogues and on streets so that people will praise them. I tell you the truth, they have their reward.'
EXEC add_BibleVerse @BibleId, 340006003, N'But when you do your giving, do not let your left hand know what your right hand is doing,'
EXEC add_BibleVerse @BibleId, 340006004, N'so that your gift may be in secret. And your Father, who sees in secret, will reward you.'
EXEC add_BibleVerse @BibleId, 340006005, N'“Whenever you pray, do not be like the hypocrites, because they love to pray while standing in synagogues and on street corners so that people can see them. Truly I say to you, they have their reward.'
EXEC add_BibleVerse @BibleId, 340006006, N'But whenever you pray, go into your room, close the door, and pray to your Father in secret. And your Father, who sees in secret, will reward you.'
EXEC add_BibleVerse @BibleId, 340006007, N'When you pray, do not babble repetitiously like the Gentiles, because they think that by their many words they will be heard.'
EXEC add_BibleVerse @BibleId, 340006008, N'Do not be like them, for your Father knows what you need before you ask him.'
EXEC add_BibleVerse @BibleId, 340006009, N'So pray this way: Our Father in heaven, may your name be honored,'
EXEC add_BibleVerse @BibleId, 340006010, N'may your kingdom come, may your will be done on earth as it is in heaven.'
EXEC add_BibleVerse @BibleId, 340006011, N'Give us today our daily bread,'
EXEC add_BibleVerse @BibleId, 340006012, N'and forgive us our debts, as we ourselves have forgiven our debtors.'
EXEC add_BibleVerse @BibleId, 340006013, N'And do not lead us into temptation, but deliver us from the evil one.'
EXEC add_BibleVerse @BibleId, 340006014, N'“For if you forgive others their sins, your heavenly Father will also forgive you.'
EXEC add_BibleVerse @BibleId, 340006015, N'But if you do not forgive others, your Father will not forgive you your sins.'
EXEC add_BibleVerse @BibleId, 340006016, N'“When you fast, do not look sullen like the hypocrites, for they make their faces unattractive so that people will see them fasting. I tell you the truth, they have their reward.'
EXEC add_BibleVerse @BibleId, 340006017, N'When you fast, put oil on your head and wash your face,'
EXEC add_BibleVerse @BibleId, 340006018, N'so that it will not be obvious to others when you are fasting, but only to your Father who is in secret. And your Father, who sees in secret, will reward you.'
EXEC add_BibleVerse @BibleId, 340006019, N'“Do not accumulate for yourselves treasures on earth, where moth and rust destroy and where thieves break in and steal.'
EXEC add_BibleVerse @BibleId, 340006020, N'But accumulate for yourselves treasures in heaven, where moth and rust do not destroy, and thieves do not break in and steal.'
EXEC add_BibleVerse @BibleId, 340006021, N'For where your treasure is, there your heart will be also.'
EXEC add_BibleVerse @BibleId, 340006022, N'“The eye is the lamp of the body. If then your eye is healthy, your whole body will be full of light.'
EXEC add_BibleVerse @BibleId, 340006023, N'But if your eye is diseased, your whole body will be full of darkness. If then the light in you is darkness, how great is the darkness!'
EXEC add_BibleVerse @BibleId, 340006024, N'“No one can serve two masters, for either he will hate the one and love the other, or he will be devoted to the one and despise the other. You cannot serve God and money.'
EXEC add_BibleVerse @BibleId, 340006025, N'“Therefore I tell you, do not worry about your life, what you will eat or drink, or about your body, what you will wear. Isn’t there more to life than food and more to the body than clothing?'
EXEC add_BibleVerse @BibleId, 340006026, N'Look at the birds in the sky: They do not sow, or reap, or gather into barns, yet your heavenly Father feeds them. Aren’t you more valuable than they are?'
EXEC add_BibleVerse @BibleId, 340006027, N'And which of you by worrying can add even one hour to his life?'
EXEC add_BibleVerse @BibleId, 340006028, N'Why do you worry about clothing? Think about how the flowers of the field grow; they do not work or spin.'
EXEC add_BibleVerse @BibleId, 340006029, N'Yet I tell you that not even Solomon in all his glory was clothed like one of these!'
EXEC add_BibleVerse @BibleId, 340006030, N'And if this is how God clothes the wild grass, which is here today and tomorrow is tossed into the fire to heat the oven, won’t he clothe you even more, you people of little faith?'
EXEC add_BibleVerse @BibleId, 340006031, N'So then, don’t worry saying, ‘What will we eat?’ or ‘What will we drink?’ or ‘What will we wear?’'
EXEC add_BibleVerse @BibleId, 340006032, N'For the unconverted pursue these things, and your heavenly Father knows that you need them.'
EXEC add_BibleVerse @BibleId, 340006033, N'But above all pursue his kingdom and righteousness, and all these things will be given to you as well.'
EXEC add_BibleVerse @BibleId, 340006034, N'So then, do not worry about tomorrow, for tomorrow will worry about itself. Today has enough trouble of its own.'
EXEC add_BibleVerse @BibleId, 340007001, N'“Do not judge so that you will not be judged.'
EXEC add_BibleVerse @BibleId, 340007002, N'For by the standard you judge you will be judged, and the measure you use will be the measure you receive.'
EXEC add_BibleVerse @BibleId, 340007003, N'Why do you see the speck in your brother’s eye, but fail to see the beam of wood in your own?'
EXEC add_BibleVerse @BibleId, 340007004, N'Or how can you say to your brother, ‘Let me remove the speck from your eye,’ while there is a beam in your own?'
EXEC add_BibleVerse @BibleId, 340007005, N'You hypocrite! First remove the beam from your own eye, and then you can see clearly to remove the speck from your brother’s eye.'
EXEC add_BibleVerse @BibleId, 340007006, N'Do not give what is holy to dogs or throw your pearls before pigs; otherwise they will trample them under their feet and turn around and tear you to pieces.'
EXEC add_BibleVerse @BibleId, 340007007, N'“Ask and it will be given to you; seek and you will find; knock and the door will be opened for you.'
EXEC add_BibleVerse @BibleId, 340007008, N'For everyone who asks receives, and the one who seeks finds, and to the one who knocks, the door will be opened.'
EXEC add_BibleVerse @BibleId, 340007009, N'Is there anyone among you who, if his son asks for bread, will give him a stone?'
EXEC add_BibleVerse @BibleId, 340007010, N'Or if he asks for a fish, will give him a snake?'
EXEC add_BibleVerse @BibleId, 340007011, N'If you then, although you are evil, know how to give good gifts to your children, how much more will your Father in heaven give good gifts to those who ask him!'
EXEC add_BibleVerse @BibleId, 340007012, N'In everything, treat others as you would want them to treat you, for this fulfills the law and the prophets.'
EXEC add_BibleVerse @BibleId, 340007013, N'“Enter through the narrow gate, because the gate is wide and the way is spacious that leads to destruction, and there are many who enter through it.'
EXEC add_BibleVerse @BibleId, 340007014, N'But the gate is narrow and the way is difficult that leads to life, and there are few who find it.'
EXEC add_BibleVerse @BibleId, 340007015, N'“Watch out for false prophets, who come to you in sheep’s clothing but inwardly are voracious wolves.'
EXEC add_BibleVerse @BibleId, 340007016, N'You will recognize them by their fruit. Grapes are not gathered from thorns or figs from thistles, are they?'
EXEC add_BibleVerse @BibleId, 340007017, N'In the same way, every good tree bears good fruit, but the bad tree bears bad fruit.'
EXEC add_BibleVerse @BibleId, 340007018, N'A good tree is not able to bear bad fruit, nor a bad tree to bear good fruit.'
EXEC add_BibleVerse @BibleId, 340007019, N'Every tree that does not bear good fruit is cut down and thrown into the fire.'
EXEC add_BibleVerse @BibleId, 340007020, N'So then, you will recognize them by their fruit.'
EXEC add_BibleVerse @BibleId, 340007021, N'“Not everyone who says to me, ‘Lord, Lord,’ will enter into the kingdom of heaven – only the one who does the will of my Father in heaven.'
EXEC add_BibleVerse @BibleId, 340007022, N'On that day, many will say to me, ‘Lord, Lord, didn’t we prophesy in your name, and in your name cast out demons and do many powerful deeds?’'
EXEC add_BibleVerse @BibleId, 340007023, N'Then I will declare to them, ‘I never knew you. Go away from me, you lawbreakers!’'
EXEC add_BibleVerse @BibleId, 340007024, N'“Everyone who hears these words of mine and does them is like a wise man who built his house on rock.'
EXEC add_BibleVerse @BibleId, 340007025, N'The rain fell, the flood came, and the winds beat against that house, but it did not collapse because it had been founded on rock.'
EXEC add_BibleVerse @BibleId, 340007026, N'Everyone who hears these words of mine and does not do them is like a foolish man who built his house on sand.'
EXEC add_BibleVerse @BibleId, 340007027, N'The rain fell, the flood came, and the winds beat against that house, and it collapsed; it was utterly destroyed!”'
EXEC add_BibleVerse @BibleId, 340007028, N'When Jesus finished saying these things, the crowds were amazed by his teaching,'
EXEC add_BibleVerse @BibleId, 340007029, N'because he taught them like one who had authority, not like their experts in the law.'
EXEC add_BibleVerse @BibleId, 340008001, N'After he came down from the mountain, large crowds followed him.'
EXEC add_BibleVerse @BibleId, 340008002, N'And a leper approached, and bowed low before him, saying, “Lord, if you are willing, you can make me clean.”'
EXEC add_BibleVerse @BibleId, 340008003, N'He stretched out his hand and touched him saying, “I am willing. Be clean!” Immediately his leprosy was cleansed.'
EXEC add_BibleVerse @BibleId, 340008004, N'Then Jesus said to him, “See that you do not speak to anyone, but go, show yourself to a priest, and bring the offering that Moses commanded, as a testimony to them.”'
EXEC add_BibleVerse @BibleId, 340008005, N'When he entered Capernaum, a centurion came to him asking for help:'
EXEC add_BibleVerse @BibleId, 340008006, N'“Lord, my servant is lying at home paralyzed, in terrible anguish.”'
EXEC add_BibleVerse @BibleId, 340008007, N'Jesus said to him, “I will come and heal him.”'
EXEC add_BibleVerse @BibleId, 340008008, N'But the centurion replied, “Lord, I am not worthy to have you come under my roof. Instead, just say the word and my servant will be healed.'
EXEC add_BibleVerse @BibleId, 340008009, N'For I too am a man under authority, with soldiers under me. I say to this one, ‘Go’ and he goes, and to another ‘Come’ and he comes, and to my slave ‘Do this’ and he does it.”'
EXEC add_BibleVerse @BibleId, 340008010, N'When Jesus heard this he was amazed and said to those who followed him, “I tell you the truth, I have not found such faith in anyone in Israel!'
EXEC add_BibleVerse @BibleId, 340008011, N'I tell you, many will come from the east and west to share the banquet with Abraham, Isaac, and Jacob in the kingdom of heaven,'
EXEC add_BibleVerse @BibleId, 340008012, N'but the sons of the kingdom will be thrown out into the outer darkness, where there will be weeping and gnashing of teeth.”'
EXEC add_BibleVerse @BibleId, 340008013, N'Then Jesus said to the centurion, “Go; just as you believed, it will be done for you.” And the servant was healed at that hour.'
EXEC add_BibleVerse @BibleId, 340008014, N'Now when Jesus entered Peter’s house, he saw his mother-in-law lying down, sick with a fever.'
EXEC add_BibleVerse @BibleId, 340008015, N'He touched her hand, and the fever left her. Then she got up and began to serve them.'
EXEC add_BibleVerse @BibleId, 340008016, N'When it was evening, many demon-possessed people were brought to him. He drove out the spirits with a word, and healed all who were sick.'
EXEC add_BibleVerse @BibleId, 340008017, N'In this way what was spoken by Isaiah the prophet was fulfilled: “ He took our weaknesses and carried our diseases.”'
EXEC add_BibleVerse @BibleId, 340008018, N'Now when Jesus saw a large crowd around him, he gave orders to go to the other side of the lake.'
EXEC add_BibleVerse @BibleId, 340008019, N'Then an expert in the law came to him and said, “Teacher, I will follow you wherever you go.”'
EXEC add_BibleVerse @BibleId, 340008020, N'Jesus said to him, “Foxes have dens, and the birds in the sky have nests, but the Son of Man has no place to lay his head.”'
EXEC add_BibleVerse @BibleId, 340008021, N'Another of the disciples said to him, “Lord, let me first go and bury my father.”'
EXEC add_BibleVerse @BibleId, 340008022, N'But Jesus said to him, “Follow me, and let the dead bury their own dead.”'
EXEC add_BibleVerse @BibleId, 340008023, N'As he got into the boat, his disciples followed him.'
EXEC add_BibleVerse @BibleId, 340008024, N'And a great storm developed on the sea so that the waves began to swamp the boat. But he was asleep.'
EXEC add_BibleVerse @BibleId, 340008025, N'So they came and woke him up saying, “Lord, save us! We are about to die!”'
EXEC add_BibleVerse @BibleId, 340008026, N'But he said to them, “Why are you cowardly, you people of little faith?” Then he got up and rebuked the winds and the sea, and it was dead calm.'
EXEC add_BibleVerse @BibleId, 340008027, N'And the men were amazed and said, “What sort of person is this? Even the winds and the sea obey him!”'
EXEC add_BibleVerse @BibleId, 340008028, N'When he came to the other side, to the region of the Gadarenes, two demon-possessed men coming from the tombs met him. They were extremely violent, so that no one was able to pass by that way.'
EXEC add_BibleVerse @BibleId, 340008029, N'They cried out, “Son of God, leave us alone! Have you come here to torment us before the time?”'
EXEC add_BibleVerse @BibleId, 340008030, N'A large herd of pigs was feeding some distance from them.'
EXEC add_BibleVerse @BibleId, 340008031, N'Then the demons begged him, “If you drive us out, send us into the herd of pigs.”'
EXEC add_BibleVerse @BibleId, 340008032, N'And he said, “Go!” So they came out and went into the pigs, and the herd rushed down the steep slope into the lake and drowned in the water.'
EXEC add_BibleVerse @BibleId, 340008033, N'The herdsmen ran off, went into the town, and told everything that had happened to the demon-possessed men.'
EXEC add_BibleVerse @BibleId, 340008034, N'Then the entire town came out to meet Jesus. And when they saw him, they begged him to leave their region.'
EXEC add_BibleVerse @BibleId, 340009001, N'After getting into a boat he crossed to the other side and came to his own town.'
EXEC add_BibleVerse @BibleId, 340009002, N'Just then some people brought to him a paralytic lying on a stretcher. When Jesus saw their faith, he said to the paralytic, “Have courage, son! Your sins are forgiven.”'
EXEC add_BibleVerse @BibleId, 340009003, N'Then some of the experts in the law said to themselves, “This man is blaspheming!”'
EXEC add_BibleVerse @BibleId, 340009004, N'When Jesus saw their reaction he said, “Why do you respond with evil in your hearts?'
EXEC add_BibleVerse @BibleId, 340009005, N'Which is easier, to say, ‘Your sins are forgiven’ or to say, ‘Stand up and walk’?'
EXEC add_BibleVerse @BibleId, 340009006, N'But so that you may know that the Son of Man has authority on earth to forgive sins” – then he said to the paralytic – “Stand up, take your stretcher, and go home.”'
EXEC add_BibleVerse @BibleId, 340009007, N'And he stood up and went home.'
EXEC add_BibleVerse @BibleId, 340009008, N'When the crowd saw this, they were afraid and honored God who had given such authority to men.'
EXEC add_BibleVerse @BibleId, 340009009, N'As Jesus went on from there, he saw a man named Matthew sitting at the tax booth. “Follow me,” he said to him. And he got up and followed him.'
EXEC add_BibleVerse @BibleId, 340009010, N'As Jesus was having a meal in Matthew’s house, many tax collectors and sinners came and ate with Jesus and his disciples.'
EXEC add_BibleVerse @BibleId, 340009011, N'When the Pharisees saw this they said to his disciples, “Why does your teacher eat with tax collectors and sinners?”'
EXEC add_BibleVerse @BibleId, 340009012, N'When Jesus heard this he said, “Those who are healthy don’t need a physician, but those who are sick do.'
EXEC add_BibleVerse @BibleId, 340009013, N'Go and learn what this saying means: ‘ I want mercy and not sacrifice.’ For I did not come to call the righteous, but sinners.”'
EXEC add_BibleVerse @BibleId, 340009014, N'Then John’s disciples came to Jesus and asked, “Why do we and the Pharisees fast often, but your disciples don’t fast?”'
EXEC add_BibleVerse @BibleId, 340009015, N'Jesus said to them, “The wedding guests cannot mourn while the bridegroom is with them, can they? But the days are coming when the bridegroom will be taken from them, and then they will fast.'
EXEC add_BibleVerse @BibleId, 340009016, N'No one sews a patch of unshrunk cloth on an old garment, because the patch will pull away from the garment and the tear will be worse.'
EXEC add_BibleVerse @BibleId, 340009017, N'And no one pours new wine into old wineskins; otherwise the skins burst and the wine is spilled out and the skins are destroyed. Instead they put new wine into new wineskins and both are preserved.”'
EXEC add_BibleVerse @BibleId, 340009018, N'As he was saying these things, a ruler came, bowed low before him, and said, “My daughter has just died, but come and lay your hand on her and she will live.”'
EXEC add_BibleVerse @BibleId, 340009019, N'Jesus and his disciples got up and followed him.'
EXEC add_BibleVerse @BibleId, 340009020, N'But a woman who had been suffering from a hemorrhage for twelve years came up behind him and touched the edge of his cloak.'
EXEC add_BibleVerse @BibleId, 340009021, N'For she kept saying to herself, “If only I touch his cloak, I will be healed.”'
EXEC add_BibleVerse @BibleId, 340009022, N'But when Jesus turned and saw her he said, “Have courage, daughter! Your faith has made you well.” And the woman was healed from that hour.'
EXEC add_BibleVerse @BibleId, 340009023, N'When Jesus entered the ruler’s house and saw the flute players and the disorderly crowd,'
EXEC add_BibleVerse @BibleId, 340009024, N'he said, “Go away, for the girl is not dead but asleep.” And they began making fun of him.'
EXEC add_BibleVerse @BibleId, 340009025, N'But when the crowd had been put outside, he went in and gently took her by the hand, and the girl got up.'
EXEC add_BibleVerse @BibleId, 340009026, N'And the news of this spread throughout that region.'
EXEC add_BibleVerse @BibleId, 340009027, N'As Jesus went on from there, two blind men followed him, shouting, “Have mercy on us, Son of David!”'
EXEC add_BibleVerse @BibleId, 340009028, N'When he went into the house, the blind men came to him. Jesus said to them, “Do you believe that I am able to do this?” They said to him, “Yes, Lord.”'
EXEC add_BibleVerse @BibleId, 340009029, N'Then he touched their eyes saying, “Let it be done for you according to your faith.”'
EXEC add_BibleVerse @BibleId, 340009030, N'And their eyes were opened. Then Jesus sternly warned them, “See that no one knows about this.”'
EXEC add_BibleVerse @BibleId, 340009031, N'But they went out and spread the news about him throughout that entire region.'
EXEC add_BibleVerse @BibleId, 340009032, N'As they were going away, a man who could not talk and was demon-possessed was brought to him.'
EXEC add_BibleVerse @BibleId, 340009033, N'After the demon was cast out, the man who had been mute spoke. The crowds were amazed and said, “Never has anything like this been seen in Israel!”'
EXEC add_BibleVerse @BibleId, 340009034, N'But the Pharisees said, “By the ruler of demons he casts out demons.”'
EXEC add_BibleVerse @BibleId, 340009035, N'Then Jesus went throughout all the towns and villages, teaching in their synagogues, preaching the good news of the kingdom, and healing every kind of disease and sickness.'
EXEC add_BibleVerse @BibleId, 340009036, N'When he saw the crowds, he had compassion on them because they were bewildered and helpless, like sheep without a shepherd.'
EXEC add_BibleVerse @BibleId, 340009037, N'Then he said to his disciples, “The harvest is plentiful, but the workers are few.'
EXEC add_BibleVerse @BibleId, 340009038, N'Therefore ask the Lord of the harvest to send out workers into his harvest.”'
EXEC add_BibleVerse @BibleId, 340010001, N'Jesus called his twelve disciples and gave them authority over unclean spirits so they could cast them out and heal every kind of disease and sickness.'
EXEC add_BibleVerse @BibleId, 340010002, N'Now these are the names of the twelve apostles: first, Simon (called Peter), and Andrew his brother; James son of Zebedee and John his brother;'
EXEC add_BibleVerse @BibleId, 340010003, N'Philip and Bartholomew; Thomas and Matthew the tax collector; James the son of Alphaeus, and Thaddaeus;'
EXEC add_BibleVerse @BibleId, 340010004, N'Simon the Zealot and Judas Iscariot, who betrayed him.'
EXEC add_BibleVerse @BibleId, 340010005, N'Jesus sent out these twelve, instructing them as follows: “Do not go to Gentile regions and do not enter any Samaritan town.'
EXEC add_BibleVerse @BibleId, 340010006, N'Go instead to the lost sheep of the house of Israel.'
EXEC add_BibleVerse @BibleId, 340010007, N'As you go, preach this message: ‘The kingdom of heaven is near!’'
EXEC add_BibleVerse @BibleId, 340010008, N'Heal the sick, raise the dead, cleanse lepers, cast out demons. Freely you received, freely give.'
EXEC add_BibleVerse @BibleId, 340010009, N'Do not take gold, silver, or copper in your belts,'
EXEC add_BibleVerse @BibleId, 340010010, N'no bag for the journey, or an extra tunic, or sandals or staff, for the worker deserves his provisions.'
EXEC add_BibleVerse @BibleId, 340010011, N'Whenever you enter a town or village, find out who is worthy there and stay with them until you leave.'
EXEC add_BibleVerse @BibleId, 340010012, N'As you enter the house, give it greetings.'
EXEC add_BibleVerse @BibleId, 340010013, N'And if the house is worthy, let your peace come on it, but if it is not worthy, let your peace return to you.'
EXEC add_BibleVerse @BibleId, 340010014, N'And if anyone will not welcome you or listen to your message, shake the dust off your feet as you leave that house or that town.'
EXEC add_BibleVerse @BibleId, 340010015, N'I tell you the truth, it will be more bearable for the region of Sodom and Gomorrah on the day of judgment than for that town!'
EXEC add_BibleVerse @BibleId, 340010016, N'“I am sending you out like sheep surrounded by wolves, so be wise as serpents and innocent as doves.'
EXEC add_BibleVerse @BibleId, 340010017, N'Beware of people, because they will hand you over to councils and flog you in their synagogues.'
EXEC add_BibleVerse @BibleId, 340010018, N'And you will be brought before governors and kings because of me, as a witness to them and the Gentiles.'
EXEC add_BibleVerse @BibleId, 340010019, N'Whenever they hand you over for trial, do not worry about how to speak or what to say, for what you should say will be given to you at that time.'
EXEC add_BibleVerse @BibleId, 340010020, N'For it is not you speaking, but the Spirit of your Father speaking through you.'
EXEC add_BibleVerse @BibleId, 340010021, N'“Brother will hand over brother to death, and a father his child. Children will rise against parents and have them put to death.'
EXEC add_BibleVerse @BibleId, 340010022, N'And you will be hated by everyone because of my name. But the one who endures to the end will be saved.'
EXEC add_BibleVerse @BibleId, 340010023, N'Whenever they persecute you in one place, flee to another. I tell you the truth, you will not finish going through all the towns of Israel before the Son of Man comes.'
EXEC add_BibleVerse @BibleId, 340010024, N'“A disciple is not greater than his teacher, nor a slave greater than his master.'
EXEC add_BibleVerse @BibleId, 340010025, N'It is enough for the disciple to become like his teacher, and the slave like his master. If they have called the head of the house ‘Beelzebul,’ how much more will they defame the members of his household!'
EXEC add_BibleVerse @BibleId, 340010026, N'“Do not be afraid of them, for nothing is hidden that will not be revealed, and nothing is secret that will not be made known.'
EXEC add_BibleVerse @BibleId, 340010027, N'What I say to you in the dark, tell in the light, and what is whispered in your ear, proclaim from the housetops.'
EXEC add_BibleVerse @BibleId, 340010028, N'Do not be afraid of those who kill the body but cannot kill the soul. Instead, fear the one who is able to destroy both soul and body in hell.'
EXEC add_BibleVerse @BibleId, 340010029, N'Aren’t two sparrows sold for a penny? Yet not one of them falls to the ground apart from your Father’s will.'
EXEC add_BibleVerse @BibleId, 340010030, N'Even all the hairs on your head are numbered.'
EXEC add_BibleVerse @BibleId, 340010031, N'So do not be afraid; you are more valuable than many sparrows.'
EXEC add_BibleVerse @BibleId, 340010032, N'“Whoever, then, acknowledges me before people, I will acknowledge before my Father in heaven.'
EXEC add_BibleVerse @BibleId, 340010033, N'But whoever denies me before people, I will deny him also before my Father in heaven.'
EXEC add_BibleVerse @BibleId, 340010034, N'“Do not think that I have come to bring peace to the earth. I have not come to bring peace but a sword.'
EXEC add_BibleVerse @BibleId, 340010035, N'For I have come to set a man against his father, a daughter against her mother, and a daughter-in-law against her mother-in-law,'
EXEC add_BibleVerse @BibleId, 340010036, N'and a man’s enemies will be the members of his household.'
EXEC add_BibleVerse @BibleId, 340010037, N'“Whoever loves father or mother more than me is not worthy of me, and whoever loves son or daughter more than me is not worthy of me.'
EXEC add_BibleVerse @BibleId, 340010038, N'And whoever does not take up his cross and follow me is not worthy of me.'
EXEC add_BibleVerse @BibleId, 340010039, N'Whoever finds his life will lose it, and whoever loses his life because of me will find it.'
EXEC add_BibleVerse @BibleId, 340010040, N'“Whoever receives you receives me, and whoever receives me receives the one who sent me.'
EXEC add_BibleVerse @BibleId, 340010041, N'Whoever receives a prophet in the name of a prophet will receive a prophet’s reward. Whoever receives a righteous person in the name of a righteous person will receive a righteous person’s reward.'
EXEC add_BibleVerse @BibleId, 340010042, N'And whoever gives only a cup of cold water to one of these little ones in the name of a disciple, I tell you the truth, he will never lose his reward.”'
EXEC add_BibleVerse @BibleId, 340011001, N'When Jesus had finished instructing his twelve disciples, he went on from there to teach and preach in their towns.'
EXEC add_BibleVerse @BibleId, 340011002, N'Now when John heard in prison about the deeds Christ had done, he sent his disciples to ask a question:'
EXEC add_BibleVerse @BibleId, 340011003, N'“Are you the one who is to come, or should we look for another?”'
EXEC add_BibleVerse @BibleId, 340011004, N'Jesus answered them, “Go tell John what you hear and see:'
EXEC add_BibleVerse @BibleId, 340011005, N'The blind see, the lame walk, lepers are cleansed, the deaf hear, the dead are raised, and the poor have good news proclaimed to them.'
EXEC add_BibleVerse @BibleId, 340011006, N'Blessed is anyone who takes no offense at me.”'
EXEC add_BibleVerse @BibleId, 340011007, N'While they were going away, Jesus began to speak to the crowd about John: “What did you go out into the wilderness to see? A reed shaken by the wind?'
EXEC add_BibleVerse @BibleId, 340011008, N'What did you go out to see? A man dressed in fancy clothes? Look, those who wear fancy clothes are in the homes of kings!'
EXEC add_BibleVerse @BibleId, 340011009, N'What did you go out to see? A prophet? Yes, I tell you, and more than a prophet.'
EXEC add_BibleVerse @BibleId, 340011010, N'This is the one about whom it is written: ‘ Look, I am sending my messenger ahead of you, who will prepare your way before you.’'
EXEC add_BibleVerse @BibleId, 340011011, N'“I tell you the truth, among those born of women, no one has arisen greater than John the Baptist. Yet the one who is least in the kingdom of heaven is greater than he is.'
EXEC add_BibleVerse @BibleId, 340011012, N'From the days of John the Baptist until now the kingdom of heaven has suffered violence, and forceful people lay hold of it.'
EXEC add_BibleVerse @BibleId, 340011013, N'For all the prophets and the law prophesied until John appeared.'
EXEC add_BibleVerse @BibleId, 340011014, N'And if you are willing to accept it, he is Elijah, who is to come.'
EXEC add_BibleVerse @BibleId, 340011015, N'The one who has ears had better listen!'
EXEC add_BibleVerse @BibleId, 340011016, N'“To what should I compare this generation? They are like children sitting in the marketplaces who call out to one another,'
EXEC add_BibleVerse @BibleId, 340011017, N'‘We played the flute for you, yet you did not dance; we wailed in mourning, yet you did not weep.’'
EXEC add_BibleVerse @BibleId, 340011018, N'For John came neither eating nor drinking, and they say, ‘He has a demon!’'
EXEC add_BibleVerse @BibleId, 340011019, N'The Son of Man came eating and drinking, and they say, ‘Look at him, a glutton and a drunk, a friend of tax collectors and sinners!’ But wisdom is vindicated by her deeds.”'
EXEC add_BibleVerse @BibleId, 340011020, N'Then Jesus began to criticize openly the cities in which he had done many of his miracles, because they did not repent.'
EXEC add_BibleVerse @BibleId, 340011021, N'“Woe to you, Chorazin! Woe to you, Bethsaida! If the miracles done in you had been done in Tyre they would have repented long ago in sackcloth and ashes.'
EXEC add_BibleVerse @BibleId, 340011022, N'But I tell you, it will be more bearable for Tyre and Sidon on the day of judgment than for you!'
EXEC add_BibleVerse @BibleId, 340011023, N'And you, Capernaum, will you be exalted to heaven? No, you will be thrown down to Hades! For if the miracles done among you had been done in Sodom, it would have continued to this day.'
EXEC add_BibleVerse @BibleId, 340011024, N'But I tell you, it will be more bearable for the region of Sodom on the day of judgment than for you!”'
EXEC add_BibleVerse @BibleId, 340011025, N'At that time Jesus said, “I praise you, Father, Lord of heaven and earth, because you have hidden these things from the wise and intelligent, and revealed them to little children.'
EXEC add_BibleVerse @BibleId, 340011026, N'Yes, Father, for this was your gracious will.'
EXEC add_BibleVerse @BibleId, 340011027, N'All things have been handed over to me by my Father. No one knows the Son except the Father, and no one knows the Father except the Son and anyone to whom the Son decides to reveal him.'
EXEC add_BibleVerse @BibleId, 340011028, N'Come to me, all you who are weary and burdened, and I will give you rest.'
EXEC add_BibleVerse @BibleId, 340011029, N'Take my yoke on you and learn from me, because I am gentle and humble in heart, and you will find rest for your souls.'
EXEC add_BibleVerse @BibleId, 340011030, N'For my yoke is easy to bear, and my load is not hard to carry.”'
EXEC add_BibleVerse @BibleId, 340012001, N'At that time Jesus went through the grain fields on a Sabbath. His disciples were hungry, and they began to pick heads of wheat and eat them.'
EXEC add_BibleVerse @BibleId, 340012002, N'But when the Pharisees saw this they said to him, “Look, your disciples are doing what is against the law to do on the Sabbath.”'
EXEC add_BibleVerse @BibleId, 340012003, N'He said to them, “Haven’t you read what David did when he and his companions were hungry –'
EXEC add_BibleVerse @BibleId, 340012004, N'how he entered the house of God and they ate the sacred bread, which was against the law for him or his companions to eat, but only for the priests?'
EXEC add_BibleVerse @BibleId, 340012005, N'Or have you not read in the law that the priests in the temple desecrate the Sabbath and yet are not guilty?'
EXEC add_BibleVerse @BibleId, 340012006, N'I tell you that something greater than the temple is here.'
EXEC add_BibleVerse @BibleId, 340012007, N'If you had known what this means: ‘ I want mercy and not sacrifice,’ you would not have condemned the innocent.'
EXEC add_BibleVerse @BibleId, 340012008, N'For the Son of Man is lord of the Sabbath.”'
EXEC add_BibleVerse @BibleId, 340012009, N'Then Jesus left that place and entered their synagogue.'
EXEC add_BibleVerse @BibleId, 340012010, N'A man was there who had a withered hand. And they asked Jesus, “Is it lawful to heal on the Sabbath?” so that they could accuse him.'
EXEC add_BibleVerse @BibleId, 340012011, N'He said to them, “Would not any one of you, if he had one sheep that fell into a pit on the Sabbath, take hold of it and lift it out?'
EXEC add_BibleVerse @BibleId, 340012012, N'How much more valuable is a person than a sheep! So it is lawful to do good on the Sabbath.”'
EXEC add_BibleVerse @BibleId, 340012013, N'Then he said to the man, “Stretch out your hand.” He stretched it out and it was restored, as healthy as the other.'
EXEC add_BibleVerse @BibleId, 340012014, N'But the Pharisees went out and plotted against him, as to how they could assassinate him.'
EXEC add_BibleVerse @BibleId, 340012015, N'Now when Jesus learned of this, he went away from there. Great crowds followed him, and he healed them all.'
EXEC add_BibleVerse @BibleId, 340012016, N'But he sternly warned them not to make him known.'
EXEC add_BibleVerse @BibleId, 340012017, N'This fulfilled what was spoken by Isaiah the prophet:'
EXEC add_BibleVerse @BibleId, 340012018, N'“ Here is my servant whom I have chosen, the one I love, in whom I take great delight. I will put my Spirit on him, and he will proclaim justice to the nations.'
EXEC add_BibleVerse @BibleId, 340012019, N'He will not quarrel or cry out, nor will anyone hear his voice in the streets.'
EXEC add_BibleVerse @BibleId, 340012020, N'He will not break a bruised reed or extinguish a smoldering wick, until he brings justice to victory.'
EXEC add_BibleVerse @BibleId, 340012021, N'And in his name the Gentiles will hope.”'
EXEC add_BibleVerse @BibleId, 340012022, N'Then they brought to him a demon-possessed man who was blind and mute. Jesus healed him so that he could speak and see.'
EXEC add_BibleVerse @BibleId, 340012023, N'All the crowds were amazed and said, “Could this one be the Son of David?”'
EXEC add_BibleVerse @BibleId, 340012024, N'But when the Pharisees heard this they said, “He does not cast out demons except by the power of Beelzebul, the ruler of demons!”'
EXEC add_BibleVerse @BibleId, 340012025, N'Now when Jesus realized what they were thinking, he said to them, “Every kingdom divided against itself is destroyed, and no town or house divided against itself will stand.'
EXEC add_BibleVerse @BibleId, 340012026, N'So if Satan casts out Satan, he is divided against himself. How then will his kingdom stand?'
EXEC add_BibleVerse @BibleId, 340012027, N'And if I cast out demons by Beelzebul, by whom do your sons cast them out? For this reason they will be your judges.'
EXEC add_BibleVerse @BibleId, 340012028, N'But if I cast out demons by the Spirit of God, then the kingdom of God has already overtaken you.'
EXEC add_BibleVerse @BibleId, 340012029, N'How else can someone enter a strong man’s house and steal his property, unless he first ties up the strong man? Then he can thoroughly plunder the house.'
EXEC add_BibleVerse @BibleId, 340012030, N'Whoever is not with me is against me, and whoever does not gather with me scatters.'
EXEC add_BibleVerse @BibleId, 340012031, N'For this reason I tell you, people will be forgiven for every sin and blasphemy, but the blasphemy against the Spirit will not be forgiven.'
EXEC add_BibleVerse @BibleId, 340012032, N'Whoever speaks a word against the Son of Man will be forgiven. But whoever speaks against the Holy Spirit will not be forgiven, either in this age or in the age to come.'
EXEC add_BibleVerse @BibleId, 340012033, N'“Make a tree good and its fruit will be good, or make a tree bad and its fruit will be bad, for a tree is known by its fruit.'
EXEC add_BibleVerse @BibleId, 340012034, N'Offspring of vipers! How are you able to say anything good, since you are evil? For the mouth speaks from what fills the heart.'
EXEC add_BibleVerse @BibleId, 340012035, N'The good person brings good things out of his good treasury, and the evil person brings evil things out of his evil treasury.'
EXEC add_BibleVerse @BibleId, 340012036, N'I tell you that on the day of judgment, people will give an account for every worthless word they speak.'
EXEC add_BibleVerse @BibleId, 340012037, N'For by your words you will be justified, and by your words you will be condemned.”'
EXEC add_BibleVerse @BibleId, 340012038, N'Then some of the experts in the law along with some Pharisees answered him, “Teacher, we want to see a sign from you.”'
EXEC add_BibleVerse @BibleId, 340012039, N'But he answered them, “An evil and adulterous generation asks for a sign, but no sign will be given to it except the sign of the prophet Jonah.'
EXEC add_BibleVerse @BibleId, 340012040, N'For just as Jonah was in the belly of the huge fish for three days and three nights, so the Son of Man will be in the heart of the earth for three days and three nights.'
EXEC add_BibleVerse @BibleId, 340012041, N'The people of Nineveh will stand up at the judgment with this generation and condemn it, because they repented when Jonah preached to them – and now, something greater than Jonah is here!'
EXEC add_BibleVerse @BibleId, 340012042, N'The queen of the South will rise up at the judgment with this generation and condemn it, because she came from the ends of the earth to hear the wisdom of Solomon – and now, something greater than Solomon is here!'
EXEC add_BibleVerse @BibleId, 340012043, N'“When an unclean spirit goes out of a person, it passes through waterless places looking for rest but does not find it.'
EXEC add_BibleVerse @BibleId, 340012044, N'Then it says, ‘I will return to the home I left.’ When it returns, it finds the house empty, swept clean, and put in order.'
EXEC add_BibleVerse @BibleId, 340012045, N'Then it goes and brings with it seven other spirits more evil than itself, and they go in and live there, so the last state of that person is worse than the first. It will be that way for this evil generation as well!”'
EXEC add_BibleVerse @BibleId, 340012046, N'While Jesus was still speaking to the crowds, his mother and brothers came and stood outside, asking to speak to him.'
EXEC add_BibleVerse @BibleId, 340012047, N'Someone told him, “Look, your mother and your brothers are standing outside wanting to speak to you.”'
EXEC add_BibleVerse @BibleId, 340012048, N'To the one who had said this, Jesus replied, “Who is my mother and who are my brothers?”'
EXEC add_BibleVerse @BibleId, 340012049, N'And pointing toward his disciples he said, “Here are my mother and my brothers!'
EXEC add_BibleVerse @BibleId, 340012050, N'For whoever does the will of my Father in heaven is my brother and sister and mother.”'
EXEC add_BibleVerse @BibleId, 340013001, N'On that day after Jesus went out of the house, he sat by the lake.'
EXEC add_BibleVerse @BibleId, 340013002, N'And such a large crowd gathered around him that he got into a boat to sit while the whole crowd stood on the shore.'
EXEC add_BibleVerse @BibleId, 340013003, N'He told them many things in parables, saying: “Listen! A sower went out to sow.'
EXEC add_BibleVerse @BibleId, 340013004, N'And as he sowed, some seeds fell along the path, and the birds came and devoured them.'
EXEC add_BibleVerse @BibleId, 340013005, N'Other seeds fell on rocky ground where they did not have much soil. They sprang up quickly because the soil was not deep.'
EXEC add_BibleVerse @BibleId, 340013006, N'But when the sun came up, they were scorched, and because they did not have sufficient root, they withered.'
EXEC add_BibleVerse @BibleId, 340013007, N'Other seeds fell among the thorns, and they grew up and choked them.'
EXEC add_BibleVerse @BibleId, 340013008, N'But other seeds fell on good soil and produced grain, some a hundred times as much, some sixty, and some thirty.'
EXEC add_BibleVerse @BibleId, 340013009, N'The one who has ears had better listen!”'
EXEC add_BibleVerse @BibleId, 340013010, N'Then the disciples came to him and said, “Why do you speak to them in parables?”'
EXEC add_BibleVerse @BibleId, 340013011, N'He replied, “You have been given the opportunity to know the secrets of the kingdom of heaven, but they have not.'
EXEC add_BibleVerse @BibleId, 340013012, N'For whoever has will be given more, and will have an abundance. But whoever does not have, even what he has will be taken from him.'
EXEC add_BibleVerse @BibleId, 340013013, N'For this reason I speak to them in parables: Although they see they do not see, and although they hear they do not hear nor do they understand.'
EXEC add_BibleVerse @BibleId, 340013014, N'And concerning them the prophecy of Isaiah is fulfilled that says: ‘ You will listen carefully yet will never understand, you will look closely yet will never comprehend.'
EXEC add_BibleVerse @BibleId, 340013015, N'For the heart of this people has become dull; they are hard of hearing, and they have shut their eyes, so that they would not see with their eyes and hear with their ears and understand with their hearts and turn, and I would heal them.’'
EXEC add_BibleVerse @BibleId, 340013016, N'“But your eyes are blessed because they see, and your ears because they hear.'
EXEC add_BibleVerse @BibleId, 340013017, N'For I tell you the truth, many prophets and righteous people longed to see what you see but did not see it, and to hear what you hear but did not hear it.'
EXEC add_BibleVerse @BibleId, 340013018, N'“So listen to the parable of the sower:'
EXEC add_BibleVerse @BibleId, 340013019, N'When anyone hears the word about the kingdom and does not understand it, the evil one comes and snatches what was sown in his heart; this is the seed sown along the path.'
EXEC add_BibleVerse @BibleId, 340013020, N'The seed sown on rocky ground is the person who hears the word and immediately receives it with joy.'
EXEC add_BibleVerse @BibleId, 340013021, N'But he has no root in himself and does not endure; when trouble or persecution comes because of the word, immediately he falls away.'
EXEC add_BibleVerse @BibleId, 340013022, N'The seed sown among thorns is the person who hears the word, but worldly cares and the seductiveness of wealth choke the word, so it produces nothing.'
EXEC add_BibleVerse @BibleId, 340013023, N'But as for the seed sown on good soil, this is the person who hears the word and understands. He bears fruit, yielding a hundred, sixty, or thirty times what was sown.”'
EXEC add_BibleVerse @BibleId, 340013024, N'He presented them with another parable: “The kingdom of heaven is like a person who sowed good seed in his field.'
EXEC add_BibleVerse @BibleId, 340013025, N'But while everyone was sleeping, an enemy came and sowed weeds among the wheat and went away.'
EXEC add_BibleVerse @BibleId, 340013026, N'When the plants sprouted and bore grain, then the weeds also appeared.'
EXEC add_BibleVerse @BibleId, 340013027, N'So the slaves of the owner came and said to him, ‘Sir, didn’t you sow good seed in your field? Then where did the weeds come from?’'
EXEC add_BibleVerse @BibleId, 340013028, N'He said, ‘An enemy has done this.’ So the slaves replied, ‘Do you want us to go and gather them?’'
EXEC add_BibleVerse @BibleId, 340013029, N'But he said, ‘No, since in gathering the weeds you may uproot the wheat with them.'
EXEC add_BibleVerse @BibleId, 340013030, N'Let both grow together until the harvest. At harvest time I will tell the reapers, “First collect the weeds and tie them in bundles to be burned, but then gather the wheat into my barn.”’”'
EXEC add_BibleVerse @BibleId, 340013031, N'He gave them another parable: “The kingdom of heaven is like a mustard seed that a man took and sowed in his field.'
EXEC add_BibleVerse @BibleId, 340013032, N'It is the smallest of all the seeds, but when it has grown it is the greatest garden plant and becomes a tree, so that the wild birds come and nest in its branches.”'
EXEC add_BibleVerse @BibleId, 340013033, N'He told them another parable: “The kingdom of heaven is like yeast that a woman took and mixed with three measures of flour until all the dough had risen.”'
EXEC add_BibleVerse @BibleId, 340013034, N'Jesus spoke all these things in parables to the crowds; he did not speak to them without a parable.'
EXEC add_BibleVerse @BibleId, 340013035, N'This fulfilled what was spoken by the prophet: “ I will open my mouth in parables, I will announce what has been hidden from the foundation of the world.”'
EXEC add_BibleVerse @BibleId, 340013036, N'Then he left the crowds and went into the house. And his disciples came to him saying, “Explain to us the parable of the weeds in the field.”'
EXEC add_BibleVerse @BibleId, 340013037, N'He answered, “The one who sowed the good seed is the Son of Man.'
EXEC add_BibleVerse @BibleId, 340013038, N'The field is the world and the good seed are the people of the kingdom. The weeds are the people of the evil one,'
EXEC add_BibleVerse @BibleId, 340013039, N'and the enemy who sows them is the devil. The harvest is the end of the age, and the reapers are angels.'
EXEC add_BibleVerse @BibleId, 340013040, N'As the weeds are collected and burned with fire, so it will be at the end of the age.'
EXEC add_BibleVerse @BibleId, 340013041, N'The Son of Man will send his angels, and they will gather from his kingdom everything that causes sin as well as all lawbreakers.'
EXEC add_BibleVerse @BibleId, 340013042, N'They will throw them into the fiery furnace, where there will be weeping and gnashing of teeth.'
EXEC add_BibleVerse @BibleId, 340013043, N'Then the righteous will shine like the sun in the kingdom of their Father. The one who has ears had better listen!'
EXEC add_BibleVerse @BibleId, 340013044, N'“The kingdom of heaven is like a treasure, hidden in a field, that a person found and hid. Then because of joy he went and sold all that he had and bought that field.'
EXEC add_BibleVerse @BibleId, 340013045, N'“Again, the kingdom of heaven is like a merchant searching for fine pearls.'
EXEC add_BibleVerse @BibleId, 340013046, N'When he found a pearl of great value, he went out and sold everything he had and bought it.'
EXEC add_BibleVerse @BibleId, 340013047, N'“Again, the kingdom of heaven is like a net that was cast into the sea that caught all kinds of fish.'
EXEC add_BibleVerse @BibleId, 340013048, N'When it was full, they pulled it ashore, sat down, and put the good fish into containers and threw the bad away.'
EXEC add_BibleVerse @BibleId, 340013049, N'It will be this way at the end of the age. Angels will come and separate the evil from the righteous'
EXEC add_BibleVerse @BibleId, 340013050, N'and throw them into the fiery furnace, where there will be weeping and gnashing of teeth.'
EXEC add_BibleVerse @BibleId, 340013051, N'“Have you understood all these things?” They replied, “Yes.”'
EXEC add_BibleVerse @BibleId, 340013052, N'Then he said to them, “Therefore every expert in the law who has been trained for the kingdom of heaven is like the owner of a house who brings out of his treasure what is new and old.”'
EXEC add_BibleVerse @BibleId, 340013053, N'Now when Jesus finished these parables, he moved on from there.'
EXEC add_BibleVerse @BibleId, 340013054, N'Then he came to his hometown and began to teach the people in their synagogue. They were astonished and said, “Where did this man get such wisdom and miraculous powers?'
EXEC add_BibleVerse @BibleId, 340013055, N'Isn’t this the carpenter’s son? Isn’t his mother named Mary? And aren’t his brothers James, Joseph, Simon, and Judas?'
EXEC add_BibleVerse @BibleId, 340013056, N'And aren’t all his sisters here with us? Where did he get all this?”'
EXEC add_BibleVerse @BibleId, 340013057, N'And so they took offense at him. But Jesus said to them, “A prophet is not without honor except in his hometown and in his own house.”'
EXEC add_BibleVerse @BibleId, 340013058, N'And he did not do many miracles there because of their unbelief.'
EXEC add_BibleVerse @BibleId, 340014001, N'At that time Herod the tetrarch heard reports about Jesus,'
EXEC add_BibleVerse @BibleId, 340014002, N'and he said to his servants, “This is John the Baptist. He has been raised from the dead! And because of this, miraculous powers are at work in him.”'
EXEC add_BibleVerse @BibleId, 340014003, N'For Herod had arrested John, bound him, and put him in prison on account of Herodias, his brother Philip’s wife,'
EXEC add_BibleVerse @BibleId, 340014004, N'because John had repeatedly told him, “It is not lawful for you to have her.”'
EXEC add_BibleVerse @BibleId, 340014005, N'Although Herod wanted to kill John, he feared the crowd because they accepted John as a prophet.'
EXEC add_BibleVerse @BibleId, 340014006, N'But on Herod’s birthday, the daughter of Herodias danced before them and pleased Herod,'
EXEC add_BibleVerse @BibleId, 340014007, N'so much that he promised with an oath to give her whatever she asked.'
EXEC add_BibleVerse @BibleId, 340014008, N'Instructed by her mother, she said, “Give me the head of John the Baptist here on a platter.”'
EXEC add_BibleVerse @BibleId, 340014009, N'Although it grieved the king, because of his oath and the dinner guests he commanded it to be given.'
EXEC add_BibleVerse @BibleId, 340014010, N'So he sent and had John beheaded in the prison.'
EXEC add_BibleVerse @BibleId, 340014011, N'His head was brought on a platter and given to the girl, and she brought it to her mother.'
EXEC add_BibleVerse @BibleId, 340014012, N'Then John’s disciples came and took the body and buried it and went and told Jesus.'
EXEC add_BibleVerse @BibleId, 340014013, N'Now when Jesus heard this he went away from there privately in a boat to an isolated place. But when the crowd heard about it, they followed him on foot from the towns.'
EXEC add_BibleVerse @BibleId, 340014014, N'As he got out he saw the large crowd, and he had compassion on them and healed their sick.'
EXEC add_BibleVerse @BibleId, 340014015, N'When evening arrived, his disciples came to him saying, “This is an isolated place and the hour is already late. Send the crowds away so that they can go into the villages and buy food for themselves.”'
EXEC add_BibleVerse @BibleId, 340014016, N'But he replied, “They don’t need to go. You give them something to eat.”'
EXEC add_BibleVerse @BibleId, 340014017, N'They said to him, “We have here only five loaves and two fish.”'
EXEC add_BibleVerse @BibleId, 340014018, N'“Bring them here to me,” he replied.'
EXEC add_BibleVerse @BibleId, 340014019, N'Then he instructed the crowds to sit down on the grass. He took the five loaves and two fish, and looking up to heaven he gave thanks and broke the loaves. He gave them to the disciples, who in turn gave them to the crowds.'
EXEC add_BibleVerse @BibleId, 340014020, N'They all ate and were satisfied, and they picked up the broken pieces left over, twelve baskets full.'
EXEC add_BibleVerse @BibleId, 340014021, N'Not counting women and children, there were about five thousand men who ate.'
EXEC add_BibleVerse @BibleId, 340014022, N'Immediately Jesus made the disciples get into the boat and go ahead of him to the other side, while he dispersed the crowds.'
EXEC add_BibleVerse @BibleId, 340014023, N'And after he sent the crowds away, he went up the mountain by himself to pray. When evening came, he was there alone.'
EXEC add_BibleVerse @BibleId, 340014024, N'Meanwhile the boat, already far from land, was taking a beating from the waves because the wind was against it.'
EXEC add_BibleVerse @BibleId, 340014025, N'As the night was ending, Jesus came to them walking on the sea.'
EXEC add_BibleVerse @BibleId, 340014026, N'When the disciples saw him walking on the water they were terrified and said, “It’s a ghost!” and cried out with fear.'
EXEC add_BibleVerse @BibleId, 340014027, N'But immediately Jesus spoke to them: “Have courage! It is I. Do not be afraid.”'
EXEC add_BibleVerse @BibleId, 340014028, N'Peter said to him, “Lord, if it is you, order me to come to you on the water.”'
EXEC add_BibleVerse @BibleId, 340014029, N'So he said, “Come.” Peter got out of the boat, walked on the water, and came toward Jesus.'
EXEC add_BibleVerse @BibleId, 340014030, N'But when he saw the strong wind he became afraid. And starting to sink, he cried out, “Lord, save me!”'
EXEC add_BibleVerse @BibleId, 340014031, N'Immediately Jesus reached out his hand and caught him, saying to him, “You of little faith, why did you doubt?”'
EXEC add_BibleVerse @BibleId, 340014032, N'When they went up into the boat, the wind ceased.'
EXEC add_BibleVerse @BibleId, 340014033, N'Then those who were in the boat worshiped him, saying, “Truly you are the Son of God.”'
EXEC add_BibleVerse @BibleId, 340014034, N'After they had crossed over, they came to land at Gennesaret.'
EXEC add_BibleVerse @BibleId, 340014035, N'When the people there recognized him, they sent word into all the surrounding area, and they brought all their sick to him.'
EXEC add_BibleVerse @BibleId, 340014036, N'They begged him if they could only touch the edge of his cloak, and all who touched it were healed.'
EXEC add_BibleVerse @BibleId, 340015001, N'Then Pharisees and experts in the law came from Jerusalem to Jesus and said,'
EXEC add_BibleVerse @BibleId, 340015002, N'“Why do your disciples disobey the tradition of the elders? For they don’t wash their hands when they eat.”'
EXEC add_BibleVerse @BibleId, 340015003, N'He answered them, “And why do you disobey the commandment of God because of your tradition?'
EXEC add_BibleVerse @BibleId, 340015004, N'For God said, ‘ Honor your father and mother’ and ‘ Whoever insults his father or mother must be put to death.’'
EXEC add_BibleVerse @BibleId, 340015005, N'But you say, ‘If someone tells his father or mother, “Whatever help you would have received from me is given to God,”'
EXEC add_BibleVerse @BibleId, 340015006, N'he does not need to honor his father.’ You have nullified the word of God on account of your tradition.'
EXEC add_BibleVerse @BibleId, 340015007, N'Hypocrites! Isaiah prophesied correctly about you when he said,'
EXEC add_BibleVerse @BibleId, 340015008, N'‘ This people honors me with their lips, but their heart is far from me,'
EXEC add_BibleVerse @BibleId, 340015009, N'and they worship me in vain, teaching as doctrines the commandments of men.’”'
EXEC add_BibleVerse @BibleId, 340015010, N'Then he called the crowd to him and said, “Listen and understand.'
EXEC add_BibleVerse @BibleId, 340015011, N'What defiles a person is not what goes into the mouth; it is what comes out of the mouth that defiles a person.”'
EXEC add_BibleVerse @BibleId, 340015012, N'Then the disciples came to him and said, “Do you know that when the Pharisees heard this saying they were offended?”'
EXEC add_BibleVerse @BibleId, 340015013, N'And he replied, “Every plant that my heavenly Father did not plant will be uprooted.'
EXEC add_BibleVerse @BibleId, 340015014, N'Leave them! They are blind guides. If someone who is blind leads another who is blind, both will fall into a pit.”'
EXEC add_BibleVerse @BibleId, 340015015, N'But Peter said to him, “Explain this parable to us.”'
EXEC add_BibleVerse @BibleId, 340015016, N'Jesus said, “Even after all this, are you still so foolish?'
EXEC add_BibleVerse @BibleId, 340015017, N'Don’t you understand that whatever goes into the mouth enters the stomach and then passes out into the sewer?'
EXEC add_BibleVerse @BibleId, 340015018, N'But the things that come out of the mouth come from the heart, and these things defile a person.'
EXEC add_BibleVerse @BibleId, 340015019, N'For out of the heart come evil ideas, murder, adultery, sexual immorality, theft, false testimony, slander.'
EXEC add_BibleVerse @BibleId, 340015020, N'These are the things that defile a person; it is not eating with unwashed hands that defiles a person.”'
EXEC add_BibleVerse @BibleId, 340015021, N'After going out from there, Jesus went to the region of Tyre'
EXEC add_BibleVerse @BibleId, 340015022, N'A Canaanite woman from that area came and cried out, “Have mercy on me, Lord, Son of David! My daughter is horribly demon-possessed!”'
EXEC add_BibleVerse @BibleId, 340015023, N'But he did not answer her a word. Then his disciples came and begged him, “Send her away, because she keeps on crying out after us.”'
EXEC add_BibleVerse @BibleId, 340015024, N'So he answered, “I was sent only to the lost sheep of the house of Israel.”'
EXEC add_BibleVerse @BibleId, 340015025, N'But she came and bowed down before him and said, “Lord, help me!”'
EXEC add_BibleVerse @BibleId, 340015026, N'“It is not right to take the children’s bread and throw it to the dogs,” he said.'
EXEC add_BibleVerse @BibleId, 340015027, N'“Yes, Lord,” she replied, “but even the dogs eat the crumbs that fall from their masters’ table.”'
EXEC add_BibleVerse @BibleId, 340015028, N'Then Jesus answered her, “Woman, your faith is great! Let what you want be done for you.” And her daughter was healed from that hour.'
EXEC add_BibleVerse @BibleId, 340015029, N'When he left there, Jesus went along the Sea of Galilee. Then he went up a mountain, where he sat down.'
EXEC add_BibleVerse @BibleId, 340015030, N'Then large crowds came to him bringing with them the lame, blind, crippled, mute, and many others. They laid them at his feet, and he healed them.'
EXEC add_BibleVerse @BibleId, 340015031, N'As a result, the crowd was amazed when they saw the mute speaking, the crippled healthy, the lame walking, and the blind seeing, and they praised the God of Israel.'
EXEC add_BibleVerse @BibleId, 340015032, N'Then Jesus called the disciples and said, “I have compassion on the crowd, because they have already been here with me three days and they have nothing to eat. I don’t want to send them away hungry since they may faint on the way.”'
EXEC add_BibleVerse @BibleId, 340015033, N'The disciples said to him, “Where can we get enough bread in this desolate place to satisfy so great a crowd?”'
EXEC add_BibleVerse @BibleId, 340015034, N'Jesus said to them, “How many loaves do you have?” They replied, “Seven – and a few small fish.”'
EXEC add_BibleVerse @BibleId, 340015035, N'After instructing the crowd to sit down on the ground,'
EXEC add_BibleVerse @BibleId, 340015036, N'he took the seven loaves and the fish, and after giving thanks, he broke them and began giving them to the disciples, who then gave them to the crowds.'
EXEC add_BibleVerse @BibleId, 340015037, N'They all ate and were satisfied, and they picked up the broken pieces left over, seven baskets full.'
EXEC add_BibleVerse @BibleId, 340015038, N'Not counting children and women, there were four thousand men who ate.'
EXEC add_BibleVerse @BibleId, 340015039, N'After sending away the crowd, he got into the boat and went to the region of Magadan.'
EXEC add_BibleVerse @BibleId, 340016001, N'Now when the Pharisees and Sadducees came to test Jesus, they asked him to show them a sign from heaven.'
EXEC add_BibleVerse @BibleId, 340016002, N'He said, “When evening comes you say, ‘It will be fair weather, because the sky is red,’'
EXEC add_BibleVerse @BibleId, 340016003, N'and in the morning, ‘It will be stormy today, because the sky is red and darkening.’ You know how to judge correctly the appearance of the sky, but you cannot evaluate the signs of the times.'
EXEC add_BibleVerse @BibleId, 340016004, N'A wicked and adulterous generation asks for a sign, but no sign will be given to it except the sign of Jonah.” Then he left them and went away.'
EXEC add_BibleVerse @BibleId, 340016005, N'When the disciples went to the other side, they forgot to take bread.'
EXEC add_BibleVerse @BibleId, 340016006, N'“Watch out,” Jesus said to them, “beware of the yeast of the Pharisees and Sadducees.”'
EXEC add_BibleVerse @BibleId, 340016007, N'So they began to discuss this among themselves, saying, “It is because we brought no bread.”'
EXEC add_BibleVerse @BibleId, 340016008, N'When Jesus learned of this, he said, “You who have such little faith! Why are you arguing among yourselves about having no bread?'
EXEC add_BibleVerse @BibleId, 340016009, N'Do you still not understand? Don’t you remember the five loaves for the five thousand, and how many baskets you took up?'
EXEC add_BibleVerse @BibleId, 340016010, N'Or the seven loaves for the four thousand and how many baskets you took up?'
EXEC add_BibleVerse @BibleId, 340016011, N'How could you not understand that I was not speaking to you about bread? But beware of the yeast of the Pharisees and Sadducees!”'
EXEC add_BibleVerse @BibleId, 340016012, N'Then they understood that he had not told them to be on guard against the yeast in bread, but against the teaching of the Pharisees and Sadducees.'
EXEC add_BibleVerse @BibleId, 340016013, N'When Jesus came to the area of Caesarea Philippi, he asked his disciples, “Who do people say that the Son of Man is?”'
EXEC add_BibleVerse @BibleId, 340016014, N'They answered, “Some say John the Baptist, others Elijah, and others Jeremiah or one of the prophets.”'
EXEC add_BibleVerse @BibleId, 340016015, N'He said to them, “But who do you say that I am?”'
EXEC add_BibleVerse @BibleId, 340016016, N'Simon Peter answered, “You are the Christ, the Son of the living God.”'
EXEC add_BibleVerse @BibleId, 340016017, N'And Jesus answered him, “You are blessed, Simon son of Jonah, because flesh and blood did not reveal this to you, but my Father in heaven!'
EXEC add_BibleVerse @BibleId, 340016018, N'And I tell you that you are Peter, and on this rock I will build my church, and the gates of Hades will not overpower it.'
EXEC add_BibleVerse @BibleId, 340016019, N'I will give you the keys of the kingdom of heaven. Whatever you bind on earth will have been bound in heaven, and whatever you release on earth will have been released in heaven.”'
EXEC add_BibleVerse @BibleId, 340016020, N'Then he instructed his disciples not to tell anyone that he was the Christ.'
EXEC add_BibleVerse @BibleId, 340016021, N'From that time on Jesus began to show his disciples that he must go to Jerusalem and suffer many things at the hands of the elders, chief priests, and experts in the law, and be killed, and on the third day be raised.'
EXEC add_BibleVerse @BibleId, 340016022, N'So Peter took him aside and began to rebuke him: “God forbid, Lord! This must not happen to you!”'
EXEC add_BibleVerse @BibleId, 340016023, N'But he turned and said to Peter, “Get behind me, Satan! You are a stumbling block to me, because you are not setting your mind on God’s interests, but on man’s.”'
EXEC add_BibleVerse @BibleId, 340016024, N'Then Jesus said to his disciples, “If anyone wants to become my follower, he must deny himself, take up his cross, and follow me.'
EXEC add_BibleVerse @BibleId, 340016025, N'For whoever wants to save his life will lose it, but whoever loses his life for my sake will find it.'
EXEC add_BibleVerse @BibleId, 340016026, N'For what does it benefit a person if he gains the whole world but forfeits his life? Or what can a person give in exchange for his life?'
EXEC add_BibleVerse @BibleId, 340016027, N'For the Son of Man will come with his angels in the glory of his Father, and then he will reward each person according to what he has done.'
EXEC add_BibleVerse @BibleId, 340016028, N'I tell you the truth, there are some standing here who will not experience death before they see the Son of Man coming in his kingdom.”'
EXEC add_BibleVerse @BibleId, 340017001, N'Six days later Jesus took with him Peter, James, and John the brother of James, and led them privately up a high mountain.'
EXEC add_BibleVerse @BibleId, 340017002, N'And he was transfigured before them. His face shone like the sun, and his clothes became white as light.'
EXEC add_BibleVerse @BibleId, 340017003, N'Then Moses and Elijah also appeared before them, talking with him.'
EXEC add_BibleVerse @BibleId, 340017004, N'So Peter said to Jesus, “Lord, it is good for us to be here. If you want, I will make three shelters – one for you, one for Moses, and one for Elijah.”'
EXEC add_BibleVerse @BibleId, 340017005, N'While he was still speaking, a bright cloud overshadowed them, and a voice from the cloud said, “This is my one dear Son, in whom I take great delight. Listen to him!”'
EXEC add_BibleVerse @BibleId, 340017006, N'When the disciples heard this, they were overwhelmed with fear and threw themselves down with their faces to the ground.'
EXEC add_BibleVerse @BibleId, 340017007, N'But Jesus came and touched them. “Get up,” he said. “Do not be afraid.”'
EXEC add_BibleVerse @BibleId, 340017008, N'When they looked up, all they saw was Jesus alone.'
EXEC add_BibleVerse @BibleId, 340017009, N'As they were coming down from the mountain, Jesus commanded them, “Do not tell anyone about the vision until the Son of Man is raised from the dead.”'
EXEC add_BibleVerse @BibleId, 340017010, N'The disciples asked him, “Why then do the experts in the law say that Elijah must come first?”'
EXEC add_BibleVerse @BibleId, 340017011, N'He answered, “Elijah does indeed come first and will restore all things.'
EXEC add_BibleVerse @BibleId, 340017012, N'And I tell you that Elijah has already come. Yet they did not recognize him, but did to him whatever they wanted. In the same way, the Son of Man will suffer at their hands.”'
EXEC add_BibleVerse @BibleId, 340017013, N'Then the disciples understood that he was speaking to them about John the Baptist.'
EXEC add_BibleVerse @BibleId, 340017014, N'When they came to the crowd, a man came to him, knelt before him,'
EXEC add_BibleVerse @BibleId, 340017015, N'and said, “Lord, have mercy on my son, because he has seizures and suffers terribly, for he often falls into the fire and into the water.'
EXEC add_BibleVerse @BibleId, 340017016, N'I brought him to your disciples, but they were not able to heal him.”'
EXEC add_BibleVerse @BibleId, 340017017, N'Jesus answered, “You unbelieving and perverse generation! How much longer must I be with you? How much longer must I endure you? Bring him here to me.”'
EXEC add_BibleVerse @BibleId, 340017018, N'Then Jesus rebuked the demon and it came out of him, and the boy was healed from that moment.'
EXEC add_BibleVerse @BibleId, 340017019, N'Then the disciples came to Jesus privately and said, “Why couldn’t we cast it out?”'
EXEC add_BibleVerse @BibleId, 340017020, N'He told them, “It was because of your little faith. I tell you the truth, if you have faith the size of a mustard seed, you will say to this mountain, ‘Move from here to there,’ and it will move; nothing will be impossible for you.”'
EXEC add_BibleVerse @BibleId, 340017022, N' When they gathered together in Galilee, Jesus told them, “The Son of Man is going to be betrayed into the hands of men.'
EXEC add_BibleVerse @BibleId, 340017023, N'They will kill him, and on the third day he will be raised.” And they became greatly distressed.'
EXEC add_BibleVerse @BibleId, 340017024, N'After they arrived in Capernaum, the collectors of the temple tax came to Peter and said, “Your teacher pays the double drachma tax, doesn’t he?”'
EXEC add_BibleVerse @BibleId, 340017025, N'He said, “Yes.” When Peter came into the house, Jesus spoke to him first, “What do you think, Simon? From whom do earthly kings collect tolls or taxes – from their sons or from foreigners?”'
EXEC add_BibleVerse @BibleId, 340017026, N'After he said, “From foreigners,” Jesus said to him, “Then the sons are free.'
EXEC add_BibleVerse @BibleId, 340017027, N'But so that we don’t offend them, go to the lake and throw out a hook. Take the first fish that comes up, and when you open its mouth, you will find a four drachma coin. Take that and give it to them for me and you.”'
EXEC add_BibleVerse @BibleId, 340018001, N'At that time the disciples came to Jesus saying, “Who is the greatest in the kingdom of heaven?”'
EXEC add_BibleVerse @BibleId, 340018002, N'He called a child, had him stand among them,'
EXEC add_BibleVerse @BibleId, 340018003, N'and said, “I tell you the truth, unless you turn around and become like little children, you will never enter the kingdom of heaven!'
EXEC add_BibleVerse @BibleId, 340018004, N'Whoever then humbles himself like this little child is the greatest in the kingdom of heaven.'
EXEC add_BibleVerse @BibleId, 340018005, N'And whoever welcomes a child like this in my name welcomes me.'
EXEC add_BibleVerse @BibleId, 340018006, N'“But if anyone causes one of these little ones who believe in me to sin, it would be better for him to have a huge millstone hung around his neck and to be drowned in the open sea.'
EXEC add_BibleVerse @BibleId, 340018007, N'Woe to the world because of stumbling blocks! It is necessary that stumbling blocks come, but woe to the person through whom they come.'
EXEC add_BibleVerse @BibleId, 340018008, N'If your hand or your foot causes you to sin, cut it off and throw it away. It is better for you to enter life crippled or lame than to have two hands or two feet and be thrown into eternal fire.'
EXEC add_BibleVerse @BibleId, 340018009, N'And if your eye causes you to sin, tear it out and throw it away. It is better for you to enter into life with one eye than to have two eyes and be thrown into fiery hell.'
EXEC add_BibleVerse @BibleId, 340018010, N'“See that you do not disdain one of these little ones. For I tell you that their angels in heaven always see the face of my Father in heaven.'
EXEC add_BibleVerse @BibleId, 340018012, N' What do you think? If someone owns a hundred sheep and one of them goes astray, will he not leave the ninety-nine on the mountains and go look for the one that went astray?'
EXEC add_BibleVerse @BibleId, 340018013, N'And if he finds it, I tell you the truth, he will rejoice more over it than over the ninety-nine that did not go astray.'
EXEC add_BibleVerse @BibleId, 340018014, N'In the same way, your Father in heaven is not willing that one of these little ones be lost.'
EXEC add_BibleVerse @BibleId, 340018015, N'“If your brother sins, go and show him his fault when the two of you are alone. If he listens to you, you have regained your brother.'
EXEC add_BibleVerse @BibleId, 340018016, N'But if he does not listen, take one or two others with you, so that at the testimony of two or three witnesses every matter may be established.'
EXEC add_BibleVerse @BibleId, 340018017, N'If he refuses to listen to them, tell it to the church. If he refuses to listen to the church, treat him like a Gentile or a tax collector.'
EXEC add_BibleVerse @BibleId, 340018018, N'“I tell you the truth, whatever you bind on earth will have been bound in heaven, and whatever you release on earth will have been released in heaven.'
EXEC add_BibleVerse @BibleId, 340018019, N'Again, I tell you the truth, if two of you on earth agree about whatever you ask, my Father in heaven will do it for you.'
EXEC add_BibleVerse @BibleId, 340018020, N'For where two or three are assembled in my name, I am there among them.”'
EXEC add_BibleVerse @BibleId, 340018021, N'Then Peter came to him and said, “Lord, how many times must I forgive my brother who sins against me? As many as seven times?”'
EXEC add_BibleVerse @BibleId, 340018022, N'Jesus said to him, “Not seven times, I tell you, but seventy-seven times!'
EXEC add_BibleVerse @BibleId, 340018023, N'“For this reason, the kingdom of heaven is like a king who wanted to settle accounts with his slaves.'
EXEC add_BibleVerse @BibleId, 340018024, N'As he began settling his accounts, a man who owed ten thousand talents was brought to him.'
EXEC add_BibleVerse @BibleId, 340018025, N'Because he was not able to repay it, the lord ordered him to be sold, along with his wife, children, and whatever he possessed, and repayment to be made.'
EXEC add_BibleVerse @BibleId, 340018026, N'Then the slave threw himself to the ground before him, saying, ‘Be patient with me, and I will repay you everything.’'
EXEC add_BibleVerse @BibleId, 340018027, N'The lord had compassion on that slave and released him, and forgave him the debt.'
EXEC add_BibleVerse @BibleId, 340018028, N'After he went out, that same slave found one of his fellow slaves who owed him one hundred silver coins. So he grabbed him by the throat and started to choke him, saying, ‘Pay back what you owe me!’'
EXEC add_BibleVerse @BibleId, 340018029, N'Then his fellow slave threw himself down and begged him, ‘Be patient with me, and I will repay you.’'
EXEC add_BibleVerse @BibleId, 340018030, N'But he refused. Instead, he went out and threw him in prison until he repaid the debt.'
EXEC add_BibleVerse @BibleId, 340018031, N'When his fellow slaves saw what had happened, they were very upset and went and told their lord everything that had taken place.'
EXEC add_BibleVerse @BibleId, 340018032, N'Then his lord called the first slave and said to him, ‘Evil slave! I forgave you all that debt because you begged me!'
EXEC add_BibleVerse @BibleId, 340018033, N'Should you not have shown mercy to your fellow slave, just as I showed it to you?’'
EXEC add_BibleVerse @BibleId, 340018034, N'And in anger his lord turned him over to the prison guards to torture him until he repaid all he owed.'
EXEC add_BibleVerse @BibleId, 340018035, N'So also my heavenly Father will do to you, if each of you does not forgive your brother from your heart.”'
EXEC add_BibleVerse @BibleId, 340019001, N'Now when Jesus finished these sayings, he left Galilee and went to the region of Judea beyond the Jordan River.'
EXEC add_BibleVerse @BibleId, 340019002, N'Large crowds followed him, and he healed them there.'
EXEC add_BibleVerse @BibleId, 340019003, N'Then some Pharisees came to him in order to test him. They asked, “Is it lawful to divorce a wife for any cause?”'
EXEC add_BibleVerse @BibleId, 340019004, N'He answered, “Have you not read that from the beginning the Creator made them male and female them male and female,'
EXEC add_BibleVerse @BibleId, 340019005, N'and said, ‘ For this reason a man will leave his father and mother and will be united with his wife, and the two will become one flesh’?'
EXEC add_BibleVerse @BibleId, 340019006, N'So they are no longer two, but one flesh. Therefore what God has joined together, let no one separate.”'
EXEC add_BibleVerse @BibleId, 340019007, N'They said to him, “Why then did Moses command us to give a certificate of dismissal and to divorce her?”'
EXEC add_BibleVerse @BibleId, 340019008, N'Jesus said to them, “Moses permitted you to divorce your wives because of your hard hearts, but from the beginning it was not this way.'
EXEC add_BibleVerse @BibleId, 340019009, N'Now I say to you that whoever divorces his wife, except for immorality, and marries another commits adultery.”'
EXEC add_BibleVerse @BibleId, 340019010, N'The disciples said to him, “If this is the case of a husband with a wife, it is better not to marry!”'
EXEC add_BibleVerse @BibleId, 340019011, N'He said to them, “Not everyone can accept this statement, except those to whom it has been given.'
EXEC add_BibleVerse @BibleId, 340019012, N'For there are some eunuchs who were that way from birth, and some who were made eunuchs by others, and some who became eunuchs for the sake of the kingdom of heaven. The one who is able to accept this should accept it.”'
EXEC add_BibleVerse @BibleId, 340019013, N'Then little children were brought to him for him to lay his hands on them and pray. But the disciples scolded those who brought them.'
EXEC add_BibleVerse @BibleId, 340019014, N'But Jesus said, “Let the little children come to me and do not try to stop them, for the kingdom of heaven belongs to such as these.”'
EXEC add_BibleVerse @BibleId, 340019015, N'And he placed his hands on them and went on his way.'
EXEC add_BibleVerse @BibleId, 340019016, N'Now someone came up to him and said, “Teacher, what good thing must I do to gain eternal life?”'
EXEC add_BibleVerse @BibleId, 340019017, N'He said to him, “Why do you ask me about what is good? There is only one who is good. But if you want to enter into life, keep the commandments.”'
EXEC add_BibleVerse @BibleId, 340019018, N'“Which ones?” he asked. Jesus replied, “ Do not murder, do not commit adultery, do not steal, do not give false testimony,'
EXEC add_BibleVerse @BibleId, 340019019, N'honor your father and mother, and love your neighbor as yourself your neighbor as yourself.”'
EXEC add_BibleVerse @BibleId, 340019020, N'The young man said to him, “I have wholeheartedly obeyed all these laws. What do I still lack?”'
EXEC add_BibleVerse @BibleId, 340019021, N'Jesus said to him, “If you wish to be perfect, go sell your possessions and give the money to the poor, and you will have treasure in heaven. Then come, follow me.”'
EXEC add_BibleVerse @BibleId, 340019022, N'But when the young man heard this he went away sorrowful, for he was very rich.'
EXEC add_BibleVerse @BibleId, 340019023, N'Then Jesus said to his disciples, “I tell you the truth, it will be hard for a rich person to enter the kingdom of heaven!'
EXEC add_BibleVerse @BibleId, 340019024, N'Again I say, it is easier for a camel to go through the eye of a needle than for a rich person to enter into the kingdom of God.”'
EXEC add_BibleVerse @BibleId, 340019025, N'The disciples were greatly astonished when they heard this and said, “Then who can be saved?”'
EXEC add_BibleVerse @BibleId, 340019026, N'Jesus looked at them and replied, “This is impossible for mere humans, but for God all things are possible.”'
EXEC add_BibleVerse @BibleId, 340019027, N'Then Peter said to him, “Look, we have left everything to follow you! What then will there be for us?”'
EXEC add_BibleVerse @BibleId, 340019028, N'Jesus said to them, “I tell you the truth: In the age when all things are renewed, when the Son of Man sits on his glorious throne, you who have followed me will also sit on twelve thrones, judging the twelve tribes of Israel.'
EXEC add_BibleVerse @BibleId, 340019029, N'And whoever has left houses or brothers or sisters or father or mother or children or fields for my sake will receive a hundred times as much and will inherit eternal life.'
EXEC add_BibleVerse @BibleId, 340019030, N'But many who are first will be last, and the last first.'
EXEC add_BibleVerse @BibleId, 340020001, N'“For the kingdom of heaven is like a landowner who went out early in the morning to hire workers for his vineyard.'
EXEC add_BibleVerse @BibleId, 340020002, N'And after agreeing with the workers for the standard wage, he sent them into his vineyard.'
EXEC add_BibleVerse @BibleId, 340020003, N'When it was about nine o’clock in the morning, he went out again and saw others standing around in the marketplace without work.'
EXEC add_BibleVerse @BibleId, 340020004, N'He said to them, ‘You go into the vineyard too, and I will give you whatever is right.’'
EXEC add_BibleVerse @BibleId, 340020005, N'So they went. When he went out again about noon and three o’clock that afternoon, he did the same thing.'
EXEC add_BibleVerse @BibleId, 340020006, N'And about five o’clock that afternoon he went out and found others standing around, and said to them, ‘Why are you standing here all day without work?’'
EXEC add_BibleVerse @BibleId, 340020007, N'They said to him, ‘Because no one hired us.’ He said to them, ‘You go and work in the vineyard too.’'
EXEC add_BibleVerse @BibleId, 340020008, N'When it was evening the owner of the vineyard said to his manager, ‘Call the workers and give the pay starting with the last hired until the first.’'
EXEC add_BibleVerse @BibleId, 340020009, N'When those hired about five o’clock came, each received a full day’s pay.'
EXEC add_BibleVerse @BibleId, 340020010, N'And when those hired first came, they thought they would receive more. But each one also received the standard wage.'
EXEC add_BibleVerse @BibleId, 340020011, N'When they received it, they began to complain against the landowner,'
EXEC add_BibleVerse @BibleId, 340020012, N'saying, ‘These last fellows worked one hour, and you have made them equal to us who bore the hardship and burning heat of the day.’'
EXEC add_BibleVerse @BibleId, 340020013, N'And the landowner replied to one of them, ‘Friend, I am not treating you unfairly. Didn’t you agree with me to work for the standard wage?'
EXEC add_BibleVerse @BibleId, 340020014, N'Take what is yours and go. I want to give to this last man the same as I gave to you.'
EXEC add_BibleVerse @BibleId, 340020015, N'Am I not permitted to do what I want with what belongs to me? Or are you envious because I am generous?’'
EXEC add_BibleVerse @BibleId, 340020016, N'So the last will be first, and the first last.”'
EXEC add_BibleVerse @BibleId, 340020017, N'As Jesus was going up to Jerusalem, he took the twelve aside privately and said to them on the way,'
EXEC add_BibleVerse @BibleId, 340020018, N'“Look, we are going up to Jerusalem, and the Son of Man will be handed over to the chief priests and the experts in the law. They will condemn him to death,'
EXEC add_BibleVerse @BibleId, 340020019, N'and will turn him over to the Gentiles to be mocked and flogged severely and crucified. Yet on the third day, he will be raised.”'
EXEC add_BibleVerse @BibleId, 340020020, N'Then the mother of the sons of Zebedee came to him with her sons, and kneeling down she asked him for a favor.'
EXEC add_BibleVerse @BibleId, 340020021, N'He said to her, “What do you want?” She replied, “Permit these two sons of mine to sit, one at your right hand and one at your left, in your kingdom.”'
EXEC add_BibleVerse @BibleId, 340020022, N'Jesus answered, “You don’t know what you are asking! Are you able to drink the cup I am about to drink?” They said to him, “We are able.”'
EXEC add_BibleVerse @BibleId, 340020023, N'He told them, “You will drink my cup, but to sit at my right and at my left is not mine to give. Rather, it is for those for whom it has been prepared by my Father.”'
EXEC add_BibleVerse @BibleId, 340020024, N'Now when the other ten heard this, they were angry with the two brothers.'
EXEC add_BibleVerse @BibleId, 340020025, N'But Jesus called them and said, “You know that the rulers of the Gentiles lord it over them, and those in high positions use their authority over them.'
EXEC add_BibleVerse @BibleId, 340020026, N'It must not be this way among you! Instead whoever wants to be great among you must be your servant,'
EXEC add_BibleVerse @BibleId, 340020027, N'and whoever wants to be first among you must be your slave –'
EXEC add_BibleVerse @BibleId, 340020028, N'just as the Son of Man did not come to be served but to serve, and to give his life as a ransom for many.”'
EXEC add_BibleVerse @BibleId, 340020029, N'As they were leaving Jericho, a large crowd followed them.'
EXEC add_BibleVerse @BibleId, 340020030, N'Two blind men were sitting by the road. When they heard that Jesus was passing by, they shouted, “Have mercy on us, Lord, Son of David!”'
EXEC add_BibleVerse @BibleId, 340020031, N'The crowd scolded them to get them to be quiet. But they shouted even more loudly, “Lord, have mercy on us, Son of David!”'
EXEC add_BibleVerse @BibleId, 340020032, N'Jesus stopped, called them, and said, “What do you want me to do for you?”'
EXEC add_BibleVerse @BibleId, 340020033, N'They said to him, “Lord, let our eyes be opened.”'
EXEC add_BibleVerse @BibleId, 340020034, N'Moved with compassion, Jesus touched their eyes. Immediately they received their sight and followed him.'
EXEC add_BibleVerse @BibleId, 340021001, N'Now when they approached Jerusalem and came to Bethphage, at the Mount of Olives, Jesus sent two disciples,'
EXEC add_BibleVerse @BibleId, 340021002, N'telling them, “Go to the village ahead of you. Right away you will find a donkey tied there, and a colt with her. Untie them and bring them to me.'
EXEC add_BibleVerse @BibleId, 340021003, N'If anyone says anything to you, you are to say, ‘The Lord needs them,’ and he will send them at once.”'
EXEC add_BibleVerse @BibleId, 340021004, N'This took place to fulfill what was spoken by the prophet:'
EXEC add_BibleVerse @BibleId, 340021005, N'“ Tell the people of Zion, ‘ Look, your king is coming to you, unassuming and seated on a donkey, and on a colt, the foal of a donkey.’”'
EXEC add_BibleVerse @BibleId, 340021006, N'So the disciples went and did as Jesus had instructed them.'
EXEC add_BibleVerse @BibleId, 340021007, N'They brought the donkey and the colt and placed their cloaks on them, and he sat on them.'
EXEC add_BibleVerse @BibleId, 340021008, N'A very large crowd spread their cloaks on the road. Others cut branches from the trees and spread them on the road.'
EXEC add_BibleVerse @BibleId, 340021009, N'The crowds that went ahead of him and those following kept shouting, “Hosanna to the Son of David! Blessed is the one who comes in the name of the Lord! Hosanna in the highest!”'
EXEC add_BibleVerse @BibleId, 340021010, N'As he entered Jerusalem the whole city was thrown into an uproar, saying, “Who is this?”'
EXEC add_BibleVerse @BibleId, 340021011, N'And the crowds were saying, “This is the prophet Jesus, from Nazareth in Galilee.”'
EXEC add_BibleVerse @BibleId, 340021012, N'Then Jesus entered the temple area and drove out all those who were selling and buying in the temple courts, and turned over the tables of the money changers and the chairs of those selling doves.'
EXEC add_BibleVerse @BibleId, 340021013, N'And he said to them, “It is written, ‘ My house will be called a house of prayer,’ but you are turning it into a den of robbers!”'
EXEC add_BibleVerse @BibleId, 340021014, N'The blind and lame came to him in the temple courts, and he healed them.'
EXEC add_BibleVerse @BibleId, 340021015, N'But when the chief priests and the experts in the law saw the wonderful things he did and heard the children crying out in the temple courts, “Hosanna to the Son of David,” they became indignant'
EXEC add_BibleVerse @BibleId, 340021016, N'and said to him, “Do you hear what they are saying?” Jesus said to them, “Yes. Have you never read, ‘ Out of the mouths of children and nursing infants you have prepared praise for yourself’?”'
EXEC add_BibleVerse @BibleId, 340021017, N'And leaving them, he went out of the city to Bethany and spent the night there.'
EXEC add_BibleVerse @BibleId, 340021018, N'Now early in the morning, as he returned to the city, he was hungry.'
EXEC add_BibleVerse @BibleId, 340021019, N'After noticing a fig tree by the road he went to it, but found nothing on it except leaves. He said to it, “Never again will there be fruit from you!” And the fig tree withered at once.'
EXEC add_BibleVerse @BibleId, 340021020, N'When the disciples saw it they were amazed, saying, “How did the fig tree wither so quickly?”'
EXEC add_BibleVerse @BibleId, 340021021, N'Jesus answered them, “I tell you the truth, if you have faith and do not doubt, not only will you do what was done to the fig tree, but even if you say to this mountain, ‘Be lifted up and thrown into the sea,’ it will happen.'
EXEC add_BibleVerse @BibleId, 340021022, N'And whatever you ask in prayer, if you believe, you will receive.”'
EXEC add_BibleVerse @BibleId, 340021023, N'Now after Jesus entered the temple courts, the chief priests and elders of the people came up to him as he was teaching and said, “By what authority are you doing these things, and who gave you this authority?”'
EXEC add_BibleVerse @BibleId, 340021024, N'Jesus answered them, “I will also ask you one question. If you answer me then I will also tell you by what authority I do these things.'
EXEC add_BibleVerse @BibleId, 340021025, N'Where did John’s baptism come from? From heaven or from people?” They discussed this among themselves, saying, “If we say, ‘From heaven,’ he will say, ‘Then why did you not believe him?’'
EXEC add_BibleVerse @BibleId, 340021026, N'But if we say, ‘From people,’ we fear the crowd, for they all consider John to be a prophet.”'
EXEC add_BibleVerse @BibleId, 340021027, N'So they answered Jesus, “We don’t know.” Then he said to them, “Neither will I tell you by what authority I am doing these things.'
EXEC add_BibleVerse @BibleId, 340021028, N'“What do you think? A man had two sons. He went to the first and said, ‘Son, go and work in the vineyard today.’'
EXEC add_BibleVerse @BibleId, 340021029, N'The boy answered, ‘I will not.’ But later he had a change of heart and went.'
EXEC add_BibleVerse @BibleId, 340021030, N'The father went to the other son and said the same thing. This boy answered, ‘I will, sir,’ but did not go.'
EXEC add_BibleVerse @BibleId, 340021031, N'Which of the two did his father’s will?” They said, “The first.” Jesus said to them, “I tell you the truth, tax collectors and prostitutes will go ahead of you into the kingdom of God!'
EXEC add_BibleVerse @BibleId, 340021032, N'For John came to you in the way of righteousness, and you did not believe him. But the tax collectors and prostitutes did believe. Although you saw this, you did not later change your minds and believe him.'
EXEC add_BibleVerse @BibleId, 340021033, N'“Listen to another parable: There was a landowner who planted a vineyard. He put a fence around it, dug a pit for its winepress, and built a watchtower. Then he leased it to tenant farmers and went on a journey.'
EXEC add_BibleVerse @BibleId, 340021034, N'When the harvest time was near, he sent his slaves to the tenants to collect his portion of the crop.'
EXEC add_BibleVerse @BibleId, 340021035, N'But the tenants seized his slaves, beat one, killed another, and stoned another.'
EXEC add_BibleVerse @BibleId, 340021036, N'Again he sent other slaves, more than the first, and they treated them the same way.'
EXEC add_BibleVerse @BibleId, 340021037, N'Finally he sent his son to them, saying, ‘They will respect my son.’'
EXEC add_BibleVerse @BibleId, 340021038, N'But when the tenants saw the son, they said to themselves, ‘This is the heir. Come, let’s kill him and get his inheritance!’'
EXEC add_BibleVerse @BibleId, 340021039, N'So they seized him, threw him out of the vineyard, and killed him.'
EXEC add_BibleVerse @BibleId, 340021040, N'Now when the owner of the vineyard comes, what will he do to those tenants?”'
EXEC add_BibleVerse @BibleId, 340021041, N'They said to him, “He will utterly destroy those evil men! Then he will lease the vineyard to other tenants who will give him his portion at the harvest.”'
EXEC add_BibleVerse @BibleId, 340021042, N'Jesus said to them, “Have you never read in the scriptures: ‘ The stone the builders rejected has become the cornerstone. This is from the Lord, and it is marvelous in our eyes’?'
EXEC add_BibleVerse @BibleId, 340021043, N'For this reason I tell you that the kingdom of God will be taken from you and given to a people who will produce its fruit.'
EXEC add_BibleVerse @BibleId, 340021044, N'The one who falls on this stone will be broken to pieces, and the one on whom it falls will be crushed.”'
EXEC add_BibleVerse @BibleId, 340021045, N'When the chief priests and the Pharisees heard his parables, they realized that he was speaking about them.'
EXEC add_BibleVerse @BibleId, 340021046, N'They wanted to arrest him, but they were afraid of the crowds, because the crowds regarded him as a prophet.'
EXEC add_BibleVerse @BibleId, 340022001, N'Jesus spoke to them again in parables, saying:'
EXEC add_BibleVerse @BibleId, 340022002, N'“The kingdom of heaven can be compared to a king who gave a wedding banquet for his son.'
EXEC add_BibleVerse @BibleId, 340022003, N'He sent his slaves to summon those who had been invited to the banquet, but they would not come.'
EXEC add_BibleVerse @BibleId, 340022004, N'Again he sent other slaves, saying, ‘Tell those who have been invited, “Look! The feast I have prepared for you is ready. My oxen and fattened cattle have been slaughtered, and everything is ready. Come to the wedding banquet.”’'
EXEC add_BibleVerse @BibleId, 340022005, N'But they were indifferent and went away, one to his farm, another to his business.'
EXEC add_BibleVerse @BibleId, 340022006, N'The rest seized his slaves, insolently mistreated them, and killed them.'
EXEC add_BibleVerse @BibleId, 340022007, N'The king was furious! He sent his soldiers, and they put those murderers to death and set their city on fire.'
EXEC add_BibleVerse @BibleId, 340022008, N'Then he said to his slaves, ‘The wedding is ready, but the ones who had been invited were not worthy.'
EXEC add_BibleVerse @BibleId, 340022009, N'So go into the main streets and invite everyone you find to the wedding banquet.’'
EXEC add_BibleVerse @BibleId, 340022010, N'And those slaves went out into the streets and gathered all they found, both bad and good, and the wedding hall was filled with guests.'
EXEC add_BibleVerse @BibleId, 340022011, N'But when the king came in to see the wedding guests, he saw a man there who was not wearing wedding clothes.'
EXEC add_BibleVerse @BibleId, 340022012, N'And he said to him, ‘Friend, how did you get in here without wedding clothes?’ But he had nothing to say.'
EXEC add_BibleVerse @BibleId, 340022013, N'Then the king said to his attendants, ‘Tie him up hand and foot and throw him into the outer darkness, where there will be weeping and gnashing of teeth!’'
EXEC add_BibleVerse @BibleId, 340022014, N'For many are called, but few are chosen.”'
EXEC add_BibleVerse @BibleId, 340022015, N'Then the Pharisees went out and planned together to entrap him with his own words.'
EXEC add_BibleVerse @BibleId, 340022016, N'They sent to him their disciples along with the Herodians, saying, “Teacher, we know that you are truthful, and teach the way of God in accordance with the truth. You do not court anyone’s favor because you show no partiality.'
EXEC add_BibleVerse @BibleId, 340022017, N'Tell us then, what do you think? Is it right to pay taxes to Caesar or not?”'
EXEC add_BibleVerse @BibleId, 340022018, N'But Jesus realized their evil intentions and said, “Hypocrites! Why are you testing me?'
EXEC add_BibleVerse @BibleId, 340022019, N'Show me the coin used for the tax.” So they brought him a denarius.'
EXEC add_BibleVerse @BibleId, 340022020, N'Jesus said to them, “Whose image is this, and whose inscription?”'
EXEC add_BibleVerse @BibleId, 340022021, N'They replied, “Caesar’s.” He said to them, “Then give to Caesar the things that are Caesar’s, and to God the things that are God’s.”'
EXEC add_BibleVerse @BibleId, 340022022, N'Now when they heard this they were stunned, and they left him and went away.'
EXEC add_BibleVerse @BibleId, 340022023, N'The same day Sadducees (who say there is no resurrection) came to him and asked him,'
EXEC add_BibleVerse @BibleId, 340022024, N'“Teacher, Moses said, ‘ If a man dies without having children, his brother must marry the widow and father children for his brother.’'
EXEC add_BibleVerse @BibleId, 340022025, N'Now there were seven brothers among us. The first one married and died, and since he had no children he left his wife to his brother.'
EXEC add_BibleVerse @BibleId, 340022026, N'The second did the same, and the third, down to the seventh.'
EXEC add_BibleVerse @BibleId, 340022027, N'Last of all, the woman died.'
EXEC add_BibleVerse @BibleId, 340022028, N'In the resurrection, therefore, whose wife of the seven will she be? For they all had married her.”'
EXEC add_BibleVerse @BibleId, 340022029, N'Jesus answered them, “You are deceived, because you don’t know the scriptures or the power of God.'
EXEC add_BibleVerse @BibleId, 340022030, N'For in the resurrection they neither marry nor are given in marriage, but are like angels in heaven.'
EXEC add_BibleVerse @BibleId, 340022031, N'Now as for the resurrection of the dead, have you not read what was spoken to you by God,'
EXEC add_BibleVerse @BibleId, 340022032, N'‘ I am the God of Abraham, the God of Isaac, and the God of Jacob’? He is not the God of the dead but of the living!”'
EXEC add_BibleVerse @BibleId, 340022033, N'When the crowds heard this, they were amazed at his teaching.'
EXEC add_BibleVerse @BibleId, 340022034, N'Now when the Pharisees heard that he had silenced the Sadducees, they assembled together.'
EXEC add_BibleVerse @BibleId, 340022035, N'And one of them, an expert in religious law, asked him a question to test him:'
EXEC add_BibleVerse @BibleId, 340022036, N'“Teacher, which commandment in the law is the greatest?”'
EXEC add_BibleVerse @BibleId, 340022037, N'Jesus said to him, “‘Love the Lord your God with all your heart, with all your soul, and with all your mind.’'
EXEC add_BibleVerse @BibleId, 340022038, N'This is the first and greatest commandment.'
EXEC add_BibleVerse @BibleId, 340022039, N'The second is like it : ‘Love your neighbor as yourself.’'
EXEC add_BibleVerse @BibleId, 340022040, N'All the law and the prophets depend on these two commandments.”'
EXEC add_BibleVerse @BibleId, 340022041, N'While the Pharisees were assembled, Jesus asked them a question:'
EXEC add_BibleVerse @BibleId, 340022042, N'“What do you think about the Christ? Whose son is he?” They said, “The son of David.”'
EXEC add_BibleVerse @BibleId, 340022043, N'He said to them, “How then does David by the Spirit call him ‘Lord,’ saying,'
EXEC add_BibleVerse @BibleId, 340022044, N'‘ The Lord said to my lord, “ Sit at my right hand, until I put your enemies under your feet”’?'
EXEC add_BibleVerse @BibleId, 340022045, N'If David then calls him ‘Lord,’ how can he be his son?”'
EXEC add_BibleVerse @BibleId, 340022046, N'No one was able to answer him a word, and from that day on no one dared to question him any longer.'
EXEC add_BibleVerse @BibleId, 340023001, N'Then Jesus said to the crowds and to his disciples,'
EXEC add_BibleVerse @BibleId, 340023002, N'“The experts in the law and the Pharisees sit on Moses’ seat.'
EXEC add_BibleVerse @BibleId, 340023003, N'Therefore pay attention to what they tell you and do it. But do not do what they do, for they do not practice what they teach.'
EXEC add_BibleVerse @BibleId, 340023004, N'They tie up heavy loads, hard to carry, and put them on men’s shoulders, but they themselves are not willing even to lift a finger to move them.'
EXEC add_BibleVerse @BibleId, 340023005, N'They do all their deeds to be seen by people, for they make their phylacteries wide and their tassels long.'
EXEC add_BibleVerse @BibleId, 340023006, N'They love the place of honor at banquets and the best seats in the synagogues'
EXEC add_BibleVerse @BibleId, 340023007, N'and elaborate greetings in the marketplaces, and to have people call them ‘Rabbi.’'
EXEC add_BibleVerse @BibleId, 340023008, N'But you are not to be called ‘Rabbi,’ for you have one Teacher and you are all brothers.'
EXEC add_BibleVerse @BibleId, 340023009, N'And call no one your ‘father’ on earth, for you have one Father, who is in heaven.'
EXEC add_BibleVerse @BibleId, 340023010, N'Nor are you to be called ‘teacher,’ for you have one teacher, the Christ.'
EXEC add_BibleVerse @BibleId, 340023011, N'The greatest among you will be your servant.'
EXEC add_BibleVerse @BibleId, 340023012, N'And whoever exalts himself will be humbled, and whoever humbles himself will be exalted.'
EXEC add_BibleVerse @BibleId, 340023013, N'“But woe to you, experts in the law and you Pharisees, hypocrites! You keep locking people out of the kingdom of heaven! For you neither enter nor permit those trying to enter to go in.'
EXEC add_BibleVerse @BibleId, 340023015, N'“Woe to you, experts in the law and you Pharisees, hypocrites! You cross land and sea to make one convert, and when you get one, you make him twice as much a child of hell as yourselves!'
EXEC add_BibleVerse @BibleId, 340023016, N'“Woe to you, blind guides, who say, ‘Whoever swears by the temple is bound by nothing. But whoever swears by the gold of the temple is bound by the oath.’'
EXEC add_BibleVerse @BibleId, 340023017, N'Blind fools! Which is greater, the gold or the temple that makes the gold sacred?'
EXEC add_BibleVerse @BibleId, 340023018, N'And, ‘Whoever swears by the altar is bound by nothing. But if anyone swears by the gift on it he is bound by the oath.’'
EXEC add_BibleVerse @BibleId, 340023019, N'You are blind! For which is greater, the gift or the altar that makes the gift sacred?'
EXEC add_BibleVerse @BibleId, 340023020, N'So whoever swears by the altar swears by it and by everything on it.'
EXEC add_BibleVerse @BibleId, 340023021, N'And whoever swears by the temple swears by it and the one who dwells in it.'
EXEC add_BibleVerse @BibleId, 340023022, N'And whoever swears by heaven swears by the throne of God and the one who sits on it.'
EXEC add_BibleVerse @BibleId, 340023023, N'“Woe to you, experts in the law and you Pharisees, hypocrites! You give a tenth of mint, dill, and cumin, yet you neglect what is more important in the law – justice, mercy, and faithfulness! You should have done these things without neglecting the others.'
EXEC add_BibleVerse @BibleId, 340023024, N'Blind guides! You strain out a gnat yet swallow a camel!'
EXEC add_BibleVerse @BibleId, 340023025, N'“Woe to you, experts in the law and you Pharisees, hypocrites! You clean the outside of the cup and the dish, but inside they are full of greed and self-indulgence.'
EXEC add_BibleVerse @BibleId, 340023026, N'Blind Pharisee! First clean the inside of the cup, so that the outside may become clean too!'
EXEC add_BibleVerse @BibleId, 340023027, N'“Woe to you, experts in the law and you Pharisees, hypocrites! You are like whitewashed tombs that look beautiful on the outside but inside are full of the bones of the dead and of everything unclean.'
EXEC add_BibleVerse @BibleId, 340023028, N'In the same way, on the outside you look righteous to people, but inside you are full of hypocrisy and lawlessness.'
EXEC add_BibleVerse @BibleId, 340023029, N'“Woe to you, experts in the law and you Pharisees, hypocrites! You build tombs for the prophets and decorate the graves of the righteous.'
EXEC add_BibleVerse @BibleId, 340023030, N'And you say, ‘If we had lived in the days of our ancestors, we would not have participated with them in shedding the blood of the prophets.’'
EXEC add_BibleVerse @BibleId, 340023031, N'By saying this you testify against yourselves that you are descendants of those who murdered the prophets.'
EXEC add_BibleVerse @BibleId, 340023032, N'Fill up then the measure of your ancestors!'
EXEC add_BibleVerse @BibleId, 340023033, N'You snakes, you offspring of vipers! How will you escape being condemned to hell?'
EXEC add_BibleVerse @BibleId, 340023034, N'“For this reason I am sending you prophets and wise men and experts in the law, some of whom you will kill and crucify, and some you will flog in your synagogues and pursue from town to town,'
EXEC add_BibleVerse @BibleId, 340023035, N'so that on you will come all the righteous blood shed on earth, from the blood of righteous Abel to the blood of Zechariah son of Barachiah, whom you murdered between the temple and the altar.'
EXEC add_BibleVerse @BibleId, 340023036, N'I tell you the truth, this generation will be held responsible for all these things!'
EXEC add_BibleVerse @BibleId, 340023037, N'“O Jerusalem, Jerusalem, you who kill the prophets and stone those who are sent to you! How often I have longed to gather your children together as a hen gathers her chicks under her wings, but you would have none of it!'
EXEC add_BibleVerse @BibleId, 340023038, N'Look, your house is left to you desolate!'
EXEC add_BibleVerse @BibleId, 340023039, N'For I tell you, you will not see me from now until you say, ‘Blessed is the one who comes in the name of the Lord!’”'
EXEC add_BibleVerse @BibleId, 340024001, N'Now as Jesus was going out of the temple courts and walking away, his disciples came to show him the temple buildings.'
EXEC add_BibleVerse @BibleId, 340024002, N'And he said to them, “Do you see all these things? I tell you the truth, not one stone will be left on another. All will be torn down!”'
EXEC add_BibleVerse @BibleId, 340024003, N'As he was sitting on the Mount of Olives, his disciples came to him privately and said, “Tell us, when will these things happen? And what will be the sign of your coming and of the end of the age?”'
EXEC add_BibleVerse @BibleId, 340024004, N'Jesus answered them, “Watch out that no one misleads you.'
EXEC add_BibleVerse @BibleId, 340024005, N'For many will come in my name, saying, ‘I am the Christ,’ and they will mislead many.'
EXEC add_BibleVerse @BibleId, 340024006, N'You will hear of wars and rumors of wars. Make sure that you are not alarmed, for this must happen, but the end is still to come.'
EXEC add_BibleVerse @BibleId, 340024007, N'For nation will rise up in arms against nation, and kingdom against kingdom. And there will be famines and earthquakes in various places.'
EXEC add_BibleVerse @BibleId, 340024008, N'All these things are the beginning of birth pains.'
EXEC add_BibleVerse @BibleId, 340024009, N'“Then they will hand you over to be persecuted and will kill you. You will be hated by all the nations because of my name.'
EXEC add_BibleVerse @BibleId, 340024010, N'Then many will be led into sin, and they will betray one another and hate one another.'
EXEC add_BibleVerse @BibleId, 340024011, N'And many false prophets will appear and deceive many,'
EXEC add_BibleVerse @BibleId, 340024012, N'and because lawlessness will increase so much, the love of many will grow cold.'
EXEC add_BibleVerse @BibleId, 340024013, N'But the person who endures to the end will be saved.'
EXEC add_BibleVerse @BibleId, 340024014, N'And this gospel of the kingdom will be preached throughout the whole inhabited earth as a testimony to all the nations, and then the end will come.'
EXEC add_BibleVerse @BibleId, 340024015, N'“So when you see the abomination of desolation – spoken about by Daniel the prophet – standing in the holy place (let the reader understand),'
EXEC add_BibleVerse @BibleId, 340024016, N'then those in Judea must flee to the mountains.'
EXEC add_BibleVerse @BibleId, 340024017, N'The one on the roof must not come down to take anything out of his house,'
EXEC add_BibleVerse @BibleId, 340024018, N'and the one in the field must not turn back to get his cloak.'
EXEC add_BibleVerse @BibleId, 340024019, N'Woe to those who are pregnant and to those who are nursing their babies in those days!'
EXEC add_BibleVerse @BibleId, 340024020, N'Pray that your flight may not be in winter or on a Sabbath.'
EXEC add_BibleVerse @BibleId, 340024021, N'For then there will be great suffering unlike anything that has happened from the beginning of the world until now, or ever will happen.'
EXEC add_BibleVerse @BibleId, 340024022, N'And if those days had not been cut short, no one would be saved. But for the sake of the elect those days will be cut short.'
EXEC add_BibleVerse @BibleId, 340024023, N'Then if anyone says to you, ‘Look, here is the Christ!’ or ‘There he is!’ do not believe him.'
EXEC add_BibleVerse @BibleId, 340024024, N'For false messiahs and false prophets will appear and perform great signs and wonders to deceive, if possible, even the elect.'
EXEC add_BibleVerse @BibleId, 340024025, N'Remember, I have told you ahead of time.'
EXEC add_BibleVerse @BibleId, 340024026, N'So then, if someone says to you, ‘Look, he is in the wilderness,’ do not go out, or ‘Look, he is in the inner rooms,’ do not believe him.'
EXEC add_BibleVerse @BibleId, 340024027, N'For just like the lightning comes from the east and flashes to the west, so the coming of the Son of Man will be.'
EXEC add_BibleVerse @BibleId, 340024028, N'Wherever the corpse is, there the vultures will gather.'
EXEC add_BibleVerse @BibleId, 340024029, N'“Immediately after the suffering of those days, the sun will be darkened, and the moon will not give its light; the stars will fall from heaven, and the powers of heaven will be shaken.'
EXEC add_BibleVerse @BibleId, 340024030, N'Then the sign of the Son of Man will appear in heaven, and all the tribes of the earth will mourn. They will see the Son of Man arriving on the clouds of heaven with power and great glory.'
EXEC add_BibleVerse @BibleId, 340024031, N'And he will send his angels with a loud trumpet blast, and they will gather his elect from the four winds, from one end of heaven to the other.'
EXEC add_BibleVerse @BibleId, 340024032, N'“Learn this parable from the fig tree: Whenever its branch becomes tender and puts out its leaves, you know that summer is near.'
EXEC add_BibleVerse @BibleId, 340024033, N'So also you, when you see all these things, know that he is near, right at the door.'
EXEC add_BibleVerse @BibleId, 340024034, N'I tell you the truth, this generation will not pass away until all these things take place.'
EXEC add_BibleVerse @BibleId, 340024035, N'Heaven and earth will pass away, but my words will never pass away.'
EXEC add_BibleVerse @BibleId, 340024036, N'“But as for that day and hour no one knows it – not even the angels in heaven – except the Father alone.'
EXEC add_BibleVerse @BibleId, 340024037, N'For just like the days of Noah were, so the coming of the Son of Man will be.'
EXEC add_BibleVerse @BibleId, 340024038, N'For in those days before the flood, people were eating and drinking, marrying and giving in marriage, until the day Noah entered the ark.'
EXEC add_BibleVerse @BibleId, 340024039, N'And they knew nothing until the flood came and took them all away. It will be the same at the coming of the Son of Man.'
EXEC add_BibleVerse @BibleId, 340024040, N'Then there will be two men in the field; one will be taken and one left.'
EXEC add_BibleVerse @BibleId, 340024041, N'There will be two women grinding grain with a mill; one will be taken and one left.'
EXEC add_BibleVerse @BibleId, 340024042, N'“Therefore stay alert, because you do not know on what day your Lord will come.'
EXEC add_BibleVerse @BibleId, 340024043, N'But understand this: If the owner of the house had known at what time of night the thief was coming, he would have been alert and would not have let his house be broken into.'
EXEC add_BibleVerse @BibleId, 340024044, N'Therefore you also must be ready, because the Son of Man will come at an hour when you do not expect him.'
EXEC add_BibleVerse @BibleId, 340024045, N'“Who then is the faithful and wise slave, whom the master has put in charge of his household, to give the other slaves their food at the proper time?'
EXEC add_BibleVerse @BibleId, 340024046, N'Blessed is that slave whom the master finds at work when he comes.'
EXEC add_BibleVerse @BibleId, 340024047, N'I tell you the truth, the master will put him in charge of all his possessions.'
EXEC add_BibleVerse @BibleId, 340024048, N'But if that evil slave should say to himself, ‘My master is staying away a long time,’'
EXEC add_BibleVerse @BibleId, 340024049, N'and he begins to beat his fellow slaves and to eat and drink with drunkards,'
EXEC add_BibleVerse @BibleId, 340024050, N'then the master of that slave will come on a day when he does not expect him and at an hour he does not foresee,'
EXEC add_BibleVerse @BibleId, 340024051, N'and will cut him in two, and assign him a place with the hypocrites, where there will be weeping and gnashing of teeth.'
EXEC add_BibleVerse @BibleId, 340025001, N'“At that time the kingdom of heaven will be like ten virgins who took their lamps and went out to meet the bridegroom.'
EXEC add_BibleVerse @BibleId, 340025002, N'Five of the virgins were foolish, and five were wise.'
EXEC add_BibleVerse @BibleId, 340025003, N'When the foolish ones took their lamps, they did not take extra olive oil with them.'
EXEC add_BibleVerse @BibleId, 340025004, N'But the wise ones took flasks of olive oil with their lamps.'
EXEC add_BibleVerse @BibleId, 340025005, N'When the bridegroom was delayed a long time, they all became drowsy and fell asleep.'
EXEC add_BibleVerse @BibleId, 340025006, N'But at midnight there was a shout, ‘Look, the bridegroom is here! Come out to meet him.’'
EXEC add_BibleVerse @BibleId, 340025007, N'Then all the virgins woke up and trimmed their lamps.'
EXEC add_BibleVerse @BibleId, 340025008, N'The foolish ones said to the wise, ‘Give us some of your oil, because our lamps are going out.’'
EXEC add_BibleVerse @BibleId, 340025009, N'‘No,’ they replied. ‘There won’t be enough for you and for us. Go instead to those who sell oil and buy some for yourselves.’'
EXEC add_BibleVerse @BibleId, 340025010, N'But while they had gone to buy it, the bridegroom arrived, and those who were ready went inside with him to the wedding banquet. Then the door was shut.'
EXEC add_BibleVerse @BibleId, 340025011, N'Later, the other virgins came too, saying, ‘Lord, lord! Let us in!’'
EXEC add_BibleVerse @BibleId, 340025012, N'But he replied, ‘I tell you the truth, I do not know you!’'
EXEC add_BibleVerse @BibleId, 340025013, N'Therefore stay alert, because you do not know the day or the hour.'
EXEC add_BibleVerse @BibleId, 340025014, N'“For it is like a man going on a journey, who summoned his slaves and entrusted his property to them.'
EXEC add_BibleVerse @BibleId, 340025015, N'To one he gave five talents, to another two, and to another one, each according to his ability. Then he went on his journey.'
EXEC add_BibleVerse @BibleId, 340025016, N'The one who had received five talents went off right away and put his money to work and gained five more.'
EXEC add_BibleVerse @BibleId, 340025017, N'In the same way, the one who had two gained two more.'
EXEC add_BibleVerse @BibleId, 340025018, N'But the one who had received one talent went out and dug a hole in the ground and hid his master’s money in it.'
EXEC add_BibleVerse @BibleId, 340025019, N'After a long time, the master of those slaves came and settled his accounts with them.'
EXEC add_BibleVerse @BibleId, 340025020, N'The one who had received the five talents came and brought five more, saying, ‘Sir, you entrusted me with five talents. See, I have gained five more.’'
EXEC add_BibleVerse @BibleId, 340025021, N'His master answered, ‘Well done, good and faithful slave! You have been faithful in a few things. I will put you in charge of many things. Enter into the joy of your master.’'
EXEC add_BibleVerse @BibleId, 340025022, N'The one with the two talents also came and said, ‘Sir, you entrusted two talents to me. See, I have gained two more.’'
EXEC add_BibleVerse @BibleId, 340025023, N'His master answered, ‘Well done, good and faithful slave! You have been faithful with a few things. I will put you in charge of many things. Enter into the joy of your master.’'
EXEC add_BibleVerse @BibleId, 340025024, N'Then the one who had received the one talent came and said, ‘Sir, I knew that you were a hard man, harvesting where you did not sow, and gathering where you did not scatter seed,'
EXEC add_BibleVerse @BibleId, 340025025, N'so I was afraid, and I went and hid your talent in the ground. See, you have what is yours.’'
EXEC add_BibleVerse @BibleId, 340025026, N'But his master answered, ‘Evil and lazy slave! So you knew that I harvest where I didn’t sow and gather where I didn’t scatter?'
EXEC add_BibleVerse @BibleId, 340025027, N'Then you should have deposited my money with the bankers, and on my return I would have received my money back with interest!'
EXEC add_BibleVerse @BibleId, 340025028, N'Therefore take the talent from him and give it to the one who has ten.'
EXEC add_BibleVerse @BibleId, 340025029, N'For the one who has will be given more, and he will have more than enough. But the one who does not have, even what he has will be taken from him.'
EXEC add_BibleVerse @BibleId, 340025030, N'And throw that worthless slave into the outer darkness, where there will be weeping and gnashing of teeth.’'
EXEC add_BibleVerse @BibleId, 340025031, N'“When the Son of Man comes in his glory and all the angels with him, then he will sit on his glorious throne.'
EXEC add_BibleVerse @BibleId, 340025032, N'All the nations will be assembled before him, and he will separate people one from another like a shepherd separates the sheep from the goats.'
EXEC add_BibleVerse @BibleId, 340025033, N'He will put the sheep on his right and the goats on his left.'
EXEC add_BibleVerse @BibleId, 340025034, N'Then the king will say to those on his right, ‘Come, you who are blessed by my Father, inherit the kingdom prepared for you from the foundation of the world.'
EXEC add_BibleVerse @BibleId, 340025035, N'For I was hungry and you gave me food, I was thirsty and you gave me something to drink, I was a stranger and you invited me in,'
EXEC add_BibleVerse @BibleId, 340025036, N'I was naked and you gave me clothing, I was sick and you took care of me, I was in prison and you visited me.’'
EXEC add_BibleVerse @BibleId, 340025037, N'Then the righteous will answer him, ‘Lord, when did we see you hungry and feed you, or thirsty and give you something to drink?'
EXEC add_BibleVerse @BibleId, 340025038, N'When did we see you a stranger and invite you in, or naked and clothe you?'
EXEC add_BibleVerse @BibleId, 340025039, N'When did we see you sick or in prison and visit you?’'
EXEC add_BibleVerse @BibleId, 340025040, N'And the king will answer them, ‘I tell you the truth, just as you did it for one of the least of these brothers or sisters of mine, you did it for me.’'
EXEC add_BibleVerse @BibleId, 340025041, N'“Then he will say to those on his left, ‘Depart from me, you accursed, into the eternal fire that has been prepared for the devil and his angels!'
EXEC add_BibleVerse @BibleId, 340025042, N'For I was hungry and you gave me nothing to eat, I was thirsty and you gave me nothing to drink.'
EXEC add_BibleVerse @BibleId, 340025043, N'I was a stranger and you did not receive me as a guest, naked and you did not clothe me, sick and in prison and you did not visit me.’'
EXEC add_BibleVerse @BibleId, 340025044, N'Then they too will answer, ‘Lord, when did we see you hungry or thirsty or a stranger or naked or sick or in prison, and did not give you whatever you needed?’'
EXEC add_BibleVerse @BibleId, 340025045, N'Then he will answer them, ‘I tell you the truth, just as you did not do it for one of the least of these, you did not do it for me.’'
EXEC add_BibleVerse @BibleId, 340025046, N'And these will depart into eternal punishment, but the righteous into eternal life.”'
EXEC add_BibleVerse @BibleId, 340026001, N'When Jesus had finished saying all these things, he told his disciples,'
EXEC add_BibleVerse @BibleId, 340026002, N'“You know that after two days the Passover is coming, and the Son of Man will be handed over to be crucified.”'
EXEC add_BibleVerse @BibleId, 340026003, N'Then the chief priests and the elders of the people met together in the palace of the high priest, who was named Caiaphas.'
EXEC add_BibleVerse @BibleId, 340026004, N'They planned to arrest Jesus by stealth and kill him.'
EXEC add_BibleVerse @BibleId, 340026005, N'But they said, “Not during the feast, so that there won’t be a riot among the people.”'
EXEC add_BibleVerse @BibleId, 340026006, N'Now while Jesus was in Bethany at the house of Simon the leper,'
EXEC add_BibleVerse @BibleId, 340026007, N'a woman came to him with an alabaster jar of expensive perfumed oil, and she poured it on his head as he was at the table.'
EXEC add_BibleVerse @BibleId, 340026008, N'When the disciples saw this, they became indignant and said, “Why this waste?'
EXEC add_BibleVerse @BibleId, 340026009, N'It could have been sold at a high price and the money given to the poor!”'
EXEC add_BibleVerse @BibleId, 340026010, N'When Jesus learned of this, he said to them, “Why are you bothering this woman? She has done a good service for me.'
EXEC add_BibleVerse @BibleId, 340026011, N'For you will always have the poor with you, but you will not always have me!'
EXEC add_BibleVerse @BibleId, 340026012, N'When she poured this oil on my body, she did it to prepare me for burial.'
EXEC add_BibleVerse @BibleId, 340026013, N'I tell you the truth, wherever this gospel is proclaimed in the whole world, what she has done will also be told in memory of her.”'
EXEC add_BibleVerse @BibleId, 340026014, N'Then one of the twelve, the one named Judas Iscariot, went to the chief priests'
EXEC add_BibleVerse @BibleId, 340026015, N'and said, “What will you give me to betray him into your hands?” So they set out thirty silver coins for him.'
EXEC add_BibleVerse @BibleId, 340026016, N'From that time on, Judas began looking for an opportunity to betray him.'
EXEC add_BibleVerse @BibleId, 340026017, N'Now on the first day of the feast of Unleavened Bread the disciples came to Jesus and said, “Where do you want us to prepare for you to eat the Passover?”'
EXEC add_BibleVerse @BibleId, 340026018, N'He said, “Go into the city to a certain man and tell him, ‘The Teacher says, “My time is near. I will observe the Passover with my disciples at your house.”’”'
EXEC add_BibleVerse @BibleId, 340026019, N'So the disciples did as Jesus had instructed them, and they prepared the Passover.'
EXEC add_BibleVerse @BibleId, 340026020, N'When it was evening, he took his place at the table with the twelve.'
EXEC add_BibleVerse @BibleId, 340026021, N'And while they were eating he said, “I tell you the truth, one of you will betray me.”'
EXEC add_BibleVerse @BibleId, 340026022, N'They became greatly distressed and each one began to say to him, “Surely not I, Lord?”'
EXEC add_BibleVerse @BibleId, 340026023, N'He answered, “The one who has dipped his hand into the bowl with me will betray me.'
EXEC add_BibleVerse @BibleId, 340026024, N'The Son of Man will go as it is written about him, but woe to that man by whom the Son of Man is betrayed! It would be better for him if he had never been born.”'
EXEC add_BibleVerse @BibleId, 340026025, N'Then Judas, the one who would betray him, said, “Surely not I, Rabbi?” Jesus replied, “You have said it yourself.”'
EXEC add_BibleVerse @BibleId, 340026026, N'While they were eating, Jesus took bread, and after giving thanks he broke it, gave it to his disciples, and said, “Take, eat, this is my body.”'
EXEC add_BibleVerse @BibleId, 340026027, N'And after taking the cup and giving thanks, he gave it to them, saying, “Drink from it, all of you,'
EXEC add_BibleVerse @BibleId, 340026028, N'for this is my blood, the blood of the covenant, that is poured out for many for the forgiveness of sins.'
EXEC add_BibleVerse @BibleId, 340026029, N'I tell you, from now on I will not drink of this fruit of the vine until that day when I drink it new with you in my Father’s kingdom.”'
EXEC add_BibleVerse @BibleId, 340026030, N'After singing a hymn, they went out to the Mount of Olives.'
EXEC add_BibleVerse @BibleId, 340026031, N'Then Jesus said to them, “This night you will all fall away because of me, for it is written: ‘ I will strike the shepherd, and the sheep of the flock will be scattered.’'
EXEC add_BibleVerse @BibleId, 340026032, N'But after I am raised, I will go ahead of you into Galilee.”'
EXEC add_BibleVerse @BibleId, 340026033, N'Peter said to him, “If they all fall away because of you, I will never fall away!”'
EXEC add_BibleVerse @BibleId, 340026034, N'Jesus said to him, “I tell you the truth, on this night, before the rooster crows, you will deny me three times.”'
EXEC add_BibleVerse @BibleId, 340026035, N'Peter said to him, “Even if I must die with you, I will never deny you.” And all the disciples said the same thing.'
EXEC add_BibleVerse @BibleId, 340026036, N'Then Jesus went with them to a place called Gethsemane, and he said to the disciples, “Sit here while I go over there and pray.”'
EXEC add_BibleVerse @BibleId, 340026037, N'He took with him Peter and the two sons of Zebedee, and became anguished and distressed.'
EXEC add_BibleVerse @BibleId, 340026038, N'Then he said to them, “My soul is deeply grieved, even to the point of death. Remain here and stay awake with me.”'
EXEC add_BibleVerse @BibleId, 340026039, N'Going a little farther, he threw himself down with his face to the ground and prayed, “My Father, if possible, let this cup pass from me! Yet not what I will, but what you will.”'
EXEC add_BibleVerse @BibleId, 340026040, N'Then he came to the disciples and found them sleeping. He said to Peter, “So, couldn’t you stay awake with me for one hour?'
EXEC add_BibleVerse @BibleId, 340026041, N'Stay awake and pray that you will not fall into temptation. The spirit is willing, but the flesh is weak.”'
EXEC add_BibleVerse @BibleId, 340026042, N'He went away a second time and prayed, “My Father, if this cup cannot be taken away unless I drink it, your will must be done.”'
EXEC add_BibleVerse @BibleId, 340026043, N'He came again and found them sleeping; they could not keep their eyes open.'
EXEC add_BibleVerse @BibleId, 340026044, N'So leaving them again, he went away and prayed for the third time, saying the same thing once more.'
EXEC add_BibleVerse @BibleId, 340026045, N'Then he came to the disciples and said to them, “Are you still sleeping and resting? Look, the hour is approaching, and the Son of Man is betrayed into the hands of sinners.'
EXEC add_BibleVerse @BibleId, 340026046, N'Get up, let us go. Look! My betrayer is approaching!”'
EXEC add_BibleVerse @BibleId, 340026047, N'While he was still speaking, Judas, one of the twelve, arrived. With him was a large crowd armed with swords and clubs, sent by the chief priests and elders of the people.'
EXEC add_BibleVerse @BibleId, 340026048, N'(Now the betrayer had given them a sign, saying, “The one I kiss is the man. Arrest him!”)'
EXEC add_BibleVerse @BibleId, 340026049, N'Immediately he went up to Jesus and said, “Greetings, Rabbi,” and kissed him.'
EXEC add_BibleVerse @BibleId, 340026050, N'Jesus said to him, “Friend, do what you are here to do.” Then they came and took hold of Jesus and arrested him.'
EXEC add_BibleVerse @BibleId, 340026051, N'But one of those with Jesus grabbed his sword, drew it out, and struck the high priest’s slave, cutting off his ear.'
EXEC add_BibleVerse @BibleId, 340026052, N'Then Jesus said to him, “Put your sword back in its place! For all who take hold of the sword will die by the sword.'
EXEC add_BibleVerse @BibleId, 340026053, N'Or do you think that I cannot call on my Father, and that he would send me more than twelve legions of angels right now?'
EXEC add_BibleVerse @BibleId, 340026054, N'How then would the scriptures that say it must happen this way be fulfilled?”'
EXEC add_BibleVerse @BibleId, 340026055, N'At that moment Jesus said to the crowd, “Have you come out with swords and clubs to arrest me like you would an outlaw? Day after day I sat teaching in the temple courts, yet you did not arrest me.'
EXEC add_BibleVerse @BibleId, 340026056, N'But this has happened so that the scriptures of the prophets would be fulfilled.” Then all the disciples left him and fled.'
EXEC add_BibleVerse @BibleId, 340026057, N'Now the ones who had arrested Jesus led him to Caiaphas, the high priest, in whose house the experts in the law and the elders had gathered.'
EXEC add_BibleVerse @BibleId, 340026058, N'But Peter was following him from a distance, all the way to the high priest’s courtyard. After going in, he sat with the guards to see the outcome.'
EXEC add_BibleVerse @BibleId, 340026059, N'The chief priests and the whole Sanhedrin were trying to find false testimony against Jesus so that they could put him to death.'
EXEC add_BibleVerse @BibleId, 340026060, N'But they did not find anything, though many false witnesses came forward. Finally two came forward'
EXEC add_BibleVerse @BibleId, 340026061, N'and declared, “This man said, ‘I am able to destroy the temple of God and rebuild it in three days.’”'
EXEC add_BibleVerse @BibleId, 340026062, N'So the high priest stood up and said to him, “Have you no answer? What is this that they are testifying against you?”'
EXEC add_BibleVerse @BibleId, 340026063, N'But Jesus was silent. The high priest said to him, “I charge you under oath by the living God, tell us if you are the Christ, the Son of God.”'
EXEC add_BibleVerse @BibleId, 340026064, N'Jesus said to him, “You have said it yourself. But I tell you, from now on you will see the Son of Man sitting at the right hand of the Power and coming on the clouds of heaven.”'
EXEC add_BibleVerse @BibleId, 340026065, N'Then the high priest tore his clothes and declared, “He has blasphemed! Why do we still need witnesses? Now you have heard the blasphemy!'
EXEC add_BibleVerse @BibleId, 340026066, N'What is your verdict?” They answered, “He is guilty and deserves death.”'
EXEC add_BibleVerse @BibleId, 340026067, N'Then they spat in his face and struck him with their fists. And some slapped him,'
EXEC add_BibleVerse @BibleId, 340026068, N'saying, “Prophesy for us, you Christ! Who hit you?”'
EXEC add_BibleVerse @BibleId, 340026069, N'Now Peter was sitting outside in the courtyard. A slave girl came to him and said, “You also were with Jesus the Galilean.”'
EXEC add_BibleVerse @BibleId, 340026070, N'But he denied it in front of them all: “I don’t know what you’re talking about!”'
EXEC add_BibleVerse @BibleId, 340026071, N'When he went out to the gateway, another slave girl saw him and said to the people there, “This man was with Jesus the Nazarene.”'
EXEC add_BibleVerse @BibleId, 340026072, N'He denied it again with an oath, “I do not know the man!”'
EXEC add_BibleVerse @BibleId, 340026073, N'After a little while, those standing there came up to Peter and said, “You really are one of them too – even your accent gives you away!”'
EXEC add_BibleVerse @BibleId, 340026074, N'At that he began to curse, and he swore with an oath, “I do not know the man!” At that moment a rooster crowed.'
EXEC add_BibleVerse @BibleId, 340026075, N'Then Peter remembered what Jesus had said: “Before the rooster crows, you will deny me three times.” And he went outside and wept bitterly.'
EXEC add_BibleVerse @BibleId, 340027001, N'When it was early in the morning, all the chief priests and the elders of the people plotted against Jesus to execute him.'
EXEC add_BibleVerse @BibleId, 340027002, N'They tied him up, led him away, and handed him over to Pilate the governor.'
EXEC add_BibleVerse @BibleId, 340027003, N'Now when Judas, who had betrayed him, saw that Jesus had been condemned, he regretted what he had done and returned the thirty silver coins to the chief priests and the elders,'
EXEC add_BibleVerse @BibleId, 340027004, N'saying, “I have sinned by betraying innocent blood!” But they said, “What is that to us? You take care of it yourself!”'
EXEC add_BibleVerse @BibleId, 340027005, N'So Judas threw the silver coins into the temple and left. Then he went out and hanged himself.'
EXEC add_BibleVerse @BibleId, 340027006, N'The chief priests took the silver and said, “It is not lawful to put this into the temple treasury, since it is blood money.”'
EXEC add_BibleVerse @BibleId, 340027007, N'After consulting together they bought the Potter’s Field with it, as a burial place for foreigners.'
EXEC add_BibleVerse @BibleId, 340027008, N'For this reason that field has been called the “Field of Blood” to this day.'
EXEC add_BibleVerse @BibleId, 340027009, N'Then what was spoken by Jeremiah the prophet was fulfilled : “They took the thirty silver coins, the price of the one whose price had been set by the people of Israel,'
EXEC add_BibleVerse @BibleId, 340027010, N'and they gave them for the potter’s field, as the Lord commanded me.”'
EXEC add_BibleVerse @BibleId, 340027011, N'Then Jesus stood before the governor, and the governor asked him, “Are you the king of the Jews?” Jesus said, “You say so.”'
EXEC add_BibleVerse @BibleId, 340027012, N'But when he was accused by the chief priests and the elders, he did not respond.'
EXEC add_BibleVerse @BibleId, 340027013, N'Then Pilate said to him, “Don’t you hear how many charges they are bringing against you?”'
EXEC add_BibleVerse @BibleId, 340027014, N'But he did not answer even one accusation, so that the governor was quite amazed.'
EXEC add_BibleVerse @BibleId, 340027015, N'During the feast the governor was accustomed to release one prisoner to the crowd, whomever they wanted.'
EXEC add_BibleVerse @BibleId, 340027016, N'At that time they had in custody a notorious prisoner named Jesus Barabbas.'
EXEC add_BibleVerse @BibleId, 340027017, N'So after they had assembled, Pilate said to them, “Whom do you want me to release for you, Jesus Barabbas or Jesus who is called the Christ?”'
EXEC add_BibleVerse @BibleId, 340027018, N'(For he knew that they had handed him over because of envy.)'
EXEC add_BibleVerse @BibleId, 340027019, N'As he was sitting on the judgment seat, his wife sent a message to him: “Have nothing to do with that innocent man; I have suffered greatly as a result of a dream about him today.”'
EXEC add_BibleVerse @BibleId, 340027020, N'But the chief priests and the elders persuaded the crowds to ask for Barabbas and to have Jesus killed.'
EXEC add_BibleVerse @BibleId, 340027021, N'The governor asked them, “Which of the two do you want me to release for you?” And they said, “Barabbas!”'
EXEC add_BibleVerse @BibleId, 340027022, N'Pilate said to them, “Then what should I do with Jesus who is called the Christ?” They all said, “Crucify him!”'
EXEC add_BibleVerse @BibleId, 340027023, N'He asked, “Why? What wrong has he done?” But they shouted more insistently, “Crucify him!”'
EXEC add_BibleVerse @BibleId, 340027024, N'When Pilate saw that he could do nothing, but that instead a riot was starting, he took some water, washed his hands before the crowd and said, “I am innocent of this man’s blood. You take care of it yourselves!”'
EXEC add_BibleVerse @BibleId, 340027025, N'In reply all the people said, “Let his blood be on us and on our children!”'
EXEC add_BibleVerse @BibleId, 340027026, N'Then he released Barabbas for them. But after he had Jesus flogged, he handed him over to be crucified.'
EXEC add_BibleVerse @BibleId, 340027027, N'Then the governor’s soldiers took Jesus into the governor’s residence and gathered the whole cohort around him.'
EXEC add_BibleVerse @BibleId, 340027028, N'They stripped him and put a scarlet robe around him,'
EXEC add_BibleVerse @BibleId, 340027029, N'and after braiding a crown of thorns, they put it on his head. They put a staff in his right hand, and kneeling down before him, they mocked him: “Hail, king of the Jews!”'
EXEC add_BibleVerse @BibleId, 340027030, N'They spat on him and took the staff and struck him repeatedly on the head.'
EXEC add_BibleVerse @BibleId, 340027031, N'When they had mocked him, they stripped him of the robe and put his own clothes back on him. Then they led him away to crucify him.'
EXEC add_BibleVerse @BibleId, 340027032, N'As they were going out, they found a man from Cyrene named Simon, whom they forced to carry his cross.'
EXEC add_BibleVerse @BibleId, 340027033, N'They came to a place called Golgotha (which means “Place of the Skull”)'
EXEC add_BibleVerse @BibleId, 340027034, N'and offered Jesus wine mixed with gall to drink. But after tasting it, he would not drink it.'
EXEC add_BibleVerse @BibleId, 340027035, N'When they had crucified him, they divided his clothes by throwing dice.'
EXEC add_BibleVerse @BibleId, 340027036, N'Then they sat down and kept guard over him there.'
EXEC add_BibleVerse @BibleId, 340027037, N'Above his head they put the charge against him, which read: “This is Jesus, the king of the Jews.”'
EXEC add_BibleVerse @BibleId, 340027038, N'Then two outlaws were crucified with him, one on his right and one on his left.'
EXEC add_BibleVerse @BibleId, 340027039, N'Those who passed by defamed him, shaking their heads'
EXEC add_BibleVerse @BibleId, 340027040, N'and saying, “You who can destroy the temple and rebuild it in three days, save yourself! If you are God’s Son, come down from the cross!”'
EXEC add_BibleVerse @BibleId, 340027041, N'In the same way even the chief priests – together with the experts in the law and elders – were mocking him:'
EXEC add_BibleVerse @BibleId, 340027042, N'“He saved others, but he cannot save himself! He is the king of Israel! If he comes down now from the cross, we will believe in him!'
EXEC add_BibleVerse @BibleId, 340027043, N'He trusts in God – let God, if he wants to, deliver him now because he said, ‘I am God’s Son’!”'
EXEC add_BibleVerse @BibleId, 340027044, N'The robbers who were crucified with him also spoke abusively to him.'
EXEC add_BibleVerse @BibleId, 340027045, N'Now from noon until three, darkness came over all the land.'
EXEC add_BibleVerse @BibleId, 340027046, N'At about three o’clock Jesus shouted with a loud voice, “ Eli, Eli, lema sabachthani? ” that is, “My God, my God, why have you forsaken me?”'
EXEC add_BibleVerse @BibleId, 340027047, N'When some of the bystanders heard it, they said, “This man is calling for Elijah.”'
EXEC add_BibleVerse @BibleId, 340027048, N'Immediately one of them ran and got a sponge, filled it with sour wine, put it on a stick, and gave it to him to drink.'
EXEC add_BibleVerse @BibleId, 340027049, N'But the rest said, “Leave him alone! Let’s see if Elijah will come to save him.”'
EXEC add_BibleVerse @BibleId, 340027050, N'Then Jesus cried out again with a loud voice and gave up his spirit.'
EXEC add_BibleVerse @BibleId, 340027051, N'Just then the temple curtain was torn in two, from top to bottom. The earth shook and the rocks were split apart.'
EXEC add_BibleVerse @BibleId, 340027052, N'And tombs were opened, and the bodies of many saints who had died were raised.'
EXEC add_BibleVerse @BibleId, 340027053, N'(They came out of the tombs after his resurrection and went into the holy city and appeared to many people.)'
EXEC add_BibleVerse @BibleId, 340027054, N'Now when the centurion and those with him who were guarding Jesus saw the earthquake and what took place, they were extremely terrified and said, “Truly this one was God’s Son!”'
EXEC add_BibleVerse @BibleId, 340027055, N'Many women who had followed Jesus from Galilee and given him support were also there, watching from a distance.'
EXEC add_BibleVerse @BibleId, 340027056, N'Among them were Mary Magdalene, Mary the mother of James and Joseph, and the mother of the sons of Zebedee.'
EXEC add_BibleVerse @BibleId, 340027057, N'Now when it was evening, there came a rich man from Arimathea, named Joseph, who was also a disciple of Jesus.'
EXEC add_BibleVerse @BibleId, 340027058, N'He went to Pilate and asked for the body of Jesus. Then Pilate ordered that it be given to him.'
EXEC add_BibleVerse @BibleId, 340027059, N'Joseph took the body, wrapped it in a clean linen cloth,'
EXEC add_BibleVerse @BibleId, 340027060, N'and placed it in his own new tomb that he had cut in the rock. Then he rolled a great stone across the entrance of the tomb and went away.'
EXEC add_BibleVerse @BibleId, 340027061, N'(Now Mary Magdalene and the other Mary were sitting there, opposite the tomb.)'
EXEC add_BibleVerse @BibleId, 340027062, N'The next day (which is after the day of preparation) the chief priests and the Pharisees assembled before Pilate'
EXEC add_BibleVerse @BibleId, 340027063, N'and said, “Sir, we remember that while that deceiver was still alive he said, ‘After three days I will rise again.’'
EXEC add_BibleVerse @BibleId, 340027064, N'So give orders to secure the tomb until the third day. Otherwise his disciples may come and steal his body and say to the people, ‘He has been raised from the dead,’ and the last deception will be worse than the first.”'
EXEC add_BibleVerse @BibleId, 340027065, N'Pilate said to them, “Take a guard of soldiers. Go and make it as secure as you can.”'
EXEC add_BibleVerse @BibleId, 340027066, N'So they went with the soldiers of the guard and made the tomb secure by sealing the stone.'
EXEC add_BibleVerse @BibleId, 340028001, N'Now after the Sabbath, at dawn on the first day of the week, Mary Magdalene and the other Mary went to look at the tomb.'
EXEC add_BibleVerse @BibleId, 340028002, N'Suddenly there was a severe earthquake, for an angel of the Lord descending from heaven came and rolled away the stone and sat on it.'
EXEC add_BibleVerse @BibleId, 340028003, N'His appearance was like lightning, and his clothes were white as snow.'
EXEC add_BibleVerse @BibleId, 340028004, N'The guards were shaken and became like dead men because they were so afraid of him.'
EXEC add_BibleVerse @BibleId, 340028005, N'But the angel said to the women, “Do not be afraid; I know that you are looking for Jesus, who was crucified.'
EXEC add_BibleVerse @BibleId, 340028006, N'He is not here, for he has been raised, just as he said. Come and see the place where he was lying.'
EXEC add_BibleVerse @BibleId, 340028007, N'Then go quickly and tell his disciples, ‘He has been raised from the dead. He is going ahead of you into Galilee. You will see him there.’ Listen, I have told you!”'
EXEC add_BibleVerse @BibleId, 340028008, N'So they left the tomb quickly, with fear and great joy, and ran to tell his disciples.'
EXEC add_BibleVerse @BibleId, 340028009, N'But Jesus met them, saying, “Greetings!” They came to him, held on to his feet and worshiped him.'
EXEC add_BibleVerse @BibleId, 340028010, N'Then Jesus said to them, “Do not be afraid. Go and tell my brothers to go to Galilee. They will see me there.”'
EXEC add_BibleVerse @BibleId, 340028011, N'While they were going, some of the guard went into the city and told the chief priests everything that had happened.'
EXEC add_BibleVerse @BibleId, 340028012, N'After they had assembled with the elders and formed a plan, they gave a large sum of money to the soldiers,'
EXEC add_BibleVerse @BibleId, 340028013, N'telling them, “You are to say, ‘His disciples came at night and stole his body while we were asleep.’'
EXEC add_BibleVerse @BibleId, 340028014, N'If this matter is heard before the governor, we will satisfy him and keep you out of trouble.”'
EXEC add_BibleVerse @BibleId, 340028015, N'So they took the money and did as they were instructed. And this story is told among the Jews to this day.'
EXEC add_BibleVerse @BibleId, 340028016, N'So the eleven disciples went to Galilee to the mountain Jesus had designated.'
EXEC add_BibleVerse @BibleId, 340028017, N'When they saw him, they worshiped him, but some doubted.'
EXEC add_BibleVerse @BibleId, 340028018, N'Then Jesus came up and said to them, “All authority in heaven and on earth has been given to me.'
EXEC add_BibleVerse @BibleId, 340028019, N'Therefore go and make disciples of all nations, baptizing them in the name of the Father and the Son and the Holy Spirit,'
EXEC add_BibleVerse @BibleId, 340028020, N'teaching them to obey everything I have commanded you. And remember, I am with you always, to the end of the age.”'
EXEC add_BibleVerse @BibleId, 341001001, N'The beginning of the gospel of Jesus Christ, the Son of God.'
EXEC add_BibleVerse @BibleId, 341001002, N'As it is written in Isaiah the prophet, “ Look, I am sending my messenger ahead of you, who will prepare your way,'
EXEC add_BibleVerse @BibleId, 341001003, N'the voice of one shouting in the wilderness, ‘ Prepare the way for the Lord, make his paths straight.’”'
EXEC add_BibleVerse @BibleId, 341001004, N'In the wilderness John the baptizer began preaching a baptism of repentance for the forgiveness of sins.'
EXEC add_BibleVerse @BibleId, 341001005, N'People from the whole Judean countryside and all of Jerusalem were going out to him, and he was baptizing them in the Jordan River as they confessed their sins.'
EXEC add_BibleVerse @BibleId, 341001006, N'John wore a garment made of camel’s hair with a leather belt around his waist, and he ate locusts and wild honey.'
EXEC add_BibleVerse @BibleId, 341001007, N'He proclaimed, “One more powerful than I am is coming after me; I am not worthy to bend down and untie the strap of his sandals.'
EXEC add_BibleVerse @BibleId, 341001008, N'I baptize you with water, but he will baptize you with the Holy Spirit.”'
EXEC add_BibleVerse @BibleId, 341001009, N'Now in those days Jesus came from Nazareth in Galilee and was baptized by John in the Jordan River.'
EXEC add_BibleVerse @BibleId, 341001010, N'And just as Jesus was coming up out of the water, he saw the heavens splitting apart and the Spirit descending on him like a dove.'
EXEC add_BibleVerse @BibleId, 341001011, N'And a voice came from heaven: “You are my one dear Son; in you I take great delight.”'
EXEC add_BibleVerse @BibleId, 341001012, N'The Spirit immediately drove him into the wilderness.'
EXEC add_BibleVerse @BibleId, 341001013, N'He was in the wilderness forty days, enduring temptations from Satan. He was with wild animals, and angels were ministering to his needs.'
EXEC add_BibleVerse @BibleId, 341001014, N'Now after John was imprisoned, Jesus went into Galilee and proclaimed the gospel of God.'
EXEC add_BibleVerse @BibleId, 341001015, N'He said, “The time is fulfilled and the kingdom of God is near. Repent and believe the gospel!”'
EXEC add_BibleVerse @BibleId, 341001016, N'As he went along the Sea of Galilee, he saw Simon and Andrew, Simon’s brother, casting a net into the sea (for they were fishermen).'
EXEC add_BibleVerse @BibleId, 341001017, N'Jesus said to them, “Follow me, and I will turn you into fishers of people.”'
EXEC add_BibleVerse @BibleId, 341001018, N'They left their nets immediately and followed him.'
EXEC add_BibleVerse @BibleId, 341001019, N'Going on a little farther, he saw James, the son of Zebedee, and John his brother in their boat mending nets.'
EXEC add_BibleVerse @BibleId, 341001020, N'Immediately he called them, and they left their father Zebedee in the boat with the hired men and followed him.'
EXEC add_BibleVerse @BibleId, 341001021, N'Then they went to Capernaum. When the Sabbath came, Jesus went into the synagogue and began to teach.'
EXEC add_BibleVerse @BibleId, 341001022, N'The people there were amazed by his teaching, because he taught them like one who had authority, not like the experts in the law.'
EXEC add_BibleVerse @BibleId, 341001023, N'Just then there was a man in their synagogue with an unclean spirit, and he cried out,'
EXEC add_BibleVerse @BibleId, 341001024, N'“Leave us alone, Jesus the Nazarene! Have you come to destroy us? I know who you are – the Holy One of God!”'
EXEC add_BibleVerse @BibleId, 341001025, N'But Jesus rebuked him: “Silence! Come out of him!”'
EXEC add_BibleVerse @BibleId, 341001026, N'After throwing him into convulsions, the unclean spirit cried out with a loud voice and came out of him.'
EXEC add_BibleVerse @BibleId, 341001027, N'They were all amazed so that they asked each other, “What is this? A new teaching with authority! He even commands the unclean spirits and they obey him.”'
EXEC add_BibleVerse @BibleId, 341001028, N'So the news about him spread quickly throughout all the region around Galilee.'
EXEC add_BibleVerse @BibleId, 341001029, N'Now as soon as they left the synagogue, they entered Simon and Andrew’s house, with James and John.'
EXEC add_BibleVerse @BibleId, 341001030, N'Simon’s mother-in-law was lying down, sick with a fever, so they spoke to Jesus at once about her.'
EXEC add_BibleVerse @BibleId, 341001031, N'He came and raised her up by gently taking her hand. Then the fever left her and she began to serve them.'
EXEC add_BibleVerse @BibleId, 341001032, N'When it was evening, after sunset, they brought to him all who were sick and demon-possessed.'
EXEC add_BibleVerse @BibleId, 341001033, N'The whole town gathered by the door.'
EXEC add_BibleVerse @BibleId, 341001034, N'So he healed many who were sick with various diseases and drove out many demons. But he would not permit the demons to speak, because they knew him.'
EXEC add_BibleVerse @BibleId, 341001035, N'Then Jesus got up early in the morning when it was still very dark, departed, and went out to a deserted place, and there he spent time in prayer.'
EXEC add_BibleVerse @BibleId, 341001036, N'Simon and his companions searched for him.'
EXEC add_BibleVerse @BibleId, 341001037, N'When they found him, they said, “Everyone is looking for you.”'
EXEC add_BibleVerse @BibleId, 341001038, N'He replied, “Let us go elsewhere, into the surrounding villages, so that I can preach there too. For that is what I came out here to do.”'
EXEC add_BibleVerse @BibleId, 341001039, N'So he went into all of Galilee preaching in their synagogues and casting out demons.'
EXEC add_BibleVerse @BibleId, 341001040, N'Now a leper came to him and fell to his knees, asking for help. “If you are willing, you can make me clean,” he said.'
EXEC add_BibleVerse @BibleId, 341001041, N'Moved with compassion, Jesus stretched out his hand and touched him, saying, “I am willing. Be clean!”'
EXEC add_BibleVerse @BibleId, 341001042, N'The leprosy left him at once, and he was clean.'
EXEC add_BibleVerse @BibleId, 341001043, N'Immediately Jesus sent the man away with a very strong warning.'
EXEC add_BibleVerse @BibleId, 341001044, N'He told him, “See that you do not say anything to anyone, but go, show yourself to a priest, and bring the offering that Moses commanded for your cleansing, as a testimony to them.”'
EXEC add_BibleVerse @BibleId, 341001045, N'But as the man went out he began to announce it publicly and spread the story widely, so that Jesus was no longer able to enter any town openly but stayed outside in remote places. Still they kept coming to him from everywhere.'
EXEC add_BibleVerse @BibleId, 341002001, N'Now after some days, when he returned to Capernaum, the news spread that he was at home.'
EXEC add_BibleVerse @BibleId, 341002002, N'So many gathered that there was no longer any room, not even by the door, and he preached the word to them.'
EXEC add_BibleVerse @BibleId, 341002003, N'Some people came bringing to him a paralytic, carried by four of them.'
EXEC add_BibleVerse @BibleId, 341002004, N'When they were not able to bring him in because of the crowd, they removed the roof above Jesus. Then, after tearing it out, they lowered the stretcher the paralytic was lying on.'
EXEC add_BibleVerse @BibleId, 341002005, N'When Jesus saw their faith, he said to the paralytic, “Son, your sins are forgiven.”'
EXEC add_BibleVerse @BibleId, 341002006, N'Now some of the experts in the law were sitting there, turning these things over in their minds:'
EXEC add_BibleVerse @BibleId, 341002007, N'“Why does this man speak this way? He is blaspheming! Who can forgive sins but God alone?”'
EXEC add_BibleVerse @BibleId, 341002008, N'Now immediately, when Jesus realized in his spirit that they were contemplating such thoughts, he said to them, “Why are you thinking such things in your hearts?'
EXEC add_BibleVerse @BibleId, 341002009, N'Which is easier, to say to the paralytic, ‘Your sins are forgiven,’ or to say, ‘Stand up, take your stretcher, and walk’?'
EXEC add_BibleVerse @BibleId, 341002010, N'But so that you may know that the Son of Man has authority on earth to forgive sins,” – he said to the paralytic –'
EXEC add_BibleVerse @BibleId, 341002011, N'“I tell you, stand up, take your stretcher, and go home.”'
EXEC add_BibleVerse @BibleId, 341002012, N'And immediately the man stood up, took his stretcher, and went out in front of them all. They were all amazed and glorified God, saying, “We have never seen anything like this!”'
EXEC add_BibleVerse @BibleId, 341002013, N'Jesus went out again by the sea. The whole crowd came to him, and he taught them.'
EXEC add_BibleVerse @BibleId, 341002014, N'As he went along, he saw Levi, the son of Alphaeus, sitting at the tax booth. “Follow me,” he said to him. And he got up and followed him.'
EXEC add_BibleVerse @BibleId, 341002015, N'As Jesus was having a meal in Levi’s home, many tax collectors and sinners were eating with Jesus and his disciples, for there were many who followed him.'
EXEC add_BibleVerse @BibleId, 341002016, N'When the experts in the law and the Pharisees saw that he was eating with sinners and tax collectors, they said to his disciples, “Why does he eat with tax collectors and sinners?”'
EXEC add_BibleVerse @BibleId, 341002017, N'When Jesus heard this he said to them, “Those who are healthy don’t need a physician, but those who are sick do. I have not come to call the righteous, but sinners.”'
EXEC add_BibleVerse @BibleId, 341002018, N'Now John’s disciples and the Pharisees were fasting. So they came to Jesus and said, “Why do the disciples of John and the disciples of the Pharisees fast, but your disciples don’t fast?”'
EXEC add_BibleVerse @BibleId, 341002019, N'Jesus said to them, “The wedding guests cannot fast while the bridegroom is with them, can they? As long as they have the bridegroom with them they do not fast.'
EXEC add_BibleVerse @BibleId, 341002020, N'But the days are coming when the bridegroom will be taken from them, and at that time they will fast.'
EXEC add_BibleVerse @BibleId, 341002021, N'No one sews a patch of unshrunk cloth on an old garment; otherwise, the patch pulls away from it, the new from the old, and the tear becomes worse.'
EXEC add_BibleVerse @BibleId, 341002022, N'And no one pours new wine into old wineskins; otherwise, the wine will burst the skins, and both the wine and the skins will be destroyed. Instead new wine is poured into new wineskins.”'
EXEC add_BibleVerse @BibleId, 341002023, N'Jesus was going through the grain fields on a Sabbath, and his disciples began to pick some heads of wheat as they made their way.'
EXEC add_BibleVerse @BibleId, 341002024, N'So the Pharisees said to him, “Look, why are they doing what is against the law on the Sabbath?”'
EXEC add_BibleVerse @BibleId, 341002025, N'He said to them, “Have you never read what David did when he was in need and he and his companions were hungry –'
EXEC add_BibleVerse @BibleId, 341002026, N'how he entered the house of God when Abiathar was high priest and ate the sacred bread, which is against the law for any but the priests to eat, and also gave it to his companions?”'
EXEC add_BibleVerse @BibleId, 341002027, N'Then he said to them, “The Sabbath was made for people, not people for the Sabbath.'
EXEC add_BibleVerse @BibleId, 341002028, N'For this reason the Son of Man is lord even of the Sabbath.”'
EXEC add_BibleVerse @BibleId, 341003001, N'Then Jesus entered the synagogue again, and a man was there who had a withered hand.'
EXEC add_BibleVerse @BibleId, 341003002, N'They watched Jesus closely to see if he would heal him on the Sabbath, so that they could accuse him.'
EXEC add_BibleVerse @BibleId, 341003003, N'So he said to the man who had the withered hand, “Stand up among all these people.”'
EXEC add_BibleVerse @BibleId, 341003004, N'Then he said to them, “Is it lawful to do good on the Sabbath, or evil, to save a life or destroy it?” But they were silent.'
EXEC add_BibleVerse @BibleId, 341003005, N'After looking around at them in anger, grieved by the hardness of their hearts, he said to the man, “Stretch out your hand.” He stretched it out, and his hand was restored.'
EXEC add_BibleVerse @BibleId, 341003006, N'So the Pharisees went out immediately and began plotting with the Herodians, as to how they could assassinate him.'
EXEC add_BibleVerse @BibleId, 341003007, N'Then Jesus went away with his disciples to the sea, and a great multitude from Galilee followed him. And from Judea,'
EXEC add_BibleVerse @BibleId, 341003008, N'Jerusalem, a great multitude came to him when they heard about the things he had done.'
EXEC add_BibleVerse @BibleId, 341003009, N'Because of the crowd, he told his disciples to have a small boat ready for him so the crowd would not press toward him.'
EXEC add_BibleVerse @BibleId, 341003010, N'For he had healed many, so that all who were afflicted with diseases pressed toward him in order to touch him.'
EXEC add_BibleVerse @BibleId, 341003011, N'And whenever the unclean spirits saw him, they fell down before him and cried out, “You are the Son of God.”'
EXEC add_BibleVerse @BibleId, 341003012, N'But he sternly ordered them not to make him known.'
EXEC add_BibleVerse @BibleId, 341003013, N'Now Jesus went up the mountain and called for those he wanted, and they came to him.'
EXEC add_BibleVerse @BibleId, 341003014, N'He appointed twelve (whom he named apostles ), so that they would be with him and he could send them to preach'
EXEC add_BibleVerse @BibleId, 341003015, N'and to have authority to cast out demons.'
EXEC add_BibleVerse @BibleId, 341003016, N'He appointed twelve: To Simon he gave the name Peter;'
EXEC add_BibleVerse @BibleId, 341003017, N'to James and his brother John, the sons of Zebedee, he gave the name Boanerges (that is, “sons of thunder”);'
EXEC add_BibleVerse @BibleId, 341003018, N'and Andrew, Philip, Bartholomew, Matthew, Thomas, James the son of Alphaeus, Thaddaeus, Simon the Zealot,'
EXEC add_BibleVerse @BibleId, 341003019, N'and Judas Iscariot, who betrayed him.'
EXEC add_BibleVerse @BibleId, 341003020, N'Now Jesus went home, and a crowd gathered so that they were not able to eat.'
EXEC add_BibleVerse @BibleId, 341003021, N'When his family heard this they went out to restrain him, for they said, “He is out of his mind.”'
EXEC add_BibleVerse @BibleId, 341003022, N'The experts in the law who came down from Jerusalem said, “He is possessed by Beelzebul,” and, “By the ruler of demons he casts out demons.”'
EXEC add_BibleVerse @BibleId, 341003023, N'So he called them and spoke to them in parables: “How can Satan cast out Satan?'
EXEC add_BibleVerse @BibleId, 341003024, N'If a kingdom is divided against itself, that kingdom will not be able to stand.'
EXEC add_BibleVerse @BibleId, 341003025, N'If a house is divided against itself, that house will not be able to stand.'
EXEC add_BibleVerse @BibleId, 341003026, N'And if Satan rises against himself and is divided, he is not able to stand and his end has come.'
EXEC add_BibleVerse @BibleId, 341003027, N'But no one is able to enter a strong man’s house and steal his property unless he first ties up the strong man. Then he can thoroughly plunder his house.'
EXEC add_BibleVerse @BibleId, 341003028, N'I tell you the truth, people will be forgiven for all sins, even all the blasphemies they utter.'
EXEC add_BibleVerse @BibleId, 341003029, N'But whoever blasphemes against the Holy Spirit will never be forgiven, but is guilty of an eternal sin”'
EXEC add_BibleVerse @BibleId, 341003030, N'(because they said, “He has an unclean spirit” ).'
EXEC add_BibleVerse @BibleId, 341003031, N'Then Jesus’ mother and his brothers came. Standing outside, they sent word to him, to summon him.'
EXEC add_BibleVerse @BibleId, 341003032, N'A crowd was sitting around him and they said to him, “Look, your mother and your brothers are outside looking for you.”'
EXEC add_BibleVerse @BibleId, 341003033, N'He answered them and said, “Who are my mother and my brothers?”'
EXEC add_BibleVerse @BibleId, 341003034, N'And looking at those who were sitting around him in a circle, he said, “Here are my mother and my brothers!'
EXEC add_BibleVerse @BibleId, 341003035, N'For whoever does the will of God is my brother and sister and mother.”'
EXEC add_BibleVerse @BibleId, 341004001, N'Again he began to teach by the lake. Such a large crowd gathered around him that he got into a boat on the lake and sat there while the whole crowd was on the shore by the lake.'
EXEC add_BibleVerse @BibleId, 341004002, N'He taught them many things in parables, and in his teaching said to them:'
EXEC add_BibleVerse @BibleId, 341004003, N'“Listen! A sower went out to sow.'
EXEC add_BibleVerse @BibleId, 341004004, N'And as he sowed, some seed fell along the path, and the birds came and devoured it.'
EXEC add_BibleVerse @BibleId, 341004005, N'Other seed fell on rocky ground where it did not have much soil. It sprang up at once because the soil was not deep.'
EXEC add_BibleVerse @BibleId, 341004006, N'When the sun came up it was scorched, and because it did not have sufficient root, it withered.'
EXEC add_BibleVerse @BibleId, 341004007, N'Other seed fell among the thorns, and they grew up and choked it, and it did not produce grain.'
EXEC add_BibleVerse @BibleId, 341004008, N'But other seed fell on good soil and produced grain, sprouting and growing; some yielded thirty times as much, some sixty, and some a hundred times.”'
EXEC add_BibleVerse @BibleId, 341004009, N'And he said, “Whoever has ears to hear had better listen!”'
EXEC add_BibleVerse @BibleId, 341004010, N'When he was alone, those around him with the twelve asked him about the parables.'
EXEC add_BibleVerse @BibleId, 341004011, N'He said to them, “The secret of the kingdom of God has been given to you. But to those outside, everything is in parables,'
EXEC add_BibleVerse @BibleId, 341004012, N'so that although they look they may look but not see, and although they hear they may hear but not understand, so they may not repent and be forgiven.”'
EXEC add_BibleVerse @BibleId, 341004013, N'He said to them, “Don’t you understand this parable? Then how will you understand any parable?'
EXEC add_BibleVerse @BibleId, 341004014, N'The sower sows the word.'
EXEC add_BibleVerse @BibleId, 341004015, N'These are the ones on the path where the word is sown: Whenever they hear, immediately Satan comes and snatches the word that was sown in them.'
EXEC add_BibleVerse @BibleId, 341004016, N'These are the ones sown on rocky ground: As soon as they hear the word, they receive it with joy.'
EXEC add_BibleVerse @BibleId, 341004017, N'But they have no root in themselves and do not endure. Then, when trouble or persecution comes because of the word, immediately they fall away.'
EXEC add_BibleVerse @BibleId, 341004018, N'Others are the ones sown among thorns: They are those who hear the word,'
EXEC add_BibleVerse @BibleId, 341004019, N'but worldly cares, the seductiveness of wealth, and the desire for other things come in and choke the word, and it produces nothing.'
EXEC add_BibleVerse @BibleId, 341004020, N'But these are the ones sown on good soil: They hear the word and receive it and bear fruit, one thirty times as much, one sixty, and one a hundred.”'
EXEC add_BibleVerse @BibleId, 341004021, N'He also said to them, “A lamp isn’t brought to be put under a basket or under a bed, is it? Isn’t it to be placed on a lampstand?'
EXEC add_BibleVerse @BibleId, 341004022, N'For nothing is hidden except to be revealed, and nothing concealed except to be brought to light.'
EXEC add_BibleVerse @BibleId, 341004023, N'If anyone has ears to hear, he had better listen!”'
EXEC add_BibleVerse @BibleId, 341004024, N'And he said to them, “Take care about what you hear. The measure you use will be the measure you receive, and more will be added to you.'
EXEC add_BibleVerse @BibleId, 341004025, N'For whoever has will be given more, but whoever does not have, even what he has will be taken from him.”'
EXEC add_BibleVerse @BibleId, 341004026, N'He also said, “The kingdom of God is like someone who spreads seed on the ground.'
EXEC add_BibleVerse @BibleId, 341004027, N'He goes to sleep and gets up, night and day, and the seed sprouts and grows, though he does not know how.'
EXEC add_BibleVerse @BibleId, 341004028, N'By itself the soil produces a crop, first the stalk, then the head, then the full grain in the head.'
EXEC add_BibleVerse @BibleId, 341004029, N'And when the grain is ripe, he sends in the sickle because the harvest has come.”'
EXEC add_BibleVerse @BibleId, 341004030, N'He also asked, “To what can we compare the kingdom of God, or what parable can we use to present it?'
EXEC add_BibleVerse @BibleId, 341004031, N'It is like a mustard seed that when sown in the ground, even though it is the smallest of all the seeds in the ground –'
EXEC add_BibleVerse @BibleId, 341004032, N'when it is sown, it grows up, becomes the greatest of all garden plants, and grows large branches so that the wild birds can nest in its shade.”'
EXEC add_BibleVerse @BibleId, 341004033, N'So with many parables like these, he spoke the word to them, as they were able to hear.'
EXEC add_BibleVerse @BibleId, 341004034, N'He did not speak to them without a parable. But privately he explained everything to his own disciples.'
EXEC add_BibleVerse @BibleId, 341004035, N'On that day, when evening came, Jesus said to his disciples, “Let’s go across to the other side of the lake.”'
EXEC add_BibleVerse @BibleId, 341004036, N'So after leaving the crowd, they took him along, just as he was, in the boat, and other boats were with him.'
EXEC add_BibleVerse @BibleId, 341004037, N'Now a great windstorm developed and the waves were breaking into the boat, so that the boat was nearly swamped.'
EXEC add_BibleVerse @BibleId, 341004038, N'But he was in the stern, sleeping on a cushion. They woke him up and said to him, “Teacher, don’t you care that we are about to die?”'
EXEC add_BibleVerse @BibleId, 341004039, N'So he got up and rebuked the wind, and said to the sea, “Be quiet! Calm down!” Then the wind stopped, and it was dead calm.'
EXEC add_BibleVerse @BibleId, 341004040, N'And he said to them, “Why are you cowardly? Do you still not have faith?”'
EXEC add_BibleVerse @BibleId, 341004041, N'They were overwhelmed by fear and said to one another, “Who then is this? Even the wind and sea obey him!”'
EXEC add_BibleVerse @BibleId, 341005001, N'So they came to the other side of the lake, to the region of the Gerasenes.'
EXEC add_BibleVerse @BibleId, 341005002, N'Just as Jesus was getting out of the boat, a man with an unclean spirit came from the tombs and met him.'
EXEC add_BibleVerse @BibleId, 341005003, N'He lived among the tombs, and no one could bind him anymore, not even with a chain.'
EXEC add_BibleVerse @BibleId, 341005004, N'For his hands and feet had often been bound with chains and shackles, but he had torn the chains apart and broken the shackles in pieces. No one was strong enough to subdue him.'
EXEC add_BibleVerse @BibleId, 341005005, N'Each night and every day among the tombs and in the mountains, he would cry out and cut himself with stones.'
EXEC add_BibleVerse @BibleId, 341005006, N'When he saw Jesus from a distance, he ran and bowed down before him.'
EXEC add_BibleVerse @BibleId, 341005007, N'Then he cried out with a loud voice, “Leave me alone, Jesus, Son of the Most High God! I implore you by God – do not torment me!”'
EXEC add_BibleVerse @BibleId, 341005008, N'(For Jesus had said to him, “Come out of that man, you unclean spirit!”)'
EXEC add_BibleVerse @BibleId, 341005009, N'Jesus asked him, “What is your name?” And he said, “My name is Legion, for we are many.”'
EXEC add_BibleVerse @BibleId, 341005010, N'He begged Jesus repeatedly not to send them out of the region.'
EXEC add_BibleVerse @BibleId, 341005011, N'There on the hillside, a great herd of pigs was feeding.'
EXEC add_BibleVerse @BibleId, 341005012, N'And the demonic spirits begged him, “Send us into the pigs. Let us enter them.”'
EXEC add_BibleVerse @BibleId, 341005013, N'Jesus gave them permission. So the unclean spirits came out and went into the pigs. Then the herd rushed down the steep slope into the lake, and about two thousand were drowned in the lake.'
EXEC add_BibleVerse @BibleId, 341005014, N'Now the herdsmen ran off and spread the news in the town and countryside, and the people went out to see what had happened.'
EXEC add_BibleVerse @BibleId, 341005015, N'They came to Jesus and saw the demon-possessed man sitting there, clothed and in his right mind – the one who had the “Legion” – and they were afraid.'
EXEC add_BibleVerse @BibleId, 341005016, N'Those who had seen what had happened to the demon-possessed man reported it, and they also told about the pigs.'
EXEC add_BibleVerse @BibleId, 341005017, N'Then they asked Jesus to leave their region.'
EXEC add_BibleVerse @BibleId, 341005018, N'As he was getting into the boat the man who had been demon-possessed asked if he could go with him.'
EXEC add_BibleVerse @BibleId, 341005019, N'But Jesus did not permit him to do so. Instead, he said to him, “Go to your home and to your people and tell them what the Lord has done for you, that he had mercy on you.”'
EXEC add_BibleVerse @BibleId, 341005020, N'So he went away and began to proclaim in the Decapolis what Jesus had done for him, and all were amazed.'
EXEC add_BibleVerse @BibleId, 341005021, N'When Jesus had crossed again in a boat to the other side, a large crowd gathered around him, and he was by the sea.'
EXEC add_BibleVerse @BibleId, 341005022, N'Then one of the synagogue rulers, named Jairus, came up, and when he saw Jesus, he fell at his feet.'
EXEC add_BibleVerse @BibleId, 341005023, N'He asked him urgently, “My little daughter is near death. Come and lay your hands on her so that she may be healed and live.”'
EXEC add_BibleVerse @BibleId, 341005024, N'Jesus went with him, and a large crowd followed and pressed around him.'
EXEC add_BibleVerse @BibleId, 341005025, N'Now a woman was there who had been suffering from a hemorrhage for twelve years.'
EXEC add_BibleVerse @BibleId, 341005026, N'She had endured a great deal under the care of many doctors and had spent all that she had. Yet instead of getting better, she grew worse.'
EXEC add_BibleVerse @BibleId, 341005027, N'When she heard about Jesus, she came up behind him in the crowd and touched his cloak,'
EXEC add_BibleVerse @BibleId, 341005028, N'for she kept saying, “If only I touch his clothes, I will be healed.”'
EXEC add_BibleVerse @BibleId, 341005029, N'At once the bleeding stopped, and she felt in her body that she was healed of her disease.'
EXEC add_BibleVerse @BibleId, 341005030, N'Jesus knew at once that power had gone out from him. He turned around in the crowd and said, “Who touched my clothes?”'
EXEC add_BibleVerse @BibleId, 341005031, N'His disciples said to him, “You see the crowd pressing against you and you say, ‘Who touched me?’”'
EXEC add_BibleVerse @BibleId, 341005032, N'But he looked around to see who had done it.'
EXEC add_BibleVerse @BibleId, 341005033, N'Then the woman, with fear and trembling, knowing what had happened to her, came and fell down before him and told him the whole truth.'
EXEC add_BibleVerse @BibleId, 341005034, N'He said to her, “Daughter, your faith has made you well. Go in peace, and be healed of your disease.”'
EXEC add_BibleVerse @BibleId, 341005035, N'While he was still speaking, people came from the synagogue ruler’s house saying, “Your daughter has died. Why trouble the teacher any longer?”'
EXEC add_BibleVerse @BibleId, 341005036, N'But Jesus, paying no attention to what was said, told the synagogue ruler, “Do not be afraid; just believe.”'
EXEC add_BibleVerse @BibleId, 341005037, N'He did not let anyone follow him except Peter, James, and John, the brother of James.'
EXEC add_BibleVerse @BibleId, 341005038, N'They came to the house of the synagogue ruler where he saw noisy confusion and people weeping and wailing loudly.'
EXEC add_BibleVerse @BibleId, 341005039, N'When he entered he said to them, “Why are you distressed and weeping? The child is not dead but asleep.”'
EXEC add_BibleVerse @BibleId, 341005040, N'And they began making fun of him. But he put them all outside and he took the child’s father and mother and his own companions and went into the room where the child was.'
EXEC add_BibleVerse @BibleId, 341005041, N'Then, gently taking the child by the hand, he said to her, “ Talitha koum,” which means, “Little girl, I say to you, get up.”'
EXEC add_BibleVerse @BibleId, 341005042, N'The girl got up at once and began to walk around (she was twelve years old). They were completely astonished at this.'
EXEC add_BibleVerse @BibleId, 341005043, N'He strictly ordered that no one should know about this, and told them to give her something to eat.'
EXEC add_BibleVerse @BibleId, 341006001, N'Now Jesus left that place and came to his hometown, and his disciples followed him.'
EXEC add_BibleVerse @BibleId, 341006002, N'When the Sabbath came, he began to teach in the synagogue. Many who heard him were astonished, saying, “Where did he get these ideas? And what is this wisdom that has been given to him? What are these miracles that are done through his hands?'
EXEC add_BibleVerse @BibleId, 341006003, N'Isn’t this the carpenter, the son of Mary and brother of James, Joses, Judas, and Simon? And aren’t his sisters here with us?” And so they took offense at him.'
EXEC add_BibleVerse @BibleId, 341006004, N'Then Jesus said to them, “A prophet is not without honor except in his hometown, and among his relatives, and in his own house.”'
EXEC add_BibleVerse @BibleId, 341006005, N'He was not able to do a miracle there, except to lay his hands on a few sick people and heal them.'
EXEC add_BibleVerse @BibleId, 341006006, N'And he was amazed because of their unbelief. Then he went around among the villages and taught.'
EXEC add_BibleVerse @BibleId, 341006007, N'Jesus called the twelve and began to send them out two by two. He gave them authority over the unclean spirits.'
EXEC add_BibleVerse @BibleId, 341006008, N'He instructed them to take nothing for the journey except a staff – no bread, no bag, no money in their belts –'
EXEC add_BibleVerse @BibleId, 341006009, N'and to put on sandals but not to wear two tunics.'
EXEC add_BibleVerse @BibleId, 341006010, N'He said to them, “Wherever you enter a house, stay there until you leave the area.'
EXEC add_BibleVerse @BibleId, 341006011, N'If a place will not welcome you or listen to you, as you go out from there, shake the dust off your feet as a testimony against them.”'
EXEC add_BibleVerse @BibleId, 341006012, N'So they went out and preached that all should repent.'
EXEC add_BibleVerse @BibleId, 341006013, N'They cast out many demons and anointed many sick people with oil and healed them.'
EXEC add_BibleVerse @BibleId, 341006014, N'Now King Herod heard this, for Jesus’ name had become known. Some were saying, “John the baptizer has been raised from the dead, and because of this, miraculous powers are at work in him.”'
EXEC add_BibleVerse @BibleId, 341006015, N'Others said, “He is Elijah.” Others said, “He is a prophet, like one of the prophets from the past.”'
EXEC add_BibleVerse @BibleId, 341006016, N'But when Herod heard this, he said, “John, whom I beheaded, has been raised!”'
EXEC add_BibleVerse @BibleId, 341006017, N'For Herod himself had sent men, arrested John, and bound him in prison on account of Herodias, his brother Philip’s wife, because Herod had married her.'
EXEC add_BibleVerse @BibleId, 341006018, N'For John had repeatedly told Herod, “It is not lawful for you to have your brother’s wife.”'
EXEC add_BibleVerse @BibleId, 341006019, N'So Herodias nursed a grudge against him and wanted to kill him. But she could not'
EXEC add_BibleVerse @BibleId, 341006020, N'because Herod stood in awe of John and protected him, since he knew that John was a righteous and holy man. When Herod heard him, he was thoroughly baffled, and yet he liked to listen to John.'
EXEC add_BibleVerse @BibleId, 341006021, N'But a suitable day came, when Herod gave a banquet on his birthday for his court officials, military commanders, and leaders of Galilee.'
EXEC add_BibleVerse @BibleId, 341006022, N'When his daughter Herodias came in and danced, she pleased Herod and his dinner guests. The king said to the girl, “Ask me for whatever you want and I will give it to you.”'
EXEC add_BibleVerse @BibleId, 341006023, N'He swore to her, “Whatever you ask I will give you, up to half my kingdom.”'
EXEC add_BibleVerse @BibleId, 341006024, N'So she went out and said to her mother, “What should I ask for?” Her mother said, “The head of John the baptizer.”'
EXEC add_BibleVerse @BibleId, 341006025, N'Immediately she hurried back to the king and made her request: “I want the head of John the Baptist on a platter immediately.”'
EXEC add_BibleVerse @BibleId, 341006026, N'Although it grieved the king deeply, he did not want to reject her request because of his oath and his guests.'
EXEC add_BibleVerse @BibleId, 341006027, N'So the king sent an executioner at once to bring John’s head, and he went and beheaded John in prison.'
EXEC add_BibleVerse @BibleId, 341006028, N'He brought his head on a platter and gave it to the girl, and the girl gave it to her mother.'
EXEC add_BibleVerse @BibleId, 341006029, N'When John’s disciples heard this, they came and took his body and placed it in a tomb.'
EXEC add_BibleVerse @BibleId, 341006030, N'Then the apostles gathered around Jesus and told him everything they had done and taught.'
EXEC add_BibleVerse @BibleId, 341006031, N'He said to them, “Come with me privately to an isolated place and rest a while” (for many were coming and going, and there was no time to eat).'
EXEC add_BibleVerse @BibleId, 341006032, N'So they went away by themselves in a boat to some remote place.'
EXEC add_BibleVerse @BibleId, 341006033, N'But many saw them leaving and recognized them, and they hurried on foot from all the towns and arrived there ahead of them.'
EXEC add_BibleVerse @BibleId, 341006034, N'As Jesus came ashore he saw the large crowd and he had compassion on them, because they were like sheep without a shepherd. So he taught them many things.'
EXEC add_BibleVerse @BibleId, 341006035, N'When it was already late, his disciples came to him and said, “This is an isolated place and it is already very late.'
EXEC add_BibleVerse @BibleId, 341006036, N'Send them away so that they can go into the surrounding countryside and villages and buy something for themselves to eat.”'
EXEC add_BibleVerse @BibleId, 341006037, N'But he answered them, “You give them something to eat.” And they said, “Should we go and buy bread for two hundred silver coins and give it to them to eat?”'
EXEC add_BibleVerse @BibleId, 341006038, N'He said to them, “How many loaves do you have? Go and see.” When they found out, they said, “Five – and two fish.”'
EXEC add_BibleVerse @BibleId, 341006039, N'Then he directed them all to sit down in groups on the green grass.'
EXEC add_BibleVerse @BibleId, 341006040, N'So they reclined in groups of hundreds and fifties.'
EXEC add_BibleVerse @BibleId, 341006041, N'He took the five loaves and the two fish, and looking up to heaven, he gave thanks and broke the loaves. He gave them to his disciples to serve the people, and he divided the two fish among them all.'
EXEC add_BibleVerse @BibleId, 341006042, N'They all ate and were satisfied,'
EXEC add_BibleVerse @BibleId, 341006043, N'and they picked up the broken pieces and fish that were left over, twelve baskets full.'
EXEC add_BibleVerse @BibleId, 341006044, N'Now there were five thousand men who ate the bread.'
EXEC add_BibleVerse @BibleId, 341006045, N'Immediately Jesus made his disciples get into the boat and go on ahead to the other side, to Bethsaida, while he dispersed the crowd.'
EXEC add_BibleVerse @BibleId, 341006046, N'After saying good-bye to them, he went to the mountain to pray.'
EXEC add_BibleVerse @BibleId, 341006047, N'When evening came, the boat was in the middle of the sea and he was alone on the land.'
EXEC add_BibleVerse @BibleId, 341006048, N'He saw them straining at the oars, because the wind was against them. As the night was ending, he came to them walking on the sea, for he wanted to pass by them.'
EXEC add_BibleVerse @BibleId, 341006049, N'When they saw him walking on the water they thought he was a ghost. They cried out,'
EXEC add_BibleVerse @BibleId, 341006050, N'for they all saw him and were terrified. But immediately he spoke to them: “Have courage! It is I. Do not be afraid.”'
EXEC add_BibleVerse @BibleId, 341006051, N'Then he went up with them into the boat, and the wind ceased. They were completely astonished,'
EXEC add_BibleVerse @BibleId, 341006052, N'because they did not understand about the loaves, but their hearts were hardened.'
EXEC add_BibleVerse @BibleId, 341006053, N'After they had crossed over, they came to land at Gennesaret and anchored there.'
EXEC add_BibleVerse @BibleId, 341006054, N'As they got out of the boat, people immediately recognized Jesus.'
EXEC add_BibleVerse @BibleId, 341006055, N'They ran through that whole region and began to bring the sick on mats to wherever he was rumored to be.'
EXEC add_BibleVerse @BibleId, 341006056, N'And wherever he would go – into villages, towns, or countryside – they would place the sick in the marketplaces, and would ask him if they could just touch the edge of his cloak, and all who touched it were healed.'
EXEC add_BibleVerse @BibleId, 341007001, N'Now the Pharisees and some of the experts in the law who came from Jerusalem gathered around him.'
EXEC add_BibleVerse @BibleId, 341007002, N'And they saw that some of Jesus’ disciples ate their bread with unclean hands, that is, unwashed.'
EXEC add_BibleVerse @BibleId, 341007003, N'(For the Pharisees and all the Jews do not eat unless they perform a ritual washing, holding fast to the tradition of the elders.'
EXEC add_BibleVerse @BibleId, 341007004, N'And when they come from the marketplace, they do not eat unless they wash. They hold fast to many other traditions: the washing of cups, pots, kettles, and dining couches. )'
EXEC add_BibleVerse @BibleId, 341007005, N'The Pharisees and the experts in the law asked him, “Why do your disciples not live according to the tradition of the elders, but eat with unwashed hands?”'
EXEC add_BibleVerse @BibleId, 341007006, N'He said to them, “Isaiah prophesied correctly about you hypocrites, as it is written: ‘ This people honors me with their lips, but their heart is far from me.'
EXEC add_BibleVerse @BibleId, 341007007, N'They worship me in vain, teaching as doctrine the commandments of men.’'
EXEC add_BibleVerse @BibleId, 341007008, N'Having no regard for the command of God, you hold fast to human tradition.”'
EXEC add_BibleVerse @BibleId, 341007009, N'He also said to them, “You neatly reject the commandment of God in order to set up your tradition.'
EXEC add_BibleVerse @BibleId, 341007010, N'For Moses said, ‘ Honor your father and your mother,’ and, ‘ Whoever insults his father or mother must be put to death.’'
EXEC add_BibleVerse @BibleId, 341007011, N'But you say that if anyone tells his father or mother, ‘Whatever help you would have received from me is corban’ (that is, a gift for God),'
EXEC add_BibleVerse @BibleId, 341007012, N'then you no longer permit him to do anything for his father or mother.'
EXEC add_BibleVerse @BibleId, 341007013, N'Thus you nullify the word of God by your tradition that you have handed down. And you do many things like this.”'
EXEC add_BibleVerse @BibleId, 341007014, N'Then he called the crowd again and said to them, “Listen to me, everyone, and understand.'
EXEC add_BibleVerse @BibleId, 341007015, N'There is nothing outside of a person that can defile him by going into him. Rather, it is what comes out of a person that defiles him.”'
EXEC add_BibleVerse @BibleId, 341007017, N' Now when Jesus had left the crowd and entered the house, his disciples asked him about the parable.'
EXEC add_BibleVerse @BibleId, 341007018, N'He said to them, “Are you so foolish? Don’t you understand that whatever goes into a person from outside cannot defile him?'
EXEC add_BibleVerse @BibleId, 341007019, N'For it does not enter his heart but his stomach, and then goes out into the sewer.” (This means all foods are clean.)'
EXEC add_BibleVerse @BibleId, 341007020, N'He said, “What comes out of a person defiles him.'
EXEC add_BibleVerse @BibleId, 341007021, N'For from within, out of the human heart, come evil ideas, sexual immorality, theft, murder,'
EXEC add_BibleVerse @BibleId, 341007022, N'adultery, greed, evil, deceit, debauchery, envy, slander, pride, and folly.'
EXEC add_BibleVerse @BibleId, 341007023, N'All these evils come from within and defile a person.”'
EXEC add_BibleVerse @BibleId, 341007024, N'After Jesus left there, he went to the region of Tyre. When he went into a house, he did not want anyone to know, but he was not able to escape notice.'
EXEC add_BibleVerse @BibleId, 341007025, N'Instead, a woman whose young daughter had an unclean spirit immediately heard about him and came and fell at his feet.'
EXEC add_BibleVerse @BibleId, 341007026, N'The woman was a Greek, of Syrophoenician origin. She asked him to cast the demon out of her daughter.'
EXEC add_BibleVerse @BibleId, 341007027, N'He said to her, “Let the children be satisfied first, for it is not right to take the children’s bread and to throw it to the dogs.”'
EXEC add_BibleVerse @BibleId, 341007028, N'She answered, “Yes, Lord, but even the dogs under the table eat the children’s crumbs.”'
EXEC add_BibleVerse @BibleId, 341007029, N'Then he said to her, “Because you said this, you may go. The demon has left your daughter.”'
EXEC add_BibleVerse @BibleId, 341007030, N'She went home and found the child lying on the bed, and the demon gone.'
EXEC add_BibleVerse @BibleId, 341007031, N'Then Jesus went out again from the region of Tyre to the Sea of Galilee in the region of the Decapolis.'
EXEC add_BibleVerse @BibleId, 341007032, N'They brought to him a deaf man who had difficulty speaking, and they asked him to place his hands on him.'
EXEC add_BibleVerse @BibleId, 341007033, N'After Jesus took him aside privately, away from the crowd, he put his fingers in the man’s ears, and after spitting, he touched his tongue.'
EXEC add_BibleVerse @BibleId, 341007034, N'Then he looked up to heaven and said with a sigh, “ Ephphatha” (that is, “Be opened”).'
EXEC add_BibleVerse @BibleId, 341007035, N'And immediately the man’s ears were opened, his tongue loosened, and he spoke plainly.'
EXEC add_BibleVerse @BibleId, 341007036, N'Jesus ordered them not to tell anything. But as much as he ordered them not to do this, they proclaimed it all the more.'
EXEC add_BibleVerse @BibleId, 341007037, N'People were completely astounded and said, “He has done everything well. He even makes the deaf hear and the mute speak.”'
EXEC add_BibleVerse @BibleId, 341008001, N'In those days there was another large crowd with nothing to eat. So Jesus called his disciples and said to them,'
EXEC add_BibleVerse @BibleId, 341008002, N'“I have compassion on the crowd, because they have already been here with me three days, and they have nothing to eat.'
EXEC add_BibleVerse @BibleId, 341008003, N'If I send them home hungry, they will faint on the way, and some of them have come from a great distance.”'
EXEC add_BibleVerse @BibleId, 341008004, N'His disciples answered him, “Where can someone get enough bread in this desolate place to satisfy these people?”'
EXEC add_BibleVerse @BibleId, 341008005, N'He asked them, “How many loaves do you have?” They replied, “Seven.”'
EXEC add_BibleVerse @BibleId, 341008006, N'Then he directed the crowd to sit down on the ground. After he took the seven loaves and gave thanks, he broke them and began giving them to the disciples to serve. So they served the crowd.'
EXEC add_BibleVerse @BibleId, 341008007, N'They also had a few small fish. After giving thanks for these, he told them to serve these as well.'
EXEC add_BibleVerse @BibleId, 341008008, N'Everyone ate and was satisfied, and they picked up the broken pieces left over, seven baskets full.'
EXEC add_BibleVerse @BibleId, 341008009, N'There were about four thousand who ate. Then he dismissed them.'
EXEC add_BibleVerse @BibleId, 341008010, N'Immediately he got into a boat with his disciples and went to the district of Dalmanutha.'
EXEC add_BibleVerse @BibleId, 341008011, N'Then the Pharisees came and began to argue with Jesus, asking for a sign from heaven to test him.'
EXEC add_BibleVerse @BibleId, 341008012, N'Sighing deeply in his spirit he said, “Why does this generation look for a sign? I tell you the truth, no sign will be given to this generation.”'
EXEC add_BibleVerse @BibleId, 341008013, N'Then he left them, got back into the boat, and went to the other side.'
EXEC add_BibleVerse @BibleId, 341008014, N'Now they had forgotten to take bread, except for one loaf they had with them in the boat.'
EXEC add_BibleVerse @BibleId, 341008015, N'And Jesus ordered them, “Watch out! Beware of the yeast of the Pharisees and the yeast of Herod!”'
EXEC add_BibleVerse @BibleId, 341008016, N'So they began to discuss with one another about having no bread.'
EXEC add_BibleVerse @BibleId, 341008017, N'When he learned of this, Jesus said to them, “Why are you arguing about having no bread? Do you still not see or understand? Have your hearts been hardened?'
EXEC add_BibleVerse @BibleId, 341008018, N'Though you have eyes, don’t you see? And though you have ears, can’t you hear? Don’t you remember?'
EXEC add_BibleVerse @BibleId, 341008019, N'When I broke the five loaves for the five thousand, how many baskets full of pieces did you pick up?” They replied, “Twelve.”'
EXEC add_BibleVerse @BibleId, 341008020, N'“When I broke the seven loaves for the four thousand, how many baskets full of pieces did you pick up?” They replied, “Seven.”'
EXEC add_BibleVerse @BibleId, 341008021, N'Then he said to them, “Do you still not understand?”'
EXEC add_BibleVerse @BibleId, 341008022, N'Then they came to Bethsaida. They brought a blind man to Jesus and asked him to touch him.'
EXEC add_BibleVerse @BibleId, 341008023, N'He took the blind man by the hand and brought him outside of the village. Then he spit on his eyes, placed his hands on his eyes and asked, “Do you see anything?”'
EXEC add_BibleVerse @BibleId, 341008024, N'Regaining his sight he said, “I see people, but they look like trees walking.”'
EXEC add_BibleVerse @BibleId, 341008025, N'Then Jesus placed his hands on the man’s eyes again. And he opened his eyes, his sight was restored, and he saw everything clearly.'
EXEC add_BibleVerse @BibleId, 341008026, N'Jesus sent him home, saying, “Do not even go into the village.”'
EXEC add_BibleVerse @BibleId, 341008027, N'Then Jesus and his disciples went to the villages of Caesarea Philippi. On the way he asked his disciples, “Who do people say that I am?”'
EXEC add_BibleVerse @BibleId, 341008028, N'They said, “John the Baptist, others say Elijah, and still others, one of the prophets.”'
EXEC add_BibleVerse @BibleId, 341008029, N'He asked them, “But who do you say that I am?” Peter answered him, “You are the Christ.”'
EXEC add_BibleVerse @BibleId, 341008030, N'Then he warned them not to tell anyone about him.'
EXEC add_BibleVerse @BibleId, 341008031, N'Then Jesus began to teach them that the Son of Man must suffer many things and be rejected by the elders, chief priests, and experts in the law, and be killed, and after three days rise again.'
EXEC add_BibleVerse @BibleId, 341008032, N'He spoke openly about this. So Peter took him aside and began to rebuke him.'
EXEC add_BibleVerse @BibleId, 341008033, N'But after turning and looking at his disciples, he rebuked Peter and said, “Get behind me, Satan. You are not setting your mind on God’s interests, but on man’s.”'
EXEC add_BibleVerse @BibleId, 341008034, N'Then Jesus called the crowd, along with his disciples, and said to them, “If anyone wants to become my follower, he must deny himself, take up his cross, and follow me.'
EXEC add_BibleVerse @BibleId, 341008035, N'For whoever wants to save his life will lose it, but whoever loses his life for my sake and for the gospel will save it.'
EXEC add_BibleVerse @BibleId, 341008036, N'For what benefit is it for a person to gain the whole world, yet forfeit his life?'
EXEC add_BibleVerse @BibleId, 341008037, N'What can a person give in exchange for his life?'
EXEC add_BibleVerse @BibleId, 341008038, N'For if anyone is ashamed of me and my words in this adulterous and sinful generation, the Son of Man will also be ashamed of him when he comes in the glory of his Father with the holy angels.”'
EXEC add_BibleVerse @BibleId, 341009001, N'And he said to them, “I tell you the truth, there are some standing here who will not experience death before they see the kingdom of God come with power.”'
EXEC add_BibleVerse @BibleId, 341009002, N'Six days later Jesus took with him Peter, James, and John and led them alone up a high mountain privately. And he was transfigured before them,'
EXEC add_BibleVerse @BibleId, 341009003, N'and his clothes became radiantly white, more so than any launderer in the world could bleach them.'
EXEC add_BibleVerse @BibleId, 341009004, N'Then Elijah appeared before them along with Moses, and they were talking with Jesus.'
EXEC add_BibleVerse @BibleId, 341009005, N'So Peter said to Jesus, “Rabbi, it is good for us to be here. Let us make three shelters – one for you, one for Moses, and one for Elijah.”'
EXEC add_BibleVerse @BibleId, 341009006, N'(For they were afraid, and he did not know what to say.)'
EXEC add_BibleVerse @BibleId, 341009007, N'Then a cloud overshadowed them, and a voice came from the cloud, “This is my one dear Son. Listen to him!”'
EXEC add_BibleVerse @BibleId, 341009008, N'Suddenly when they looked around, they saw no one with them any more except Jesus.'
EXEC add_BibleVerse @BibleId, 341009009, N'As they were coming down from the mountain, he gave them orders not to tell anyone what they had seen until after the Son of Man had risen from the dead.'
EXEC add_BibleVerse @BibleId, 341009010, N'They kept this statement to themselves, discussing what this rising from the dead meant.'
EXEC add_BibleVerse @BibleId, 341009011, N'Then they asked him, “Why do the experts in the law say that Elijah must come first?”'
EXEC add_BibleVerse @BibleId, 341009012, N'He said to them, “Elijah does indeed come first, and restores all things. And why is it written that the Son of Man must suffer many things and be despised?'
EXEC add_BibleVerse @BibleId, 341009013, N'But I tell you that Elijah has certainly come, and they did to him whatever they wanted, just as it is written about him.”'
EXEC add_BibleVerse @BibleId, 341009014, N'When they came to the disciples, they saw a large crowd around them and experts in the law arguing with them.'
EXEC add_BibleVerse @BibleId, 341009015, N'When the whole crowd saw him, they were amazed and ran at once and greeted him.'
EXEC add_BibleVerse @BibleId, 341009016, N'He asked them, “What are you arguing about with them?”'
EXEC add_BibleVerse @BibleId, 341009017, N'A member of the crowd said to him, “Teacher, I brought you my son, who is possessed by a spirit that makes him mute.'
EXEC add_BibleVerse @BibleId, 341009018, N'Whenever it seizes him, it throws him down, and he foams at the mouth, grinds his teeth, and becomes rigid. I asked your disciples to cast it out, but they were not able to do so.”'
EXEC add_BibleVerse @BibleId, 341009019, N'He answered them, “You unbelieving generation! How much longer must I be with you? How much longer must I endure you? Bring him to me.”'
EXEC add_BibleVerse @BibleId, 341009020, N'So they brought the boy to him. When the spirit saw him, it immediately threw the boy into a convulsion. He fell on the ground and rolled around, foaming at the mouth.'
EXEC add_BibleVerse @BibleId, 341009021, N'Jesus asked his father, “How long has this been happening to him?” And he said, “From childhood.'
EXEC add_BibleVerse @BibleId, 341009022, N'It has often thrown him into fire or water to destroy him. But if you are able to do anything, have compassion on us and help us.”'
EXEC add_BibleVerse @BibleId, 341009023, N'Then Jesus said to him, “‘If you are able?’ All things are possible for the one who believes.”'
EXEC add_BibleVerse @BibleId, 341009024, N'Immediately the father of the boy cried out and said, “I believe; help my unbelief!”'
EXEC add_BibleVerse @BibleId, 341009025, N'Now when Jesus saw that a crowd was quickly gathering, he rebuked the unclean spirit, saying to it, “Mute and deaf spirit, I command you, come out of him and never enter him again.”'
EXEC add_BibleVerse @BibleId, 341009026, N'It shrieked, threw him into terrible convulsions, and came out. The boy looked so much like a corpse that many said, “He is dead!”'
EXEC add_BibleVerse @BibleId, 341009027, N'But Jesus gently took his hand and raised him to his feet, and he stood up.'
EXEC add_BibleVerse @BibleId, 341009028, N'Then, after he went into the house, his disciples asked him privately, “Why couldn’t we cast it out?”'
EXEC add_BibleVerse @BibleId, 341009029, N'He told them, “This kind can come out only by prayer.”'
EXEC add_BibleVerse @BibleId, 341009030, N'They went out from there and passed through Galilee. But Jesus did not want anyone to know,'
EXEC add_BibleVerse @BibleId, 341009031, N'for he was teaching his disciples and telling them, “The Son of Man will be betrayed into the hands of men. They will kill him, and after three days he will rise.”'
EXEC add_BibleVerse @BibleId, 341009032, N'But they did not understand this statement and were afraid to ask him.'
EXEC add_BibleVerse @BibleId, 341009033, N'Then they came to Capernaum. After Jesus was inside the house he asked them, “What were you discussing on the way?”'
EXEC add_BibleVerse @BibleId, 341009034, N'But they were silent, for on the way they had argued with one another about who was the greatest.'
EXEC add_BibleVerse @BibleId, 341009035, N'After he sat down, he called the twelve and said to them, “If anyone wants to be first, he must be last of all and servant of all.”'
EXEC add_BibleVerse @BibleId, 341009036, N'He took a little child and had him stand among them. Taking him in his arms, he said to them,'
EXEC add_BibleVerse @BibleId, 341009037, N'“Whoever welcomes one of these little children in my name welcomes me, and whoever welcomes me does not welcome me but the one who sent me.”'
EXEC add_BibleVerse @BibleId, 341009038, N'John said to him, “Teacher, we saw someone casting out demons in your name, and we tried to stop him because he was not following us.”'
EXEC add_BibleVerse @BibleId, 341009039, N'But Jesus said, “Do not stop him, because no one who does a miracle in my name will be able soon afterward to say anything bad about me.'
EXEC add_BibleVerse @BibleId, 341009040, N'For whoever is not against us is for us.'
EXEC add_BibleVerse @BibleId, 341009041, N'For I tell you the truth, whoever gives you a cup of water because you bear Christ’s name will never lose his reward.'
EXEC add_BibleVerse @BibleId, 341009042, N'“If anyone causes one of these little ones who believe in me to sin, it would be better for him to have a huge millstone tied around his neck and to be thrown into the sea.'
EXEC add_BibleVerse @BibleId, 341009043, N'If your hand causes you to sin, cut it off! It is better for you to enter into life crippled than to have two hands and go into hell, to the unquenchable fire.'
EXEC add_BibleVerse @BibleId, 341009045, N' If your foot causes you to sin, cut it off! It is better to enter life lame than to have two feet and be thrown into hell.'
EXEC add_BibleVerse @BibleId, 341009047, N' If your eye causes you to sin, tear it out! It is better to enter into the kingdom of God with one eye than to have two eyes and be thrown into hell,'
EXEC add_BibleVerse @BibleId, 341009048, N'where their worm never dies and the fire is never quenched.'
EXEC add_BibleVerse @BibleId, 341009049, N'Everyone will be salted with fire.'
EXEC add_BibleVerse @BibleId, 341009050, N'Salt is good, but if it loses its saltiness, how can you make it salty again? Have salt in yourselves, and be at peace with each other.”'
EXEC add_BibleVerse @BibleId, 341010001, N'Then Jesus left that place and went to the region of Judea and beyond the Jordan River. Again crowds gathered to him, and again, as was his custom, he taught them.'
EXEC add_BibleVerse @BibleId, 341010002, N'Then some Pharisees came, and to test him they asked, “Is it lawful for a man to divorce his wife?”'
EXEC add_BibleVerse @BibleId, 341010003, N'He answered them, “What did Moses command you?”'
EXEC add_BibleVerse @BibleId, 341010004, N'They said, “Moses permitted a man to write a certificate of dismissal and to divorce her.”'
EXEC add_BibleVerse @BibleId, 341010005, N'But Jesus said to them, “He wrote this commandment for you because of your hard hearts.'
EXEC add_BibleVerse @BibleId, 341010006, N'But from the beginning of creation he made them male and female*.'
EXEC add_BibleVerse @BibleId, 341010007, N'For this reason a man will leave his father and mother,'
EXEC add_BibleVerse @BibleId, 341010008, N'and the two will become one flesh. So they are no longer two, but one flesh.'
EXEC add_BibleVerse @BibleId, 341010009, N'Therefore what God has joined together, let no one separate.”'
EXEC add_BibleVerse @BibleId, 341010010, N'In the house once again, the disciples asked him about this.'
EXEC add_BibleVerse @BibleId, 341010011, N'So he told them, “Whoever divorces his wife and marries another commits adultery against her.'
EXEC add_BibleVerse @BibleId, 341010012, N'And if she divorces her husband and marries another, she commits adultery.”'
EXEC add_BibleVerse @BibleId, 341010013, N'Now people were bringing little children to him for him to touch, but the disciples scolded those who brought them.'
EXEC add_BibleVerse @BibleId, 341010014, N'But when Jesus saw this, he was indignant and said to them, “Let the little children come to me and do not try to stop them, for the kingdom of God belongs to such as these.'
EXEC add_BibleVerse @BibleId, 341010015, N'I tell you the truth, whoever does not receive the kingdom of God like a child will never enter it.”'
EXEC add_BibleVerse @BibleId, 341010016, N'After he took the children in his arms, he placed his hands on them and blessed them.'
EXEC add_BibleVerse @BibleId, 341010017, N'Now as Jesus was starting out on his way, someone ran up to him, fell on his knees, and said, “Good teacher, what must I do to inherit eternal life?”'
EXEC add_BibleVerse @BibleId, 341010018, N'Jesus said to him, “Why do you call me good? No one is good except God alone.'
EXEC add_BibleVerse @BibleId, 341010019, N'You know the commandments: ‘ Do not murder, do not commit adultery, do not steal, do not give false testimony, do not defraud , honor your father and mother.’”'
EXEC add_BibleVerse @BibleId, 341010020, N'The man said to him, “Teacher, I have wholeheartedly obeyed all these laws since my youth.”'
EXEC add_BibleVerse @BibleId, 341010021, N'As Jesus looked at him, he felt love for him and said, “You lack one thing. Go, sell whatever you have and give the money to the poor, and you will have treasure in heaven. Then come, follow me.”'
EXEC add_BibleVerse @BibleId, 341010022, N'But at this statement, the man looked sad and went away sorrowful, for he was very rich.'
EXEC add_BibleVerse @BibleId, 341010023, N'Then Jesus looked around and said to his disciples, “How hard it is for the rich to enter the kingdom of God!”'
EXEC add_BibleVerse @BibleId, 341010024, N'The disciples were astonished at these words. But again Jesus said to them, “Children, how hard it is to enter the kingdom of God!'
EXEC add_BibleVerse @BibleId, 341010025, N'It is easier for a camel to go through the eye of a needle than for a rich person to enter the kingdom of God.”'
EXEC add_BibleVerse @BibleId, 341010026, N'They were even more astonished and said to one another, “Then who can be saved?”'
EXEC add_BibleVerse @BibleId, 341010027, N'Jesus looked at them and replied, “This is impossible for mere humans, but not for God; all things are possible for God.”'
EXEC add_BibleVerse @BibleId, 341010028, N'Peter began to speak to him, “Look, we have left everything to follow you!”'
EXEC add_BibleVerse @BibleId, 341010029, N'Jesus said, “I tell you the truth, there is no one who has left home or brothers or sisters or mother or father or children or fields for my sake and for the sake of the gospel'
EXEC add_BibleVerse @BibleId, 341010030, N'who will not receive in this age a hundred times as much – homes, brothers, sisters, mothers, children, fields, all with persecutions – and in the age to come, eternal life.'
EXEC add_BibleVerse @BibleId, 341010031, N'But many who are first will be last, and the last first.”'
EXEC add_BibleVerse @BibleId, 341010032, N'They were on the way, going up to Jerusalem. Jesus was going ahead of them, and they were amazed, but those who followed were afraid. He took the twelve aside again and began to tell them what was going to happen to him.'
EXEC add_BibleVerse @BibleId, 341010033, N'“Look, we are going up to Jerusalem, and the Son of Man will be handed over to the chief priests and experts in the law. They will condemn him to death and will turn him over to the Gentiles.'
EXEC add_BibleVerse @BibleId, 341010034, N'They will mock him, spit on him, flog him severely, and kill him. Yet after three days, he will rise again.”'
EXEC add_BibleVerse @BibleId, 341010035, N'Then James and John, the sons of Zebedee, came to him and said, “Teacher, we want you to do for us whatever we ask.”'
EXEC add_BibleVerse @BibleId, 341010036, N'He said to them, “What do you want me to do for you?”'
EXEC add_BibleVerse @BibleId, 341010037, N'They said to him, “Permit one of us to sit at your right hand and the other at your left in your glory.”'
EXEC add_BibleVerse @BibleId, 341010038, N'But Jesus said to them, “You don’t know what you are asking! Are you able to drink the cup I drink or be baptized with the baptism I experience?”'
EXEC add_BibleVerse @BibleId, 341010039, N'They said to him, “We are able.” Then Jesus said to them, “You will drink the cup I drink, and you will be baptized with the baptism I experience,'
EXEC add_BibleVerse @BibleId, 341010040, N'but to sit at my right or at my left is not mine to give. It is for those for whom it has been prepared.”'
EXEC add_BibleVerse @BibleId, 341010041, N'Now when the other ten heard this, they became angry with James and John.'
EXEC add_BibleVerse @BibleId, 341010042, N'Jesus called them and said to them, “You know that those who are recognized as rulers of the Gentiles lord it over them, and those in high positions use their authority over them.'
EXEC add_BibleVerse @BibleId, 341010043, N'But it is not this way among you. Instead whoever wants to be great among you must be your servant,'
EXEC add_BibleVerse @BibleId, 341010044, N'and whoever wants to be first among you must be the slave of all.'
EXEC add_BibleVerse @BibleId, 341010045, N'For even the Son of Man did not come to be served but to serve, and to give his life as a ransom for many.”'
EXEC add_BibleVerse @BibleId, 341010046, N'They came to Jericho. As Jesus and his disciples and a large crowd were leaving Jericho, Bartimaeus the son of Timaeus, a blind beggar, was sitting by the road.'
EXEC add_BibleVerse @BibleId, 341010047, N'When he heard that it was Jesus the Nazarene, he began to shout, “Jesus, Son of David, have mercy on me!”'
EXEC add_BibleVerse @BibleId, 341010048, N'Many scolded him to get him to be quiet, but he shouted all the more, “Son of David, have mercy on me!”'
EXEC add_BibleVerse @BibleId, 341010049, N'Jesus stopped and said, “Call him.” So they called the blind man and said to him, “Have courage! Get up! He is calling you.”'
EXEC add_BibleVerse @BibleId, 341010050, N'He threw off his cloak, jumped up, and came to Jesus.'
EXEC add_BibleVerse @BibleId, 341010051, N'Then Jesus said to him, “What do you want me to do for you?” The blind man replied, “Rabbi, let me see again.”'
EXEC add_BibleVerse @BibleId, 341010052, N'Jesus said to him, “Go, your faith has healed you.” Immediately he regained his sight and followed him on the road.'
EXEC add_BibleVerse @BibleId, 341011001, N'Now as they approached Jerusalem, near Bethphage and Bethany, at the Mount of Olives, Jesus sent two of his disciples'
EXEC add_BibleVerse @BibleId, 341011002, N'and said to them, “Go to the village ahead of you. As soon as you enter it, you will find a colt tied there that has never been ridden. Untie it and bring it here.'
EXEC add_BibleVerse @BibleId, 341011003, N'If anyone says to you, ‘Why are you doing this?’ say, ‘The Lord needs it and will send it back here soon.’”'
EXEC add_BibleVerse @BibleId, 341011004, N'So they went and found a colt tied at a door, outside in the street, and untied it.'
EXEC add_BibleVerse @BibleId, 341011005, N'Some people standing there said to them, “What are you doing, untying that colt?”'
EXEC add_BibleVerse @BibleId, 341011006, N'They replied as Jesus had told them, and the bystanders let them go.'
EXEC add_BibleVerse @BibleId, 341011007, N'Then they brought the colt to Jesus, threw their cloaks on it, and he sat on it.'
EXEC add_BibleVerse @BibleId, 341011008, N'Many spread their cloaks on the road and others spread branches they had cut in the fields.'
EXEC add_BibleVerse @BibleId, 341011009, N'Both those who went ahead and those who followed kept shouting, “ Hosanna! Blessed is the one who comes in the name of the Lord!*'
EXEC add_BibleVerse @BibleId, 341011010, N'Blessed is the coming kingdom of our father David! Hosanna in the highest!”'
EXEC add_BibleVerse @BibleId, 341011011, N'Then Jesus entered Jerusalem and went to the temple. And after looking around at everything, he went out to Bethany with the twelve since it was already late.'
EXEC add_BibleVerse @BibleId, 341011012, N'Now the next day, as they went out from Bethany, he was hungry.'
EXEC add_BibleVerse @BibleId, 341011013, N'After noticing in the distance a fig tree with leaves, he went to see if he could find any fruit on it. When he came to it he found nothing but leaves, for it was not the season for figs.'
EXEC add_BibleVerse @BibleId, 341011014, N'He said to it, “May no one ever eat fruit from you again.” And his disciples heard it.'
EXEC add_BibleVerse @BibleId, 341011015, N'Then they came to Jerusalem. Jesus entered the temple area and began to drive out those who were selling and buying in the temple courts. He turned over the tables of the money changers and the chairs of those selling doves,'
EXEC add_BibleVerse @BibleId, 341011016, N'and he would not permit anyone to carry merchandise through the temple courts.'
EXEC add_BibleVerse @BibleId, 341011017, N'Then he began to teach them and said, “Is it not written: ‘ My house will be called a house of prayer for all nations’? But you have turned it into a den of robbers!”'
EXEC add_BibleVerse @BibleId, 341011018, N'The chief priests and the experts in the law heard it and they considered how they could assassinate him, for they feared him, because the whole crowd was amazed by his teaching.'
EXEC add_BibleVerse @BibleId, 341011019, N'When evening came, Jesus and his disciples went out of the city.'
EXEC add_BibleVerse @BibleId, 341011020, N'In the morning as they passed by, they saw the fig tree withered from the roots.'
EXEC add_BibleVerse @BibleId, 341011021, N'Peter remembered and said to him, “Rabbi, look! The fig tree you cursed has withered.”'
EXEC add_BibleVerse @BibleId, 341011022, N'Jesus said to them, “Have faith in God.'
EXEC add_BibleVerse @BibleId, 341011023, N'I tell you the truth, if someone says to this mountain, ‘Be lifted up and thrown into the sea,’ and does not doubt in his heart but believes that what he says will happen, it will be done for him.'
EXEC add_BibleVerse @BibleId, 341011024, N'For this reason I tell you, whatever you pray and ask for, believe that you have received it, and it will be yours.'
EXEC add_BibleVerse @BibleId, 341011025, N'Whenever you stand praying, if you have anything against anyone, forgive him, so that your Father in heaven will also forgive you your sins.”'
EXEC add_BibleVerse @BibleId, 341011027, N' They came again to Jerusalem. While Jesus was walking in the temple courts, the chief priests, the experts in the law, and the elders came up to him'
EXEC add_BibleVerse @BibleId, 341011028, N'and said, “By what authority are you doing these things? Or who gave you this authority to do these things?”'
EXEC add_BibleVerse @BibleId, 341011029, N'Jesus said to them, “I will ask you one question. Answer me and I will tell you by what authority I do these things:'
EXEC add_BibleVerse @BibleId, 341011030, N'John’s baptism – was it from heaven or from people? Answer me.”'
EXEC add_BibleVerse @BibleId, 341011031, N'They discussed with one another, saying, “If we say, ‘From heaven,’ he will say, ‘Then why did you not believe him?’'
EXEC add_BibleVerse @BibleId, 341011032, N'But if we say, ‘From people – ’” (they feared the crowd, for they all considered John to be truly a prophet).'
EXEC add_BibleVerse @BibleId, 341011033, N'So they answered Jesus, “We don’t know.” Then Jesus said to them, “Neither will I tell you by what authority I am doing these things.”'
EXEC add_BibleVerse @BibleId, 341012001, N'Then he began to speak to them in parables: “A man planted a vineyard. He put a fence around it, dug a pit for its winepress, and built a watchtower. Then he leased it to tenant farmers and went on a journey.'
EXEC add_BibleVerse @BibleId, 341012002, N'At harvest time he sent a slave to the tenants to collect from them his portion of the crop.'
EXEC add_BibleVerse @BibleId, 341012003, N'But those tenants seized his slave, beat him, and sent him away empty-handed.'
EXEC add_BibleVerse @BibleId, 341012004, N'So he sent another slave to them again. This one they struck on the head and treated outrageously.'
EXEC add_BibleVerse @BibleId, 341012005, N'He sent another, and that one they killed. This happened to many others, some of whom were beaten, others killed.'
EXEC add_BibleVerse @BibleId, 341012006, N'He had one left, his one dear son. Finally he sent him to them, saying, ‘They will respect my son.’'
EXEC add_BibleVerse @BibleId, 341012007, N'But those tenants said to one another, ‘This is the heir. Come, let’s kill him and the inheritance will be ours!’'
EXEC add_BibleVerse @BibleId, 341012008, N'So they seized him, killed him, and threw his body out of the vineyard.'
EXEC add_BibleVerse @BibleId, 341012009, N'What then will the owner of the vineyard do? He will come and destroy those tenants and give the vineyard to others.'
EXEC add_BibleVerse @BibleId, 341012010, N'Have you not read this scripture: ‘ The stone the builders rejected has become the cornerstone.'
EXEC add_BibleVerse @BibleId, 341012011, N'This is from the Lord, and it is marvelous in our eyes’?”'
EXEC add_BibleVerse @BibleId, 341012012, N'Now they wanted to arrest him (but they feared the crowd), because they realized that he told this parable against them. So they left him and went away.'
EXEC add_BibleVerse @BibleId, 341012013, N'Then they sent some of the Pharisees and Herodians to trap him with his own words.'
EXEC add_BibleVerse @BibleId, 341012014, N'When they came they said to him, “Teacher, we know that you are truthful and do not court anyone’s favor, because you show no partiality but teach the way of God in accordance with the truth. Is it right to pay taxes to Caesar or not? Should we pay or shouldn’t we?”'
EXEC add_BibleVerse @BibleId, 341012015, N'But he saw through their hypocrisy and said to them, “Why are you testing me? Bring me a denarius and let me look at it.”'
EXEC add_BibleVerse @BibleId, 341012016, N'So they brought one, and he said to them, “Whose image is this, and whose inscription?” They replied, “Caesar’s.”'
EXEC add_BibleVerse @BibleId, 341012017, N'Then Jesus said to them, “Give to Caesar the things that are Caesar’s, and to God the things that are God’s.” And they were utterly amazed at him.'
EXEC add_BibleVerse @BibleId, 341012018, N'Sadducees (who say there is no resurrection) also came to him and asked him,'
EXEC add_BibleVerse @BibleId, 341012019, N'“Teacher, Moses wrote for us: ‘ If a man’s brother dies and leaves a wife but no children, that man must marry the widow and father children for his brother.’'
EXEC add_BibleVerse @BibleId, 341012020, N'There were seven brothers. The first one married, and when he died he had no children.'
EXEC add_BibleVerse @BibleId, 341012021, N'The second married her and died without any children, and likewise the third.'
EXEC add_BibleVerse @BibleId, 341012022, N'None of the seven had children. Finally, the woman died too.'
EXEC add_BibleVerse @BibleId, 341012023, N'In the resurrection, when they rise again, whose wife will she be? For all seven had married her.”'
EXEC add_BibleVerse @BibleId, 341012024, N'Jesus said to them, “Aren’t you deceived for this reason, because you don’t know the scriptures or the power of God?'
EXEC add_BibleVerse @BibleId, 341012025, N'For when they rise from the dead, they neither marry nor are given in marriage, but are like angels in heaven.'
EXEC add_BibleVerse @BibleId, 341012026, N'Now as for the dead being raised, have you not read in the book of Moses, in the passage about the bush, how God said to him, ‘ I am the God of Abraham, the God of Isaac, and the God of Jacob’?'
EXEC add_BibleVerse @BibleId, 341012027, N'He is not the God of the dead but of the living. You are badly mistaken!”'
EXEC add_BibleVerse @BibleId, 341012028, N'Now one of the experts in the law came and heard them debating. When he saw that Jesus answered them well, he asked him, “Which commandment is the most important of all?”'
EXEC add_BibleVerse @BibleId, 341012029, N'Jesus answered, “The most important is: ‘ Listen, Israel, the Lord our God, the Lord is one.'
EXEC add_BibleVerse @BibleId, 341012030, N'Love the Lord your God with all your heart, with all your soul, with all your mind, and with all your strength.’'
EXEC add_BibleVerse @BibleId, 341012031, N'The second is: ‘ Love your neighbor as yourself.’ There is no other commandment greater than these.”'
EXEC add_BibleVerse @BibleId, 341012032, N'The expert in the law said to him, “That is true, Teacher; you are right to say that he is one, and there is no one else besides him.'
EXEC add_BibleVerse @BibleId, 341012033, N'And to love him with all your heart, with all your mind, and with all your strength and to love your neighbor as yourself is more important than all burnt offerings and sacrifices.”'
EXEC add_BibleVerse @BibleId, 341012034, N'When Jesus saw that he had answered thoughtfully, he said to him, “You are not far from the kingdom of God.” Then no one dared any longer to question him.'
EXEC add_BibleVerse @BibleId, 341012035, N'While Jesus was teaching in the temple courts, he said, “How is it that the experts in the law say that the Christ is David’s son?'
EXEC add_BibleVerse @BibleId, 341012036, N'David himself, by the Holy Spirit, said, ‘ The Lord said to my lord, “ Sit at my right hand, until I put your enemies under your feet.”’'
EXEC add_BibleVerse @BibleId, 341012037, N'If David himself calls him ‘Lord,’ how can he be his son?” And the large crowd was listening to him with delight.'
EXEC add_BibleVerse @BibleId, 341012038, N'In his teaching Jesus also said, “Watch out for the experts in the law. They like walking around in long robes and elaborate greetings in the marketplaces,'
EXEC add_BibleVerse @BibleId, 341012039, N'and the best seats in the synagogues and the places of honor at banquets.'
EXEC add_BibleVerse @BibleId, 341012040, N'They devour widows’ property, and as a show make long prayers. These men will receive a more severe punishment.”'
EXEC add_BibleVerse @BibleId, 341012041, N'Then he sat down opposite the offering box, and watched the crowd putting coins into it. Many rich people were throwing in large amounts.'
EXEC add_BibleVerse @BibleId, 341012042, N'And a poor widow came and put in two small copper coins, worth less than a penny.'
EXEC add_BibleVerse @BibleId, 341012043, N'He called his disciples and said to them, “I tell you the truth, this poor widow has put more into the offering box than all the others.'
EXEC add_BibleVerse @BibleId, 341012044, N'For they all gave out of their wealth. But she, out of her poverty, put in what she had to live on, everything she had.”'
EXEC add_BibleVerse @BibleId, 341013001, N'Now as Jesus was going out of the temple courts, one of his disciples said to him, “Teacher, look at these tremendous stones and buildings!”'
EXEC add_BibleVerse @BibleId, 341013002, N'Jesus said to him, “Do you see these great buildings? Not one stone will be left on another. All will be torn down!”'
EXEC add_BibleVerse @BibleId, 341013003, N'So while he was sitting on the Mount of Olives opposite the temple, Peter, James, John, and Andrew asked him privately,'
EXEC add_BibleVerse @BibleId, 341013004, N'“Tell us, when will these things happen? And what will be the sign that all these things are about to take place?”'
EXEC add_BibleVerse @BibleId, 341013005, N'Jesus began to say to them, “Watch out that no one misleads you.'
EXEC add_BibleVerse @BibleId, 341013006, N'Many will come in my name, saying, ‘I am he,’ and they will mislead many.'
EXEC add_BibleVerse @BibleId, 341013007, N'When you hear of wars and rumors of wars, do not be alarmed. These things must happen, but the end is still to come.'
EXEC add_BibleVerse @BibleId, 341013008, N'For nation will rise up in arms against nation, and kingdom against kingdom. There will be earthquakes in various places, and there will be famines. These are but the beginning of birth pains.'
EXEC add_BibleVerse @BibleId, 341013009, N'“You must watch out for yourselves. You will be handed over to councils and beaten in the synagogues. You will stand before governors and kings because of me, as a witness to them.'
EXEC add_BibleVerse @BibleId, 341013010, N'First the gospel must be preached to all nations.'
EXEC add_BibleVerse @BibleId, 341013011, N'When they arrest you and hand you over for trial, do not worry about what to speak. But say whatever is given you at that time, for it is not you speaking, but the Holy Spirit.'
EXEC add_BibleVerse @BibleId, 341013012, N'Brother will hand over brother to death, and a father his child. Children will rise against parents and have them put to death.'
EXEC add_BibleVerse @BibleId, 341013013, N'You will be hated by everyone because of my name. But the one who endures to the end will be saved.'
EXEC add_BibleVerse @BibleId, 341013014, N'“But when you see the abomination of desolation standing where it should not be (let the reader understand), then those in Judea must flee to the mountains.'
EXEC add_BibleVerse @BibleId, 341013015, N'The one on the roof must not come down or go inside to take anything out of his house.'
EXEC add_BibleVerse @BibleId, 341013016, N'The one in the field must not turn back to get his cloak.'
EXEC add_BibleVerse @BibleId, 341013017, N'Woe to those who are pregnant and to those who are nursing their babies in those days!'
EXEC add_BibleVerse @BibleId, 341013018, N'Pray that it may not be in winter.'
EXEC add_BibleVerse @BibleId, 341013019, N'For in those days there will be suffering unlike anything that has happened from the beginning of the creation that God created until now, or ever will happen.'
EXEC add_BibleVerse @BibleId, 341013020, N'And if the Lord had not cut short those days, no one would be saved. But because of the elect, whom he chose, he has cut them short.'
EXEC add_BibleVerse @BibleId, 341013021, N'Then if anyone says to you, ‘Look, here is the Christ!’ or ‘Look, there he is!’ do not believe him.'
EXEC add_BibleVerse @BibleId, 341013022, N'For false messiahs and false prophets will appear and perform signs and wonders to deceive, if possible, the elect.'
EXEC add_BibleVerse @BibleId, 341013023, N'Be careful! I have told you everything ahead of time.'
EXEC add_BibleVerse @BibleId, 341013024, N'“But in those days, after that suffering, the sun will be darkened and the moon will not give its light;'
EXEC add_BibleVerse @BibleId, 341013025, N'the stars will be falling from heaven, and the powers in the heavens will be shaken.'
EXEC add_BibleVerse @BibleId, 341013026, N'Then everyone will see the Son of Man arriving in the clouds with great power and glory.'
EXEC add_BibleVerse @BibleId, 341013027, N'Then he will send angels and they will gather his elect from the four winds, from the ends of the earth to the ends of heaven.'
EXEC add_BibleVerse @BibleId, 341013028, N'“Learn this parable from the fig tree: Whenever its branch becomes tender and puts out its leaves, you know that summer is near.'
EXEC add_BibleVerse @BibleId, 341013029, N'So also you, when you see these things happening, know that he is near, right at the door.'
EXEC add_BibleVerse @BibleId, 341013030, N'I tell you the truth, this generation will not pass away until all these things take place.'
EXEC add_BibleVerse @BibleId, 341013031, N'Heaven and earth will pass away, but my words will never pass away.'
EXEC add_BibleVerse @BibleId, 341013032, N'“But as for that day or hour no one knows it – neither the angels in heaven, nor the Son – except the Father.'
EXEC add_BibleVerse @BibleId, 341013033, N'Watch out! Stay alert! For you do not know when the time will come.'
EXEC add_BibleVerse @BibleId, 341013034, N'It is like a man going on a journey. He left his house and put his slaves in charge, assigning to each his work, and commanded the doorkeeper to stay alert.'
EXEC add_BibleVerse @BibleId, 341013035, N'Stay alert, then, because you do not know when the owner of the house will return – whether during evening, at midnight, when the rooster crows, or at dawn –'
EXEC add_BibleVerse @BibleId, 341013036, N'or else he might find you asleep when he returns suddenly.'
EXEC add_BibleVerse @BibleId, 341013037, N'What I say to you I say to everyone: Stay alert!”'
EXEC add_BibleVerse @BibleId, 341014001, N'Two days before the Passover and the Feast of Unleavened Bread, the chief priests and the experts in the law were trying to find a way to arrest Jesus by stealth and kill him.'
EXEC add_BibleVerse @BibleId, 341014002, N'For they said, “Not during the feast, so there won’t be a riot among the people.”'
EXEC add_BibleVerse @BibleId, 341014003, N'Now while Jesus was in Bethany at the house of Simon the leper, reclining at the table, a woman came with an alabaster jar of costly aromatic oil from pure nard. After breaking open the jar, she poured it on his head.'
EXEC add_BibleVerse @BibleId, 341014004, N'But some who were present indignantly said to one another, “Why this waste of expensive ointment?'
EXEC add_BibleVerse @BibleId, 341014005, N'It could have been sold for more than three hundred silver coins and the money given to the poor!” So they spoke angrily to her.'
EXEC add_BibleVerse @BibleId, 341014006, N'But Jesus said, “Leave her alone. Why are you bothering her? She has done a good service for me.'
EXEC add_BibleVerse @BibleId, 341014007, N'For you will always have the poor with you, and you can do good for them whenever you want. But you will not always have me!'
EXEC add_BibleVerse @BibleId, 341014008, N'She did what she could. She anointed my body beforehand for burial.'
EXEC add_BibleVerse @BibleId, 341014009, N'I tell you the truth, wherever the gospel is proclaimed in the whole world, what she has done will also be told in memory of her.”'
EXEC add_BibleVerse @BibleId, 341014010, N'Then Judas Iscariot, one of the twelve, went to the chief priests to betray Jesus into their hands.'
EXEC add_BibleVerse @BibleId, 341014011, N'When they heard this, they were delighted and promised to give him money. So Judas began looking for an opportunity to betray him.'
EXEC add_BibleVerse @BibleId, 341014012, N'Now on the first day of the feast of Unleavened Bread, when the Passover lamb is sacrificed, Jesus’ disciples said to him, “Where do you want us to prepare for you to eat the Passover?”'
EXEC add_BibleVerse @BibleId, 341014013, N'He sent two of his disciples and told them, “Go into the city, and a man carrying a jar of water will meet you. Follow him.'
EXEC add_BibleVerse @BibleId, 341014014, N'Wherever he enters, tell the owner of the house, ‘The Teacher says, “Where is my guest room where I may eat the Passover with my disciples?”’'
EXEC add_BibleVerse @BibleId, 341014015, N'He will show you a large room upstairs, furnished and ready. Make preparations for us there.”'
EXEC add_BibleVerse @BibleId, 341014016, N'So the disciples left, went into the city, and found things just as he had told them, and they prepared the Passover.'
EXEC add_BibleVerse @BibleId, 341014017, N'Then, when it was evening, he came to the house with the twelve.'
EXEC add_BibleVerse @BibleId, 341014018, N'While they were at the table eating, Jesus said, “I tell you the truth, one of you eating with me will betray me.”'
EXEC add_BibleVerse @BibleId, 341014019, N'They were distressed, and one by one said to him, “Surely not I?”'
EXEC add_BibleVerse @BibleId, 341014020, N'He said to them, “It is one of the twelve, one who dips his hand with me into the bowl.'
EXEC add_BibleVerse @BibleId, 341014021, N'For the Son of Man will go as it is written about him, but woe to that man by whom the Son of Man is betrayed! It would be better for him if he had never been born.”'
EXEC add_BibleVerse @BibleId, 341014022, N'While they were eating, he took bread, and after giving thanks he broke it, gave it to them, and said, “Take it. This is my body.”'
EXEC add_BibleVerse @BibleId, 341014023, N'And after taking the cup and giving thanks, he gave it to them, and they all drank from it.'
EXEC add_BibleVerse @BibleId, 341014024, N'He said to them, “This is my blood, the blood of the covenant, that is poured out for many.'
EXEC add_BibleVerse @BibleId, 341014025, N'I tell you the truth, I will no longer drink of the fruit of the vine until that day when I drink it new in the kingdom of God.”'
EXEC add_BibleVerse @BibleId, 341014026, N'After singing a hymn, they went out to the Mount of Olives.'
EXEC add_BibleVerse @BibleId, 341014027, N'Then Jesus said to them, “You will all fall away, for it is written, ‘ I will strike the shepherd, and the sheep will be scattered.’'
EXEC add_BibleVerse @BibleId, 341014028, N'But after I am raised, I will go ahead of you into Galilee.”'
EXEC add_BibleVerse @BibleId, 341014029, N'Peter said to him, “Even if they all fall away, I will not!”'
EXEC add_BibleVerse @BibleId, 341014030, N'Jesus said to him, “I tell you the truth, today – this very night – before a rooster crows twice, you will deny me three times.”'
EXEC add_BibleVerse @BibleId, 341014031, N'But Peter insisted emphatically, “Even if I must die with you, I will never deny you.” And all of them said the same thing.'
EXEC add_BibleVerse @BibleId, 341014032, N'Then they went to a place called Gethsemane, and Jesus said to his disciples, “Sit here while I pray.”'
EXEC add_BibleVerse @BibleId, 341014033, N'He took Peter, James, and John with him, and became very troubled and distressed.'
EXEC add_BibleVerse @BibleId, 341014034, N'He said to them, “My soul is deeply grieved, even to the point of death. Remain here and stay alert.”'
EXEC add_BibleVerse @BibleId, 341014035, N'Going a little farther, he threw himself to the ground and prayed that if it were possible the hour would pass from him.'
EXEC add_BibleVerse @BibleId, 341014036, N'He said, “Abba, Father, all things are possible for you. Take this cup away from me. Yet not what I will, but what you will.”'
EXEC add_BibleVerse @BibleId, 341014037, N'Then he came and found them sleeping, and said to Peter, “Simon, are you sleeping? Couldn’t you stay awake for one hour?'
EXEC add_BibleVerse @BibleId, 341014038, N'Stay awake and pray that you will not fall into temptation. The spirit is willing, but the flesh is weak.”'
EXEC add_BibleVerse @BibleId, 341014039, N'He went away again and prayed the same thing.'
EXEC add_BibleVerse @BibleId, 341014040, N'When he came again he found them sleeping; they could not keep their eyes open. And they did not know what to tell him.'
EXEC add_BibleVerse @BibleId, 341014041, N'He came a third time and said to them, “Are you still sleeping and resting? Enough of that! The hour has come. Look, the Son of Man is betrayed into the hands of sinners.'
EXEC add_BibleVerse @BibleId, 341014042, N'Get up, let us go. Look! My betrayer is approaching!”'
EXEC add_BibleVerse @BibleId, 341014043, N'Right away, while Jesus was still speaking, Judas, one of the twelve, arrived. With him came a crowd armed with swords and clubs, sent by the chief priests and experts in the law and elders.'
EXEC add_BibleVerse @BibleId, 341014044, N'(Now the betrayer had given them a sign, saying, “The one I kiss is the man. Arrest him and lead him away under guard.”)'
EXEC add_BibleVerse @BibleId, 341014045, N'When Judas arrived, he went up to Jesus immediately and said, “Rabbi!” and kissed him.'
EXEC add_BibleVerse @BibleId, 341014046, N'Then they took hold of him and arrested him.'
EXEC add_BibleVerse @BibleId, 341014047, N'One of the bystanders drew his sword and struck the high priest’s slave, cutting off his ear.'
EXEC add_BibleVerse @BibleId, 341014048, N'Jesus said to them, “Have you come with swords and clubs to arrest me like you would an outlaw?'
EXEC add_BibleVerse @BibleId, 341014049, N'Day after day I was with you, teaching in the temple courts, yet you did not arrest me. But this has happened so that the scriptures would be fulfilled.”'
EXEC add_BibleVerse @BibleId, 341014050, N'Then all the disciples left him and fled.'
EXEC add_BibleVerse @BibleId, 341014051, N'A young man was following him, wearing only a linen cloth. They tried to arrest him,'
EXEC add_BibleVerse @BibleId, 341014052, N'but he ran off naked, leaving his linen cloth behind.'
EXEC add_BibleVerse @BibleId, 341014053, N'Then they led Jesus to the high priest, and all the chief priests and elders and experts in the law came together.'
EXEC add_BibleVerse @BibleId, 341014054, N'And Peter had followed him from a distance, up to the high priest’s courtyard. He was sitting with the guards and warming himself by the fire.'
EXEC add_BibleVerse @BibleId, 341014055, N'The chief priests and the whole Sanhedrin were looking for evidence against Jesus so that they could put him to death, but they did not find anything.'
EXEC add_BibleVerse @BibleId, 341014056, N'Many gave false testimony against him, but their testimony did not agree.'
EXEC add_BibleVerse @BibleId, 341014057, N'Some stood up and gave this false testimony against him:'
EXEC add_BibleVerse @BibleId, 341014058, N'“We heard him say, ‘I will destroy this temple made with hands and in three days build another not made with hands.’”'
EXEC add_BibleVerse @BibleId, 341014059, N'Yet even on this point their testimony did not agree.'
EXEC add_BibleVerse @BibleId, 341014060, N'Then the high priest stood up before them and asked Jesus, “Have you no answer? What is this that they are testifying against you?”'
EXEC add_BibleVerse @BibleId, 341014061, N'But he was silent and did not answer. Again the high priest questioned him, “Are you the Christ, the Son of the Blessed One?”'
EXEC add_BibleVerse @BibleId, 341014062, N'“I am,” said Jesus, “and you will see the Son of Man sitting at the right hand of the Power and coming with the clouds of heaven.”'
EXEC add_BibleVerse @BibleId, 341014063, N'Then the high priest tore his clothes and said, “Why do we still need witnesses?'
EXEC add_BibleVerse @BibleId, 341014064, N'You have heard the blasphemy! What is your verdict?” They all condemned him as deserving death.'
EXEC add_BibleVerse @BibleId, 341014065, N'Then some began to spit on him, and to blindfold him, and to strike him with their fists, saying, “Prophesy!” The guards also took him and beat him.'
EXEC add_BibleVerse @BibleId, 341014066, N'Now while Peter was below in the courtyard, one of the high priest’s slave girls came by.'
EXEC add_BibleVerse @BibleId, 341014067, N'When she saw Peter warming himself, she looked directly at him and said, “You also were with that Nazarene, Jesus.”'
EXEC add_BibleVerse @BibleId, 341014068, N'But he denied it: “I don’t even understand what you’re talking about!” Then he went out to the gateway, and a rooster crowed.'
EXEC add_BibleVerse @BibleId, 341014069, N'When the slave girl saw him, she began again to say to the bystanders, “This man is one of them.”'
EXEC add_BibleVerse @BibleId, 341014070, N'But he denied it again. A short time later the bystanders again said to Peter, “You must be one of them, because you are also a Galilean.”'
EXEC add_BibleVerse @BibleId, 341014071, N'Then he began to curse, and he swore with an oath, “I do not know this man you are talking about!”'
EXEC add_BibleVerse @BibleId, 341014072, N'Immediately a rooster crowed a second time. Then Peter remembered what Jesus had said to him: “Before a rooster crows twice, you will deny me three times.” And he broke down and wept.'
EXEC add_BibleVerse @BibleId, 341015001, N'Early in the morning, after forming a plan, the chief priests with the elders and the experts in the law and the whole Sanhedrin tied Jesus up, led him away, and handed him over to Pilate.'
EXEC add_BibleVerse @BibleId, 341015002, N'So Pilate asked him, “Are you the king of the Jews?” He replied, “You say so.”'
EXEC add_BibleVerse @BibleId, 341015003, N'Then the chief priests began to accuse him repeatedly.'
EXEC add_BibleVerse @BibleId, 341015004, N'So Pilate asked him again, “Have you nothing to say? See how many charges they are bringing against you!”'
EXEC add_BibleVerse @BibleId, 341015005, N'But Jesus made no further reply, so that Pilate was amazed.'
EXEC add_BibleVerse @BibleId, 341015006, N'During the feast it was customary to release one prisoner to the people, whomever they requested.'
EXEC add_BibleVerse @BibleId, 341015007, N'A man named Barabbas was imprisoned with rebels who had committed murder during an insurrection.'
EXEC add_BibleVerse @BibleId, 341015008, N'Then the crowd came up and began to ask Pilate to release a prisoner for them, as was his custom.'
EXEC add_BibleVerse @BibleId, 341015009, N'So Pilate asked them, “Do you want me to release the king of the Jews for you?”'
EXEC add_BibleVerse @BibleId, 341015010, N'(For he knew that the chief priests had handed him over because of envy.)'
EXEC add_BibleVerse @BibleId, 341015011, N'But the chief priests stirred up the crowd to have him release Barabbas instead.'
EXEC add_BibleVerse @BibleId, 341015012, N'So Pilate spoke to them again, “Then what do you want me to do with the one you call king of the Jews?”'
EXEC add_BibleVerse @BibleId, 341015013, N'They shouted back, “Crucify him!”'
EXEC add_BibleVerse @BibleId, 341015014, N'Pilate asked them, “Why? What has he done wrong?” But they shouted more insistently, “Crucify him!”'
EXEC add_BibleVerse @BibleId, 341015015, N'Because he wanted to satisfy the crowd, Pilate released Barabbas for them. Then, after he had Jesus flogged, he handed him over to be crucified.'
EXEC add_BibleVerse @BibleId, 341015016, N'So the soldiers led him into the palace (that is, the governor’s residence) and called together the whole cohort.'
EXEC add_BibleVerse @BibleId, 341015017, N'They put a purple cloak on him and after braiding a crown of thorns, they put it on him.'
EXEC add_BibleVerse @BibleId, 341015018, N'They began to salute him: “Hail, king of the Jews!”'
EXEC add_BibleVerse @BibleId, 341015019, N'Again and again they struck him on the head with a staff and spit on him. Then they knelt down and paid homage to him.'
EXEC add_BibleVerse @BibleId, 341015020, N'When they had finished mocking him, they stripped him of the purple cloak and put his own clothes back on him. Then they led him away to crucify him.'
EXEC add_BibleVerse @BibleId, 341015021, N'The soldiers forced a passerby to carry his cross, Simon of Cyrene, who was coming in from the country (he was the father of Alexander and Rufus).'
EXEC add_BibleVerse @BibleId, 341015022, N'They brought Jesus to a place called Golgotha (which is translated, “Place of the Skull”).'
EXEC add_BibleVerse @BibleId, 341015023, N'They offered him wine mixed with myrrh, but he did not take it.'
EXEC add_BibleVerse @BibleId, 341015024, N'Then they crucified him and divided his clothes, throwing dice for them, to decide what each would take.'
EXEC add_BibleVerse @BibleId, 341015025, N'It was nine o’clock in the morning when they crucified him.'
EXEC add_BibleVerse @BibleId, 341015026, N'The inscription of the charge against him read, “The king of the Jews.”'
EXEC add_BibleVerse @BibleId, 341015027, N'And they crucified two outlaws with him, one on his right and one on his left.'
EXEC add_BibleVerse @BibleId, 341015029, N' Those who passed by defamed him, shaking their heads and saying, “Aha! You who can destroy the temple and rebuild it in three days,'
EXEC add_BibleVerse @BibleId, 341015030, N'save yourself and come down from the cross!”'
EXEC add_BibleVerse @BibleId, 341015031, N'In the same way even the chief priests – together with the experts in the law – were mocking him among themselves: “He saved others, but he cannot save himself!'
EXEC add_BibleVerse @BibleId, 341015032, N'Let the Christ, the king of Israel, come down from the cross now, that we may see and believe!” Those who were crucified with him also spoke abusively to him.'
EXEC add_BibleVerse @BibleId, 341015033, N'Now when it was noon, darkness came over the whole land until three in the afternoon.'
EXEC add_BibleVerse @BibleId, 341015034, N'Around three o’clock Jesus cried out with a loud voice, “ Eloi, Eloi, lema sabachthani?” which means, “ My God, my God, why have you forsaken me?”'
EXEC add_BibleVerse @BibleId, 341015035, N'When some of the bystanders heard it they said, “Listen, he is calling for Elijah!”'
EXEC add_BibleVerse @BibleId, 341015036, N'Then someone ran, filled a sponge with sour wine, put it on a stick, and gave it to him to drink, saying, “Leave him alone! Let’s see if Elijah will come to take him down!”'
EXEC add_BibleVerse @BibleId, 341015037, N'But Jesus cried out with a loud voice and breathed his last.'
EXEC add_BibleVerse @BibleId, 341015038, N'And the temple curtain was torn in two, from top to bottom.'
EXEC add_BibleVerse @BibleId, 341015039, N'Now when the centurion, who stood in front of him, saw how he died, he said, “Truly this man was God’s Son!”'
EXEC add_BibleVerse @BibleId, 341015040, N'There were also women, watching from a distance. Among them were Mary Magdalene, and Mary the mother of James the younger and of Joses, and Salome.'
EXEC add_BibleVerse @BibleId, 341015041, N'When he was in Galilee, they had followed him and given him support. Many other women who had come up with him to Jerusalem were there too.'
EXEC add_BibleVerse @BibleId, 341015042, N'Now when evening had already come, since it was the day of preparation (that is, the day before the Sabbath),'
EXEC add_BibleVerse @BibleId, 341015043, N'Joseph of Arimathea, a highly regarded member of the council, who was himself looking forward to the kingdom of God, went boldly to Pilate and asked for the body of Jesus.'
EXEC add_BibleVerse @BibleId, 341015044, N'Pilate was surprised that he was already dead. He called the centurion and asked him if he had been dead for some time.'
EXEC add_BibleVerse @BibleId, 341015045, N'When Pilate was informed by the centurion, he gave the body to Joseph.'
EXEC add_BibleVerse @BibleId, 341015046, N'After Joseph bought a linen cloth and took down the body, he wrapped it in the linen and placed it in a tomb cut out of the rock. Then he rolled a stone across the entrance of the tomb.'
EXEC add_BibleVerse @BibleId, 341015047, N'Mary Magdalene and Mary the mother of Joses saw where the body was placed.'
EXEC add_BibleVerse @BibleId, 341016001, N'When the Sabbath was over, Mary Magdalene, Mary the mother of James, and Salome bought aromatic spices so that they might go and anoint him.'
EXEC add_BibleVerse @BibleId, 341016002, N'And very early on the first day of the week, at sunrise, they went to the tomb.'
EXEC add_BibleVerse @BibleId, 341016003, N'They had been asking each other, “Who will roll away the stone for us from the entrance to the tomb?”'
EXEC add_BibleVerse @BibleId, 341016004, N'But when they looked up, they saw that the stone, which was very large, had been rolled back.'
EXEC add_BibleVerse @BibleId, 341016005, N'Then as they went into the tomb, they saw a young man dressed in a white robe sitting on the right side; and they were alarmed.'
EXEC add_BibleVerse @BibleId, 341016006, N'But he said to them, “Do not be alarmed. You are looking for Jesus the Nazarene, who was crucified. He has been raised! He is not here. Look, there is the place where they laid him.'
EXEC add_BibleVerse @BibleId, 341016007, N'But go, tell his disciples, even Peter, that he is going ahead of you into Galilee. You will see him there, just as he told you.”'
EXEC add_BibleVerse @BibleId, 341016008, N'Then they went out and ran from the tomb, for terror and bewilderment had seized them. And they said nothing to anyone, because they were afraid.'
EXEC add_BibleVerse @BibleId, 341016009, N'Early on the first day of the week, after he arose, he appeared first to Mary Magdalene, from whom he had driven out seven demons.'
EXEC add_BibleVerse @BibleId, 341016010, N'She went out and told those who were with him, while they were mourning and weeping.'
EXEC add_BibleVerse @BibleId, 341016011, N'And when they heard that he was alive and had been seen by her, they did not believe.'
EXEC add_BibleVerse @BibleId, 341016012, N'After this he appeared in a different form to two of them while they were on their way to the country.'
EXEC add_BibleVerse @BibleId, 341016013, N'They went back and told the rest, but they did not believe them.'
EXEC add_BibleVerse @BibleId, 341016014, N'Then he appeared to the eleven themselves, while they were eating, and he rebuked them for their unbelief and hardness of heart, because they did not believe those who had seen him resurrected.'
EXEC add_BibleVerse @BibleId, 341016015, N'He said to them, “Go into all the world and preach the gospel to every creature.'
EXEC add_BibleVerse @BibleId, 341016016, N'The one who believes and is baptized will be saved, but the one who does not believe will be condemned.'
EXEC add_BibleVerse @BibleId, 341016017, N'These signs will accompany those who believe: In my name they will drive out demons; they will speak in new languages;'
EXEC add_BibleVerse @BibleId, 341016018, N'they will pick up snakes with their hands, and whatever poison they drink will not harm them; they will place their hands on the sick and they will be well.”'
EXEC add_BibleVerse @BibleId, 341016019, N'After the Lord Jesus had spoken to them, he was taken up into heaven and sat down at the right hand of God.'
EXEC add_BibleVerse @BibleId, 341016020, N'They went out and proclaimed everywhere, while the Lord worked with them and confirmed the word through the accompanying signs.'
EXEC add_BibleVerse @BibleId, 342001001, N'Now many have undertaken to compile an account of the things that have been fulfilled among us,'
EXEC add_BibleVerse @BibleId, 342001002, N'like the accounts passed on to us by those who were eyewitnesses and servants of the word from the beginning.'
EXEC add_BibleVerse @BibleId, 342001003, N'So it seemed good to me as well, because I have followed all things carefully from the beginning, to write an orderly account for you, most excellent Theophilus,'
EXEC add_BibleVerse @BibleId, 342001004, N'so that you may know for certain the things you were taught.'
EXEC add_BibleVerse @BibleId, 342001005, N'During the reign of Herod king of Judea, there lived a priest named Zechariah who belonged to the priestly division of Abijah, and he had a wife named Elizabeth, who was a descendant of Aaron.'
EXEC add_BibleVerse @BibleId, 342001006, N'They were both righteous in the sight of God, following all the commandments and ordinances of the Lord blamelessly.'
EXEC add_BibleVerse @BibleId, 342001007, N'But they did not have a child, because Elizabeth was barren, and they were both very old.'
EXEC add_BibleVerse @BibleId, 342001008, N'Now while Zechariah was serving as priest before God when his division was on duty,'
EXEC add_BibleVerse @BibleId, 342001009, N'he was chosen by lot, according to the custom of the priesthood, to enter the holy place of the Lord and burn incense.'
EXEC add_BibleVerse @BibleId, 342001010, N'Now the whole crowd of people were praying outside at the hour of the incense offering.'
EXEC add_BibleVerse @BibleId, 342001011, N'An angel of the Lord, standing on the right side of the altar of incense, appeared to him.'
EXEC add_BibleVerse @BibleId, 342001012, N'And Zechariah, visibly shaken when he saw the angel, was seized with fear.'
EXEC add_BibleVerse @BibleId, 342001013, N'But the angel said to him, “Do not be afraid, Zechariah, for your prayer has been heard, and your wife Elizabeth will bear you a son; you will name him John.'
EXEC add_BibleVerse @BibleId, 342001014, N'Joy and gladness will come to you, and many will rejoice at his birth,'
EXEC add_BibleVerse @BibleId, 342001015, N'for he will be great in the sight of the Lord. He must never drink wine or strong drink, and he will be filled with the Holy Spirit, even before his birth.'
EXEC add_BibleVerse @BibleId, 342001016, N'He will turn many of the people of Israel to the Lord their God.'
EXEC add_BibleVerse @BibleId, 342001017, N'And he will go as forerunner before the Lord in the spirit and power of Elijah, to turn the hearts of the fathers back to their children and the disobedient to the wisdom of the just, to make ready for the Lord a people prepared for him.”'
EXEC add_BibleVerse @BibleId, 342001018, N'Zechariah said to the angel, “How can I be sure of this? For I am an old man, and my wife is old as well.”'
EXEC add_BibleVerse @BibleId, 342001019, N'The angel answered him, “I am Gabriel, who stands in the presence of God, and I was sent to speak to you and to bring you this good news.'
EXEC add_BibleVerse @BibleId, 342001020, N'And now, because you did not believe my words, which will be fulfilled in their time, you will be silent, unable to speak, until the day these things take place.”'
EXEC add_BibleVerse @BibleId, 342001021, N'Now the people were waiting for Zechariah, and they began to wonder why he was delayed in the holy place.'
EXEC add_BibleVerse @BibleId, 342001022, N'When he came out, he was not able to speak to them. They realized that he had seen a vision in the holy place, because he was making signs to them and remained unable to speak.'
EXEC add_BibleVerse @BibleId, 342001023, N'When his time of service was over, he went to his home.'
EXEC add_BibleVerse @BibleId, 342001024, N'After some time his wife Elizabeth became pregnant, and for five months she kept herself in seclusion. She said,'
EXEC add_BibleVerse @BibleId, 342001025, N'“This is what the Lord has done for me at the time when he has been gracious to me, to take away my disgrace among people.”'
EXEC add_BibleVerse @BibleId, 342001026, N'In the sixth month of Elizabeth’s pregnancy, the angel Gabriel was sent by God to a town of Galilee called Nazareth,'
EXEC add_BibleVerse @BibleId, 342001027, N'to a virgin engaged to a man whose name was Joseph, a descendant of David, and the virgin’s name was Mary.'
EXEC add_BibleVerse @BibleId, 342001028, N'The angel came to her and said, “Greetings, favored one, the Lord is with you!”'
EXEC add_BibleVerse @BibleId, 342001029, N'But she was greatly troubled by his words and began to wonder about the meaning of this greeting.'
EXEC add_BibleVerse @BibleId, 342001030, N'So the angel said to her, “Do not be afraid, Mary, for you have found favor with God!'
EXEC add_BibleVerse @BibleId, 342001031, N'Listen: You will become pregnant and give birth to a son, and you will name him Jesus.'
EXEC add_BibleVerse @BibleId, 342001032, N'He will be great, and will be called the Son of the Most High, and the Lord God will give him the throne of his father David.'
EXEC add_BibleVerse @BibleId, 342001033, N'He will reign over the house of Jacob forever, and his kingdom will never end.”'
EXEC add_BibleVerse @BibleId, 342001034, N'Mary said to the angel, “How will this be, since I have not had sexual relations with a man?”'
EXEC add_BibleVerse @BibleId, 342001035, N'The angel replied, “The Holy Spirit will come upon you, and the power of the Most High will overshadow you. Therefore the child to be born will be holy; he will be called the Son of God.'
EXEC add_BibleVerse @BibleId, 342001036, N'“And look, your relative Elizabeth has also become pregnant with a son in her old age – although she was called barren, she is now in her sixth month!'
EXEC add_BibleVerse @BibleId, 342001037, N'For nothing will be impossible with God.”'
EXEC add_BibleVerse @BibleId, 342001038, N'So Mary said, “Yes, I am a servant of the Lord; let this happen to me according to your word.” Then the angel departed from her.'
EXEC add_BibleVerse @BibleId, 342001039, N'In those days Mary got up and went hurriedly into the hill country, to a town of Judah,'
EXEC add_BibleVerse @BibleId, 342001040, N'and entered Zechariah’s house and greeted Elizabeth.'
EXEC add_BibleVerse @BibleId, 342001041, N'When Elizabeth heard Mary’s greeting, the baby leaped in her womb, and Elizabeth was filled with the Holy Spirit.'
EXEC add_BibleVerse @BibleId, 342001042, N'She exclaimed with a loud voice, “Blessed are you among women, and blessed is the child in your womb!'
EXEC add_BibleVerse @BibleId, 342001043, N'And who am I that the mother of my Lord should come and visit me?'
EXEC add_BibleVerse @BibleId, 342001044, N'For the instant the sound of your greeting reached my ears, the baby in my womb leaped for joy.'
EXEC add_BibleVerse @BibleId, 342001045, N'And blessed is she who believed that what was spoken to her by the Lord would be fulfilled.”'
EXEC add_BibleVerse @BibleId, 342001046, N'And Mary said, “My soul exalts the Lord,'
EXEC add_BibleVerse @BibleId, 342001047, N'and my spirit has begun to rejoice in God my Savior,'
EXEC add_BibleVerse @BibleId, 342001048, N'because he has looked upon the humble state of his servant. For from now on all generations will call me blessed,'
EXEC add_BibleVerse @BibleId, 342001049, N'because he who is mighty has done great things for me, and holy is his name;'
EXEC add_BibleVerse @BibleId, 342001050, N'from generation to generation he is merciful to those who fear him.'
EXEC add_BibleVerse @BibleId, 342001051, N'He has demonstrated power with his arm; he has scattered those whose pride wells up from the sheer arrogance of their hearts.'
EXEC add_BibleVerse @BibleId, 342001052, N'He has brought down the mighty from their thrones, and has lifted up those of lowly position;'
EXEC add_BibleVerse @BibleId, 342001053, N'he has filled the hungry with good things, and has sent the rich away empty.'
EXEC add_BibleVerse @BibleId, 342001054, N'He has helped his servant Israel, remembering his mercy,'
EXEC add_BibleVerse @BibleId, 342001055, N'as he promised to our ancestors, to Abraham and to his descendants forever.”'
EXEC add_BibleVerse @BibleId, 342001056, N'So Mary stayed with Elizabeth about three months and then returned to her home.'
EXEC add_BibleVerse @BibleId, 342001057, N'Now the time came for Elizabeth to have her baby, and she gave birth to a son.'
EXEC add_BibleVerse @BibleId, 342001058, N'Her neighbors and relatives heard that the Lord had shown great mercy to her, and they rejoiced with her.'
EXEC add_BibleVerse @BibleId, 342001059, N'On the eighth day they came to circumcise the child, and they wanted to name him Zechariah after his father.'
EXEC add_BibleVerse @BibleId, 342001060, N'But his mother replied, “No! He must be named John.”'
EXEC add_BibleVerse @BibleId, 342001061, N'They said to her, “But none of your relatives bears this name.”'
EXEC add_BibleVerse @BibleId, 342001062, N'So they made signs to the baby’s father, inquiring what he wanted to name his son.'
EXEC add_BibleVerse @BibleId, 342001063, N'He asked for a writing tablet and wrote, “His name is John.” And they were all amazed.'
EXEC add_BibleVerse @BibleId, 342001064, N'Immediately Zechariah’s mouth was opened and his tongue released, and he spoke, blessing God.'
EXEC add_BibleVerse @BibleId, 342001065, N'All their neighbors were filled with fear, and throughout the entire hill country of Judea all these things were talked about.'
EXEC add_BibleVerse @BibleId, 342001066, N'All who heard these things kept them in their hearts, saying, “What then will this child be?” For the Lord’s hand was indeed with him.'
EXEC add_BibleVerse @BibleId, 342001067, N'Then his father Zechariah was filled with the Holy Spirit and prophesied,'
EXEC add_BibleVerse @BibleId, 342001068, N'“Blessed be the Lord God of Israel, because he has come to help and has redeemed his people.'
EXEC add_BibleVerse @BibleId, 342001069, N'For he has raised up a horn of salvation for us in the house of his servant David,'
EXEC add_BibleVerse @BibleId, 342001070, N'as he spoke through the mouth of his holy prophets from long ago,'
EXEC add_BibleVerse @BibleId, 342001071, N'that we should be saved from our enemies, and from the hand of all who hate us.'
EXEC add_BibleVerse @BibleId, 342001072, N'He has done this to show mercy to our ancestors, and to remember his holy covenant –'
EXEC add_BibleVerse @BibleId, 342001073, N'the oath that he swore to our ancestor Abraham. This oath grants'
EXEC add_BibleVerse @BibleId, 342001074, N'that we, being rescued from the hand of our enemies, may serve him without fear,'
EXEC add_BibleVerse @BibleId, 342001075, N'in holiness and righteousness before him for as long as we live.'
EXEC add_BibleVerse @BibleId, 342001076, N'And you, child, will be called the prophet of the Most High. For you will go before the Lord to prepare his ways,'
EXEC add_BibleVerse @BibleId, 342001077, N'to give his people knowledge of salvation through the forgiveness of their sins.'
EXEC add_BibleVerse @BibleId, 342001078, N'Because of our God’s tender mercy the dawn will break upon us from on high'
EXEC add_BibleVerse @BibleId, 342001079, N'to give light to those who sit in darkness and in the shadow of death, to guide our feet into the way of peace.”'
EXEC add_BibleVerse @BibleId, 342001080, N'And the child kept growing and becoming strong in spirit, and he was in the wilderness until the day he was revealed to Israel.'
EXEC add_BibleVerse @BibleId, 342002001, N'Now in those days a decree went out from Caesar Augustus to register all the empire for taxes.'
EXEC add_BibleVerse @BibleId, 342002002, N'This was the first registration, taken when Quirinius was governor of Syria.'
EXEC add_BibleVerse @BibleId, 342002003, N'Everyone went to his own town to be registered.'
EXEC add_BibleVerse @BibleId, 342002004, N'So Joseph also went up from the town of Nazareth because he was of the house and family line of David.'
EXEC add_BibleVerse @BibleId, 342002005, N'He went to be registered with Mary, who was promised in marriage to him, and who was expecting a child.'
EXEC add_BibleVerse @BibleId, 342002006, N'While they were there, the time came for her to deliver her child.'
EXEC add_BibleVerse @BibleId, 342002007, N'And she gave birth to her firstborn son and wrapped him in strips of cloth and laid him in a manger, because there was no place for them in the inn.'
EXEC add_BibleVerse @BibleId, 342002008, N'Now there were shepherds nearby living out in the field, keeping guard over their flock at night.'
EXEC add_BibleVerse @BibleId, 342002009, N'An angel of the Lord appeared to them, and the glory of the Lord shone around them, and they were absolutely terrified.'
EXEC add_BibleVerse @BibleId, 342002010, N'But the angel said to them, “Do not be afraid! Listen carefully, for I proclaim to you good news that brings great joy to all the people:'
EXEC add_BibleVerse @BibleId, 342002011, N'Today your Savior is born in the city of David. He is Christ the Lord.'
EXEC add_BibleVerse @BibleId, 342002012, N'This will be a sign for you: You will find a baby wrapped in strips of cloth and lying in a manger.”'
EXEC add_BibleVerse @BibleId, 342002013, N'Suddenly a vast, heavenly army appeared with the angel, praising God and saying,'
EXEC add_BibleVerse @BibleId, 342002014, N'“Glory to God in the highest, and on earth peace among people with whom he is pleased!”'
EXEC add_BibleVerse @BibleId, 342002015, N'When the angels left them and went back to heaven, the shepherds said to one another, “Let us go over to Bethlehem and see this thing that has taken place, that the Lord has made known to us.”'
EXEC add_BibleVerse @BibleId, 342002016, N'So they hurried off and located Mary and Joseph, and found the baby lying in a manger.'
EXEC add_BibleVerse @BibleId, 342002017, N'When they saw him, they related what they had been told about this child,'
EXEC add_BibleVerse @BibleId, 342002018, N'and all who heard it were astonished at what the shepherds said.'
EXEC add_BibleVerse @BibleId, 342002019, N'But Mary treasured up all these words, pondering in her heart what they might mean.'
EXEC add_BibleVerse @BibleId, 342002020, N'So the shepherds returned, glorifying and praising God for all they had heard and seen; everything was just as they had been told.'
EXEC add_BibleVerse @BibleId, 342002021, N'At the end of eight days, when he was circumcised, he was named Jesus, the name given by the angel before he was conceived in the womb.'
EXEC add_BibleVerse @BibleId, 342002022, N'Now when the time came for their purification according to the law of Moses, Joseph and Mary brought Jesus up to Jerusalem to present him to the Lord'
EXEC add_BibleVerse @BibleId, 342002023, N'(just as it is written in the law of the Lord, “ Every firstborn male will be set apart to the Lord” ),'
EXEC add_BibleVerse @BibleId, 342002024, N'and to offer a sacrifice according to what is specified in the law of the Lord, a pair of doves of doves or two young pigeons.'
EXEC add_BibleVerse @BibleId, 342002025, N'Now there was a man in Jerusalem named Simeon who was righteous and devout, looking for the restoration of Israel, and the Holy Spirit was upon him.'
EXEC add_BibleVerse @BibleId, 342002026, N'It had been revealed to him by the Holy Spirit that he would not die before he had seen the Lord’s Christ.'
EXEC add_BibleVerse @BibleId, 342002027, N'So Simeon, directed by the Spirit, came into the temple courts, and when the parents brought in the child Jesus to do for him what was customary according to the law,'
EXEC add_BibleVerse @BibleId, 342002028, N'Simeon took him in his arms and blessed God, saying,'
EXEC add_BibleVerse @BibleId, 342002029, N'“Now, according to your word, Sovereign Lord, permit your servant to depart in peace.'
EXEC add_BibleVerse @BibleId, 342002030, N'For my eyes have seen your salvation'
EXEC add_BibleVerse @BibleId, 342002031, N'that you have prepared in the presence of all peoples:'
EXEC add_BibleVerse @BibleId, 342002032, N'a light, for revelation to the Gentiles, and for glory to your people Israel.”'
EXEC add_BibleVerse @BibleId, 342002033, N'So the child’s father and mother were amazed at what was said about him.'
EXEC add_BibleVerse @BibleId, 342002034, N'Then Simeon blessed them and said to his mother Mary, “Listen carefully: This child is destined to be the cause of the falling and rising of many in Israel and to be a sign that will be rejected.'
EXEC add_BibleVerse @BibleId, 342002035, N'Indeed, as a result of him the thoughts of many hearts will be revealed – and a sword will pierce your own soul as well!”'
EXEC add_BibleVerse @BibleId, 342002036, N'There was also a prophetess, Anna the daughter of Phanuel, of the tribe of Asher. She was very old, having been married to her husband for seven years until his death.'
EXEC add_BibleVerse @BibleId, 342002037, N'She had lived as a widow since then for eighty-four years. She never left the temple, worshiping with fasting and prayer night and day.'
EXEC add_BibleVerse @BibleId, 342002038, N'At that moment, she came up to them and began to give thanks to God and to speak about the child to all who were waiting for the redemption of Jerusalem.'
EXEC add_BibleVerse @BibleId, 342002039, N'So when Joseph and Mary had performed everything according to the law of the Lord, they returned to Galilee, to their own town of Nazareth.'
EXEC add_BibleVerse @BibleId, 342002040, N'And the child grew and became strong, filled with wisdom, and the favor of God was upon him.'
EXEC add_BibleVerse @BibleId, 342002041, N'Now Jesus’ parents went to Jerusalem every year for the feast of the Passover.'
EXEC add_BibleVerse @BibleId, 342002042, N'When he was twelve years old, they went up according to custom.'
EXEC add_BibleVerse @BibleId, 342002043, N'But when the feast was over, as they were returning home, the boy Jesus stayed behind in Jerusalem. His parents did not know it,'
EXEC add_BibleVerse @BibleId, 342002044, N'but (because they assumed that he was in their group of travelers) they went a day’s journey. Then they began to look for him among their relatives and acquaintances.'
EXEC add_BibleVerse @BibleId, 342002045, N'When they did not find him, they returned to Jerusalem to look for him.'
EXEC add_BibleVerse @BibleId, 342002046, N'After three days they found him in the temple courts, sitting among the teachers, listening to them and asking them questions.'
EXEC add_BibleVerse @BibleId, 342002047, N'And all who heard Jesus were astonished at his understanding and his answers.'
EXEC add_BibleVerse @BibleId, 342002048, N'When his parents saw him, they were overwhelmed. His mother said to him, “Child, why have you treated us like this? Look, your father and I have been looking for you anxiously.”'
EXEC add_BibleVerse @BibleId, 342002049, N'But he replied, “Why were you looking for me? Didn’t you know that I must be in my Father’s house?”'
EXEC add_BibleVerse @BibleId, 342002050, N'Yet his parents did not understand the remark he made to them.'
EXEC add_BibleVerse @BibleId, 342002051, N'Then he went down with them and came to Nazareth, and was obedient to them. But his mother kept all these things in her heart.'
EXEC add_BibleVerse @BibleId, 342002052, N'And Jesus increased in wisdom and in stature, and in favor with God and with people.'
EXEC add_BibleVerse @BibleId, 342003001, N'In the fifteenth year of the reign of Tiberius Caesar, when Pontius Pilate was governor of Judea, and Herod was tetrarch of Galilee, and his brother Philip was tetrarch of the region of Iturea and Trachonitis, and Lysanias was tetrarch of Abilene,'
EXEC add_BibleVerse @BibleId, 342003002, N'during the high priesthood of Annas and Caiaphas, the word of God came to John the son of Zechariah in the wilderness.'
EXEC add_BibleVerse @BibleId, 342003003, N'He went into all the region around the Jordan River, preaching a baptism of repentance for the forgiveness of sins.'
EXEC add_BibleVerse @BibleId, 342003004, N'As it is written in the book of the words of Isaiah the prophet, “The voice of one shouting in the wilderness: ‘Prepare the way for the Lord, make his paths straight*.'
EXEC add_BibleVerse @BibleId, 342003005, N'Every valley will be filled, and every mountain and hill will be brought low, and the crooked will be made straight, and the rough ways will be made smooth,'
EXEC add_BibleVerse @BibleId, 342003006, N'and all humanity will see the salvation of God.’”'
EXEC add_BibleVerse @BibleId, 342003007, N'So John said to the crowds that came out to be baptized by him, “You offspring of vipers! Who warned you to flee from the coming wrath?'
EXEC add_BibleVerse @BibleId, 342003008, N'Therefore produce fruit that proves your repentance, and don’t begin to say to yourselves, ‘We have Abraham as our father.’ For I tell you that God can raise up children for Abraham from these stones!'
EXEC add_BibleVerse @BibleId, 342003009, N'Even now the ax is laid at the root of the trees, and every tree that does not produce good fruit will be cut down and thrown into the fire.”'
EXEC add_BibleVerse @BibleId, 342003010, N'So the crowds were asking him, “What then should we do?”'
EXEC add_BibleVerse @BibleId, 342003011, N'John answered them, “The person who has two tunics must share with the person who has none, and the person who has food must do likewise.”'
EXEC add_BibleVerse @BibleId, 342003012, N'Tax collectors also came to be baptized, and they said to him, “Teacher, what should we do?”'
EXEC add_BibleVerse @BibleId, 342003013, N'He told them, “Collect no more than you are required to.”'
EXEC add_BibleVerse @BibleId, 342003014, N'Then some soldiers also asked him, “And as for us – what should we do?” He told them, “Take money from no one by violence or by false accusation, and be content with your pay.”'
EXEC add_BibleVerse @BibleId, 342003015, N'While the people were filled with anticipation and they all wondered whether perhaps John could be the Christ,'
EXEC add_BibleVerse @BibleId, 342003016, N'John answered them all, “I baptize you with water, but one more powerful than I am is coming – I am not worthy to untie the strap of his sandals. He will baptize you with the Holy Spirit and fire.'
EXEC add_BibleVerse @BibleId, 342003017, N'His winnowing fork is in his hand to clean out his threshing floor and to gather the wheat into his storehouse, but the chaff he will burn up with inextinguishable fire.”'
EXEC add_BibleVerse @BibleId, 342003018, N'And in this way, with many other exhortations, John proclaimed good news to the people.'
EXEC add_BibleVerse @BibleId, 342003019, N'But when John rebuked Herod the tetrarch because of Herodias, his brother’s wife, and because of all the evil deeds that he had done,'
EXEC add_BibleVerse @BibleId, 342003020, N'Herod added this to them all: He locked up John in prison.'
EXEC add_BibleVerse @BibleId, 342003021, N'Now when all the people were baptized, Jesus also was baptized. And while he was praying, the heavens opened,'
EXEC add_BibleVerse @BibleId, 342003022, N'and the Holy Spirit descended on him in bodily form like a dove. And a voice came from heaven, “You are my one dear Son; in you I take great delight.”'
EXEC add_BibleVerse @BibleId, 342003023, N'So Jesus, when he began his ministry, was about thirty years old. He was the son (as was supposed) of Joseph, the son of Heli,'
EXEC add_BibleVerse @BibleId, 342003024, N'the son of Matthat, the son of Levi, the son of Melchi, the son of Jannai, the son of Joseph,'
EXEC add_BibleVerse @BibleId, 342003025, N'the son of Mattathias, the son of Amos, the son of Nahum, the son of Esli, the son of Naggai,'
EXEC add_BibleVerse @BibleId, 342003026, N'the son of Maath, the son of Mattathias, the son of Semein, the son of Josech, the son of Joda,'
EXEC add_BibleVerse @BibleId, 342003027, N'the son of Joanan, the son of Rhesa, the son of Zerubbabel, the son of Shealtiel, the son of Neri,'
EXEC add_BibleVerse @BibleId, 342003028, N'the son of Melchi, the son of Addi, the son of Cosam, the son of Elmadam, the son of Er,'
EXEC add_BibleVerse @BibleId, 342003029, N'the son of Joshua, the son of Eliezer, the son of Jorim, the son of Matthat, the son of Levi,'
EXEC add_BibleVerse @BibleId, 342003030, N'the son of Simeon, the son of Judah, the son of Joseph, the son of Jonam, the son of Eliakim,'
EXEC add_BibleVerse @BibleId, 342003031, N'the son of Melea, the son of Menna, the son of Mattatha, the son of Nathan, the son of David,'
EXEC add_BibleVerse @BibleId, 342003032, N'the son of Jesse, the son of Obed, the son of Boaz, the son of Sala, the son of Nahshon,'
EXEC add_BibleVerse @BibleId, 342003033, N'the son of Amminadab, the son of Admin, the son of Arni, the son of Hezron, the son of Perez, the son of Judah,'
EXEC add_BibleVerse @BibleId, 342003034, N'the son of Jacob, the son of Isaac, the son of Abraham, the son of Terah, the son of Nahor,'
EXEC add_BibleVerse @BibleId, 342003035, N'the son of Serug, the son of Reu, the son of Peleg, the son of Eber, the son of Shelah,'
EXEC add_BibleVerse @BibleId, 342003036, N'the son of Cainan, the son of Arphaxad, the son of Shem, the son of Noah, the son of Lamech,'
EXEC add_BibleVerse @BibleId, 342003037, N'the son of Methuselah, the son of Enoch, the son of Jared, the son of Mahalalel, the son of Kenan,'
EXEC add_BibleVerse @BibleId, 342003038, N'the son of Enosh, the son of Seth, the son of Adam, the son of God.'
EXEC add_BibleVerse @BibleId, 342004001, N'Then Jesus, full of the Holy Spirit, returned from the Jordan River and was led by the Spirit in the wilderness,'
EXEC add_BibleVerse @BibleId, 342004002, N'where for forty days he endured temptations from the devil. He ate nothing during those days, and when they were completed, he was famished.'
EXEC add_BibleVerse @BibleId, 342004003, N'The devil said to him, “If you are the Son of God, command this stone to become bread.”'
EXEC add_BibleVerse @BibleId, 342004004, N'Jesus answered him, “It is written, ‘ Man does not live by bread alone.’”'
EXEC add_BibleVerse @BibleId, 342004005, N'Then the devil led him up to a high place and showed him in a flash all the kingdoms of the world.'
EXEC add_BibleVerse @BibleId, 342004006, N'And he said to him, “To you I will grant this whole realm – and the glory that goes along with it, for it has been relinquished to me, and I can give it to anyone I wish.'
EXEC add_BibleVerse @BibleId, 342004007, N'So then, if you will worship me, all this will be yours.”'
EXEC add_BibleVerse @BibleId, 342004008, N'Jesus answered him, “It is written, ‘ You are to worship the Lord your God and serve only him.’”'
EXEC add_BibleVerse @BibleId, 342004009, N'Then the devil brought him to Jerusalem, had him stand on the highest point of the temple, and said to him, “If you are the Son of God, throw yourself down from here,'
EXEC add_BibleVerse @BibleId, 342004010, N'for it is written, ‘ He will command his angels concerning you, to protect you,’'
EXEC add_BibleVerse @BibleId, 342004011, N'and ‘ with their hands they will lift you up, so that you will not strike your foot against a stone.’”'
EXEC add_BibleVerse @BibleId, 342004012, N'Jesus answered him, “It is said, ‘ You are not to put the Lord your God to the test.’”'
EXEC add_BibleVerse @BibleId, 342004013, N'So when the devil had completed every temptation, he departed from him until a more opportune time.'
EXEC add_BibleVerse @BibleId, 342004014, N'Then Jesus, in the power of the Spirit, returned to Galilee, and news about him spread throughout the surrounding countryside.'
EXEC add_BibleVerse @BibleId, 342004015, N'He began to teach in their synagogues and was praised by all.'
EXEC add_BibleVerse @BibleId, 342004016, N'Now Jesus came to Nazareth, where he had been brought up, and went into the synagogue on the Sabbath day, as was his custom. He stood up to read,'
EXEC add_BibleVerse @BibleId, 342004017, N'and the scroll of the prophet Isaiah was given to him. He unrolled the scroll and found the place where it was written,'
EXEC add_BibleVerse @BibleId, 342004018, N'“ The Spirit of the Lord is upon me, because he has anointed me to proclaim good news to the poor. He has sent me to proclaim release to the captives and the regaining of sight to the blind, to set free those who are oppressed,'
EXEC add_BibleVerse @BibleId, 342004019, N'to proclaim the year of the Lord’s favor.”'
EXEC add_BibleVerse @BibleId, 342004020, N'Then he rolled up the scroll, gave it back to the attendant, and sat down. The eyes of everyone in the synagogue were fixed on him.'
EXEC add_BibleVerse @BibleId, 342004021, N'Then he began to tell them, “Today this scripture has been fulfilled even as you heard it being read.”'
EXEC add_BibleVerse @BibleId, 342004022, N'All were speaking well of him, and were amazed at the gracious words coming out of his mouth. They said, “Isn’t this Joseph’s son?”'
EXEC add_BibleVerse @BibleId, 342004023, N'Jesus said to them, “No doubt you will quote to me the proverb, ‘Physician, heal yourself!’ and say, ‘What we have heard that you did in Capernaum, do here in your hometown too.’”'
EXEC add_BibleVerse @BibleId, 342004024, N'And he added, “I tell you the truth, no prophet is acceptable in his hometown.'
EXEC add_BibleVerse @BibleId, 342004025, N'But in truth I tell you, there were many widows in Israel in Elijah’s days, when the sky was shut up three and a half years, and there was a great famine over all the land.'
EXEC add_BibleVerse @BibleId, 342004026, N'Yet Elijah was sent to none of them, but only to a woman who was a widow at Zarephath in Sidon.'
EXEC add_BibleVerse @BibleId, 342004027, N'And there were many lepers in Israel in the time of the prophet Elisha, yet none of them was cleansed except Naaman the Syrian.”'
EXEC add_BibleVerse @BibleId, 342004028, N'When they heard this, all the people in the synagogue were filled with rage.'
EXEC add_BibleVerse @BibleId, 342004029, N'They got up, forced him out of the town, and brought him to the brow of the hill on which their town was built, so that they could throw him down the cliff.'
EXEC add_BibleVerse @BibleId, 342004030, N'But he passed through the crowd and went on his way.'
EXEC add_BibleVerse @BibleId, 342004031, N'So he went down to Capernaum, a town in Galilee, and on the Sabbath he began to teach the people.'
EXEC add_BibleVerse @BibleId, 342004032, N'They were amazed at his teaching, because he spoke with authority.'
EXEC add_BibleVerse @BibleId, 342004033, N'Now in the synagogue there was a man who had the spirit of an unclean demon, and he cried out with a loud voice,'
EXEC add_BibleVerse @BibleId, 342004034, N'“Ha! Leave us alone, Jesus the Nazarene! Have you come to destroy us? I know who you are – the Holy One of God.”'
EXEC add_BibleVerse @BibleId, 342004035, N'But Jesus rebuked him: “Silence! Come out of him!” Then, after the demon threw the man down in their midst, he came out of him without hurting him.'
EXEC add_BibleVerse @BibleId, 342004036, N'They were all amazed and began to say to one another, “What’s happening here? For with authority and power he commands the unclean spirits, and they come out!”'
EXEC add_BibleVerse @BibleId, 342004037, N'So the news about him spread into all areas of the region.'
EXEC add_BibleVerse @BibleId, 342004038, N'After Jesus left the synagogue, he entered Simon’s house. Now Simon’s mother-in-law was suffering from a high fever, and they asked Jesus to help her.'
EXEC add_BibleVerse @BibleId, 342004039, N'So he stood over her, commanded the fever, and it left her. Immediately she got up and began to serve them.'
EXEC add_BibleVerse @BibleId, 342004040, N'As the sun was setting, all those who had any relatives sick with various diseases brought them to Jesus. He placed his hands on every one of them and healed them.'
EXEC add_BibleVerse @BibleId, 342004041, N'Demons also came out of many, crying out, “You are the Son of God!” But he rebuked them, and would not allow them to speak, because they knew that he was the Christ.'
EXEC add_BibleVerse @BibleId, 342004042, N'The next morning Jesus departed and went to a deserted place. Yet the crowds were seeking him, and they came to him and tried to keep him from leaving them.'
EXEC add_BibleVerse @BibleId, 342004043, N'But Jesus said to them, “I must proclaim the good news of the kingdom of God to the other towns too, for that is what I was sent to do.”'
EXEC add_BibleVerse @BibleId, 342004044, N'So he continued to preach in the synagogues of Judea.'
EXEC add_BibleVerse @BibleId, 342005001, N'Now Jesus was standing by the Lake of Gennesaret, and the crowd was pressing around him to hear the word of God.'
EXEC add_BibleVerse @BibleId, 342005002, N'He saw two boats by the lake, but the fishermen had gotten out of them and were washing their nets.'
EXEC add_BibleVerse @BibleId, 342005003, N'He got into one of the boats, which was Simon’s, and asked him to put out a little way from the shore. Then Jesus sat down and taught the crowds from the boat.'
EXEC add_BibleVerse @BibleId, 342005004, N'When he had finished speaking, he said to Simon, “Put out into the deep water and lower your nets for a catch.”'
EXEC add_BibleVerse @BibleId, 342005005, N'Simon answered, “Master, we worked hard all night and caught nothing! But at your word I will lower the nets.”'
EXEC add_BibleVerse @BibleId, 342005006, N'When they had done this, they caught so many fish that their nets started to tear.'
EXEC add_BibleVerse @BibleId, 342005007, N'So they motioned to their partners in the other boat to come and help them. And they came and filled both boats, so that they were about to sink.'
EXEC add_BibleVerse @BibleId, 342005008, N'But when Simon Peter saw it, he fell down at Jesus’ knees, saying, “Go away from me, Lord, for I am a sinful man!”'
EXEC add_BibleVerse @BibleId, 342005009, N'For Peter and all who were with him were astonished at the catch of fish that they had taken,'
EXEC add_BibleVerse @BibleId, 342005010, N'and so were James and John, Zebedee’s sons, who were Simon’s business partners. Then Jesus said to Simon, “Do not be afraid; from now on you will be catching people.”'
EXEC add_BibleVerse @BibleId, 342005011, N'So when they had brought their boats to shore, they left everything and followed him.'
EXEC add_BibleVerse @BibleId, 342005012, N'While Jesus was in one of the towns, a man came to him who was covered with leprosy. When he saw Jesus, he bowed down with his face to the ground and begged him, “Lord, if you are willing, you can make me clean.”'
EXEC add_BibleVerse @BibleId, 342005013, N'So he stretched out his hand and touched him, saying, “I am willing. Be clean!” And immediately the leprosy left him.'
EXEC add_BibleVerse @BibleId, 342005014, N'Then he ordered the man to tell no one, but commanded him, “Go and show yourself to a priest, and bring the offering for your cleansing, as Moses commanded, as a testimony to them.”'
EXEC add_BibleVerse @BibleId, 342005015, N'But the news about him spread even more, and large crowds were gathering together to hear him and to be healed of their illnesses.'
EXEC add_BibleVerse @BibleId, 342005016, N'Yet Jesus himself frequently withdrew to the wilderness and prayed.'
EXEC add_BibleVerse @BibleId, 342005017, N'Now on one of those days, while he was teaching, there were Pharisees and teachers of the law sitting nearby (who had come from every village of Galilee and Judea and from Jerusalem), and the power of the Lord was with him to heal.'
EXEC add_BibleVerse @BibleId, 342005018, N'Just then some men showed up, carrying a paralyzed man on a stretcher. They were trying to bring him in and place him before Jesus.'
EXEC add_BibleVerse @BibleId, 342005019, N'But since they found no way to carry him in because of the crowd, they went up on the roof and let him down on the stretcher through the roof tiles right in front of Jesus.'
EXEC add_BibleVerse @BibleId, 342005020, N'When Jesus saw their faith he said, “Friend, your sins are forgiven.”'
EXEC add_BibleVerse @BibleId, 342005021, N'Then the experts in the law and the Pharisees began to think to themselves, “Who is this man who is uttering blasphemies? Who can forgive sins but God alone?”'
EXEC add_BibleVerse @BibleId, 342005022, N'When Jesus perceived their hostile thoughts, he said to them, “Why are you raising objections within yourselves?'
EXEC add_BibleVerse @BibleId, 342005023, N'Which is easier, to say, ‘Your sins are forgiven,’ or to say, ‘Stand up and walk’?'
EXEC add_BibleVerse @BibleId, 342005024, N'But so that you may know that the Son of Man has authority on earth to forgive sins” – he said to the paralyzed man – “I tell you, stand up, take your stretcher and go home.”'
EXEC add_BibleVerse @BibleId, 342005025, N'Immediately he stood up before them, picked up the stretcher he had been lying on, and went home, glorifying God.'
EXEC add_BibleVerse @BibleId, 342005026, N'Then astonishment seized them all, and they glorified God. They were filled with awe, saying, “We have seen incredible things today.”'
EXEC add_BibleVerse @BibleId, 342005027, N'After this, Jesus went out and saw a tax collector named Levi sitting at the tax booth. “Follow me,” he said to him.'
EXEC add_BibleVerse @BibleId, 342005028, N'And he got up and followed him, leaving everything behind.'
EXEC add_BibleVerse @BibleId, 342005029, N'Then Levi gave a great banquet in his house for Jesus, and there was a large crowd of tax collectors and others sitting at the table with them.'
EXEC add_BibleVerse @BibleId, 342005030, N'But the Pharisees and their experts in the law complained to his disciples, saying, “Why do you eat and drink with tax collectors and sinners?”'
EXEC add_BibleVerse @BibleId, 342005031, N'Jesus answered them, “Those who are well don’t need a physician, but those who are sick do.'
EXEC add_BibleVerse @BibleId, 342005032, N'I have not come to call the righteous, but sinners to repentance.”'
EXEC add_BibleVerse @BibleId, 342005033, N'Then they said to him, “John’s disciples frequently fast and pray, and so do the disciples of the Pharisees, but yours continue to eat and drink.”'
EXEC add_BibleVerse @BibleId, 342005034, N'So Jesus said to them, “You cannot make the wedding guests fast while the bridegroom is with them, can you?'
EXEC add_BibleVerse @BibleId, 342005035, N'But those days are coming, and when the bridegroom is taken from them, at that time they will fast.”'
EXEC add_BibleVerse @BibleId, 342005036, N'He also told them a parable: “No one tears a patch from a new garment and sews it on an old garment. If he does, he will have torn the new, and the piece from the new will not match the old.'
EXEC add_BibleVerse @BibleId, 342005037, N'And no one pours new wine into old wineskins. If he does, the new wine will burst the skins and will be spilled, and the skins will be destroyed.'
EXEC add_BibleVerse @BibleId, 342005038, N'Instead new wine must be poured into new wineskins.'
EXEC add_BibleVerse @BibleId, 342005039, N'No one after drinking old wine wants the new, for he says, ‘The old is good enough.’”'
EXEC add_BibleVerse @BibleId, 342006001, N'Jesus was going through the grain fields on a Sabbath, and his disciples picked some heads of wheat, rubbed them in their hands, and ate them.'
EXEC add_BibleVerse @BibleId, 342006002, N'But some of the Pharisees said, “Why are you doing what is against the law on the Sabbath?”'
EXEC add_BibleVerse @BibleId, 342006003, N'Jesus answered them, “Haven’t you read what David did when he and his companions were hungry –'
EXEC add_BibleVerse @BibleId, 342006004, N'how he entered the house of God, took and ate the sacred bread, which is not lawful for any to eat but the priests alone, and gave it to his companions?”'
EXEC add_BibleVerse @BibleId, 342006005, N'Then he said to them, “The Son of Man is lord of the Sabbath.”'
EXEC add_BibleVerse @BibleId, 342006006, N'On another Sabbath, Jesus entered the synagogue and was teaching. Now a man was there whose right hand was withered.'
EXEC add_BibleVerse @BibleId, 342006007, N'The experts in the law and the Pharisees watched Jesus closely to see if he would heal on the Sabbath, so that they could find a reason to accuse him.'
EXEC add_BibleVerse @BibleId, 342006008, N'But he knew their thoughts, and said to the man who had the withered hand, “Get up and stand here.” So he rose and stood there.'
EXEC add_BibleVerse @BibleId, 342006009, N'Then Jesus said to them, “I ask you, is it lawful to do good on the Sabbath or to do evil, to save a life or to destroy it?”'
EXEC add_BibleVerse @BibleId, 342006010, N'After looking around at them all, he said to the man, “Stretch out your hand.” The man did so, and his hand was restored.'
EXEC add_BibleVerse @BibleId, 342006011, N'But they were filled with mindless rage and began debating with one another what they would do to Jesus.'
EXEC add_BibleVerse @BibleId, 342006012, N'Now it was during this time that Jesus went out to the mountain to pray, and he spent all night in prayer to God.'
EXEC add_BibleVerse @BibleId, 342006013, N'When morning came, he called his disciples and chose twelve of them, whom he also named apostles:'
EXEC add_BibleVerse @BibleId, 342006014, N'Simon (whom he named Peter), and his brother Andrew; and James, John, Philip, Bartholomew,'
EXEC add_BibleVerse @BibleId, 342006015, N'Matthew, Thomas, James the son of Alphaeus, Simon who was called the Zealot,'
EXEC add_BibleVerse @BibleId, 342006016, N'Judas the son of James, and Judas Iscariot, who became a traitor.'
EXEC add_BibleVerse @BibleId, 342006017, N'Then he came down with them and stood on a level place. And a large number of his disciples had gathered along with a vast multitude from all over Judea, from Jerusalem, They came to hear him and to be healed of their diseases,'
EXEC add_BibleVerse @BibleId, 342006018, N'and those who suffered from unclean spirits were cured.'
EXEC add_BibleVerse @BibleId, 342006019, N'The whole crowd was trying to touch him, because power was coming out from him and healing them all.'
EXEC add_BibleVerse @BibleId, 342006020, N'Then he looked up at his disciples and said: “Blessed are you who are poor, for the kingdom of God belongs to you.'
EXEC add_BibleVerse @BibleId, 342006021, N'“Blessed are you who hunger now, for you will be satisfied. “Blessed are you who weep now, for you will laugh.'
EXEC add_BibleVerse @BibleId, 342006022, N'“Blessed are you when people hate you, and when they exclude you and insult you and reject you as evil on account of the Son of Man!'
EXEC add_BibleVerse @BibleId, 342006023, N'Rejoice in that day, and jump for joy, because your reward is great in heaven. For their ancestors did the same things to the prophets.'
EXEC add_BibleVerse @BibleId, 342006024, N'“But woe to you who are rich, for you have received your comfort already.'
EXEC add_BibleVerse @BibleId, 342006025, N'“Woe to you who are well satisfied with food now, for you will be hungry. “Woe to you who laugh now, for you will mourn and weep.'
EXEC add_BibleVerse @BibleId, 342006026, N'“Woe to you when all people speak well of you, for their ancestors did the same things to the false prophets.'
EXEC add_BibleVerse @BibleId, 342006027, N'“But I say to you who are listening: Love your enemies, do good to those who hate you,'
EXEC add_BibleVerse @BibleId, 342006028, N'bless those who curse you, pray for those who mistreat you.'
EXEC add_BibleVerse @BibleId, 342006029, N'To the person who strikes you on the cheek, offer the other as well, and from the person who takes away your coat, do not withhold your tunic either.'
EXEC add_BibleVerse @BibleId, 342006030, N'Give to everyone who asks you, and do not ask for your possessions back from the person who takes them away.'
EXEC add_BibleVerse @BibleId, 342006031, N'Treat others in the same way that you would want them to treat you.'
EXEC add_BibleVerse @BibleId, 342006032, N'“If you love those who love you, what credit is that to you? For even sinners love those who love them.'
EXEC add_BibleVerse @BibleId, 342006033, N'And if you do good to those who do good to you, what credit is that to you? Even sinners do the same.'
EXEC add_BibleVerse @BibleId, 342006034, N'And if you lend to those from whom you hope to be repaid, what credit is that to you? Even sinners lend to sinners, so that they may be repaid in full.'
EXEC add_BibleVerse @BibleId, 342006035, N'But love your enemies, and do good, and lend, expecting nothing back. Then your reward will be great, and you will be sons of the Most High, because he is kind to ungrateful and evil people.'
EXEC add_BibleVerse @BibleId, 342006036, N'Be merciful, just as your Father is merciful.'
EXEC add_BibleVerse @BibleId, 342006037, N'“Do not judge, and you will not be judged; do not condemn, and you will not be condemned; forgive, and you will be forgiven.'
EXEC add_BibleVerse @BibleId, 342006038, N'Give, and it will be given to you: A good measure, pressed down, shaken together, running over, will be poured into your lap. For the measure you use will be the measure you receive.”'
EXEC add_BibleVerse @BibleId, 342006039, N'He also told them a parable: “Someone who is blind cannot lead another who is blind, can he? Won’t they both fall into a pit?'
EXEC add_BibleVerse @BibleId, 342006040, N'A disciple is not greater than his teacher, but everyone when fully trained will be like his teacher.'
EXEC add_BibleVerse @BibleId, 342006041, N'Why do you see the speck in your brother’s eye, but fail to see the beam of wood in your own?'
EXEC add_BibleVerse @BibleId, 342006042, N'How can you say to your brother, ‘Brother, let me remove the speck from your eye,’ while you yourself don’t see the beam in your own? You hypocrite! First remove the beam from your own eye, and then you can see clearly to remove the speck from your brother’s eye.'
EXEC add_BibleVerse @BibleId, 342006043, N'“For no good tree bears bad fruit, nor again does a bad tree bear good fruit,'
EXEC add_BibleVerse @BibleId, 342006044, N'for each tree is known by its own fruit. For figs are not gathered from thorns, nor are grapes picked from brambles.'
EXEC add_BibleVerse @BibleId, 342006045, N'The good person out of the good treasury of his heart produces good, and the evil person out of his evil treasury produces evil, for his mouth speaks from what fills his heart.'
EXEC add_BibleVerse @BibleId, 342006046, N'“Why do you call me ‘Lord, Lord,’ and don’t do what I tell you?'
EXEC add_BibleVerse @BibleId, 342006047, N'“Everyone who comes to me and listens to my words and puts them into practice – I will show you what he is like:'
EXEC add_BibleVerse @BibleId, 342006048, N'He is like a man building a house, who dug down deep, and laid the foundation on bedrock. When a flood came, the river burst against that house but could not shake it, because it had been well built.'
EXEC add_BibleVerse @BibleId, 342006049, N'But the person who hears and does not put my words into practice is like a man who built a house on the ground without a foundation. When the river burst against that house, it collapsed immediately, and was utterly destroyed!”'
EXEC add_BibleVerse @BibleId, 342007001, N'After Jesus had finished teaching all this to the people, he entered Capernaum.'
EXEC add_BibleVerse @BibleId, 342007002, N'A centurion there had a slave who was highly regarded, but who was sick and at the point of death.'
EXEC add_BibleVerse @BibleId, 342007003, N'When the centurion heard about Jesus, he sent some Jewish elders to him, asking him to come and heal his slave.'
EXEC add_BibleVerse @BibleId, 342007004, N'When they came to Jesus, they urged him earnestly, “He is worthy to have you do this for him,'
EXEC add_BibleVerse @BibleId, 342007005, N'because he loves our nation, and even built our synagogue.”'
EXEC add_BibleVerse @BibleId, 342007006, N'So Jesus went with them. When he was not far from the house, the centurion sent friends to say to him, “Lord, do not trouble yourself, for I am not worthy to have you come under my roof.'
EXEC add_BibleVerse @BibleId, 342007007, N'That is why I did not presume to come to you. Instead, say the word, and my servant must be healed.'
EXEC add_BibleVerse @BibleId, 342007008, N'For I too am a man set under authority, with soldiers under me. I say to this one, ‘Go,’ and he goes, and to another, ‘Come,’ and he comes, and to my slave, ‘Do this,’ and he does it.”'
EXEC add_BibleVerse @BibleId, 342007009, N'When Jesus heard this, he was amazed at him. He turned and said to the crowd that followed him, “I tell you, not even in Israel have I found such faith!”'
EXEC add_BibleVerse @BibleId, 342007010, N'So when those who had been sent returned to the house, they found the slave well.'
EXEC add_BibleVerse @BibleId, 342007011, N'Soon afterward Jesus went to a town called Nain, and his disciples and a large crowd went with him.'
EXEC add_BibleVerse @BibleId, 342007012, N'As he approached the town gate, a man who had died was being carried out, the only son of his mother (who was a widow ), and a large crowd from the town was with her.'
EXEC add_BibleVerse @BibleId, 342007013, N'When the Lord saw her, he had compassion for her and said to her, “Do not weep.”'
EXEC add_BibleVerse @BibleId, 342007014, N'Then he came up and touched the bier, and those who carried it stood still. He said, “Young man, I say to you, get up!”'
EXEC add_BibleVerse @BibleId, 342007015, N'So the dead man sat up and began to speak, and Jesus gave him back to his mother.'
EXEC add_BibleVerse @BibleId, 342007016, N'Fear seized them all, and they began to glorify God, saying, “A great prophet has appeared among us!” and “God has come to help his people!”'
EXEC add_BibleVerse @BibleId, 342007017, N'This report about Jesus circulated throughout Judea and all the surrounding country.'
EXEC add_BibleVerse @BibleId, 342007018, N'John’s disciples informed him about all these things. So John called two of his disciples'
EXEC add_BibleVerse @BibleId, 342007019, N'and sent them to Jesus to ask, “Are you the one who is to come, or should we look for another?”'
EXEC add_BibleVerse @BibleId, 342007020, N'When the men came to Jesus, they said, “John the Baptist has sent us to you to ask, ‘Are you the one who is to come, or should we look for another?’”'
EXEC add_BibleVerse @BibleId, 342007021, N'At that very time Jesus cured many people of diseases, sicknesses, and evil spirits, and granted sight to many who were blind.'
EXEC add_BibleVerse @BibleId, 342007022, N'So he answered them, “Go tell John what you have seen and heard: The blind see, the lame walk, lepers are cleansed, the deaf hear, the dead are raised, the poor have good news proclaimed to them.'
EXEC add_BibleVerse @BibleId, 342007023, N'Blessed is anyone who takes no offense at me.”'
EXEC add_BibleVerse @BibleId, 342007024, N'When John’s messengers had gone, Jesus began to speak to the crowds about John: “What did you go out into the wilderness to see? A reed shaken by the wind?'
EXEC add_BibleVerse @BibleId, 342007025, N'What did you go out to see? A man dressed in fancy clothes? Look, those who wear fancy clothes and live in luxury are in kings’ courts!'
EXEC add_BibleVerse @BibleId, 342007026, N'What did you go out to see? A prophet? Yes, I tell you, and more than a prophet.'
EXEC add_BibleVerse @BibleId, 342007027, N'This is the one about whom it is written, ‘ Look, I am sending my messenger ahead of you, who will prepare your way before you.’'
EXEC add_BibleVerse @BibleId, 342007028, N'I tell you, among those born of women no one is greater than John. Yet the one who is least in the kingdom of God is greater than he is.”'
EXEC add_BibleVerse @BibleId, 342007029, N'(Now all the people who heard this, even the tax collectors, acknowledged God’s justice, because they had been baptized with John’s baptism.'
EXEC add_BibleVerse @BibleId, 342007030, N'However, the Pharisees and the experts in religious law rejected God’s purpose for themselves, because they had not been baptized by John. )'
EXEC add_BibleVerse @BibleId, 342007031, N'“To what then should I compare the people of this generation, and what are they like?'
EXEC add_BibleVerse @BibleId, 342007032, N'They are like children sitting in the marketplace and calling out to one another, ‘We played the flute for you, yet you did not dance; we wailed in mourning, yet you did not weep.’'
EXEC add_BibleVerse @BibleId, 342007033, N'For John the Baptist has come eating no bread and drinking no wine, and you say, ‘He has a demon!’'
EXEC add_BibleVerse @BibleId, 342007034, N'The Son of Man has come eating and drinking, and you say, ‘Look at him, a glutton and a drunk, a friend of tax collectors and sinners!’'
EXEC add_BibleVerse @BibleId, 342007035, N'But wisdom is vindicated by all her children.”'
EXEC add_BibleVerse @BibleId, 342007036, N'Now one of the Pharisees asked Jesus to have dinner with him, so he went into the Pharisee’s house and took his place at the table.'
EXEC add_BibleVerse @BibleId, 342007037, N'Then when a woman of that town, who was a sinner, learned that Jesus was dining at the Pharisee’s house, she brought an alabaster jar of perfumed oil.'
EXEC add_BibleVerse @BibleId, 342007038, N'As she stood behind him at his feet, weeping, she began to wet his feet with her tears. She wiped them with her hair, kissed them, and anointed them with the perfumed oil.'
EXEC add_BibleVerse @BibleId, 342007039, N'Now when the Pharisee who had invited him saw this, he said to himself, “If this man were a prophet, he would know who and what kind of woman this is who is touching him, that she is a sinner.”'
EXEC add_BibleVerse @BibleId, 342007040, N'So Jesus answered him, “Simon, I have something to say to you.” He replied, “Say it, Teacher.”'
EXEC add_BibleVerse @BibleId, 342007041, N'“A certain creditor had two debtors; one owed him five hundred silver coins, and the other fifty.'
EXEC add_BibleVerse @BibleId, 342007042, N'When they could not pay, he canceled the debts of both. Now which of them will love him more?”'
EXEC add_BibleVerse @BibleId, 342007043, N'Simon answered, “I suppose the one who had the bigger debt canceled.” Jesus said to him, “You have judged rightly.”'
EXEC add_BibleVerse @BibleId, 342007044, N'Then, turning toward the woman, he said to Simon, “Do you see this woman? I entered your house. You gave me no water for my feet, but she has wet my feet with her tears and wiped them with her hair.'
EXEC add_BibleVerse @BibleId, 342007045, N'You gave me no kiss of greeting, but from the time I entered she has not stopped kissing my feet.'
EXEC add_BibleVerse @BibleId, 342007046, N'You did not anoint my head with oil, but she has anointed my feet with perfumed oil.'
EXEC add_BibleVerse @BibleId, 342007047, N'Therefore I tell you, her sins, which were many, are forgiven, thus she loved much; but the one who is forgiven little loves little.”'
EXEC add_BibleVerse @BibleId, 342007048, N'Then Jesus said to her, “Your sins are forgiven.”'
EXEC add_BibleVerse @BibleId, 342007049, N'But those who were at the table with him began to say among themselves, “Who is this, who even forgives sins?”'
EXEC add_BibleVerse @BibleId, 342007050, N'He said to the woman, “Your faith has saved you; go in peace.”'
EXEC add_BibleVerse @BibleId, 342008001, N'Some time afterward he went on through towns and villages, preaching and proclaiming the good news of the kingdom of God. The twelve were with him,'
EXEC add_BibleVerse @BibleId, 342008002, N'and also some women who had been healed of evil spirits and disabilities: Mary (called Magdalene), from whom seven demons had gone out,'
EXEC add_BibleVerse @BibleId, 342008003, N'and Joanna the wife of Cuza (Herod’s household manager), Susanna, and many others who provided for them out of their own resources.'
EXEC add_BibleVerse @BibleId, 342008004, N'While a large crowd was gathering and people were coming to Jesus from one town after another, he spoke to them in a parable:'
EXEC add_BibleVerse @BibleId, 342008005, N'“A sower went out to sow his seed. And as he sowed, some fell along the path and was trampled on, and the wild birds devoured it.'
EXEC add_BibleVerse @BibleId, 342008006, N'Other seed fell on rock, and when it came up, it withered because it had no moisture.'
EXEC add_BibleVerse @BibleId, 342008007, N'Other seed fell among the thorns, and they grew up with it and choked it.'
EXEC add_BibleVerse @BibleId, 342008008, N'But other seed fell on good soil and grew, and it produced a hundred times as much grain.” As he said this, he called out, “The one who has ears to hear had better listen!”'
EXEC add_BibleVerse @BibleId, 342008009, N'Then his disciples asked him what this parable meant.'
EXEC add_BibleVerse @BibleId, 342008010, N'He said, “You have been given the opportunity to know the secrets of the kingdom of God, but for others they are in parables, so that although they see they may not see, and although they hear they may not understand.'
EXEC add_BibleVerse @BibleId, 342008011, N'“Now the parable means this: The seed is the word of God.'
EXEC add_BibleVerse @BibleId, 342008012, N'Those along the path are the ones who have heard; then the devil comes and takes away the word from their hearts, so that they may not believe and be saved.'
EXEC add_BibleVerse @BibleId, 342008013, N'Those on the rock are the ones who receive the word with joy when they hear it, but they have no root. They believe for a while, but in a time of testing fall away.'
EXEC add_BibleVerse @BibleId, 342008014, N'As for the seed that fell among thorns, these are the ones who hear, but as they go on their way they are choked by the worries and riches and pleasures of life, and their fruit does not mature.'
EXEC add_BibleVerse @BibleId, 342008015, N'But as for the seed that landed on good soil, these are the ones who, after hearing the word, cling to it with an honest and good heart, and bear fruit with steadfast endurance.'
EXEC add_BibleVerse @BibleId, 342008016, N'“No one lights a lamp and then covers it with a jar or puts it under a bed, but puts it on a lampstand so that those who come in can see the light.'
EXEC add_BibleVerse @BibleId, 342008017, N'For nothing is hidden that will not be revealed, and nothing concealed that will not be made known and brought to light.'
EXEC add_BibleVerse @BibleId, 342008018, N'So listen carefully, for whoever has will be given more, but whoever does not have, even what he thinks he has will be taken from him.”'
EXEC add_BibleVerse @BibleId, 342008019, N'Now Jesus’ mother and his brothers came to him, but they could not get near him because of the crowd.'
EXEC add_BibleVerse @BibleId, 342008020, N'So he was told, “Your mother and your brothers are standing outside, wanting to see you.”'
EXEC add_BibleVerse @BibleId, 342008021, N'But he replied to them, “My mother and my brothers are those who hear the word of God and do it.”'
EXEC add_BibleVerse @BibleId, 342008022, N'One day Jesus got into a boat with his disciples and said to them, “Let’s go across to the other side of the lake.” So they set out,'
EXEC add_BibleVerse @BibleId, 342008023, N'and as they sailed he fell asleep. Now a violent windstorm came down on the lake, and the boat started filling up with water, and they were in danger.'
EXEC add_BibleVerse @BibleId, 342008024, N'They came and woke him, saying, “Master, Master, we are about to die!” So he got up and rebuked the wind and the raging waves; they died down, and it was calm.'
EXEC add_BibleVerse @BibleId, 342008025, N'Then he said to them, “Where is your faith?” But they were afraid and amazed, saying to one another, “Who then is this? He commands even the winds and the water, and they obey him!”'
EXEC add_BibleVerse @BibleId, 342008026, N'So they sailed over to the region of the Gerasenes, which is opposite Galilee.'
EXEC add_BibleVerse @BibleId, 342008027, N'As Jesus stepped ashore, a certain man from the town met him who was possessed by demons. For a long time this man had worn no clothes and had not lived in a house, but among the tombs.'
EXEC add_BibleVerse @BibleId, 342008028, N'When he saw Jesus, he cried out, fell down before him, and shouted with a loud voice, “Leave me alone, Jesus, Son of the Most High God! I beg you, do not torment me!”'
EXEC add_BibleVerse @BibleId, 342008029, N'For Jesus had started commanding the evil spirit to come out of the man. (For it had seized him many times, so he would be bound with chains and shackles and kept under guard. But he would break the restraints and be driven by the demon into deserted places.)'
EXEC add_BibleVerse @BibleId, 342008030, N'Jesus then asked him, “What is your name?” He said, “Legion,” because many demons had entered him.'
EXEC add_BibleVerse @BibleId, 342008031, N'And they began to beg him not to order them to depart into the abyss.'
EXEC add_BibleVerse @BibleId, 342008032, N'Now a large herd of pigs was feeding there on the hillside, and the demonic spirits begged Jesus to let them go into them. He gave them permission.'
EXEC add_BibleVerse @BibleId, 342008033, N'So the demons came out of the man and went into the pigs, and the herd of pigs rushed down the steep slope into the lake and drowned.'
EXEC add_BibleVerse @BibleId, 342008034, N'When the herdsmen saw what had happened, they ran off and spread the news in the town and countryside.'
EXEC add_BibleVerse @BibleId, 342008035, N'So the people went out to see what had happened, and they came to Jesus. They found the man from whom the demons had gone out, sitting at Jesus’ feet, clothed and in his right mind, and they were afraid.'
EXEC add_BibleVerse @BibleId, 342008036, N'Those who had seen it told them how the man who had been demon-possessed had been healed.'
EXEC add_BibleVerse @BibleId, 342008037, N'Then all the people of the Gerasenes and the surrounding region asked Jesus to leave them alone, for they were seized with great fear. So he got into the boat and left.'
EXEC add_BibleVerse @BibleId, 342008038, N'The man from whom the demons had gone out begged to go with him, but Jesus sent him away, saying,'
EXEC add_BibleVerse @BibleId, 342008039, N'“Return to your home, and declare what God has done for you.” So he went away, proclaiming throughout the whole town what Jesus had done for him.'
EXEC add_BibleVerse @BibleId, 342008040, N'Now when Jesus returned, the crowd welcomed him, because they were all waiting for him.'
EXEC add_BibleVerse @BibleId, 342008041, N'Then a man named Jairus, who was a ruler of the synagogue, came up. Falling at Jesus’ feet, he pleaded with him to come to his house,'
EXEC add_BibleVerse @BibleId, 342008042, N'because he had an only daughter, about twelve years old, and she was dying. As Jesus was on his way, the crowds pressed around him.'
EXEC add_BibleVerse @BibleId, 342008043, N'Now a woman was there who had been suffering from a hemorrhage for twelve years but could not be healed by anyone.'
EXEC add_BibleVerse @BibleId, 342008044, N'She came up behind Jesus and touched the edge of his cloak, and at once the bleeding stopped.'
EXEC add_BibleVerse @BibleId, 342008045, N'Then Jesus asked, “Who was it who touched me?” When they all denied it, Peter said, “Master, the crowds are surrounding you and pressing against you!”'
EXEC add_BibleVerse @BibleId, 342008046, N'But Jesus said, “Someone touched me, for I know that power has gone out from me.”'
EXEC add_BibleVerse @BibleId, 342008047, N'When the woman saw that she could not escape notice, she came trembling and fell down before him. In the presence of all the people, she explained why she had touched him and how she had been immediately healed.'
EXEC add_BibleVerse @BibleId, 342008048, N'Then he said to her, “Daughter, your faith has made you well. Go in peace.”'
EXEC add_BibleVerse @BibleId, 342008049, N'While he was still speaking, someone from the synagogue ruler’s house came and said, “Your daughter is dead; do not trouble the teacher any longer.”'
EXEC add_BibleVerse @BibleId, 342008050, N'But when Jesus heard this, he told him, “Do not be afraid; just believe, and she will be healed.”'
EXEC add_BibleVerse @BibleId, 342008051, N'Now when he came to the house, Jesus did not let anyone go in with him except Peter, John, and James, and the child’s father and mother.'
EXEC add_BibleVerse @BibleId, 342008052, N'Now they were all wailing and mourning for her, but he said, “Stop your weeping; she is not dead but asleep.”'
EXEC add_BibleVerse @BibleId, 342008053, N'And they began making fun of him, because they knew that she was dead.'
EXEC add_BibleVerse @BibleId, 342008054, N'But Jesus gently took her by the hand and said, “Child, get up.”'
EXEC add_BibleVerse @BibleId, 342008055, N'Her spirit returned, and she got up immediately. Then he told them to give her something to eat.'
EXEC add_BibleVerse @BibleId, 342008056, N'Her parents were astonished, but he ordered them to tell no one what had happened.'
EXEC add_BibleVerse @BibleId, 342009001, N'After Jesus called the twelve together, he gave them power and authority over all demons and to cure diseases,'
EXEC add_BibleVerse @BibleId, 342009002, N'and he sent them out to proclaim the kingdom of God and to heal the sick.'
EXEC add_BibleVerse @BibleId, 342009003, N'He said to them, “Take nothing for your journey – no staff, no bag, no bread, no money, and do not take an extra tunic.'
EXEC add_BibleVerse @BibleId, 342009004, N'Whatever house you enter, stay there until you leave the area.'
EXEC add_BibleVerse @BibleId, 342009005, N'Wherever they do not receive you, as you leave that town, shake the dust off your feet as a testimony against them.”'
EXEC add_BibleVerse @BibleId, 342009006, N'Then they departed and went throughout the villages, proclaiming the good news and healing people everywhere.'
EXEC add_BibleVerse @BibleId, 342009007, N'Now Herod the tetrarch heard about everything that was happening, and he was thoroughly perplexed, because some people were saying that John had been raised from the dead,'
EXEC add_BibleVerse @BibleId, 342009008, N'while others were saying that Elijah had appeared, and still others that one of the prophets of long ago had risen.'
EXEC add_BibleVerse @BibleId, 342009009, N'Herod said, “I had John beheaded, but who is this about whom I hear such things?” So Herod wanted to learn about Jesus.'
EXEC add_BibleVerse @BibleId, 342009010, N'When the apostles returned, they told Jesus everything they had done. Then he took them with him and they withdrew privately to a town called Bethsaida.'
EXEC add_BibleVerse @BibleId, 342009011, N'But when the crowds found out, they followed him. He welcomed them, spoke to them about the kingdom of God, and cured those who needed healing.'
EXEC add_BibleVerse @BibleId, 342009012, N'Now the day began to draw to a close, so the twelve came and said to Jesus, “Send the crowd away, so they can go into the surrounding villages and countryside and find lodging and food, because we are in an isolated place.”'
EXEC add_BibleVerse @BibleId, 342009013, N'But he said to them, “You give them something to eat.” They replied, “We have no more than five loaves and two fish – unless we go and buy food for all these people.”'
EXEC add_BibleVerse @BibleId, 342009014, N'(Now about five thousand men were there.) Then he said to his disciples, “Have them sit down in groups of about fifty each.”'
EXEC add_BibleVerse @BibleId, 342009015, N'So they did as Jesus directed, and the people all sat down.'
EXEC add_BibleVerse @BibleId, 342009016, N'Then he took the five loaves and the two fish, and looking up to heaven he gave thanks and broke them. He gave them to the disciples to set before the crowd.'
EXEC add_BibleVerse @BibleId, 342009017, N'They all ate and were satisfied, and what was left over was picked up – twelve baskets of broken pieces.'
EXEC add_BibleVerse @BibleId, 342009018, N'Once when Jesus was praying by himself, and his disciples were nearby, he asked them, “Who do the crowds say that I am?”'
EXEC add_BibleVerse @BibleId, 342009019, N'They answered, “John the Baptist; others say Elijah; and still others that one of the prophets of long ago has risen.”'
EXEC add_BibleVerse @BibleId, 342009020, N'Then he said to them, “But who do you say that I am?” Peter answered, “The Christ of God.”'
EXEC add_BibleVerse @BibleId, 342009021, N'But he forcefully commanded them not to tell this to anyone,'
EXEC add_BibleVerse @BibleId, 342009022, N'saying, “The Son of Man must suffer many things and be rejected by the elders, chief priests, and experts in the law, and be killed, and on the third day be raised.”'
EXEC add_BibleVerse @BibleId, 342009023, N'Then he said to them all, “If anyone wants to become my follower, he must deny himself, take up his cross daily, and follow me.'
EXEC add_BibleVerse @BibleId, 342009024, N'For whoever wants to save his life will lose it, but whoever loses his life for my sake will save it.'
EXEC add_BibleVerse @BibleId, 342009025, N'For what does it benefit a person if he gains the whole world but loses or forfeits himself?'
EXEC add_BibleVerse @BibleId, 342009026, N'For whoever is ashamed of me and my words, the Son of Man will be ashamed of that person when he comes in his glory and in the glory of the Father and of the holy angels.'
EXEC add_BibleVerse @BibleId, 342009027, N'But I tell you most certainly, there are some standing here who will not experience death before they see the kingdom of God.”'
EXEC add_BibleVerse @BibleId, 342009028, N'Now about eight days after these sayings, Jesus took with him Peter, John, and James, and went up the mountain to pray.'
EXEC add_BibleVerse @BibleId, 342009029, N'As he was praying, the appearance of his face was transformed, and his clothes became very bright, a brilliant white.'
EXEC add_BibleVerse @BibleId, 342009030, N'Then two men, Moses and Elijah, began talking with him.'
EXEC add_BibleVerse @BibleId, 342009031, N'They appeared in glorious splendor and spoke about his departure that he was about to carry out at Jerusalem.'
EXEC add_BibleVerse @BibleId, 342009032, N'Now Peter and those with him were quite sleepy, but as they became fully awake, they saw his glory and the two men standing with him.'
EXEC add_BibleVerse @BibleId, 342009033, N'Then as the men were starting to leave, Peter said to Jesus, “Master, it is good for us to be here. Let us make three shelters, one for you and one for Moses and one for Elijah” – not knowing what he was saying.'
EXEC add_BibleVerse @BibleId, 342009034, N'As he was saying this, a cloud came and overshadowed them, and they were afraid as they entered the cloud.'
EXEC add_BibleVerse @BibleId, 342009035, N'Then a voice came from the cloud, saying, “This is my Son, my Chosen One. Listen to him!”'
EXEC add_BibleVerse @BibleId, 342009036, N'After the voice had spoken, Jesus was found alone. So they kept silent and told no one at that time anything of what they had seen.'
EXEC add_BibleVerse @BibleId, 342009037, N'Now on the next day, when they had come down from the mountain, a large crowd met him.'
EXEC add_BibleVerse @BibleId, 342009038, N'Then a man from the crowd cried out, “Teacher, I beg you to look at my son – he is my only child!'
EXEC add_BibleVerse @BibleId, 342009039, N'A spirit seizes him, and he suddenly screams; it throws him into convulsions and causes him to foam at the mouth. It hardly ever leaves him alone, torturing him severely.'
EXEC add_BibleVerse @BibleId, 342009040, N'I begged your disciples to cast it out, but they could not do so.”'
EXEC add_BibleVerse @BibleId, 342009041, N'Jesus answered, “You unbelieving and perverse generation! How much longer must I be with you and endure you? Bring your son here.”'
EXEC add_BibleVerse @BibleId, 342009042, N'As the boy was approaching, the demon threw him to the ground and shook him with convulsions. But Jesus rebuked the unclean spirit, healed the boy, and gave him back to his father.'
EXEC add_BibleVerse @BibleId, 342009043, N'Then they were all astonished at the mighty power of God. But while the entire crowd was amazed at everything Jesus was doing, he said to his disciples,'
EXEC add_BibleVerse @BibleId, 342009044, N'“Take these words to heart, for the Son of Man is going to be betrayed into the hands of men.”'
EXEC add_BibleVerse @BibleId, 342009045, N'But they did not understand this statement; its meaning had been concealed from them, so that they could not grasp it. Yet they were afraid to ask him about this statement.'
EXEC add_BibleVerse @BibleId, 342009046, N'Now an argument started among the disciples as to which of them might be the greatest.'
EXEC add_BibleVerse @BibleId, 342009047, N'But when Jesus discerned their innermost thoughts, he took a child, had him stand by his side,'
EXEC add_BibleVerse @BibleId, 342009048, N'and said to them, “Whoever welcomes this child in my name welcomes me, and whoever welcomes me welcomes the one who sent me, for the one who is least among you all is the one who is great.”'
EXEC add_BibleVerse @BibleId, 342009049, N'John answered, “Master, we saw someone casting out demons in your name, and we tried to stop him because he is not a disciple along with us.”'
EXEC add_BibleVerse @BibleId, 342009050, N'But Jesus said to him, “Do not stop him, for whoever is not against you is for you.”'
EXEC add_BibleVerse @BibleId, 342009051, N'Now when the days drew near for him to be taken up, Jesus set out resolutely to go to Jerusalem.'
EXEC add_BibleVerse @BibleId, 342009052, N'He sent messengers on ahead of him. As they went along, they entered a Samaritan village to make things ready in advance for him,'
EXEC add_BibleVerse @BibleId, 342009053, N'but the villagers refused to welcome him, because he was determined to go to Jerusalem.'
EXEC add_BibleVerse @BibleId, 342009054, N'Now when his disciples James and John saw this, they said, “Lord, do you want us to call fire to come down from heaven and consume them?”'
EXEC add_BibleVerse @BibleId, 342009055, N'But Jesus turned and rebuked them,'
EXEC add_BibleVerse @BibleId, 342009056, N'and they went on to another village.'
EXEC add_BibleVerse @BibleId, 342009057, N'As they were walking along the road, someone said to him, “I will follow you wherever you go.”'
EXEC add_BibleVerse @BibleId, 342009058, N'Jesus said to him, “Foxes have dens and the birds in the sky have nests, but the Son of Man has no place to lay his head.”'
EXEC add_BibleVerse @BibleId, 342009059, N'Jesus said to another, “Follow me.” But he replied, “Lord, first let me go and bury my father.”'
EXEC add_BibleVerse @BibleId, 342009060, N'But Jesus said to him, “Let the dead bury their own dead, but as for you, go and proclaim the kingdom of God.”'
EXEC add_BibleVerse @BibleId, 342009061, N'Yet another said, “I will follow you, Lord, but first let me say goodbye to my family.”'
EXEC add_BibleVerse @BibleId, 342009062, N'Jesus said to him, “No one who puts his hand to the plow and looks back is fit for the kingdom of God.”'
EXEC add_BibleVerse @BibleId, 342010001, N'After this the Lord appointed seventy-two others and sent them on ahead of him two by two into every town and place where he himself was about to go.'
EXEC add_BibleVerse @BibleId, 342010002, N'He said to them, “The harvest is plentiful, but the workers are few. Therefore ask the Lord of the harvest to send out workers into his harvest.'
EXEC add_BibleVerse @BibleId, 342010003, N'Go! I am sending you out like lambs surrounded by wolves.'
EXEC add_BibleVerse @BibleId, 342010004, N'Do not carry a money bag, a traveler’s bag, or sandals, and greet no one on the road.'
EXEC add_BibleVerse @BibleId, 342010005, N'Whenever you enter a house, first say, ‘May peace be on this house!’'
EXEC add_BibleVerse @BibleId, 342010006, N'And if a peace-loving person is there, your peace will remain on him, but if not, it will return to you.'
EXEC add_BibleVerse @BibleId, 342010007, N'Stay in that same house, eating and drinking what they give you, for the worker deserves his pay. Do not move around from house to house.'
EXEC add_BibleVerse @BibleId, 342010008, N'Whenever you enter a town and the people welcome you, eat what is set before you.'
EXEC add_BibleVerse @BibleId, 342010009, N'Heal the sick in that town and say to them, ‘The kingdom of God has come upon you!’'
EXEC add_BibleVerse @BibleId, 342010010, N'But whenever you enter a town and the people do not welcome you, go into its streets and say,'
EXEC add_BibleVerse @BibleId, 342010011, N'‘Even the dust of your town that clings to our feet we wipe off against you. Nevertheless know this: The kingdom of God has come.’'
EXEC add_BibleVerse @BibleId, 342010012, N'I tell you, it will be more bearable on that day for Sodom than for that town!'
EXEC add_BibleVerse @BibleId, 342010013, N'“Woe to you, Chorazin! Woe to you, Bethsaida! For if the miracles done in you had been done in Tyre they would have repented long ago, sitting in sackcloth and ashes.'
EXEC add_BibleVerse @BibleId, 342010014, N'But it will be more bearable for Tyre and Sidon in the judgment than for you!'
EXEC add_BibleVerse @BibleId, 342010015, N'And you, Capernaum, will you be exalted to heaven? No, you will be thrown down to Hades!'
EXEC add_BibleVerse @BibleId, 342010016, N'“The one who listens to you listens to me, and the one who rejects you rejects me, and the one who rejects me rejects the one who sent me.”'
EXEC add_BibleVerse @BibleId, 342010017, N'Then the seventy-two returned with joy, saying, “Lord, even the demons submit to us in your name!”'
EXEC add_BibleVerse @BibleId, 342010018, N'So he said to them, “I saw Satan fall like lightning from heaven.'
EXEC add_BibleVerse @BibleId, 342010019, N'Look, I have given you authority to tread on snakes and scorpions and on the full force of the enemy, and nothing will hurt you.'
EXEC add_BibleVerse @BibleId, 342010020, N'Nevertheless, do not rejoice that the spirits submit to you, but rejoice that your names stand written in heaven.”'
EXEC add_BibleVerse @BibleId, 342010021, N'On that same occasion Jesus rejoiced in the Holy Spirit and said, “I praise you, Father, Lord of heaven and earth, because you have hidden these things from the wise and intelligent, and revealed them to little children. Yes, Father, for this was your gracious will.'
EXEC add_BibleVerse @BibleId, 342010022, N'All things have been given to me by my Father. No one knows who the Son is except the Father, or who the Father is except the Son and anyone to whom the Son decides to reveal him.”'
EXEC add_BibleVerse @BibleId, 342010023, N'Then Jesus turned to his disciples and said privately, “Blessed are the eyes that see what you see!'
EXEC add_BibleVerse @BibleId, 342010024, N'For I tell you that many prophets and kings longed to see what you see but did not see it, and to hear what you hear but did not hear it.”'
EXEC add_BibleVerse @BibleId, 342010025, N'Now an expert in religious law stood up to test Jesus, saying, “Teacher, what must I do to inherit eternal life?”'
EXEC add_BibleVerse @BibleId, 342010026, N'He said to him, “What is written in the law? How do you understand it?”'
EXEC add_BibleVerse @BibleId, 342010027, N'The expert answered, “ Love the Lord your God with all your heart, with all your soul, with all your strength, and with all your mind, and love your neighbor as yourself.”'
EXEC add_BibleVerse @BibleId, 342010028, N'Jesus said to him, “You have answered correctly; do this, and you will live.”'
EXEC add_BibleVerse @BibleId, 342010029, N'But the expert, wanting to justify himself, said to Jesus, “And who is my neighbor?”'
EXEC add_BibleVerse @BibleId, 342010030, N'Jesus replied, “A man was going down from Jerusalem and fell into the hands of robbers, who stripped him, beat him up, and went off, leaving him half dead.'
EXEC add_BibleVerse @BibleId, 342010031, N'Now by chance a priest was going down that road, but when he saw the injured man he passed by on the other side.'
EXEC add_BibleVerse @BibleId, 342010032, N'So too a Levite, when he came up to the place and saw him, passed by on the other side.'
EXEC add_BibleVerse @BibleId, 342010033, N'But a Samaritan who was traveling came to where the injured man was, and when he saw him, he felt compassion for him.'
EXEC add_BibleVerse @BibleId, 342010034, N'He went up to him and bandaged his wounds, pouring oil and wine on them. Then he put him on his own animal, brought him to an inn, and took care of him.'
EXEC add_BibleVerse @BibleId, 342010035, N'The next day he took out two silver coins and gave them to the innkeeper, saying, ‘Take care of him, and whatever else you spend, I will repay you when I come back this way.’'
EXEC add_BibleVerse @BibleId, 342010036, N'Which of these three do you think became a neighbor to the man who fell into the hands of the robbers?”'
EXEC add_BibleVerse @BibleId, 342010037, N'The expert in religious law said, “The one who showed mercy to him.” So Jesus said to him, “Go and do the same.”'
EXEC add_BibleVerse @BibleId, 342010038, N'Now as they went on their way, Jesus entered a certain village where a woman named Martha welcomed him as a guest.'
EXEC add_BibleVerse @BibleId, 342010039, N'She had a sister named Mary, who sat at the Lord’s feet and listened to what he said.'
EXEC add_BibleVerse @BibleId, 342010040, N'But Martha was distracted with all the preparations she had to make, so she came up to him and said, “Lord, don’t you care that my sister has left me to do all the work alone? Tell her to help me.”'
EXEC add_BibleVerse @BibleId, 342010041, N'But the Lord answered her, “Martha, Martha, you are worried and troubled about many things,'
EXEC add_BibleVerse @BibleId, 342010042, N'but one thing is needed. Mary has chosen the best part; it will not be taken away from her.”'
EXEC add_BibleVerse @BibleId, 342011001, N'Now Jesus was praying in a certain place. When he stopped, one of his disciples said to him, “Lord, teach us to pray, just as John taught his disciples.”'
EXEC add_BibleVerse @BibleId, 342011002, N'So he said to them, “When you pray, say: Father, may your name be honored; may your kingdom come.'
EXEC add_BibleVerse @BibleId, 342011003, N'Give us each day our daily bread,'
EXEC add_BibleVerse @BibleId, 342011004, N'and forgive us our sins, for we also forgive everyone who sins against us. And do not lead us into temptation.”'
EXEC add_BibleVerse @BibleId, 342011005, N'Then he said to them, “Suppose one of you has a friend, and you go to him at midnight and say to him, ‘Friend, lend me three loaves of bread,'
EXEC add_BibleVerse @BibleId, 342011006, N'because a friend of mine has stopped here while on a journey, and I have nothing to set before him.’'
EXEC add_BibleVerse @BibleId, 342011007, N'Then he will reply from inside, ‘Do not bother me. The door is already shut, and my children and I are in bed. I cannot get up and give you anything.’'
EXEC add_BibleVerse @BibleId, 342011008, N'I tell you, even though the man inside will not get up and give him anything because he is his friend, yet because of the first man’s sheer persistence he will get up and give him whatever he needs.'
EXEC add_BibleVerse @BibleId, 342011009, N'“So I tell you: Ask, and it will be given to you; seek, and you will find; knock, and the door will be opened for you.'
EXEC add_BibleVerse @BibleId, 342011010, N'For everyone who asks receives, and the one who seeks finds, and to the one who knocks, the door will be opened.'
EXEC add_BibleVerse @BibleId, 342011011, N'What father among you, if your son asks for a fish, will give him a snake instead of a fish?'
EXEC add_BibleVerse @BibleId, 342011012, N'Or if he asks for an egg, will give him a scorpion?'
EXEC add_BibleVerse @BibleId, 342011013, N'If you then, although you are evil, know how to give good gifts to your children, how much more will the heavenly Father give the Holy Spirit to those who ask him!”'
EXEC add_BibleVerse @BibleId, 342011014, N'Now he was casting out a demon that was mute. When the demon had gone out, the man who had been mute began to speak, and the crowds were amazed.'
EXEC add_BibleVerse @BibleId, 342011015, N'But some of them said, “By the power of Beelzebul, the ruler of demons, he casts out demons.”'
EXEC add_BibleVerse @BibleId, 342011016, N'Others, to test him, began asking for a sign from heaven.'
EXEC add_BibleVerse @BibleId, 342011017, N'But Jesus, realizing their thoughts, said to them, “Every kingdom divided against itself is destroyed, and a divided household falls.'
EXEC add_BibleVerse @BibleId, 342011018, N'So if Satan too is divided against himself, how will his kingdom stand? I ask you this because you claim that I cast out demons by Beelzebul.'
EXEC add_BibleVerse @BibleId, 342011019, N'Now if I cast out demons by Beelzebul, by whom do your sons cast them out? Therefore they will be your judges.'
EXEC add_BibleVerse @BibleId, 342011020, N'But if I cast out demons by the finger of God, then the kingdom of God has already overtaken you.'
EXEC add_BibleVerse @BibleId, 342011021, N'When a strong man, fully armed, guards his own palace, his possessions are safe.'
EXEC add_BibleVerse @BibleId, 342011022, N'But when a stronger man attacks and conquers him, he takes away the first man’s armor on which the man relied and divides up his plunder.'
EXEC add_BibleVerse @BibleId, 342011023, N'Whoever is not with me is against me, and whoever does not gather with me scatters.'
EXEC add_BibleVerse @BibleId, 342011024, N'“When an unclean spirit goes out of a person, it passes through waterless places looking for rest but not finding any. Then it says, ‘I will return to the home I left.’'
EXEC add_BibleVerse @BibleId, 342011025, N'When it returns, it finds the house swept clean and put in order.'
EXEC add_BibleVerse @BibleId, 342011026, N'Then it goes and brings seven other spirits more evil than itself, and they go in and live there, so the last state of that person is worse than the first.”'
EXEC add_BibleVerse @BibleId, 342011027, N'As he said these things, a woman in the crowd spoke out to him, “Blessed is the womb that bore you and the breasts at which you nursed!”'
EXEC add_BibleVerse @BibleId, 342011028, N'But he replied, “Blessed rather are those who hear the word of God and obey it!”'
EXEC add_BibleVerse @BibleId, 342011029, N'As the crowds were increasing, Jesus began to say, “This generation is a wicked generation; it looks for a sign, but no sign will be given to it except the sign of Jonah.'
EXEC add_BibleVerse @BibleId, 342011030, N'For just as Jonah became a sign to the people of Nineveh, so the Son of Man will be a sign to this generation.'
EXEC add_BibleVerse @BibleId, 342011031, N'The queen of the South will rise up at the judgment with the people of this generation and condemn them, because she came from the ends of the earth to hear the wisdom of Solomon – and now, something greater than Solomon is here!'
EXEC add_BibleVerse @BibleId, 342011032, N'The people of Nineveh will stand up at the judgment with this generation and condemn it, because they repented when Jonah preached to them – and now, something greater than Jonah is here!'
EXEC add_BibleVerse @BibleId, 342011033, N'“No one after lighting a lamp puts it in a hidden place or under a basket, but on a lampstand, so that those who come in can see the light.'
EXEC add_BibleVerse @BibleId, 342011034, N'Your eye is the lamp of your body. When your eye is healthy, your whole body is full of light, but when it is diseased, your body is full of darkness.'
EXEC add_BibleVerse @BibleId, 342011035, N'Therefore see to it that the light in you is not darkness.'
EXEC add_BibleVerse @BibleId, 342011036, N'If then your whole body is full of light, with no part in the dark, it will be as full of light as when the light of a lamp shines on you.”'
EXEC add_BibleVerse @BibleId, 342011037, N'As he spoke, a Pharisee invited Jesus to have a meal with him, so he went in and took his place at the table.'
EXEC add_BibleVerse @BibleId, 342011038, N'The Pharisee was astonished when he saw that Jesus did not first wash his hands before the meal.'
EXEC add_BibleVerse @BibleId, 342011039, N'But the Lord said to him, “Now you Pharisees clean the outside of the cup and the plate, but inside you are full of greed and wickedness.'
EXEC add_BibleVerse @BibleId, 342011040, N'You fools! Didn’t the one who made the outside make the inside as well?'
EXEC add_BibleVerse @BibleId, 342011041, N'But give from your heart to those in need, and then everything will be clean for you.'
EXEC add_BibleVerse @BibleId, 342011042, N'“But woe to you Pharisees! You give a tenth of your mint, rue, and every herb, yet you neglect justice and love for God! But you should have done these things without neglecting the others.'
EXEC add_BibleVerse @BibleId, 342011043, N'Woe to you Pharisees! You love the best seats in the synagogues and elaborate greetings in the marketplaces!'
EXEC add_BibleVerse @BibleId, 342011044, N'Woe to you! You are like unmarked graves, and people walk over them without realizing it!”'
EXEC add_BibleVerse @BibleId, 342011045, N'One of the experts in religious law answered him, “Teacher, when you say these things you insult us too.”'
EXEC add_BibleVerse @BibleId, 342011046, N'But Jesus replied, “Woe to you experts in religious law as well! You load people down with burdens difficult to bear, yet you yourselves refuse to touch the burdens with even one of your fingers!'
EXEC add_BibleVerse @BibleId, 342011047, N'Woe to you! You build the tombs of the prophets whom your ancestors killed.'
EXEC add_BibleVerse @BibleId, 342011048, N'So you testify that you approve of the deeds of your ancestors, because they killed the prophets and you build their tombs!'
EXEC add_BibleVerse @BibleId, 342011049, N'For this reason also the wisdom of God said, ‘I will send them prophets and apostles, some of whom they will kill and persecute,’'
EXEC add_BibleVerse @BibleId, 342011050, N'so that this generation may be held accountable for the blood of all the prophets that has been shed since the beginning of the world,'
EXEC add_BibleVerse @BibleId, 342011051, N'from the blood of Abel to the blood of Zechariah, who was killed between the altar and the sanctuary. Yes, I tell you, it will be charged against this generation.'
EXEC add_BibleVerse @BibleId, 342011052, N'Woe to you experts in religious law! You have taken away the key to knowledge! You did not go in yourselves, and you hindered those who were going in.”'
EXEC add_BibleVerse @BibleId, 342011053, N'When he went out from there, the experts in the law and the Pharisees began to oppose him bitterly, and to ask him hostile questions about many things,'
EXEC add_BibleVerse @BibleId, 342011054, N'plotting against him, to catch him in something he might say.'
EXEC add_BibleVerse @BibleId, 342012001, N'Meanwhile, when many thousands of the crowd had gathered so that they were trampling on one another, Jesus began to speak first to his disciples, “Be on your guard against the yeast of the Pharisees, which is hypocrisy.'
EXEC add_BibleVerse @BibleId, 342012002, N'Nothing is hidden that will not be revealed, and nothing is secret that will not be made known.'
EXEC add_BibleVerse @BibleId, 342012003, N'So then whatever you have said in the dark will be heard in the light, and what you have whispered in private rooms will be proclaimed from the housetops.'
EXEC add_BibleVerse @BibleId, 342012004, N'“I tell you, my friends, do not be afraid of those who kill the body, and after that have nothing more they can do.'
EXEC add_BibleVerse @BibleId, 342012005, N'But I will warn you whom you should fear: Fear the one who, after the killing, has authority to throw you into hell. Yes, I tell you, fear him!'
EXEC add_BibleVerse @BibleId, 342012006, N'Aren’t five sparrows sold for two pennies? Yet not one of them is forgotten before God.'
EXEC add_BibleVerse @BibleId, 342012007, N'In fact, even the hairs on your head are all numbered. Do not be afraid; you are more valuable than many sparrows.'
EXEC add_BibleVerse @BibleId, 342012008, N'“I tell you, whoever acknowledges me before men, the Son of Man will also acknowledge before God’s angels.'
EXEC add_BibleVerse @BibleId, 342012009, N'But the one who denies me before men will be denied before God’s angels.'
EXEC add_BibleVerse @BibleId, 342012010, N'And everyone who speaks a word against the Son of Man will be forgiven, but the person who blasphemes against the Holy Spirit will not be forgiven.'
EXEC add_BibleVerse @BibleId, 342012011, N'But when they bring you before the synagogues, the rulers, and the authorities, do not worry about how you should make your defense or what you should say,'
EXEC add_BibleVerse @BibleId, 342012012, N'for the Holy Spirit will teach you at that moment what you must say.”'
EXEC add_BibleVerse @BibleId, 342012013, N'Then someone from the crowd said to him, “Teacher, tell my brother to divide the inheritance with me.”'
EXEC add_BibleVerse @BibleId, 342012014, N'But Jesus said to him, “Man, who made me a judge or arbitrator between you two?”'
EXEC add_BibleVerse @BibleId, 342012015, N'Then he said to them, “Watch out and guard yourself from all types of greed, because one’s life does not consist in the abundance of his possessions.”'
EXEC add_BibleVerse @BibleId, 342012016, N'He then told them a parable: “The land of a certain rich man produced an abundant crop,'
EXEC add_BibleVerse @BibleId, 342012017, N'so he thought to himself, ‘What should I do, for I have nowhere to store my crops?’'
EXEC add_BibleVerse @BibleId, 342012018, N'Then he said, ‘I will do this: I will tear down my barns and build bigger ones, and there I will store all my grain and my goods.'
EXEC add_BibleVerse @BibleId, 342012019, N'And I will say to myself, “You have plenty of goods stored up for many years; relax, eat, drink, celebrate!”’'
EXEC add_BibleVerse @BibleId, 342012020, N'But God said to him, ‘You fool! This very night your life will be demanded back from you, but who will get what you have prepared for yourself?’'
EXEC add_BibleVerse @BibleId, 342012021, N'So it is with the one who stores up riches for himself, but is not rich toward God.”'
EXEC add_BibleVerse @BibleId, 342012022, N'Then Jesus said to his disciples, “Therefore I tell you, do not worry about your life, what you will eat, or about your body, what you will wear.'
EXEC add_BibleVerse @BibleId, 342012023, N'For there is more to life than food, and more to the body than clothing.'
EXEC add_BibleVerse @BibleId, 342012024, N'Consider the ravens: They do not sow or reap, they have no storeroom or barn, yet God feeds them. How much more valuable are you than the birds!'
EXEC add_BibleVerse @BibleId, 342012025, N'And which of you by worrying can add an hour to his life?'
EXEC add_BibleVerse @BibleId, 342012026, N'So if you cannot do such a very little thing as this, why do you worry about the rest?'
EXEC add_BibleVerse @BibleId, 342012027, N'Consider how the flowers grow; they do not work or spin. Yet I tell you, not even Solomon in all his glory was clothed like one of these!'
EXEC add_BibleVerse @BibleId, 342012028, N'And if this is how God clothes the wild grass, which is here today and tomorrow is tossed into the fire to heat the oven, how much more will he clothe you, you people of little faith!'
EXEC add_BibleVerse @BibleId, 342012029, N'So do not be overly concerned about what you will eat and what you will drink, and do not worry about such things.'
EXEC add_BibleVerse @BibleId, 342012030, N'For all the nations of the world pursue these things, and your Father knows that you need them.'
EXEC add_BibleVerse @BibleId, 342012031, N'Instead, pursue his kingdom, and these things will be given to you as well.'
EXEC add_BibleVerse @BibleId, 342012032, N'“Do not be afraid, little flock, for your Father is well pleased to give you the kingdom.'
EXEC add_BibleVerse @BibleId, 342012033, N'Sell your possessions and give to the poor. Provide yourselves purses that do not wear out – a treasure in heaven that never decreases, where no thief approaches and no moth destroys.'
EXEC add_BibleVerse @BibleId, 342012034, N'For where your treasure is, there your heart will be also.'
EXEC add_BibleVerse @BibleId, 342012035, N'“Get dressed for service and keep your lamps burning;'
EXEC add_BibleVerse @BibleId, 342012036, N'be like people waiting for their master to come back from the wedding celebration, so that when he comes and knocks they can immediately open the door for him.'
EXEC add_BibleVerse @BibleId, 342012037, N'Blessed are those slaves whom their master finds alert when he returns! I tell you the truth, he will dress himself to serve, have them take their place at the table, and will come and wait on them!'
EXEC add_BibleVerse @BibleId, 342012038, N'Even if he comes in the second or third watch of the night and finds them alert, blessed are those slaves!'
EXEC add_BibleVerse @BibleId, 342012039, N'But understand this: If the owner of the house had known at what hour the thief was coming, he would not have let his house be broken into.'
EXEC add_BibleVerse @BibleId, 342012040, N'You also must be ready, because the Son of Man will come at an hour when you do not expect him.”'
EXEC add_BibleVerse @BibleId, 342012041, N'Then Peter said, “Lord, are you telling this parable for us or for everyone?”'
EXEC add_BibleVerse @BibleId, 342012042, N'The Lord replied, “Who then is the faithful and wise manager, whom the master puts in charge of his household servants, to give them their allowance of food at the proper time?'
EXEC add_BibleVerse @BibleId, 342012043, N'Blessed is that slave whom his master finds at work when he returns.'
EXEC add_BibleVerse @BibleId, 342012044, N'I tell you the truth, the master will put him in charge of all his possessions.'
EXEC add_BibleVerse @BibleId, 342012045, N'But if that slave should say to himself, ‘My master is delayed in returning,’ and he begins to beat the other slaves, both men and women, and to eat, drink, and get drunk,'
EXEC add_BibleVerse @BibleId, 342012046, N'then the master of that slave will come on a day when he does not expect him and at an hour he does not foresee, and will cut him in two, and assign him a place with the unfaithful.'
EXEC add_BibleVerse @BibleId, 342012047, N'That servant who knew his master’s will but did not get ready or do what his master asked will receive a severe beating.'
EXEC add_BibleVerse @BibleId, 342012048, N'But the one who did not know his master’s will and did things worthy of punishment will receive a light beating. From everyone who has been given much, much will be required, and from the one who has been entrusted with much, even more will be asked.'
EXEC add_BibleVerse @BibleId, 342012049, N'“I have come to bring fire on the earth – and how I wish it were already kindled!'
EXEC add_BibleVerse @BibleId, 342012050, N'I have a baptism to undergo, and how distressed I am until it is finished!'
EXEC add_BibleVerse @BibleId, 342012051, N'Do you think I have come to bring peace on earth? No, I tell you, but rather division!'
EXEC add_BibleVerse @BibleId, 342012052, N'For from now on there will be five in one household divided, three against two and two against three.'
EXEC add_BibleVerse @BibleId, 342012053, N'They will be divided, father against son and son against father, mother against daughter and daughter against mother, mother-in-law against her daughter-in-law and daughter-in-law against mother-in-law.”'
EXEC add_BibleVerse @BibleId, 342012054, N'Jesus also said to the crowds, “When you see a cloud rising in the west, you say at once, ‘A rainstorm is coming,’ and it does.'
EXEC add_BibleVerse @BibleId, 342012055, N'And when you see the south wind blowing, you say, ‘There will be scorching heat,’ and there is.'
EXEC add_BibleVerse @BibleId, 342012056, N'You hypocrites! You know how to interpret the appearance of the earth and the sky, but how can you not know how to interpret the present time?'
EXEC add_BibleVerse @BibleId, 342012057, N'“And why don’t you judge for yourselves what is right?'
EXEC add_BibleVerse @BibleId, 342012058, N'As you are going with your accuser before the magistrate, make an effort to settle with him on the way, so that he will not drag you before the judge, and the judge hand you over to the officer, and the officer throw you into prison.'
EXEC add_BibleVerse @BibleId, 342012059, N'I tell you, you will never get out of there until you have paid the very last cent!”'
EXEC add_BibleVerse @BibleId, 342013001, N'Now there were some present on that occasion who told him about the Galileans whose blood Pilate had mixed with their sacrifices.'
EXEC add_BibleVerse @BibleId, 342013002, N'He answered them, “Do you think these Galileans were worse sinners than all the other Galileans, because they suffered these things?'
EXEC add_BibleVerse @BibleId, 342013003, N'No, I tell you! But unless you repent, you will all perish as well!'
EXEC add_BibleVerse @BibleId, 342013004, N'Or those eighteen who were killed when the tower in Siloam fell on them, do you think they were worse offenders than all the others who live in Jerusalem?'
EXEC add_BibleVerse @BibleId, 342013005, N'No, I tell you! But unless you repent you will all perish as well!”'
EXEC add_BibleVerse @BibleId, 342013006, N'Then Jesus told this parable: “A man had a fig tree planted in his vineyard, and he came looking for fruit on it and found none.'
EXEC add_BibleVerse @BibleId, 342013007, N'So he said to the worker who tended the vineyard, ‘For three years now, I have come looking for fruit on this fig tree, and each time I inspect it I find none. Cut it down! Why should it continue to deplete the soil?’'
EXEC add_BibleVerse @BibleId, 342013008, N'But the worker answered him, ‘Sir, leave it alone this year too, until I dig around it and put fertilizer on it.'
EXEC add_BibleVerse @BibleId, 342013009, N'Then if it bears fruit next year, very well, but if not, you can cut it down.’”'
EXEC add_BibleVerse @BibleId, 342013010, N'Now he was teaching in one of the synagogues on the Sabbath,'
EXEC add_BibleVerse @BibleId, 342013011, N'and a woman was there who had been disabled by a spirit for eighteen years. She was bent over and could not straighten herself up completely.'
EXEC add_BibleVerse @BibleId, 342013012, N'When Jesus saw her, he called her to him and said, “Woman, you are freed from your infirmity.”'
EXEC add_BibleVerse @BibleId, 342013013, N'Then he placed his hands on her, and immediately she straightened up and praised God.'
EXEC add_BibleVerse @BibleId, 342013014, N'But the president of the synagogue, indignant because Jesus had healed on the Sabbath, said to the crowd, “There are six days on which work should be done! So come and be healed on those days, and not on the Sabbath day.”'
EXEC add_BibleVerse @BibleId, 342013015, N'Then the Lord answered him, “You hypocrites! Does not each of you on the Sabbath untie his ox or his donkey from its stall, and lead it to water?'
EXEC add_BibleVerse @BibleId, 342013016, N'Then shouldn’t this woman, a daughter of Abraham whom Satan bound for eighteen long years, be released from this imprisonment on the Sabbath day?”'
EXEC add_BibleVerse @BibleId, 342013017, N'When he said this all his adversaries were humiliated, but the entire crowd was rejoicing at all the wonderful things he was doing.'
EXEC add_BibleVerse @BibleId, 342013018, N'Thus Jesus asked, “What is the kingdom of God like? To what should I compare it?'
EXEC add_BibleVerse @BibleId, 342013019, N'It is like a mustard seed that a man took and sowed in his garden. It grew and became a tree, and the wild birds nested in its branches.”'
EXEC add_BibleVerse @BibleId, 342013020, N'Again he said, “To what should I compare the kingdom of God?'
EXEC add_BibleVerse @BibleId, 342013021, N'It is like yeast that a woman took and mixed with three measures of flour until all the dough had risen.”'
EXEC add_BibleVerse @BibleId, 342013022, N'Then Jesus traveled throughout towns and villages, teaching and making his way toward Jerusalem.'
EXEC add_BibleVerse @BibleId, 342013023, N'Someone asked him, “Lord, will only a few be saved?” So he said to them,'
EXEC add_BibleVerse @BibleId, 342013024, N'“Exert every effort to enter through the narrow door, because many, I tell you, will try to enter and will not be able to.'
EXEC add_BibleVerse @BibleId, 342013025, N'Once the head of the house gets up and shuts the door, then you will stand outside and start to knock on the door and beg him, ‘Lord, let us in!’ But he will answer you, ‘I don’t know where you come from.’'
EXEC add_BibleVerse @BibleId, 342013026, N'Then you will begin to say, ‘We ate and drank in your presence, and you taught in our streets.’'
EXEC add_BibleVerse @BibleId, 342013027, N'But he will reply, ‘I don’t know where you come from! Go away from me, all you evildoers!’'
EXEC add_BibleVerse @BibleId, 342013028, N'There will be weeping and gnashing of teeth when you see Abraham, Isaac, Jacob, and all the prophets in the kingdom of God but you yourselves thrown out.'
EXEC add_BibleVerse @BibleId, 342013029, N'Then people will come from east and west, and from north and south, and take their places at the banquet table in the kingdom of God.'
EXEC add_BibleVerse @BibleId, 342013030, N'But indeed, some are last who will be first, and some are first who will be last.”'
EXEC add_BibleVerse @BibleId, 342013031, N'At that time, some Pharisees came up and said to Jesus, “Get away from here, because Herod wants to kill you.”'
EXEC add_BibleVerse @BibleId, 342013032, N'But he said to them, “Go and tell that fox, ‘Look, I am casting out demons and performing healings today and tomorrow, and on the third day I will complete my work.'
EXEC add_BibleVerse @BibleId, 342013033, N'Nevertheless I must go on my way today and tomorrow and the next day, because it is impossible that a prophet should be killed outside Jerusalem.’'
EXEC add_BibleVerse @BibleId, 342013034, N'O Jerusalem, Jerusalem, you who kill the prophets and stone those who are sent to you! How often I have longed to gather your children together as a hen gathers her chicks under her wings, but you would have none of it!'
EXEC add_BibleVerse @BibleId, 342013035, N'Look, your house is forsaken! And I tell you, you will not see me until you say, ‘Blessed is the one who comes in the name of the Lord!’”'
EXEC add_BibleVerse @BibleId, 342014001, N'Now one Sabbath when Jesus went to dine at the house of a leader of the Pharisees, they were watching him closely.'
EXEC add_BibleVerse @BibleId, 342014002, N'There right in front of him was a man suffering from dropsy.'
EXEC add_BibleVerse @BibleId, 342014003, N'So Jesus asked the experts in religious law and the Pharisees, “Is it lawful to heal on the Sabbath or not?”'
EXEC add_BibleVerse @BibleId, 342014004, N'But they remained silent. So Jesus took hold of the man, healed him, and sent him away.'
EXEC add_BibleVerse @BibleId, 342014005, N'Then he said to them, “Which of you, if you have a son or an ox that has fallen into a well on a Sabbath day, will not immediately pull him out?”'
EXEC add_BibleVerse @BibleId, 342014006, N'But they could not reply to this.'
EXEC add_BibleVerse @BibleId, 342014007, N'Then when Jesus noticed how the guests chose the places of honor, he told them a parable. He said to them,'
EXEC add_BibleVerse @BibleId, 342014008, N'“When you are invited by someone to a wedding feast, do not take the place of honor, because a person more distinguished than you may have been invited by your host.'
EXEC add_BibleVerse @BibleId, 342014009, N'So the host who invited both of you will come and say to you, ‘Give this man your place.’ Then, ashamed, you will begin to move to the least important place.'
EXEC add_BibleVerse @BibleId, 342014010, N'But when you are invited, go and take the least important place, so that when your host approaches he will say to you, ‘Friend, move up here to a better place.’ Then you will be honored in the presence of all who share the meal with you.'
EXEC add_BibleVerse @BibleId, 342014011, N'For everyone who exalts himself will be humbled, but the one who humbles himself will be exalted.”'
EXEC add_BibleVerse @BibleId, 342014012, N'He said also to the man who had invited him, “When you host a dinner or a banquet, don’t invite your friends or your brothers or your relatives or rich neighbors so you can be invited by them in return and get repaid.'
EXEC add_BibleVerse @BibleId, 342014013, N'But when you host an elaborate meal, invite the poor, the crippled, the lame, and the blind.'
EXEC add_BibleVerse @BibleId, 342014014, N'Then you will be blessed, because they cannot repay you, for you will be repaid at the resurrection of the righteous.”'
EXEC add_BibleVerse @BibleId, 342014015, N'When one of those at the meal with Jesus heard this, he said to him, “Blessed is everyone who will feast in the kingdom of God!”'
EXEC add_BibleVerse @BibleId, 342014016, N'But Jesus said to him, “A man once gave a great banquet and invited many guests.'
EXEC add_BibleVerse @BibleId, 342014017, N'At the time for the banquet he sent his slave to tell those who had been invited, ‘Come, because everything is now ready.’'
EXEC add_BibleVerse @BibleId, 342014018, N'But one after another they all began to make excuses. The first said to him, ‘I have bought a field, and I must go out and see it. Please excuse me.’'
EXEC add_BibleVerse @BibleId, 342014019, N'Another said, ‘I have bought five yoke of oxen, and I am going out to examine them. Please excuse me.’'
EXEC add_BibleVerse @BibleId, 342014020, N'Another said, ‘I just got married, and I cannot come.’'
EXEC add_BibleVerse @BibleId, 342014021, N'So the slave came back and reported this to his master. Then the master of the household was furious and said to his slave, ‘Go out quickly to the streets and alleys of the city, and bring in the poor, the crippled, the blind, and the lame.’'
EXEC add_BibleVerse @BibleId, 342014022, N'Then the slave said, ‘Sir, what you instructed has been done, and there is still room.’'
EXEC add_BibleVerse @BibleId, 342014023, N'So the master said to his slave, ‘Go out to the highways and country roads and urge people to come in, so that my house will be filled.'
EXEC add_BibleVerse @BibleId, 342014024, N'For I tell you, not one of those individuals who were invited will taste my banquet!’”'
EXEC add_BibleVerse @BibleId, 342014025, N'Now large crowds were accompanying Jesus, and turning to them he said,'
EXEC add_BibleVerse @BibleId, 342014026, N'“If anyone comes to me and does not hate his own father and mother, and wife and children, and brothers and sisters, and even his own life, he cannot be my disciple.'
EXEC add_BibleVerse @BibleId, 342014027, N'Whoever does not carry his own cross and follow me cannot be my disciple.'
EXEC add_BibleVerse @BibleId, 342014028, N'For which of you, wanting to build a tower, doesn’t sit down first and compute the cost to see if he has enough money to complete it?'
EXEC add_BibleVerse @BibleId, 342014029, N'Otherwise, when he has laid a foundation and is not able to finish the tower, all who see it will begin to make fun of him.'
EXEC add_BibleVerse @BibleId, 342014030, N'They will say, ‘This man began to build and was not able to finish!’'
EXEC add_BibleVerse @BibleId, 342014031, N'Or what king, going out to confront another king in battle, will not sit down first and determine whether he is able with ten thousand to oppose the one coming against him with twenty thousand?'
EXEC add_BibleVerse @BibleId, 342014032, N'If he cannot succeed, he will send a representative while the other is still a long way off and ask for terms of peace.'
EXEC add_BibleVerse @BibleId, 342014033, N'In the same way therefore not one of you can be my disciple if he does not renounce all his own possessions.'
EXEC add_BibleVerse @BibleId, 342014034, N'“Salt is good, but if salt loses its flavor, how can its flavor be restored?'
EXEC add_BibleVerse @BibleId, 342014035, N'It is of no value for the soil or for the manure pile; it is to be thrown out. The one who has ears to hear had better listen!”'
EXEC add_BibleVerse @BibleId, 342015001, N'Now all the tax collectors and sinners were coming to hear him.'
EXEC add_BibleVerse @BibleId, 342015002, N'But the Pharisees and the experts in the law were complaining, “This man welcomes sinners and eats with them.”'
EXEC add_BibleVerse @BibleId, 342015003, N'So Jesus told them this parable:'
EXEC add_BibleVerse @BibleId, 342015004, N'“Which one of you, if he has a hundred sheep and loses one of them, would not leave the ninety-nine in the open pasture and go look for the one that is lost until he finds it?'
EXEC add_BibleVerse @BibleId, 342015005, N'Then when he has found it, he places it on his shoulders, rejoicing.'
EXEC add_BibleVerse @BibleId, 342015006, N'Returning home, he calls together his friends and neighbors, telling them, ‘Rejoice with me, because I have found my sheep that was lost.’'
EXEC add_BibleVerse @BibleId, 342015007, N'I tell you, in the same way there will be more joy in heaven over one sinner who repents than over ninety-nine righteous people who have no need to repent.'
EXEC add_BibleVerse @BibleId, 342015008, N'“Or what woman, if she has ten silver coins and loses one of them, does not light a lamp, sweep the house, and search thoroughly until she finds it?'
EXEC add_BibleVerse @BibleId, 342015009, N'Then when she has found it, she calls together her friends and neighbors, saying, ‘Rejoice with me, for I have found the coin that I had lost.’'
EXEC add_BibleVerse @BibleId, 342015010, N'In the same way, I tell you, there is joy in the presence of God’s angels over one sinner who repents.”'
EXEC add_BibleVerse @BibleId, 342015011, N'Then Jesus said, “A man had two sons.'
EXEC add_BibleVerse @BibleId, 342015012, N'The younger of them said to his father, ‘Father, give me the share of the estate that will belong to me.’ So he divided his assets between them.'
EXEC add_BibleVerse @BibleId, 342015013, N'After a few days, the younger son gathered together all he had and left on a journey to a distant country, and there he squandered his wealth with a wild lifestyle.'
EXEC add_BibleVerse @BibleId, 342015014, N'Then after he had spent everything, a severe famine took place in that country, and he began to be in need.'
EXEC add_BibleVerse @BibleId, 342015015, N'So he went and worked for one of the citizens of that country, who sent him to his fields to feed pigs.'
EXEC add_BibleVerse @BibleId, 342015016, N'He was longing to eat the carob pods the pigs were eating, but no one gave him anything.'
EXEC add_BibleVerse @BibleId, 342015017, N'But when he came to his senses he said, ‘How many of my father’s hired workers have food enough to spare, but here I am dying from hunger!'
EXEC add_BibleVerse @BibleId, 342015018, N'I will get up and go to my father and say to him, “Father, I have sinned against heaven and against you.'
EXEC add_BibleVerse @BibleId, 342015019, N'I am no longer worthy to be called your son; treat me like one of your hired workers.”’'
EXEC add_BibleVerse @BibleId, 342015020, N'So he got up and went to his father. But while he was still a long way from home his father saw him, and his heart went out to him; he ran and hugged his son and kissed him.'
EXEC add_BibleVerse @BibleId, 342015021, N'Then his son said to him, ‘Father, I have sinned against heaven and against you; I am no longer worthy to be called your son.’'
EXEC add_BibleVerse @BibleId, 342015022, N'But the father said to his slaves, ‘Hurry! Bring the best robe, and put it on him! Put a ring on his finger and sandals on his feet!'
EXEC add_BibleVerse @BibleId, 342015023, N'Bring the fattened calf and kill it! Let us eat and celebrate,'
EXEC add_BibleVerse @BibleId, 342015024, N'because this son of mine was dead, and is alive again – he was lost and is found!’ So they began to celebrate.'
EXEC add_BibleVerse @BibleId, 342015025, N'“Now his older son was in the field. As he came and approached the house, he heard music and dancing.'
EXEC add_BibleVerse @BibleId, 342015026, N'So he called one of the slaves and asked what was happening.'
EXEC add_BibleVerse @BibleId, 342015027, N'The slave replied, ‘Your brother has returned, and your father has killed the fattened calf because he got his son back safe and sound.’'
EXEC add_BibleVerse @BibleId, 342015028, N'But the older son became angry and refused to go in. His father came out and appealed to him,'
EXEC add_BibleVerse @BibleId, 342015029, N'but he answered his father, ‘Look! These many years I have worked like a slave for you, and I never disobeyed your commands. Yet you never gave me even a goat so that I could celebrate with my friends!'
EXEC add_BibleVerse @BibleId, 342015030, N'But when this son of yours came back, who has devoured your assets with prostitutes, you killed the fattened calf for him!’'
EXEC add_BibleVerse @BibleId, 342015031, N'Then the father said to him, ‘Son, you are always with me, and everything that belongs to me is yours.'
EXEC add_BibleVerse @BibleId, 342015032, N'It was appropriate to celebrate and be glad, for your brother was dead, and is alive; he was lost and is found.’”'
EXEC add_BibleVerse @BibleId, 342016001, N'Jesus also said to the disciples, “There was a rich man who was informed of accusations that his manager was wasting his assets.'
EXEC add_BibleVerse @BibleId, 342016002, N'So he called the manager in and said to him, ‘What is this I hear about you? Turn in the account of your administration, because you can no longer be my manager.’'
EXEC add_BibleVerse @BibleId, 342016003, N'Then the manager said to himself, ‘What should I do, since my master is taking my position away from me? I’m not strong enough to dig, and I’m too ashamed to beg.'
EXEC add_BibleVerse @BibleId, 342016004, N'I know what to do so that when I am put out of management, people will welcome me into their homes.’'
EXEC add_BibleVerse @BibleId, 342016005, N'So he contacted his master’s debtors one by one. He asked the first, ‘How much do you owe my master?’'
EXEC add_BibleVerse @BibleId, 342016006, N'The man replied, ‘A hundred measures of olive oil.’ The manager said to him, ‘Take your bill, sit down quickly, and write fifty.’'
EXEC add_BibleVerse @BibleId, 342016007, N'Then he said to another, ‘And how much do you owe?’ The second man replied, ‘A hundred measures of wheat.’ The manager said to him, ‘Take your bill, and write eighty.’'
EXEC add_BibleVerse @BibleId, 342016008, N'The master commended the dishonest manager because he acted shrewdly. For the people of this world are more shrewd in dealing with their contemporaries than the people of light.'
EXEC add_BibleVerse @BibleId, 342016009, N'And I tell you, make friends for yourselves by how you use worldly wealth, so that when it runs out you will be welcomed into the eternal homes.'
EXEC add_BibleVerse @BibleId, 342016010, N'“The one who is faithful in a very little is also faithful in much, and the one who is dishonest in a very little is also dishonest in much.'
EXEC add_BibleVerse @BibleId, 342016011, N'If then you haven’t been trustworthy in handling worldly wealth, who will entrust you with the true riches?'
EXEC add_BibleVerse @BibleId, 342016012, N'And if you haven’t been trustworthy with someone else’s property, who will give you your own ?'
EXEC add_BibleVerse @BibleId, 342016013, N'No servant can serve two masters, for either he will hate the one and love the other, or he will be devoted to the one and despise the other. You cannot serve God and money.”'
EXEC add_BibleVerse @BibleId, 342016014, N'The Pharisees (who loved money) heard all this and ridiculed him.'
EXEC add_BibleVerse @BibleId, 342016015, N'But Jesus said to them, “You are the ones who justify yourselves in men’s eyes, but God knows your hearts. For what is highly prized among men is utterly detestable in God’s sight.'
EXEC add_BibleVerse @BibleId, 342016016, N'“The law and the prophets were in force until John; since then, the good news of the kingdom of God has been proclaimed, and everyone is urged to enter it.'
EXEC add_BibleVerse @BibleId, 342016017, N'But it is easier for heaven and earth to pass away than for one tiny stroke of a letter in the law to become void.'
EXEC add_BibleVerse @BibleId, 342016018, N'“Everyone who divorces his wife and marries someone else commits adultery, and the one who marries a woman divorced from her husband commits adultery.'
EXEC add_BibleVerse @BibleId, 342016019, N'“There was a rich man who dressed in purple and fine linen and who feasted sumptuously every day.'
EXEC add_BibleVerse @BibleId, 342016020, N'But at his gate lay a poor man named Lazarus whose body was covered with sores,'
EXEC add_BibleVerse @BibleId, 342016021, N'who longed to eat what fell from the rich man’s table. In addition, the dogs came and licked his sores.'
EXEC add_BibleVerse @BibleId, 342016022, N'“Now the poor man died and was carried by the angels to Abraham’s side. The rich man also died and was buried.'
EXEC add_BibleVerse @BibleId, 342016023, N'And in hell, as he was in torment, he looked up and saw Abraham far off with Lazarus at his side.'
EXEC add_BibleVerse @BibleId, 342016024, N'So he called out, ‘Father Abraham, have mercy on me, and send Lazarus to dip the tip of his finger in water and cool my tongue, because I am in anguish in this fire.’'
EXEC add_BibleVerse @BibleId, 342016025, N'But Abraham said, ‘Child, remember that in your lifetime you received your good things and Lazarus likewise bad things, but now he is comforted here and you are in anguish.'
EXEC add_BibleVerse @BibleId, 342016026, N'Besides all this, a great chasm has been fixed between us, so that those who want to cross over from here to you cannot do so, and no one can cross from there to us.’'
EXEC add_BibleVerse @BibleId, 342016027, N'So the rich man said, ‘Then I beg you, father – send Lazarus to my father’s house'
EXEC add_BibleVerse @BibleId, 342016028, N'(for I have five brothers) to warn them so that they don’t come into this place of torment.’'
EXEC add_BibleVerse @BibleId, 342016029, N'But Abraham said, ‘They have Moses and the prophets; they must respond to them.’'
EXEC add_BibleVerse @BibleId, 342016030, N'Then the rich man said, ‘No, father Abraham, but if someone from the dead goes to them, they will repent.’'
EXEC add_BibleVerse @BibleId, 342016031, N'He replied to him, ‘If they do not respond to Moses and the prophets, they will not be convinced even if someone rises from the dead.’”'
EXEC add_BibleVerse @BibleId, 342017001, N'Jesus said to his disciples, “Stumbling blocks are sure to come, but woe to the one through whom they come!'
EXEC add_BibleVerse @BibleId, 342017002, N'It would be better for him to have a millstone tied around his neck and be thrown into the sea than for him to cause one of these little ones to sin.'
EXEC add_BibleVerse @BibleId, 342017003, N'Watch yourselves! If your brother sins, rebuke him. If he repents, forgive him.'
EXEC add_BibleVerse @BibleId, 342017004, N'Even if he sins against you seven times in a day, and seven times returns to you saying, ‘I repent,’ you must forgive him.”'
EXEC add_BibleVerse @BibleId, 342017005, N'The apostles said to the Lord, “Increase our faith!”'
EXEC add_BibleVerse @BibleId, 342017006, N'So the Lord replied, “If you had faith the size of a mustard seed, you could say to this black mulberry tree, ‘Be pulled out by the roots and planted in the sea,’ and it would obey you.'
EXEC add_BibleVerse @BibleId, 342017007, N'“Would any one of you say to your slave who comes in from the field after plowing or shepherding sheep, ‘Come at once and sit down for a meal’?'
EXEC add_BibleVerse @BibleId, 342017008, N'Won’t the master instead say to him, ‘Get my dinner ready, and make yourself ready to serve me while I eat and drink. Then you may eat and drink’?'
EXEC add_BibleVerse @BibleId, 342017009, N'He won’t thank the slave because he did what he was told, will he?'
EXEC add_BibleVerse @BibleId, 342017010, N'So you too, when you have done everything you were commanded to do, should say, ‘We are slaves undeserving of special praise; we have only done what was our duty.’”'
EXEC add_BibleVerse @BibleId, 342017011, N'Now on the way to Jerusalem, Jesus was passing along between Samaria and Galilee.'
EXEC add_BibleVerse @BibleId, 342017012, N'As he was entering a village, ten men with leprosy met him. They stood at a distance,'
EXEC add_BibleVerse @BibleId, 342017013, N'raised their voices and said, “Jesus, Master, have mercy on us.”'
EXEC add_BibleVerse @BibleId, 342017014, N'When he saw them he said, “Go and show yourselves to the priests.” And as they went along, they were cleansed.'
EXEC add_BibleVerse @BibleId, 342017015, N'Then one of them, when he saw he was healed, turned back, praising God with a loud voice.'
EXEC add_BibleVerse @BibleId, 342017016, N'He fell with his face to the ground at Jesus’ feet and thanked him. (Now he was a Samaritan.)'
EXEC add_BibleVerse @BibleId, 342017017, N'Then Jesus said, “Were not ten cleansed? Where are the other nine?'
EXEC add_BibleVerse @BibleId, 342017018, N'Was no one found to turn back and give praise to God except this foreigner?”'
EXEC add_BibleVerse @BibleId, 342017019, N'Then he said to the man, “Get up and go your way. Your faith has made you well.”'
EXEC add_BibleVerse @BibleId, 342017020, N'Now at one point the Pharisees asked Jesus when the kingdom of God was coming, so he answered, “The kingdom of God is not coming with signs to be observed,'
EXEC add_BibleVerse @BibleId, 342017021, N'nor will they say, ‘Look, here it is!’ or ‘There!’ For indeed, the kingdom of God is in your midst.”'
EXEC add_BibleVerse @BibleId, 342017022, N'Then he said to the disciples, “The days are coming when you will desire to see one of the days of the Son of Man, and you will not see it.'
EXEC add_BibleVerse @BibleId, 342017023, N'Then people will say to you, ‘Look, there he is!’ or ‘Look, here he is!’ Do not go out or chase after them.'
EXEC add_BibleVerse @BibleId, 342017024, N'For just like the lightning flashes and lights up the sky from one side to the other, so will the Son of Man be in his day.'
EXEC add_BibleVerse @BibleId, 342017025, N'But first he must suffer many things and be rejected by this generation.'
EXEC add_BibleVerse @BibleId, 342017026, N'Just as it was in the days of Noah, so too it will be in the days of the Son of Man.'
EXEC add_BibleVerse @BibleId, 342017027, N'People were eating, they were drinking, they were marrying, they were being given in marriage – right up to the day Noah entered the ark. Then the flood came and destroyed them all.'
EXEC add_BibleVerse @BibleId, 342017028, N'Likewise, just as it was in the days of Lot, people were eating, drinking, buying, selling, planting, building;'
EXEC add_BibleVerse @BibleId, 342017029, N'but on the day Lot went out from Sodom, fire and sulfur rained down from heaven and destroyed them all.'
EXEC add_BibleVerse @BibleId, 342017030, N'It will be the same on the day the Son of Man is revealed.'
EXEC add_BibleVerse @BibleId, 342017031, N'On that day, anyone who is on the roof, with his goods in the house, must not come down to take them away, and likewise the person in the field must not turn back.'
EXEC add_BibleVerse @BibleId, 342017032, N'Remember Lot’s wife!'
EXEC add_BibleVerse @BibleId, 342017033, N'Whoever tries to keep his life will lose it, but whoever loses his life will preserve it.'
EXEC add_BibleVerse @BibleId, 342017034, N'I tell you, in that night there will be two people in one bed; one will be taken and the other left.'
EXEC add_BibleVerse @BibleId, 342017035, N'There will be two women grinding grain together; one will be taken and the other left.”'
EXEC add_BibleVerse @BibleId, 342017037, N' Then the disciples said to him, “Where, Lord?” He replied to them, “Where the dead body is, there the vultures will gather.”'
EXEC add_BibleVerse @BibleId, 342018001, N'Then Jesus told them a parable to show them they should always pray and not lose heart.'
EXEC add_BibleVerse @BibleId, 342018002, N'He said, “In a certain city there was a judge who neither feared God nor respected people.'
EXEC add_BibleVerse @BibleId, 342018003, N'There was also a widow in that city who kept coming to him and saying, ‘Give me justice against my adversary.’'
EXEC add_BibleVerse @BibleId, 342018004, N'For a while he refused, but later on he said to himself, ‘Though I neither fear God nor have regard for people,'
EXEC add_BibleVerse @BibleId, 342018005, N'yet because this widow keeps on bothering me, I will give her justice, or in the end she will wear me out by her unending pleas.’”'
EXEC add_BibleVerse @BibleId, 342018006, N'And the Lord said, “Listen to what the unrighteous judge says!'
EXEC add_BibleVerse @BibleId, 342018007, N'Won’t God give justice to his chosen ones, who cry out to him day and night? Will he delay long to help them?'
EXEC add_BibleVerse @BibleId, 342018008, N'I tell you, he will give them justice speedily. Nevertheless, when the Son of Man comes, will he find faith on earth?”'
EXEC add_BibleVerse @BibleId, 342018009, N'Jesus also told this parable to some who were confident that they were righteous and looked down on everyone else.'
EXEC add_BibleVerse @BibleId, 342018010, N'“Two men went up to the temple to pray, one a Pharisee and the other a tax collector.'
EXEC add_BibleVerse @BibleId, 342018011, N'The Pharisee stood and prayed about himself like this: ‘God, I thank you that I am not like other people: extortionists, unrighteous people, adulterers – or even like this tax collector.'
EXEC add_BibleVerse @BibleId, 342018012, N'I fast twice a week; I give a tenth of everything I get.’'
EXEC add_BibleVerse @BibleId, 342018013, N'The tax collector, however, stood far off and would not even look up to heaven, but beat his breast and said, ‘God, be merciful to me, sinner that I am!’'
EXEC add_BibleVerse @BibleId, 342018014, N'I tell you that this man went down to his home justified rather than the Pharisee. For everyone who exalts himself will be humbled, but he who humbles himself will be exalted.”'
EXEC add_BibleVerse @BibleId, 342018015, N'Now people were even bringing their babies to him for him to touch. But when the disciples saw it, they began to scold those who brought them.'
EXEC add_BibleVerse @BibleId, 342018016, N'But Jesus called for the children, saying, “Let the little children come to me and do not try to stop them, for the kingdom of God belongs to such as these.'
EXEC add_BibleVerse @BibleId, 342018017, N'I tell you the truth, whoever does not receive the kingdom of God like a child will never enter it.”'
EXEC add_BibleVerse @BibleId, 342018018, N'Now a certain ruler asked him, “Good teacher, what must I do to inherit eternal life?”'
EXEC add_BibleVerse @BibleId, 342018019, N'Jesus said to him, “Why do you call me good? No one is good except God alone.'
EXEC add_BibleVerse @BibleId, 342018020, N'You know the commandments: ‘ Do not commit adultery, do not murder, do not steal, do not give false testimony, honor your father and mother.’”'
EXEC add_BibleVerse @BibleId, 342018021, N'The man replied, “I have wholeheartedly obeyed all these laws since my youth.”'
EXEC add_BibleVerse @BibleId, 342018022, N'When Jesus heard this, he said to him, “One thing you still lack. Sell all that you have and give the money to the poor, and you will have treasure in heaven. Then come, follow me.”'
EXEC add_BibleVerse @BibleId, 342018023, N'But when the man heard this he became very sad, for he was extremely wealthy.'
EXEC add_BibleVerse @BibleId, 342018024, N'When Jesus noticed this, he said, “How hard it is for the rich to enter the kingdom of God!'
EXEC add_BibleVerse @BibleId, 342018025, N'In fact, it is easier for a camel to go through the eye of a needle than for a rich person to enter the kingdom of God.”'
EXEC add_BibleVerse @BibleId, 342018026, N'Those who heard this said, “Then who can be saved?”'
EXEC add_BibleVerse @BibleId, 342018027, N'He replied, “What is impossible for mere humans is possible for God.”'
EXEC add_BibleVerse @BibleId, 342018028, N'And Peter said, “Look, we have left everything we own to follow you!”'
EXEC add_BibleVerse @BibleId, 342018029, N'Then Jesus said to them, “I tell you the truth, there is no one who has left home or wife or brothers or parents or children for the sake of God’s kingdom'
EXEC add_BibleVerse @BibleId, 342018030, N'who will not receive many times more in this age – and in the age to come, eternal life.”'
EXEC add_BibleVerse @BibleId, 342018031, N'Then Jesus took the twelve aside and said to them, “Look, we are going up to Jerusalem, and everything that is written about the Son of Man by the prophets will be accomplished.'
EXEC add_BibleVerse @BibleId, 342018032, N'For he will be handed over to the Gentiles; he will be mocked, mistreated, and spat on.'
EXEC add_BibleVerse @BibleId, 342018033, N'They will flog him severely and kill him. Yet on the third day he will rise again.”'
EXEC add_BibleVerse @BibleId, 342018034, N'But the twelve understood none of these things. This saying was hidden from them, and they did not grasp what Jesus meant.'
EXEC add_BibleVerse @BibleId, 342018035, N'As Jesus approached Jericho, a blind man was sitting by the road begging.'
EXEC add_BibleVerse @BibleId, 342018036, N'When he heard a crowd going by, he asked what was going on.'
EXEC add_BibleVerse @BibleId, 342018037, N'They told him, “Jesus the Nazarene is passing by.”'
EXEC add_BibleVerse @BibleId, 342018038, N'So he called out, “Jesus, Son of David, have mercy on me!”'
EXEC add_BibleVerse @BibleId, 342018039, N'And those who were in front scolded him to get him to be quiet, but he shouted even more, “Son of David, have mercy on me!”'
EXEC add_BibleVerse @BibleId, 342018040, N'So Jesus stopped and ordered the beggar to be brought to him. When the man came near, Jesus asked him,'
EXEC add_BibleVerse @BibleId, 342018041, N'“What do you want me to do for you?” He replied, “Lord, let me see again.”'
EXEC add_BibleVerse @BibleId, 342018042, N'Jesus said to him, “Receive your sight; your faith has healed you.”'
EXEC add_BibleVerse @BibleId, 342018043, N'And immediately he regained his sight and followed Jesus, praising God. When all the people saw it, they too gave praise to God.'
EXEC add_BibleVerse @BibleId, 342019001, N'Jesus entered Jericho and was passing through it.'
EXEC add_BibleVerse @BibleId, 342019002, N'Now a man named Zacchaeus was there; he was a chief tax collector and was rich.'
EXEC add_BibleVerse @BibleId, 342019003, N'He was trying to get a look at Jesus, but being a short man he could not see over the crowd.'
EXEC add_BibleVerse @BibleId, 342019004, N'So he ran on ahead and climbed up into a sycamore tree to see him, because Jesus was going to pass that way.'
EXEC add_BibleVerse @BibleId, 342019005, N'And when Jesus came to that place, he looked up and said to him, “Zacchaeus, come down quickly, because I must stay at your house today.”'
EXEC add_BibleVerse @BibleId, 342019006, N'So he came down quickly and welcomed Jesus joyfully.'
EXEC add_BibleVerse @BibleId, 342019007, N'And when the people saw it, they all complained, “He has gone in to be the guest of a man who is a sinner.”'
EXEC add_BibleVerse @BibleId, 342019008, N'But Zacchaeus stopped and said to the Lord, “Look, Lord, half of my possessions I now give to the poor, and if I have cheated anyone of anything, I am paying back four times as much!”'
EXEC add_BibleVerse @BibleId, 342019009, N'Then Jesus said to him, “Today salvation has come to this household, because he too is a son of Abraham!'
EXEC add_BibleVerse @BibleId, 342019010, N'For the Son of Man came to seek and to save the lost.”'
EXEC add_BibleVerse @BibleId, 342019011, N'While the people were listening to these things, Jesus proceeded to tell a parable, because he was near to Jerusalem, and because they thought that the kingdom of God was going to appear immediately.'
EXEC add_BibleVerse @BibleId, 342019012, N'Therefore he said, “A nobleman went to a distant country to receive for himself a kingdom and then return.'
EXEC add_BibleVerse @BibleId, 342019013, N'And he summoned ten of his slaves, gave them ten minas, and said to them, ‘Do business with these until I come back.’'
EXEC add_BibleVerse @BibleId, 342019014, N'But his citizens hated him and sent a delegation after him, saying, ‘We do not want this man to be king over us!’'
EXEC add_BibleVerse @BibleId, 342019015, N'When he returned after receiving the kingdom, he summoned these slaves to whom he had given the money. He wanted to know how much they had earned by trading.'
EXEC add_BibleVerse @BibleId, 342019016, N'So the first one came before him and said, ‘Sir, your mina has made ten minas more.’'
EXEC add_BibleVerse @BibleId, 342019017, N'And the king said to him, ‘Well done, good slave! Because you have been faithful in a very small matter, you will have authority over ten cities.’'
EXEC add_BibleVerse @BibleId, 342019018, N'Then the second one came and said, ‘Sir, your mina has made five minas.’'
EXEC add_BibleVerse @BibleId, 342019019, N'So the king said to him, ‘And you are to be over five cities.’'
EXEC add_BibleVerse @BibleId, 342019020, N'Then another slave came and said, ‘Sir, here is your mina that I put away for safekeeping in a piece of cloth.'
EXEC add_BibleVerse @BibleId, 342019021, N'For I was afraid of you, because you are a severe man. You withdraw what you did not deposit and reap what you did not sow.’'
EXEC add_BibleVerse @BibleId, 342019022, N'The king said to him, ‘I will judge you by your own words, you wicked slave! So you knew, did you, that I was a severe man, withdrawing what I didn’t deposit and reaping what I didn’t sow?'
EXEC add_BibleVerse @BibleId, 342019023, N'Why then didn’t you put my money in the bank, so that when I returned I could have collected it with interest?’'
EXEC add_BibleVerse @BibleId, 342019024, N'And he said to his attendants, ‘Take the mina from him, and give it to the one who has ten.’'
EXEC add_BibleVerse @BibleId, 342019025, N'But they said to him, ‘Sir, he has ten minas already!’'
EXEC add_BibleVerse @BibleId, 342019026, N'‘I tell you that everyone who has will be given more, but from the one who does not have, even what he has will be taken away.'
EXEC add_BibleVerse @BibleId, 342019027, N'But as for these enemies of mine who did not want me to be their king, bring them here and slaughter them in front of me!’”'
EXEC add_BibleVerse @BibleId, 342019028, N'After Jesus had said this, he continued on ahead, going up to Jerusalem.'
EXEC add_BibleVerse @BibleId, 342019029, N'Now when he approached Bethphage and Bethany, at the place called the Mount of Olives, he sent two of the disciples,'
EXEC add_BibleVerse @BibleId, 342019030, N'telling them, “Go to the village ahead of you. When you enter it, you will find a colt tied there that has never been ridden. Untie it and bring it here.'
EXEC add_BibleVerse @BibleId, 342019031, N'If anyone asks you, ‘Why are you untying it?’ just say, ‘The Lord needs it.’”'
EXEC add_BibleVerse @BibleId, 342019032, N'So those who were sent ahead found it exactly as he had told them.'
EXEC add_BibleVerse @BibleId, 342019033, N'As they were untying the colt, its owners asked them, “Why are you untying that colt?”'
EXEC add_BibleVerse @BibleId, 342019034, N'They replied, “The Lord needs it.”'
EXEC add_BibleVerse @BibleId, 342019035, N'Then they brought it to Jesus, threw their cloaks on the colt, and had Jesus get on it.'
EXEC add_BibleVerse @BibleId, 342019036, N'As he rode along, they spread their cloaks on the road.'
EXEC add_BibleVerse @BibleId, 342019037, N'As he approached the road leading down from the Mount of Olives, the whole crowd of his disciples began to rejoice and praise God with a loud voice for all the mighty works they had seen:'
EXEC add_BibleVerse @BibleId, 342019038, N'“ Blessed is the king who comes in the name of the Lord! Peace in heaven and glory in the highest!”'
EXEC add_BibleVerse @BibleId, 342019039, N'But some of the Pharisees in the crowd said to him, “Teacher, rebuke your disciples.”'
EXEC add_BibleVerse @BibleId, 342019040, N'He answered, “I tell you, if they keep silent, the very stones will cry out!”'
EXEC add_BibleVerse @BibleId, 342019041, N'Now when Jesus approached and saw the city, he wept over it,'
EXEC add_BibleVerse @BibleId, 342019042, N'saying, “If you had only known on this day, even you, the things that make for peace! But now they are hidden from your eyes.'
EXEC add_BibleVerse @BibleId, 342019043, N'For the days will come upon you when your enemies will build an embankment against you and surround you and close in on you from every side.'
EXEC add_BibleVerse @BibleId, 342019044, N'They will demolish you – you and your children within your walls – and they will not leave within you one stone on top of another, because you did not recognize the time of your visitation from God.”'
EXEC add_BibleVerse @BibleId, 342019045, N'Then Jesus entered the temple courts and began to drive out those who were selling things there,'
EXEC add_BibleVerse @BibleId, 342019046, N'saying to them, “It is written, ‘ My house will be a house of prayer,’ but you have turned it into a den of robbers!”'
EXEC add_BibleVerse @BibleId, 342019047, N'Jesus was teaching daily in the temple courts. The chief priests and the experts in the law and the prominent leaders among the people were seeking to assassinate him,'
EXEC add_BibleVerse @BibleId, 342019048, N'but they could not find a way to do it, for all the people hung on his words.'
EXEC add_BibleVerse @BibleId, 342020001, N'Now one day, as Jesus was teaching the people in the temple courts and proclaiming the gospel, the chief priests and the experts in the law with the elders came up'
EXEC add_BibleVerse @BibleId, 342020002, N'and said to him, “Tell us: By what authority are you doing these things? Or who it is who gave you this authority?”'
EXEC add_BibleVerse @BibleId, 342020003, N'He answered them, “I will also ask you a question, and you tell me:'
EXEC add_BibleVerse @BibleId, 342020004, N'John’s baptism – was it from heaven or from people?”'
EXEC add_BibleVerse @BibleId, 342020005, N'So they discussed it with one another, saying, “If we say, ‘From heaven,’ he will say, ‘Why did you not believe him?’'
EXEC add_BibleVerse @BibleId, 342020006, N'But if we say, ‘From people,’ all the people will stone us, because they are convinced that John was a prophet.”'
EXEC add_BibleVerse @BibleId, 342020007, N'So they replied that they did not know where it came from.'
EXEC add_BibleVerse @BibleId, 342020008, N'Then Jesus said to them, “Neither will I tell you by whose authority I do these things.”'
EXEC add_BibleVerse @BibleId, 342020009, N'Then he began to tell the people this parable: “A man planted a vineyard, leased it to tenant farmers, and went on a journey for a long time.'
EXEC add_BibleVerse @BibleId, 342020010, N'When harvest time came, he sent a slave to the tenants so that they would give him his portion of the crop. However, the tenants beat his slave and sent him away empty-handed.'
EXEC add_BibleVerse @BibleId, 342020011, N'So he sent another slave. They beat this one too, treated him outrageously, and sent him away empty-handed.'
EXEC add_BibleVerse @BibleId, 342020012, N'So he sent still a third. They even wounded this one, and threw him out.'
EXEC add_BibleVerse @BibleId, 342020013, N'Then the owner of the vineyard said, ‘What should I do? I will send my one dear son; perhaps they will respect him.’'
EXEC add_BibleVerse @BibleId, 342020014, N'But when the tenants saw him, they said to one another, ‘This is the heir; let’s kill him so the inheritance will be ours!’'
EXEC add_BibleVerse @BibleId, 342020015, N'So they threw him out of the vineyard and killed him. What then will the owner of the vineyard do to them?'
EXEC add_BibleVerse @BibleId, 342020016, N'He will come and destroy those tenants and give the vineyard to others.” When the people heard this, they said, “May this never happen!”'
EXEC add_BibleVerse @BibleId, 342020017, N'But Jesus looked straight at them and said, “Then what is the meaning of that which is written: ‘ The stone the builders rejected has become the cornerstone’?'
EXEC add_BibleVerse @BibleId, 342020018, N'Everyone who falls on this stone will be broken to pieces, and the one on whom it falls will be crushed.”'
EXEC add_BibleVerse @BibleId, 342020019, N'Then the experts in the law and the chief priests wanted to arrest him that very hour, because they realized he had told this parable against them. But they were afraid of the people.'
EXEC add_BibleVerse @BibleId, 342020020, N'Then they watched him carefully and sent spies who pretended to be sincere. They wanted to take advantage of what he might say so that they could deliver him up to the authority and jurisdiction of the governor.'
EXEC add_BibleVerse @BibleId, 342020021, N'Thus they asked him, “Teacher, we know that you speak and teach correctly, and show no partiality, but teach the way of God in accordance with the truth.'
EXEC add_BibleVerse @BibleId, 342020022, N'Is it right for us to pay the tribute tax to Caesar or not?”'
EXEC add_BibleVerse @BibleId, 342020023, N'But Jesus perceived their deceit and said to them,'
EXEC add_BibleVerse @BibleId, 342020024, N'“Show me a denarius. Whose image and inscription are on it?” They said, “Caesar’s.”'
EXEC add_BibleVerse @BibleId, 342020025, N'So he said to them, “Then give to Caesar the things that are Caesar’s, and to God the things that are God’s.”'
EXEC add_BibleVerse @BibleId, 342020026, N'Thus they were unable in the presence of the people to trap him with his own words. And stunned by his answer, they fell silent.'
EXEC add_BibleVerse @BibleId, 342020027, N'Now some Sadducees (who contend that there is no resurrection) came to him.'
EXEC add_BibleVerse @BibleId, 342020028, N'They asked him, “Teacher, Moses wrote for us that if a man’s brother dies leaving a wife but no children, that man must marry the widow and father children for his brother*.'
EXEC add_BibleVerse @BibleId, 342020029, N'Now there were seven brothers. The first one married a woman and died without children.'
EXEC add_BibleVerse @BibleId, 342020030, N'The second'
EXEC add_BibleVerse @BibleId, 342020031, N'and then the third married her, and in this same way all seven died, leaving no children.'
EXEC add_BibleVerse @BibleId, 342020032, N'Finally the woman died too.'
EXEC add_BibleVerse @BibleId, 342020033, N'In the resurrection, therefore, whose wife will the woman be? For all seven had married her.”'
EXEC add_BibleVerse @BibleId, 342020034, N'So Jesus said to them, “The people of this age marry and are given in marriage.'
EXEC add_BibleVerse @BibleId, 342020035, N'But those who are regarded as worthy to share in that age and in the resurrection from the dead neither marry nor are given in marriage.'
EXEC add_BibleVerse @BibleId, 342020036, N'In fact, they can no longer die, because they are equal to angels and are sons of God, since they are sons of the resurrection.'
EXEC add_BibleVerse @BibleId, 342020037, N'But even Moses revealed that the dead are raised in the passage about the bush, where he calls the Lord the God of Abraham and the God of Isaac and the God of Jacob of Abraham and the God of Isaac and the God of Jacob.'
EXEC add_BibleVerse @BibleId, 342020038, N'Now he is not God of the dead, but of the living, for all live before him.”'
EXEC add_BibleVerse @BibleId, 342020039, N'Then some of the experts in the law answered, “Teacher, you have spoken well!”'
EXEC add_BibleVerse @BibleId, 342020040, N'For they did not dare any longer to ask him anything.'
EXEC add_BibleVerse @BibleId, 342020041, N'But he said to them, “How is it that they say that the Christ is David’s son?'
EXEC add_BibleVerse @BibleId, 342020042, N'For David himself says in the book of Psalms, ‘ The Lord said to my lord, “ Sit at my right hand,'
EXEC add_BibleVerse @BibleId, 342020043, N'until I make your enemies a footstool for your feet.”’'
EXEC add_BibleVerse @BibleId, 342020044, N'If David then calls him ‘Lord,’ how can he be his son?”'
EXEC add_BibleVerse @BibleId, 342020045, N'As all the people were listening, Jesus said to his disciples,'
EXEC add_BibleVerse @BibleId, 342020046, N'“Beware of the experts in the law. They like walking around in long robes, and they love elaborate greetings in the marketplaces and the best seats in the synagogues and the places of honor at banquets.'
EXEC add_BibleVerse @BibleId, 342020047, N'They devour widows’ property, and as a show make long prayers. They will receive a more severe punishment.”'
EXEC add_BibleVerse @BibleId, 342021001, N'Jesus looked up and saw the rich putting their gifts into the offering box.'
EXEC add_BibleVerse @BibleId, 342021002, N'He also saw a poor widow put in two small copper coins.'
EXEC add_BibleVerse @BibleId, 342021003, N'He said, “I tell you the truth, this poor widow has put in more than all of them.'
EXEC add_BibleVerse @BibleId, 342021004, N'For they all offered their gifts out of their wealth. But she, out of her poverty, put in everything she had to live on.”'
EXEC add_BibleVerse @BibleId, 342021005, N'Now while some were speaking about the temple, how it was adorned with beautiful stones and offerings, Jesus said,'
EXEC add_BibleVerse @BibleId, 342021006, N'“As for these things that you are gazing at, the days will come when not one stone will be left on another. All will be torn down!”'
EXEC add_BibleVerse @BibleId, 342021007, N'So they asked him, “Teacher, when will these things happen? And what will be the sign that these things are about to take place?”'
EXEC add_BibleVerse @BibleId, 342021008, N'He said, “Watch out that you are not misled. For many will come in my name, saying, ‘I am he,’ and, ‘The time is near.’ Do not follow them!'
EXEC add_BibleVerse @BibleId, 342021009, N'And when you hear of wars and rebellions, do not be afraid. For these things must happen first, but the end will not come at once.”'
EXEC add_BibleVerse @BibleId, 342021010, N'Then he said to them, “Nation will rise up in arms against nation, and kingdom against kingdom.'
EXEC add_BibleVerse @BibleId, 342021011, N'There will be great earthquakes, and famines and plagues in various places, and there will be terrifying sights and great signs from heaven.'
EXEC add_BibleVerse @BibleId, 342021012, N'But before all this, they will seize you and persecute you, handing you over to the synagogues and prisons. You will be brought before kings and governors because of my name.'
EXEC add_BibleVerse @BibleId, 342021013, N'This will be a time for you to serve as witnesses.'
EXEC add_BibleVerse @BibleId, 342021014, N'Therefore be resolved not to rehearse ahead of time how to make your defense.'
EXEC add_BibleVerse @BibleId, 342021015, N'For I will give you the words along with the wisdom that none of your adversaries will be able to withstand or contradict.'
EXEC add_BibleVerse @BibleId, 342021016, N'You will be betrayed even by parents, brothers, relatives, and friends, and they will have some of you put to death.'
EXEC add_BibleVerse @BibleId, 342021017, N'You will be hated by everyone because of my name.'
EXEC add_BibleVerse @BibleId, 342021018, N'Yet not a hair of your head will perish.'
EXEC add_BibleVerse @BibleId, 342021019, N'By your endurance you will gain your lives.'
EXEC add_BibleVerse @BibleId, 342021020, N'“But when you see Jerusalem surrounded by armies, then know that its desolation has come near.'
EXEC add_BibleVerse @BibleId, 342021021, N'Then those who are in Judea must flee to the mountains. Those who are inside the city must depart. Those who are out in the country must not enter it,'
EXEC add_BibleVerse @BibleId, 342021022, N'because these are days of vengeance, to fulfill all that is written.'
EXEC add_BibleVerse @BibleId, 342021023, N'Woe to those who are pregnant and to those who are nursing their babies in those days! For there will be great distress on the earth and wrath against this people.'
EXEC add_BibleVerse @BibleId, 342021024, N'They will fall by the edge of the sword and be led away as captives among all nations. Jerusalem will be trampled down by the Gentiles until the times of the Gentiles are fulfilled.'
EXEC add_BibleVerse @BibleId, 342021025, N'“And there will be signs in the sun and moon and stars, and on the earth nations will be in distress, anxious over the roaring of the sea and the surging waves.'
EXEC add_BibleVerse @BibleId, 342021026, N'People will be fainting from fear and from the expectation of what is coming on the world, for the powers of the heavens will be shaken.'
EXEC add_BibleVerse @BibleId, 342021027, N'Then they will see the Son of Man arriving in a cloud with power and great glory.'
EXEC add_BibleVerse @BibleId, 342021028, N'But when these things begin to happen, stand up and raise your heads, because your redemption is drawing near.”'
EXEC add_BibleVerse @BibleId, 342021029, N'Then he told them a parable: “Look at the fig tree and all the other trees.'
EXEC add_BibleVerse @BibleId, 342021030, N'When they sprout leaves, you see for yourselves and know that summer is now near.'
EXEC add_BibleVerse @BibleId, 342021031, N'So also you, when you see these things happening, know that the kingdom of God is near.'
EXEC add_BibleVerse @BibleId, 342021032, N'I tell you the truth, this generation will not pass away until all these things take place.'
EXEC add_BibleVerse @BibleId, 342021033, N'Heaven and earth will pass away, but my words will never pass away.'
EXEC add_BibleVerse @BibleId, 342021034, N'“But be on your guard so that your hearts are not weighed down with dissipation and drunkenness and the worries of this life, and that day close down upon you suddenly like a trap.'
EXEC add_BibleVerse @BibleId, 342021035, N'For it will overtake all who live on the face of the whole earth.'
EXEC add_BibleVerse @BibleId, 342021036, N'But stay alert at all times, praying that you may have strength to escape all these things that must happen, and to stand before the Son of Man.”'
EXEC add_BibleVerse @BibleId, 342021037, N'So every day Jesus was teaching in the temple courts, but at night he went and stayed on the Mount of Olives.'
EXEC add_BibleVerse @BibleId, 342021038, N'And all the people came to him early in the morning to listen to him in the temple courts.'
EXEC add_BibleVerse @BibleId, 342022001, N'Now the Feast of Unleavened Bread, which is called the Passover, was approaching.'
EXEC add_BibleVerse @BibleId, 342022002, N'The chief priests and the experts in the law were trying to find some way to execute Jesus, for they were afraid of the people.'
EXEC add_BibleVerse @BibleId, 342022003, N'Then Satan entered Judas, the one called Iscariot, who was one of the twelve.'
EXEC add_BibleVerse @BibleId, 342022004, N'He went away and discussed with the chief priests and officers of the temple guard how he might betray Jesus, handing him over to them.'
EXEC add_BibleVerse @BibleId, 342022005, N'They were delighted and arranged to give him money.'
EXEC add_BibleVerse @BibleId, 342022006, N'So Judas agreed and began looking for an opportunity to betray Jesus when no crowd was present.'
EXEC add_BibleVerse @BibleId, 342022007, N'Then the day for the feast of Unleavened Bread came, on which the Passover lamb had to be sacrificed.'
EXEC add_BibleVerse @BibleId, 342022008, N'Jesus sent Peter and John, saying, “Go and prepare the Passover for us to eat.”'
EXEC add_BibleVerse @BibleId, 342022009, N'They said to him, “Where do you want us to prepare it?”'
EXEC add_BibleVerse @BibleId, 342022010, N'He said to them, “Listen, when you have entered the city, a man carrying a jar of water will meet you. Follow him into the house that he enters,'
EXEC add_BibleVerse @BibleId, 342022011, N'and tell the owner of the house, ‘The Teacher says to you, “Where is the guest room where I may eat the Passover with my disciples?”’'
EXEC add_BibleVerse @BibleId, 342022012, N'Then he will show you a large furnished room upstairs. Make preparations there.”'
EXEC add_BibleVerse @BibleId, 342022013, N'So they went and found things just as he had told them, and they prepared the Passover.'
EXEC add_BibleVerse @BibleId, 342022014, N'Now when the hour came, Jesus took his place at the table and the apostles joined him.'
EXEC add_BibleVerse @BibleId, 342022015, N'And he said to them, “I have earnestly desired to eat this Passover with you before I suffer.'
EXEC add_BibleVerse @BibleId, 342022016, N'For I tell you, I will not eat it again until it is fulfilled in the kingdom of God.”'
EXEC add_BibleVerse @BibleId, 342022017, N'Then he took a cup, and after giving thanks he said, “Take this and divide it among yourselves.'
EXEC add_BibleVerse @BibleId, 342022018, N'For I tell you that from now on I will not drink of the fruit of the vine until the kingdom of God comes.”'
EXEC add_BibleVerse @BibleId, 342022019, N'Then he took bread, and after giving thanks he broke it and gave it to them, saying, “This is my body which is given for you. Do this in remembrance of me.”'
EXEC add_BibleVerse @BibleId, 342022020, N'And in the same way he took the cup after they had eaten, saying, “This cup that is poured out for you is the new covenant in my blood.'
EXEC add_BibleVerse @BibleId, 342022021, N'“But look, the hand of the one who betrays me is with me on the table.'
EXEC add_BibleVerse @BibleId, 342022022, N'For the Son of Man is to go just as it has been determined, but woe to that man by whom he is betrayed!”'
EXEC add_BibleVerse @BibleId, 342022023, N'So they began to question one another as to which of them it could possibly be who would do this.'
EXEC add_BibleVerse @BibleId, 342022024, N'A dispute also started among them over which of them was to be regarded as the greatest.'
EXEC add_BibleVerse @BibleId, 342022025, N'So Jesus said to them, “The kings of the Gentiles lord it over them, and those in authority over them are called ‘benefactors.’'
EXEC add_BibleVerse @BibleId, 342022026, N'Not so with you; instead the one who is greatest among you must become like the youngest, and the leader like the one who serves.'
EXEC add_BibleVerse @BibleId, 342022027, N'For who is greater, the one who is seated at the table, or the one who serves? Is it not the one who is seated at the table? But I am among you as one who serves.'
EXEC add_BibleVerse @BibleId, 342022028, N'“You are the ones who have remained with me in my trials.'
EXEC add_BibleVerse @BibleId, 342022029, N'Thus I grant to you a kingdom, just as my Father granted to me,'
EXEC add_BibleVerse @BibleId, 342022030, N'that you may eat and drink at my table in my kingdom, and you will sit on thrones judging the twelve tribes of Israel.'
EXEC add_BibleVerse @BibleId, 342022031, N'“Simon, Simon, pay attention! Satan has demanded to have you all, to sift you like wheat,'
EXEC add_BibleVerse @BibleId, 342022032, N'but I have prayed for you, Simon, that your faith may not fail. When you have turned back, strengthen your brothers.”'
EXEC add_BibleVerse @BibleId, 342022033, N'But Peter said to him, “Lord, I am ready to go with you both to prison and to death!”'
EXEC add_BibleVerse @BibleId, 342022034, N'Jesus replied, “I tell you, Peter, the rooster will not crow today until you have denied three times that you know me.”'
EXEC add_BibleVerse @BibleId, 342022035, N'Then Jesus said to them, “When I sent you out with no money bag, or traveler’s bag, or sandals, you didn’t lack anything, did you?” They replied, “Nothing.”'
EXEC add_BibleVerse @BibleId, 342022036, N'He said to them, “But now, the one who has a money bag must take it, and likewise a traveler’s bag too. And the one who has no sword must sell his cloak and buy one.'
EXEC add_BibleVerse @BibleId, 342022037, N'For I tell you that this scripture must be fulfilled in me, ‘ And he was counted with the transgressors.’ For what is written about me is being fulfilled.”'
EXEC add_BibleVerse @BibleId, 342022038, N'So they said, “Look, Lord, here are two swords.” Then he told them, “It is enough.”'
EXEC add_BibleVerse @BibleId, 342022039, N'Then Jesus went out and made his way, as he customarily did, to the Mount of Olives, and the disciples followed him.'
EXEC add_BibleVerse @BibleId, 342022040, N'When he came to the place, he said to them, “Pray that you will not fall into temptation.”'
EXEC add_BibleVerse @BibleId, 342022041, N'He went away from them about a stone’s throw, knelt down, and prayed,'
EXEC add_BibleVerse @BibleId, 342022042, N'“Father, if you are willing, take this cup away from me. Yet not my will but yours be done.”'
EXEC add_BibleVerse @BibleId, 342022043, N'Then an angel from heaven appeared to him and strengthened him.'
EXEC add_BibleVerse @BibleId, 342022044, N'And in his anguish he prayed more earnestly, and his sweat was like drops of blood falling to the ground.'
EXEC add_BibleVerse @BibleId, 342022045, N'When he got up from prayer, he came to the disciples and found them sleeping, exhausted from grief.'
EXEC add_BibleVerse @BibleId, 342022046, N'So he said to them, “Why are you sleeping? Get up and pray that you will not fall into temptation!”'
EXEC add_BibleVerse @BibleId, 342022047, N'While he was still speaking, suddenly a crowd appeared, and the man named Judas, one of the twelve, was leading them. He walked up to Jesus to kiss him.'
EXEC add_BibleVerse @BibleId, 342022048, N'But Jesus said to him, “Judas, would you betray the Son of Man with a kiss?”'
EXEC add_BibleVerse @BibleId, 342022049, N'When those who were around him saw what was about to happen, they said, “Lord, should we use our swords?”'
EXEC add_BibleVerse @BibleId, 342022050, N'Then one of them struck the high priest’s slave, cutting off his right ear.'
EXEC add_BibleVerse @BibleId, 342022051, N'But Jesus said, “Enough of this!” And he touched the man’s ear and healed him.'
EXEC add_BibleVerse @BibleId, 342022052, N'Then Jesus said to the chief priests, the officers of the temple guard, and the elders who had come out to get him, “Have you come out with swords and clubs like you would against an outlaw?'
EXEC add_BibleVerse @BibleId, 342022053, N'Day after day when I was with you in the temple courts, you did not arrest me. But this is your hour, and that of the power of darkness!”'
EXEC add_BibleVerse @BibleId, 342022054, N'Then they arrested Jesus, led him away, and brought him into the high priest’s house. But Peter was following at a distance.'
EXEC add_BibleVerse @BibleId, 342022055, N'When they had made a fire in the middle of the courtyard and sat down together, Peter sat down among them.'
EXEC add_BibleVerse @BibleId, 342022056, N'Then a slave girl, seeing him as he sat in the firelight, stared at him and said, “This man was with him too!”'
EXEC add_BibleVerse @BibleId, 342022057, N'But Peter denied it: “Woman, I don’t know him!”'
EXEC add_BibleVerse @BibleId, 342022058, N'Then a little later someone else saw him and said, “You are one of them too.” But Peter said, “Man, I am not!”'
EXEC add_BibleVerse @BibleId, 342022059, N'And after about an hour still another insisted, “Certainly this man was with him, because he too is a Galilean.”'
EXEC add_BibleVerse @BibleId, 342022060, N'But Peter said, “Man, I don’t know what you’re talking about!” At that moment, while he was still speaking, a rooster crowed.'
EXEC add_BibleVerse @BibleId, 342022061, N'Then the Lord turned and looked straight at Peter, and Peter remembered the word of the Lord, how he had said to him, “Before a rooster crows today, you will deny me three times.”'
EXEC add_BibleVerse @BibleId, 342022062, N'And he went outside and wept bitterly.'
EXEC add_BibleVerse @BibleId, 342022063, N'Now the men who were holding Jesus under guard began to mock him and beat him.'
EXEC add_BibleVerse @BibleId, 342022064, N'They blindfolded him and asked him repeatedly, “Prophesy! Who hit you?”'
EXEC add_BibleVerse @BibleId, 342022065, N'They also said many other things against him, reviling him.'
EXEC add_BibleVerse @BibleId, 342022066, N'When day came, the council of the elders of the people gathered together, both the chief priests and the experts in the law. Then they led Jesus away to their council'
EXEC add_BibleVerse @BibleId, 342022067, N'and said, “If you are the Christ, tell us.” But he said to them, “If I tell you, you will not believe,'
EXEC add_BibleVerse @BibleId, 342022068, N'and if I ask you, you will not answer.'
EXEC add_BibleVerse @BibleId, 342022069, N'But from now on the Son of Man will be seated at the right hand of the power of God.”'
EXEC add_BibleVerse @BibleId, 342022070, N'So they all said, “Are you the Son of God, then?” He answered them, “You say that I am.”'
EXEC add_BibleVerse @BibleId, 342022071, N'Then they said, “Why do we need further testimony? We have heard it ourselves from his own lips!”'
EXEC add_BibleVerse @BibleId, 342023001, N'Then the whole group of them rose up and brought Jesus before Pilate.'
EXEC add_BibleVerse @BibleId, 342023002, N'They began to accuse him, saying, “We found this man subverting our nation, forbidding us to pay the tribute tax to Caesar and claiming that he himself is Christ, a king.”'
EXEC add_BibleVerse @BibleId, 342023003, N'So Pilate asked Jesus, “Are you the king of the Jews?” He replied, “You say so.”'
EXEC add_BibleVerse @BibleId, 342023004, N'Then Pilate said to the chief priests and the crowds, “I find no basis for an accusation against this man.”'
EXEC add_BibleVerse @BibleId, 342023005, N'But they persisted in saying, “He incites the people by teaching throughout all Judea. It started in Galilee and ended up here!”'
EXEC add_BibleVerse @BibleId, 342023006, N'Now when Pilate heard this, he asked whether the man was a Galilean.'
EXEC add_BibleVerse @BibleId, 342023007, N'When he learned that he was from Herod’s jurisdiction, he sent him over to Herod, who also happened to be in Jerusalem at that time.'
EXEC add_BibleVerse @BibleId, 342023008, N'When Herod saw Jesus, he was very glad, for he had long desired to see him, because he had heard about him and was hoping to see him perform some miraculous sign.'
EXEC add_BibleVerse @BibleId, 342023009, N'So Herod questioned him at considerable length; Jesus gave him no answer.'
EXEC add_BibleVerse @BibleId, 342023010, N'The chief priests and the experts in the law were there, vehemently accusing him.'
EXEC add_BibleVerse @BibleId, 342023011, N'Even Herod with his soldiers treated him with contempt and mocked him. Then, dressing him in elegant clothes, Herod sent him back to Pilate.'
EXEC add_BibleVerse @BibleId, 342023012, N'That very day Herod and Pilate became friends with each other, for prior to this they had been enemies.'
EXEC add_BibleVerse @BibleId, 342023013, N'Then Pilate called together the chief priests, the rulers, and the people,'
EXEC add_BibleVerse @BibleId, 342023014, N'and said to them, “You brought me this man as one who was misleading the people. When I examined him before you, I did not find this man guilty of anything you accused him of doing.'
EXEC add_BibleVerse @BibleId, 342023015, N'Neither did Herod, for he sent him back to us. Look, he has done nothing deserving death.'
EXEC add_BibleVerse @BibleId, 342023016, N'I will therefore have him flogged and release him.”'
EXEC add_BibleVerse @BibleId, 342023018, N' But they all shouted out together, “Take this man away! Release Barabbas for us!”'
EXEC add_BibleVerse @BibleId, 342023019, N'(This was a man who had been thrown into prison for an insurrection started in the city, and for murder.)'
EXEC add_BibleVerse @BibleId, 342023020, N'Pilate addressed them once again because he wanted to release Jesus.'
EXEC add_BibleVerse @BibleId, 342023021, N'But they kept on shouting, “Crucify, crucify him!”'
EXEC add_BibleVerse @BibleId, 342023022, N'A third time he said to them, “Why? What wrong has he done? I have found him guilty of no crime deserving death. I will therefore flog him and release him.”'
EXEC add_BibleVerse @BibleId, 342023023, N'But they were insistent, demanding with loud shouts that he be crucified. And their shouts prevailed.'
EXEC add_BibleVerse @BibleId, 342023024, N'So Pilate decided that their demand should be granted.'
EXEC add_BibleVerse @BibleId, 342023025, N'He released the man they asked for, who had been thrown in prison for insurrection and murder. But he handed Jesus over to their will.'
EXEC add_BibleVerse @BibleId, 342023026, N'As they led him away, they seized Simon of Cyrene, who was coming in from the country. They placed the cross on his back and made him carry it behind Jesus.'
EXEC add_BibleVerse @BibleId, 342023027, N'A great number of the people followed him, among them women who were mourning and wailing for him.'
EXEC add_BibleVerse @BibleId, 342023028, N'But Jesus turned to them and said, “Daughters of Jerusalem, do not weep for me, but weep for yourselves and for your children.'
EXEC add_BibleVerse @BibleId, 342023029, N'For this is certain: The days are coming when they will say, ‘Blessed are the barren, the wombs that never bore children, and the breasts that never nursed!’'
EXEC add_BibleVerse @BibleId, 342023030, N'Then they will begin to say to the mountains, ‘Fall on us!’ and to the hills, ‘Cover us!’'
EXEC add_BibleVerse @BibleId, 342023031, N'For if such things are done when the wood is green, what will happen when it is dry?”'
EXEC add_BibleVerse @BibleId, 342023032, N'Two other criminals were also led away to be executed with him.'
EXEC add_BibleVerse @BibleId, 342023033, N'So when they came to the place that is called “The Skull,” they crucified him there, along with the criminals, one on his right and one on his left.'
EXEC add_BibleVerse @BibleId, 342023034, N'But Jesus said, “Father, forgive them, for they don’t know what they are doing.” Then they threw dice to divide his clothes.'
EXEC add_BibleVerse @BibleId, 342023035, N'The people also stood there watching, but the rulers ridiculed him, saying, “He saved others. Let him save himself if he is the Christ of God, his chosen one!”'
EXEC add_BibleVerse @BibleId, 342023036, N'The soldiers also mocked him, coming up and offering him sour wine,'
EXEC add_BibleVerse @BibleId, 342023037, N'and saying, “If you are the king of the Jews, save yourself!”'
EXEC add_BibleVerse @BibleId, 342023038, N'There was also an inscription over him, “This is the king of the Jews.”'
EXEC add_BibleVerse @BibleId, 342023039, N'One of the criminals who was hanging there railed at him, saying, “Aren’t you the Christ? Save yourself and us!”'
EXEC add_BibleVerse @BibleId, 342023040, N'But the other rebuked him, saying, “Don’t you fear God, since you are under the same sentence of condemnation?'
EXEC add_BibleVerse @BibleId, 342023041, N'And we rightly so, for we are getting what we deserve for what we did, but this man has done nothing wrong.”'
EXEC add_BibleVerse @BibleId, 342023042, N'Then he said, “Jesus, remember me when you come in your kingdom.”'
EXEC add_BibleVerse @BibleId, 342023043, N'And Jesus said to him, “I tell you the truth, today you will be with me in paradise.”'
EXEC add_BibleVerse @BibleId, 342023044, N'It was now about noon, and darkness came over the whole land until three in the afternoon,'
EXEC add_BibleVerse @BibleId, 342023045, N'because the sun’s light failed. The temple curtain was torn in two.'
EXEC add_BibleVerse @BibleId, 342023046, N'Then Jesus, calling out with a loud voice, said, “Father, into your hands I commit my spirit!” And after he said this he breathed his last.'
EXEC add_BibleVerse @BibleId, 342023047, N'Now when the centurion saw what had happened, he praised God and said, “Certainly this man was innocent!”'
EXEC add_BibleVerse @BibleId, 342023048, N'And all the crowds that had assembled for this spectacle, when they saw what had taken place, returned home beating their breasts.'
EXEC add_BibleVerse @BibleId, 342023049, N'And all those who knew Jesus stood at a distance, and the women who had followed him from Galilee saw these things.'
EXEC add_BibleVerse @BibleId, 342023050, N'Now there was a man named Joseph who was a member of the council, a good and righteous man.'
EXEC add_BibleVerse @BibleId, 342023051, N'(He had not consented to their plan and action.) He was from the Judean town of Arimathea, and was looking forward to the kingdom of God.'
EXEC add_BibleVerse @BibleId, 342023052, N'He went to Pilate and asked for the body of Jesus.'
EXEC add_BibleVerse @BibleId, 342023053, N'Then he took it down, wrapped it in a linen cloth, and placed it in a tomb cut out of the rock, where no one had yet been buried.'
EXEC add_BibleVerse @BibleId, 342023054, N'It was the day of preparation and the Sabbath was beginning.'
EXEC add_BibleVerse @BibleId, 342023055, N'The women who had accompanied Jesus from Galilee followed, and they saw the tomb and how his body was laid in it.'
EXEC add_BibleVerse @BibleId, 342023056, N'Then they returned and prepared aromatic spices and perfumes. On the Sabbath they rested according to the commandment.'
EXEC add_BibleVerse @BibleId, 342024001, N'Now on the first day of the week, at early dawn, the women went to the tomb, taking the aromatic spices they had prepared.'
EXEC add_BibleVerse @BibleId, 342024002, N'They found that the stone had been rolled away from the tomb,'
EXEC add_BibleVerse @BibleId, 342024003, N'but when they went in, they did not find the body of the Lord Jesus.'
EXEC add_BibleVerse @BibleId, 342024004, N'While they were perplexed about this, suddenly two men stood beside them in dazzling attire.'
EXEC add_BibleVerse @BibleId, 342024005, N'The women were terribly frightened and bowed their faces to the ground, but the men said to them, “Why do you look for the living among the dead?'
EXEC add_BibleVerse @BibleId, 342024006, N'He is not here, but has been raised! Remember how he told you, while he was still in Galilee,'
EXEC add_BibleVerse @BibleId, 342024007, N'that the Son of Man must be delivered into the hands of sinful men, and be crucified, and on the third day rise again.”'
EXEC add_BibleVerse @BibleId, 342024008, N'Then the women remembered his words,'
EXEC add_BibleVerse @BibleId, 342024009, N'and when they returned from the tomb they told all these things to the eleven and to all the rest.'
EXEC add_BibleVerse @BibleId, 342024010, N'Now it was Mary Magdalene, Joanna, Mary the mother of James, and the other women with them who told these things to the apostles.'
EXEC add_BibleVerse @BibleId, 342024011, N'But these words seemed like pure nonsense to them, and they did not believe them.'
EXEC add_BibleVerse @BibleId, 342024012, N'But Peter got up and ran to the tomb. He bent down and saw only the strips of linen cloth; then he went home, wondering what had happened.'
EXEC add_BibleVerse @BibleId, 342024013, N'Now that very day two of them were on their way to a village called Emmaus, about seven miles from Jerusalem.'
EXEC add_BibleVerse @BibleId, 342024014, N'They were talking to each other about all the things that had happened.'
EXEC add_BibleVerse @BibleId, 342024015, N'While they were talking and debating these things, Jesus himself approached and began to accompany them'
EXEC add_BibleVerse @BibleId, 342024016, N'(but their eyes were kept from recognizing him).'
EXEC add_BibleVerse @BibleId, 342024017, N'Then he said to them, “What are these matters you are discussing so intently as you walk along?” And they stood still, looking sad.'
EXEC add_BibleVerse @BibleId, 342024018, N'Then one of them, named Cleopas, answered him, “Are you the only visitor to Jerusalem who doesn’t know the things that have happened there in these days?”'
EXEC add_BibleVerse @BibleId, 342024019, N'He said to them, “What things?” “The things concerning Jesus the Nazarene,” they replied, “a man who, with his powerful deeds and words, proved to be a prophet before God and all the people;'
EXEC add_BibleVerse @BibleId, 342024020, N'and how our chief priests and rulers handed him over to be condemned to death, and crucified him.'
EXEC add_BibleVerse @BibleId, 342024021, N'But we had hoped that he was the one who was going to redeem Israel. Not only this, but it is now the third day since these things happened.'
EXEC add_BibleVerse @BibleId, 342024022, N'Furthermore, some women of our group amazed us. They were at the tomb early this morning,'
EXEC add_BibleVerse @BibleId, 342024023, N'and when they did not find his body, they came back and said they had seen a vision of angels, who said he was alive.'
EXEC add_BibleVerse @BibleId, 342024024, N'Then some of those who were with us went to the tomb, and found it just as the women had said, but they did not see him.”'
EXEC add_BibleVerse @BibleId, 342024025, N'So he said to them, “You foolish people – how slow of heart to believe all that the prophets have spoken!'
EXEC add_BibleVerse @BibleId, 342024026, N'Wasn’t it necessary for the Christ to suffer these things and enter into his glory?”'
EXEC add_BibleVerse @BibleId, 342024027, N'Then beginning with Moses and all the prophets, he interpreted to them the things written about himself in all the scriptures.'
EXEC add_BibleVerse @BibleId, 342024028, N'So they approached the village where they were going. He acted as though he wanted to go farther,'
EXEC add_BibleVerse @BibleId, 342024029, N'but they urged him, “Stay with us, because it is getting toward evening and the day is almost done.” So he went in to stay with them.'
EXEC add_BibleVerse @BibleId, 342024030, N'When he had taken his place at the table with them, he took the bread, blessed and broke it, and gave it to them.'
EXEC add_BibleVerse @BibleId, 342024031, N'At this point their eyes were opened and they recognized him. Then he vanished out of their sight.'
EXEC add_BibleVerse @BibleId, 342024032, N'They said to each other, “Didn’t our hearts burn within us while he was speaking with us on the road, while he was explaining the scriptures to us?”'
EXEC add_BibleVerse @BibleId, 342024033, N'So they got up that very hour and returned to Jerusalem. They found the eleven and those with them gathered together'
EXEC add_BibleVerse @BibleId, 342024034, N'and saying, “The Lord has really risen, and has appeared to Simon!”'
EXEC add_BibleVerse @BibleId, 342024035, N'Then they told what had happened on the road, and how they recognized him when he broke the bread.'
EXEC add_BibleVerse @BibleId, 342024036, N'While they were saying these things, Jesus himself stood among them and said to them, “Peace be with you.”'
EXEC add_BibleVerse @BibleId, 342024037, N'But they were startled and terrified, thinking they saw a ghost.'
EXEC add_BibleVerse @BibleId, 342024038, N'Then he said to them, “Why are you frightened, and why do doubts arise in your hearts?'
EXEC add_BibleVerse @BibleId, 342024039, N'Look at my hands and my feet; it’s me! Touch me and see; a ghost does not have flesh and bones like you see I have.”'
EXEC add_BibleVerse @BibleId, 342024040, N'When he had said this, he showed them his hands and his feet.'
EXEC add_BibleVerse @BibleId, 342024041, N'And while they still could not believe it (because of their joy) and were amazed, he said to them, “Do you have anything here to eat?”'
EXEC add_BibleVerse @BibleId, 342024042, N'So they gave him a piece of broiled fish,'
EXEC add_BibleVerse @BibleId, 342024043, N'and he took it and ate it in front of them.'
EXEC add_BibleVerse @BibleId, 342024044, N'Then he said to them, “These are my words that I spoke to you while I was still with you, that everything written about me in the law of Moses and the prophets and the psalms must be fulfilled.”'
EXEC add_BibleVerse @BibleId, 342024045, N'Then he opened their minds so they could understand the scriptures,'
EXEC add_BibleVerse @BibleId, 342024046, N'and said to them, “Thus it stands written that the Christ would suffer and would rise from the dead on the third day,'
EXEC add_BibleVerse @BibleId, 342024047, N'and repentance for the forgiveness of sins would be proclaimed in his name to all nations, beginning from Jerusalem.'
EXEC add_BibleVerse @BibleId, 342024048, N'You are witnesses of these things.'
EXEC add_BibleVerse @BibleId, 342024049, N'And look, I am sending you what my Father promised. But stay in the city until you have been clothed with power from on high.”'
EXEC add_BibleVerse @BibleId, 342024050, N'Then Jesus led them out as far as Bethany, and lifting up his hands, he blessed them.'
EXEC add_BibleVerse @BibleId, 342024051, N'Now during the blessing he departed and was taken up into heaven.'
EXEC add_BibleVerse @BibleId, 342024052, N'So they worshiped him and returned to Jerusalem with great joy,'
EXEC add_BibleVerse @BibleId, 342024053, N'and were continually in the temple courts blessing God.'
EXEC add_BibleVerse @BibleId, 343001001, N'In the beginning was the Word, and the Word was with God, and the Word was fully God.'
EXEC add_BibleVerse @BibleId, 343001002, N'The Word was with God in the beginning.'
EXEC add_BibleVerse @BibleId, 343001003, N'All things were created by him, and apart from him not one thing was created that has been created.'
EXEC add_BibleVerse @BibleId, 343001004, N'In him was life, and the life was the light of mankind.'
EXEC add_BibleVerse @BibleId, 343001005, N'And the light shines on in the darkness, but the darkness has not mastered it.'
EXEC add_BibleVerse @BibleId, 343001006, N'A man came, sent from God, whose name was John.'
EXEC add_BibleVerse @BibleId, 343001007, N'He came as a witness to testify about the light, so that everyone might believe through him.'
EXEC add_BibleVerse @BibleId, 343001008, N'He himself was not the light, but he came to testify about the light.'
EXEC add_BibleVerse @BibleId, 343001009, N'The true light, who gives light to everyone, was coming into the world.'
EXEC add_BibleVerse @BibleId, 343001010, N'He was in the world, and the world was created by him, but the world did not recognize him.'
EXEC add_BibleVerse @BibleId, 343001011, N'He came to what was his own, but his own people did not receive him.'
EXEC add_BibleVerse @BibleId, 343001012, N'But to all who have received him – those who believe in his name – he has given the right to become God’s children'
EXEC add_BibleVerse @BibleId, 343001013, N'– children not born by human parents or by human desire or a husband’s decision, but by God.'
EXEC add_BibleVerse @BibleId, 343001014, N'Now the Word became flesh and took up residence among us. We saw his glory – the glory of the one and only, full of grace and truth, who came from the Father.'
EXEC add_BibleVerse @BibleId, 343001015, N'John testified about him and shouted out, “This one was the one about whom I said, ‘He who comes after me is greater than I am, because he existed before me.’”'
EXEC add_BibleVerse @BibleId, 343001016, N'For we have all received from his fullness one gracious gift after another.'
EXEC add_BibleVerse @BibleId, 343001017, N'For the law was given through Moses, but grace and truth came about through Jesus Christ.'
EXEC add_BibleVerse @BibleId, 343001018, N'No one has ever seen God. The only one, himself God, who is in closest fellowship with the Father, has made God known.'
EXEC add_BibleVerse @BibleId, 343001019, N'Now this was John’s testimony when the Jewish leaders sent priests and Levites from Jerusalem to ask him, “Who are you?”'
EXEC add_BibleVerse @BibleId, 343001020, N'He confessed – he did not deny but confessed – “I am not the Christ!”'
EXEC add_BibleVerse @BibleId, 343001021, N'So they asked him, “Then who are you? Are you Elijah?” He said, “I am not!” “Are you the Prophet?” He answered, “No!”'
EXEC add_BibleVerse @BibleId, 343001022, N'Then they said to him, “Who are you? Tell us so that we can give an answer to those who sent us. What do you say about yourself?”'
EXEC add_BibleVerse @BibleId, 343001023, N'John said, “I am the voice of one shouting in the wilderness, ‘Make straight the way for the Lord,’ as Isaiah the prophet said.”'
EXEC add_BibleVerse @BibleId, 343001024, N'(Now they had been sent from the Pharisees. )'
EXEC add_BibleVerse @BibleId, 343001025, N'So they asked John, “Why then are you baptizing if you are not the Christ, nor Elijah, nor the Prophet?”'
EXEC add_BibleVerse @BibleId, 343001026, N'John answered them, “I baptize with water. Among you stands one whom you do not recognize,'
EXEC add_BibleVerse @BibleId, 343001027, N'who is coming after me. I am not worthy to untie the strap of his sandal!”'
EXEC add_BibleVerse @BibleId, 343001028, N'These things happened in Bethany across the Jordan River where John was baptizing.'
EXEC add_BibleVerse @BibleId, 343001029, N'On the next day John saw Jesus coming toward him and said, “Look, the Lamb of God who takes away the sin of the world!'
EXEC add_BibleVerse @BibleId, 343001030, N'This is the one about whom I said, ‘After me comes a man who is greater than I am, because he existed before me.’'
EXEC add_BibleVerse @BibleId, 343001031, N'I did not recognize him, but I came baptizing with water so that he could be revealed to Israel.”'
EXEC add_BibleVerse @BibleId, 343001032, N'Then John testified, “I saw the Spirit descending like a dove from heaven, and it remained on him.'
EXEC add_BibleVerse @BibleId, 343001033, N'And I did not recognize him, but the one who sent me to baptize with water said to me, ‘The one on whom you see the Spirit descending and remaining – this is the one who baptizes with the Holy Spirit.’'
EXEC add_BibleVerse @BibleId, 343001034, N'I have both seen and testified that this man is the Chosen One of God.”'
EXEC add_BibleVerse @BibleId, 343001035, N'Again the next day John was standing there with two of his disciples.'
EXEC add_BibleVerse @BibleId, 343001036, N'Gazing at Jesus as he walked by, he said, “Look, the Lamb of God!”'
EXEC add_BibleVerse @BibleId, 343001037, N'When John’s two disciples heard him say this, they followed Jesus.'
EXEC add_BibleVerse @BibleId, 343001038, N'Jesus turned around and saw them following and said to them, “What do you want?” So they said to him, “Rabbi” (which is translated Teacher), “where are you staying?”'
EXEC add_BibleVerse @BibleId, 343001039, N'Jesus answered, “Come and you will see.” So they came and saw where he was staying, and they stayed with him that day. Now it was about four o’clock in the afternoon.'
EXEC add_BibleVerse @BibleId, 343001040, N'Andrew, the brother of Simon Peter, was one of the two disciples who heard what John said and followed Jesus.'
EXEC add_BibleVerse @BibleId, 343001041, N'He first found his own brother Simon and told him, “We have found the Messiah!” (which is translated Christ).'
EXEC add_BibleVerse @BibleId, 343001042, N'Andrew brought Simon to Jesus. Jesus looked at him and said, “You are Simon, the son of John. You will be called Cephas” (which is translated Peter).'
EXEC add_BibleVerse @BibleId, 343001043, N'On the next day Jesus wanted to set out for Galilee. He found Philip and said to him, “Follow me.”'
EXEC add_BibleVerse @BibleId, 343001044, N'(Now Philip was from Bethsaida, the town of Andrew and Peter.)'
EXEC add_BibleVerse @BibleId, 343001045, N'Philip found Nathanael and told him, “We have found the one Moses wrote about in the law, and the prophets also wrote about – Jesus of Nazareth, the son of Joseph.”'
EXEC add_BibleVerse @BibleId, 343001046, N'Nathanael replied, “Can anything good come out of Nazareth?” Philip replied, “Come and see.”'
EXEC add_BibleVerse @BibleId, 343001047, N'Jesus saw Nathanael coming toward him and exclaimed, “Look, a true Israelite in whom there is no deceit!”'
EXEC add_BibleVerse @BibleId, 343001048, N'Nathanael asked him, “How do you know me?” Jesus replied, “Before Philip called you, when you were under the fig tree, I saw you.”'
EXEC add_BibleVerse @BibleId, 343001049, N'Nathanael answered him, “Rabbi, you are the Son of God; you are the king of Israel!”'
EXEC add_BibleVerse @BibleId, 343001050, N'Jesus said to him, “Because I told you that I saw you under the fig tree, do you believe? You will see greater things than these.”'
EXEC add_BibleVerse @BibleId, 343001051, N'He continued, “I tell all of you the solemn truth – you will see heaven opened and the angels of God ascending and descending on the Son of Man.”'
EXEC add_BibleVerse @BibleId, 343002001, N'Now on the third day there was a wedding at Cana in Galilee. Jesus’ mother was there,'
EXEC add_BibleVerse @BibleId, 343002002, N'and Jesus and his disciples were also invited to the wedding.'
EXEC add_BibleVerse @BibleId, 343002003, N'When the wine ran out, Jesus’ mother said to him, “They have no wine left.”'
EXEC add_BibleVerse @BibleId, 343002004, N'Jesus replied, “Woman, why are you saying this to me? My time has not yet come.”'
EXEC add_BibleVerse @BibleId, 343002005, N'His mother told the servants, “Whatever he tells you, do it.”'
EXEC add_BibleVerse @BibleId, 343002006, N'Now there were six stone water jars there for Jewish ceremonial washing, each holding twenty or thirty gallons.'
EXEC add_BibleVerse @BibleId, 343002007, N'Jesus told the servants, “Fill the water jars with water.” So they filled them up to the very top.'
EXEC add_BibleVerse @BibleId, 343002008, N'Then he told them, “Now draw some out and take it to the head steward,” and they did.'
EXEC add_BibleVerse @BibleId, 343002009, N'When the head steward tasted the water that had been turned to wine, not knowing where it came from (though the servants who had drawn the water knew), he called the bridegroom'
EXEC add_BibleVerse @BibleId, 343002010, N'and said to him, “Everyone serves the good wine first, and then the cheaper wine when the guests are drunk. You have kept the good wine until now!”'
EXEC add_BibleVerse @BibleId, 343002011, N'Jesus did this as the first of his miraculous signs, in Cana of Galilee. In this way he revealed his glory, and his disciples believed in him.'
EXEC add_BibleVerse @BibleId, 343002012, N'After this he went down to Capernaum with his mother and brothers and his disciples, and they stayed there a few days.'
EXEC add_BibleVerse @BibleId, 343002013, N'Now the Jewish feast of Passover was near, so Jesus went up to Jerusalem.'
EXEC add_BibleVerse @BibleId, 343002014, N'He found in the temple courts those who were selling oxen and sheep and doves, and the money changers sitting at tables.'
EXEC add_BibleVerse @BibleId, 343002015, N'So he made a whip of cords and drove them all out of the temple courts, with the sheep and the oxen. He scattered the coins of the money changers and overturned their tables.'
EXEC add_BibleVerse @BibleId, 343002016, N'To those who sold the doves he said, “Take these things away from here! Do not make my Father’s house a marketplace!”'
EXEC add_BibleVerse @BibleId, 343002017, N'His disciples remembered that it was written, “ Zeal for your house will devour me.”'
EXEC add_BibleVerse @BibleId, 343002018, N'So then the Jewish leaders responded, “What sign can you show us, since you are doing these things?”'
EXEC add_BibleVerse @BibleId, 343002019, N'Jesus replied, “Destroy this temple and in three days I will raise it up again.”'
EXEC add_BibleVerse @BibleId, 343002020, N'Then the Jewish leaders said to him, “This temple has been under construction for forty-six years, and are you going to raise it up in three days?”'
EXEC add_BibleVerse @BibleId, 343002021, N'But Jesus was speaking about the temple of his body.'
EXEC add_BibleVerse @BibleId, 343002022, N'So after he was raised from the dead, his disciples remembered that he had said this, and they believed the scripture and the saying that Jesus had spoken.'
EXEC add_BibleVerse @BibleId, 343002023, N'Now while Jesus was in Jerusalem at the feast of the Passover, many people believed in his name because they saw the miraculous signs he was doing.'
EXEC add_BibleVerse @BibleId, 343002024, N'But Jesus would not entrust himself to them, because he knew all people.'
EXEC add_BibleVerse @BibleId, 343002025, N'He did not need anyone to testify about man, for he knew what was in man.'
EXEC add_BibleVerse @BibleId, 343003001, N'Now a certain man, a Pharisee named Nicodemus, who was a member of the Jewish ruling council,'
EXEC add_BibleVerse @BibleId, 343003002, N'came to Jesus at night and said to him, “Rabbi, we know that you are a teacher who has come from God. For no one could perform the miraculous signs that you do unless God is with him.”'
EXEC add_BibleVerse @BibleId, 343003003, N'Jesus replied, “I tell you the solemn truth, unless a person is born from above, he cannot see the kingdom of God.”'
EXEC add_BibleVerse @BibleId, 343003004, N'Nicodemus said to him, “How can a man be born when he is old? He cannot enter his mother’s womb and be born a second time, can he?”'
EXEC add_BibleVerse @BibleId, 343003005, N'Jesus answered, “I tell you the solemn truth, unless a person is born of water and spirit, he cannot enter the kingdom of God.'
EXEC add_BibleVerse @BibleId, 343003006, N'What is born of the flesh is flesh, and what is born of the Spirit is spirit.'
EXEC add_BibleVerse @BibleId, 343003007, N'Do not be amazed that I said to you, ‘You must all be born from above.’'
EXEC add_BibleVerse @BibleId, 343003008, N'The wind blows wherever it will, and you hear the sound it makes, but do not know where it comes from and where it is going. So it is with everyone who is born of the Spirit.”'
EXEC add_BibleVerse @BibleId, 343003009, N'Nicodemus replied, “How can these things be?”'
EXEC add_BibleVerse @BibleId, 343003010, N'Jesus answered, “Are you the teacher of Israel and yet you don’t understand these things?'
EXEC add_BibleVerse @BibleId, 343003011, N'I tell you the solemn truth, we speak about what we know and testify about what we have seen, but you people do not accept our testimony.'
EXEC add_BibleVerse @BibleId, 343003012, N'If I have told you people about earthly things and you don’t believe, how will you believe if I tell you about heavenly things?'
EXEC add_BibleVerse @BibleId, 343003013, N'No one has ascended into heaven except the one who descended from heaven – the Son of Man.'
EXEC add_BibleVerse @BibleId, 343003014, N'Just as Moses lifted up the serpent in the wilderness, so must the Son of Man be lifted up,'
EXEC add_BibleVerse @BibleId, 343003015, N'so that everyone who believes in him may have eternal life.”'
EXEC add_BibleVerse @BibleId, 343003016, N'For this is the way God loved the world: He gave his one and only Son, so that everyone who believes in him will not perish but have eternal life.'
EXEC add_BibleVerse @BibleId, 343003017, N'For God did not send his Son into the world to condemn the world, but that the world should be saved through him.'
EXEC add_BibleVerse @BibleId, 343003018, N'The one who believes in him is not condemned. The one who does not believe has been condemned already, because he has not believed in the name of the one and only Son of God.'
EXEC add_BibleVerse @BibleId, 343003019, N'Now this is the basis for judging: that the light has come into the world and people loved the darkness rather than the light, because their deeds were evil.'
EXEC add_BibleVerse @BibleId, 343003020, N'For everyone who does evil deeds hates the light and does not come to the light, so that their deeds will not be exposed.'
EXEC add_BibleVerse @BibleId, 343003021, N'But the one who practices the truth comes to the light, so that it may be plainly evident that his deeds have been done in God.'
EXEC add_BibleVerse @BibleId, 343003022, N'After this, Jesus and his disciples came into Judean territory, and there he spent time with them and was baptizing.'
EXEC add_BibleVerse @BibleId, 343003023, N'John was also baptizing at Aenon near Salim, because water was plentiful there, and people were coming to him and being baptized.'
EXEC add_BibleVerse @BibleId, 343003024, N'(For John had not yet been thrown into prison.)'
EXEC add_BibleVerse @BibleId, 343003025, N'Now a dispute came about between some of John’s disciples and a certain Jew concerning ceremonial washing.'
EXEC add_BibleVerse @BibleId, 343003026, N'So they came to John and said to him, “Rabbi, the one who was with you on the other side of the Jordan River, about whom you testified – see, he is baptizing, and everyone is flocking to him!”'
EXEC add_BibleVerse @BibleId, 343003027, N'John replied, “No one can receive anything unless it has been given to him from heaven.'
EXEC add_BibleVerse @BibleId, 343003028, N'You yourselves can testify that I said, ‘I am not the Christ,’ but rather, ‘I have been sent before him.’'
EXEC add_BibleVerse @BibleId, 343003029, N'The one who has the bride is the bridegroom. The friend of the bridegroom, who stands by and listens for him, rejoices greatly when he hears the bridegroom’s voice. This then is my joy, and it is complete.'
EXEC add_BibleVerse @BibleId, 343003030, N'He must become more important while I become less important.”'
EXEC add_BibleVerse @BibleId, 343003031, N'The one who comes from above is superior to all. The one who is from the earth belongs to the earth and speaks about earthly things. The one who comes from heaven is superior to all.'
EXEC add_BibleVerse @BibleId, 343003032, N'He testifies about what he has seen and heard, but no one accepts his testimony.'
EXEC add_BibleVerse @BibleId, 343003033, N'The one who has accepted his testimony has confirmed clearly that God is truthful.'
EXEC add_BibleVerse @BibleId, 343003034, N'For the one whom God has sent speaks the words of God, for he does not give the Spirit sparingly.'
EXEC add_BibleVerse @BibleId, 343003035, N'The Father loves the Son and has placed all things under his authority.'
EXEC add_BibleVerse @BibleId, 343003036, N'The one who believes in the Son has eternal life. The one who rejects the Son will not see life, but God’s wrath remains on him.'
EXEC add_BibleVerse @BibleId, 343004001, N'Now when Jesus knew that the Pharisees had heard that he was winning and baptizing more disciples than John'
EXEC add_BibleVerse @BibleId, 343004002, N'(although Jesus himself was not baptizing, but his disciples were),'
EXEC add_BibleVerse @BibleId, 343004003, N'he left Judea and set out once more for Galilee.'
EXEC add_BibleVerse @BibleId, 343004004, N'But he had to pass through Samaria.'
EXEC add_BibleVerse @BibleId, 343004005, N'Now he came to a Samaritan town called Sychar, near the plot of land that Jacob had given to his son Joseph.'
EXEC add_BibleVerse @BibleId, 343004006, N'Jacob’s well was there, so Jesus, since he was tired from the journey, sat right down beside the well. It was about noon.'
EXEC add_BibleVerse @BibleId, 343004007, N'A Samaritan woman came to draw water. Jesus said to her, “Give me some water to drink.”'
EXEC add_BibleVerse @BibleId, 343004008, N'(For his disciples had gone off into the town to buy supplies. )'
EXEC add_BibleVerse @BibleId, 343004009, N'So the Samaritan woman said to him, “How can you – a Jew – ask me, a Samaritan woman, for water to drink?” (For Jews use nothing in common with Samaritans.)'
EXEC add_BibleVerse @BibleId, 343004010, N'Jesus answered her, “If you had known the gift of God and who it is who said to you, ‘Give me some water to drink,’ you would have asked him, and he would have given you living water.”'
EXEC add_BibleVerse @BibleId, 343004011, N'“Sir,” the woman said to him, “you have no bucket and the well is deep; where then do you get this living water?'
EXEC add_BibleVerse @BibleId, 343004012, N'Surely you’re not greater than our ancestor Jacob, are you? For he gave us this well and drank from it himself, along with his sons and his livestock.”'
EXEC add_BibleVerse @BibleId, 343004013, N'Jesus replied, “Everyone who drinks some of this water will be thirsty again.'
EXEC add_BibleVerse @BibleId, 343004014, N'But whoever drinks some of the water that I will give him will never be thirsty again, but the water that I will give him will become in him a fountain of water springing up to eternal life.”'
EXEC add_BibleVerse @BibleId, 343004015, N'The woman said to him, “Sir, give me this water, so that I will not be thirsty or have to come here to draw water.”'
EXEC add_BibleVerse @BibleId, 343004016, N'He said to her, “Go call your husband and come back here.”'
EXEC add_BibleVerse @BibleId, 343004017, N'The woman replied, “I have no husband.” Jesus said to her, “Right you are when you said, ‘I have no husband,’'
EXEC add_BibleVerse @BibleId, 343004018, N'for you have had five husbands, and the man you are living with now is not your husband. This you said truthfully!”'
EXEC add_BibleVerse @BibleId, 343004019, N'The woman said to him, “Sir, I see that you are a prophet.'
EXEC add_BibleVerse @BibleId, 343004020, N'Our fathers worshiped on this mountain, and you people say that the place where people must worship is in Jerusalem.”'
EXEC add_BibleVerse @BibleId, 343004021, N'Jesus said to her, “Believe me, woman, a time is coming when you will worship the Father neither on this mountain nor in Jerusalem.'
EXEC add_BibleVerse @BibleId, 343004022, N'You people worship what you do not know. We worship what we know, because salvation is from the Jews.'
EXEC add_BibleVerse @BibleId, 343004023, N'But a time is coming – and now is here – when the true worshipers will worship the Father in spirit and truth, for the Father seeks such people to be his worshipers.'
EXEC add_BibleVerse @BibleId, 343004024, N'God is spirit, and the people who worship him must worship in spirit and truth.”'
EXEC add_BibleVerse @BibleId, 343004025, N'The woman said to him, “I know that Messiah is coming” (the one called Christ); “whenever he comes, he will tell us everything.”'
EXEC add_BibleVerse @BibleId, 343004026, N'Jesus said to her, “I, the one speaking to you, am he.”'
EXEC add_BibleVerse @BibleId, 343004027, N'Now at that very moment his disciples came back. They were shocked because he was speaking with a woman. However, no one said, “What do you want?” or “Why are you speaking with her?”'
EXEC add_BibleVerse @BibleId, 343004028, N'Then the woman left her water jar, went off into the town and said to the people,'
EXEC add_BibleVerse @BibleId, 343004029, N'“Come, see a man who told me everything I ever did. Surely he can’t be the Messiah, can he?”'
EXEC add_BibleVerse @BibleId, 343004030, N'So they left the town and began coming to him.'
EXEC add_BibleVerse @BibleId, 343004031, N'Meanwhile the disciples were urging him, “Rabbi, eat something.”'
EXEC add_BibleVerse @BibleId, 343004032, N'But he said to them, “I have food to eat that you know nothing about.”'
EXEC add_BibleVerse @BibleId, 343004033, N'So the disciples began to say to one another, “No one brought him anything to eat, did they?”'
EXEC add_BibleVerse @BibleId, 343004034, N'Jesus said to them, “My food is to do the will of the one who sent me and to complete his work.'
EXEC add_BibleVerse @BibleId, 343004035, N'Don’t you say, ‘There are four more months and then comes the harvest?’ I tell you, look up and see that the fields are already white for harvest!'
EXEC add_BibleVerse @BibleId, 343004036, N'The one who reaps receives pay and gathers fruit for eternal life, so that the one who sows and the one who reaps can rejoice together.'
EXEC add_BibleVerse @BibleId, 343004037, N'For in this instance the saying is true, ‘One sows and another reaps.’'
EXEC add_BibleVerse @BibleId, 343004038, N'I sent you to reap what you did not work for; others have labored and you have entered into their labor.”'
EXEC add_BibleVerse @BibleId, 343004039, N'Now many Samaritans from that town believed in him because of the report of the woman who testified, “He told me everything I ever did.”'
EXEC add_BibleVerse @BibleId, 343004040, N'So when the Samaritans came to him, they began asking him to stay with them. He stayed there two days,'
EXEC add_BibleVerse @BibleId, 343004041, N'and because of his word many more believed.'
EXEC add_BibleVerse @BibleId, 343004042, N'They said to the woman, “No longer do we believe because of your words, for we have heard for ourselves, and we know that this one really is the Savior of the world.”'
EXEC add_BibleVerse @BibleId, 343004043, N'After the two days he departed from there to Galilee.'
EXEC add_BibleVerse @BibleId, 343004044, N'(For Jesus himself had testified that a prophet has no honor in his own country.)'
EXEC add_BibleVerse @BibleId, 343004045, N'So when he came to Galilee, the Galileans welcomed him because they had seen all the things he had done in Jerusalem at the feast (for they themselves had gone to the feast).'
EXEC add_BibleVerse @BibleId, 343004046, N'Now he came again to Cana there was a certain royal official whose son was sick.'
EXEC add_BibleVerse @BibleId, 343004047, N'When he heard that Jesus had come back from Judea to Galilee, he went to him and begged him to come down and heal his son, who was about to die.'
EXEC add_BibleVerse @BibleId, 343004048, N'So Jesus said to him, “Unless you people see signs and wonders you will never believe!”'
EXEC add_BibleVerse @BibleId, 343004049, N'“Sir,” the official said to him, “come down before my child dies.”'
EXEC add_BibleVerse @BibleId, 343004050, N'Jesus told him, “Go home; your son will live.” The man believed the word that Jesus spoke to him, and set off for home.'
EXEC add_BibleVerse @BibleId, 343004051, N'While he was on his way down, his slaves met him and told him that his son was going to live.'
EXEC add_BibleVerse @BibleId, 343004052, N'So he asked them the time when his condition began to improve, and they told him, “Yesterday at one o’clock in the afternoon the fever left him.”'
EXEC add_BibleVerse @BibleId, 343004053, N'Then the father realized that it was the very time Jesus had said to him, “Your son will live,” and he himself believed along with his entire household.'
EXEC add_BibleVerse @BibleId, 343004054, N'Jesus did this as his second miraculous sign when he returned from Judea to Galilee.'
EXEC add_BibleVerse @BibleId, 343005001, N'After this there was a Jewish feast, and Jesus went up to Jerusalem.'
EXEC add_BibleVerse @BibleId, 343005002, N'Now there is in Jerusalem by the Sheep Gate a pool called Bethzatha in Aramaic, which has five covered walkways.'
EXEC add_BibleVerse @BibleId, 343005003, N'A great number of sick, blind, lame, and paralyzed people were lying in these walkways.'
EXEC add_BibleVerse @BibleId, 343005005, N' Now a man was there who had been disabled for thirty-eight years.'
EXEC add_BibleVerse @BibleId, 343005006, N'When Jesus saw him lying there and when he realized that the man had been disabled a long time already, he said to him, “Do you want to become well?”'
EXEC add_BibleVerse @BibleId, 343005007, N'The sick man answered him, “Sir, I have no one to put me into the pool when the water is stirred up. While I am trying to get into the water, someone else goes down there before me.”'
EXEC add_BibleVerse @BibleId, 343005008, N'Jesus said to him, “Stand up! Pick up your mat and walk.”'
EXEC add_BibleVerse @BibleId, 343005009, N'Immediately the man was healed, and he picked up his mat and started walking. (Now that day was a Sabbath.)'
EXEC add_BibleVerse @BibleId, 343005010, N'So the Jewish leaders said to the man who had been healed, “It is the Sabbath, and you are not permitted to carry your mat.”'
EXEC add_BibleVerse @BibleId, 343005011, N'But he answered them, “The man who made me well said to me, ‘Pick up your mat and walk.’”'
EXEC add_BibleVerse @BibleId, 343005012, N'They asked him, “Who is the man who said to you, ‘Pick up your mat and walk’?”'
EXEC add_BibleVerse @BibleId, 343005013, N'But the man who had been healed did not know who it was, for Jesus had slipped out, since there was a crowd in that place.'
EXEC add_BibleVerse @BibleId, 343005014, N'After this Jesus found him at the temple and said to him, “Look, you have become well. Don’t sin any more, lest anything worse happen to you.”'
EXEC add_BibleVerse @BibleId, 343005015, N'The man went away and informed the Jewish leaders that Jesus was the one who had made him well.'
EXEC add_BibleVerse @BibleId, 343005016, N'Now because Jesus was doing these things on the Sabbath, the Jewish leaders began persecuting him.'
EXEC add_BibleVerse @BibleId, 343005017, N'So he told them, “My Father is working until now, and I too am working.”'
EXEC add_BibleVerse @BibleId, 343005018, N'For this reason the Jewish leaders were trying even harder to kill him, because not only was he breaking the Sabbath, but he was also calling God his own Father, thus making himself equal with God.'
EXEC add_BibleVerse @BibleId, 343005019, N'So Jesus answered them, “I tell you the solemn truth, the Son can do nothing on his own initiative, but only what he sees the Father doing. For whatever the Father does, the Son does likewise.'
EXEC add_BibleVerse @BibleId, 343005020, N'For the Father loves the Son and shows him everything he does, and will show him greater deeds than these, so that you will be amazed.'
EXEC add_BibleVerse @BibleId, 343005021, N'For just as the Father raises the dead and gives them life, so also the Son gives life to whomever he wishes.'
EXEC add_BibleVerse @BibleId, 343005022, N'Furthermore, the Father does not judge anyone, but has assigned all judgment to the Son,'
EXEC add_BibleVerse @BibleId, 343005023, N'so that all people will honor the Son just as they honor the Father. The one who does not honor the Son does not honor the Father who sent him.'
EXEC add_BibleVerse @BibleId, 343005024, N'“I tell you the solemn truth, the one who hears my message and believes the one who sent me has eternal life and will not be condemned, but has crossed over from death to life.'
EXEC add_BibleVerse @BibleId, 343005025, N'I tell you the solemn truth, a time is coming – and is now here – when the dead will hear the voice of the Son of God, and those who hear will live.'
EXEC add_BibleVerse @BibleId, 343005026, N'For just as the Father has life in himself, thus he has granted the Son to have life in himself,'
EXEC add_BibleVerse @BibleId, 343005027, N'and he has granted the Son authority to execute judgment, because he is the Son of Man.'
EXEC add_BibleVerse @BibleId, 343005028, N'“Do not be amazed at this, because a time is coming when all who are in the tombs will hear his voice'
EXEC add_BibleVerse @BibleId, 343005029, N'and will come out – the ones who have done what is good to the resurrection resulting in life, and the ones who have done what is evil to the resurrection resulting in condemnation.'
EXEC add_BibleVerse @BibleId, 343005030, N'I can do nothing on my own initiative. Just as I hear, I judge, and my judgment is just, because I do not seek my own will, but the will of the one who sent me.'
EXEC add_BibleVerse @BibleId, 343005031, N'“If I testify about myself, my testimony is not true.'
EXEC add_BibleVerse @BibleId, 343005032, N'There is another who testifies about me, and I know the testimony he testifies about me is true.'
EXEC add_BibleVerse @BibleId, 343005033, N'You have sent to John, and he has testified to the truth.'
EXEC add_BibleVerse @BibleId, 343005034, N'(I do not accept human testimony, but I say this so that you may be saved.)'
EXEC add_BibleVerse @BibleId, 343005035, N'He was a lamp that was burning and shining, and you wanted to rejoice greatly for a short time in his light.'
EXEC add_BibleVerse @BibleId, 343005036, N'“But I have a testimony greater than that from John. For the deeds that the Father has assigned me to complete – the deeds I am now doing – testify about me that the Father has sent me.'
EXEC add_BibleVerse @BibleId, 343005037, N'And the Father who sent me has himself testified about me. You people have never heard his voice nor seen his form at any time,'
EXEC add_BibleVerse @BibleId, 343005038, N'nor do you have his word residing in you, because you do not believe the one whom he sent.'
EXEC add_BibleVerse @BibleId, 343005039, N'You study the scriptures thoroughly because you think in them you possess eternal life, and it is these same scriptures that testify about me,'
EXEC add_BibleVerse @BibleId, 343005040, N'but you are not willing to come to me so that you may have life.'
EXEC add_BibleVerse @BibleId, 343005041, N'“I do not accept praise from people,'
EXEC add_BibleVerse @BibleId, 343005042, N'but I know you, that you do not have the love of God within you.'
EXEC add_BibleVerse @BibleId, 343005043, N'I have come in my Father’s name, and you do not accept me. If someone else comes in his own name, you will accept him.'
EXEC add_BibleVerse @BibleId, 343005044, N'How can you believe, if you accept praise from one another and don’t seek the praise that comes from the only God?'
EXEC add_BibleVerse @BibleId, 343005045, N'“Do not suppose that I will accuse you before the Father. The one who accuses you is Moses, in whom you have placed your hope.'
EXEC add_BibleVerse @BibleId, 343005046, N'If you believed Moses, you would believe me, because he wrote about me.'
EXEC add_BibleVerse @BibleId, 343005047, N'But if you do not believe what Moses wrote, how will you believe my words?”'
EXEC add_BibleVerse @BibleId, 343006001, N'After this Jesus went away to the other side of the Sea of Galilee (also called the Sea of Tiberias).'
EXEC add_BibleVerse @BibleId, 343006002, N'A large crowd was following him because they were observing the miraculous signs he was performing on the sick.'
EXEC add_BibleVerse @BibleId, 343006003, N'So Jesus went on up the mountainside and sat down there with his disciples.'
EXEC add_BibleVerse @BibleId, 343006004, N'(Now the Jewish feast of the Passover was near.)'
EXEC add_BibleVerse @BibleId, 343006005, N'Then Jesus, when he looked up and saw that a large crowd was coming to him, said to Philip, “Where can we buy bread so that these people may eat?”'
EXEC add_BibleVerse @BibleId, 343006006, N'(Now Jesus said this to test him, for he knew what he was going to do.)'
EXEC add_BibleVerse @BibleId, 343006007, N'Philip replied, “Two hundred silver coins worth of bread would not be enough for them, for each one to get a little.”'
EXEC add_BibleVerse @BibleId, 343006008, N'One of Jesus’ disciples, Andrew, Simon Peter’s brother, said to him,'
EXEC add_BibleVerse @BibleId, 343006009, N'“Here is a boy who has five barley loaves and two fish, but what good are these for so many people?”'
EXEC add_BibleVerse @BibleId, 343006010, N'Jesus said, “Have the people sit down.” (Now there was a lot of grass in that place.) So the men sat down, about five thousand in number.'
EXEC add_BibleVerse @BibleId, 343006011, N'Then Jesus took the loaves, and when he had given thanks, he distributed the bread to those who were seated. He then did the same with the fish, as much as they wanted.'
EXEC add_BibleVerse @BibleId, 343006012, N'When they were all satisfied, Jesus said to his disciples, “Gather up the broken pieces that are left over, so that nothing is wasted.”'
EXEC add_BibleVerse @BibleId, 343006013, N'So they gathered them up and filled twelve baskets with broken pieces from the five barley loaves left over by the people who had eaten.'
EXEC add_BibleVerse @BibleId, 343006014, N'Now when the people saw the miraculous sign that Jesus performed, they began to say to one another, “This is certainly the Prophet who is to come into the world.”'
EXEC add_BibleVerse @BibleId, 343006015, N'Then Jesus, because he knew they were going to come and seize him by force to make him king, withdrew again up the mountainside alone.'
EXEC add_BibleVerse @BibleId, 343006016, N'Now when evening came, his disciples went down to the lake,'
EXEC add_BibleVerse @BibleId, 343006017, N'got into a boat, and started to cross the lake to Capernaum. (It had already become dark, and Jesus had not yet come to them.)'
EXEC add_BibleVerse @BibleId, 343006018, N'By now a strong wind was blowing and the sea was getting rough.'
EXEC add_BibleVerse @BibleId, 343006019, N'Then, when they had rowed about three or four miles, they caught sight of Jesus walking on the lake, approaching the boat, and they were frightened.'
EXEC add_BibleVerse @BibleId, 343006020, N'But he said to them, “It is I. Do not be afraid.”'
EXEC add_BibleVerse @BibleId, 343006021, N'Then they wanted to take him into the boat, and immediately the boat came to the land where they had been heading.'
EXEC add_BibleVerse @BibleId, 343006022, N'The next day the crowd that remained on the other side of the lake realized that only one small boat had been there, and that Jesus had not boarded it with his disciples, but that his disciples had gone away alone.'
EXEC add_BibleVerse @BibleId, 343006023, N'But some boats from Tiberias came to shore near the place where they had eaten the bread after the Lord had given thanks.'
EXEC add_BibleVerse @BibleId, 343006024, N'So when the crowd realized that neither Jesus nor his disciples were there, they got into the boats and came to Capernaum looking for Jesus.'
EXEC add_BibleVerse @BibleId, 343006025, N'When they found him on the other side of the lake, they said to him, “Rabbi, when did you get here?”'
EXEC add_BibleVerse @BibleId, 343006026, N'Jesus replied, “I tell you the solemn truth, you are looking for me not because you saw miraculous signs, but because you ate all the loaves of bread you wanted.'
EXEC add_BibleVerse @BibleId, 343006027, N'Do not work for the food that disappears, but for the food that remains to eternal life – the food which the Son of Man will give to you. For God the Father has put his seal of approval on him.”'
EXEC add_BibleVerse @BibleId, 343006028, N'So then they said to him, “What must we do to accomplish the deeds God requires?”'
EXEC add_BibleVerse @BibleId, 343006029, N'Jesus replied, “This is the deed God requires – to believe in the one whom he sent.”'
EXEC add_BibleVerse @BibleId, 343006030, N'So they said to him, “Then what miraculous sign will you perform, so that we may see it and believe you? What will you do?'
EXEC add_BibleVerse @BibleId, 343006031, N'Our ancestors ate the manna in the wilderness, just as it is written, ‘ He gave them bread from heaven to eat.’”'
EXEC add_BibleVerse @BibleId, 343006032, N'Then Jesus told them, “I tell you the solemn truth, it is not Moses who has given you the bread from heaven, but my Father is giving you the true bread from heaven.'
EXEC add_BibleVerse @BibleId, 343006033, N'For the bread of God is the one who comes down from heaven and gives life to the world.”'
EXEC add_BibleVerse @BibleId, 343006034, N'So they said to him, “Sir, give us this bread all the time!”'
EXEC add_BibleVerse @BibleId, 343006035, N'Jesus said to them, “I am the bread of life. The one who comes to me will never go hungry, and the one who believes in me will never be thirsty.'
EXEC add_BibleVerse @BibleId, 343006036, N'But I told you that you have seen me and still do not believe.'
EXEC add_BibleVerse @BibleId, 343006037, N'Everyone whom the Father gives me will come to me, and the one who comes to me I will never send away.'
EXEC add_BibleVerse @BibleId, 343006038, N'For I have come down from heaven not to do my own will but the will of the one who sent me.'
EXEC add_BibleVerse @BibleId, 343006039, N'Now this is the will of the one who sent me – that I should not lose one person of every one he has given me, but raise them all up at the last day.'
EXEC add_BibleVerse @BibleId, 343006040, N'For this is the will of my Father – for everyone who looks on the Son and believes in him to have eternal life, and I will raise him up at the last day.”'
EXEC add_BibleVerse @BibleId, 343006041, N'Then the Jews who were hostile to Jesus began complaining about him because he said, “I am the bread that came down from heaven,”'
EXEC add_BibleVerse @BibleId, 343006042, N'and they said, “Isn’t this Jesus the son of Joseph, whose father and mother we know? How can he now say, ‘I have come down from heaven’?”'
EXEC add_BibleVerse @BibleId, 343006043, N'Jesus replied, “Do not complain about me to one another.'
EXEC add_BibleVerse @BibleId, 343006044, N'No one can come to me unless the Father who sent me draws him, and I will raise him up at the last day.'
EXEC add_BibleVerse @BibleId, 343006045, N'It is written in the prophets, ‘ And they will all be taught by God.’ Everyone who hears and learns from the Father comes to me.'
EXEC add_BibleVerse @BibleId, 343006046, N'(Not that anyone has seen the Father except the one who is from God – he has seen the Father.)'
EXEC add_BibleVerse @BibleId, 343006047, N'I tell you the solemn truth, the one who believes has eternal life.'
EXEC add_BibleVerse @BibleId, 343006048, N'I am the bread of life.'
EXEC add_BibleVerse @BibleId, 343006049, N'Your ancestors ate the manna in the wilderness, and they died.'
EXEC add_BibleVerse @BibleId, 343006050, N'This is the bread that has come down from heaven, so that a person may eat from it and not die.'
EXEC add_BibleVerse @BibleId, 343006051, N'I am the living bread that came down from heaven. If anyone eats from this bread he will live forever. The bread that I will give for the life of the world is my flesh.”'
EXEC add_BibleVerse @BibleId, 343006052, N'Then the Jews who were hostile to Jesus began to argue with one another, “How can this man give us his flesh to eat?”'
EXEC add_BibleVerse @BibleId, 343006053, N'Jesus said to them, “I tell you the solemn truth, unless you eat the flesh of the Son of Man and drink his blood, you have no life in yourselves.'
EXEC add_BibleVerse @BibleId, 343006054, N'The one who eats my flesh and drinks my blood has eternal life, and I will raise him up on the last day.'
EXEC add_BibleVerse @BibleId, 343006055, N'For my flesh is true food, and my blood is true drink.'
EXEC add_BibleVerse @BibleId, 343006056, N'The one who eats my flesh and drinks my blood resides in me, and I in him.'
EXEC add_BibleVerse @BibleId, 343006057, N'Just as the living Father sent me, and I live because of the Father, so the one who consumes me will live because of me.'
EXEC add_BibleVerse @BibleId, 343006058, N'This is the bread that came down from heaven; it is not like the bread your ancestors ate, but then later died. The one who eats this bread will live forever.”'
EXEC add_BibleVerse @BibleId, 343006059, N'Jesus said these things while he was teaching in the synagogue in Capernaum.'
EXEC add_BibleVerse @BibleId, 343006060, N'Then many of his disciples, when they heard these things, said, “This is a difficult saying! Who can understand it?”'
EXEC add_BibleVerse @BibleId, 343006061, N'When Jesus was aware that his disciples were complaining about this, he said to them, “Does this cause you to be offended?'
EXEC add_BibleVerse @BibleId, 343006062, N'Then what if you see the Son of Man ascending where he was before?'
EXEC add_BibleVerse @BibleId, 343006063, N'The Spirit is the one who gives life; human nature is of no help! The words that I have spoken to you are spirit and are life.'
EXEC add_BibleVerse @BibleId, 343006064, N'But there are some of you who do not believe.” (For Jesus had already known from the beginning who those were who did not believe, and who it was who would betray him.)'
EXEC add_BibleVerse @BibleId, 343006065, N'So Jesus added, “Because of this I told you that no one can come to me unless the Father has allowed him to come.”'
EXEC add_BibleVerse @BibleId, 343006066, N'After this many of his disciples quit following him and did not accompany him any longer.'
EXEC add_BibleVerse @BibleId, 343006067, N'So Jesus said to the twelve, “You don’t want to go away too, do you?”'
EXEC add_BibleVerse @BibleId, 343006068, N'Simon Peter answered him, “Lord, to whom would we go? You have the words of eternal life.'
EXEC add_BibleVerse @BibleId, 343006069, N'We have come to believe and to know that you are the Holy One of God!”'
EXEC add_BibleVerse @BibleId, 343006070, N'Jesus replied, “Didn’t I choose you, the twelve, and yet one of you is the devil?”'
EXEC add_BibleVerse @BibleId, 343006071, N'(Now he said this about Judas son of Simon Iscariot, for Judas, one of the twelve, was going to betray him.)'
EXEC add_BibleVerse @BibleId, 343007001, N'After this Jesus traveled throughout Galilee. He stayed out of Judea because the Jewish leaders wanted to kill him.'
EXEC add_BibleVerse @BibleId, 343007002, N'Now the Jewish feast of Tabernacles was near.'
EXEC add_BibleVerse @BibleId, 343007003, N'So Jesus’ brothers advised him, “Leave here and go to Judea so your disciples may see your miracles that you are performing.'
EXEC add_BibleVerse @BibleId, 343007004, N'For no one who seeks to make a reputation for himself does anything in secret. If you are doing these things, show yourself to the world.”'
EXEC add_BibleVerse @BibleId, 343007005, N'(For not even his own brothers believed in him.)'
EXEC add_BibleVerse @BibleId, 343007006, N'So Jesus replied, “My time has not yet arrived, but you are ready at any opportunity!'
EXEC add_BibleVerse @BibleId, 343007007, N'The world cannot hate you, but it hates me, because I am testifying about it that its deeds are evil.'
EXEC add_BibleVerse @BibleId, 343007008, N'You go up to the feast yourselves. I am not going up to this feast because my time has not yet fully arrived.”'
EXEC add_BibleVerse @BibleId, 343007009, N'When he had said this, he remained in Galilee.'
EXEC add_BibleVerse @BibleId, 343007010, N'But when his brothers had gone up to the feast, then Jesus himself also went up, not openly but in secret.'
EXEC add_BibleVerse @BibleId, 343007011, N'So the Jewish leaders were looking for him at the feast, asking, “Where is he?”'
EXEC add_BibleVerse @BibleId, 343007012, N'There was a lot of grumbling about him among the crowds. Some were saying, “He is a good man,” but others, “He deceives the common people.”'
EXEC add_BibleVerse @BibleId, 343007013, N'However, no one spoke openly about him for fear of the Jewish leaders.'
EXEC add_BibleVerse @BibleId, 343007014, N'When the feast was half over, Jesus went up to the temple courts and began to teach.'
EXEC add_BibleVerse @BibleId, 343007015, N'Then the Jewish leaders were astonished and said, “How does this man know so much when he has never had formal instruction?”'
EXEC add_BibleVerse @BibleId, 343007016, N'So Jesus replied, “My teaching is not from me, but from the one who sent me.'
EXEC add_BibleVerse @BibleId, 343007017, N'If anyone wants to do God’s will, he will know about my teaching, whether it is from God or whether I speak from my own authority.'
EXEC add_BibleVerse @BibleId, 343007018, N'The person who speaks on his own authority desires to receive honor for himself; the one who desires the honor of the one who sent him is a man of integrity, and there is no unrighteousness in him.'
EXEC add_BibleVerse @BibleId, 343007019, N'Hasn’t Moses given you the law? Yet not one of you keeps the law! Why do you want to kill me?”'
EXEC add_BibleVerse @BibleId, 343007020, N'The crowd answered, “You’re possessed by a demon! Who is trying to kill you?”'
EXEC add_BibleVerse @BibleId, 343007021, N'Jesus replied, “I performed one miracle and you are all amazed.'
EXEC add_BibleVerse @BibleId, 343007022, N'However, because Moses gave you the practice of circumcision (not that it came from Moses, but from the forefathers), you circumcise a male child on the Sabbath.'
EXEC add_BibleVerse @BibleId, 343007023, N'But if a male child is circumcised on the Sabbath so that the law of Moses is not broken, why are you angry with me because I made a man completely well on the Sabbath?'
EXEC add_BibleVerse @BibleId, 343007024, N'Do not judge according to external appearance, but judge with proper judgment.”'
EXEC add_BibleVerse @BibleId, 343007025, N'Then some of the residents of Jerusalem began to say, “Isn’t this the man they are trying to kill?'
EXEC add_BibleVerse @BibleId, 343007026, N'Yet here he is, speaking publicly, and they are saying nothing to him. Do the rulers really know that this man is the Christ?'
EXEC add_BibleVerse @BibleId, 343007027, N'But we know where this man comes from. Whenever the Christ comes, no one will know where he comes from.”'
EXEC add_BibleVerse @BibleId, 343007028, N'Then Jesus, while teaching in the temple courts, cried out, “You both know me and know where I come from! And I have not come on my own initiative, but the one who sent me is true. You do not know him,'
EXEC add_BibleVerse @BibleId, 343007029, N'but I know him, because I have come from him and he sent me.”'
EXEC add_BibleVerse @BibleId, 343007030, N'So then they tried to seize Jesus, but no one laid a hand on him, because his time had not yet come.'
EXEC add_BibleVerse @BibleId, 343007031, N'Yet many of the crowd believed in him and said, “Whenever the Christ comes, he won’t perform more miraculous signs than this man did, will he?”'
EXEC add_BibleVerse @BibleId, 343007032, N'The Pharisees heard the crowd murmuring these things about Jesus, so the chief priests and the Pharisees sent officers to arrest him.'
EXEC add_BibleVerse @BibleId, 343007033, N'Then Jesus said, “I will be with you for only a little while longer, and then I am going to the one who sent me.'
EXEC add_BibleVerse @BibleId, 343007034, N'You will look for me but will not find me, and where I am you cannot come.”'
EXEC add_BibleVerse @BibleId, 343007035, N'Then the Jewish leaders said to one another, “Where is he going to go that we cannot find him? He is not going to go to the Jewish people dispersed among the Greeks and teach the Greeks, is he?'
EXEC add_BibleVerse @BibleId, 343007036, N'What did he mean by saying, ‘You will look for me but will not find me, and where I am you cannot come’?”'
EXEC add_BibleVerse @BibleId, 343007037, N'On the last day of the feast, the greatest day, Jesus stood up and shouted out, “If anyone is thirsty, let him come to me, and'
EXEC add_BibleVerse @BibleId, 343007038, N'let the one who believes in me drink. Just as the scripture says, ‘ From within him will flow rivers of living water.’”'
EXEC add_BibleVerse @BibleId, 343007039, N'(Now he said this about the Spirit, whom those who believed in him were going to receive, for the Spirit had not yet been given, because Jesus was not yet glorified.)'
EXEC add_BibleVerse @BibleId, 343007040, N'When they heard these words, some of the crowd began to say, “This really is the Prophet!”'
EXEC add_BibleVerse @BibleId, 343007041, N'Others said, “This is the Christ!” But still others said, “No, for the Christ doesn’t come from Galilee, does he?'
EXEC add_BibleVerse @BibleId, 343007042, N'Don’t the scriptures say that the Christ is a descendant of David and comes from Bethlehem, the village where David lived?”'
EXEC add_BibleVerse @BibleId, 343007043, N'So there was a division in the crowd because of Jesus.'
EXEC add_BibleVerse @BibleId, 343007044, N'Some of them were wanting to seize him, but no one laid a hand on him.'
EXEC add_BibleVerse @BibleId, 343007045, N'Then the officers returned to the chief priests and Pharisees, who said to them, “Why didn’t you bring him back with you?”'
EXEC add_BibleVerse @BibleId, 343007046, N'The officers replied, “No one ever spoke like this man!”'
EXEC add_BibleVerse @BibleId, 343007047, N'Then the Pharisees answered, “You haven’t been deceived too, have you?'
EXEC add_BibleVerse @BibleId, 343007048, N'None of the rulers or the Pharisees have believed in him, have they?'
EXEC add_BibleVerse @BibleId, 343007049, N'But this rabble who do not know the law are accursed!”'
EXEC add_BibleVerse @BibleId, 343007050, N'Nicodemus, who had gone to Jesus before and who was one of the rulers, said,'
EXEC add_BibleVerse @BibleId, 343007051, N'“Our law doesn’t condemn a man unless it first hears from him and learns what he is doing, does it?”'
EXEC add_BibleVerse @BibleId, 343007052, N'They replied, “You aren’t from Galilee too, are you? Investigate carefully and you will see that no prophet comes from Galilee!”'
EXEC add_BibleVerse @BibleId, 343007053, N'And each one departed to his own house.'
EXEC add_BibleVerse @BibleId, 343008001, N'But Jesus went to the Mount of Olives.'
EXEC add_BibleVerse @BibleId, 343008002, N'Early in the morning he came to the temple courts again. All the people came to him, and he sat down and began to teach them.'
EXEC add_BibleVerse @BibleId, 343008003, N'The experts in the law and the Pharisees brought a woman who had been caught committing adultery. They made her stand in front of them'
EXEC add_BibleVerse @BibleId, 343008004, N'and said to Jesus, “Teacher, this woman was caught in the very act of adultery.'
EXEC add_BibleVerse @BibleId, 343008005, N'In the law Moses commanded us to stone to death such women. What then do you say?”'
EXEC add_BibleVerse @BibleId, 343008006, N'(Now they were asking this in an attempt to trap him, so that they could bring charges against him.) Jesus bent down and wrote on the ground with his finger.'
EXEC add_BibleVerse @BibleId, 343008007, N'When they persisted in asking him, he stood up straight and replied, “Whoever among you is guiltless may be the first to throw a stone at her.”'
EXEC add_BibleVerse @BibleId, 343008008, N'Then he bent over again and wrote on the ground.'
EXEC add_BibleVerse @BibleId, 343008009, N'Now when they heard this, they began to drift away one at a time, starting with the older ones, until Jesus was left alone with the woman standing before him.'
EXEC add_BibleVerse @BibleId, 343008010, N'Jesus stood up straight and said to her, “Woman, where are they? Did no one condemn you?”'
EXEC add_BibleVerse @BibleId, 343008011, N'She replied, “No one, Lord.” And Jesus said, “I do not condemn you either. Go, and from now on do not sin any more.”'
EXEC add_BibleVerse @BibleId, 343008012, N'Then Jesus spoke out again, “I am the light of the world. The one who follows me will never walk in darkness, but will have the light of life.”'
EXEC add_BibleVerse @BibleId, 343008013, N'So the Pharisees objected, “You testify about yourself; your testimony is not true!”'
EXEC add_BibleVerse @BibleId, 343008014, N'Jesus answered, “Even if I testify about myself, my testimony is true, because I know where I came from and where I am going. But you people do not know where I came from or where I am going.'
EXEC add_BibleVerse @BibleId, 343008015, N'You people judge by outward appearances; I do not judge anyone.'
EXEC add_BibleVerse @BibleId, 343008016, N'But if I judge, my evaluation is accurate, because I am not alone when I judge, but I and the Father who sent me do so together.'
EXEC add_BibleVerse @BibleId, 343008017, N'It is written in your law that the testimony of two men is true.'
EXEC add_BibleVerse @BibleId, 343008018, N'I testify about myself and the Father who sent me testifies about me.”'
EXEC add_BibleVerse @BibleId, 343008019, N'Then they began asking him, “Who is your father?” Jesus answered, “You do not know either me or my Father. If you knew me you would know my Father too.”'
EXEC add_BibleVerse @BibleId, 343008020, N'(Jesus spoke these words near the offering box while he was teaching in the temple courts. No one seized him because his time had not yet come.)'
EXEC add_BibleVerse @BibleId, 343008021, N'Then Jesus said to them again, “I am going away, and you will look for me but will die in your sin. Where I am going you cannot come.”'
EXEC add_BibleVerse @BibleId, 343008022, N'So the Jewish leaders began to say, “Perhaps he is going to kill himself, because he says, ‘Where I am going you cannot come.’”'
EXEC add_BibleVerse @BibleId, 343008023, N'Jesus replied, “You people are from below; I am from above. You people are from this world; I am not from this world.'
EXEC add_BibleVerse @BibleId, 343008024, N'Thus I told you that you will die in your sins. For unless you believe that I am he, you will die in your sins.”'
EXEC add_BibleVerse @BibleId, 343008025, N'So they said to him, “Who are you?” Jesus replied, “What I have told you from the beginning.'
EXEC add_BibleVerse @BibleId, 343008026, N'I have many things to say and to judge about you, but the Father who sent me is truthful, and the things I have heard from him I speak to the world.”'
EXEC add_BibleVerse @BibleId, 343008027, N'(They did not understand that he was telling them about his Father.)'
EXEC add_BibleVerse @BibleId, 343008028, N'Then Jesus said, “When you lift up the Son of Man, then you will know that I am he, and I do nothing on my own initiative, but I speak just what the Father taught me.'
EXEC add_BibleVerse @BibleId, 343008029, N'And the one who sent me is with me. He has not left me alone, because I always do those things that please him.”'
EXEC add_BibleVerse @BibleId, 343008030, N'While he was saying these things, many people believed in him.'
EXEC add_BibleVerse @BibleId, 343008031, N'Then Jesus said to those Judeans who had believed him, “If you continue to follow my teaching, you are really my disciples'
EXEC add_BibleVerse @BibleId, 343008032, N'and you will know the truth, and the truth will set you free.”'
EXEC add_BibleVerse @BibleId, 343008033, N'“We are descendants of Abraham,” they replied, “and have never been anyone’s slaves! How can you say, ‘You will become free’?”'
EXEC add_BibleVerse @BibleId, 343008034, N'Jesus answered them, “I tell you the solemn truth, everyone who practices sin is a slave of sin.'
EXEC add_BibleVerse @BibleId, 343008035, N'The slave does not remain in the family forever, but the son remains forever.'
EXEC add_BibleVerse @BibleId, 343008036, N'So if the son sets you free, you will be really free.'
EXEC add_BibleVerse @BibleId, 343008037, N'I know that you are Abraham’s descendants. But you want to kill me, because my teaching makes no progress among you.'
EXEC add_BibleVerse @BibleId, 343008038, N'I am telling you the things I have seen while with the Father; as for you, practice the things you have heard from the Father!”'
EXEC add_BibleVerse @BibleId, 343008039, N'They answered him, “Abraham is our father!” Jesus replied, “If you are Abraham’s children, you would be doing the deeds of Abraham.'
EXEC add_BibleVerse @BibleId, 343008040, N'But now you are trying to kill me, a man who has told you the truth I heard from God. Abraham did not do this!'
EXEC add_BibleVerse @BibleId, 343008041, N'You people are doing the deeds of your father.” Then they said to Jesus, “We were not born as a result of immorality! We have only one Father, God himself.”'
EXEC add_BibleVerse @BibleId, 343008042, N'Jesus replied, “If God were your Father, you would love me, for I have come from God and am now here. I have not come on my own initiative, but he sent me.'
EXEC add_BibleVerse @BibleId, 343008043, N'Why don’t you understand what I am saying? It is because you cannot accept my teaching.'
EXEC add_BibleVerse @BibleId, 343008044, N'You people are from your father the devil, and you want to do what your father desires. He was a murderer from the beginning, and does not uphold the truth, because there is no truth in him. Whenever he lies, he speaks according to his own nature, because he is a liar and the father of lies.'
EXEC add_BibleVerse @BibleId, 343008045, N'But because I am telling you the truth, you do not believe me.'
EXEC add_BibleVerse @BibleId, 343008046, N'Who among you can prove me guilty of any sin? If I am telling you the truth, why don’t you believe me?'
EXEC add_BibleVerse @BibleId, 343008047, N'The one who belongs to God listens and responds to God’s words. You don’t listen and respond, because you don’t belong to God.”'
EXEC add_BibleVerse @BibleId, 343008048, N'The Judeans replied, “Aren’t we correct in saying that you are a Samaritan and are possessed by a demon?”'
EXEC add_BibleVerse @BibleId, 343008049, N'Jesus answered, “I am not possessed by a demon, but I honor my Father – and yet you dishonor me.'
EXEC add_BibleVerse @BibleId, 343008050, N'I am not trying to get praise for myself. There is one who demands it, and he also judges.'
EXEC add_BibleVerse @BibleId, 343008051, N'I tell you the solemn truth, if anyone obeys my teaching, he will never see death.”'
EXEC add_BibleVerse @BibleId, 343008052, N'Then the Judeans responded, “Now we know you’re possessed by a demon! Both Abraham and the prophets died, and yet you say, ‘If anyone obeys my teaching, he will never experience death.’'
EXEC add_BibleVerse @BibleId, 343008053, N'You aren’t greater than our father Abraham who died, are you? And the prophets died too! Who do you claim to be?”'
EXEC add_BibleVerse @BibleId, 343008054, N'Jesus replied, “If I glorify myself, my glory is worthless. The one who glorifies me is my Father, about whom you people say, ‘He is our God.’'
EXEC add_BibleVerse @BibleId, 343008055, N'Yet you do not know him, but I know him. If I were to say that I do not know him, I would be a liar like you. But I do know him, and I obey his teaching.'
EXEC add_BibleVerse @BibleId, 343008056, N'Your father Abraham was overjoyed to see my day, and he saw it and was glad.”'
EXEC add_BibleVerse @BibleId, 343008057, N'Then the Judeans replied, “You are not yet fifty years old! Have you seen Abraham?”'
EXEC add_BibleVerse @BibleId, 343008058, N'Jesus said to them, “I tell you the solemn truth, before Abraham came into existence, I am!”'
EXEC add_BibleVerse @BibleId, 343008059, N'Then they picked up stones to throw at him, but Jesus hid himself and went out from the temple area.'
EXEC add_BibleVerse @BibleId, 343009001, N'Now as Jesus was passing by, he saw a man who had been blind from birth.'
EXEC add_BibleVerse @BibleId, 343009002, N'His disciples asked him, “Rabbi, who committed the sin that caused him to be born blind, this man or his parents?”'
EXEC add_BibleVerse @BibleId, 343009003, N'Jesus answered, “Neither this man nor his parents sinned, but he was born blind so that the acts of God may be revealed through what happens to him.'
EXEC add_BibleVerse @BibleId, 343009004, N'We must perform the deeds of the one who sent me as long as it is daytime. Night is coming when no one can work.'
EXEC add_BibleVerse @BibleId, 343009005, N'As long as I am in the world, I am the light of the world.”'
EXEC add_BibleVerse @BibleId, 343009006, N'Having said this, he spat on the ground and made some mud with the saliva. He smeared the mud on the blind man’s eyes'
EXEC add_BibleVerse @BibleId, 343009007, N'and said to him, “Go wash in the pool of Siloam” (which is translated “sent”). So the blind man went away and washed, and came back seeing.'
EXEC add_BibleVerse @BibleId, 343009008, N'Then the neighbors and the people who had seen him previously as a beggar began saying, “Is this not the man who used to sit and beg?”'
EXEC add_BibleVerse @BibleId, 343009009, N'Some people said, “This is the man!” while others said, “No, but he looks like him.” The man himself kept insisting, “I am the one!”'
EXEC add_BibleVerse @BibleId, 343009010, N'So they asked him, “How then were you made to see?”'
EXEC add_BibleVerse @BibleId, 343009011, N'He replied, “The man called Jesus made mud, smeared it on my eyes and told me, ‘Go to Siloam and wash.’ So I went and washed, and was able to see.”'
EXEC add_BibleVerse @BibleId, 343009012, N'They said to him, “Where is that man?” He replied, “I don’t know.”'
EXEC add_BibleVerse @BibleId, 343009013, N'They brought the man who used to be blind to the Pharisees.'
EXEC add_BibleVerse @BibleId, 343009014, N'(Now the day on which Jesus made the mud and caused him to see was a Sabbath.)'
EXEC add_BibleVerse @BibleId, 343009015, N'So the Pharisees asked him again how he had gained his sight. He replied, “He put mud on my eyes and I washed, and now I am able to see.”'
EXEC add_BibleVerse @BibleId, 343009016, N'Then some of the Pharisees began to say, “This man is not from God, because he does not observe the Sabbath.” But others said, “How can a man who is a sinner perform such miraculous signs?” Thus there was a division among them.'
EXEC add_BibleVerse @BibleId, 343009017, N'So again they asked the man who used to be blind, “What do you say about him, since he caused you to see?” “He is a prophet,” the man replied.'
EXEC add_BibleVerse @BibleId, 343009018, N'Now the Jewish religious leaders refused to believe that he had really been blind and had gained his sight until at last they summoned the parents of the man who had become able to see.'
EXEC add_BibleVerse @BibleId, 343009019, N'They asked the parents, “Is this your son, whom you say was born blind? Then how does he now see?”'
EXEC add_BibleVerse @BibleId, 343009020, N'So his parents replied, “We know that this is our son and that he was born blind.'
EXEC add_BibleVerse @BibleId, 343009021, N'But we do not know how he is now able to see, nor do we know who caused him to see. Ask him, he is a mature adult. He will speak for himself.”'
EXEC add_BibleVerse @BibleId, 343009022, N'(His parents said these things because they were afraid of the Jewish religious leaders. For the Jewish leaders had already agreed that anyone who confessed Jesus to be the Christ would be put out of the synagogue.'
EXEC add_BibleVerse @BibleId, 343009023, N'For this reason his parents said, “He is a mature adult, ask him.”)'
EXEC add_BibleVerse @BibleId, 343009024, N'Then they summoned the man who used to be blind a second time and said to him, “Promise before God to tell the truth. We know that this man is a sinner.”'
EXEC add_BibleVerse @BibleId, 343009025, N'He replied, “I do not know whether he is a sinner. I do know one thing – that although I was blind, now I can see.”'
EXEC add_BibleVerse @BibleId, 343009026, N'Then they said to him, “What did he do to you? How did he cause you to see?”'
EXEC add_BibleVerse @BibleId, 343009027, N'He answered, “I told you already and you didn’t listen. Why do you want to hear it again? You people don’t want to become his disciples too, do you?”'
EXEC add_BibleVerse @BibleId, 343009028, N'They heaped insults on him, saying, “You are his disciple! We are disciples of Moses!'
EXEC add_BibleVerse @BibleId, 343009029, N'We know that God has spoken to Moses! We do not know where this man comes from!”'
EXEC add_BibleVerse @BibleId, 343009030, N'The man replied, “This is a remarkable thing, that you don’t know where he comes from, and yet he caused me to see!'
EXEC add_BibleVerse @BibleId, 343009031, N'We know that God doesn’t listen to sinners, but if anyone is devout and does his will, God listens to him.'
EXEC add_BibleVerse @BibleId, 343009032, N'Never before has anyone heard of someone causing a man born blind to see.'
EXEC add_BibleVerse @BibleId, 343009033, N'If this man were not from God, he could do nothing.”'
EXEC add_BibleVerse @BibleId, 343009034, N'They replied, “You were born completely in sinfulness, and yet you presume to teach us?” So they threw him out.'
EXEC add_BibleVerse @BibleId, 343009035, N'Jesus heard that they had thrown him out, so he found the man and said to him, “Do you believe in the Son of Man?”'
EXEC add_BibleVerse @BibleId, 343009036, N'The man replied, “And who is he, sir, that I may believe in him?”'
EXEC add_BibleVerse @BibleId, 343009037, N'Jesus told him, “You have seen him; he is the one speaking with you.”'
EXEC add_BibleVerse @BibleId, 343009038, N'He said, “Lord, I believe,” and he worshiped him.'
EXEC add_BibleVerse @BibleId, 343009039, N'Jesus said, “For judgment I have come into this world, so that those who do not see may gain their sight, and the ones who see may become blind.”'
EXEC add_BibleVerse @BibleId, 343009040, N'Some of the Pharisees who were with him heard this and asked him, “We are not blind too, are we?”'
EXEC add_BibleVerse @BibleId, 343009041, N'Jesus replied, “If you were blind, you would not be guilty of sin, but now because you claim that you can see, your guilt remains.”'
EXEC add_BibleVerse @BibleId, 343010001, N'“I tell you the solemn truth, the one who does not enter the sheepfold by the door, but climbs in some other way, is a thief and a robber.'
EXEC add_BibleVerse @BibleId, 343010002, N'The one who enters by the door is the shepherd of the sheep.'
EXEC add_BibleVerse @BibleId, 343010003, N'The doorkeeper opens the door for him, and the sheep hear his voice. He calls his own sheep by name and leads them out.'
EXEC add_BibleVerse @BibleId, 343010004, N'When he has brought all his own sheep out, he goes ahead of them, and the sheep follow him because they recognize his voice.'
EXEC add_BibleVerse @BibleId, 343010005, N'They will never follow a stranger, but will run away from him, because they do not recognize the stranger’s voice.”'
EXEC add_BibleVerse @BibleId, 343010006, N'Jesus told them this parable, but they did not understand what he was saying to them.'
EXEC add_BibleVerse @BibleId, 343010007, N'So Jesus said to them again, “I tell you the solemn truth, I am the door for the sheep.'
EXEC add_BibleVerse @BibleId, 343010008, N'All who came before me were thieves and robbers, but the sheep did not listen to them.'
EXEC add_BibleVerse @BibleId, 343010009, N'I am the door. If anyone enters through me, he will be saved, and will come in and go out, and find pasture.'
EXEC add_BibleVerse @BibleId, 343010010, N'The thief comes only to steal and kill and destroy; I have come so that they may have life, and may have it abundantly.'
EXEC add_BibleVerse @BibleId, 343010011, N'“I am the good shepherd. The good shepherd lays down his life for the sheep.'
EXEC add_BibleVerse @BibleId, 343010012, N'The hired hand, who is not a shepherd and does not own sheep, sees the wolf coming and abandons the sheep and runs away. So the wolf attacks the sheep and scatters them.'
EXEC add_BibleVerse @BibleId, 343010013, N'Because he is a hired hand and is not concerned about the sheep, he runs away.'
EXEC add_BibleVerse @BibleId, 343010014, N'“I am the good shepherd. I know my own and my own know me –'
EXEC add_BibleVerse @BibleId, 343010015, N'just as the Father knows me and I know the Father – and I lay down my life for the sheep.'
EXEC add_BibleVerse @BibleId, 343010016, N'I have other sheep that do not come from this sheepfold. I must bring them too, and they will listen to my voice, so that there will be one flock and one shepherd.'
EXEC add_BibleVerse @BibleId, 343010017, N'This is why the Father loves me – because I lay down my life, so that I may take it back again.'
EXEC add_BibleVerse @BibleId, 343010018, N'No one takes it away from me, but I lay it down of my own free will. I have the authority to lay it down, and I have the authority to take it back again. This commandment I received from my Father.”'
EXEC add_BibleVerse @BibleId, 343010019, N'Another sharp division took place among the Jewish people because of these words.'
EXEC add_BibleVerse @BibleId, 343010020, N'Many of them were saying, “He is possessed by a demon and has lost his mind! Why do you listen to him?”'
EXEC add_BibleVerse @BibleId, 343010021, N'Others said, “These are not the words of someone possessed by a demon. A demon cannot cause the blind to see, can it?”'
EXEC add_BibleVerse @BibleId, 343010022, N'Then came the feast of the Dedication in Jerusalem.'
EXEC add_BibleVerse @BibleId, 343010023, N'It was winter, and Jesus was walking in the temple area in Solomon’s Portico.'
EXEC add_BibleVerse @BibleId, 343010024, N'The Jewish leaders surrounded him and asked, “How long will you keep us in suspense? If you are the Christ, tell us plainly.”'
EXEC add_BibleVerse @BibleId, 343010025, N'Jesus replied, “I told you and you do not believe. The deeds I do in my Father’s name testify about me.'
EXEC add_BibleVerse @BibleId, 343010026, N'But you refuse to believe because you are not my sheep.'
EXEC add_BibleVerse @BibleId, 343010027, N'My sheep listen to my voice, and I know them, and they follow me.'
EXEC add_BibleVerse @BibleId, 343010028, N'I give them eternal life, and they will never perish; no one will snatch them from my hand.'
EXEC add_BibleVerse @BibleId, 343010029, N'My Father, who has given them to me, is greater than all, and no one can snatch them from my Father’s hand.'
EXEC add_BibleVerse @BibleId, 343010030, N'The Father and I are one.”'
EXEC add_BibleVerse @BibleId, 343010031, N'The Jewish leaders picked up rocks again to stone him to death.'
EXEC add_BibleVerse @BibleId, 343010032, N'Jesus said to them, “I have shown you many good deeds from the Father. For which one of them are you going to stone me?”'
EXEC add_BibleVerse @BibleId, 343010033, N'The Jewish leaders replied, “We are not going to stone you for a good deed but for blasphemy, because you, a man, are claiming to be God.”'
EXEC add_BibleVerse @BibleId, 343010034, N'Jesus answered, “Is it not written in your law, ‘ I said, you are gods’?'
EXEC add_BibleVerse @BibleId, 343010035, N'If those people to whom the word of God came were called ‘gods’ (and the scripture cannot be broken),'
EXEC add_BibleVerse @BibleId, 343010036, N'do you say about the one whom the Father set apart and sent into the world, ‘You are blaspheming,’ because I said, ‘I am the Son of God’?'
EXEC add_BibleVerse @BibleId, 343010037, N'If I do not perform the deeds of my Father, do not believe me.'
EXEC add_BibleVerse @BibleId, 343010038, N'But if I do them, even if you do not believe me, believe the deeds, so that you may come to know and understand that I am in the Father and the Father is in me.”'
EXEC add_BibleVerse @BibleId, 343010039, N'Then they attempted again to seize him, but he escaped their clutches.'
EXEC add_BibleVerse @BibleId, 343010040, N'Jesus went back across the Jordan River again to the place where John had been baptizing at an earlier time, and he stayed there.'
EXEC add_BibleVerse @BibleId, 343010041, N'Many came to him and began to say, “John performed no miraculous sign, but everything John said about this man was true!”'
EXEC add_BibleVerse @BibleId, 343010042, N'And many believed in Jesus there.'
EXEC add_BibleVerse @BibleId, 343011001, N'Now a certain man named Lazarus was sick. He was from Bethany, the village where Mary and her sister Martha lived.'
EXEC add_BibleVerse @BibleId, 343011002, N'(Now it was Mary who anointed the Lord with perfumed oil and wiped his feet dry with her hair, whose brother Lazarus was sick.)'
EXEC add_BibleVerse @BibleId, 343011003, N'So the sisters sent a message to Jesus, “Lord, look, the one you love is sick.”'
EXEC add_BibleVerse @BibleId, 343011004, N'When Jesus heard this, he said, “This sickness will not lead to death, but to God’s glory, so that the Son of God may be glorified through it.”'
EXEC add_BibleVerse @BibleId, 343011005, N'(Now Jesus loved Martha and her sister and Lazarus.)'
EXEC add_BibleVerse @BibleId, 343011006, N'So when he heard that Lazarus was sick, he remained in the place where he was for two more days.'
EXEC add_BibleVerse @BibleId, 343011007, N'Then after this, he said to his disciples, “Let us go to Judea again.”'
EXEC add_BibleVerse @BibleId, 343011008, N'The disciples replied, “Rabbi, the Jewish leaders were just now trying to stone you to death! Are you going there again?”'
EXEC add_BibleVerse @BibleId, 343011009, N'Jesus replied, “Are there not twelve hours in a day? If anyone walks around in the daytime, he does not stumble, because he sees the light of this world.'
EXEC add_BibleVerse @BibleId, 343011010, N'But if anyone walks around at night, he stumbles, because the light is not in him.”'
EXEC add_BibleVerse @BibleId, 343011011, N'After he said this, he added, “Our friend Lazarus has fallen asleep. But I am going there to awaken him.”'
EXEC add_BibleVerse @BibleId, 343011012, N'Then the disciples replied, “Lord, if he has fallen asleep, he will recover.”'
EXEC add_BibleVerse @BibleId, 343011013, N'(Now Jesus had been talking about his death, but they thought he had been talking about real sleep.)'
EXEC add_BibleVerse @BibleId, 343011014, N'Then Jesus told them plainly, “Lazarus has died,'
EXEC add_BibleVerse @BibleId, 343011015, N'and I am glad for your sake that I was not there, so that you may believe. But let us go to him.”'
EXEC add_BibleVerse @BibleId, 343011016, N'So Thomas (called Didymus ) said to his fellow disciples, “Let us go too, so that we may die with him.”'
EXEC add_BibleVerse @BibleId, 343011017, N'When Jesus arrived, he found that Lazarus had been in the tomb four days already.'
EXEC add_BibleVerse @BibleId, 343011018, N'(Now Bethany was less than two miles from Jerusalem,'
EXEC add_BibleVerse @BibleId, 343011019, N'so many of the Jewish people of the region had come to Martha and Mary to console them over the loss of their brother.)'
EXEC add_BibleVerse @BibleId, 343011020, N'So when Martha heard that Jesus was coming, she went out to meet him, but Mary was sitting in the house.'
EXEC add_BibleVerse @BibleId, 343011021, N'Martha said to Jesus, “Lord, if you had been here, my brother would not have died.'
EXEC add_BibleVerse @BibleId, 343011022, N'But even now I know that whatever you ask from God, God will grant you.”'
EXEC add_BibleVerse @BibleId, 343011023, N'Jesus replied, “Your brother will come back to life again.”'
EXEC add_BibleVerse @BibleId, 343011024, N'Martha said, “I know that he will come back to life again in the resurrection at the last day.”'
EXEC add_BibleVerse @BibleId, 343011025, N'Jesus said to her, “I am the resurrection and the life. The one who believes in me will live even if he dies,'
EXEC add_BibleVerse @BibleId, 343011026, N'and the one who lives and believes in me will never die. Do you believe this?”'
EXEC add_BibleVerse @BibleId, 343011027, N'She replied, “Yes, Lord, I believe that you are the Christ, the Son of God who comes into the world.”'
EXEC add_BibleVerse @BibleId, 343011028, N'And when she had said this, Martha went and called her sister Mary, saying privately, “The Teacher is here and is asking for you.”'
EXEC add_BibleVerse @BibleId, 343011029, N'So when Mary heard this, she got up quickly and went to him.'
EXEC add_BibleVerse @BibleId, 343011030, N'(Now Jesus had not yet entered the village, but was still in the place where Martha had come out to meet him.)'
EXEC add_BibleVerse @BibleId, 343011031, N'Then the people who were with Mary in the house consoling her saw her get up quickly and go out. They followed her, because they thought she was going to the tomb to weep there.'
EXEC add_BibleVerse @BibleId, 343011032, N'Now when Mary came to the place where Jesus was and saw him, she fell at his feet and said to him, “Lord, if you had been here, my brother would not have died.”'
EXEC add_BibleVerse @BibleId, 343011033, N'When Jesus saw her weeping, and the people who had come with her weeping, he was intensely moved in spirit and greatly distressed.'
EXEC add_BibleVerse @BibleId, 343011034, N'He asked, “Where have you laid him?” They replied, “Lord, come and see.”'
EXEC add_BibleVerse @BibleId, 343011035, N'Jesus wept.'
EXEC add_BibleVerse @BibleId, 343011036, N'Thus the people who had come to mourn said, “Look how much he loved him!”'
EXEC add_BibleVerse @BibleId, 343011037, N'But some of them said, “This is the man who caused the blind man to see! Couldn’t he have done something to keep Lazarus from dying?”'
EXEC add_BibleVerse @BibleId, 343011038, N'Jesus, intensely moved again, came to the tomb. (Now it was a cave, and a stone was placed across it.)'
EXEC add_BibleVerse @BibleId, 343011039, N'Jesus said, “Take away the stone.” Martha, the sister of the deceased, replied, “Lord, by this time the body will have a bad smell, because he has been buried four days.”'
EXEC add_BibleVerse @BibleId, 343011040, N'Jesus responded, “Didn’t I tell you that if you believe, you would see the glory of God?”'
EXEC add_BibleVerse @BibleId, 343011041, N'So they took away the stone. Jesus looked upward and said, “Father, I thank you that you have listened to me.'
EXEC add_BibleVerse @BibleId, 343011042, N'I knew that you always listen to me, but I said this for the sake of the crowd standing around here, that they may believe that you sent me.”'
EXEC add_BibleVerse @BibleId, 343011043, N'When he had said this, he shouted in a loud voice, “Lazarus, come out!”'
EXEC add_BibleVerse @BibleId, 343011044, N'The one who had died came out, his feet and hands tied up with strips of cloth, and a cloth wrapped around his face. Jesus said to them, “Unwrap him and let him go.”'
EXEC add_BibleVerse @BibleId, 343011045, N'Then many of the people, who had come with Mary and had seen the things Jesus did, believed in him.'
EXEC add_BibleVerse @BibleId, 343011046, N'But some of them went to the Pharisees and reported to them what Jesus had done.'
EXEC add_BibleVerse @BibleId, 343011047, N'So the chief priests and the Pharisees called the council together and said, “What are we doing? For this man is performing many miraculous signs.'
EXEC add_BibleVerse @BibleId, 343011048, N'If we allow him to go on in this way, everyone will believe in him, and the Romans will come and take away our sanctuary and our nation.”'
EXEC add_BibleVerse @BibleId, 343011049, N'Then one of them, Caiaphas, who was high priest that year, said, “You know nothing at all!'
EXEC add_BibleVerse @BibleId, 343011050, N'You do not realize that it is more to your advantage to have one man die for the people than for the whole nation to perish.”'
EXEC add_BibleVerse @BibleId, 343011051, N'(Now he did not say this on his own, but because he was high priest that year, he prophesied that Jesus was going to die for the Jewish nation,'
EXEC add_BibleVerse @BibleId, 343011052, N'and not for the Jewish nation only, but to gather together into one the children of God who are scattered.)'
EXEC add_BibleVerse @BibleId, 343011053, N'So from that day they planned together to kill him.'
EXEC add_BibleVerse @BibleId, 343011054, N'Thus Jesus no longer went around publicly among the Judeans, but went away from there to the region near the wilderness, to a town called Ephraim, and stayed there with his disciples.'
EXEC add_BibleVerse @BibleId, 343011055, N'Now the Jewish feast of Passover was near, and many people went up to Jerusalem from the rural areas before the Passover to cleanse themselves ritually.'
EXEC add_BibleVerse @BibleId, 343011056, N'Thus they were looking for Jesus, and saying to one another as they stood in the temple courts, “What do you think? That he won’t come to the feast?”'
EXEC add_BibleVerse @BibleId, 343011057, N'(Now the chief priests and the Pharisees had given orders that anyone who knew where Jesus was should report it, so that they could arrest him.)'
EXEC add_BibleVerse @BibleId, 343012001, N'Then, six days before the Passover, Jesus came to Bethany, where Lazarus lived, whom he had raised from the dead.'
EXEC add_BibleVerse @BibleId, 343012002, N'So they prepared a dinner for Jesus there. Martha was serving, and Lazarus was among those present at the table with him.'
EXEC add_BibleVerse @BibleId, 343012003, N'Then Mary took three quarters of a pound of expensive aromatic oil from pure nard and anointed the feet of Jesus. She then wiped his feet dry with her hair. (Now the house was filled with the fragrance of the perfumed oil.)'
EXEC add_BibleVerse @BibleId, 343012004, N'But Judas Iscariot, one of his disciples (the one who was going to betray him) said,'
EXEC add_BibleVerse @BibleId, 343012005, N'“Why wasn’t this oil sold for three hundred silver coins and the money given to the poor?”'
EXEC add_BibleVerse @BibleId, 343012006, N'(Now Judas said this not because he was concerned about the poor, but because he was a thief. As keeper of the money box, he used to steal what was put into it.)'
EXEC add_BibleVerse @BibleId, 343012007, N'So Jesus said, “Leave her alone. She has kept it for the day of my burial.'
EXEC add_BibleVerse @BibleId, 343012008, N'For you will always have the poor with you, but you will not always have me!”'
EXEC add_BibleVerse @BibleId, 343012009, N'Now a large crowd of Judeans learned that Jesus was there, and so they came not only because of him but also to see Lazarus whom he had raised from the dead.'
EXEC add_BibleVerse @BibleId, 343012010, N'So the chief priests planned to kill Lazarus too,'
EXEC add_BibleVerse @BibleId, 343012011, N'for on account of him many of the Jewish people from Jerusalem were going away and believing in Jesus.'
EXEC add_BibleVerse @BibleId, 343012012, N'The next day the large crowd that had come to the feast heard that Jesus was coming to Jerusalem.'
EXEC add_BibleVerse @BibleId, 343012013, N'So they took branches of palm trees and went out to meet him. They began to shout, “ Hosanna! Blessed is the one who comes in the name of the Lord*! Blessed is the king of Israel!”'
EXEC add_BibleVerse @BibleId, 343012014, N'Jesus found a young donkey and sat on it, just as it is written,'
EXEC add_BibleVerse @BibleId, 343012015, N'“ Do not be afraid, people of Zion; look, your king is coming, seated on a donkey’s colt!”'
EXEC add_BibleVerse @BibleId, 343012016, N'(His disciples did not understand these things when they first happened, but when Jesus was glorified, then they remembered that these things were written about him and that these things had happened to him.)'
EXEC add_BibleVerse @BibleId, 343012017, N'So the crowd who had been with him when he called Lazarus out of the tomb and raised him from the dead were continuing to testify about it.'
EXEC add_BibleVerse @BibleId, 343012018, N'Because they had heard that Jesus had performed this miraculous sign, the crowd went out to meet him.'
EXEC add_BibleVerse @BibleId, 343012019, N'Thus the Pharisees said to one another, “You see that you can do nothing. Look, the world has run off after him!”'
EXEC add_BibleVerse @BibleId, 343012020, N'Now some Greeks were among those who had gone up to worship at the feast.'
EXEC add_BibleVerse @BibleId, 343012021, N'So these approached Philip, who was from Bethsaida in Galilee, and requested, “Sir, we would like to see Jesus.”'
EXEC add_BibleVerse @BibleId, 343012022, N'Philip went and told Andrew, and they both went and told Jesus.'
EXEC add_BibleVerse @BibleId, 343012023, N'Jesus replied, “The time has come for the Son of Man to be glorified.'
EXEC add_BibleVerse @BibleId, 343012024, N'I tell you the solemn truth, unless a kernel of wheat falls into the ground and dies, it remains by itself alone. But if it dies, it produces much grain.'
EXEC add_BibleVerse @BibleId, 343012025, N'The one who loves his life destroys it, and the one who hates his life in this world guards it for eternal life.'
EXEC add_BibleVerse @BibleId, 343012026, N'If anyone wants to serve me, he must follow me, and where I am, my servant will be too. If anyone serves me, the Father will honor him.'
EXEC add_BibleVerse @BibleId, 343012027, N'“Now my soul is greatly distressed. And what should I say? ‘Father, deliver me from this hour’? No, but for this very reason I have come to this hour.'
EXEC add_BibleVerse @BibleId, 343012028, N'Father, glorify your name.” Then a voice came from heaven, “I have glorified it, and I will glorify it again.”'
EXEC add_BibleVerse @BibleId, 343012029, N'The crowd that stood there and heard the voice said that it had thundered. Others said that an angel had spoken to him.'
EXEC add_BibleVerse @BibleId, 343012030, N'Jesus said, “This voice has not come for my benefit but for yours.'
EXEC add_BibleVerse @BibleId, 343012031, N'Now is the judgment of this world; now the ruler of this world will be driven out.'
EXEC add_BibleVerse @BibleId, 343012032, N'And I, when I am lifted up from the earth, will draw all people to myself.”'
EXEC add_BibleVerse @BibleId, 343012033, N'(Now he said this to indicate clearly what kind of death he was going to die.)'
EXEC add_BibleVerse @BibleId, 343012034, N'Then the crowd responded, “We have heard from the law that the Christ will remain forever. How can you say, ‘The Son of Man must be lifted up’? Who is this Son of Man?”'
EXEC add_BibleVerse @BibleId, 343012035, N'Jesus replied, “The light is with you for a little while longer. Walk while you have the light, so that the darkness may not overtake you. The one who walks in the darkness does not know where he is going.'
EXEC add_BibleVerse @BibleId, 343012036, N'While you have the light, believe in the light, so that you may become sons of light.” When Jesus had said these things, he went away and hid himself from them.'
EXEC add_BibleVerse @BibleId, 343012037, N'Although Jesus had performed so many miraculous signs before them, they still refused to believe in him,'
EXEC add_BibleVerse @BibleId, 343012038, N'so that the word of Isaiah the prophet would be fulfilled. He said, “ Lord, who has believed our message, and to whom has the arm of the Lord, who has believed our message, and to whom has the arm of the Lord been revealed?”'
EXEC add_BibleVerse @BibleId, 343012039, N'For this reason they could not believe, because again Isaiah said,'
EXEC add_BibleVerse @BibleId, 343012040, N'“ He has blinded their eyes and hardened their heart, so that they would not see with their eyes and understand with their heart, and turn to me, and I would heal them*.”'
EXEC add_BibleVerse @BibleId, 343012041, N'Isaiah said these things because he saw Christ’s glory, and spoke about him.'
EXEC add_BibleVerse @BibleId, 343012042, N'Nevertheless, even among the rulers many believed in him, but because of the Pharisees they would not confess Jesus to be the Christ, so that they would not be put out of the synagogue.'
EXEC add_BibleVerse @BibleId, 343012043, N'For they loved praise from men more than praise from God.'
EXEC add_BibleVerse @BibleId, 343012044, N'But Jesus shouted out, “The one who believes in me does not believe in me, but in the one who sent me,'
EXEC add_BibleVerse @BibleId, 343012045, N'and the one who sees me sees the one who sent me.'
EXEC add_BibleVerse @BibleId, 343012046, N'I have come as a light into the world, so that everyone who believes in me should not remain in darkness.'
EXEC add_BibleVerse @BibleId, 343012047, N'If anyone hears my words and does not obey them, I do not judge him. For I have not come to judge the world, but to save the world.'
EXEC add_BibleVerse @BibleId, 343012048, N'The one who rejects me and does not accept my words has a judge; the word I have spoken will judge him at the last day.'
EXEC add_BibleVerse @BibleId, 343012049, N'For I have not spoken from my own authority, but the Father himself who sent me has commanded me what I should say and what I should speak.'
EXEC add_BibleVerse @BibleId, 343012050, N'And I know that his commandment is eternal life. Thus the things I say, I say just as the Father has told me.”'
EXEC add_BibleVerse @BibleId, 343013001, N'Just before the Passover feast, Jesus knew that his time had come to depart from this world to the Father. Having loved his own who were in the world, he now loved them to the very end.'
EXEC add_BibleVerse @BibleId, 343013002, N'The evening meal was in progress, and the devil had already put into the heart of Judas Iscariot, Simon’s son, that he should betray Jesus.'
EXEC add_BibleVerse @BibleId, 343013003, N'Because Jesus knew that the Father had handed all things over to him, and that he had come from God and was going back to God,'
EXEC add_BibleVerse @BibleId, 343013004, N'he got up from the meal, removed his outer clothes, took a towel and tied it around himself.'
EXEC add_BibleVerse @BibleId, 343013005, N'He poured water into the washbasin and began to wash the disciples’ feet and to dry them with the towel he had wrapped around himself.'
EXEC add_BibleVerse @BibleId, 343013006, N'Then he came to Simon Peter. Peter said to him, “Lord, are you going to wash my feet?”'
EXEC add_BibleVerse @BibleId, 343013007, N'Jesus replied, “You do not understand what I am doing now, but you will understand after these things.”'
EXEC add_BibleVerse @BibleId, 343013008, N'Peter said to him, “You will never wash my feet!” Jesus replied, “If I do not wash you, you have no share with me.”'
EXEC add_BibleVerse @BibleId, 343013009, N'Simon Peter said to him, “Lord, wash not only my feet, but also my hands and my head!”'
EXEC add_BibleVerse @BibleId, 343013010, N'Jesus replied, “The one who has bathed needs only to wash his feet, but is completely clean. And you disciples are clean, but not every one of you.”'
EXEC add_BibleVerse @BibleId, 343013011, N'(For Jesus knew the one who was going to betray him. For this reason he said, “Not every one of you is clean.”)'
EXEC add_BibleVerse @BibleId, 343013012, N'So when Jesus had washed their feet and put his outer clothing back on, he took his place at the table again and said to them, “Do you understand what I have done for you?'
EXEC add_BibleVerse @BibleId, 343013013, N'You call me ‘Teacher’ and ‘Lord,’ and do so correctly, for that is what I am.'
EXEC add_BibleVerse @BibleId, 343013014, N'If I then, your Lord and Teacher, have washed your feet, you too ought to wash one another’s feet.'
EXEC add_BibleVerse @BibleId, 343013015, N'For I have given you an example – you should do just as I have done for you.'
EXEC add_BibleVerse @BibleId, 343013016, N'I tell you the solemn truth, the slave is not greater than his master, nor is the one who is sent as a messenger greater than the one who sent him.'
EXEC add_BibleVerse @BibleId, 343013017, N'If you understand these things, you will be blessed if you do them.'
EXEC add_BibleVerse @BibleId, 343013018, N'“What I am saying does not refer to all of you. I know the ones I have chosen. But this is to fulfill the scripture, ‘ The one who eats my bread my bread has turned against me.’'
EXEC add_BibleVerse @BibleId, 343013019, N'I am telling you this now, before it happens, so that when it happens you may believe that I am he.'
EXEC add_BibleVerse @BibleId, 343013020, N'I tell you the solemn truth, whoever accepts the one I send accepts me, and whoever accepts me accepts the one who sent me.”'
EXEC add_BibleVerse @BibleId, 343013021, N'When he had said these things, Jesus was greatly distressed in spirit, and testified, “I tell you the solemn truth, one of you will betray me.”'
EXEC add_BibleVerse @BibleId, 343013022, N'The disciples began to look at one another, worried and perplexed to know which of them he was talking about.'
EXEC add_BibleVerse @BibleId, 343013023, N'One of his disciples, the one Jesus loved, was at the table to the right of Jesus in a place of honor.'
EXEC add_BibleVerse @BibleId, 343013024, N'So Simon Peter gestured to this disciple to ask Jesus who it was he was referring to.'
EXEC add_BibleVerse @BibleId, 343013025, N'Then the disciple whom Jesus loved leaned back against Jesus’ chest and asked him, “Lord, who is it?”'
EXEC add_BibleVerse @BibleId, 343013026, N'Jesus replied, “It is the one to whom I will give this piece of bread after I have dipped it in the dish.” Then he dipped the piece of bread in the dish and gave it to Judas Iscariot, Simon’s son.'
EXEC add_BibleVerse @BibleId, 343013027, N'And after Judas took the piece of bread, Satan entered into him. Jesus said to him, “What you are about to do, do quickly.”'
EXEC add_BibleVerse @BibleId, 343013028, N'(Now none of those present at the table understood why Jesus said this to Judas.'
EXEC add_BibleVerse @BibleId, 343013029, N'Some thought that, because Judas had the money box, Jesus was telling him to buy whatever they needed for the feast, or to give something to the poor.)'
EXEC add_BibleVerse @BibleId, 343013030, N'Judas took the piece of bread and went out immediately. (Now it was night.)'
EXEC add_BibleVerse @BibleId, 343013031, N'When Judas had gone out, Jesus said, “Now the Son of Man is glorified, and God is glorified in him.'
EXEC add_BibleVerse @BibleId, 343013032, N'If God is glorified in him, God will also glorify him in himself, and he will glorify him right away.'
EXEC add_BibleVerse @BibleId, 343013033, N'Children, I am still with you for a little while. You will look for me, and just as I said to the Jewish religious leaders, ‘Where I am going you cannot come,’ now I tell you the same.'
EXEC add_BibleVerse @BibleId, 343013034, N'“I give you a new commandment – to love one another. Just as I have loved you, you also are to love one another.'
EXEC add_BibleVerse @BibleId, 343013035, N'Everyone will know by this that you are my disciples – if you have love for one another.”'
EXEC add_BibleVerse @BibleId, 343013036, N'Simon Peter said to him, “Lord, where are you going?” Jesus replied, “Where I am going, you cannot follow me now, but you will follow later.”'
EXEC add_BibleVerse @BibleId, 343013037, N'Peter said to him, “Lord, why can’t I follow you now? I will lay down my life for you!”'
EXEC add_BibleVerse @BibleId, 343013038, N'Jesus answered, “Will you lay down your life for me? I tell you the solemn truth, the rooster will not crow until you have denied me three times!'
EXEC add_BibleVerse @BibleId, 343014001, N'“Do not let your hearts be distressed. You believe in God; believe also in me.'
EXEC add_BibleVerse @BibleId, 343014002, N'There are many dwelling places in my Father’s house. Otherwise, I would have told you, because I am going away to make ready a place for you.'
EXEC add_BibleVerse @BibleId, 343014003, N'And if I go and make ready a place for you, I will come again and take you to be with me, so that where I am you may be too.'
EXEC add_BibleVerse @BibleId, 343014004, N'And you know the way where I am going.”'
EXEC add_BibleVerse @BibleId, 343014005, N'Thomas said, “Lord, we don’t know where you are going. How can we know the way?”'
EXEC add_BibleVerse @BibleId, 343014006, N'Jesus replied, “I am the way, and the truth, and the life. No one comes to the Father except through me.'
EXEC add_BibleVerse @BibleId, 343014007, N'If you have known me, you will know my Father too. And from now on you do know him and have seen him.”'
EXEC add_BibleVerse @BibleId, 343014008, N'Philip said, “Lord, show us the Father, and we will be content.”'
EXEC add_BibleVerse @BibleId, 343014009, N'Jesus replied, “Have I been with you for so long, and you have not known me, Philip? The person who has seen me has seen the Father! How can you say, ‘Show us the Father’?'
EXEC add_BibleVerse @BibleId, 343014010, N'Do you not believe that I am in the Father, and the Father is in me? The words that I say to you, I do not speak on my own initiative, but the Father residing in me performs his miraculous deeds.'
EXEC add_BibleVerse @BibleId, 343014011, N'Believe me that I am in the Father, and the Father is in me, but if you do not believe me, believe because of the miraculous deeds themselves.'
EXEC add_BibleVerse @BibleId, 343014012, N'I tell you the solemn truth, the person who believes in me will perform the miraculous deeds that I am doing, and will perform greater deeds than these, because I am going to the Father.'
EXEC add_BibleVerse @BibleId, 343014013, N'And I will do whatever you ask in my name, so that the Father may be glorified in the Son.'
EXEC add_BibleVerse @BibleId, 343014014, N'If you ask me anything in my name, I will do it.'
EXEC add_BibleVerse @BibleId, 343014015, N'“If you love me, you will obey my commandments.'
EXEC add_BibleVerse @BibleId, 343014016, N'Then I will ask the Father, and he will give you another Advocate to be with you forever –'
EXEC add_BibleVerse @BibleId, 343014017, N'the Spirit of truth, whom the world cannot accept, because it does not see him or know him. But you know him, because he resides with you and will be in you.'
EXEC add_BibleVerse @BibleId, 343014018, N'“I will not abandon you as orphans, I will come to you.'
EXEC add_BibleVerse @BibleId, 343014019, N'In a little while the world will not see me any longer, but you will see me; because I live, you will live too.'
EXEC add_BibleVerse @BibleId, 343014020, N'You will know at that time that I am in my Father and you are in me and I am in you.'
EXEC add_BibleVerse @BibleId, 343014021, N'The person who has my commandments and obeys them is the one who loves me. The one who loves me will be loved by my Father, and I will love him and will reveal myself to him.”'
EXEC add_BibleVerse @BibleId, 343014022, N'“Lord,” Judas (not Judas Iscariot) said, “what has happened that you are going to reveal yourself to us and not to the world?”'
EXEC add_BibleVerse @BibleId, 343014023, N'Jesus replied, “If anyone loves me, he will obey my word, and my Father will love him, and we will come to him and take up residence with him.'
EXEC add_BibleVerse @BibleId, 343014024, N'The person who does not love me does not obey my words. And the word you hear is not mine, but the Father’s who sent me.'
EXEC add_BibleVerse @BibleId, 343014025, N'“I have spoken these things while staying with you.'
EXEC add_BibleVerse @BibleId, 343014026, N'But the Advocate, the Holy Spirit, whom the Father will send in my name, will teach you everything, and will cause you to remember everything I said to you.'
EXEC add_BibleVerse @BibleId, 343014027, N'“Peace I leave with you; my peace I give to you; I do not give it to you as the world does. Do not let your hearts be distressed or lacking in courage.'
EXEC add_BibleVerse @BibleId, 343014028, N'You heard me say to you, ‘I am going away and I am coming back to you.’ If you loved me, you would be glad that I am going to the Father, because the Father is greater than I am.'
EXEC add_BibleVerse @BibleId, 343014029, N'I have told you now before it happens, so that when it happens you may believe.'
EXEC add_BibleVerse @BibleId, 343014030, N'I will not speak with you much longer, for the ruler of this world is coming. He has no power over me,'
EXEC add_BibleVerse @BibleId, 343014031, N'but I am doing just what the Father commanded me, so that the world may know that I love the Father. Get up, let us go from here.”'
EXEC add_BibleVerse @BibleId, 343015001, N'“I am the true vine and my Father is the gardener.'
EXEC add_BibleVerse @BibleId, 343015002, N'He takes away every branch that does not bear fruit in me. He prunes every branch that bears fruit so that it will bear more fruit.'
EXEC add_BibleVerse @BibleId, 343015003, N'You are clean already because of the word that I have spoken to you.'
EXEC add_BibleVerse @BibleId, 343015004, N'Remain in me, and I will remain in you. Just as the branch cannot bear fruit by itself, unless it remains in the vine, so neither can you unless you remain in me.'
EXEC add_BibleVerse @BibleId, 343015005, N'“I am the vine; you are the branches. The one who remains in me – and I in him – bears much fruit, because apart from me you can accomplish nothing.'
EXEC add_BibleVerse @BibleId, 343015006, N'If anyone does not remain in me, he is thrown out like a branch, and dries up; and such branches are gathered up and thrown into the fire, and are burned up.'
EXEC add_BibleVerse @BibleId, 343015007, N'If you remain in me and my words remain in you, ask whatever you want, and it will be done for you.'
EXEC add_BibleVerse @BibleId, 343015008, N'My Father is honored by this, that you bear much fruit and show that you are my disciples.'
EXEC add_BibleVerse @BibleId, 343015009, N'“Just as the Father has loved me, I have also loved you; remain in my love.'
EXEC add_BibleVerse @BibleId, 343015010, N'If you obey my commandments, you will remain in my love, just as I have obeyed my Father’s commandments and remain in his love.'
EXEC add_BibleVerse @BibleId, 343015011, N'I have told you these things so that my joy may be in you, and your joy may be complete.'
EXEC add_BibleVerse @BibleId, 343015012, N'My commandment is this – to love one another just as I have loved you.'
EXEC add_BibleVerse @BibleId, 343015013, N'No one has greater love than this – that one lays down his life for his friends.'
EXEC add_BibleVerse @BibleId, 343015014, N'You are my friends if you do what I command you.'
EXEC add_BibleVerse @BibleId, 343015015, N'I no longer call you slaves, because the slave does not understand what his master is doing. But I have called you friends, because I have revealed to you everything I heard from my Father.'
EXEC add_BibleVerse @BibleId, 343015016, N'You did not choose me, but I chose you and appointed you to go and bear fruit, fruit that remains, so that whatever you ask the Father in my name he will give you.'
EXEC add_BibleVerse @BibleId, 343015017, N'This I command you – to love one another.'
EXEC add_BibleVerse @BibleId, 343015018, N'“If the world hates you, be aware that it hated me first.'
EXEC add_BibleVerse @BibleId, 343015019, N'If you belonged to the world, the world would love you as its own. However, because you do not belong to the world, but I chose you out of the world, for this reason the world hates you.'
EXEC add_BibleVerse @BibleId, 343015020, N'Remember what I told you, ‘A slave is not greater than his master.’ If they persecuted me, they will also persecute you. If they obeyed my word, they will obey yours too.'
EXEC add_BibleVerse @BibleId, 343015021, N'But they will do all these things to you on account of my name, because they do not know the one who sent me.'
EXEC add_BibleVerse @BibleId, 343015022, N'If I had not come and spoken to them, they would not be guilty of sin. But they no longer have any excuse for their sin.'
EXEC add_BibleVerse @BibleId, 343015023, N'The one who hates me hates my Father too.'
EXEC add_BibleVerse @BibleId, 343015024, N'If I had not performed among them the miraculous deeds that no one else did, they would not be guilty of sin. But now they have seen the deeds and have hated both me and my Father.'
EXEC add_BibleVerse @BibleId, 343015025, N'Now this happened to fulfill the word that is written in their law, ‘ They hated me without reason.’'
EXEC add_BibleVerse @BibleId, 343015026, N'When the Advocate comes, whom I will send you from the Father – the Spirit of truth who goes out from the Father – he will testify about me,'
EXEC add_BibleVerse @BibleId, 343015027, N'and you also will testify, because you have been with me from the beginning.'
EXEC add_BibleVerse @BibleId, 343016001, N'“I have told you all these things so that you will not fall away.'
EXEC add_BibleVerse @BibleId, 343016002, N'They will put you out of the synagogue, yet a time is coming when the one who kills you will think he is offering service to God.'
EXEC add_BibleVerse @BibleId, 343016003, N'They will do these things because they have not known the Father or me.'
EXEC add_BibleVerse @BibleId, 343016004, N'But I have told you these things so that when their time comes, you will remember that I told you about them. “I did not tell you these things from the beginning because I was with you.'
EXEC add_BibleVerse @BibleId, 343016005, N'But now I am going to the one who sent me, and not one of you is asking me, ‘Where are you going?’'
EXEC add_BibleVerse @BibleId, 343016006, N'Instead your hearts are filled with sadness because I have said these things to you.'
EXEC add_BibleVerse @BibleId, 343016007, N'But I tell you the truth, it is to your advantage that I am going away. For if I do not go away, the Advocate will not come to you, but if I go, I will send him to you.'
EXEC add_BibleVerse @BibleId, 343016008, N'And when he comes, he will prove the world wrong concerning sin and righteousness and judgment –'
EXEC add_BibleVerse @BibleId, 343016009, N'concerning sin, because they do not believe in me;'
EXEC add_BibleVerse @BibleId, 343016010, N'concerning righteousness, because I am going to the Father and you will see me no longer;'
EXEC add_BibleVerse @BibleId, 343016011, N'and concerning judgment, because the ruler of this world has been condemned.'
EXEC add_BibleVerse @BibleId, 343016012, N'“I have many more things to say to you, but you cannot bear them now.'
EXEC add_BibleVerse @BibleId, 343016013, N'But when he, the Spirit of truth, comes, he will guide you into all truth. For he will not speak on his own authority, but will speak whatever he hears, and will tell you what is to come.'
EXEC add_BibleVerse @BibleId, 343016014, N'He will glorify me, because he will receive from me what is mine and will tell it to you.'
EXEC add_BibleVerse @BibleId, 343016015, N'Everything that the Father has is mine; that is why I said the Spirit will receive from me what is mine and will tell it to you.'
EXEC add_BibleVerse @BibleId, 343016016, N'In a little while you will see me no longer; again after a little while, you will see me.”'
EXEC add_BibleVerse @BibleId, 343016017, N'Then some of his disciples said to one another, “What is the meaning of what he is saying, ‘In a little while you will not see me; again after a little while, you will see me,’ and, ‘because I am going to the Father’?”'
EXEC add_BibleVerse @BibleId, 343016018, N'So they kept on repeating, “What is the meaning of what he says, ‘In a little while’? We do not understand what he is talking about.”'
EXEC add_BibleVerse @BibleId, 343016019, N'Jesus could see that they wanted to ask him about these things, so he said to them, “Are you asking each other about this – that I said, ‘In a little while you will not see me; again after a little while, you will see me’?'
EXEC add_BibleVerse @BibleId, 343016020, N'I tell you the solemn truth, you will weep and wail, but the world will rejoice; you will be sad, but your sadness will turn into joy.'
EXEC add_BibleVerse @BibleId, 343016021, N'When a woman gives birth, she has distress because her time has come, but when her child is born, she no longer remembers the suffering because of her joy that a human being has been born into the world.'
EXEC add_BibleVerse @BibleId, 343016022, N'So also you have sorrow now, but I will see you again, and your hearts will rejoice, and no one will take your joy away from you.'
EXEC add_BibleVerse @BibleId, 343016023, N'At that time you will ask me nothing. I tell you the solemn truth, whatever you ask the Father in my name he will give you.'
EXEC add_BibleVerse @BibleId, 343016024, N'Until now you have not asked for anything in my name. Ask and you will receive it, so that your joy may be complete.'
EXEC add_BibleVerse @BibleId, 343016025, N'“I have told you these things in obscure figures of speech; a time is coming when I will no longer speak to you in obscure figures, but will tell you plainly about the Father.'
EXEC add_BibleVerse @BibleId, 343016026, N'At that time you will ask in my name, and I do not say that I will ask the Father on your behalf.'
EXEC add_BibleVerse @BibleId, 343016027, N'For the Father himself loves you, because you have loved me and have believed that I came from God.'
EXEC add_BibleVerse @BibleId, 343016028, N'I came from the Father and entered into the world, but in turn, I am leaving the world and going back to the Father.”'
EXEC add_BibleVerse @BibleId, 343016029, N'His disciples said, “Look, now you are speaking plainly and not in obscure figures of speech!'
EXEC add_BibleVerse @BibleId, 343016030, N'Now we know that you know everything and do not need anyone to ask you anything. Because of this we believe that you have come from God.”'
EXEC add_BibleVerse @BibleId, 343016031, N'Jesus replied, “Do you now believe?'
EXEC add_BibleVerse @BibleId, 343016032, N'Look, a time is coming – and has come – when you will be scattered, each one to his own home, and I will be left alone. Yet I am not alone, because my Father is with me.'
EXEC add_BibleVerse @BibleId, 343016033, N'I have told you these things so that in me you may have peace. In the world you have trouble and suffering, but take courage – I have conquered the world.”'
EXEC add_BibleVerse @BibleId, 343017001, N'When Jesus had finished saying these things, he looked upward to heaven and said, “Father, the time has come. Glorify your Son, so that your Son may glorify you –'
EXEC add_BibleVerse @BibleId, 343017002, N'just as you have given him authority over all humanity, so that he may give eternal life to everyone you have given him.'
EXEC add_BibleVerse @BibleId, 343017003, N'Now this is eternal life – that they know you, the only true God, and Jesus Christ, whom you sent.'
EXEC add_BibleVerse @BibleId, 343017004, N'I glorified you on earth by completing the work you gave me to do.'
EXEC add_BibleVerse @BibleId, 343017005, N'And now, Father, glorify me at your side with the glory I had with you before the world was created.'
EXEC add_BibleVerse @BibleId, 343017006, N'“I have revealed your name to the men you gave me out of the world. They belonged to you, and you gave them to me, and they have obeyed your word.'
EXEC add_BibleVerse @BibleId, 343017007, N'Now they understand that everything you have given me comes from you,'
EXEC add_BibleVerse @BibleId, 343017008, N'because I have given them the words you have given me. They accepted them and really understand that I came from you, and they believed that you sent me.'
EXEC add_BibleVerse @BibleId, 343017009, N'I am praying on behalf of them. I am not praying on behalf of the world, but on behalf of those you have given me, because they belong to you.'
EXEC add_BibleVerse @BibleId, 343017010, N'Everything I have belongs to you, and everything you have belongs to me, and I have been glorified by them.'
EXEC add_BibleVerse @BibleId, 343017011, N'I am no longer in the world, but they are in the world, and I am coming to you. Holy Father, keep them safe in your name that you have given me, so that they may be one just as we are one.'
EXEC add_BibleVerse @BibleId, 343017012, N'When I was with them I kept them safe and watched over them in your name that you have given me. Not one of them was lost except the one destined for destruction, so that the scripture could be fulfilled.'
EXEC add_BibleVerse @BibleId, 343017013, N'But now I am coming to you, and I am saying these things in the world, so they may experience my joy completed in themselves.'
EXEC add_BibleVerse @BibleId, 343017014, N'I have given them your word, and the world has hated them, because they do not belong to the world, just as I do not belong to the world.'
EXEC add_BibleVerse @BibleId, 343017015, N'I am not asking you to take them out of the world, but that you keep them safe from the evil one.'
EXEC add_BibleVerse @BibleId, 343017016, N'They do not belong to the world just as I do not belong to the world.'
EXEC add_BibleVerse @BibleId, 343017017, N'Set them apart in the truth; your word is truth.'
EXEC add_BibleVerse @BibleId, 343017018, N'Just as you sent me into the world, so I sent them into the world.'
EXEC add_BibleVerse @BibleId, 343017019, N'And I set myself apart on their behalf, so that they too may be truly set apart.'
EXEC add_BibleVerse @BibleId, 343017020, N'“I am not praying only on their behalf, but also on behalf of those who believe in me through their testimony,'
EXEC add_BibleVerse @BibleId, 343017021, N'that they will all be one, just as you, Father, are in me and I am in you. I pray that they will be in us, so that the world will believe that you sent me.'
EXEC add_BibleVerse @BibleId, 343017022, N'The glory you gave to me I have given to them, that they may be one just as we are one –'
EXEC add_BibleVerse @BibleId, 343017023, N'I in them and you in me – that they may be completely one, so that the world will know that you sent me, and you have loved them just as you have loved me.'
EXEC add_BibleVerse @BibleId, 343017024, N'“Father, I want those you have given me to be with me where I am, so that they can see my glory that you gave me because you loved me before the creation of the world .'
EXEC add_BibleVerse @BibleId, 343017025, N'Righteous Father, even if the world does not know you, I know you, and these men know that you sent me.'
EXEC add_BibleVerse @BibleId, 343017026, N'I made known your name to them, and I will continue to make it known, so that the love you have loved me with may be in them, and I may be in them.”'
EXEC add_BibleVerse @BibleId, 343018001, N'When he had said these things, Jesus went out with his disciples across the Kidron Valley. There was an orchard there, and he and his disciples went into it.'
EXEC add_BibleVerse @BibleId, 343018002, N'(Now Judas, the one who betrayed him, knew the place too, because Jesus had met there many times with his disciples.)'
EXEC add_BibleVerse @BibleId, 343018003, N'So Judas obtained a squad of soldiers and some officers of the chief priests and Pharisees. They came to the orchard with lanterns and torches and weapons.'
EXEC add_BibleVerse @BibleId, 343018004, N'Then Jesus, because he knew everything that was going to happen to him, came and asked them, “Who are you looking for?”'
EXEC add_BibleVerse @BibleId, 343018005, N'They replied, “Jesus the Nazarene.” He told them, “I am he.” (Now Judas, the one who betrayed him, was standing there with them.)'
EXEC add_BibleVerse @BibleId, 343018006, N'So when Jesus said to them, “I am he,” they retreated and fell to the ground.'
EXEC add_BibleVerse @BibleId, 343018007, N'Then Jesus asked them again, “Who are you looking for?” And they said, “Jesus the Nazarene.”'
EXEC add_BibleVerse @BibleId, 343018008, N'Jesus replied, “I told you that I am he. If you are looking for me, let these men go.”'
EXEC add_BibleVerse @BibleId, 343018009, N'He said this to fulfill the word he had spoken, “I have not lost a single one of those whom you gave me.”'
EXEC add_BibleVerse @BibleId, 343018010, N'Then Simon Peter, who had a sword, pulled it out and struck the high priest’s slave, cutting off his right ear. (Now the slave’s name was Malchus.)'
EXEC add_BibleVerse @BibleId, 343018011, N'But Jesus said to Peter, “Put your sword back into its sheath! Am I not to drink the cup that the Father has given me?”'
EXEC add_BibleVerse @BibleId, 343018012, N'Then the squad of soldiers with their commanding officer and the officers of the Jewish leaders arrested Jesus and tied him up.'
EXEC add_BibleVerse @BibleId, 343018013, N'They brought him first to Annas, for he was the father-in-law of Caiaphas, who was high priest that year.'
EXEC add_BibleVerse @BibleId, 343018014, N'(Now it was Caiaphas who had advised the Jewish leaders that it was to their advantage that one man die for the people.)'
EXEC add_BibleVerse @BibleId, 343018015, N'Simon Peter and another disciple followed them as they brought Jesus to Annas. (Now the other disciple was acquainted with the high priest, and he went with Jesus into the high priest’s courtyard.)'
EXEC add_BibleVerse @BibleId, 343018016, N'But Simon Peter was left standing outside by the door. So the other disciple who was acquainted with the high priest came out and spoke to the slave girl who watched the door, and brought Peter inside.'
EXEC add_BibleVerse @BibleId, 343018017, N'The girl who was the doorkeeper said to Peter, “You’re not one of this man’s disciples too, are you?” He replied, “I am not.”'
EXEC add_BibleVerse @BibleId, 343018018, N'(Now the slaves and the guards were standing around a charcoal fire they had made, warming themselves because it was cold. Peter also was standing with them, warming himself.)'
EXEC add_BibleVerse @BibleId, 343018019, N'While this was happening, the high priest questioned Jesus about his disciples and about his teaching.'
EXEC add_BibleVerse @BibleId, 343018020, N'Jesus replied, “I have spoken publicly to the world. I always taught in the synagogues and in the temple courts, where all the Jewish people assemble together. I have said nothing in secret.'
EXEC add_BibleVerse @BibleId, 343018021, N'Why do you ask me? Ask those who heard what I said. They know what I said.”'
EXEC add_BibleVerse @BibleId, 343018022, N'When Jesus had said this, one of the high priest’s officers who stood nearby struck him on the face and said, “Is that the way you answer the high priest?”'
EXEC add_BibleVerse @BibleId, 343018023, N'Jesus replied, “If I have said something wrong, confirm what is wrong. But if I spoke correctly, why strike me?”'
EXEC add_BibleVerse @BibleId, 343018024, N'Then Annas sent him, still tied up, to Caiaphas the high priest.'
EXEC add_BibleVerse @BibleId, 343018025, N'Meanwhile Simon Peter was standing in the courtyard warming himself. They said to him, “You aren’t one of his disciples too, are you?” Peter denied it: “I am not!”'
EXEC add_BibleVerse @BibleId, 343018026, N'One of the high priest’s slaves, a relative of the man whose ear Peter had cut off, said, “Did I not see you in the orchard with him?”'
EXEC add_BibleVerse @BibleId, 343018027, N'Then Peter denied it again, and immediately a rooster crowed.'
EXEC add_BibleVerse @BibleId, 343018028, N'Then they brought Jesus from Caiaphas to the Roman governor’s residence. (Now it was very early morning.) They did not go into the governor’s residence so they would not be ceremonially defiled, but could eat the Passover meal.'
EXEC add_BibleVerse @BibleId, 343018029, N'So Pilate came outside to them and said, “What accusation do you bring against this man?”'
EXEC add_BibleVerse @BibleId, 343018030, N'They replied, “If this man were not a criminal, we would not have handed him over to you.”'
EXEC add_BibleVerse @BibleId, 343018031, N'Pilate told them, “Take him yourselves and pass judgment on him according to your own law!” The Jewish leaders replied, “We cannot legally put anyone to death.”'
EXEC add_BibleVerse @BibleId, 343018032, N'(This happened to fulfill the word Jesus had spoken when he indicated what kind of death he was going to die. )'
EXEC add_BibleVerse @BibleId, 343018033, N'So Pilate went back into the governor’s residence, summoned Jesus, and asked him, “Are you the king of the Jews?”'
EXEC add_BibleVerse @BibleId, 343018034, N'Jesus replied, “Are you saying this on your own initiative, or have others told you about me?”'
EXEC add_BibleVerse @BibleId, 343018035, N'Pilate answered, “I am not a Jew, am I? Your own people and your chief priests handed you over to me. What have you done?”'
EXEC add_BibleVerse @BibleId, 343018036, N'Jesus replied, “My kingdom is not from this world. If my kingdom were from this world, my servants would be fighting to keep me from being handed over to the Jewish authorities. But as it is, my kingdom is not from here.”'
EXEC add_BibleVerse @BibleId, 343018037, N'Then Pilate said, “So you are a king!” Jesus replied, “You say that I am a king. For this reason I was born, and for this reason I came into the world – to testify to the truth. Everyone who belongs to the truth listens to my voice.”'
EXEC add_BibleVerse @BibleId, 343018038, N'Pilate asked, “What is truth?” When he had said this he went back outside to the Jewish leaders and announced, “I find no basis for an accusation against him.'
EXEC add_BibleVerse @BibleId, 343018039, N'But it is your custom that I release one prisoner for you at the Passover. So do you want me to release for you the king of the Jews?”'
EXEC add_BibleVerse @BibleId, 343018040, N'Then they shouted back, “Not this man, but Barabbas!” (Now Barabbas was a revolutionary. )'
EXEC add_BibleVerse @BibleId, 343019001, N'Then Pilate took Jesus and had him flogged severely.'
EXEC add_BibleVerse @BibleId, 343019002, N'The soldiers braided a crown of thorns and put it on his head, and they clothed him in a purple robe.'
EXEC add_BibleVerse @BibleId, 343019003, N'They came up to him again and again and said, “Hail, king of the Jews!” And they struck him repeatedly in the face.'
EXEC add_BibleVerse @BibleId, 343019004, N'Again Pilate went out and said to the Jewish leaders, “Look, I am bringing him out to you, so that you may know that I find no reason for an accusation against him.”'
EXEC add_BibleVerse @BibleId, 343019005, N'So Jesus came outside, wearing the crown of thorns and the purple robe. Pilate said to them, “Look, here is the man!”'
EXEC add_BibleVerse @BibleId, 343019006, N'When the chief priests and their officers saw him, they shouted out, “Crucify him! Crucify him!” Pilate said, “You take him and crucify him! Certainly I find no reason for an accusation against him!”'
EXEC add_BibleVerse @BibleId, 343019007, N'The Jewish leaders replied, “We have a law, and according to our law he ought to die, because he claimed to be the Son of God!”'
EXEC add_BibleVerse @BibleId, 343019008, N'When Pilate heard what they said, he was more afraid than ever,'
EXEC add_BibleVerse @BibleId, 343019009, N'and he went back into the governor’s residence and said to Jesus, “Where do you come from?” But Jesus gave him no answer.'
EXEC add_BibleVerse @BibleId, 343019010, N'So Pilate said, “Do you refuse to speak to me? Don’t you know I have the authority to release you, and to crucify you?”'
EXEC add_BibleVerse @BibleId, 343019011, N'Jesus replied, “You would have no authority over me at all, unless it was given to you from above. Therefore the one who handed me over to you is guilty of greater sin.”'
EXEC add_BibleVerse @BibleId, 343019012, N'From this point on, Pilate tried to release him. But the Jewish leaders shouted out, “If you release this man, you are no friend of Caesar! Everyone who claims to be a king opposes Caesar!”'
EXEC add_BibleVerse @BibleId, 343019013, N'When Pilate heard these words he brought Jesus outside and sat down on the judgment seat in the place called “The Stone Pavement” ( Gabbatha in Aramaic).'
EXEC add_BibleVerse @BibleId, 343019014, N'(Now it was the day of preparation for the Passover, about noon. ) Pilate said to the Jewish leaders, “Look, here is your king!”'
EXEC add_BibleVerse @BibleId, 343019015, N'Then they shouted out, “Away with him! Away with him! Crucify him!” Pilate asked, “Shall I crucify your king?” The high priests replied, “We have no king except Caesar!”'
EXEC add_BibleVerse @BibleId, 343019016, N'Then Pilate handed him over to them to be crucified. So they took Jesus,'
EXEC add_BibleVerse @BibleId, 343019017, N'and carrying his own cross he went out to the place called “The Place of the Skull” (called in Aramaic Golgotha).'
EXEC add_BibleVerse @BibleId, 343019018, N'There they crucified him along with two others, one on each side, with Jesus in the middle.'
EXEC add_BibleVerse @BibleId, 343019019, N'Pilate also had a notice written and fastened to the cross, which read: “Jesus the Nazarene, the king of the Jews.”'
EXEC add_BibleVerse @BibleId, 343019020, N'Thus many of the Jewish residents of Jerusalem read this notice, because the place where Jesus was crucified was near the city, and the notice was written in Aramaic, Latin, and Greek.'
EXEC add_BibleVerse @BibleId, 343019021, N'Then the chief priests of the Jews said to Pilate, “Do not write, ‘The king of the Jews,’ but rather, ‘This man said, I am king of the Jews.’”'
EXEC add_BibleVerse @BibleId, 343019022, N'Pilate answered, “What I have written, I have written.”'
EXEC add_BibleVerse @BibleId, 343019023, N'Now when the soldiers crucified Jesus, they took his clothes and made four shares, one for each soldier, and the tunic remained. (Now the tunic was seamless, woven from top to bottom as a single piece.)'
EXEC add_BibleVerse @BibleId, 343019024, N'So the soldiers said to one another, “Let’s not tear it, but throw dice to see who will get it.” This took place to fulfill the scripture that says, “ They divided my garments among them, and for my clothing they threw dice.” So the soldiers did these things.'
EXEC add_BibleVerse @BibleId, 343019025, N'Now standing beside Jesus’ cross were his mother, his mother’s sister, Mary the wife of Clopas, and Mary Magdalene.'
EXEC add_BibleVerse @BibleId, 343019026, N'So when Jesus saw his mother and the disciple whom he loved standing there, he said to his mother, “Woman, look, here is your son!”'
EXEC add_BibleVerse @BibleId, 343019027, N'He then said to his disciple, “Look, here is your mother!” From that very time the disciple took her into his own home.'
EXEC add_BibleVerse @BibleId, 343019028, N'After this Jesus, realizing that by this time everything was completed, said (in order to fulfill the scripture), “I am thirsty!”'
EXEC add_BibleVerse @BibleId, 343019029, N'A jar full of sour wine was there, so they put a sponge soaked in sour wine on a branch of hyssop and lifted it to his mouth.'
EXEC add_BibleVerse @BibleId, 343019030, N'When he had received the sour wine, Jesus said, “It is completed!” Then he bowed his head and gave up his spirit.'
EXEC add_BibleVerse @BibleId, 343019031, N'Then, because it was the day of preparation, so that the bodies should not stay on the crosses on the Sabbath (for that Sabbath was an especially important one), the Jewish leaders asked Pilate to have the victims’ legs broken and the bodies taken down.'
EXEC add_BibleVerse @BibleId, 343019032, N'So the soldiers came and broke the legs of the two men who had been crucified with Jesus, first the one and then the other.'
EXEC add_BibleVerse @BibleId, 343019033, N'But when they came to Jesus and saw that he was already dead, they did not break his legs.'
EXEC add_BibleVerse @BibleId, 343019034, N'But one of the soldiers pierced his side with a spear, and blood and water flowed out immediately.'
EXEC add_BibleVerse @BibleId, 343019035, N'And the person who saw it has testified (and his testimony is true, and he knows that he is telling the truth), so that you also may believe.'
EXEC add_BibleVerse @BibleId, 343019036, N'For these things happened so that the scripture would be fulfilled, “ Not a bone of his will be broken.”'
EXEC add_BibleVerse @BibleId, 343019037, N'And again another scripture says, “ They will look on the one whom they have pierced.”'
EXEC add_BibleVerse @BibleId, 343019038, N'After this, Joseph of Arimathea, a disciple of Jesus (but secretly, because he feared the Jewish leaders ), asked Pilate if he could remove the body of Jesus. Pilate gave him permission, so he went and took the body away.'
EXEC add_BibleVerse @BibleId, 343019039, N'Nicodemus, the man who had previously come to Jesus at night, accompanied Joseph, carrying a mixture of myrrh and aloes weighing about seventy-five pounds.'
EXEC add_BibleVerse @BibleId, 343019040, N'Then they took Jesus’ body and wrapped it, with the aromatic spices, in strips of linen cloth according to Jewish burial customs.'
EXEC add_BibleVerse @BibleId, 343019041, N'Now at the place where Jesus was crucified there was a garden, and in the garden was a new tomb where no one had yet been buried.'
EXEC add_BibleVerse @BibleId, 343019042, N'And so, because it was the Jewish day of preparation and the tomb was nearby, they placed Jesus’ body there.'
EXEC add_BibleVerse @BibleId, 343020001, N'Now very early on the first day of the week, while it was still dark, Mary Magdalene came to the tomb and saw that the stone had been moved away from the entrance.'
EXEC add_BibleVerse @BibleId, 343020002, N'So she went running to Simon Peter and the other disciple whom Jesus loved and told them, “They have taken the Lord from the tomb, and we don’t know where they have put him!”'
EXEC add_BibleVerse @BibleId, 343020003, N'Then Peter and the other disciple set out to go to the tomb.'
EXEC add_BibleVerse @BibleId, 343020004, N'The two were running together, but the other disciple ran faster than Peter and reached the tomb first.'
EXEC add_BibleVerse @BibleId, 343020005, N'He bent down and saw the strips of linen cloth lying there, but he did not go in.'
EXEC add_BibleVerse @BibleId, 343020006, N'Then Simon Peter, who had been following him, arrived and went right into the tomb. He saw the strips of linen cloth lying there,'
EXEC add_BibleVerse @BibleId, 343020007, N'and the face cloth, which had been around Jesus’ head, not lying with the strips of linen cloth but rolled up in a place by itself.'
EXEC add_BibleVerse @BibleId, 343020008, N'Then the other disciple, who had reached the tomb first, came in, and he saw and believed.'
EXEC add_BibleVerse @BibleId, 343020009, N'(For they did not yet understand the scripture that Jesus must rise from the dead.)'
EXEC add_BibleVerse @BibleId, 343020010, N'So the disciples went back to their homes.'
EXEC add_BibleVerse @BibleId, 343020011, N'But Mary stood outside the tomb weeping. As she wept, she bent down and looked into the tomb.'
EXEC add_BibleVerse @BibleId, 343020012, N'And she saw two angels in white sitting where Jesus’ body had been lying, one at the head and one at the feet.'
EXEC add_BibleVerse @BibleId, 343020013, N'They said to her, “Woman, why are you weeping?” Mary replied, “They have taken my Lord away, and I do not know where they have put him!”'
EXEC add_BibleVerse @BibleId, 343020014, N'When she had said this, she turned around and saw Jesus standing there, but she did not know that it was Jesus.'
EXEC add_BibleVerse @BibleId, 343020015, N'Jesus said to her, “Woman, why are you weeping? Who are you looking for?” Because she thought he was the gardener, she said to him, “Sir, if you have carried him away, tell me where you have put him, and I will take him.”'
EXEC add_BibleVerse @BibleId, 343020016, N'Jesus said to her, “Mary.” She turned and said to him in Aramaic, “ Rabboni” (which means Teacher).'
EXEC add_BibleVerse @BibleId, 343020017, N'Jesus replied, “Do not touch me, for I have not yet ascended to my Father. Go to my brothers and tell them, ‘I am ascending to my Father and your Father, to my God and your God.’”'
EXEC add_BibleVerse @BibleId, 343020018, N'Mary Magdalene came and informed the disciples, “I have seen the Lord!” And she told them what Jesus had said to her.'
EXEC add_BibleVerse @BibleId, 343020019, N'On the evening of that day, the first day of the week, the disciples had gathered together and locked the doors of the place because they were afraid of the Jewish leaders. Jesus came and stood among them and said to them, “Peace be with you.”'
EXEC add_BibleVerse @BibleId, 343020020, N'When he had said this, he showed them his hands and his side. Then the disciples rejoiced when they saw the Lord.'
EXEC add_BibleVerse @BibleId, 343020021, N'So Jesus said to them again, “Peace be with you. Just as the Father has sent me, I also send you.”'
EXEC add_BibleVerse @BibleId, 343020022, N'And after he said this, he breathed on them and said, “Receive the Holy Spirit.'
EXEC add_BibleVerse @BibleId, 343020023, N'If you forgive anyone’s sins, they are forgiven; if you retain anyone’s sins, they are retained.”'
EXEC add_BibleVerse @BibleId, 343020024, N'Now Thomas (called Didymus), one of the twelve, was not with them when Jesus came.'
EXEC add_BibleVerse @BibleId, 343020025, N'The other disciples told him, “We have seen the Lord!” But he replied, “Unless I see the wounds from the nails in his hands, and put my finger into the wounds from the nails, and put my hand into his side, I will never believe it!”'
EXEC add_BibleVerse @BibleId, 343020026, N'Eight days later the disciples were again together in the house, and Thomas was with them. Although the doors were locked, Jesus came and stood among them and said, “Peace be with you!”'
EXEC add_BibleVerse @BibleId, 343020027, N'Then he said to Thomas, “Put your finger here, and examine my hands. Extend your hand and put it into my side. Do not continue in your unbelief, but believe.”'
EXEC add_BibleVerse @BibleId, 343020028, N'Thomas replied to him, “My Lord and my God!”'
EXEC add_BibleVerse @BibleId, 343020029, N'Jesus said to him, “Have you believed because you have seen me? Blessed are the people who have not seen and yet have believed.”'
EXEC add_BibleVerse @BibleId, 343020030, N'Now Jesus performed many other miraculous signs in the presence of the disciples, which are not recorded in this book.'
EXEC add_BibleVerse @BibleId, 343020031, N'But these are recorded so that you may believe that Jesus is the Christ, the Son of God, and that by believing you may have life in his name.'
EXEC add_BibleVerse @BibleId, 343021001, N'After this Jesus revealed himself again to the disciples by the Sea of Tiberias. Now this is how he did so.'
EXEC add_BibleVerse @BibleId, 343021002, N'Simon Peter, Thomas (called Didymus), Nathanael (who was from Cana in Galilee), the sons of Zebedee, and two other disciples of his were together.'
EXEC add_BibleVerse @BibleId, 343021003, N'Simon Peter told them, “I am going fishing.” “We will go with you,” they replied. They went out and got into the boat, but that night they caught nothing.'
EXEC add_BibleVerse @BibleId, 343021004, N'When it was already very early morning, Jesus stood on the beach, but the disciples did not know that it was Jesus.'
EXEC add_BibleVerse @BibleId, 343021005, N'So Jesus said to them, “Children, you don’t have any fish, do you?” They replied, “No.”'
EXEC add_BibleVerse @BibleId, 343021006, N'He told them, “Throw your net on the right side of the boat, and you will find some.” So they threw the net, and were not able to pull it in because of the large number of fish.'
EXEC add_BibleVerse @BibleId, 343021007, N'Then the disciple whom Jesus loved said to Peter, “It is the Lord!” So Simon Peter, when he heard that it was the Lord, tucked in his outer garment (for he had nothing on underneath it), and plunged into the sea.'
EXEC add_BibleVerse @BibleId, 343021008, N'Meanwhile the other disciples came with the boat, dragging the net full of fish, for they were not far from land, only about a hundred yards.'
EXEC add_BibleVerse @BibleId, 343021009, N'When they got out on the beach, they saw a charcoal fire ready with a fish placed on it, and bread.'
EXEC add_BibleVerse @BibleId, 343021010, N'Jesus said, “Bring some of the fish you have just now caught.”'
EXEC add_BibleVerse @BibleId, 343021011, N'So Simon Peter went aboard and pulled the net to shore. It was full of large fish, one hundred fifty-three, but although there were so many, the net was not torn.'
EXEC add_BibleVerse @BibleId, 343021012, N'“Come, have breakfast,” Jesus said. But none of the disciples dared to ask him, “Who are you?” because they knew it was the Lord.'
EXEC add_BibleVerse @BibleId, 343021013, N'Jesus came and took the bread and gave it to them, and did the same with the fish.'
EXEC add_BibleVerse @BibleId, 343021014, N'This was now the third time Jesus was revealed to the disciples after he was raised from the dead.'
EXEC add_BibleVerse @BibleId, 343021015, N'Then when they had finished breakfast, Jesus said to Simon Peter, “Simon, son of John, do you love me more than these do?” He replied, “Yes, Lord, you know I love you.” Jesus told him, “Feed my lambs.”'
EXEC add_BibleVerse @BibleId, 343021016, N'Jesus said a second time, “Simon, son of John, do you love me?” He replied, “Yes, Lord, you know I love you.” Jesus told him, “Shepherd my sheep.”'
EXEC add_BibleVerse @BibleId, 343021017, N'Jesus said a third time, “Simon, son of John, do you love me?” Peter was distressed that Jesus asked him a third time, “Do you love me?” and said, “Lord, you know everything. You know that I love you.” Jesus replied, “Feed my sheep.'
EXEC add_BibleVerse @BibleId, 343021018, N'I tell you the solemn truth, when you were young, you tied your clothes around you and went wherever you wanted, but when you are old, you will stretch out your hands, and others will tie you up and bring you where you do not want to go.”'
EXEC add_BibleVerse @BibleId, 343021019, N'(Now Jesus said this to indicate clearly by what kind of death Peter was going to glorify God.) After he said this, Jesus told Peter, “Follow me.”'
EXEC add_BibleVerse @BibleId, 343021020, N'Peter turned around and saw the disciple whom Jesus loved following them. (This was the disciple who had leaned back against Jesus’ chest at the meal and asked, “Lord, who is the one who is going to betray you?”)'
EXEC add_BibleVerse @BibleId, 343021021, N'So when Peter saw him, he asked Jesus, “Lord, what about him?”'
EXEC add_BibleVerse @BibleId, 343021022, N'Jesus replied, “If I want him to live until I come back, what concern is that of yours? You follow me!”'
EXEC add_BibleVerse @BibleId, 343021023, N'So the saying circulated among the brothers and sisters that this disciple was not going to die. But Jesus did not say to him that he was not going to die, but rather, “If I want him to live until I come back, what concern is that of yours?”'
EXEC add_BibleVerse @BibleId, 343021024, N'This is the disciple who testifies about these things and has written these things, and we know that his testimony is true.'
EXEC add_BibleVerse @BibleId, 343021025, N'There are many other things that Jesus did. If every one of them were written down, I suppose the whole world would not have room for the books that would be written.'
EXEC add_BibleVerse @BibleId, 344001001, N'I wrote the former account, Theophilus, about all that Jesus began to do and teach'
EXEC add_BibleVerse @BibleId, 344001002, N'until the day he was taken up to heaven, after he had given orders by the Holy Spirit to the apostles he had chosen.'
EXEC add_BibleVerse @BibleId, 344001003, N'To the same apostles also, after his suffering, he presented himself alive with many convincing proofs. He was seen by them over a forty-day period and spoke about matters concerning the kingdom of God.'
EXEC add_BibleVerse @BibleId, 344001004, N'While he was with them, he declared, “Do not leave Jerusalem, but wait there for what my Father promised, which you heard about from me.'
EXEC add_BibleVerse @BibleId, 344001005, N'For John baptized with water, but you will be baptized with the Holy Spirit not many days from now.”'
EXEC add_BibleVerse @BibleId, 344001006, N'So when they had gathered together, they began to ask him, “Lord, is this the time when you are restoring the kingdom to Israel?”'
EXEC add_BibleVerse @BibleId, 344001007, N'He told them, “You are not permitted to know the times or periods that the Father has set by his own authority.'
EXEC add_BibleVerse @BibleId, 344001008, N'But you will receive power when the Holy Spirit has come upon you, and you will be my witnesses in Jerusalem, and in all Judea and Samaria, and to the farthest parts of the earth.”'
EXEC add_BibleVerse @BibleId, 344001009, N'After he had said this, while they were watching, he was lifted up and a cloud hid him from their sight.'
EXEC add_BibleVerse @BibleId, 344001010, N'As they were still staring into the sky while he was going, suddenly two men in white clothing stood near them'
EXEC add_BibleVerse @BibleId, 344001011, N'and said, “Men of Galilee, why do you stand here looking up into the sky? This same Jesus who has been taken up from you into heaven will come back in the same way you saw him go into heaven.”'
EXEC add_BibleVerse @BibleId, 344001012, N'Then they returned to Jerusalem from the mountain called the Mount of Olives (which is near Jerusalem, a Sabbath day’s journey away).'
EXEC add_BibleVerse @BibleId, 344001013, N'When they had entered Jerusalem, they went to the upstairs room where they were staying. Peter and John, and James, and Andrew, Philip and Thomas, Bartholomew and Matthew, James son of Alphaeus and Simon the Zealot, and Judas son of James were there.'
EXEC add_BibleVerse @BibleId, 344001014, N'All these continued together in prayer with one mind, together with the women, along with Mary the mother of Jesus, and his brothers.'
EXEC add_BibleVerse @BibleId, 344001015, N'In those days Peter stood up among the believers (a gathering of about one hundred and twenty people) and said,'
EXEC add_BibleVerse @BibleId, 344001016, N'“Brothers, the scripture had to be fulfilled that the Holy Spirit foretold through David concerning Judas – who became the guide for those who arrested Jesus –'
EXEC add_BibleVerse @BibleId, 344001017, N'for he was counted as one of us and received a share in this ministry.”'
EXEC add_BibleVerse @BibleId, 344001018, N'(Now this man Judas acquired a field with the reward of his unjust deed, and falling headfirst he burst open in the middle and all his intestines gushed out.'
EXEC add_BibleVerse @BibleId, 344001019, N'This became known to all who lived in Jerusalem, so that in their own language they called that field Hakeldama, that is, “Field of Blood.”)'
EXEC add_BibleVerse @BibleId, 344001020, N'“For it is written in the book of Psalms, ‘ Let his house become deserted, and let there be no one to live in it,’ and ‘ Let another take his position of responsibility.’'
EXEC add_BibleVerse @BibleId, 344001021, N'Thus one of the men who have accompanied us during all the time the Lord Jesus associated with us,'
EXEC add_BibleVerse @BibleId, 344001022, N'beginning from his baptism by John until the day he was taken up from us – one of these must become a witness of his resurrection together with us.”'
EXEC add_BibleVerse @BibleId, 344001023, N'So they proposed two candidates: Joseph called Barsabbas (also called Justus) and Matthias.'
EXEC add_BibleVerse @BibleId, 344001024, N'Then they prayed, “Lord, you know the hearts of all. Show us which one of these two you have chosen'
EXEC add_BibleVerse @BibleId, 344001025, N'to assume the task of this service and apostleship from which Judas turned aside to go to his own place.”'
EXEC add_BibleVerse @BibleId, 344001026, N'Then they cast lots for them, and the one chosen was Matthias; so he was counted with the eleven apostles.'
EXEC add_BibleVerse @BibleId, 344002001, N'Now when the day of Pentecost had come, they were all together in one place.'
EXEC add_BibleVerse @BibleId, 344002002, N'Suddenly a sound like a violent wind blowing came from heaven and filled the entire house where they were sitting.'
EXEC add_BibleVerse @BibleId, 344002003, N'And tongues spreading out like a fire appeared to them and came to rest on each one of them.'
EXEC add_BibleVerse @BibleId, 344002004, N'All of them were filled with the Holy Spirit, and they began to speak in other languages as the Spirit enabled them.'
EXEC add_BibleVerse @BibleId, 344002005, N'Now there were devout Jews from every nation under heaven residing in Jerusalem.'
EXEC add_BibleVerse @BibleId, 344002006, N'When this sound occurred, a crowd gathered and was in confusion, because each one heard them speaking in his own language.'
EXEC add_BibleVerse @BibleId, 344002007, N'Completely baffled, they said, “Aren’t all these who are speaking Galileans?'
EXEC add_BibleVerse @BibleId, 344002008, N'And how is it that each one of us hears them in our own native language?'
EXEC add_BibleVerse @BibleId, 344002009, N'Parthians, Medes, Elamites, and residents of Mesopotamia, Judea and Cappadocia, Pontus and the province of Asia,'
EXEC add_BibleVerse @BibleId, 344002010, N'Phrygia and Pamphylia, Egypt and the parts of Libya near Cyrene, and visitors from Rome,'
EXEC add_BibleVerse @BibleId, 344002011, N'both Jews and proselytes, Cretans and Arabs – we hear them speaking in our own languages about the great deeds God has done!”'
EXEC add_BibleVerse @BibleId, 344002012, N'All were astounded and greatly confused, saying to one another, “What does this mean?”'
EXEC add_BibleVerse @BibleId, 344002013, N'But others jeered at the speakers, saying, “They are drunk on new wine!”'
EXEC add_BibleVerse @BibleId, 344002014, N'But Peter stood up with the eleven, raised his voice, and addressed them: “You men of Judea and all you who live in Jerusalem, know this and listen carefully to what I say.'
EXEC add_BibleVerse @BibleId, 344002015, N'In spite of what you think, these men are not drunk, for it is only nine o’clock in the morning.'
EXEC add_BibleVerse @BibleId, 344002016, N'But this is what was spoken about through the prophet Joel:'
EXEC add_BibleVerse @BibleId, 344002017, N'‘ And in the last days it will be,’ God says, ‘ that I will pour out my Spirit on all people, and your sons and your daughters will prophesy, and your young men will see visions, and your old men will dream dreams.'
EXEC add_BibleVerse @BibleId, 344002018, N'Even on my servants, both men and women,* I will pour out my Spirit in those days, and they will prophesy.'
EXEC add_BibleVerse @BibleId, 344002019, N'And I will perform wonders in the sky above* and miraculous signs on the earth below, blood and fire and clouds of smoke.'
EXEC add_BibleVerse @BibleId, 344002020, N'The sun will be changed to darkness and the moon to blood before the great and glorious day of the Lord comes.'
EXEC add_BibleVerse @BibleId, 344002021, N'And then everyone who calls on the name of the Lord will be saved.’'
EXEC add_BibleVerse @BibleId, 344002022, N'“Men of Israel, listen to these words: Jesus the Nazarene, a man clearly attested to you by God with powerful deeds, wonders, and miraculous signs that God performed among you through him, just as you yourselves know –'
EXEC add_BibleVerse @BibleId, 344002023, N'this man, who was handed over by the predetermined plan and foreknowledge of God, you executed by nailing him to a cross at the hands of Gentiles.'
EXEC add_BibleVerse @BibleId, 344002024, N'But God raised him up, having released him from the pains of death, because it was not possible for him to be held in its power.'
EXEC add_BibleVerse @BibleId, 344002025, N'For David says about him, ‘ I saw the Lord always in front of me, for he is at my right hand so that I will not be shaken.'
EXEC add_BibleVerse @BibleId, 344002026, N'Therefore my heart was glad and my tongue rejoiced; my body also will live in hope,'
EXEC add_BibleVerse @BibleId, 344002027, N'because you will not leave my soul in Hades, nor permit your Holy One to experience decay.'
EXEC add_BibleVerse @BibleId, 344002028, N'You have made known to me the paths of life; you will make me full of joy with your presence.’'
EXEC add_BibleVerse @BibleId, 344002029, N'“Brothers, I can speak confidently to you about our forefather David, that he both died and was buried, and his tomb is with us to this day.'
EXEC add_BibleVerse @BibleId, 344002030, N'So then, because he was a prophet and knew that God had sworn to him with an oath to seat one of his descendants on his throne,'
EXEC add_BibleVerse @BibleId, 344002031, N'David by foreseeing this spoke about the resurrection of the Christ, that he was neither abandoned to Hades, nor did his body experience decay.'
EXEC add_BibleVerse @BibleId, 344002032, N'This Jesus God raised up, and we are all witnesses of it.'
EXEC add_BibleVerse @BibleId, 344002033, N'So then, exalted to the right hand of God, and having received the promise of the Holy Spirit from the Father, he has poured out what you both see and hear.'
EXEC add_BibleVerse @BibleId, 344002034, N'For David did not ascend into heaven, but he himself says, ‘ The Lord said to my lord, “ Sit at my right hand*'
EXEC add_BibleVerse @BibleId, 344002035, N'until I make your enemies a footstool for your feet.”’'
EXEC add_BibleVerse @BibleId, 344002036, N'Therefore let all the house of Israel know beyond a doubt that God has made this Jesus whom you crucified both Lord and Christ.”'
EXEC add_BibleVerse @BibleId, 344002037, N'Now when they heard this, they were acutely distressed and said to Peter and the rest of the apostles, “What should we do, brothers?”'
EXEC add_BibleVerse @BibleId, 344002038, N'Peter said to them, “Repent, and each one of you be baptized in the name of Jesus Christ for the forgiveness of your sins, and you will receive the gift of the Holy Spirit.'
EXEC add_BibleVerse @BibleId, 344002039, N'For the promise is for you and your children, and for all who are far away, as many as the Lord our God will call to himself.”'
EXEC add_BibleVerse @BibleId, 344002040, N'With many other words he testified and exhorted them saying, “Save yourselves from this perverse generation!”'
EXEC add_BibleVerse @BibleId, 344002041, N'So those who accepted his message were baptized, and that day about three thousand people were added.'
EXEC add_BibleVerse @BibleId, 344002042, N'They were devoting themselves to the apostles’ teaching and to fellowship, to the breaking of bread and to prayer.'
EXEC add_BibleVerse @BibleId, 344002043, N'Reverential awe came over everyone, and many wonders and miraculous signs came about by the apostles.'
EXEC add_BibleVerse @BibleId, 344002044, N'All who believed were together and held everything in common,'
EXEC add_BibleVerse @BibleId, 344002045, N'and they began selling their property and possessions and distributing the proceeds to everyone, as anyone had need.'
EXEC add_BibleVerse @BibleId, 344002046, N'Every day they continued to gather together by common consent in the temple courts, breaking bread from house to house, sharing their food with glad and humble hearts,'
EXEC add_BibleVerse @BibleId, 344002047, N'praising God and having the good will of all the people. And the Lord was adding to their number every day those who were being saved.'
EXEC add_BibleVerse @BibleId, 344003001, N'Now Peter and John were going up to the temple at the time for prayer, at three o’clock in the afternoon.'
EXEC add_BibleVerse @BibleId, 344003002, N'And a man lame from birth was being carried up, who was placed at the temple gate called “the Beautiful Gate” every day so he could beg for money from those going into the temple courts.'
EXEC add_BibleVerse @BibleId, 344003003, N'When he saw Peter and John about to go into the temple courts, he asked them for money.'
EXEC add_BibleVerse @BibleId, 344003004, N'Peter looked directly at him (as did John) and said, “Look at us!”'
EXEC add_BibleVerse @BibleId, 344003005, N'So the lame man paid attention to them, expecting to receive something from them.'
EXEC add_BibleVerse @BibleId, 344003006, N'But Peter said, “I have no silver or gold, but what I do have I give you. In the name of Jesus Christ the Nazarene, stand up and walk!”'
EXEC add_BibleVerse @BibleId, 344003007, N'Then Peter took hold of him by the right hand and raised him up, and at once the man’s feet and ankles were made strong.'
EXEC add_BibleVerse @BibleId, 344003008, N'He jumped up, stood and began walking around, and he entered the temple courts with them, walking and leaping and praising God.'
EXEC add_BibleVerse @BibleId, 344003009, N'All the people saw him walking and praising God,'
EXEC add_BibleVerse @BibleId, 344003010, N'and they recognized him as the man who used to sit and ask for donations at the Beautiful Gate of the temple, and they were filled with astonishment and amazement at what had happened to him.'
EXEC add_BibleVerse @BibleId, 344003011, N'While the man was hanging on to Peter and John, all the people, completely astounded, ran together to them in the covered walkway called Solomon’s Portico.'
EXEC add_BibleVerse @BibleId, 344003012, N'When Peter saw this, he declared to the people, “Men of Israel, why are you amazed at this? Why do you stare at us as if we had made this man walk by our own power or piety?'
EXEC add_BibleVerse @BibleId, 344003013, N'The God of Abraham, Isaac, and Jacob, the God of our forefathers, has glorified his servant Jesus, whom you handed over and rejected in the presence of Pilate after he had decided to release him.'
EXEC add_BibleVerse @BibleId, 344003014, N'But you rejected the Holy and Righteous One and asked that a man who was a murderer be released to you.'
EXEC add_BibleVerse @BibleId, 344003015, N'You killed the Originator of life, whom God raised from the dead. To this fact we are witnesses!'
EXEC add_BibleVerse @BibleId, 344003016, N'And on the basis of faith in Jesus’ name, his very name has made this man – whom you see and know – strong. The faith that is through Jesus has given him this complete health in the presence of you all.'
EXEC add_BibleVerse @BibleId, 344003017, N'And now, brothers, I know you acted in ignorance, as your rulers did too.'
EXEC add_BibleVerse @BibleId, 344003018, N'But the things God foretold long ago through all the prophets – that his Christ would suffer – he has fulfilled in this way.'
EXEC add_BibleVerse @BibleId, 344003019, N'Therefore repent and turn back so that your sins may be wiped out,'
EXEC add_BibleVerse @BibleId, 344003020, N'so that times of refreshing may come from the presence of the Lord, and so that he may send the Messiah appointed for you – that is, Jesus.'
EXEC add_BibleVerse @BibleId, 344003021, N'This one heaven must receive until the time all things are restored, which God declared from times long ago through his holy prophets.'
EXEC add_BibleVerse @BibleId, 344003022, N'Moses said, ‘ The Lord your God will raise up for you a prophet like me from among your brothers. You must obey him in everything he tells you*.'
EXEC add_BibleVerse @BibleId, 344003023, N'Every person who does not obey that prophet will be destroyed and thus removed from the people.’'
EXEC add_BibleVerse @BibleId, 344003024, N'And all the prophets, from Samuel and those who followed him, have spoken about and announced these days.'
EXEC add_BibleVerse @BibleId, 344003025, N'You are the sons of the prophets and of the covenant that God made with your ancestors, saying to Abraham, ‘ And in your descendants all the nations of the earth will be blessed: *.’'
EXEC add_BibleVerse @BibleId, 344003026, N'God raised up his servant and sent him first to you, to bless you by turning each one of you from your iniquities.”'
EXEC add_BibleVerse @BibleId, 344004001, N'While Peter and John were speaking to the people, the priests and the commander of the temple guard and the Sadducees came up to them,'
EXEC add_BibleVerse @BibleId, 344004002, N'angry because they were teaching the people and announcing in Jesus the resurrection of the dead.'
EXEC add_BibleVerse @BibleId, 344004003, N'So they seized them and put them in jail until the next day (for it was already evening).'
EXEC add_BibleVerse @BibleId, 344004004, N'But many of those who had listened to the message believed, and the number of the men came to about five thousand.'
EXEC add_BibleVerse @BibleId, 344004005, N'On the next day, their rulers, elders, and experts in the law came together in Jerusalem.'
EXEC add_BibleVerse @BibleId, 344004006, N'Annas the high priest was there, and Caiaphas, John, Alexander, and others who were members of the high priest’s family.'
EXEC add_BibleVerse @BibleId, 344004007, N'After making Peter and John stand in their midst, they began to inquire, “By what power or by what name did you do this?”'
EXEC add_BibleVerse @BibleId, 344004008, N'Then Peter, filled with the Holy Spirit, replied, “Rulers of the people and elders,'
EXEC add_BibleVerse @BibleId, 344004009, N'if we are being examined today for a good deed done to a sick man – by what means this man was healed –'
EXEC add_BibleVerse @BibleId, 344004010, N'let it be known to all of you and to all the people of Israel that by the name of Jesus Christ the Nazarene whom you crucified, whom God raised from the dead, this man stands before you healthy.'
EXEC add_BibleVerse @BibleId, 344004011, N'This Jesus is the stone that was rejected by that was rejected by you, the builders, that has become the cornerstone.'
EXEC add_BibleVerse @BibleId, 344004012, N'And there is salvation in no one else, for there is no other name under heaven given among people by which we must be saved.”'
EXEC add_BibleVerse @BibleId, 344004013, N'When they saw the boldness of Peter and John, and discovered that they were uneducated and ordinary men, they were amazed and recognized these men had been with Jesus.'
EXEC add_BibleVerse @BibleId, 344004014, N'And because they saw the man who had been healed standing with them, they had nothing to say against this.'
EXEC add_BibleVerse @BibleId, 344004015, N'But when they had ordered them to go outside the council, they began to confer with one another,'
EXEC add_BibleVerse @BibleId, 344004016, N'saying, “What should we do with these men? For it is plain to all who live in Jerusalem that a notable miraculous sign has come about through them, and we cannot deny it.'
EXEC add_BibleVerse @BibleId, 344004017, N'But to keep this matter from spreading any further among the people, let us warn them to speak no more to anyone in this name.”'
EXEC add_BibleVerse @BibleId, 344004018, N'And they called them in and ordered them not to speak or teach at all in the name of Jesus.'
EXEC add_BibleVerse @BibleId, 344004019, N'But Peter and John replied, “Whether it is right before God to obey you rather than God, you decide,'
EXEC add_BibleVerse @BibleId, 344004020, N'for it is impossible for us not to speak about what we have seen and heard.”'
EXEC add_BibleVerse @BibleId, 344004021, N'After threatening them further, they released them, for they could not find how to punish them on account of the people, because they were all praising God for what had happened.'
EXEC add_BibleVerse @BibleId, 344004022, N'For the man, on whom this miraculous sign of healing had been performed, was over forty years old.'
EXEC add_BibleVerse @BibleId, 344004023, N'When they were released, Peter and John went to their fellow believers and reported everything the high priests and the elders had said to them.'
EXEC add_BibleVerse @BibleId, 344004024, N'When they heard this, they raised their voices to God with one mind and said, “Master of all, you who made the heaven, the earth, the sea, and everything that is in them,'
EXEC add_BibleVerse @BibleId, 344004025, N'who said by the Holy Spirit through your servant David our forefather, ‘ Why do the nations rage, and the peoples plot foolish things?'
EXEC add_BibleVerse @BibleId, 344004026, N'The kings of the earth stood together, and the rulers assembled together, against the Lord and against his Christ: *.’'
EXEC add_BibleVerse @BibleId, 344004027, N'“For indeed both Herod and Pontius Pilate, with the Gentiles and the people of Israel, assembled together in this city against your holy servant Jesus, whom you anointed,'
EXEC add_BibleVerse @BibleId, 344004028, N'to do as much as your power and your plan had decided beforehand would happen.'
EXEC add_BibleVerse @BibleId, 344004029, N'And now, Lord, pay attention to their threats, and grant to your servants to speak your message with great courage,'
EXEC add_BibleVerse @BibleId, 344004030, N'while you extend your hand to heal, and to bring about miraculous signs and wonders through the name of your holy servant Jesus.”'
EXEC add_BibleVerse @BibleId, 344004031, N'When they had prayed, the place where they were assembled together was shaken, and they were all filled with the Holy Spirit and began to speak the word of God courageously.'
EXEC add_BibleVerse @BibleId, 344004032, N'The group of those who believed were of one heart and mind, and no one said that any of his possessions was his own, but everything was held in common.'
EXEC add_BibleVerse @BibleId, 344004033, N'With great power the apostles were giving testimony to the resurrection of the Lord Jesus, and great grace was on them all.'
EXEC add_BibleVerse @BibleId, 344004034, N'For there was no one needy among them, because those who were owners of land or houses were selling them and bringing the proceeds from the sales'
EXEC add_BibleVerse @BibleId, 344004035, N'and placing them at the apostles’ feet. The proceeds were distributed to each, as anyone had need.'
EXEC add_BibleVerse @BibleId, 344004036, N'So Joseph, a Levite who was a native of Cyprus, called by the apostles Barnabas (which is translated “son of encouragement”),'
EXEC add_BibleVerse @BibleId, 344004037, N'sold a field that belonged to him and brought the money and placed it at the apostles’ feet.'
EXEC add_BibleVerse @BibleId, 344005001, N'Now a man named Ananias, together with Sapphira his wife, sold a piece of property.'
EXEC add_BibleVerse @BibleId, 344005002, N'He kept back for himself part of the proceeds with his wife’s knowledge; he brought only part of it and placed it at the apostles’ feet.'
EXEC add_BibleVerse @BibleId, 344005003, N'But Peter said, “Ananias, why has Satan filled your heart to lie to the Holy Spirit and keep back for yourself part of the proceeds from the sale of the land?'
EXEC add_BibleVerse @BibleId, 344005004, N'Before it was sold, did it not belong to you? And when it was sold, was the money not at your disposal? How have you thought up this deed in your heart? You have not lied to people but to God!”'
EXEC add_BibleVerse @BibleId, 344005005, N'When Ananias heard these words he collapsed and died, and great fear gripped all who heard about it.'
EXEC add_BibleVerse @BibleId, 344005006, N'So the young men came, wrapped him up, carried him out, and buried him.'
EXEC add_BibleVerse @BibleId, 344005007, N'After an interval of about three hours, his wife came in, but she did not know what had happened.'
EXEC add_BibleVerse @BibleId, 344005008, N'Peter said to her, “Tell me, were the two of you paid this amount for the land?” Sapphira said, “Yes, that much.”'
EXEC add_BibleVerse @BibleId, 344005009, N'Peter then told her, “Why have you agreed together to test the Spirit of the Lord? Look! The feet of those who have buried your husband are at the door, and they will carry you out!”'
EXEC add_BibleVerse @BibleId, 344005010, N'At once she collapsed at his feet and died. So when the young men came in, they found her dead, and they carried her out and buried her beside her husband.'
EXEC add_BibleVerse @BibleId, 344005011, N'Great fear gripped the whole church and all who heard about these things.'
EXEC add_BibleVerse @BibleId, 344005012, N'Now many miraculous signs and wonders came about among the people through the hands of the apostles. By common consent they were all meeting together in Solomon’s Portico.'
EXEC add_BibleVerse @BibleId, 344005013, N'None of the rest dared to join them, but the people held them in high honor.'
EXEC add_BibleVerse @BibleId, 344005014, N'More and more believers in the Lord were added to their number, crowds of both men and women.'
EXEC add_BibleVerse @BibleId, 344005015, N'Thus they even carried the sick out into the streets, and put them on cots and pallets, so that when Peter came by at least his shadow would fall on some of them.'
EXEC add_BibleVerse @BibleId, 344005016, N'A crowd of people from the towns around Jerusalem also came together, bringing the sick and those troubled by unclean spirits. They were all being healed.'
EXEC add_BibleVerse @BibleId, 344005017, N'Now the high priest rose up, and all those with him (that is, the religious party of the Sadducees ), and they were filled with jealousy.'
EXEC add_BibleVerse @BibleId, 344005018, N'They laid hands on the apostles and put them in a public jail.'
EXEC add_BibleVerse @BibleId, 344005019, N'But during the night an angel of the Lord opened the doors of the prison, led them out, and said,'
EXEC add_BibleVerse @BibleId, 344005020, N'“Go and stand in the temple courts and proclaim to the people all the words of this life.”'
EXEC add_BibleVerse @BibleId, 344005021, N'When they heard this, they entered the temple courts at daybreak and began teaching. Now when the high priest and those who were with him arrived, they summoned the Sanhedrin – that is, the whole high council of the Israelites – and sent to the jail to have the apostles brought before them.'
EXEC add_BibleVerse @BibleId, 344005022, N'But the officers who came for them did not find them in the prison, so they returned and reported,'
EXEC add_BibleVerse @BibleId, 344005023, N'“We found the jail locked securely and the guards standing at the doors, but when we opened them, we found no one inside.”'
EXEC add_BibleVerse @BibleId, 344005024, N'Now when the commander of the temple guard and the chief priests heard this report, they were greatly puzzled concerning it, wondering what this could be.'
EXEC add_BibleVerse @BibleId, 344005025, N'But someone came and reported to them, “Look! The men you put in prison are standing in the temple courts and teaching the people!”'
EXEC add_BibleVerse @BibleId, 344005026, N'Then the commander of the temple guard went with the officers and brought the apostles without the use of force (for they were afraid of being stoned by the people).'
EXEC add_BibleVerse @BibleId, 344005027, N'When they had brought them, they stood them before the council, and the high priest questioned them,'
EXEC add_BibleVerse @BibleId, 344005028, N'saying, “We gave you strict orders not to teach in this name. Look, you have filled Jerusalem with your teaching, and you intend to bring this man’s blood on us!”'
EXEC add_BibleVerse @BibleId, 344005029, N'But Peter and the apostles replied, “We must obey God rather than people.'
EXEC add_BibleVerse @BibleId, 344005030, N'The God of our forefathers raised up Jesus, whom you seized and killed by hanging him on a tree.'
EXEC add_BibleVerse @BibleId, 344005031, N'God exalted him to his right hand as Leader and Savior, to give repentance to Israel and forgiveness of sins.'
EXEC add_BibleVerse @BibleId, 344005032, N'And we are witnesses of these events, and so is the Holy Spirit whom God has given to those who obey him.”'
EXEC add_BibleVerse @BibleId, 344005033, N'Now when they heard this, they became furious and wanted to execute them.'
EXEC add_BibleVerse @BibleId, 344005034, N'But a Pharisee whose name was Gamaliel, a teacher of the law who was respected by all the people, stood up in the council and ordered the men to be put outside for a short time.'
EXEC add_BibleVerse @BibleId, 344005035, N'Then he said to the council, “Men of Israel, pay close attention to what you are about to do to these men.'
EXEC add_BibleVerse @BibleId, 344005036, N'For some time ago Theudas rose up, claiming to be somebody, and about four hundred men joined him. He was killed, and all who followed him were dispersed and nothing came of it.'
EXEC add_BibleVerse @BibleId, 344005037, N'After him Judas the Galilean arose in the days of the census, and incited people to follow him in revolt. He too was killed, and all who followed him were scattered.'
EXEC add_BibleVerse @BibleId, 344005038, N'So in this case I say to you, stay away from these men and leave them alone, because if this plan or this undertaking originates with people, it will come to nothing,'
EXEC add_BibleVerse @BibleId, 344005039, N'but if it is from God, you will not be able to stop them, or you may even be found fighting against God.” He convinced them,'
EXEC add_BibleVerse @BibleId, 344005040, N'and they summoned the apostles and had them beaten. Then they ordered them not to speak in the name of Jesus and released them.'
EXEC add_BibleVerse @BibleId, 344005041, N'So they left the council rejoicing because they had been considered worthy to suffer dishonor for the sake of the name.'
EXEC add_BibleVerse @BibleId, 344005042, N'And every day both in the temple courts and from house to house, they did not stop teaching and proclaiming the good news that Jesus was the Christ.'
EXEC add_BibleVerse @BibleId, 344006001, N'Now in those days, when the disciples were growing in number, a complaint arose on the part of the Greek-speaking Jews against the native Hebraic Jews, because their widows were being overlooked in the daily distribution of food.'
EXEC add_BibleVerse @BibleId, 344006002, N'So the twelve called the whole group of the disciples together and said, “It is not right for us to neglect the word of God to wait on tables.'
EXEC add_BibleVerse @BibleId, 344006003, N'But carefully select from among you, brothers, seven men who are well-attested, full of the Spirit and of wisdom, whom we may put in charge of this necessary task.'
EXEC add_BibleVerse @BibleId, 344006004, N'But we will devote ourselves to prayer and to the ministry of the word.”'
EXEC add_BibleVerse @BibleId, 344006005, N'The proposal pleased the entire group, so they chose Stephen, a man full of faith and of the Holy Spirit, with Philip, Prochorus, Nicanor, Timon, Parmenas, and Nicolas, a Gentile convert to Judaism from Antioch.'
EXEC add_BibleVerse @BibleId, 344006006, N'They stood these men before the apostles, who prayed and placed their hands on them.'
EXEC add_BibleVerse @BibleId, 344006007, N'The word of God continued to spread, the number of disciples in Jerusalem increased greatly, and a large group of priests became obedient to the faith.'
EXEC add_BibleVerse @BibleId, 344006008, N'Now Stephen, full of grace and power, was performing great wonders and miraculous signs among the people.'
EXEC add_BibleVerse @BibleId, 344006009, N'But some men from the Synagogue of the Freedmen (as it was called), both Cyrenians and Alexandrians, as well as some from Cilicia and the province of Asia, stood up and argued with Stephen.'
EXEC add_BibleVerse @BibleId, 344006010, N'Yet they were not able to resist the wisdom and the Spirit with which he spoke.'
EXEC add_BibleVerse @BibleId, 344006011, N'Then they secretly instigated some men to say, “We have heard this man speaking blasphemous words against Moses and God.”'
EXEC add_BibleVerse @BibleId, 344006012, N'They incited the people, the elders, and the experts in the law; then they approached Stephen, seized him, and brought him before the council.'
EXEC add_BibleVerse @BibleId, 344006013, N'They brought forward false witnesses who said, “This man does not stop saying things against this holy place and the law.'
EXEC add_BibleVerse @BibleId, 344006014, N'For we have heard him saying that Jesus the Nazarene will destroy this place and change the customs that Moses handed down to us.”'
EXEC add_BibleVerse @BibleId, 344006015, N'All who were sitting in the council looked intently at Stephen and saw his face was like the face of an angel.'
EXEC add_BibleVerse @BibleId, 344007001, N'Then the high priest said, “Are these things true?”'
EXEC add_BibleVerse @BibleId, 344007002, N'So he replied, “Brothers and fathers, listen to me. The God of glory appeared to our forefather Abraham when he was in Mesopotamia, before he settled in Haran,'
EXEC add_BibleVerse @BibleId, 344007003, N'and said to him, ‘ Go out from your country and from your relatives, and come to the land I will show you.’'
EXEC add_BibleVerse @BibleId, 344007004, N'Then he went out from the country of the Chaldeans and settled in Haran. After his father died, God made him move to this country where you now live.'
EXEC add_BibleVerse @BibleId, 344007005, N'He did not give any of it to him for an inheritance, not even a foot of ground, yet God promised to give it to him as his possession, and to his descendants after him, even though Abraham as yet had no child.'
EXEC add_BibleVerse @BibleId, 344007006, N'But God spoke as follows: ‘Your descendants will be foreigners in a foreign country, whose citizens will enslave them and mistreat them for four hundred years.'
EXEC add_BibleVerse @BibleId, 344007007, N'But I will punish the nation they serve as slaves,’ said God, ‘ and after these things they will come out of there and worship me in this place.’'
EXEC add_BibleVerse @BibleId, 344007008, N'Then God gave Abraham the covenant of circumcision, and so he became the father of Isaac and circumcised him when he was eight days old, and Isaac became the father of Jacob, and Jacob of the twelve patriarchs.'
EXEC add_BibleVerse @BibleId, 344007009, N'The patriarchs, because they were jealous of Joseph, sold him into Egypt. But God was with him,'
EXEC add_BibleVerse @BibleId, 344007010, N'and rescued him from all his troubles, and granted him favor and wisdom in the presence of Pharaoh, king of Egypt, who made him ruler over Egypt and over all his household.'
EXEC add_BibleVerse @BibleId, 344007011, N'Then a famine occurred throughout Egypt and Canaan, causing great suffering, and our ancestors could not find food.'
EXEC add_BibleVerse @BibleId, 344007012, N'So when Jacob heard that there was grain in Egypt, he sent our ancestors there the first time.'
EXEC add_BibleVerse @BibleId, 344007013, N'On their second visit Joseph made himself known to his brothers again, and Joseph’s family became known to Pharaoh.'
EXEC add_BibleVerse @BibleId, 344007014, N'So Joseph sent a message and invited his father Jacob and all his relatives to come, seventy-five people in all.'
EXEC add_BibleVerse @BibleId, 344007015, N'So Jacob went down to Egypt and died there, along with our ancestors,'
EXEC add_BibleVerse @BibleId, 344007016, N'and their bones were later moved to Shechem and placed in the tomb that Abraham had bought for a certain sum of money from the sons of Hamor in Shechem.'
EXEC add_BibleVerse @BibleId, 344007017, N'“But as the time drew near for God to fulfill the promise he had declared to Abraham, the people increased greatly in number in Egypt,'
EXEC add_BibleVerse @BibleId, 344007018, N'until another king who did not know about Joseph ruled over Egypt.'
EXEC add_BibleVerse @BibleId, 344007019, N'This was the one who exploited our people and was cruel to our ancestors, forcing them to abandon their infants so they would die.'
EXEC add_BibleVerse @BibleId, 344007020, N'At that time Moses was born, and he was beautiful to God. For three months he was brought up in his father’s house,'
EXEC add_BibleVerse @BibleId, 344007021, N'and when he had been abandoned, Pharaoh’s daughter adopted him and brought him up as her own son.'
EXEC add_BibleVerse @BibleId, 344007022, N'So Moses was trained in all the wisdom of the Egyptians and was powerful in his words and deeds.'
EXEC add_BibleVerse @BibleId, 344007023, N'But when he was about forty years old, it entered his mind to visit his fellow countrymen the Israelites.'
EXEC add_BibleVerse @BibleId, 344007024, N'When he saw one of them being hurt unfairly, Moses came to his defense and avenged the person who was mistreated by striking down the Egyptian.'
EXEC add_BibleVerse @BibleId, 344007025, N'He thought his own people would understand that God was delivering them through him, but they did not understand.'
EXEC add_BibleVerse @BibleId, 344007026, N'The next day Moses saw two men fighting, and tried to make peace between them, saying, ‘Men, you are brothers; why are you hurting one another?’'
EXEC add_BibleVerse @BibleId, 344007027, N'But the man who was unfairly hurting his neighbor pushed Moses aside, saying, ‘ Who made you a ruler and judge over us?'
EXEC add_BibleVerse @BibleId, 344007028, N'You don’t want to kill me the way you killed the Egyptian yesterday, do you?’'
EXEC add_BibleVerse @BibleId, 344007029, N'When the man said this, Moses fled and became a foreigner in the land of Midian, where he became the father of two sons.'
EXEC add_BibleVerse @BibleId, 344007030, N'“After forty years had passed, an angel appeared to him in the desert of Mount Sinai, in the flame of a burning bush.'
EXEC add_BibleVerse @BibleId, 344007031, N'When Moses saw it, he was amazed at the sight, and when he approached to investigate, there came the voice of the Lord,'
EXEC add_BibleVerse @BibleId, 344007032, N'‘ I am the God of your forefathers, the God of Abraham, Isaac, and Jacob.’ Moses began to tremble and did not dare to look more closely.'
EXEC add_BibleVerse @BibleId, 344007033, N'But the Lord said to him, ‘ Take the sandals off your feet, for the place where you are standing is holy ground.'
EXEC add_BibleVerse @BibleId, 344007034, N'I have certainly seen the suffering of my people who are in Egypt and have heard their groaning, and I have come down to rescue them. Now come, I will send you to Egypt*.’'
EXEC add_BibleVerse @BibleId, 344007035, N'This same Moses they had rejected, saying, ‘ Who made you a ruler and judge?’ God sent as both ruler and deliverer through the hand of the angel who appeared to him in the bush.'
EXEC add_BibleVerse @BibleId, 344007036, N'This man led them out, performing wonders and miraculous signs in the land of Egypt, at the Red Sea, and in the wilderness for forty years.'
EXEC add_BibleVerse @BibleId, 344007037, N'This is the Moses who said to the Israelites, ‘ God will raise up for you a prophet like me from among your brothers will raise up for you a prophet like me from among your brothers.’'
EXEC add_BibleVerse @BibleId, 344007038, N'This is the man who was in the congregation in the wilderness with the angel who spoke to him at Mount Sinai, and with our ancestors, and he received living oracles to give to you.'
EXEC add_BibleVerse @BibleId, 344007039, N'Our ancestors were unwilling to obey him, but pushed him aside and turned back to Egypt in their hearts,'
EXEC add_BibleVerse @BibleId, 344007040, N'saying to Aaron, ‘ Make us gods who will go in front of us, for this Moses, who led us out of the land of Egypt – we do not know what has happened to him!’'
EXEC add_BibleVerse @BibleId, 344007041, N'At that time they made an idol in the form of a calf, brought a sacrifice to the idol, and began rejoicing in the works of their hands.'
EXEC add_BibleVerse @BibleId, 344007042, N'But God turned away from them and gave them over to worship the host of heaven, as it is written in the book of the prophets: ‘ It was not to me that you offered slain animals and sacrifices forty years in the wilderness, was it, house of Israel?'
EXEC add_BibleVerse @BibleId, 344007043, N'But you took along the tabernacle of Moloch and the star of the god Rephan, the images you made to worship, but I will deport you beyond Babylon*.’'
EXEC add_BibleVerse @BibleId, 344007044, N'Our ancestors had the tabernacle of testimony in the wilderness, just as God who spoke to Moses ordered him to make it according to the design he had seen.'
EXEC add_BibleVerse @BibleId, 344007045, N'Our ancestors received possession of it and brought it in with Joshua when they dispossessed the nations that God drove out before our ancestors, until the time of David.'
EXEC add_BibleVerse @BibleId, 344007046, N'He found favor with God and asked that he could find a dwelling place for the house of Jacob.'
EXEC add_BibleVerse @BibleId, 344007047, N'But Solomon built a house for him.'
EXEC add_BibleVerse @BibleId, 344007048, N'Yet the Most High does not live in houses made by human hands, as the prophet says,'
EXEC add_BibleVerse @BibleId, 344007049, N'‘ Heaven is my throne, and earth is the footstool for my feet. What kind of house will you build for me, says the Lord, or what is my resting place?'
EXEC add_BibleVerse @BibleId, 344007050, N'Did my hand not make all these things?’'
EXEC add_BibleVerse @BibleId, 344007051, N'“You stubborn people, with uncircumcised hearts and ears! You are always resisting the Holy Spirit, like your ancestors did!'
EXEC add_BibleVerse @BibleId, 344007052, N'Which of the prophets did your ancestors not persecute? They killed those who foretold long ago the coming of the Righteous One, whose betrayers and murderers you have now become!'
EXEC add_BibleVerse @BibleId, 344007053, N'You received the law by decrees given by angels, but you did not obey it.”'
EXEC add_BibleVerse @BibleId, 344007054, N'When they heard these things, they became furious and ground their teeth at him.'
EXEC add_BibleVerse @BibleId, 344007055, N'But Stephen, full of the Holy Spirit, looked intently toward heaven and saw the glory of God, and Jesus standing at the right hand of God.'
EXEC add_BibleVerse @BibleId, 344007056, N'“Look!” he said. “I see the heavens opened, and the Son of Man standing at the right hand of God!”'
EXEC add_BibleVerse @BibleId, 344007057, N'But they covered their ears, shouting out with a loud voice, and rushed at him with one intent.'
EXEC add_BibleVerse @BibleId, 344007058, N'When they had driven him out of the city, they began to stone him, and the witnesses laid their cloaks at the feet of a young man named Saul.'
EXEC add_BibleVerse @BibleId, 344007059, N'They continued to stone Stephen while he prayed, “Lord Jesus, receive my spirit!”'
EXEC add_BibleVerse @BibleId, 344007060, N'Then he fell to his knees and cried out with a loud voice, “Lord, do not hold this sin against them!” When he had said this, he died.'
EXEC add_BibleVerse @BibleId, 344008001, N'And Saul agreed completely with killing him. Now on that day a great persecution began against the church in Jerusalem, and all except the apostles were forced to scatter throughout the regions of Judea and Samaria.'
EXEC add_BibleVerse @BibleId, 344008002, N'Some devout men buried Stephen and made loud lamentation over him.'
EXEC add_BibleVerse @BibleId, 344008003, N'But Saul was trying to destroy the church; entering one house after another, he dragged off both men and women and put them in prison.'
EXEC add_BibleVerse @BibleId, 344008004, N'Now those who had been forced to scatter went around proclaiming the good news of the word.'
EXEC add_BibleVerse @BibleId, 344008005, N'Philip went down to the main city of Samaria and began proclaiming the Christ to them.'
EXEC add_BibleVerse @BibleId, 344008006, N'The crowds were paying attention with one mind to what Philip said, as they heard and saw the miraculous signs he was performing.'
EXEC add_BibleVerse @BibleId, 344008007, N'For unclean spirits, crying with loud shrieks, were coming out of many who were possessed, and many paralyzed and lame people were healed.'
EXEC add_BibleVerse @BibleId, 344008008, N'So there was great joy in that city.'
EXEC add_BibleVerse @BibleId, 344008009, N'Now in that city was a man named Simon, who had been practicing magic and amazing the people of Samaria, claiming to be someone great.'
EXEC add_BibleVerse @BibleId, 344008010, N'All the people, from the least to the greatest, paid close attention to him, saying, “This man is the power of God that is called ‘Great.’”'
EXEC add_BibleVerse @BibleId, 344008011, N'And they paid close attention to him because he had amazed them for a long time with his magic.'
EXEC add_BibleVerse @BibleId, 344008012, N'But when they believed Philip as he was proclaiming the good news about the kingdom of God and the name of Jesus Christ, they began to be baptized, both men and women.'
EXEC add_BibleVerse @BibleId, 344008013, N'Even Simon himself believed, and after he was baptized, he stayed close to Philip constantly, and when he saw the signs and great miracles that were occurring, he was amazed.'
EXEC add_BibleVerse @BibleId, 344008014, N'Now when the apostles in Jerusalem heard that Samaria had accepted the word of God, they sent Peter and John to them.'
EXEC add_BibleVerse @BibleId, 344008015, N'These two went down and prayed for them so that they would receive the Holy Spirit.'
EXEC add_BibleVerse @BibleId, 344008016, N'(For the Spirit had not yet come upon any of them, but they had only been baptized in the name of the Lord Jesus.)'
EXEC add_BibleVerse @BibleId, 344008017, N'Then Peter and John placed their hands on the Samaritans, and they received the Holy Spirit.'
EXEC add_BibleVerse @BibleId, 344008018, N'Now Simon, when he saw that the Spirit was given through the laying on of the apostles’ hands, offered them money,'
EXEC add_BibleVerse @BibleId, 344008019, N'saying, “Give me this power too, so that everyone I place my hands on may receive the Holy Spirit.”'
EXEC add_BibleVerse @BibleId, 344008020, N'But Peter said to him, “May your silver perish with you, because you thought you could acquire God’s gift with money!'
EXEC add_BibleVerse @BibleId, 344008021, N'You have no share or part in this matter because your heart is not right before God!'
EXEC add_BibleVerse @BibleId, 344008022, N'Therefore repent of this wickedness of yours, and pray to the Lord that he may perhaps forgive you for the intent of your heart.'
EXEC add_BibleVerse @BibleId, 344008023, N'For I see that you are bitterly envious and in bondage to sin.”'
EXEC add_BibleVerse @BibleId, 344008024, N'But Simon replied, “You pray to the Lord for me so that nothing of what you have said may happen to me.”'
EXEC add_BibleVerse @BibleId, 344008025, N'So after Peter and John had solemnly testified and spoken the word of the Lord, they started back to Jerusalem, proclaiming the good news to many Samaritan villages as they went.'
EXEC add_BibleVerse @BibleId, 344008026, N'Then an angel of the Lord said to Philip, “Get up and go south on the road that goes down from Jerusalem to Gaza.” (This is a desert road.)'
EXEC add_BibleVerse @BibleId, 344008027, N'So he got up and went. There he met an Ethiopian eunuch, a court official of Candace, queen of the Ethiopians, who was in charge of all her treasury. He had come to Jerusalem to worship,'
EXEC add_BibleVerse @BibleId, 344008028, N'and was returning home, sitting in his chariot, reading the prophet Isaiah.'
EXEC add_BibleVerse @BibleId, 344008029, N'Then the Spirit said to Philip, “Go over and join this chariot.”'
EXEC add_BibleVerse @BibleId, 344008030, N'So Philip ran up to it and heard the man reading Isaiah the prophet. He asked him, “Do you understand what you’re reading?”'
EXEC add_BibleVerse @BibleId, 344008031, N'The man replied, “How in the world can I, unless someone guides me?” So he invited Philip to come up and sit with him.'
EXEC add_BibleVerse @BibleId, 344008032, N'Now the passage of scripture the man was reading was this: “ He was led like a sheep to slaughter, and like a lamb before its shearer is silent, so he did not open his mouth.'
EXEC add_BibleVerse @BibleId, 344008033, N'In humiliation justice was taken from him.* Who can describe his posterity? For his life was taken away from the earth.”'
EXEC add_BibleVerse @BibleId, 344008034, N'Then the eunuch said to Philip, “Please tell me, who is the prophet saying this about – himself or someone else?”'
EXEC add_BibleVerse @BibleId, 344008035, N'So Philip started speaking, and beginning with this scripture proclaimed the good news about Jesus to him.'
EXEC add_BibleVerse @BibleId, 344008036, N'Now as they were going along the road, they came to some water, and the eunuch said, “Look, there is water! What is to stop me from being baptized?”'
EXEC add_BibleVerse @BibleId, 344008038, N' So he ordered the chariot to stop, and both Philip and the eunuch went down into the water, and Philip baptized him.'
EXEC add_BibleVerse @BibleId, 344008039, N'Now when they came up out of the water, the Spirit of the Lord snatched Philip away, and the eunuch did not see him any more, but went on his way rejoicing.'
EXEC add_BibleVerse @BibleId, 344008040, N'Philip, however, found himself at Azotus, and as he passed through the area, he proclaimed the good news to all the towns until he came to Caesarea.'
EXEC add_BibleVerse @BibleId, 344009001, N'Meanwhile Saul, still breathing out threats to murder the Lord’s disciples, went to the high priest'
EXEC add_BibleVerse @BibleId, 344009002, N'and requested letters from him to the synagogues in Damascus, so that if he found any who belonged to the Way, either men or women, he could bring them as prisoners to Jerusalem.'
EXEC add_BibleVerse @BibleId, 344009003, N'As he was going along, approaching Damascus, suddenly a light from heaven flashed around him.'
EXEC add_BibleVerse @BibleId, 344009004, N'He fell to the ground and heard a voice saying to him, “Saul, Saul, why are you persecuting me?”'
EXEC add_BibleVerse @BibleId, 344009005, N'So he said, “Who are you, Lord?” He replied, “I am Jesus whom you are persecuting!'
EXEC add_BibleVerse @BibleId, 344009006, N'But stand up and enter the city and you will be told what you must do.”'
EXEC add_BibleVerse @BibleId, 344009007, N'(Now the men who were traveling with him stood there speechless, because they heard the voice but saw no one.)'
EXEC add_BibleVerse @BibleId, 344009008, N'So Saul got up from the ground, but although his eyes were open, he could see nothing. Leading him by the hand, his companions brought him into Damascus.'
EXEC add_BibleVerse @BibleId, 344009009, N'For three days he could not see, and he neither ate nor drank anything.'
EXEC add_BibleVerse @BibleId, 344009010, N'Now there was a disciple in Damascus named Ananias. The Lord said to him in a vision, “Ananias,” and he replied, “Here I am, Lord.”'
EXEC add_BibleVerse @BibleId, 344009011, N'Then the Lord told him, “Get up and go to the street called ‘Straight,’ and at Judas’ house look for a man from Tarsus named Saul. For he is praying,'
EXEC add_BibleVerse @BibleId, 344009012, N'and he has seen in a vision a man named Ananias come in and place his hands on him so that he may see again.”'
EXEC add_BibleVerse @BibleId, 344009013, N'But Ananias replied, “Lord, I have heard from many people about this man, how much harm he has done to your saints in Jerusalem,'
EXEC add_BibleVerse @BibleId, 344009014, N'and here he has authority from the chief priests to imprison all who call on your name!”'
EXEC add_BibleVerse @BibleId, 344009015, N'But the Lord said to him, “Go, because this man is my chosen instrument to carry my name before Gentiles and kings and the people of Israel.'
EXEC add_BibleVerse @BibleId, 344009016, N'For I will show him how much he must suffer for the sake of my name.”'
EXEC add_BibleVerse @BibleId, 344009017, N'So Ananias departed and entered the house, placed his hands on Saul and said, “Brother Saul, the Lord Jesus, who appeared to you on the road as you came here, has sent me so that you may see again and be filled with the Holy Spirit.”'
EXEC add_BibleVerse @BibleId, 344009018, N'Immediately something like scales fell from his eyes, and he could see again. He got up and was baptized,'
EXEC add_BibleVerse @BibleId, 344009019, N'and after taking some food, his strength returned. For several days he was with the disciples in Damascus,'
EXEC add_BibleVerse @BibleId, 344009020, N'and immediately he began to proclaim Jesus in the synagogues, saying, “This man is the Son of God.”'
EXEC add_BibleVerse @BibleId, 344009021, N'All who heard him were amazed and were saying, “Is this not the man who in Jerusalem was ravaging those who call on this name, and who had come here to bring them as prisoners to the chief priests?”'
EXEC add_BibleVerse @BibleId, 344009022, N'But Saul became more and more capable, and was causing consternation among the Jews who lived in Damascus by proving that Jesus is the Christ.'
EXEC add_BibleVerse @BibleId, 344009023, N'Now after some days had passed, the Jews plotted together to kill him,'
EXEC add_BibleVerse @BibleId, 344009024, N'but Saul learned of their plot against him. They were also watching the city gates day and night so that they could kill him.'
EXEC add_BibleVerse @BibleId, 344009025, N'But his disciples took him at night and let him down through an opening in the wall by lowering him in a basket.'
EXEC add_BibleVerse @BibleId, 344009026, N'When he arrived in Jerusalem, he attempted to associate with the disciples, and they were all afraid of him, because they did not believe that he was a disciple.'
EXEC add_BibleVerse @BibleId, 344009027, N'But Barnabas took Saul, brought him to the apostles, and related to them how he had seen the Lord on the road, that the Lord had spoken to him, and how in Damascus he had spoken out boldly in the name of Jesus.'
EXEC add_BibleVerse @BibleId, 344009028, N'So he was staying with them, associating openly with them in Jerusalem, speaking out boldly in the name of the Lord.'
EXEC add_BibleVerse @BibleId, 344009029, N'He was speaking and debating with the Greek-speaking Jews, but they were trying to kill him.'
EXEC add_BibleVerse @BibleId, 344009030, N'When the brothers found out about this, they brought him down to Caesarea and sent him away to Tarsus.'
EXEC add_BibleVerse @BibleId, 344009031, N'Then the church throughout Judea, Galilee, and Samaria experienced peace and thus was strengthened. Living in the fear of the Lord and in the encouragement of the Holy Spirit, the church increased in numbers.'
EXEC add_BibleVerse @BibleId, 344009032, N'Now as Peter was traveling around from place to place, he also came down to the saints who lived in Lydda.'
EXEC add_BibleVerse @BibleId, 344009033, N'He found there a man named Aeneas who had been confined to a mattress for eight years because he was paralyzed.'
EXEC add_BibleVerse @BibleId, 344009034, N'Peter said to him, “Aeneas, Jesus the Christ heals you. Get up and make your own bed!” And immediately he got up.'
EXEC add_BibleVerse @BibleId, 344009035, N'All those who lived in Lydda and Sharon saw him, and they turned to the Lord.'
EXEC add_BibleVerse @BibleId, 344009036, N'Now in Joppa there was a disciple named Tabitha (which in translation means Dorcas). She was continually doing good deeds and acts of charity.'
EXEC add_BibleVerse @BibleId, 344009037, N'At that time she became sick and died. When they had washed her body, they placed it in an upstairs room.'
EXEC add_BibleVerse @BibleId, 344009038, N'Because Lydda was near Joppa, when the disciples heard that Peter was there, they sent two men to him and urged him, “Come to us without delay.”'
EXEC add_BibleVerse @BibleId, 344009039, N'So Peter got up and went with them, and when he arrived they brought him to the upper room. All the widows stood beside him, crying and showing him the tunics and other clothing Dorcas used to make while she was with them.'
EXEC add_BibleVerse @BibleId, 344009040, N'But Peter sent them all outside, knelt down, and prayed. Turning to the body, he said, “Tabitha, get up.” Then she opened her eyes, and when she saw Peter, she sat up.'
EXEC add_BibleVerse @BibleId, 344009041, N'He gave her his hand and helped her get up. Then he called the saints and widows and presented her alive.'
EXEC add_BibleVerse @BibleId, 344009042, N'This became known throughout all Joppa, and many believed in the Lord.'
EXEC add_BibleVerse @BibleId, 344009043, N'So Peter stayed many days in Joppa with a man named Simon, a tanner.'
EXEC add_BibleVerse @BibleId, 344010001, N'Now there was a man in Caesarea named Cornelius, a centurion of what was known as the Italian Cohort.'
EXEC add_BibleVerse @BibleId, 344010002, N'He was a devout, God-fearing man, as was all his household; he did many acts of charity for the people and prayed to God regularly.'
EXEC add_BibleVerse @BibleId, 344010003, N'About three o’clock one afternoon he saw clearly in a vision an angel of God who came in and said to him, “Cornelius.”'
EXEC add_BibleVerse @BibleId, 344010004, N'Staring at him and becoming greatly afraid, Cornelius replied, “What is it, Lord?” The angel said to him, “Your prayers and your acts of charity have gone up as a memorial before God.'
EXEC add_BibleVerse @BibleId, 344010005, N'Now send men to Joppa and summon a man named Simon, who is called Peter.'
EXEC add_BibleVerse @BibleId, 344010006, N'This man is staying as a guest with a man named Simon, a tanner, whose house is by the sea.”'
EXEC add_BibleVerse @BibleId, 344010007, N'When the angel who had spoken to him departed, Cornelius called two of his personal servants and a devout soldier from among those who served him,'
EXEC add_BibleVerse @BibleId, 344010008, N'and when he had explained everything to them, he sent them to Joppa.'
EXEC add_BibleVerse @BibleId, 344010009, N'About noon the next day, while they were on their way and approaching the city, Peter went up on the roof to pray.'
EXEC add_BibleVerse @BibleId, 344010010, N'He became hungry and wanted to eat, but while they were preparing the meal, a trance came over him.'
EXEC add_BibleVerse @BibleId, 344010011, N'He saw heaven opened and an object something like a large sheet descending, being let down to earth by its four corners.'
EXEC add_BibleVerse @BibleId, 344010012, N'In it were all kinds of four-footed animals and reptiles of the earth and wild birds.'
EXEC add_BibleVerse @BibleId, 344010013, N'Then a voice said to him, “Get up, Peter; slaughter and eat!”'
EXEC add_BibleVerse @BibleId, 344010014, N'But Peter said, “Certainly not, Lord, for I have never eaten anything defiled and ritually unclean!”'
EXEC add_BibleVerse @BibleId, 344010015, N'The voice spoke to him again, a second time, “What God has made clean, you must not consider ritually unclean!”'
EXEC add_BibleVerse @BibleId, 344010016, N'This happened three times, and immediately the object was taken up into heaven.'
EXEC add_BibleVerse @BibleId, 344010017, N'Now while Peter was puzzling over what the vision he had seen could signify, the men sent by Cornelius had learned where Simon’s house was and approached the gate.'
EXEC add_BibleVerse @BibleId, 344010018, N'They called out to ask if Simon, known as Peter, was staying there as a guest.'
EXEC add_BibleVerse @BibleId, 344010019, N'While Peter was still thinking seriously about the vision, the Spirit said to him, “Look! Three men are looking for you.'
EXEC add_BibleVerse @BibleId, 344010020, N'But get up, go down, and accompany them without hesitation, because I have sent them.”'
EXEC add_BibleVerse @BibleId, 344010021, N'So Peter went down to the men and said, “Here I am, the person you’re looking for. Why have you come?”'
EXEC add_BibleVerse @BibleId, 344010022, N'They said, “Cornelius the centurion, a righteous and God-fearing man, well spoken of by the whole Jewish nation, was directed by a holy angel to summon you to his house and to hear a message from you.”'
EXEC add_BibleVerse @BibleId, 344010023, N'So Peter invited them in and entertained them as guests. On the next day he got up and set out with them, and some of the brothers from Joppa accompanied him.'
EXEC add_BibleVerse @BibleId, 344010024, N'The following day he entered Caesarea. Now Cornelius was waiting anxiously for them and had called together his relatives and close friends.'
EXEC add_BibleVerse @BibleId, 344010025, N'So when Peter came in, Cornelius met him, fell at his feet, and worshiped him.'
EXEC add_BibleVerse @BibleId, 344010026, N'But Peter helped him up, saying, “Stand up. I too am a mere mortal.”'
EXEC add_BibleVerse @BibleId, 344010027, N'Peter continued talking with him as he went in, and he found many people gathered together.'
EXEC add_BibleVerse @BibleId, 344010028, N'He said to them, “You know that it is unlawful for a Jew to associate with or visit a Gentile, yet God has shown me that I should call no person defiled or ritually unclean.'
EXEC add_BibleVerse @BibleId, 344010029, N'Therefore when you sent for me, I came without any objection. Now may I ask why you sent for me?”'
EXEC add_BibleVerse @BibleId, 344010030, N'Cornelius replied, “Four days ago at this very hour, at three o’clock in the afternoon, I was praying in my house, and suddenly a man in shining clothing stood before me'
EXEC add_BibleVerse @BibleId, 344010031, N'and said, ‘Cornelius, your prayer has been heard and your acts of charity have been remembered before God.'
EXEC add_BibleVerse @BibleId, 344010032, N'Therefore send to Joppa and summon Simon, who is called Peter. This man is staying as a guest in the house of Simon the tanner, by the sea.’'
EXEC add_BibleVerse @BibleId, 344010033, N'Therefore I sent for you at once, and you were kind enough to come. So now we are all here in the presence of God to listen to everything the Lord has commanded you to say to us.”'
EXEC add_BibleVerse @BibleId, 344010034, N'Then Peter started speaking: “I now truly understand that God does not show favoritism in dealing with people,'
EXEC add_BibleVerse @BibleId, 344010035, N'but in every nation the person who fears him and does what is right is welcomed before him.'
EXEC add_BibleVerse @BibleId, 344010036, N'You know the message he sent to the people of Israel, proclaiming the good news of peace through Jesus Christ (he is Lord of all) –'
EXEC add_BibleVerse @BibleId, 344010037, N'you know what happened throughout Judea, beginning from Galilee after the baptism that John announced:'
EXEC add_BibleVerse @BibleId, 344010038, N'with respect to Jesus from Nazareth, that God anointed him with the Holy Spirit and with power. He went around doing good and healing all who were oppressed by the devil, because God was with him.'
EXEC add_BibleVerse @BibleId, 344010039, N'We are witnesses of all the things he did both in Judea and in Jerusalem. They killed him by hanging him on a tree,'
EXEC add_BibleVerse @BibleId, 344010040, N'but God raised him up on the third day and caused him to be seen,'
EXEC add_BibleVerse @BibleId, 344010041, N'not by all the people, but by us, the witnesses God had already chosen, who ate and drank with him after he rose from the dead.'
EXEC add_BibleVerse @BibleId, 344010042, N'He commanded us to preach to the people and to warn them that he is the one appointed by God as judge of the living and the dead.'
EXEC add_BibleVerse @BibleId, 344010043, N'About him all the prophets testify, that everyone who believes in him receives forgiveness of sins through his name.”'
EXEC add_BibleVerse @BibleId, 344010044, N'While Peter was still speaking these words, the Holy Spirit fell on all those who heard the message.'
EXEC add_BibleVerse @BibleId, 344010045, N'The circumcised believers who had accompanied Peter were greatly astonished that the gift of the Holy Spirit had been poured out even on the Gentiles,'
EXEC add_BibleVerse @BibleId, 344010046, N'for they heard them speaking in tongues and praising God. Then Peter said,'
EXEC add_BibleVerse @BibleId, 344010047, N'“No one can withhold the water for these people to be baptized, who have received the Holy Spirit just as we did, can he?”'
EXEC add_BibleVerse @BibleId, 344010048, N'So he gave orders to have them baptized in the name of Jesus Christ. Then they asked him to stay for several days.'
EXEC add_BibleVerse @BibleId, 344011001, N'Now the apostles and the brothers who were throughout Judea heard that the Gentiles too had accepted the word of God.'
EXEC add_BibleVerse @BibleId, 344011002, N'So when Peter went up to Jerusalem, the circumcised believers took issue with him,'
EXEC add_BibleVerse @BibleId, 344011003, N'saying, “You went to uncircumcised men and shared a meal with them.”'
EXEC add_BibleVerse @BibleId, 344011004, N'But Peter began and explained it to them point by point, saying,'
EXEC add_BibleVerse @BibleId, 344011005, N'“I was in the city of Joppa praying, and in a trance I saw a vision, an object something like a large sheet descending, being let down from heaven by its four corners, and it came to me.'
EXEC add_BibleVerse @BibleId, 344011006, N'As I stared I looked into it and saw four-footed animals of the earth, wild animals, reptiles, and wild birds.'
EXEC add_BibleVerse @BibleId, 344011007, N'I also heard a voice saying to me, ‘Get up, Peter; slaughter and eat!’'
EXEC add_BibleVerse @BibleId, 344011008, N'But I said, ‘Certainly not, Lord, for nothing defiled or ritually unclean has ever entered my mouth!’'
EXEC add_BibleVerse @BibleId, 344011009, N'But the voice replied a second time from heaven, ‘What God has made clean, you must not consider ritually unclean!’'
EXEC add_BibleVerse @BibleId, 344011010, N'This happened three times, and then everything was pulled up to heaven again.'
EXEC add_BibleVerse @BibleId, 344011011, N'At that very moment, three men sent to me from Caesarea approached the house where we were staying.'
EXEC add_BibleVerse @BibleId, 344011012, N'The Spirit told me to accompany them without hesitation. These six brothers also went with me, and we entered the man’s house.'
EXEC add_BibleVerse @BibleId, 344011013, N'He informed us how he had seen an angel standing in his house and saying, ‘Send to Joppa and summon Simon, who is called Peter,'
EXEC add_BibleVerse @BibleId, 344011014, N'who will speak a message to you by which you and your entire household will be saved.’'
EXEC add_BibleVerse @BibleId, 344011015, N'Then as I began to speak, the Holy Spirit fell on them just as he did on us at the beginning.'
EXEC add_BibleVerse @BibleId, 344011016, N'And I remembered the word of the Lord, as he used to say, ‘John baptized with water, but you will be baptized with the Holy Spirit.’'
EXEC add_BibleVerse @BibleId, 344011017, N'Therefore if God gave them the same gift as he also gave us after believing in the Lord Jesus Christ, who was I to hinder God?”'
EXEC add_BibleVerse @BibleId, 344011018, N'When they heard this, they ceased their objections and praised God, saying, “So then, God has granted the repentance that leads to life even to the Gentiles.”'
EXEC add_BibleVerse @BibleId, 344011019, N'Now those who had been scattered because of the persecution that took place over Stephen went as far as Phoenicia, Cyprus, and Antioch, speaking the message to no one but Jews.'
EXEC add_BibleVerse @BibleId, 344011020, N'But there were some men from Cyprus and Cyrene among them who came to Antioch and began to speak to the Greeks too, proclaiming the good news of the Lord Jesus.'
EXEC add_BibleVerse @BibleId, 344011021, N'The hand of the Lord was with them, and a great number who believed turned to the Lord.'
EXEC add_BibleVerse @BibleId, 344011022, N'A report about them came to the attention of the church in Jerusalem, and they sent Barnabas to Antioch.'
EXEC add_BibleVerse @BibleId, 344011023, N'When he came and saw the grace of God, he rejoiced and encouraged them all to remain true to the Lord with devoted hearts,'
EXEC add_BibleVerse @BibleId, 344011024, N'because he was a good man, full of the Holy Spirit and of faith, and a significant number of people were brought to the Lord.'
EXEC add_BibleVerse @BibleId, 344011025, N'Then Barnabas departed for Tarsus to look for Saul,'
EXEC add_BibleVerse @BibleId, 344011026, N'and when he found him, he brought him to Antioch. So for a whole year Barnabas and Saul met with the church and taught a significant number of people. Now it was in Antioch that the disciples were first called Christians.'
EXEC add_BibleVerse @BibleId, 344011027, N'At that time some prophets came down from Jerusalem'
EXEC add_BibleVerse @BibleId, 344011028, N'One of them, named Agabus, got up and predicted by the Spirit that a severe famine was about to come over the whole inhabited world. (This took place during the reign of Claudius.)'
EXEC add_BibleVerse @BibleId, 344011029, N'So the disciples, each in accordance with his financial ability, decided to send relief to the brothers living in Judea.'
EXEC add_BibleVerse @BibleId, 344011030, N'They did so, sending their financial aid to the elders by Barnabas and Saul.'
EXEC add_BibleVerse @BibleId, 344012001, N'About that time King Herod laid hands on some from the church to harm them.'
EXEC add_BibleVerse @BibleId, 344012002, N'He had James, the brother of John, executed with a sword.'
EXEC add_BibleVerse @BibleId, 344012003, N'When he saw that this pleased the Jews, he proceeded to arrest Peter too. (This took place during the feast of Unleavened Bread.)'
EXEC add_BibleVerse @BibleId, 344012004, N'When he had seized him, he put him in prison, handing him over to four squads of soldiers to guard him. Herod planned to bring him out for public trial after the Passover.'
EXEC add_BibleVerse @BibleId, 344012005, N'So Peter was kept in prison, but those in the church were earnestly praying to God for him.'
EXEC add_BibleVerse @BibleId, 344012006, N'On that very night before Herod was going to bring him out for trial, Peter was sleeping between two soldiers, bound with two chains, while guards in front of the door were keeping watch over the prison.'
EXEC add_BibleVerse @BibleId, 344012007, N'Suddenly an angel of the Lord appeared, and a light shone in the prison cell. He struck Peter on the side and woke him up, saying, “Get up quickly!” And the chains fell off Peter’s wrists.'
EXEC add_BibleVerse @BibleId, 344012008, N'The angel said to him, “Fasten your belt and put on your sandals.” Peter did so. Then the angel said to him, “Put on your cloak and follow me.”'
EXEC add_BibleVerse @BibleId, 344012009, N'Peter went out and followed him; he did not realize that what was happening through the angel was real, but thought he was seeing a vision.'
EXEC add_BibleVerse @BibleId, 344012010, N'After they had passed the first and second guards, they came to the iron gate leading into the city. It opened for them by itself, and they went outside and walked down one narrow street, when at once the angel left him.'
EXEC add_BibleVerse @BibleId, 344012011, N'When Peter came to himself, he said, “Now I know for certain that the Lord has sent his angel and rescued me from the hand of Herod and from everything the Jewish people were expecting to happen.”'
EXEC add_BibleVerse @BibleId, 344012012, N'When Peter realized this, he went to the house of Mary, the mother of John Mark, where many people had gathered together and were praying.'
EXEC add_BibleVerse @BibleId, 344012013, N'When he knocked at the door of the outer gate, a slave girl named Rhoda answered.'
EXEC add_BibleVerse @BibleId, 344012014, N'When she recognized Peter’s voice, she was so overjoyed she did not open the gate, but ran back in and told them that Peter was standing at the gate.'
EXEC add_BibleVerse @BibleId, 344012015, N'But they said to her, “You’ve lost your mind!” But she kept insisting that it was Peter, and they kept saying, “It is his angel!”'
EXEC add_BibleVerse @BibleId, 344012016, N'Now Peter continued knocking, and when they opened the door and saw him, they were greatly astonished.'
EXEC add_BibleVerse @BibleId, 344012017, N'He motioned to them with his hand to be quiet and then related how the Lord had brought him out of the prison. He said, “Tell James and the brothers these things,” and then he left and went to another place.'
EXEC add_BibleVerse @BibleId, 344012018, N'At daybreak there was great consternation among the soldiers over what had become of Peter.'
EXEC add_BibleVerse @BibleId, 344012019, N'When Herod had searched for him and did not find him, he questioned the guards and commanded that they be led away to execution. Then Herod went down from Judea to Caesarea and stayed there.'
EXEC add_BibleVerse @BibleId, 344012020, N'Now Herod was having an angry quarrel with the people of Tyre So they joined together and presented themselves before him. And after convincing Blastus, the king’s personal assistant, to help them, they asked for peace, because their country’s food supply was provided by the king’s country.'
EXEC add_BibleVerse @BibleId, 344012021, N'On a day determined in advance, Herod put on his royal robes, sat down on the judgment seat, and made a speech to them.'
EXEC add_BibleVerse @BibleId, 344012022, N'But the crowd began to shout, “The voice of a god, and not of a man!”'
EXEC add_BibleVerse @BibleId, 344012023, N'Immediately an angel of the Lord struck Herod down because he did not give the glory to God, and he was eaten by worms and died.'
EXEC add_BibleVerse @BibleId, 344012024, N'But the word of God kept on increasing and multiplying.'
EXEC add_BibleVerse @BibleId, 344012025, N'So Barnabas and Saul returned to Jerusalem when they had completed their mission, bringing along with them John Mark.'
EXEC add_BibleVerse @BibleId, 344013001, N'Now there were these prophets and teachers in the church at Antioch: Barnabas, Simeon called Niger, Lucius the Cyrenian, Manaen (a close friend of Herod the tetrarch from childhood ) and Saul.'
EXEC add_BibleVerse @BibleId, 344013002, N'While they were serving the Lord and fasting, the Holy Spirit said, “Set apart for me Barnabas and Saul for the work to which I have called them.”'
EXEC add_BibleVerse @BibleId, 344013003, N'Then, after they had fasted and prayed and placed their hands on them, they sent them off.'
EXEC add_BibleVerse @BibleId, 344013004, N'So Barnabas and Saul, sent out by the Holy Spirit, went down to Seleucia, and from there they sailed to Cyprus.'
EXEC add_BibleVerse @BibleId, 344013005, N'When they arrived in Salamis, they began to proclaim the word of God in the Jewish synagogues. (Now they also had John as their assistant.)'
EXEC add_BibleVerse @BibleId, 344013006, N'When they had crossed over the whole island as far as Paphos, they found a magician, a Jewish false prophet named Bar-Jesus,'
EXEC add_BibleVerse @BibleId, 344013007, N'who was with the proconsul Sergius Paulus, an intelligent man. The proconsul summoned Barnabas and Saul and wanted to hear the word of God.'
EXEC add_BibleVerse @BibleId, 344013008, N'But the magician Elymas (for that is the way his name is translated) opposed them, trying to turn the proconsul away from the faith.'
EXEC add_BibleVerse @BibleId, 344013009, N'But Saul (also known as Paul), filled with the Holy Spirit, stared straight at him'
EXEC add_BibleVerse @BibleId, 344013010, N'and said, “You who are full of all deceit and all wrongdoing, you son of the devil, you enemy of all righteousness – will you not stop making crooked the straight paths of the Lord?'
EXEC add_BibleVerse @BibleId, 344013011, N'Now look, the hand of the Lord is against you, and you will be blind, unable to see the sun for a time!” Immediately mistiness and darkness came over him, and he went around seeking people to lead him by the hand.'
EXEC add_BibleVerse @BibleId, 344013012, N'Then when the proconsul saw what had happened, he believed, because he was greatly astounded at the teaching about the Lord.'
EXEC add_BibleVerse @BibleId, 344013013, N'Then Paul and his companions put out to sea from Paphos and came to Perga in Pamphylia, but John left them and returned to Jerusalem.'
EXEC add_BibleVerse @BibleId, 344013014, N'Moving on from Perga, they arrived at Pisidian Antioch, and on the Sabbath day they went into the synagogue and sat down.'
EXEC add_BibleVerse @BibleId, 344013015, N'After the reading from the law and the prophets, the leaders of the synagogue sent them a message, saying, “Brothers, if you have any message of exhortation for the people, speak it.”'
EXEC add_BibleVerse @BibleId, 344013016, N'So Paul stood up, gestured with his hand and said, “Men of Israel, and you Gentiles who fear God, listen:'
EXEC add_BibleVerse @BibleId, 344013017, N'The God of this people Israel chose our ancestors and made the people great during their stay as foreigners in the country of Egypt, and with uplifted arm he led them out of it.'
EXEC add_BibleVerse @BibleId, 344013018, N'For a period of about forty years he put up with them in the wilderness.'
EXEC add_BibleVerse @BibleId, 344013019, N'After he had destroyed seven nations in the land of Canaan, he gave his people their land as an inheritance.'
EXEC add_BibleVerse @BibleId, 344013020, N'All this took about four hundred fifty years. After this he gave them judges until the time of Samuel the prophet.'
EXEC add_BibleVerse @BibleId, 344013021, N'Then they asked for a king, and God gave them Saul son of Kish, a man from the tribe of Benjamin, who ruled forty years.'
EXEC add_BibleVerse @BibleId, 344013022, N'After removing him, God raised up David their king. He testified about him: ‘ I have found David the son of Jesse to be a man after my heart, who will accomplish everything I want him to do.’'
EXEC add_BibleVerse @BibleId, 344013023, N'From the descendants of this man God brought to Israel a Savior, Jesus, just as he promised.'
EXEC add_BibleVerse @BibleId, 344013024, N'Before Jesus arrived, John had proclaimed a baptism for repentance to all the people of Israel.'
EXEC add_BibleVerse @BibleId, 344013025, N'But while John was completing his mission, he said repeatedly, ‘What do you think I am? I am not he. But look, one is coming after me. I am not worthy to untie the sandals on his feet!’'
EXEC add_BibleVerse @BibleId, 344013026, N'Brothers, descendants of Abraham’s family, and those Gentiles among you who fear God, the message of this salvation has been sent to us.'
EXEC add_BibleVerse @BibleId, 344013027, N'For the people who live in Jerusalem and their rulers did not recognize him, and they fulfilled the sayings of the prophets that are read every Sabbath by condemning him.'
EXEC add_BibleVerse @BibleId, 344013028, N'Though they found no basis for a death sentence, they asked Pilate to have him executed.'
EXEC add_BibleVerse @BibleId, 344013029, N'When they had accomplished everything that was written about him, they took him down from the cross and placed him in a tomb.'
EXEC add_BibleVerse @BibleId, 344013030, N'But God raised him from the dead,'
EXEC add_BibleVerse @BibleId, 344013031, N'and for many days he appeared to those who had accompanied him from Galilee to Jerusalem. These are now his witnesses to the people.'
EXEC add_BibleVerse @BibleId, 344013032, N'And we proclaim to you the good news about the promise to our ancestors,'
EXEC add_BibleVerse @BibleId, 344013033, N'that this promise God has fulfilled to us, their children, by raising Jesus, as also it is written in the second psalm, ‘ You are my Son; today I have fathered you*.’'
EXEC add_BibleVerse @BibleId, 344013034, N'But regarding the fact that he has raised Jesus from the dead, never again to be in a state of decay, God has spoken in this way: ‘ I will give you the holy and trustworthy promises made to David*.’'
EXEC add_BibleVerse @BibleId, 344013035, N'Therefore he also says in another psalm, ‘ You will not permit your Holy One to experience decay*.’'
EXEC add_BibleVerse @BibleId, 344013036, N'For David, after he had served God’s purpose in his own generation, died, was buried with his ancestors, and experienced decay,'
EXEC add_BibleVerse @BibleId, 344013037, N'but the one whom God raised up did not experience decay.'
EXEC add_BibleVerse @BibleId, 344013038, N'Therefore let it be known to you, brothers, that through this one forgiveness of sins is proclaimed to you,'
EXEC add_BibleVerse @BibleId, 344013039, N'and by this one everyone who believes is justified from everything from which the law of Moses could not justify you.'
EXEC add_BibleVerse @BibleId, 344013040, N'Watch out, then, that what is spoken about by the prophets does not happen to you:'
EXEC add_BibleVerse @BibleId, 344013041, N'‘ Look, you scoffers; be amazed and perish! For I am doing a work in your days, a work you would never believe, even if someone tells you.’”'
EXEC add_BibleVerse @BibleId, 344013042, N'As Paul and Barnabas were going out, the people were urging them to speak about these things on the next Sabbath.'
EXEC add_BibleVerse @BibleId, 344013043, N'When the meeting of the synagogue had broken up, many of the Jews and God-fearing proselytes followed Paul and Barnabas, who were speaking with them and were persuading them to continue in the grace of God.'
EXEC add_BibleVerse @BibleId, 344013044, N'On the next Sabbath almost the whole city assembled together to hear the word of the Lord.'
EXEC add_BibleVerse @BibleId, 344013045, N'But when the Jews saw the crowds, they were filled with jealousy, and they began to contradict what Paul was saying by reviling him.'
EXEC add_BibleVerse @BibleId, 344013046, N'Both Paul and Barnabas replied courageously, “It was necessary to speak the word of God to you first. Since you reject it and do not consider yourselves worthy of eternal life, we are turning to the Gentiles.'
EXEC add_BibleVerse @BibleId, 344013047, N'For this is what the Lord has commanded us: ‘ I have appointed you to be a light for the Gentiles, to bring salvation to the ends of the earth.’”'
EXEC add_BibleVerse @BibleId, 344013048, N'When the Gentiles heard this, they began to rejoice and praise the word of the Lord, and all who had been appointed for eternal life believed.'
EXEC add_BibleVerse @BibleId, 344013049, N'So the word of the Lord was spreading through the entire region.'
EXEC add_BibleVerse @BibleId, 344013050, N'But the Jews incited the God-fearing women of high social standing and the prominent men of the city, stirred up persecution against Paul and Barnabas, and threw them out of their region.'
EXEC add_BibleVerse @BibleId, 344013051, N'So after they shook the dust off their feet in protest against them, they went to Iconium.'
EXEC add_BibleVerse @BibleId, 344013052, N'And the disciples were filled with joy and with the Holy Spirit.'
EXEC add_BibleVerse @BibleId, 344014001, N'The same thing happened in Iconium when Paul and Barnabas went into the Jewish synagogue and spoke in such a way that a large group of both Jews and Greeks believed.'
EXEC add_BibleVerse @BibleId, 344014002, N'But the Jews who refused to believe stirred up the Gentiles and poisoned their minds against the brothers.'
EXEC add_BibleVerse @BibleId, 344014003, N'So they stayed there for a considerable time, speaking out courageously for the Lord, who testified to the message of his grace, granting miraculous signs and wonders to be performed through their hands.'
EXEC add_BibleVerse @BibleId, 344014004, N'But the population of the city was divided; some sided with the Jews, and some with the apostles.'
EXEC add_BibleVerse @BibleId, 344014005, N'When both the Gentiles and the Jews (together with their rulers) made an attempt to mistreat them and stone them,'
EXEC add_BibleVerse @BibleId, 344014006, N'Paul and Barnabas learned about it and fled to the Lycaonian cities of Lystra and the surrounding region.'
EXEC add_BibleVerse @BibleId, 344014007, N'There they continued to proclaim the good news.'
EXEC add_BibleVerse @BibleId, 344014008, N'In Lystra sat a man who could not use his feet, lame from birth, who had never walked.'
EXEC add_BibleVerse @BibleId, 344014009, N'This man was listening to Paul as he was speaking. When Paul stared intently at him and saw he had faith to be healed,'
EXEC add_BibleVerse @BibleId, 344014010, N'he said with a loud voice, “Stand upright on your feet.” And the man leaped up and began walking.'
EXEC add_BibleVerse @BibleId, 344014011, N'So when the crowds saw what Paul had done, they shouted in the Lycaonian language, “The gods have come down to us in human form!”'
EXEC add_BibleVerse @BibleId, 344014012, N'They began to call Barnabas Zeus and Paul Hermes, because he was the chief speaker.'
EXEC add_BibleVerse @BibleId, 344014013, N'The priest of the temple of Zeus, located just outside the city, brought bulls and garlands to the city gates; he and the crowds wanted to offer sacrifices to them.'
EXEC add_BibleVerse @BibleId, 344014014, N'But when the apostles Barnabas and Paul heard about it, they tore their clothes and rushed out into the crowd, shouting,'
EXEC add_BibleVerse @BibleId, 344014015, N'“Men, why are you doing these things? We too are men, with human natures just like you! We are proclaiming the good news to you, so that you should turn from these worthless things to the living God, who made the heaven, the earth, the sea, and everything that is in them.'
EXEC add_BibleVerse @BibleId, 344014016, N'In past generations he allowed all the nations to go their own ways,'
EXEC add_BibleVerse @BibleId, 344014017, N'yet he did not leave himself without a witness by doing good, by giving you rain from heaven and fruitful seasons, satisfying you with food and your hearts with joy.”'
EXEC add_BibleVerse @BibleId, 344014018, N'Even by saying these things, they scarcely persuaded the crowds not to offer sacrifice to them.'
EXEC add_BibleVerse @BibleId, 344014019, N'But Jews came from Antioch and Iconium, and after winning the crowds over, they stoned Paul and dragged him out of the city, presuming him to be dead.'
EXEC add_BibleVerse @BibleId, 344014020, N'But after the disciples had surrounded him, he got up and went back into the city. On the next day he left with Barnabas for Derbe.'
EXEC add_BibleVerse @BibleId, 344014021, N'After they had proclaimed the good news in that city and made many disciples, they returned to Lystra,'
EXEC add_BibleVerse @BibleId, 344014022, N'They strengthened the souls of the disciples and encouraged them to continue in the faith, saying, “We must enter the kingdom of God through many persecutions.”'
EXEC add_BibleVerse @BibleId, 344014023, N'When they had appointed elders for them in the various churches, with prayer and fasting they entrusted them to the protection of the Lord in whom they had believed.'
EXEC add_BibleVerse @BibleId, 344014024, N'Then they passed through Pisidia and came into Pamphylia,'
EXEC add_BibleVerse @BibleId, 344014025, N'and when they had spoken the word in Perga, they went down to Attalia.'
EXEC add_BibleVerse @BibleId, 344014026, N'From there they sailed back to Antioch, where they had been commended to the grace of God for the work they had now completed.'
EXEC add_BibleVerse @BibleId, 344014027, N'When they arrived and gathered the church together, they reported all the things God had done with them, and that he had opened a door of faith for the Gentiles.'
EXEC add_BibleVerse @BibleId, 344014028, N'So they spent considerable time with the disciples.'
EXEC add_BibleVerse @BibleId, 344015001, N'Now some men came down from Judea and began to teach the brothers, “Unless you are circumcised according to the custom of Moses, you cannot be saved.”'
EXEC add_BibleVerse @BibleId, 344015002, N'When Paul and Barnabas had a major argument and debate with them, the church appointed Paul and Barnabas and some others from among them to go up to meet with the apostles and elders in Jerusalem about this point of disagreement.'
EXEC add_BibleVerse @BibleId, 344015003, N'So they were sent on their way by the church, and as they passed through both Phoenicia and Samaria, they were relating at length the conversion of the Gentiles and bringing great joy to all the brothers.'
EXEC add_BibleVerse @BibleId, 344015004, N'When they arrived in Jerusalem, they were received by the church and the apostles and the elders, and they reported all the things God had done with them.'
EXEC add_BibleVerse @BibleId, 344015005, N'But some from the religious party of the Pharisees who had believed stood up and said, “It is necessary to circumcise the Gentiles and to order them to observe the law of Moses.”'
EXEC add_BibleVerse @BibleId, 344015006, N'Both the apostles and the elders met together to deliberate about this matter.'
EXEC add_BibleVerse @BibleId, 344015007, N'After there had been much debate, Peter stood up and said to them, “Brothers, you know that some time ago God chose me to preach to the Gentiles so they would hear the message of the gospel and believe.'
EXEC add_BibleVerse @BibleId, 344015008, N'And God, who knows the heart, has testified to them by giving them the Holy Spirit just as he did to us,'
EXEC add_BibleVerse @BibleId, 344015009, N'and he made no distinction between them and us, cleansing their hearts by faith.'
EXEC add_BibleVerse @BibleId, 344015010, N'So now why are you putting God to the test by placing on the neck of the disciples a yoke that neither our ancestors nor we have been able to bear?'
EXEC add_BibleVerse @BibleId, 344015011, N'On the contrary, we believe that we are saved through the grace of the Lord Jesus, in the same way as they are.”'
EXEC add_BibleVerse @BibleId, 344015012, N'The whole group kept quiet and listened to Barnabas and Paul while they explained all the miraculous signs and wonders God had done among the Gentiles through them.'
EXEC add_BibleVerse @BibleId, 344015013, N'After they stopped speaking, James replied, “Brothers, listen to me.'
EXEC add_BibleVerse @BibleId, 344015014, N'Simeon has explained how God first concerned himself to select from among the Gentiles a people for his name.'
EXEC add_BibleVerse @BibleId, 344015015, N'The words of the prophets agree with this, as it is written,'
EXEC add_BibleVerse @BibleId, 344015016, N'‘ After this I will return, and I will rebuild the fallen tent of David;* I will rebuild its ruins and restore it,*'
EXEC add_BibleVerse @BibleId, 344015017, N'so that the rest of humanity may seek the Lord,* namely, all the Gentiles I have called to be my own,’ says the Lord,* who makes these things'
EXEC add_BibleVerse @BibleId, 344015018, N'known from long ago.'
EXEC add_BibleVerse @BibleId, 344015019, N'“Therefore I conclude that we should not cause extra difficulty for those among the Gentiles who are turning to God,'
EXEC add_BibleVerse @BibleId, 344015020, N'but that we should write them a letter telling them to abstain from things defiled by idols and from sexual immorality and from what has been strangled and from blood.'
EXEC add_BibleVerse @BibleId, 344015021, N'For Moses has had those who proclaim him in every town from ancient times, because he is read aloud in the synagogues every Sabbath.”'
EXEC add_BibleVerse @BibleId, 344015022, N'Then the apostles and elders, with the whole church, decided to send men chosen from among them, Judas called Barsabbas and Silas, leaders among the brothers, to Antioch with Paul and Barnabas.'
EXEC add_BibleVerse @BibleId, 344015023, N'They sent this letter with them: From the apostles and elders, your brothers, to the Gentile brothers and sisters in Antioch, Syria, and Cilicia, greetings!'
EXEC add_BibleVerse @BibleId, 344015024, N'Since we have heard that some have gone out from among us with no orders from us and have confused you, upsetting your minds by what they said,'
EXEC add_BibleVerse @BibleId, 344015025, N'we have unanimously decided to choose men to send to you along with our dear friends Barnabas and Paul,'
EXEC add_BibleVerse @BibleId, 344015026, N'who have risked their lives for the name of our Lord Jesus Christ.'
EXEC add_BibleVerse @BibleId, 344015027, N'Therefore we are sending Judas and Silas who will tell you these things themselves in person.'
EXEC add_BibleVerse @BibleId, 344015028, N'For it seemed best to the Holy Spirit and to us not to place any greater burden on you than these necessary rules:'
EXEC add_BibleVerse @BibleId, 344015029, N'that you abstain from meat that has been sacrificed to idols and from blood and from what has been strangled and from sexual immorality. If you keep yourselves from doing these things, you will do well. Farewell.'
EXEC add_BibleVerse @BibleId, 344015030, N'So when they were dismissed, they went down to Antioch, and after gathering the entire group together, they delivered the letter.'
EXEC add_BibleVerse @BibleId, 344015031, N'When they read it aloud, the people rejoiced at its encouragement.'
EXEC add_BibleVerse @BibleId, 344015032, N'Both Judas and Silas, who were prophets themselves, encouraged and strengthened the brothers with a long speech.'
EXEC add_BibleVerse @BibleId, 344015033, N'After they had spent some time there, they were sent off in peace by the brothers to those who had sent them.'
EXEC add_BibleVerse @BibleId, 344015035, N' But Paul and Barnabas remained in Antioch, teaching and proclaiming (along with many others) the word of the Lord.'
EXEC add_BibleVerse @BibleId, 344015036, N'After some days Paul said to Barnabas, “Let’s return and visit the brothers in every town where we proclaimed the word of the Lord to see how they are doing.”'
EXEC add_BibleVerse @BibleId, 344015037, N'Barnabas wanted to bring John called Mark along with them too,'
EXEC add_BibleVerse @BibleId, 344015038, N'but Paul insisted that they should not take along this one who had left them in Pamphylia and had not accompanied them in the work.'
EXEC add_BibleVerse @BibleId, 344015039, N'They had a sharp disagreement, so that they parted company. Barnabas took along Mark and sailed away to Cyprus,'
EXEC add_BibleVerse @BibleId, 344015040, N'but Paul chose Silas and set out, commended to the grace of the Lord by the brothers and sisters.'
EXEC add_BibleVerse @BibleId, 344015041, N'He passed through Syria and Cilicia, strengthening the churches.'
EXEC add_BibleVerse @BibleId, 344016001, N'He also came to Derbe A disciple named Timothy was there, the son of a Jewish woman who was a believer, but whose father was a Greek.'
EXEC add_BibleVerse @BibleId, 344016002, N'The brothers in Lystra and Iconium spoke well of him.'
EXEC add_BibleVerse @BibleId, 344016003, N'Paul wanted Timothy to accompany him, and he took him and circumcised him because of the Jews who were in those places, for they all knew that his father was Greek.'
EXEC add_BibleVerse @BibleId, 344016004, N'As they went through the towns, they passed on the decrees that had been decided on by the apostles and elders in Jerusalem for the Gentile believers to obey.'
EXEC add_BibleVerse @BibleId, 344016005, N'So the churches were being strengthened in the faith and were increasing in number every day.'
EXEC add_BibleVerse @BibleId, 344016006, N'They went through the region of Phrygia and Galatia, having been prevented by the Holy Spirit from speaking the message in the province of Asia.'
EXEC add_BibleVerse @BibleId, 344016007, N'When they came to Mysia, they attempted to go into Bithynia, but the Spirit of Jesus did not allow them to do this,'
EXEC add_BibleVerse @BibleId, 344016008, N'so they passed through Mysia and went down to Troas.'
EXEC add_BibleVerse @BibleId, 344016009, N'A vision appeared to Paul during the night: A Macedonian man was standing there urging him, “Come over to Macedonia and help us!”'
EXEC add_BibleVerse @BibleId, 344016010, N'After Paul saw the vision, we attempted immediately to go over to Macedonia, concluding that God had called us to proclaim the good news to them.'
EXEC add_BibleVerse @BibleId, 344016011, N'We put out to sea from Troas and sailed a straight course to Samothrace, the next day to Neapolis,'
EXEC add_BibleVerse @BibleId, 344016012, N'and from there to Philippi, which is a leading city of that district of Macedonia, a Roman colony. We stayed in this city for some days.'
EXEC add_BibleVerse @BibleId, 344016013, N'On the Sabbath day we went outside the city gate to the side of the river, where we thought there would be a place of prayer, and we sat down and began to speak to the women who had assembled there.'
EXEC add_BibleVerse @BibleId, 344016014, N'A woman named Lydia, a dealer in purple cloth from the city of Thyatira, a God-fearing woman, listened to us. The Lord opened her heart to respond to what Paul was saying.'
EXEC add_BibleVerse @BibleId, 344016015, N'After she and her household were baptized, she urged us, “If you consider me to be a believer in the Lord, come and stay in my house.” And she persuaded us.'
EXEC add_BibleVerse @BibleId, 344016016, N'Now as we were going to the place of prayer, a slave girl met us who had a spirit that enabled her to foretell the future by supernatural means. She brought her owners a great profit by fortune-telling.'
EXEC add_BibleVerse @BibleId, 344016017, N'She followed behind Paul and us and kept crying out, “These men are servants of the Most High God, who are proclaiming to you the way of salvation.”'
EXEC add_BibleVerse @BibleId, 344016018, N'She continued to do this for many days. But Paul became greatly annoyed, and turned and said to the spirit, “I command you in the name of Jesus Christ to come out of her!” And it came out of her at once.'
EXEC add_BibleVerse @BibleId, 344016019, N'But when her owners saw their hope of profit was gone, they seized Paul and Silas and dragged them into the marketplace before the authorities.'
EXEC add_BibleVerse @BibleId, 344016020, N'When they had brought them before the magistrates, they said, “These men are throwing our city into confusion. They are Jews'
EXEC add_BibleVerse @BibleId, 344016021, N'and are advocating customs that are not lawful for us to accept or practice, since we are Romans.”'
EXEC add_BibleVerse @BibleId, 344016022, N'The crowd joined the attack against them, and the magistrates tore the clothes off Paul and Silas and ordered them to be beaten with rods.'
EXEC add_BibleVerse @BibleId, 344016023, N'After they had beaten them severely, they threw them into prison and commanded the jailer to guard them securely.'
EXEC add_BibleVerse @BibleId, 344016024, N'Receiving such orders, he threw them in the inner cell and fastened their feet in the stocks.'
EXEC add_BibleVerse @BibleId, 344016025, N'About midnight Paul and Silas were praying and singing hymns to God, and the rest of the prisoners were listening to them.'
EXEC add_BibleVerse @BibleId, 344016026, N'Suddenly a great earthquake occurred, so that the foundations of the prison were shaken. Immediately all the doors flew open, and the bonds of all the prisoners came loose.'
EXEC add_BibleVerse @BibleId, 344016027, N'When the jailer woke up and saw the doors of the prison standing open, he drew his sword and was about to kill himself, because he assumed the prisoners had escaped.'
EXEC add_BibleVerse @BibleId, 344016028, N'But Paul called out loudly, “Do not harm yourself, for we are all here!”'
EXEC add_BibleVerse @BibleId, 344016029, N'Calling for lights, the jailer rushed in and fell down trembling at the feet of Paul and Silas.'
EXEC add_BibleVerse @BibleId, 344016030, N'Then he brought them outside and asked, “Sirs, what must I do to be saved?”'
EXEC add_BibleVerse @BibleId, 344016031, N'They replied, “Believe in the Lord Jesus and you will be saved, you and your household.”'
EXEC add_BibleVerse @BibleId, 344016032, N'Then they spoke the word of the Lord to him, along with all those who were in his house.'
EXEC add_BibleVerse @BibleId, 344016033, N'At that hour of the night he took them and washed their wounds; then he and all his family were baptized right away.'
EXEC add_BibleVerse @BibleId, 344016034, N'The jailer brought them into his house and set food before them, and he rejoiced greatly that he had come to believe in God, together with his entire household.'
EXEC add_BibleVerse @BibleId, 344016035, N'At daybreak the magistrates sent their police officers, saying, “Release those men.”'
EXEC add_BibleVerse @BibleId, 344016036, N'The jailer reported these words to Paul, saying, “The magistrates have sent orders to release you. So come out now and go in peace.”'
EXEC add_BibleVerse @BibleId, 344016037, N'But Paul said to the police officers, “They had us beaten in public without a proper trial – even though we are Roman citizens – and they threw us in prison. And now they want to send us away secretly? Absolutely not! They themselves must come and escort us out!”'
EXEC add_BibleVerse @BibleId, 344016038, N'The police officers reported these words to the magistrates. They were frightened when they heard Paul and Silas were Roman citizens'
EXEC add_BibleVerse @BibleId, 344016039, N'and came and apologized to them. After they brought them out, they asked them repeatedly to leave the city.'
EXEC add_BibleVerse @BibleId, 344016040, N'When they came out of the prison, they entered Lydia’s house, and when they saw the brothers, they encouraged them and then departed.'
EXEC add_BibleVerse @BibleId, 344017001, N'After they traveled through Amphipolis and Apollonia, they came to Thessalonica, where there was a Jewish synagogue.'
EXEC add_BibleVerse @BibleId, 344017002, N'Paul went to the Jews in the synagogue, as he customarily did, and on three Sabbath days he addressed them from the scriptures,'
EXEC add_BibleVerse @BibleId, 344017003, N'explaining and demonstrating that the Christ had to suffer and to rise from the dead, saying, “This Jesus I am proclaiming to you is the Christ.”'
EXEC add_BibleVerse @BibleId, 344017004, N'Some of them were persuaded and joined Paul and Silas, along with a large group of God-fearing Greeks and quite a few prominent women.'
EXEC add_BibleVerse @BibleId, 344017005, N'But the Jews became jealous, and gathering together some worthless men from the rabble in the marketplace, they formed a mob and set the city in an uproar. They attacked Jason’s house, trying to find Paul and Silas to bring them out to the assembly.'
EXEC add_BibleVerse @BibleId, 344017006, N'When they did not find them, they dragged Jason and some of the brothers before the city officials, screaming, “These people who have stirred up trouble throughout the world have come here too,'
EXEC add_BibleVerse @BibleId, 344017007, N'and Jason has welcomed them as guests! They are all acting against Caesar’s decrees, saying there is another king named Jesus!”'
EXEC add_BibleVerse @BibleId, 344017008, N'They caused confusion among the crowd and the city officials who heard these things.'
EXEC add_BibleVerse @BibleId, 344017009, N'After the city officials had received bail from Jason and the others, they released them.'
EXEC add_BibleVerse @BibleId, 344017010, N'The brothers sent Paul and Silas off to Berea at once, during the night. When they arrived, they went to the Jewish synagogue.'
EXEC add_BibleVerse @BibleId, 344017011, N'These Jews were more open-minded than those in Thessalonica, for they eagerly received the message, examining the scriptures carefully every day to see if these things were so.'
EXEC add_BibleVerse @BibleId, 344017012, N'Therefore many of them believed, along with quite a few prominent Greek women and men.'
EXEC add_BibleVerse @BibleId, 344017013, N'But when the Jews from Thessalonica heard that Paul had also proclaimed the word of God in Berea, they came there too, inciting and disturbing the crowds.'
EXEC add_BibleVerse @BibleId, 344017014, N'Then the brothers sent Paul away to the coast at once, but Silas and Timothy remained in Berea.'
EXEC add_BibleVerse @BibleId, 344017015, N'Those who accompanied Paul escorted him as far as Athens, and after receiving an order for Silas and Timothy to come to him as soon as possible, they left.'
EXEC add_BibleVerse @BibleId, 344017016, N'While Paul was waiting for them in Athens, his spirit was greatly upset because he saw the city was full of idols.'
EXEC add_BibleVerse @BibleId, 344017017, N'So he was addressing the Jews and the God-fearing Gentiles in the synagogue, and in the marketplace every day those who happened to be there.'
EXEC add_BibleVerse @BibleId, 344017018, N'Also some of the Epicurean and Stoic philosophers were conversing with him, and some were asking, “What does this foolish babbler want to say?” Others said, “He seems to be a proclaimer of foreign gods.” (They said this because he was proclaiming the good news about Jesus and the resurrection.)'
EXEC add_BibleVerse @BibleId, 344017019, N'So they took Paul and brought him to the Areopagus, saying, “May we know what this new teaching is that you are proclaiming?'
EXEC add_BibleVerse @BibleId, 344017020, N'For you are bringing some surprising things to our ears, so we want to know what they mean.”'
EXEC add_BibleVerse @BibleId, 344017021, N'(All the Athenians and the foreigners who lived there used to spend their time in nothing else than telling or listening to something new.)'
EXEC add_BibleVerse @BibleId, 344017022, N'So Paul stood before the Areopagus and said, “Men of Athens, I see that you are very religious in all respects.'
EXEC add_BibleVerse @BibleId, 344017023, N'For as I went around and observed closely your objects of worship, I even found an altar with this inscription: ‘To an unknown god.’ Therefore what you worship without knowing it, this I proclaim to you.'
EXEC add_BibleVerse @BibleId, 344017024, N'The God who made the world and everything in it, who is Lord of heaven and earth, does not live in temples made by human hands,'
EXEC add_BibleVerse @BibleId, 344017025, N'nor is he served by human hands, as if he needed anything, because he himself gives life and breath and everything to everyone.'
EXEC add_BibleVerse @BibleId, 344017026, N'From one man he made every nation of the human race to inhabit the entire earth, determining their set times and the fixed limits of the places where they would live,'
EXEC add_BibleVerse @BibleId, 344017027, N'so that they would search for God and perhaps grope around for him and find him, though he is not far from each one of us.'
EXEC add_BibleVerse @BibleId, 344017028, N'For in him we live and move about and exist, as even some of your own poets have said, ‘For we too are his offspring.’'
EXEC add_BibleVerse @BibleId, 344017029, N'So since we are God’s offspring, we should not think the deity is like gold or silver or stone, an image made by human skill and imagination.'
EXEC add_BibleVerse @BibleId, 344017030, N'Therefore, although God has overlooked such times of ignorance, he now commands all people everywhere to repent,'
EXEC add_BibleVerse @BibleId, 344017031, N'because he has set a day on which he is going to judge the world in righteousness, by a man whom he designated, having provided proof to everyone by raising him from the dead.”'
EXEC add_BibleVerse @BibleId, 344017032, N'Now when they heard about the resurrection from the dead, some began to scoff, but others said, “We will hear you again about this.”'
EXEC add_BibleVerse @BibleId, 344017033, N'So Paul left the Areopagus.'
EXEC add_BibleVerse @BibleId, 344017034, N'But some people joined him and believed. Among them were Dionysius, who was a member of the Areopagus, a woman named Damaris, and others with them.'
EXEC add_BibleVerse @BibleId, 344018001, N'After this Paul departed from Athens'
EXEC add_BibleVerse @BibleId, 344018002, N'There he found a Jew named Aquila, a native of Pontus, who had recently come from Italy with his wife Priscilla, because Claudius had ordered all the Jews to depart from Rome. Paul approached them,'
EXEC add_BibleVerse @BibleId, 344018003, N'and because he worked at the same trade, he stayed with them and worked with them (for they were tentmakers by trade).'
EXEC add_BibleVerse @BibleId, 344018004, N'He addressed both Jews and Greeks in the synagogue every Sabbath, attempting to persuade them.'
EXEC add_BibleVerse @BibleId, 344018005, N'Now when Silas and Timothy arrived from Macedonia, Paul became wholly absorbed with proclaiming the word, testifying to the Jews that Jesus was the Christ.'
EXEC add_BibleVerse @BibleId, 344018006, N'When they opposed him and reviled him, he protested by shaking out his clothes and said to them, “Your blood be on your own heads! I am guiltless! From now on I will go to the Gentiles!”'
EXEC add_BibleVerse @BibleId, 344018007, N'Then Paul left the synagogue and went to the house of a person named Titius Justus, a Gentile who worshiped God, whose house was next door to the synagogue.'
EXEC add_BibleVerse @BibleId, 344018008, N'Crispus, the president of the synagogue, believed in the Lord together with his entire household, and many of the Corinthians who heard about it believed and were baptized.'
EXEC add_BibleVerse @BibleId, 344018009, N'The Lord said to Paul by a vision in the night, “Do not be afraid, but speak and do not be silent,'
EXEC add_BibleVerse @BibleId, 344018010, N'because I am with you, and no one will assault you to harm you, because I have many people in this city.”'
EXEC add_BibleVerse @BibleId, 344018011, N'So he stayed there a year and six months, teaching the word of God among them.'
EXEC add_BibleVerse @BibleId, 344018012, N'Now while Gallio was proconsul of Achaia, the Jews attacked Paul together and brought him before the judgment seat,'
EXEC add_BibleVerse @BibleId, 344018013, N'saying, “This man is persuading people to worship God in a way contrary to the law!”'
EXEC add_BibleVerse @BibleId, 344018014, N'But just as Paul was about to speak, Gallio said to the Jews, “If it were a matter of some crime or serious piece of villainy, I would have been justified in accepting the complaint of you Jews,'
EXEC add_BibleVerse @BibleId, 344018015, N'but since it concerns points of disagreement about words and names and your own law, settle it yourselves. I will not be a judge of these things!”'
EXEC add_BibleVerse @BibleId, 344018016, N'Then he had them forced away from the judgment seat.'
EXEC add_BibleVerse @BibleId, 344018017, N'So they all seized Sosthenes, the president of the synagogue, and began to beat him in front of the judgment seat. Yet none of these things were of any concern to Gallio.'
EXEC add_BibleVerse @BibleId, 344018018, N'Paul, after staying many more days in Corinth, said farewell to the brothers and sailed away to Syria accompanied by Priscilla and Aquila. He had his hair cut off at Cenchrea because he had made a vow.'
EXEC add_BibleVerse @BibleId, 344018019, N'When they reached Ephesus, Paul left Priscilla and Aquila behind there, but he himself went into the synagogue and addressed the Jews.'
EXEC add_BibleVerse @BibleId, 344018020, N'When they asked him to stay longer, he would not consent,'
EXEC add_BibleVerse @BibleId, 344018021, N'but said farewell to them and added, “I will come back to you again if God wills.” Then he set sail from Ephesus,'
EXEC add_BibleVerse @BibleId, 344018022, N'and when he arrived at Caesarea,'
EXEC add_BibleVerse @BibleId, 344018023, N'After he spent some time there, Paul left and went through the region of Galatia and Phrygia, strengthening all the disciples.'
EXEC add_BibleVerse @BibleId, 344018024, N'Now a Jew named Apollos, a native of Alexandria, arrived in Ephesus. He was an eloquent speaker, well-versed in the scriptures.'
EXEC add_BibleVerse @BibleId, 344018025, N'He had been instructed in the way of the Lord, and with great enthusiasm he spoke and taught accurately the facts about Jesus, although he knew only the baptism of John.'
EXEC add_BibleVerse @BibleId, 344018026, N'He began to speak out fearlessly in the synagogue, but when Priscilla and Aquila heard him, they took him aside and explained the way of God to him more accurately.'
EXEC add_BibleVerse @BibleId, 344018027, N'When Apollos wanted to cross over to Achaia, the brothers encouraged him and wrote to the disciples to welcome him. When he arrived, he assisted greatly those who had believed by grace,'
EXEC add_BibleVerse @BibleId, 344018028, N'for he refuted the Jews vigorously in public debate, demonstrating from the scriptures that the Christ was Jesus.'
EXEC add_BibleVerse @BibleId, 344019001, N'While Apollos was in Corinth, He found some disciples there'
EXEC add_BibleVerse @BibleId, 344019002, N'and said to them, “Did you receive the Holy Spirit when you believed?” They replied, “No, we have not even heard that there is a Holy Spirit.”'
EXEC add_BibleVerse @BibleId, 344019003, N'So Paul said, “Into what then were you baptized?” “Into John’s baptism,” they replied.'
EXEC add_BibleVerse @BibleId, 344019004, N'Paul said, “John baptized with a baptism of repentance, telling the people to believe in the one who was to come after him, that is, in Jesus.”'
EXEC add_BibleVerse @BibleId, 344019005, N'When they heard this, they were baptized in the name of the Lord Jesus,'
EXEC add_BibleVerse @BibleId, 344019006, N'and when Paul placed his hands on them, the Holy Spirit came upon them, and they began to speak in tongues and to prophesy.'
EXEC add_BibleVerse @BibleId, 344019007, N'(Now there were about twelve men in all.)'
EXEC add_BibleVerse @BibleId, 344019008, N'So Paul entered the synagogue and spoke out fearlessly for three months, addressing and convincing them about the kingdom of God.'
EXEC add_BibleVerse @BibleId, 344019009, N'But when some were stubborn and refused to believe, reviling the Way before the congregation, he left them and took the disciples with him, addressing them every day in the lecture hall of Tyrannus.'
EXEC add_BibleVerse @BibleId, 344019010, N'This went on for two years, so that all who lived in the province of Asia, both Jews and Greeks, heard the word of the Lord.'
EXEC add_BibleVerse @BibleId, 344019011, N'God was performing extraordinary miracles by Paul’s hands,'
EXEC add_BibleVerse @BibleId, 344019012, N'so that when even handkerchiefs or aprons that had touched his body were brought to the sick, their diseases left them and the evil spirits went out of them.'
EXEC add_BibleVerse @BibleId, 344019013, N'But some itinerant Jewish exorcists tried to invoke the name of the Lord Jesus over those who were possessed by evil spirits, saying, “I sternly warn you by Jesus whom Paul preaches.”'
EXEC add_BibleVerse @BibleId, 344019014, N'(Now seven sons of a man named Sceva, a Jewish high priest, were doing this.)'
EXEC add_BibleVerse @BibleId, 344019015, N'But the evil spirit replied to them, “I know about Jesus and I am acquainted with Paul, but who are you?”'
EXEC add_BibleVerse @BibleId, 344019016, N'Then the man who was possessed by the evil spirit jumped on them and beat them all into submission. He prevailed against them so that they fled from that house naked and wounded.'
EXEC add_BibleVerse @BibleId, 344019017, N'This became known to all who lived in Ephesus, both Jews and Greeks; fear came over them all, and the name of the Lord Jesus was praised.'
EXEC add_BibleVerse @BibleId, 344019018, N'Many of those who had believed came forward, confessing and making their deeds known.'
EXEC add_BibleVerse @BibleId, 344019019, N'Large numbers of those who had practiced magic collected their books and burned them up in the presence of everyone. When the value of the books was added up, it was found to total fifty thousand silver coins.'
EXEC add_BibleVerse @BibleId, 344019020, N'In this way the word of the Lord continued to grow in power and to prevail.'
EXEC add_BibleVerse @BibleId, 344019021, N'Now after all these things had taken place, Paul resolved to go to Jerusalem, passing through Macedonia and Achaia. He said, “After I have been there, I must also see Rome.”'
EXEC add_BibleVerse @BibleId, 344019022, N'So after sending two of his assistants, Timothy and Erastus, to Macedonia, he himself stayed on for a while in the province of Asia.'
EXEC add_BibleVerse @BibleId, 344019023, N'At that time a great disturbance took place concerning the Way.'
EXEC add_BibleVerse @BibleId, 344019024, N'For a man named Demetrius, a silversmith who made silver shrines of Artemis, brought a great deal of business to the craftsmen.'
EXEC add_BibleVerse @BibleId, 344019025, N'He gathered these together, along with the workmen in similar trades, and said, “Men, you know that our prosperity comes from this business.'
EXEC add_BibleVerse @BibleId, 344019026, N'And you see and hear that this Paul has persuaded and turned away a large crowd, not only in Ephesus but in practically all of the province of Asia, by saying that gods made by hands are not gods at all.'
EXEC add_BibleVerse @BibleId, 344019027, N'There is danger not only that this business of ours will come into disrepute, but also that the temple of the great goddess Artemis will be regarded as nothing, and she whom all the province of Asia and the world worship will suffer the loss of her greatness.”'
EXEC add_BibleVerse @BibleId, 344019028, N'When they heard this they became enraged and began to shout, “Great is Artemis of the Ephesians!”'
EXEC add_BibleVerse @BibleId, 344019029, N'The city was filled with the uproar, and the crowd rushed to the theater together, dragging with them Gaius and Aristarchus, the Macedonians who were Paul’s traveling companions.'
EXEC add_BibleVerse @BibleId, 344019030, N'But when Paul wanted to enter the public assembly, the disciples would not let him.'
EXEC add_BibleVerse @BibleId, 344019031, N'Even some of the provincial authorities who were his friends sent a message to him, urging him not to venture into the theater.'
EXEC add_BibleVerse @BibleId, 344019032, N'So then some were shouting one thing, some another, for the assembly was in confusion, and most of them did not know why they had met together.'
EXEC add_BibleVerse @BibleId, 344019033, N'Some of the crowd concluded it was about Alexander because the Jews had pushed him to the front. Alexander, gesturing with his hand, was wanting to make a defense before the public assembly.'
EXEC add_BibleVerse @BibleId, 344019034, N'But when they recognized that he was a Jew, they all shouted in unison, “Great is Artemis of the Ephesians!” for about two hours.'
EXEC add_BibleVerse @BibleId, 344019035, N'After the city secretary quieted the crowd, he said, “Men of Ephesus, what person is there who does not know that the city of the Ephesians is the keeper of the temple of the great Artemis and of her image that fell from heaven?'
EXEC add_BibleVerse @BibleId, 344019036, N'So because these facts are indisputable, you must keep quiet and not do anything reckless.'
EXEC add_BibleVerse @BibleId, 344019037, N'For you have brought these men here who are neither temple robbers nor blasphemers of our goddess.'
EXEC add_BibleVerse @BibleId, 344019038, N'If then Demetrius and the craftsmen who are with him have a complaint against someone, the courts are open and there are proconsuls; let them bring charges against one another there.'
EXEC add_BibleVerse @BibleId, 344019039, N'But if you want anything in addition, it will have to be settled in a legal assembly.'
EXEC add_BibleVerse @BibleId, 344019040, N'For we are in danger of being charged with rioting today, since there is no cause we can give to explain this disorderly gathering.”'
EXEC add_BibleVerse @BibleId, 344019041, N'After he had said this, he dismissed the assembly.'
EXEC add_BibleVerse @BibleId, 344020001, N'After the disturbance had ended, Paul sent for the disciples, and after encouraging them and saying farewell, he left to go to Macedonia.'
EXEC add_BibleVerse @BibleId, 344020002, N'After he had gone through those regions and spoken many words of encouragement to the believers there, he came to Greece,'
EXEC add_BibleVerse @BibleId, 344020003, N'where he stayed for three months. Because the Jews had made a plot against him as he was intending to sail for Syria, he decided to return through Macedonia.'
EXEC add_BibleVerse @BibleId, 344020004, N'Paul was accompanied by Sopater son of Pyrrhus from Berea, and Timothy, as well as Tychicus and Trophimus from the province of Asia.'
EXEC add_BibleVerse @BibleId, 344020005, N'These had gone on ahead and were waiting for us in Troas.'
EXEC add_BibleVerse @BibleId, 344020006, N'We sailed away from Philippi after the days of Unleavened Bread, and within five days we came to the others in Troas, where we stayed for seven days.'
EXEC add_BibleVerse @BibleId, 344020007, N'On the first day of the week, when we met to break bread, Paul began to speak to the people, and because he intended to leave the next day, he extended his message until midnight.'
EXEC add_BibleVerse @BibleId, 344020008, N'(Now there were many lamps in the upstairs room where we were meeting.)'
EXEC add_BibleVerse @BibleId, 344020009, N'A young man named Eutychus, who was sitting in the window, was sinking into a deep sleep while Paul continued to speak for a long time. Fast asleep, he fell down from the third story and was picked up dead.'
EXEC add_BibleVerse @BibleId, 344020010, N'But Paul went down, threw himself on the young man, put his arms around him, and said, “Do not be distressed, for he is still alive!”'
EXEC add_BibleVerse @BibleId, 344020011, N'Then Paul went back upstairs, and after he had broken bread and eaten, he talked with them a long time, until dawn. Then he left.'
EXEC add_BibleVerse @BibleId, 344020012, N'They took the boy home alive and were greatly comforted.'
EXEC add_BibleVerse @BibleId, 344020013, N'We went on ahead to the ship and put out to sea for Assos, intending to take Paul aboard there, for he had arranged it this way. He himself was intending to go there by land.'
EXEC add_BibleVerse @BibleId, 344020014, N'When he met us in Assos, we took him aboard and went to Mitylene.'
EXEC add_BibleVerse @BibleId, 344020015, N'We set sail from there, and on the following day we arrived off Chios. The next day we approached Samos, and the day after that we arrived at Miletus.'
EXEC add_BibleVerse @BibleId, 344020016, N'For Paul had decided to sail past Ephesus if possible, by the day of Pentecost.'
EXEC add_BibleVerse @BibleId, 344020017, N'From Miletus he sent a message to Ephesus, telling the elders of the church to come to him.'
EXEC add_BibleVerse @BibleId, 344020018, N'When they arrived, he said to them, “You yourselves know how I lived the whole time I was with you, from the first day I set foot in the province of Asia,'
EXEC add_BibleVerse @BibleId, 344020019, N'serving the Lord with all humility and with tears, and with the trials that happened to me because of the plots of the Jews.'
EXEC add_BibleVerse @BibleId, 344020020, N'You know that I did not hold back from proclaiming to you anything that would be helpful, and from teaching you publicly and from house to house,'
EXEC add_BibleVerse @BibleId, 344020021, N'testifying to both Jews and Greeks about repentance toward God and faith in our Lord Jesus.'
EXEC add_BibleVerse @BibleId, 344020022, N'And now, compelled by the Spirit, I am going to Jerusalem without knowing what will happen to me there,'
EXEC add_BibleVerse @BibleId, 344020023, N'except that the Holy Spirit warns me in town after town that imprisonment and persecutions are waiting for me.'
EXEC add_BibleVerse @BibleId, 344020024, N'But I do not consider my life worth anything to myself, so that I may finish my task and the ministry that I received from the Lord Jesus, to testify to the good news of God’s grace.'
EXEC add_BibleVerse @BibleId, 344020025, N'“And now I know that none of you among whom I went around proclaiming the kingdom will see me again.'
EXEC add_BibleVerse @BibleId, 344020026, N'Therefore I declare to you today that I am innocent of the blood of you all.'
EXEC add_BibleVerse @BibleId, 344020027, N'For I did not hold back from announcing to you the whole purpose of God.'
EXEC add_BibleVerse @BibleId, 344020028, N'Watch out for yourselves and for all the flock of which the Holy Spirit has made you overseers, to shepherd the church of God that he obtained with the blood of his own Son.'
EXEC add_BibleVerse @BibleId, 344020029, N'I know that after I am gone fierce wolves will come in among you, not sparing the flock.'
EXEC add_BibleVerse @BibleId, 344020030, N'Even from among your own group men will arise, teaching perversions of the truth to draw the disciples away after them.'
EXEC add_BibleVerse @BibleId, 344020031, N'Therefore be alert, remembering that night and day for three years I did not stop warning each one of you with tears.'
EXEC add_BibleVerse @BibleId, 344020032, N'And now I entrust you to God and to the message of his grace. This message is able to build you up and give you an inheritance among all those who are sanctified.'
EXEC add_BibleVerse @BibleId, 344020033, N'I have desired no one’s silver or gold or clothing.'
EXEC add_BibleVerse @BibleId, 344020034, N'You yourselves know that these hands of mine provided for my needs and the needs of those who were with me.'
EXEC add_BibleVerse @BibleId, 344020035, N'By all these things, I have shown you that by working in this way we must help the weak, and remember the words of the Lord Jesus that he himself said, ‘It is more blessed to give than to receive.’”'
EXEC add_BibleVerse @BibleId, 344020036, N'When he had said these things, he knelt down with them all and prayed.'
EXEC add_BibleVerse @BibleId, 344020037, N'They all began to weep loudly, and hugged Paul and kissed him,'
EXEC add_BibleVerse @BibleId, 344020038, N'especially saddened by what he had said, that they were not going to see him again. Then they accompanied him to the ship.'
EXEC add_BibleVerse @BibleId, 344021001, N'After we tore ourselves away from them, we put out to sea, and sailing a straight course, we came to Cos, on the next day to Rhodes, and from there to Patara.'
EXEC add_BibleVerse @BibleId, 344021002, N'We found a ship crossing over to Phoenicia, went aboard, and put out to sea.'
EXEC add_BibleVerse @BibleId, 344021003, N'After we sighted Cyprus and left it behind on our port side, we sailed on to Syria and put in at Tyre, because the ship was to unload its cargo there.'
EXEC add_BibleVerse @BibleId, 344021004, N'After we located the disciples, we stayed there seven days. They repeatedly told Paul through the Spirit not to set foot in Jerusalem.'
EXEC add_BibleVerse @BibleId, 344021005, N'When our time was over, we left and went on our way. All of them, with their wives and children, accompanied us outside of the city. After kneeling down on the beach and praying,'
EXEC add_BibleVerse @BibleId, 344021006, N'we said farewell to one another. Then we went aboard the ship, and they returned to their own homes.'
EXEC add_BibleVerse @BibleId, 344021007, N'We continued the voyage from Tyre and arrived at Ptolemais, and when we had greeted the brothers, we stayed with them for one day.'
EXEC add_BibleVerse @BibleId, 344021008, N'On the next day we left and came to Caesarea, and entered the house of Philip the evangelist, who was one of the seven, and stayed with him.'
EXEC add_BibleVerse @BibleId, 344021009, N'(He had four unmarried daughters who prophesied.)'
EXEC add_BibleVerse @BibleId, 344021010, N'While we remained there for a number of days, a prophet named Agabus came down from Judea.'
EXEC add_BibleVerse @BibleId, 344021011, N'He came to us, took Paul’s belt, tied his own hands and feet with it, and said, “The Holy Spirit says this: ‘This is the way the Jews in Jerusalem will tie up the man whose belt this is, and will hand him over to the Gentiles.’”'
EXEC add_BibleVerse @BibleId, 344021012, N'When we heard this, both we and the local people begged him not to go up to Jerusalem.'
EXEC add_BibleVerse @BibleId, 344021013, N'Then Paul replied, “What are you doing, weeping and breaking my heart? For I am ready not only to be tied up, but even to die in Jerusalem for the name of the Lord Jesus.”'
EXEC add_BibleVerse @BibleId, 344021014, N'Because he could not be persuaded, we said no more except, “The Lord’s will be done.”'
EXEC add_BibleVerse @BibleId, 344021015, N'After these days we got ready and started up to Jerusalem.'
EXEC add_BibleVerse @BibleId, 344021016, N'Some of the disciples from Caesarea came along with us too, and brought us to the house of Mnason of Cyprus, a disciple from the earliest times, with whom we were to stay.'
EXEC add_BibleVerse @BibleId, 344021017, N'When we arrived in Jerusalem, the brothers welcomed us gladly.'
EXEC add_BibleVerse @BibleId, 344021018, N'The next day Paul went in with us to see James, and all the elders were there.'
EXEC add_BibleVerse @BibleId, 344021019, N'When Paul had greeted them, he began to explain in detail what God had done among the Gentiles through his ministry.'
EXEC add_BibleVerse @BibleId, 344021020, N'When they heard this, they praised God. Then they said to him, “You see, brother, how many thousands of Jews there are who have believed, and they are all ardent observers of the law.'
EXEC add_BibleVerse @BibleId, 344021021, N'They have been informed about you – that you teach all the Jews now living among the Gentiles to abandon Moses, telling them not to circumcise their children or live according to our customs.'
EXEC add_BibleVerse @BibleId, 344021022, N'What then should we do? They will no doubt hear that you have come.'
EXEC add_BibleVerse @BibleId, 344021023, N'So do what we tell you: We have four men who have taken a vow;'
EXEC add_BibleVerse @BibleId, 344021024, N'take them and purify yourself along with them and pay their expenses, so that they may have their heads shaved. Then everyone will know there is nothing in what they have been told about you, but that you yourself live in conformity with the law.'
EXEC add_BibleVerse @BibleId, 344021025, N'But regarding the Gentiles who have believed, we have written a letter, having decided that they should avoid meat that has been sacrificed to idols and blood and what has been strangled and sexual immorality.”'
EXEC add_BibleVerse @BibleId, 344021026, N'Then Paul took the men the next day, and after he had purified himself along with them, he went to the temple and gave notice of the completion of the days of purification, when the sacrifice would be offered for each of them.'
EXEC add_BibleVerse @BibleId, 344021027, N'When the seven days were almost over, the Jews from the province of Asia who had seen him in the temple area stirred up the whole crowd and seized him,'
EXEC add_BibleVerse @BibleId, 344021028, N'shouting, “Men of Israel, help! This is the man who teaches everyone everywhere against our people, our law, and this sanctuary! Furthermore he has brought Greeks into the inner courts of the temple and made this holy place ritually unclean!”'
EXEC add_BibleVerse @BibleId, 344021029, N'(For they had seen Trophimus the Ephesian in the city with him previously, and they assumed Paul had brought him into the inner temple courts.)'
EXEC add_BibleVerse @BibleId, 344021030, N'The whole city was stirred up, and the people rushed together. They seized Paul and dragged him out of the temple courts, and immediately the doors were shut.'
EXEC add_BibleVerse @BibleId, 344021031, N'While they were trying to kill him, a report was sent up to the commanding officer of the cohort that all Jerusalem was in confusion.'
EXEC add_BibleVerse @BibleId, 344021032, N'He immediately took soldiers and centurions and ran down to the crowd. When they saw the commanding officer and the soldiers, they stopped beating Paul.'
EXEC add_BibleVerse @BibleId, 344021033, N'Then the commanding officer came up and arrested him and ordered him to be tied up with two chains; he then asked who he was and what he had done.'
EXEC add_BibleVerse @BibleId, 344021034, N'But some in the crowd shouted one thing, and others something else, and when the commanding officer was unable to find out the truth because of the disturbance, he ordered Paul to be brought into the barracks.'
EXEC add_BibleVerse @BibleId, 344021035, N'When he came to the steps, Paul had to be carried by the soldiers because of the violence of the mob,'
EXEC add_BibleVerse @BibleId, 344021036, N'for a crowd of people followed them, screaming, “Away with him!”'
EXEC add_BibleVerse @BibleId, 344021037, N'As Paul was about to be brought into the barracks, he said to the commanding officer, “May I say something to you?” The officer replied, “Do you know Greek?'
EXEC add_BibleVerse @BibleId, 344021038, N'Then you’re not that Egyptian who started a rebellion and led the four thousand men of the ‘Assassins’ into the wilderness some time ago?”'
EXEC add_BibleVerse @BibleId, 344021039, N'Paul answered, “I am a Jew from Tarsus in Cilicia, a citizen of an important city. Please allow me to speak to the people.”'
EXEC add_BibleVerse @BibleId, 344021040, N'When the commanding officer had given him permission, Paul stood on the steps and gestured to the people with his hand. When they had become silent, he addressed them in Aramaic,'
EXEC add_BibleVerse @BibleId, 344022001, N'“Brothers and fathers, listen to my defense that I now make to you.”'
EXEC add_BibleVerse @BibleId, 344022002, N'(When they heard that he was addressing them in Aramaic, they became even quieter.) Then Paul said,'
EXEC add_BibleVerse @BibleId, 344022003, N'“I am a Jew, born in Tarsus in Cilicia, but brought up in this city, educated with strictness under Gamaliel according to the law of our ancestors, and was zealous for God just as all of you are today.'
EXEC add_BibleVerse @BibleId, 344022004, N'I persecuted this Way even to the point of death, tying up both men and women and putting them in prison,'
EXEC add_BibleVerse @BibleId, 344022005, N'as both the high priest and the whole council of elders can testify about me. From them I also received letters to the brothers in Damascus, and I was on my way to make arrests there and bring the prisoners to Jerusalem to be punished.'
EXEC add_BibleVerse @BibleId, 344022006, N'As I was en route and near Damascus, about noon a very bright light from heaven suddenly flashed around me.'
EXEC add_BibleVerse @BibleId, 344022007, N'Then I fell to the ground and heard a voice saying to me, ‘Saul, Saul, why are you persecuting me?’'
EXEC add_BibleVerse @BibleId, 344022008, N'I answered, ‘Who are you, Lord?’ He said to me, ‘I am Jesus the Nazarene, whom you are persecuting.’'
EXEC add_BibleVerse @BibleId, 344022009, N'Those who were with me saw the light, but did not understand the voice of the one who was speaking to me.'
EXEC add_BibleVerse @BibleId, 344022010, N'So I asked, ‘What should I do, Lord?’ The Lord said to me, ‘Get up and go to Damascus; there you will be told about everything that you have been designated to do.’'
EXEC add_BibleVerse @BibleId, 344022011, N'Since I could not see because of the brilliance of that light, I came to Damascus led by the hand of those who were with me.'
EXEC add_BibleVerse @BibleId, 344022012, N'A man named Ananias, a devout man according to the law, well spoken of by all the Jews who live there,'
EXEC add_BibleVerse @BibleId, 344022013, N'came to me and stood beside me and said to me, ‘Brother Saul, regain your sight!’ And at that very moment I looked up and saw him.'
EXEC add_BibleVerse @BibleId, 344022014, N'Then he said, ‘The God of our ancestors has already chosen you to know his will, to see the Righteous One, and to hear a command from his mouth,'
EXEC add_BibleVerse @BibleId, 344022015, N'because you will be his witness to all people of what you have seen and heard.'
EXEC add_BibleVerse @BibleId, 344022016, N'And now what are you waiting for? Get up, be baptized, and have your sins washed away, calling on his name.’'
EXEC add_BibleVerse @BibleId, 344022017, N'When I returned to Jerusalem and was praying in the temple, I fell into a trance'
EXEC add_BibleVerse @BibleId, 344022018, N'and saw the Lord saying to me, ‘Hurry and get out of Jerusalem quickly, because they will not accept your testimony about me.’'
EXEC add_BibleVerse @BibleId, 344022019, N'I replied, ‘Lord, they themselves know that I imprisoned and beat those in the various synagogues who believed in you.'
EXEC add_BibleVerse @BibleId, 344022020, N'And when the blood of your witness Stephen was shed, I myself was standing nearby, approving, and guarding the cloaks of those who were killing him.’'
EXEC add_BibleVerse @BibleId, 344022021, N'Then he said to me, ‘Go, because I will send you far away to the Gentiles.’”'
EXEC add_BibleVerse @BibleId, 344022022, N'The crowd was listening to him until he said this. Then they raised their voices and shouted, “Away with this man from the earth! For he should not be allowed to live!”'
EXEC add_BibleVerse @BibleId, 344022023, N'While they were screaming and throwing off their cloaks and tossing dust in the air,'
EXEC add_BibleVerse @BibleId, 344022024, N'the commanding officer ordered Paul to be brought back into the barracks. He told them to interrogate Paul by beating him with a lash so that he could find out the reason the crowd was shouting at Paul in this way.'
EXEC add_BibleVerse @BibleId, 344022025, N'When they had stretched him out for the lash, Paul said to the centurion standing nearby, “Is it legal for you to lash a man who is a Roman citizen without a proper trial?”'
EXEC add_BibleVerse @BibleId, 344022026, N'When the centurion heard this, he went to the commanding officer and reported it, saying, “What are you about to do? For this man is a Roman citizen.”'
EXEC add_BibleVerse @BibleId, 344022027, N'So the commanding officer came and asked Paul, “Tell me, are you a Roman citizen?” He replied, “Yes.”'
EXEC add_BibleVerse @BibleId, 344022028, N'The commanding officer answered, “I acquired this citizenship with a large sum of money.” “But I was even born a citizen,” Paul replied.'
EXEC add_BibleVerse @BibleId, 344022029, N'Then those who were about to interrogate him stayed away from him, and the commanding officer was frightened when he realized that Paul was a Roman citizen and that he had had him tied up.'
EXEC add_BibleVerse @BibleId, 344022030, N'The next day, because the commanding officer wanted to know the true reason Paul was being accused by the Jews, he released him and ordered the chief priests and the whole council to assemble. He then brought Paul down and had him stand before them.'
EXEC add_BibleVerse @BibleId, 344023001, N'Paul looked directly at the council and said, “Brothers, I have lived my life with a clear conscience before God to this day.”'
EXEC add_BibleVerse @BibleId, 344023002, N'At that the high priest Ananias ordered those standing near Paul to strike him on the mouth.'
EXEC add_BibleVerse @BibleId, 344023003, N'Then Paul said to him, “God is going to strike you, you whitewashed wall! Do you sit there judging me according to the law, and in violation of the law you order me to be struck?”'
EXEC add_BibleVerse @BibleId, 344023004, N'Those standing near him said, “Do you dare insult God’s high priest?”'
EXEC add_BibleVerse @BibleId, 344023005, N'Paul replied, “I did not realize, brothers, that he was the high priest, for it is written, ‘ You must not speak evil about a ruler of your people.’”'
EXEC add_BibleVerse @BibleId, 344023006, N'Then when Paul noticed that part of them were Sadducees and the others Pharisees, he shouted out in the council, “Brothers, I am a Pharisee, a son of Pharisees. I am on trial concerning the hope of the resurrection of the dead!”'
EXEC add_BibleVerse @BibleId, 344023007, N'When he said this, an argument began between the Pharisees and the Sadducees, and the assembly was divided.'
EXEC add_BibleVerse @BibleId, 344023008, N'(For the Sadducees say there is no resurrection, or angel, or spirit, but the Pharisees acknowledge them all.)'
EXEC add_BibleVerse @BibleId, 344023009, N'There was a great commotion, and some experts in the law from the party of the Pharisees stood up and protested strongly, “We find nothing wrong with this man. What if a spirit or an angel has spoken to him?”'
EXEC add_BibleVerse @BibleId, 344023010, N'When the argument became so great the commanding officer feared that they would tear Paul to pieces, he ordered the detachment to go down, take him away from them by force, and bring him into the barracks.'
EXEC add_BibleVerse @BibleId, 344023011, N'The following night the Lord stood near Paul and said, “Have courage, for just as you have testified about me in Jerusalem, so you must also testify in Rome.”'
EXEC add_BibleVerse @BibleId, 344023012, N'When morning came, the Jews formed a conspiracy and bound themselves with an oath not to eat or drink anything until they had killed Paul.'
EXEC add_BibleVerse @BibleId, 344023013, N'There were more than forty of them who formed this conspiracy.'
EXEC add_BibleVerse @BibleId, 344023014, N'They went to the chief priests and the elders and said, “We have bound ourselves with a solemn oath not to partake of anything until we have killed Paul.'
EXEC add_BibleVerse @BibleId, 344023015, N'So now you and the council request the commanding officer to bring him down to you, as if you were going to determine his case by conducting a more thorough inquiry. We are ready to kill him before he comes near this place.”'
EXEC add_BibleVerse @BibleId, 344023016, N'But when the son of Paul’s sister heard about the ambush, he came and entered the barracks and told Paul.'
EXEC add_BibleVerse @BibleId, 344023017, N'Paul called one of the centurions and said, “Take this young man to the commanding officer, for he has something to report to him.”'
EXEC add_BibleVerse @BibleId, 344023018, N'So the centurion took him and brought him to the commanding officer and said, “The prisoner Paul called me and asked me to bring this young man to you because he has something to tell you.”'
EXEC add_BibleVerse @BibleId, 344023019, N'The commanding officer took him by the hand, withdrew privately, and asked, “What is it that you want to report to me?”'
EXEC add_BibleVerse @BibleId, 344023020, N'He replied, “The Jews have agreed to ask you to bring Paul down to the council tomorrow, as if they were going to inquire more thoroughly about him.'
EXEC add_BibleVerse @BibleId, 344023021, N'So do not let them persuade you to do this, because more than forty of them are lying in ambush for him. They have bound themselves with an oath not to eat or drink anything until they have killed him, and now they are ready, waiting for you to agree to their request.”'
EXEC add_BibleVerse @BibleId, 344023022, N'Then the commanding officer sent the young man away, directing him, “Tell no one that you have reported these things to me.”'
EXEC add_BibleVerse @BibleId, 344023023, N'Then he summoned two of the centurions and said, “Make ready two hundred soldiers to go to Caesarea along with seventy horsemen and two hundred spearmen by nine o’clock tonight,'
EXEC add_BibleVerse @BibleId, 344023024, N'and provide mounts for Paul to ride so that he may be brought safely to Felix the governor.”'
EXEC add_BibleVerse @BibleId, 344023025, N'He wrote a letter that went like this:'
EXEC add_BibleVerse @BibleId, 344023026, N'Claudius Lysias to His Excellency Governor Felix, greetings.'
EXEC add_BibleVerse @BibleId, 344023027, N'This man was seized by the Jews and they were about to kill him, when I came up with the detachment and rescued him, because I had learned that he was a Roman citizen.'
EXEC add_BibleVerse @BibleId, 344023028, N'Since I wanted to know what charge they were accusing him of, I brought him down to their council.'
EXEC add_BibleVerse @BibleId, 344023029, N'I found he was accused with reference to controversial questions about their law, but no charge against him deserved death or imprisonment.'
EXEC add_BibleVerse @BibleId, 344023030, N'When I was informed there would be a plot against this man, I sent him to you at once, also ordering his accusers to state their charges against him before you.'
EXEC add_BibleVerse @BibleId, 344023031, N'So the soldiers, in accordance with their orders, took Paul and brought him to Antipatris during the night.'
EXEC add_BibleVerse @BibleId, 344023032, N'The next day they let the horsemen go on with him, and they returned to the barracks.'
EXEC add_BibleVerse @BibleId, 344023033, N'When the horsemen came to Caesarea and delivered the letter to the governor, they also presented Paul to him.'
EXEC add_BibleVerse @BibleId, 344023034, N'When the governor had read the letter, he asked what province he was from. When he learned that he was from Cilicia,'
EXEC add_BibleVerse @BibleId, 344023035, N'he said, “I will give you a hearing when your accusers arrive too.” Then he ordered that Paul be kept under guard in Herod’s palace.'
EXEC add_BibleVerse @BibleId, 344024001, N'After five days the high priest Ananias came down with some elders and an attorney named Tertullus, and they brought formal charges against Paul to the governor.'
EXEC add_BibleVerse @BibleId, 344024002, N'When Paul had been summoned, Tertullus began to accuse him, saying, “We have experienced a lengthy time of peace through your rule, and reforms are being made in this nation through your foresight.'
EXEC add_BibleVerse @BibleId, 344024003, N'Most excellent Felix, we acknowledge this everywhere and in every way with all gratitude.'
EXEC add_BibleVerse @BibleId, 344024004, N'But so that I may not delay you any further, I beg you to hear us briefly with your customary graciousness.'
EXEC add_BibleVerse @BibleId, 344024005, N'For we have found this man to be a troublemaker, one who stirs up riots among all the Jews throughout the world, and a ringleader of the sect of the Nazarenes.'
EXEC add_BibleVerse @BibleId, 344024006, N'He even tried to desecrate the temple, so we arrested him.'
EXEC add_BibleVerse @BibleId, 344024008, N' When you examine him yourself, you will be able to learn from him about all these things we are accusing him of doing.”'
EXEC add_BibleVerse @BibleId, 344024009, N'The Jews also joined in the verbal attack, claiming that these things were true.'
EXEC add_BibleVerse @BibleId, 344024010, N'When the governor gestured for him to speak, Paul replied, “Because I know that you have been a judge over this nation for many years, I confidently make my defense.'
EXEC add_BibleVerse @BibleId, 344024011, N'As you can verify for yourself, not more than twelve days ago I went up to Jerusalem to worship.'
EXEC add_BibleVerse @BibleId, 344024012, N'They did not find me arguing with anyone or stirring up a crowd in the temple courts or in the synagogues or throughout the city,'
EXEC add_BibleVerse @BibleId, 344024013, N'nor can they prove to you the things they are accusing me of doing.'
EXEC add_BibleVerse @BibleId, 344024014, N'But I confess this to you, that I worship the God of our ancestors according to the Way (which they call a sect), believing everything that is according to the law and that is written in the prophets.'
EXEC add_BibleVerse @BibleId, 344024015, N'I have a hope in God (a hope that these men themselves accept too) that there is going to be a resurrection of both the righteous and the unrighteous.'
EXEC add_BibleVerse @BibleId, 344024016, N'This is the reason I do my best to always have a clear conscience toward God and toward people.'
EXEC add_BibleVerse @BibleId, 344024017, N'After several years I came to bring to my people gifts for the poor and to present offerings,'
EXEC add_BibleVerse @BibleId, 344024018, N'which I was doing when they found me in the temple, ritually purified, without a crowd or a disturbance.'
EXEC add_BibleVerse @BibleId, 344024019, N'But there are some Jews from the province of Asia who should be here before you and bring charges, if they have anything against me.'
EXEC add_BibleVerse @BibleId, 344024020, N'Or these men here should tell what crime they found me guilty of when I stood before the council,'
EXEC add_BibleVerse @BibleId, 344024021, N'other than this one thing I shouted out while I stood before them: ‘I am on trial before you today concerning the resurrection of the dead.’”'
EXEC add_BibleVerse @BibleId, 344024022, N'Then Felix, who understood the facts concerning the Way more accurately, adjourned their hearing, saying, “When Lysias the commanding officer comes down, I will decide your case.”'
EXEC add_BibleVerse @BibleId, 344024023, N'He ordered the centurion to guard Paul, but to let him have some freedom, and not to prevent any of his friends from meeting his needs.'
EXEC add_BibleVerse @BibleId, 344024024, N'Some days later, when Felix arrived with his wife Drusilla, who was Jewish, he sent for Paul and heard him speak about faith in Christ Jesus.'
EXEC add_BibleVerse @BibleId, 344024025, N'While Paul was discussing righteousness, self-control, and the coming judgment, Felix became frightened and said, “Go away for now, and when I have an opportunity, I will send for you.”'
EXEC add_BibleVerse @BibleId, 344024026, N'At the same time he was also hoping that Paul would give him money, and for this reason he sent for Paul as often as possible and talked with him.'
EXEC add_BibleVerse @BibleId, 344024027, N'After two years had passed, Porcius Festus succeeded Felix, and because he wanted to do the Jews a favor, Felix left Paul in prison.'
EXEC add_BibleVerse @BibleId, 344025001, N'Now three days after Festus arrived in the province, he went up to Jerusalem from Caesarea.'
EXEC add_BibleVerse @BibleId, 344025002, N'So the chief priests and the most prominent men of the Jews brought formal charges against Paul to him.'
EXEC add_BibleVerse @BibleId, 344025003, N'Requesting him to do them a favor against Paul, they urged Festus to summon him to Jerusalem, planning an ambush to kill him along the way.'
EXEC add_BibleVerse @BibleId, 344025004, N'Then Festus replied that Paul was being kept at Caesarea, and he himself intended to go there shortly.'
EXEC add_BibleVerse @BibleId, 344025005, N'“So,” he said, “let your leaders go down there with me, and if this man has done anything wrong, they may bring charges against him.”'
EXEC add_BibleVerse @BibleId, 344025006, N'After Festus had stayed not more than eight or ten days among them, he went down to Caesarea, and the next day he sat on the judgment seat and ordered Paul to be brought.'
EXEC add_BibleVerse @BibleId, 344025007, N'When he arrived, the Jews who had come down from Jerusalem stood around him, bringing many serious charges that they were not able to prove.'
EXEC add_BibleVerse @BibleId, 344025008, N'Paul said in his defense, “I have committed no offense against the Jewish law or against the temple or against Caesar.”'
EXEC add_BibleVerse @BibleId, 344025009, N'But Festus, wanting to do the Jews a favor, asked Paul, “Are you willing to go up to Jerusalem and be tried before me there on these charges?”'
EXEC add_BibleVerse @BibleId, 344025010, N'Paul replied, “I am standing before Caesar’s judgment seat, where I should be tried. I have done nothing wrong to the Jews, as you also know very well.'
EXEC add_BibleVerse @BibleId, 344025011, N'If then I am in the wrong and have done anything that deserves death, I am not trying to escape dying, but if not one of their charges against me is true, no one can hand me over to them. I appeal to Caesar!”'
EXEC add_BibleVerse @BibleId, 344025012, N'Then, after conferring with his council, Festus replied, “You have appealed to Caesar; to Caesar you will go!”'
EXEC add_BibleVerse @BibleId, 344025013, N'After several days had passed, King Agrippa and Bernice arrived at Caesarea to pay their respects to Festus.'
EXEC add_BibleVerse @BibleId, 344025014, N'While they were staying there many days, Festus explained Paul’s case to the king to get his opinion, saying, “There is a man left here as a prisoner by Felix.'
EXEC add_BibleVerse @BibleId, 344025015, N'When I was in Jerusalem, the chief priests and the elders of the Jews informed me about him, asking for a sentence of condemnation against him.'
EXEC add_BibleVerse @BibleId, 344025016, N'I answered them that it was not the custom of the Romans to hand over anyone before the accused had met his accusers face to face and had been given an opportunity to make a defense against the accusation.'
EXEC add_BibleVerse @BibleId, 344025017, N'So after they came back here with me, I did not postpone the case, but the next day I sat on the judgment seat and ordered the man to be brought.'
EXEC add_BibleVerse @BibleId, 344025018, N'When his accusers stood up, they did not charge him with any of the evil deeds I had suspected.'
EXEC add_BibleVerse @BibleId, 344025019, N'Rather they had several points of disagreement with him about their own religion and about a man named Jesus who was dead, whom Paul claimed to be alive.'
EXEC add_BibleVerse @BibleId, 344025020, N'Because I was at a loss how I could investigate these matters, I asked if he were willing to go to Jerusalem and be tried there on these charges.'
EXEC add_BibleVerse @BibleId, 344025021, N'But when Paul appealed to be kept in custody for the decision of His Majesty the Emperor, I ordered him to be kept under guard until I could send him to Caesar.”'
EXEC add_BibleVerse @BibleId, 344025022, N'Agrippa said to Festus, “I would also like to hear the man myself.” “Tomorrow,” he replied, “you will hear him.”'
EXEC add_BibleVerse @BibleId, 344025023, N'So the next day Agrippa and Bernice came with great pomp and entered the audience hall, along with the senior military officers and the prominent men of the city. When Festus gave the order, Paul was brought in.'
EXEC add_BibleVerse @BibleId, 344025024, N'Then Festus said, “King Agrippa, and all you who are present here with us, you see this man about whom the entire Jewish populace petitioned me both in Jerusalem and here, shouting loudly that he ought not to live any longer.'
EXEC add_BibleVerse @BibleId, 344025025, N'But I found that he had done nothing that deserved death, and when he appealed to His Majesty the Emperor, I decided to send him.'
EXEC add_BibleVerse @BibleId, 344025026, N'But I have nothing definite to write to my lord about him. Therefore I have brought him before you all, and especially before you, King Agrippa, so that after this preliminary hearing I may have something to write.'
EXEC add_BibleVerse @BibleId, 344025027, N'For it seems unreasonable to me to send a prisoner without clearly indicating the charges against him.”'
EXEC add_BibleVerse @BibleId, 344026001, N'So Agrippa said to Paul, “You have permission to speak for yourself.” Then Paul held out his hand and began his defense:'
EXEC add_BibleVerse @BibleId, 344026002, N'“Regarding all the things I have been accused of by the Jews, King Agrippa, I consider myself fortunate that I am about to make my defense before you today,'
EXEC add_BibleVerse @BibleId, 344026003, N'because you are especially familiar with all the customs and controversial issues of the Jews. Therefore I ask you to listen to me patiently.'
EXEC add_BibleVerse @BibleId, 344026004, N'Now all the Jews know the way I lived from my youth, spending my life from the beginning among my own people and in Jerusalem.'
EXEC add_BibleVerse @BibleId, 344026005, N'They know, because they have known me from time past, if they are willing to testify, that according to the strictest party of our religion, I lived as a Pharisee.'
EXEC add_BibleVerse @BibleId, 344026006, N'And now I stand here on trial because of my hope in the promise made by God to our ancestors,'
EXEC add_BibleVerse @BibleId, 344026007, N'a promise that our twelve tribes hope to attain as they earnestly serve God night and day. Concerning this hope the Jews are accusing me, Your Majesty!'
EXEC add_BibleVerse @BibleId, 344026008, N'Why do you people think it is unbelievable that God raises the dead?'
EXEC add_BibleVerse @BibleId, 344026009, N'Of course, I myself was convinced that it was necessary to do many things hostile to the name of Jesus the Nazarene.'
EXEC add_BibleVerse @BibleId, 344026010, N'And that is what I did in Jerusalem: Not only did I lock up many of the saints in prisons by the authority I received from the chief priests, but I also cast my vote against them when they were sentenced to death.'
EXEC add_BibleVerse @BibleId, 344026011, N'I punished them often in all the synagogues and tried to force them to blaspheme. Because I was so furiously enraged at them, I went to persecute them even in foreign cities.'
EXEC add_BibleVerse @BibleId, 344026012, N'“While doing this very thing, as I was going to Damascus with authority and complete power from the chief priests,'
EXEC add_BibleVerse @BibleId, 344026013, N'about noon along the road, Your Majesty, I saw a light from heaven, brighter than the sun, shining everywhere around me and those traveling with me.'
EXEC add_BibleVerse @BibleId, 344026014, N'When we had all fallen to the ground, I heard a voice saying to me in Aramaic, ‘Saul, Saul, why are you persecuting me? You are hurting yourself by kicking against the goads.’'
EXEC add_BibleVerse @BibleId, 344026015, N'So I said, ‘Who are you, Lord?’ And the Lord replied, ‘I am Jesus whom you are persecuting.'
EXEC add_BibleVerse @BibleId, 344026016, N'But get up and stand on your feet, for I have appeared to you for this reason, to designate you in advance as a servant and witness to the things you have seen and to the things in which I will appear to you.'
EXEC add_BibleVerse @BibleId, 344026017, N'I will rescue you from your own people and from the Gentiles, to whom I am sending you'
EXEC add_BibleVerse @BibleId, 344026018, N'to open their eyes so that they turn from darkness to light and from the power of Satan to God, so that they may receive forgiveness of sins and a share among those who are sanctified by faith in me.’'
EXEC add_BibleVerse @BibleId, 344026019, N'“Therefore, King Agrippa, I was not disobedient to the heavenly vision,'
EXEC add_BibleVerse @BibleId, 344026020, N'but I declared to those in Damascus first, and then to those in Jerusalem and in all Judea, and to the Gentiles, that they should repent and turn to God, performing deeds consistent with repentance.'
EXEC add_BibleVerse @BibleId, 344026021, N'For this reason the Jews seized me in the temple courts and were trying to kill me.'
EXEC add_BibleVerse @BibleId, 344026022, N'I have experienced help from God to this day, and so I stand testifying to both small and great, saying nothing except what the prophets and Moses said was going to happen:'
EXEC add_BibleVerse @BibleId, 344026023, N'that the Christ was to suffer and be the first to rise from the dead, to proclaim light both to our people and to the Gentiles.”'
EXEC add_BibleVerse @BibleId, 344026024, N'As Paul was saying these things in his defense, Festus exclaimed loudly, “You have lost your mind, Paul! Your great learning is driving you insane!”'
EXEC add_BibleVerse @BibleId, 344026025, N'But Paul replied, “I have not lost my mind, most excellent Festus, but am speaking true and rational words.'
EXEC add_BibleVerse @BibleId, 344026026, N'For the king knows about these things, and I am speaking freely to him, because I cannot believe that any of these things has escaped his notice, for this was not done in a corner.'
EXEC add_BibleVerse @BibleId, 344026027, N'Do you believe the prophets, King Agrippa? I know that you believe.”'
EXEC add_BibleVerse @BibleId, 344026028, N'Agrippa said to Paul, “In such a short time are you persuading me to become a Christian?”'
EXEC add_BibleVerse @BibleId, 344026029, N'Paul replied, “I pray to God that whether in a short or a long time not only you but also all those who are listening to me today could become such as I am, except for these chains.”'
EXEC add_BibleVerse @BibleId, 344026030, N'So the king got up, and with him the governor and Bernice and those sitting with them,'
EXEC add_BibleVerse @BibleId, 344026031, N'and as they were leaving they said to one another, “This man is not doing anything deserving death or imprisonment.”'
EXEC add_BibleVerse @BibleId, 344026032, N'Agrippa said to Festus, “This man could have been released if he had not appealed to Caesar.”'
EXEC add_BibleVerse @BibleId, 344027001, N'When it was decided we would sail to Italy, they handed over Paul and some other prisoners to a centurion of the Augustan Cohort named Julius.'
EXEC add_BibleVerse @BibleId, 344027002, N'We went on board a ship from Adramyttium that was about to sail to various ports along the coast of the province of Asia and put out to sea, accompanied by Aristarchus, a Macedonian from Thessalonica.'
EXEC add_BibleVerse @BibleId, 344027003, N'The next day we put in at Sidon, and Julius, treating Paul kindly, allowed him to go to his friends so they could provide him with what he needed.'
EXEC add_BibleVerse @BibleId, 344027004, N'From there we put out to sea and sailed under the lee of Cyprus because the winds were against us.'
EXEC add_BibleVerse @BibleId, 344027005, N'After we had sailed across the open sea off Cilicia and Pamphylia, we put in at Myra in Lycia.'
EXEC add_BibleVerse @BibleId, 344027006, N'There the centurion found a ship from Alexandria sailing for Italy, and he put us aboard it.'
EXEC add_BibleVerse @BibleId, 344027007, N'We sailed slowly for many days and arrived with difficulty off Cnidus. Because the wind prevented us from going any farther, we sailed under the lee of Crete off Salmone.'
EXEC add_BibleVerse @BibleId, 344027008, N'With difficulty we sailed along the coast of Crete and came to a place called Fair Havens that was near the town of Lasea.'
EXEC add_BibleVerse @BibleId, 344027009, N'Since considerable time had passed and the voyage was now dangerous because the fast was already over, Paul advised them,'
EXEC add_BibleVerse @BibleId, 344027010, N'“Men, I can see the voyage is going to end in disaster and great loss not only of the cargo and the ship, but also of our lives.”'
EXEC add_BibleVerse @BibleId, 344027011, N'But the centurion was more convinced by the captain and the ship’s owner than by what Paul said.'
EXEC add_BibleVerse @BibleId, 344027012, N'Because the harbor was not suitable to spend the winter in, the majority decided to put out to sea from there. They hoped that somehow they could reach Phoenix, a harbor of Crete facing southwest and northwest, and spend the winter there.'
EXEC add_BibleVerse @BibleId, 344027013, N'When a gentle south wind sprang up, they thought they could carry out their purpose, so they weighed anchor and sailed close along the coast of Crete.'
EXEC add_BibleVerse @BibleId, 344027014, N'Not long after this, a hurricane-force wind called the northeaster blew down from the island.'
EXEC add_BibleVerse @BibleId, 344027015, N'When the ship was caught in it and could not head into the wind, we gave way to it and were driven along.'
EXEC add_BibleVerse @BibleId, 344027016, N'As we ran under the lee of a small island called Cauda, we were able with difficulty to get the ship’s boat under control.'
EXEC add_BibleVerse @BibleId, 344027017, N'After the crew had hoisted it aboard, they used supports to undergird the ship. Fearing they would run aground on the Syrtis, they lowered the sea anchor, thus letting themselves be driven along.'
EXEC add_BibleVerse @BibleId, 344027018, N'The next day, because we were violently battered by the storm, they began throwing the cargo overboard,'
EXEC add_BibleVerse @BibleId, 344027019, N'and on the third day they threw the ship’s gear overboard with their own hands.'
EXEC add_BibleVerse @BibleId, 344027020, N'When neither sun nor stars appeared for many days and a violent storm continued to batter us, we finally abandoned all hope of being saved.'
EXEC add_BibleVerse @BibleId, 344027021, N'Since many of them had no desire to eat, Paul stood up among them and said, “Men, you should have listened to me and not put out to sea from Crete, thus avoiding this damage and loss.'
EXEC add_BibleVerse @BibleId, 344027022, N'And now I advise you to keep up your courage, for there will be no loss of life among you, but only the ship will be lost.'
EXEC add_BibleVerse @BibleId, 344027023, N'For last night an angel of the God to whom I belong and whom I serve came to me'
EXEC add_BibleVerse @BibleId, 344027024, N'and said, ‘Do not be afraid, Paul! You must stand before Caesar, and God has graciously granted you the safety of all who are sailing with you.’'
EXEC add_BibleVerse @BibleId, 344027025, N'Therefore keep up your courage, men, for I have faith in God that it will be just as I have been told.'
EXEC add_BibleVerse @BibleId, 344027026, N'But we must run aground on some island.”'
EXEC add_BibleVerse @BibleId, 344027027, N'When the fourteenth night had come, while we were being driven across the Adriatic Sea, about midnight the sailors suspected they were approaching some land.'
EXEC add_BibleVerse @BibleId, 344027028, N'They took soundings and found the water was twenty fathoms deep; when they had sailed a little farther they took soundings again and found it was fifteen fathoms deep.'
EXEC add_BibleVerse @BibleId, 344027029, N'Because they were afraid that we would run aground on the rocky coast, they threw out four anchors from the stern and wished for day to appear.'
EXEC add_BibleVerse @BibleId, 344027030, N'Then when the sailors tried to escape from the ship and were lowering the ship’s boat into the sea, pretending that they were going to put out anchors from the bow,'
EXEC add_BibleVerse @BibleId, 344027031, N'Paul said to the centurion and the soldiers, “Unless these men stay with the ship, you cannot be saved.”'
EXEC add_BibleVerse @BibleId, 344027032, N'Then the soldiers cut the ropes of the ship’s boat and let it drift away.'
EXEC add_BibleVerse @BibleId, 344027033, N'As day was about to dawn, Paul urged them all to take some food, saying, “Today is the fourteenth day you have been in suspense and have gone without food; you have eaten nothing.'
EXEC add_BibleVerse @BibleId, 344027034, N'Therefore I urge you to take some food, for this is important for your survival. For not one of you will lose a hair from his head.”'
EXEC add_BibleVerse @BibleId, 344027035, N'After he said this, Paul took bread and gave thanks to God in front of them all, broke it, and began to eat.'
EXEC add_BibleVerse @BibleId, 344027036, N'So all of them were encouraged and took food themselves.'
EXEC add_BibleVerse @BibleId, 344027037, N'(We were in all two hundred seventy-six persons on the ship.)'
EXEC add_BibleVerse @BibleId, 344027038, N'When they had eaten enough to be satisfied, they lightened the ship by throwing the wheat into the sea.'
EXEC add_BibleVerse @BibleId, 344027039, N'When day came, they did not recognize the land, but they noticed a bay with a beach, where they decided to run the ship aground if they could.'
EXEC add_BibleVerse @BibleId, 344027040, N'So they slipped the anchors and left them in the sea, at the same time loosening the linkage that bound the steering oars together. Then they hoisted the foresail to the wind and steered toward the beach.'
EXEC add_BibleVerse @BibleId, 344027041, N'But they encountered a patch of crosscurrents and ran the ship aground; the bow stuck fast and could not be moved, but the stern was being broken up by the force of the waves.'
EXEC add_BibleVerse @BibleId, 344027042, N'Now the soldiers’ plan was to kill the prisoners so that none of them would escape by swimming away.'
EXEC add_BibleVerse @BibleId, 344027043, N'But the centurion, wanting to save Paul’s life, prevented them from carrying out their plan. He ordered those who could swim to jump overboard first and get to land,'
EXEC add_BibleVerse @BibleId, 344027044, N'and the rest were to follow, some on planks and some on pieces of the ship. And in this way all were brought safely to land.'
EXEC add_BibleVerse @BibleId, 344028001, N'After we had safely reached shore, we learned that the island was called Malta.'
EXEC add_BibleVerse @BibleId, 344028002, N'The local inhabitants showed us extraordinary kindness, for they built a fire and welcomed us all because it had started to rain and was cold.'
EXEC add_BibleVerse @BibleId, 344028003, N'When Paul had gathered a bundle of brushwood and was putting it on the fire, a viper came out because of the heat and fastened itself on his hand.'
EXEC add_BibleVerse @BibleId, 344028004, N'When the local people saw the creature hanging from Paul’s hand, they said to one another, “No doubt this man is a murderer! Although he has escaped from the sea, Justice herself has not allowed him to live!”'
EXEC add_BibleVerse @BibleId, 344028005, N'However, Paul shook the creature off into the fire and suffered no harm.'
EXEC add_BibleVerse @BibleId, 344028006, N'But they were expecting that he was going to swell up or suddenly drop dead. So after they had waited a long time and had seen nothing unusual happen to him, they changed their minds and said he was a god.'
EXEC add_BibleVerse @BibleId, 344028007, N'Now in the region around that place were fields belonging to the chief official of the island, named Publius, who welcomed us and entertained us hospitably as guests for three days.'
EXEC add_BibleVerse @BibleId, 344028008, N'The father of Publius lay sick in bed, suffering from fever and dysentery. Paul went in to see him and after praying, placed his hands on him and healed him.'
EXEC add_BibleVerse @BibleId, 344028009, N'After this had happened, many of the people on the island who were sick also came and were healed.'
EXEC add_BibleVerse @BibleId, 344028010, N'They also bestowed many honors, and when we were preparing to sail, they gave us all the supplies we needed.'
EXEC add_BibleVerse @BibleId, 344028011, N'After three months we put out to sea in an Alexandrian ship that had wintered at the island and had the “Heavenly Twins” as its figurehead.'
EXEC add_BibleVerse @BibleId, 344028012, N'We put in at Syracuse and stayed there three days.'
EXEC add_BibleVerse @BibleId, 344028013, N'From there we cast off and arrived at Rhegium, and after one day a south wind sprang up and on the second day we came to Puteoli.'
EXEC add_BibleVerse @BibleId, 344028014, N'There we found some brothers and were invited to stay with them seven days. And in this way we came to Rome.'
EXEC add_BibleVerse @BibleId, 344028015, N'The brothers from there, when they heard about us, came as far as the Forum of Appius and Three Taverns to meet us. When he saw them, Paul thanked God and took courage.'
EXEC add_BibleVerse @BibleId, 344028016, N'When we entered Rome, Paul was allowed to live by himself, with the soldier who was guarding him.'
EXEC add_BibleVerse @BibleId, 344028017, N'After three days Paul called the local Jewish leaders together. When they had assembled, he said to them, “Brothers, although I had done nothing against our people or the customs of our ancestors, from Jerusalem I was handed over as a prisoner to the Romans.'
EXEC add_BibleVerse @BibleId, 344028018, N'When they had heard my case, they wanted to release me, because there was no basis for a death sentence against me.'
EXEC add_BibleVerse @BibleId, 344028019, N'But when the Jews objected, I was forced to appeal to Caesar – not that I had some charge to bring against my own people.'
EXEC add_BibleVerse @BibleId, 344028020, N'So for this reason I have asked to see you and speak with you, for I am bound with this chain because of the hope of Israel.”'
EXEC add_BibleVerse @BibleId, 344028021, N'They replied, “We have received no letters from Judea about you, nor have any of the brothers come from there and reported or said anything bad about you.'
EXEC add_BibleVerse @BibleId, 344028022, N'But we would like to hear from you what you think, for regarding this sect we know that people everywhere speak against it.”'
EXEC add_BibleVerse @BibleId, 344028023, N'They set a day to meet with him, and they came to him where he was staying in even greater numbers. From morning until evening he explained things to them, testifying about the kingdom of God and trying to convince them about Jesus from both the law of Moses and the prophets.'
EXEC add_BibleVerse @BibleId, 344028024, N'Some were convinced by what he said, but others refused to believe.'
EXEC add_BibleVerse @BibleId, 344028025, N'So they began to leave, unable to agree among themselves, after Paul made one last statement: “The Holy Spirit spoke rightly to your ancestors through the prophet Isaiah'
EXEC add_BibleVerse @BibleId, 344028026, N'when he said, ‘ Go to this people and say, “ You will keep on hearing, but will never understand, and you will keep on looking, but will never perceive.'
EXEC add_BibleVerse @BibleId, 344028027, N'For the heart of this people has become dull, and their ears are hard of hearing, and they have closed their eyes, so that they would not see with their eyes and hear with their ears and understand with their heart and turn, and I would heal them.”’'
EXEC add_BibleVerse @BibleId, 344028028, N'“Therefore be advised that this salvation from God has been sent to the Gentiles; they will listen!”'
EXEC add_BibleVerse @BibleId, 344028030, N' Paul lived there two whole years in his own rented quarters and welcomed all who came to him,'
EXEC add_BibleVerse @BibleId, 344028031, N'proclaiming the kingdom of God and teaching about the Lord Jesus Christ with complete boldness and without restriction.'
EXEC add_BibleVerse @BibleId, 345001001, N'From Paul, a slave of Christ Jesus, called to be an apostle, set apart for the gospel of God.'
EXEC add_BibleVerse @BibleId, 345001002, N'This gospel he promised beforehand through his prophets in the holy scriptures,'
EXEC add_BibleVerse @BibleId, 345001003, N'concerning his Son who was a descendant of David with reference to the flesh,'
EXEC add_BibleVerse @BibleId, 345001004, N'who was appointed the Son-of-God-in-power according to the Holy Spirit by the resurrection from the dead, Jesus Christ our Lord.'
EXEC add_BibleVerse @BibleId, 345001005, N'Through him we have received grace and our apostleship to bring about the obedience of faith among all the Gentiles on behalf of his name.'
EXEC add_BibleVerse @BibleId, 345001006, N'You also are among them, called to belong to Jesus Christ.'
EXEC add_BibleVerse @BibleId, 345001007, N'To all those loved by God in Rome, called to be saints: Grace and peace to you from God our Father and the Lord Jesus Christ!'
EXEC add_BibleVerse @BibleId, 345001008, N'First of all, I thank my God through Jesus Christ for all of you, because your faith is proclaimed throughout the whole world.'
EXEC add_BibleVerse @BibleId, 345001009, N'For God, whom I serve in my spirit by preaching the gospel of his Son, is my witness that I continually remember you'
EXEC add_BibleVerse @BibleId, 345001010, N'and I always ask in my prayers, if perhaps now at last I may succeed in visiting you according to the will of God.'
EXEC add_BibleVerse @BibleId, 345001011, N'For I long to see you, so that I may impart to you some spiritual gift to strengthen you,'
EXEC add_BibleVerse @BibleId, 345001012, N'that is, that we may be mutually comforted by one another’s faith, both yours and mine.'
EXEC add_BibleVerse @BibleId, 345001013, N'I do not want you to be unaware, brothers and sisters, that I often intended to come to you (and was prevented until now), so that I may have some fruit even among you, just as I already have among the rest of the Gentiles.'
EXEC add_BibleVerse @BibleId, 345001014, N'I am a debtor both to the Greeks and to the barbarians, both to the wise and to the foolish.'
EXEC add_BibleVerse @BibleId, 345001015, N'Thus I am eager also to preach the gospel to you who are in Rome.'
EXEC add_BibleVerse @BibleId, 345001016, N'For I am not ashamed of the gospel, for it is God’s power for salvation to everyone who believes, to the Jew first and also to the Greek.'
EXEC add_BibleVerse @BibleId, 345001017, N'For the righteousness of God is revealed in the gospel from faith to faith, just as it is written, “ The righteous by faith will live.”'
EXEC add_BibleVerse @BibleId, 345001018, N'For the wrath of God is revealed from heaven against all ungodliness and unrighteousness of people who suppress the truth by their unrighteousness,'
EXEC add_BibleVerse @BibleId, 345001019, N'because what can be known about God is plain to them, because God has made it plain to them.'
EXEC add_BibleVerse @BibleId, 345001020, N'For since the creation of the world his invisible attributes – his eternal power and divine nature – have been clearly seen, because they are understood through what has been made. So people are without excuse.'
EXEC add_BibleVerse @BibleId, 345001021, N'For although they knew God, they did not glorify him as God or give him thanks, but they became futile in their thoughts and their senseless hearts were darkened.'
EXEC add_BibleVerse @BibleId, 345001022, N'Although they claimed to be wise, they became fools'
EXEC add_BibleVerse @BibleId, 345001023, N'and exchanged the glory of the immortal God for an image resembling mortal human beings or birds or four-footed animals or reptiles.'
EXEC add_BibleVerse @BibleId, 345001024, N'Therefore God gave them over in the desires of their hearts to impurity, to dishonor their bodies among themselves.'
EXEC add_BibleVerse @BibleId, 345001025, N'They exchanged the truth of God for a lie and worshiped and served the creation rather than the Creator, who is blessed forever! Amen.'
EXEC add_BibleVerse @BibleId, 345001026, N'For this reason God gave them over to dishonorable passions. For their women exchanged the natural sexual relations for unnatural ones,'
EXEC add_BibleVerse @BibleId, 345001027, N'and likewise the men also abandoned natural relations with women and were inflamed in their passions for one another. Men committed shameless acts with men and received in themselves the due penalty for their error.'
EXEC add_BibleVerse @BibleId, 345001028, N'And just as they did not see fit to acknowledge God, God gave them over to a depraved mind, to do what should not be done.'
EXEC add_BibleVerse @BibleId, 345001029, N'They are filled with every kind of unrighteousness, wickedness, covetousness, malice. They are rife with envy, murder, strife, deceit, hostility. They are gossips,'
EXEC add_BibleVerse @BibleId, 345001030, N'slanderers, haters of God, insolent, arrogant, boastful, contrivers of all sorts of evil, disobedient to parents,'
EXEC add_BibleVerse @BibleId, 345001031, N'senseless, covenant-breakers, heartless, ruthless.'
EXEC add_BibleVerse @BibleId, 345001032, N'Although they fully know God’s righteous decree that those who practice such things deserve to die, they not only do them but also approve of those who practice them.'
EXEC add_BibleVerse @BibleId, 345002001, N'Therefore you are without excuse, whoever you are, when you judge someone else. For on whatever grounds you judge another, you condemn yourself, because you who judge practice the same things.'
EXEC add_BibleVerse @BibleId, 345002002, N'Now we know that God’s judgment is in accordance with truth against those who practice such things.'
EXEC add_BibleVerse @BibleId, 345002003, N'And do you think, whoever you are, when you judge those who practice such things and yet do them yourself, that you will escape God’s judgment?'
EXEC add_BibleVerse @BibleId, 345002004, N'Or do you have contempt for the wealth of his kindness, forbearance, and patience, and yet do not know that God’s kindness leads you to repentance?'
EXEC add_BibleVerse @BibleId, 345002005, N'But because of your stubbornness and your unrepentant heart, you are storing up wrath for yourselves in the day of wrath, when God’s righteous judgment is revealed!'
EXEC add_BibleVerse @BibleId, 345002006, N'He will reward each one according to his works:'
EXEC add_BibleVerse @BibleId, 345002007, N'eternal life to those who by perseverance in good works seek glory and honor and immortality,'
EXEC add_BibleVerse @BibleId, 345002008, N'but wrath and anger to those who live in selfish ambition and do not obey the truth but follow unrighteousness.'
EXEC add_BibleVerse @BibleId, 345002009, N'There will be affliction and distress on everyone who does evil, on the Jew first and also the Greek,'
EXEC add_BibleVerse @BibleId, 345002010, N'but glory and honor and peace for everyone who does good, for the Jew first and also the Greek.'
EXEC add_BibleVerse @BibleId, 345002011, N'For there is no partiality with God.'
EXEC add_BibleVerse @BibleId, 345002012, N'For all who have sinned apart from the law will also perish apart from the law, and all who have sinned under the law will be judged by the law.'
EXEC add_BibleVerse @BibleId, 345002013, N'For it is not those who hear the law who are righteous before God, but those who do the law will be declared righteous.'
EXEC add_BibleVerse @BibleId, 345002014, N'For whenever the Gentiles, who do not have the law, do by nature the things required by the law, these who do not have the law are a law to themselves.'
EXEC add_BibleVerse @BibleId, 345002015, N'They show that the work of the law is written in their hearts, as their conscience bears witness and their conflicting thoughts accuse or else defend them,'
EXEC add_BibleVerse @BibleId, 345002016, N'on the day when God will judge the secrets of human hearts, according to my gospel through Christ Jesus.'
EXEC add_BibleVerse @BibleId, 345002017, N'But if you call yourself a Jew and rely on the law and boast of your relationship to God'
EXEC add_BibleVerse @BibleId, 345002018, N'and know his will and approve the superior things because you receive instruction from the law,'
EXEC add_BibleVerse @BibleId, 345002019, N'and if you are convinced that you yourself are a guide to the blind, a light to those who are in darkness,'
EXEC add_BibleVerse @BibleId, 345002020, N'an educator of the senseless, a teacher of little children, because you have in the law the essential features of knowledge and of the truth –'
EXEC add_BibleVerse @BibleId, 345002021, N'therefore you who teach someone else, do you not teach yourself? You who preach against stealing, do you steal?'
EXEC add_BibleVerse @BibleId, 345002022, N'You who tell others not to commit adultery, do you commit adultery? You who abhor idols, do you rob temples?'
EXEC add_BibleVerse @BibleId, 345002023, N'You who boast in the law dishonor God by transgressing the law!'
EXEC add_BibleVerse @BibleId, 345002024, N'For just as it is written, “ the name of God is being blasphemed among the Gentiles because of you.”'
EXEC add_BibleVerse @BibleId, 345002025, N'For circumcision has its value if you practice the law, but if you break the law, your circumcision has become uncircumcision.'
EXEC add_BibleVerse @BibleId, 345002026, N'Therefore if the uncircumcised man obeys the righteous requirements of the law, will not his uncircumcision be regarded as circumcision?'
EXEC add_BibleVerse @BibleId, 345002027, N'And will not the physically uncircumcised man who keeps the law judge you who, despite the written code and circumcision, transgress the law?'
EXEC add_BibleVerse @BibleId, 345002028, N'For a person is not a Jew who is one outwardly, nor is circumcision something that is outward in the flesh,'
EXEC add_BibleVerse @BibleId, 345002029, N'but someone is a Jew who is one inwardly, and circumcision is of the heart by the Spirit and not by the written code. This person’s praise is not from people but from God.'
EXEC add_BibleVerse @BibleId, 345003001, N'Therefore what advantage does the Jew have, or what is the value of circumcision?'
EXEC add_BibleVerse @BibleId, 345003002, N'Actually, there are many advantages. First of all, the Jews were entrusted with the oracles of God.'
EXEC add_BibleVerse @BibleId, 345003003, N'What then? If some did not believe, does their unbelief nullify the faithfulness of God?'
EXEC add_BibleVerse @BibleId, 345003004, N'Absolutely not! Let God be proven true, and every human being shown up as a liar, just as it is written: “ so that you will be justified in your words and will prevail when you are judged.”'
EXEC add_BibleVerse @BibleId, 345003005, N'But if our unrighteousness demonstrates the righteousness of God, what shall we say? The God who inflicts wrath is not unrighteous, is he? (I am speaking in human terms.)'
EXEC add_BibleVerse @BibleId, 345003006, N'Absolutely not! For otherwise how could God judge the world?'
EXEC add_BibleVerse @BibleId, 345003007, N'For if by my lie the truth of God enhances his glory, why am I still actually being judged as a sinner?'
EXEC add_BibleVerse @BibleId, 345003008, N'And why not say, “Let us do evil so that good may come of it”? – as some who slander us allege that we say. (Their condemnation is deserved!)'
EXEC add_BibleVerse @BibleId, 345003009, N'What then? Are we better off? Certainly not, for we have already charged that Jews and Greeks alike are all under sin,'
EXEC add_BibleVerse @BibleId, 345003010, N'just as it is written: “ There is no one righteous, not even one,'
EXEC add_BibleVerse @BibleId, 345003011, N'there is no one who understands, there is no one who seeks God.'
EXEC add_BibleVerse @BibleId, 345003012, N'All have turned away, together they have become worthless; there is no one who shows kindness, not even one.”'
EXEC add_BibleVerse @BibleId, 345003013, N'“ Their throats are open graves, they deceive with their tongues, the poison of asps is under their lips.”'
EXEC add_BibleVerse @BibleId, 345003014, N'“ Their mouths are full of cursing and bitterness.”'
EXEC add_BibleVerse @BibleId, 345003015, N'“ Their feet are swift to shed blood,'
EXEC add_BibleVerse @BibleId, 345003016, N'ruin and misery are in their paths,'
EXEC add_BibleVerse @BibleId, 345003017, N'and the way of peace they have not known.”'
EXEC add_BibleVerse @BibleId, 345003018, N'“ There is no fear of God before their eyes.”'
EXEC add_BibleVerse @BibleId, 345003019, N'Now we know that whatever the law says, it says to those who are under the law, so that every mouth may be silenced and the whole world may be held accountable to God.'
EXEC add_BibleVerse @BibleId, 345003020, N'For no one is declared righteous before him by the works of the law, for through the law comes the knowledge of sin.'
EXEC add_BibleVerse @BibleId, 345003021, N'But now apart from the law the righteousness of God (which is attested by the law and the prophets) has been disclosed –'
EXEC add_BibleVerse @BibleId, 345003022, N'namely, the righteousness of God through the faithfulness of Jesus Christ for all who believe. For there is no distinction,'
EXEC add_BibleVerse @BibleId, 345003023, N'for all have sinned and fall short of the glory of God.'
EXEC add_BibleVerse @BibleId, 345003024, N'But they are justified freely by his grace through the redemption that is in Christ Jesus.'
EXEC add_BibleVerse @BibleId, 345003025, N'God publicly displayed him at his death as the mercy seat accessible through faith. This was to demonstrate his righteousness, because God in his forbearance had passed over the sins previously committed.'
EXEC add_BibleVerse @BibleId, 345003026, N'This was also to demonstrate his righteousness in the present time, so that he would be just and the justifier of the one who lives because of Jesus’ faithfulness.'
EXEC add_BibleVerse @BibleId, 345003027, N'Where, then, is boasting? It is excluded! By what principle? Of works? No, but by the principle of faith!'
EXEC add_BibleVerse @BibleId, 345003028, N'For we consider that a person is declared righteous by faith apart from the works of the law.'
EXEC add_BibleVerse @BibleId, 345003029, N'Or is God the God of the Jews only? Is he not the God of the Gentiles too? Yes, of the Gentiles too!'
EXEC add_BibleVerse @BibleId, 345003030, N'Since God is one, he will justify the circumcised by faith and the uncircumcised through faith.'
EXEC add_BibleVerse @BibleId, 345003031, N'Do we then nullify the law through faith? Absolutely not! Instead we uphold the law.'
EXEC add_BibleVerse @BibleId, 345004001, N'What then shall we say that Abraham, our ancestor according to the flesh, has discovered regarding this matter?'
EXEC add_BibleVerse @BibleId, 345004002, N'For if Abraham was declared righteous by the works of the law, he has something to boast about – but not before God.'
EXEC add_BibleVerse @BibleId, 345004003, N'For what does the scripture say? “ Abraham believed God, and it was credited to him as righteousness*.”'
EXEC add_BibleVerse @BibleId, 345004004, N'Now to the one who works, his pay is not credited due to grace but due to obligation.'
EXEC add_BibleVerse @BibleId, 345004005, N'But to the one who does not work, but believes in the one who declares the ungodly righteous, his faith is credited as righteousness.'
EXEC add_BibleVerse @BibleId, 345004006, N'So even David himself speaks regarding the blessedness of the man to whom God credits righteousness apart from works:'
EXEC add_BibleVerse @BibleId, 345004007, N'“ Blessed are those whose lawless deeds are forgiven, and whose sins are covered;'
EXEC add_BibleVerse @BibleId, 345004008, N'blessed is the one against whom the Lord will never count sin*.”'
EXEC add_BibleVerse @BibleId, 345004009, N'Is this blessedness then for the circumcision or also for the uncircumcision? For we say, “ faith was credited to Abraham as righteousness.”'
EXEC add_BibleVerse @BibleId, 345004010, N'How then was it credited to him? Was he circumcised at the time, or not? No, he was not circumcised but uncircumcised!'
EXEC add_BibleVerse @BibleId, 345004011, N'And he received the sign of circumcision as a seal of the righteousness that he had by faith while he was still uncircumcised, so that he would become the father of all those who believe but have never been circumcised, that they too could have righteousness credited to them.'
EXEC add_BibleVerse @BibleId, 345004012, N'And he is also the father of the circumcised, who are not only circumcised, but who also walk in the footsteps of the faith that our father Abraham possessed when he was still uncircumcised.'
EXEC add_BibleVerse @BibleId, 345004013, N'For the promise to Abraham or to his descendants that he would inherit the world was not fulfilled through the law, but through the righteousness that comes by faith.'
EXEC add_BibleVerse @BibleId, 345004014, N'For if they become heirs by the law, faith is empty and the promise is nullified.'
EXEC add_BibleVerse @BibleId, 345004015, N'For the law brings wrath, because where there is no law there is no transgression either.'
EXEC add_BibleVerse @BibleId, 345004016, N'For this reason it is by faith so that it may be by grace, with the result that the promise may be certain to all the descendants – not only to those who are under the law, but also to those who have the faith of Abraham, who is the father of us all'
EXEC add_BibleVerse @BibleId, 345004017, N'(as it is written, “ I have made you the father of many nations”). He is our father in the presence of God whom he believed – the God who makes the dead alive and summons the things that do not yet exist as though they already do.'
EXEC add_BibleVerse @BibleId, 345004018, N'Against hope Abraham believed in hope with the result that he became the father of many nations according to the pronouncement, “ so will your descendants be.”'
EXEC add_BibleVerse @BibleId, 345004019, N'Without being weak in faith, he considered his own body as dead (because he was about one hundred years old) and the deadness of Sarah’s womb.'
EXEC add_BibleVerse @BibleId, 345004020, N'He did not waver in unbelief about the promise of God but was strengthened in faith, giving glory to God.'
EXEC add_BibleVerse @BibleId, 345004021, N'He was fully convinced that what God promised he was also able to do.'
EXEC add_BibleVerse @BibleId, 345004022, N'So indeed it was credited to Abraham as righteousness.'
EXEC add_BibleVerse @BibleId, 345004023, N'But the statement it was credited to him was not written only for Abraham’s sake,'
EXEC add_BibleVerse @BibleId, 345004024, N'but also for our sake, to whom it will be credited, those who believe in the one who raised Jesus our Lord from the dead.'
EXEC add_BibleVerse @BibleId, 345004025, N'He was given over because of our transgressions and was raised for the sake of our justification.'
EXEC add_BibleVerse @BibleId, 345005001, N'Therefore, since we have been declared righteous by faith, we have peace with God through our Lord Jesus Christ,'
EXEC add_BibleVerse @BibleId, 345005002, N'through whom we have also obtained access by faith into this grace in which we stand, and we rejoice in the hope of God’s glory.'
EXEC add_BibleVerse @BibleId, 345005003, N'Not only this, but we also rejoice in sufferings, knowing that suffering produces endurance,'
EXEC add_BibleVerse @BibleId, 345005004, N'and endurance, character, and character, hope.'
EXEC add_BibleVerse @BibleId, 345005005, N'And hope does not disappoint, because the love of God has been poured out in our hearts through the Holy Spirit who was given to us.'
EXEC add_BibleVerse @BibleId, 345005006, N'For while we were still helpless, at the right time Christ died for the ungodly.'
EXEC add_BibleVerse @BibleId, 345005007, N'(For rarely will anyone die for a righteous person, though for a good person perhaps someone might possibly dare to die.)'
EXEC add_BibleVerse @BibleId, 345005008, N'But God demonstrates his own love for us, in that while we were still sinners, Christ died for us.'
EXEC add_BibleVerse @BibleId, 345005009, N'Much more then, because we have now been declared righteous by his blood, we will be saved through him from God’s wrath.'
EXEC add_BibleVerse @BibleId, 345005010, N'For if while we were enemies we were reconciled to God through the death of his Son, how much more, since we have been reconciled, will we be saved by his life?'
EXEC add_BibleVerse @BibleId, 345005011, N'Not only this, but we also rejoice in God through our Lord Jesus Christ, through whom we have now received this reconciliation.'
EXEC add_BibleVerse @BibleId, 345005012, N'So then, just as sin entered the world through one man and death through sin, and so death spread to all people because all sinned –'
EXEC add_BibleVerse @BibleId, 345005013, N'for before the law was given, sin was in the world, but there is no accounting for sin when there is no law.'
EXEC add_BibleVerse @BibleId, 345005014, N'Yet death reigned from Adam until Moses even over those who did not sin in the same way that Adam (who is a type of the coming one) transgressed.'
EXEC add_BibleVerse @BibleId, 345005015, N'But the gracious gift is not like the transgression. For if the many died through the transgression of the one man, how much more did the grace of God and the gift by the grace of the one man Jesus Christ multiply to the many!'
EXEC add_BibleVerse @BibleId, 345005016, N'And the gift is not like the one who sinned. For judgment, resulting from the one transgression, led to condemnation, but the gracious gift from the many failures led to justification.'
EXEC add_BibleVerse @BibleId, 345005017, N'For if, by the transgression of the one man, death reigned through the one, how much more will those who receive the abundance of grace and of the gift of righteousness reign in life through the one, Jesus Christ!'
EXEC add_BibleVerse @BibleId, 345005018, N'Consequently, just as condemnation for all people came through one transgression, so too through the one righteous act came righteousness leading to life for all people.'
EXEC add_BibleVerse @BibleId, 345005019, N'For just as through the disobedience of the one man many were made sinners, so also through the obedience of one man many will be made righteous.'
EXEC add_BibleVerse @BibleId, 345005020, N'Now the law came in so that the transgression may increase, but where sin increased, grace multiplied all the more,'
EXEC add_BibleVerse @BibleId, 345005021, N'so that just as sin reigned in death, so also grace will reign through righteousness to eternal life through Jesus Christ our Lord.'
EXEC add_BibleVerse @BibleId, 345006001, N'What shall we say then? Are we to remain in sin so that grace may increase?'
EXEC add_BibleVerse @BibleId, 345006002, N'Absolutely not! How can we who died to sin still live in it?'
EXEC add_BibleVerse @BibleId, 345006003, N'Or do you not know that as many as were baptized into Christ Jesus were baptized into his death?'
EXEC add_BibleVerse @BibleId, 345006004, N'Therefore we have been buried with him through baptism into death, in order that just as Christ was raised from the dead through the glory of the Father, so we too may live a new life.'
EXEC add_BibleVerse @BibleId, 345006005, N'For if we have become united with him in the likeness of his death, we will certainly also be united in the likeness of his resurrection.'
EXEC add_BibleVerse @BibleId, 345006006, N'We know that our old man was crucified with him so that the body of sin would no longer dominate us, so that we would no longer be enslaved to sin.'
EXEC add_BibleVerse @BibleId, 345006007, N'(For someone who has died has been freed from sin.)'
EXEC add_BibleVerse @BibleId, 345006008, N'Now if we died with Christ, we believe that we will also live with him.'
EXEC add_BibleVerse @BibleId, 345006009, N'We know that since Christ has been raised from the dead, he is never going to die again; death no longer has mastery over him.'
EXEC add_BibleVerse @BibleId, 345006010, N'For the death he died, he died to sin once for all, but the life he lives, he lives to God.'
EXEC add_BibleVerse @BibleId, 345006011, N'So you too consider yourselves dead to sin, but alive to God in Christ Jesus.'
EXEC add_BibleVerse @BibleId, 345006012, N'Therefore do not let sin reign in your mortal body so that you obey its desires,'
EXEC add_BibleVerse @BibleId, 345006013, N'and do not present your members to sin as instruments to be used for unrighteousness, but present yourselves to God as those who are alive from the dead and your members to God as instruments to be used for righteousness.'
EXEC add_BibleVerse @BibleId, 345006014, N'For sin will have no mastery over you, because you are not under law but under grace.'
EXEC add_BibleVerse @BibleId, 345006015, N'What then? Shall we sin because we are not under law but under grace? Absolutely not!'
EXEC add_BibleVerse @BibleId, 345006016, N'Do you not know that if you present yourselves as obedient slaves, you are slaves of the one you obey, either of sin resulting in death, or obedience resulting in righteousness?'
EXEC add_BibleVerse @BibleId, 345006017, N'But thanks be to God that though you were slaves to sin, you obeyed from the heart that pattern of teaching you were entrusted to,'
EXEC add_BibleVerse @BibleId, 345006018, N'and having been freed from sin, you became enslaved to righteousness.'
EXEC add_BibleVerse @BibleId, 345006019, N'(I am speaking in human terms because of the weakness of your flesh.) For just as you once presented your members as slaves to impurity and lawlessness leading to more lawlessness, so now present your members as slaves to righteousness leading to sanctification.'
EXEC add_BibleVerse @BibleId, 345006020, N'For when you were slaves of sin, you were free with regard to righteousness.'
EXEC add_BibleVerse @BibleId, 345006021, N'So what benefit did you then reap from those things that you are now ashamed of? For the end of those things is death.'
EXEC add_BibleVerse @BibleId, 345006022, N'But now, freed from sin and enslaved to God, you have your benefit leading to sanctification, and the end is eternal life.'
EXEC add_BibleVerse @BibleId, 345006023, N'For the payoff of sin is death, but the gift of God is eternal life in Christ Jesus our Lord.'
EXEC add_BibleVerse @BibleId, 345007001, N'Or do you not know, brothers and sisters (for I am speaking to those who know the law), that the law is lord over a person as long as he lives?'
EXEC add_BibleVerse @BibleId, 345007002, N'For a married woman is bound by law to her husband as long as he lives, but if her husband dies, she is released from the law of the marriage.'
EXEC add_BibleVerse @BibleId, 345007003, N'So then, if she is joined to another man while her husband is alive, she will be called an adulteress. But if her husband dies, she is free from that law, and if she is joined to another man, she is not an adulteress.'
EXEC add_BibleVerse @BibleId, 345007004, N'So, my brothers and sisters, you also died to the law through the body of Christ, so that you could be joined to another, to the one who was raised from the dead, to bear fruit to God.'
EXEC add_BibleVerse @BibleId, 345007005, N'For when we were in the flesh, the sinful desires, aroused by the law, were active in the members of our body to bear fruit for death.'
EXEC add_BibleVerse @BibleId, 345007006, N'But now we have been released from the law, because we have died to what controlled us, so that we may serve in the new life of the Spirit and not under the old written code.'
EXEC add_BibleVerse @BibleId, 345007007, N'What shall we say then? Is the law sin? Absolutely not! Certainly, I would not have known sin except through the law. For indeed I would not have known what it means to desire something belonging to someone else if the law had not said, “ Do not covet.”'
EXEC add_BibleVerse @BibleId, 345007008, N'But sin, seizing the opportunity through the commandment, produced in me all kinds of wrong desires. For apart from the law, sin is dead.'
EXEC add_BibleVerse @BibleId, 345007009, N'And I was once alive apart from the law, but with the coming of the commandment sin became alive'
EXEC add_BibleVerse @BibleId, 345007010, N'and I died. So I found that the very commandment that was intended to bring life brought death!'
EXEC add_BibleVerse @BibleId, 345007011, N'For sin, seizing the opportunity through the commandment, deceived me and through it I died.'
EXEC add_BibleVerse @BibleId, 345007012, N'So then, the law is holy, and the commandment is holy, righteous, and good.'
EXEC add_BibleVerse @BibleId, 345007013, N'Did that which is good, then, become death to me? Absolutely not! But sin, so that it would be shown to be sin, produced death in me through what is good, so that through the commandment sin would become utterly sinful.'
EXEC add_BibleVerse @BibleId, 345007014, N'For we know that the law is spiritual – but I am unspiritual, sold into slavery to sin.'
EXEC add_BibleVerse @BibleId, 345007015, N'For I don’t understand what I am doing. For I do not do what I want – instead, I do what I hate.'
EXEC add_BibleVerse @BibleId, 345007016, N'But if I do what I don’t want, I agree that the law is good.'
EXEC add_BibleVerse @BibleId, 345007017, N'But now it is no longer me doing it, but sin that lives in me.'
EXEC add_BibleVerse @BibleId, 345007018, N'For I know that nothing good lives in me, that is, in my flesh. For I want to do the good, but I cannot do it.'
EXEC add_BibleVerse @BibleId, 345007019, N'For I do not do the good I want, but I do the very evil I do not want!'
EXEC add_BibleVerse @BibleId, 345007020, N'Now if I do what I do not want, it is no longer me doing it but sin that lives in me.'
EXEC add_BibleVerse @BibleId, 345007021, N'So, I find the law that when I want to do good, evil is present with me.'
EXEC add_BibleVerse @BibleId, 345007022, N'For I delight in the law of God in my inner being.'
EXEC add_BibleVerse @BibleId, 345007023, N'But I see a different law in my members waging war against the law of my mind and making me captive to the law of sin that is in my members.'
EXEC add_BibleVerse @BibleId, 345007024, N'Wretched man that I am! Who will rescue me from this body of death?'
EXEC add_BibleVerse @BibleId, 345007025, N'Thanks be to God through Jesus Christ our Lord! So then, I myself serve the law of God with my mind, but with my flesh I serve the law of sin.'
EXEC add_BibleVerse @BibleId, 345008001, N'There is therefore now no condemnation for those who are in Christ Jesus.'
EXEC add_BibleVerse @BibleId, 345008002, N'For the law of the life-giving Spirit in Christ Jesus has set you free from the law of sin and death.'
EXEC add_BibleVerse @BibleId, 345008003, N'For God achieved what the law could not do because it was weakened through the flesh. By sending his own Son in the likeness of sinful flesh and concerning sin, he condemned sin in the flesh,'
EXEC add_BibleVerse @BibleId, 345008004, N'so that the righteous requirement of the law may be fulfilled in us, who do not walk according to the flesh but according to the Spirit.'
EXEC add_BibleVerse @BibleId, 345008005, N'For those who live according to the flesh have their outlook shaped by the things of the flesh, but those who live according to the Spirit have their outlook shaped by the things of the Spirit.'
EXEC add_BibleVerse @BibleId, 345008006, N'For the outlook of the flesh is death, but the outlook of the Spirit is life and peace,'
EXEC add_BibleVerse @BibleId, 345008007, N'because the outlook of the flesh is hostile to God, for it does not submit to the law of God, nor is it able to do so.'
EXEC add_BibleVerse @BibleId, 345008008, N'Those who are in the flesh cannot please God.'
EXEC add_BibleVerse @BibleId, 345008009, N'You, however, are not in the flesh but in the Spirit, if indeed the Spirit of God lives in you. Now if anyone does not have the Spirit of Christ, this person does not belong to him.'
EXEC add_BibleVerse @BibleId, 345008010, N'But if Christ is in you, your body is dead because of sin, but the Spirit is your life because of righteousness.'
EXEC add_BibleVerse @BibleId, 345008011, N'Moreover if the Spirit of the one who raised Jesus from the dead lives in you, the one who raised Christ from the dead will also make your mortal bodies alive through his Spirit who lives in you.'
EXEC add_BibleVerse @BibleId, 345008012, N'So then, brothers and sisters, we are under obligation, not to the flesh, to live according to the flesh'
EXEC add_BibleVerse @BibleId, 345008013, N'(for if you live according to the flesh, you will die), but if by the Spirit you put to death the deeds of the body you will live.'
EXEC add_BibleVerse @BibleId, 345008014, N'For all who are led by the Spirit of God are the sons of God.'
EXEC add_BibleVerse @BibleId, 345008015, N'For you did not receive the spirit of slavery leading again to fear, but you received the Spirit of adoption, by whom we cry, “Abba, Father.”'
EXEC add_BibleVerse @BibleId, 345008016, N'The Spirit himself bears witness to our spirit that we are God’s children.'
EXEC add_BibleVerse @BibleId, 345008017, N'And if children, then heirs (namely, heirs of God and also fellow heirs with Christ) – if indeed we suffer with him so we may also be glorified with him.'
EXEC add_BibleVerse @BibleId, 345008018, N'For I consider that our present sufferings cannot even be compared to the glory that will be revealed to us.'
EXEC add_BibleVerse @BibleId, 345008019, N'For the creation eagerly waits for the revelation of the sons of God.'
EXEC add_BibleVerse @BibleId, 345008020, N'For the creation was subjected to futility – not willingly but because of God who subjected it – in hope'
EXEC add_BibleVerse @BibleId, 345008021, N'that the creation itself will also be set free from the bondage of decay into the glorious freedom of God’s children.'
EXEC add_BibleVerse @BibleId, 345008022, N'For we know that the whole creation groans and suffers together until now.'
EXEC add_BibleVerse @BibleId, 345008023, N'Not only this, but we ourselves also, who have the firstfruits of the Spirit, groan inwardly as we eagerly await our adoption, the redemption of our bodies.'
EXEC add_BibleVerse @BibleId, 345008024, N'For in hope we were saved. Now hope that is seen is not hope, because who hopes for what he sees?'
EXEC add_BibleVerse @BibleId, 345008025, N'But if we hope for what we do not see, we eagerly wait for it with endurance.'
EXEC add_BibleVerse @BibleId, 345008026, N'In the same way, the Spirit helps us in our weakness, for we do not know how we should pray, but the Spirit himself intercedes for us with inexpressible groanings.'
EXEC add_BibleVerse @BibleId, 345008027, N'And he who searches our hearts knows the mind of the Spirit, because the Spirit intercedes on behalf of the saints according to God’s will.'
EXEC add_BibleVerse @BibleId, 345008028, N'And we know that all things work together for good for those who love God, who are called according to his purpose,'
EXEC add_BibleVerse @BibleId, 345008029, N'because those whom he foreknew he also predestined to be conformed to the image of his Son, that his Son would be the firstborn among many brothers and sisters.'
EXEC add_BibleVerse @BibleId, 345008030, N'And those he predestined, he also called; and those he called, he also justified; and those he justified, he also glorified.'
EXEC add_BibleVerse @BibleId, 345008031, N'What then shall we say about these things? If God is for us, who can be against us?'
EXEC add_BibleVerse @BibleId, 345008032, N'Indeed, he who did not spare his own Son, but gave him up for us all – how will he not also, along with him, freely give us all things?'
EXEC add_BibleVerse @BibleId, 345008033, N'Who will bring any charge against God’s elect? It is God who justifies.'
EXEC add_BibleVerse @BibleId, 345008034, N'Who is the one who will condemn? Christ is the one who died (and more than that, he was raised), who is at the right hand of God, and who also is interceding for us.'
EXEC add_BibleVerse @BibleId, 345008035, N'Who will separate us from the love of Christ? Will trouble, or distress, or persecution, or famine, or nakedness, or danger, or sword?'
EXEC add_BibleVerse @BibleId, 345008036, N'As it is written, “ For your sake we encounter death all day long; we were considered as sheep to be slaughtered.”'
EXEC add_BibleVerse @BibleId, 345008037, N'No, in all these things we have complete victory through him who loved us!'
EXEC add_BibleVerse @BibleId, 345008038, N'For I am convinced that neither death, nor life, nor angels, nor heavenly rulers, nor things that are present, nor things to come, nor powers,'
EXEC add_BibleVerse @BibleId, 345008039, N'nor height, nor depth, nor anything else in creation will be able to separate us from the love of God in Christ Jesus our Lord.'
EXEC add_BibleVerse @BibleId, 345009001, N'I am telling the truth in Christ (I am not lying!), for my conscience assures me in the Holy Spirit –'
EXEC add_BibleVerse @BibleId, 345009002, N'I have great sorrow and unceasing anguish in my heart.'
EXEC add_BibleVerse @BibleId, 345009003, N'For I could wish that I myself were accursed – cut off from Christ – for the sake of my people, my fellow countrymen,'
EXEC add_BibleVerse @BibleId, 345009004, N'who are Israelites. To them belong the adoption as sons, the glory, the covenants, the giving of the law, the temple worship, and the promises.'
EXEC add_BibleVerse @BibleId, 345009005, N'To them belong the patriarchs, and from them, by human descent, came the Christ, who is God over all, blessed forever! Amen.'
EXEC add_BibleVerse @BibleId, 345009006, N'It is not as though the word of God had failed. For not all those who are descended from Israel are truly Israel,'
EXEC add_BibleVerse @BibleId, 345009007, N'nor are all the children Abraham’s true descendants; rather “ through Isaac will your descendants be counted.”'
EXEC add_BibleVerse @BibleId, 345009008, N'This means it is not the children of the flesh who are the children of God; rather, the children of promise are counted as descendants.'
EXEC add_BibleVerse @BibleId, 345009009, N'For this is what the promise declared: “ About a year from now I will return and Sarah will have a son.”'
EXEC add_BibleVerse @BibleId, 345009010, N'Not only that, but when Rebekah had conceived children by one man, our ancestor Isaac –'
EXEC add_BibleVerse @BibleId, 345009011, N'even before they were born or had done anything good or bad (so that God’s purpose in election would stand, not by works but by his calling) –'
EXEC add_BibleVerse @BibleId, 345009012, N'it was said to her, “ The older will serve the younger,”'
EXEC add_BibleVerse @BibleId, 345009013, N'just as it is written: “ Jacob I loved, but Esau I hated.”'
EXEC add_BibleVerse @BibleId, 345009014, N'What shall we say then? Is there injustice with God? Absolutely not!'
EXEC add_BibleVerse @BibleId, 345009015, N'For he says to Moses: “ I will have mercy on whom I have mercy, and I will have compassion on whom I have compassion.”'
EXEC add_BibleVerse @BibleId, 345009016, N'So then, it does not depend on human desire or exertion, but on God who shows mercy.'
EXEC add_BibleVerse @BibleId, 345009017, N'For the scripture says to Pharaoh: “ For this very purpose I have raised you up, that I may demonstrate my power in you, and that my name may be proclaimed in all the earth.”'
EXEC add_BibleVerse @BibleId, 345009018, N'So then, God has mercy on whom he chooses to have mercy, and he hardens whom he chooses to harden.'
EXEC add_BibleVerse @BibleId, 345009019, N'You will say to me then, “Why does he still find fault? For who has ever resisted his will?”'
EXEC add_BibleVerse @BibleId, 345009020, N'But who indeed are you – a mere human being – to talk back to God? Does what is molded say to the molder, “Why have you made me like this?”'
EXEC add_BibleVerse @BibleId, 345009021, N'Has the potter no right to make from the same lump of clay one vessel for special use and another for ordinary use?'
EXEC add_BibleVerse @BibleId, 345009022, N'But what if God, willing to demonstrate his wrath and to make known his power, has endured with much patience the objects of wrath prepared for destruction?'
EXEC add_BibleVerse @BibleId, 345009023, N'And what if he is willing to make known the wealth of his glory on the objects of mercy that he has prepared beforehand for glory –'
EXEC add_BibleVerse @BibleId, 345009024, N'even us, whom he has called, not only from the Jews but also from the Gentiles?'
EXEC add_BibleVerse @BibleId, 345009025, N'As he also says in Hosea: “ I will call those who were not my people, ‘My people,’ and I will call her who was unloved, ‘My beloved.*’”'
EXEC add_BibleVerse @BibleId, 345009026, N'“ And in the very place where it was said to them, ‘You are not my people,*’ there they will be called ‘sons of the living God.’”'
EXEC add_BibleVerse @BibleId, 345009027, N'And Isaiah cries out on behalf of Israel, “Though the number of the children of Israel are as the sand of the sea, only the remnant will be saved,'
EXEC add_BibleVerse @BibleId, 345009028, N'for the Lord will execute his sentence on the earth completely and quickly.”'
EXEC add_BibleVerse @BibleId, 345009029, N'Just as Isaiah predicted, “ If the Lord of armies had not left us descendants,* we would have become like Sodom, and we would have resembled Gomorrah.”'
EXEC add_BibleVerse @BibleId, 345009030, N'What shall we say then? – that the Gentiles who did not pursue righteousness obtained it, that is, a righteousness that is by faith,'
EXEC add_BibleVerse @BibleId, 345009031, N'but Israel even though pursuing a law of righteousness did not attain it.'
EXEC add_BibleVerse @BibleId, 345009032, N'Why not? Because they pursued it not by faith but (as if it were possible) by works. They stumbled over the stumbling stone,'
EXEC add_BibleVerse @BibleId, 345009033, N'just as it is written, “ Look, I am laying in Zion a stone that will cause people to stumble and a rock that will make them fall, yet the one who believes in him will not be put to shame.”'
EXEC add_BibleVerse @BibleId, 345010001, N'Brothers and sisters, my heart’s desire and prayer to God on behalf of my fellow Israelites is for their salvation.'
EXEC add_BibleVerse @BibleId, 345010002, N'For I can testify that they are zealous for God, but their zeal is not in line with the truth.'
EXEC add_BibleVerse @BibleId, 345010003, N'For ignoring the righteousness that comes from God, and seeking instead to establish their own righteousness, they did not submit to God’s righteousness.'
EXEC add_BibleVerse @BibleId, 345010004, N'For Christ is the end of the law, with the result that there is righteousness for everyone who believes.'
EXEC add_BibleVerse @BibleId, 345010005, N'For Moses writes about the righteousness that is by the law: “ The one who does these things will live by them.”'
EXEC add_BibleVerse @BibleId, 345010006, N'But the righteousness that is by faith says: “ Do not say in your heart, ‘ Who will ascend into heaven?’” (that is, to bring Christ down)'
EXEC add_BibleVerse @BibleId, 345010007, N'or “ Who will descend into the abyss?” (that is, to bring Christ up from the dead).'
EXEC add_BibleVerse @BibleId, 345010008, N'But what does it say? “ The word is near you, in your mouth and in your heart” (that is, the word of faith that we preach),'
EXEC add_BibleVerse @BibleId, 345010009, N'because if you confess with your mouth that Jesus is Lord and believe in your heart that God raised him from the dead, you will be saved.'
EXEC add_BibleVerse @BibleId, 345010010, N'For with the heart one believes and thus has righteousness and with the mouth one confesses and thus has salvation.'
EXEC add_BibleVerse @BibleId, 345010011, N'For the scripture says, “ Everyone who believes in him will not be put to shame.”'
EXEC add_BibleVerse @BibleId, 345010012, N'For there is no distinction between the Jew and the Greek, for the same Lord is Lord of all, who richly blesses all who call on him.'
EXEC add_BibleVerse @BibleId, 345010013, N'For everyone who calls on the name of the Lord will be saved.'
EXEC add_BibleVerse @BibleId, 345010014, N'How are they to call on one they have not believed in? And how are they to believe in one they have not heard of? And how are they to hear without someone preaching to them ?'
EXEC add_BibleVerse @BibleId, 345010015, N'And how are they to preach unless they are sent? As it is written, “ How timely is the arrival of those who proclaim the good news*.”'
EXEC add_BibleVerse @BibleId, 345010016, N'But not all have obeyed the good news, for Isaiah says, “ Lord, who has believed our report?”'
EXEC add_BibleVerse @BibleId, 345010017, N'Consequently faith comes from what is heard, and what is heard comes through the preached word of Christ.'
EXEC add_BibleVerse @BibleId, 345010018, N'But I ask, have they not heard? Yes, they have: Their voice has gone out to all the earth, and their words to the ends of the world.'
EXEC add_BibleVerse @BibleId, 345010019, N'But again I ask, didn’t Israel understand? First Moses says, “ I will make you jealous by those who are not a nation; with a senseless nation I will provoke you to anger.”'
EXEC add_BibleVerse @BibleId, 345010020, N'And Isaiah is even bold enough to say, “ I was found by those who did not seek me; I became well known to those who did not ask for me.”'
EXEC add_BibleVerse @BibleId, 345010021, N'But about Israel he says, “ All day long I held out my hands to this disobedient and stubborn people!”'
EXEC add_BibleVerse @BibleId, 345011001, N'So I ask, God has not rejected his people, has he? Absolutely not! For I too am an Israelite, a descendant of Abraham, from the tribe of Benjamin.'
EXEC add_BibleVerse @BibleId, 345011002, N'God has not rejected his people whom he foreknew! Do you not know what the scripture says about Elijah, how he pleads with God against Israel?'
EXEC add_BibleVerse @BibleId, 345011003, N'“Lord, they have killed your prophets, they have demolished your altars; I alone am left and they are seeking my life!”'
EXEC add_BibleVerse @BibleId, 345011004, N'But what was the divine response to him? “ I have kept for myself seven thousand people who have not bent the knee to Baal*.”'
EXEC add_BibleVerse @BibleId, 345011005, N'So in the same way at the present time there is a remnant chosen by grace.'
EXEC add_BibleVerse @BibleId, 345011006, N'And if it is by grace, it is no longer by works, otherwise grace would no longer be grace.'
EXEC add_BibleVerse @BibleId, 345011007, N'What then? Israel failed to obtain what it was diligently seeking, but the elect obtained it. The rest were hardened,'
EXEC add_BibleVerse @BibleId, 345011008, N'as it is written, “God gave them a spirit of stupor, eyes that would not see and ears that would not hear, to this very day.”'
EXEC add_BibleVerse @BibleId, 345011009, N'And David says, “Let their table become a snare and trap, a stumbling block and a retribution for them;'
EXEC add_BibleVerse @BibleId, 345011010, N'let their eyes be darkened so that they may not see, and make their backs bend continually.”'
EXEC add_BibleVerse @BibleId, 345011011, N'I ask then, they did not stumble into an irrevocable fall, did they? Absolutely not! But by their transgression salvation has come to the Gentiles, to make Israel jealous.'
EXEC add_BibleVerse @BibleId, 345011012, N'Now if their transgression means riches for the world and their defeat means riches for the Gentiles, how much more will their full restoration bring?'
EXEC add_BibleVerse @BibleId, 345011013, N'Now I am speaking to you Gentiles. Seeing that I am an apostle to the Gentiles, I magnify my ministry,'
EXEC add_BibleVerse @BibleId, 345011014, N'if somehow I could provoke my people to jealousy and save some of them.'
EXEC add_BibleVerse @BibleId, 345011015, N'For if their rejection is the reconciliation of the world, what will their acceptance be but life from the dead?'
EXEC add_BibleVerse @BibleId, 345011016, N'If the first portion of the dough offered is holy, then the whole batch is holy, and if the root is holy, so too are the branches.'
EXEC add_BibleVerse @BibleId, 345011017, N'Now if some of the branches were broken off, and you, a wild olive shoot, were grafted in among them and participated in the richness of the olive root,'
EXEC add_BibleVerse @BibleId, 345011018, N'do not boast over the branches. But if you boast, remember that you do not support the root, but the root supports you.'
EXEC add_BibleVerse @BibleId, 345011019, N'Then you will say, “The branches were broken off so that I could be grafted in.”'
EXEC add_BibleVerse @BibleId, 345011020, N'Granted! They were broken off because of their unbelief, but you stand by faith. Do not be arrogant, but fear!'
EXEC add_BibleVerse @BibleId, 345011021, N'For if God did not spare the natural branches, perhaps he will not spare you.'
EXEC add_BibleVerse @BibleId, 345011022, N'Notice therefore the kindness and harshness of God – harshness toward those who have fallen, but God’s kindness toward you, provided you continue in his kindness; otherwise you also will be cut off.'
EXEC add_BibleVerse @BibleId, 345011023, N'And even they – if they do not continue in their unbelief – will be grafted in, for God is able to graft them in again.'
EXEC add_BibleVerse @BibleId, 345011024, N'For if you were cut off from what is by nature a wild olive tree, and grafted, contrary to nature, into a cultivated olive tree, how much more will these natural branches be grafted back into their own olive tree?'
EXEC add_BibleVerse @BibleId, 345011025, N'For I do not want you to be ignorant of this mystery, brothers and sisters, so that you may not be conceited: A partial hardening has happened to Israel until the full number of the Gentiles has come in.'
EXEC add_BibleVerse @BibleId, 345011026, N'And so all Israel will be saved, as it is written: “The Deliverer will come out of Zion; he will remove ungodliness from Jacob.'
EXEC add_BibleVerse @BibleId, 345011027, N'And this is my covenant with them, when I take away their sins.”'
EXEC add_BibleVerse @BibleId, 345011028, N'In regard to the gospel they are enemies for your sake, but in regard to election they are dearly loved for the sake of the fathers.'
EXEC add_BibleVerse @BibleId, 345011029, N'For the gifts and the call of God are irrevocable.'
EXEC add_BibleVerse @BibleId, 345011030, N'Just as you were formerly disobedient to God, but have now received mercy due to their disobedience,'
EXEC add_BibleVerse @BibleId, 345011031, N'so they too have now been disobedient in order that, by the mercy shown to you, they too may now receive mercy.'
EXEC add_BibleVerse @BibleId, 345011032, N'For God has consigned all people to disobedience so that he may show mercy to them all.'
EXEC add_BibleVerse @BibleId, 345011033, N'Oh, the depth of the riches and wisdom and knowledge of God! How unsearchable are his judgments and how fathomless his ways!'
EXEC add_BibleVerse @BibleId, 345011034, N'For who has known the mind of the Lord, or who has been his counselor?'
EXEC add_BibleVerse @BibleId, 345011035, N'Or who has first given to God, that God needs to repay him?'
EXEC add_BibleVerse @BibleId, 345011036, N'For from him and through him and to him are all things. To him be glory forever! Amen.'
EXEC add_BibleVerse @BibleId, 345012001, N'Therefore I exhort you, brothers and sisters, by the mercies of God, to present your bodies as a sacrifice – alive, holy, and pleasing to God – which is your reasonable service.'
EXEC add_BibleVerse @BibleId, 345012002, N'Do not be conformed to this present world, but be transformed by the renewing of your mind, so that you may test and approve what is the will of God – what is good and well-pleasing and perfect.'
EXEC add_BibleVerse @BibleId, 345012003, N'For by the grace given to me I say to every one of you not to think more highly of yourself than you ought to think, but to think with sober discernment, as God has distributed to each of you a measure of faith.'
EXEC add_BibleVerse @BibleId, 345012004, N'For just as in one body we have many members, and not all the members serve the same function,'
EXEC add_BibleVerse @BibleId, 345012005, N'so we who are many are one body in Christ, and individually we are members who belong to one another.'
EXEC add_BibleVerse @BibleId, 345012006, N'And we have different gifts according to the grace given to us. If the gift is prophecy, that individual must use it in proportion to his faith.'
EXEC add_BibleVerse @BibleId, 345012007, N'If it is service, he must serve; if it is teaching, he must teach;'
EXEC add_BibleVerse @BibleId, 345012008, N'if it is exhortation, he must exhort; if it is contributing, he must do so with sincerity; if it is leadership, he must do so with diligence; if it is showing mercy, he must do so with cheerfulness.'
EXEC add_BibleVerse @BibleId, 345012009, N'Love must be without hypocrisy. Abhor what is evil, cling to what is good.'
EXEC add_BibleVerse @BibleId, 345012010, N'Be devoted to one another with mutual love, showing eagerness in honoring one another.'
EXEC add_BibleVerse @BibleId, 345012011, N'Do not lag in zeal, be enthusiastic in spirit, serve the Lord.'
EXEC add_BibleVerse @BibleId, 345012012, N'Rejoice in hope, endure in suffering, persist in prayer.'
EXEC add_BibleVerse @BibleId, 345012013, N'Contribute to the needs of the saints, pursue hospitality.'
EXEC add_BibleVerse @BibleId, 345012014, N'Bless those who persecute you, bless and do not curse.'
EXEC add_BibleVerse @BibleId, 345012015, N'Rejoice with those who rejoice, weep with those who weep.'
EXEC add_BibleVerse @BibleId, 345012016, N'Live in harmony with one another; do not be haughty but associate with the lowly. Do not be conceited.'
EXEC add_BibleVerse @BibleId, 345012017, N'Do not repay anyone evil for evil; consider what is good before all people.'
EXEC add_BibleVerse @BibleId, 345012018, N'If possible, so far as it depends on you, live peaceably with all people.'
EXEC add_BibleVerse @BibleId, 345012019, N'Do not avenge yourselves, dear friends, but give place to God’s wrath, for it is written, “ Vengeance is mine, I will repay,” says the Lord.'
EXEC add_BibleVerse @BibleId, 345012020, N'Rather, if your enemy is hungry, feed him; if he is thirsty, give him a drink; for in doing this you will be heaping burning coals on his head.'
EXEC add_BibleVerse @BibleId, 345012021, N'Do not be overcome by evil, but overcome evil with good.'
EXEC add_BibleVerse @BibleId, 345013001, N'Let every person be subject to the governing authorities. For there is no authority except by God’s appointment, and the authorities that exist have been instituted by God.'
EXEC add_BibleVerse @BibleId, 345013002, N'So the person who resists such authority resists the ordinance of God, and those who resist will incur judgment'
EXEC add_BibleVerse @BibleId, 345013003, N'(for rulers cause no fear for good conduct but for bad). Do you desire not to fear authority? Do good and you will receive its commendation,'
EXEC add_BibleVerse @BibleId, 345013004, N'for it is God’s servant for your good. But if you do wrong, be in fear, for it does not bear the sword in vain. It is God’s servant to administer retribution on the wrongdoer.'
EXEC add_BibleVerse @BibleId, 345013005, N'Therefore it is necessary to be in subjection, not only because of the wrath of the authorities but also because of your conscience.'
EXEC add_BibleVerse @BibleId, 345013006, N'For this reason you also pay taxes, for the authorities are God’s servants devoted to governing.'
EXEC add_BibleVerse @BibleId, 345013007, N'Pay everyone what is owed: taxes to whom taxes are due, revenue to whom revenue is due, respect to whom respect is due, honor to whom honor is due.'
EXEC add_BibleVerse @BibleId, 345013008, N'Owe no one anything, except to love one another, for the one who loves his neighbor has fulfilled the law.'
EXEC add_BibleVerse @BibleId, 345013009, N'For the commandments, “ Do not commit adultery, do not murder, do not steal, do not covet,” (and if there is any other commandment) are summed up in this, “ Love your neighbor as yourself.”'
EXEC add_BibleVerse @BibleId, 345013010, N'Love does no wrong to a neighbor. Therefore love is the fulfillment of the law.'
EXEC add_BibleVerse @BibleId, 345013011, N'And do this because we know the time, that it is already the hour for us to awake from sleep, for our salvation is now nearer than when we became believers.'
EXEC add_BibleVerse @BibleId, 345013012, N'The night has advanced toward dawn; the day is near. So then we must lay aside the works of darkness, and put on the weapons of light.'
EXEC add_BibleVerse @BibleId, 345013013, N'Let us live decently as in the daytime, not in carousing and drunkenness, not in sexual immorality and sensuality, not in discord and jealousy.'
EXEC add_BibleVerse @BibleId, 345013014, N'Instead, put on the Lord Jesus Christ, and make no provision for the flesh to arouse its desires.'
EXEC add_BibleVerse @BibleId, 345014001, N'Now receive the one who is weak in the faith, and do not have disputes over differing opinions.'
EXEC add_BibleVerse @BibleId, 345014002, N'One person believes in eating everything, but the weak person eats only vegetables.'
EXEC add_BibleVerse @BibleId, 345014003, N'The one who eats everything must not despise the one who does not, and the one who abstains must not judge the one who eats everything, for God has accepted him.'
EXEC add_BibleVerse @BibleId, 345014004, N'Who are you to pass judgment on another’s servant? Before his own master he stands or falls. And he will stand, for the Lord is able to make him stand.'
EXEC add_BibleVerse @BibleId, 345014005, N'One person regards one day holier than other days, and another regards them all alike. Each must be fully convinced in his own mind.'
EXEC add_BibleVerse @BibleId, 345014006, N'The one who observes the day does it for the Lord. The one who eats, eats for the Lord because he gives thanks to God, and the one who abstains from eating abstains for the Lord, and he gives thanks to God.'
EXEC add_BibleVerse @BibleId, 345014007, N'For none of us lives for himself and none dies for himself.'
EXEC add_BibleVerse @BibleId, 345014008, N'If we live, we live for the Lord; if we die, we die for the Lord. Therefore, whether we live or die, we are the Lord’s.'
EXEC add_BibleVerse @BibleId, 345014009, N'For this reason Christ died and returned to life, so that he may be the Lord of both the dead and the living.'
EXEC add_BibleVerse @BibleId, 345014010, N'But you who eat vegetables only – why do you judge your brother or sister? And you who eat everything – why do you despise your brother or sister? For we will all stand before the judgment seat of God.'
EXEC add_BibleVerse @BibleId, 345014011, N'For it is written, “ As I live, says the Lord, every knee will bow to me, and every tongue will give praise to God.”'
EXEC add_BibleVerse @BibleId, 345014012, N'Therefore, each of us will give an account of himself to God.'
EXEC add_BibleVerse @BibleId, 345014013, N'Therefore we must not pass judgment on one another, but rather determine never to place an obstacle or a trap before a brother or sister.'
EXEC add_BibleVerse @BibleId, 345014014, N'I know and am convinced in the Lord Jesus that there is nothing unclean in itself; still, it is unclean to the one who considers it unclean.'
EXEC add_BibleVerse @BibleId, 345014015, N'For if your brother or sister is distressed because of what you eat, you are no longer walking in love. Do not destroy by your food someone for whom Christ died.'
EXEC add_BibleVerse @BibleId, 345014016, N'Therefore do not let what you consider good be spoken of as evil.'
EXEC add_BibleVerse @BibleId, 345014017, N'For the kingdom of God does not consist of food and drink, but righteousness, peace, and joy in the Holy Spirit.'
EXEC add_BibleVerse @BibleId, 345014018, N'For the one who serves Christ in this way is pleasing to God and approved by people.'
EXEC add_BibleVerse @BibleId, 345014019, N'So then, let us pursue what makes for peace and for building up one another.'
EXEC add_BibleVerse @BibleId, 345014020, N'Do not destroy the work of God for the sake of food. For although all things are clean, it is wrong to cause anyone to stumble by what you eat.'
EXEC add_BibleVerse @BibleId, 345014021, N'It is good not to eat meat or drink wine or to do anything that causes your brother to stumble.'
EXEC add_BibleVerse @BibleId, 345014022, N'The faith you have, keep to yourself before God. Blessed is the one who does not judge himself by what he approves.'
EXEC add_BibleVerse @BibleId, 345014023, N'But the man who doubts is condemned if he eats, because he does not do so from faith, and whatever is not from faith is sin.'
EXEC add_BibleVerse @BibleId, 345015001, N'But we who are strong ought to bear with the failings of the weak, and not just please ourselves.'
EXEC add_BibleVerse @BibleId, 345015002, N'Let each of us please his neighbor for his good to build him up.'
EXEC add_BibleVerse @BibleId, 345015003, N'For even Christ did not please himself, but just as it is written, “ The insults of those who insult you have fallen on me.”'
EXEC add_BibleVerse @BibleId, 345015004, N'For everything that was written in former times was written for our instruction, so that through endurance and through encouragement of the scriptures we may have hope.'
EXEC add_BibleVerse @BibleId, 345015005, N'Now may the God of endurance and comfort give you unity with one another in accordance with Christ Jesus,'
EXEC add_BibleVerse @BibleId, 345015006, N'so that together you may with one voice glorify the God and Father of our Lord Jesus Christ.'
EXEC add_BibleVerse @BibleId, 345015007, N'Receive one another, then, just as Christ also received you, to God’s glory.'
EXEC add_BibleVerse @BibleId, 345015008, N'For I tell you that Christ has become a servant of the circumcised on behalf of God’s truth to confirm the promises made to the fathers,'
EXEC add_BibleVerse @BibleId, 345015009, N'and thus the Gentiles glorify God for his mercy. As it is written, “ Because of this I will confess you among the Gentiles, and I will sing praises to your name.”'
EXEC add_BibleVerse @BibleId, 345015010, N'And again it says: “ Rejoice, O Gentiles, with his people.”'
EXEC add_BibleVerse @BibleId, 345015011, N'And again, “ Praise the Lord all you Gentiles, and let all the peoples praise him.”'
EXEC add_BibleVerse @BibleId, 345015012, N'And again Isaiah says, “ The root of Jesse will come, and the one who rises to rule over the Gentiles, in him will the Gentiles hope.”'
EXEC add_BibleVerse @BibleId, 345015013, N'Now may the God of hope fill you with all joy and peace as you believe in him, so that you may abound in hope by the power of the Holy Spirit.'
EXEC add_BibleVerse @BibleId, 345015014, N'But I myself am fully convinced about you, my brothers and sisters, that you yourselves are full of goodness, filled with all knowledge, and able to instruct one another.'
EXEC add_BibleVerse @BibleId, 345015015, N'But I have written more boldly to you on some points so as to remind you, because of the grace given to me by God'
EXEC add_BibleVerse @BibleId, 345015016, N'to be a minister of Christ Jesus to the Gentiles. I serve the gospel of God like a priest, so that the Gentiles may become an acceptable offering, sanctified by the Holy Spirit.'
EXEC add_BibleVerse @BibleId, 345015017, N'So I boast in Christ Jesus about the things that pertain to God.'
EXEC add_BibleVerse @BibleId, 345015018, N'For I will not dare to speak of anything except what Christ has accomplished through me in order to bring about the obedience of the Gentiles, by word and deed,'
EXEC add_BibleVerse @BibleId, 345015019, N'in the power of signs and wonders, in the power of the Spirit of God. So from Jerusalem even as far as Illyricum I have fully preached the gospel of Christ.'
EXEC add_BibleVerse @BibleId, 345015020, N'And in this way I desire to preach where Christ has not been named, so as not to build on another person’s foundation,'
EXEC add_BibleVerse @BibleId, 345015021, N'but as it is written: “ Those who were not told about him will see, and those who have not heard will understand.”'
EXEC add_BibleVerse @BibleId, 345015022, N'This is the reason I was often hindered from coming to you.'
EXEC add_BibleVerse @BibleId, 345015023, N'But now there is nothing more to keep me in these regions, and I have for many years desired to come to you'
EXEC add_BibleVerse @BibleId, 345015024, N'when I go to Spain. For I hope to visit you when I pass through and that you will help me on my journey there, after I have enjoyed your company for a while.'
EXEC add_BibleVerse @BibleId, 345015025, N'But now I go to Jerusalem to minister to the saints.'
EXEC add_BibleVerse @BibleId, 345015026, N'For Macedonia and Achaia are pleased to make some contribution for the poor among the saints in Jerusalem.'
EXEC add_BibleVerse @BibleId, 345015027, N'For they were pleased to do this, and indeed they are indebted to the Jerusalem saints. For if the Gentiles have shared in their spiritual things, they are obligated also to minister to them in material things.'
EXEC add_BibleVerse @BibleId, 345015028, N'Therefore after I have completed this and have safely delivered this bounty to them, I will set out for Spain by way of you,'
EXEC add_BibleVerse @BibleId, 345015029, N'and I know that when I come to you I will come in the fullness of Christ’s blessing.'
EXEC add_BibleVerse @BibleId, 345015030, N'Now I urge you, brothers and sisters, through our Lord Jesus Christ and through the love of the Spirit, to join fervently with me in prayer to God on my behalf.'
EXEC add_BibleVerse @BibleId, 345015031, N'Pray that I may be rescued from those who are disobedient in Judea and that my ministry in Jerusalem may be acceptable to the saints,'
EXEC add_BibleVerse @BibleId, 345015032, N'so that by God’s will I may come to you with joy and be refreshed in your company.'
EXEC add_BibleVerse @BibleId, 345015033, N'Now may the God of peace be with all of you. Amen.'
EXEC add_BibleVerse @BibleId, 345016001, N'Now I commend to you our sister Phoebe, who is a servant of the church in Cenchrea,'
EXEC add_BibleVerse @BibleId, 345016002, N'so that you may welcome her in the Lord in a way worthy of the saints and provide her with whatever help she may need from you, for she has been a great help to many, including me.'
EXEC add_BibleVerse @BibleId, 345016003, N'Greet Prisca and Aquila, my fellow workers in Christ Jesus,'
EXEC add_BibleVerse @BibleId, 345016004, N'who risked their own necks for my life. Not only I, but all the churches of the Gentiles are grateful to them.'
EXEC add_BibleVerse @BibleId, 345016005, N'Also greet the church in their house. Greet my dear friend Epenetus, who was the first convert to Christ in the province of Asia.'
EXEC add_BibleVerse @BibleId, 345016006, N'Greet Mary, who has worked very hard for you.'
EXEC add_BibleVerse @BibleId, 345016007, N'Greet Andronicus and Junia, my compatriots and my fellow prisoners. They are well known to the apostles, and they were in Christ before me.'
EXEC add_BibleVerse @BibleId, 345016008, N'Greet Ampliatus, my dear friend in the Lord.'
EXEC add_BibleVerse @BibleId, 345016009, N'Greet Urbanus, our fellow worker in Christ, and my good friend Stachys.'
EXEC add_BibleVerse @BibleId, 345016010, N'Greet Apelles, who is approved in Christ. Greet those who belong to the household of Aristobulus.'
EXEC add_BibleVerse @BibleId, 345016011, N'Greet Herodion, my compatriot. Greet those in the household of Narcissus who are in the Lord.'
EXEC add_BibleVerse @BibleId, 345016012, N'Greet Tryphena and Tryphosa, laborers in the Lord. Greet my dear friend Persis, who has worked hard in the Lord.'
EXEC add_BibleVerse @BibleId, 345016013, N'Greet Rufus, chosen in the Lord, and his mother who was also a mother to me.'
EXEC add_BibleVerse @BibleId, 345016014, N'Greet Asyncritus, Phlegon, Hermes, Patrobas, Hermas, and the brothers and sisters with them.'
EXEC add_BibleVerse @BibleId, 345016015, N'Greet Philologus and Julia, Nereus and his sister, and Olympas, and all the believers who are with them.'
EXEC add_BibleVerse @BibleId, 345016016, N'Greet one another with a holy kiss. All the churches of Christ greet you.'
EXEC add_BibleVerse @BibleId, 345016017, N'Now I urge you, brothers and sisters, to watch out for those who create dissensions and obstacles contrary to the teaching that you learned. Avoid them!'
EXEC add_BibleVerse @BibleId, 345016018, N'For these are the kind who do not serve our Lord Christ, but their own appetites. By their smooth talk and flattery they deceive the minds of the naive.'
EXEC add_BibleVerse @BibleId, 345016019, N'Your obedience is known to all and thus I rejoice over you. But I want you to be wise in what is good and innocent in what is evil.'
EXEC add_BibleVerse @BibleId, 345016020, N'The God of peace will quickly crush Satan under your feet. The grace of our Lord Jesus be with you.'
EXEC add_BibleVerse @BibleId, 345016021, N'Timothy, my fellow worker, greets you; so do Lucius, Jason, and Sosipater, my compatriots.'
EXEC add_BibleVerse @BibleId, 345016022, N'I, Tertius, who am writing this letter, greet you in the Lord.'
EXEC add_BibleVerse @BibleId, 345016023, N'Gaius, who is host to me and to the whole church, greets you. Erastus the city treasurer and our brother Quartus greet you.'
EXEC add_BibleVerse @BibleId, 345016025, N' Now to him who is able to strengthen you according to my gospel and the proclamation of Jesus Christ, according to the revelation of the mystery that had been kept secret for long ages,'
EXEC add_BibleVerse @BibleId, 345016026, N'but now is disclosed, and through the prophetic scriptures has been made known to all the nations, according to the command of the eternal God, to bring about the obedience of faith –'
EXEC add_BibleVerse @BibleId, 345016027, N'to the only wise God, through Jesus Christ, be glory forever! Amen.'
EXEC add_BibleVerse @BibleId, 346001001, N'From Paul, called to be an apostle of Christ Jesus by the will of God, and Sosthenes, our brother,'
EXEC add_BibleVerse @BibleId, 346001002, N'to the church of God that is in Corinth, to those who are sanctified in Christ Jesus, and called to be saints, with all those in every place who call on the name of our Lord Jesus Christ, their Lord and ours.'
EXEC add_BibleVerse @BibleId, 346001003, N'Grace and peace to you from God our Father and the Lord Jesus Christ!'
EXEC add_BibleVerse @BibleId, 346001004, N'I always thank my God for you because of the grace of God that was given to you in Christ Jesus.'
EXEC add_BibleVerse @BibleId, 346001005, N'For you were made rich in every way in him, in all your speech and in every kind of knowledge –'
EXEC add_BibleVerse @BibleId, 346001006, N'just as the testimony about Christ has been confirmed among you –'
EXEC add_BibleVerse @BibleId, 346001007, N'so that you do not lack any spiritual gift as you wait for the revelation of our Lord Jesus Christ.'
EXEC add_BibleVerse @BibleId, 346001008, N'He will also strengthen you to the end, so that you will be blameless on the day of our Lord Jesus Christ.'
EXEC add_BibleVerse @BibleId, 346001009, N'God is faithful, by whom you were called into fellowship with his son, Jesus Christ our Lord.'
EXEC add_BibleVerse @BibleId, 346001010, N'I urge you, brothers and sisters, by the name of our Lord Jesus Christ, to agree together, to end your divisions, and to be united by the same mind and purpose.'
EXEC add_BibleVerse @BibleId, 346001011, N'For members of Chloe’s household have made it clear to me, my brothers and sisters, that there are quarrels among you.'
EXEC add_BibleVerse @BibleId, 346001012, N'Now I mean this, that each of you is saying, “I am with Paul,” or “I am with Apollos,” or “I am with Cephas,” or “I am with Christ.”'
EXEC add_BibleVerse @BibleId, 346001013, N'Is Christ divided? Paul wasn’t crucified for you, was he? Or were you in fact baptized in the name of Paul?'
EXEC add_BibleVerse @BibleId, 346001014, N'I thank God that I did not baptize any of you except Crispus and Gaius,'
EXEC add_BibleVerse @BibleId, 346001015, N'so that no one can say that you were baptized in my name!'
EXEC add_BibleVerse @BibleId, 346001016, N'(I also baptized the household of Stephanus. Otherwise, I do not remember whether I baptized anyone else.)'
EXEC add_BibleVerse @BibleId, 346001017, N'For Christ did not send me to baptize, but to preach the gospel – and not with clever speech, so that the cross of Christ would not become useless.'
EXEC add_BibleVerse @BibleId, 346001018, N'For the message about the cross is foolishness to those who are perishing, but to us who are being saved it is the power of God.'
EXEC add_BibleVerse @BibleId, 346001019, N'For it is written, “ I will destroy the wisdom of the wise, and I will thwart the cleverness of the intelligent.”'
EXEC add_BibleVerse @BibleId, 346001020, N'Where is the wise man? Where is the expert in the Mosaic law? Where is the debater of this age? Has God not made the wisdom of the world foolish?'
EXEC add_BibleVerse @BibleId, 346001021, N'For since in the wisdom of God the world by its wisdom did not know God, God was pleased to save those who believe by the foolishness of preaching.'
EXEC add_BibleVerse @BibleId, 346001022, N'For Jews demand miraculous signs and Greeks ask for wisdom,'
EXEC add_BibleVerse @BibleId, 346001023, N'but we preach about a crucified Christ, a stumbling block to Jews and foolishness to Gentiles.'
EXEC add_BibleVerse @BibleId, 346001024, N'But to those who are called, both Jews and Greeks, Christ is the power of God and the wisdom of God.'
EXEC add_BibleVerse @BibleId, 346001025, N'For the foolishness of God is wiser than human wisdom, and the weakness of God is stronger than human strength.'
EXEC add_BibleVerse @BibleId, 346001026, N'Think about the circumstances of your call, brothers and sisters. Not many were wise by human standards, not many were powerful, not many were born to a privileged position.'
EXEC add_BibleVerse @BibleId, 346001027, N'But God chose what the world thinks foolish to shame the wise, and God chose what the world thinks weak to shame the strong.'
EXEC add_BibleVerse @BibleId, 346001028, N'God chose what is low and despised in the world, what is regarded as nothing, to set aside what is regarded as something,'
EXEC add_BibleVerse @BibleId, 346001029, N'so that no one can boast in his presence.'
EXEC add_BibleVerse @BibleId, 346001030, N'He is the reason you have a relationship with Christ Jesus, who became for us wisdom from God, and righteousness and sanctification and redemption,'
EXEC add_BibleVerse @BibleId, 346001031, N'so that, as it is written, “ Let the one who boasts, boast in the Lord.”'
EXEC add_BibleVerse @BibleId, 346002001, N'When I came to you, brothers and sisters, I did not come with superior eloquence or wisdom as I proclaimed the testimony of God.'
EXEC add_BibleVerse @BibleId, 346002002, N'For I decided to be concerned about nothing among you except Jesus Christ, and him crucified.'
EXEC add_BibleVerse @BibleId, 346002003, N'And I was with you in weakness and in fear and with much trembling.'
EXEC add_BibleVerse @BibleId, 346002004, N'My conversation and my preaching were not with persuasive words of wisdom, but with a demonstration of the Spirit and of power,'
EXEC add_BibleVerse @BibleId, 346002005, N'so that your faith would not be based on human wisdom but on the power of God.'
EXEC add_BibleVerse @BibleId, 346002006, N'Now we do speak wisdom among the mature, but not a wisdom of this age or of the rulers of this age, who are perishing.'
EXEC add_BibleVerse @BibleId, 346002007, N'Instead we speak the wisdom of God, hidden in a mystery, that God determined before the ages for our glory.'
EXEC add_BibleVerse @BibleId, 346002008, N'None of the rulers of this age understood it. If they had known it, they would not have crucified the Lord of glory.'
EXEC add_BibleVerse @BibleId, 346002009, N'But just as it is written, “ Things that no eye has seen, or ear heard, or mind imagined, are the things God has prepared for those who love him.”'
EXEC add_BibleVerse @BibleId, 346002010, N'God has revealed these to us by the Spirit. For the Spirit searches all things, even the deep things of God.'
EXEC add_BibleVerse @BibleId, 346002011, N'For who among men knows the things of a man except the man’s spirit within him? So too, no one knows the things of God except the Spirit of God.'
EXEC add_BibleVerse @BibleId, 346002012, N'Now we have not received the spirit of the world, but the Spirit who is from God, so that we may know the things that are freely given to us by God.'
EXEC add_BibleVerse @BibleId, 346002013, N'And we speak about these things, not with words taught us by human wisdom, but with those taught by the Spirit, explaining spiritual things to spiritual people.'
EXEC add_BibleVerse @BibleId, 346002014, N'The unbeliever does not receive the things of the Spirit of God, for they are foolishness to him. And he cannot understand them, because they are spiritually discerned.'
EXEC add_BibleVerse @BibleId, 346002015, N'The one who is spiritual discerns all things, yet he himself is understood by no one.'
EXEC add_BibleVerse @BibleId, 346002016, N'For who has known the mind of the Lord, so as to advise him? But we have the mind of Christ.'
EXEC add_BibleVerse @BibleId, 346003001, N'So, brothers and sisters, I could not speak to you as spiritual people, but instead as people of the flesh, as infants in Christ.'
EXEC add_BibleVerse @BibleId, 346003002, N'I fed you milk, not solid food, for you were not yet ready. In fact, you are still not ready,'
EXEC add_BibleVerse @BibleId, 346003003, N'for you are still influenced by the flesh. For since there is still jealousy and dissension among you, are you not influenced by the flesh and behaving like unregenerate people?'
EXEC add_BibleVerse @BibleId, 346003004, N'For whenever someone says, “I am with Paul,” or “I am with Apollos,” are you not merely human?'
EXEC add_BibleVerse @BibleId, 346003005, N'What is Apollos, really? Or what is Paul? Servants through whom you came to believe, and each of us in the ministry the Lord gave us.'
EXEC add_BibleVerse @BibleId, 346003006, N'I planted, Apollos watered, but God caused it to grow.'
EXEC add_BibleVerse @BibleId, 346003007, N'So neither the one who plants counts for anything, nor the one who waters, but God who causes the growth.'
EXEC add_BibleVerse @BibleId, 346003008, N'The one who plants and the one who waters work as one, but each will receive his reward according to his work.'
EXEC add_BibleVerse @BibleId, 346003009, N'We are coworkers belonging to God. You are God’s field, God’s building.'
EXEC add_BibleVerse @BibleId, 346003010, N'According to the grace of God given to me, like a skilled master-builder I laid a foundation, but someone else builds on it. And each one must be careful how he builds.'
EXEC add_BibleVerse @BibleId, 346003011, N'For no one can lay any foundation other than what is being laid, which is Jesus Christ.'
EXEC add_BibleVerse @BibleId, 346003012, N'If anyone builds on the foundation with gold, silver, precious stones, wood, hay, or straw,'
EXEC add_BibleVerse @BibleId, 346003013, N'each builder’s work will be plainly seen, for the Day will make it clear, because it will be revealed by fire. And the fire will test what kind of work each has done.'
EXEC add_BibleVerse @BibleId, 346003014, N'If what someone has built survives, he will receive a reward.'
EXEC add_BibleVerse @BibleId, 346003015, N'If someone’s work is burned up, he will suffer loss. He himself will be saved, but only as through fire.'
EXEC add_BibleVerse @BibleId, 346003016, N'Do you not know that you are God’s temple and that God’s Spirit lives in you?'
EXEC add_BibleVerse @BibleId, 346003017, N'If someone destroys God’s temple, God will destroy him. For God’s temple is holy, which is what you are.'
EXEC add_BibleVerse @BibleId, 346003018, N'Guard against self-deception, each of you. If someone among you thinks he is wise in this age, let him become foolish so that he can become wise.'
EXEC add_BibleVerse @BibleId, 346003019, N'For the wisdom of this age is foolishness with God. As it is written, “ He catches the wise in their craftiness.”'
EXEC add_BibleVerse @BibleId, 346003020, N'And again, “ The Lord knows that the thoughts of the wise are futile.”'
EXEC add_BibleVerse @BibleId, 346003021, N'So then, no more boasting about mere mortals! For everything belongs to you,'
EXEC add_BibleVerse @BibleId, 346003022, N'whether Paul or Apollos or Cephas or the world or life or death or the present or the future. Everything belongs to you,'
EXEC add_BibleVerse @BibleId, 346003023, N'and you belong to Christ, and Christ belongs to God.'
EXEC add_BibleVerse @BibleId, 346004001, N'One should think about us this way – as servants of Christ and stewards of the mysteries of God.'
EXEC add_BibleVerse @BibleId, 346004002, N'Now what is sought in stewards is that one be found faithful.'
EXEC add_BibleVerse @BibleId, 346004003, N'So for me, it is a minor matter that I am judged by you or by any human court. In fact, I do not even judge myself.'
EXEC add_BibleVerse @BibleId, 346004004, N'For I am not aware of anything against myself, but I am not acquitted because of this. The one who judges me is the Lord.'
EXEC add_BibleVerse @BibleId, 346004005, N'So then, do not judge anything before the time. Wait until the Lord comes. He will bring to light the hidden things of darkness and reveal the motives of hearts. Then each will receive recognition from God.'
EXEC add_BibleVerse @BibleId, 346004006, N'I have applied these things to myself and Apollos because of you, brothers and sisters, so that through us you may learn “not to go beyond what is written,” so that none of you will be puffed up in favor of the one against the other.'
EXEC add_BibleVerse @BibleId, 346004007, N'For who concedes you any superiority? What do you have that you did not receive? And if you received it, why do you boast as though you did not?'
EXEC add_BibleVerse @BibleId, 346004008, N'Already you are satisfied! Already you are rich! You have become kings without us! I wish you had become kings so that we could reign with you!'
EXEC add_BibleVerse @BibleId, 346004009, N'For, I think, God has exhibited us apostles last of all, as men condemned to die, because we have become a spectacle to the world, both to angels and to people.'
EXEC add_BibleVerse @BibleId, 346004010, N'We are fools for Christ, but you are wise in Christ! We are weak, but you are strong! You are distinguished, we are dishonored!'
EXEC add_BibleVerse @BibleId, 346004011, N'To the present hour we are hungry and thirsty, poorly clothed, brutally treated, and without a roof over our heads.'
EXEC add_BibleVerse @BibleId, 346004012, N'We do hard work, toiling with our own hands. When we are verbally abused, we respond with a blessing, when persecuted, we endure,'
EXEC add_BibleVerse @BibleId, 346004013, N'when people lie about us, we answer in a friendly manner. We are the world’s dirt and scum, even now.'
EXEC add_BibleVerse @BibleId, 346004014, N'I am not writing these things to shame you, but to correct you as my dear children.'
EXEC add_BibleVerse @BibleId, 346004015, N'For though you may have ten thousand guardians in Christ, you do not have many fathers, because I became your father in Christ Jesus through the gospel.'
EXEC add_BibleVerse @BibleId, 346004016, N'I encourage you, then, be imitators of me.'
EXEC add_BibleVerse @BibleId, 346004017, N'For this reason, I have sent Timothy to you, who is my dear and faithful son in the Lord. He will remind you of my ways in Christ, as I teach them everywhere in every church.'
EXEC add_BibleVerse @BibleId, 346004018, N'Some have become arrogant, as if I were not coming to you.'
EXEC add_BibleVerse @BibleId, 346004019, N'But I will come to you soon, if the Lord is willing, and I will find out not only the talk of these arrogant people, but also their power.'
EXEC add_BibleVerse @BibleId, 346004020, N'For the kingdom of God is demonstrated not in idle talk but with power.'
EXEC add_BibleVerse @BibleId, 346004021, N'What do you want? Shall I come to you with a rod of discipline or with love and a spirit of gentleness?'
EXEC add_BibleVerse @BibleId, 346005001, N'It is actually reported that sexual immorality exists among you, the kind of immorality that is not permitted even among the Gentiles, so that someone is cohabiting with his father’s wife.'
EXEC add_BibleVerse @BibleId, 346005002, N'And you are proud! Shouldn’t you have been deeply sorrowful instead and removed the one who did this from among you?'
EXEC add_BibleVerse @BibleId, 346005003, N'For even though I am absent physically, I am present in spirit. And I have already judged the one who did this, just as though I were present.'
EXEC add_BibleVerse @BibleId, 346005004, N'When you gather together in the name of our Lord Jesus, and I am with you in spirit, along with the power of our Lord Jesus,'
EXEC add_BibleVerse @BibleId, 346005005, N'turn this man over to Satan for the destruction of the flesh, so that his spirit may be saved in the day of the Lord.'
EXEC add_BibleVerse @BibleId, 346005006, N'Your boasting is not good. Don’t you know that a little yeast affects the whole batch of dough?'
EXEC add_BibleVerse @BibleId, 346005007, N'Clean out the old yeast so that you may be a new batch of dough – you are, in fact, without yeast. For Christ, our Passover lamb, has been sacrificed.'
EXEC add_BibleVerse @BibleId, 346005008, N'So then, let us celebrate the festival, not with the old yeast, the yeast of vice and evil, but with the bread without yeast, the bread of sincerity and truth.'
EXEC add_BibleVerse @BibleId, 346005009, N'I wrote you in my letter not to associate with sexually immoral people.'
EXEC add_BibleVerse @BibleId, 346005010, N'In no way did I mean the immoral people of this world, or the greedy and swindlers and idolaters, since you would then have to go out of the world.'
EXEC add_BibleVerse @BibleId, 346005011, N'But now I am writing to you not to associate with anyone who calls himself a Christian who is sexually immoral, or greedy, or an idolater, or verbally abusive, or a drunkard, or a swindler. Do not even eat with such a person.'
EXEC add_BibleVerse @BibleId, 346005012, N'For what do I have to do with judging those outside? Are you not to judge those inside?'
EXEC add_BibleVerse @BibleId, 346005013, N'But God will judge those outside. Remove the evil person from among you.'
EXEC add_BibleVerse @BibleId, 346006001, N'When any of you has a legal dispute with another, does he dare go to court before the unrighteous rather than before the saints?'
EXEC add_BibleVerse @BibleId, 346006002, N'Or do you not know that the saints will judge the world? And if the world is to be judged by you, are you not competent to settle trivial suits?'
EXEC add_BibleVerse @BibleId, 346006003, N'Do you not know that we will judge angels? Why not ordinary matters!'
EXEC add_BibleVerse @BibleId, 346006004, N'So if you have ordinary lawsuits, do you appoint as judges those who have no standing in the church?'
EXEC add_BibleVerse @BibleId, 346006005, N'I say this to your shame! Is there no one among you wise enough to settle disputes between fellow Christians?'
EXEC add_BibleVerse @BibleId, 346006006, N'Instead, does a Christian sue a Christian, and do this before unbelievers?'
EXEC add_BibleVerse @BibleId, 346006007, N'The fact that you have lawsuits among yourselves demonstrates that you have already been defeated. Why not rather be wronged? Why not rather be cheated?'
EXEC add_BibleVerse @BibleId, 346006008, N'But you yourselves wrong and cheat, and you do this to your brothers and sisters!'
EXEC add_BibleVerse @BibleId, 346006009, N'Do you not know that the unrighteous will not inherit the kingdom of God? Do not be deceived! The sexually immoral, idolaters, adulterers, passive homosexual partners, practicing homosexuals,'
EXEC add_BibleVerse @BibleId, 346006010, N'thieves, the greedy, drunkards, the verbally abusive, and swindlers will not inherit the kingdom of God.'
EXEC add_BibleVerse @BibleId, 346006011, N'Some of you once lived this way. But you were washed, you were sanctified, you were justified in the name of the Lord Jesus Christ and by the Spirit of our God.'
EXEC add_BibleVerse @BibleId, 346006012, N'“All things are lawful for me” – but not everything is beneficial. “All things are lawful for me” – but I will not be controlled by anything.'
EXEC add_BibleVerse @BibleId, 346006013, N'“Food is for the stomach and the stomach is for food, but God will do away with both.” The body is not for sexual immorality, but for the Lord, and the Lord for the body.'
EXEC add_BibleVerse @BibleId, 346006014, N'Now God indeed raised the Lord and he will raise us by his power.'
EXEC add_BibleVerse @BibleId, 346006015, N'Do you not know that your bodies are members of Christ? Should I take the members of Christ and make them members of a prostitute? Never!'
EXEC add_BibleVerse @BibleId, 346006016, N'Or do you not know that anyone who is united with a prostitute is one body with her? For it is said, “ The two will become one flesh.”'
EXEC add_BibleVerse @BibleId, 346006017, N'But the one united with the Lord is one spirit with him.'
EXEC add_BibleVerse @BibleId, 346006018, N'Flee sexual immorality! “Every sin a person commits is outside of the body” – but the immoral person sins against his own body.'
EXEC add_BibleVerse @BibleId, 346006019, N'Or do you not know that your body is the temple of the Holy Spirit who is in you, whom you have from God, and you are not your own?'
EXEC add_BibleVerse @BibleId, 346006020, N'For you were bought at a price. Therefore glorify God with your body.'
EXEC add_BibleVerse @BibleId, 346007001, N'Now with regard to the issues you wrote about: “It is good for a man not to have sexual relations with a woman.”'
EXEC add_BibleVerse @BibleId, 346007002, N'But because of immoralities, each man should have relations with his own wife and each woman with her own husband.'
EXEC add_BibleVerse @BibleId, 346007003, N'A husband should give to his wife her sexual rights, and likewise a wife to her husband.'
EXEC add_BibleVerse @BibleId, 346007004, N'It is not the wife who has the rights to her own body, but the husband. In the same way, it is not the husband who has the rights to his own body, but the wife.'
EXEC add_BibleVerse @BibleId, 346007005, N'Do not deprive each other, except by mutual agreement for a specified time, so that you may devote yourselves to prayer. Then resume your relationship, so that Satan may not tempt you because of your lack of self-control.'
EXEC add_BibleVerse @BibleId, 346007006, N'I say this as a concession, not as a command.'
EXEC add_BibleVerse @BibleId, 346007007, N'I wish that everyone was as I am. But each has his own gift from God, one this way, another that.'
EXEC add_BibleVerse @BibleId, 346007008, N'To the unmarried and widows I say that it is best for them to remain as I am.'
EXEC add_BibleVerse @BibleId, 346007009, N'But if they do not have self-control, let them get married. For it is better to marry than to burn with sexual desire.'
EXEC add_BibleVerse @BibleId, 346007010, N'To the married I give this command – not I, but the Lord – a wife should not divorce a husband'
EXEC add_BibleVerse @BibleId, 346007011, N'(but if she does, let her remain unmarried, or be reconciled to her husband), and a husband should not divorce his wife.'
EXEC add_BibleVerse @BibleId, 346007012, N'To the rest I say – I, not the Lord – if a brother has a wife who is not a believer and she is happy to live with him, he should not divorce her.'
EXEC add_BibleVerse @BibleId, 346007013, N'And if a woman has a husband who is not a believer and he is happy to live with her, she should not divorce him.'
EXEC add_BibleVerse @BibleId, 346007014, N'For the unbelieving husband is sanctified because of the wife, and the unbelieving wife because of her husband. Otherwise your children are unclean, but now they are holy.'
EXEC add_BibleVerse @BibleId, 346007015, N'But if the unbeliever wants a divorce, let it take place. In these circumstances the brother or sister is not bound. God has called you in peace.'
EXEC add_BibleVerse @BibleId, 346007016, N'For how do you know, wife, whether you will bring your husband to salvation? Or how do you know, husband, whether you will bring your wife to salvation?'
EXEC add_BibleVerse @BibleId, 346007017, N'Nevertheless, as the Lord has assigned to each one, as God has called each person, so must he live. I give this sort of direction in all the churches.'
EXEC add_BibleVerse @BibleId, 346007018, N'Was anyone called after he had been circumcised? He should not try to undo his circumcision. Was anyone called who is uncircumcised? He should not get circumcised.'
EXEC add_BibleVerse @BibleId, 346007019, N'Circumcision is nothing and uncircumcision is nothing. Instead, keeping God’s commandments is what counts.'
EXEC add_BibleVerse @BibleId, 346007020, N'Let each one remain in that situation in life in which he was called.'
EXEC add_BibleVerse @BibleId, 346007021, N'Were you called as a slave? Do not worry about it. But if indeed you are able to be free, make the most of the opportunity.'
EXEC add_BibleVerse @BibleId, 346007022, N'For the one who was called in the Lord as a slave is the Lord’s freedman. In the same way, the one who was called as a free person is Christ’s slave.'
EXEC add_BibleVerse @BibleId, 346007023, N'You were bought with a price. Do not become slaves of men.'
EXEC add_BibleVerse @BibleId, 346007024, N'In whatever situation someone was called, brothers and sisters, let him remain in it with God.'
EXEC add_BibleVerse @BibleId, 346007025, N'With regard to the question about people who have never married, I have no command from the Lord, but I give my opinion as one shown mercy by the Lord to be trustworthy.'
EXEC add_BibleVerse @BibleId, 346007026, N'Because of the impending crisis I think it best for you to remain as you are.'
EXEC add_BibleVerse @BibleId, 346007027, N'The one bound to a wife should not seek divorce. The one released from a wife should not seek marriage.'
EXEC add_BibleVerse @BibleId, 346007028, N'But if you marry, you have not sinned. And if a virgin marries, she has not sinned. But those who marry will face difficult circumstances, and I am trying to spare you such problems.'
EXEC add_BibleVerse @BibleId, 346007029, N'And I say this, brothers and sisters: The time is short. So then those who have wives should be as those who have none,'
EXEC add_BibleVerse @BibleId, 346007030, N'those with tears like those not weeping, those who rejoice like those not rejoicing, those who buy like those without possessions,'
EXEC add_BibleVerse @BibleId, 346007031, N'those who use the world as though they were not using it to the full. For the present shape of this world is passing away.'
EXEC add_BibleVerse @BibleId, 346007032, N'And I want you to be free from concern. An unmarried man is concerned about the things of the Lord, how to please the Lord.'
EXEC add_BibleVerse @BibleId, 346007033, N'But a married man is concerned about the things of the world, how to please his wife,'
EXEC add_BibleVerse @BibleId, 346007034, N'and he is divided. An unmarried woman or a virgin is concerned about the things of the Lord, to be holy both in body and spirit. But a married woman is concerned about the things of the world, how to please her husband.'
EXEC add_BibleVerse @BibleId, 346007035, N'I am saying this for your benefit, not to place a limitation on you, but so that without distraction you may give notable and constant service to the Lord.'
EXEC add_BibleVerse @BibleId, 346007036, N'If anyone thinks he is acting inappropriately toward his virgin, if she is past the bloom of youth and it seems necessary, he should do what he wishes; he does not sin. Let them marry.'
EXEC add_BibleVerse @BibleId, 346007037, N'But the man who is firm in his commitment, and is under no necessity but has control over his will, and has decided in his own mind to keep his own virgin, does well.'
EXEC add_BibleVerse @BibleId, 346007038, N'So then, the one who marries his own virgin does well, but the one who does not, does better.'
EXEC add_BibleVerse @BibleId, 346007039, N'A wife is bound as long as her husband is living. But if her husband dies, she is free to marry anyone she wishes (only someone in the Lord).'
EXEC add_BibleVerse @BibleId, 346007040, N'But in my opinion, she will be happier if she remains as she is – and I think that I too have the Spirit of God!'
EXEC add_BibleVerse @BibleId, 346008001, N'With regard to food sacrificed to idols, we know that “we all have knowledge.” Knowledge puffs up, but love builds up.'
EXEC add_BibleVerse @BibleId, 346008002, N'If someone thinks he knows something, he does not yet know to the degree that he needs to know.'
EXEC add_BibleVerse @BibleId, 346008003, N'But if someone loves God, he is known by God.'
EXEC add_BibleVerse @BibleId, 346008004, N'With regard then to eating food sacrificed to idols, we know that “an idol in this world is nothing,” and that “there is no God but one.”'
EXEC add_BibleVerse @BibleId, 346008005, N'If after all there are so-called gods, whether in heaven or on earth (as there are many gods and many lords),'
EXEC add_BibleVerse @BibleId, 346008006, N'yet for us there is one God, the Father, from whom are all things and for whom we live, and one Lord, Jesus Christ, through whom are all things and through whom we live.'
EXEC add_BibleVerse @BibleId, 346008007, N'But this knowledge is not shared by all. And some, by being accustomed to idols in former times, eat this food as an idol sacrifice, and their conscience, because it is weak, is defiled.'
EXEC add_BibleVerse @BibleId, 346008008, N'Now food will not bring us close to God. We are no worse if we do not eat and no better if we do.'
EXEC add_BibleVerse @BibleId, 346008009, N'But be careful that this liberty of yours does not become a hindrance to the weak.'
EXEC add_BibleVerse @BibleId, 346008010, N'For if someone weak sees you who possess knowledge dining in an idol’s temple, will not his conscience be “strengthened” to eat food offered to idols?'
EXEC add_BibleVerse @BibleId, 346008011, N'So by your knowledge the weak brother or sister, for whom Christ died, is destroyed.'
EXEC add_BibleVerse @BibleId, 346008012, N'If you sin against your brothers or sisters in this way and wound their weak conscience, you sin against Christ.'
EXEC add_BibleVerse @BibleId, 346008013, N'For this reason, if food causes my brother or sister to sin, I will never eat meat again, so that I may not cause one of them to sin.'
EXEC add_BibleVerse @BibleId, 346009001, N'Am I not free? Am I not an apostle? Have I not seen Jesus our Lord? Are you not my work in the Lord?'
EXEC add_BibleVerse @BibleId, 346009002, N'If I am not an apostle to others, at least I am to you, for you are the confirming sign of my apostleship in the Lord.'
EXEC add_BibleVerse @BibleId, 346009003, N'This is my defense to those who examine me.'
EXEC add_BibleVerse @BibleId, 346009004, N'Do we not have the right to financial support?'
EXEC add_BibleVerse @BibleId, 346009005, N'Do we not have the right to the company of a believing wife, like the other apostles and the Lord’s brothers and Cephas?'
EXEC add_BibleVerse @BibleId, 346009006, N'Or do only Barnabas and I lack the right not to work?'
EXEC add_BibleVerse @BibleId, 346009007, N'Who ever serves in the army at his own expense? Who plants a vineyard and does not eat its fruit? Who tends a flock and does not consume its milk?'
EXEC add_BibleVerse @BibleId, 346009008, N'Am I saying these things only on the basis of common sense, or does the law not say this as well?'
EXEC add_BibleVerse @BibleId, 346009009, N'For it is written in the law of Moses, “ Do not muzzle an ox while it is treading out the grain.” God is not concerned here about oxen, is he?'
EXEC add_BibleVerse @BibleId, 346009010, N'Or is he not surely speaking for our benefit? It was written for us, because the one plowing and threshing ought to work in hope of enjoying the harvest.'
EXEC add_BibleVerse @BibleId, 346009011, N'If we sowed spiritual blessings among you, is it too much to reap material things from you?'
EXEC add_BibleVerse @BibleId, 346009012, N'If others receive this right from you, are we not more deserving? But we have not made use of this right. Instead we endure everything so that we may not be a hindrance to the gospel of Christ.'
EXEC add_BibleVerse @BibleId, 346009013, N'Don’t you know that those who serve in the temple eat food from the temple, and those who serve at the altar receive a part of the offerings?'
EXEC add_BibleVerse @BibleId, 346009014, N'In the same way the Lord commanded those who proclaim the gospel to receive their living by the gospel.'
EXEC add_BibleVerse @BibleId, 346009015, N'But I have not used any of these rights. And I am not writing these things so that something will be done for me. In fact, it would be better for me to die than – no one will deprive me of my reason for boasting!'
EXEC add_BibleVerse @BibleId, 346009016, N'For if I preach the gospel, I have no reason for boasting, because I am compelled to do this. Woe to me if I do not preach the gospel!'
EXEC add_BibleVerse @BibleId, 346009017, N'For if I do this voluntarily, I have a reward. But if I do it unwillingly, I am entrusted with a responsibility.'
EXEC add_BibleVerse @BibleId, 346009018, N'What then is my reward? That when I preach the gospel I may offer the gospel free of charge, and so not make full use of my rights in the gospel.'
EXEC add_BibleVerse @BibleId, 346009019, N'For since I am free from all I can make myself a slave to all, in order to gain even more people.'
EXEC add_BibleVerse @BibleId, 346009020, N'To the Jews I became like a Jew to gain the Jews. To those under the law I became like one under the law (though I myself am not under the law) to gain those under the law.'
EXEC add_BibleVerse @BibleId, 346009021, N'To those free from the law I became like one free from the law (though I am not free from God’s law but under the law of Christ) to gain those free from the law.'
EXEC add_BibleVerse @BibleId, 346009022, N'To the weak I became weak in order to gain the weak. I have become all things to all people, so that by all means I may save some.'
EXEC add_BibleVerse @BibleId, 346009023, N'I do all these things because of the gospel, so that I can be a participant in it.'
EXEC add_BibleVerse @BibleId, 346009024, N'Do you not know that all the runners in a stadium compete, but only one receives the prize? So run to win.'
EXEC add_BibleVerse @BibleId, 346009025, N'Each competitor must exercise self-control in everything. They do it to receive a perishable crown, but we an imperishable one.'
EXEC add_BibleVerse @BibleId, 346009026, N'So I do not run uncertainly or box like one who hits only air.'
EXEC add_BibleVerse @BibleId, 346009027, N'Instead I subdue my body and make it my slave, so that after preaching to others I myself will not be disqualified.'
EXEC add_BibleVerse @BibleId, 346010001, N'For I do not want you to be unaware, brothers and sisters, that our fathers were all under the cloud and all passed through the sea,'
EXEC add_BibleVerse @BibleId, 346010002, N'and all were baptized into Moses in the cloud and in the sea,'
EXEC add_BibleVerse @BibleId, 346010003, N'and all ate the same spiritual food,'
EXEC add_BibleVerse @BibleId, 346010004, N'and all drank the same spiritual drink. For they were all drinking from the spiritual rock that followed them, and the rock was Christ.'
EXEC add_BibleVerse @BibleId, 346010005, N'But God was not pleased with most of them, for they were cut down in the wilderness.'
EXEC add_BibleVerse @BibleId, 346010006, N'These things happened as examples for us, so that we will not crave evil things as they did.'
EXEC add_BibleVerse @BibleId, 346010007, N'So do not be idolaters, as some of them were. As it is written, “ The people sat down to eat and drink and rose up to play.”'
EXEC add_BibleVerse @BibleId, 346010008, N'And let us not be immoral, as some of them were, and twenty-three thousand died in a single day.'
EXEC add_BibleVerse @BibleId, 346010009, N'And let us not put Christ to the test, as some of them did, and were destroyed by snakes.'
EXEC add_BibleVerse @BibleId, 346010010, N'And do not complain, as some of them did, and were killed by the destroying angel.'
EXEC add_BibleVerse @BibleId, 346010011, N'These things happened to them as examples and were written for our instruction, on whom the ends of the ages have come.'
EXEC add_BibleVerse @BibleId, 346010012, N'So let the one who thinks he is standing be careful that he does not fall.'
EXEC add_BibleVerse @BibleId, 346010013, N'No trial has overtaken you that is not faced by others. And God is faithful: He will not let you be tried beyond what you are able to bear, but with the trial will also provide a way out so that you may be able to endure it.'
EXEC add_BibleVerse @BibleId, 346010014, N'So then, my dear friends, flee from idolatry.'
EXEC add_BibleVerse @BibleId, 346010015, N'I am speaking to thoughtful people. Consider what I say.'
EXEC add_BibleVerse @BibleId, 346010016, N'Is not the cup of blessing that we bless a sharing in the blood of Christ? Is not the bread that we break a sharing in the body of Christ?'
EXEC add_BibleVerse @BibleId, 346010017, N'Because there is one bread, we who are many are one body, for we all share the one bread.'
EXEC add_BibleVerse @BibleId, 346010018, N'Look at the people of Israel. Are not those who eat the sacrifices partners in the altar?'
EXEC add_BibleVerse @BibleId, 346010019, N'Am I saying that idols or food sacrificed to them amount to anything?'
EXEC add_BibleVerse @BibleId, 346010020, N'No, I mean that what the pagans sacrifice is to demons and not to God. I do not want you to be partners with demons.'
EXEC add_BibleVerse @BibleId, 346010021, N'You cannot drink the cup of the Lord and the cup of demons. You cannot take part in the table of the Lord and the table of demons.'
EXEC add_BibleVerse @BibleId, 346010022, N'Or are we trying to provoke the Lord to jealousy? Are we really stronger than he is?'
EXEC add_BibleVerse @BibleId, 346010023, N'“Everything is lawful,” but not everything is beneficial. “Everything is lawful,” but not everything builds others up.'
EXEC add_BibleVerse @BibleId, 346010024, N'Do not seek your own good, but the good of the other person.'
EXEC add_BibleVerse @BibleId, 346010025, N'Eat anything that is sold in the marketplace without questions of conscience,'
EXEC add_BibleVerse @BibleId, 346010026, N'for the earth and its abundance are the Lord’s.'
EXEC add_BibleVerse @BibleId, 346010027, N'If an unbeliever invites you to dinner and you want to go, eat whatever is served without asking questions of conscience.'
EXEC add_BibleVerse @BibleId, 346010028, N'But if someone says to you, “This is from a sacrifice,” do not eat, because of the one who told you and because of conscience –'
EXEC add_BibleVerse @BibleId, 346010029, N'I do not mean yours but the other person’s. For why is my freedom being judged by another’s conscience?'
EXEC add_BibleVerse @BibleId, 346010030, N'If I partake with thankfulness, why am I blamed for the food that I give thanks for?'
EXEC add_BibleVerse @BibleId, 346010031, N'So whether you eat or drink, or whatever you do, do everything for the glory of God.'
EXEC add_BibleVerse @BibleId, 346010032, N'Do not give offense to Jews or Greeks or to the church of God,'
EXEC add_BibleVerse @BibleId, 346010033, N'just as I also try to please everyone in all things. I do not seek my own benefit, but the benefit of many, so that they may be saved.'
EXEC add_BibleVerse @BibleId, 346011001, N'Be imitators of me, just as I also am of Christ.'
EXEC add_BibleVerse @BibleId, 346011002, N'I praise you because you remember me in everything and maintain the traditions just as I passed them on to you.'
EXEC add_BibleVerse @BibleId, 346011003, N'But I want you to know that Christ is the head of every man, and the man is the head of a woman, and God is the head of Christ.'
EXEC add_BibleVerse @BibleId, 346011004, N'Any man who prays or prophesies with his head covered disgraces his head.'
EXEC add_BibleVerse @BibleId, 346011005, N'But any woman who prays or prophesies with her head uncovered disgraces her head, for it is one and the same thing as having a shaved head.'
EXEC add_BibleVerse @BibleId, 346011006, N'For if a woman will not cover her head, she should cut off her hair. But if it is disgraceful for a woman to have her hair cut off or her head shaved, she should cover her head.'
EXEC add_BibleVerse @BibleId, 346011007, N'For a man should not have his head covered, since he is the image and glory of God. But the woman is the glory of the man.'
EXEC add_BibleVerse @BibleId, 346011008, N'For man did not come from woman, but woman from man.'
EXEC add_BibleVerse @BibleId, 346011009, N'Neither was man created for the sake of woman, but woman for man.'
EXEC add_BibleVerse @BibleId, 346011010, N'For this reason a woman should have a symbol of authority on her head, because of the angels.'
EXEC add_BibleVerse @BibleId, 346011011, N'In any case, in the Lord woman is not independent of man, nor is man independent of woman.'
EXEC add_BibleVerse @BibleId, 346011012, N'For just as woman came from man, so man comes through woman. But all things come from God.'
EXEC add_BibleVerse @BibleId, 346011013, N'Judge for yourselves: Is it proper for a woman to pray to God with her head uncovered?'
EXEC add_BibleVerse @BibleId, 346011014, N'Does not nature itself teach you that if a man has long hair, it is a disgrace for him,'
EXEC add_BibleVerse @BibleId, 346011015, N'but if a woman has long hair, it is her glory? For her hair is given to her for a covering.'
EXEC add_BibleVerse @BibleId, 346011016, N'If anyone intends to quarrel about this, we have no other practice, nor do the churches of God.'
EXEC add_BibleVerse @BibleId, 346011017, N'Now in giving the following instruction I do not praise you, because you come together not for the better but for the worse.'
EXEC add_BibleVerse @BibleId, 346011018, N'For in the first place, when you come together as a church I hear there are divisions among you, and in part I believe it.'
EXEC add_BibleVerse @BibleId, 346011019, N'For there must in fact be divisions among you, so that those of you who are approved may be evident.'
EXEC add_BibleVerse @BibleId, 346011020, N'Now when you come together at the same place, you are not really eating the Lord’s Supper.'
EXEC add_BibleVerse @BibleId, 346011021, N'For when it is time to eat, everyone proceeds with his own supper. One is hungry and another becomes drunk.'
EXEC add_BibleVerse @BibleId, 346011022, N'Do you not have houses so that you can eat and drink? Or are you trying to show contempt for the church of God by shaming those who have nothing? What should I say to you? Should I praise you? I will not praise you for this!'
EXEC add_BibleVerse @BibleId, 346011023, N'For I received from the Lord what I also passed on to you, that the Lord Jesus on the night in which he was betrayed took bread,'
EXEC add_BibleVerse @BibleId, 346011024, N'and after he had given thanks he broke it and said, “This is my body, which is for you. Do this in remembrance of me.”'
EXEC add_BibleVerse @BibleId, 346011025, N'In the same way, he also took the cup after supper, saying, “This cup is the new covenant in my blood. Do this, every time you drink it, in remembrance of me.”'
EXEC add_BibleVerse @BibleId, 346011026, N'For every time you eat this bread and drink the cup, you proclaim the Lord’s death until he comes.'
EXEC add_BibleVerse @BibleId, 346011027, N'For this reason, whoever eats the bread or drinks the cup of the Lord in an unworthy manner will be guilty of the body and blood of the Lord.'
EXEC add_BibleVerse @BibleId, 346011028, N'A person should examine himself first, and in this way let him eat the bread and drink of the cup.'
EXEC add_BibleVerse @BibleId, 346011029, N'For the one who eats and drinks without careful regard for the body eats and drinks judgment against himself.'
EXEC add_BibleVerse @BibleId, 346011030, N'That is why many of you are weak and sick, and quite a few are dead.'
EXEC add_BibleVerse @BibleId, 346011031, N'But if we examined ourselves, we would not be judged.'
EXEC add_BibleVerse @BibleId, 346011032, N'But when we are judged by the Lord, we are disciplined so that we may not be condemned with the world.'
EXEC add_BibleVerse @BibleId, 346011033, N'So then, my brothers and sisters, when you come together to eat, wait for one another.'
EXEC add_BibleVerse @BibleId, 346011034, N'If anyone is hungry, let him eat at home, so that when you assemble it does not lead to judgment. I will give directions about other matters when I come.'
EXEC add_BibleVerse @BibleId, 346012001, N'With regard to spiritual gifts, brothers and sisters, I do not want you to be uninformed.'
EXEC add_BibleVerse @BibleId, 346012002, N'You know that when you were pagans you were often led astray by speechless idols, however you were led.'
EXEC add_BibleVerse @BibleId, 346012003, N'So I want you to understand that no one speaking by the Spirit of God says, “Jesus is cursed,” and no one can say, “Jesus is Lord,” except by the Holy Spirit.'
EXEC add_BibleVerse @BibleId, 346012004, N'Now there are different gifts, but the same Spirit.'
EXEC add_BibleVerse @BibleId, 346012005, N'And there are different ministries, but the same Lord.'
EXEC add_BibleVerse @BibleId, 346012006, N'And there are different results, but the same God who produces all of them in everyone.'
EXEC add_BibleVerse @BibleId, 346012007, N'To each person the manifestation of the Spirit is given for the benefit of all.'
EXEC add_BibleVerse @BibleId, 346012008, N'For one person is given through the Spirit the message of wisdom, and another the message of knowledge according to the same Spirit,'
EXEC add_BibleVerse @BibleId, 346012009, N'to another faith by the same Spirit, and to another gifts of healing by the one Spirit,'
EXEC add_BibleVerse @BibleId, 346012010, N'to another performance of miracles, to another prophecy, and to another discernment of spirits, to another different kinds of tongues, and to another the interpretation of tongues.'
EXEC add_BibleVerse @BibleId, 346012011, N'It is one and the same Spirit, distributing as he decides to each person, who produces all these things.'
EXEC add_BibleVerse @BibleId, 346012012, N'For just as the body is one and yet has many members, and all the members of the body – though many – are one body, so too is Christ.'
EXEC add_BibleVerse @BibleId, 346012013, N'For in one Spirit we were all baptized into one body. Whether Jews or Greeks or slaves or free, we were all made to drink of the one Spirit.'
EXEC add_BibleVerse @BibleId, 346012014, N'For in fact the body is not a single member, but many.'
EXEC add_BibleVerse @BibleId, 346012015, N'If the foot says, “Since I am not a hand, I am not part of the body,” it does not lose its membership in the body because of that.'
EXEC add_BibleVerse @BibleId, 346012016, N'And if the ear says, “Since I am not an eye, I am not part of the body,” it does not lose its membership in the body because of that.'
EXEC add_BibleVerse @BibleId, 346012017, N'If the whole body were an eye, what part would do the hearing? If the whole were an ear, what part would exercise the sense of smell?'
EXEC add_BibleVerse @BibleId, 346012018, N'But as a matter of fact, God has placed each of the members in the body just as he decided.'
EXEC add_BibleVerse @BibleId, 346012019, N'If they were all the same member, where would the body be?'
EXEC add_BibleVerse @BibleId, 346012020, N'So now there are many members, but one body.'
EXEC add_BibleVerse @BibleId, 346012021, N'The eye cannot say to the hand, “I do not need you,” nor in turn can the head say to the foot, “I do not need you.”'
EXEC add_BibleVerse @BibleId, 346012022, N'On the contrary, those members that seem to be weaker are essential,'
EXEC add_BibleVerse @BibleId, 346012023, N'and those members we consider less honorable we clothe with greater honor, and our unpresentable members are clothed with dignity,'
EXEC add_BibleVerse @BibleId, 346012024, N'but our presentable members do not need this. Instead, God has blended together the body, giving greater honor to the lesser member,'
EXEC add_BibleVerse @BibleId, 346012025, N'so that there may be no division in the body, but the members may have mutual concern for one another.'
EXEC add_BibleVerse @BibleId, 346012026, N'If one member suffers, everyone suffers with it. If a member is honored, all rejoice with it.'
EXEC add_BibleVerse @BibleId, 346012027, N'Now you are Christ’s body, and each of you is a member of it.'
EXEC add_BibleVerse @BibleId, 346012028, N'And God has placed in the church first apostles, second prophets, third teachers, then miracles, gifts of healing, helps, gifts of leadership, different kinds of tongues.'
EXEC add_BibleVerse @BibleId, 346012029, N'Not all are apostles, are they? Not all are prophets, are they? Not all are teachers, are they? Not all perform miracles, do they?'
EXEC add_BibleVerse @BibleId, 346012030, N'Not all have gifts of healing, do they? Not all speak in tongues, do they? Not all interpret, do they?'
EXEC add_BibleVerse @BibleId, 346012031, N'But you should be eager for the greater gifts. And now I will show you a way that is beyond comparison.'
EXEC add_BibleVerse @BibleId, 346013001, N'If I speak in the tongues of men and of angels, but I do not have love, I am a noisy gong or a clanging cymbal.'
EXEC add_BibleVerse @BibleId, 346013002, N'And if I have prophecy, and know all mysteries and all knowledge, and if I have all faith so that I can remove mountains, but do not have love, I am nothing.'
EXEC add_BibleVerse @BibleId, 346013003, N'If I give away everything I own, and if I give over my body in order to boast, but do not have love, I receive no benefit.'
EXEC add_BibleVerse @BibleId, 346013004, N'Love is patient, love is kind, it is not envious. Love does not brag, it is not puffed up.'
EXEC add_BibleVerse @BibleId, 346013005, N'It is not rude, it is not self-serving, it is not easily angered or resentful.'
EXEC add_BibleVerse @BibleId, 346013006, N'It is not glad about injustice, but rejoices in the truth.'
EXEC add_BibleVerse @BibleId, 346013007, N'It bears all things, believes all things, hopes all things, endures all things.'
EXEC add_BibleVerse @BibleId, 346013008, N'Love never ends. But if there are prophecies, they will be set aside; if there are tongues, they will cease; if there is knowledge, it will be set aside.'
EXEC add_BibleVerse @BibleId, 346013009, N'For we know in part, and we prophesy in part,'
EXEC add_BibleVerse @BibleId, 346013010, N'but when what is perfect comes, the partial will be set aside.'
EXEC add_BibleVerse @BibleId, 346013011, N'When I was a child, I talked like a child, I thought like a child, I reasoned like a child. But when I became an adult, I set aside childish ways.'
EXEC add_BibleVerse @BibleId, 346013012, N'For now we see in a mirror indirectly, but then we will see face to face. Now I know in part, but then I will know fully, just as I have been fully known.'
EXEC add_BibleVerse @BibleId, 346013013, N'And now these three remain: faith, hope, and love. But the greatest of these is love.'
EXEC add_BibleVerse @BibleId, 346014001, N'Pursue love and be eager for the spiritual gifts, especially that you may prophesy.'
EXEC add_BibleVerse @BibleId, 346014002, N'For the one speaking in a tongue does not speak to people but to God, for no one understands; he is speaking mysteries by the Spirit.'
EXEC add_BibleVerse @BibleId, 346014003, N'But the one who prophesies speaks to people for their strengthening, encouragement, and consolation.'
EXEC add_BibleVerse @BibleId, 346014004, N'The one who speaks in a tongue builds himself up, but the one who prophesies builds up the church.'
EXEC add_BibleVerse @BibleId, 346014005, N'I wish you all spoke in tongues, but even more that you would prophesy. The one who prophesies is greater than the one who speaks in tongues, unless he interprets so that the church may be strengthened.'
EXEC add_BibleVerse @BibleId, 346014006, N'Now, brothers and sisters, if I come to you speaking in tongues, how will I help you unless I speak to you with a revelation or with knowledge or prophecy or teaching?'
EXEC add_BibleVerse @BibleId, 346014007, N'It is similar for lifeless things that make a sound, like a flute or harp. Unless they make a distinction in the notes, how can what is played on the flute or harp be understood?'
EXEC add_BibleVerse @BibleId, 346014008, N'If, for example, the trumpet makes an unclear sound, who will get ready for battle?'
EXEC add_BibleVerse @BibleId, 346014009, N'It is the same for you. If you do not speak clearly with your tongue, how will anyone know what is being said? For you will be speaking into the air.'
EXEC add_BibleVerse @BibleId, 346014010, N'There are probably many kinds of languages in the world, and none is without meaning.'
EXEC add_BibleVerse @BibleId, 346014011, N'If then I do not know the meaning of a language, I will be a foreigner to the speaker and the speaker a foreigner to me.'
EXEC add_BibleVerse @BibleId, 346014012, N'It is the same with you. Since you are eager for manifestations of the Spirit, seek to abound in order to strengthen the church.'
EXEC add_BibleVerse @BibleId, 346014013, N'So then, one who speaks in a tongue should pray that he may interpret.'
EXEC add_BibleVerse @BibleId, 346014014, N'If I pray in a tongue, my spirit prays, but my mind is unproductive.'
EXEC add_BibleVerse @BibleId, 346014015, N'What should I do? I will pray with my spirit, but I will also pray with my mind. I will sing praises with my spirit, but I will also sing praises with my mind.'
EXEC add_BibleVerse @BibleId, 346014016, N'Otherwise, if you are praising God with your spirit, how can someone without the gift say “Amen” to your thanksgiving, since he does not know what you are saying?'
EXEC add_BibleVerse @BibleId, 346014017, N'For you are certainly giving thanks well, but the other person is not strengthened.'
EXEC add_BibleVerse @BibleId, 346014018, N'I thank God that I speak in tongues more than all of you,'
EXEC add_BibleVerse @BibleId, 346014019, N'but in the church I want to speak five words with my mind to instruct others, rather than ten thousand words in a tongue.'
EXEC add_BibleVerse @BibleId, 346014020, N'Brothers and sisters, do not be children in your thinking. Instead, be infants in evil, but in your thinking be mature.'
EXEC add_BibleVerse @BibleId, 346014021, N'It is written in the law: “ By people with strange tongues and by the lips of strangers I will speak to this people, yet not even in this way will they listen to me,” says the Lord.'
EXEC add_BibleVerse @BibleId, 346014022, N'So then, tongues are a sign not for believers but for unbelievers. Prophecy, however, is not for unbelievers but for believers.'
EXEC add_BibleVerse @BibleId, 346014023, N'So if the whole church comes together and all speak in tongues, and unbelievers or uninformed people enter, will they not say that you have lost your minds?'
EXEC add_BibleVerse @BibleId, 346014024, N'But if all prophesy, and an unbeliever or uninformed person enters, he will be convicted by all, he will be called to account by all.'
EXEC add_BibleVerse @BibleId, 346014025, N'The secrets of his heart are disclosed, and in this way he will fall down with his face to the ground and worship God, declaring, “God is really among you.”'
EXEC add_BibleVerse @BibleId, 346014026, N'What should you do then, brothers and sisters? When you come together, each one has a song, has a lesson, has a revelation, has a tongue, has an interpretation. Let all these things be done for the strengthening of the church.'
EXEC add_BibleVerse @BibleId, 346014027, N'If someone speaks in a tongue, it should be two, or at the most three, one after the other, and someone must interpret.'
EXEC add_BibleVerse @BibleId, 346014028, N'But if there is no interpreter, he should be silent in the church. Let him speak to himself and to God.'
EXEC add_BibleVerse @BibleId, 346014029, N'Two or three prophets should speak and the others should evaluate what is said.'
EXEC add_BibleVerse @BibleId, 346014030, N'And if someone sitting down receives a revelation, the person who is speaking should conclude.'
EXEC add_BibleVerse @BibleId, 346014031, N'For you can all prophesy one after another, so all can learn and be encouraged.'
EXEC add_BibleVerse @BibleId, 346014032, N'Indeed, the spirits of the prophets are subject to the prophets,'
EXEC add_BibleVerse @BibleId, 346014033, N'for God is not characterized by disorder but by peace. As in all the churches of the saints,'
EXEC add_BibleVerse @BibleId, 346014034, N'the women should be silent in the churches, for they are not permitted to speak. Rather, let them be in submission, as in fact the law says.'
EXEC add_BibleVerse @BibleId, 346014035, N'If they want to find out about something, they should ask their husbands at home, because it is disgraceful for a woman to speak in church.'
EXEC add_BibleVerse @BibleId, 346014036, N'Did the word of God begin with you, or did it come to you alone?'
EXEC add_BibleVerse @BibleId, 346014037, N'If anyone considers himself a prophet or spiritual person, he should acknowledge that what I write to you is the Lord’s command.'
EXEC add_BibleVerse @BibleId, 346014038, N'If someone does not recognize this, he is not recognized.'
EXEC add_BibleVerse @BibleId, 346014039, N'So then, brothers and sisters, be eager to prophesy, and do not forbid anyone from speaking in tongues.'
EXEC add_BibleVerse @BibleId, 346014040, N'And do everything in a decent and orderly manner.'
EXEC add_BibleVerse @BibleId, 346015001, N'Now I want to make clear for you, brothers and sisters, the gospel that I preached to you, that you received and on which you stand,'
EXEC add_BibleVerse @BibleId, 346015002, N'and by which you are being saved, if you hold firmly to the message I preached to you – unless you believed in vain.'
EXEC add_BibleVerse @BibleId, 346015003, N'For I passed on to you as of first importance what I also received – that Christ died for our sins according to the scriptures,'
EXEC add_BibleVerse @BibleId, 346015004, N'and that he was buried, and that he was raised on the third day according to the scriptures,'
EXEC add_BibleVerse @BibleId, 346015005, N'and that he appeared to Cephas, then to the twelve.'
EXEC add_BibleVerse @BibleId, 346015006, N'Then he appeared to more than five hundred of the brothers and sisters at one time, most of whom are still alive, though some have fallen asleep.'
EXEC add_BibleVerse @BibleId, 346015007, N'Then he appeared to James, then to all the apostles.'
EXEC add_BibleVerse @BibleId, 346015008, N'Last of all, as though to one born at the wrong time, he appeared to me also.'
EXEC add_BibleVerse @BibleId, 346015009, N'For I am the least of the apostles, unworthy to be called an apostle, because I persecuted the church of God.'
EXEC add_BibleVerse @BibleId, 346015010, N'But by the grace of God I am what I am, and his grace to me has not been in vain. In fact, I worked harder than all of them – yet not I, but the grace of God with me.'
EXEC add_BibleVerse @BibleId, 346015011, N'Whether then it was I or they, this is the way we preach and this is the way you believed.'
EXEC add_BibleVerse @BibleId, 346015012, N'Now if Christ is being preached as raised from the dead, how can some of you say there is no resurrection of the dead?'
EXEC add_BibleVerse @BibleId, 346015013, N'But if there is no resurrection of the dead, then not even Christ has been raised.'
EXEC add_BibleVerse @BibleId, 346015014, N'And if Christ has not been raised, then our preaching is futile and your faith is empty.'
EXEC add_BibleVerse @BibleId, 346015015, N'Also, we are found to be false witnesses about God, because we have testified against God that he raised Christ from the dead, when in reality he did not raise him, if indeed the dead are not raised.'
EXEC add_BibleVerse @BibleId, 346015016, N'For if the dead are not raised, then not even Christ has been raised.'
EXEC add_BibleVerse @BibleId, 346015017, N'And if Christ has not been raised, your faith is useless; you are still in your sins.'
EXEC add_BibleVerse @BibleId, 346015018, N'Furthermore, those who have fallen asleep in Christ have also perished.'
EXEC add_BibleVerse @BibleId, 346015019, N'For if only in this life we have hope in Christ, we should be pitied more than anyone.'
EXEC add_BibleVerse @BibleId, 346015020, N'But now Christ has been raised from the dead, the firstfruits of those who have fallen asleep.'
EXEC add_BibleVerse @BibleId, 346015021, N'For since death came through a man, the resurrection of the dead also came through a man.'
EXEC add_BibleVerse @BibleId, 346015022, N'For just as in Adam all die, so also in Christ all will be made alive.'
EXEC add_BibleVerse @BibleId, 346015023, N'But each in his own order: Christ, the firstfruits; then when Christ comes, those who belong to him.'
EXEC add_BibleVerse @BibleId, 346015024, N'Then comes the end, when he hands over the kingdom to God the Father, when he has brought to an end all rule and all authority and power.'
EXEC add_BibleVerse @BibleId, 346015025, N'For he must reign until he has put all his enemies under his feet.'
EXEC add_BibleVerse @BibleId, 346015026, N'The last enemy to be eliminated is death.'
EXEC add_BibleVerse @BibleId, 346015027, N'For he has put everything in subjection under his feet everything in subjection under his feet. But when it says “everything” has been put in subjection, it is clear that this does not include the one who put everything in subjection to him.'
EXEC add_BibleVerse @BibleId, 346015028, N'And when all things are subjected to him, then the Son himself will be subjected to the one who subjected everything to him, so that God may be all in all.'
EXEC add_BibleVerse @BibleId, 346015029, N'Otherwise, what will those do who are baptized for the dead? If the dead are not raised at all, then why are they baptized for them?'
EXEC add_BibleVerse @BibleId, 346015030, N'Why too are we in danger every hour?'
EXEC add_BibleVerse @BibleId, 346015031, N'Every day I am in danger of death! This is as sure as my boasting in you, which I have in Christ Jesus our Lord.'
EXEC add_BibleVerse @BibleId, 346015032, N'If from a human point of view I fought with wild beasts at Ephesus, what did it benefit me? If the dead are not raised, let us eat and drink, for tomorrow we die.'
EXEC add_BibleVerse @BibleId, 346015033, N'Do not be deceived: “Bad company corrupts good morals.”'
EXEC add_BibleVerse @BibleId, 346015034, N'Sober up as you should, and stop sinning! For some have no knowledge of God – I say this to your shame!'
EXEC add_BibleVerse @BibleId, 346015035, N'But someone will say, “How are the dead raised? With what kind of body will they come?”'
EXEC add_BibleVerse @BibleId, 346015036, N'Fool! What you sow will not come to life unless it dies.'
EXEC add_BibleVerse @BibleId, 346015037, N'And what you sow is not the body that is to be, but a bare seed – perhaps of wheat or something else.'
EXEC add_BibleVerse @BibleId, 346015038, N'But God gives it a body just as he planned, and to each of the seeds a body of its own.'
EXEC add_BibleVerse @BibleId, 346015039, N'All flesh is not the same: People have one flesh, animals have another, birds and fish another.'
EXEC add_BibleVerse @BibleId, 346015040, N'And there are heavenly bodies and earthly bodies. The glory of the heavenly body is one sort and the earthly another.'
EXEC add_BibleVerse @BibleId, 346015041, N'There is one glory of the sun, and another glory of the moon and another glory of the stars, for star differs from star in glory.'
EXEC add_BibleVerse @BibleId, 346015042, N'It is the same with the resurrection of the dead. What is sown is perishable, what is raised is imperishable.'
EXEC add_BibleVerse @BibleId, 346015043, N'It is sown in dishonor, it is raised in glory; it is sown in weakness, it is raised in power;'
EXEC add_BibleVerse @BibleId, 346015044, N'it is sown a natural body, it is raised a spiritual body. If there is a natural body, there is also a spiritual body.'
EXEC add_BibleVerse @BibleId, 346015045, N'So also it is written, “ The first man, Adam, became a living person”; the last Adam became a life-giving spirit.'
EXEC add_BibleVerse @BibleId, 346015046, N'However, the spiritual did not come first, but the natural, and then the spiritual.'
EXEC add_BibleVerse @BibleId, 346015047, N'The first man is from the earth, made of dust; the second man is from heaven.'
EXEC add_BibleVerse @BibleId, 346015048, N'Like the one made of dust, so too are those made of dust, and like the one from heaven, so too those who are heavenly.'
EXEC add_BibleVerse @BibleId, 346015049, N'And just as we have borne the image of the man of dust, let us also bear the image of the man of heaven.'
EXEC add_BibleVerse @BibleId, 346015050, N'Now this is what I am saying, brothers and sisters: Flesh and blood cannot inherit the kingdom of God, nor does the perishable inherit the imperishable.'
EXEC add_BibleVerse @BibleId, 346015051, N'Listen, I will tell you a mystery: We will not all sleep, but we will all be changed –'
EXEC add_BibleVerse @BibleId, 346015052, N'in a moment, in the blinking of an eye, at the last trumpet. For the trumpet will sound, and the dead will be raised imperishable, and we will be changed.'
EXEC add_BibleVerse @BibleId, 346015053, N'For this perishable body must put on the imperishable, and this mortal body must put on immortality.'
EXEC add_BibleVerse @BibleId, 346015054, N'Now when this perishable puts on the imperishable, and this mortal puts on immortality, then the saying that is written will happen, “ Death has been swallowed up in victory.”'
EXEC add_BibleVerse @BibleId, 346015055, N'“ Where, O death, is your victory? Where, O death, is your sting?”'
EXEC add_BibleVerse @BibleId, 346015056, N'The sting of death is sin, and the power of sin is the law.'
EXEC add_BibleVerse @BibleId, 346015057, N'But thanks be to God, who gives us the victory through our Lord Jesus Christ!'
EXEC add_BibleVerse @BibleId, 346015058, N'So then, dear brothers and sisters, be firm. Do not be moved! Always be outstanding in the work of the Lord, knowing that your labor is not in vain in the Lord.'
EXEC add_BibleVerse @BibleId, 346016001, N'With regard to the collection for the saints, please follow the directions that I gave to the churches of Galatia:'
EXEC add_BibleVerse @BibleId, 346016002, N'On the first day of the week, each of you should set aside some income and save it to the extent that God has blessed you, so that a collection will not have to be made when I come.'
EXEC add_BibleVerse @BibleId, 346016003, N'Then, when I arrive, I will send those whom you approve with letters of explanation to carry your gift to Jerusalem.'
EXEC add_BibleVerse @BibleId, 346016004, N'And if it seems advisable that I should go also, they will go with me.'
EXEC add_BibleVerse @BibleId, 346016005, N'But I will come to you after I have gone through Macedonia – for I will be going through Macedonia –'
EXEC add_BibleVerse @BibleId, 346016006, N'and perhaps I will stay with you, or even spend the winter, so that you can send me on my journey, wherever I go.'
EXEC add_BibleVerse @BibleId, 346016007, N'For I do not want to see you now in passing, since I hope to spend some time with you, if the Lord allows.'
EXEC add_BibleVerse @BibleId, 346016008, N'But I will stay in Ephesus until Pentecost,'
EXEC add_BibleVerse @BibleId, 346016009, N'because a door of great opportunity stands wide open for me, but there are many opponents.'
EXEC add_BibleVerse @BibleId, 346016010, N'Now if Timothy comes, see that he has nothing to fear among you, for he is doing the Lord’s work, as I am too.'
EXEC add_BibleVerse @BibleId, 346016011, N'So then, let no one treat him with contempt. But send him on his way in peace so that he may come to me. For I am expecting him with the brothers.'
EXEC add_BibleVerse @BibleId, 346016012, N'With regard to our brother Apollos: I strongly encouraged him to visit you with the other brothers, but it was simply not his intention to come now. He will come when he has the opportunity.'
EXEC add_BibleVerse @BibleId, 346016013, N'Stay alert, stand firm in the faith, show courage, be strong.'
EXEC add_BibleVerse @BibleId, 346016014, N'Everything you do should be done in love.'
EXEC add_BibleVerse @BibleId, 346016015, N'Now, brothers and sisters, you know about the household of Stephanus, that as the first converts of Achaia, they devoted themselves to ministry for the saints. I urge you'
EXEC add_BibleVerse @BibleId, 346016016, N'also to submit to people like this, and to everyone who cooperates in the work and labors hard.'
EXEC add_BibleVerse @BibleId, 346016017, N'I was glad about the arrival of Stephanus, Fortunatus, and Achaicus because they have supplied the fellowship with you that I lacked.'
EXEC add_BibleVerse @BibleId, 346016018, N'For they refreshed my spirit and yours. So then, recognize people like this.'
EXEC add_BibleVerse @BibleId, 346016019, N'The churches in the province of Asia send greetings to you. Aquila and Prisca greet you warmly in the Lord, with the church that meets in their house.'
EXEC add_BibleVerse @BibleId, 346016020, N'All the brothers and sisters send greetings. Greet one another with a holy kiss.'
EXEC add_BibleVerse @BibleId, 346016021, N'I, Paul, send this greeting with my own hand.'
EXEC add_BibleVerse @BibleId, 346016022, N'Let anyone who has no love for the Lord be accursed. Our Lord, come!'
EXEC add_BibleVerse @BibleId, 346016023, N'The grace of the Lord Jesus be with you.'
EXEC add_BibleVerse @BibleId, 346016024, N'My love be with all of you in Christ Jesus.'
EXEC add_BibleVerse @BibleId, 347001001, N'From Paul, an apostle of Christ Jesus by the will of God, and Timothy our brother, to the church of God that is in Corinth, with all the saints who are in all Achaia.'
EXEC add_BibleVerse @BibleId, 347001002, N'Grace and peace to you from God our Father and the Lord Jesus Christ!'
EXEC add_BibleVerse @BibleId, 347001003, N'Blessed is the God and Father of our Lord Jesus Christ, the Father of mercies and God of all comfort,'
EXEC add_BibleVerse @BibleId, 347001004, N'who comforts us in all our troubles so that we may be able to comfort those experiencing any trouble with the comfort with which we ourselves are comforted by God.'
EXEC add_BibleVerse @BibleId, 347001005, N'For just as the sufferings of Christ overflow toward us, so also our comfort through Christ overflows to you.'
EXEC add_BibleVerse @BibleId, 347001006, N'But if we are afflicted, it is for your comfort and salvation; if we are comforted, it is for your comfort that you experience in your patient endurance of the same sufferings that we also suffer.'
EXEC add_BibleVerse @BibleId, 347001007, N'And our hope for you is steadfast because we know that as you share in our sufferings, so also you will share in our comfort.'
EXEC add_BibleVerse @BibleId, 347001008, N'For we do not want you to be unaware, brothers and sisters, regarding the affliction that happened to us in the province of Asia, that we were burdened excessively, beyond our strength, so that we despaired even of living.'
EXEC add_BibleVerse @BibleId, 347001009, N'Indeed we felt as if the sentence of death had been passed against us, so that we would not trust in ourselves but in God who raises the dead.'
EXEC add_BibleVerse @BibleId, 347001010, N'He delivered us from so great a risk of death, and he will deliver us. We have set our hope on him that he will deliver us yet again,'
EXEC add_BibleVerse @BibleId, 347001011, N'as you also join in helping us by prayer, so that many people may give thanks to God on our behalf for the gracious gift given to us through the help of many.'
EXEC add_BibleVerse @BibleId, 347001012, N'For our reason for confidence is this: the testimony of our conscience, that with pure motives and sincerity which are from God – not by human wisdom but by the grace of God – we conducted ourselves in the world, and all the more toward you.'
EXEC add_BibleVerse @BibleId, 347001013, N'For we do not write you anything other than what you can read and also understand. But I hope that you will understand completely'
EXEC add_BibleVerse @BibleId, 347001014, N'just as also you have partly understood us, that we are your source of pride just as you also are ours in the day of the Lord Jesus.'
EXEC add_BibleVerse @BibleId, 347001015, N'And with this confidence I intended to come to you first so that you would get a second opportunity to see us,'
EXEC add_BibleVerse @BibleId, 347001016, N'and through your help to go on into Macedonia and then from Macedonia to come back to you and be helped on our way into Judea by you.'
EXEC add_BibleVerse @BibleId, 347001017, N'Therefore when I was planning to do this, I did not do so without thinking about what I was doing, did I? Or do I make my plans according to mere human standards so that I would be saying both “Yes, yes” and “No, no” at the same time?'
EXEC add_BibleVerse @BibleId, 347001018, N'But as God is faithful, our message to you is not “Yes” and “No.”'
EXEC add_BibleVerse @BibleId, 347001019, N'For the Son of God, Jesus Christ, the one who was proclaimed among you by us – by me and Silvanus and Timothy – was not “Yes” and “No,” but it has always been “Yes” in him.'
EXEC add_BibleVerse @BibleId, 347001020, N'For every one of God’s promises are “Yes” in him; therefore also through him the “Amen” is spoken, to the glory we give to God.'
EXEC add_BibleVerse @BibleId, 347001021, N'But it is God who establishes us together with you in Christ and who anointed us,'
EXEC add_BibleVerse @BibleId, 347001022, N'who also sealed us and gave us the Spirit in our hearts as a down payment.'
EXEC add_BibleVerse @BibleId, 347001023, N'Now I appeal to God as my witness, that to spare you I did not come again to Corinth.'
EXEC add_BibleVerse @BibleId, 347001024, N'I do not mean that we rule over your faith, but we are workers with you for your joy, because by faith you stand firm.'
EXEC add_BibleVerse @BibleId, 347002001, N'So I made up my own mind not to pay you another painful visit.'
EXEC add_BibleVerse @BibleId, 347002002, N'For if I make you sad, who would be left to make me glad but the one I caused to be sad?'
EXEC add_BibleVerse @BibleId, 347002003, N'And I wrote this very thing to you, so that when I came I would not have sadness from those who ought to make me rejoice, since I am confident in you all that my joy would be yours.'
EXEC add_BibleVerse @BibleId, 347002004, N'For out of great distress and anguish of heart I wrote to you with many tears, not to make you sad, but to let you know the love that I have especially for you.'
EXEC add_BibleVerse @BibleId, 347002005, N'But if anyone has caused sadness, he has not saddened me alone, but to some extent (not to exaggerate) he has saddened all of you as well.'
EXEC add_BibleVerse @BibleId, 347002006, N'This punishment on such an individual by the majority is enough for him,'
EXEC add_BibleVerse @BibleId, 347002007, N'so that now instead you should rather forgive and comfort him. This will keep him from being overwhelmed by excessive grief to the point of despair.'
EXEC add_BibleVerse @BibleId, 347002008, N'Therefore I urge you to reaffirm your love for him.'
EXEC add_BibleVerse @BibleId, 347002009, N'For this reason also I wrote you: to test you to see if you are obedient in everything.'
EXEC add_BibleVerse @BibleId, 347002010, N'If you forgive anyone for anything, I also forgive him – for indeed what I have forgiven (if I have forgiven anything) I did so for you in the presence of Christ,'
EXEC add_BibleVerse @BibleId, 347002011, N'so that we may not be exploited by Satan (for we are not ignorant of his schemes).'
EXEC add_BibleVerse @BibleId, 347002012, N'Now when I arrived in Troas to proclaim the gospel of Christ, even though the Lord had opened a door of opportunity for me,'
EXEC add_BibleVerse @BibleId, 347002013, N'I had no relief in my spirit, because I did not find my brother Titus there. So I said good-bye to them and set out for Macedonia.'
EXEC add_BibleVerse @BibleId, 347002014, N'But thanks be to God who always leads us in triumphal procession in Christ and who makes known through us the fragrance that consists of the knowledge of him in every place.'
EXEC add_BibleVerse @BibleId, 347002015, N'For we are a sweet aroma of Christ to God among those who are being saved and among those who are perishing –'
EXEC add_BibleVerse @BibleId, 347002016, N'to the latter an odor from death to death, but to the former a fragrance from life to life. And who is adequate for these things?'
EXEC add_BibleVerse @BibleId, 347002017, N'For we are not like so many others, hucksters who peddle the word of God for profit, but we are speaking in Christ before God as persons of sincerity, as persons sent from God.'
EXEC add_BibleVerse @BibleId, 347003001, N'Are we beginning to commend ourselves again? We don’t need letters of recommendation to you or from you as some other people do, do we?'
EXEC add_BibleVerse @BibleId, 347003002, N'You yourselves are our letter, written on our hearts, known and read by everyone,'
EXEC add_BibleVerse @BibleId, 347003003, N'revealing that you are a letter of Christ, delivered by us, written not with ink but by the Spirit of the living God, not on stone tablets but on tablets of human hearts.'
EXEC add_BibleVerse @BibleId, 347003004, N'Now we have such confidence in God through Christ.'
EXEC add_BibleVerse @BibleId, 347003005, N'Not that we are adequate in ourselves to consider anything as if it were coming from ourselves, but our adequacy is from God,'
EXEC add_BibleVerse @BibleId, 347003006, N'who made us adequate to be servants of a new covenant not based on the letter but on the Spirit, for the letter kills, but the Spirit gives life.'
EXEC add_BibleVerse @BibleId, 347003007, N'But if the ministry that produced death – carved in letters on stone tablets – came with glory, so that the Israelites could not keep their eyes fixed on the face of Moses because of the glory of his face (a glory which was made ineffective),'
EXEC add_BibleVerse @BibleId, 347003008, N'how much more glorious will the ministry of the Spirit be?'
EXEC add_BibleVerse @BibleId, 347003009, N'For if there was glory in the ministry that produced condemnation, how much more does the ministry that produces righteousness excel in glory!'
EXEC add_BibleVerse @BibleId, 347003010, N'For indeed, what had been glorious now has no glory because of the tremendously greater glory of what replaced it.'
EXEC add_BibleVerse @BibleId, 347003011, N'For if what was made ineffective came with glory, how much more has what remains come in glory!'
EXEC add_BibleVerse @BibleId, 347003012, N'Therefore, since we have such a hope, we behave with great boldness,'
EXEC add_BibleVerse @BibleId, 347003013, N'and not like Moses who used to put a veil over his face to keep the Israelites from staring at the result of the glory that was made ineffective.'
EXEC add_BibleVerse @BibleId, 347003014, N'But their minds were closed. For to this very day, the same veil remains when they hear the old covenant read. It has not been removed because only in Christ is it taken away.'
EXEC add_BibleVerse @BibleId, 347003015, N'But until this very day whenever Moses is read, a veil lies over their minds,'
EXEC add_BibleVerse @BibleId, 347003016, N'but when one turns to the Lord, the veil is removed.'
EXEC add_BibleVerse @BibleId, 347003017, N'Now the Lord is the Spirit, and where the Spirit of the Lord is present, there is freedom.'
EXEC add_BibleVerse @BibleId, 347003018, N'And we all, with unveiled faces reflecting the glory of the Lord, are being transformed into the same image from one degree of glory to another, which is from the Lord, who is the Spirit.'
EXEC add_BibleVerse @BibleId, 347004001, N'Therefore, since we have this ministry, just as God has shown us mercy, we do not become discouraged.'
EXEC add_BibleVerse @BibleId, 347004002, N'But we have rejected shameful hidden deeds, not behaving with deceptiveness or distorting the word of God, but by open proclamation of the truth we commend ourselves to everyone’s conscience before God.'
EXEC add_BibleVerse @BibleId, 347004003, N'But even if our gospel is veiled, it is veiled only to those who are perishing,'
EXEC add_BibleVerse @BibleId, 347004004, N'among whom the god of this age has blinded the minds of those who do not believe so they would not see the light of the glorious gospel of Christ, who is the image of God.'
EXEC add_BibleVerse @BibleId, 347004005, N'For we do not proclaim ourselves, but Jesus Christ as Lord, and ourselves as your slaves for Jesus’ sake.'
EXEC add_BibleVerse @BibleId, 347004006, N'For God, who said “ Let light shine out of darkness,” is the one who shined in our hearts to give us the light of the glorious knowledge of God in the face of Christ.'
EXEC add_BibleVerse @BibleId, 347004007, N'But we have this treasure in clay jars, so that the extraordinary power belongs to God and does not come from us.'
EXEC add_BibleVerse @BibleId, 347004008, N'We are experiencing trouble on every side, but are not crushed; we are perplexed, but not driven to despair;'
EXEC add_BibleVerse @BibleId, 347004009, N'we are persecuted, but not abandoned; we are knocked down, but not destroyed,'
EXEC add_BibleVerse @BibleId, 347004010, N'always carrying around in our body the death of Jesus, so that the life of Jesus may also be made visible in our body.'
EXEC add_BibleVerse @BibleId, 347004011, N'For we who are alive are constantly being handed over to death for Jesus’ sake, so that the life of Jesus may also be made visible in our mortal body.'
EXEC add_BibleVerse @BibleId, 347004012, N'As a result, death is at work in us, but life is at work in you.'
EXEC add_BibleVerse @BibleId, 347004013, N'But since we have the same spirit of faith as that shown in what has been written, “ I believed; therefore I spoke,” we also believe, therefore we also speak.'
EXEC add_BibleVerse @BibleId, 347004014, N'We do so because we know that the one who raised up Jesus will also raise us up with Jesus and will bring us with you into his presence.'
EXEC add_BibleVerse @BibleId, 347004015, N'For all these things are for your sake, so that the grace that is including more and more people may cause thanksgiving to increase to the glory of God.'
EXEC add_BibleVerse @BibleId, 347004016, N'Therefore we do not despair, but even if our physical body is wearing away, our inner person is being renewed day by day.'
EXEC add_BibleVerse @BibleId, 347004017, N'For our momentary, light suffering is producing for us an eternal weight of glory far beyond all comparison'
EXEC add_BibleVerse @BibleId, 347004018, N'because we are not looking at what can be seen but at what cannot be seen. For what can be seen is temporary, but what cannot be seen is eternal.'
EXEC add_BibleVerse @BibleId, 347005001, N'For we know that if our earthly house, the tent we live in, is dismantled, we have a building from God, a house not built by human hands, that is eternal in the heavens.'
EXEC add_BibleVerse @BibleId, 347005002, N'For in this earthly house we groan, because we desire to put on our heavenly dwelling,'
EXEC add_BibleVerse @BibleId, 347005003, N'if indeed, after we have put on our heavenly house, we will not be found naked.'
EXEC add_BibleVerse @BibleId, 347005004, N'For we groan while we are in this tent, since we are weighed down, because we do not want to be unclothed, but clothed, so that what is mortal may be swallowed up by life.'
EXEC add_BibleVerse @BibleId, 347005005, N'Now the one who prepared us for this very purpose is God, who gave us the Spirit as a down payment.'
EXEC add_BibleVerse @BibleId, 347005006, N'Therefore we are always full of courage, and we know that as long as we are alive here on earth we are absent from the Lord –'
EXEC add_BibleVerse @BibleId, 347005007, N'for we live by faith, not by sight.'
EXEC add_BibleVerse @BibleId, 347005008, N'Thus we are full of courage and would prefer to be away from the body and at home with the Lord.'
EXEC add_BibleVerse @BibleId, 347005009, N'So then whether we are alive or away, we make it our ambition to please him.'
EXEC add_BibleVerse @BibleId, 347005010, N'For we must all appear before the judgment seat of Christ, so that each one may be paid back according to what he has done while in the body, whether good or evil.'
EXEC add_BibleVerse @BibleId, 347005011, N'Therefore, because we know the fear of the Lord, we try to persuade people, but we are well known to God, and I hope we are well known to your consciences too.'
EXEC add_BibleVerse @BibleId, 347005012, N'We are not trying to commend ourselves to you again, but are giving you an opportunity to be proud of us, so that you may be able to answer those who take pride in outward appearance and not in what is in the heart.'
EXEC add_BibleVerse @BibleId, 347005013, N'For if we are out of our minds, it is for God; if we are of sound mind, it is for you.'
EXEC add_BibleVerse @BibleId, 347005014, N'For the love of Christ controls us, since we have concluded this, that Christ died for all; therefore all have died.'
EXEC add_BibleVerse @BibleId, 347005015, N'And he died for all so that those who live should no longer live for themselves but for him who died for them and was raised.'
EXEC add_BibleVerse @BibleId, 347005016, N'So then from now on we acknowledge no one from an outward human point of view. Even though we have known Christ from such a human point of view, now we do not know him in that way any longer.'
EXEC add_BibleVerse @BibleId, 347005017, N'So then, if anyone is in Christ, he is a new creation; what is old has passed away – look, what is new has come!'
EXEC add_BibleVerse @BibleId, 347005018, N'And all these things are from God who reconciled us to himself through Christ, and who has given us the ministry of reconciliation.'
EXEC add_BibleVerse @BibleId, 347005019, N'In other words, in Christ God was reconciling the world to himself, not counting people’s trespasses against them, and he has given us the message of reconciliation.'
EXEC add_BibleVerse @BibleId, 347005020, N'Therefore we are ambassadors for Christ, as though God were making His plea through us. We plead with you on Christ’s behalf, “Be reconciled to God!”'
EXEC add_BibleVerse @BibleId, 347005021, N'God made the one who did not know sin to be sin for us, so that in him we would become the righteousness of God.'
EXEC add_BibleVerse @BibleId, 347006001, N'Now because we are fellow workers, we also urge you not to receive the grace of God in vain.'
EXEC add_BibleVerse @BibleId, 347006002, N'For he says, “ I heard you at the acceptable time, and in the day of salvation I helped you.” Look, now is the acceptable time; look, now is the day of salvation!'
EXEC add_BibleVerse @BibleId, 347006003, N'We do not give anyone an occasion for taking an offense in anything, so that no fault may be found with our ministry.'
EXEC add_BibleVerse @BibleId, 347006004, N'But as God’s servants, we have commended ourselves in every way, with great endurance, in persecutions, in difficulties, in distresses,'
EXEC add_BibleVerse @BibleId, 347006005, N'in beatings, in imprisonments, in riots, in troubles, in sleepless nights, in hunger,'
EXEC add_BibleVerse @BibleId, 347006006, N'by purity, by knowledge, by patience, by benevolence, by the Holy Spirit, by genuine love,'
EXEC add_BibleVerse @BibleId, 347006007, N'by truthful teaching, by the power of God, with weapons of righteousness both for the right hand and for the left,'
EXEC add_BibleVerse @BibleId, 347006008, N'through glory and dishonor, through slander and praise; regarded as impostors, and yet true;'
EXEC add_BibleVerse @BibleId, 347006009, N'as unknown, and yet well-known; as dying and yet – see! – we continue to live; as those who are scourged and yet not executed;'
EXEC add_BibleVerse @BibleId, 347006010, N'as sorrowful, but always rejoicing, as poor, but making many rich, as having nothing, and yet possessing everything.'
EXEC add_BibleVerse @BibleId, 347006011, N'We have spoken freely to you, Corinthians; our heart has been opened wide to you.'
EXEC add_BibleVerse @BibleId, 347006012, N'Our affection for you is not restricted, but you are restricted in your affections for us.'
EXEC add_BibleVerse @BibleId, 347006013, N'Now as a fair exchange – I speak as to my children – open wide your hearts to us also.'
EXEC add_BibleVerse @BibleId, 347006014, N'Do not become partners with those who do not believe, for what partnership is there between righteousness and lawlessness, or what fellowship does light have with darkness?'
EXEC add_BibleVerse @BibleId, 347006015, N'And what agreement does Christ have with Beliar? Or what does a believer share in common with an unbeliever?'
EXEC add_BibleVerse @BibleId, 347006016, N'And what mutual agreement does the temple of God have with idols? For we are the temple of the living God, just as God said, “ I will live in them and will walk among them, and I will be their God, and they will be my people: *.”'
EXEC add_BibleVerse @BibleId, 347006017, N'Therefore “ come out from their midst, and be separate,” says the Lord, “ and touch no unclean thing, and I will welcome you,'
EXEC add_BibleVerse @BibleId, 347006018, N'and I will be a father to you, and you will be my sons and daughters,” says the All-Powerful Lord.'
EXEC add_BibleVerse @BibleId, 347007001, N'Therefore, since we have these promises, dear friends, let us cleanse ourselves from everything that could defile the body and the spirit, and thus accomplish holiness out of reverence for God.'
EXEC add_BibleVerse @BibleId, 347007002, N'Make room for us in your hearts; we have wronged no one, we have ruined no one, we have exploited no one.'
EXEC add_BibleVerse @BibleId, 347007003, N'I do not say this to condemn you, for I told you before that you are in our hearts so that we die together and live together with you.'
EXEC add_BibleVerse @BibleId, 347007004, N'I have great confidence in you; I take great pride on your behalf. I am filled with encouragement; I am overflowing with joy in the midst of all our suffering.'
EXEC add_BibleVerse @BibleId, 347007005, N'For even when we came into Macedonia, our body had no rest at all, but we were troubled in every way – struggles from the outside, fears from within.'
EXEC add_BibleVerse @BibleId, 347007006, N'But God, who encourages the downhearted, encouraged us by the arrival of Titus.'
EXEC add_BibleVerse @BibleId, 347007007, N'We were encouraged not only by his arrival, but also by the encouragement you gave him, as he reported to us your longing, your mourning, your deep concern for me, so that I rejoiced more than ever.'
EXEC add_BibleVerse @BibleId, 347007008, N'For even if I made you sad by my letter, I do not regret having written it (even though I did regret it, for I see that my letter made you sad, though only for a short time).'
EXEC add_BibleVerse @BibleId, 347007009, N'Now I rejoice, not because you were made sad, but because you were made sad to the point of repentance. For you were made sad as God intended, so that you were not harmed in any way by us.'
EXEC add_BibleVerse @BibleId, 347007010, N'For sadness as intended by God produces a repentance that leads to salvation, leaving no regret, but worldly sadness brings about death.'
EXEC add_BibleVerse @BibleId, 347007011, N'For see what this very thing, this sadness as God intended, has produced in you: what eagerness, what defense of yourselves, what indignation, what alarm, what longing, what deep concern, what punishment! In everything you have proved yourselves to be innocent in this matter.'
EXEC add_BibleVerse @BibleId, 347007012, N'So then, even though I wrote to you, it was not on account of the one who did wrong, or on account of the one who was wronged, but to reveal to you your eagerness on our behalf before God.'
EXEC add_BibleVerse @BibleId, 347007013, N'Therefore we have been encouraged. And in addition to our own encouragement, we rejoiced even more at the joy of Titus, because all of you have refreshed his spirit.'
EXEC add_BibleVerse @BibleId, 347007014, N'For if I have boasted to him about anything concerning you, I have not been embarrassed by you, but just as everything we said to you was true, so our boasting to Titus about you has proved true as well.'
EXEC add_BibleVerse @BibleId, 347007015, N'And his affection for you is much greater when he remembers the obedience of you all, how you welcomed him with fear and trembling.'
EXEC add_BibleVerse @BibleId, 347007016, N'I rejoice because in everything I am fully confident in you.'
EXEC add_BibleVerse @BibleId, 347008001, N'Now we make known to you, brothers and sisters, the grace of God given to the churches of Macedonia,'
EXEC add_BibleVerse @BibleId, 347008002, N'that during a severe ordeal of suffering, their abundant joy and their extreme poverty have overflowed in the wealth of their generosity.'
EXEC add_BibleVerse @BibleId, 347008003, N'For I testify, they gave according to their means and beyond their means. They did so voluntarily,'
EXEC add_BibleVerse @BibleId, 347008004, N'begging us with great earnestness for the blessing and fellowship of helping the saints.'
EXEC add_BibleVerse @BibleId, 347008005, N'And they did this not just as we had hoped, but they gave themselves first to the Lord and to us by the will of God.'
EXEC add_BibleVerse @BibleId, 347008006, N'Thus we urged Titus that, just as he had previously begun this work, so also he should complete this act of kindness for you.'
EXEC add_BibleVerse @BibleId, 347008007, N'But as you excel in everything – in faith, in speech, in knowledge, and in all eagerness and in the love from us that is in you – make sure that you excel in this act of kindness too.'
EXEC add_BibleVerse @BibleId, 347008008, N'I am not saying this as a command, but I am testing the genuineness of your love by comparison with the eagerness of others.'
EXEC add_BibleVerse @BibleId, 347008009, N'For you know the grace of our Lord Jesus Christ, that although he was rich, he became poor for your sakes, so that you by his poverty could become rich.'
EXEC add_BibleVerse @BibleId, 347008010, N'So here is my opinion on this matter: It is to your advantage, since you made a good start last year both in your giving and your desire to give,'
EXEC add_BibleVerse @BibleId, 347008011, N'to finish what you started, so that just as you wanted to do it eagerly, you can also complete it according to your means.'
EXEC add_BibleVerse @BibleId, 347008012, N'For if the eagerness is present, the gift itself is acceptable according to whatever one has, not according to what he does not have.'
EXEC add_BibleVerse @BibleId, 347008013, N'For I do not say this so there would be relief for others and suffering for you, but as a matter of equality.'
EXEC add_BibleVerse @BibleId, 347008014, N'At the present time, your abundance will meet their need, so that one day their abundance may also meet your need, and thus there may be equality,'
EXEC add_BibleVerse @BibleId, 347008015, N'as it is written: “ The one who gathered much did not have too much, and the one who gathered little did not have too little.”'
EXEC add_BibleVerse @BibleId, 347008016, N'But thanks be to God who put in the heart of Titus the same devotion I have for you,'
EXEC add_BibleVerse @BibleId, 347008017, N'because he not only accepted our request, but since he was very eager, he is coming to you of his own accord.'
EXEC add_BibleVerse @BibleId, 347008018, N'And we are sending along with him the brother who is praised by all the churches for his work in spreading the gospel.'
EXEC add_BibleVerse @BibleId, 347008019, N'In addition, this brother has also been chosen by the churches as our traveling companion as we administer this generous gift to the glory of the Lord himself and to show our readiness to help.'
EXEC add_BibleVerse @BibleId, 347008020, N'We did this as a precaution so that no one should blame us in regard to this generous gift we are administering.'
EXEC add_BibleVerse @BibleId, 347008021, N'For we are concerned about what is right not only before the Lord but also before men.'
EXEC add_BibleVerse @BibleId, 347008022, N'And we are sending with them our brother whom we have tested many times and found eager in many matters, but who now is much more eager than ever because of the great confidence he has in you.'
EXEC add_BibleVerse @BibleId, 347008023, N'If there is any question about Titus, he is my partner and fellow worker among you; if there is any question about our brothers, they are messengers of the churches, a glory to Christ.'
EXEC add_BibleVerse @BibleId, 347008024, N'Therefore show them openly before the churches the proof of your love and of our pride in you.'
EXEC add_BibleVerse @BibleId, 347009001, N'For it is not necessary for me to write you about this service to the saints,'
EXEC add_BibleVerse @BibleId, 347009002, N'because I know your eagerness to help. I keep boasting to the Macedonians about this eagerness of yours, that Achaia has been ready to give since last year, and your zeal to participate has stirred up most of them.'
EXEC add_BibleVerse @BibleId, 347009003, N'But I am sending these brothers so that our boasting about you may not be empty in this case, so that you may be ready just as I kept telling them.'
EXEC add_BibleVerse @BibleId, 347009004, N'For if any of the Macedonians should come with me and find that you are not ready to give, we would be humiliated (not to mention you) by this confidence we had in you.'
EXEC add_BibleVerse @BibleId, 347009005, N'Therefore I thought it necessary to urge these brothers to go to you in advance and to arrange ahead of time the generous contribution you had promised, so this may be ready as a generous gift and not as something you feel forced to do.'
EXEC add_BibleVerse @BibleId, 347009006, N'My point is this: The person who sows sparingly will also reap sparingly, and the person who sows generously will also reap generously.'
EXEC add_BibleVerse @BibleId, 347009007, N'Each one of you should give just as he has decided in his heart, not reluctantly or under compulsion, because God loves a cheerful giver.'
EXEC add_BibleVerse @BibleId, 347009008, N'And God is able to make all grace overflow to you so that because you have enough of everything in every way at all times, you will overflow in every good work.'
EXEC add_BibleVerse @BibleId, 347009009, N'Just as it is written, “ He has scattered widely, he has given to the poor; his righteousness remains forever.”'
EXEC add_BibleVerse @BibleId, 347009010, N'Now God who provides seed for the sower and bread for food will provide and multiply your supply of seed and will cause the harvest of your righteousness to grow.'
EXEC add_BibleVerse @BibleId, 347009011, N'You will be enriched in every way so that you may be generous on every occasion, which is producing through us thanksgiving to God,'
EXEC add_BibleVerse @BibleId, 347009012, N'because the service of this ministry is not only providing for the needs of the saints but is also overflowing with many thanks to God.'
EXEC add_BibleVerse @BibleId, 347009013, N'Through the evidence of this service they will glorify God because of your obedience to your confession in the gospel of Christ and the generosity of your sharing with them and with everyone.'
EXEC add_BibleVerse @BibleId, 347009014, N'And in their prayers on your behalf they long for you because of the extraordinary grace God has shown to you.'
EXEC add_BibleVerse @BibleId, 347009015, N'Thanks be to God for his indescribable gift!'
EXEC add_BibleVerse @BibleId, 347010001, N'Now I, Paul, appeal to you personally by the meekness and gentleness of Christ (I who am meek when present among you, but am full of courage toward you when away!) –'
EXEC add_BibleVerse @BibleId, 347010002, N'now I ask that when I am present I may not have to be bold with the confidence that (I expect) I will dare to use against some who consider us to be behaving according to human standards.'
EXEC add_BibleVerse @BibleId, 347010003, N'For though we live as human beings, we do not wage war according to human standards,'
EXEC add_BibleVerse @BibleId, 347010004, N'for the weapons of our warfare are not human weapons, but are made powerful by God for tearing down strongholds. We tear down arguments'
EXEC add_BibleVerse @BibleId, 347010005, N'and every arrogant obstacle that is raised up against the knowledge of God, and we take every thought captive to make it obey Christ.'
EXEC add_BibleVerse @BibleId, 347010006, N'We are also ready to punish every act of disobedience, whenever your obedience is complete.'
EXEC add_BibleVerse @BibleId, 347010007, N'You are looking at outward appearances. If anyone is confident that he belongs to Christ, he should reflect on this again: Just as he himself belongs to Christ, so too do we.'
EXEC add_BibleVerse @BibleId, 347010008, N'For if I boast somewhat more about our authority that the Lord gave us for building you up and not for tearing you down, I will not be ashamed of doing so.'
EXEC add_BibleVerse @BibleId, 347010009, N'I do not want to seem as though I am trying to terrify you with my letters,'
EXEC add_BibleVerse @BibleId, 347010010, N'because some say, “His letters are weighty and forceful, but his physical presence is weak and his speech is of no account.”'
EXEC add_BibleVerse @BibleId, 347010011, N'Let such a person consider this: What we say by letters when we are absent, we also are in actions when we are present.'
EXEC add_BibleVerse @BibleId, 347010012, N'For we would not dare to classify or compare ourselves with some of those who recommend themselves. But when they measure themselves by themselves and compare themselves with themselves, they are without understanding.'
EXEC add_BibleVerse @BibleId, 347010013, N'But we will not boast beyond certain limits, but will confine our boasting according to the limits of the work to which God has appointed us, that reaches even as far as you.'
EXEC add_BibleVerse @BibleId, 347010014, N'For we were not overextending ourselves, as though we did not reach as far as you, because we were the first to reach as far as you with the gospel about Christ.'
EXEC add_BibleVerse @BibleId, 347010015, N'Nor do we boast beyond certain limits in the work done by others, but we hope that as your faith continues to grow, our work may be greatly expanded among you according to our limits,'
EXEC add_BibleVerse @BibleId, 347010016, N'so that we may preach the gospel in the regions that lie beyond you, and not boast of work already done in another person’s area.'
EXEC add_BibleVerse @BibleId, 347010017, N'But the one who boasts must boast in the Lord must boast in the Lord.'
EXEC add_BibleVerse @BibleId, 347010018, N'For it is not the person who commends himself who is approved, but the person the Lord commends.'
EXEC add_BibleVerse @BibleId, 347011001, N'I wish that you would be patient with me in a little foolishness, but indeed you are being patient with me!'
EXEC add_BibleVerse @BibleId, 347011002, N'For I am jealous for you with godly jealousy, because I promised you in marriage to one husband, to present you as a pure virgin to Christ.'
EXEC add_BibleVerse @BibleId, 347011003, N'But I am afraid that just as the serpent deceived Eve by his treachery, your minds may be led astray from a sincere and pure devotion to Christ.'
EXEC add_BibleVerse @BibleId, 347011004, N'For if someone comes and proclaims another Jesus different from the one we proclaimed, or if you receive a different spirit than the one you received, or a different gospel than the one you accepted, you put up with it well enough!'
EXEC add_BibleVerse @BibleId, 347011005, N'For I consider myself not at all inferior to those “super-apostles.”'
EXEC add_BibleVerse @BibleId, 347011006, N'And even if I am unskilled in speaking, yet I am certainly not so in knowledge. Indeed, we have made this plain to you in everything in every way.'
EXEC add_BibleVerse @BibleId, 347011007, N'Or did I commit a sin by humbling myself so that you could be exalted, because I proclaimed the gospel of God to you free of charge?'
EXEC add_BibleVerse @BibleId, 347011008, N'I robbed other churches by receiving support from them so that I could serve you!'
EXEC add_BibleVerse @BibleId, 347011009, N'When I was with you and was in need, I was not a burden to anyone, for the brothers who came from Macedonia fully supplied my needs. I kept myself from being a burden to you in any way, and will continue to do so.'
EXEC add_BibleVerse @BibleId, 347011010, N'As the truth of Christ is in me, this boasting of mine will not be stopped in the regions of Achaia.'
EXEC add_BibleVerse @BibleId, 347011011, N'Why? Because I do not love you? God knows I do!'
EXEC add_BibleVerse @BibleId, 347011012, N'And what I am doing I will continue to do, so that I may eliminate any opportunity for those who want a chance to be regarded as our equals in the things they boast about.'
EXEC add_BibleVerse @BibleId, 347011013, N'For such people are false apostles, deceitful workers, disguising themselves as apostles of Christ.'
EXEC add_BibleVerse @BibleId, 347011014, N'And no wonder, for even Satan disguises himself as an angel of light.'
EXEC add_BibleVerse @BibleId, 347011015, N'Therefore it is not surprising his servants also disguise themselves as servants of righteousness, whose end will correspond to their actions.'
EXEC add_BibleVerse @BibleId, 347011016, N'I say again, let no one think that I am a fool. But if you do, then at least accept me as a fool, so that I too may boast a little.'
EXEC add_BibleVerse @BibleId, 347011017, N'What I am saying with this boastful confidence I do not say the way the Lord would. Instead it is, as it were, foolishness.'
EXEC add_BibleVerse @BibleId, 347011018, N'Since many are boasting according to human standards, I too will boast.'
EXEC add_BibleVerse @BibleId, 347011019, N'For since you are so wise, you put up with fools gladly.'
EXEC add_BibleVerse @BibleId, 347011020, N'For you put up with it if someone makes slaves of you, if someone exploits you, if someone takes advantage of you, if someone behaves arrogantly toward you, if someone strikes you in the face.'
EXEC add_BibleVerse @BibleId, 347011021, N'(To my disgrace I must say that we were too weak for that!) But whatever anyone else dares to boast about (I am speaking foolishly), I also dare to boast about the same thing.'
EXEC add_BibleVerse @BibleId, 347011022, N'Are they Hebrews? So am I. Are they Israelites? So am I. Are they descendants of Abraham? So am I.'
EXEC add_BibleVerse @BibleId, 347011023, N'Are they servants of Christ? (I am talking like I am out of my mind!) I am even more so: with much greater labors, with far more imprisonments, with more severe beatings, facing death many times.'
EXEC add_BibleVerse @BibleId, 347011024, N'Five times I received from the Jews forty lashes less one.'
EXEC add_BibleVerse @BibleId, 347011025, N'Three times I was beaten with a rod. Once I received a stoning. Three times I suffered shipwreck. A night and a day I spent adrift in the open sea.'
EXEC add_BibleVerse @BibleId, 347011026, N'I have been on journeys many times, in dangers from rivers, in dangers from robbers, in dangers from my own countrymen, in dangers from Gentiles, in dangers in the city, in dangers in the wilderness, in dangers at sea, in dangers from false brothers,'
EXEC add_BibleVerse @BibleId, 347011027, N'in hard work and toil, through many sleepless nights, in hunger and thirst, many times without food, in cold and without enough clothing.'
EXEC add_BibleVerse @BibleId, 347011028, N'Apart from other things, there is the daily pressure on me of my anxious concern for all the churches.'
EXEC add_BibleVerse @BibleId, 347011029, N'Who is weak, and I am not weak? Who is led into sin, and I do not burn with indignation?'
EXEC add_BibleVerse @BibleId, 347011030, N'If I must boast, I will boast about the things that show my weakness.'
EXEC add_BibleVerse @BibleId, 347011031, N'The God and Father of the Lord Jesus, who is blessed forever, knows I am not lying.'
EXEC add_BibleVerse @BibleId, 347011032, N'In Damascus, the governor under King Aretas was guarding the city of Damascus in order to arrest me,'
EXEC add_BibleVerse @BibleId, 347011033, N'but I was let down in a rope-basket through a window in the city wall, and escaped his hands.'
EXEC add_BibleVerse @BibleId, 347012001, N'It is necessary to go on boasting. Though it is not profitable, I will go on to visions and revelations from the Lord.'
EXEC add_BibleVerse @BibleId, 347012002, N'I know a man in Christ who fourteen years ago (whether in the body or out of the body I do not know, God knows) was caught up to the third heaven.'
EXEC add_BibleVerse @BibleId, 347012003, N'And I know that this man (whether in the body or apart from the body I do not know, God knows)'
EXEC add_BibleVerse @BibleId, 347012004, N'was caught up into paradise and heard things too sacred to be put into words, things that a person is not permitted to speak.'
EXEC add_BibleVerse @BibleId, 347012005, N'On behalf of such an individual I will boast, but on my own behalf I will not boast, except about my weaknesses.'
EXEC add_BibleVerse @BibleId, 347012006, N'For even if I wish to boast, I will not be a fool, for I would be telling the truth, but I refrain from this so that no one may regard me beyond what he sees in me or what he hears from me,'
EXEC add_BibleVerse @BibleId, 347012007, N'even because of the extraordinary character of the revelations. Therefore, so that I would not become arrogant, a thorn in the flesh was given to me, a messenger of Satan to trouble me – so that I would not become arrogant.'
EXEC add_BibleVerse @BibleId, 347012008, N'I asked the Lord three times about this, that it would depart from me.'
EXEC add_BibleVerse @BibleId, 347012009, N'But he said to me, “My grace is enough for you, for my power is made perfect in weakness.” So then, I will boast most gladly about my weaknesses, so that the power of Christ may reside in me.'
EXEC add_BibleVerse @BibleId, 347012010, N'Therefore I am content with weaknesses, with insults, with troubles, with persecutions and difficulties for the sake of Christ, for whenever I am weak, then I am strong.'
EXEC add_BibleVerse @BibleId, 347012011, N'I have become a fool. You yourselves forced me to do it, for I should have been commended by you. For I lack nothing in comparison to those “super-apostles,” even though I am nothing.'
EXEC add_BibleVerse @BibleId, 347012012, N'Indeed, the signs of an apostle were performed among you with great perseverance by signs and wonders and powerful deeds.'
EXEC add_BibleVerse @BibleId, 347012013, N'For how were you treated worse than the other churches, except that I myself was not a burden to you? Forgive me this injustice!'
EXEC add_BibleVerse @BibleId, 347012014, N'Look, for the third time I am ready to come to you, and I will not be a burden to you, because I do not want your possessions, but you. For children should not have to save up for their parents, but parents for their children.'
EXEC add_BibleVerse @BibleId, 347012015, N'Now I will most gladly spend and be spent for your lives! If I love you more, am I to be loved less?'
EXEC add_BibleVerse @BibleId, 347012016, N'But be that as it may, I have not burdened you. Yet because I was a crafty person, I took you in by deceit!'
EXEC add_BibleVerse @BibleId, 347012017, N'I have not taken advantage of you through anyone I have sent to you, have I?'
EXEC add_BibleVerse @BibleId, 347012018, N'I urged Titus to visit you and I sent our brother along with him. Titus did not take advantage of you, did he? Did we not conduct ourselves in the same spirit? Did we not behave in the same way?'
EXEC add_BibleVerse @BibleId, 347012019, N'Have you been thinking all this time that we have been defending ourselves to you? We are speaking in Christ before God, and everything we do, dear friends, is to build you up.'
EXEC add_BibleVerse @BibleId, 347012020, N'For I am afraid that somehow when I come I will not find you what I wish, and you will find me not what you wish. I am afraid that somehow there may be quarreling, jealousy, intense anger, selfish ambition, slander, gossip, arrogance, and disorder.'
EXEC add_BibleVerse @BibleId, 347012021, N'I am afraid that when I come again, my God may humiliate me before you, and I will grieve for many of those who previously sinned and have not repented of the impurity, sexual immorality, and licentiousness that they have practiced.'
EXEC add_BibleVerse @BibleId, 347013001, N'This is the third time I am coming to visit you. By the testimony the testimony of two or three witnesses every matter will be established.'
EXEC add_BibleVerse @BibleId, 347013002, N'I said before when I was present the second time and now, though absent, I say again to those who sinned previously and to all the rest, that if I come again, I will not spare anyone,'
EXEC add_BibleVerse @BibleId, 347013003, N'since you are demanding proof that Christ is speaking through me. He is not weak toward you but is powerful among you.'
EXEC add_BibleVerse @BibleId, 347013004, N'For indeed he was crucified by reason of weakness, but he lives because of God’s power. For we also are weak in him, but we will live together with him, because of God’s power toward you.'
EXEC add_BibleVerse @BibleId, 347013005, N'Put yourselves to the test to see if you are in the faith; examine yourselves! Or do you not recognize regarding yourselves that Jesus Christ is in you – unless, indeed, you fail the test!'
EXEC add_BibleVerse @BibleId, 347013006, N'And I hope that you will realize that we have not failed the test!'
EXEC add_BibleVerse @BibleId, 347013007, N'Now we pray to God that you may not do anything wrong, not so that we may appear to have passed the test, but so that you may do what is right even if we may appear to have failed the test.'
EXEC add_BibleVerse @BibleId, 347013008, N'For we cannot do anything against the truth, but only for the sake of the truth.'
EXEC add_BibleVerse @BibleId, 347013009, N'For we rejoice whenever we are weak, but you are strong. And we pray for this: that you may become fully qualified.'
EXEC add_BibleVerse @BibleId, 347013010, N'Because of this I am writing these things while absent, so that when I arrive I may not have to deal harshly with you by using my authority – the Lord gave it to me for building up, not for tearing down!'
EXEC add_BibleVerse @BibleId, 347013011, N'Finally, brothers and sisters, rejoice, set things right, be encouraged, agree with one another, live in peace, and the God of love and peace will be with you.'
EXEC add_BibleVerse @BibleId, 347013012, N'Greet one another with a holy kiss. All the saints greet you.'
EXEC add_BibleVerse @BibleId, 347013013, N'The grace of the Lord Jesus Christ and the love of God and the fellowship of the Holy Spirit be with you all.'
EXEC add_BibleVerse @BibleId, 348001001, N' From Paul, an apostle (not from men, nor by human agency, but by Jesus Christ and God the Father who raised him from the dead)'
EXEC add_BibleVerse @BibleId, 348001002, N'and all the brothers with me, to the churches of Galatia.'
EXEC add_BibleVerse @BibleId, 348001003, N'Grace and peace to you from God the Father and our Lord Jesus Christ,'
EXEC add_BibleVerse @BibleId, 348001004, N'who gave himself for our sins to rescue us from this present evil age according to the will of our God and Father,'
EXEC add_BibleVerse @BibleId, 348001005, N'to whom be glory forever and ever! Amen.'
EXEC add_BibleVerse @BibleId, 348001006, N'I am astonished that you are so quickly deserting the one who called you by the grace of Christ and are following a different gospel –'
EXEC add_BibleVerse @BibleId, 348001007, N'not that there really is another gospel, but there are some who are disturbing you and wanting to distort the gospel of Christ.'
EXEC add_BibleVerse @BibleId, 348001008, N'But even if we (or an angel from heaven) should preach a gospel contrary to the one we preached to you, let him be condemned to hell!'
EXEC add_BibleVerse @BibleId, 348001009, N'As we have said before, and now I say again, if any one is preaching to you a gospel contrary to what you received, let him be condemned to hell!'
EXEC add_BibleVerse @BibleId, 348001010, N'Am I now trying to gain the approval of people, or of God? Or am I trying to please people? If I were still trying to please people, I would not be a slave of Christ!'
EXEC add_BibleVerse @BibleId, 348001011, N'Now I want you to know, brothers and sisters, that the gospel I preached is not of human origin.'
EXEC add_BibleVerse @BibleId, 348001012, N'For I did not receive it or learn it from any human source; instead I received it by a revelation of Jesus Christ.'
EXEC add_BibleVerse @BibleId, 348001013, N'For you have heard of my former way of life in Judaism, how I was savagely persecuting the church of God and trying to destroy it.'
EXEC add_BibleVerse @BibleId, 348001014, N'I was advancing in Judaism beyond many of my contemporaries in my nation, and was extremely zealous for the traditions of my ancestors.'
EXEC add_BibleVerse @BibleId, 348001015, N'But when the one who set me apart from birth and called me by his grace was pleased'
EXEC add_BibleVerse @BibleId, 348001016, N'to reveal his Son in me so that I could preach him among the Gentiles, I did not go to ask advice from any human being,'
EXEC add_BibleVerse @BibleId, 348001017, N'nor did I go up to Jerusalem to see those who were apostles before me, but right away I departed to Arabia, and then returned to Damascus.'
EXEC add_BibleVerse @BibleId, 348001018, N'Then after three years I went up to Jerusalem to visit Cephas and get information from him, and I stayed with him fifteen days.'
EXEC add_BibleVerse @BibleId, 348001019, N'But I saw none of the other apostles except James the Lord’s brother.'
EXEC add_BibleVerse @BibleId, 348001020, N'I assure you that, before God, I am not lying about what I am writing to you!'
EXEC add_BibleVerse @BibleId, 348001021, N'Afterward I went to the regions of Syria and Cilicia.'
EXEC add_BibleVerse @BibleId, 348001022, N'But I was personally unknown to the churches of Judea that are in Christ.'
EXEC add_BibleVerse @BibleId, 348001023, N'They were only hearing, “The one who once persecuted us is now proclaiming the good news of the faith he once tried to destroy.”'
EXEC add_BibleVerse @BibleId, 348001024, N'So they glorified God because of me.'
EXEC add_BibleVerse @BibleId, 348002001, N'Then after fourteen years I went up to Jerusalem again with Barnabas, taking Titus along too.'
EXEC add_BibleVerse @BibleId, 348002002, N'I went there because of a revelation and presented to them the gospel that I preach among the Gentiles. But I did so only in a private meeting with the influential people, to make sure that I was not running – or had not run – in vain.'
EXEC add_BibleVerse @BibleId, 348002003, N'Yet not even Titus, who was with me, was compelled to be circumcised, although he was a Greek.'
EXEC add_BibleVerse @BibleId, 348002004, N'Now this matter arose because of the false brothers with false pretenses who slipped in unnoticed to spy on our freedom that we have in Christ Jesus, to make us slaves.'
EXEC add_BibleVerse @BibleId, 348002005, N'But we did not surrender to them even for a moment, in order that the truth of the gospel would remain with you.'
EXEC add_BibleVerse @BibleId, 348002006, N'But from those who were influential (whatever they were makes no difference to me; God shows no favoritism between people ) – those influential leaders added nothing to my message.'
EXEC add_BibleVerse @BibleId, 348002007, N'On the contrary, when they saw that I was entrusted with the gospel to the uncircumcised just as Peter was to the circumcised'
EXEC add_BibleVerse @BibleId, 348002008, N'(for he who empowered Peter for his apostleship to the circumcised also empowered me for my apostleship to the Gentiles)'
EXEC add_BibleVerse @BibleId, 348002009, N'and when James, Cephas, and John, who had a reputation as pillars, recognized the grace that had been given to me, they gave to Barnabas and me the right hand of fellowship, agreeing that we would go to the Gentiles and they to the circumcised.'
EXEC add_BibleVerse @BibleId, 348002010, N'They requested only that we remember the poor, the very thing I also was eager to do.'
EXEC add_BibleVerse @BibleId, 348002011, N'But when Cephas came to Antioch, I opposed him to his face, because he had clearly done wrong.'
EXEC add_BibleVerse @BibleId, 348002012, N'Until certain people came from James, he had been eating with the Gentiles. But when they arrived, he stopped doing this and separated himself because he was afraid of those who were pro-circumcision.'
EXEC add_BibleVerse @BibleId, 348002013, N'And the rest of the Jews also joined with him in this hypocrisy, so that even Barnabas was led astray with them by their hypocrisy.'
EXEC add_BibleVerse @BibleId, 348002014, N'But when I saw that they were not behaving consistently with the truth of the gospel, I said to Cephas in front of them all, “If you, although you are a Jew, live like a Gentile and not like a Jew, how can you try to force the Gentiles to live like Jews?”'
EXEC add_BibleVerse @BibleId, 348002015, N'We are Jews by birth and not Gentile sinners,'
EXEC add_BibleVerse @BibleId, 348002016, N'yet we know that no one is justified by the works of the law but by the faithfulness of Jesus Christ. And we have come to believe in Christ Jesus, so that we may be justified by the faithfulness of Christ and not by the works of the law, because by the works of the law no one will be justified.'
EXEC add_BibleVerse @BibleId, 348002017, N'But if while seeking to be justified in Christ we ourselves have also been found to be sinners, is Christ then one who encourages sin? Absolutely not!'
EXEC add_BibleVerse @BibleId, 348002018, N'But if I build up again those things I once destroyed, I demonstrate that I am one who breaks God’s law.'
EXEC add_BibleVerse @BibleId, 348002019, N'For through the law I died to the law so that I may live to God.'
EXEC add_BibleVerse @BibleId, 348002020, N'I have been crucified with Christ, and it is no longer I who live, but Christ lives in me. So the life I now live in the body, I live because of the faithfulness of the Son of God, who loved me and gave himself for me.'
EXEC add_BibleVerse @BibleId, 348002021, N'I do not set aside God’s grace, because if righteousness could come through the law, then Christ died for nothing!'
EXEC add_BibleVerse @BibleId, 348003001, N'You foolish Galatians! Who has cast a spell on you? Before your eyes Jesus Christ was vividly portrayed as crucified!'
EXEC add_BibleVerse @BibleId, 348003002, N'The only thing I want to learn from you is this: Did you receive the Spirit by doing the works of the law or by believing what you heard?'
EXEC add_BibleVerse @BibleId, 348003003, N'Are you so foolish? Although you began with the Spirit, are you now trying to finish by human effort?'
EXEC add_BibleVerse @BibleId, 348003004, N'Have you suffered so many things for nothing? – if indeed it was for nothing.'
EXEC add_BibleVerse @BibleId, 348003005, N'Does God then give you the Spirit and work miracles among you by your doing the works of the law or by your believing what you heard?'
EXEC add_BibleVerse @BibleId, 348003006, N'Just as Abraham believed God, and it was credited to him as righteousness,'
EXEC add_BibleVerse @BibleId, 348003007, N'so then, understand that those who believe are the sons of Abraham.'
EXEC add_BibleVerse @BibleId, 348003008, N'And the scripture, foreseeing that God would justify the Gentiles by faith, proclaimed the gospel to Abraham ahead of time, saying, “ All the nations will be blessed in you*.”'
EXEC add_BibleVerse @BibleId, 348003009, N'So then those who believe are blessed along with Abraham the believer.'
EXEC add_BibleVerse @BibleId, 348003010, N'For all who rely on doing the works of the law are under a curse, because it is written, “ Cursed is everyone who does not keep on doing everything written in the book of the law.”'
EXEC add_BibleVerse @BibleId, 348003011, N'Now it is clear no one is justified before God by the law, because the righteous one will live by faith.'
EXEC add_BibleVerse @BibleId, 348003012, N'But the law is not based on faith, but the one who does the works of the law will live by them.'
EXEC add_BibleVerse @BibleId, 348003013, N'Christ redeemed us from the curse of the law by becoming a curse for us (because it is written, “ Cursed is everyone who hangs on a tree”)'
EXEC add_BibleVerse @BibleId, 348003014, N'in order that in Christ Jesus the blessing of Abraham would come to the Gentiles, so that we could receive the promise of the Spirit by faith.'
EXEC add_BibleVerse @BibleId, 348003015, N'Brothers and sisters, I offer an example from everyday life: When a covenant has been ratified, even though it is only a human contract, no one can set it aside or add anything to it.'
EXEC add_BibleVerse @BibleId, 348003016, N'Now the promises were spoken to Abraham and to his descendant. Scripture does not say, “and to the descendants,” referring to many, but “ and to your descendant,” referring to one, who is Christ.'
EXEC add_BibleVerse @BibleId, 348003017, N'What I am saying is this: The law that came four hundred thirty years later does not cancel a covenant previously ratified by God, so as to invalidate the promise.'
EXEC add_BibleVerse @BibleId, 348003018, N'For if the inheritance is based on the law, it is no longer based on the promise, but God graciously gave it to Abraham through the promise.'
EXEC add_BibleVerse @BibleId, 348003019, N'Why then was the law given? It was added because of transgressions, until the arrival of the descendant to whom the promise had been made. It was administered through angels by an intermediary.'
EXEC add_BibleVerse @BibleId, 348003020, N'Now an intermediary is not for one party alone, but God is one.'
EXEC add_BibleVerse @BibleId, 348003021, N'Is the law therefore opposed to the promises of God? Absolutely not! For if a law had been given that was able to give life, then righteousness would certainly have come by the law.'
EXEC add_BibleVerse @BibleId, 348003022, N'But the scripture imprisoned everything and everyone under sin so that the promise could be given – because of the faithfulness of Jesus Christ – to those who believe.'
EXEC add_BibleVerse @BibleId, 348003023, N'Now before faith came we were held in custody under the law, being kept as prisoners until the coming faith would be revealed.'
EXEC add_BibleVerse @BibleId, 348003024, N'Thus the law had become our guardian until Christ, so that we could be declared righteous by faith.'
EXEC add_BibleVerse @BibleId, 348003025, N'But now that faith has come, we are no longer under a guardian.'
EXEC add_BibleVerse @BibleId, 348003026, N'For in Christ Jesus you are all sons of God through faith.'
EXEC add_BibleVerse @BibleId, 348003027, N'For all of you who were baptized into Christ have clothed yourselves with Christ.'
EXEC add_BibleVerse @BibleId, 348003028, N'There is neither Jew nor Greek, there is neither slave nor free, there is neither male nor female – for all of you are one in Christ Jesus.'
EXEC add_BibleVerse @BibleId, 348003029, N'And if you belong to Christ, then you are Abraham’s descendants, heirs according to the promise.'
EXEC add_BibleVerse @BibleId, 348004001, N'Now I mean that the heir, as long as he is a minor, is no different from a slave, though he is the owner of everything.'
EXEC add_BibleVerse @BibleId, 348004002, N'But he is under guardians and managers until the date set by his father.'
EXEC add_BibleVerse @BibleId, 348004003, N'So also we, when we were minors, were enslaved under the basic forces of the world.'
EXEC add_BibleVerse @BibleId, 348004004, N'But when the appropriate time had come, God sent out his Son, born of a woman, born under the law,'
EXEC add_BibleVerse @BibleId, 348004005, N'to redeem those who were under the law, so that we may be adopted as sons with full rights.'
EXEC add_BibleVerse @BibleId, 348004006, N'And because you are sons, God sent the Spirit of his Son into our hearts, who calls “ Abba! Father!”'
EXEC add_BibleVerse @BibleId, 348004007, N'So you are no longer a slave but a son, and if you are a son, then you are also an heir through God.'
EXEC add_BibleVerse @BibleId, 348004008, N'Formerly when you did not know God, you were enslaved to beings that by nature are not gods at all.'
EXEC add_BibleVerse @BibleId, 348004009, N'But now that you have come to know God (or rather to be known by God), how can you turn back again to the weak and worthless basic forces? Do you want to be enslaved to them all over again?'
EXEC add_BibleVerse @BibleId, 348004010, N'You are observing religious days and months and seasons and years.'
EXEC add_BibleVerse @BibleId, 348004011, N'I fear for you that my work for you may have been in vain.'
EXEC add_BibleVerse @BibleId, 348004012, N'I beg you, brothers and sisters, become like me, because I have become like you. You have done me no wrong!'
EXEC add_BibleVerse @BibleId, 348004013, N'But you know it was because of a physical illness that I first proclaimed the gospel to you,'
EXEC add_BibleVerse @BibleId, 348004014, N'and though my physical condition put you to the test, you did not despise or reject me. Instead, you welcomed me as though I were an angel of God, as though I were Christ Jesus himself!'
EXEC add_BibleVerse @BibleId, 348004015, N'Where then is your sense of happiness now? For I testify about you that if it were possible, you would have pulled out your eyes and given them to me!'
EXEC add_BibleVerse @BibleId, 348004016, N'So then, have I become your enemy by telling you the truth?'
EXEC add_BibleVerse @BibleId, 348004017, N'They court you eagerly, but for no good purpose; they want to exclude you, so that you would seek them eagerly.'
EXEC add_BibleVerse @BibleId, 348004018, N'However, it is good to be sought eagerly for a good purpose at all times, and not only when I am present with you.'
EXEC add_BibleVerse @BibleId, 348004019, N'My children – I am again undergoing birth pains until Christ is formed in you!'
EXEC add_BibleVerse @BibleId, 348004020, N'I wish I could be with you now and change my tone of voice, because I am perplexed about you.'
EXEC add_BibleVerse @BibleId, 348004021, N'Tell me, you who want to be under the law, do you not understand the law?'
EXEC add_BibleVerse @BibleId, 348004022, N'For it is written that Abraham had two sons, one by the slave woman and the other by the free woman.'
EXEC add_BibleVerse @BibleId, 348004023, N'But one, the son by the slave woman, was born by natural descent, while the other, the son by the free woman, was born through the promise.'
EXEC add_BibleVerse @BibleId, 348004024, N'These things may be treated as an allegory, for these women represent two covenants. One is from Mount Sinai bearing children for slavery; this is Hagar.'
EXEC add_BibleVerse @BibleId, 348004025, N'Now Hagar represents Mount Sinai in Arabia and corresponds to the present Jerusalem, for she is in slavery with her children.'
EXEC add_BibleVerse @BibleId, 348004026, N'But the Jerusalem above is free, and she is our mother.'
EXEC add_BibleVerse @BibleId, 348004027, N'For it is written: “ Rejoice, O barren woman who does not bear children; break forth and shout, you who have no birth pains, because the children of the desolate woman are more numerous than those of the woman who has a husband.”'
EXEC add_BibleVerse @BibleId, 348004028, N'But you, brothers and sisters, are children of the promise like Isaac.'
EXEC add_BibleVerse @BibleId, 348004029, N'But just as at that time the one born by natural descent persecuted the one born according to the Spirit, so it is now.'
EXEC add_BibleVerse @BibleId, 348004030, N'But what does the scripture say? “ Throw out the slave woman and her son, for the son of the slave woman will not share the inheritance with the son” of the free woman.'
EXEC add_BibleVerse @BibleId, 348004031, N'Therefore, brothers and sisters, we are not children of the slave woman but of the free woman.'
EXEC add_BibleVerse @BibleId, 348005001, N'For freedom Christ has set us free. Stand firm, then, and do not be subject again to the yoke of slavery.'
EXEC add_BibleVerse @BibleId, 348005002, N'Listen! I, Paul, tell you that if you let yourselves be circumcised, Christ will be of no benefit to you at all!'
EXEC add_BibleVerse @BibleId, 348005003, N'And I testify again to every man who lets himself be circumcised that he is obligated to obey the whole law.'
EXEC add_BibleVerse @BibleId, 348005004, N'You who are trying to be declared righteous by the law have been alienated from Christ; you have fallen away from grace!'
EXEC add_BibleVerse @BibleId, 348005005, N'For through the Spirit, by faith, we wait expectantly for the hope of righteousness.'
EXEC add_BibleVerse @BibleId, 348005006, N'For in Christ Jesus neither circumcision nor uncircumcision carries any weight – the only thing that matters is faith working through love.'
EXEC add_BibleVerse @BibleId, 348005007, N'You were running well; who prevented you from obeying the truth?'
EXEC add_BibleVerse @BibleId, 348005008, N'This persuasion does not come from the one who calls you!'
EXEC add_BibleVerse @BibleId, 348005009, N'A little yeast makes the whole batch of dough rise!'
EXEC add_BibleVerse @BibleId, 348005010, N'I am confident in the Lord that you will accept no other view. But the one who is confusing you will pay the penalty, whoever he may be.'
EXEC add_BibleVerse @BibleId, 348005011, N'Now, brothers and sisters, if I am still preaching circumcision, why am I still being persecuted? In that case the offense of the cross has been removed.'
EXEC add_BibleVerse @BibleId, 348005012, N'I wish those agitators would go so far as to castrate themselves!'
EXEC add_BibleVerse @BibleId, 348005013, N'For you were called to freedom, brothers and sisters; only do not use your freedom as an opportunity to indulge your flesh, but through love serve one another.'
EXEC add_BibleVerse @BibleId, 348005014, N'For the whole law can be summed up in a single commandment, namely, “ You must love your neighbor as yourself.”'
EXEC add_BibleVerse @BibleId, 348005015, N'However, if you continually bite and devour one another, beware that you are not consumed by one another.'
EXEC add_BibleVerse @BibleId, 348005016, N'But I say, live by the Spirit and you will not carry out the desires of the flesh.'
EXEC add_BibleVerse @BibleId, 348005017, N'For the flesh has desires that are opposed to the Spirit, and the Spirit has desires that are opposed to the flesh, for these are in opposition to each other, so that you cannot do what you want.'
EXEC add_BibleVerse @BibleId, 348005018, N'But if you are led by the Spirit, you are not under the law.'
EXEC add_BibleVerse @BibleId, 348005019, N'Now the works of the flesh are obvious: sexual immorality, impurity, depravity,'
EXEC add_BibleVerse @BibleId, 348005020, N'idolatry, sorcery, hostilities, strife, jealousy, outbursts of anger, selfish rivalries, dissensions, factions,'
EXEC add_BibleVerse @BibleId, 348005021, N'envying, murder, drunkenness, carousing, and similar things. I am warning you, as I had warned you before: Those who practice such things will not inherit the kingdom of God!'
EXEC add_BibleVerse @BibleId, 348005022, N'But the fruit of the Spirit is love, joy, peace, patience, kindness, goodness, faithfulness,'
EXEC add_BibleVerse @BibleId, 348005023, N'gentleness, and self-control. Against such things there is no law.'
EXEC add_BibleVerse @BibleId, 348005024, N'Now those who belong to Christ have crucified the flesh with its passions and desires.'
EXEC add_BibleVerse @BibleId, 348005025, N'If we live by the Spirit, let us also behave in accordance with the Spirit.'
EXEC add_BibleVerse @BibleId, 348005026, N'Let us not become conceited, provoking one another, being jealous of one another.'
EXEC add_BibleVerse @BibleId, 348006001, N'Brothers and sisters, if a person is discovered in some sin, you who are spiritual restore such a person in a spirit of gentleness. Pay close attention to yourselves, so that you are not tempted too.'
EXEC add_BibleVerse @BibleId, 348006002, N'Carry one another’s burdens, and in this way you will fulfill the law of Christ.'
EXEC add_BibleVerse @BibleId, 348006003, N'For if anyone thinks he is something when he is nothing, he deceives himself.'
EXEC add_BibleVerse @BibleId, 348006004, N'Let each one examine his own work. Then he can take pride in himself and not compare himself with someone else.'
EXEC add_BibleVerse @BibleId, 348006005, N'For each one will carry his own load.'
EXEC add_BibleVerse @BibleId, 348006006, N'Now the one who receives instruction in the word must share all good things with the one who teaches it.'
EXEC add_BibleVerse @BibleId, 348006007, N'Do not be deceived. God will not be made a fool. For a person will reap what he sows,'
EXEC add_BibleVerse @BibleId, 348006008, N'because the person who sows to his own flesh will reap corruption from the flesh, but the one who sows to the Spirit will reap eternal life from the Spirit.'
EXEC add_BibleVerse @BibleId, 348006009, N'So we must not grow weary in doing good, for in due time we will reap, if we do not give up.'
EXEC add_BibleVerse @BibleId, 348006010, N'So then, whenever we have an opportunity, let us do good to all people, and especially to those who belong to the family of faith.'
EXEC add_BibleVerse @BibleId, 348006011, N'See what big letters I make as I write to you with my own hand!'
EXEC add_BibleVerse @BibleId, 348006012, N'Those who want to make a good showing in external matters are trying to force you to be circumcised. They do so only to avoid being persecuted for the cross of Christ.'
EXEC add_BibleVerse @BibleId, 348006013, N'For those who are circumcised do not obey the law themselves, but they want you to be circumcised so that they can boast about your flesh.'
EXEC add_BibleVerse @BibleId, 348006014, N'But may I never boast except in the cross of our Lord Jesus Christ, through which the world has been crucified to me, and I to the world.'
EXEC add_BibleVerse @BibleId, 348006015, N'For neither circumcision nor uncircumcision counts for anything; the only thing that matters is a new creation!'
EXEC add_BibleVerse @BibleId, 348006016, N'And all who will behave in accordance with this rule, peace and mercy be on them, and on the Israel of God.'
EXEC add_BibleVerse @BibleId, 348006017, N'From now on let no one cause me trouble, for I bear the marks of Jesus on my body.'
EXEC add_BibleVerse @BibleId, 348006018, N'The grace of our Lord Jesus Christ be with your spirit, brothers and sisters. Amen.'
EXEC add_BibleVerse @BibleId, 349001001, N'From Paul, an apostle of Christ Jesus by the will of God, to the saints in Ephesus, the faithful in Christ Jesus.'
EXEC add_BibleVerse @BibleId, 349001002, N'Grace and peace to you from God our Father and the Lord Jesus Christ!'
EXEC add_BibleVerse @BibleId, 349001003, N'Blessed is the God and Father of our Lord Jesus Christ, who has blessed us with every spiritual blessing in the heavenly realms in Christ.'
EXEC add_BibleVerse @BibleId, 349001004, N'For he chose us in Christ before the foundation of the world that we may be holy and unblemished in his sight in love.'
EXEC add_BibleVerse @BibleId, 349001005, N'He did this by predestining us to adoption as his sons through Jesus Christ, according to the pleasure of his will –'
EXEC add_BibleVerse @BibleId, 349001006, N'to the praise of the glory of his grace that he has freely bestowed on us in his dearly loved Son.'
EXEC add_BibleVerse @BibleId, 349001007, N'In him we have redemption through his blood, the forgiveness of our trespasses, according to the riches of his grace'
EXEC add_BibleVerse @BibleId, 349001008, N'that he lavished on us in all wisdom and insight.'
EXEC add_BibleVerse @BibleId, 349001009, N'He did this when he revealed to us the secret of his will, according to his good pleasure that he set forth in Christ,'
EXEC add_BibleVerse @BibleId, 349001010, N'toward the administration of the fullness of the times, to head up all things in Christ – the things in heaven and the things on earth.'
EXEC add_BibleVerse @BibleId, 349001011, N'In Christ we too have been claimed as God’s own possession, since we were predestined according to the one purpose of him who accomplishes all things according to the counsel of his will'
EXEC add_BibleVerse @BibleId, 349001012, N'so that we, who were the first to set our hope on Christ, would be to the praise of his glory.'
EXEC add_BibleVerse @BibleId, 349001013, N'And when you heard the word of truth (the gospel of your salvation) – when you believed in Christ – you were marked with the seal of the promised Holy Spirit,'
EXEC add_BibleVerse @BibleId, 349001014, N'who is the down payment of our inheritance, until the redemption of God’s own possession, to the praise of his glory.'
EXEC add_BibleVerse @BibleId, 349001015, N'For this reason, because I have heard of your faith in the Lord Jesus and your love for all the saints,'
EXEC add_BibleVerse @BibleId, 349001016, N'I do not cease to give thanks for you when I remember you in my prayers.'
EXEC add_BibleVerse @BibleId, 349001017, N'I pray that the God of our Lord Jesus Christ, the Father of glory, may give you spiritual wisdom and revelation in your growing knowledge of him,'
EXEC add_BibleVerse @BibleId, 349001018, N'– since the eyes of your heart have been enlightened – so that you may know what is the hope of his calling, what is the wealth of his glorious inheritance in the saints,'
EXEC add_BibleVerse @BibleId, 349001019, N'and what is the incomparable greatness of his power toward us who believe, as displayed in the exercise of his immense strength.'
EXEC add_BibleVerse @BibleId, 349001020, N'This power he exercised in Christ when he raised him from the dead and seated him at his right hand in the heavenly realms'
EXEC add_BibleVerse @BibleId, 349001021, N'far above every rule and authority and power and dominion and every name that is named, not only in this age but also in the one to come.'
EXEC add_BibleVerse @BibleId, 349001022, N'And God put all things under Christ’s feet, and he gave him to the church as head over all things.'
EXEC add_BibleVerse @BibleId, 349001023, N'Now the church is his body, the fullness of him who fills all in all.'
EXEC add_BibleVerse @BibleId, 349002001, N'And although you were dead in your transgressions and sins,'
EXEC add_BibleVerse @BibleId, 349002002, N'in which you formerly lived according to this world’s present path, according to the ruler of the kingdom of the air, the ruler of the spirit that is now energizing the sons of disobedience,'
EXEC add_BibleVerse @BibleId, 349002003, N'among whom all of us also formerly lived out our lives in the cravings of our flesh, indulging the desires of the flesh and the mind, and were by nature children of wrath even as the rest…'
EXEC add_BibleVerse @BibleId, 349002004, N'But God, being rich in mercy, because of his great love with which he loved us,'
EXEC add_BibleVerse @BibleId, 349002005, N'even though we were dead in transgressions, made us alive together with Christ – by grace you are saved! –'
EXEC add_BibleVerse @BibleId, 349002006, N'and he raised us up with him and seated us with him in the heavenly realms in Christ Jesus,'
EXEC add_BibleVerse @BibleId, 349002007, N'to demonstrate in the coming ages the surpassing wealth of his grace in kindness toward us in Christ Jesus.'
EXEC add_BibleVerse @BibleId, 349002008, N'For by grace you are saved through faith, and this is not from yourselves, it is the gift of God;'
EXEC add_BibleVerse @BibleId, 349002009, N'it is not from works, so that no one can boast.'
EXEC add_BibleVerse @BibleId, 349002010, N'For we are his workmanship, having been created in Christ Jesus for good works that God prepared beforehand so we may do them.'
EXEC add_BibleVerse @BibleId, 349002011, N'Therefore remember that formerly you, the Gentiles in the flesh – who are called “uncircumcision” by the so-called “circumcision” that is performed on the body by human hands –'
EXEC add_BibleVerse @BibleId, 349002012, N'that you were at that time without the Messiah, alienated from the citizenship of Israel and strangers to the covenants of promise, having no hope and without God in the world.'
EXEC add_BibleVerse @BibleId, 349002013, N'But now in Christ Jesus you who used to be far away have been brought near by the blood of Christ.'
EXEC add_BibleVerse @BibleId, 349002014, N'For he is our peace, the one who made both groups into one and who destroyed the middle wall of partition, the hostility,'
EXEC add_BibleVerse @BibleId, 349002015, N'when he nullified in his flesh the law of commandments in decrees. He did this to create in himself one new man out of two, thus making peace,'
EXEC add_BibleVerse @BibleId, 349002016, N'and to reconcile them both in one body to God through the cross, by which the hostility has been killed.'
EXEC add_BibleVerse @BibleId, 349002017, N'And he came and preached peace to you who were far off and peace to those who were near,'
EXEC add_BibleVerse @BibleId, 349002018, N'so that through him we both have access in one Spirit to the Father.'
EXEC add_BibleVerse @BibleId, 349002019, N'So then you are no longer foreigners and noncitizens, but you are fellow citizens with the saints and members of God’s household,'
EXEC add_BibleVerse @BibleId, 349002020, N'because you have been built on the foundation of the apostles and prophets, with Christ Jesus himself as the cornerstone.'
EXEC add_BibleVerse @BibleId, 349002021, N'In him the whole building, being joined together, grows into a holy temple in the Lord,'
EXEC add_BibleVerse @BibleId, 349002022, N'in whom you also are being built together into a dwelling place of God in the Spirit.'
EXEC add_BibleVerse @BibleId, 349003001, N'For this reason I, Paul, the prisoner of Christ Jesus for the sake of you Gentiles –'
EXEC add_BibleVerse @BibleId, 349003002, N'if indeed you have heard of the stewardship of God’s grace that was given to me for you,'
EXEC add_BibleVerse @BibleId, 349003003, N'that by revelation the divine secret was made known to me, as I wrote before briefly.'
EXEC add_BibleVerse @BibleId, 349003004, N'When reading this, you will be able to understand my insight into this secret of Christ.'
EXEC add_BibleVerse @BibleId, 349003005, N'Now this secret was not disclosed to people in former generations as it has now been revealed to his holy apostles and prophets by the Spirit,'
EXEC add_BibleVerse @BibleId, 349003006, N'namely, that through the gospel the Gentiles are fellow heirs, fellow members of the body, and fellow partakers of the promise in Christ Jesus.'
EXEC add_BibleVerse @BibleId, 349003007, N'I became a servant of this gospel according to the gift of God’s grace that was given to me by the exercise of his power.'
EXEC add_BibleVerse @BibleId, 349003008, N'To me – less than the least of all the saints – this grace was given, to proclaim to the Gentiles the unfathomable riches of Christ'
EXEC add_BibleVerse @BibleId, 349003009, N'and to enlighten everyone about God’s secret plan – a secret that has been hidden for ages in God who has created all things.'
EXEC add_BibleVerse @BibleId, 349003010, N'The purpose of this enlightenment is that through the church the multifaceted wisdom of God should now be disclosed to the rulers and the authorities in the heavenly realms.'
EXEC add_BibleVerse @BibleId, 349003011, N'This was according to the eternal purpose that he accomplished in Christ Jesus our Lord,'
EXEC add_BibleVerse @BibleId, 349003012, N'in whom we have boldness and confident access to God because of Christ’s faithfulness.'
EXEC add_BibleVerse @BibleId, 349003013, N'For this reason I ask you not to lose heart because of what I am suffering for you, which is your glory.'
EXEC add_BibleVerse @BibleId, 349003014, N'For this reason I kneel before the Father,'
EXEC add_BibleVerse @BibleId, 349003015, N'from whom every family in heaven and on the earth is named.'
EXEC add_BibleVerse @BibleId, 349003016, N'I pray that according to the wealth of his glory he may grant you to be strengthened with power through his Spirit in the inner person,'
EXEC add_BibleVerse @BibleId, 349003017, N'that Christ may dwell in your hearts through faith, so that, because you have been rooted and grounded in love,'
EXEC add_BibleVerse @BibleId, 349003018, N'you may be able to comprehend with all the saints what is the breadth and length and height and depth,'
EXEC add_BibleVerse @BibleId, 349003019, N'and thus to know the love of Christ that surpasses knowledge, so that you may be filled up to all the fullness of God.'
EXEC add_BibleVerse @BibleId, 349003020, N'Now to him who by the power that is working within us is able to do far beyond all that we ask or think,'
EXEC add_BibleVerse @BibleId, 349003021, N'to him be the glory in the church and in Christ Jesus to all generations, forever and ever. Amen.'
EXEC add_BibleVerse @BibleId, 349004001, N'I, therefore, the prisoner for the Lord, urge you to live worthily of the calling with which you have been called,'
EXEC add_BibleVerse @BibleId, 349004002, N'with all humility and gentleness, with patience, bearing with one another in love,'
EXEC add_BibleVerse @BibleId, 349004003, N'making every effort to keep the unity of the Spirit in the bond of peace.'
EXEC add_BibleVerse @BibleId, 349004004, N'There is one body and one Spirit, just as you too were called to the one hope of your calling,'
EXEC add_BibleVerse @BibleId, 349004005, N'one Lord, one faith, one baptism,'
EXEC add_BibleVerse @BibleId, 349004006, N'one God and Father of all, who is over all and through all and in all.'
EXEC add_BibleVerse @BibleId, 349004007, N'But to each one of us grace was given according to the measure of the gift of Christ.'
EXEC add_BibleVerse @BibleId, 349004008, N'Therefore it says, “ When he ascended on high he captured captives; he gave gifts to men.”'
EXEC add_BibleVerse @BibleId, 349004009, N'Now what is the meaning of “ he ascended,” except that he also descended to the lower regions, namely, the earth?'
EXEC add_BibleVerse @BibleId, 349004010, N'He, the very one who descended, is also the one who ascended above all the heavens, in order to fill all things.'
EXEC add_BibleVerse @BibleId, 349004011, N'It was he who gave some as apostles, some as prophets, some as evangelists, and some as pastors and teachers,'
EXEC add_BibleVerse @BibleId, 349004012, N'to equip the saints for the work of ministry, that is, to build up the body of Christ,'
EXEC add_BibleVerse @BibleId, 349004013, N'until we all attain to the unity of the faith and of the knowledge of the Son of God – a mature person, attaining to the measure of Christ’s full stature.'
EXEC add_BibleVerse @BibleId, 349004014, N'So we are no longer to be children, tossed back and forth by waves and carried about by every wind of teaching by the trickery of people who craftily carry out their deceitful schemes.'
EXEC add_BibleVerse @BibleId, 349004015, N'But practicing the truth in love, we will in all things grow up into Christ, who is the head.'
EXEC add_BibleVerse @BibleId, 349004016, N'From him the whole body grows, fitted and held together through every supporting ligament. As each one does its part, the body grows in love.'
EXEC add_BibleVerse @BibleId, 349004017, N'So I say this, and insist in the Lord, that you no longer live as the Gentiles do, in the futility of their thinking.'
EXEC add_BibleVerse @BibleId, 349004018, N'They are darkened in their understanding, being alienated from the life of God because of the ignorance that is in them due to the hardness of their hearts.'
EXEC add_BibleVerse @BibleId, 349004019, N'Because they are callous, they have given themselves over to indecency for the practice of every kind of impurity with greediness.'
EXEC add_BibleVerse @BibleId, 349004020, N'But you did not learn about Christ like this,'
EXEC add_BibleVerse @BibleId, 349004021, N'if indeed you heard about him and were taught in him, just as the truth is in Jesus.'
EXEC add_BibleVerse @BibleId, 349004022, N'You were taught with reference to your former way of life to lay aside the old man who is being corrupted in accordance with deceitful desires,'
EXEC add_BibleVerse @BibleId, 349004023, N'to be renewed in the spirit of your mind,'
EXEC add_BibleVerse @BibleId, 349004024, N'and to put on the new man who has been created in God’s image – in righteousness and holiness that comes from truth.'
EXEC add_BibleVerse @BibleId, 349004025, N'Therefore, having laid aside falsehood , each one of you speak the truth with his neighbor, for we are members of one another.'
EXEC add_BibleVerse @BibleId, 349004026, N'Be angry and do not sin; do not let the sun go down on the cause of your anger.'
EXEC add_BibleVerse @BibleId, 349004027, N'Do not give the devil an opportunity.'
EXEC add_BibleVerse @BibleId, 349004028, N'The one who steals must steal no longer; rather he must labor, doing good with his own hands, so that he may have something to share with the one who has need.'
EXEC add_BibleVerse @BibleId, 349004029, N'You must let no unwholesome word come out of your mouth, but only what is beneficial for the building up of the one in need, that it may give grace to those who hear.'
EXEC add_BibleVerse @BibleId, 349004030, N'And do not grieve the Holy Spirit of God, by whom you were sealed for the day of redemption.'
EXEC add_BibleVerse @BibleId, 349004031, N'You must put away every kind of bitterness, anger, wrath, quarreling, and evil, slanderous talk.'
EXEC add_BibleVerse @BibleId, 349004032, N'Instead, be kind to one another, compassionate, forgiving one another, just as God in Christ also forgave you.'
EXEC add_BibleVerse @BibleId, 349005001, N'Therefore, be imitators of God as dearly loved children'
EXEC add_BibleVerse @BibleId, 349005002, N'and live in love, just as Christ also loved us and gave himself for us, a sacrificial and fragrant offering to God.'
EXEC add_BibleVerse @BibleId, 349005003, N'But among you there must not be either sexual immorality, impurity of any kind, or greed, as these are not fitting for the saints.'
EXEC add_BibleVerse @BibleId, 349005004, N'Neither should there be vulgar speech, foolish talk, or coarse jesting – all of which are out of character – but rather thanksgiving.'
EXEC add_BibleVerse @BibleId, 349005005, N'For you can be confident of this one thing: that no person who is immoral, impure, or greedy (such a person is an idolater) has any inheritance in the kingdom of Christ and God.'
EXEC add_BibleVerse @BibleId, 349005006, N'Let nobody deceive you with empty words, for because of these things God’s wrath comes on the sons of disobedience.'
EXEC add_BibleVerse @BibleId, 349005007, N'Therefore do not be partakers with them,'
EXEC add_BibleVerse @BibleId, 349005008, N'for you were at one time darkness, but now you are light in the Lord. Walk as children of the light –'
EXEC add_BibleVerse @BibleId, 349005009, N'for the fruit of the light consists in all goodness, righteousness, and truth –'
EXEC add_BibleVerse @BibleId, 349005010, N'trying to learn what is pleasing to the Lord.'
EXEC add_BibleVerse @BibleId, 349005011, N'Do not participate in the unfruitful deeds of darkness, but rather expose them.'
EXEC add_BibleVerse @BibleId, 349005012, N'For the things they do in secret are shameful even to mention.'
EXEC add_BibleVerse @BibleId, 349005013, N'But all things being exposed by the light are made evident.'
EXEC add_BibleVerse @BibleId, 349005014, N'For everything made evident is light, and for this reason it says: “Awake, O sleeper! Rise from the dead, and Christ will shine on you!”'
EXEC add_BibleVerse @BibleId, 349005015, N'Therefore be very careful how you live – not as unwise but as wise,'
EXEC add_BibleVerse @BibleId, 349005016, N'taking advantage of every opportunity, because the days are evil.'
EXEC add_BibleVerse @BibleId, 349005017, N'For this reason do not be foolish, but be wise by understanding what the Lord’s will is.'
EXEC add_BibleVerse @BibleId, 349005018, N'And do not get drunk with wine, which is debauchery, but be filled by the Spirit,'
EXEC add_BibleVerse @BibleId, 349005019, N'speaking to one another in psalms, hymns, and spiritual songs, singing and making music in your hearts to the Lord,'
EXEC add_BibleVerse @BibleId, 349005020, N'always giving thanks to God the Father for each other in the name of our Lord Jesus Christ,'
EXEC add_BibleVerse @BibleId, 349005021, N'and submitting to one another out of reverence for Christ.'
EXEC add_BibleVerse @BibleId, 349005022, N'Wives, submit to your husbands as to the Lord,'
EXEC add_BibleVerse @BibleId, 349005023, N'because the husband is the head of the wife as also Christ is the head of the church – he himself being the savior of the body.'
EXEC add_BibleVerse @BibleId, 349005024, N'But as the church submits to Christ, so also wives should submit to their husbands in everything.'
EXEC add_BibleVerse @BibleId, 349005025, N'Husbands, love your wives just as Christ loved the church and gave himself for her'
EXEC add_BibleVerse @BibleId, 349005026, N'to sanctify her by cleansing her with the washing of the water by the word,'
EXEC add_BibleVerse @BibleId, 349005027, N'so that he may present the church to himself as glorious – not having a stain or wrinkle, or any such blemish, but holy and blameless.'
EXEC add_BibleVerse @BibleId, 349005028, N'In the same way husbands ought to love their wives as their own bodies. He who loves his wife loves himself.'
EXEC add_BibleVerse @BibleId, 349005029, N'For no one has ever hated his own body but he feeds it and takes care of it, just as Christ also does the church,'
EXEC add_BibleVerse @BibleId, 349005030, N'for we are members of his body.'
EXEC add_BibleVerse @BibleId, 349005031, N'For this reason a man will leave his father and mother and will be joined to his wife, and the two will become one flesh.'
EXEC add_BibleVerse @BibleId, 349005032, N'This mystery is great – but I am actually speaking with reference to Christ and the church.'
EXEC add_BibleVerse @BibleId, 349005033, N'Nevertheless, each one of you must also love his own wife as he loves himself, and the wife must respect her husband.'
EXEC add_BibleVerse @BibleId, 349006001, N'Children, obey your parents in the Lord for this is right.'
EXEC add_BibleVerse @BibleId, 349006002, N'“ Honor your father and mother,,*” which is the first commandment accompanied by a promise, namely,'
EXEC add_BibleVerse @BibleId, 349006003, N'“ that it may go well with you and that you will live a long time on the earth.”'
EXEC add_BibleVerse @BibleId, 349006004, N'Fathers, do not provoke your children to anger, but raise them up in the discipline and instruction of the Lord.'
EXEC add_BibleVerse @BibleId, 349006005, N'Slaves, obey your human masters with fear and trembling, in the sincerity of your heart as to Christ,'
EXEC add_BibleVerse @BibleId, 349006006, N'not like those who do their work only when someone is watching – as people-pleasers – but as slaves of Christ doing the will of God from the heart.'
EXEC add_BibleVerse @BibleId, 349006007, N'Obey with enthusiasm, as though serving the Lord and not people,'
EXEC add_BibleVerse @BibleId, 349006008, N'because you know that each person, whether slave or free, if he does something good, this will be rewarded by the Lord.'
EXEC add_BibleVerse @BibleId, 349006009, N'Masters, treat your slaves the same way, giving up the use of threats, because you know that both you and they have the same master in heaven, and there is no favoritism with him.'
EXEC add_BibleVerse @BibleId, 349006010, N'Finally, be strengthened in the Lord and in the strength of his power.'
EXEC add_BibleVerse @BibleId, 349006011, N'Clothe yourselves with the full armor of God so that you may be able to stand against the schemes of the devil.'
EXEC add_BibleVerse @BibleId, 349006012, N'For our struggle is not against flesh and blood, but against the rulers, against the powers, against the world rulers of this darkness, against the spiritual forces of evil in the heavens.'
EXEC add_BibleVerse @BibleId, 349006013, N'For this reason, take up the full armor of God so that you may be able to stand your ground on the evil day, and having done everything, to stand.'
EXEC add_BibleVerse @BibleId, 349006014, N'Stand firm therefore, by fastening the belt of truth around your waist, by putting on the breastplate of righteousness,'
EXEC add_BibleVerse @BibleId, 349006015, N'by fitting your feet with the preparation that comes from the good news of peace,'
EXEC add_BibleVerse @BibleId, 349006016, N'and in all of this, by taking up the shield of faith with which you can extinguish all the flaming arrows of the evil one.'
EXEC add_BibleVerse @BibleId, 349006017, N'And take the helmet of salvation and the sword of the Spirit, which is the word of God.'
EXEC add_BibleVerse @BibleId, 349006018, N'With every prayer and petition, pray at all times in the Spirit, and to this end be alert, with all perseverance and requests for all the saints.'
EXEC add_BibleVerse @BibleId, 349006019, N'Pray for me also, that I may be given the message when I begin to speak – that I may confidently make known the mystery of the gospel,'
EXEC add_BibleVerse @BibleId, 349006020, N'for which I am an ambassador in chains. Pray that I may be able to speak boldly as I ought to speak.'
EXEC add_BibleVerse @BibleId, 349006021, N'Tychicus, my dear brother and faithful servant in the Lord, will make everything known to you, so that you too may know about my circumstances, how I am doing.'
EXEC add_BibleVerse @BibleId, 349006022, N'I have sent him to you for this very purpose, that you may know our circumstances and that he may encourage your hearts.'
EXEC add_BibleVerse @BibleId, 349006023, N'Peace to the brothers and sisters, and love with faith, from God the Father and the Lord Jesus Christ.'
EXEC add_BibleVerse @BibleId, 349006024, N'Grace be with all of those who love our Lord Jesus Christ with an undying love.'
EXEC add_BibleVerse @BibleId, 350001001, N'From Paul and Timothy, slaves of Christ Jesus, to all the saints in Christ Jesus who are in Philippi, with the overseers and deacons.'
EXEC add_BibleVerse @BibleId, 350001002, N'Grace and peace to you from God our Father and the Lord Jesus Christ!'
EXEC add_BibleVerse @BibleId, 350001003, N'I thank my God every time I remember you.'
EXEC add_BibleVerse @BibleId, 350001004, N'I always pray with joy in my every prayer for all of you'
EXEC add_BibleVerse @BibleId, 350001005, N'because of your participation in the gospel from the first day until now.'
EXEC add_BibleVerse @BibleId, 350001006, N'For I am sure of this very thing, that the one who began a good work in you will perfect it until the day of Christ Jesus.'
EXEC add_BibleVerse @BibleId, 350001007, N'For it is right for me to think this about all of you, because I have you in my heart, since both in my imprisonment and in the defense and confirmation of the gospel all of you became partners in God’s grace together with me.'
EXEC add_BibleVerse @BibleId, 350001008, N'For God is my witness that I long for all of you with the affection of Christ Jesus.'
EXEC add_BibleVerse @BibleId, 350001009, N'And I pray this, that your love may abound even more and more in knowledge and every kind of insight'
EXEC add_BibleVerse @BibleId, 350001010, N'so that you can decide what is best, and thus be sincere and blameless for the day of Christ,'
EXEC add_BibleVerse @BibleId, 350001011, N'filled with the fruit of righteousness that comes through Jesus Christ to the glory and praise of God.'
EXEC add_BibleVerse @BibleId, 350001012, N'I want you to know, brothers and sisters, that my situation has actually turned out to advance the gospel:'
EXEC add_BibleVerse @BibleId, 350001013, N'The whole imperial guard and everyone else knows that I am in prison for the sake of Christ,'
EXEC add_BibleVerse @BibleId, 350001014, N'and most of the brothers and sisters, having confidence in the Lord because of my imprisonment, now more than ever dare to speak the word fearlessly.'
EXEC add_BibleVerse @BibleId, 350001015, N'Some, to be sure, are preaching Christ from envy and rivalry, but others from goodwill.'
EXEC add_BibleVerse @BibleId, 350001016, N'The latter do so from love because they know that I am placed here for the defense of the gospel.'
EXEC add_BibleVerse @BibleId, 350001017, N'The former proclaim Christ from selfish ambition, not sincerely, because they think they can cause trouble for me in my imprisonment.'
EXEC add_BibleVerse @BibleId, 350001018, N'What is the result? Only that in every way, whether in pretense or in truth, Christ is being proclaimed, and in this I rejoice. Yes, and I will continue to rejoice,'
EXEC add_BibleVerse @BibleId, 350001019, N'for I know that this will turn out for my deliverance through your prayers and the help of the Spirit of Jesus Christ.'
EXEC add_BibleVerse @BibleId, 350001020, N'My confident hope is that I will in no way be ashamed but that with complete boldness, even now as always, Christ will be exalted in my body, whether I live or die.'
EXEC add_BibleVerse @BibleId, 350001021, N'For to me, living is Christ and dying is gain.'
EXEC add_BibleVerse @BibleId, 350001022, N'Now if I am to go on living in the body, this will mean productive work for me, yet I don’t know which I prefer:'
EXEC add_BibleVerse @BibleId, 350001023, N'I feel torn between the two, because I have a desire to depart and be with Christ, which is better by far,'
EXEC add_BibleVerse @BibleId, 350001024, N'but it is more vital for your sake that I remain in the body.'
EXEC add_BibleVerse @BibleId, 350001025, N'And since I am sure of this, I know that I will remain and continue with all of you for the sake of your progress and joy in the faith,'
EXEC add_BibleVerse @BibleId, 350001026, N'so that what you can be proud of may increase because of me in Christ Jesus, when I come back to you.'
EXEC add_BibleVerse @BibleId, 350001027, N'Only conduct yourselves in a manner worthy of the gospel of Christ so that – whether I come and see you or whether I remain absent – I should hear that you are standing firm in one spirit, with one mind, by contending side by side for the faith of the gospel,'
EXEC add_BibleVerse @BibleId, 350001028, N'and by not being intimidated in any way by your opponents. This is a sign of their destruction, but of your salvation – a sign which is from God.'
EXEC add_BibleVerse @BibleId, 350001029, N'For it has been granted to you not only to believe in Christ but also to suffer for him,'
EXEC add_BibleVerse @BibleId, 350001030, N'since you are encountering the same conflict that you saw me face and now hear that I am facing.'
EXEC add_BibleVerse @BibleId, 350002001, N'Therefore, if there is any encouragement in Christ, any comfort provided by love, any fellowship in the Spirit, any affection or mercy,'
EXEC add_BibleVerse @BibleId, 350002002, N'complete my joy and be of the same mind, by having the same love, being united in spirit, and having one purpose.'
EXEC add_BibleVerse @BibleId, 350002003, N'Instead of being motivated by selfish ambition or vanity, each of you should, in humility, be moved to treat one another as more important than yourself.'
EXEC add_BibleVerse @BibleId, 350002004, N'Each of you should be concerned not only about your own interests, but about the interests of others as well.'
EXEC add_BibleVerse @BibleId, 350002005, N'You should have the same attitude toward one another that Christ Jesus had,'
EXEC add_BibleVerse @BibleId, 350002006, N'who though he existed in the form of God did not regard equality with God as something to be grasped,'
EXEC add_BibleVerse @BibleId, 350002007, N'but emptied himself by taking on the form of a slave, by looking like other men, and by sharing in human nature.'
EXEC add_BibleVerse @BibleId, 350002008, N'He humbled himself, by becoming obedient to the point of death – even death on a cross!'
EXEC add_BibleVerse @BibleId, 350002009, N'As a result God exalted him and gave him the name that is above every name,'
EXEC add_BibleVerse @BibleId, 350002010, N'so that at the name of Jesus every knee will bow – in heaven and on earth and under the earth –'
EXEC add_BibleVerse @BibleId, 350002011, N'and every tongue confess that Jesus Christ is Lord to the glory of God the Father.'
EXEC add_BibleVerse @BibleId, 350002012, N'So then, my dear friends, just as you have always obeyed, not only in my presence but even more in my absence, continue working out your salvation with awe and reverence,'
EXEC add_BibleVerse @BibleId, 350002013, N'for the one bringing forth in you both the desire and the effort – for the sake of his good pleasure – is God.'
EXEC add_BibleVerse @BibleId, 350002014, N'Do everything without grumbling or arguing,'
EXEC add_BibleVerse @BibleId, 350002015, N'so that you may be blameless and pure, children of God without blemish though you live in a crooked and perverse society, in which you shine as lights in the world'
EXEC add_BibleVerse @BibleId, 350002016, N'by holding on to the word of life so that on the day of Christ I will have a reason to boast that I did not run in vain nor labor in vain.'
EXEC add_BibleVerse @BibleId, 350002017, N'But even if I am being poured out like a drink offering on the sacrifice and service of your faith, I am glad and rejoice together with all of you.'
EXEC add_BibleVerse @BibleId, 350002018, N'And in the same way you also should be glad and rejoice together with me.'
EXEC add_BibleVerse @BibleId, 350002019, N'Now I hope in the Lord Jesus to send Timothy to you soon, so that I too may be encouraged by hearing news about you.'
EXEC add_BibleVerse @BibleId, 350002020, N'For there is no one here like him who will readily demonstrate his deep concern for you.'
EXEC add_BibleVerse @BibleId, 350002021, N'Others are busy with their own concerns, not those of Jesus Christ.'
EXEC add_BibleVerse @BibleId, 350002022, N'But you know his qualifications, that like a son working with his father, he served with me in advancing the gospel.'
EXEC add_BibleVerse @BibleId, 350002023, N'So I hope to send him as soon as I know more about my situation,'
EXEC add_BibleVerse @BibleId, 350002024, N'though I am confident in the Lord that I too will be coming to see you soon.'
EXEC add_BibleVerse @BibleId, 350002025, N'But for now I have considered it necessary to send Epaphroditus to you. For he is my brother, coworker and fellow soldier, and your messenger and minister to me in my need.'
EXEC add_BibleVerse @BibleId, 350002026, N'Indeed, he greatly missed all of you and was distressed because you heard that he had been ill.'
EXEC add_BibleVerse @BibleId, 350002027, N'In fact he became so ill that he nearly died. But God showed mercy to him – and not to him only, but also to me – so that I would not have grief on top of grief.'
EXEC add_BibleVerse @BibleId, 350002028, N'Therefore I am all the more eager to send him, so that when you see him again you can rejoice and I can be free from anxiety.'
EXEC add_BibleVerse @BibleId, 350002029, N'So welcome him in the Lord with great joy, and honor people like him,'
EXEC add_BibleVerse @BibleId, 350002030, N'since it was because of the work of Christ that he almost died. He risked his life so that he could make up for your inability to serve me.'
EXEC add_BibleVerse @BibleId, 350003001, N'Finally, my brothers and sisters, rejoice in the Lord! To write this again is no trouble to me, and it is a safeguard for you.'
EXEC add_BibleVerse @BibleId, 350003002, N'Beware of the dogs, beware of the evil workers, beware of those who mutilate the flesh!'
EXEC add_BibleVerse @BibleId, 350003003, N'For we are the circumcision, the ones who worship by the Spirit of God, exult in Christ Jesus, and do not rely on human credentials'
EXEC add_BibleVerse @BibleId, 350003004, N'– though mine too are significant. If someone thinks he has good reasons to put confidence in human credentials, I have more:'
EXEC add_BibleVerse @BibleId, 350003005, N'I was circumcised on the eighth day, from the people of Israel and the tribe of Benjamin, a Hebrew of Hebrews. I lived according to the law as a Pharisee.'
EXEC add_BibleVerse @BibleId, 350003006, N'In my zeal for God I persecuted the church. According to the righteousness stipulated in the law I was blameless.'
EXEC add_BibleVerse @BibleId, 350003007, N'But these assets I have come to regard as liabilities because of Christ.'
EXEC add_BibleVerse @BibleId, 350003008, N'More than that, I now regard all things as liabilities compared to the far greater value of knowing Christ Jesus my Lord, for whom I have suffered the loss of all things – indeed, I regard them as dung! – that I may gain Christ,'
EXEC add_BibleVerse @BibleId, 350003009, N'and be found in him, not because I have my own righteousness derived from the law, but because I have the righteousness that comes by way of Christ’s faithfulness – a righteousness from God that is in fact based on Christ’s faithfulness.'
EXEC add_BibleVerse @BibleId, 350003010, N'My aim is to know him, to experience the power of his resurrection, to share in his sufferings, and to be like him in his death,'
EXEC add_BibleVerse @BibleId, 350003011, N'and so, somehow, to attain to the resurrection from the dead.'
EXEC add_BibleVerse @BibleId, 350003012, N'Not that I have already attained this – that is, I have not already been perfected – but I strive to lay hold of that for which Christ Jesus also laid hold of me.'
EXEC add_BibleVerse @BibleId, 350003013, N'Brothers and sisters, I do not consider myself to have attained this. Instead I am single-minded: Forgetting the things that are behind and reaching out for the things that are ahead,'
EXEC add_BibleVerse @BibleId, 350003014, N'with this goal in mind, I strive toward the prize of the upward call of God in Christ Jesus.'
EXEC add_BibleVerse @BibleId, 350003015, N'Therefore let those of us who are “perfect” embrace this point of view. If you think otherwise, God will reveal to you the error of your ways.'
EXEC add_BibleVerse @BibleId, 350003016, N'Nevertheless, let us live up to the standard that we have already attained.'
EXEC add_BibleVerse @BibleId, 350003017, N'Be imitators of me, brothers and sisters, and watch carefully those who are living this way, just as you have us as an example.'
EXEC add_BibleVerse @BibleId, 350003018, N'For many live, about whom I have often told you, and now, with tears, I tell you that they are the enemies of the cross of Christ.'
EXEC add_BibleVerse @BibleId, 350003019, N'Their end is destruction, their god is the belly, they exult in their shame, and they think about earthly things.'
EXEC add_BibleVerse @BibleId, 350003020, N'But our citizenship is in heaven – and we also await a savior from there, the Lord Jesus Christ,'
EXEC add_BibleVerse @BibleId, 350003021, N'who will transform these humble bodies of ours into the likeness of his glorious body by means of that power by which he is able to subject all things to himself.'
EXEC add_BibleVerse @BibleId, 350004001, N'So then, my brothers and sisters, dear friends whom I long to see, my joy and crown, stand in the Lord in this way, my dear friends!'
EXEC add_BibleVerse @BibleId, 350004002, N'I appeal to Euodia and to Syntyche to agree in the Lord.'
EXEC add_BibleVerse @BibleId, 350004003, N'Yes, I say also to you, true companion, help them. They have struggled together in the gospel ministry along with me and Clement and my other coworkers, whose names are in the book of life.'
EXEC add_BibleVerse @BibleId, 350004004, N'Rejoice in the Lord always. Again I say, rejoice!'
EXEC add_BibleVerse @BibleId, 350004005, N'Let everyone see your gentleness. The Lord is near!'
EXEC add_BibleVerse @BibleId, 350004006, N'Do not be anxious about anything. Instead, in every situation, through prayer and petition with thanksgiving, tell your requests to God.'
EXEC add_BibleVerse @BibleId, 350004007, N'And the peace of God that surpasses all understanding will guard your hearts and minds in Christ Jesus.'
EXEC add_BibleVerse @BibleId, 350004008, N'Finally, brothers and sisters, whatever is true, whatever is worthy of respect, whatever is just, whatever is pure, whatever is lovely, whatever is commendable, if something is excellent or praiseworthy, think about these things.'
EXEC add_BibleVerse @BibleId, 350004009, N'And what you learned and received and heard and saw in me, do these things. And the God of peace will be with you.'
EXEC add_BibleVerse @BibleId, 350004010, N'I have great joy in the Lord because now at last you have again expressed your concern for me. (Now I know you were concerned before but had no opportunity to do anything.)'
EXEC add_BibleVerse @BibleId, 350004011, N'I am not saying this because I am in need, for I have learned to be content in any circumstance.'
EXEC add_BibleVerse @BibleId, 350004012, N'I have experienced times of need and times of abundance. In any and every circumstance I have learned the secret of contentment, whether I go satisfied or hungry, have plenty or nothing.'
EXEC add_BibleVerse @BibleId, 350004013, N'I am able to do all things through the one who strengthens me.'
EXEC add_BibleVerse @BibleId, 350004014, N'Nevertheless, you did well to share with me in my trouble.'
EXEC add_BibleVerse @BibleId, 350004015, N'And as you Philippians know, at the beginning of my gospel ministry, when I left Macedonia, no church shared with me in this matter of giving and receiving except you alone.'
EXEC add_BibleVerse @BibleId, 350004016, N'For even in Thessalonica on more than one occasion you sent something for my need.'
EXEC add_BibleVerse @BibleId, 350004017, N'I do not say this because I am seeking a gift. Rather, I seek the credit that abounds to your account.'
EXEC add_BibleVerse @BibleId, 350004018, N'For I have received everything, and I have plenty. I have all I need because I received from Epaphroditus what you sent – a fragrant offering, an acceptable sacrifice, very pleasing to God.'
EXEC add_BibleVerse @BibleId, 350004019, N'And my God will supply your every need according to his glorious riches in Christ Jesus.'
EXEC add_BibleVerse @BibleId, 350004020, N'May glory be given to God our Father forever and ever. Amen.'
EXEC add_BibleVerse @BibleId, 350004021, N'Give greetings to all the saints in Christ Jesus. The brothers with me here send greetings.'
EXEC add_BibleVerse @BibleId, 350004022, N'All the saints greet you, especially those who belong to Caesar’s household.'
EXEC add_BibleVerse @BibleId, 350004023, N'The grace of the Lord Jesus Christ be with your spirit.'
EXEC add_BibleVerse @BibleId, 351001001, N'From Paul, an apostle of Christ Jesus by the will of God, and Timothy our brother,'
EXEC add_BibleVerse @BibleId, 351001002, N'to the saints, the faithful brothers and sisters in Christ, at Colossae. Grace and peace to you from God our Father!'
EXEC add_BibleVerse @BibleId, 351001003, N'We always give thanks to God, the Father of our Lord Jesus Christ, when we pray for you,'
EXEC add_BibleVerse @BibleId, 351001004, N'since we heard about your faith in Christ Jesus and the love that you have for all the saints.'
EXEC add_BibleVerse @BibleId, 351001005, N'Your faith and love have arisen from the hope laid up for you in heaven, which you have heard about in the message of truth, the gospel'
EXEC add_BibleVerse @BibleId, 351001006, N'that has come to you. Just as in the entire world this gospel is bearing fruit and growing, so it has also been bearing fruit and growing among you from the first day you heard it and understood the grace of God in truth.'
EXEC add_BibleVerse @BibleId, 351001007, N'You learned the gospel from Epaphras, our dear fellow slave – a faithful minister of Christ on our behalf –'
EXEC add_BibleVerse @BibleId, 351001008, N'who also told us of your love in the Spirit.'
EXEC add_BibleVerse @BibleId, 351001009, N'For this reason we also, from the day we heard about you, have not ceased praying for you and asking God to fill you with the knowledge of his will in all spiritual wisdom and understanding,'
EXEC add_BibleVerse @BibleId, 351001010, N'so that you may live worthily of the Lord and please him in all respects – bearing fruit in every good deed, growing in the knowledge of God,'
EXEC add_BibleVerse @BibleId, 351001011, N'being strengthened with all power according to his glorious might for the display of all patience and steadfastness, joyfully'
EXEC add_BibleVerse @BibleId, 351001012, N'giving thanks to the Father who has qualified you to share in the saints’ inheritance in the light.'
EXEC add_BibleVerse @BibleId, 351001013, N'He delivered us from the power of darkness and transferred us to the kingdom of the Son he loves,'
EXEC add_BibleVerse @BibleId, 351001014, N'in whom we have redemption, the forgiveness of sins.'
EXEC add_BibleVerse @BibleId, 351001015, N'He is the image of the invisible God, the firstborn over all creation,'
EXEC add_BibleVerse @BibleId, 351001016, N'for all things in heaven and on earth were created by him – all things, whether visible or invisible, whether thrones or dominions, whether principalities or powers – all things were created through him and for him.'
EXEC add_BibleVerse @BibleId, 351001017, N'He himself is before all things and all things are held together in him.'
EXEC add_BibleVerse @BibleId, 351001018, N'He is the head of the body, the church, as well as the beginning, the firstborn from among the dead, so that he himself may become first in all things.'
EXEC add_BibleVerse @BibleId, 351001019, N'For God was pleased to have all his fullness dwell in the Son'
EXEC add_BibleVerse @BibleId, 351001020, N'and through him to reconcile all things to himself by making peace through the blood of his cross – through him, whether things on earth or things in heaven.'
EXEC add_BibleVerse @BibleId, 351001021, N'And you were at one time strangers and enemies in your minds as expressed through your evil deeds,'
EXEC add_BibleVerse @BibleId, 351001022, N'but now he has reconciled you by his physical body through death to present you holy, without blemish, and blameless before him –'
EXEC add_BibleVerse @BibleId, 351001023, N'if indeed you remain in the faith, established and firm, without shifting from the hope of the gospel that you heard. This gospel has also been preached in all creation under heaven, and I, Paul, have become its servant.'
EXEC add_BibleVerse @BibleId, 351001024, N'Now I rejoice in my sufferings for you, and I fill up in my physical body – for the sake of his body, the church – what is lacking in the sufferings of Christ.'
EXEC add_BibleVerse @BibleId, 351001025, N'I became a servant of the church according to the stewardship from God – given to me for you – in order to complete the word of God,'
EXEC add_BibleVerse @BibleId, 351001026, N'that is, the mystery that has been kept hidden from ages and generations, but has now been revealed to his saints.'
EXEC add_BibleVerse @BibleId, 351001027, N'God wanted to make known to them the glorious riches of this mystery among the Gentiles, which is Christ in you, the hope of glory.'
EXEC add_BibleVerse @BibleId, 351001028, N'We proclaim him by instructing and teaching all people with all wisdom so that we may present every person mature in Christ.'
EXEC add_BibleVerse @BibleId, 351001029, N'Toward this goal I also labor, struggling according to his power that powerfully works in me.'
EXEC add_BibleVerse @BibleId, 351002001, N'For I want you to know how great a struggle I have for you, and for those in Laodicea, and for those who have not met me face to face.'
EXEC add_BibleVerse @BibleId, 351002002, N'My goal is that their hearts, having been knit together in love, may be encouraged, and that they may have all the riches that assurance brings in their understanding of the knowledge of the mystery of God, namely, Christ,'
EXEC add_BibleVerse @BibleId, 351002003, N'in whom are hidden all the treasures of wisdom and knowledge.'
EXEC add_BibleVerse @BibleId, 351002004, N'I say this so that no one will deceive you through arguments that sound reasonable.'
EXEC add_BibleVerse @BibleId, 351002005, N'For though I am absent from you in body, I am present with you in spirit, rejoicing to see your morale and the firmness of your faith in Christ.'
EXEC add_BibleVerse @BibleId, 351002006, N'Therefore, just as you received Christ Jesus as Lord, continue to live your lives in him,'
EXEC add_BibleVerse @BibleId, 351002007, N'rooted and built up in him and firm in your faith just as you were taught, and overflowing with thankfulness.'
EXEC add_BibleVerse @BibleId, 351002008, N'Be careful not to allow anyone to captivate you through an empty, deceitful philosophy that is according to human traditions and the elemental spirits of the world, and not according to Christ.'
EXEC add_BibleVerse @BibleId, 351002009, N'For in him all the fullness of deity lives in bodily form,'
EXEC add_BibleVerse @BibleId, 351002010, N'and you have been filled in him, who is the head over every ruler and authority.'
EXEC add_BibleVerse @BibleId, 351002011, N'In him you also were circumcised – not, however, with a circumcision performed by human hands, but by the removal of the fleshly body, that is, through the circumcision done by Christ.'
EXEC add_BibleVerse @BibleId, 351002012, N'Having been buried with him in baptism, you also have been raised with him through your faith in the power of God who raised him from the dead.'
EXEC add_BibleVerse @BibleId, 351002013, N'And even though you were dead in your transgressions and in the uncircumcision of your flesh, he nevertheless made you alive with him, having forgiven all your transgressions.'
EXEC add_BibleVerse @BibleId, 351002014, N'He has destroyed what was against us, a certificate of indebtedness expressed in decrees opposed to us. He has taken it away by nailing it to the cross.'
EXEC add_BibleVerse @BibleId, 351002015, N'Disarming the rulers and authorities, he has made a public disgrace of them, triumphing over them by the cross.'
EXEC add_BibleVerse @BibleId, 351002016, N'Therefore do not let anyone judge you with respect to food or drink, or in the matter of a feast, new moon, or Sabbath days –'
EXEC add_BibleVerse @BibleId, 351002017, N'these are only the shadow of the things to come, but the reality is Christ!'
EXEC add_BibleVerse @BibleId, 351002018, N'Let no one who delights in humility and the worship of angels pass judgment on you. That person goes on at great lengths about what he has supposedly seen, but he is puffed up with empty notions by his fleshly mind.'
EXEC add_BibleVerse @BibleId, 351002019, N'He has not held fast to the head from whom the whole body, supported and knit together through its ligaments and sinews, grows with a growth that is from God.'
EXEC add_BibleVerse @BibleId, 351002020, N'If you have died with Christ to the elemental spirits of the world, why do you submit to them as though you lived in the world?'
EXEC add_BibleVerse @BibleId, 351002021, N'“Do not handle! Do not taste! Do not touch!”'
EXEC add_BibleVerse @BibleId, 351002022, N'These are all destined to perish with use, founded as they are on human commands and teachings.'
EXEC add_BibleVerse @BibleId, 351002023, N'Even though they have the appearance of wisdom with their self-imposed worship and false humility achieved by an unsparing treatment of the body – a wisdom with no true value – they in reality result in fleshly indulgence.'
EXEC add_BibleVerse @BibleId, 351003001, N'Therefore, if you have been raised with Christ, keep seeking the things above, where Christ is, seated at the right hand of God.'
EXEC add_BibleVerse @BibleId, 351003002, N'Keep thinking about things above, not things on the earth,'
EXEC add_BibleVerse @BibleId, 351003003, N'for you have died and your life is hidden with Christ in God.'
EXEC add_BibleVerse @BibleId, 351003004, N'When Christ (who is your life) appears, then you too will be revealed in glory with him.'
EXEC add_BibleVerse @BibleId, 351003005, N'So put to death whatever in your nature belongs to the earth: sexual immorality, impurity, shameful passion, evil desire, and greed which is idolatry.'
EXEC add_BibleVerse @BibleId, 351003006, N'Because of these things the wrath of God is coming on the sons of disobedience.'
EXEC add_BibleVerse @BibleId, 351003007, N'You also lived your lives in this way at one time, when you used to live among them.'
EXEC add_BibleVerse @BibleId, 351003008, N'But now, put off all such things as anger, rage, malice, slander, abusive language from your mouth.'
EXEC add_BibleVerse @BibleId, 351003009, N'Do not lie to one another since you have put off the old man with its practices'
EXEC add_BibleVerse @BibleId, 351003010, N'and have been clothed with the new man that is being renewed in knowledge according to the image of the one who created it.'
EXEC add_BibleVerse @BibleId, 351003011, N'Here there is neither Greek nor Jew, circumcised or uncircumcised, barbarian, Scythian, slave or free, but Christ is all and in all.'
EXEC add_BibleVerse @BibleId, 351003012, N'Therefore, as the elect of God, holy and dearly loved, clothe yourselves with a heart of mercy, kindness, humility, gentleness, and patience,'
EXEC add_BibleVerse @BibleId, 351003013, N'bearing with one another and forgiving one another, if someone happens to have a complaint against anyone else. Just as the Lord has forgiven you, so you also forgive others.'
EXEC add_BibleVerse @BibleId, 351003014, N'And to all these virtues add love, which is the perfect bond.'
EXEC add_BibleVerse @BibleId, 351003015, N'Let the peace of Christ be in control in your heart (for you were in fact called as one body to this peace), and be thankful.'
EXEC add_BibleVerse @BibleId, 351003016, N'Let the word of Christ dwell in you richly, teaching and exhorting one another with all wisdom, singing psalms, hymns, and spiritual songs, all with grace in your hearts to God.'
EXEC add_BibleVerse @BibleId, 351003017, N'And whatever you do in word or deed, do it all in the name of the Lord Jesus, giving thanks to God the Father through him.'
EXEC add_BibleVerse @BibleId, 351003018, N'Wives, submit to your husbands, as is fitting in the Lord.'
EXEC add_BibleVerse @BibleId, 351003019, N'Husbands, love your wives and do not be embittered against them.'
EXEC add_BibleVerse @BibleId, 351003020, N'Children, obey your parents in everything, for this is pleasing in the Lord.'
EXEC add_BibleVerse @BibleId, 351003021, N'Fathers, do not provoke your children, so they will not become disheartened.'
EXEC add_BibleVerse @BibleId, 351003022, N'Slaves, obey your earthly masters in every respect, not only when they are watching – like those who are strictly people-pleasers – but with a sincere heart, fearing the Lord.'
EXEC add_BibleVerse @BibleId, 351003023, N'Whatever you are doing, work at it with enthusiasm, as to the Lord and not for people,'
EXEC add_BibleVerse @BibleId, 351003024, N'because you know that you will receive your inheritance from the Lord as the reward. Serve the Lord Christ.'
EXEC add_BibleVerse @BibleId, 351003025, N'For the one who does wrong will be repaid for his wrong, and there are no exceptions.'
EXEC add_BibleVerse @BibleId, 351004001, N'Masters, treat your slaves with justice and fairness, because you know that you also have a master in heaven.'
EXEC add_BibleVerse @BibleId, 351004002, N'Be devoted to prayer, keeping alert in it with thanksgiving.'
EXEC add_BibleVerse @BibleId, 351004003, N'At the same time pray for us too, that God may open a door for the message so that we may proclaim the mystery of Christ, for which I am in chains.'
EXEC add_BibleVerse @BibleId, 351004004, N'Pray that I may make it known as I should.'
EXEC add_BibleVerse @BibleId, 351004005, N'Conduct yourselves with wisdom toward outsiders, making the most of the opportunities.'
EXEC add_BibleVerse @BibleId, 351004006, N'Let your speech always be gracious, seasoned with salt, so that you may know how you should answer everyone.'
EXEC add_BibleVerse @BibleId, 351004007, N'Tychicus, a dear brother, faithful minister, and fellow slave in the Lord, will tell you all the news about me.'
EXEC add_BibleVerse @BibleId, 351004008, N'I sent him to you for this very purpose, that you may know how we are doing and that he may encourage your hearts.'
EXEC add_BibleVerse @BibleId, 351004009, N'I sent him with Onesimus, the faithful and dear brother, who is one of you. They will tell you about everything here.'
EXEC add_BibleVerse @BibleId, 351004010, N'Aristarchus, my fellow prisoner, sends you greetings, as does Mark, the cousin of Barnabas (about whom you received instructions; if he comes to you, welcome him).'
EXEC add_BibleVerse @BibleId, 351004011, N'And Jesus who is called Justus also sends greetings. In terms of Jewish converts, these are the only fellow workers for the kingdom of God, and they have been a comfort to me.'
EXEC add_BibleVerse @BibleId, 351004012, N'Epaphras, who is one of you and a slave of Christ, greets you. He is always struggling in prayer on your behalf, so that you may stand mature and fully assured in all the will of God.'
EXEC add_BibleVerse @BibleId, 351004013, N'For I can testify that he has worked hard for you and for those in Laodicea and Hierapolis.'
EXEC add_BibleVerse @BibleId, 351004014, N'Our dear friend Luke the physician and Demas greet you.'
EXEC add_BibleVerse @BibleId, 351004015, N'Give my greetings to the brothers and sisters who are in Laodicea and to Nympha and the church that meets in her house.'
EXEC add_BibleVerse @BibleId, 351004016, N'And after you have read this letter, have it read to the church of Laodicea. In turn, read the letter from Laodicea as well.'
EXEC add_BibleVerse @BibleId, 351004017, N'And tell Archippus, “See to it that you complete the ministry you received in the Lord.”'
EXEC add_BibleVerse @BibleId, 351004018, N'I, Paul, write this greeting by my own hand. Remember my chains. Grace be with you.'
EXEC add_BibleVerse @BibleId, 352001001, N'From Paul and Silvanus and Timothy, to the church of the Thessalonians in God the Father and the Lord Jesus Christ. Grace and peace to you!'
EXEC add_BibleVerse @BibleId, 352001002, N'We thank God always for all of you as we mention you constantly in our prayers,'
EXEC add_BibleVerse @BibleId, 352001003, N'because we recall in the presence of our God and Father your work of faith and labor of love and endurance of hope in our Lord Jesus Christ.'
EXEC add_BibleVerse @BibleId, 352001004, N'We know, brothers and sisters loved by God, that he has chosen you,'
EXEC add_BibleVerse @BibleId, 352001005, N'in that our gospel did not come to you merely in words, but in power and in the Holy Spirit and with deep conviction (surely you recall the character we displayed when we came among you to help you).'
EXEC add_BibleVerse @BibleId, 352001006, N'And you became imitators of us and of the Lord, when you received the message with joy that comes from the Holy Spirit, despite great affliction.'
EXEC add_BibleVerse @BibleId, 352001007, N'As a result you became an example to all the believers in Macedonia and in Achaia.'
EXEC add_BibleVerse @BibleId, 352001008, N'For from you the message of the Lord has echoed forth not just in Macedonia and Achaia, but in every place reports of your faith in God have spread, so that we do not need to say anything.'
EXEC add_BibleVerse @BibleId, 352001009, N'For people everywhere report how you welcomed us and how you turned to God from idols to serve the living and true God'
EXEC add_BibleVerse @BibleId, 352001010, N'and to wait for his Son from heaven, whom he raised from the dead, Jesus our deliverer from the coming wrath.'
EXEC add_BibleVerse @BibleId, 352002001, N'For you yourselves know, brothers and sisters, about our coming to you – it has not proven to be purposeless.'
EXEC add_BibleVerse @BibleId, 352002002, N'But although we suffered earlier and were mistreated in Philippi, as you know, we had the courage in our God to declare to you the gospel of God in spite of much opposition.'
EXEC add_BibleVerse @BibleId, 352002003, N'For the appeal we make does not come from error or impurity or with deceit,'
EXEC add_BibleVerse @BibleId, 352002004, N'but just as we have been approved by God to be entrusted with the gospel, so we declare it, not to please people but God, who examines our hearts.'
EXEC add_BibleVerse @BibleId, 352002005, N'For we never appeared with flattering speech, as you know, nor with a pretext for greed – God is our witness –'
EXEC add_BibleVerse @BibleId, 352002006, N'nor to seek glory from people, either from you or from others,'
EXEC add_BibleVerse @BibleId, 352002007, N'although we could have imposed our weight as apostles of Christ; instead we became little children among you. Like a nursing mother caring for her own children,'
EXEC add_BibleVerse @BibleId, 352002008, N'with such affection for you we were happy to share with you not only the gospel of God but also our own lives, because you had become dear to us.'
EXEC add_BibleVerse @BibleId, 352002009, N'For you recall, brothers and sisters, our toil and drudgery: By working night and day so as not to impose a burden on any of you, we preached to you the gospel of God.'
EXEC add_BibleVerse @BibleId, 352002010, N'You are witnesses, and so is God, as to how holy and righteous and blameless our conduct was toward you who believe.'
EXEC add_BibleVerse @BibleId, 352002011, N'As you know, we treated each one of you as a father treats his own children,'
EXEC add_BibleVerse @BibleId, 352002012, N'exhorting and encouraging you and insisting that you live in a way worthy of God who calls you to his own kingdom and his glory.'
EXEC add_BibleVerse @BibleId, 352002013, N'And so we too constantly thank God that when you received God’s message that you heard from us, you accepted it not as a human message, but as it truly is, God’s message, which is at work among you who believe.'
EXEC add_BibleVerse @BibleId, 352002014, N'For you became imitators, brothers and sisters, of God’s churches in Christ Jesus that are in Judea, because you too suffered the same things from your own countrymen as they in fact did from the Jews,'
EXEC add_BibleVerse @BibleId, 352002015, N'who killed both the Lord Jesus and the prophets and persecuted us severely. They are displeasing to God and are opposed to all people,'
EXEC add_BibleVerse @BibleId, 352002016, N'because they hinder us from speaking to the Gentiles so that they may be saved. Thus they constantly fill up their measure of sins, but wrath has come upon them completely.'
EXEC add_BibleVerse @BibleId, 352002017, N'But when we were separated from you, brothers and sisters, for a short time (in presence, not in affection) we became all the more fervent in our great desire to see you in person.'
EXEC add_BibleVerse @BibleId, 352002018, N'For we wanted to come to you (I, Paul, in fact tried again and again) but Satan thwarted us.'
EXEC add_BibleVerse @BibleId, 352002019, N'For who is our hope or joy or crown to boast of before our Lord Jesus at his coming? Is it not of course you?'
EXEC add_BibleVerse @BibleId, 352002020, N'For you are our glory and joy!'
EXEC add_BibleVerse @BibleId, 352003001, N'So when we could bear it no longer, we decided to stay on in Athens alone.'
EXEC add_BibleVerse @BibleId, 352003002, N'We sent Timothy, our brother and fellow worker for God in the gospel of Christ, to strengthen you and encourage you about your faith,'
EXEC add_BibleVerse @BibleId, 352003003, N'so that no one would be shaken by these afflictions. For you yourselves know that we are destined for this.'
EXEC add_BibleVerse @BibleId, 352003004, N'For in fact when we were with you, we were telling you in advance that we would suffer affliction, and so it has happened, as you well know.'
EXEC add_BibleVerse @BibleId, 352003005, N'So when I could bear it no longer, I sent to find out about your faith, for fear that the tempter somehow tempted you and our toil had proven useless.'
EXEC add_BibleVerse @BibleId, 352003006, N'But now Timothy has come to us from you and given us the good news of your faith and love and that you always think of us with affection and long to see us just as we also long to see you!'
EXEC add_BibleVerse @BibleId, 352003007, N'So in all our distress and affliction, we were reassured about you, brothers and sisters, through your faith.'
EXEC add_BibleVerse @BibleId, 352003008, N'For now we are alive again, if you stand firm in the Lord.'
EXEC add_BibleVerse @BibleId, 352003009, N'For how can we thank God enough for you, for all the joy we feel because of you before our God?'
EXEC add_BibleVerse @BibleId, 352003010, N'We pray earnestly night and day to see you in person and make up what may be lacking in your faith.'
EXEC add_BibleVerse @BibleId, 352003011, N'Now may God our Father himself and our Lord Jesus direct our way to you.'
EXEC add_BibleVerse @BibleId, 352003012, N'And may the Lord cause you to increase and abound in love for one another and for all, just as we do for you,'
EXEC add_BibleVerse @BibleId, 352003013, N'so that your hearts are strengthened in holiness to be blameless before our God and Father at the coming of our Lord Jesus with all his saints.'
EXEC add_BibleVerse @BibleId, 352004001, N'Finally then, brothers and sisters, we ask you and urge you in the Lord Jesus, that as you received instruction from us about how you must live and please God (as you are in fact living) that you do so more and more.'
EXEC add_BibleVerse @BibleId, 352004002, N'For you know what commands we gave you through the Lord Jesus.'
EXEC add_BibleVerse @BibleId, 352004003, N'For this is God’s will: that you become holy, that you keep away from sexual immorality,'
EXEC add_BibleVerse @BibleId, 352004004, N'that each of you know how to possess his own body in holiness and honor,'
EXEC add_BibleVerse @BibleId, 352004005, N'not in lustful passion like the Gentiles who do not know God.'
EXEC add_BibleVerse @BibleId, 352004006, N'In this matter no one should violate the rights of his brother or take advantage of him, because the Lord is the avenger in all these cases, as we also told you earlier and warned you solemnly.'
EXEC add_BibleVerse @BibleId, 352004007, N'For God did not call us to impurity but in holiness.'
EXEC add_BibleVerse @BibleId, 352004008, N'Consequently the one who rejects this is not rejecting human authority but God, who gives his Holy Spirit to you.'
EXEC add_BibleVerse @BibleId, 352004009, N'Now on the topic of brotherly love you have no need for anyone to write you, for you yourselves are taught by God to love one another.'
EXEC add_BibleVerse @BibleId, 352004010, N'And indeed you are practicing it toward all the brothers and sisters in all of Macedonia. But we urge you, brothers and sisters, to do so more and more,'
EXEC add_BibleVerse @BibleId, 352004011, N'to aspire to lead a quiet life, to attend to your own business, and to work with your hands, as we commanded you.'
EXEC add_BibleVerse @BibleId, 352004012, N'In this way you will live a decent life before outsiders and not be in need.'
EXEC add_BibleVerse @BibleId, 352004013, N'Now we do not want you to be uninformed, brothers and sisters, about those who are asleep, so that you will not grieve like the rest who have no hope.'
EXEC add_BibleVerse @BibleId, 352004014, N'For if we believe that Jesus died and rose again, so also we believe that God will bring with him those who have fallen asleep as Christians.'
EXEC add_BibleVerse @BibleId, 352004015, N'For we tell you this by the word of the Lord, that we who are alive, who are left until the coming of the Lord, will surely not go ahead of those who have fallen asleep.'
EXEC add_BibleVerse @BibleId, 352004016, N'For the Lord himself will come down from heaven with a shout of command, with the voice of the archangel, and with the trumpet of God, and the dead in Christ will rise first.'
EXEC add_BibleVerse @BibleId, 352004017, N'Then we who are alive, who are left, will be suddenly caught up together with them in the clouds to meet the Lord in the air. And so we will always be with the Lord.'
EXEC add_BibleVerse @BibleId, 352004018, N'Therefore encourage one another with these words.'
EXEC add_BibleVerse @BibleId, 352005001, N'Now on the topic of times and seasons, brothers and sisters, you have no need for anything to be written to you.'
EXEC add_BibleVerse @BibleId, 352005002, N'For you know quite well that the day of the Lord will come in the same way as a thief in the night.'
EXEC add_BibleVerse @BibleId, 352005003, N'Now when they are saying, “There is peace and security,” then sudden destruction comes on them, like labor pains on a pregnant woman, and they will surely not escape.'
EXEC add_BibleVerse @BibleId, 352005004, N'But you, brothers and sisters, are not in the darkness for the day to overtake you like a thief would.'
EXEC add_BibleVerse @BibleId, 352005005, N'For you all are sons of the light and sons of the day. We are not of the night nor of the darkness.'
EXEC add_BibleVerse @BibleId, 352005006, N'So then we must not sleep as the rest, but must stay alert and sober.'
EXEC add_BibleVerse @BibleId, 352005007, N'For those who sleep, sleep at night and those who get drunk are drunk at night.'
EXEC add_BibleVerse @BibleId, 352005008, N'But since we are of the day, we must stay sober by putting on the breastplate of faith and love and as a helmet our hope for salvation.'
EXEC add_BibleVerse @BibleId, 352005009, N'For God did not destine us for wrath but for gaining salvation through our Lord Jesus Christ.'
EXEC add_BibleVerse @BibleId, 352005010, N'He died for us so that whether we are alert or asleep we will come to life together with him.'
EXEC add_BibleVerse @BibleId, 352005011, N'Therefore encourage one another and build up each other, just as you are in fact doing.'
EXEC add_BibleVerse @BibleId, 352005012, N'Now we ask you, brothers and sisters, to acknowledge those who labor among you and preside over you in the Lord and admonish you,'
EXEC add_BibleVerse @BibleId, 352005013, N'and to esteem them most highly in love because of their work. Be at peace among yourselves.'
EXEC add_BibleVerse @BibleId, 352005014, N'And we urge you, brothers and sisters, admonish the undisciplined, comfort the discouraged, help the weak, be patient toward all.'
EXEC add_BibleVerse @BibleId, 352005015, N'See that no one pays back evil for evil to anyone, but always pursue what is good for one another and for all.'
EXEC add_BibleVerse @BibleId, 352005016, N'Always rejoice,'
EXEC add_BibleVerse @BibleId, 352005017, N'constantly pray,'
EXEC add_BibleVerse @BibleId, 352005018, N'in everything give thanks. For this is God’s will for you in Christ Jesus.'
EXEC add_BibleVerse @BibleId, 352005019, N'Do not extinguish the Spirit.'
EXEC add_BibleVerse @BibleId, 352005020, N'Do not treat prophecies with contempt.'
EXEC add_BibleVerse @BibleId, 352005021, N'But examine all things; hold fast to what is good.'
EXEC add_BibleVerse @BibleId, 352005022, N'Stay away from every form of evil.'
EXEC add_BibleVerse @BibleId, 352005023, N'Now may the God of peace himself make you completely holy and may your spirit and soul and body be kept entirely blameless at the coming of our Lord Jesus Christ.'
EXEC add_BibleVerse @BibleId, 352005024, N'He who calls you is trustworthy, and he will in fact do this.'
EXEC add_BibleVerse @BibleId, 352005025, N'Brothers and sisters, pray for us too.'
EXEC add_BibleVerse @BibleId, 352005026, N'Greet all the brothers and sisters with a holy kiss.'
EXEC add_BibleVerse @BibleId, 352005027, N'I call on you solemnly in the Lord to have this letter read to all the brothers and sisters.'
EXEC add_BibleVerse @BibleId, 352005028, N'The grace of our Lord Jesus Christ be with you.'
EXEC add_BibleVerse @BibleId, 353001001, N'From Paul and Silvanus and Timothy, to the church of the Thessalonians in God our Father and the Lord Jesus Christ.'
EXEC add_BibleVerse @BibleId, 353001002, N'Grace and peace to you from God the Father and the Lord Jesus Christ!'
EXEC add_BibleVerse @BibleId, 353001003, N'We ought to thank God always for you, brothers and sisters, and rightly so, because your faith flourishes more and more and the love of each one of you all for one another is ever greater.'
EXEC add_BibleVerse @BibleId, 353001004, N'As a result we ourselves boast about you in the churches of God for your perseverance and faith in all the persecutions and afflictions you are enduring.'
EXEC add_BibleVerse @BibleId, 353001005, N'This is evidence of God’s righteous judgment, to make you worthy of the kingdom of God, for which in fact you are suffering.'
EXEC add_BibleVerse @BibleId, 353001006, N'For it is right for God to repay with affliction those who afflict you,'
EXEC add_BibleVerse @BibleId, 353001007, N'and to you who are being afflicted to give rest together with us when the Lord Jesus is revealed from heaven with his mighty angels.'
EXEC add_BibleVerse @BibleId, 353001008, N'With flaming fire he will mete out punishment on those who do not know God and do not obey the gospel of our Lord Jesus.'
EXEC add_BibleVerse @BibleId, 353001009, N'They will undergo the penalty of eternal destruction, away from the presence of the Lord and from the glory of his strength,'
EXEC add_BibleVerse @BibleId, 353001010, N'when he comes to be glorified among his saints and admired on that day among all who have believed – and you did in fact believe our testimony.'
EXEC add_BibleVerse @BibleId, 353001011, N'And in this regard we pray for you always, that our God will make you worthy of his calling and fulfill by his power your every desire for goodness and every work of faith,'
EXEC add_BibleVerse @BibleId, 353001012, N'that the name of our Lord Jesus may be glorified in you, and you in him, according to the grace of our God and the Lord Jesus Christ.'
EXEC add_BibleVerse @BibleId, 353002001, N'Now regarding the arrival of our Lord Jesus Christ and our being gathered to be with him, we ask you, brothers and sisters,'
EXEC add_BibleVerse @BibleId, 353002002, N'not to be easily shaken from your composure or disturbed by any kind of spirit or message or letter allegedly from us, to the effect that the day of the Lord is already here.'
EXEC add_BibleVerse @BibleId, 353002003, N'Let no one deceive you in any way. For that day will not arrive until the rebellion comes and the man of lawlessness is revealed, the son of destruction.'
EXEC add_BibleVerse @BibleId, 353002004, N'He opposes and exalts himself above every so-called god or object of worship, and as a result he takes his seat in God’s temple, displaying himself as God.'
EXEC add_BibleVerse @BibleId, 353002005, N'Surely you recall that I used to tell you these things while I was still with you.'
EXEC add_BibleVerse @BibleId, 353002006, N'And so you know what holds him back, so that he will be revealed in his own time.'
EXEC add_BibleVerse @BibleId, 353002007, N'For the hidden power of lawlessness is already at work. However, the one who holds him back will do so until he is taken out of the way,'
EXEC add_BibleVerse @BibleId, 353002008, N'and then the lawless one will be revealed, whom the Lord will destroy by the breath of his mouth and wipe out by the manifestation of his arrival.'
EXEC add_BibleVerse @BibleId, 353002009, N'The arrival of the lawless one will be by Satan’s working with all kinds of miracles and signs and false wonders,'
EXEC add_BibleVerse @BibleId, 353002010, N'and with every kind of evil deception directed against those who are perishing, because they found no place in their hearts for the truth so as to be saved.'
EXEC add_BibleVerse @BibleId, 353002011, N'Consequently God sends on them a deluding influence so that they will believe what is false.'
EXEC add_BibleVerse @BibleId, 353002012, N'And so all of them who have not believed the truth but have delighted in evil will be condemned.'
EXEC add_BibleVerse @BibleId, 353002013, N'But we ought to thank God always for you, brothers and sisters loved by the Lord, because God chose you from the beginning for salvation through sanctification by the Spirit and faith in the truth.'
EXEC add_BibleVerse @BibleId, 353002014, N'He called you to this salvation through our gospel, so that you may possess the glory of our Lord Jesus Christ.'
EXEC add_BibleVerse @BibleId, 353002015, N'Therefore, brothers and sisters, stand firm and hold on to the traditions that we taught you, whether by speech or by letter.'
EXEC add_BibleVerse @BibleId, 353002016, N'Now may our Lord Jesus Christ himself and God our Father, who loved us and by grace gave us eternal comfort and good hope,'
EXEC add_BibleVerse @BibleId, 353002017, N'encourage your hearts and strengthen you in every good thing you do or say.'
EXEC add_BibleVerse @BibleId, 353003001, N'Finally, pray for us, brothers and sisters, that the Lord’s message may spread quickly and be honored as in fact it was among you,'
EXEC add_BibleVerse @BibleId, 353003002, N'and that we may be delivered from perverse and evil people. For not all have faith.'
EXEC add_BibleVerse @BibleId, 353003003, N'But the Lord is faithful, and he will strengthen you and protect you from the evil one.'
EXEC add_BibleVerse @BibleId, 353003004, N'And we are confident about you in the Lord that you are both doing – and will do – what we are commanding.'
EXEC add_BibleVerse @BibleId, 353003005, N'Now may the Lord direct your hearts toward the love of God and the endurance of Christ.'
EXEC add_BibleVerse @BibleId, 353003006, N'But we command you, brothers and sisters, in the name of our Lord Jesus Christ, to keep away from any brother who lives an undisciplined life and not according to the tradition they received from us.'
EXEC add_BibleVerse @BibleId, 353003007, N'For you know yourselves how you must imitate us, because we did not behave without discipline among you,'
EXEC add_BibleVerse @BibleId, 353003008, N'and we did not eat anyone’s food without paying. Instead, in toil and drudgery we worked night and day in order not to burden any of you.'
EXEC add_BibleVerse @BibleId, 353003009, N'It was not because we do not have that right, but to give ourselves as an example for you to imitate.'
EXEC add_BibleVerse @BibleId, 353003010, N'For even when we were with you, we used to give you this command: “If anyone is not willing to work, neither should he eat.”'
EXEC add_BibleVerse @BibleId, 353003011, N'For we hear that some among you are living an undisciplined life, not doing their own work but meddling in the work of others.'
EXEC add_BibleVerse @BibleId, 353003012, N'Now such people we command and urge in the Lord Jesus Christ to work quietly and so provide their own food to eat.'
EXEC add_BibleVerse @BibleId, 353003013, N'But you, brothers and sisters, do not grow weary in doing what is right.'
EXEC add_BibleVerse @BibleId, 353003014, N'But if anyone does not obey our message through this letter, take note of him and do not associate closely with him, so that he may be ashamed.'
EXEC add_BibleVerse @BibleId, 353003015, N'Yet do not regard him as an enemy, but admonish him as a brother.'
EXEC add_BibleVerse @BibleId, 353003016, N'Now may the Lord of peace himself give you peace at all times and in every way. The Lord be with you all.'
EXEC add_BibleVerse @BibleId, 353003017, N'I, Paul, write this greeting with my own hand, which is how I write in every letter.'
EXEC add_BibleVerse @BibleId, 353003018, N'The grace of our Lord Jesus Christ be with you all.'
EXEC add_BibleVerse @BibleId, 354001001, N'From Paul, an apostle of Christ Jesus by the command of God our Savior and of Christ Jesus our hope,'
EXEC add_BibleVerse @BibleId, 354001002, N'to Timothy, my genuine child in the faith. Grace, mercy, and peace from God the Father and Christ Jesus our Lord!'
EXEC add_BibleVerse @BibleId, 354001003, N'As I urged you when I was leaving for Macedonia, stay on in Ephesus to instruct certain people not to spread false teachings,'
EXEC add_BibleVerse @BibleId, 354001004, N'nor to occupy themselves with myths and interminable genealogies. Such things promote useless speculations rather than God’s redemptive plan that operates by faith.'
EXEC add_BibleVerse @BibleId, 354001005, N'But the aim of our instruction is love that comes from a pure heart, a good conscience, and a sincere faith.'
EXEC add_BibleVerse @BibleId, 354001006, N'Some have strayed from these and turned away to empty discussion.'
EXEC add_BibleVerse @BibleId, 354001007, N'They want to be teachers of the law, but they do not understand what they are saying or the things they insist on so confidently.'
EXEC add_BibleVerse @BibleId, 354001008, N'But we know that the law is good if someone uses it legitimately,'
EXEC add_BibleVerse @BibleId, 354001009, N'realizing that law is not intended for a righteous person, but for lawless and rebellious people, for the ungodly and sinners, for the unholy and profane, for those who kill their fathers or mothers, for murderers,'
EXEC add_BibleVerse @BibleId, 354001010, N'sexually immoral people, practicing homosexuals, kidnappers, liars, perjurers – in fact, for any who live contrary to sound teaching.'
EXEC add_BibleVerse @BibleId, 354001011, N'This accords with the glorious gospel of the blessed God that was entrusted to me.'
EXEC add_BibleVerse @BibleId, 354001012, N'I am grateful to the one who has strengthened me, Christ Jesus our Lord, because he considered me faithful in putting me into ministry,'
EXEC add_BibleVerse @BibleId, 354001013, N'even though I was formerly a blasphemer and a persecutor, and an arrogant man. But I was treated with mercy because I acted ignorantly in unbelief,'
EXEC add_BibleVerse @BibleId, 354001014, N'and our Lord’s grace was abundant, bringing faith and love in Christ Jesus.'
EXEC add_BibleVerse @BibleId, 354001015, N'This saying is trustworthy and deserves full acceptance: “Christ Jesus came into the world to save sinners” – and I am the worst of them!'
EXEC add_BibleVerse @BibleId, 354001016, N'But here is why I was treated with mercy: so that in me as the worst, Christ Jesus could demonstrate his utmost patience, as an example for those who are going to believe in him for eternal life.'
EXEC add_BibleVerse @BibleId, 354001017, N'Now to the eternal king, immortal, invisible, the only God, be honor and glory forever and ever! Amen.'
EXEC add_BibleVerse @BibleId, 354001018, N'I put this charge before you, Timothy my child, in keeping with the prophecies once spoken about you, in order that with such encouragement you may fight the good fight.'
EXEC add_BibleVerse @BibleId, 354001019, N'To do this you must hold firmly to faith and a good conscience, which some have rejected and so have suffered shipwreck in regard to the faith.'
EXEC add_BibleVerse @BibleId, 354001020, N'Among these are Hymenaeus and Alexander, whom I handed over to Satan to be taught not to blaspheme.'
EXEC add_BibleVerse @BibleId, 354002001, N'First of all, then, I urge that requests, prayers, intercessions, and thanks be offered on behalf of all people,'
EXEC add_BibleVerse @BibleId, 354002002, N'even for kings and all who are in authority, that we may lead a peaceful and quiet life in all godliness and dignity.'
EXEC add_BibleVerse @BibleId, 354002003, N'Such prayer for all is good and welcomed before God our Savior,'
EXEC add_BibleVerse @BibleId, 354002004, N'since he wants all people to be saved and to come to a knowledge of the truth.'
EXEC add_BibleVerse @BibleId, 354002005, N'For there is one God and one intermediary between God and humanity, Christ Jesus, himself human,'
EXEC add_BibleVerse @BibleId, 354002006, N'who gave himself as a ransom for all, revealing God’s purpose at his appointed time.'
EXEC add_BibleVerse @BibleId, 354002007, N'For this I was appointed a preacher and apostle – I am telling the truth; I am not lying – and a teacher of the Gentiles in faith and truth.'
EXEC add_BibleVerse @BibleId, 354002008, N'So I want the men to pray in every place, lifting up holy hands without anger or dispute.'
EXEC add_BibleVerse @BibleId, 354002009, N'Likewise the women are to dress in suitable apparel, with modesty and self-control. Their adornment must not be with braided hair and gold or pearls or expensive clothing,'
EXEC add_BibleVerse @BibleId, 354002010, N'but with good deeds, as is proper for women who profess reverence for God.'
EXEC add_BibleVerse @BibleId, 354002011, N'A woman must learn quietly with all submissiveness.'
EXEC add_BibleVerse @BibleId, 354002012, N'But I do not allow a woman to teach or exercise authority over a man. She must remain quiet.'
EXEC add_BibleVerse @BibleId, 354002013, N'For Adam was formed first and then Eve.'
EXEC add_BibleVerse @BibleId, 354002014, N'And Adam was not deceived, but the woman, because she was fully deceived, fell into transgression.'
EXEC add_BibleVerse @BibleId, 354002015, N'But she will be delivered through childbearing, if she continues in faith and love and holiness with self-control.'
EXEC add_BibleVerse @BibleId, 354003001, N'This saying is trustworthy: “If someone aspires to the office of overseer, he desires a good work.”'
EXEC add_BibleVerse @BibleId, 354003002, N'The overseer then must be above reproach, the husband of one wife, temperate, self-controlled, respectable, hospitable, an able teacher,'
EXEC add_BibleVerse @BibleId, 354003003, N'not a drunkard, not violent, but gentle, not contentious, free from the love of money.'
EXEC add_BibleVerse @BibleId, 354003004, N'He must manage his own household well and keep his children in control without losing his dignity.'
EXEC add_BibleVerse @BibleId, 354003005, N'But if someone does not know how to manage his own household, how will he care for the church of God?'
EXEC add_BibleVerse @BibleId, 354003006, N'He must not be a recent convert or he may become arrogant and fall into the punishment that the devil will exact.'
EXEC add_BibleVerse @BibleId, 354003007, N'And he must be well thought of by those outside the faith, so that he may not fall into disgrace and be caught by the devil’s trap.'
EXEC add_BibleVerse @BibleId, 354003008, N'Deacons likewise must be dignified, not two-faced, not given to excessive drinking, not greedy for gain,'
EXEC add_BibleVerse @BibleId, 354003009, N'holding to the mystery of the faith with a clear conscience.'
EXEC add_BibleVerse @BibleId, 354003010, N'And these also must be tested first and then let them serve as deacons if they are found blameless.'
EXEC add_BibleVerse @BibleId, 354003011, N'Likewise also their wives must be dignified, not slanderous, temperate, faithful in every respect.'
EXEC add_BibleVerse @BibleId, 354003012, N'Deacons must be husbands of one wife and good managers of their children and their own households.'
EXEC add_BibleVerse @BibleId, 354003013, N'For those who have served well as deacons gain a good standing for themselves and great boldness in the faith that is in Christ Jesus.'
EXEC add_BibleVerse @BibleId, 354003014, N'I hope to come to you soon, but I am writing these instructions to you'
EXEC add_BibleVerse @BibleId, 354003015, N'in case I am delayed, to let you know how people ought to conduct themselves in the household of God, because it is the church of the living God, the support and bulwark of the truth.'
EXEC add_BibleVerse @BibleId, 354003016, N'And we all agree, our religion contains amazing revelation: He was revealed in the flesh, vindicated by the Spirit, seen by angels, proclaimed among Gentiles, believed on in the world, taken up in glory.'
EXEC add_BibleVerse @BibleId, 354004001, N'Now the Spirit explicitly says that in the later times some will desert the faith and occupy themselves with deceiving spirits and demonic teachings,'
EXEC add_BibleVerse @BibleId, 354004002, N'influenced by the hypocrisy of liars whose consciences are seared.'
EXEC add_BibleVerse @BibleId, 354004003, N'They will prohibit marriage and require abstinence from foods that God created to be received with thanksgiving by those who believe and know the truth.'
EXEC add_BibleVerse @BibleId, 354004004, N'For every creation of God is good and no food is to be rejected if it is received with thanksgiving.'
EXEC add_BibleVerse @BibleId, 354004005, N'For it is sanctified by God’s word and by prayer.'
EXEC add_BibleVerse @BibleId, 354004006, N'By pointing out such things to the brothers and sisters, you will be a good servant of Christ Jesus, having nourished yourself on the words of the faith and of the good teaching that you have followed.'
EXEC add_BibleVerse @BibleId, 354004007, N'But reject those myths fit only for the godless and gullible, and train yourself for godliness.'
EXEC add_BibleVerse @BibleId, 354004008, N'For “physical exercise has some value, but godliness is valuable in every way. It holds promise for the present life and for the life to come.”'
EXEC add_BibleVerse @BibleId, 354004009, N'This saying is trustworthy and deserves full acceptance.'
EXEC add_BibleVerse @BibleId, 354004010, N'In fact this is why we work hard and struggle, because we have set our hope on the living God, who is the Savior of all people, especially of believers.'
EXEC add_BibleVerse @BibleId, 354004011, N'Command and teach these things.'
EXEC add_BibleVerse @BibleId, 354004012, N'Let no one look down on you because you are young, but set an example for the believers in your speech, conduct, love, faithfulness, and purity.'
EXEC add_BibleVerse @BibleId, 354004013, N'Until I come, give attention to the public reading of scripture, to exhortation, to teaching.'
EXEC add_BibleVerse @BibleId, 354004014, N'Do not neglect the spiritual gift you have, given to you and confirmed by prophetic words when the elders laid hands on you.'
EXEC add_BibleVerse @BibleId, 354004015, N'Take pains with these things; be absorbed in them, so that everyone will see your progress.'
EXEC add_BibleVerse @BibleId, 354004016, N'Be conscientious about how you live and what you teach. Persevere in this, because by doing so you will save both yourself and those who listen to you.'
EXEC add_BibleVerse @BibleId, 354005001, N'Do not address an older man harshly but appeal to him as a father. Speak to younger men as brothers,'
EXEC add_BibleVerse @BibleId, 354005002, N'older women as mothers, and younger women as sisters – with complete purity.'
EXEC add_BibleVerse @BibleId, 354005003, N'Honor widows who are truly in need.'
EXEC add_BibleVerse @BibleId, 354005004, N'But if a widow has children or grandchildren, they should first learn to fulfill their duty toward their own household and so repay their parents what is owed them. For this is what pleases God.'
EXEC add_BibleVerse @BibleId, 354005005, N'But the widow who is truly in need, and completely on her own, has set her hope on God and continues in her pleas and prayers night and day.'
EXEC add_BibleVerse @BibleId, 354005006, N'But the one who lives for pleasure is dead even while she lives.'
EXEC add_BibleVerse @BibleId, 354005007, N'Reinforce these commands, so that they will be beyond reproach.'
EXEC add_BibleVerse @BibleId, 354005008, N'But if someone does not provide for his own, especially his own family, he has denied the faith and is worse than an unbeliever.'
EXEC add_BibleVerse @BibleId, 354005009, N'No widow should be put on the list unless she is at least sixty years old, was the wife of one husband,'
EXEC add_BibleVerse @BibleId, 354005010, N'and has a reputation for good works: as one who has raised children, practiced hospitality, washed the feet of the saints, helped those in distress – as one who has exhibited all kinds of good works.'
EXEC add_BibleVerse @BibleId, 354005011, N'But do not accept younger widows on the list, because their passions may lead them away from Christ and they will desire to marry,'
EXEC add_BibleVerse @BibleId, 354005012, N'and so incur judgment for breaking their former pledge.'
EXEC add_BibleVerse @BibleId, 354005013, N'And besides that, going around from house to house they learn to be lazy, and they are not only lazy, but also gossips and busybodies, talking about things they should not.'
EXEC add_BibleVerse @BibleId, 354005014, N'So I want younger women to marry, raise children, and manage a household, in order to give the adversary no opportunity to vilify us.'
EXEC add_BibleVerse @BibleId, 354005015, N'For some have already wandered away to follow Satan.'
EXEC add_BibleVerse @BibleId, 354005016, N'If a believing woman has widows in her family, let her help them. The church should not be burdened, so that it may help the widows who are truly in need.'
EXEC add_BibleVerse @BibleId, 354005017, N'Elders who provide effective leadership must be counted worthy of double honor, especially those who work hard in speaking and teaching.'
EXEC add_BibleVerse @BibleId, 354005018, N'For the scripture says, “ Do not muzzle an ox while it is treading out the grain,” and, “The worker deserves his pay.”'
EXEC add_BibleVerse @BibleId, 354005019, N'Do not accept an accusation against an elder unless it can be confirmed by two or three witnesses.'
EXEC add_BibleVerse @BibleId, 354005020, N'Those guilty of sin must be rebuked before all, as a warning to the rest.'
EXEC add_BibleVerse @BibleId, 354005021, N'Before God and Christ Jesus and the elect angels, I solemnly charge you to carry out these commands without prejudice or favoritism of any kind.'
EXEC add_BibleVerse @BibleId, 354005022, N'Do not lay hands on anyone hastily and so identify with the sins of others. Keep yourself pure.'
EXEC add_BibleVerse @BibleId, 354005023, N'(Stop drinking just water, but use a little wine for your digestion and your frequent illnesses.)'
EXEC add_BibleVerse @BibleId, 354005024, N'The sins of some people are obvious, going before them into judgment, but for others, they show up later.'
EXEC add_BibleVerse @BibleId, 354005025, N'Similarly good works are also obvious, and the ones that are not cannot remain hidden.'
EXEC add_BibleVerse @BibleId, 354006001, N'Those who are under the yoke as slaves must regard their own masters as deserving of full respect. This will prevent the name of God and Christian teaching from being discredited.'
EXEC add_BibleVerse @BibleId, 354006002, N'But those who have believing masters must not show them less respect because they are brothers. Instead they are to serve all the more, because those who benefit from their service are believers and dearly loved. Teach them and exhort them about these things.'
EXEC add_BibleVerse @BibleId, 354006003, N'If someone spreads false teachings and does not agree with sound words (that is, those of our Lord Jesus Christ) and with the teaching that accords with godliness,'
EXEC add_BibleVerse @BibleId, 354006004, N'he is conceited and understands nothing, but has an unhealthy interest in controversies and verbal disputes. This gives rise to envy, dissension, slanders, evil suspicions,'
EXEC add_BibleVerse @BibleId, 354006005, N'and constant bickering by people corrupted in their minds and deprived of the truth, who suppose that godliness is a way of making a profit.'
EXEC add_BibleVerse @BibleId, 354006006, N'Now godliness combined with contentment brings great profit.'
EXEC add_BibleVerse @BibleId, 354006007, N'For we have brought nothing into this world and so we cannot take a single thing out either.'
EXEC add_BibleVerse @BibleId, 354006008, N'But if we have food and shelter, we will be satisfied with that.'
EXEC add_BibleVerse @BibleId, 354006009, N'Those who long to be rich, however, stumble into temptation and a trap and many senseless and harmful desires that plunge people into ruin and destruction.'
EXEC add_BibleVerse @BibleId, 354006010, N'For the love of money is the root of all evils. Some people in reaching for it have strayed from the faith and stabbed themselves with many pains.'
EXEC add_BibleVerse @BibleId, 354006011, N'But you, as a person dedicated to God, keep away from all that. Instead pursue righteousness, godliness, faithfulness, love, endurance, and gentleness.'
EXEC add_BibleVerse @BibleId, 354006012, N'Compete well for the faith and lay hold of that eternal life you were called for and made your good confession for in the presence of many witnesses.'
EXEC add_BibleVerse @BibleId, 354006013, N'I charge you before God who gives life to all things and Christ Jesus who made his good confession before Pontius Pilate,'
EXEC add_BibleVerse @BibleId, 354006014, N'to obey this command without fault or failure until the appearing of our Lord Jesus Christ'
EXEC add_BibleVerse @BibleId, 354006015, N'– whose appearing the blessed and only Sovereign, the King of kings and Lord of lords, will reveal at the right time.'
EXEC add_BibleVerse @BibleId, 354006016, N'He alone possesses immortality and lives in unapproachable light, whom no human has ever seen or is able to see. To him be honor and eternal power! Amen.'
EXEC add_BibleVerse @BibleId, 354006017, N'Command those who are rich in this world’s goods not to be haughty or to set their hope on riches, which are uncertain, but on God who richly provides us with all things for our enjoyment.'
EXEC add_BibleVerse @BibleId, 354006018, N'Tell them to do good, to be rich in good deeds, to be generous givers, sharing with others.'
EXEC add_BibleVerse @BibleId, 354006019, N'In this way they will save up a treasure for themselves as a firm foundation for the future and so lay hold of what is truly life.'
EXEC add_BibleVerse @BibleId, 354006020, N'O Timothy, protect what has been entrusted to you. Avoid the profane chatter and absurdities of so-called “knowledge.”'
EXEC add_BibleVerse @BibleId, 354006021, N'By professing it, some have strayed from the faith. Grace be with you all.'
EXEC add_BibleVerse @BibleId, 355001001, N'From Paul, an apostle of Christ Jesus by the will of God, to further the promise of life in Christ Jesus,'
EXEC add_BibleVerse @BibleId, 355001002, N'to Timothy, my dear child. Grace, mercy, and peace from God the Father and Christ Jesus our Lord!'
EXEC add_BibleVerse @BibleId, 355001003, N'I am thankful to God, whom I have served with a clear conscience as my ancestors did, when I remember you in my prayers as I do constantly night and day.'
EXEC add_BibleVerse @BibleId, 355001004, N'As I remember your tears, I long to see you, so that I may be filled with joy.'
EXEC add_BibleVerse @BibleId, 355001005, N'I recall your sincere faith that was alive first in your grandmother Lois and in your mother Eunice, and I am sure is in you.'
EXEC add_BibleVerse @BibleId, 355001006, N'Because of this I remind you to rekindle God’s gift that you possess through the laying on of my hands.'
EXEC add_BibleVerse @BibleId, 355001007, N'For God did not give us a Spirit of fear but of power and love and self-control.'
EXEC add_BibleVerse @BibleId, 355001008, N'So do not be ashamed of the testimony about our Lord or of me, a prisoner for his sake, but by God’s power accept your share of suffering for the gospel.'
EXEC add_BibleVerse @BibleId, 355001009, N'He is the one who saved us and called us with a holy calling, not based on our works but on his own purpose and grace, granted to us in Christ Jesus before time began,'
EXEC add_BibleVerse @BibleId, 355001010, N'but now made visible through the appearing of our Savior Christ Jesus. He has broken the power of death and brought life and immortality to light through the gospel!'
EXEC add_BibleVerse @BibleId, 355001011, N'For this gospel I was appointed a preacher and apostle and teacher.'
EXEC add_BibleVerse @BibleId, 355001012, N'Because of this, in fact, I suffer as I do. But I am not ashamed, because I know the one in whom my faith is set and I am convinced that he is able to protect what has been entrusted to me until that day.'
EXEC add_BibleVerse @BibleId, 355001013, N'Hold to the standard of sound words that you heard from me and do so with the faith and love that are in Christ Jesus.'
EXEC add_BibleVerse @BibleId, 355001014, N'Protect that good thing entrusted to you, through the Holy Spirit who lives within us.'
EXEC add_BibleVerse @BibleId, 355001015, N'You know that everyone in the province of Asia deserted me, including Phygelus and Hermogenes.'
EXEC add_BibleVerse @BibleId, 355001016, N'May the Lord grant mercy to the family of Onesiphorus, because he often refreshed me and was not ashamed of my imprisonment.'
EXEC add_BibleVerse @BibleId, 355001017, N'But when he arrived in Rome, he eagerly searched for me and found me.'
EXEC add_BibleVerse @BibleId, 355001018, N'May the Lord grant him to find mercy from the Lord on that day! And you know very well all the ways he served me in Ephesus.'
EXEC add_BibleVerse @BibleId, 355002001, N'So you, my child, be strong in the grace that is in Christ Jesus.'
EXEC add_BibleVerse @BibleId, 355002002, N'And entrust what you heard me say in the presence of many others as witnesses to faithful people who will be competent to teach others as well.'
EXEC add_BibleVerse @BibleId, 355002003, N'Take your share of suffering as a good soldier of Christ Jesus.'
EXEC add_BibleVerse @BibleId, 355002004, N'No one in military service gets entangled in matters of everyday life; otherwise he will not please the one who recruited him.'
EXEC add_BibleVerse @BibleId, 355002005, N'Also, if anyone competes as an athlete, he will not be crowned as the winner unless he competes according to the rules.'
EXEC add_BibleVerse @BibleId, 355002006, N'The farmer who works hard ought to have the first share of the crops.'
EXEC add_BibleVerse @BibleId, 355002007, N'Think about what I am saying and the Lord will give you understanding of all this.'
EXEC add_BibleVerse @BibleId, 355002008, N'Remember Jesus Christ, raised from the dead, a descendant of David; such is my gospel,'
EXEC add_BibleVerse @BibleId, 355002009, N'for which I suffer hardship to the point of imprisonment as a criminal, but God’s message is not imprisoned!'
EXEC add_BibleVerse @BibleId, 355002010, N'So I endure all things for the sake of those chosen by God, that they too may obtain salvation in Christ Jesus and its eternal glory.'
EXEC add_BibleVerse @BibleId, 355002011, N'This saying is trustworthy: If we died with him, we will also live with him.'
EXEC add_BibleVerse @BibleId, 355002012, N'If we endure, we will also reign with him. If we deny him, he will also deny us.'
EXEC add_BibleVerse @BibleId, 355002013, N'If we are unfaithful, he remains faithful, since he cannot deny himself.'
EXEC add_BibleVerse @BibleId, 355002014, N'Remind people of these things and solemnly charge them before the Lord not to wrangle over words. This is of no benefit; it just brings ruin on those who listen.'
EXEC add_BibleVerse @BibleId, 355002015, N'Make every effort to present yourself before God as a proven worker who does not need to be ashamed, teaching the message of truth accurately.'
EXEC add_BibleVerse @BibleId, 355002016, N'But avoid profane chatter, because those occupied with it will stray further and further into ungodliness,'
EXEC add_BibleVerse @BibleId, 355002017, N'and their message will spread its infection like gangrene. Hymenaeus and Philetus are in this group.'
EXEC add_BibleVerse @BibleId, 355002018, N'They have strayed from the truth by saying that the resurrection has already occurred, and they are undermining some people’s faith.'
EXEC add_BibleVerse @BibleId, 355002019, N'However, God’s solid foundation remains standing, bearing this seal: “ The Lord knows those who are his,” and “Everyone who confesses the name of the Lord must turn away from evil.”'
EXEC add_BibleVerse @BibleId, 355002020, N'Now in a wealthy home there are not only gold and silver vessels, but also ones made of wood and of clay, and some are for honorable use, but others for ignoble use.'
EXEC add_BibleVerse @BibleId, 355002021, N'So if someone cleanses himself of such behavior, he will be a vessel for honorable use, set apart, useful for the Master, prepared for every good work.'
EXEC add_BibleVerse @BibleId, 355002022, N'But keep away from youthful passions, and pursue righteousness, faithfulness, love, and peace, in company with others who call on the Lord from a pure heart.'
EXEC add_BibleVerse @BibleId, 355002023, N'But reject foolish and ignorant controversies, because you know they breed infighting.'
EXEC add_BibleVerse @BibleId, 355002024, N'And the Lord’s slave must not engage in heated disputes but be kind toward all, an apt teacher, patient,'
EXEC add_BibleVerse @BibleId, 355002025, N'correcting opponents with gentleness. Perhaps God will grant them repentance and then knowledge of the truth'
EXEC add_BibleVerse @BibleId, 355002026, N'and they will come to their senses and escape the devil’s trap where they are held captive to do his will.'
EXEC add_BibleVerse @BibleId, 355003001, N'But understand this, that in the last days difficult times will come.'
EXEC add_BibleVerse @BibleId, 355003002, N'For people will be lovers of themselves, lovers of money, boastful, arrogant, blasphemers, disobedient to parents, ungrateful, unholy,'
EXEC add_BibleVerse @BibleId, 355003003, N'unloving, irreconcilable, slanderers, without self-control, savage, opposed to what is good,'
EXEC add_BibleVerse @BibleId, 355003004, N'treacherous, reckless, conceited, loving pleasure rather than loving God.'
EXEC add_BibleVerse @BibleId, 355003005, N'They will maintain the outward appearance of religion but will have repudiated its power. So avoid people like these.'
EXEC add_BibleVerse @BibleId, 355003006, N'For some of these insinuate themselves into households and captivate weak women who are overwhelmed with sins and led along by various passions.'
EXEC add_BibleVerse @BibleId, 355003007, N'Such women are always seeking instruction, yet never able to arrive at a knowledge of the truth.'
EXEC add_BibleVerse @BibleId, 355003008, N'And just as Jannes and Jambres opposed Moses, so these people – who have warped minds and are disqualified in the faith – also oppose the truth.'
EXEC add_BibleVerse @BibleId, 355003009, N'But they will not go much further, for their foolishness will be obvious to everyone, just like it was with Jannes and Jambres.'
EXEC add_BibleVerse @BibleId, 355003010, N'You, however, have followed my teaching, my way of life, my purpose, my faith, my patience, my love, my endurance,'
EXEC add_BibleVerse @BibleId, 355003011, N'as well as the persecutions and sufferings that happened to me in Antioch, I endured these persecutions and the Lord delivered me from them all.'
EXEC add_BibleVerse @BibleId, 355003012, N'Now in fact all who want to live godly lives in Christ Jesus will be persecuted.'
EXEC add_BibleVerse @BibleId, 355003013, N'But evil people and charlatans will go from bad to worse, deceiving others and being deceived themselves.'
EXEC add_BibleVerse @BibleId, 355003014, N'You, however, must continue in the things you have learned and are confident about. You know who taught you'
EXEC add_BibleVerse @BibleId, 355003015, N'and how from infancy you have known the holy writings, which are able to give you wisdom for salvation through faith in Christ Jesus.'
EXEC add_BibleVerse @BibleId, 355003016, N'Every scripture is inspired by God and useful for teaching, for reproof, for correction, and for training in righteousness,'
EXEC add_BibleVerse @BibleId, 355003017, N'that the person dedicated to God may be capable and equipped for every good work.'
EXEC add_BibleVerse @BibleId, 355004001, N'I solemnly charge you before God and Christ Jesus, who is going to judge the living and the dead, and by his appearing and his kingdom:'
EXEC add_BibleVerse @BibleId, 355004002, N'Preach the message, be ready whether it is convenient or not, reprove, rebuke, exhort with complete patience and instruction.'
EXEC add_BibleVerse @BibleId, 355004003, N'For there will be a time when people will not tolerate sound teaching. Instead, following their own desires, they will accumulate teachers for themselves, because they have an insatiable curiosity to hear new things.'
EXEC add_BibleVerse @BibleId, 355004004, N'And they will turn away from hearing the truth, but on the other hand they will turn aside to myths.'
EXEC add_BibleVerse @BibleId, 355004005, N'You, however, be self-controlled in all things, endure hardship, do an evangelist’s work, fulfill your ministry.'
EXEC add_BibleVerse @BibleId, 355004006, N'For I am already being poured out as an offering, and the time for me to depart is at hand.'
EXEC add_BibleVerse @BibleId, 355004007, N'I have competed well; I have finished the race; I have kept the faith!'
EXEC add_BibleVerse @BibleId, 355004008, N'Finally the crown of righteousness is reserved for me. The Lord, the righteous Judge, will award it to me in that day – and not to me only, but also to all who have set their affection on his appearing.'
EXEC add_BibleVerse @BibleId, 355004009, N'Make every effort to come to me soon.'
EXEC add_BibleVerse @BibleId, 355004010, N'For Demas deserted me, since he loved the present age, and he went to Thessalonica. Crescens went to Galatia and Titus to Dalmatia.'
EXEC add_BibleVerse @BibleId, 355004011, N'Only Luke is with me. Get Mark and bring him with you, because he is a great help to me in ministry.'
EXEC add_BibleVerse @BibleId, 355004012, N'Now I have sent Tychicus to Ephesus.'
EXEC add_BibleVerse @BibleId, 355004013, N'When you come, bring with you the cloak I left in Troas with Carpas and the scrolls, especially the parchments.'
EXEC add_BibleVerse @BibleId, 355004014, N'Alexander the coppersmith did me a great deal of harm. The Lord will repay him in keeping with his deeds.'
EXEC add_BibleVerse @BibleId, 355004015, N'You be on guard against him too, because he vehemently opposed our words.'
EXEC add_BibleVerse @BibleId, 355004016, N'At my first defense no one appeared in my support; instead they all deserted me – may they not be held accountable for it.'
EXEC add_BibleVerse @BibleId, 355004017, N'But the Lord stood by me and strengthened me, so that through me the message would be fully proclaimed for all the Gentiles to hear. And so I was delivered from the lion’s mouth!'
EXEC add_BibleVerse @BibleId, 355004018, N'The Lord will deliver me from every evil deed and will bring me safely into his heavenly kingdom. To him be glory for ever and ever! Amen.'
EXEC add_BibleVerse @BibleId, 355004019, N'Greetings to Prisca and Aquila and the family of Onesiphorus.'
EXEC add_BibleVerse @BibleId, 355004020, N'Erastus stayed in Corinth. Trophimus I left ill in Miletus.'
EXEC add_BibleVerse @BibleId, 355004021, N'Make every effort to come before winter. Greetings to you from Eubulus, Pudens, Linus, Claudia, and all the brothers and sisters.'
EXEC add_BibleVerse @BibleId, 355004022, N'The Lord be with your spirit. Grace be with you.'
EXEC add_BibleVerse @BibleId, 356001001, N'From Paul, a slave of God and apostle of Jesus Christ, to further the faith of God’s chosen ones and the knowledge of the truth that is in keeping with godliness,'
EXEC add_BibleVerse @BibleId, 356001002, N'in hope of eternal life, which God, who does not lie, promised before the ages began.'
EXEC add_BibleVerse @BibleId, 356001003, N'But now in his own time he has made his message evident through the preaching I was entrusted with according to the command of God our Savior.'
EXEC add_BibleVerse @BibleId, 356001004, N'To Titus, my genuine son in a common faith. Grace and peace from God the Father and Christ Jesus our Savior!'
EXEC add_BibleVerse @BibleId, 356001005, N'The reason I left you in Crete was to set in order the remaining matters and to appoint elders in every town, as I directed you.'
EXEC add_BibleVerse @BibleId, 356001006, N'An elder must be blameless, the husband of one wife, with faithful children who cannot be charged with dissipation or rebellion.'
EXEC add_BibleVerse @BibleId, 356001007, N'For the overseer must be blameless as one entrusted with God’s work, not arrogant, not prone to anger, not a drunkard, not violent, not greedy for gain.'
EXEC add_BibleVerse @BibleId, 356001008, N'Instead he must be hospitable, devoted to what is good, sensible, upright, devout, and self-controlled.'
EXEC add_BibleVerse @BibleId, 356001009, N'He must hold firmly to the faithful message as it has been taught, so that he will be able to give exhortation in such healthy teaching and correct those who speak against it.'
EXEC add_BibleVerse @BibleId, 356001010, N'For there are many rebellious people, idle talkers, and deceivers, especially those with Jewish connections,'
EXEC add_BibleVerse @BibleId, 356001011, N'who must be silenced because they mislead whole families by teaching for dishonest gain what ought not to be taught.'
EXEC add_BibleVerse @BibleId, 356001012, N'A certain one of them, in fact, one of their own prophets, said, “Cretans are always liars, evil beasts, lazy gluttons.”'
EXEC add_BibleVerse @BibleId, 356001013, N'Such testimony is true. For this reason rebuke them sharply that they may be healthy in the faith'
EXEC add_BibleVerse @BibleId, 356001014, N'and not pay attention to Jewish myths and commands of people who reject the truth.'
EXEC add_BibleVerse @BibleId, 356001015, N'All is pure to those who are pure. But to those who are corrupt and unbelieving, nothing is pure, but both their minds and consciences are corrupted.'
EXEC add_BibleVerse @BibleId, 356001016, N'They profess to know God but with their deeds they deny him, since they are detestable, disobedient, and unfit for any good deed.'
EXEC add_BibleVerse @BibleId, 356002001, N'But as for you, communicate the behavior that goes with sound teaching.'
EXEC add_BibleVerse @BibleId, 356002002, N'Older men are to be temperate, dignified, self-controlled, sound in faith, in love, and in endurance.'
EXEC add_BibleVerse @BibleId, 356002003, N'Older women likewise are to exhibit behavior fitting for those who are holy, not slandering, not slaves to excessive drinking, but teaching what is good.'
EXEC add_BibleVerse @BibleId, 356002004, N'In this way they will train the younger women to love their husbands, to love their children,'
EXEC add_BibleVerse @BibleId, 356002005, N'to be self-controlled, pure, fulfilling their duties at home, kind, being subject to their own husbands, so that the message of God may not be discredited.'
EXEC add_BibleVerse @BibleId, 356002006, N'Encourage younger men likewise to be self-controlled,'
EXEC add_BibleVerse @BibleId, 356002007, N'showing yourself to be an example of good works in every way. In your teaching show integrity, dignity,'
EXEC add_BibleVerse @BibleId, 356002008, N'and a sound message that cannot be criticized, so that any opponent will be at a loss, because he has nothing evil to say about us.'
EXEC add_BibleVerse @BibleId, 356002009, N'Slaves are to be subject to their own masters in everything, to do what is wanted and not talk back,'
EXEC add_BibleVerse @BibleId, 356002010, N'not pilfering, but showing all good faith, in order to bring credit to the teaching of God our Savior in everything.'
EXEC add_BibleVerse @BibleId, 356002011, N'For the grace of God has appeared, bringing salvation to all people.'
EXEC add_BibleVerse @BibleId, 356002012, N'It trains us to reject godless ways and worldly desires and to live self-controlled, upright, and godly lives in the present age,'
EXEC add_BibleVerse @BibleId, 356002013, N'as we wait for the happy fulfillment of our hope in the glorious appearing of our great God and Savior, Jesus Christ.'
EXEC add_BibleVerse @BibleId, 356002014, N'He gave himself for us to set us free from every kind of lawlessness and to purify for himself a people who are truly his, who are eager to do good.'
EXEC add_BibleVerse @BibleId, 356002015, N'So communicate these things with the sort of exhortation or rebuke that carries full authority. Don’t let anyone look down on you.'
EXEC add_BibleVerse @BibleId, 356003001, N'Remind them to be subject to rulers and authorities, to be obedient, to be ready for every good work.'
EXEC add_BibleVerse @BibleId, 356003002, N'They must not slander anyone, but be peaceable, gentle, showing complete courtesy to all people.'
EXEC add_BibleVerse @BibleId, 356003003, N'For we too were once foolish, disobedient, misled, enslaved to various passions and desires, spending our lives in evil and envy, hateful and hating one another.'
EXEC add_BibleVerse @BibleId, 356003004, N'But “when the kindness of God our Savior and his love for mankind appeared,'
EXEC add_BibleVerse @BibleId, 356003005, N'he saved us not by works of righteousness that we have done but on the basis of his mercy, through the washing of the new birth and the renewing of the Holy Spirit,'
EXEC add_BibleVerse @BibleId, 356003006, N'whom he poured out on us in full measure through Jesus Christ our Savior.'
EXEC add_BibleVerse @BibleId, 356003007, N'And so, since we have been justified by his grace, we become heirs with the confident expectation of eternal life.”'
EXEC add_BibleVerse @BibleId, 356003008, N'This saying is trustworthy, and I want you to insist on such truths, so that those who have placed their faith in God may be intent on engaging in good works. These things are good and beneficial for all people.'
EXEC add_BibleVerse @BibleId, 356003009, N'But avoid foolish controversies, genealogies, quarrels, and fights about the law, because they are useless and empty.'
EXEC add_BibleVerse @BibleId, 356003010, N'Reject a divisive person after one or two warnings.'
EXEC add_BibleVerse @BibleId, 356003011, N'You know that such a person is twisted by sin and is conscious of it himself.'
EXEC add_BibleVerse @BibleId, 356003012, N'When I send Artemas or Tychicus to you, do your best to come to me at Nicopolis, for I have decided to spend the winter there.'
EXEC add_BibleVerse @BibleId, 356003013, N'Make every effort to help Zenas the lawyer and Apollos on their way; make sure they have what they need.'
EXEC add_BibleVerse @BibleId, 356003014, N'Here is another way that our people can learn to engage in good works to meet pressing needs and so not be unfruitful.'
EXEC add_BibleVerse @BibleId, 356003015, N'Everyone with me greets you. Greet those who love us in the faith. Grace be with you all.'
EXEC add_BibleVerse @BibleId, 357001001, N'From Paul, a prisoner of Christ Jesus, and Timothy our brother, to Philemon, our dear friend and colaborer,'
EXEC add_BibleVerse @BibleId, 357001002, N'to Apphia our sister, to Archippus our fellow soldier, and to the church that meets in your house.'
EXEC add_BibleVerse @BibleId, 357001003, N'Grace and peace to you from God our Father and the Lord Jesus Christ!'
EXEC add_BibleVerse @BibleId, 357001004, N'I always thank my God as I remember you in my prayers,'
EXEC add_BibleVerse @BibleId, 357001005, N'because I hear of your faith in the Lord Jesus and your love for all the saints.'
EXEC add_BibleVerse @BibleId, 357001006, N'I pray that the faith you share with us may deepen your understanding of every blessing that belongs to you in Christ.'
EXEC add_BibleVerse @BibleId, 357001007, N'I have had great joy and encouragement because of your love, for the hearts of the saints have been refreshed through you, brother.'
EXEC add_BibleVerse @BibleId, 357001008, N'So, although I have quite a lot of confidence in Christ and could command you to do what is proper,'
EXEC add_BibleVerse @BibleId, 357001009, N'I would rather appeal to you on the basis of love – I, Paul, an old man and even now a prisoner for the sake of Christ Jesus –'
EXEC add_BibleVerse @BibleId, 357001010, N'I am appealing to you concerning my child, whose spiritual father I have become during my imprisonment, that is, Onesimus,'
EXEC add_BibleVerse @BibleId, 357001011, N'who was formerly useless to you, but is now useful to you and me.'
EXEC add_BibleVerse @BibleId, 357001012, N'I have sent him (who is my very heart) back to you.'
EXEC add_BibleVerse @BibleId, 357001013, N'I wanted to keep him so that he could serve me in your place during my imprisonment for the sake of the gospel.'
EXEC add_BibleVerse @BibleId, 357001014, N'However, without your consent I did not want to do anything, so that your good deed would not be out of compulsion, but from your own willingness.'
EXEC add_BibleVerse @BibleId, 357001015, N'For perhaps it was for this reason that he was separated from you for a little while, so that you would have him back eternally,'
EXEC add_BibleVerse @BibleId, 357001016, N'no longer as a slave, but more than a slave, as a dear brother. He is especially so to me, and even more so to you now, both humanly speaking and in the Lord.'
EXEC add_BibleVerse @BibleId, 357001017, N'Therefore if you regard me as a partner, accept him as you would me.'
EXEC add_BibleVerse @BibleId, 357001018, N'Now if he has defrauded you of anything or owes you anything, charge what he owes to me.'
EXEC add_BibleVerse @BibleId, 357001019, N'I, Paul, have written this letter with my own hand: I will repay it. I could also mention that you owe me your very self.'
EXEC add_BibleVerse @BibleId, 357001020, N'Yes, brother, let me have some benefit from you in the Lord. Refresh my heart in Christ.'
EXEC add_BibleVerse @BibleId, 357001021, N'Since I was confident that you would obey, I wrote to you, because I knew that you would do even more than what I am asking you to do.'
EXEC add_BibleVerse @BibleId, 357001022, N'At the same time also, prepare a place for me to stay, for I hope that through your prayers I will be given back to you.'
EXEC add_BibleVerse @BibleId, 357001023, N'Epaphras, my fellow prisoner in Christ Jesus, greets you.'
EXEC add_BibleVerse @BibleId, 357001024, N'Mark, Aristarchus, Demas and Luke, my colaborers, greet you too.'
EXEC add_BibleVerse @BibleId, 357001025, N'May the grace of the Lord Jesus Christ be with your spirit.'
EXEC add_BibleVerse @BibleId, 358001001, N'After God spoke long ago in various portions and in various ways to our ancestors through the prophets,'
EXEC add_BibleVerse @BibleId, 358001002, N'in these last days he has spoken to us in a son, whom he appointed heir of all things, and through whom he created the world.'
EXEC add_BibleVerse @BibleId, 358001003, N'The Son is the radiance of his glory and the representation of his essence, and he sustains all things by his powerful word, and so when he had accomplished cleansing for sins, he sat down at the right hand of the Majesty on high.'
EXEC add_BibleVerse @BibleId, 358001004, N'Thus he became so far better than the angels as he has inherited a name superior to theirs.'
EXEC add_BibleVerse @BibleId, 358001005, N'For to which of the angels did God ever say, “ You are my son! Today I have fathered you”? And in another place he says, “ I will be his father and he will be my son.”'
EXEC add_BibleVerse @BibleId, 358001006, N'But when he again brings his firstborn into the world, he says, “ Let all the angels of God worship him!”'
EXEC add_BibleVerse @BibleId, 358001007, N'And he says of the angels, “ He makes his angels spirits and his ministers a flame of fire,”'
EXEC add_BibleVerse @BibleId, 358001008, N'but of the Son he says, “ Your throne, O God, is forever and ever, and a righteous scepter is the scepter of your kingdom.'
EXEC add_BibleVerse @BibleId, 358001009, N'You have loved righteousness and hated lawlessness. So God, your God, has anointed you over your companions with the oil of rejoicing.”'
EXEC add_BibleVerse @BibleId, 358001010, N'And, “ You founded the earth in the beginning, Lord, and the heavens are the works of your hands.'
EXEC add_BibleVerse @BibleId, 358001011, N'They will perish, but you continue. And they will all grow old like a garment,'
EXEC add_BibleVerse @BibleId, 358001012, N'and like a robe you will fold them up and like a garment they will be changed, but you are the same and your years will never run out.”'
EXEC add_BibleVerse @BibleId, 358001013, N'But to which of the angels has he ever said, “ Sit at my right hand until I make your enemies a footstool for your feet”?'
EXEC add_BibleVerse @BibleId, 358001014, N'Are they not all ministering spirits, sent out to serve those who will inherit salvation?'
EXEC add_BibleVerse @BibleId, 358002001, N'Therefore we must pay closer attention to what we have heard, so that we do not drift away.'
EXEC add_BibleVerse @BibleId, 358002002, N'For if the message spoken through angels proved to be so firm that every violation or disobedience received its just penalty,'
EXEC add_BibleVerse @BibleId, 358002003, N'how will we escape if we neglect such a great salvation? It was first communicated through the Lord and was confirmed to us by those who heard him,'
EXEC add_BibleVerse @BibleId, 358002004, N'while God confirmed their witness with signs and wonders and various miracles and gifts of the Holy Spirit distributed according to his will.'
EXEC add_BibleVerse @BibleId, 358002005, N'For he did not put the world to come, about which we are speaking, under the control of angels.'
EXEC add_BibleVerse @BibleId, 358002006, N'Instead someone testified somewhere: “ What is man that you think of him or the son of man that you care for him?'
EXEC add_BibleVerse @BibleId, 358002007, N'You made him lower than the angels for a little while. You crowned him with glory and honor.'
EXEC add_BibleVerse @BibleId, 358002008, N'You put all things under his control.” For when he put all things under his control, he left nothing outside of his control. At present we do not yet see all things under his control,'
EXEC add_BibleVerse @BibleId, 358002009, N'but we see Jesus, who was made lower than the angels for a little while, now crowned with glory and honor because he suffered death, so that by God’s grace he would experience death on behalf of everyone.'
EXEC add_BibleVerse @BibleId, 358002010, N'For it was fitting for him, for whom and through whom all things exist, in bringing many sons to glory, to make the pioneer of their salvation perfect through sufferings.'
EXEC add_BibleVerse @BibleId, 358002011, N'For indeed he who makes holy and those being made holy all have the same origin, and so he is not ashamed to call them brothers and sisters,'
EXEC add_BibleVerse @BibleId, 358002012, N'saying, “ I will proclaim your name to my brothers; in the midst of the assembly I will praise you*.”'
EXEC add_BibleVerse @BibleId, 358002013, N'Again he says, “I will be confident in him,” and again, “ Here I am, with the children God has given me*.”'
EXEC add_BibleVerse @BibleId, 358002014, N'Therefore, since the children share in flesh and blood, he likewise shared in their humanity, so that through death he could destroy the one who holds the power of death (that is, the devil),'
EXEC add_BibleVerse @BibleId, 358002015, N'and set free those who were held in slavery all their lives by their fear of death.'
EXEC add_BibleVerse @BibleId, 358002016, N'For surely his concern is not for angels, but he is concerned for Abraham’s descendants.'
EXEC add_BibleVerse @BibleId, 358002017, N'Therefore he had to be made like his brothers and sisters in every respect, so that he could become a merciful and faithful high priest in things relating to God, to make atonement for the sins of the people.'
EXEC add_BibleVerse @BibleId, 358002018, N'For since he himself suffered when he was tempted, he is able to help those who are tempted.'
EXEC add_BibleVerse @BibleId, 358003001, N'Therefore, holy brothers and sisters, partners in a heavenly calling, take note of Jesus, the apostle and high priest whom we confess,'
EXEC add_BibleVerse @BibleId, 358003002, N'who is faithful to the one who appointed him, as Moses was also in God’s house.'
EXEC add_BibleVerse @BibleId, 358003003, N'For he has come to deserve greater glory than Moses, just as the builder of a house deserves greater honor than the house itself!'
EXEC add_BibleVerse @BibleId, 358003004, N'For every house is built by someone, but the builder of all things is God.'
EXEC add_BibleVerse @BibleId, 358003005, N'Now Moses was faithful in all God’s house as a servant, to testify to the things that would be spoken.'
EXEC add_BibleVerse @BibleId, 358003006, N'But Christ is faithful as a son over God’s house. We are of his house, if in fact we hold firmly to our confidence and the hope we take pride in.'
EXEC add_BibleVerse @BibleId, 358003007, N'Therefore, as the Holy Spirit says, “ Oh, that today you would listen as he speaks!'
EXEC add_BibleVerse @BibleId, 358003008, N'“ Do not harden your hearts as in the rebellion, in the day of testing in the wilderness.'
EXEC add_BibleVerse @BibleId, 358003009, N'“ There your fathers tested me and tried me, and they saw my works for forty years.'
EXEC add_BibleVerse @BibleId, 358003010, N'“ Therefore, I became provoked at that generation and said, ‘Their hearts are always wandering and they have not known my ways.’'
EXEC add_BibleVerse @BibleId, 358003011, N'“ As I swore in my anger, ‘They will never enter my rest!’”'
EXEC add_BibleVerse @BibleId, 358003012, N'See to it, brothers and sisters, that none of you has an evil, unbelieving heart that forsakes the living God.'
EXEC add_BibleVerse @BibleId, 358003013, N'But exhort one another each day, as long as it is called “Today,” that none of you may become hardened by sin’s deception.'
EXEC add_BibleVerse @BibleId, 358003014, N'For we have become partners with Christ, if in fact we hold our initial confidence firm until the end.'
EXEC add_BibleVerse @BibleId, 358003015, N'As it says, “ O, that today you would listen as he speaks! Do not harden your hearts as in the rebellion.”'
EXEC add_BibleVerse @BibleId, 358003016, N'For which ones heard and rebelled? Was it not all who came out of Egypt under Moses’ leadership?'
EXEC add_BibleVerse @BibleId, 358003017, N'And against whom was God provoked for forty years? Was it not those who sinned, whose dead bodies fell in the wilderness?'
EXEC add_BibleVerse @BibleId, 358003018, N'And to whom did he swear they would never enter into his rest, except those who were disobedient?'
EXEC add_BibleVerse @BibleId, 358003019, N'So we see that they could not enter because of unbelief.'
EXEC add_BibleVerse @BibleId, 358004001, N'Therefore we must be wary that, while the promise of entering his rest remains open, none of you may seem to have come short of it.'
EXEC add_BibleVerse @BibleId, 358004002, N'For we had good news proclaimed to us just as they did. But the message they heard did them no good, since they did not join in with those who heard it in faith.'
EXEC add_BibleVerse @BibleId, 358004003, N'For we who have believed enter that rest, as he has said, “ As I swore in my anger, ‘They will never enter my rest!’” And yet God’s works were accomplished from the foundation of the world.'
EXEC add_BibleVerse @BibleId, 358004004, N'For he has spoken somewhere about the seventh day in this way: “ And God rested on the seventh day from all his works,”'
EXEC add_BibleVerse @BibleId, 358004005, N'but to repeat the text cited earlier: “ They will never enter my rest!”'
EXEC add_BibleVerse @BibleId, 358004006, N'Therefore it remains for some to enter it, yet those to whom it was previously proclaimed did not enter because of disobedience.'
EXEC add_BibleVerse @BibleId, 358004007, N'So God again ordains a certain day, “Today,” speaking through David after so long a time, as in the words quoted before, “ O, that today you would listen as he speaks! Do not harden your hearts.”'
EXEC add_BibleVerse @BibleId, 358004008, N'For if Joshua had given them rest, God would not have spoken afterward about another day.'
EXEC add_BibleVerse @BibleId, 358004009, N'Consequently a Sabbath rest remains for the people of God.'
EXEC add_BibleVerse @BibleId, 358004010, N'For the one who enters God’s rest has also rested from his works, just as God did from his own works.'
EXEC add_BibleVerse @BibleId, 358004011, N'Thus we must make every effort to enter that rest, so that no one may fall by following the same pattern of disobedience.'
EXEC add_BibleVerse @BibleId, 358004012, N'For the word of God is living and active and sharper than any double-edged sword, piercing even to the point of dividing soul from spirit, and joints from marrow; it is able to judge the desires and thoughts of the heart.'
EXEC add_BibleVerse @BibleId, 358004013, N'And no creature is hidden from God, but everything is naked and exposed to the eyes of him to whom we must render an account.'
EXEC add_BibleVerse @BibleId, 358004014, N'Therefore since we have a great high priest who has passed through the heavens, Jesus the Son of God, let us hold fast to our confession.'
EXEC add_BibleVerse @BibleId, 358004015, N'For we do not have a high priest incapable of sympathizing with our weaknesses, but one who has been tempted in every way just as we are, yet without sin.'
EXEC add_BibleVerse @BibleId, 358004016, N'Therefore let us confidently approach the throne of grace to receive mercy and find grace whenever we need help.'
EXEC add_BibleVerse @BibleId, 358005001, N'For every high priest is taken from among the people and appointed to represent them before God, to offer both gifts and sacrifices for sins.'
EXEC add_BibleVerse @BibleId, 358005002, N'He is able to deal compassionately with those who are ignorant and erring, since he also is subject to weakness,'
EXEC add_BibleVerse @BibleId, 358005003, N'and for this reason he is obligated to make sin offerings for himself as well as for the people.'
EXEC add_BibleVerse @BibleId, 358005004, N'And no one assumes this honor on his own initiative, but only when called to it by God, as in fact Aaron was.'
EXEC add_BibleVerse @BibleId, 358005005, N'So also Christ did not glorify himself in becoming high priest, but the one who glorified him was God, who said to him, “ You are my Son! Today I have fathered you,”'
EXEC add_BibleVerse @BibleId, 358005006, N'as also in another place God says, “ You are a priest forever in the order of Melchizedek.”'
EXEC add_BibleVerse @BibleId, 358005007, N'During his earthly life Christ offered both requests and supplications, with loud cries and tears, to the one who was able to save him from death and he was heard because of his devotion.'
EXEC add_BibleVerse @BibleId, 358005008, N'Although he was a son, he learned obedience through the things he suffered.'
EXEC add_BibleVerse @BibleId, 358005009, N'And by being perfected in this way, he became the source of eternal salvation to all who obey him,'
EXEC add_BibleVerse @BibleId, 358005010, N'and he was designated by God as high priest in the order of Melchizedek.'
EXEC add_BibleVerse @BibleId, 358005011, N'On this topic we have much to say and it is difficult to explain, since you have become sluggish in hearing.'
EXEC add_BibleVerse @BibleId, 358005012, N'For though you should in fact be teachers by this time, you need someone to teach you the beginning elements of God’s utterances. You have gone back to needing milk, not solid food.'
EXEC add_BibleVerse @BibleId, 358005013, N'For everyone who lives on milk is inexperienced in the message of righteousness, because he is an infant.'
EXEC add_BibleVerse @BibleId, 358005014, N'But solid food is for the mature, whose perceptions are trained by practice to discern both good and evil.'
EXEC add_BibleVerse @BibleId, 358006001, N'Therefore we must progress beyond the elementary instructions about Christ and move on to maturity, not laying this foundation again: repentance from dead works and faith in God,'
EXEC add_BibleVerse @BibleId, 358006002, N'teaching about baptisms, laying on of hands, resurrection of the dead, and eternal judgment.'
EXEC add_BibleVerse @BibleId, 358006003, N'And this is what we intend to do, if God permits.'
EXEC add_BibleVerse @BibleId, 358006004, N'For it is impossible in the case of those who have once been enlightened, tasted the heavenly gift, become partakers of the Holy Spirit,'
EXEC add_BibleVerse @BibleId, 358006005, N'tasted the good word of God and the miracles of the coming age,'
EXEC add_BibleVerse @BibleId, 358006006, N'and then have committed apostasy, to renew them again to repentance, since they are crucifying the Son of God for themselves all over again and holding him up to contempt.'
EXEC add_BibleVerse @BibleId, 358006007, N'For the ground that has soaked up the rain that frequently falls on it and yields useful vegetation for those who tend it receives a blessing from God.'
EXEC add_BibleVerse @BibleId, 358006008, N'But if it produces thorns and thistles, it is useless and about to be cursed; its fate is to be burned.'
EXEC add_BibleVerse @BibleId, 358006009, N'But in your case, dear friends, even though we speak like this, we are convinced of better things relating to salvation.'
EXEC add_BibleVerse @BibleId, 358006010, N'For God is not unjust so as to forget your work and the love you have demonstrated for his name, in having served and continuing to serve the saints.'
EXEC add_BibleVerse @BibleId, 358006011, N'But we passionately want each of you to demonstrate the same eagerness for the fulfillment of your hope until the end,'
EXEC add_BibleVerse @BibleId, 358006012, N'so that you may not be sluggish, but imitators of those who through faith and perseverance inherit the promises.'
EXEC add_BibleVerse @BibleId, 358006013, N'Now when God made his promise to Abraham, since he could swear by no one greater, he swore by himself,'
EXEC add_BibleVerse @BibleId, 358006014, N'saying, “ Surely I will bless you greatly and multiply your descendants abundantly.”'
EXEC add_BibleVerse @BibleId, 358006015, N'And so by persevering, Abraham inherited the promise.'
EXEC add_BibleVerse @BibleId, 358006016, N'For people swear by something greater than themselves, and the oath serves as a confirmation to end all dispute.'
EXEC add_BibleVerse @BibleId, 358006017, N'In the same way God wanted to demonstrate more clearly to the heirs of the promise that his purpose was unchangeable, and so he intervened with an oath,'
EXEC add_BibleVerse @BibleId, 358006018, N'so that we who have found refuge in him may find strong encouragement to hold fast to the hope set before us through two unchangeable things, since it is impossible for God to lie.'
EXEC add_BibleVerse @BibleId, 358006019, N'We have this hope as an anchor for the soul, sure and steadfast, which reaches inside behind the curtain,'
EXEC add_BibleVerse @BibleId, 358006020, N'where Jesus our forerunner entered on our behalf, since he became a priest forever in the order of Melchizedek forever in the order of Melchizedek.'
EXEC add_BibleVerse @BibleId, 358007001, N'Now this Melchizedek, king of Salem, priest of the most high God, met Abraham as he was returning from defeating the kings and blessed him.'
EXEC add_BibleVerse @BibleId, 358007002, N'To him also t Abraham apportioned a tithe apportioned a tithe of everything. His name first means king of righteousness, then king of Salem of Salem, that is, king of peace.'
EXEC add_BibleVerse @BibleId, 358007003, N'Without father, without mother, without genealogy, he has neither beginning of days nor end of life but is like the son of God, and he remains a priest for all time.'
EXEC add_BibleVerse @BibleId, 358007004, N'But see how great he must be, if Abraham the patriarch gave him a tithe of his plunder.'
EXEC add_BibleVerse @BibleId, 358007005, N'And those of the sons of Levi who receive the priestly office have authorization according to the law to collect a tithe from the people, that is, from their fellow countrymen, although they too are descendants of Abraham.'
EXEC add_BibleVerse @BibleId, 358007006, N'But Melchizedek who does not share their ancestry collected a tithe from Abraham and blessed the one who possessed the promise.'
EXEC add_BibleVerse @BibleId, 358007007, N'Now without dispute the inferior is blessed by the superior,'
EXEC add_BibleVerse @BibleId, 358007008, N'and in one case tithes are received by mortal men, while in the other by him who is affirmed to be alive.'
EXEC add_BibleVerse @BibleId, 358007009, N'And it could be said that Levi himself, who receives tithes, paid a tithe through Abraham.'
EXEC add_BibleVerse @BibleId, 358007010, N'For he was still in his ancestor Abraham’s loins when Melchizedek met him.'
EXEC add_BibleVerse @BibleId, 358007011, N'So if perfection had in fact been possible through the Levitical priesthood – for on that basis the people received the law – what further need would there have been for another priest to arise, said to be in the order of Melchizedek and not in Aaron’s order?'
EXEC add_BibleVerse @BibleId, 358007012, N'For when the priesthood changes, a change in the law must come as well.'
EXEC add_BibleVerse @BibleId, 358007013, N'Yet the one these things are spoken about belongs to a different tribe, and no one from that tribe has ever officiated at the altar.'
EXEC add_BibleVerse @BibleId, 358007014, N'For it is clear that our Lord is descended from Judah, yet Moses said nothing about priests in connection with that tribe.'
EXEC add_BibleVerse @BibleId, 358007015, N'And this is even clearer if another priest arises in the likeness of Melchizedek,'
EXEC add_BibleVerse @BibleId, 358007016, N'who has become a priest not by a legal regulation about physical descent but by the power of an indestructible life.'
EXEC add_BibleVerse @BibleId, 358007017, N'For here is the testimony about him: “ You are a priest forever in the order of Melchizedek.”'
EXEC add_BibleVerse @BibleId, 358007018, N'On the one hand a former command is set aside because it is weak and useless,'
EXEC add_BibleVerse @BibleId, 358007019, N'for the law made nothing perfect. On the other hand a better hope is introduced, through which we draw near to God.'
EXEC add_BibleVerse @BibleId, 358007020, N'And since this was not done without a sworn affirmation – for the others have become priests without a sworn affirmation,'
EXEC add_BibleVerse @BibleId, 358007021, N'but Jesus did so with a sworn affirmation by the one who said to him, “ The Lord has sworn and will not change his mind, ‘You are a priest forever’” –'
EXEC add_BibleVerse @BibleId, 358007022, N'accordingly Jesus has become the guarantee of a better covenant.'
EXEC add_BibleVerse @BibleId, 358007023, N'And the others who became priests were numerous, because death prevented them from continuing in office,'
EXEC add_BibleVerse @BibleId, 358007024, N'but he holds his priesthood permanently since he lives forever.'
EXEC add_BibleVerse @BibleId, 358007025, N'So he is able to save completely those who come to God through him, because he always lives to intercede for them.'
EXEC add_BibleVerse @BibleId, 358007026, N'For it is indeed fitting for us to have such a high priest: holy, innocent, undefiled, separate from sinners, and exalted above the heavens.'
EXEC add_BibleVerse @BibleId, 358007027, N'He has no need to do every day what those priests do, to offer sacrifices first for their own sins and then for the sins of the people, since he did this in offering himself once for all.'
EXEC add_BibleVerse @BibleId, 358007028, N'For the law appoints as high priests men subject to weakness, but the word of solemn affirmation that came after the law appoints a son made perfect forever.'
EXEC add_BibleVerse @BibleId, 358008001, N'Now the main point of what we are saying is this: We have such a high priest, one who sat down at the right hand of the throne of the Majesty in heaven,'
EXEC add_BibleVerse @BibleId, 358008002, N'a minister in the sanctuary and the true tabernacle that the Lord, not man, set up.'
EXEC add_BibleVerse @BibleId, 358008003, N'For every high priest is appointed to offer both gifts and sacrifices. So this one too had to have something to offer.'
EXEC add_BibleVerse @BibleId, 358008004, N'Now if he were on earth, he would not be a priest, since there are already priests who offer the gifts prescribed by the law.'
EXEC add_BibleVerse @BibleId, 358008005, N'The place where they serve is a sketch and shadow of the heavenly sanctuary, just as Moses was warned by God as he was about to complete the tabernacle. For he says, “ See that you make everything according to the design shown to you on the mountain.”'
EXEC add_BibleVerse @BibleId, 358008006, N'But now Jesus has obtained a superior ministry, since the covenant that he mediates is also better and is enacted on better promises.'
EXEC add_BibleVerse @BibleId, 358008007, N'For if that first covenant had been faultless, no one would have looked for a second one.'
EXEC add_BibleVerse @BibleId, 358008008, N'But showing its fault, God says to them, “ Look, the days are coming, says the Lord, when I will complete a new covenant with the house of Israel and with the house of Judah.'
EXEC add_BibleVerse @BibleId, 358008009, N'“ It will not be like the covenant that I made with their fathers, on the day when I took them by the hand to lead them out of Egypt, because they did not continue in my covenant and I had no regard for them, says the Lord*.'
EXEC add_BibleVerse @BibleId, 358008010, N'“ For this is the covenant that I will establish with the house of Israel after those days, says the Lord. I will put my laws in their minds and I will inscribe them on their hearts. And I will be their God and they will be my people.'
EXEC add_BibleVerse @BibleId, 358008011, N'“ And there will be no need at all for each one to teach his countryman or each one to teach his brother saying, ‘Know the Lord,’ since they will all know me, from the least to the greatest.'
EXEC add_BibleVerse @BibleId, 358008012, N'“ For I will be merciful toward their evil deeds, and their sins I will remember no longer.”'
EXEC add_BibleVerse @BibleId, 358008013, N'When he speaks of a new covenant, he makes the first obsolete. Now what is growing obsolete and aging is about to disappear.'
EXEC add_BibleVerse @BibleId, 358009001, N'Now the first covenant, in fact, had regulations for worship and its earthly sanctuary.'
EXEC add_BibleVerse @BibleId, 358009002, N'For a tent was prepared, the outer one, which contained the lampstand, the table, and the presentation of the loaves; this is called the holy place.'
EXEC add_BibleVerse @BibleId, 358009003, N'And after the second curtain there was a tent called the holy of holies.'
EXEC add_BibleVerse @BibleId, 358009004, N'It contained the golden altar of incense and the ark of the covenant covered entirely with gold. In this ark were the golden urn containing the manna, Aaron’s rod that budded, and the stone tablets of the covenant.'
EXEC add_BibleVerse @BibleId, 358009005, N'And above the ark were the cherubim of glory overshadowing the mercy seat. Now is not the time to speak of these things in detail.'
EXEC add_BibleVerse @BibleId, 358009006, N'So with these things prepared like this, the priests enter continually into the outer tent as they perform their duties.'
EXEC add_BibleVerse @BibleId, 358009007, N'But only the high priest enters once a year into the inner tent, and not without blood that he offers for himself and for the sins of the people committed in ignorance.'
EXEC add_BibleVerse @BibleId, 358009008, N'The Holy Spirit is making clear that the way into the holy place had not yet appeared as long as the old tabernacle was standing.'
EXEC add_BibleVerse @BibleId, 358009009, N'This was a symbol for the time then present, when gifts and sacrifices were offered that could not perfect the conscience of the worshiper.'
EXEC add_BibleVerse @BibleId, 358009010, N'They served only for matters of food and drink and various washings; they are external regulations imposed until the new order came.'
EXEC add_BibleVerse @BibleId, 358009011, N'But now Christ has come as the high priest of the good things to come. He passed through the greater and more perfect tent not made with hands, that is, not of this creation,'
EXEC add_BibleVerse @BibleId, 358009012, N'and he entered once for all into the most holy place not by the blood of goats and calves but by his own blood, and so he himself secured eternal redemption.'
EXEC add_BibleVerse @BibleId, 358009013, N'For if the blood of goats and bulls and the ashes of a young cow sprinkled on those who are defiled consecrated them and provided ritual purity,'
EXEC add_BibleVerse @BibleId, 358009014, N'how much more will the blood of Christ, who through the eternal Spirit offered himself without blemish to God, purify our consciences from dead works to worship the living God.'
EXEC add_BibleVerse @BibleId, 358009015, N'And so he is the mediator of a new covenant, so that those who are called may receive the eternal inheritance he has promised, since he died to set them free from the violations committed under the first covenant.'
EXEC add_BibleVerse @BibleId, 358009016, N'For where there is a will, the death of the one who made it must be proven.'
EXEC add_BibleVerse @BibleId, 358009017, N'For a will takes effect only at death, since it carries no force while the one who made it is alive.'
EXEC add_BibleVerse @BibleId, 358009018, N'So even the first covenant was inaugurated with blood.'
EXEC add_BibleVerse @BibleId, 358009019, N'For when Moses had spoken every command to all the people according to the law, he took the blood of calves and goats with water and scarlet wool and hyssop and sprinkled both the book itself and all the people,'
EXEC add_BibleVerse @BibleId, 358009020, N'and said, “ This is the blood of the covenant that God has commanded you to keep.”'
EXEC add_BibleVerse @BibleId, 358009021, N'And both the tabernacle and all the utensils of worship he likewise sprinkled with blood.'
EXEC add_BibleVerse @BibleId, 358009022, N'Indeed according to the law almost everything was purified with blood, and without the shedding of blood there is no forgiveness.'
EXEC add_BibleVerse @BibleId, 358009023, N'So it was necessary for the sketches of the things in heaven to be purified with these sacrifices, but the heavenly things themselves required better sacrifices than these.'
EXEC add_BibleVerse @BibleId, 358009024, N'For Christ did not enter a sanctuary made with hands – the representation of the true sanctuary – but into heaven itself, and he appears now in God’s presence for us.'
EXEC add_BibleVerse @BibleId, 358009025, N'And he did not enter to offer himself again and again, the way the high priest enters the sanctuary year after year with blood that is not his own,'
EXEC add_BibleVerse @BibleId, 358009026, N'for then he would have had to suffer again and again since the foundation of the world. But now he has appeared once for all at the consummation of the ages to put away sin by his sacrifice.'
EXEC add_BibleVerse @BibleId, 358009027, N'And just as people are appointed to die once, and then to face judgment,'
EXEC add_BibleVerse @BibleId, 358009028, N'so also, after Christ was offered once to bear the sins of many, to those who eagerly await him he will appear a second time, not to bear sin but to bring salvation.'
EXEC add_BibleVerse @BibleId, 358010001, N'For the law possesses a shadow of the good things to come but not the reality itself, and is therefore completely unable, by the same sacrifices offered continually, year after year, to perfect those who come to worship.'
EXEC add_BibleVerse @BibleId, 358010002, N'For otherwise would they not have ceased to be offered, since the worshipers would have been purified once for all and so have no further consciousness of sin?'
EXEC add_BibleVerse @BibleId, 358010003, N'But in those sacrifices there is a reminder of sins year after year.'
EXEC add_BibleVerse @BibleId, 358010004, N'For the blood of bulls and goats cannot take away sins.'
EXEC add_BibleVerse @BibleId, 358010005, N'So when he came into the world, he said, “ Sacrifice and offering you did not desire, but a body you prepared for me.'
EXEC add_BibleVerse @BibleId, 358010006, N'“ Whole burnt offerings and sin-offerings you took no delight in.'
EXEC add_BibleVerse @BibleId, 358010007, N'“ Then I said, ‘Here I am: I have come – it is written of me in the scroll of the book – to do your will, O God*.’”'
EXEC add_BibleVerse @BibleId, 358010008, N'When he says above, “ Sacrifices and offerings and whole burnt offerings and sin-offeringsyou did not desire nor did you take delight in them” (which are offered according to the law),'
EXEC add_BibleVerse @BibleId, 358010009, N'then he says, “ Here I am: I have come to do your will.” He does away with the first to establish the second.'
EXEC add_BibleVerse @BibleId, 358010010, N'By his will we have been made holy through the offering of the body of Jesus Christ once for all.'
EXEC add_BibleVerse @BibleId, 358010011, N'And every priest stands day after day serving and offering the same sacrifices again and again – sacrifices that can never take away sins.'
EXEC add_BibleVerse @BibleId, 358010012, N'But when this priest had offered one sacrifice for sins for all time, he sat down at the right hand of God,'
EXEC add_BibleVerse @BibleId, 358010013, N'where he is now waiting until his enemies are made a footstool for his feet.'
EXEC add_BibleVerse @BibleId, 358010014, N'For by one offering he has perfected for all time those who are made holy.'
EXEC add_BibleVerse @BibleId, 358010015, N'And the Holy Spirit also witnesses to us, for after saying,'
EXEC add_BibleVerse @BibleId, 358010016, N'“ This is the covenant that I will establish with them after those days, says the Lord. I will put my laws on their hearts and I will inscribe them on their minds,”'
EXEC add_BibleVerse @BibleId, 358010017, N'then he says, “ Their sins and their lawless deeds I will remember no longer.”'
EXEC add_BibleVerse @BibleId, 358010018, N'Now where there is forgiveness of these, there is no longer any offering for sin.'
EXEC add_BibleVerse @BibleId, 358010019, N'Therefore, brothers and sisters, since we have confidence to enter the sanctuary by the blood of Jesus,'
EXEC add_BibleVerse @BibleId, 358010020, N'by the fresh and living way that he inaugurated for us through the curtain, that is, through his flesh,'
EXEC add_BibleVerse @BibleId, 358010021, N'and since we have a great priest over the house of God,'
EXEC add_BibleVerse @BibleId, 358010022, N'let us draw near with a sincere heart in the assurance that faith brings, because we have had our hearts sprinkled clean from an evil conscience and our bodies washed in pure water.'
EXEC add_BibleVerse @BibleId, 358010023, N'And let us hold unwaveringly to the hope that we confess, for the one who made the promise is trustworthy.'
EXEC add_BibleVerse @BibleId, 358010024, N'And let us take thought of how to spur one another on to love and good works,'
EXEC add_BibleVerse @BibleId, 358010025, N'not abandoning our own meetings, as some are in the habit of doing, but encouraging each other, and even more so because you see the day drawing near.'
EXEC add_BibleVerse @BibleId, 358010026, N'For if we deliberately keep on sinning after receiving the knowledge of the truth, no further sacrifice for sins is left for us,'
EXEC add_BibleVerse @BibleId, 358010027, N'but only a certain fearful expectation of judgment and a fury of fire that will consume God’s enemies.'
EXEC add_BibleVerse @BibleId, 358010028, N'Someone who rejected the law of Moses was put to death without mercy on the testimony of two or three witnesses.'
EXEC add_BibleVerse @BibleId, 358010029, N'How much greater punishment do you think that person deserves who has contempt for the Son of God, and profanes the blood of the covenant that made him holy, and insults the Spirit of grace?'
EXEC add_BibleVerse @BibleId, 358010030, N'For we know the one who said, “ Vengeance is mine, I will repay,” and again, “ The Lord will judge his people.”'
EXEC add_BibleVerse @BibleId, 358010031, N'It is a terrifying thing to fall into the hands of the living God.'
EXEC add_BibleVerse @BibleId, 358010032, N'But remember the former days when you endured a harsh conflict of suffering after you were enlightened.'
EXEC add_BibleVerse @BibleId, 358010033, N'At times you were publicly exposed to abuse and afflictions, and at other times you came to share with others who were treated in that way.'
EXEC add_BibleVerse @BibleId, 358010034, N'For in fact you shared the sufferings of those in prison, and you accepted the confiscation of your belongings with joy, because you knew that you certainly had a better and lasting possession.'
EXEC add_BibleVerse @BibleId, 358010035, N'So do not throw away your confidence, because it has great reward.'
EXEC add_BibleVerse @BibleId, 358010036, N'For you need endurance in order to do God’s will and so receive what is promised.'
EXEC add_BibleVerse @BibleId, 358010037, N'For just a little longer and he who is coming will arrive and not delay.'
EXEC add_BibleVerse @BibleId, 358010038, N'But my righteous one will live by faith, and if he shrinks back, I take no pleasure in him.'
EXEC add_BibleVerse @BibleId, 358010039, N'But we are not among those who shrink back and thus perish, but are among those who have faith and preserve their souls.'
EXEC add_BibleVerse @BibleId, 358011001, N'Now faith is being sure of what we hope for, being convinced of what we do not see.'
EXEC add_BibleVerse @BibleId, 358011002, N'For by it the people of old received God’s commendation.'
EXEC add_BibleVerse @BibleId, 358011003, N'By faith we understand that the worlds were set in order at God’s command, so that the visible has its origin in the invisible.'
EXEC add_BibleVerse @BibleId, 358011004, N'By faith Abel offered God a greater sacrifice than Cain, and through his faith he was commended as righteous, because God commended him for his offerings. And through his faith he still speaks, though he is dead.'
EXEC add_BibleVerse @BibleId, 358011005, N'By faith Enoch was taken up so that he did not see death, and he was not to be found because God took him up. For before his removal he had been commended as having pleased God.'
EXEC add_BibleVerse @BibleId, 358011006, N'Now without faith it is impossible to please him, for the one who approaches God must believe that he exists and that he rewards those who seek him.'
EXEC add_BibleVerse @BibleId, 358011007, N'By faith Noah, when he was warned about things not yet seen, with reverent regard constructed an ark for the deliverance of his family. Through faith he condemned the world and became an heir of the righteousness that comes by faith.'
EXEC add_BibleVerse @BibleId, 358011008, N'By faith Abraham obeyed when he was called to go out to a place he would later receive as an inheritance, and he went out without understanding where he was going.'
EXEC add_BibleVerse @BibleId, 358011009, N'By faith he lived as a foreigner in the promised land as though it were a foreign country, living in tents with Isaac and Jacob, who were fellow heirs of the same promise.'
EXEC add_BibleVerse @BibleId, 358011010, N'For he was looking forward to the city with firm foundations, whose architect and builder is God.'
EXEC add_BibleVerse @BibleId, 358011011, N'By faith, even though Sarah herself was barren and he was too old, he received the ability to procreate, because he regarded the one who had given the promise to be trustworthy.'
EXEC add_BibleVerse @BibleId, 358011012, N'So in fact children were fathered by one man – and this one as good as dead – like the number of stars in the sky and like the innumerable grains of sand on the seashore.'
EXEC add_BibleVerse @BibleId, 358011013, N'These all died in faith without receiving the things promised, but they saw them in the distance and welcomed them and acknowledged that they were strangers and foreigners on the earth.'
EXEC add_BibleVerse @BibleId, 358011014, N'For those who speak in such a way make it clear that they are seeking a homeland.'
EXEC add_BibleVerse @BibleId, 358011015, N'In fact, if they had been thinking of the land that they had left, they would have had opportunity to return.'
EXEC add_BibleVerse @BibleId, 358011016, N'But as it is, they aspire to a better land, that is, a heavenly one. Therefore, God is not ashamed to be called their God, for he has prepared a city for them.'
EXEC add_BibleVerse @BibleId, 358011017, N'By faith Abraham, when he was tested, offered up Isaac. He had received the promises, yet he was ready to offer up his only son.'
EXEC add_BibleVerse @BibleId, 358011018, N'God had told him, “ Through Isaac descendants will carry on your name,”'
EXEC add_BibleVerse @BibleId, 358011019, N'and he reasoned that God could even raise him from the dead, and in a sense he received him back from there.'
EXEC add_BibleVerse @BibleId, 358011020, N'By faith also Isaac blessed Jacob and Esau concerning the future.'
EXEC add_BibleVerse @BibleId, 358011021, N'By faith Jacob, as he was dying, blessed each of the sons of Joseph and worshiped as he leaned on his staff as he leaned on his staff.'
EXEC add_BibleVerse @BibleId, 358011022, N'By faith Joseph, at the end of his life, mentioned the exodus of the sons of Israel and gave instructions about his burial.'
EXEC add_BibleVerse @BibleId, 358011023, N'By faith, when Moses was born, his parents hid him for three months, because they saw the child was beautiful and they were not afraid of the king’s edict.'
EXEC add_BibleVerse @BibleId, 358011024, N'By faith, when he grew up, Moses refused to be called the son of Pharaoh’s daughter,'
EXEC add_BibleVerse @BibleId, 358011025, N'choosing rather to be ill-treated with the people of God than to enjoy sin’s fleeting pleasure.'
EXEC add_BibleVerse @BibleId, 358011026, N'He regarded abuse suffered for Christ to be greater wealth than the treasures of Egypt, for his eyes were fixed on the reward.'
EXEC add_BibleVerse @BibleId, 358011027, N'By faith he left Egypt without fearing the king’s anger, for he persevered as though he could see the one who is invisible.'
EXEC add_BibleVerse @BibleId, 358011028, N'By faith he kept the Passover and the sprinkling of the blood, so that the one who destroyed the firstborn would not touch them.'
EXEC add_BibleVerse @BibleId, 358011029, N'By faith they crossed the Red Sea as if on dry ground, but when the Egyptians tried it, they were swallowed up.'
EXEC add_BibleVerse @BibleId, 358011030, N'By faith the walls of Jericho fell after the people marched around them for seven days.'
EXEC add_BibleVerse @BibleId, 358011031, N'By faith Rahab the prostitute escaped the destruction of the disobedient, because she welcomed the spies in peace.'
EXEC add_BibleVerse @BibleId, 358011032, N'And what more shall I say? For time will fail me if I tell of Gideon, Barak, Samson, Jephthah, of David and Samuel and the prophets.'
EXEC add_BibleVerse @BibleId, 358011033, N'Through faith they conquered kingdoms, administered justice, gained what was promised, shut the mouths of lions,'
EXEC add_BibleVerse @BibleId, 358011034, N'quenched raging fire, escaped the edge of the sword, gained strength in weakness, became mighty in battle, put foreign armies to flight,'
EXEC add_BibleVerse @BibleId, 358011035, N'and women received back their dead raised to life. But others were tortured, not accepting release, to obtain resurrection to a better life.'
EXEC add_BibleVerse @BibleId, 358011036, N'And others experienced mocking and flogging, and even chains and imprisonment.'
EXEC add_BibleVerse @BibleId, 358011037, N'They were stoned, sawed apart, murdered with the sword; they went about in sheepskins and goatskins; they were destitute, afflicted, ill-treated'
EXEC add_BibleVerse @BibleId, 358011038, N'(the world was not worthy of them); they wandered in deserts and mountains and caves and openings in the earth.'
EXEC add_BibleVerse @BibleId, 358011039, N'And these all were commended for their faith, yet they did not receive what was promised.'
EXEC add_BibleVerse @BibleId, 358011040, N'For God had provided something better for us, so that they would be made perfect together with us.'
EXEC add_BibleVerse @BibleId, 358012001, N'Therefore, since we are surrounded by such a great cloud of witnesses, we must get rid of every weight and the sin that clings so closely, and run with endurance the race set out for us,'
EXEC add_BibleVerse @BibleId, 358012002, N'keeping our eyes fixed on Jesus, the pioneer and perfecter of our faith. For the joy set out for him he endured the cross, disregarding its shame, and has taken his seat at the right hand of the throne of God.'
EXEC add_BibleVerse @BibleId, 358012003, N'Think of him who endured such opposition against himself by sinners, so that you may not grow weary in your souls and give up.'
EXEC add_BibleVerse @BibleId, 358012004, N'You have not yet resisted to the point of bloodshed in your struggle against sin.'
EXEC add_BibleVerse @BibleId, 358012005, N'And have you forgotten the exhortation addressed to you as sons? “ My son, do not scorn the Lord’s discipline or give up when he corrects you*.'
EXEC add_BibleVerse @BibleId, 358012006, N'“ For the Lord disciplines the one he loves and chastises every son he accepts.”'
EXEC add_BibleVerse @BibleId, 358012007, N'Endure your suffering as discipline; God is treating you as sons. For what son is there that a father does not discipline?'
EXEC add_BibleVerse @BibleId, 358012008, N'But if you do not experience discipline, something all sons have shared in, then you are illegitimate and are not sons.'
EXEC add_BibleVerse @BibleId, 358012009, N'Besides, we have experienced discipline from our earthly fathers and we respected them; shall we not submit ourselves all the more to the Father of spirits and receive life?'
EXEC add_BibleVerse @BibleId, 358012010, N'For they disciplined us for a little while as seemed good to them, but he does so for our benefit, that we may share his holiness.'
EXEC add_BibleVerse @BibleId, 358012011, N'Now all discipline seems painful at the time, not joyful. But later it produces the fruit of peace and righteousness for those trained by it.'
EXEC add_BibleVerse @BibleId, 358012012, N'Therefore, strengthen your listless hands and your weak knees,'
EXEC add_BibleVerse @BibleId, 358012013, N'and make straight paths for your feet straight paths for your feet, so that what is lame may not be put out of joint but be healed.'
EXEC add_BibleVerse @BibleId, 358012014, N'Pursue peace with everyone, and holiness, for without it no one will see the Lord.'
EXEC add_BibleVerse @BibleId, 358012015, N'See to it that no one comes short of the grace of God, that no one be like a bitter root springing up and causing trouble, and through him many become defiled.'
EXEC add_BibleVerse @BibleId, 358012016, N'And see to it that no one becomes an immoral or godless person like Esau, who sold his own birthright for a single meal.'
EXEC add_BibleVerse @BibleId, 358012017, N'For you know that later when he wanted to inherit the blessing, he was rejected, for he found no opportunity for repentance, although he sought the blessing with tears.'
EXEC add_BibleVerse @BibleId, 358012018, N'For you have not come to something that can be touched, to a burning fire and darkness and gloom and a whirlwind'
EXEC add_BibleVerse @BibleId, 358012019, N'and the blast of a trumpet and a voice uttering words such that those who heard begged to hear no more.'
EXEC add_BibleVerse @BibleId, 358012020, N'For they could not bear what was commanded: “ If even an animal touches the mountain, it must be stoned.”'
EXEC add_BibleVerse @BibleId, 358012021, N'In fact, the scene was so terrifying that Moses said, “ I shudder with fear.”'
EXEC add_BibleVerse @BibleId, 358012022, N'But you have come to Mount Zion, the city of the living God, the heavenly Jerusalem, and to myriads of angels, to the assembly'
EXEC add_BibleVerse @BibleId, 358012023, N'and congregation of the firstborn, who are enrolled in heaven, and to God, the judge of all, and to the spirits of the righteous, who have been made perfect,'
EXEC add_BibleVerse @BibleId, 358012024, N'and to Jesus, the mediator of a new covenant, and to the sprinkled blood that speaks of something better than Abel’s does.'
EXEC add_BibleVerse @BibleId, 358012025, N'Take care not to refuse the one who is speaking! For if they did not escape when they refused the one who warned them on earth, how much less shall we, if we reject the one who warns from heaven?'
EXEC add_BibleVerse @BibleId, 358012026, N'Then his voice shook the earth, but now he has promised, “ I will once more shake not only the earth but heaven too.”'
EXEC add_BibleVerse @BibleId, 358012027, N'Now this phrase “ once more” indicates the removal of what is shaken, that is, of created things, so that what is unshaken may remain.'
EXEC add_BibleVerse @BibleId, 358012028, N'So since we are receiving an unshakable kingdom, let us give thanks, and through this let us offer worship pleasing to God in devotion and awe.'
EXEC add_BibleVerse @BibleId, 358012029, N'For our God is indeed a devouring fire.'
EXEC add_BibleVerse @BibleId, 358013001, N'Brotherly love must continue.'
EXEC add_BibleVerse @BibleId, 358013002, N'Do not neglect hospitality, because through it some have entertained angels without knowing it.'
EXEC add_BibleVerse @BibleId, 358013003, N'Remember those in prison as though you were in prison with them, and those ill-treated as though you too felt their torment.'
EXEC add_BibleVerse @BibleId, 358013004, N'Marriage must be honored among all and the marriage bed kept undefiled, for God will judge sexually immoral people and adulterers.'
EXEC add_BibleVerse @BibleId, 358013005, N'Your conduct must be free from the love of money and you must be content with what you have, for he has said, “ I will never leave you and I will never abandon you.”'
EXEC add_BibleVerse @BibleId, 358013006, N'So we can say with confidence, “ The Lord is my helper, and I will not be afraid. What can man do to me?*”'
EXEC add_BibleVerse @BibleId, 358013007, N'Remember your leaders, who spoke God’s message to you; reflect on the outcome of their lives and imitate their faith.'
EXEC add_BibleVerse @BibleId, 358013008, N'Jesus Christ is the same yesterday and today and forever!'
EXEC add_BibleVerse @BibleId, 358013009, N'Do not be carried away by all sorts of strange teachings. For it is good for the heart to be strengthened by grace, not ritual meals, which have never benefited those who participated in them.'
EXEC add_BibleVerse @BibleId, 358013010, N'We have an altar that those who serve in the tabernacle have no right to eat from.'
EXEC add_BibleVerse @BibleId, 358013011, N'For the bodies of those animals whose blood the high priest brings into the sanctuary as an offering for sin are burned outside the camp.'
EXEC add_BibleVerse @BibleId, 358013012, N'Therefore, to sanctify the people by his own blood, Jesus also suffered outside the camp.'
EXEC add_BibleVerse @BibleId, 358013013, N'We must go out to him, then, outside the camp, bearing the abuse he experienced.'
EXEC add_BibleVerse @BibleId, 358013014, N'For here we have no lasting city, but we seek the city that is to come.'
EXEC add_BibleVerse @BibleId, 358013015, N'Through him then let us continually offer up a sacrifice of praise to God, that is, the fruit of our lips, acknowledging his name.'
EXEC add_BibleVerse @BibleId, 358013016, N'And do not neglect to do good and to share what you have, for God is pleased with such sacrifices.'
EXEC add_BibleVerse @BibleId, 358013017, N'Obey your leaders and submit to them, for they keep watch over your souls and will give an account for their work. Let them do this with joy and not with complaints, for this would be no advantage for you.'
EXEC add_BibleVerse @BibleId, 358013018, N'Pray for us, for we are sure that we have a clear conscience and desire to conduct ourselves rightly in every respect.'
EXEC add_BibleVerse @BibleId, 358013019, N'I especially ask you to pray that I may be restored to you very soon.'
EXEC add_BibleVerse @BibleId, 358013020, N'Now may the God of peace who by the blood of the eternal covenant brought back from the dead the great shepherd of the sheep, our Lord Jesus Christ,'
EXEC add_BibleVerse @BibleId, 358013021, N'equip you with every good thing to do his will, working in us what is pleasing before him through Jesus Christ, to whom be glory forever. Amen.'
EXEC add_BibleVerse @BibleId, 358013022, N'Now I urge you, brothers and sisters, bear with my message of exhortation, for in fact I have written to you briefly.'
EXEC add_BibleVerse @BibleId, 358013023, N'You should know that our brother Timothy has been released. If he comes soon, he will be with me when I see you.'
EXEC add_BibleVerse @BibleId, 358013024, N'Greetings to all your leaders and all the saints. Those from Italy send you greetings.'
EXEC add_BibleVerse @BibleId, 358013025, N'Grace be with you all.'
EXEC add_BibleVerse @BibleId, 359001001, N'From James, a slave of God and the Lord Jesus Christ, to the twelve tribes dispersed abroad. Greetings!'
EXEC add_BibleVerse @BibleId, 359001002, N'My brothers and sisters, consider it nothing but joy when you fall into all sorts of trials,'
EXEC add_BibleVerse @BibleId, 359001003, N'because you know that the testing of your faith produces endurance.'
EXEC add_BibleVerse @BibleId, 359001004, N'And let endurance have its perfect effect, so that you will be perfect and complete, not deficient in anything.'
EXEC add_BibleVerse @BibleId, 359001005, N'But if anyone is deficient in wisdom, he should ask God, who gives to all generously and without reprimand, and it will be given to him.'
EXEC add_BibleVerse @BibleId, 359001006, N'But he must ask in faith without doubting, for the one who doubts is like a wave of the sea, blown and tossed around by the wind.'
EXEC add_BibleVerse @BibleId, 359001007, N'For that person must not suppose that he will receive anything from the Lord,'
EXEC add_BibleVerse @BibleId, 359001008, N'since he is a double-minded individual, unstable in all his ways.'
EXEC add_BibleVerse @BibleId, 359001009, N'Now the believer of humble means should take pride in his high position.'
EXEC add_BibleVerse @BibleId, 359001010, N'But the rich person’s pride should be in his humiliation, because he will pass away like a wildflower in the meadow.'
EXEC add_BibleVerse @BibleId, 359001011, N'For the sun rises with its heat and dries up the meadow; the petal of the flower falls off and its beauty is lost forever. So also the rich person in the midst of his pursuits will wither away.'
EXEC add_BibleVerse @BibleId, 359001012, N'Happy is the one who endures testing, because when he has proven to be genuine, he will receive the crown of life that God promised to those who love him.'
EXEC add_BibleVerse @BibleId, 359001013, N'Let no one say when he is tempted, “I am tempted by God,” for God cannot be tempted by evil, and he himself tempts no one.'
EXEC add_BibleVerse @BibleId, 359001014, N'But each one is tempted when he is lured and enticed by his own desires.'
EXEC add_BibleVerse @BibleId, 359001015, N'Then when desire conceives, it gives birth to sin, and when sin is full grown, it gives birth to death.'
EXEC add_BibleVerse @BibleId, 359001016, N'Do not be led astray, my dear brothers and sisters.'
EXEC add_BibleVerse @BibleId, 359001017, N'All generous giving and every perfect gift is from above, coming down from the Father of lights, with whom there is no variation or the slightest hint of change.'
EXEC add_BibleVerse @BibleId, 359001018, N'By his sovereign plan he gave us birth through the message of truth, that we would be a kind of firstfruits of all he created.'
EXEC add_BibleVerse @BibleId, 359001019, N'Understand this, my dear brothers and sisters! Let every person be quick to listen, slow to speak, slow to anger.'
EXEC add_BibleVerse @BibleId, 359001020, N'For human anger does not accomplish God’s righteousness.'
EXEC add_BibleVerse @BibleId, 359001021, N'So put away all filth and evil excess and humbly welcome the message implanted within you, which is able to save your souls.'
EXEC add_BibleVerse @BibleId, 359001022, N'But be sure you live out the message and do not merely listen to it and so deceive yourselves.'
EXEC add_BibleVerse @BibleId, 359001023, N'For if someone merely listens to the message and does not live it out, he is like someone who gazes at his own face in a mirror.'
EXEC add_BibleVerse @BibleId, 359001024, N'For he gazes at himself and then goes out and immediately forgets what sort of person he was.'
EXEC add_BibleVerse @BibleId, 359001025, N'But the one who peers into the perfect law of liberty and fixes his attention there, and does not become a forgetful listener but one who lives it out – he will be blessed in what he does.'
EXEC add_BibleVerse @BibleId, 359001026, N'If someone thinks he is religious yet does not bridle his tongue, and so deceives his heart, his religion is futile.'
EXEC add_BibleVerse @BibleId, 359001027, N'Pure and undefiled religion before God the Father is this: to care for orphans and widows in their misfortune and to keep oneself unstained by the world.'
EXEC add_BibleVerse @BibleId, 359002001, N'My brothers and sisters, do not show prejudice if you possess faith in our glorious Lord Jesus Christ.'
EXEC add_BibleVerse @BibleId, 359002002, N'For if someone comes into your assembly wearing a gold ring and fine clothing, and a poor person enters in filthy clothes,'
EXEC add_BibleVerse @BibleId, 359002003, N'do you pay attention to the one who is finely dressed and say, “You sit here in a good place,” and to the poor person, “You stand over there,” or “Sit on the floor”?'
EXEC add_BibleVerse @BibleId, 359002004, N'If so, have you not made distinctions among yourselves and become judges with evil motives?'
EXEC add_BibleVerse @BibleId, 359002005, N'Listen, my dear brothers and sisters! Did not God choose the poor in the world to be rich in faith and heirs of the kingdom that he promised to those who love him?'
EXEC add_BibleVerse @BibleId, 359002006, N'But you have dishonored the poor! Are not the rich oppressing you and dragging you into the courts?'
EXEC add_BibleVerse @BibleId, 359002007, N'Do they not blaspheme the good name of the one you belong to?'
EXEC add_BibleVerse @BibleId, 359002008, N'But if you fulfill the royal law as expressed in this scripture, “ You shall love your neighbor as yourself your neighbor as yourself,” you are doing well.'
EXEC add_BibleVerse @BibleId, 359002009, N'But if you show prejudice, you are committing sin and are convicted by the law as violators.'
EXEC add_BibleVerse @BibleId, 359002010, N'For the one who obeys the whole law but fails in one point has become guilty of all of it.'
EXEC add_BibleVerse @BibleId, 359002011, N'For he who said, “Do not commit adultery,” also said, “Do not murder.” Now if you do not commit adultery but do commit murder, you have become a violator of the law.'
EXEC add_BibleVerse @BibleId, 359002012, N'Speak and act as those who will be judged by a law that gives freedom.'
EXEC add_BibleVerse @BibleId, 359002013, N'For judgment is merciless for the one who has shown no mercy. But mercy triumphs over judgment.'
EXEC add_BibleVerse @BibleId, 359002014, N'What good is it, my brothers and sisters, if someone claims to have faith but does not have works? Can this kind of faith save him?'
EXEC add_BibleVerse @BibleId, 359002015, N'If a brother or sister is poorly clothed and lacks daily food,'
EXEC add_BibleVerse @BibleId, 359002016, N'and one of you says to them, “Go in peace, keep warm and eat well,” but you do not give them what the body needs, what good is it?'
EXEC add_BibleVerse @BibleId, 359002017, N'So also faith, if it does not have works, is dead being by itself.'
EXEC add_BibleVerse @BibleId, 359002018, N'But someone will say, “You have faith and I have works.” Show me your faith without works and I will show you faith by my works.'
EXEC add_BibleVerse @BibleId, 359002019, N'You believe that God is one; well and good. Even the demons believe that – and tremble with fear.'
EXEC add_BibleVerse @BibleId, 359002020, N'But would you like evidence, you empty fellow, that faith without works is useless?'
EXEC add_BibleVerse @BibleId, 359002021, N'Was not Abraham our father justified by works when he offered Isaac his son on the altar?'
EXEC add_BibleVerse @BibleId, 359002022, N'You see that his faith was working together with his works and his faith was perfected by works.'
EXEC add_BibleVerse @BibleId, 359002023, N'And the scripture was fulfilled that says, “Now Abraham believed God and it was counted to him for righteousness,” and he was called God’s friend.'
EXEC add_BibleVerse @BibleId, 359002024, N'You see that a person is justified by works and not by faith alone.'
EXEC add_BibleVerse @BibleId, 359002025, N'And similarly, was not Rahab the prostitute also justified by works when she welcomed the messengers and sent them out by another way?'
EXEC add_BibleVerse @BibleId, 359002026, N'For just as the body without the spirit is dead, so also faith without works is dead.'
EXEC add_BibleVerse @BibleId, 359003001, N'Not many of you should become teachers, my brothers and sisters, because you know that we will be judged more strictly.'
EXEC add_BibleVerse @BibleId, 359003002, N'For we all stumble in many ways. If someone does not stumble in what he says, he is a perfect individual, able to control the entire body as well.'
EXEC add_BibleVerse @BibleId, 359003003, N'And if we put bits into the mouths of horses to get them to obey us, then we guide their entire bodies.'
EXEC add_BibleVerse @BibleId, 359003004, N'Look at ships too: Though they are so large and driven by harsh winds, they are steered by a tiny rudder wherever the pilot’s inclination directs.'
EXEC add_BibleVerse @BibleId, 359003005, N'So too the tongue is a small part of the body, yet it has great pretensions. Think how small a flame sets a huge forest ablaze.'
EXEC add_BibleVerse @BibleId, 359003006, N'And the tongue is a fire! The tongue represents the world of wrongdoing among the parts of our bodies. It pollutes the entire body and sets fire to the course of human existence – and is set on fire by hell.'
EXEC add_BibleVerse @BibleId, 359003007, N'For every kind of animal, bird, reptile, and sea creature is subdued and has been subdued by humankind.'
EXEC add_BibleVerse @BibleId, 359003008, N'But no human being can subdue the tongue; it is a restless evil, full of deadly poison.'
EXEC add_BibleVerse @BibleId, 359003009, N'With it we bless the Lord and Father, and with it we curse people made in God’s image.'
EXEC add_BibleVerse @BibleId, 359003010, N'From the same mouth come blessing and cursing. These things should not be so, my brothers and sisters.'
EXEC add_BibleVerse @BibleId, 359003011, N'A spring does not pour out fresh water and bitter water from the same opening, does it?'
EXEC add_BibleVerse @BibleId, 359003012, N'Can a fig tree produce olives, my brothers and sisters, or a vine produce figs? Neither can a salt water spring produce fresh water.'
EXEC add_BibleVerse @BibleId, 359003013, N'Who is wise and understanding among you? By his good conduct he should show his works done in the gentleness that wisdom brings.'
EXEC add_BibleVerse @BibleId, 359003014, N'But if you have bitter jealousy and selfishness in your hearts, do not boast and tell lies against the truth.'
EXEC add_BibleVerse @BibleId, 359003015, N'Such wisdom does not come from above but is earthly, natural, demonic.'
EXEC add_BibleVerse @BibleId, 359003016, N'For where there is jealousy and selfishness, there is disorder and every evil practice.'
EXEC add_BibleVerse @BibleId, 359003017, N'But the wisdom from above is first pure, then peaceable, gentle, accommodating, full of mercy and good fruit, impartial, and not hypocritical.'
EXEC add_BibleVerse @BibleId, 359003018, N'And the fruit that consists of righteousness is planted in peace among those who make peace.'
EXEC add_BibleVerse @BibleId, 359004001, N'Where do the conflicts and where do the quarrels among you come from? Is it not from this, from your passions that battle inside you?'
EXEC add_BibleVerse @BibleId, 359004002, N'You desire and you do not have; you murder and envy and you cannot obtain; you quarrel and fight. You do not have because you do not ask;'
EXEC add_BibleVerse @BibleId, 359004003, N'you ask and do not receive because you ask wrongly, so you can spend it on your passions.'
EXEC add_BibleVerse @BibleId, 359004004, N'Adulterers, do you not know that friendship with the world means hostility toward God? So whoever decides to be the world’s friend makes himself God’s enemy.'
EXEC add_BibleVerse @BibleId, 359004005, N'Or do you think the scripture means nothing when it says, “The spirit that God caused to live within us has an envious yearning”?'
EXEC add_BibleVerse @BibleId, 359004006, N'But he gives greater grace. Therefore it says, “ God opposes the proud, but he gives grace to the humble.”'
EXEC add_BibleVerse @BibleId, 359004007, N'So submit to God. But resist the devil and he will flee from you.'
EXEC add_BibleVerse @BibleId, 359004008, N'Draw near to God and he will draw near to you. Cleanse your hands, you sinners, and make your hearts pure, you double-minded.'
EXEC add_BibleVerse @BibleId, 359004009, N'Grieve, mourn, and weep. Turn your laughter into mourning and your joy into despair.'
EXEC add_BibleVerse @BibleId, 359004010, N'Humble yourselves before the Lord and he will exalt you.'
EXEC add_BibleVerse @BibleId, 359004011, N'Do not speak against one another, brothers and sisters. He who speaks against a fellow believer or judges a fellow believer speaks against the law and judges the law. But if you judge the law, you are not a doer of the law but its judge.'
EXEC add_BibleVerse @BibleId, 359004012, N'But there is only one who is lawgiver and judge – the one who is able to save and destroy. On the other hand, who are you to judge your neighbor?'
EXEC add_BibleVerse @BibleId, 359004013, N'Come now, you who say, “Today or tomorrow we will go into this or that town and spend a year there and do business and make a profit.”'
EXEC add_BibleVerse @BibleId, 359004014, N'You do not know about tomorrow. What is your life like? For you are a puff of smoke that appears for a short time and then vanishes.'
EXEC add_BibleVerse @BibleId, 359004015, N'You ought to say instead, “If the Lord is willing, then we will live and do this or that.”'
EXEC add_BibleVerse @BibleId, 359004016, N'But as it is, you boast in your arrogance. All such boasting is evil.'
EXEC add_BibleVerse @BibleId, 359004017, N'So whoever knows what is good to do and does not do it is guilty of sin.'
EXEC add_BibleVerse @BibleId, 359005001, N'Come now, you rich! Weep and cry aloud over the miseries that are coming on you.'
EXEC add_BibleVerse @BibleId, 359005002, N'Your riches have rotted and your clothing has become moth-eaten.'
EXEC add_BibleVerse @BibleId, 359005003, N'Your gold and silver have rusted and their rust will be a witness against you. It will consume your flesh like fire. It is in the last days that you have hoarded treasure!'
EXEC add_BibleVerse @BibleId, 359005004, N'Look, the pay you have held back from the workers who mowed your fields cries out against you, and the cries of the reapers have reached the ears of the Lord of hosts.'
EXEC add_BibleVerse @BibleId, 359005005, N'You have lived indulgently and luxuriously on the earth. You have fattened your hearts in a day of slaughter.'
EXEC add_BibleVerse @BibleId, 359005006, N'You have condemned and murdered the righteous person, although he does not resist you.'
EXEC add_BibleVerse @BibleId, 359005007, N'So be patient, brothers and sisters, until the Lord’s return. Think of how the farmer waits for the precious fruit of the ground and is patient for it until it receives the early and late rains.'
EXEC add_BibleVerse @BibleId, 359005008, N'You also be patient and strengthen your hearts, for the Lord’s return is near.'
EXEC add_BibleVerse @BibleId, 359005009, N'Do not grumble against one another, brothers and sisters, so that you may not be judged. See, the judge stands before the gates!'
EXEC add_BibleVerse @BibleId, 359005010, N'As an example of suffering and patience, brothers and sisters, take the prophets who spoke in the Lord’s name.'
EXEC add_BibleVerse @BibleId, 359005011, N'Think of how we regard as blessed those who have endured. You have heard of Job’s endurance and you have seen the Lord’s purpose, that the Lord is full of compassion and mercy.'
EXEC add_BibleVerse @BibleId, 359005012, N'And above all, my brothers and sisters, do not swear, either by heaven or by earth or by any other oath. But let your “Yes” be yes and your “No” be no, so that you may not fall into judgment.'
EXEC add_BibleVerse @BibleId, 359005013, N'Is anyone among you suffering? He should pray. Is anyone in good spirits? He should sing praises.'
EXEC add_BibleVerse @BibleId, 359005014, N'Is anyone among you ill? He should summon the elders of the church, and they should pray for him and anoint him with oil in the name of the Lord.'
EXEC add_BibleVerse @BibleId, 359005015, N'And the prayer of faith will save the one who is sick and the Lord will raise him up – and if he has committed sins, he will be forgiven.'
EXEC add_BibleVerse @BibleId, 359005016, N'So confess your sins to one another and pray for one another so that you may be healed. The prayer of a righteous person has great effectiveness.'
EXEC add_BibleVerse @BibleId, 359005017, N'Elijah was a human being like us, and he prayed earnestly that it would not rain and there was no rain on the land for three years and six months!'
EXEC add_BibleVerse @BibleId, 359005018, N'Then he prayed again, and the sky gave rain and the land sprouted with a harvest.'
EXEC add_BibleVerse @BibleId, 359005019, N'My brothers and sisters, if anyone among you wanders from the truth and someone turns him back,'
EXEC add_BibleVerse @BibleId, 359005020, N'he should know that the one who turns a sinner back from his wandering path will save that person’s soul from death and will cover a multitude of sins.'
EXEC add_BibleVerse @BibleId, 360001001, N'From Peter, an apostle of Jesus Christ, to those temporarily residing abroad (in Pontus, Galatia, Cappadocia, the province of Asia, and Bithynia) who are chosen'
EXEC add_BibleVerse @BibleId, 360001002, N'according to the foreknowledge of God the Father by being set apart by the Spirit for obedience and for sprinkling with Jesus Christ’s blood. May grace and peace be yours in full measure!'
EXEC add_BibleVerse @BibleId, 360001003, N'Blessed be the God and Father of our Lord Jesus Christ! By his great mercy he gave us new birth into a living hope through the resurrection of Jesus Christ from the dead,'
EXEC add_BibleVerse @BibleId, 360001004, N'that is, into an inheritance imperishable, undefiled, and unfading. It is reserved in heaven for you,'
EXEC add_BibleVerse @BibleId, 360001005, N'who by God’s power are protected through faith for a salvation ready to be revealed in the last time.'
EXEC add_BibleVerse @BibleId, 360001006, N'This brings you great joy, although you may have to suffer for a short time in various trials.'
EXEC add_BibleVerse @BibleId, 360001007, N'Such trials show the proven character of your faith, which is much more valuable than gold – gold that is tested by fire, even though it is passing away – and will bring praise and glory and honor when Jesus Christ is revealed.'
EXEC add_BibleVerse @BibleId, 360001008, N'You have not seen him, but you love him. You do not see him now but you believe in him, and so you rejoice with an indescribable and glorious joy,'
EXEC add_BibleVerse @BibleId, 360001009, N'because you are attaining the goal of your faith – the salvation of your souls.'
EXEC add_BibleVerse @BibleId, 360001010, N'Concerning this salvation, the prophets who predicted the grace that would come to you searched and investigated carefully.'
EXEC add_BibleVerse @BibleId, 360001011, N'They probed into what person or time the Spirit of Christ within them was indicating when he testified beforehand about the sufferings appointed for Christ and his subsequent glory.'
EXEC add_BibleVerse @BibleId, 360001012, N'They were shown that they were serving not themselves but you, in regard to the things now announced to you through those who proclaimed the gospel to you by the Holy Spirit sent from heaven – things angels long to catch a glimpse of.'
EXEC add_BibleVerse @BibleId, 360001013, N'Therefore, get your minds ready for action by being fully sober, and set your hope completely on the grace that will be brought to you when Jesus Christ is revealed.'
EXEC add_BibleVerse @BibleId, 360001014, N'Like obedient children, do not comply with the evil urges you used to follow in your ignorance,'
EXEC add_BibleVerse @BibleId, 360001015, N'but, like the Holy One who called you, become holy yourselves in all of your conduct,'
EXEC add_BibleVerse @BibleId, 360001016, N'for it is written, “ You shall be holy, because I am holy.”'
EXEC add_BibleVerse @BibleId, 360001017, N'And if you address as Father the one who impartially judges according to each one’s work, live out the time of your temporary residence here in reverence.'
EXEC add_BibleVerse @BibleId, 360001018, N'You know that from your empty way of life inherited from your ancestors you were ransomed – not by perishable things like silver or gold,'
EXEC add_BibleVerse @BibleId, 360001019, N'but by precious blood like that of an unblemished and spotless lamb, namely Christ.'
EXEC add_BibleVerse @BibleId, 360001020, N'He was foreknown before the foundation of the world but was manifested in these last times for your sake.'
EXEC add_BibleVerse @BibleId, 360001021, N'Through him you now trust in God, who raised him from the dead and gave him glory, so that your faith and hope are in God.'
EXEC add_BibleVerse @BibleId, 360001022, N'You have purified your souls by obeying the truth in order to show sincere mutual love. So love one another earnestly from a pure heart.'
EXEC add_BibleVerse @BibleId, 360001023, N'You have been born anew, not from perishable but from imperishable seed, through the living and enduring word of God.'
EXEC add_BibleVerse @BibleId, 360001024, N'For all flesh is like grass and all its glory like the flower of the grass; the grass withers and the flower falls off,'
EXEC add_BibleVerse @BibleId, 360001025, N'but the word of the Lord endures forever. And this is the word that was proclaimed to you.'
EXEC add_BibleVerse @BibleId, 360002001, N'So get rid of all evil and all deceit and hypocrisy and envy and all slander.'
EXEC add_BibleVerse @BibleId, 360002002, N'And yearn like newborn infants for pure, spiritual milk, so that by it you may grow up to salvation,'
EXEC add_BibleVerse @BibleId, 360002003, N'if you have experienced the Lord’s kindness.'
EXEC add_BibleVerse @BibleId, 360002004, N'So as you come to him, a living stone rejected by men but chosen and priceless in God’s sight,'
EXEC add_BibleVerse @BibleId, 360002005, N'you yourselves, as living stones, are built up as a spiritual house to be a holy priesthood and to offer spiritual sacrifices that are acceptable to God through Jesus Christ.'
EXEC add_BibleVerse @BibleId, 360002006, N'For it says in scripture, “ Look,I lay in Zion a stone, a chosen and priceless cornerstone, and whoever believes in him will never be put to shame*.”'
EXEC add_BibleVerse @BibleId, 360002007, N'So you who believe see his value, but for those who do not believe, the stone that the builders rejected has become the cornerstone,'
EXEC add_BibleVerse @BibleId, 360002008, N'and a stumbling-stone and a rock to trip over*. They stumble because they disobey the word, as they were destined to do.'
EXEC add_BibleVerse @BibleId, 360002009, N'But you are a chosen race, a royal priesthood, a holy nation, a people of his own, so that you may proclaim the virtues of the one who called you out of darkness into his marvelous light.'
EXEC add_BibleVerse @BibleId, 360002010, N'You once were not a people, but now you are God’s people. You were shown no mercy, but now you have received mercy.'
EXEC add_BibleVerse @BibleId, 360002011, N'Dear friends, I urge you as foreigners and exiles to keep away from fleshly desires that do battle against the soul,'
EXEC add_BibleVerse @BibleId, 360002012, N'and maintain good conduct among the non-Christians, so that though they now malign you as wrongdoers, they may see your good deeds and glorify God when he appears.'
EXEC add_BibleVerse @BibleId, 360002013, N'Be subject to every human institution for the Lord’s sake, whether to a king as supreme'
EXEC add_BibleVerse @BibleId, 360002014, N'or to governors as those he commissions to punish wrongdoers and praise those who do good.'
EXEC add_BibleVerse @BibleId, 360002015, N'For God wants you to silence the ignorance of foolish people by doing good.'
EXEC add_BibleVerse @BibleId, 360002016, N'Live as free people, not using your freedom as a pretext for evil, but as God’s slaves.'
EXEC add_BibleVerse @BibleId, 360002017, N'Honor all people, love the family of believers, fear God, honor the king.'
EXEC add_BibleVerse @BibleId, 360002018, N'Slaves, be subject to your masters with all reverence, not only to those who are good and gentle, but also to those who are perverse.'
EXEC add_BibleVerse @BibleId, 360002019, N'For this finds God’s favor, if because of conscience toward God someone endures hardships in suffering unjustly.'
EXEC add_BibleVerse @BibleId, 360002020, N'For what credit is it if you sin and are mistreated and endure it? But if you do good and suffer and so endure, this finds favor with God.'
EXEC add_BibleVerse @BibleId, 360002021, N'For to this you were called, since Christ also suffered for you, leaving an example for you to follow in his steps.'
EXEC add_BibleVerse @BibleId, 360002022, N'He committed no sin nor was deceit found in his mouth.'
EXEC add_BibleVerse @BibleId, 360002023, N'When he was maligned, he did not answer back; when he suffered, he threatened no retaliation, but committed himself to God who judges justly.'
EXEC add_BibleVerse @BibleId, 360002024, N'He himself bore our sins in his body on the tree, that we may cease from sinning and live for righteousness. By his wounds you were healed.'
EXEC add_BibleVerse @BibleId, 360002025, N'For you were going astray like sheep but now you have turned back to the shepherd and guardian of your souls.'
EXEC add_BibleVerse @BibleId, 360003001, N'In the same way, wives, be subject to your own husbands. Then, even if some are disobedient to the word, they will be won over without a word by the way you live,'
EXEC add_BibleVerse @BibleId, 360003002, N'when they see your pure and reverent conduct.'
EXEC add_BibleVerse @BibleId, 360003003, N'Let your beauty not be external – the braiding of hair and wearing of gold jewelry or fine clothes –'
EXEC add_BibleVerse @BibleId, 360003004, N'but the inner person of the heart, the lasting beauty of a gentle and tranquil spirit, which is precious in God’s sight.'
EXEC add_BibleVerse @BibleId, 360003005, N'For in the same way the holy women who hoped in God long ago adorned themselves by being subject to their husbands,'
EXEC add_BibleVerse @BibleId, 360003006, N'like Sarah who obeyed Abraham, calling him lord. You become her children when you do what is good and have no fear in doing so.'
EXEC add_BibleVerse @BibleId, 360003007, N'Husbands, in the same way, treat your wives with consideration as the weaker partners and show them honor as fellow heirs of the grace of life. In this way nothing will hinder your prayers.'
EXEC add_BibleVerse @BibleId, 360003008, N'Finally, all of you be harmonious, sympathetic, affectionate, compassionate, and humble.'
EXEC add_BibleVerse @BibleId, 360003009, N'Do not return evil for evil or insult for insult, but instead bless others because you were called to inherit a blessing.'
EXEC add_BibleVerse @BibleId, 360003010, N'For the one who wants to love life and see good days must keep his tongue from evil and his lips from uttering deceit.'
EXEC add_BibleVerse @BibleId, 360003011, N'And he must turn away from evil and do good; he must seek peace and pursue it.'
EXEC add_BibleVerse @BibleId, 360003012, N'For the eyes of the Lord are upon the righteous and his ears are open to their prayer. But the Lord’s face is against those who do evil.'
EXEC add_BibleVerse @BibleId, 360003013, N'For who is going to harm you if you are devoted to what is good?'
EXEC add_BibleVerse @BibleId, 360003014, N'But in fact, if you happen to suffer for doing what is right, you are blessed. But do not be terrified of them or be shaken.'
EXEC add_BibleVerse @BibleId, 360003015, N'But set Christ apart as Lord in your hearts and always be ready to give an answer to anyone who asks about the hope you possess.'
EXEC add_BibleVerse @BibleId, 360003016, N'Yet do it with courtesy and respect, keeping a good conscience, so that those who slander your good conduct in Christ may be put to shame when they accuse you.'
EXEC add_BibleVerse @BibleId, 360003017, N'For it is better to suffer for doing good, if God wills it, than for doing evil.'
EXEC add_BibleVerse @BibleId, 360003018, N'Because Christ also suffered once for sins, the just for the unjust, to bring you to God, by being put to death in the flesh but by being made alive in the spirit.'
EXEC add_BibleVerse @BibleId, 360003019, N'In it he went and preached to the spirits in prison,'
EXEC add_BibleVerse @BibleId, 360003020, N'after they were disobedient long ago when God patiently waited in the days of Noah as an ark was being constructed. In the ark a few, that is eight souls, were delivered through water.'
EXEC add_BibleVerse @BibleId, 360003021, N'And this prefigured baptism, which now saves you – not the washing off of physical dirt but the pledge of a good conscience to God – through the resurrection of Jesus Christ,'
EXEC add_BibleVerse @BibleId, 360003022, N'who went into heaven and is at the right hand of God with angels and authorities and powers subject to him.'
EXEC add_BibleVerse @BibleId, 360004001, N'So, since Christ suffered in the flesh, you also arm yourselves with the same attitude, because the one who has suffered in the flesh has finished with sin,'
EXEC add_BibleVerse @BibleId, 360004002, N'in that he spends the rest of his time on earth concerned about the will of God and not human desires.'
EXEC add_BibleVerse @BibleId, 360004003, N'For the time that has passed was sufficient for you to do what the non-Christians desire. You lived then in debauchery, evil desires, drunkenness, carousing, drinking bouts, and wanton idolatries.'
EXEC add_BibleVerse @BibleId, 360004004, N'So they are astonished when you do not rush with them into the same flood of wickedness, and they vilify you.'
EXEC add_BibleVerse @BibleId, 360004005, N'They will face a reckoning before Jesus Christ who stands ready to judge the living and the dead.'
EXEC add_BibleVerse @BibleId, 360004006, N'Now it was for this very purpose that the gospel was preached to those who are now dead, so that though they were judged in the flesh by human standards they may live spiritually by God’s standards.'
EXEC add_BibleVerse @BibleId, 360004007, N'For the culmination of all things is near. So be self-controlled and sober-minded for the sake of prayer.'
EXEC add_BibleVerse @BibleId, 360004008, N'Above all keep your love for one another fervent, because love covers a multitude of sins.'
EXEC add_BibleVerse @BibleId, 360004009, N'Show hospitality to one another without complaining.'
EXEC add_BibleVerse @BibleId, 360004010, N'Just as each one has received a gift, use it to serve one another as good stewards of the varied grace of God.'
EXEC add_BibleVerse @BibleId, 360004011, N'Whoever speaks, let it be with God’s words. Whoever serves, do so with the strength that God supplies, so that in everything God will be glorified through Jesus Christ. To him belong the glory and the power forever and ever. Amen.'
EXEC add_BibleVerse @BibleId, 360004012, N'Dear friends, do not be astonished that a trial by fire is occurring among you, as though something strange were happening to you.'
EXEC add_BibleVerse @BibleId, 360004013, N'But rejoice in the degree that you have shared in the sufferings of Christ, so that when his glory is revealed you may also rejoice and be glad.'
EXEC add_BibleVerse @BibleId, 360004014, N'If you are insulted for the name of Christ, you are blessed, because the Spirit of glory, who is the Spirit of God, rests on you.'
EXEC add_BibleVerse @BibleId, 360004015, N'But let none of you suffer as a murderer or thief or criminal or as a troublemaker.'
EXEC add_BibleVerse @BibleId, 360004016, N'But if you suffer as a Christian, do not be ashamed, but glorify God that you bear such a name.'
EXEC add_BibleVerse @BibleId, 360004017, N'For it is time for judgment to begin, starting with the house of God. And if it starts with us, what will be the fate of those who are disobedient to the gospel of God?'
EXEC add_BibleVerse @BibleId, 360004018, N'And if the righteous are barely saved, what will become of the ungodly and sinners?'
EXEC add_BibleVerse @BibleId, 360004019, N'So then let those who suffer according to the will of God entrust their souls to a faithful Creator as they do good.'
EXEC add_BibleVerse @BibleId, 360005001, N'So as your fellow elder and a witness of Christ’s sufferings and as one who shares in the glory that will be revealed, I urge the elders among you:'
EXEC add_BibleVerse @BibleId, 360005002, N'Give a shepherd’s care to God’s flock among you, exercising oversight not merely as a duty but willingly under God’s direction, not for shameful profit but eagerly.'
EXEC add_BibleVerse @BibleId, 360005003, N'And do not lord it over those entrusted to you, but be examples to the flock.'
EXEC add_BibleVerse @BibleId, 360005004, N'Then when the Chief Shepherd appears, you will receive the crown of glory that never fades away.'
EXEC add_BibleVerse @BibleId, 360005005, N'In the same way, you who are younger, be subject to the elders. And all of you, clothe yourselves with humility toward one another, because God opposes the proud but gives grace to the humble.'
EXEC add_BibleVerse @BibleId, 360005006, N'And God will exalt you in due time, if you humble yourselves under his mighty hand'
EXEC add_BibleVerse @BibleId, 360005007, N'by casting all your cares on him because he cares for you.'
EXEC add_BibleVerse @BibleId, 360005008, N'Be sober and alert. Your enemy the devil, like a roaring lion, is on the prowl looking for someone to devour.'
EXEC add_BibleVerse @BibleId, 360005009, N'Resist him, strong in your faith, because you know that your brothers and sisters throughout the world are enduring the same kinds of suffering.'
EXEC add_BibleVerse @BibleId, 360005010, N'And, after you have suffered for a little while, the God of all grace who called you to his eternal glory in Christ will himself restore, confirm, strengthen, and establish you.'
EXEC add_BibleVerse @BibleId, 360005011, N'To him belongs the power forever. Amen.'
EXEC add_BibleVerse @BibleId, 360005012, N'Through Silvanus, whom I know to be a faithful brother, I have written to you briefly, in order to encourage you and testify that this is the true grace of God. Stand fast in it.'
EXEC add_BibleVerse @BibleId, 360005013, N'The church in Babylon, chosen together with you, greets you, and so does Mark, my son.'
EXEC add_BibleVerse @BibleId, 360005014, N'Greet one another with a loving kiss. Peace to all of you who are in Christ.'
EXEC add_BibleVerse @BibleId, 361001001, N'From Simeon Peter, a slave and apostle of Jesus Christ, to those who through the righteousness of our God and Savior, Jesus Christ, have been granted a faith just as precious as ours.'
EXEC add_BibleVerse @BibleId, 361001002, N'May grace and peace be lavished on you as you grow in the rich knowledge of God and of Jesus our Lord!'
EXEC add_BibleVerse @BibleId, 361001003, N'I can pray this because his divine power has bestowed on us everything necessary for life and godliness through the rich knowledge of the one who called us by his own glory and excellence.'
EXEC add_BibleVerse @BibleId, 361001004, N'Through these things he has bestowed on us his precious and most magnificent promises, so that by means of what was promised you may become partakers of the divine nature, after escaping the worldly corruption that is produced by evil desire.'
EXEC add_BibleVerse @BibleId, 361001005, N'For this very reason, make every effort to add to your faith excellence, to excellence, knowledge;'
EXEC add_BibleVerse @BibleId, 361001006, N'to knowledge, self-control; to self-control, perseverance; to perseverance, godliness;'
EXEC add_BibleVerse @BibleId, 361001007, N'to godliness, brotherly affection; to brotherly affection, unselfish love.'
EXEC add_BibleVerse @BibleId, 361001008, N'For if these things are really yours and are continually increasing, they will keep you from becoming ineffective and unproductive in your pursuit of knowing our Lord Jesus Christ more intimately.'
EXEC add_BibleVerse @BibleId, 361001009, N'But concerning the one who lacks such things – he is blind. That is to say, he is nearsighted, since he has forgotten about the cleansing of his past sins.'
EXEC add_BibleVerse @BibleId, 361001010, N'Therefore, brothers and sisters, make every effort to be sure of your calling and election. For by doing this you will never stumble into sin.'
EXEC add_BibleVerse @BibleId, 361001011, N'For thus an entrance into the eternal kingdom of our Lord and Savior, Jesus Christ, will be richly provided for you.'
EXEC add_BibleVerse @BibleId, 361001012, N'Therefore, I intend to remind you constantly of these things even though you know them and are well established in the truth that you now have.'
EXEC add_BibleVerse @BibleId, 361001013, N'Indeed, as long as I am in this tabernacle, I consider it right to stir you up by way of a reminder,'
EXEC add_BibleVerse @BibleId, 361001014, N'since I know that my tabernacle will soon be removed, because our Lord Jesus Christ revealed this to me.'
EXEC add_BibleVerse @BibleId, 361001015, N'Indeed, I will also make every effort that, after my departure, you have a testimony of these things.'
EXEC add_BibleVerse @BibleId, 361001016, N'For we did not follow cleverly concocted fables when we made known to you the power and return of our Lord Jesus Christ; no, we were eyewitnesses of his grandeur.'
EXEC add_BibleVerse @BibleId, 361001017, N'For he received honor and glory from God the Father, when that voice was conveyed to him by the Majestic Glory: “This is my dear Son, in whom I am delighted.”'
EXEC add_BibleVerse @BibleId, 361001018, N'When this voice was conveyed from heaven, we ourselves heard it, for we were with him on the holy mountain.'
EXEC add_BibleVerse @BibleId, 361001019, N'Moreover, we possess the prophetic word as an altogether reliable thing. You do well if you pay attention to this as you would to a light shining in a murky place, until the day dawns and the morning star rises in your hearts.'
EXEC add_BibleVerse @BibleId, 361001020, N'Above all, you do well if you recognize this: No prophecy of scripture ever comes about by the prophet’s own imagination,'
EXEC add_BibleVerse @BibleId, 361001021, N'for no prophecy was ever borne of human impulse; rather, men carried along by the Holy Spirit spoke from God.'
EXEC add_BibleVerse @BibleId, 361002001, N'But false prophets arose among the people, just as there will be false teachers among you. These false teachers will infiltrate your midst with destructive heresies, even to the point of denying the Master who bought them. As a result, they will bring swift destruction on themselves.'
EXEC add_BibleVerse @BibleId, 361002002, N'And many will follow their debauched lifestyles. Because of these false teachers, the way of truth will be slandered.'
EXEC add_BibleVerse @BibleId, 361002003, N'And in their greed they will exploit you with deceptive words. Their condemnation pronounced long ago is not sitting idly by; their destruction is not asleep.'
EXEC add_BibleVerse @BibleId, 361002004, N'For if God did not spare the angels who sinned, but threw them into hell and locked them up in chains in utter darkness, to be kept until the judgment,'
EXEC add_BibleVerse @BibleId, 361002005, N'and if he did not spare the ancient world, but did protect Noah, a herald of righteousness, along with seven others, when God brought a flood on an ungodly world,'
EXEC add_BibleVerse @BibleId, 361002006, N'and if he turned to ashes the cities of Sodom and Gomorrah when he condemned them to destruction, having appointed them to serve as an example to future generations of the ungodly,'
EXEC add_BibleVerse @BibleId, 361002007, N'and if he rescued Lot, a righteous man in anguish over the debauched lifestyle of lawless men,'
EXEC add_BibleVerse @BibleId, 361002008, N'(for while he lived among them day after day, that righteous man was tormented in his righteous soul by the lawless deeds he saw and heard )'
EXEC add_BibleVerse @BibleId, 361002009, N'– if so, then the Lord knows how to rescue the godly from their trials, and to reserve the unrighteous for punishment at the day of judgment,'
EXEC add_BibleVerse @BibleId, 361002010, N'especially those who indulge their fleshly desires and who despise authority. Brazen and insolent, they are not afraid to insult the glorious ones,'
EXEC add_BibleVerse @BibleId, 361002011, N'yet even angels, who are much more powerful, do not bring a slanderous judgment against them before the Lord.'
EXEC add_BibleVerse @BibleId, 361002012, N'But these men, like irrational animals – creatures of instinct, born to be caught and destroyed – do not understand whom they are insulting, and consequently in their destruction they will be destroyed,'
EXEC add_BibleVerse @BibleId, 361002013, N'suffering harm as the wages for their harmful ways. By considering it a pleasure to carouse in broad daylight, they are stains and blemishes, indulging in their deceitful pleasures when they feast together with you.'
EXEC add_BibleVerse @BibleId, 361002014, N'Their eyes, full of adultery, never stop sinning; they entice unstable people. They have trained their hearts for greed, these cursed children!'
EXEC add_BibleVerse @BibleId, 361002015, N'By forsaking the right path they have gone astray, because they followed the way of Balaam son of Bosor, who loved the wages of unrighteousness,'
EXEC add_BibleVerse @BibleId, 361002016, N'yet was rebuked for his own transgression (a dumb donkey, speaking with a human voice, restrained the prophet’s madness).'
EXEC add_BibleVerse @BibleId, 361002017, N'These men are waterless springs and mists driven by a storm, for whom the utter depths of darkness have been reserved.'
EXEC add_BibleVerse @BibleId, 361002018, N'For by speaking high-sounding but empty words they are able to entice, with fleshly desires and with debauchery, people who have just escaped from those who reside in error.'
EXEC add_BibleVerse @BibleId, 361002019, N'Although these false teachers promise such people freedom, they themselves are enslaved to immorality. For whatever a person succumbs to, to that he is enslaved.'
EXEC add_BibleVerse @BibleId, 361002020, N'For if after they have escaped the filthy things of the world through the rich knowledge of our Lord and Savior Jesus Christ, they again get entangled in them and succumb to them, their last state has become worse for them than their first.'
EXEC add_BibleVerse @BibleId, 361002021, N'For it would have been better for them never to have known the way of righteousness than, having known it, to turn back from the holy commandment that had been delivered to them.'
EXEC add_BibleVerse @BibleId, 361002022, N'They are illustrations of this true proverb: “ A dog returns to its own vomit,” and “A sow, after washing herself, wallows in the mire.”'
EXEC add_BibleVerse @BibleId, 361003001, N'Dear friends, this is already the second letter I have written you, in which I am trying to stir up your pure mind by way of reminder:'
EXEC add_BibleVerse @BibleId, 361003002, N'I want you to recall both the predictions foretold by the holy prophets and the commandment of the Lord and Savior through your apostles.'
EXEC add_BibleVerse @BibleId, 361003003, N'Above all, understand this: In the last days blatant scoffers will come, being propelled by their own evil urges'
EXEC add_BibleVerse @BibleId, 361003004, N'and saying, “Where is his promised return? For ever since our ancestors died, all things have continued as they were from the beginning of creation.”'
EXEC add_BibleVerse @BibleId, 361003005, N'For they deliberately suppress this fact, that by the word of God heavens existed long ago and an earth was formed out of water and by means of water.'
EXEC add_BibleVerse @BibleId, 361003006, N'Through these things the world existing at that time was destroyed when it was deluged with water.'
EXEC add_BibleVerse @BibleId, 361003007, N'But by the same word the present heavens and earth have been reserved for fire, by being kept for the day of judgment and destruction of the ungodly.'
EXEC add_BibleVerse @BibleId, 361003008, N'Now, dear friends, do not let this one thing escape your notice, that a single day is like a thousand years with the Lord and a thousand years are like a single day.'
EXEC add_BibleVerse @BibleId, 361003009, N'The Lord is not slow concerning his promise, as some regard slowness, but is being patient toward you, because he does not wish for any to perish but for all to come to repentance.'
EXEC add_BibleVerse @BibleId, 361003010, N'But the day of the Lord will come like a thief; when it comes, the heavens will disappear with a horrific noise, and the celestial bodies will melt away in a blaze, and the earth and every deed done on it will be laid bare.'
EXEC add_BibleVerse @BibleId, 361003011, N'Since all these things are to melt away in this manner, what sort of people must we be, conducting our lives in holiness and godliness,'
EXEC add_BibleVerse @BibleId, 361003012, N'while waiting for and hastening the coming of the day of God? Because of this day, the heavens will be burned up and dissolve, and the celestial bodies will melt away in a blaze!'
EXEC add_BibleVerse @BibleId, 361003013, N'But, according to his promise, we are waiting for new heavens and a new earth, in which righteousness truly resides.'
EXEC add_BibleVerse @BibleId, 361003014, N'Therefore, dear friends, since you are waiting for these things, strive to be found at peace, without spot or blemish, when you come into his presence.'
EXEC add_BibleVerse @BibleId, 361003015, N'And regard the patience of our Lord as salvation, just as also our dear brother Paul wrote to you, according to the wisdom given to him,'
EXEC add_BibleVerse @BibleId, 361003016, N'speaking of these things in all his letters. Some things in these letters are hard to understand, things the ignorant and unstable twist to their own destruction, as they also do to the rest of the scriptures.'
EXEC add_BibleVerse @BibleId, 361003017, N'Therefore, dear friends, since you have been forewarned, be on your guard that you do not get led astray by the error of these unprincipled men and fall from your firm grasp on the truth.'
EXEC add_BibleVerse @BibleId, 361003018, N'But grow in the grace and knowledge of our Lord and Savior Jesus Christ. To him be the honor both now and on that eternal day.'
EXEC add_BibleVerse @BibleId, 362001001, N'This is what we proclaim to you: what was from the beginning, what we have heard, what we have seen with our eyes, what we have looked at and our hands have touched (concerning the word of life –'
EXEC add_BibleVerse @BibleId, 362001002, N'and the life was revealed, and we have seen and testify and announce to you the eternal life that was with the Father and was revealed to us).'
EXEC add_BibleVerse @BibleId, 362001003, N'What we have seen and heard we announce to you too, so that you may have fellowship with us (and indeed our fellowship is with the Father and with his Son Jesus Christ).'
EXEC add_BibleVerse @BibleId, 362001004, N'Thus we are writing these things so that our joy may be complete.'
EXEC add_BibleVerse @BibleId, 362001005, N'Now this is the gospel message we have heard from him and announce to you: God is light, and in him there is no darkness at all.'
EXEC add_BibleVerse @BibleId, 362001006, N'If we say we have fellowship with him and yet keep on walking in the darkness, we are lying and not practicing the truth.'
EXEC add_BibleVerse @BibleId, 362001007, N'But if we walk in the light as he himself is in the light, we have fellowship with one another and the blood of Jesus his Son cleanses us from all sin.'
EXEC add_BibleVerse @BibleId, 362001008, N'If we say we do not bear the guilt of sin, we are deceiving ourselves and the truth is not in us.'
EXEC add_BibleVerse @BibleId, 362001009, N'But if we confess our sins, he is faithful and righteous, forgiving us our sins and cleansing us from all unrighteousness.'
EXEC add_BibleVerse @BibleId, 362001010, N'If we say we have not sinned, we make him a liar and his word is not in us.'
EXEC add_BibleVerse @BibleId, 362002001, N'(My little children, I am writing these things to you so that you may not sin. ) But if anyone does sin, we have an advocate with the Father, Jesus Christ the righteous One,'
EXEC add_BibleVerse @BibleId, 362002002, N'and he himself is the atoning sacrifice for our sins, and not only for our sins but also for the whole world.'
EXEC add_BibleVerse @BibleId, 362002003, N'Now by this we know that we have come to know God: if we keep his commandments.'
EXEC add_BibleVerse @BibleId, 362002004, N'The one who says “I have come to know God” and yet does not keep his commandments is a liar, and the truth is not in such a person.'
EXEC add_BibleVerse @BibleId, 362002005, N'But whoever obeys his word, truly in this person the love of God has been perfected. By this we know that we are in him.'
EXEC add_BibleVerse @BibleId, 362002006, N'The one who says he resides in God ought himself to walk just as Jesus walked.'
EXEC add_BibleVerse @BibleId, 362002007, N'Dear friends, I am not writing a new commandment to you, but an old commandment which you have had from the beginning. The old commandment is the word that you have already heard.'
EXEC add_BibleVerse @BibleId, 362002008, N'On the other hand, I am writing a new commandment to you which is true in him and in you, because the darkness is passing away and the true light is already shining.'
EXEC add_BibleVerse @BibleId, 362002009, N'The one who says he is in the light but still hates his fellow Christian is still in the darkness.'
EXEC add_BibleVerse @BibleId, 362002010, N'The one who loves his fellow Christian resides in the light, and there is no cause for stumbling in him.'
EXEC add_BibleVerse @BibleId, 362002011, N'But the one who hates his fellow Christian is in the darkness, walks in the darkness, and does not know where he is going, because the darkness has blinded his eyes.'
EXEC add_BibleVerse @BibleId, 362002012, N'I am writing to you, little children, that your sins have been forgiven because of his name.'
EXEC add_BibleVerse @BibleId, 362002013, N'I am writing to you, fathers, that you have known him who has been from the beginning. I am writing to you, young people, that you have conquered the evil one.'
EXEC add_BibleVerse @BibleId, 362002014, N'I have written to you, children, that you have known the Father. I have written to you, fathers, that you have known him who has been from the beginning. I have written to you, young people, that you are strong, and the word of God resides in you, and you have conquered the evil one.'
EXEC add_BibleVerse @BibleId, 362002015, N'Do not love the world or the things in the world. If anyone loves the world, the love of the Father is not in him,'
EXEC add_BibleVerse @BibleId, 362002016, N'because all that is in the world (the desire of the flesh and the desire of the eyes and the arrogance produced by material possessions) is not from the Father, but is from the world.'
EXEC add_BibleVerse @BibleId, 362002017, N'And the world is passing away with all its desires, but the person who does the will of God remains forever.'
EXEC add_BibleVerse @BibleId, 362002018, N'Children, it is the last hour, and just as you heard that the antichrist is coming, so now many antichrists have appeared. We know from this that it is the last hour.'
EXEC add_BibleVerse @BibleId, 362002019, N'They went out from us, but they did not really belong to us, because if they had belonged to us, they would have remained with us. But they went out from us to demonstrate that all of them do not belong to us.'
EXEC add_BibleVerse @BibleId, 362002020, N'Nevertheless you have an anointing from the Holy One, and you all know.'
EXEC add_BibleVerse @BibleId, 362002021, N'I have not written to you that you do not know the truth, but that you do know it, and that no lie is of the truth.'
EXEC add_BibleVerse @BibleId, 362002022, N'Who is the liar but the person who denies that Jesus is the Christ ? This one is the antichrist: the person who denies the Father and the Son.'
EXEC add_BibleVerse @BibleId, 362002023, N'Everyone who denies the Son does not have the Father either. The person who confesses the Son has the Father also.'
EXEC add_BibleVerse @BibleId, 362002024, N'As for you, what you have heard from the beginning must remain in you. If what you heard from the beginning remains in you, you also will remain in the Son and in the Father.'
EXEC add_BibleVerse @BibleId, 362002025, N'Now this is the promise that he himself made to us: eternal life.'
EXEC add_BibleVerse @BibleId, 362002026, N'These things I have written to you about those who are trying to deceive you.'
EXEC add_BibleVerse @BibleId, 362002027, N'Now as for you, the anointing that you received from him resides in you, and you have no need for anyone to teach you. But as his anointing teaches you about all things, it is true and is not a lie. Just as it has taught you, you reside in him.'
EXEC add_BibleVerse @BibleId, 362002028, N'And now, little children, remain in him, so that when he appears we may have confidence and not shrink away from him in shame when he comes back.'
EXEC add_BibleVerse @BibleId, 362002029, N'If you know that he is righteous, you also know that everyone who practices righteousness has been fathered by him.'
EXEC add_BibleVerse @BibleId, 362003001, N'(See what sort of love the Father has given to us: that we should be called God’s children – and indeed we are! For this reason the world does not know us: because it did not know him.'
EXEC add_BibleVerse @BibleId, 362003002, N'Dear friends, we are God’s children now, and what we will be has not yet been revealed. We know that whenever it is revealed we will be like him, because we will see him just as he is.'
EXEC add_BibleVerse @BibleId, 362003003, N'And everyone who has this hope focused on him purifies himself, just as Jesus is pure).'
EXEC add_BibleVerse @BibleId, 362003004, N'Everyone who practices sin also practices lawlessness; indeed, sin is lawlessness.'
EXEC add_BibleVerse @BibleId, 362003005, N'And you know that Jesus was revealed to take away sins, and in him there is no sin.'
EXEC add_BibleVerse @BibleId, 362003006, N'Everyone who resides in him does not sin; everyone who sins has neither seen him nor known him.'
EXEC add_BibleVerse @BibleId, 362003007, N'Little children, let no one deceive you: The one who practices righteousness is righteous, just as Jesus is righteous.'
EXEC add_BibleVerse @BibleId, 362003008, N'The one who practices sin is of the devil, because the devil has been sinning from the beginning. For this purpose the Son of God was revealed: to destroy the works of the devil.'
EXEC add_BibleVerse @BibleId, 362003009, N'Everyone who has been fathered by God does not practice sin, because God’s seed resides in him, and thus he is not able to sin, because he has been fathered by God.'
EXEC add_BibleVerse @BibleId, 362003010, N'By this the children of God and the children of the devil are revealed: Everyone who does not practice righteousness – the one who does not love his fellow Christian – is not of God.'
EXEC add_BibleVerse @BibleId, 362003011, N'For this is the gospel message that you have heard from the beginning: that we should love one another,'
EXEC add_BibleVerse @BibleId, 362003012, N'not like Cain who was of the evil one and brutally murdered his brother. And why did he murder him? Because his deeds were evil, but his brother’s were righteous.'
EXEC add_BibleVerse @BibleId, 362003013, N'Therefore do not be surprised, brothers and sisters, if the world hates you.'
EXEC add_BibleVerse @BibleId, 362003014, N'We know that we have crossed over from death to life because we love our fellow Christians. The one who does not love remains in death.'
EXEC add_BibleVerse @BibleId, 362003015, N'Everyone who hates his fellow Christian is a murderer, and you know that no murderer has eternal life residing in him.'
EXEC add_BibleVerse @BibleId, 362003016, N'We have come to know love by this: that Jesus laid down his life for us; thus we ought to lay down our lives for our fellow Christians.'
EXEC add_BibleVerse @BibleId, 362003017, N'But whoever has the world’s possessions and sees his fellow Christian in need and shuts off his compassion against him, how can the love of God reside in such a person?'
EXEC add_BibleVerse @BibleId, 362003018, N'Little children, let us not love with word or with tongue but in deed and truth.'
EXEC add_BibleVerse @BibleId, 362003019, N'And by this we will know that we are of the truth and will convince our conscience in his presence,'
EXEC add_BibleVerse @BibleId, 362003020, N'that if our conscience condemns us, that God is greater than our conscience and knows all things.'
EXEC add_BibleVerse @BibleId, 362003021, N'Dear friends, if our conscience does not condemn us, we have confidence in the presence of God,'
EXEC add_BibleVerse @BibleId, 362003022, N'and whatever we ask we receive from him, because we keep his commandments and do the things that are pleasing to him.'
EXEC add_BibleVerse @BibleId, 362003023, N'Now this is his commandment: that we believe in the name of his Son Jesus Christ and love one another, just as he gave us the commandment.'
EXEC add_BibleVerse @BibleId, 362003024, N'And the person who keeps his commandments resides in God, and God in him. Now by this we know that God resides in us: by the Spirit he has given us.'
EXEC add_BibleVerse @BibleId, 362004001, N'Dear friends, do not believe every spirit, but test the spirits to determine if they are from God, because many false prophets have gone out into the world.'
EXEC add_BibleVerse @BibleId, 362004002, N'By this you know the Spirit of God: Every spirit that confesses Jesus as the Christ who has come in the flesh is from God,'
EXEC add_BibleVerse @BibleId, 362004003, N'but every spirit that does not confess Jesus is not from God, and this is the spirit of the antichrist, which you have heard is coming, and now is already in the world.'
EXEC add_BibleVerse @BibleId, 362004004, N'You are from God, little children, and have conquered them, because the one who is in you is greater than the one who is in the world.'
EXEC add_BibleVerse @BibleId, 362004005, N'They are from the world; therefore they speak from the world’s perspective and the world listens to them.'
EXEC add_BibleVerse @BibleId, 362004006, N'We are from God; the person who knows God listens to us, but whoever is not from God does not listen to us. By this we know the Spirit of truth and the spirit of deceit.'
EXEC add_BibleVerse @BibleId, 362004007, N'Dear friends, let us love one another, because love is from God, and everyone who loves has been fathered by God and knows God.'
EXEC add_BibleVerse @BibleId, 362004008, N'The person who does not love does not know God, because God is love.'
EXEC add_BibleVerse @BibleId, 362004009, N'By this the love of God is revealed in us: that God has sent his one and only Son into the world so that we may live through him.'
EXEC add_BibleVerse @BibleId, 362004010, N'In this is love: not that we have loved God, but that he loved us and sent his Son to be the atoning sacrifice for our sins.'
EXEC add_BibleVerse @BibleId, 362004011, N'Dear friends, if God so loved us, then we also ought to love one another.'
EXEC add_BibleVerse @BibleId, 362004012, N'No one has seen God at any time. If we love one another, God resides in us, and his love is perfected in us.'
EXEC add_BibleVerse @BibleId, 362004013, N'By this we know that we reside in God and he in us: in that he has given us of his Spirit.'
EXEC add_BibleVerse @BibleId, 362004014, N'And we have seen and testify that the Father has sent the Son to be the Savior of the world.'
EXEC add_BibleVerse @BibleId, 362004015, N'If anyone confesses that Jesus is the Son of God, God resides in him and he in God.'
EXEC add_BibleVerse @BibleId, 362004016, N'And we have come to know and to believe the love that God has in us. God is love, and the one who resides in love resides in God, and God resides in him.'
EXEC add_BibleVerse @BibleId, 362004017, N'By this love is perfected with us, so that we may have confidence in the day of judgment, because just as Jesus is, so also are we in this world.'
EXEC add_BibleVerse @BibleId, 362004018, N'There is no fear in love, but perfect love drives out fear, because fear has to do with punishment. The one who fears punishment has not been perfected in love.'
EXEC add_BibleVerse @BibleId, 362004019, N'We love because he loved us first.'
EXEC add_BibleVerse @BibleId, 362004020, N'If anyone says “I love God” and yet hates his fellow Christian, he is a liar, because the one who does not love his fellow Christian whom he has seen cannot love God whom he has not seen.'
EXEC add_BibleVerse @BibleId, 362004021, N'And the commandment we have from him is this: that the one who loves God should love his fellow Christian too.'
EXEC add_BibleVerse @BibleId, 362005001, N'Everyone who believes that Jesus is the Christ has been fathered by God, and everyone who loves the father loves the child fathered by him.'
EXEC add_BibleVerse @BibleId, 362005002, N'By this we know that we love the children of God: whenever we love God and obey his commandments.'
EXEC add_BibleVerse @BibleId, 362005003, N'For this is the love of God: that we keep his commandments. And his commandments do not weigh us down,'
EXEC add_BibleVerse @BibleId, 362005004, N'because everyone who has been fathered by God conquers the world. This is the conquering power that has conquered the world: our faith.'
EXEC add_BibleVerse @BibleId, 362005005, N'Now who is the person who has conquered the world except the one who believes that Jesus is the Son of God?'
EXEC add_BibleVerse @BibleId, 362005006, N'Jesus Christ is the one who came by water and blood – not by the water only, but by the water and the blood. And the Spirit is the one who testifies, because the Spirit is the truth.'
EXEC add_BibleVerse @BibleId, 362005007, N'For there are three that testify,'
EXEC add_BibleVerse @BibleId, 362005008, N'the Spirit and the water and the blood, and these three are in agreement.'
EXEC add_BibleVerse @BibleId, 362005009, N'If we accept the testimony of men, the testimony of God is greater, because this is the testimony of God that he has testified concerning his Son.'
EXEC add_BibleVerse @BibleId, 362005010, N'(The one who believes in the Son of God has the testimony in himself; the one who does not believe God has made him a liar, because he has not believed in the testimony that God has testified concerning his Son.)'
EXEC add_BibleVerse @BibleId, 362005011, N'And this is the testimony: God has given us eternal life, and this life is in his Son.'
EXEC add_BibleVerse @BibleId, 362005012, N'The one who has the Son has this eternal life; the one who does not have the Son of God does not have this eternal life.'
EXEC add_BibleVerse @BibleId, 362005013, N'I have written these things to you who believe in the name of the Son of God so that you may know that you have eternal life.'
EXEC add_BibleVerse @BibleId, 362005014, N'And this is the confidence that we have before him: that whenever we ask anything according to his will, he hears us.'
EXEC add_BibleVerse @BibleId, 362005015, N'And if we know that he hears us in regard to whatever we ask, then we know that we have the requests that we have asked from him.'
EXEC add_BibleVerse @BibleId, 362005016, N'If anyone sees his fellow Christian committing a sin not resulting in death, he should ask, and God will grant life to the person who commits a sin not resulting in death. There is a sin resulting in death. I do not say that he should ask about that.'
EXEC add_BibleVerse @BibleId, 362005017, N'All unrighteousness is sin, but there is sin not resulting in death.'
EXEC add_BibleVerse @BibleId, 362005018, N'We know that everyone fathered by God does not sin, but God protects the one he has fathered, and the evil one cannot touch him.'
EXEC add_BibleVerse @BibleId, 362005019, N'We know that we are from God, and the whole world lies in the power of the evil one.'
EXEC add_BibleVerse @BibleId, 362005020, N'And we know that the Son of God has come and has given us insight to know him who is true, and we are in him who is true, in his Son Jesus Christ. This one is the true God and eternal life.'
EXEC add_BibleVerse @BibleId, 362005021, N'Little children, guard yourselves from idols.'
EXEC add_BibleVerse @BibleId, 363001001, N'From the elder, to an elect lady and her children, whom I love in truth (and not I alone, but also all those who know the truth),'
EXEC add_BibleVerse @BibleId, 363001002, N'because of the truth that resides in us and will be with us forever.'
EXEC add_BibleVerse @BibleId, 363001003, N'Grace, mercy, and peace will be with us from God the Father and from Jesus Christ the Son of the Father, in truth and love.'
EXEC add_BibleVerse @BibleId, 363001004, N'I rejoiced greatly because I have found some of your children living according to the truth, just as the Father commanded us.'
EXEC add_BibleVerse @BibleId, 363001005, N'But now I ask you, lady (not as if I were writing a new commandment to you, but the one we have had from the beginning), that we love one another.'
EXEC add_BibleVerse @BibleId, 363001006, N'(Now this is love: that we walk according to his commandments.) This is the commandment, just as you have heard from the beginning; thus you should walk in it.'
EXEC add_BibleVerse @BibleId, 363001007, N'For many deceivers have gone out into the world, people who do not confess Jesus as Christ coming in the flesh. This person is the deceiver and the antichrist!'
EXEC add_BibleVerse @BibleId, 363001008, N'Watch out, so that you do not lose the things we have worked for, but receive a full reward.'
EXEC add_BibleVerse @BibleId, 363001009, N'Everyone who goes on ahead and does not remain in the teaching of Christ does not have God. The one who remains in this teaching has both the Father and the Son.'
EXEC add_BibleVerse @BibleId, 363001010, N'If anyone comes to you and does not bring this teaching, do not receive him into your house and do not give him any greeting,'
EXEC add_BibleVerse @BibleId, 363001011, N'because the person who gives him a greeting shares in his evil deeds.'
EXEC add_BibleVerse @BibleId, 363001012, N'Though I have many other things to write to you, I do not want to do so with paper and ink, but I hope to come visit you and speak face to face, so that our joy may be complete.'
EXEC add_BibleVerse @BibleId, 363001013, N'The children of your elect sister greet you.'
EXEC add_BibleVerse @BibleId, 364001001, N'From the elder, to Gaius my dear brother, whom I love in truth.'
EXEC add_BibleVerse @BibleId, 364001002, N'Dear friend, I pray that all may go well with you and that you may be in good health, just as it is well with your soul.'
EXEC add_BibleVerse @BibleId, 364001003, N'For I rejoiced greatly when the brothers came and testified to your truth, just as you are living according to the truth.'
EXEC add_BibleVerse @BibleId, 364001004, N'I have no greater joy than this: to hear that my children are living according to the truth.'
EXEC add_BibleVerse @BibleId, 364001005, N'Dear friend, you demonstrate faithfulness by whatever you do for the brothers (even though they are strangers).'
EXEC add_BibleVerse @BibleId, 364001006, N'They have testified to your love before the church. You will do well to send them on their way in a manner worthy of God.'
EXEC add_BibleVerse @BibleId, 364001007, N'For they have gone forth on behalf of “The Name,” accepting nothing from the pagans.'
EXEC add_BibleVerse @BibleId, 364001008, N'Therefore we ought to support such people, so that we become coworkers in cooperation with the truth.'
EXEC add_BibleVerse @BibleId, 364001009, N'I wrote something to the church, but Diotrephes, who loves to be first among them, does not acknowledge us.'
EXEC add_BibleVerse @BibleId, 364001010, N'Therefore, if I come, I will call attention to the deeds he is doing – the bringing of unjustified charges against us with evil words! And not being content with that, he not only refuses to welcome the brothers himself, but hinders the people who want to do so and throws them out of the church!'
EXEC add_BibleVerse @BibleId, 364001011, N'Dear friend, do not imitate what is bad but what is good. The one who does good is of God; the one who does what is bad has not seen God.'
EXEC add_BibleVerse @BibleId, 364001012, N'Demetrius has been testified to by all, even by the truth itself. We also testify to him, and you know that our testimony is true.'
EXEC add_BibleVerse @BibleId, 364001013, N'I have many things to write to you, but I do not wish to write to you with pen and ink.'
EXEC add_BibleVerse @BibleId, 364001014, N'But I hope to see you right away, and we will speak face to face. Peace be with you. The friends here greet you. Greet the friends there by name.'
EXEC add_BibleVerse @BibleId, 365001001, N'From Jude, a slave of Jesus Christ and brother of James, to those who are called, wrapped in the love of God the Father and kept for Jesus Christ.'
EXEC add_BibleVerse @BibleId, 365001002, N'May mercy, peace, and love be lavished on you!'
EXEC add_BibleVerse @BibleId, 365001003, N'Dear friends, although I have been eager to write to you about our common salvation, I now feel compelled instead to write to encourage you to contend earnestly for the faith that was once for all entrusted to the saints.'
EXEC add_BibleVerse @BibleId, 365001004, N'For certain men have secretly slipped in among you – men who long ago were marked out for the condemnation I am about to describe – ungodly men who have turned the grace of our God into a license for evil and who deny our only Master and Lord, Jesus Christ.'
EXEC add_BibleVerse @BibleId, 365001005, N'Now I desire to remind you (even though you have been fully informed of these facts once for all ) that Jesus, having saved the people out of the land of Egypt, later destroyed those who did not believe.'
EXEC add_BibleVerse @BibleId, 365001006, N'You also know that the angels who did not keep within their proper domain but abandoned their own place of residence, he has kept in eternal chains in utter darkness, locked up for the judgment of the great Day.'
EXEC add_BibleVerse @BibleId, 365001007, N'So also Sodom and Gomorrah and the neighboring towns, since they indulged in sexual immorality and pursued unnatural desire in a way similar to these angels, are now displayed as an example by suffering the punishment of eternal fire.'
EXEC add_BibleVerse @BibleId, 365001008, N'Yet these men, as a result of their dreams, defile the flesh, reject authority, and insult the glorious ones.'
EXEC add_BibleVerse @BibleId, 365001009, N'But even when Michael the archangel was arguing with the devil and debating with him concerning Moses’ body, he did not dare to bring a slanderous judgment, but said, “May the Lord rebuke you!”'
EXEC add_BibleVerse @BibleId, 365001010, N'But these men do not understand the things they slander, and they are being destroyed by the very things that, like irrational animals, they instinctively comprehend.'
EXEC add_BibleVerse @BibleId, 365001011, N'Woe to them! For they have traveled down Cain’s path, and because of greed have abandoned themselves to Balaam’s error; hence, they will certainly perish in Korah’s rebellion.'
EXEC add_BibleVerse @BibleId, 365001012, N'These men are dangerous reefs at your love feasts, feasting without reverence, feeding only themselves. They are waterless clouds, carried along by the winds; autumn trees without fruit – twice dead, uprooted;'
EXEC add_BibleVerse @BibleId, 365001013, N'wild sea waves, spewing out the foam of their shame; wayward stars for whom the utter depths of eternal darkness have been reserved.'
EXEC add_BibleVerse @BibleId, 365001014, N'Now Enoch, the seventh in descent beginning with Adam, even prophesied of them, saying, “Look! The Lord is coming with thousands and thousands of his holy ones,'
EXEC add_BibleVerse @BibleId, 365001015, N'to execute judgment on all, and to convict every person of all their thoroughly ungodly deeds that they have committed, and of all the harsh words that ungodly sinners have spoken against him.”'
EXEC add_BibleVerse @BibleId, 365001016, N'These people are grumblers and fault-finders who go wherever their desires lead them, and they give bombastic speeches, enchanting folks for their own gain.'
EXEC add_BibleVerse @BibleId, 365001017, N'But you, dear friends – recall the predictions foretold by the apostles of our Lord Jesus Christ.'
EXEC add_BibleVerse @BibleId, 365001018, N'For they said to you, “In the end time there will come scoffers, propelled by their own ungodly desires.”'
EXEC add_BibleVerse @BibleId, 365001019, N'These people are divisive, worldly, devoid of the Spirit.'
EXEC add_BibleVerse @BibleId, 365001020, N'But you, dear friends, by building yourselves up in your most holy faith, by praying in the Holy Spirit,'
EXEC add_BibleVerse @BibleId, 365001021, N'maintain yourselves in the love of God, while anticipating the mercy of our Lord Jesus Christ that brings eternal life.'
EXEC add_BibleVerse @BibleId, 365001022, N'And have mercy on those who waver;'
EXEC add_BibleVerse @BibleId, 365001023, N'save others by snatching them out of the fire; have mercy on others, coupled with a fear of God, hating even the clothes stained by the flesh.'
EXEC add_BibleVerse @BibleId, 365001024, N'Now to the one who is able to keep you from falling, and to cause you to stand, rejoicing, without blemish before his glorious presence,'
EXEC add_BibleVerse @BibleId, 365001025, N'to the only God our Savior through Jesus Christ our Lord, be glory, majesty, power, and authority, before all time, and now, and for all eternity. Amen.'
EXEC add_BibleVerse @BibleId, 366001001, N'The revelation of Jesus Christ, which God gave him to show his servants what must happen very soon. He made it clear by sending his angel to his servant John,'
EXEC add_BibleVerse @BibleId, 366001002, N'who then testified to everything that he saw concerning the word of God and the testimony about Jesus Christ.'
EXEC add_BibleVerse @BibleId, 366001003, N'Blessed is the one who reads the words of this prophecy aloud, and blessed are those who hear and obey the things written in it, because the time is near!'
EXEC add_BibleVerse @BibleId, 366001004, N'From John, to the seven churches that are in the province of Asia: Grace and peace to you from “he who is,” and who was, and who is still to come, and from the seven spirits who are before his throne,'
EXEC add_BibleVerse @BibleId, 366001005, N'and from Jesus Christ – the faithful witness, the firstborn from among the dead, the ruler over the kings of the earth. To the one who loves us and has set us free from our sins at the cost of his own blood'
EXEC add_BibleVerse @BibleId, 366001006, N'and has appointed us as a kingdom, as priests serving his God and Father – to him be the glory and the power for ever and ever! Amen.'
EXEC add_BibleVerse @BibleId, 366001007, N'(Look! He is returning with the clouds, and every eye will see him, even those who pierced him, and all the tribes on the earth will mourn because of him. This will certainly come to pass! Amen.)'
EXEC add_BibleVerse @BibleId, 366001008, N'“I am the Alpha and the Omega,” says the Lord God – the one who is, and who was, and who is still to come – the All-Powerful!'
EXEC add_BibleVerse @BibleId, 366001009, N'I, John, your brother and the one who shares with you in the persecution, kingdom, and endurance that are in Jesus, was on the island called Patmos because of the word of God and the testimony about Jesus.'
EXEC add_BibleVerse @BibleId, 366001010, N'I was in the Spirit on the Lord’s Day when I heard behind me a loud voice like a trumpet,'
EXEC add_BibleVerse @BibleId, 366001011, N'saying: “Write in a book what you see and send it to the seven churches – to Ephesus, Smyrna, Pergamum, Thyatira, Sardis, Philadelphia, and Laodicea.”'
EXEC add_BibleVerse @BibleId, 366001012, N'I turned to see whose voice was speaking to me, and when I did so, I saw seven golden lampstands,'
EXEC add_BibleVerse @BibleId, 366001013, N'and in the midst of the lampstands was one like a son of man. He was dressed in a robe extending down to his feet and he wore a wide golden belt around his chest.'
EXEC add_BibleVerse @BibleId, 366001014, N'His head and hair were as white as wool, even as white as snow, and his eyes were like a fiery flame.'
EXEC add_BibleVerse @BibleId, 366001015, N'His feet were like polished bronze refined in a furnace, and his voice was like the roar of many waters.'
EXEC add_BibleVerse @BibleId, 366001016, N'He held seven stars in his right hand, and a sharp double-edged sword extended out of his mouth. His face shone like the sun shining at full strength.'
EXEC add_BibleVerse @BibleId, 366001017, N'When I saw him I fell down at his feet as though I were dead, but he placed his right hand on me and said: “Do not be afraid! I am the first and the last,'
EXEC add_BibleVerse @BibleId, 366001018, N'and the one who lives! I was dead, but look, now I am alive – forever and ever – and I hold the keys of death and of Hades!'
EXEC add_BibleVerse @BibleId, 366001019, N'Therefore write what you saw, what is, and what will be after these things.'
EXEC add_BibleVerse @BibleId, 366001020, N'The mystery of the seven stars that you saw in my right hand and the seven golden lampstands is this: The seven stars are the angels of the seven churches and the seven lampstands are the seven churches.'
EXEC add_BibleVerse @BibleId, 366002001, N'“To the angel of the church in Ephesus, write the following: “This is the solemn pronouncement of the one who has a firm grasp on the seven stars in his right hand – the one who walks among the seven golden lampstands:'
EXEC add_BibleVerse @BibleId, 366002002, N'‘I know your works as well as your labor and steadfast endurance, and that you cannot tolerate evil. You have even put to the test those who refer to themselves as apostles (but are not), and have discovered that they are false.'
EXEC add_BibleVerse @BibleId, 366002003, N'I am also aware that you have persisted steadfastly, endured much for the sake of my name, and have not grown weary.'
EXEC add_BibleVerse @BibleId, 366002004, N'But I have this against you: You have departed from your first love!'
EXEC add_BibleVerse @BibleId, 366002005, N'Therefore, remember from what high state you have fallen and repent! Do the deeds you did at the first; if not, I will come to you and remove your lampstand from its place – that is, if you do not repent.'
EXEC add_BibleVerse @BibleId, 366002006, N'But you do have this going for you: You hate what the Nicolaitans practice – practices I also hate.'
EXEC add_BibleVerse @BibleId, 366002007, N'The one who has an ear had better hear what the Spirit says to the churches. To the one who conquers, I will permit him to eat from the tree of life that is in the paradise of God.’'
EXEC add_BibleVerse @BibleId, 366002008, N'“To the angel of the church in Smyrna write the following: “This is the solemn pronouncement of the one who is the first and the last, the one who was dead, but came to life:'
EXEC add_BibleVerse @BibleId, 366002009, N'‘I know the distress you are suffering and your poverty (but you are rich). I also know the slander against you by those who call themselves Jews and really are not, but are a synagogue of Satan.'
EXEC add_BibleVerse @BibleId, 366002010, N'Do not be afraid of the things you are about to suffer. The devil is about to have some of you thrown into prison so you may be tested, and you will experience suffering for ten days. Remain faithful even to the point of death, and I will give you the crown that is life itself.'
EXEC add_BibleVerse @BibleId, 366002011, N'The one who has an ear had better hear what the Spirit says to the churches. The one who conquers will in no way be harmed by the second death.’'
EXEC add_BibleVerse @BibleId, 366002012, N'“To the angel of the church in Pergamum write the following: “This is the solemn pronouncement of the one who has the sharp double-edged sword:'
EXEC add_BibleVerse @BibleId, 366002013, N'‘I know where you live – where Satan’s throne is. Yet you continue to cling to my name and you have not denied your faith in me, even in the days of Antipas, my faithful witness, who was killed in your city where Satan lives.'
EXEC add_BibleVerse @BibleId, 366002014, N'But I have a few things against you: You have some people there who follow the teaching of Balaam, who instructed Balak to put a stumbling block before the people of Israel so they would eat food sacrificed to idols and commit sexual immorality.'
EXEC add_BibleVerse @BibleId, 366002015, N'In the same way, there are also some among you who follow the teaching of the Nicolaitans.'
EXEC add_BibleVerse @BibleId, 366002016, N'Therefore, repent! If not, I will come against you quickly and make war against those people with the sword of my mouth.'
EXEC add_BibleVerse @BibleId, 366002017, N'The one who has an ear had better hear what the Spirit says to the churches. To the one who conquers, I will give him some of the hidden manna, and I will give him a white stone, and on that stone will be written a new name that no one can understand except the one who receives it.’'
EXEC add_BibleVerse @BibleId, 366002018, N'“To the angel of the church in Thyatira writethe following: “ This is the solemn pronouncement of the Son of God, the one who has eyes like a fiery flame and whose feet are like polished bronze:'
EXEC add_BibleVerse @BibleId, 366002019, N'‘I know your deeds: your love, faith, service, and steadfast endurance. In fact, your more recent deeds are greater than your earlier ones.'
EXEC add_BibleVerse @BibleId, 366002020, N'But I have this against you: You tolerate that woman Jezebel, who calls herself a prophetess, and by her teaching deceives my servants to commit sexual immorality and to eat food sacrificed to idols.'
EXEC add_BibleVerse @BibleId, 366002021, N'I have given her time to repent, but she is not willing to repent of her sexual immorality.'
EXEC add_BibleVerse @BibleId, 366002022, N'Look! I am throwing her onto a bed of violent illness, and those who commit adultery with her into terrible suffering, unless they repent of her deeds.'
EXEC add_BibleVerse @BibleId, 366002023, N'Furthermore, I will strike her followers with a deadly disease, and then all the churches will know that I am the one who searches minds and hearts. I will repay each one of you what your deeds deserve.'
EXEC add_BibleVerse @BibleId, 366002024, N'But to the rest of you in Thyatira, all who do not hold to this teaching (who have not learned the so-called “deep secrets of Satan”), to you I say: I do not put any additional burden on you.'
EXEC add_BibleVerse @BibleId, 366002025, N'However, hold on to what you have until I come.'
EXEC add_BibleVerse @BibleId, 366002026, N'And to the one who conquers and who continues in my deeds until the end, I will give him authority over the nations –'
EXEC add_BibleVerse @BibleId, 366002027, N'he will rule them with an iron rod* and like clay jars he will break them to pieces,'
EXEC add_BibleVerse @BibleId, 366002028, N'just as I have received the right to rule from my Father – and I will give him the morning star.'
EXEC add_BibleVerse @BibleId, 366002029, N'The one who has an ear had better hear what the Spirit says to the churches.’'
EXEC add_BibleVerse @BibleId, 366003001, N'“To the angel of the church in Sardis write the following: “This is the solemn pronouncement of the one who holds the seven spirits of God and the seven stars: ‘I know your deeds, that you have a reputation that you are alive, but in reality you are dead.'
EXEC add_BibleVerse @BibleId, 366003002, N'Wake up then, and strengthen what remains that was about to die, because I have not found your deeds complete in the sight of my God.'
EXEC add_BibleVerse @BibleId, 366003003, N'Therefore, remember what you received and heard, and obey it, and repent. If you do not wake up, I will come like a thief, and you will never know at what hour I will come against you.'
EXEC add_BibleVerse @BibleId, 366003004, N'But you have a few individuals in Sardis who have not stained their clothes, and they will walk with me dressed in white, because they are worthy.'
EXEC add_BibleVerse @BibleId, 366003005, N'The one who conquers will be dressed like them in white clothing, and I will never erase his name from the book of life, but will declare his name before my Father and before his angels.'
EXEC add_BibleVerse @BibleId, 366003006, N'The one who has an ear had better hear what the Spirit says to the churches.’'
EXEC add_BibleVerse @BibleId, 366003007, N'“To the angel of the church in Philadelphia write the following: “This is the solemn pronouncement of the Holy One, the True One, who holds the key of David, who opens doors no one can shut, and shuts doors no one can open:'
EXEC add_BibleVerse @BibleId, 366003008, N'‘I know your deeds. (Look! I have put in front of you an open door that no one can shut.) I know that you have little strength, but you have obeyed my word and have not denied my name.'
EXEC add_BibleVerse @BibleId, 366003009, N'Listen! I am going to make those people from the synagogue of Satan – who say they are Jews yet are not, but are lying – Look, I will make them come and bow down at your feet and acknowledge that I have loved you.'
EXEC add_BibleVerse @BibleId, 366003010, N'Because you have kept my admonition to endure steadfastly, I will also keep you from the hour of testing that is about to come on the whole world to test those who live on the earth.'
EXEC add_BibleVerse @BibleId, 366003011, N'I am coming soon. Hold on to what you have so that no one can take away your crown.'
EXEC add_BibleVerse @BibleId, 366003012, N'The one who conquers I will make a pillar in the temple of my God, and he will never depart from it. I will write on him the name of my God and the name of the city of my God (the new Jerusalem that comes down out of heaven from my God), and my new name as well.'
EXEC add_BibleVerse @BibleId, 366003013, N'The one who has an ear had better hear what the Spirit says to the churches.’'
EXEC add_BibleVerse @BibleId, 366003014, N'“To the angel of the church in Laodicea write the following: “This is the solemn pronouncement of the Amen, the faithful and true witness, the originator of God’s creation:'
EXEC add_BibleVerse @BibleId, 366003015, N'‘I know your deeds, that you are neither cold nor hot. I wish you were either cold or hot!'
EXEC add_BibleVerse @BibleId, 366003016, N'So because you are lukewarm, and neither hot nor cold, I am going to vomit you out of my mouth!'
EXEC add_BibleVerse @BibleId, 366003017, N'Because you say, “I am rich and have acquired great wealth, and need nothing,” but do not realize that you are wretched, pitiful, poor, blind, and naked,'
EXEC add_BibleVerse @BibleId, 366003018, N'take my advice and buy gold from me refined by fire so you can become rich! Buy from me white clothing so you can be clothed and your shameful nakedness will not be exposed, and buy eye salve to put on your eyes so you can see!'
EXEC add_BibleVerse @BibleId, 366003019, N'All those I love, I rebuke and discipline. So be earnest and repent!'
EXEC add_BibleVerse @BibleId, 366003020, N'Listen! I am standing at the door and knocking! If anyone hears my voice and opens the door I will come into his home and share a meal with him, and he with me.'
EXEC add_BibleVerse @BibleId, 366003021, N'I will grant the one who conquers permission to sit with me on my throne, just as I too conquered and sat down with my Father on his throne.'
EXEC add_BibleVerse @BibleId, 366003022, N'The one who has an ear had better hear what the Spirit says to the churches.’”'
EXEC add_BibleVerse @BibleId, 366004001, N'After these things I looked, and there was a door standing open in heaven! And the first voice I had heard speaking to me like a trumpet said: “Come up here so that I can show you what must happen after these things.”'
EXEC add_BibleVerse @BibleId, 366004002, N'Immediately I was in the Spirit, and a throne was standing in heaven with someone seated on it!'
EXEC add_BibleVerse @BibleId, 366004003, N'And the one seated on it was like jasper and carnelian in appearance, and a rainbow looking like it was made of emerald encircled the throne.'
EXEC add_BibleVerse @BibleId, 366004004, N'In a circle around the throne were twenty-four other thrones, and seated on those thrones were twenty-four elders. They were dressed in white clothing and had golden crowns on their heads.'
EXEC add_BibleVerse @BibleId, 366004005, N'From the throne came out flashes of lightning and roaring and crashes of thunder. Seven flaming torches, which are the seven spirits of God, were burning in front of the throne'
EXEC add_BibleVerse @BibleId, 366004006, N'and in front of the throne was something like a sea of glass, like crystal. In the middle of the throne and around the throne were four living creatures full of eyes in front and in back.'
EXEC add_BibleVerse @BibleId, 366004007, N'The first living creature was like a lion, the second creature like an ox, the third creature had a face like a man’s, and the fourth creature looked like an eagle flying.'
EXEC add_BibleVerse @BibleId, 366004008, N'Each one of the four living creatures had six wings and was full of eyes all around and inside. They never rest day or night, saying: “ Holy Holy Holy is the Lord God, the All-Powerful, Who was and who is, and who is still to come!”'
EXEC add_BibleVerse @BibleId, 366004009, N'And whenever the living creatures give glory, honor, and thanks to the one who sits on the throne, who lives forever and ever,'
EXEC add_BibleVerse @BibleId, 366004010, N'the twenty-four elders throw themselves to the ground before the one who sits on the throne and worship the one who lives forever and ever, and they offer their crowns before his throne, saying:'
EXEC add_BibleVerse @BibleId, 366004011, N'“You are worthy, our Lord and God, to receive glory and honor and power, since you created all things, and because of your will they existed and were created!”'
EXEC add_BibleVerse @BibleId, 366005001, N'Then I saw in the right hand of the one who was seated on the throne a scroll written on the front and back and sealed with seven seals.'
EXEC add_BibleVerse @BibleId, 366005002, N'And I saw a powerful angel proclaiming in a loud voice: “Who is worthy to open the scroll and to break its seals?”'
EXEC add_BibleVerse @BibleId, 366005003, N'But no one in heaven or on earth or under the earth was able to open the scroll or look into it.'
EXEC add_BibleVerse @BibleId, 366005004, N'So I began weeping bitterly because no one was found who was worthy to open the scroll or to look into it.'
EXEC add_BibleVerse @BibleId, 366005005, N'Then one of the elders said to me, “Stop weeping! Look, the Lion of the tribe of Judah, the root of David, has conquered; thus he can open the scroll and its seven seals.”'
EXEC add_BibleVerse @BibleId, 366005006, N'Then I saw standing in the middle of the throne and of the four living creatures, and in the middle of the elders, a Lamb that appeared to have been killed. He had seven horns and seven eyes, which are the seven spirits of God sent out into all the earth.'
EXEC add_BibleVerse @BibleId, 366005007, N'Then he came and took the scroll from the right hand of the one who was seated on the throne,'
EXEC add_BibleVerse @BibleId, 366005008, N'and when he had taken the scroll, the four living creatures and the twenty-four elders threw themselves to the ground before the Lamb. Each of them had a harp and golden bowls full of incense (which are the prayers of the saints).'
EXEC add_BibleVerse @BibleId, 366005009, N'They were singing a new song: “You are worthy to take the scroll and to open its seals because you were killed, and at the cost of your own blood you have purchased for God persons from every tribe, language, people, and nation.'
EXEC add_BibleVerse @BibleId, 366005010, N'You have appointed them as a kingdom and priests to serve our God, and they will reign on the earth.”'
EXEC add_BibleVerse @BibleId, 366005011, N'Then I looked and heard the voice of many angels in a circle around the throne, as well as the living creatures and the elders. Their number was ten thousand times ten thousand – thousands times thousands –'
EXEC add_BibleVerse @BibleId, 366005012, N'all of whom were singing in a loud voice: “Worthy is the lamb who was killed to receive power and wealth and wisdom and might and honor and glory and praise!”'
EXEC add_BibleVerse @BibleId, 366005013, N'Then I heard every creature – in heaven, on earth, under the earth, in the sea, and all that is in them – singing: “To the one seated on the throne and to the Lamb be praise, honor, glory, and ruling power forever and ever!”'
EXEC add_BibleVerse @BibleId, 366005014, N'And the four living creatures were saying “Amen,” and the elders threw themselves to the ground and worshiped.'
EXEC add_BibleVerse @BibleId, 366006001, N'I looked on when the Lamb opened one of the seven seals, and I heard one of the four living creatures saying with a thunderous voice, “Come!”'
EXEC add_BibleVerse @BibleId, 366006002, N'So I looked, and here came a white horse! The one who rode it had a bow, and he was given a crown, and as a conqueror he rode out to conquer.'
EXEC add_BibleVerse @BibleId, 366006003, N'Then when the Lamb opened the second seal, I heard the second living creature saying, “Come!”'
EXEC add_BibleVerse @BibleId, 366006004, N'And another horse, fiery red, came out, and the one who rode it was granted permission to take peace from the earth, so that people would butcher one another, and he was given a huge sword.'
EXEC add_BibleVerse @BibleId, 366006005, N'Then when the Lamb opened the third seal I heard the third living creature saying, “Come!” So I looked, and here came a black horse! The one who rode it had a balance scale in his hand.'
EXEC add_BibleVerse @BibleId, 366006006, N'Then I heard something like a voice from among the four living creatures saying, “A quart of wheat will cost a day’s pay and three quarts of barley will cost a day’s pay. But do not damage the olive oil and the wine!”'
EXEC add_BibleVerse @BibleId, 366006007, N'Then when the Lamb opened the fourth seal I heard the voice of the fourth living creature saying, “Come!”'
EXEC add_BibleVerse @BibleId, 366006008, N'So I looked and here came a pale green horse! The name of the one who rode it was Death, and Hades followed right behind. They were given authority over a fourth of the earth, to kill its population with the sword, famine, and disease, and by the wild animals of the earth.'
EXEC add_BibleVerse @BibleId, 366006009, N'Now when the Lamb opened the fifth seal, I saw under the altar the souls of those who had been violently killed because of the word of God and because of the testimony they had given.'
EXEC add_BibleVerse @BibleId, 366006010, N'They cried out with a loud voice, “How long, Sovereign Master, holy and true, before you judge those who live on the earth and avenge our blood?”'
EXEC add_BibleVerse @BibleId, 366006011, N'Each of them was given a long white robe and they were told to rest for a little longer, until the full number was reached of both their fellow servants and their brothers who were going to be killed just as they had been.'
EXEC add_BibleVerse @BibleId, 366006012, N'Then I looked when the Lamb opened the sixth seal, and a huge earthquake took place; the sun became as black as sackcloth made of hair, and the full moon became blood red;'
EXEC add_BibleVerse @BibleId, 366006013, N'and the stars in the sky fell to the earth like a fig tree dropping its unripe figs when shaken by a fierce wind.'
EXEC add_BibleVerse @BibleId, 366006014, N'The sky was split apart like a scroll being rolled up, and every mountain and island was moved from its place.'
EXEC add_BibleVerse @BibleId, 366006015, N'Then the kings of the earth, the very important people, the generals, the rich, the powerful, and everyone, slave and free, hid themselves in the caves and among the rocks of the mountains.'
EXEC add_BibleVerse @BibleId, 366006016, N'They said to the mountains and to the rocks, “Fall on us and hide us from the face of the one who is seated on the throne and from the wrath of the Lamb,'
EXEC add_BibleVerse @BibleId, 366006017, N'because the great day of their wrath has come, and who is able to withstand it?”'
EXEC add_BibleVerse @BibleId, 366007001, N'After this I saw four angels standing at the four corners of the earth, holding back the four winds of the earth so no wind could blow on the earth, on the sea, or on any tree.'
EXEC add_BibleVerse @BibleId, 366007002, N'Then I saw another angel ascending from the east, who had the seal of the living God. He shouted out with a loud voice to the four angels who had been given permission to damage the earth and the sea:'
EXEC add_BibleVerse @BibleId, 366007003, N'“Do not damage the earth or the sea or the trees until we have put a seal on the foreheads of the servants of our God.”'
EXEC add_BibleVerse @BibleId, 366007004, N'Now I heard the number of those who were marked with the seal, one hundred and forty-four thousand, sealed from all the tribes of the people of Israel:'
EXEC add_BibleVerse @BibleId, 366007005, N'From the tribe of Judah, twelve thousand were sealed, from the tribe of Reuben, twelve thousand, from the tribe of Gad, twelve thousand,'
EXEC add_BibleVerse @BibleId, 366007006, N'from the tribe of Asher, twelve thousand, from the tribe of Naphtali, twelve thousand, from the tribe of Manasseh, twelve thousand,'
EXEC add_BibleVerse @BibleId, 366007007, N'from the tribe of Simeon, twelve thousand, from the tribe of Levi, twelve thousand, from the tribe of Issachar, twelve thousand,'
EXEC add_BibleVerse @BibleId, 366007008, N'from the tribe of Zebulun, twelve thousand, from the tribe of Joseph, twelve thousand, from the tribe of Benjamin, twelve thousand were sealed.'
EXEC add_BibleVerse @BibleId, 366007009, N'After these things I looked, and here was an enormous crowd that no one could count, made up of persons from every nation, tribe, people, and language, standing before the throne and before the Lamb dressed in long white robes, and with palm branches in their hands.'
EXEC add_BibleVerse @BibleId, 366007010, N'They were shouting out in a loud voice, “Salvation belongs to our God, to the one seated on the throne, and to the Lamb!”'
EXEC add_BibleVerse @BibleId, 366007011, N'And all the angels stood there in a circle around the throne and around the elders and the four living creatures, and they threw themselves down with their faces to the ground before the throne and worshiped God,'
EXEC add_BibleVerse @BibleId, 366007012, N'saying, “Amen! Praise and glory, and wisdom and thanksgiving, and honor and power and strength be to our God for ever and ever. Amen!”'
EXEC add_BibleVerse @BibleId, 366007013, N'Then one of the elders asked me, “These dressed in long white robes – who are they and where have they come from?”'
EXEC add_BibleVerse @BibleId, 366007014, N'So I said to him, “My lord, you know the answer.” Then he said to me, “These are the ones who have come out of the great tribulation. They have washed their robes and made them white in the blood of the Lamb!'
EXEC add_BibleVerse @BibleId, 366007015, N'For this reason they are before the throne of God, and they serve him day and night in his temple, and the one seated on the throne will shelter them.'
EXEC add_BibleVerse @BibleId, 366007016, N'They will never go hungry or be thirsty again, and the sun will not beat down on them, nor any burning heat,'
EXEC add_BibleVerse @BibleId, 366007017, N'because the Lamb in the middle of the throne will shepherd them and lead them to springs of living water, and God will wipe away every tear from their eyes.”'
EXEC add_BibleVerse @BibleId, 366008001, N'Now when the Lamb opened the seventh seal there was silence in heaven for about half an hour.'
EXEC add_BibleVerse @BibleId, 366008002, N'Then I saw the seven angels who stand before God, and seven trumpets were given to them.'
EXEC add_BibleVerse @BibleId, 366008003, N'Another angel holding a golden censer came and was stationed at the altar. A large amount of incense was given to him to offer up, with the prayers of all the saints, on the golden altar that is before the throne.'
EXEC add_BibleVerse @BibleId, 366008004, N'The smoke coming from the incense, along with the prayers of the saints, ascended before God from the angel’s hand.'
EXEC add_BibleVerse @BibleId, 366008005, N'Then the angel took the censer, filled it with fire from the altar, and threw it on the earth, and there were crashes of thunder, roaring, flashes of lightning, and an earthquake.'
EXEC add_BibleVerse @BibleId, 366008006, N'Now the seven angels holding the seven trumpets prepared to blow them.'
EXEC add_BibleVerse @BibleId, 366008007, N'The first angel blew his trumpet, and there was hail and fire mixed with blood, and it was thrown at the earth so that a third of the earth was burned up, a third of the trees were burned up, and all the green grass was burned up.'
EXEC add_BibleVerse @BibleId, 366008008, N'Then the second angel blew his trumpet, and something like a great mountain of burning fire was thrown into the sea. A third of the sea became blood,'
EXEC add_BibleVerse @BibleId, 366008009, N'and a third of the creatures living in the sea died, and a third of the ships were completely destroyed.'
EXEC add_BibleVerse @BibleId, 366008010, N'Then the third angel blew his trumpet, and a huge star burning like a torch fell from the sky; it landed on a third of the rivers and on the springs of water.'
EXEC add_BibleVerse @BibleId, 366008011, N'(Now the name of the star is Wormwood.) So a third of the waters became wormwood, and many people died from these waters because they were poisoned.'
EXEC add_BibleVerse @BibleId, 366008012, N'Then the fourth angel blew his trumpet, and a third of the sun was struck, and a third of the moon, and a third of the stars, so that a third of them were darkened. And there was no light for a third of the day and for a third of the night likewise.'
EXEC add_BibleVerse @BibleId, 366008013, N'Then I looked, and I heard an eagle flying directly overhead, proclaiming with a loud voice, “Woe! Woe! Woe to those who live on the earth because of the remaining sounds of the trumpets of the three angels who are about to blow them!”'
EXEC add_BibleVerse @BibleId, 366009001, N'Then the fifth angel blew his trumpet, and I saw a star that had fallen from the sky to the earth, and he was given the key to the shaft of the abyss.'
EXEC add_BibleVerse @BibleId, 366009002, N'He opened the shaft of the abyss and smoke rose out of it like smoke from a giant furnace. The sun and the air were darkened with smoke from the shaft.'
EXEC add_BibleVerse @BibleId, 366009003, N'Then out of the smoke came locusts onto the earth, and they were given power like that of the scorpions of the earth.'
EXEC add_BibleVerse @BibleId, 366009004, N'They were told not to damage the grass of the earth, or any green plant or tree, but only those people who did not have the seal of God on their forehead.'
EXEC add_BibleVerse @BibleId, 366009005, N'The locusts were not given permission to kill them, but only to torture them for five months, and their torture was like that of a scorpion when it stings a person.'
EXEC add_BibleVerse @BibleId, 366009006, N'In those days people will seek death, but will not be able to find it; they will long to die, but death will flee from them.'
EXEC add_BibleVerse @BibleId, 366009007, N'Now the locusts looked like horses equipped for battle. On their heads were something like crowns similar to gold, and their faces looked like men’s faces.'
EXEC add_BibleVerse @BibleId, 366009008, N'They had hair like women’s hair, and their teeth were like lions’ teeth.'
EXEC add_BibleVerse @BibleId, 366009009, N'They had breastplates like iron breastplates, and the sound of their wings was like the noise of many horse-drawn chariots charging into battle.'
EXEC add_BibleVerse @BibleId, 366009010, N'They have tails and stingers like scorpions, and their ability to injure people for five months is in their tails.'
EXEC add_BibleVerse @BibleId, 366009011, N'They have as king over them the angel of the abyss, whose name in Hebrew is Abaddon, and in Greek, Apollyon.'
EXEC add_BibleVerse @BibleId, 366009012, N'The first woe has passed, but two woes are still coming after these things!'
EXEC add_BibleVerse @BibleId, 366009013, N'Then the sixth angel blew his trumpet, and I heard a single voice coming from the horns on the golden altar that is before God,'
EXEC add_BibleVerse @BibleId, 366009014, N'saying to the sixth angel, the one holding the trumpet, “Set free the four angels who are bound at the great river Euphrates!”'
EXEC add_BibleVerse @BibleId, 366009015, N'Then the four angels who had been prepared for this hour, day, month, and year were set free to kill a third of humanity.'
EXEC add_BibleVerse @BibleId, 366009016, N'The number of soldiers on horseback was two hundred million; I heard their number.'
EXEC add_BibleVerse @BibleId, 366009017, N'Now this is what the horses and their riders looked like in my vision: The riders had breastplates that were fiery red, dark blue, and sulfurous yellow in color. The heads of the horses looked like lions’ heads, and fire, smoke, and sulfur came out of their mouths.'
EXEC add_BibleVerse @BibleId, 366009018, N'A third of humanity was killed by these three plagues, that is, by the fire, the smoke, and the sulfur that came out of their mouths.'
EXEC add_BibleVerse @BibleId, 366009019, N'For the power of the horses resides in their mouths and in their tails, because their tails are like snakes, having heads that inflict injuries.'
EXEC add_BibleVerse @BibleId, 366009020, N'The rest of humanity, who had not been killed by these plagues, did not repent of the works of their hands, so that they did not stop worshiping demons and idols made of gold, silver, bronze, stone, and wood – idols that cannot see or hear or walk about.'
EXEC add_BibleVerse @BibleId, 366009021, N'Furthermore, they did not repent of their murders, of their magic spells, of their sexual immorality, or of their stealing.'
EXEC add_BibleVerse @BibleId, 366010001, N'Then I saw another powerful angel descending from heaven, wrapped in a cloud, with a rainbow above his head; his face was like the sun and his legs were like pillars of fire.'
EXEC add_BibleVerse @BibleId, 366010002, N'He held in his hand a little scroll that was open, and he put his right foot on the sea and his left on the land.'
EXEC add_BibleVerse @BibleId, 366010003, N'Then he shouted in a loud voice like a lion roaring, and when he shouted, the seven thunders sounded their voices.'
EXEC add_BibleVerse @BibleId, 366010004, N'When the seven thunders spoke, I was preparing to write, but just then I heard a voice from heaven say, “Seal up what the seven thunders spoke and do not write it down.”'
EXEC add_BibleVerse @BibleId, 366010005, N'Then the angel I saw standing on the sea and on the land raised his right hand to heaven'
EXEC add_BibleVerse @BibleId, 366010006, N'and swore by the one who lives forever and ever, who created heaven and what is in it, and the earth and what is in it, and the sea and what is in it, “There will be no more delay!'
EXEC add_BibleVerse @BibleId, 366010007, N'But in the days when the seventh angel is about to blow his trumpet, the mystery of God is completed, just as he has proclaimed to his servants the prophets.”'
EXEC add_BibleVerse @BibleId, 366010008, N'Then the voice I had heard from heaven began to speak to me again, “Go and take the open scroll in the hand of the angel who is standing on the sea and on the land.”'
EXEC add_BibleVerse @BibleId, 366010009, N'So I went to the angel and asked him to give me the little scroll. He said to me, “Take the scroll and eat it. It will make your stomach bitter, but it will be as sweet as honey in your mouth.”'
EXEC add_BibleVerse @BibleId, 366010010, N'So I took the little scroll from the angel’s hand and ate it, and it did taste as sweet as honey in my mouth, but when I had eaten it, my stomach became bitter.'
EXEC add_BibleVerse @BibleId, 366010011, N'Then they told me: “You must prophesy again about many peoples, nations, languages, and kings.”'
EXEC add_BibleVerse @BibleId, 366011001, N'Then a measuring rod like a staff was given to me, and I was told, “Get up and measure the temple of God, and the altar, and the ones who worship there.'
EXEC add_BibleVerse @BibleId, 366011002, N'But do not measure the outer courtyard of the temple; leave it out, because it has been given to the Gentiles, and they will trample on the holy city for forty-two months.'
EXEC add_BibleVerse @BibleId, 366011003, N'And I will grant my two witnesses authority to prophesy for 1,260 days, dressed in sackcloth.'
EXEC add_BibleVerse @BibleId, 366011004, N'(These are the two olive trees and the two lampstands that stand before the Lord of the earth.)'
EXEC add_BibleVerse @BibleId, 366011005, N'If anyone wants to harm them, fire comes out of their mouths and completely consumes their enemies. If anyone wants to harm them, they must be killed this way.'
EXEC add_BibleVerse @BibleId, 366011006, N'These two have the power to close up the sky so that it does not rain during the time they are prophesying. They have power to turn the waters to blood and to strike the earth with every kind of plague whenever they want.'
EXEC add_BibleVerse @BibleId, 366011007, N'When they have completed their testimony, the beast that comes up from the abyss will make war on them and conquer them and kill them.'
EXEC add_BibleVerse @BibleId, 366011008, N'Their corpses will lie in the street of the great city that is symbolically called Sodom and Egypt, where their Lord was also crucified.'
EXEC add_BibleVerse @BibleId, 366011009, N'For three and a half days those from every people, tribe, nation, and language will look at their corpses, because they will not permit them to be placed in a tomb.'
EXEC add_BibleVerse @BibleId, 366011010, N'And those who live on the earth will rejoice over them and celebrate, even sending gifts to each other, because these two prophets had tormented those who live on the earth.'
EXEC add_BibleVerse @BibleId, 366011011, N'But after three and a half days a breath of life from God entered them, and they stood on their feet, and tremendous fear seized those who were watching them.'
EXEC add_BibleVerse @BibleId, 366011012, N'Then they heard a loud voice from heaven saying to them: “Come up here!” So the two prophets went up to heaven in a cloud while their enemies stared at them.'
EXEC add_BibleVerse @BibleId, 366011013, N'Just then a major earthquake took place and a tenth of the city collapsed; seven thousand people were killed in the earthquake, and the rest were terrified and gave glory to the God of heaven.'
EXEC add_BibleVerse @BibleId, 366011014, N'The second woe has come and gone; the third is coming quickly.'
EXEC add_BibleVerse @BibleId, 366011015, N'Then the seventh angel blew his trumpet, and there were loud voices in heaven saying: “The kingdom of the world has become the kingdom of our Lord and of his Christ, and he will reign for ever and ever.”'
EXEC add_BibleVerse @BibleId, 366011016, N'Then the twenty-four elders who are seated on their thrones before God threw themselves down with their faces to the ground and worshiped God'
EXEC add_BibleVerse @BibleId, 366011017, N'with these words: “We give you thanks, Lord God, the All-Powerful, the one who is and who was, because you have taken your great power and begun to reign.'
EXEC add_BibleVerse @BibleId, 366011018, N'The nations were enraged, but your wrath has come, and the time has come for the dead to be judged, and the time has come to give to your servants, the prophets, their reward, as well as to the saints and to those who revere your name, both small and great, and the time has come to destroy those who destroy the earth.”'
EXEC add_BibleVerse @BibleId, 366011019, N'Then the temple of God in heaven was opened and the ark of his covenant was visible within his temple. And there were flashes of lightning, roaring, crashes of thunder, an earthquake, and a great hailstorm.'
EXEC add_BibleVerse @BibleId, 366012001, N'Then a great sign appeared in heaven: a woman clothed with the sun, and with the moon under her feet, and on her head was a crown of twelve stars.'
EXEC add_BibleVerse @BibleId, 366012002, N'She was pregnant and was screaming in labor pains, struggling to give birth.'
EXEC add_BibleVerse @BibleId, 366012003, N'Then another sign appeared in heaven: a huge red dragon that had seven heads and ten horns, and on its heads were seven diadem crowns.'
EXEC add_BibleVerse @BibleId, 366012004, N'Now the dragon’s tail swept away a third of the stars in heaven and hurled them to the earth. Then the dragon stood before the woman who was about to give birth, so that he might devour her child as soon as it was born.'
EXEC add_BibleVerse @BibleId, 366012005, N'So the woman gave birth to a son, a male child, who is going to rule over all the nations with an iron rod. Her child was suddenly caught up to God and to his throne,'
EXEC add_BibleVerse @BibleId, 366012006, N'and she fled into the wilderness where a place had been prepared for her by God, so she could be taken care of for 1,260 days.'
EXEC add_BibleVerse @BibleId, 366012007, N'Then war broke out in heaven: Michael and his angels fought against the dragon, and the dragon and his angels fought back.'
EXEC add_BibleVerse @BibleId, 366012008, N'But the dragon was not strong enough to prevail, so there was no longer any place left in heaven for him and his angels.'
EXEC add_BibleVerse @BibleId, 366012009, N'So that huge dragon – the ancient serpent, the one called the devil and Satan, who deceives the whole world – was thrown down to the earth, and his angels along with him.'
EXEC add_BibleVerse @BibleId, 366012010, N'Then I heard a loud voice in heaven saying, “The salvation and the power and the kingdom of our God, and the ruling authority of his Christ, have now come, because the accuser of our brothers and sisters, the one who accuses them day and night before our God, has been thrown down.'
EXEC add_BibleVerse @BibleId, 366012011, N'But they overcame him by the blood of the Lamb and by the word of their testimony, and they did not love their lives so much that they were afraid to die.'
EXEC add_BibleVerse @BibleId, 366012012, N'Therefore you heavens rejoice, and all who reside in them! But woe to the earth and the sea because the devil has come down to you! He is filled with terrible anger, for he knows that he only has a little time!”'
EXEC add_BibleVerse @BibleId, 366012013, N'Now when the dragon realized that he had been thrown down to the earth, he pursued the woman who had given birth to the male child.'
EXEC add_BibleVerse @BibleId, 366012014, N'But the woman was given the two wings of a giant eagle so that she could fly out into the wilderness, to the place God prepared for her, where she is taken care of – away from the presence of the serpent – for a time, times, and half a time.'
EXEC add_BibleVerse @BibleId, 366012015, N'Then the serpent spouted water like a river out of his mouth after the woman in an attempt to sweep her away by a flood,'
EXEC add_BibleVerse @BibleId, 366012016, N'but the earth came to her rescue; the ground opened up and swallowed the river that the dragon had spewed from his mouth.'
EXEC add_BibleVerse @BibleId, 366012017, N'So the dragon became enraged at the woman and went away to make war on the rest of her children, those who keep God’s commandments and hold to the testimony about Jesus. And the dragon stood on the sand of the seashore.'
EXEC add_BibleVerse @BibleId, 366013001, N'Then I saw a beast coming up out of the sea. It had ten horns and seven heads, and on its horns were ten diadem crowns, and on its heads a blasphemous name.'
EXEC add_BibleVerse @BibleId, 366013002, N'Now the beast that I saw was like a leopard, but its feet were like a bear’s, and its mouth was like a lion’s mouth. The dragon gave the beast his power, his throne, and great authority to rule.'
EXEC add_BibleVerse @BibleId, 366013003, N'One of the beast’s heads appeared to have been killed, but the lethal wound had been healed. And the whole world followed the beast in amazement;'
EXEC add_BibleVerse @BibleId, 366013004, N'they worshiped the dragon because he had given ruling authority to the beast, and they worshiped the beast too, saying: “Who is like the beast?” and “Who is able to make war against him?”'
EXEC add_BibleVerse @BibleId, 366013005, N'The beast was given a mouth speaking proud words and blasphemies, and he was permitted to exercise ruling authority for forty-two months.'
EXEC add_BibleVerse @BibleId, 366013006, N'So the beast opened his mouth to blaspheme against God – to blaspheme both his name and his dwelling place, that is, those who dwell in heaven.'
EXEC add_BibleVerse @BibleId, 366013007, N'The beast was permitted to go to war against the saints and conquer them. He was given ruling authority over every tribe, people, language, and nation,'
EXEC add_BibleVerse @BibleId, 366013008, N'and all those who live on the earth will worship the beast, everyone whose name has not been written since the foundation of the world in the book of life belonging to the Lamb who was killed.'
EXEC add_BibleVerse @BibleId, 366013009, N'If anyone has an ear, he had better listen!'
EXEC add_BibleVerse @BibleId, 366013010, N'If anyone is meant for captivity, into captivity he will go. If anyone is to be killed by the sword, then by the sword he must be killed. This requires steadfast endurance and faith from the saints.'
EXEC add_BibleVerse @BibleId, 366013011, N'Then I saw another beast coming up from the earth. He had two horns like a lamb, but was speaking like a dragon.'
EXEC add_BibleVerse @BibleId, 366013012, N'He exercised all the ruling authority of the first beast on his behalf, and made the earth and those who inhabit it worship the first beast, the one whose lethal wound had been healed.'
EXEC add_BibleVerse @BibleId, 366013013, N'He performed momentous signs, even making fire come down from heaven in front of people'
EXEC add_BibleVerse @BibleId, 366013014, N'and, by the signs he was permitted to perform on behalf of the beast, he deceived those who live on the earth. He told those who live on the earth to make an image to the beast who had been wounded by the sword, but still lived.'
EXEC add_BibleVerse @BibleId, 366013015, N'The second beast was empowered to give life to the image of the first beast so that it could speak, and could cause all those who did not worship the image of the beast to be killed.'
EXEC add_BibleVerse @BibleId, 366013016, N'He also caused everyone (small and great, rich and poor, free and slave ) to obtain a mark on their right hand or on their forehead.'
EXEC add_BibleVerse @BibleId, 366013017, N'Thus no one was allowed to buy or sell things unless he bore the mark of the beast – that is, his name or his number.'
EXEC add_BibleVerse @BibleId, 366013018, N'This calls for wisdom: Let the one who has insight calculate the beast’s number, for it is man’s number, and his number is 666.'
EXEC add_BibleVerse @BibleId, 366014001, N'Then I looked, and here was the Lamb standing on Mount Zion, and with him were one hundred and forty-four thousand, who had his name and his Father’s name written on their foreheads.'
EXEC add_BibleVerse @BibleId, 366014002, N'I also heard a sound coming out of heaven like the sound of many waters and like the sound of loud thunder. Now the sound I heard was like that made by harpists playing their harps,'
EXEC add_BibleVerse @BibleId, 366014003, N'and they were singing a new song before the throne and before the four living creatures and the elders. No one was able to learn the song except the one hundred and forty-four thousand who had been redeemed from the earth.'
EXEC add_BibleVerse @BibleId, 366014004, N'These are the ones who have not defiled themselves with women, for they are virgins. These are the ones who follow the Lamb wherever he goes. These were redeemed from humanity as firstfruits to God and to the Lamb,'
EXEC add_BibleVerse @BibleId, 366014005, N'and no lie was found on their lips; they are blameless.'
EXEC add_BibleVerse @BibleId, 366014006, N'Then I saw another angel flying directly overhead, and he had an eternal gospel to proclaim to those who live on the earth – to every nation, tribe, language, and people.'
EXEC add_BibleVerse @BibleId, 366014007, N'He declared in a loud voice: “Fear God and give him glory, because the hour of his judgment has arrived, and worship the one who made heaven and earth, the sea and the springs of water!”'
EXEC add_BibleVerse @BibleId, 366014008, N'A second angel followed the first, declaring: “Fallen, fallen is Babylon the great city! She made all the nations drink of the wine of her immoral passion.”'
EXEC add_BibleVerse @BibleId, 366014009, N'A third angel followed the first two, declaring in a loud voice: “If anyone worships the beast and his image, and takes the mark on his forehead or his hand,'
EXEC add_BibleVerse @BibleId, 366014010, N'that person will also drink of the wine of God’s anger that has been mixed undiluted in the cup of his wrath, and he will be tortured with fire and sulfur in front of the holy angels and in front of the Lamb.'
EXEC add_BibleVerse @BibleId, 366014011, N'And the smoke from their torture will go up forever and ever, and those who worship the beast and his image will have no rest day or night, along with anyone who receives the mark of his name.”'
EXEC add_BibleVerse @BibleId, 366014012, N'This requires the steadfast endurance of the saints – those who obey God’s commandments and hold to their faith in Jesus.'
EXEC add_BibleVerse @BibleId, 366014013, N'Then I heard a voice from heaven say, “Write this: ‘Blessed are the dead, those who die in the Lord from this moment on!’” “Yes,” says the Spirit, “so they can rest from their hard work, because their deeds will follow them.”'
EXEC add_BibleVerse @BibleId, 366014014, N'Then I looked, and a white cloud appeared, and seated on the cloud was one like a son of man! He had a golden crown on his head and a sharp sickle in his hand.'
EXEC add_BibleVerse @BibleId, 366014015, N'Then another angel came out of the temple, shouting in a loud voice to the one seated on the cloud, “Use your sickle and start to reap, because the time to reap has come, since the earth’s harvest is ripe!”'
EXEC add_BibleVerse @BibleId, 366014016, N'So the one seated on the cloud swung his sickle over the earth, and the earth was reaped.'
EXEC add_BibleVerse @BibleId, 366014017, N'Then another angel came out of the temple in heaven, and he too had a sharp sickle.'
EXEC add_BibleVerse @BibleId, 366014018, N'Another angel, who was in charge of the fire, came from the altar and called in a loud voice to the angel who had the sharp sickle, “Use your sharp sickle and gather the clusters of grapes off the vine of the earth, because its grapes are now ripe.”'
EXEC add_BibleVerse @BibleId, 366014019, N'So the angel swung his sickle over the earth and gathered the grapes from the vineyard of the earth and tossed them into the great winepress of the wrath of God.'
EXEC add_BibleVerse @BibleId, 366014020, N'Then the winepress was stomped outside the city, and blood poured out of the winepress up to the height of horses’ bridles for a distance of almost two hundred miles.'
EXEC add_BibleVerse @BibleId, 366015001, N'Then I saw another great and astounding sign in heaven: seven angels who have seven final plagues (they are final because in them God’s anger is completed).'
EXEC add_BibleVerse @BibleId, 366015002, N'Then I saw something like a sea of glass mixed with fire, and those who had conquered the beast and his image and the number of his name. They were standing by the sea of glass, holding harps given to them by God.'
EXEC add_BibleVerse @BibleId, 366015003, N'They sang the song of Moses the servant of God and the song of the Lamb: “Great and astounding are your deeds, Lord God, the All-Powerful! Just and true are your ways, King over the nations!'
EXEC add_BibleVerse @BibleId, 366015004, N'Who will not fear you, O Lord, and glorify your name, because you alone are holy? All nations will come and worship before you for your righteous acts have been revealed.”'
EXEC add_BibleVerse @BibleId, 366015005, N'After these things I looked, and the temple (the tent of the testimony) was opened in heaven,'
EXEC add_BibleVerse @BibleId, 366015006, N'and the seven angels who had the seven plagues came out of the temple, dressed in clean bright linen, wearing wide golden belts around their chests.'
EXEC add_BibleVerse @BibleId, 366015007, N'Then one of the four living creatures gave the seven angels seven golden bowls filled with the wrath of God who lives forever and ever,'
EXEC add_BibleVerse @BibleId, 366015008, N'and the temple was filled with smoke from God’s glory and from his power. Thus no one could enter the temple until the seven plagues from the seven angels were completed.'
EXEC add_BibleVerse @BibleId, 366016001, N'Then I heard a loud voice from the temple declaring to the seven angels: “Go and pour out on the earth the seven bowls containing God’s wrath.”'
EXEC add_BibleVerse @BibleId, 366016002, N'So the first angel went and poured out his bowl on the earth. Then ugly and painful sores appeared on the people who had the mark of the beast and who worshiped his image.'
EXEC add_BibleVerse @BibleId, 366016003, N'Next, the second angel poured out his bowl on the sea and it turned into blood, like that of a corpse, and every living creature that was in the sea died.'
EXEC add_BibleVerse @BibleId, 366016004, N'Then the third angel poured out his bowl on the rivers and the springs of water, and they turned into blood.'
EXEC add_BibleVerse @BibleId, 366016005, N'Now I heard the angel of the waters saying: “You are just – the one who is and who was, the Holy One – because you have passed these judgments,'
EXEC add_BibleVerse @BibleId, 366016006, N'because they poured out the blood of your saints and prophets, so you have given them blood to drink. They got what they deserved!”'
EXEC add_BibleVerse @BibleId, 366016007, N'Then I heard the altar reply, “Yes, Lord God, the All-Powerful, your judgments are true and just!”'
EXEC add_BibleVerse @BibleId, 366016008, N'Then the fourth angel poured out his bowl on the sun, and it was permitted to scorch people with fire.'
EXEC add_BibleVerse @BibleId, 366016009, N'Thus people were scorched by the terrible heat, yet they blasphemed the name of God, who has ruling authority over these plagues, and they would not repent and give him glory.'
EXEC add_BibleVerse @BibleId, 366016010, N'Then the fifth angel poured out his bowl on the throne of the beast so that darkness covered his kingdom, and people began to bite their tongues because of their pain.'
EXEC add_BibleVerse @BibleId, 366016011, N'They blasphemed the God of heaven because of their sufferings and because of their sores, but nevertheless they still refused to repent of their deeds.'
EXEC add_BibleVerse @BibleId, 366016012, N'Then the sixth angel poured out his bowl on the great river Euphrates and dried up its water to prepare the way for the kings from the east.'
EXEC add_BibleVerse @BibleId, 366016013, N'Then I saw three unclean spirits that looked like frogs coming out of the mouth of the dragon, out of the mouth of the beast, and out of the mouth of the false prophet.'
EXEC add_BibleVerse @BibleId, 366016014, N'For they are the spirits of the demons performing signs who go out to the kings of the earth to bring them together for the battle that will take place on the great day of God, the All-Powerful.'
EXEC add_BibleVerse @BibleId, 366016015, N'(Look! I will come like a thief! Blessed is the one who stays alert and does not lose his clothes so that he will not have to walk around naked and his shameful condition be seen.)'
EXEC add_BibleVerse @BibleId, 366016016, N'Now the spirits gathered the kings and their armies to the place that is called Armageddon in Hebrew.'
EXEC add_BibleVerse @BibleId, 366016017, N'Finally the seventh angel poured out his bowl into the air and a loud voice came out of the temple from the throne, saying: “It is done!”'
EXEC add_BibleVerse @BibleId, 366016018, N'Then there were flashes of lightning, roaring, and crashes of thunder, and there was a tremendous earthquake – an earthquake unequaled since humanity has been on the earth, so tremendous was that earthquake.'
EXEC add_BibleVerse @BibleId, 366016019, N'The great city was split into three parts and the cities of the nations collapsed. So Babylon the great was remembered before God, and was given the cup filled with the wine made of God’s furious wrath.'
EXEC add_BibleVerse @BibleId, 366016020, N'Every island fled away and no mountains could be found.'
EXEC add_BibleVerse @BibleId, 366016021, N'And gigantic hailstones, weighing about a hundred pounds each, fell from heaven on people, but they blasphemed God because of the plague of hail, since it was so horrendous.'
EXEC add_BibleVerse @BibleId, 366017001, N'Then one of the seven angels who had the seven bowls came and spoke to me. “Come,” he said, “I will show you the condemnation and punishment of the great prostitute who sits on many waters,'
EXEC add_BibleVerse @BibleId, 366017002, N'with whom the kings of the earth committed sexual immorality and the earth’s inhabitants got drunk with the wine of her immorality.”'
EXEC add_BibleVerse @BibleId, 366017003, N'So he carried me away in the Spirit to a wilderness, and there I saw a woman sitting on a scarlet beast that was full of blasphemous names and had seven heads and ten horns.'
EXEC add_BibleVerse @BibleId, 366017004, N'Now the woman was dressed in purple and scarlet clothing, and adorned with gold, precious stones, and pearls. She held in her hand a golden cup filled with detestable things and unclean things from her sexual immorality.'
EXEC add_BibleVerse @BibleId, 366017005, N'On her forehead was written a name, a mystery: “Babylon the Great, the Mother of prostitutes and of the detestable things of the earth.”'
EXEC add_BibleVerse @BibleId, 366017006, N'I saw that the woman was drunk with the blood of the saints and the blood of those who testified to Jesus. I was greatly astounded when I saw her.'
EXEC add_BibleVerse @BibleId, 366017007, N'But the angel said to me, “Why are you astounded? I will interpret for you the mystery of the woman and of the beast with the seven heads and ten horns that carries her.'
EXEC add_BibleVerse @BibleId, 366017008, N'The beast you saw was, and is not, but is about to come up from the abyss and then go to destruction. The inhabitants of the earth – all those whose names have not been written in the book of life since the foundation of the world – will be astounded when they see that the beast was, and is not, but is to come.'
EXEC add_BibleVerse @BibleId, 366017009, N'(This requires a mind that has wisdom.) The seven heads are seven mountains the woman sits on. They are also seven kings:'
EXEC add_BibleVerse @BibleId, 366017010, N'five have fallen; one is, and the other has not yet come, but whenever he does come, he must remain for only a brief time.'
EXEC add_BibleVerse @BibleId, 366017011, N'The beast that was, and is not, is himself an eighth king and yet is one of the seven, and is going to destruction.'
EXEC add_BibleVerse @BibleId, 366017012, N'The ten horns that you saw are ten kings who have not yet received a kingdom, but will receive ruling authority as kings with the beast for one hour.'
EXEC add_BibleVerse @BibleId, 366017013, N'These kings have a single intent, and they will give their power and authority to the beast.'
EXEC add_BibleVerse @BibleId, 366017014, N'They will make war with the Lamb, but the Lamb will conquer them, because he is Lord of lords and King of kings, and those accompanying the Lamb are the called, chosen, and faithful.”'
EXEC add_BibleVerse @BibleId, 366017015, N'Then the angel said to me, “The waters you saw (where the prostitute is seated) are peoples, multitudes, nations, and languages.'
EXEC add_BibleVerse @BibleId, 366017016, N'The ten horns that you saw, and the beast – these will hate the prostitute and make her desolate and naked. They will consume her flesh and burn her up with fire.'
EXEC add_BibleVerse @BibleId, 366017017, N'For God has put into their minds to carry out his purpose by making a decision to give their royal power to the beast until the words of God are fulfilled.'
EXEC add_BibleVerse @BibleId, 366017018, N'As for the woman you saw, she is the great city that has sovereignty over the kings of the earth.”'
EXEC add_BibleVerse @BibleId, 366018001, N'After these things I saw another angel, who possessed great authority, coming down out of heaven, and the earth was lit up by his radiance.'
EXEC add_BibleVerse @BibleId, 366018002, N'He shouted with a powerful voice: “Fallen, fallen, is Babylon the great! She has become a lair for demons, a haunt for every unclean spirit, a haunt for every unclean bird, a haunt for every unclean and detested beast.'
EXEC add_BibleVerse @BibleId, 366018003, N'For all the nations have fallen from the wine of her immoral passion, and the kings of the earth have committed sexual immorality with her, and the merchants of the earth have gotten rich from the power of her sensual behavior.”'
EXEC add_BibleVerse @BibleId, 366018004, N'Then I heard another voice from heaven saying, “Come out of her, my people, so you will not take part in her sins and so you will not receive her plagues,'
EXEC add_BibleVerse @BibleId, 366018005, N'because her sins have piled up all the way to heaven and God has remembered her crimes.'
EXEC add_BibleVerse @BibleId, 366018006, N'Repay her the same way she repaid others; pay her back double corresponding to her deeds. In the cup she mixed, mix double the amount for her.'
EXEC add_BibleVerse @BibleId, 366018007, N'As much as she exalted herself and lived in sensual luxury, to this extent give her torment and grief because she said to herself, ‘I rule as queen and am no widow; I will never experience grief!’'
EXEC add_BibleVerse @BibleId, 366018008, N'For this reason, she will experience her plagues in a single day: disease, mourning, and famine, and she will be burned down with fire, because the Lord God who judges her is powerful!”'
EXEC add_BibleVerse @BibleId, 366018009, N'Then the kings of the earth who committed immoral acts with her and lived in sensual luxury with her will weep and wail for her when they see the smoke from the fire that burns her up.'
EXEC add_BibleVerse @BibleId, 366018010, N'They will stand a long way off because they are afraid of her torment, and will say, “Woe, woe, O great city, Babylon the powerful city! For in a single hour your doom has come!”'
EXEC add_BibleVerse @BibleId, 366018011, N'Then the merchants of the earth will weep and mourn for her because no one buys their cargo any longer –'
EXEC add_BibleVerse @BibleId, 366018012, N'cargo such as gold, silver, precious stones, pearls, fine linen, purple cloth, silk, scarlet cloth, all sorts of things made of citron wood, all sorts of objects made of ivory, all sorts of things made of expensive wood, bronze, iron and marble,'
EXEC add_BibleVerse @BibleId, 366018013, N'cinnamon, spice, incense, perfumed ointment, frankincense, wine, olive oil and costly flour, wheat, cattle and sheep, horses and four-wheeled carriages, slaves and human lives.'
EXEC add_BibleVerse @BibleId, 366018014, N'(The ripe fruit you greatly desired has gone from you, and all your luxury and splendor have gone from you – they will never ever be found again!)'
EXEC add_BibleVerse @BibleId, 366018015, N'The merchants who sold these things, who got rich from her, will stand a long way off because they are afraid of her torment. They will weep and mourn,'
EXEC add_BibleVerse @BibleId, 366018016, N'saying, “Woe, woe, O great city – dressed in fine linen, purple and scarlet clothing, and adorned with gold, precious stones, and pearls –'
EXEC add_BibleVerse @BibleId, 366018017, N'because in a single hour such great wealth has been destroyed!” And every ship’s captain, and all who sail along the coast – seamen, and all who make their living from the sea, stood a long way off'
EXEC add_BibleVerse @BibleId, 366018018, N'and began to shout when they saw the smoke from the fire that burned her up, “Who is like the great city?”'
EXEC add_BibleVerse @BibleId, 366018019, N'And they threw dust on their heads and were shouting with weeping and mourning, “Woe, Woe, O great city – in which all those who had ships on the sea got rich from her wealth – because in a single hour she has been destroyed!”'
EXEC add_BibleVerse @BibleId, 366018020, N'(Rejoice over her, O heaven, and you saints and apostles and prophets, for God has pronounced judgment against her on your behalf!)'
EXEC add_BibleVerse @BibleId, 366018021, N'Then one powerful angel picked up a stone like a huge millstone, threw it into the sea, and said, “With this kind of sudden violent force Babylon the great city will be thrown down and it will never be found again!'
EXEC add_BibleVerse @BibleId, 366018022, N'And the sound of the harpists, musicians, flute players, and trumpeters will never be heard in you again. No craftsman who practices any trade will ever be found in you again; the noise of a mill will never be heard in you again.'
EXEC add_BibleVerse @BibleId, 366018023, N'Even the light from a lamp will never shine in you again! The voices of the bridegroom and his bride will never be heard in you again. For your merchants were the tycoons of the world, because all the nations were deceived by your magic spells!'
EXEC add_BibleVerse @BibleId, 366018024, N'The blood of the saints and prophets was found in her, along with the blood of all those who had been killed on the earth.”'
EXEC add_BibleVerse @BibleId, 366019001, N'After these things I heard what sounded like the loud voice of a vast throng in heaven, saying, “Hallelujah! Salvation and glory and power belong to our God,'
EXEC add_BibleVerse @BibleId, 366019002, N'because his judgments are true and just. For he has judged the great prostitute who corrupted the earth with her sexual immorality, and has avenged the blood of his servants poured out by her own hands!”'
EXEC add_BibleVerse @BibleId, 366019003, N'Then a second time the crowd shouted, “Hallelujah!” The smoke rises from her forever and ever.'
EXEC add_BibleVerse @BibleId, 366019004, N'The twenty-four elders and the four living creatures threw themselves to the ground and worshiped God, who was seated on the throne, saying: “Amen! Hallelujah!”'
EXEC add_BibleVerse @BibleId, 366019005, N'Then a voice came from the throne, saying: “Praise our God all you his servants, and all you who fear Him, both the small and the great!”'
EXEC add_BibleVerse @BibleId, 366019006, N'Then I heard what sounded like the voice of a vast throng, like the roar of many waters and like loud crashes of thunder. They were shouting: “Hallelujah! For the Lord our God, the All-Powerful, reigns!'
EXEC add_BibleVerse @BibleId, 366019007, N'Let us rejoice and exult and give him glory, because the wedding celebration of the Lamb has come, and his bride has made herself ready.'
EXEC add_BibleVerse @BibleId, 366019008, N'She was permitted to be dressed in bright, clean, fine linen” (for the fine linen is the righteous deeds of the saints).'
EXEC add_BibleVerse @BibleId, 366019009, N'Then the angel said to me, “Write the following: Blessed are those who are invited to the banquet at the wedding celebration of the Lamb!” He also said to me, “These are the true words of God.”'
EXEC add_BibleVerse @BibleId, 366019010, N'So I threw myself down at his feet to worship him, but he said, “Do not do this! I am only a fellow servant with you and your brothers who hold to the testimony about Jesus. Worship God, for the testimony about Jesus is the spirit of prophecy.”'
EXEC add_BibleVerse @BibleId, 366019011, N'Then I saw heaven opened and here came a white horse! The one riding it was called “Faithful” and “True,” and with justice he judges and goes to war.'
EXEC add_BibleVerse @BibleId, 366019012, N'His eyes are like a fiery flame and there are many diadem crowns on his head. He has a name written that no one knows except himself.'
EXEC add_BibleVerse @BibleId, 366019013, N'He is dressed in clothing dipped in blood, and he is called the Word of God.'
EXEC add_BibleVerse @BibleId, 366019014, N'The armies that are in heaven, dressed in white, clean, fine linen, were following him on white horses.'
EXEC add_BibleVerse @BibleId, 366019015, N'From his mouth extends a sharp sword, so that with it he can strike the nations. He will rule them with an iron rod, and he stomps the winepress of the furious wrath of God, the All-Powerful.'
EXEC add_BibleVerse @BibleId, 366019016, N'He has a name written on his clothing and on his thigh: “King of kings and Lord of lords.”'
EXEC add_BibleVerse @BibleId, 366019017, N'Then I saw one angel standing in the sun, and he shouted in a loud voice to all the birds flying high in the sky: “Come, gather around for the great banquet of God,'
EXEC add_BibleVerse @BibleId, 366019018, N'to eat your fill of the flesh of kings, the flesh of generals, the flesh of powerful people, the flesh of horses and those who ride them, and the flesh of all people, both free and slave, and small and great!”'
EXEC add_BibleVerse @BibleId, 366019019, N'Then I saw the beast and the kings of the earth and their armies assembled to do battle with the one who rode the horse and with his army.'
EXEC add_BibleVerse @BibleId, 366019020, N'Now the beast was seized, and along with him the false prophet who had performed the signs on his behalf – signs by which he deceived those who had received the mark of the beast and those who worshiped his image. Both of them were thrown alive into the lake of fire burning with sulfur.'
EXEC add_BibleVerse @BibleId, 366019021, N'The others were killed by the sword that extended from the mouth of the one who rode the horse, and all the birds gorged themselves with their flesh.'
EXEC add_BibleVerse @BibleId, 366020001, N'Then I saw an angel descending from heaven, holding in his hand the key to the abyss and a huge chain.'
EXEC add_BibleVerse @BibleId, 366020002, N'He seized the dragon – the ancient serpent, who is the devil and Satan – and tied him up for a thousand years.'
EXEC add_BibleVerse @BibleId, 366020003, N'The angel then threw him into the abyss and locked and sealed it so that he could not deceive the nations until the one thousand years were finished. (After these things he must be released for a brief period of time.)'
EXEC add_BibleVerse @BibleId, 366020004, N'Then I saw thrones and seated on them were those who had been given authority to judge. I also saw the souls of those who had been beheaded because of the testimony about Jesus and because of the word of God. These had not worshiped the beast or his image and had refused to receive his mark on their forehead or hand. They came to life and reigned with Christ for a thousand years.'
EXEC add_BibleVerse @BibleId, 366020005, N'(The rest of the dead did not come to life until the thousand years were finished.) This is the first resurrection.'
EXEC add_BibleVerse @BibleId, 366020006, N'Blessed and holy is the one who takes part in the first resurrection. The second death has no power over them, but they will be priests of God and of Christ, and they will reign with him for a thousand years.'
EXEC add_BibleVerse @BibleId, 366020007, N'Now when the thousand years are finished, Satan will be released from his prison'
EXEC add_BibleVerse @BibleId, 366020008, N'and will go out to deceive the nations at the four corners of the earth, Gog and Magog, to bring them together for the battle. They are as numerous as the grains of sand in the sea.'
EXEC add_BibleVerse @BibleId, 366020009, N'They went up on the broad plain of the earth and encircled the camp of the saints and the beloved city, but fire came down from heaven and devoured them completely.'
EXEC add_BibleVerse @BibleId, 366020010, N'And the devil who deceived them was thrown into the lake of fire and sulfur, where the beast and the false prophet are too, and they will be tormented there day and night forever and ever.'
EXEC add_BibleVerse @BibleId, 366020011, N'Then I saw a large white throne and the one who was seated on it; the earth and the heaven fled from his presence, and no place was found for them.'
EXEC add_BibleVerse @BibleId, 366020012, N'And I saw the dead, the great and the small, standing before the throne. Then books were opened, and another book was opened – the book of life. So the dead were judged by what was written in the books, according to their deeds.'
EXEC add_BibleVerse @BibleId, 366020013, N'The sea gave up the dead that were in it, and Death and Hades gave up the dead that were in them, and each one was judged according to his deeds.'
EXEC add_BibleVerse @BibleId, 366020014, N'Then Death and Hades were thrown into the lake of fire. This is the second death – the lake of fire.'
EXEC add_BibleVerse @BibleId, 366020015, N'If anyone’s name was not found written in the book of life, that person was thrown into the lake of fire.'
EXEC add_BibleVerse @BibleId, 366021001, N'Then I saw a new heaven and a new earth, for the first heaven and earth had ceased to exist, and the sea existed no more.'
EXEC add_BibleVerse @BibleId, 366021002, N'And I saw the holy city – the new Jerusalem – descending out of heaven from God, made ready like a bride adorned for her husband.'
EXEC add_BibleVerse @BibleId, 366021003, N'And I heard a loud voice from the throne saying: “Look! The residence of God is among human beings. He will live among them, and they will be his people, and God himself will be with them.'
EXEC add_BibleVerse @BibleId, 366021004, N'He will wipe away every tear from their eyes, and death will not exist any more – or mourning, or crying, or pain, for the former things have ceased to exist.”'
EXEC add_BibleVerse @BibleId, 366021005, N'And the one seated on the throne said: “Look! I am making all things new!” Then he said to me, “Write it down, because these words are reliable and true.”'
EXEC add_BibleVerse @BibleId, 366021006, N'He also said to me, “It is done! I am the Alpha and the Omega, the beginning and the end. To the one who is thirsty I will give water free of charge from the spring of the water of life.'
EXEC add_BibleVerse @BibleId, 366021007, N'The one who conquers will inherit these things, and I will be his God and he will be my son.'
EXEC add_BibleVerse @BibleId, 366021008, N'But to the cowards, unbelievers, detestable persons, murderers, the sexually immoral, and those who practice magic spells, idol worshipers, and all those who lie, their place will be in the lake that burns with fire and sulfur. That is the second death.”'
EXEC add_BibleVerse @BibleId, 366021009, N'Then one of the seven angels who had the seven bowls full of the seven final plagues came and spoke to me, saying, “Come, I will show you the bride, the wife of the Lamb!”'
EXEC add_BibleVerse @BibleId, 366021010, N'So he took me away in the Spirit to a huge, majestic mountain and showed me the holy city, Jerusalem, descending out of heaven from God.'
EXEC add_BibleVerse @BibleId, 366021011, N'The city possesses the glory of God; its brilliance is like a precious jewel, like a stone of crystal-clear jasper.'
EXEC add_BibleVerse @BibleId, 366021012, N'It has a massive, high wall with twelve gates, with twelve angels at the gates, and the names of the twelve tribes of the nation of Israel are written on the gates.'
EXEC add_BibleVerse @BibleId, 366021013, N'There are three gates on the east side, three gates on the north side, three gates on the south side and three gates on the west side.'
EXEC add_BibleVerse @BibleId, 366021014, N'The wall of the city has twelve foundations, and on them are the twelve names of the twelve apostles of the Lamb.'
EXEC add_BibleVerse @BibleId, 366021015, N'The angel who spoke to me had a golden measuring rod with which to measure the city and its foundation stones and wall.'
EXEC add_BibleVerse @BibleId, 366021016, N'Now the city is laid out as a square, its length and width the same. He measured the city with the measuring rod at fourteen hundred miles (its length and width and height are equal).'
EXEC add_BibleVerse @BibleId, 366021017, N'He also measured its wall, one hundred forty-four cubits according to human measurement, which is also the angel’s.'
EXEC add_BibleVerse @BibleId, 366021018, N'The city’s wall is made of jasper and the city is pure gold, like transparent glass.'
EXEC add_BibleVerse @BibleId, 366021019, N'The foundations of the city’s wall are decorated with every kind of precious stone. The first foundation is jasper, the second sapphire, the third agate, the fourth emerald,'
EXEC add_BibleVerse @BibleId, 366021020, N'the fifth onyx, the sixth carnelian, the seventh chrysolite, the eighth beryl, the ninth topaz, the tenth chrysoprase, the eleventh jacinth, and the twelfth amethyst.'
EXEC add_BibleVerse @BibleId, 366021021, N'And the twelve gates are twelve pearls – each one of the gates is made from just one pearl! The main street of the city is pure gold, like transparent glass.'
EXEC add_BibleVerse @BibleId, 366021022, N'Now I saw no temple in the city, because the Lord God – the All-Powerful – and the Lamb are its temple.'
EXEC add_BibleVerse @BibleId, 366021023, N'The city does not need the sun or the moon to shine on it, because the glory of God lights it up, and its lamp is the Lamb.'
EXEC add_BibleVerse @BibleId, 366021024, N'The nations will walk by its light and the kings of the earth will bring their grandeur into it.'
EXEC add_BibleVerse @BibleId, 366021025, N'Its gates will never be closed during the day (and there will be no night there).'
EXEC add_BibleVerse @BibleId, 366021026, N'They will bring the grandeur and the wealth of the nations into it,'
EXEC add_BibleVerse @BibleId, 366021027, N'but nothing ritually unclean will ever enter into it, nor anyone who does what is detestable or practices falsehood, but only those whose names are written in the Lamb’s book of life.'
EXEC add_BibleVerse @BibleId, 366022001, N'Then the angel showed me the river of the water of life – water as clear as crystal – pouring out from the throne of God and of the Lamb,'
EXEC add_BibleVerse @BibleId, 366022002, N'flowing down the middle of the city’s main street. On each side of the river is the tree of life producing twelve kinds of fruit, yielding its fruit every month of the year. Its leaves are for the healing of the nations.'
EXEC add_BibleVerse @BibleId, 366022003, N'And there will no longer be any curse, and the throne of God and the Lamb will be in the city. His servants will worship him,'
EXEC add_BibleVerse @BibleId, 366022004, N'and they will see his face, and his name will be on their foreheads.'
EXEC add_BibleVerse @BibleId, 366022005, N'Night will be no more, and they will not need the light of a lamp or the light of the sun, because the Lord God will shine on them, and they will reign forever and ever.'
EXEC add_BibleVerse @BibleId, 366022006, N'Then the angel said to me, “These words are reliable and true. The Lord, the God of the spirits of the prophets, has sent his angel to show his servants what must happen soon.”'
EXEC add_BibleVerse @BibleId, 366022007, N'(Look! I am coming soon! Blessed is the one who keeps the words of the prophecy expressed in this book.)'
EXEC add_BibleVerse @BibleId, 366022008, N'I, John, am the one who heard and saw these things, and when I heard and saw them, I threw myself down to worship at the feet of the angel who was showing them to me.'
EXEC add_BibleVerse @BibleId, 366022009, N'But he said to me, “Do not do this! I am a fellow servant with you and with your brothers the prophets, and with those who obey the words of this book. Worship God!”'
EXEC add_BibleVerse @BibleId, 366022010, N'Then he said to me, “Do not seal up the words of the prophecy contained in this book, because the time is near.'
EXEC add_BibleVerse @BibleId, 366022011, N'The evildoer must continue to do evil, and the one who is morally filthy must continue to be filthy. The one who is righteous must continue to act righteously, and the one who is holy must continue to be holy.”'
EXEC add_BibleVerse @BibleId, 366022012, N'(Look! I am coming soon, and my reward is with me to pay each one according to what he has done!'
EXEC add_BibleVerse @BibleId, 366022013, N'I am the Alpha and the Omega, the first and the last, the beginning and the end!)'
EXEC add_BibleVerse @BibleId, 366022014, N'Blessed are those who wash their robes so they can have access to the tree of life and can enter into the city by the gates.'
EXEC add_BibleVerse @BibleId, 366022015, N'Outside are the dogs and the sorcerers and the sexually immoral, and the murderers, and the idolaters and everyone who loves and practices falsehood!'
EXEC add_BibleVerse @BibleId, 366022016, N'“I, Jesus, have sent my angel to testify to you about these things for the churches. I am the root and the descendant of David, the bright morning star!”'
EXEC add_BibleVerse @BibleId, 366022017, N'And the Spirit and the bride say, “Come!” And let the one who hears say: “Come!” And let the one who is thirsty come; let the one who wants it take the water of life free of charge.'
EXEC add_BibleVerse @BibleId, 366022018, N'I testify to the one who hears the words of the prophecy contained in this book: If anyone adds to them, God will add to him the plagues described in this book.'
EXEC add_BibleVerse @BibleId, 366022019, N'And if anyone takes away from the words of this book of prophecy, God will take away his share in the tree of life and in the holy city that are described in this book.'
EXEC add_BibleVerse @BibleId, 366022020, N'The one who testifies to these things says, “Yes, I am coming soon!” Amen! Come, Lord Jesus!'
EXEC add_BibleVerse @BibleId, 366022021, N'The grace of the Lord Jesus be with all.'
COMMIT TRANSACTION;
